CREATE TABLE IF NOT EXISTS "public"."access_control_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "client_request_id" "uuid" NOT NULL,
    "location_event_id" "uuid",
    "site_id" "uuid",
    "zone_id" "uuid",
    "shift_id" "uuid",
    "officer_user_id" "uuid" NOT NULL,
    "observed_at" timestamp with time zone NOT NULL,
    "event_kind" "text" NOT NULL,
    "subject_kind" "text" NOT NULL,
    "officer_decision" "text" NOT NULL,
    "decision_basis" "text" NOT NULL,
    "claimed_identity" "text",
    "credential_reference" "text",
    "notes" "text",
    "gps_lat" double precision,
    "gps_lng" double precision,
    "geofence_context" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "evidence_state" "text" DEFAULT 'not_provided'::"text" NOT NULL,
    "recognition_summary" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "recognition_review_state" "text" DEFAULT 'not_requested'::"text" NOT NULL,
    "received_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    "created_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL
);
COMMENT ON TABLE "public"."access_control_events" IS 'Human-authored field record of an access encounter at a place. recognition_summary may contain ranked person/vehicle discovery candidates, but can never grant entry, confirm identity, or replace the officer decision.';
COMMENT ON COLUMN "public"."access_control_events"."officer_decision" IS 'The attributable action recorded by the officer. It is independent of and authoritative over any machine recognition candidate.';
COMMENT ON COLUMN "public"."access_control_events"."geofence_context" IS 'Exact resolve_context-style receipt supplied by the governed edge function. Unresolved states remain visible and are never converted to a successful place verification.';
COMMENT ON COLUMN "public"."access_control_events"."recognition_summary" IS 'Sanitized recognition probes and ranked possible person/vehicle matches. Embeddings are excluded; human confirmation and access authorization remain separate.';

