CREATE TABLE IF NOT EXISTS "public"."biosecurity_assessments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "dispatch_job_id" "uuid",
    "officer_user_id" "uuid",
    "location_id" "uuid",
    "species_identified" "text",
    "density_estimate" "text",
    "seed_head_present" boolean,
    "bob_species_confirmed" boolean,
    "bob_checklist" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "bob_recommendation" "text",
    "action_taken" "text",
    "land_use_context" "text",
    "scene_description" "text",
    "assessed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "officer_id" "uuid",
    "officer_name" "text",
    "site_id" "uuid",
    "species_name" "text",
