    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);

CREATE TABLE IF NOT EXISTS "public"."bob_owner_rulings" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "ruling_key" "text" NOT NULL,
    "title" "text" NOT NULL,
    "ruling_text" "text" NOT NULL,
    "domain" "text" DEFAULT 'general'::"text" NOT NULL,
    "ruling_status" "text" DEFAULT 'active'::"text" NOT NULL,
    "superseded_by" "uuid",
    "authored_by" "text" DEFAULT 'owner'::"text" NOT NULL,
