CREATE TABLE IF NOT EXISTS "public"."bob_turn_runs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "conversation_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "request_id" "uuid" NOT NULL,
    "request_fingerprint" "text" NOT NULL,
    "status" "text" DEFAULT 'running'::"text" NOT NULL,
    "response_payload" "jsonb",
    "error_code" "text",
    "started_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "heartbeat_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "completed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."bob_turn_runs" IS 'Durable, tenant-scoped Bob request ledger. A client request_id is claimed once so browser timeouts and retries can reconcile without duplicating conductor work.';
COMMENT ON COLUMN "public"."bob_turn_runs"."request_id" IS 'Client-generated UUID retained across status checks and safe replays.';
COMMENT ON COLUMN "public"."bob_turn_runs"."request_fingerprint" IS 'SHA-256 of the normalized message, attachment identities, and agent mode. A reused request_id with different input is rejected.';
COMMENT ON COLUMN "public"."bob_turn_runs"."status" IS 'queued, running, cancel_requested, completed, failed, or cancelled. Queued requests return to the caller immediately and are claimed once by background execution.';
COMMENT ON COLUMN "public"."bob_turn_runs"."response_payload" IS 'Final structured Bob response used to reconcile a timed-out browser without rerunning the turn.';

CREATE TABLE IF NOT EXISTS "public"."boundary_proposals" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
