    "homeless_notes" "text"
);
COMMENT ON TABLE "public"."canonical_people" IS 'Global person identity index. Tenant-scoped person_records remain restricted projections linked through canonical_person_links.';
COMMENT ON COLUMN "public"."canonical_people"."date_of_birth" IS 'Date of birth, when known. Personal information - never exposed via canonical_person_public; governed paths only.';
COMMENT ON COLUMN "public"."canonical_people"."homeless_status" IS 'Independent homeless status for the person (e.g. living in a tent/vehicle), separate from any vehicle. Lifecycle: none -> claiming -> investigating -> confirmed. Reconciled to a vehicle via entity_links (occupant/lives_in). Mirrors canonical_vehicles.homeless_status.';
COMMENT ON COLUMN "public"."canonical_people"."homeless_verified_at" IS 'Timestamp the homeless_status was last confirmed by a human reviewer.';
COMMENT ON COLUMN "public"."canonical_people"."homeless_notes" IS 'Free-text note on the homeless_status finding. Personal information - never exposed via canonical_person_public; governed paths only.';

CREATE TABLE IF NOT EXISTS "public"."canonical_person_links" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "canonical_person_id" "uuid" NOT NULL,
    "source_table" "text" NOT NULL,
    "source_id" "uuid" NOT NULL,
    "organization_id" "uuid",
    "link_kind" "text" DEFAULT 'projection'::"text" NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL
);
COMMENT ON TABLE "public"."canonical_person_links" IS 'Global person identity links. Tenant-scoped person_records remain the access-controlled projection; canonical_people can be merged only with human identity evidence.';

CREATE TABLE IF NOT EXISTS "public"."canonical_place_links" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "canonical_place_id" "uuid" NOT NULL,
    "source_table" "text" NOT NULL,
    "source_id" "uuid" NOT NULL,
    "organization_id" "uuid",
    "link_kind" "text" DEFAULT 'projection'::"text" NOT NULL,
    "source_key" "text",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL
);
COMMENT ON TABLE "public"."canonical_place_links" IS 'Global place index links. Location, Site, Zone, and LOI facets may all point to the same canonical_place_id; source uniqueness prevents duplicate projections.';

CREATE TABLE IF NOT EXISTS "public"."canonical_places" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "place_kind" "text" NOT NULL,
    "canonical_key" "text" NOT NULL,
    "display_name" "text" NOT NULL,
    "normalized_name" "text" NOT NULL,
    "address" "text",
    "boundary" "public"."geometry"(MultiPolygon,4326),
    "center_point" "public"."geometry"(Point,4326),
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "merged_into_id" "uuid",
    "created_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL
);
COMMENT ON TABLE "public"."canonical_places" IS 'The place registry. One permanent row per real-world place: site (an address / LINZ lot, keyed site:<address key>) or zone (an area, keyed zone:<house id>). Organisations link to it through locations; nothing here is deleted, only merged or retired.';

CREATE TABLE IF NOT EXISTS "public"."canonical_scv" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "plate_number" "text" NOT NULL,
    "certificate_number" "text",
    "certificate_status" "text" DEFAULT 'active'::"text" NOT NULL,
    "issued_date" "date",
    "expiry_date" "date",
    "vehicle_make" "text",
    "vehicle_model" "text",
    "vehicle_year" integer,
    "nzscv_raw" "jsonb",
    "last_checked_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "source" "text" DEFAULT 'csv_import'::"text" NOT NULL,
    "import_batch_id" "uuid",
    "imported_at" timestamp with time zone,
    "raw_source_row" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL
);
COMMENT ON TABLE "public"."canonical_scv" IS 'SCV certification per plate. Source of truth: NZSCV registry. Synced via proxy-server.';
COMMENT ON COLUMN "public"."canonical_scv"."id" IS 'Global SCV registry identity. Used for Freedom Camping self-contained vehicle search independently of organization ownership.';

CREATE TABLE IF NOT EXISTS "public"."canonical_scv_links" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "canonical_scv_id" "uuid" NOT NULL,
    "source_system" "text" NOT NULL,
    "source_table" "text" NOT NULL,
    "source_key" "text" NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL
);

CREATE TABLE IF NOT EXISTS "public"."canonical_ta_names" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "ta_name" "text" NOT NULL,
    "ta_name_upper" "text" GENERATED ALWAYS AS (upper(ta_name)) STORED NOT NULL,
    "source" "text" DEFAULT 'nzta_featureserver'::"text" NOT NULL,
    "last_refreshed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."canonical_ta_names" IS 'Canonical NZ Territorial Authority names. Populated from the LIVE NZTA FeatureServer (Q1 ruling: never a hardcoded list). Used for proposal-time validation of district_names in set_org_jurisdiction and create_patrol_route_service_area. Phase 2 of the geofence redesign (epic #226).';

CREATE TABLE IF NOT EXISTS "public"."canonical_vehicle_links" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "canonical_vehicle_id" "uuid" NOT NULL,
    "source_system" "text" NOT NULL,
    "source_table" "text" NOT NULL,
    "source_key" "text" NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL
);

CREATE TABLE IF NOT EXISTS "public"."canonical_vehicles" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "plate_number" "text" NOT NULL,
    "make" "text",
    "model" "text",
    "year" integer,
    "colour" "text",
    "body_type" "text",
    "fuel_type" "text",
    "registered_owner_name" "text",
    "motorweb_enriched_at" timestamp with time zone,
    "embedding_quality" double precision,
    "last_seen_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "homeless_status" "text" DEFAULT 'none'::"text" NOT NULL,
    "homeless_verified_at" timestamp with time zone,
    "homeless_notes" "text",
    "rego_expiry" "date",
    "rego_status" "text",
    "wof_expiry" "date",
    "wof_status" "text",
    "cof_expiry" "date",
    "cof_status" "text",
    "compliance_checked_at" timestamp with time zone,
    "compliance_source" "text",
    "org_notes" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "vin" "text",
    "chassis_number" "text",
    "engine_number" "text",
    "external_data_source_name" "text",
    "external_data_source_url" "text",
    "external_data_source_location" "text",
    "external_data_source_checked_at" timestamp with time zone,
    "external_data_source_meta" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "details_updated_at" timestamp with time zone,
    "details_updated_by_org_id" "uuid",
    "details_updated_by" "uuid"
);
COMMENT ON TABLE "public"."canonical_vehicles" IS 'Vehicle attributes per plate. Platform-level (cross-org). Source: ONNX + MotorWeb.';
COMMENT ON COLUMN "public"."canonical_vehicles"."id" IS 'Global vehicle identity. Observations and operational records reference this identity while retaining organization/place context.';
COMMENT ON COLUMN "public"."canonical_vehicles"."homeless_status" IS 'Independent homeless status for the vehicle (lived-in), separate from any person. Lifecycle: none -> claiming -> investigating -> confirmed. Reconciled to a person via entity_links (occupant/lives_in).';
COMMENT ON COLUMN "public"."canonical_vehicles"."rego_expiry" IS 'NZ vehicle registration expiry date. Source: MotorWeb or manual entry.';
COMMENT ON COLUMN "public"."canonical_vehicles"."rego_status" IS 'Registration status: current, expired, unknown. Derived from rego_expiry vs now().';
COMMENT ON COLUMN "public"."canonical_vehicles"."wof_expiry" IS 'Warrant of Fitness expiry date. Applies to light vehicles (<3500 kg).';
COMMENT ON COLUMN "public"."canonical_vehicles"."wof_status" IS 'WoF status: current, expired, unknown. Derived from wof_expiry vs now().';
COMMENT ON COLUMN "public"."canonical_vehicles"."cof_expiry" IS 'Certificate of Fitness expiry date. Applies to heavy vehicles (>=3500 kg).';
COMMENT ON COLUMN "public"."canonical_vehicles"."cof_status" IS 'CoF status: current, expired, unknown. Derived from cof_expiry vs now().';
COMMENT ON COLUMN "public"."canonical_vehicles"."compliance_checked_at" IS 'Timestamp of the last compliance check (rego/WoF/CoF lookup).';
COMMENT ON COLUMN "public"."canonical_vehicles"."compliance_source" IS 'How compliance data was obtained: motoweb (API), manual (officer entry), canonical (seeded).';
COMMENT ON COLUMN "public"."canonical_vehicles"."org_notes" IS 'Reviewer notes on the vehicle, keyed by organization_id (text) -> {text, updated_at, updated_by}. Org-scoped by design: a note is this org''s context about a shared plate, not a fact about the vehicle. Never exposed via canonical_vehicle_public; read only through get_cctv_vehicle_note (returns the calling org''s own slice).';
COMMENT ON COLUMN "public"."canonical_vehicles"."vin" IS 'Vehicle identification number from a human-reviewed authoritative source. Source-time evidence remains in vehicle_identity_checks.';
COMMENT ON COLUMN "public"."canonical_vehicles"."chassis_number" IS 'Chassis number from a human-reviewed authoritative source. Source-time evidence remains in vehicle_identity_checks.';
COMMENT ON COLUMN "public"."canonical_vehicles"."engine_number" IS 'Engine number from a human-reviewed authoritative source. Source-time evidence remains in vehicle_identity_checks.';
COMMENT ON COLUMN "public"."canonical_vehicles"."external_data_source_name" IS 'Provider named by the latest licensed enrichment receipt; not a claim that the provider supplied every current vehicle field.';
COMMENT ON COLUMN "public"."canonical_vehicles"."external_data_source_url" IS 'Credential-free source locator for the latest licensed vehicle enrichment.';
COMMENT ON COLUMN "public"."canonical_vehicles"."external_data_source_location" IS 'Geographic or registry scope represented by the latest external source.';
COMMENT ON COLUMN "public"."canonical_vehicles"."external_data_source_checked_at" IS 'Time the latest licensed external source was retrieved.';
COMMENT ON COLUMN "public"."canonical_vehicles"."external_data_source_meta" IS 'Minimized source metadata. Raw provider responses and credentials are never stored.';
COMMENT ON COLUMN "public"."canonical_vehicles"."details_updated_at" IS 'When a human last corrected the shared vehicle profile facts (make/model/year/colour/body/expiries). Audit before/after in audit_log action vehicle_profile_details_updated.';
COMMENT ON COLUMN "public"."canonical_vehicles"."details_updated_by_org_id" IS 'Organisation whose administrator last corrected the shared vehicle profile facts.';

CREATE TABLE IF NOT EXISTS "public"."cctv_camera_scene_profiles" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "location_id" "uuid",
    "site_id" "uuid",
    "zone_id" "uuid",
    "camera_key" "text" NOT NULL,
    "scene_label" "text",
    "scene_fingerprint" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "first_seen_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    "last_seen_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    "evidence_count" integer DEFAULT 0 NOT NULL,
    "recidivism_summary" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "review_state" "text" DEFAULT 'active'::"text" NOT NULL
);

CREATE TABLE IF NOT EXISTS "public"."cctv_cloud_inference_receipts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "inference_job_id" "uuid" NOT NULL,
    "evidence_item_id" "uuid",
    "source_event_id" "text",
    "provider" "text" NOT NULL,
    "purpose" "text" NOT NULL,
    "model" "text" NOT NULL,
    "crop_sha256" "text" NOT NULL,
    "crop_bytes" integer NOT NULL,
    "plate_masked" boolean NOT NULL,
    "plate_boxes_masked" integer NOT NULL,
    "persons_excluded" boolean NOT NULL,
    "policy_set_at" timestamp with time zone NOT NULL,
    "created_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL
);
COMMENT ON TABLE "public"."cctv_cloud_inference_receipts" IS 'One row per vehicle crop sent to a cloud vision model, written before the send. Holds the crop hash and privacy checks (plates masked, no people), never the image. Written only by record_cctv_cloud_inference_receipt.';

CREATE TABLE IF NOT EXISTS "public"."cctv_device_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "cctv_import_id" "uuid" NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "source" "text" NOT NULL,
    "source_ref" "text" NOT NULL,
    "event_start_at" timestamp with time zone NOT NULL,
    "event_end_at" timestamp with time zone,
    "severity" "text" DEFAULT 'motion'::"text" NOT NULL,
    "thumbnail_path" "text",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL
);
COMMENT ON TABLE "public"."cctv_device_events" IS 'Motion/activity intervals the camera itself recorded (snapshot or index files) or inference produced, per import. Timeline marks, not evidence.';

CREATE TABLE IF NOT EXISTS "public"."cctv_entity_observations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "inference_job_id" "uuid" NOT NULL,
    "evidence_item_id" "uuid" NOT NULL,
    "source_event_id" "text" NOT NULL,
    "entity_kind" "text" NOT NULL,
    "observed_at" timestamp with time zone NOT NULL,
    "observed_to" timestamp with time zone,
    "site_id" "uuid",
    "zone_id" "uuid",
    "canonical_person_id" "uuid",
    "canonical_vehicle_id" "uuid",
    "candidate_label" "text",
    "candidate_plate" "text",
    "animal_type" "text",
    "candidate_embedding" "jsonb",
    "model_confidence" real,
    "frame_sha256" "text",
    "thumbnail" "text",
    "review_state" "text" DEFAULT 'unreviewed'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    "person_record_id" "uuid",
    "cctv_import_id" "uuid",
    "location_id" "uuid",
    "canonical_place_id" "uuid",
    "quality_state" "text" DEFAULT 'clear'::"text" NOT NULL,
    "species_confidence" real,
    "is_pest" boolean,
    "attributes" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "appearance_embedding" "jsonb",
    "face_vec" "public"."vector"(128),
    "appearance_vec" "public"."vector"(256),
    "portfolio_key" "uuid",
    "portfolio_state" "text" DEFAULT 'unmatched'::"text" NOT NULL,
    "portfolio_candidates" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "reviewed_by" "uuid",
    "reviewed_at" timestamp with time zone,
    "review_notes" "text",
    "vehicle_appearance_vec" "public"."vector"(512)
);
COMMENT ON TABLE "public"."cctv_entity_observations" IS 'Cross-job CCTV person, vehicle, and animal observations. Similarity remains provisional until a human review link is accepted.';
COMMENT ON COLUMN "public"."cctv_entity_observations"."animal_type" IS 'Species label (NZ forestry pest list first: possum, stoat, ferret, weasel, rat, mouse, hedgehog, deer, pig, goat, cat, dog, rabbit, hare, wallaby, other).';
COMMENT ON COLUMN "public"."cctv_entity_observations"."candidate_embedding" IS 'Raw model embedding for the sighting. Service/definer paths only; not readable by browser roles. Expired by expire_cctv_biometric_templates.';
COMMENT ON COLUMN "public"."cctv_entity_observations"."attributes" IS 'Model attributes: vehicle make/model/colour/body_type, plate_confidence, bbox, track_id, body/clothing descriptors.';
COMMENT ON COLUMN "public"."cctv_entity_observations"."appearance_embedding" IS 'Raw appearance embedding for the sighting. Service/definer paths only; not readable by browser roles. Expired by expire_cctv_biometric_templates.';
COMMENT ON COLUMN "public"."cctv_entity_observations"."face_vec" IS 'Biometric face template (128-d). Service/definer paths only; not readable by browser roles. Expired by expire_cctv_biometric_templates.';
COMMENT ON COLUMN "public"."cctv_entity_observations"."appearance_vec" IS 'Appearance (re-identification) template (256-d). Service/definer paths only; not readable by browser roles. Expired by expire_cctv_biometric_templates.';
COMMENT ON COLUMN "public"."cctv_entity_observations"."portfolio_key" IS 'Provisional identity cluster: observations judged the same person/vehicle by similarity. A human review action turns a portfolio into a canonical identity.';
COMMENT ON COLUMN "public"."cctv_entity_observations"."vehicle_appearance_vec" IS 'Official Open Model Zoo vehicle-reid-0001 512-d template. Service/definer paths only; never exposed to browser roles.';

CREATE TABLE IF NOT EXISTS "public"."cctv_exports" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "inference_job_id" "uuid" NOT NULL,
    "evidence_item_id" "uuid" NOT NULL,
    "purpose" "text" NOT NULL,
    "recipient_scope" "text" NOT NULL,
    "legal_hold" boolean DEFAULT false NOT NULL,
    "approval_state" "text" DEFAULT 'draft'::"text" NOT NULL,
    "selected_event_ids" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "manifest" "jsonb" NOT NULL,
    "manifest_sha256" "text" NOT NULL,
    "generated_by" "uuid" NOT NULL,
    "approved_by" "uuid",
    "generated_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    "approved_at" timestamp with time zone,
    "sealed_at" timestamp with time zone,
    "issued_at" timestamp with time zone,
    "artifact_bucket" "text",
    "artifact_path" "text"
);
COMMENT ON TABLE "public"."cctv_exports" IS 'Immutable CCTV evidence package manifests. Approval and sealing are separate from report printing.';
COMMENT ON COLUMN "public"."cctv_exports"."artifact_path" IS 'Private storage object for the sealed export package. Access requires an audited signed URL path.';

CREATE TABLE IF NOT EXISTS "public"."cctv_identity_drafts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "inference_job_id" "uuid" NOT NULL,
    "evidence_item_id" "uuid" NOT NULL,
    "event_id" "text",
    "event_type" "text" NOT NULL,
    "subject_kind" "text" NOT NULL,
    "proposed_person_record_id" "uuid",
    "proposed_display_name" "text",
    "candidate_matches" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "status" "text" DEFAULT 'proposed'::"text" NOT NULL,
    "authority_level" "text" DEFAULT 'provisional'::"text" NOT NULL,
    "final_action" "text",
    "final_person_record_id" "uuid",
    "reason" "text",
    "review_notes" "text",
    "created_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    "approved_by" "uuid",
    "approved_at" timestamp with time zone
);

CREATE TABLE IF NOT EXISTS "public"."cctv_imports" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "location_id" "uuid" NOT NULL,
    "canonical_place_id" "uuid" NOT NULL,
    "site_id" "uuid",
    "zone_id" "uuid",
    "camera_label" "text" NOT NULL,
    "camera_key" "text" NOT NULL,
    "source_device_kind" "text" DEFAULT 'unknown'::"text" NOT NULL,
    "source_timezone" "text" DEFAULT 'Pacific/Auckland'::"text" NOT NULL,
    "source_root_label" "text",
    "watermark_location_hint" "text",
    "source_manifest" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "video_count" integer DEFAULT 0 NOT NULL,
    "skipped_count" integer DEFAULT 0 NOT NULL,
    "snapshot_count" integer DEFAULT 0 NOT NULL,
    "bytes_total" bigint DEFAULT 0 NOT NULL,
    "recorded_from" timestamp with time zone,
    "recorded_to" timestamp with time zone,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "notes" "text",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL
);
COMMENT ON TABLE "public"."cctv_imports" IS 'One camera folder / SD-card import. Anchored to a house (locations) and its registry place before any file is accepted; the watermark text is a hint only.';

CREATE TABLE IF NOT EXISTS "public"."cctv_inference_budgets" (
    "organization_id" "uuid" NOT NULL,
    "daily_frame_budget" integer NOT NULL,
    "reason" "text",
    "set_by" "uuid",
    "set_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL
);
COMMENT ON TABLE "public"."cctv_inference_budgets" IS 'Per-organisation daily cap on frames sent to GPU inference by the CCTV worker. No row = platform default. Written via set_cctv_inference_budget only.';

CREATE TABLE IF NOT EXISTS "public"."cctv_inference_claim_pauses" (
    "holder" "text" NOT NULL,
    "reason" "text" NOT NULL,
    "paused_until" timestamp with time zone NOT NULL,
    "created_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL
);
COMMENT ON TABLE "public"."cctv_inference_claim_pauses" IS 'Release-time pauses of CCTV inference job claims. Written only by pause_/resume_cctv_inference_claims (service role); a row blocks claim_cctv_inference_job until paused_until.';

CREATE TABLE IF NOT EXISTS "public"."cctv_inference_policies" (
    "organization_id" "uuid" NOT NULL,
    "cloud_vehicle_vlm_enabled" boolean DEFAULT false NOT NULL,
    "cloud_vehicle_vlm_model" "text",
    "reason" "text",
    "set_by" "uuid",
    "set_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL
);
COMMENT ON TABLE "public"."cctv_inference_policies" IS 'Per-organisation CCTV inference governance. cloud_vehicle_vlm_enabled permits only person-free, plate-masked vehicle crops to a cloud vision model, each preceded by a cctv_cloud_inference_receipts row. Written only by set_cctv_inference_policy.';

CREATE TABLE IF NOT EXISTS "public"."cctv_media_upload_claims" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "evidence_kind" "text" NOT NULL,
    "sha256" "text" NOT NULL,
    "cctv_import_id" "uuid" NOT NULL,
    "storage_path" "text" NOT NULL,
    "status" "text" DEFAULT 'claimed'::"text" NOT NULL,
    "evidence_item_id" "uuid",
    "claimed_by" "uuid",
    "claimed_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    "expires_at" timestamp with time zone DEFAULT (clock_timestamp() + '00:30:00'::interval) NOT NULL,
    "registered_at" timestamp with time zone
);
COMMENT ON TABLE "public"."cctv_media_upload_claims" IS 'Short-lived hash reservation made before Desktop V2 uploads CCTV bytes. One organization/kind/hash can upload at a time; registered evidence wins permanently.';

CREATE TABLE IF NOT EXISTS "public"."cctv_missed_detection_reports" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "evidence_item_id" "uuid" NOT NULL,
    "inference_job_id" "uuid",
    "entity_kind" "text" NOT NULL,
    "offset_seconds" numeric,
    "observed_at" timestamp with time zone,
    "bbox" "jsonb",
    "notes" "text",
    "engine_version" "text",
    "state" "text" DEFAULT 'open'::"text" NOT NULL,
    "reported_by" "uuid" NOT NULL,
    "reported_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    "resolved_by" "uuid",
    "resolved_at" timestamp with time zone,
    "resolution_notes" "text"
);
COMMENT ON TABLE "public"."cctv_missed_detection_reports" IS 'A reviewer-reported sighting the CCTV engine did not produce. Counts toward recall in cctv_accuracy_summary. Written only by report_cctv_missed_detection and resolved only by resolve_cctv_missed_detection.';

CREATE TABLE IF NOT EXISTS "public"."cctv_observation_derivatives" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "observation_id" "uuid" NOT NULL,
    "inference_job_id" "uuid" NOT NULL,
    "evidence_item_id" "uuid" NOT NULL,
    "source_event_id" "text" NOT NULL,
    "entity_kind" "text" NOT NULL,
    "original_bucket" "text" NOT NULL,
    "original_path" "text" NOT NULL,
    "original_sha256" "text" NOT NULL,
    "enhanced_bucket" "text" NOT NULL,
    "enhanced_path" "text" NOT NULL,
    "enhanced_sha256" "text" NOT NULL,
    "provider" "text" NOT NULL,
    "enhancement_profile" "text" NOT NULL,
    "generative" boolean DEFAULT false NOT NULL,
    "source_frame_hash" "text",
    "source_frames" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "fusion_receipt" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "enhancement_receipt" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "recognition_results" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "recognition_comparison" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "review_required" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL
);
COMMENT ON TABLE "public"."cctv_observation_derivatives" IS 'Private original/enhanced still pairs and receipts for human CCTV review. Source evidence remains authoritative; generative output is always interpretive.';

