CREATE TABLE IF NOT EXISTS "public"."crm_commercial_settings" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "service_agreement_id" "uuid" NOT NULL,
    "billing_cycle" "text" DEFAULT 'monthly'::"text" NOT NULL,
    "payment_terms_days" integer DEFAULT 14 NOT NULL,
    "currency" "text" DEFAULT 'NZD'::"text" NOT NULL,
    "base_rate_per_hour" numeric(10,2),
    "overtime_rate_per_hour" numeric(10,2),
    "callout_minimum_hours" numeric(4,2) DEFAULT 3,
    "callout_rate_per_hour" numeric(10,2),
    "travel_rate_per_km" numeric(6,4),
    "infringement_admin_fee" numeric(10,2),
    "invoice_email" "text",
    "purchase_order_number" "text",
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "commercial_model" "text",
    "updated_at" timestamp with time zone,
    "standing_authority_limit" numeric(12,2),
    "payment_due_day_of_month" smallint,
    "fee_overrun_policy" "text"
);
COMMENT ON TABLE "public"."crm_commercial_settings" IS 'Billing and commercial configuration per service agreement.';
COMMENT ON COLUMN "public"."crm_commercial_settings"."payment_terms_days" IS 'Days after the invoice date that payment is due, used only when payment_due_day_of_month is not set.';
COMMENT ON COLUMN "public"."crm_commercial_settings"."base_rate_per_hour" IS 'Agreed hourly rate, before GST.';
COMMENT ON COLUMN "public"."crm_commercial_settings"."overtime_rate_per_hour" IS 'Agreed overtime hourly rate, before GST.';
COMMENT ON COLUMN "public"."crm_commercial_settings"."callout_rate_per_hour" IS 'Agreed callout hourly rate, before GST.';
COMMENT ON COLUMN "public"."crm_commercial_settings"."travel_rate_per_km" IS 'Agreed travel rate per km, before GST.';
COMMENT ON COLUMN "public"."crm_commercial_settings"."commercial_model" IS 'How work on this agreement is charged: fixed_price_with_extras (contract price + Extra), pay_as_you_go (all work at agreed rates each cycle), do_and_invoice (standing authority to do what is needed, invoice actuals; client approval needed only above standing_authority_limit), per_request (each job requested by the client, request/PO reference required). NULL = not set; every callout needs a Contract/Extra decision. Set only through set_agreement_commercial_terms (audited).';
COMMENT ON COLUMN "public"."crm_commercial_settings"."updated_at" IS 'Last change through set_agreement_commercial_terms.';
COMMENT ON COLUMN "public"."crm_commercial_settings"."standing_authority_limit" IS 'Do and invoice only: the most one job may cost (charge lines, excl. GST) under the client''s standing authority. A job above it needs the client''s approval reference (dispatch_jobs.client_order_reference) before it is invoiced. NULL = no cap. Set only through set_agreement_commercial_terms (audited).';
COMMENT ON COLUMN "public"."crm_commercial_settings"."payment_due_day_of_month" IS 'When set, an invoice is due on this day of the month after the invoiced work period (20 = 20th of the following month), and never before the invoice date. Overrides payment_terms_days. NULL = payment_terms_days after the invoice date. Set only through set_agreement_commercial_terms (audited).';
COMMENT ON COLUMN "public"."crm_commercial_settings"."fee_overrun_policy" IS 'Fixed price plus Extra only: what happens when contracted work in a month is worth more than the monthly fee. bill_as_extra = pre-agreed with the client, the excess is billed as Extra; justify (or NULL) = the excess is billed only with a written justification on the invoice, otherwise absorbed.';

