    "work_request_id" "uuid" NOT NULL,
    "criterion_text" "text" NOT NULL,
    "sort_order" integer DEFAULT 0 NOT NULL,
    "is_required" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);

CREATE TABLE IF NOT EXISTS "public"."dev_work_approvals" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "work_request_id" "uuid" NOT NULL,
    "approval_stage" "text" NOT NULL,
    "decision" "text" NOT NULL,
    "decided_by" "uuid",
    "decision_note" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "decided_at" timestamp with time zone
);

CREATE TABLE IF NOT EXISTS "public"."dev_work_artifacts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "run_id" "uuid" NOT NULL,
    "artifact_type" "text" NOT NULL,
    "storage_path" "text",
    "content_text" "text",
    "content_json" "jsonb",
    "mime_type" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);

CREATE TABLE IF NOT EXISTS "public"."dev_work_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "work_request_id" "uuid" NOT NULL,
    "run_id" "uuid",
    "event_type" "text" NOT NULL,
    "event_payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);

CREATE TABLE IF NOT EXISTS "public"."dev_work_requests" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "title" "text" NOT NULL,
    "goal" "text" NOT NULL,
    "description" "text",
    "request_type" "text" NOT NULL,
    "target_area" "text",
    "risk_tier" "text" NOT NULL,
    "status" "text" NOT NULL,
    "requested_by" "uuid",
    "assigned_runner" "text",
    "execution_host" "text" DEFAULT 'hpanel'::"text" NOT NULL,
    "source_repo" "text",
    "target_branch" "text",
    "draft_branch" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "verified_at" timestamp with time zone,
    "ratified_at" timestamp with time zone,
    "promoted_at" timestamp with time zone
);

CREATE TABLE IF NOT EXISTS "public"."dev_work_runs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "work_request_id" "uuid" NOT NULL,
    "run_number" integer NOT NULL,
    "status" "text" NOT NULL,
    "worker_name" "text",
    "worker_host" "text",
    "started_at" timestamp with time zone,
    "finished_at" timestamp with time zone,
    "exit_summary" "text",
    "branch_name" "text",
    "commit_ref" "text",
    "test_summary" "jsonb",
    "build_summary" "jsonb",
    "failure_summary" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);

CREATE TABLE IF NOT EXISTS "public"."dispatch_job_charge_lines" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "source_dispatch_id" "uuid" NOT NULL,
    "client_organization_id" "uuid",
    "service_agreement_id" "uuid",
    "rate_rule_id" "uuid",
    "rate_type" "text" NOT NULL,
    "description" "text" NOT NULL,
    "quantity" numeric DEFAULT 0 NOT NULL,
    "unit_rate" numeric DEFAULT 0 NOT NULL,
    "line_total" numeric DEFAULT 0 NOT NULL,
    "distance_km" numeric,
    "service_type" "text",
    "day_category" "text",
    "invoice_line_item_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "billing_basis" "text",
    "extra_work_order_id" "uuid"
);
COMMENT ON TABLE "public"."dispatch_job_charge_lines" IS 'Customer charge lines resolved from billing rate_rules when a dispatch job completes (pay lines are the staff side). rate_rule_id NULL = unresolved, kept for finance review, never a $0 charge.';
COMMENT ON COLUMN "public"."dispatch_job_charge_lines"."billing_basis" IS 'Copied from dispatch_jobs.billing_basis when the line is written and kept in step by set_dispatch_job_billing_basis until invoiced. NULL = job not yet classified.';

CREATE TABLE IF NOT EXISTS "public"."dispatch_job_pay_line_reviews" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "pay_line_id" "uuid" NOT NULL,
    "decision" "text" NOT NULL,
    "review_notes" "text",
    "reviewed_by" "uuid" NOT NULL,
    "reviewed_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    "supersedes_review_id" "uuid",
    "client_request_id" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."dispatch_job_pay_line_reviews" IS 'Append-only finance decisions for calculated dispatch pay evidence. A later decision supersedes, never updates or deletes, the earlier decision.';

CREATE TABLE IF NOT EXISTS "public"."dispatch_job_pay_lines" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "source_dispatch_id" "uuid" NOT NULL,
    "officer_user_id" "uuid",
    "rate_rule_id" "uuid",
    "pay_code" "text",
    "rate_type" "text" NOT NULL,
    "description" "text" NOT NULL,
    "quantity" numeric(12,4) DEFAULT 1 NOT NULL,
    "unit_rate" numeric(12,4) DEFAULT 0 NOT NULL,
    "multiplier" numeric(6,4) DEFAULT 1 NOT NULL,
    "line_total" numeric(12,2) DEFAULT 0 NOT NULL,
    "distance_km" numeric(10,3),
    "distance_reason" "text",
    "role_code" "text",
    "region_code" "text",
    "service_type" "text",
    "day_category" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."dispatch_job_pay_lines" IS 'Resolved pay/cost lines per completed dispatch job. One row per pay_code per job. Output of resolvePayLines() from rateEngine.ts. Idempotent via partial unique index on (organization_id, source_dispatch_id, pay_code).';

CREATE TABLE IF NOT EXISTS "public"."dispatch_job_protected_parties" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "dispatch_job_id" "uuid" NOT NULL,
    "party_role" "text" NOT NULL,
    "display_name" "text",
    "phone" "text",
    "email" "text",
    "notes" "text",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_by" "uuid",
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."dispatch_job_protected_parties" IS 'Sensitive party identity for a dispatch job (complainant etc.). No read policy: readable only through get_dispatch_job_protected_party, which applies the three-question test and logs the read (Privacy Act IPP 6). NOTICES_HARMED_PARTY_SENSITIVITY option (a).';

CREATE TABLE IF NOT EXISTS "public"."dispatch_jobs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "service_agreement_id" "uuid",
    "dispatch_resource_id" "uuid",
    "location_id" "uuid",
    "client_site_id" "uuid",
    "job_type" "text" NOT NULL,
    "priority" "text" DEFAULT 'normal'::"text" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "sla_minutes" integer,
    "sla_breached" boolean DEFAULT false NOT NULL,
    "briefing_notes" "text",
    "outcome_notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "dispatched_at" timestamp with time zone,
    "acknowledged_at" timestamp with time zone,
    "en_route_at" timestamp with time zone,
    "on_scene_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "shift_id" "uuid",
    "shift_stop_id" "uuid",
    "sla_respond_by" timestamp with time zone,
    "sla_impact_warning" boolean DEFAULT false NOT NULL,
    "sla_impact_report" "jsonb",
    "adhoc_inserted_at" timestamp with time zone,
    "insert_gps_lat" double precision,
    "insert_gps_lng" double precision,
    "client_request_id" "uuid",
    "expected_dwell_minutes" integer DEFAULT 5 NOT NULL,
    "timing_source" "text" DEFAULT 'dispatch_default'::"text" NOT NULL,
    "investigation_id" "uuid",
    "origin_type" "text" DEFAULT 'standard'::"text" NOT NULL,
    "origin_reference_id" "uuid",
    "assigned_officer_id" "uuid",
    "work_unit_id" "uuid",
    "module_key" "text",
    "harmed_party_site_id" "uuid",
    "harmed_party_address" "text",
    "sla_delay_reason" "text",
    "zone_id" "uuid",
    "billing_basis" "text",
    "extra_work_order_id" "uuid",
    "billing_basis_set_at" timestamp with time zone,
    "billing_basis_set_by" "uuid",
    "client_order_reference" "text"
);
COMMENT ON TABLE "public"."dispatch_jobs" IS 'Dispatch jobs with full lifecycle state machine. SLA tracking and client site context.';
COMMENT ON COLUMN "public"."dispatch_jobs"."dispatch_resource_id" IS 'FK to dispatch_resources (named patrol run / callsign). Written by field module pages when officer has an active shift.';
COMMENT ON COLUMN "public"."dispatch_jobs"."client_site_id" IS 'Site the job is associated with. FK to client_sites. Written by NoiseControlPage.';
COMMENT ON COLUMN "public"."dispatch_jobs"."job_type" IS 'Module-specific job type (e.g. noise_complaint, parking_enforcement). Written by field module pages.';
COMMENT ON COLUMN "public"."dispatch_jobs"."sla_minutes" IS 'SLA target in minutes from job creation. Written by field module pages.';
COMMENT ON COLUMN "public"."dispatch_jobs"."briefing_notes" IS 'Human-readable briefing for the responding officer. Written by field module pages.';
COMMENT ON COLUMN "public"."dispatch_jobs"."dispatched_at" IS 'Timestamp when the job was dispatched to a resource. Written by field module pages.';
COMMENT ON COLUMN "public"."dispatch_jobs"."sla_respond_by" IS 'Absolute SLA deadline timestamp. Written by field module pages.';
COMMENT ON COLUMN "public"."dispatch_jobs"."harmed_party_site_id" IS 'Place of harm (complainant / protected land) as a client_sites facet. client_site_id remains the work place (noise source). Ruling 2026-09-14.';
COMMENT ON COLUMN "public"."dispatch_jobs"."harmed_party_address" IS 'Complainant / harmed-party address as received. Readable only where the harmed-party read applies; never on served documents.';
COMMENT ON COLUMN "public"."dispatch_jobs"."sla_delay_reason" IS 'Mandatory explanation when arrival breached the SLA clock; the client report must state any material delay and its reasons.';
COMMENT ON COLUMN "public"."dispatch_jobs"."zone_id" IS 'Zone where the job is performed when the agreement place is not an addressed Site. Exactly one of client_site_id or zone_id is required.';
COMMENT ON COLUMN "public"."dispatch_jobs"."billing_basis" IS 'contract = inside the fixed contract price; extra = outside contracted scope, billed on top. NULL = not yet classified. Set only through set_dispatch_job_billing_basis (audited).';
COMMENT ON COLUMN "public"."dispatch_jobs"."extra_work_order_id" IS 'The Extra works order that authorises this job, when the Extra work is part of temporary/ongoing authorised work rather than a one-off.';
COMMENT ON COLUMN "public"."dispatch_jobs"."client_order_reference" IS 'The client''s own reference for this job: the request or purchase-order reference (required before invoicing on per_request agreements) or the client''s approval (required on do_and_invoice agreements when the job costs more than the standing authority limit). Set only through set_dispatch_job_client_reference (audited).';

CREATE TABLE IF NOT EXISTS "public"."dispatch_resources" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "callsign" "text",
    "service_type" "text" NOT NULL,
    "location_id" "uuid",
    "assigned_officer_id" "uuid",
    "status" "text" DEFAULT 'available'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."dispatch_resources" IS 'Named patrol runs / callsigns. Jobs dispatch to a resource (not an officer); the roster resolves which officer is on the run. SELECT org-scoped; write admin.';

CREATE TABLE IF NOT EXISTS "public"."disputes" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "notice_id" "uuid" NOT NULL,
    "submitter_name" "text",
    "submitter_email" "text",
    "submitter_phone" "text",
    "grounds" "text",
    "bob_analysis" "text",
    "bob_confidence" real,
    "status" "text" DEFAULT 'received'::"text" NOT NULL,
    "decision_note" "text",
    "decided_by" "uuid",
    "decided_at" timestamp with time zone,
    "submitted_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "notice_number" "text",
    "dispute_type" "text",
    "plate_number" "text",
    "notice_date" "date",
    "scv_number" "text",
    "statement" "text",
    "review_notes" "text",
    "reviewed_by" "uuid",
    "reviewed_at" timestamp with time zone
);
COMMENT ON TABLE "public"."disputes" IS 'Notice disputes (org-scoped via organization_id, linked via notice_id). SELECT: org_access_allowed. UPDATE: admin (review decisions). INSERT is via the submit-dispute service-role edge function, not anon.';
COMMENT ON COLUMN "public"."disputes"."notice_number" IS 'Notice number as entered by the disputer (used to resolve notice_id/org).';
COMMENT ON COLUMN "public"."disputes"."statement" IS 'Free-text dispute statement from the public portal.';
COMMENT ON COLUMN "public"."disputes"."review_notes" IS 'Internal admin review notes (distinct from decision_note).';

CREATE TABLE IF NOT EXISTS "public"."document_classifications" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "document_version_id" "uuid" NOT NULL,
    "privacy_class" "text" NOT NULL,
    "contains_pii" boolean DEFAULT false NOT NULL,
    "contains_operational_security" boolean DEFAULT false NOT NULL,
    "contains_financial_data" boolean DEFAULT false NOT NULL,
    "contains_legal_privilege" boolean DEFAULT false NOT NULL,
    "classifier_source" "text" DEFAULT 'bob'::"text" NOT NULL,
    "confidence" real,
    "rationale" "text",
    "reviewed_by" "uuid",
    "reviewed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."document_classifications" IS 'Sensitivity classification for a document version. Bob may propose (classifier_source=bob); low-confidence / high-risk classifications require human_review before any promotion to a shared library.';

CREATE TABLE IF NOT EXISTS "public"."document_placements" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "document_id" "uuid" NOT NULL,
    "space_id" "uuid" NOT NULL,
    "folder_id" "uuid",
    "is_primary" boolean DEFAULT true NOT NULL,
    "client_request_id" "uuid",
    "placed_by" "uuid",
    "placed_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    "removed_at" timestamp with time zone
);
COMMENT ON TABLE "public"."document_placements" IS 'Auditable document-to-folder placement history. Exactly one active primary placement exists per tenant document.';

CREATE TABLE IF NOT EXISTS "public"."document_promotion_proposals" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "document_version_id" "uuid" NOT NULL,
    "target_type" "text" NOT NULL,
    "proposed_payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "source_map" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "status" "text" DEFAULT 'proposed'::"text" NOT NULL,
    "requested_by" "uuid" NOT NULL,
    "reviewed_by" "uuid",
    "reviewed_at" timestamp with time zone,
    "review_reason" "text",
    "created_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    "applied_target_id" "uuid",
    "applied_at" timestamp with time zone
);

CREATE TABLE IF NOT EXISTS "public"."document_reference_sources" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "label" "text" NOT NULL,
    "source_kind" "text" DEFAULT 'repo_folder'::"text" NOT NULL,
    "location_ref" "text" NOT NULL,
    "organization_id" "uuid",
    "trust_level" "text" DEFAULT 'provisional'::"text" NOT NULL,
    "default_scope" "text" DEFAULT 'tenant_reference'::"text" NOT NULL,
    "default_sensitivity" "text" DEFAULT 'tenant_sensitive'::"text" NOT NULL,
    "approval_status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."document_reference_sources" IS 'Registry of approved source-location roots Bob may draw reference material from. local_folder values use a neutral alias resolved only by an approved worker; absolute workstation paths and credentials are never exposed through the app. Registering a location does not ingest or promote content.';

CREATE TABLE IF NOT EXISTS "public"."document_source_ingestion_runs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "source_id" "uuid" NOT NULL,
    "requested_by" "uuid" NOT NULL,
    "client_request_id" "uuid" NOT NULL,
    "mode" "text" DEFAULT 'inventory'::"text" NOT NULL,
    "status" "text" DEFAULT 'queued'::"text" NOT NULL,
    "phase" "text" DEFAULT 'enumeration'::"text" NOT NULL,
    "worker_id" "text",
    "lease_token" "uuid",
    "lease_expires_at" timestamp with time zone,
    "cursor_json" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "discovered_count" bigint DEFAULT 0 NOT NULL,
    "hashed_count" bigint DEFAULT 0 NOT NULL,
    "duplicate_count" bigint DEFAULT 0 NOT NULL,
    "supported_count" bigint DEFAULT 0 NOT NULL,
    "partial_count" bigint DEFAULT 0 NOT NULL,
    "gap_count" bigint DEFAULT 0 NOT NULL,
    "excluded_count" bigint DEFAULT 0 NOT NULL,
    "quarantined_count" bigint DEFAULT 0 NOT NULL,
    "failed_count" bigint DEFAULT 0 NOT NULL,
    "error_code" "text",
    "error_detail_redacted" "text",
    "requested_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    "started_at" timestamp with time zone,
    "heartbeat_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "updated_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL
);
COMMENT ON TABLE "public"."document_source_ingestion_runs" IS 'Durable, resumable jobs for approved document_reference_sources. A run starts read-only and records inventory/checkpoint receipts before any extraction or governed promotion.';

CREATE TABLE IF NOT EXISTS "public"."document_source_manifest_entries" (
    "id" bigint GENERATED ALWAYS AS IDENTITY NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "run_id" "uuid" NOT NULL,
    "source_id" "uuid" NOT NULL,
    "relative_path" "text" NOT NULL,
    "file_name" "text" NOT NULL,
    "extension" "text",
    "size_bytes" bigint NOT NULL,
    "modified_at" timestamp with time zone,
    "sha256" "text",
    "capability_status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "sensitivity" "text" DEFAULT 'unclassified'::"text" NOT NULL,
    "disposition" "text" DEFAULT 'pending'::"text" NOT NULL,
    "extraction_status" "text" DEFAULT 'not_started'::"text" NOT NULL,
    "document_id" "uuid",
    "duplicate_of_entry_id" bigint,
    "error_code" "text",
    "metadata_json" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL
);
COMMENT ON TABLE "public"."document_source_manifest_entries" IS 'Tenant-scoped metadata manifest for a source run. Paths are relative to the approved source alias; source bytes and absolute workstation paths never enter this table.';

CREATE TABLE IF NOT EXISTS "public"."document_source_run_events" (
    "id" bigint GENERATED ALWAYS AS IDENTITY NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "run_id" "uuid" NOT NULL,
    "event_type" "text" NOT NULL,
    "phase" "text",
    "counts_json" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "message_redacted" "text",
    "created_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL
);
COMMENT ON TABLE "public"."document_source_run_events" IS 'Append-only before/during/after receipts for document source ingestion runs. Messages must not contain credentials, absolute paths, or extracted private content.';

CREATE TABLE IF NOT EXISTS "public"."document_upload_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "document_id" "uuid",
    "attachment_id" "uuid",
    "sha256" "text" NOT NULL,
    "original_filename" "text" NOT NULL,
    "mime_type" "text",
    "uploaded_by" "uuid",
    "organization_id" "uuid",
    "conversation_id" "uuid",
    "source_channel" "text" DEFAULT 'chat_upload'::"text" NOT NULL,
    "was_deduplicated" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."document_upload_events" IS 'Provenance ledger: one row per upload/attach event, ALWAYS recorded even when the bytes already exist (was_deduplicated=true). Separate from the canonical documents row so dedupe never loses who/where/when.';

CREATE TABLE IF NOT EXISTS "public"."document_versions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "document_id" "uuid" NOT NULL,
    "version_label" "text" DEFAULT 'v1'::"text" NOT NULL,
    "effective_from" "date",
    "effective_to" "date",
    "supersedes_version_id" "uuid",
    "extracted_text" "text",
    "extraction_confidence" real,
    "ocr_required" boolean DEFAULT false NOT NULL,
    "metadata_json" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."document_versions" IS 'Extracted, readable content for a document version. Text is stored separately from the binary blob. Supports supersession and effective-date windows.';

CREATE TABLE IF NOT EXISTS "public"."documents" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "attachment_id" "uuid",
    "storage_bucket" "text" DEFAULT 'bob-uploads'::"text" NOT NULL,
    "storage_object_ref" "text",
    "original_filename" "text" NOT NULL,
    "mime_type" "text" NOT NULL,
    "sha256" "text",
    "uploaded_by" "uuid",
    "source_channel" "text" DEFAULT 'chat_upload'::"text" NOT NULL,
    "conversation_id" "uuid",
    "organization_id" "uuid",
    "current_scope" "text" DEFAULT 'conversation_only'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."documents" IS 'Registry row per stored document object. Bytes live in Supabase Storage (bob-uploads); this row holds provenance, tenant scope and discoverability. organization_id null = global/public reference material.';

CREATE TABLE IF NOT EXISTS "public"."dynamic_risk_assessments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "shift_id" "uuid" NOT NULL,
    "officer_id" "uuid" NOT NULL,
    "location_id" "uuid" NOT NULL,
    "site_id" "uuid",
    "zone_id" "uuid",
    "task" "text" NOT NULL,
    "hazards" "text" NOT NULL,
    "controls" "text"[] NOT NULL,
    "likelihood" smallint NOT NULL,
    "consequence" smallint NOT NULL,
    "decision" "text" NOT NULL,
    "briefing_snapshot" "jsonb" NOT NULL,
    "signed_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    "client_request_id" "uuid" NOT NULL
);
COMMENT ON TABLE "public"."dynamic_risk_assessments" IS 'Immutable officer-authored task assessment and electronic attestation, not a supervisor approval or legal certification. Unsafe means stop this task and contact the supervisor; a later assessment never rewrites the original.';

CREATE TABLE IF NOT EXISTS "public"."effective_rule_snapshots" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "module_key" "text" NOT NULL,
    "governing_jurisdiction_id" "uuid",
    "governing_jurisdiction_name" "text",
