CREATE TABLE IF NOT EXISTS "public"."entity_flags" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "entity_type" "text" NOT NULL,
    "entity_id" "uuid" NOT NULL,
    "flag_type" "text" NOT NULL,
    "alert_level" "text",
    "reason" "text",
    "active" boolean DEFAULT true NOT NULL,
    "raised_by" "uuid",
    "raised_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "resolved_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "hazard_class" "text",
    "resolved_by" "uuid",
    "client_request_id" "uuid"
);
COMMENT ON TABLE "public"."entity_flags" IS 'Org-scoped of-interest status (VOI/POI/LOI/trespass/welfare) keyed to a canonical entity. Replaces standalone vehicle_flags/person_flags/location_flags (retired in 0115 after 0114 backfill). Substantive flag detail stays org-scoped (Privacy Act).';
COMMENT ON COLUMN "public"."entity_flags"."hazard_class" IS 'When set, this flag is a health-and-safety warning and its existence (hazard class, severity, raising organisation contact) is visible platform-wide through get_safety_warnings; the reason stays with the raising organisation. NULL = ordinary org-scoped of-interest flag.';

CREATE TABLE IF NOT EXISTS "public"."entity_links" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "from_type" "text" NOT NULL,
    "from_id" "uuid" NOT NULL,
    "to_type" "text" NOT NULL,
    "to_id" "uuid" NOT NULL,
    "relationship" "text" NOT NULL,
    "evidence" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "active" boolean DEFAULT true NOT NULL,
    "starts_at" timestamp with time zone,
    "ends_at" timestamp with time zone,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."entity_links" IS 'Polymorphic relationship graph between canonical entities (vehicle/person/place/staff). Org-scoped. Generalises person_vehicle_links. Enables cross-entity intelligence (driver of a vehicle, trespass from a site, POI<->staff match) without merging records.';

CREATE TABLE IF NOT EXISTS "public"."event_context_snapshots" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "source_table" "text" NOT NULL,
    "source_event_id" "uuid" NOT NULL,
    "location_id" "uuid",
    "client_site_id" "uuid",
    "zone_id" "uuid",
    "checkpoint_id" "uuid",
    "module_key" "text",
    "service_agreement_id" "uuid",
    "provider_organization_id" "uuid",
    "client_organization_id" "uuid",
    "jurisdiction_organization_id" "uuid",
    "jurisdiction_rule_set_id" "uuid",
    "authority_snapshot" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "source_refs" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "captured_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."event_context_snapshots" IS 'Immutable future-write context: physical anchor fields are separate from module, agreement, jurisdiction, actor/authority, and source provenance. Historical backfill is intentionally a later reconciliation slice.';
COMMENT ON COLUMN "public"."event_context_snapshots"."authority_snapshot" IS 'Immutable JSON snapshot of the authority/actor decisions in force at event creation; not a live profile lookup.';
COMMENT ON COLUMN "public"."event_context_snapshots"."source_refs" IS 'External/source identifiers used to prove provenance without making mutable provider/person records the event anchor.';

CREATE TABLE IF NOT EXISTS "public"."evidence_items" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "module_key" "text" NOT NULL,
    "evidence_kind" "text" NOT NULL,
    "storage_path" "text",
    "captured_by_user_id" "uuid",
    "captured_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "sha256_hash" "text",
    "retention_days" integer,
    "is_court_ready" boolean DEFAULT false NOT NULL,
    "locked_at" timestamp with time zone,
    "retention_class" "text",
    "retention_until" timestamp with time zone,
    "retention_hold" boolean DEFAULT false NOT NULL,
    "retention_reason" "text",
    "location_event_id" "uuid",
    "cctv_import_id" "uuid"
);
COMMENT ON TABLE "public"."evidence_items" IS 'Shared evidence store across all modules. Vehicle, face, ID, document, audio, and note evidence.';
COMMENT ON COLUMN "public"."evidence_items"."sha256_hash" IS 'SHA-256 cryptographic digest of the raw evidence payload for court-ready integrity verification.';
COMMENT ON COLUMN "public"."evidence_items"."retention_days" IS 'Calculated retention window in days derived from retention_policies or module defaults.';
COMMENT ON COLUMN "public"."evidence_items"."is_court_ready" IS 'Whether this evidence item meets court-ready chain-of-custody standards (watermarked, hashed, time-stamped).';
COMMENT ON COLUMN "public"."evidence_items"."locked_at" IS 'Timestamp when the evidence record was sealed. Sealed records cannot be modified or purged before retention expiration.';
COMMENT ON COLUMN "public"."evidence_items"."location_event_id" IS 'Canonical physical event this evidence supports. Event context, not captured_by_user_id or organization_id alone, is the durable place provenance.';

