);

CREATE TABLE IF NOT EXISTS "public"."geo_source_registry" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "agency_id" "text" NOT NULL,
    "authority_class" "text" DEFAULT 'council'::"text" NOT NULL,
    "source_class" "text" DEFAULT 'arcgis_featureserver'::"text" NOT NULL,
    "base_url" "text" NOT NULL,
    "layer_id" integer DEFAULT 0 NOT NULL,
    "search_field" "text" NOT NULL,
    "place_kind" "text",
    "status" "text" DEFAULT 'provisional'::"text" NOT NULL,
    "last_tested_at" timestamp with time zone,
    "verified_by" "uuid",
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."geo_source_registry" IS 'Platform-level discovered geospatial endpoints (council ArcGIS, LINZ, DOC, NZTA). Bob discovers once, all orgs reuse. status = ENDPOINT verification only; polygon accuracy is decided by the per-zone_type validity/area gate + human review, not here.';
COMMENT ON COLUMN "public"."geo_source_registry"."status" IS 'Endpoint-verified state only (verified/provisional/stale/retired). NOT a claim that any returned polygon is the correct boundary for a place.';

CREATE TABLE IF NOT EXISTS "public"."geofence_boundary_history" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "entity_type" "text" NOT NULL,
    "entity_id" "uuid" NOT NULL,
    "boundary" "public"."geometry",
    "boundary_source" "text",
    "verification_state" "text",
    "verified_by" "uuid",
    "verified_at" timestamp with time zone,
    "changed_by" "uuid",
    "changed_via" "text" NOT NULL,
    "change_reason" "text",
    "version" integer DEFAULT 1 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."geofence_boundary_history" IS 'Boundary versioning history for all geofence-bearing entities (org jurisdiction, zone, site). Q4 ruling: ALL boundaries versioned uniformly, any origin. Records verification state, boundary source, and actor. Phase 4 geofence redesign (#226).';

CREATE TABLE IF NOT EXISTS "public"."homeless_claims" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "plate_number" "text" NOT NULL,
    "observation_id" "uuid",
    "claimed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "claimed_by_officer_id" "uuid" NOT NULL,
    "claim_basis" "text",
    "status" "text" DEFAULT 'pending_review'::"text" NOT NULL,
    "reviewed_by" "uuid",
    "reviewed_at" timestamp with time zone,
    "review_notes" "text",
    "support_agency" "text",
    "support_contact" "text",
    "referral_notes" "text",
    "evidence_refs" "jsonb",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."homeless_claims" IS 'Mandatory verification workflow for a homelessness claim made at point of contact. status=pending_review holds enforcement (does not silently waive it) until an admin/welfare-authorised reviewer confirms or declines -- both outcomes are permanent on the record. Confirming does NOT change the compliance verdict; it sets observations.enforcement_exempt separately (see section 4) so the true rule outcome is never falsified. support_agency/contact model a REFERRAL (LGA 2002 s.11A wellbeing coordination), not a housing commitment -- councils do not carry a statutory duty to house (MSD/HUD do). #73/#74.';

