    "service_period_start" "date",
    "service_period_end" "date",
    "sent_at" timestamp with time zone,
    "paid_at" timestamp with time zone
);
COMMENT ON TABLE "public"."invoices" IS 'Invoice header records for client billing. Linked to service agreements.';

CREATE TABLE IF NOT EXISTS "public"."job_party_interactions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "dispatch_job_id" "uuid" NOT NULL,
    "noise_assessment_id" "uuid",
    "shift_stop_id" "uuid",
    "party_role" "text" NOT NULL,
    "mode" "text" NOT NULL,
    "occurred_at" timestamp with time zone NOT NULL,
