    "protected" boolean DEFAULT true NOT NULL,
    "officer_user_id" "uuid" NOT NULL,
    "client_request_id" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."job_party_interactions" IS 'Recorded contact with a party to a dispatch job (complainant, occupant, witness, Police). Linked to the job, the assessment and the stop so the client report reflects exactly what happened. Identity lives in dispatch_job_protected_parties, never here.';

CREATE TABLE IF NOT EXISTS "public"."jurisdiction_rule_sets" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
