    "reason" "text",
    "approved_by" "uuid",
    "approved_at" timestamp with time zone,
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "client_event_id" "uuid",
    "decision_notes" "text",
    "branch_reviewed_by" "uuid",
    "branch_reviewed_at" timestamp with time zone,
    "branch_review_notes" "text",
    "branch_reviewed_organization_id" "uuid"
);
COMMENT ON TABLE "public"."leave_requests" IS 'Staff leave requests. Approved leave is visible in the roster planner to prevent scheduling conflicts.';

CREATE TABLE IF NOT EXISTS "public"."location_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "client_site_id" "uuid",
    "zone_id" "uuid",
    "checkpoint_id" "uuid",
    "event_type" "text" NOT NULL,
    "module_key" "text",
    "occurred_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "status" "text",
    "source" "text",
    "external_ref" "text",
    "payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "observed_entity_type" "text",
    "observed_entity_id" "uuid",
    "canonical_place_id" "uuid",
    "canonical_person_id" "uuid",
    "distance_km" numeric(10,3)
);
COMMENT ON TABLE "public"."location_events" IS 'Unified per-place event stream. Every module writes typed events against a Site (client_site_id) XOR Zone (zone_id), optional checkpoint. Detail may stay in module tables (dual-write) referenced via external_ref/payload.';
COMMENT ON COLUMN "public"."location_events"."observed_entity_type" IS 'What/who this event is about: vehicle (canonical_vehicles) | person (persons) | place (client_sites/location_zones) | staff (user_profiles). NULL = a pure place event. Detail lives in payload.';
COMMENT ON COLUMN "public"."location_events"."observed_entity_id" IS 'Id of the observed entity, interpreted per observed_entity_type. Polymorphic (no FK) so one stream serves all entity kinds; integrity is by convention + Bob reasoning.';
COMMENT ON COLUMN "public"."location_events"."distance_km" IS 'Real recorded travel distance for this patrol visit (officer-recorded, e.g. from a patrol-log import or future manual/odometer entry). Not a GPS estimate - see shift_stops.travel_distance_metres for the live patrol engine''s pre-visit estimate.';

CREATE TABLE IF NOT EXISTS "public"."location_events_superseded" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "provider_organization_id" "uuid" NOT NULL,
    "client_organization_id" "uuid" NOT NULL,
    "location_event_id" "uuid" NOT NULL,
    "external_ref" "text" NOT NULL,
    "canonical_location_event_id" "uuid" NOT NULL,
    "canonical_external_ref" "text" NOT NULL,
    "reason_code" "text" NOT NULL,
    "batch_id" "uuid" NOT NULL,
    "event_snapshot" "jsonb" NOT NULL,
    "superseded_by" "uuid" NOT NULL,
    "superseded_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL
);
COMMENT ON TABLE "public"."location_events_superseded" IS 'Append-only archive of imported patrol events removed as duplicates of a canonical source record. Holds the full original row, the canonical record it duplicated, the batch and the actor.';

CREATE TABLE IF NOT EXISTS "public"."location_module_assignments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "location_id" "uuid" NOT NULL,
    "module_key" "text" NOT NULL,
    "service_agreement_id" "uuid" NOT NULL,
    "enabled" boolean DEFAULT true NOT NULL,
    "effective_from" "date" DEFAULT CURRENT_DATE NOT NULL,
    "effective_to" "date",
    "rule_set_ref" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid"
);

CREATE TABLE IF NOT EXISTS "public"."location_notes" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "site_id" "uuid",
    "zone_id" "uuid",
    "organization_id" "uuid" NOT NULL,
    "body" "text" NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."location_notes" IS 'Org-private notes on a site or zone (Tier 3 visibility, epic #179). RLS enforces that only the owning org can read or write its own notes. No override possible. Notes from different orgs at the same location are completely isolated.';

CREATE TABLE IF NOT EXISTS "public"."location_zones" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "nightly_limit_consecutive" integer,
    "nightly_limit_monthly" integer,
    "scv_required" boolean DEFAULT false NOT NULL,
    "jurisdiction_rule_set_id" "uuid",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "boundary" "public"."geometry"(MultiPolygon,4326),
    "center_point" "public"."geometry"(Point,4326),
    "radius_meters" integer,
    "zone_type" "text" DEFAULT 'freedom_camping'::"text" NOT NULL,
    "module_key" "text" DEFAULT 'freedom_camping'::"text" NOT NULL,
    "bylaw_clause" "text",
    "bylaw_source_url" "text",
    "is_active" boolean DEFAULT true NOT NULL,
    "repeat_stay_window_nights" integer,
    "enforcement_workflow_override" "text",
    "repeat_stay_radius_m" integer,
    "onsite_profile" "text" DEFAULT 'boundary'::"text" NOT NULL,
    "active_schedule" "jsonb",
    "rule_overrides" "jsonb",
    "is_adhoc" boolean DEFAULT false NOT NULL,
    "parking_time_limit_minutes" integer,
    "parking_disabled_multiplier" numeric DEFAULT 2 NOT NULL,
    "parking_signage_photo_url" "text",
    "parking_limit_source" "text",
    "parking_limit_set_by" "uuid",
    "parking_limit_set_at" timestamp with time zone,
    "external_ref" "text",
    "internal_client_ref" "text",
    "despatch_zone_code" "text",
    "location_id" "uuid" NOT NULL,
    "rule_type" "text" DEFAULT 'overnight_limited'::"text" NOT NULL,
    "boundary_status" "text" DEFAULT 'authoritative'::"text" NOT NULL,
    "scv_exempts_restriction" boolean DEFAULT true NOT NULL,
    "boundary_verification" "text" DEFAULT 'unverified'::"text" NOT NULL,
    "boundary_verified_by" "uuid",
    "boundary_verified_at" timestamp with time zone,
    "configuration_version" integer DEFAULT 1 NOT NULL,
    "parent_zone_id" "uuid",
    "is_verification_point" boolean DEFAULT false NOT NULL
);
COMMENT ON TABLE "public"."location_zones" IS 'Canonical Zone table. A Zone is a SIBLING of a Site (Org -> Site XOR Zone; see docs/LOCATION_HIERARCHY.md), so site_id and boundary are OPTIONAL: a Zone may stand alone and may be imported before its geometry is set (geometry applied later via the governed geofence step). The 0100 site/boundary NOT-NULL guards were removed in 0111 to match the 0108 sibling model.';
COMMENT ON COLUMN "public"."location_zones"."boundary" IS 'PostGIS MultiPolygon boundary (EPSG:4326). Widened from Polygon in 0279 (Q7 ruling). Used for GPS-to-zone detection and map rendering.';
COMMENT ON COLUMN "public"."location_zones"."center_point" IS 'Centroid of the zone polygon. Used for fast proximity queries.';
COMMENT ON COLUMN "public"."location_zones"."radius_meters" IS 'For circular zones: radius in metres from center_point. NULL for polygon zones.';
COMMENT ON COLUMN "public"."location_zones"."zone_type" IS 'Enforcement type. Determines which compliance rules and notice templates apply.';
COMMENT ON COLUMN "public"."location_zones"."repeat_stay_window_nights" IS 'Repeat-stay rule window in nights: a vehicle may not return within the radius for this many nights. NULL = rule disabled.';
COMMENT ON COLUMN "public"."location_zones"."enforcement_workflow_override" IS 'Per-zone enforcement workflow override. NULL = inherit the org default.';
COMMENT ON COLUMN "public"."location_zones"."onsite_profile" IS 'On-site activation profile: boundary (patrol/parking/freedom/static = polygon + onsite radius) or approach_10m (alarm/noise/biosecurity/smoke = 10 m pre-attendance ring).';
COMMENT ON COLUMN "public"."location_zones"."active_schedule" IS 'Optional time-of-day/day schedule (jsonb) when this module geofence is active. Lets the same area be e.g. freedom_camping overnight and parking 08:00-20:00 as two rows.';
COMMENT ON COLUMN "public"."location_zones"."rule_overrides" IS 'Optional site/geofence-level rule overrides (jsonb) applied on top of the jurisdiction (council, module) ruleset. Override wins where present.';
COMMENT ON COLUMN "public"."location_zones"."is_adhoc" IS 'True for ad-hoc geofences created at incident time (noise/biosecurity/smoke/alarm), distinct from pre-mapped module geofences.';
COMMENT ON COLUMN "public"."location_zones"."parking_time_limit_minutes" IS 'Posted parking time limit in minutes (e.g. P60=60, P120=120, P150=150, P90=90). Null = metered / no fixed limit. Editable in the zone Rules editor; settable from a Bob-read signage photo.';
COMMENT ON COLUMN "public"."location_zones"."parking_disabled_multiplier" IS 'Multiplier applied to the time limit for disabled (mobility) parking. Default 2 = double the posted time. Adjustable per zone.';
COMMENT ON COLUMN "public"."location_zones"."parking_signage_photo_url" IS 'Storage path/URL of the photographed time-limit sign that is the legal authority for the limit (court-defensible provenance).';
COMMENT ON COLUMN "public"."location_zones"."parking_limit_source" IS 'Provenance of the time limit: bob_signage (OCR + human-approved), manual (admin set), rfp_seed (seeded from the contract).';
COMMENT ON COLUMN "public"."location_zones"."despatch_zone_code" IS 'Operational patrol-route despatch code (e.g. 587 Nelson, 586 Richmond, 584 Stoke, 583 Motueka). The pivot that joins a billable patrol/alarm visit (Despatch Zone in the billing feeds) to its patrol route zone. Patrol route zones use zone_type=''patrol_route''; nesting/support relationships use parent_zone_id. text because these are external identifiers, not arithmetic values.';
COMMENT ON COLUMN "public"."location_zones"."location_id" IS 'FK to the Location ("house") this zone is a facet of. Nullable during migration; once backfilled, every zone belongs to exactly one house. The zone is the area facet of the house.';
COMMENT ON COLUMN "public"."location_zones"."rule_type" IS 'Compliance rule class. Act-aligned values (Freedom Camping Act 2011): prohibited (no camping, no SCV exception), restricted (SCV-only; see scv_exempts_restriction), unrestricted (no restriction; night-limit columns may still apply as a bylaw condition). Legacy values from 0179 (overnight_limited, day_visit_only) remain valid during transition -- reclassify per zone via the actual council bylaw (propose_freedom_camping_org_strategy), not by guessing. #74.';
COMMENT ON COLUMN "public"."location_zones"."boundary_status" IS 'Fence provenance: authoritative (LINZ parcel polygon, or a confirmed Google-backed polygon) or provisional (point-buffer created when no polygon was found, awaiting a human to draw the real boundary). Partial index surfaces the review queue: WHERE boundary_status = ''provisional''. Mirrors client_sites.boundary_status (0133).';
COMMENT ON COLUMN "public"."location_zones"."scv_exempts_restriction" IS 'For rule_type=restricted zones: whether holding a valid SCV certificate exempts a vehicle from the restriction (the normal Freedom Camping Act reading). Default true. #74.';
COMMENT ON COLUMN "public"."location_zones"."parent_zone_id" IS 'Optional same-organisation parent zone for reporting/attribution (e.g. a named forest sub-block''s parent estate). Never crosses organization_id. Not used by resolve_context/geofence containment - see docs/canon/LOCATION_HOUSE_MODEL.md "Ruling correction 2026-09-23".';
COMMENT ON COLUMN "public"."location_zones"."is_verification_point" IS 'Officer-confirmed reference zone, not a replacement perimeter or a source of regulatory rules.';

CREATE TABLE IF NOT EXISTS "public"."locations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "address" "text",
    "address_match_key" "text",
    "suburb" "text",
    "postcode" "text",
    "notes" "text",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "client_request_id" "uuid",
    "canonical_place_id" "uuid" NOT NULL
);
COMMENT ON TABLE "public"."locations" IS 'An organisation''s house: its link to one registry place (canonical_place_id). Site and zone facets hang off the house as siblings.';
COMMENT ON COLUMN "public"."locations"."organization_id" IS 'The CLIENT org that owns this physical place (place-axis ownership). A provider may patrol this place only when an active service_agreement authorises the cross-org link.';
COMMENT ON COLUMN "public"."locations"."name" IS 'Human-readable name for the house / location (e.g. "12 Lowburn Terrace").';
COMMENT ON COLUMN "public"."locations"."address" IS 'Full street address of the location.';
COMMENT ON COLUMN "public"."locations"."address_match_key" IS 'Normalised address key for deduplication and import matching (lowercase, stripped punctuation).';
COMMENT ON COLUMN "public"."locations"."suburb" IS 'Suburb or locality name.';
COMMENT ON COLUMN "public"."locations"."postcode" IS 'NZ postcode.';
COMMENT ON COLUMN "public"."locations"."notes" IS 'Free-text notes about the location (access instructions, hazards, etc.).';
COMMENT ON COLUMN "public"."locations"."created_by" IS 'User who created this location record.';
COMMENT ON COLUMN "public"."locations"."canonical_place_id" IS 'The registry place this house is a link to. Assigned by trigger from the address key (site) or the house id (zone).';

CREATE TABLE IF NOT EXISTS "public"."module_catalog" (
    "module_key" "text" NOT NULL,
    "base_price" numeric(12,2) DEFAULT 0 NOT NULL,
    "per_seat_price" numeric(12,2) DEFAULT 0 NOT NULL,
    "per_site_price" numeric(12,2) DEFAULT 0 NOT NULL,
    "billing_period" "text" DEFAULT 'monthly'::"text" NOT NULL,
    "currency" "text" DEFAULT 'NZD'::"text" NOT NULL,
    "active" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."module_catalog" IS 'Layer 1 (owner->provider) platform price list: owner-set base + per-seat + per-site price per module_key. No organization_id (applies to all providers; overridden per subscription in org_module_subscriptions). Which modules are sellable is defined by moduleManifest.ts (sellable:true), not here; this table carries only the price. Grand_master write; all authenticated read.';

CREATE TABLE IF NOT EXISTS "public"."module_dependencies" (
    "module_key" "text" NOT NULL,
    "depends_on_module_key" "text" NOT NULL,
    "reason" "text" NOT NULL
);

CREATE TABLE IF NOT EXISTS "public"."module_rule_sets" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "module_key" "text" NOT NULL,
    "name" "text" NOT NULL,
    "evidence_requirements" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "approval_policy" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "report_template_code" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."module_rule_sets" IS 'Operational rules per module: evidence requirements, approval policy, report templates.';

CREATE TABLE IF NOT EXISTS "public"."monthly_report_packs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "service_agreement_id" "uuid" NOT NULL,
    "template_code" "text" NOT NULL,
    "period_start" "date" NOT NULL,
    "period_end" "date" NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "data" "jsonb",
    "pdf_path" "text",
    "generated_at" timestamp with time zone,
    "generated_by" "uuid",
    "sent_at" timestamp with time zone,
    "sent_to" "text",
    "delivery_error" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "pdf_mime_type" "text",
    "pdf_sha256" "text",
    "pdf_renderer_version" "text",
    "editorial" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "reviewed_at" timestamp with time zone,
    "reviewed_by" "uuid",
    "published_at" timestamp with time zone,
    "published_by" "uuid",
    "delivery_channel" "text",
    "report_kind" "text" DEFAULT 'monthly'::"text" NOT NULL,
    "report_scope" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "delivery_attempt_id" "uuid",
    "delivery_started_at" timestamp with time zone,
    "delivery_recipient" "text",
    "pdf_source_updated_at" timestamp with time zone,
    "activity_lines" "jsonb"
);
COMMENT ON TABLE "public"."monthly_report_packs" IS 'Generated monthly report packs per service agreement. One row per period+template, with a JSONB data snapshot, PDF path, and delivery log. Feeds the client portal (3.3).';
COMMENT ON COLUMN "public"."monthly_report_packs"."pdf_path" IS 'Private bob-uploads storage path for the generated client report pack PDF.';
COMMENT ON COLUMN "public"."monthly_report_packs"."pdf_sha256" IS 'SHA-256 checksum of the generated report pack PDF bytes.';
COMMENT ON COLUMN "public"."monthly_report_packs"."pdf_renderer_version" IS 'Renderer identifier used to produce the report pack PDF.';
COMMENT ON COLUMN "public"."monthly_report_packs"."editorial" IS 'Provider-authored client-facing title, summary, notes, and follow-up. Source-derived report data remains in data and is not manually editable.';
COMMENT ON COLUMN "public"."monthly_report_packs"."reviewed_at" IS 'When a provider administrator last saved the client-facing review.';
COMMENT ON COLUMN "public"."monthly_report_packs"."reviewed_by" IS 'Provider administrator who last saved the client-facing review.';
COMMENT ON COLUMN "public"."monthly_report_packs"."published_at" IS 'When the reviewed pack was explicitly released for client delivery.';
COMMENT ON COLUMN "public"."monthly_report_packs"."published_by" IS 'Provider administrator who explicitly released the reviewed pack.';
COMMENT ON COLUMN "public"."monthly_report_packs"."delivery_channel" IS 'portal when an active client login can consume live reporting; email otherwise.';
COMMENT ON COLUMN "public"."monthly_report_packs"."report_kind" IS 'monthly for scheduled template packs; custom for an administrator-selected agreement scope.';
COMMENT ON COLUMN "public"."monthly_report_packs"."report_scope" IS 'Exact generation-time scope for a custom report. IDs are OR-matched within a dimension and AND-matched across populated dimensions.';
COMMENT ON COLUMN "public"."monthly_report_packs"."delivery_attempt_id" IS 'Opaque lease identifying the single email-delivery attempt currently allowed to update this pack.';
COMMENT ON COLUMN "public"."monthly_report_packs"."delivery_started_at" IS 'When email delivery was atomically claimed. An uncertain claim requires explicit provider review/republication before retry.';
COMMENT ON COLUMN "public"."monthly_report_packs"."delivery_recipient" IS 'Active primary client contact email bound inside the current delivery claim transaction.';
COMMENT ON COLUMN "public"."monthly_report_packs"."pdf_source_updated_at" IS 'Pack updated_at value whose content the current PDF renders. Equality means current; inequality means retained but stale until replacement.';
COMMENT ON COLUMN "public"."monthly_report_packs"."activity_lines" IS 'Frozen itemised site activity for a monthly report pack: {version, lines[], notItemised}. Each line is one client-reportable entry with its place, date and time, category, recorded narrative and photo references (see the activityReport key of data). Kept out of data so report lists do not carry it; read it for one pack at a time.';

CREATE TABLE IF NOT EXISTS "public"."noise_assessment_evidence" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
