);
COMMENT ON TABLE "public"."notice_print_authorizations" IS 'Server-only idempotency and receipt ledger for typed-name notice print authorization. Browser roles have no direct table access.';

CREATE TABLE IF NOT EXISTS "public"."notice_templates" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
