    "notice_type" "text" NOT NULL,
    "version" integer DEFAULT 1 NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "issuing_authority" "text",
    "authorising_act" "text" DEFAULT 'Freedom Camping Act 2011'::"text" NOT NULL,
    "authorising_section" "text",
    "bylaw_reference" "text",
    "body_html" "text" DEFAULT ''::"text" NOT NULL,
    "fine_amount" numeric(10,2),
    "payment_url" "text",
    "payment_deadline_days" integer DEFAULT 28 NOT NULL,
    "objections_email" "text",
    "objections_address" "text",
    "objections_deadline_days" integer DEFAULT 28 NOT NULL,
