COMMENT ON TABLE "public"."nzta_access_reviews" IS 'Quarterly review of who holds NZTA register access, with a snapshot of holders and their training status.';

CREATE TABLE IF NOT EXISTS "public"."nzta_register_access_log" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
