);
COMMENT ON TABLE "public"."nzta_register_access_log" IS 'Append-only log of purpose-stated reveals of NZTA person<->vehicle links. A reveal opens a short window for that user and subject only.';

CREATE TABLE IF NOT EXISTS "public"."nzta_register_lookups" (
