COMMENT ON TABLE "public"."nzta_register_lookups" IS 'One row per Motochek/MVR lookup: date, plate/VIN, individual Motochek user, Gazette purpose, explanation, supporting links and outcome (NZTA T&C 13-16). Written only through record_nzta_register_lookup.';

CREATE TABLE IF NOT EXISTS "public"."obligation_proof_artifacts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "obligation_id" "uuid" NOT NULL,
    "artifact_type" "text" NOT NULL,
    "source_table" "text",
    "source_record_id" "uuid",
    "captured_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "notes" "text",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "client_request_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "withdrawn_at" timestamp with time zone,
    "withdrawn_by" "uuid",
    "withdrawal_reason" "text"
);
COMMENT ON TABLE "public"."obligation_proof_artifacts" IS 'Governed links between reviewed source records and contract obligations. Browser access is RPC-only; withdrawn links preserve correction history.';
COMMENT ON COLUMN "public"."obligation_proof_artifacts"."client_request_id" IS 'Caller-generated replay key. Unique within the provider organization.';
COMMENT ON COLUMN "public"."obligation_proof_artifacts"."status" IS 'Append-preserving review state. Withdrawn links remain available for chain-of-custody review.';
COMMENT ON COLUMN "public"."obligation_proof_artifacts"."metadata" IS 'Source-time snapshot used to explain what was reviewed without treating the link as the source record.';

CREATE TABLE IF NOT EXISTS "public"."observation_frozen_fields" (
    "id" bigint GENERATED ALWAYS AS IDENTITY NOT NULL,
    "table_name" "text" NOT NULL,
    "column_name" "text" NOT NULL,
    "reason" "text" NOT NULL,
    "ratified_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "ratified_by" "text" NOT NULL
);
COMMENT ON TABLE "public"."observation_frozen_fields" IS 'Canonical contract: columns frozen at observation lock. Authoritative for Bob queries, Atlas drift-check, and trigger generation. Append-only by governance rule — no UPDATE/DELETE. A new Part 0 ruling is required to add or remove a row. Issue #315.';
COMMENT ON COLUMN "public"."observation_frozen_fields"."table_name" IS 'Plain table name (e.g. ''observations''). No schema prefix.';
COMMENT ON COLUMN "public"."observation_frozen_fields"."column_name" IS 'Column name as it appears in information_schema.columns.';
COMMENT ON COLUMN "public"."observation_frozen_fields"."reason" IS 'Why this field is frozen — the evidential or legal basis.';
COMMENT ON COLUMN "public"."observation_frozen_fields"."ratified_at" IS 'Timestamp of the owner ruling that added this row.';
COMMENT ON COLUMN "public"."observation_frozen_fields"."ratified_by" IS 'Name of the person who ratified this row (owner-authored). Plain text — not a FK to user_profiles (owner may not be a platform user).';

CREATE TABLE IF NOT EXISTS "public"."observation_person_mentions" (
