    "reviewed_by" "uuid",
    "reviewed_at" timestamp with time zone,
    "review_notes" "text"
);
COMMENT ON TABLE "public"."observation_person_mentions" IS 'People mentioned at a sighting. Unconfirmed until an administrator confirms a verified person; observations.person_record_id remains the identity of record.';

CREATE TABLE IF NOT EXISTS "public"."observation_supporting_evidence" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "observation_id" "uuid",
    "overnight_session_id" "uuid",
