    "config_value" integer NOT NULL,
    "zone_type" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."org_geofence_config" IS 'Per-org geofence configuration (Q8 ruling). Keys: site_provisional_radius_m (default 50), zone_provisional_radius_m (default 100), checkpoint_radius_m (default 5). Optional zone_type for per-zone-type overrides.';

CREATE TABLE IF NOT EXISTS "public"."org_jurisdiction_geom_stages" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "geom" "public"."geometry"(MultiPolygon,4326),
    "part_count" integer DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "expires_at" timestamp with time zone DEFAULT ("now"() + '01:00:00'::interval) NOT NULL
);
COMMENT ON TABLE "public"."org_jurisdiction_geom_stages" IS 'Service-only scratch accumulator for unioning large organisation jurisdictions one part per request (stage_org_jurisdiction_part -> commit_org_jurisdiction_stage). Not a boundary of record; rows are deleted on commit and expire after an hour.';

CREATE TABLE IF NOT EXISTS "public"."org_module_subscriptions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "module_key" "text" NOT NULL,
    "base_price" numeric(12,2),
    "per_seat_price" numeric(12,2),
    "per_site_price" numeric(12,2),
    "discount_pct" numeric(5,2) DEFAULT 0 NOT NULL,
    "billing_period" "text",
    "currency" "text",
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "started_at" "date" DEFAULT CURRENT_DATE NOT NULL,
    "ended_at" "date",
    "effective_from" "date",
    "effective_to" "date",
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    "updated_by" "uuid"
);
COMMENT ON TABLE "public"."org_module_subscriptions" IS 'Layer 1 (owner->provider) subscription lines: what each provider org is actually charged per module (per-provider price overrides + discount applied after the resolved price, else inherits module_catalog). effective_from/to version price changes. Aligned to organization_modules enablement. Grand_master write; provider reads its own.';

CREATE TABLE IF NOT EXISTS "public"."org_printer_settings" (
