    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);

CREATE TABLE IF NOT EXISTS "public"."organizations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "name" "text" NOT NULL,
    "organization_type" "text" NOT NULL,
    "parent_organization_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "active" boolean DEFAULT true NOT NULL,
    "contact_email" "text",
    "contact_phone" "text",
    "billing_email" "text",
    "billing_address" "text",
    "account_notes" "text",
    "enforcement_workflow_mode" "text" DEFAULT 'officer_direct'::"text" NOT NULL,
    "organization_level" smallint,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "logo_url" "text",
    "jurisdiction_geom" "public"."geometry"(MultiPolygon,4326),
    "external_refs" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "company_registration_number" "text",
    "nzbn" "text",
    "corporate_status" "text",
    "corporate_status_as_of" timestamp with time zone,
    "corporate_profile_verified_by" "uuid",
    "corporate_profile_verified_at" timestamp with time zone,
    "nzbn_entity_type" "text",
    "discoverable" boolean DEFAULT false NOT NULL,
    "jurisdiction_verification" "text" DEFAULT 'unverified'::"text" NOT NULL,
    "jurisdiction_verified_by" "uuid",
    "jurisdiction_verified_at" timestamp with time zone,
    "client_request_id" "uuid",
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "account_owner_user_id" "uuid",
    "legal_name" "text",
    "trading_name" "text",
    "registered_office" "text",
    "postal_address" "text",
    "website_url" "text",
    "corporate_profile_source" "text",
    "corporate_profile_verification_status" "text" DEFAULT 'unverified'::"text" NOT NULL
);
COMMENT ON TABLE "public"."organizations" IS 'Tenancy anchor. Supports platform owners, service providers, branches, clients, contractors, government entities, and private enterprises.';
COMMENT ON COLUMN "public"."organizations"."active" IS 'CRM account status. Inactive accounts remain visible for audit/history but are excluded from active operations.';
COMMENT ON COLUMN "public"."organizations"."contact_email" IS 'Primary organisation-level contact email used by CRM and onboarding workflows.';
COMMENT ON COLUMN "public"."organizations"."contact_phone" IS 'Primary organisation-level contact phone used by CRM and operational handoff.';
COMMENT ON COLUMN "public"."organizations"."billing_email" IS 'Billing contact email for finance/invoicing workflows.';
COMMENT ON COLUMN "public"."organizations"."billing_address" IS 'Billing address for finance/invoicing workflows.';
COMMENT ON COLUMN "public"."organizations"."account_notes" IS 'General CRM account notes visible to admins and masters.';
COMMENT ON COLUMN "public"."organizations"."enforcement_workflow_mode" IS 'Org default enforcement workflow: admin_first | officer_direct | hybrid. Zones may override via location_zones.enforcement_workflow_override.';
COMMENT ON COLUMN "public"."organizations"."jurisdiction_geom" IS 'Org operating boundary (service provider = all operated districts as one MultiPolygon; council = its district). Null for private enterprise. Layer 1/2 of geofence resolution.';
COMMENT ON COLUMN "public"."organizations"."external_refs" IS 'Generic external system reference IDs. Keys are system names (wilsar, deputy, greentree, d365, etc.), values are objects of field->value pairs.';
COMMENT ON COLUMN "public"."organizations"."company_registration_number" IS 'NZ Companies Office registration number. Distinct from nzbn (New Zealand Business Number), which some entities have without being a registered company.';
COMMENT ON COLUMN "public"."organizations"."nzbn" IS 'New Zealand Business Number — the stable structural anchor for corporate entity resolution (names are mutable; the NZBN is not).';
COMMENT ON COLUMN "public"."organizations"."corporate_status" IS 'Registry-reported standing at corporate_status_as_of. registered = active/trade-legal; removed/in_liquidation/receivership must be surfaced to the approver, never silently treated as active.';
COMMENT ON COLUMN "public"."organizations"."corporate_status_as_of" IS 'Timestamp the corporate_status was last confirmed against the registry. Registry data can be up to a month stale — never presented as real-time.';
COMMENT ON COLUMN "public"."organizations"."corporate_profile_verified_by" IS 'Human who approved the corporate profile (registration number + officers) as correct. NULL means Bob resolved it but no human has confirmed it yet.';
COMMENT ON COLUMN "public"."organizations"."corporate_profile_verified_at" IS 'When a human approved the corporate profile. NULL = unverified (registry-resolved only, not human-confirmed).';
COMMENT ON COLUMN "public"."organizations"."nzbn_entity_type" IS 'NZBN entity type: company | sole_trader | partnership | trust | other. Drives privacy masking -- non-company types have personal data masked by default in org discovery (Privacy Act, design doc 6.2). Populated from the NZBN API lookup (W3) or manual entry.';
COMMENT ON COLUMN "public"."organizations"."discoverable" IS 'Opt-in to org-to-org discovery (design doc 6.4). When false (default), the org is only findable by strong identifier (NZBN / exact name) and personal data is masked for non-company entity types. Iron Eagle (grand_master) sees all orgs regardless.';
COMMENT ON COLUMN "public"."organizations"."account_owner_user_id" IS 'Internal user/relationship manager owning this account.';

CREATE TABLE IF NOT EXISTS "public"."overtime_offers" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "roster_slot_id" "uuid" NOT NULL,
    "staff_id" "uuid" NOT NULL,
    "offer_round" integer DEFAULT 1 NOT NULL,
    "seniority_position" integer NOT NULL,
    "status" "text" DEFAULT 'offered'::"text" NOT NULL,
    "expires_at" timestamp with time zone NOT NULL,
    "responded_at" timestamp with time zone,
    "decline_reason" "text",
    "client_request_id" "uuid" NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);

CREATE TABLE IF NOT EXISTS "public"."parking_chalk_records" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "plate" "text" NOT NULL,
    "chalked_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "return_by" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "officer_id" "uuid",
    "officer_name" "text",
    "site_id" "uuid",
    "location_name" "text",
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "photo_url" "text",
    "infringement_number" "text",
    "notes" "text",
    "resolved_at" timestamp with time zone,
    "bob_classification" "text",
    "bob_confidence" real,
    "client_site_id" "uuid",
    "embedding" "public"."vector"(384),
    "embedding_quality" double precision,
    "movement_detected" boolean,
    "movement_similarity" double precision,
    "zone_id" "uuid",
    "is_disabled_bay" boolean,
    "road_marking_detected" "text",
    "sign_time_limit_minutes" integer,
    "sign_confidence" double precision,
    "effective_time_limit_minutes" integer,
    "inference_provider" "text",
    "vehicle_make" "text",
    "vehicle_model" "text",
    "vehicle_colour" "text",
    "rego_status" "text",
    "rego_expiry" "date",
    "wof_status" "text",
    "wof_expiry" "date",
    "cof_status" "text",
    "cof_expiry" "date",
    "vehicle_compliance_flags" "jsonb",
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "photo_urls" "jsonb" DEFAULT '[]'::"jsonb",
    "geofence_context" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "canonical_vehicle_id" "uuid"
);
COMMENT ON TABLE "public"."parking_chalk_records" IS 'Parking chalk pass records. Tracks tyre marks, return times, and overstay status.';
COMMENT ON COLUMN "public"."parking_chalk_records"."bob_classification" IS 'Bob AI classification result for parking violation detection from photo evidence';
COMMENT ON COLUMN "public"."parking_chalk_records"."bob_confidence" IS 'Bob AI confidence score (0-100) for the classification result';
COMMENT ON COLUMN "public"."parking_chalk_records"."client_site_id" IS 'Canonical site anchor (client_sites.id). Populated when the officer selects a known site during chalk recording. Nullable — free-text location_name remains for ad-hoc locations without a registered site.';
COMMENT ON COLUMN "public"."parking_chalk_records"."embedding" IS '384D MobileNetV3 embedding (pgvector). Used for movement detection via cosine similarity between first-pass and return-pass scans of the same vehicle.';
COMMENT ON COLUMN "public"."parking_chalk_records"."embedding_quality" IS 'Quality score (0–1) of the embedding extraction. Low values indicate poor photo quality or obstructed view.';
COMMENT ON COLUMN "public"."parking_chalk_records"."movement_detected" IS 'Whether the vehicle moved between scans. true = moved (not overstaying), false = stationary, null = not yet checked.';
COMMENT ON COLUMN "public"."parking_chalk_records"."movement_similarity" IS 'Cosine similarity (0–1) between first-pass and return-pass embeddings. Lower values suggest the vehicle moved.';
COMMENT ON COLUMN "public"."parking_chalk_records"."zone_id" IS 'Geofence anchor — the location_zones row the vehicle was parked in at scan time. Used for zone-specific time limits and repeat-offender queries.';
COMMENT ON COLUMN "public"."parking_chalk_records"."is_disabled_bay" IS 'Whether the parking bay is a designated disabled bay, detected from road markings or signage by the inference pipeline.';
COMMENT ON COLUMN "public"."parking_chalk_records"."road_marking_detected" IS 'Road marking classification from inference: yellow_lines, disabled_bay, standard, or unknown.';
COMMENT ON COLUMN "public"."parking_chalk_records"."sign_time_limit_minutes" IS 'Parking time limit in minutes extracted from signage via OCR. Null if no sign detected or OCR failed.';
COMMENT ON COLUMN "public"."parking_chalk_records"."sign_confidence" IS 'Confidence score (0–1) of the signage OCR time-limit extraction.';
COMMENT ON COLUMN "public"."parking_chalk_records"."effective_time_limit_minutes" IS 'Effective time limit applied to this record. Resolved by priority: sign OCR > zone default > org default (parking_module_config.default_time_limit_minutes).';
COMMENT ON COLUMN "public"."parking_chalk_records"."inference_provider" IS 'Which inference provider produced the results: e.g. "local" (on-device ONNX) or "classify_photo" (server-side pipeline).';
COMMENT ON COLUMN "public"."parking_chalk_records"."vehicle_make" IS 'Vehicle make (e.g. Toyota, Ford) as detected by the inference pipeline.';
COMMENT ON COLUMN "public"."parking_chalk_records"."vehicle_model" IS 'Vehicle model (e.g. Corolla, Ranger) as detected by the inference pipeline.';
COMMENT ON COLUMN "public"."parking_chalk_records"."vehicle_colour" IS 'Vehicle colour as detected by the inference pipeline. Stored as free text to accommodate multi-tone descriptions.';
COMMENT ON COLUMN "public"."parking_chalk_records"."rego_status" IS 'Registration status at time of chalk: current, expired, unknown.';
COMMENT ON COLUMN "public"."parking_chalk_records"."wof_status" IS 'Warrant of Fitness status at time of chalk: current, expired, unknown.';
COMMENT ON COLUMN "public"."parking_chalk_records"."cof_status" IS 'Certificate of Fitness status at time of chalk: current, expired, unknown.';
COMMENT ON COLUMN "public"."parking_chalk_records"."vehicle_compliance_flags" IS 'Array of compliance flags detected at scan time, e.g. ["expired_rego", "expired_wof"].';
COMMENT ON COLUMN "public"."parking_chalk_records"."updated_at" IS 'Last modification timestamp. Auto-set by trigger on every UPDATE. Added in 0233 for audit trail completeness.';
COMMENT ON COLUMN "public"."parking_chalk_records"."photo_urls" IS 'Array of photo storage paths with metadata: [{"id": "...", "name": "...", "storage_path": "...", "uploaded_at": "...", "metadata": {"gps_latitude": 0, "gps_longitude": 0, "gps_accuracy": 0, "address": "...", "zone": "...", "officer_id": "...", "officer_name": "..."}}]';
COMMENT ON COLUMN "public"."parking_chalk_records"."geofence_context" IS 'Immutable-at-capture snapshot of resolve_context and is_zone_closed evidence used by the parking scan. Geometry answers where; rules and closure overlays answer what.';
COMMENT ON COLUMN "public"."parking_chalk_records"."canonical_vehicle_id" IS 'Persistent global vehicle identity resolved from plate; plate/organization fields retain the operational record context.';

CREATE TABLE IF NOT EXISTS "public"."parking_infringement_notices" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "chalk_record_id" "uuid",
    "notice_number" "text" NOT NULL,
    "plate_number" "text" NOT NULL,
    "zone_name" "text",
    "zone_id" "uuid",
    "client_site_id" "uuid",
    "offence_description" "text",
    "amount" numeric(10,2),
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "issued_at" timestamp with time zone,
    "issued_by" "uuid",
    "officer_name" "text",
    "evidence_photo_urls" "jsonb",
    "legislative_text" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."parking_infringement_notices" IS 'Parking infringement notices with lifecycle tracking (draft/issued/paid/disputed/cancelled). Issue #114. Separate from the legacy FC public.infringement_notices table (migration 0009) which has a different schema and status enum — see migration 0230/0231 for the history of this split.';

CREATE TABLE IF NOT EXISTS "public"."parking_module_config" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "default_time_limit_minutes" integer DEFAULT 60 NOT NULL,
    "grace_period_minutes" integer DEFAULT 5 NOT NULL,
    "infringement_fee_dollars" numeric(10,2) DEFAULT 65.00 NOT NULL,
    "require_photo_evidence" boolean DEFAULT true NOT NULL,
    "auto_escalate_overstay" boolean DEFAULT true NOT NULL,
    "legislative_text" "text",
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."parking_module_config" IS 'Per-org parking enforcement module configuration: default time limits, grace period, infringement fee, evidence requirements, escalation policy, and legislative text. Issue #113.';
COMMENT ON COLUMN "public"."parking_module_config"."default_time_limit_minutes" IS 'Default parking time limit in minutes used when no zone-specific limit is set. Configurable per org.';
COMMENT ON COLUMN "public"."parking_module_config"."grace_period_minutes" IS 'Grace period in minutes after the time limit expires before an overstay is flagged. Default 5.';
COMMENT ON COLUMN "public"."parking_module_config"."infringement_fee_dollars" IS 'Default infringement fee in dollars for parking overstay notices. Configurable per org/bylaw.';
COMMENT ON COLUMN "public"."parking_module_config"."require_photo_evidence" IS 'When true, officers must attach at least one photo before saving a chalk record. Default true.';
COMMENT ON COLUMN "public"."parking_module_config"."auto_escalate_overstay" IS 'When true, overstay records are automatically escalated for infringement review. Default true.';
COMMENT ON COLUMN "public"."parking_module_config"."legislative_text" IS 'Legislative framework text surfaced in parking infringement notices. Override for council-specific references.';

CREATE TABLE IF NOT EXISTS "public"."parking_rule_matrix" (
