    "qr_code_data" "text",
    "expected_arrival_offset_minutes" integer,
    "required_actions" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "is_mandatory" boolean DEFAULT true NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."patrol_route_checkpoints" IS 'Checkpoint sequences within a named patrol route. GPS, NFC, QR, or manual scan types.';

CREATE TABLE IF NOT EXISTS "public"."patrol_route_sites" (
    "patrol_route_id" "uuid" NOT NULL,
    "site_id" "uuid" NOT NULL,
    "coverage_priority" integer DEFAULT 1 NOT NULL,
    "expected_visits_per_shift" integer,
    "preferred_time_window" "text",
    "required_module" "text",
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "preferred_stop_order" integer DEFAULT 0 NOT NULL,
    "dwell_minutes" integer DEFAULT 15 NOT NULL,
    "sla_arrive_within_minutes" integer DEFAULT 30 NOT NULL
);
COMMENT ON TABLE "public"."patrol_route_sites" IS 'Many-to-many coverage between patrol routes/runs and client sites.';

CREATE TABLE IF NOT EXISTS "public"."patrol_route_stop_modules" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "patrol_config_id" "uuid" NOT NULL,
    "module_key" "text" NOT NULL,
    "module_config" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "is_required" boolean DEFAULT true NOT NULL,
    "display_order" integer DEFAULT 0 NOT NULL,
    "active" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "service_agreement_module_id" "uuid",
    "service_agreement_location_id" "uuid"
);
COMMENT ON TABLE "public"."patrol_route_stop_modules" IS 'Plan-time module assignment for a patrol stop config (unified stop model, !709). One or MORE modules per stop; the route stays module-agnostic. Legacy client_site_patrol_config.module_key is kept for dual-write until Phase 4 deprecation.';
COMMENT ON COLUMN "public"."patrol_route_stop_modules"."service_agreement_module_id" IS 'The authorising service_agreement_module for this plan-time module task. Set at plan-time config; inherited into shift_stop_modules at generation. Nullable for back-compat (existing rows pre-date this column). Exactly ONE authorising contract per stop-module attendance (single FK, not a junction). Owner ruling 2026-08-15: contract attribution at MODULE grain.';
COMMENT ON COLUMN "public"."patrol_route_stop_modules"."service_agreement_location_id" IS 'The authorising service_agreement_location (place-contract) for this plan-time module. Names the place-level contract that authorises this stop. Nullable for back-compat. Set at plan-time config alongside service_agreement_module_id.';

CREATE TABLE IF NOT EXISTS "public"."patrol_route_zones" (
    "patrol_route_id" "uuid" NOT NULL,
    "zone_id" "uuid" NOT NULL,
    "coverage_priority" integer DEFAULT 1 NOT NULL,
    "expected_visits_per_shift" integer,
    "preferred_time_window" "text",
    "required_module" "text",
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."patrol_route_zones" IS 'Many-to-many coverage between patrol routes/runs and location zones.';

CREATE TABLE IF NOT EXISTS "public"."patrol_routes" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "site_id" "uuid",
    "name" "text" NOT NULL,
    "route_code" "text",
    "description" "text",
    "route_type" "text" DEFAULT 'patrol'::"text" NOT NULL,
    "default_shift" "text",
    "default_start_time" time without time zone,
    "default_end_time" time without time zone,
    "expected_duration_minutes" integer,
    "checkpoint_mode" "text" DEFAULT 'sequential'::"text" NOT NULL,
    "min_checkpoints_required" integer,
    "active_days" integer[] DEFAULT '{1,2,3,4,5,6,7}'::integer[] NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "color" "text" DEFAULT '#D32F2F'::"text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "call_sign" "text",
    "guards_required" integer DEFAULT 1 NOT NULL,
    "assignment_type" "text",
    "parent_assignment_id" "uuid",
    "primary_staff_id" "uuid"
);
COMMENT ON TABLE "public"."patrol_routes" IS 'Permanent named patrol templates. Linked to sites and zones. Assigned to officers via roster.';
COMMENT ON COLUMN "public"."patrol_routes"."call_sign" IS 'Base call sign for this assignment (e.g. Alpha). Child positions sequence from this (Alpha 1, Alpha 2). Epic #190 R1.';
COMMENT ON COLUMN "public"."patrol_routes"."guards_required" IS 'Number of staffable positions under this assignment. 1 = single guard (static or solo patrol). Epic #190 R1.';
COMMENT ON COLUMN "public"."patrol_routes"."assignment_type" IS 'Assignment type for dispatch routing and channel grouping: general_patrol | client_patrol | specialty_patrol | static. Epic #190 R1.';
COMMENT ON COLUMN "public"."patrol_routes"."parent_assignment_id" IS 'Self-referencing FK: child position points to its parent assignment. Null = top-level assignment. Epic #190 R1.';
COMMENT ON COLUMN "public"."patrol_routes"."primary_staff_id" IS 'Usual officer for this route. Places this officer mostly attends belong to the route; other staff may still cover it.';

CREATE TABLE IF NOT EXISTS "public"."patrol_solve_cache" (
