    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."person_permit_vehicles" IS 'Vehicles authorised under a specific permit. A permit may cover several vehicles (confirmed from real OFO permit extracts).';

CREATE TABLE IF NOT EXISTS "public"."person_permits" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "client_organization_id" "uuid",
    "canonical_person_id" "uuid" NOT NULL,
    "permit_number" "text" NOT NULL,
    "permit_type" "text",
    "applicant_type" "text",
    "company_name" "text",
    "forest_areas" "text"[],
    "activities" "text"[],
    "hunting_season" "text",
    "date_from" "date",
    "date_to" "date",
    "firearm_confirm" boolean,
    "firearm_licence_valid" boolean,
    "firearm_licence_number" "text",
    "chainsaw_safety_equipment" boolean,
    "keys_issued" boolean,
    "conditions" "text",
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "compliance_checked_at" timestamp with time zone,
    "compliance_source" "text",
    "source_document" "text",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "contact_email" "text",
    "contact_phone" "text",
    "address_text" "text"
);
COMMENT ON TABLE "public"."person_permits" IS 'Forest/site access permits issued to a canonical person, org-scoped. Read path for ordinary users is person_permits_fieldwork, not this table.';
COMMENT ON COLUMN "public"."person_permits"."client_organization_id" IS 'The forest/land owner the permit is issued for (e.g. OFO, TPFL), distinct from organization_id (the issuing/administering org, e.g. R&M).';
COMMENT ON COLUMN "public"."person_permits"."firearm_licence_number" IS 'Personal information - never exposed via person_permits_fieldwork; is_admin_for_org base-table access only.';
COMMENT ON COLUMN "public"."person_permits"."compliance_checked_at" IS 'When this permit''s details were last confirmed (e.g. the date of the source extract/photo it was seeded from). Mirrors canonical_vehicles.compliance_checked_at.';
COMMENT ON COLUMN "public"."person_permits"."compliance_source" IS 'How compliance_checked_at was established: manual (staff entry), import (bulk seed from a historical extract), canonical (system-derived).';
COMMENT ON COLUMN "public"."person_permits"."source_document" IS 'Provenance: the file this permit was imported from (e.g. "OFO permit list 201020.xlsx"), for audit trail back to the original record.';
COMMENT ON COLUMN "public"."person_permits"."contact_email" IS 'Email captured on this permit application. Not necessarily current for the person - it is what was supplied at the time.';
COMMENT ON COLUMN "public"."person_permits"."contact_phone" IS 'Phone captured on this permit application.';
COMMENT ON COLUMN "public"."person_permits"."address_text" IS 'Free-text address captured on this permit application (source data is not structured enough to split reliably).';

CREATE TABLE IF NOT EXISTS "public"."person_record_aliases" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "person_record_id" "uuid" NOT NULL,
    "alias" "text" NOT NULL,
    "alias_norm" "text" NOT NULL,
    "alias_kind" "text" DEFAULT 'aka'::"text" NOT NULL,
    "source" "text" DEFAULT 'user_entered'::"text" NOT NULL,
    "notes" "text",
    "active" boolean DEFAULT true NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    "retired_at" timestamp with time zone,
    "retired_by" "uuid",
    "retired_reason" "text"
);
COMMENT ON TABLE "public"."person_record_aliases" IS 'Other names one person is known by (AKA, preferred, legal, previous/maiden name, merged-record names). Written only through add_person_alias, retire_person_alias and merge_person_records.';

CREATE TABLE IF NOT EXISTS "public"."person_record_document_types" (
    "code" "text" NOT NULL,
    "label" "text" NOT NULL,
    "notice_type" "text"
);

CREATE TABLE IF NOT EXISTS "public"."person_record_documents" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "canonical_person_id" "uuid" NOT NULL,
    "document_type" "text" NOT NULL,
    "file_name" "text" NOT NULL,
    "storage_path" "text" NOT NULL,
    "sha256" "text" NOT NULL,
    "mime_type" "text" NOT NULL,
    "file_size_bytes" bigint NOT NULL,
    "notice_id" "uuid",
    "uploaded_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    "client_request_id" "uuid" NOT NULL,
    "request_payload" "jsonb" NOT NULL
);

CREATE TABLE IF NOT EXISTS "public"."person_records" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "display_name" "text",
    "review_state" "text" DEFAULT 'draft'::"text" NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."person_records" IS 'Master person registry. Draft records require human review before enforcement use.';

CREATE TABLE IF NOT EXISTS "public"."person_vehicle_links" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "person_id" "uuid" NOT NULL,
