    "linked_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "linked_by" "uuid",
    "notes" "text"
);
COMMENT ON TABLE "public"."person_vehicle_links" IS 'Links a known person to a vehicle plate.';

CREATE TABLE IF NOT EXISTS "public"."place_hazards" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "location_id" "uuid" NOT NULL,
    "client_site_id" "uuid",
    "zone_id" "uuid",
    "title" "text" NOT NULL,
    "hazard_class" "text" NOT NULL,
    "risk_level" "text" NOT NULL,
    "likelihood" smallint,
    "consequence" smallint,
    "controls" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "details" "text",
    "source_document_id" "uuid",
    "source_locator" "text",
    "source_name" "text",
    "source_as_of" "date",
    "origin" "text" NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "reported_by" "uuid",
    "reported_shift_id" "uuid",
    "reviewed_by" "uuid",
    "reviewed_at" timestamp with time zone,
    "review_due" "date",
    "retired_by" "uuid",
    "retired_at" timestamp with time zone,
    "retired_reason" "text",
    "version" integer DEFAULT 1 NOT NULL,
    "bob_action_id" "uuid",
    "client_request_id" "uuid",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "risk_owner_id" "uuid",
    "control_levels" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL
);
COMMENT ON TABLE "public"."place_hazards" IS 'Place hazard register: one specific risk at a house (location) or one of its facets (client site or zone), with residual risk level, controls and a link to the exact section of its source document. Feeds the officer safety briefing at shift start and patrol arrival. Writes only through report_place_hazard, manage_place_hazard and apply_bob_place_hazard_proposal.';
COMMENT ON COLUMN "public"."place_hazards"."organization_id" IS 'Organisation that keeps this register entry (custodian). Briefings show every organisation''s live hazards at the place.';
COMMENT ON COLUMN "public"."place_hazards"."source_locator" IS 'Where in the source document the hazard comes from (section or page), shown beside the document link.';
COMMENT ON COLUMN "public"."place_hazards"."status" IS 'reported = raised by an officer, shown to officers as not yet reviewed; active = reviewed or approved; retired = no longer applies.';
COMMENT ON COLUMN "public"."place_hazards"."version" IS 'Bumped whenever briefing-relevant content changes, so officers must re-acknowledge.';

CREATE TABLE IF NOT EXISTS "public"."preset_assignments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "preset_id" "uuid" NOT NULL,
    "scope_org_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "assigned_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."preset_assignments" IS 'Links a user to an access preset at an org scope. Effective grants resolve LIVE from the preset, so preset edits cascade to all holders (issue #3, C3).';

CREATE TABLE IF NOT EXISTS "public"."provider_client_access_grants" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "service_agreement_id" "uuid" NOT NULL,
    "provider_organization_id" "uuid" NOT NULL,
    "client_organization_id" "uuid" NOT NULL,
    "module_key" "text",
    "grant_kind" "text" NOT NULL,
    "starts_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "ends_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."provider_client_access_grants" IS 'Explicit provider/client sharing grants. Prevents cross-client data leakage.';

CREATE TABLE IF NOT EXISTS "public"."ptt_channels" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
