    "emergency" boolean DEFAULT false NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL
);
COMMENT ON TABLE "public"."ptt_transmissions" IS 'PTT transmission audit trail. Emergency flag triggers supervisor alerts.';

CREATE TABLE IF NOT EXISTS "public"."quote_commercial_snapshots" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "quote_id" "uuid" NOT NULL,
    "provider_organization_id" "uuid" NOT NULL,
    "client_organization_id" "uuid" NOT NULL,
    "tender_id" "uuid",
    "discount_schedule_id" "uuid",
    "currency" "text" NOT NULL,
    "gst_rate" numeric(5,4) NOT NULL,
    "discount_pct" numeric(5,2) NOT NULL,
    "total_cost" numeric(12,2) NOT NULL,
    "subtotal_charge" numeric(12,2) NOT NULL,
    "discount_amount" numeric(12,2) NOT NULL,
    "gst_amount" numeric(12,2) NOT NULL,
    "total_charge" numeric(12,2) NOT NULL,
    "pricing_detail" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "accepted_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "accepted_by" "uuid" NOT NULL
);

CREATE TABLE IF NOT EXISTS "public"."quote_lines" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "quote_id" "uuid" NOT NULL,
    "kind" "text" DEFAULT 'custom'::"text" NOT NULL,
    "description" "text" NOT NULL,
    "quantity" numeric(12,2) DEFAULT 1 NOT NULL,
    "unit_cost" numeric(12,2) DEFAULT 0 NOT NULL,
    "unit_charge" numeric(12,2) DEFAULT 0 NOT NULL,
    "module_key" "text",
    "site_id" "uuid",
    "line_order" integer DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "source_dispatch_id" "uuid",
    "client_request_id" "uuid"
);
COMMENT ON TABLE "public"."quote_lines" IS 'One line of a quote. unit_cost (provider pay) + unit_charge (client price) = cost-vs-charge. kind platform_fee lines are generated from the provider Layer-1 effective price (org_module_subscriptions override-else-module_catalog) so client pricing recovers the platform cost.';
COMMENT ON COLUMN "public"."quote_lines"."source_dispatch_id" IS 'FK to dispatch_jobs.id for on-charge lines auto-created by the completion pipeline. Partial unique index prevents duplicate on-charge lines per job per quote.';

CREATE TABLE IF NOT EXISTS "public"."quote_proposal_modules" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "quote_id" "uuid" NOT NULL,
    "module_key" "text" NOT NULL,
    "sla_minutes" integer,
    "service_window" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "pricing_basis" "text" DEFAULT 'quote_lines'::"text" NOT NULL,
    "rate_rule_id" "uuid",
    "client_request_id" "uuid" NOT NULL,
    "created_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "work_model" "text" DEFAULT 'scheduled_patrol'::"text" NOT NULL
);

CREATE TABLE IF NOT EXISTS "public"."quote_proposal_places" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
