    "converted_zone_id" "uuid",
    "converted_at" timestamp with time zone
);

CREATE TABLE IF NOT EXISTS "public"."quote_proposal_scope_schedules" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "proposal_scope_id" "uuid" NOT NULL,
    "capability_key" "text" NOT NULL,
