    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."reference_catalog_entries" IS 'Searchable catalogue entry for an approved / proposed reference document. is_global_reference + approval_status=approved is the only combination Bob may retrieve as a durable global source; setting it is a governed action (promote_document_to_reference_library).';

CREATE TABLE IF NOT EXISTS "public"."reference_code_templates" (
    "code_type" "text" NOT NULL,
    "code" "text" NOT NULL,
    "name" "text" NOT NULL,
    "description" "text",
    "is_active" boolean DEFAULT true NOT NULL,
    "sort_order" integer DEFAULT 0 NOT NULL,
    "external_refs" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."reference_code_templates" IS 'Platform default catalog data copied into each organization. Runtime selectors read organization reference_codes, never hard-coded arrays.';

CREATE TABLE IF NOT EXISTS "public"."reference_codes" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "code_type" "text" NOT NULL,
    "code" "text" NOT NULL,
    "name" "text" NOT NULL,
    "description" "text",
    "item_category" "text",
    "unit" "text",
    "default_rate" numeric,
    "region_code" "text",
    "service_type" "text",
    "parent_code" "text",
    "is_active" boolean DEFAULT true NOT NULL,
    "sort_order" integer DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    "updated_by" "uuid",
    "external_refs" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL
);
COMMENT ON COLUMN "public"."reference_codes"."external_refs" IS 'Legacy external system identifiers (Wilsar/Deputy branch numbers, payroll codes). Boundary mappings only — never used as the human-readable code (ruling 7B). Same pattern as 0167 external_refs on client_sites/location_zones.';

CREATE TABLE IF NOT EXISTS "public"."report_incident_triage" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "service_agreement_id" "uuid" NOT NULL,
    "line_key" "text" NOT NULL,
    "line_date" "date" NOT NULL,
    "place" "text",
    "excerpt" "text",
    "bob_flagged" boolean DEFAULT false NOT NULL,
    "bob_incident_type" "text",
    "bob_reason" "text",
    "bob_confidence" numeric(3,2),
    "bob_model" "text",
    "bob_assessed_at" timestamp with time zone,
    "decision" "text" DEFAULT 'unreviewed'::"text" NOT NULL,
    "incident_type" "text",
    "decision_note" "text",
    "decided_by" "uuid",
    "decided_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."report_incident_triage" IS 'Bob''s potential-incident flags on client report activity lines and the provider reviewer''s decision (incident / not_incident). Keyed by agreement and a content key of the frozen line (v1: hash of every content field except photo and video counts and refs). excerpt is the already-redacted client-facing line text. Written only by the flag-report-potential-incidents edge function (Bob fields) and set_report_incident_triage (decision fields).';

CREATE TABLE IF NOT EXISTS "public"."report_templates" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "module_key" "text" NOT NULL,
    "template_code" "text" NOT NULL,
    "name" "text" NOT NULL,
    "output_policy" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL
);
COMMENT ON TABLE "public"."report_templates" IS 'Report templates per module. Controls output format and client visibility.';

CREATE TABLE IF NOT EXISTS "public"."retention_policies" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid",
    "module_key" "text",
    "category" "text" NOT NULL,
    "retention_days" integer,
    "legal_basis" "text",
    "is_active" boolean DEFAULT true NOT NULL,
    "effective_from" "date" DEFAULT CURRENT_DATE NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "is_permanent" boolean DEFAULT false NOT NULL
);
COMMENT ON TABLE "public"."retention_policies" IS 'Per-council (and optional per-module) evidence retention periods. Councils differ by bylaw; periods are configurable, not hardcoded. organization_id null = platform default fallback.';

CREATE TABLE IF NOT EXISTS "public"."roster_assignments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "roster_template_id" "uuid",
    "officer_id" "uuid" NOT NULL,
    "patrol_route_id" "uuid",
    "site_id" "uuid",
    "service_type" "text" NOT NULL,
    "day_of_week" integer,
    "specific_date" "date",
    "shift" "text" NOT NULL,
    "start_time" time without time zone,
    "end_time" time without time zone,
    "assignment_status" "text" DEFAULT 'scheduled'::"text" NOT NULL,
    "swapped_with_id" "uuid",
    "notification_sent_at" timestamp with time zone,
    "accepted_at" timestamp with time zone,
    "declined_at" timestamp with time zone,
    "decline_reason" "text",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "external_refs" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL
);

CREATE TABLE IF NOT EXISTS "public"."roster_skill_catalog" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "skill_name" "text" NOT NULL,
    "skill_key" "text" NOT NULL,
    "skill_category" "text",
    "active" boolean DEFAULT true NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);

CREATE TABLE IF NOT EXISTS "public"."roster_slots" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "work_unit_id" "uuid" NOT NULL,
    "staff_id" "uuid",
    "scheduled_start" timestamp with time zone NOT NULL,
    "scheduled_end" timestamp with time zone NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "linked_shift_id" "uuid",
    "client_request_id" "uuid" NOT NULL,
    "notes" "text",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "external_refs" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "planned_break_minutes" integer DEFAULT 0 NOT NULL,
    "break_unpaid" boolean DEFAULT false NOT NULL
);
COMMENT ON COLUMN "public"."roster_slots"."staff_id" IS 'Assigned staff member. NULL means the slot is open/unfilled and awaiting assignment, template generation, or an overtime offer.';
COMMENT ON COLUMN "public"."roster_slots"."external_refs" IS 'Source-system evidence for an imported slot, e.g. {"source":"deputy","deputy_location_code":..,"area_name":..,"pay_code":..,"ems_minutes":..,"ncr_minutes":..,"purchase_order":..,"req_ritm":..}.';

CREATE TABLE IF NOT EXISTS "public"."roster_templates" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "description" "text",
    "template_type" "text" DEFAULT 'weekly'::"text" NOT NULL,
    "effective_from" "date",
    "effective_to" "date",
    "is_active" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."roster_templates" IS 'Weekly/fortnightly/monthly roster patterns. Officers are assigned to patrol routes on a recurring schedule.';

CREATE TABLE IF NOT EXISTS "public"."roster_work_units" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "work_unit_type" "text" NOT NULL,
    "service_type" "text" NOT NULL,
    "active" boolean DEFAULT true NOT NULL,
    "patrol_route_id" "uuid",
    "service_agreement_location_id" "uuid",
    "service_agreement_module_id" "uuid",
    "workplace_id" "uuid",
    "team_id" "uuid",
    "cost_centre_id" "uuid",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "required_skill_names" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "required_skill_ids" "uuid"[] DEFAULT '{}'::"uuid"[] NOT NULL,
    "external_refs" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "workshop_work_order_id" "uuid"
);
COMMENT ON COLUMN "public"."roster_work_units"."external_refs" IS 'Source-system identity of this rosterable unit, e.g. {"deputy":{"code":"6947","name":"NSN: 585 Day Patrol"}} so later imports match without asking again.';

CREATE TABLE IF NOT EXISTS "public"."safety_briefing_acknowledgements" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "shift_id" "uuid" NOT NULL,
    "shift_stop_id" "uuid",
    "officer_user_id" "uuid" NOT NULL,
    "briefing_hash" "text" NOT NULL,
    "hazard_snapshot" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "item_count" integer DEFAULT 0 NOT NULL,
    "gps_lat" double precision,
    "gps_lng" double precision,
    "client_request_id" "uuid" NOT NULL,
    "acknowledged_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."safety_briefing_acknowledgements" IS 'Officer receipt that they read and understood the exact safety briefing (briefing_hash over hazard ids, versions and statuses plus active place warnings) for a shift, or for one patrol stop. hazard_snapshot preserves what was shown. Written only by acknowledge_safety_briefing.';

CREATE TABLE IF NOT EXISTS "public"."safety_reviews" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "location_id" "uuid",
    "field_report_id" "uuid",
    "incident_id" "uuid",
    "assessment_id" "uuid",
    "title" "text" NOT NULL,
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "outcome" "text",
    "hazard_id" "uuid",
    "investigation_id" "uuid",
    "reviewed_by" "uuid",
    "reviewed_at" timestamp with time zone,
    "created_by" "uuid" DEFAULT auth.uid(),
    "created_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL
);
COMMENT ON TABLE "public"."safety_reviews" IS 'Custodian-private H&S triage and corrective-action receipt. References original field evidence and the existing investigation spine; never place-widens staff-sensitive narratives.';

CREATE TABLE IF NOT EXISTS "public"."scv_import_batches" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid",
    "source_name" "text" DEFAULT 'canonical_scv_csv'::"text" NOT NULL,
    "file_name" "text",
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "total_rows" integer DEFAULT 0 NOT NULL,
    "valid_rows" integer DEFAULT 0 NOT NULL,
    "inserted_rows" integer DEFAULT 0 NOT NULL,
    "updated_rows" integer DEFAULT 0 NOT NULL,
    "skipped_rows" integer DEFAULT 0 NOT NULL,
    "invalid_rows" integer DEFAULT 0 NOT NULL,
    "error_summary" "text",
    "imported_by" "uuid",
    "started_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."scv_import_batches" IS 'Audit records for canonical SCV CSV imports. CSV import is the primary SCV lookup source before NZSCV API fallback.';

CREATE TABLE IF NOT EXISTS "public"."scv_import_rows" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "batch_id" "uuid" NOT NULL,
    "row_number" integer NOT NULL,
    "raw_row" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "normalized_plate" "text",
    "certificate_number" "text",
    "certificate_status" "text",
    "issued_date" "date",
    "expiry_date" "date",
    "vehicle_make" "text",
    "vehicle_model" "text",
    "vehicle_year" integer,
    "row_status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "error_message" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."scv_import_rows" IS 'Per-row staging and validation result for canonical SCV CSV imports.';

CREATE TABLE IF NOT EXISTS "public"."service_agreement_continuity_policies" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "service_agreement_location_id" "uuid" NOT NULL,
    "service_agreement_module_id" "uuid" NOT NULL,
    "continuity_mode" "text" DEFAULT 'none'::"text" NOT NULL,
    "client_coverage_start" time without time zone,
    "client_coverage_end" time without time zone,
    "provider_coverage_start" time without time zone,
    "provider_coverage_end" time without time zone,
    "share_active_cases" boolean DEFAULT false NOT NULL,
    "share_open_tasks" boolean DEFAULT false NOT NULL,
    "share_recent_history_hours" integer DEFAULT 24 NOT NULL,
    "share_attachments_mode" "text" DEFAULT 'none'::"text" NOT NULL,
    "share_presence_mode" "text" DEFAULT 'none'::"text" NOT NULL,
    "require_handoff_ack" boolean DEFAULT true NOT NULL,
    "continuity_retention_hours" integer DEFAULT 24 NOT NULL,
    "created_by" "uuid" NOT NULL,
    "updated_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);

CREATE TABLE IF NOT EXISTS "public"."service_agreement_delivery_schedules" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "service_agreement_id" "uuid" NOT NULL,
    "proposal_scope_schedule_id" "uuid",
    "site_id" "uuid",
    "zone_id" "uuid",
    "module_key" "text" NOT NULL,
    "capability_key" "text" NOT NULL,
    "work_model" "text" NOT NULL,
    "active_days" integer[] NOT NULL,
    "visits_per_shift" integer NOT NULL,
    "min_gap_between_visits_minutes" integer NOT NULL,
    "window_start" time without time zone,
    "window_end" time without time zone,
    "response_sla_minutes" integer,
    "pricing_basis" "text" NOT NULL,
    "rate_rule_id" "uuid",
    "chargeable_conditions" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "notes" "text",
    "active" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "active_months" integer[] DEFAULT ARRAY[]::integer[] NOT NULL,
    "dwell_minutes" integer DEFAULT 15 NOT NULL,
    "depart_sla_minutes" integer,
    "preferred_stop_order" integer DEFAULT 0 NOT NULL,
    "officer_instructions" "text"
);

CREATE TABLE IF NOT EXISTS "public"."service_agreement_locations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "service_agreement_id" "uuid" NOT NULL,
    "site_id" "uuid",
    "zone_id" "uuid",
    "share_contract_price" boolean,
    "share_actual_cost" boolean,
    "standalone_scan_enabled" boolean DEFAULT false NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "head_contractor_org_id" "uuid",
    "subcontract_attribution_mode" "text" DEFAULT 'whitelabel'::"text" NOT NULL
);
COMMENT ON TABLE "public"."service_agreement_locations" IS 'Location-level contract layer (epic #179). Anchors a service agreement to a specific site or zone. One location can have multiple agreements (different providers for different modules). Visibility settings (share_contract_price, share_actual_cost) override the agreement-level defaults. Self-managed locations use site_services directly and do not need a row here.';

CREATE TABLE IF NOT EXISTS "public"."service_agreement_modules" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "service_agreement_id" "uuid" NOT NULL,
    "module_key" "text" NOT NULL,
    "enabled" boolean DEFAULT true NOT NULL,
    "sla_minutes" integer,
    "allows_client_submission" boolean DEFAULT false NOT NULL,
    "allows_auto_dispatch" boolean DEFAULT false NOT NULL,
    "settings" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "standalone_scan_enabled" boolean DEFAULT false NOT NULL,
    "client_access_mode" "text" DEFAULT 'operational'::"text" NOT NULL,
    "billing_direction" "text" DEFAULT 'on_charge'::"text" NOT NULL
);
COMMENT ON TABLE "public"."service_agreement_modules" IS 'Per-module contract settings: SLA, client submission, auto-dispatch, and module rules.';
COMMENT ON COLUMN "public"."service_agreement_modules"."standalone_scan_enabled" IS 'When true, this module can be used in standalone "login and scan" mode under this agreement — no dispatch_roster dependency. See issue #150.';

CREATE TABLE IF NOT EXISTS "public"."service_agreements" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "provider_organization_id" "uuid" NOT NULL,
    "client_organization_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "starts_on" "date",
    "ends_on" "date",
    "visibility_policy" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "client_portal_access_mode" "text" DEFAULT 'transparency_only'::"text",
    "client_portal_reports_enabled" boolean DEFAULT true NOT NULL,
    "client_portal_finance_enabled" boolean DEFAULT false NOT NULL,
    "allows_client_submission" boolean DEFAULT false NOT NULL,
    "allows_auto_dispatch" boolean DEFAULT false NOT NULL,
    "enabled_modules" "text"[] DEFAULT '{}'::"text"[],
    "monthly_report_template_code" "text",
    "external_refs" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "default_share_contract_price" boolean DEFAULT false NOT NULL,
    "default_share_actual_cost" boolean DEFAULT false NOT NULL,
    "agreement_type" "text" DEFAULT 'operational'::"text" NOT NULL,
    "invitation_status" "text" DEFAULT 'not_invited'::"text" NOT NULL
);
COMMENT ON TABLE "public"."service_agreements" IS 'Contract layer. Defines provider/client relationship, data sharing, and module scope.';
COMMENT ON COLUMN "public"."service_agreements"."client_portal_access_mode" IS 'transparency_only: client sees reports only. full_modules: client can submit jobs, view live map, etc. scan_only: client uses standalone scan modules only (no dispatch/roster). See issue #150.';
COMMENT ON COLUMN "public"."service_agreements"."enabled_modules" IS 'Array of module keys enabled for this agreement (e.g. {patrol, static_guard, alarm_response})';
COMMENT ON COLUMN "public"."service_agreements"."monthly_report_template_code" IS 'Template code selecting the monthly report assembler (e.g. ncc_monthly_facilities_v1). NULL = no monthly pack.';
COMMENT ON COLUMN "public"."service_agreements"."external_refs" IS 'Generic external system reference IDs. E.g. {"wilsar": {"bureau_id": "FSG-NCC", "bureau_name": "NELSON CITY COUNCIL SECURITY CONTRACT"}}';
COMMENT ON COLUMN "public"."service_agreements"."default_share_contract_price" IS 'Default: share contract price with the client org for locations under this agreement. Overridable per location in service_agreement_locations.';
COMMENT ON COLUMN "public"."service_agreements"."default_share_actual_cost" IS 'Default: share actual cost (open-book) with the client org. Overridable per location. False by default.';
COMMENT ON COLUMN "public"."service_agreements"."agreement_type" IS 'financial = Iron Eagle->org platform subscription (Layer 1); operational = provider->client fieldwork (Layer 2).';

CREATE TABLE IF NOT EXISTS "public"."shift_assets" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "shift_id" "uuid" NOT NULL,
    "asset_id" "uuid" NOT NULL,
    "assigned_by" "uuid",
    "assigned_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "returned_at" timestamp with time zone,
    "client_request_id" "uuid" NOT NULL
);

CREATE TABLE IF NOT EXISTS "public"."shift_breaks" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "shift_id" "uuid" NOT NULL,
    "officer_user_id" "uuid" NOT NULL,
    "break_type" "text" NOT NULL,
    "started_at" timestamp with time zone NOT NULL,
    "ended_at" timestamp with time zone,
    "is_paid" boolean NOT NULL,
    "client_request_id" "uuid" NOT NULL,
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."shift_breaks" IS 'Rest and meal breaks taken during a shift. Rest breaks are paid, meal breaks unpaid, per Employment Relations Act 1990 Part 6D.';

CREATE TABLE IF NOT EXISTS "public"."shift_coverage_requests" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "shift_template_id" "uuid",
    "shift_date" "date" NOT NULL,
    "start_time" time without time zone NOT NULL,
    "end_time" time without time zone NOT NULL,
    "site_id" "uuid",
    "patrol_route_id" "uuid",
    "required_staff_count" integer DEFAULT 1 NOT NULL,
    "required_credentials" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "urgency" "text" DEFAULT 'normal'::"text" NOT NULL,
    "claimed_by" "uuid",
    "claimed_at" timestamp with time zone,
    "filled_at" timestamp with time zone,
    "notes" "text",
    "created_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "roster_slot_id" "uuid"
);
COMMENT ON TABLE "public"."shift_coverage_requests" IS 'Open shifts needing coverage. Staff can claim these. Supports credential-aware matching.';

CREATE TABLE IF NOT EXISTS "public"."shift_debriefs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "shift_id" "uuid" NOT NULL,
    "officer_user_id" "uuid" NOT NULL,
    "client_event_id" "uuid" NOT NULL,
    "summary" "text" NOT NULL,
    "safety_incident_reported" boolean DEFAULT false NOT NULL,
    "equipment_issue_reported" boolean DEFAULT false NOT NULL,
    "follow_up_required" boolean DEFAULT false NOT NULL,
    "follow_up_notes" "text",
    "submitted_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."shift_debriefs" IS 'Append-only officer handover submitted after operational work. Shift completion remains a separate lifecycle truth.';

CREATE TABLE IF NOT EXISTS "public"."shift_stop_actions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "shift_stop_id" "uuid" NOT NULL,
    "shift_id" "uuid" NOT NULL,
    "action_type" "text" NOT NULL,
    "result_record_id" "uuid",
    "result_table" "text",
    "outcome" "text",
    "notes" "text",
    "gps_lat" double precision,
    "gps_lng" double precision,
    "performed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "shift_stop_module_id" "uuid",
    "client_request_id" "uuid",
    "gps_accuracy_metres" double precision,
    "evidence_metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "receipt" "jsonb"
);
COMMENT ON TABLE "public"."shift_stop_actions" IS 'Module-specific actions completed at each shift stop. Audit trail for vehicle scans, checkpoints, evidence, and other field actions.';
COMMENT ON COLUMN "public"."shift_stop_actions"."shift_stop_module_id" IS 'Optional link to the specific module task this action belongs to (unified stop model, !709). Null = a stop-level event (e.g. arrival GPS); set = a module-level event (e.g. an FC inspection outcome).';

CREATE TABLE IF NOT EXISTS "public"."shift_stop_modules" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "shift_stop_id" "uuid" NOT NULL,
    "module_key" "text" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "is_required" boolean DEFAULT true NOT NULL,
    "started_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "outcome" "text",
    "result_record_id" "uuid",
    "result_table" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "service_agreement_module_id" "uuid",
    "service_agreement_location_id" "uuid"
);
COMMENT ON TABLE "public"."shift_stop_modules" IS 'Run-time module task for a shift stop (unified stop model, !709). One attendance (shift_stop) can have N module tasks, each with its own completion/outcome. Attendance KPIs (shift_stops) and module-outcome KPIs (this table) are cleanly separable.';
COMMENT ON COLUMN "public"."shift_stop_modules"."service_agreement_module_id" IS 'The authorising service_agreement_module for this run-time module attendance. Inherited from patrol_route_stop_modules at shift generation (generate_shift_stops). Nullable for back-compat. Exactly ONE authorising contract per attendance. Owner ruling 2026-08-15: contract attribution at MODULE grain, #328.';
COMMENT ON COLUMN "public"."shift_stop_modules"."service_agreement_location_id" IS 'The authorising service_agreement_location (place-contract) for this run-time module. Inherited from patrol_route_stop_modules at shift generation. Nullable for back-compat.';

CREATE TABLE IF NOT EXISTS "public"."shift_stops" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "shift_id" "uuid" NOT NULL,
    "patrol_config_id" "uuid",
    "site_id" "uuid",
    "zone_id" "uuid",
    "module_key" "text" NOT NULL,
    "stop_order" integer DEFAULT 0 NOT NULL,
    "visit_number" integer DEFAULT 1 NOT NULL,
    "is_adhoc" boolean DEFAULT false NOT NULL,
    "dispatch_job_id" "uuid",
    "sla_window_open" timestamp with time zone,
    "sla_arrive_by" timestamp with time zone NOT NULL,
    "sla_depart_by" timestamp with time zone,
    "required_dwell_minutes" integer DEFAULT 15 NOT NULL,
    "estimated_arrival_at" timestamp with time zone,
    "estimated_departure_at" timestamp with time zone,
    "travel_distance_metres" integer,
    "travel_time_seconds" integer,
    "sla_status" "text" DEFAULT 'on_track'::"text" NOT NULL,
    "actual_arrived_at" timestamp with time zone,
    "actual_departed_at" timestamp with time zone,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "officer_notes" "text",
    "arrived_gps_lat" double precision,
    "arrived_gps_lng" double precision,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "external_dispatch_id" "text",
    "external_refs" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "place_role" "text" DEFAULT 'work_place'::"text" NOT NULL,
    "arrived_gps_accuracy" double precision,
    "arrival_verification" "text",
    "arrival_distance_m" numeric(10,1),
    "departed_gps_lat" double precision,
    "departed_gps_lng" double precision,
    "bwc_reference" "text",
    "officer_instructions" "text",
    "actual_travel_distance_km" numeric(10,3),
    "travel_from_stop_id" "uuid",
    "travel_distance_method" "text",
    "travel_odometer_start_km" numeric(12,3),
    "travel_odometer_end_km" numeric(12,3),
    "travel_distance_version" integer DEFAULT 0 NOT NULL,
    "travel_distance_recorded_at" timestamp with time zone,
    "travel_distance_recorded_by" "uuid"
);
COMMENT ON TABLE "public"."shift_stops" IS 'Materialised stop list per shift. Generated from client_site_patrol_config when shift is published. SLA windows locked at generation. Updated live by the patrol engine.';
COMMENT ON COLUMN "public"."shift_stops"."zone_id" IS 'The zone attended at this stop, when the stop is a ZONE rather than a SITE (unified stop model, !709). Exactly one of site_id / zone_id is set (shift_stops_place_xor).';
COMMENT ON COLUMN "public"."shift_stops"."external_dispatch_id" IS 'External dispatch/job ID from the source billing system (e.g. Wilsar Internal DespatchId: 59199448). Used for per-visit billing reconciliation.';
COMMENT ON COLUMN "public"."shift_stops"."external_refs" IS 'Generic external system reference IDs for this patrol visit. E.g. {"wilsar": {"dispatch_id": "59199448", "client_id": "NCC200", "visit_charge_exgst": "6.05", "status": "Completed"}}';
COMMENT ON COLUMN "public"."shift_stops"."place_role" IS 'work_place = the place the job is done at (noise source); harmed_party_place = the complainant / protected place. One ad-hoc stop per place attended, per visit.';
COMMENT ON COLUMN "public"."shift_stops"."arrival_verification" IS 'Server-computed geofence result at arrival. Loud, never blocking: verified_on_site | near_site | off_site | unverified_boundary | no_geofence | no_gps.';
COMMENT ON COLUMN "public"."shift_stops"."bwc_reference" IS 'Body-worn camera recording reference spoken/logged at arrival (job number, type, address).';
COMMENT ON COLUMN "public"."shift_stops"."officer_instructions" IS 'Instruction for the officer at this stop, copied from client_site_patrol_config at generation (quote schedule -> patrol config -> stop).';

CREATE TABLE IF NOT EXISTS "public"."shift_swaps" (
