    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "user_id" "uuid",
    "work_ready" boolean DEFAULT false NOT NULL,
    "external_refs" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "work_ready_reviewed_by" "uuid",
    "work_ready_reviewed_at" timestamp with time zone,
    "work_ready_review_notes" "text",
    "seniority_date" "date",
    "overtime_eligible" boolean DEFAULT true NOT NULL,
    "role_code" "text"
);
COMMENT ON TABLE "public"."staff_profiles" IS 'Extended employment profile for staff. Covers employment type, emergency contact, payroll, and uniform.';
COMMENT ON COLUMN "public"."staff_profiles"."employee_number" IS 'Organisation-unique staff identifier. Blank values are assigned as EMP-###### at profile creation; existing identifiers are preserved.';
COMMENT ON COLUMN "public"."staff_profiles"."external_refs" IS 'Generic external system reference IDs. E.g. {"deputy": {"employee_id": "521735", "payroll_export_code": "356310000|MPP"}}';
COMMENT ON COLUMN "public"."staff_profiles"."seniority_date" IS 'Basis for seniority-ordered overtime distribution. Defaults to start_date; kept separate so recognised prior service can be credited.';

