    "basis" "text" NOT NULL,
    "observation_id" "uuid",
    "noise_assessment_id" "uuid",
    "smoke_assessment_id" "uuid",
    "biosecurity_assessment_id" "uuid",
    "incident_id" "uuid",
    "notice_id" "uuid",
    "enforcement_case_id" "uuid",
    "started_at" timestamp with time zone DEFAULT "now"() NOT NULL,
