    "reviewed_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    "created_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL
);
COMMENT ON TABLE "public"."vehicle_identity_checks" IS 'Org-scoped, human-reviewed source-time identity checks linking a canonical vehicle, canonical person, private source image, and the exact NZTA MVR snapshot. A historical check does not claim current ownership.';

CREATE TABLE IF NOT EXISTS "public"."vehicle_observations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "vehicle_id" "uuid",
    "plate_raw" "text" NOT NULL,
    "plate_confidence" real,
    "location_id" "uuid",
    "zone_id" "uuid",
    "gps_lat" double precision,
    "gps_lng" double precision,
    "officer_user_id" "uuid",
