);
COMMENT ON TABLE "public"."website_page_views_daily" IS 'Daily first-party R&M website page-view aggregates by page and approximate country/region. No visitor-level records, unique visitor IDs, raw IP addresses or user-agent values.';
COMMENT ON COLUMN "public"."website_page_views_daily"."viewed_on" IS 'UTC calendar date; individual request timestamps are not stored.';
COMMENT ON COLUMN "public"."website_page_views_daily"."country_code" IS 'Approximate country code from Vercel geolocation headers; ZZ means unavailable.';
COMMENT ON COLUMN "public"."website_page_views_daily"."region_code" IS 'Approximate region code from Vercel geolocation headers; ZZ means unavailable.';

CREATE TABLE IF NOT EXISTS "public"."website_posts" (
