);
COMMENT ON TABLE "public"."website_posts" IS 'Provider-private marketing drafts. Only an explicit publish action copies validated text/photo into published_content; saving a draft never changes the public copy. Plain text, not executable HTML.';

CREATE TABLE IF NOT EXISTS "public"."welfare_alerts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "officer_user_id" "uuid" NOT NULL,
    "shift_id" "uuid",
    "alert_type" "text" NOT NULL,
    "gps_lat" double precision,
    "gps_lng" double precision,
    "acknowledged_by" "uuid",
    "acknowledged_at" timestamp with time zone,
    "resolved_at" timestamp with time zone,
    "triggered_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "escalation_level" integer DEFAULT 1 NOT NULL,
    "escalated_at" timestamp with time zone,
    "acknowledgement_notes" "text",
    "resolution_notes" "text",
    "resolved_by" "uuid",
    "officer_phone" "text",
    "last_activity_at" timestamp with time zone,
    "gps_accuracy" double precision,
    "notes" "text",
    "client_request_id" "uuid"
);
COMMENT ON TABLE "public"."welfare_alerts" IS 'Escalated welfare alerts. SOS and armed_danger trigger emergency broadcast and supervisor notification.';

CREATE TABLE IF NOT EXISTS "public"."welfare_checks" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
