CREATE TABLE IF NOT EXISTS "public"."workshop_bom_template_lines" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "template_id" "uuid" NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "line_kind" "text" NOT NULL,
    "item_id" "uuid",
    "description" "text" NOT NULL,
    "quantity" numeric(14,3) NOT NULL,
    "unit_of_measure" "text",
    "position" integer DEFAULT 0 NOT NULL
);

CREATE TABLE IF NOT EXISTS "public"."workshop_bom_templates" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "description" "text",
    "kind" "text" DEFAULT 'fabrication'::"text" NOT NULL,
    "active" boolean DEFAULT true NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."workshop_bom_templates" IS 'Reusable bill-of-materials templates (e.g. "Standard lockbox") an organisation copies onto a work order or quote.';

CREATE TABLE IF NOT EXISTS "public"."workshop_settings" (
    "organization_id" "uuid" NOT NULL,
    "default_job_lead_user_id" "uuid",
    "updated_by" "uuid",
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."workshop_settings" IS 'Per-organization Manufacturing & maintenance defaults. The default job lead is preselected on new client jobs; the work order keeps the actual assignee. Written only through set_workshop_default_job_lead.';

CREATE TABLE IF NOT EXISTS "public"."workshop_work_order_lines" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "work_order_id" "uuid" NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "client_request_id" "uuid",
    "line_kind" "text" NOT NULL,
    "item_id" "uuid",
    "description" "text" NOT NULL,
    "quantity" numeric(14,3) NOT NULL,
    "unit_of_measure" "text",
    "unit_cost" numeric(14,2) DEFAULT 0 NOT NULL,
    "unit_price" numeric(14,2) DEFAULT 0 NOT NULL,
    "line_total" numeric(14,2) GENERATED ALWAYS AS (round((quantity * unit_price), 2)) STORED,
    "inventory_transaction_id" "uuid",
    "invoice_line_item_id" "uuid",
    "position" integer DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid"
);

CREATE TABLE IF NOT EXISTS "public"."workshop_work_orders" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "client_request_id" "uuid" NOT NULL,
    "order_number" "text" NOT NULL,
    "kind" "text" NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "title" "text" NOT NULL,
    "description" "text",
    "client_organization_id" "uuid",
    "service_agreement_id" "uuid",
    "client_site_id" "uuid",
    "asset_id" "uuid",
    "inventory_location_id" "uuid",
    "bom_template_id" "uuid",
    "assigned_user_id" "uuid",
    "scheduled_for" timestamp with time zone,
    "started_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "cancelled_at" timestamp with time zone,
    "completion_note" "text",
    "created_by" "uuid",
    "updated_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "zone_id" "uuid",
    "work_subject_code_id" "uuid",
    "work_activity_code_id" "uuid"
);
COMMENT ON TABLE "public"."workshop_work_orders" IS 'Fabrication (workshop build) and maintenance (visit to a client place/asset) work orders. Lines are the bill of materials + labour + travel; completion draws down stock and leaves billable lines for the invoice sweep.';
COMMENT ON COLUMN "public"."workshop_work_orders"."zone_id" IS 'The zone this maintenance visit is at, when the place has no address (see client_site_id for the addressed case). A maintenance work order needs client_site_id, zone_id, or asset_id.';
COMMENT ON COLUMN "public"."workshop_work_orders"."work_subject_code_id" IS 'Catalog row describing the object of the work; labels and options come from reference_codes.';
COMMENT ON COLUMN "public"."workshop_work_orders"."work_activity_code_id" IS 'Catalog row describing the work action; labels and options come from reference_codes.';

CREATE TABLE IF NOT EXISTS "public"."zone_closures" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "zone_id" "uuid" NOT NULL,
    "closure_type" "text" DEFAULT 'temporary_closure'::"text" NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "effective_from" "date" DEFAULT CURRENT_DATE NOT NULL,
    "effective_to" "date",
    "reason" "text",
    "resolution_notes" "text",
    "notice_bundle_url" "text",
    "created_by" "uuid",
    "lifted_by" "uuid",
    "lifted_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."zone_closures" IS 'Temporary closures, prohibited and restricted area overlays per zone. Effective dates + reason + resolution + notice bundle reference. History kept.';

CREATE TABLE IF NOT EXISTS "public"."zone_compliance_matrix" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "zone_id" "uuid" NOT NULL,
    "version" integer DEFAULT 1 NOT NULL,
    "is_current" boolean DEFAULT true NOT NULL,
    "max_consecutive_nights" integer,
    "max_nights_per_month" integer,
    "max_nights_per_year" integer,
    "allowed_vehicle_types" "text"[] DEFAULT ARRAY['self_contained'::"text", 'tent'::"text", 'campervan'::"text"],
    "scv_required" boolean DEFAULT false NOT NULL,
    "no_camping_start_time" time without time zone,
    "no_camping_end_time" time without time zone,
    "restricted_from_date" "date",
    "restricted_to_date" "date",
    "effective_from" "date" DEFAULT CURRENT_DATE NOT NULL,
    "effective_to" "date",
    "bylaw_clause" "text",
    "bylaw_source_url" "text",
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid"
);
COMMENT ON TABLE "public"."zone_compliance_matrix" IS 'Versioned compliance rules per zone. Supports bylaw amendments without losing history.';

CREATE TABLE IF NOT EXISTS "public"."zone_legal_config" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "zone_id" "uuid" NOT NULL,
    "payment_url" "text",
    "payment_deadline_days" integer DEFAULT 28 NOT NULL,
    "infringement_amount" numeric(10,2),
    "objections_email" "text",
    "objections_address" "text",
    "issuing_authority" "text",
    "authorising_act" "text",
    "authorising_section" "text",
    "dispute_portal_url" "text",
    "council_phone" "text",
    "council_email" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."zone_legal_config" IS 'Payment, objections, and dispute portal config per zone. Appears on generated notices.';

CREATE TABLE IF NOT EXISTS "public"."zone_signage_evidence" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "zone_id" "uuid" NOT NULL,
    "officer_id" "uuid" NOT NULL,
    "photo_url" "text" NOT NULL,
    "sign_type" "text" DEFAULT 'freedom_camping'::"text" NOT NULL,
    "gps_lat" double precision,
    "gps_lng" double precision,
    "notes" "text",
    "captured_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."zone_signage_evidence" IS 'Photos of posted signage at zone boundaries. Required for court-ready evidence package.';

