CREATE OR REPLACE FUNCTION "public"."_entitled_org_ids_for"(p_user_id uuid)
 RETURNS SETOF uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  -- CLAUSE 1: grand_master sees ALL orgs.
  select o.id
  from public.organizations o
  where exists (
    select 1 from public.user_profiles p
    where p.id = p_user_id and p.role = 'grand_master'
  )

  union

  -- CLAUSE 2: own org + authorized_organization_ids.
  select target.id
  from public.organizations target
  join public.user_profiles p on p.id = p_user_id
  where target.id = p.organization_id
     or target.id = any(p.authorized_organization_ids)

  union

  -- CLAUSE 3: master/admin ownership-tree descent (org + employer anchors).
  select d.org_id
  from public.user_profiles p
  cross join lateral (
    select unnest(
      public.get_descendant_organizations(p.organization_id)
      || case
           when p.employer_organization_id is not null
           then public.get_descendant_organizations(p.employer_organization_id)
           else array[]::uuid[]
         end
    ) as org_id
  ) d
  where p.id = p_user_id
    and p.role in ('grand_master', 'master', 'admin', 'admin_officer')

  union

  -- CLAUSE 4: provider_client_access_grants (active).
  select g_target.org_id
  from public.provider_client_access_grants g
  join public.user_profiles p on p.id = p_user_id
  cross join lateral (
    values (g.provider_organization_id), (g.client_organization_id)
  ) as g_target(org_id)
  where (
      p.organization_id = g.provider_organization_id
      or p.organization_id = g.client_organization_id
    )
    and (g.ends_at is null or g.ends_at > now())

  union

  -- CLAUSE 5 (0271): agreement-based, bidirectional.
  select sa_target.org_id
  from public.service_agreements sa
  join public.user_profiles p on p.id = p_user_id
  cross join lateral (
    values
      (case when (p.organization_id = sa.provider_organization_id
                  or p.employer_organization_id = sa.provider_organization_id)
            then sa.client_organization_id end),
      (case when (p.organization_id = sa.client_organization_id
                  or p.employer_organization_id = sa.client_organization_id)
            then sa.provider_organization_id end)
  ) as sa_target(org_id)
  where (sa.ends_on is null or sa.ends_on >= current_date)
    and sa_target.org_id is not null;
$function$;
COMMENT ON FUNCTION "public"."_entitled_org_ids_for"(p_user_id uuid) IS 'INTERNAL shared entitlement resolver: the five org_access_allowed clauses keyed on an EXPLICIT resolved user id. NOT user-callable (revoked from public / authenticated / anon) - it accepts an arbitrary user id, so it is reachable ONLY through the governed wrappers my_entitled_org_ids() (self-only) and my_entitled_org_ids_for_user() (service-role only). Single source of truth for both; 0352 parity matrix applies. #306.';
REVOKE ALL ON FUNCTION "public"."_entitled_org_ids_for"(p_user_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."_entitled_org_ids_for"(p_user_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."_entitled_org_ids_for"(p_user_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."_gbh_next_version"(p_entity_type text, p_entity_id uuid)
 RETURNS integer
 LANGUAGE sql
 STABLE
AS $function$
  SELECT COALESCE(MAX(version), 0) + 1
    FROM public.geofence_boundary_history
   WHERE entity_type = p_entity_type
     AND entity_id   = p_entity_id;
$function$;
REVOKE ALL ON FUNCTION "public"."_gbh_next_version"(p_entity_type text, p_entity_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."_gbh_next_version"(p_entity_type text, p_entity_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."_gbh_next_version"(p_entity_type text, p_entity_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."_geofence_active_at"(p_schedule jsonb, p_at timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v_local   timestamp := p_at at time zone 'Pacific/Auckland';
  v_minutes int := extract(hour from v_local)::int * 60 + extract(minute from v_local)::int;
  v_isodow  int := extract(isodow from v_local)::int;   -- 1 = Monday … 7 = Sunday
  v_month   int := extract(month from v_local)::int;
  v_start   text;
  v_end     text;
  v_start_m int;
  v_end_m   int;
  v_days    jsonb;
  v_months  jsonb;
begin
  if p_schedule is null or p_schedule = '{}'::jsonb then
    return true;
  end if;

  -- Day-of-week filter (ISO; a legacy 0 still means Sunday).
  v_days := p_schedule -> 'days';
  if v_days is not null and jsonb_typeof(v_days) = 'array' and jsonb_array_length(v_days) > 0 then
    if not exists (
      select 1 from jsonb_array_elements_text(v_days) d
      where case when d::int = 0 then 7 else d::int end = v_isodow
    ) then
      return false;
    end if;
  end if;

  -- Month filter (seasonal rules).
  v_months := p_schedule -> 'months';
  if v_months is not null and jsonb_typeof(v_months) = 'array' and jsonb_array_length(v_months) > 0 then
    if not exists (select 1 from jsonb_array_elements_text(v_months) m where m::int = v_month) then
      return false;
    end if;
  end if;

  -- Time-of-day window.
  v_start := p_schedule ->> 'start';
  v_end   := p_schedule ->> 'end';
  if v_start is null or v_end is null then
    return true;
  end if;

  v_start_m := split_part(v_start, ':', 1)::int * 60 + split_part(v_start, ':', 2)::int;
  v_end_m   := split_part(v_end,   ':', 1)::int * 60 + split_part(v_end,   ':', 2)::int;

  if v_start_m <= v_end_m then
    return v_minutes >= v_start_m and v_minutes < v_end_m;
  else
    return v_minutes >= v_start_m or v_minutes < v_end_m;   -- overnight wrap
  end if;
end;
$function$;
COMMENT ON FUNCTION "public"."_geofence_active_at"(p_schedule jsonb, p_at timestamp with time zone) IS 'True if a zone active_schedule (jsonb {days (ISO 1=Mon..7=Sun; legacy 0=Sun), months (1-12), start "HH:MM", end "HH:MM"}) is in force at the given time in Pacific/Auckland. Null or {} = always active; start > end wraps overnight.';
REVOKE ALL ON FUNCTION "public"."_geofence_active_at"(p_schedule jsonb, p_at timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."_geofence_active_at"(p_schedule jsonb, p_at timestamp with time zone) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."_geofence_active_at"(p_schedule jsonb, p_at timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."_geofence_active_at"(p_schedule jsonb, p_at timestamp with time zone) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."_geofence_active_at"(p_schedule jsonb, p_at timestamp with time zone) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."_geofence_active_at"(p_schedule jsonb, p_at timestamp with time zone) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."_match_person_records"(p_organization_id uuid, p_name text, p_date_of_birth date, p_licence_number text, p_phone text, p_email text, p_exclude_person_record_id uuid, p_limit integer, p_include_contacts boolean)
 RETURNS TABLE(person_record_id uuid, display_name text, review_state text, matched_name text, match_basis text, score real, strength text, aliases text[], locality text, origin text, sighting_count bigint)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
DECLARE
  v_contacts boolean := coalesce(p_include_contacts, false);
  v_norm text := public.normalize_person_name(p_name);
  v_lower text := nullif(lower(regexp_replace(trim(coalesce(p_name, '')), '\s+', ' ', 'g')), '');
  v_first text;
  v_last text;
  v_licence text := nullif(upper(regexp_replace(coalesce(p_licence_number, ''), '[^A-Za-z0-9]', '', 'g')), '');
  v_phone text := CASE WHEN coalesce(p_include_contacts, false) THEN nullif(regexp_replace(coalesce(p_phone, ''), '[^0-9]', '', 'g'), '') END;
  v_email text := CASE WHEN coalesce(p_include_contacts, false) THEN nullif(lower(trim(coalesce(p_email, ''))), '') END;
BEGIN
  IF p_organization_id IS NULL THEN RETURN; END IF;
  IF v_phone IS NOT NULL AND length(v_phone) < 7 THEN v_phone := NULL; END IF;
  IF v_norm IS NULL AND v_licence IS NULL AND v_phone IS NULL AND v_email IS NULL THEN RETURN; END IF;
  IF v_lower IS NOT NULL THEN
    v_first := split_part(v_lower, ' ', 1);
    v_last := CASE WHEN position(' ' IN v_lower) > 0 THEN regexp_replace(v_lower, '^.* ', '') END;
  END IF;
  RETURN QUERY
  WITH people AS (
    SELECT pr.id, pr.display_name, pr.review_state, pr.metadata,
      coalesce(pr.metadata->'profile_details', '{}'::jsonb) AS details
    FROM public.person_records pr
    WHERE pr.organization_id = p_organization_id AND pr.id IS DISTINCT FROM p_exclude_person_record_id
      AND NOT (pr.metadata ? 'merged_into_person_record_id')
      AND NOT (pr.metadata ? 'resolved_into_person_record_id')
  ), names AS (
    SELECT p.id, p.display_name AS name, 'display_name'::text AS name_kind FROM people p WHERE p.display_name IS NOT NULL
    UNION ALL
    SELECT a.person_record_id, a.alias, 'alias' FROM public.person_record_aliases a
    JOIN people p ON p.id = a.person_record_id WHERE a.active
  ), name_hits AS (
    SELECT n.id, n.name,
      CASE
        WHEN public.normalize_person_name(n.name) = v_norm THEN CASE WHEN n.name_kind = 'alias' THEN 'alias_exact' ELSE 'name_exact' END
        WHEN v_last IS NOT NULL AND lower(regexp_replace(trim(n.name), '^.* ', '')) = v_last
          AND length(v_first) >= 2 AND length(split_part(lower(trim(n.name)), ' ', 1)) >= 2
          AND (position(v_first IN split_part(lower(trim(n.name)), ' ', 1)) > 0
            OR position(split_part(lower(trim(n.name)), ' ', 1) IN v_first) > 0) THEN 'name_variant'
        ELSE 'name_similar'
      END AS basis,
      CASE
        WHEN public.normalize_person_name(n.name) = v_norm THEN 0.85
        WHEN v_last IS NOT NULL AND lower(regexp_replace(trim(n.name), '^.* ', '')) = v_last
          AND length(v_first) >= 2 AND length(split_part(lower(trim(n.name)), ' ', 1)) >= 2
          AND (position(v_first IN split_part(lower(trim(n.name)), ' ', 1)) > 0
            OR position(split_part(lower(trim(n.name)), ' ', 1) IN v_first) > 0) THEN 0.72
        ELSE 0.40 + 0.40 * extensions.similarity(lower(n.name), v_lower)
      END::real AS score
    FROM names n
    WHERE v_norm IS NOT NULL AND (
      public.normalize_person_name(n.name) = v_norm OR extensions.similarity(lower(n.name), v_lower) >= 0.45
      OR (v_last IS NOT NULL AND lower(regexp_replace(trim(n.name), '^.* ', '')) = v_last
        AND length(v_first) >= 2 AND length(split_part(lower(trim(n.name)), ' ', 1)) >= 2
        AND (position(v_first IN split_part(lower(trim(n.name)), ' ', 1)) > 0
          OR position(split_part(lower(trim(n.name)), ' ', 1) IN v_first) > 0))
    )
  ), detail_hits AS (
    SELECT p.id, p.display_name AS name,
      CASE WHEN v_licence IS NOT NULL AND v_licence IN (
        upper(regexp_replace(coalesce(p.details->>'driver_licence_number', ''), '[^A-Za-z0-9]', '', 'g')),
        upper(regexp_replace(coalesce(p.details->>'firearms_licence_number', ''), '[^A-Za-z0-9]', '', 'g')),
        upper(regexp_replace(coalesce(p.details->>'security_licence_number', ''), '[^A-Za-z0-9]', '', 'g')),
        upper(regexp_replace(coalesce(p.details->>'document_number', ''), '[^A-Za-z0-9]', '', 'g'))) THEN 'credential_number_exact'
        WHEN v_phone IS NOT NULL AND regexp_replace(coalesce(p.details->>'phone', ''), '[^0-9]', '', 'g') = v_phone THEN 'phone_exact'
        ELSE 'email_exact' END AS basis,
      CASE WHEN v_licence IS NOT NULL AND v_licence IN (
        upper(regexp_replace(coalesce(p.details->>'driver_licence_number', ''), '[^A-Za-z0-9]', '', 'g')),
        upper(regexp_replace(coalesce(p.details->>'firearms_licence_number', ''), '[^A-Za-z0-9]', '', 'g')),
        upper(regexp_replace(coalesce(p.details->>'security_licence_number', ''), '[^A-Za-z0-9]', '', 'g')),
        upper(regexp_replace(coalesce(p.details->>'document_number', ''), '[^A-Za-z0-9]', '', 'g'))) THEN 1.0
        ELSE 0.90 END::real AS score
    FROM people p
    WHERE (v_licence IS NOT NULL AND v_licence IN (
      upper(regexp_replace(coalesce(p.details->>'driver_licence_number', ''), '[^A-Za-z0-9]', '', 'g')),
      upper(regexp_replace(coalesce(p.details->>'firearms_licence_number', ''), '[^A-Za-z0-9]', '', 'g')),
      upper(regexp_replace(coalesce(p.details->>'security_licence_number', ''), '[^A-Za-z0-9]', '', 'g')),
      upper(regexp_replace(coalesce(p.details->>'document_number', ''), '[^A-Za-z0-9]', '', 'g'))))
      OR (v_phone IS NOT NULL AND regexp_replace(coalesce(p.details->>'phone', ''), '[^0-9]', '', 'g') = v_phone)
      OR (v_email IS NOT NULL AND lower(trim(coalesce(p.details->>'email', ''))) = v_email)
  ), hits AS (
    SELECT h.id, h.name, h.basis,
      CASE WHEN p_date_of_birth IS NOT NULL AND nullif(p.details->>'date_of_birth', '')::date = p_date_of_birth
        THEN greatest(h.score, 0.97)::real ELSE h.score END AS score,
      (p_date_of_birth IS NOT NULL AND nullif(p.details->>'date_of_birth', '')::date = p_date_of_birth) AS dob_match
    FROM (SELECT * FROM name_hits UNION ALL SELECT * FROM detail_hits) h JOIN people p ON p.id = h.id
  ), ranked AS (
    SELECT DISTINCT ON (h.id) h.id, h.name, h.basis || CASE WHEN h.dob_match THEN '+date_of_birth' ELSE '' END AS basis, h.score
    FROM hits h ORDER BY h.id, h.score DESC
  )
  SELECT p.id, p.display_name, p.review_state, r.name, r.basis, r.score,
    CASE WHEN r.score >= 0.95 THEN 'strong' WHEN r.score >= 0.80 THEN 'likely' ELSE 'possible' END,
    coalesce(ARRAY(SELECT a.alias FROM public.person_record_aliases a WHERE a.person_record_id = p.id AND a.active ORDER BY a.created_at), ARRAY[]::text[]),
    CASE WHEN v_contacts THEN public.vehicle_owner_locality(p.details) END,
    coalesce(p.metadata->>'origin', p.metadata->>'created_from'),
    (SELECT count(*) FROM public.cctv_entity_observations c WHERE c.person_record_id = p.id)
      + (SELECT count(*) FROM public.observations o WHERE o.person_record_id = p.id)
  FROM ranked r JOIN people p ON p.id = r.id
  ORDER BY r.score DESC, p.review_state = 'verified' DESC, p.display_name
  LIMIT least(greatest(coalesce(p_limit, 8), 1), 25);
END;
$function$;
REVOKE ALL ON FUNCTION "public"."_match_person_records"(p_organization_id uuid, p_name text, p_date_of_birth date, p_licence_number text, p_phone text, p_email text, p_exclude_person_record_id uuid, p_limit integer, p_include_contacts boolean) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."_match_person_records"(p_organization_id uuid, p_name text, p_date_of_birth date, p_licence_number text, p_phone text, p_email text, p_exclude_person_record_id uuid, p_limit integer, p_include_contacts boolean) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."_write_org_jurisdiction_geom"(p_org_id uuid, p_geom geometry, p_boundary_source text, p_changed_by uuid, p_changed_via text)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_geom    geometry;
  v_area_m2 numeric;
  v_source  text;
  v_via     text;
BEGIN
  IF p_geom IS NULL THEN
    RAISE EXCEPTION 'Could not build geometry from supplied GeoJSON';
  END IF;
  v_geom := st_multi(st_setsrid(st_makevalid(p_geom), 4326));
  IF st_isempty(v_geom) THEN
    RAISE EXCEPTION 'Geometry is empty after ST_MakeValid + ST_Union';
  END IF;
  IF NOT st_isvalid(v_geom) THEN
    RAISE EXCEPTION 'Geometry is still invalid after ST_MakeValid: %', st_isvalidreason(v_geom);
  END IF;

  v_area_m2 := st_area(v_geom::geography);

  UPDATE public.organizations SET jurisdiction_geom = v_geom WHERE id = p_org_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Organization % not found', p_org_id;
  END IF;

  -- P1: loud, explicit provenance when the caller supplies none.
  v_source := COALESCE(NULLIF(TRIM(p_boundary_source), ''), 'UNKNOWN_SOURCE');
  v_via := CASE
    WHEN p_changed_via IN ('governed_proposal', 'direct_edit', 'reconciliation', 'refresh', 'verification', 'backfill')
    THEN p_changed_via
    ELSE 'governed_proposal'
  END;

  INSERT INTO public.geofence_boundary_history (
    entity_type, entity_id, boundary, boundary_source,
    verification_state, verified_by, verified_at,
    changed_by, changed_via, change_reason, version
  ) VALUES (
    'organization', p_org_id, v_geom, v_source,
    'unverified', NULL, NULL,
    p_changed_by, v_via, 'Jurisdiction geometry set via set_org_jurisdiction_geom',
    public._gbh_next_version('organization', p_org_id)
  );

  RETURN v_area_m2;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."_write_org_jurisdiction_geom"(p_org_id uuid, p_geom geometry, p_boundary_source text, p_changed_by uuid, p_changed_via text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."_write_org_jurisdiction_geom"(p_org_id uuid, p_geom geometry, p_boundary_source text, p_changed_by uuid, p_changed_via text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."_write_org_jurisdiction_geom"(p_org_id uuid, p_geom geometry, p_boundary_source text, p_changed_by uuid, p_changed_via text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."accept_boundary_proposal"(p_proposal_id uuid, p_final_geojson jsonb DEFAULT NULL::jsonb, p_verify boolean DEFAULT false, p_note text DEFAULT NULL::text)
 RETURNS TABLE(entity_type text, entity_id uuid, area_m2 numeric, human_edited boolean, verified boolean, history_version integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_p public.boundary_proposals%rowtype;
  v_final geometry;
  v_edited boolean := false;
  v_area numeric;
  v_gate record;
  v_version integer;
  v_owner_org uuid;
  v_source text;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT * INTO v_p FROM public.boundary_proposals WHERE id = p_proposal_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Proposal not found'; END IF;
  IF v_p.status <> 'proposed' THEN RAISE EXCEPTION 'Proposal is already %', v_p.status; END IF;
  IF v_p.entity_id IS NULL THEN RAISE EXCEPTION 'Proposal has no target entity; create the site or zone first'; END IF;

  IF p_final_geojson IS NOT NULL THEN
    v_final := ST_Multi(ST_MakeValid(ST_SetSRID(ST_GeomFromGeoJSON(p_final_geojson::text), 4326)));
    IF v_final IS NULL OR ST_IsEmpty(v_final) OR NOT ST_IsValid(v_final) THEN RAISE EXCEPTION 'Final geometry is empty or invalid'; END IF;
    v_edited := NOT ST_Equals(v_final, v_p.proposed_boundary);
  ELSE
    v_final := v_p.proposed_boundary;
  END IF;
  v_area := ST_Area(v_final::geography);
  SELECT * INTO v_gate FROM public.geofence_area_gate(v_area, v_p.zone_type);
  IF NOT v_gate.ok THEN RAISE EXCEPTION 'Boundary fails the % area gate: %', coalesce(v_p.zone_type, 'default'), v_gate.reason; END IF;

  v_source := CASE WHEN v_edited THEN 'user_drawn' ELSE v_p.source END;

  IF v_p.entity_type = 'client_site' THEN
    SELECT client_organization_id INTO v_owner_org FROM public.client_sites WHERE id = v_p.entity_id FOR UPDATE;
    IF v_owner_org IS NULL OR NOT public.org_access_allowed(v_owner_org) THEN RAISE EXCEPTION 'Site not found or access denied'; END IF;
    -- client_sites.boundary is Polygon(4326); a single-part multipolygon is unwrapped.
    IF ST_NumGeometries(v_final) <> 1 THEN RAISE EXCEPTION 'A site boundary must be a single polygon'; END IF;
    UPDATE public.client_sites
      SET boundary = ST_GeometryN(v_final, 1), center_point = ST_Centroid(v_final),
          boundary_status = CASE WHEN v_p.source = 'google_point_radius' THEN 'provisional' ELSE 'authoritative' END,
          boundary_verification = 'unverified', boundary_verified_by = NULL, boundary_verified_at = NULL,
          configuration_version = configuration_version + 1
      WHERE id = v_p.entity_id;
    v_version := public._gbh_next_version('client_site', v_p.entity_id);
    INSERT INTO public.geofence_boundary_history (entity_type, entity_id, boundary, boundary_source, verification_state, changed_by, changed_via, change_reason, version)
    VALUES ('client_site', v_p.entity_id, ST_GeometryN(v_final, 1), v_source, 'unverified', v_actor, 'direct_edit',
      format('Accepted boundary proposal %s (%s%s)', v_p.id, v_p.source, CASE WHEN v_edited THEN ', human-edited' ELSE '' END), v_version);
  ELSIF v_p.entity_type = 'location_zone' THEN
    SELECT organization_id INTO v_owner_org FROM public.location_zones WHERE id = v_p.entity_id FOR UPDATE;
    IF v_owner_org IS NULL OR NOT public.is_admin_for_org(v_owner_org) THEN RAISE EXCEPTION 'Zone not found or access denied'; END IF;
    UPDATE public.location_zones
      SET boundary = v_final, center_point = ST_Centroid(v_final),
          boundary_status = CASE WHEN v_p.source = 'google_point_radius' THEN 'provisional' ELSE 'authoritative' END,
          boundary_verification = 'unverified', boundary_verified_by = NULL, boundary_verified_at = NULL,
          configuration_version = configuration_version + 1
      WHERE id = v_p.entity_id;
    v_version := public._gbh_next_version('location_zone', v_p.entity_id);
    INSERT INTO public.geofence_boundary_history (entity_type, entity_id, boundary, boundary_source, verification_state, changed_by, changed_via, change_reason, version)
    VALUES ('location_zone', v_p.entity_id, v_final, v_source, 'unverified', v_actor, 'direct_edit',
      format('Accepted boundary proposal %s (%s%s)', v_p.id, v_p.source, CASE WHEN v_edited THEN ', human-edited' ELSE '' END), v_version);
  ELSE
    -- Org jurisdiction is SENSITIVE (Q5): it must go through the governed proposal flow.
    RAISE EXCEPTION 'Entity type % cannot be accepted through the workbench', v_p.entity_type;
  END IF;

  UPDATE public.boundary_proposals
    SET status = 'accepted', decided_by = v_actor, decided_at = clock_timestamp(), decision_note = p_note,
        final_boundary = v_final, human_edited = v_edited, history_version = v_version
    WHERE id = v_p.id;

  IF p_verify THEN
    PERFORM public.verify_boundary(v_p.entity_type, v_p.entity_id);
  END IF;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_p.organization_id, v_actor, 'boundary_proposal_accepted', v_p.entity_type || 's', v_p.entity_id,
    jsonb_build_object('proposal_id', v_p.id, 'source', v_p.source, 'human_edited', v_edited, 'area_m2', round(v_area), 'verified', p_verify, 'history_version', v_version));

  RETURN QUERY SELECT v_p.entity_type, v_p.entity_id, v_area, v_edited, p_verify, v_version;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."accept_boundary_proposal"(p_proposal_id uuid, p_final_geojson jsonb, p_verify boolean, p_note text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."accept_boundary_proposal"(p_proposal_id uuid, p_final_geojson jsonb, p_verify boolean, p_note text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."accept_boundary_proposal"(p_proposal_id uuid, p_final_geojson jsonb, p_verify boolean, p_note text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."accept_boundary_proposal"(p_proposal_id uuid, p_final_geojson jsonb, p_verify boolean, p_note text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."accept_client_capability_share"(p_token text)
 RETURNS service_agreements
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_invite public.onboarding_invites%rowtype;
  v_agreement public.service_agreements%rowtype;
  v_hash text := encode(extensions.digest(coalesce(p_token, ''), 'sha256'), 'hex');
BEGIN
  SELECT * INTO v_invite FROM public.onboarding_invites
  WHERE token_hash = v_hash AND invite_kind IN ('reporting_share', 'finance_share')
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Invite not found'; END IF;
  IF v_invite.status <> 'pending' THEN RAISE EXCEPTION 'Invite is no longer pending'; END IF;
  IF v_invite.expires_at < now() THEN
    UPDATE public.onboarding_invites SET status = 'expired' WHERE id = v_invite.id;
    RAISE EXCEPTION 'Invite has expired';
  END IF;

  SELECT * INTO v_agreement FROM public.service_agreements WHERE id = v_invite.service_agreement_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Service agreement not found'; END IF;

  IF v_invite.invite_kind = 'reporting_share' THEN
    UPDATE public.service_agreements SET client_portal_reports_enabled = true WHERE id = v_agreement.id RETURNING * INTO v_agreement;
  ELSE
    UPDATE public.service_agreements SET client_portal_finance_enabled = true WHERE id = v_agreement.id RETURNING * INTO v_agreement;
  END IF;

  UPDATE public.onboarding_invites SET status = 'accepted', accepted_at = now() WHERE id = v_invite.id;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_agreement.provider_organization_id, auth.uid(), 'client_capability_share_accepted', 'service_agreements', v_agreement.id, jsonb_build_object('invite_kind', v_invite.invite_kind));

  RETURN v_agreement;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."accept_client_capability_share"(p_token text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."accept_client_capability_share"(p_token text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."accept_client_capability_share"(p_token text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."accept_client_capability_share"(p_token text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."accept_client_invitation"()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_profile public.user_profiles%rowtype;
  v_client_name text;
  v_accepted integer := 0;
  v_row record;
  v_inviter uuid;
begin
  select * into v_profile from public.user_profiles where id = v_actor and deactivated_at is null;
  if not found then raise exception 'Active user required'; end if;
  select name into v_client_name from public.organizations where id = v_profile.organization_id;

  for v_row in
    update public.service_agreements a
    set invitation_status = 'accepted'
    where a.client_organization_id = v_profile.organization_id
      and a.invitation_status = 'invited'
    returning a.id, a.name, a.agreement_type, a.provider_organization_id
  loop
    v_accepted := v_accepted + 1;
    insert into public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
    values (v_row.provider_organization_id, v_actor, 'client_invitation_accepted', 'service_agreements', v_row.id,
      jsonb_build_object('client_organization_id', v_profile.organization_id, 'agreement_name', v_row.name, 'agreement_type', v_row.agreement_type, 'accepted_by_role', v_profile.role));

    -- whoever prepared the invitation hears first, by name; the agreement holder's administrators as a role
    select l.actor_user_id into v_inviter
    from public.audit_log l
    where l.action = 'crm_client_invitation_prepared' and l.target_id = v_row.id
    order by l.created_at desc limit 1;
    if v_inviter is not null then
      perform public.enqueue_notification(
        p_organization_id => v_row.provider_organization_id, p_category => 'crm_client',
        p_title => coalesce(v_client_name, 'The client') || ' has accepted your invitation',
        p_body => coalesce(v_profile.display_name, 'Their administrator') || ' set their password and can sign in to the client portal. Finish the provider setup, then activate the account.',
        p_severity => 'info', p_recipient_user_id => v_inviter, p_recipient_role => null, p_link_page => 'crm',
        p_link_payload => jsonb_build_object('account_organization_id', v_profile.organization_id, 'agreement_id', v_row.id),
        p_dedup_key => 'crm_client_accepted:' || v_row.id::text || ':' || v_inviter::text);
    end if;
    -- the inviter already has their own row; an admin inviter would otherwise read the same news twice
    if v_inviter is null or not exists (select 1 from public.user_profiles p where p.id = v_inviter and p.role IN ('admin', 'admin_officer') and p.deactivated_at is null) then
    perform public.enqueue_notification(
      p_organization_id => v_row.provider_organization_id, p_category => 'crm_client',
      p_title => coalesce(v_client_name, 'A client') || ' has accepted the invitation',
      p_body => coalesce(v_profile.display_name, 'Their administrator') || ' can now sign in to the client portal.',
      p_severity => 'info', p_recipient_user_id => null, p_recipient_role => 'admin', p_link_page => 'crm',
      p_link_payload => jsonb_build_object('account_organization_id', v_profile.organization_id, 'agreement_id', v_row.id),
      p_dedup_key => 'crm_client_accepted:' || v_row.id::text || ':admin');
    end if;
  end loop;
  return jsonb_build_object('accepted', v_accepted, 'organization_id', v_profile.organization_id);
end;
$function$;
COMMENT ON FUNCTION "public"."accept_client_invitation"() IS 'Called by an invited user after setting their password: marks every invited agreement naming their organisation as client accepted, audited per agreement. Idempotent (0 when nothing was pending).';
REVOKE ALL ON FUNCTION "public"."accept_client_invitation"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."accept_client_invitation"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."accept_client_invitation"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."accept_client_invitation"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."accept_quote"(p_quote_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_quote            public.quotes%rowtype;
  v_role             text;
  v_caller_org       uuid;
  v_employer_org     uuid;
  v_agreement_id     uuid;
  v_base_rate        numeric;
  v_callout_rate     numeric;
  v_travel_rate      numeric;
  v_site             record;
  v_site_rate        numeric;
begin
  select * into v_quote from public.quotes where id = p_quote_id;
  if not found then
    raise exception 'accept_quote: quote % not found', p_quote_id;
  end if;

  select role, organization_id, employer_organization_id into v_role, v_caller_org, v_employer_org
  from public.user_profiles where id = auth.uid();

  if not (
    public.is_grand_master()
    or (
      v_role in ('master','admin','admin_officer')
      and v_quote.provider_org_id = any(public.get_descendant_organizations(coalesce(v_employer_org, v_caller_org)))
    )
  ) then
    raise exception 'accept_quote: not authorised to accept quotes for this provider';
  end if;

  if v_quote.status = 'accepted' and v_quote.service_agreement_id is not null then
    return v_quote.service_agreement_id;
  end if;

  if v_quote.status not in ('draft','sent') then
    raise exception 'accept_quote: quote status % cannot be accepted', v_quote.status;
  end if;
  if v_quote.client_org_id is null then
    raise exception 'accept_quote: quote has no client organisation; a service agreement requires a real client (set client_org_id before accepting)';
  end if;

  v_agreement_id := v_quote.service_agreement_id;

  if v_agreement_id is null then
    select id into v_agreement_id
    from public.service_agreements
    where provider_organization_id = v_quote.provider_org_id
      and client_organization_id  = v_quote.client_org_id
      and name = v_quote.title
    limit 1;
  end if;

  if v_agreement_id is null then
    insert into public.service_agreements (provider_organization_id, client_organization_id, name, starts_on, agreement_type)
    values (v_quote.provider_org_id, v_quote.client_org_id, v_quote.title, current_date, 'operational')
    returning id into v_agreement_id;
  else
    update public.service_agreements
    set agreement_type = 'operational'
    where id = v_agreement_id;
  end if;

  select avg(unit_charge) into v_base_rate
  from public.quote_lines where quote_id = p_quote_id and kind in ('labour','module') and unit_charge > 0;

  select avg(unit_charge) into v_travel_rate
  from public.quote_lines where quote_id = p_quote_id and kind = 'travel' and unit_charge > 0;

  select avg(unit_charge) into v_callout_rate
  from public.quote_lines where quote_id = p_quote_id and kind in ('platform_fee','custom')
    and unit_charge > 0 and lower(description) like '%callout%';

  if exists (select 1 from public.crm_commercial_settings where service_agreement_id = v_agreement_id) then
    update public.crm_commercial_settings set
      currency            = v_quote.currency,
      base_rate_per_hour  = coalesce(v_base_rate, base_rate_per_hour),
      callout_rate_per_hour = coalesce(v_callout_rate, callout_rate_per_hour),
      travel_rate_per_km  = coalesce(v_travel_rate, travel_rate_per_km)
    where service_agreement_id = v_agreement_id;
  else
    insert into public.crm_commercial_settings
      (service_agreement_id, currency, base_rate_per_hour, callout_rate_per_hour, travel_rate_per_km)
    values
      (v_agreement_id, v_quote.currency, v_base_rate, v_callout_rate, v_travel_rate);
  end if;

  for v_site in
    select distinct site_id from public.quote_lines
    where quote_id = p_quote_id and site_id is not null
  loop
    select avg(unit_charge) into v_site_rate
    from public.quote_lines
    where quote_id = p_quote_id and site_id = v_site.site_id and kind in ('labour','module') and unit_charge > 0;
    v_site_rate := coalesce(v_site_rate, v_base_rate);

    if exists (
      select 1 from public.site_financial_config
      where site_id = v_site.site_id and service_agreement_id = v_agreement_id
    ) then
      update public.site_financial_config set
        billing_model = 'hourly',
        hourly_rate   = coalesce(v_site_rate, hourly_rate),
        updated_at    = now()
      where site_id = v_site.site_id and service_agreement_id = v_agreement_id;
    else
      insert into public.site_financial_config
        (organization_id, site_id, service_agreement_id, billing_model, hourly_rate)
      values
        (v_quote.provider_org_id, v_site.site_id, v_agreement_id, 'hourly', v_site_rate);
    end if;
  end loop;

  update public.quotes set
    status               = 'accepted',
    accepted_at          = now(),
    accepted_by          = auth.uid(),
    service_agreement_id = v_agreement_id,
    updated_by           = auth.uid()
  where id = p_quote_id;

  return v_agreement_id;
end $function$;
COMMENT ON FUNCTION "public"."accept_quote"(p_quote_id uuid) IS 'B5 (#2): accept a Layer 2 quote -> create/link a service_agreement, write crm_commercial_settings + per-site site_financial_config from the quote lines, stamp the quote accepted. Atomic, security-definer, authz = grand_master or provider admin/master. Idempotent; requires a real client_org_id.';
REVOKE ALL ON FUNCTION "public"."accept_quote"(p_quote_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."accept_quote"(p_quote_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."accept_quote"(p_quote_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."accessible_org_ids"()
 RETURNS uuid[]
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(array_agg(distinct reach.org_id) filter (where reach.org_id is not null), array[]::uuid[])
  from user_profiles p
  cross join lateral (
    select p.organization_id
    union all
    select unnest(p.authorized_organization_ids)
    union all
    select unnest(get_descendant_organizations(p.organization_id))
     where p.role in ('grand_master', 'master', 'admin', 'admin_officer')
    union all
    select unnest(get_descendant_organizations(p.employer_organization_id))
     where p.role in ('grand_master', 'master', 'admin', 'admin_officer')
       and p.employer_organization_id is not null
    union all
    select unnest(array[g.provider_organization_id, g.client_organization_id])
      from provider_client_access_grants g
     where (p.organization_id = g.provider_organization_id or p.organization_id = g.client_organization_id)
       and (g.ends_at is null or g.ends_at > now())
    union all
    select sa.client_organization_id
      from service_agreements sa
     where (sa.ends_on is null or sa.ends_on >= current_date)
       and sa.agreement_type = 'operational'
       and (p.organization_id = sa.provider_organization_id
            or p.employer_organization_id = sa.provider_organization_id)
    union all
    select sa.provider_organization_id
      from service_agreements sa
     where (sa.ends_on is null or sa.ends_on >= current_date)
       and sa.agreement_type = 'operational'
       and (p.organization_id = sa.client_organization_id
            or p.employer_organization_id = sa.client_organization_id)
  ) as reach(org_id)
  where p.id = auth.uid()
    and p.deactivated_at is null;
$function$;
COMMENT ON FUNCTION "public"."accessible_org_ids"() IS 'Set form of org_access_allowed for row-level security: the organisations the caller may reach, computed once per statement. Must stay equivalent to org_access_allowed(target) for every target; change both together.';
REVOKE ALL ON FUNCTION "public"."accessible_org_ids"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."accessible_org_ids"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."accessible_org_ids"() TO "anon";
GRANT EXECUTE ON FUNCTION "public"."accessible_org_ids"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."accessible_org_ids"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."acknowledge_operational_continuity_item"(p_client_request_id uuid, p_continuity_item_id uuid, p_acknowledgement_notes text DEFAULT NULL::text, p_continuation_location_event_id uuid DEFAULT NULL::uuid)
 RETURNS operational_continuity_receipts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_item public.operational_continuity_items%rowtype;
  v_receipt public.operational_continuity_receipts%rowtype;
BEGIN
  IF p_client_request_id IS NULL THEN
    RAISE EXCEPTION 'client_request_id is required';
  END IF;

  SELECT receipt.*
  INTO v_receipt
  FROM public.operational_continuity_receipts AS receipt
  WHERE receipt.recipient_organization_id = (
      SELECT item.recipient_organization_id
      FROM public.operational_continuity_items AS item
      WHERE item.id = p_continuity_item_id
    )
    AND receipt.client_request_id = p_client_request_id;

  IF FOUND THEN
    RETURN v_receipt;
  END IF;

  SELECT item.*
  INTO v_item
  FROM public.operational_continuity_items AS item
  WHERE item.id = p_continuity_item_id
  FOR UPDATE;

  IF NOT FOUND OR NOT public.is_admin_for_org(v_item.recipient_organization_id) THEN
    RAISE EXCEPTION 'Continuity item not available to your organization';
  END IF;

  IF v_item.operational_status <> 'active' OR v_item.expires_at < clock_timestamp() THEN
    RAISE EXCEPTION 'Continuity item is no longer active';
  END IF;

  IF p_continuation_location_event_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1
      FROM public.location_events AS continuation
      WHERE continuation.id = p_continuation_location_event_id
        AND continuation.organization_id = v_item.recipient_organization_id
        AND continuation.module_key IS NOT DISTINCT FROM v_item.module_key
        AND continuation.occurred_at >= v_item.source_occurred_at
        AND (
          (v_item.client_site_id IS NOT NULL AND continuation.client_site_id = v_item.client_site_id)
          OR (v_item.zone_id IS NOT NULL AND continuation.zone_id = v_item.zone_id)
        )
    )
  THEN
    RAISE EXCEPTION 'Continuation event must belong to the recipient at the same place and module';
  END IF;

  INSERT INTO public.operational_continuity_receipts (
    continuity_item_id,
    recipient_organization_id,
    acknowledged_by,
    continuation_location_event_id,
    acknowledgement_notes,
    client_request_id
  )
  VALUES (
    v_item.id,
    v_item.recipient_organization_id,
    v_actor,
    p_continuation_location_event_id,
    NULLIF(trim(COALESCE(p_acknowledgement_notes, '')), ''),
    p_client_request_id
  )
  RETURNING * INTO v_receipt;

  INSERT INTO public.audit_log (
    organization_id,
    actor_user_id,
    action,
    target_table,
    target_id,
    metadata
  )
  VALUES (
    v_item.recipient_organization_id,
    v_actor,
    'operational_continuity_acknowledged',
    'operational_continuity_items',
    v_item.id,
    jsonb_build_object(
      'source_organization_id', v_item.source_organization_id,
      'continuation_location_event_id', p_continuation_location_event_id
    )
  );

  RETURN v_receipt;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."acknowledge_operational_continuity_item"(p_client_request_id uuid, p_continuity_item_id uuid, p_acknowledgement_notes text, p_continuation_location_event_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."acknowledge_operational_continuity_item"(p_client_request_id uuid, p_continuity_item_id uuid, p_acknowledgement_notes text, p_continuation_location_event_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."acknowledge_operational_continuity_item"(p_client_request_id uuid, p_continuity_item_id uuid, p_acknowledgement_notes text, p_continuation_location_event_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."acknowledge_operational_continuity_item"(p_client_request_id uuid, p_continuity_item_id uuid, p_acknowledgement_notes text, p_continuation_location_event_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."acknowledge_roster_attendance_exception"(p_shift_id uuid, p_exception_type text, p_notes text)
 RETURNS TABLE(shift_id uuid, acknowledged_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid := auth.uid(); v_shift public.shifts%rowtype; v_user uuid; v_at timestamptz := clock_timestamp(); v_notes text := nullif(trim(coalesce(p_notes, '')), '');
begin
  if v_notes is null then raise exception 'Attendance exception notes are required'; end if;
  if p_exception_type not in ('late_start', 'active_overrun', 'missed') then raise exception 'Unsupported attendance exception type'; end if;
  select s.* into v_shift from public.shifts s where s.id = p_shift_id for update;
  if not found then raise exception 'Shift not found'; end if;
  if not public.is_admin_for_org(v_shift.organization_id) then raise exception 'Roster administrator required'; end if;
  v_user := v_shift.officer_user_id;
  if v_user is null then
    select coalesce(sp.user_id, sp.id) into v_user from public.staff_profiles sp where sp.id = (select rs.staff_id from public.roster_slots rs where rs.linked_shift_id = v_shift.id limit 1);
  end if;
  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (v_shift.organization_id, v_actor, 'roster_attendance_exception_acknowledged', 'shifts', v_shift.id, jsonb_build_object('exception_type', p_exception_type, 'notes', v_notes, 'acknowledged_at', v_at));
  if v_user is not null then
    perform public.enqueue_notification(p_organization_id => v_shift.organization_id, p_category => 'roster',
      p_title => case when p_exception_type = 'missed' then 'Missed shift reviewed' else 'Attendance exception acknowledged' end,
      p_body => v_notes, p_severity => 'warning', p_recipient_user_id => v_user, p_recipient_role => null, p_link_page => 'schedule',
      p_link_payload => jsonb_build_object('shift_id', v_shift.id, 'exception_type', p_exception_type), p_dedup_key => 'attendance_ack:' || v_shift.id::text || ':' || p_exception_type || ':' || extract(epoch from v_at)::bigint::text);
  end if;
  return query select v_shift.id, v_at;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."acknowledge_roster_attendance_exception"(p_shift_id uuid, p_exception_type text, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."acknowledge_roster_attendance_exception"(p_shift_id uuid, p_exception_type text, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."acknowledge_roster_attendance_exception"(p_shift_id uuid, p_exception_type text, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."acknowledge_roster_attendance_exception"(p_shift_id uuid, p_exception_type text, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."acknowledge_safety_briefing"(p_shift_id uuid, p_briefing_hash text, p_client_request_id uuid, p_stop_id uuid DEFAULT NULL::uuid, p_gps_lat double precision DEFAULT NULL::double precision, p_gps_lng double precision DEFAULT NULL::double precision)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_shift public.shifts%rowtype;
  v_briefing jsonb;
  v_existing public.safety_briefing_acknowledgements%rowtype;
  v_ack public.safety_briefing_acknowledgements%rowtype;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_client_request_id IS NULL THEN RAISE EXCEPTION 'client_request_id is required'; END IF;
  SELECT * INTO v_shift FROM public.shifts WHERE id = p_shift_id FOR UPDATE;
  IF NOT FOUND OR v_shift.officer_user_id IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'Only the assigned officer can acknowledge this briefing';
  END IF;
  IF v_shift.status NOT IN ('scheduled', 'published', 'accepted', 'in_progress') THEN
    RAISE EXCEPTION 'This shift is not open for a safety briefing (status %)', v_shift.status;
  END IF;
  IF p_stop_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.shift_stops WHERE id = p_stop_id AND shift_id = p_shift_id
  ) THEN RAISE EXCEPTION 'Stop is not part of this shift'; END IF;

  v_briefing := public.build_shift_safety_briefing(p_shift_id, p_stop_id);
  IF v_briefing->>'briefing_hash' IS DISTINCT FROM p_briefing_hash THEN
    RAISE EXCEPTION 'The safety briefing changed while you were reading it. Review the updated briefing and acknowledge again.'
      USING ERRCODE = 'P0001', HINT = 'briefing_changed';
  END IF;
  SELECT * INTO v_existing FROM public.safety_briefing_acknowledgements
  WHERE officer_user_id = v_actor AND client_request_id = p_client_request_id;
  IF FOUND THEN
    IF v_existing.shift_id IS DISTINCT FROM p_shift_id
      OR v_existing.shift_stop_id IS DISTINCT FROM p_stop_id
      OR v_existing.briefing_hash IS DISTINCT FROM p_briefing_hash THEN
      RAISE EXCEPTION 'This request already acknowledged a different briefing. Reload and confirm again.'
        USING HINT = 'briefing_changed';
    END IF;
    RETURN jsonb_build_object('acknowledgement_id', v_existing.id, 'acknowledged_at', v_existing.acknowledged_at,
      'briefing_hash', v_existing.briefing_hash, 'replayed', true);
  END IF;
  INSERT INTO public.safety_briefing_acknowledgements (
    organization_id, shift_id, shift_stop_id, officer_user_id, briefing_hash,
    hazard_snapshot, item_count, gps_lat, gps_lng, client_request_id
  ) VALUES (
    v_shift.organization_id, p_shift_id, p_stop_id, v_actor, p_briefing_hash,
    v_briefing, (v_briefing->>'item_count')::integer,
    CASE WHEN p_gps_lat BETWEEN -90 AND 90 THEN p_gps_lat END,
    CASE WHEN p_gps_lng BETWEEN -180 AND 180 THEN p_gps_lng END, p_client_request_id
  ) RETURNING * INTO v_ack;
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_shift.organization_id, v_actor, 'safety_briefing_acknowledged', 'safety_briefing_acknowledgements', v_ack.id,
    jsonb_build_object('shift_id', p_shift_id, 'stop_id', p_stop_id, 'item_count', v_ack.item_count, 'briefing_hash', p_briefing_hash));
  RETURN jsonb_build_object('acknowledgement_id', v_ack.id, 'acknowledged_at', v_ack.acknowledged_at,
    'briefing_hash', v_ack.briefing_hash, 'replayed', false);
END;
$function$;
COMMENT ON FUNCTION "public"."acknowledge_safety_briefing"(p_shift_id uuid, p_briefing_hash text, p_client_request_id uuid, p_stop_id uuid, p_gps_lat double precision, p_gps_lng double precision) IS 'The assigned officer acknowledges the exact safety briefing they read. Rejected (hint briefing_changed) if the briefing changed since it was shown. Idempotent on client_request_id; audited.';
REVOKE ALL ON FUNCTION "public"."acknowledge_safety_briefing"(p_shift_id uuid, p_briefing_hash text, p_client_request_id uuid, p_stop_id uuid, p_gps_lat double precision, p_gps_lng double precision) FROM PUBLIC, "anon", "authenticated", "service_role";
