CREATE OR REPLACE FUNCTION "public"."adopt_patrol_source_baseline"(p_batch_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_records jsonb)
 RETURNS TABLE(external_ref text, record_id uuid, outcome text, detail text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_batch public.file_import_batches%rowtype;
  v_item jsonb;
  v_desired jsonb;
  v_payload jsonb;
  v_kind text;
  v_ref text;
  v_id uuid;
  v_version public.patrol_import_record_versions%rowtype;
  v_existing jsonb;
  v_current jsonb;
  v_target jsonb;
  v_before jsonb;
  v_after jsonb;
  v_mismatch text[];
  v_provenance constant text[] := array['source', 'source_file', 'source_sheet', 'source_row', 'source_sha256', 'derivative_sha256', 'classification_profile'];
begin
  v_batch := public.patrol_source_sync_batch(p_batch_id, p_provider_organization_id, p_client_organization_id);
  if jsonb_typeof(p_records) <> 'array' or jsonb_array_length(p_records) > 500 then
    raise exception 'Between 0 and 500 baseline rows are required per call';
  end if;

  for v_item in
    select value from jsonb_array_elements(p_records) value order by value->>'kind', value->>'external_ref'
  loop
    v_payload := public.patrol_source_assert_row_provenance(v_batch, v_item);
    v_kind := v_item->>'kind';
    v_ref := v_item->>'external_ref';
    v_id := (v_item->>'record_id')::uuid;
    v_desired := v_item->'desired';
    perform pg_advisory_xact_lock(hashtextextended(p_client_organization_id::text || ':evidence:' || v_ref, 0));

    if v_kind = 'event' then
      select event.payload into v_existing from public.location_events event
      where event.id = v_id and event.organization_id = p_client_organization_id
        and event.external_ref = v_ref and event.source = 'rm_patrol_log_import'
      for update;
    else
      select observation.external_refs->'import' into v_existing from public.observations observation
      where observation.id = v_id and observation.organization_id = p_client_organization_id
        and observation.external_refs->>'external_ref' = v_ref
        and coalesce(observation.external_refs->'import'->>'source', 'rm_patrol_log_import') = 'rm_patrol_log_import'
      for update;
    end if;
    if not found then
      external_ref := v_ref; record_id := v_id; outcome := 'held'; detail := 'record_not_owned_by_importer';
      return next; continue;
    end if;

    select * into v_version from public.patrol_import_record_versions version
    where version.record_kind = v_kind and version.record_id = v_id and version.is_current;
    if found then
      external_ref := v_ref; record_id := v_id;
      if v_version.source_fingerprint = v_item->>'source_fingerprint' then
        outcome := 'already_current'; detail := null;
      else
        outcome := 'held'; detail := 'baseline_already_recorded';
      end if;
      return next; continue;
    end if;

    if (nullif(v_existing->>'source_file', '') is not null and v_existing->>'source_file' is distinct from v_payload->>'source_file')
       or (nullif(v_existing->>'source_sheet', '') is not null and v_existing->>'source_sheet' is distinct from v_payload->>'source_sheet') then
      external_ref := v_ref; record_id := v_id; outcome := 'held'; detail := 'existing_source_identity_mismatch';
      return next; continue;
    end if;

    v_current := public.patrol_source_record_state(v_kind, v_id);
    v_target := jsonb_build_object(
      'occurred_at', to_char((v_desired->>'occurred_at')::timestamptz at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
      'zone_id', nullif(v_desired->>'zone_id', ''),
      'site_id', nullif(v_desired->>'site_id', ''),
      'distance_km', case when v_desired->'distance_km' is null or jsonb_typeof(v_desired->'distance_km') = 'null' then null else (v_desired->>'distance_km')::numeric end
    ) || case v_kind
      when 'event' then jsonb_build_object(
        'officer_id', nullif(v_desired->>'observed_entity_id', ''),
        'event_type', v_desired->>'event_type',
        'status', v_desired->>'status',
        'observed_entity_type', v_desired->>'observed_entity_type')
      else jsonb_build_object(
        'officer_id', nullif(v_desired->>'officer_id', ''),
        'plate', upper(v_desired->>'plate'),
        'officer_notes', v_desired->>'officer_notes')
    end;

    select coalesce(array_agg(field order by field), '{}'::text[]) into v_mismatch
    from (
      select key as field from jsonb_each(v_target) target
      where (v_current->key) is distinct from target.value
        and not (jsonb_typeof(v_current->key) = 'number' and jsonb_typeof(target.value) = 'number'
                 and (v_current->>key)::numeric = (target.value#>>'{}')::numeric)
      union all
      select 'payload.' || key from (
        select jsonb_object_keys(v_payload || coalesce(v_existing, '{}'::jsonb)) as key
      ) payload_keys
      where key <> all (v_provenance)
        and coalesce(v_existing->key, 'null'::jsonb) is distinct from coalesce(v_payload->key, 'null'::jsonb)
    ) differences;

    if cardinality(v_mismatch) > 0 then
      external_ref := v_ref; record_id := v_id; outcome := 'held';
      detail := 'initial_difference_requires_review:' || array_to_string(v_mismatch, ',');
      return next; continue;
    end if;

    v_before := v_current;
    if v_kind = 'event' then
      update public.location_events event
      set payload = coalesce(event.payload, '{}'::jsonb) || jsonb_build_object(
        'source', v_payload->'source', 'source_file', v_payload->'source_file', 'source_sheet', v_payload->'source_sheet',
        'source_row', v_payload->'source_row', 'source_sha256', v_payload->'source_sha256',
        'derivative_sha256', v_payload->'derivative_sha256', 'classification_profile', v_payload->'classification_profile')
      where event.id = v_id;
    else
      update public.observations observation
      set external_refs = jsonb_set(coalesce(observation.external_refs, '{}'::jsonb), '{import}',
        coalesce(observation.external_refs->'import', '{}'::jsonb) || jsonb_build_object(
          'source', v_payload->'source', 'source_file', v_payload->'source_file', 'source_sheet', v_payload->'source_sheet',
          'source_row', v_payload->'source_row', 'source_sha256', v_payload->'source_sha256',
          'derivative_sha256', v_payload->'derivative_sha256', 'classification_profile', v_payload->'classification_profile'), true)
      where observation.id = v_id;
    end if;
    v_after := public.patrol_source_record_state(v_kind, v_id);

    insert into public.patrol_import_record_versions(
      provider_organization_id, client_organization_id, record_kind, record_id, external_ref, source_profile,
      source_file, source_sheet, source_row, source_sha256, derivative_sha256, source_fingerprint, batch_id,
      version_no, change_kind, changed_fields, state_before, state_after, applied_by
    ) values (
      p_provider_organization_id, p_client_organization_id, v_kind, v_id, v_ref, v_payload->>'classification_profile',
      v_payload->>'source_file', v_payload->>'source_sheet', (v_payload->>'source_row')::integer,
      v_payload->>'source_sha256', v_payload->>'derivative_sha256', v_item->>'source_fingerprint', p_batch_id,
      1, 'baseline', public.patrol_source_state_diff(v_before, v_after), v_before, v_after, auth.uid()
    );

    external_ref := v_ref; record_id := v_id; outcome := 'adopted'; detail := null;
    return next;
  end loop;

  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (p_provider_organization_id, auth.uid(), 'patrol_source_baseline_recorded', 'file_import_batches', p_batch_id,
    jsonb_build_object('client_organization_id', p_client_organization_id, 'rows', jsonb_array_length(p_records)));
end;
$function$;
REVOKE ALL ON FUNCTION "public"."adopt_patrol_source_baseline"(p_batch_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_records jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."adopt_patrol_source_baseline"(p_batch_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_records jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."adopt_patrol_source_baseline"(p_batch_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_records jsonb) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."advance_dispatch_job_status"(p_job_id uuid, p_expected_status text, p_next_status text, p_outcome_notes text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, status text, shift_id uuid, completed_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_job public.dispatch_jobs%rowtype;
  v_allowed boolean := false;
begin
  select * into v_job
  from public.dispatch_jobs
  where dispatch_jobs.id = p_job_id
  for update;

  if not found then raise exception 'Dispatch job not found'; end if;

  if not public.is_admin_for_org(v_job.organization_id) and not exists (
    select 1 from public.dispatch_resources dr
    where dr.id = v_job.dispatch_resource_id
      and dr.assigned_officer_id = auth.uid()
  ) then
    raise exception 'Not authorised to update this dispatch job';
  end if;

  if v_job.status <> p_expected_status then
    raise exception 'Dispatch job changed from expected status % to %', p_expected_status, v_job.status;
  end if;

  v_allowed := case v_job.status
    when 'pending' then p_next_status in ('dispatched', 'cancelled')
    when 'dispatched' then p_next_status in ('acknowledged', 'en_route', 'cancelled')
    when 'acknowledged' then p_next_status in ('en_route', 'cancelled')
    when 'en_route' then p_next_status in ('on_scene', 'cancelled')
    when 'on_scene' then p_next_status in ('completed', 'cancelled')
    else false
  end;

  if not v_allowed then
    raise exception 'Invalid dispatch transition from % to %', v_job.status, p_next_status;
  end if;

  if p_next_status in ('completed', 'cancelled') and nullif(trim(p_outcome_notes), '') is null then
    raise exception 'Outcome notes are required for terminal dispatch transitions';
  end if;

  update public.dispatch_jobs
  set status = p_next_status,
      acknowledged_at = case when p_next_status = 'acknowledged' then now() else dispatch_jobs.acknowledged_at end,
      en_route_at = case when p_next_status = 'en_route' then now() else dispatch_jobs.en_route_at end,
      on_scene_at = case when p_next_status = 'on_scene' then now() else dispatch_jobs.on_scene_at end,
      completed_at = case when p_next_status = 'completed' then now() else dispatch_jobs.completed_at end,
      outcome_notes = case when p_next_status in ('completed', 'cancelled') then nullif(trim(p_outcome_notes), '') else dispatch_jobs.outcome_notes end
  where dispatch_jobs.id = p_job_id;

  if p_next_status in ('completed', 'cancelled') and v_job.dispatch_resource_id is not null and not exists (
    select 1 from public.dispatch_jobs other
    where other.dispatch_resource_id = v_job.dispatch_resource_id
      and other.id <> p_job_id
      and other.status in ('dispatched', 'acknowledged', 'en_route', 'on_scene')
  ) then
    update public.dispatch_resources
    set status = 'available'
    where dispatch_resources.id = v_job.dispatch_resource_id;
  end if;

  -- Live financials on completion. Pay and charge lines are written now (unmatched rules
  -- become 'UNRESOLVED' rows for finance review); a failure here is recorded, not raised,
  -- so the officer's completion is never lost.
  if p_next_status = 'completed' then
    begin
      perform public.resolve_dispatch_job_financials_internal(auth.uid(), gen_random_uuid(), p_job_id, null);
    exception when others then
      insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
      values (v_job.organization_id, auth.uid(), 'dispatch_financials_auto_resolution_failed', 'dispatch_jobs', p_job_id, jsonb_build_object('error', sqlerrm));
    end;
  end if;

  return query select p_job_id, p_next_status, v_job.shift_id,
    case when p_next_status = 'completed' then now() else v_job.completed_at end;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."advance_dispatch_job_status"(p_job_id uuid, p_expected_status text, p_next_status text, p_outcome_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."advance_dispatch_job_status"(p_job_id uuid, p_expected_status text, p_next_status text, p_outcome_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."advance_dispatch_job_status"(p_job_id uuid, p_expected_status text, p_next_status text, p_outcome_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."advance_dispatch_job_status"(p_job_id uuid, p_expected_status text, p_next_status text, p_outcome_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."advance_workshop_work_order_status"(p_work_order_id uuid, p_status text, p_note text DEFAULT NULL::text)
 RETURNS workshop_work_orders
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_wo public.workshop_work_orders%rowtype;
  v_actor uuid := auth.uid();
  v_line record;
  v_tx public.finance_inventory_transactions%rowtype;
  v_on_hand numeric;
  v_is_admin boolean;
begin
  select * into v_wo from public.workshop_work_orders w where w.id = p_work_order_id for update;
  if not found then raise exception 'Work order not found'; end if;
  v_is_admin := public.is_admin_for_org(v_wo.organization_id);
  -- The assigned worker may start and complete; approving, cancelling and re-opening stay with an administrator.
  if not (v_is_admin or (v_wo.assigned_user_id = v_actor and p_status in ('in_progress', 'completed'))) then
    raise exception 'Only a workshop administrator or the assigned worker can move this work order';
  end if;
  if v_wo.status = p_status then return v_wo; end if;
  if not (
       (v_wo.status = 'draft' and p_status in ('approved', 'cancelled'))
    or (v_wo.status = 'approved' and p_status in ('in_progress', 'cancelled', 'draft'))
    or (v_wo.status = 'in_progress' and p_status in ('completed', 'cancelled'))
  ) then
    raise exception 'A % work order cannot move to %', v_wo.status, p_status;
  end if;

  if p_status = 'completed' then
    if not exists (select 1 from public.workshop_work_order_lines l where l.work_order_id = v_wo.id) then
      raise exception 'Add at least one line (materials, labour or travel) before completing';
    end if;
    -- Strict stock draw-down when the order names a stock location: every material/equipment line with a
    -- price-book item is consumed there. A shortfall stops completion with a plain message.
    if v_wo.inventory_location_id is not null then
      if not v_is_admin then
        raise exception 'This order draws stock from a location, so a workshop administrator must complete it (or clear the stock location first)';
      end if;
      for v_line in select l.* from public.workshop_work_order_lines l
                     where l.work_order_id = v_wo.id and l.line_kind in ('material', 'equipment') and l.item_id is not null and l.inventory_transaction_id is null
                     order by l.position loop
        select coalesce(b.on_hand - b.reserved, 0) into v_on_hand from public.finance_inventory_balances b where b.item_id = v_line.item_id and b.location_id = v_wo.inventory_location_id;
        if coalesce(v_on_hand, 0) < v_line.quantity then
          raise exception 'Not enough "%" in stock at this location (on hand %, needed %). Record the stock receipt first, or clear the stock location on the work order.',
            v_line.description, coalesce(v_on_hand, 0), v_line.quantity;
        end if;
        v_tx := public.record_finance_inventory_transaction(
          v_line.item_id, v_wo.inventory_location_id, 'consumption', v_line.quantity, v_line.unit_cost,
          'workshop_line:' || v_line.id::text, 'workshop_work_order:' || v_wo.order_number, null, v_wo.asset_id, null, null);
        update public.workshop_work_order_lines set inventory_transaction_id = v_tx.id where id = v_line.id;
      end loop;
    end if;
    update public.workshop_work_orders
       set status = 'completed', completed_at = now(), completion_note = nullif(trim(coalesce(p_note, '')), ''), updated_at = now(), updated_by = v_actor
     where id = v_wo.id returning * into v_wo;
  elsif p_status = 'in_progress' then
    update public.workshop_work_orders set status = 'in_progress', started_at = coalesce(started_at, now()), updated_at = now(), updated_by = v_actor where id = v_wo.id returning * into v_wo;
  elsif p_status = 'cancelled' then
    update public.workshop_work_orders set status = 'cancelled', cancelled_at = now(), completion_note = nullif(trim(coalesce(p_note, '')), ''), updated_at = now(), updated_by = v_actor where id = v_wo.id returning * into v_wo;
  else
    update public.workshop_work_orders set status = p_status, updated_at = now(), updated_by = v_actor where id = v_wo.id returning * into v_wo;
  end if;

  insert into public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (v_wo.organization_id, v_actor, 'workshop_work_order_' || p_status, 'workshop_work_orders', v_wo.id,
          jsonb_build_object('order_number', v_wo.order_number, 'kind', v_wo.kind, 'note', nullif(trim(coalesce(p_note, '')), ''),
                             'charge_total', (select coalesce(sum(line_total), 0) from public.workshop_work_order_lines where work_order_id = v_wo.id)));
  return v_wo;
end;
$function$;
COMMENT ON FUNCTION "public"."advance_workshop_work_order_status"(p_work_order_id uuid, p_status text, p_note text) IS 'draft→approved→in_progress→completed (cancel from any open state). Completion draws material/equipment lines down from the named stock location through record_finance_inventory_transaction and leaves the lines billable for generate_crm_invoice_from_completed_work.';
REVOKE ALL ON FUNCTION "public"."advance_workshop_work_order_status"(p_work_order_id uuid, p_status text, p_note text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."advance_workshop_work_order_status"(p_work_order_id uuid, p_status text, p_note text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."advance_workshop_work_order_status"(p_work_order_id uuid, p_status text, p_note text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."agreement_commercial_model"(p_service_agreement_id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT c.commercial_model FROM public.crm_commercial_settings c WHERE c.service_agreement_id = p_service_agreement_id;
$function$;
COMMENT ON FUNCTION "public"."agreement_commercial_model"(p_service_agreement_id uuid) IS 'Internal: the commercial model of one service agreement, NULL when not set or when there is no agreement.';
REVOKE ALL ON FUNCTION "public"."agreement_commercial_model"(p_service_agreement_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."agreement_commercial_model"(p_service_agreement_id uuid) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."agreement_fee_drawdown_month"(p_service_agreement_id uuid, p_month date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_agreement public.service_agreements%ROWTYPE;
  v_comm public.crm_commercial_settings%ROWTYPE;
  v_start date := date_trunc('month', p_month)::date;
  v_end date := (date_trunc('month', p_month) + interval '1 month - 1 day')::date;
  v_today date := (now() AT TIME ZONE 'Pacific/Auckland')::date;
  v_label text := to_char(date_trunc('month', p_month), 'FMMonth YYYY');
  v_fee numeric(12,2);
  v_fee_source text;
  v_quote_lines integer;
  v_imported record;
  v_callout record;
  v_patrol record;
  v_work numeric(12,2);
  v_balance numeric(12,2);
  v_blockers jsonb := '[]'::jsonb;
  v_settlement jsonb;
BEGIN
  IF p_month IS NULL THEN RAISE EXCEPTION 'Choose a month'; END IF;
  SELECT * INTO v_agreement FROM public.service_agreements WHERE id = p_service_agreement_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Service agreement not found'; END IF;
  SELECT * INTO v_comm FROM public.crm_commercial_settings WHERE service_agreement_id = v_agreement.id;

  SELECT count(*)::integer, round(coalesce(sum(ql.quantity * ql.unit_charge), 0), 2)
    INTO v_quote_lines, v_fee
  FROM public.quotes q JOIN public.quote_lines ql ON ql.quote_id = q.id
  WHERE q.service_agreement_id = v_agreement.id AND q.status = 'accepted';
  IF v_quote_lines > 0 THEN
    v_fee_source := 'accepted_quote';
  ELSIF coalesce(v_comm.base_rate_per_hour, 0) > 0 THEN
    v_fee := v_comm.base_rate_per_hour; v_fee_source := 'agreement_rate';
  ELSE
    v_fee := NULL;
  END IF;

  SELECT count(*)::integer AS rows_total,
    round(coalesce(sum(r.amount) FILTER (WHERE c.basis = 'contract'), 0), 2) AS contract_amount,
    count(*) FILTER (WHERE c.basis = 'contract')::integer AS contract_rows,
    round(coalesce(sum(r.amount) FILTER (WHERE c.basis = 'extra'), 0), 2) AS extra_amount,
    count(*) FILTER (WHERE c.basis = 'unclassified')::integer AS unclassified_rows,
    round(coalesce(sum(r.amount) FILTER (WHERE c.basis = 'unclassified'), 0), 2) AS unclassified_amount
    INTO v_imported
  FROM public.file_import_finance_cost_rows r
  CROSS JOIN LATERAL public.classify_patrol_cost_row_billing_basis(v_agreement.provider_organization_id, r.source_values) c
  WHERE r.service_agreement_id = v_agreement.id AND r.status = 'applied' AND r.service_date BETWEEN v_start AND v_end;

  SELECT count(*)::integer AS lines_total,
    round(coalesce(sum(l.line_total) FILTER (WHERE l.billing_basis = 'contract'), 0), 2) AS contract_amount,
    count(*) FILTER (WHERE l.billing_basis = 'contract')::integer AS contract_lines,
    count(*) FILTER (WHERE l.billing_basis IS NULL)::integer AS undecided_lines,
    count(*) FILTER (WHERE l.rate_rule_id IS NULL AND coalesce(l.billing_basis, 'contract') = 'contract')::integer AS unpriced_lines
    INTO v_callout
  FROM public.dispatch_job_charge_lines l
  WHERE l.service_agreement_id = v_agreement.id
    AND (l.created_at AT TIME ZONE 'Pacific/Auckland')::date BETWEEN v_start AND v_end;

  SELECT count(*)::integer AS lines_total,
    round(coalesce(sum(l.line_total) FILTER (WHERE l.status IN ('ready', 'waived_sla', 'invoiced')), 0), 2) AS amount,
    count(*) FILTER (WHERE l.status IN ('ready', 'waived_sla', 'invoiced'))::integer AS visits,
    count(*) FILTER (WHERE l.status LIKE 'unresolved%')::integer AS unresolved_lines
    INTO v_patrol
  FROM public.patrol_stop_charge_lines l
  WHERE l.service_agreement_id = v_agreement.id
    AND (l.created_at AT TIME ZONE 'Pacific/Auckland')::date BETWEEN v_start AND v_end;

  v_work := v_imported.contract_amount + v_callout.contract_amount + v_patrol.amount;
  v_balance := CASE WHEN v_fee IS NOT NULL THEN v_fee - v_work END;

  IF v_fee IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object('code', 'no_fee', 'message',
      'No monthly fee is recorded for this agreement. Record it as an accepted quote line before settling a month.');
  END IF;
  IF v_end >= v_today THEN
    v_blockers := v_blockers || jsonb_build_object('code', 'month_not_finished', 'message',
      format('%s has not finished. A month is settled once it is over.', v_label));
  END IF;
  IF v_imported.unclassified_rows > 0 THEN
    v_blockers := v_blockers || jsonb_build_object('code', 'unclassified_imported_rows', 'message',
      format('%s imported patrol row(s) worth %s in %s are not marked Contract or Extra. Give their charge codes a billing basis first.',
        v_imported.unclassified_rows, to_char(v_imported.unclassified_amount, 'FM$999,999,990.00'), v_label));
  END IF;
  IF v_callout.undecided_lines > 0 THEN
    v_blockers := v_blockers || jsonb_build_object('code', 'undecided_callouts', 'message',
      format('%s callout charge line(s) in %s have no Contract or Extra decision.', v_callout.undecided_lines, v_label));
  END IF;
  IF v_callout.unpriced_lines > 0 THEN
    v_blockers := v_blockers || jsonb_build_object('code', 'unpriced_callouts', 'message',
      format('%s contracted callout charge line(s) in %s have no rate. Price them first.', v_callout.unpriced_lines, v_label));
  END IF;
  IF v_patrol.unresolved_lines > 0 THEN
    v_blockers := v_blockers || jsonb_build_object('code', 'unresolved_patrol_visits', 'message',
      format('%s patrol visit charge line(s) in %s have no rate or agreement.', v_patrol.unresolved_lines, v_label));
  END IF;
  IF v_imported.rows_total = 0 AND v_callout.lines_total = 0 AND v_patrol.lines_total = 0 THEN
    v_blockers := v_blockers || jsonb_build_object('code', 'no_work_recorded', 'message',
      format('No work is recorded for %s. Import or record the month''s work first, otherwise the whole fee would be credited.', v_label));
  END IF;

  SELECT jsonb_build_object('id', s.id, 'outcome', s.outcome, 'adjustment_amount', s.adjustment_amount,
      'overrun_decision', s.overrun_decision, 'justification', s.justification, 'invoice_id', i.id,
      'invoice_number', i.invoice_number, 'invoice_status', i.status, 'created_at', s.created_at)
    INTO v_settlement
  FROM public.agreement_fee_settlements s JOIN public.invoices i ON i.id = s.invoice_id
  WHERE s.service_agreement_id = v_agreement.id AND s.period_start = v_start AND i.status <> 'void';

  RETURN jsonb_build_object(
    'month', to_char(v_start, 'YYYY-MM'), 'label', v_label, 'period_start', v_start, 'period_end', v_end,
    'fee', v_fee, 'fee_source', v_fee_source,
    'contract_work', jsonb_build_object(
      'imported', jsonb_build_object('amount', v_imported.contract_amount, 'rows', v_imported.contract_rows,
        'extra_amount', v_imported.extra_amount, 'unclassified_rows', v_imported.unclassified_rows,
        'unclassified_amount', v_imported.unclassified_amount),
      'callouts', jsonb_build_object('amount', v_callout.contract_amount, 'lines', v_callout.contract_lines,
        'undecided_lines', v_callout.undecided_lines, 'unpriced_lines', v_callout.unpriced_lines),
      'patrol_visits', jsonb_build_object('amount', v_patrol.amount, 'lines', v_patrol.visits,
        'unresolved_lines', v_patrol.unresolved_lines),
      'total', v_work),
    'balance', v_balance,
    'outcome', CASE WHEN v_balance IS NULL THEN NULL WHEN v_balance > 0 THEN 'credit' WHEN v_balance < 0 THEN 'overrun' ELSE 'balanced' END,
    'overrun_policy', coalesce(v_comm.fee_overrun_policy, 'justify'),
    'blockers', v_blockers,
    'settlement', v_settlement);
END;
$function$;
COMMENT ON FUNCTION "public"."agreement_fee_drawdown_month"(p_service_agreement_id uuid, p_month date) IS 'Internal: the monthly fee drawdown for one agreement and calendar month: fee (accepted quote lines, else the agreement rate), contracted work by source (imported patrol rows classified Contract, Contract callout charge lines, patrol visit charge lines; NZ dates), balance = fee - work, the outcome it would produce, what blocks settling it, and the existing non-void settlement.';
REVOKE ALL ON FUNCTION "public"."agreement_fee_drawdown_month"(p_service_agreement_id uuid, p_month date) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."agreement_fee_drawdown_month"(p_service_agreement_id uuid, p_month date) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."agreement_service_delivery"(p_agreement_id uuid, p_period_start date, p_period_end date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_agreement public.service_agreements%rowtype;
  v_start timestamptz := p_period_start::timestamptz;
  v_end timestamptz := (p_period_end + 1)::timestamptz;
  v_providers uuid[];
  v_places jsonb;
  v_totals jsonb;
  v_responses jsonb;
begin
  select * into v_agreement from public.service_agreements a where a.id = p_agreement_id;
  if not found then raise exception 'Service agreement not found'; end if;
  v_providers := public.get_descendant_organizations(v_agreement.provider_organization_id);

  with places as (
    select sal.id as location_id, sal.site_id, sal.zone_id,
      coalesce(s.name, z.name) as place_name,
      case when s.id is not null then 'site' else 'zone' end as place_kind
    from public.service_agreement_locations sal
    left join public.client_sites s on s.id = sal.site_id
    left join public.location_zones z on z.id = sal.zone_id
    where sal.service_agreement_id = v_agreement.id and sal.status = 'active'
  ), stops as (
    select ss.*, sh.scheduled_start, sh.actual_start, sh.actual_end, sh.status as shift_status,
      p.location_id
    from public.shift_stops ss
    join public.shifts sh on sh.id = ss.shift_id
    join places p on (p.site_id is not null and p.site_id = ss.site_id) or (p.zone_id is not null and p.zone_id = ss.zone_id)
    where sh.organization_id = any(v_providers)
      and sh.status <> 'cancelled'
      and sh.scheduled_start >= v_start
      and sh.scheduled_start < least(v_end, now())
  ), per_place as (
    select p.location_id, p.place_name, p.place_kind,
      count(st.id) filter (where st.module_key is distinct from 'static_guarding') as patrol_expected,
      count(st.id) filter (where st.module_key is distinct from 'static_guarding' and st.status = 'completed') as patrol_completed,
      count(st.id) filter (where st.module_key is distinct from 'static_guarding' and st.status in ('skipped', 'cancelled', 'missed')) as patrol_missed,
      count(st.id) filter (where st.module_key is distinct from 'static_guarding' and st.status = 'completed' and st.sla_status = 'breached') as patrol_late,
      count(st.id) filter (where st.module_key = 'static_guarding') as post_expected,
      count(st.id) filter (where st.module_key = 'static_guarding' and st.actual_arrived_at is not null) as post_attended,
      coalesce(sum(case when st.module_key = 'static_guarding' and st.actual_arrived_at is not null
        then greatest(0, extract(epoch from (coalesce(st.actual_departed_at, st.actual_end, now()) - st.actual_arrived_at)) / 60) end), 0)::integer as post_minutes,
      max(coalesce(st.actual_departed_at, st.actual_arrived_at)) as last_presence_at,
      count(distinct st.shift_id) as shift_count
    from places p
    left join stops st on st.location_id = p.location_id
    group by p.location_id, p.place_name, p.place_kind
  )
  select coalesce(jsonb_agg(jsonb_build_object(
      'location_id', location_id, 'place_name', place_name, 'place_kind', place_kind,
      'patrol_expected', patrol_expected, 'patrol_completed', patrol_completed, 'patrol_missed', patrol_missed, 'patrol_late', patrol_late,
      'post_expected', post_expected, 'post_attended', post_attended, 'post_minutes', post_minutes,
      'last_presence_at', last_presence_at, 'shift_count', shift_count
    ) order by place_name), '[]'::jsonb),
    jsonb_build_object(
      'patrol_expected', coalesce(sum(patrol_expected), 0), 'patrol_completed', coalesce(sum(patrol_completed), 0),
      'patrol_missed', coalesce(sum(patrol_missed), 0), 'patrol_late', coalesce(sum(patrol_late), 0),
      'post_expected', coalesce(sum(post_expected), 0), 'post_attended', coalesce(sum(post_attended), 0),
      'post_minutes', coalesce(sum(post_minutes), 0), 'place_count', count(*)
    )
  into v_places, v_totals
  from per_place;


  -- Responses: dispatch jobs raised under this agreement (alarm responses, incidents, welfare checks...). The clock
  -- runs from the alarm when one is recorded (record_alarm_signal), otherwise from when the job was raised.
  with jobs as (
    select j.id, j.job_type, j.status, j.sla_minutes, j.on_scene_at,
      coalesce(e.received_at, j.created_at) as raised_at
    from public.dispatch_jobs j
    left join public.alarm_events e on e.dispatch_job_id = j.id
    where j.service_agreement_id = v_agreement.id
      and j.organization_id = any(v_providers)
      and j.status <> 'cancelled'
      and coalesce(e.received_at, j.created_at) >= v_start
      and coalesce(e.received_at, j.created_at) < v_end
  ), typed as (
    select job_type, count(*) as n from jobs group by job_type
  )
  select jsonb_build_object(
    'count', (select count(*) from jobs),
    'attended', (select count(*) from jobs where on_scene_at is not null),
    'within_target', (select count(*) from jobs where on_scene_at is not null and sla_minutes is not null and on_scene_at <= raised_at + make_interval(mins => sla_minutes)),
    'over_target', (select count(*) from jobs where on_scene_at is not null and sla_minutes is not null and on_scene_at > raised_at + make_interval(mins => sla_minutes)),
    'still_open', (select count(*) from jobs where on_scene_at is null and status <> 'completed'),
    'median_minutes_to_scene', (select round(percentile_cont(0.5) within group (order by extract(epoch from (on_scene_at - raised_at)) / 60.0)::numeric, 1) from jobs where on_scene_at is not null),
    'slowest_minutes_to_scene', (select round((max(extract(epoch from (on_scene_at - raised_at))) / 60.0)::numeric, 1) from jobs where on_scene_at is not null),
    'by_type', (select coalesce(jsonb_object_agg(job_type, n), '{}'::jsonb) from typed)
  ) into v_responses;

  return jsonb_build_object(
    'agreement_id', v_agreement.id,
    'period_start', p_period_start,
    'period_end', p_period_end,
    'places', v_places,
    'totals', v_totals,
    'responses', v_responses
  );
end;
$function$;
COMMENT ON FUNCTION "public"."agreement_service_delivery"(p_agreement_id uuid, p_period_start date, p_period_end date) IS 'Internal assembler: per agreement place, contracted patrol stops expected/completed/missed/late and static-post attendances and minutes on post in the period; plus responses (dispatch jobs under the agreement: attended, within/over target from the alarm or the job, median minutes to scene). No officer identities. Auth is on get_agreement_service_delivery.';
REVOKE ALL ON FUNCTION "public"."agreement_service_delivery"(p_agreement_id uuid, p_period_start date, p_period_end date) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."agreement_service_delivery"(p_agreement_id uuid, p_period_start date, p_period_end date) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."agreement_uses_contract_extra"(p_service_agreement_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT coalesce(public.agreement_commercial_model(p_service_agreement_id), 'fixed_price_with_extras') = 'fixed_price_with_extras';
$function$;
COMMENT ON FUNCTION "public"."agreement_uses_contract_extra"(p_service_agreement_id uuid) IS 'Internal: true when callouts on this agreement need a Contract/Extra decision (fixed price + Extra, or model not set). False for pay as you go, do and invoice, and per request, where all completed work is billed.';
REVOKE ALL ON FUNCTION "public"."agreement_uses_contract_extra"(p_service_agreement_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."agreement_uses_contract_extra"(p_service_agreement_id uuid) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."apply_biosecurity_photo_review_to_perception"(p_assessment_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_assessment public.biosecurity_assessments%rowtype;
  v_envelope public.perception_evidence_envelopes%rowtype;
  v_field public.perception_evidence_fields%rowtype;
  v_review jsonb;
  v_actor uuid;
  v_short_key text;
  v_value_key text;
  v_final_value text;
  v_target_authority text;
  v_decision text;
  v_correction_field_id uuid;
BEGIN
  SELECT * INTO v_assessment
  FROM public.biosecurity_assessments
  WHERE id = p_assessment_id;
  IF NOT FOUND THEN RETURN; END IF;

  v_review := v_assessment.biosecurity_ai_review;
  IF jsonb_typeof(v_review) IS DISTINCT FROM 'object'
     OR v_review->>'status' NOT IN ('confirmed','corrected','rejected') THEN
    RETURN;
  END IF;
  v_actor := nullif(v_review->>'reviewed_by', '')::uuid;
  IF v_actor IS NULL THEN RETURN; END IF;

  FOR v_envelope IN
    SELECT e.*
    FROM public.perception_evidence_envelopes e
    WHERE e.organization_id = v_assessment.organization_id
      AND e.domain = 'biosecurity_photo'
      AND e.source_receipt->>'biosecurity_assessment_id' = v_assessment.id::text
  LOOP
    FOR v_field IN
      SELECT f.*
      FROM public.perception_evidence_fields f
      WHERE f.envelope_id = v_envelope.id
      ORDER BY f.field_key, f.candidate_ordinal
    LOOP
      v_short_key := replace(replace(v_field.field_key, 'biosecurity.', ''), '_candidate', '');
      v_value_key := CASE v_short_key
        WHEN 'species' THEN 'species_name'
        WHEN 'density' THEN 'density_estimate'
        WHEN 'threat_level' THEN 'threat_level'
        ELSE v_short_key
      END;
      IF NOT coalesce(v_review->'reviewed_fields', '[]'::jsonb) ? v_value_key THEN
        CONTINUE;
      END IF;

      v_final_value := coalesce(v_review#>>ARRAY['values', v_value_key], v_field.candidate_value);
      v_target_authority := CASE
        WHEN v_review->>'status' = 'rejected' THEN 'rejected'
        WHEN lower(coalesce(v_field.normalized_value, v_field.candidate_value)) = lower(v_final_value)
          THEN 'human_approved'
        ELSE 'superseded'
      END;
      v_decision := CASE
        WHEN v_target_authority = 'rejected' THEN 'reject'
        WHEN v_target_authority = 'superseded' THEN 'supersede'
        ELSE 'approve'
      END;

      IF v_field.authority_state IS DISTINCT FROM v_target_authority OR v_field.review_required THEN
        INSERT INTO public.perception_evidence_reviews (
          organization_id, field_id, previous_authority_state, decision,
          next_authority_state, reviewer_notes, canonical_reference, decided_by
        ) VALUES (
          v_assessment.organization_id, v_field.id, v_field.authority_state, v_decision,
          v_target_authority, nullif(trim(v_review->>'notes'), ''),
          jsonb_strip_nulls(jsonb_build_object(
            'biosecurity_assessment_id', v_assessment.id,
            'field', v_value_key,
            'final_value', v_final_value,
            'review_status', v_review->>'status'
          )),
          v_actor
        );
        UPDATE public.perception_evidence_fields
        SET authority_state = v_target_authority,
            review_required = false,
            updated_at = clock_timestamp()
        WHERE id = v_field.id;
      END IF;

      IF v_target_authority = 'superseded' AND v_final_value IS NOT NULL THEN
        INSERT INTO public.perception_evidence_fields (
          organization_id, envelope_id, field_key, candidate_ordinal, value_type,
          candidate_value, normalized_value, candidate_payload, source_locations,
          consensus_rule, authority_state, review_required
        ) VALUES (
          v_assessment.organization_id, v_envelope.id, v_field.field_key, 1, v_field.value_type,
          v_final_value, lower(trim(v_final_value)),
          jsonb_build_object('human_correction', true),
          jsonb_build_array(jsonb_build_object('biosecurity_assessment_id', v_assessment.id)),
          'explicit_human_biosecurity_correction_v1', 'candidate', true
        )
        ON CONFLICT (envelope_id, field_key, candidate_ordinal) DO UPDATE
        SET candidate_value = EXCLUDED.candidate_value,
            normalized_value = EXCLUDED.normalized_value,
            candidate_payload = EXCLUDED.candidate_payload,
            updated_at = clock_timestamp()
        RETURNING id INTO v_correction_field_id;

        INSERT INTO public.perception_evidence_reviews (
          organization_id, field_id, previous_authority_state, decision,
          next_authority_state, reviewer_notes, canonical_reference, decided_by
        ) VALUES (
          v_assessment.organization_id, v_correction_field_id, 'candidate', 'correct',
          'human_approved', nullif(trim(v_review->>'notes'), ''),
          jsonb_strip_nulls(jsonb_build_object(
            'biosecurity_assessment_id', v_assessment.id,
            'field', v_value_key,
            'final_value', v_final_value,
            'review_status', v_review->>'status'
          )),
          v_actor
        );
        UPDATE public.perception_evidence_fields
        SET authority_state = 'human_approved',
            review_required = false,
            updated_at = clock_timestamp()
        WHERE id = v_correction_field_id;
      END IF;
    END LOOP;

    UPDATE public.perception_evidence_envelopes e
    SET status = CASE
          WHEN EXISTS (
            SELECT 1
            FROM public.perception_evidence_fields f
            WHERE f.envelope_id = e.id
              AND f.review_required
          ) THEN 'manual_review_required'
          ELSE 'complete'
        END,
        updated_at = clock_timestamp()
    WHERE e.id = v_envelope.id;
  END LOOP;
END;
$function$;
COMMENT ON FUNCTION "public"."apply_biosecurity_photo_review_to_perception"(p_assessment_id uuid) IS 'Internal projection of the dedicated human biosecurity classification decision into shared field authority.';
REVOKE ALL ON FUNCTION "public"."apply_biosecurity_photo_review_to_perception"(p_assessment_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."apply_biosecurity_photo_review_to_perception"(p_assessment_id uuid) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."apply_bob_compliance_record_proposal"(p_action_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_action public.bob_agentic_actions%rowtype;
  v_payload jsonb;
  v_actor public.user_profiles%rowtype;
  v_org_id uuid;
  v_record public.organization_compliance_records%rowtype;
  v_replaced public.organization_compliance_records%rowtype;
  v_evidence_id uuid;
  v_attachment_id uuid;
  v_effective date;
  v_expiry date;
  v_source_as_of date;
  v_coverage numeric;
BEGIN
  SELECT * INTO v_action FROM public.bob_agentic_actions WHERE id = p_action_id FOR UPDATE;
  IF NOT FOUND OR v_action.action_type <> 'create_org_compliance_record' OR v_action.status <> 'approved' THEN
    RAISE EXCEPTION 'Only approved create_org_compliance_record actions can be executed';
  END IF;
  IF v_action.result_record_id IS NOT NULL THEN
    RETURN v_action.result_record_id;
  END IF;

  v_payload := coalesce(v_action.amended_payload, v_action.proposed_payload);
  v_org_id := nullif(v_payload->>'organization_id', '')::uuid;
  IF v_org_id IS NULL OR NOT EXISTS (SELECT 1 FROM public.organizations WHERE id = v_org_id) THEN
    RAISE EXCEPTION 'Target organization does not exist';
  END IF;

  SELECT * INTO v_actor FROM public.user_profiles WHERE id = v_action.approved_by AND deactivated_at IS NULL;
  IF NOT FOUND OR v_actor.role NOT IN ('grand_master', 'master')
    OR NOT public.can_approve_action(v_action.approved_by, v_org_id) THEN
    RAISE EXCEPTION 'Active organization master approval is required';
  END IF;

  -- Idempotent on the action id (unique organization_id + client_request_id).
  SELECT * INTO v_record FROM public.organization_compliance_records
  WHERE organization_id = v_org_id AND client_request_id = v_action.id;
  IF FOUND THEN
    RETURN v_record.id;
  END IF;

  IF coalesce(v_payload->>'record_type', '') NOT IN (
    'company_licence', 'insurance', 'policy', 'prequalification', 'registration', 'certification', 'other'
  ) THEN
    RAISE EXCEPTION 'Unsupported compliance record type';
  END IF;
  IF length(trim(coalesce(v_payload->>'name', ''))) NOT BETWEEN 2 AND 200 THEN
    RAISE EXCEPTION 'Compliance record name is required';
  END IF;
  v_source_as_of := nullif(v_payload->>'source_as_of', '')::date;
  IF length(trim(coalesce(v_payload->>'source_name', ''))) NOT BETWEEN 2 AND 500 OR v_source_as_of IS NULL THEN
    RAISE EXCEPTION 'Source name and source date are required';
  END IF;
  v_effective := nullif(v_payload->>'effective_date', '')::date;
  v_expiry := nullif(v_payload->>'expiry_date', '')::date;
  IF v_effective IS NOT NULL AND v_expiry IS NOT NULL AND v_expiry < v_effective THEN
    RAISE EXCEPTION 'Expiry date cannot precede effective date';
  END IF;
  v_coverage := nullif(v_payload->>'coverage_amount', '')::numeric;
  IF v_coverage IS NOT NULL AND v_coverage < 0 THEN
    RAISE EXCEPTION 'Coverage amount cannot be negative';
  END IF;

  -- Evidence must be a governed document owned by the target organization or
  -- by the operator that filed the proposal. A chat attachment resolves to its
  -- registered document; an unregistered attachment stays as provenance text.
  v_evidence_id := nullif(v_payload->>'evidence_document_id', '')::uuid;
  v_attachment_id := nullif(v_payload->>'source_attachment_id', '')::uuid;
  IF v_evidence_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.documents d
      WHERE d.id = v_evidence_id AND d.organization_id IN (v_org_id, v_action.organization_id)
    ) THEN
      RAISE EXCEPTION 'Evidence document is not available to this organization';
    END IF;
  ELSIF v_attachment_id IS NOT NULL THEN
    SELECT d.id INTO v_evidence_id
    FROM public.documents d
    WHERE d.attachment_id = v_attachment_id
      AND d.organization_id IN (v_org_id, v_action.organization_id)
    ORDER BY d.created_at DESC
    LIMIT 1;
  END IF;

  IF nullif(v_payload->>'replaces_record_id', '') IS NOT NULL THEN
    SELECT * INTO v_replaced FROM public.organization_compliance_records
    WHERE id = (v_payload->>'replaces_record_id')::uuid
      AND organization_id = v_org_id
      AND status = 'current'
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Current record to replace was not found';
    END IF;
  END IF;

  INSERT INTO public.organization_compliance_records (
    organization_id, record_type, name, reference_number, issuer,
    effective_date, expiry_date, coverage_amount, currency,
    evidence_document_id, source_name, source_as_of, source_notes,
    replaces_record_id, client_request_id, created_by, updated_by
  )
  VALUES (
    v_org_id,
    v_payload->>'record_type',
    trim(v_payload->>'name'),
    nullif(trim(coalesce(v_payload->>'reference_number', '')), ''),
    nullif(trim(coalesce(v_payload->>'issuer', '')), ''),
    v_effective,
    v_expiry,
    v_coverage,
    upper(coalesce(nullif(trim(v_payload->>'currency'), ''), 'NZD')),
    v_evidence_id,
    trim(v_payload->>'source_name'),
    v_source_as_of,
    nullif(trim(coalesce(v_payload->>'source_notes', '')), ''),
    v_replaced.id,
    v_action.id,
    v_action.approved_by,
    v_action.approved_by
  )
  RETURNING * INTO v_record;

  IF v_replaced.id IS NOT NULL THEN
    UPDATE public.organization_compliance_records
    SET status = 'superseded', updated_by = v_action.approved_by, updated_at = clock_timestamp()
    WHERE id = v_replaced.id;
  END IF;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (
    v_org_id,
    v_action.approved_by,
    'bob_compliance_record_proposal_applied',
    'organization_compliance_records',
    v_record.id,
    jsonb_build_object(
      'action_id', v_action.id,
      'record_type', v_record.record_type,
      'replaces_record_id', v_replaced.id,
      'evidence_document_id', v_evidence_id,
      'source_attachment_id', v_attachment_id
    )
  );

  RETURN v_record.id;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."apply_bob_compliance_record_proposal"(p_action_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."apply_bob_compliance_record_proposal"(p_action_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."apply_bob_compliance_record_proposal"(p_action_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."apply_bob_place_hazard_proposal"(p_action_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_action public.bob_agentic_actions%rowtype;
  v_payload jsonb;
  v_org uuid;
  v_location uuid;
  v_site uuid;
  v_zone uuid;
  v_doc uuid;
  v_attachment uuid;
  v_controls text[];
  v_existing public.place_hazards%rowtype;
  v_id uuid;
BEGIN
  SELECT * INTO v_action FROM public.bob_agentic_actions WHERE id = p_action_id FOR UPDATE;
  IF NOT FOUND OR v_action.action_type <> 'create_place_hazard' OR v_action.status <> 'approved' THEN
    RAISE EXCEPTION 'Only approved create_place_hazard actions can be executed';
  END IF;
  IF v_action.result_record_id IS NOT NULL THEN RETURN v_action.result_record_id; END IF;
  SELECT id INTO v_id FROM public.place_hazards WHERE bob_action_id = v_action.id LIMIT 1;
  IF FOUND THEN RETURN v_id; END IF;

  v_payload := coalesce(v_action.amended_payload, v_action.proposed_payload);
  v_org := nullif(v_payload->>'organization_id', '')::uuid;
  v_site := nullif(v_payload->>'client_site_id', '')::uuid;
  v_zone := nullif(v_payload->>'zone_id', '')::uuid;
  v_location := coalesce(
    nullif(v_payload->>'location_id', '')::uuid,
    (SELECT location_id FROM public.client_sites WHERE id = v_site),
    (SELECT location_id FROM public.location_zones WHERE id = v_zone)
  );
  IF v_org IS NULL OR NOT EXISTS (SELECT 1 FROM public.organizations WHERE id = v_org) THEN RAISE EXCEPTION 'Target organization does not exist'; END IF;
  IF v_location IS NULL OR NOT EXISTS (SELECT 1 FROM public.locations WHERE id = v_location) THEN RAISE EXCEPTION 'Target place does not exist'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.user_profiles WHERE id = v_action.approved_by AND deactivated_at IS NULL)
    OR NOT public.can_approve_action(v_action.approved_by, v_org) THEN
    RAISE EXCEPTION 'Active organization approver is required';
  END IF;

  SELECT coalesce(array_agg(left(btrim(c), 300)) FILTER (WHERE btrim(c) <> ''), '{}'::text[])
  INTO v_controls FROM jsonb_array_elements_text(coalesce(v_payload->'controls', '[]'::jsonb)) c;

  v_doc := nullif(v_payload->>'source_document_id', '')::uuid;
  v_attachment := nullif(v_payload->>'source_attachment_id', '')::uuid;
  IF v_doc IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM public.documents d WHERE d.id = v_doc AND (d.organization_id IS NULL OR d.organization_id IN (v_org, v_action.organization_id))) THEN
      RAISE EXCEPTION 'Source document is not available to this organization';
    END IF;
  ELSIF v_attachment IS NOT NULL THEN
    SELECT d.id INTO v_doc FROM public.documents d
    WHERE d.attachment_id = v_attachment AND d.organization_id IN (v_org, v_action.organization_id)
    ORDER BY d.created_at DESC LIMIT 1;
  END IF;

  SELECT * INTO v_existing FROM public.place_hazards h
  WHERE h.organization_id = v_org AND h.location_id = v_location
    AND h.client_site_id IS NOT DISTINCT FROM v_site AND h.zone_id IS NOT DISTINCT FROM v_zone
    AND h.status <> 'retired' AND lower(btrim(h.title)) = lower(btrim(v_payload->>'title'))
  ORDER BY h.updated_at DESC LIMIT 1
  FOR UPDATE;

  IF v_existing.id IS NOT NULL THEN
    UPDATE public.place_hazards SET
      hazard_class = v_payload->>'hazard_class',
      risk_level = v_payload->>'risk_level',
      likelihood = nullif(v_payload->>'likelihood', '')::smallint,
      consequence = nullif(v_payload->>'consequence', '')::smallint,
      controls = v_controls,
      details = nullif(btrim(coalesce(v_payload->>'details', '')), ''),
      source_document_id = coalesce(v_doc, source_document_id),
      source_locator = nullif(btrim(coalesce(v_payload->>'source_locator', '')), ''),
      source_name = nullif(btrim(coalesce(v_payload->>'source_name', '')), ''),
      source_as_of = nullif(v_payload->>'source_as_of', '')::date,
      review_due = coalesce(nullif(v_payload->>'review_due', '')::date, review_due),
      status = 'active',
      reviewed_by = v_action.approved_by,
      reviewed_at = clock_timestamp(),
      bob_action_id = v_action.id,
      version = version + 1
    WHERE id = v_existing.id
    RETURNING id INTO v_id;
  ELSE
    INSERT INTO public.place_hazards (
      organization_id, location_id, client_site_id, zone_id, title, hazard_class, risk_level, likelihood, consequence,
      controls, details, source_document_id, source_locator, source_name, source_as_of, review_due,
      origin, status, reviewed_by, reviewed_at, bob_action_id, client_request_id, created_by
    ) VALUES (
      v_org, v_location, v_site, v_zone, btrim(coalesce(v_payload->>'title', '')), v_payload->>'hazard_class', v_payload->>'risk_level',
      nullif(v_payload->>'likelihood', '')::smallint, nullif(v_payload->>'consequence', '')::smallint,
      v_controls, nullif(btrim(coalesce(v_payload->>'details', '')), ''), v_doc,
      nullif(btrim(coalesce(v_payload->>'source_locator', '')), ''), nullif(btrim(coalesce(v_payload->>'source_name', '')), ''),
      nullif(v_payload->>'source_as_of', '')::date, nullif(v_payload->>'review_due', '')::date,
      'bob_extracted', 'active', v_action.approved_by, clock_timestamp(), v_action.id, v_action.id, v_action.approved_by
    ) RETURNING id INTO v_id;
  END IF;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_org, v_action.approved_by, 'bob_place_hazard_proposal_applied', 'place_hazards', v_id,
    jsonb_build_object('action_id', v_action.id, 'replaced_hazard_id', v_existing.id, 'source_document_id', v_doc, 'source_attachment_id', v_attachment));

  RETURN v_id;
END;
$function$;
COMMENT ON FUNCTION "public"."apply_bob_place_hazard_proposal"(p_action_id uuid) IS 'Service-only executor for approved create_place_hazard actions. Idempotent on the action id; replaces a live hazard with the same title at the same place and facet (version bump forces officer re-acknowledgement); audited.';
REVOKE ALL ON FUNCTION "public"."apply_bob_place_hazard_proposal"(p_action_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."apply_bob_place_hazard_proposal"(p_action_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."apply_bob_place_hazard_proposal"(p_action_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."apply_bob_rate_rule_proposal"(p_action_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_action public.bob_agentic_actions%rowtype;
  v_payload jsonb;
  v_actor public.user_profiles%rowtype;
  v_rule public.rate_rules%rowtype;
begin
  select * into v_action from public.bob_agentic_actions where id=p_action_id for update;
  if not found or v_action.action_type<>'create_rate_rule' or v_action.status<>'approved' then raise exception 'Only approved create_rate_rule actions can be executed'; end if;
  if v_action.result_record_id is not null then return v_action.result_record_id; end if;
  select * into v_actor from public.user_profiles where id=v_action.approved_by and deactivated_at is null;
  if not found or v_actor.organization_id<>v_action.organization_id or not public.can_approve_action(v_action.approved_by, v_action.organization_id) then raise exception 'An active finance administrator approval is required'; end if;
  v_payload:=coalesce(v_action.amended_payload,v_action.proposed_payload);
  if nullif(trim(coalesce(v_payload->>'name','')),'') is null or v_payload->>'rule_kind' not in ('pay','billing') or v_payload->>'rate_type' not in ('hourly','flat','daily','per_km','per_unit','percentage','per_hour_travel','per_hour_allowance','oncall_flat','callout','higher_duties_flat','per_visit','per_notice') or (v_payload->>'amount')::numeric<0 then raise exception 'Approved rate-rule proposal is invalid'; end if;
  insert into public.rate_rules(organization_id,rule_kind,name,rate_type,amount,pay_code,service_type,job_type,day_category,priority,active,created_by,updated_by,client_request_id)
  values(v_action.organization_id,v_payload->>'rule_kind',trim(v_payload->>'name'),v_payload->>'rate_type',(v_payload->>'amount')::numeric,nullif(trim(coalesce(v_payload->>'pay_code','')),''),nullif(trim(coalesce(v_payload->>'service_type','')),''),nullif(trim(coalesce(v_payload->>'job_type','')),''),nullif(trim(coalesce(v_payload->>'day_category','')),''),coalesce((v_payload->>'priority')::integer,0),true,v_action.approved_by,v_action.approved_by,gen_random_uuid()) returning * into v_rule;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_rule.organization_id,v_action.approved_by,'bob_rate_rule_proposal_applied','rate_rules',v_rule.id,jsonb_build_object('action_id',v_action.id));
  return v_rule.id;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."apply_bob_rate_rule_proposal"(p_action_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."apply_bob_rate_rule_proposal"(p_action_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."apply_bob_rate_rule_proposal"(p_action_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."apply_bob_roster_fill_plan"(p_action_id uuid)
 RETURNS TABLE(plan_id uuid, assignments_applied integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_action public.bob_agentic_actions%rowtype;
  v_payload jsonb;
  v_plan public.bob_roster_plans%rowtype;
  v_item jsonb;
  v_slot public.roster_slots%rowtype;
  v_staff public.staff_profiles%rowtype;
  v_count integer := 0;
  v_actor uuid;
begin
  select a.* into v_action from public.bob_agentic_actions a where a.id = p_action_id for update;
  if not found then raise exception 'Bob action not found'; end if;
  if v_action.action_type <> 'apply_roster_fill_plan' or v_action.status <> 'approved' then
    raise exception 'Only approved apply_roster_fill_plan actions can be executed';
  end if;

  select p.* into v_plan from public.bob_roster_plans p where p.action_id = v_action.id;
  if found then
    return query select v_plan.id, (select count(*)::integer from public.bob_roster_plan_slots where bob_roster_plan_slots.plan_id = v_plan.id);
    return;
  end if;

  v_payload := coalesce(v_action.amended_payload, v_action.proposed_payload);
  if jsonb_typeof(v_payload->'assignments') <> 'array' or jsonb_array_length(v_payload->'assignments') = 0 then
    raise exception 'Roster plan requires at least one assignment';
  end if;

  v_actor := v_action.approved_by;
  insert into public.bob_roster_plans(organization_id, action_id, period_start, period_end, applied_by)
  values (
    v_action.organization_id, v_action.id,
    (v_payload->>'period_start')::timestamptz,
    (v_payload->>'period_end')::timestamptz,
    v_actor
  ) returning * into v_plan;

  for v_item in select value from jsonb_array_elements(v_payload->'assignments') loop
    select s.* into v_slot from public.roster_slots s where s.id = (v_item->>'roster_slot_id')::uuid for update;
    if not found or v_slot.organization_id <> v_action.organization_id then
      raise exception 'Proposed roster slot is unavailable';
    end if;
    if v_slot.status <> 'draft' or v_slot.staff_id is not null then
      raise exception 'Roster slot % changed after Bob proposed it; revise the plan', v_slot.id;
    end if;

    select sp.* into v_staff from public.staff_profiles sp where sp.id = (v_item->>'staff_id')::uuid;
    if not found or v_staff.organization_id <> v_action.organization_id or not v_staff.work_ready then
      raise exception 'Proposed staff member is unavailable';
    end if;
    if public.staff_has_roster_availability_conflict(v_staff.id, v_slot.scheduled_start, v_slot.scheduled_end)
      or public.staff_fatigue_conflict(v_staff.id, v_slot.scheduled_start, v_slot.scheduled_end, v_slot.id) is not null then
      raise exception 'Proposed staff member no longer meets availability or fatigue requirements';
    end if;

    update public.roster_slots set staff_id = v_staff.id where id = v_slot.id;
    insert into public.bob_roster_plan_slots(plan_id, roster_slot_id, staff_id, score, rationale)
    values (v_plan.id, v_slot.id, v_staff.id, coalesce((v_item->>'score')::numeric, 0), coalesce(nullif(trim(v_item->>'rationale'), ''), 'Bob roster proposal'));
    v_count := v_count + 1;
  end loop;

  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (v_action.organization_id, v_actor, 'bob_roster_plan_applied', 'bob_roster_plans', v_plan.id,
    jsonb_build_object('action_id', v_action.id, 'assignments_applied', v_count));

  return query select v_plan.id, v_count;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."apply_bob_roster_fill_plan"(p_action_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."apply_bob_roster_fill_plan"(p_action_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."apply_bob_roster_fill_plan"(p_action_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."apply_bob_staff_onboarding_proposal"(p_action_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare a public.bob_agentic_actions%rowtype; sp public.staff_profiles%rowtype; l public.staff_onboarding_ledgers%rowtype; p jsonb; approver public.user_profiles%rowtype;
begin
 select * into a from public.bob_agentic_actions where id=p_action_id for update;
 if not found or a.action_type<>'start_staff_onboarding' or a.status<>'approved' then raise exception 'Only approved start_staff_onboarding actions can be executed'; end if;
 if a.result_record_id is not null then return a.result_record_id; end if;
 select * into approver from public.user_profiles where id=a.approved_by and deactivated_at is null;
 if not found or approver.organization_id<>a.organization_id or not public.is_admin_for_org(a.organization_id) then raise exception 'An active HR administrator approval is required'; end if;
 p:=coalesce(a.amended_payload,a.proposed_payload);
 select * into sp from public.staff_profiles where id=(p->>'staff_id')::uuid and organization_id=a.organization_id for update;
 if not found then raise exception 'Proposed staff profile is unavailable'; end if;
 select * into l from public.staff_onboarding_ledgers where staff_id=sp.id;
 if found then return l.id; end if;
 insert into public.staff_onboarding_ledgers(organization_id,staff_id,assigned_to,target_start,stage_note) values(a.organization_id,sp.id,nullif(p->>'assigned_to','')::uuid,nullif(p->>'target_start','')::date,coalesce(nullif(trim(p->>'note'),''),'Bob proposed onboarding start')) returning * into l;
 insert into public.staff_onboarding_events(ledger_id,organization_id,to_stage,to_status,note,actor_user_id,version) values(l.id,l.organization_id,l.current_stage,l.status,l.stage_note,a.approved_by,l.version);
 insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(a.organization_id,a.approved_by,'bob_staff_onboarding_started','staff_onboarding_ledgers',l.id,jsonb_build_object('action_id',a.id,'staff_id',sp.id));
 return l.id;
end;$function$;
REVOKE ALL ON FUNCTION "public"."apply_bob_staff_onboarding_proposal"(p_action_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."apply_bob_staff_onboarding_proposal"(p_action_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."apply_bob_staff_onboarding_proposal"(p_action_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."apply_bob_tentative_roster_block"(p_action_id uuid)
 RETURNS TABLE(slots_created integer, quote_id uuid, first_slot_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_action public.bob_agentic_actions%rowtype;
  v_payload jsonb;
  v_approver public.user_profiles%rowtype;
  v_site jsonb;
  v_shift jsonb;
  v_line jsonb;
  v_unit public.roster_work_units%rowtype;
  v_units jsonb := '{}'::jsonb;
  v_quote public.quotes%rowtype;
  v_client_org uuid;
  v_slot_id uuid;
  v_first uuid;
  v_created integer := 0;
  v_index integer := 0;
  v_rows integer;
  v_gst numeric;
begin
  select a.* into v_action from public.bob_agentic_actions a where a.id = p_action_id for update;
  if not found then raise exception 'Bob action not found'; end if;
  if v_action.action_type <> 'apply_tentative_roster_block' or v_action.status <> 'approved' then
    raise exception 'Only approved apply_tentative_roster_block actions can be executed';
  end if;

  select * into v_approver from public.user_profiles where id = v_action.approved_by and deactivated_at is null;
  if not found or v_approver.role not in ('grand_master', 'master', 'admin', 'admin_officer')
     or (v_approver.role <> 'grand_master' and v_approver.organization_id <> v_action.organization_id
         and not (v_action.organization_id = any(coalesce(v_approver.authorized_organization_ids, '{}')))) then
    raise exception 'An active administrator approval is required';
  end if;

  v_payload := coalesce(v_action.amended_payload, v_action.proposed_payload);
  if jsonb_typeof(v_payload->'sites') <> 'array' or jsonb_typeof(v_payload->'shifts') <> 'array'
     or jsonb_array_length(v_payload->'shifts') = 0 or jsonb_array_length(v_payload->'shifts') > 1500 then
    raise exception 'Tentative roster block requires 1 to 1500 shifts and a site list';
  end if;

  for v_site in select value from jsonb_array_elements(v_payload->'sites') loop
    select u.* into v_unit from public.roster_work_units u
    where u.id = (v_site->>'work_unit_id')::uuid and u.organization_id = v_action.organization_id and u.active;
    if not found then raise exception 'Work unit for site % is unavailable', coalesce(v_site->>'label', v_site->>'key'); end if;
    v_units := v_units || jsonb_build_object(v_site->>'key', v_unit.id::text);
  end loop;

  for v_shift in select value from jsonb_array_elements(v_payload->'shifts') loop
    v_index := v_index + 1;
    if not (v_units ? (v_shift->>'site_key')) then raise exception 'Shift % references an unknown site', v_index; end if;
    if (v_shift->>'scheduled_end')::timestamptz <= (v_shift->>'scheduled_start')::timestamptz
       or (v_shift->>'scheduled_end')::timestamptz - (v_shift->>'scheduled_start')::timestamptz > interval '24 hours' then
      raise exception 'Shift % has an invalid time range', v_index;
    end if;
    insert into public.roster_slots(organization_id, work_unit_id, staff_id, scheduled_start, scheduled_end, status,
                                    client_request_id, notes, created_by, external_refs)
    values (v_action.organization_id, (v_units->>(v_shift->>'site_key'))::uuid, null,
            (v_shift->>'scheduled_start')::timestamptz, (v_shift->>'scheduled_end')::timestamptz, 'draft',
            md5(v_action.id::text || ':' || v_index::text)::uuid,
            nullif(trim(v_shift->>'block'), ''), v_action.approved_by,
            jsonb_build_object('source', 'bob_tentative_roster_block', 'action_id', v_action.id,
                               'unpaid_break_minutes', coalesce((v_shift->>'unpaid_break_minutes')::integer, 0)))
    on conflict (organization_id, client_request_id) do nothing
    returning id into v_slot_id;
    get diagnostics v_rows = row_count;
    if v_rows > 0 then v_created := v_created + 1; v_first := coalesce(v_first, v_slot_id); end if;
  end loop;

  v_client_org := nullif(v_payload#>>'{quote,client_org_id}', '')::uuid;
  if v_client_org is not null and jsonb_typeof(v_payload#>'{quote,lines}') = 'array' then
    if not exists (select 1 from public.organizations o where o.id = v_client_org and o.active) then
      raise exception 'Quote client organisation is unavailable';
    end if;
    v_gst := coalesce((v_payload#>>'{quote,gst_rate}')::numeric, 0.15);
    insert into public.quotes(provider_org_id, client_org_id, title, status, gst_rate, notes, created_by, client_request_id)
    values (v_action.organization_id, v_client_org,
            coalesce(nullif(trim(v_payload#>>'{quote,title}'), ''), 'Static guard roster block'), 'draft', v_gst,
            'Generated by Bob from an approved tentative roster block; unpaid breaks excluded from charged hours.',
            v_action.approved_by, md5('quote:' || v_action.id::text)::uuid)
    returning * into v_quote;
    v_index := 0;
    for v_line in select value from jsonb_array_elements(v_payload#>'{quote,lines}') loop
      v_index := v_index + 1;
      insert into public.quote_lines(quote_id, kind, description, quantity, unit_cost, unit_charge, line_order, client_request_id)
      values (v_quote.id, 'labour', left(v_line->>'description', 500), (v_line->>'quantity')::numeric,
              (v_line->>'unit_cost')::numeric, (v_line->>'unit_charge')::numeric, v_index,
              md5('quote-line:' || v_action.id::text || ':' || v_index::text)::uuid);
    end loop;
    update public.quotes q set
      total_cost = t.cost,
      subtotal_charge = t.charge,
      gst_amount = round(t.charge * q.gst_rate, 2),
      total_charge = t.charge + round(t.charge * q.gst_rate, 2)
    from (select coalesce(sum(round(l.quantity * l.unit_cost, 2)), 0) cost, coalesce(sum(round(l.quantity * l.unit_charge, 2)), 0) charge
          from public.quote_lines l where l.quote_id = v_quote.id) t
    where q.id = v_quote.id
    returning q.* into v_quote;
  end if;

  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (v_action.organization_id, v_action.approved_by, 'bob_tentative_roster_block_applied', 'bob_agentic_actions', v_action.id,
          jsonb_build_object('slots_created', v_created, 'quote_id', v_quote.id));

  return query select v_created, v_quote.id, v_first;
end;
$function$;
COMMENT ON FUNCTION "public"."apply_bob_tentative_roster_block"(p_action_id uuid) IS 'Applies an approved Bob tentative roster block: open draft roster_slots (no staff, unpublished) and an optional draft quote. Idempotent per action via derived client_request_ids.';
REVOKE ALL ON FUNCTION "public"."apply_bob_tentative_roster_block"(p_action_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."apply_bob_tentative_roster_block"(p_action_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."apply_bob_tentative_roster_block"(p_action_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."apply_cctv_person_review_to_perception"(p_observation_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_observation public.cctv_entity_observations%rowtype;
  v_envelope public.perception_evidence_envelopes%rowtype;
  v_field public.perception_evidence_fields%rowtype;
  v_target_authority text;
  v_decision text;
  v_review_required boolean;
  v_identity_value text;
BEGIN
  SELECT * INTO v_observation
  FROM public.cctv_entity_observations
  WHERE id = p_observation_id;
  IF NOT FOUND OR v_observation.entity_kind <> 'person' THEN
    RETURN;
  END IF;

  FOR v_envelope IN
    SELECT e.*
    FROM public.perception_evidence_envelopes e
    WHERE e.organization_id = v_observation.organization_id
      AND e.domain = 'cctv_person'
      AND e.source_receipt->>'cctv_entity_observation_id' = v_observation.id::text
  LOOP
    IF v_observation.review_state = 'superseded' THEN
      UPDATE public.perception_evidence_fields
      SET authority_state = 'superseded',
          review_required = false,
          updated_at = clock_timestamp()
      WHERE envelope_id = v_envelope.id;
      UPDATE public.perception_evidence_envelopes
      SET status = 'superseded',
          updated_at = clock_timestamp()
      WHERE id = v_envelope.id;
      CONTINUE;
    END IF;

    IF v_observation.review_state NOT IN ('accepted', 'rejected') THEN
      CONTINUE;
    END IF;
    IF v_observation.reviewed_by IS NULL THEN
      RAISE EXCEPTION 'CCTV person review state % requires an attributable reviewer', v_observation.review_state;
    END IF;

    IF v_observation.review_state = 'accepted'
       AND v_observation.portfolio_state IN ('linked', 'new_identity')
       AND (v_observation.canonical_person_id IS NOT NULL OR v_observation.person_record_id IS NOT NULL) THEN
      v_identity_value := coalesce(v_observation.canonical_person_id, v_observation.person_record_id)::text;
      INSERT INTO public.perception_evidence_fields (
        organization_id, envelope_id, field_key, candidate_ordinal, value_type,
        candidate_value, normalized_value, candidate_payload, source_locations,
        consensus_rule, authority_state, review_required
      ) VALUES (
        v_observation.organization_id, v_envelope.id, 'person.identity_reference', 0, 'entity',
        v_identity_value, v_identity_value,
        jsonb_strip_nulls(jsonb_build_object(
          'person_record_id', v_observation.person_record_id,
          'canonical_person_id', v_observation.canonical_person_id,
          'identity_basis', v_observation.portfolio_state
        )),
        jsonb_build_array(jsonb_build_object(
          'cctv_entity_observation_id', v_observation.id,
          'source_event_id', v_observation.source_event_id
        )),
        'explicit_human_cctv_identity_link_v1', 'candidate', true
      )
      ON CONFLICT (envelope_id, field_key, candidate_ordinal) DO UPDATE
      SET candidate_value = EXCLUDED.candidate_value,
          normalized_value = EXCLUDED.normalized_value,
          candidate_payload = EXCLUDED.candidate_payload,
          updated_at = clock_timestamp()
      WHERE public.perception_evidence_fields.authority_state <> 'human_approved';
    END IF;

    FOR v_field IN
      SELECT f.*
      FROM public.perception_evidence_fields f
      WHERE f.envelope_id = v_envelope.id
      ORDER BY f.field_key, f.candidate_ordinal
    LOOP
      v_target_authority := NULL;
      v_decision := NULL;
      v_review_required := v_field.review_required;

      IF v_observation.review_state = 'rejected' THEN
        v_target_authority := 'rejected';
        v_decision := 'reject';
        v_review_required := false;
      ELSIF v_field.field_key IN ('person.presence', 'person.face_detected', 'person.identity_reference') THEN
        v_target_authority := 'human_approved';
        v_decision := 'approve';
        v_review_required := false;
      ELSIF v_field.field_key = 'person.portfolio_candidate'
            AND v_observation.portfolio_state IN ('linked', 'new_identity') THEN
        v_target_authority := 'superseded';
        v_decision := 'supersede';
        v_review_required := false;
      END IF;

      IF v_target_authority IS NULL
         OR (v_field.authority_state = v_target_authority AND v_field.review_required = v_review_required) THEN
        CONTINUE;
      END IF;

      INSERT INTO public.perception_evidence_reviews (
        organization_id, field_id, previous_authority_state, decision,
        next_authority_state, reviewer_notes, canonical_reference, decided_by
      ) VALUES (
        v_observation.organization_id, v_field.id, v_field.authority_state, v_decision,
        v_target_authority, nullif(trim(v_observation.review_notes), ''),
        jsonb_strip_nulls(jsonb_build_object(
          'cctv_entity_observation_id', v_observation.id,
          'person_record_id', v_observation.person_record_id,
          'canonical_person_id', v_observation.canonical_person_id,
          'portfolio_state', v_observation.portfolio_state,
          'review_state', v_observation.review_state
        )),
        v_observation.reviewed_by
      );

      UPDATE public.perception_evidence_fields
      SET authority_state = v_target_authority,
          review_required = v_review_required,
          updated_at = clock_timestamp()
      WHERE id = v_field.id;
    END LOOP;

    UPDATE public.perception_evidence_envelopes e
    SET status = CASE
          WHEN EXISTS (
            SELECT 1
            FROM public.perception_evidence_fields f
            WHERE f.envelope_id = e.id
              AND f.review_required
          ) THEN 'manual_review_required'
          ELSE 'complete'
        END,
        updated_at = clock_timestamp()
    WHERE e.id = v_envelope.id;
  END LOOP;
END;
$function$;
COMMENT ON FUNCTION "public"."apply_cctv_person_review_to_perception"(p_observation_id uuid) IS 'Internal projection of the existing CCTV person-observation decision into shared perception authority. It never reads or copies biometric templates.';
REVOKE ALL ON FUNCTION "public"."apply_cctv_person_review_to_perception"(p_observation_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."apply_cctv_person_review_to_perception"(p_observation_id uuid) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."apply_cctv_vehicle_attribute_review_to_perception"(p_observation_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_review jsonb;
BEGIN
  SELECT attributes->'make_model_review'
  INTO v_review
  FROM public.cctv_entity_observations
  WHERE id = p_observation_id
    AND entity_kind = 'vehicle';

  IF jsonb_typeof(v_review) IS DISTINCT FROM 'object'
     OR v_review->>'status' NOT IN ('confirmed','corrected','rejected')
     OR nullif(v_review->>'reviewed_by', '') IS NULL THEN
    RETURN;
  END IF;

  PERFORM public.apply_cctv_vehicle_attribute_review_to_perception_unchecked(p_observation_id);
END;
$function$;
COMMENT ON FUNCTION "public"."apply_cctv_vehicle_attribute_review_to_perception"(p_observation_id uuid) IS 'Fail-closed wrapper that ignores absent or unattributed legacy review metadata instead of blocking candidate receipt creation.';
REVOKE ALL ON FUNCTION "public"."apply_cctv_vehicle_attribute_review_to_perception"(p_observation_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."apply_cctv_vehicle_attribute_review_to_perception"(p_observation_id uuid) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."apply_cctv_vehicle_attribute_review_to_perception_unchecked"(p_observation_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_observation public.cctv_entity_observations%rowtype;
  v_envelope public.perception_evidence_envelopes%rowtype;
  v_field public.perception_evidence_fields%rowtype;
  v_review jsonb;
  v_reviewed_fields jsonb;
  v_short_key text;
  v_final_value text;
  v_target_authority text;
  v_decision text;
  v_actor uuid;
  v_correction_field_id uuid;
BEGIN
  SELECT * INTO v_observation
  FROM public.cctv_entity_observations
  WHERE id = p_observation_id;
  IF NOT FOUND OR v_observation.entity_kind <> 'vehicle' THEN RETURN; END IF;

  v_review := v_observation.attributes->'make_model_review';
  IF jsonb_typeof(v_review) <> 'object' OR v_review->>'status' NOT IN ('confirmed','corrected','rejected') THEN
    RETURN;
  END IF;
  v_actor := nullif(v_review->>'reviewed_by', '')::uuid;
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Vehicle attribute review requires an attributable reviewer';
  END IF;
  v_reviewed_fields := CASE
    WHEN jsonb_typeof(v_review->'reviewed_fields') = 'array' THEN v_review->'reviewed_fields'
    WHEN v_review->>'status' = 'rejected' THEN jsonb_build_array('make','model')
    ELSE jsonb_build_array('make','model')
  END;

  FOR v_envelope IN
    SELECT e.*
    FROM public.perception_evidence_envelopes e
    WHERE e.organization_id = v_observation.organization_id
      AND e.domain = 'cctv_vehicle_attributes'
      AND e.source_receipt->>'cctv_entity_observation_id' = v_observation.id::text
  LOOP
    FOR v_field IN
      SELECT f.*
      FROM public.perception_evidence_fields f
      WHERE f.envelope_id = v_envelope.id
      ORDER BY f.field_key, f.candidate_ordinal
    LOOP
      v_short_key := replace(v_field.field_key, 'vehicle.', '');
      IF NOT v_reviewed_fields ? v_short_key THEN CONTINUE; END IF;
      v_final_value := coalesce(v_review#>>ARRAY['values', v_short_key], v_field.candidate_value);
      v_target_authority := CASE
        WHEN v_review->>'status' = 'rejected' THEN 'rejected'
        WHEN lower(coalesce(v_field.normalized_value, v_field.candidate_value)) = lower(v_final_value) THEN 'human_approved'
        ELSE 'superseded'
      END;
      v_decision := CASE
        WHEN v_target_authority = 'rejected' THEN 'reject'
        WHEN v_target_authority = 'superseded' THEN 'supersede'
        ELSE 'approve'
      END;

      IF v_field.authority_state IS DISTINCT FROM v_target_authority OR v_field.review_required THEN
        INSERT INTO public.perception_evidence_reviews (
          organization_id, field_id, previous_authority_state, decision,
          next_authority_state, reviewer_notes, canonical_reference, decided_by
        ) VALUES (
          v_observation.organization_id, v_field.id, v_field.authority_state, v_decision,
          v_target_authority, nullif(trim(v_review->>'notes'), ''),
          jsonb_strip_nulls(jsonb_build_object(
            'cctv_entity_observation_id', v_observation.id,
            'canonical_vehicle_id', v_observation.canonical_vehicle_id,
            'field', v_short_key,
            'final_value', v_final_value,
            'review_status', v_review->>'status'
          )),
          v_actor
        );
        UPDATE public.perception_evidence_fields
        SET authority_state = v_target_authority,
            review_required = false,
            updated_at = clock_timestamp()
        WHERE id = v_field.id;
      END IF;

      IF v_target_authority = 'superseded' AND v_final_value IS NOT NULL THEN
        INSERT INTO public.perception_evidence_fields (
          organization_id, envelope_id, field_key, candidate_ordinal, value_type,
          candidate_value, normalized_value, candidate_payload, source_locations,
          consensus_rule, authority_state, review_required
        ) VALUES (
          v_observation.organization_id, v_envelope.id, v_field.field_key, 1, v_field.value_type,
          v_final_value, lower(trim(v_final_value)),
          jsonb_build_object('human_correction', true),
          jsonb_build_array(jsonb_build_object('cctv_entity_observation_id', v_observation.id)),
          'explicit_human_vehicle_attribute_correction_v1', 'candidate', true
        )
        ON CONFLICT (envelope_id, field_key, candidate_ordinal) DO UPDATE
        SET candidate_value = EXCLUDED.candidate_value,
            normalized_value = EXCLUDED.normalized_value,
            candidate_payload = EXCLUDED.candidate_payload,
            updated_at = clock_timestamp()
        RETURNING id INTO v_correction_field_id;

        INSERT INTO public.perception_evidence_reviews (
          organization_id, field_id, previous_authority_state, decision,
          next_authority_state, reviewer_notes, canonical_reference, decided_by
        ) VALUES (
          v_observation.organization_id, v_correction_field_id, 'candidate', 'correct',
          'human_approved', nullif(trim(v_review->>'notes'), ''),
          jsonb_strip_nulls(jsonb_build_object(
            'cctv_entity_observation_id', v_observation.id,
            'canonical_vehicle_id', v_observation.canonical_vehicle_id,
            'field', v_short_key,
            'final_value', v_final_value,
            'review_status', v_review->>'status'
          )),
          v_actor
        );
        UPDATE public.perception_evidence_fields
        SET authority_state = 'human_approved',
            review_required = false,
            updated_at = clock_timestamp()
        WHERE id = v_correction_field_id;
      END IF;
    END LOOP;

    UPDATE public.perception_evidence_envelopes e
    SET status = CASE
          WHEN EXISTS (
            SELECT 1 FROM public.perception_evidence_fields f
            WHERE f.envelope_id = e.id AND f.review_required
          ) THEN 'manual_review_required'
          ELSE 'complete'
        END,
        updated_at = clock_timestamp()
    WHERE e.id = v_envelope.id;
  END LOOP;
END;
$function$;
COMMENT ON FUNCTION "public"."apply_cctv_vehicle_attribute_review_to_perception_unchecked"(p_observation_id uuid) IS 'Projects the existing human vehicle-attribute decision into shared field authority while preserving corrected machine candidates as superseded evidence.';
REVOKE ALL ON FUNCTION "public"."apply_cctv_vehicle_attribute_review_to_perception_unchecked"(p_observation_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."apply_cctv_vehicle_attribute_review_to_perception_unchecked"(p_observation_id uuid) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."apply_credential_promotion_proposal"(p_proposal_id uuid, p_staff_id uuid, p_credential_type text, p_credential_number text DEFAULT NULL::text, p_issuing_authority text DEFAULT NULL::text, p_issued_date date DEFAULT NULL::date, p_expiry_date date DEFAULT NULL::date, p_authorized_activities text[] DEFAULT '{}'::text[])
 RETURNS TABLE(proposal_id uuid, credential_id uuid, created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_proposal public.document_promotion_proposals%rowtype;
  v_org_id uuid;
  v_storage_path text;
  v_credential_id uuid;
  v_created boolean := false;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_credential_type NOT IN ('certificate_of_authority','warrant_of_authority','drivers_licence','first_aid','security_licence','firearms_licence','noise_control_warrant','biosecurity_warrant','other') THEN RAISE EXCEPTION 'Unsupported credential type'; END IF;
  SELECT * INTO v_proposal FROM public.document_promotion_proposals WHERE id = p_proposal_id FOR UPDATE;
  IF NOT FOUND OR v_proposal.target_type <> 'credential' OR v_proposal.status <> 'approved' THEN RAISE EXCEPTION 'Only approved credential proposals can be applied'; END IF;
  SELECT sp.organization_id INTO v_org_id FROM public.staff_profiles sp WHERE sp.id = p_staff_id;
  IF v_org_id IS NULL THEN RAISE EXCEPTION 'Staff profile not found'; END IF;
  IF v_org_id <> v_proposal.organization_id THEN RAISE EXCEPTION 'Staff profile is outside proposal organisation'; END IF;
  IF NOT public.is_admin_for_org(v_org_id) AND NOT public.is_grand_master() THEN RAISE EXCEPTION 'Credential application denied'; END IF;
  SELECT d.storage_object_ref INTO v_storage_path FROM public.document_versions dv JOIN public.documents d ON d.id = dv.document_id WHERE dv.id = v_proposal.document_version_id;
  IF v_proposal.applied_target_id IS NOT NULL THEN RETURN QUERY SELECT v_proposal.id, v_proposal.applied_target_id, false; RETURN; END IF;
  SELECT id INTO v_credential_id FROM public.staff_credentials WHERE staff_id = p_staff_id AND organization_id = v_org_id AND credential_type = p_credential_type AND credential_number IS NOT DISTINCT FROM p_credential_number AND expiry_date IS NOT DISTINCT FROM p_expiry_date LIMIT 1;
  IF v_credential_id IS NULL THEN
    INSERT INTO public.staff_credentials (staff_id, organization_id, credential_type, credential_number, issuing_authority, issued_date, expiry_date, authorized_activities, document_storage_path, verified, notes, client_request_id)
    VALUES (p_staff_id, v_org_id, p_credential_type, nullif(trim(p_credential_number), ''), nullif(trim(p_issuing_authority), ''), p_issued_date, p_expiry_date, coalesce(p_authorized_activities, '{}'::text[]), v_storage_path, false, 'Created from document promotion proposal ' || v_proposal.id::text, v_proposal.id)
    RETURNING id INTO v_credential_id;
    v_created := true;
  END IF;
  UPDATE public.document_promotion_proposals SET status = 'applied', applied_target_id = v_credential_id, applied_at = clock_timestamp(), updated_at = clock_timestamp() WHERE id = v_proposal.id;
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_org_id, v_actor, 'document_promotion_proposal_applied', 'staff_credentials', v_credential_id, jsonb_build_object('proposal_id', v_proposal.id, 'document_version_id', v_proposal.document_version_id, 'created', v_created, 'verified', false));
  RETURN QUERY SELECT v_proposal.id, v_credential_id, v_created;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."apply_credential_promotion_proposal"(p_proposal_id uuid, p_staff_id uuid, p_credential_type text, p_credential_number text, p_issuing_authority text, p_issued_date date, p_expiry_date date, p_authorized_activities text[]) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."apply_credential_promotion_proposal"(p_proposal_id uuid, p_staff_id uuid, p_credential_type text, p_credential_number text, p_issuing_authority text, p_issued_date date, p_expiry_date date, p_authorized_activities text[]) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."apply_credential_promotion_proposal"(p_proposal_id uuid, p_staff_id uuid, p_credential_type text, p_credential_number text, p_issuing_authority text, p_issued_date date, p_expiry_date date, p_authorized_activities text[]) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."apply_credential_promotion_proposal"(p_proposal_id uuid, p_staff_id uuid, p_credential_type text, p_credential_number text, p_issuing_authority text, p_issued_date date, p_expiry_date date, p_authorized_activities text[]) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."apply_crm_agreement_promotion_proposal"(p_proposal_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_name text, p_starts_on date DEFAULT NULL::date, p_ends_on date DEFAULT NULL::date, p_enabled_modules text[] DEFAULT '{}'::text[])
 RETURNS TABLE(proposal_id uuid, agreement_id uuid, created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_proposal public.document_promotion_proposals%rowtype;
  v_agreement_id uuid;
  v_created boolean := false;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF nullif(trim(coalesce(p_name, '')), '') IS NULL THEN RAISE EXCEPTION 'Agreement name is required'; END IF;
  SELECT * INTO v_proposal FROM public.document_promotion_proposals WHERE id = p_proposal_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Promotion proposal not found'; END IF;
  IF v_proposal.target_type <> 'crm_agreement' OR v_proposal.status <> 'approved' THEN
    RAISE EXCEPTION 'Only approved CRM agreement proposals can be applied';
  END IF;
  IF NOT public.is_admin_for_org(p_provider_organization_id) AND NOT public.is_grand_master() THEN
    RAISE EXCEPTION 'CRM agreement application denied';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.organizations WHERE id = p_client_organization_id AND active) THEN
    RAISE EXCEPTION 'Active client organisation is required';
  END IF;
  IF v_proposal.applied_target_id IS NOT NULL THEN
    RETURN QUERY SELECT v_proposal.id, v_proposal.applied_target_id, false;
    RETURN;
  END IF;
  SELECT id INTO v_agreement_id
  FROM public.service_agreements
  WHERE provider_organization_id = p_provider_organization_id
    AND client_organization_id = p_client_organization_id
    AND name = trim(p_name)
  LIMIT 1;
  IF v_agreement_id IS NULL THEN
    INSERT INTO public.service_agreements (provider_organization_id, client_organization_id, name, starts_on, ends_on, agreement_type, invitation_status, enabled_modules, external_refs)
    VALUES (p_provider_organization_id, p_client_organization_id, trim(p_name), p_starts_on, p_ends_on, 'operational', 'not_invited', coalesce(p_enabled_modules, '{}'::text[]), jsonb_build_object('document_promotion_proposal_id', v_proposal.id, 'document_version_id', v_proposal.document_version_id))
    RETURNING id INTO v_agreement_id;
    v_created := true;
  END IF;
  UPDATE public.document_promotion_proposals
  SET status = 'applied', applied_target_id = v_agreement_id, applied_at = clock_timestamp(), updated_at = clock_timestamp()
  WHERE id = v_proposal.id;
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_proposal.organization_id, v_actor, 'document_promotion_proposal_applied', 'service_agreements', v_agreement_id,
    jsonb_build_object('proposal_id', v_proposal.id, 'document_version_id', v_proposal.document_version_id, 'created', v_created));
  RETURN QUERY SELECT v_proposal.id, v_agreement_id, v_created;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."apply_crm_agreement_promotion_proposal"(p_proposal_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_name text, p_starts_on date, p_ends_on date, p_enabled_modules text[]) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."apply_crm_agreement_promotion_proposal"(p_proposal_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_name text, p_starts_on date, p_ends_on date, p_enabled_modules text[]) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."apply_crm_agreement_promotion_proposal"(p_proposal_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_name text, p_starts_on date, p_ends_on date, p_enabled_modules text[]) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."apply_crm_agreement_promotion_proposal"(p_proposal_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_name text, p_starts_on date, p_ends_on date, p_enabled_modules text[]) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."apply_dart_patrol_source_updates_and_supersede"(p_canonical_batch_id uuid, p_update_batch_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_items jsonb)
 RETURNS TABLE(external_ref text, record_id uuid, outcome text, detail text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_canonical_batch public.file_import_batches%rowtype;
  v_update_batch public.file_import_batches%rowtype;
  v_item jsonb;
  v_canonical_item jsonb;
  v_update_item jsonb;
  v_update_desired jsonb;
  v_canonical_payload jsonb;
  v_update_payload jsonb;
  v_patch jsonb;
  v_ref text;
  v_copy_ref text;
  v_update_ref text;
  v_canonical_id uuid;
  v_copy_id uuid;
  v_canonical public.location_events%rowtype;
  v_copy public.location_events%rowtype;
  v_canonical_version public.patrol_import_record_versions%rowtype;
  v_copy_version public.patrol_import_record_versions%rowtype;
  v_archive public.location_events_superseded%rowtype;
  v_before jsonb;
  v_after jsonb;
  v_copy_before jsonb;
  v_changed text[];
  v_shift numeric;
  v_hold text;
  v_field text;
  v_version_no integer;
  v_current_copy_version boolean;
  v_repeated_canonical text[];
  v_repeated_copy text[];
begin
  v_canonical_batch := public.patrol_source_sync_batch(
    p_canonical_batch_id, p_provider_organization_id, p_client_organization_id);
  v_update_batch := public.patrol_source_sync_batch(
    p_update_batch_id, p_provider_organization_id, p_client_organization_id);

  if v_canonical_batch.source_file is distinct from v_update_batch.source_file
     or v_canonical_batch.source_sha256 is distinct from v_update_batch.source_sha256
     or v_canonical_batch.manifest_json->>'source_profile' is distinct from v_update_batch.manifest_json->>'source_profile'
     or v_canonical_batch.manifest_json->>'source_sheet' is distinct from '2025'
     or v_update_batch.manifest_json->>'source_sheet' is distinct from 'Update 251215' then
    raise exception 'DART canonical and Update worksheet batches do not match';
  end if;
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) > 500 then
    raise exception 'Between 0 and 500 DART Update rows are required per call';
  end if;

  -- An Update row must pair one canonical with one copy. Any repeat in the call makes every
  -- item it touches ambiguous, so none of them are written.
  select coalesce(array_agg(key), '{}') into v_repeated_canonical
  from (select value->'canonical'->>'record_id' key from jsonb_array_elements(p_items) value
        group by 1 having count(*) > 1) repeated;
  select coalesce(array_agg(key), '{}') into v_repeated_copy
  from (select value->>'copy_record_id' key from jsonb_array_elements(p_items) value
        group by 1 having count(*) > 1) repeated;

  for v_item in
    select value from jsonb_array_elements(p_items) value order by value->>'copy_external_ref'
  loop
    v_canonical_item := v_item->'canonical';
    v_canonical_payload := public.patrol_source_assert_row_provenance(v_canonical_batch, v_canonical_item);
    v_ref := v_canonical_item->>'external_ref';
    v_canonical_id := (v_canonical_item->>'record_id')::uuid;
    v_copy_ref := nullif(btrim(v_item->>'copy_external_ref'), '');
    v_copy_id := nullif(v_item->>'copy_record_id', '')::uuid;
    v_update_ref := nullif(btrim(v_item->>'update_external_ref'), '');
    v_update_desired := v_item->'update_desired';
    v_update_item := jsonb_build_object(
      'kind', 'event',
      'record_id', v_canonical_id,
      'external_ref', v_update_ref,
      'source_fingerprint', v_item->>'update_source_fingerprint',
      'desired', v_update_desired
    );
    v_update_payload := public.patrol_source_assert_row_provenance(v_update_batch, v_update_item);
    v_hold := null;

    if v_ref is null or v_copy_ref is null or v_update_ref is null or v_copy_id is null
       or v_ref = v_copy_ref or v_canonical_item->>'kind' is distinct from 'event'
       or coalesce(v_item->>'update_source_fingerprint', '') !~ '^[a-f0-9]{64}$' then
      raise exception 'DART Update rows require distinct canonical and copy references with source provenance';
    end if;
    if v_canonical_payload->>'source_sheet' is distinct from '2025'
       or v_update_payload->>'source_sheet' is distinct from 'Update 251215'
       or v_canonical_payload->>'source_file' is distinct from v_update_payload->>'source_file'
       or v_canonical_payload->>'source_sha256' is distinct from v_update_payload->>'source_sha256' then
      raise exception 'DART Update row provenance does not match the canonical workbook';
    end if;
    if jsonb_typeof(v_update_payload->'plates_found') is distinct from 'array'
       or nullif(btrim(v_update_payload->>'location_raw'), '') is null then
      raise exception 'DART Update row is missing a mapped source field';
    end if;
    if coalesce(v_item->>'record_fingerprint', '') !~ '^[a-f0-9]{64}$' then
      raise exception 'DART Update row is missing the reviewed record fingerprint';
    end if;
    if v_canonical_id::text = any(v_repeated_canonical) or v_copy_id::text = any(v_repeated_copy) then
      external_ref := v_update_ref; record_id := v_canonical_id; outcome := 'held'; detail := 'ambiguous_update_pairing';
      return next; continue;
    end if;

    perform pg_advisory_xact_lock(hashtextextended(
      p_client_organization_id::text || ':evidence:' || least(v_ref, v_copy_ref), 0));
    perform pg_advisory_xact_lock(hashtextextended(
      p_client_organization_id::text || ':evidence:' || greatest(v_ref, v_copy_ref), 0));

    select * into v_archive
    from public.location_events_superseded archived
    where archived.client_organization_id = p_client_organization_id
      and archived.external_ref = v_copy_ref;
    if found then
      select * into v_canonical_version
      from public.patrol_import_record_versions version
      where version.record_kind = 'event' and version.record_id = v_canonical_id and version.is_current;
      if v_archive.canonical_location_event_id = v_canonical_id
         and v_archive.canonical_external_ref = v_ref
         and v_archive.batch_id = p_update_batch_id
         and v_canonical_version.provider_organization_id = p_provider_organization_id
         and v_canonical_version.client_organization_id = p_client_organization_id
         and v_canonical_version.external_ref = v_ref
         and v_canonical_version.change_kind = 'update'
         and v_canonical_version.batch_id = p_update_batch_id
         and v_canonical_version.overlay_source->>'source_fingerprint' = v_item->>'update_source_fingerprint'
         and public.patrol_source_record_state('event', v_canonical_id) is not distinct from v_canonical_version.state_after then
        external_ref := v_update_ref; record_id := v_canonical_id; outcome := 'already_applied'; detail := null;
      else
        external_ref := v_update_ref; record_id := v_canonical_id; outcome := 'held'; detail := 'archive_or_update_history_mismatch';
      end if;
      return next; continue;
    end if;

    select * into v_canonical
    from public.location_events event
    where event.id = v_canonical_id and event.organization_id = p_client_organization_id
      and event.external_ref = v_ref and event.source = 'rm_patrol_log_import'
    for update;
    if not found then
      external_ref := v_update_ref; record_id := v_canonical_id; outcome := 'held'; detail := 'canonical_record_missing';
      return next; continue;
    end if;
    select * into v_copy
    from public.location_events event
    where event.id = v_copy_id and event.organization_id = p_client_organization_id
      and event.external_ref = v_copy_ref and event.source = 'rm_patrol_log_import'
    for update;
    if not found then
      external_ref := v_update_ref; record_id := v_canonical_id; outcome := 'held'; detail := 'source_copy_missing';
      return next; continue;
    end if;

    select * into v_canonical_version
    from public.patrol_import_record_versions version
    where version.record_kind = 'event' and version.record_id = v_canonical_id and version.is_current
    for update;
    if not found then
      external_ref := v_update_ref; record_id := v_canonical_id; outcome := 'held'; detail := 'canonical_source_baseline_required';
      return next; continue;
    end if;
    if v_canonical_version.provider_organization_id <> p_provider_organization_id
       or v_canonical_version.client_organization_id <> p_client_organization_id
       or v_canonical_version.external_ref <> v_ref
       or v_canonical_version.source_sheet is distinct from '2025'
       or v_canonical_version.change_kind not in ('legacy_correction', 'update') then
      external_ref := v_update_ref; record_id := v_canonical_id; outcome := 'held'; detail := 'canonical_source_identity_mismatch';
      return next; continue;
    end if;
    if v_canonical_version.change_kind = 'update' then
      external_ref := v_update_ref; record_id := v_canonical_id; outcome := 'held'; detail := 'canonical_already_updated_from_another_source';
      return next; continue;
    end if;

    if v_canonical.payload->>'source_sheet' is distinct from '2025'
       or nullif(v_canonical.payload->>'job_number', '') is null
       or v_copy.payload->>'source_file' is distinct from v_update_payload->>'source_file'
       or v_copy.payload->>'source_sheet' is distinct from 'Update 251215'
       or v_copy.payload->>'source_row' is distinct from v_update_payload->>'source_row' then
      v_hold := 'source_copy_identity_mismatch';
    end if;

    v_before := public.patrol_source_record_state('event', v_canonical_id);
    if v_hold is null and v_before is distinct from v_canonical_version.state_after then
      v_hold := 'fcm_record_changed_since_last_sync';
    end if;
    if v_hold is null and (
      v_canonical.occurred_at is distinct from (v_update_desired->>'occurred_at')::timestamptz
      or v_canonical.zone_id is distinct from nullif(v_update_desired->>'zone_id', '')::uuid
      or v_canonical.client_site_id is distinct from nullif(v_update_desired->>'site_id', '')::uuid
      or v_canonical.observed_entity_id is distinct from nullif(v_update_desired->>'observed_entity_id', '')::uuid
      or v_canonical.observed_entity_type is distinct from v_update_desired->>'observed_entity_type'
      or v_canonical.event_type is distinct from v_update_desired->>'event_type'
      or nullif(btrim(v_canonical.payload->>'comments'), '') is distinct from nullif(btrim(v_update_payload->>'comments'), '')
    ) then
      v_hold := 'update_visit_identity_mismatch';
    end if;

    if v_hold is null then
      v_shift := extract(epoch from v_copy.occurred_at - v_canonical.occurred_at);
      if v_copy.zone_id is distinct from v_canonical.zone_id
         or v_copy.client_site_id is distinct from v_canonical.client_site_id
         or v_copy.observed_entity_id is distinct from v_canonical.observed_entity_id
         or v_copy.event_type is distinct from v_canonical.event_type
         or (v_copy.status is not null and v_copy.status is distinct from v_canonical.status)
         or nullif(btrim(v_copy.payload->>'comments'), '') is distinct from nullif(btrim(v_canonical.payload->>'comments'), '')
         -- The legacy artifact only ever made the copy one hour late, and only in NZ daylight time.
         or not (v_shift = 0 or (v_shift = 3600 and public.patrol_nz_daylight(v_canonical.occurred_at))) then
        v_hold := 'not_an_identical_copy';
      end if;
    end if;

    -- A second live Update copy of the same visit means the pairing is not one-to-one.
    if v_hold is null and exists (
      select 1
      from public.location_events other
      where other.organization_id = p_client_organization_id
        and other.source = 'rm_patrol_log_import'
        and other.id <> v_copy_id
        and other.id <> v_canonical_id
        and other.payload->>'source_sheet' = 'Update 251215'
        and other.zone_id is not distinct from v_canonical.zone_id
        and other.client_site_id is not distinct from v_canonical.client_site_id
        and other.observed_entity_id is not distinct from v_canonical.observed_entity_id
        and other.event_type is not distinct from v_canonical.event_type
        and (other.status is null or other.status is not distinct from v_canonical.status)
        and nullif(btrim(other.payload->>'comments'), '') is not distinct from nullif(btrim(v_canonical.payload->>'comments'), '')
        and (other.occurred_at = v_canonical.occurred_at
          or (other.occurred_at = v_canonical.occurred_at + interval '1 hour'
            and public.patrol_nz_daylight(v_canonical.occurred_at)))
    ) then
      v_hold := 'ambiguous_update_copy_group';
    end if;

    if v_hold is null then
      v_hold := public.patrol_source_event_dependency_hold(
        p_provider_organization_id, p_client_organization_id, v_canonical_id, v_ref, p_update_batch_id);
    end if;
    if v_hold is null then
      v_hold := public.patrol_source_event_dependency_hold(
        p_provider_organization_id, p_client_organization_id, v_copy_id, v_copy_ref, p_update_batch_id);
    end if;
    if v_hold is not null then
      external_ref := v_update_ref; record_id := v_canonical_id; outcome := 'held'; detail := v_hold;
      return next; continue;
    end if;

    v_patch := jsonb_build_object('location_raw', v_update_payload->'location_raw');
    foreach v_field in array array['reserve_raw', 'source_category', 'comments', 'patroller_raw', 'plates_found']
    loop
      if v_update_payload ? v_field and v_update_payload->v_field not in ('null'::jsonb, '""'::jsonb) then
        v_patch := v_patch || jsonb_build_object(v_field, v_update_payload->v_field);
      end if;
    end loop;
    if (v_canonical.payload || v_patch) is not distinct from v_canonical.payload then
      external_ref := v_update_ref; record_id := v_canonical_id; outcome := 'held'; detail := 'no_source_update_difference';
      return next; continue;
    end if;

    v_copy_before := public.patrol_source_record_state('event', v_copy_id);
    update public.location_events event
    set payload = coalesce(event.payload, '{}'::jsonb) || v_patch
    where event.id = v_canonical_id;
    v_after := public.patrol_source_record_state('event', v_canonical_id);
    v_changed := public.patrol_source_state_diff(v_before, v_after);

    update public.patrol_import_record_versions
    set is_current = false
    where id = v_canonical_version.id;
    -- The canonical keeps its 2025 source identity so a later resync still recognises it;
    -- the Update row is recorded as an overlay with its own provenance.
    insert into public.patrol_import_record_versions(
      provider_organization_id, client_organization_id, record_kind, record_id, external_ref, source_profile,
      source_file, source_sheet, source_row, source_sha256, derivative_sha256, source_fingerprint, batch_id,
      version_no, change_kind, changed_fields, state_before, state_after, applied_by,
      record_fingerprint, overlay_source
    ) values (
      p_provider_organization_id, p_client_organization_id, 'event', v_canonical_id, v_ref,
      v_canonical_version.source_profile, v_canonical_version.source_file, v_canonical_version.source_sheet,
      v_canonical_version.source_row, v_canonical_version.source_sha256,
      v_canonical_version.derivative_sha256, v_canonical_version.source_fingerprint, p_update_batch_id,
      v_canonical_version.version_no + 1, 'update', v_changed, v_before, v_after, auth.uid(),
      v_item->>'record_fingerprint',
      jsonb_build_object(
        'external_ref', v_update_ref,
        'source_file', v_update_payload->>'source_file',
        'source_sheet', v_update_payload->>'source_sheet',
        'source_row', (v_update_payload->>'source_row')::integer,
        'source_sha256', v_update_payload->>'source_sha256',
        'derivative_sha256', v_update_payload->>'derivative_sha256',
        'source_fingerprint', v_item->>'update_source_fingerprint',
        'batch_id', p_update_batch_id)
    );

    select * into v_copy_version
    from public.patrol_import_record_versions version
    where version.record_kind = 'event' and version.record_id = v_copy_id and version.is_current
    for update;
    v_current_copy_version := found;
    if v_current_copy_version and (
      v_copy_version.provider_organization_id <> p_provider_organization_id
      or v_copy_version.client_organization_id <> p_client_organization_id
      or v_copy_version.external_ref <> v_copy_ref
    ) then
      raise exception 'Source history scope does not match the DART Update copy';
    end if;
    if v_current_copy_version then
      update public.patrol_import_record_versions set is_current = false where id = v_copy_version.id;
      v_version_no := v_copy_version.version_no + 1;
    else
      v_version_no := 1;
    end if;
    insert into public.location_events_superseded(
      provider_organization_id, client_organization_id, location_event_id, external_ref,
      canonical_location_event_id, canonical_external_ref, reason_code, batch_id, event_snapshot, superseded_by
    ) values (
      p_provider_organization_id, p_client_organization_id, v_copy_id, v_copy_ref,
      v_canonical_id, v_ref, 'duplicate_of_canonical_sheet', p_update_batch_id, to_jsonb(v_copy), auth.uid()
    );
    insert into public.patrol_import_record_versions(
      provider_organization_id, client_organization_id, record_kind, record_id, external_ref, source_profile,
      source_file, source_sheet, source_row, source_sha256, derivative_sha256, source_fingerprint, batch_id,
      version_no, change_kind, changed_fields, state_before, state_after, applied_by
    ) values (
      p_provider_organization_id, p_client_organization_id, 'event', v_copy_id, v_copy_ref,
      v_update_payload->>'classification_profile', v_update_payload->>'source_file', v_update_payload->>'source_sheet',
      (v_update_payload->>'source_row')::integer, v_update_payload->>'source_sha256',
      v_update_payload->>'derivative_sha256', v_item->>'update_source_fingerprint', p_update_batch_id,
      v_version_no, 'superseded', array['superseded'], v_copy_before,
      jsonb_build_object('superseded_by_external_ref', v_ref, 'canonical_location_event_id', v_canonical_id), auth.uid()
    );
    delete from public.location_events event where event.id = v_copy_id;

    insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
    values (p_provider_organization_id, auth.uid(), 'dart_update_row_applied_and_copy_archived',
      'location_events', v_canonical_id,
      jsonb_build_object('canonical_external_ref', v_ref, 'update_external_ref', v_update_ref,
        'copy_external_ref', v_copy_ref, 'canonical_batch_id', p_canonical_batch_id,
        'update_batch_id', p_update_batch_id, 'source_sheet', v_update_payload->>'source_sheet',
        'source_row', (v_update_payload->>'source_row')::integer, 'changed_fields', to_jsonb(v_changed)));

    external_ref := v_update_ref; record_id := v_canonical_id;
    outcome := 'updated_and_superseded'; detail := array_to_string(v_changed, ',');
    return next;
  end loop;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."apply_dart_patrol_source_updates_and_supersede"(p_canonical_batch_id uuid, p_update_batch_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_items jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."apply_dart_patrol_source_updates_and_supersede"(p_canonical_batch_id uuid, p_update_batch_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_items jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."apply_dart_patrol_source_updates_and_supersede"(p_canonical_batch_id uuid, p_update_batch_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_items jsonb) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."apply_file_import_finance_batch"(p_batch_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid:=auth.uid();
  v_batch public.file_import_batches%rowtype;
  v_proposal public.file_import_row_proposals%rowtype;
  v_period public.finance_pl_periods%rowtype;
  v_cost public.finance_service_costs%rowtype;
  v_month date;
  v_source_count integer;
  v_source_total numeric;
  v_applied integer:=0;
  v_existing integer:=0;
  v_period_count integer;
  v_periods_created integer:=0;
  v_total numeric:=0;
BEGIN
  SELECT * INTO v_batch FROM public.file_import_batches WHERE id=p_batch_id FOR UPDATE;
  IF NOT FOUND OR v_batch.status NOT IN ('approved','applied') OR NOT public.is_tenant_import_admin(v_batch.organization_id) THEN
    RAISE EXCEPTION 'Approved tenant finance import batch required';
  END IF;
  IF v_batch.status='applied' THEN
    SELECT count(*),coalesce(sum(total_cost),0) INTO v_existing,v_total
    FROM public.finance_service_costs cost
    WHERE cost.id IN(SELECT applied_target_id FROM public.file_import_row_proposals WHERE batch_id=v_batch.id AND status='applied');
    RETURN jsonb_build_object('applied',0,'existing',v_existing,'total',round(v_total,2),'batch_status','applied');
  END IF;
  IF EXISTS(SELECT 1 FROM public.file_import_row_proposals WHERE batch_id=v_batch.id AND status NOT IN ('approved','rejected')) THEN
    RAISE EXCEPTION 'Every finance proposal must be approved or rejected before apply';
  END IF;

  FOR v_proposal IN
    SELECT * FROM public.file_import_row_proposals
    WHERE batch_id=v_batch.id AND target_type='finance_service_cost' AND status='approved'
    ORDER BY source_record_key FOR UPDATE
  LOOP
    v_month:=to_date((v_proposal.proposed_payload->>'service_month')||'-01','YYYY-MM-DD');
    PERFORM pg_advisory_xact_lock(hashtextextended(v_batch.organization_id::text||':finance_pl_period:'||v_month::text,0));
    SELECT count(*) INTO v_period_count FROM public.finance_pl_periods
    WHERE organization_id=v_batch.organization_id
      AND daterange(period_start,period_end,'[]') && daterange(v_month,(v_month+interval '1 month'-interval '1 day')::date,'[]');
    IF v_period_count=0 THEN
      INSERT INTO public.finance_pl_periods(
        organization_id,name,period_start,period_end,status,created_by
      ) VALUES(
        v_batch.organization_id,to_char(v_month,'FMMonth YYYY'),v_month,
        (v_month+interval '1 month'-interval '1 day')::date,'draft',v_actor
      ) RETURNING * INTO v_period;
      v_periods_created:=v_periods_created+1;
      INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
      VALUES(v_batch.organization_id,v_actor,'finance_pl_period_created_for_import','finance_pl_periods',v_period.id,
        jsonb_build_object('batch_id',v_batch.id,'period_start',v_period.period_start,'period_end',v_period.period_end));
    ELSIF v_period_count=1 THEN
      SELECT * INTO v_period FROM public.finance_pl_periods
      WHERE organization_id=v_batch.organization_id
        AND period_start<=v_month
        AND period_end>=(v_month+interval '1 month'-interval '1 day')::date;
      IF NOT FOUND OR v_period.status<>'draft' THEN
        RAISE EXCEPTION 'A draft P&L period covering finance proposal month % is required',v_month;
      END IF;
    ELSE
      RAISE EXCEPTION 'Finance proposal month % overlaps more than one P&L period',v_month;
    END IF;
    IF v_proposal.proposed_payload->>'organization_id' IS DISTINCT FROM v_batch.organization_id::text
      OR v_proposal.proposed_payload->>'client_organization_id' IS DISTINCT FROM v_batch.manifest_json->>'target_client_organization_id'
      OR v_proposal.proposed_payload->>'source_document_type'<>'patrol_log'
      OR v_proposal.proposed_payload->>'source_reference' IS DISTINCT FROM
        'rm_patrol:'||v_batch.source_sha256||':'||(v_batch.manifest_json->>'source_sheet')||':'||v_proposal.source_record_key THEN
      RAISE EXCEPTION 'Finance proposal identity or provenance is invalid';
    END IF;
    IF NOT EXISTS(
      SELECT 1 FROM public.service_agreements agreement
      JOIN public.service_agreement_modules module ON module.service_agreement_id=agreement.id AND module.module_key='patrol' AND module.enabled
      WHERE agreement.id=(v_proposal.proposed_payload->>'service_agreement_id')::uuid
        AND agreement.provider_organization_id=v_batch.organization_id
        AND agreement.client_organization_id=(v_proposal.proposed_payload->>'client_organization_id')::uuid
        AND agreement.agreement_type='operational'
    ) THEN RAISE EXCEPTION 'Finance proposal agreement is invalid'; END IF;
    SELECT count(*),coalesce(sum(amount),0) INTO v_source_count,v_source_total
    FROM public.file_import_finance_cost_rows
    WHERE batch_id=v_batch.id AND aggregate_key=v_proposal.source_record_key AND status='eligible';
    IF v_source_count<>(v_proposal.proposed_payload->>'source_row_count')::integer
      OR round(v_source_total,2)<>round((v_proposal.proposed_payload->>'unit_cost')::numeric,2) THEN
      RAISE EXCEPTION 'Finance proposal no longer reconciles to its source rows';
    END IF;

    SELECT * INTO v_cost FROM public.finance_service_costs
    WHERE organization_id=v_batch.organization_id
      AND source_document_type='patrol_log'
      AND source_reference=v_proposal.proposed_payload->>'source_reference'
    FOR UPDATE;
    IF FOUND THEN
      IF v_cost.total_cost<>round(v_source_total,2)
        OR v_cost.service_agreement_id IS DISTINCT FROM (v_proposal.proposed_payload->>'service_agreement_id')::uuid
        OR v_cost.pl_period_id IS DISTINCT FROM v_period.id THEN
        RAISE EXCEPTION 'Existing patrol finance cost conflicts with approved proposal';
      END IF;
      v_existing:=v_existing+1;
    ELSE
      INSERT INTO public.finance_service_costs(
        organization_id,pl_period_id,service_agreement_id,client_organization_id,
        cost_type,source_document_type,source_reference,quantity,unit_of_measure,unit_cost,total_cost,allocation_driver,created_by
      ) VALUES(
        v_batch.organization_id,v_period.id,(v_proposal.proposed_payload->>'service_agreement_id')::uuid,
        (v_proposal.proposed_payload->>'client_organization_id')::uuid,
        v_proposal.proposed_payload->>'cost_type','patrol_log',v_proposal.proposed_payload->>'source_reference',
        1,'source rows',round(v_source_total,4),round(v_source_total,2),'patrol_log_row_reconciliation',v_actor
      ) RETURNING * INTO v_cost;
      v_applied:=v_applied+1;
    END IF;
    UPDATE public.file_import_finance_cost_rows
    SET status='applied',finance_service_cost_id=v_cost.id,applied_at=now()
    WHERE batch_id=v_batch.id AND aggregate_key=v_proposal.source_record_key AND status='eligible';
    UPDATE public.file_import_row_proposals
    SET status='applied',applied_target_id=v_cost.id,applied_at=now(),updated_at=now()
    WHERE id=v_proposal.id;
    v_total:=v_total+v_cost.total_cost;
  END LOOP;
  UPDATE public.file_import_batches SET status='applied',updated_at=now() WHERE id=v_batch.id;
  INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
  VALUES(v_batch.organization_id,v_actor,'file_import_finance_batch_applied','file_import_batches',v_batch.id,
    jsonb_build_object('applied',v_applied,'existing',v_existing,'periods_created',v_periods_created,'total',round(v_total,2)));
  RETURN jsonb_build_object('applied',v_applied,'existing',v_existing,'periods_created',v_periods_created,'total',round(v_total,2),'batch_status','applied');
END;
$function$;
REVOKE ALL ON FUNCTION "public"."apply_file_import_finance_batch"(p_batch_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."apply_file_import_finance_batch"(p_batch_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."apply_file_import_finance_batch"(p_batch_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."apply_file_import_finance_batch"(p_batch_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."apply_finance_reconciliation_proposal"(p_proposal_id uuid, p_client_organization_id uuid, p_service_agreement_id uuid DEFAULT NULL::uuid, p_invoice_number text DEFAULT NULL::text, p_invoice_date date DEFAULT CURRENT_DATE, p_due_date date DEFAULT NULL::date, p_subtotal numeric DEFAULT 0, p_gst_amount numeric DEFAULT 0, p_total_amount numeric DEFAULT 0, p_notes text DEFAULT NULL::text)
 RETURNS TABLE(proposal_id uuid, invoice_id uuid, created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_proposal public.document_promotion_proposals%rowtype;
  v_invoice_id uuid;
  v_due_date date := coalesce(p_due_date, p_invoice_date + 20);
  v_created boolean := false;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT * INTO v_proposal FROM public.document_promotion_proposals WHERE id = p_proposal_id FOR UPDATE;
  IF NOT FOUND OR v_proposal.target_type <> 'finance_reconciliation' OR v_proposal.status <> 'approved' THEN RAISE EXCEPTION 'Only approved finance proposals can be applied'; END IF;
  IF NOT public.is_admin_for_org(v_proposal.organization_id) AND NOT public.is_grand_master() THEN RAISE EXCEPTION 'Finance proposal application denied'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.organizations WHERE id = p_client_organization_id AND organization_type = 'client' AND active) THEN RAISE EXCEPTION 'Active client organisation is required'; END IF;
  IF p_invoice_number IS NULL OR nullif(trim(p_invoice_number), '') IS NULL THEN RAISE EXCEPTION 'Invoice number is required'; END IF;
  IF p_invoice_date IS NULL OR v_due_date < p_invoice_date THEN RAISE EXCEPTION 'Valid invoice and due dates are required'; END IF;
  IF p_subtotal < 0 OR p_gst_amount < 0 OR p_total_amount <= 0 OR p_total_amount <> p_subtotal + p_gst_amount THEN RAISE EXCEPTION 'Invoice totals must be positive and reconcile'; END IF;
  IF p_service_agreement_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.service_agreements WHERE id = p_service_agreement_id AND provider_organization_id = v_proposal.organization_id AND client_organization_id = p_client_organization_id) THEN RAISE EXCEPTION 'Service agreement does not match provider and client'; END IF;
  IF v_proposal.applied_target_id IS NOT NULL THEN RETURN QUERY SELECT v_proposal.id, v_proposal.applied_target_id, false; RETURN; END IF;
  SELECT id INTO v_invoice_id FROM public.invoices WHERE organization_id = v_proposal.organization_id AND invoice_number = trim(p_invoice_number) LIMIT 1;
  IF v_invoice_id IS NULL THEN
    INSERT INTO public.invoices (organization_id, client_organization_id, service_agreement_id, invoice_number, invoice_date, due_date, status, subtotal, gst_amount, total_amount, currency, notes, created_by)
    VALUES (v_proposal.organization_id, p_client_organization_id, p_service_agreement_id, trim(p_invoice_number), p_invoice_date, v_due_date, 'draft', p_subtotal, p_gst_amount, p_total_amount, 'NZD', concat_ws(E'\n', nullif(trim(p_notes), ''), 'Created from document promotion proposal ' || v_proposal.id::text || ' / version ' || v_proposal.document_version_id::text), v_actor)
    RETURNING id INTO v_invoice_id;
    v_created := true;
  END IF;
  UPDATE public.document_promotion_proposals SET status = 'applied', applied_target_id = v_invoice_id, applied_at = clock_timestamp(), updated_at = clock_timestamp() WHERE id = v_proposal.id;
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_proposal.organization_id, v_actor, 'document_promotion_proposal_applied', 'invoices', v_invoice_id, jsonb_build_object('proposal_id', v_proposal.id, 'document_version_id', v_proposal.document_version_id, 'created', v_created, 'status', 'draft'));
  RETURN QUERY SELECT v_proposal.id, v_invoice_id, v_created;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."apply_finance_reconciliation_proposal"(p_proposal_id uuid, p_client_organization_id uuid, p_service_agreement_id uuid, p_invoice_number text, p_invoice_date date, p_due_date date, p_subtotal numeric, p_gst_amount numeric, p_total_amount numeric, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."apply_finance_reconciliation_proposal"(p_proposal_id uuid, p_client_organization_id uuid, p_service_agreement_id uuid, p_invoice_number text, p_invoice_date date, p_due_date date, p_subtotal numeric, p_gst_amount numeric, p_total_amount numeric, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."apply_finance_reconciliation_proposal"(p_proposal_id uuid, p_client_organization_id uuid, p_service_agreement_id uuid, p_invoice_number text, p_invoice_date date, p_due_date date, p_subtotal numeric, p_gst_amount numeric, p_total_amount numeric, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."apply_finance_reconciliation_proposal"(p_proposal_id uuid, p_client_organization_id uuid, p_service_agreement_id uuid, p_invoice_number text, p_invoice_date date, p_due_date date, p_subtotal numeric, p_gst_amount numeric, p_total_amount numeric, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."apply_historical_patrol_labour_routes"(p_organization_id uuid, p_client_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_receipt jsonb;
begin
  if v_actor is null or not public.is_admin_for_org(p_organization_id) then
    raise exception 'Not authorised to route historical labour for this organization';
  end if;
  if p_client_request_id is null then raise exception 'A request ID is required'; end if;

  -- Held until commit, so a concurrent replay waits and then finds this receipt.
  perform pg_advisory_xact_lock(hashtextextended('historical_patrol_labour_routing:' || p_organization_id::text, 0));

  select metadata into v_receipt from public.audit_log
  where organization_id = p_organization_id and action = 'historical_patrol_labour_routed'
    and metadata->>'request_id' = p_client_request_id::text
  limit 1;
  if found then return v_receipt || jsonb_build_object('replayed', true); end if;

  v_receipt := public.route_historical_patrol_labour(p_organization_id, p_client_request_id);
  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (p_organization_id, v_actor, 'historical_patrol_labour_routed', 'roster_slots', null, v_receipt);
  return v_receipt;
end;
$function$;
COMMENT ON FUNCTION "public"."apply_historical_patrol_labour_routes"(p_organization_id uuid, p_client_request_id uuid) IS 'Admin-only, idempotent, audited routing of historical patrol-log labour onto primary-officer patrol routes. Serialised per organisation.';
REVOKE ALL ON FUNCTION "public"."apply_historical_patrol_labour_routes"(p_organization_id uuid, p_client_request_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."apply_historical_patrol_labour_routes"(p_organization_id uuid, p_client_request_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."apply_historical_patrol_labour_routes"(p_organization_id uuid, p_client_request_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."apply_historical_patrol_labour_routes"(p_organization_id uuid, p_client_request_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."apply_historical_roster_assignment_import"(p_client_request_id uuid, p_organization_id uuid, p_client_organization_id uuid, p_source_file text, p_source_sha256 text, p_assignments jsonb, p_unresolved_values jsonb DEFAULT '[]'::jsonb, p_field_source_codes text[] DEFAULT '{}'::text[], p_field_route_by_officer jsonb DEFAULT '{}'::jsonb, p_remove_prior_projection boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_item jsonb;
  v_route public.patrol_routes%rowtype;
  v_officer public.user_profiles%rowtype;
  v_source_key text;
  v_inserted integer := 0;
  v_skipped integer := 0;
  v_field_inserted integer := 0;
  v_prior_slots_removed integer := 0;
  v_prior_route_places_removed integer := 0;
  v_receipt jsonb;
  v_row_count integer;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_client_request_id IS NULL THEN RAISE EXCEPTION 'client_request_id is required'; END IF;
  IF NOT public.is_admin_for_org(p_organization_id) THEN RAISE EXCEPTION 'Roster administrator access required'; END IF;
  IF nullif(trim(coalesce(p_source_file, '')), '') IS NULL THEN RAISE EXCEPTION 'source_file is required'; END IF;
  IF p_source_sha256 !~ '^[A-Fa-f0-9]{64}$' THEN RAISE EXCEPTION 'source_sha256 must be a SHA-256 digest'; END IF;
  IF jsonb_typeof(p_assignments) <> 'array' THEN RAISE EXCEPTION 'assignments must be an array'; END IF;
  IF jsonb_typeof(p_unresolved_values) <> 'array' THEN RAISE EXCEPTION 'unresolved_values must be an array'; END IF;
  IF jsonb_typeof(p_field_route_by_officer) <> 'object' THEN RAISE EXCEPTION 'field_route_by_officer must be an object'; END IF;

  SELECT audit.metadata INTO v_receipt
  FROM public.audit_log audit
  WHERE audit.organization_id = p_organization_id
    AND audit.action = 'historical_roster_assignment_imported'
    AND audit.metadata->>'client_request_id' = p_client_request_id::text
  ORDER BY audit.created_at DESC
  LIMIT 1;
  IF FOUND THEN RETURN v_receipt; END IF;

  IF p_remove_prior_projection THEN
    DELETE FROM public.roster_slots slot
    WHERE slot.organization_id = p_organization_id
      AND slot.external_refs->>'source' = 'rm_patrol_log_roster_projection';
    GET DIAGNOSTICS v_prior_slots_removed = ROW_COUNT;

    DELETE FROM public.patrol_route_zones route_zone
    USING public.patrol_routes route
    WHERE route.id = route_zone.patrol_route_id
      AND route.organization_id = p_organization_id
      AND route.route_code IN ('RM-NELSON-FORESTRY', 'RM-BLENHEIM-FORESTRY')
      AND route_zone.notes = 'Historical coverage evidence; future cadence requires an approved delivery schedule.';
    GET DIAGNOSTICS v_prior_route_places_removed = ROW_COUNT;

    DELETE FROM public.patrol_route_sites route_site
    USING public.patrol_routes route
    WHERE route.id = route_site.patrol_route_id
      AND route.organization_id = p_organization_id
      AND route.route_code IN ('RM-NELSON-FORESTRY', 'RM-BLENHEIM-FORESTRY')
      AND route_site.notes = 'Historical coverage evidence; future cadence requires an approved delivery schedule.';
    GET DIAGNOSTICS v_row_count = ROW_COUNT;
    v_prior_route_places_removed := v_prior_route_places_removed + v_row_count;
  END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_assignments)
  LOOP
    IF nullif(v_item->>'source_key', '') IS NULL
       OR nullif(v_item->>'officer_id', '') IS NULL
       OR nullif(v_item->>'route_code', '') IS NULL
       OR nullif(v_item->>'specific_date', '') IS NULL
       OR (v_item->>'shift') NOT IN ('day', 'swing', 'night', 'overnight') THEN
      RAISE EXCEPTION 'Every assignment requires source_key, officer_id, route_code, specific_date and a valid shift';
    END IF;
    IF (v_item->>'specific_date')::date > current_date THEN
      RAISE EXCEPTION 'Historical assignment % is in the future', v_item->>'source_key';
    END IF;
    SELECT * INTO v_officer FROM public.user_profiles profile
    WHERE profile.id = (v_item->>'officer_id')::uuid
      AND profile.organization_id = p_organization_id
      AND profile.deactivated_at IS NULL;
    IF NOT FOUND THEN RAISE EXCEPTION 'Officer % is not active in this organization', v_item->>'officer_id'; END IF;
    SELECT * INTO v_route FROM public.patrol_routes route
    WHERE route.organization_id = p_organization_id
      AND upper(route.route_code) = upper(v_item->>'route_code')
      AND route.is_active;
    IF NOT FOUND THEN RAISE EXCEPTION 'Active route % was not found', v_item->>'route_code'; END IF;
    v_source_key := v_item->>'source_key';
    IF EXISTS (
      SELECT 1 FROM public.roster_assignments assignment
      WHERE assignment.organization_id = p_organization_id
        AND assignment.external_refs->>'source_key' = v_source_key
    ) THEN
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;
    INSERT INTO public.roster_assignments(
      organization_id, officer_id, patrol_route_id, service_type, specific_date,
      shift, start_time, end_time, assignment_status, notification_sent_at,
      created_by, external_refs
    ) VALUES (
      p_organization_id, v_officer.id, v_route.id, 'patrol', (v_item->>'specific_date')::date,
      v_item->>'shift', nullif(v_item->>'start_time', '')::time, nullif(v_item->>'end_time', '')::time,
      'confirmed', now(), v_actor,
      jsonb_build_object(
        'source', 'rm_forestry_roster_history',
        'source_key', v_source_key,
        'source_file', p_source_file,
        'source_sha256', lower(p_source_sha256),
        'source_sheet', v_item->>'source_sheet',
        'source_rows', coalesce(v_item->'source_rows', '[]'::jsonb),
        'beat_names', coalesce(v_item->'beat_names', '[]'::jsonb),
        'time_precision', coalesce(v_item->>'time_precision', 'date_only')
      )
    );
    v_inserted := v_inserted + 1;
  END LOOP;

  WITH raw AS (
    SELECT event.observed_entity_id AS officer_id, event.occurred_at,
           event.external_ref AS source_ref,
           CASE WHEN event.payload->>'job_time_hours' ~ '^[0-9]+([.][0-9]+)?$'
                THEN least(greatest((event.payload->>'job_time_hours')::numeric, 0), 24)
                ELSE 0 END AS duration_hours
    FROM public.location_events event
    WHERE event.source = 'rm_patrol_log_import'
      AND event.organization_id = p_client_organization_id
      AND event.observed_entity_type = 'staff'
      AND event.observed_entity_id IS NOT NULL
      AND EXISTS (SELECT 1 FROM unnest(p_field_source_codes) code WHERE upper(code) = upper(split_part(event.external_ref, ':', 2)))
    UNION ALL
    SELECT observation.officer_id, observation.observed_at,
           observation.external_refs->>'external_ref',
           CASE WHEN observation.external_refs->'import'->>'job_time_hours' ~ '^[0-9]+([.][0-9]+)?$'
                THEN least(greatest((observation.external_refs->'import'->>'job_time_hours')::numeric, 0), 24)
                ELSE 0 END
    FROM public.observations observation
    WHERE observation.organization_id = p_client_organization_id
      AND EXISTS (SELECT 1 FROM unnest(p_field_source_codes) code WHERE upper(code) = upper(split_part(observation.external_refs->>'external_ref', ':', 2)))
  ), grouped AS (
    SELECT raw.officer_id,
           (raw.occurred_at AT TIME ZONE 'Pacific/Auckland')::date AS work_date,
           min(raw.occurred_at AT TIME ZONE 'Pacific/Auckland') AS first_local,
           max((raw.occurred_at AT TIME ZONE 'Pacific/Auckland') + make_interval(secs => raw.duration_hours::double precision * 3600)) AS last_local,
           count(*)::integer AS source_event_count,
           jsonb_agg(raw.source_ref ORDER BY raw.occurred_at, raw.source_ref) AS source_event_refs
    FROM raw
    WHERE (raw.occurred_at AT TIME ZONE 'Pacific/Auckland')::date <= current_date
    GROUP BY raw.officer_id, (raw.occurred_at AT TIME ZONE 'Pacific/Auckland')::date
  )
  INSERT INTO public.roster_assignments(
    organization_id, officer_id, patrol_route_id, service_type, specific_date,
    shift, start_time, end_time, assignment_status, notification_sent_at,
    created_by, external_refs
  )
  SELECT p_organization_id, profile.id, route.id, 'patrol', grouped.work_date,
         CASE WHEN extract(hour FROM grouped.first_local) < 6 OR extract(hour FROM grouped.first_local) >= 20 THEN 'night'
              WHEN extract(hour FROM grouped.first_local) >= 14 THEN 'swing' ELSE 'day' END,
         grouped.first_local::time,
         CASE WHEN grouped.last_local::date = grouped.work_date AND grouped.last_local > grouped.first_local THEN grouped.last_local::time ELSE NULL END,
         'confirmed', now(), v_actor,
         jsonb_build_object(
           'source', 'rm_patrol_log_roster_evidence',
           'source_key', 'rm_patrol_log_roster:' || profile.id::text || ':' || grouped.work_date::text,
           'source_codes', to_jsonb(p_field_source_codes),
           'source_event_count', grouped.source_event_count,
           'source_event_refs', grouped.source_event_refs,
           'time_precision', 'field_evidence'
         )
  FROM grouped
  JOIN public.user_profiles profile ON profile.id = grouped.officer_id
    AND profile.organization_id = p_organization_id AND profile.deactivated_at IS NULL
  JOIN public.patrol_routes route ON route.organization_id = p_organization_id
    AND upper(route.route_code) = upper(p_field_route_by_officer->>grouped.officer_id::text)
    AND route.is_active
  WHERE NOT EXISTS (
    SELECT 1 FROM public.roster_assignments existing
    WHERE existing.organization_id = p_organization_id
      AND existing.officer_id = profile.id
      AND existing.specific_date = grouped.work_date
      AND existing.external_refs->>'source' = 'rm_forestry_roster_history'
  )
  AND NOT EXISTS (
    SELECT 1 FROM public.roster_assignments existing
    WHERE existing.organization_id = p_organization_id
      AND existing.external_refs->>'source_key' = 'rm_patrol_log_roster:' || profile.id::text || ':' || grouped.work_date::text
  );
  GET DIAGNOSTICS v_field_inserted = ROW_COUNT;

  v_receipt := jsonb_build_object(
    'client_request_id', p_client_request_id,
    'organization_id', p_organization_id,
    'source_file', p_source_file,
    'source_sha256', lower(p_source_sha256),
    'dedicated_assignments_received', jsonb_array_length(p_assignments),
    'dedicated_assignments_inserted', v_inserted,
    'dedicated_assignments_skipped', v_skipped,
    'field_assignments_inserted', v_field_inserted,
    'unresolved_values', p_unresolved_values,
    'prior_slots_removed', v_prior_slots_removed,
    'prior_route_places_removed', v_prior_route_places_removed,
    'notifications_created', 0,
    'shifts_created', 0
  );
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, metadata)
  VALUES (p_organization_id, v_actor, 'historical_roster_assignment_imported', 'roster_assignments', v_receipt);
  RETURN v_receipt;
END;
$function$;
COMMENT ON FUNCTION "public"."apply_historical_roster_assignment_import"(p_client_request_id uuid, p_organization_id uuid, p_client_organization_id uuid, p_source_file text, p_source_sha256 text, p_assignments jsonb, p_unresolved_values jsonb, p_field_source_codes text[], p_field_route_by_officer jsonb, p_remove_prior_projection boolean) IS 'Imports date-specific historical assignments from R&M roster evidence, supplements missing dates from field-log evidence, suppresses historical notifications, and optionally removes the superseded task-geocode roster_slots projection. PostgreSQL-only, audited and replay-safe.';
REVOKE ALL ON FUNCTION "public"."apply_historical_roster_assignment_import"(p_client_request_id uuid, p_organization_id uuid, p_client_organization_id uuid, p_source_file text, p_source_sha256 text, p_assignments jsonb, p_unresolved_values jsonb, p_field_source_codes text[], p_field_route_by_officer jsonb, p_remove_prior_projection boolean) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."apply_historical_roster_assignment_import"(p_client_request_id uuid, p_organization_id uuid, p_client_organization_id uuid, p_source_file text, p_source_sha256 text, p_assignments jsonb, p_unresolved_values jsonb, p_field_source_codes text[], p_field_route_by_officer jsonb, p_remove_prior_projection boolean) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."apply_hr_document_promotion_proposal"(p_proposal_id uuid, p_staff_id uuid, p_document_type text, p_file_name text, p_storage_path text, p_expiry_date date DEFAULT NULL::date, p_notes text DEFAULT NULL::text)
 RETURNS TABLE(proposal_id uuid, staff_document_id uuid, created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_proposal public.document_promotion_proposals%rowtype;
  v_org_id uuid;
  v_document_id uuid;
  v_created boolean := false;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_document_type NOT IN ('credential_evidence','contract','certificate','policy_acknowledgement','other') THEN RAISE EXCEPTION 'Unsupported staff document type'; END IF;
  IF nullif(trim(coalesce(p_file_name, '')), '') IS NULL OR nullif(trim(coalesce(p_storage_path, '')), '') IS NULL THEN RAISE EXCEPTION 'File name and secure storage path are required'; END IF;
  SELECT * INTO v_proposal FROM public.document_promotion_proposals WHERE id = p_proposal_id FOR UPDATE;
  IF NOT FOUND OR v_proposal.target_type <> 'hr_case' OR v_proposal.status <> 'approved' THEN RAISE EXCEPTION 'Only approved HR proposals can be applied'; END IF;
  SELECT sp.organization_id INTO v_org_id FROM public.staff_profiles sp WHERE sp.id = p_staff_id;
  IF v_org_id IS NULL THEN RAISE EXCEPTION 'Staff profile not found'; END IF;
  IF v_org_id <> v_proposal.organization_id THEN RAISE EXCEPTION 'Staff profile is outside proposal organisation'; END IF;
  IF NOT public.is_admin_for_org(v_org_id) AND NOT public.is_grand_master() THEN RAISE EXCEPTION 'HR document application denied'; END IF;
  IF v_proposal.applied_target_id IS NOT NULL THEN RETURN QUERY SELECT v_proposal.id, v_proposal.applied_target_id, false; RETURN; END IF;
  SELECT id INTO v_document_id FROM public.staff_documents WHERE staff_id = p_staff_id AND organization_id = v_org_id AND storage_path = trim(p_storage_path) LIMIT 1;
  IF v_document_id IS NULL THEN
    INSERT INTO public.staff_documents (staff_id, organization_id, document_type, file_name, storage_path, expiry_date, notes, uploaded_by)
    VALUES (p_staff_id, v_org_id, p_document_type, trim(p_file_name), trim(p_storage_path), p_expiry_date, nullif(trim(p_notes), ''), v_actor)
    RETURNING id INTO v_document_id;
    v_created := true;
  END IF;
  UPDATE public.document_promotion_proposals SET status = 'applied', applied_target_id = v_document_id, applied_at = clock_timestamp(), updated_at = clock_timestamp() WHERE id = v_proposal.id;
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_org_id, v_actor, 'document_promotion_proposal_applied', 'staff_documents', v_document_id, jsonb_build_object('proposal_id', v_proposal.id, 'document_version_id', v_proposal.document_version_id, 'created', v_created, 'document_type', p_document_type));
  RETURN QUERY SELECT v_proposal.id, v_document_id, v_created;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."apply_hr_document_promotion_proposal"(p_proposal_id uuid, p_staff_id uuid, p_document_type text, p_file_name text, p_storage_path text, p_expiry_date date, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."apply_hr_document_promotion_proposal"(p_proposal_id uuid, p_staff_id uuid, p_document_type text, p_file_name text, p_storage_path text, p_expiry_date date, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."apply_hr_document_promotion_proposal"(p_proposal_id uuid, p_staff_id uuid, p_document_type text, p_file_name text, p_storage_path text, p_expiry_date date, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."apply_hr_document_promotion_proposal"(p_proposal_id uuid, p_staff_id uuid, p_document_type text, p_file_name text, p_storage_path text, p_expiry_date date, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."apply_investigation_link_promotion_proposal"(p_proposal_id uuid, p_investigation_id uuid, p_entity_type text, p_entity_id uuid, p_link_role text DEFAULT 'supporting'::text, p_link_reason text DEFAULT NULL::text)
 RETURNS TABLE(proposal_id uuid, link_id uuid, created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_proposal public.document_promotion_proposals%rowtype;
  v_investigation public.investigations%rowtype;
  v_link public.investigation_links%rowtype;
  v_created boolean := false;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_entity_type NOT IN ('observation','field_report','incident','evidence','site','zone','person','vehicle','dispatch_job') THEN RAISE EXCEPTION 'Unsupported investigation entity type'; END IF;
  IF p_link_role NOT IN ('primary','supporting','context','lead','excluded') THEN RAISE EXCEPTION 'Unsupported investigation link role'; END IF;
  IF nullif(trim(coalesce(p_link_reason, '')), '') IS NULL THEN RAISE EXCEPTION 'Investigation link reason is required'; END IF;
  SELECT * INTO v_proposal FROM public.document_promotion_proposals WHERE id = p_proposal_id FOR UPDATE;
  IF NOT FOUND OR v_proposal.target_type <> 'investigation_link' OR v_proposal.status <> 'approved' THEN RAISE EXCEPTION 'Only approved investigation-link proposals can be applied'; END IF;
  SELECT * INTO v_investigation FROM public.investigations WHERE id = p_investigation_id FOR UPDATE;
  IF NOT FOUND OR v_investigation.organization_id <> v_proposal.organization_id THEN RAISE EXCEPTION 'Investigation is outside proposal organisation'; END IF;
  IF NOT public.is_admin_for_org(v_investigation.organization_id) AND NOT public.is_grand_master() THEN RAISE EXCEPTION 'Investigation link application denied'; END IF;
  IF v_proposal.applied_target_id IS NOT NULL THEN RETURN QUERY SELECT v_proposal.id, v_proposal.applied_target_id, false; RETURN; END IF;
  v_link := public.link_investigation_entity(p_investigation_id, p_entity_type, p_entity_id, p_link_role, trim(p_link_reason));
  IF v_link.id IS NULL THEN RAISE EXCEPTION 'Investigation link receipt was not confirmed'; END IF;
  v_created := true;
  UPDATE public.document_promotion_proposals SET status = 'applied', applied_target_id = v_link.id, applied_at = clock_timestamp(), updated_at = clock_timestamp() WHERE id = v_proposal.id;
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_proposal.organization_id, v_actor, 'document_promotion_proposal_applied', 'investigation_links', v_link.id, jsonb_build_object('proposal_id', v_proposal.id, 'document_version_id', v_proposal.document_version_id, 'created', v_created, 'entity_type', p_entity_type, 'entity_id', p_entity_id));
  RETURN QUERY SELECT v_proposal.id, v_link.id, v_created;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."apply_investigation_link_promotion_proposal"(p_proposal_id uuid, p_investigation_id uuid, p_entity_type text, p_entity_id uuid, p_link_role text, p_link_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."apply_investigation_link_promotion_proposal"(p_proposal_id uuid, p_investigation_id uuid, p_entity_type text, p_entity_id uuid, p_link_role text, p_link_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."apply_investigation_link_promotion_proposal"(p_proposal_id uuid, p_investigation_id uuid, p_entity_type text, p_entity_id uuid, p_link_role text, p_link_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."apply_investigation_link_promotion_proposal"(p_proposal_id uuid, p_investigation_id uuid, p_entity_type text, p_entity_id uuid, p_link_role text, p_link_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."apply_patrol_source_updates"(p_batch_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_updates jsonb)
 RETURNS TABLE(external_ref text, record_id uuid, outcome text, detail text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_batch public.file_import_batches%rowtype;
  v_item jsonb;
  v_desired jsonb;
  v_payload jsonb;
  v_kind text;
  v_ref text;
  v_id uuid;
  v_version public.patrol_import_record_versions%rowtype;
  v_observation public.observations%rowtype;
  v_before jsonb;
  v_after jsonb;
  v_changed text[];
  v_zone uuid;
  v_site uuid;
  v_officer uuid;
  v_occurred timestamptz;
  v_distance numeric;
  v_plate text;
  v_vehicle uuid;
  v_hold text;
  v_updated integer := 0;
  v_ignored constant text[] := array['source', 'source_file', 'source_sheet', 'source_row', 'source_sha256', 'derivative_sha256',
    'classification_profile', 'source_profile', 'evidence_record_type', 'evidence_external_ref', 'client_organization_id'];
begin
  v_batch := public.patrol_source_sync_batch(p_batch_id, p_provider_organization_id, p_client_organization_id);
  if jsonb_typeof(p_updates) <> 'array' or jsonb_array_length(p_updates) > 500 then
    raise exception 'Between 0 and 500 update rows are required per call';
  end if;

  for v_item in
    select value from jsonb_array_elements(p_updates) value order by value->>'kind', value->>'external_ref'
  loop
    v_payload := public.patrol_source_assert_row_provenance(v_batch, v_item);
    if coalesce(v_item->>'prior_source_fingerprint', '') !~ '^[a-f0-9]{64}$' then
      raise exception 'Source updates require the prior source fingerprint';
    end if;
    v_kind := v_item->>'kind';
    v_ref := v_item->>'external_ref';
    v_id := (v_item->>'record_id')::uuid;
    v_desired := v_item->'desired';
    v_hold := null;
    perform pg_advisory_xact_lock(hashtextextended(p_client_organization_id::text || ':evidence:' || v_ref, 0));

    select * into v_version from public.patrol_import_record_versions version
    where version.record_kind = v_kind and version.record_id = v_id and version.is_current
    for update;
    if not found then
      v_hold := 'source_baseline_required';
    elsif v_version.client_organization_id <> p_client_organization_id
       or v_version.provider_organization_id <> p_provider_organization_id
       or v_version.external_ref <> v_ref then
      raise exception 'Source history scope does not match the requested record';
    elsif v_version.source_fingerprint = v_item->>'source_fingerprint' and v_version.batch_id = p_batch_id then
      external_ref := v_ref; record_id := v_id; outcome := 'already_applied'; detail := null;
      return next; continue;
    elsif v_version.source_fingerprint <> v_item->>'prior_source_fingerprint' then
      v_hold := 'stale_source_comparison';
    elsif v_version.source_file <> v_payload->>'source_file'
       or v_version.source_sheet is distinct from v_payload->>'source_sheet'
       or v_version.source_profile <> v_payload->>'classification_profile' then
      v_hold := 'source_identity_changed';
    end if;

    if v_hold is null then
      v_before := public.patrol_source_record_state(v_kind, v_id);
      if v_before is null then
        v_hold := 'previously_linked_record_missing';
      elsif v_before is distinct from v_version.state_after then
        v_hold := 'fcm_record_changed_since_last_sync';
      end if;
    end if;

    if v_hold is null then
      v_occurred := (v_desired->>'occurred_at')::timestamptz;
      v_zone := nullif(v_desired->>'zone_id', '')::uuid;
      v_site := nullif(v_desired->>'site_id', '')::uuid;
      v_officer := nullif(v_desired->>(case when v_kind = 'event' then 'observed_entity_id' else 'officer_id' end), '')::uuid;
      v_distance := case when v_desired->'distance_km' is null or jsonb_typeof(v_desired->'distance_km') = 'null'
        then null else (v_desired->>'distance_km')::numeric end;
      if (v_zone is null) = (v_site is null) then
        v_hold := 'one_resolved_place_required';
      elsif v_distance is not null and v_distance < 0 then
        v_hold := 'invalid_source_distance';
      elsif not exists (
        select 1 from public.service_agreements agreement
        join public.service_agreement_modules module
          on module.service_agreement_id = agreement.id and module.module_key = 'patrol' and module.enabled
        join public.service_agreement_locations location
          on location.service_agreement_id = agreement.id and location.status = 'active'
        where agreement.provider_organization_id = p_provider_organization_id
          and agreement.client_organization_id = p_client_organization_id
          and agreement.agreement_type = 'operational'
          and (agreement.starts_on is null or agreement.starts_on <= current_date)
          and (agreement.ends_on is null or agreement.ends_on >= current_date)
          and ((v_zone is not null and location.zone_id = v_zone) or (v_site is not null and location.site_id = v_site))
      ) then
        v_hold := 'place_outside_contracted_patrol_coverage';
      elsif (v_officer is not null or v_kind = 'observation') and not exists (
        select 1 from public.user_profiles profile
        where profile.id = v_officer and profile.deactivated_at is null
          and (profile.organization_id = p_provider_organization_id or profile.employer_organization_id = p_provider_organization_id)
      ) then
        v_hold := 'source_staff_not_active_for_provider';
      elsif exists (
        select 1
        from public.file_import_row_proposals proposal
        cross join lateral jsonb_each(proposal.source_values) source_value
        where proposal.organization_id = p_provider_organization_id
          and proposal.source_record_key = v_ref
          -- Only an undecided or unapplied review of the old values blocks the edit; applied
          -- outcomes are revisited through the fresh proposal staged in this batch.
          and proposal.batch_id <> p_batch_id
          and proposal.status in ('proposed', 'approved')
          and source_value.key <> all (v_ignored)
          and v_payload ? source_value.key
          and v_payload->source_value.key is distinct from source_value.value
      ) then
        v_hold := 'dependent_proposal_review_required';
      end if;
    end if;

    if v_hold is null and v_kind = 'observation' then
      select * into v_observation from public.observations where id = v_id for update;
      v_plate := upper(btrim(v_desired->>'plate'));
      if nullif(v_plate, '') is null then
        v_hold := 'observation_plate_required';
      elsif v_observation.locked_at is not null and (
        v_observation.observed_at is distinct from v_occurred
        or upper(v_observation.plate_number) is distinct from v_plate
        or v_observation.officer_id is distinct from v_officer
        or v_observation.zone_id is distinct from v_zone
      ) then
        v_hold := 'locked_evidence_requires_correction_review';
      end if;
    end if;

    if v_hold is not null then
      external_ref := v_ref; record_id := v_id; outcome := 'held'; detail := v_hold;
      return next; continue;
    end if;

    if v_kind = 'event' then
      update public.location_events event
      set occurred_at = v_occurred,
          zone_id = v_zone,
          client_site_id = v_site,
          observed_entity_id = v_officer,
          observed_entity_type = v_desired->>'observed_entity_type',
          event_type = v_desired->>'event_type',
          status = v_desired->>'status',
          distance_km = v_distance,
          payload = v_payload
      where event.id = v_id and event.organization_id = p_client_organization_id
        and event.external_ref = v_ref and event.source = 'rm_patrol_log_import';
    else
      if upper(v_observation.plate_number) is distinct from v_plate then
        perform pg_advisory_xact_lock(hashtextextended('vehicle:' || v_plate, 0));
        select id into v_vehicle from public.canonical_vehicles where upper(plate_number) = v_plate limit 1;
        if v_vehicle is null then
          insert into public.canonical_vehicles(plate_number, compliance_source) values (v_plate, 'canonical') returning id into v_vehicle;
        end if;
      else
        v_vehicle := v_observation.canonical_vehicle_id;
      end if;
      update public.observations observation
      set observed_at = v_occurred,
          -- Plate identity is case-insensitive; keep the stored spelling so locked evidence is not rewritten.
          plate_number = case when upper(observation.plate_number) = v_plate then observation.plate_number else v_plate end,
          canonical_vehicle_id = v_vehicle,
          zone_id = v_zone,
          site_id = v_site,
          officer_id = v_officer,
          officer_notes = v_desired->>'officer_notes',
          distance_km = v_distance,
          external_refs = jsonb_set(coalesce(observation.external_refs, '{}'::jsonb), '{import}', v_payload, true)
      where observation.id = v_id and observation.organization_id = p_client_organization_id
        and observation.external_refs->>'external_ref' = v_ref;
    end if;
    if not found then
      raise exception 'Source update target changed during synchronisation';
    end if;

    v_after := public.patrol_source_record_state(v_kind, v_id);
    v_changed := public.patrol_source_state_diff(v_before, v_after);

    update public.patrol_import_record_versions set is_current = false where id = v_version.id;
    insert into public.patrol_import_record_versions(
      provider_organization_id, client_organization_id, record_kind, record_id, external_ref, source_profile,
      source_file, source_sheet, source_row, source_sha256, derivative_sha256, source_fingerprint, batch_id,
      version_no, change_kind, changed_fields, state_before, state_after, applied_by
    ) values (
      p_provider_organization_id, p_client_organization_id, v_kind, v_id, v_ref, v_payload->>'classification_profile',
      v_payload->>'source_file', v_payload->>'source_sheet', (v_payload->>'source_row')::integer,
      v_payload->>'source_sha256', v_payload->>'derivative_sha256', v_item->>'source_fingerprint', p_batch_id,
      v_version.version_no + 1, 'update', v_changed, v_before, v_after, auth.uid()
    );

    insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
    values (p_provider_organization_id, auth.uid(), 'patrol_source_row_updated',
      case v_kind when 'event' then 'location_events' else 'observations' end, v_id,
      jsonb_build_object('batch_id', p_batch_id, 'client_organization_id', p_client_organization_id,
        'external_ref', v_ref, 'version_no', v_version.version_no + 1, 'changed_fields', to_jsonb(v_changed),
        'source_file', v_payload->>'source_file', 'source_sheet', v_payload->>'source_sheet',
        'source_row', (v_payload->>'source_row')::integer, 'source_sha256', v_payload->>'source_sha256'));

    v_updated := v_updated + 1;
    external_ref := v_ref; record_id := v_id; outcome := 'updated'; detail := array_to_string(v_changed, ',');
    return next;
  end loop;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."apply_patrol_source_updates"(p_batch_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_updates jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."apply_patrol_source_updates"(p_batch_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_updates jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."apply_patrol_source_updates"(p_batch_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_updates jsonb) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."apply_person_interaction_details"(p_interaction_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_pi public.person_interactions%rowtype;
  v_person public.person_records%rowtype;
  v_notes text;
BEGIN
  SELECT * INTO v_pi FROM public.person_interactions WHERE id = p_interaction_id;
  IF v_pi.id IS NULL OR v_pi.proposed_details IS NULL THEN RAISE EXCEPTION 'There are no details to apply for this interaction'; END IF;
  SELECT * INTO v_person FROM public.person_records
  WHERE id = v_pi.person_record_id AND organization_id = v_pi.organization_id
    AND NOT (metadata ? 'merged_into_person_record_id')
    AND NOT (metadata ? 'resolved_into_person_record_id');
  IF v_person.id IS NULL THEN RAISE EXCEPTION 'The person record for these details no longer exists; update the merged record instead'; END IF;
  -- A description adds to the record's notes rather than replacing what is already known.
  v_notes := nullif(concat_ws(E'\n', nullif(trim(v_person.metadata->'profile_details'->>'notes'), ''),
    v_pi.proposed_details->>'description'), '');
  PERFORM public.manage_identity_person(v_pi.organization_id, v_person.id, 'update', jsonb_strip_nulls(jsonb_build_object(
    'display_name', v_person.display_name,
    'notes', CASE WHEN v_pi.proposed_details ? 'description' THEN v_notes END,
    'phone', v_pi.proposed_details->>'phone',
    'address', v_pi.proposed_details->>'address',
    'date_of_birth', v_pi.proposed_details->>'date_of_birth')), p_reason);
END;
$function$;
REVOKE ALL ON FUNCTION "public"."apply_person_interaction_details"(p_interaction_id uuid, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."apply_person_interaction_details"(p_interaction_id uuid, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."apply_person_interaction_details"(p_interaction_id uuid, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."apply_site_brief_promotion_proposal"(p_proposal_id uuid, p_name text, p_work_unit_type text, p_service_type text, p_patrol_route_id uuid DEFAULT NULL::uuid, p_service_agreement_location_id uuid DEFAULT NULL::uuid, p_service_agreement_module_id uuid DEFAULT NULL::uuid, p_workplace_id uuid DEFAULT NULL::uuid, p_team_id uuid DEFAULT NULL::uuid, p_cost_centre_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(proposal_id uuid, work_unit_id uuid, created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_proposal public.document_promotion_proposals%rowtype;
  v_unit public.roster_work_units%rowtype;
  v_created boolean := false;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT * INTO v_proposal FROM public.document_promotion_proposals WHERE id = p_proposal_id FOR UPDATE;
  IF NOT FOUND OR v_proposal.target_type <> 'site_brief' OR v_proposal.status <> 'approved' THEN RAISE EXCEPTION 'Only approved site brief proposals can be applied'; END IF;
  IF NOT public.is_admin_for_org(v_proposal.organization_id) AND NOT public.is_grand_master() THEN RAISE EXCEPTION 'Site brief application denied'; END IF;
  IF v_proposal.applied_target_id IS NOT NULL THEN RETURN QUERY SELECT v_proposal.id, v_proposal.applied_target_id, false; RETURN; END IF;
  IF p_work_unit_type NOT IN ('patrol','static','internal') THEN RAISE EXCEPTION 'Unsupported work unit type'; END IF;
  IF nullif(trim(coalesce(p_name, '')), '') IS NULL OR nullif(trim(coalesce(p_service_type, '')), '') IS NULL THEN RAISE EXCEPTION 'Work unit name and service type are required'; END IF;
  SELECT * INTO v_unit FROM public.create_roster_work_unit(trim(p_name), p_work_unit_type, trim(p_service_type), p_patrol_route_id, p_service_agreement_location_id, p_service_agreement_module_id, p_workplace_id, p_team_id, p_cost_centre_id);
  IF v_unit.id IS NULL THEN RAISE EXCEPTION 'Work unit creation was not confirmed'; END IF;
  v_created := true;
  UPDATE public.document_promotion_proposals SET status = 'applied', applied_target_id = v_unit.id, applied_at = clock_timestamp(), updated_at = clock_timestamp() WHERE id = v_proposal.id;
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_proposal.organization_id, v_actor, 'document_promotion_proposal_applied', 'roster_work_units', v_unit.id, jsonb_build_object('proposal_id', v_proposal.id, 'document_version_id', v_proposal.document_version_id, 'created', v_created, 'work_unit_type', p_work_unit_type));
  RETURN QUERY SELECT v_proposal.id, v_unit.id, v_created;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."apply_site_brief_promotion_proposal"(p_proposal_id uuid, p_name text, p_work_unit_type text, p_service_type text, p_patrol_route_id uuid, p_service_agreement_location_id uuid, p_service_agreement_module_id uuid, p_workplace_id uuid, p_team_id uuid, p_cost_centre_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."apply_site_brief_promotion_proposal"(p_proposal_id uuid, p_name text, p_work_unit_type text, p_service_type text, p_patrol_route_id uuid, p_service_agreement_location_id uuid, p_service_agreement_module_id uuid, p_workplace_id uuid, p_team_id uuid, p_cost_centre_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."apply_site_brief_promotion_proposal"(p_proposal_id uuid, p_name text, p_work_unit_type text, p_service_type text, p_patrol_route_id uuid, p_service_agreement_location_id uuid, p_service_agreement_module_id uuid, p_workplace_id uuid, p_team_id uuid, p_cost_centre_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."apply_site_brief_promotion_proposal"(p_proposal_id uuid, p_name text, p_work_unit_type text, p_service_type text, p_patrol_route_id uuid, p_service_agreement_location_id uuid, p_service_agreement_module_id uuid, p_workplace_id uuid, p_team_id uuid, p_cost_centre_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."approve_cctv_export"(p_export_id uuid, p_approval_state text)
 RETURNS cctv_exports
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  actor_id uuid := auth.uid();
  export_row public.cctv_exports;
  previous_state text;
BEGIN
  IF actor_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  IF p_approval_state NOT IN ('submitted', 'approved', 'rejected') THEN
    RAISE EXCEPTION 'Invalid export approval state';
  END IF;

  SELECT *
    INTO export_row
    FROM public.cctv_exports
   WHERE id = p_export_id
   FOR UPDATE;

  IF NOT FOUND OR NOT public.org_access_allowed(export_row.organization_id) THEN
    RAISE EXCEPTION 'CCTV export not found or access denied';
  END IF;

  previous_state := export_row.approval_state;

  IF p_approval_state = 'submitted' THEN
    IF previous_state <> 'draft' THEN
      RAISE EXCEPTION 'Only draft exports may be submitted';
    END IF;
    IF export_row.generated_by <> actor_id
       AND NOT public.is_admin_for_org(export_row.organization_id) THEN
      RAISE EXCEPTION 'Only the export author or an organization administrator may submit this draft';
    END IF;
  ELSE
    IF NOT public.is_admin_for_org(export_row.organization_id) THEN
      RAISE EXCEPTION 'Organization administrator authority is required to approve or reject CCTV exports';
    END IF;
    IF previous_state <> 'submitted' THEN
      RAISE EXCEPTION 'Only submitted exports may be approved or rejected';
    END IF;
  END IF;

  UPDATE public.cctv_exports
     SET approval_state = p_approval_state,
         approved_by = CASE WHEN p_approval_state = 'approved' THEN actor_id ELSE NULL END,
         approved_at = CASE WHEN p_approval_state = 'approved' THEN clock_timestamp() ELSE NULL END
   WHERE id = p_export_id
   RETURNING * INTO export_row;

  INSERT INTO public.audit_log (
    organization_id,
    actor_user_id,
    action,
    target_table,
    target_id,
    metadata
  )
  VALUES (
    export_row.organization_id,
    actor_id,
    'cctv_export_approval_changed',
    'cctv_exports',
    p_export_id,
    jsonb_build_object(
      'previous_state', previous_state,
      'approval_state', p_approval_state,
      'manifest_sha256', export_row.manifest_sha256
    )
  );

  RETURN export_row;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."approve_cctv_export"(p_export_id uuid, p_approval_state text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."approve_cctv_export"(p_export_id uuid, p_approval_state text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."approve_cctv_export"(p_export_id uuid, p_approval_state text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."approve_cctv_export"(p_export_id uuid, p_approval_state text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."approve_cctv_identity_draft"(p_draft_id uuid, p_final_action text, p_final_person_record_id uuid DEFAULT NULL::uuid, p_review_notes text DEFAULT NULL::text)
 RETURNS cctv_identity_drafts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  draft_row public.cctv_identity_drafts;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'User must be authenticated to approve a draft identity';
  END IF;

  SELECT * INTO draft_row
    FROM public.cctv_identity_drafts
   WHERE id = p_draft_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Identity draft not found';
  END IF;

  IF NOT public.org_access_allowed(draft_row.organization_id) THEN
    RAISE EXCEPTION 'Identity draft access denied';
  END IF;

  IF p_final_action NOT IN ('approve_draft', 'create_new_record', 'match_existing', 'reject', 'relocate', 'manual_review') THEN
    RAISE EXCEPTION 'Invalid final action';
  END IF;

  IF p_final_action IN ('match_existing', 'relocate', 'approve_draft') AND p_final_person_record_id IS NULL THEN
    RAISE EXCEPTION 'Final person record is required for an identity action';
  END IF;

  IF p_final_person_record_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.person_records
    WHERE id = p_final_person_record_id
      AND organization_id = draft_row.organization_id
  ) THEN
    RAISE EXCEPTION 'Final person record is not in the draft organization';
  END IF;

  IF p_final_action = 'create_new_record' THEN
    RAISE EXCEPTION 'Create the new canonical record before approving this draft';
  END IF;

  UPDATE public.cctv_identity_drafts
     SET status = CASE
       WHEN p_final_action = 'reject' THEN 'rejected'
       WHEN p_final_action = 'manual_review' THEN 'escalated'
       WHEN p_final_action = 'relocate' THEN 'relocated'
       WHEN p_final_action = 'create_new_record' THEN 'approved'
       WHEN p_final_action = 'match_existing' THEN 'approved'
       WHEN p_final_action = 'approve_draft' THEN 'approved'
       ELSE 'draft'
     END,
     authority_level = CASE
       WHEN p_final_action = 'reject' THEN 'provisional'
       ELSE 'approved'
     END,
     final_action = p_final_action,
     final_person_record_id = p_final_person_record_id,
     review_notes = NULLIF(trim(p_review_notes), ''),
     approved_by = auth.uid(),
     approved_at = clock_timestamp(),
     updated_at = clock_timestamp()
   WHERE id = p_draft_id
   RETURNING * INTO draft_row;

  RETURN draft_row;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."approve_cctv_identity_draft"(p_draft_id uuid, p_final_action text, p_final_person_record_id uuid, p_review_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."approve_cctv_identity_draft"(p_draft_id uuid, p_final_action text, p_final_person_record_id uuid, p_review_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."approve_cctv_identity_draft"(p_draft_id uuid, p_final_action text, p_final_person_record_id uuid, p_review_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."approve_cctv_identity_draft"(p_draft_id uuid, p_final_action text, p_final_person_record_id uuid, p_review_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."approve_finance_budget"(p_budget_id uuid)
 RETURNS finance_budgets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_budget public.finance_budgets%rowtype;
BEGIN
  SELECT organization_id INTO v_org FROM public.user_profiles WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_org IS NULL OR NOT public.is_admin_for_org(v_org) THEN RAISE EXCEPTION 'Active finance administrator required'; END IF;
  SELECT * INTO v_budget FROM public.finance_budgets WHERE id = p_budget_id AND organization_id = v_org FOR UPDATE;
  IF NOT FOUND OR v_budget.status <> 'draft' THEN RAISE EXCEPTION 'Only draft budgets can be approved'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.finance_budget_lines WHERE budget_id = p_budget_id) THEN RAISE EXCEPTION 'Budget requires at least one line'; END IF;
  UPDATE public.finance_budgets SET status = 'approved', approved_by = v_actor, approved_at = now(), updated_at = now() WHERE id = p_budget_id RETURNING * INTO v_budget;
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_org, v_actor, 'finance_budget_approved', 'finance_budgets', v_budget.id, jsonb_build_object('version', v_budget.version));
  RETURN v_budget;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."approve_finance_budget"(p_budget_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."approve_finance_budget"(p_budget_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."approve_finance_budget"(p_budget_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."approve_finance_budget"(p_budget_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."archive_provider_branch"(p_branch_organization_id uuid, p_expected_updated_at timestamp with time zone)
 RETURNS organizations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_branch public.organizations%rowtype;
  v_key text;
begin
  select * into v_branch from public.organizations where id = p_branch_organization_id for update;
  if not found or v_branch.organization_type <> 'branch' then raise exception 'Branch not found'; end if;
  if v_actor is null or not public.user_can_operate_organization(v_branch.parent_organization_id) or not public.is_admin_for_org(v_branch.parent_organization_id) then
    raise exception 'Active organisation administrator required';
  end if;
  if v_branch.status = 'archived' then return v_branch; end if;
  if p_expected_updated_at is not null and v_branch.updated_at <> p_expected_updated_at then raise exception 'Branch changed since it was opened'; end if;
  if exists (select 1 from public.user_profiles u where u.organization_id = v_branch.id and u.deactivated_at is null) then
    raise exception 'Move or deactivate the branch''s staff before archiving it';
  end if;
  if exists (select 1 from public.organizations c where c.parent_organization_id = v_branch.id and c.status <> 'archived') then
    raise exception 'Archive the branch''s own branches first';
  end if;

  for v_key in
    select om.module_key from public.organization_modules om
    where om.organization_id = v_branch.id and om.enabled
    order by (exists (select 1 from public.module_dependencies d where d.depends_on_module_key = om.module_key)), om.module_key
  loop
    update public.organization_modules set enabled = false where organization_id = v_branch.id and module_key = v_key;
  end loop;
  update public.staff_branch_authorisations set status = 'ended', ends_on = least(coalesce(ends_on, current_date), current_date)
   where branch_org_id = v_branch.id and status = 'active';

  update public.organizations set active = false, status = 'archived', updated_at = now()
   where id = v_branch.id returning * into v_branch;
  insert into public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (v_branch.parent_organization_id, v_actor, 'provider_branch_archived', 'organizations', v_branch.id, jsonb_build_object('name', v_branch.name));
  return v_branch;
end;
$function$;
COMMENT ON FUNCTION "public"."archive_provider_branch"(p_branch_organization_id uuid, p_expected_updated_at timestamp with time zone) IS 'Organisation settings: archive a branch that has no active staff or sub-branches; disables its modules and ends its branch authorisations. Requires the parent organisation''s administrator.';
REVOKE ALL ON FUNCTION "public"."archive_provider_branch"(p_branch_organization_id uuid, p_expected_updated_at timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."archive_provider_branch"(p_branch_organization_id uuid, p_expected_updated_at timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."archive_provider_branch"(p_branch_organization_id uuid, p_expected_updated_at timestamp with time zone) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."arrive_at_dispatch_place"(p_client_request_id uuid, p_dispatch_job_id uuid, p_place_role text DEFAULT 'work_place'::text, p_gps_lat double precision DEFAULT NULL::double precision, p_gps_lng double precision DEFAULT NULL::double precision, p_gps_accuracy double precision DEFAULT NULL::double precision, p_bwc_reference text DEFAULT NULL::text)
 RETURNS TABLE(stop_id uuid, created boolean, arrived_at timestamp with time zone, arrival_verification text, arrival_distance_m numeric, visit_number integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_org uuid;
  v_job public.dispatch_jobs%rowtype;
  v_site public.client_sites%rowtype;
  v_stop public.shift_stops%rowtype;
  v_receipt public.officer_command_requests%rowtype;
  v_site_id uuid;
  v_shift_id uuid;
  v_point geometry;
  v_distance numeric;
  v_verification text;
  v_onsite_m numeric;
  v_approach_m numeric;
  v_next_visit integer;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_client_request_id IS NULL THEN RAISE EXCEPTION 'client_request_id is required'; END IF;
  IF p_place_role NOT IN ('work_place', 'harmed_party_place') THEN RAISE EXCEPTION 'place_role must be work_place or harmed_party_place'; END IF;
  SELECT p.organization_id INTO v_org FROM public.user_profiles p
  WHERE p.id = v_user AND p.deactivated_at IS NULL AND p.role IN ('officer', 'admin_officer', 'admin', 'master', 'grand_master');
  IF v_org IS NULL THEN RAISE EXCEPTION 'Active officer profile required'; END IF;

  SELECT * INTO v_receipt FROM public.officer_command_requests r WHERE r.request_id = p_client_request_id::text;
  IF FOUND AND v_receipt.actor_user_id IS DISTINCT FROM v_user THEN RAISE EXCEPTION 'client_request_id belongs to another actor'; END IF;
  IF FOUND AND v_receipt.command_status = 'completed' THEN
    RETURN QUERY SELECT (v_receipt.response->>'stop_id')::uuid, false, (v_receipt.response->>'arrived_at')::timestamptz,
      v_receipt.response->>'arrival_verification', (v_receipt.response->>'arrival_distance_m')::numeric, (v_receipt.response->>'visit_number')::integer;
    RETURN;
  END IF;

  SELECT * INTO v_job FROM public.dispatch_jobs d WHERE d.id = p_dispatch_job_id AND d.organization_id = v_org;
  IF NOT FOUND THEN RAISE EXCEPTION 'Dispatch job not found in the officer organisation'; END IF;
  IF NOT (v_job.assigned_officer_id = v_user OR public.is_admin_for_org(v_org)
      OR EXISTS (SELECT 1 FROM public.dispatch_resources dr WHERE dr.id = v_job.dispatch_resource_id AND dr.assigned_officer_id = v_user)) THEN
    RAISE EXCEPTION 'Only the assigned officer may record attendance for this job';
  END IF;

  v_site_id := CASE p_place_role WHEN 'work_place' THEN v_job.client_site_id ELSE v_job.harmed_party_site_id END;
  IF p_place_role = 'harmed_party_place' AND v_site_id IS NULL AND v_job.harmed_party_address IS NULL THEN
    RAISE EXCEPTION 'This job has no harmed-party place recorded';
  END IF;

  v_shift_id := v_job.shift_id;
  IF v_shift_id IS NULL THEN
    SELECT s.id INTO v_shift_id FROM public.shifts s
    WHERE s.officer_user_id = v_user AND s.organization_id = v_org AND s.status = 'in_progress'
    ORDER BY s.actual_start DESC NULLS LAST LIMIT 1;
  END IF;
  IF v_shift_id IS NULL THEN RAISE EXCEPTION 'An in-progress shift is required to record attendance'; END IF;

  -- Geofence verification: loud, never blocking (GEOFENCE_PRINCIPLES P1/P2).
  IF p_gps_lat IS NULL OR p_gps_lng IS NULL THEN
    v_verification := 'no_gps';
  ELSE
    v_point := ST_SetSRID(ST_MakePoint(p_gps_lng, p_gps_lat), 4326);
    IF v_site_id IS NOT NULL THEN SELECT * INTO v_site FROM public.client_sites cs WHERE cs.id = v_site_id; END IF;
    IF v_site.id IS NULL OR (v_site.boundary IS NULL AND v_site.center_point IS NULL) THEN
      v_verification := 'no_geofence';
    ELSE
      v_distance := round((CASE WHEN v_site.boundary IS NOT NULL
        THEN ST_Distance(v_site.boundary::geography, v_point::geography)
        ELSE ST_Distance(v_site.center_point::geography, v_point::geography) END)::numeric, 1);
      v_onsite_m := COALESCE(v_site.onsite_radius_meters, 10);
      SELECT c.config_value::numeric INTO v_approach_m FROM public.org_geofence_config c
      WHERE c.organization_id = v_org AND c.config_key = 'approach_radius_m' AND c.zone_type IS NULL LIMIT 1;
      v_approach_m := COALESCE(v_approach_m, v_site.prompt_radius_meters, 50);
      IF v_site.boundary_verification IS DISTINCT FROM 'verified' THEN v_verification := 'unverified_boundary';
      ELSIF v_distance <= v_onsite_m THEN v_verification := 'verified_on_site';
      ELSIF v_distance <= v_approach_m THEN v_verification := 'near_site';
      ELSE v_verification := 'off_site';
      END IF;
    END IF;
  END IF;

  SELECT * INTO v_stop FROM public.shift_stops st
  WHERE st.dispatch_job_id = v_job.id AND st.place_role = p_place_role AND st.status NOT IN ('completed', 'cancelled', 'skipped')
  ORDER BY st.visit_number DESC LIMIT 1;
  IF NOT FOUND THEN
    SELECT COALESCE(max(st.visit_number), 0) + 1 INTO v_next_visit FROM public.shift_stops st WHERE st.dispatch_job_id = v_job.id AND st.place_role = p_place_role;
    INSERT INTO public.shift_stops (organization_id, shift_id, site_id, module_key, stop_order, visit_number, is_adhoc, dispatch_job_id,
      sla_arrive_by, required_dwell_minutes, status, place_role)
    VALUES (v_org, v_shift_id, v_site_id, COALESCE(v_job.module_key, 'noise_control'),
      (SELECT COALESCE(max(so.stop_order), 0) + 1 FROM public.shift_stops so WHERE so.shift_id = v_shift_id),
      v_next_visit, true, v_job.id, COALESCE(v_job.sla_respond_by, now()), COALESCE(v_job.expected_dwell_minutes, 15), 'on_scene', p_place_role)
    RETURNING * INTO v_stop;
  END IF;

  UPDATE public.shift_stops
  SET actual_arrived_at = COALESCE(shift_stops.actual_arrived_at, now()),
      arrived_gps_lat = COALESCE(p_gps_lat, shift_stops.arrived_gps_lat),
      arrived_gps_lng = COALESCE(p_gps_lng, shift_stops.arrived_gps_lng),
      arrived_gps_accuracy = COALESCE(p_gps_accuracy, shift_stops.arrived_gps_accuracy),
      arrival_verification = v_verification,
      arrival_distance_m = v_distance,
      bwc_reference = COALESCE(nullif(trim(coalesce(p_bwc_reference, '')), ''), shift_stops.bwc_reference),
      status = 'on_scene',
      sla_status = CASE WHEN COALESCE(shift_stops.actual_arrived_at, now()) > shift_stops.sla_arrive_by THEN 'breached' ELSE shift_stops.sla_status END,
      updated_at = now()
  WHERE id = v_stop.id
  RETURNING * INTO v_stop;

  IF p_place_role = 'work_place' THEN
    UPDATE public.dispatch_jobs
    SET on_scene_at = COALESCE(dispatch_jobs.on_scene_at, v_stop.actual_arrived_at),
        status = CASE WHEN dispatch_jobs.status IN ('dispatched', 'acknowledged', 'en_route') THEN 'on_scene' ELSE dispatch_jobs.status END,
        sla_breached = CASE WHEN dispatch_jobs.sla_respond_by IS NOT NULL AND v_stop.actual_arrived_at > dispatch_jobs.sla_respond_by THEN true ELSE dispatch_jobs.sla_breached END
    WHERE id = v_job.id;
  END IF;

  INSERT INTO public.officer_command_requests (request_id, organization_id, actor_user_id, shift_id, site_id, command_type, command_status, response)
  VALUES (p_client_request_id::text, v_org, v_user, v_shift_id, v_site_id, 'arrive_at_dispatch_place', 'completed',
    jsonb_build_object('stop_id', v_stop.id, 'arrived_at', v_stop.actual_arrived_at, 'arrival_verification', v_verification,
      'arrival_distance_m', v_distance, 'visit_number', v_stop.visit_number, 'place_role', p_place_role))
  ON CONFLICT (request_id) DO UPDATE SET command_status = 'completed', response = EXCLUDED.response;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_org, v_user, 'dispatch_place_arrival_recorded', 'shift_stops', v_stop.id,
    jsonb_build_object('dispatch_job_id', v_job.id, 'place_role', p_place_role, 'arrival_verification', v_verification,
      'arrival_distance_m', v_distance, 'visit_number', v_stop.visit_number, 'bwc_reference_recorded', v_stop.bwc_reference IS NOT NULL));

  RETURN QUERY SELECT v_stop.id, true, v_stop.actual_arrived_at, v_verification, v_distance, v_stop.visit_number;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."arrive_at_dispatch_place"(p_client_request_id uuid, p_dispatch_job_id uuid, p_place_role text, p_gps_lat double precision, p_gps_lng double precision, p_gps_accuracy double precision, p_bwc_reference text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."arrive_at_dispatch_place"(p_client_request_id uuid, p_dispatch_job_id uuid, p_place_role text, p_gps_lat double precision, p_gps_lng double precision, p_gps_accuracy double precision, p_bwc_reference text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."arrive_at_dispatch_place"(p_client_request_id uuid, p_dispatch_job_id uuid, p_place_role text, p_gps_lat double precision, p_gps_lng double precision, p_gps_accuracy double precision, p_bwc_reference text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."arrive_at_dispatch_place"(p_client_request_id uuid, p_dispatch_job_id uuid, p_place_role text, p_gps_lat double precision, p_gps_lng double precision, p_gps_accuracy double precision, p_bwc_reference text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."assert_new_person_not_duplicate"(p_organization_id uuid, p_fields jsonb)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_names text;
  v_contacts boolean;
BEGIN
  IF coalesce((p_fields->>'confirm_new_person')::boolean, false) THEN RETURN; END IF;
  v_contacts := public.can_access_person_contacts(p_organization_id);
  SELECT string_agg(m.display_name, ', ') INTO v_names
  FROM public._match_person_records(p_organization_id, p_fields->>'display_name', nullif(p_fields->>'date_of_birth', '')::date,
    p_fields->>'licence_number', p_fields->>'phone', p_fields->>'email', NULL, 5, v_contacts) m
  WHERE m.score >= 0.85;
  IF v_names IS NULL THEN RETURN; END IF;
  IF public.can_search_people(p_organization_id) OR public.can_access_vehicle_owner_identity(p_organization_id) THEN
    RAISE EXCEPTION 'POSSIBLE_DUPLICATE: % may already be recorded. Choose the existing person, or confirm this is a different person.', v_names;
  END IF;
  RAISE EXCEPTION 'POSSIBLE_DUPLICATE: Someone with these details may already be recorded. Confirm this is a different person, or ask an administrator to link the existing record.';
END;
$function$;
REVOKE ALL ON FUNCTION "public"."assert_new_person_not_duplicate"(p_organization_id uuid, p_fields jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."assert_new_person_not_duplicate"(p_organization_id uuid, p_fields jsonb) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."assess_bob_nz_finance_readiness"()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_tax_periods integer;
  v_tax_transactions integer;
  v_timesheets integer;
  v_labour_postings integer;
  v_finance_costs integer;
  v_results jsonb;
BEGIN
  SELECT organization_id INTO v_org FROM public.user_profiles WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_org IS NULL OR NOT public.is_admin_for_org(v_org) THEN RAISE EXCEPTION 'Active finance administrator required'; END IF;
  SELECT count(*)::integer INTO v_tax_periods FROM public.finance_tax_periods WHERE organization_id = v_org;
  SELECT count(*)::integer INTO v_tax_transactions FROM public.finance_tax_transactions WHERE organization_id = v_org;
  SELECT count(*)::integer INTO v_timesheets FROM public.timesheets WHERE organization_id = v_org;
  SELECT count(*)::integer INTO v_labour_postings FROM public.finance_labour_cost_postings WHERE organization_id = v_org;
  SELECT count(*)::integer INTO v_finance_costs FROM public.finance_service_costs WHERE organization_id = v_org;

  INSERT INTO public.bob_nz_finance_readiness_checks(organization_id, source_key, check_code, check_title, status, score, evidence, bob_can_do, human_or_provider_needed, measured_at)
  VALUES
    (v_org, 'ird-gst-overview', 'gst', 'GST calculation and period control', CASE WHEN v_tax_periods > 0 AND v_tax_transactions > 0 THEN 'partial' ELSE 'gap' END, CASE WHEN v_tax_periods > 0 AND v_tax_transactions > 0 THEN 60 ELSE 30 END, 'GST periods and tax transactions exist: ' || v_tax_periods || ' periods, ' || v_tax_transactions || ' transactions. Filing submission and payment integration are not present.', 'Prepare GST figures, explain output/input tax, identify missing transactions, and create a filing checklist.', 'A person or approved tax/accounting provider must confirm the return and submit/pay it to IRD.', now()),
    (v_org, 'ird-gst-records', 'gst_record_keeping', 'GST evidence and record keeping', CASE WHEN v_finance_costs > 0 THEN 'partial' ELSE 'gap' END, CASE WHEN v_finance_costs > 0 THEN 65 ELSE 25 END, 'Finance service costs provide source references and audit entries; source documents and full tax-invoice evidence are not automatically complete.', 'Collect provenance, flag missing receipts/invoices, and explain which records support each figure.', 'The owner and accountant must retain complete tax invoices and decide whether evidence supports a GST position.', now()),
    (v_org, 'ird-employers', 'employers', 'Employer cost and staff finance controls', CASE WHEN v_timesheets > 0 AND v_labour_postings > 0 THEN 'partial' ELSE 'gap' END, CASE WHEN v_timesheets > 0 AND v_labour_postings > 0 THEN 60 ELSE 30 END, 'Timesheets and actual labour-cost postings exist: ' || v_timesheets || ' timesheets, ' || v_labour_postings || ' labour postings. Employment compliance and PAYE calculations are not statutory payroll.', 'Check approved hours, rates, on-cost assumptions, missing pay rules, and management labour cost.', 'A payroll provider or payroll specialist must calculate and file PAYE and employment obligations.', now()),
    (v_org, 'ird-provisional-tax', 'provisional_tax', 'Provisional tax planning', 'gap', 15, 'No dedicated provisional-tax liability, estimate, payment schedule, or IRD submission workflow exists.', 'Explain that provisional tax may need planning and prepare questions for the accountant using management results.', 'An accountant or tax agent must calculate the liability, method, dates, and payment instruction.', now()),
    (v_org, 'ird-payroll', 'payday_filing', 'Payday filing integration', 'gap', 10, 'Timesheets and cost postings exist, but no IRD payday-file generation, submission, response, or correction workflow exists.', 'Prepare a clean hours/rates export and identify unresolved payroll inputs.', 'An approved payroll system/provider must generate and submit payday files to IRD.', now()),
    (v_org, 'xrb-nz-accounting-standards', 'accounting_standards', 'Accounting standards and statutory reporting', 'partial', 45, 'Management P&L, budgets, costs, invoices, tax records, and audit trails exist; general-ledger journals, statutory statements, and reporting-entity classification are not implemented.', 'Keep management measures separate, show assumptions, preserve evidence, and prepare an accountant handoff.', 'A qualified accountant must determine applicable standards, classifications, adjustments, and statutory statements.', now())
  ON CONFLICT (organization_id, source_key) DO UPDATE SET check_code = EXCLUDED.check_code, check_title = EXCLUDED.check_title, status = EXCLUDED.status, score = EXCLUDED.score, evidence = EXCLUDED.evidence, bob_can_do = EXCLUDED.bob_can_do, human_or_provider_needed = EXCLUDED.human_or_provider_needed, measured_at = EXCLUDED.measured_at;

  SELECT jsonb_build_object('measured_at', now(), 'overall_score', round(avg(score)), 'checks', jsonb_agg(jsonb_build_object('source_key', source_key, 'title', check_title, 'status', status, 'score', score, 'evidence', evidence, 'bob_can_do', bob_can_do, 'human_or_provider_needed', human_or_provider_needed) ORDER BY source_key)) INTO v_results
  FROM public.bob_nz_finance_readiness_checks WHERE organization_id = v_org;
  RETURN v_results;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."assess_bob_nz_finance_readiness"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."assess_bob_nz_finance_readiness"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."assess_bob_nz_finance_readiness"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."assess_bob_nz_finance_readiness"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."assign_dispatch_job_to_officer"(p_job_id uuid, p_officer_user_id uuid)
 RETURNS dispatch_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_actor uuid := auth.uid(); v_job public.dispatch_jobs%rowtype;
BEGIN
  SELECT * INTO v_job FROM public.dispatch_jobs WHERE id=p_job_id FOR UPDATE;
  IF NOT FOUND OR v_actor IS NULL OR NOT public.is_admin_for_org(v_job.organization_id) THEN RAISE EXCEPTION 'Dispatch job access denied'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.user_profiles u
    JOIN public.service_agreements sa ON sa.id=v_job.service_agreement_id
    JOIN public.organizations officer_org ON officer_org.id=u.organization_id
    WHERE u.id=p_officer_user_id AND u.deactivated_at IS NULL AND u.role IN ('officer','admin_officer')
      AND (officer_org.id=sa.provider_organization_id OR sa.provider_organization_id=ANY(public.get_descendant_organizations(officer_org.id)))
  ) THEN RAISE EXCEPTION 'Target officer is not authorized for this service agreement'; END IF;
  UPDATE public.dispatch_jobs SET assigned_officer_id=p_officer_user_id WHERE public.dispatch_jobs.id=p_job_id RETURNING * INTO v_job;
  INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
    VALUES(v_job.organization_id,v_actor,'dispatch_job_assigned_to_officer','dispatch_jobs',v_job.id,jsonb_build_object('officer_user_id',p_officer_user_id,'roster_independent',true));
  RETURN v_job;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."assign_dispatch_job_to_officer"(p_job_id uuid, p_officer_user_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."assign_dispatch_job_to_officer"(p_job_id uuid, p_officer_user_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."assign_dispatch_job_to_officer"(p_job_id uuid, p_officer_user_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."assign_dispatch_job_to_officer"(p_job_id uuid, p_officer_user_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."assign_face_observation_person"(p_observation_id uuid, p_person_record_id uuid, p_display_name text DEFAULT NULL::text)
 RETURNS face_observations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  observation public.face_observations;
  source_metadata jsonb;
  v_face_vec vector(128);
BEGIN
  IF auth.role() <> 'service_role' AND session_user <> 'postgres' THEN
    IF v_actor IS NULL OR NOT EXISTS (
      SELECT 1 FROM public.face_observations
      WHERE id = p_observation_id AND public.org_access_allowed(organization_id)
    ) THEN RAISE EXCEPTION 'Observation access denied'; END IF;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.face_observations observation
    JOIN public.person_records person ON person.organization_id = observation.organization_id
    WHERE observation.id = p_observation_id AND person.id = p_person_record_id
  ) THEN RAISE EXCEPTION 'Person record does not belong to the observation organization'; END IF;

  SELECT metadata INTO source_metadata FROM public.face_observations WHERE id = p_observation_id;
  IF nullif(trim(p_display_name), '') IS NOT NULL THEN
    UPDATE public.person_records SET display_name = trim(p_display_name) WHERE id = p_person_record_id;
  END IF;
  UPDATE public.person_records
  SET metadata = jsonb_set(metadata, '{face_reference}', jsonb_strip_nulls(jsonb_build_object(
    'thumbnail', source_metadata->>'original_thumbnail',
    'evidence_item_id', source_metadata->>'evidence_item_id',
    'event_id', source_metadata->>'source_event_id'
  )), true)
  WHERE id = p_person_record_id;

  v_face_vec := public.cctv_jsonb_to_vector(source_metadata->'embedding', 128);
  IF v_face_vec IS NOT NULL THEN
    INSERT INTO public.person_face_templates (organization_id, person_record_id, face_vec, confidence, model,
      source_kind, source_ref, retention_reason, approved_by)
    SELECT face.organization_id, p_person_record_id, v_face_vec, face.confidence, 'legacy_face_observation',
      'cctv_face_observation', face.id::text, 'Human-linked CCTV face observation', v_actor
    FROM public.face_observations face WHERE face.id = p_observation_id
    ON CONFLICT (organization_id, person_record_id, source_kind, source_ref) DO NOTHING;
  END IF;

  UPDATE public.face_observations SET person_record_id = p_person_record_id, review_state = 'reviewed'
  WHERE id = p_observation_id RETURNING * INTO observation;
  observation.metadata := observation.metadata - ARRAY['embedding','face_embedding','candidate_embedding','appearance_embedding']::text[];
  RETURN observation;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."assign_face_observation_person"(p_observation_id uuid, p_person_record_id uuid, p_display_name text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."assign_face_observation_person"(p_observation_id uuid, p_person_record_id uuid, p_display_name text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."assign_face_observation_person"(p_observation_id uuid, p_person_record_id uuid, p_display_name text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."assign_face_observation_person"(p_observation_id uuid, p_person_record_id uuid, p_display_name text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."assign_noise_job_number"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF nullif(trim(coalesce(NEW.job_number, '')), '') IS NULL THEN
    NEW.job_number := public.generate_noise_job_number();
  END IF;
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."assign_noise_job_number"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."assign_noise_job_number"() TO "postgres";
