CREATE OR REPLACE FUNCTION "public"."assign_roster_skill_to_staff"(p_staff_id uuid, p_skill_id uuid, p_proficiency_level text, p_certified boolean DEFAULT false, p_certification_expiry date DEFAULT NULL::date, p_notes text DEFAULT NULL::text)
 RETURNS staff_skills
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_skill public.roster_skill_catalog%rowtype;
  v_row public.staff_skills%rowtype;
  v_created boolean := false;
BEGIN
  SELECT organization_id
  INTO v_org
  FROM public.user_profiles
  WHERE id = v_actor
    AND deactivated_at IS NULL;

  IF v_org IS NULL OR NOT public.is_admin_for_org(v_org) THEN
    RAISE EXCEPTION 'Roster administrator required';
  END IF;
  IF p_proficiency_level NOT IN ('basic', 'competent', 'proficient', 'expert') THEN
    RAISE EXCEPTION 'Unsupported proficiency level';
  END IF;

  SELECT *
  INTO v_skill
  FROM public.roster_skill_catalog
  WHERE id = p_skill_id
    AND organization_id = v_org
    AND active;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Active catalog skill required';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.staff_profiles
    WHERE id = p_staff_id
      AND organization_id = v_org
  ) THEN
    RAISE EXCEPTION 'Staff profile not found';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(p_staff_id::text || ':' || p_skill_id::text, 0));

  SELECT *
  INTO v_row
  FROM public.staff_skills skill
  WHERE skill.staff_id = p_staff_id
    AND skill.skill_id = p_skill_id
  ORDER BY skill.created_at DESC
  LIMIT 1
  FOR UPDATE;

  IF FOUND THEN
    UPDATE public.staff_skills
    SET skill_name = v_skill.skill_name,
        skill_category = v_skill.skill_category,
        proficiency_level = p_proficiency_level,
        certified = coalesce(p_certified, false),
        certification_expiry = p_certification_expiry,
        notes = nullif(trim(coalesce(p_notes, '')), ''),
        updated_at = now()
    WHERE id = v_row.id
    RETURNING * INTO v_row;
  ELSE
    INSERT INTO public.staff_skills (
      staff_id, organization_id, skill_id, skill_name, skill_category,
      proficiency_level, certified, certification_expiry, notes
    ) VALUES (
      p_staff_id, v_org, v_skill.id, v_skill.skill_name, v_skill.skill_category,
      p_proficiency_level, coalesce(p_certified, false), p_certification_expiry,
      nullif(trim(coalesce(p_notes, '')), '')
    )
    RETURNING * INTO v_row;
    v_created := true;
  END IF;

  INSERT INTO public.audit_log (
    organization_id, actor_user_id, action, target_table, target_id, metadata
  ) VALUES (
    v_org,
    v_actor,
    CASE WHEN v_created THEN 'roster_skill_assigned_to_staff' ELSE 'roster_staff_skill_updated' END,
    'staff_skills',
    v_row.id,
    jsonb_build_object(
      'staff_id', p_staff_id,
      'skill_id', p_skill_id,
      'proficiency_level', p_proficiency_level,
      'certified', coalesce(p_certified, false),
      'certification_expiry', p_certification_expiry
    )
  );

  RETURN v_row;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."assign_roster_skill_to_staff"(p_staff_id uuid, p_skill_id uuid, p_proficiency_level text, p_certified boolean, p_certification_expiry date, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."assign_roster_skill_to_staff"(p_staff_id uuid, p_skill_id uuid, p_proficiency_level text, p_certified boolean, p_certification_expiry date, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."assign_roster_skill_to_staff"(p_staff_id uuid, p_skill_id uuid, p_proficiency_level text, p_certified boolean, p_certification_expiry date, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."assign_roster_skill_to_staff"(p_staff_id uuid, p_skill_id uuid, p_proficiency_level text, p_certified boolean, p_certification_expiry date, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."assign_shift_asset"(p_client_request_id uuid, p_shift_id uuid, p_asset_id uuid)
 RETURNS shift_assets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_shift public.shifts%rowtype;
  v_asset public.assets%rowtype;
  v_link public.shift_assets%rowtype;
begin
  if p_client_request_id is null then
    raise exception 'client_request_id is required';
  end if;

  select s.* into v_shift from public.shifts s where s.id = p_shift_id;
  if not found then
    raise exception 'Shift not found';
  end if;

  if not public.is_admin_for_org(v_shift.organization_id) and v_shift.officer_user_id <> v_actor then
    raise exception 'Not authorised to assign assets to this shift';
  end if;

  select l.* into v_link from public.shift_assets l
  where l.organization_id = v_shift.organization_id and l.client_request_id = p_client_request_id;
  if found then
    return v_link;
  end if;

  select a.* into v_asset from public.assets a where a.id = p_asset_id for update;
  if not found then
    raise exception 'Asset not found';
  end if;

  if v_asset.organization_id <> v_shift.organization_id then
    raise exception 'Asset belongs to another organization';
  end if;

  if v_asset.status <> 'available' then
    raise exception 'Asset is not available (current status %)', v_asset.status;
  end if;

  insert into public.shift_assets(organization_id, shift_id, asset_id, assigned_by, client_request_id)
  values (v_shift.organization_id, v_shift.id, v_asset.id, v_actor, p_client_request_id)
  returning * into v_link;

  update public.assets
  set status = 'in_use', assigned_to = v_shift.officer_user_id
  where id = v_asset.id;

  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (
    v_shift.organization_id, v_actor, 'shift_asset_assigned', 'shift_assets', v_link.id,
    jsonb_build_object(
      'shift_id', v_shift.id,
      'asset_id', v_asset.id,
      'asset_type', v_asset.asset_type,
      'registration', v_asset.registration,
      'client_request_id', p_client_request_id
    )
  );

  return v_link;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."assign_shift_asset"(p_client_request_id uuid, p_shift_id uuid, p_asset_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."assign_shift_asset"(p_client_request_id uuid, p_shift_id uuid, p_asset_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."assign_shift_asset"(p_client_request_id uuid, p_shift_id uuid, p_asset_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."assign_shift_asset"(p_client_request_id uuid, p_shift_id uuid, p_asset_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."attach_crm_site_to_location"(p_site_id uuid, p_location_id uuid)
 RETURNS client_sites
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_provider uuid; v_site public.client_sites%rowtype;
BEGIN
 SELECT up.organization_id INTO v_provider FROM public.user_profiles AS up WHERE up.id=v_actor AND up.deactivated_at IS NULL;
 SELECT site.* INTO v_site FROM public.client_sites AS site WHERE site.id=p_site_id FOR UPDATE;
 IF v_provider IS NULL OR NOT public.is_admin_for_org(v_provider) OR NOT public.crm_actor_can_manage_account(v_site.client_organization_id) THEN RAISE EXCEPTION 'Active CRM administrator required'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.locations AS house WHERE house.id=p_location_id AND house.organization_id=v_site.client_organization_id) THEN RAISE EXCEPTION 'Location house does not belong to the Site organization'; END IF;
 UPDATE public.client_sites SET location_id=p_location_id WHERE id=v_site.id RETURNING * INTO v_site;
 INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) VALUES(v_provider,v_actor,'crm_site_attached_to_location','client_sites',v_site.id,jsonb_build_object('location_id',p_location_id));
 RETURN v_site;
END; $function$;
REVOKE ALL ON FUNCTION "public"."attach_crm_site_to_location"(p_site_id uuid, p_location_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."attach_crm_site_to_location"(p_site_id uuid, p_location_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."attach_crm_site_to_location"(p_site_id uuid, p_location_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."attach_crm_site_to_location"(p_site_id uuid, p_location_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."attach_external_photo_to_record"(p_record_kind text, p_record_id uuid, p_storage_path text, p_sha256 text, p_description text DEFAULT NULL::text, p_source_note text DEFAULT NULL::text, p_original_name text DEFAULT NULL::text, p_captured_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_org uuid;
  v_event_id uuid;
  v_evidence_id uuid;
  v_support_id uuid;
  v_path text := nullif(trim(coalesce(p_storage_path, '')), '');
  v_evidence_path text;
  v_hash text := lower(nullif(trim(coalesce(p_sha256, '')), ''));
  v_captured_at timestamptz := coalesce(p_captured_at, clock_timestamp());
  v_reused boolean := false;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  IF p_record_kind NOT IN ('location_event', 'observation') THEN
    RAISE EXCEPTION 'Unsupported record kind %', p_record_kind;
  END IF;
  IF v_path IS NULL THEN
    RAISE EXCEPTION 'storage_path is required';
  END IF;
  IF v_hash IS NULL OR v_hash !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'A SHA-256 hash of the file is required';
  END IF;

  IF p_record_kind = 'location_event' THEN
    SELECT event.organization_id, event.id
      INTO v_org, v_event_id
      FROM public.location_events AS event
     WHERE event.id = p_record_id;
  ELSE
    SELECT observation.organization_id
      INTO v_org
      FROM public.observations AS observation
     WHERE observation.id = p_record_id;
  END IF;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'Record not found';
  END IF;
  IF NOT public.org_access_allowed(v_org) THEN
    RAISE EXCEPTION 'Not permitted to add evidence to this record';
  END IF;
  IF position('org/' || v_org::text || '/record-evidence/' in v_path) <> 1 THEN
    RAISE EXCEPTION 'Evidence must be stored under org/%/record-evidence/', v_org;
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(
    v_org::text || ':photo:' || v_hash,
    0
  ));

  SELECT evidence.id, evidence.storage_path
    INTO v_evidence_id, v_evidence_path
    FROM public.evidence_items AS evidence
   WHERE evidence.organization_id = v_org
     AND evidence.evidence_kind = 'photo'
     AND lower(evidence.sha256_hash) = v_hash
   ORDER BY (
     evidence.metadata->>'record_kind' = p_record_kind
     AND evidence.metadata->>'record_id' = p_record_id::text
   ) DESC,
     evidence.captured_at
   LIMIT 1
   FOR UPDATE;

  IF v_evidence_id IS NULL THEN
    v_evidence_path := v_path;
    INSERT INTO public.evidence_items (
      organization_id,
      module_key,
      evidence_kind,
      storage_path,
      captured_by_user_id,
      captured_at,
      sha256_hash,
      is_court_ready,
      retention_class,
      location_event_id,
      metadata
    ) VALUES (
      v_org,
      'record_review',
      'photo',
      v_evidence_path,
      v_user,
      v_captured_at,
      v_hash,
      false,
      'policy_defined',
      v_event_id,
      jsonb_strip_nulls(jsonb_build_object(
        'provenance', 'external',
        'record_kind', p_record_kind,
        'record_id', p_record_id,
        'observation_id', CASE
          WHEN p_record_kind = 'observation' THEN p_record_id
        END,
        'linked_observation_ids', CASE
          WHEN p_record_kind = 'observation'
          THEN jsonb_build_array(p_record_id::text)
        END,
        'description', nullif(trim(coalesce(p_description, '')), ''),
        'source_note', nullif(trim(coalesce(p_source_note, '')), ''),
        'original_name', nullif(trim(coalesce(p_original_name, '')), ''),
        'source_captured_at', p_captured_at
      ))
    )
    RETURNING id INTO v_evidence_id;

    INSERT INTO public.audit_log (
      organization_id, actor_user_id, action, target_table, target_id, metadata
    ) VALUES (
      v_org,
      v_user,
      'external_photo_attached',
      'evidence_items',
      v_evidence_id,
      jsonb_strip_nulls(jsonb_build_object(
        'record_kind', p_record_kind,
        'record_id', p_record_id,
        'sha256_hash', v_hash,
        'storage_path', v_evidence_path,
        'source_captured_at', p_captured_at
      ))
    );
  ELSE
    v_reused := true;
    IF p_record_kind = 'observation' THEN
      UPDATE public.evidence_items
         SET metadata = jsonb_set(
           coalesce(metadata, '{}'::jsonb),
           '{linked_observation_ids}',
           CASE
             WHEN coalesce(metadata->'linked_observation_ids', '[]'::jsonb)
               @> jsonb_build_array(p_record_id::text)
             THEN coalesce(metadata->'linked_observation_ids', '[]'::jsonb)
             ELSE coalesce(metadata->'linked_observation_ids', '[]'::jsonb)
               || jsonb_build_array(p_record_id::text)
           END,
           true
         )
       WHERE id = v_evidence_id;
    END IF;
  END IF;

  IF p_record_kind = 'observation' THEN
    INSERT INTO public.observation_supporting_evidence (
      organization_id,
      observation_id,
      evidence_kind,
      storage_bucket,
      storage_path,
      notes,
      captured_at,
      created_by
    ) VALUES (
      v_org,
      p_record_id,
      'external_photo',
      'bob-uploads',
      v_evidence_path,
      nullif(trim(coalesce(p_description, '')), ''),
      v_captured_at,
      v_user
    )
    ON CONFLICT (organization_id, observation_id, storage_path)
      WHERE evidence_kind = 'external_photo'
        AND observation_id IS NOT NULL
        AND storage_path IS NOT NULL
    DO NOTHING
    RETURNING id INTO v_support_id;

    IF v_reused AND v_support_id IS NOT NULL THEN
      INSERT INTO public.audit_log (
        organization_id, actor_user_id, action, target_table, target_id, metadata
      ) VALUES (
        v_org,
        v_user,
        'external_photo_reused_for_observation',
        'evidence_items',
        v_evidence_id,
        jsonb_build_object(
          'observation_id', p_record_id,
          'sha256_hash', v_hash,
          'storage_path', v_evidence_path
        )
      );
    END IF;
  END IF;

  RETURN v_evidence_id;
END;
$function$;
COMMENT ON FUNCTION "public"."attach_external_photo_to_record"(p_record_kind text, p_record_id uuid, p_storage_path text, p_sha256 text, p_description text, p_source_note text, p_original_name text, p_captured_at timestamp with time zone) IS 'Registers an external photo or reuses the organization''s existing hash-addressed evidence item, then creates an idempotent record link. Source capture time, provenance, non-court-ready state, and an audit receipt are preserved.';
REVOKE ALL ON FUNCTION "public"."attach_external_photo_to_record"(p_record_kind text, p_record_id uuid, p_storage_path text, p_sha256 text, p_description text, p_source_note text, p_original_name text, p_captured_at timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."attach_external_photo_to_record"(p_record_kind text, p_record_id uuid, p_storage_path text, p_sha256 text, p_description text, p_source_note text, p_original_name text, p_captured_at timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."attach_external_photo_to_record"(p_record_kind text, p_record_id uuid, p_storage_path text, p_sha256 text, p_description text, p_source_note text, p_original_name text, p_captured_at timestamp with time zone) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."attach_external_photo_to_record"(p_record_kind text, p_record_id uuid, p_storage_path text, p_sha256 text, p_description text, p_source_note text, p_original_name text, p_captured_at timestamp with time zone) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."attach_incident_identity_proposal"(p_actor_user_id uuid, p_incident_id uuid, p_person_record_id uuid, p_identity_document_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_document public.person_identity_documents%rowtype;BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' AND session_user NOT IN ('postgres','supabase_admin') THEN RAISE EXCEPTION 'Service identity required'; END IF;
  IF NOT public.can_record_incident_person(p_incident_id,p_actor_user_id) THEN RAISE EXCEPTION 'Assigned incident access required'; END IF;
  SELECT * INTO v_document FROM public.person_identity_documents WHERE id=p_identity_document_id AND person_record_id=p_person_record_id;
  IF v_document.id IS NULL THEN RAISE EXCEPTION 'Identity proposal does not belong to this incident person'; END IF;
  UPDATE public.incident_person_links SET identity_document_id=v_document.id,updated_at=clock_timestamp()
  WHERE incident_id=p_incident_id AND person_record_id=p_person_record_id;
  INSERT INTO public.incident_attachments(organization_id,incident_id,evidence_item_id,attachment_kind)
  SELECT v_document.organization_id,p_incident_id,v_document.evidence_item_id,'document'
  WHERE NOT EXISTS(SELECT 1 FROM public.incident_attachments WHERE incident_id=p_incident_id AND evidence_item_id=v_document.evidence_item_id);
END;
$function$;
REVOKE ALL ON FUNCTION "public"."attach_incident_identity_proposal"(p_actor_user_id uuid, p_incident_id uuid, p_person_record_id uuid, p_identity_document_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."attach_incident_identity_proposal"(p_actor_user_id uuid, p_incident_id uuid, p_person_record_id uuid, p_identity_document_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."attach_incident_identity_proposal"(p_actor_user_id uuid, p_incident_id uuid, p_person_record_id uuid, p_identity_document_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."attach_officer_record_photo"(p_record_kind text, p_record_id uuid, p_sha256 text, p_original_name text, p_selected_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_org uuid;
  v_shift uuid;
  v_path text;
  v_object storage.objects%rowtype;
  v_photo public.officer_record_photos%rowtype;
  v_evidence uuid;
BEGIN
  SELECT c.organization_id,c.shift_id INTO v_org,v_shift
    FROM public.officer_photo_target_context(p_record_kind,p_record_id) c;
  -- Keep the authorization context from being reassigned during registration.
  PERFORM 1 FROM public.user_profiles WHERE id = v_user FOR SHARE;
  IF p_record_kind = 'field_report' THEN
    PERFORM 1 FROM public.officer_field_reports WHERE id = p_record_id FOR SHARE;
  ELSE
    PERFORM 1 FROM public.incidents WHERE id = p_record_id FOR SHARE;
    PERFORM 1 FROM public.dispatch_jobs WHERE id = (
      SELECT dispatch_job_id FROM public.incidents WHERE id = p_record_id
    ) FOR SHARE;
  END IF;
  SELECT c.organization_id,c.shift_id INTO v_org,v_shift
    FROM public.officer_photo_target_context(p_record_kind,p_record_id) c;
  IF v_shift IS NOT NULL THEN
    PERFORM 1 FROM public.shifts WHERE id = v_shift FOR SHARE;
    PERFORM public.officer_photo_target_context(p_record_kind,p_record_id);
  END IF;
  IF p_sha256 IS NULL OR p_sha256 !~ '^[0-9a-f]{64}$'
    OR p_selected_at IS NULL OR p_selected_at > clock_timestamp() + interval '5 minutes'
    OR nullif(btrim(p_original_name),'') IS NULL OR length(p_original_name) > 255 THEN
    RAISE EXCEPTION 'Photo provenance is invalid';
  END IF;
  v_path := 'org/' || v_org || '/officer-photos/' || p_record_kind || '/' || p_record_id || '/' || p_sha256;
  PERFORM pg_advisory_xact_lock(hashtextextended(v_path,0));
  SELECT * INTO v_photo FROM public.officer_record_photos WHERE storage_path = v_path;
  IF v_photo.id IS NOT NULL AND v_photo.shift_id IS DISTINCT FROM v_shift THEN
    RAISE EXCEPTION 'This original photo belongs to an earlier shift context; contact operations rather than replacing it';
  END IF;
  IF v_photo.id IS NULL THEN
    SELECT * INTO v_object FROM storage.objects
      WHERE bucket_id = 'officer-record-photos' AND name = v_path;
    IF v_object.id IS NULL OR coalesce(v_object.owner_id,'') <> v_user::text
      OR coalesce(v_object.metadata->>'mimetype','') NOT IN ('image/jpeg','image/png','image/webp','image/heic','image/heif')
      OR coalesce((v_object.metadata->>'size')::bigint,0) NOT BETWEEN 1 AND 15728640 THEN
      RAISE EXCEPTION 'The original photo upload was not confirmed';
    END IF;
    INSERT INTO public.evidence_items(
      organization_id,module_key,evidence_kind,storage_path,captured_by_user_id,
      captured_at,sha256_hash,is_court_ready,retention_class,metadata
    ) VALUES (
      v_org,'record_review','photo',v_path,v_user,p_selected_at,p_sha256,false,'policy_defined',
      jsonb_build_object('provenance','external','source','officer_photo_attachment',
        'storage_bucket','officer-record-photos','record_kind',p_record_kind,'record_id',p_record_id,
        'shift_id',v_shift,'original_name',p_original_name,'raw_sha256',p_sha256,
        'selected_at',p_selected_at,'capture_time_verified',false,
        'privacy_review_status','pending','client_publish_allowed',false)
    ) RETURNING id INTO v_evidence;
    INSERT INTO public.officer_record_photos(
      organization_id,officer_id,field_report_id,incident_id,shift_id,evidence_id,
      storage_path,sha256_hash,original_name,selected_at
    ) VALUES (
      v_org,v_user,CASE WHEN p_record_kind='field_report' THEN p_record_id END,
      CASE WHEN p_record_kind='incident' THEN p_record_id END,v_shift,v_evidence,
      v_path,p_sha256,p_original_name,p_selected_at
    ) RETURNING * INTO v_photo;
    INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
    VALUES(v_org,v_user,'officer_record_photo_attached','evidence_items',v_evidence,
      jsonb_build_object('record_kind',p_record_kind,'record_id',p_record_id,'shift_id',v_shift,
        'sha256',p_sha256,'privacy_review_status','pending'));
  END IF;
  RETURN jsonb_build_object('attachment_id',v_photo.id,'evidence_id',v_photo.evidence_id,
    'record_kind',p_record_kind,'record_id',p_record_id,'organization_id',v_photo.organization_id,
    'shift_id',v_photo.shift_id,'sha256',v_photo.sha256_hash,'storage_path',v_photo.storage_path,
    'privacy_review_status','pending');
END;
$function$;
REVOKE ALL ON FUNCTION "public"."attach_officer_record_photo"(p_record_kind text, p_record_id uuid, p_sha256 text, p_original_name text, p_selected_at timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."attach_officer_record_photo"(p_record_kind text, p_record_id uuid, p_sha256 text, p_original_name text, p_selected_at timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."attach_officer_record_photo"(p_record_kind text, p_record_id uuid, p_sha256 text, p_original_name text, p_selected_at timestamp with time zone) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."attach_officer_record_photo"(p_record_kind text, p_record_id uuid, p_sha256 text, p_original_name text, p_selected_at timestamp with time zone) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."attach_tender_document"(p_tender_id uuid, p_document_name text, p_document_type text, p_storage_path text, p_source_sha256 text DEFAULT NULL::text, p_source_reference text DEFAULT NULL::text, p_source_document_id uuid DEFAULT NULL::uuid)
 RETURNS tender_documents
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_tender public.tenders%rowtype;
  v_document public.tender_documents%rowtype;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  IF nullif(trim(coalesce(p_document_name, '')), '') IS NULL
     OR nullif(trim(coalesce(p_storage_path, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Document name and storage path are required';
  END IF;
  IF p_storage_path ~ '(^|/)\.\.(/|$)' OR p_storage_path LIKE '/%' OR p_storage_path ~ '^[A-Za-z]:[\\/]' THEN
    RAISE EXCEPTION 'Storage path must be a tenant-relative object path';
  END IF;
  SELECT * INTO STRICT v_tender
  FROM public.tenders
  WHERE id = p_tender_id
  FOR SHARE;
  IF NOT public.is_admin_for_org(v_tender.organization_id) THEN
    RAISE EXCEPTION 'Tender document attachment denied';
  END IF;
  IF p_source_document_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.documents d
    WHERE d.id = p_source_document_id
      AND (d.organization_id = v_tender.organization_id OR d.organization_id IS NULL)
  ) THEN
    RAISE EXCEPTION 'Source document is outside the tender organisation';
  END IF;
  INSERT INTO public.tender_documents(
    tender_id, organization_id, document_name, document_type, storage_path,
    source_document_id, source_sha256, source_reference, uploaded_by
  ) VALUES (
    v_tender.id, v_tender.organization_id, trim(p_document_name), nullif(trim(coalesce(p_document_type, '')), ''),
    trim(p_storage_path), p_source_document_id, nullif(trim(coalesce(p_source_sha256, '')), ''),
    nullif(trim(coalesce(p_source_reference, '')), ''), v_actor
  )
  ON CONFLICT (organization_id, tender_id, source_sha256)
  WHERE source_sha256 IS NOT NULL
  DO UPDATE SET document_name = public.tender_documents.document_name
  RETURNING * INTO v_document;
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (
    v_tender.organization_id, v_actor, 'tender_document_attached', 'tender_documents', v_document.id,
    jsonb_build_object(
      'tender_id', v_tender.id, 'document_name', v_document.document_name,
      'source_sha256', v_document.source_sha256, 'source_reference', v_document.source_reference,
      'review_status', v_document.review_status
    )
  );
  RETURN v_document;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."attach_tender_document"(p_tender_id uuid, p_document_name text, p_document_type text, p_storage_path text, p_source_sha256 text, p_source_reference text, p_source_document_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."attach_tender_document"(p_tender_id uuid, p_document_name text, p_document_type text, p_storage_path text, p_source_sha256 text, p_source_reference text, p_source_document_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."attach_tender_document"(p_tender_id uuid, p_document_name text, p_document_type text, p_storage_path text, p_source_sha256 text, p_source_reference text, p_source_document_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."attach_tender_document"(p_tender_id uuid, p_document_name text, p_document_type text, p_storage_path text, p_source_sha256 text, p_source_reference text, p_source_document_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."attribute_permit_holder"(p_organization_id uuid, p_canonical_person_id uuid, p_full_name text, p_permit_numbers text[], p_source_document text, p_source_sha256 text, p_with_same_email boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_name text := nullif(regexp_replace(trim(coalesce(p_full_name, '')), '\s+', ' ', 'g'), '');
  v_source text := nullif(trim(coalesce(p_source_document, '')), '');
  v_hash text := lower(nullif(trim(coalesce(p_source_sha256, '')), ''));
  v_person public.canonical_people%rowtype;
  v_evidence text[];
  v_numbers text[];
  v_held text[];
  v_missing integer;
  v_added integer;
  v_target uuid;
  v_outcome text;
  v_moved integer := 0;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_organization_id IS NULL OR NOT public.is_admin_for_org(p_organization_id) THEN
    RAISE EXCEPTION 'Administrator access to the permit organisation is required';
  END IF;
  IF v_source IS NULL THEN RAISE EXCEPTION 'The source document is required'; END IF;
  IF v_hash IS NULL OR v_hash !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'A SHA-256 source hash is required'; END IF;
  IF cardinality(public.person_name_parts(v_name)) < 2 THEN
    RAISE EXCEPTION 'A full name of at least two words is required';
  END IF;
  v_evidence := array(
    SELECT DISTINCT cleaned.permit_number FROM (
      SELECT nullif(regexp_replace(trim(item), '\s+', ' ', 'g'), '') AS permit_number
      FROM unnest(coalesce(p_permit_numbers, '{}'::text[])) AS listed(item)
    ) cleaned
    WHERE cleaned.permit_number IS NOT NULL
    ORDER BY cleaned.permit_number
  );
  IF cardinality(v_evidence) = 0 THEN RAISE EXCEPTION 'At least one evidence permit is required'; END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('canonical-person:' || coalesce(p_canonical_person_id::text, ''), 0));
  SELECT * INTO v_person FROM public.canonical_people p WHERE p.id = p_canonical_person_id FOR UPDATE;
  IF v_person.id IS NULL OR v_person.status <> 'active' OR v_person.merged_into_id IS NOT NULL THEN
    RAISE EXCEPTION 'The permit holder must be an active, unmerged person';
  END IF;

  v_held := array(
    SELECT permit.permit_number FROM public.person_permits permit
    WHERE permit.organization_id = p_organization_id AND permit.canonical_person_id = v_person.id
    ORDER BY permit.permit_number
  );
  SELECT count(*) INTO v_missing FROM unnest(v_evidence) AS listed(permit_number) WHERE listed.permit_number <> ALL (v_held);
  IF v_missing > 0 THEN
    RAISE EXCEPTION 'Permit holder conflict: % of the listed permits are not held by this person', v_missing;
  END IF;

  v_numbers := v_evidence;
  IF coalesce(p_with_same_email, false) THEN
    -- The record's other permits applied for under an evidence permit's email belong to the same holder.
    v_numbers := array(
      SELECT permit.permit_number FROM public.person_permits permit
      WHERE permit.organization_id = p_organization_id AND permit.canonical_person_id = v_person.id
        AND (permit.permit_number = ANY (v_evidence) OR lower(trim(permit.contact_email)) IN (
          SELECT lower(trim(evidence.contact_email)) FROM public.person_permits evidence
          WHERE evidence.organization_id = p_organization_id AND evidence.canonical_person_id = v_person.id
            AND evidence.permit_number = ANY (v_evidence) AND nullif(trim(evidence.contact_email), '') IS NOT NULL))
      ORDER BY permit.permit_number
    );
  END IF;

  IF public.normalize_person_name(v_person.display_name) = public.normalize_person_name(v_name) THEN
    IF cardinality(v_numbers) = cardinality(v_held) THEN
      RETURN jsonb_build_object('outcome', 'unchanged', 'canonical_person_id', v_person.id,
        'from_canonical_person_id', v_person.id, 'permits_attributed', cardinality(v_numbers),
        'permits_moved', 0, 'permits_remaining', cardinality(v_held));
    END IF;
    RAISE EXCEPTION 'Permit holder name conflict: the person already carries this name, so it cannot separate their permits';
  END IF;
  IF v_person.metadata->>'name_basis' IS DISTINCT FROM 'surname' THEN
    RAISE EXCEPTION 'Permit holder name conflict: the person is not recorded by surname alone';
  END IF;
  IF NOT public.person_name_extends(v_person.display_name, v_name) THEN
    RAISE EXCEPTION 'Permit holder name conflict: the full name must end with the recorded name';
  END IF;
  v_added := cardinality(public.person_name_parts(v_name)) - cardinality(public.person_name_parts(v_person.display_name));

  IF cardinality(v_numbers) = cardinality(v_held) THEN
    IF EXISTS (SELECT 1 FROM public.person_permits permit
               WHERE permit.canonical_person_id = v_person.id AND permit.organization_id <> p_organization_id)
       OR EXISTS (SELECT 1 FROM public.canonical_person_links link
                  WHERE link.canonical_person_id = v_person.id AND link.organization_id IS DISTINCT FROM p_organization_id)
       OR EXISTS (SELECT 1 FROM public.notices notice
                  WHERE notice.person_id = v_person.id AND notice.organization_id IS DISTINCT FROM p_organization_id)
       OR EXISTS (SELECT 1 FROM public.entity_links link
                  WHERE ((link.from_type = 'person' AND link.from_id = v_person.id) OR (link.to_type = 'person' AND link.to_id = v_person.id))
                    AND link.organization_id IS DISTINCT FROM p_organization_id)
       OR EXISTS (SELECT 1 FROM public.vehicle_identity_checks identity_check
                  WHERE identity_check.canonical_person_id = v_person.id
                    AND identity_check.organization_id IS DISTINCT FROM p_organization_id) THEN
      RAISE EXCEPTION 'Permit holder is shared: another organisation records this person, so the name is not changed here';
    END IF;
    UPDATE public.canonical_people p SET
      display_name = v_name,
      normalized_name = public.normalize_person_name(v_name),
      metadata = (p.metadata - 'name_basis' - 'name_basis_source') || jsonb_build_object('name_completed', jsonb_build_object(
        'previous_display_name', v_person.display_name, 'previous_name_basis', v_person.metadata->>'name_basis',
        'source_document', v_source, 'source_sha256', v_hash, 'permit_numbers', to_jsonb(v_numbers), 'completed_at', now())),
      updated_at = clock_timestamp()
    WHERE p.id = v_person.id;
    v_target := v_person.id;
    v_outcome := 'name_completed';
  ELSE
    v_target := gen_random_uuid();
    INSERT INTO public.canonical_people (id, canonical_key, display_name, normalized_name, metadata, review_state, status)
    VALUES (v_target, 'person:permit-holder:' || v_target::text, v_name, public.normalize_person_name(v_name),
      jsonb_build_object('split_from_canonical_person_id', v_person.id, 'source_document', v_source,
        'source_sha256', v_hash, 'permit_numbers', to_jsonb(v_numbers)),
      'draft', 'active');
    UPDATE public.person_permits permit SET canonical_person_id = v_target, updated_at = now()
    WHERE permit.organization_id = p_organization_id AND permit.canonical_person_id = v_person.id
      AND permit.permit_number = ANY (v_numbers);
    GET DIAGNOSTICS v_moved = ROW_COUNT;
    v_outcome := 'split';
  END IF;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (p_organization_id, v_actor,
    CASE v_outcome WHEN 'split' THEN 'permit_holder_split' ELSE 'permit_holder_name_completed' END,
    'canonical_people', v_target,
    jsonb_build_object(
      'source_document', v_source, 'source_sha256', v_hash, 'permit_numbers', to_jsonb(v_numbers),
      'from_canonical_person_id', v_person.id, 'canonical_person_id', v_target,
      'with_same_email', coalesce(p_with_same_email, false), 'given_name_words_added', v_added,
      'permits_moved', v_moved, 'permits_remaining', cardinality(v_held) - v_moved));

  RETURN jsonb_build_object('outcome', v_outcome, 'canonical_person_id', v_target, 'from_canonical_person_id', v_person.id,
    'permits_attributed', cardinality(v_numbers), 'permits_moved', v_moved, 'permits_remaining', cardinality(v_held) - v_moved);
END;
$function$;
COMMENT ON FUNCTION "public"."attribute_permit_holder"(p_organization_id uuid, p_canonical_person_id uuid, p_full_name text, p_permit_numbers text[], p_source_document text, p_source_sha256 text, p_with_same_email boolean) IS 'Organisation-administrator repair of a permit holder''s identity from a permit extract that names the holder of each listed permit. When the listed permits (plus, on request, the record''s other permits applied for under the same email) are all the record''s permits, the given names are added in front of the recorded name; otherwise they move to a new person of their own. Refuses a person not recorded by surname alone (metadata name_basis), names that do not extend the recorded name, permits the person does not hold, and renaming a person another organisation records. Keeps the previous name on the person; audited with source file and SHA-256 and no personal values.';
REVOKE ALL ON FUNCTION "public"."attribute_permit_holder"(p_organization_id uuid, p_canonical_person_id uuid, p_full_name text, p_permit_numbers text[], p_source_document text, p_source_sha256 text, p_with_same_email boolean) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."attribute_permit_holder"(p_organization_id uuid, p_canonical_person_id uuid, p_full_name text, p_permit_numbers text[], p_source_document text, p_source_sha256 text, p_with_same_email boolean) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."attribute_permit_holder"(p_organization_id uuid, p_canonical_person_id uuid, p_full_name text, p_permit_numbers text[], p_source_document text, p_source_sha256 text, p_with_same_email boolean) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."attribute_permit_holder"(p_organization_id uuid, p_canonical_person_id uuid, p_full_name text, p_permit_numbers text[], p_source_document text, p_source_sha256 text, p_with_same_email boolean) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."autolink_client_site_service_agreement"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  -- A captured draft does not approve financial defaults or an inferred provider relationship.
  if new.metadata->>'created_via' in ('service_client_setup', 'officer_field_capture')
    or new.metadata->'field_place_managed' = 'true'::jsonb then return new; end if;
  if new.service_agreement_id is null and new.client_organization_id is not null then
    select sa.id
      into new.service_agreement_id
    from public.service_agreements sa
    where sa.client_organization_id = new.client_organization_id
      and (sa.ends_on is null or sa.ends_on >= current_date)
    order by sa.starts_on desc nulls last, sa.created_at desc, sa.id desc
    limit 1;
  end if;

  return new;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."autolink_client_site_service_agreement"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."autolink_client_site_service_agreement"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."autolink_client_site_service_agreement"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."autolink_client_site_service_agreement"() TO "anon";
GRANT EXECUTE ON FUNCTION "public"."autolink_client_site_service_agreement"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."autolink_client_site_service_agreement"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."base44_rams_resolve_person"(p_provider_organization_id uuid, p_canonical_key text, p_name text, p_email text, OUT person_id uuid, OUT created boolean, OUT needs_review boolean)
 RETURNS record
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
	v_norm text := public.normalize_person_name(p_name);
	v_email text := nullif(lower(btrim(p_email)), '');
	v_candidates uuid[];
	v_same_name boolean;
begin
	created := false;
	needs_review := false;

	select coalesce(cp.merged_into_id, cp.id) into person_id
	from public.canonical_people cp where cp.canonical_key = p_canonical_key;
	if person_id is not null then
		return;
	end if;

	if v_email is not null and v_norm is not null then
		select array_agg(distinct p.id) into v_candidates
		from (
			select pp.canonical_person_id as id
			from public.person_permits pp
			where pp.organization_id = p_provider_organization_id and lower(btrim(pp.contact_email)) = v_email
			union
			select rp.canonical_person_id
			from public.rams_person_profiles rp
			where rp.organization_id = p_provider_organization_id and rp.email = v_email
		) m
		join public.canonical_people p on p.id = m.id
		where p.status = 'active' and p.merged_into_id is null
			and public.normalize_person_name(p.display_name) = v_norm;
		if cardinality(v_candidates) = 1 then
			person_id := v_candidates[1];
			return;
		end if;
	end if;

	select exists (
		select 1 from public.canonical_people p
		where p.normalized_name = v_norm and p.status = 'active' and p.merged_into_id is null
	) into v_same_name;

	insert into public.canonical_people (canonical_key, display_name, normalized_name, review_state, status, metadata)
	values (p_canonical_key, p_name, coalesce(v_norm, ''),
		case when v_same_name then 'manual_review_required' else 'draft' end, 'active',
		jsonb_build_object('source', 'base44_rams', 'possible_duplicate_name', v_same_name))
	on conflict (canonical_key) do nothing
	returning id into person_id;
	if person_id is null then
		select coalesce(cp.merged_into_id, cp.id) into person_id from public.canonical_people cp where cp.canonical_key = p_canonical_key;
	else
		created := true;
		needs_review := v_same_name;
	end if;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."base44_rams_resolve_person"(p_provider_organization_id uuid, p_canonical_key text, p_name text, p_email text, OUT person_id uuid, OUT created boolean, OUT needs_review boolean) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."base44_rams_resolve_person"(p_provider_organization_id uuid, p_canonical_key text, p_name text, p_email text, OUT person_id uuid, OUT created boolean, OUT needs_review boolean) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."batch_publish_roster_slots"(p_client_request_id uuid, p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone)
 RETURNS TABLE(published_count integer, materialized_count integer, conflict_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid := auth.uid(); v_provider uuid; v_slot record; v_unit public.roster_work_units%rowtype; v_pub integer := 0; v_mat integer := 0; v_conf integer := 0; v_res record; v_error text;
begin
  if p_client_request_id is null then raise exception 'client_request_id is required'; end if;
  select actor.organization_id into v_provider from public.user_profiles actor where actor.id = v_actor and actor.deactivated_at is null;
  if v_provider is null or not public.is_admin_for_org(v_provider) then raise exception 'Active roster administrator required'; end if;
  if p_organization_id <> v_provider then raise exception 'Organization is outside your managed account hierarchy'; end if;
  for v_slot in (select s.* from public.roster_slots s where s.organization_id = v_provider and s.status = 'draft' and s.scheduled_start >= p_from and s.scheduled_start < p_to for update) loop
    if v_slot.staff_id is not null and exists (select 1 from public.leave_requests l where l.staff_id = v_slot.staff_id and l.status = 'approved' and daterange(l.starts_on, l.ends_on, '[]') && daterange(v_slot.scheduled_start::date, v_slot.scheduled_end::date, '[]')) then v_conf := v_conf + 1; continue; end if;
    update public.roster_slots set status = 'published', updated_at = now() where id = v_slot.id; v_pub := v_pub + 1;
    select wu.* into v_unit from public.roster_work_units wu where wu.id = v_slot.work_unit_id;
    if found and v_unit.work_unit_type in ('patrol', 'static') then
      begin select * into v_res from public.materialize_roster_slot(v_slot.id, 'published'); v_mat := v_mat + 1;
      exception when others then
        get stacked diagnostics v_error = message_text;
        insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata) values (v_provider, v_actor, 'roster_batch_publish_materialization_failed', 'roster_slots', v_slot.id, jsonb_build_object('client_request_id', p_client_request_id, 'error', v_error, 'work_unit_id', v_slot.work_unit_id));
      end;
    end if;
  end loop;
  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata) values (v_provider, v_actor, 'roster_period_batch_published', 'roster_slots', v_provider, jsonb_build_object('from', p_from, 'to', p_to, 'published_count', v_pub, 'materialized_count', v_mat, 'conflict_count', v_conf, 'client_request_id', p_client_request_id));
  return query select v_pub, v_mat, v_conf;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."batch_publish_roster_slots"(p_client_request_id uuid, p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."batch_publish_roster_slots"(p_client_request_id uuid, p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."batch_publish_roster_slots"(p_client_request_id uuid, p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."batch_publish_roster_slots"(p_client_request_id uuid, p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."batch_publish_roster_slots"(p_client_request_id uuid, p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."batch_publish_roster_slots"(p_client_request_id uuid, p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."begin_patrol_import_batch"(p_provider_organization_id uuid, p_client_organization_id uuid, p_batch_name text, p_source_file text, p_source_sha256 text, p_parser text, p_manifest_json jsonb, p_schema_json jsonb, p_row_count integer, p_duplicate_count integer, p_unresolved_count integer)
 RETURNS file_import_batches
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_batch public.file_import_batches%rowtype;
  v_key text:=nullif(p_manifest_json->>'idempotency_key','');
BEGIN
  IF v_key IS NULL THEN RAISE EXCEPTION 'Import idempotency key is required'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_provider_organization_id::text||':'||v_key,0));
  SELECT * INTO v_batch FROM public.file_import_batches
  WHERE organization_id=p_provider_organization_id AND manifest_json->>'idempotency_key'=v_key
  FOR UPDATE;
  IF FOUND THEN
    IF v_batch.status<>'staging' THEN RAISE EXCEPTION 'This source and import configuration already has a closed review batch'; END IF;
    IF v_batch.batch_name IS DISTINCT FROM trim(p_batch_name)
      OR v_batch.source_file IS DISTINCT FROM trim(p_source_file)
      OR v_batch.source_sha256 IS DISTINCT FROM p_source_sha256
      OR v_batch.parser IS DISTINCT FROM trim(p_parser)
      OR v_batch.manifest_json IS DISTINCT FROM p_manifest_json
      OR v_batch.schema_json IS DISTINCT FROM p_schema_json
      OR v_batch.row_count IS DISTINCT FROM p_row_count
      OR v_batch.duplicate_count IS DISTINCT FROM p_duplicate_count
      OR v_batch.unresolved_count IS DISTINCT FROM p_unresolved_count THEN
      RAISE EXCEPTION 'Open import batch metadata is immutable; use a new source/configuration identity';
    END IF;
    RETURN v_batch;
  END IF;
  RETURN public.begin_patrol_import_batch_identity_bound_unfrozen(
    p_provider_organization_id,p_client_organization_id,p_batch_name,p_source_file,p_source_sha256,
    p_parser,p_manifest_json,p_schema_json,p_row_count,p_duplicate_count,p_unresolved_count
  );
END;
$function$;
REVOKE ALL ON FUNCTION "public"."begin_patrol_import_batch"(p_provider_organization_id uuid, p_client_organization_id uuid, p_batch_name text, p_source_file text, p_source_sha256 text, p_parser text, p_manifest_json jsonb, p_schema_json jsonb, p_row_count integer, p_duplicate_count integer, p_unresolved_count integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."begin_patrol_import_batch"(p_provider_organization_id uuid, p_client_organization_id uuid, p_batch_name text, p_source_file text, p_source_sha256 text, p_parser text, p_manifest_json jsonb, p_schema_json jsonb, p_row_count integer, p_duplicate_count integer, p_unresolved_count integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."begin_patrol_import_batch"(p_provider_organization_id uuid, p_client_organization_id uuid, p_batch_name text, p_source_file text, p_source_sha256 text, p_parser text, p_manifest_json jsonb, p_schema_json jsonb, p_row_count integer, p_duplicate_count integer, p_unresolved_count integer) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."begin_patrol_import_batch"(p_provider_organization_id uuid, p_client_organization_id uuid, p_batch_name text, p_source_file text, p_source_sha256 text, p_parser text, p_manifest_json jsonb, p_schema_json jsonb, p_row_count integer, p_duplicate_count integer, p_unresolved_count integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."begin_patrol_import_batch_identity_bound_unfrozen"(p_provider_organization_id uuid, p_client_organization_id uuid, p_batch_name text, p_source_file text, p_source_sha256 text, p_parser text, p_manifest_json jsonb, p_schema_json jsonb, p_row_count integer, p_duplicate_count integer, p_unresolved_count integer)
 RETURNS file_import_batches
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_profile public.import_source_profiles%rowtype;
BEGIN
  SELECT * INTO v_profile FROM public.import_source_profiles
  WHERE organization_id=p_provider_organization_id AND profile_code=p_manifest_json->>'source_profile' AND active;
  IF NOT FOUND OR v_profile.import_actor_id IS NULL OR v_profile.import_actor_id<>auth.uid() THEN RAISE EXCEPTION 'Configured tenant import identity required'; END IF;
  IF NOT public.is_tenant_import_admin(p_provider_organization_id) THEN RAISE EXCEPTION 'Configured import identity is not an active tenant administrator'; END IF;
  RETURN public.begin_patrol_import_batch_provenance_unchecked(
    p_provider_organization_id,p_client_organization_id,p_batch_name,p_source_file,p_source_sha256,
    p_parser,p_manifest_json,p_schema_json,p_row_count,p_duplicate_count,p_unresolved_count
  );
END;
$function$;
REVOKE ALL ON FUNCTION "public"."begin_patrol_import_batch_identity_bound_unfrozen"(p_provider_organization_id uuid, p_client_organization_id uuid, p_batch_name text, p_source_file text, p_source_sha256 text, p_parser text, p_manifest_json jsonb, p_schema_json jsonb, p_row_count integer, p_duplicate_count integer, p_unresolved_count integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."begin_patrol_import_batch_identity_bound_unfrozen"(p_provider_organization_id uuid, p_client_organization_id uuid, p_batch_name text, p_source_file text, p_source_sha256 text, p_parser text, p_manifest_json jsonb, p_schema_json jsonb, p_row_count integer, p_duplicate_count integer, p_unresolved_count integer) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."begin_patrol_import_batch_provenance_unchecked"(p_provider_organization_id uuid, p_client_organization_id uuid, p_batch_name text, p_source_file text, p_source_sha256 text, p_parser text, p_manifest_json jsonb, p_schema_json jsonb, p_row_count integer, p_duplicate_count integer, p_unresolved_count integer)
 RETURNS file_import_batches
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_source_sha256 IS NULL OR p_source_sha256 !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'A lowercase SHA-256 source hash is required'; END IF;
  IF p_manifest_json->>'derivative_sha256' IS NULL OR p_manifest_json->>'derivative_sha256' !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'A lowercase SHA-256 derivative hash is required'; END IF;
  RETURN public.begin_patrol_import_batch_unvalidated(
    p_provider_organization_id,p_client_organization_id,p_batch_name,p_source_file,p_source_sha256,
    p_parser,p_manifest_json,p_schema_json,p_row_count,p_duplicate_count,p_unresolved_count
  );
END;
$function$;
REVOKE ALL ON FUNCTION "public"."begin_patrol_import_batch_provenance_unchecked"(p_provider_organization_id uuid, p_client_organization_id uuid, p_batch_name text, p_source_file text, p_source_sha256 text, p_parser text, p_manifest_json jsonb, p_schema_json jsonb, p_row_count integer, p_duplicate_count integer, p_unresolved_count integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."begin_patrol_import_batch_provenance_unchecked"(p_provider_organization_id uuid, p_client_organization_id uuid, p_batch_name text, p_source_file text, p_source_sha256 text, p_parser text, p_manifest_json jsonb, p_schema_json jsonb, p_row_count integer, p_duplicate_count integer, p_unresolved_count integer) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."begin_patrol_import_batch_unvalidated"(p_provider_organization_id uuid, p_client_organization_id uuid, p_batch_name text, p_source_file text, p_source_sha256 text, p_parser text, p_manifest_json jsonb, p_schema_json jsonb, p_row_count integer, p_duplicate_count integer, p_unresolved_count integer)
 RETURNS file_import_batches
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_batch public.file_import_batches%rowtype;
  v_idempotency_key text := nullif(p_manifest_json->>'idempotency_key', '');
  v_header text;
  v_mapping jsonb;
  v_expected_mappings integer;
  v_actual_mappings integer;
BEGIN
  IF v_actor IS NULL OR NOT public.is_tenant_import_admin(p_provider_organization_id) THEN RAISE EXCEPTION 'Tenant import administrator required'; END IF;
  IF p_provider_organization_id = p_client_organization_id THEN RAISE EXCEPTION 'Patrol import requires a distinct client organization'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.organizations WHERE id = p_provider_organization_id AND active) THEN RAISE EXCEPTION 'Active provider organization required'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.organizations WHERE id = p_client_organization_id AND active) THEN RAISE EXCEPTION 'Active client organization required'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.service_agreements agreement
    WHERE agreement.provider_organization_id = p_provider_organization_id
      AND agreement.client_organization_id = p_client_organization_id
      AND agreement.agreement_type = 'operational'
      AND (agreement.starts_on IS NULL OR agreement.starts_on <= current_date)
      AND (agreement.ends_on IS NULL OR agreement.ends_on >= current_date)
  ) THEN RAISE EXCEPTION 'An active operational provider-client agreement is required'; END IF;
  IF v_idempotency_key IS NULL THEN RAISE EXCEPTION 'Import idempotency key is required'; END IF;
  IF p_source_sha256 !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'A lowercase SHA-256 source hash is required'; END IF;
  IF jsonb_typeof(p_schema_json->'headers') <> 'array' OR jsonb_typeof(p_schema_json->'resolved_mappings') <> 'array' THEN RAISE EXCEPTION 'Import headers and resolved mappings are required'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.import_source_profiles profile
    WHERE profile.organization_id = p_provider_organization_id
      AND profile.profile_code = p_manifest_json->>'source_profile'
      AND profile.active
  ) THEN RAISE EXCEPTION 'Active provider import profile required'; END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(p_provider_organization_id::text || ':' || v_idempotency_key, 0));
  SELECT * INTO v_batch FROM public.file_import_batches
  WHERE organization_id = p_provider_organization_id
    AND manifest_json->>'idempotency_key' = v_idempotency_key
  FOR UPDATE;
  IF FOUND AND v_batch.status <> 'staging' THEN RAISE EXCEPTION 'This source and import configuration already has a closed review batch'; END IF;

  IF NOT FOUND THEN
    INSERT INTO public.file_import_batches(
      organization_id, batch_name, source_file, source_sha256, parser, status,
      manifest_json, schema_json, row_count, duplicate_count, unresolved_count, created_by
    ) VALUES (
      p_provider_organization_id, trim(p_batch_name), trim(p_source_file), p_source_sha256,
      trim(p_parser), 'staging', p_manifest_json, p_schema_json,
      p_row_count, p_duplicate_count, p_unresolved_count, v_actor
    ) RETURNING * INTO v_batch;
  ELSE
    UPDATE public.file_import_batches SET
      batch_name = trim(p_batch_name), source_file = trim(p_source_file), source_sha256 = p_source_sha256,
      parser = trim(p_parser), manifest_json = p_manifest_json, schema_json = p_schema_json,
      row_count = p_row_count, duplicate_count = p_duplicate_count,
      unresolved_count = p_unresolved_count, updated_at = clock_timestamp()
    WHERE id = v_batch.id RETURNING * INTO v_batch;
    DELETE FROM public.file_import_mapping_reviews WHERE batch_id = v_batch.id AND decision = 'proposed';
  END IF;

  WITH normalized_headers AS (
    SELECT nullif(lower(regexp_replace(btrim(value), '\s+', ' ', 'g')), '') AS normalized_header
    FROM jsonb_array_elements_text(p_schema_json->'headers')
  )
  SELECT count(*)::integer, count(DISTINCT normalized_header)::integer
  INTO v_expected_mappings, v_actual_mappings
  FROM normalized_headers
  WHERE normalized_header IS NOT NULL;
  IF v_expected_mappings <> v_actual_mappings THEN RAISE EXCEPTION 'Duplicate source headers require manual correction'; END IF;

  FOR v_header IN
    SELECT value
    FROM jsonb_array_elements_text(p_schema_json->'headers')
    WHERE nullif(regexp_replace(btrim(value), '\s+', '', 'g'), '') IS NOT NULL
  LOOP
    v_mapping := NULL;
    SELECT item INTO v_mapping
    FROM jsonb_array_elements(p_schema_json->'resolved_mappings') item
    WHERE item->>'source_column' = v_header
    LIMIT 1;
    INSERT INTO public.file_import_mapping_reviews(
      organization_id, batch_id, source_column, target_entity, target_field, decision
    ) VALUES (
      v_batch.organization_id, v_batch.id, v_header,
      v_mapping->>'target_entity', v_mapping->>'target_field', 'proposed'
    ) ON CONFLICT(batch_id, source_column) DO NOTHING;
  END LOOP;

  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_batch.organization_id, v_actor, 'patrol_import_batch_staging_started', 'file_import_batches', v_batch.id,
    jsonb_build_object('client_organization_id', p_client_organization_id, 'source_profile', p_manifest_json->>'source_profile'));
  RETURN v_batch;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."begin_patrol_import_batch_unvalidated"(p_provider_organization_id uuid, p_client_organization_id uuid, p_batch_name text, p_source_file text, p_source_sha256 text, p_parser text, p_manifest_json jsonb, p_schema_json jsonb, p_row_count integer, p_duplicate_count integer, p_unresolved_count integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."begin_patrol_import_batch_unvalidated"(p_provider_organization_id uuid, p_client_organization_id uuid, p_batch_name text, p_source_file text, p_source_sha256 text, p_parser text, p_manifest_json jsonb, p_schema_json jsonb, p_row_count integer, p_duplicate_count integer, p_unresolved_count integer) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."bob_atlas_expectation_report"(p_limit integer DEFAULT 200, p_offset integer DEFAULT 0)
 RETURNS TABLE(expectation_id uuid, spine text, assertion_kind text, from_type text, from_name text, to_type text, to_name text, via_type text, via_name text, expectation_status text, gap_kind text, rationale text, signal_weight numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with recursive active_expectations as (
    select *
    from public.app_map_expectations
    where status = 'active'
  ), paths as (
    select
      e.id as expectation_id,
      e.from_type as entity_type,
      e.from_name as entity_name,
      0 as depth,
      array[e.from_type || ':' || e.from_name]::text[] as path
    from active_expectations e
    union all
    select
      p.expectation_id,
      edge.target_type,
      edge.target_name,
      p.depth + 1,
      p.path || (edge.target_type || ':' || edge.target_name)
    from paths p
    join public.bob_app_map_edges edge
      on edge.source_type = p.entity_type
     and edge.source_name = p.entity_name
     and edge.retirement_status = 'live'
     and edge.edge_kind in ('writes', 'reads', 'calls', 'invokes')
    where p.depth < 8
      and not (edge.target_type || ':' || edge.target_name) = any(p.path)
  ), evaluated as (
    select
      e.*,
      exists (
        select 1 from paths p
        where p.expectation_id = e.id
          and p.entity_type = e.to_type
          and p.entity_name = e.to_name
      ) as reaches_target,
      exists (
        select 1 from paths p
        where p.expectation_id = e.id
          and p.entity_type = e.to_type
          and p.entity_name = e.to_name
          and e.via_type is not null
          and (e.via_type || ':' || e.via_name) = any(p.path)
      ) as reaches_target_via
    from active_expectations e
  )
  select
    e.id,
    e.spine,
    e.assertion_kind,
    e.from_type,
    e.from_name,
    e.to_type,
    e.to_name,
    e.via_type,
    e.via_name,
    case
      when e.assertion_kind = 'must_reach' and e.reaches_target then 'satisfied'
      when e.assertion_kind = 'must_not_reach' and not e.reaches_target then 'satisfied'
      when e.assertion_kind = 'must_pass_through' and e.reaches_target_via then 'satisfied'
      else 'gap'
    end as expectation_status,
    case
      when e.assertion_kind = 'must_reach' and not e.reaches_target then 'broken_reach'
      when e.assertion_kind = 'must_not_reach' and e.reaches_target then 'prohibited_reach'
      when e.assertion_kind = 'must_pass_through' and not e.reaches_target_via then 'missing_required_hop'
      else null
    end as gap_kind,
    e.rationale,
    e.signal_weight
  from evaluated e
  order by e.spine, e.from_type, e.from_name, e.to_type, e.to_name
  limit greatest(1, least(coalesce(p_limit, 200), 500))
  offset greatest(0, coalesce(p_offset, 0));
$function$;
COMMENT ON FUNCTION "public"."bob_atlas_expectation_report"(p_limit integer, p_offset integer) IS 'Atlas intent evaluator: tests active authored must_reach, must_not_reach, and must_pass_through assertions against directed live flow edges, cycle-guarded and capped at eight hops.';
REVOKE ALL ON FUNCTION "public"."bob_atlas_expectation_report"(p_limit integer, p_offset integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."bob_atlas_expectation_report"(p_limit integer, p_offset integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."bob_atlas_expectation_report"(p_limit integer, p_offset integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."bob_atlas_fk_reach"(p_from_type text, p_from_name text, p_max_depth integer DEFAULT 8)
 RETURNS TABLE(entity_type text, entity_name text, depth integer, edge_kind text, edge_from text, edge_to text, path text[])
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH RECURSIVE walk AS (
    SELECT
      p_from_type::text AS entity_type,
      p_from_name::text AS entity_name,
      0 AS depth,
      NULL::text AS edge_kind,
      NULL::text AS edge_from,
      NULL::text AS edge_to,
      ARRAY[p_from_type || ':' || p_from_name]::text[] AS path
    UNION ALL
    SELECT
      neighbour.entity_type,
      neighbour.entity_name,
      walk.depth + 1,
      edge.edge_kind,
      edge.source_type || ':' || edge.source_name,
      edge.target_type || ':' || edge.target_name,
      walk.path || (neighbour.entity_type || ':' || neighbour.entity_name)
    FROM walk
    JOIN public.bob_app_map_edges edge
      ON edge.retirement_status = 'live'
     AND edge.edge_kind = 'fk_references'
     AND (
          (edge.source_type = walk.entity_type AND edge.source_name = walk.entity_name)
       OR (edge.target_type = walk.entity_type AND edge.target_name = walk.entity_name)
     )
    CROSS JOIN LATERAL (
      SELECT
        CASE
          WHEN edge.source_type = walk.entity_type AND edge.source_name = walk.entity_name
            THEN edge.target_type
          ELSE edge.source_type
        END AS entity_type,
        CASE
          WHEN edge.source_type = walk.entity_type AND edge.source_name = walk.entity_name
            THEN edge.target_name
          ELSE edge.source_name
        END AS entity_name
    ) neighbour
    WHERE walk.depth < LEAST(GREATEST(COALESCE(p_max_depth, 8), 1), 20)
      AND NOT (neighbour.entity_type || ':' || neighbour.entity_name) = ANY(walk.path)
  ),
  nearest AS (
    SELECT DISTINCT ON (walk.entity_type, walk.entity_name)
      walk.entity_type,
      walk.entity_name,
      walk.depth,
      walk.edge_kind,
      walk.edge_from,
      walk.edge_to,
      walk.path
    FROM walk
    WHERE walk.depth > 0
    ORDER BY walk.entity_type, walk.entity_name, walk.depth, cardinality(walk.path), walk.path
  )
  SELECT
    nearest.entity_type,
    nearest.entity_name,
    nearest.depth,
    nearest.edge_kind,
    nearest.edge_from,
    nearest.edge_to,
    nearest.path
  FROM nearest
  ORDER BY nearest.depth, nearest.entity_type, nearest.entity_name;
$function$;
COMMENT ON FUNCTION "public"."bob_atlas_fk_reach"(p_from_type text, p_from_name text, p_max_depth integer) IS 'Atlas blast-radius: undirected live fk_references adjacency only, cycle-guarded and deduplicated to the nearest path per node. Structural relation is not proof of data flow.';
REVOKE ALL ON FUNCTION "public"."bob_atlas_fk_reach"(p_from_type text, p_from_name text, p_max_depth integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."bob_atlas_fk_reach"(p_from_type text, p_from_name text, p_max_depth integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."bob_atlas_fk_reach"(p_from_type text, p_from_name text, p_max_depth integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."bob_atlas_flow_reach"(p_from_type text, p_from_name text, p_direction text DEFAULT 'downstream'::text, p_max_depth integer DEFAULT 8)
 RETURNS TABLE(entity_type text, entity_name text, depth integer, edge_kind text, path text[])
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with recursive walk as (
    -- Seed: the origin node itself, depth 0.
    select
      p_from_type::text as entity_type,
      p_from_name::text as entity_name,
      0                 as depth,
      null::text        as edge_kind,
      array[p_from_type || ':' || p_from_name]::text[] as path
    union all
    select
      case when p_direction = 'upstream' then e.source_type else e.target_type end,
      case when p_direction = 'upstream' then e.source_name else e.target_name end,
      w.depth + 1,
      e.edge_kind,
      w.path || (
        (case when p_direction = 'upstream' then e.source_type else e.target_type end)
        || ':' ||
        (case when p_direction = 'upstream' then e.source_name else e.target_name end)
      )
    from walk w
    join public.bob_app_map_edges e
      on e.retirement_status = 'live'
     and e.edge_kind in ('writes','reads','calls','invokes')
     and (
           (p_direction = 'upstream'
              and e.target_type = w.entity_type and e.target_name = w.entity_name)
        or (p_direction <> 'upstream'
              and e.source_type = w.entity_type and e.source_name = w.entity_name)
         )
    where w.depth < least(p_max_depth, 20)
      -- cycle guard: do not revisit a node already on this path (#313 M1)
      and not (
        (case when p_direction = 'upstream' then e.source_type else e.target_type end)
        || ':' ||
        (case when p_direction = 'upstream' then e.source_name else e.target_name end)
      ) = any(w.path)
  )
  select entity_type, entity_name, depth, edge_kind, path
  from walk
  where depth > 0
$function$;
COMMENT ON FUNCTION "public"."bob_atlas_flow_reach"(p_from_type text, p_from_name text, p_direction text, p_max_depth integer) IS 'Atlas blast-radius: directed data-FLOW reachability (writes/reads/calls/invokes) from a node, live edges only, cycle-guarded + depth-capped. FLOW only - never conflate with FK relation (bob_atlas_fk_reach).';
REVOKE ALL ON FUNCTION "public"."bob_atlas_flow_reach"(p_from_type text, p_from_name text, p_direction text, p_max_depth integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."bob_atlas_flow_reach"(p_from_type text, p_from_name text, p_direction text, p_max_depth integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."bob_atlas_flow_reach"(p_from_type text, p_from_name text, p_direction text, p_max_depth integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."bob_atlas_gap_report"(p_limit integer DEFAULT 200, p_offset integer DEFAULT 0, p_include_columns boolean DEFAULT false, p_include_unknown_exercise boolean DEFAULT false)
 RETURNS TABLE(entity_type text, entity_name text, gap_kind text, present boolean, wired boolean, exercised boolean, caller_summary text, notes text, retirement_status text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    c.entity_type,
    c.entity_name,
    case
      when c.present = true and c.wired = false then 'unwired'
      when c.present = true and c.exercised = false then 'unexercised'
      else 'exercise_unknown'
    end as gap_kind,
    c.present,
    c.wired,
    c.exercised,
    c.caller_summary,
    c.notes,
    c.retirement_status
  from public.bob_capability_map c
  where c.retirement_status = 'live'
    and c.present = true
    and (coalesce(p_include_columns, false) or c.entity_type <> 'column')
    and (
      c.wired = false
      or c.exercised = false
      or (coalesce(p_include_unknown_exercise, false) and c.exercised is null)
    )
  order by c.entity_type, c.entity_name
  limit greatest(1, least(coalesce(p_limit, 200), 500))
  offset greatest(0, coalesce(p_offset, 0));
$function$;
COMMENT ON FUNCTION "public"."bob_atlas_gap_report"(p_limit integer, p_offset integer, p_include_columns boolean, p_include_unknown_exercise boolean) IS 'Atlas operational gaps: live, present, but unwired or explicitly unexercised capabilities. Columns and unknown exercise state are opt-in diagnostics because static refresh cannot infer runtime execution.';
REVOKE ALL ON FUNCTION "public"."bob_atlas_gap_report"(p_limit integer, p_offset integer, p_include_columns boolean, p_include_unknown_exercise boolean) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."bob_atlas_gap_report"(p_limit integer, p_offset integer, p_include_columns boolean, p_include_unknown_exercise boolean) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."bob_atlas_gap_report"(p_limit integer, p_offset integer, p_include_columns boolean, p_include_unknown_exercise boolean) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."bob_cards_needing_embedding"(match_limit integer DEFAULT 25)
 RETURNS TABLE(id uuid, title text, content text)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select c.id, c.title, c.content
  from public.bob_knowledge_cards c
  where c.is_active
    and (
      c.embedding is null
      or c.embedded_at is null
      or c.embedded_at < c.updated_at
