  order by c.embedded_at asc nulls first, c.updated_at asc
  limit greatest(1, least(match_limit, 100));
$function$;
COMMENT ON FUNCTION "public"."bob_cards_needing_embedding"(match_limit integer) IS 'Bob RAG embed backfill: active cards that are new or whose content changed since last embed (embedding IS NULL OR embedded_at IS NULL OR embedded_at < updated_at). Stalest-first. Service-role only.';
