CREATE OR REPLACE FUNCTION "public"."bob_execute_read_query"(query_text text, row_limit integer DEFAULT 200, timeout_ms integer DEFAULT 5000)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  cleaned text;
  lowered text;
  wrapped text;
  result jsonb;
begin
  cleaned := btrim(query_text);
  -- Strip a single trailing semicolon (allowed), then forbid any remaining one
  -- (blocks statement chaining / injection of a second statement).
  cleaned := regexp_replace(cleaned, ';\s*$', '');
  if position(';' in cleaned) > 0 then
    raise exception 'Only a single statement is allowed';
  end if;

  lowered := lower(cleaned);
  -- Must be a read: single SELECT or a CTE that ends in SELECT.
  if left(lowered, 6) <> 'select' and left(lowered, 4) <> 'with' then
    raise exception 'Only SELECT / WITH...SELECT queries are allowed';
  end if;
  -- Belt-and-braces keyword denylist (the READ ONLY tx is the real guard).
  if lowered ~ '\y(insert|update|delete|drop|alter|create|truncate|grant|revoke|comment|copy|merge|call|do|vacuum|analyze|reindex|refresh|set|reset)\y' then
    raise exception 'Write / DDL / session keywords are not permitted';
  end if;

  row_limit := greatest(1, least(coalesce(row_limit, 200), 2000));
  perform set_config('statement_timeout', greatest(1000, least(coalesce(timeout_ms, 5000), 20000))::text, true);

  -- Wrap in a read-only subquery with a hard row cap; aggregate queries just
  -- return their single row.
  wrapped := format('select coalesce(jsonb_agg(t), ''[]''::jsonb) from (select * from (%s) q limit %s) t', cleaned, row_limit);

  -- READ ONLY transaction block: any attempted write raises 25006.
  begin
    set transaction read only;
  exception when others then
    -- already in a read-only-capable context; ignore
    null;
  end;

  execute wrapped into result;
  return jsonb_build_object('ok', true, 'rows', coalesce(result, '[]'::jsonb), 'row_limit', row_limit);
exception when others then
  return jsonb_build_object('ok', false, 'error', sqlerrm);
end;
$function$;
COMMENT ON FUNCTION "public"."bob_execute_read_query"(query_text text, row_limit integer, timeout_ms integer) IS 'Admiral-only read-only SQL for Bob. SELECT/WITH-SELECT only, single statement, row-capped, statement-timeout, executed read-only. Called by the bob-sql-read edge function AFTER it verifies the caller is grand_master. service_role execute only.';
REVOKE ALL ON FUNCTION "public"."bob_execute_read_query"(query_text text, row_limit integer, timeout_ms integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."bob_execute_read_query"(query_text text, row_limit integer, timeout_ms integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."bob_execute_read_query"(query_text text, row_limit integer, timeout_ms integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."bob_execute_read_query_scoped"(query_text text, row_limit integer DEFAULT 50, timeout_ms integer DEFAULT 5000)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  cleaned text;
  lowered text;
  wrapped text;
  result jsonb;
begin
  -- Apply per-call statement timeout (local to this transaction).
  perform set_config(
    'statement_timeout',
    greatest(1000, least(coalesce(timeout_ms, 5000), 20000))::text,
    true
  );

  -- Force read-only transaction so writes are physically impossible.
  set local transaction read only;

  cleaned := btrim(query_text);
  -- Strip a single trailing semicolon, then forbid any remaining one
  -- (blocks statement chaining / injection of a second statement).
  cleaned := regexp_replace(cleaned, ';\s*$', '');
  if position(';' in cleaned) > 0 then
    raise exception 'Only a single statement is allowed';
  end if;

  lowered := lower(cleaned);
  -- Must be a read: single SELECT or a CTE that ends in SELECT.
  if left(lowered, 6) <> 'select' and left(lowered, 4) <> 'with' then
    raise exception 'Only SELECT / WITH...SELECT queries are allowed';
  end if;

  -- Belt-and-braces keyword denylist (the READ ONLY tx is the real guard).
  if lowered ~ '\y(insert|update|delete|drop|alter|create|truncate|grant|revoke|copy|vacuum|analyze|reindex|refresh)\y' then
    raise exception 'Write / DDL / session keywords are not permitted';
  end if;

  row_limit := greatest(1, least(coalesce(row_limit, 50), 2000));

  -- Wrap in a subquery with a hard row cap; aggregate queries just
  -- return their single row. RLS is enforced because this function
  -- is SECURITY INVOKER -- the caller''s role policies apply.
  wrapped := format(
    'select coalesce(jsonb_agg(t), ''[]''::jsonb) from (select * from (%s) q limit %s) t',
    cleaned,
    row_limit
  );

  execute wrapped into result;

  return jsonb_build_object(
    'ok', true,
    'rows', coalesce(result, '[]'::jsonb),
    'row_limit', row_limit
  );
exception when others then
  return jsonb_build_object('ok', false, 'error', sqlerrm);
end;
$function$;
COMMENT ON FUNCTION "public"."bob_execute_read_query_scoped"(query_text text, row_limit integer, timeout_ms integer) IS 'Non-admiral read-only SQL for Bob (security invoker -- RLS applies). SELECT/WITH-SELECT only, single statement, row-capped, statement-timeout, executed read-only. Called by bob-sql-read edge function via callerClient (anon key + user JWT) for captain/commander tiers. Epic #185 E4 (#189).';
REVOKE ALL ON FUNCTION "public"."bob_execute_read_query_scoped"(query_text text, row_limit integer, timeout_ms integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."bob_execute_read_query_scoped"(query_text text, row_limit integer, timeout_ms integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."bob_execute_read_query_scoped"(query_text text, row_limit integer, timeout_ms integer) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."bob_execute_read_query_scoped"(query_text text, row_limit integer, timeout_ms integer) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."bob_execute_read_query_scoped"(query_text text, row_limit integer, timeout_ms integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."bob_friction_packets_immutable_envelope"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if OLD.envelope is distinct from NEW.envelope then
    raise exception 'envelope column is immutable once written'
      using errcode = 'restrict_violation';
  end if;
  return NEW;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."bob_friction_packets_immutable_envelope"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."bob_friction_packets_immutable_envelope"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."bob_friction_packets_immutable_envelope"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."bob_friction_packets_immutable_envelope"() TO "anon";
GRANT EXECUTE ON FUNCTION "public"."bob_friction_packets_immutable_envelope"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."bob_friction_packets_immutable_envelope"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."bob_friction_packets_stamp_review"()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if NEW.disposition is distinct from OLD.disposition or NEW.review_note is distinct from OLD.review_note then
    NEW.reviewed_by := auth.uid();
    NEW.reviewed_at := now();
  elsif auth.role() <> 'service_role' then
    NEW.reviewed_by := OLD.reviewed_by;
    NEW.reviewed_at := OLD.reviewed_at;
  end if;
  return NEW;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."bob_friction_packets_stamp_review"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."bob_friction_packets_stamp_review"() TO "postgres";
