END;
$function$;
REVOKE ALL ON FUNCTION "public"."bob_laptop_link_touch"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."bob_laptop_link_touch"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."bob_laptop_link_touch"() TO "postgres";
