CREATE OR REPLACE FUNCTION "public"."bob_match_knowledge"(query_embedding vector, match_count integer DEFAULT 5, scope_org_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, category text, key text, title text, content text, tags text[], similarity double precision)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    c.id, c.category, c.key, c.title, c.content, c.tags,
    1 - (c.embedding <=> query_embedding) as similarity
  from public.bob_knowledge_cards c
  where c.is_active
    and c.embedding is not null
    and (c.organization_id is null or c.organization_id = scope_org_id)
  order by c.embedding <=> query_embedding
  limit greatest(1, least(match_count, 20));
$function$;
COMMENT ON FUNCTION "public"."bob_match_knowledge"(query_embedding vector, match_count integer, scope_org_id uuid) IS 'Semantic knowledge retrieval for Bob RAG. Returns closest active cards by cosine similarity to the query embedding, scoped to platform-canonical + the caller''s org cards. Read-only.';
REVOKE ALL ON FUNCTION "public"."bob_match_knowledge"(query_embedding vector, match_count integer, scope_org_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."bob_match_knowledge"(query_embedding vector, match_count integer, scope_org_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."bob_match_knowledge"(query_embedding vector, match_count integer, scope_org_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."bob_match_knowledge_for_assistant_384"(in_query_embedding vector, in_match_threshold double precision DEFAULT 0.72, in_match_count integer DEFAULT 8, in_org_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, organization_id uuid, category text, key text, title text, content text, tags text[], source text, similarity double precision)
 LANGUAGE sql
 STABLE
AS $function$
  SELECT
    c.id,
    c.organization_id,
    c.category,
    c.key,
    c.title,
    c.content,
    c.tags,
    c.source,
    1 - (c.embedding_384 <=> in_query_embedding) AS similarity
  FROM public.bob_knowledge_cards c
  WHERE c.is_active = true
    AND c.embedding_384 IS NOT NULL
    AND (
      c.organization_id = in_org_id
      OR c.organization_id IS NULL
    )
    AND 1 - (c.embedding_384 <=> in_query_embedding) >= in_match_threshold
  ORDER BY c.embedding_384 <=> in_query_embedding
  LIMIT GREATEST(in_match_count, 1);
$function$;
REVOKE ALL ON FUNCTION "public"."bob_match_knowledge_for_assistant_384"(in_query_embedding vector, in_match_threshold double precision, in_match_count integer, in_org_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."bob_match_knowledge_for_assistant_384"(in_query_embedding vector, in_match_threshold double precision, in_match_count integer, in_org_id uuid) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."bob_match_knowledge_for_assistant_384"(in_query_embedding vector, in_match_threshold double precision, in_match_count integer, in_org_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."bob_match_knowledge_for_assistant_384"(in_query_embedding vector, in_match_threshold double precision, in_match_count integer, in_org_id uuid) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."bob_match_knowledge_for_assistant_384"(in_query_embedding vector, in_match_threshold double precision, in_match_count integer, in_org_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."bob_match_knowledge_for_assistant_384"(in_query_embedding vector, in_match_threshold double precision, in_match_count integer, in_org_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."bob_recall_prior_context"(search_terms text, scope_org_id uuid DEFAULT NULL::uuid, max_results integer DEFAULT 15, lookback_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_results jsonb := '[]'::jsonb;
  v_rulings jsonb;
  v_learnings jsonb;
  v_derived jsonb;
  v_events jsonb;
  v_jobs jsonb;
  v_cutoff timestamptz;
  v_terms text;
begin
  -- Sanitise inputs
  v_terms := lower(btrim(coalesce(search_terms, '')));
  if v_terms = '' then
    return jsonb_build_object(
      'ok', false,
      'error', 'search_terms is required'
    );
  end if;

  max_results := greatest(1, least(coalesce(max_results, 15), 50));
  lookback_days := greatest(1, least(coalesce(lookback_days, 30), 365));
  v_cutoff := now() - (lookback_days || ' days')::interval;

  -- 1. Owner rulings (highest authority, always included)
  select coalesce(jsonb_agg(r order by r.created_at desc), '[]'::jsonb)
  into v_rulings
  from (
    select
      'owner_ruling'::text as source_type,
      id,
      ruling_key as key,
      title,
      ruling_text as content,
      domain as category,
      1.0::double precision as authority,
      created_at
    from public.bob_owner_rulings
    where ruling_status = 'active'
      and (
        lower(ruling_text) like '%' || v_terms || '%'
        or lower(title) like '%' || v_terms || '%'
        or lower(ruling_key) like '%' || v_terms || '%'
        or lower(domain) like '%' || v_terms || '%'
      )
    limit least(max_results, 10)
  ) r;

  -- 2. Knowledge cards with relevant categories
  select coalesce(jsonb_agg(k order by k.created_at desc), '[]'::jsonb)
  into v_learnings
  from (
    select
      'knowledge_card'::text as source_type,
      id,
      key,
      title,
      content,
      category,
      0.8::double precision as authority,
      created_at
    from public.bob_knowledge_cards
    where is_active
      and category in ('learning', 'ruling', 'discipline', 'governance')
      and (organization_id is null or organization_id = scope_org_id)
      and (
        lower(content) like '%' || v_terms || '%'
        or lower(title) like '%' || v_terms || '%'
        or lower(key) like '%' || v_terms || '%'
      )
    limit least(max_results, 10)
  ) k;

  -- 3. Derived learnings (approved + auto_digest; proposed at lower authority)
  select coalesce(jsonb_agg(d order by d.created_at desc), '[]'::jsonb)
  into v_derived
  from (
    select
      'derived_learning'::text as source_type,
      id,
      learning_key as key,
      title,
      learning_text as content,
      learning_type as category,
      case
        when learning_status = 'approved' then 0.9::double precision
        when learning_status = 'auto_digest' then 0.3::double precision
        else 0.2::double precision  -- proposed
      end as authority,
      created_at
    from public.bob_learnings
    where learning_status in ('approved', 'auto_digest', 'proposed')
      and (
        lower(learning_text) like '%' || v_terms || '%'
        or lower(title) like '%' || v_terms || '%'
        or lower(learning_key) like '%' || v_terms || '%'
      )
    limit least(max_results, 10)
  ) d;

  -- 4. Recent event_log failures/outcomes (org-scoped)
  select coalesce(jsonb_agg(e order by e.created_at desc), '[]'::jsonb)
  into v_events
  from (
    select
      'event_log'::text as source_type,
      id,
      event_type as key,
      tool as title,
      outcome as content,
      event_type as category,
      0.5::double precision as authority,
      created_at
    from public.bob_event_log
    where created_at >= v_cutoff
      and (scope_org_id is null or organization_id = scope_org_id)
      and outcome is not null
      and (
        lower(coalesce(outcome, '')) like '%' || v_terms || '%'
        or lower(coalesce(tool, '')) like '%' || v_terms || '%'
        or lower(event_type) like '%' || v_terms || '%'
      )
    limit least(max_results, 10)
  ) e;

  -- 5. Recent job_runs outcomes (org-scoped)
  select coalesce(jsonb_agg(j order by j.created_at desc), '[]'::jsonb)
  into v_jobs
  from (
    select
      'job_run'::text as source_type,
      id,
      status as key,
      goal as title,
      stopped_reason as content,
      status as category,
      0.4::double precision as authority,
      created_at
    from public.bob_job_runs
    where created_at >= v_cutoff
      and (scope_org_id is null or organization_id = scope_org_id)
      and (
        lower(coalesce(goal, '')) like '%' || v_terms || '%'
        or lower(coalesce(stopped_reason, '')) like '%' || v_terms || '%'
        or lower(status) like '%' || v_terms || '%'
      )
    limit least(max_results, 10)
  ) j;

  -- Combine all results
  v_results := v_rulings || v_learnings || v_derived || v_events || v_jobs;

  return jsonb_build_object(
    'ok', true,
    'results', v_results,
    'counts', jsonb_build_object(
      'rulings', jsonb_array_length(v_rulings),
      'learnings', jsonb_array_length(v_learnings),
      'derived', jsonb_array_length(v_derived),
      'events', jsonb_array_length(v_events),
      'jobs', jsonb_array_length(v_jobs)
    ),
    'search_terms', search_terms,
    'lookback_days', lookback_days
  );
exception when others then
  return jsonb_build_object('ok', false, 'error', sqlerrm);
end;
$function$;
COMMENT ON FUNCTION "public"."bob_recall_prior_context"(search_terms text, scope_org_id uuid, max_results integer, lookback_days integer) IS 'Runtime retrieval for Bob: queries prior owner rulings, learnings, event-log outcomes, and job-run results matching search terms. Returns a unified result set ordered by authority (rulings > learnings > events > jobs). Bob calls this via sql_read or directly as an RPC before acting on a topic where prior context may exist. Read-only. Issue #232, epic #228.';
REVOKE ALL ON FUNCTION "public"."bob_recall_prior_context"(search_terms text, scope_org_id uuid, max_results integer, lookback_days integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."bob_recall_prior_context"(search_terms text, scope_org_id uuid, max_results integer, lookback_days integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."bob_recall_prior_context"(search_terms text, scope_org_id uuid, max_results integer, lookback_days integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."bob_search_reference_documents"(p_query text DEFAULT NULL::text, p_scope text DEFAULT 'both'::text, p_organization_id uuid DEFAULT NULL::uuid, p_document_type text DEFAULT NULL::text, p_jurisdiction text DEFAULT NULL::text, p_tags text[] DEFAULT NULL::text[], p_allow_restricted boolean DEFAULT false, p_limit integer DEFAULT 25)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_limit int := greatest(1, least(coalesce(p_limit, 25), 100));
  v_scope text := lower(coalesce(p_scope, 'both'));
  v_q text := nullif(btrim(coalesce(p_query, '')), '');
  result jsonb;
begin
  if v_scope not in ('tenant','global','both') then
    return jsonb_build_object('ok', false, 'error', 'scope must be tenant, global or both');
  end if;

  select coalesce(jsonb_agg(row_to_json(t)), '[]'::jsonb)
  into result
  from (
    select
      rce.id                as catalog_entry_id,
      rce.title,
      rce.topic,
      rce.publisher,
      rce.jurisdiction,
      rce.document_type,
      rce.trust_level,
      rce.searchable_tags,
      rce.is_global_reference,
      rce.organization_id,
      d.id                  as document_id,
      dv.id                 as document_version_id,
      dv.version_label,
      dv.effective_from,
      dv.effective_to,
      dc.privacy_class,
      dc.confidence         as classification_confidence,
      -- Approved retrieval handle only. Never a raw bucket path.
      ('docref:' || dv.id::text) as retrieval_handle
    from public.reference_catalog_entries rce
    join public.document_versions dv on dv.id = rce.document_version_id
    join public.documents d on d.id = dv.document_id
    left join lateral (
      select privacy_class, confidence
      from public.document_classifications c
      where c.document_version_id = dv.id
      order by c.created_at desc
      limit 1
    ) dc on true
    where rce.approval_status = 'approved'
      and d.current_scope <> 'quarantined'
      -- Scope filter
      and (
        (v_scope = 'global' and rce.is_global_reference)
        or (v_scope = 'tenant' and rce.organization_id is not distinct from p_organization_id and not rce.is_global_reference)
        or (v_scope = 'both' and (rce.is_global_reference
              or rce.organization_id is not distinct from p_organization_id))
      )
      -- Restricted / tenant_sensitive never surface unless explicitly authorized.
      and (
        p_allow_restricted
        or coalesce(dc.privacy_class, 'restricted') in ('public','internal_non_sensitive')
        or (rce.organization_id is not distinct from p_organization_id
            and coalesce(dc.privacy_class, 'restricted') = 'tenant_sensitive')
      )
      and (p_document_type is null or rce.document_type = p_document_type)
      and (p_jurisdiction is null or rce.jurisdiction = p_jurisdiction)
      and (p_tags is null or rce.searchable_tags && p_tags)
      and (
        v_q is null
        or rce.title ilike '%' || v_q || '%'
        or coalesce(rce.topic, '') ilike '%' || v_q || '%'
        or coalesce(dv.extracted_text, '') ilike '%' || v_q || '%'
      )
    order by rce.trust_level desc, rce.updated_at desc
    limit v_limit
  ) t;

  return jsonb_build_object('ok', true, 'results', coalesce(result, '[]'::jsonb), 'scope', v_scope, 'limit', v_limit);
exception when others then
  return jsonb_build_object('ok', false, 'error', sqlerrm);
end;
$function$;
COMMENT ON FUNCTION "public"."bob_search_reference_documents"(p_query text, p_scope text, p_organization_id uuid, p_document_type text, p_jurisdiction text, p_tags text[], p_allow_restricted boolean, p_limit integer) IS 'Mediated, policy-filtered retrieval over approved reference documents for Bob. Enforces tenant/global scope, excludes quarantined and (unless authorized) restricted/tenant_sensitive material, and returns summaries + approved retrieval handles only. service_role execute only; the edge function verifies caller scope first.';
REVOKE ALL ON FUNCTION "public"."bob_search_reference_documents"(p_query text, p_scope text, p_organization_id uuid, p_document_type text, p_jurisdiction text, p_tags text[], p_allow_restricted boolean, p_limit integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."bob_search_reference_documents"(p_query text, p_scope text, p_organization_id uuid, p_document_type text, p_jurisdiction text, p_tags text[], p_allow_restricted boolean, p_limit integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."bob_search_reference_documents"(p_query text, p_scope text, p_organization_id uuid, p_document_type text, p_jurisdiction text, p_tags text[], p_allow_restricted boolean, p_limit integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."bob_site_risk"(p_site_id uuid, p_radius_m integer DEFAULT 500, p_unrestricted boolean DEFAULT false, p_scope_org_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_site        client_sites%rowtype;
  v_point       geography;
  v_radius      integer := greatest(50, least(coalesce(p_radius_m, 500), 5000));
  v_now         timestamptz := now();
  v_signals     jsonb := '[]'::jsonb;
begin
  select * into v_site from client_sites where id = p_site_id;
  if not found then
    return jsonb_build_object('success', false, 'error', 'site_not_found');
  end if;

  if v_site.center_point is not null then
    v_point := v_site.center_point::geography;
  elsif v_site.gps_lat is not null and v_site.gps_lng is not null then
    v_point := st_setsrid(st_makepoint(v_site.gps_lng, v_site.gps_lat), 4326)::geography;
  else
    v_point := null;
  end if;

  with sources as (
    select 'observation'::text as source, 'intrinsic'::text as scope,
           o.organization_id, coalesce(nullif(o.compliance_reason,''),'observation')::text as severity_hint,
           o.observed_at as occurred_at, null::numeric as distance_m,
           o.plate_number::text as detail
    from observations o
    where o.site_id = p_site_id

    union all

    select 'observation'::text, 'proximity'::text, o.organization_id, coalesce(nullif(o.compliance_reason,''),'observation')::text,
           o.observed_at,
           round(st_distance(o.gps_point::geography, v_point)::numeric, 0),
           o.plate_number::text
    from observations o
    where v_point is not null and o.site_id is distinct from p_site_id
      and o.gps_point is not null
      and st_dwithin(o.gps_point::geography, v_point, v_radius)

    union all

    select 'incident'::text,
           case when i.client_site_id = p_site_id then 'intrinsic' else 'proximity' end::text,
           i.organization_id, i.severity::text, i.occurred_at,
           round(st_distance(
             case when ics.center_point is not null then ics.center_point::geography
                  else st_setsrid(st_makepoint(ics.gps_lng, ics.gps_lat),4326)::geography end,
             v_point)::numeric, 0) as distance_m,
           i.incident_type::text
    from incidents i
    join client_sites ics on ics.id = i.client_site_id
    where v_point is not null
      and (ics.center_point is not null
           or (ics.gps_lat is not null and ics.gps_lng is not null))
      and st_dwithin(
            case when ics.center_point is not null then ics.center_point::geography
                 else st_setsrid(st_makepoint(ics.gps_lng, ics.gps_lat),4326)::geography end,
            v_point, v_radius)

    union all

    select 'field_report'::text, case when r.site_id = p_site_id then 'intrinsic' else 'proximity' end::text,
           r.organization_id, r.severity::text, r.reported_at,
           case when r.gps_lat is null then null
                else round(st_distance(st_setsrid(st_makepoint(r.gps_lng, r.gps_lat),4326)::geography, v_point)::numeric,0) end,
           r.report_type::text
    from officer_field_reports r
    where (r.site_id = p_site_id)
       or (v_point is not null and r.gps_lat is not null
           and st_dwithin(st_setsrid(st_makepoint(r.gps_lng, r.gps_lat),4326)::geography, v_point, v_radius))

    union all

    select case ef.entity_type
             when 'place' then 'location_flag'
             when 'vehicle' then 'vehicle_flag'
             else 'entity_flag'
           end::text,
           case when ef.entity_type = 'place' and ef.entity_id = p_site_id then 'intrinsic'
                else 'proximity' end::text,
           ef.organization_id, ef.alert_level::text, ef.raised_at,
           case when ef.entity_type = 'place' then
             (select round(st_distance(
               case when efs.center_point is not null then efs.center_point::geography
                    else st_setsrid(st_makepoint(efs.gps_lng, efs.gps_lat),4326)::geography end,
               v_point)::numeric, 0)
              from client_sites efs where efs.id = ef.entity_id
                and (efs.center_point is not null or (efs.gps_lat is not null and efs.gps_lng is not null)))
           else null end,
           ef.flag_type::text
    from entity_flags ef
    where ef.active
      and ((ef.entity_type = 'place' and ef.entity_id = p_site_id)
        or (ef.entity_type = 'place' and v_point is not null
            and exists (
              select 1 from client_sites efs
              where efs.id = ef.entity_id
                and (efs.center_point is not null or (efs.gps_lat is not null and efs.gps_lng is not null))
                and st_dwithin(
                  case when efs.center_point is not null then efs.center_point::geography
                       else st_setsrid(st_makepoint(efs.gps_lng, efs.gps_lat),4326)::geography end,
                  v_point, v_radius)))
        or (ef.entity_type in ('vehicle', 'person', 'staff')))

    union all

    select 'welfare_alert'::text, 'proximity'::text, wa.organization_id, wa.alert_type::text, wa.triggered_at,
           case when wa.gps_lat is null then null
                else round(st_distance(st_setsrid(st_makepoint(wa.gps_lng, wa.gps_lat),4326)::geography, v_point)::numeric,0) end,
           wa.alert_type::text
    from welfare_alerts wa
    where v_point is not null and wa.gps_lat is not null
      and st_dwithin(st_setsrid(st_makepoint(wa.gps_lng, wa.gps_lat),4326)::geography, v_point, v_radius)

    union all
    select 'noise_assessment'::text, 'intrinsic'::text, n.organization_id,
           (case when n.hs_flag_active then 'high' else 'low' end)::text, n.assessed_at, null, n.noise_source::text
    from noise_assessments n where n.site_id = p_site_id

    union all
    select 'smoke_assessment'::text, 'intrinsic'::text, sm.organization_id, coalesce(sm.severity::text,'low')::text, sm.assessed_at, null, sm.smoke_source_type::text
    from smoke_assessments sm where sm.site_id = p_site_id

    union all
    select 'biosecurity_assessment'::text, 'intrinsic'::text, b.organization_id, 'low'::text, b.assessed_at, null, b.species_identified::text
    from biosecurity_assessments b where b.site_id = p_site_id
  ),
  banded as (
    select *,
      case when occurred_at >= v_now - interval '7 days'  then 'active'
           when occurred_at >= v_now - interval '28 days' then 'monitor'
           else 'history' end as band,
      (p_unrestricted
        or p_scope_org_ids is null
        or organization_id = any(p_scope_org_ids)) as in_scope
    from sources
    where occurred_at is not null
  )
  select jsonb_agg(
    jsonb_build_object(
      'source', source,
      'scope', scope,
      'band', band,
      'severity', severity_hint,
      'occurred_at', occurred_at,
      'distance_m', distance_m,
      'in_scope', in_scope,
      'detail', case when in_scope then detail else null end,
      'identity_withheld', (not in_scope)
    )
    order by occurred_at desc
  )
  into v_signals
  from banded;

  return jsonb_build_object(
    'success', true,
    'site_id', p_site_id,
    'site_name', v_site.name,
    'has_point', (v_point is not null),
    'radius_m', v_radius,
    'generated_at', v_now,
    'signals', coalesce(v_signals, '[]'::jsonb)
  );
end;
$function$;
REVOKE ALL ON FUNCTION "public"."bob_site_risk"(p_site_id uuid, p_radius_m integer, p_unrestricted boolean, p_scope_org_ids uuid[]) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."bob_site_risk"(p_site_id uuid, p_radius_m integer, p_unrestricted boolean, p_scope_org_ids uuid[]) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."bob_site_risk"(p_site_id uuid, p_radius_m integer, p_unrestricted boolean, p_scope_org_ids uuid[]) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."build_agreement_activity_report"(p_service_agreement_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_max_lines integer DEFAULT 2000)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
with core as (
  select public.build_agreement_activity_report_core(p_service_agreement_id,p_from,p_to,p_max_lines) as j
), agreement as (
  select provider_organization_id,client_organization_id from public.service_agreements where id=p_service_agreement_id
), client_returns as (
  select h.hunting_area,h.return_type,h.animals,h.total_animals,h.hunt_date
  from public.hunter_kill_returns h join agreement a
    on h.organization_id=a.provider_organization_id and h.client_organization_id=a.client_organization_id
  where h.withdrawn_at is null
), in_window as (
  select c.* from client_returns c
  where (c.hunt_date::timestamp at time zone 'Pacific/Auckland')>=p_from
    and (c.hunt_date::timestamp at time zone 'Pacific/Auckland')<p_to
), species as (
  select a->>'species' as species,sum((a->>'count')::integer)::integer as animals,count(*)::integer as returns
  from in_window w cross join lateral jsonb_array_elements(w.animals) a group by 1
), areas as (
  select w.hunting_area as area,count(*)::integer as returns,
    count(*) filter(where w.return_type='kill')::integer as kill,
    count(*) filter(where w.return_type='nil')::integer as nil,sum(w.total_animals)::integer as animals
  from in_window w group by 1
), summary as (
  select jsonb_build_object(
    'source','Hunter-submitted returns (RAMS)','returns',(select count(*) from in_window),
    'killReturns',(select count(*) from in_window where return_type='kill'),
    'nilReturns',(select count(*) from in_window where return_type='nil'),
    'animals',(select coalesce(sum(total_animals),0) from in_window),
    'bySpecies',coalesce((select jsonb_agg(jsonb_build_object('species',s.species,'animals',s.animals,'returns',s.returns)
      order by s.animals desc,s.species) from species s),'[]'::jsonb),
    'byArea',coalesce((select jsonb_agg(jsonb_build_object('area',ar.area,'returns',ar.returns,'kill',ar.kill,'nil',ar.nil,'animals',ar.animals)
      order by ar.animals desc,ar.returns desc,ar.area) from areas ar),'[]'::jsonb)
  ) as s
), base as (
  select case when core.j->'report' is null or not exists(select 1 from client_returns) then core.j
    else jsonb_set(core.j,'{report,hunterReturns}',(select s from summary)) end as j from core
)
select case when base.j->'report' is null then base.j else jsonb_set(base.j,'{report,serviceDelivery}',
  public.report_service_delivery_summary(p_service_agreement_id,p_from,p_to)->'client') end
from base;
$function$;
COMMENT ON FUNCTION "public"."build_agreement_activity_report"(p_service_agreement_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_max_lines integer) IS 'Internal assembler for the R&M month-end site activity report. Wraps build_agreement_activity_report_core and, for clients with Base44 RAMS hunter returns, adds report.hunterReturns: return counts and animals by species and hunting area for hunt dates in the window (Pacific/Auckland). Hunter names, emails, permits and comments are never copied. Auth is on generate_due_report_packs and get_report_pack_activity_accounting.';
REVOKE ALL ON FUNCTION "public"."build_agreement_activity_report"(p_service_agreement_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_max_lines integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."build_agreement_activity_report"(p_service_agreement_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_max_lines integer) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."build_agreement_activity_report_core"(p_service_agreement_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_max_lines integer DEFAULT 2000)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
with
params as materialized (
	select greatest(0, least(coalesce(p_max_lines, 2000), 5000)) as max_lines
),
agreement as materialized (
	select a.provider_organization_id, a.client_organization_id
	from public.service_agreements a
	where a.id = p_service_agreement_id
),
links as materialized (
	select l.id as link_id, l.site_id, l.zone_id,
		coalesce(s.name, z.name, 'Unnamed place') as place_name
	from public.service_agreement_locations l
	left join public.client_sites s on s.id = l.site_id
	left join public.location_zones z on z.id = l.zone_id
	where l.service_agreement_id = p_service_agreement_id
		and l.status = 'active'
),
event_scope as materialized (
	select e.id, e.occurred_at, e.event_type, e.source, e.module_key, e.payload, e.observed_entity_id, pl.place_name
	from public.location_events e
	cross join lateral (
		select k.place_name
		from links k
		where (k.zone_id is not null and k.zone_id = e.zone_id)
			or (k.site_id is not null and k.site_id = e.client_site_id)
		order by k.place_name, k.link_id
		limit 1
	) pl
	where e.occurred_at >= p_from
		and e.occurred_at < p_to
),
observation_scope as materialized (
	select o.id, o.observed_at, o.module_key, o.officer_notes, o.officer_id,
		case when jsonb_typeof(o.external_refs -> 'import') = 'object' then o.external_refs -> 'import' else '{}'::jsonb end as imported,
		array_remove(array[
			nullif(btrim(o.watermarked_photo_url), ''),
			nullif(btrim(o.original_photo_url), ''),
			nullif(btrim(o.photo_url), '')
		], null) as direct_photo_paths,
		pl.place_name
	from public.observations o
	cross join lateral (
		select k.place_name
		from links k
		where (k.zone_id is not null and k.zone_id = o.zone_id)
			or (k.site_id is not null and k.site_id = o.site_id)
		order by k.place_name, k.link_id
		limit 1
	) pl
	where o.observed_at >= p_from
		and o.observed_at < p_to
),
work_order_scope as materialized (
	select w.id, w.kind, w.status, w.order_number, w.title, w.description, w.completion_note,
		coalesce(w.completed_at, w.started_at, w.scheduled_for, w.created_at) as at,
		public.report_code_or_null(subject.code) as subject,
		public.report_code_or_null(activity.code) as activity,
		pl.place_name
	from public.workshop_work_orders w
	join agreement a on a.provider_organization_id = w.organization_id
	left join public.reference_codes subject on subject.id = w.work_subject_code_id
		and subject.organization_id = a.provider_organization_id and subject.code_type = 'work_subject'
	left join public.reference_codes activity on activity.id = w.work_activity_code_id
		and activity.organization_id = a.provider_organization_id and activity.code_type = 'work_activity'
	left join lateral (
		select k.place_name
		from links k
		where (k.zone_id is not null and k.zone_id = w.zone_id)
			or (k.site_id is not null and k.site_id = w.client_site_id)
		order by k.place_name, k.link_id
		limit 1
	) pl on true
	where w.status in ('approved', 'in_progress', 'completed')
		and (w.service_agreement_id = p_service_agreement_id or pl.place_name is not null)
		and coalesce(w.completed_at, w.started_at, w.scheduled_for, w.created_at) >= p_from
		and coalesce(w.completed_at, w.started_at, w.scheduled_for, w.created_at) < p_to
),
incident_scope as materialized (
	select i.id, i.occurred_at, i.incident_type, i.severity, i.status, i.description, i.location_event_id,
		inv.investigation_reference, inv.status as investigation_status, pl.place_name
	from public.incidents i
	join agreement a on i.organization_id in (a.provider_organization_id, a.client_organization_id)
	cross join lateral (
		select k.place_name
		from links k
		where (k.zone_id is not null and k.zone_id = i.zone_id)
			or (k.site_id is not null and k.site_id = i.client_site_id)
		order by k.place_name, k.link_id
		limit 1
	) pl
	left join public.investigations inv on inv.id = i.investigation_id
		and inv.organization_id in (a.provider_organization_id, a.client_organization_id)
	where i.occurred_at >= p_from
		and i.occurred_at < p_to
		and not i.is_staff_sensitive
),
-- One row per stored photo per entry. Observation photo variants (watermarked,
-- original, captured) are one photo; evidence items carry no bucket column, so
-- they are read from bob-uploads unless they are an observation's own photo.
photo_refs as materialized (
	select distinct on (r.record_id, r.path) r.record_id, r.bucket, r.path, r.captured_at
	from (
		select i.location_event_id as record_id, 'bob-uploads'::text as bucket, i.storage_path as path, i.captured_at, 3 as priority
		from public.evidence_items i
		join event_scope e on e.id = i.location_event_id
		where i.evidence_kind = 'photo'
			and i.storage_path is not null
			and not public.report_photo_name_withheld(i.metadata ->> 'original_name')
		union all
		select o.id,
			case when s.storage_path = any(o.direct_photo_paths) then 'scans' else s.storage_bucket end,
			case when s.storage_path = any(o.direct_photo_paths) then o.direct_photo_paths[1] else s.storage_path end,
			s.captured_at, 1
		from public.observation_supporting_evidence s
		join observation_scope o on o.id = s.observation_id
		where s.evidence_kind = 'external_photo'
			and s.storage_path is not null
			and not public.report_photo_name_withheld(s.storage_path)
		union all
		select o.id,
			case when i.storage_path = any(o.direct_photo_paths) then 'scans' else 'bob-uploads' end,
			case when i.storage_path = any(o.direct_photo_paths) then o.direct_photo_paths[1] else i.storage_path end,
			i.captured_at, 3
		from public.evidence_items i
		join observation_scope o on o.id::text = i.metadata ->> 'observation_id'
		where i.evidence_kind = 'photo'
			and i.storage_path is not null
			and not public.report_photo_name_withheld(i.metadata ->> 'original_name')
		union all
		select o.id, 'scans', o.direct_photo_paths[1], o.observed_at, 2
		from observation_scope o
		where cardinality(o.direct_photo_paths) > 0
		union all
		select n.id, 'bob-uploads', i.storage_path, i.captured_at, 3
		from incident_scope n
		join public.incident_attachments a on a.incident_id = n.id and a.attachment_kind = 'photo'
		join public.evidence_items i on i.id = a.evidence_item_id
		where i.storage_path is not null
			and not public.report_photo_name_withheld(i.metadata ->> 'original_name')
		union all
		select n.id, 'bob-uploads', i.storage_path, i.captured_at, 3
		from incident_scope n
		join public.evidence_items i on i.location_event_id = n.location_event_id
		where i.evidence_kind = 'photo'
			and i.storage_path is not null
			and not public.report_photo_name_withheld(i.metadata ->> 'original_name')
	) r
	where not public.report_photo_name_withheld(r.path)
	order by r.record_id, r.path, r.priority
),
photo_ranked as (
	select r.record_id, r.bucket, r.path,
		r.path ~* '^[a-z][a-z0-9+.-]*://' as external_url,
		row_number() over (
			partition by r.record_id, r.path ~* '^[a-z][a-z0-9+.-]*://'
			order by r.captured_at, r.path
		) as rn
	from photo_refs r
),
photo_counts as (
	select p.record_id, count(*) as n,
		jsonb_agg(jsonb_build_object('b', p.bucket, 'p', p.path) order by p.rn)
			filter (where not p.external_url and p.rn <= 4) as refs
	from photo_ranked p
	group by p.record_id
),
incident_videos as (
	select a.incident_id as record_id, count(distinct coalesce(a.evidence_item_id, a.id)) as n
	from public.incident_attachments a
	join incident_scope n on n.id = a.incident_id
	where a.attachment_kind = 'video'
	group by a.incident_id
),
acts_base as materialized (
	select e.id as record_id, 'event'::text as kind, e.occurred_at as at, e.place_name, e.module_key,
		e.event_type,
		public.report_service_line(e.payload ->> 'source_category') as service_line,
		public.report_code_or_null(e.payload ->> 'work_subject_code') as subject,
		public.report_code_or_null(e.payload ->> 'work_activity_code') as activity,
		public.report_code_or_null(e.payload ->> 'biosecurity_species_code') as species,
		public.report_code_or_null(e.payload ->> 'equipment_type_code') as equipment,
		public.report_code_or_null(e.payload ->> 'material_type_code') as material,
		case when e.payload ->> 'job_number' ~ '^[A-Za-z0-9._/-]{1,24}$' then e.payload ->> 'job_number' end as job,
		case when jsonb_typeof(e.payload -> 'materials_used') = 'array' then e.payload -> 'materials_used' else '[]'::jsonb end as materials,
		null::text as work_order_status,
		public.report_text_or_null(e.payload ->> 'issue', 80) as title,
		public.report_text_or_null(e.payload ->> 'comments', 1500) as note,
		public.report_text_or_null(e.payload ->> 'action_notes', 1500) as action,
		null::text as incident_type,
		null::text as severity,
		null::text as incident_status,
		null::text as investigation_ref,
		null::text as investigation_status
	from event_scope e
	where e.source is distinct from 'observation_trigger'
	union all
	select o.id, 'observation', o.observed_at, o.place_name, o.module_key,
		null::text,
		public.report_service_line(o.imported ->> 'source_category'),
		public.report_code_or_null(o.imported ->> 'work_subject_code'),
		public.report_code_or_null(o.imported ->> 'work_activity_code'),
		public.report_code_or_null(o.imported ->> 'biosecurity_species_code'),
		public.report_code_or_null(o.imported ->> 'equipment_type_code'),
		public.report_code_or_null(o.imported ->> 'material_type_code'),
		case when o.imported ->> 'job_number' ~ '^[A-Za-z0-9._/-]{1,24}$' then o.imported ->> 'job_number' end,
		case when jsonb_typeof(o.imported -> 'materials_used') = 'array' then o.imported -> 'materials_used' else '[]'::jsonb end,
		null::text,
		public.report_text_or_null(o.imported ->> 'issue', 80),
		coalesce(public.report_text_or_null(o.officer_notes, 1500), public.report_text_or_null(o.imported ->> 'comments', 1500)),
		public.report_text_or_null(o.imported ->> 'action_notes', 1500),
		null::text, null::text, null::text, null::text, null::text
	from observation_scope o
	union all
	select w.id, 'work_order', w.at, w.place_name, 'workshop',
		null::text,
		null::text,
		w.subject,
		coalesce(w.activity, case w.kind when 'maintenance' then 'maintenance' when 'fabrication' then 'manufacture' end),
		null::text,
		null::text,
		null::text,
		case when w.order_number ~ '^[A-Za-z0-9._/-]{1,24}$' then w.order_number end,
		'[]'::jsonb,
		w.status,
		public.report_text_or_null(w.title, 120),
		public.report_text_or_null(w.description, 1500),
		public.report_text_or_null(w.completion_note, 1500),
		null::text, null::text, null::text, null::text, null::text
	from work_order_scope w
	union all
	select n.id, 'incident', n.occurred_at, n.place_name, 'incident',
		null::text, null::text, null::text, null::text, null::text, null::text, null::text,
		null::text,
		'[]'::jsonb,
		null::text,
		null::text,
		public.report_text_or_null(n.description, 1500),
		null::text,
		public.report_code_or_null(n.incident_type),
		public.report_code_or_null(n.severity),
		public.report_code_or_null(n.status),
		case when n.investigation_reference ~ '^[A-Za-z0-9._/-]{1,32}$' then n.investigation_reference end,
		public.report_code_or_null(n.investigation_status)
	from incident_scope n
),
mats as (
	select a.record_id,
		public.report_code_or_null(m ->> 'material_type') as material_type,
		case
			when m ->> 'calibre' ~* '^(\.[0-9]{2,3}|[0-9]{1,2}(\.[0-9]{1,2})?mm)$' then lower(m ->> 'calibre')
			when m ? 'calibre' then 'unspecified'
		end as calibre,
		public.report_numeric_or_null(m ->> 'quantity') as quantity
	from acts_base a
	cross join lateral jsonb_array_elements(a.materials) m
	where jsonb_typeof(m) = 'object'
		and public.report_code_or_null(m ->> 'material_type') is not null
),
mat_lines as (
	select m.record_id,
		jsonb_agg(jsonb_strip_nulls(jsonb_build_object('t', m.material_type, 'cal', m.calibre, 'q', m.quantity))
			order by m.material_type, m.calibre, m.quantity) as materials
	from mats m
	group by m.record_id
),
acts as materialized (
	select a.record_id, a.kind, a.at, (a.at at time zone 'Pacific/Auckland')::date as local_date,
		to_char(a.at at time zone 'Pacific/Auckland', 'HH24:MI') as local_time,
		a.place_name, a.module_key, a.event_type, a.service_line, a.subject, a.activity, a.species,
		a.equipment, a.material, a.job, a.work_order_status, a.title, a.note, a.action,
		a.incident_type, a.severity, a.incident_status, a.investigation_ref, a.investigation_status,
		coalesce(pc.n, 0)::integer as photos, pc.refs as photo_refs, coalesce(iv.n, 0)::integer as videos,
		ml.materials as materials_used,
		c.category,
		-- Travel, materials and shift or movement markers are how the work was run,
		-- not what happened at the place, so the client report withholds them.
		-- Administration and desk entries are withheld too (owner ruling 2026-11-05,
		-- replacing the 2026-11-04 ruling that reported them). Photos and
		-- service-line classifications do not override this boundary.
		case
			when c.category = 'administration' then 'travel_admin'
			when a.activity in ('travel', 'administration', 'materials')
				or c.category = 'travel_admin' then 'travel_admin'
			when c.category in ('patrol_visit', 'other_work', 'unclassified')
				and regexp_replace(lower(coalesce(a.title, '')), '[^a-z]', '', 'g') in ('travel', 'admin', 'administration')
				then 'travel_admin'
			when c.category in ('patrol_visit', 'other_work', 'unclassified')
				and regexp_replace(lower(coalesce(a.note, '')), '[^a-z]', '', 'g') in (
					'start', 'finish', 'restart', 'home', 'enter', 'exit',
					'startshift', 'finishshift', 'endshift', 'shiftstart', 'shiftend', 'shiftfinish', 'endofshift'
				)
				then 'shift_marker'
			-- A card swap with nothing found is routine camera upkeep, not news for the client.
			when a.kind in ('event', 'observation')
				and coalesce(pc.n, 0) = 0
				and c.category <> 'incident'
				and regexp_replace(lower(coalesce(a.title, '')), '[^a-z]', '', 'g') in ('', 'card', 'cardreview', 'cardreplace', 'cardreplacement', 'cardchange', 'cardswap', 'replacecard')
				and btrim(regexp_replace(lower(concat_ws(' ', a.note, a.action)), '[^a-z]+', ' ', 'g')) ~ '^((sd )?cards? (replaced|replace|swapped|swap|changed|change)|(replaced|replace|swapped|swap|changed|change|new) (sd )?cards?)( (replaced|swapped|changed))?$'
				then 'routine_card'
			-- The same entry recorded twice: same local minute, place, officer, title, comment and action.
			when a.kind in ('event', 'observation')
				and row_number() over (
					partition by a.kind in ('event', 'observation'),
						date_trunc('minute', a.at at time zone 'Pacific/Auckland'),
						lower(coalesce(a.place_name, '')),
						coalesce(lower(btrim(coalesce(es.payload ->> 'patroller_raw', os.imported ->> 'patroller_raw'))), es.observed_entity_id::text, os.officer_id::text, ''),
						lower(btrim(regexp_replace(coalesce(a.title, ''), '\s+', ' ', 'g'))),
						lower(btrim(regexp_replace(coalesce(a.note, ''), '\s+', ' ', 'g'))),
						lower(btrim(regexp_replace(coalesce(a.action, ''), '\s+', ' ', 'g')))
					order by coalesce(pc.n, 0) desc, a.at, a.record_id::text
				) > 1
				then 'duplicate'
		end as withheld_reason
	from acts_base a
	left join mat_lines ml on ml.record_id = a.record_id
	left join photo_counts pc on pc.record_id = a.record_id
	left join incident_videos iv on iv.record_id = a.record_id
	left join event_scope es on a.kind = 'event' and es.id = a.record_id
	left join observation_scope os on a.kind = 'observation' and os.id = a.record_id
	cross join lateral (
		select case
			-- Camera card reviews are logged under the reviewing officer, so they arrive as
			-- patrol visits. Every card review is a camera observation for the client
			-- (owner ruling 2026-11-05), whatever its comment says and at any time of day.
			when a.kind = 'event'
				and regexp_replace(lower(coalesce(a.title, '')), '[^a-z]', '', 'g') = 'cardreview'
				then 'camera_activation'
			-- Travel stays operational even when it is logged as a desk entry.
			when a.activity in ('travel', 'materials')
				or regexp_replace(lower(coalesce(a.title, '')), '[^a-z]', '', 'g') = 'travel'
				then public.report_activity_category(a.kind, a.event_type, a.service_line, a.subject, a.activity, a.species, a.equipment, a.material)
			-- R&M patrol logs record desk work (card reviews, log entry, reconciliations)
			-- with a 0000 time, which imports as local midnight.
			when a.activity = 'administration'
				or regexp_replace(lower(coalesce(a.title, '')), '[^a-z]', '', 'g') in ('admin', 'administration')
				or (es.payload ->> 'source' = 'rm_patrol_log_import'
					and (a.at at time zone 'Pacific/Auckland')::time = time '00:00')
				then 'administration'
			else public.report_activity_category(a.kind, a.event_type, a.service_line, a.subject, a.activity, a.species, a.equipment, a.material)
		end as category
	) c
),
vis as materialized (
	select * from acts where withheld_reason is null
),
category_catalog(code, label, sort_order) as (
	values
		('incident', 'Incidents and investigations', 0),
		('call_out', 'Call-outs and responses', 1),
		('pest_control', 'Pest control', 2),
		('maintenance', 'Maintenance and repairs', 3),
		('manufacture', 'Manufacture and fabrication', 4),
		('installation_removal', 'Installation and removal', 5),
		('securing', 'Securing and access control', 6),
		('inspection', 'Inspections and checks', 7),
		('camera_activation', 'CCTV and camera activity', 8),
		('vehicle_observation', 'Observations', 9),
		('other_work', 'Other site work', 10),
		('administration', 'Administration and review', 11),
		('patrol_visit', 'Patrols', 12),
		('unclassified', 'Other site activity', 13),
		('travel_admin', 'Travel and materials', 14)
),
labels as (
	select rc.code_type, rc.code, rc.name
	from public.reference_codes rc
	where rc.code_type in ('work_activity', 'work_subject', 'biosecurity_species', 'equipment_type', 'material_type')
		and rc.is_active
		and rc.organization_id = (select provider_organization_id from agreement)
),
used_codes as (
	select 'activity' as dim, activity as code from vis where activity is not null
	union
	select 'subject', subject from vis where subject is not null
	union
	select 'species', species from vis where species is not null
	union
	select 'equipment', equipment from vis where equipment is not null
	union
	select 'material', material from vis where material is not null
	union
	select 'material', m.material_type from mats m join vis v on v.record_id = m.record_id
),
code_labels as (
	select u.dim, u.code,
		coalesce(l.name, initcap(replace(u.code, '_', ' '))) as label
	from used_codes u
	left join labels l
		on l.code = u.code
		and l.code_type = case u.dim
			when 'activity' then 'work_activity'
			when 'subject' then 'work_subject'
			when 'species' then 'biosecurity_species'
			when 'equipment' then 'equipment_type'
			else 'material_type'
		end
),
totals as (
	select count(*) as entries,
		count(*) filter (where kind = 'event') as events,
		count(*) filter (where kind = 'observation') as observations,
		count(*) filter (where kind = 'work_order') as work_orders,
		count(*) filter (where kind = 'incident') as incidents,
		count(*) filter (where category = 'call_out') as call_outs,
		count(*) filter (where kind = 'event' and event_type = 'patrol_visit' and category <> 'camera_activation') as patrol_visits,
		count(*) filter (where category = 'camera_activation') as camera_activations,
		count(*) filter (where note is not null or action is not null) as with_notes,
		count(distinct place_name) as places,
		(select count(distinct r.path) from photo_refs r join vis v on v.record_id = r.record_id) as photos
	from vis
),
category_totals as (
	select category, count(*) as entries, coalesce(sum(photos), 0) as photos
	from vis
	group by category
),
place_totals as (
	select coalesce(place_name, 'Not location-specific') as place_name, count(*) as entries,
		coalesce(sum(photos), 0) as photos
	from vis
	group by 1
),
place_categories as (
	select coalesce(place_name, 'Not location-specific') as place_name, category, count(*) as n
	from vis
	group by 1, 2
),
pest as (
	select * from vis where category = 'pest_control'
),
pest_species as (
	select coalesce(species, 'unspecified') as code,
		count(*) filter (where activity = 'cull') as culls,
		count(*) filter (where activity = 'sighting') as sightings,
		count(*) as total
	from pest
	where species is not null or activity in ('cull', 'sighting')
	group by 1
),
pest_activity as (
	select coalesce(activity, 'not_recorded') as code, count(*) as entries
	from pest
	group by 1
),
pest_equipment as (
	select equipment as code, count(*) as entries
	from pest
	where equipment is not null
	group by 1
),
pest_ammunition as (
	select coalesce(m.calibre, 'unspecified') as calibre, count(distinct m.record_id) as entries, sum(m.quantity) as rounds
	from mats m
	join pest p on p.record_id = m.record_id
	where m.material_type = 'ammunition'
	group by 1
),
work_subjects as (
	select category, coalesce(subject, 'not_recorded') as code, count(*) as entries
	from vis
	where category in ('maintenance', 'manufacture')
	group by category, coalesce(subject, 'not_recorded')
),
work_order_status as (
	select category,
		count(*) filter (where work_order_status = 'completed') as completed,
		count(*) filter (where work_order_status in ('approved', 'in_progress')) as open
	from vis
	where kind = 'work_order'
	group by category
),
observation_modules as (
	select coalesce(module_key, 'unknown') as module_key, count(*) as entries,
		count(*) filter (where photos > 0) as with_photo, coalesce(sum(photos), 0) as photos
	from vis
	where kind = 'observation'
	group by 1
),
incident_summary as (
	select count(*) as total,
		count(distinct investigation_ref) as investigations,
		count(*) filter (where photos > 0 or videos > 0) as with_media
	from vis
	where kind = 'incident'
),
numbered as (
	select row_number() over (order by v.at, v.place_name, v.category, v.record_id) as n, v.*
	from vis v
),
all_line_rows as (
	select n.n, jsonb_strip_nulls(jsonb_build_object(
		'd', n.local_date,
		't', n.local_time,
		'p', n.place_name,
		'k', n.kind,
		'c', n.category,
		'mo', case when n.kind = 'observation' then public.report_code_or_null(n.module_key) end,
		'a', n.activity,
		's', n.subject,
		'sp', n.species,
		'eq', n.equipment,
		'j', n.job,
		'm', n.materials_used,
		'ws', n.work_order_status,
		'ti', public.report_redact_identified_persons(n.title),
		'n', public.report_redact_identified_persons(n.note),
		'ac', public.report_redact_identified_persons(n.action),
		'it', n.incident_type,
		'sev', n.severity,
		'st', n.incident_status,
		'inv', n.investigation_ref,
		'ivs', n.investigation_status,
		'ph', nullif(n.photos, 0),
		'pr', n.photo_refs,
		'vid', nullif(n.videos, 0)
	)) as line
	from numbered n
),
line_rows as (
	select * from all_line_rows where n <= (select max_lines from params)
),
scope_counts as (
	select
		(select count(*) from event_scope) as events_in_scope,
		(select count(*) from event_scope where source = 'observation_trigger') as mirrors,
		(select count(*) from observation_scope) as observations_in_scope,
		(select count(*) from work_order_scope) as work_orders_in_scope,
		(select count(*) from incident_scope) as incidents_in_scope,
		(select count(*) from acts) as all_entries,
		(select count(*) filter (where withheld_reason = 'travel_admin') from acts) as withheld_travel_admin,
		(select count(*) filter (where withheld_reason = 'shift_marker') from acts) as withheld_shift_markers,
		(select count(*) filter (where withheld_reason = 'routine_card') from acts) as withheld_routine_cards,
		(select count(*) filter (where withheld_reason = 'duplicate') from acts) as withheld_duplicates
)
select jsonb_build_object(
	'report', jsonb_build_object(
		'version', 2,
		'itemisedDigest', (select md5(coalesce(string_agg(md5(lr.line::text), '' order by lr.n), '')) from all_line_rows lr),
		'basis', 'Activity recorded at the locations covered by this agreement: call-outs attended, patrols and site checks, observations, pest control, maintenance and manufacture, CCTV and incidents. Counts are recorded entries, not animals or devices.',
		'totals', (select jsonb_build_object(
			'entries', t.entries,
			'events', t.events,
			'observations', t.observations,
			'workOrders', t.work_orders,
			'incidents', t.incidents,
			'callOuts', t.call_outs,
			'patrolVisits', t.patrol_visits,
			'cameraActivations', t.camera_activations,
			'withNotes', t.with_notes,
			'places', t.places,
			'photos', t.photos
		) from totals t),
		'categories', coalesce((
			select jsonb_agg(jsonb_build_object('code', c.category, 'entries', c.entries, 'photos', c.photos)
				order by cc.sort_order)
			from category_totals c
			join category_catalog cc on cc.code = c.category
		), '[]'::jsonb),
		'byPlace', coalesce((
			select jsonb_agg(jsonb_build_object(
				'place', p.place_name, 'entries', p.entries, 'photos', p.photos,
				'categories', (
					select jsonb_object_agg(pc.category, pc.n)
					from place_categories pc
					where pc.place_name = p.place_name
				)
			) order by p.entries desc, p.place_name)
			from place_totals p
		), '[]'::jsonb),
		'pestControl', jsonb_build_object(
			'entries', (select count(*) from pest),
			'bySpecies', coalesce((
				select jsonb_agg(jsonb_build_object(
					'code', s.code, 'culls', s.culls, 'sightings', s.sightings,
					'other', s.total - s.culls - s.sightings, 'total', s.total
				) order by s.total desc, s.code)
				from pest_species s
			), '[]'::jsonb),
			'byActivity', coalesce((
				select jsonb_agg(jsonb_build_object('code', a.code, 'entries', a.entries)
					order by a.entries desc, a.code)
				from pest_activity a
			), '[]'::jsonb),
			'byEquipment', coalesce((
				select jsonb_agg(jsonb_build_object('code', q.code, 'entries', q.entries)
					order by q.entries desc, q.code)
				from pest_equipment q
			), '[]'::jsonb),
			'ammunition', coalesce((
				select jsonb_agg(jsonb_build_object(
					'calibre', m.calibre, 'entries', m.entries, 'rounds', m.rounds
				) order by m.entries desc, m.calibre)
				from pest_ammunition m
			), '[]'::jsonb)
		),
		'maintenance', jsonb_build_object(
			'entries', (select count(*) from vis where category = 'maintenance'),
			'bySubject', coalesce((
				select jsonb_agg(jsonb_build_object('code', w.code, 'entries', w.entries)
					order by w.entries desc, w.code)
				from work_subjects w
				where w.category = 'maintenance'
			), '[]'::jsonb),
			'workOrders', jsonb_build_object(
				'completed', coalesce((select completed from work_order_status where category = 'maintenance'), 0),
				'open', coalesce((select open from work_order_status where category = 'maintenance'), 0)
			)
		),
		'manufacture', jsonb_build_object(
			'entries', (select count(*) from vis where category = 'manufacture'),
			'bySubject', coalesce((
				select jsonb_agg(jsonb_build_object('code', w.code, 'entries', w.entries)
					order by w.entries desc, w.code)
				from work_subjects w
				where w.category = 'manufacture'
			), '[]'::jsonb),
			'workOrders', jsonb_build_object(
				'completed', coalesce((select completed from work_order_status where category = 'manufacture'), 0),
				'open', coalesce((select open from work_order_status where category = 'manufacture'), 0)
			)
		),
		'observations', jsonb_build_object(
			'total', (select count(*) from vis where kind = 'observation'),
			'withPhoto', (select count(*) from vis where kind = 'observation' and photos > 0),
			'photos', (select count(distinct r.path) from photo_refs r join vis v on v.record_id = r.record_id and v.kind = 'observation'),
			'byModule', coalesce((
				select jsonb_agg(jsonb_build_object(
					'module', m.module_key, 'entries', m.entries,
					'withPhoto', m.with_photo, 'photos', m.photos
				) order by m.entries desc, m.module_key)
				from observation_modules m
			), '[]'::jsonb)
		),
		'incidents', (select jsonb_build_object(
			'total', s.total,
			'investigations', s.investigations,
			'withMedia', s.with_media,
			'bySeverity', coalesce((
				select jsonb_agg(jsonb_build_object('code', x.code, 'entries', x.n) order by x.n desc, x.code)
				from (select coalesce(severity, 'standard') as code, count(*) as n from vis where kind = 'incident' group by 1) x
			), '[]'::jsonb),
			'byStatus', coalesce((
				select jsonb_agg(jsonb_build_object('code', x.code, 'entries', x.n) order by x.n desc, x.code)
				from (select coalesce(incident_status, 'open') as code, count(*) as n from vis where kind = 'incident' group by 1) x
			), '[]'::jsonb)
		) from incident_summary s),
		'labels', jsonb_build_object(
			'category', coalesce((select jsonb_object_agg(cc.code, cc.label) from category_catalog cc where cc.code in (select category from category_totals)), '{}'::jsonb),
			'activity', coalesce((select jsonb_object_agg(l.code, l.label) from code_labels l where l.dim = 'activity'), '{}'::jsonb),
			'subject', coalesce((select jsonb_object_agg(l.code, l.label) from code_labels l where l.dim = 'subject'), '{}'::jsonb),
			'species', coalesce((select jsonb_object_agg(l.code, l.label) from code_labels l where l.dim = 'species'), '{}'::jsonb),
			'equipment', coalesce((select jsonb_object_agg(l.code, l.label) from code_labels l where l.dim = 'equipment'), '{}'::jsonb),
			'material', coalesce((select jsonb_object_agg(l.code, l.label) from code_labels l where l.dim = 'material'), '{}'::jsonb)
		),
		'accountedFor', (select jsonb_build_object(
			'eventsInScope', sc.events_in_scope,
			'mirrorEventsExcluded', sc.mirrors,
			'activityEvents', sc.events_in_scope - sc.mirrors,
			'observationsInScope', sc.observations_in_scope,
			'workOrdersInScope', sc.work_orders_in_scope,
			'incidentsInScope', sc.incidents_in_scope,
			'entries', sc.all_entries,
			'reported', t.entries,
			'operationalWithheld', sc.withheld_travel_admin + sc.withheld_shift_markers + sc.withheld_routine_cards + sc.withheld_duplicates,
			'withheldTravelAdmin', sc.withheld_travel_admin,
			'withheldShiftMarkers', sc.withheld_shift_markers,
			'withheldRoutineCards', sc.withheld_routine_cards,
			'withheldDuplicates', sc.withheld_duplicates,
			'itemised', (select count(*) from line_rows),
			'notItemised', t.entries - (select count(*) from line_rows),
			'unclassified', coalesce((select ct.entries from category_totals ct where ct.category = 'unclassified'), 0),
			'reconciled', (
				sc.all_entries = (sc.events_in_scope - sc.mirrors) + sc.observations_in_scope + sc.work_orders_in_scope + sc.incidents_in_scope
				and sc.all_entries = t.entries + sc.withheld_travel_admin + sc.withheld_shift_markers + sc.withheld_routine_cards + sc.withheld_duplicates
				and t.entries = (select coalesce(sum(ct.entries), 0) from category_totals ct)
				and t.entries = (select coalesce(sum(pt.entries), 0) from place_totals pt)
			)
		) from scope_counts sc, totals t)
	),
	'lines', jsonb_build_object(
		'version', 2,
		'lines', coalesce((select jsonb_agg(lr.line order by lr.n) from line_rows lr), '[]'::jsonb),
		'notItemised', (select t.entries from totals t) - (select count(*) from line_rows)
	)
);
$function$;
COMMENT ON FUNCTION "public"."build_agreement_activity_report_core"(p_service_agreement_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_max_lines integer) IS 'Internal assembler for the R&M month-end site activity report: what happened at one agreement''s places in a window, as categorised statistics and itemised entries with the comments, action notes, incident descriptions and photos recorded there. Travel, materials and shift or movement markers are withheld from the client report but accounted for, and so is administration (including 0000 desk entries in R&M patrol logs). Every camera card review is reported as a camera observation, except a photo-less card replacement, which is withheld as routine; an entry repeated with the same local minute, place, officer, title, comment and action is withheld as a duplicate. Attended dispatch call-outs are reported in their own category with when they were requested, when the officer was on scene, the response time against the target and the outcome. Observation mirror events are excluded so nothing is counted twice. Personal details of identified people in titles, comments and action notes are replaced with "R & M have identified a person relating to this", and NZTA screenshots and identity-document photos are never included. Never copied: costs, officer or staff names, structured plates, GPS, investigation detail or source file names. Auth is on generate_due_report_packs and get_report_pack_activity_accounting.';
REVOKE ALL ON FUNCTION "public"."build_agreement_activity_report_core"(p_service_agreement_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_max_lines integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."build_agreement_activity_report_core"(p_service_agreement_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_max_lines integer) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."build_shift_safety_briefing"(p_shift_id uuid, p_stop_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_places jsonb;
  v_hazards jsonb;
  v_warnings jsonb := '[]'::jsonb;
  v_place_ids uuid[];
BEGIN
  SELECT coalesce(jsonb_agg(p.item ORDER BY p.item::text), '[]'::jsonb) INTO v_places
  FROM (
    SELECT DISTINCT jsonb_build_object('kind', place_kind, 'id', place_id, 'location_id', location_id, 'name', place_name) AS item
    FROM public.shift_safety_places(p_shift_id, p_stop_id)
  ) p;
  WITH places AS (SELECT * FROM public.shift_safety_places(p_shift_id, p_stop_id)),
  scoped AS (
    SELECT h.* FROM public.place_hazards h WHERE h.status IN ('reported', 'active') AND (
      (h.client_site_id IS NULL AND h.zone_id IS NULL AND h.location_id IN (SELECT location_id FROM places))
      OR h.client_site_id IN (SELECT place_id FROM places WHERE place_kind = 'site')
      OR h.zone_id IN (SELECT place_id FROM places WHERE place_kind = 'zone')
      OR (p_stop_id IS NULL AND h.client_site_id IS NULL AND h.zone_id IS NULL
          AND h.location_id = (SELECT location_id FROM public.shifts WHERE id = p_shift_id))
    )
  )
  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'id', h.id, 'title', h.title, 'hazard_class', h.hazard_class, 'risk_level', h.risk_level,
    'controls', to_jsonb(h.controls), 'details', h.details, 'status', h.status, 'origin', h.origin, 'version', h.version,
    'place_name', coalesce(cs.name, z.name, l.name),
    'place_kind', CASE WHEN h.client_site_id IS NOT NULL THEN 'site' WHEN h.zone_id IS NOT NULL THEN 'zone' ELSE 'location' END,
    'source_name', h.source_name, 'source_locator', h.source_locator, 'source_as_of', h.source_as_of,
    'has_source_document', h.source_document_id IS NOT NULL, 'recorded_by', o.name, 'updated_at', h.updated_at
  ) ORDER BY CASE h.risk_level WHEN 'critical' THEN 0 WHEN 'high' THEN 1 WHEN 'medium' THEN 2 ELSE 3 END, h.status DESC, h.title, h.id), '[]'::jsonb)
  INTO v_hazards FROM scoped h
  JOIN public.locations l ON l.id = h.location_id
  JOIN public.organizations o ON o.id = h.organization_id
  LEFT JOIN public.client_sites cs ON cs.id = h.client_site_id
  LEFT JOIN public.location_zones z ON z.id = h.zone_id;
  SELECT array_agg(DISTINCT l.canonical_place_id) INTO v_place_ids FROM public.locations l
  WHERE l.id IN (SELECT location_id FROM public.shift_safety_places(p_shift_id, p_stop_id))
    OR (p_stop_id IS NULL AND l.id = (SELECT location_id FROM public.shifts WHERE id = p_shift_id));
  IF cardinality(v_place_ids) > 0 THEN
    SELECT coalesce(jsonb_agg(jsonb_build_object(
      'id', w.id, 'hazard_class', w.hazard_class, 'alert_level', w.alert_level, 'raised_at', w.raised_at,
      'organization_name', w.organization_name, 'contact_phone', w.contact_phone, 'reason', w.reason
    ) ORDER BY w.id), '[]'::jsonb) INTO v_warnings
    FROM public.get_safety_warnings('place', v_place_ids) w;
  END IF;
  RETURN jsonb_build_object(
    'shift_id', p_shift_id, 'stop_id', p_stop_id, 'places', v_places, 'hazards', v_hazards, 'warnings', v_warnings,
    'item_count', jsonb_array_length(v_hazards) + jsonb_array_length(v_warnings),
    'briefing_hash', md5(jsonb_build_object('places', v_places, 'hazards', v_hazards, 'warnings', v_warnings)::text)
  );
END;
$function$;
COMMENT ON FUNCTION "public"."build_shift_safety_briefing"(p_shift_id uuid, p_stop_id uuid) IS 'Internal authorised-caller helper. Canonical shift/stop risks and warnings, with deterministic hash over all displayed content; changes to controls, warning reasons and source references require a fresh receipt.';
REVOKE ALL ON FUNCTION "public"."build_shift_safety_briefing"(p_shift_id uuid, p_stop_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."build_shift_safety_briefing"(p_shift_id uuid, p_stop_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."build_shift_safety_briefing"(p_shift_id uuid, p_stop_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_abort_independent_code_review"(_job_id uuid, _step_id uuid, _reason text)
 RETURNS builder_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _job public.builder_jobs%rowtype; _step public.builder_job_steps%rowtype; _terminal boolean;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  SELECT * INTO _job FROM public.builder_jobs WHERE id = _job_id FOR UPDATE;
  SELECT * INTO _step FROM public.builder_job_steps WHERE id = _step_id AND job_id = _job_id FOR UPDATE;
  IF _job.id IS NULL OR _job.status <> 'security_review' OR _job.code_review_mode <> 'independent_ai'
     OR _step.id IS NULL OR _step.status <> 'running' OR _step.builder_mode <> 'code_reviewer' THEN
    RAISE EXCEPTION 'Independent code review is not running';
  END IF;
  _terminal := _step.attempt_count >= 2;
  UPDATE public.builder_job_steps
  SET status = CASE WHEN _terminal THEN 'failed' ELSE 'pending' END,
      retryable = NOT _terminal,
      completed_at = CASE WHEN _terminal THEN now() ELSE NULL END,
      error = left(COALESCE(_reason, 'Independent reviewer infrastructure failure'), 1000),
      updated_at = now()
  WHERE id = _step.id;
  UPDATE public.builder_jobs
  SET code_review_status = CASE WHEN _terminal THEN 'blocked' ELSE 'pending' END,
      status = CASE WHEN _terminal THEN 'failed' ELSE 'security_review' END,
      last_error = left(COALESCE(_reason, 'Independent reviewer infrastructure failure'), 1000),
      updated_at = now()
  WHERE id = _job.id RETURNING * INTO _job;
  INSERT INTO public.builder_audit_events (organization_id, job_id, event_type, actor_type, previous_value, new_value, change_summary)
  VALUES (_job.organization_id, _job.id, 'step_failed', 'builder_mode',
    jsonb_build_object('step_status', 'running', 'attempt_count', _step.attempt_count),
    jsonb_build_object('step_status', CASE WHEN _terminal THEN 'failed' ELSE 'pending' END,
      'retryable', NOT _terminal, 'code_review_status', _job.code_review_status),
    CASE WHEN _terminal THEN 'Independent AI review retry limit reached' ELSE 'Independent AI review infrastructure failure is retryable' END);
  RETURN _job;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_abort_independent_code_review"(_job_id uuid, _step_id uuid, _reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_abort_independent_code_review"(_job_id uuid, _step_id uuid, _reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_abort_independent_code_review"(_job_id uuid, _step_id uuid, _reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_abort_model_step"(_job_id uuid, _step_id uuid, _reason text)
 RETURNS builder_job_steps
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _step public.builder_job_steps%rowtype; _job public.builder_jobs%rowtype;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  SELECT * INTO _job FROM public.builder_jobs WHERE id = _job_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Builder job is unavailable'; END IF;
  SELECT * INTO _step FROM public.builder_job_steps WHERE id = _step_id AND job_id = _job_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Builder step is unavailable'; END IF;
  IF _step.builder_mode NOT IN ('product_analyst', 'ux_designer') THEN RAISE EXCEPTION 'Only analyst and designer steps are aborted this way'; END IF;
  IF _step.status <> 'running' THEN RAISE EXCEPTION 'Step is not running'; END IF;
  UPDATE public.builder_job_steps
  SET status = 'failed',
      retryable = true,
      error = left(COALESCE(NULLIF(btrim(_reason), ''), 'model run failed'), 2000),
      completed_at = now(),
      updated_at = now()
  WHERE id = _step.id RETURNING * INTO _step;
  UPDATE public.builder_jobs SET last_error = left(COALESCE(NULLIF(btrim(_reason), ''), 'model run failed'), 1000), updated_at = now() WHERE id = _job.id;
  INSERT INTO public.builder_audit_events (organization_id, job_id, event_type, actor_type, previous_value, new_value, change_summary)
  VALUES (_job.organization_id, _job.id, 'step_failed', 'bot',
    jsonb_build_object('step', _step.step_id, 'step_status', 'running', 'attempt_count', _step.attempt_count),
    jsonb_build_object('step', _step.step_id, 'step_status', 'failed', 'retryable', true, 'reason', left(_reason, 500)),
    'Model run failed after the step started; step returned to failed/retryable');
  RETURN _step;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_abort_model_step"(_job_id uuid, _step_id uuid, _reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_abort_model_step"(_job_id uuid, _step_id uuid, _reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_abort_model_step"(_job_id uuid, _step_id uuid, _reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_abort_release_preparation"(_job_id uuid, _step_id uuid, _reason text)
 RETURNS builder_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _job public.builder_jobs%rowtype; _step public.builder_job_steps%rowtype;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  SELECT * INTO _job FROM public.builder_jobs WHERE id = _job_id FOR UPDATE;
  SELECT * INTO _step FROM public.builder_job_steps WHERE id = _step_id AND job_id = _job_id FOR UPDATE;
  IF _job.id IS NULL OR _job.status <> 'security_review' OR _step.id IS NULL OR _step.status <> 'running' OR _step.builder_mode <> 'release_engineer' THEN
    RAISE EXCEPTION 'Release preparation is not running';
  END IF;
  UPDATE public.builder_job_steps SET status = 'failed', retryable = true,
    error = left(COALESCE(_reason, 'Release preparation failed'), 1000), updated_at = now()
  WHERE id = _step.id;
  UPDATE public.builder_jobs SET last_error = left(COALESCE(_reason, 'Release preparation failed'), 1000), updated_at = now()
  WHERE id = _job.id RETURNING * INTO _job;
  INSERT INTO public.builder_audit_events (organization_id, job_id, event_type, actor_type, previous_value, new_value, change_summary)
  VALUES (_job.organization_id, _job.id, 'step_failed', 'builder_mode',
    jsonb_build_object('job_status', 'security_review', 'step_status', 'running'),
    jsonb_build_object('job_status', 'security_review', 'step_status', 'failed', 'retryable', true),
    'Release preparation failed and is retryable');
  RETURN _job;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_abort_release_preparation"(_job_id uuid, _step_id uuid, _reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_abort_release_preparation"(_job_id uuid, _step_id uuid, _reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_abort_release_preparation"(_job_id uuid, _step_id uuid, _reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_abort_security_review"(_run_id uuid, _lease_token text, _reason text)
 RETURNS builder_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _run public.builder_worker_runs%rowtype; _job public.builder_jobs%rowtype;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  SELECT * INTO _run FROM public.builder_worker_runs WHERE id = _run_id AND profile = 'security-review' AND status = 'running'
    AND lease_token_hash = encode(extensions.digest(_lease_token, 'sha256'), 'hex') FOR UPDATE;
  IF _run.id IS NULL THEN RAISE EXCEPTION 'Security review lease is missing or invalid'; END IF;
  UPDATE public.builder_worker_runs SET status = 'failed', completed_at = now(), lease_token_hash = NULL,
    lease_expires_at = NULL, log_summary = left(COALESCE(_reason, 'Security review infrastructure failure'), 1000), updated_at = now()
  WHERE id = _run.id;
  UPDATE public.builder_job_steps SET status = 'failed', retryable = true,
    error = left(COALESCE(_reason, 'Security review infrastructure failure'), 1000), updated_at = now()
  WHERE id = _run.step_id;
  UPDATE public.builder_jobs SET status = 'testing',
    last_error = left(COALESCE(_reason, 'Security review infrastructure failure'), 1000), updated_at = now()
  WHERE id = _run.job_id RETURNING * INTO _job;
  INSERT INTO public.builder_audit_events (organization_id, job_id, event_type, actor_type, previous_value, new_value, change_summary)
  VALUES (_run.organization_id, _run.job_id, 'step_failed', 'builder_mode',
    jsonb_build_object('job_status', 'security_review', 'step_status', 'running'),
    jsonb_build_object('job_status', 'testing', 'step_status', 'failed', 'retryable', true),
    'Security review infrastructure failure is retryable');
  RETURN _job;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_abort_security_review"(_run_id uuid, _lease_token text, _reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_abort_security_review"(_run_id uuid, _lease_token text, _reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_abort_security_review"(_run_id uuid, _lease_token text, _reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_account_verifier_recoveries"(_job_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _job public.builder_jobs%rowtype;
  _run public.builder_worker_runs%rowtype;
  _key text;
  _recoveries integer;
  _baseline boolean;
  _count integer := 0;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  SELECT * INTO _job FROM public.builder_jobs WHERE id = _job_id FOR UPDATE;
  IF _job.id IS NULL THEN RAISE EXCEPTION 'Builder job is missing'; END IF;
  IF _job.status IN ('failed', 'cancelled', 'deployed', 'release_ready') THEN RETURN 0; END IF;
  FOR _run IN
    SELECT * FROM public.builder_worker_runs
    WHERE job_id = _job.id AND organization_id = _job.organization_id
      AND target_sha = _job.target_sha
      AND profile IN ('frontend-verify', 'backend-verify')
      AND started_at IS NOT NULL AND patch_artifact_id IS NOT NULL
      AND (status = 'timeout' OR (status = 'failed' AND (
        log_summary LIKE 'Frontend verifier infrastructure failure (%'
        OR log_summary LIKE 'Backend verifier infrastructure failure (%'
        OR log_summary LIKE 'Frontend verification attribution unresolved (%'
        OR log_summary LIKE 'Backend verification attribution unresolved (%'
        OR log_summary = 'Frontend worker handoff failed'
        OR log_summary LIKE 'Frontend worker handoff failed during %'
        OR log_summary = 'Backend worker handoff failed'
        OR log_summary LIKE 'Backend worker handoff failed during %'
        OR log_summary LIKE 'Repository is red at the pinned commit (%'
      )))
    ORDER BY created_at
    FOR UPDATE
  LOOP
    _key := _run.id::text || ':' || extract(epoch FROM _run.started_at)::text;
    _baseline := coalesce(_run.log_summary LIKE 'Repository is red at the pinned commit (%', false);
    IF EXISTS (
      SELECT 1 FROM public.builder_audit_events
      WHERE job_id = _job.id AND organization_id = _job.organization_id
        AND event_type = 'error_recorded' AND new_value->>'verifier_recovery_key' = _key
    ) THEN CONTINUE; END IF;
    SELECT count(*) INTO _recoveries FROM public.builder_audit_events
    WHERE job_id = _job.id AND organization_id = _job.organization_id
      AND event_type = 'error_recorded'
      AND new_value->>'patch_artifact_id' = _run.patch_artifact_id::text
      AND new_value ? 'verifier_recovery_key'
      AND coalesce(new_value->>'recovery_kind', '') <> 'baseline';
    _recoveries := _recoveries + 1;
    UPDATE public.builder_job_steps
    SET attempt_count = greatest(0, coalesce(attempt_count, 0) - 1),
        retryable = NOT _baseline AND _recoveries < 2,
        error = CASE WHEN _baseline
          THEN 'baseline: repository red at the pinned commit: ' || left(_run.log_summary, 500)
          WHEN _recoveries < 2
          THEN 'Verifier recovery pending; re-verify the saved patch without another engineering revision'
          ELSE 'Verifier recovery paused after two infrastructure or attribution failures; patch preserved; inspect the runner and evidence before resuming'
        END,
        updated_at = now()
    WHERE id = _run.step_id AND job_id = _job.id AND status = 'failed'
      AND retryable = true AND coalesce(error, '') NOT LIKE 'Evidence conflict:%'
      AND input_context->>'patch_artifact_id' = _run.patch_artifact_id::text;
    IF NOT FOUND THEN CONTINUE; END IF;
    INSERT INTO public.builder_audit_events (
      organization_id, job_id, event_type, actor_type, new_value, change_summary, related_artifact_ids
    ) VALUES (
      _job.organization_id, _job.id, 'error_recorded', 'bot',
      jsonb_build_object('verifier_recovery_key', _key, 'step_id', _run.step_id,
        'patch_artifact_id', _run.patch_artifact_id, 'recovery_count', _recoveries,
        'recovery_kind', CASE WHEN _baseline THEN 'baseline' ELSE 'infrastructure_or_evidence' END,
        'verifier_failure_summary', left(_run.log_summary, 500),
        'engineering_attempt_refunded', true, 'retryable', NOT _baseline AND _recoveries < 2),
      'Verifier recovery recorded separately from engineering revisions; candidate patch preserved',
      ARRAY[_run.patch_artifact_id]
    );
    _count := _count + 1;
  END LOOP;
  RETURN _count;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_account_verifier_recoveries"(_job_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_account_verifier_recoveries"(_job_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_account_verifier_recoveries"(_job_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_authorize_frontend_repair"(_job_id uuid, _step_id uuid, _failed_worker_run_id uuid, _failed_patch_artifact_id uuid, _failure_artifact_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _job public.builder_jobs%rowtype;
  _step public.builder_job_steps%rowtype;
  _failed_run public.builder_worker_runs%rowtype;
  _patch public.builder_artifacts%rowtype;
  _failure public.builder_artifacts%rowtype;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  SELECT * INTO _job FROM public.builder_jobs WHERE id = _job_id FOR UPDATE;
  SELECT * INTO _step FROM public.builder_job_steps WHERE id = _step_id AND job_id = _job_id FOR UPDATE;
  SELECT * INTO _failed_run FROM public.builder_worker_runs WHERE id = _failed_worker_run_id AND job_id = _job_id AND step_id = _step_id;
  SELECT * INTO _patch FROM public.builder_artifacts WHERE id = _failed_patch_artifact_id AND job_id = _job_id AND step_id = _step_id;
  SELECT * INTO _failure FROM public.builder_artifacts WHERE id = _failure_artifact_id AND job_id = _job_id AND step_id = _step_id;

  IF _job.id IS NULL OR _job.status <> 'implementation_pending' THEN RAISE EXCEPTION 'Job is not awaiting frontend repair'; END IF;
  IF _step.id IS NULL OR _step.builder_mode <> 'frontend_engineer' THEN RAISE EXCEPTION 'Frontend Engineer step is missing'; END IF;
  IF _step.status <> 'failed' OR NOT _step.retryable THEN RAISE EXCEPTION 'Frontend Engineer step is not retryable'; END IF;
  IF _step.attempt_count >= 3 THEN
    UPDATE public.builder_job_steps SET retryable = false, error = 'Frontend repair attempt limit reached', updated_at = now() WHERE id = _step.id;
    UPDATE public.builder_jobs SET status = 'failed', last_error = 'Frontend repair attempt limit reached', updated_at = now() WHERE id = _job.id;
    INSERT INTO public.builder_audit_events (
      organization_id, job_id, event_type, actor_type, previous_value, new_value, change_summary, related_artifact_ids
    ) VALUES (
      _job.organization_id, _job.id, 'step_failed', 'builder_mode',
      jsonb_build_object('job_status', _job.status, 'step_status', _step.status, 'attempt_count', _step.attempt_count),
      jsonb_build_object('job_status', 'failed', 'step_status', 'failed', 'retryable', false),
      'Frontend autonomous repair attempt limit reached', ARRAY[_patch.id, _failure.id]
    );
    RETURN jsonb_build_object('authorized', false, 'reason', 'frontend repair attempt limit reached');
  END IF;
  IF _failed_run.id IS NULL OR _failed_run.status <> 'failed' OR _failed_run.target_sha IS DISTINCT FROM _job.target_sha THEN
    RAISE EXCEPTION 'Failed worker run is missing or stale';
  END IF;
  IF _patch.id IS NULL OR _patch.artifact_type <> 'code_implementation' OR _patch.status <> 'final' THEN
    RAISE EXCEPTION 'Failed patch artifact is invalid';
  END IF;
  IF _failure.id IS NULL OR _failure.artifact_type <> 'build_logs' OR _failure.status <> 'final'
     OR NOT (_failure.id = ANY(COALESCE(_failed_run.output_artifact_ids, '{}'))) THEN
    RAISE EXCEPTION 'Failure evidence is invalid';
  END IF;
  IF _failed_run.patch_artifact_id IS DISTINCT FROM _patch.id THEN RAISE EXCEPTION 'Failed patch does not belong to worker run'; END IF;

  INSERT INTO public.builder_audit_events (
    organization_id, job_id, event_type, actor_type, new_value, change_summary, related_artifact_ids
  ) VALUES (
    _job.organization_id, _job.id, 'model_run_started', 'builder_mode',
    jsonb_build_object('mode', 'frontend_repair', 'repair_attempt', _step.attempt_count + 1,
      'failed_worker_run_id', _failed_run.id, 'target_sha', _job.target_sha),
    'Bounded autonomous frontend repair authorized', ARRAY[_patch.id, _failure.id]
  );
  RETURN jsonb_build_object('authorized', true, 'repair_attempt', _step.attempt_count + 1, 'target_sha', _job.target_sha);
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_authorize_frontend_repair"(_job_id uuid, _step_id uuid, _failed_worker_run_id uuid, _failed_patch_artifact_id uuid, _failure_artifact_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_authorize_frontend_repair"(_job_id uuid, _step_id uuid, _failed_worker_run_id uuid, _failed_patch_artifact_id uuid, _failure_artifact_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_authorize_frontend_repair"(_job_id uuid, _step_id uuid, _failed_worker_run_id uuid, _failed_patch_artifact_id uuid, _failure_artifact_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_autopilot_bind"(_job_id uuid, _requested_by uuid, _conversation_id uuid DEFAULT NULL::uuid)
 RETURNS builder_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _job public.builder_jobs%rowtype;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  IF _requested_by IS NULL THEN RAISE EXCEPTION 'Autopilot requester is required'; END IF;
  SELECT * INTO _job FROM public.builder_jobs WHERE id = _job_id FOR UPDATE;
  IF _job.id IS NULL THEN RAISE EXCEPTION 'Builder job is unavailable'; END IF;
  IF _job.status IN ('failed', 'cancelled', 'deployed') THEN RAISE EXCEPTION 'Builder job is terminal'; END IF;
  IF NOT public.can_approve_action(_requested_by, _job.organization_id) THEN
    RAISE EXCEPTION 'Autopilot requester cannot approve Builder work for this organisation';
  END IF;
  UPDATE public.builder_jobs
  SET autopilot_requested_by = _requested_by,
      autopilot_conversation_id = _conversation_id,
      autopilot_state = 'driving',
      autopilot_updated_at = now(),
      updated_at = now()
  WHERE id = _job.id RETURNING * INTO _job;
  INSERT INTO public.builder_audit_events (organization_id, job_id, event_type, actor_user_id, actor_type, new_value, change_summary)
  VALUES (_job.organization_id, _job.id, 'builder_job_policy_bound', _requested_by, 'bot',
    jsonb_build_object('autopilot_requested_by', _requested_by, 'autopilot_conversation_id', _conversation_id),
    'Bob autopilot bound: gates will be cleared on this person''s standing chat instruction; merge and deployment remain human');
  RETURN _job;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_autopilot_bind"(_job_id uuid, _requested_by uuid, _conversation_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_autopilot_bind"(_job_id uuid, _requested_by uuid, _conversation_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_autopilot_bind"(_job_id uuid, _requested_by uuid, _conversation_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_autopilot_decide_approval"(_approval_id uuid, _comment text DEFAULT NULL::text)
 RETURNS builder_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _approval public.builder_approvals%rowtype; _job public.builder_jobs%rowtype; _next_status text; _uid uuid;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  SELECT * INTO _approval FROM public.builder_approvals WHERE id = _approval_id FOR UPDATE;
  IF NOT FOUND OR _approval.status <> 'pending' THEN RAISE EXCEPTION 'Approval is missing or already decided'; END IF;
  IF _approval.expires_at <= now() THEN RAISE EXCEPTION 'Approval has expired and requires a new evidence review'; END IF;
  SELECT * INTO _job FROM public.builder_jobs WHERE id = _approval.job_id FOR UPDATE;
  IF NOT FOUND OR _job.autopilot_requested_by IS NULL THEN RAISE EXCEPTION 'Job is not under Bob autopilot'; END IF;
  _uid := _job.autopilot_requested_by;
  IF NOT public.can_approve_action(_uid, _approval.organization_id) THEN RAISE EXCEPTION 'Autopilot requester is not authorized to approve this job'; END IF;
  IF cardinality(_approval.requested_from_users) > 0 AND NOT (_uid = ANY(_approval.requested_from_users)) THEN RAISE EXCEPTION 'Approval was not requested from the autopilot requester'; END IF;
  IF _job.status <> _approval.triggered_at_status THEN RAISE EXCEPTION 'Job has moved beyond this approval gate'; END IF;
  IF _approval.requested_target_sha IS DISTINCT FROM _job.target_sha THEN RAISE EXCEPTION 'Job target changed after approval was requested'; END IF;
  IF (SELECT count(*) FROM public.builder_artifacts WHERE job_id = _job.id AND id = ANY(_approval.reviewed_artifact_ids) AND status = 'final') <> cardinality(_approval.reviewed_artifact_ids) THEN
    RAISE EXCEPTION 'Reviewed evidence is no longer valid';
  END IF;
  IF _approval.approval_type = 'specification_review' AND _approval.triggered_at_status = 'specification_ready' THEN _next_status := 'design_pending';
  ELSIF _approval.approval_type = 'release_approval' AND _approval.triggered_at_status = 'approval_pending' THEN _next_status := 'release_ready';
  ELSE RAISE EXCEPTION 'Approval gate cannot transition this job'; END IF;
  UPDATE public.builder_approvals
  SET status = 'approved', approved_by = _uid, decided_by = _uid,
      approval_comment = left(COALESCE(NULLIF(btrim(_comment), ''), 'Cleared by Bob autopilot on the requester''s standing chat instruction'), 2000),
      responded_at = now(), updated_at = now()
  WHERE id = _approval.id;
  UPDATE public.builder_jobs SET status = _next_status, last_error = NULL, autopilot_updated_at = now(), updated_at = now() WHERE id = _job.id RETURNING * INTO _job;
  INSERT INTO public.builder_audit_events (organization_id, job_id, event_type, actor_user_id, actor_type, previous_value, new_value, change_summary, related_artifact_ids, related_approval_id)
  VALUES (_approval.organization_id, _approval.job_id, 'approval_approved', _uid, 'bot',
    jsonb_build_object('status', _approval.triggered_at_status),
    jsonb_build_object('status', _next_status, 'decision', 'approved', 'source', 'bob_autopilot'),
    'Bob autopilot cleared the ' || _approval.approval_type || ' gate on the requester''s standing chat instruction; merge and deployment remain human',
    _approval.reviewed_artifact_ids, _approval.id);
  RETURN _job;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_autopilot_decide_approval"(_approval_id uuid, _comment text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_autopilot_decide_approval"(_approval_id uuid, _comment text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_autopilot_decide_approval"(_approval_id uuid, _comment text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_autopilot_decide_approval_guarded"(_approval_id uuid, _comment text DEFAULT NULL::text)
 RETURNS builder_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _approval public.builder_approvals%rowtype;
  _job public.builder_jobs%rowtype;
  _packet public.bob_friction_packets%rowtype;
  _actor uuid;
  _next_status text;
  _source text;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  SELECT * INTO _approval FROM public.builder_approvals WHERE id = _approval_id FOR UPDATE;
  IF NOT FOUND OR _approval.status <> 'pending' THEN RAISE EXCEPTION 'Approval is missing or already decided'; END IF;
  SELECT * INTO _job FROM public.builder_jobs WHERE id = _approval.job_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Builder job is unavailable'; END IF;
  IF _job.autopilot_source = 'main_monitor' THEN
    IF _job.repair_risk <> 'routine'
       OR _job.source_main_health_sha IS NULL
       OR _job.source_main_health_sha !~ '^[a-f0-9]{40}$'
       OR COALESCE(cardinality(_job.source_main_health_files), 0) < 1
       OR cardinality(_job.source_main_health_files) > 8
       OR EXISTS (
         SELECT 1 FROM unnest(_job.source_main_health_files) AS file_name
         WHERE NOT public.builder_main_health_test_path_valid(file_name)
       ) THEN
      RAISE EXCEPTION 'Main-health repair authorization is no longer valid';
    END IF;
    _actor := NULL;
    _source := 'main_monitor';
  ELSIF _job.autopilot_source = 'routine_monitor' THEN
    SELECT * INTO _packet FROM public.bob_friction_packets WHERE id = _job.source_friction_packet_id;
    IF NOT FOUND OR _packet.repair_risk <> 'routine'
       OR _packet.route <> 'dispatch_flow' OR _packet.stop_line_hit IS NOT NULL THEN
      RAISE EXCEPTION 'Routine repair authorization is no longer valid';
    END IF;
    _actor := _packet.user_id;
    _source := 'routine_monitor';
  ELSE
    RETURN public.builder_autopilot_decide_approval(_approval_id, _comment);
  END IF;
  IF _approval.expires_at <= now() THEN RAISE EXCEPTION 'Approval has expired and requires a new evidence review'; END IF;
  IF _job.status <> _approval.triggered_at_status THEN RAISE EXCEPTION 'Job has moved beyond this approval gate'; END IF;
  IF _approval.requested_target_sha IS DISTINCT FROM _job.target_sha THEN RAISE EXCEPTION 'Job target changed after approval was requested'; END IF;
  IF (SELECT count(*) FROM public.builder_artifacts WHERE job_id = _job.id AND id = ANY(_approval.reviewed_artifact_ids) AND status = 'final') <> cardinality(_approval.reviewed_artifact_ids) THEN
    RAISE EXCEPTION 'Reviewed evidence is no longer valid';
  END IF;
  IF _approval.approval_type = 'specification_review' AND _approval.triggered_at_status = 'specification_ready' THEN
    _next_status := 'design_pending';
  ELSIF _approval.approval_type = 'release_approval' AND _approval.triggered_at_status = 'approval_pending' THEN
    _next_status := 'release_ready';
  ELSE
    RAISE EXCEPTION 'Approval gate cannot transition this job';
  END IF;
  UPDATE public.builder_approvals
  SET status = 'approved', approved_by = _actor, decided_by = _actor,
      approval_comment = left(COALESCE(NULLIF(btrim(_comment), ''), 'Cleared by Bob after bounded automated verification'), 2000),
      responded_at = now(), updated_at = now()
  WHERE id = _approval.id;
  UPDATE public.builder_jobs
  SET status = _next_status, last_error = NULL, autopilot_updated_at = now(), updated_at = now()
  WHERE id = _job.id RETURNING * INTO _job;
  INSERT INTO public.builder_audit_events (
    organization_id, job_id, event_type, actor_user_id, actor_type,
    previous_value, new_value, change_summary, related_artifact_ids, related_approval_id
  ) VALUES (
    _approval.organization_id, _approval.job_id, 'approval_approved', _actor, 'bot',
    jsonb_build_object('status', _approval.triggered_at_status),
    jsonb_build_object('status', _next_status, 'decision', 'approved', 'source', _source),
    CASE WHEN _source = 'main_monitor'
      THEN 'Bob cleared a bounded main-health repair gate; the verified draft remains subject to the protected release policy'
      ELSE 'Bob cleared a routine-repair gate after deterministic risk classification; protected scope remains held for Grandmaster review'
    END,
    _approval.reviewed_artifact_ids, _approval.id
  );
  RETURN _job;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_autopilot_decide_approval_guarded"(_approval_id uuid, _comment text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_autopilot_decide_approval_guarded"(_approval_id uuid, _comment text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_autopilot_decide_approval_guarded"(_approval_id uuid, _comment text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_autopilot_mark_reported"(_job_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  UPDATE public.builder_jobs SET autopilot_reported_at = now(), updated_at = now()
  WHERE id = _job_id AND autopilot_report IS NOT NULL AND autopilot_reported_at IS NULL;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_autopilot_mark_reported"(_job_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_autopilot_mark_reported"(_job_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_autopilot_mark_reported"(_job_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_autopilot_record"(_job_id uuid, _state text, _report jsonb DEFAULT NULL::jsonb)
 RETURNS builder_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _job public.builder_jobs%rowtype;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  IF _state NOT IN ('driving', 'awaiting_human', 'published', 'blocked', 'done') THEN RAISE EXCEPTION 'Unsupported autopilot state'; END IF;
  UPDATE public.builder_jobs
  SET autopilot_state = _state,
      autopilot_report = COALESCE(_report, autopilot_report),
      autopilot_reported_at = CASE WHEN _report IS NOT NULL THEN NULL ELSE autopilot_reported_at END,
      autopilot_updated_at = now(),
      updated_at = now()
  WHERE id = _job_id
    AND (autopilot_requested_by IS NOT NULL OR autopilot_source = 'main_monitor')
  RETURNING * INTO _job;
  IF _job.id IS NULL THEN RAISE EXCEPTION 'Builder job is not under Bob autopilot'; END IF;
  IF _state = 'awaiting_human' THEN
    INSERT INTO public.builder_audit_events (organization_id, job_id, event_type, actor_type, new_value, change_summary)
    VALUES (_job.organization_id, _job.id, 'approval_requested', 'bot',
      jsonb_build_object('autopilot_state', _state, 'gate', _report->>'gate', 'evidential_files', COALESCE(_report->'evidential_files', '[]'::jsonb)),
      'Bob autopilot paused for a human decision');
  END IF;
  RETURN _job;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_autopilot_record"(_job_id uuid, _state text, _report jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_autopilot_record"(_job_id uuid, _state text, _report jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_autopilot_record"(_job_id uuid, _state text, _report jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_bind_routine_repair"(_job_id uuid, _packet_id uuid)
 RETURNS builder_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _job public.builder_jobs%rowtype;
  _packet public.bob_friction_packets%rowtype;
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;

  SELECT * INTO _packet
  FROM public.bob_friction_packets
  WHERE id = _packet_id
  FOR UPDATE;

  IF NOT FOUND
     OR _packet.repair_risk <> 'routine'
     OR _packet.route <> 'dispatch_flow'
     OR _packet.stop_line_hit IS NOT NULL
     OR _packet.automation_status <> 'claimed' THEN
    RAISE EXCEPTION 'Friction packet is not eligible for routine automation';
  END IF;

  SELECT * INTO _job
  FROM public.builder_jobs
  WHERE id = _job_id
  FOR UPDATE;

  IF NOT FOUND OR _job.status IN ('failed', 'cancelled', 'deployed') THEN
    RAISE EXCEPTION 'Builder job is unavailable';
  END IF;

  UPDATE public.builder_jobs
  SET autopilot_requested_by = _packet.user_id,
      autopilot_conversation_id = NULL,
      autopilot_source = 'routine_monitor',
      source_friction_packet_id = _packet.id,
      repair_risk = 'routine',
      autopilot_state = 'driving',
      autopilot_updated_at = now(),
      updated_at = now()
  WHERE id = _job.id
  RETURNING * INTO _job;

  UPDATE public.bob_friction_packets
  SET builder_job_id = _job.id,
      automation_status = 'builder_started',
      automation_updated_at = now()
  WHERE id = _packet.id;

  INSERT INTO public.builder_audit_events (
    organization_id, job_id, event_type, actor_user_id, actor_type,
    new_value, change_summary
  )
  VALUES (
    _job.organization_id, _job.id, 'builder_job_policy_bound', _packet.user_id, 'bot',
    jsonb_build_object(
      'autopilot_source', 'routine_monitor',
      'source_friction_packet_id', _packet.id,
      'repair_risk', 'routine'
    ),
    'Bob automatically opened a bounded routine repair from a monitored friction packet; protected or expanded scope still requires Grandmaster review'
  );

  RETURN _job;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_bind_routine_repair"(_job_id uuid, _packet_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_bind_routine_repair"(_job_id uuid, _packet_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_bind_routine_repair"(_job_id uuid, _packet_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_bind_workspace"(_job_id uuid, _workspace_branch text, _workspace_head_sha text)
 RETURNS builder_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _job public.builder_jobs%rowtype;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  IF _workspace_branch !~ '^bob/job-[a-z0-9]+$' THEN RAISE EXCEPTION 'Builder workspace branch is invalid'; END IF;
  IF _workspace_head_sha !~ '^[a-f0-9]{40}$' THEN RAISE EXCEPTION 'Builder workspace commit is invalid'; END IF;
  SELECT * INTO _job FROM public.builder_jobs WHERE id = _job_id FOR UPDATE;
  IF _job.id IS NULL OR _job.target_sha IS NULL THEN RAISE EXCEPTION 'Builder job or target SHA is unavailable'; END IF;
  IF _workspace_head_sha IS DISTINCT FROM _job.target_sha THEN RAISE EXCEPTION 'Builder workspace must start from the pinned target SHA'; END IF;
  IF _job.workspace_branch IS NOT NULL AND _job.workspace_branch <> _workspace_branch THEN RAISE EXCEPTION 'Builder workspace branch is already bound'; END IF;
  UPDATE public.builder_jobs
  SET workspace_branch = _workspace_branch, workspace_head_sha = _workspace_head_sha,
      workspace_created_at = COALESCE(workspace_created_at, now()), updated_at = now()
  WHERE id = _job.id
  RETURNING * INTO _job;
  INSERT INTO public.builder_audit_events (organization_id, job_id, event_type, actor_type, new_value, change_summary)
  VALUES (_job.organization_id, _job.id, 'job_status_changed', 'builder_mode',
    jsonb_build_object('workspace_branch', _job.workspace_branch, 'workspace_head_sha', _job.workspace_head_sha),
    'Interactive Builder workspace bound to the immutable target commit');
  RETURN _job;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_bind_workspace"(_job_id uuid, _workspace_branch text, _workspace_head_sha text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_bind_workspace"(_job_id uuid, _workspace_branch text, _workspace_head_sha text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_bind_workspace"(_job_id uuid, _workspace_branch text, _workspace_head_sha text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_cancel_job"(_job_id uuid, _reason text)
 RETURNS builder_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _trimmed_reason text := btrim(_reason);
  _job public.builder_jobs;
  _updated_job public.builder_jobs;
BEGIN
  IF auth.role() IS DISTINCT FROM 'authenticated' OR _uid IS NULL THEN
    RAISE EXCEPTION 'Authenticated human required';
  END IF;
  IF _trimmed_reason IS NULL OR _trimmed_reason = '' OR char_length(_trimmed_reason) > 2000 THEN
    RAISE EXCEPTION 'Cancellation reason must be 1 to 2000 characters';
  END IF;

  SELECT * INTO _job
  FROM public.builder_jobs
  WHERE id = _job_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Builder job not found';
  END IF;
  IF _job.status IN ('deployed', 'failed', 'cancelled') THEN
    RAISE EXCEPTION 'Builder job is already finished';
  END IF;
  IF NOT public.can_approve_action(_uid, _job.organization_id) THEN
    RAISE EXCEPTION 'Not authorized to cancel Builder job';
  END IF;

  UPDATE public.builder_jobs
  SET status = 'cancelled',
      last_error = 'Cancelled: ' || _trimmed_reason,
      autopilot_state = CASE WHEN autopilot_requested_by IS NOT NULL THEN 'done' ELSE autopilot_state END,
      updated_at = now()
  WHERE id = _job.id
  RETURNING * INTO _updated_job;

  INSERT INTO public.builder_audit_events (
    organization_id, job_id, event_type, actor_user_id, actor_type,
    previous_value, new_value, change_summary
  ) VALUES (
    _job.organization_id, _job.id, 'job_cancelled', _uid, 'human',
    jsonb_build_object('status', _job.status),
    jsonb_build_object('status', 'cancelled', 'reason', _trimmed_reason),
    'Builder job cancelled by human operator'
  );

  RETURN _updated_job;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_cancel_job"(_job_id uuid, _reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_cancel_job"(_job_id uuid, _reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_cancel_job"(_job_id uuid, _reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."builder_cancel_job"(_job_id uuid, _reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_cancel_terminal_approvals"()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _count integer;
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;

  UPDATE public.builder_approvals approval
  SET status = 'cancelled',
      approval_comment = COALESCE(approval.approval_comment, 'Cancelled because the Builder job is already terminal.'),
      responded_at = COALESCE(approval.responded_at, now()),
      updated_at = now()
  FROM public.builder_jobs job
  WHERE approval.job_id = job.id
    AND approval.status = 'pending'
    AND job.status IN ('deployed', 'failed', 'cancelled');

  GET DIAGNOSTICS _count = ROW_COUNT;
  RETURN _count;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_cancel_terminal_approvals"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_cancel_terminal_approvals"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_cancel_terminal_approvals"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_chat_claim_next"()
 RETURNS SETOF builder_chat_messages
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  UPDATE public.builder_chat_messages m
     SET status = 'claimed', claimed_at = now()
   WHERE m.id = (
     SELECT q.id FROM public.builder_chat_messages q
       JOIN public.builder_chat_threads t ON t.id = q.thread_id
      WHERE q.status = 'queued' AND t.status <> 'closed'
        AND NOT EXISTS (SELECT 1 FROM public.builder_chat_messages c WHERE c.thread_id = q.thread_id AND c.status = 'claimed')
      ORDER BY q.created_at
      LIMIT 1
      FOR UPDATE OF q SKIP LOCKED)
  RETURNING m.*;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_chat_claim_next"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_chat_claim_next"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_chat_claim_next"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_chat_record_job"(p_message_id uuid, p_job_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := public.builder_chat_require_owner();
  v_thread uuid;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.builder_jobs WHERE id = p_job_id) THEN RAISE EXCEPTION 'Builder job not found'; END IF;
  UPDATE public.builder_chat_messages
     SET payload = (payload - 'creating_token' - 'creating_by' - 'creating_at')
                   || jsonb_build_object('job_id', p_job_id, 'accepted_by', v_user, 'accepted_at', now())
   WHERE id = p_message_id AND kind = 'proposal' AND NOT (payload ? 'job_id')
  RETURNING thread_id INTO v_thread;
  IF v_thread IS NULL THEN
    -- A retried record for the job already linked is a success, not an error.
    IF EXISTS (SELECT 1 FROM public.builder_chat_messages WHERE id = p_message_id AND kind = 'proposal' AND payload->>'job_id' = p_job_id::text) THEN RETURN; END IF;
    RAISE EXCEPTION 'Proposal not found or already accepted';
  END IF;
  INSERT INTO public.builder_chat_messages (thread_id, role, kind, content, payload, created_by)
  VALUES (v_thread, 'system', 'status', 'Owner created the proposed Builder job.', jsonb_build_object('job_id', p_job_id, 'proposal_id', p_message_id), v_user);
  UPDATE public.builder_chat_threads SET last_activity_at = now(), updated_at = now() WHERE id = v_thread;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_chat_record_job"(p_message_id uuid, p_job_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_chat_record_job"(p_message_id uuid, p_job_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_chat_record_job"(p_message_id uuid, p_job_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."builder_chat_record_job"(p_message_id uuid, p_job_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_chat_recover_implementation"(p_message_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := public.builder_chat_require_owner();
  v_card public.builder_chat_messages%rowtype;
  v_source public.builder_chat_messages%rowtype;
  v_job public.builder_jobs%rowtype;
  v_step public.builder_job_steps%rowtype;
  v_approval public.builder_approvals%rowtype;
  v_revision jsonb;
  v_feedback text;
  v_event uuid := gen_random_uuid();
BEGIN
  SELECT m.* INTO v_card FROM public.builder_chat_messages m
    JOIN public.builder_chat_threads t ON t.id = m.thread_id
    WHERE m.id = p_message_id AND m.kind = 'proposal' AND m.role = 'bob' AND t.created_by = v_user
    FOR UPDATE OF m;
  IF v_card.id IS NULL OR v_card.payload->'revision'->>'kind' IS DISTINCT FROM 'recovery' THEN
    RAISE EXCEPTION 'Implementation recovery card not found';
  END IF;
  IF v_card.payload ? 'revision_receipt' THEN RETURN (v_card.payload->>'revision_receipt')::uuid; END IF;
  v_revision := v_card.payload->'revision';
  v_feedback := v_revision->>'feedback';
  IF v_feedback IS NULL OR char_length(btrim(v_feedback)) < 40 OR char_length(v_feedback) > 4000 THEN
    RAISE EXCEPTION 'Bounded recovery feedback is required';
  END IF;
  SELECT * INTO v_source FROM public.builder_chat_messages
    WHERE id = (v_revision->>'source_message_id')::uuid AND thread_id = v_card.thread_id
      AND created_by = v_user AND id::text = v_card.payload->>'message_id'
      AND role = 'owner' AND status = 'done' AND payload->>'pm_purpose' IN ('pm', 'technical_review')
      AND payload->'research_consent'->>'allowed' = 'true';
  IF v_source.id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.builder_chat_messages WHERE thread_id = v_card.thread_id
      AND kind = 'proposal' AND payload->>'job_id' = v_revision->>'job_id'
  ) THEN RAISE EXCEPTION 'Recovery requires an accepted same-thread handoff and completed approved PM turn'; END IF;

  SELECT * INTO v_job FROM public.builder_jobs WHERE id = (v_revision->>'job_id')::uuid FOR UPDATE;
  IF v_job.id IS NULL OR v_job.status IS DISTINCT FROM 'failed'
    OR v_job.target_sha IS DISTINCT FROM v_revision->>'target_sha'
    OR v_job.updated_at IS DISTINCT FROM (v_revision->>'job_updated_at')::timestamptz
    OR v_job.code_review_revision->>'approval_id' IS DISTINCT FROM v_revision->>'approval_id'
    OR v_job.code_review_revision->>'approval_id' IS NULL
    OR v_job.code_review_mode IS DISTINCT FROM 'human'
    OR v_job.workspace_published_at IS NOT NULL OR v_job.workspace_published_head_sha IS NOT NULL
    OR v_job.workspace_pull_request_url IS NOT NULL THEN
    RAISE EXCEPTION 'Failed correction changed or is published; prepare a fresh recovery card';
  END IF;
  SELECT * INTO v_approval FROM public.builder_approvals
    WHERE id = (v_job.code_review_revision->>'approval_id')::uuid;
  IF v_approval.id IS NULL OR v_approval.job_id <> v_job.id
    OR v_approval.organization_id IS DISTINCT FROM v_job.organization_id
    OR v_approval.approval_type <> 'implementation_review' OR v_approval.status <> 'cancelled'
    OR v_approval.requested_target_sha IS DISTINCT FROM v_job.target_sha
    OR public.can_approve_action(v_user, v_job.organization_id) IS DISTINCT FROM true
    OR (cardinality(v_approval.requested_from_users) > 0 AND NOT (v_user = ANY(v_approval.requested_from_users))) THEN
    RAISE EXCEPTION 'User is not authorized to recover this correction';
  END IF;
  PERFORM 1 FROM public.builder_job_steps WHERE job_id = v_job.id FOR UPDATE;
  SELECT * INTO v_step FROM public.builder_job_steps
    WHERE id = (v_revision->>'failed_step_id')::uuid AND job_id = v_job.id;
  IF v_step.id IS NULL OR v_step.status <> 'failed'
    OR v_step.step_id NOT IN ('frontend_implementation', 'backend_implementation')
    OR v_step.error NOT LIKE 'generation: %'
    OR v_step.error IS NULL
    OR (SELECT count(*) FROM public.builder_job_steps WHERE job_id = v_job.id AND status = 'failed') <> 1
    OR EXISTS (SELECT 1 FROM public.builder_job_steps WHERE job_id = v_job.id AND status = 'running')
    OR EXISTS (SELECT 1 FROM public.builder_job_steps WHERE job_id = v_job.id
      AND step_id IN ('frontend_implementation', 'backend_implementation') AND id <> v_step.id AND status <> 'pending')
    OR EXISTS (SELECT 1 FROM public.builder_job_steps WHERE job_id = v_job.id
      AND step_id IN ('test_suite', 'security_review', 'code_review', 'release_prep')
      AND (status <> 'pending' OR started_at IS NOT NULL OR completed_at IS NOT NULL))
    OR (SELECT count(*) FROM public.builder_job_steps WHERE job_id = v_job.id
      AND step_id IN ('test_suite', 'security_review', 'code_review', 'release_prep')) <> 4
    OR NOT EXISTS (SELECT 1 FROM public.builder_job_steps WHERE job_id = v_job.id AND step_id = 'product_analysis' AND status = 'completed')
    OR NOT EXISTS (SELECT 1 FROM public.builder_job_steps WHERE job_id = v_job.id AND step_id = 'ui_design' AND status IN ('completed', 'skipped'))
    OR EXISTS (SELECT 1 FROM public.builder_worker_runs WHERE job_id = v_job.id AND status IN ('pending', 'running'))
    OR EXISTS (SELECT 1 FROM public.builder_model_runs WHERE job_id = v_job.id AND status IN ('pending', 'running'))
    OR EXISTS (SELECT 1 FROM public.builder_approvals WHERE job_id = v_job.id AND status = 'pending')
    OR EXISTS (SELECT 1 FROM public.builder_artifacts WHERE job_id = v_job.id AND status = 'final'
      AND artifact_type = 'code_implementation' AND step_id = v_step.id) THEN
    RAISE EXCEPTION 'Recovery requires an idle author failure without a patch and untouched downstream checks';
  END IF;
  UPDATE public.builder_job_steps SET status = 'pending', started_at = NULL, completed_at = NULL,
    error = NULL, result_summary = NULL, blocked_reason = NULL, retryable = false, updated_at = now()
    WHERE id = v_step.id;
  UPDATE public.builder_jobs SET status = 'implementation_pending', last_error = NULL,
    current_step_name = NULL, current_step_index = 2,
    code_review_revision = code_review_revision || jsonb_build_object(
      'recovery_id', v_event, 'recovery_feedback', v_feedback, 'recovery_report', v_source.content,
      'recovery_source_message_id', v_source.id, 'recovered_by', v_user, 'recovered_at', now()),
    autopilot_state = CASE WHEN autopilot_requested_by IS NOT NULL THEN 'driving' ELSE autopilot_state END,
    updated_at = now() WHERE id = v_job.id;
  INSERT INTO public.builder_audit_events (
    id, organization_id, job_id, event_type, actor_user_id, actor_type, previous_value, new_value,
    change_summary, related_approval_id
  ) VALUES (
    v_event, v_job.organization_id, v_job.id, 'job_status_changed', v_user, 'user',
    jsonb_build_object('status', v_job.status, 'step_id', v_step.id, 'step_error', v_step.error,
      'attempt_count', v_step.attempt_count, 'previous_recovery_id', v_job.code_review_revision->>'recovery_id'),
    jsonb_build_object('status', 'implementation_pending', 'source_message_id', v_source.id,
      'feedback', v_feedback, 'human_report', v_source.content, 'attempt_count', v_step.attempt_count),
    'Owner confirmed same-job recovery after implementation author failure; attempts and history preserved',
    v_approval.id
  );
  UPDATE public.builder_chat_messages SET payload = payload || jsonb_build_object('revision_receipt', v_event)
    WHERE id = v_card.id;
  RETURN v_event;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_chat_recover_implementation"(p_message_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_chat_recover_implementation"(p_message_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_chat_recover_implementation"(p_message_id uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."builder_chat_release_proposal"(p_message_id uuid, p_token text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := public.builder_chat_require_owner();
BEGIN
  UPDATE public.builder_chat_messages
     SET payload = payload - 'creating_token' - 'creating_by' - 'creating_at'
   WHERE id = p_message_id AND kind = 'proposal' AND payload->>'creating_token' = p_token;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_chat_release_proposal"(p_message_id uuid, p_token text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_chat_release_proposal"(p_message_id uuid, p_token text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_chat_release_proposal"(p_message_id uuid, p_token text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."builder_chat_release_proposal"(p_message_id uuid, p_token text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_chat_remember"(p_message_id uuid, p_content text, p_memory_type text DEFAULT 'builder_note'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_message public.builder_chat_messages%ROWTYPE;
  v_memory_id uuid;
  v_text text;
BEGIN
  IF p_content IS NULL OR char_length(btrim(p_content)) NOT BETWEEN 1 AND 2000
     OR p_memory_type IS NULL OR p_memory_type NOT IN ('reflection', 'builder_note') THEN
    RAISE EXCEPTION 'Diary entry requires bounded content and reflection or builder_note type';
  END IF;
  SELECT m.* INTO v_message FROM public.builder_chat_messages m
    JOIN public.builder_chat_threads t ON t.id = m.thread_id
    WHERE m.id = p_message_id AND m.role = 'owner'
      AND m.created_by = t.created_by
      AND (public.is_platform_owner(m.created_by) OR EXISTS (
        SELECT 1 FROM public.user_profiles p WHERE p.id = m.created_by AND p.role::text = 'grand_master'))
      AND m.status IN ('claimed', 'done')
      AND m.payload->>'pm_purpose' IN ('pm', 'qa', 'technical_review')
      AND m.payload->'research_consent'->>'allowed' = 'true';
  IF NOT FOUND THEN RAISE EXCEPTION 'Approved owner PM message not found'; END IF;
  v_text := btrim(p_content) || E'\n\n[Bob Builder Chat self-memory; unverified reflection, not approved knowledge.'
    || ' Source message: ' || p_message_id::text || '; thread: ' || v_message.thread_id::text || ']';
  v_memory_id := substring(encode(extensions.digest(
    'builder-chat-memory:' || p_message_id::text || ':' || p_memory_type || ':' || btrim(p_content),
    'sha256'), 'hex') FROM 1 FOR 32)::uuid;
  INSERT INTO public.bob_self_memory(id, memory_text, memory_kind, proposed_by, status)
    VALUES (v_memory_id, v_text, p_memory_type, '00000000-0000-0000-0000-00000000b0b0', 'kept')
    ON CONFLICT (id) DO NOTHING;
  IF NOT EXISTS (SELECT 1 FROM public.bob_self_memory WHERE id = v_memory_id
    AND memory_text = v_text AND memory_kind = p_memory_type
    AND proposed_by = '00000000-0000-0000-0000-00000000b0b0' AND status = 'kept') THEN
    RAISE EXCEPTION 'Diary receipt conflicts with an existing immutable entry';
  END IF;
  RETURN v_memory_id;
END;
$function$;
COMMENT ON FUNCTION "public"."builder_chat_remember"(p_message_id uuid, p_content text, p_memory_type text) IS 'Service worker append-only reuse of Bob own diary from an approved owner PM turn. Retry-safe, no approval/bell for memory writes, no approved knowledge or conduct promotion. No tenant-specific data belongs in this global diary.';
REVOKE ALL ON FUNCTION "public"."builder_chat_remember"(p_message_id uuid, p_content text, p_memory_type text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_chat_remember"(p_message_id uuid, p_content text, p_memory_type text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_chat_remember"(p_message_id uuid, p_content text, p_memory_type text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_chat_request_code_changes"(p_message_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := public.builder_chat_require_owner();
  v_card public.builder_chat_messages%rowtype;
  v_source public.builder_chat_messages%rowtype;
  v_approval public.builder_approvals%rowtype;
  v_job public.builder_jobs%rowtype;
  v_revision jsonb;
  v_feedback text;
  v_seed_ids jsonb := '{}'::jsonb;
  v_step public.builder_job_steps%rowtype;
  v_patch uuid;
  v_count integer;
  v_event uuid;
BEGIN
  SELECT m.* INTO v_card FROM public.builder_chat_messages m
    JOIN public.builder_chat_threads t ON t.id = m.thread_id
    WHERE m.id = p_message_id AND m.kind = 'proposal' AND m.role = 'bob' AND t.created_by = v_user
    FOR UPDATE OF m;
  IF v_card.id IS NULL OR v_card.payload->'revision'->>'kind' IS DISTINCT FROM 'implementation' THEN
    RAISE EXCEPTION 'Implementation correction card not found';
  END IF;
  IF v_card.payload ? 'revision_receipt' THEN RETURN (v_card.payload->>'revision_receipt')::uuid; END IF;
  v_revision := v_card.payload->'revision';
  v_feedback := v_revision->>'feedback';
  IF v_feedback IS NULL OR char_length(btrim(v_feedback)) < 40 OR char_length(v_feedback) > 4000 THEN
    RAISE EXCEPTION 'Bounded implementation feedback is required';
  END IF;
  SELECT * INTO v_source FROM public.builder_chat_messages
    WHERE id = (v_revision->>'source_message_id')::uuid
      AND thread_id = v_card.thread_id AND created_by = v_user
      AND id::text = v_card.payload->>'message_id' AND role = 'owner' AND status = 'done'
      AND payload->>'pm_purpose' IN ('pm', 'technical_review')
      AND payload->'research_consent'->>'allowed' = 'true';
  IF v_source.id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.builder_chat_messages WHERE thread_id = v_card.thread_id
      AND kind = 'proposal' AND payload->>'job_id' = v_revision->>'job_id'
  ) THEN RAISE EXCEPTION 'Corrections require an accepted same-thread handoff and completed approved PM turn'; END IF;

  -- Match the existing human decision RPC's approval-before-job lock order.
  SELECT * INTO v_approval FROM public.builder_approvals
    WHERE id = (v_revision->>'approval_id')::uuid FOR UPDATE;
  IF v_approval.id IS NULL OR v_approval.status <> 'pending'
    OR v_approval.approval_type <> 'implementation_review'
    OR v_approval.job_id::text IS DISTINCT FROM v_revision->>'job_id'
    OR v_approval.expires_at <= now() THEN
    RAISE EXCEPTION 'Human code review has moved or expired; prepare a fresh correction card';
  END IF;
  IF public.can_approve_action(v_user, v_approval.organization_id) IS DISTINCT FROM true
    OR (cardinality(v_approval.requested_from_users) > 0
      AND NOT (v_user = ANY(v_approval.requested_from_users))) THEN
    RAISE EXCEPTION 'User is not authorized to request implementation changes';
  END IF;
  SELECT * INTO v_job FROM public.builder_jobs WHERE id = v_approval.job_id FOR UPDATE;
  IF v_job.status IS DISTINCT FROM 'security_review' OR v_job.code_review_mode IS DISTINCT FROM 'human'
    OR v_job.code_review_status IS DISTINCT FROM 'pending'
    OR v_job.target_sha IS DISTINCT FROM v_approval.requested_target_sha
    OR v_job.target_sha IS DISTINCT FROM v_revision->>'target_sha'
    OR v_job.workspace_published_at IS NOT NULL OR v_job.workspace_published_head_sha IS NOT NULL
    OR v_job.workspace_pull_request_url IS NOT NULL THEN
    RAISE EXCEPTION 'Job is not at an unpublished pending human code review';
  END IF;
  PERFORM 1 FROM public.builder_job_steps WHERE job_id = v_job.id FOR UPDATE;
  IF NOT EXISTS (SELECT 1 FROM public.builder_job_steps WHERE job_id = v_job.id AND step_id = 'code_review' AND status = 'blocked')
    OR NOT EXISTS (SELECT 1 FROM public.builder_job_steps WHERE job_id = v_job.id AND step_id = 'security_review' AND status = 'completed')
    OR NOT EXISTS (SELECT 1 FROM public.builder_job_steps WHERE job_id = v_job.id AND step_id = 'test_suite' AND status = 'completed')
    OR NOT EXISTS (SELECT 1 FROM public.builder_job_steps WHERE job_id = v_job.id AND step_id = 'release_prep'
      AND status = 'pending' AND started_at IS NULL AND completed_at IS NULL)
    OR EXISTS (SELECT 1 FROM public.builder_job_steps WHERE job_id = v_job.id AND status = 'running')
    OR EXISTS (SELECT 1 FROM public.builder_worker_runs WHERE job_id = v_job.id AND status IN ('pending', 'running'))
    OR EXISTS (SELECT 1 FROM public.builder_model_runs WHERE job_id = v_job.id AND status IN ('pending', 'running'))
    OR EXISTS (SELECT 1 FROM public.builder_approvals WHERE job_id = v_job.id AND status = 'pending' AND id <> v_approval.id) THEN
    RAISE EXCEPTION 'Implementation correction requires idle completed verification and an untouched release';
  END IF;

  FOR v_step IN SELECT * FROM public.builder_job_steps WHERE job_id = v_job.id
    AND step_id IN ('frontend_implementation', 'backend_implementation')
  LOOP
    IF v_step.status = 'skipped' THEN CONTINUE; END IF;
    IF v_step.status <> 'completed' THEN RAISE EXCEPTION 'Implementation must be completed or scope-skipped'; END IF;
    SELECT count(*), (array_agg(r.patch_artifact_id))[1] INTO v_count, v_patch
      FROM public.builder_worker_runs r JOIN public.builder_artifacts a ON a.id = r.patch_artifact_id
      WHERE r.job_id = v_job.id AND r.step_id = v_step.id AND r.status = 'completed'
        AND r.organization_id = v_job.organization_id AND r.target_sha = v_job.target_sha
        AND r.profile = CASE v_step.step_id WHEN 'frontend_implementation' THEN 'frontend-verify' ELSE 'backend-verify' END
        AND a.job_id = v_job.id AND a.step_id = v_step.id AND a.status = 'final'
        AND a.artifact_type = 'code_implementation' AND a.id = ANY(v_approval.reviewed_artifact_ids);
    IF v_count <> 1 THEN RAISE EXCEPTION 'Exactly one reviewed verified patch per implementation lane is required'; END IF;
    v_seed_ids := v_seed_ids || jsonb_build_object(v_step.step_id, v_patch);
  END LOOP;
  IF v_seed_ids = '{}'::jsonb THEN RAISE EXCEPTION 'No reviewed implementation to correct'; END IF;

  UPDATE public.builder_approvals SET status = 'cancelled', decided_by = v_user,
    approval_comment = v_feedback, responded_at = now(), updated_at = now() WHERE id = v_approval.id;
  UPDATE public.builder_artifacts SET status = 'superseded', updated_at = now()
    WHERE job_id = v_job.id AND status = 'final' AND step_id IN (
      SELECT id FROM public.builder_job_steps WHERE job_id = v_job.id
        AND step_id IN ('frontend_implementation', 'backend_implementation', 'test_suite', 'security_review', 'code_review', 'release_prep'));
  UPDATE public.builder_job_steps SET status = 'pending', started_at = NULL, completed_at = NULL,
    result_summary = NULL, error = NULL, retryable = false, blocked_reason = NULL, updated_at = now()
    WHERE job_id = v_job.id AND step_id IN ('frontend_implementation', 'backend_implementation', 'test_suite', 'security_review', 'code_review')
      AND status <> 'skipped';
  UPDATE public.builder_jobs SET status = 'implementation_pending', code_review_status = 'pending',
    code_review_artifact_id = NULL, current_step_name = NULL, current_step_index = 2, last_error = NULL,
    code_review_revision = jsonb_build_object('approval_id', v_approval.id, 'feedback', v_feedback,
      'review_quote', v_source.content, 'source_message_id', v_source.id, 'requested_by', v_user,
      'seed_patch_ids', v_seed_ids, 'requested_at', now()),
    autopilot_state = CASE WHEN autopilot_requested_by IS NOT NULL THEN 'driving' ELSE autopilot_state END,
    updated_at = now() WHERE id = v_job.id;
  INSERT INTO public.builder_audit_events (
    organization_id, job_id, event_type, actor_user_id, actor_type, previous_value, new_value,
    change_summary, related_artifact_ids, related_approval_id
  ) VALUES (
    v_job.organization_id, v_job.id, 'job_status_changed', v_user, 'user',
    jsonb_build_object('status', 'security_review'),
    jsonb_build_object('status', 'implementation_pending', 'feedback', v_feedback,
      'source_message_id', v_source.id, 'seed_patch_ids', v_seed_ids),
    'Owner requested same-job implementation corrections; fresh verification, security and human review required',
    v_approval.reviewed_artifact_ids, v_approval.id
  ) RETURNING id INTO v_event;
  UPDATE public.builder_chat_messages SET payload = payload || jsonb_build_object(
    'revision_receipt', v_event, 'revision_requested_at', now()) WHERE id = v_card.id;
  RETURN v_event;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_chat_request_code_changes"(p_message_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_chat_request_code_changes"(p_message_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_chat_request_code_changes"(p_message_id uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."builder_chat_request_spec_revision"(p_message_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := public.builder_chat_require_owner();
  v_card public.builder_chat_messages%rowtype;
  v_approval public.builder_approvals%rowtype;
  v_job public.builder_jobs%rowtype;
  v_step public.builder_job_steps%rowtype;
  v_revision jsonb;
  v_feedback text;
  v_event uuid;
BEGIN
  SELECT m.* INTO v_card FROM public.builder_chat_messages m
    JOIN public.builder_chat_threads t ON t.id = m.thread_id
    WHERE m.id = p_message_id AND m.kind = 'proposal' AND t.created_by = v_user
    FOR UPDATE OF m;
  IF v_card.id IS NULL OR jsonb_typeof(v_card.payload->'revision') IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'Specification revision card not found';
  END IF;
  IF v_card.payload ? 'revision_receipt' THEN
    RETURN (v_card.payload->>'revision_receipt')::uuid;
  END IF;
  v_revision := v_card.payload->'revision';
  v_feedback := v_revision->>'feedback';
  IF v_feedback IS NULL OR char_length(btrim(v_feedback)) < 40 OR char_length(v_feedback) > 4000 THEN
    RAISE EXCEPTION 'Bounded specification feedback is required';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.builder_chat_messages m
    WHERE m.thread_id = v_card.thread_id AND m.kind = 'proposal'
      AND m.payload->>'job_id' = v_revision->>'job_id'
  ) OR NOT EXISTS (
    SELECT 1 FROM public.builder_chat_messages m
    WHERE m.id = (v_revision->>'source_message_id')::uuid
      AND m.thread_id = v_card.thread_id AND m.created_by = v_user
      AND m.id::text = v_card.payload->>'message_id' AND m.role = 'owner' AND m.status = 'done'
      AND m.payload->>'pm_purpose' IN ('pm', 'technical_review')
      AND m.payload->'research_consent'->>'allowed' = 'true'
  ) THEN RAISE EXCEPTION 'Revision must belong to an accepted owner handoff and approved PM turn'; END IF;

  -- Match the decision RPC's approval-before-job lock order.
  SELECT * INTO v_approval FROM public.builder_approvals
    WHERE id = (v_revision->>'approval_id')::uuid FOR UPDATE;
  IF v_approval.id IS NULL OR v_approval.status <> 'pending'
    OR v_approval.approval_type <> 'specification_review'
    OR v_approval.job_id::text IS DISTINCT FROM v_revision->>'job_id'
    OR v_approval.expires_at <= now() THEN
    RAISE EXCEPTION 'Specification review has moved or expired; prepare a fresh revision';
  END IF;
  IF public.can_approve_action(v_user, v_approval.organization_id) IS DISTINCT FROM true
    OR (cardinality(v_approval.requested_from_users) > 0
      AND NOT (v_user = ANY(v_approval.requested_from_users))) THEN
    RAISE EXCEPTION 'User is not authorized to revise this specification';
  END IF;
  SELECT * INTO v_job FROM public.builder_jobs WHERE id = v_approval.job_id FOR UPDATE;
  IF v_job.status IS DISTINCT FROM 'specification_ready'
    OR v_job.target_sha IS DISTINCT FROM v_approval.requested_target_sha
    OR v_job.target_sha IS DISTINCT FROM v_revision->>'target_sha' THEN
    RAISE EXCEPTION 'Job has moved beyond this specification gate';
  END IF;
  PERFORM 1 FROM public.builder_job_steps WHERE job_id = v_job.id FOR UPDATE;
  SELECT * INTO v_step FROM public.builder_job_steps
    WHERE job_id = v_job.id AND builder_mode = 'product_analyst';
  IF v_step.id IS NULL OR v_step.status <> 'completed'
    OR EXISTS (SELECT 1 FROM public.builder_job_steps WHERE job_id = v_job.id
      AND id <> v_step.id AND (status NOT IN ('pending', 'skipped')
        OR started_at IS NOT NULL OR completed_at IS NOT NULL))
    OR EXISTS (SELECT 1 FROM public.builder_worker_runs WHERE job_id = v_job.id)
    OR EXISTS (SELECT 1 FROM public.builder_model_runs WHERE job_id = v_job.id AND status = 'running') THEN
    RAISE EXCEPTION 'Revision is limited to an idle initial specification review';
  END IF;

  UPDATE public.builder_approvals SET status = 'cancelled', decided_by = v_user,
    approval_comment = v_feedback, responded_at = now(), updated_at = now()
    WHERE id = v_approval.id;
  UPDATE public.builder_artifacts SET status = 'superseded', updated_at = now()
    WHERE job_id = v_job.id AND id = ANY(v_approval.reviewed_artifact_ids) AND status = 'final';
  UPDATE public.builder_job_steps SET status = 'pending', started_at = NULL, completed_at = NULL,
    result_summary = NULL, error = NULL, retryable = false,
    input_context = COALESCE(input_context, '{}'::jsonb) || jsonb_build_object(
      'specification_revision', jsonb_build_object('feedback', v_feedback,
        'review_quote', v_revision->>'review_quote', 'approval_id', v_approval.id,
        'source_message_id', v_revision->>'source_message_id', 'requested_by', v_user)),
    updated_at = now() WHERE id = v_step.id;
  UPDATE public.builder_jobs SET status = 'analysis_pending', last_error = NULL,
    autopilot_state = CASE WHEN autopilot_requested_by IS NOT NULL THEN 'driving' ELSE autopilot_state END,
    updated_at = now() WHERE id = v_job.id;
  INSERT INTO public.builder_audit_events (
    organization_id, job_id, event_type, actor_user_id, actor_type,
    previous_value, new_value, change_summary, related_artifact_ids, related_approval_id
  ) VALUES (
    v_job.organization_id, v_job.id, 'job_status_changed', v_user, 'user',
    jsonb_build_object('status', 'specification_ready'),
    jsonb_build_object('status', 'analysis_pending', 'feedback', v_feedback, 'source_message_id', v_revision->>'source_message_id'),
    'Owner requested a revised specification on the existing job; no implementation approved',
    v_approval.reviewed_artifact_ids, v_approval.id
  ) RETURNING id INTO v_event;
  UPDATE public.builder_chat_messages
    SET payload = payload || jsonb_build_object('revision_receipt', v_event, 'revision_requested_at', now())
    WHERE id = v_card.id;
  RETURN v_event;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_chat_request_spec_revision"(p_message_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_chat_request_spec_revision"(p_message_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_chat_request_spec_revision"(p_message_id uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."builder_chat_require_owner"()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_grand_master() THEN
    RAISE EXCEPTION 'Bob Builder chat is limited to the platform owner' USING ERRCODE = '42501';
  END IF;
  RETURN auth.uid();
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_chat_require_owner"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_chat_require_owner"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_chat_require_owner"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."builder_chat_require_owner"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_chat_reserve_proposal"(p_message_id uuid, p_token text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := public.builder_chat_require_owner();
  v_id uuid;
BEGIN
  IF p_token IS NULL OR length(p_token) < 8 OR length(p_token) > 120 THEN RAISE EXCEPTION 'A reservation token is required'; END IF;
  UPDATE public.builder_chat_messages
     SET payload = payload || jsonb_build_object('creating_token', p_token, 'creating_by', v_user, 'creating_at', now())
   WHERE id = p_message_id AND kind = 'proposal' AND NOT (payload ? 'job_id')
     AND (NOT (payload ? 'creating_token')
          OR payload->>'creating_token' = p_token
          OR (payload->>'creating_at')::timestamptz < now() - interval '5 minutes')
  RETURNING id INTO v_id;
  RETURN v_id IS NOT NULL;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_chat_reserve_proposal"(p_message_id uuid, p_token text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_chat_reserve_proposal"(p_message_id uuid, p_token text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_chat_reserve_proposal"(p_message_id uuid, p_token text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."builder_chat_reserve_proposal"(p_message_id uuid, p_token text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_chat_send"(p_thread_id uuid, p_content text, p_client_request_id text DEFAULT NULL::text, p_context jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := public.builder_chat_require_owner();
  v_status text;
  v_id uuid;
  v_content text := btrim(coalesce(p_content, ''));
  v_context jsonb := CASE WHEN jsonb_typeof(p_context) = 'object' THEN p_context ELSE '{}'::jsonb END;
BEGIN
  IF v_content = '' THEN RAISE EXCEPTION 'Message is empty'; END IF;
  IF char_length(v_content) > 20000 THEN RAISE EXCEPTION 'Message is longer than 20000 characters'; END IF;
  IF octet_length(v_context::text) > 4000 THEN RAISE EXCEPTION 'Builder context is too large'; END IF;
  SELECT status INTO v_status FROM public.builder_chat_threads WHERE id = p_thread_id FOR UPDATE;
  IF v_status IS NULL THEN RAISE EXCEPTION 'Builder chat not found'; END IF;
  IF v_status = 'closed' THEN RAISE EXCEPTION 'Builder chat is closed'; END IF;
  IF p_client_request_id IS NOT NULL THEN
    SELECT id INTO v_id FROM public.builder_chat_messages WHERE thread_id = p_thread_id AND client_request_id = p_client_request_id;
    IF v_id IS NOT NULL THEN RETURN v_id; END IF;
  END IF;
  INSERT INTO public.builder_chat_messages (thread_id, role, kind, content, payload, status, client_request_id, created_by)
  VALUES (p_thread_id, 'owner', 'message', v_content, jsonb_build_object('context', v_context), 'queued', left(p_client_request_id, 80), v_user)
  RETURNING id INTO v_id;
  UPDATE public.builder_chat_threads SET last_activity_at = now(), updated_at = now() WHERE id = p_thread_id;
  RETURN v_id;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_chat_send"(p_thread_id uuid, p_content text, p_client_request_id text, p_context jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_chat_send"(p_thread_id uuid, p_content text, p_client_request_id text, p_context jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_chat_send"(p_thread_id uuid, p_content text, p_client_request_id text, p_context jsonb) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."builder_chat_send"(p_thread_id uuid, p_content text, p_client_request_id text, p_context jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_chat_send_pm"(p_thread_id uuid, p_content text, p_client_request_id text, p_purpose text DEFAULT 'pm'::text, p_evidence_summary text DEFAULT ''::text, p_files jsonb DEFAULT '[]'::jsonb, p_urls jsonb DEFAULT '[]'::jsonb, p_web_search boolean DEFAULT false, p_allow_cloud boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := public.builder_chat_require_owner();
  v_id uuid;
  v_existing public.builder_chat_messages%ROWTYPE;
  v_hash text;
BEGIN
  IF p_purpose IS NULL OR p_purpose NOT IN ('pm', 'qa', 'technical_review') THEN
    RAISE EXCEPTION 'Cloud PM purpose must be pm, qa or technical_review';
  END IF;
  IF p_evidence_summary IS NULL OR char_length(p_evidence_summary) > 6000 THEN
    RAISE EXCEPTION 'Reviewed evidence summary must be at most 6000 characters';
  END IF;
  v_hash := encode(extensions.digest(convert_to(p_evidence_summary, 'UTF8'), 'sha256'), 'hex');
  PERFORM 1 FROM public.builder_chat_threads
    WHERE id = p_thread_id AND created_by = v_user AND status <> 'closed' FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Open Builder chat not found for this owner'; END IF;
  SELECT * INTO v_existing FROM public.builder_chat_messages
    WHERE thread_id = p_thread_id AND client_request_id = p_client_request_id;
  IF FOUND AND (
    v_existing.payload->>'pm_purpose' IS DISTINCT FROM p_purpose
    OR v_existing.payload->>'evidence_summary' IS DISTINCT FROM p_evidence_summary
  ) THEN
    RAISE EXCEPTION 'Request id was already used with different PM purpose or summary';
  END IF;
  -- The existing function enforces ownership, consent, attachment scope and exact retries.
  v_id := public.builder_chat_send_research(
    p_thread_id, p_content, p_client_request_id, p_files, p_urls, p_web_search, p_allow_cloud
  );
  UPDATE public.builder_chat_messages SET payload =
    payload || jsonb_build_object('pm_purpose', p_purpose, 'evidence_summary', p_evidence_summary,
      'research_consent', (payload->'research_consent') || jsonb_build_object(
        'pm_purpose', p_purpose, 'evidence_summary_sha256', v_hash))
    WHERE id = v_id;
  RETURN v_id;
END;
$function$;
COMMENT ON FUNCTION "public"."builder_chat_send_pm"(p_thread_id uuid, p_content text, p_client_request_id text, p_purpose text, p_evidence_summary text, p_files jsonb, p_urls jsonb, p_web_search boolean, p_allow_cloud boolean) IS 'Owner-approved isolated Ollama Cloud PM/QA packet. Fixed purpose model, human-reviewed non-sensitive summary, no private history/source or automatic inference fallback. Advisory briefs do not create jobs.';
REVOKE ALL ON FUNCTION "public"."builder_chat_send_pm"(p_thread_id uuid, p_content text, p_client_request_id text, p_purpose text, p_evidence_summary text, p_files jsonb, p_urls jsonb, p_web_search boolean, p_allow_cloud boolean) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_chat_send_pm"(p_thread_id uuid, p_content text, p_client_request_id text, p_purpose text, p_evidence_summary text, p_files jsonb, p_urls jsonb, p_web_search boolean, p_allow_cloud boolean) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_chat_send_pm"(p_thread_id uuid, p_content text, p_client_request_id text, p_purpose text, p_evidence_summary text, p_files jsonb, p_urls jsonb, p_web_search boolean, p_allow_cloud boolean) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."builder_chat_send_pm"(p_thread_id uuid, p_content text, p_client_request_id text, p_purpose text, p_evidence_summary text, p_files jsonb, p_urls jsonb, p_web_search boolean, p_allow_cloud boolean) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_chat_send_research"(p_thread_id uuid, p_content text, p_client_request_id text, p_files jsonb DEFAULT '[]'::jsonb, p_urls jsonb DEFAULT '[]'::jsonb, p_web_search boolean DEFAULT false, p_allow_cloud boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := public.builder_chat_require_owner();
  v_id uuid;
  v_existing public.builder_chat_messages%ROWTYPE;
  v_file jsonb;
  v_url jsonb;
  v_payload jsonb;
  v_prefix text;
  v_size bigint;
BEGIN
  IF p_allow_cloud IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'Public cloud research requires explicit non-sensitive-content approval';
  END IF;
  IF p_client_request_id IS NULL OR char_length(p_client_request_id) NOT BETWEEN 1 AND 80 THEN
    RAISE EXCEPTION 'Research requires a request id of 1 to 80 characters';
  END IF;
  IF p_content IS NULL OR char_length(btrim(p_content)) NOT BETWEEN 1 AND 2000 THEN
    RAISE EXCEPTION 'Research question must be 1 to 2000 characters';
  END IF;
  IF jsonb_typeof(p_files) IS DISTINCT FROM 'array' OR jsonb_array_length(p_files) > 5
     OR jsonb_typeof(p_urls) IS DISTINCT FROM 'array' OR jsonb_array_length(p_urls) > 6
     OR octet_length(p_files::text) > 100000 THEN
    RAISE EXCEPTION 'Research accepts five files, six URLs and bounded extracted text';
  END IF;
  PERFORM 1 FROM public.builder_chat_threads
   WHERE id = p_thread_id AND created_by = v_user AND status <> 'closed' FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Open Builder chat not found for this owner'; END IF;

  SELECT * INTO v_existing FROM public.builder_chat_messages
   WHERE thread_id = p_thread_id AND client_request_id = p_client_request_id;
  IF FOUND THEN
    IF v_existing.created_by IS DISTINCT FROM v_user OR v_existing.content IS DISTINCT FROM btrim(p_content)
       OR v_existing.payload->>'research_mode' IS DISTINCT FROM 'public_cloud'
       OR v_existing.payload->'research_files' IS DISTINCT FROM p_files
       OR v_existing.payload->'research_urls' IS DISTINCT FROM p_urls
       OR v_existing.payload->'web_search' IS DISTINCT FROM to_jsonb(coalesce(p_web_search, false)) THEN
      RAISE EXCEPTION 'Request id was already used with different research or consent';
    END IF;
    RETURN v_existing.id;
  END IF;
  IF (SELECT count(DISTINCT f->>'id') FROM jsonb_array_elements(p_files) f) <> jsonb_array_length(p_files) THEN
    RAISE EXCEPTION 'Research attachments must have unique ids';
  END IF;
  FOR v_file IN SELECT value FROM jsonb_array_elements(p_files) LOOP
    IF jsonb_typeof(v_file) <> 'object'
       OR coalesce(v_file->>'id', '') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR coalesce(v_file->>'sha256', '') !~ '^[0-9a-f]{64}$'
       OR char_length(coalesce(v_file->>'file_name', '')) NOT BETWEEN 1 AND 255
       OR coalesce(v_file->>'file_type', '') NOT IN (
         'image/jpeg', 'image/png', 'image/webp', 'application/pdf', 'text/plain', 'text/csv',
         'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
         'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
       ) OR char_length(coalesce(v_file->>'extracted_text', '')) > 12000 THEN
      RAISE EXCEPTION 'Invalid research attachment metadata';
    END IF;
    v_size := (v_file->>'file_size_bytes')::bigint;
    IF v_size IS NULL OR v_size <= 0 OR v_size > 20971520
       OR (v_file->>'file_type' LIKE 'image/%' AND v_size > 10485760)
       OR (v_file->>'file_type' NOT LIKE 'image/%' AND btrim(coalesce(v_file->>'extracted_text', '')) = '') THEN
      RAISE EXCEPTION 'Research file is too large or has no readable document text';
    END IF;
    v_prefix := 'desktop/' || v_user::text || '/builder-chat/' || p_thread_id::text || '/' || (v_file->>'id') || '-';
    IF v_file->>'storage_path' IS NULL OR left(v_file->>'storage_path', length(v_prefix)) <> v_prefix
       OR substring(v_file->>'storage_path' FROM length(v_prefix) + 1) !~ '^[A-Za-z0-9._-]{1,180}$'
       OR NOT EXISTS (
         SELECT 1 FROM storage.objects o WHERE o.bucket_id = 'bob-uploads'
           AND o.name = v_file->>'storage_path' AND o.owner_id = v_user::text
       ) THEN
      RAISE EXCEPTION 'Research file is not owned by this chat owner';
    END IF;
  END LOOP;
  FOR v_url IN SELECT value FROM jsonb_array_elements(p_urls) LOOP
    IF jsonb_typeof(v_url) <> 'string' OR char_length(v_url #>> '{}') > 1000
       OR (v_url #>> '{}') !~ '^https://[^/?#@]+/[^?#]*$' THEN
      RAISE EXCEPTION 'Research URLs must be public HTTPS without query strings or credentials';
    END IF;
  END LOOP;
  v_payload := jsonb_build_object(
    'research_mode', 'public_cloud', 'research_files', p_files, 'research_urls', p_urls,
    'web_search', coalesce(p_web_search, false),
    'research_consent', jsonb_build_object(
      'allowed', true, 'policy_version', 'builder_research_v1',
      'actor_user_id', v_user, 'recorded_at', now(),
      'attachment_ids', (SELECT coalesce(jsonb_agg(f->>'id'), '[]'::jsonb) FROM jsonb_array_elements(p_files) f),
      'raw_images_allowed', true, 'raw_documents_allowed_if_supported', true
    )
  );
  INSERT INTO public.builder_chat_messages(thread_id, role, kind, content, payload, status, client_request_id, created_by)
  VALUES (p_thread_id, 'owner', 'message', btrim(p_content), v_payload, 'queued', p_client_request_id, v_user)
  RETURNING id INTO v_id;
  UPDATE public.builder_chat_threads SET last_activity_at = now(), updated_at = now() WHERE id = p_thread_id;
  RETURN v_id;
END;
$function$;
COMMENT ON FUNCTION "public"."builder_chat_send_research"(p_thread_id uuid, p_content text, p_client_request_id text, p_files jsonb, p_urls jsonb, p_web_search boolean, p_allow_cloud boolean) IS 'Explicit per-message owner attestation for isolated Ollama Cloud research. No earlier history, private repository source, credentials or tenant records are included. Raw images require verified vision support; documents use extracted text until native document support is verified.';
REVOKE ALL ON FUNCTION "public"."builder_chat_send_research"(p_thread_id uuid, p_content text, p_client_request_id text, p_files jsonb, p_urls jsonb, p_web_search boolean, p_allow_cloud boolean) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_chat_send_research"(p_thread_id uuid, p_content text, p_client_request_id text, p_files jsonb, p_urls jsonb, p_web_search boolean, p_allow_cloud boolean) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_chat_send_research"(p_thread_id uuid, p_content text, p_client_request_id text, p_files jsonb, p_urls jsonb, p_web_search boolean, p_allow_cloud boolean) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."builder_chat_send_research"(p_thread_id uuid, p_content text, p_client_request_id text, p_files jsonb, p_urls jsonb, p_web_search boolean, p_allow_cloud boolean) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_chat_thread_close"(p_thread_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := public.builder_chat_require_owner();
BEGIN
  UPDATE public.builder_chat_threads SET status = 'closed', closed_at = now(), updated_at = now()
   WHERE id = p_thread_id AND status <> 'closed';
  IF NOT FOUND THEN RAISE EXCEPTION 'Builder chat not found or already closed'; END IF;
  UPDATE public.builder_chat_messages SET status = 'failed', completed_at = now()
   WHERE thread_id = p_thread_id AND status = 'queued';
  INSERT INTO public.builder_chat_messages (thread_id, role, kind, content, created_by)
  VALUES (p_thread_id, 'system', 'status', 'Chat closed by the owner.', v_user);
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_chat_thread_close"(p_thread_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_chat_thread_close"(p_thread_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_chat_thread_close"(p_thread_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."builder_chat_thread_close"(p_thread_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_chat_thread_open"(p_title text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := public.builder_chat_require_owner();
  v_id uuid;
  v_title text := left(coalesce(nullif(btrim(p_title), ''), 'Bob Builder chat'), 160);
BEGIN
  INSERT INTO public.builder_chat_threads (created_by, title) VALUES (v_user, v_title) RETURNING id INTO v_id;
  INSERT INTO public.builder_chat_messages (thread_id, role, kind, content, created_by)
  VALUES (v_id, 'system', 'status', 'Bob Builder chat opened. This lane is separate from in-app Bob.', v_user);
  RETURN v_id;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_chat_thread_open"(p_title text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_chat_thread_open"(p_title text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_chat_thread_open"(p_title text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."builder_chat_thread_open"(p_title text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_claim_aggregate_security_review"(_job_id uuid, _security_step_id uuid, _implementation_worker_run_ids uuid[], _runner_id text, _expected_target_sha text, _timeout_seconds integer DEFAULT 300)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _job public.builder_jobs%rowtype; _security_step public.builder_job_steps%rowtype; _test_step public.builder_job_steps%rowtype;
  _run public.builder_worker_runs%rowtype; _patch_ids uuid[]; _manifest_ids uuid[]; _log_ids uuid[];
  _lease_token text := encode(extensions.gen_random_bytes(32), 'hex'); _lease_hash text; _idempotency_key text; _run_count integer;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  IF NULLIF(btrim(_runner_id), '') IS NULL THEN RAISE EXCEPTION 'runner_id is required'; END IF;
  IF _timeout_seconds < 60 OR _timeout_seconds > 900 THEN RAISE EXCEPTION 'security review timeout is invalid'; END IF;
  IF cardinality(_implementation_worker_run_ids) NOT BETWEEN 1 AND 2
     OR (SELECT count(DISTINCT id) FROM unnest(_implementation_worker_run_ids) id) <> cardinality(_implementation_worker_run_ids) THEN
    RAISE EXCEPTION 'One or two distinct implementation worker runs are required';
  END IF;
  IF EXISTS (SELECT 1 FROM public.builder_worker_runs WHERE status = 'running') THEN RAISE EXCEPTION 'Another Builder worker already holds the active lease'; END IF;

  SELECT * INTO _job FROM public.builder_jobs WHERE id = _job_id FOR UPDATE;
  SELECT * INTO _security_step FROM public.builder_job_steps WHERE id = _security_step_id AND job_id = _job_id FOR UPDATE;
  SELECT * INTO _test_step FROM public.builder_job_steps WHERE job_id = _job_id AND step_id = 'test_suite' FOR UPDATE;
  IF _job.id IS NULL OR _job.status <> 'testing' THEN RAISE EXCEPTION 'Job is not ready for security review'; END IF;
  IF _job.target_sha IS NULL OR _expected_target_sha IS DISTINCT FROM _job.target_sha THEN RAISE EXCEPTION 'Security review target SHA is stale or missing'; END IF;
  IF _security_step.id IS NULL OR _security_step.step_id <> 'security_review' OR _security_step.builder_mode <> 'qa_security_reviewer'
     OR (_security_step.status <> 'pending' AND NOT (_security_step.status = 'failed' AND _security_step.retryable)) THEN
    RAISE EXCEPTION 'Security review step is not pending';
  END IF;
  IF _test_step.id IS NULL OR _test_step.builder_mode <> 'qa_security_reviewer' OR _test_step.status NOT IN ('pending', 'completed') THEN
    RAISE EXCEPTION 'Test-suite step is not ready';
  END IF;

  SELECT count(*), array_agg(run.patch_artifact_id ORDER BY run.profile, run.id)
  INTO _run_count, _patch_ids
  FROM public.builder_worker_runs run
  WHERE run.id = ANY(_implementation_worker_run_ids) AND run.job_id = _job.id AND run.status = 'completed'
    AND run.organization_id = _job.organization_id AND run.target_sha = _job.target_sha
    AND run.profile IN ('frontend-verify', 'backend-verify');
  IF _run_count <> cardinality(_implementation_worker_run_ids) OR array_position(_patch_ids, NULL) IS NOT NULL THEN
    RAISE EXCEPTION 'Completed implementation worker evidence is missing or stale';
  END IF;
  IF _run_count = 2 AND (
    SELECT count(DISTINCT profile) FROM public.builder_worker_runs WHERE id = ANY(_implementation_worker_run_ids)
  ) <> 2 THEN RAISE EXCEPTION 'Aggregate review requires distinct frontend and backend worker profiles'; END IF;

  SELECT array_agg(artifact.id ORDER BY run.profile, run.id)
  INTO _manifest_ids
  FROM public.builder_worker_runs run
  JOIN public.builder_artifacts artifact ON artifact.id = ANY(run.output_artifact_ids)
  WHERE run.id = ANY(_implementation_worker_run_ids) AND artifact.job_id = _job.id
    AND artifact.step_id = run.step_id AND artifact.artifact_type = 'changed_file_manifest' AND artifact.status = 'final';
  SELECT array_agg(artifact.id ORDER BY run.profile, run.id)
  INTO _log_ids
  FROM public.builder_worker_runs run
  JOIN public.builder_artifacts artifact ON artifact.id = ANY(run.output_artifact_ids)
  WHERE run.id = ANY(_implementation_worker_run_ids) AND artifact.job_id = _job.id
    AND artifact.step_id = run.step_id AND artifact.artifact_type = 'build_logs' AND artifact.status = 'final';
  IF cardinality(_manifest_ids) <> _run_count OR cardinality(_log_ids) <> _run_count THEN
    RAISE EXCEPTION 'Implementation verification evidence is incomplete';
  END IF;

  UPDATE public.builder_job_steps SET status = 'completed', completed_at = now(),
    result_summary = 'Accepted isolated implementation verification evidence',
    artifact_ids = _patch_ids || _manifest_ids || _log_ids, updated_at = now() WHERE id = _test_step.id;
  UPDATE public.builder_job_steps SET status = 'running', attempt_count = attempt_count + 1, started_at = now(), retryable = false,
    input_context = jsonb_build_object('implementation_worker_run_ids', _implementation_worker_run_ids,
      'patch_artifact_ids', _patch_ids, 'manifest_artifact_ids', _manifest_ids,
      'build_log_artifact_ids', _log_ids, 'target_sha', _job.target_sha), updated_at = now()
  WHERE id = _security_step.id;
  UPDATE public.builder_jobs SET status = 'security_review', current_step_name = _security_step.step_id,
    current_step_index = _security_step.ordinal_position, updated_at = now() WHERE id = _job.id;

  _lease_hash := encode(extensions.digest(_lease_token, 'sha256'), 'hex');
  _idempotency_key := _job.id::text || '::security-aggregate::' || _job.target_sha || '::'
    || encode(extensions.digest(array_to_string(_patch_ids || _manifest_ids, '::'), 'sha256'), 'hex');
  INSERT INTO public.builder_worker_runs (
    organization_id, job_id, step_id, runner_id, worker_isolation_level, command, command_args,
    environment_variables_snapshot, profile, target_sha, patch_artifact_id, idempotency_key,
    lease_token_hash, lease_expires_at, heartbeat_at, status, started_at, timeout_seconds
  ) VALUES (
    _job.organization_id, _job.id, _security_step.id, _runner_id, 'container', 'security-review', ARRAY['security-review'],
    '{}'::jsonb, 'security-review', _job.target_sha, _patch_ids[1], _idempotency_key,
    _lease_hash, now() + make_interval(secs => _timeout_seconds), now(), 'running', now(), _timeout_seconds
  )
  ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO UPDATE
  SET runner_id = EXCLUDED.runner_id, lease_token_hash = EXCLUDED.lease_token_hash,
      lease_expires_at = EXCLUDED.lease_expires_at, heartbeat_at = EXCLUDED.heartbeat_at,
      status = 'running', started_at = now(), completed_at = NULL,
      output_artifact_ids = '{}', review_summary = '{}'::jsonb, updated_at = now()
  RETURNING * INTO _run;
  INSERT INTO public.builder_audit_events (organization_id, job_id, event_type, actor_type, new_value, change_summary, related_artifact_ids)
  VALUES (_job.organization_id, _job.id, 'step_started', 'builder_mode',
    jsonb_build_object('step_id', _security_step.step_id, 'worker_run_id', _run.id, 'target_sha', _job.target_sha,
      'implementation_worker_run_ids', _implementation_worker_run_ids),
    'Aggregate independent security review worker claimed', _patch_ids || _manifest_ids || _log_ids);
  RETURN jsonb_build_object('run_id', _run.id, 'lease_token', _lease_token, 'lease_expires_at', _run.lease_expires_at,
    'organization_id', _job.organization_id, 'job_id', _job.id, 'step_id', _security_step.id, 'target_sha', _job.target_sha,
    'profile', 'security-review', 'patch_artifact_ids', _patch_ids, 'manifest_artifact_ids', _manifest_ids,
    'build_log_artifact_ids', _log_ids);
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_claim_aggregate_security_review"(_job_id uuid, _security_step_id uuid, _implementation_worker_run_ids uuid[], _runner_id text, _expected_target_sha text, _timeout_seconds integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_claim_aggregate_security_review"(_job_id uuid, _security_step_id uuid, _implementation_worker_run_ids uuid[], _runner_id text, _expected_target_sha text, _timeout_seconds integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_claim_aggregate_security_review"(_job_id uuid, _security_step_id uuid, _implementation_worker_run_ids uuid[], _runner_id text, _expected_target_sha text, _timeout_seconds integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_claim_backend_worker"(_job_id uuid, _step_id uuid, _patch_artifact_id uuid, _runner_id text, _expected_target_sha text, _timeout_seconds integer DEFAULT 900)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _job public.builder_jobs%rowtype;
  _step public.builder_job_steps%rowtype;
  _patch public.builder_artifacts%rowtype;
  _run public.builder_worker_runs%rowtype;
  _lease_token text := encode(extensions.gen_random_bytes(32), 'hex');
  _lease_token_hash text;
  _idempotency_key text;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  IF NULLIF(btrim(_runner_id), '') IS NULL THEN RAISE EXCEPTION 'runner_id is required'; END IF;
  IF _timeout_seconds < 60 OR _timeout_seconds > 3600 THEN RAISE EXCEPTION 'timeout must be between 60 and 3600 seconds'; END IF;

  UPDATE public.builder_job_steps step
  SET status = 'failed', retryable = true, error = 'Backend worker lease expired', updated_at = now()
  FROM public.builder_worker_runs run
  WHERE run.step_id = step.id AND run.profile = 'backend-verify'
    AND run.status = 'running' AND run.lease_expires_at <= now();
  UPDATE public.builder_worker_runs
  SET status = 'timeout', completed_at = now(), lease_token_hash = NULL, updated_at = now()
  WHERE profile = 'backend-verify' AND status = 'running' AND lease_expires_at <= now();

  SELECT * INTO _job FROM public.builder_jobs WHERE id = _job_id FOR UPDATE;
  SELECT * INTO _step FROM public.builder_job_steps WHERE id = _step_id AND job_id = _job_id FOR UPDATE;
  SELECT * INTO _patch FROM public.builder_artifacts WHERE id = _patch_artifact_id AND job_id = _job_id;

  IF _job.id IS NULL OR _job.status <> 'implementation_pending' THEN RAISE EXCEPTION 'Job is not ready for backend implementation'; END IF;
  IF _job.target_sha IS NULL OR _expected_target_sha IS DISTINCT FROM _job.target_sha THEN RAISE EXCEPTION 'Worker target SHA is stale or missing'; END IF;
  IF _step.id IS NULL OR _step.builder_mode <> 'backend_engineer' THEN RAISE EXCEPTION 'Backend Engineer step is missing'; END IF;
  IF _step.status <> 'pending' AND NOT (_step.status = 'failed' AND _step.retryable) THEN RAISE EXCEPTION 'Backend Engineer step cannot be claimed'; END IF;
  IF _patch.id IS NULL OR _patch.step_id IS DISTINCT FROM _step.id OR _patch.artifact_type <> 'code_implementation' OR _patch.status <> 'final' OR _patch.checksum IS NULL THEN
    RAISE EXCEPTION 'A final generated backend patch artifact is required';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.builder_model_runs model_run
    WHERE model_run.job_id = _job.id AND model_run.step_id = _step.id
      AND model_run.status = 'completed' AND _patch.id = ANY(model_run.output_artifact_ids)
      AND EXISTS (
        SELECT 1 FROM public.builder_job_steps product_step
        JOIN public.builder_artifacts product_artifact ON product_artifact.step_id = product_step.id
        WHERE product_step.job_id = _job.id AND product_step.builder_mode = 'product_analyst' AND product_step.status = 'completed'
          AND product_artifact.artifact_type = 'product_specification' AND product_artifact.status = 'final'
          AND product_artifact.id = ANY(model_run.input_artifact_ids)
      )
  ) THEN RAISE EXCEPTION 'Patch provenance does not include the completed product specification'; END IF;
  IF EXISTS (SELECT 1 FROM public.builder_worker_runs WHERE status = 'running') THEN RAISE EXCEPTION 'Another Builder worker already holds the active lease'; END IF;

  _idempotency_key := _job.id::text || '::' || _step.id::text || '::' || _job.target_sha || '::' || _patch.checksum
    || CASE WHEN _job.code_review_revision->>'approval_id' IS NOT NULL
      THEN '::correction::' || (_job.code_review_revision->>'approval_id') ELSE '' END;
  IF EXISTS (SELECT 1 FROM public.builder_worker_runs WHERE idempotency_key = _idempotency_key AND status = 'completed') THEN
    RAISE EXCEPTION 'This exact backend patch was already verified';
  END IF;
  _lease_token_hash := encode(extensions.digest(_lease_token, 'sha256'), 'hex');

  INSERT INTO public.builder_worker_runs (
    organization_id, job_id, step_id, runner_id, worker_isolation_level,
    command, command_args, environment_variables_snapshot, profile, target_sha,
    patch_artifact_id, idempotency_key, lease_token_hash, lease_expires_at,
    heartbeat_at, status, started_at, timeout_seconds
  ) VALUES (
    _job.organization_id, _job.id, _step.id, _runner_id, 'container',
    'backend-verify', ARRAY['backend-verify'], '{}'::jsonb, 'backend-verify', _job.target_sha,
    _patch.id, _idempotency_key, _lease_token_hash, now() + make_interval(secs => _timeout_seconds),
    now(), 'running', now(), _timeout_seconds
  )
  ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO UPDATE
  SET runner_id = EXCLUDED.runner_id, lease_token_hash = EXCLUDED.lease_token_hash,
      lease_expires_at = EXCLUDED.lease_expires_at, heartbeat_at = EXCLUDED.heartbeat_at,
      status = 'running', started_at = now(), completed_at = NULL, updated_at = now()
  RETURNING * INTO _run;

  UPDATE public.builder_job_steps
  SET status = 'running', attempt_count = attempt_count + 1, started_at = now(), completed_at = NULL,
      retryable = false, error = NULL,
      input_context = jsonb_build_object('patch_artifact_id', _patch.id, 'target_sha', _job.target_sha, 'verification_scope', 'static_backend_patch'), updated_at = now()
  WHERE id = _step.id;
  UPDATE public.builder_jobs SET status = 'building', current_step_name = _step.step_id,
    current_step_index = _step.ordinal_position, updated_at = now() WHERE id = _job.id;
  INSERT INTO public.builder_audit_events (organization_id, job_id, event_type, actor_type, previous_value, new_value, change_summary, related_artifact_ids)
  VALUES (_job.organization_id, _job.id, 'step_started', 'builder_mode',
    jsonb_build_object('job_status', 'implementation_pending', 'step_status', _step.status),
    jsonb_build_object('job_status', 'building', 'step_status', 'running', 'worker_run_id', _run.id, 'target_sha', _job.target_sha, 'verification_scope', 'static_backend_patch'),
    'Backend Engineer static verification lease claimed', ARRAY[_patch.id]);

  RETURN jsonb_build_object(
    'run_id', _run.id, 'lease_token', _lease_token, 'lease_expires_at', _run.lease_expires_at,
    'job_id', _job.id, 'step_id', _step.id, 'organization_id', _job.organization_id,
    'profile', 'backend-verify', 'target_sha', _job.target_sha, 'patch_artifact_id', _patch.id
  );
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_claim_backend_worker"(_job_id uuid, _step_id uuid, _patch_artifact_id uuid, _runner_id text, _expected_target_sha text, _timeout_seconds integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_claim_backend_worker"(_job_id uuid, _step_id uuid, _patch_artifact_id uuid, _runner_id text, _expected_target_sha text, _timeout_seconds integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_claim_backend_worker"(_job_id uuid, _step_id uuid, _patch_artifact_id uuid, _runner_id text, _expected_target_sha text, _timeout_seconds integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_claim_frontend_worker"(_job_id uuid, _step_id uuid, _patch_artifact_id uuid, _runner_id text, _expected_target_sha text, _timeout_seconds integer DEFAULT 900)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _job public.builder_jobs%rowtype;
  _step public.builder_job_steps%rowtype;
  _patch public.builder_artifacts%rowtype;
  _run public.builder_worker_runs%rowtype;
  _lease_token text := encode(extensions.gen_random_bytes(32), 'hex');
  _lease_token_hash text;
  _idempotency_key text;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  IF NULLIF(btrim(_runner_id), '') IS NULL THEN RAISE EXCEPTION 'runner_id is required'; END IF;
  IF _timeout_seconds < 60 OR _timeout_seconds > 3600 THEN RAISE EXCEPTION 'timeout must be between 60 and 3600 seconds'; END IF;

  UPDATE public.builder_job_steps step
  SET status = 'failed', retryable = true, error = 'Frontend worker lease expired', updated_at = now()
  FROM public.builder_worker_runs run
  WHERE run.step_id = step.id AND run.status = 'running' AND run.lease_expires_at <= now();
  UPDATE public.builder_worker_runs
  SET status = 'timeout', completed_at = now(), lease_token_hash = NULL, updated_at = now()
  WHERE status = 'running' AND lease_expires_at <= now();

  SELECT * INTO _job FROM public.builder_jobs WHERE id = _job_id FOR UPDATE;
  SELECT * INTO _step FROM public.builder_job_steps WHERE id = _step_id AND job_id = _job_id FOR UPDATE;
  SELECT * INTO _patch FROM public.builder_artifacts WHERE id = _patch_artifact_id AND job_id = _job_id;

  IF _job.id IS NULL OR _job.status <> 'implementation_pending' THEN RAISE EXCEPTION 'Job is not ready for frontend implementation'; END IF;
  IF _job.target_sha IS NULL OR _expected_target_sha IS DISTINCT FROM _job.target_sha THEN RAISE EXCEPTION 'Worker target SHA is stale or missing'; END IF;
  IF _step.id IS NULL OR _step.builder_mode <> 'frontend_engineer' THEN RAISE EXCEPTION 'Frontend Engineer step is missing'; END IF;
  IF _step.status <> 'pending' AND NOT (_step.status = 'failed' AND _step.retryable) THEN RAISE EXCEPTION 'Frontend Engineer step cannot be claimed'; END IF;
  IF _patch.id IS NULL OR _patch.step_id IS DISTINCT FROM _step.id OR _patch.artifact_type <> 'code_implementation' OR _patch.status <> 'final' OR _patch.checksum IS NULL THEN
    RAISE EXCEPTION 'A final generated patch artifact is required';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.builder_model_runs model_run
    WHERE model_run.job_id = _job.id AND model_run.step_id = _step.id
      AND model_run.status = 'completed' AND _patch.id = ANY(model_run.output_artifact_ids)
      AND EXISTS (
        SELECT 1 FROM public.builder_job_steps ux_step
        JOIN public.builder_artifacts ux_artifact ON ux_artifact.step_id = ux_step.id
        WHERE ux_step.job_id = _job.id AND ux_step.builder_mode = 'ux_designer' AND ux_step.status = 'completed'
          AND ux_artifact.artifact_type = 'ui_design_plan' AND ux_artifact.status = 'final'
          AND ux_artifact.id = ANY(model_run.input_artifact_ids)
      )
  ) THEN RAISE EXCEPTION 'Patch provenance does not include the completed UX design'; END IF;
  IF EXISTS (SELECT 1 FROM public.builder_worker_runs WHERE status = 'running') THEN RAISE EXCEPTION 'Another Builder worker already holds the active lease'; END IF;

  _idempotency_key := _job.id::text || '::' || _step.id::text || '::' || _job.target_sha || '::' || _patch.checksum
    || CASE WHEN _job.code_review_revision->>'approval_id' IS NOT NULL
      THEN '::correction::' || (_job.code_review_revision->>'approval_id') ELSE '' END
    || CASE WHEN _step.input_context->>'owner_patch_retry_receipt' IS NOT NULL
      THEN '::owner_patch_retry::' || (_step.input_context->>'owner_patch_retry_receipt')
        || '::attempt::' || (_step.attempt_count + 1)::text ELSE '' END;
  IF EXISTS (SELECT 1 FROM public.builder_worker_runs WHERE idempotency_key = _idempotency_key AND status = 'completed') THEN
    RAISE EXCEPTION 'This exact frontend patch was already verified';
  END IF;
  _lease_token_hash := encode(extensions.digest(_lease_token, 'sha256'), 'hex');

  INSERT INTO public.builder_worker_runs (
    organization_id, job_id, step_id, runner_id, worker_isolation_level,
    command, command_args, environment_variables_snapshot, profile, target_sha,
    patch_artifact_id, idempotency_key, lease_token_hash, lease_expires_at,
    heartbeat_at, status, started_at, timeout_seconds
  ) VALUES (
    _job.organization_id, _job.id, _step.id, _runner_id, 'container',
    'frontend-verify', ARRAY['frontend-verify'], '{}'::jsonb, 'frontend-verify', _job.target_sha,
    _patch.id, _idempotency_key, _lease_token_hash, now() + make_interval(secs => _timeout_seconds),
    now(), 'running', now(), _timeout_seconds
  )
  ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO UPDATE
  SET runner_id = EXCLUDED.runner_id, lease_token_hash = EXCLUDED.lease_token_hash,
      lease_expires_at = EXCLUDED.lease_expires_at, heartbeat_at = EXCLUDED.heartbeat_at,
      status = 'running', started_at = now(), completed_at = NULL, updated_at = now()
  RETURNING * INTO _run;

  UPDATE public.builder_job_steps
  SET status = 'running', attempt_count = attempt_count + 1, started_at = now(), completed_at = NULL,
      retryable = false, error = NULL,
      input_context = jsonb_build_object('patch_artifact_id', _patch.id, 'target_sha', _job.target_sha)
      || CASE WHEN _step.input_context->>'owner_patch_retry_receipt' IS NOT NULL THEN jsonb_build_object(
        'owner_patch_retry_receipt', _step.input_context->'owner_patch_retry_receipt',
        'owner_patch_retry_actor', _step.input_context->'owner_patch_retry_actor',
        'owner_patch_retry_at', _step.input_context->'owner_patch_retry_at',
        'owner_patch_retry_attempt_count', _step.input_context->'owner_patch_retry_attempt_count')
        ELSE '{}'::jsonb END, updated_at = now()
  WHERE id = _step.id;
  UPDATE public.builder_jobs SET status = 'building', current_step_name = _step.step_id,
    current_step_index = _step.ordinal_position, updated_at = now() WHERE id = _job.id;
  INSERT INTO public.builder_audit_events (organization_id, job_id, event_type, actor_type, previous_value, new_value, change_summary, related_artifact_ids)
  VALUES (_job.organization_id, _job.id, 'step_started', 'builder_mode',
    jsonb_build_object('job_status', 'implementation_pending', 'step_status', _step.status),
    jsonb_build_object('job_status', 'building', 'step_status', 'running', 'worker_run_id', _run.id, 'target_sha', _job.target_sha),
    'Frontend Engineer worker lease claimed', ARRAY[_patch.id]);

  RETURN jsonb_build_object(
    'run_id', _run.id, 'lease_token', _lease_token, 'lease_expires_at', _run.lease_expires_at,
    'job_id', _job.id, 'step_id', _step.id, 'organization_id', _job.organization_id,
    'profile', 'frontend-verify', 'target_sha', _job.target_sha, 'patch_artifact_id', _patch.id
  );
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_claim_frontend_worker"(_job_id uuid, _step_id uuid, _patch_artifact_id uuid, _runner_id text, _expected_target_sha text, _timeout_seconds integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_claim_frontend_worker"(_job_id uuid, _step_id uuid, _patch_artifact_id uuid, _runner_id text, _expected_target_sha text, _timeout_seconds integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_claim_frontend_worker"(_job_id uuid, _step_id uuid, _patch_artifact_id uuid, _runner_id text, _expected_target_sha text, _timeout_seconds integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_claim_routine_repairs"(_limit integer DEFAULT 3)
 RETURNS SETOF bob_friction_packets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;

  RETURN QUERY
  WITH candidates AS (
    SELECT packet.id
    FROM public.bob_friction_packets packet
    WHERE packet.repair_risk = 'routine'
      AND (
        packet.automation_status = 'queued'
        OR (
          packet.automation_status = 'claimed'
          AND packet.automation_updated_at < now() - interval '10 minutes'
        )
      )
      AND packet.route = 'dispatch_flow'
      AND packet.stop_line_hit IS NULL
      AND packet.automation_attempt_count < 5
    ORDER BY packet.automation_updated_at, packet.created_at
    FOR UPDATE SKIP LOCKED
    LIMIT LEAST(GREATEST(COALESCE(_limit, 3), 1), 10)
  )
  UPDATE public.bob_friction_packets packet
  SET automation_status = 'claimed',
      automation_attempt_count = packet.automation_attempt_count + 1,
      automation_error_redacted = NULL,
      automation_updated_at = now()
  FROM candidates
  WHERE packet.id = candidates.id
  RETURNING packet.*;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_claim_routine_repairs"(_limit integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_claim_routine_repairs"(_limit integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_claim_routine_repairs"(_limit integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_complete_independent_code_review"(_job_id uuid, _step_id uuid, _reviewer_model_run_id uuid, _review_artifact_id uuid, _verdict text)
 RETURNS builder_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _job public.builder_jobs%rowtype; _step public.builder_job_steps%rowtype;
  reviewer_run public.builder_model_runs%rowtype; _expected_inputs uuid[]; _reviewed_patch_ids uuid[];
  _author_identities jsonb; _passed boolean;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  IF _verdict NOT IN ('passed', 'blocked') THEN RAISE EXCEPTION 'Independent review verdict is invalid'; END IF;
  SELECT * INTO _job FROM public.builder_jobs WHERE id = _job_id FOR UPDATE;
  SELECT * INTO _step FROM public.builder_job_steps WHERE id = _step_id AND job_id = _job_id FOR UPDATE;
  SELECT * INTO reviewer_run FROM public.builder_model_runs WHERE id = _reviewer_model_run_id AND job_id = _job_id AND step_id = _step_id;
  IF _job.id IS NULL OR _job.status <> 'security_review' OR _job.code_review_mode <> 'independent_ai' THEN RAISE EXCEPTION 'Independent code review is not configured'; END IF;
  IF _step.id IS NULL OR _step.status <> 'running' OR _step.builder_mode <> 'code_reviewer' THEN RAISE EXCEPTION 'Independent code review step is not running'; END IF;

  SELECT COALESCE(array_agg(value::uuid), '{}') INTO _expected_inputs
  FROM jsonb_array_elements_text(COALESCE(_step.input_context->'reviewed_artifact_ids', '[]'::jsonb)) value;
  SELECT COALESCE(array_agg(artifact.id ORDER BY artifact.id), '{}') INTO _reviewed_patch_ids
  FROM public.builder_artifacts artifact
  WHERE artifact.job_id = _job.id AND artifact.id = ANY(_expected_inputs)
    AND artifact.artifact_type = 'code_implementation' AND artifact.status = 'final';

  IF reviewer_run.id IS NULL OR reviewer_run.status <> 'completed' OR NOT (_review_artifact_id = ANY(reviewer_run.output_artifact_ids)) THEN RAISE EXCEPTION 'Independent reviewer model evidence is incomplete'; END IF;
  IF cardinality(_expected_inputs) < 4 OR NOT (reviewer_run.input_artifact_ids @> _expected_inputs)
     OR cardinality(reviewer_run.input_artifact_ids) <> cardinality(_expected_inputs) THEN
    RAISE EXCEPTION 'Independent reviewer inputs do not match the approved evidence snapshot';
  END IF;
  IF cardinality(_reviewed_patch_ids) NOT BETWEEN 1 AND 2 THEN RAISE EXCEPTION 'Reviewed patch evidence is incomplete'; END IF;
  IF EXISTS (
    SELECT 1 FROM unnest(_reviewed_patch_ids) reviewed_patch_id
    WHERE NOT EXISTS (
      SELECT 1 FROM public.builder_model_runs author_run
      JOIN public.builder_job_steps author_step ON author_step.id = author_run.step_id
      WHERE author_run.job_id = _job.id AND author_step.builder_mode IN ('frontend_engineer', 'backend_engineer')
        AND author_run.status = 'completed' AND reviewed_patch_id = ANY(author_run.output_artifact_ids)
    )
  ) THEN RAISE EXCEPTION 'Reviewed patch author provenance is missing'; END IF;
  IF EXISTS (
    SELECT 1 FROM public.builder_model_runs author_run
    JOIN public.builder_job_steps author_step ON author_step.id = author_run.step_id
    WHERE author_run.job_id = _job.id AND author_step.builder_mode IN ('frontend_engineer', 'backend_engineer')
      AND author_run.status = 'completed' AND author_run.output_artifact_ids && _reviewed_patch_ids
      AND reviewer_run.provider = author_run.provider AND reviewer_run.model_name = author_run.model_name
  ) THEN RAISE EXCEPTION 'Independent reviewer must use a different provider or model identity from every patch author'; END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('provider', author_run.provider, 'model', author_run.model_name,
    'builder_mode', author_step.builder_mode)), '[]'::jsonb) INTO _author_identities
  FROM public.builder_model_runs author_run
  JOIN public.builder_job_steps author_step ON author_step.id = author_run.step_id
  WHERE author_run.job_id = _job.id AND author_step.builder_mode IN ('frontend_engineer', 'backend_engineer')
    AND author_run.status = 'completed' AND author_run.output_artifact_ids && _reviewed_patch_ids;
  IF NOT EXISTS (SELECT 1 FROM public.builder_artifacts WHERE id = _review_artifact_id AND job_id = _job.id
    AND step_id = _step.id AND artifact_type = 'code_review' AND status = 'final') THEN RAISE EXCEPTION 'Independent code review artifact is invalid'; END IF;

  _passed := _verdict = 'passed';
  UPDATE public.builder_job_steps SET status = CASE WHEN _passed THEN 'completed' ELSE 'failed' END,
    completed_at = now(), retryable = false, artifact_ids = ARRAY[_review_artifact_id],
    result_summary = CASE WHEN _passed THEN 'Independent AI code review passed' ELSE 'Independent AI code review blocked release' END,
    error = CASE WHEN _passed THEN NULL ELSE 'Independent AI code review found blocking defects' END, updated_at = now()
  WHERE id = _step.id;
  UPDATE public.builder_jobs SET code_review_status = CASE WHEN _passed THEN 'passed' ELSE 'blocked' END,
    code_review_artifact_id = _review_artifact_id, status = CASE WHEN _passed THEN 'security_review' ELSE 'failed' END,
    last_error = CASE WHEN _passed THEN NULL ELSE 'Independent AI code review found blocking defects' END, updated_at = now()
  WHERE id = _job.id RETURNING * INTO _job;
  INSERT INTO public.builder_audit_events (organization_id, job_id, event_type, actor_type, new_value, change_summary, related_artifact_ids)
  VALUES (_job.organization_id, _job.id, CASE WHEN _passed THEN 'step_completed' ELSE 'step_failed' END, 'builder_mode',
    jsonb_build_object('code_review_status', _job.code_review_status, 'reviewer_provider', reviewer_run.provider,
      'reviewer_model', reviewer_run.model_name, 'author_identities', _author_identities,
      'reviewed_patch_ids', _reviewed_patch_ids),
    CASE WHEN _passed THEN 'Independent AI code review passed' ELSE 'Independent AI code review blocked release' END,
    ARRAY[_review_artifact_id]);
  RETURN _job;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_complete_independent_code_review"(_job_id uuid, _step_id uuid, _reviewer_model_run_id uuid, _review_artifact_id uuid, _verdict text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_complete_independent_code_review"(_job_id uuid, _step_id uuid, _reviewer_model_run_id uuid, _review_artifact_id uuid, _verdict text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_complete_independent_code_review"(_job_id uuid, _step_id uuid, _reviewer_model_run_id uuid, _review_artifact_id uuid, _verdict text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_complete_product_analysis"(_job_id uuid, _step_id uuid, _artifact_id uuid, _result_summary text, _requested_from_users uuid[] DEFAULT '{}'::uuid[])
 RETURNS builder_approvals
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _job public.builder_jobs%rowtype;
  _step public.builder_job_steps%rowtype;
  _artifact public.builder_artifacts%rowtype;
  _approval public.builder_approvals%rowtype;
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;

  SELECT * INTO _job FROM public.builder_jobs WHERE id = _job_id FOR UPDATE;
  SELECT * INTO _step FROM public.builder_job_steps WHERE id = _step_id AND job_id = _job_id FOR UPDATE;
  SELECT * INTO _artifact FROM public.builder_artifacts WHERE id = _artifact_id AND job_id = _job_id;

  IF _job.id IS NULL OR _job.status <> 'analysis_pending' THEN
    RAISE EXCEPTION 'Job is not awaiting product analysis completion';
  END IF;
  IF _step.id IS NULL OR _step.builder_mode <> 'product_analyst' OR _step.status <> 'running' THEN
    RAISE EXCEPTION 'Product Analyst step is not running';
  END IF;
  IF _artifact.id IS NULL OR _artifact.step_id IS DISTINCT FROM _step.id
     OR _artifact.artifact_type <> 'product_specification' OR _artifact.status <> 'final' THEN
    RAISE EXCEPTION 'A final Product Analyst artifact is required';
  END IF;

  UPDATE public.builder_job_steps
  SET status = 'completed',
      completed_at = now(),
      result_summary = left(COALESCE(_result_summary, ''), 1000),
      artifact_ids = CASE
        WHEN _artifact.id = ANY(COALESCE(artifact_ids, '{}')) THEN artifact_ids
        ELSE array_append(COALESCE(artifact_ids, '{}'), _artifact.id)
      END,
      updated_at = now()
  WHERE id = _step.id;

  UPDATE public.builder_jobs
  SET status = 'specification_ready',
      current_step_name = _step.step_id,
      current_step_index = _step.ordinal_position,
      updated_at = now()
  WHERE id = _job.id;

  INSERT INTO public.builder_audit_events (
    organization_id, job_id, event_type, actor_type,
    previous_value, new_value, change_summary, related_artifact_ids
  ) VALUES (
    _job.organization_id, _job.id, 'step_completed', 'builder_mode',
    jsonb_build_object('job_status', _job.status, 'step_status', _step.status),
    jsonb_build_object('job_status', 'specification_ready', 'step_status', 'completed', 'step_id', _step.step_id),
    'Product Analyst completed a validated specification',
    ARRAY[_artifact.id]
  );

  SELECT * INTO _approval
  FROM public.builder_request_approval(
    _job.id,
    'specification_review',
    ARRAY[_artifact.id],
    COALESCE(_requested_from_users, '{}')
  );

  RETURN _approval;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_complete_product_analysis"(_job_id uuid, _step_id uuid, _artifact_id uuid, _result_summary text, _requested_from_users uuid[]) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_complete_product_analysis"(_job_id uuid, _step_id uuid, _artifact_id uuid, _result_summary text, _requested_from_users uuid[]) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_complete_product_analysis"(_job_id uuid, _step_id uuid, _artifact_id uuid, _result_summary text, _requested_from_users uuid[]) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_complete_release_preparation"(_job_id uuid, _step_id uuid, _release_notes_id uuid, _rollback_plan_id uuid, _deployment_manifest_id uuid, _reviewed_artifact_ids uuid[], _requested_from_users uuid[] DEFAULT '{}'::uuid[])
 RETURNS builder_approvals
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _job public.builder_jobs%rowtype; _step public.builder_job_steps%rowtype; _approval public.builder_approvals%rowtype; _all_artifacts uuid[];
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  SELECT * INTO _job FROM public.builder_jobs WHERE id = _job_id FOR UPDATE;
  SELECT * INTO _step FROM public.builder_job_steps WHERE id = _step_id AND job_id = _job_id FOR UPDATE;
  IF _job.id IS NULL OR _job.status <> 'security_review' OR _step.id IS NULL OR _step.status <> 'running' OR _step.builder_mode <> 'release_engineer' THEN
    RAISE EXCEPTION 'Release preparation is not running';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.builder_artifacts WHERE id = _release_notes_id AND job_id = _job.id AND step_id = _step.id AND artifact_type = 'release_notes' AND status = 'final')
     OR NOT EXISTS (SELECT 1 FROM public.builder_artifacts WHERE id = _rollback_plan_id AND job_id = _job.id AND step_id = _step.id AND artifact_type = 'rollback_plan' AND status = 'final')
     OR NOT EXISTS (SELECT 1 FROM public.builder_artifacts WHERE id = _deployment_manifest_id AND job_id = _job.id AND step_id = _step.id AND artifact_type = 'deployment_manifest' AND status = 'final') THEN
    RAISE EXCEPTION 'Release notes, rollback plan, and deployment manifest are required';
  END IF;
  IF COALESCE(cardinality(_reviewed_artifact_ids), 0) = 0 OR (
    SELECT count(*) FROM public.builder_artifacts WHERE job_id = _job.id AND id = ANY(_reviewed_artifact_ids) AND status = 'final'
  ) <> cardinality(_reviewed_artifact_ids) THEN RAISE EXCEPTION 'Release evidence snapshot is invalid'; END IF;

  _all_artifacts := ARRAY[_release_notes_id, _rollback_plan_id, _deployment_manifest_id] || _reviewed_artifact_ids;
  UPDATE public.builder_job_steps SET status = 'completed', completed_at = now(),
    result_summary = 'Release package prepared for human approval', artifact_ids = _all_artifacts, updated_at = now()
  WHERE id = _step.id;
  UPDATE public.builder_jobs SET status = 'approval_pending', current_step_name = _step.step_id,
    current_step_index = _step.ordinal_position, updated_at = now() WHERE id = _job.id;
  INSERT INTO public.builder_audit_events (organization_id, job_id, event_type, actor_type, previous_value, new_value, change_summary, related_artifact_ids)
  VALUES (_job.organization_id, _job.id, 'step_completed', 'builder_mode',
    jsonb_build_object('job_status', 'security_review', 'step_status', 'running'),
    jsonb_build_object('job_status', 'approval_pending', 'step_status', 'completed', 'target_sha', _job.target_sha),
    'Release package prepared; production deployment remains disabled', _all_artifacts);
  SELECT * INTO _approval FROM public.builder_request_approval(
    _job.id, 'release_approval', _all_artifacts, COALESCE(_requested_from_users, '{}')
  );
  RETURN _approval;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_complete_release_preparation"(_job_id uuid, _step_id uuid, _release_notes_id uuid, _rollback_plan_id uuid, _deployment_manifest_id uuid, _reviewed_artifact_ids uuid[], _requested_from_users uuid[]) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_complete_release_preparation"(_job_id uuid, _step_id uuid, _release_notes_id uuid, _rollback_plan_id uuid, _deployment_manifest_id uuid, _reviewed_artifact_ids uuid[], _requested_from_users uuid[]) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_complete_release_preparation"(_job_id uuid, _step_id uuid, _release_notes_id uuid, _rollback_plan_id uuid, _deployment_manifest_id uuid, _reviewed_artifact_ids uuid[], _requested_from_users uuid[]) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_complete_ux_design"(_job_id uuid, _step_id uuid, _artifact_id uuid, _result_summary text)
 RETURNS builder_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _job public.builder_jobs%rowtype;
  _step public.builder_job_steps%rowtype;
  _artifact public.builder_artifacts%rowtype;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  SELECT * INTO _job FROM public.builder_jobs WHERE id=_job_id FOR UPDATE;
  SELECT * INTO _step FROM public.builder_job_steps WHERE id=_step_id AND job_id=_job_id FOR UPDATE;
  SELECT * INTO _artifact FROM public.builder_artifacts WHERE id=_artifact_id AND job_id=_job_id;
  IF _job.id IS NULL OR _job.status <> 'design_pending' THEN RAISE EXCEPTION 'Job is not awaiting UX design completion'; END IF;
  IF _step.id IS NULL OR _step.builder_mode <> 'ux_designer' OR _step.status <> 'running' THEN RAISE EXCEPTION 'UX Designer step is not running'; END IF;
  IF _artifact.id IS NULL OR _artifact.step_id IS DISTINCT FROM _step.id OR _artifact.artifact_type <> 'ui_design_plan' OR _artifact.status <> 'final' THEN
    RAISE EXCEPTION 'A final UX design plan artifact is required';
  END IF;

  UPDATE public.builder_job_steps
  SET status='completed', completed_at=now(), result_summary=left(COALESCE(_result_summary,''),1000),
      artifact_ids=CASE WHEN _artifact.id=ANY(COALESCE(artifact_ids,'{}')) THEN artifact_ids ELSE array_append(COALESCE(artifact_ids,'{}'),_artifact.id) END,
      updated_at=now()
  WHERE id=_step.id;
  UPDATE public.builder_jobs
  SET status='implementation_pending', current_step_name=_step.step_id, current_step_index=_step.ordinal_position, updated_at=now()
  WHERE id=_job.id RETURNING * INTO _job;
  INSERT INTO public.builder_audit_events (organization_id,job_id,event_type,actor_type,previous_value,new_value,change_summary,related_artifact_ids)
  VALUES (_job.organization_id,_job.id,'step_completed','builder_mode',jsonb_build_object('job_status','design_pending','step_status','running'),jsonb_build_object('job_status','implementation_pending','step_status','completed','step_id',_step.step_id),'UX Designer completed a validated design plan',ARRAY[_artifact.id]);
  RETURN _job;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_complete_ux_design"(_job_id uuid, _step_id uuid, _artifact_id uuid, _result_summary text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_complete_ux_design"(_job_id uuid, _step_id uuid, _artifact_id uuid, _result_summary text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_complete_ux_design"(_job_id uuid, _step_id uuid, _artifact_id uuid, _result_summary text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_continue_backend_only_job"(_job_id uuid)
 RETURNS builder_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _job public.builder_jobs%rowtype; _ux_step public.builder_job_steps%rowtype;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  SELECT * INTO _job FROM public.builder_jobs WHERE id = _job_id FOR UPDATE;
  SELECT * INTO _ux_step FROM public.builder_job_steps WHERE job_id = _job_id AND step_id = 'ui_design' FOR UPDATE;
  IF _job.id IS NULL OR _job.status <> 'design_pending' OR _job.frontend_required OR NOT _job.backend_required THEN
    RAISE EXCEPTION 'Job is not an approved backend-only build';
  END IF;
  IF _ux_step.id IS NULL OR _ux_step.status <> 'skipped' THEN RAISE EXCEPTION 'UX step was not intentionally skipped'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.builder_approvals WHERE job_id = _job.id
    AND approval_type = 'specification_review' AND status = 'approved'
    AND requested_target_sha = _job.target_sha) THEN RAISE EXCEPTION 'Approved specification evidence is required'; END IF;
  UPDATE public.builder_jobs SET status = 'implementation_pending', current_step_name = _ux_step.step_id,
    current_step_index = _ux_step.ordinal_position, updated_at = now() WHERE id = _job.id RETURNING * INTO _job;
  INSERT INTO public.builder_audit_events (organization_id, job_id, event_type, actor_type, previous_value, new_value, change_summary)
  VALUES (_job.organization_id, _job.id, 'job_status_changed', 'builder_mode',
    jsonb_build_object('job_status', 'design_pending', 'step_status', 'skipped'),
    jsonb_build_object('job_status', 'implementation_pending', 'frontend_required', false, 'backend_required', true),
    'Backend-only job advanced past intentionally skipped UX design');
  RETURN _job;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_continue_backend_only_job"(_job_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_continue_backend_only_job"(_job_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_continue_backend_only_job"(_job_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_create_autopilot_child"(_parent_job_id uuid, _target_sha text, _title text, _task_description text, _description text DEFAULT NULL::text, _frontend_required boolean DEFAULT true, _backend_required boolean DEFAULT false, _code_review_mode text DEFAULT 'independent_ai'::text)
 RETURNS builder_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _parent public.builder_jobs;
  _child public.builder_jobs;
  _child_description text;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  SELECT * INTO _parent FROM public.builder_jobs WHERE id = _parent_job_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Parent Builder job is unavailable'; END IF;
  IF _parent.status IN ('cancelled', 'deployed') THEN RAISE EXCEPTION 'Parent Builder job cannot be continued'; END IF;
  IF _parent.autopilot_source = 'main_monitor' THEN RAISE EXCEPTION 'Main-health repairs require the main-health repair path'; END IF;
  IF _parent.autopilot_requested_by IS NULL
     OR NOT public.can_approve_action(_parent.autopilot_requested_by, _parent.organization_id) THEN
    RAISE EXCEPTION 'Parent autopilot requester cannot approve Builder work for this organisation';
  END IF;
  IF NULLIF(btrim(_title), '') IS NULL OR NULLIF(btrim(_task_description), '') IS NULL THEN
    RAISE EXCEPTION 'Title and task description are required';
  END IF;
  IF _target_sha IS NULL OR _target_sha !~ '^[a-f0-9]{40}$' THEN
    RAISE EXCEPTION 'A full lowercase Git target SHA is required';
  END IF;
  IF _parent.code_review_mode = 'human' AND _code_review_mode IS DISTINCT FROM 'human'
     OR _parent.code_review_mode = 'independent_ai' AND _code_review_mode = 'none' THEN
    RAISE EXCEPTION 'Parent code-review policy cannot be weakened';
  END IF;
  _child_description := COALESCE(NULLIF(btrim(_description), ''), 'Opened by Bob''s autopilot from job ' || _parent.id || '.');

  -- A retry after a lost response reuses the pinned child, even if main has moved again.
  SELECT * INTO _child FROM public.builder_jobs
  WHERE parent_job_id = _parent.id
    AND title = btrim(_title)
    AND task_description = btrim(_task_description)
    AND description = _child_description
    AND frontend_required = _frontend_required
    AND backend_required = _backend_required
    AND code_review_mode = _code_review_mode
  ORDER BY created_at LIMIT 1;
  IF FOUND THEN RETURN _child; END IF;

  SELECT * INTO _child FROM public.builder_create_job_v2(
    _parent.organization_id, _parent.project_id, _title, _task_description,
    _target_sha, 'main', _child_description, _frontend_required, _backend_required,
    _code_review_mode, _parent.task_run_id, _parent.requested_action, _parent.target_environment
  );
  PERFORM public.builder_autopilot_bind(
    _child.id, _parent.autopilot_requested_by, _parent.autopilot_conversation_id
  );
  UPDATE public.builder_jobs
  SET parent_job_id = _parent.id,
      autopilot_source = _parent.autopilot_source,
      source_friction_packet_id = _parent.source_friction_packet_id,
      repair_risk = _parent.repair_risk
  WHERE id = _child.id
  RETURNING * INTO _child;

  INSERT INTO public.builder_audit_events (
    organization_id, job_id, event_type, actor_type, new_value, change_summary
  ) VALUES (
    _child.organization_id, _child.id, 'builder_job_policy_bound', 'bot',
    jsonb_build_object('parent_job_id', _parent.id, 'target_sha', _child.target_sha,
      'autopilot_source', _child.autopilot_source),
    'Automatic Builder continuation linked and bound atomically; release controls remain unchanged'
  );
  RETURN _child;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_create_autopilot_child"(_parent_job_id uuid, _target_sha text, _title text, _task_description text, _description text, _frontend_required boolean, _backend_required boolean, _code_review_mode text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_create_autopilot_child"(_parent_job_id uuid, _target_sha text, _title text, _task_description text, _description text, _frontend_required boolean, _backend_required boolean, _code_review_mode text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_create_autopilot_child"(_parent_job_id uuid, _target_sha text, _title text, _task_description text, _description text, _frontend_required boolean, _backend_required boolean, _code_review_mode text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_create_followup_job"(_parent_job_id uuid, _title text, _task_description text, _frontend_required boolean DEFAULT true, _backend_required boolean DEFAULT false, _code_review_mode text DEFAULT 'none'::text)
 RETURNS builder_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _parent public.builder_jobs%rowtype; _job public.builder_jobs%rowtype;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  SELECT * INTO _parent FROM public.builder_jobs WHERE id = _parent_job_id FOR UPDATE;
  IF _parent.id IS NULL OR _parent.workspace_branch IS NULL OR _parent.workspace_head_sha IS NULL THEN RAISE EXCEPTION 'A verified Builder workspace is required for a follow-up iteration'; END IF;
  IF NULLIF(btrim(_title), '') IS NULL OR NULLIF(btrim(_task_description), '') IS NULL THEN RAISE EXCEPTION 'Title and task description are required'; END IF;
  IF NOT COALESCE(_frontend_required, false) AND NOT COALESCE(_backend_required, false) THEN RAISE EXCEPTION 'At least one implementation scope is required'; END IF;
  IF _code_review_mode NOT IN ('none', 'human', 'independent_ai') THEN RAISE EXCEPTION 'Unsupported code review mode'; END IF;
  INSERT INTO public.builder_jobs (organization_id, project_id, parent_job_id, title, task_description, status, current_step_index, total_steps, branch_name, target_sha, workspace_branch, workspace_head_sha, workspace_created_at, approval_required_at, frontend_required, backend_required, code_review_mode, code_review_status)
  VALUES (_parent.organization_id, _parent.project_id, _parent.id, btrim(_title), btrim(_task_description), 'intake', 0, 8, _parent.workspace_branch, _parent.workspace_head_sha, _parent.workspace_branch, _parent.workspace_head_sha, _parent.workspace_created_at, ARRAY['specification_ready','approval_pending'], _frontend_required, _backend_required, _code_review_mode, CASE WHEN _code_review_mode = 'none' THEN 'not_required' ELSE 'pending' END)
  RETURNING * INTO _job;
  INSERT INTO public.builder_job_steps (job_id, step_id, ordinal_position, builder_mode, status, blocked_dependencies, result_summary)
  VALUES
    (_job.id, 'product_analysis', 1, 'product_analyst', 'pending', '{}', NULL),
    (_job.id, 'ui_design', 2, 'ux_designer', CASE WHEN _frontend_required THEN 'pending' ELSE 'skipped' END, ARRAY['product_analysis'], CASE WHEN _frontend_required THEN NULL ELSE 'No frontend scope requested' END),
    (_job.id, 'frontend_implementation', 3, 'frontend_engineer', CASE WHEN _frontend_required THEN 'pending' ELSE 'skipped' END, ARRAY['ui_design'], CASE WHEN _frontend_required THEN NULL ELSE 'No frontend scope requested' END),
    (_job.id, 'backend_implementation', 4, 'backend_engineer', CASE WHEN _backend_required THEN 'pending' ELSE 'skipped' END, ARRAY['product_analysis'], CASE WHEN _backend_required THEN NULL ELSE 'No backend scope requested' END),
    (_job.id, 'test_suite', 5, 'qa_security_reviewer', 'pending', ARRAY['frontend_implementation','backend_implementation'], NULL),
    (_job.id, 'security_review', 6, 'qa_security_reviewer', 'pending', ARRAY['test_suite'], NULL),
    (_job.id, 'code_review', 7, 'code_reviewer', 'pending', ARRAY['security_review'], NULL),
    (_job.id, 'release_prep', 8, 'release_engineer', 'pending', ARRAY['code_review'], NULL);
  INSERT INTO public.builder_audit_events (organization_id, job_id, event_type, actor_type, new_value, change_summary)
  VALUES (_job.organization_id, _job.id, 'job_created', 'user', jsonb_build_object('parent_job_id', _parent.id, 'workspace_branch', _job.workspace_branch, 'target_sha', _job.target_sha), 'Builder follow-up iteration created from a verified workspace commit');
  RETURN _job;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_create_followup_job"(_parent_job_id uuid, _title text, _task_description text, _frontend_required boolean, _backend_required boolean, _code_review_mode text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_create_followup_job"(_parent_job_id uuid, _title text, _task_description text, _frontend_required boolean, _backend_required boolean, _code_review_mode text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_create_followup_job"(_parent_job_id uuid, _title text, _task_description text, _frontend_required boolean, _backend_required boolean, _code_review_mode text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_create_job"(_organization_id uuid, _project_id uuid, _title text, _task_description text, _target_sha text, _branch_name text DEFAULT 'main'::text, _description text DEFAULT NULL::text, _frontend_required boolean DEFAULT true, _backend_required boolean DEFAULT false, _code_review_mode text DEFAULT 'none'::text, _task_run_id uuid DEFAULT NULL::uuid)
 RETURNS builder_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _project public.builder_projects%rowtype; _job public.builder_jobs%rowtype;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  IF NULLIF(btrim(_title), '') IS NULL OR NULLIF(btrim(_task_description), '') IS NULL THEN RAISE EXCEPTION 'Title and task description are required'; END IF;
  IF _target_sha !~ '^[a-f0-9]{40}$' THEN RAISE EXCEPTION 'A full lowercase Git target SHA is required'; END IF;
  IF NOT COALESCE(_frontend_required, false) AND NOT COALESCE(_backend_required, false) THEN RAISE EXCEPTION 'At least one implementation scope is required'; END IF;
  IF _code_review_mode NOT IN ('none', 'human', 'independent_ai') THEN RAISE EXCEPTION 'Unsupported code review mode'; END IF;
  SELECT * INTO _project FROM public.builder_projects WHERE id = _project_id AND organization_id = _organization_id AND status = 'active' FOR UPDATE;
  IF _project.id IS NULL THEN RAISE EXCEPTION 'Active Builder project is unavailable'; END IF;

  INSERT INTO public.builder_jobs (
    organization_id, project_id, task_run_id, title, description, task_description,
    status, current_step_index, total_steps, branch_name, target_sha, approval_required_at,
    frontend_required, backend_required, code_review_mode, code_review_status
  ) VALUES (
    _organization_id, _project_id, _task_run_id, btrim(_title), NULLIF(btrim(_description), ''), btrim(_task_description),
    'intake', 0, 8, COALESCE(NULLIF(btrim(_branch_name), ''), 'main'), _target_sha,
    ARRAY['specification_ready','approval_pending'], _frontend_required, _backend_required,
    _code_review_mode, CASE WHEN _code_review_mode = 'none' THEN 'not_required' ELSE 'pending' END
  ) RETURNING * INTO _job;

  INSERT INTO public.builder_job_steps (job_id, step_id, ordinal_position, builder_mode, status, blocked_dependencies, result_summary)
  VALUES
    (_job.id, 'product_analysis', 1, 'product_analyst', 'pending', '{}', NULL),
    (_job.id, 'ui_design', 2, 'ux_designer', CASE WHEN _frontend_required THEN 'pending' ELSE 'skipped' END,
      ARRAY['product_analysis'], CASE WHEN _frontend_required THEN NULL ELSE 'No frontend scope requested' END),
    (_job.id, 'frontend_implementation', 3, 'frontend_engineer', CASE WHEN _frontend_required THEN 'pending' ELSE 'skipped' END,
      ARRAY['ui_design'], CASE WHEN _frontend_required THEN NULL ELSE 'No frontend scope requested' END),
    (_job.id, 'backend_implementation', 4, 'backend_engineer', CASE WHEN _backend_required THEN 'pending' ELSE 'skipped' END,
      ARRAY['product_analysis'], CASE WHEN _backend_required THEN NULL ELSE 'No backend scope requested' END),
    (_job.id, 'test_suite', 5, 'qa_security_reviewer', 'pending', ARRAY['frontend_implementation','backend_implementation'], NULL),
    (_job.id, 'security_review', 6, 'qa_security_reviewer', 'pending', ARRAY['test_suite'], NULL),
    (_job.id, 'code_review', 7, 'code_reviewer', 'pending', ARRAY['security_review'], NULL),
    (_job.id, 'release_prep', 8, 'release_engineer', 'pending', ARRAY['code_review'], NULL);

  INSERT INTO public.builder_audit_events (organization_id, job_id, event_type, actor_type, new_value, change_summary)
  VALUES (_job.organization_id, _job.id, 'job_created', 'bot',
    jsonb_build_object('target_sha', _job.target_sha, 'frontend_required', _frontend_required,
      'backend_required', _backend_required, 'code_review_mode', _code_review_mode),
    'Builder job created with immutable repository target and implementation scope');
  RETURN _job;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_create_job"(_organization_id uuid, _project_id uuid, _title text, _task_description text, _target_sha text, _branch_name text, _description text, _frontend_required boolean, _backend_required boolean, _code_review_mode text, _task_run_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_create_job"(_organization_id uuid, _project_id uuid, _title text, _task_description text, _target_sha text, _branch_name text, _description text, _frontend_required boolean, _backend_required boolean, _code_review_mode text, _task_run_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_create_job"(_organization_id uuid, _project_id uuid, _title text, _task_description text, _target_sha text, _branch_name text, _description text, _frontend_required boolean, _backend_required boolean, _code_review_mode text, _task_run_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_create_job_v2"(_organization_id uuid, _project_id uuid, _title text, _task_description text, _target_sha text, _branch_name text DEFAULT 'main'::text, _description text DEFAULT NULL::text, _frontend_required boolean DEFAULT true, _backend_required boolean DEFAULT false, _code_review_mode text DEFAULT 'none'::text, _task_run_id uuid DEFAULT NULL::uuid, _requested_action text DEFAULT 'prepare_change'::text, _target_environment text DEFAULT 'development'::text)
 RETURNS builder_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _job public.builder_jobs%rowtype;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  IF _requested_action NOT IN ('prepare_change', 'prepare_release') THEN RAISE EXCEPTION 'Unsupported Builder requested action'; END IF;
  IF _target_environment NOT IN ('development', 'staging', 'production') THEN RAISE EXCEPTION 'Unsupported Builder target environment'; END IF;
  IF _target_environment = 'production' AND _requested_action <> 'prepare_release' THEN RAISE EXCEPTION 'Production Builder jobs must prepare a release'; END IF;
  IF _target_environment = 'production' AND _code_review_mode <> 'human' THEN RAISE EXCEPTION 'Production Builder jobs require human code review'; END IF;

  SELECT * INTO _job FROM public.builder_create_job(
    _organization_id, _project_id, _title, _task_description, _target_sha,
    _branch_name, _description, _frontend_required, _backend_required,
    _code_review_mode, _task_run_id
  );

  UPDATE public.builder_jobs
  SET requested_action = _requested_action,
      target_environment = _target_environment
  WHERE id = _job.id
  RETURNING * INTO _job;

  INSERT INTO public.builder_audit_events (organization_id, job_id, event_type, actor_type, new_value, change_summary)
  VALUES (_job.organization_id, _job.id, 'builder_job_policy_bound', 'bot',
    jsonb_build_object('requested_action', _job.requested_action, 'target_environment', _job.target_environment, 'target_sha', _job.target_sha),
    'Builder job intent and target environment bound to the immutable repository target');

  RETURN _job;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_create_job_v2"(_organization_id uuid, _project_id uuid, _title text, _task_description text, _target_sha text, _branch_name text, _description text, _frontend_required boolean, _backend_required boolean, _code_review_mode text, _task_run_id uuid, _requested_action text, _target_environment text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_create_job_v2"(_organization_id uuid, _project_id uuid, _title text, _task_description text, _target_sha text, _branch_name text, _description text, _frontend_required boolean, _backend_required boolean, _code_review_mode text, _task_run_id uuid, _requested_action text, _target_environment text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_create_job_v2"(_organization_id uuid, _project_id uuid, _title text, _task_description text, _target_sha text, _branch_name text, _description text, _frontend_required boolean, _backend_required boolean, _code_review_mode text, _task_run_id uuid, _requested_action text, _target_environment text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_decide_approval"(_approval_id uuid, _decision text, _comment text DEFAULT NULL::text)
 RETURNS builder_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _approval public.builder_approvals%rowtype; _job public.builder_jobs%rowtype; _next_status text; _event_type text;
BEGIN
  IF auth.role() <> 'authenticated' OR _uid IS NULL THEN RAISE EXCEPTION 'Authenticated human identity required'; END IF;
  IF _decision NOT IN ('approved', 'rejected') THEN RAISE EXCEPTION 'Decision must be approved or rejected'; END IF;
  SELECT * INTO _approval FROM public.builder_approvals WHERE id = _approval_id FOR UPDATE;
  IF NOT FOUND OR _approval.status <> 'pending' THEN RAISE EXCEPTION 'Approval is missing or already decided'; END IF;
  IF _approval.expires_at <= now() THEN RAISE EXCEPTION 'Approval has expired and requires a new evidence review'; END IF;
  IF NOT public.can_approve_action(_uid, _approval.organization_id) THEN RAISE EXCEPTION 'User is not authorized to approve this job'; END IF;
  IF cardinality(_approval.requested_from_users) > 0 AND NOT (_uid = ANY(_approval.requested_from_users)) THEN RAISE EXCEPTION 'Approval was not requested from this user'; END IF;
  SELECT * INTO _job FROM public.builder_jobs WHERE id = _approval.job_id FOR UPDATE;
  IF NOT FOUND OR _job.status <> _approval.triggered_at_status THEN RAISE EXCEPTION 'Job has moved beyond this approval gate'; END IF;
  IF _approval.requested_target_sha IS DISTINCT FROM _job.target_sha THEN RAISE EXCEPTION 'Job target changed after approval was requested'; END IF;
  IF (SELECT count(*) FROM public.builder_artifacts WHERE job_id = _job.id AND id = ANY(_approval.reviewed_artifact_ids) AND status = 'final') <> cardinality(_approval.reviewed_artifact_ids) THEN RAISE EXCEPTION 'Reviewed evidence is no longer valid'; END IF;
  IF _decision = 'rejected' THEN _next_status := 'failed'; _event_type := 'approval_rejected';
  ELSIF _approval.approval_type = 'specification_review' AND _approval.triggered_at_status = 'specification_ready' THEN _next_status := 'design_pending'; _event_type := 'approval_approved';
  ELSIF _approval.approval_type = 'release_approval' AND _approval.triggered_at_status = 'approval_pending' THEN _next_status := 'release_ready'; _event_type := 'approval_approved';
  ELSE RAISE EXCEPTION 'Approval gate cannot transition this job'; END IF;
  UPDATE public.builder_approvals SET status = _decision, approved_by = CASE WHEN _decision = 'approved' THEN _uid ELSE NULL END, decided_by = _uid, approval_comment = NULLIF(btrim(_comment), ''), responded_at = now(), updated_at = now() WHERE id = _approval.id;
  UPDATE public.builder_jobs SET status = _next_status, last_error = CASE WHEN _decision = 'rejected' THEN COALESCE(NULLIF(btrim(_comment), ''), 'Builder approval rejected') ELSE NULL END, updated_at = now() WHERE id = _job.id RETURNING * INTO _job;
  INSERT INTO public.builder_audit_events (organization_id, job_id, event_type, actor_user_id, actor_type, previous_value, new_value, change_summary, related_artifact_ids, related_approval_id)
  VALUES (_approval.organization_id, _approval.job_id, _event_type, _uid, 'user', jsonb_build_object('status', _approval.triggered_at_status), jsonb_build_object('status', _next_status, 'decision', _decision), CASE WHEN _decision = 'approved' THEN 'Human approved Builder gate' ELSE 'Human rejected Builder gate' END, _approval.reviewed_artifact_ids, _approval.id);
  RETURN _job;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_decide_approval"(_approval_id uuid, _decision text, _comment text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_decide_approval"(_approval_id uuid, _decision text, _comment text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_decide_approval"(_approval_id uuid, _decision text, _comment text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."builder_decide_human_code_review"(_approval_id uuid, _decision text, _comment text DEFAULT NULL::text)
 RETURNS builder_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _approval public.builder_approvals%rowtype; _job public.builder_jobs%rowtype; _passed boolean;
BEGIN
  IF auth.role() <> 'authenticated' OR _uid IS NULL THEN RAISE EXCEPTION 'Authenticated human identity required'; END IF;
  IF _decision NOT IN ('approved', 'rejected') THEN RAISE EXCEPTION 'Decision must be approved or rejected'; END IF;
  SELECT * INTO _approval FROM public.builder_approvals WHERE id = _approval_id AND approval_type = 'implementation_review' FOR UPDATE;
  IF _approval.id IS NULL OR _approval.status <> 'pending' THEN RAISE EXCEPTION 'Human code review is missing or decided'; END IF;
  IF _approval.expires_at <= now() THEN RAISE EXCEPTION 'Approval has expired and requires a new evidence review'; END IF;
  IF NOT public.can_approve_action(_uid, _approval.organization_id) THEN RAISE EXCEPTION 'User cannot review this job'; END IF;
  IF cardinality(_approval.requested_from_users) > 0 AND NOT (_uid = ANY(_approval.requested_from_users)) THEN RAISE EXCEPTION 'Review was not requested from this user'; END IF;
  SELECT * INTO _job FROM public.builder_jobs WHERE id = _approval.job_id FOR UPDATE;
  IF _job.status <> 'security_review' OR _job.code_review_mode <> 'human' OR _approval.requested_target_sha IS DISTINCT FROM _job.target_sha THEN RAISE EXCEPTION 'Human code review is stale'; END IF;
  _passed := _decision = 'approved';
  UPDATE public.builder_approvals SET status = _decision, decided_by = _uid, approved_by = CASE WHEN _passed THEN _uid ELSE NULL END, approval_comment = NULLIF(btrim(_comment), ''), responded_at = now(), updated_at = now() WHERE id = _approval.id;
  UPDATE public.builder_job_steps SET status = CASE WHEN _passed THEN 'completed' ELSE 'failed' END, completed_at = now(), blocked_reason = NULL, result_summary = CASE WHEN _passed THEN 'Optional human code review passed' ELSE 'Human code review blocked release' END, error = CASE WHEN _passed THEN NULL ELSE 'Human code review rejected implementation' END, artifact_ids = _approval.reviewed_artifact_ids, updated_at = now() WHERE job_id = _job.id AND step_id = 'code_review';
  UPDATE public.builder_jobs SET code_review_status = CASE WHEN _passed THEN 'passed' ELSE 'blocked' END, status = CASE WHEN _passed THEN 'security_review' ELSE 'failed' END, last_error = CASE WHEN _passed THEN NULL ELSE COALESCE(NULLIF(btrim(_comment), ''), 'Human code review rejected implementation') END, updated_at = now() WHERE id = _job.id RETURNING * INTO _job;
  INSERT INTO public.builder_audit_events (organization_id, job_id, event_type, actor_user_id, actor_type, new_value, change_summary, related_artifact_ids, related_approval_id)
  VALUES (_job.organization_id, _job.id, CASE WHEN _passed THEN 'approval_approved' ELSE 'approval_rejected' END, _uid, 'user', jsonb_build_object('code_review_status', _job.code_review_status, 'target_sha', _job.target_sha), CASE WHEN _passed THEN 'Optional human code review passed' ELSE 'Human code review blocked release' END, _approval.reviewed_artifact_ids, _approval.id);
  RETURN _job;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_decide_human_code_review"(_approval_id uuid, _decision text, _comment text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_decide_human_code_review"(_approval_id uuid, _decision text, _comment text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_decide_human_code_review"(_approval_id uuid, _decision text, _comment text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."builder_enforce_implementation_acceptance"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_TABLE_NAME = 'builder_job_steps' THEN
    IF (NEW.step_id = 'code_review' AND NEW.status IN ('running', 'blocked', 'skipped', 'completed')
        OR NEW.step_id = 'release_prep' AND NEW.status IN ('running', 'completed'))
      AND NEW.status IS DISTINCT FROM OLD.status
    THEN PERFORM public.builder_require_implementation_acceptance(NEW.job_id,
      NOT (NEW.step_id = 'code_review' AND NEW.status = 'blocked' AND EXISTS (
        SELECT 1 FROM public.builder_jobs WHERE id = NEW.job_id AND code_review_mode = 'human'
      ))); END IF;
  ELSIF TG_TABLE_NAME = 'builder_approvals' THEN
    IF NEW.approval_type = 'implementation_review' AND NEW.status = 'approved' AND OLD.status <> 'approved'
      THEN PERFORM public.builder_require_implementation_acceptance(NEW.job_id); END IF;
  ELSIF NEW.status = 'release_ready' AND OLD.status <> 'release_ready' THEN
    PERFORM public.builder_require_implementation_acceptance(NEW.id);
  END IF;
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_enforce_implementation_acceptance"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_enforce_implementation_acceptance"() TO "postgres";

CREATE OR REPLACE FUNCTION "public"."builder_enforce_release_review_policy"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _job public.builder_jobs%rowtype;
BEGIN
  IF NEW.step_id <> 'release_prep' OR NEW.status <> 'running' THEN RETURN NEW; END IF;
  SELECT * INTO _job FROM public.builder_jobs WHERE id = NEW.job_id;
  IF _job.code_review_mode IN ('human', 'independent_ai') AND _job.code_review_status <> 'passed' THEN
    RAISE EXCEPTION 'Configured code review must pass before release preparation';
  END IF;
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_enforce_release_review_policy"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_enforce_release_review_policy"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."builder_enforce_release_review_policy"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_enforce_release_review_policy"() TO "anon";
GRANT EXECUTE ON FUNCTION "public"."builder_enforce_release_review_policy"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."builder_enforce_release_review_policy"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_finalize_model_artifact"(_model_run_id uuid, _artifact_type text, _content_type text, _object_path text, _sha256 text, _size_bytes integer, _model_name text, _usage_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS builder_artifacts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _run public.builder_model_runs%rowtype;
  _artifact public.builder_artifacts%rowtype;
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;

  IF _object_path IS NULL OR _object_path = '' OR _object_path LIKE '../%' OR _object_path LIKE '%/../%' THEN
    RAISE EXCEPTION 'Invalid artifact object path';
  END IF;
  IF _sha256 !~ '^[a-f0-9]{64}$' OR _size_bytes < 0 OR _size_bytes > 10485760 THEN
    RAISE EXCEPTION 'Invalid artifact integrity metadata';
  END IF;
  IF _content_type NOT IN ('application/json', 'text/markdown', 'text/plain') THEN
    RAISE EXCEPTION 'Unsupported artifact content type';
  END IF;

  SELECT * INTO _run
  FROM public.builder_model_runs
  WHERE id = _model_run_id
  FOR UPDATE;

  IF NOT FOUND OR _run.status <> 'running' THEN
    RAISE EXCEPTION 'Model run is missing or not running';
  END IF;

  INSERT INTO public.builder_artifacts (
    job_id,
    step_id,
    artifact_type,
    content_type,
    content_size_bytes,
    storage_location,
    checksum,
    produced_by_model,
    status
  )
  VALUES (
    _run.job_id,
    _run.step_id,
    _artifact_type,
    _content_type,
    _size_bytes,
    'supabase_storage://builder-artifacts/' || _object_path,
    _sha256,
    _run.provider,
    'final'
  )
  RETURNING * INTO _artifact;

  IF _run.step_id IS NOT NULL THEN
    UPDATE public.builder_job_steps
    SET artifact_ids = array_append(COALESCE(artifact_ids, '{}'), _artifact.id),
        updated_at = now()
    WHERE id = _run.step_id AND job_id = _run.job_id;
  END IF;

  INSERT INTO public.builder_audit_events (
    organization_id,
    job_id,
    event_type,
    actor_type,
    new_value,
    change_summary,
    related_artifact_ids
  )
  VALUES (
    _run.organization_id,
    _run.job_id,
    'artifact_created',
    'builder_mode',
    jsonb_build_object(
      'model_run_id', _run.id,
      'artifact_type', _artifact_type,
      'checksum', _sha256,
      'size_bytes', _size_bytes
    ),
    'Builder model output artifact verified and registered',
    ARRAY[_artifact.id]
  );

  UPDATE public.builder_model_runs
  SET status = 'completed',
      completed_at = now(),
      output_artifact_ids = array_append(COALESCE(output_artifact_ids, '{}'), _artifact.id),
      usage_metadata = COALESCE(_usage_metadata, '{}'::jsonb),
      model_name = COALESCE(NULLIF(_model_name, ''), model_name),
      error = NULL,
      updated_at = now()
  WHERE id = _run.id;

  INSERT INTO public.builder_audit_events (
    organization_id,
    job_id,
    event_type,
    actor_type,
    previous_value,
    new_value,
    change_summary,
    related_artifact_ids
  )
  VALUES (
    _run.organization_id,
    _run.job_id,
    'model_run_completed',
    'builder_mode',
    jsonb_build_object('status', _run.status),
    jsonb_build_object('status', 'completed', 'model_run_id', _run.id),
    'Builder model run completed with verified artifact',
    ARRAY[_artifact.id]
  );

  RETURN _artifact;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_finalize_model_artifact"(_model_run_id uuid, _artifact_type text, _content_type text, _object_path text, _sha256 text, _size_bytes integer, _model_name text, _usage_metadata jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_finalize_model_artifact"(_model_run_id uuid, _artifact_type text, _content_type text, _object_path text, _sha256 text, _size_bytes integer, _model_name text, _usage_metadata jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_finalize_model_artifact"(_model_run_id uuid, _artifact_type text, _content_type text, _object_path text, _sha256 text, _size_bytes integer, _model_name text, _usage_metadata jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_finish_backend_worker"(_run_id uuid, _lease_token text, _succeeded boolean, _exit_code integer, _log_summary text DEFAULT NULL::text)
 RETURNS builder_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _run public.builder_worker_runs%rowtype; _job public.builder_jobs%rowtype; _next_status text; _event_type text;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  SELECT * INTO _run FROM public.builder_worker_runs WHERE id = _run_id AND profile = 'backend-verify' AND status = 'running'
    AND lease_expires_at > now() AND lease_token_hash = encode(extensions.digest(_lease_token, 'sha256'), 'hex') FOR UPDATE;
  IF _run.id IS NULL THEN RAISE EXCEPTION 'Backend worker lease is missing, expired, or invalid'; END IF;
  SELECT * INTO _job FROM public.builder_jobs WHERE id = _run.job_id FOR UPDATE;
  IF _job.target_sha IS DISTINCT FROM _run.target_sha THEN RAISE EXCEPTION 'Job target changed during worker execution'; END IF;
  IF _succeeded AND NOT (
    EXISTS (SELECT 1 FROM public.builder_artifacts WHERE id = ANY(_run.output_artifact_ids) AND job_id = _run.job_id AND artifact_type = 'code_implementation' AND status = 'final')
    AND EXISTS (SELECT 1 FROM public.builder_artifacts WHERE id = ANY(_run.output_artifact_ids) AND job_id = _run.job_id AND artifact_type = 'changed_file_manifest' AND status = 'final')
    AND EXISTS (SELECT 1 FROM public.builder_artifacts WHERE id = ANY(_run.output_artifact_ids) AND job_id = _run.job_id AND artifact_type = 'build_logs' AND status = 'final')
  ) THEN RAISE EXCEPTION 'Successful backend completion requires patch, manifest, and verification logs'; END IF;

  _next_status := CASE
    WHEN NOT _succeeded THEN 'implementation_pending'
    WHEN EXISTS (SELECT 1 FROM public.builder_job_steps WHERE job_id = _run.job_id AND builder_mode = 'frontend_engineer' AND status IN ('completed', 'skipped')) THEN 'testing'
    ELSE 'implementation_pending'
  END;
  _event_type := CASE WHEN _succeeded THEN 'step_completed' ELSE 'step_failed' END;
  UPDATE public.builder_worker_runs SET status = CASE WHEN _succeeded THEN 'completed' ELSE 'failed' END,
    completed_at = now(), exit_code = _exit_code, log_summary = left(COALESCE(_log_summary, ''), 1000),
    lease_token_hash = NULL, lease_expires_at = NULL, updated_at = now() WHERE id = _run.id;
  UPDATE public.builder_job_steps SET status = CASE WHEN _succeeded THEN 'completed' ELSE 'failed' END,
    completed_at = now(), retryable = NOT _succeeded,
    error = CASE WHEN _succeeded THEN NULL ELSE 'Backend worker verification failed' END,
    artifact_ids = CASE WHEN _succeeded THEN COALESCE(_run.output_artifact_ids, '{}') ELSE artifact_ids END,
    result_summary = CASE WHEN _succeeded THEN 'Backend verification passed; disposable migration evidence registered when required' ELSE result_summary END,
    updated_at = now() WHERE id = _run.step_id;
  UPDATE public.builder_jobs SET status = _next_status,
    last_error = CASE WHEN _succeeded THEN NULL ELSE 'Backend worker verification failed' END,
    updated_at = now() WHERE id = _run.job_id RETURNING * INTO _job;
  INSERT INTO public.builder_audit_events (organization_id, job_id, event_type, actor_type, previous_value, new_value, change_summary, related_artifact_ids)
  VALUES (_run.organization_id, _run.job_id, _event_type, 'builder_mode',
    jsonb_build_object('job_status', 'building', 'step_status', 'running'),
    jsonb_build_object('job_status', _next_status, 'step_status', CASE WHEN _succeeded THEN 'completed' ELSE 'failed' END,
      'worker_run_id', _run.id, 'exit_code', _exit_code, 'verification_scope', 'backend_patch',
      'disposable_migration_evidence', CASE WHEN _succeeded THEN 'registered_or_not_required' ELSE 'failed' END,
      'production_execution', false),
    CASE WHEN _succeeded THEN 'Backend verification completed with disposable database evidence when required; production execution was not performed'
      ELSE 'Backend verification failed and is retryable' END,
    COALESCE(_run.output_artifact_ids, '{}'));
  RETURN _job;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_finish_backend_worker"(_run_id uuid, _lease_token text, _succeeded boolean, _exit_code integer, _log_summary text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_finish_backend_worker"(_run_id uuid, _lease_token text, _succeeded boolean, _exit_code integer, _log_summary text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_finish_backend_worker"(_run_id uuid, _lease_token text, _succeeded boolean, _exit_code integer, _log_summary text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_finish_frontend_worker"(_run_id uuid, _lease_token text, _succeeded boolean, _exit_code integer, _log_summary text DEFAULT NULL::text)
 RETURNS builder_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _run public.builder_worker_runs%rowtype; _job public.builder_jobs%rowtype; _next_status text; _event_type text;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  SELECT * INTO _run FROM public.builder_worker_runs WHERE id = _run_id AND profile = 'frontend-verify' AND status = 'running'
    AND lease_expires_at > now() AND lease_token_hash = encode(extensions.digest(_lease_token, 'sha256'), 'hex') FOR UPDATE;
  IF _run.id IS NULL THEN RAISE EXCEPTION 'Frontend worker lease is missing, expired, or invalid'; END IF;
  SELECT * INTO _job FROM public.builder_jobs WHERE id = _run.job_id FOR UPDATE;
  IF _job.target_sha IS DISTINCT FROM _run.target_sha THEN RAISE EXCEPTION 'Job target changed during worker execution'; END IF;
  IF _succeeded AND NOT (
    EXISTS (SELECT 1 FROM public.builder_artifacts WHERE id = ANY(_run.output_artifact_ids) AND job_id = _run.job_id AND artifact_type = 'code_implementation' AND status = 'final')
    AND EXISTS (SELECT 1 FROM public.builder_artifacts WHERE id = ANY(_run.output_artifact_ids) AND job_id = _run.job_id AND artifact_type = 'changed_file_manifest' AND status = 'final')
    AND EXISTS (SELECT 1 FROM public.builder_artifacts WHERE id = ANY(_run.output_artifact_ids) AND job_id = _run.job_id AND artifact_type = 'build_logs' AND status = 'final')
  ) THEN RAISE EXCEPTION 'Successful frontend completion requires patch, manifest, and build logs'; END IF;
  _next_status := CASE
    WHEN NOT _succeeded THEN 'implementation_pending'
    WHEN EXISTS (SELECT 1 FROM public.builder_job_steps WHERE job_id = _run.job_id AND builder_mode = 'backend_engineer' AND status IN ('completed', 'skipped')) THEN 'testing'
    ELSE 'implementation_pending'
  END;
  _event_type := CASE WHEN _succeeded THEN 'step_completed' ELSE 'step_failed' END;
  UPDATE public.builder_worker_runs SET status = CASE WHEN _succeeded THEN 'completed' ELSE 'failed' END,
    completed_at = now(), exit_code = _exit_code, log_summary = left(COALESCE(_log_summary, ''), 1000),
    lease_token_hash = NULL, lease_expires_at = NULL, updated_at = now() WHERE id = _run.id;
  UPDATE public.builder_job_steps SET status = CASE WHEN _succeeded THEN 'completed' ELSE 'failed' END,
    completed_at = now(), retryable = NOT _succeeded,
    error = CASE WHEN _succeeded THEN NULL ELSE 'Frontend worker verification failed' END,
    artifact_ids = CASE WHEN _succeeded THEN COALESCE(_run.output_artifact_ids, '{}') ELSE artifact_ids END,
    updated_at = now() WHERE id = _run.step_id;
  UPDATE public.builder_jobs SET status = _next_status,
    last_error = CASE WHEN _succeeded THEN NULL ELSE 'Frontend worker verification failed' END,
    updated_at = now() WHERE id = _run.job_id RETURNING * INTO _job;
  INSERT INTO public.builder_audit_events (organization_id, job_id, event_type, actor_type, previous_value, new_value, change_summary, related_artifact_ids)
  VALUES (_run.organization_id, _run.job_id, _event_type, 'builder_mode',
    jsonb_build_object('job_status', 'building', 'step_status', 'running'),
    jsonb_build_object('job_status', _next_status, 'step_status', CASE WHEN _succeeded THEN 'completed' ELSE 'failed' END, 'worker_run_id', _run.id, 'exit_code', _exit_code),
    CASE WHEN _succeeded THEN 'Frontend worker verification completed' ELSE 'Frontend worker verification failed and is retryable' END,
    COALESCE(_run.output_artifact_ids, '{}'));
  RETURN _job;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_finish_frontend_worker"(_run_id uuid, _lease_token text, _succeeded boolean, _exit_code integer, _log_summary text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_finish_frontend_worker"(_run_id uuid, _lease_token text, _succeeded boolean, _exit_code integer, _log_summary text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_finish_frontend_worker"(_run_id uuid, _lease_token text, _succeeded boolean, _exit_code integer, _log_summary text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_finish_security_review"(_run_id uuid, _lease_token text, _security_artifact_id uuid, _critical_count integer, _high_count integer, _medium_count integer, _low_count integer)
 RETURNS builder_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _run public.builder_worker_runs%rowtype; _job public.builder_jobs%rowtype; _next_job_status text; _passed boolean;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  IF LEAST(_critical_count, _high_count, _medium_count, _low_count) < 0 THEN RAISE EXCEPTION 'Finding counts cannot be negative'; END IF;
  SELECT * INTO _run FROM public.builder_worker_runs WHERE id = _run_id AND profile = 'security-review' AND status = 'running'
    AND lease_expires_at > now() AND lease_token_hash = encode(extensions.digest(_lease_token, 'sha256'), 'hex') FOR UPDATE;
  IF _run.id IS NULL THEN RAISE EXCEPTION 'Security review lease is missing, expired, or invalid'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.builder_artifacts WHERE id = _security_artifact_id AND job_id = _run.job_id
    AND step_id = _run.step_id AND artifact_type = 'security_review' AND status = 'final'
    AND id = ANY(_run.output_artifact_ids)) THEN RAISE EXCEPTION 'Verified security review artifact is required'; END IF;
  SELECT * INTO _job FROM public.builder_jobs WHERE id = _run.job_id FOR UPDATE;
  IF _job.status <> 'security_review' OR _job.target_sha IS DISTINCT FROM _run.target_sha THEN RAISE EXCEPTION 'Security review job state is stale'; END IF;

  _passed := NOT (_critical_count > 0 OR _high_count > 0);
  _next_job_status := CASE WHEN _passed THEN 'security_review' ELSE 'failed' END;
  UPDATE public.builder_worker_runs SET status = 'completed', completed_at = now(), exit_code = CASE WHEN _passed THEN 0 ELSE 1 END,
    review_summary = jsonb_build_object('passed', _passed, 'critical', _critical_count, 'high', _high_count, 'medium', _medium_count, 'low', _low_count),
    lease_token_hash = NULL, lease_expires_at = NULL, updated_at = now() WHERE id = _run.id;
  UPDATE public.builder_job_steps SET status = CASE WHEN _passed THEN 'completed' ELSE 'failed' END, completed_at = now(),
    retryable = false, artifact_ids = ARRAY[_security_artifact_id],
    result_summary = CASE WHEN _passed THEN 'Independent security review passed' ELSE 'Security review blocked release' END,
    error = CASE WHEN _passed THEN NULL ELSE 'Critical or high security findings block release' END, updated_at = now()
  WHERE id = _run.step_id;
  UPDATE public.builder_jobs SET status = _next_job_status,
    last_error = CASE WHEN _passed THEN NULL ELSE 'Critical or high security findings block release' END, updated_at = now()
  WHERE id = _run.job_id RETURNING * INTO _job;
  INSERT INTO public.builder_audit_events (organization_id, job_id, event_type, actor_type, previous_value, new_value, change_summary, related_artifact_ids)
  VALUES (_run.organization_id, _run.job_id, CASE WHEN _passed THEN 'step_completed' ELSE 'step_failed' END, 'builder_mode',
    jsonb_build_object('job_status', 'security_review', 'step_status', 'running'),
    jsonb_build_object('job_status', _next_job_status, 'step_status', CASE WHEN _passed THEN 'completed' ELSE 'failed' END,
      'critical', _critical_count, 'high', _high_count, 'medium', _medium_count, 'low', _low_count),
    CASE WHEN _passed THEN 'Independent security review passed' ELSE 'Independent security review blocked release' END,
    ARRAY[_security_artifact_id]);
  RETURN _job;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_finish_security_review"(_run_id uuid, _lease_token text, _security_artifact_id uuid, _critical_count integer, _high_count integer, _medium_count integer, _low_count integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_finish_security_review"(_run_id uuid, _lease_token text, _security_artifact_id uuid, _critical_count integer, _high_count integer, _medium_count integer, _low_count integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_finish_security_review"(_run_id uuid, _lease_token text, _security_artifact_id uuid, _critical_count integer, _high_count integer, _medium_count integer, _low_count integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_heartbeat_backend_worker"(_run_id uuid, _lease_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _run public.builder_worker_runs%rowtype;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  UPDATE public.builder_worker_runs
  SET heartbeat_at = now(), lease_expires_at = now() + make_interval(secs => timeout_seconds), updated_at = now()
  WHERE id = _run_id AND profile = 'backend-verify' AND status = 'running' AND lease_expires_at > now()
    AND lease_token_hash = encode(extensions.digest(_lease_token, 'sha256'), 'hex')
  RETURNING * INTO _run;
  IF _run.id IS NULL THEN RAISE EXCEPTION 'Backend worker lease is missing, expired, or invalid'; END IF;
  RETURN jsonb_build_object('run_id', _run.id, 'lease_expires_at', _run.lease_expires_at);
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_heartbeat_backend_worker"(_run_id uuid, _lease_token text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_heartbeat_backend_worker"(_run_id uuid, _lease_token text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_heartbeat_backend_worker"(_run_id uuid, _lease_token text) TO "service_role";

