CREATE OR REPLACE FUNCTION "public"."builder_implementation_acceptance_identity"(_job_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_build_object(
    'target_sha', j.target_sha,
    'correction', j.code_review_revision,
    'steps', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('id', s.id, 'step_id', s.step_id, 'status', s.status) ORDER BY s.id)
      FROM public.builder_job_steps s WHERE s.job_id = j.id
        AND s.step_id IN ('frontend_implementation', 'backend_implementation')
    ), '[]'::jsonb),
    'artifacts', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('id', a.id, 'step_id', a.step_id,
        'artifact_type', a.artifact_type, 'checksum', a.checksum) ORDER BY a.id)
      FROM public.builder_artifacts a WHERE a.job_id = j.id AND a.status = 'final'
        AND a.artifact_type IN ('product_specification', 'code_implementation', 'changed_file_manifest', 'build_logs')
        AND (a.artifact_type = 'product_specification' OR EXISTS (
          SELECT 1 FROM public.builder_job_steps s WHERE s.id = a.step_id AND s.job_id = j.id
            AND s.step_id IN ('frontend_implementation', 'backend_implementation')))
    ), '[]'::jsonb),
    'runs', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('id', r.id, 'step_id', r.step_id,
        'patch_artifact_id', r.patch_artifact_id, 'output_artifact_ids',
          COALESCE((SELECT jsonb_agg(v ORDER BY v) FROM unnest(r.output_artifact_ids) v), '[]'::jsonb)) ORDER BY r.id)
      FROM public.builder_worker_runs r JOIN public.builder_job_steps s ON s.id = r.step_id AND s.job_id = j.id
      WHERE r.job_id = j.id AND r.status = 'completed' AND r.profile IN ('frontend-verify', 'backend-verify')
        AND s.step_id IN ('frontend_implementation', 'backend_implementation')
        AND EXISTS (SELECT 1 FROM public.builder_artifacts a WHERE a.id = r.patch_artifact_id
          AND a.job_id = j.id AND a.status = 'final')
    ), '[]'::jsonb)
  ) FROM public.builder_jobs j WHERE j.id = _job_id;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_implementation_acceptance_identity"(_job_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_implementation_acceptance_identity"(_job_id uuid) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."builder_main_health_test_path_valid"(_file text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(
    position('..' in _file) = 0 AND _file ~
    '^(test/[A-Za-z0-9_.-]+[.]test[.][cm]?js|apps/web/(src/[A-Za-z0-9_./-]+[.](test|spec)[.]tsx?|e2e/[A-Za-z0-9_./-]+[.]spec[.]ts))$',
    false
  );
$function$;
REVOKE ALL ON FUNCTION "public"."builder_main_health_test_path_valid"(_file text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_main_health_test_path_valid"(_file text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_main_health_test_path_valid"(_file text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_open_main_health_repair"(_organization_id uuid, _project_id uuid, _health_sha text, _target_sha text, _title text, _task_description text, _failed_files text[], _parent_job_id uuid DEFAULT NULL::uuid)
 RETURNS builder_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _job public.builder_jobs%rowtype;
  _file text;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;
  IF _health_sha IS NULL OR _target_sha IS NULL
     OR _health_sha !~ '^[a-f0-9]{40}$' OR _target_sha !~ '^[a-f0-9]{40}$' THEN
    RAISE EXCEPTION 'Main-health commits must be full Git SHAs';
  END IF;
  IF _title IS NULL OR length(btrim(_title)) = 0 OR length(_title) > 200
     OR _task_description IS NULL OR length(_task_description) = 0 OR length(_task_description) > 12000 THEN
    RAISE EXCEPTION 'Main-health repair brief is invalid';
  END IF;
  IF COALESCE(cardinality(_failed_files), 0) < 1 OR cardinality(_failed_files) > 8 THEN
    RAISE EXCEPTION 'Main-health repair requires one to eight failing test files';
  END IF;
  FOREACH _file IN ARRAY _failed_files LOOP
    IF NOT public.builder_main_health_test_path_valid(_file) THEN
      RAISE EXCEPTION 'Main-health failure must name root, web unit or browser test files';
    END IF;
  END LOOP;
  IF NOT EXISTS (
    SELECT 1 FROM public.builder_projects
    WHERE id = _project_id AND organization_id = _organization_id AND status = 'active'
  ) THEN
    RAISE EXCEPTION 'Active Builder project is unavailable';
  END IF;
  IF _parent_job_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.builder_jobs
    WHERE id = _parent_job_id AND project_id = _project_id AND organization_id = _organization_id
  ) THEN
    RAISE EXCEPTION 'Main-health repair parent must belong to the same project and organization';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('main-health:' || _project_id::text || ':' || COALESCE(_parent_job_id::text, 'root'), 0));
  SELECT * INTO _job FROM public.builder_jobs
  WHERE organization_id = _organization_id AND project_id = _project_id
    AND autopilot_source = 'main_monitor'
    AND source_main_health_sha = _health_sha
    AND parent_job_id IS NOT DISTINCT FROM _parent_job_id
    AND status NOT IN ('failed', 'cancelled')
  ORDER BY created_at DESC LIMIT 1 FOR UPDATE;
  IF FOUND THEN RETURN _job; END IF;
  IF _parent_job_id IS NULL THEN
    SELECT * INTO _job FROM public.builder_jobs
    WHERE organization_id = _organization_id AND project_id = _project_id
      AND autopilot_source = 'main_monitor' AND parent_job_id IS NULL
      AND source_main_health_files @> _failed_files AND source_main_health_files <@ _failed_files
      AND status NOT IN ('failed', 'cancelled', 'deployed')
    ORDER BY created_at DESC LIMIT 1 FOR UPDATE;
    IF FOUND THEN RETURN _job; END IF;
  END IF;
  SELECT * INTO _job FROM public.builder_create_job_v2(
    _organization_id, _project_id, _title, _task_description, _target_sha, 'main',
    'Opened automatically by Bob after isolated main-health verification failed.',
    true, true, 'independent_ai', NULL, 'prepare_change', 'development'
  );
  UPDATE public.builder_jobs
  SET parent_job_id = _parent_job_id, autopilot_source = 'main_monitor', repair_risk = 'routine',
      source_main_health_sha = _health_sha, source_main_health_files = _failed_files,
      autopilot_state = 'driving', autopilot_updated_at = now(), updated_at = now()
  WHERE id = _job.id RETURNING * INTO _job;
  INSERT INTO public.builder_audit_events (
    organization_id, job_id, event_type, actor_type, new_value, change_summary
  ) VALUES (
    _job.organization_id, _job.id, 'builder_job_policy_bound', 'bot',
    jsonb_build_object('autopilot_source', 'main_monitor', 'health_sha', _health_sha,
      'target_sha', _target_sha, 'repair_risk', 'routine', 'failed_files', _failed_files,
      'frontend_required', true, 'backend_required', true),
    'Bob opened a root/web root-cause repair; protected release gates remain unchanged'
  );
  RETURN _job;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_open_main_health_repair"(_organization_id uuid, _project_id uuid, _health_sha text, _target_sha text, _title text, _task_description text, _failed_files text[], _parent_job_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_open_main_health_repair"(_organization_id uuid, _project_id uuid, _health_sha text, _target_sha text, _title text, _task_description text, _failed_files text[], _parent_job_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_open_main_health_repair"(_organization_id uuid, _project_id uuid, _health_sha text, _target_sha text, _title text, _task_description text, _failed_files text[], _parent_job_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_record_generation_failure"(_job_id uuid, _step_id uuid, _reason text, _retryable boolean DEFAULT true)
 RETURNS builder_job_steps
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _step public.builder_job_steps%rowtype; _job public.builder_jobs%rowtype;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  SELECT * INTO _job FROM public.builder_jobs WHERE id = _job_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Builder job is unavailable'; END IF;
  SELECT * INTO _step FROM public.builder_job_steps WHERE id = _step_id AND job_id = _job_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Builder step is unavailable'; END IF;
  IF _step.builder_mode NOT IN ('backend_engineer', 'frontend_engineer') THEN RAISE EXCEPTION 'Only implementation steps record generation failures'; END IF;
  IF _step.status NOT IN ('pending', 'failed') THEN RAISE EXCEPTION 'Step is not awaiting an author attempt'; END IF;
  UPDATE public.builder_job_steps
  SET status = 'failed',
      retryable = COALESCE(_retryable, true),
      attempt_count = COALESCE(attempt_count, 0) + 1,
      error = left(COALESCE(NULLIF(btrim(_reason), ''), 'author produced no proposal'), 2000),
      started_at = COALESCE(started_at, now()),
      completed_at = now(),
      updated_at = now()
  WHERE id = _step.id RETURNING * INTO _step;
  INSERT INTO public.builder_audit_events (organization_id, job_id, event_type, actor_type, previous_value, new_value, change_summary)
  VALUES (_job.organization_id, _job.id, 'step_failed', 'bot',
    jsonb_build_object('step', _step.step_id, 'attempt_count', _step.attempt_count - 1),
    jsonb_build_object('step', _step.step_id, 'attempt_count', _step.attempt_count, 'retryable', COALESCE(_retryable, true), 'reason', left(_reason, 500)),
    CASE WHEN COALESCE(_retryable, true) THEN 'Author run ended without a proposal; attempt counted towards the step ceiling'
         ELSE 'Author declined the change with a reason; step parked for a human, not retried' END);
  RETURN _step;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_record_generation_failure"(_job_id uuid, _step_id uuid, _reason text, _retryable boolean) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_record_generation_failure"(_job_id uuid, _step_id uuid, _reason text, _retryable boolean) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_record_generation_failure"(_job_id uuid, _step_id uuid, _reason text, _retryable boolean) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_record_implementation_acceptance"(_job_id uuid, _expected_identity jsonb, _report jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _job public.builder_jobs%rowtype; _step public.builder_job_steps%rowtype; _receipt jsonb;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  SELECT * INTO _job FROM public.builder_jobs WHERE id = _job_id FOR UPDATE;
  IF _job.id IS NULL OR _job.status <> 'security_review' THEN
    RAISE EXCEPTION 'Job is not ready for whole-job acceptance';
  END IF;
  PERFORM 1 FROM public.builder_job_steps WHERE job_id = _job_id FOR UPDATE;
  IF _expected_identity IS DISTINCT FROM public.builder_implementation_acceptance_identity(_job_id)
    OR EXISTS (SELECT 1 FROM public.builder_worker_runs WHERE job_id = _job_id AND status = 'running')
    OR EXISTS (SELECT 1 FROM public.builder_model_runs WHERE job_id = _job_id AND status = 'running')
  THEN RAISE EXCEPTION 'Acceptance evidence changed or work is active'; END IF;
  IF _report IS NULL OR jsonb_typeof(_report) <> 'object' OR octet_length(_report::text) > 262144
    OR (_report->>'version') IS DISTINCT FROM '1'
    OR jsonb_typeof(_report->'passed') IS DISTINCT FROM 'boolean'
    OR jsonb_typeof(_report->'requirements') IS DISTINCT FROM 'array'
    OR jsonb_typeof(_report->'blockers') IS DISTINCT FROM 'array'
  THEN RAISE EXCEPTION 'Invalid whole-job acceptance report'; END IF;
  IF _report->>'passed' = 'true' AND (
    jsonb_array_length(_report->'requirements') NOT BETWEEN 1 AND 100
    OR jsonb_array_length(_report->'blockers') <> 0
    OR EXISTS (SELECT 1 FROM jsonb_array_elements(_report->'requirements') r
      WHERE r->>'status' IS DISTINCT FROM 'covered' OR COALESCE(btrim(r->>'requirement_id'), '') = '')
    OR (SELECT count(DISTINCT r->>'requirement_id') FROM jsonb_array_elements(_report->'requirements') r)
      <> jsonb_array_length(_report->'requirements')
  ) THEN RAISE EXCEPTION 'Passing acceptance report has unresolved requirements'; END IF;
  SELECT * INTO _step FROM public.builder_job_steps WHERE job_id = _job_id AND step_id = 'test_suite';
  IF _step.id IS NULL THEN RAISE EXCEPTION 'Acceptance test step is missing'; END IF;
  _receipt := jsonb_build_object('identity', _expected_identity, 'report', _report);
  IF _step.input_context->'implementation_acceptance' IS NOT DISTINCT FROM _receipt THEN RETURN; END IF;
  UPDATE public.builder_job_steps SET input_context = COALESCE(input_context, '{}'::jsonb)
    || jsonb_build_object('implementation_acceptance', _receipt),
    result_summary = CASE WHEN _report->>'passed' = 'true'
      THEN 'Whole-job acceptance coverage reconciled; semantic and human review still required'
      ELSE 'Whole-job acceptance incomplete: ' || left((
        SELECT string_agg(value, ' ') FROM jsonb_array_elements_text(_report->'blockers')
      ), 3000) END, updated_at = now() WHERE id = _step.id;
  INSERT INTO public.builder_audit_events(organization_id, job_id, event_type, actor_type,
    new_value, change_summary)
  VALUES (_job.organization_id, _job.id, 'step_completed', 'bot', _receipt,
    CASE WHEN _report->>'passed' = 'true' THEN 'Whole-job acceptance coverage reconciled; human/semantic review still required'
      ELSE 'Whole-job acceptance incomplete; correction required before approval or release' END);
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_record_implementation_acceptance"(_job_id uuid, _expected_identity jsonb, _report jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_record_implementation_acceptance"(_job_id uuid, _expected_identity jsonb, _report jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_record_implementation_acceptance"(_job_id uuid, _expected_identity jsonb, _report jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_record_pull_request_closed"(_job_id uuid, _pull_request_url text, _details jsonb DEFAULT '{}'::jsonb)
 RETURNS builder_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _job public.builder_jobs%rowtype;
  _updated public.builder_jobs%rowtype;
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;
  IF NULLIF(btrim(_pull_request_url), '') IS NULL THEN
    RAISE EXCEPTION 'Pull request URL required';
  END IF;
  IF _details IS NULL OR jsonb_typeof(_details) <> 'object' THEN
    RAISE EXCEPTION 'Pull request closure details must be an object';
  END IF;

  SELECT * INTO _job FROM public.builder_jobs WHERE id = _job_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Builder job not found';
  END IF;
  IF _job.status IN ('deployed', 'failed', 'cancelled') THEN
    RETURN _job;
  END IF;
  IF _job.workspace_pull_request_url IS DISTINCT FROM btrim(_pull_request_url) THEN
    RAISE EXCEPTION 'Pull request does not belong to this Builder job';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.builder_model_runs WHERE job_id = _job.id AND status IN ('pending', 'running')
  ) OR EXISTS (
    SELECT 1 FROM public.builder_worker_runs WHERE job_id = _job.id AND status IN ('pending', 'running')
  ) THEN
    RAISE EXCEPTION 'Builder job still has active execution';
  END IF;

  UPDATE public.builder_approvals
  SET status = 'cancelled',
      approval_comment = COALESCE(approval_comment, 'Cancelled because the pull request was closed without merging.'),
      responded_at = COALESCE(responded_at, now()),
      updated_at = now()
  WHERE job_id = _job.id AND status = 'pending';

  UPDATE public.builder_jobs
  SET status = 'cancelled',
      last_error = 'Cancelled: pull request closed without merging',
      autopilot_state = CASE
        WHEN autopilot_requested_by IS NOT NULL OR autopilot_source IN ('main_monitor', 'routine_monitor') THEN 'done'
        ELSE autopilot_state
      END,
      updated_at = now()
  WHERE id = _job.id
  RETURNING * INTO _updated;

  INSERT INTO public.builder_audit_events (
    organization_id, job_id, event_type, actor_type, previous_value, new_value, change_summary
  ) VALUES (
    _job.organization_id, _job.id, 'job_cancelled', 'bot',
    jsonb_build_object('status', _job.status),
    jsonb_build_object('status', 'cancelled', 'reason', 'pull_request_closed_unmerged', 'pull_request_url', _job.workspace_pull_request_url) || _details,
    'Builder job cancelled because its pull request was closed without merging'
  );

  RETURN _updated;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_record_pull_request_closed"(_job_id uuid, _pull_request_url text, _details jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_record_pull_request_closed"(_job_id uuid, _pull_request_url text, _details jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_record_pull_request_closed"(_job_id uuid, _pull_request_url text, _details jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_record_workspace_commit"(_job_id uuid, _expected_head_sha text, _commit_sha text)
 RETURNS builder_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _job public.builder_jobs%rowtype;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  IF _expected_head_sha !~ '^[a-f0-9]{40}$' OR _commit_sha !~ '^[a-f0-9]{40}$' THEN RAISE EXCEPTION 'Builder workspace commit is invalid'; END IF;
  SELECT * INTO _job FROM public.builder_jobs WHERE id = _job_id FOR UPDATE;
  IF _job.id IS NULL OR _job.workspace_branch IS NULL OR _job.workspace_head_sha IS DISTINCT FROM _expected_head_sha THEN RAISE EXCEPTION 'Builder workspace head is stale'; END IF;
  UPDATE public.builder_jobs SET workspace_head_sha = _commit_sha, updated_at = now() WHERE id = _job.id RETURNING * INTO _job;
  INSERT INTO public.builder_audit_events (organization_id, job_id, event_type, actor_type, previous_value, new_value, change_summary)
  VALUES (_job.organization_id, _job.id, 'step_completed', 'builder_mode', jsonb_build_object('workspace_head_sha', _expected_head_sha), jsonb_build_object('workspace_head_sha', _commit_sha), 'Verified Builder patch committed to dedicated workspace branch');
  RETURN _job;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_record_workspace_commit"(_job_id uuid, _expected_head_sha text, _commit_sha text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_record_workspace_commit"(_job_id uuid, _expected_head_sha text, _commit_sha text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_record_workspace_commit"(_job_id uuid, _expected_head_sha text, _commit_sha text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_record_workspace_publication"(_job_id uuid, _expected_head_sha text)
 RETURNS builder_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _job public.builder_jobs%rowtype;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  IF _expected_head_sha !~ '^[a-f0-9]{40}$' THEN RAISE EXCEPTION 'Builder workspace commit is invalid'; END IF;
  SELECT * INTO _job FROM public.builder_jobs WHERE id = _job_id FOR UPDATE;
  IF _job.id IS NULL OR _job.workspace_branch IS NULL OR _job.workspace_head_sha IS DISTINCT FROM _expected_head_sha THEN RAISE EXCEPTION 'Builder workspace head is stale'; END IF;
  UPDATE public.builder_jobs SET workspace_published_at = now(), workspace_published_head_sha = _expected_head_sha, updated_at = now()
  WHERE id = _job.id RETURNING * INTO _job;
  INSERT INTO public.builder_audit_events (organization_id, job_id, event_type, actor_type, new_value, change_summary)
  VALUES (_job.organization_id, _job.id, 'step_completed', 'builder_mode', jsonb_build_object('workspace_branch', _job.workspace_branch, 'workspace_head_sha', _expected_head_sha), 'Verified Builder branch published for review; no merge or deployment performed');
  RETURN _job;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_record_workspace_publication"(_job_id uuid, _expected_head_sha text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_record_workspace_publication"(_job_id uuid, _expected_head_sha text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_record_workspace_publication"(_job_id uuid, _expected_head_sha text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_record_workspace_pull_request"(_job_id uuid, _expected_head_sha text, _pull_request_url text)
 RETURNS builder_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _job public.builder_jobs%rowtype;
DECLARE _host text;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  IF _expected_head_sha !~ '^[a-f0-9]{40}$' THEN RAISE EXCEPTION 'Builder pull request metadata is invalid'; END IF;
  IF _pull_request_url ~ '^https://github\.com/[^/[:space:]]+/[^/[:space:]]+/pull/[0-9]+$' THEN
    _host := 'github';
  ELSIF _pull_request_url ~ '^https?://[^[:space:]]+/pulls/[0-9]+$' THEN
    _host := 'gitea';
  ELSE
    RAISE EXCEPTION 'Builder pull request metadata is invalid';
  END IF;
  SELECT * INTO _job FROM public.builder_jobs WHERE id = _job_id FOR UPDATE;
  IF _job.id IS NULL OR _job.workspace_branch IS NULL OR _job.workspace_published_head_sha IS DISTINCT FROM _expected_head_sha OR _job.workspace_head_sha IS DISTINCT FROM _expected_head_sha THEN RAISE EXCEPTION 'Builder workspace publication is stale'; END IF;
  UPDATE public.builder_jobs SET workspace_pull_request_url = _pull_request_url, workspace_pull_request_head_sha = _expected_head_sha, workspace_pull_request_created_at = now(), updated_at = now() WHERE id = _job.id RETURNING * INTO _job;
  INSERT INTO public.builder_audit_events (organization_id, job_id, event_type, actor_type, new_value, change_summary)
  VALUES (_job.organization_id, _job.id, 'step_completed', 'builder_mode', jsonb_build_object('workspace_branch', _job.workspace_branch, 'workspace_head_sha', _expected_head_sha, 'pull_request_url', _pull_request_url, 'host', _host), 'Verified Builder branch opened as a ' || _host || ' pull request for human review; no merge or deployment performed');
  RETURN _job;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_record_workspace_pull_request"(_job_id uuid, _expected_head_sha text, _pull_request_url text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_record_workspace_pull_request"(_job_id uuid, _expected_head_sha text, _pull_request_url text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_record_workspace_pull_request"(_job_id uuid, _expected_head_sha text, _pull_request_url text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_recover_expired_security_review"()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _count integer;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  WITH expired AS (
    UPDATE public.builder_worker_runs
    SET status = 'timeout', completed_at = now(), lease_token_hash = NULL,
        output_artifact_ids = '{}', review_summary = '{}'::jsonb, updated_at = now()
    WHERE profile = 'security-review' AND status = 'running' AND lease_expires_at <= now()
    RETURNING job_id, step_id
  ), updated_steps AS (
    UPDATE public.builder_job_steps step
    SET status = 'failed', retryable = true, error = 'Security review worker lease expired', updated_at = now()
    FROM expired WHERE step.id = expired.step_id RETURNING expired.job_id
  )
  UPDATE public.builder_jobs job
  SET status = 'testing', last_error = 'Security review worker lease expired', updated_at = now()
  WHERE job.id IN (SELECT job_id FROM updated_steps);
  GET DIAGNOSTICS _count = ROW_COUNT;
  RETURN _count;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_recover_expired_security_review"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_recover_expired_security_review"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_recover_expired_security_review"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_recover_expired_worker_runs"(_include_active boolean DEFAULT false, _reason text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _count integer; _why text;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  _why := left(COALESCE(NULLIF(btrim(_reason), ''), CASE WHEN COALESCE(_include_active, false) THEN 'runner restarted before the verifier reported' ELSE 'worker lease expired: the runner was lost before it reported' END), 300);
  WITH expired AS (
    UPDATE public.builder_worker_runs
    SET status = 'timeout', completed_at = now(), lease_token_hash = NULL, lease_expires_at = NULL,
        log_summary = left(COALESCE(log_summary, '') || CASE WHEN log_summary IS NULL OR log_summary = '' THEN '' ELSE ' | ' END
          || _why || '; the same patch is verified again', 1000),
        updated_at = now()
    WHERE profile IN ('frontend-verify', 'backend-verify') AND status = 'running'
      AND (COALESCE(_include_active, false) OR lease_expires_at <= now())
    RETURNING id, job_id, step_id, organization_id, profile
  ), updated_steps AS (
    UPDATE public.builder_job_steps step
    SET status = 'failed', retryable = true, completed_at = now(), updated_at = now(),
        error = CASE WHEN expired.profile = 'frontend-verify' THEN 'Frontend' ELSE 'Backend' END
          || ' worker lease expired (runner lost); the same patch is verified again'
    FROM expired WHERE step.id = expired.step_id
    RETURNING expired.job_id, expired.id AS run_id, expired.organization_id, expired.profile, step.step_id AS step_name
  ), updated_jobs AS (
    UPDATE public.builder_jobs job
    SET status = 'implementation_pending', last_error = 'Verification worker lease expired (runner lost); verifying the same patch again', updated_at = now()
    WHERE job.id IN (SELECT job_id FROM updated_steps) AND job.status NOT IN ('deployed', 'failed', 'cancelled')
    RETURNING id
  )
  INSERT INTO public.builder_audit_events (organization_id, job_id, event_type, actor_type, previous_value, new_value, change_summary)
  SELECT organization_id, job_id, 'step_failed', 'bot',
    jsonb_build_object('step', step_name, 'step_status', 'running', 'worker_run_id', run_id),
    jsonb_build_object('step', step_name, 'step_status', 'failed', 'retryable', true, 'worker_run_status', 'timeout', 'reason', _why),
    'Verification worker run ended without a report (' || _why || '); step returned to failed/retryable so the same patch is verified again'
  FROM updated_steps;
  GET DIAGNOSTICS _count = ROW_COUNT;
  RETURN _count;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_recover_expired_worker_runs"(_include_active boolean, _reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_recover_expired_worker_runs"(_include_active boolean, _reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_recover_expired_worker_runs"(_include_active boolean, _reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_register_release_artifact"(_job_id uuid, _step_id uuid, _artifact_type text, _object_path text, _sha256 text, _size_bytes integer)
 RETURNS builder_artifacts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _job public.builder_jobs%rowtype; _step public.builder_job_steps%rowtype; _artifact public.builder_artifacts%rowtype;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  IF _artifact_type NOT IN ('release_notes', 'rollback_plan', 'deployment_manifest') THEN RAISE EXCEPTION 'Unsupported release artifact type'; END IF;
  IF _object_path IS NULL OR _object_path = '' OR _object_path LIKE '%..%' THEN RAISE EXCEPTION 'Invalid release artifact path'; END IF;
  IF _sha256 !~ '^[a-f0-9]{64}$' OR _size_bytes < 0 OR _size_bytes > 10485760 THEN RAISE EXCEPTION 'Invalid release artifact integrity metadata'; END IF;
  SELECT * INTO _job FROM public.builder_jobs WHERE id = _job_id FOR UPDATE;
  SELECT * INTO _step FROM public.builder_job_steps WHERE id = _step_id AND job_id = _job_id FOR UPDATE;
  IF _job.id IS NULL OR _job.status <> 'security_review' OR _step.id IS NULL OR _step.status <> 'running' OR _step.builder_mode <> 'release_engineer' THEN
    RAISE EXCEPTION 'Release preparation is not running';
  END IF;
  INSERT INTO public.builder_artifacts (job_id, step_id, artifact_type, content_type, content_size_bytes, storage_location, checksum, status)
  VALUES (_job.id, _step.id, _artifact_type, 'application/json', _size_bytes,
    'supabase_storage://builder-artifacts/' || _object_path, _sha256, 'final') RETURNING * INTO _artifact;
  UPDATE public.builder_job_steps
  SET artifact_ids = CASE WHEN _artifact.id = ANY(COALESCE(artifact_ids, '{}')) THEN artifact_ids
    ELSE array_append(COALESCE(artifact_ids, '{}'), _artifact.id) END, updated_at = now()
  WHERE id = _step.id;
  INSERT INTO public.builder_audit_events (organization_id, job_id, event_type, actor_type, new_value, change_summary, related_artifact_ids)
  VALUES (_job.organization_id, _job.id, 'artifact_created', 'builder_mode',
    jsonb_build_object('artifact_type', _artifact_type, 'checksum', _sha256, 'target_sha', _job.target_sha),
    'Release preparation artifact registered', ARRAY[_artifact.id]);
  RETURN _artifact;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_register_release_artifact"(_job_id uuid, _step_id uuid, _artifact_type text, _object_path text, _sha256 text, _size_bytes integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_register_release_artifact"(_job_id uuid, _step_id uuid, _artifact_type text, _object_path text, _sha256 text, _size_bytes integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_register_release_artifact"(_job_id uuid, _step_id uuid, _artifact_type text, _object_path text, _sha256 text, _size_bytes integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_register_security_review"(_run_id uuid, _lease_token text, _object_path text, _sha256 text, _size_bytes integer)
 RETURNS builder_artifacts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _run public.builder_worker_runs%rowtype; _artifact public.builder_artifacts%rowtype;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  SELECT * INTO _run FROM public.builder_worker_runs WHERE id = _run_id AND profile = 'security-review' AND status = 'running'
    AND lease_expires_at > now() AND lease_token_hash = encode(extensions.digest(_lease_token, 'sha256'), 'hex') FOR UPDATE;
  IF _run.id IS NULL THEN RAISE EXCEPTION 'Security review lease is missing, expired, or invalid'; END IF;
  IF _object_path IS NULL OR _object_path = '' OR _object_path LIKE '%..%' THEN RAISE EXCEPTION 'Invalid security artifact path'; END IF;
  IF _sha256 !~ '^[a-f0-9]{64}$' OR _size_bytes < 0 OR _size_bytes > 10485760 THEN RAISE EXCEPTION 'Invalid security artifact integrity metadata'; END IF;
  INSERT INTO public.builder_artifacts (job_id, step_id, artifact_type, content_type, content_size_bytes, storage_location, checksum, status)
  VALUES (_run.job_id, _run.step_id, 'security_review', 'application/json', _size_bytes,
    'supabase_storage://builder-artifacts/' || _object_path, _sha256, 'final') RETURNING * INTO _artifact;
  UPDATE public.builder_worker_runs SET output_artifact_ids = ARRAY[_artifact.id], updated_at = now() WHERE id = _run.id;
  INSERT INTO public.builder_audit_events (organization_id, job_id, event_type, actor_type, new_value, change_summary, related_artifact_ids)
  VALUES (_run.organization_id, _run.job_id, 'artifact_created', 'builder_mode',
    jsonb_build_object('worker_run_id', _run.id, 'artifact_type', 'security_review', 'checksum', _sha256),
    'Independent security review artifact registered', ARRAY[_artifact.id]);
  RETURN _artifact;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_register_security_review"(_run_id uuid, _lease_token text, _object_path text, _sha256 text, _size_bytes integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_register_security_review"(_run_id uuid, _lease_token text, _object_path text, _sha256 text, _size_bytes integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_register_security_review"(_run_id uuid, _lease_token text, _object_path text, _sha256 text, _size_bytes integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_register_worker_artifact"(_run_id uuid, _lease_token text, _artifact_type text, _content_type text, _object_path text, _sha256 text, _size_bytes integer)
 RETURNS builder_artifacts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _run public.builder_worker_runs%rowtype; _artifact public.builder_artifacts%rowtype;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  SELECT * INTO _run FROM public.builder_worker_runs WHERE id = _run_id AND status = 'running'
    AND lease_expires_at > now() AND lease_token_hash = encode(extensions.digest(_lease_token, 'sha256'), 'hex') FOR UPDATE;
  IF _run.id IS NULL THEN RAISE EXCEPTION 'Worker lease is missing, expired, or invalid'; END IF;
  IF _artifact_type NOT IN ('code_implementation', 'changed_file_manifest', 'build_logs') THEN RAISE EXCEPTION 'Unsupported worker artifact type'; END IF;
  IF _object_path IS NULL OR _object_path = '' OR _object_path LIKE '%..%' THEN RAISE EXCEPTION 'Invalid artifact object path'; END IF;
  IF _sha256 !~ '^[a-f0-9]{64}$' OR _size_bytes < 0 OR _size_bytes > 10485760 THEN RAISE EXCEPTION 'Invalid artifact integrity metadata'; END IF;
  IF _content_type NOT IN ('application/json', 'text/plain', 'text/x-diff') THEN RAISE EXCEPTION 'Unsupported artifact content type'; END IF;
  INSERT INTO public.builder_artifacts (job_id, step_id, artifact_type, content_type, content_size_bytes, storage_location, checksum, status)
  VALUES (_run.job_id, _run.step_id, _artifact_type, _content_type, _size_bytes,
    'supabase_storage://builder-artifacts/' || _object_path, _sha256, 'final') RETURNING * INTO _artifact;
  UPDATE public.builder_worker_runs SET output_artifact_ids = array_append(COALESCE(output_artifact_ids, '{}'), _artifact.id), updated_at = now() WHERE id = _run.id;
  INSERT INTO public.builder_audit_events (organization_id, job_id, event_type, actor_type, new_value, change_summary, related_artifact_ids)
  VALUES (_run.organization_id, _run.job_id, 'artifact_created', 'builder_mode', jsonb_build_object('worker_run_id', _run.id, 'artifact_type', _artifact_type, 'checksum', _sha256), 'Verified frontend worker artifact registered', ARRAY[_artifact.id]);
  RETURN _artifact;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_register_worker_artifact"(_run_id uuid, _lease_token text, _artifact_type text, _content_type text, _object_path text, _sha256 text, _size_bytes integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_register_worker_artifact"(_run_id uuid, _lease_token text, _artifact_type text, _content_type text, _object_path text, _sha256 text, _size_bytes integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_register_worker_artifact"(_run_id uuid, _lease_token text, _artifact_type text, _content_type text, _object_path text, _sha256 text, _size_bytes integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_reopen_required_implementation_lanes"(_job_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_job public.builder_jobs%ROWTYPE;
  v_approval public.builder_approvals%ROWTYPE;
  v_step public.builder_job_steps%ROWTYPE;
  v_approval_id uuid;
  v_reopened text[] := ARRAY[]::text[];
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;

  SELECT * INTO v_job FROM public.builder_jobs WHERE id = _job_id FOR UPDATE;
  IF v_job.id IS NULL OR v_job.status <> 'implementation_pending'
    OR v_job.code_review_mode <> 'human' OR v_job.code_review_status <> 'pending'
    OR v_job.code_review_revision IS NULL THEN
    RAISE EXCEPTION 'Job is not continuing a confirmed human implementation correction';
  END IF;

  v_approval_id := NULLIF(v_job.code_review_revision->>'approval_id', '')::uuid;
  SELECT * INTO v_approval FROM public.builder_approvals
    WHERE id = v_approval_id AND job_id = v_job.id FOR UPDATE;
  IF v_approval.id IS NULL OR v_approval.status <> 'cancelled'
    OR v_approval.approval_type <> 'implementation_review'
    OR v_approval.requested_target_sha IS DISTINCT FROM v_job.target_sha
    OR v_job.workspace_published_at IS NOT NULL OR v_job.workspace_published_head_sha IS NOT NULL
    OR v_job.workspace_pull_request_url IS NOT NULL THEN
    RAISE EXCEPTION 'Confirmed correction is stale or already published';
  END IF;
  IF EXISTS (SELECT 1 FROM public.builder_job_steps WHERE job_id = v_job.id AND status = 'running')
    OR EXISTS (SELECT 1 FROM public.builder_worker_runs WHERE job_id = v_job.id AND status IN ('pending', 'running'))
    OR EXISTS (SELECT 1 FROM public.builder_model_runs WHERE job_id = v_job.id AND status IN ('pending', 'running'))
    OR EXISTS (SELECT 1 FROM public.builder_approvals WHERE job_id = v_job.id AND status = 'pending')
    OR EXISTS (SELECT 1 FROM public.builder_job_steps WHERE job_id = v_job.id AND step_id = 'release_prep'
      AND (status <> 'pending' OR started_at IS NOT NULL OR completed_at IS NOT NULL)) THEN
    RAISE EXCEPTION 'Required implementation lanes can only reopen before work or release starts';
  END IF;
  IF v_job.code_review_revision ? 'reopened_required_lanes' THEN
    RETURN jsonb_build_object('reopened', v_job.code_review_revision->'reopened_required_lanes');
  END IF;

  FOR v_step IN
    SELECT * FROM public.builder_job_steps
    WHERE job_id = v_job.id AND status = 'skipped'
      AND ((step_id = 'frontend_implementation' AND v_job.frontend_required)
        OR (step_id = 'backend_implementation' AND v_job.backend_required))
    ORDER BY ordinal_position
    FOR UPDATE
  LOOP
    UPDATE public.builder_job_steps SET status = 'pending', started_at = NULL, completed_at = NULL,
      result_summary = NULL, error = NULL, retryable = false, blocked_reason = NULL, artifact_ids = NULL,
      updated_at = now()
    WHERE id = v_step.id;
    v_reopened := array_append(v_reopened, v_step.step_id);
    INSERT INTO public.builder_audit_events (
      organization_id, job_id, event_type, actor_type, previous_value, new_value, change_summary, related_approval_id
    ) VALUES (
      v_job.organization_id, v_job.id, 'error_recorded', 'builder_mode',
      jsonb_build_object('step_id', v_step.step_id, 'status', 'skipped'),
      jsonb_build_object('step_id', v_step.step_id, 'status', 'pending', 'cause', 'required_lane_skipped'),
      'Reopened a required implementation lane for the confirmed same-job correction',
      v_approval.id
    );
  END LOOP;

  UPDATE public.builder_jobs SET code_review_revision = code_review_revision || jsonb_build_object(
    'reopened_required_lanes', to_jsonb(v_reopened), 'required_lanes_reopened_at', now()
  ), updated_at = now()
  WHERE id = v_job.id;

  RETURN jsonb_build_object('reopened', to_jsonb(v_reopened));
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_reopen_required_implementation_lanes"(_job_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_reopen_required_implementation_lanes"(_job_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_reopen_required_implementation_lanes"(_job_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_request_approval"(_job_id uuid, _approval_type text, _artifact_ids uuid[], _requested_from_users uuid[] DEFAULT '{}'::uuid[])
 RETURNS builder_approvals
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _job public.builder_jobs%rowtype;
  _approval public.builder_approvals%rowtype;
  _expected_status text;
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;

  _expected_status := CASE _approval_type
    WHEN 'specification_review' THEN 'specification_ready'
    WHEN 'release_approval' THEN 'approval_pending'
    ELSE NULL
  END;
  IF _expected_status IS NULL THEN
    RAISE EXCEPTION 'Unsupported approval gate';
  END IF;
  IF COALESCE(cardinality(_artifact_ids), 0) = 0 THEN
    RAISE EXCEPTION 'At least one review artifact is required';
  END IF;

  SELECT * INTO _job
  FROM public.builder_jobs
  WHERE id = _job_id
  FOR UPDATE;

  IF NOT FOUND OR _job.status <> _expected_status THEN
    RAISE EXCEPTION 'Job is not at the requested approval gate';
  END IF;
  IF (
    SELECT count(*)
    FROM public.builder_artifacts
    WHERE job_id = _job.id
      AND id = ANY(_artifact_ids)
      AND status = 'final'
  ) <> cardinality(_artifact_ids) THEN
    RAISE EXCEPTION 'Review artifacts must be final and belong to the job';
  END IF;

  INSERT INTO public.builder_approvals (
    organization_id,
    job_id,
    approval_type,
    triggered_at_status,
    status,
    requested_from_users,
    requested_target_sha,
    reviewed_artifact_ids
  )
  VALUES (
    _job.organization_id,
    _job.id,
    _approval_type,
    _expected_status,
    'pending',
    COALESCE(_requested_from_users, '{}'),
    _job.target_sha,
    _artifact_ids
  )
  RETURNING * INTO _approval;

  INSERT INTO public.builder_audit_events (
    organization_id,
    job_id,
    event_type,
    actor_type,
    new_value,
    change_summary,
    related_artifact_ids,
    related_approval_id
  )
  VALUES (
    _job.organization_id,
    _job.id,
    'approval_requested',
    'bot',
    jsonb_build_object(
      'approval_type', _approval_type,
      'triggered_at_status', _expected_status,
      'target_sha', _job.target_sha
    ),
    'Builder approval requested with immutable evidence snapshot',
    _artifact_ids,
    _approval.id
  );

  RETURN _approval;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_request_approval"(_job_id uuid, _approval_type text, _artifact_ids uuid[], _requested_from_users uuid[]) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_request_approval"(_job_id uuid, _approval_type text, _artifact_ids uuid[], _requested_from_users uuid[]) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_request_approval"(_job_id uuid, _approval_type text, _artifact_ids uuid[], _requested_from_users uuid[]) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_requeue_failed_routine_repairs"(_release_sha text, _released_at timestamp with time zone, _limit integer DEFAULT 3)
 RETURNS SETOF bob_friction_packets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _candidate record;
  _packet public.bob_friction_packets%rowtype;
  _last_job public.builder_jobs%rowtype;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;
  IF _release_sha IS NULL OR _release_sha !~ '^[a-f0-9]{40}$' THEN
    RAISE EXCEPTION 'A full lowercase release SHA is required';
  END IF;
  IF _released_at IS NULL OR _released_at > now() + interval '5 minutes' THEN
    RAISE EXCEPTION 'A past release time is required';
  END IF;

  FOR _candidate IN
    SELECT packet.id, packet.covered_by_job_id
    FROM public.bob_friction_packets packet
    WHERE packet.automation_status = 'failed'
      AND packet.repair_risk = 'routine'
      AND packet.route = 'dispatch_flow'
      AND packet.stop_line_hit IS NULL
      AND packet.disposition IN ('open', 'reviewing')
      AND packet.automation_attempt_count < 3
      -- It failed under code that has since been replaced; a failure under this release waits for the next.
      AND packet.automation_updated_at < _released_at
      AND packet.created_at > now() - interval '21 days'
      AND NOT EXISTS (
        SELECT 1 FROM public.builder_jobs job
        WHERE (job.source_friction_packet_id = packet.id OR job.id = packet.covered_by_job_id)
          AND job.status NOT IN ('failed', 'cancelled', 'deployed')
      )
    ORDER BY packet.automation_updated_at, packet.created_at
    LIMIT LEAST(GREATEST(COALESCE(_limit, 3), 1), 10)
    FOR UPDATE OF packet SKIP LOCKED
  LOOP
    UPDATE public.bob_friction_packets packet
    SET automation_status = 'queued',
        covered_by_job_id = NULL,
        automation_error_redacted = left('Re-queued after release ' || left(_release_sha, 8)
          || ' for attempt ' || (packet.automation_attempt_count + 1) || ' of 3.', 300),
        automation_updated_at = now()
    WHERE packet.id = _candidate.id
    RETURNING packet.* INTO _packet;

    -- The job that last tried: the packet's own intake chain, or the repair that covered it.
    SELECT * INTO _last_job
    FROM public.builder_jobs job
    WHERE job.source_friction_packet_id = _packet.id
       OR job.id = _packet.builder_job_id
       OR job.id = _candidate.covered_by_job_id
    ORDER BY job.updated_at DESC
    LIMIT 1;

    IF FOUND THEN
      INSERT INTO public.builder_audit_events (
        organization_id, job_id, event_type, actor_user_id, actor_type,
        previous_value, new_value, change_summary
      ) VALUES (
        _last_job.organization_id, _last_job.id, 'routine_repair_requeued', _packet.user_id, 'bot',
        jsonb_build_object('packet_id', _packet.id, 'automation_status', 'failed', 'job_status', _last_job.status),
        jsonb_build_object('packet_id', _packet.id, 'automation_status', 'queued',
          'release_sha', _release_sha, 'next_attempt', _packet.automation_attempt_count + 1, 'max_attempts', 3),
        'Bob re-queued a failed routine repair after a verified production release; the next attempt is bounded by the same routine policy'
      );
    END IF;

    RETURN NEXT _packet;
  END LOOP;
END;
$function$;
COMMENT ON FUNCTION "public"."builder_requeue_failed_routine_repairs"(_release_sha text, _released_at timestamp with time zone, _limit integer) IS 'Service-only. Re-queues failed routine friction packets once per verified production release (at most 3 attempts, 21 days) and audits each requeue.';
REVOKE ALL ON FUNCTION "public"."builder_requeue_failed_routine_repairs"(_release_sha text, _released_at timestamp with time zone, _limit integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_requeue_failed_routine_repairs"(_release_sha text, _released_at timestamp with time zone, _limit integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_requeue_failed_routine_repairs"(_release_sha text, _released_at timestamp with time zone, _limit integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_require_human_code_review_evidence"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _required_types text[] := ARRAY['code_implementation','changed_file_manifest','build_logs','security_review'];
BEGIN
  IF NEW.approval_type <> 'implementation_review' THEN RETURN NEW; END IF;
  IF EXISTS (SELECT 1 FROM unnest(_required_types) required_type WHERE NOT EXISTS (
    SELECT 1 FROM public.builder_artifacts artifact
    WHERE artifact.job_id = NEW.job_id AND artifact.id = ANY(NEW.reviewed_artifact_ids)
      AND artifact.artifact_type = required_type AND artifact.status = 'final'
  )) THEN RAISE EXCEPTION 'Human code review requires the complete verified artifact set'; END IF;
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_require_human_code_review_evidence"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_require_human_code_review_evidence"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_require_human_code_review_evidence"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_require_implementation_acceptance"(_job_id uuid, _require_passed boolean DEFAULT true)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _receipt jsonb;
BEGIN
  SELECT input_context->'implementation_acceptance' INTO _receipt FROM public.builder_job_steps
    WHERE job_id = _job_id AND step_id = 'test_suite';
  IF _receipt IS NULL OR (_require_passed AND (_receipt->'report'->>'passed') IS DISTINCT FROM 'true')
    OR _receipt->'identity' IS DISTINCT FROM public.builder_implementation_acceptance_identity(_job_id)
  THEN RAISE EXCEPTION 'Whole-job acceptance incomplete or stale; reconcile every approved delivery requirement before review or release'; END IF;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_require_implementation_acceptance"(_job_id uuid, _require_passed boolean) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_require_implementation_acceptance"(_job_id uuid, _require_passed boolean) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."builder_require_release_approval_evidence"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _required_types text[] := ARRAY['code_implementation','changed_file_manifest','build_logs','security_review','release_notes','rollback_plan','deployment_manifest']; _review_mode text;
BEGIN
  IF NEW.approval_type <> 'release_approval' THEN RETURN NEW; END IF;
  SELECT code_review_mode INTO _review_mode FROM public.builder_jobs WHERE id = NEW.job_id;
  IF _review_mode = 'independent_ai' THEN _required_types := array_append(_required_types, 'code_review'); END IF;
  IF EXISTS (SELECT 1 FROM unnest(_required_types) required_type WHERE NOT EXISTS (
    SELECT 1 FROM public.builder_artifacts artifact WHERE artifact.job_id = NEW.job_id AND artifact.id = ANY(NEW.reviewed_artifact_ids)
      AND artifact.artifact_type = required_type AND artifact.status = 'final'
  )) THEN RAISE EXCEPTION 'Release approval requires the complete verified artifact set'; END IF;
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_require_release_approval_evidence"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_require_release_approval_evidence"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_require_release_approval_evidence"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_reset_backend_worker_retry"(_run_id uuid)
 RETURNS builder_worker_runs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _run public.builder_worker_runs%rowtype;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  UPDATE public.builder_worker_runs
  SET output_artifact_ids = '{}', exit_code = NULL, log_summary = NULL,
      dangerous_patterns_detected = '{}', secrets_redacted_count = 0, updated_at = now()
  WHERE id = _run_id AND profile = 'backend-verify' AND status = 'running'
  RETURNING * INTO _run;
  IF _run.id IS NULL THEN RAISE EXCEPTION 'Active backend worker run not found'; END IF;
  RETURN _run;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_reset_backend_worker_retry"(_run_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_reset_backend_worker_retry"(_run_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_reset_backend_worker_retry"(_run_id uuid) TO "service_role";

