CREATE OR REPLACE FUNCTION "public"."builder_resolve_historical_health_job"(_job_id uuid, _organization_id uuid, _project_id uuid, _main_sha text, _source_sha text, _verified_files text[], _verification jsonb)
 RETURNS builder_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _job public.builder_jobs%rowtype;
  _updated public.builder_jobs%rowtype;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  IF _main_sha IS NULL OR _main_sha !~ '^[a-f0-9]{40}$'
     OR _source_sha IS NULL OR _source_sha !~ '^[a-f0-9]{40}$' OR _main_sha = _source_sha
     OR _verification IS NULL
     OR _verification->>'status' IS DISTINCT FROM 'passed'
     OR _verification->>'profile' IS DISTINCT FROM 'main-health'
     OR _verification->>'sha' IS DISTINCT FROM _main_sha
     OR NULLIF(_verification->>'checked_at', '') IS NULL THEN
    RAISE EXCEPTION 'A passed pinned main-health receipt is required';
  END IF;
  SELECT * INTO _job FROM public.builder_jobs
  WHERE id = _job_id AND organization_id = _organization_id AND project_id = _project_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Historical job is unavailable in this project'; END IF;
  IF _job.status NOT IN ('failed', 'cancelled')
     OR _job.autopilot_source IS DISTINCT FROM 'main_monitor'
     OR _job.source_main_health_sha IS DISTINCT FROM _source_sha
     OR _job.workspace_branch IS NOT NULL OR _job.workspace_pull_request_url IS NOT NULL THEN
    RAISE EXCEPTION 'Only workspace-free failed or cancelled main-health jobs can be resolved';
  END IF;
  IF _job.autopilot_state = 'done' THEN RETURN _job; END IF;
  IF COALESCE(cardinality(_job.source_main_health_files), 0) NOT BETWEEN 1 AND 8
     OR _verified_files IS NULL OR NOT (_verified_files @> _job.source_main_health_files)
     OR EXISTS (
       SELECT 1 FROM unnest(_job.source_main_health_files) AS file_name
       WHERE NOT public.builder_main_health_test_path_valid(file_name)
     ) THEN
    RAISE EXCEPTION 'Every original failing test must be covered by the current verification';
  END IF;
  IF EXISTS (SELECT 1 FROM public.builder_model_runs WHERE job_id = _job.id AND status IN ('pending', 'queued', 'running'))
     OR EXISTS (SELECT 1 FROM public.builder_worker_runs WHERE job_id = _job.id AND status IN ('pending', 'queued', 'running')) THEN
    RAISE EXCEPTION 'Historical job still has active execution';
  END IF;
  UPDATE public.builder_jobs
  SET autopilot_state = 'done',
      autopilot_report = COALESCE(autopilot_report, '{}'::jsonb) || jsonb_build_object(
        'historical_resolution', jsonb_build_object(
          'outcome', 'resolved_historical_main_health', 'verification', _verification,
          'source_sha', _source_sha, 'failed_files', source_main_health_files, 'resolved_at', now()
        )
      ),
      autopilot_updated_at = now(), updated_at = now()
  WHERE id = _job.id RETURNING * INTO _updated;
  INSERT INTO public.builder_audit_events (
    organization_id, job_id, event_type, actor_type, previous_value, new_value, change_summary
  ) VALUES (
    _job.organization_id, _job.id, 'builder_job_policy_bound', 'bot',
    jsonb_build_object('status', _job.status, 'autopilot_state', _job.autopilot_state),
    jsonb_build_object('status', _updated.status, 'autopilot_state', 'done',
      'outcome', 'resolved_historical_main_health', 'verification', _verification),
    'A newer main passed every health step; historical failure/cancellation and release receipts were preserved'
  );
  RETURN _updated;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_resolve_historical_health_job"(_job_id uuid, _organization_id uuid, _project_id uuid, _main_sha text, _source_sha text, _verified_files text[], _verification jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_resolve_historical_health_job"(_job_id uuid, _organization_id uuid, _project_id uuid, _main_sha text, _source_sha text, _verified_files text[], _verification jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_resolve_historical_health_job"(_job_id uuid, _organization_id uuid, _project_id uuid, _main_sha text, _source_sha text, _verified_files text[], _verification jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_retire_stale_job"(_job_id uuid, _reason text, _outcome text, _details jsonb DEFAULT '{}'::jsonb)
 RETURNS builder_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _job public.builder_jobs%rowtype;
  _updated public.builder_jobs%rowtype;
  _trimmed_reason text := btrim(_reason);
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;
  IF _outcome NOT IN (
    'completed_autopilot',
    'superseded_main_health',
    'inactive_orphan',
    'owner_requested_cleanup'
  ) THEN
    RAISE EXCEPTION 'Unsupported Builder housekeeping outcome';
  END IF;
  IF NULLIF(_trimmed_reason, '') IS NULL OR char_length(_trimmed_reason) > 2000 THEN
    RAISE EXCEPTION 'Builder housekeeping reason must be 1 to 2000 characters';
  END IF;
  IF _details IS NULL OR jsonb_typeof(_details) <> 'object' THEN
    RAISE EXCEPTION 'Builder housekeeping details must be an object';
  END IF;

  SELECT * INTO _job
  FROM public.builder_jobs
  WHERE id = _job_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Builder job not found';
  END IF;
  IF _job.status IN ('deployed', 'failed', 'cancelled') THEN
    RETURN _job;
  END IF;
  IF _job.workspace_branch IS NOT NULL OR _job.workspace_pull_request_url IS NOT NULL THEN
    RAISE EXCEPTION 'Builder jobs with a workspace or pull request require explicit release handling';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.builder_model_runs
    WHERE job_id = _job.id AND status IN ('pending', 'running')
  ) OR EXISTS (
    SELECT 1 FROM public.builder_worker_runs
    WHERE job_id = _job.id AND status IN ('pending', 'running')
  ) THEN
    RAISE EXCEPTION 'Builder job still has active execution';
  END IF;
  IF _outcome = 'completed_autopilot' AND _job.autopilot_state IS DISTINCT FROM 'done' THEN
    RAISE EXCEPTION 'Builder job has not been recorded done';
  END IF;
  IF _outcome = 'superseded_main_health' AND _job.autopilot_source IS DISTINCT FROM 'main_monitor' THEN
    RAISE EXCEPTION 'Builder job is not a main-health repair';
  END IF;
  IF _outcome = 'inactive_orphan' AND (
    _job.autopilot_requested_by IS NOT NULL
    OR _job.autopilot_source IS NOT NULL
    OR _job.autopilot_state IS NOT NULL
    OR _job.updated_at > now() - interval '7 days'
    OR EXISTS (
      SELECT 1 FROM public.builder_approvals
      WHERE job_id = _job.id AND status = 'pending'
    )
  ) THEN
    RAISE EXCEPTION 'Builder job is not an inactive orphan';
  END IF;

  UPDATE public.builder_approvals
  SET status = 'cancelled',
      approval_comment = COALESCE(approval_comment, 'Cancelled because the Builder job was retired by audited housekeeping.'),
      responded_at = COALESCE(responded_at, now()),
      updated_at = now()
  WHERE job_id = _job.id
    AND status = 'pending';

  UPDATE public.builder_jobs
  SET status = 'cancelled',
      autopilot_state = CASE
        WHEN autopilot_requested_by IS NOT NULL OR autopilot_source IN ('main_monitor', 'routine_monitor') THEN 'done'
        ELSE autopilot_state
      END,
      autopilot_report = COALESCE(autopilot_report, '{}'::jsonb) || jsonb_build_object(
        'housekeeping',
        jsonb_build_object(
          'outcome', _outcome,
          'reason', _trimmed_reason,
          'details', _details,
          'retired_at', now()
        )
      ),
      last_error = 'Retired: ' || _trimmed_reason,
      updated_at = now()
  WHERE id = _job.id
  RETURNING * INTO _updated;

  INSERT INTO public.builder_audit_events (
    organization_id,
    job_id,
    event_type,
    actor_type,
    previous_value,
    new_value,
    change_summary
  ) VALUES (
    _job.organization_id,
    _job.id,
    'job_cancelled',
    'bot',
    jsonb_build_object('status', _job.status, 'autopilot_state', _job.autopilot_state),
    jsonb_build_object('status', 'cancelled', 'outcome', _outcome, 'details', _details),
    'Bob retired stale Builder work through the audited housekeeping policy: ' || _trimmed_reason
  );

  RETURN _updated;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_retire_stale_job"(_job_id uuid, _reason text, _outcome text, _details jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_retire_stale_job"(_job_id uuid, _reason text, _outcome text, _details jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_retire_stale_job"(_job_id uuid, _reason text, _outcome text, _details jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_retry_failed_frontend_patch"(p_job_id uuid, p_step_id uuid, p_patch_artifact_id uuid, p_target_sha text, p_job_updated_at timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := public.builder_chat_require_owner();
  v_job public.builder_jobs%rowtype;
  v_step public.builder_job_steps%rowtype;
  v_patch public.builder_artifacts%rowtype;
  v_run public.builder_worker_runs%rowtype;
  v_receipt uuid;
BEGIN
  IF p_job_id IS NULL OR p_step_id IS NULL OR p_patch_artifact_id IS NULL
    OR p_job_updated_at IS NULL OR p_target_sha IS NULL OR p_target_sha !~ '^[a-f0-9]{40}$' THEN
    RAISE EXCEPTION 'A pinned failed patch handoff is required';
  END IF;

  SELECT * INTO v_job FROM public.builder_jobs WHERE id = p_job_id FOR UPDATE;
  IF v_job.id IS NULL OR v_job.autopilot_requested_by IS DISTINCT FROM v_user
    OR public.can_approve_action(v_user, v_job.organization_id) IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'User is not authorized to hand off this Builder job';
  END IF;

  SELECT id INTO v_receipt FROM public.builder_audit_events
    WHERE job_id = p_job_id AND actor_user_id = v_user AND event_type = 'job_status_changed'
      AND new_value->>'handoff_kind' = 'saved_frontend_patch_retry'
      AND new_value->>'step_id' = p_step_id::text
      AND new_value->>'patch_artifact_id' = p_patch_artifact_id::text
      AND new_value->>'target_sha' = p_target_sha
      AND new_value->>'request_updated_at' = p_job_updated_at::text
    ORDER BY created_at DESC LIMIT 1;
  IF v_receipt IS NOT NULL THEN RETURN v_receipt; END IF;

  IF v_job.status IS DISTINCT FROM 'failed'
    OR v_job.updated_at IS DISTINCT FROM p_job_updated_at
    OR v_job.target_sha IS DISTINCT FROM p_target_sha
    OR v_job.code_review_mode IS DISTINCT FROM 'human'
    OR v_job.frontend_required IS DISTINCT FROM true
    OR v_job.workspace_published_at IS NOT NULL
    OR v_job.workspace_published_head_sha IS NOT NULL
    OR v_job.workspace_pull_request_url IS NOT NULL
    OR v_job.workspace_pull_request_head_sha IS NOT NULL THEN
    RAISE EXCEPTION 'Failed job changed, is published, or is not eligible; refresh before retrying';
  END IF;

  SELECT * INTO v_step FROM public.builder_job_steps
    WHERE id = p_step_id AND job_id = p_job_id FOR UPDATE;
  IF v_step.id IS NULL OR v_step.step_id <> 'frontend_implementation'
    OR v_step.builder_mode <> 'frontend_engineer'
    OR v_step.status <> 'failed' OR v_step.retryable IS DISTINCT FROM false
    OR v_step.error IS NULL
    OR v_step.error NOT LIKE 'Verifier recovery paused after two infrastructure or attribution failures; patch preserved;%'
    OR v_step.input_context->>'patch_artifact_id' IS DISTINCT FROM p_patch_artifact_id::text
    OR v_step.input_context->>'target_sha' IS DISTINCT FROM p_target_sha
    OR (SELECT count(*) FROM public.builder_job_steps WHERE job_id = p_job_id AND status = 'failed') <> 1
    OR EXISTS (SELECT 1 FROM public.builder_job_steps WHERE job_id = p_job_id AND status = 'running')
    OR EXISTS (SELECT 1 FROM public.builder_job_steps WHERE job_id = p_job_id
      AND step_id IN ('test_suite', 'security_review', 'code_review', 'release_prep')
      AND (status <> 'pending' OR started_at IS NOT NULL OR completed_at IS NOT NULL))
    OR (SELECT count(*) FROM public.builder_job_steps WHERE job_id = p_job_id
      AND step_id IN ('test_suite', 'security_review', 'code_review', 'release_prep')) <> 4
    OR NOT EXISTS (SELECT 1 FROM public.builder_job_steps WHERE job_id = p_job_id
      AND step_id = 'product_analysis' AND status = 'completed')
    OR NOT EXISTS (SELECT 1 FROM public.builder_job_steps WHERE job_id = p_job_id
      AND step_id = 'ui_design' AND status = 'completed')
    OR (v_job.backend_required AND (SELECT count(*) FROM public.builder_job_steps
      WHERE job_id = p_job_id AND step_id = 'backend_implementation') <> 1)
    OR EXISTS (SELECT 1 FROM public.builder_job_steps WHERE job_id = p_job_id
      AND step_id = 'backend_implementation'
      AND ((v_job.backend_required AND (status <> 'pending' OR started_at IS NOT NULL OR completed_at IS NOT NULL))
        OR (NOT v_job.backend_required AND NOT (
          (status = 'pending' AND started_at IS NULL AND completed_at IS NULL)
          OR (status = 'skipped' AND started_at IS NULL))))) THEN
    RAISE EXCEPTION 'Saved-patch retry requires one paused frontend verifier and untouched downstream gates';
  END IF;

  IF EXISTS (SELECT 1 FROM public.builder_worker_runs WHERE job_id = p_job_id AND status IN ('pending', 'running'))
    OR EXISTS (SELECT 1 FROM public.builder_model_runs WHERE job_id = p_job_id AND status IN ('pending', 'running'))
    OR EXISTS (SELECT 1 FROM public.builder_approvals WHERE job_id = p_job_id AND status = 'pending') THEN
    RAISE EXCEPTION 'An active worker, model run, or approval prevents the saved-patch retry';
  END IF;

  SELECT * INTO v_patch FROM public.builder_artifacts
    WHERE id = p_patch_artifact_id AND job_id = p_job_id AND step_id = p_step_id
      AND artifact_type = 'code_implementation' AND status = 'final' FOR UPDATE;
  IF v_patch.id IS NULL OR v_patch.checksum IS NULL OR v_patch.checksum !~ '^[a-f0-9]{64}$' THEN
    RAISE EXCEPTION 'The exact final saved patch is unavailable';
  END IF;

  SELECT * INTO v_run FROM public.builder_worker_runs
    WHERE job_id = p_job_id AND step_id = p_step_id
    ORDER BY created_at DESC LIMIT 1;
  IF v_run.id IS NULL OR v_run.status NOT IN ('failed', 'timeout') OR v_run.profile <> 'frontend-verify'
    OR v_run.patch_artifact_id IS DISTINCT FROM v_patch.id
    OR v_run.target_sha IS DISTINCT FROM p_target_sha
    OR (v_run.status = 'failed' AND (v_run.exit_code IS NULL OR v_run.exit_code = 0))
    OR (v_run.status = 'timeout' AND v_run.exit_code = 0) THEN
    RAISE EXCEPTION 'The latest frontend verifier did not fail against this saved patch and target';
  END IF;

  v_receipt := gen_random_uuid();
  UPDATE public.builder_job_steps SET
    retryable = true,
    error = 'Verifier recovery pending: owner-confirmed saved patch verification',
    input_context = coalesce(input_context, '{}'::jsonb) || jsonb_build_object(
      'patch_artifact_id', v_patch.id, 'target_sha', v_job.target_sha,
      'owner_patch_retry_receipt', v_receipt, 'owner_patch_retry_actor', v_user,
      'owner_patch_retry_at', now(), 'owner_patch_retry_attempt_count', v_step.attempt_count
    ),
    updated_at = now()
    WHERE id = v_step.id;

  UPDATE public.builder_jobs SET status = 'implementation_pending', last_error = NULL,
    current_step_name = NULL, current_step_index = 2,
    autopilot_state = CASE WHEN autopilot_requested_by IS NOT NULL THEN 'driving' ELSE autopilot_state END,
    updated_at = now()
    WHERE id = v_job.id;

  INSERT INTO public.builder_audit_events (
    id, organization_id, job_id, event_type, actor_user_id, actor_type,
    previous_value, new_value, change_summary, related_artifact_ids
  ) VALUES (
    v_receipt, v_job.organization_id, v_job.id, 'job_status_changed', v_user, 'user',
    jsonb_build_object('status', v_job.status, 'step_id', v_step.id, 'step_error', v_step.error,
      'attempt_count', v_step.attempt_count, 'target_sha', v_job.target_sha),
    jsonb_build_object('status', 'implementation_pending', 'handoff_kind', 'saved_frontend_patch_retry',
      'step_id', v_step.id, 'patch_artifact_id', v_patch.id, 'patch_checksum', v_patch.checksum,
      'target_sha', v_job.target_sha, 'request_updated_at', p_job_updated_at::text,
      'attempt_count', v_step.attempt_count, 'owner_user_id', v_user),
    'Owner confirmed same-job verification of the preserved frontend patch; no approval or publication',
    ARRAY[v_patch.id]
  );
  RETURN v_receipt;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_retry_failed_frontend_patch"(p_job_id uuid, p_step_id uuid, p_patch_artifact_id uuid, p_target_sha text, p_job_updated_at timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_retry_failed_frontend_patch"(p_job_id uuid, p_step_id uuid, p_patch_artifact_id uuid, p_target_sha text, p_job_updated_at timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_retry_failed_frontend_patch"(p_job_id uuid, p_step_id uuid, p_patch_artifact_id uuid, p_target_sha text, p_job_updated_at timestamp with time zone) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."builder_set_code_review_policy"(_job_id uuid, _mode text)
 RETURNS builder_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _job public.builder_jobs%rowtype;
BEGIN
  IF auth.role() <> 'authenticated' OR _uid IS NULL THEN RAISE EXCEPTION 'Authenticated human identity required'; END IF;
  IF _mode NOT IN ('none', 'human', 'independent_ai') THEN RAISE EXCEPTION 'Unsupported code review mode'; END IF;
  SELECT * INTO _job FROM public.builder_jobs WHERE id = _job_id FOR UPDATE;
  IF _job.id IS NULL OR _job.status <> 'intake' THEN RAISE EXCEPTION 'Code review policy can only be set during intake'; END IF;
  IF NOT public.can_approve_action(_uid, _job.organization_id) THEN RAISE EXCEPTION 'User cannot configure this job'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.builder_job_steps WHERE job_id = _job.id AND step_id = 'code_review' AND builder_mode = 'code_reviewer') THEN
    RAISE EXCEPTION 'Code review step is missing';
  END IF;
  UPDATE public.builder_jobs SET code_review_mode = _mode,
    code_review_status = CASE WHEN _mode = 'none' THEN 'not_required' ELSE 'pending' END, updated_at = now()
  WHERE id = _job.id RETURNING * INTO _job;
  UPDATE public.builder_job_steps SET status = CASE WHEN _mode = 'none' THEN 'skipped' ELSE 'pending' END, updated_at = now()
  WHERE job_id = _job.id AND step_id = 'code_review';
  INSERT INTO public.builder_audit_events (organization_id, job_id, event_type, actor_user_id, actor_type, new_value, change_summary)
  VALUES (_job.organization_id, _job.id, 'job_status_changed', _uid, 'user',
    jsonb_build_object('code_review_mode', _mode), 'Optional code review policy configured');
  RETURN _job;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_set_code_review_policy"(_job_id uuid, _mode text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_set_code_review_policy"(_job_id uuid, _mode text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_set_code_review_policy"(_job_id uuid, _mode text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."builder_skip_implementation_step"(_job_id uuid, _step_id uuid, _builder_mode text, _reason text)
 RETURNS builder_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _job public.builder_jobs%rowtype; _step public.builder_job_steps%rowtype; _sibling_mode text; _next_status text;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  IF _builder_mode NOT IN ('frontend_engineer', 'backend_engineer') THEN RAISE EXCEPTION 'Unsupported implementation mode'; END IF;
  IF NULLIF(btrim(_reason), '') IS NULL THEN RAISE EXCEPTION 'A skip reason is required'; END IF;
  SELECT * INTO _job FROM public.builder_jobs WHERE id = _job_id FOR UPDATE;
  SELECT * INTO _step FROM public.builder_job_steps WHERE id = _step_id AND job_id = _job_id FOR UPDATE;
  IF _job.id IS NULL OR _job.status <> 'implementation_pending' THEN RAISE EXCEPTION 'Job is not ready for an implementation skip'; END IF;
  IF _step.id IS NULL OR _step.builder_mode <> _builder_mode OR _step.status NOT IN ('pending', 'blocked') THEN RAISE EXCEPTION 'Implementation step cannot be skipped'; END IF;
  IF jsonb_typeof(_job.code_review_revision->'reopened_required_lanes') = 'array'
    AND _job.code_review_revision->'reopened_required_lanes' ? _step.step_id THEN
    RAISE EXCEPTION 'A required lane reopened by the confirmed correction cannot be skipped';
  END IF;
  _sibling_mode := CASE WHEN _builder_mode = 'frontend_engineer' THEN 'backend_engineer' ELSE 'frontend_engineer' END;
  IF _reason LIKE 'Nothing to change in this lane; author evidence says%' AND NOT EXISTS (
    SELECT 1 FROM public.builder_job_steps WHERE job_id = _job_id
      AND builder_mode = _sibling_mode AND status IN ('pending', 'completed')
  ) THEN RAISE EXCEPTION 'Destination implementation lane is unavailable; explicit scope authorization is required'; END IF;
  _next_status := CASE
    WHEN EXISTS (SELECT 1 FROM public.builder_job_steps WHERE job_id = _job_id AND builder_mode = _sibling_mode AND status IN ('completed', 'skipped')) THEN 'testing'
    ELSE 'implementation_pending'
  END;
  UPDATE public.builder_job_steps SET status = 'skipped', completed_at = now(), retryable = false,
    result_summary = left(btrim(_reason), 1000), error = NULL, updated_at = now() WHERE id = _step.id;
  UPDATE public.builder_jobs SET status = _next_status, current_step_name = _step.step_id,
    current_step_index = _step.ordinal_position, updated_at = now() WHERE id = _job.id RETURNING * INTO _job;
  INSERT INTO public.builder_audit_events (organization_id, job_id, event_type, actor_type, previous_value, new_value, change_summary)
  VALUES (_job.organization_id, _job.id, 'step_completed', 'builder_mode',
    jsonb_build_object('job_status', 'implementation_pending', 'step_status', _step.status),
    jsonb_build_object('job_status', _next_status, 'step_status', 'skipped', 'builder_mode', _builder_mode),
    left('Implementation step skipped: ' || btrim(_reason), 1000));
  RETURN _job;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_skip_implementation_step"(_job_id uuid, _step_id uuid, _builder_mode text, _reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_skip_implementation_step"(_job_id uuid, _step_id uuid, _builder_mode text, _reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_skip_implementation_step"(_job_id uuid, _step_id uuid, _builder_mode text, _reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_start_code_review"(_job_id uuid, _step_id uuid, _reviewed_artifact_ids uuid[], _requested_from_users uuid[] DEFAULT '{}'::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _job public.builder_jobs%rowtype; _step public.builder_job_steps%rowtype; _approval public.builder_approvals%rowtype;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  SELECT * INTO _job FROM public.builder_jobs WHERE id = _job_id FOR UPDATE;
  SELECT * INTO _step FROM public.builder_job_steps WHERE id = _step_id AND job_id = _job_id FOR UPDATE;
  IF _job.id IS NULL OR _job.status <> 'security_review' THEN RAISE EXCEPTION 'Job is not ready for optional code review'; END IF;
  IF _step.id IS NULL OR _step.step_id <> 'code_review' OR _step.builder_mode <> 'code_reviewer' THEN RAISE EXCEPTION 'Code review step is missing'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.builder_job_steps WHERE job_id = _job.id AND step_id = 'security_review' AND status = 'completed') THEN
    RAISE EXCEPTION 'Independent security review must complete first';
  END IF;
  IF _job.code_review_mode = 'none' THEN
    UPDATE public.builder_job_steps SET status = 'skipped', completed_at = now(), result_summary = 'Optional code review not requested', updated_at = now() WHERE id = _step.id;
    UPDATE public.builder_jobs SET code_review_status = 'not_required', updated_at = now() WHERE id = _job.id;
    INSERT INTO public.builder_audit_events (organization_id, job_id, event_type, actor_type, new_value, change_summary)
    VALUES (_job.organization_id, _job.id, 'step_completed', 'builder_mode',
      jsonb_build_object('step_id', 'code_review', 'status', 'skipped', 'target_sha', _job.target_sha),
      'Optional code review skipped by configured policy');
    RETURN jsonb_build_object('mode', 'none', 'status', 'skipped');
  END IF;

  IF _step.status <> 'pending' THEN RAISE EXCEPTION 'Code review step is not pending'; END IF;
  IF EXISTS (
    SELECT 1 FROM unnest(ARRAY['code_implementation','changed_file_manifest','build_logs','security_review']) required_type
    WHERE NOT EXISTS (
      SELECT 1 FROM public.builder_artifacts artifact
      WHERE artifact.job_id = _job.id AND artifact.id = ANY(_reviewed_artifact_ids)
        AND artifact.artifact_type = required_type AND artifact.status = 'final'
    )
  ) OR (
    SELECT count(*) FROM public.builder_artifacts WHERE job_id = _job.id AND id = ANY(_reviewed_artifact_ids) AND status = 'final'
  ) <> cardinality(_reviewed_artifact_ids) THEN RAISE EXCEPTION 'Code review evidence snapshot is incomplete'; END IF;

  IF _job.code_review_mode = 'human' THEN
    UPDATE public.builder_job_steps SET status = 'blocked', blocked_reason = 'Waiting for human code review', input_context = jsonb_build_object('reviewed_artifact_ids', _reviewed_artifact_ids), updated_at = now() WHERE id = _step.id;
    INSERT INTO public.builder_approvals (organization_id, job_id, approval_type, triggered_at_status, status,
      requested_from_users, requested_target_sha, reviewed_artifact_ids)
    VALUES (_job.organization_id, _job.id, 'implementation_review', 'security_review', 'pending',
      COALESCE(_requested_from_users, '{}'), _job.target_sha, _reviewed_artifact_ids)
    RETURNING * INTO _approval;
    UPDATE public.builder_jobs SET code_review_status = 'pending', updated_at = now() WHERE id = _job.id;
    INSERT INTO public.builder_audit_events (organization_id, job_id, event_type, actor_type, new_value, change_summary, related_artifact_ids, related_approval_id)
    VALUES (_job.organization_id, _job.id, 'approval_requested', 'bot', jsonb_build_object('approval_type', 'implementation_review', 'target_sha', _job.target_sha),
      'Optional human code review requested', _reviewed_artifact_ids, _approval.id);
    RETURN jsonb_build_object('mode', 'human', 'status', 'pending', 'approval_id', _approval.id);
  ELSIF _job.code_review_mode = 'independent_ai' THEN
    UPDATE public.builder_job_steps SET status = 'running', attempt_count = attempt_count + 1, started_at = now(),
      input_context = jsonb_build_object('reviewed_artifact_ids', _reviewed_artifact_ids, 'target_sha', _job.target_sha), updated_at = now()
    WHERE id = _step.id;
    UPDATE public.builder_jobs SET code_review_status = 'pending', updated_at = now() WHERE id = _job.id;
    INSERT INTO public.builder_audit_events (organization_id, job_id, event_type, actor_type, new_value, change_summary, related_artifact_ids)
    VALUES (_job.organization_id, _job.id, 'step_started', 'builder_mode',
      jsonb_build_object('step_id', 'code_review', 'mode', 'independent_ai', 'target_sha', _job.target_sha),
      'Independent AI code review started', _reviewed_artifact_ids);
    RETURN jsonb_build_object('mode', 'independent_ai', 'status', 'running');
  END IF;
  RAISE EXCEPTION 'Unsupported code review policy state';
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_start_code_review"(_job_id uuid, _step_id uuid, _reviewed_artifact_ids uuid[], _requested_from_users uuid[]) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_start_code_review"(_job_id uuid, _step_id uuid, _reviewed_artifact_ids uuid[], _requested_from_users uuid[]) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_start_code_review"(_job_id uuid, _step_id uuid, _reviewed_artifact_ids uuid[], _requested_from_users uuid[]) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_start_product_analysis"(_job_id uuid, _step_id uuid)
 RETURNS builder_job_steps
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _job public.builder_jobs%rowtype;
  _step public.builder_job_steps%rowtype;
  _previous_step_status text;
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;

  SELECT * INTO _job FROM public.builder_jobs WHERE id = _job_id FOR UPDATE;
  SELECT * INTO _step FROM public.builder_job_steps WHERE id = _step_id AND job_id = _job_id FOR UPDATE;

  IF _job.id IS NULL OR _job.status NOT IN ('intake', 'analysis_pending') THEN
    RAISE EXCEPTION 'Job is not ready for product analysis';
  END IF;
  IF _step.id IS NULL OR _step.builder_mode <> 'product_analyst' THEN
    RAISE EXCEPTION 'Product Analyst step is missing';
  END IF;
  IF _step.status <> 'pending' AND NOT (_step.status = 'failed' AND _step.retryable) THEN
    RAISE EXCEPTION 'Product Analyst step cannot be started';
  END IF;

  _previous_step_status := _step.status;
  UPDATE public.builder_job_steps
  SET status = 'running',
      attempt_count = attempt_count + 1,
      started_at = now(),
      completed_at = NULL,
      error = NULL,
      retryable = false,
      updated_at = now()
  WHERE id = _step.id
  RETURNING * INTO _step;

  UPDATE public.builder_jobs
  SET status = 'analysis_pending',
      current_step_name = _step.step_id,
      current_step_index = _step.ordinal_position,
      last_error = NULL,
      updated_at = now()
  WHERE id = _job.id;

  INSERT INTO public.builder_audit_events (
    organization_id, job_id, event_type, actor_type,
    previous_value, new_value, change_summary
  ) VALUES (
    _job.organization_id, _job.id, 'step_started', 'builder_mode',
    jsonb_build_object('job_status', _job.status, 'step_status', _previous_step_status),
    jsonb_build_object('job_status', 'analysis_pending', 'step_status', 'running', 'step_id', _step.step_id),
    'Product Analyst step started'
  );

  RETURN _step;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_start_product_analysis"(_job_id uuid, _step_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_start_product_analysis"(_job_id uuid, _step_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_start_product_analysis"(_job_id uuid, _step_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_start_release_preparation"(_job_id uuid, _step_id uuid, _security_worker_run_id uuid)
 RETURNS builder_job_steps
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _job public.builder_jobs%rowtype;
  _step public.builder_job_steps%rowtype;
  _security_run public.builder_worker_runs%rowtype;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  SELECT * INTO _job FROM public.builder_jobs WHERE id = _job_id FOR UPDATE;
  SELECT * INTO _step FROM public.builder_job_steps WHERE id = _step_id AND job_id = _job_id FOR UPDATE;
  SELECT * INTO _security_run FROM public.builder_worker_runs
  WHERE id = _security_worker_run_id AND job_id = _job_id AND profile = 'security-review';
  IF _job.id IS NULL OR _job.status <> 'security_review' THEN RAISE EXCEPTION 'Job is not ready for release preparation'; END IF;
    IF _step.id IS NULL OR _step.step_id <> 'release_prep' OR _step.builder_mode <> 'release_engineer'
      OR (_step.status <> 'pending' AND NOT (_step.status = 'failed' AND _step.retryable)) THEN
    RAISE EXCEPTION 'Release Engineer step is not pending';
  END IF;
  IF _security_run.id IS NULL OR _security_run.status <> 'completed'
     OR _security_run.organization_id IS DISTINCT FROM _job.organization_id
     OR _security_run.target_sha IS DISTINCT FROM _job.target_sha
     OR _security_run.review_summary->>'passed' <> 'true'
     OR COALESCE((_security_run.review_summary->>'critical')::integer, 0) <> 0
     OR COALESCE((_security_run.review_summary->>'high')::integer, 0) <> 0 THEN
    RAISE EXCEPTION 'A clean independent security review is required';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.builder_job_steps
    WHERE job_id = _job.id AND step_id = 'security_review' AND status = 'completed'
      AND artifact_ids && _security_run.output_artifact_ids
  ) THEN RAISE EXCEPTION 'Security review step evidence is incomplete'; END IF;

  UPDATE public.builder_job_steps
  SET status = 'running', attempt_count = attempt_count + 1, started_at = now(), retryable = false,
      input_context = jsonb_build_object('security_worker_run_id', _security_run.id,
        'security_artifact_ids', _security_run.output_artifact_ids, 'target_sha', _job.target_sha), updated_at = now()
  WHERE id = _step.id RETURNING * INTO _step;
  UPDATE public.builder_jobs SET current_step_name = _step.step_id, current_step_index = _step.ordinal_position, updated_at = now()
  WHERE id = _job.id;
  INSERT INTO public.builder_audit_events (organization_id, job_id, event_type, actor_type, new_value, change_summary, related_artifact_ids)
  VALUES (_job.organization_id, _job.id, 'step_started', 'builder_mode',
    jsonb_build_object('step_id', _step.step_id, 'target_sha', _job.target_sha, 'security_worker_run_id', _security_run.id),
    'Release preparation started from clean security evidence', _security_run.output_artifact_ids);
  RETURN _step;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_start_release_preparation"(_job_id uuid, _step_id uuid, _security_worker_run_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_start_release_preparation"(_job_id uuid, _step_id uuid, _security_worker_run_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_start_release_preparation"(_job_id uuid, _step_id uuid, _security_worker_run_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_start_ux_design"(_job_id uuid, _step_id uuid, _specification_artifact_id uuid)
 RETURNS builder_job_steps
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _job public.builder_jobs%rowtype;
  _step public.builder_job_steps%rowtype;
  _specification public.builder_artifacts%rowtype;
  _previous_step_status text;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  SELECT * INTO _job FROM public.builder_jobs WHERE id = _job_id FOR UPDATE;
  SELECT * INTO _step FROM public.builder_job_steps WHERE id = _step_id AND job_id = _job_id FOR UPDATE;
  SELECT * INTO _specification FROM public.builder_artifacts WHERE id = _specification_artifact_id AND job_id = _job_id;

  IF _job.id IS NULL OR _job.status <> 'design_pending' THEN RAISE EXCEPTION 'Job is not ready for UX design'; END IF;
  IF _step.id IS NULL OR _step.builder_mode <> 'ux_designer' THEN RAISE EXCEPTION 'UX Designer step is missing'; END IF;
  IF _step.status <> 'pending' AND NOT (_step.status = 'failed' AND _step.retryable) THEN RAISE EXCEPTION 'UX Designer step cannot be started'; END IF;
  IF _specification.id IS NULL OR _specification.artifact_type <> 'product_specification' OR _specification.status <> 'final' THEN
    RAISE EXCEPTION 'Final product specification artifact is required';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.builder_approvals
    WHERE job_id = _job.id AND approval_type = 'specification_review' AND status = 'approved'
      AND _specification.id = ANY(reviewed_artifact_ids)
  ) THEN RAISE EXCEPTION 'Product specification has not been approved'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.builder_job_steps
    WHERE job_id = _job.id AND builder_mode = 'product_analyst' AND status = 'completed'
      AND _specification.id = ANY(COALESCE(artifact_ids, '{}'))
  ) THEN RAISE EXCEPTION 'Product analysis dependency is incomplete'; END IF;

  _previous_step_status := _step.status;
  UPDATE public.builder_job_steps
  SET status='running', attempt_count=attempt_count+1, started_at=now(), completed_at=NULL,
      error=NULL, retryable=false, input_context=jsonb_build_object('specification_artifact_id', _specification.id), updated_at=now()
  WHERE id=_step.id RETURNING * INTO _step;
  UPDATE public.builder_jobs SET current_step_name=_step.step_id, current_step_index=_step.ordinal_position, updated_at=now() WHERE id=_job.id;
  INSERT INTO public.builder_audit_events (organization_id,job_id,event_type,actor_type,previous_value,new_value,change_summary,related_artifact_ids)
  VALUES (_job.organization_id,_job.id,'step_started','builder_mode',jsonb_build_object('job_status',_job.status,'step_status',_previous_step_status),jsonb_build_object('job_status','design_pending','step_status','running','step_id',_step.step_id),'UX Designer step started from approved specification',ARRAY[_specification.id]);
  RETURN _step;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_start_ux_design"(_job_id uuid, _step_id uuid, _specification_artifact_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_start_ux_design"(_job_id uuid, _step_id uuid, _specification_artifact_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_start_ux_design"(_job_id uuid, _step_id uuid, _specification_artifact_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_vibe_attachment_delete"(p_session_id uuid, p_attachment_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := public.builder_vibe_require_owner();
BEGIN
  DELETE FROM public.builder_vibe_attachments a
   USING public.builder_vibe_sessions s
   WHERE a.id = p_attachment_id
     AND a.session_id = p_session_id
     AND s.id = a.session_id
     AND s.created_by = v_user
     AND s.status <> 'closed';
  IF NOT FOUND THEN RAISE EXCEPTION 'Attachment not found for this open Vibe session'; END IF;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_vibe_attachment_delete"(p_session_id uuid, p_attachment_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_vibe_attachment_delete"(p_session_id uuid, p_attachment_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_vibe_attachment_delete"(p_session_id uuid, p_attachment_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."builder_vibe_attachment_delete"(p_session_id uuid, p_attachment_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_vibe_attachment_register"(p_session_id uuid, p_attachment_id uuid, p_file_name text, p_file_type text, p_file_size_bytes bigint, p_storage_path text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := public.builder_vibe_require_owner();
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.builder_vibe_sessions
    WHERE id = p_session_id AND created_by = v_user AND status <> 'closed'
  ) THEN
    RAISE EXCEPTION 'Vibe session not found or closed';
  END IF;
  IF p_file_name IS NULL OR char_length(p_file_name) NOT BETWEEN 1 AND 255 THEN
    RAISE EXCEPTION 'Attachment filename is invalid';
  END IF;
  IF p_file_type NOT IN (
    'image/jpeg',
    'image/png',
    'image/webp',
    'application/pdf',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    'text/plain',
    'text/csv',
    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
  ) THEN
    RAISE EXCEPTION 'Attachment type is not supported';
  END IF;
  IF p_file_size_bytes IS NULL OR p_file_size_bytes <= 0 OR p_file_size_bytes > 20971520 THEN
    RAISE EXCEPTION 'Attachment exceeds the 20 MB Vibe limit';
  END IF;
  IF p_file_type LIKE 'image/%' AND p_file_size_bytes > 10485760 THEN
    RAISE EXCEPTION 'Vibe images must not exceed 10 MB';
  END IF;
  IF p_storage_path !~ (
    '^desktop/' || v_user::text || '/vibe/' || p_session_id::text || '/'
    || p_attachment_id::text || '-[A-Za-z0-9._-]{1,180}$'
  ) THEN
    RAISE EXCEPTION 'Attachment is outside this Vibe session storage path';
  END IF;
  INSERT INTO public.builder_vibe_attachments (
    id, session_id, uploaded_by, file_name, file_type, file_size_bytes,
    storage_bucket, storage_path, extraction_status
  ) VALUES (
    p_attachment_id, p_session_id, v_user, p_file_name, p_file_type, p_file_size_bytes,
    'bob-uploads', p_storage_path,
    CASE WHEN p_file_type LIKE 'image/%' THEN 'not_applicable' ELSE 'pending' END
  );
  RETURN p_attachment_id;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_vibe_attachment_register"(p_session_id uuid, p_attachment_id uuid, p_file_name text, p_file_type text, p_file_size_bytes bigint, p_storage_path text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_vibe_attachment_register"(p_session_id uuid, p_attachment_id uuid, p_file_name text, p_file_type text, p_file_size_bytes bigint, p_storage_path text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_vibe_attachment_register"(p_session_id uuid, p_attachment_id uuid, p_file_name text, p_file_type text, p_file_size_bytes bigint, p_storage_path text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."builder_vibe_attachment_register"(p_session_id uuid, p_attachment_id uuid, p_file_name text, p_file_type text, p_file_size_bytes bigint, p_storage_path text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_vibe_attachment_set_extraction"(p_session_id uuid, p_attachment_id uuid, p_extracted_text text, p_sha256 text, p_extraction_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := public.builder_vibe_require_owner();
BEGIN
  IF p_extraction_status NOT IN ('extracted', 'empty', 'failed')
     OR char_length(coalesce(p_extracted_text, '')) > 200000
     OR (p_sha256 IS NOT NULL AND p_sha256 !~ '^[0-9a-f]{64}$') THEN
    RAISE EXCEPTION 'Attachment extraction result is invalid';
  END IF;
  UPDATE public.builder_vibe_attachments a
     SET extracted_text = coalesce(p_extracted_text, ''),
         sha256 = p_sha256,
         extraction_status = p_extraction_status
    FROM public.builder_vibe_sessions s
   WHERE a.id = p_attachment_id
     AND a.session_id = p_session_id
     AND a.file_type NOT LIKE 'image/%'
     AND a.session_id = s.id
     AND s.created_by = v_user
     AND s.status <> 'closed';
  IF NOT FOUND THEN RAISE EXCEPTION 'Document attachment not found for this open Vibe session'; END IF;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_vibe_attachment_set_extraction"(p_session_id uuid, p_attachment_id uuid, p_extracted_text text, p_sha256 text, p_extraction_status text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_vibe_attachment_set_extraction"(p_session_id uuid, p_attachment_id uuid, p_extracted_text text, p_sha256 text, p_extraction_status text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_vibe_attachment_set_extraction"(p_session_id uuid, p_attachment_id uuid, p_extracted_text text, p_sha256 text, p_extraction_status text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."builder_vibe_attachment_set_extraction"(p_session_id uuid, p_attachment_id uuid, p_extracted_text text, p_sha256 text, p_extraction_status text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_vibe_claim_next"()
 RETURNS SETOF builder_vibe_messages
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  UPDATE public.builder_vibe_messages m
     SET status = 'claimed', claimed_at = now()
   WHERE m.id = (
     SELECT q.id FROM public.builder_vibe_messages q
       JOIN public.builder_vibe_sessions s ON s.id = q.session_id
      WHERE q.status = 'queued' AND s.status IN ('open', 'shipped', 'failed')
        AND NOT EXISTS (SELECT 1 FROM public.builder_vibe_messages c WHERE c.session_id = q.session_id AND c.status = 'claimed')
      ORDER BY q.created_at
      LIMIT 1
      FOR UPDATE OF q SKIP LOCKED)
  RETURNING m.*;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_vibe_claim_next"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_vibe_claim_next"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_vibe_claim_next"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_vibe_preview_ticket"(p_session_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := public.builder_vibe_require_owner();
  v_ticket text := replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.builder_vibe_sessions WHERE id = p_session_id AND status <> 'closed') THEN
    RAISE EXCEPTION 'Vibe session not found or closed';
  END IF;
  DELETE FROM public.builder_vibe_preview_tickets WHERE expires_at < now() - interval '1 hour';
  INSERT INTO public.builder_vibe_preview_tickets (session_id, ticket_hash, created_by, expires_at)
  VALUES (p_session_id, encode(sha256(convert_to(v_ticket, 'UTF8')), 'hex'), v_user, now() + interval '5 minutes');
  RETURN v_ticket;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_vibe_preview_ticket"(p_session_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_vibe_preview_ticket"(p_session_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_vibe_preview_ticket"(p_session_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."builder_vibe_preview_ticket"(p_session_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_vibe_recover_failed_turn"(p_session_id uuid, p_message_id uuid, p_expected_head text, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_session public.builder_vibe_sessions%ROWTYPE;
  v_message public.builder_vibe_messages%ROWTYPE;
  v_error text;
  v_retries integer;
  v_committed boolean;
BEGIN
  IF p_session_id IS NULL OR p_message_id IS NULL OR p_request_id IS NULL
     OR p_expected_head IS NULL OR p_expected_head !~ '^[0-9a-f]{40}$' THEN
    RAISE EXCEPTION 'A session, owner message, full branch head and request id are required';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_request_id::text, 0));
  SELECT * INTO v_session FROM public.builder_vibe_sessions WHERE id = p_session_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Vibe session not found'; END IF;
  SELECT * INTO v_message FROM public.builder_vibe_messages
   WHERE id = p_message_id AND session_id = p_session_id FOR UPDATE;
  IF NOT FOUND OR v_message.role <> 'owner' OR v_message.kind <> 'message'
     OR coalesce(v_message.payload->>'action', 'message') <> 'message' THEN
    RAISE EXCEPTION 'Vibe coding turn not found';
  END IF;

  IF v_message.payload->>'governed_recovery_request_id' = p_request_id::text THEN
    IF v_message.payload->>'governed_recovery_expected_head' IS DISTINCT FROM p_expected_head THEN
      RAISE EXCEPTION 'Recovery request was already used with a different branch head';
    END IF;
    RETURN jsonb_build_object('result', 'already_scheduled', 'message_status', v_message.status);
  END IF;
  IF v_message.payload ? 'governed_recovery_request_id'
     OR EXISTS (
       SELECT 1 FROM public.builder_vibe_messages
        WHERE role = 'system' AND payload->>'reason' = 'governed_turn_recovery'
          AND payload->>'request_id' = p_request_id::text
     ) THEN
    RAISE EXCEPTION 'This turn or request id has already been used for recovery';
  END IF;
  IF v_session.status <> 'open' OR v_session.pr_url IS NOT NULL
     OR v_session.head_sha IS DISTINCT FROM p_expected_head THEN
    RAISE EXCEPTION 'Vibe session is closed, busy, published or no longer at the expected branch head';
  END IF;
  IF v_message.status IS DISTINCT FROM 'failed' OR v_message.completed_at IS NULL THEN
    RAISE EXCEPTION 'Only a completed failed turn can be recovered';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.builder_vibe_messages
     WHERE session_id = p_session_id AND role = 'owner' AND id <> p_message_id
       AND (seq > v_message.seq OR status IN ('queued', 'claimed'))
  ) THEN
    RAISE EXCEPTION 'A newer or pending owner instruction prevents recovery';
  END IF;

  SELECT content INTO v_error FROM public.builder_vibe_messages
   WHERE session_id = p_session_id AND role = 'bob' AND kind = 'error' AND seq > v_message.seq
   ORDER BY seq DESC LIMIT 1;
  IF NOT FOUND OR NOT (
    v_error LIKE 'Changes are not verified:%'
    OR v_error LIKE 'The automatic continuation %'
    OR v_error LIKE 'The execution budget %'
  ) THEN
    RAISE EXCEPTION 'The latest turn has no recoverable verification or budget failure';
  END IF;
  IF v_message.payload ? 'restart_retries'
     AND coalesce(v_message.payload->>'restart_retries', '') !~ '^[01]$' THEN
    RAISE EXCEPTION 'The turn restart count is invalid or exhausted';
  END IF;
  v_retries := coalesce((v_message.payload->>'restart_retries')::integer, 0) + 1;
  SELECT EXISTS (
    SELECT 1 FROM public.builder_vibe_messages
     WHERE session_id = p_session_id AND seq > v_message.seq AND role = 'bob' AND kind = 'diff'
       AND payload->>'commit' = p_expected_head
  ) INTO v_committed;

  UPDATE public.builder_vibe_messages
     SET status = 'queued', claimed_at = NULL, completed_at = NULL,
         payload = payload || jsonb_build_object(
           'restart_retries', v_retries,
           'governed_recovery_request_id', p_request_id::text,
           'governed_recovery_expected_head', p_expected_head,
           'governed_recovery_committed_edits', v_committed
         )
   WHERE id = p_message_id;
  INSERT INTO public.builder_vibe_messages (session_id, role, kind, content, payload)
  VALUES (
    p_session_id, 'system', 'status',
    'A governed recovery queued this original failed coding turn again on its existing branch. No new owner message was created; verification and approval gates remain in place.',
    jsonb_build_object(
      'reason', 'governed_turn_recovery', 'message_id', p_message_id,
      'request_id', p_request_id, 'expected_head', p_expected_head,
      'credential_class', 'service_operator'
    )
  );
  RETURN jsonb_build_object('result', 'scheduled', 'message_status', 'queued');
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_vibe_recover_failed_turn"(p_session_id uuid, p_message_id uuid, p_expected_head text, p_request_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_vibe_recover_failed_turn"(p_session_id uuid, p_message_id uuid, p_expected_head text, p_request_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_vibe_recover_failed_turn"(p_session_id uuid, p_message_id uuid, p_expected_head text, p_request_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_vibe_redeem_preview_ticket"(p_session_id uuid, p_ticket text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid;
BEGIN
  UPDATE public.builder_vibe_preview_tickets
     SET used_at = now()
   WHERE session_id = p_session_id AND used_at IS NULL AND expires_at > now()
     AND ticket_hash = encode(sha256(convert_to(coalesce(p_ticket, ''), 'UTF8')), 'hex')
  RETURNING created_by INTO v_user;
  RETURN v_user;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_vibe_redeem_preview_ticket"(p_session_id uuid, p_ticket text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_vibe_redeem_preview_ticket"(p_session_id uuid, p_ticket text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_vibe_redeem_preview_ticket"(p_session_id uuid, p_ticket text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_vibe_require_owner"()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_grand_master() THEN
    RAISE EXCEPTION 'Vibe sessions are limited to the platform owner' USING ERRCODE = '42501';
  END IF;
  RETURN auth.uid();
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_vibe_require_owner"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_vibe_require_owner"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_vibe_require_owner"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."builder_vibe_require_owner"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_vibe_send"(p_session_id uuid, p_content text, p_client_request_id text DEFAULT NULL::text, p_action text DEFAULT 'message'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := public.builder_vibe_require_owner();
  v_status text;
  v_id uuid;
  v_content text := btrim(coalesce(p_content, ''));
BEGIN
  IF p_action NOT IN ('message', 'ship', 'revert') THEN RAISE EXCEPTION 'Unsupported vibe action'; END IF;
  IF p_action = 'message' AND v_content = '' THEN RAISE EXCEPTION 'Message is empty'; END IF;
  IF char_length(v_content) > 20000 THEN RAISE EXCEPTION 'Message is longer than 20000 characters'; END IF;
  SELECT status INTO v_status FROM public.builder_vibe_sessions WHERE id = p_session_id FOR UPDATE;
  IF v_status IS NULL THEN RAISE EXCEPTION 'Vibe session not found'; END IF;
  IF v_status = 'closed' THEN RAISE EXCEPTION 'Vibe session is closed'; END IF;
  IF p_client_request_id IS NOT NULL THEN
    SELECT id INTO v_id FROM public.builder_vibe_messages WHERE session_id = p_session_id AND client_request_id = p_client_request_id;
    IF v_id IS NOT NULL THEN RETURN v_id; END IF;
  END IF;
  INSERT INTO public.builder_vibe_messages (session_id, role, kind, content, payload, status, client_request_id, created_by)
  VALUES (p_session_id, 'owner', 'message', CASE WHEN v_content = '' THEN p_action ELSE v_content END,
          jsonb_build_object('action', p_action), 'queued', left(p_client_request_id, 80), v_user)
  RETURNING id INTO v_id;
  UPDATE public.builder_vibe_sessions SET last_activity_at = now(), updated_at = now() WHERE id = p_session_id;
  RETURN v_id;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_vibe_send"(p_session_id uuid, p_content text, p_client_request_id text, p_action text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_vibe_send"(p_session_id uuid, p_content text, p_client_request_id text, p_action text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_vibe_send"(p_session_id uuid, p_content text, p_client_request_id text, p_action text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."builder_vibe_send"(p_session_id uuid, p_content text, p_client_request_id text, p_action text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_vibe_send_with_attachments"(p_session_id uuid, p_content text, p_client_request_id text, p_attachment_ids uuid[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := public.builder_vibe_require_owner();
  v_ids uuid[] := coalesce(p_attachment_ids, '{}'::uuid[]);
  v_message_id uuid;
  v_payload jsonb;
BEGIN
  IF cardinality(v_ids) > 5 OR cardinality(v_ids) <> (SELECT count(DISTINCT id)::integer FROM unnest(v_ids) AS requested(id)) THEN
    RAISE EXCEPTION 'A message may contain up to five unique attachments';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM unnest(v_ids) AS requested(id)
    LEFT JOIN public.builder_vibe_attachments a
      ON a.id = requested.id AND a.session_id = p_session_id AND a.uploaded_by = v_user
    WHERE a.id IS NULL
       OR (a.file_type NOT LIKE 'image/%' AND a.extraction_status NOT IN ('extracted', 'empty'))
  ) THEN
    RAISE EXCEPTION 'One or more attachments are unavailable or not ready';
  END IF;

  v_message_id := public.builder_vibe_send(p_session_id, p_content, p_client_request_id, 'message');
  SELECT payload INTO v_payload
  FROM public.builder_vibe_messages
  WHERE id = v_message_id AND session_id = p_session_id AND created_by = v_user
  FOR UPDATE;
  IF v_payload IS NULL THEN RAISE EXCEPTION 'Vibe message could not be associated with this owner'; END IF;
  IF v_payload ? 'attachment_ids'
     AND v_payload->'attachment_ids' <> to_jsonb(v_ids) THEN
    RAISE EXCEPTION 'Request id was already used with different attachments';
  END IF;

  UPDATE public.builder_vibe_messages m
     SET payload = v_payload || jsonb_build_object(
       'attachment_ids', to_jsonb(v_ids),
       'attachments', coalesce((
         SELECT jsonb_agg(jsonb_build_object(
           'id', a.id,
           'file_name', a.file_name,
           'file_type', a.file_type,
           'file_size_bytes', a.file_size_bytes,
           'extraction_status', a.extraction_status
         ) ORDER BY a.created_at)
         FROM public.builder_vibe_attachments a
         WHERE a.session_id = p_session_id AND a.id = ANY(v_ids)
       ), '[]'::jsonb)
     )
   WHERE m.id = v_message_id;
  RETURN v_message_id;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_vibe_send_with_attachments"(p_session_id uuid, p_content text, p_client_request_id text, p_attachment_ids uuid[]) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_vibe_send_with_attachments"(p_session_id uuid, p_content text, p_client_request_id text, p_attachment_ids uuid[]) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_vibe_send_with_attachments"(p_session_id uuid, p_content text, p_client_request_id text, p_attachment_ids uuid[]) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."builder_vibe_send_with_attachments"(p_session_id uuid, p_content text, p_client_request_id text, p_attachment_ids uuid[]) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_vibe_send_with_attachments_opt_in"(p_session_id uuid, p_content text, p_client_request_id text, p_attachment_ids uuid[], p_allow_ollama_cloud boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := public.builder_vibe_require_owner();
  v_message_id uuid;
  v_payload jsonb;
  v_consent boolean := coalesce(p_allow_ollama_cloud, false);
BEGIN
  PERFORM 1 FROM public.builder_vibe_sessions
   WHERE id = p_session_id AND created_by = v_user AND status <> 'closed'
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Open Vibe session not found for this owner';
  END IF;
  IF p_client_request_id IS NULL OR char_length(p_client_request_id) NOT BETWEEN 1 AND 80 THEN
    RAISE EXCEPTION 'Attachment consent requires a request id of 1 to 80 characters';
  END IF;

  SELECT payload INTO v_payload FROM public.builder_vibe_messages
   WHERE session_id = p_session_id AND client_request_id = p_client_request_id;
  IF FOUND AND coalesce(v_payload->'external_attachment_consent', 'false'::jsonb) <> to_jsonb(v_consent) THEN
    RAISE EXCEPTION 'Request id was already used with different attachment consent';
  END IF;

  v_message_id := public.builder_vibe_send_with_attachments(
    p_session_id,
    p_content,
    p_client_request_id,
    p_attachment_ids
  );

  UPDATE public.builder_vibe_messages
     SET payload = payload || jsonb_build_object(
       'external_attachment_consent', v_consent,
       'external_attachment_consent_receipt', jsonb_build_object(
         'policy_version', 'non_sensitive_context_v1',
         'actor_user_id', v_user,
         'recorded_at', now(),
         'attachment_ids', coalesce(p_attachment_ids, '{}'::uuid[]),
         'allowed', v_consent
       )
     )
   WHERE id = v_message_id
     AND session_id = p_session_id
     AND created_by = v_user
     AND NOT (payload ? 'external_attachment_consent');

  IF NOT FOUND AND v_payload IS NULL THEN
    RAISE EXCEPTION 'Vibe attachment consent could not be associated with this owner message';
  END IF;

  RETURN v_message_id;
END;
$function$;
COMMENT ON FUNCTION "public"."builder_vibe_send_with_attachments_opt_in"(p_session_id uuid, p_content text, p_client_request_id text, p_attachment_ids uuid[], p_allow_ollama_cloud boolean) IS 'Owner-only attachment send with an explicit per-message Ollama Cloud egress attestation. The worker may send only extracted text or local image descriptions, never raw attachment bytes; no consent defaults to local-only.';
REVOKE ALL ON FUNCTION "public"."builder_vibe_send_with_attachments_opt_in"(p_session_id uuid, p_content text, p_client_request_id text, p_attachment_ids uuid[], p_allow_ollama_cloud boolean) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_vibe_send_with_attachments_opt_in"(p_session_id uuid, p_content text, p_client_request_id text, p_attachment_ids uuid[], p_allow_ollama_cloud boolean) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_vibe_send_with_attachments_opt_in"(p_session_id uuid, p_content text, p_client_request_id text, p_attachment_ids uuid[], p_allow_ollama_cloud boolean) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."builder_vibe_send_with_attachments_opt_in"(p_session_id uuid, p_content text, p_client_request_id text, p_attachment_ids uuid[], p_allow_ollama_cloud boolean) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_vibe_session_close"(p_session_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := public.builder_vibe_require_owner();
BEGIN
  UPDATE public.builder_vibe_sessions
     SET status = 'closed', preview_requested = false, closed_at = now(), updated_at = now()
   WHERE id = p_session_id AND status <> 'closed';
  IF NOT FOUND THEN RAISE EXCEPTION 'Vibe session not found or already closed'; END IF;
  UPDATE public.builder_vibe_messages SET status = 'failed', completed_at = now()
   WHERE session_id = p_session_id AND status = 'queued';
  INSERT INTO public.builder_vibe_messages (session_id, role, kind, content, created_by)
  VALUES (p_session_id, 'system', 'status', 'Session closed by the owner.', v_user);
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_vibe_session_close"(p_session_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_vibe_session_close"(p_session_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_vibe_session_close"(p_session_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."builder_vibe_session_close"(p_session_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_vibe_session_open"(p_title text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := public.builder_vibe_require_owner();
  v_id uuid;
  v_title text := left(coalesce(nullif(btrim(p_title), ''), 'Untitled vibe session'), 160);
BEGIN
  INSERT INTO public.builder_vibe_sessions (created_by, title) VALUES (v_user, v_title) RETURNING id INTO v_id;
  INSERT INTO public.builder_vibe_messages (session_id, role, kind, content, created_by)
  VALUES (v_id, 'system', 'status', 'Session opened. Bob will branch from the current main on your first message.', v_user);
  RETURN v_id;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_vibe_session_open"(p_title text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_vibe_session_open"(p_title text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_vibe_session_open"(p_title text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."builder_vibe_session_open"(p_title text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_vibe_set_preview"(p_session_id uuid, p_on boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := public.builder_vibe_require_owner();
BEGIN
  UPDATE public.builder_vibe_sessions
     SET preview_requested = coalesce(p_on, false),
         preview_status = CASE WHEN coalesce(p_on, false) AND preview_status IN ('off', 'failed') THEN 'starting' ELSE preview_status END,
         last_activity_at = now(), updated_at = now()
   WHERE id = p_session_id AND status <> 'closed';
  IF NOT FOUND THEN RAISE EXCEPTION 'Vibe session not found or closed'; END IF;
  INSERT INTO public.builder_vibe_messages (session_id, role, kind, content, created_by)
  VALUES (p_session_id, 'system', 'preview', CASE WHEN p_on THEN 'Live preview requested.' ELSE 'Live preview turned off.' END, v_user);
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_vibe_set_preview"(p_session_id uuid, p_on boolean) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_vibe_set_preview"(p_session_id uuid, p_on boolean) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_vibe_set_preview"(p_session_id uuid, p_on boolean) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."builder_vibe_set_preview"(p_session_id uuid, p_on boolean) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."calculate_cost_centre_roll"(p_pl_period_id uuid)
 RETURNS SETOF finance_cost_centre_rolls
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_period public.finance_pl_periods%rowtype;
BEGIN
  SELECT organization_id
  INTO v_org
  FROM public.user_profiles
  WHERE id = v_actor
    AND deactivated_at IS NULL;

  IF v_org IS NULL OR NOT public.is_admin_for_org(v_org) THEN
    RAISE EXCEPTION 'Active finance administrator required';
  END IF;

  SELECT *
  INTO v_period
  FROM public.finance_pl_periods
  WHERE id = p_pl_period_id
    AND organization_id = v_org;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'P&L period not found in organization';
  END IF;

  RETURN QUERY
  INSERT INTO public.finance_cost_centre_rolls (
    organization_id,
    pl_period_id,
    cost_centre_id,
    cost_centre_code,
    cost_centre_name,
    total_labour,
    total_vehicle,
    total_materials,
    total_equipment,
    total_overhead,
    total_depreciation,
    total_cost,
    attribution_count
  )
  SELECT
    v_org,
    p_pl_period_id,
    cc.id,
    cc.code,
    cc.name,
    COALESCE(SUM(CASE WHEN fsc.cost_type = 'labour' THEN fsc.total_cost ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN fsc.cost_type = 'vehicle' THEN fsc.total_cost ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN fsc.cost_type = 'materials' THEN fsc.total_cost ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN fsc.cost_type = 'equipment' THEN fsc.total_cost ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN fsc.cost_type = 'overhead' THEN fsc.total_cost ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN fsc.cost_type = 'depreciation' THEN fsc.total_cost ELSE 0 END), 0),
    COALESCE(SUM(fsc.total_cost), 0),
    COUNT(fsc.id)
  FROM public.cost_centres cc
  LEFT JOIN public.finance_service_costs fsc
    ON cc.id = fsc.cost_centre_id
   AND fsc.pl_period_id = p_pl_period_id
   AND fsc.organization_id = v_org
  WHERE cc.organization_id = v_org
  GROUP BY cc.id, cc.code, cc.name
  ON CONFLICT (organization_id, pl_period_id, cost_centre_id)
  DO UPDATE SET
    cost_centre_code = EXCLUDED.cost_centre_code,
    cost_centre_name = EXCLUDED.cost_centre_name,
    total_labour = EXCLUDED.total_labour,
    total_vehicle = EXCLUDED.total_vehicle,
    total_materials = EXCLUDED.total_materials,
    total_equipment = EXCLUDED.total_equipment,
    total_overhead = EXCLUDED.total_overhead,
    total_depreciation = EXCLUDED.total_depreciation,
    total_cost = EXCLUDED.total_cost,
    attribution_count = EXCLUDED.attribution_count
  RETURNING *;
END;
$function$;
COMMENT ON FUNCTION "public"."calculate_cost_centre_roll"(p_pl_period_id uuid) IS 'Recalculates and atomically upserts organization-scoped cost-centre totals for one P&L period.';
REVOKE ALL ON FUNCTION "public"."calculate_cost_centre_roll"(p_pl_period_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."calculate_cost_centre_roll"(p_pl_period_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."calculate_cost_centre_roll"(p_pl_period_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."calculate_cost_centre_roll"(p_pl_period_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."calculate_finance_budget_variance"(p_budget_id uuid, p_pl_period_id uuid)
 RETURNS SETOF finance_budget_variances
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
BEGIN
  SELECT organization_id INTO v_org FROM public.user_profiles WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_org IS NULL OR NOT public.is_admin_for_org(v_org) THEN RAISE EXCEPTION 'Active finance administrator required'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.finance_budgets WHERE id = p_budget_id AND organization_id = v_org AND status IN ('approved','locked')) THEN RAISE EXCEPTION 'Approved budget not found in organization'; END IF;
  RETURN QUERY
  INSERT INTO public.finance_budget_variances(organization_id, budget_id, pl_period_id, cost_centre_id, service_agreement_id, cost_type, budget_amount, actual_amount, variance_amount, variance_pct, status)
  SELECT v_org, p_budget_id, p_pl_period_id, x.cost_centre_id, x.service_agreement_id, x.cost_type, x.budget_amount, x.actual_amount,
    x.actual_amount - x.budget_amount,
    CASE WHEN x.budget_amount > 0 THEN ROUND(((x.actual_amount - x.budget_amount) / x.budget_amount) * 100, 2) ELSE NULL END,
    CASE WHEN x.budget_amount = 0 AND x.actual_amount > 0 THEN 'no_budget' WHEN x.actual_amount <= x.budget_amount THEN 'on_track' WHEN x.actual_amount <= x.budget_amount * 1.10 THEN 'watch' ELSE 'over_budget' END
  FROM (
    SELECT COALESCE(bl.cost_centre_id, ac.cost_centre_id) AS cost_centre_id,
      COALESCE(bl.service_agreement_id, ac.service_agreement_id) AS service_agreement_id,
      COALESCE(bl.cost_type, ac.cost_type) AS cost_type,
      COALESCE(bl.budget_amount, 0) AS budget_amount,
      COALESCE(ac.actual_amount, 0) AS actual_amount
    FROM (SELECT cost_centre_id, service_agreement_id, cost_type, SUM(budget_amount) budget_amount FROM public.finance_budget_lines WHERE budget_id = p_budget_id AND pl_period_id = p_pl_period_id GROUP BY cost_centre_id, service_agreement_id, cost_type) bl
    FULL JOIN (SELECT cost_centre_id, service_agreement_id, cost_type, SUM(total_cost) actual_amount FROM public.finance_service_costs WHERE organization_id = v_org AND pl_period_id = p_pl_period_id GROUP BY cost_centre_id, service_agreement_id, cost_type) ac
      ON bl.cost_centre_id IS NOT DISTINCT FROM ac.cost_centre_id AND bl.service_agreement_id IS NOT DISTINCT FROM ac.service_agreement_id AND bl.cost_type = ac.cost_type
  ) x
  ON CONFLICT (budget_id, pl_period_id, cost_centre_id, service_agreement_id, cost_type)
  DO UPDATE SET budget_amount = EXCLUDED.budget_amount, actual_amount = EXCLUDED.actual_amount, variance_amount = EXCLUDED.variance_amount, variance_pct = EXCLUDED.variance_pct, status = EXCLUDED.status, calculated_at = now()
  RETURNING *;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."calculate_finance_budget_variance"(p_budget_id uuid, p_pl_period_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."calculate_finance_budget_variance"(p_budget_id uuid, p_pl_period_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."calculate_finance_budget_variance"(p_budget_id uuid, p_pl_period_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."calculate_finance_budget_variance"(p_budget_id uuid, p_pl_period_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."calculate_finance_quote_cost"(p_inputs jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_hours numeric := greatest(0, coalesce((p_inputs->>'labour_hours')::numeric, 0));
  v_km numeric := greatest(0, coalesce((p_inputs->>'vehicle_km')::numeric, 0));
  v_base numeric := greatest(0, coalesce((p_inputs->>'base_hourly_rate')::numeric, 0));
  v_oncost numeric := greatest(0, coalesce((p_inputs->>'labour_oncost_pct')::numeric, 0));
  v_leave numeric := greatest(0, coalesce((p_inputs->>'leave_provision_pct')::numeric, 0));
  v_vehicle_fixed numeric := greatest(0, coalesce((p_inputs->>'vehicle_fixed_annual')::numeric, 0));
  v_vehicle_hours numeric := greatest(0, coalesce((p_inputs->>'vehicle_productive_hours')::numeric, 0));
  v_vehicle_km_rate numeric := greatest(0, coalesce((p_inputs->>'vehicle_variable_per_km')::numeric, 0));
  v_acquisition_cost numeric := greatest(0, coalesce((p_inputs->>'asset_acquisition_cost')::numeric, 0));
  v_setup_cost numeric := greatest(0, coalesce((p_inputs->>'asset_setup_cost')::numeric, 0));
  v_residual_value numeric := greatest(0, coalesce((p_inputs->>'asset_residual_value')::numeric, 0));
  v_useful_life_months numeric := greatest(0, coalesce((p_inputs->>'asset_useful_life_months')::numeric, 0));
  v_depreciation numeric := 0;
  v_equipment numeric := greatest(0, coalesce((p_inputs->>'equipment_cost')::numeric, 0));
  v_direct numeric := greatest(0, coalesce((p_inputs->>'direct_operating_cost')::numeric, 0));
  v_overhead_pct numeric := greatest(0, coalesce((p_inputs->>'overhead_pct')::numeric, 0));
  v_margin_pct numeric := greatest(0, least(99.99, coalesce((p_inputs->>'target_margin_pct')::numeric, 0)));
  v_labour numeric;
  v_vehicle numeric;
  v_direct_cost numeric;
  v_overhead numeric;
  v_true_cost numeric;
  v_charge numeric;
BEGIN
  SELECT organization_id INTO v_org FROM public.user_profiles WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_org IS NULL OR NOT public.is_admin_for_org(v_org) THEN RAISE EXCEPTION 'Active finance administrator required'; END IF;
  IF v_hours <= 0 THEN RAISE EXCEPTION 'Labour hours are required'; END IF;
  IF v_base <= 0 THEN RAISE EXCEPTION 'Base hourly rate is required'; END IF;
  IF v_km > 0 AND v_vehicle_km_rate <= 0 THEN RAISE EXCEPTION 'Vehicle per-km cost is required when travel is entered'; END IF;
  IF v_vehicle_fixed > 0 AND v_vehicle_hours <= 0 THEN RAISE EXCEPTION 'Vehicle productive hours are required for fixed vehicle cost'; END IF;
  IF v_acquisition_cost + v_setup_cost > 0 AND v_useful_life_months <= 0 THEN RAISE EXCEPTION 'Asset useful life is required when an acquisition cost is entered'; END IF;
  IF v_residual_value > v_acquisition_cost + v_setup_cost THEN RAISE EXCEPTION 'Asset residual value cannot exceed capitalized cost'; END IF;
  v_labour := v_hours * v_base * (1 + (v_oncost + v_leave) / 100);
  v_depreciation := (v_acquisition_cost + v_setup_cost - v_residual_value) / nullif(v_useful_life_months / 12, 0);
  IF v_depreciation > 0 AND v_vehicle_hours <= 0 THEN RAISE EXCEPTION 'Vehicle productive hours are required to allocate asset depreciation'; END IF;
  v_vehicle := CASE WHEN v_vehicle_fixed + v_depreciation > 0 THEN v_hours * ((v_vehicle_fixed + v_depreciation) / v_vehicle_hours) ELSE 0 END + v_km * v_vehicle_km_rate;
  v_direct_cost := v_labour + v_vehicle + v_equipment + v_direct;
  v_overhead := v_direct_cost * v_overhead_pct / 100;
  v_true_cost := round(v_direct_cost + v_overhead, 2);
  v_charge := round(greatest(coalesce((p_inputs->>'client_charge')::numeric, 0), v_true_cost / nullif(1 - v_margin_pct / 100, 0)), 2);
  RETURN jsonb_build_object('organization_id', v_org, 'currency', coalesce(p_inputs->>'currency', 'NZD'), 'true_cost', v_true_cost, 'client_charge', v_charge, 'gross_margin', round(v_charge - v_true_cost, 2), 'gross_margin_pct', round((v_charge - v_true_cost) / nullif(v_charge, 0) * 100, 2), 'breakdown', jsonb_build_object('loaded_labour', round(v_labour, 2), 'vehicle_travel', round(v_vehicle, 2), 'depreciation_annual', round(v_depreciation, 2), 'equipment', round(v_equipment, 2), 'direct_operating', round(v_direct, 2), 'allocated_overhead', round(v_overhead, 2)), 'inputs', p_inputs, 'basis', 'server_calculated_estimate', 'approval_required', true);
END;
$function$;
REVOKE ALL ON FUNCTION "public"."calculate_finance_quote_cost"(p_inputs jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."calculate_finance_quote_cost"(p_inputs jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."calculate_finance_quote_cost"(p_inputs jsonb) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."calculate_finance_quote_cost"(p_inputs jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."calculate_service_profitability_snapshot"(p_pl_period_id uuid)
 RETURNS SETOF finance_service_profitability
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_period public.finance_pl_periods%rowtype;
  v_row public.finance_service_profitability%rowtype;
BEGIN
  SELECT organization_id INTO v_org FROM public.user_profiles WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_org IS NULL OR NOT public.is_admin_for_org(v_org) THEN RAISE EXCEPTION 'Active finance administrator required'; END IF;

  SELECT * INTO v_period FROM public.finance_pl_periods WHERE id = p_pl_period_id AND organization_id = v_org;
  IF NOT FOUND THEN RAISE EXCEPTION 'P&L period not found in organization'; END IF;

  RETURN QUERY
  WITH quote_estimates AS (
    SELECT
      sa.id as service_agreement_id,
      sa.client_organization_id,
      'quote' as service_type,
      NULL::uuid as location_id,
      COALESCE(SUM(CASE WHEN ct.category_name = 'labour' THEN qci.cost_amount ELSE 0 END), 0) as est_labour,
      COALESCE(SUM(CASE WHEN ct.category_name = 'vehicle' THEN qci.cost_amount ELSE 0 END), 0) as est_vehicle,
      COALESCE(SUM(CASE WHEN ct.category_name = 'materials' THEN qci.cost_amount ELSE 0 END), 0) as est_materials,
      COALESCE(SUM(CASE WHEN ct.category_name = 'overhead' THEN qci.cost_amount ELSE 0 END), 0) as est_overhead,
      COALESCE(SUM(qci.cost_amount), 0) as est_total,
      COALESCE(SUM(qci.invoice_amount), 0) as quoted_charge
    FROM public.service_agreements sa
    LEFT JOIN public.quotes q ON sa.id = q.service_agreement_id AND q.status IN ('approved','accepted','invoiced')
    LEFT JOIN public.quote_cost_items qci ON q.id = qci.quote_id
    LEFT JOIN public.finance_cost_categories ct ON qci.cost_category_id = ct.id
    WHERE sa.provider_organization_id = v_org
    GROUP BY sa.id, sa.client_organization_id
  ),
  actual_costs AS (
    SELECT
      fsc.service_agreement_id,
      fsc.client_organization_id,
      fsc.site_id as location_id,
      COALESCE(SUM(CASE WHEN fsc.cost_type = 'labour' THEN fsc.total_cost ELSE 0 END), 0) as act_labour,
      COALESCE(SUM(CASE WHEN fsc.cost_type = 'vehicle' THEN fsc.total_cost ELSE 0 END), 0) as act_vehicle,
      COALESCE(SUM(CASE WHEN fsc.cost_type = 'materials' THEN fsc.total_cost ELSE 0 END), 0) as act_materials,
      COALESCE(SUM(CASE WHEN fsc.cost_type = 'overhead' THEN fsc.total_cost ELSE 0 END), 0) as act_overhead,
      COALESCE(SUM(fsc.total_cost), 0) as act_total,
      COUNT(*) as cost_lines
    FROM public.finance_service_costs fsc
    WHERE fsc.organization_id = v_org AND fsc.pl_period_id = p_pl_period_id
    GROUP BY fsc.service_agreement_id, fsc.client_organization_id, fsc.site_id
  ),
  combined AS (
    SELECT
      COALESCE(qe.service_agreement_id, ac.service_agreement_id) as sa_id,
      COALESCE(qe.client_organization_id, ac.client_organization_id) as client_org,
      qe.service_type,
      COALESCE(ac.location_id, qe.location_id) as loc_id,
      qe.est_labour, ac.act_labour,
      qe.est_vehicle, ac.act_vehicle,
      qe.est_materials, ac.act_materials,
      qe.est_overhead, ac.act_overhead,
      qe.est_total, ac.act_total,
      qe.quoted_charge
    FROM quote_estimates qe
    FULL JOIN actual_costs ac ON qe.service_agreement_id = ac.service_agreement_id AND qe.location_id IS NOT DISTINCT FROM ac.location_id
  )
  INSERT INTO public.finance_service_profitability(
    organization_id, pl_period_id, service_agreement_id, client_organization_id, service_type, location_id,
    estimated_labour, actual_labour, labour_variance_pct,
    estimated_vehicle, actual_vehicle, vehicle_variance_pct,
    estimated_materials, actual_materials, materials_variance_pct,
    estimated_overhead, actual_overhead, overhead_variance_pct,
    estimated_total_cost, actual_total_cost, total_variance_pct,
    estimated_margin_pct, actual_margin_pct, margin_impact_pct,
    client_invoice_total, net_profit, work_unit_count, invoice_count, created_by
  )
  SELECT
    v_org, p_pl_period_id, c.sa_id, c.client_org, c.service_type, c.loc_id,
    c.est_labour, c.act_labour,
    CASE WHEN c.est_labour > 0 THEN ROUND(((c.act_labour - c.est_labour) / c.est_labour) * 100, 2) ELSE NULL END,
    c.est_vehicle, c.act_vehicle,
    CASE WHEN c.est_vehicle > 0 THEN ROUND(((c.act_vehicle - c.est_vehicle) / c.est_vehicle) * 100, 2) ELSE NULL END,
    c.est_materials, c.act_materials,
    CASE WHEN c.est_materials > 0 THEN ROUND(((c.act_materials - c.est_materials) / c.est_materials) * 100, 2) ELSE NULL END,
    c.est_overhead, c.act_overhead,
    CASE WHEN c.est_overhead > 0 THEN ROUND(((c.act_overhead - c.est_overhead) / c.est_overhead) * 100, 2) ELSE NULL END,
    c.est_total, c.act_total,
    CASE WHEN c.est_total > 0 THEN ROUND(((c.act_total - c.est_total) / c.est_total) * 100, 2) ELSE NULL END,
    CASE WHEN c.quoted_charge > 0 THEN ROUND(((c.quoted_charge - c.est_total) / c.quoted_charge) * 100, 2) ELSE NULL END,
    CASE WHEN c.quoted_charge > 0 THEN ROUND(((c.quoted_charge - c.act_total) / c.quoted_charge) * 100, 2) ELSE NULL END,
    CASE WHEN c.quoted_charge > 0 THEN ROUND(((c.quoted_charge - c.act_total) / c.quoted_charge) * 100, 2) ELSE NULL END,
    c.quoted_charge, c.quoted_charge - c.act_total,
    NULL::integer, NULL::integer, v_actor
  FROM combined c;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."calculate_service_profitability_snapshot"(p_pl_period_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."calculate_service_profitability_snapshot"(p_pl_period_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."calculate_service_profitability_snapshot"(p_pl_period_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."calculate_service_profitability_snapshot"(p_pl_period_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."calculate_vehicle_compliance"(p_plate text, p_zone_id uuid, p_org_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
declare
  v_rules             zone_compliance_matrix%rowtype;
  v_zone              location_zones%rowtype;
  v_scv               canonical_scv%rowtype;
  v_streak            integer := 0;   -- current consecutive-night streak
  v_nights_month      integer := 0;   -- distinct verified nights this calendar month
  v_is_compliant      boolean := true;
  v_reason            text := 'compliant';
  v_month_start_date  date := date_trunc('month', current_date)::date;
  v_rule_type         text;
  v_scv_exempts       boolean := true;
begin
  -- Fetch zone rule_type + scv_exempts_restriction (0191).
  select * into v_zone from location_zones where id = p_zone_id;
  if found then
    v_rule_type   := coalesce(v_zone.rule_type, 'overnight_limited');
    v_scv_exempts := coalesce(v_zone.scv_exempts_restriction, true);
  else
    v_rule_type   := 'overnight_limited';
    v_scv_exempts := true;
  end if;

  -- ── GATE 1: prohibited / day_visit_only (unchanged from 0194) ────────────
  if v_rule_type in ('prohibited', 'day_visit_only') then
    select count(distinct overnight_date)
    into v_streak
    from vehicle_overnight_sessions
    where
      plate_number = p_plate
      and zone_id = p_zone_id
      and organization_id = p_org_id
      and verification_status = 'verified_overnight'
      and overnight_date >= v_month_start_date;

    if v_streak > 0 then
      return jsonb_build_object(
        'is_compliant',      false,
        'reason',            'no_overnight_permitted',
        'nights_this_zone',  v_streak,
        'nights_this_month', v_streak,
        'limit_consecutive', null,
        'limit_monthly',     null,
        'scv_required',      false,
        'is_scv',            false
      );
    end if;
    return jsonb_build_object(
      'is_compliant',      true,
      'reason',            'no_overnight_yet',
      'nights_this_zone',  0,
      'nights_this_month', 0,
      'limit_consecutive', null,
      'limit_monthly',     null,
      'scv_required',      false,
      'is_scv',            false
    );
  end if;

  -- ── GATE 2: restricted / SCV gate (unchanged from 0194) ──────────────────
  if v_rule_type = 'restricted' and v_scv_exempts then
    select * into v_scv
    from canonical_scv
    where
      plate_number = p_plate
      and certificate_status = 'active'
      and (expiry_date is null or expiry_date >= current_date);

    if not found then
      return jsonb_build_object(
        'is_compliant',      false,
        'reason',            'no_scv_certificate',
        'nights_this_zone',  0,
        'nights_this_month', 0,
        'limit_consecutive', null,
        'limit_monthly',     null,
        'scv_required',      true,
        'is_scv',            false
      );
    end if;
  end if;

  -- ── Night-count path (unrestricted / overnight_limited / restricted+SCV) ──

  -- Get current compliance rules.
  select * into v_rules
  from zone_compliance_matrix
  where
    zone_id = p_zone_id
    and organization_id = p_org_id
    and is_current = true
    and effective_from <= current_date
    and (effective_to is null or effective_to >= current_date)
  order by version desc
  limit 1;

  if not found then
    return jsonb_build_object(
      'is_compliant', true,
      'reason', 'no_rules_configured',
      'nights_this_zone', 0,
      'nights_this_month', 0,
      'limit_consecutive', null,
      'limit_monthly', null,
      'scv_required', false,
      'is_scv', (v_scv.id is not null)
    );
  end if;

  -- SCV gate for overnight_limited zones (unchanged from 0194).
  if v_rule_type not in ('restricted') and v_rules.scv_required then
    if v_scv.id is null then
      select * into v_scv
      from canonical_scv
      where
        plate_number = p_plate
        and certificate_status = 'active'
        and (expiry_date is null or expiry_date >= current_date);

      if not found then
        return jsonb_build_object(
          'is_compliant', false,
          'reason', 'no_scv_certificate',
          'nights_this_zone', 0,
          'nights_this_month', 0,
          'limit_consecutive', v_rules.max_consecutive_nights,
          'limit_monthly', v_rules.max_nights_per_month,
          'scv_required', true,
          'is_scv', false
        );
      end if;
    end if;
  end if;

  -- ── COUNTER 1: consecutive streak (THE FIX) ──────────────────────────────
  -- Reads from vehicle_overnight_sessions for BOTH verification modes.
  -- For two_photo_verified: sessions created by the two-photo morning scan.
  -- For single_daily_observation: sessions created by process-officer-scan
  --   using the movement-check result (stationary -> verified_overnight).
  -- For historical import (#79): sessions with evidence_strength='inferred'.
  -- All three produce verified_overnight rows; the streak algorithm is identical.
  --
  -- Algorithm: subtract ROW_NUMBER() (as an interval) from each date.
  -- Consecutive dates produce the same anchor (streak_group); a gap of >=1
  -- day produces a different anchor. Current streak = count of dates in the
  -- group containing max(overnight_date). No cursor, no loop.
  with dated as (
    select distinct overnight_date
    from vehicle_overnight_sessions
    where
      plate_number = p_plate
      and zone_id = p_zone_id
      and organization_id = p_org_id
      and verification_status = 'verified_overnight'
  ),
  grouped as (
    select
      overnight_date,
      overnight_date
        - (row_number() over (order by overnight_date))::integer * interval '1 day'
        as streak_group
    from dated
  ),
  current_group as (
    select streak_group
    from grouped
    order by overnight_date desc
    limit 1
  )
  select coalesce(count(*), 0)
  into v_streak
  from grouped
  where streak_group = (select streak_group from current_group);

  -- ── COUNTER 2: monthly total ────────────────────────────────────────────────
  -- Distinct verified overnight nights since the 1st of the calendar month,
  -- regardless of gaps or streaks. Resets on the 1st.
  select coalesce(count(distinct overnight_date), 0)
  into v_nights_month
  from vehicle_overnight_sessions
  where
    plate_number = p_plate
    and organization_id = p_org_id
    and verification_status = 'verified_overnight'
    and overnight_date >= v_month_start_date;

  -- ── Limit comparisons ────────────────────────────────────────────────────────────
  -- BREACH fires when the count EXCEEDS the limit (> not >=).
  -- Owner-confirmed: limit=3 means 3 nights are allowed; the 4th breaches.
  -- Consecutive checked first; if both trip simultaneously, consecutive wins.

  if v_rules.max_consecutive_nights is not null
    and v_streak > v_rules.max_consecutive_nights then
    v_is_compliant := false;
    v_reason := 'consecutive_night_limit_exceeded';
  end if;

  if v_is_compliant
    and v_rules.max_nights_per_month is not null
    and v_nights_month > v_rules.max_nights_per_month then
    v_is_compliant := false;
    v_reason := 'monthly_limit_exceeded';
  end if;

  -- nights_this_zone = streak (what the consecutive limit is about).
  -- nights_this_month = monthly total (what the monthly limit is about).
  -- process-officer-scan Step 8a at_risk detection reads both and fires
  -- when streak == max_consecutive_nights OR total == max_nights_per_month
  -- (AT the limit, next night would breach) -- no code change needed there.
  return jsonb_build_object(
    'is_compliant',      v_is_compliant,
    'reason',            v_reason,
    'nights_this_zone',  v_streak,
    'nights_this_month', v_nights_month,
    'limit_consecutive', v_rules.max_consecutive_nights,
    'limit_monthly',     v_rules.max_nights_per_month,
    'scv_required',      coalesce(v_rules.scv_required, false),
    'is_scv',            (v_scv.id is not null)
  );
end;
$function$;
COMMENT ON FUNCTION "public"."calculate_vehicle_compliance"(p_plate text, p_zone_id uuid, p_org_id uuid) IS 'Compliance engine. Layer 2 (0195): two independent counters. (1) Consecutive streak (nights_this_zone): length of the current unbroken run of verified_overnight sessions, using ROW_NUMBER()-subtraction streak-group algorithm -- resets to 1 after any gap. Breach fires when streak > max_consecutive_nights (the 4th night breaches when limit is 3). (2) Monthly total (nights_this_month): count(distinct overnight_date) from verified sessions since the 1st of the calendar month, regardless of gaps. Breach fires when total > max_nights_per_month. Both limits are independent; consecutive checked first. Unified source: both two_photo_verified and single_daily_observation modes read from vehicle_overnight_sessions (sessions created by process-officer-scan using movement-check for live single-daily orgs, or by historical import with evidence_strength=inferred). Layer 1 (0194) rule_type gate runs first. Layer 0 (0193) verified-session source. #74.';
REVOKE ALL ON FUNCTION "public"."calculate_vehicle_compliance"(p_plate text, p_zone_id uuid, p_org_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."calculate_vehicle_compliance"(p_plate text, p_zone_id uuid, p_org_id uuid) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."calculate_vehicle_compliance"(p_plate text, p_zone_id uuid, p_org_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."calculate_vehicle_compliance"(p_plate text, p_zone_id uuid, p_org_id uuid) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."calculate_vehicle_compliance"(p_plate text, p_zone_id uuid, p_org_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."calculate_vehicle_compliance"(p_plate text, p_zone_id uuid, p_org_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."can_access_person_contacts"(p_organization_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT p_organization_id IS NOT NULL
    AND public.org_access_allowed(p_organization_id)
    AND EXISTS (
      SELECT 1 FROM public.user_profiles p
      WHERE p.id = auth.uid() AND p.deactivated_at IS NULL
        AND p.role IN ('grand_master', 'master', 'admin', 'admin_officer')
    );
$function$;
REVOKE ALL ON FUNCTION "public"."can_access_person_contacts"(p_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."can_access_person_contacts"(p_organization_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."can_access_person_contacts"(p_organization_id uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."can_access_vehicle_owner_identity"(p_organization_id uuid, p_record boolean DEFAULT false)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT auth.uid() IS NOT NULL AND p_organization_id IS NOT NULL AND (
    public.is_admin_for_org(p_organization_id)
    OR EXISTS (
      SELECT 1
      FROM public.resolve_access_grants(auth.uid(), p_organization_id) grant_row
      JOIN public.user_profiles profile ON profile.id = auth.uid() AND profile.deactivated_at IS NULL
      WHERE grant_row.area = 'vehicle_owner_identity'
        AND (NOT p_record OR grant_row.level IN ('adjust', 'manage'))
    )
  );
$function$;
COMMENT ON FUNCTION "public"."can_access_vehicle_owner_identity"(p_organization_id uuid, p_record boolean) IS 'True when the caller may see (p_record=false) or record (p_record=true) vehicle owner identity for the organisation: organisation administrators, or users holding the vehicle_owner_identity access area (direct grant or preset; view reads, adjust/manage records).';
REVOKE ALL ON FUNCTION "public"."can_access_vehicle_owner_identity"(p_organization_id uuid, p_record boolean) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."can_access_vehicle_owner_identity"(p_organization_id uuid, p_record boolean) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."can_access_vehicle_owner_identity"(p_organization_id uuid, p_record boolean) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."can_access_vehicle_owner_identity"(p_organization_id uuid, p_record boolean) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."can_approve_action"(p_user_id uuid, p_action_org_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_role text;
BEGIN
  SELECT up.role INTO v_role
  FROM user_profiles up
  WHERE up.id = p_user_id AND up.deactivated_at IS NULL;

  IF v_role IS NULL THEN
    RETURN false;
  END IF;

  -- grand_master can approve anything
  IF v_role = 'grand_master' THEN
    RETURN true;
  END IF;

  -- master/admin: check tree-based access
  IF v_role IN ('master', 'admin', 'admin_officer') THEN
    -- Use a direct check mirroring is_admin_for_org but parameterized by user
    RETURN EXISTS (
      SELECT 1 FROM user_profiles up
      WHERE up.id = p_user_id
        AND (
          -- master: descendant tree
          (up.role = 'master' AND (
            p_action_org_id = ANY(get_descendant_organizations(up.employer_organization_id))
            OR p_action_org_id = ANY(get_descendant_organizations(up.organization_id))
            -- Agreement-based (0271 Model A)
            OR EXISTS (
              SELECT 1 FROM service_agreements sa
              WHERE (sa.ends_on IS NULL OR sa.ends_on >= current_date)
                AND sa.agreement_type = 'operational'
                AND sa.client_organization_id = p_action_org_id
                AND (up.organization_id = sa.provider_organization_id
                     OR up.employer_organization_id = sa.provider_organization_id)
            )
          ))
          OR
          -- admin: direct org or descendant tree
          (up.role IN ('admin', 'admin_officer') AND (
            up.organization_id = p_action_org_id
            OR p_action_org_id = ANY(get_descendant_organizations(up.organization_id))
            -- Agreement-based (0271 Model A)
            OR EXISTS (
              SELECT 1 FROM service_agreements sa
              WHERE (sa.ends_on IS NULL OR sa.ends_on >= current_date)
                AND sa.agreement_type = 'operational'
                AND sa.client_organization_id = p_action_org_id
                AND (up.organization_id = sa.provider_organization_id
                     OR up.employer_organization_id = sa.provider_organization_id)
            )
          ))
        )
    );
  END IF;

  RETURN false;
END;
$function$;
COMMENT ON FUNCTION "public"."can_approve_action"(p_user_id uuid, p_action_org_id uuid) IS 'Tree-based authorization check: can user p_user_id approve actions for org p_action_org_id? Mirrors is_admin_for_org logic but parameterized by user_id (not auth.uid()). Used by bob-proposal-approver edge function. #16/#18.';
REVOKE ALL ON FUNCTION "public"."can_approve_action"(p_user_id uuid, p_action_org_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."can_approve_action"(p_user_id uuid, p_action_org_id uuid) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."can_approve_action"(p_user_id uuid, p_action_org_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."can_approve_action"(p_user_id uuid, p_action_org_id uuid) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."can_approve_action"(p_user_id uuid, p_action_org_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."can_approve_action"(p_user_id uuid, p_action_org_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."can_manage_place_hazards"(p_organization_id uuid, p_location_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT public.is_admin_for_org(p_organization_id) AND (
    EXISTS (SELECT 1 FROM public.locations l WHERE l.id = p_location_id AND l.organization_id = p_organization_id)
    OR EXISTS (
      SELECT 1 FROM public.service_agreement_locations sal
      JOIN public.service_agreements sa ON sa.id = sal.service_agreement_id
      LEFT JOIN public.client_sites s ON s.id = sal.site_id
      LEFT JOIN public.location_zones z ON z.id = sal.zone_id
      WHERE sal.status = 'active' AND sa.agreement_type = 'operational'
        AND (sa.starts_on IS NULL OR sa.starts_on <= current_date)
        AND (sa.ends_on IS NULL OR sa.ends_on >= current_date)
        AND (s.location_id = p_location_id OR z.location_id = p_location_id)
        AND (sa.provider_organization_id = p_organization_id OR sa.client_organization_id = p_organization_id
             OR sal.head_contractor_org_id = p_organization_id)
    )
  );
$function$;
COMMENT ON FUNCTION "public"."can_manage_place_hazards"(p_organization_id uuid, p_location_id uuid) IS 'Caller is an administrator of the keeping organisation and that organisation owns or works at the place.';
REVOKE ALL ON FUNCTION "public"."can_manage_place_hazards"(p_organization_id uuid, p_location_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."can_manage_place_hazards"(p_organization_id uuid, p_location_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."can_manage_place_hazards"(p_organization_id uuid, p_location_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."can_manage_place_hazards"(p_organization_id uuid, p_location_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."can_manage_r_and_m_identity"()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.user_profiles actor
    WHERE actor.id = (SELECT auth.uid())
      AND actor.deactivated_at IS NULL
      AND actor.role IN ('admin', 'admin_officer', 'master', 'grand_master')
      AND (
        actor.role = 'grand_master'
        OR actor.organization_id = 'e96d71c9-28a6-4d4a-b0f3-1c4ecdaa9c13'::uuid
        OR actor.organization_id = ANY(public.get_descendant_organizations('e96d71c9-28a6-4d4a-b0f3-1c4ecdaa9c13'::uuid))
        OR actor.employer_organization_id = ANY(public.get_descendant_organizations('e96d71c9-28a6-4d4a-b0f3-1c4ecdaa9c13'::uuid))
      )
  );
$function$;
REVOKE ALL ON FUNCTION "public"."can_manage_r_and_m_identity"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."can_manage_r_and_m_identity"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."can_manage_r_and_m_identity"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."can_manage_r_and_m_identity"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."can_read_current_report_pack_pdf"(p_object_name text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
  select exists (
    select 1
    from public.monthly_report_packs report_pack
    where report_pack.pdf_path = p_object_name
      and report_pack.pdf_source_updated_at = report_pack.updated_at
  );
$function$;
REVOKE ALL ON FUNCTION "public"."can_read_current_report_pack_pdf"(p_object_name text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."can_read_current_report_pack_pdf"(p_object_name text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."can_read_current_report_pack_pdf"(p_object_name text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."can_read_place_hazard"(p_organization_id uuid, p_location_id uuid, p_site_id uuid, p_zone_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT public.org_access_allowed(p_organization_id)
    OR EXISTS (SELECT 1 FROM public.locations l WHERE l.id = p_location_id AND public.org_access_allowed(l.organization_id))
    OR (p_site_id IS NOT NULL AND public.has_location_access(p_site_id, NULL))
    OR (p_zone_id IS NOT NULL AND public.has_location_access(NULL, p_zone_id))
    OR EXISTS (SELECT 1 FROM public.client_sites s WHERE s.location_id = p_location_id AND public.has_location_access(s.id, NULL))
    OR EXISTS (SELECT 1 FROM public.location_zones z WHERE z.location_id = p_location_id AND public.has_location_access(NULL, z.id));
$function$;
COMMENT ON FUNCTION "public"."can_read_place_hazard"(p_organization_id uuid, p_location_id uuid, p_site_id uuid, p_zone_id uuid) IS 'Caller may read a place hazard: the keeping organisation is in scope, or the caller''s organisation owns or works at the place (ownership, operational agreement or head contractor).';
REVOKE ALL ON FUNCTION "public"."can_read_place_hazard"(p_organization_id uuid, p_location_id uuid, p_site_id uuid, p_zone_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."can_read_place_hazard"(p_organization_id uuid, p_location_id uuid, p_site_id uuid, p_zone_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."can_read_place_hazard"(p_organization_id uuid, p_location_id uuid, p_site_id uuid, p_zone_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."can_read_place_hazard"(p_organization_id uuid, p_location_id uuid, p_site_id uuid, p_zone_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."can_record_incident_person"(p_incident_id uuid, p_actor uuid DEFAULT auth.uid())
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS(
    SELECT 1 FROM public.incidents incident
    JOIN public.user_profiles profile ON profile.id=p_actor AND profile.deactivated_at IS NULL
    WHERE incident.id=p_incident_id AND incident.status IN ('open','in_review','escalated')
      AND (public.is_admin_for_org(incident.organization_id)
        OR (profile.role IN ('officer','admin_officer') AND incident.officer_user_id=p_actor))
  )
$function$;
REVOKE ALL ON FUNCTION "public"."can_record_incident_person"(p_incident_id uuid, p_actor uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."can_record_incident_person"(p_incident_id uuid, p_actor uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."can_record_incident_person"(p_incident_id uuid, p_actor uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."can_record_incident_person"(p_incident_id uuid, p_actor uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."can_search_people"(p_organization_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.user_profiles p
    WHERE p.id = auth.uid() AND p.deactivated_at IS NULL
      AND public.org_access_allowed(coalesce(p_organization_id, p.organization_id))
      AND (
        p.role IN ('grand_master', 'master', 'admin', 'admin_officer')
        OR EXISTS (
          SELECT 1 FROM public.resolve_access_grants(p.id, p.organization_id) g
          WHERE g.area = 'person_search'
        )
      )
  );
$function$;
COMMENT ON FUNCTION "public"."can_search_people"(p_organization_id uuid) IS 'Operational person lookup: active operations roles or explicit person_search area at the user home organisation. The staff authorization enables lookup only within existing org_access_allowed scope, including operational agreements; it creates no organization access and no NZTA or contact-detail permission.';
REVOKE ALL ON FUNCTION "public"."can_search_people"(p_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."can_search_people"(p_organization_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."can_search_people"(p_organization_id uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."can_view_rnm_identity_for_organization"(p_organization_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT COALESCE(private.rnm_admin_for_organization(p_organization_id), false);
$function$;
COMMENT ON FUNCTION "public"."can_view_rnm_identity_for_organization"(p_organization_id uuid) IS 'True only when the caller is an R&M administrator, master or grandmaster for this R&M-tree organisation. Same gate as the R&M identity RPCs; reveals nothing beyond the caller''s own authority.';
REVOKE ALL ON FUNCTION "public"."can_view_rnm_identity_for_organization"(p_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."can_view_rnm_identity_for_organization"(p_organization_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."can_view_rnm_identity_for_organization"(p_organization_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."can_view_rnm_identity_for_organization"(p_organization_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."cancel_document_source_ingestion"(p_run_id uuid)
 RETURNS document_source_ingestion_runs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_run public.document_source_ingestion_runs%ROWTYPE;
BEGIN
  SELECT * INTO v_run
  FROM public.document_source_ingestion_runs
  WHERE id = p_run_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Document source run not found';
  END IF;
  IF NOT (public.is_admin_for_org(v_run.organization_id) OR public.is_grand_master()) THEN
    RAISE EXCEPTION 'Not authorized for this document source run';
  END IF;
  IF v_run.status IN ('completed', 'failed', 'cancelled') THEN
    RETURN v_run;
  END IF;

  UPDATE public.document_source_ingestion_runs
  SET status = CASE WHEN status = 'queued' THEN 'cancelled' ELSE 'cancel_requested' END,
      completed_at = CASE WHEN status = 'queued' THEN clock_timestamp() ELSE completed_at END
  WHERE id = p_run_id
  RETURNING * INTO v_run;

  INSERT INTO public.document_source_run_events (
    organization_id,
    run_id,
    event_type,
    phase,
    message_redacted
  )
  VALUES (
    v_run.organization_id,
    v_run.id,
    'cancellation_requested',
    v_run.phase,
    'Document source run cancellation requested.'
  );

  RETURN v_run;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."cancel_document_source_ingestion"(p_run_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."cancel_document_source_ingestion"(p_run_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."cancel_document_source_ingestion"(p_run_id uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."cancel_shift_swap"(p_swap_id uuid, p_expected_status text, p_reason text)
 RETURNS shift_swaps
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid := auth.uid(); v_swap public.shift_swaps%rowtype; v_user uuid; v_reason text := nullif(trim(coalesce(p_reason, '')), '');
begin
  if v_reason is null then raise exception 'A cancellation reason is required'; end if;
  select sw.* into v_swap from public.shift_swaps sw where sw.id = p_swap_id for update;
  if not found then raise exception 'Shift swap request not found'; end if;
  if v_swap.status <> p_expected_status or v_swap.status <> 'pending' then raise exception 'Only the current pending swap request can be cancelled'; end if;
  select coalesce(sp.user_id, sp.id) into v_user from public.staff_profiles sp where sp.id = v_swap.original_staff_id;
  if v_user is distinct from v_actor then raise exception 'Only the requesting officer can cancel this swap'; end if;
  update public.shift_swaps set status = 'cancelled', declined_reason = v_reason where id = v_swap.id returning * into v_swap;
  insert into public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata) values (v_swap.organization_id, v_actor, 'shift_swap_cancelled', 'shift_swaps', v_swap.id, jsonb_build_object('reason', v_reason, 'original_shift_id', v_swap.original_shift_id));
  return v_swap;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."cancel_shift_swap"(p_swap_id uuid, p_expected_status text, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."cancel_shift_swap"(p_swap_id uuid, p_expected_status text, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."cancel_shift_swap"(p_swap_id uuid, p_expected_status text, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."cancel_shift_swap"(p_swap_id uuid, p_expected_status text, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."canonical_place_for_house"(p_location_id uuid, p_org uuid, p_name text, p_address text, p_key text, p_kind_hint text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; v_kind text;
BEGIN
  IF p_location_id IS NULL THEN RETURN NULL; END IF;
  v_kind := CASE WHEN p_key IS NOT NULL THEN 'site' WHEN p_kind_hint IN ('site', 'zone') THEN p_kind_hint ELSE 'zone' END;
  v_id := CASE WHEN p_key IS NOT NULL
    THEN public.ensure_canonical_place('site', 'site:' || p_key, p_name, p_address, jsonb_build_object('created_from', 'locations', 'source_id', p_location_id))
    ELSE public.ensure_canonical_place(v_kind, v_kind || ':' || p_location_id::text, p_name, NULL, jsonb_build_object('created_from', 'locations', 'source_id', p_location_id)) END;
  INSERT INTO public.canonical_place_links (canonical_place_id, source_table, source_id, organization_id, link_kind, source_key, metadata)
  VALUES (v_id, 'locations', p_location_id, p_org, 'projection', p_location_id::text, '{}'::jsonb)
  ON CONFLICT (source_table, source_id) DO UPDATE SET canonical_place_id = EXCLUDED.canonical_place_id;
  RETURN v_id;
END $function$;
REVOKE ALL ON FUNCTION "public"."canonical_place_for_house"(p_location_id uuid, p_org uuid, p_name text, p_address text, p_key text, p_kind_hint text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."canonical_place_for_house"(p_location_id uuid, p_org uuid, p_name text, p_address text, p_key text, p_kind_hint text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."canonical_place_for_house"(p_location_id uuid, p_org uuid, p_name text, p_address text, p_key text, p_kind_hint text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."capture_accepted_quote_commercial_snapshot"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.status = 'accepted' and new.service_agreement_id is not null and old.status is distinct from 'accepted' then
    insert into public.quote_commercial_snapshots(
      quote_id,provider_organization_id,client_organization_id,tender_id,discount_schedule_id,
      currency,gst_rate,discount_pct,total_cost,subtotal_charge,discount_amount,gst_amount,total_charge,
      pricing_detail,accepted_at,accepted_by
    )
    values(
      new.id,new.provider_org_id,new.client_org_id,new.tender_id,new.discount_schedule_id,
      new.currency,new.gst_rate,new.discount_pct,new.total_cost,new.subtotal_charge,new.discount_amount,new.gst_amount,new.total_charge,
      jsonb_build_object(
        'quote_lines', coalesce((select jsonb_agg(jsonb_build_object('id',line.id,'kind',line.kind,'description',line.description,'quantity',line.quantity,'unit_cost',line.unit_cost,'unit_charge',line.unit_charge,'module_key',line.module_key,'site_id',line.site_id) order by line.line_order) from public.quote_lines line where line.quote_id = new.id), '[]'::jsonb),
        'proposal_modules', coalesce((select jsonb_agg(jsonb_build_object('module_key',module.module_key,'sla_minutes',module.sla_minutes,'service_window',module.service_window,'pricing_basis',module.pricing_basis,'rate_rule_id',module.rate_rule_id,'rate_rule_type',rule.rate_type,'rate_rule_amount',rule.amount) order by module.module_key) from public.quote_proposal_modules module left join public.rate_rules rule on rule.id = module.rate_rule_id where module.quote_id = new.id), '[]'::jsonb)
      ),
      coalesce(new.accepted_at, now()),coalesce(new.accepted_by, auth.uid())
    ) on conflict (quote_id) do nothing;
  end if;
  return new;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."capture_accepted_quote_commercial_snapshot"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."capture_accepted_quote_commercial_snapshot"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."capture_accepted_quote_commercial_snapshot"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."capture_field_place"(p_request_id uuid, p_provider_id uuid, p_client_id uuid, p_location_id uuid, p_expected_updated_at timestamp with time zone, p_place_kind text, p_name text, p_capture jsonb, p_map_confirmed boolean, p_parent_zone_id uuid DEFAULT NULL::uuid, p_target_site_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_actor uuid := auth.uid(); v_house public.locations%rowtype; v_zone public.location_zones%rowtype;
  v_site_id uuid; v_parent geometry; v_point geometry; v_circle geometry; v_raw geometry;
  v_time timestamptz; v_accuracy double precision; v_prior jsonb; v_request jsonb;
  v_result jsonb; v_anchor text; v_agreement_id uuid; v_created boolean := false; v_field jsonb;
  v_new_id uuid := gen_random_uuid();
BEGIN
  IF v_actor IS NULL OR NOT public.field_place_client_allowed(p_provider_id, p_client_id) THEN
    RAISE EXCEPTION 'Field place access requires an active role and confirmed operational client';
  END IF;
  IF p_request_id IS NULL OR p_map_confirmed IS DISTINCT FROM true OR p_place_kind NOT IN ('site', 'zone')
    OR p_place_kind IS NULL OR nullif(trim(p_name), '') IS NULL OR char_length(p_name) > 200 THEN
    RAISE EXCEPTION 'Choose a client, place type and name, then confirm the point on the map';
  END IF;
  IF jsonb_typeof(p_capture) IS DISTINCT FROM 'object'
    OR jsonb_typeof(p_capture->'lat') IS DISTINCT FROM 'number'
    OR jsonb_typeof(p_capture->'lng') IS DISTINCT FROM 'number'
    OR jsonb_typeof(p_capture->'accuracy') IS DISTINCT FROM 'number'
    OR jsonb_typeof(p_capture->'confirmed_lat') IS DISTINCT FROM 'number'
    OR jsonb_typeof(p_capture->'confirmed_lng') IS DISTINCT FROM 'number'
    OR jsonb_typeof(p_capture->'captured_at') IS DISTINCT FROM 'string' THEN
    RAISE EXCEPTION 'A complete GPS capture and confirmed map point are required';
  END IF;
  IF (p_capture->>'lat')::double precision NOT BETWEEN -90 AND 90
    OR (p_capture->>'confirmed_lat')::double precision NOT BETWEEN -90 AND 90
    OR (p_capture->>'lng')::double precision NOT BETWEEN -180 AND 180
    OR (p_capture->>'confirmed_lng')::double precision NOT BETWEEN -180 AND 180
    OR (p_capture->>'accuracy')::double precision NOT BETWEEN 0.01 AND 100000 THEN
    RAISE EXCEPTION 'GPS coordinates or accuracy are invalid';
  END IF;
  v_request := jsonb_build_object('client', p_client_id, 'location', p_location_id,
    'version', p_expected_updated_at, 'kind', p_place_kind, 'name', trim(p_name),
    'capture', p_capture, 'parent_zone', p_parent_zone_id, 'target_site', p_target_site_id);
  PERFORM pg_advisory_xact_lock(hashtextextended('field-place:' || p_provider_id || ':' || p_request_id, 0));
  SELECT metadata INTO v_prior FROM public.audit_log WHERE organization_id = p_provider_id
    AND actor_user_id = v_actor AND action = 'field_place_verified'
    AND metadata->>'request_id' = p_request_id::text LIMIT 1;
  IF FOUND THEN
    IF v_prior->'request' IS DISTINCT FROM v_request THEN RAISE EXCEPTION 'Retry contains changed field details'; END IF;
    RETURN v_prior->'result';
  END IF;
  v_time := (p_capture->>'captured_at')::timestamptz;
  IF v_time < clock_timestamp() - interval '10 minutes' OR v_time > clock_timestamp() + interval '1 minute' THEN
    RAISE EXCEPTION 'GPS capture is stale. Capture your position again before verifying';
  END IF;
  v_accuracy := (p_capture->>'accuracy')::double precision;
  v_raw := ST_SetSRID(ST_MakePoint((p_capture->>'lng')::double precision, (p_capture->>'lat')::double precision), 4326);
  v_point := ST_SetSRID(ST_MakePoint((p_capture->>'confirmed_lng')::double precision, (p_capture->>'confirmed_lat')::double precision), 4326);
  v_circle := ST_Multi(ST_Buffer(v_point::geography, 10)::geometry);
  v_agreement_id := public.field_place_agreement_id(p_provider_id, p_client_id);
  IF p_location_id IS NULL THEN
    IF p_parent_zone_id IS NOT NULL OR p_target_site_id IS NOT NULL THEN RAISE EXCEPTION 'Select the existing location before its site or zone'; END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended('service-place-name:' || p_client_id || ':' || lower(trim(p_name)), 0));
    IF EXISTS (SELECT 1 FROM public.locations WHERE organization_id = p_client_id AND lower(trim(name)) = lower(trim(p_name))) THEN
      RAISE EXCEPTION 'A location with this name exists for the client. Select it to verify or update it';
    END IF;
    INSERT INTO public.locations(id, organization_id, name, created_by, client_request_id, canonical_place_id)
      VALUES (v_new_id, p_client_id, trim(p_name), v_actor, p_request_id,
        public.canonical_place_for_house(v_new_id, p_client_id, trim(p_name), NULL, NULL, p_place_kind))
      RETURNING * INTO v_house;
    v_created := true;
    IF p_place_kind = 'site' THEN
      INSERT INTO public.client_sites(client_organization_id, location_id, name, site_type, site_origin, service_agreement_id,
        boundary_status, boundary_verification, center_point, metadata)
      VALUES (p_client_id, v_house.id, trim(p_name), 'other', 'adhoc', v_agreement_id, 'provisional', 'unverified', v_point,
        jsonb_build_object('created_via', 'officer_field_capture')) RETURNING id INTO v_site_id;
    ELSE
      INSERT INTO public.location_zones(organization_id, location_id, name, zone_type, module_key, rule_type,
        boundary_status, boundary_verification)
      VALUES (p_client_id, v_house.id, trim(p_name), 'general', 'patrol', 'unrestricted', 'provisional', 'unverified')
      RETURNING id INTO p_parent_zone_id;
    END IF;
  ELSE
    SELECT * INTO v_house FROM public.locations WHERE id = p_location_id AND organization_id = p_client_id FOR UPDATE;
    IF NOT FOUND OR p_expected_updated_at IS NULL OR v_house.updated_at IS DISTINCT FROM p_expected_updated_at THEN
      RAISE EXCEPTION 'Location changed or is not available. Reload before verifying';
    END IF;
    IF p_parent_zone_id IS NOT NULL THEN
      IF p_target_site_id IS NOT NULL THEN RAISE EXCEPTION 'Select one site or zone boundary to verify'; END IF;
      SELECT boundary INTO v_parent FROM public.location_zones
        WHERE id = p_parent_zone_id AND location_id = v_house.id AND organization_id = p_client_id
          AND NOT is_verification_point FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION 'The parent zone does not belong to this location'; END IF;
    ELSE
      IF p_target_site_id IS NULL AND (SELECT count(*) FROM public.client_sites WHERE location_id = v_house.id) > 1 THEN
        RAISE EXCEPTION 'This location has several sites. Select the intended boundary';
      END IF;
      SELECT id, boundary INTO v_site_id, v_parent FROM public.client_sites
        WHERE location_id = v_house.id AND (p_target_site_id IS NULL OR id = p_target_site_id)
        ORDER BY created_at LIMIT 1 FOR UPDATE;
      IF p_target_site_id IS NOT NULL AND NOT FOUND THEN RAISE EXCEPTION 'The site does not belong to this location'; END IF;
      IF v_site_id IS NULL AND EXISTS (SELECT 1 FROM public.location_zones WHERE location_id = v_house.id AND NOT is_verification_point) THEN
        RAISE EXCEPTION 'Select the zone boundary for this location';
      END IF;
    END IF;
    IF v_parent IS NOT NULL THEN
      IF NOT ST_IsValid(v_parent) THEN RAISE EXCEPTION 'The existing boundary is invalid. Ask an administrator to repair it'; END IF;
      IF NOT ST_Covers(v_parent, v_point) THEN RAISE EXCEPTION 'Place the verification point inside the selected boundary'; END IF;
    END IF;
    UPDATE public.locations SET name = trim(p_name), updated_at = clock_timestamp()
      WHERE id = v_house.id RETURNING * INTO v_house;
    IF v_site_id IS NOT NULL THEN
      UPDATE public.client_sites SET name = trim(p_name), center_point = coalesce(center_point, v_point),
        configuration_version = configuration_version + 1,
        service_agreement_id = coalesce(service_agreement_id, v_agreement_id),
        metadata = coalesce(metadata, '{}') || jsonb_build_object('field_place_managed', true)
        WHERE id = v_site_id;
    ELSIF p_parent_zone_id IS NOT NULL THEN
      UPDATE public.location_zones SET name = trim(p_name), center_point = coalesce(center_point, v_point),
        configuration_version = configuration_version + 1 WHERE id = p_parent_zone_id;
    END IF;
  END IF;
  v_anchor := coalesce('zone:' || p_parent_zone_id, 'site:' || v_site_id, 'location:' || v_house.id);
  v_field := p_capture || jsonb_build_object('verified_at', clock_timestamp(), 'verified_by', v_actor,
    'provider_id', p_provider_id, 'radius_m', 10, 'method', CASE WHEN ST_Equals(v_raw, v_point)
      THEN 'gps_and_map_confirmation' ELSE 'gps_with_manual_map_correction' END);
  SELECT * INTO v_zone FROM public.location_zones
    WHERE location_id = v_house.id AND is_verification_point AND metadata->>'verification_anchor' = v_anchor FOR UPDATE;
  IF NOT FOUND THEN
    INSERT INTO public.location_zones(organization_id, location_id, name, zone_type, module_key, rule_type,
      is_verification_point, boundary, center_point, radius_meters, boundary_status,
      boundary_verification, boundary_verified_by, boundary_verified_at, metadata, parent_zone_id)
    VALUES (p_client_id, v_house.id, trim(p_name) || ' - verification point',
      'general', 'patrol', 'unrestricted', true, v_circle, v_point, 10, 'provisional', 'verified', v_actor,
      clock_timestamp(), jsonb_build_object('verification_anchor', v_anchor, 'field_capture', v_field), p_parent_zone_id)
    RETURNING * INTO v_zone;
  ELSE
    UPDATE public.location_zones SET name = trim(p_name) || ' - verification point', boundary = v_circle, is_active = true, center_point = v_point, radius_meters = 10,
      boundary_verification = 'verified', boundary_verified_by = v_actor, boundary_verified_at = clock_timestamp(),
      metadata = metadata || jsonb_build_object('field_capture', v_field), configuration_version = configuration_version + 1
      WHERE id = v_zone.id RETURNING * INTO v_zone;
  END IF;
  INSERT INTO public.geofence_boundary_history(entity_type, entity_id, boundary, boundary_source, verification_state,
    verified_by, verified_at, changed_by, changed_via, change_reason, version)
  VALUES ('location_zone', v_zone.id, v_circle, 'officer_gps', 'verified', v_actor, clock_timestamp(), v_actor,
    'verification', 'Officer portal: 10 m reference point confirmed on map; existing perimeter preserved', public._gbh_next_version('location_zone', v_zone.id));
  IF v_agreement_id IS NOT NULL THEN
    IF p_parent_zone_id IS NOT NULL THEN
      INSERT INTO public.service_agreement_locations(service_agreement_id, zone_id, status)
        SELECT v_agreement_id, p_parent_zone_id, 'active'
        WHERE NOT EXISTS (SELECT 1 FROM public.service_agreement_locations WHERE service_agreement_id = v_agreement_id AND zone_id = p_parent_zone_id);
    END IF;
    IF v_site_id IS NOT NULL THEN
      INSERT INTO public.service_agreement_locations(service_agreement_id, site_id, status)
        SELECT v_agreement_id, v_site_id, 'active'
        WHERE NOT EXISTS (SELECT 1 FROM public.service_agreement_locations WHERE service_agreement_id = v_agreement_id AND site_id = v_site_id);
    END IF;
  END IF;
  v_result := jsonb_build_object('location_id', v_house.id, 'site_id', v_site_id, 'zone_id', v_zone.id,
    'created', v_created, 'radius_m', 10, 'verified_at', v_zone.boundary_verified_at, 'updated_at', v_house.updated_at);
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
    VALUES (p_provider_id, v_actor, 'field_place_verified', 'location_zones', v_zone.id,
      jsonb_build_object('request_id', p_request_id, 'request', v_request, 'result', v_result, 'field_capture', v_field));
  RETURN v_result;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."capture_field_place"(p_request_id uuid, p_provider_id uuid, p_client_id uuid, p_location_id uuid, p_expected_updated_at timestamp with time zone, p_place_kind text, p_name text, p_capture jsonb, p_map_confirmed boolean, p_parent_zone_id uuid, p_target_site_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."capture_field_place"(p_request_id uuid, p_provider_id uuid, p_client_id uuid, p_location_id uuid, p_expected_updated_at timestamp with time zone, p_place_kind text, p_name text, p_capture jsonb, p_map_confirmed boolean, p_parent_zone_id uuid, p_target_site_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."capture_field_place"(p_request_id uuid, p_provider_id uuid, p_client_id uuid, p_location_id uuid, p_expected_updated_at timestamp with time zone, p_place_kind text, p_name text, p_capture jsonb, p_map_confirmed boolean, p_parent_zone_id uuid, p_target_site_id uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."capture_observation_effective_rule_snapshot"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_ctx jsonb := coalesce(NEW.geofence_context, '{}'::jsonb);
  v_jur_id uuid := CASE WHEN NULLIF(v_ctx->>'governing_jurisdiction_id', '') IS NOT NULL THEN (v_ctx->>'governing_jurisdiction_id')::uuid ELSE NULL END;
  v_jur_name text := NULLIF(v_ctx->>'governing_jurisdiction_name', '');
  v_effective jsonb := coalesce(v_ctx->'effective_rules', '{}'::jsonb);
  v_status text := coalesce(NULLIF(v_ctx->>'resolution_status', ''), 'outside_all_geofences');
BEGIN
  IF NEW.module_key IS NULL OR NULLIF(trim(NEW.module_key), '') IS NULL THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.effective_rule_snapshots (
    organization_id,
    module_key,
    governing_jurisdiction_id,
    governing_jurisdiction_name,
    matched_zone_id,
    matched_site_id,
    matched_location_id,
    effective_rules,
    resolution_status,
    source_event_table,
    source_event_id,
    captured_at
  ) VALUES (
    NEW.organization_id,
    NEW.module_key,
    v_jur_id,
    v_jur_name,
    NEW.zone_id,
    NEW.site_id,
    NEW.location_id,
    v_effective,
    v_status,
    'observations',
    NEW.id,
    NEW.observed_at
  )
  ON CONFLICT (source_event_table, source_event_id) DO UPDATE
    SET organization_id = EXCLUDED.organization_id,
        module_key = EXCLUDED.module_key,
        governing_jurisdiction_id = EXCLUDED.governing_jurisdiction_id,
        governing_jurisdiction_name = EXCLUDED.governing_jurisdiction_name,
        matched_zone_id = EXCLUDED.matched_zone_id,
        matched_site_id = EXCLUDED.matched_site_id,
        matched_location_id = EXCLUDED.matched_location_id,
        effective_rules = EXCLUDED.effective_rules,
        resolution_status = EXCLUDED.resolution_status,
        captured_at = EXCLUDED.captured_at;

  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."capture_observation_effective_rule_snapshot"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."capture_observation_effective_rule_snapshot"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."capture_observation_effective_rule_snapshot"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."capture_observation_effective_rule_snapshot"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."cctv_accuracy_summary"(p_organization_id uuid, p_since timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_since timestamptz := coalesce(p_since, clock_timestamp() - interval '90 days');
  v_groups jsonb;
  v_missed jsonb;
BEGIN
  IF NOT (coalesce(auth.role(), '') = 'service_role' OR session_user IN ('postgres', 'supabase_admin')
          OR (auth.uid() IS NOT NULL AND coalesce(public.org_access_allowed(p_organization_id), false))) THEN
    RAISE EXCEPTION 'CCTV review access denied';
  END IF;
  WITH observed AS (
    SELECT o.entity_kind,
           coalesce(o.attributes->>'engine_version', 'legacy') AS engine_version,
           coalesce(o.attributes->>'detector_model', 'unreported') AS detector_model,
           coalesce(o.attributes->>'review_candidate_basis', 'unrecorded') AS review_basis,
           CASE
             WHEN o.model_confidence IS NULL THEN 'unknown'
             WHEN o.model_confidence < 0.5 THEN '0.00-0.49'
             WHEN o.model_confidence < 0.7 THEN '0.50-0.69'
             WHEN o.model_confidence < 0.85 THEN '0.70-0.84'
             ELSE '0.85-1.00'
           END AS confidence_band,
           o.review_state
      FROM public.cctv_entity_observations o
     WHERE o.organization_id = p_organization_id
       AND o.created_at >= v_since
       AND o.review_state <> 'superseded'
  ), grouped AS (
    SELECT entity_kind, engine_version, detector_model, review_basis, confidence_band,
           count(*) AS total,
           count(*) FILTER (WHERE review_state = 'accepted') AS accepted,
           count(*) FILTER (WHERE review_state = 'rejected') AS rejected,
           count(*) FILTER (WHERE review_state IN ('uncertain', 'needs_more_context')) AS inconclusive,
           count(*) FILTER (WHERE review_state = 'unreviewed') AS pending
      FROM observed
     GROUP BY entity_kind, engine_version, detector_model, review_basis, confidence_band
  )
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'entity_kind', entity_kind,
           'engine_version', engine_version,
           'detector_model', detector_model,
           'review_basis', review_basis,
           'confidence_band', confidence_band,
           'total', total,
           'accepted', accepted,
           'rejected', rejected,
           'inconclusive', inconclusive,
           'pending', pending,
           'decided', accepted + rejected,
           'precision', CASE WHEN accepted + rejected > 0 THEN round(accepted::numeric / (accepted + rejected), 4) END,
           'precision_lower_bound', CASE WHEN accepted + rejected > 0 THEN round((
               (accepted::numeric / (accepted + rejected)) + 3.8416 / (2 * (accepted + rejected))
               - 1.96 * sqrt(((accepted::numeric / (accepted + rejected)) * (1 - accepted::numeric / (accepted + rejected))
                              + 3.8416 / (4 * (accepted + rejected))) / (accepted + rejected))
             ) / (1 + 3.8416 / (accepted + rejected)), 4) END,
           'calibrated', accepted + rejected >= 30
         ) ORDER BY entity_kind, engine_version, detector_model, review_basis, confidence_band), '[]'::jsonb)
    INTO v_groups
    FROM grouped;
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'entity_kind', entity_kind,
           'engine_version', engine_version,
           'open', open,
           'confirmed_missed', confirmed_missed,
           'not_missed', not_missed
         ) ORDER BY entity_kind, engine_version), '[]'::jsonb)
    INTO v_missed
    FROM (
      SELECT entity_kind, coalesce(engine_version, 'legacy') AS engine_version,
             count(*) FILTER (WHERE state = 'open') AS open,
             count(*) FILTER (WHERE state = 'confirmed_missed') AS confirmed_missed,
             count(*) FILTER (WHERE state = 'not_missed') AS not_missed
        FROM public.cctv_missed_detection_reports
       WHERE organization_id = p_organization_id AND reported_at >= v_since
       GROUP BY entity_kind, coalesce(engine_version, 'legacy')
    ) missed;
  RETURN jsonb_build_object(
    'organization_id', p_organization_id,
    'since', v_since,
    'calibration_minimum_decisions', 30,
    'groups', v_groups,
    'missed_detections', v_missed
  );
END;
$function$;
COMMENT ON FUNCTION "public"."cctv_accuracy_summary"(p_organization_id uuid, p_since timestamp with time zone) IS 'Precision of CCTV sightings per entity kind, engine, detector, review basis and confidence band from human decisions only, with the Wilson 95% lower bound. A group is calibrated at 30 decisions. Includes reviewer-reported missed detections for recall.';
REVOKE ALL ON FUNCTION "public"."cctv_accuracy_summary"(p_organization_id uuid, p_since timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."cctv_accuracy_summary"(p_organization_id uuid, p_since timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."cctv_accuracy_summary"(p_organization_id uuid, p_since timestamp with time zone) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."cctv_accuracy_summary"(p_organization_id uuid, p_since timestamp with time zone) TO "service_role";

