CREATE OR REPLACE FUNCTION "public"."cctv_bbox_iou"(p_left jsonb, p_right jsonb)
 RETURNS double precision
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
AS $function$
DECLARE
  lx double precision; ly double precision; lw double precision; lh double precision;
  rx double precision; ry double precision; rw double precision; rh double precision;
  overlap_w double precision; overlap_h double precision; intersection double precision;
BEGIN
  IF jsonb_typeof(p_left) IS DISTINCT FROM 'object' OR jsonb_typeof(p_right) IS DISTINCT FROM 'object' THEN RETURN 0; END IF;
  lx := (p_left->>'x')::double precision; ly := (p_left->>'y')::double precision;
  lw := (p_left->>'width')::double precision; lh := (p_left->>'height')::double precision;
  rx := (p_right->>'x')::double precision; ry := (p_right->>'y')::double precision;
  rw := (p_right->>'width')::double precision; rh := (p_right->>'height')::double precision;
  IF lx IS NULL OR ly IS NULL OR rx IS NULL OR ry IS NULL OR least(lw, lh, rw, rh) IS NULL OR least(lw, lh, rw, rh) <= 0 THEN RETURN 0; END IF;
  overlap_w := least(lx + lw, rx + rw) - greatest(lx, rx);
  overlap_h := least(ly + lh, ry + rh) - greatest(ly, ry);
  IF overlap_w <= 0 OR overlap_h <= 0 THEN RETURN 0; END IF;
  intersection := overlap_w * overlap_h;
  RETURN intersection / (lw * lh + rw * rh - intersection);
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
  RETURN 0;
END;
$function$;
COMMENT ON FUNCTION "public"."cctv_bbox_iou"(p_left jsonb, p_right jsonb) IS 'Intersection over union of two CCTV {x,y,width,height} boxes. Returns 0 for missing or malformed boxes.';
REVOKE ALL ON FUNCTION "public"."cctv_bbox_iou"(p_left jsonb, p_right jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."cctv_bbox_iou"(p_left jsonb, p_right jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."cctv_bbox_iou"(p_left jsonb, p_right jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."cctv_bbox_is_stationary"(p_left jsonb, p_right jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
AS $function$
DECLARE
  lx double precision; ly double precision; lw double precision; lh double precision;
  rx double precision; ry double precision; rw double precision; rh double precision;
  scale double precision;
BEGIN
  IF jsonb_typeof(p_left) <> 'object' OR jsonb_typeof(p_right) <> 'object' THEN RETURN false; END IF;
  lx := (p_left->>'x')::double precision; ly := (p_left->>'y')::double precision;
  lw := (p_left->>'width')::double precision; lh := (p_left->>'height')::double precision;
  rx := (p_right->>'x')::double precision; ry := (p_right->>'y')::double precision;
  rw := (p_right->>'width')::double precision; rh := (p_right->>'height')::double precision;
  IF least(lw, lh, rw, rh) <= 0 THEN RETURN false; END IF;
  scale := greatest(lw, lh, rw, rh);
  RETURN sqrt(power((lx + lw / 2) - (rx + rw / 2), 2) + power((ly + lh / 2) - (ry + rh / 2), 2)) <= scale * 0.30
    AND lw / rw BETWEEN 0.65 AND 1.55
    AND lh / rh BETWEEN 0.65 AND 1.55;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
  RETURN false;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."cctv_bbox_is_stationary"(p_left jsonb, p_right jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."cctv_bbox_is_stationary"(p_left jsonb, p_right jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."cctv_bbox_is_stationary"(p_left jsonb, p_right jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."cctv_biometric_governance"(p_organization_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_result jsonb;
BEGIN
  IF auth.uid() IS NULL AND auth.role() <> 'service_role' AND session_user NOT IN ('postgres', 'supabase_admin') THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF NOT public.org_access_allowed(p_organization_id) THEN RAISE EXCEPTION 'CCTV governance access denied'; END IF;
  SELECT jsonb_build_object(
    'organization_id', p_organization_id,
    'live_templates', count(*) FILTER (WHERE o.face_vec IS NOT NULL OR o.appearance_vec IS NOT NULL),
    'live_face_templates', count(*) FILTER (WHERE o.face_vec IS NOT NULL),
    'oldest_live_template_at', min(o.created_at) FILTER (WHERE o.face_vec IS NOT NULL OR o.appearance_vec IS NOT NULL),
    'expired_templates', count(*) FILTER (WHERE o.attributes ? 'biometric_templates_expired_at'),
    'rejected_still_holding_templates', count(*) FILTER (WHERE o.review_state = 'rejected' AND (o.face_vec IS NOT NULL OR o.appearance_vec IS NOT NULL)),
    'last_expiry_run_at', (SELECT max(a.created_at) FROM public.audit_log a WHERE a.organization_id = p_organization_id AND a.action = 'cctv_biometric_templates_expired'),
    'purpose', 'Templates are used only to suggest same-or-similar sightings within this organisation; identity is always a reviewer decision.',
    'default_retention', '90 days'
  ) INTO v_result
  FROM public.cctv_entity_observations o
  WHERE o.organization_id = p_organization_id AND o.entity_kind = 'person';
  RETURN v_result;
END $function$;
COMMENT ON FUNCTION "public"."cctv_biometric_governance"(p_organization_id uuid) IS 'Org-scoped biometric holdings readout: live/expired template counts, oldest live template, rejected sightings still holding templates, last expiry run, stated purpose and default retention.';
REVOKE ALL ON FUNCTION "public"."cctv_biometric_governance"(p_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."cctv_biometric_governance"(p_organization_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."cctv_biometric_governance"(p_organization_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."cctv_biometric_governance"(p_organization_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."cctv_compact_event_array"(p_job_id uuid, p_events jsonb, p_kind text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT coalesce(jsonb_agg(
    (event.value - ARRAY['thumbnail', 'face_embedding', 'appearance_embedding']::text[])
    || CASE WHEN preview.thumbnail IS NOT NULL THEN jsonb_build_object('thumbnail', preview.thumbnail) ELSE '{}'::jsonb END
    ORDER BY event.ordinality
  ), '[]'::jsonb)
  FROM jsonb_array_elements(CASE WHEN jsonb_typeof(p_events) = 'array' THEN p_events ELSE '[]'::jsonb END) WITH ORDINALITY event(value, ordinality)
  LEFT JOIN LATERAL (
    SELECT observation.thumbnail
    FROM public.cctv_entity_observations observation
    WHERE observation.inference_job_id = p_job_id
      AND observation.review_state <> 'superseded'
      AND observation.entity_kind = CASE WHEN p_kind IN ('person', 'face') THEN 'person' ELSE p_kind END
      AND (
        observation.source_event_id = event.value->>'event_id'
        OR (p_kind = 'face' AND observation.attributes->>'face_event_id' = event.value->>'event_id')
      )
    ORDER BY (observation.source_event_id = event.value->>'event_id') DESC, observation.observed_at
    LIMIT 1
  ) preview ON true
$function$;
REVOKE ALL ON FUNCTION "public"."cctv_compact_event_array"(p_job_id uuid, p_events jsonb, p_kind text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."cctv_compact_event_array"(p_job_id uuid, p_events jsonb, p_kind text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."cctv_compact_event_array"(p_job_id uuid, p_events jsonb, p_kind text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."cctv_compact_motion_result"(p_job_id uuid, p_result jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_result jsonb := coalesce(p_result, '{}'::jsonb);
  v_segments jsonb;
  v_events jsonb := coalesce(p_result->'consolidated_events', '{}'::jsonb);
  v_keyframes jsonb;
BEGIN
  SELECT coalesce(jsonb_agg(
    (segment.value - 'frames') || jsonb_build_object('frame_count', coalesce(jsonb_array_length(segment.value->'frames'), 0))
    ORDER BY segment.ordinality
  ), '[]'::jsonb)
  INTO v_segments
  FROM jsonb_array_elements(CASE WHEN jsonb_typeof(p_result->'motion_segments') = 'array' THEN p_result->'motion_segments' ELSE '[]'::jsonb END) WITH ORDINALITY segment(value, ordinality);

  SELECT coalesce(jsonb_agg(frame.value - 'thumbnail' ORDER BY frame.ordinality), '[]'::jsonb)
  INTO v_keyframes
  FROM jsonb_array_elements(CASE WHEN jsonb_typeof(v_events->'keyframes') = 'array' THEN v_events->'keyframes' ELSE '[]'::jsonb END) WITH ORDINALITY frame(value, ordinality);

  v_events := jsonb_set(v_events, '{vehicle_events}', public.cctv_compact_event_array(p_job_id, v_events->'vehicle_events', 'vehicle'), true);
  v_events := jsonb_set(v_events, '{person_events}', public.cctv_compact_event_array(p_job_id, v_events->'person_events', 'person'), true);
  v_events := jsonb_set(v_events, '{face_events}', public.cctv_compact_event_array(p_job_id, v_events->'face_events', 'face'), true);
  v_events := jsonb_set(v_events, '{animal_events}', public.cctv_compact_event_array(p_job_id, v_events->'animal_events', 'animal'), true);
  v_events := jsonb_set(v_events, '{keyframes}', v_keyframes, true);
  v_result := jsonb_set(v_result, '{motion_segments}', v_segments, true);
  v_result := jsonb_set(v_result, '{consolidated_events}', v_events, true);
  RETURN v_result || jsonb_build_object('storage_profile', 'review_event_summary_v1');
END;
$function$;
REVOKE ALL ON FUNCTION "public"."cctv_compact_motion_result"(p_job_id uuid, p_result jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."cctv_compact_motion_result"(p_job_id uuid, p_result jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."cctv_compact_motion_result"(p_job_id uuid, p_result jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."cctv_evidence_custody"(p_evidence_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_evidence public.evidence_items%rowtype;
  v_events jsonb;
BEGIN
  IF auth.uid() IS NULL AND auth.role() <> 'service_role' AND session_user NOT IN ('postgres', 'supabase_admin') THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT * INTO v_evidence FROM public.evidence_items WHERE id = p_evidence_id;
  IF v_evidence.id IS NULL THEN RAISE EXCEPTION 'Recording not found'; END IF;
  IF NOT public.org_access_allowed(v_evidence.organization_id) THEN RAISE EXCEPTION 'CCTV custody access denied'; END IF;

  SELECT coalesce(jsonb_agg(event ORDER BY (event->>'at')::timestamptz), '[]'::jsonb) INTO v_events
  FROM (
    SELECT jsonb_build_object('at', a.created_at, 'kind', a.action, 'actor_user_id', a.actor_user_id,
             'detail', CASE a.action
               WHEN 'cctv_evidence_locked' THEN jsonb_build_object('reason', a.metadata->>'reason', 'sha256_hash', a.metadata->>'sha256_hash')
               WHEN 'cctv_bookmark_created' THEN jsonb_build_object('incident_id', a.metadata->>'incident_id', 'bookmark_at', a.metadata->>'bookmark_at', 'severity', a.metadata->>'severity')
               WHEN 'cctv_evidence_integrity_verified' THEN jsonb_build_object('checked_by', a.metadata->>'checked_by', 'check_count', a.metadata->>'check_count')
               WHEN 'cctv_evidence_integrity_mismatch' THEN jsonb_build_object('checked_by', a.metadata->>'checked_by', 'observed_sha256', a.metadata->>'observed_sha256', 'expected_sha256', a.metadata->>'expected_sha256')
               ELSE '{}'::jsonb END) AS event
      FROM public.audit_log a
     WHERE a.organization_id = v_evidence.organization_id
       AND ((a.target_table = 'evidence_items' AND a.target_id = v_evidence.id)
            OR (a.action = 'cctv_bookmark_created' AND (a.metadata->>'evidence_item_id')::uuid = v_evidence.id))
    UNION ALL
    SELECT jsonb_build_object('at', r.generated_at, 'kind', 'cctv_report_issued', 'actor_user_id', r.generated_by,
             'detail', jsonb_build_object('receipt_id', r.id, 'batch_id', r.batch_id, 'observation_count', r.observation_count, 'sha256', r.sha256))
      FROM public.cctv_report_receipts r
     WHERE r.evidence_item_id = v_evidence.id
  ) trail;

  RETURN jsonb_strip_nulls(jsonb_build_object(
    'evidence_item_id', v_evidence.id,
    'storage_path', v_evidence.storage_path,
    'captured_at', v_evidence.captured_at,
    'sha256_hash', v_evidence.sha256_hash,
    'source_size_bytes', (v_evidence.metadata->>'source_size_bytes')::bigint,
    'source_hashed_at', v_evidence.metadata->>'source_hashed_at',
    'is_court_ready', v_evidence.is_court_ready,
    'locked_at', v_evidence.locked_at,
    'lock', v_evidence.metadata->'evidence_lock',
    'retention_hold', v_evidence.retention_hold,
    'retention_reason', v_evidence.retention_reason,
    'integrity', v_evidence.metadata->'integrity',
    'events', v_events
  ));
END $function$;
COMMENT ON FUNCTION "public"."cctv_evidence_custody"(p_evidence_id uuid) IS 'Org-scoped custody record for one CCTV recording: hash and provenance, lock, retention hold, latest integrity check, and the ordered trail of lock / bookmark / integrity / export events.';
