CREATE OR REPLACE FUNCTION "public"."cctv_inference_frames_used_today"(p_organization_id uuid)
 RETURNS bigint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT coalesce(sum((a.metadata->>'frames_sent')::bigint), 0)
    FROM public.audit_log a
   WHERE a.organization_id = p_organization_id AND a.action = 'cctv_inference_usage_recorded'
     AND a.created_at >= date_trunc('day', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'
$function$;
REVOKE ALL ON FUNCTION "public"."cctv_inference_frames_used_today"(p_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."cctv_inference_frames_used_today"(p_organization_id uuid) TO "postgres";
