CREATE OR REPLACE FUNCTION "public"."cctv_inference_usage"(p_organization_id uuid, p_days integer DEFAULT 14)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_budget public.cctv_inference_budgets%rowtype; v_days jsonb; v_deferred integer; v_used bigint;
BEGIN
  IF auth.uid() IS NULL AND auth.role() <> 'service_role' AND session_user NOT IN ('postgres', 'supabase_admin') THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF NOT public.org_access_allowed(p_organization_id) THEN RAISE EXCEPTION 'CCTV usage access denied'; END IF;
  SELECT * INTO v_budget FROM public.cctv_inference_budgets WHERE organization_id = p_organization_id;
  SELECT coalesce(jsonb_agg(jsonb_build_object('day', day, 'jobs', jobs, 'frames_sent', frames_sent, 'gpu_calls', gpu_calls, 'gpu_ms', gpu_ms) ORDER BY day), '[]'::jsonb) INTO v_days
  FROM (
    SELECT (a.created_at AT TIME ZONE 'UTC')::date AS day, count(*) AS jobs,
           sum((a.metadata->>'frames_sent')::bigint) AS frames_sent, sum((a.metadata->>'gpu_calls')::bigint) AS gpu_calls, sum((a.metadata->>'gpu_ms')::bigint) AS gpu_ms
      FROM public.audit_log a
     WHERE a.organization_id = p_organization_id AND a.action = 'cctv_inference_usage_recorded'
       AND a.created_at >= (date_trunc('day', now() AT TIME ZONE 'UTC') - make_interval(days => greatest(0, coalesce(p_days, 14) - 1))) AT TIME ZONE 'UTC'
     GROUP BY 1
  ) d;
  SELECT count(*) INTO v_deferred FROM public.inference_jobs j
   WHERE j.organization_id = p_organization_id AND j.domain = 'video_motion' AND j.status = 'queued' AND j.stage = 'deferred' AND j.lease_expires_at > clock_timestamp();
  v_used := public.cctv_inference_frames_used_today(p_organization_id);
  RETURN jsonb_build_object(
    'organization_id', p_organization_id,
    'daily_frame_budget', coalesce(v_budget.daily_frame_budget, public.cctv_inference_default_daily_frames()),
    'budget_is_default', v_budget.organization_id IS NULL,
    'budget_reason', v_budget.reason,
    'frames_used_today', v_used,
    'exhausted', v_used >= coalesce(v_budget.daily_frame_budget, public.cctv_inference_default_daily_frames()),
    'deferred_jobs', v_deferred,
    'days', v_days);
END $function$;
COMMENT ON FUNCTION "public"."cctv_inference_usage"(p_organization_id uuid, p_days integer) IS 'Org-scoped inference metering: per-day frames sent / GPU calls / GPU ms, the daily frame budget (default or set), today''s use, and jobs currently deferred for budget.';
REVOKE ALL ON FUNCTION "public"."cctv_inference_usage"(p_organization_id uuid, p_days integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."cctv_inference_usage"(p_organization_id uuid, p_days integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."cctv_inference_usage"(p_organization_id uuid, p_days integer) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."cctv_inference_usage"(p_organization_id uuid, p_days integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."cctv_jsonb_to_vector"(p_embedding jsonb, p_dims integer)
 RETURNS vector
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE v_arr real[];
BEGIN
  IF p_embedding IS NULL OR jsonb_typeof(p_embedding) <> 'array' OR jsonb_array_length(p_embedding) <> p_dims THEN RETURN NULL; END IF;
  SELECT array_agg(t.x::real ORDER BY t.ord) INTO v_arr FROM jsonb_array_elements_text(p_embedding) WITH ORDINALITY AS t(x, ord);
  RETURN v_arr::public.vector;
EXCEPTION WHEN OTHERS THEN
  RETURN NULL;
END $function$;
REVOKE ALL ON FUNCTION "public"."cctv_jsonb_to_vector"(p_embedding jsonb, p_dims integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."cctv_jsonb_to_vector"(p_embedding jsonb, p_dims integer) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."cctv_jsonb_to_vector"(p_embedding jsonb, p_dims integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."cctv_jsonb_to_vector"(p_embedding jsonb, p_dims integer) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."cctv_jsonb_to_vector"(p_embedding jsonb, p_dims integer) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."cctv_jsonb_to_vector"(p_embedding jsonb, p_dims integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."cctv_observation_payload_guard"()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.portfolio_candidates := public.cctv_strip_candidate_images(NEW.portfolio_candidates);
  IF NEW.thumbnail IS NOT NULL AND octet_length(NEW.thumbnail) > 80000 THEN
    NEW.attributes := coalesce(NEW.attributes, '{}'::jsonb) || jsonb_build_object(
      'thumbnail_omitted', 'payload_over_80kb',
      'thumbnail_original_bytes', octet_length(NEW.thumbnail)
    );
    NEW.thumbnail := NULL;
  END IF;
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."cctv_observation_payload_guard"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."cctv_observation_payload_guard"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."cctv_observation_payload_guard"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."cctv_observation_payload_guard"() TO "anon";
GRANT EXECUTE ON FUNCTION "public"."cctv_observation_payload_guard"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."cctv_observation_payload_guard"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."cctv_strip_candidate_images"(p_candidates jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
AS $function$
  SELECT CASE WHEN jsonb_typeof(p_candidates) = 'array'
    THEN coalesce(jsonb_agg(candidate - 'thumbnail'), '[]'::jsonb)
    ELSE '[]'::jsonb END
  FROM jsonb_array_elements(CASE WHEN jsonb_typeof(p_candidates) = 'array' THEN p_candidates ELSE '[]'::jsonb END) candidate
$function$;
REVOKE ALL ON FUNCTION "public"."cctv_strip_candidate_images"(p_candidates jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."cctv_strip_candidate_images"(p_candidates jsonb) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."cctv_strip_candidate_images"(p_candidates jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."cctv_strip_candidate_images"(p_candidates jsonb) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."cctv_strip_candidate_images"(p_candidates jsonb) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."cctv_strip_candidate_images"(p_candidates jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."charge_catalog_group_members"(p_root uuid)
 RETURNS SETOF uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH tree AS (
    SELECT unnest(public.get_descendant_organizations(p_root)) AS id
  )
  SELECT id FROM tree
  UNION
  SELECT agreement.client_organization_id
  FROM public.service_agreements agreement
  JOIN tree ON tree.id = agreement.provider_organization_id
  WHERE agreement.client_organization_id IS NOT NULL
    AND agreement.agreement_type = 'operational'
    AND (agreement.ends_on IS NULL OR agreement.ends_on >= current_date);
$function$;
REVOKE ALL ON FUNCTION "public"."charge_catalog_group_members"(p_root uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."charge_catalog_group_members"(p_root uuid) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."check_invite_rate_limit"(p_caller_id uuid, p_target_org_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_caller_count integer;
  v_org_count    integer;
begin
  -- Per-caller: max 5 invites in the last 5 minutes
  select count(*) into v_caller_count
    from invite_rate_log
   where caller_id = p_caller_id
     and attempted_at > now() - interval '5 minutes';

  if v_caller_count >= 5 then
    return false;
  end if;

  -- Per-target-org: max 1 invite in the last 2 minutes
  select count(*) into v_org_count
    from invite_rate_log
   where target_org_id = p_target_org_id
     and attempted_at > now() - interval '2 minutes';

  if v_org_count >= 1 then
    return false;
  end if;

  -- Allowed — record the attempt
  insert into invite_rate_log (caller_id, target_org_id)
  values (p_caller_id, p_target_org_id);

  return true;
end;
$function$;
COMMENT ON FUNCTION "public"."check_invite_rate_limit"(p_caller_id uuid, p_target_org_id uuid) IS 'Rate-limit gate for invite-org (#361). Returns true if allowed, false if rate-limited. Per-caller: 5/5min. Per-target-org: 1/2min.';
REVOKE ALL ON FUNCTION "public"."check_invite_rate_limit"(p_caller_id uuid, p_target_org_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."check_invite_rate_limit"(p_caller_id uuid, p_target_org_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."check_invite_rate_limit"(p_caller_id uuid, p_target_org_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."check_place_hazard_control_levels"()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF jsonb_typeof(NEW.control_levels) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'Control hierarchy must be an object keyed by the exact control text';
  END IF;
  -- Removed controls lose their classifications; unchanged controls retain theirs.
  IF TG_OP = 'UPDATE' AND NEW.controls IS DISTINCT FROM OLD.controls
    AND NEW.control_levels = OLD.control_levels THEN
    SELECT coalesce(jsonb_object_agg(key, value), '{}'::jsonb) INTO NEW.control_levels
    FROM jsonb_each(NEW.control_levels) WHERE key = ANY(NEW.controls);
  END IF;
  IF EXISTS (SELECT 1 FROM jsonb_each_text(NEW.control_levels) c
    WHERE NOT (c.key = ANY(NEW.controls))
      OR c.value IS NULL OR c.value NOT IN ('elimination', 'substitution', 'isolation', 'engineering', 'administrative', 'ppe')) THEN
    RAISE EXCEPTION 'Classify only existing controls using a recognised hierarchy level';
  END IF;
  IF NEW.risk_owner_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.user_profiles WHERE id = NEW.risk_owner_id
      AND organization_id = NEW.organization_id AND deactivated_at IS NULL
  ) THEN RAISE EXCEPTION 'Risk owner must be an active member of the keeping organisation'; END IF;
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."check_place_hazard_control_levels"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."check_place_hazard_control_levels"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."check_place_hazard_control_levels"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."claim_cctv_inference_job"(p_job_id uuid, p_lease_token uuid, p_lease_seconds integer DEFAULT 900)
 RETURNS TABLE(id uuid, organization_id uuid, evidence_item_id uuid, domain text, status text, lease_token uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' AND session_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;
  IF p_job_id IS NULL OR p_lease_token IS NULL OR p_lease_seconds NOT BETWEEN 60 AND 7200 THEN
    RAISE EXCEPTION 'Valid job, lease, and lease duration are required';
  END IF;

  -- Released at commit, so a pause waits for this claim; the pause check below then reads a fresh snapshot.
  PERFORM pg_advisory_xact_lock_shared(hashtextextended('public.cctv_inference_claim_gate', 0));
  IF EXISTS (SELECT 1 FROM public.cctv_inference_claim_pauses p WHERE p.paused_until > clock_timestamp()) THEN
    RETURN;
  END IF;

  RETURN QUERY
  UPDATE public.inference_jobs j
     SET status = 'processing', stage = 'claimed', attempt_count = j.attempt_count + 1,
         lease_token = p_lease_token, lease_expires_at = clock_timestamp() + make_interval(secs => p_lease_seconds),
         heartbeat_at = clock_timestamp(), error_message = NULL
   WHERE j.id = p_job_id AND j.domain = 'video_motion' AND j.status = 'queued'
   RETURNING j.id, j.organization_id, j.evidence_item_id, j.domain, j.status, j.lease_token;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."claim_cctv_inference_job"(p_job_id uuid, p_lease_token uuid, p_lease_seconds integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."claim_cctv_inference_job"(p_job_id uuid, p_lease_token uuid, p_lease_seconds integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."claim_cctv_inference_job"(p_job_id uuid, p_lease_token uuid, p_lease_seconds integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."claim_document_source_ingestion"(p_worker_id text, p_lease_seconds integer DEFAULT 120)
 RETURNS document_source_ingestion_runs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_run public.document_source_ingestion_runs%ROWTYPE;
BEGIN
  IF p_worker_id IS NULL OR btrim(p_worker_id) = '' THEN
    RAISE EXCEPTION 'worker_id is required';
  END IF;
  IF p_lease_seconds < 30 OR p_lease_seconds > 600 THEN
    RAISE EXCEPTION 'lease_seconds must be between 30 and 600';
  END IF;

  SELECT * INTO v_run
  FROM public.document_source_ingestion_runs
  WHERE status = 'queued'
     OR (status = 'running' AND lease_expires_at < clock_timestamp())
  ORDER BY requested_at, id
  FOR UPDATE SKIP LOCKED
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  UPDATE public.document_source_ingestion_runs
  SET status = 'running',
      worker_id = p_worker_id,
      lease_token = gen_random_uuid(),
      lease_expires_at = clock_timestamp() + make_interval(secs => p_lease_seconds),
      started_at = COALESCE(started_at, clock_timestamp()),
      heartbeat_at = clock_timestamp()
  WHERE id = v_run.id
  RETURNING * INTO v_run;

  RETURN v_run;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."claim_document_source_ingestion"(p_worker_id text, p_lease_seconds integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."claim_document_source_ingestion"(p_worker_id text, p_lease_seconds integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."claim_document_source_ingestion"(p_worker_id text, p_lease_seconds integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."claim_first_org_user"(p_org_id uuid, p_user_id uuid, p_display_name text, p_role text, p_email text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_existing_count integer;
begin
  if p_role not in ('master', 'client_admin') then raise exception 'The first user of an organisation is a master or a client administrator'; end if;
  perform pg_advisory_xact_lock(hashtext(p_org_id::text));
  select count(*) into v_existing_count from public.user_profiles where organization_id = p_org_id;
  if v_existing_count > 0 then
    raise exception 'Organisation already has users — duplicate first-user prevented' using errcode = '23505';
  end if;
  insert into public.user_profiles (id, organization_id, employer_organization_id, display_name, role, email)
  values (p_user_id, p_org_id, p_org_id, p_display_name, p_role, p_email)
  on conflict (id) do update set
    organization_id = excluded.organization_id,
    employer_organization_id = excluded.employer_organization_id,
    display_name = excluded.display_name,
    role = excluded.role,
    email = excluded.email;
end;
$function$;
COMMENT ON FUNCTION "public"."claim_first_org_user"(p_org_id uuid, p_user_id uuid, p_display_name text, p_role text, p_email text) IS 'Race-safe first-user creation for invite-org (#361). Uses pg_advisory_xact_lock to serialise per-org, making duplicate-first-user impossible.';
REVOKE ALL ON FUNCTION "public"."claim_first_org_user"(p_org_id uuid, p_user_id uuid, p_display_name text, p_role text, p_email text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."claim_first_org_user"(p_org_id uuid, p_user_id uuid, p_display_name text, p_role text, p_email text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."claim_first_org_user"(p_org_id uuid, p_user_id uuid, p_display_name text, p_role text, p_email text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."claim_report_pack_email_delivery"(p_pack_id uuid, p_expected_updated_at timestamp with time zone, p_delivery_attempt_id uuid, p_actor_user_id uuid, p_requested_recipient text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_actor uuid := p_actor_user_id;
  v_pack public.monthly_report_packs%rowtype;
  v_recipient text;
  v_recipient_count integer;
begin
  if v_actor is null or p_delivery_attempt_id is null then raise exception 'Provider administrator and delivery attempt are required'; end if;
  select * into v_pack from public.monthly_report_packs where id = p_pack_id for update;
  if not found then raise exception 'Report pack not found'; end if;
  if not public.report_provider_custodian_for_actor(v_pack.organization_id, v_actor) then
    raise exception 'Provider administrator access required';
  end if;
  if v_pack.status = 'sent' then
    return jsonb_build_object('status', 'sent', 'sent_to', v_pack.sent_to);
  end if;
  if v_pack.status <> 'generated' or v_pack.published_at is null or v_pack.delivery_channel <> 'email' then
    raise exception 'Review and publish this email report before sending it';
  end if;
  if v_pack.updated_at is distinct from p_expected_updated_at
     or v_pack.pdf_path is null
     or v_pack.pdf_source_updated_at is distinct from v_pack.updated_at then
    raise exception 'Report changed before delivery; generate a current reviewed PDF';
  end if;
  if v_pack.delivery_attempt_id is not null then
    raise exception 'Report delivery is already in progress; review and republish before retrying an uncertain attempt';
  end if;

  select count(*)::integer, min(btrim(contact.email))
  into v_recipient_count, v_recipient
  from public.service_agreements agreement
  join public.crm_contacts contact
    on contact.organization_id = agreement.client_organization_id
   and contact.is_primary
   and contact.deactivated_at is null
   and nullif(btrim(contact.email), '') is not null
  where agreement.id = v_pack.service_agreement_id;

  if v_recipient_count <> 1 or v_recipient is null then
    raise exception 'Exactly one active primary client contact email is required';
  end if;
  if nullif(btrim(coalesce(p_requested_recipient, '')), '') is not null
     and lower(btrim(p_requested_recipient)) <> lower(v_recipient) then
    raise exception 'Recipient must match the active primary client contact';
  end if;
  if v_pack.report_kind = 'custom'
     and coalesce(v_pack.report_scope->>'privacy_tier', 'operational_metadata') <> 'operational_metadata'
     and not exists (
       select 1
       from public.service_agreements agreement
       join public.user_profiles client_admin
         on client_admin.organization_id = agreement.client_organization_id
        and client_admin.deactivated_at is null
        and client_admin.role = 'client_admin'
        and lower(btrim(coalesce(client_admin.email, ''))) = lower(v_recipient)
       where agreement.id = v_pack.service_agreement_id
     ) then
    raise exception 'Personal report email recipient must be an active client administrator';
  end if;

  update public.monthly_report_packs
  set delivery_attempt_id = p_delivery_attempt_id,
      delivery_started_at = clock_timestamp(),
      delivery_recipient = v_recipient,
      delivery_error = null
  where id = p_pack_id;

  insert into public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (v_pack.organization_id, v_actor, 'monthly_report_pack_delivery_claimed', 'monthly_report_packs', p_pack_id,
    jsonb_build_object('delivery_attempt_id', p_delivery_attempt_id, 'recipient', v_recipient));
  return jsonb_build_object('status', 'claimed', 'delivery_attempt_id', p_delivery_attempt_id, 'recipient', v_recipient);
end;
$function$;
REVOKE ALL ON FUNCTION "public"."claim_report_pack_email_delivery"(p_pack_id uuid, p_expected_updated_at timestamp with time zone, p_delivery_attempt_id uuid, p_actor_user_id uuid, p_requested_recipient text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."claim_report_pack_email_delivery"(p_pack_id uuid, p_expected_updated_at timestamp with time zone, p_delivery_attempt_id uuid, p_actor_user_id uuid, p_requested_recipient text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."claim_report_pack_email_delivery"(p_pack_id uuid, p_expected_updated_at timestamp with time zone, p_delivery_attempt_id uuid, p_actor_user_id uuid, p_requested_recipient text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."claim_shift_coverage"(p_request_id uuid, p_expected_status text DEFAULT 'open'::text)
 RETURNS shift_coverage_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_profile public.user_profiles%rowtype;
  v_request public.shift_coverage_requests%rowtype;
begin
  if v_user_id is null then raise exception 'Authentication required'; end if;
  select * into v_profile from public.user_profiles where id = v_user_id and deactivated_at is null and role in ('officer', 'admin_officer');
  if not found then raise exception 'Active officer profile required'; end if;
  select * into v_request from public.shift_coverage_requests where id = p_request_id for update;
  if not found then raise exception 'Coverage request not found'; end if;
  if v_request.organization_id <> v_profile.organization_id then raise exception 'Coverage request is outside the officer organization'; end if;
  if v_request.status <> p_expected_status then raise exception 'Coverage request changed from expected status % to %', p_expected_status, v_request.status; end if;
  if v_request.status <> 'open' then raise exception 'Coverage request is no longer open'; end if;
  if v_request.shift_date < current_date then raise exception 'Past coverage cannot be claimed'; end if;
  update public.shift_coverage_requests set status = 'claimed', claimed_by = v_user_id, claimed_at = clock_timestamp()
  where id = p_request_id returning * into v_request;
  insert into public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (v_request.organization_id, v_user_id, 'shift_coverage_claimed', 'shift_coverage_requests', v_request.id,
    jsonb_build_object('shift_date', v_request.shift_date, 'start_time', v_request.start_time, 'site_id', v_request.site_id));
  return v_request;
end;
$function$;
COMMENT ON FUNCTION "public"."claim_shift_coverage"(p_request_id uuid, p_expected_status text) IS 'Atomically claims open coverage for the authenticated active officer and records audit provenance.';
REVOKE ALL ON FUNCTION "public"."claim_shift_coverage"(p_request_id uuid, p_expected_status text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."claim_shift_coverage"(p_request_id uuid, p_expected_status text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."claim_shift_coverage"(p_request_id uuid, p_expected_status text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."claim_shift_coverage"(p_request_id uuid, p_expected_status text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."classify_fc_overnight_window"(p_observed_at timestamp with time zone, p_timezone text DEFAULT 'Pacific/Auckland'::text)
 RETURNS TABLE(overnight_date date, scan_window text)
 LANGUAGE sql
 STABLE
AS $function$
  select
    case
      when ((p_observed_at at time zone p_timezone)::time >= time '00:00'
        and (p_observed_at at time zone p_timezone)::time < time '12:00')
      then ((p_observed_at at time zone p_timezone)::date - 1)
      else (p_observed_at at time zone p_timezone)::date
    end as overnight_date,
    case
      when ((p_observed_at at time zone p_timezone)::time >= time '00:00'
        and (p_observed_at at time zone p_timezone)::time < time '12:00')
      then 'morning'
      else 'evening'
    end as scan_window;
$function$;
COMMENT ON FUNCTION "public"."classify_fc_overnight_window"(p_observed_at timestamp with time zone, p_timezone text) IS 'Returns overnight_date and scan window for the two-photo FC verification model using local midnight boundary.';
REVOKE ALL ON FUNCTION "public"."classify_fc_overnight_window"(p_observed_at timestamp with time zone, p_timezone text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."classify_fc_overnight_window"(p_observed_at timestamp with time zone, p_timezone text) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."classify_fc_overnight_window"(p_observed_at timestamp with time zone, p_timezone text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."classify_fc_overnight_window"(p_observed_at timestamp with time zone, p_timezone text) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."classify_fc_overnight_window"(p_observed_at timestamp with time zone, p_timezone text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."classify_fc_overnight_window"(p_observed_at timestamp with time zone, p_timezone text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."classify_patrol_cost_row_billing_basis"(p_provider_organization_id uuid, p_source_values jsonb)
 RETURNS TABLE(basis text, sheet_basis text, code_basis text, conflict boolean)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  WITH s AS (
    SELECT
      CASE lower(btrim(p_source_values->>'activity_type')) WHEN 'contract' THEN 'contract' WHEN 'extra' THEN 'extra' END AS sheet_basis,
      (SELECT CASE lower(rc.external_refs->>'billing_basis') WHEN 'contract' THEN 'contract' WHEN 'extra' THEN 'extra' END
       FROM public.reference_codes rc
       WHERE rc.organization_id = p_provider_organization_id
         AND rc.code_type = 'charge_code'
         AND rc.code = nullif(btrim(p_source_values->>'charge_code'), '')) AS code_basis
  )
  SELECT coalesce(s.sheet_basis, s.code_basis, 'unclassified'), s.sheet_basis, s.code_basis,
    (s.sheet_basis IS NOT NULL AND s.code_basis IS NOT NULL AND s.sheet_basis <> s.code_basis)
  FROM s;
$function$;
COMMENT ON FUNCTION "public"."classify_patrol_cost_row_billing_basis"(p_provider_organization_id uuid, p_source_values jsonb) IS 'Internal rule: an imported patrol cost row is Contract or Extra by the workbook TYPE column first, otherwise by the provider charge-code catalog billing_basis, otherwise unclassified; conflict is true when both are present and disagree.';
REVOKE ALL ON FUNCTION "public"."classify_patrol_cost_row_billing_basis"(p_provider_organization_id uuid, p_source_values jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."classify_patrol_cost_row_billing_basis"(p_provider_organization_id uuid, p_source_values jsonb) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."clear_report_pack_delivery_claim"()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_content_changed boolean :=
    new.published_at is distinct from old.published_at
    or new.editorial is distinct from old.editorial
    or new.data is distinct from old.data
    or new.report_scope is distinct from old.report_scope;
  v_pdf_changed boolean :=
    new.pdf_path is distinct from old.pdf_path
    or new.pdf_mime_type is distinct from old.pdf_mime_type
    or new.pdf_sha256 is distinct from old.pdf_sha256
    or new.pdf_renderer_version is distinct from old.pdf_renderer_version
    or new.pdf_source_updated_at is distinct from old.pdf_source_updated_at;
  v_delivery_finalization boolean :=
    new.status is distinct from old.status
    and new.delivery_attempt_id = old.delivery_attempt_id
    and new.status in ('sent', 'failed');
begin
  if old.status = 'sent' and new is distinct from old then
    raise exception 'Sent report packs are immutable';
  end if;

  if auth.uid() is not null
     and not public.is_report_provider_custodian_for_org(old.organization_id) then
    raise exception 'Provider custodian access required';
  end if;

  if old.delivery_attempt_id is not null
     and old.delivery_started_at > clock_timestamp() - interval '10 minutes'
     and (v_content_changed or v_pdf_changed or new.status is distinct from old.status)
     and not v_delivery_finalization then
    raise exception 'Report email delivery is in progress; wait before changing this report';
  end if;

  if old.pdf_path is not null and new.pdf_path is null then
    new.pdf_path := old.pdf_path;
    new.pdf_mime_type := old.pdf_mime_type;
    new.pdf_sha256 := old.pdf_sha256;
    new.pdf_renderer_version := old.pdf_renderer_version;
    new.pdf_source_updated_at := old.pdf_source_updated_at;
  end if;

  if v_content_changed then
    new.delivery_attempt_id := null;
    new.delivery_started_at := null;
    new.delivery_recipient := null;
  end if;

  if new.status = 'generated'
     and new.published_at is not null
     and new.report_kind = 'custom'
     and coalesce(new.report_scope->>'privacy_tier', 'operational_metadata') <> 'operational_metadata'
     and not exists (
       select 1
       from public.service_agreements agreement
       join public.user_profiles client_profile
         on client_profile.organization_id = agreement.client_organization_id
        and client_profile.deactivated_at is null
        and client_profile.role = 'client_admin'
       where agreement.id = new.service_agreement_id
     ) then
    raise exception 'Personal and sensitive reports require an active client administrator before publication';
  end if;

  if v_delivery_finalization then
    if new.status = 'sent' and old.pdf_source_updated_at = old.updated_at then
      new.pdf_source_updated_at := new.updated_at;
    elsif new.status = 'failed' then
      new.pdf_source_updated_at := null;
    end if;
    new.delivery_attempt_id := null;
    new.delivery_started_at := null;
  end if;
  return new;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."clear_report_pack_delivery_claim"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."clear_report_pack_delivery_claim"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."clear_report_pack_delivery_claim"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."clear_report_pack_delivery_claim"() TO "anon";
GRANT EXECUTE ON FUNCTION "public"."clear_report_pack_delivery_claim"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."clear_report_pack_delivery_claim"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."close_finance_pl_period"(p_pl_period_id uuid)
 RETURNS finance_pl_periods
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_period public.finance_pl_periods%rowtype;
  v_snapshot public.finance_pl_snapshots%rowtype;
BEGIN
  SELECT organization_id INTO v_org FROM public.user_profiles WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_org IS NULL OR NOT public.is_admin_for_org(v_org) THEN RAISE EXCEPTION 'Active finance administrator required'; END IF;
  SELECT * INTO v_period FROM public.finance_pl_periods WHERE id = p_pl_period_id AND organization_id = v_org FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'P&L period not found in organization'; END IF;
  IF v_period.status IN ('closed','archived') THEN RAISE EXCEPTION 'Period is already closed or archived'; END IF;

  WITH cost_summary AS (
    SELECT COALESCE(SUM(CASE WHEN cost_type = 'labour' THEN total_cost ELSE 0 END), 0) AS total_labour,
      COALESCE(SUM(CASE WHEN cost_type = 'vehicle' THEN total_cost ELSE 0 END), 0) AS total_vehicle,
      COALESCE(SUM(CASE WHEN cost_type = 'materials' THEN total_cost ELSE 0 END), 0) AS total_materials,
      COALESCE(SUM(CASE WHEN cost_type = 'equipment' THEN total_cost ELSE 0 END), 0) AS total_equipment,
      COALESCE(SUM(CASE WHEN cost_type = 'overhead' THEN total_cost ELSE 0 END), 0) AS total_overhead,
      COALESCE(SUM(CASE WHEN cost_type = 'depreciation' THEN total_cost ELSE 0 END), 0) AS total_depreciation,
      COALESCE(SUM(total_cost), 0) AS total_cost,
      COUNT(*)::integer AS cost_count
    FROM public.finance_service_costs
    WHERE pl_period_id = p_pl_period_id
      AND organization_id = v_org
  ),
  revenue_summary AS (
    SELECT
      COALESCE(SUM(total_amount), 0)::numeric AS total_revenue,
      COUNT(*)::integer AS invoice_count
    FROM public.invoices
    WHERE organization_id = v_org
      AND invoice_date BETWEEN v_period.period_start AND v_period.period_end
  )
  INSERT INTO public.finance_pl_snapshots(
    organization_id,
    pl_period_id,
    total_labour,
    total_vehicle,
    total_materials,
    total_equipment,
    total_overhead,
    total_depreciation,
    total_cost,
    cost_line_count,
    total_revenue,
    invoice_count,
    gross_profit,
    gross_margin_pct
  )
  SELECT
    v_org,
    p_pl_period_id,
    costs.total_labour,
    costs.total_vehicle,
    costs.total_materials,
    costs.total_equipment,
    costs.total_overhead,
    costs.total_depreciation,
    costs.total_cost,
    costs.cost_count,
    revenue.total_revenue,
    revenue.invoice_count,
    round(revenue.total_revenue - costs.total_cost, 2),
    CASE
      WHEN revenue.total_revenue > 0
        THEN round(((revenue.total_revenue - costs.total_cost) / revenue.total_revenue) * 100, 2)
      ELSE NULL
    END
  FROM cost_summary costs
  CROSS JOIN revenue_summary revenue
  RETURNING * INTO v_snapshot;

  UPDATE public.finance_pl_periods SET status = 'closed', closed_at = now(), closed_by = v_actor, updated_at = now() WHERE id = p_pl_period_id RETURNING * INTO v_period;
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_org, v_actor, 'finance_pl_period_closed', 'finance_pl_periods', v_period.id, jsonb_build_object('snapshot_id', v_snapshot.id, 'total_cost', v_snapshot.total_cost, 'total_revenue', v_snapshot.total_revenue));
  RETURN v_period;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."close_finance_pl_period"(p_pl_period_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."close_finance_pl_period"(p_pl_period_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."close_finance_pl_period"(p_pl_period_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."close_finance_pl_period"(p_pl_period_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."close_ptt_transmission"(p_transmission_id uuid, p_state text DEFAULT 'ended'::text, p_metadata jsonb DEFAULT NULL::jsonb)
 RETURNS TABLE(transmission_id uuid, state text, ended_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_trans public.ptt_transmissions%rowtype;
  v_final_state text := coalesce(p_state, 'ended');
begin
  if v_user_id is null then raise exception 'Authentication required'; end if;

  select t.* into v_trans from public.ptt_transmissions t where t.id = p_transmission_id for update;
  if not found then raise exception 'PTT transmission not found'; end if;
  if v_trans.speaker_user_id <> v_user_id and not public.is_admin_for_org(v_trans.organization_id) then
    raise exception 'Not authorised to update this PTT transmission';
  end if;

  if v_final_state not in ('ended', 'failed', 'emergency') then
    raise exception 'Invalid transmission end state %', p_state;
  end if;

  update public.ptt_transmissions
    set state = v_final_state,
        ended_at = clock_timestamp(),
        metadata = case when p_metadata is not null then metadata || p_metadata else metadata end
    where id = v_trans.id
    returning * into v_trans;

  insert into public.audit_log (
    organization_id, actor_user_id, action, target_table, target_id, metadata
  ) values (
    v_trans.organization_id, v_user_id, 'ptt_transmission_ended', 'ptt_transmissions', v_trans.id,
    jsonb_build_object('state', v_final_state, 'duration_ms', extract(epoch from (v_trans.ended_at - v_trans.started_at)) * 1000)
  );

  return query select v_trans.id, v_trans.state, v_trans.ended_at;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."close_ptt_transmission"(p_transmission_id uuid, p_state text, p_metadata jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."close_ptt_transmission"(p_transmission_id uuid, p_state text, p_metadata jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."close_ptt_transmission"(p_transmission_id uuid, p_state text, p_metadata jsonb) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."close_ptt_transmission"(p_transmission_id uuid, p_state text, p_metadata jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."close_unfinished_officer_shift"(p_client_request_id uuid, p_shift_id uuid, p_expected_status text, p_expected_updated_at timestamp with time zone, p_actual_end timestamp with time zone, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_shift public.shifts%rowtype;
  v_existing public.audit_log%rowtype;
  v_now timestamptz := clock_timestamp();
  v_skipped_stops integer := 0;
  v_completed_stops integer := 0;
  v_closed_breaks integer := 0;
  v_previous jsonb;
  v_resulting jsonb;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Authentication is required';
  END IF;
  IF p_client_request_id IS NULL THEN
    RAISE EXCEPTION 'A client request ID is required';
  END IF;

  SELECT * INTO v_shift FROM public.shifts s WHERE s.id = p_shift_id FOR UPDATE;
  IF NOT FOUND OR NOT public.is_admin_for_org(v_shift.organization_id) THEN
    RAISE EXCEPTION 'Shift not found or access denied';
  END IF;

  SELECT * INTO v_existing
  FROM public.audit_log al
  WHERE al.organization_id = v_shift.organization_id
    AND al.action = 'shift_supervisor_close'
    AND al.target_table = 'shifts'
    AND al.metadata ->> 'client_request_id' = p_client_request_id::text
  ORDER BY al.created_at DESC
  LIMIT 1;
  IF FOUND THEN
    IF v_existing.target_id IS DISTINCT FROM p_shift_id THEN
      RAISE EXCEPTION 'Client request ID was already used for a different shift';
    END IF;
    RETURN jsonb_build_object('replayed', true, 'action', 'close', 'target_id', p_shift_id,
      'previous', v_existing.metadata -> 'previous', 'resulting', v_existing.metadata -> 'resulting');
  END IF;

  IF v_shift.status IS DISTINCT FROM p_expected_status
    OR v_shift.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'Shift changed since it was opened';
  END IF;
  IF v_shift.status <> 'in_progress' OR v_shift.actual_start IS NULL THEN
    RAISE EXCEPTION 'Only a started, unfinished shift can be closed this way';
  END IF;
  IF nullif(trim(coalesce(p_reason, '')), '') IS NULL THEN
    RAISE EXCEPTION 'A reason is required';
  END IF;
  IF length(trim(p_reason)) > 1000 THEN
    RAISE EXCEPTION 'The reason is too long';
  END IF;
  IF p_actual_end IS NULL THEN
    RAISE EXCEPTION 'The time the shift ended is required';
  END IF;
  IF p_actual_end <= v_shift.actual_start THEN
    RAISE EXCEPTION 'The end time must be after the shift started';
  END IF;
  IF p_actual_end > v_now THEN
    RAISE EXCEPTION 'The end time cannot be in the future';
  END IF;
  IF EXISTS (SELECT 1 FROM public.dispatch_jobs j WHERE j.shift_id = v_shift.id AND j.status NOT IN ('completed', 'cancelled')) THEN
    RAISE EXCEPTION 'Complete or cancel this shift''s dispatch jobs before closing it';
  END IF;
  IF EXISTS (SELECT 1 FROM public.welfare_alerts w WHERE w.shift_id = v_shift.id AND w.status <> 'resolved') THEN
    RAISE EXCEPTION 'Resolve this shift''s welfare alerts before closing it';
  END IF;

  v_previous := jsonb_build_object('status', v_shift.status, 'actual_start', v_shift.actual_start,
    'actual_end', v_shift.actual_end, 'ended_reason', v_shift.ended_reason, 'updated_at', v_shift.updated_at);

  UPDATE public.shift_breaks
  SET ended_at = greatest(started_at, p_actual_end)
  WHERE shift_id = v_shift.id AND ended_at IS NULL;
  GET DIAGNOSTICS v_closed_breaks = ROW_COUNT;

  -- A stop the officer reached is finished at the recorded end; one never reached is skipped.
  UPDATE public.shift_stops
  SET status = 'completed',
      actual_departed_at = coalesce(actual_departed_at, greatest(actual_arrived_at, p_actual_end)),
      sla_status = 'completed',
      updated_at = v_now
  WHERE shift_id = v_shift.id AND status = 'on_scene';
  GET DIAGNOSTICS v_completed_stops = ROW_COUNT;

  UPDATE public.shift_stops
  SET status = 'skipped', sla_status = 'skipped', updated_at = v_now
  WHERE shift_id = v_shift.id AND status IN ('pending', 'en_route');
  GET DIAGNOSTICS v_skipped_stops = ROW_COUNT;

  UPDATE public.shifts
  SET status = 'completed', actual_end = p_actual_end, ended_reason = 'supervisor_closed', updated_at = v_now
  WHERE id = v_shift.id
  RETURNING * INTO v_shift;

  UPDATE public.roster_slots SET status = 'completed'
  WHERE linked_shift_id = v_shift.id AND status IN ('published', 'accepted');

  v_resulting := jsonb_build_object('status', v_shift.status, 'actual_start', v_shift.actual_start,
    'actual_end', v_shift.actual_end, 'ended_reason', v_shift.ended_reason, 'updated_at', v_shift.updated_at,
    'stops_skipped', v_skipped_stops, 'stops_completed', v_completed_stops, 'breaks_closed', v_closed_breaks);

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_shift.organization_id, v_actor, 'shift_supervisor_close', 'shifts', v_shift.id, jsonb_build_object(
    'client_request_id', p_client_request_id,
    'reason', trim(p_reason),
    'officer_user_id', v_shift.officer_user_id,
    'previous', v_previous,
    'resulting', v_resulting));

  RETURN jsonb_build_object('replayed', false, 'action', 'close', 'target_id', v_shift.id,
    'previous', v_previous, 'resulting', v_resulting);
END;
$function$;
COMMENT ON FUNCTION "public"."close_unfinished_officer_shift"(p_client_request_id uuid, p_shift_id uuid, p_expected_status text, p_expected_updated_at timestamp with time zone, p_actual_end timestamp with time zone, p_reason text) IS 'Branch admin closes an in-progress shift the officer could not end, at the recorded end time (after start, not in the future). Reached stops complete, unreached stops are skipped, open breaks end; dispatch jobs and welfare alerts must already be closed. Replay-safe on client_request_id with a before/after audit receipt.';
REVOKE ALL ON FUNCTION "public"."close_unfinished_officer_shift"(p_client_request_id uuid, p_shift_id uuid, p_expected_status text, p_expected_updated_at timestamp with time zone, p_actual_end timestamp with time zone, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."close_unfinished_officer_shift"(p_client_request_id uuid, p_shift_id uuid, p_expected_status text, p_expected_updated_at timestamp with time zone, p_actual_end timestamp with time zone, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."close_unfinished_officer_shift"(p_client_request_id uuid, p_shift_id uuid, p_expected_status text, p_expected_updated_at timestamp with time zone, p_actual_end timestamp with time zone, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."close_unfinished_officer_shift"(p_client_request_id uuid, p_shift_id uuid, p_expected_status text, p_expected_updated_at timestamp with time zone, p_actual_end timestamp with time zone, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."coalesce_cctv_stationary_vehicle_observations"(p_job_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_new public.cctv_entity_observations%rowtype;
  v_anchor public.cctv_entity_observations%rowtype;
  v_timezone text;
  v_count integer := 0;
  v_new_end timestamptz;
  v_anchor_end timestamptz;
BEGIN
  IF auth.role() <> 'service_role' AND session_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.inference_jobs WHERE id = p_job_id AND domain = 'video_motion') THEN
    RAISE EXCEPTION 'CCTV inference job is missing';
  END IF;

  FOR v_new IN
    SELECT * FROM public.cctv_entity_observations
    WHERE inference_job_id = p_job_id AND entity_kind = 'vehicle' AND review_state = 'unreviewed'
    ORDER BY observed_at, id
  LOOP
    IF v_new.cctv_import_id IS NULL OR jsonb_typeof(v_new.attributes->'bbox') <> 'object' THEN CONTINUE; END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended(v_new.cctv_import_id::text || ':stationary-vehicle', 0));
    SELECT source_timezone INTO v_timezone FROM public.cctv_imports WHERE id = v_new.cctv_import_id;
    v_timezone := coalesce(v_timezone, 'Pacific/Auckland');
    v_new_end := coalesce(v_new.observed_to, v_new.observed_at);
    v_anchor.id := NULL;

    SELECT candidate.* INTO v_anchor
    FROM public.cctv_entity_observations candidate
    WHERE candidate.id <> v_new.id
      AND candidate.organization_id = v_new.organization_id
      AND candidate.cctv_import_id = v_new.cctv_import_id
      AND candidate.entity_kind = 'vehicle'
      AND candidate.review_state = 'unreviewed'
      AND (candidate.observed_at AT TIME ZONE v_timezone)::date = (v_new.observed_at AT TIME ZONE v_timezone)::date
      AND candidate.observed_at <= v_new_end + interval '15 minutes'
      AND coalesce(candidate.observed_to, candidate.observed_at) >= v_new.observed_at - interval '15 minutes'
      AND public.cctv_bbox_is_stationary(coalesce(candidate.attributes->'last_bbox', candidate.attributes->'bbox'), v_new.attributes->'bbox')
      AND (
        (v_new.candidate_plate IS NOT NULL AND candidate.candidate_plate = v_new.candidate_plate)
        OR (v_new.appearance_vec IS NOT NULL AND candidate.appearance_vec IS NOT NULL AND (1 - (candidate.appearance_vec <=> v_new.appearance_vec)) >= 0.88)
      )
    ORDER BY abs(extract(epoch FROM (candidate.observed_at - v_new.observed_at))), candidate.observed_at
    LIMIT 1
    FOR UPDATE SKIP LOCKED;

    IF v_anchor.id IS NULL THEN CONTINUE; END IF;
    v_anchor_end := coalesce(v_anchor.observed_to, v_anchor.observed_at);
    UPDATE public.cctv_entity_observations
    SET observed_at = least(v_anchor.observed_at, v_new.observed_at),
        observed_to = greatest(v_anchor_end, v_new_end),
        candidate_plate = coalesce(v_anchor.candidate_plate, v_new.candidate_plate),
        canonical_vehicle_id = coalesce(v_anchor.canonical_vehicle_id, v_new.canonical_vehicle_id),
        model_confidence = greatest(v_anchor.model_confidence, v_new.model_confidence),
        attributes = v_anchor.attributes || jsonb_strip_nulls(jsonb_build_object(
          'frame_count', coalesce((v_anchor.attributes->>'frame_count')::integer, 1) + coalesce((v_new.attributes->>'frame_count')::integer, 1),
          'source_observation_count', coalesce((v_anchor.attributes->>'source_observation_count')::integer, 1) + 1,
          'continuous_stationary_event', true,
          'last_bbox', v_new.attributes->'bbox',
          'coalesced_until', greatest(v_anchor_end, v_new_end)
        )),
        thumbnail = CASE WHEN coalesce(v_new.model_confidence, 0) > coalesce(v_anchor.model_confidence, 0) AND v_new.thumbnail IS NOT NULL THEN v_new.thumbnail ELSE v_anchor.thumbnail END,
        frame_sha256 = CASE WHEN coalesce(v_new.model_confidence, 0) > coalesce(v_anchor.model_confidence, 0) THEN coalesce(v_new.frame_sha256, v_anchor.frame_sha256) ELSE v_anchor.frame_sha256 END
    WHERE id = v_anchor.id;

    UPDATE public.cctv_entity_observations
    SET review_state = 'superseded',
        review_notes = 'Source detection consolidated into continuous stationary vehicle event ' || v_anchor.id::text,
        attributes = attributes || jsonb_build_object('superseded_by_observation_id', v_anchor.id, 'continuous_stationary_event_source', true),
        portfolio_candidates = '[]'::jsonb,
        thumbnail = NULL
    WHERE id = v_new.id;
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END;
$function$;
COMMENT ON FUNCTION "public"."coalesce_cctv_stationary_vehicle_observations"(p_job_id uuid) IS 'Service-only post-inference consolidation: same camera/day, <=15 minute gap, stationary bbox, and exact plate or >=88% appearance similarity. Source rows remain superseded for evidence provenance.';
REVOKE ALL ON FUNCTION "public"."coalesce_cctv_stationary_vehicle_observations"(p_job_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."coalesce_cctv_stationary_vehicle_observations"(p_job_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."coalesce_cctv_stationary_vehicle_observations"(p_job_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."commercial_model_label"(p_model text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE p_model
    WHEN 'fixed_price_with_extras' THEN 'fixed price plus Extra'
    WHEN 'pay_as_you_go' THEN 'pay as you go'
    WHEN 'do_and_invoice' THEN 'do and invoice'
    WHEN 'per_request' THEN 'per request'
    ELSE 'not set' END;
$function$;
REVOKE ALL ON FUNCTION "public"."commercial_model_label"(p_model text) FROM PUBLIC, "anon", "authenticated", "service_role";
