CREATE OR REPLACE FUNCTION "public"."commit_org_jurisdiction_stage"(p_stage_id uuid, p_org_id uuid, p_expected_parts integer, p_boundary_source text DEFAULT NULL::text, p_changed_by uuid DEFAULT NULL::uuid, p_changed_via text DEFAULT 'governed_proposal'::text)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_stage public.org_jurisdiction_geom_stages;
  v_area  numeric;
BEGIN
  SELECT * INTO v_stage FROM public.org_jurisdiction_geom_stages WHERE id = p_stage_id FOR UPDATE;
  IF NOT FOUND OR v_stage.expires_at < now() THEN
    RAISE EXCEPTION 'Jurisdiction stage % not found or expired', p_stage_id;
  END IF;
  IF v_stage.organization_id <> p_org_id THEN
    RAISE EXCEPTION 'Jurisdiction stage belongs to a different organization';
  END IF;
  -- Never commit a partial service area.
  IF p_expected_parts IS NULL OR v_stage.part_count <> p_expected_parts THEN
    RAISE EXCEPTION 'Jurisdiction stage has % of % parts', v_stage.part_count, p_expected_parts;
  END IF;
  v_area := public._write_org_jurisdiction_geom(p_org_id, v_stage.geom, p_boundary_source, p_changed_by, p_changed_via);
  DELETE FROM public.org_jurisdiction_geom_stages WHERE id = v_stage.id;
  RETURN v_area;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."commit_org_jurisdiction_stage"(p_stage_id uuid, p_org_id uuid, p_expected_parts integer, p_boundary_source text, p_changed_by uuid, p_changed_via text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."commit_org_jurisdiction_stage"(p_stage_id uuid, p_org_id uuid, p_expected_parts integer, p_boundary_source text, p_changed_by uuid, p_changed_via text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."commit_org_jurisdiction_stage"(p_stage_id uuid, p_org_id uuid, p_expected_parts integer, p_boundary_source text, p_changed_by uuid, p_changed_via text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."compact_cctv_inference_results"(p_limit integer DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  target record;
  v_rows integer := 0;
  v_before bigint := 0;
  v_after bigint := 0;
  v_compact jsonb;
BEGIN
  IF auth.role() <> 'service_role' AND session_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;
  FOR target IN
    SELECT id, inference_job_id, result
    FROM public.inference_results
    WHERE domain = 'video_motion' AND coalesce(result->>'storage_profile', '') <> 'review_event_summary_v1'
    ORDER BY created_at, id
    LIMIT least(greatest(coalesce(p_limit, 5), 1), 20)
    FOR UPDATE SKIP LOCKED
  LOOP
    v_before := v_before + pg_column_size(target.result);
    v_compact := public.cctv_compact_motion_result(target.inference_job_id, target.result);
    UPDATE public.inference_results SET result = v_compact WHERE id = target.id;
    v_after := v_after + pg_column_size(v_compact);
    v_rows := v_rows + 1;
  END LOOP;
  RETURN jsonb_build_object('rows', v_rows, 'before_bytes', v_before, 'after_bytes', v_after);
END;
$function$;
REVOKE ALL ON FUNCTION "public"."compact_cctv_inference_results"(p_limit integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."compact_cctv_inference_results"(p_limit integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."compact_cctv_inference_results"(p_limit integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."compact_cctv_observation_thumbnail"(p_observation_id uuid, p_thumbnail text, p_original_bytes integer, p_compacted_bytes integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.role() <> 'service_role' AND session_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;
  IF p_thumbnail IS NOT NULL AND (p_thumbnail NOT LIKE 'data:image/jpeg;base64,%' OR octet_length(p_thumbnail) > 80000 OR p_compacted_bytes > 60000) THEN
    RAISE EXCEPTION 'Compacted CCTV thumbnail is invalid or too large';
  END IF;
  UPDATE public.cctv_entity_observations
  SET thumbnail = p_thumbnail,
      attributes = attributes || jsonb_build_object(
        'thumbnail_compacted', p_thumbnail IS NOT NULL,
        'thumbnail_compaction_failed', p_thumbnail IS NULL,
        'thumbnail_original_bytes', p_original_bytes,
        'thumbnail_compacted_bytes', p_compacted_bytes,
        'thumbnail_compacted_at', clock_timestamp()
      )
  WHERE id = p_observation_id AND review_state <> 'superseded';
  RETURN FOUND;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."compact_cctv_observation_thumbnail"(p_observation_id uuid, p_thumbnail text, p_original_bytes integer, p_compacted_bytes integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."compact_cctv_observation_thumbnail"(p_observation_id uuid, p_thumbnail text, p_original_bytes integer, p_compacted_bytes integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."compact_cctv_observation_thumbnail"(p_observation_id uuid, p_thumbnail text, p_original_bytes integer, p_compacted_bytes integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."compare_boundaries_hausdorff"(p_geojson_a text, p_geojson_b text)
 RETURNS double precision
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  geom_a geometry;
  geom_b geometry;
  dist double precision;
BEGIN
  -- Null/empty guard: return large sentinel (mismatch), never 0.
  IF p_geojson_a IS NULL OR p_geojson_b IS NULL
     OR trim(p_geojson_a) = '' OR trim(p_geojson_b) = '' THEN
    RETURN 1e9;
  END IF;

  BEGIN
    geom_a := ST_MakeValid(ST_GeomFromGeoJSON(p_geojson_a));
    geom_b := ST_MakeValid(ST_GeomFromGeoJSON(p_geojson_b));
  EXCEPTION WHEN OTHERS THEN
    -- Invalid GeoJSON: return large sentinel (mismatch), never 0.
    RETURN 1e9;
  END;

  -- Empty geometry guard
  IF geom_a IS NULL OR geom_b IS NULL
     OR ST_IsEmpty(geom_a) OR ST_IsEmpty(geom_b) THEN
    RETURN 1e9;
  END IF;

  -- ST_HausdorffDistance on geography returns metres.
  dist := ST_HausdorffDistance(ST_Transform(ST_SetSRID(geom_a, 4326), 2193), ST_Transform(ST_SetSRID(geom_b, 4326), 2193));

  -- Defensive: if the result is NULL or non-finite, return sentinel.
  IF dist IS NULL OR dist = 'NaN'::double precision
     OR dist = 'Infinity'::double precision THEN
    RETURN 1e9;
  END IF;

  RETURN dist;
END;
$function$;
COMMENT ON FUNCTION "public"."compare_boundaries_hausdorff"(p_geojson_a text, p_geojson_b text) IS 'Compare two GeoJSON boundaries via ST_HausdorffDistance (geography, metres). Returns distance in metres; returns 1e9 sentinel on null/invalid input (never 0). Used by canonicalSiteEntry.ts for Q-A3 reconciliation (threshold 5m per Q7).';
REVOKE ALL ON FUNCTION "public"."compare_boundaries_hausdorff"(p_geojson_a text, p_geojson_b text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."compare_boundaries_hausdorff"(p_geojson_a text, p_geojson_b text) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."compare_boundaries_hausdorff"(p_geojson_a text, p_geojson_b text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."compare_boundaries_hausdorff"(p_geojson_a text, p_geojson_b text) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."compare_boundaries_hausdorff"(p_geojson_a text, p_geojson_b text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."compare_boundaries_hausdorff"(p_geojson_a text, p_geojson_b text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."complete_cctv_media_upload_claim"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.evidence_kind IN('video','photo') AND NEW.sha256_hash IS NOT NULL THEN
    UPDATE public.cctv_media_upload_claims SET status='registered',evidence_item_id=NEW.id,registered_at=clock_timestamp(),expires_at=clock_timestamp() WHERE organization_id=NEW.organization_id AND evidence_kind=NEW.evidence_kind AND sha256=lower(NEW.sha256_hash);
  END IF;
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."complete_cctv_media_upload_claim"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."complete_cctv_media_upload_claim"() TO "postgres";

CREATE OR REPLACE FUNCTION "public"."complete_cctv_still_inference"(p_job_id uuid, p_evidence_id uuid, p_org_id uuid, p_result jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_result_id uuid;
  v_import_id uuid;
BEGIN
  IF auth.role() <> 'service_role' AND session_user NOT IN ('postgres', 'supabase_admin') THEN RAISE EXCEPTION 'Service identity required'; END IF;
  IF jsonb_typeof(p_result) <> 'object' THEN RAISE EXCEPTION 'Still inference result must be an object'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.inference_jobs
    WHERE id = p_job_id AND evidence_item_id = p_evidence_id AND organization_id = p_org_id
      AND domain = 'video_motion' AND status = 'processing'
  ) THEN RAISE EXCEPTION 'CCTV still inference job is missing, mismatched, or not processing'; END IF;
  SELECT cctv_import_id INTO v_import_id FROM public.evidence_items
  WHERE id = p_evidence_id AND organization_id = p_org_id AND evidence_kind = 'photo';
  IF NOT FOUND THEN RAISE EXCEPTION 'Photo evidence is missing or belongs to another organization'; END IF;

  INSERT INTO public.inference_results (inference_job_id, evidence_item_id, domain, status, result)
  VALUES (p_job_id, p_evidence_id, 'video_motion', 'complete', p_result)
  RETURNING id INTO v_result_id;

  UPDATE public.inference_jobs SET status = 'complete', stage = 'complete', progress_percent = 100,
    progress_label = 'Photo analysis ready for review', completed_at = clock_timestamp(),
    lease_token = NULL, lease_expires_at = NULL, heartbeat_at = NULL
  WHERE id = p_job_id AND status = 'processing';
  IF NOT FOUND THEN RAISE EXCEPTION 'CCTV still inference job changed before completion'; END IF;

  IF v_import_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.evidence_items item
    JOIN public.inference_jobs job ON job.evidence_item_id = item.id
    WHERE item.cctv_import_id = v_import_id AND job.domain = 'video_motion'
      AND job.status NOT IN ('complete', 'inconclusive', 'manual_review_required')
  ) THEN
    UPDATE public.cctv_imports SET status = 'review_ready', updated_at = clock_timestamp()
    WHERE id = v_import_id AND status IN ('registered', 'processing');
  END IF;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (p_org_id, NULL, 'cctv_still_inference_completed', 'inference_jobs', p_job_id,
    jsonb_build_object('evidence_item_id', p_evidence_id, 'review_required', true));
  RETURN v_result_id;
END;
$function$;
COMMENT ON FUNCTION "public"."complete_cctv_still_inference"(p_job_id uuid, p_evidence_id uuid, p_org_id uuid, p_result jsonb) IS 'Service-only completion for one CCTV photo. Recognition is provisional and review-required.';
REVOKE ALL ON FUNCTION "public"."complete_cctv_still_inference"(p_job_id uuid, p_evidence_id uuid, p_org_id uuid, p_result jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."complete_cctv_still_inference"(p_job_id uuid, p_evidence_id uuid, p_org_id uuid, p_result jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."complete_cctv_still_inference"(p_job_id uuid, p_evidence_id uuid, p_org_id uuid, p_result jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."complete_crm_follow_up"(p_client_request_id uuid, p_activity_id uuid, p_completion_notes text DEFAULT NULL::text)
 RETURNS TABLE(activity_id uuid, completed_at timestamp with time zone, completed_by uuid, completed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_activity public.crm_account_activities%rowtype;
  v_notes text := nullif(trim(coalesce(p_completion_notes, '')), '');
begin
  if p_client_request_id is null then
    raise exception 'client_request_id is required';
  end if;

  select a.* into v_activity from public.crm_account_activities a where a.id = p_activity_id;
  if not found then
    raise exception 'Activity not found';
  end if;

  if not public.is_admin_for_org(v_activity.provider_organization_id) then
    raise exception 'Not authorised to modify activity for this account';
  end if;

  if v_activity.completed_at is not null then
    return query select v_activity.id, v_activity.completed_at, v_activity.completed_by, true;
    return;
  end if;

  update public.crm_account_activities
  set
    completed_at = now(),
    completed_by = v_actor,
    completion_notes = coalesce(v_notes, completion_notes)
  where id = v_activity.id
  returning * into v_activity;

  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (
    v_activity.provider_organization_id,
    v_actor,
    'crm_follow_up_completed',
    'crm_account_activities',
    v_activity.id,
    jsonb_build_object(
      'account_organization_id', v_activity.account_organization_id,
      'subject', v_activity.subject,
      'completion_notes', v_notes,
      'client_request_id', p_client_request_id
    )
  );

  return query select v_activity.id, v_activity.completed_at, v_activity.completed_by, true;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."complete_crm_follow_up"(p_client_request_id uuid, p_activity_id uuid, p_completion_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."complete_crm_follow_up"(p_client_request_id uuid, p_activity_id uuid, p_completion_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."complete_crm_follow_up"(p_client_request_id uuid, p_activity_id uuid, p_completion_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."complete_crm_follow_up"(p_client_request_id uuid, p_activity_id uuid, p_completion_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."complete_finance_external_connection"(p_request_id uuid, p_provider_connection_reference text, p_adapter_name text, p_granted_scopes text[] DEFAULT '{}'::text[])
 RETURNS finance_external_connection_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_request public.finance_external_connection_requests%rowtype;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Provider adapter execution only'; END IF;
  IF nullif(trim(p_provider_connection_reference), '') IS NULL OR nullif(trim(p_adapter_name), '') IS NULL THEN RAISE EXCEPTION 'Provider connection reference and adapter are required'; END IF;
  SELECT * INTO v_request FROM public.finance_external_connection_requests WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Finance connection request not found'; END IF;
  UPDATE public.finance_external_connection_requests
  SET status = 'connected', provider_connection_reference = trim(p_provider_connection_reference), adapter_name = trim(p_adapter_name), requested_scopes = COALESCE(p_granted_scopes, requested_scopes), connected_at = now(), disconnected_at = NULL, last_error = NULL, updated_at = now()
  WHERE id = p_request_id
  RETURNING * INTO v_request;
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_request.organization_id, NULL, 'finance_external_connection_completed', 'finance_external_connection_requests', v_request.id, jsonb_build_object('provider_type', v_request.provider_type, 'adapter_name', v_request.adapter_name, 'credentials_stored_in_browser', false));
  RETURN v_request;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."complete_finance_external_connection"(p_request_id uuid, p_provider_connection_reference text, p_adapter_name text, p_granted_scopes text[]) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."complete_finance_external_connection"(p_request_id uuid, p_provider_connection_reference text, p_adapter_name text, p_granted_scopes text[]) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."complete_finance_external_connection"(p_request_id uuid, p_provider_connection_reference text, p_adapter_name text, p_granted_scopes text[]) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."complete_motion_inference"(p_job_id uuid, p_evidence_id uuid, p_org_id uuid, p_motion_result jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  result_id uuid;
  face_event record;
  candidate_list jsonb;
  import_id uuid;
  ready_import_id uuid;
  v_person_id uuid;
  v_canonical_id uuid;
  v_portfolio_key uuid;
BEGIN
  IF auth.role() <> 'service_role' AND session_user <> 'postgres' THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;
  IF p_job_id IS NULL OR p_evidence_id IS NULL OR p_org_id IS NULL OR p_motion_result IS NULL THEN
    RAISE EXCEPTION 'Job, evidence, organization, and motion result are required';
  END IF;
  IF jsonb_typeof(p_motion_result) <> 'object' OR jsonb_typeof(p_motion_result->'motion_segments') <> 'array' THEN
    RAISE EXCEPTION 'Motion result must contain a motion_segments array';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.inference_jobs
    WHERE id = p_job_id
      AND evidence_item_id = p_evidence_id
      AND organization_id = p_org_id
      AND domain = 'video_motion'
      AND status = 'processing'
  ) THEN
    RAISE EXCEPTION 'Inference job is missing, mismatched, or not processing';
  END IF;
  SELECT evidence.cctv_import_id
    INTO import_id
    FROM public.evidence_items AS evidence
   WHERE evidence.id = p_evidence_id
     AND evidence.organization_id = p_org_id
     AND evidence.evidence_kind = 'video';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Video evidence is missing or belongs to another organization';
  END IF;

  INSERT INTO public.inference_results (inference_job_id, evidence_item_id, domain, status, result)
  VALUES (p_job_id, p_evidence_id, 'video_motion', 'complete', p_motion_result)
  RETURNING id INTO result_id;

  FOR face_event IN
    SELECT value AS event, ordinality AS event_number
    FROM jsonb_array_elements(COALESCE(p_motion_result #> '{consolidated_events,face_events}', '[]'::jsonb)) WITH ORDINALITY
  LOOP
    v_person_id := NULL;
    v_canonical_id := NULL;
    v_portfolio_key := NULL;
    SELECT observation.person_record_id, observation.canonical_person_id, observation.portfolio_key
      INTO v_person_id, v_canonical_id, v_portfolio_key
      FROM public.cctv_entity_observations AS observation
     WHERE observation.inference_job_id = p_job_id
       AND observation.organization_id = p_org_id
       AND observation.entity_kind = 'person'
       AND (
         observation.source_event_id = face_event.event->>'event_id'
         OR observation.attributes->>'face_event_id' = face_event.event->>'event_id'
       )
     ORDER BY (observation.source_event_id = face_event.event->>'event_id') DESC,
              observation.observed_at
     LIMIT 1;

    IF v_person_id IS NULL THEN
      v_portfolio_key := COALESCE(v_portfolio_key, gen_random_uuid());
      SELECT profile.person_record_id, profile.canonical_person_id
        INTO v_person_id, v_canonical_id
        FROM public.ensure_cctv_person_profile(
          p_org_id,
          v_portfolio_key,
          NULL,
          p_evidence_id,
          NULLIF(face_event.event->>'first_seen_at', '')::timestamptz
        ) AS profile;
    ELSIF v_canonical_id IS NULL THEN
      v_canonical_id := public.ensure_canonical_person_for_record(v_person_id);
    END IF;

    SELECT COALESCE(jsonb_agg(candidate ORDER BY similarity DESC), '[]'::jsonb)
      INTO candidate_list
      FROM (
        SELECT jsonb_build_object(
          'person_record_id', person.id,
          'display_name', COALESCE(person.display_name, 'Unnamed person'),
          'similarity', round(public.face_embedding_cosine(
            face_event.event->'face_embedding', person.metadata #> '{face_reference,embedding}'
          )::numeric, 4),
          'reference_thumbnail', person.metadata #>> '{face_reference,thumbnail}',
          'review_state', person.review_state
        ) AS candidate,
        public.face_embedding_cosine(face_event.event->'face_embedding', person.metadata #> '{face_reference,embedding}') AS similarity
        FROM public.person_records AS person
        WHERE person.organization_id = p_org_id
          AND jsonb_typeof(face_event.event->'face_embedding') = 'array'
          AND jsonb_typeof(person.metadata #> '{face_reference,embedding}') = 'array'
        ORDER BY similarity DESC
        LIMIT 5
      ) AS ranked;

    IF NOT EXISTS (
      SELECT 1
      FROM public.face_observations AS face_observation
      WHERE face_observation.evidence_item_id = p_evidence_id
        AND face_observation.metadata->>'source_event_id' = face_event.event->>'event_id'
    ) THEN
      INSERT INTO public.face_observations (
        organization_id,
        evidence_item_id,
        person_record_id,
        confidence,
        purpose,
        review_state,
        metadata
      )
      VALUES (
        p_org_id,
        p_evidence_id,
        v_person_id,
        NULL,
        'cctv_video_motion_candidate',
        'manual_review_required',
        jsonb_strip_nulls(jsonb_build_object(
          'source_event_id', face_event.event->>'event_id',
          'source_subject_id', face_event.event->>'subject_id',
          'original_thumbnail', face_event.event->>'thumbnail',
          'original_frame_hash', face_event.event->>'best_frame_hash',
          'embedding', face_event.event->'face_embedding',
          'canonical_person_id', v_canonical_id,
          'candidates', candidate_list
        ))
      );
    END IF;
  END LOOP;

  UPDATE public.inference_jobs
     SET status = 'complete',
         completed_at = clock_timestamp()
   WHERE id = p_job_id
     AND status = 'processing';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Inference job changed before completion';
  END IF;

  IF import_id IS NOT NULL THEN
    PERFORM 1
      FROM public.cctv_imports
     WHERE id = import_id
     FOR UPDATE;
    UPDATE public.cctv_imports AS import_row
       SET status = 'review_ready',
           updated_at = clock_timestamp()
     WHERE import_row.id = import_id
       AND import_row.status IN ('registered', 'processing')
       AND EXISTS (
         SELECT 1
         FROM public.evidence_items AS import_evidence
         JOIN public.inference_jobs AS import_job
           ON import_job.evidence_item_id = import_evidence.id
        WHERE import_evidence.cctv_import_id = import_row.id
          AND import_job.domain = 'video_motion'
       )
       AND NOT EXISTS (
         SELECT 1
         FROM public.evidence_items AS import_evidence
         JOIN public.inference_jobs AS import_job
           ON import_job.evidence_item_id = import_evidence.id
        WHERE import_evidence.cctv_import_id = import_row.id
          AND import_job.domain = 'video_motion'
          AND import_job.status NOT IN ('complete', 'inconclusive', 'manual_review_required')
       )
    RETURNING import_row.id INTO ready_import_id;
    IF ready_import_id IS NOT NULL THEN
      INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
      VALUES (
        p_org_id,
        NULL,
        'cctv_import_review_ready',
        'cctv_imports',
        ready_import_id,
        jsonb_build_object('trigger_job_id', p_job_id, 'completed_video_jobs', (
          SELECT count(*)
          FROM public.evidence_items AS import_evidence
          JOIN public.inference_jobs AS import_job
            ON import_job.evidence_item_id = import_evidence.id
          WHERE import_evidence.cctv_import_id = ready_import_id
            AND import_job.domain = 'video_motion'
            AND import_job.status IN ('complete', 'inconclusive', 'manual_review_required')
        ))
      );
    END IF;
  END IF;

  RETURN result_id;
END;
$function$;
COMMENT ON FUNCTION "public"."complete_motion_inference"(p_job_id uuid, p_evidence_id uuid, p_org_id uuid, p_motion_result jsonb) IS 'Stores a completed video-motion result, attaches face evidence to its inferred person profile, and advances the parent CCTV import to review_ready only when every video job is reviewable.';
REVOKE ALL ON FUNCTION "public"."complete_motion_inference"(p_job_id uuid, p_evidence_id uuid, p_org_id uuid, p_motion_result jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."complete_motion_inference"(p_job_id uuid, p_evidence_id uuid, p_org_id uuid, p_motion_result jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."complete_motion_inference"(p_job_id uuid, p_evidence_id uuid, p_org_id uuid, p_motion_result jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."complete_officer_shift"(p_shift_id uuid, p_expected_status text, p_gps_lat double precision DEFAULT NULL::double precision, p_gps_lng double precision DEFAULT NULL::double precision)
 RETURNS TABLE(shift_id uuid, shift_status text, completed_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_shift public.shifts%rowtype;
  v_completed_at timestamptz := clock_timestamp();
  v_position jsonb;
begin
  if v_actor is null then raise exception 'Authentication required'; end if;
  select s.* into v_shift from public.shifts s where s.id = p_shift_id for update;
  if not found then raise exception 'Shift not found'; end if;
  if v_shift.officer_user_id <> v_actor then raise exception 'Shift does not belong to the authenticated officer'; end if;
  if v_shift.status <> p_expected_status then raise exception 'Shift changed from expected status % to %', p_expected_status, v_shift.status; end if;
  if v_shift.status <> 'in_progress' then raise exception 'Only an in-progress shift can be completed'; end if;
  if not exists (select 1 from public.shift_debriefs d where d.shift_id = v_shift.id and d.officer_user_id = v_actor) then raise exception 'Submit the shift debrief before completing the shift'; end if;
  if exists (select 1 from public.shift_stops st where st.shift_id = v_shift.id and st.status not in ('completed', 'skipped', 'cancelled')) then raise exception 'Complete or skip every shift stop before completing the shift'; end if;
  if exists (select 1 from public.shift_stop_modules sm join public.shift_stops st on st.id = sm.shift_stop_id where st.shift_id = v_shift.id and sm.is_required and sm.status not in ('completed', 'skipped')) then raise exception 'Complete or skip every required module task before completing the shift'; end if;
  if exists (select 1 from public.dispatch_jobs j where j.shift_id = v_shift.id and j.status not in ('completed', 'cancelled')) then raise exception 'Complete or cancel every dispatch job before completing the shift'; end if;
  if exists (select 1 from public.welfare_alerts w where w.shift_id = v_shift.id and w.status <> 'resolved') then raise exception 'Resolve active welfare alerts before completing the shift'; end if;

  if p_gps_lat is not null and p_gps_lng is not null then
    v_position := public.evaluate_shift_start_position(v_shift.id, p_gps_lat, p_gps_lng);
  end if;

  update public.shifts set status = 'completed', actual_end = coalesce(actual_end, v_completed_at), ended_reason = 'officer', updated_at = v_completed_at where id = v_shift.id returning * into v_shift;
  update public.roster_slots set status = 'completed' where linked_shift_id = v_shift.id and status in ('published', 'accepted');
  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (v_shift.organization_id, v_actor, 'officer_shift_completed', 'shifts', v_shift.id, jsonb_build_object(
    'previous_status', p_expected_status,
    'actual_end', v_shift.actual_end,
    'gps_lat', p_gps_lat,
    'gps_lng', p_gps_lng,
    'end_position', v_position
  ));
  return query select v_shift.id, v_shift.status, v_shift.actual_end;
end;
$function$;
COMMENT ON FUNCTION "public"."complete_officer_shift"(p_shift_id uuid, p_expected_status text, p_gps_lat double precision, p_gps_lng double precision) IS 'Ends the officer''s in-progress shift once the debrief is in and every stop, required task, dispatch job and welfare alert is closed. Optional GPS records where the shift ended (advisory evaluation) in the audit row.';
REVOKE ALL ON FUNCTION "public"."complete_officer_shift"(p_shift_id uuid, p_expected_status text, p_gps_lat double precision, p_gps_lng double precision) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."complete_officer_shift"(p_shift_id uuid, p_expected_status text, p_gps_lat double precision, p_gps_lng double precision) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."complete_officer_shift"(p_shift_id uuid, p_expected_status text, p_gps_lat double precision, p_gps_lng double precision) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."complete_officer_shift"(p_shift_id uuid, p_expected_status text, p_gps_lat double precision, p_gps_lng double precision) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."complete_officer_static_shift"(p_shift_id uuid, p_expected_status text, p_gps_lat double precision DEFAULT NULL::double precision, p_gps_lng double precision DEFAULT NULL::double precision, p_off_site_reason text DEFAULT NULL::text)
 RETURNS TABLE(shift_id uuid, shift_status text, completed_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_readiness jsonb; v_shift public.shifts%rowtype;
begin
  select * into v_shift from public.shifts where id = p_shift_id for update;
  v_readiness := public.get_officer_attendance_readiness(p_shift_id);
  if v_shift.status = 'completed' and v_shift.actual_end is not null
    and (v_readiness->>'single_site_attendance')::boolean
    and exists(select 1 from public.shift_stop_actions a
      where a.shift_id = p_shift_id and a.action_type = 'static_post_departed') then
    return query select v_shift.id, v_shift.status, v_shift.actual_end;
    return;
  end if;
  if not coalesce((v_readiness->>'single_site_attendance')::boolean,false)
    or not coalesce((v_readiness->>'can_end')::boolean,false) then raise exception 'Finish required work, break and debrief before ending this static shift'; end if;
  perform public.record_static_shift_presence(p_shift_id,'depart',gen_random_uuid(),p_gps_lat,p_gps_lng,p_off_site_reason);
  return query select * from public.complete_officer_shift(p_shift_id,p_expected_status,p_gps_lat,p_gps_lng);
end;
$function$;
REVOKE ALL ON FUNCTION "public"."complete_officer_static_shift"(p_shift_id uuid, p_expected_status text, p_gps_lat double precision, p_gps_lng double precision, p_off_site_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."complete_officer_static_shift"(p_shift_id uuid, p_expected_status text, p_gps_lat double precision, p_gps_lng double precision, p_off_site_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."complete_officer_static_shift"(p_shift_id uuid, p_expected_status text, p_gps_lat double precision, p_gps_lng double precision, p_off_site_reason text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."complete_patrol_session"(p_patrol_id uuid, p_notes text DEFAULT NULL::text)
 RETURNS patrols
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_profile public.user_profiles%rowtype;v_patrol record;v_result public.patrols%rowtype;
begin
  if v_actor is null then raise exception 'Authentication required';end if;
  select * into v_profile from public.user_profiles where id=v_actor and deactivated_at is null;
  if not found or v_profile.role not in('grand_master','master','admin','admin_officer','officer') then raise exception 'Active Patrol officer required';end if;
  select p.*,s.patrol_route_id,s.zone_id as shift_zone_id into v_patrol from public.patrols p join public.shifts s on s.id=p.shift_id where p.id=p_patrol_id for update of p;
  if not found or v_profile.organization_id is distinct from v_patrol.organization_id or v_patrol.officer_user_id is distinct from v_actor then raise exception 'Active assigned Patrol session not found';end if;
  if v_patrol.status='completed' then select * into v_result from public.patrols where id=p_patrol_id;return v_result;end if;
  if v_patrol.status<>'in_progress' then raise exception 'Patrol session is not in progress';end if;
  if exists(select 1 from public.patrol_route_checkpoints c where c.patrol_route_id=v_patrol.patrol_route_id and c.is_active and c.is_mandatory and not exists(select 1 from public.patrol_checkpoint_visits v where v.patrol_id=v_patrol.id and v.route_checkpoint_id=c.id)) then raise exception 'One or more mandatory checkpoints remain';end if;
  if not exists(select 1 from public.patrol_route_checkpoints c where c.patrol_route_id=v_patrol.patrol_route_id and c.is_active and c.is_mandatory) and exists(select 1 from public.patrol_checkpoints c where c.active and((c.zone_id is not null and c.zone_id=v_patrol.shift_zone_id)or exists(select 1 from public.shift_stops st where st.shift_id=v_patrol.shift_id and((c.client_site_id is not null and st.site_id=c.client_site_id)or(c.zone_id is not null and st.zone_id=c.zone_id))))and not exists(select 1 from public.patrol_checkpoint_visits v where v.patrol_id=v_patrol.id and v.checkpoint_id=c.id)) then raise exception 'One or more mandatory checkpoints remain';end if;
  update public.patrols set status='completed',ended_at=clock_timestamp(),notes=coalesce(nullif(trim(coalesce(p_notes,'')),''),notes) where id=v_patrol.id returning * into v_result;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_result.organization_id,v_actor,'patrol.completed','patrols',v_result.id,jsonb_build_object('shift_id',v_result.shift_id,'checkpoint_count',(select count(*) from public.patrol_checkpoint_visits where patrol_id=v_result.id)));
  return v_result;
end;$function$;
REVOKE ALL ON FUNCTION "public"."complete_patrol_session"(p_patrol_id uuid, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."complete_patrol_session"(p_patrol_id uuid, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."complete_patrol_session"(p_patrol_id uuid, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."complete_patrol_session"(p_patrol_id uuid, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."complete_performance_review"(p_review_id uuid, p_expected_status text, p_rating smallint, p_strengths text, p_development_goals text, p_employee_comments text DEFAULT NULL::text)
 RETURNS performance_reviews
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_review public.performance_reviews%rowtype;
begin
  select * into v_review from public.performance_reviews where id=p_review_id for update;
  if not found then raise exception 'Performance review not found'; end if;
  if v_review.reviewer_user_id<>v_actor and not public.is_admin_for_org(v_review.organization_id) then raise exception 'Only the reviewer or HR administrator can complete this review'; end if;
  if v_review.status<>p_expected_status then raise exception 'Performance review changed from expected status % to %',p_expected_status,v_review.status; end if;
  if v_review.status not in ('pending','in_progress') then raise exception 'Review is not available for completion'; end if;
  if p_rating not between 1 and 5 then raise exception 'Rating must be from 1 to 5'; end if;
  update public.performance_reviews set status='completed',rating=p_rating,strengths=nullif(trim(coalesce(p_strengths,'')),''),development_goals=nullif(trim(coalesce(p_development_goals,'')),''),employee_comments=nullif(trim(coalesce(p_employee_comments,'')),''),completed_at=now() where id=v_review.id returning * into v_review;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_review.organization_id,v_actor,'performance_review_completed','performance_reviews',v_review.id,jsonb_build_object('rating',p_rating));
  return v_review;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."complete_performance_review"(p_review_id uuid, p_expected_status text, p_rating smallint, p_strengths text, p_development_goals text, p_employee_comments text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."complete_performance_review"(p_review_id uuid, p_expected_status text, p_rating smallint, p_strengths text, p_development_goals text, p_employee_comments text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."complete_performance_review"(p_review_id uuid, p_expected_status text, p_rating smallint, p_strengths text, p_development_goals text, p_employee_comments text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."complete_performance_review"(p_review_id uuid, p_expected_status text, p_rating smallint, p_strengths text, p_development_goals text, p_employee_comments text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."complete_safety_review"(p_review_id uuid, p_outcome text, p_hazard_id uuid DEFAULT NULL::uuid, p_investigation_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_item public.safety_reviews%rowtype;
BEGIN
  SELECT * INTO v_item FROM public.safety_reviews WHERE id = p_review_id FOR UPDATE;
  IF NOT FOUND OR auth.uid() IS NULL OR NOT public.is_admin_for_org(v_item.organization_id) THEN
    RAISE EXCEPTION 'Safety review access denied';
  END IF;
  IF v_item.status <> 'open' THEN RAISE EXCEPTION 'Review already completed. Refresh to read its receipt'; END IF;
  IF length(btrim(coalesce(p_outcome, ''))) NOT BETWEEN 10 AND 4000 THEN
    RAISE EXCEPTION 'Record the findings, corrective action and reason for closing (10-4000 characters)';
  END IF;
  IF p_hazard_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.place_hazards h WHERE h.id = p_hazard_id
      AND h.organization_id = v_item.organization_id AND h.location_id = v_item.location_id
  ) THEN RAISE EXCEPTION 'Linked hazard must belong to the same organisation and place'; END IF;
  IF p_investigation_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM public.investigations WHERE id = p_investigation_id AND organization_id = v_item.organization_id) THEN
      RAISE EXCEPTION 'Linked investigation must belong to this organisation';
    END IF;
    IF v_item.field_report_id IS NOT NULL THEN
      PERFORM public.link_investigation_entity(p_investigation_id, 'field_report', v_item.field_report_id, 'primary', 'H&S review corrective action');
    ELSIF v_item.incident_id IS NOT NULL THEN
      PERFORM public.link_investigation_entity(p_investigation_id, 'incident', v_item.incident_id, 'primary', 'H&S review corrective action');
    END IF;
  END IF;
  UPDATE public.safety_reviews SET status = 'closed', outcome = btrim(p_outcome), hazard_id = p_hazard_id,
    investigation_id = p_investigation_id, reviewed_by = auth.uid(), reviewed_at = clock_timestamp() WHERE id = v_item.id;
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_item.organization_id, auth.uid(), 'safety_review_completed', 'safety_reviews', v_item.id,
    jsonb_build_object('hazard_id', p_hazard_id, 'investigation_id', p_investigation_id));
  IF v_item.assessment_id IS NOT NULL THEN
    PERFORM public.enqueue_notification(
      p_organization_id => v_item.organization_id, p_category => 'system',
      p_title => 'Your task risk assessment has been reviewed',
      p_body => 'Read the supervisor findings in your shift safety assessments. An unsafe assessment stays on record; reassess before resuming that task.',
      p_recipient_user_id => (SELECT officer_id FROM public.dynamic_risk_assessments WHERE id = v_item.assessment_id),
      p_link_page => 'safety-assessments', p_link_payload => jsonb_build_object('assessment_id', v_item.assessment_id),
      p_dedup_key => 'assessment_reviewed:' || v_item.id::text
    );
  END IF;
  RETURN v_item.id;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."complete_safety_review"(p_review_id uuid, p_outcome text, p_hazard_id uuid, p_investigation_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."complete_safety_review"(p_review_id uuid, p_outcome text, p_hazard_id uuid, p_investigation_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."complete_safety_review"(p_review_id uuid, p_outcome text, p_hazard_id uuid, p_investigation_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."complete_safety_review"(p_review_id uuid, p_outcome text, p_hazard_id uuid, p_investigation_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."complete_shift_stop"(p_stop_id uuid, p_officer_notes text DEFAULT NULL::text, p_gps_lat double precision DEFAULT NULL::double precision, p_gps_lng double precision DEFAULT NULL::double precision)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_stop record;
begin
  select * into v_stop from shift_stops where id = p_stop_id;
  if not found then
    raise exception 'Shift stop % not found', p_stop_id;
  end if;

  update shift_stops
  set status              = 'completed',
      sla_status          = case
                              when actual_arrived_at is null then 'completed'
                              when actual_arrived_at > sla_arrive_by then 'breached'
                              else 'completed'
                            end,
      actual_departed_at  = now(),
      officer_notes       = coalesce(p_officer_notes, officer_notes),
      updated_at          = now()
  where id = p_stop_id;

  -- Increment completed_stops on the shift.
  update shifts
  set completed_stops = completed_stops + 1
  where id = v_stop.shift_id;
end;
$function$;
COMMENT ON FUNCTION "public"."complete_shift_stop"(p_stop_id uuid, p_officer_notes text, p_gps_lat double precision, p_gps_lng double precision) IS 'Marks a shift stop as completed and updates shift progress counters.';
REVOKE ALL ON FUNCTION "public"."complete_shift_stop"(p_stop_id uuid, p_officer_notes text, p_gps_lat double precision, p_gps_lng double precision) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."complete_shift_stop"(p_stop_id uuid, p_officer_notes text, p_gps_lat double precision, p_gps_lng double precision) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."complete_shift_stop"(p_stop_id uuid, p_officer_notes text, p_gps_lat double precision, p_gps_lng double precision) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."compute_travel_distance_km"(p_from_lat double precision, p_from_lng double precision, p_to_lat double precision, p_to_lng double precision)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case
    when p_from_lat is null or p_from_lng is null or p_to_lat is null or p_to_lng is null then null
    else round((
      6371.0088 * 2 * asin(sqrt(
        power(sin(radians(p_to_lat - p_from_lat) / 2), 2)
        + cos(radians(p_from_lat)) * cos(radians(p_to_lat))
          * power(sin(radians(p_to_lng - p_from_lng) / 2), 2)
      ))
    )::numeric, 3)
  end;
$function$;
REVOKE ALL ON FUNCTION "public"."compute_travel_distance_km"(p_from_lat double precision, p_from_lng double precision, p_to_lat double precision, p_to_lng double precision) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."compute_travel_distance_km"(p_from_lat double precision, p_from_lng double precision, p_to_lat double precision, p_to_lng double precision) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."compute_travel_distance_km"(p_from_lat double precision, p_from_lng double precision, p_to_lat double precision, p_to_lng double precision) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."compute_travel_distance_km"(p_from_lat double precision, p_from_lng double precision, p_to_lat double precision, p_to_lng double precision) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."confirm_cctv_vehicle_attributes"(p_observation_id uuid, p_action text, p_make text DEFAULT NULL::text, p_model text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_request_id text DEFAULT NULL::text, p_colour text DEFAULT NULL::text, p_body_type text DEFAULT NULL::text, p_year integer DEFAULT NULL::integer)
 RETURNS cctv_entity_observations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_obs public.cctv_entity_observations%rowtype;
  v_org uuid;
  v_actor uuid := auth.uid();
  v_action text := lower(trim(coalesce(p_action, '')));
  v_existing_request uuid;
  v_final_make text;
  v_final_model text;
  v_final_colour text;
  v_final_body_type text;
  v_final_year integer;
  v_reviewed_fields jsonb := '[]'::jsonb;
  v_vehicle uuid;
  v_plate text;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF v_action NOT IN ('confirm', 'correct', 'reject') THEN
    RAISE EXCEPTION 'Action must be confirm, correct, or reject';
  END IF;
  IF p_year IS NOT NULL AND (p_year < 1886 OR p_year > extract(year FROM current_date)::integer + 2) THEN
    RAISE EXCEPTION 'Vehicle year is outside the supported range';
  END IF;

  SELECT * INTO v_obs
  FROM public.cctv_entity_observations
  WHERE id = p_observation_id
    AND entity_kind = 'vehicle'
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Vehicle observation not found'; END IF;
  v_org := v_obs.organization_id;

  IF NOT public.is_admin_for_org(v_org) THEN
    RAISE EXCEPTION 'Vehicle attribute review requires manager access';
  END IF;

  IF nullif(trim(coalesce(p_request_id, '')), '') IS NOT NULL THEN
    SELECT id INTO v_existing_request
    FROM public.audit_log
    WHERE organization_id = v_org
      AND action = 'cctv_vehicle_attributes_reviewed'
      AND metadata->>'request_id' = trim(p_request_id)
    LIMIT 1;
    IF v_existing_request IS NOT NULL THEN RETURN v_obs; END IF;
  END IF;

  IF v_action = 'correct'
     AND nullif(trim(coalesce(p_make, '')), '') IS NULL
     AND nullif(trim(coalesce(p_model, '')), '') IS NULL
     AND nullif(trim(coalesce(p_colour, '')), '') IS NULL
     AND nullif(trim(coalesce(p_body_type, '')), '') IS NULL
     AND p_year IS NULL THEN
    RAISE EXCEPTION 'A correction requires at least one corrected attribute';
  END IF;

  IF v_action IN ('confirm', 'correct') THEN
    v_final_make := coalesce(nullif(trim(p_make), ''), nullif(trim(v_obs.attributes->>'make'), ''));
    v_final_model := coalesce(nullif(trim(p_model), ''), nullif(trim(v_obs.attributes->>'model'), ''));
    v_final_colour := coalesce(nullif(trim(p_colour), ''), nullif(trim(v_obs.attributes->>'colour'), ''));
    v_final_body_type := coalesce(nullif(trim(p_body_type), ''), nullif(trim(v_obs.attributes->>'body_type'), ''));
    v_final_year := coalesce(
      p_year,
      CASE WHEN v_obs.attributes->>'year' ~ '^[0-9]{4}$' THEN (v_obs.attributes->>'year')::integer END
    );

    IF v_final_make IS NOT NULL THEN v_reviewed_fields := v_reviewed_fields || jsonb_build_array('make'); END IF;
    IF v_final_model IS NOT NULL THEN v_reviewed_fields := v_reviewed_fields || jsonb_build_array('model'); END IF;
    IF v_final_colour IS NOT NULL THEN v_reviewed_fields := v_reviewed_fields || jsonb_build_array('colour'); END IF;
    IF v_final_body_type IS NOT NULL THEN v_reviewed_fields := v_reviewed_fields || jsonb_build_array('body_type'); END IF;
    IF v_final_year IS NOT NULL THEN v_reviewed_fields := v_reviewed_fields || jsonb_build_array('year'); END IF;
    IF jsonb_array_length(v_reviewed_fields) = 0 THEN
      RAISE EXCEPTION 'No vehicle attributes are available to review';
    END IF;
  END IF;

  UPDATE public.cctv_entity_observations
  SET attributes = attributes
        || CASE WHEN v_action IN ('confirm', 'correct') THEN jsonb_strip_nulls(jsonb_build_object(
             'make', v_final_make,
             'model', v_final_model,
             'colour', v_final_colour,
             'body_type', v_final_body_type,
             'year', v_final_year,
             'make_model_source', CASE WHEN v_final_make IS NOT NULL OR v_final_model IS NOT NULL THEN 'human_confirmed' END,
             'vehicle_attribute_source', CASE WHEN v_final_colour IS NOT NULL OR v_final_body_type IS NOT NULL OR v_final_year IS NOT NULL THEN 'human_confirmed' END
           )) ELSE '{}'::jsonb END
        || jsonb_build_object('make_model_review', jsonb_strip_nulls(jsonb_build_object(
             'status', CASE v_action WHEN 'confirm' THEN 'confirmed' WHEN 'correct' THEN 'corrected' ELSE 'rejected' END,
             'reviewed_at', clock_timestamp(),
             'reviewed_by', v_actor,
             'notes', nullif(trim(p_notes), ''),
             'reviewed_fields', CASE WHEN v_action = 'reject' THEN jsonb_build_array('make','model','colour','body_type','year') ELSE v_reviewed_fields END,
             'values', CASE WHEN v_action = 'reject' THEN NULL ELSE jsonb_strip_nulls(jsonb_build_object(
               'make', v_final_make,
               'model', v_final_model,
               'colour', v_final_colour,
               'body_type', v_final_body_type,
               'year', v_final_year
             )) END
           )))
  WHERE id = v_obs.id
  RETURNING * INTO v_obs;

  IF v_action IN ('confirm', 'correct') THEN
    v_plate := public.normalize_plate_number(v_obs.candidate_plate);
    IF v_plate IS NOT NULL THEN
      v_vehicle := coalesce(
        v_obs.canonical_vehicle_id,
        public.ensure_canonical_vehicle(
          v_plate, NULL, NULL, NULL,
          'cctv_entity_observations', v_obs.id::text, v_obs.observed_at
        )
      );
      IF v_vehicle IS NOT NULL THEN
        UPDATE public.canonical_vehicles
        SET make = coalesce(v_final_make, make),
            model = coalesce(v_final_model, model),
            colour = coalesce(v_final_colour, colour),
            body_type = coalesce(v_final_body_type, body_type),
            year = coalesce(v_final_year, year),
            updated_at = clock_timestamp()
        WHERE id = v_vehicle;
      END IF;
    END IF;
  END IF;

  INSERT INTO public.audit_log (
    organization_id, actor_user_id, action, target_table, target_id, metadata
  ) VALUES (
    v_org, v_actor, 'cctv_vehicle_attributes_reviewed',
    'cctv_entity_observations', v_obs.id,
    jsonb_strip_nulls(jsonb_build_object(
      'review_action', v_action,
      'request_id', nullif(trim(p_request_id), ''),
      'reviewed_fields', CASE WHEN v_action = 'reject' THEN jsonb_build_array('make','model','colour','body_type','year') ELSE v_reviewed_fields END,
      'values', CASE WHEN v_action = 'reject' THEN NULL ELSE v_obs.attributes->'make_model_review'->'values' END,
      'canonical_vehicle_id', v_vehicle
    ))
  );
  RETURN v_obs;
END;
$function$;
COMMENT ON FUNCTION "public"."confirm_cctv_vehicle_attributes"(p_observation_id uuid, p_action text, p_make text, p_model text, p_notes text, p_request_id text, p_colour text, p_body_type text, p_year integer) IS 'The sole human authority for CCTV-derived make, model, colour, body type and year. Review requires the established organization administrator access predicate.';
REVOKE ALL ON FUNCTION "public"."confirm_cctv_vehicle_attributes"(p_observation_id uuid, p_action text, p_make text, p_model text, p_notes text, p_request_id text, p_colour text, p_body_type text, p_year integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."confirm_cctv_vehicle_attributes"(p_observation_id uuid, p_action text, p_make text, p_model text, p_notes text, p_request_id text, p_colour text, p_body_type text, p_year integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."confirm_cctv_vehicle_attributes"(p_observation_id uuid, p_action text, p_make text, p_model text, p_notes text, p_request_id text, p_colour text, p_body_type text, p_year integer) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."confirm_cctv_vehicle_attributes"(p_observation_id uuid, p_action text, p_make text, p_model text, p_notes text, p_request_id text, p_colour text, p_body_type text, p_year integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."confirm_cctv_weapon_hint"(p_observation_id uuid, p_status text, p_notes text DEFAULT NULL::text)
 RETURNS cctv_entity_observations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_obs public.cctv_entity_observations%rowtype;
  v_review jsonb;
BEGIN
  SELECT * INTO v_obs FROM public.cctv_entity_observations WHERE id = p_observation_id FOR UPDATE;
  IF v_obs.id IS NULL THEN RAISE EXCEPTION 'CCTV observation not found'; END IF;
  IF v_actor IS NULL OR NOT public.org_access_allowed(v_obs.organization_id) THEN RAISE EXCEPTION 'CCTV review access denied'; END IF;
  IF v_obs.entity_kind <> 'person' THEN RAISE EXCEPTION 'Only a person observation carries a weapon hint'; END IF;
  IF v_obs.attributes->'weapon_hint' IS NULL THEN RAISE EXCEPTION 'This observation has no weapon hint to review'; END IF;
  IF p_status NOT IN ('confirmed', 'dismissed') THEN RAISE EXCEPTION 'Unsupported weapon hint status %', p_status; END IF;

  v_review := jsonb_build_object('status', p_status, 'reviewed_by', v_actor, 'reviewed_at', clock_timestamp(), 'notes', nullif(trim(p_notes), ''));

  UPDATE public.cctv_entity_observations
     SET attributes = jsonb_set(attributes, '{weapon_hint,review}', v_review, true)
   WHERE id = v_obs.id
   RETURNING * INTO v_obs;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_obs.organization_id, v_actor, 'cctv_weapon_hint_' || p_status, 'cctv_entity_observations', v_obs.id, '{}'::jsonb);

  v_obs.face_vec := NULL; v_obs.appearance_vec := NULL; v_obs.candidate_embedding := NULL; v_obs.appearance_embedding := NULL;
  RETURN v_obs;
END;
$function$;
COMMENT ON FUNCTION "public"."confirm_cctv_weapon_hint"(p_observation_id uuid, p_status text, p_notes text) IS 'Reviewer confirm/dismiss of a person observation weapon vision-LLM hint. Records the human decision only - never writes any other table, never triggers alerting/escalation.';
REVOKE ALL ON FUNCTION "public"."confirm_cctv_weapon_hint"(p_observation_id uuid, p_status text, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."confirm_cctv_weapon_hint"(p_observation_id uuid, p_status text, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."confirm_cctv_weapon_hint"(p_observation_id uuid, p_status text, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."confirm_cctv_weapon_hint"(p_observation_id uuid, p_status text, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."confirm_file_import_profile_mappings"(p_batch_id uuid, p_reason text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid:=auth.uid();
  v_batch public.file_import_batches%rowtype;
  v_profile public.import_source_profiles%rowtype;
  v_review public.file_import_mapping_reviews%rowtype;
  v_logical_field text;
  v_expected jsonb;
  v_count integer:=0;
BEGIN
  IF nullif(trim(coalesce(p_reason,'')),'') IS NULL THEN RAISE EXCEPTION 'Mapping confirmation reason is required'; END IF;
  SELECT * INTO v_batch FROM public.file_import_batches WHERE id=p_batch_id FOR UPDATE;
  IF NOT FOUND OR v_batch.status NOT IN ('staging','needs_review') OR NOT public.is_tenant_import_admin(v_batch.organization_id) THEN
    RAISE EXCEPTION 'Open tenant import review batch required';
  END IF;
  SELECT * INTO v_profile FROM public.import_source_profiles
  WHERE organization_id=v_batch.organization_id AND profile_code=v_batch.manifest_json->>'source_profile' AND active;
  IF NOT FOUND THEN RAISE EXCEPTION 'Active source profile required'; END IF;

  FOR v_review IN SELECT * FROM public.file_import_mapping_reviews WHERE batch_id=v_batch.id AND decision='proposed' FOR UPDATE LOOP
    SELECT mapping.key INTO v_logical_field
    FROM jsonb_each(v_profile.column_mappings) mapping
    CROSS JOIN LATERAL jsonb_array_elements_text(mapping.value) alias
    WHERE regexp_replace(lower(alias),'\s+',' ','g')
      =regexp_replace(lower(regexp_replace(v_review.source_column,' #[0-9]+$','')),'\s+',' ','g')
    LIMIT 1;
    v_expected:=v_profile.target_mappings->v_logical_field;
    IF v_logical_field IS NULL OR v_expected IS NULL
      OR v_review.target_entity IS DISTINCT FROM v_expected->>'target_entity'
      OR v_review.target_field IS DISTINCT FROM v_expected->>'target_field' THEN
      RAISE EXCEPTION 'Source column % does not exactly match the active import profile',v_review.source_column;
    END IF;
    UPDATE public.file_import_mapping_reviews
    SET decision='confirmed',review_reason=trim(p_reason),reviewed_by=v_actor,reviewed_at=now(),updated_at=now()
    WHERE id=v_review.id;
    v_count:=v_count+1;
  END LOOP;
  INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
  VALUES(v_batch.organization_id,v_actor,'file_import_profile_mappings_confirmed','file_import_batches',v_batch.id,
    jsonb_build_object('confirmed_count',v_count,'source_profile',v_profile.profile_code,'reason',trim(p_reason)));
  RETURN v_count;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."confirm_file_import_profile_mappings"(p_batch_id uuid, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."confirm_file_import_profile_mappings"(p_batch_id uuid, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."confirm_file_import_profile_mappings"(p_batch_id uuid, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."confirm_file_import_profile_mappings"(p_batch_id uuid, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."consume_bob_signing_nonce"(p_nonce text, p_expires_at timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_now timestamp with time zone := now();
  v_ok boolean := false;
begin
  if p_nonce is null or length(trim(p_nonce)) < 16 then
    return false;
  end if;

  if p_expires_at is null or p_expires_at <= v_now or p_expires_at > (v_now + interval '10 minutes') then
    return false;
  end if;

  delete from public.bob_signing_nonces where expires_at < v_now;

  insert into public.bob_signing_nonces (nonce, expires_at)
  values (p_nonce, p_expires_at)
  on conflict (nonce) do nothing;

  get diagnostics v_ok = row_count;
  return coalesce(v_ok, false);
end;
$function$;
REVOKE ALL ON FUNCTION "public"."consume_bob_signing_nonce"(p_nonce text, p_expires_at timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."consume_bob_signing_nonce"(p_nonce text, p_expires_at timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."consume_bob_signing_nonce"(p_nonce text, p_expires_at timestamp with time zone) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."consume_workload_token"(p_jti uuid, p_job_id uuid, p_org_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.role() <> 'service_role' AND session_user <> 'postgres' THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;

  IF p_jti IS NULL OR p_job_id IS NULL OR p_org_id IS NULL THEN
    RAISE EXCEPTION 'Token, job, and organization identifiers are required';
  END IF;

  INSERT INTO public.consumed_job_tokens (
    jti,
    inference_job_id,
    organization_id
  )
  VALUES (
    p_jti,
    p_job_id,
    p_org_id
  )
  ON CONFLICT (jti) DO NOTHING;

  RETURN FOUND;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."consume_workload_token"(p_jti uuid, p_job_id uuid, p_org_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."consume_workload_token"(p_jti uuid, p_job_id uuid, p_org_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."consume_workload_token"(p_jti uuid, p_job_id uuid, p_org_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."continuity_party_on_duty"(p_start time without time zone, p_end time without time zone, p_at timestamp with time zone)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  SELECT CASE
    WHEN p_start IS NULL OR p_end IS NULL OR p_start = p_end THEN true
    WHEN p_start < p_end THEN (p_at AT TIME ZONE 'Pacific/Auckland')::time >= p_start AND (p_at AT TIME ZONE 'Pacific/Auckland')::time < p_end
    ELSE (p_at AT TIME ZONE 'Pacific/Auckland')::time >= p_start OR (p_at AT TIME ZONE 'Pacific/Auckland')::time < p_end
  END;
$function$;
REVOKE ALL ON FUNCTION "public"."continuity_party_on_duty"(p_start time without time zone, p_end time without time zone, p_at timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."continuity_party_on_duty"(p_start time without time zone, p_end time without time zone, p_at timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."continuity_party_on_duty"(p_start time without time zone, p_end time without time zone, p_at timestamp with time zone) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."convert_recruitment_candidate_to_staff"(p_candidate_id uuid, p_user_id uuid, p_staff_id uuid, p_note text)
 RETURNS TABLE(candidate_id uuid, onboarding_ledger_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid := auth.uid(); v_candidate public.recruitment_candidates%rowtype; v_staff public.staff_profiles%rowtype; v_ledger public.staff_onboarding_ledgers%rowtype; v_note text := nullif(trim(coalesce(p_note,'')), '');
begin
  select * into v_candidate from public.recruitment_candidates where id=p_candidate_id for update;
  if not found or not public.is_admin_for_org(v_candidate.organization_id) then raise exception 'Candidate not found in your organization'; end if;
  if v_candidate.stage<>'offer' or v_candidate.status<>'offered' then raise exception 'Only an offered candidate can be converted'; end if;
  if v_note is null then raise exception 'A conversion note is required'; end if;
  select * into v_staff from public.staff_profiles where id=p_staff_id and user_id=p_user_id and organization_id=v_candidate.organization_id;
  if not found then raise exception 'Provisioned user and staff records must belong to the recruiting organization'; end if;
  update public.recruitment_candidates set stage='hired',status='hired',offer_accepted_at=now(),provisioned_user_id=p_user_id,provisioned_staff_id=p_staff_id where id=v_candidate.id returning * into v_candidate;
  select * into v_ledger from public.staff_onboarding_ledgers where staff_id=v_staff.id;
  if not found then
    insert into public.staff_onboarding_ledgers(organization_id,staff_id,stage_note,target_start) values(v_candidate.organization_id,v_staff.id,v_note,v_candidate.offer_start_date) returning * into v_ledger;
    insert into public.staff_onboarding_events(ledger_id,organization_id,to_stage,to_status,note,actor_user_id,version) values(v_ledger.id,v_ledger.organization_id,'identity','in_progress',v_note,v_actor,v_ledger.version);
  end if;
  insert into public.recruitment_candidate_events(candidate_id,organization_id,from_stage,to_stage,note,actor_user_id) values(v_candidate.id,v_candidate.organization_id,'offer','hired',v_note,v_actor);
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_candidate.organization_id,v_actor,'recruitment_candidate_converted','recruitment_candidates',v_candidate.id,jsonb_build_object('user_id',p_user_id,'staff_id',p_staff_id,'onboarding_ledger_id',v_ledger.id));
  return query select v_candidate.id,v_ledger.id;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."convert_recruitment_candidate_to_staff"(p_candidate_id uuid, p_user_id uuid, p_staff_id uuid, p_note text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."convert_recruitment_candidate_to_staff"(p_candidate_id uuid, p_user_id uuid, p_staff_id uuid, p_note text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."convert_recruitment_candidate_to_staff"(p_candidate_id uuid, p_user_id uuid, p_staff_id uuid, p_note text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."convert_recruitment_candidate_to_staff"(p_candidate_id uuid, p_user_id uuid, p_staff_id uuid, p_note text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."correct_legacy_patrol_source_records"(p_batch_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_records jsonb)
 RETURNS TABLE(external_ref text, record_id uuid, outcome text, detail text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_batch public.file_import_batches%rowtype;
  v_item jsonb;
  v_desired jsonb;
  v_payload jsonb;
  v_kind text;
  v_ref text;
  v_id uuid;
  v_event public.location_events%rowtype;
  v_observation public.observations%rowtype;
  v_existing jsonb;
  v_stored_at timestamptz;
  v_stored_distance numeric;
  v_version public.patrol_import_record_versions%rowtype;
  v_occurred timestamptz;
  v_distance numeric;
  v_offset interval;
  v_mismatch text[];
  v_source_leg jsonb;
  v_hold text;
  v_before jsonb;
  v_after jsonb;
  v_changed text[];
  v_context_moved integer;
  v_context_id uuid;
  -- Provenance from an earlier workbook version is replaced, not compared.
  v_provenance constant text[] := array['source', 'source_file', 'source_sheet', 'source_row', 'source_sha256',
    'derivative_sha256', 'classification_profile'];
begin
  v_batch := public.patrol_source_sync_batch(p_batch_id, p_provider_organization_id, p_client_organization_id);
  if jsonb_typeof(p_records) <> 'array' or jsonb_array_length(p_records) > 500 then
    raise exception 'Between 0 and 500 legacy correction rows are required per call';
  end if;

  for v_item in
    select value from jsonb_array_elements(p_records) value order by value->>'kind', value->>'external_ref'
  loop
    v_payload := public.patrol_source_assert_row_provenance(v_batch, v_item);
    v_kind := v_item->>'kind';
    if v_kind is null or v_kind not in ('event', 'observation') then
      raise exception 'Legacy correction applies to patrol events and observations only';
    end if;
    v_ref := v_item->>'external_ref';
    v_id := (v_item->>'record_id')::uuid;
    v_desired := v_item->'desired';
    v_hold := null;
    perform pg_advisory_xact_lock(hashtextextended(p_client_organization_id::text || ':evidence:' || v_ref, 0));

    if v_kind = 'event' then
      select * into v_event from public.location_events event
      where event.id = v_id and event.organization_id = p_client_organization_id
        and event.external_ref = v_ref and event.source = 'rm_patrol_log_import'
      for update;
      if found then
        v_existing := coalesce(v_event.payload, '{}'::jsonb);
        v_stored_at := v_event.occurred_at;
        v_stored_distance := v_event.distance_km;
      end if;
    else
      select * into v_observation from public.observations observation
      where observation.id = v_id and observation.organization_id = p_client_organization_id
        and observation.external_refs->>'external_ref' = v_ref
        and coalesce(observation.external_refs->'import'->>'source', 'rm_patrol_log_import') = 'rm_patrol_log_import'
      for update;
      if found then
        v_existing := coalesce(v_observation.external_refs->'import', '{}'::jsonb);
        v_stored_at := v_observation.observed_at;
        v_stored_distance := v_observation.distance_km;
      end if;
    end if;
    if not found then
      external_ref := v_ref; record_id := v_id; outcome := 'held'; detail := 'record_not_owned_by_importer';
      return next; continue;
    end if;

    select * into v_version from public.patrol_import_record_versions version
    where version.record_kind = v_kind and version.record_id = v_id and version.is_current;
    if found then
      external_ref := v_ref; record_id := v_id;
      if v_version.change_kind = 'legacy_correction' and v_version.source_fingerprint = v_item->>'source_fingerprint' then
        outcome := 'already_current'; detail := null;
      else
        outcome := 'held'; detail := 'source_history_already_recorded';
      end if;
      return next; continue;
    end if;

    -- Provenance-free (pre-provenance import) or already naming this same workbook and sheet.
    if (nullif(v_existing->>'source_file', '') is not null and v_existing->>'source_file' is distinct from v_payload->>'source_file')
       or (nullif(v_existing->>'source_sheet', '') is not null and v_existing->>'source_sheet' is distinct from v_payload->>'source_sheet') then
      v_hold := 'existing_source_identity_mismatch';
    end if;

    if v_hold is null and v_kind = 'observation' and v_observation.locked_at is not null then
      v_hold := 'locked_evidence_requires_correction_review';
    end if;

    if v_hold is null then
      if v_kind = 'event' then
        select coalesce(array_agg(field order by field), '{}'::text[]) into v_mismatch
        from (
          select 'zone_id' as field where v_event.zone_id is distinct from nullif(v_desired->>'zone_id', '')::uuid
          union all select 'site_id' where v_event.client_site_id is distinct from nullif(v_desired->>'site_id', '')::uuid
          union all select 'officer_id' where v_event.observed_entity_id is distinct from nullif(v_desired->>'observed_entity_id', '')::uuid
          union all select 'observed_entity_type' where v_event.observed_entity_type is distinct from v_desired->>'observed_entity_type'
          union all select 'event_type' where v_event.event_type is distinct from v_desired->>'event_type'
          union all select 'status' where v_event.status is distinct from v_desired->>'status'
        ) identity_fields;
      else
        select coalesce(array_agg(field order by field), '{}'::text[]) into v_mismatch
        from (
          select 'zone_id' as field where v_observation.zone_id is distinct from nullif(v_desired->>'zone_id', '')::uuid
          union all select 'site_id' where v_observation.site_id is distinct from nullif(v_desired->>'site_id', '')::uuid
          union all select 'officer_id' where v_observation.officer_id is distinct from nullif(v_desired->>'officer_id', '')::uuid
          union all select 'plate' where upper(v_observation.plate_number) is distinct from upper(v_desired->>'plate')
          union all select 'officer_notes' where v_observation.officer_notes is distinct from v_desired->>'officer_notes'
        ) identity_fields;
      end if;
      if cardinality(v_mismatch) > 0 then
        v_hold := 'legacy_identity_difference:' || array_to_string(v_mismatch, ',');
      end if;
    end if;

    if v_hold is null then
      v_occurred := (v_desired->>'occurred_at')::timestamptz;
      -- The legacy importer used a fixed +12 offset, so NZDT visits were stored one hour late.
      v_offset := (v_occurred at time zone 'Pacific/Auckland') - (v_occurred at time zone 'UTC');
      if not (v_stored_at = v_occurred
              or (v_stored_at = v_occurred + interval '1 hour' and v_offset = interval '13 hours')) then
        v_hold := 'legacy_time_difference_not_offset_artifact';
      end if;
    end if;

    if v_hold is null then
      -- A recorded source-leg correction keeps the sheet's original values; legacy rows that still hold
      -- those values are the same source facts, not a conflicting edit.
      v_source_leg := case when v_payload->'source_leg_correction'->>'rule' = 'formula_skipped_start_row'
          and coalesce(v_payload->'source_leg_correction'->>'job_kms', '') ~ '^-[0-9]+([.][0-9]+)?$'
        then v_payload->'source_leg_correction' end;
      v_distance := case when v_desired->'distance_km' is null or jsonb_typeof(v_desired->'distance_km') = 'null'
        then null else (v_desired->>'distance_km')::numeric end;
      if v_distance is not null and v_distance < 0 then
        v_hold := 'invalid_source_distance';
      elsif v_stored_distance is not null and v_stored_distance is distinct from v_distance
        and not (v_source_leg is not null and v_stored_distance = (v_source_leg->>'job_kms')::numeric) then
        v_hold := 'legacy_distance_difference';
      end if;
    end if;

    if v_hold is null then
      -- Stored values must equal the sheet (numerically for legacy text numbers); objects may only
      -- have gained keys. Null or missing stored values are filled from the sheet.
      select coalesce(array_agg(key order by key), '{}'::text[]) into v_mismatch
      from jsonb_each(v_existing) existing
      where existing.key <> all (v_provenance)
        and jsonb_typeof(existing.value) <> 'null'
        and existing.value is distinct from v_payload->existing.key
        and not public.patrol_source_numeric_text_equal(existing.value, v_payload->existing.key)
        and not coalesce(jsonb_typeof(existing.value) = 'object' and jsonb_typeof(v_payload->existing.key) = 'object'
          and (v_payload->existing.key) @> existing.value, false)
        and not (coalesce(v_source_leg ? existing.key, false)
          and (existing.value = v_source_leg->existing.key
            or public.patrol_source_numeric_text_equal(existing.value, v_source_leg->existing.key)));
      if cardinality(v_mismatch) > 0 then
        v_hold := 'legacy_payload_difference:' || array_to_string(v_mismatch, ',');
      end if;
    end if;

    if v_hold is null then
      v_hold := public.patrol_source_correction_dependency_hold(
        p_provider_organization_id, p_client_organization_id, v_kind, v_id, v_ref, p_batch_id,
        (v_stored_at at time zone 'Pacific/Auckland')::date = (v_occurred at time zone 'Pacific/Auckland')::date);
    end if;

    -- An observation's timeline context event moves with it, so anything published from or
    -- linked to that event (continuity handoffs, incidents, evidence) must be clear first.
    if v_hold is null and v_kind = 'observation' then
      for v_context_id in
        select context_event.id from public.location_events context_event
        where context_event.organization_id = p_client_organization_id
          and context_event.source = 'observation_trigger'
          and context_event.external_ref = v_id::text
          and context_event.occurred_at = v_stored_at
        order by context_event.id
        for update
      loop
        v_hold := public.patrol_source_correction_dependency_hold(
          p_provider_organization_id, p_client_organization_id, 'event', v_context_id, v_ref, p_batch_id,
          (v_stored_at at time zone 'Pacific/Auckland')::date = (v_occurred at time zone 'Pacific/Auckland')::date);
        if v_hold is not null then
          v_hold := 'context_event_' || v_hold;
          exit;
        end if;
      end loop;
    end if;

    if v_hold is not null then
      external_ref := v_ref; record_id := v_id; outcome := 'held'; detail := v_hold;
      return next; continue;
    end if;

    v_before := public.patrol_source_record_state(v_kind, v_id);
    v_context_moved := 0;
    if v_kind = 'event' then
      update public.location_events event
      set occurred_at = v_occurred,
          distance_km = v_distance,
          payload = coalesce(event.payload, '{}'::jsonb) || v_payload
      where event.id = v_id;
    else
      update public.observations observation
      set observed_at = v_occurred,
          distance_km = v_distance,
          external_refs = jsonb_set(coalesce(observation.external_refs, '{}'::jsonb), '{import}',
            coalesce(observation.external_refs->'import', '{}'::jsonb) || v_payload, true)
      where observation.id = v_id;
      -- The observation's timeline context event was written from the same stored time.
      update public.location_events context_event
      set occurred_at = v_occurred
      where context_event.organization_id = p_client_organization_id
        and context_event.source = 'observation_trigger'
        and context_event.external_ref = v_id::text
        and context_event.occurred_at = v_stored_at;
      get diagnostics v_context_moved = row_count;
    end if;
    v_after := public.patrol_source_record_state(v_kind, v_id);
    v_changed := public.patrol_source_state_diff(v_before, v_after);

    insert into public.patrol_import_record_versions(
      provider_organization_id, client_organization_id, record_kind, record_id, external_ref, source_profile,
      source_file, source_sheet, source_row, source_sha256, derivative_sha256, source_fingerprint, batch_id,
      version_no, change_kind, changed_fields, state_before, state_after, applied_by
    ) values (
      p_provider_organization_id, p_client_organization_id, v_kind, v_id, v_ref, v_payload->>'classification_profile',
      v_payload->>'source_file', v_payload->>'source_sheet', (v_payload->>'source_row')::integer,
      v_payload->>'source_sha256', v_payload->>'derivative_sha256', v_item->>'source_fingerprint', p_batch_id,
      1, 'legacy_correction', v_changed, v_before, v_after, auth.uid()
    );

    insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
    values (p_provider_organization_id, auth.uid(), 'patrol_legacy_source_corrected',
      case v_kind when 'event' then 'location_events' else 'observations' end, v_id,
      jsonb_build_object('batch_id', p_batch_id, 'client_organization_id', p_client_organization_id,
        'record_kind', v_kind, 'external_ref', v_ref, 'changed_fields', to_jsonb(v_changed),
        'time_shift_seconds', extract(epoch from (v_before->>'occurred_at')::timestamptz - v_occurred),
        'context_events_moved', v_context_moved,
        'finance_cost_rows_linked', (select count(*) from public.file_import_finance_cost_rows cost_row
          where cost_row.client_organization_id = p_client_organization_id and cost_row.evidence_external_ref = v_ref),
        'prior_source_sha256', v_existing->>'source_sha256',
        'source_file', v_payload->>'source_file', 'source_sheet', v_payload->>'source_sheet',
        'source_row', (v_payload->>'source_row')::integer, 'source_sha256', v_payload->>'source_sha256',
        'ruling', 'R&M workbooks are verified source truth (owner ruling 2026-10-30)'));

    external_ref := v_ref; record_id := v_id; outcome := 'corrected'; detail := array_to_string(v_changed, ',');
    return next;
  end loop;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."correct_legacy_patrol_source_records"(p_batch_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_records jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."correct_legacy_patrol_source_records"(p_batch_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_records jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."correct_legacy_patrol_source_records"(p_batch_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_records jsonb) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."correct_timesheet_hours"(p_timesheet_id uuid, p_expected_status text, p_actual_hours numeric, p_overtime_hours numeric, p_reason text)
 RETURNS timesheets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_sheet public.timesheets%rowtype;
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
  v_previous_actual numeric;
begin
  if v_reason is null then raise exception 'A correction reason is required'; end if;
  if p_actual_hours is null or p_actual_hours < 0 or p_actual_hours > 744 then raise exception 'Actual hours are outside the accepted range'; end if;
  if p_overtime_hours is null or p_overtime_hours < 0 or p_overtime_hours > p_actual_hours then raise exception 'Overtime hours are outside the accepted range'; end if;
  select t.* into v_sheet from public.timesheets t where t.id = p_timesheet_id for update;
  if not found then raise exception 'Timesheet not found'; end if;
  if not public.is_admin_for_org(v_sheet.organization_id) then raise exception 'Not authorised to correct this timesheet'; end if;
  if v_sheet.status <> p_expected_status or v_sheet.status not in ('submitted', 'branch_checked') then raise exception 'Only submitted or branch-checked timesheets can be corrected'; end if;
  v_previous_actual := v_sheet.actual_hours;

  update public.timesheets set actual_hours = p_actual_hours, overtime_hours = p_overtime_hours, adjustment_hours = p_actual_hours - coalesce(work_derived_hours, 0), review_notes = v_reason, status = 'submitted', branch_reviewed_by = null, branch_reviewed_at = null, branch_review_notes = null, branch_reviewed_organization_id = null where id = v_sheet.id returning * into v_sheet;
  insert into public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata) values (v_sheet.organization_id, v_actor, 'timesheet_hours_corrected', 'timesheets', v_sheet.id, jsonb_build_object('previous_status', p_expected_status, 'previous_actual_hours', v_previous_actual, 'actual_hours', p_actual_hours, 'overtime_hours', p_overtime_hours, 'reason', v_reason));
  return v_sheet;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."correct_timesheet_hours"(p_timesheet_id uuid, p_expected_status text, p_actual_hours numeric, p_overtime_hours numeric, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."correct_timesheet_hours"(p_timesheet_id uuid, p_expected_status text, p_actual_hours numeric, p_overtime_hours numeric, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."correct_timesheet_hours"(p_timesheet_id uuid, p_expected_status text, p_actual_hours numeric, p_overtime_hours numeric, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."correct_timesheet_hours"(p_timesheet_id uuid, p_expected_status text, p_actual_hours numeric, p_overtime_hours numeric, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."correct_timesheet_pay"(p_client_request_id uuid, p_timesheet_id uuid, p_expected_revision integer, p_pay_code text, p_hourly_rate numeric, p_reason text)
 RETURNS timesheets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_sheet public.timesheets%rowtype; v_request jsonb; v_old jsonb; v_receipt jsonb;
BEGIN
  SELECT * INTO v_sheet FROM public.timesheets WHERE id = p_timesheet_id FOR UPDATE;
  IF NOT FOUND OR NOT public.is_timesheet_payroll_admin(v_sheet.organization_id) THEN
    RAISE EXCEPTION 'Active employer payroll administrator required' USING ERRCODE = '42501';
  END IF;
  IF p_client_request_id IS NULL OR nullif(btrim(p_reason),'') IS NULL OR length(p_reason)>2000 THEN
    RAISE EXCEPTION 'A request ID and audited pay override reason are required';
  END IF;
  v_request := jsonb_build_object('expected_revision',p_expected_revision,'pay_code',nullif(btrim(p_pay_code),''),
    'hourly_rate',p_hourly_rate,'reason',btrim(p_reason));
  SELECT metadata INTO v_receipt FROM public.audit_log WHERE target_id=v_sheet.id
    AND action='timesheet_pay_corrected' AND metadata->>'client_request_id'=p_client_request_id::text;
  IF FOUND THEN
    IF v_receipt->'request' IS DISTINCT FROM v_request THEN RAISE EXCEPTION 'Request ID already used with different pay details'; END IF;
    RETURN v_sheet;
  END IF;
  IF v_sheet.revision IS DISTINCT FROM p_expected_revision OR v_sheet.status NOT IN ('submitted','branch_checked')
    OR v_sheet.payroll_export_batch_id IS NOT NULL THEN RAISE EXCEPTION 'Timesheet changed or is no longer editable; reload'; END IF;
  v_old := jsonb_build_object('pay_code',v_sheet.pay_code_override,'hourly_rate',v_sheet.hourly_rate_override);
  UPDATE public.timesheets SET pay_code_override=nullif(btrim(p_pay_code),''),
    hourly_rate_override=p_hourly_rate,pay_override_reason=btrim(p_reason),
    status='submitted',branch_reviewed_by=NULL,branch_reviewed_at=NULL,branch_review_notes=NULL,
    branch_reviewed_organization_id=NULL,approved_by=NULL,approved_at=NULL
    WHERE id=v_sheet.id RETURNING * INTO v_sheet;
  INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
    VALUES(v_sheet.organization_id,auth.uid(),'timesheet_pay_corrected','timesheets',v_sheet.id,
      jsonb_build_object('client_request_id',p_client_request_id,'request',v_request,'previous',v_old,
        'scope','this_timesheet_only','revision',v_sheet.revision));
  RETURN v_sheet;
END $function$;
REVOKE ALL ON FUNCTION "public"."correct_timesheet_pay"(p_client_request_id uuid, p_timesheet_id uuid, p_expected_revision integer, p_pay_code text, p_hourly_rate numeric, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."correct_timesheet_pay"(p_client_request_id uuid, p_timesheet_id uuid, p_expected_revision integer, p_pay_code text, p_hourly_rate numeric, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."correct_timesheet_pay"(p_client_request_id uuid, p_timesheet_id uuid, p_expected_revision integer, p_pay_code text, p_hourly_rate numeric, p_reason text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."create_and_assign_dispatch_job"(p_service_agreement_id uuid, p_client_site_id uuid, p_zone_id uuid, p_job_type text, p_priority text, p_sla_minutes integer, p_briefing_notes text DEFAULT NULL::text, p_officer_user_id uuid DEFAULT NULL::uuid, p_client_request_id uuid DEFAULT NULL::uuid, p_website_enquiry_id uuid DEFAULT NULL::uuid, p_source text DEFAULT 'dispatch_console'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_agreement public.service_agreements%rowtype;
  v_enquiry public.website_enquiries%rowtype;
  v_job_type text := lower(btrim(coalesce(p_job_type, '')));
  v_priority text := lower(btrim(coalesce(p_priority, 'normal')));
  v_source text := lower(btrim(coalesce(p_source, 'dispatch_console')));
  v_request_id uuid;
  v_job_id uuid;
  v_created boolean;
  v_status text;
  v_respond_by timestamptz;
  v_job public.dispatch_jobs%rowtype;
  v_enquiry_linked boolean := false;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Sign in to create dispatch jobs' USING ERRCODE = '42501';
  END IF;
  IF v_job_type !~ '^[a-z][a-z0-9_]{1,40}$' THEN
    RAISE EXCEPTION 'Choose a job type' USING ERRCODE = '22023';
  END IF;
  IF v_priority NOT IN ('low', 'normal', 'high', 'urgent') THEN
    RAISE EXCEPTION 'Priority must be low, normal, high or urgent' USING ERRCODE = '22023';
  END IF;
  IF v_source NOT IN ('dispatch_console', 'website_enquiry', 'bob') THEN
    RAISE EXCEPTION 'Unknown dispatch source' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_agreement FROM public.service_agreements WHERE id = p_service_agreement_id;
  IF NOT FOUND OR NOT public.is_admin_for_org(v_agreement.provider_organization_id) THEN
    RAISE EXCEPTION 'Service agreement not found, or you cannot dispatch for it' USING ERRCODE = '42501';
  END IF;

  IF p_website_enquiry_id IS NOT NULL THEN
    SELECT * INTO v_enquiry FROM public.website_enquiries WHERE id = p_website_enquiry_id FOR UPDATE;
    IF NOT FOUND OR v_enquiry.provider_organization_id <> v_agreement.provider_organization_id THEN
      RAISE EXCEPTION 'Website enquiry not found for this provider' USING ERRCODE = '42501';
    END IF;
    IF v_enquiry.status IN ('closed', 'spam') THEN
      RAISE EXCEPTION 'Reopen this enquiry before creating a job from it' USING ERRCODE = '22023';
    END IF;
    IF v_enquiry.dispatch_job_id IS NOT NULL THEN
      SELECT * INTO v_job FROM public.dispatch_jobs WHERE id = v_enquiry.dispatch_job_id;
      RETURN jsonb_build_object(
        'job_id', v_job.id, 'created', false, 'status', v_job.status,
        'sla_respond_by', v_job.sla_respond_by, 'assigned_officer_id', v_job.assigned_officer_id,
        'website_enquiry_id', v_enquiry.id, 'enquiry_linked', true
      );
    END IF;
  END IF;

  -- An enquiry yields at most one job; otherwise honour the caller's idempotency key.
  v_request_id := coalesce(p_client_request_id, p_website_enquiry_id, gen_random_uuid());

  SELECT created_job.id, created_job.created, created_job.status, created_job.sla_respond_by
    INTO v_job_id, v_created, v_status, v_respond_by
    FROM public.create_dispatch_job_for_place(
      v_agreement.provider_organization_id, v_agreement.id, p_client_site_id, p_zone_id,
      v_request_id, v_job_type, v_priority, p_sla_minutes, NULL, p_briefing_notes, NULL
    ) AS created_job;

  IF p_officer_user_id IS NOT NULL THEN
    SELECT * INTO v_job FROM public.dispatch_jobs WHERE id = v_job_id;
    IF v_job.assigned_officer_id IS DISTINCT FROM p_officer_user_id THEN
      PERFORM public.assign_dispatch_job_to_officer(v_job_id, p_officer_user_id);
    END IF;
  END IF;

  IF p_website_enquiry_id IS NOT NULL THEN
    UPDATE public.website_enquiries e
       SET dispatch_job_id = v_job_id,
           status = 'converted',
           status_note = CASE WHEN e.status = 'converted' THEN e.status_note
                              ELSE 'Dispatch job created from this enquiry' END,
           handled_by = CASE WHEN e.status = 'converted' THEN e.handled_by ELSE v_uid END,
           handled_at = CASE WHEN e.status = 'converted' THEN e.handled_at ELSE clock_timestamp() END,
           version = e.version + 1,
           updated_at = clock_timestamp()
     WHERE e.id = p_website_enquiry_id;
    v_enquiry_linked := true;
  END IF;

  SELECT * INTO v_job FROM public.dispatch_jobs WHERE id = v_job_id;

  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_agreement.provider_organization_id, v_uid, 'dispatch_job_created_and_assigned', 'dispatch_jobs', v_job_id,
    jsonb_strip_nulls(jsonb_build_object(
      'source', v_source,
      'created', v_created,
      'service_agreement_id', v_agreement.id,
      'client_site_id', p_client_site_id,
      'zone_id', p_zone_id,
      'job_type', v_job_type,
      'priority', v_priority,
      'assigned_officer_id', v_job.assigned_officer_id,
      'website_enquiry_id', p_website_enquiry_id,
      'website_enquiry_reference', v_enquiry.reference
    )));

  RETURN jsonb_build_object(
    'job_id', v_job_id,
    'created', v_created,
    'status', v_job.status,
    'sla_respond_by', v_job.sla_respond_by,
    'assigned_officer_id', v_job.assigned_officer_id,
    'website_enquiry_id', p_website_enquiry_id,
    'enquiry_linked', v_enquiry_linked
  );
END;
$function$;
COMMENT ON FUNCTION "public"."create_and_assign_dispatch_job"(p_service_agreement_id uuid, p_client_site_id uuid, p_zone_id uuid, p_job_type text, p_priority text, p_sla_minutes integer, p_briefing_notes text, p_officer_user_id uuid, p_client_request_id uuid, p_website_enquiry_id uuid, p_source text) IS 'Creates a dispatch job at one agreement Site or Zone (create_dispatch_job_for_place), optionally queues it to an officer (assign_dispatch_job_to_officer) and links/converts a website enquiry. Provider admin only; idempotent per enquiry or client_request_id; writes audit_log dispatch_job_created_and_assigned.';
REVOKE ALL ON FUNCTION "public"."create_and_assign_dispatch_job"(p_service_agreement_id uuid, p_client_site_id uuid, p_zone_id uuid, p_job_type text, p_priority text, p_sla_minutes integer, p_briefing_notes text, p_officer_user_id uuid, p_client_request_id uuid, p_website_enquiry_id uuid, p_source text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_and_assign_dispatch_job"(p_service_agreement_id uuid, p_client_site_id uuid, p_zone_id uuid, p_job_type text, p_priority text, p_sla_minutes integer, p_briefing_notes text, p_officer_user_id uuid, p_client_request_id uuid, p_website_enquiry_id uuid, p_source text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_and_assign_dispatch_job"(p_service_agreement_id uuid, p_client_site_id uuid, p_zone_id uuid, p_job_type text, p_priority text, p_sla_minutes integer, p_briefing_notes text, p_officer_user_id uuid, p_client_request_id uuid, p_website_enquiry_id uuid, p_source text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_and_assign_dispatch_job"(p_service_agreement_id uuid, p_client_site_id uuid, p_zone_id uuid, p_job_type text, p_priority text, p_sla_minutes integer, p_briefing_notes text, p_officer_user_id uuid, p_client_request_id uuid, p_website_enquiry_id uuid, p_source text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_bob_document_draft"(p_title text, p_document_type text, p_authored_html text, p_authored_text text, p_reference_handles jsonb DEFAULT '[]'::jsonb, p_reference_metadata jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org_id uuid;
  v_document_id uuid;
  v_version_id uuid;
  v_title text := nullif(trim(coalesce(p_title, '')), '');
  v_type text := nullif(trim(coalesce(p_document_type, '')), '');
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF v_title IS NULL THEN RAISE EXCEPTION 'Document title is required'; END IF;
  IF nullif(trim(coalesce(p_authored_text, '')), '') IS NULL THEN RAISE EXCEPTION 'Document content is required'; END IF;
  IF jsonb_typeof(coalesce(p_reference_handles, '[]'::jsonb)) <> 'array' THEN RAISE EXCEPTION 'Reference handles must be an array'; END IF;
  IF jsonb_typeof(coalesce(p_reference_metadata, '[]'::jsonb)) <> 'array' THEN RAISE EXCEPTION 'Reference metadata must be an array'; END IF;

  SELECT organization_id INTO v_org_id
  FROM public.user_profiles
  WHERE id = v_actor;
  IF v_org_id IS NULL THEN RAISE EXCEPTION 'Organization context is required'; END IF;
  IF NOT public.is_admin_for_org(v_org_id) AND NOT public.is_grand_master() THEN
    RAISE EXCEPTION 'Document drafting requires an administrator';
  END IF;

  INSERT INTO public.documents (
    original_filename, mime_type, source_channel, organization_id, current_scope, uploaded_by
  ) VALUES (
    left(v_title || '.html', 255), 'text/html', 'system_generated', v_org_id, 'conversation_only', v_actor
  ) RETURNING id INTO v_document_id;

  INSERT INTO public.document_versions (
    document_id, version_label, extracted_text, metadata_json
  ) VALUES (
    v_document_id, 'v1', p_authored_text,
    jsonb_build_object(
      'authoring_html', coalesce(p_authored_html, ''),
      'content_format', 'html',
      'title', v_title,
      'document_type', v_type,
      'authoring_status', 'draft',
      'authored_by', v_actor,
      'reference_handles', coalesce(p_reference_handles, '[]'::jsonb),
      'references', coalesce(p_reference_metadata, '[]'::jsonb)
    )
  ) RETURNING id INTO v_version_id;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (
    v_org_id, v_actor, 'bob_document_draft_created', 'documents', v_document_id,
    jsonb_build_object('document_version_id', v_version_id, 'document_type', v_type, 'title', v_title, 'reference_count', jsonb_array_length(coalesce(p_reference_handles, '[]'::jsonb)))
  );

  RETURN jsonb_build_object('ok', true, 'document_id', v_document_id, 'document_version_id', v_version_id, 'scope', 'conversation_only', 'status', 'draft');
END;
$function$;
REVOKE ALL ON FUNCTION "public"."create_bob_document_draft"(p_title text, p_document_type text, p_authored_html text, p_authored_text text, p_reference_handles jsonb, p_reference_metadata jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_bob_document_draft"(p_title text, p_document_type text, p_authored_html text, p_authored_text text, p_reference_handles jsonb, p_reference_metadata jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_bob_document_draft"(p_title text, p_document_type text, p_authored_html text, p_authored_text text, p_reference_handles jsonb, p_reference_metadata jsonb) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_bob_document_draft"(p_title text, p_document_type text, p_authored_html text, p_authored_text text, p_reference_handles jsonb, p_reference_metadata jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_cctv_bookmark"(p_evidence_id uuid, p_at timestamp with time zone, p_title text, p_notes text DEFAULT NULL::text, p_until timestamp with time zone DEFAULT NULL::timestamp with time zone, p_severity text DEFAULT 'standard'::text, p_observation_id uuid DEFAULT NULL::uuid, p_client_request_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_evidence public.evidence_items%rowtype;
  v_import public.cctv_imports%rowtype;
  v_incident uuid;
  v_title text := nullif(trim(coalesce(p_title, '')), '');
  v_severity text := lower(coalesce(nullif(trim(p_severity), ''), 'standard'));
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF v_title IS NULL THEN RAISE EXCEPTION 'A bookmark title is required'; END IF;
  IF p_at IS NULL THEN RAISE EXCEPTION 'A bookmark instant is required'; END IF;
  IF p_until IS NOT NULL AND p_until < p_at THEN RAISE EXCEPTION 'Bookmark end must not precede its start'; END IF;
  IF v_severity NOT IN ('low', 'standard', 'high', 'critical') THEN RAISE EXCEPTION 'Unknown bookmark severity %', p_severity; END IF;

  SELECT * INTO v_evidence FROM public.evidence_items WHERE id = p_evidence_id;
  IF v_evidence.id IS NULL THEN RAISE EXCEPTION 'Recording not found'; END IF;
  IF NOT public.org_access_allowed(v_evidence.organization_id) THEN RAISE EXCEPTION 'CCTV bookmark access denied'; END IF;
  IF v_evidence.cctv_import_id IS NOT NULL THEN
    SELECT * INTO v_import FROM public.cctv_imports WHERE id = v_evidence.cctv_import_id;
  END IF;
  IF p_observation_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.cctv_entity_observations o WHERE o.id = p_observation_id AND o.evidence_item_id = v_evidence.id
  ) THEN RAISE EXCEPTION 'Observation does not belong to this recording'; END IF;
  -- incidents_place_anchor_present_chk: an incident is anchored to a place or it is not an incident.
  IF v_import.location_id IS NULL AND v_import.site_id IS NULL AND v_import.zone_id IS NULL THEN
    RAISE EXCEPTION 'This recording is not anchored to a place; import it against a location before bookmarking';
  END IF;

  -- Idempotent on the caller's request id so a retried click cannot double-book.
  IF p_client_request_id IS NOT NULL THEN
    SELECT (a.metadata->>'incident_id')::uuid INTO v_incident
      FROM public.audit_log a
     WHERE a.action = 'cctv_bookmark_created' AND a.metadata->>'client_request_id' = p_client_request_id::text
     LIMIT 1;
    IF v_incident IS NOT NULL THEN
      RETURN jsonb_build_object('incident_id', v_incident, 'deduped', true);
    END IF;
  END IF;

  INSERT INTO public.incidents (organization_id, officer_user_id, location_id, client_site_id, zone_id, canonical_place_id,
                                incident_type, severity, description, status, occurred_at)
  VALUES (v_evidence.organization_id, v_actor, v_import.location_id, v_import.site_id, v_import.zone_id, v_import.canonical_place_id,
          'cctv_bookmark', v_severity,
          v_title || CASE WHEN nullif(trim(coalesce(p_notes, '')), '') IS NULL THEN '' ELSE E'\n\n' || trim(p_notes) END,
          'open', p_at)
  RETURNING id INTO v_incident;

  -- incident_attachments_attachment_kind_check allows photo|video|audio|document|note.
  INSERT INTO public.incident_attachments (organization_id, incident_id, evidence_item_id, attachment_kind)
  VALUES (v_evidence.organization_id, v_incident, v_evidence.id, 'video');

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_evidence.organization_id, v_actor, 'cctv_bookmark_created', 'incidents', v_incident,
          jsonb_strip_nulls(jsonb_build_object(
            'incident_id', v_incident, 'evidence_item_id', v_evidence.id, 'cctv_import_id', v_evidence.cctv_import_id,
            'camera_label', v_import.camera_label, 'bookmark_at', p_at, 'bookmark_until', p_until, 'severity', v_severity,
            'observation_id', p_observation_id, 'client_request_id', p_client_request_id)));

  RETURN jsonb_build_object('incident_id', v_incident, 'deduped', false);
END $function$;
COMMENT ON FUNCTION "public"."create_cctv_bookmark"(p_evidence_id uuid, p_at timestamp with time zone, p_title text, p_notes text, p_until timestamp with time zone, p_severity text, p_observation_id uuid, p_client_request_id uuid) IS 'Reviewer bookmark on a CCTV recording: an incidents row (incident_type cctv_bookmark) anchored to the import place, with the recording attached. Idempotent on p_client_request_id. Audited.';
REVOKE ALL ON FUNCTION "public"."create_cctv_bookmark"(p_evidence_id uuid, p_at timestamp with time zone, p_title text, p_notes text, p_until timestamp with time zone, p_severity text, p_observation_id uuid, p_client_request_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_cctv_bookmark"(p_evidence_id uuid, p_at timestamp with time zone, p_title text, p_notes text, p_until timestamp with time zone, p_severity text, p_observation_id uuid, p_client_request_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_cctv_bookmark"(p_evidence_id uuid, p_at timestamp with time zone, p_title text, p_notes text, p_until timestamp with time zone, p_severity text, p_observation_id uuid, p_client_request_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_cctv_bookmark"(p_evidence_id uuid, p_at timestamp with time zone, p_title text, p_notes text, p_until timestamp with time zone, p_severity text, p_observation_id uuid, p_client_request_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_cctv_export_draft"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_purpose text, p_recipient_scope text, p_legal_hold boolean, p_selected_event_ids jsonb, p_manifest jsonb)
 RETURNS cctv_exports
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  actor_id uuid := auth.uid();
  export_row public.cctv_exports;
  manifest_hash text;
BEGIN
  IF actor_id IS NULL OR NOT public.org_access_allowed(p_organization_id) THEN
    RAISE EXCEPTION 'CCTV export access denied';
  END IF;
  IF p_purpose IS NULL OR char_length(trim(p_purpose)) < 3 OR p_recipient_scope IS NULL OR char_length(trim(p_recipient_scope)) < 3 THEN
    RAISE EXCEPTION 'Export purpose and recipient scope are required';
  END IF;
  IF jsonb_typeof(p_selected_event_ids) <> 'array' OR jsonb_typeof(p_manifest) <> 'object' THEN
    RAISE EXCEPTION 'Export event selection and manifest shapes are invalid';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.inference_jobs
    WHERE id = p_job_id AND evidence_item_id = p_evidence_id AND organization_id = p_organization_id
  ) THEN
    RAISE EXCEPTION 'CCTV evidence is missing or outside the organization';
  END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements_text(p_selected_event_ids) selected_id
    WHERE NOT EXISTS (
      SELECT 1 FROM public.cctv_review_events event
      WHERE event.id = selected_id::uuid
        AND event.organization_id = p_organization_id
        AND event.inference_job_id = p_job_id
        AND event.evidence_item_id = p_evidence_id
        AND event.review_state = 'accepted'
    )
  ) THEN
    RAISE EXCEPTION 'Only accepted CCTV review events may be exported';
  END IF;

  manifest_hash := encode(digest(convert_to(p_manifest::text, 'UTF8'), 'sha256'), 'hex');
  INSERT INTO public.cctv_exports (
    organization_id, inference_job_id, evidence_item_id, purpose, recipient_scope,
    legal_hold, selected_event_ids, manifest, manifest_sha256, generated_by
  ) VALUES (
    p_organization_id, p_job_id, p_evidence_id, trim(p_purpose), trim(p_recipient_scope),
    coalesce(p_legal_hold, false), p_selected_event_ids, p_manifest, manifest_hash, actor_id
  ) RETURNING * INTO export_row;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (p_organization_id, actor_id, 'cctv_export_draft_created', 'cctv_exports', export_row.id,
    jsonb_build_object('purpose', p_purpose, 'recipient_scope', p_recipient_scope, 'legal_hold', p_legal_hold, 'manifest_sha256', manifest_hash));

  RETURN export_row;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."create_cctv_export_draft"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_purpose text, p_recipient_scope text, p_legal_hold boolean, p_selected_event_ids jsonb, p_manifest jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_cctv_export_draft"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_purpose text, p_recipient_scope text, p_legal_hold boolean, p_selected_event_ids jsonb, p_manifest jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_cctv_export_draft"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_purpose text, p_recipient_scope text, p_legal_hold boolean, p_selected_event_ids jsonb, p_manifest jsonb) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_cctv_export_draft"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_purpose text, p_recipient_scope text, p_legal_hold boolean, p_selected_event_ids jsonb, p_manifest jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_cctv_import"(p_organization_id uuid, p_location_id uuid, p_camera_label text, p_site_id uuid DEFAULT NULL::uuid, p_zone_id uuid DEFAULT NULL::uuid, p_source_device_kind text DEFAULT 'unknown'::text, p_source_timezone text DEFAULT 'Pacific/Auckland'::text, p_source_root_label text DEFAULT NULL::text, p_watermark_location_hint text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS cctv_imports
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_actor uuid := auth.uid(); v_house_org uuid; v_row public.cctv_imports%rowtype; v_tz_probe timestamp;
BEGIN
  IF v_actor IS NULL OR NOT public.org_access_allowed(p_organization_id) THEN RAISE EXCEPTION 'CCTV import access denied'; END IF;
  SELECT organization_id INTO v_house_org FROM public.locations WHERE id = p_location_id;
  IF v_house_org IS NULL THEN RAISE EXCEPTION 'Choose the location before importing camera files'; END IF;
  IF NOT public.org_access_allowed(v_house_org) THEN RAISE EXCEPTION 'No access to the chosen location'; END IF;
  BEGIN
    v_tz_probe := now() AT TIME ZONE coalesce(p_source_timezone, 'Pacific/Auckland');
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'Unknown time zone %', p_source_timezone;
  END;
  INSERT INTO public.cctv_imports (organization_id, location_id, canonical_place_id, site_id, zone_id, camera_label, camera_key,
                                   source_device_kind, source_timezone, source_root_label, watermark_location_hint, notes, created_by)
  SELECT p_organization_id, p_location_id, l.canonical_place_id, p_site_id, p_zone_id, p_camera_label, 'pending',
         coalesce(nullif(p_source_device_kind, ''), 'unknown'), coalesce(nullif(p_source_timezone, ''), 'Pacific/Auckland'),
         nullif(trim(p_source_root_label), ''), nullif(trim(p_watermark_location_hint), ''), nullif(trim(p_notes), ''),
         (SELECT up.id FROM public.user_profiles up WHERE up.id = v_actor)
  FROM public.locations l WHERE l.id = p_location_id
  RETURNING * INTO v_row;
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (p_organization_id, v_actor, 'cctv_import_created', 'cctv_imports', v_row.id,
          jsonb_build_object('location_id', p_location_id, 'canonical_place_id', v_row.canonical_place_id, 'camera_key', v_row.camera_key, 'device', v_row.source_device_kind));
  RETURN v_row;
END $function$;
REVOKE ALL ON FUNCTION "public"."create_cctv_import"(p_organization_id uuid, p_location_id uuid, p_camera_label text, p_site_id uuid, p_zone_id uuid, p_source_device_kind text, p_source_timezone text, p_source_root_label text, p_watermark_location_hint text, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_cctv_import"(p_organization_id uuid, p_location_id uuid, p_camera_label text, p_site_id uuid, p_zone_id uuid, p_source_device_kind text, p_source_timezone text, p_source_root_label text, p_watermark_location_hint text, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_cctv_import"(p_organization_id uuid, p_location_id uuid, p_camera_label text, p_site_id uuid, p_zone_id uuid, p_source_device_kind text, p_source_timezone text, p_source_root_label text, p_watermark_location_hint text, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_cctv_import"(p_organization_id uuid, p_location_id uuid, p_camera_label text, p_site_id uuid, p_zone_id uuid, p_source_device_kind text, p_source_timezone text, p_source_root_label text, p_watermark_location_hint text, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_crm_account_activity"(p_client_request_id uuid, p_account_organization_id uuid, p_service_agreement_id uuid, p_activity_type text, p_subject text, p_details text, p_outcome text, p_occurred_at timestamp with time zone, p_follow_up_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS crm_account_activities
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_provider uuid;v_activity public.crm_account_activities%rowtype;v_subject text:=nullif(trim(coalesce(p_subject,'')),'');
begin
  if v_actor is null or not public.crm_actor_can_manage_account(p_account_organization_id) then raise exception 'Not authorised to manage this CRM account';end if;
  select organization_id into v_provider from public.user_profiles where id=v_actor and deactivated_at is null;
  if p_client_request_id is null then raise exception 'client_request_id is required';end if;if p_activity_type not in('call','email','meeting','note','task') then raise exception 'Unsupported CRM activity type';end if;if v_subject is null then raise exception 'Activity subject is required';end if;
  if p_occurred_at is null or p_occurred_at>now()+interval '5 minutes' or p_occurred_at<now()-interval '90 days' then raise exception 'Activity time is outside the accepted window';end if;
  if p_follow_up_at is not null and p_follow_up_at<p_occurred_at then raise exception 'Follow-up cannot be before the activity';end if;
  if p_service_agreement_id is not null and not exists(select 1 from public.service_agreements a where a.id=p_service_agreement_id and a.provider_organization_id=v_provider and a.client_organization_id=p_account_organization_id) then raise exception 'Agreement does not belong to this CRM account';end if;
  select a.* into v_activity from public.crm_account_activities a where a.provider_organization_id=v_provider and a.client_request_id=p_client_request_id;if found then return v_activity;end if;
  insert into public.crm_account_activities(provider_organization_id,account_organization_id,service_agreement_id,client_request_id,activity_type,subject,details,outcome,occurred_at,follow_up_at,created_by) values(v_provider,p_account_organization_id,p_service_agreement_id,p_client_request_id,p_activity_type,v_subject,nullif(trim(coalesce(p_details,'')),''),nullif(trim(coalesce(p_outcome,'')),''),p_occurred_at,p_follow_up_at,v_actor) returning * into v_activity;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_provider,v_actor,'crm_account_activity_created','crm_account_activities',v_activity.id,jsonb_build_object('account_organization_id',p_account_organization_id,'activity_type',p_activity_type,'follow_up_at',p_follow_up_at));
  return v_activity;
end;$function$;
REVOKE ALL ON FUNCTION "public"."create_crm_account_activity"(p_client_request_id uuid, p_account_organization_id uuid, p_service_agreement_id uuid, p_activity_type text, p_subject text, p_details text, p_outcome text, p_occurred_at timestamp with time zone, p_follow_up_at timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_crm_account_activity"(p_client_request_id uuid, p_account_organization_id uuid, p_service_agreement_id uuid, p_activity_type text, p_subject text, p_details text, p_outcome text, p_occurred_at timestamp with time zone, p_follow_up_at timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_crm_account_activity"(p_client_request_id uuid, p_account_organization_id uuid, p_service_agreement_id uuid, p_activity_type text, p_subject text, p_details text, p_outcome text, p_occurred_at timestamp with time zone, p_follow_up_at timestamp with time zone) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_crm_account_activity"(p_client_request_id uuid, p_account_organization_id uuid, p_service_agreement_id uuid, p_activity_type text, p_subject text, p_details text, p_outcome text, p_occurred_at timestamp with time zone, p_follow_up_at timestamp with time zone) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_crm_draft_quote_for_provider"(p_client_request_id uuid, p_operating_provider_organization_id uuid, p_client_org_id uuid, p_title text, p_target_margin_pct numeric DEFAULT 0, p_valid_until date DEFAULT NULL::date, p_notes text DEFAULT NULL::text, p_service_agreement_id uuid DEFAULT NULL::uuid)
 RETURNS quotes
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_provider public.organizations%rowtype;
  v_client public.organizations%rowtype;
  v_agreement public.service_agreements%rowtype;
  v_quote public.quotes%rowtype;
  v_title text := nullif(trim(coalesce(p_title, '')), '');
  v_provider_tree uuid[];
begin
  if p_client_request_id is null then raise exception 'client_request_id is required'; end if;
  select * into v_provider from public.organizations where id = p_operating_provider_organization_id;
  if not found or not public.is_admin_for_org(v_provider.id) then raise exception 'Operating provider organization is not available for management'; end if;
  if v_provider.organization_type not in ('owner', 'service_provider', 'branch') then raise exception 'Operating provider must be a service provider or internal branch'; end if;
  v_provider_tree := public.get_descendant_organizations(coalesce(v_provider.parent_organization_id, v_provider.id));
  select * into v_client from public.organizations where id = p_client_org_id;
  if not found or not (
    (v_client.active and v_client.status = 'active')
    or (
      not v_client.active
      and v_client.status = 'prospect'
      and exists(
        select 1
        from public.crm_onboarding_ledgers ledger
        where ledger.provider_organization_id = any(v_provider_tree)
          and ledger.account_organization_id = v_client.id
          and ledger.status <> 'activated'
      )
    )
  ) then raise exception 'An active client organization is required for a service proposal'; end if;
  if v_client.id = v_provider.id then raise exception 'A provider cannot create a service proposal for itself'; end if;
  if v_title is null then raise exception 'Quote title is required'; end if;
  if p_target_margin_pct < 0 or p_target_margin_pct >= 100 then raise exception 'Target margin must be between zero and 100'; end if;
  if p_valid_until is not null and p_valid_until < current_date then raise exception 'Quote validity date cannot be in the past'; end if;

  if p_service_agreement_id is not null then
    select * into v_agreement from public.service_agreements where id = p_service_agreement_id;
    if not found then raise exception 'The agreement this variation changes could not be found'; end if;
    if v_agreement.client_organization_id <> v_client.id then raise exception 'A variation must change an agreement held by the same client'; end if;
    if v_agreement.agreement_type <> 'operational' then raise exception 'Only operational service agreements can be varied'; end if;
    if v_agreement.provider_organization_id <> v_provider.id and not (v_agreement.provider_organization_id = any(v_provider_tree)) then
      raise exception 'A variation must change an agreement delivered by this provider or its branches';
    end if;
    if v_agreement.ends_on is not null and v_agreement.ends_on < current_date then
      raise exception 'This agreement has ended. Raise a new agreement instead of a variation';
    end if;
  end if;

  select * into v_quote from public.quotes quote where quote.provider_org_id = v_provider.id and quote.client_request_id = p_client_request_id;
  if found then return v_quote; end if;

  insert into public.quotes(provider_org_id,client_org_id,title,status,currency,target_margin_pct,valid_until,notes,client_request_id,service_agreement_id,created_by,updated_by)
  values(v_provider.id,v_client.id,v_title,'draft','NZD',p_target_margin_pct,p_valid_until,nullif(trim(coalesce(p_notes,'')),''),p_client_request_id,p_service_agreement_id,v_actor,v_actor)
  returning * into v_quote;

  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
  values(v_provider.id,v_actor,'crm_draft_quote_created_for_operating_provider','quotes',v_quote.id,jsonb_build_object(
    'operating_provider_organization_id',v_provider.id,
    'client_org_id',v_client.id,
    'title',v_title,
    'relationship_state',case when p_service_agreement_id is null then 'proposal_only' else 'variation_of_agreement' end,
    'service_agreement_id',p_service_agreement_id,
    'service_agreement_name',v_agreement.name));
  return v_quote;
end;
$function$;
COMMENT ON FUNCTION "public"."create_crm_draft_quote_for_provider"(p_client_request_id uuid, p_operating_provider_organization_id uuid, p_client_org_id uuid, p_title text, p_target_margin_pct numeric, p_valid_until date, p_notes text, p_service_agreement_id uuid) IS 'Create an idempotent draft quote for a client on behalf of an operating provider/branch. When p_service_agreement_id is given the quote is a VARIATION of that existing operational agreement (same client, provider tree, not ended): on acceptance its places, delivery schedules, and prices are appended to that agreement instead of creating a new one.';
REVOKE ALL ON FUNCTION "public"."create_crm_draft_quote_for_provider"(p_client_request_id uuid, p_operating_provider_organization_id uuid, p_client_org_id uuid, p_title text, p_target_margin_pct numeric, p_valid_until date, p_notes text, p_service_agreement_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_crm_draft_quote_for_provider"(p_client_request_id uuid, p_operating_provider_organization_id uuid, p_client_org_id uuid, p_title text, p_target_margin_pct numeric, p_valid_until date, p_notes text, p_service_agreement_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_crm_draft_quote_for_provider"(p_client_request_id uuid, p_operating_provider_organization_id uuid, p_client_org_id uuid, p_title text, p_target_margin_pct numeric, p_valid_until date, p_notes text, p_service_agreement_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_crm_draft_quote_for_provider"(p_client_request_id uuid, p_operating_provider_organization_id uuid, p_client_org_id uuid, p_title text, p_target_margin_pct numeric, p_valid_until date, p_notes text, p_service_agreement_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_crm_site"(p_client_request_id uuid, p_account_organization_id uuid, p_name text, p_address text, p_site_type text DEFAULT 'commercial_premises'::text, p_center_lat double precision DEFAULT NULL::double precision, p_center_lng double precision DEFAULT NULL::double precision, p_location_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, name text, address text, site_type text, active boolean, boundary_status text, boundary_verification text, created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid(); v_provider uuid; v_site public.client_sites%rowtype;
  v_name text := nullif(trim(coalesce(p_name, '')), ''); v_address text := nullif(trim(coalesce(p_address, '')), ''); v_address_key text;
BEGIN
  SELECT up.organization_id INTO v_provider FROM public.user_profiles AS up WHERE up.id=v_actor AND up.deactivated_at IS NULL;
  IF v_provider IS NULL OR NOT public.is_admin_for_org(v_provider) OR NOT public.crm_actor_can_manage_account(p_account_organization_id) THEN RAISE EXCEPTION 'Active CRM administrator required'; END IF;
  IF p_client_request_id IS NULL THEN RAISE EXCEPTION 'client_request_id is required'; END IF;
  PERFORM 1 FROM public.organizations AS org WHERE org.id=p_account_organization_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'CRM account organization not found'; END IF;
  IF p_location_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.locations AS house WHERE house.id=p_location_id AND house.organization_id=p_account_organization_id) THEN RAISE EXCEPTION 'Location house does not belong to the account'; END IF;
  SELECT site.* INTO v_site FROM public.client_sites AS site WHERE site.client_organization_id=p_account_organization_id AND site.client_request_id=p_client_request_id;
  IF FOUND THEN id:=v_site.id; name:=v_site.name; address:=v_site.address; site_type:=v_site.site_type; active:=v_site.active; boundary_status:=v_site.boundary_status; boundary_verification:=v_site.boundary_verification; created:=false; RETURN NEXT; RETURN; END IF;
  IF v_name IS NULL OR char_length(v_name)>200 THEN RAISE EXCEPTION 'Site name is required and must be 200 characters or fewer'; END IF;
  IF v_address IS NULL OR char_length(v_address)<4 OR char_length(v_address)>500 THEN RAISE EXCEPTION 'A complete site address is required'; END IF;
  IF p_center_lat IS NULL OR p_center_lng IS NULL OR p_center_lat NOT BETWEEN -90 AND 90 OR p_center_lng NOT BETWEEN -180 AND 180 THEN RAISE EXCEPTION 'Resolve the address before creating the site'; END IF;
  IF p_site_type NOT IN ('freedom_camping_area','parking_area','commercial_premises','residential_complex','government_facility','hospital','education_facility','industrial_site','public_space','other') THEN RAISE EXCEPTION 'Unsupported site type'; END IF;
  v_address_key:=regexp_replace(lower(v_address),'[^a-z0-9]+','','g');
  IF EXISTS (SELECT 1 FROM public.client_sites AS duplicate_site WHERE duplicate_site.client_organization_id=p_account_organization_id AND duplicate_site.address_match_key=v_address_key) THEN RAISE EXCEPTION 'A site with this address already exists for the account'; END IF;
  INSERT INTO public.client_sites(client_organization_id,location_id,name,address,address_match_key,site_type,active,site_origin,boundary_status,boundary_verification,center_point,client_request_id)
  VALUES(p_account_organization_id,p_location_id,v_name,v_address,v_address_key,p_site_type,true,'contracted','provisional','unverified',ST_SetSRID(ST_MakePoint(p_center_lng,p_center_lat),4326),p_client_request_id) RETURNING * INTO v_site;
  INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) VALUES(v_provider,v_actor,'crm_site_created','client_sites',v_site.id,jsonb_build_object('account_organization_id',p_account_organization_id,'location_id',p_location_id,'address_match_key',v_address_key,'center_source','resolved_address'));
  id:=v_site.id; name:=v_site.name; address:=v_site.address; site_type:=v_site.site_type; active:=v_site.active; boundary_status:=v_site.boundary_status; boundary_verification:=v_site.boundary_verification; created:=true; RETURN NEXT;
END; $function$;
REVOKE ALL ON FUNCTION "public"."create_crm_site"(p_client_request_id uuid, p_account_organization_id uuid, p_name text, p_address text, p_site_type text, p_center_lat double precision, p_center_lng double precision, p_location_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_crm_site"(p_client_request_id uuid, p_account_organization_id uuid, p_name text, p_address text, p_site_type text, p_center_lat double precision, p_center_lng double precision, p_location_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_crm_site"(p_client_request_id uuid, p_account_organization_id uuid, p_name text, p_address text, p_site_type text, p_center_lat double precision, p_center_lng double precision, p_location_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_crm_site"(p_client_request_id uuid, p_account_organization_id uuid, p_name text, p_address text, p_site_type text, p_center_lat double precision, p_center_lng double precision, p_location_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_default_welfare_settings"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
begin
  if new.role in ('officer', 'admin_officer') and new.organization_id is not null then
    insert into officer_welfare_settings (organization_id, officer_user_id)
    values (new.organization_id, new.id)
    on conflict (officer_user_id, organization_id) do nothing;
  end if;
  return new;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."create_default_welfare_settings"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_default_welfare_settings"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."create_default_welfare_settings"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_default_welfare_settings"() TO "anon";
GRANT EXECUTE ON FUNCTION "public"."create_default_welfare_settings"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_default_welfare_settings"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_dispatch_intake_job"(p_organization_id uuid, p_service_agreement_id uuid, p_client_request_id uuid, p_job_type text, p_priority text, p_sla_minutes integer, p_location_name text, p_location_address text, p_location_lat double precision, p_location_lng double precision, p_dispatch_resource_id uuid DEFAULT NULL::uuid, p_briefing_notes text DEFAULT NULL::text, p_shift_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, client_site_id uuid, created boolean, status text, sla_respond_by timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_place record;
  v_job record;
  v_client_org_id uuid;
BEGIN
  IF NOT public.is_admin_for_org(p_organization_id) THEN RAISE EXCEPTION 'Not authorised to create dispatch jobs for this organisation'; END IF;
  IF p_client_request_id IS NULL THEN RAISE EXCEPTION 'client_request_id is required'; END IF;
  IF nullif(trim(coalesce(p_location_name, '')), '') IS NULL OR nullif(trim(coalesce(p_location_address, '')), '') IS NULL THEN RAISE EXCEPTION 'Incident location name and address are required'; END IF;
  IF p_location_lat IS NULL OR p_location_lng IS NULL OR p_location_lat NOT BETWEEN -90 AND 90 OR p_location_lng NOT BETWEEN -180 AND 180 THEN RAISE EXCEPTION 'Resolve the incident address before dispatching'; END IF;

  SELECT agreement.client_organization_id INTO v_client_org_id FROM public.service_agreements AS agreement
  WHERE agreement.id = p_service_agreement_id AND agreement.provider_organization_id = p_organization_id;
  IF v_client_org_id IS NULL THEN RAISE EXCEPTION 'Service agreement is not available to this provider'; END IF;

  SELECT * INTO v_place FROM public.resolve_or_create_dispatch_place_site(
    p_organization_id, v_client_org_id, trim(p_location_name), trim(p_location_address), p_location_lat, p_location_lng, auth.uid());

  INSERT INTO public.service_agreement_locations (service_agreement_id, site_id, status, created_by)
  VALUES (p_service_agreement_id, v_place.site_id, 'active', auth.uid()) ON CONFLICT (service_agreement_id, site_id) DO NOTHING;

  SELECT * INTO v_job FROM public.create_dispatch_job(p_organization_id, p_service_agreement_id, v_place.site_id, p_client_request_id, p_job_type, p_priority, p_sla_minutes, p_dispatch_resource_id, p_briefing_notes, p_shift_id);
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (p_organization_id, auth.uid(), 'dispatch_intake_location_created', 'client_sites', v_place.site_id,
    jsonb_build_object('service_agreement_id', p_service_agreement_id, 'dispatch_job_id', v_job.id, 'site_created', v_place.site_created,
      'location_id', v_place.location_id, 'house_action', v_place.house_action, 'boundary_status', 'provisional'));
  RETURN QUERY SELECT v_job.id, v_place.site_id, v_job.created, v_job.status, v_job.sla_respond_by;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."create_dispatch_intake_job"(p_organization_id uuid, p_service_agreement_id uuid, p_client_request_id uuid, p_job_type text, p_priority text, p_sla_minutes integer, p_location_name text, p_location_address text, p_location_lat double precision, p_location_lng double precision, p_dispatch_resource_id uuid, p_briefing_notes text, p_shift_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_dispatch_intake_job"(p_organization_id uuid, p_service_agreement_id uuid, p_client_request_id uuid, p_job_type text, p_priority text, p_sla_minutes integer, p_location_name text, p_location_address text, p_location_lat double precision, p_location_lng double precision, p_dispatch_resource_id uuid, p_briefing_notes text, p_shift_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_dispatch_intake_job"(p_organization_id uuid, p_service_agreement_id uuid, p_client_request_id uuid, p_job_type text, p_priority text, p_sla_minutes integer, p_location_name text, p_location_address text, p_location_lat double precision, p_location_lng double precision, p_dispatch_resource_id uuid, p_briefing_notes text, p_shift_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_dispatch_intake_job"(p_organization_id uuid, p_service_agreement_id uuid, p_client_request_id uuid, p_job_type text, p_priority text, p_sla_minutes integer, p_location_name text, p_location_address text, p_location_lat double precision, p_location_lng double precision, p_dispatch_resource_id uuid, p_briefing_notes text, p_shift_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_dispatch_job"(p_organization_id uuid, p_service_agreement_id uuid, p_client_site_id uuid, p_client_request_id uuid, p_job_type text, p_priority text, p_sla_minutes integer, p_dispatch_resource_id uuid DEFAULT NULL::uuid, p_briefing_notes text DEFAULT NULL::text, p_shift_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, created boolean, status text, sla_respond_by timestamp with time zone)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT *
  FROM public.create_dispatch_job_for_place(
    p_organization_id,
    p_service_agreement_id,
    p_client_site_id,
    NULL,
    p_client_request_id,
    p_job_type,
    p_priority,
    p_sla_minutes,
    p_dispatch_resource_id,
    p_briefing_notes,
    p_shift_id
  );
$function$;
COMMENT ON FUNCTION "public"."create_dispatch_job"(p_organization_id uuid, p_service_agreement_id uuid, p_client_site_id uuid, p_client_request_id uuid, p_job_type text, p_priority text, p_sla_minutes integer, p_dispatch_resource_id uuid, p_briefing_notes text, p_shift_id uuid) IS 'Backward-compatible Site-only wrapper around create_dispatch_job_for_place.';
REVOKE ALL ON FUNCTION "public"."create_dispatch_job"(p_organization_id uuid, p_service_agreement_id uuid, p_client_site_id uuid, p_client_request_id uuid, p_job_type text, p_priority text, p_sla_minutes integer, p_dispatch_resource_id uuid, p_briefing_notes text, p_shift_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_dispatch_job"(p_organization_id uuid, p_service_agreement_id uuid, p_client_site_id uuid, p_client_request_id uuid, p_job_type text, p_priority text, p_sla_minutes integer, p_dispatch_resource_id uuid, p_briefing_notes text, p_shift_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_dispatch_job"(p_organization_id uuid, p_service_agreement_id uuid, p_client_site_id uuid, p_client_request_id uuid, p_job_type text, p_priority text, p_sla_minutes integer, p_dispatch_resource_id uuid, p_briefing_notes text, p_shift_id uuid) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."create_dispatch_job"(p_organization_id uuid, p_service_agreement_id uuid, p_client_site_id uuid, p_client_request_id uuid, p_job_type text, p_priority text, p_sla_minutes integer, p_dispatch_resource_id uuid, p_briefing_notes text, p_shift_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_dispatch_job"(p_organization_id uuid, p_service_agreement_id uuid, p_client_site_id uuid, p_client_request_id uuid, p_job_type text, p_priority text, p_sla_minutes integer, p_dispatch_resource_id uuid, p_briefing_notes text, p_shift_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_dispatch_job_for_place"(p_organization_id uuid, p_service_agreement_id uuid, p_client_site_id uuid, p_zone_id uuid, p_client_request_id uuid, p_job_type text, p_priority text, p_sla_minutes integer, p_dispatch_resource_id uuid DEFAULT NULL::uuid, p_briefing_notes text DEFAULT NULL::text, p_shift_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, created boolean, status text, sla_respond_by timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_existing public.dispatch_jobs%rowtype;
  v_created public.dispatch_jobs%rowtype;
  v_resource public.dispatch_resources%rowtype;
  v_shift public.shifts%rowtype;
BEGIN
  IF NOT public.is_admin_for_org(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorised to create dispatch jobs for this organisation';
  END IF;
  IF p_sla_minutes IS NULL OR p_sla_minutes < 1 OR p_sla_minutes > 1440 THEN
    RAISE EXCEPTION 'SLA minutes must be between 1 and 1440';
  END IF;
  IF num_nonnulls(p_client_site_id, p_zone_id) <> 1 THEN
    RAISE EXCEPTION 'Choose exactly one dispatch place: a Site or Zone';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.service_agreements agreement
    JOIN public.service_agreement_locations link
      ON link.service_agreement_id = agreement.id
    LEFT JOIN public.client_sites site
      ON site.id = link.site_id
    LEFT JOIN public.location_zones zone
      ON zone.id = link.zone_id
    WHERE agreement.id = p_service_agreement_id
      AND agreement.provider_organization_id = p_organization_id
      AND link.status = 'active'
      AND (
        (p_client_site_id IS NOT NULL AND link.site_id = p_client_site_id AND site.active)
        OR (p_zone_id IS NOT NULL AND link.zone_id = p_zone_id AND zone.is_active)
      )
  ) THEN
    RAISE EXCEPTION 'Place is not active under this service agreement';
  END IF;

  SELECT * INTO v_existing
  FROM public.dispatch_jobs job
  WHERE job.organization_id = p_organization_id
    AND job.client_request_id = p_client_request_id;
  IF FOUND THEN
    RETURN QUERY SELECT v_existing.id, false, v_existing.status, v_existing.sla_respond_by;
    RETURN;
  END IF;

  IF p_dispatch_resource_id IS NOT NULL THEN
    IF p_shift_id IS NULL THEN
      RAISE EXCEPTION 'A shift is required when dispatching to a resource';
    END IF;
    SELECT * INTO v_resource
    FROM public.dispatch_resources resource
    WHERE resource.id = p_dispatch_resource_id
      AND resource.organization_id = p_organization_id
    FOR UPDATE;
    IF NOT FOUND OR v_resource.status <> 'available' OR v_resource.assigned_officer_id IS NULL THEN
      RAISE EXCEPTION 'Dispatch resource is not available with an assigned officer';
    END IF;
    SELECT * INTO v_shift
    FROM public.shifts shift
    WHERE shift.id = p_shift_id
      AND shift.organization_id = p_organization_id
      AND shift.status IN ('accepted', 'in_progress')
    FOR SHARE;
    IF NOT FOUND OR v_shift.officer_user_id <> v_resource.assigned_officer_id THEN
      RAISE EXCEPTION 'Shift officer does not match the selected dispatch resource';
    END IF;
  ELSIF p_shift_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.shifts shift
    WHERE shift.id = p_shift_id
      AND shift.organization_id = p_organization_id
      AND shift.status IN ('accepted', 'in_progress')
  ) THEN
    RAISE EXCEPTION 'Shift is not active in this organisation';
  END IF;

  BEGIN
    INSERT INTO public.dispatch_jobs (
      organization_id, service_agreement_id, client_site_id, zone_id,
      client_request_id, dispatch_resource_id, job_type, priority, status,
      sla_minutes, sla_respond_by, briefing_notes, shift_id, dispatched_at
    ) VALUES (
      p_organization_id, p_service_agreement_id, p_client_site_id, p_zone_id,
      p_client_request_id, p_dispatch_resource_id, p_job_type, p_priority,
      CASE WHEN p_dispatch_resource_id IS NULL THEN 'pending' ELSE 'dispatched' END,
      p_sla_minutes, now() + make_interval(mins => p_sla_minutes),
      nullif(trim(p_briefing_notes), ''), p_shift_id,
      CASE WHEN p_dispatch_resource_id IS NULL THEN NULL ELSE now() END
    ) RETURNING * INTO v_created;

    IF p_dispatch_resource_id IS NOT NULL THEN
      UPDATE public.dispatch_resources SET status = 'busy'
      WHERE dispatch_resources.id = p_dispatch_resource_id;
    END IF;
  EXCEPTION WHEN unique_violation THEN
    SELECT * INTO v_created
    FROM public.dispatch_jobs job
    WHERE job.organization_id = p_organization_id
      AND job.client_request_id = p_client_request_id;
    RETURN QUERY SELECT v_created.id, false, v_created.status, v_created.sla_respond_by;
    RETURN;
  END;

  RETURN QUERY SELECT v_created.id, true, v_created.status, v_created.sla_respond_by;
END;
$function$;
COMMENT ON FUNCTION "public"."create_dispatch_job_for_place"(p_organization_id uuid, p_service_agreement_id uuid, p_client_site_id uuid, p_zone_id uuid, p_client_request_id uuid, p_job_type text, p_priority text, p_sla_minutes integer, p_dispatch_resource_id uuid, p_briefing_notes text, p_shift_id uuid) IS 'Creates one retry-safe dispatch job at exactly one active agreement-linked Site or Zone.';
REVOKE ALL ON FUNCTION "public"."create_dispatch_job_for_place"(p_organization_id uuid, p_service_agreement_id uuid, p_client_site_id uuid, p_zone_id uuid, p_client_request_id uuid, p_job_type text, p_priority text, p_sla_minutes integer, p_dispatch_resource_id uuid, p_briefing_notes text, p_shift_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_dispatch_job_for_place"(p_organization_id uuid, p_service_agreement_id uuid, p_client_site_id uuid, p_zone_id uuid, p_client_request_id uuid, p_job_type text, p_priority text, p_sla_minutes integer, p_dispatch_resource_id uuid, p_briefing_notes text, p_shift_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_dispatch_job_for_place"(p_organization_id uuid, p_service_agreement_id uuid, p_client_site_id uuid, p_zone_id uuid, p_client_request_id uuid, p_job_type text, p_priority text, p_sla_minutes integer, p_dispatch_resource_id uuid, p_briefing_notes text, p_shift_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_dispatch_job_for_place"(p_organization_id uuid, p_service_agreement_id uuid, p_client_site_id uuid, p_zone_id uuid, p_client_request_id uuid, p_job_type text, p_priority text, p_sla_minutes integer, p_dispatch_resource_id uuid, p_briefing_notes text, p_shift_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_event_context_snapshot"(p_source_table text, p_source_event_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_client_site_id uuid DEFAULT NULL::uuid, p_zone_id uuid DEFAULT NULL::uuid, p_checkpoint_id uuid DEFAULT NULL::uuid, p_module_key text DEFAULT NULL::text, p_service_agreement_id uuid DEFAULT NULL::uuid, p_provider_organization_id uuid DEFAULT NULL::uuid, p_client_organization_id uuid DEFAULT NULL::uuid, p_jurisdiction_organization_id uuid DEFAULT NULL::uuid, p_jurisdiction_rule_set_id uuid DEFAULT NULL::uuid, p_authority_snapshot jsonb DEFAULT '{}'::jsonb, p_source_refs jsonb DEFAULT '{}'::jsonb, p_captured_at timestamp with time zone DEFAULT now())
 RETURNS event_context_snapshots
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.event_context_snapshots%rowtype;
  v_context_org uuid := coalesce(p_provider_organization_id, p_client_organization_id, p_jurisdiction_organization_id);
BEGIN
  IF nullif(trim(coalesce(p_source_table, '')), '') IS NULL OR p_source_event_id IS NULL THEN RAISE EXCEPTION 'source_table and source_event_id are required'; END IF;
  IF auth.uid() IS NULL OR v_context_org IS NULL OR NOT public.org_access_allowed(v_context_org) THEN RAISE EXCEPTION 'Event context organization access denied'; END IF;
  IF p_client_site_id IS NOT NULL AND p_zone_id IS NOT NULL THEN RAISE EXCEPTION 'Event context Site and Zone are mutually exclusive'; END IF;
  IF p_client_site_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.client_sites s WHERE s.id=p_client_site_id AND (p_location_id IS NULL OR s.location_id=p_location_id)) THEN RAISE EXCEPTION 'Event context Site does not match the House'; END IF;
  IF p_zone_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.location_zones z WHERE z.id=p_zone_id AND (p_location_id IS NULL OR z.location_id=p_location_id)) THEN RAISE EXCEPTION 'Event context Zone does not match the House'; END IF;
  IF p_service_agreement_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.service_agreements sa WHERE sa.id=p_service_agreement_id
      AND (p_provider_organization_id IS NULL OR sa.provider_organization_id=p_provider_organization_id)
      AND (p_client_organization_id IS NULL OR sa.client_organization_id=p_client_organization_id)
  ) THEN RAISE EXCEPTION 'Event context service agreement does not match its parties'; END IF;
  IF p_checkpoint_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.patrol_checkpoints cp
    WHERE cp.id=p_checkpoint_id
      AND cp.organization_id=v_context_org
      AND ((cp.client_site_id IS NOT NULL AND cp.client_site_id=p_client_site_id AND p_zone_id IS NULL)
        OR (cp.zone_id IS NOT NULL AND cp.zone_id=p_zone_id AND p_client_site_id IS NULL))
  ) THEN RAISE EXCEPTION 'Checkpoint does not match the event Site/Zone and organization'; END IF;

  INSERT INTO public.event_context_snapshots (
    source_table, source_event_id, location_id, client_site_id, zone_id, checkpoint_id,
    module_key, service_agreement_id, provider_organization_id, client_organization_id,
    jurisdiction_organization_id, jurisdiction_rule_set_id, authority_snapshot, source_refs, captured_at
  ) VALUES (
    trim(p_source_table), p_source_event_id, p_location_id, p_client_site_id, p_zone_id, p_checkpoint_id,
    p_module_key, p_service_agreement_id, p_provider_organization_id, p_client_organization_id,
    p_jurisdiction_organization_id, p_jurisdiction_rule_set_id, coalesce(p_authority_snapshot, '{}'::jsonb),
    coalesce(p_source_refs, '{}'::jsonb), coalesce(p_captured_at, now())
  ) ON CONFLICT (source_table, source_event_id) DO NOTHING RETURNING * INTO v_row;

  IF v_row.id IS NULL THEN
    SELECT * INTO v_row FROM public.event_context_snapshots WHERE source_table=trim(p_source_table) AND source_event_id=p_source_event_id;
  END IF;
  RETURN v_row;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."create_event_context_snapshot"(p_source_table text, p_source_event_id uuid, p_location_id uuid, p_client_site_id uuid, p_zone_id uuid, p_checkpoint_id uuid, p_module_key text, p_service_agreement_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_jurisdiction_organization_id uuid, p_jurisdiction_rule_set_id uuid, p_authority_snapshot jsonb, p_source_refs jsonb, p_captured_at timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_event_context_snapshot"(p_source_table text, p_source_event_id uuid, p_location_id uuid, p_client_site_id uuid, p_zone_id uuid, p_checkpoint_id uuid, p_module_key text, p_service_agreement_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_jurisdiction_organization_id uuid, p_jurisdiction_rule_set_id uuid, p_authority_snapshot jsonb, p_source_refs jsonb, p_captured_at timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_event_context_snapshot"(p_source_table text, p_source_event_id uuid, p_location_id uuid, p_client_site_id uuid, p_zone_id uuid, p_checkpoint_id uuid, p_module_key text, p_service_agreement_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_jurisdiction_organization_id uuid, p_jurisdiction_rule_set_id uuid, p_authority_snapshot jsonb, p_source_refs jsonb, p_captured_at timestamp with time zone) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_event_context_snapshot"(p_source_table text, p_source_event_id uuid, p_location_id uuid, p_client_site_id uuid, p_zone_id uuid, p_checkpoint_id uuid, p_module_key text, p_service_agreement_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_jurisdiction_organization_id uuid, p_jurisdiction_rule_set_id uuid, p_authority_snapshot jsonb, p_source_refs jsonb, p_captured_at timestamp with time zone) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_file_folder"(p_organization_id uuid, p_space_id uuid, p_parent_folder_id uuid, p_name text, p_client_request_id uuid)
 RETURNS file_folders
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_actor uuid:=auth.uid();v_space public.file_spaces%rowtype;v_folder public.file_folders%rowtype;v_name text:=nullif(trim(coalesce(p_name,'')),'');
BEGIN
  IF v_actor IS NULL OR NOT public.is_admin_for_org(p_organization_id) THEN RAISE EXCEPTION 'Active organization administrator required'; END IF;
  IF p_client_request_id IS NULL THEN RAISE EXCEPTION 'client_request_id is required'; END IF;
  SELECT * INTO v_folder FROM public.file_folders WHERE organization_id=p_organization_id AND client_request_id=p_client_request_id;
  IF FOUND THEN RETURN v_folder; END IF;
  IF v_name IS NULL OR char_length(v_name)>160 OR v_name IN ('.','..') OR v_name ~ '[\\/]' THEN RAISE EXCEPTION 'Folder name is required, must be 160 characters or fewer, and cannot contain slashes'; END IF;
  SELECT * INTO v_space FROM public.file_spaces WHERE id=p_space_id AND organization_id=p_organization_id AND active FOR UPDATE;
  IF v_space.id IS NULL THEN RAISE EXCEPTION 'File space not found'; END IF;
  IF NOT public.file_space_access_allowed(p_organization_id,v_space.sensitivity) THEN RAISE EXCEPTION 'Folder access denied'; END IF;
  IF p_parent_folder_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.file_folders WHERE id=p_parent_folder_id AND organization_id=p_organization_id AND space_id=p_space_id AND active) THEN RAISE EXCEPTION 'Parent folder not found in this file space'; END IF;
  IF EXISTS(SELECT 1 FROM public.file_folders WHERE space_id=p_space_id AND parent_folder_id IS NOT DISTINCT FROM p_parent_folder_id AND lower(name)=lower(v_name) AND active) THEN RAISE EXCEPTION 'A folder with this name already exists here'; END IF;
  INSERT INTO public.file_folders(organization_id,space_id,parent_folder_id,name,folder_key,folder_kind,client_request_id,created_by)
  VALUES(p_organization_id,p_space_id,p_parent_folder_id,v_name,'custom:'||p_client_request_id::text,'custom',p_client_request_id,v_actor) RETURNING * INTO v_folder;
  INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) VALUES(p_organization_id,v_actor,'file_folder_created','file_folders',v_folder.id,jsonb_build_object('space_id',p_space_id,'parent_folder_id',p_parent_folder_id,'name',v_name));
  RETURN v_folder;
END;
$function$;
COMMENT ON FUNCTION "public"."create_file_folder"(p_organization_id uuid, p_space_id uuid, p_parent_folder_id uuid, p_name text, p_client_request_id uuid) IS 'Creates an audited custom folder inside an authorized organization file space.';
REVOKE ALL ON FUNCTION "public"."create_file_folder"(p_organization_id uuid, p_space_id uuid, p_parent_folder_id uuid, p_name text, p_client_request_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_file_folder"(p_organization_id uuid, p_space_id uuid, p_parent_folder_id uuid, p_name text, p_client_request_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_file_folder"(p_organization_id uuid, p_space_id uuid, p_parent_folder_id uuid, p_name text, p_client_request_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_file_folder"(p_organization_id uuid, p_space_id uuid, p_parent_folder_id uuid, p_name text, p_client_request_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_file_import_batch"(p_batch_name text, p_source_file text, p_source_sha256 text, p_parser text, p_manifest_json jsonb DEFAULT '{}'::jsonb, p_schema_json jsonb DEFAULT '{}'::jsonb, p_row_count integer DEFAULT 0, p_duplicate_count integer DEFAULT 0, p_unresolved_count integer DEFAULT 0, p_organization_id uuid DEFAULT NULL::uuid)
 RETURNS file_import_batches
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org_id uuid := p_organization_id;
  v_batch public.file_import_batches%rowtype;
  v_duplicate_of uuid;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF v_org_id IS NULL THEN RAISE EXCEPTION 'Organisation is required'; END IF;
  IF NOT public.is_tenant_import_admin(v_org_id) THEN RAISE EXCEPTION 'Tenant import batch creation denied'; END IF;
  IF nullif(trim(coalesce(p_batch_name,'')),'') IS NULL OR nullif(trim(coalesce(p_source_file,'')),'') IS NULL THEN RAISE EXCEPTION 'Batch name and source file are required'; END IF;
  IF p_row_count<0 OR p_duplicate_count<0 OR p_unresolved_count<0 THEN RAISE EXCEPTION 'Import counts cannot be negative'; END IF;
  IF nullif(trim(coalesce(p_source_sha256,'')),'') IS NOT NULL THEN
    SELECT id INTO v_duplicate_of FROM public.file_import_batches
    WHERE organization_id=v_org_id AND source_sha256=trim(p_source_sha256)
    ORDER BY created_at LIMIT 1;
  END IF;
  INSERT INTO public.file_import_batches(
    organization_id,batch_name,source_file,source_sha256,duplicate_of_batch_id,parser,
    manifest_json,schema_json,row_count,duplicate_count,unresolved_count,created_by
  ) VALUES (
    v_org_id,trim(p_batch_name),trim(p_source_file),nullif(trim(coalesce(p_source_sha256,'')),''),v_duplicate_of,trim(p_parser),
    coalesce(p_manifest_json,'{}'::jsonb),coalesce(p_schema_json,'{}'::jsonb),p_row_count,p_duplicate_count,p_unresolved_count,v_actor
  ) RETURNING * INTO v_batch;
  INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
  VALUES(v_org_id,v_actor,'file_import_batch_created','file_import_batches',v_batch.id,
    jsonb_build_object('source_file',v_batch.source_file,'parser',v_batch.parser,'row_count',v_batch.row_count,'duplicate_count',v_batch.duplicate_count,'unresolved_count',v_batch.unresolved_count,'duplicate_of_batch_id',v_batch.duplicate_of_batch_id));
  RETURN v_batch;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."create_file_import_batch"(p_batch_name text, p_source_file text, p_source_sha256 text, p_parser text, p_manifest_json jsonb, p_schema_json jsonb, p_row_count integer, p_duplicate_count integer, p_unresolved_count integer, p_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_file_import_batch"(p_batch_name text, p_source_file text, p_source_sha256 text, p_parser text, p_manifest_json jsonb, p_schema_json jsonb, p_row_count integer, p_duplicate_count integer, p_unresolved_count integer, p_organization_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_file_import_batch"(p_batch_name text, p_source_file text, p_source_sha256 text, p_parser text, p_manifest_json jsonb, p_schema_json jsonb, p_row_count integer, p_duplicate_count integer, p_unresolved_count integer, p_organization_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_file_import_batch"(p_batch_name text, p_source_file text, p_source_sha256 text, p_parser text, p_manifest_json jsonb, p_schema_json jsonb, p_row_count integer, p_duplicate_count integer, p_unresolved_count integer, p_organization_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_finance_budget"(p_name text, p_fiscal_year integer)
 RETURNS finance_budgets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_budget public.finance_budgets%rowtype;
BEGIN
  SELECT organization_id INTO v_org FROM public.user_profiles WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_org IS NULL OR NOT public.is_admin_for_org(v_org) THEN RAISE EXCEPTION 'Active finance administrator required'; END IF;
  IF nullif(trim(p_name), '') IS NULL OR p_fiscal_year NOT BETWEEN 2000 AND 2200 THEN RAISE EXCEPTION 'Budget name and fiscal year are required'; END IF;
  INSERT INTO public.finance_budgets(organization_id, name, fiscal_year, created_by)
  VALUES (v_org, trim(p_name), p_fiscal_year, v_actor)
  RETURNING * INTO v_budget;
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_org, v_actor, 'finance_budget_created', 'finance_budgets', v_budget.id, jsonb_build_object('fiscal_year', p_fiscal_year));
  RETURN v_budget;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."create_finance_budget"(p_name text, p_fiscal_year integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_finance_budget"(p_name text, p_fiscal_year integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_finance_budget"(p_name text, p_fiscal_year integer) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_finance_budget"(p_name text, p_fiscal_year integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_finance_pl_period"(p_name text, p_period_start date, p_period_end date)
 RETURNS finance_pl_periods
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_period public.finance_pl_periods%rowtype;
BEGIN
  SELECT organization_id INTO v_org FROM public.user_profiles WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_org IS NULL OR NOT public.is_admin_for_org(v_org) THEN RAISE EXCEPTION 'Active finance administrator required'; END IF;
  IF nullif(trim(p_name), '') IS NULL OR p_period_start IS NULL OR p_period_end IS NULL OR p_period_end < p_period_start THEN RAISE EXCEPTION 'Valid period name and dates are required'; END IF;
  INSERT INTO public.finance_pl_periods(organization_id, name, period_start, period_end, status, created_by)
  VALUES(v_org, trim(p_name), p_period_start, p_period_end, 'draft', v_actor)
  ON CONFLICT (organization_id, period_start, period_end) DO UPDATE SET name = EXCLUDED.name, updated_at = now()
  RETURNING * INTO v_period;
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES(v_org, v_actor, 'finance_pl_period_created', 'finance_pl_periods', v_period.id, jsonb_build_object('name', v_period.name, 'period_start', v_period.period_start, 'period_end', v_period.period_end));
  RETURN v_period;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."create_finance_pl_period"(p_name text, p_period_start date, p_period_end date) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_finance_pl_period"(p_name text, p_period_start date, p_period_end date) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_finance_pl_period"(p_name text, p_period_start date, p_period_end date) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_finance_pl_period"(p_name text, p_period_start date, p_period_end date) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_finance_tax_period"(p_period_start date, p_period_end date, p_filing_due_date date)
 RETURNS finance_tax_periods
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_period public.finance_tax_periods%rowtype;
BEGIN
  SELECT organization_id INTO v_org FROM public.user_profiles WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_org IS NULL OR NOT public.is_admin_for_org(v_org) THEN RAISE EXCEPTION 'Active finance administrator required'; END IF;
  IF p_period_start IS NULL OR p_period_end IS NULL OR p_filing_due_date IS NULL OR p_period_end < p_period_start OR p_filing_due_date < p_period_end THEN RAISE EXCEPTION 'Valid tax period and filing due dates are required'; END IF;
  INSERT INTO public.finance_tax_periods(organization_id, period_start, period_end, filing_due_date, status, created_by)
  VALUES(v_org, p_period_start, p_period_end, p_filing_due_date, 'open', v_actor)
  ON CONFLICT (organization_id, period_start, period_end) DO UPDATE SET filing_due_date = EXCLUDED.filing_due_date
  RETURNING * INTO v_period;
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES(v_org, v_actor, 'finance_tax_period_created', 'finance_tax_periods', v_period.id, jsonb_build_object('period_start', v_period.period_start, 'period_end', v_period.period_end, 'filing_due_date', v_period.filing_due_date));
  RETURN v_period;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."create_finance_tax_period"(p_period_start date, p_period_end date, p_filing_due_date date) FROM PUBLIC, "anon", "authenticated", "service_role";
