    jsonb_build_object('name', v_row.name, 'operating_organization_id', p_operating_organization_id));
  return v_row;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."create_operating_organization_workplace"(p_operating_organization_id uuid, p_name text, p_address text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_operating_organization_workplace"(p_operating_organization_id uuid, p_name text, p_address text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_operating_organization_workplace"(p_operating_organization_id uuid, p_name text, p_address text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_operating_organization_workplace"(p_operating_organization_id uuid, p_name text, p_address text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_operating_roster_work_unit"(p_operating_organization_id uuid, p_name text, p_work_unit_type text, p_service_type text, p_patrol_route_id uuid DEFAULT NULL::uuid, p_service_agreement_location_id uuid DEFAULT NULL::uuid, p_service_agreement_module_id uuid DEFAULT NULL::uuid, p_workplace_id uuid DEFAULT NULL::uuid, p_team_id uuid DEFAULT NULL::uuid, p_cost_centre_id uuid DEFAULT NULL::uuid)
 RETURNS roster_work_units
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_unit public.roster_work_units%rowtype;
  v_agreement uuid;
begin
  if not public.user_can_operate_organization(p_operating_organization_id)
    or not public.is_admin_for_org(p_operating_organization_id) then
    raise exception 'Active authorized operating branch administrator required';
  end if;
  if nullif(trim(coalesce(p_name, '')), '') is null or nullif(trim(coalesce(p_service_type, '')), '') is null then
    raise exception 'Name and service type are required';
  end if;
  if p_work_unit_type = 'patrol' then
    if p_patrol_route_id is null or not exists(select 1 from public.patrol_routes route where route.id = p_patrol_route_id and route.organization_id = p_operating_organization_id and route.is_active) then raise exception 'Active patrol route in this operating branch required'; end if;
  elsif p_work_unit_type = 'static' then
    select location.service_agreement_id into v_agreement from public.service_agreement_locations location join public.service_agreements agreement on agreement.id = location.service_agreement_id and agreement.provider_organization_id = p_operating_organization_id where location.id = p_service_agreement_location_id and location.status = 'active';
    if v_agreement is null or not exists(select 1 from public.service_agreement_modules module where module.id = p_service_agreement_module_id and module.service_agreement_id = v_agreement and module.enabled and module.module_key = 'static_guarding') then raise exception 'Active static guarding agreement location and module required'; end if;
  elsif p_work_unit_type = 'internal' then
    if p_workplace_id is null or not exists(select 1 from public.organization_workplaces workplace where workplace.id = p_workplace_id and workplace.organization_id = p_operating_organization_id and workplace.active) then raise exception 'Active provider workplace required'; end if;
    if p_team_id is not null and not exists(select 1 from public.teams team where team.id = p_team_id and team.organization_id = p_operating_organization_id and team.status = 'active') then raise exception 'Active team in this operating branch required'; end if;
    if p_cost_centre_id is not null and not exists(select 1 from public.cost_centres centre where centre.id = p_cost_centre_id and centre.organization_id = p_operating_organization_id and centre.active) then raise exception 'Active cost centre in this operating branch required'; end if;
  else raise exception 'Unsupported work unit type'; end if;
  insert into public.roster_work_units(organization_id, name, work_unit_type, service_type, patrol_route_id, service_agreement_location_id, service_agreement_module_id, workplace_id, team_id, cost_centre_id, created_by)
  values(p_operating_organization_id, trim(p_name), p_work_unit_type, trim(p_service_type), p_patrol_route_id, p_service_agreement_location_id, p_service_agreement_module_id, p_workplace_id, p_team_id, p_cost_centre_id, v_actor)
  returning * into v_unit;
  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values(p_operating_organization_id, v_actor, 'roster_work_unit_created', 'roster_work_units', v_unit.id,
    jsonb_build_object('work_unit_type', v_unit.work_unit_type, 'service_type', v_unit.service_type, 'operating_organization_id', p_operating_organization_id));
  return v_unit;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."create_operating_roster_work_unit"(p_operating_organization_id uuid, p_name text, p_work_unit_type text, p_service_type text, p_patrol_route_id uuid, p_service_agreement_location_id uuid, p_service_agreement_module_id uuid, p_workplace_id uuid, p_team_id uuid, p_cost_centre_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_operating_roster_work_unit"(p_operating_organization_id uuid, p_name text, p_work_unit_type text, p_service_type text, p_patrol_route_id uuid, p_service_agreement_location_id uuid, p_service_agreement_module_id uuid, p_workplace_id uuid, p_team_id uuid, p_cost_centre_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_operating_roster_work_unit"(p_operating_organization_id uuid, p_name text, p_work_unit_type text, p_service_type text, p_patrol_route_id uuid, p_service_agreement_location_id uuid, p_service_agreement_module_id uuid, p_workplace_id uuid, p_team_id uuid, p_cost_centre_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_operating_roster_work_unit"(p_operating_organization_id uuid, p_name text, p_work_unit_type text, p_service_type text, p_patrol_route_id uuid, p_service_agreement_location_id uuid, p_service_agreement_module_id uuid, p_workplace_id uuid, p_team_id uuid, p_cost_centre_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_operating_workshop_roster_work_unit"(p_operating_organization_id uuid, p_name text, p_work_order_id uuid, p_workplace_id uuid, p_team_id uuid DEFAULT NULL::uuid, p_cost_centre_id uuid DEFAULT NULL::uuid)
 RETURNS roster_work_units
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_order public.workshop_work_orders%rowtype;
  v_unit public.roster_work_units%rowtype;
BEGIN
  IF v_actor IS NULL
    OR NOT public.user_can_operate_organization(p_operating_organization_id)
    OR NOT public.is_admin_for_org(p_operating_organization_id) THEN
    RAISE EXCEPTION 'Active authorized operating branch administrator required';
  END IF;
  IF nullif(trim(p_name), '') IS NULL THEN RAISE EXCEPTION 'Work unit name is required'; END IF;
  SELECT * INTO v_order FROM public.workshop_work_orders
    WHERE id = p_work_order_id AND organization_id = p_operating_organization_id FOR UPDATE;
  IF NOT FOUND OR v_order.status NOT IN ('draft', 'approved', 'in_progress') THEN
    RAISE EXCEPTION 'Open work order in this operating branch required';
  END IF;
  IF v_order.client_organization_id IS NULL THEN
    RAISE EXCEPTION 'Manufacturing and maintenance work must be assigned to a client. Set the client on the work order first.';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.organization_workplaces
    WHERE id = p_workplace_id AND organization_id = p_operating_organization_id AND active) THEN
    RAISE EXCEPTION 'Active provider workplace required';
  END IF;
  IF p_team_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.teams
    WHERE id = p_team_id AND organization_id = p_operating_organization_id AND status = 'active') THEN
    RAISE EXCEPTION 'Active team in this operating branch required';
  END IF;
  IF p_cost_centre_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.cost_centres
    WHERE id = p_cost_centre_id AND organization_id = p_operating_organization_id AND active) THEN
    RAISE EXCEPTION 'Active cost centre in this operating branch required';
  END IF;
  IF EXISTS (SELECT 1 FROM public.roster_work_units WHERE workshop_work_order_id = v_order.id
    AND organization_id = p_operating_organization_id) THEN
    RAISE EXCEPTION 'This work order already has a roster work unit. Roster additional staff against that unit.';
  END IF;
  INSERT INTO public.roster_work_units (
    organization_id, name, work_unit_type, service_type, workshop_work_order_id,
    workplace_id, team_id, cost_centre_id, created_by
  ) VALUES (
    p_operating_organization_id, trim(p_name), 'workshop', v_order.kind, v_order.id,
    p_workplace_id, p_team_id, p_cost_centre_id, v_actor
  ) RETURNING * INTO v_unit;
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (p_operating_organization_id, v_actor, 'roster_work_unit_created', 'roster_work_units', v_unit.id,
    jsonb_build_object('work_unit_type', 'workshop', 'service_type', v_order.kind,
      'workshop_work_order_id', v_order.id, 'operating_organization_id', p_operating_organization_id));
  RETURN v_unit;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."create_operating_workshop_roster_work_unit"(p_operating_organization_id uuid, p_name text, p_work_order_id uuid, p_workplace_id uuid, p_team_id uuid, p_cost_centre_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_operating_workshop_roster_work_unit"(p_operating_organization_id uuid, p_name text, p_work_order_id uuid, p_workplace_id uuid, p_team_id uuid, p_cost_centre_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_operating_workshop_roster_work_unit"(p_operating_organization_id uuid, p_name text, p_work_order_id uuid, p_workplace_id uuid, p_team_id uuid, p_cost_centre_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_operating_workshop_roster_work_unit"(p_operating_organization_id uuid, p_name text, p_work_order_id uuid, p_workplace_id uuid, p_team_id uuid, p_cost_centre_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_patrol_route_from_agreement"(p_client_request_id uuid, p_service_agreement_id uuid, p_name text DEFAULT NULL::text, p_operating_organization_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(route_id uuid, route_name text, created boolean, attached_places integer, skipped_places integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_agreement public.service_agreements%rowtype;
  v_route public.patrol_routes%rowtype;
  v_config public.client_site_patrol_config%rowtype;
  v_existing_route uuid;
  v_replay uuid;
  v_config_ids uuid[];
  v_name text := nullif(trim(coalesce(p_name, '')), '');
  v_attached integer := 0;
  v_skipped integer := 0;
  v_start time;
  v_end time;
  v_module_id uuid;
  v_location_id uuid;
  v_operating uuid;
  v_schedule_module text;
begin
  if v_actor is null then raise exception 'Authentication required'; end if;
  if p_client_request_id is null then raise exception 'client_request_id is required'; end if;

  select * into v_agreement from public.service_agreements where id = p_service_agreement_id;
  if not found then raise exception 'Service agreement not found'; end if;
  if v_agreement.agreement_type <> 'operational' then
    raise exception 'A patrol run can only be built from a live operational agreement';
  end if;
  -- The route belongs to the branch that delivers. It is named by the caller, otherwise it is the branch whose
  -- accepted schedules (patrol configs) carry this agreement, otherwise the agreement holder itself.
  v_operating := coalesce(p_operating_organization_id,
    (select cspc.organization_id from public.client_site_patrol_config cspc
       join public.service_agreement_delivery_schedules sads on (cspc.delivery_schedule_id = sads.id OR (cspc.proposal_scope_schedule_id IS NOT NULL AND sads.proposal_scope_schedule_id = cspc.proposal_scope_schedule_id))
      where sads.service_agreement_id = v_agreement.id and sads.active and cspc.active
      order by cspc.created_at desc limit 1),
    v_agreement.provider_organization_id);
  if v_operating <> v_agreement.provider_organization_id and not (v_operating = any(public.get_descendant_organizations(v_agreement.provider_organization_id))) then
    raise exception 'The operating branch must be the agreement holder or one of its branches';
  end if;
  if not public.is_admin_for_org(v_operating) then
    raise exception 'Active authorized operating branch administrator required';
  end if;

  -- Idempotent replay on the same client request id.
  select target_id into v_replay from public.audit_log
  where action = 'patrol_route_created_from_agreement' and metadata->>'client_request_id' = p_client_request_id::text
  limit 1;
  if v_replay is not null then
    select * into v_route from public.patrol_routes where id = v_replay;
    return query select v_route.id, v_route.name, false,
      (select count(*)::integer from public.client_site_patrol_config c where c.patrol_route_id = v_route.id), 0;
    return;
  end if;

  -- Contract configs for this agreement (joined through the accepted schedule they came from).
  select array_agg(cspc.id) into v_config_ids
  from public.client_site_patrol_config cspc
  join public.service_agreement_delivery_schedules sads on (cspc.delivery_schedule_id = sads.id OR (cspc.proposal_scope_schedule_id IS NOT NULL AND sads.proposal_scope_schedule_id = cspc.proposal_scope_schedule_id))
  where sads.service_agreement_id = v_agreement.id
    and sads.active
    and cspc.organization_id = v_operating
    and cspc.active;

  if v_config_ids is null then
    raise exception 'This agreement has no scheduled patrol places yet. Add delivery schedules in the quote or a variation first';
  end if;

  -- Already routed (fully): return that route instead of making a second one.
  select c.patrol_route_id into v_existing_route from public.client_site_patrol_config c
  where c.id = any(v_config_ids) and c.patrol_route_id is not null limit 1;
  if v_existing_route is not null and not exists (select 1 from public.client_site_patrol_config c where c.id = any(v_config_ids) and c.patrol_route_id is null) then
    select * into v_route from public.patrol_routes where id = v_existing_route;
    return query select v_route.id, v_route.name, false, cardinality(v_config_ids), 0;
    return;
  end if;

  if v_existing_route is not null then
    select * into v_route from public.patrol_routes where id = v_existing_route;
  else
    select min(c.window_start), max(c.window_end) into v_start, v_end from public.client_site_patrol_config c where c.id = any(v_config_ids);
    insert into public.patrol_routes(organization_id, name, description, route_type, assignment_type, checkpoint_mode, default_start_time, default_end_time, is_active)
    values (
      v_operating,
      coalesce(v_name, v_agreement.name || ' patrol run'),
      'Built from the accepted agreement "' || v_agreement.name || '". Stops come from its delivery schedules.',
      'mobile', 'client_patrol', 'none', v_start, v_end, true
    )
    returning * into v_route;
  end if;

  for v_config in
    select cspc.* from public.client_site_patrol_config cspc
    where cspc.id = any(v_config_ids) and cspc.patrol_route_id is null
    order by cspc.preferred_stop_order, cspc.created_at
  loop
    begin
      update public.client_site_patrol_config
      set patrol_route_id = v_route.id, updated_at = now()
      where id = v_config.id;
    exception when unique_violation then
      -- Same site + module already on this route (duplicate schedule); leave it unrouted and report it.
      v_skipped := v_skipped + 1;
      continue;
    end;
    v_attached := v_attached + 1;

    if v_config.site_id is not null then
      insert into public.patrol_route_sites(patrol_route_id, site_id, expected_visits_per_shift, preferred_stop_order, dwell_minutes, sla_arrive_within_minutes, required_module, preferred_time_window, notes)
      values (
        v_route.id, v_config.site_id, v_config.visits_per_shift, v_config.preferred_stop_order, v_config.dwell_minutes, v_config.sla_arrive_within_minutes, v_config.module_key,
        case when v_config.window_start is not null then to_char(v_config.window_start, 'HH24:MI') || '-' || coalesce(to_char(v_config.window_end, 'HH24:MI'), '') end,
        v_config.officer_instructions
      )
      on conflict (patrol_route_id, site_id) do nothing;
    end if;

    -- Contract inheritance for generated stops: which agreement module and covered place this stop serves.
    select sads.module_key into v_schedule_module from public.service_agreement_delivery_schedules sads
    where (v_config.delivery_schedule_id = sads.id OR (v_config.proposal_scope_schedule_id IS NOT NULL AND sads.proposal_scope_schedule_id = v_config.proposal_scope_schedule_id)) and sads.service_agreement_id = v_agreement.id limit 1;
    select sam.id into v_module_id from public.service_agreement_modules sam
    where sam.service_agreement_id = v_agreement.id and sam.enabled
      and sam.module_key = any(array_remove(array[v_schedule_module, v_config.module_key, case when v_config.module_key = 'general_patrol' then 'patrol' end], null))
    order by case when sam.module_key = v_schedule_module then 0 when sam.module_key = v_config.module_key then 1 else 2 end
    limit 1;
    select sal.id into v_location_id from public.service_agreement_locations sal
    where sal.service_agreement_id = v_agreement.id and sal.status = 'active'
      and sal.site_id is not distinct from v_config.site_id and sal.zone_id is not distinct from v_config.zone_id
    limit 1;
    insert into public.patrol_route_stop_modules(organization_id, patrol_config_id, module_key, is_required, display_order, service_agreement_module_id, service_agreement_location_id)
    values (v_operating, v_config.id, coalesce(v_schedule_module, v_config.module_key), true, v_config.preferred_stop_order, v_module_id, v_location_id)
    on conflict (patrol_config_id, module_key) do nothing;
  end loop;

  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (v_agreement.provider_organization_id, v_actor, 'patrol_route_created_from_agreement', 'patrol_routes', v_route.id,
    jsonb_build_object('client_request_id', p_client_request_id, 'service_agreement_id', v_agreement.id, 'created', v_existing_route is null,
      'attached_places', v_attached, 'skipped_places', v_skipped, 'operating_organization_id', v_operating));

  return query select v_route.id, v_route.name, v_existing_route is null, v_attached, v_skipped;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."create_patrol_route_from_agreement"(p_client_request_id uuid, p_service_agreement_id uuid, p_name text, p_operating_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_patrol_route_from_agreement"(p_client_request_id uuid, p_service_agreement_id uuid, p_name text, p_operating_organization_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_patrol_route_from_agreement"(p_client_request_id uuid, p_service_agreement_id uuid, p_name text, p_operating_organization_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_patrol_route_from_agreement"(p_client_request_id uuid, p_service_agreement_id uuid, p_name text, p_operating_organization_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_payroll_export_batch"(p_client_request_id uuid, p_organization_id uuid, p_period_from date, p_period_to date, p_format text DEFAULT 'csv'::text, p_notes text DEFAULT NULL::text)
 RETURNS TABLE(batch_id uuid, timesheet_count integer, total_hours numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_batch public.payroll_export_batches%rowtype; v_ids uuid[]; v_blocker text;
  v_count integer; v_hours numeric; v_updated integer;
  v_notes text := nullif(btrim(p_notes),'');
BEGIN
  IF NOT public.is_timesheet_payroll_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Active employer payroll administrator required' USING ERRCODE='42501';
  END IF;
  IF p_client_request_id IS NULL OR p_period_from IS NULL OR p_period_to IS NULL OR p_period_to<p_period_from THEN
    RAISE EXCEPTION 'A request ID and valid export period are required';
  END IF;
  IF p_format NOT IN ('csv','json','ird_csv') OR p_format IS NULL THEN RAISE EXCEPTION 'Unsupported payroll export format'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('payroll_export:'||p_organization_id::text,0));

  SELECT b.* INTO v_batch FROM public.payroll_export_batches b
  WHERE b.organization_id=p_organization_id AND b.client_request_id=p_client_request_id;
  IF FOUND THEN
    IF v_batch.exported_by IS DISTINCT FROM v_actor
      OR v_batch.period_from IS DISTINCT FROM p_period_from
      OR v_batch.period_to IS DISTINCT FROM p_period_to
      OR v_batch.format IS DISTINCT FROM p_format
      OR v_batch.notes IS DISTINCT FROM v_notes THEN
      RAISE EXCEPTION 'Request ID already used with different export details';
    END IF;
    RETURN QUERY SELECT v_batch.id,v_batch.timesheet_count,v_batch.total_hours;
    RETURN;
  END IF;

  SELECT array_agg(locked.id),count(*)::integer,coalesce(sum(coalesce(locked.actual_hours,locked.work_derived_hours,0)),0)
  INTO v_ids,v_count,v_hours
  FROM (
    SELECT t.id,t.actual_hours,t.work_derived_hours FROM public.timesheets t
    WHERE t.organization_id=p_organization_id AND t.status='approved' AND t.payroll_export_batch_id IS NULL
      AND t.period_start>=p_period_from AND t.period_end<=p_period_to
    ORDER BY t.id FOR UPDATE
  ) locked;
  IF v_count=0 THEN RAISE EXCEPTION 'No approved unexported timesheets in this period'; END IF;
  SELECT public.timesheet_dispatch_pay_review_blocker(t.id) INTO v_blocker FROM public.timesheets t
    WHERE t.id=ANY(v_ids) AND public.timesheet_dispatch_pay_review_blocker(t.id) IS NOT NULL ORDER BY t.id LIMIT 1;
  IF v_blocker IS NOT NULL THEN RAISE EXCEPTION 'Payroll export blocked: %',v_blocker; END IF;

  INSERT INTO public.payroll_export_batches(organization_id,exported_by,period_from,period_to,format,timesheet_count,total_hours,notes,client_request_id)
    VALUES(p_organization_id,v_actor,p_period_from,p_period_to,p_format,v_count,v_hours,v_notes,p_client_request_id)
    RETURNING * INTO v_batch;
  UPDATE public.timesheets t SET payroll_export_batch_id=v_batch.id,status='paid'
    WHERE t.organization_id=p_organization_id AND t.id=ANY(v_ids);
  GET DIAGNOSTICS v_updated = ROW_COUNT;
  IF v_updated<>v_count THEN RAISE EXCEPTION 'Payroll batch timesheet count could not be confirmed'; END IF;
  INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
    VALUES(p_organization_id,v_actor,'payroll_export_batch_created','payroll_export_batches',v_batch.id,
      jsonb_build_object('period_from',p_period_from,'period_to',p_period_to,'timesheet_count',v_count,
        'total_hours',v_hours,'format',p_format,'client_request_id',p_client_request_id));
  RETURN QUERY SELECT v_batch.id,v_batch.timesheet_count,v_batch.total_hours;
END $function$;
REVOKE ALL ON FUNCTION "public"."create_payroll_export_batch"(p_client_request_id uuid, p_organization_id uuid, p_period_from date, p_period_to date, p_format text, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_payroll_export_batch"(p_client_request_id uuid, p_organization_id uuid, p_period_from date, p_period_to date, p_format text, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_payroll_export_batch"(p_client_request_id uuid, p_organization_id uuid, p_period_from date, p_period_to date, p_format text, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_payroll_export_batch"(p_client_request_id uuid, p_organization_id uuid, p_period_from date, p_period_to date, p_format text, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_performance_review"(p_client_request_id uuid, p_cycle_id uuid, p_staff_id uuid, p_reviewer_user_id uuid)
 RETURNS performance_reviews
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid(); v_cycle public.performance_review_cycles%rowtype; v_review public.performance_reviews%rowtype;
begin
  if p_client_request_id is null then raise exception 'client_request_id is required'; end if;
  select * into v_cycle from public.performance_review_cycles where id=p_cycle_id for update;
  if not found or not public.is_admin_for_org(v_cycle.organization_id) then raise exception 'Open review cycle not found in your organization'; end if;
  if v_cycle.status<>'open' then raise exception 'Reviews can only be created for an open cycle'; end if;
  if not exists(select 1 from public.staff_profiles sp where sp.id=p_staff_id and sp.organization_id=v_cycle.organization_id) then raise exception 'Staff member not found in this organization'; end if;
  if not exists(select 1 from public.user_profiles u where u.id=p_reviewer_user_id and u.organization_id=v_cycle.organization_id and u.deactivated_at is null) then raise exception 'Reviewer must be an active organization member'; end if;
  select * into v_review from public.performance_reviews where organization_id=v_cycle.organization_id and client_request_id=p_client_request_id;
  if found then return v_review; end if;
  insert into public.performance_reviews(organization_id,cycle_id,staff_id,reviewer_user_id,client_request_id) values(v_cycle.organization_id,p_cycle_id,p_staff_id,p_reviewer_user_id,p_client_request_id) returning * into v_review;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_cycle.organization_id,v_actor,'performance_review_created','performance_reviews',v_review.id,jsonb_build_object('cycle_id',p_cycle_id,'staff_id',p_staff_id,'reviewer_user_id',p_reviewer_user_id));
  return v_review;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."create_performance_review"(p_client_request_id uuid, p_cycle_id uuid, p_staff_id uuid, p_reviewer_user_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_performance_review"(p_client_request_id uuid, p_cycle_id uuid, p_staff_id uuid, p_reviewer_user_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_performance_review"(p_client_request_id uuid, p_cycle_id uuid, p_staff_id uuid, p_reviewer_user_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_performance_review"(p_client_request_id uuid, p_cycle_id uuid, p_staff_id uuid, p_reviewer_user_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_provider_branch"(p_client_request_id uuid, p_parent_organization_id uuid, p_name text, p_contact_email text DEFAULT NULL::text, p_contact_phone text DEFAULT NULL::text)
 RETURNS organizations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_parent public.organizations%rowtype;
  v_branch public.organizations%rowtype;
  v_name text := nullif(trim(coalesce(p_name, '')), '');
  v_key text;
begin
  if p_client_request_id is null then raise exception 'client_request_id is required'; end if;
  if v_actor is null or not public.user_can_operate_organization(p_parent_organization_id) or not public.is_admin_for_org(p_parent_organization_id) then
    raise exception 'Active organisation administrator required';
  end if;
  select * into v_parent from public.organizations where id = p_parent_organization_id for update;
  if not found or not v_parent.active or v_parent.organization_type not in ('owner', 'service_provider', 'branch') then
    raise exception 'Branches can only be added to an active provider organisation';
  end if;

  select * into v_branch from public.organizations
  where parent_organization_id = v_parent.id and client_request_id = p_client_request_id;
  if found then return v_branch; end if;

  if v_name is null or char_length(v_name) > 200 then raise exception 'Branch name is required and must be 200 characters or fewer'; end if;
  if exists (select 1 from public.organizations o where o.parent_organization_id = v_parent.id and lower(trim(o.name)) = lower(v_name) and o.status <> 'archived') then
    raise exception 'A branch with this name already exists';
  end if;

  insert into public.organizations (name, organization_type, parent_organization_id, active, status, contact_email, contact_phone, client_request_id)
  values (v_name, 'branch', v_parent.id, true, 'active',
          nullif(lower(trim(coalesce(p_contact_email, ''))), ''), nullif(trim(coalesce(p_contact_phone, '')), ''), p_client_request_id)
  returning * into v_branch;

  -- Inherit the parent's enabled modules, dependencies first, so the branch is usable immediately.
  for v_key in
    select pm.module_key from public.organization_modules pm
    where pm.organization_id = v_parent.id and pm.enabled
    order by (exists (select 1 from public.module_dependencies d where d.module_key = pm.module_key)), pm.module_key
  loop
    insert into public.organization_modules (organization_id, module_key, enabled)
    values (v_branch.id, v_key, true)
    on conflict (organization_id, module_key) do update set enabled = true;
  end loop;

  insert into public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (v_parent.id, v_actor, 'provider_branch_created', 'organizations', v_branch.id,
          jsonb_build_object('name', v_branch.name, 'client_request_id', p_client_request_id));
  return v_branch;
end;
$function$;
COMMENT ON FUNCTION "public"."create_provider_branch"(p_client_request_id uuid, p_parent_organization_id uuid, p_name text, p_contact_email text, p_contact_phone text) IS 'Organisation settings: an administrator of an active provider organisation adds a branch (active immediately, inherits the parent''s enabled modules). Idempotent on (parent, client_request_id).';
REVOKE ALL ON FUNCTION "public"."create_provider_branch"(p_client_request_id uuid, p_parent_organization_id uuid, p_name text, p_contact_email text, p_contact_phone text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_provider_branch"(p_client_request_id uuid, p_parent_organization_id uuid, p_name text, p_contact_email text, p_contact_phone text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_provider_branch"(p_client_request_id uuid, p_parent_organization_id uuid, p_name text, p_contact_email text, p_contact_phone text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."create_recruitment_candidate"(p_client_request_id uuid, p_vacancy_id uuid, p_first_name text, p_last_name text, p_email text, p_phone text DEFAULT NULL::text, p_source text DEFAULT NULL::text, p_resume_storage_path text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS recruitment_candidates
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid := auth.uid(); v_vacancy public.recruitment_vacancies%rowtype; v_row public.recruitment_candidates%rowtype;
begin
  if p_client_request_id is null then raise exception 'client_request_id is required'; end if;
  select * into v_vacancy from public.recruitment_vacancies where id=p_vacancy_id for update;
  if not found or not public.is_admin_for_org(v_vacancy.organization_id) then raise exception 'Open vacancy not found in your organization'; end if;
  if v_vacancy.status<>'open' then raise exception 'Candidates can only be added to an open vacancy'; end if;
  select * into v_row from public.recruitment_candidates where organization_id=v_vacancy.organization_id and client_request_id=p_client_request_id;
  if found then return v_row; end if;
  if nullif(trim(p_first_name),'') is null or nullif(trim(p_last_name),'') is null or nullif(lower(trim(p_email)),'') is null then raise exception 'Candidate name and email are required'; end if;
  insert into public.recruitment_candidates(organization_id,vacancy_id,first_name,last_name,email,phone,source,resume_storage_path,notes,client_request_id,created_by)
  values(v_vacancy.organization_id,v_vacancy.id,trim(p_first_name),trim(p_last_name),lower(trim(p_email)),nullif(trim(coalesce(p_phone,'')),''),nullif(trim(coalesce(p_source,'')),''),nullif(trim(coalesce(p_resume_storage_path,'')),''),nullif(trim(coalesce(p_notes,'')),''),p_client_request_id,v_actor) returning * into v_row;
  insert into public.recruitment_candidate_events(candidate_id,organization_id,to_stage,note,actor_user_id) values(v_row.id,v_row.organization_id,'applied','Candidate added',v_actor);
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_row.organization_id,v_actor,'recruitment_candidate_created','recruitment_candidates',v_row.id,jsonb_build_object('vacancy_id',v_row.vacancy_id,'client_request_id',p_client_request_id));
  return v_row;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."create_recruitment_candidate"(p_client_request_id uuid, p_vacancy_id uuid, p_first_name text, p_last_name text, p_email text, p_phone text, p_source text, p_resume_storage_path text, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_recruitment_candidate"(p_client_request_id uuid, p_vacancy_id uuid, p_first_name text, p_last_name text, p_email text, p_phone text, p_source text, p_resume_storage_path text, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_recruitment_candidate"(p_client_request_id uuid, p_vacancy_id uuid, p_first_name text, p_last_name text, p_email text, p_phone text, p_source text, p_resume_storage_path text, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_recruitment_candidate"(p_client_request_id uuid, p_vacancy_id uuid, p_first_name text, p_last_name text, p_email text, p_phone text, p_source text, p_resume_storage_path text, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_roster_shift"(p_officer_user_id uuid, p_service_type text, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_location_id uuid DEFAULT NULL::uuid, p_zone_id uuid DEFAULT NULL::uuid, p_patrol_route_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text, p_publish boolean DEFAULT false, p_organization_id uuid DEFAULT NULL::uuid)
 RETURNS shifts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_profile public.user_profiles%rowtype;
  v_staff public.staff_profiles%rowtype;
  v_shift public.shifts%rowtype;
  v_org uuid;
begin
  if v_actor is null then raise exception 'Authentication required'; end if;
  select * into v_profile from public.user_profiles where id = p_officer_user_id and deactivated_at is null;
  if not found or v_profile.organization_id is null then raise exception 'Active officer profile not found'; end if;

  v_org := coalesce(p_organization_id, v_profile.organization_id);
  if not exists (select 1 from public.organizations o where o.id = v_org and o.active) then raise exception 'Operating organisation not found'; end if;
  if not public.is_admin_for_org(v_org) then raise exception 'Not authorised to roster for this organisation'; end if;
  if v_profile.role not in ('officer', 'admin_officer') then raise exception 'Selected user is not rosterable as an officer'; end if;

  -- The officer works at their home organisation, or at a branch that has authorised them to be rostered there.
  if v_org <> v_profile.organization_id and not exists (
    select 1 from public.staff_branch_authorisations a
    where a.user_id = p_officer_user_id
      and a.branch_org_id = v_org
      and a.status = 'active'
      and a.can_be_rostered
      and (a.starts_on is null or a.starts_on <= current_date)
      and (a.ends_on is null or a.ends_on >= current_date)
  ) then raise exception 'Officer is not authorised to be rostered at this branch'; end if;

  -- Employment is corporate: the staff profile lives with the employer, which may be the branch's parent.
  select s.* into v_staff
  from public.staff_profiles s
  where (s.id = p_officer_user_id or s.user_id = p_officer_user_id)
    and (
      s.organization_id = v_org
      or s.organization_id = v_profile.organization_id
      or s.organization_id = v_profile.employer_organization_id
      or v_org = any(public.get_descendant_organizations(s.organization_id))
    )
  order by (s.organization_id = v_org) desc, (s.organization_id = v_profile.employer_organization_id) desc, (s.organization_id = v_profile.organization_id) desc
  limit 1;
  if not found or not v_staff.work_ready then raise exception 'Officer is not work ready'; end if;

  if p_scheduled_start is null or p_scheduled_end is null or p_scheduled_start >= p_scheduled_end then raise exception 'Shift end must be after shift start'; end if;
  if p_scheduled_start < now() - interval '5 minutes' or p_scheduled_end - p_scheduled_start > interval '24 hours' then raise exception 'Shift timing is outside the accepted range'; end if;
  if nullif(trim(coalesce(p_service_type, '')), '') is null then raise exception 'Service type is required'; end if;
  if exists (
    select 1 from public.leave_requests l
    where l.staff_id = v_staff.id and l.status = 'approved'
      and daterange(l.starts_on, l.ends_on, '[]') && daterange(p_scheduled_start::date, p_scheduled_end::date, '[]')
  ) then raise exception 'Officer has approved leave during this shift'; end if;
  if exists (
    select 1 from public.shifts s
    where s.officer_user_id = p_officer_user_id
      and s.status not in ('declined', 'cancelled')
      and s.scheduled_end > s.scheduled_start
      and s.scheduled_start < p_scheduled_end
      and s.scheduled_end > p_scheduled_start
  ) then raise exception 'Officer already has an overlapping shift'; end if;

  insert into public.shifts(organization_id, officer_user_id, service_type, location_id, zone_id, patrol_route_id, scheduled_start, scheduled_end, status, notes)
  values (v_org, p_officer_user_id, trim(p_service_type), p_location_id, p_zone_id, p_patrol_route_id, p_scheduled_start, p_scheduled_end, case when p_publish then 'published' else 'scheduled' end, nullif(trim(coalesce(p_notes, '')), ''))
  returning * into v_shift;

  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (v_org, v_actor, 'roster_shift_created', 'shifts', v_shift.id, jsonb_build_object(
    'officer_user_id', p_officer_user_id,
    'officer_home_organization_id', v_profile.organization_id,
    'staff_id', v_staff.id,
    'scheduled_start', p_scheduled_start,
    'scheduled_end', p_scheduled_end,
    'status', v_shift.status
  ));
  return v_shift;
end;
$function$;
COMMENT ON FUNCTION "public"."create_roster_shift"(p_officer_user_id uuid, p_service_type text, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_location_id uuid, p_zone_id uuid, p_patrol_route_id uuid, p_notes text, p_publish boolean, p_organization_id uuid) IS 'Creates a field shift for an officer at the operating organisation p_organization_id (default: the officer''s home organisation). The actor must administer that organisation; the officer must belong to it or hold an active rosterable branch authorisation for it. Stamps the shift and its audit row with the operating organisation.';
REVOKE ALL ON FUNCTION "public"."create_roster_shift"(p_officer_user_id uuid, p_service_type text, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_location_id uuid, p_zone_id uuid, p_patrol_route_id uuid, p_notes text, p_publish boolean, p_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_roster_shift"(p_officer_user_id uuid, p_service_type text, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_location_id uuid, p_zone_id uuid, p_patrol_route_id uuid, p_notes text, p_publish boolean, p_organization_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_roster_shift"(p_officer_user_id uuid, p_service_type text, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_location_id uuid, p_zone_id uuid, p_patrol_route_id uuid, p_notes text, p_publish boolean, p_organization_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_roster_shift"(p_officer_user_id uuid, p_service_type text, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_location_id uuid, p_zone_id uuid, p_patrol_route_id uuid, p_notes text, p_publish boolean, p_organization_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_roster_slot"(p_client_request_id uuid, p_work_unit_id uuid, p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_publish boolean DEFAULT false, p_notes text DEFAULT NULL::text)
 RETURNS roster_slots
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_unit public.roster_work_units%rowtype;
  v_staff public.staff_profiles%rowtype;
  v_slot public.roster_slots%rowtype;
begin
  select u.* into v_unit
  from public.roster_work_units u
  where u.id = p_work_unit_id and u.active;

  if not found or not public.is_admin_for_org(v_unit.organization_id) then
    raise exception 'Active authorized work unit required';
  end if;

  if p_client_request_id is null then
    raise exception 'client_request_id is required';
  end if;
  if p_scheduled_start is null
    or p_scheduled_end is null
    or p_scheduled_start >= p_scheduled_end
    or p_scheduled_start < now() - interval '5 minutes'
    or p_scheduled_end - p_scheduled_start > interval '24 hours'
  then
    raise exception 'Slot timing is outside the accepted range';
  end if;

  select s.* into v_slot
  from public.roster_slots s
  where s.organization_id = v_unit.organization_id
    and s.client_request_id = p_client_request_id;
  if found then
    return v_slot;
  end if;

  if p_staff_id is not null then
    select sp.* into v_staff
    from public.staff_profiles sp
    where sp.id = p_staff_id and sp.work_ready;

    if not found or not (
      v_staff.organization_id = v_unit.organization_id
      or exists (
        select 1
        from public.staff_branch_authorisations sba
        where sba.user_id = v_staff.user_id
          and sba.branch_org_id = v_unit.organization_id
          and sba.status = 'active'
      )
    ) then
      raise exception 'Work-ready staff profile required';
    end if;

    if exists (
      select 1
      from public.leave_requests l
      where l.staff_id = p_staff_id
        and l.status = 'approved'
        and daterange(l.starts_on, l.ends_on, '[]')
          && daterange(p_scheduled_start::date, p_scheduled_end::date, '[]')
    ) then
      raise exception 'Staff member has approved leave';
    end if;

    if exists (
      select 1
      from public.roster_slots s
      where s.staff_id = p_staff_id
        and s.status not in ('declined', 'cancelled')
        and s.scheduled_start < p_scheduled_end
        and s.scheduled_end > p_scheduled_start
    ) then
      raise exception 'Staff member already has an overlapping roster slot';
    end if;
  end if;

  insert into public.roster_slots (
    organization_id,
    work_unit_id,
    staff_id,
    scheduled_start,
    scheduled_end,
    status,
    client_request_id,
    notes,
    created_by
  )
  values (
    v_unit.organization_id,
    v_unit.id,
    p_staff_id,
    p_scheduled_start,
    p_scheduled_end,
    case when p_publish then 'published' else 'draft' end,
    p_client_request_id,
    nullif(trim(coalesce(p_notes, '')), ''),
    v_actor
  )
  returning * into v_slot;

  insert into public.audit_log (
    organization_id,
    actor_user_id,
    action,
    target_table,
    target_id,
    metadata
  )
  values (
    v_unit.organization_id,
    v_actor,
    'roster_slot_created',
    'roster_slots',
    v_slot.id,
    jsonb_build_object(
      'work_unit_id', v_unit.id,
      'work_unit_type', v_unit.work_unit_type,
      'staff_id', p_staff_id,
      'is_open', p_staff_id is null,
      'status', v_slot.status
    )
  );

  return v_slot;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."create_roster_slot"(p_client_request_id uuid, p_work_unit_id uuid, p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_publish boolean, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_roster_slot"(p_client_request_id uuid, p_work_unit_id uuid, p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_publish boolean, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_roster_slot"(p_client_request_id uuid, p_work_unit_id uuid, p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_publish boolean, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_roster_slot"(p_client_request_id uuid, p_work_unit_id uuid, p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_publish boolean, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_roster_slot_with_break"(p_client_request_id uuid, p_work_unit_id uuid, p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_publish boolean DEFAULT false, p_notes text DEFAULT NULL::text, p_planned_break_minutes integer DEFAULT 0, p_break_unpaid boolean DEFAULT false)
 RETURNS roster_slots
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_slot public.roster_slots%rowtype;
begin
  if p_planned_break_minutes is null or p_break_unpaid is null then raise exception 'Break settings are required'; end if;
  select * into v_slot from public.create_roster_slot(p_client_request_id, p_work_unit_id, p_staff_id,
    p_scheduled_start, p_scheduled_end, false, p_notes);
  if auth.uid() is null or not public.is_admin_for_org(v_slot.organization_id)
    or not exists(select 1 from public.user_profiles where id = auth.uid() and deactivated_at is null) then
    raise exception 'Active roster administrator required' using errcode = '42501';
  end if;
  if v_slot.work_unit_id is distinct from p_work_unit_id or v_slot.staff_id is distinct from p_staff_id
    or v_slot.scheduled_start is distinct from p_scheduled_start or v_slot.scheduled_end is distinct from p_scheduled_end
    or v_slot.notes is distinct from nullif(btrim(coalesce(p_notes,'')),'') then
    raise exception 'This request already created a different roster slot';
  end if;
  if v_slot.status <> 'draft' then
    if v_slot.planned_break_minutes is distinct from p_planned_break_minutes
      or v_slot.break_unpaid is distinct from p_break_unpaid then
      raise exception 'This request already created a different break plan';
    end if;
    return v_slot;
  end if;
  select * into v_slot from public.set_roster_slot_break(v_slot.id, 'draft', p_planned_break_minutes, p_break_unpaid);
  if p_publish then
    if v_slot.staff_id is not null then
      perform public.manage_roster_slot(v_slot.id, 'draft', 'publish', null);
      select * into v_slot from public.roster_slots where id = v_slot.id;
    else
      update public.roster_slots set status = 'published' where id = v_slot.id returning * into v_slot;
      insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
      values(v_slot.organization_id,auth.uid(),'roster_slot_published','roster_slots',v_slot.id,jsonb_build_object('is_open',true));
    end if;
  end if;
  return v_slot;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."create_roster_slot_with_break"(p_client_request_id uuid, p_work_unit_id uuid, p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_publish boolean, p_notes text, p_planned_break_minutes integer, p_break_unpaid boolean) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_roster_slot_with_break"(p_client_request_id uuid, p_work_unit_id uuid, p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_publish boolean, p_notes text, p_planned_break_minutes integer, p_break_unpaid boolean) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_roster_slot_with_break"(p_client_request_id uuid, p_work_unit_id uuid, p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_publish boolean, p_notes text, p_planned_break_minutes integer, p_break_unpaid boolean) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."create_roster_work_unit"(p_name text, p_work_unit_type text, p_service_type text, p_patrol_route_id uuid DEFAULT NULL::uuid, p_service_agreement_location_id uuid DEFAULT NULL::uuid, p_service_agreement_module_id uuid DEFAULT NULL::uuid, p_workplace_id uuid DEFAULT NULL::uuid, p_team_id uuid DEFAULT NULL::uuid, p_cost_centre_id uuid DEFAULT NULL::uuid)
 RETURNS roster_work_units
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_org uuid;v_unit public.roster_work_units%rowtype;v_agreement uuid;
begin
 select up.organization_id into v_org from public.user_profiles up where up.id=v_actor and up.deactivated_at is null;if v_org is null or not public.is_admin_for_org(v_org) then raise exception 'Active roster administrator required';end if;
 if nullif(trim(coalesce(p_name,'')),'') is null or nullif(trim(coalesce(p_service_type,'')),'') is null then raise exception 'Name and service type are required';end if;
 if p_work_unit_type='patrol' then if p_patrol_route_id is null or not exists(select 1 from public.patrol_routes r where r.id=p_patrol_route_id and r.organization_id=v_org and r.is_active) then raise exception 'Active patrol route in this organization required';end if;
 elsif p_work_unit_type='static' then select sal.service_agreement_id into v_agreement from public.service_agreement_locations sal join public.service_agreements sa on sa.id=sal.service_agreement_id and sa.provider_organization_id=v_org where sal.id=p_service_agreement_location_id and sal.status='active';if v_agreement is null or not exists(select 1 from public.service_agreement_modules sam where sam.id=p_service_agreement_module_id and sam.service_agreement_id=v_agreement and sam.enabled and sam.module_key='static_guarding') then raise exception 'Active static guarding agreement location and module required';end if;
 elsif p_work_unit_type='internal' then if p_workplace_id is null or not exists(select 1 from public.organization_workplaces w where w.id=p_workplace_id and w.organization_id=v_org and w.active) then raise exception 'Active provider workplace required';end if;if p_team_id is not null and not exists(select 1 from public.teams t where t.id=p_team_id and t.organization_id=v_org and t.status='active') then raise exception 'Active team in this organization required';end if;if p_cost_centre_id is not null and not exists(select 1 from public.cost_centres c where c.id=p_cost_centre_id and c.organization_id=v_org and c.active) then raise exception 'Active cost centre in this organization required';end if;
 else raise exception 'Unsupported work unit type';end if;
 insert into public.roster_work_units(organization_id,name,work_unit_type,service_type,patrol_route_id,service_agreement_location_id,service_agreement_module_id,workplace_id,team_id,cost_centre_id,created_by)
 values(v_org,trim(p_name),p_work_unit_type,trim(p_service_type),p_patrol_route_id,p_service_agreement_location_id,p_service_agreement_module_id,p_workplace_id,p_team_id,p_cost_centre_id,v_actor) returning * into v_unit;
 insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_org,v_actor,'roster_work_unit_created','roster_work_units',v_unit.id,jsonb_build_object('work_unit_type',v_unit.work_unit_type,'service_type',v_unit.service_type));return v_unit;
end;$function$;
