CREATE OR REPLACE FUNCTION "public"."create_workshop_work_order_classified_core"(p_client_request_id uuid, p_organization_id uuid, p_kind text, p_title text, p_work_subject_code_id uuid, p_work_activity_code_id uuid, p_description text, p_client_organization_id uuid, p_service_agreement_id uuid, p_client_site_id uuid, p_asset_id uuid, p_inventory_location_id uuid, p_assigned_user_id uuid, p_scheduled_for timestamp with time zone, p_bom_template_id uuid, p_zone_id uuid)
 RETURNS workshop_work_orders
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_kind='maintenance' AND ((p_client_site_id IS NULL)=(p_zone_id IS NULL)) THEN
    RAISE EXCEPTION 'Maintenance requires exactly one contracted site or zone';
  END IF;
  RETURN public.create_workshop_work_order_classified_core_agreement_scoped(
    p_client_request_id,p_organization_id,p_kind,p_title,p_work_subject_code_id,p_work_activity_code_id,p_description,
    p_client_organization_id,p_service_agreement_id,p_client_site_id,p_asset_id,p_inventory_location_id,
    p_assigned_user_id,p_scheduled_for,p_bom_template_id,p_zone_id
  );
END;
$function$;
REVOKE ALL ON FUNCTION "public"."create_workshop_work_order_classified_core"(p_client_request_id uuid, p_organization_id uuid, p_kind text, p_title text, p_work_subject_code_id uuid, p_work_activity_code_id uuid, p_description text, p_client_organization_id uuid, p_service_agreement_id uuid, p_client_site_id uuid, p_asset_id uuid, p_inventory_location_id uuid, p_assigned_user_id uuid, p_scheduled_for timestamp with time zone, p_bom_template_id uuid, p_zone_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
