CREATE OR REPLACE FUNCTION "public"."create_workshop_work_order_classified_core_agreement_scoped"(p_client_request_id uuid, p_organization_id uuid, p_kind text, p_title text, p_work_subject_code_id uuid, p_work_activity_code_id uuid, p_description text, p_client_organization_id uuid, p_service_agreement_id uuid, p_client_site_id uuid, p_asset_id uuid, p_inventory_location_id uuid, p_assigned_user_id uuid, p_scheduled_for timestamp with time zone, p_bom_template_id uuid, p_zone_id uuid)
 RETURNS workshop_work_orders
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_tenant_import_admin(p_organization_id) THEN RAISE EXCEPTION 'Tenant Workshop administrator required'; END IF;
  IF p_kind='maintenance' THEN
    IF p_client_organization_id IS NULL OR p_service_agreement_id IS NULL THEN RAISE EXCEPTION 'Maintenance requires a client and service agreement'; END IF;
    IF NOT EXISTS(
      SELECT 1 FROM public.service_agreements agreement
      JOIN public.service_agreement_modules module ON module.service_agreement_id=agreement.id AND module.module_key='workshop' AND module.enabled
      WHERE agreement.id=p_service_agreement_id
        AND agreement.provider_organization_id=p_organization_id
        AND agreement.client_organization_id=p_client_organization_id
        AND agreement.agreement_type='operational'
        AND (agreement.starts_on IS NULL OR agreement.starts_on<=current_date)
        AND (agreement.ends_on IS NULL OR agreement.ends_on>=current_date)
    ) THEN RAISE EXCEPTION 'Active contracted Workshop module required'; END IF;
    IF (p_client_site_id IS NOT NULL OR p_zone_id IS NOT NULL) AND NOT EXISTS(
      SELECT 1 FROM public.service_agreement_locations location
      WHERE location.service_agreement_id=p_service_agreement_id AND location.status='active'
        AND ((p_client_site_id IS NOT NULL AND location.site_id=p_client_site_id) OR (p_zone_id IS NOT NULL AND location.zone_id=p_zone_id))
    ) THEN RAISE EXCEPTION 'Maintenance place is outside the service agreement'; END IF;
  END IF;
  RETURN public.create_workshop_work_order_classified_core_unchecked(
    p_client_request_id,p_organization_id,p_kind,p_title,p_work_subject_code_id,p_work_activity_code_id,p_description,
    p_client_organization_id,p_service_agreement_id,p_client_site_id,p_asset_id,p_inventory_location_id,
    p_assigned_user_id,p_scheduled_for,p_bom_template_id,p_zone_id
  );
END;
$function$;
REVOKE ALL ON FUNCTION "public"."create_workshop_work_order_classified_core_agreement_scoped"(p_client_request_id uuid, p_organization_id uuid, p_kind text, p_title text, p_work_subject_code_id uuid, p_work_activity_code_id uuid, p_description text, p_client_organization_id uuid, p_service_agreement_id uuid, p_client_site_id uuid, p_asset_id uuid, p_inventory_location_id uuid, p_assigned_user_id uuid, p_scheduled_for timestamp with time zone, p_bom_template_id uuid, p_zone_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_workshop_work_order_classified_core_agreement_scoped"(p_client_request_id uuid, p_organization_id uuid, p_kind text, p_title text, p_work_subject_code_id uuid, p_work_activity_code_id uuid, p_description text, p_client_organization_id uuid, p_service_agreement_id uuid, p_client_site_id uuid, p_asset_id uuid, p_inventory_location_id uuid, p_assigned_user_id uuid, p_scheduled_for timestamp with time zone, p_bom_template_id uuid, p_zone_id uuid) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."create_workshop_work_order_classified_core_unchecked"(p_client_request_id uuid, p_organization_id uuid, p_kind text, p_title text, p_work_subject_code_id uuid, p_work_activity_code_id uuid, p_description text, p_client_organization_id uuid, p_service_agreement_id uuid, p_client_site_id uuid, p_asset_id uuid, p_inventory_location_id uuid, p_assigned_user_id uuid, p_scheduled_for timestamp with time zone, p_bom_template_id uuid, p_zone_id uuid)
 RETURNS workshop_work_orders
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := public.workshop_actor_org(p_organization_id);
  v_order public.workshop_work_orders%rowtype;
  v_subject public.reference_codes%rowtype;
  v_activity public.reference_codes%rowtype;
  v_template_line record;
  v_cost numeric;
  v_price numeric;
  v_unit text;
  v_sequence integer;
BEGIN
  IF p_client_request_id IS NULL THEN RAISE EXCEPTION 'client_request_id is required'; END IF;
  IF p_kind NOT IN ('fabrication','maintenance') THEN RAISE EXCEPTION 'Kind must be fabrication or maintenance'; END IF;
  IF nullif(trim(coalesce(p_title,'')),'') IS NULL THEN RAISE EXCEPTION 'Give the work order a title'; END IF;
  IF p_kind='maintenance' AND p_client_organization_id IS NULL THEN RAISE EXCEPTION 'A maintenance visit needs a client organization'; END IF;
  IF p_kind='maintenance' AND p_client_site_id IS NULL AND p_zone_id IS NULL AND p_asset_id IS NULL THEN RAISE EXCEPTION 'A maintenance visit needs the place (site or zone) or the asset being maintained'; END IF;

  IF p_kind='maintenance' THEN
    SELECT * INTO v_subject FROM public.reference_codes WHERE id=p_work_subject_code_id AND organization_id=p_organization_id AND code_type='work_subject' AND is_active;
    IF NOT FOUND THEN RAISE EXCEPTION 'Choose what the maintenance work is for'; END IF;
    SELECT * INTO v_activity FROM public.reference_codes WHERE id=p_work_activity_code_id AND organization_id=p_organization_id AND code_type='work_activity' AND is_active;
    IF NOT FOUND THEN RAISE EXCEPTION 'Choose what maintenance work is being done'; END IF;
  ELSE
    p_work_subject_code_id:=NULL;
    p_work_activity_code_id:=NULL;
  END IF;

  IF p_client_site_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.client_sites site
    WHERE site.id=p_client_site_id
      AND (p_client_organization_id IS NULL OR site.client_organization_id=p_client_organization_id OR site.organization_id=p_client_organization_id)
  ) THEN RAISE EXCEPTION 'Site not found for this client'; END IF;
  IF p_zone_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.location_zones zone
    WHERE zone.id=p_zone_id AND (p_client_organization_id IS NULL OR zone.organization_id=p_client_organization_id)
  ) THEN RAISE EXCEPTION 'Zone not found for this client'; END IF;
  IF p_asset_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.assets asset
    WHERE asset.id=p_asset_id AND asset.organization_id IN (p_organization_id,p_client_organization_id)
  ) THEN RAISE EXCEPTION 'Asset not found'; END IF;
  IF p_inventory_location_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.finance_inventory_locations location
    WHERE location.id=p_inventory_location_id AND location.organization_id=p_organization_id AND location.active
  ) THEN RAISE EXCEPTION 'Stock location not found'; END IF;
  IF p_service_agreement_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.service_agreements agreement
    WHERE agreement.id=p_service_agreement_id
      AND agreement.provider_organization_id=p_organization_id
      AND (p_client_organization_id IS NULL OR agreement.client_organization_id=p_client_organization_id)
  ) THEN RAISE EXCEPTION 'Agreement not found for this provider and client'; END IF;
  IF p_bom_template_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.workshop_bom_templates template
    WHERE template.id=p_bom_template_id AND template.organization_id=p_organization_id AND template.active
  ) THEN RAISE EXCEPTION 'Template not found'; END IF;
  IF p_assigned_user_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.user_profiles profile
    WHERE profile.id=p_assigned_user_id AND profile.deactivated_at IS NULL
      AND (profile.organization_id=p_organization_id OR profile.employer_organization_id=p_organization_id)
  ) THEN RAISE EXCEPTION 'Assigned staff member is not active for this provider'; END IF;

  SELECT * INTO v_order FROM public.workshop_work_orders work_order
  WHERE work_order.organization_id=p_organization_id AND work_order.client_request_id=p_client_request_id;
  IF FOUND THEN
    IF v_order.kind IS DISTINCT FROM p_kind
      OR v_order.title IS DISTINCT FROM trim(p_title)
      OR v_order.client_organization_id IS DISTINCT FROM p_client_organization_id
      OR v_order.client_site_id IS DISTINCT FROM p_client_site_id
      OR v_order.zone_id IS DISTINCT FROM p_zone_id
      OR v_order.asset_id IS DISTINCT FROM p_asset_id
      OR v_order.work_subject_code_id IS DISTINCT FROM p_work_subject_code_id
      OR v_order.work_activity_code_id IS DISTINCT FROM p_work_activity_code_id THEN
      RAISE EXCEPTION 'client_request_id is already bound to a different work order';
    END IF;
    RETURN v_order;
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(p_organization_id::text||':workshop_order_number',0));
  SELECT count(*)+1 INTO v_sequence FROM public.workshop_work_orders WHERE organization_id=p_organization_id;
  INSERT INTO public.workshop_work_orders(
    organization_id,client_request_id,order_number,kind,title,description,
    work_subject_code_id,work_activity_code_id,client_organization_id,service_agreement_id,
    client_site_id,zone_id,asset_id,inventory_location_id,bom_template_id,
    assigned_user_id,scheduled_for,created_by,updated_by
  ) VALUES (
    p_organization_id,p_client_request_id,'WO-'||to_char(now(),'YYYYMM')||'-'||lpad(v_sequence::text,4,'0'),p_kind,trim(p_title),nullif(trim(coalesce(p_description,'')),''),
    p_work_subject_code_id,p_work_activity_code_id,p_client_organization_id,p_service_agreement_id,
    p_client_site_id,p_zone_id,p_asset_id,p_inventory_location_id,p_bom_template_id,
    p_assigned_user_id,p_scheduled_for,v_actor,v_actor
  ) RETURNING * INTO v_order;

  FOR v_template_line IN SELECT * FROM public.workshop_bom_template_lines line WHERE line.template_id=p_bom_template_id ORDER BY line.position LOOP
    v_cost:=NULL;v_price:=NULL;v_unit:=NULL;
    IF v_template_line.item_id IS NOT NULL THEN SELECT prices.unit_cost,prices.unit_price,prices.unit_of_measure INTO v_cost,v_price,v_unit FROM public.workshop_current_prices(v_template_line.item_id) prices; END IF;
    INSERT INTO public.workshop_work_order_lines(work_order_id,organization_id,line_kind,item_id,description,quantity,unit_of_measure,unit_cost,unit_price,position)
    VALUES(v_order.id,p_organization_id,v_template_line.line_kind,v_template_line.item_id,v_template_line.description,v_template_line.quantity,coalesce(v_template_line.unit_of_measure,v_unit),coalesce(v_cost,0),coalesce(v_price,0),v_template_line.position);
  END LOOP;

  INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
  VALUES(p_organization_id,v_actor,'workshop_work_order_created','workshop_work_orders',v_order.id,
    jsonb_build_object('order_number',v_order.order_number,'kind',v_order.kind,'client_organization_id',v_order.client_organization_id,'work_subject_code_id',v_order.work_subject_code_id,'work_activity_code_id',v_order.work_activity_code_id,'bom_template_id',p_bom_template_id));
  RETURN v_order;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."create_workshop_work_order_classified_core_unchecked"(p_client_request_id uuid, p_organization_id uuid, p_kind text, p_title text, p_work_subject_code_id uuid, p_work_activity_code_id uuid, p_description text, p_client_organization_id uuid, p_service_agreement_id uuid, p_client_site_id uuid, p_asset_id uuid, p_inventory_location_id uuid, p_assigned_user_id uuid, p_scheduled_for timestamp with time zone, p_bom_template_id uuid, p_zone_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_workshop_work_order_classified_core_unchecked"(p_client_request_id uuid, p_organization_id uuid, p_kind text, p_title text, p_work_subject_code_id uuid, p_work_activity_code_id uuid, p_description text, p_client_organization_id uuid, p_service_agreement_id uuid, p_client_site_id uuid, p_asset_id uuid, p_inventory_location_id uuid, p_assigned_user_id uuid, p_scheduled_for timestamp with time zone, p_bom_template_id uuid, p_zone_id uuid) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."crm_actor_can_manage_account"(p_account_organization_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists(
    select 1
    from public.user_profiles actor
    join public.organizations account on account.id=p_account_organization_id
    where actor.id=auth.uid()
      and actor.deactivated_at is null
      and (
        account.id=actor.organization_id
        or account.parent_organization_id=actor.organization_id
        or account.parent_organization_id = any(public.get_descendant_organizations(coalesce(actor.employer_organization_id,actor.organization_id)))
        or exists(
          select 1
          from public.service_agreements agreement
          where agreement.provider_organization_id = any(public.get_descendant_organizations(coalesce(actor.employer_organization_id,actor.organization_id)))
            and agreement.client_organization_id=account.id
            and agreement.agreement_type='operational'
            and (agreement.starts_on is null or agreement.starts_on<=current_date)
            and (agreement.ends_on is null or agreement.ends_on>=current_date)
            and public.is_admin_for_org(agreement.provider_organization_id)
        )
      )
  );
$function$;
REVOKE ALL ON FUNCTION "public"."crm_actor_can_manage_account"(p_account_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."crm_actor_can_manage_account"(p_account_organization_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."crm_actor_can_manage_account"(p_account_organization_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."crm_actor_can_manage_account"(p_account_organization_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."crm_actor_can_manage_location"(p_location_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.locations l
    JOIN public.user_profiles actor ON actor.id = auth.uid() AND actor.deactivated_at IS NULL
    WHERE l.id = p_location_id AND public.is_admin_for_org(actor.organization_id)
      AND (
        l.organization_id = actor.organization_id
        OR l.organization_id = ANY(public.get_descendant_organizations(coalesce(actor.employer_organization_id, actor.organization_id)))
        OR EXISTS (
          SELECT 1 FROM public.service_agreements agreement
          JOIN public.service_agreement_locations coverage ON coverage.service_agreement_id = agreement.id AND coverage.status = 'active'
          LEFT JOIN public.client_sites site ON site.id = coverage.site_id
          LEFT JOIN public.location_zones zone ON zone.id = coverage.zone_id
          WHERE ((agreement.provider_organization_id = actor.organization_id)
            OR (public.is_admin_for_org(agreement.provider_organization_id)
              AND agreement.client_organization_id = l.organization_id
              AND (agreement.starts_on IS NULL OR agreement.starts_on <= current_date)
              AND (agreement.ends_on IS NULL OR agreement.ends_on >= current_date)))
            AND agreement.agreement_type = 'operational'
            AND (site.location_id = l.id OR zone.location_id = l.id)
        )
      )
  );
$function$;
REVOKE ALL ON FUNCTION "public"."crm_actor_can_manage_location"(p_location_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."crm_actor_can_manage_location"(p_location_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."crm_actor_can_manage_location"(p_location_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."current_account_is_active"()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT NOT EXISTS (
    SELECT 1
    FROM public.user_profiles p
    WHERE p.id = (SELECT auth.uid())
      AND p.deactivated_at IS NOT NULL
  );
$function$;
COMMENT ON FUNCTION "public"."current_account_is_active"() IS 'False when the calling Auth user has a deactivated profile. Backs restrictive RLS guards so an unexpired access token cannot outlive deactivation.';
REVOKE ALL ON FUNCTION "public"."current_account_is_active"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."current_account_is_active"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."current_account_is_active"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."current_account_is_active"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."current_user_role"()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT role
  FROM public.user_profiles
  WHERE id = auth.uid()
    AND deactivated_at IS NULL
  LIMIT 1;
$function$;
COMMENT ON FUNCTION "public"."current_user_role"() IS 'Returns the role of the currently authenticated user.';
REVOKE ALL ON FUNCTION "public"."current_user_role"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."current_user_role"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."current_user_role"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."current_user_role"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."custodian_classify_evidence"(p_evidence_id uuid, p_retention_class text, p_reason text)
 RETURNS evidence_items
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_item public.evidence_items%rowtype;
  v_days integer;
  v_until timestamptz;
  v_hold boolean := false;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_retention_class NOT IN ('interaction_permanent', 'observation_30_day', 'canonical_indefinite', 'legal_hold') THEN
    RAISE EXCEPTION 'Unsupported Custodian retention class %', p_retention_class;
  END IF;
  IF nullif(trim(p_reason), '') IS NULL THEN RAISE EXCEPTION 'Custodian classification reason is required'; END IF;
  SELECT * INTO v_item FROM public.evidence_items WHERE id = p_evidence_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Evidence item not found'; END IF;
  IF NOT public.is_admin_for_org(v_item.organization_id) AND v_item.captured_by_user_id <> v_actor THEN
    RAISE EXCEPTION 'Not authorised to classify this evidence';
  END IF;
  IF p_retention_class = 'observation_30_day' THEN v_days := 30; v_until := clock_timestamp() + interval '30 days'; END IF;
  IF p_retention_class = 'legal_hold' THEN v_hold := true; END IF;
  UPDATE public.evidence_items
    SET retention_class = p_retention_class,
        retention_days = v_days,
        retention_until = v_until,
        retention_hold = v_hold,
        retention_reason = trim(p_reason)
    WHERE evidence_items.id = p_evidence_id
    RETURNING * INTO v_item;
  INSERT INTO public.custodian_actions (organization_id, actor_user_id, action, target_table, target_id, reason, metadata)
    VALUES (v_item.organization_id, v_actor, 'evidence_retention_classified', 'evidence_items', p_evidence_id, trim(p_reason), jsonb_build_object('retention_class', p_retention_class, 'retention_until', v_until, 'retention_hold', v_hold));
  RETURN v_item;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."custodian_classify_evidence"(p_evidence_id uuid, p_retention_class text, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."custodian_classify_evidence"(p_evidence_id uuid, p_retention_class text, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."custodian_classify_evidence"(p_evidence_id uuid, p_retention_class text, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."custodian_classify_evidence"(p_evidence_id uuid, p_retention_class text, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."custodian_classify_observation"(p_observation_id uuid, p_retention_class text, p_reason text)
 RETURNS observations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_item public.observations%rowtype;
  v_org uuid;
  v_until timestamptz;
  v_hold boolean := false;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_retention_class NOT IN ('interaction_permanent', 'observation_30_day', 'canonical_indefinite', 'legal_hold') THEN
    RAISE EXCEPTION 'Unsupported Custodian retention class %', p_retention_class;
  END IF;
  IF nullif(trim(p_reason), '') IS NULL THEN RAISE EXCEPTION 'Custodian classification reason is required'; END IF;
  SELECT * INTO v_item FROM public.observations WHERE id = p_observation_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Observation not found'; END IF;
  v_org := v_item.organization_id;
  IF NOT public.is_admin_for_org(v_org) THEN RAISE EXCEPTION 'Active organization administrator required'; END IF;
  IF p_retention_class = 'observation_30_day' THEN v_until := clock_timestamp() + interval '30 days'; END IF;
  IF p_retention_class = 'legal_hold' THEN v_hold := true; END IF;
  UPDATE public.observations
    SET retention_until = v_until,
        retention_reason = trim(p_reason),
        retention_hold = v_hold,
        retention_hold_days = NULL
    WHERE observations.id = p_observation_id
    RETURNING * INTO v_item;
  INSERT INTO public.custodian_actions (organization_id, actor_user_id, action, target_table, target_id, reason, metadata)
    VALUES (v_org, v_actor, 'observation_retention_classified', 'observations', p_observation_id, trim(p_reason), jsonb_build_object('retention_class', p_retention_class, 'retention_until', v_until, 'retention_hold', v_hold));
  RETURN v_item;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."custodian_classify_observation"(p_observation_id uuid, p_retention_class text, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."custodian_classify_observation"(p_observation_id uuid, p_retention_class text, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."custodian_classify_observation"(p_observation_id uuid, p_retention_class text, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."custodian_classify_observation"(p_observation_id uuid, p_retention_class text, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."custodian_manage_legal_hold"(p_action text, p_hold_id uuid DEFAULT NULL::uuid, p_hold_key text DEFAULT NULL::text, p_title text DEFAULT NULL::text, p_reason text DEFAULT NULL::text, p_scope jsonb DEFAULT '{}'::jsonb, p_release_reason text DEFAULT NULL::text)
 RETURNS custodian_legal_holds
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_hold public.custodian_legal_holds%rowtype;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT organization_id INTO v_org FROM public.user_profiles
    WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_org IS NULL OR NOT public.is_admin_for_org(v_org) THEN
    RAISE EXCEPTION 'Active organization administrator required';
  END IF;

  IF p_action = 'place' THEN
    IF nullif(trim(p_hold_key), '') IS NULL OR nullif(trim(p_title), '') IS NULL OR nullif(trim(p_reason), '') IS NULL THEN
      RAISE EXCEPTION 'hold_key, title, and reason are required';
    END IF;
    INSERT INTO public.custodian_legal_holds (
      organization_id, hold_key, title, reason, scope, placed_by
    ) VALUES (
      v_org, trim(p_hold_key), trim(p_title), trim(p_reason), coalesce(p_scope, '{}'::jsonb), v_actor
    ) RETURNING * INTO v_hold;
    UPDATE public.evidence_items e
      SET retention_hold = true, retention_class = 'legal_hold', retention_reason = trim(p_reason)
      WHERE e.organization_id = v_org
        AND (p_scope = '{}'::jsonb OR e.metadata @> coalesce(p_scope, '{}'::jsonb));
    INSERT INTO public.custodian_actions (organization_id, actor_user_id, action, target_table, target_id, reason, metadata)
      VALUES (v_org, v_actor, 'legal_hold_placed', 'custodian_legal_holds', v_hold.id, trim(p_reason), coalesce(p_scope, '{}'::jsonb));
    RETURN v_hold;
  ELSIF p_action = 'release' THEN
    IF p_hold_id IS NULL OR nullif(trim(p_release_reason), '') IS NULL THEN
      RAISE EXCEPTION 'hold_id and release_reason are required';
    END IF;
    UPDATE public.custodian_legal_holds
      SET status = 'released', released_by = v_actor, released_at = clock_timestamp(), release_reason = trim(p_release_reason), updated_at = clock_timestamp()
      WHERE id = p_hold_id AND organization_id = v_org AND status = 'active'
      RETURNING * INTO v_hold;
    IF NOT FOUND THEN RAISE EXCEPTION 'Active legal hold not found'; END IF;
    INSERT INTO public.custodian_actions (organization_id, actor_user_id, action, target_table, target_id, reason, metadata)
      VALUES (v_org, v_actor, 'legal_hold_released', 'custodian_legal_holds', v_hold.id, trim(p_release_reason), jsonb_build_object('hold_key', v_hold.hold_key));
    RETURN v_hold;
  ELSE
    RAISE EXCEPTION 'Unsupported Custodian legal hold action %', p_action;
  END IF;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."custodian_manage_legal_hold"(p_action text, p_hold_id uuid, p_hold_key text, p_title text, p_reason text, p_scope jsonb, p_release_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."custodian_manage_legal_hold"(p_action text, p_hold_id uuid, p_hold_key text, p_title text, p_reason text, p_scope jsonb, p_release_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."custodian_manage_legal_hold"(p_action text, p_hold_id uuid, p_hold_key text, p_title text, p_reason text, p_scope jsonb, p_release_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."custodian_manage_legal_hold"(p_action text, p_hold_id uuid, p_hold_key text, p_title text, p_reason text, p_scope jsonb, p_release_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."custodian_retention_candidates"(p_organization_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 500)
 RETURNS TABLE(target_table text, target_id uuid, organization_id uuid, retention_until timestamp with time zone, retention_class text, retention_reason text, blocked_by_hold boolean)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT 'observations'::text, o.id, o.organization_id, o.retention_until,
    CASE WHEN o.retention_hold THEN 'legal_hold' ELSE 'observation_30_day' END,
    o.retention_reason, o.retention_hold
  FROM public.observations o
  WHERE (p_organization_id IS NULL OR o.organization_id = p_organization_id)
    AND o.retention_until IS NOT NULL
    AND o.retention_until <= clock_timestamp()
  ORDER BY o.retention_until ASC
  LIMIT greatest(1, least(coalesce(p_limit, 500), 5000));
$function$;
REVOKE ALL ON FUNCTION "public"."custodian_retention_candidates"(p_organization_id uuid, p_limit integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."custodian_retention_candidates"(p_organization_id uuid, p_limit integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."custodian_retention_candidates"(p_organization_id uuid, p_limit integer) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."custodian_retention_candidates"(p_organization_id uuid, p_limit integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."custom_report_source_snapshot"(p_provider_organization_id uuid, p_service_agreement_id uuid, p_start_ts timestamp with time zone, p_end_ts timestamp with time zone, p_site_ids uuid[], p_zone_ids uuid[], p_person_ids uuid[], p_vehicle_ids uuid[], p_has_entity_scope boolean, p_sections text[])
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
with scoped_observations as not materialized (
  select observation.id,
    observation.observed_at,
    observation.site_id,
    site.name as site_name,
    observation.zone_id,
    zone.name as zone_name,
    observation.canonical_person_id,
    coalesce(person.display_name, 'Unnamed person') as person_name,
    observation.canonical_vehicle_id,
    vehicle.plate_number as vehicle_plate,
    observation.plate_number,
    observation.module_key,
    observation.is_compliant,
    observation.compliance_reason
  from public.observations observation
  left join public.client_sites site on site.id = observation.site_id
  left join public.location_zones zone on zone.id = observation.zone_id
  left join public.canonical_person_public person on person.id = observation.canonical_person_id
  left join public.canonical_vehicle_public vehicle on vehicle.id = observation.canonical_vehicle_id
  where ('summary' = any(p_sections) or 'observations' = any(p_sections) or 'breaches' = any(p_sections))
    and observation.organization_id = p_provider_organization_id
    and observation.observed_at >= p_start_ts
    and observation.observed_at < p_end_ts
    and exists (
      select 1 from public.service_agreement_locations link
      where link.service_agreement_id = p_service_agreement_id
        and link.status = 'active'
        and (
          (link.site_id is not null and link.site_id = observation.site_id)
          or (link.zone_id is not null and link.zone_id = observation.zone_id)
        )
    )
    and (
      cardinality(p_site_ids) + cardinality(p_zone_ids) = 0
      or observation.site_id = any(p_site_ids)
      or observation.zone_id = any(p_zone_ids)
    )
    and (cardinality(p_person_ids) = 0 or observation.canonical_person_id = any(p_person_ids))
    and (cardinality(p_vehicle_ids) = 0 or observation.canonical_vehicle_id = any(p_vehicle_ids))
), limited_observations as materialized (
  select * from scoped_observations
  order by observed_at, id
  limit 1001
), scoped_breaches as not materialized (
  select alert.id,
    alert.observation_id,
    alert.created_at,
    observation.site_id,
    observation.site_name,
    observation.zone_id,
    observation.zone_name,
    alert.plate_number,
    alert.breach_type,
    alert.status
  from public.breach_alerts alert
  join scoped_observations observation on observation.id = alert.observation_id
  where ('summary' = any(p_sections) or 'breaches' = any(p_sections))
    and alert.organization_id = p_provider_organization_id
), limited_breaches as materialized (
  select * from scoped_breaches
  order by created_at, id
  limit 1001
), scoped_incidents as not materialized (
  select incident.id,
    incident.occurred_at,
    incident.client_site_id as site_id,
    site.name as site_name,
    incident.zone_id,
    zone.name as zone_name,
    incident.incident_type,
    incident.severity,
    incident.status
  from public.incidents incident
  left join public.client_sites site on site.id = incident.client_site_id
  left join public.location_zones zone on zone.id = incident.zone_id
  where ('summary' = any(p_sections) or 'incidents' = any(p_sections))
    and not p_has_entity_scope
    and incident.organization_id = p_provider_organization_id
    and incident.occurred_at >= p_start_ts
    and incident.occurred_at < p_end_ts
    and exists (
      select 1 from public.service_agreement_locations link
      where link.service_agreement_id = p_service_agreement_id
        and link.status = 'active'
        and (
          (link.site_id is not null and link.site_id = incident.client_site_id)
          or (link.zone_id is not null and link.zone_id = incident.zone_id)
        )
    )
    and (
      cardinality(p_site_ids) + cardinality(p_zone_ids) = 0
      or incident.client_site_id = any(p_site_ids)
      or incident.zone_id = any(p_zone_ids)
    )
), limited_incidents as materialized (
  select * from scoped_incidents
  order by occurred_at, id
  limit 1001
), scoped_checkpoints as not materialized (
  select visit.id,
    visit.visited_at,
    visit.checkpoint_id,
    visit.route_checkpoint_id,
    case when visit.route_checkpoint_id is not null then 'route' else 'legacy' end as checkpoint_kind,
    coalesce(route_checkpoint.name, checkpoint.name) as checkpoint_name,
    coalesce(route.site_id, checkpoint.client_site_id) as site_id,
    site.name as site_name,
    checkpoint.zone_id,
    zone.name as zone_name,
    visit.within_radius,
    visit.scan_method
  from public.patrol_checkpoint_visits visit
  left join public.patrol_checkpoints checkpoint
    on checkpoint.id = visit.checkpoint_id
   and checkpoint.organization_id = p_provider_organization_id
  left join public.patrol_route_checkpoints route_checkpoint
    on route_checkpoint.id = visit.route_checkpoint_id
  left join public.patrol_routes route
    on route.id = route_checkpoint.patrol_route_id
   and route.organization_id = p_provider_organization_id
  left join public.client_sites site
    on site.id = coalesce(route.site_id, checkpoint.client_site_id)
  left join public.location_zones zone on zone.id = checkpoint.zone_id
  where ('summary' = any(p_sections) or 'checkpoint_visits' = any(p_sections))
    and not p_has_entity_scope
    and visit.organization_id = p_provider_organization_id
    and visit.visited_at >= p_start_ts
    and visit.visited_at < p_end_ts
    and (
      (visit.checkpoint_id is not null and checkpoint.id is not null)
      or (visit.route_checkpoint_id is not null and route_checkpoint.id is not null and route.id is not null)
    )
    and exists (
      select 1 from public.service_agreement_locations link
      where link.service_agreement_id = p_service_agreement_id
        and link.status = 'active'
        and (
          (link.site_id is not null and link.site_id = coalesce(route.site_id, checkpoint.client_site_id))
          or (link.zone_id is not null and link.zone_id = checkpoint.zone_id)
        )
    )
    and (
      cardinality(p_site_ids) + cardinality(p_zone_ids) = 0
      or coalesce(route.site_id, checkpoint.client_site_id) = any(p_site_ids)
      or checkpoint.zone_id = any(p_zone_ids)
    )
), limited_checkpoints as materialized (
  select * from scoped_checkpoints
  order by visited_at, id
  limit 1001
)
select jsonb_build_object(
  'observation_count', (select count(*) from scoped_observations),
  'compliant_count', (select count(*) from scoped_observations where is_compliant is true),
  'non_compliant_count', (select count(*) from scoped_observations where is_compliant is false),
  'breach_count', (select count(*) from scoped_breaches),
  'incident_count', (select count(*) from scoped_incidents),
  'checkpoint_count', (select count(*) from scoped_checkpoints),
  'observations', case when 'observations' = any(p_sections) then coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', observation.id,
      'observed_at', observation.observed_at,
      'site_id', observation.site_id,
      'site_name', observation.site_name,
      'zone_id', observation.zone_id,
      'zone_name', observation.zone_name,
      'canonical_person_id', observation.canonical_person_id,
      'person_name', observation.person_name,
      'canonical_vehicle_id', observation.canonical_vehicle_id,
      'vehicle_plate', observation.vehicle_plate,
      'plate_number', observation.plate_number,
      'module_key', observation.module_key,
      'is_compliant', observation.is_compliant,
      'compliance_reason', observation.compliance_reason
    ) order by observation.observed_at, observation.id)
    from limited_observations observation
  ), '[]'::jsonb) else '[]'::jsonb end,
  'breaches', case when 'breaches' = any(p_sections) then coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', alert.id,
      'observation_id', alert.observation_id,
      'created_at', alert.created_at,
      'site_id', alert.site_id,
      'site_name', alert.site_name,
      'zone_id', alert.zone_id,
      'zone_name', alert.zone_name,
      'plate_number', alert.plate_number,
      'breach_type', alert.breach_type,
      'status', alert.status
    ) order by alert.created_at, alert.id)
    from limited_breaches alert
  ), '[]'::jsonb) else '[]'::jsonb end,
  'incidents', case when 'incidents' = any(p_sections) then coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', incident.id,
      'occurred_at', incident.occurred_at,
      'site_id', incident.site_id,
      'site_name', incident.site_name,
      'zone_id', incident.zone_id,
      'zone_name', incident.zone_name,
      'incident_type', incident.incident_type,
      'severity', incident.severity,
      'status', incident.status
    ) order by incident.occurred_at, incident.id)
    from limited_incidents incident
  ), '[]'::jsonb) else '[]'::jsonb end,
  'checkpoint_visits', case when 'checkpoint_visits' = any(p_sections) then coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', visit.id,
      'visited_at', visit.visited_at,
      'checkpoint_id', visit.checkpoint_id,
      'route_checkpoint_id', visit.route_checkpoint_id,
      'checkpoint_kind', visit.checkpoint_kind,
      'checkpoint_name', visit.checkpoint_name,
      'site_id', visit.site_id,
      'site_name', visit.site_name,
      'zone_id', visit.zone_id,
      'zone_name', visit.zone_name,
      'within_radius', visit.within_radius,
      'scan_method', visit.scan_method
    ) order by visit.visited_at, visit.id)
    from limited_checkpoints visit
  ), '[]'::jsonb) else '[]'::jsonb end,
  'scope_labels', jsonb_build_object(
    'sites', coalesce((
      select jsonb_agg(jsonb_build_object('id', site.id, 'name', site.name, 'address', site.address) order by site.name, site.id)
      from public.client_sites site where site.id = any(p_site_ids)
    ), '[]'::jsonb),
    'zones', coalesce((
      select jsonb_agg(jsonb_build_object('id', zone.id, 'name', zone.name, 'zone_type', zone.zone_type) order by zone.name, zone.id)
      from public.location_zones zone where zone.id = any(p_zone_ids)
    ), '[]'::jsonb),
    'people', coalesce((
      select jsonb_agg(jsonb_build_object('id', person.id, 'name', coalesce(person.display_name, 'Unnamed person')) order by person.display_name, person.id)
      from public.canonical_person_public person where person.id = any(p_person_ids)
    ), '[]'::jsonb),
    'vehicles', coalesce((
      select jsonb_agg(jsonb_build_object('id', vehicle.id, 'plate', vehicle.plate_number, 'make', vehicle.make, 'model', vehicle.model) order by vehicle.plate_number, vehicle.id)
      from public.canonical_vehicle_public vehicle where vehicle.id = any(p_vehicle_ids)
    ), '[]'::jsonb)
  )
);
$function$;
REVOKE ALL ON FUNCTION "public"."custom_report_source_snapshot"(p_provider_organization_id uuid, p_service_agreement_id uuid, p_start_ts timestamp with time zone, p_end_ts timestamp with time zone, p_site_ids uuid[], p_zone_ids uuid[], p_person_ids uuid[], p_vehicle_ids uuid[], p_has_entity_scope boolean, p_sections text[]) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."custom_report_source_snapshot"(p_provider_organization_id uuid, p_service_agreement_id uuid, p_start_ts timestamp with time zone, p_end_ts timestamp with time zone, p_site_ids uuid[], p_zone_ids uuid[], p_person_ids uuid[], p_vehicle_ids uuid[], p_has_entity_scope boolean, p_sections text[]) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."defer_cctv_inference_job"(p_job_id uuid, p_lease_token uuid, p_reason text, p_not_before_seconds integer DEFAULT 900)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org uuid;
BEGIN
  IF auth.role() <> 'service_role' AND session_user NOT IN ('postgres', 'supabase_admin') THEN RAISE EXCEPTION 'Service identity required'; END IF;
  IF p_not_before_seconds NOT BETWEEN 60 AND 86400 THEN RAISE EXCEPTION 'Deferral must be between one minute and one day'; END IF;
  UPDATE public.inference_jobs j
     SET status = 'queued', stage = 'deferred', lease_token = NULL, heartbeat_at = NULL,
         lease_expires_at = clock_timestamp() + make_interval(secs => p_not_before_seconds),
         attempt_count = greatest(0, j.attempt_count - 1),
         progress_label = left(coalesce(nullif(trim(p_reason), ''), 'Deferred'), 200)
   WHERE j.id = p_job_id AND j.status = 'processing' AND j.lease_token = p_lease_token
   RETURNING j.organization_id INTO v_org;
  IF v_org IS NULL THEN RETURN false; END IF;
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_org, NULL, 'cctv_inference_job_deferred', 'inference_jobs', p_job_id, jsonb_build_object('reason', p_reason, 'not_before_seconds', p_not_before_seconds));
  RETURN true;
END $function$;
REVOKE ALL ON FUNCTION "public"."defer_cctv_inference_job"(p_job_id uuid, p_lease_token uuid, p_reason text, p_not_before_seconds integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."defer_cctv_inference_job"(p_job_id uuid, p_lease_token uuid, p_reason text, p_not_before_seconds integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."defer_cctv_inference_job"(p_job_id uuid, p_lease_token uuid, p_reason text, p_not_before_seconds integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."depart_dispatch_place"(p_client_request_id uuid, p_stop_id uuid, p_officer_notes text DEFAULT NULL::text, p_gps_lat double precision DEFAULT NULL::double precision, p_gps_lng double precision DEFAULT NULL::double precision, p_sla_delay_reason text DEFAULT NULL::text)
 RETURNS TABLE(stop_id uuid, departed_at timestamp with time zone, sla_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_org uuid;
  v_stop public.shift_stops%rowtype;
  v_job public.dispatch_jobs%rowtype;
  v_receipt public.officer_command_requests%rowtype;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_client_request_id IS NULL THEN RAISE EXCEPTION 'client_request_id is required'; END IF;
  SELECT p.organization_id INTO v_org FROM public.user_profiles p WHERE p.id = v_user AND p.deactivated_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'Active profile required'; END IF;

  SELECT * INTO v_receipt FROM public.officer_command_requests r WHERE r.request_id = p_client_request_id::text;
  IF FOUND AND v_receipt.actor_user_id IS DISTINCT FROM v_user THEN RAISE EXCEPTION 'client_request_id belongs to another actor'; END IF;
  IF FOUND AND v_receipt.command_status = 'completed' THEN
    RETURN QUERY SELECT (v_receipt.response->>'stop_id')::uuid, (v_receipt.response->>'departed_at')::timestamptz, v_receipt.response->>'sla_status';
    RETURN;
  END IF;

  SELECT * INTO v_stop FROM public.shift_stops st WHERE st.id = p_stop_id AND st.organization_id = v_org;
  IF NOT FOUND THEN RAISE EXCEPTION 'Stop not found in the officer organisation'; END IF;
  IF v_stop.dispatch_job_id IS NOT NULL THEN SELECT * INTO v_job FROM public.dispatch_jobs d WHERE d.id = v_stop.dispatch_job_id; END IF;
  IF NOT (public.is_admin_for_org(v_org)
      OR EXISTS (SELECT 1 FROM public.shifts s WHERE s.id = v_stop.shift_id AND s.officer_user_id = v_user)
      OR (v_job.id IS NOT NULL AND (v_job.assigned_officer_id = v_user
          OR EXISTS (SELECT 1 FROM public.dispatch_resources dr WHERE dr.id = v_job.dispatch_resource_id AND dr.assigned_officer_id = v_user)))) THEN
    RAISE EXCEPTION 'Only the attending officer may record departure for this stop';
  END IF;
  IF v_stop.actual_arrived_at IS NULL THEN RAISE EXCEPTION 'Arrival must be recorded before departure'; END IF;

  -- The contract requires every material delay to be explained in the report.
  IF v_stop.place_role = 'work_place' AND v_job.id IS NOT NULL AND v_job.sla_respond_by IS NOT NULL
     AND v_stop.actual_arrived_at > v_job.sla_respond_by
     AND nullif(trim(coalesce(p_sla_delay_reason, v_job.sla_delay_reason, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Arrival breached the response SLA; a delay reason is required before departure';
  END IF;

  UPDATE public.shift_stops
  SET status = 'completed',
      actual_departed_at = COALESCE(shift_stops.actual_departed_at, now()),
      departed_gps_lat = COALESCE(p_gps_lat, shift_stops.departed_gps_lat),
      departed_gps_lng = COALESCE(p_gps_lng, shift_stops.departed_gps_lng),
      officer_notes = COALESCE(nullif(trim(coalesce(p_officer_notes, '')), ''), shift_stops.officer_notes),
      sla_status = CASE WHEN shift_stops.actual_arrived_at > shift_stops.sla_arrive_by THEN 'breached' ELSE 'completed' END,
      updated_at = now()
  WHERE id = v_stop.id
  RETURNING * INTO v_stop;

  IF v_job.id IS NOT NULL AND nullif(trim(coalesce(p_sla_delay_reason, '')), '') IS NOT NULL THEN
    UPDATE public.dispatch_jobs SET sla_delay_reason = trim(p_sla_delay_reason) WHERE id = v_job.id;
  END IF;

  INSERT INTO public.officer_command_requests (request_id, organization_id, actor_user_id, shift_id, site_id, command_type, command_status, response)
  VALUES (p_client_request_id::text, v_org, v_user, v_stop.shift_id, v_stop.site_id, 'depart_dispatch_place', 'completed',
    jsonb_build_object('stop_id', v_stop.id, 'departed_at', v_stop.actual_departed_at, 'sla_status', v_stop.sla_status))
  ON CONFLICT (request_id) DO UPDATE SET command_status = 'completed', response = EXCLUDED.response;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_org, v_user, 'dispatch_place_departure_recorded', 'shift_stops', v_stop.id,
    jsonb_build_object('dispatch_job_id', v_stop.dispatch_job_id, 'place_role', v_stop.place_role, 'sla_status', v_stop.sla_status,
      'delay_reason_recorded', nullif(trim(coalesce(p_sla_delay_reason, '')), '') IS NOT NULL));

  RETURN QUERY SELECT v_stop.id, v_stop.actual_departed_at, v_stop.sla_status;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."depart_dispatch_place"(p_client_request_id uuid, p_stop_id uuid, p_officer_notes text, p_gps_lat double precision, p_gps_lng double precision, p_sla_delay_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."depart_dispatch_place"(p_client_request_id uuid, p_stop_id uuid, p_officer_notes text, p_gps_lat double precision, p_gps_lng double precision, p_sla_delay_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."depart_dispatch_place"(p_client_request_id uuid, p_stop_id uuid, p_officer_notes text, p_gps_lat double precision, p_gps_lng double precision, p_sla_delay_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."depart_dispatch_place"(p_client_request_id uuid, p_stop_id uuid, p_officer_notes text, p_gps_lat double precision, p_gps_lng double precision, p_sla_delay_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."desktop_signing_material"()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'vault'
AS $function$
DECLARE v_pfx text; v_pw text;
BEGIN
  IF auth.role() <> 'service_role' AND session_user NOT IN ('postgres', 'supabase_admin') THEN RAISE EXCEPTION 'Service identity required'; END IF;
  SELECT decrypted_secret INTO v_pfx FROM vault.decrypted_secrets WHERE name = 'desktop_signing_pfx_base64' LIMIT 1;
  SELECT decrypted_secret INTO v_pw FROM vault.decrypted_secrets WHERE name = 'desktop_signing_pfx_password' LIMIT 1;
  IF v_pfx IS NULL OR v_pw IS NULL THEN
    RAISE EXCEPTION 'Desktop signing material is not in Vault. Add desktop_signing_pfx_base64 and desktop_signing_pfx_password (Dashboard → Vault) or call set_desktop_signing_material.';
  END IF;
  -- Every read is on the record: who (session/service), when, what names. Never the values.
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (NULL, auth.uid(), 'desktop_signing_material_read', 'vault.secrets', NULL,
          jsonb_build_object('names', jsonb_build_array('desktop_signing_pfx_base64', 'desktop_signing_pfx_password'), 'session_user', session_user, 'read_at', clock_timestamp()));
  RETURN jsonb_build_object('pfx_base64', v_pfx, 'pfx_password', v_pw);
END $function$;
COMMENT ON FUNCTION "public"."desktop_signing_material"() IS 'Service-only: returns the FCM Desktop code-signing PFX (base64) and password from Vault for the protected-side signing step. Every read is audited by name.';
REVOKE ALL ON FUNCTION "public"."desktop_signing_material"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."desktop_signing_material"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."desktop_signing_material"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."dev_work_requests_set_updated_at"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at := now();
  return new;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."dev_work_requests_set_updated_at"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."dev_work_requests_set_updated_at"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."dev_work_requests_set_updated_at"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."dev_work_requests_set_updated_at"() TO "anon";
GRANT EXECUTE ON FUNCTION "public"."dev_work_requests_set_updated_at"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."dev_work_requests_set_updated_at"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."dispatch_job_create_sla_clock"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_agreement_id uuid;
  v_obligation_id uuid;
begin
  -- Only meter jobs that carry an SLA target.
  if new.sla_minutes is null then
    return new;
  end if;

  -- Resolve the service agreement for the job's site (best effort).
  if new.client_site_id is not null then
    select sfc.service_agreement_id
      into v_agreement_id
    from site_financial_config sfc
    where sfc.site_id = new.client_site_id
      and sfc.service_agreement_id is not null
    order by sfc.active desc nulls last, sfc.created_at desc
    limit 1;
  end if;

  -- Resolve the governing response_time obligation for that agreement.
  if v_agreement_id is not null then
    select ao.id
      into v_obligation_id
    from agreement_obligations ao
    where ao.service_agreement_id = v_agreement_id
      and ao.obligation_type = 'response_time'
      and ao.active = true
    order by ao.created_at
    limit 1;
  end if;

  insert into sla_clocks (
    organization_id, service_agreement_id, obligation_id,
    dispatch_job_id, site_id, started_at, target_minutes, status
  ) values (
    new.organization_id, v_agreement_id, v_obligation_id,
    new.id, new.client_site_id, coalesce(new.created_at, now()),
    new.sla_minutes, 'running'
  );

  return new;
end;
$function$;
COMMENT ON FUNCTION "public"."dispatch_job_create_sla_clock"() IS 'AFTER INSERT on dispatch_jobs: creates a running sla_clocks row when sla_minutes is set, resolving the response_time obligation via site -> agreement (best effort).';
REVOKE ALL ON FUNCTION "public"."dispatch_job_create_sla_clock"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."dispatch_job_create_sla_clock"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."dispatch_job_create_sla_clock"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."dispatch_job_create_sla_clock"() TO "anon";
GRANT EXECUTE ON FUNCTION "public"."dispatch_job_create_sla_clock"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."dispatch_job_create_sla_clock"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."dispatch_job_over_standing_authority"(p_job_id uuid, p_limit numeric)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT p_limit IS NOT NULL
    AND coalesce((SELECT sum(l.line_total) FROM public.dispatch_job_charge_lines l WHERE l.source_dispatch_id = p_job_id), 0) > p_limit;
$function$;
COMMENT ON FUNCTION "public"."dispatch_job_over_standing_authority"(p_job_id uuid, p_limit numeric) IS 'Internal: true when all charge lines of the dispatch job (invoiced or not, so a job cannot be split under the limit) total more than the standing authority limit. False when the limit is NULL.';
REVOKE ALL ON FUNCTION "public"."dispatch_job_over_standing_authority"(p_job_id uuid, p_limit numeric) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."dispatch_job_over_standing_authority"(p_job_id uuid, p_limit numeric) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."end_branch_area_grant"(p_grant_id uuid, p_expected_updated_at timestamp with time zone, p_reason text)
 RETURNS staff_area_grants
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid := auth.uid(); v_grant public.staff_area_grants%rowtype; v_reason text := nullif(trim(coalesce(p_reason,'')), '');
begin
  if v_reason is null then raise exception 'A change reason is required'; end if;
  select * into v_grant from public.staff_area_grants where id = p_grant_id for update;
  if not found or v_grant.status <> 'active' then raise exception 'Active direct area grant not found'; end if;
  if not public.user_can_operate_organization(v_grant.scope_org_id) or not public.staff_branch_authorisation_manager_can_manage(v_actor, v_grant.scope_org_id, v_grant.user_id) then raise exception 'Not authorised to end this branch area grant'; end if;
  if p_expected_updated_at is not null and v_grant.updated_at <> p_expected_updated_at then raise exception 'Direct area grant changed since it was opened'; end if;
  update public.staff_area_grants set status = 'ended', updated_at = clock_timestamp() where id = v_grant.id returning * into v_grant;
  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata) values(v_grant.scope_org_id, v_actor, 'branch_area_grant_ended', 'staff_area_grants', v_grant.id, jsonb_build_object('user_id',v_grant.user_id,'area',v_grant.area,'level',v_grant.level,'reason',v_reason));
  return v_grant;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."end_branch_area_grant"(p_grant_id uuid, p_expected_updated_at timestamp with time zone, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."end_branch_area_grant"(p_grant_id uuid, p_expected_updated_at timestamp with time zone, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."end_branch_area_grant"(p_grant_id uuid, p_expected_updated_at timestamp with time zone, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."end_branch_area_grant"(p_grant_id uuid, p_expected_updated_at timestamp with time zone, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."end_service_agreement"(p_agreement_id uuid, p_ends_on date, p_reason text)
 RETURNS service_agreements
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_before public.service_agreements%rowtype;
  v_after public.service_agreements%rowtype;
begin
  select * into v_before from public.service_agreements a where a.id = p_agreement_id for update;
  if not found or not public.is_admin_for_org(v_before.provider_organization_id) then raise exception 'Service agreement not found or access denied'; end if;
  if p_ends_on is null then raise exception 'Give the date the agreement ends'; end if;
  -- ends_on is the last day in force; the day before it started means it never took effect (cancelled)
  if v_before.starts_on is not null and p_ends_on < v_before.starts_on - 1 then raise exception 'The agreement cannot end before it started (%). To cancel one that never took effect, end it the day before it started.', to_char(v_before.starts_on, 'DD Mon YYYY'); end if;
  if char_length(trim(coalesce(p_reason, ''))) not between 3 and 500 then raise exception 'Say why the agreement is ending (3 to 500 characters)'; end if;
  update public.service_agreements a set ends_on = p_ends_on where a.id = v_before.id returning * into v_after;
  insert into public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (v_before.provider_organization_id, v_actor, 'service_agreement_ended', 'service_agreements', v_before.id,
    jsonb_build_object('client_organization_id', v_before.client_organization_id, 'agreement_name', v_before.name, 'reason', trim(p_reason),
      'ends_on', p_ends_on, 'before', jsonb_build_object('ends_on', v_before.ends_on), 'after', jsonb_build_object('ends_on', v_after.ends_on)));
  return v_after;
end;
$function$;
COMMENT ON FUNCTION "public"."end_service_agreement"(p_agreement_id uuid, p_ends_on date, p_reason text) IS 'Provider administrator ends (or re-dates the end of) a service agreement; reason required; audited service_agreement_ended with before/after ends_on. Live-agreement predicates read ends_on.';
REVOKE ALL ON FUNCTION "public"."end_service_agreement"(p_agreement_id uuid, p_ends_on date, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."end_service_agreement"(p_agreement_id uuid, p_ends_on date, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."end_service_agreement"(p_agreement_id uuid, p_ends_on date, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."end_service_agreement"(p_agreement_id uuid, p_ends_on date, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."end_shift_break"(p_break_id uuid, p_notes text DEFAULT NULL::text)
 RETURNS shift_breaks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_break public.shift_breaks%rowtype;
begin
  select b.* into v_break from public.shift_breaks b where b.id = p_break_id for update;
  if not found then
    raise exception 'Break not found';
  end if;

  if v_break.officer_user_id <> v_actor then
    raise exception 'Only the officer who started this break can end it';
  end if;

  if v_break.ended_at is not null then
    return v_break;
  end if;

  update public.shift_breaks
  set ended_at = now(), notes = nullif(trim(coalesce(p_notes, '')), '')
  where id = v_break.id
  returning * into v_break;

  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (
    v_break.organization_id, v_actor, 'shift_break_ended', 'shift_breaks', v_break.id,
    jsonb_build_object(
      'shift_id', v_break.shift_id,
      'break_type', v_break.break_type,
      'duration_minutes', round(extract(epoch from (v_break.ended_at - v_break.started_at)) / 60.0)
    )
  );

  return v_break;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."end_shift_break"(p_break_id uuid, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."end_shift_break"(p_break_id uuid, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."end_shift_break"(p_break_id uuid, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."end_shift_break"(p_break_id uuid, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."end_vehicle_owner_link"(p_link_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_link public.entity_links%rowtype;
BEGIN
  SELECT * INTO v_link FROM public.entity_links
  WHERE id = p_link_id AND relationship IN ('owner', 'registered_owner', 'driver', 'associated_person') FOR UPDATE;
  IF v_link.id IS NULL OR auth.uid() IS NULL
     OR NOT public.can_access_vehicle_owner_identity(v_link.organization_id, true) THEN
    RAISE EXCEPTION 'Vehicle owner identity access required';
  END IF;
  IF coalesce(trim(p_reason), '') = '' THEN RAISE EXCEPTION 'A reason is required for the identity audit trail'; END IF;
  IF NOT v_link.active THEN RETURN; END IF;
  UPDATE public.entity_links SET active = false, ends_at = clock_timestamp(), updated_at = clock_timestamp() WHERE id = p_link_id;
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_link.organization_id, auth.uid(),
    CASE WHEN v_link.relationship IN ('owner', 'registered_owner') THEN 'vehicle_owner_ended' ELSE 'vehicle_person_ended' END,
    'entity_links', p_link_id,
    jsonb_build_object('canonical_vehicle_id', v_link.to_id, 'relationship', v_link.relationship, 'reason', trim(p_reason)));
END;
$function$;
COMMENT ON FUNCTION "public"."end_vehicle_owner_link"(p_link_id uuid, p_reason text) IS 'Ends an owner, driver or associated-person link on a vehicle with a reason (authorised users). Audited.';
REVOKE ALL ON FUNCTION "public"."end_vehicle_owner_link"(p_link_id uuid, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."end_vehicle_owner_link"(p_link_id uuid, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."end_vehicle_owner_link"(p_link_id uuid, p_reason text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."enforce_import_value_rule_catalog_scope"()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_code public.reference_codes%rowtype;
BEGIN
  SELECT * INTO v_code FROM public.reference_codes WHERE id = NEW.target_code_id;
  IF NOT FOUND OR v_code.organization_id <> NEW.organization_id
     OR v_code.code_type NOT IN ('work_subject', 'work_activity', 'biosecurity_species', 'equipment_type', 'material_type') THEN
    RAISE EXCEPTION 'Classification rule target must be an organization work subject, work activity, biosecurity species, equipment type, or material type code';
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."enforce_import_value_rule_catalog_scope"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."enforce_import_value_rule_catalog_scope"() TO "postgres";

CREATE OR REPLACE FUNCTION "public"."enforce_nzta_grant_readiness"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_ready jsonb;
  v_unready integer;
BEGIN
  IF TG_TABLE_NAME = 'staff_area_grants' THEN
    IF NEW.area <> 'vehicle_owner_identity' OR NEW.status <> 'active' THEN RETURN NEW; END IF;
    IF TG_OP = 'UPDATE' AND OLD.status = 'active' AND OLD.area = NEW.area
       AND OLD.user_id = NEW.user_id AND OLD.scope_org_id = NEW.scope_org_id THEN
      RETURN NEW;
    END IF;
    v_ready := public.nzta_access_readiness(NEW.user_id, NEW.scope_org_id);
  ELSIF TG_TABLE_NAME = 'preset_assignments' THEN
    IF NEW.status <> 'active' THEN RETURN NEW; END IF;
    IF TG_OP = 'UPDATE' AND OLD.status = 'active' AND OLD.preset_id = NEW.preset_id
       AND OLD.user_id = NEW.user_id AND OLD.scope_org_id = NEW.scope_org_id THEN
      RETURN NEW;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.access_presets preset
                   WHERE preset.id = NEW.preset_id AND preset.grants ? 'vehicle_owner_identity') THEN
      RETURN NEW;
    END IF;
    v_ready := public.nzta_access_readiness(NEW.user_id, NEW.scope_org_id);
  ELSE
    IF TG_OP <> 'UPDATE' OR NOT (NEW.grants ? 'vehicle_owner_identity')
       OR (OLD.grants ? 'vehicle_owner_identity') THEN
      RETURN NEW;
    END IF;
    SELECT count(*) INTO v_unready
    FROM public.preset_assignments assignment
    CROSS JOIN LATERAL public.nzta_access_readiness(assignment.user_id, assignment.scope_org_id) readiness
    WHERE assignment.preset_id = NEW.id AND assignment.status = 'active'
      AND NOT ((readiness->>'training_current')::boolean AND (readiness->>'confidentiality_current')::boolean);
    IF v_unready > 0 THEN
      RAISE EXCEPTION '% people assigned this preset have no current NZTA register training and confidentiality acceptance. Record both before adding NZTA register access to the preset.', v_unready
        USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
  END IF;
  IF NOT ((v_ready->>'training_current')::boolean AND (v_ready->>'confidentiality_current')::boolean) THEN
    RAISE EXCEPTION 'Record current NZTA register training and confidentiality acceptance before granting access'
      USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."enforce_nzta_grant_readiness"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."enforce_nzta_grant_readiness"() TO "postgres";

CREATE OR REPLACE FUNCTION "public"."enforce_roster_slot_availability"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_fatigue text;
begin
  if current_setting('fcm.historical_labour_import', true) = 'on'
     and new.status = 'completed'
     and new.scheduled_end <= now()
     and new.external_refs->>'source' = 'rm_patrol_log_labour' then
    return new;
  end if;
  if new.staff_id is not null and new.status not in ('declined', 'cancelled') then
    if public.staff_has_roster_availability_conflict(new.staff_id, new.scheduled_start, new.scheduled_end) then
      raise exception 'Staff member is unavailable during this roster slot';
    end if;
    v_fatigue := public.staff_fatigue_conflict(new.staff_id, new.scheduled_start, new.scheduled_end, new.id);
    if v_fatigue is not null then
      raise exception 'Fatigue rule breach: %', v_fatigue;
    end if;
  end if;
  return new;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."enforce_roster_slot_availability"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."enforce_roster_slot_availability"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."enforce_roster_slot_availability"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."enforce_workshop_roster_order"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_unit public.roster_work_units%rowtype;
BEGIN
  SELECT * INTO v_unit FROM public.roster_work_units WHERE id = NEW.work_unit_id;
  IF v_unit.work_unit_type = 'workshop' AND NEW.status NOT IN ('cancelled', 'declined', 'completed') THEN
    IF NEW.linked_shift_id IS NOT NULL THEN RAISE EXCEPTION 'Workshop work runs through its work order, not a patrol shift'; END IF;
    PERFORM 1 FROM public.workshop_work_orders
      WHERE id = v_unit.workshop_work_order_id AND organization_id = NEW.organization_id
        AND status IN ('approved', 'in_progress') FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Approve an open Workshop work order before rostering its labour'; END IF;
  END IF;
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."enforce_workshop_roster_order"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."enforce_workshop_roster_order"() TO "postgres";

CREATE OR REPLACE FUNCTION "public"."enqueue_notification"(p_organization_id uuid, p_category text, p_title text, p_body text DEFAULT NULL::text, p_severity text DEFAULT 'info'::text, p_recipient_user_id uuid DEFAULT NULL::uuid, p_recipient_role text DEFAULT NULL::text, p_link_page text DEFAULT NULL::text, p_link_payload jsonb DEFAULT NULL::jsonb, p_dedup_key text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id uuid;
begin
  if p_recipient_user_id is null and p_recipient_role is null then
    raise exception 'enqueue_notification requires a recipient_user_id or recipient_role';
  end if;

  -- Idempotent on dedup_key within the org.
  if p_dedup_key is not null then
    select id into v_id
    from notifications
    where organization_id = p_organization_id and dedup_key = p_dedup_key
    limit 1;
    if v_id is not null then
      return v_id;
    end if;
  end if;

  insert into notifications (
    organization_id, recipient_user_id, recipient_role, category, severity,
    title, body, link_page, link_payload, dedup_key
  ) values (
    p_organization_id, p_recipient_user_id, p_recipient_role, p_category, coalesce(p_severity, 'info'),
    p_title, p_body, p_link_page, p_link_payload, p_dedup_key
  )
  returning id into v_id;

  return v_id;
end;
$function$;
COMMENT ON FUNCTION "public"."enqueue_notification"(p_organization_id uuid, p_category text, p_title text, p_body text, p_severity text, p_recipient_user_id uuid, p_recipient_role text, p_link_page text, p_link_payload jsonb, p_dedup_key text) IS 'Layer 4.4 single write path for notifications. Idempotent on (organization_id, dedup_key). Server only: SECURITY DEFINER functions and triggers, and edge functions with the service role. Clients cannot execute it.';
REVOKE ALL ON FUNCTION "public"."enqueue_notification"(p_organization_id uuid, p_category text, p_title text, p_body text, p_severity text, p_recipient_user_id uuid, p_recipient_role text, p_link_page text, p_link_payload jsonb, p_dedup_key text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."enqueue_notification"(p_organization_id uuid, p_category text, p_title text, p_body text, p_severity text, p_recipient_user_id uuid, p_recipient_role text, p_link_page text, p_link_payload jsonb, p_dedup_key text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."enqueue_notification"(p_organization_id uuid, p_category text, p_title text, p_body text, p_severity text, p_recipient_user_id uuid, p_recipient_role text, p_link_page text, p_link_payload jsonb, p_dedup_key text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."ensure_canonical_person_for_record"(p_person_record_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
  v_rec record;
  v_key text;
BEGIN
  IF p_person_record_id IS NULL THEN RETURN NULL; END IF;

  SELECT canonical_person_id INTO v_id
  FROM public.canonical_person_links
  WHERE source_table = 'person_records' AND source_id = p_person_record_id
  LIMIT 1;
  IF v_id IS NOT NULL THEN RETURN v_id; END IF;

  SELECT id, display_name, organization_id, review_state INTO v_rec
  FROM public.person_records WHERE id = p_person_record_id;
  IF v_rec.id IS NULL THEN RETURN NULL; END IF;

  v_key := 'person_record:' || v_rec.id::text;
  INSERT INTO public.canonical_people (canonical_key, display_name, normalized_name, metadata, review_state)
  VALUES (
    v_key, v_rec.display_name,
    regexp_replace(lower(trim(coalesce(v_rec.display_name, ''))), '[^a-z0-9]+', '', 'g'),
    jsonb_build_object('created_from', 'person_records', 'source_id', v_rec.id, 'source_organization_id', v_rec.organization_id),
    coalesce(v_rec.review_state, 'draft')
  )
  ON CONFLICT (canonical_key) DO NOTHING
  RETURNING id INTO v_id;
  IF v_id IS NULL THEN
    SELECT id INTO v_id FROM public.canonical_people WHERE canonical_key = v_key;
  END IF;

  INSERT INTO public.canonical_person_links (canonical_person_id, source_table, source_id, organization_id, link_kind, metadata)
  VALUES (v_id, 'person_records', v_rec.id, v_rec.organization_id, 'projection', jsonb_build_object('review_state', v_rec.review_state))
  ON CONFLICT (source_table, source_id) DO NOTHING;

  RETURN v_id;
END;
$function$;
COMMENT ON FUNCTION "public"."ensure_canonical_person_for_record"(p_person_record_id uuid) IS 'Find-or-create the global person identity for a tenant-scoped person_records row. Cross-organization merges remain a human review action.';
REVOKE ALL ON FUNCTION "public"."ensure_canonical_person_for_record"(p_person_record_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."ensure_canonical_person_for_record"(p_person_record_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."ensure_canonical_person_for_record"(p_person_record_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."ensure_canonical_person_for_staff"(p_staff_profile_id uuid)
 RETURNS TABLE(canonical_person_id uuid, person_record_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_staff public.staff_profiles%rowtype;
  v_name text;
  v_person_id uuid;
  v_canonical_id uuid;
BEGIN
  SELECT * INTO v_staff FROM public.staff_profiles WHERE id=p_staff_profile_id;
  IF v_staff.id IS NULL THEN RAISE EXCEPTION 'Staff profile not found'; END IF;
  SELECT link.canonical_person_id INTO v_canonical_id FROM public.canonical_person_links link
  WHERE link.source_table='staff_profiles' AND link.source_id=v_staff.id LIMIT 1;
  SELECT record.id INTO v_person_id FROM public.person_records record
  WHERE record.metadata->>'staff_profile_id'=v_staff.id::text LIMIT 1;
  IF v_person_id IS NULL THEN
    SELECT nullif(trim(profile.display_name),'') INTO v_name FROM public.user_profiles profile WHERE profile.id=coalesce(v_staff.user_id,v_staff.id);
    INSERT INTO public.person_records(organization_id,display_name,review_state,metadata)
    VALUES(v_staff.organization_id,coalesce(v_name,v_staff.employee_number,'Staff member'),'manual_review_required',
      jsonb_build_object('profile_details',jsonb_strip_nulls(jsonb_build_object('category','Staff member','staff_profile_id',v_staff.id,'user_id',v_staff.user_id)),
        'created_from','staff_profiles','staff_profile_id',v_staff.id))
    ON CONFLICT ((metadata->>'staff_profile_id')) WHERE metadata ? 'staff_profile_id' DO UPDATE SET organization_id=excluded.organization_id
    RETURNING id INTO v_person_id;
  END IF;
  IF v_canonical_id IS NULL THEN v_canonical_id:=public.ensure_canonical_person_for_record(v_person_id); END IF;
  INSERT INTO public.canonical_person_links(canonical_person_id,source_table,source_id,organization_id,link_kind,metadata)
  VALUES(v_canonical_id,'staff_profiles',v_staff.id,v_staff.organization_id,'projection',jsonb_build_object('person_record_id',v_person_id,'user_id',v_staff.user_id))
  ON CONFLICT (source_table,source_id) DO UPDATE SET canonical_person_id=excluded.canonical_person_id,organization_id=excluded.organization_id,metadata=excluded.metadata;
  RETURN QUERY SELECT v_canonical_id,v_person_id;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."ensure_canonical_person_for_staff"(p_staff_profile_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."ensure_canonical_person_for_staff"(p_staff_profile_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."ensure_canonical_person_for_staff"(p_staff_profile_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."ensure_canonical_place"(p_kind text, p_key text, p_name text, p_address text, p_meta jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; v_into uuid; v_status text; v_hops integer := 0;
BEGIN
  IF p_key IS NULL OR p_kind NOT IN ('site', 'zone') THEN RETURN NULL; END IF;
  INSERT INTO public.canonical_places (place_kind, canonical_key, display_name, normalized_name, address, metadata)
  VALUES (p_kind, p_key, coalesce(nullif(trim(p_name), ''), p_address, p_key),
          regexp_replace(lower(trim(coalesce(p_name, ''))), '[^a-z0-9]+', '', 'g'), p_address, coalesce(p_meta, '{}'::jsonb))
  ON CONFLICT (canonical_key) DO NOTHING
  RETURNING id INTO v_id;
  IF v_id IS NULL THEN
    SELECT id, status, merged_into_id INTO v_id, v_status, v_into FROM public.canonical_places WHERE canonical_key = p_key;
    WHILE v_status = 'merged' AND v_into IS NOT NULL AND v_hops < 10 LOOP
      SELECT id, status, merged_into_id INTO v_id, v_status, v_into FROM public.canonical_places WHERE id = v_into;
      v_hops := v_hops + 1;
    END LOOP;
  END IF;
  RETURN v_id;
END $function$;
REVOKE ALL ON FUNCTION "public"."ensure_canonical_place"(p_kind text, p_key text, p_name text, p_address text, p_meta jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."ensure_canonical_place"(p_kind text, p_key text, p_name text, p_address text, p_meta jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."ensure_canonical_place"(p_kind text, p_key text, p_name text, p_address text, p_meta jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."ensure_canonical_place_for_house"(p_location_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_house public.locations%rowtype; v_id uuid;
BEGIN
  SELECT * INTO v_house FROM public.locations WHERE id = p_location_id;
  IF v_house.id IS NULL THEN RETURN NULL; END IF;
  IF v_house.canonical_place_id IS NOT NULL THEN RETURN v_house.canonical_place_id; END IF;
  v_id := public.canonical_place_for_house(v_house.id, v_house.organization_id, v_house.name, v_house.address, v_house.address_match_key,
    CASE WHEN EXISTS (SELECT 1 FROM public.client_sites s WHERE s.location_id = v_house.id) THEN 'site' ELSE 'zone' END);
  UPDATE public.locations SET canonical_place_id = v_id, updated_at = now() WHERE id = v_house.id;
  RETURN v_id;
END $function$;
REVOKE ALL ON FUNCTION "public"."ensure_canonical_place_for_house"(p_location_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."ensure_canonical_place_for_house"(p_location_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."ensure_canonical_place_for_house"(p_location_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."ensure_canonical_place_for_projection"(p_source_table text, p_source_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_house uuid; v_org uuid; v_id uuid;
BEGIN
  IF p_source_id IS NULL THEN RETURN NULL; END IF;
  IF p_source_table = 'locations' THEN
    v_house := p_source_id;
  ELSIF p_source_table = 'client_sites' THEN
    SELECT location_id, client_organization_id INTO v_house, v_org FROM public.client_sites WHERE id = p_source_id;
  ELSIF p_source_table = 'location_zones' THEN
    SELECT location_id, organization_id INTO v_house, v_org FROM public.location_zones WHERE id = p_source_id;
  ELSE
    RETURN NULL;
  END IF;
  IF v_house IS NULL THEN RETURN NULL; END IF;
  SELECT canonical_place_id INTO v_id FROM public.locations WHERE id = v_house;
  IF v_id IS NULL THEN v_id := public.ensure_canonical_place_for_house(v_house); END IF;
  IF v_id IS NULL THEN RETURN NULL; END IF;
  IF p_source_table <> 'locations' THEN
    INSERT INTO public.canonical_place_links (canonical_place_id, source_table, source_id, organization_id, link_kind, source_key, metadata)
    VALUES (v_id, p_source_table, p_source_id, v_org, 'projection', p_source_id::text, jsonb_build_object('location_id', v_house))
    ON CONFLICT (source_table, source_id) DO UPDATE SET canonical_place_id = EXCLUDED.canonical_place_id;
  END IF;
  RETURN v_id;
END $function$;
COMMENT ON FUNCTION "public"."ensure_canonical_place_for_projection"(p_source_table text, p_source_id uuid) IS 'Find-or-create the global place identity for a locations/client_sites/location_zones row, mirroring the backfill precedence: a facet with a house links to the house identity.';
REVOKE ALL ON FUNCTION "public"."ensure_canonical_place_for_projection"(p_source_table text, p_source_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."ensure_canonical_place_for_projection"(p_source_table text, p_source_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."ensure_canonical_place_for_projection"(p_source_table text, p_source_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."ensure_canonical_vehicle"(p_plate text, p_make text, p_model text, p_colour text, p_source_table text, p_source_key text, p_observed_at timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_alnum text := upper(regexp_replace(coalesce(p_plate, ''), '[^A-Za-z0-9]', '', 'g'));
  v_plate text := public.normalize_plate_number(p_plate);
  v_id uuid;
  v_make text := CASE WHEN p_source_table = 'cctv_entity_observations' THEN NULL ELSE p_make END;
  v_model text := CASE WHEN p_source_table = 'cctv_entity_observations' THEN NULL ELSE p_model END;
  v_colour text := CASE WHEN p_source_table = 'cctv_entity_observations' THEN NULL ELSE p_colour END;
BEGIN
  IF v_plate IS NULL THEN RETURN NULL; END IF;
  IF length(v_alnum) > 10 THEN RETURN NULL; END IF;

  SELECT id INTO v_id FROM public.canonical_vehicles WHERE plate_number = v_plate;
  IF v_id IS NOT NULL THEN RETURN v_id; END IF;

  INSERT INTO public.canonical_vehicles (plate_number, make, model, colour, last_seen_at)
  VALUES (v_plate, v_make, v_model, v_colour, p_observed_at)
  ON CONFLICT (plate_number) DO NOTHING
  RETURNING id INTO v_id;

  IF v_id IS NULL THEN
    SELECT id INTO v_id FROM public.canonical_vehicles WHERE plate_number = v_plate;
    RETURN v_id;
  END IF;

  INSERT INTO public.canonical_vehicle_links (
    canonical_vehicle_id, source_system, source_table, source_key, metadata
  ) VALUES (
    v_id, 'field_observation', p_source_table, p_source_key,
    jsonb_build_object(
      'created_from_record', true,
      'observed_at', p_observed_at,
      'raw_plate', p_plate
    )
  )
  ON CONFLICT (source_system, source_table, source_key) DO NOTHING;

  RETURN v_id;
END;
$function$;
COMMENT ON FUNCTION "public"."ensure_canonical_vehicle"(p_plate text, p_make text, p_model text, p_colour text, p_source_table text, p_source_key text, p_observed_at timestamp with time zone) IS 'Find-or-create the global vehicle identity for a normalized plate. CCTV calls establish identity only; their visual attributes require the dedicated human attribute review before canonical promotion.';
REVOKE ALL ON FUNCTION "public"."ensure_canonical_vehicle"(p_plate text, p_make text, p_model text, p_colour text, p_source_table text, p_source_key text, p_observed_at timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."ensure_canonical_vehicle"(p_plate text, p_make text, p_model text, p_colour text, p_source_table text, p_source_key text, p_observed_at timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."ensure_canonical_vehicle"(p_plate text, p_make text, p_model text, p_colour text, p_source_table text, p_source_key text, p_observed_at timestamp with time zone) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."ensure_cctv_person_profile"(p_organization_id uuid, p_portfolio_key uuid, p_observation_id uuid DEFAULT NULL::uuid, p_evidence_item_id uuid DEFAULT NULL::uuid, p_observed_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS TABLE(person_record_id uuid, canonical_person_id uuid, display_name text, created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_person_id uuid;
  v_canonical_id uuid;
  v_display_name text;
  v_unknown_number integer;
  v_created boolean := false;
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' AND session_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;
  IF p_organization_id IS NULL OR p_portfolio_key IS NULL THEN
    RAISE EXCEPTION 'Organization and person portfolio are required';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.organizations WHERE id = p_organization_id) THEN
    RAISE EXCEPTION 'Organization does not exist';
  END IF;

  -- Serialise the per-organisation number so concurrent clips cannot mint the same Unknown Person #N.
  PERFORM pg_advisory_xact_lock(hashtextextended('cctv_unknown_person:' || p_organization_id::text, 0));

  SELECT observation.person_record_id,
         COALESCE(observation.canonical_person_id, link.canonical_person_id),
         person.display_name
    INTO v_person_id, v_canonical_id, v_display_name
    FROM public.cctv_entity_observations AS observation
    LEFT JOIN public.person_records AS person ON person.id = observation.person_record_id
    LEFT JOIN public.canonical_person_links AS link
      ON link.source_table = 'person_records' AND link.source_id = observation.person_record_id
   WHERE observation.organization_id = p_organization_id
     AND observation.entity_kind = 'person'
     AND observation.portfolio_key = p_portfolio_key
     AND observation.review_state <> 'rejected'
     AND observation.person_record_id IS NOT NULL
   ORDER BY (observation.review_state = 'accepted') DESC,
            observation.reviewed_at DESC NULLS LAST,
            observation.observed_at
   LIMIT 1;

  IF v_person_id IS NULL THEN
    SELECT person.id, link.canonical_person_id, person.display_name
      INTO v_person_id, v_canonical_id, v_display_name
      FROM public.person_records AS person
      LEFT JOIN public.canonical_person_links AS link
        ON link.source_table = 'person_records' AND link.source_id = person.id
     WHERE person.organization_id = p_organization_id
       AND person.metadata->>'cctv_portfolio_key' = p_portfolio_key::text
     ORDER BY person.created_at
     LIMIT 1;
  END IF;

  IF v_person_id IS NULL AND (
    p_observation_id IS NULL OR NOT EXISTS (
      SELECT 1
      FROM public.cctv_entity_observations AS observation
      WHERE observation.id = p_observation_id
        AND observation.organization_id = p_organization_id
        AND observation.entity_kind = 'person'
        AND observation.face_vec IS NOT NULL
        AND observation.quality_state = 'clear'
        AND observation.attributes->>'face_usable_for_matching' = 'true'
    )
  ) THEN
    RETURN;
  END IF;

  IF v_person_id IS NULL THEN
    SELECT COALESCE(MAX(GREATEST(
      CASE WHEN person.metadata->>'cctv_unknown_person_number' ~ '^[0-9]+$'
        THEN (person.metadata->>'cctv_unknown_person_number')::integer ELSE 0 END,
      CASE WHEN person.display_name ~ '^Unknown Person #[0-9]+$'
        THEN regexp_replace(person.display_name, '^Unknown Person #', '')::integer ELSE 0 END
    )), 0) + 1
      INTO v_unknown_number
      FROM public.person_records AS person
     WHERE person.organization_id = p_organization_id;

    v_display_name := 'Unknown Person #' || v_unknown_number;
    INSERT INTO public.person_records (organization_id, display_name, review_state, metadata)
    VALUES (
      p_organization_id,
      v_display_name,
      'manual_review_required',
      jsonb_strip_nulls(jsonb_build_object(
        'origin', 'cctv_inference_profile',
        'identity_status', 'unknown_pending_human_review',
        'cctv_portfolio_key', p_portfolio_key,
        'cctv_unknown_person_number', v_unknown_number,
        'first_observation_id', p_observation_id,
        'first_evidence_item_id', p_evidence_item_id,
        'first_seen_at', p_observed_at
      ))
    )
    RETURNING id INTO v_person_id;
    v_canonical_id := public.ensure_canonical_person_for_record(v_person_id);
    UPDATE public.canonical_people
       SET metadata = metadata || jsonb_strip_nulls(jsonb_build_object(
             'origin', 'cctv_inference_profile',
             'identity_status', 'unknown_pending_human_review',
             'cctv_portfolio_key', p_portfolio_key,
             'cctv_unknown_person_number', v_unknown_number,
             'first_observation_id', p_observation_id,
             'first_evidence_item_id', p_evidence_item_id,
             'first_seen_at', p_observed_at
           )),
           review_state = 'manual_review_required',
           updated_at = clock_timestamp()
     WHERE id = v_canonical_id;

    INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
    VALUES (
      p_organization_id, NULL, 'cctv_unknown_person_profile_created', 'person_records', v_person_id,
      jsonb_build_object(
        'canonical_person_id', v_canonical_id,
        'portfolio_key', p_portfolio_key,
        'unknown_person_number', v_unknown_number,
        'observation_id', p_observation_id,
        'evidence_item_id', p_evidence_item_id
      )
    );
    v_created := true;
  ELSE
    v_canonical_id := COALESCE(v_canonical_id, public.ensure_canonical_person_for_record(v_person_id));
  END IF;

  person_record_id := v_person_id;
  canonical_person_id := v_canonical_id;
  display_name := v_display_name;
  created := v_created;
  RETURN NEXT;
END;
$function$;
COMMENT ON FUNCTION "public"."ensure_cctv_person_profile"(p_organization_id uuid, p_portfolio_key uuid, p_observation_id uuid, p_evidence_item_id uuid, p_observed_at timestamp with time zone) IS 'Service-only find-or-create of a provisional CCTV person profile. New profiles require a clear, quality-gated face observation; human review is still required before identity use.';
REVOKE ALL ON FUNCTION "public"."ensure_cctv_person_profile"(p_organization_id uuid, p_portfolio_key uuid, p_observation_id uuid, p_evidence_item_id uuid, p_observed_at timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."ensure_cctv_person_profile"(p_organization_id uuid, p_portfolio_key uuid, p_observation_id uuid, p_evidence_item_id uuid, p_observed_at timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."ensure_cctv_person_profile"(p_organization_id uuid, p_portfolio_key uuid, p_observation_id uuid, p_evidence_item_id uuid, p_observed_at timestamp with time zone) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."ensure_crm_client_agreement"(p_account_organization_id uuid, p_provider_organization_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_home uuid;
  v_provider uuid;
  v_account public.organizations%rowtype;
  v_agreement public.service_agreements%rowtype;
  v_created boolean := false;
BEGIN
  SELECT organization_id INTO v_home FROM public.user_profiles WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_home IS NULL THEN RAISE EXCEPTION 'Active CRM administrator required'; END IF;
  v_provider := coalesce(p_provider_organization_id, v_home);
  IF NOT public.is_admin_for_org(v_provider) THEN RAISE EXCEPTION 'Not authorised to hold agreements for this organisation'; END IF;
  SELECT * INTO v_account FROM public.organizations WHERE id = p_account_organization_id FOR UPDATE;
  IF NOT FOUND OR NOT public.crm_actor_can_manage_account(v_account.id) THEN RAISE EXCEPTION 'Client account not found'; END IF;
  IF v_account.id = v_provider THEN RAISE EXCEPTION 'An organisation cannot be its own client'; END IF;

  SELECT * INTO v_agreement
  FROM public.service_agreements
  WHERE provider_organization_id = v_provider AND client_organization_id = v_account.id AND agreement_type = 'operational'
    AND (ends_on IS NULL OR ends_on >= current_date)
  ORDER BY CASE WHEN invitation_status = 'accepted' THEN 0 WHEN invitation_status = 'invited' THEN 1 ELSE 2 END, created_at DESC
  LIMIT 1 FOR UPDATE;
  IF NOT FOUND THEN
    INSERT INTO public.service_agreements (provider_organization_id, client_organization_id, name, starts_on, agreement_type, invitation_status, client_portal_access_mode, external_refs)
    VALUES (v_provider, v_account.id, v_account.name || ' service agreement', current_date, 'operational', 'not_invited', 'transparency_only', jsonb_build_object('created_via', 'client_setup', 'created_by', v_actor))
    RETURNING * INTO v_agreement;
    v_created := true;
    INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
    VALUES (v_provider, v_actor, 'service_agreement_created', 'service_agreements', v_agreement.id, jsonb_build_object('client_organization_id', v_account.id, 'via', 'client_setup'));
  END IF;
  RETURN jsonb_build_object('agreement_id', v_agreement.id, 'created', v_created, 'invitation_status', v_agreement.invitation_status,
    'provider_organization_id', v_agreement.provider_organization_id, 'client_organization_id', v_agreement.client_organization_id, 'name', v_agreement.name);
END;
$function$;
COMMENT ON FUNCTION "public"."ensure_crm_client_agreement"(p_account_organization_id uuid, p_provider_organization_id uuid) IS 'The live operational agreement between the operating organisation (default: the caller''s home) and a client account, created not_invited / transparency_only when none exists. Used by the guided client setup so places and services can be recorded before the client is invited.';
REVOKE ALL ON FUNCTION "public"."ensure_crm_client_agreement"(p_account_organization_id uuid, p_provider_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."ensure_crm_client_agreement"(p_account_organization_id uuid, p_provider_organization_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."ensure_crm_client_agreement"(p_account_organization_id uuid, p_provider_organization_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."ensure_crm_client_agreement"(p_account_organization_id uuid, p_provider_organization_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."ensure_file_organization_tree"(p_organization_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_organisation_space uuid;v_people_space uuid;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.organizations WHERE id=p_organization_id) THEN RAISE EXCEPTION 'Organization not found'; END IF;
  INSERT INTO public.file_spaces(organization_id,space_key,name,sensitivity,sort_order) VALUES
    (p_organization_id,'organisation','Organisation','internal',10),
    (p_organization_id,'contracts','Contracts','internal',20),
    (p_organization_id,'locations','Locations','internal',30),
    (p_organization_id,'people','People','restricted',40),
    (p_organization_id,'finance','Finance','restricted',50),
    (p_organization_id,'evidence','Evidence','restricted',60),
    (p_organization_id,'investigations','Investigations','restricted',70),
    (p_organization_id,'bob','Bob intake','internal',80),
    (p_organization_id,'generated','Generated outputs','internal',90)
  ON CONFLICT(organization_id,space_key) DO UPDATE SET name=excluded.name,sensitivity=excluded.sensitivity,sort_order=excluded.sort_order,active=true,updated_at=clock_timestamp();

  SELECT id INTO v_organisation_space FROM public.file_spaces WHERE organization_id=p_organization_id AND space_key='organisation';
  INSERT INTO public.file_folders(organization_id,space_id,name,folder_key,folder_kind,policy_json) VALUES
    (p_organization_id,v_organisation_space,'Company records','company_records','system',jsonb_build_object('purpose','corporate records and registrations')),
    (p_organization_id,v_organisation_space,'Health & safety','health_safety','system',jsonb_build_object('purpose','organisation health and safety documents')),
    (p_organization_id,v_organisation_space,'Policies','policies','system',jsonb_build_object('purpose','organisation policies and procedures')),
    (p_organization_id,v_organisation_space,'Unfiled','unfiled','system',jsonb_build_object('purpose','new files awaiting folder placement'))
  ON CONFLICT(space_id,folder_key) DO UPDATE SET name=excluded.name,policy_json=excluded.policy_json,active=true,updated_at=clock_timestamp();

  SELECT id INTO v_people_space FROM public.file_spaces WHERE organization_id=p_organization_id AND space_key='people';
  INSERT INTO public.file_folders(organization_id,space_id,name,folder_key,folder_kind,policy_json) VALUES
    (p_organization_id,v_people_space,'Users & staff','users_staff','system',jsonb_build_object('purpose','staff and application user folders')),
    (p_organization_id,v_people_space,'Other people','other_people','system',jsonb_build_object('purpose','tenant person records that are not staff accounts'))
  ON CONFLICT(space_id,folder_key) DO UPDATE SET name=excluded.name,policy_json=excluded.policy_json,active=true,updated_at=clock_timestamp();
END;
$function$;
REVOKE ALL ON FUNCTION "public"."ensure_file_organization_tree"(p_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."ensure_file_organization_tree"(p_organization_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."ensure_file_organization_tree"(p_organization_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."ensure_site_financial_config_from_site"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  -- A captured draft does not approve financial defaults or an inferred provider relationship.
  if new.metadata->>'created_via' in ('service_client_setup', 'officer_field_capture')
    or new.metadata->'field_place_managed' = 'true'::jsonb then return new; end if;
  if new.service_agreement_id is null then
    return new;
  end if;

  insert into public.site_financial_config (
    organization_id,
    site_id,
    service_agreement_id,
    billing_model,
    billing_cycle,
    gst_registered,
    gst_rate,
    payment_terms_days,
    minimum_hours,
    active
  )
  values (
    new.client_organization_id,
    new.id,
    new.service_agreement_id,
    'hourly',
    'monthly',
    true,
    0.15,
    14,
    2,
    true
  )
  on conflict (site_id, service_agreement_id) do nothing;

  return new;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."ensure_site_financial_config_from_site"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."ensure_site_financial_config_from_site"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."ensure_site_financial_config_from_site"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."ensure_site_financial_config_from_site"() TO "anon";
GRANT EXECUTE ON FUNCTION "public"."ensure_site_financial_config_from_site"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."ensure_site_financial_config_from_site"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."evaluate_parking_compliance"(p_org_id uuid, p_zone_id uuid, p_plate text, p_is_disabled_bay boolean DEFAULT false, p_sign_time_limit_minutes integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rule record;
  v_legacy_zone_limit integer;
  v_legacy_multiplier numeric;
  v_legacy_org_default integer;
  v_legacy_grace integer;
  v_effective_limit integer;
  v_grace integer;
  v_multiplier numeric;
  v_chalk record;
  v_minutes_elapsed numeric;
  v_is_overstay boolean := false;
  v_is_repeat boolean;
  v_repeat_count integer;
BEGIN
  SELECT * INTO v_rule
  FROM public.parking_rule_matrix
  WHERE organization_id = p_org_id
    AND is_current
    AND effective_from <= current_date
    AND (effective_to IS NULL OR effective_to >= current_date)
    AND (zone_id = p_zone_id OR zone_id IS NULL)
  ORDER BY (zone_id IS NULL), effective_from DESC, version DESC
  LIMIT 1;

  SELECT parking_time_limit_minutes, parking_disabled_multiplier INTO v_legacy_zone_limit, v_legacy_multiplier
  FROM public.location_zones WHERE id = p_zone_id;
  SELECT default_time_limit_minutes, grace_period_minutes INTO v_legacy_org_default, v_legacy_grace
  FROM public.parking_module_config WHERE organization_id = p_org_id;

  v_effective_limit := COALESCE(p_sign_time_limit_minutes, v_rule.time_limit_minutes, v_legacy_zone_limit, v_legacy_org_default, 60);
  v_grace := COALESCE(v_rule.grace_period_minutes, v_legacy_grace, 5);
  v_multiplier := COALESCE(v_rule.disabled_multiplier, v_legacy_multiplier, 1);
  IF p_is_disabled_bay THEN v_effective_limit := round(v_effective_limit * v_multiplier); END IF;

  SELECT * INTO v_chalk FROM public.parking_chalk_records
  WHERE organization_id = p_org_id AND plate = upper(p_plate) AND status = 'active'
    AND (p_zone_id IS NULL OR zone_id = p_zone_id)
  ORDER BY chalked_at DESC LIMIT 1;

  IF v_chalk.id IS NOT NULL THEN
    v_minutes_elapsed := extract(epoch FROM (now() - v_chalk.chalked_at)) / 60.0;
    v_is_overstay := v_minutes_elapsed > (v_effective_limit + v_grace);
  END IF;

  SELECT count(*) INTO v_repeat_count FROM public.parking_chalk_records
  WHERE organization_id = p_org_id AND plate = upper(p_plate)
    AND chalked_at >= date_trunc('day', current_timestamp AT TIME ZONE 'Pacific/Auckland') AT TIME ZONE 'Pacific/Auckland'
    AND status != 'compliant' AND (v_chalk.id IS NULL OR id != v_chalk.id);
  v_is_repeat := v_repeat_count > 0;

  RETURN jsonb_build_object(
    'verdict', CASE WHEN v_is_overstay AND v_is_repeat THEN 'repeat_offender' WHEN v_is_overstay THEN 'overstay' WHEN v_chalk.id IS NOT NULL THEN 'watch' ELSE 'clear' END,
    'effective_limit_minutes', v_effective_limit, 'grace_period_minutes', v_grace,
    'chalked_at', v_chalk.chalked_at, 'minutes_elapsed', v_minutes_elapsed,
    'is_overstay', v_is_overstay, 'is_repeat', v_is_repeat, 'repeat_count', v_repeat_count,
    'recommended_action', CASE WHEN v_is_overstay THEN 'infringement' WHEN v_chalk.id IS NOT NULL THEN 'warning' ELSE 'none' END,
    'rule_matrix_id', v_rule.id, 'rule_matrix_version', v_rule.version
  );
END;
$function$;
