REVOKE ALL ON FUNCTION "public"."evaluate_parking_compliance"(p_org_id uuid, p_zone_id uuid, p_plate text, p_is_disabled_bay boolean, p_sign_time_limit_minutes integer) FROM PUBLIC, "anon", "authenticated", "service_role";
