GRANT EXECUTE ON FUNCTION "public"."evaluate_parking_compliance"(p_org_id uuid, p_zone_id uuid, p_plate text, p_is_disabled_bay boolean, p_sign_time_limit_minutes integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."evaluate_shift_start_position"(p_shift_id uuid, p_gps_lat double precision, p_gps_lng double precision)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_shift public.shifts%rowtype;
  v_point geometry;
  v_radius integer;
  v_best record;
begin
  if v_actor is null then raise exception 'Authentication required'; end if;
  select s.* into v_shift from public.shifts s where s.id = p_shift_id;
  if not found then raise exception 'Shift not found'; end if;
  if v_shift.officer_user_id <> v_actor and not public.is_admin_for_org(v_shift.organization_id) then
    raise exception 'Only the assigned officer or an administrator can evaluate this shift';
  end if;

  v_radius := coalesce(public.get_org_geofence_config(v_shift.organization_id, 'shift_start_advisory_radius_m', null, 250), 250);
  if p_gps_lat is not null and p_gps_lng is not null and p_gps_lat between -90 and 90 and p_gps_lng between -180 and 180 then
    v_point := st_setsrid(st_point(p_gps_lng, p_gps_lat), 4326);
  end if;

  -- Every place this shift is for: its stops' sites and zones, plus the shift's own zone. The place we are inside wins, else the nearest.
  with places as (
    select 'site'::text as kind, s.id, s.name, s.boundary::geometry as boundary, coalesce(s.center_point, st_centroid(s.boundary))::geometry as center, coalesce(s.onsite_radius_meters, 10) as onsite_radius
    from public.shift_stops st join public.client_sites s on s.id = st.site_id
    where st.shift_id = v_shift.id and st.status not in ('cancelled', 'skipped') and (s.boundary is not null or s.center_point is not null)
    union
    select 'zone'::text, z.id, z.name, z.boundary::geometry, coalesce(z.center_point, st_centroid(z.boundary))::geometry, 0
    from public.location_zones z
    where z.boundary is not null and (z.id = v_shift.zone_id or z.id in (select st.zone_id from public.shift_stops st where st.shift_id = v_shift.id and st.status not in ('cancelled', 'skipped') and st.zone_id is not null))
  ), scored as (
    select p.kind, p.id, p.name,
      ((p.boundary is not null and st_covers(p.boundary, v_point)) or st_dwithin(p.center::geography, v_point::geography, p.onsite_radius)) as inside,
      st_distance(coalesce(p.boundary, p.center)::geography, v_point::geography) as dist,
      count(*) over () as place_count
    from places p
  )
  select kind, id, name, inside, round(dist::numeric, 0) as distance_m, place_count
  into v_best
  from scored
  order by inside desc nulls last, dist asc nulls last, kind desc, name
  limit 1;

  if v_best.id is null then
    return jsonb_build_object('status', 'no_place', 'advisory_radius_m', v_radius, 'place_count', 0, 'route_shift', v_shift.patrol_route_id is not null);
  end if;
  if v_point is null then
    return jsonb_build_object('status', 'no_gps', 'advisory_radius_m', v_radius, 'place_count', v_best.place_count, 'place_kind', v_best.kind, 'place_id', v_best.id, 'place_name', v_best.name, 'route_shift', v_shift.patrol_route_id is not null);
  end if;

  return jsonb_build_object(
    'status', case when v_best.inside then 'on_site' when v_best.distance_m <= v_radius then 'near_site' else 'off_site' end,
    'place_kind', v_best.kind,
    'place_id', v_best.id,
    'place_name', v_best.name,
    'distance_m', v_best.distance_m,
    'advisory_radius_m', v_radius,
    'place_count', v_best.place_count,
    'route_shift', v_shift.patrol_route_id is not null
  );
end;
$function$;
COMMENT ON FUNCTION "public"."evaluate_shift_start_position"(p_shift_id uuid, p_gps_lat double precision, p_gps_lng double precision) IS 'Where the officer is relative to the shift''s places: on_site (inside a boundary or on-site radius), near_site (within the organisation''s shift_start_advisory_radius_m, default 250), off_site, no_gps, or no_place. Advisory only; never blocks.';
REVOKE ALL ON FUNCTION "public"."evaluate_shift_start_position"(p_shift_id uuid, p_gps_lat double precision, p_gps_lng double precision) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."evaluate_shift_start_position"(p_shift_id uuid, p_gps_lat double precision, p_gps_lng double precision) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."evaluate_shift_start_position"(p_shift_id uuid, p_gps_lat double precision, p_gps_lng double precision) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."evaluate_shift_start_position"(p_shift_id uuid, p_gps_lat double precision, p_gps_lng double precision) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."evaluate_static_shift_position"(p_shift_id uuid, p_gps_lat double precision, p_gps_lng double precision)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare v_shift public.shifts%rowtype; v_stop public.shift_stops%rowtype; v_verified boolean := false; v_status text;
begin
  select * into v_shift from public.shifts where id = p_shift_id;
  if not found or auth.uid() is null or v_shift.officer_user_id is distinct from auth.uid()
    or v_shift.service_type <> 'static_guarding'
    or not exists(select 1 from public.user_profiles where id = auth.uid() and deactivated_at is null) then
    raise exception 'Active assigned static officer required' using errcode = '42501';
  end if;
  if (select count(*) from public.shift_stops where shift_id = v_shift.id) <> 1 then
    raise exception 'Static work requires one assigned place; contact operations';
  end if;
  select * into v_stop from public.shift_stops where shift_id = v_shift.id and module_key = 'static_guarding';
  if not found then raise exception 'Static guarding stop is missing'; end if;
  if p_gps_lat is null or p_gps_lng is null then
    v_status := 'no_gps';
  elsif not (p_gps_lat between -90 and 90 and p_gps_lng between -180 and 180) then
    raise exception 'Invalid GPS position';
  else
    select coalesce(cs.boundary_verification = 'verified' and cs.boundary is not null
      and st_isvalid(cs.boundary) and not st_isempty(cs.boundary)
      and (st_covers(cs.boundary, st_setsrid(st_point(p_gps_lng, p_gps_lat),4326))
        or st_dwithin(coalesce(cs.center_point,cs.boundary)::geography,
          st_setsrid(st_point(p_gps_lng,p_gps_lat),4326)::geography,coalesce(cs.onsite_radius_meters,10))), false)
      into v_verified from public.client_sites cs where cs.id = v_stop.site_id and cs.active;
    v_status := case when coalesce(v_verified, false) then 'on_site'
      when exists(select 1 from public.client_sites where id = v_stop.site_id and active and boundary is not null and boundary_verification = 'verified') then 'off_site'
      else 'unverified_site' end;
  end if;
  return jsonb_build_object('status',v_status,'verified_attendance',coalesce(v_verified,false));
end;
$function$;
REVOKE ALL ON FUNCTION "public"."evaluate_static_shift_position"(p_shift_id uuid, p_gps_lat double precision, p_gps_lng double precision) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."evaluate_static_shift_position"(p_shift_id uuid, p_gps_lat double precision, p_gps_lng double precision) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."evaluate_static_shift_position"(p_shift_id uuid, p_gps_lat double precision, p_gps_lng double precision) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."expire_cctv_biometric_templates"(p_retention interval DEFAULT '90 days'::interval, p_organization_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 5000)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_total integer := 0;
  v_org record;
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' AND session_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;
  IF p_retention IS NULL OR p_retention < interval '1 day' THEN
    RAISE EXCEPTION 'Biometric retention must be at least one day';
  END IF;

  FOR v_org IN
    WITH due AS (
      SELECT o.id, o.organization_id
      FROM public.cctv_entity_observations o
      WHERE (p_organization_id IS NULL OR o.organization_id = p_organization_id)
        AND (o.face_vec IS NOT NULL OR o.appearance_vec IS NOT NULL OR o.vehicle_appearance_vec IS NOT NULL
          OR o.candidate_embedding IS NOT NULL OR o.appearance_embedding IS NOT NULL)
        AND (
          o.review_state = 'rejected'
          OR (o.review_state IN ('unreviewed', 'uncertain', 'needs_more_context', 'superseded')
            AND o.created_at < v_now - p_retention)
        )
      ORDER BY o.created_at
      LIMIT p_limit
    ), expired AS (
      UPDATE public.cctv_entity_observations o
      SET face_vec = NULL, appearance_vec = NULL, vehicle_appearance_vec = NULL,
          candidate_embedding = NULL, appearance_embedding = NULL,
          attributes = coalesce(o.attributes, '{}'::jsonb) || jsonb_build_object(
            'biometric_templates_expired_at', v_now,
            'biometric_templates_expiry_reason', CASE WHEN o.review_state = 'rejected' THEN 'rejected' ELSE 'retention_window' END
          )
      FROM due
      WHERE o.id = due.id
      RETURNING o.organization_id, (o.attributes->>'biometric_templates_expiry_reason') AS reason
    )
    SELECT organization_id,
      count(*) FILTER (WHERE reason = 'rejected') AS rejected,
      count(*) FILTER (WHERE reason = 'retention_window') AS aged,
      count(*) AS total
    FROM expired GROUP BY organization_id
  LOOP
    v_total := v_total + v_org.total;
    INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
    VALUES (v_org.organization_id, NULL, 'cctv_biometric_templates_expired', 'cctv_entity_observations', NULL,
      jsonb_build_object('expired', v_org.total, 'rejected', v_org.rejected, 'aged_out', v_org.aged,
        'retention', p_retention::text, 'expired_at', v_now));
  END LOOP;

  RETURN jsonb_build_object('expired', v_total, 'retention', p_retention::text, 'expired_at', v_now);
END;
$function$;
COMMENT ON FUNCTION "public"."expire_cctv_biometric_templates"(p_retention interval, p_organization_id uuid, p_limit integer) IS 'Service-only: expires face, person, and vehicle appearance templates for rejected sightings and undecided sightings past retention; keeps the sighting, thumbnail and decision.';
REVOKE ALL ON FUNCTION "public"."expire_cctv_biometric_templates"(p_retention interval, p_organization_id uuid, p_limit integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."expire_cctv_biometric_templates"(p_retention interval, p_organization_id uuid, p_limit integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."expire_cctv_biometric_templates"(p_retention interval, p_organization_id uuid, p_limit integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."face_embedding_cosine"(p_left jsonb, p_right jsonb)
 RETURNS real
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  left_value jsonb;
  right_value jsonb;
  left_norm double precision := 0;
  right_norm double precision := 0;
  dot_product double precision := 0;
  index integer;
  left_number double precision;
  right_number double precision;
BEGIN
  IF jsonb_typeof(p_left) <> 'array' OR jsonb_typeof(p_right) <> 'array'
     OR jsonb_array_length(p_left) = 0 OR jsonb_array_length(p_left) <> jsonb_array_length(p_right) THEN
    RETURN 0;
  END IF;
  FOR index IN 0..jsonb_array_length(p_left) - 1 LOOP
    left_value := p_left -> index;
    right_value := p_right -> index;
    IF jsonb_typeof(left_value) <> 'number' OR jsonb_typeof(right_value) <> 'number' THEN
      RETURN 0;
    END IF;
    left_number := left_value::text::double precision;
    right_number := right_value::text::double precision;
    dot_product := dot_product + left_number * right_number;
    left_norm := left_norm + left_number * left_number;
    right_norm := right_norm + right_number * right_number;
  END LOOP;
  IF left_norm = 0 OR right_norm = 0 THEN RETURN 0; END IF;
  RETURN (dot_product / sqrt(left_norm * right_norm))::real;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."face_embedding_cosine"(p_left jsonb, p_right jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."face_embedding_cosine"(p_left jsonb, p_right jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."face_embedding_cosine"(p_left jsonb, p_right jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."field_place_agreement_id"(p_provider_id uuid, p_client_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_ids uuid[];
BEGIN
  IF NOT public.field_place_client_allowed(p_provider_id, p_client_id) THEN
    RAISE EXCEPTION 'No current operational agreement for this client';
  END IF;
  IF p_provider_id = p_client_id THEN RETURN NULL; END IF;
  SELECT array_agg(id ORDER BY created_at) INTO v_ids FROM public.service_agreements
    WHERE provider_organization_id = p_provider_id AND client_organization_id = p_client_id
      AND agreement_type = 'operational'
      AND (starts_on IS NULL OR starts_on <= current_date) AND (ends_on IS NULL OR ends_on >= current_date);
  IF coalesce(cardinality(v_ids), 0) <> 1 THEN
    RAISE EXCEPTION 'One current operational agreement is required. Ask an administrator to review the client agreements';
  END IF;
  RETURN v_ids[1];
END;
$function$;
REVOKE ALL ON FUNCTION "public"."field_place_agreement_id"(p_provider_id uuid, p_client_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."field_place_agreement_id"(p_provider_id uuid, p_client_id uuid) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."field_place_client_allowed"(p_provider_id uuid, p_client_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT p_client_id IS NOT NULL AND public.field_place_provider_allowed(p_provider_id) AND
    (p_client_id = p_provider_id OR EXISTS (
      SELECT 1 FROM public.service_agreements a
      WHERE a.provider_organization_id = p_provider_id AND a.client_organization_id = p_client_id
        AND a.agreement_type = 'operational'
        AND (a.starts_on IS NULL OR a.starts_on <= current_date)
        AND (a.ends_on IS NULL OR a.ends_on >= current_date)
    ));
$function$;
REVOKE ALL ON FUNCTION "public"."field_place_client_allowed"(p_provider_id uuid, p_client_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."field_place_client_allowed"(p_provider_id uuid, p_client_id uuid) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."field_place_provider_allowed"(p_provider_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT private.rm_tenancy_tree_contains(p_provider_id)
    AND EXISTS (
      SELECT 1
      FROM public.organizations provider
      WHERE provider.id = p_provider_id
        AND provider.active
        AND provider.organization_type IN ('service_provider', 'branch', 'contractor')
    )
    AND EXISTS (
      SELECT 1
      FROM public.user_profiles u
      WHERE u.id = auth.uid()
        AND u.deactivated_at IS NULL
        AND u.role IN ('officer', 'admin_officer', 'admin', 'master', 'grand_master')
        AND (
          u.organization_id = p_provider_id
          OR (
            u.role IN ('admin_officer', 'admin', 'master', 'grand_master')
            AND public.is_admin_for_org(p_provider_id)
          )
          OR EXISTS (
            SELECT 1
            FROM public.staff_branch_authorisations b
            WHERE b.user_id = u.id
              AND b.branch_org_id = p_provider_id
              AND b.status = 'active'
              AND (b.starts_on IS NULL OR b.starts_on <= current_date)
              AND (b.ends_on IS NULL OR b.ends_on >= current_date)
          )
        )
    );
$function$;
REVOKE ALL ON FUNCTION "public"."field_place_provider_allowed"(p_provider_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."field_place_provider_allowed"(p_provider_id uuid) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."file_restricted_access_allowed"(p_organization_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS(
    SELECT 1 FROM public.user_profiles actor
    WHERE actor.id=auth.uid() AND actor.deactivated_at IS NULL
      AND actor.role IN('grand_master','master','admin', 'admin_officer')
      AND (
        actor.organization_id=p_organization_id
        OR actor.employer_organization_id=p_organization_id
        OR p_organization_id=ANY(public.get_descendant_organizations(coalesce(actor.employer_organization_id,actor.organization_id)))
      )
  );
$function$;
REVOKE ALL ON FUNCTION "public"."file_restricted_access_allowed"(p_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."file_restricted_access_allowed"(p_organization_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."file_restricted_access_allowed"(p_organization_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."file_restricted_access_allowed"(p_organization_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."file_space_access_allowed"(p_organization_id uuid, p_sensitivity text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT auth.uid() IS NOT NULL
    AND public.org_access_allowed(p_organization_id)
    AND (p_sensitivity <> 'restricted' OR public.file_restricted_access_allowed(p_organization_id));
$function$;
REVOKE ALL ON FUNCTION "public"."file_space_access_allowed"(p_organization_id uuid, p_sensitivity text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."file_space_access_allowed"(p_organization_id uuid, p_sensitivity text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."file_space_access_allowed"(p_organization_id uuid, p_sensitivity text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."file_space_access_allowed"(p_organization_id uuid, p_sensitivity text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."finalize_biosecurity_photo_inference"(p_assessment_id uuid, p_actor_user_id uuid, p_photo jsonb, p_species_id text, p_confidence real, p_recommendation text, p_checklist jsonb)
 RETURNS biosecurity_assessments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_assessment public.biosecurity_assessments%rowtype;
  v_actor public.user_profiles%rowtype;
  v_storage_path text := p_photo ->> 'storage_path';
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;

  SELECT * INTO v_actor
  FROM public.user_profiles
  WHERE id = p_actor_user_id;

  IF NOT FOUND OR v_actor.role::text NOT IN ('grand_master', 'master', 'admin', 'admin_officer', 'officer') THEN
    RAISE EXCEPTION 'Authorized actor required';
  END IF;

  SELECT * INTO v_assessment
  FROM public.biosecurity_assessments
  WHERE id = p_assessment_id
  FOR UPDATE;

  IF NOT FOUND OR v_assessment.organization_id IS DISTINCT FROM v_actor.organization_id THEN
    RAISE EXCEPTION 'Assessment not found';
  END IF;
  IF v_actor.role::text = 'officer'
     AND v_assessment.officer_user_id IS DISTINCT FROM p_actor_user_id
     AND v_assessment.officer_id IS DISTINCT FROM p_actor_user_id THEN
    RAISE EXCEPTION 'Officer does not own assessment';
  END IF;
  IF jsonb_typeof(p_photo) IS DISTINCT FROM 'object'
     OR COALESCE(p_photo ->> 'id', '') = ''
     OR COALESCE(p_photo ->> 'storage_bucket', '') <> 'scans'
     OR v_storage_path NOT LIKE 'org/' || v_assessment.organization_id::text || '/biosecurity/' || v_assessment.id::text || '/%' THEN
    RAISE EXCEPTION 'Invalid evidence reference';
  END IF;
  IF p_confidence < 0 OR p_confidence > 1 OR p_confidence IS NULL THEN
    RAISE EXCEPTION 'Invalid inference confidence';
  END IF;
  IF jsonb_typeof(p_checklist) IS DISTINCT FROM 'object'
     OR COALESCE(p_checklist ->> 'photo_id', '') <> p_photo ->> 'id' THEN
    RAISE EXCEPTION 'Invalid inference checklist';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(COALESCE(v_assessment.photo_urls, '[]'::jsonb)) AS existing_photo
    WHERE existing_photo ->> 'id' = p_photo ->> 'id'
  ) THEN
    RETURN v_assessment;
  END IF;

  UPDATE public.biosecurity_assessments
  SET photo_url = v_storage_path,
      photo_urls = COALESCE(photo_urls, '[]'::jsonb) || jsonb_build_array(p_photo),
      bob_species_id = NULLIF(BTRIM(p_species_id), ''),
      bob_confidence = p_confidence,
      bob_species_confirmed = false,
      bob_recommendation = NULLIF(BTRIM(p_recommendation), ''),
      bob_checklist = p_checklist
  WHERE id = v_assessment.id
  RETURNING * INTO v_assessment;

  INSERT INTO public.audit_log (
    organization_id,
    actor_user_id,
    action,
    target_table,
    target_id,
    metadata
  )
  VALUES (
    v_assessment.organization_id,
    p_actor_user_id,
    'biosecurity.photo_classified',
    'biosecurity_assessments',
    v_assessment.id,
    jsonb_build_object(
      'photo_id', p_photo ->> 'id',
      'model', p_checklist ->> 'model',
      'confidence', p_confidence,
      'manual_review_required', COALESCE((p_checklist ->> 'manual_review_required')::boolean, true)
    )
  );

  RETURN v_assessment;
END;
$function$;
COMMENT ON FUNCTION "public"."finalize_biosecurity_photo_inference"(p_assessment_id uuid, p_actor_user_id uuid, p_photo jsonb, p_species_id text, p_confidence real, p_recommendation text, p_checklist jsonb) IS 'Atomically appends tenant-scoped biosecurity photo evidence, stores advisory inference, and writes its audit event. Service identity only; never confirms species.';
REVOKE ALL ON FUNCTION "public"."finalize_biosecurity_photo_inference"(p_assessment_id uuid, p_actor_user_id uuid, p_photo jsonb, p_species_id text, p_confidence real, p_recommendation text, p_checklist jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."finalize_biosecurity_photo_inference"(p_assessment_id uuid, p_actor_user_id uuid, p_photo jsonb, p_species_id text, p_confidence real, p_recommendation text, p_checklist jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."finalize_biosecurity_photo_inference"(p_assessment_id uuid, p_actor_user_id uuid, p_photo jsonb, p_species_id text, p_confidence real, p_recommendation text, p_checklist jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."finalize_patrol_import_batch"(p_batch_id uuid, p_receipt jsonb)
 RETURNS file_import_batches
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_batch public.file_import_batches%rowtype;v_profile public.import_source_profiles%rowtype;
BEGIN
  SELECT * INTO v_batch FROM public.file_import_batches WHERE id=p_batch_id FOR UPDATE;
  IF NOT FOUND OR v_batch.status<>'staging' THEN RAISE EXCEPTION 'Open staging import batch required'; END IF;
  SELECT * INTO v_profile FROM public.import_source_profiles WHERE organization_id=v_batch.organization_id AND profile_code=v_batch.manifest_json->>'source_profile' AND active;
  IF NOT FOUND OR v_profile.import_actor_id IS NULL OR v_profile.import_actor_id<>auth.uid() OR v_batch.created_by<>auth.uid() THEN RAISE EXCEPTION 'Configured tenant import identity required'; END IF;
  RETURN public.finalize_patrol_import_batch_unvalidated(p_batch_id,p_receipt);
END;
$function$;
REVOKE ALL ON FUNCTION "public"."finalize_patrol_import_batch"(p_batch_id uuid, p_receipt jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."finalize_patrol_import_batch"(p_batch_id uuid, p_receipt jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."finalize_patrol_import_batch"(p_batch_id uuid, p_receipt jsonb) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."finalize_patrol_import_batch"(p_batch_id uuid, p_receipt jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."finalize_patrol_import_batch_unvalidated"(p_batch_id uuid, p_receipt jsonb)
 RETURNS file_import_batches
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_actor uuid := auth.uid(); v_batch public.file_import_batches%rowtype; v_expected integer; v_actual integer;
BEGIN
  SELECT * INTO v_batch FROM public.file_import_batches WHERE id = p_batch_id FOR UPDATE;
  IF NOT FOUND OR NOT public.is_tenant_import_admin(v_batch.organization_id) THEN RAISE EXCEPTION 'Tenant import batch is unavailable'; END IF;
  IF v_batch.status <> 'staging' THEN RAISE EXCEPTION 'Only a staging import can be finalized'; END IF;
  v_expected := coalesce((v_batch.manifest_json->>'expected_proposal_count')::integer, 0);
  SELECT count(*)::integer INTO v_actual FROM public.file_import_row_proposals WHERE batch_id = v_batch.id;
  IF v_actual <> v_expected THEN RAISE EXCEPTION 'Proposal staging is incomplete: expected %, found %', v_expected, v_actual; END IF;
  IF coalesce((p_receipt->>'direct_workshop_writes')::integer, -1) <> 0 OR coalesce((p_receipt->>'direct_finance_writes')::integer, -1) <> 0 THEN RAISE EXCEPTION 'Consequential import writes are not allowed'; END IF;
  UPDATE public.file_import_batches SET status='needs_review',manifest_json=manifest_json||jsonb_build_object('receipt',p_receipt),updated_at=clock_timestamp() WHERE id=v_batch.id RETURNING * INTO v_batch;
  INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) VALUES(v_batch.organization_id,v_actor,'patrol_import_staged_for_review','file_import_batches',v_batch.id,p_receipt);
  RETURN v_batch;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."finalize_patrol_import_batch_unvalidated"(p_batch_id uuid, p_receipt jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."finalize_patrol_import_batch_unvalidated"(p_batch_id uuid, p_receipt jsonb) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."finalize_report_pack_email_delivery"(p_pack_id uuid, p_delivery_attempt_id uuid, p_outcome text, p_sent_to text DEFAULT NULL::text, p_error text DEFAULT NULL::text, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_actor uuid := p_actor_user_id;
  v_pack public.monthly_report_packs%rowtype;
  v_now timestamptz := clock_timestamp();
begin
  if v_actor is null or p_delivery_attempt_id is null then raise exception 'Provider administrator and delivery attempt are required'; end if;
  if p_outcome not in ('sent', 'failed') then raise exception 'Delivery outcome must be sent or failed'; end if;
  select * into v_pack from public.monthly_report_packs where id = p_pack_id for update;
  if not found then raise exception 'Report pack not found'; end if;
  if not public.report_provider_custodian_for_actor(v_pack.organization_id, v_actor) then
    raise exception 'Provider administrator access required';
  end if;
  if v_pack.status = 'sent' and p_outcome = 'sent' then
    return jsonb_build_object('status', 'sent', 'sent_to', v_pack.sent_to, 'already_sent', true);
  end if;
  if v_pack.status <> 'generated' or v_pack.delivery_attempt_id is distinct from p_delivery_attempt_id then
    raise exception 'Report delivery claim no longer matches';
  end if;
  if p_outcome = 'sent'
     and (v_pack.delivery_recipient is null
          or lower(btrim(coalesce(p_sent_to, ''))) <> lower(v_pack.delivery_recipient)) then
    raise exception 'Sent delivery recipient must match the claimed recipient';
  end if;

  update public.monthly_report_packs
  set status = p_outcome,
      sent_at = case when p_outcome = 'sent' then v_now else null end,
      sent_to = case when p_outcome = 'sent' then v_pack.delivery_recipient else null end,
      delivery_error = case when p_outcome = 'failed' then coalesce(p_error, 'Email delivery failed') else null end,
      updated_at = v_now
  where id = p_pack_id;

  insert into public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (v_pack.organization_id, v_actor,
    case when p_outcome = 'sent' then 'monthly_report_pack_sent' else 'monthly_report_pack_send_failed' end,
    'monthly_report_packs', p_pack_id,
    jsonb_strip_nulls(jsonb_build_object('delivery_attempt_id', p_delivery_attempt_id, 'sent_to', v_pack.delivery_recipient, 'error', p_error)));
  return jsonb_build_object('status', p_outcome, 'sent_to', case when p_outcome = 'sent' then v_pack.delivery_recipient else null end);
end;
$function$;
REVOKE ALL ON FUNCTION "public"."finalize_report_pack_email_delivery"(p_pack_id uuid, p_delivery_attempt_id uuid, p_outcome text, p_sent_to text, p_error text, p_actor_user_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."finalize_report_pack_email_delivery"(p_pack_id uuid, p_delivery_attempt_id uuid, p_outcome text, p_sent_to text, p_error text, p_actor_user_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."finalize_report_pack_email_delivery"(p_pack_id uuid, p_delivery_attempt_id uuid, p_outcome text, p_sent_to text, p_error text, p_actor_user_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."finalize_shift_coverage"(p_request_id uuid, p_expected_status text, p_work_unit_id uuid, p_notes text DEFAULT NULL::text)
 RETURNS TABLE(request_id uuid, request_status text, roster_slot_id uuid, shift_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_request public.shift_coverage_requests%rowtype;v_staff public.staff_profiles%rowtype;v_unit public.roster_work_units%rowtype;v_slot public.roster_slots%rowtype;v_materialized record;v_shift_id uuid;v_start timestamptz;v_end timestamptz;
begin
  select r.* into v_request from public.shift_coverage_requests r where r.id=p_request_id for update;if not found then raise exception 'Coverage request not found';end if;
  if not public.is_admin_for_org(v_request.organization_id) then raise exception 'Active roster administrator required';end if;
  if v_request.status<>p_expected_status then raise exception 'Coverage request changed from expected status % to %',p_expected_status,v_request.status;end if;
  if v_request.status<>'claimed' or v_request.claimed_by is null then raise exception 'Only claimed coverage can be finalized';end if;
  select sp.* into v_staff from public.staff_profiles sp where sp.organization_id=v_request.organization_id and (sp.user_id=v_request.claimed_by or sp.id=v_request.claimed_by);if not found then raise exception 'Claimant staff profile not found';end if;
  select u.* into v_unit from public.roster_work_units u where u.id=p_work_unit_id and u.organization_id=v_request.organization_id and u.active;if not found then raise exception 'Active work unit in this organization required';end if;
  if v_request.patrol_route_id is not null and v_unit.patrol_route_id is distinct from v_request.patrol_route_id then raise exception 'Work unit does not match requested patrol route';end if;
  v_start:=(v_request.shift_date+v_request.start_time) at time zone 'Pacific/Auckland';v_end:=(v_request.shift_date+v_request.end_time) at time zone 'Pacific/Auckland';if v_end<=v_start then v_end:=v_end+interval '1 day';end if;
  select * into v_slot from public.create_roster_slot(v_request.id,v_unit.id,v_staff.id,v_start,v_end,true,concat_ws(E'\n',nullif(trim(coalesce(v_request.notes,'')),''),nullif(trim(coalesce(p_notes,'')),'')));
  if v_unit.work_unit_type in ('patrol', 'static') then select * into v_materialized from public.materialize_roster_slot(v_slot.id,'published');v_shift_id:=v_materialized.shift_id;end if;
  update public.shift_coverage_requests set status='filled',filled_at=clock_timestamp(),roster_slot_id=v_slot.id where id=v_request.id returning * into v_request;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_request.organization_id,v_actor,'shift_coverage_finalized','shift_coverage_requests',v_request.id,jsonb_build_object('claimed_by',v_request.claimed_by,'work_unit_id',v_unit.id,'roster_slot_id',v_slot.id,'shift_id',v_shift_id));
  perform public.enqueue_notification(p_organization_id=>v_request.organization_id,p_category=>'roster',p_title=>'Coverage assignment confirmed',p_body=>'Your claimed coverage is now a confirmed roster assignment.',p_severity=>'info',p_recipient_user_id=>v_request.claimed_by,p_link_page=>'schedule',p_link_payload=>jsonb_build_object('roster_slot_id',v_slot.id,'shift_id',v_shift_id),p_dedup_key=>'coverage_finalized:'||v_request.id::text);
  return query select v_request.id,v_request.status,v_slot.id,v_shift_id;
end;$function$;
REVOKE ALL ON FUNCTION "public"."finalize_shift_coverage"(p_request_id uuid, p_expected_status text, p_work_unit_id uuid, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."finalize_shift_coverage"(p_request_id uuid, p_expected_status text, p_work_unit_id uuid, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."finalize_shift_coverage"(p_request_id uuid, p_expected_status text, p_work_unit_id uuid, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."finalize_shift_coverage"(p_request_id uuid, p_expected_status text, p_work_unit_id uuid, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."finalize_smoke_photo_inference"(p_assessment_id uuid, p_actor_user_id uuid, p_analysis jsonb, p_summary text, p_confidence real, p_recommendation text)
 RETURNS smoke_assessments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_assessment public.smoke_assessments%rowtype;v_actor public.user_profiles%rowtype;
begin
  if auth.role() <> 'service_role' then raise exception 'Service identity required';end if;
  select * into v_actor from public.user_profiles where id=p_actor_user_id and deactivated_at is null;
  if not found or v_actor.role not in('grand_master','master','admin','admin_officer','officer') then raise exception 'Authorized actor required';end if;
  select * into v_assessment from public.smoke_assessments where id=p_assessment_id for update;
  if not found or v_assessment.organization_id is distinct from v_actor.organization_id then raise exception 'Assessment not found';end if;
  if v_actor.role='officer' and v_assessment.officer_user_id is distinct from p_actor_user_id then raise exception 'Officer does not own assessment';end if;
  if v_assessment.status<>'open' then raise exception 'Only open Smoke assessments can be classified';end if;
  if jsonb_typeof(p_analysis) is distinct from 'object' or coalesce((p_analysis->>'schema_version')::integer,0)<>1 or coalesce((p_analysis->>'images_analyzed')::integer,0) not between 1 and 3 or jsonb_typeof(p_analysis->'confidence_by_field') is distinct from 'object' or nullif(p_analysis->>'legal_use_boundary','') is null then raise exception 'Invalid Smoke inference analysis';end if;
  if p_confidence is null or p_confidence<0 or p_confidence>1 then raise exception 'Invalid inference confidence';end if;
  if v_assessment.smoke_ai_analysis is not null then return v_assessment;end if;
  update public.smoke_assessments set bob_classification=nullif(btrim(p_summary),''),bob_confidence=p_confidence,bob_recommendation=nullif(btrim(p_recommendation),''),smoke_ai_analysis=p_analysis,smoke_ai_analyzed_at=clock_timestamp() where id=v_assessment.id returning * into v_assessment;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_assessment.organization_id,p_actor_user_id,'smoke.photo_classified','smoke_assessments',v_assessment.id,jsonb_build_object('model',p_analysis->>'model','confidence',p_confidence,'manual_review_required',coalesce((p_analysis->>'manual_review_required')::boolean,true),'images_analyzed',(p_analysis->>'images_analyzed')::integer));
  return v_assessment;
end;$function$;
COMMENT ON FUNCTION "public"."finalize_smoke_photo_inference"(p_assessment_id uuid, p_actor_user_id uuid, p_analysis jsonb, p_summary text, p_confidence real, p_recommendation text) IS 'Atomically stores advisory visible-image Smoke analysis and audit. Service identity only; never determines legal breach or action.';
REVOKE ALL ON FUNCTION "public"."finalize_smoke_photo_inference"(p_assessment_id uuid, p_actor_user_id uuid, p_analysis jsonb, p_summary text, p_confidence real, p_recommendation text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."finalize_smoke_photo_inference"(p_assessment_id uuid, p_actor_user_id uuid, p_analysis jsonb, p_summary text, p_confidence real, p_recommendation text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."finalize_smoke_photo_inference"(p_assessment_id uuid, p_actor_user_id uuid, p_analysis jsonb, p_summary text, p_confidence real, p_recommendation text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."finance_service_cost_attribution_guard"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_agreement public.service_agreements%rowtype;
  v_period public.finance_pl_periods%rowtype;
  v_shift public.shifts%rowtype;
  v_work_unit public.roster_work_units%rowtype;
  v_linked_agreement_id uuid;
  v_work_unit_id uuid := NEW.work_unit_id;
BEGIN
  SELECT * INTO v_agreement
  FROM public.service_agreements
  WHERE id = NEW.service_agreement_id
    AND provider_organization_id = NEW.organization_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Service agreement is not owned by the finance organization'; END IF;
  IF NEW.client_organization_id IS DISTINCT FROM v_agreement.client_organization_id THEN
    RAISE EXCEPTION 'Finance cost client must match the selected service agreement';
  END IF;

  SELECT * INTO v_period
  FROM public.finance_pl_periods
  WHERE id = NEW.pl_period_id
    AND organization_id = NEW.organization_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'P&L period is not available in the finance organization'; END IF;
  IF v_period.status IN ('closed', 'archived') THEN
    RAISE EXCEPTION 'P&L period is unavailable for finance cost entry';
  END IF;
  IF nullif(trim(coalesce(NEW.source_reference, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Finance cost source reference is required';
  END IF;

  IF NEW.shift_id IS NOT NULL THEN
    SELECT * INTO v_shift
    FROM public.shifts
    WHERE id = NEW.shift_id
      AND organization_id = NEW.organization_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Shift is not available in the finance organization'; END IF;
    IF NEW.work_unit_id IS NOT NULL
      AND v_shift.work_unit_id IS NOT NULL
      AND NEW.work_unit_id IS DISTINCT FROM v_shift.work_unit_id THEN
      RAISE EXCEPTION 'Finance cost work unit must match the selected shift';
    END IF;
    v_work_unit_id := coalesce(v_work_unit_id, v_shift.work_unit_id);

    IF NEW.dispatch_job_id IS NULL THEN
      IF v_shift.service_agreement_location_id IS NOT NULL THEN
        SELECT service_agreement_id INTO v_linked_agreement_id
        FROM public.service_agreement_locations
        WHERE id = v_shift.service_agreement_location_id;
        IF NOT FOUND THEN RAISE EXCEPTION 'Shift location agreement could not be verified'; END IF;
        IF v_linked_agreement_id IS DISTINCT FROM NEW.service_agreement_id THEN
          RAISE EXCEPTION 'Finance cost agreement must match the shift location agreement';
        END IF;
      END IF;
      IF v_shift.service_agreement_module_id IS NOT NULL THEN
        SELECT service_agreement_id INTO v_linked_agreement_id
        FROM public.service_agreement_modules
        WHERE id = v_shift.service_agreement_module_id;
        IF NOT FOUND THEN RAISE EXCEPTION 'Shift module agreement could not be verified'; END IF;
        IF v_linked_agreement_id IS DISTINCT FROM NEW.service_agreement_id THEN
          RAISE EXCEPTION 'Finance cost agreement must match the shift module agreement';
        END IF;
      END IF;
    END IF;
  END IF;

  IF v_work_unit_id IS NOT NULL THEN
    SELECT * INTO v_work_unit
    FROM public.roster_work_units
    WHERE id = v_work_unit_id
      AND organization_id = NEW.organization_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Work unit is not available in the finance organization'; END IF;
    NEW.work_unit_id := v_work_unit_id;
    NEW.cost_centre_id := coalesce(NEW.cost_centre_id, v_work_unit.cost_centre_id);

    IF NEW.dispatch_job_id IS NULL THEN
      IF v_work_unit.service_agreement_location_id IS NOT NULL THEN
        SELECT service_agreement_id INTO v_linked_agreement_id
        FROM public.service_agreement_locations
        WHERE id = v_work_unit.service_agreement_location_id;
        IF NOT FOUND THEN RAISE EXCEPTION 'Work unit location agreement could not be verified'; END IF;
        IF v_linked_agreement_id IS DISTINCT FROM NEW.service_agreement_id THEN
          RAISE EXCEPTION 'Finance cost agreement must match the work unit location agreement';
        END IF;
      END IF;
      IF v_work_unit.service_agreement_module_id IS NOT NULL THEN
        SELECT service_agreement_id INTO v_linked_agreement_id
        FROM public.service_agreement_modules
        WHERE id = v_work_unit.service_agreement_module_id;
        IF NOT FOUND THEN RAISE EXCEPTION 'Work unit module agreement could not be verified'; END IF;
        IF v_linked_agreement_id IS DISTINCT FROM NEW.service_agreement_id THEN
          RAISE EXCEPTION 'Finance cost agreement must match the work unit module agreement';
        END IF;
      END IF;
    END IF;
  END IF;

  IF NEW.dispatch_job_id IS NOT NULL THEN
    SELECT service_agreement_id INTO v_linked_agreement_id
    FROM public.dispatch_jobs
    WHERE id = NEW.dispatch_job_id
      AND organization_id = NEW.organization_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Dispatch job is not available in the finance organization'; END IF;
    IF v_linked_agreement_id IS NOT NULL
      AND v_linked_agreement_id IS DISTINCT FROM NEW.service_agreement_id THEN
      RAISE EXCEPTION 'Finance cost agreement must match the dispatch job agreement';
    END IF;
  END IF;

  IF NEW.investigation_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.investigations
    WHERE id = NEW.investigation_id
      AND organization_id = NEW.organization_id
  ) THEN
    RAISE EXCEPTION 'Investigation is not available in the finance organization';
  END IF;

  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."finance_service_cost_attribution_guard"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."finance_service_cost_attribution_guard"() TO "postgres";

CREATE OR REPLACE FUNCTION "public"."find_cctv_portfolio_matches"(p_organization_id uuid, p_entity_kind text, p_face_embedding jsonb DEFAULT NULL::jsonb, p_appearance_embedding jsonb DEFAULT NULL::jsonb, p_plate text DEFAULT NULL::text, p_exclude_observation_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 10)
 RETURNS TABLE(match_kind text, match_id uuid, observation_id uuid, portfolio_key uuid, display_name text, score real, basis text, last_seen_at timestamp with time zone, canonical_place_id uuid, plate_number text, person_record_id uuid, canonical_vehicle_id uuid, thumbnail text, evidence_item_id uuid, cctv_import_id uuid)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_face public.vector;
  v_app public.vector;
  v_plate text;
  v_n integer := greatest(coalesce(p_limit, 10), 1);
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' AND session_user NOT IN ('postgres', 'supabase_admin')
     AND (auth.uid() IS NULL OR NOT public.org_access_allowed(p_organization_id)) THEN
    RAISE EXCEPTION 'CCTV portfolio access denied';
  END IF;
  IF p_entity_kind NOT IN ('person', 'vehicle', 'animal') THEN RAISE EXCEPTION 'Unknown entity kind %', p_entity_kind; END IF;
  v_face := public.cctv_jsonb_to_vector(p_face_embedding, 128);
  v_app := public.cctv_jsonb_to_vector(p_appearance_embedding, CASE WHEN p_entity_kind = 'vehicle' THEN 512 ELSE 256 END);
  v_plate := public.normalize_plate_number(p_plate);
  RETURN QUERY
  WITH face_hits AS (
    SELECT 'observation'::text AS match_kind, o.id AS match_id, o.id AS observation_id, o.portfolio_key,
           coalesce(pr.display_name, o.candidate_label)::text AS display_name,
           (1 - (o.face_vec <=> v_face))::real AS score, 'face'::text AS basis, o.observed_at AS last_seen_at,
           o.canonical_place_id, o.candidate_plate::text AS plate_number, o.person_record_id, o.canonical_vehicle_id,
           NULL::text AS thumbnail, o.evidence_item_id, o.cctv_import_id
    FROM public.cctv_entity_observations o
    LEFT JOIN public.person_records pr ON pr.id = o.person_record_id
    WHERE v_face IS NOT NULL AND p_entity_kind = 'person'
      AND o.organization_id = p_organization_id AND o.entity_kind = 'person' AND o.face_vec IS NOT NULL
      AND o.quality_state = 'clear' AND o.attributes->>'face_usable_for_matching' = 'true'
      AND o.review_state NOT IN ('rejected', 'superseded')
      AND (p_exclude_observation_id IS NULL OR o.id <> p_exclude_observation_id)
    ORDER BY o.face_vec <=> v_face LIMIT v_n * 3
  ), identity_face_hits AS (
    SELECT 'person_record'::text, t.id, NULL::uuid, NULL::uuid, pr.display_name::text,
           (1 - (t.face_vec <=> v_face))::real, 'face_identity'::text, t.approved_at,
           NULL::uuid, NULL::text, t.person_record_id, NULL::uuid, NULL::text, d.evidence_item_id, NULL::uuid
    FROM public.person_face_templates t
    JOIN public.person_records pr ON pr.id = t.person_record_id AND pr.organization_id = t.organization_id
    JOIN public.person_identity_documents d ON d.id = t.identity_document_id
    WHERE v_face IS NOT NULL AND p_entity_kind = 'person' AND t.organization_id = p_organization_id
    ORDER BY t.face_vec <=> v_face LIMIT v_n * 3
  ), legacy_face_hits AS (
    SELECT 'person_record'::text, fo.person_record_id, NULL::uuid, NULL::uuid, pr.display_name::text,
           public.face_embedding_cosine(fo.metadata->'embedding', p_face_embedding)::real, 'face_legacy'::text, fo.created_at,
           NULL::uuid, NULL::text, fo.person_record_id, NULL::uuid, NULL::text, NULL::uuid, NULL::uuid
    FROM public.face_observations fo JOIN public.person_records pr ON pr.id = fo.person_record_id
    WHERE p_face_embedding IS NOT NULL AND p_entity_kind = 'person'
      AND fo.organization_id = p_organization_id AND fo.metadata ? 'embedding' AND fo.review_state = 'accepted'
  ), appearance_hits AS (
    SELECT 'observation'::text, o.id, o.id, o.portfolio_key,
           coalesce(cv.plate_number, pr.display_name, o.candidate_label)::text,
           (1 - (o.appearance_vec <=> v_app))::real, 'appearance'::text, o.observed_at,
           o.canonical_place_id, coalesce(cv.plate_number, o.candidate_plate)::text, o.person_record_id, o.canonical_vehicle_id,
           NULL::text, o.evidence_item_id, o.cctv_import_id
    FROM public.cctv_entity_observations o
    LEFT JOIN public.canonical_vehicles cv ON cv.id = o.canonical_vehicle_id
    LEFT JOIN public.person_records pr ON pr.id = o.person_record_id
    WHERE v_app IS NOT NULL AND p_entity_kind <> 'vehicle'
      AND o.organization_id = p_organization_id AND o.entity_kind = p_entity_kind AND o.appearance_vec IS NOT NULL
      AND (o.entity_kind = 'animal' OR (
        o.quality_state = 'clear' AND o.attributes->>'appearance_embedding_usable' = 'true'
      ))
      AND o.review_state NOT IN ('rejected', 'superseded')
      AND (p_exclude_observation_id IS NULL OR o.id <> p_exclude_observation_id)
    ORDER BY o.appearance_vec <=> v_app LIMIT v_n * 3
  ), vehicle_appearance_hits AS (
    SELECT 'observation'::text, o.id, o.id, o.portfolio_key,
           coalesce(cv.plate_number, o.candidate_label)::text,
           (1 - (o.vehicle_appearance_vec <=> v_app))::real, 'appearance'::text, o.observed_at,
           o.canonical_place_id, coalesce(cv.plate_number, o.candidate_plate)::text, o.person_record_id, o.canonical_vehicle_id,
           NULL::text, o.evidence_item_id, o.cctv_import_id
    FROM public.cctv_entity_observations o
    LEFT JOIN public.canonical_vehicles cv ON cv.id = o.canonical_vehicle_id
    WHERE v_app IS NOT NULL AND p_entity_kind = 'vehicle'
      AND o.organization_id = p_organization_id AND o.entity_kind = 'vehicle'
      AND o.vehicle_appearance_vec IS NOT NULL AND o.quality_state = 'clear'
      AND o.attributes->>'appearance_embedding_usable' = 'true'
      AND o.attributes->>'appearance_embedding_model' = 'vehicle-reid-0001.onnx'
      AND o.review_state NOT IN ('rejected', 'superseded')
      AND (p_exclude_observation_id IS NULL OR o.id <> p_exclude_observation_id)
    ORDER BY o.vehicle_appearance_vec <=> v_app LIMIT v_n * 3
  ), plate_hits AS (
    SELECT 'canonical_vehicle'::text, cv.id, NULL::uuid, NULL::uuid,
           concat_ws(' ', cv.plate_number, cv.make, cv.model, cv.colour)::text,
           (CASE WHEN cv.plate_number = v_plate THEN 1.0 ELSE extensions.similarity(cv.plate_number, v_plate) END)::real,
           (CASE WHEN cv.plate_number = v_plate THEN 'plate_exact' ELSE 'plate_similar' END)::text, cv.last_seen_at,
           NULL::uuid, cv.plate_number::text, NULL::uuid, cv.id, NULL::text, NULL::uuid, NULL::uuid
    FROM public.canonical_vehicles cv
    WHERE v_plate IS NOT NULL AND p_entity_kind = 'vehicle'
      AND (cv.plate_number = v_plate OR extensions.similarity(cv.plate_number, v_plate) >= 0.6)
    ORDER BY (cv.plate_number = v_plate) DESC, extensions.similarity(cv.plate_number, v_plate) DESC LIMIT v_n
  ), all_hits AS (
    SELECT * FROM face_hits UNION ALL SELECT * FROM identity_face_hits UNION ALL SELECT * FROM legacy_face_hits
    UNION ALL SELECT * FROM appearance_hits UNION ALL SELECT * FROM vehicle_appearance_hits UNION ALL SELECT * FROM plate_hits
  )
  SELECT h.match_kind, h.match_id, h.observation_id, h.portfolio_key, h.display_name, h.score, h.basis,
         h.last_seen_at, h.canonical_place_id, h.plate_number, h.person_record_id, h.canonical_vehicle_id,
         h.thumbnail, h.evidence_item_id, h.cctv_import_id
  FROM all_hits h
  WHERE h.score >= CASE h.basis WHEN 'face' THEN 0.65 WHEN 'face_identity' THEN 0.65 WHEN 'face_legacy' THEN 0.65 WHEN 'appearance' THEN 0.70 ELSE 0.60 END
  ORDER BY h.score DESC, h.last_seen_at DESC NULLS LAST LIMIT v_n;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."find_cctv_portfolio_matches"(p_organization_id uuid, p_entity_kind text, p_face_embedding jsonb, p_appearance_embedding jsonb, p_plate text, p_exclude_observation_id uuid, p_limit integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."find_cctv_portfolio_matches"(p_organization_id uuid, p_entity_kind text, p_face_embedding jsonb, p_appearance_embedding jsonb, p_plate text, p_exclude_observation_id uuid, p_limit integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."find_cctv_portfolio_matches"(p_organization_id uuid, p_entity_kind text, p_face_embedding jsonb, p_appearance_embedding jsonb, p_plate text, p_exclude_observation_id uuid, p_limit integer) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."find_cctv_portfolio_matches"(p_organization_id uuid, p_entity_kind text, p_face_embedding jsonb, p_appearance_embedding jsonb, p_plate text, p_exclude_observation_id uuid, p_limit integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."find_crm_location_candidates"(p_account_organization_id uuid, p_query text DEFAULT NULL::text, p_address text DEFAULT NULL::text)
 RETURNS TABLE(location_id uuid, name text, address text, suburb text, postcode text, site_count integer, zone_count integer, boundary_state text, match_reason text, belongs_to_account boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_provider uuid;
  v_query text := lower(trim(coalesce(p_query, '')));
  v_address_key text := nullif(regexp_replace(lower(trim(coalesce(p_address, ''))), '[^a-z0-9]+', '', 'g'), '');
BEGIN
  SELECT profile.organization_id INTO v_provider FROM public.user_profiles AS profile WHERE profile.id = v_actor AND profile.deactivated_at IS NULL;
  IF v_provider IS NULL OR NOT public.is_admin_for_org(v_provider) OR NOT public.crm_actor_can_manage_account(p_account_organization_id) THEN RAISE EXCEPTION 'Active CRM administrator required for this organization'; END IF;
  IF char_length(v_query) < 2 AND coalesce(char_length(v_address_key), 0) < 4 THEN RAISE EXCEPTION 'Enter a location name or complete address to search'; END IF;

  RETURN QUERY
  WITH matches AS (
    SELECT location.id, location.organization_id, location.name, location.address, location.suburb, location.postcode,
      CASE WHEN v_address_key IS NOT NULL AND location.address_match_key = v_address_key THEN 0 WHEN lower(location.name) = v_query THEN 1 ELSE 2 END AS match_rank
    FROM public.locations AS location
    WHERE (v_address_key IS NOT NULL AND location.address_match_key = v_address_key)
       OR (char_length(v_query) >= 2 AND lower(location.name) LIKE '%' || v_query || '%')
  )
  SELECT match.id, match.name, match.address, match.suburb, match.postcode,
    (SELECT count(*)::integer FROM public.client_sites AS site WHERE site.location_id = match.id),
    (SELECT count(*)::integer FROM public.location_zones AS zone WHERE zone.location_id = match.id),
    CASE WHEN EXISTS (SELECT 1 FROM public.client_sites AS site WHERE site.location_id = match.id AND site.boundary_verification = 'verified') OR EXISTS (SELECT 1 FROM public.location_zones AS zone WHERE zone.location_id = match.id AND zone.boundary_verification = 'verified') THEN 'verified geometry available' WHEN EXISTS (SELECT 1 FROM public.client_sites AS site WHERE site.location_id = match.id AND site.boundary IS NOT NULL) OR EXISTS (SELECT 1 FROM public.location_zones AS zone WHERE zone.location_id = match.id AND zone.boundary IS NOT NULL) THEN 'geometry requires review' ELSE 'no geometry recorded' END,
    CASE match.match_rank WHEN 0 THEN 'Exact address match' WHEN 1 THEN 'Exact location name' ELSE 'Similar location name' END,
    match.organization_id = p_account_organization_id
  FROM matches AS match
  ORDER BY match.match_rank, match.name
  LIMIT 20;
END; $function$;
REVOKE ALL ON FUNCTION "public"."find_crm_location_candidates"(p_account_organization_id uuid, p_query text, p_address text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."find_crm_location_candidates"(p_account_organization_id uuid, p_query text, p_address text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."find_crm_location_candidates"(p_account_organization_id uuid, p_query text, p_address text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."find_crm_location_candidates"(p_account_organization_id uuid, p_query text, p_address text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."find_crm_organization_candidates"(p_query text, p_nzbn text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, name text, organization_type text, status text, nzbn text, parent_organization_id uuid, match_reason text, manageable boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_provider uuid;
  v_query text := lower(trim(coalesce(p_query, '')));
  v_nzbn text := nullif(regexp_replace(coalesce(p_nzbn, ''), '[^0-9]', '', 'g'), '');
begin
  select profile.organization_id into v_provider from public.user_profiles profile where profile.id = v_actor and profile.deactivated_at is null;
  if v_provider is null or not public.is_admin_for_org(v_provider) then raise exception 'Active CRM administrator required'; end if;
  if char_length(v_query) < 2 and v_nzbn is null then raise exception 'Enter at least two search characters or an NZBN'; end if;

  return query
  with matches as (
    select organization.*,
      case
        when v_nzbn is not null and regexp_replace(coalesce(organization.nzbn, ''), '[^0-9]', '', 'g') = v_nzbn then 0
        when lower(trim(organization.name)) = v_query then 1
        when lower(organization.name) like '%' || v_query || '%' then 2
        when exists (select 1 from public.client_sites site where site.client_organization_id = organization.id and (lower(site.name) like '%' || v_query || '%' or lower(coalesce(site.address, '')) like '%' || v_query || '%')) then 3
        when exists (select 1 from public.locations location where location.organization_id = organization.id and (lower(location.name) like '%' || v_query || '%' or lower(coalesce(location.address, '')) like '%' || v_query || '%')) then 4
        when extensions.word_similarity(v_query, lower(organization.name)) >= 0.5 then 5
        else 99
      end as match_rank
    from public.organizations organization
  )
  select match.id, match.name, match.organization_type, match.status, match.nzbn, match.parent_organization_id,
    case match.match_rank
      when 0 then 'Exact NZBN'
      when 1 then 'Exact organization name'
      when 2 then 'Name contains search'
      when 3 then 'Matched owned site'
      when 4 then 'Matched owned location'
      else 'Similar organization name'
    end,
    coalesce(match.id = v_provider or match.parent_organization_id = v_provider or public.crm_actor_can_manage_account(match.id), false)
  from matches match
  where match.match_rank < 99
  order by match.match_rank, case when match.match_rank = 5 then extensions.word_similarity(v_query, lower(match.name)) else 1 end desc, match.name
  limit 20;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."find_crm_organization_candidates"(p_query text, p_nzbn text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."find_crm_organization_candidates"(p_query text, p_nzbn text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."find_crm_organization_candidates"(p_query text, p_nzbn text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."find_crm_organization_candidates"(p_query text, p_nzbn text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."find_crm_site_candidates"(p_account_organization_id uuid, p_query text DEFAULT NULL::text, p_address text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, name text, address text, site_type text, active boolean, boundary_status text, boundary_verification text, match_reason text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_query text:=lower(trim(coalesce(p_query,'')));v_address_key text:=regexp_replace(lower(trim(coalesce(p_address,''))),'[^a-z0-9]+','','g');
begin
  if v_actor is null or not public.crm_actor_can_manage_account(p_account_organization_id) then raise exception 'Not authorised to review sites for this CRM account';end if;
  if char_length(v_query)<2 and char_length(v_address_key)<4 then raise exception 'Enter at least two name characters or a complete address';end if;
  return query select s.id,s.name,s.address,s.site_type,s.active,s.boundary_status,s.boundary_verification,
    case when char_length(v_address_key)>=4 and s.address_match_key=v_address_key then 'Exact address' when lower(trim(s.name))=v_query then 'Exact name' else 'Similar site' end
  from public.client_sites s
  where s.client_organization_id=p_account_organization_id
    and ((char_length(v_query)>=2 and lower(s.name) like '%'||v_query||'%') or (char_length(v_address_key)>=4 and s.address_match_key=v_address_key))
  order by case when char_length(v_address_key)>=4 and s.address_match_key=v_address_key then 0 when lower(trim(s.name))=v_query then 1 else 2 end,s.name limit 20;
end;$function$;
REVOKE ALL ON FUNCTION "public"."find_crm_site_candidates"(p_account_organization_id uuid, p_query text, p_address text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."find_crm_site_candidates"(p_account_organization_id uuid, p_query text, p_address text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."find_crm_site_candidates"(p_account_organization_id uuid, p_query text, p_address text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."find_crm_site_candidates"(p_account_organization_id uuid, p_query text, p_address text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."find_existing_cctv_media_by_hash"(p_import_id uuid, p_sha256 text, p_evidence_kind text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_actor uuid:=auth.uid();v_import public.cctv_imports%rowtype;v_evidence public.evidence_items%rowtype;v_job_status text;v_hash text:=lower(trim(coalesce(p_sha256,'')));
BEGIN
  SELECT * INTO v_import FROM public.cctv_imports WHERE id=p_import_id;
  IF v_import.id IS NULL THEN RAISE EXCEPTION 'CCTV import not found';END IF;
  IF v_actor IS NULL OR NOT public.org_access_allowed(v_import.organization_id) THEN RAISE EXCEPTION 'CCTV import access denied';END IF;
  IF p_evidence_kind NOT IN('video','photo') OR v_hash !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'Valid CCTV media kind and SHA-256 are required';END IF;
  SELECT evidence.* INTO v_evidence FROM public.evidence_items evidence
  WHERE evidence.organization_id=v_import.organization_id AND evidence.evidence_kind=p_evidence_kind AND lower(evidence.sha256_hash)=v_hash
  ORDER BY evidence.captured_at,evidence.id LIMIT 1;
  IF v_evidence.id IS NULL THEN RETURN jsonb_build_object('found',false);END IF;
  SELECT status INTO v_job_status FROM public.inference_jobs WHERE evidence_item_id=v_evidence.id AND domain='video_motion' ORDER BY created_at DESC LIMIT 1;
  RETURN jsonb_build_object('found',true,'evidence_item_id',v_evidence.id,'cctv_import_id',v_evidence.cctv_import_id,'storage_path',v_evidence.storage_path,'file_name',v_evidence.metadata->>'file_name','inference_status',v_job_status);
END;
$function$;
COMMENT ON FUNCTION "public"."find_existing_cctv_media_by_hash"(p_import_id uuid, p_sha256 text, p_evidence_kind text) IS 'Tenant-scoped pre-review hash check. Returns only an existing evidence receipt and storage path, never media content.';
REVOKE ALL ON FUNCTION "public"."find_existing_cctv_media_by_hash"(p_import_id uuid, p_sha256 text, p_evidence_kind text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."find_existing_cctv_media_by_hash"(p_import_id uuid, p_sha256 text, p_evidence_kind text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."find_existing_cctv_media_by_hash"(p_import_id uuid, p_sha256 text, p_evidence_kind text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."find_existing_cctv_media_by_hash"(p_import_id uuid, p_sha256 text, p_evidence_kind text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."find_existing_site_for_address"(p_organization_id uuid, p_address text, p_lat double precision, p_lng double precision)
 RETURNS TABLE(site_id uuid, site_name text, address text, client_organization_id uuid, match_reason text, distance_m double precision, has_boundary boolean, boundary_verification text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_key text := nullif(regexp_replace(lower(trim(coalesce(p_address, ''))), '[^a-z0-9]+', '', 'g'), '');
  v_point geometry;
BEGIN
  IF auth.uid() IS NULL OR NOT public.org_access_allowed(p_organization_id) THEN
    RAISE EXCEPTION 'Organization access denied';
  END IF;
  IF p_lat IS NOT NULL AND p_lng IS NOT NULL THEN
    v_point := ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326);
  END IF;
  RETURN QUERY
  SELECT s.id, s.name, s.address, s.client_organization_id,
    CASE WHEN v_key IS NOT NULL AND s.address_match_key = v_key THEN 'exact_address' ELSE 'within_50m' END,
    CASE WHEN v_point IS NULL OR s.center_point IS NULL THEN NULL
         ELSE ST_Distance(s.center_point::geography, v_point::geography) END,
    s.boundary IS NOT NULL,
    s.boundary_verification
  FROM public.client_sites s
  WHERE public.org_access_allowed(s.client_organization_id)
    AND ((v_key IS NOT NULL AND s.address_match_key = v_key)
      OR (v_point IS NOT NULL AND s.center_point IS NOT NULL
          AND ST_DWithin(s.center_point::geography, v_point::geography, 50)))
  ORDER BY CASE WHEN v_key IS NOT NULL AND s.address_match_key = v_key THEN 0 ELSE 1 END,
           ST_Distance(s.center_point::geography, v_point::geography) NULLS LAST
  LIMIT 5;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."find_existing_site_for_address"(p_organization_id uuid, p_address text, p_lat double precision, p_lng double precision) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."find_existing_site_for_address"(p_organization_id uuid, p_address text, p_lat double precision, p_lng double precision) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."find_existing_site_for_address"(p_organization_id uuid, p_address text, p_lat double precision, p_lng double precision) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."find_existing_site_for_address"(p_organization_id uuid, p_address text, p_lat double precision, p_lng double precision) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."find_person_matches"(p_organization_id uuid, p_name text DEFAULT NULL::text, p_date_of_birth date DEFAULT NULL::date, p_licence_number text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_exclude_person_record_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 8)
 RETURNS TABLE(person_record_id uuid, display_name text, review_state text, matched_name text, match_basis text, score real, strength text, aliases text[], locality text, origin text, sighting_count bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_phone text := nullif(regexp_replace(coalesce(p_phone, ''), '[^0-9]', '', 'g'), '');
  v_email text := nullif(lower(trim(coalesce(p_email, ''))), '');
  v_contacts boolean := public.can_access_person_contacts(p_organization_id);
BEGIN
  IF auth.uid() IS NULL OR p_organization_id IS NULL OR NOT public.org_access_allowed(p_organization_id)
    OR NOT (public.can_search_people(p_organization_id) OR public.can_access_vehicle_owner_identity(p_organization_id)) THEN
    RAISE EXCEPTION 'Person-search or vehicle-owner authorization required' USING ERRCODE = '42501';
  END IF;
  IF NOT v_contacts AND (v_phone IS NOT NULL OR v_email IS NOT NULL) THEN
    RAISE EXCEPTION 'Contact-detail matching requires an operations administrator' USING ERRCODE = '42501';
  END IF;
  IF public.normalize_person_name(p_name) IS NULL
    AND nullif(upper(regexp_replace(coalesce(p_licence_number, ''), '[^A-Za-z0-9]', '', 'g')), '') IS NULL
    AND (v_phone IS NULL OR length(v_phone) < 7) AND v_email IS NULL THEN
    RAISE EXCEPTION 'Enter a name or an authorized identity detail to match';
  END IF;
  RETURN QUERY SELECT * FROM public._match_person_records(p_organization_id, p_name, p_date_of_birth,
    p_licence_number, p_phone, p_email, p_exclude_person_record_id, p_limit, v_contacts);
END;
$function$;
COMMENT ON FUNCTION "public"."find_person_matches"(p_organization_id uuid, p_name text, p_date_of_birth date, p_licence_number text, p_phone text, p_email text, p_exclude_person_record_id uuid, p_limit integer) IS 'Duplicate-prevention matching for authorized person-search or vehicle-owner users. Contact matching and returned locality are operations-administrator-only. No private contact values are returned.';
REVOKE ALL ON FUNCTION "public"."find_person_matches"(p_organization_id uuid, p_name text, p_date_of_birth date, p_licence_number text, p_phone text, p_email text, p_exclude_person_record_id uuid, p_limit integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."find_person_matches"(p_organization_id uuid, p_name text, p_date_of_birth date, p_licence_number text, p_phone text, p_email text, p_exclude_person_record_id uuid, p_limit integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."find_person_matches"(p_organization_id uuid, p_name text, p_date_of_birth date, p_licence_number text, p_phone text, p_email text, p_exclude_person_record_id uuid, p_limit integer) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."generate_crm_invoice_from_agreement"(p_client_request_id uuid, p_service_agreement_id uuid, p_service_period_start date, p_service_period_end date, p_overrun_decision text DEFAULT NULL::text, p_overrun_justification text DEFAULT NULL::text)
 RETURNS TABLE(invoice_id uuid, invoice_number text, client_organization_id uuid, subtotal numeric, gst_amount numeric, total_amount numeric, line_item_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_agreement public.service_agreements%ROWTYPE;
  v_invoice public.invoices%ROWTYPE;
  v_inv_number text;
  v_count integer := 0;
  v_qline record;
  v_comm public.crm_commercial_settings%ROWTYPE;
  v_drawdown jsonb;
  v_settlement public.agreement_fee_settlements%ROWTYPE;
  v_fee numeric(12,2);
  v_work numeric(12,2);
  v_balance numeric(12,2);
  v_policy text;
  v_decision text := nullif(btrim(coalesce(p_overrun_decision, '')), '');
  v_justification text := nullif(btrim(coalesce(p_overrun_justification, '')), '');
  v_outcome text;
  v_adjustment numeric(12,2) := 0;
  v_label text;
  v_money_fee text;
  v_money_work text;
BEGIN
  IF p_client_request_id IS NULL THEN RAISE EXCEPTION 'client_request_id is required'; END IF;
  SELECT * INTO v_agreement FROM public.service_agreements WHERE id = p_service_agreement_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Service agreement not found'; END IF;
  IF NOT public.is_admin_for_org(v_agreement.provider_organization_id) THEN RAISE EXCEPTION 'Not authorised to invoice for this agreement'; END IF;
  IF p_service_period_start IS NULL OR p_service_period_end IS NULL THEN RAISE EXCEPTION 'Choose the service period'; END IF;
  IF p_service_period_end < p_service_period_start THEN RAISE EXCEPTION 'Service period end cannot precede service period start'; END IF;
  IF v_decision IS NOT NULL AND v_decision NOT IN ('bill_as_extra', 'absorb') THEN
    RAISE EXCEPTION 'Work above the monthly fee is either billed as Extra or absorbed';
  END IF;
  SELECT * INTO v_comm FROM public.crm_commercial_settings WHERE service_agreement_id = v_agreement.id;

  IF coalesce(v_comm.commercial_model, '') = 'fixed_price_with_extras' THEN
    IF p_service_period_start <> date_trunc('month', p_service_period_start)::date
       OR p_service_period_end <> (date_trunc('month', p_service_period_start) + interval '1 month - 1 day')::date THEN
      RAISE EXCEPTION 'A fixed monthly fee is settled one whole calendar month at a time';
    END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended('agreement_fee_settlement:' || v_agreement.id::text || ':' || p_service_period_start::text, 0));

    -- Same request again: return the invoice it already made.
    SELECT s.* INTO v_settlement FROM public.agreement_fee_settlements s
    WHERE s.service_agreement_id = v_agreement.id AND s.period_start = p_service_period_start AND s.client_request_id = p_client_request_id;
    IF FOUND THEN
      RETURN QUERY SELECT i.id, i.invoice_number, i.client_organization_id, i.subtotal, i.gst_amount, i.total_amount,
        (SELECT count(*)::integer FROM public.invoice_line_items li WHERE li.invoice_id = i.id)
      FROM public.invoices i WHERE i.id = v_settlement.invoice_id;
      RETURN;
    END IF;

    v_drawdown := public.agreement_fee_drawdown_month(v_agreement.id, p_service_period_start);
    IF v_drawdown->'settlement' <> 'null'::jsonb THEN
      RAISE EXCEPTION '% is already settled on invoice % (%). Void that invoice to settle the month again.',
        v_drawdown->>'label', v_drawdown->'settlement'->>'invoice_number', v_drawdown->'settlement'->>'invoice_status';
    END IF;
    IF jsonb_array_length(v_drawdown->'blockers') > 0 THEN
      RAISE EXCEPTION '%', v_drawdown->'blockers'->0->>'message';
    END IF;
    -- A voided settlement frees the month.
    DELETE FROM public.agreement_fee_settlements s
    WHERE s.service_agreement_id = v_agreement.id AND s.period_start = p_service_period_start;

    v_fee := (v_drawdown->>'fee')::numeric;
    v_work := (v_drawdown->'contract_work'->>'total')::numeric;
    v_balance := v_fee - v_work;
    v_policy := v_drawdown->>'overrun_policy';
    v_label := v_drawdown->>'label';
    v_money_fee := to_char(v_fee, 'FM$999,999,990.00');
    v_money_work := to_char(v_work, 'FM$999,999,990.00');

    IF v_balance > 0 THEN
      v_outcome := 'credit'; v_adjustment := -v_balance; v_decision := NULL; v_justification := NULL;
    ELSIF v_balance = 0 THEN
      v_outcome := 'balanced'; v_decision := NULL; v_justification := NULL;
    ELSE
      v_decision := coalesce(v_decision, CASE WHEN v_policy = 'bill_as_extra' THEN 'bill_as_extra' END);
      IF v_decision IS NULL THEN
        RAISE EXCEPTION 'Contracted work in % (%) is % above the monthly fee (%). Bill the excess as Extra with a justification, or absorb it.',
          v_label, v_money_work, to_char(-v_balance, 'FM$999,999,990.00'), v_money_fee;
      END IF;
      IF v_decision = 'bill_as_extra' THEN
        IF v_policy <> 'bill_as_extra' AND char_length(coalesce(v_justification, '')) NOT BETWEEN 10 AND 500 THEN
          RAISE EXCEPTION 'Say why the client should pay for work above the monthly fee (10 to 500 characters)';
        END IF;
        v_outcome := 'overrun_billed'; v_adjustment := -v_balance;
      ELSE
        v_outcome := 'overrun_absorbed';
      END IF;
      IF v_justification IS NOT NULL AND char_length(v_justification) NOT BETWEEN 10 AND 500 THEN
        RAISE EXCEPTION 'A justification is 10 to 500 characters';
      END IF;
    END IF;
  ELSIF v_decision IS NOT NULL OR v_justification IS NOT NULL THEN
    RAISE EXCEPTION 'Only a fixed price plus Extra agreement settles work against a monthly fee';
  END IF;

  SELECT 'INV-'||to_char(now(),'YYYYMMDD')||'-'||upper(substring(gen_random_uuid()::text,1,4)) INTO v_inv_number;
  INSERT INTO public.invoices(organization_id,client_organization_id,service_agreement_id,invoice_number,invoice_date,due_date,status,service_period_start,service_period_end,created_by)
  VALUES(v_agreement.provider_organization_id,v_agreement.client_organization_id,v_agreement.id,v_inv_number,current_date,public.invoice_due_date(current_date,p_service_period_end,v_comm.payment_terms_days,v_comm.payment_due_day_of_month),'draft',p_service_period_start,p_service_period_end,v_actor) RETURNING * INTO v_invoice;
  FOR v_qline IN SELECT line.description,line.quantity,line.unit_charge FROM public.quotes quote JOIN public.quote_lines line ON line.quote_id=quote.id WHERE quote.service_agreement_id=v_agreement.id AND quote.status='accepted' ORDER BY line.line_order, line.created_at LOOP
    v_count:=v_count+1; INSERT INTO public.invoice_line_items(invoice_id,line_number,description,quantity,unit_price,line_total,organization_id) VALUES(v_invoice.id,v_count,v_qline.description,v_qline.quantity,v_qline.unit_charge,round(v_qline.quantity*v_qline.unit_charge,2),v_invoice.organization_id);
  END LOOP;
  IF v_count=0 THEN
    IF v_comm.id IS NOT NULL AND v_comm.base_rate_per_hour IS NOT NULL AND v_comm.base_rate_per_hour>0 THEN
      v_count:=1; INSERT INTO public.invoice_line_items(invoice_id,line_number,description,quantity,unit_price,line_total,organization_id) VALUES(v_invoice.id,1,'Service Agreement Base Retainer',1,v_comm.base_rate_per_hour,v_comm.base_rate_per_hour,v_invoice.organization_id);
    ELSE RAISE EXCEPTION 'Commercial configuration incomplete: an accepted quote line or positive agreement rate is required before invoicing'; END IF;
  END IF;

  IF v_outcome IS NOT NULL THEN
    IF v_outcome = 'credit' THEN
      v_count := v_count + 1;
      INSERT INTO public.invoice_line_items(invoice_id,line_number,description,quantity,unit_price,line_total,organization_id)
      VALUES (v_invoice.id, v_count,
        format('Credit — contracted work not used in %s (monthly fee %s, contracted work done %s)', v_label, v_money_fee, v_money_work),
        1, v_adjustment, v_adjustment, v_invoice.organization_id);
    ELSIF v_outcome = 'overrun_billed' THEN
      v_count := v_count + 1;
      INSERT INTO public.invoice_line_items(invoice_id,line_number,description,quantity,unit_price,line_total,organization_id)
      VALUES (v_invoice.id, v_count,
        format('Extra — contracted work above the monthly fee in %s (monthly fee %s, contracted work done %s)', v_label, v_money_fee, v_money_work)
          || CASE WHEN v_justification IS NOT NULL THEN ' — ' || v_justification
                  WHEN v_policy = 'bill_as_extra' THEN ' — as agreed with the client' ELSE '' END,
        1, v_adjustment, v_adjustment, v_invoice.organization_id);
    END IF;
    INSERT INTO public.agreement_fee_settlements (organization_id, client_organization_id, service_agreement_id, period_start, period_end,
      fee_amount, imported_contract_amount, callout_contract_amount, patrol_visit_amount, contract_work_amount, balance, outcome,
      adjustment_amount, overrun_policy, overrun_decision, justification, invoice_id, client_request_id, created_by)
    VALUES (v_agreement.provider_organization_id, v_agreement.client_organization_id, v_agreement.id, p_service_period_start, p_service_period_end,
      v_fee, (v_drawdown->'contract_work'->'imported'->>'amount')::numeric, (v_drawdown->'contract_work'->'callouts'->>'amount')::numeric,
      (v_drawdown->'contract_work'->'patrol_visits'->>'amount')::numeric, v_work, v_balance, v_outcome,
      v_adjustment, v_policy, v_decision, v_justification, v_invoice.id, p_client_request_id, v_actor)
    RETURNING * INTO v_settlement;
  END IF;

  UPDATE public.invoices invoice SET subtotal=totals.subtotal,gst_amount=round(totals.subtotal*.15,2),total_amount=round(totals.subtotal*1.15,2),updated_at=now() FROM (SELECT coalesce(sum(line.line_total),0)::numeric(12,2) subtotal FROM public.invoice_line_items line WHERE line.invoice_id=v_invoice.id) totals WHERE invoice.id=v_invoice.id RETURNING invoice.* INTO v_invoice;
  INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) VALUES(v_invoice.organization_id,v_actor,'crm_invoice_generated_from_agreement','invoices',v_invoice.id,
    jsonb_strip_nulls(jsonb_build_object('service_agreement_id',v_agreement.id,'invoice_number',v_invoice.invoice_number,'subtotal',v_invoice.subtotal,'total_amount',v_invoice.total_amount,'line_item_count',v_count,'client_request_id',p_client_request_id,'due_date',v_invoice.due_date,
      'fee_drawdown', CASE WHEN v_outcome IS NOT NULL THEN jsonb_build_object('settlement_id', v_settlement.id, 'month', v_drawdown->>'month',
        'fee', v_fee, 'contract_work', v_drawdown->'contract_work', 'balance', v_balance, 'outcome', v_outcome,
        'adjustment_amount', v_adjustment, 'overrun_policy', v_policy, 'overrun_decision', v_decision, 'justification', v_justification) END)));
  RETURN QUERY SELECT v_invoice.id,v_invoice.invoice_number,v_invoice.client_organization_id,v_invoice.subtotal,v_invoice.gst_amount,v_invoice.total_amount,v_count;
EXCEPTION WHEN OTHERS THEN
  IF v_invoice.id IS NOT NULL THEN DELETE FROM public.invoices WHERE id=v_invoice.id; END IF;
  RAISE;
END; $function$;
COMMENT ON FUNCTION "public"."generate_crm_invoice_from_agreement"(p_client_request_id uuid, p_service_agreement_id uuid, p_service_period_start date, p_service_period_end date, p_overrun_decision text, p_overrun_justification text) IS 'Provider administrator raises the agreement-price invoice (accepted quote lines, else the agreement rate as a base retainer), due by the agreement payment terms. For fixed price plus Extra the period is one whole calendar month and the invoice settles the monthly fee drawdown (agreement_fee_drawdown_month): unused contract value is credited as a negative line; contracted work above the fee is billed as an Extra line when the agreement pre-agrees it (fee_overrun_policy bill_as_extra) or with a 10-500 character justification, otherwise it must be explicitly absorbed. Refuses an unfinished, undecided, unpriced or already settled month. Writes agreement_fee_settlements; idempotent on client_request_id for a settled month; audited.';
REVOKE ALL ON FUNCTION "public"."generate_crm_invoice_from_agreement"(p_client_request_id uuid, p_service_agreement_id uuid, p_service_period_start date, p_service_period_end date, p_overrun_decision text, p_overrun_justification text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."generate_crm_invoice_from_agreement"(p_client_request_id uuid, p_service_agreement_id uuid, p_service_period_start date, p_service_period_end date, p_overrun_decision text, p_overrun_justification text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."generate_crm_invoice_from_agreement"(p_client_request_id uuid, p_service_agreement_id uuid, p_service_period_start date, p_service_period_end date, p_overrun_decision text, p_overrun_justification text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."generate_crm_invoice_from_agreement"(p_client_request_id uuid, p_service_agreement_id uuid, p_service_period_start date, p_service_period_end date, p_overrun_decision text, p_overrun_justification text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."generate_crm_invoice_from_completed_work"(p_client_request_id uuid, p_organization_id uuid, p_client_organization_id uuid, p_service_agreement_id uuid DEFAULT NULL::uuid, p_period_start date DEFAULT NULL::date, p_period_end date DEFAULT NULL::date)
 RETURNS invoices
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_invoice public.invoices%ROWTYPE;
  v_count integer := 0;
  v_unpriced integer := 0;
  v_unclassified integer := 0;
  v_contract_skipped integer := 0;
  v_missing_reference integer := 0;
  v_missing_approval integer := 0;
  v_actuals_callouts integer := 0;
  v_billable_callouts integer := 0;
  v_terms_days integer := 14;
  v_due_day integer;
  v_row record;
  v_line_id uuid;
  v_start date := coalesce(p_period_start, date '1970-01-01');
  v_end date := coalesce(p_period_end, current_date);
BEGIN
  IF p_client_request_id IS NULL THEN RAISE EXCEPTION 'client_request_id is required'; END IF;
  IF p_organization_id IS NULL OR p_client_organization_id IS NULL THEN RAISE EXCEPTION 'Organisation and client are required'; END IF;
  IF NOT public.is_admin_for_org(p_organization_id) THEN RAISE EXCEPTION 'Finance administrator access required'; END IF;
  IF v_end < v_start THEN RAISE EXCEPTION 'Period end cannot precede period start'; END IF;
  SELECT i.* INTO v_invoice FROM public.audit_log a JOIN public.invoices i ON i.id = a.target_id
   WHERE a.organization_id = p_organization_id AND a.action = 'crm_invoice_generated_from_completed_work'
     AND a.metadata->>'client_request_id' = p_client_request_id::text LIMIT 1;
  IF FOUND THEN RETURN v_invoice; END IF;

  SELECT count(*)::integer INTO v_unpriced FROM public.patrol_stop_charge_lines line
  WHERE line.organization_id = p_organization_id AND line.client_organization_id = p_client_organization_id
    AND line.status IN ('unresolved_rate', 'unresolved_agreement')
    AND line.created_at::date BETWEEN v_start AND v_end
    AND (p_service_agreement_id IS NULL OR line.service_agreement_id IS NULL OR line.service_agreement_id = p_service_agreement_id);
  IF v_unpriced > 0 THEN RAISE EXCEPTION '% completed patrol visit(s) need a per-visit rate before this invoice can be created', v_unpriced; END IF;

  -- The agreement's commercial model decides how each callout is billed.
  SELECT
    count(*) FILTER (WHERE x.uses_ce AND x.billing_basis IS NULL)::integer,
    count(*) FILTER (WHERE x.uses_ce AND x.billing_basis = 'contract')::integer,
    count(*) FILTER (WHERE x.model = 'per_request' AND x.client_order_reference IS NULL)::integer,
    count(*) FILTER (WHERE NOT x.uses_ce)::integer,
    count(DISTINCT x.source_dispatch_id) FILTER (WHERE x.model = 'do_and_invoice' AND x.client_order_reference IS NULL
      AND x.authority_limit IS NOT NULL AND public.dispatch_job_over_standing_authority(x.source_dispatch_id, x.authority_limit))::integer,
    count(*) FILTER (WHERE x.model = 'do_and_invoice')::integer
    INTO v_unclassified, v_contract_skipped, v_missing_reference, v_billable_callouts, v_missing_approval, v_actuals_callouts
  FROM (
    SELECT line.billing_basis, line.source_dispatch_id, job.client_order_reference,
      public.agreement_uses_contract_extra(line.service_agreement_id) AS uses_ce,
      public.agreement_commercial_model(line.service_agreement_id) AS model,
      settings.standing_authority_limit AS authority_limit
    FROM public.dispatch_job_charge_lines line
    LEFT JOIN public.dispatch_jobs job ON job.id = line.source_dispatch_id
    LEFT JOIN public.crm_commercial_settings settings ON settings.service_agreement_id = line.service_agreement_id
    WHERE line.organization_id = p_organization_id AND line.client_organization_id = p_client_organization_id
      AND line.invoice_line_item_id IS NULL AND line.created_at::date BETWEEN v_start AND v_end
      AND (p_service_agreement_id IS NULL OR line.service_agreement_id IS NULL OR line.service_agreement_id = p_service_agreement_id)
  ) x;
  IF v_unclassified > 0 THEN
    RAISE EXCEPTION '% callout charge line(s) need billing set (Contracted work or Extra) in Dispatch before this invoice can be created', v_unclassified;
  END IF;
  IF v_missing_reference > 0 THEN
    RAISE EXCEPTION '% callout(s) on a per-request agreement need the client''s request or PO reference in Dispatch before this invoice can be created', v_missing_reference;
  END IF;
  IF v_missing_approval > 0 THEN
    RAISE EXCEPTION '% do-and-invoice job(s) cost more than the client''s standing authority limit and need the client''s approval reference in Dispatch before this invoice can be created', v_missing_approval;
  END IF;

  IF p_service_agreement_id IS NOT NULL THEN
    SELECT coalesce(c.payment_terms_days, 14), c.payment_due_day_of_month INTO v_terms_days, v_due_day FROM public.crm_commercial_settings c WHERE c.service_agreement_id = p_service_agreement_id;
    v_terms_days := coalesce(v_terms_days, 14);
  END IF;

  INSERT INTO public.invoices (organization_id, client_organization_id, service_agreement_id, invoice_number, invoice_date, due_date, status, service_period_start, service_period_end, created_by)
  VALUES (p_organization_id, p_client_organization_id, p_service_agreement_id,
    'INV-' || to_char(now(), 'YYYYMMDD') || '-' || upper(substring(gen_random_uuid()::text, 1, 4)),
    current_date, public.invoice_due_date(current_date, v_end, v_terms_days, v_due_day), 'draft', p_period_start, p_period_end, v_actor)
  RETURNING * INTO v_invoice;

  FOR v_row IN
    SELECT line.id AS line_id, wo.order_number, wo.title, line.description, line.quantity, line.unit_price, line.unit_cost, line.line_kind, line.item_id, line.unit_of_measure
    FROM public.workshop_work_order_lines line JOIN public.workshop_work_orders wo ON wo.id = line.work_order_id
    WHERE wo.organization_id = p_organization_id AND wo.client_organization_id = p_client_organization_id AND wo.status = 'completed'
      AND line.invoice_line_item_id IS NULL AND wo.completed_at::date BETWEEN v_start AND v_end
      AND (p_service_agreement_id IS NULL OR wo.service_agreement_id IS NULL OR wo.service_agreement_id = p_service_agreement_id)
    ORDER BY wo.completed_at, line.position
  LOOP
    v_count := v_count + 1;
    INSERT INTO public.invoice_line_items (invoice_id, line_number, description, quantity, unit_price, line_total, organization_id, finance_item_catalog_id, item_type, unit_of_measure, internal_cost_amount, created_by)
    VALUES (v_invoice.id, v_count, v_row.order_number || ' · ' || v_row.title || ' — ' || v_row.description, v_row.quantity, v_row.unit_price, round(v_row.quantity * v_row.unit_price, 2),
      p_organization_id, v_row.item_id, v_row.line_kind, v_row.unit_of_measure, round(v_row.quantity * v_row.unit_cost, 2), v_actor)
    RETURNING id INTO v_line_id;
    UPDATE public.workshop_work_order_lines SET invoice_line_item_id = v_line_id WHERE id = v_row.line_id;
  END LOOP;

  FOR v_row IN
    SELECT line.id AS charge_id, line.source_dispatch_id, line.description, line.quantity, line.unit_rate, line.line_total, line.rate_type, line.created_at,
      ewo.reference AS extra_reference, job.client_order_reference, x.uses_ce, x.model
    FROM public.dispatch_job_charge_lines line
    LEFT JOIN public.agreement_extra_work_orders ewo ON ewo.id = line.extra_work_order_id
    LEFT JOIN public.dispatch_jobs job ON job.id = line.source_dispatch_id
    CROSS JOIN LATERAL (SELECT public.agreement_uses_contract_extra(line.service_agreement_id) AS uses_ce,
      public.agreement_commercial_model(line.service_agreement_id) AS model) x
    WHERE line.organization_id = p_organization_id AND line.client_organization_id = p_client_organization_id
      AND (line.billing_basis = 'extra' OR NOT x.uses_ce)
      AND line.invoice_line_item_id IS NULL AND line.created_at::date BETWEEN v_start AND v_end
      AND (p_service_agreement_id IS NULL OR line.service_agreement_id IS NULL OR line.service_agreement_id = p_service_agreement_id)
    ORDER BY line.created_at
    -- Locked so a concurrent run waits, then skips lines this run has stamped.
    FOR UPDATE OF line
  LOOP
    v_count := v_count + 1;
    INSERT INTO public.invoice_line_items (invoice_id, line_number, description, quantity, unit_price, line_total, organization_id, item_type, source_dispatch_id, created_by)
    VALUES (v_invoice.id, v_count,
      CASE WHEN v_row.uses_ce THEN 'Extra' || coalesce(' ' || v_row.extra_reference, '') || ' — '
        WHEN v_row.model = 'do_and_invoice' THEN 'Actuals — ' ELSE '' END
        || CASE WHEN v_row.model = 'do_and_invoice' THEN coalesce('Client approval ' || v_row.client_order_reference || ' — ', '')
           ELSE coalesce('Client ref ' || v_row.client_order_reference || ' — ', '') END
        || coalesce(v_row.description, 'Dispatch ' || v_row.rate_type),
      coalesce(v_row.quantity, 1), coalesce(v_row.unit_rate, v_row.line_total), v_row.line_total, p_organization_id, 'other', v_row.source_dispatch_id, v_actor)
    RETURNING id INTO v_line_id;
    UPDATE public.dispatch_job_charge_lines SET invoice_line_item_id = v_line_id WHERE id = v_row.charge_id;
  END LOOP;

  FOR v_row IN
    SELECT line.id AS charge_id, line.shift_id, line.description, line.quantity, line.unit_rate, line.line_total, line.created_at
    FROM public.patrol_stop_charge_lines line
    WHERE line.organization_id = p_organization_id AND line.client_organization_id = p_client_organization_id
      AND line.status = 'ready' AND line.invoice_line_item_id IS NULL AND line.created_at::date BETWEEN v_start AND v_end
      AND (p_service_agreement_id IS NULL OR line.service_agreement_id = p_service_agreement_id)
      -- A fixed monthly fee already pays for contracted visits; they draw the fee down instead.
      AND coalesce(public.agreement_commercial_model(line.service_agreement_id), '') <> 'fixed_price_with_extras'
    ORDER BY line.created_at
  LOOP
    v_count := v_count + 1;
    INSERT INTO public.invoice_line_items (invoice_id, line_number, description, quantity, unit_price, line_total, organization_id, item_type, shift_id, created_by)
    VALUES (v_invoice.id, v_count, v_row.description, v_row.quantity, v_row.line_total, v_row.line_total, p_organization_id, 'other', v_row.shift_id, v_actor)
    RETURNING id INTO v_line_id;
    UPDATE public.patrol_stop_charge_lines SET invoice_line_item_id = v_line_id, status = 'invoiced', updated_at = now() WHERE id = v_row.charge_id;
  END LOOP;

  IF v_count = 0 THEN
    DELETE FROM public.invoices WHERE id = v_invoice.id;
    IF v_contract_skipped > 0 THEN
      RAISE EXCEPTION 'Nothing to invoice: % callout charge line(s) in the period are contracted work, covered by the agreement price', v_contract_skipped;
    END IF;
    RAISE EXCEPTION 'No completed, uninvoiced work for this client in the period';
  END IF;
  UPDATE public.invoices invoice SET subtotal = totals.subtotal, gst_amount = round(totals.subtotal * 0.15, 2), total_amount = round(totals.subtotal * 1.15, 2), updated_at = now()
  FROM (SELECT coalesce(sum(line_total), 0) AS subtotal FROM public.invoice_line_items WHERE invoice_id = v_invoice.id) totals
  WHERE invoice.id = v_invoice.id RETURNING invoice.* INTO v_invoice;
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (p_organization_id, v_actor, 'crm_invoice_generated_from_completed_work', 'invoices', v_invoice.id,
    jsonb_build_object('client_request_id', p_client_request_id, 'client_organization_id', p_client_organization_id,
      'lines', v_count, 'total_amount', v_invoice.total_amount, 'period_start', p_period_start, 'period_end', p_period_end,
      'contract_callout_lines_not_billed', v_contract_skipped, 'callout_lines_billed_by_commercial_model', v_billable_callouts,
      'do_and_invoice_actuals_lines', v_actuals_callouts,
      'payment_terms_days', v_terms_days, 'payment_due_day_of_month', v_due_day, 'due_date', v_invoice.due_date));
  RETURN v_invoice;
END;
$function$;
COMMENT ON FUNCTION "public"."generate_crm_invoice_from_completed_work"(p_client_request_id uuid, p_organization_id uuid, p_client_organization_id uuid, p_service_agreement_id uuid, p_period_start date, p_period_end date) IS 'Sweep completed, uninvoiced workshop lines, billable dispatch charge lines and ready patrol visit lines (except on fixed price plus Extra agreements, where contracted visits draw down the monthly fee) for one client into a single draft invoice (GST 15%). Callouts follow the agreement commercial model: fixed price plus Extra (or not set) bills Extra only, skips Contract and blocks while any callout has no decision; pay as you go bills every callout at agreed rates; do and invoice bills the actuals under standing authority (lines prefixed Actuals) and blocks a job that costs more than the agreement standing authority limit until it has the client''s approval reference; per request bills every callout and blocks until each job has the client reference. Due date follows the agreement payment terms when one agreement is invoiced: the due day of the month after the invoiced period when set (never before the invoice date), otherwise payment_terms_days after the invoice date (default 14). Stamps invoice_line_item_id on the source lines so nothing is billed twice. Idempotent on client_request_id; audited.';
REVOKE ALL ON FUNCTION "public"."generate_crm_invoice_from_completed_work"(p_client_request_id uuid, p_organization_id uuid, p_client_organization_id uuid, p_service_agreement_id uuid, p_period_start date, p_period_end date) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."generate_crm_invoice_from_completed_work"(p_client_request_id uuid, p_organization_id uuid, p_client_organization_id uuid, p_service_agreement_id uuid, p_period_start date, p_period_end date) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."generate_crm_invoice_from_completed_work"(p_client_request_id uuid, p_organization_id uuid, p_client_organization_id uuid, p_service_agreement_id uuid, p_period_start date, p_period_end date) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."generate_custom_report_pack"(p_service_agreement_id uuid, p_period_start date, p_period_end date, p_title text, p_site_ids uuid[], p_zone_ids uuid[], p_person_ids uuid[], p_vehicle_ids uuid[], p_sections text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_agreement record;
  v_start_ts timestamptz := p_period_start::timestamptz;
  v_end_ts timestamptz := p_period_end::timestamptz + interval '1 day';
  v_site_ids uuid[];
  v_zone_ids uuid[];
  v_person_ids uuid[];
  v_vehicle_ids uuid[];
  v_sections text[];
  v_invalid_sections text;
  v_has_entity_scope boolean;
  v_privacy_tier text;
  v_observation_count integer := 0;
  v_compliant_count integer := 0;
  v_non_compliant_count integer := 0;
  v_breach_count integer := 0;
  v_incident_count integer := 0;
  v_checkpoint_count integer := 0;
  v_observations jsonb := '[]'::jsonb;
  v_breaches jsonb := '[]'::jsonb;
  v_incidents jsonb := '[]'::jsonb;
  v_checkpoint_visits jsonb := '[]'::jsonb;
  v_snapshot jsonb;
  v_scope_labels jsonb;
  v_report_scope jsonb;
  v_data jsonb := '{}'::jsonb;
  v_pack_id uuid := gen_random_uuid();
begin
  if v_actor is null then
    raise exception 'Authenticated provider administrator required';
  end if;
  if p_period_start is null or p_period_end is null
     or p_period_start > p_period_end
     or p_period_end - p_period_start > 366 then
    raise exception 'Select a valid report period of 366 days or less';
  end if;
  if nullif(btrim(coalesce(p_title, '')), '') is null or length(p_title) > 160 then
    raise exception 'A report title of 160 characters or less is required';
  end if;

  select coalesce(array_agg(item order by item), '{}'::uuid[])
  into v_site_ids
  from (select distinct unnest(coalesce(p_site_ids, '{}'::uuid[])) as item) selected
  where item is not null;
  select coalesce(array_agg(item order by item), '{}'::uuid[])
  into v_zone_ids
  from (select distinct unnest(coalesce(p_zone_ids, '{}'::uuid[])) as item) selected
  where item is not null;
  select coalesce(array_agg(item order by item), '{}'::uuid[])
  into v_person_ids
  from (select distinct unnest(coalesce(p_person_ids, '{}'::uuid[])) as item) selected
  where item is not null;
  select coalesce(array_agg(item order by item), '{}'::uuid[])
  into v_vehicle_ids
  from (select distinct unnest(coalesce(p_vehicle_ids, '{}'::uuid[])) as item) selected
  where item is not null;
  select coalesce(array_agg(item order by item), '{}'::text[])
  into v_sections
  from (
    select distinct lower(btrim(value)) as item
    from unnest(coalesce(p_sections, '{}'::text[])) value
    where nullif(btrim(value), '') is not null
  ) selected;

  if cardinality(v_site_ids) > 100 or cardinality(v_zone_ids) > 100
     or cardinality(v_person_ids) > 100 or cardinality(v_vehicle_ids) > 100 then
    raise exception 'Each custom report scope is limited to 100 selected records per dimension';
  end if;
  if cardinality(v_sections) = 0 then
    raise exception 'Select at least one report section';
  end if;
  select string_agg(section, ', ' order by section)
  into v_invalid_sections
  from unnest(v_sections) section
  where section <> all(array['summary', 'observations', 'breaches', 'incidents', 'checkpoint_visits']);
  if v_invalid_sections is not null then
    raise exception 'Unsupported custom report section: %', v_invalid_sections;
  end if;

  select agreement.id, agreement.provider_organization_id,
      agreement.client_organization_id, agreement.name,
      agreement.starts_on, agreement.ends_on
  into v_agreement
  from public.service_agreements agreement
  where agreement.id = p_service_agreement_id
    and agreement.agreement_type = 'operational';

  if v_agreement.id is null then
    raise exception 'Operational service agreement not found';
  end if;
  if (v_agreement.starts_on is not null and p_period_start < v_agreement.starts_on)
     or (v_agreement.ends_on is not null and p_period_end > v_agreement.ends_on) then
    raise exception 'Report period must fall within the service agreement term';
  end if;
  if not public.is_report_provider_custodian_for_org(v_agreement.provider_organization_id) then
    raise exception 'Provider administrator access required';
  end if;

  if exists (
    select 1 from unnest(v_site_ids) selected(id)
    where not exists (
      select 1 from public.service_agreement_locations link
      where link.service_agreement_id = v_agreement.id
        and link.site_id = selected.id
        and link.status = 'active'
    )
  ) or exists (
    select 1 from unnest(v_zone_ids) selected(id)
    where not exists (
      select 1 from public.service_agreement_locations link
      where link.service_agreement_id = v_agreement.id
        and link.zone_id = selected.id
        and link.status = 'active'
    )
  ) then
    raise exception 'Selected Site or Zone is outside this agreement';
  end if;

  if exists (
    select 1 from unnest(v_person_ids) selected(id)
    where not exists (
      select 1
      from public.observations observation
      where observation.organization_id = v_agreement.provider_organization_id
        and observation.observed_at >= v_start_ts
        and observation.observed_at < v_end_ts
        and observation.canonical_person_id = selected.id
        and exists (
          select 1 from public.service_agreement_locations link
          where link.service_agreement_id = v_agreement.id
            and link.status = 'active'
            and (
              (link.site_id is not null and link.site_id = observation.site_id)
              or (link.zone_id is not null and link.zone_id = observation.zone_id)
            )
        )
    )
  ) then
    raise exception 'Selected person is outside this agreement and reporting period';
  end if;

  if exists (
    select 1 from unnest(v_vehicle_ids) selected(id)
    where not exists (
      select 1
      from public.observations observation
      where observation.organization_id = v_agreement.provider_organization_id
        and observation.observed_at >= v_start_ts
        and observation.observed_at < v_end_ts
        and observation.canonical_vehicle_id = selected.id
        and exists (
          select 1 from public.service_agreement_locations link
          where link.service_agreement_id = v_agreement.id
            and link.status = 'active'
            and (
              (link.site_id is not null and link.site_id = observation.site_id)
              or (link.zone_id is not null and link.zone_id = observation.zone_id)
            )
        )
    )
  ) then
    raise exception 'Selected vehicle is outside this agreement and reporting period';
  end if;

  v_has_entity_scope := cardinality(v_person_ids) > 0 or cardinality(v_vehicle_ids) > 0;
  v_privacy_tier := case
    when array_position(v_sections, 'incidents') is not null then 'sensitive_personal'
    when v_has_entity_scope
      or array_position(v_sections, 'observations') is not null
      or array_position(v_sections, 'breaches') is not null
      or array_position(v_sections, 'checkpoint_visits') is not null then 'personal'
    else 'operational_metadata'
  end;
  if v_has_entity_scope
     and (array_position(v_sections, 'incidents') is not null
          or array_position(v_sections, 'checkpoint_visits') is not null) then
    raise exception 'Incident and checkpoint sections do not have a governed person or vehicle link';
  end if;

  v_snapshot := public.custom_report_source_snapshot(
    v_agreement.provider_organization_id,
    v_agreement.id,
    v_start_ts,
    v_end_ts,
    v_site_ids,
    v_zone_ids,
    v_person_ids,
    v_vehicle_ids,
    v_has_entity_scope,
    v_sections
  );
  v_observation_count := (v_snapshot->>'observation_count')::integer;
  v_compliant_count := (v_snapshot->>'compliant_count')::integer;
  v_non_compliant_count := (v_snapshot->>'non_compliant_count')::integer;
  v_breach_count := (v_snapshot->>'breach_count')::integer;
  v_incident_count := (v_snapshot->>'incident_count')::integer;
  v_checkpoint_count := (v_snapshot->>'checkpoint_count')::integer;
  v_observations := v_snapshot->'observations';
  v_breaches := v_snapshot->'breaches';
  v_incidents := v_snapshot->'incidents';
  v_checkpoint_visits := v_snapshot->'checkpoint_visits';
  v_scope_labels := v_snapshot->'scope_labels';

  if array_position(v_sections, 'observations') is not null and v_observation_count > 1000 then
    raise exception 'Custom report scope exceeds 1000 observations; narrow the date or entity scope';
  end if;

  if array_position(v_sections, 'breaches') is not null and v_breach_count > 1000 then
    raise exception 'Custom report scope exceeds 1000 breaches; narrow the date or entity scope';
  end if;

  if array_position(v_sections, 'incidents') is not null and v_incident_count > 1000 then
    raise exception 'Custom report scope exceeds 1000 incidents; narrow the date or place scope';
  end if;

  if array_position(v_sections, 'checkpoint_visits') is not null and v_checkpoint_count > 1000 then
    raise exception 'Custom report scope exceeds 1000 checkpoint visits; narrow the date or place scope';
  end if;

  v_report_scope := jsonb_build_object(
    'version', 1,
    'agreement_id', v_agreement.id,
    'selection_mode', case
      when cardinality(v_site_ids) + cardinality(v_zone_ids) + cardinality(v_person_ids) + cardinality(v_vehicle_ids) = 0
        then 'all_agreement_activity'
      else 'selected_entities'
    end,
    'privacy_tier', v_privacy_tier,
    'match_semantics', 'or_within_dimensions_and_across_dimensions',
    'site_ids', to_jsonb(v_site_ids),
    'zone_ids', to_jsonb(v_zone_ids),
    'person_ids', to_jsonb(v_person_ids),
    'vehicle_ids', to_jsonb(v_vehicle_ids),
    'sections', to_jsonb(v_sections),
    'labels', v_scope_labels
  );

  if array_position(v_sections, 'summary') is not null then
    v_data := v_data || jsonb_build_object('summary', jsonb_strip_nulls(jsonb_build_object(
      'observation_count', v_observation_count,
      'compliant_count', v_compliant_count,
      'non_compliant_count', v_non_compliant_count,
      'breach_count', v_breach_count,
      'incident_count', case when not v_has_entity_scope then v_incident_count end,
      'checkpoint_visit_count', case when not v_has_entity_scope then v_checkpoint_count end
    )));
  end if;
  if array_position(v_sections, 'observations') is not null then
    v_data := v_data || jsonb_build_object('observations', v_observations);
  end if;
  if array_position(v_sections, 'breaches') is not null then
    v_data := v_data || jsonb_build_object('breaches', v_breaches);
  end if;
  if array_position(v_sections, 'incidents') is not null then
    v_data := v_data || jsonb_build_object('incidents', v_incidents);
  end if;
  if array_position(v_sections, 'checkpoint_visits') is not null then
    v_data := v_data || jsonb_build_object('checkpoint_visits', v_checkpoint_visits);
  end if;

  insert into public.monthly_report_packs (
    id, organization_id, service_agreement_id, template_code,
    period_start, period_end, status, report_kind, report_scope,
    data, editorial, generated_at, generated_by, updated_at
  ) values (
    v_pack_id,
    v_agreement.provider_organization_id,
    v_agreement.id,
    'custom_' || left(replace(v_pack_id::text, '-', ''), 24),
    p_period_start,
    p_period_end,
    'draft',
    'custom',
    v_report_scope,
    v_data,
    jsonb_build_object('title', btrim(p_title)),
    clock_timestamp(),
    v_actor,
    clock_timestamp()
  );

  insert into public.audit_log (
    organization_id, actor_user_id, action, target_table, target_id, metadata
  ) values (
    v_agreement.provider_organization_id,
    v_actor,
    'custom_report_pack_generated',
    'monthly_report_packs',
    v_pack_id,
    jsonb_build_object(
      'agreement_id', v_agreement.id,
      'period_start', p_period_start,
      'period_end', p_period_end,
      'sections', to_jsonb(v_sections),
      'site_count', cardinality(v_site_ids),
      'zone_count', cardinality(v_zone_ids),
      'person_count', cardinality(v_person_ids),
      'vehicle_count', cardinality(v_vehicle_ids),
      'observation_count', v_observation_count,
      'breach_count', v_breach_count,
      'status', 'draft'
    )
  );

  return jsonb_build_object(
    'id', v_pack_id,
    'status', 'draft',
    'observation_count', v_observation_count,
    'breach_count', v_breach_count,
    'incident_count', v_incident_count,
    'checkpoint_visit_count', v_checkpoint_count
  );
end;
$function$;
COMMENT ON FUNCTION "public"."generate_custom_report_pack"(p_service_agreement_id uuid, p_period_start date, p_period_end date, p_title text, p_site_ids uuid[], p_zone_ids uuid[], p_person_ids uuid[], p_vehicle_ids uuid[], p_sections text[]) IS 'Creates a new provider-private custom report draft anchored to one accepted operational agreement. IDs are OR-matched within dimensions and AND-matched across populated dimensions; selected scope and source facts are snapshotted for review.';
REVOKE ALL ON FUNCTION "public"."generate_custom_report_pack"(p_service_agreement_id uuid, p_period_start date, p_period_end date, p_title text, p_site_ids uuid[], p_zone_ids uuid[], p_person_ids uuid[], p_vehicle_ids uuid[], p_sections text[]) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."generate_custom_report_pack"(p_service_agreement_id uuid, p_period_start date, p_period_end date, p_title text, p_site_ids uuid[], p_zone_ids uuid[], p_person_ids uuid[], p_vehicle_ids uuid[], p_sections text[]) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."generate_custom_report_pack"(p_service_agreement_id uuid, p_period_start date, p_period_end date, p_title text, p_site_ids uuid[], p_zone_ids uuid[], p_person_ids uuid[], p_vehicle_ids uuid[], p_sections text[]) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."generate_due_report_packs"(p_period_start date, p_period_end date)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
	return public.generate_due_report_packs(p_period_start, p_period_end, null);
end;
$function$;
COMMENT ON FUNCTION "public"."generate_due_report_packs"(p_period_start date, p_period_end date) IS 'Assembles provider-private draft report packs for every eligible provider-tree agreement.';
REVOKE ALL ON FUNCTION "public"."generate_due_report_packs"(p_period_start date, p_period_end date) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."generate_due_report_packs"(p_period_start date, p_period_end date) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."generate_due_report_packs"(p_period_start date, p_period_end date) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."generate_due_report_packs"(p_period_start date, p_period_end date) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."generate_due_report_packs"(p_period_start date, p_period_end date, p_service_agreement_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
	v_actor uuid := auth.uid();
	v_provider uuid;
	v_agreement record;
	v_count integer := 0;
	v_written integer;
	v_data jsonb;
	v_start_ts timestamptz := p_period_start::timestamp at time zone 'Pacific/Auckland';
	v_end_ts timestamptz := (p_period_end + 1)::timestamp at time zone 'Pacific/Auckland';
	v_sla_met integer;
	v_sla_breached integer;
	v_sla_running integer;
	v_inc_total integer;
	v_inc_by_sev jsonb;
	v_checkpoints integer;
	v_breaches integer;
	v_delivery jsonb;
	v_facilities jsonb;
	v_operational_events integer;
	v_patrol_visits integer;
	v_camera_activations integer;
	v_vehicle_observations integer;
	v_event_distance_km numeric;
	v_observation_distance_km numeric;
	v_activity jsonb;
begin
	if p_period_start is null or p_period_end is null
			or p_period_start > p_period_end
			or p_period_end - p_period_start > 366 then
		raise exception 'Select a valid report period of 366 days or less';
	end if;

	select profile.organization_id
	into v_provider
	from public.user_profiles profile
	where profile.id = v_actor
		and profile.deactivated_at is null;

	if v_provider is null or not public.is_admin_for_org(v_provider) then
		raise exception 'Active provider administrator required';
	end if;

	if p_service_agreement_id is not null and not exists (
		select 1
		from public.service_agreements agreement
		where agreement.id = p_service_agreement_id
			and agreement.provider_organization_id = any(public.get_descendant_organizations(v_provider))
			and agreement.agreement_type = 'operational'
			and agreement.monthly_report_template_code is not null
	) then
		raise exception 'Service agreement is not available for report generation';
	end if;

	for v_agreement in
		select agreement.id, agreement.provider_organization_id,
					 agreement.monthly_report_template_code
		from public.service_agreements agreement
		where agreement.provider_organization_id = any(public.get_descendant_organizations(v_provider))
			and agreement.monthly_report_template_code is not null
			and (
				p_service_agreement_id is null
				or (
					agreement.id = p_service_agreement_id
					and agreement.agreement_type = 'operational'
				)
			)
	loop
		select count(*) filter (where clock.status = 'met'),
					 count(*) filter (where clock.status = 'breached'),
					 count(*) filter (where clock.status = 'running')
		into v_sla_met, v_sla_breached, v_sla_running
		from public.sla_clocks clock
		where clock.service_agreement_id = v_agreement.id
			and clock.started_at >= v_start_ts
			and clock.started_at < v_end_ts;

		select count(*), coalesce(jsonb_object_agg(summary.severity, summary.n), '{}'::jsonb)
		into v_inc_total, v_inc_by_sev
		from (
			select incident.severity, count(*) as n
			from public.incidents incident
			where incident.organization_id = v_agreement.provider_organization_id
				and incident.occurred_at >= v_start_ts
				and incident.occurred_at < v_end_ts
			group by incident.severity
		) summary;

		select count(*) into v_checkpoints
		from public.patrol_checkpoint_visits visit
		where visit.organization_id = v_agreement.provider_organization_id
			and visit.visited_at >= v_start_ts
			and visit.visited_at < v_end_ts;

		select count(*) into v_breaches
		from public.breach_alerts alert
		where alert.organization_id = v_agreement.provider_organization_id
			and alert.created_at >= v_start_ts
			and alert.created_at < v_end_ts;

		select count(*),
					 count(*) filter (where event.event_type = 'patrol_visit'),
					 count(*) filter (where event.event_type = 'camera_activation'),
					 coalesce(sum(event.distance_km), 0)
		into v_operational_events, v_patrol_visits, v_camera_activations, v_event_distance_km
		from public.location_events event
		where event.occurred_at >= v_start_ts
			and event.occurred_at < v_end_ts
			and exists (
				select 1
				from public.service_agreement_locations link
				where link.service_agreement_id = v_agreement.id
					and link.status = 'active'
					and (
						(link.zone_id is not null and link.zone_id = event.zone_id)
						or (link.site_id is not null and link.site_id = event.client_site_id)
					)
			);

		select count(*), coalesce(sum(observation.distance_km), 0)
		into v_vehicle_observations, v_observation_distance_km
		from public.observations observation
		where observation.observed_at >= v_start_ts
			and observation.observed_at < v_end_ts
			and exists (
				select 1
				from public.service_agreement_locations link
				where link.service_agreement_id = v_agreement.id
					and link.status = 'active'
					and (
						(link.zone_id is not null and link.zone_id = observation.zone_id)
						or (link.site_id is not null and link.site_id = observation.site_id)
					)
			);

		v_delivery := public.agreement_service_delivery(
			v_agreement.id,
			p_period_start,
			p_period_end
		);

		select coalesce(jsonb_agg(jsonb_build_object(
			'siteName', place->>'place_name',
			'expected', (place->>'patrol_expected')::integer + (place->>'post_expected')::integer,
			'completed', (place->>'patrol_completed')::integer + (place->>'post_attended')::integer
		) order by place->>'place_name'), '[]'::jsonb)
		into v_facilities
		from jsonb_array_elements(v_delivery->'places') as place;

		v_activity := public.build_agreement_activity_report(v_agreement.id, v_start_ts, v_end_ts, 2000);

		v_data := jsonb_build_object(
			'slaMet', coalesce(v_sla_met, 0),
			'slaBreached', coalesce(v_sla_breached, 0),
			'slaRunning', coalesce(v_sla_running, 0),
			'incidentsTotal', coalesce(v_inc_total, 0),
			'incidentsBySeverity', coalesce(v_inc_by_sev, '{}'::jsonb),
			'checkpointVisits', coalesce(v_checkpoints, 0),
			'breachAlerts', coalesce(v_breaches, 0),
			'facilities', v_facilities,
			'delivery', v_delivery,
			'operationalEvents', coalesce(v_operational_events, 0),
			'patrolVisits', coalesce(v_patrol_visits, 0),
			'cameraActivations', coalesce(v_camera_activations, 0),
			'vehicleObservations', coalesce(v_vehicle_observations, 0),
			'patrolTravelKm', coalesce(v_event_distance_km, 0) + coalesce(v_observation_distance_km, 0),
			'activityReport', v_activity -> 'report'
		);

		insert into public.monthly_report_packs as existing (
			organization_id, service_agreement_id, template_code, period_start,
			period_end, status, data, activity_lines, generated_at, generated_by, updated_at
		) values (
			v_agreement.provider_organization_id,
			v_agreement.id,
			v_agreement.monthly_report_template_code,
			p_period_start,
			p_period_end,
			'draft',
			v_data,
			v_activity -> 'lines',
			clock_timestamp(),
			v_actor,
			clock_timestamp()
		)
		on conflict (service_agreement_id, template_code, period_start)
		do update set
			period_end = excluded.period_end,
			data = excluded.data,
			activity_lines = excluded.activity_lines,
			status = 'draft',
			generated_at = clock_timestamp(),
			generated_by = v_actor,
			reviewed_at = null,
			reviewed_by = null,
			published_at = null,
			published_by = null,
			delivery_channel = null,
			pdf_path = null,
			pdf_mime_type = null,
			pdf_sha256 = null,
			pdf_renderer_version = null,
			delivery_error = null,
			updated_at = clock_timestamp()
		where existing.status <> 'sent';

		get diagnostics v_written = row_count;
		v_count := v_count + v_written;
	end loop;

	insert into public.audit_log (
		organization_id, actor_user_id, action, target_table, metadata
	) values (
		v_provider,
		v_actor,
		'monthly_report_packs_generated',
		'monthly_report_packs',
		jsonb_build_object(
			'period_start', p_period_start,
			'period_end', p_period_end,
			'pack_count', v_count,
			'service_agreement_id', p_service_agreement_id,
			'status', 'draft'
		)
	);

	return v_count;
end;
$function$;
COMMENT ON FUNCTION "public"."generate_due_report_packs"(p_period_start date, p_period_end date, p_service_agreement_id uuid) IS 'Assembles provider-private draft report packs for one authorized agreement or all eligible agreements when no ID is supplied. Activity metrics are aggregated only from agreement-linked places; the activityReport key and activity_lines column carry the categorised and itemised R&M month-end site activity report, including the narratives and photo references recorded at each place. Travel, administration and shift markers are withheld from it; names, structured plates, costs, GPS and source file names are never copied. Report periods use New Zealand (Pacific/Auckland) day boundaries. Sent packs are never regenerated.';
REVOKE ALL ON FUNCTION "public"."generate_due_report_packs"(p_period_start date, p_period_end date, p_service_agreement_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."generate_due_report_packs"(p_period_start date, p_period_end date, p_service_agreement_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."generate_due_report_packs"(p_period_start date, p_period_end date, p_service_agreement_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."generate_due_report_packs"(p_period_start date, p_period_end date, p_service_agreement_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."generate_noise_job_number"()
 RETURNS text
 LANGUAGE sql
AS $function$
