CREATE OR REPLACE FUNCTION "public"."generate_officer_activity_evidence_export"(p_officer_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer DEFAULT 5000)
 RETURNS TABLE(export_id uuid, generated_at timestamp with time zone, sha256 text, event_count integer, package_text text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_actor_id uuid := auth.uid();
  v_org_id uuid;
  v_officer_name text;
  v_export_id uuid := gen_random_uuid();
  v_generated_at timestamptz := clock_timestamp();
  v_events jsonb;
  v_payload jsonb;
  v_package_text text;
  v_sha256 text;
  v_event_count integer;
  v_effective_limit integer := least(greatest(coalesce(p_limit, 5000), 1), 5000);
begin
  if v_actor_id is null then raise exception 'Authentication required'; end if;

  select organization_id, display_name
    into v_org_id, v_officer_name
  from public.user_profiles
  where id = p_officer_id;

  if v_org_id is null then raise exception 'Officer profile not found'; end if;
  if not public.is_admin_for_org(v_org_id) then raise exception 'Not authorised to export this officer timeline'; end if;
  if p_from is null or p_to is null or p_from >= p_to or p_to - p_from > interval '31 days' then
    raise exception 'Export range must be between 1 second and 31 days';
  end if;

  select coalesce(jsonb_agg(to_jsonb(t) order by t.event_at, t.event_key), '[]'::jsonb)
    into v_events
  from public.get_officer_activity_timeline_unlogged(p_officer_id, p_from, p_to, v_effective_limit) t;

  v_event_count := jsonb_array_length(v_events);
  v_payload := jsonb_build_object(
    'schema_version', 1,
    'export_id', v_export_id,
    'generated_at', v_generated_at,
    'generated_by', v_actor_id,
    'organization_id', v_org_id,
    'officer', jsonb_build_object('id', p_officer_id, 'display_name', v_officer_name),
    'period', jsonb_build_object('from', p_from, 'to', p_to),
    'event_count', v_event_count,
    'events', v_events
  );
  v_package_text := v_payload::text;
  v_sha256 := pg_catalog.encode(extensions.digest(pg_catalog.convert_to(v_package_text, 'UTF8'), 'sha256'), 'hex');

  insert into public.officer_activity_evidence_exports (
    id, organization_id, officer_user_id, generated_by, period_from, period_to,
    event_count, payload, sha256, generated_at
  ) values (
    v_export_id, v_org_id, p_officer_id, v_actor_id, p_from, p_to,
    v_event_count, v_payload, v_sha256, v_generated_at
  );

  insert into public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (
    v_org_id,
    v_actor_id,
    'officer_activity_evidence_exported',
    'officer_activity_evidence_exports',
    v_export_id,
    jsonb_build_object(
      'officer_user_id', p_officer_id,
      'from', p_from,
      'to', p_to,
      'event_count', v_event_count,
      'sha256', v_sha256
    )
  );

  return query select v_export_id, v_generated_at, v_sha256, v_event_count, v_package_text;
end;
$function$;
COMMENT ON FUNCTION "public"."generate_officer_activity_evidence_export"(p_officer_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer) IS 'Creates an immutable canonical officer timeline snapshot, hashes its exact returned JSON bytes, and audits issuance.';
REVOKE ALL ON FUNCTION "public"."generate_officer_activity_evidence_export"(p_officer_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."generate_officer_activity_evidence_export"(p_officer_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."generate_officer_activity_evidence_export"(p_officer_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."generate_officer_activity_evidence_export"(p_officer_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."generate_pl_financial_statement"(p_pl_period_id uuid)
 RETURNS TABLE(report_name text, period_start date, period_end date, total_revenue numeric, total_labour_cost numeric, total_vehicle_cost numeric, total_materials_cost numeric, total_equipment_cost numeric, total_overhead_cost numeric, total_depreciation_cost numeric, total_operating_cost numeric, gross_profit numeric, gross_margin_pct numeric, cost_breakdown jsonb)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid(); v_org uuid; v_period public.finance_pl_periods%rowtype; v_snapshot public.finance_pl_snapshots%rowtype;
  v_revenue numeric := 0; v_labour numeric := 0; v_vehicle numeric := 0; v_materials numeric := 0; v_equipment numeric := 0; v_overhead numeric := 0; v_depreciation numeric := 0; v_total_cost numeric := 0; v_gross_profit numeric := 0; v_margin_pct numeric := 0;
BEGIN
  SELECT organization_id INTO v_org FROM public.user_profiles WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_org IS NULL OR NOT public.is_admin_for_org(v_org) THEN RAISE EXCEPTION 'Active finance administrator required'; END IF;
  SELECT * INTO v_period FROM public.finance_pl_periods WHERE id = p_pl_period_id AND organization_id = v_org;
  IF NOT FOUND THEN RAISE EXCEPTION 'P&L period not found in organization'; END IF;
  SELECT * INTO v_snapshot FROM public.finance_pl_snapshots WHERE pl_period_id = p_pl_period_id;
  IF FOUND THEN v_labour := v_snapshot.total_labour; v_vehicle := v_snapshot.total_vehicle; v_materials := v_snapshot.total_materials; v_equipment := v_snapshot.total_equipment; v_overhead := v_snapshot.total_overhead; v_depreciation := v_snapshot.total_depreciation; v_total_cost := v_snapshot.total_cost; v_revenue := v_snapshot.total_revenue;
  ELSE SELECT COALESCE(SUM(total_amount), 0) INTO v_revenue FROM public.invoices WHERE organization_id = v_org AND invoice_date BETWEEN v_period.period_start AND v_period.period_end; END IF;
  v_gross_profit := v_revenue - v_total_cost; v_margin_pct := CASE WHEN v_revenue > 0 THEN ROUND((v_gross_profit / v_revenue) * 100, 2) ELSE 0 END;
  RETURN QUERY SELECT 'P&L Statement ' || v_period.period_start::text || ' to ' || v_period.period_end::text, v_period.period_start, v_period.period_end, v_revenue, v_labour, v_vehicle, v_materials, v_equipment, v_overhead, v_depreciation, v_total_cost, v_gross_profit, v_margin_pct, jsonb_build_object('labour', v_labour, 'vehicle', v_vehicle, 'materials', v_materials, 'equipment', v_equipment, 'overhead', v_overhead, 'depreciation', v_depreciation, 'total_cost', v_total_cost);
END;
$function$;
REVOKE ALL ON FUNCTION "public"."generate_pl_financial_statement"(p_pl_period_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."generate_pl_financial_statement"(p_pl_period_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."generate_pl_financial_statement"(p_pl_period_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."generate_pl_financial_statement"(p_pl_period_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."generate_roster_from_templates"(p_client_request_id uuid, p_organization_id uuid, p_from_date date, p_to_date date)
 RETURNS TABLE(slots_generated integer, templates_applied integer, templates_skipped integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_provider uuid;
  v_count integer := 0;
  v_applied integer := 0;
  v_skipped integer := 0;
  v_tpl record;
  v_unit_id uuid;
  v_fallback_unit uuid;
  v_curr_date date;
  v_dow integer;
  v_start_ts timestamptz;
  v_end_ts timestamptz;
  v_made_any boolean;
  v_slot integer;
begin
  if p_client_request_id is null then
    raise exception 'client_request_id is required';
  end if;

  select actor.organization_id into v_provider from public.user_profiles actor
  where actor.id = v_actor and actor.deactivated_at is null;

  if v_provider is null or not public.is_admin_for_org(v_provider) then
    raise exception 'Active roster administrator required';
  end if;

  if p_organization_id <> v_provider then
    raise exception 'Organization is outside your managed account hierarchy';
  end if;

  if p_to_date < p_from_date then
    raise exception 'Generation period end must not precede its start';
  end if;

  if (p_to_date - p_from_date) > 186 then
    raise exception 'Generation period cannot exceed six months';
  end if;

  select wu.id into v_fallback_unit
  from public.roster_work_units wu
  where wu.organization_id = v_provider and wu.active = true
  order by wu.name
  limit 1;

  for v_tpl in (
    select st.*
    from public.shift_templates st
    where st.organization_id = v_provider
      and st.is_active = true
      and (st.effective_from is null or st.effective_from <= p_to_date)
      and (st.effective_to is null or st.effective_to >= p_from_date)
  ) loop
    v_unit_id := null;

    if v_tpl.patrol_route_id is not null then
      select wu.id into v_unit_id from public.roster_work_units wu
      where wu.organization_id = v_provider and wu.active = true
        and wu.patrol_route_id = v_tpl.patrol_route_id
      limit 1;
    end if;

    if v_unit_id is null and v_tpl.site_id is not null then
      select wu.id into v_unit_id
      from public.roster_work_units wu
      join public.service_agreement_locations sal on sal.id = wu.service_agreement_location_id
      where wu.organization_id = v_provider and wu.active = true and sal.site_id = v_tpl.site_id
      limit 1;
    end if;

    v_unit_id := coalesce(v_unit_id, v_fallback_unit);

    if v_unit_id is null then
      v_skipped := v_skipped + 1;
      continue;
    end if;

    v_made_any := false;
    v_curr_date := p_from_date;

    while v_curr_date <= p_to_date loop
      v_dow := extract(isodow from v_curr_date);
      if v_dow = any(v_tpl.active_days) then
        v_start_ts := (v_curr_date + v_tpl.start_time) at time zone 'Pacific/Auckland';
        if v_tpl.end_time <= v_tpl.start_time then
          v_end_ts := ((v_curr_date + 1) + v_tpl.end_time) at time zone 'Pacific/Auckland';
        else
          v_end_ts := (v_curr_date + v_tpl.end_time) at time zone 'Pacific/Auckland';
        end if;

        for v_slot in 1..greatest(v_tpl.required_staff_count, 1) loop
          if not exists (
            select 1 from public.roster_slots s
            where s.organization_id = v_provider
              and s.work_unit_id = v_unit_id
              and s.scheduled_start = v_start_ts
              and s.notes = 'Generated from shift template: ' || v_tpl.name || ' (' || v_slot || ')'
          ) then
            insert into public.roster_slots(
              organization_id, work_unit_id, staff_id, scheduled_start, scheduled_end,
              status, client_request_id, notes, created_by
            )
            values (
              v_provider, v_unit_id, null, v_start_ts, v_end_ts,
              'draft', gen_random_uuid(),
              'Generated from shift template: ' || v_tpl.name || ' (' || v_slot || ')',
              v_actor
            );
            v_count := v_count + 1;
            v_made_any := true;
          end if;
        end loop;
      end if;
      v_curr_date := v_curr_date + 1;
    end loop;

    if v_made_any then
      v_applied := v_applied + 1;
    end if;
  end loop;

  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (
    v_provider, v_actor, 'roster_generated_from_templates', 'roster_slots', v_provider,
    jsonb_build_object(
      'from_date', p_from_date,
      'to_date', p_to_date,
      'slots_generated', v_count,
      'templates_applied', v_applied,
      'templates_skipped', v_skipped,
      'client_request_id', p_client_request_id
    )
  );

  return query select v_count, v_applied, v_skipped;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."generate_roster_from_templates"(p_client_request_id uuid, p_organization_id uuid, p_from_date date, p_to_date date) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."generate_roster_from_templates"(p_client_request_id uuid, p_organization_id uuid, p_from_date date, p_to_date date) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."generate_roster_from_templates"(p_client_request_id uuid, p_organization_id uuid, p_from_date date, p_to_date date) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."generate_roster_from_templates"(p_client_request_id uuid, p_organization_id uuid, p_from_date date, p_to_date date) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."generate_shift_stops"(p_shift_id uuid, p_shift_date date)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_shift           record;
  v_config          record;
  v_stop_id         uuid;
  v_stop_count      integer := 0;
  v_visit           integer;
  v_visits          integer;
  v_window_open     timestamptz;
  v_window_close    timestamptz;
  v_eff_open        timestamptz;
  v_eff_close       timestamptz;
  v_step            interval;
  v_sla_open        timestamptz;
  v_sla_arrive_by   timestamptz;
  v_sla_depart_by   timestamptz;
  v_day_of_week     integer;
  v_month           integer;
  v_module_count    integer;
  v_windowed        boolean;
BEGIN
  SELECT * INTO v_shift FROM shifts WHERE id = p_shift_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Shift % not found', p_shift_id;
  END IF;

  v_day_of_week := extract(isodow FROM p_shift_date)::integer;
  v_month       := extract(month  FROM p_shift_date)::integer;

  -- Regenerate the contracted (non-adhoc) stops; shift_stop_modules cascade.
  DELETE FROM shift_stops WHERE shift_id = p_shift_id AND is_adhoc = false;

  FOR v_config IN
    SELECT cspc.*
    FROM   client_site_patrol_config cspc
    WHERE  cspc.patrol_route_id = v_shift.patrol_route_id
      AND  cspc.active = true
      AND  cspc.time_window_type <> 'as_attended'
      AND  (array_length(cspc.active_days, 1) IS NULL OR v_day_of_week = ANY(cspc.active_days))
      AND  (array_length(cspc.active_months, 1) IS NULL OR array_length(cspc.active_months, 1) = 0 OR v_month = ANY(cspc.active_months))
    ORDER BY cspc.preferred_stop_order, cspc.id
  LOOP
    v_visits := greatest(coalesce(v_config.visits_per_shift, 1), 1);
    v_windowed := v_config.time_window_type = 'fixed' AND v_config.window_start IS NOT NULL;

    IF v_windowed THEN
      SELECT b.window_open, b.window_close INTO v_window_open, v_window_close
      FROM public.patrol_window_bounds(p_shift_date, v_config.window_start, v_config.window_end, v_shift.scheduled_start, v_shift.scheduled_end) b;
      -- The visits are due inside the part of the contract window this shift actually covers.
      v_eff_open  := greatest(v_window_open, v_shift.scheduled_start);
      v_eff_close := least(coalesce(v_window_close, v_shift.scheduled_end), v_shift.scheduled_end);
      IF v_eff_close <= v_eff_open THEN
        -- The shift sits outside the contracted hours: keep the contract's own window so the breach shows.
        v_eff_open  := v_window_open;
        v_eff_close := coalesce(v_window_close, v_window_open + make_interval(mins => coalesce(v_config.sla_arrive_within_minutes, 30)));
      END IF;
    ELSE
      -- Any time of day: the visits are spread across the shift.
      v_eff_open  := v_shift.scheduled_start;
      v_eff_close := v_shift.scheduled_end;
    END IF;
    v_step := CASE WHEN v_visits > 1 THEN (v_eff_close - v_eff_open) / v_visits ELSE interval '0' END;

    FOR v_visit IN 1..v_visits LOOP
      IF v_windowed THEN
        v_sla_open      := v_eff_open + v_step * (v_visit - 1);
        v_sla_arrive_by := v_sla_open + make_interval(mins => coalesce(v_config.sla_arrive_within_minutes, 30));
        v_sla_depart_by := v_sla_arrive_by + make_interval(mins => coalesce(v_config.sla_depart_within_minutes, 45));
      ELSIF v_visits > 1 THEN
        v_sla_open      := v_eff_open + v_step * (v_visit - 1);
        v_sla_arrive_by := v_sla_open + v_step;
        v_sla_depart_by := NULL;
      ELSE
        v_sla_open      := NULL;
        v_sla_arrive_by := v_shift.scheduled_end;
        v_sla_depart_by := NULL;
      END IF;

      INSERT INTO shift_stops (
        organization_id, shift_id, patrol_config_id, site_id, zone_id, module_key,
        stop_order, visit_number, is_adhoc, sla_window_open, sla_arrive_by, sla_depart_by,
        required_dwell_minutes, officer_instructions, status, sla_status
      ) VALUES (
        v_shift.organization_id, p_shift_id, v_config.id, v_config.site_id, v_config.zone_id, v_config.module_key,
        (v_config.preferred_stop_order * 10) + v_visit, v_visit, false, v_sla_open, v_sla_arrive_by, v_sla_depart_by,
        v_config.dwell_minutes, v_config.officer_instructions, 'pending', 'on_track'
      )
      RETURNING id INTO v_stop_id;

      INSERT INTO shift_stop_modules (organization_id, shift_stop_id, module_key, is_required, service_agreement_module_id, service_agreement_location_id)
      SELECT v_shift.organization_id, v_stop_id, prsm.module_key, prsm.is_required, prsm.service_agreement_module_id, prsm.service_agreement_location_id
      FROM   patrol_route_stop_modules prsm
      WHERE  prsm.patrol_config_id = v_config.id AND prsm.active = true
      ON CONFLICT (shift_stop_id, module_key) DO NOTHING;

      GET DIAGNOSTICS v_module_count = ROW_COUNT;
      IF v_module_count = 0 THEN
        INSERT INTO shift_stop_modules (organization_id, shift_stop_id, module_key, is_required)
        VALUES (v_shift.organization_id, v_stop_id, v_config.module_key, true)
        ON CONFLICT (shift_stop_id, module_key) DO NOTHING;
      END IF;

      v_stop_count := v_stop_count + 1;
    END LOOP;
  END LOOP;

  UPDATE shifts SET total_stops = v_stop_count, generated_at = now() WHERE id = p_shift_id;
  RETURN v_stop_count;
END;
$function$;
COMMENT ON FUNCTION "public"."generate_shift_stops"(p_shift_id uuid, p_shift_date date) IS 'Generates the contracted shift_stops for a patrol shift from client_site_patrol_config on that date. Visits are spread evenly across the part of the contract window the shift covers (each visit has its own open / arrive-by / depart-by); a shift outside the window keeps the contract window so the breach is visible. Dual-writes shift_stop_modules (toolset + contract inheritance from patrol_route_stop_modules).';
REVOKE ALL ON FUNCTION "public"."generate_shift_stops"(p_shift_id uuid, p_shift_date date) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."generate_shift_stops"(p_shift_id uuid, p_shift_date date) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."generate_shift_stops"(p_shift_id uuid, p_shift_date date) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."generate_shift_stops"(p_shift_id uuid, p_shift_date date) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."geofence_area_gate"(p_area_m2 numeric, p_zone_type text)
 RETURNS TABLE(ok boolean, reason text)
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  v_min numeric; v_max numeric;
BEGIN
  CASE coalesce(p_zone_type, '')
    WHEN 'parking', 'parking_enforcement' THEN v_min := 10; v_max := 50000;
    WHEN 'freedom_camping' THEN v_min := 50; v_max := 500000;
    WHEN 'noise_control' THEN v_min := 50; v_max := 2000000;
    WHEN 'patrol_area', 'patrol_route' THEN v_min := 1000; v_max := 100000000;
    WHEN 'site' THEN v_min := 10; v_max := 2000000;
    WHEN 'jurisdiction' THEN v_min := 1000000; v_max := 300000000000;
    ELSE v_min := 10; v_max := 500000;
  END CASE;
  IF p_area_m2 IS NULL OR p_area_m2 <= 0 THEN RETURN QUERY SELECT false, 'invalid_area'; RETURN; END IF;
  IF p_area_m2 < v_min THEN RETURN QUERY SELECT false, format('below_min_area:%sm2<%s', round(p_area_m2), v_min); RETURN; END IF;
  IF p_area_m2 > v_max THEN RETURN QUERY SELECT false, format('above_max_area:%sm2>%s', round(p_area_m2), v_max); RETURN; END IF;
  RETURN QUERY SELECT true, NULL::text;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."geofence_area_gate"(p_area_m2 numeric, p_zone_type text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."geofence_area_gate"(p_area_m2 numeric, p_zone_type text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."geofence_area_gate"(p_area_m2 numeric, p_zone_type text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."geofence_area_gate"(p_area_m2 numeric, p_zone_type text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."geometry_area_m2"(p_geojson jsonb)
 RETURNS numeric
 LANGUAGE sql
 STABLE
AS $function$
  select st_area(st_setsrid(st_geomfromgeojson(p_geojson::text), 4326)::geography)::numeric;
$function$;
COMMENT ON FUNCTION "public"."geometry_area_m2"(p_geojson jsonb) IS 'Read-only real area (square metres, geography cast for accuracy) of a supplied GeoJSON polygon. No writes, no pass/fail gate -- surfaces the actual number so a human can judge whether a shape plausibly matches the named place, since a geofence is a domain-blind boundary, not a zone_type-specific area band.';
REVOKE ALL ON FUNCTION "public"."geometry_area_m2"(p_geojson jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."geometry_area_m2"(p_geojson jsonb) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."geometry_area_m2"(p_geojson jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."geometry_area_m2"(p_geojson jsonb) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."geometry_area_m2"(p_geojson jsonb) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."geometry_area_m2"(p_geojson jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_agreement_billing_basis_summary"(p_service_agreement_id uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_agreement public.service_agreements%ROWTYPE;
  v_from date := coalesce(p_from, date '1970-01-01');
  v_to date := coalesce(p_to, current_date);
  v_result jsonb;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF;
  SELECT * INTO v_agreement FROM public.service_agreements WHERE id = p_service_agreement_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Service agreement not found'; END IF;
  IF NOT public.is_admin_for_org(v_agreement.provider_organization_id) THEN RAISE EXCEPTION 'Finance administrator access required'; END IF;
  IF v_to < v_from THEN RAISE EXCEPTION 'Period end cannot precede period start'; END IF;

  WITH classified AS (
    SELECT to_char(r.service_date, 'YYYY-MM') AS month, r.amount, c.basis, c.conflict
    FROM public.file_import_finance_cost_rows r
    CROSS JOIN LATERAL public.classify_patrol_cost_row_billing_basis(v_agreement.provider_organization_id, r.source_values) c
    WHERE r.service_agreement_id = v_agreement.id AND r.status = 'applied'
      AND r.service_date BETWEEN v_from AND v_to
  ), months AS (
    SELECT month,
      round(coalesce(sum(amount) FILTER (WHERE basis = 'contract'), 0), 2) AS contract_cost,
      round(coalesce(sum(amount) FILTER (WHERE basis = 'extra'), 0), 2) AS extra_cost,
      round(coalesce(sum(amount) FILTER (WHERE basis = 'unclassified'), 0), 2) AS unclassified_cost,
      count(*) FILTER (WHERE basis = 'unclassified')::integer AS unclassified_rows,
      count(*) FILTER (WHERE conflict)::integer AS conflict_rows
    FROM classified WHERE month IS NOT NULL GROUP BY month
  ), dispatch AS (
    SELECT coalesce(line.billing_basis, 'unclassified') AS basis, count(*)::integer AS lines,
      round(coalesce(sum(line.line_total), 0), 2) AS total,
      round(coalesce(sum(line.line_total) FILTER (WHERE line.invoice_line_item_id IS NULL), 0), 2) AS uninvoiced_total
    FROM public.dispatch_job_charge_lines line
    WHERE line.service_agreement_id = v_agreement.id AND line.created_at::date BETWEEN v_from AND v_to
    GROUP BY 1
  ), orders AS (
    SELECT o.id, o.reference, o.title, o.starts_on, o.ends_on,
      count(line.id)::integer AS charge_lines, round(coalesce(sum(line.line_total), 0), 2) AS charge_total
    FROM public.agreement_extra_work_orders o
    LEFT JOIN public.dispatch_job_charge_lines line ON line.extra_work_order_id = o.id AND line.created_at::date BETWEEN v_from AND v_to
    WHERE o.service_agreement_id = v_agreement.id
    GROUP BY o.id
  ), price AS (
    SELECT count(*)::integer AS lines, round(sum(ql.quantity * ql.unit_charge), 2) AS total
    FROM public.quotes q JOIN public.quote_lines ql ON ql.quote_id = q.id
    WHERE q.service_agreement_id = v_agreement.id AND q.status = 'accepted'
  )
  SELECT jsonb_build_object(
    'service_agreement_id', v_agreement.id,
    'period_from', p_from, 'period_to', p_to,
    'commercial', (SELECT jsonb_build_object(
        'commercial_model', c.commercial_model,
        'uses_contract_extra', public.agreement_uses_contract_extra(v_agreement.id),
        'billing_cycle', c.billing_cycle, 'payment_terms_days', c.payment_terms_days, 'currency', c.currency,
        'base_rate_per_hour', c.base_rate_per_hour, 'overtime_rate_per_hour', c.overtime_rate_per_hour,
        'callout_rate_per_hour', c.callout_rate_per_hour, 'callout_minimum_hours', c.callout_minimum_hours,
        'travel_rate_per_km', c.travel_rate_per_km, 'invoice_email', c.invoice_email,
        'purchase_order_number', c.purchase_order_number, 'notes', c.notes, 'updated_at', c.updated_at,
        'standing_authority_limit', c.standing_authority_limit,
        'fee_overrun_policy', c.fee_overrun_policy,
        'jobs_over_standing_authority_without_approval', CASE WHEN c.commercial_model = 'do_and_invoice' AND c.standing_authority_limit IS NOT NULL THEN
          (SELECT count(*)::integer FROM public.dispatch_jobs job
            WHERE job.service_agreement_id = v_agreement.id AND job.client_order_reference IS NULL
              AND public.dispatch_job_over_standing_authority(job.id, c.standing_authority_limit)
              AND EXISTS (SELECT 1 FROM public.dispatch_job_charge_lines l WHERE l.source_dispatch_id = job.id AND l.invoice_line_item_id IS NULL)) END)
      FROM (SELECT 1) one LEFT JOIN public.crm_commercial_settings c ON c.service_agreement_id = v_agreement.id),
    'agreement_price', (SELECT CASE WHEN lines = 0 THEN NULL ELSE jsonb_build_object('source', 'accepted_quote_lines', 'lines', lines, 'total', total) END FROM price),
    'imported_cost_months', coalesce((SELECT jsonb_agg(to_jsonb(m) ORDER BY m.month) FROM months m), '[]'::jsonb),
    'imported_cost_totals', (SELECT jsonb_build_object(
        'contract_cost', coalesce(sum(contract_cost), 0), 'extra_cost', coalesce(sum(extra_cost), 0),
        'unclassified_cost', coalesce(sum(unclassified_cost), 0), 'unclassified_rows', coalesce(sum(unclassified_rows), 0),
        'conflict_rows', coalesce(sum(conflict_rows), 0)) FROM months),
    'dispatch_charge_lines', coalesce((SELECT jsonb_agg(to_jsonb(d) ORDER BY d.basis) FROM dispatch d), '[]'::jsonb),
    'extra_work_orders', coalesce((SELECT jsonb_agg(jsonb_build_object('id', o.id, 'reference', o.reference, 'title', o.title,
        'starts_on', o.starts_on, 'ends_on', o.ends_on, 'charge_lines', o.charge_lines, 'charge_total', o.charge_total) ORDER BY o.reference) FROM orders o), '[]'::jsonb),
    'basis_rule', 'Imported rows use the workbook TYPE column when present, otherwise the provider charge-code catalog basis; amounts are recorded service cost (job + travel), not invoiced revenue.'
  ) INTO v_result;
  RETURN v_result;
END;
$function$;
COMMENT ON FUNCTION "public"."get_agreement_billing_basis_summary"(p_service_agreement_id uuid, p_from date, p_to date) IS 'Read-only, provider-admin only: the agreement commercial model and terms (including the do-and-invoice standing authority limit and jobs over it still awaiting client approval), contracted vs Extra vs unclassified per month for one service agreement (imported patrol cost rows classified by classify_patrol_cost_row_billing_basis), dispatch charge lines by billing basis, Extra works orders, and the accepted-quote agreement price (null when not recorded).';
REVOKE ALL ON FUNCTION "public"."get_agreement_billing_basis_summary"(p_service_agreement_id uuid, p_from date, p_to date) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_agreement_billing_basis_summary"(p_service_agreement_id uuid, p_from date, p_to date) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_agreement_billing_basis_summary"(p_service_agreement_id uuid, p_from date, p_to date) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_agreement_billing_basis_summary"(p_service_agreement_id uuid, p_from date, p_to date) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_agreement_fee_drawdown"(p_service_agreement_id uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_agreement public.service_agreements%ROWTYPE;
  v_comm public.crm_commercial_settings%ROWTYPE;
  v_today date := (now() AT TIME ZONE 'Pacific/Auckland')::date;
  v_to date := date_trunc('month', coalesce(p_to, v_today))::date;
  v_from date := date_trunc('month', coalesce(p_from, (coalesce(p_to, v_today) - interval '11 months')::date))::date;
  v_months jsonb := '[]'::jsonb;
  v_month date;
  v_first jsonb;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF;
  SELECT * INTO v_agreement FROM public.service_agreements WHERE id = p_service_agreement_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Service agreement not found'; END IF;
  IF NOT public.is_admin_for_org(v_agreement.provider_organization_id) THEN RAISE EXCEPTION 'Finance administrator access required'; END IF;
  IF v_to < v_from THEN RAISE EXCEPTION 'Period end cannot precede period start'; END IF;
  IF v_from < (v_to - interval '35 months')::date THEN RAISE EXCEPTION 'Choose up to 36 months'; END IF;
  SELECT * INTO v_comm FROM public.crm_commercial_settings WHERE service_agreement_id = v_agreement.id;

  IF coalesce(v_comm.commercial_model, '') = 'fixed_price_with_extras' THEN
    v_month := v_to;
    WHILE v_month >= v_from LOOP
      v_months := v_months || public.agreement_fee_drawdown_month(v_agreement.id, v_month);
      v_month := (v_month - interval '1 month')::date;
    END LOOP;
  END IF;
  v_first := v_months->0;

  RETURN jsonb_build_object(
    'service_agreement_id', v_agreement.id,
    'commercial_model', v_comm.commercial_model,
    'applies', coalesce(v_comm.commercial_model, '') = 'fixed_price_with_extras',
    'fee', v_first->'fee', 'fee_source', v_first->'fee_source',
    'overrun_policy', CASE WHEN coalesce(v_comm.commercial_model, '') = 'fixed_price_with_extras' THEN coalesce(v_comm.fee_overrun_policy, 'justify') END,
    'period_from', v_from, 'period_to', (v_to + interval '1 month - 1 day')::date,
    'months', v_months);
END;
$function$;
COMMENT ON FUNCTION "public"."get_agreement_fee_drawdown"(p_service_agreement_id uuid, p_from date, p_to date) IS 'Read-only, provider-admin only: for a fixed price plus Extra agreement, the monthly fee drawdown per calendar month (newest first, default the last 12, up to 36): fee, contracted work by source, balance, credit/overrun/balanced, blockers and the settling invoice. applies is false (no months) for other billing models.';
REVOKE ALL ON FUNCTION "public"."get_agreement_fee_drawdown"(p_service_agreement_id uuid, p_from date, p_to date) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_agreement_fee_drawdown"(p_service_agreement_id uuid, p_from date, p_to date) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_agreement_fee_drawdown"(p_service_agreement_id uuid, p_from date, p_to date) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_agreement_fee_drawdown"(p_service_agreement_id uuid, p_from date, p_to date) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_agreement_service_delivery"(p_agreement_id uuid, p_period_start date, p_period_end date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_agreement public.service_agreements%rowtype;
  v_profile public.user_profiles%rowtype;
begin
  if v_actor is null then raise exception 'Authentication required'; end if;
  if p_period_start is null or p_period_end is null or p_period_start > p_period_end or p_period_end - p_period_start > 92 then
    raise exception 'Choose a period of up to 92 days';
  end if;
  select * into v_agreement from public.service_agreements a where a.id = p_agreement_id;
  if not found then raise exception 'Service agreement not found'; end if;
  select * into v_profile from public.user_profiles p where p.id = v_actor and p.deactivated_at is null;
  if not found then raise exception 'Active profile required'; end if;

  -- The client sees delivery for its own agreement when the portal is switched on; provider administrators and branch managers always can.
  if not (
    public.is_admin_for_org(v_agreement.provider_organization_id)
    or exists (
      select 1 from public.staff_branch_authorisations a
      where a.user_id = v_actor and a.status = 'active' and a.branch_org_id = v_agreement.provider_organization_id
        and a.role_at_branch in ('branch_manager', 'admin', 'master')
    )
    or (v_profile.organization_id = v_agreement.client_organization_id
        and v_profile.role in ('client_admin', 'client_officer', 'client_viewer', 'master', 'admin', 'admin_officer')
        and v_agreement.client_portal_access_mode in ('transparency_only', 'full_modules'))
  ) then
    raise exception 'Not authorised to view delivery for this agreement';
  end if;

  return public.agreement_service_delivery(p_agreement_id, p_period_start, p_period_end);
end;
$function$;
COMMENT ON FUNCTION "public"."get_agreement_service_delivery"(p_agreement_id uuid, p_period_start date, p_period_end date) IS 'Client portal / provider read: what was delivered at the agreement''s places in a period (up to 92 days, shifts due so far) — patrol stops visited, static post attendances and hours on post, last presence. Client users of the agreement (portal transparency_only or full_modules) and provider administrators and branch managers only. No officer identities.';
REVOKE ALL ON FUNCTION "public"."get_agreement_service_delivery"(p_agreement_id uuid, p_period_start date, p_period_end date) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_agreement_service_delivery"(p_agreement_id uuid, p_period_start date, p_period_end date) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_agreement_service_delivery"(p_agreement_id uuid, p_period_start date, p_period_end date) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_agreement_service_delivery"(p_agreement_id uuid, p_period_start date, p_period_end date) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_agreement_service_delivery_summary"(p_agreement_ids uuid[], p_from timestamp with time zone, p_to timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare v_id uuid; v_result jsonb := '[]'::jsonb;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if p_from is null or p_to is null or p_to <= p_from or p_to - p_from > interval '3660 days' then
    raise exception 'A valid reporting window is required';
  end if;
  if coalesce(cardinality(p_agreement_ids), 0) > 100 then raise exception 'Too many agreements'; end if;
  for v_id in select distinct unnest(p_agreement_ids) loop
    if not exists (
      select 1 from public.service_agreements a where a.id = v_id
        and public.is_report_provider_custodian_for_org(a.provider_organization_id)
    ) then raise exception 'Provider report access required'; end if;
    v_result := v_result || jsonb_build_array(public.report_service_delivery_summary(v_id, p_from, p_to));
  end loop;
  return v_result;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."get_agreement_service_delivery_summary"(p_agreement_ids uuid[], p_from timestamp with time zone, p_to timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_agreement_service_delivery_summary"(p_agreement_ids uuid[], p_from timestamp with time zone, p_to timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_agreement_service_delivery_summary"(p_agreement_ids uuid[], p_from timestamp with time zone, p_to timestamp with time zone) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."get_approvals_activity"(p_limit integer DEFAULT 50, p_offset integer DEFAULT 0, p_statuses text[] DEFAULT NULL::text[], p_action_types text[] DEFAULT NULL::text[])
 RETURNS TABLE(id uuid, action_type text, status text, bob_reasoning text, confidence_score real, context_table text, context_summary text, created_at timestamp with time zone, applied_at timestamp with time zone, approved_at timestamp with time zone, proposed_payload jsonb, amended_payload jsonb, organization_id uuid, org_name text, triggered_by uuid, triggered_by_name text, user_id uuid, user_name text, approved_by uuid, approved_by_name text, rejection_reason text, error_message text, result_table text, result_record_id uuid, assigned_approver_id uuid, assigned_approver_name text, can_decide boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid:=auth.uid();
  v_role text;
  v_org_id uuid;
begin
  if v_user_id is null then return; end if;
  select up.role,up.organization_id into v_role,v_org_id from public.user_profiles up where up.id=v_user_id;
  if v_role is null then return; end if;
  return query
  select a.id,a.action_type,a.status,a.bob_reasoning,a.confidence_score,a.context_table,a.context_summary,a.created_at,a.applied_at,a.approved_at,a.proposed_payload,a.amended_payload,a.organization_id,o.name,
    a.triggered_by,(select up1.display_name from public.user_profiles up1 where up1.id=a.triggered_by),
    a.user_id,(select up2.display_name from public.user_profiles up2 where up2.id=a.user_id),
    a.approved_by,(select up3.display_name from public.user_profiles up3 where up3.id=a.approved_by),
    a.rejection_reason,a.error_message,a.result_table,a.result_record_id,a.assigned_approver_id,
    (select up4.display_name from public.user_profiles up4 where up4.id=a.assigned_approver_id),
    case when a.status not in('pending','pending_approval','proposed') then false when v_role='grand_master' then true when v_role in('master','admin', 'admin_officer') then public.can_approve_action(v_user_id,a.organization_id) else false end
  from public.bob_agentic_actions a left join public.organizations o on o.id=a.organization_id
  where (a.triggered_by=v_user_id or a.user_id=v_user_id or a.assigned_approver_id=v_user_id or v_role='grand_master' or (v_role in('master','admin', 'admin_officer') and public.is_admin_for_org(a.organization_id)))
    and (p_statuses is null or a.status=any(p_statuses)) and (p_action_types is null or a.action_type=any(p_action_types))
  order by case when a.status in('pending','proposed','pending_approval') then 0 else 1 end,a.created_at desc limit p_limit offset p_offset;
end;
$function$;
COMMENT ON FUNCTION "public"."get_approvals_activity"(p_limit integer, p_offset integer, p_statuses text[], p_action_types text[]) IS 'Full-lifecycle approvals activity with explicit assigned decision owner and caller authority.';
REVOKE ALL ON FUNCTION "public"."get_approvals_activity"(p_limit integer, p_offset integer, p_statuses text[], p_action_types text[]) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_approvals_activity"(p_limit integer, p_offset integer, p_statuses text[], p_action_types text[]) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_approvals_activity"(p_limit integer, p_offset integer, p_statuses text[], p_action_types text[]) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_approvals_activity"(p_limit integer, p_offset integer, p_statuses text[], p_action_types text[]) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_bob_active_signing_identity"()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(
    (
      select jsonb_build_object(
        'provider', provider,
        'key_name', key_name,
        'fingerprint_sha256', fingerprint_sha256,
        'enabled', enabled
      )
      from public.bob_signing_identities
      where provider = 'gitea' and enabled = true
      order by created_at desc
      limit 1
    ),
    jsonb_build_object('provider','gitea','enabled',false)
  );
$function$;
REVOKE ALL ON FUNCTION "public"."get_bob_active_signing_identity"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_bob_active_signing_identity"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_bob_active_signing_identity"() TO "authenticated";
