CREATE OR REPLACE FUNCTION "public"."get_bob_roster_fill_candidates"(p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone)
 RETURNS TABLE(roster_slot_id uuid, work_unit_id uuid, scheduled_start timestamp with time zone, scheduled_end timestamp with time zone, staff_id uuid, score numeric, rationale text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_admin_for_org(p_organization_id) then
    raise exception 'Active roster administrator required';
  end if;

  if p_to <= p_from or p_to - p_from > interval '31 days' then
    raise exception 'Roster planning window must be greater than zero and no more than 31 days';
  end if;

  return query
  select
    slot.id,
    slot.work_unit_id,
    slot.scheduled_start,
    slot.scheduled_end,
    staff.id,
    (
      100
      - coalesce((now()::date - staff.seniority_date) / 3650.0, 0)
      - coalesce((select count(*) from public.roster_slots assigned where assigned.staff_id = staff.id and assigned.status not in ('declined', 'cancelled') and assigned.scheduled_start >= p_from and assigned.scheduled_start < p_to), 0) * 3
    )::numeric(8,2),
    concat_ws('; ',
      'work-ready',
      'current credentials/training required by roster gate',
      'available',
      'fatigue clear',
      case when staff.seniority_date is null then 'seniority date unavailable' else 'balanced by current scheduled load and seniority' end
    )
  from public.roster_slots slot
  join public.staff_profiles staff on staff.organization_id = slot.organization_id
  where slot.organization_id = p_organization_id
    and slot.staff_id is null
    and slot.status = 'draft'
    and slot.scheduled_start >= p_from
    and slot.scheduled_start < p_to
    and staff.work_ready = true
    and staff.overtime_eligible = true
    and (staff.end_date is null or staff.end_date >= (slot.scheduled_start at time zone 'Pacific/Auckland')::date)
    and not public.staff_has_roster_availability_conflict(staff.id, slot.scheduled_start, slot.scheduled_end)
    and public.staff_fatigue_conflict(staff.id, slot.scheduled_start, slot.scheduled_end, slot.id) is null
    and not exists (
      select 1 from public.roster_slots occupied
      where occupied.staff_id = staff.id
        and occupied.status not in ('declined', 'cancelled')
        and tstzrange(occupied.scheduled_start, occupied.scheduled_end, '[)')
            && tstzrange(slot.scheduled_start, slot.scheduled_end, '[)')
    )
  order by slot.scheduled_start, score desc, staff.seniority_date asc nulls last, staff.id;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."get_bob_roster_fill_candidates"(p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_bob_roster_fill_candidates"(p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_bob_roster_fill_candidates"(p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_bob_roster_fill_candidates"(p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_boundary_history"(p_entity_type text, p_entity_id uuid)
 RETURNS TABLE(id uuid, entity_type text, entity_id uuid, boundary_source text, verification_state text, verified_by uuid, verified_at timestamp with time zone, changed_by uuid, changed_via text, change_reason text, version integer, created_at timestamp with time zone, has_boundary boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_org_id uuid;
begin
  if p_entity_type='organization' then
    if not public.org_access_allowed(p_entity_id) then raise exception 'get_boundary_history: access denied for organization %',p_entity_id;end if;
  elsif p_entity_type='location_zone' then
    select z.organization_id into v_org_id from public.location_zones z where z.id=p_entity_id;
    if not found or not public.org_access_allowed(v_org_id) then raise exception 'get_boundary_history: access denied for location_zone %',p_entity_id;end if;
  elsif p_entity_type='client_site' then
    select s.client_organization_id into v_org_id from public.client_sites s where s.id=p_entity_id;
    if not found or not public.org_access_allowed(v_org_id) then raise exception 'get_boundary_history: access denied for client_site %',p_entity_id;end if;
  else raise exception 'get_boundary_history: unknown entity_type "%"',p_entity_type;
  end if;
  return query select h.id,h.entity_type,h.entity_id,h.boundary_source,h.verification_state,h.verified_by,h.verified_at,h.changed_by,h.changed_via,h.change_reason,h.version,h.created_at,(h.boundary is not null)
  from public.geofence_boundary_history h where h.entity_type=p_entity_type and h.entity_id=p_entity_id order by h.created_at desc,h.version desc;
end;$function$;
COMMENT ON FUNCTION "public"."get_boundary_history"(p_entity_type text, p_entity_id uuid) IS 'Returns the ordered boundary history for a geofence-bearing entity (newest first). Org-access-gated. Does not return the full geometry blob (has_boundary flag instead). Phase 4 geofence redesign (#226). A history-viewer UI is deferred to a fast-follow.';
REVOKE ALL ON FUNCTION "public"."get_boundary_history"(p_entity_type text, p_entity_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_boundary_history"(p_entity_type text, p_entity_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_boundary_history"(p_entity_type text, p_entity_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_boundary_history"(p_entity_type text, p_entity_id uuid) TO "service_role";

