CREATE OR REPLACE FUNCTION "public"."get_callout_pay_summary"(p_callout_id uuid)
 RETURNS TABLE(callout_id uuid, worked_hours numeric, minimum_pay_hours numeric, payable_hours numeric, minimum_applied boolean, response_minutes numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_callout public.callout_shifts%rowtype;
  v_worked numeric;
begin
  select c.* into v_callout from public.callout_shifts c where c.id = p_callout_id;
  if not found then
    raise exception 'Callout not found';
  end if;

  if not public.is_admin_for_org(v_callout.organization_id) and v_callout.officer_user_id <> auth.uid() then
    raise exception 'Not authorised to view this callout';
  end if;

  v_worked := case
    when v_callout.work_started_at is null or v_callout.work_ended_at is null then 0
    else extract(epoch from (v_callout.work_ended_at - v_callout.work_started_at)) / 3600.0
  end;

  return query select
    v_callout.id,
    round(v_worked, 2),
    v_callout.minimum_pay_hours,
    round(greatest(v_worked, v_callout.minimum_pay_hours), 2),
    v_worked < v_callout.minimum_pay_hours,
    case
      when v_callout.callout_received_at is null or v_callout.arrived_at is null then null
      else round(extract(epoch from (v_callout.arrived_at - v_callout.callout_received_at)) / 60.0, 1)
    end;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."get_callout_pay_summary"(p_callout_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_callout_pay_summary"(p_callout_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_callout_pay_summary"(p_callout_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_callout_pay_summary"(p_callout_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_cctv_batch_report_data"(p_organization_id uuid, p_batch_id text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH batch_evidence AS (
    SELECT
      evidence.id AS evidence_item_id,
      evidence.metadata,
      NULLIF(evidence.metadata->'desktop_review_batch'->>'clip_index', '')::integer AS clip_index
    FROM public.evidence_items evidence
    WHERE evidence.organization_id = p_organization_id
      AND evidence.metadata->'desktop_review_batch'->>'batch_id' = p_batch_id
      AND public.org_access_allowed(evidence.organization_id)
  ),
  batch_jobs AS (
    SELECT DISTINCT ON (job.evidence_item_id)
      job.id AS job_id,
      job.evidence_item_id,
      job.status,
      evidence.clip_index
    FROM public.inference_jobs job
    JOIN batch_evidence evidence ON evidence.evidence_item_id = job.evidence_item_id
    WHERE job.organization_id = p_organization_id
      AND job.domain IN ('video_motion', 'vehicle', 'face')
    ORDER BY job.evidence_item_id, job.created_at DESC
  ),
  latest_results AS (
    SELECT DISTINCT ON (result.inference_job_id)
      result.inference_job_id,
      result.result->'consolidated_events' AS consolidated,
      COALESCE((result.result->>'total_frames_parsed')::integer, 0) AS total_frames_parsed
    FROM public.inference_results result
    JOIN batch_jobs job ON job.job_id = result.inference_job_id
    ORDER BY result.inference_job_id, result.created_at DESC
  ),
  observations AS (
    SELECT
      job.job_id,
      job.clip_index,
      observation.kind,
      observation.value
    FROM batch_jobs job
    JOIN latest_results result ON result.inference_job_id = job.job_id
    CROSS JOIN LATERAL (
      SELECT 'Person'::text AS kind, value
      FROM jsonb_array_elements(COALESCE(result.consolidated->'person_events', '[]'::jsonb)) value
      UNION ALL
      SELECT 'Face'::text, value
      FROM jsonb_array_elements(COALESCE(result.consolidated->'face_events', '[]'::jsonb)) value
      UNION ALL
      SELECT 'Vehicle'::text, value
      FROM jsonb_array_elements(COALESCE(result.consolidated->'vehicle_events', '[]'::jsonb)) value
    ) observation
  ),
  image_candidates AS (
    SELECT
      observation.job_id,
      observation.clip_index,
      observation.kind,
      observation.value->>'thumbnail' AS src,
      COALESCE(observation.value->>'subject_label', observation.value->>'plate', observation.kind || ' observation') AS label,
      COALESCE((observation.value->>'first_seen_seconds')::numeric, 0) AS timestamp_seconds,
      observation.value->>'best_frame_hash' AS sha256_hash,
      row_number() OVER (ORDER BY observation.clip_index NULLS LAST, COALESCE((observation.value->>'first_seen_seconds')::numeric, 0)) AS image_rank
    FROM observations observation
    WHERE observation.value->>'thumbnail' LIKE 'data:image/%'
  )
  SELECT jsonb_build_object(
    'batch_id', p_batch_id,
    'clip_count', (SELECT count(*) FROM batch_evidence),
    'loaded_clip_count', (SELECT count(*) FROM batch_jobs),
    'complete', (SELECT count(*) FROM batch_evidence) = (SELECT count(*) FROM batch_jobs),
    'frame_count', COALESCE((SELECT sum(total_frames_parsed) FROM latest_results), 0),
    'observations', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'job_id', job_id,
        'clip_index', clip_index,
        'kind', kind,
        'event_id', value->>'event_id',
        'label', COALESCE(value->>'subject_label', value->>'plate', kind || ' observation'),
        'confidence', value->'confidence',
        'start_seconds', value->'first_seen_seconds',
        'end_seconds', value->'last_seen_seconds',
        'best_frame_hash', value->>'best_frame_hash',
        'review_required', COALESCE((value->>'review_required')::boolean, true)
      ) ORDER BY clip_index NULLS LAST, COALESCE((value->>'first_seen_seconds')::numeric, 0))
      FROM observations
    ), '[]'::jsonb),
    'evidence_images', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'src', src,
        'label', label,
        'timestamp_seconds', timestamp_seconds,
        'sha256_hash', sha256_hash,
        'review_state', 'Review required'
      ) ORDER BY image_rank)
      FROM image_candidates
      WHERE image_rank <= 6
    ), '[]'::jsonb)
  );
$function$;
REVOKE ALL ON FUNCTION "public"."get_cctv_batch_report_data"(p_organization_id uuid, p_batch_id text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_cctv_batch_report_data"(p_organization_id uuid, p_batch_id text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_cctv_batch_report_data"(p_organization_id uuid, p_batch_id text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_cctv_batch_report_data"(p_organization_id uuid, p_batch_id text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_cctv_console_import_detail"(p_import_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org_id uuid;
  v_result jsonb;
BEGIN
  SELECT organization_id INTO v_org_id FROM public.cctv_imports WHERE id = p_import_id;
  IF v_org_id IS NULL OR (auth.role() NOT IN ('service_role') AND session_user NOT IN ('postgres', 'supabase_admin')
     AND (auth.uid() IS NULL OR NOT public.org_access_allowed(v_org_id))) THEN
    RAISE EXCEPTION 'CCTV import detail access denied';
  END IF;

  WITH evidence AS (
    SELECT item.* FROM public.evidence_items item
    WHERE item.organization_id = v_org_id AND item.cctv_import_id = p_import_id
  )
  SELECT jsonb_build_object(
    'evidence', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'id', item.id, 'storage_path', item.storage_path, 'captured_at', item.captured_at,
        'metadata', item.metadata, 'sha256_hash', item.sha256_hash, 'is_court_ready', item.is_court_ready,
        'locked_at', item.locked_at, 'retention_hold', item.retention_hold
      ) ORDER BY item.captured_at) FROM evidence item
    ), '[]'::jsonb),
    'marks', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'id', event.id, 'source', event.source, 'source_ref', event.source_ref,
        'event_start_at', event.event_start_at, 'event_end_at', event.event_end_at,
        'severity', event.severity, 'thumbnail_path', event.thumbnail_path, 'metadata', event.metadata
      ) ORDER BY event.event_start_at)
      FROM (SELECT * FROM public.cctv_device_events WHERE cctv_import_id = p_import_id ORDER BY event_start_at LIMIT 5000) event
    ), '[]'::jsonb),
    'observations', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'id', observation.id, 'evidence_item_id', observation.evidence_item_id, 'cctv_import_id', observation.cctv_import_id,
        'source_event_id', observation.source_event_id, 'entity_kind', observation.entity_kind,
        'observed_at', observation.observed_at, 'observed_to', observation.observed_to,
        'candidate_label', observation.candidate_label, 'candidate_plate', observation.candidate_plate,
        'animal_type', observation.animal_type, 'species_confidence', observation.species_confidence, 'is_pest', observation.is_pest,
        'model_confidence', observation.model_confidence, 'quality_state', observation.quality_state,
        'attributes', observation.attributes, 'thumbnail', observation.thumbnail,
        'review_state', observation.review_state, 'portfolio_key', observation.portfolio_key,
        'portfolio_state', observation.portfolio_state, 'portfolio_candidates', observation.portfolio_candidates,
        'person_record_id', observation.person_record_id, 'canonical_person_id', observation.canonical_person_id,
        'canonical_vehicle_id', observation.canonical_vehicle_id, 'reviewed_at', observation.reviewed_at,
        'review_notes', observation.review_notes,
        'person_records', CASE WHEN person.id IS NULL THEN NULL ELSE jsonb_build_object('display_name', person.display_name, 'metadata', person.metadata) END
      ) ORDER BY observation.observed_at)
      FROM (SELECT * FROM public.cctv_entity_observations
            WHERE organization_id = v_org_id AND cctv_import_id = p_import_id AND review_state <> 'superseded'
            ORDER BY observed_at LIMIT 2000) observation
      LEFT JOIN public.person_records person ON person.id = observation.person_record_id
    ), '[]'::jsonb),
    'jobs', coalesce((
      SELECT jsonb_agg(jsonb_build_object('id', job.id, 'evidence_item_id', job.evidence_item_id, 'status', job.status))
      FROM public.inference_jobs job JOIN evidence item ON item.id = job.evidence_item_id
      WHERE job.domain = 'video_motion'
    ), '[]'::jsonb),
    'synopses', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'evidence_id', synopsis.evidence_id, 'approval_status', synopsis.approval_status,
        'generated_summary', synopsis.generated_summary, 'generated_at', synopsis.generated_at
      ) ORDER BY synopsis.generated_at DESC)
      FROM public.evidence_summary_approvals synopsis JOIN evidence item ON item.id = synopsis.evidence_id
      WHERE synopsis.generated_mode = 'cctv_vision_llm_scene_synopsis'
    ), '[]'::jsonb)
  ) INTO v_result;
  RETURN v_result;
END;
$function$;
COMMENT ON FUNCTION "public"."get_cctv_console_import_detail"(p_import_id uuid) IS 'Tenant-authorized, snapshot-consistent CCTV console detail: evidence, timeline marks, review events, job states, and scene synopses in one read.';
REVOKE ALL ON FUNCTION "public"."get_cctv_console_import_detail"(p_import_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_cctv_console_import_detail"(p_import_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_cctv_console_import_detail"(p_import_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_cctv_console_import_detail"(p_import_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_cctv_face_observation_links"(p_organization_id uuid, p_evidence_item_id uuid)
 RETURNS TABLE(id uuid, person_record_id uuid, metadata jsonb)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT observation.id, observation.person_record_id,
    observation.metadata - ARRAY['embedding','face_embedding','candidate_embedding','appearance_embedding']::text[]
