GRANT EXECUTE ON FUNCTION "public"."get_cctv_face_observation_links"(p_organization_id uuid, p_evidence_item_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_cctv_face_observation_links"(p_organization_id uuid, p_evidence_item_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_cctv_face_observation_links"(p_organization_id uuid, p_evidence_item_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_cctv_oversized_thumbnails"(p_limit integer DEFAULT 5)
 RETURNS TABLE(observation_id uuid, thumbnail text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.role() <> 'service_role' AND session_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;
  RETURN QUERY
  SELECT observation.id,
         coalesce(
           CASE WHEN observation.thumbnail IS NOT NULL AND octet_length(observation.thumbnail) > 80000 THEN observation.thumbnail END,
           CASE observation.entity_kind
             WHEN 'vehicle' THEN jsonb_path_query_first(result.result, '$.consolidated_events.vehicle_events[*] ? (@.event_id == $event)', jsonb_build_object('event', to_jsonb(observation.source_event_id)))->>'thumbnail'
             WHEN 'animal' THEN jsonb_path_query_first(result.result, '$.consolidated_events.animal_events[*] ? (@.event_id == $event)', jsonb_build_object('event', to_jsonb(observation.source_event_id)))->>'thumbnail'
             WHEN 'person' THEN coalesce(
               jsonb_path_query_first(result.result, '$.consolidated_events.person_events[*] ? (@.event_id == $event)', jsonb_build_object('event', to_jsonb(observation.source_event_id)))->>'thumbnail',
               jsonb_path_query_first(result.result, '$.consolidated_events.face_events[*] ? (@.event_id == $event)', jsonb_build_object('event', to_jsonb(observation.source_event_id)))->>'thumbnail'
             )
           END
         ) AS thumbnail
  FROM public.cctv_entity_observations observation
  LEFT JOIN LATERAL (
    SELECT stored.result
    FROM public.inference_results stored
    WHERE stored.inference_job_id = observation.inference_job_id AND stored.domain = 'video_motion'
    ORDER BY stored.created_at DESC
    LIMIT 1
  ) result ON true
  WHERE observation.review_state <> 'superseded'
    AND (observation.thumbnail IS NULL OR octet_length(observation.thumbnail) > 80000)
    AND coalesce(
      CASE WHEN observation.thumbnail IS NOT NULL AND octet_length(observation.thumbnail) > 80000 THEN observation.thumbnail END,
      CASE observation.entity_kind
        WHEN 'vehicle' THEN jsonb_path_query_first(result.result, '$.consolidated_events.vehicle_events[*] ? (@.event_id == $event)', jsonb_build_object('event', to_jsonb(observation.source_event_id)))->>'thumbnail'
        WHEN 'animal' THEN jsonb_path_query_first(result.result, '$.consolidated_events.animal_events[*] ? (@.event_id == $event)', jsonb_build_object('event', to_jsonb(observation.source_event_id)))->>'thumbnail'
        WHEN 'person' THEN coalesce(
          jsonb_path_query_first(result.result, '$.consolidated_events.person_events[*] ? (@.event_id == $event)', jsonb_build_object('event', to_jsonb(observation.source_event_id)))->>'thumbnail',
          jsonb_path_query_first(result.result, '$.consolidated_events.face_events[*] ? (@.event_id == $event)', jsonb_build_object('event', to_jsonb(observation.source_event_id)))->>'thumbnail'
        )
      END
    ) LIKE 'data:image/%'
  ORDER BY observation.created_at, observation.id
  LIMIT least(greatest(coalesce(p_limit, 5), 1), 20);
END;
$function$;
REVOKE ALL ON FUNCTION "public"."get_cctv_oversized_thumbnails"(p_limit integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_cctv_oversized_thumbnails"(p_limit integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_cctv_oversized_thumbnails"(p_limit integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_cctv_review_person_records"(p_organization_id uuid)
 RETURNS TABLE(id uuid, display_name text, review_state text, metadata jsonb)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  WITH access AS (
    SELECT public.can_access_person_contacts(p_organization_id) AS contacts,
      public.can_search_people(p_organization_id) AS lookup
  )
  SELECT person.id, person.display_name, person.review_state,
    CASE WHEN access.contacts
      THEN person.metadata - 'face_reference' - 'embedding' - 'candidate_embedding' - 'appearance_embedding'
      ELSE jsonb_strip_nulls(jsonb_build_object(
        'origin', person.metadata->'origin',
        'created_from', person.metadata->'created_from',
        'merged_into_person_record_id', person.metadata->'merged_into_person_record_id',
        'resolved_into_person_record_id', person.metadata->'resolved_into_person_record_id'))
    END
  FROM public.person_records person
  CROSS JOIN access
  WHERE person.organization_id = p_organization_id
    AND auth.uid() IS NOT NULL
    AND access.lookup
    AND public.org_access_allowed(p_organization_id)
  ORDER BY person.created_at
$function$;
REVOKE ALL ON FUNCTION "public"."get_cctv_review_person_records"(p_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_cctv_review_person_records"(p_organization_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_cctv_review_person_records"(p_organization_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_cctv_review_person_records"(p_organization_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_cctv_vehicle_note"(p_observation_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_obs public.cctv_entity_observations%rowtype;
BEGIN
  SELECT * INTO v_obs FROM public.cctv_entity_observations WHERE id = p_observation_id;
  IF v_obs.id IS NULL THEN RETURN NULL; END IF;
  IF auth.uid() IS NULL OR NOT public.org_access_allowed(v_obs.organization_id) THEN RETURN NULL; END IF;
  IF v_obs.canonical_vehicle_id IS NULL THEN RETURN NULL; END IF;
  RETURN (SELECT org_notes -> v_obs.organization_id::text ->> 'text' FROM public.canonical_vehicles WHERE id = v_obs.canonical_vehicle_id);
END;
$function$;
COMMENT ON FUNCTION "public"."get_cctv_vehicle_note"(p_observation_id uuid) IS 'Returns only the calling organisation''s own note for the vehicle behind this observation - never another org''s note. Definer read, since canonical_vehicles stays Bob-only at the table.';
REVOKE ALL ON FUNCTION "public"."get_cctv_vehicle_note"(p_observation_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_cctv_vehicle_note"(p_observation_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_cctv_vehicle_note"(p_observation_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_cctv_vehicle_note"(p_observation_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_client_portal_access"(p_account_organization_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_provider uuid;
  v_account public.organizations%rowtype;
  v_email text;
  v_places integer;
  v_users integer;
  v_signed_in integer;
BEGIN
  SELECT organization_id INTO v_provider FROM public.user_profiles WHERE id = auth.uid() AND deactivated_at IS NULL;
  IF v_provider IS NULL OR NOT public.is_admin_for_org(v_provider) THEN RAISE EXCEPTION 'Active provider CRM administrator required'; END IF;
  SELECT * INTO v_account FROM public.organizations WHERE id = p_account_organization_id;
  IF NOT FOUND OR NOT public.crm_actor_can_manage_account(v_account.id) THEN RAISE EXCEPTION 'Managed client account not found'; END IF;

  SELECT lower(trim(c.email)) INTO v_email FROM public.crm_contacts c
  WHERE c.organization_id = v_account.id AND c.is_primary AND c.deactivated_at IS NULL AND c.email IS NOT NULL
  ORDER BY c.updated_at DESC LIMIT 1;
  v_email := coalesce(v_email, nullif(lower(trim(v_account.contact_email)), ''));

  SELECT (SELECT count(*) FROM public.client_sites s WHERE s.client_organization_id = v_account.id AND s.active)
    + (SELECT count(*) FROM public.location_zones z JOIN public.locations l ON l.id = z.location_id
       WHERE l.organization_id = v_account.id AND z.is_active)
  INTO v_places;

  SELECT count(*), count(*) FILTER (WHERE login.last_sign_in_at IS NOT NULL)
  INTO v_users, v_signed_in
  FROM public.user_profiles u LEFT JOIN auth.users login ON login.id = u.id
  WHERE u.organization_id = v_account.id AND u.deactivated_at IS NULL;

  RETURN jsonb_build_object(
    'account_organization_id', v_account.id,
    'account_status', v_account.status,
    'contact_email', v_email,
    'place_count', v_places,
    'client_user_count', v_users,
    'signed_in_user_count', v_signed_in,
    'pending_user_count', v_users - v_signed_in,
    'can_invite', v_users = 0 AND v_email IS NOT NULL AND v_places > 0
      AND ((v_account.status = 'prospect' AND NOT v_account.active) OR (v_account.status = 'active' AND v_account.active)),
    'invite_blocker', CASE
      WHEN v_users > 0 THEN NULL
      WHEN v_account.status NOT IN ('prospect', 'active') THEN 'This account is not active.'
      WHEN v_email IS NULL THEN 'Add a primary contact email before inviting the client.'
      WHEN v_places = 0 THEN 'Add at least one place before inviting the client.'
      ELSE NULL END);
END;
$function$;
REVOKE ALL ON FUNCTION "public"."get_client_portal_access"(p_account_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_client_portal_access"(p_account_organization_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_client_portal_access"(p_account_organization_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_client_portal_access"(p_account_organization_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_consolidated_commercial_overview"(p_root_organization_id uuid, p_from date DEFAULT (CURRENT_DATE - 30), p_to date DEFAULT CURRENT_DATE)
 RETURNS TABLE(source_organization_id uuid, source_organization_name text, invoice_count integer, open_receivables numeric, overdue_receivables numeric, invoice_total numeric, quote_count integer, accepted_agreement_count integer, report_pack_count integer, service_cost_count integer, service_cost_total numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_root_organization_id IS NULL OR NOT public.is_admin_for_org(p_root_organization_id) THEN
    RAISE EXCEPTION 'Root organization administrator required';
  END IF;
  IF p_from IS NULL OR p_to IS NULL OR p_to < p_from OR p_to - p_from > 366 THEN
    RAISE EXCEPTION 'Reporting period must be between one day and one year';
  END IF;

  RETURN QUERY
  WITH scoped_organizations AS (
    SELECT organization.id, organization.name
    FROM public.organizations organization
    WHERE organization.id = ANY(public.get_descendant_organizations(p_root_organization_id))
      AND (
        organization.id = p_root_organization_id
        OR organization.organization_type = 'branch'
      )
  ),
  invoice_totals AS (
    SELECT invoice.organization_id,
      count(*)::integer AS invoice_count,
      coalesce(sum(invoice.total_amount) FILTER (WHERE invoice.status IN ('sent', 'overdue')), 0)::numeric AS open_receivables,
      coalesce(sum(invoice.total_amount) FILTER (WHERE invoice.status = 'overdue'), 0)::numeric AS overdue_receivables,
      coalesce(sum(invoice.total_amount) FILTER (WHERE invoice.status <> 'void'), 0)::numeric AS invoice_total
    FROM public.invoices invoice
    WHERE invoice.organization_id IN (SELECT id FROM scoped_organizations)
      AND invoice.invoice_date BETWEEN p_from AND p_to
    GROUP BY invoice.organization_id
  ),
  quote_totals AS (
    SELECT quote.provider_org_id, count(*)::integer AS quote_count
    FROM public.quotes quote
    WHERE quote.provider_org_id IN (SELECT id FROM scoped_organizations)
      AND quote.created_at::date BETWEEN p_from AND p_to
    GROUP BY quote.provider_org_id
  ),
  agreement_totals AS (
    SELECT agreement.provider_organization_id, count(*)::integer AS accepted_agreement_count
    FROM public.service_agreements agreement
    WHERE agreement.provider_organization_id IN (SELECT id FROM scoped_organizations)
      AND agreement.agreement_type = 'operational'
      AND (agreement.starts_on IS NULL OR agreement.starts_on <= p_to)
      AND (agreement.ends_on IS NULL OR agreement.ends_on >= p_from)
    GROUP BY agreement.provider_organization_id
  ),
  report_totals AS (
    SELECT pack.organization_id, count(*)::integer AS report_pack_count
    FROM public.monthly_report_packs pack
    WHERE pack.organization_id IN (SELECT id FROM scoped_organizations)
      AND pack.period_start <= p_to
      AND pack.period_end >= p_from
    GROUP BY pack.organization_id
  ),
  cost_totals AS (
    SELECT cost.organization_id,
      count(*)::integer AS service_cost_count,
      coalesce(sum(cost.total_cost), 0)::numeric AS service_cost_total
    FROM public.finance_service_costs cost
    JOIN public.finance_pl_periods period
      ON period.id = cost.pl_period_id
      AND period.organization_id = cost.organization_id
    WHERE cost.organization_id IN (SELECT id FROM scoped_organizations)
      AND period.period_start <= p_to
      AND period.period_end >= p_from
    GROUP BY cost.organization_id
  )
  SELECT scoped.id,
    scoped.name,
    coalesce(invoices.invoice_count, 0),
    coalesce(invoices.open_receivables, 0),
    coalesce(invoices.overdue_receivables, 0),
    coalesce(invoices.invoice_total, 0),
    coalesce(quotes.quote_count, 0),
    coalesce(agreements.accepted_agreement_count, 0),
    coalesce(reports.report_pack_count, 0),
    coalesce(costs.service_cost_count, 0),
    coalesce(costs.service_cost_total, 0)
  FROM scoped_organizations scoped
  LEFT JOIN invoice_totals invoices ON invoices.organization_id = scoped.id
  LEFT JOIN quote_totals quotes ON quotes.provider_org_id = scoped.id
  LEFT JOIN agreement_totals agreements ON agreements.provider_organization_id = scoped.id
  LEFT JOIN report_totals reports ON reports.organization_id = scoped.id
  LEFT JOIN cost_totals costs ON costs.organization_id = scoped.id
  ORDER BY scoped.name;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."get_consolidated_commercial_overview"(p_root_organization_id uuid, p_from date, p_to date) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_consolidated_commercial_overview"(p_root_organization_id uuid, p_from date, p_to date) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_consolidated_commercial_overview"(p_root_organization_id uuid, p_from date, p_to date) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_consolidated_commercial_overview"(p_root_organization_id uuid, p_from date, p_to date) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_consolidated_reporting_overview"(p_root_organization_id uuid, p_from date DEFAULT (CURRENT_DATE - 30), p_to date DEFAULT CURRENT_DATE)
 RETURNS TABLE(source_organization_id uuid, source_organization_name text, breach_count integer, observation_count integer, non_compliant_observation_count integer, report_pack_count integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_root_organization_id is null or not public.is_admin_for_org(p_root_organization_id) then raise exception 'Root organization administrator required'; end if;
  if p_from is null or p_to is null or p_to < p_from or p_to - p_from > 366 then raise exception 'Reporting period must be between one day and one year'; end if;
  return query
  with scoped_organizations as (
    select organization.id, organization.name from public.organizations organization
    where organization.id = any(public.get_descendant_organizations(p_root_organization_id))
  ), breaches as (
    select breach.organization_id, count(*)::integer as breach_count from public.breach_alerts breach
    where breach.organization_id in (select id from scoped_organizations) and breach.created_at::date between p_from and p_to group by breach.organization_id
  ), observations as (
    select observation.organization_id, count(*)::integer as observation_count, count(*) filter (where observation.is_compliant = false)::integer as non_compliant_observation_count from public.observations observation
    where observation.organization_id in (select id from scoped_organizations) and observation.observed_at::date between p_from and p_to group by observation.organization_id
  ), packs as (
    select pack.organization_id, count(*)::integer as report_pack_count from public.monthly_report_packs pack
    where pack.organization_id in (select id from scoped_organizations) and pack.period_start <= p_to and pack.period_end >= p_from group by pack.organization_id
  )
  select scoped.id, scoped.name, coalesce(breaches.breach_count, 0), coalesce(observations.observation_count, 0), coalesce(observations.non_compliant_observation_count, 0), coalesce(packs.report_pack_count, 0)
  from scoped_organizations scoped left join breaches on breaches.organization_id = scoped.id left join observations on observations.organization_id = scoped.id left join packs on packs.organization_id = scoped.id order by scoped.name;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."get_consolidated_reporting_overview"(p_root_organization_id uuid, p_from date, p_to date) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_consolidated_reporting_overview"(p_root_organization_id uuid, p_from date, p_to date) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_consolidated_reporting_overview"(p_root_organization_id uuid, p_from date, p_to date) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_consolidated_reporting_overview"(p_root_organization_id uuid, p_from date, p_to date) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_cost_of_service_summary"(p_organization_id uuid, p_from date, p_to date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_result jsonb;
begin
  if auth.uid() is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if p_organization_id is null or public.is_admin_for_org(p_organization_id) is not true then
    raise exception 'Cost of service access required' using errcode = '42501';
  end if;
  if p_from is null or p_to is null or p_to < p_from or p_to - p_from > 400 then
    raise exception 'Choose a reporting window of up to 400 days';
  end if;

  with agreements as materialized (
    select a.id, a.name, coalesce(o.name, 'Client') as client_name
    from public.service_agreements a
    left join public.organizations o on o.id = a.client_organization_id
    where a.provider_organization_id = p_organization_id
  ),
  shifts_in_window as materialized (
    select s.id, coalesce(am.service_agreement_id, sal.service_agreement_id) as agreement_id,
      s.officer_user_id, s.service_type,
      (s.actual_start at time zone 'Pacific/Auckland')::date as work_date,
      case when s.actual_end > s.actual_start then
        greatest(extract(epoch from s.actual_end - s.actual_start) / 3600.0 - coalesce(ub.hours, 0), 0)
      end as hours
    from public.shifts s
    left join public.service_agreement_modules am on am.id = s.service_agreement_module_id
    left join public.service_agreement_locations sal on sal.id = s.service_agreement_location_id
    left join lateral (
      select sum(extract(epoch from b.ended_at - b.started_at)) / 3600.0 as hours
      from public.shift_breaks b
      where b.shift_id = s.id and b.organization_id = s.organization_id
        and not b.is_paid and b.ended_at is not null
    ) ub on true
    where s.organization_id = p_organization_id
      and s.actual_start is not null
      and s.superseded_by_shift_id is null
      and (s.actual_start at time zone 'Pacific/Auckland')::date between p_from and p_to
  ),
  worked as materialized (
    select w.*,
      exists (
        select 1 from public.finance_service_costs f
        where f.organization_id = p_organization_id and f.shift_id = w.id and f.cost_type = 'labour'
      ) as posted,
      t.id as timesheet_id, t.status as timesheet_status,
      coalesce((t.payroll_snapshot ->> 'hourly_rate')::numeric, t.hourly_rate_override, r.amount) as hourly_rate
    from shifts_in_window w
    left join lateral (
      select sp.id, sp.role_code from public.staff_profiles sp
      where sp.organization_id = p_organization_id
        and (sp.id = w.officer_user_id or sp.user_id = w.officer_user_id)
      order by (sp.id = w.officer_user_id) desc, sp.id
      limit 1
    ) sp on true
    left join lateral (
      select t.id, t.status, t.payroll_snapshot, t.hourly_rate_override
      from public.timesheets t
      where t.organization_id = p_organization_id
        and (t.shift_id = w.id or (
          t.shift_id is null and t.staff_id = sp.id
          and w.work_date between t.period_start and t.period_end
        ))
      order by (t.shift_id = w.id) desc nulls last, (t.status in ('approved', 'paid')) desc, t.created_at desc
      limit 1
    ) t on true
    left join lateral (
      select rr.amount from public.rate_rules rr
      where rr.organization_id = p_organization_id and rr.rule_kind = 'pay'
        and rr.rate_type = 'hourly' and rr.active and rr.amount is not null
        and (rr.role_code is null or rr.role_code = sp.role_code)
        and (rr.service_type is null or rr.service_type = w.service_type)
        and (rr.effective_from is null or rr.effective_from <= w.work_date)
        and (rr.effective_to is null or rr.effective_to >= w.work_date)
      order by (rr.role_code is not null)::integer desc, (rr.service_type is not null)::integer desc,
        rr.priority desc, rr.effective_from desc nulls last, rr.id
      limit 1
    ) r on true
  ),
  jobs as materialized (
    select j.id, coalesce(
      (select a.id from agreements a where a.id = j.service_agreement_id),
      (select min(l.service_agreement_id::text)::uuid
         from public.service_agreement_locations l
         join agreements a on a.id = l.service_agreement_id
        where j.service_agreement_id is null and l.status = 'active'
          and (l.site_id = j.client_site_id or l.zone_id = j.zone_id)
       having count(distinct l.service_agreement_id) = 1)
    ) as agreement_id,
    exists (
      select 1 from public.finance_service_costs f
      where f.organization_id = p_organization_id and f.dispatch_job_id = j.id and f.cost_type = 'labour'
    ) as posted
    from public.dispatch_jobs j
    where j.organization_id = p_organization_id and j.status = 'completed'
      and (j.completed_at at time zone 'Pacific/Auckland')::date between p_from and p_to
  ),
  job_pay as (
    select j.agreement_id, count(distinct j.id) as jobs,
      count(distinct j.id) filter (where j.posted) as posted_jobs,
      coalesce(sum(pl.line_total) filter (where pl.rate_rule_id is not null and coalesce(pl.pay_code, '') <> 'UNRESOLVED'), 0) as pay_total,
      coalesce(sum(pl.line_total) filter (where not j.posted and pl.rate_rule_id is not null and coalesce(pl.pay_code, '') <> 'UNRESOLVED'), 0) as unposted_total,
      count(pl.id) filter (where pl.rate_rule_id is null or coalesce(pl.pay_code, '') = 'UNRESOLVED') as unresolved_lines,
      count(distinct j.id) filter (where pl.id is null) as jobs_without_pay
    from jobs j
    left join public.dispatch_job_pay_lines pl
      on pl.source_dispatch_id = j.id and pl.organization_id = p_organization_id
    group by j.agreement_id
  ),
  posted as (
    select f.service_agreement_id as agreement_id, f.cost_type,
      sum(f.total_cost) as total, count(*) as entries
    from public.finance_service_costs f
    left join public.shifts s on s.id = f.shift_id
    left join public.dispatch_jobs j on j.id = f.dispatch_job_id
    left join public.finance_pl_periods p on p.id = f.pl_period_id
    where f.organization_id = p_organization_id
      and case
        when s.id is not null then
          (coalesce(s.actual_start, s.scheduled_start) at time zone 'Pacific/Auckland')::date between p_from and p_to
        when j.id is not null then
          (coalesce(j.completed_at, j.created_at) at time zone 'Pacific/Auckland')::date between p_from and p_to
        else p.period_start <= p_to and p.period_end >= p_from
      end
    group by f.service_agreement_id, f.cost_type
  ),
  labour as (
    select w.agreement_id,
      count(*) filter (where w.hours is not null) as worked_shifts,
      count(*) filter (where w.hours is null) as in_progress_shifts,
      coalesce(sum(w.hours), 0) as hours,
      count(*) filter (where w.posted) as posted_shifts,
      count(*) filter (where not w.posted and w.hours is not null and w.timesheet_id is null) as no_timesheet,
      count(*) filter (where not w.posted and w.hours is not null and w.timesheet_id is not null
        and w.timesheet_status not in ('approved', 'paid')) as timesheet_not_approved,
      count(*) filter (where not w.posted and w.hours is not null
        and w.timesheet_status in ('approved', 'paid')) as approved_not_posted,
      coalesce(sum(w.hours * w.hourly_rate) filter (where not w.posted and w.hourly_rate is not null), 0) as estimate,
      count(*) filter (where not w.posted and w.hours is not null and w.hourly_rate is not null) as estimated_shifts,
      count(*) filter (where not w.posted and w.hours is not null and w.hourly_rate is null) as rate_unresolved
    from worked w
    group by w.agreement_id
  ),
  agreement_rows as (
    select a.id, a.name, a.client_name,
      coalesce((select sum(p.total) from posted p where p.agreement_id = a.id), 0) as posted_total,
      coalesce((select jsonb_agg(jsonb_build_object('costType', p.cost_type, 'total', round(p.total, 2), 'entries', p.entries)
        order by p.total desc, p.cost_type) from posted p where p.agreement_id = a.id), '[]'::jsonb) as posted_by_type,
      l.*, jp.jobs, jp.posted_jobs, jp.pay_total, jp.unposted_total, jp.unresolved_lines, jp.jobs_without_pay
    from agreements a
    left join labour l on l.agreement_id = a.id
    left join job_pay jp on jp.agreement_id = a.id
    where l.agreement_id is not null or jp.agreement_id is not null
      or exists (select 1 from posted p where p.agreement_id = a.id)
  )
  select jsonb_build_object(
    'version', 1,
    'window', jsonb_build_object('from', p_from, 'to', p_to),
    'agreements', coalesce((select jsonb_agg(jsonb_build_object(
      'agreementId', r.id,
      'agreementName', r.name,
      'clientName', r.client_name,
      'posted', jsonb_build_object('total', round(r.posted_total, 2), 'byType', r.posted_by_type),
      'labour', jsonb_build_object(
        'workedShifts', coalesce(r.worked_shifts, 0),
        'inProgressShifts', coalesce(r.in_progress_shifts, 0),
        'hours', round(coalesce(r.hours, 0), 2),
        'postedShifts', coalesce(r.posted_shifts, 0),
        'estimateNotPosted', round(coalesce(r.estimate, 0), 2),
        'estimatedShifts', coalesce(r.estimated_shifts, 0),
        'rateUnresolvedShifts', coalesce(r.rate_unresolved, 0),
        'missingSteps', jsonb_build_object(
          'noTimesheet', coalesce(r.no_timesheet, 0),
          'timesheetNotApproved', coalesce(r.timesheet_not_approved, 0),
          'approvedNotPosted', coalesce(r.approved_not_posted, 0)
        )
      ),
      'callouts', jsonb_build_object(
        'completedJobs', coalesce(r.jobs, 0),
        'postedJobs', coalesce(r.posted_jobs, 0),
        'payLineTotal', round(coalesce(r.pay_total, 0), 2),
        'notPostedPayTotal', round(coalesce(r.unposted_total, 0), 2),
        'unresolvedPayLines', coalesce(r.unresolved_lines, 0),
        'jobsWithoutPayLines', coalesce(r.jobs_without_pay, 0)
      )
    ) order by r.client_name, r.name, r.id) from agreement_rows r), '[]'::jsonb),
    'unattributed', jsonb_build_object(
      'workedShifts', (select count(*) from worked w where w.agreement_id is null),
      'hours', (select round(coalesce(sum(w.hours), 0), 2) from worked w where w.agreement_id is null),
      'completedJobs', (select count(*) from jobs j where j.agreement_id is null)
    )
  ) into v_result;
  return v_result;
end;
$function$;
COMMENT ON FUNCTION "public"."get_cost_of_service_summary"(p_organization_id uuid, p_from date, p_to date) IS 'Admin-only cost of service per agreement: posted finance costs, callout pay lines, worked hours less unpaid breaks, missing costing steps and a separate unposted labour estimate. Agreement totals only; no officer identities or per-officer pay.';
REVOKE ALL ON FUNCTION "public"."get_cost_of_service_summary"(p_organization_id uuid, p_from date, p_to date) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_cost_of_service_summary"(p_organization_id uuid, p_from date, p_to date) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_cost_of_service_summary"(p_organization_id uuid, p_from date, p_to date) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."get_crm_activation_handoffs"()
 RETURNS TABLE(handoff_id uuid, account_organization_id uuid, account_name text, agreement_id uuid, agreement_name text, owner_user_id uuid, owner_name text, handoff_status text, version integer, activated_at timestamp with time zone, completed_at timestamp with time zone, tasks jsonb, sites jsonb, work_units jsonb, first_roster_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_provider uuid;
begin
  select organization_id into v_provider from public.user_profiles where id=v_actor and deactivated_at is null;
  if v_provider is null or not public.is_admin_for_org(v_provider) then raise exception 'Active CRM administrator required';end if;
  return query select h.id,o.id,o.name,sa.id,sa.name,h.owner_user_id,u.display_name,h.status,h.version,h.activated_at,h.completed_at,
    (select coalesce(jsonb_agg(jsonb_build_object('task_id',t.id,'task_key',t.task_key,'title',t.title,'destination',t.destination,'status',t.status,'completion_note',t.completion_note,'completed_at',t.completed_at,'completed_by_name',cu.display_name) order by t.created_at),'[]'::jsonb) from public.crm_activation_handoff_tasks t left join public.user_profiles cu on cu.id=t.completed_by where t.handoff_id=h.id),
    (select coalesce(jsonb_agg(jsonb_build_object('site_id',s.id,'name',s.name,'address',s.address,'risk_level',s.risk_level,'access_instructions',s.access_instructions,'hs_notes',s.hs_notes) order by s.name),'[]'::jsonb) from public.service_agreement_locations sal join public.client_sites s on s.id=sal.site_id where sal.service_agreement_id=h.agreement_id and sal.status='active'),
    (select coalesce(jsonb_agg(jsonb_build_object('work_unit_id',wu.id,'name',wu.name,'service_type',wu.service_type,'active',wu.active) order by wu.name),'[]'::jsonb) from public.roster_work_units wu join public.service_agreement_locations sal on sal.id=wu.service_agreement_location_id where sal.service_agreement_id=h.agreement_id and sal.status='active'),
    (select min(rs.scheduled_start) from public.roster_slots rs join public.roster_work_units wu on wu.id=rs.work_unit_id join public.service_agreement_locations sal on sal.id=wu.service_agreement_location_id where sal.service_agreement_id=h.agreement_id and rs.status in('published','accepted','completed') and rs.scheduled_start>=h.activated_at)
  from public.crm_activation_handoffs h join public.organizations o on o.id=h.account_organization_id join public.service_agreements sa on sa.id=h.agreement_id left join public.user_profiles u on u.id=h.owner_user_id
  where h.provider_organization_id=v_provider order by case when h.status='open' then 0 else 1 end,h.activated_at desc;
end;$function$;
REVOKE ALL ON FUNCTION "public"."get_crm_activation_handoffs"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_crm_activation_handoffs"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_crm_activation_handoffs"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_crm_activation_handoffs"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_crm_agreement_setup"(p_agreement_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_agreement public.service_agreements%rowtype;
BEGIN
  SELECT sa.*
  INTO v_agreement
  FROM public.service_agreements sa
  WHERE sa.id = p_agreement_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Service agreement not found';
  END IF;
  IF v_actor IS NULL OR NOT public.is_admin_for_org(v_agreement.provider_organization_id) THEN
    RAISE EXCEPTION 'Provider administrator required';
  END IF;

  RETURN jsonb_build_object(
    'agreement', jsonb_build_object(
      'id', v_agreement.id,
      'name', v_agreement.name,
      'client_organization_id', v_agreement.client_organization_id,
      'invitation_status', v_agreement.invitation_status,
      'enabled_modules', v_agreement.enabled_modules,
      'client_portal_reports_enabled', v_agreement.client_portal_reports_enabled,
      'monthly_report_template_code', v_agreement.monthly_report_template_code,
      'client_portal_finance_enabled', v_agreement.client_portal_finance_enabled
    ),
    'sites', (
      SELECT coalesce(jsonb_agg(jsonb_build_object(
        'id', s.id,
        'name', s.name,
        'address', s.address,
        'boundary_status', s.boundary_status,
        'boundary_verification', s.boundary_verification,
        'linked', sal.id IS NOT NULL,
        'link_status', sal.status
      ) ORDER BY s.name), '[]'::jsonb)
      FROM public.client_sites s
      LEFT JOIN public.service_agreement_locations sal
        ON sal.service_agreement_id = v_agreement.id
       AND sal.site_id = s.id
      WHERE s.client_organization_id = v_agreement.client_organization_id
        AND s.active
    ),
    'zones', (
      SELECT coalesce(jsonb_agg(jsonb_build_object(
        'id', z.id,
        'name', z.name,
        'address', NULL,
        'boundary_status', z.boundary_status,
        'boundary_verification', z.boundary_verification,
        'linked', sal.id IS NOT NULL,
        'link_status', sal.status
      ) ORDER BY z.name), '[]'::jsonb)
      FROM public.location_zones z
      LEFT JOIN public.service_agreement_locations sal
        ON sal.service_agreement_id = v_agreement.id
       AND sal.zone_id = z.id
      WHERE z.organization_id = v_agreement.client_organization_id
        AND z.is_active
    ),
    'modules', (
      SELECT coalesce(jsonb_agg(jsonb_build_object(
        'module_key', mc.module_key,
        'enabled', coalesce(sam.enabled, false),
        'sla_minutes', sam.sla_minutes,
        'allows_client_submission', coalesce(sam.allows_client_submission, false),
        'allows_auto_dispatch', coalesce(sam.allows_auto_dispatch, false)
      ) ORDER BY mc.module_key), '[]'::jsonb)
      FROM public.module_catalog mc
      LEFT JOIN public.service_agreement_modules sam
        ON sam.service_agreement_id = v_agreement.id
       AND sam.module_key = mc.module_key
      WHERE mc.active
    ),
    'report_templates', (
      SELECT coalesce(jsonb_agg(jsonb_build_object(
        'template_code', rt.template_code,
        'name', rt.name,
        'module_key', rt.module_key
      ) ORDER BY rt.name), '[]'::jsonb)
      FROM public.report_templates rt
      WHERE rt.organization_id = v_agreement.provider_organization_id
    ),
    'obligations', (
      SELECT coalesce(jsonb_agg(to_jsonb(ao) ORDER BY ao.active DESC, ao.obligation_code), '[]'::jsonb)
      FROM public.agreement_obligations ao
      WHERE ao.service_agreement_id = v_agreement.id
    )
  );
END;
$function$;
REVOKE ALL ON FUNCTION "public"."get_crm_agreement_setup"(p_agreement_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_crm_agreement_setup"(p_agreement_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_crm_agreement_setup"(p_agreement_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_crm_agreement_setup"(p_agreement_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_crm_enterprise_readiness"(p_agreement_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_agreement public.service_agreements%rowtype;
  v_base jsonb;
  v_provider_ready boolean;
  v_client_ready boolean;
  v_house_ready boolean;
  v_place_ready boolean;
  v_zone_ready boolean;
  v_finance_ready boolean;
  v_roster_ready boolean;
  v_active_links integer;
  v_active_sites integer;
  v_active_zones integer;
  v_active_work_units integer;
  v_dimensions jsonb;
  v_ready boolean;
begin
  select * into v_agreement from public.service_agreements where id=p_agreement_id;
  if not found then raise exception 'Service agreement not found'; end if;
  if v_actor is null or not public.is_admin_for_org(v_agreement.provider_organization_id) then
    raise exception 'Provider administrator required';
  end if;
  if v_agreement.agreement_type<>'operational' then raise exception 'Operational agreement required'; end if;

  v_base := public.get_crm_operational_readiness(p_agreement_id);

  select exists(select 1 from public.organizations o where o.id=v_agreement.provider_organization_id and o.active and o.status='active'),
         exists(select 1 from public.organizations o where o.id=v_agreement.client_organization_id and o.active and o.status in ('active','prospect'))
    into v_provider_ready,v_client_ready;

  select count(*) into v_active_links from public.service_agreement_locations sal where sal.service_agreement_id=p_agreement_id and sal.status='active';
  select count(*) into v_active_sites from public.service_agreement_locations sal join public.client_sites s on s.id=sal.site_id join public.locations l on l.id=s.location_id where sal.service_agreement_id=p_agreement_id and sal.status='active' and sal.site_id is not null and s.active and l.organization_id=v_agreement.client_organization_id;
  select count(*) into v_active_zones from public.service_agreement_locations sal join public.location_zones z on z.id=sal.zone_id where sal.service_agreement_id=p_agreement_id and sal.status='active' and sal.zone_id is not null and z.is_active and z.organization_id=v_agreement.client_organization_id;

  v_house_ready := v_active_links>0 and v_active_sites>0;
  v_place_ready := v_active_links>0 and not exists(
    select 1 from public.service_agreement_locations sal
    left join public.client_sites s on s.id=sal.site_id
    left join public.location_zones z on z.id=sal.zone_id
    where sal.service_agreement_id=p_agreement_id and sal.status='active'
      and ((sal.site_id is not null and (s.id is null or not s.active)) or (sal.zone_id is not null and (z.id is null or not z.is_active)))
  );
  v_zone_ready := not exists(
    select 1 from public.service_agreement_locations sal
    left join public.location_zones z on z.id=sal.zone_id
    where sal.service_agreement_id=p_agreement_id and sal.status='active' and sal.zone_id is not null
      and (z.id is null or z.boundary is null or z.boundary_status<>'authoritative' or not exists(select 1 from public.geofence_boundary_history h where h.entity_type='location_zone' and h.entity_id=z.id and h.verification_state='verified'))
  );
  v_finance_ready := v_active_links>0 and not exists(
    select 1 from public.service_agreement_locations sal
    where sal.service_agreement_id=p_agreement_id and sal.status='active'
      and not exists(select 1 from public.site_financial_config f where f.service_agreement_id=p_agreement_id and f.active and ((sal.site_id is not null and f.site_id=sal.site_id) or (sal.zone_id is not null and f.zone_id=sal.zone_id)) and coalesce(f.hourly_rate,f.per_visit_rate,f.flat_rate_monthly,f.per_notice_rate,f.callout_rate)>0)
  );
  select count(*) into v_active_work_units from public.roster_work_units wu join public.service_agreement_locations sal on sal.id=wu.service_agreement_location_id and sal.service_agreement_id=p_agreement_id and sal.status='active' join public.service_agreement_modules sam on sam.id=wu.service_agreement_module_id and sam.service_agreement_id=p_agreement_id and sam.enabled where wu.active;
  v_roster_ready := v_active_work_units>0;

  v_ready := coalesce((v_base->>'ready')::boolean,false) and v_provider_ready and v_client_ready and v_house_ready and v_place_ready and v_zone_ready and v_finance_ready and v_roster_ready;
  v_dimensions := jsonb_build_array(
    jsonb_build_object('key','organization_branch','label','Organization and branch','status',case when v_provider_ready and v_client_ready then 'ready' else 'blocked' end,'detail',case when v_provider_ready and v_client_ready then 'Active provider branch and client organization are linked' else 'Provider branch and client organization must both be active' end,'owner','Account administration','destination','crm'),
    jsonb_build_object('key','location_house','label','Location house and sites','status',case when v_house_ready then 'ready' else 'blocked' end,'detail',case when v_house_ready then v_active_sites||' active covered site(s) are anchored to canonical locations' else 'Every covered site must belong to an active canonical location house' end,'owner','Account administration','destination','sites'),
    jsonb_build_object('key','site_zone','label','Site and zone configuration','status',case when v_place_ready and v_zone_ready then 'ready' else 'blocked' end,'detail',case when v_place_ready and v_zone_ready then 'Covered sites and zones have active, verified place configuration' else 'Every covered site/zone must be active with verified geometry where a zone is used' end,'owner','Operations administration','destination','sites'),
    jsonb_build_object('key','finance_by_place','label','Finance by covered place','status',case when v_finance_ready then 'ready' else 'blocked' end,'detail',case when v_finance_ready then 'Every active covered site or zone has a positive billable rate' else 'Each active covered site or zone needs its own positive financial configuration' end,'owner','Commercial administration','destination','crm'),
    jsonb_build_object('key','roster_attribution','label','Roster attribution','status',case when v_roster_ready then 'ready' else 'blocked' end,'detail',case when v_roster_ready then v_active_work_units||' active work unit(s) are attributed to the agreement' else 'Create an active roster work unit linked to an enabled agreement module and covered place' end,'owner','Roster administration','destination','roster-targets')
  );
  return jsonb_build_object('agreement_id',p_agreement_id,'invitation_status',v_agreement.invitation_status,'ready',v_ready,'dimensions',coalesce(v_base->'dimensions','[]'::jsonb)||v_dimensions);
end;$function$;
REVOKE ALL ON FUNCTION "public"."get_crm_enterprise_readiness"(p_agreement_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_crm_enterprise_readiness"(p_agreement_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_crm_enterprise_readiness"(p_agreement_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_crm_enterprise_readiness"(p_agreement_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_crm_obligation_proof_register"(p_obligation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_obligation public.agreement_obligations%rowtype;
  v_agreement public.service_agreements%rowtype;
  v_readiness text;
  v_readiness_message text;
BEGIN
  SELECT ao.*
  INTO v_obligation
  FROM public.agreement_obligations ao
  WHERE ao.id = p_obligation_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Contract requirement not found';
  END IF;

  SELECT sa.*
  INTO v_agreement
  FROM public.service_agreements sa
  WHERE sa.id = v_obligation.service_agreement_id;

  IF v_actor IS NULL OR NOT public.is_admin_for_org(v_agreement.provider_organization_id) THEN
    RAISE EXCEPTION 'Provider administrator required';
  END IF;

  IF NOT v_obligation.requires_proof THEN
    v_readiness := 'not_required';
    v_readiness_message := 'This contract requirement does not require evidence.';
  ELSIF v_obligation.proof_artifact_type IS NULL THEN
    v_readiness := 'configuration_required';
    v_readiness_message := 'Choose a required evidence type before linking field evidence.';
  ELSIF v_obligation.proof_artifact_type = 'timestamp' THEN
    v_readiness := 'ready';
    v_readiness_message := 'Completed, contract-aligned stops can provide timestamp evidence.';
  ELSIF v_obligation.proof_artifact_type = 'gps_track' THEN
    v_readiness := 'ready';
    v_readiness_message := 'Only completed stops with at least two shift-linked GPS points can provide a GPS track.';
  ELSE
    v_readiness := 'source_workflow_unavailable';
    v_readiness_message := format(
      'The %s evidence workflow is not wired to this register yet.',
      replace(v_obligation.proof_artifact_type, '_', ' ')
    );
  END IF;

  RETURN jsonb_build_object(
    'obligation_id', v_obligation.id,
    'required_artifact_type', v_obligation.proof_artifact_type,
    'readiness', v_readiness,
    'readiness_message', v_readiness_message,
    'artifacts', (
      SELECT coalesce(jsonb_agg(jsonb_build_object(
        'id', opa.id,
        'artifact_type', opa.artifact_type,
        'source_table', opa.source_table,
        'source_record_id', opa.source_record_id,
        'captured_at', opa.captured_at,
        'notes', opa.notes,
        'status', opa.status,
        'created_at', opa.created_at,
        'updated_at', opa.updated_at,
        'created_by_name', coalesce(created_profile.display_name, 'Unknown reviewer'),
        'withdrawn_at', opa.withdrawn_at,
        'withdrawn_by_name', withdrawn_profile.display_name,
        'withdrawal_reason', opa.withdrawal_reason,
        'metadata', opa.metadata
      ) ORDER BY opa.created_at DESC), '[]'::jsonb)
      FROM public.obligation_proof_artifacts opa
      LEFT JOIN public.user_profiles created_profile ON created_profile.id = opa.created_by
      LEFT JOIN public.user_profiles withdrawn_profile ON withdrawn_profile.id = opa.withdrawn_by
      WHERE opa.obligation_id = v_obligation.id
    ),
    'eligible_sources', (
      SELECT coalesce(jsonb_agg(jsonb_build_object(
        'source_table', 'shift_stops',
        'source_record_id', candidate.stop_id,
        'site_name', candidate.site_name,
        'officer_name', candidate.officer_name,
        'arrived_at', candidate.arrived_at,
        'departed_at', candidate.departed_at,
        'artifact_type', candidate.artifact_type,
        'gps_point_count', candidate.gps_point_count
      ) ORDER BY candidate.departed_at DESC), '[]'::jsonb)
      FROM (
        SELECT
          ss.id AS stop_id,
          coalesce(cs.name, 'Covered Site') AS site_name,
          coalesce(up.display_name, 'Assigned officer') AS officer_name,
          ss.actual_arrived_at AS arrived_at,
          ss.actual_departed_at AS departed_at,
          CASE
            WHEN v_obligation.proof_artifact_type = 'timestamp' THEN 'arrival_timestamp'
            WHEN v_obligation.proof_artifact_type = 'gps_track' THEN 'gps_track'
          END AS artifact_type,
          (
            SELECT count(*)::integer
            FROM public.officer_gps_log ogl
            WHERE ogl.shift_id = s.id
              AND ogl.officer_id = s.officer_user_id
              AND ogl.recorded_at BETWEEN ss.actual_arrived_at AND ss.actual_departed_at
          ) AS gps_point_count
        FROM public.shift_stops ss
        JOIN public.shifts s ON s.id = ss.shift_id
        JOIN public.service_agreement_locations sal
          ON sal.id = s.service_agreement_location_id
         AND sal.service_agreement_id = v_agreement.id
         AND sal.status = 'active'
        LEFT JOIN public.client_sites cs ON cs.id = ss.site_id
        LEFT JOIN public.user_profiles up ON up.id = s.officer_user_id
        WHERE ss.organization_id = v_agreement.provider_organization_id
          AND ss.status = 'completed'
          AND ss.actual_arrived_at IS NOT NULL
          AND ss.actual_departed_at IS NOT NULL
          AND (v_obligation.site_id IS NULL OR ss.site_id = v_obligation.site_id)
          AND (
            v_obligation.proof_artifact_type = 'timestamp'
            OR (
              v_obligation.proof_artifact_type = 'gps_track'
              AND (
                SELECT count(*)
                FROM public.officer_gps_log ogl
                WHERE ogl.shift_id = s.id
                  AND ogl.officer_id = s.officer_user_id
                  AND ogl.recorded_at BETWEEN ss.actual_arrived_at AND ss.actual_departed_at
              ) >= 2
            )
          )
          AND NOT EXISTS (
            SELECT 1
            FROM public.obligation_proof_artifacts existing
            WHERE existing.obligation_id = v_obligation.id
              AND existing.source_table = 'shift_stops'
              AND existing.source_record_id = ss.id
              AND existing.status = 'active'
          )
        ORDER BY ss.actual_departed_at DESC
        LIMIT 20
      ) candidate
    )
  );
END;
$function$;
COMMENT ON FUNCTION "public"."get_crm_obligation_proof_register"(p_obligation_id uuid) IS 'Returns reviewed proof history and only contract-aligned eligible sources for a provider administrator.';
REVOKE ALL ON FUNCTION "public"."get_crm_obligation_proof_register"(p_obligation_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_crm_obligation_proof_register"(p_obligation_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_crm_obligation_proof_register"(p_obligation_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_crm_obligation_proof_register"(p_obligation_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_crm_onboarding_assignees"()
 RETURNS TABLE(user_id uuid, display_name text, role text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_provider uuid;
begin
  select organization_id into v_provider from public.user_profiles where id=v_actor and deactivated_at is null;
  if v_provider is null or not public.is_admin_for_org(v_provider) then raise exception 'Active CRM administrator required';end if;
  return query select u.id,coalesce(nullif(trim(u.display_name),''),u.email,'Administrator'),u.role from public.user_profiles u
  where u.deactivated_at is null and u.role in('admin', 'admin_officer','master','grand_master') and (u.organization_id=v_provider or u.employer_organization_id=v_provider)
  order by coalesce(nullif(trim(u.display_name),''),u.email,'Administrator');
end;$function$;
REVOKE ALL ON FUNCTION "public"."get_crm_onboarding_assignees"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_crm_onboarding_assignees"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_crm_onboarding_assignees"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_crm_onboarding_assignees"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_crm_onboarding_history"(p_account_organization_id uuid)
 RETURNS TABLE(event_id uuid, event_type text, from_stage text, to_stage text, ledger_status text, assigned_to uuid, assigned_name text, note text, actor_user_id uuid, actor_name text, ledger_version integer, created_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_provider uuid;v_ledger_id uuid;
begin
  select organization_id into v_provider from public.user_profiles where id=v_actor and deactivated_at is null;
  if v_provider is null or not public.is_admin_for_org(v_provider) then raise exception 'Active CRM administrator required';end if;
  select l.id into v_ledger_id from public.crm_onboarding_ledgers l where l.provider_organization_id=v_provider and l.account_organization_id=p_account_organization_id;
  if v_ledger_id is null then raise exception 'Onboarding ledger not found';end if;
  return query select e.id,e.event_type,e.from_stage,e.to_stage,e.ledger_status,e.assigned_to,a.display_name,e.note,e.actor_user_id,x.display_name,e.ledger_version,e.created_at from public.crm_onboarding_events e left join public.user_profiles a on a.id=e.assigned_to left join public.user_profiles x on x.id=e.actor_user_id where e.ledger_id=v_ledger_id order by e.created_at desc,e.ledger_version desc;
end;$function$;
REVOKE ALL ON FUNCTION "public"."get_crm_onboarding_history"(p_account_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_crm_onboarding_history"(p_account_organization_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_crm_onboarding_history"(p_account_organization_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_crm_onboarding_history"(p_account_organization_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_crm_onboarding_workspace"()
 RETURNS TABLE(ledger_id uuid, account_organization_id uuid, account_name text, organization_status text, organization_updated_at timestamp with time zone, current_stage text, ledger_status text, version integer, started_at timestamp with time zone, target_live_at timestamp with time zone, days_open integer, overdue boolean, has_primary_contact boolean, agreement_id uuid, agreement_name text, invitation_status text, readiness jsonb, assigned_to uuid, assigned_name text, stage_note text, client_user_count integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_provider uuid;
BEGIN
  SELECT organization_id INTO v_provider FROM public.user_profiles WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_provider IS NULL OR NOT public.is_admin_for_org(v_provider) THEN RAISE EXCEPTION 'Active CRM administrator required'; END IF;
  RETURN QUERY
  SELECT l.id, o.id, o.name, o.status, o.updated_at, l.current_stage, l.status, l.version, l.started_at, l.target_live_at,
    greatest(0, floor(extract(epoch FROM (now() - l.started_at)) / 86400)::integer), l.target_live_at < now(),
    EXISTS(SELECT 1 FROM public.crm_contacts c WHERE c.organization_id = o.id AND c.is_primary AND c.deactivated_at IS NULL),
    sa.id, sa.name, sa.invitation_status,
    CASE WHEN sa.id IS NULL THEN NULL ELSE public.get_crm_operational_readiness(sa.id) END,
    l.assigned_to, u.display_name, l.stage_note,
    (SELECT count(*)::integer FROM public.user_profiles cu WHERE cu.organization_id = o.id AND cu.deactivated_at IS NULL)
  FROM public.crm_onboarding_ledgers l
  JOIN public.organizations o ON o.id = l.account_organization_id
  LEFT JOIN public.user_profiles u ON u.id = l.assigned_to
  LEFT JOIN LATERAL(
    SELECT a.id, a.name, a.invitation_status
    FROM public.service_agreements a
    WHERE a.provider_organization_id = ANY(public.get_descendant_organizations(l.provider_organization_id))
      AND a.client_organization_id = l.account_organization_id
      AND a.agreement_type = 'operational'
      AND (a.ends_on IS NULL OR a.ends_on >= current_date)
    ORDER BY CASE WHEN a.invitation_status = 'accepted' THEN 0 WHEN a.invitation_status = 'invited' THEN 1 ELSE 2 END, a.created_at DESC
    LIMIT 1
  ) sa ON true
  WHERE l.provider_organization_id = ANY(public.get_descendant_organizations(v_provider)) AND l.status <> 'activated'
  ORDER BY l.target_live_at, l.started_at;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."get_crm_onboarding_workspace"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_crm_onboarding_workspace"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_crm_onboarding_workspace"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_crm_onboarding_workspace"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_crm_operational_geography"()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_provider uuid;
  v_reach uuid[];
BEGIN
  SELECT organization_id INTO v_provider FROM public.user_profiles WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_provider IS NULL OR NOT public.is_admin_for_org(v_provider) THEN
    RAISE EXCEPTION 'Active CRM administrator required';
  END IF;
  v_reach := array(
    SELECT DISTINCT descendant
    FROM unnest(public.get_descendant_organizations(v_provider) || v_provider) descendant
  );
  RETURN jsonb_build_object(
    'locations', (
      SELECT coalesce(jsonb_agg(to_jsonb(item) ORDER BY item.name), '[]'::jsonb)
      FROM (
        SELECT DISTINCT location.id, location.organization_id, location.canonical_place_id,
          location.name, location.address, location.suburb, location.postcode, location.notes
        FROM public.locations location
        WHERE location.organization_id = ANY(v_reach)
          OR EXISTS (
            SELECT 1 FROM public.service_agreements agreement
            JOIN public.service_agreement_locations link ON link.service_agreement_id = agreement.id AND link.status = 'active'
            LEFT JOIN public.client_sites site ON site.id = link.site_id
            LEFT JOIN public.location_zones zone ON zone.id = link.zone_id
            WHERE agreement.provider_organization_id = ANY(v_reach)
              AND (agreement.starts_on IS NULL OR agreement.starts_on <= current_date)
              AND (agreement.ends_on IS NULL OR agreement.ends_on >= current_date)
              AND agreement.agreement_type = 'operational'
              AND (site.location_id = location.id OR zone.location_id = location.id)
          )
      ) item
    ),
    'sites', (
      SELECT coalesce(jsonb_agg(to_jsonb(item) ORDER BY item.name), '[]'::jsonb)
      FROM (
        SELECT DISTINCT site.id, site.client_organization_id, site.location_id, site.name,
          site.address, site.site_type, site.active, site.gps_lat, site.gps_lng,
          st_asgeojson(site.boundary)::jsonb AS boundary, site.boundary_status,
          site.boundary_verification, site.configuration_version
        FROM public.client_sites site
        WHERE site.client_organization_id = ANY(v_reach)
          OR EXISTS (
            SELECT 1 FROM public.service_agreements agreement
            JOIN public.service_agreement_locations link ON link.service_agreement_id = agreement.id AND link.status = 'active'
            WHERE agreement.provider_organization_id = ANY(v_reach)
              AND (agreement.starts_on IS NULL OR agreement.starts_on <= current_date)
              AND (agreement.ends_on IS NULL OR agreement.ends_on >= current_date)
              AND agreement.agreement_type = 'operational' AND link.site_id = site.id
          )
      ) item
    ),
    'zones', (
      SELECT coalesce(jsonb_agg(to_jsonb(item) ORDER BY item.name), '[]'::jsonb)
      FROM (
        SELECT DISTINCT zone.id, zone.organization_id, zone.location_id, zone.name,
          location.address, zone.zone_type, zone.module_key, zone.rule_type, zone.is_active,
          zone.active_schedule, zone.onsite_profile, zone.enforcement_workflow_override,
          st_asgeojson(zone.boundary)::jsonb AS boundary, st_asgeojson(zone.center_point)::jsonb AS center_point,
          zone.boundary_status, zone.boundary_verification, zone.bylaw_clause, zone.bylaw_source_url,
          zone.nightly_limit_consecutive, zone.nightly_limit_monthly, zone.scv_required,
          zone.parking_time_limit_minutes, zone.parking_disabled_multiplier, zone.parking_signage_photo_url,
          zone.parking_limit_source, zone.parking_limit_set_at, zone.configuration_version
        FROM public.location_zones zone LEFT JOIN public.locations location ON location.id = zone.location_id
        WHERE NOT zone.is_verification_point AND (zone.organization_id = ANY(v_reach)
          OR EXISTS (
            SELECT 1 FROM public.service_agreements agreement
            JOIN public.service_agreement_locations link ON link.service_agreement_id = agreement.id AND link.status = 'active'
            WHERE agreement.provider_organization_id = ANY(v_reach)
              AND (agreement.starts_on IS NULL OR agreement.starts_on <= current_date)
              AND (agreement.ends_on IS NULL OR agreement.ends_on >= current_date)
              AND agreement.agreement_type = 'operational' AND link.zone_id = zone.id
          ))
      ) item
    )
  );
END;
$function$;
COMMENT ON FUNCTION "public"."get_crm_operational_geography"() IS 'CRM-admin scoped geography for owned and accepted or provider-attested operational places; reference markers are not work areas.';
REVOKE ALL ON FUNCTION "public"."get_crm_operational_geography"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_crm_operational_geography"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_crm_operational_geography"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_crm_operational_geography"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_crm_operational_place_editor"(p_location_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_provider uuid;v_location public.locations%rowtype;
begin
  select organization_id into v_provider from public.user_profiles where id=v_actor and deactivated_at is null;
  if v_provider is null or not public.is_admin_for_org(v_provider) or not public.crm_actor_can_manage_location(p_location_id) then raise exception 'Active CRM administrator required for this location';end if;
  select * into v_location from public.locations l where l.id=p_location_id;if not found then raise exception 'Location not found';end if;
  return jsonb_build_object(
    'location',jsonb_build_object('id',v_location.id,'name',v_location.name,'organization_id',v_location.organization_id),
    'sites',(select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'name',s.name,'risk_level',s.risk_level,'site_brief',s.site_brief,'access_instructions',s.access_instructions,'hs_notes',s.hs_notes,'active',s.active,'boundary_status',s.boundary_status,'boundary_verification',s.boundary_verification,'configuration_version',s.configuration_version) order by s.name),'[]'::jsonb) from public.client_sites s where s.location_id=v_location.id),
    'zones',(select coalesce(jsonb_agg(jsonb_build_object('id',z.id,'name',z.name,'zone_type',z.zone_type,'module_key',z.module_key,'rule_type',z.rule_type,'is_active',z.is_active,'nightly_limit_consecutive',z.nightly_limit_consecutive,'nightly_limit_monthly',z.nightly_limit_monthly,'scv_required',z.scv_required,'enforcement_workflow_override',z.enforcement_workflow_override,'boundary_status',z.boundary_status,'boundary_verification',z.boundary_verification,'configuration_version',z.configuration_version) order by z.name),'[]'::jsonb) from public.location_zones z where z.location_id=v_location.id AND NOT z.is_verification_point),
    'modules',(select coalesce(jsonb_agg(jsonb_build_object('module_key',m.module_key,'display_name',initcap(replace(m.module_key,'_',' '))) order by m.module_key),'[]'::jsonb) from public.module_catalog m where m.active),
    'closures',(select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'zone_id',c.zone_id,'closure_type',c.closure_type,'status',c.status,'effective_from',c.effective_from,'effective_to',c.effective_to,'reason',c.reason,'resolution_notes',c.resolution_notes) order by c.created_at desc),'[]'::jsonb) from public.zone_closures c join public.location_zones z on z.id=c.zone_id where z.location_id=v_location.id AND NOT z.is_verification_point)
  );
end;
$function$;
REVOKE ALL ON FUNCTION "public"."get_crm_operational_place_editor"(p_location_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_crm_operational_place_editor"(p_location_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_crm_operational_place_editor"(p_location_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_crm_operational_place_editor"(p_location_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_crm_operational_readiness"(p_agreement_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_agreement public.service_agreements%rowtype;v_location_count integer;v_boundary_ready boolean;v_module_count integer;v_billing_ready boolean;v_work_unit_count integer;v_reporting_ready boolean;
begin
  select sa.* into v_agreement from public.service_agreements sa where sa.id=p_agreement_id;
  if not found then raise exception 'Service agreement not found';end if;
  if v_actor is null or not public.is_admin_for_org(v_agreement.provider_organization_id) then raise exception 'Provider administrator required';end if;
  if v_agreement.agreement_type<>'operational' then raise exception 'Operational agreement required';end if;

  select count(*) into v_location_count from public.service_agreement_locations sal where sal.service_agreement_id=v_agreement.id and sal.status='active';
  select v_location_count>0 and not exists(
    select 1 from public.service_agreement_locations sal
    left join public.client_sites s on s.id=sal.site_id
    left join public.location_zones z on z.id=sal.zone_id
    where sal.service_agreement_id=v_agreement.id and sal.status='active' and (
      (sal.site_id is not null and (s.boundary is null or s.boundary_status<>'authoritative' or s.boundary_verification<>'verified'))
      or (sal.zone_id is not null and (z.boundary is null or not exists(select 1 from public.geofence_boundary_history h where h.entity_type='location_zone' and h.entity_id=z.id and h.verification_state='verified')))
    )
  ) into v_boundary_ready;
  select count(*) into v_module_count from public.service_agreement_modules sam where sam.service_agreement_id=v_agreement.id and sam.enabled;
  select exists(select 1 from public.crm_commercial_settings c where c.service_agreement_id=v_agreement.id and coalesce(c.base_rate_per_hour,c.callout_rate_per_hour,c.travel_rate_per_km)>0)
    or exists(select 1 from public.site_financial_config f join public.service_agreement_locations sal on sal.service_agreement_id=f.service_agreement_id and (sal.site_id=f.site_id or sal.zone_id=f.zone_id) where f.service_agreement_id=v_agreement.id and f.active and sal.status='active' and coalesce(f.hourly_rate,f.per_visit_rate,f.flat_rate_monthly,f.per_notice_rate,f.callout_rate)>0) into v_billing_ready;
  -- a static post attributed directly, or a patrol run whose stops come from this agreement's accepted schedules
  select count(*) into v_work_unit_count from public.roster_work_units wu
  where wu.active and (
    exists (select 1 from public.service_agreement_locations sal join public.service_agreement_modules sam on sam.id=wu.service_agreement_module_id and sam.service_agreement_id=v_agreement.id and sam.enabled
            where sal.id=wu.service_agreement_location_id and sal.service_agreement_id=v_agreement.id and sal.status='active')
    or exists (select 1 from public.client_site_patrol_config c join public.service_agreement_delivery_schedules s on (c.delivery_schedule_id = s.id OR (c.proposal_scope_schedule_id IS NOT NULL AND s.proposal_scope_schedule_id = c.proposal_scope_schedule_id))
               where c.patrol_route_id=wu.patrol_route_id and c.active and s.service_agreement_id=v_agreement.id and s.active));
  select not v_agreement.client_portal_reports_enabled or (v_agreement.monthly_report_template_code is not null and exists(select 1 from public.report_templates rt where rt.organization_id=v_agreement.provider_organization_id and rt.template_code=v_agreement.monthly_report_template_code)) into v_reporting_ready;

  return jsonb_build_object('agreement_id',v_agreement.id,'invitation_status',v_agreement.invitation_status,'ready',v_location_count>0 and v_boundary_ready and v_module_count>0 and v_billing_ready and v_work_unit_count>0 and v_reporting_ready,'dimensions',jsonb_build_array(
    jsonb_build_object('key','coverage','label','Covered places','status',case when v_location_count>0 then 'ready' else 'blocked' end,'detail',case when v_location_count>0 then v_location_count||' active location link'||case when v_location_count=1 then '' else 's' end else 'No active covered site or zone is linked' end,'owner','Account administration','destination','relationships'),
    jsonb_build_object('key','boundary','label','Boundary evidence','status',case when v_boundary_ready then 'ready' else 'blocked' end,'detail',case when v_boundary_ready then 'All covered places have authoritative verified boundaries' else 'Every covered place needs authoritative verified geometry' end,'owner','Operations administration','destination','sites'),
    jsonb_build_object('key','modules','label','Service scope','status',case when v_module_count>0 then 'ready' else 'blocked' end,'detail',case when v_module_count>0 then v_module_count||' enabled service module'||case when v_module_count=1 then '' else 's' end else 'No service module is enabled' end,'owner','Account administration','destination','relationships'),
    jsonb_build_object('key','billing','label','Commercial rates','status',case when v_billing_ready then 'ready' else 'blocked' end,'detail',case when v_billing_ready then 'A positive agreement or covered-place rate is recorded' else 'No positive billable rate is recorded' end,'owner','Commercial administration','destination','crm'),
    jsonb_build_object('key','operations','label','Operational work','status',case when v_work_unit_count>0 then 'ready' else 'blocked' end,'detail',case when v_work_unit_count>0 then v_work_unit_count||' active attributed work unit'||case when v_work_unit_count=1 then '' else 's' end else 'No active work unit is attributed to this agreement' end,'owner','Roster administration','destination','roster-targets'),
    jsonb_build_object('key','reporting','label','Reporting delivery','status',case when v_reporting_ready then 'ready' else 'blocked' end,'detail',case when not v_agreement.client_portal_reports_enabled then 'Client report delivery is disabled by contract' when v_reporting_ready then 'The configured monthly template exists for the provider' else 'Client reporting is enabled without a valid monthly template' end,'owner','Reporting administration','destination','reports')
  ));
end;$function$;
REVOKE ALL ON FUNCTION "public"."get_crm_operational_readiness"(p_agreement_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_crm_operational_readiness"(p_agreement_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_crm_operational_readiness"(p_agreement_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_crm_operational_readiness"(p_agreement_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_crm_organization_readiness"(p_organization_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS TABLE(organization_id uuid, organization_status text, identity_status text, contact_status text, location_status text, agreement_status text, module_status text, billing_status text, operations_status text, blockers text[], next_action text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_provider uuid;
BEGIN
  SELECT actor.organization_id INTO v_provider
  FROM public.user_profiles actor
  WHERE actor.id = v_actor AND actor.deactivated_at IS NULL;

  IF v_provider IS NULL OR NOT public.is_admin_for_org(v_provider) THEN
    RAISE EXCEPTION 'Active CRM administrator required';
  END IF;

  RETURN QUERY
  WITH accounts AS (
    SELECT o.*
    FROM public.organizations o
    WHERE o.parent_organization_id = ANY(public.get_descendant_organizations(v_provider))
      AND (p_organization_ids IS NULL OR o.id = ANY(p_organization_ids))
  ), facts AS (
    SELECT
      a.id,
      a.status,
      (a.name <> '' AND a.organization_type IS NOT NULL) AS identity_ready,
      EXISTS(SELECT 1 FROM public.crm_contacts c WHERE c.organization_id = a.id AND c.is_primary AND c.deactivated_at IS NULL) AS contact_ready,
      EXISTS(SELECT 1 FROM public.client_sites s WHERE s.client_organization_id = a.id AND s.active) AS location_ready,
      EXISTS(
        SELECT 1 FROM public.service_agreements sa
        WHERE sa.provider_organization_id = ANY(public.get_descendant_organizations(v_provider))
          AND sa.client_organization_id = a.id
          AND sa.agreement_type = 'operational'
          AND (sa.ends_on IS NULL OR sa.ends_on >= current_date)
      ) AS agreement_ready,
      EXISTS(
        SELECT 1 FROM public.service_agreements sa
        WHERE sa.provider_organization_id = ANY(public.get_descendant_organizations(v_provider))
          AND sa.client_organization_id = a.id
          AND sa.agreement_type = 'operational'
          AND (sa.ends_on IS NULL OR sa.ends_on >= current_date)
          AND (cardinality(sa.enabled_modules) > 0 OR EXISTS(SELECT 1 FROM public.service_agreement_delivery_schedules d WHERE d.service_agreement_id = sa.id AND d.active))
      ) AS module_ready,
      EXISTS(
        SELECT 1
        FROM public.service_agreements sa
        JOIN public.crm_commercial_settings cc ON cc.service_agreement_id = sa.id
        WHERE sa.provider_organization_id = ANY(public.get_descendant_organizations(v_provider))
          AND sa.client_organization_id = a.id
      ) AS billing_ready,
      EXISTS(
        -- a static post attributed to a covered place, or a patrol run whose stops come from an accepted schedule
        SELECT 1
        FROM public.roster_work_units wu
        JOIN public.service_agreements sa ON (
          sa.id = (SELECT sal.service_agreement_id FROM public.service_agreement_locations sal WHERE sal.id = wu.service_agreement_location_id)
          OR sa.id IN (SELECT s.service_agreement_id FROM public.client_site_patrol_config c JOIN public.service_agreement_delivery_schedules s ON (c.delivery_schedule_id = s.id OR (c.proposal_scope_schedule_id IS NOT NULL AND s.proposal_scope_schedule_id = c.proposal_scope_schedule_id)) WHERE c.patrol_route_id = wu.patrol_route_id AND c.active AND s.active)
        )
        WHERE sa.provider_organization_id = ANY(public.get_descendant_organizations(v_provider))
          AND sa.client_organization_id = a.id
          AND (sa.ends_on IS NULL OR sa.ends_on >= current_date)
          AND wu.active
      ) AS operations_ready
    FROM accounts a
  )
  SELECT
    f.id,
    f.status,
    CASE WHEN f.identity_ready THEN 'ready' ELSE 'blocked' END,
    CASE WHEN f.contact_ready THEN 'ready' ELSE 'blocked' END,
    CASE WHEN f.location_ready THEN 'ready' ELSE 'blocked' END,
    CASE WHEN f.agreement_ready THEN 'ready' ELSE 'blocked' END,
    CASE WHEN f.module_ready THEN 'ready' ELSE 'blocked' END,
    CASE WHEN f.billing_ready THEN 'ready' ELSE 'blocked' END,
    CASE WHEN f.operations_ready THEN 'ready' ELSE 'blocked' END,
    array_remove(ARRAY[
      CASE WHEN NOT f.identity_ready THEN 'Confirm who the client is' END,
      CASE WHEN NOT f.contact_ready THEN 'Add the person we deal with' END,
      CASE WHEN NOT f.location_ready THEN 'Add a place we work at' END,
      CASE WHEN NOT f.agreement_ready THEN 'Set up the service agreement' END,
      CASE WHEN NOT f.module_ready THEN 'Add a service (what we do there)' END,
      CASE WHEN NOT f.billing_ready THEN 'Set a price: a rate or an accepted quote' END,
      CASE WHEN NOT f.operations_ready THEN 'Build the patrol run or guard post' END
    ], NULL),
    CASE
      WHEN f.status = 'active' AND f.contact_ready AND f.location_ready AND f.agreement_ready AND f.module_ready AND f.billing_ready AND f.operations_ready THEN 'Active: roster the work and deliver'
      WHEN NOT f.contact_ready THEN 'Add the person we deal with'
      WHEN NOT f.location_ready THEN 'Add a place we work at'
      WHEN NOT f.agreement_ready THEN 'Set up the service agreement'
      WHEN NOT f.module_ready THEN 'Add a service'
      WHEN NOT f.billing_ready THEN 'Set a price'
      WHEN NOT f.operations_ready THEN 'Build the patrol run or guard post'
      ELSE 'Ready to activate'
    END
  FROM facts f
  ORDER BY f.id;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."get_crm_organization_readiness"(p_organization_ids uuid[]) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_crm_organization_readiness"(p_organization_ids uuid[]) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_crm_organization_readiness"(p_organization_ids uuid[]) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_crm_organization_readiness"(p_organization_ids uuid[]) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_crm_provider_portfolio"(p_operating_provider_organization_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(organization_id uuid, organization_name text, organization_type text, organization_status text, operating_provider_organization_id uuid, operating_provider_name text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid:=auth.uid(); v_home_provider uuid; v_selected_provider uuid;
begin
  select profile.organization_id into v_home_provider from public.user_profiles profile where profile.id=v_actor and profile.deactivated_at is null;
  if v_home_provider is null or not public.is_admin_for_org(v_home_provider) then raise exception 'Active CRM administrator required'; end if;
  v_selected_provider:=coalesce(p_operating_provider_organization_id,v_home_provider);
  if not public.is_admin_for_org(v_selected_provider) then raise exception 'Operating provider is not within your managed organization tree'; end if;
  if not exists(select 1 from public.organizations provider where provider.id=v_selected_provider and provider.organization_type in ('owner','service_provider','branch')) then raise exception 'Operating provider must be a provider organization or branch'; end if;
  return query
  with provider_scope as (
    select provider.id,provider.name from public.organizations provider
    where provider.id=any(case when v_selected_provider=v_home_provider then public.get_descendant_organizations(v_home_provider) else array[v_selected_provider] end)
      and provider.organization_type in ('service_provider','branch')
  ), portfolio(organization_id,organization_name,organization_type,organization_status,operating_provider_organization_id,operating_provider_name) as (
    select child.id,child.name,child.organization_type,child.status,provider.id,provider.name
    from provider_scope provider join public.organizations child on child.parent_organization_id=provider.id
    where child.organization_type in ('client','government','private_enterprise','contractor')
    union
    select client.id,client.name,client.organization_type,client.status,provider.id,provider.name
    from provider_scope provider join public.service_agreements agreement on agreement.provider_organization_id=provider.id and agreement.agreement_type='operational'
    join public.organizations client on client.id=agreement.client_organization_id
    union
    select client.id,client.name,client.organization_type,client.status,provider.id,provider.name
    from provider_scope provider join public.quotes proposal on proposal.provider_org_id=provider.id
    join public.organizations client on client.id=proposal.client_org_id
    where proposal.status in ('draft','sent','accepted')
  )
  select distinct on (portfolio.organization_id,portfolio.operating_provider_organization_id) portfolio.organization_id,portfolio.organization_name,portfolio.organization_type,portfolio.organization_status,portfolio.operating_provider_organization_id,portfolio.operating_provider_name
  from portfolio order by portfolio.organization_id,portfolio.operating_provider_organization_id,portfolio.organization_name;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."get_crm_provider_portfolio"(p_operating_provider_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_crm_provider_portfolio"(p_operating_provider_organization_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_crm_provider_portfolio"(p_operating_provider_organization_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_crm_provider_portfolio"(p_operating_provider_organization_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_custom_report_scope_options"(p_service_agreement_id uuid, p_period_start date, p_period_end date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_agreement record;
  v_start_ts timestamptz := p_period_start::timestamptz;
  v_end_ts timestamptz := p_period_end::timestamptz + interval '1 day';
  v_sites jsonb;
  v_zones jsonb;
  v_people jsonb;
  v_vehicles jsonb;
begin
  if v_actor is null then
    raise exception 'Authenticated provider administrator required';
  end if;
  if p_period_start is null or p_period_end is null
     or p_period_start > p_period_end
     or p_period_end - p_period_start > 366 then
    raise exception 'Select a valid report period of 366 days or less';
  end if;

  select agreement.id, agreement.provider_organization_id,
      agreement.client_organization_id, agreement.name,
      agreement.starts_on, agreement.ends_on
  into v_agreement
  from public.service_agreements agreement
  where agreement.id = p_service_agreement_id
    and agreement.agreement_type = 'operational';

  if v_agreement.id is null then
    raise exception 'Operational service agreement not found';
  end if;
  if (v_agreement.starts_on is not null and p_period_start < v_agreement.starts_on)
     or (v_agreement.ends_on is not null and p_period_end > v_agreement.ends_on) then
    raise exception 'Report period must fall within the service agreement term';
  end if;
  if not public.is_report_provider_custodian_for_org(v_agreement.provider_organization_id) then
    raise exception 'Provider administrator access required';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', site.id,
           'name', site.name,
           'address', site.address
         ) order by site.name, site.id), '[]'::jsonb)
  into v_sites
  from public.service_agreement_locations link
  join public.client_sites site on site.id = link.site_id
  where link.service_agreement_id = v_agreement.id
    and link.status = 'active'
    and site.active;

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', zone.id,
           'name', zone.name,
           'zone_type', zone.zone_type
         ) order by zone.name, zone.id), '[]'::jsonb)
  into v_zones
  from public.service_agreement_locations link
  join public.location_zones zone on zone.id = link.zone_id
  where link.service_agreement_id = v_agreement.id
    and link.status = 'active'
    and zone.is_active;

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', person.id,
           'name', coalesce(person.display_name, 'Unnamed person')
         ) order by person.display_name, person.id), '[]'::jsonb)
  into v_people
  from public.canonical_person_public person
  where exists (
    select 1
    from public.observations observation
    where observation.organization_id = v_agreement.provider_organization_id
      and observation.observed_at >= v_start_ts
      and observation.observed_at < v_end_ts
      and observation.canonical_person_id = person.id
      and exists (
        select 1
        from public.service_agreement_locations link
        where link.service_agreement_id = v_agreement.id
          and link.status = 'active'
          and (
            (link.site_id is not null and link.site_id = observation.site_id)
            or (link.zone_id is not null and link.zone_id = observation.zone_id)
          )
      )
  );

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', vehicle.id,
           'plate', vehicle.plate_number,
           'make', vehicle.make,
           'model', vehicle.model
         ) order by vehicle.plate_number, vehicle.id), '[]'::jsonb)
  into v_vehicles
  from public.canonical_vehicle_public vehicle
  where exists (
    select 1
    from public.observations observation
    where observation.organization_id = v_agreement.provider_organization_id
      and observation.observed_at >= v_start_ts
      and observation.observed_at < v_end_ts
      and observation.canonical_vehicle_id = vehicle.id
      and exists (
        select 1
        from public.service_agreement_locations link
        where link.service_agreement_id = v_agreement.id
          and link.status = 'active'
          and (
            (link.site_id is not null and link.site_id = observation.site_id)
            or (link.zone_id is not null and link.zone_id = observation.zone_id)
          )
      )
  );

  return jsonb_build_object(
    'agreement', jsonb_build_object(
      'id', v_agreement.id,
      'name', v_agreement.name,
      'provider_organization_id', v_agreement.provider_organization_id,
      'client_organization_id', v_agreement.client_organization_id
    ),
    'sites', v_sites,
    'zones', v_zones,
    'people', v_people,
    'vehicles', v_vehicles,
    'supported_sections', jsonb_build_array(
      'summary', 'observations', 'breaches', 'incidents', 'checkpoint_visits'
    )
  );
end;
$function$;
COMMENT ON FUNCTION "public"."get_custom_report_scope_options"(p_service_agreement_id uuid, p_period_start date, p_period_end date) IS 'Returns only agreement-linked Site/Zone facets and canonical people/vehicles with tenant-scoped observations in the selected period. Private canonical fields are never returned.';
REVOKE ALL ON FUNCTION "public"."get_custom_report_scope_options"(p_service_agreement_id uuid, p_period_start date, p_period_end date) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_custom_report_scope_options"(p_service_agreement_id uuid, p_period_start date, p_period_end date) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_custom_report_scope_options"(p_service_agreement_id uuid, p_period_start date, p_period_end date) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."get_descendant_organizations"(org_id uuid)
 RETURNS uuid[]
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with recursive org_tree as (
    select id from public.organizations where id = org_id
    union all
    select o.id from public.organizations o
      join org_tree t on o.parent_organization_id = t.id
  )
  select coalesce(array_agg(id), array[]::uuid[]) from org_tree;
$function$;
COMMENT ON FUNCTION "public"."get_descendant_organizations"(org_id uuid) IS 'Inclusive descendant org id array for a root org. SECURITY DEFINER (0098) so it reads the full org tree regardless of the caller RLS - required by is_master_for_org / master_manage_orgs_insert (0093). Body unchanged from 0074.';
REVOKE ALL ON FUNCTION "public"."get_descendant_organizations"(org_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_descendant_organizations"(org_id uuid) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."get_descendant_organizations"(org_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_descendant_organizations"(org_id uuid) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."get_descendant_organizations"(org_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_descendant_organizations"(org_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_dispatch_job_protected_party"(p_dispatch_job_id uuid, p_party_role text DEFAULT 'complainant'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_org uuid;
  v_role text;
  v_job public.dispatch_jobs%rowtype;
  v_party public.dispatch_job_protected_parties%rowtype;
  v_basis text;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT p.organization_id, p.role INTO v_org, v_role FROM public.user_profiles p WHERE p.id = v_user AND p.deactivated_at IS NULL;
  SELECT * INTO v_job FROM public.dispatch_jobs d WHERE d.id = p_dispatch_job_id;
  -- Reject by non-appearance: a missing job and a job outside the caller's custody look identical.
  IF NOT FOUND OR v_org IS NULL OR v_org <> v_job.organization_id THEN
    RETURN jsonb_build_object('available', false, 'reason', 'no_basis');
  END IF;
  -- Authorised: custodian admin or dispatcher; the attending officer while the job is live.
  IF public.is_admin_for_org(v_job.organization_id) OR v_role = 'admin_officer' THEN
    v_basis := 'custodian_admin';
  ELSIF v_job.status NOT IN ('completed', 'cancelled') AND (
      v_job.assigned_officer_id = v_user
      OR EXISTS (SELECT 1 FROM public.dispatch_resources dr WHERE dr.id = v_job.dispatch_resource_id AND dr.assigned_officer_id = v_user)) THEN
    v_basis := 'attending_officer';
  ELSE
    RETURN jsonb_build_object('available', false, 'reason', 'no_basis');
  END IF;

  SELECT * INTO v_party FROM public.dispatch_job_protected_parties pp
  WHERE pp.dispatch_job_id = v_job.id AND pp.party_role = p_party_role;

  -- Every read of protected identity is logged (IPP 6), including empty ones.
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_job.organization_id, v_user, 'protected_party_read', 'dispatch_job_protected_parties', v_party.id,
    jsonb_build_object('dispatch_job_id', v_job.id, 'party_role', p_party_role, 'basis', v_basis, 'found', v_party.id IS NOT NULL));

  IF v_party.id IS NULL THEN RETURN jsonb_build_object('available', false, 'reason', 'not_recorded', 'basis', v_basis); END IF;
  RETURN jsonb_build_object('available', true, 'basis', v_basis, 'party_role', v_party.party_role,
    'display_name', v_party.display_name, 'phone', v_party.phone, 'email', v_party.email, 'notes', v_party.notes,
    'harmed_party_address', v_job.harmed_party_address, 'harmed_party_site_id', v_job.harmed_party_site_id);
END;
$function$;
REVOKE ALL ON FUNCTION "public"."get_dispatch_job_protected_party"(p_dispatch_job_id uuid, p_party_role text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_dispatch_job_protected_party"(p_dispatch_job_id uuid, p_party_role text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_dispatch_job_protected_party"(p_dispatch_job_id uuid, p_party_role text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_dispatch_job_protected_party"(p_dispatch_job_id uuid, p_party_role text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_field_place_workspace"(p_provider_id uuid, p_client_id uuid DEFAULT NULL::uuid, p_search text DEFAULT ''::text, p_offset integer DEFAULT 0, p_location_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_clients jsonb; v_places jsonb; v_count integer;
BEGIN
  IF auth.uid() IS NULL OR NOT public.field_place_provider_allowed(p_provider_id) THEN
    RAISE EXCEPTION 'An active field or administrator role in this provider is required';
  END IF;
  IF p_offset IS NULL OR p_offset < 0 OR char_length(coalesce(p_search, '')) > 200 THEN
    RAISE EXCEPTION 'Invalid location search or page';
  END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('id', o.id, 'name', o.name) ORDER BY o.name), '[]')
  INTO v_clients FROM public.organizations o
  WHERE o.id = p_provider_id OR o.id IN (
    SELECT a.client_organization_id FROM public.service_agreements a
    WHERE a.provider_organization_id = p_provider_id AND a.agreement_type = 'operational'
      AND (a.starts_on IS NULL OR a.starts_on <= current_date)
      AND (a.ends_on IS NULL OR a.ends_on >= current_date)
  );
  IF p_client_id IS NULL AND p_location_id IS NOT NULL THEN
    SELECT organization_id INTO p_client_id FROM public.locations WHERE id = p_location_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Location is not available'; END IF;
  END IF;
  IF p_client_id IS NULL THEN
    RETURN jsonb_build_object('clients', v_clients, 'places', '[]'::jsonb, 'total', 0);
  END IF;
  IF NOT public.field_place_client_allowed(p_provider_id, p_client_id) THEN
    RAISE EXCEPTION 'This client has no current operational agreement with your provider';
  END IF;
  SELECT count(*) INTO v_count FROM public.locations l
  WHERE l.organization_id = p_client_id AND (p_location_id IS NULL OR l.id = p_location_id)
    AND (coalesce(p_search, '') = '' OR strpos(lower(l.name || ' ' || coalesce(l.address, '')), lower(p_search)) > 0);
  SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY q.name, q.id), '[]') INTO v_places FROM (
    SELECT l.id, l.name, l.address, l.notes, l.updated_at, l.organization_id,
      l.canonical_place_id,
      coalesce((SELECT jsonb_agg(jsonb_build_object(
        'id', s.id, 'name', s.name, 'active', s.active, 'site_type', s.site_type,
        'lat', ST_Y(s.center_point), 'lng', ST_X(s.center_point),
        'gps_lat', s.gps_lat, 'gps_lng', s.gps_lng, 'boundary_status', s.boundary_status,
        'boundary', ST_AsGeoJSON(s.boundary)::jsonb, 'boundary_verification', s.boundary_verification,
        'risk_level', s.risk_level, 'site_brief', s.site_brief, 'access_instructions', s.access_instructions,
        'hs_notes', s.hs_notes, 'configuration_version', s.configuration_version
      ) ORDER BY s.created_at) FROM public.client_sites s WHERE s.location_id = l.id), '[]') AS sites,
      coalesce((SELECT jsonb_agg(jsonb_build_object(
        'id', z.id, 'name', z.name, 'active', z.is_active, 'module_key', z.module_key,
        'lat', ST_Y(z.center_point), 'lng', ST_X(z.center_point),
        'boundary', ST_AsGeoJSON(z.boundary)::jsonb, 'boundary_verification', z.boundary_verification,
        'boundary_status', z.boundary_status,
        'is_verification_point', z.is_verification_point, 'radius_meters', z.radius_meters,
        'verified_at', z.boundary_verified_at, 'verified_by', u.display_name,
        'capture', z.metadata->'field_capture', 'configuration_version', z.configuration_version
      ) ORDER BY z.is_verification_point, z.created_at)
      FROM public.location_zones z LEFT JOIN public.user_profiles u ON u.id = z.boundary_verified_by
      WHERE z.location_id = l.id), '[]') AS zones
    FROM public.locations l
    WHERE l.organization_id = p_client_id AND (p_location_id IS NULL OR l.id = p_location_id)
      AND (coalesce(p_search, '') = '' OR strpos(lower(l.name || ' ' || coalesce(l.address, '')), lower(p_search)) > 0)
    ORDER BY l.name, l.id LIMIT 100 OFFSET p_offset
  ) q;
  RETURN jsonb_build_object('clients', v_clients, 'places', v_places, 'total', v_count);
END;
$function$;
REVOKE ALL ON FUNCTION "public"."get_field_place_workspace"(p_provider_id uuid, p_client_id uuid, p_search text, p_offset integer, p_location_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_field_place_workspace"(p_provider_id uuid, p_client_id uuid, p_search text, p_offset integer, p_location_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_field_place_workspace"(p_provider_id uuid, p_client_id uuid, p_search text, p_offset integer, p_location_id uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."get_file_explorer_tree"(p_organization_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_sensitive boolean;
BEGIN
  IF auth.uid() IS NULL OR NOT public.org_access_allowed(p_organization_id) THEN RAISE EXCEPTION 'File access denied'; END IF;
  v_sensitive:=public.is_admin_for_org(p_organization_id);
  RETURN jsonb_build_object(
    'organization',(SELECT jsonb_build_object('id',org.id,'name',org.name) FROM public.organizations org WHERE org.id=p_organization_id),
    'spaces',coalesce((SELECT jsonb_agg(jsonb_build_object('id',space.id,'space_key',space.space_key,'name',space.name,'sensitivity',space.sensitivity,'sort_order',space.sort_order,'document_count',(SELECT count(*) FROM public.document_placements placement WHERE placement.space_id=space.id AND placement.is_primary AND placement.removed_at IS NULL)) ORDER BY space.sort_order,space.name) FROM public.file_spaces space WHERE space.organization_id=p_organization_id AND space.active AND (space.sensitivity<>'restricted' OR v_sensitive)),'[]'::jsonb),
    'folders',coalesce((SELECT jsonb_agg(jsonb_build_object('id',folder.id,'space_id',folder.space_id,'parent_folder_id',folder.parent_folder_id,'name',folder.name,'folder_kind',folder.folder_kind,'entity_type',folder.entity_type,'entity_id',folder.entity_id,'document_count',(SELECT count(*) FROM public.document_placements placement WHERE placement.folder_id=folder.id AND placement.is_primary AND placement.removed_at IS NULL)) ORDER BY folder.name) FROM public.file_folders folder JOIN public.file_spaces space ON space.id=folder.space_id WHERE folder.organization_id=p_organization_id AND folder.active AND space.active AND (space.sensitivity<>'restricted' OR v_sensitive)),'[]'::jsonb),
    'placements',coalesce((SELECT jsonb_agg(jsonb_build_object('document_id',placement.document_id,'space_id',placement.space_id,'folder_id',placement.folder_id)) FROM public.document_placements placement JOIN public.file_spaces space ON space.id=placement.space_id WHERE placement.organization_id=p_organization_id AND placement.is_primary AND placement.removed_at IS NULL AND space.active AND (space.sensitivity<>'restricted' OR v_sensitive)),'[]'::jsonb)
  );
END;
$function$;
COMMENT ON FUNCTION "public"."get_file_explorer_tree"(p_organization_id uuid) IS 'Returns the caller-visible organization File Explorer tree and active document placements, filtering restricted spaces by role.';
REVOKE ALL ON FUNCTION "public"."get_file_explorer_tree"(p_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_file_explorer_tree"(p_organization_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_file_explorer_tree"(p_organization_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_file_explorer_tree"(p_organization_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_finance_owner_brief"()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_open_periods integer;
  v_over_budget integer;
  v_unmatched_payments integer;
  v_unresolved_labour integer;
  v_source_count integer;
  v_source_health_issues integer;
  v_tax_due numeric := 0;
  v_tax_due_date date;
  v_priorities jsonb := '[]'::jsonb;
  v_headline text;
BEGIN
  SELECT organization_id INTO v_org FROM public.user_profiles WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_org IS NULL OR NOT public.is_admin_for_org(v_org) THEN RAISE EXCEPTION 'Active finance administrator required'; END IF;
  SELECT count(*)::integer INTO v_open_periods FROM public.finance_pl_periods WHERE organization_id = v_org AND status IN ('draft','locked');
  SELECT count(*)::integer INTO v_over_budget FROM public.finance_budget_variances WHERE organization_id = v_org AND status IN ('over_budget','no_budget');
  SELECT count(*)::integer INTO v_unmatched_payments FROM public.payment_receipts WHERE organization_id = v_org AND reconciliation_status <> 'matched';
  SELECT count(*)::integer INTO v_unresolved_labour FROM public.finance_labour_cost_postings WHERE organization_id = v_org AND rate_status = 'unresolved';
  SELECT count(*)::integer, count(*) FILTER (WHERE status <> 'active' OR last_verified_on IS NULL OR review_due_on < CURRENT_DATE)::integer INTO v_source_count, v_source_health_issues FROM public.bob_nz_finance_sources;
  SELECT net_tax_due, filing_due_date INTO v_tax_due, v_tax_due_date FROM public.finance_tax_periods WHERE organization_id = v_org AND status IN ('open','prepared') ORDER BY filing_due_date LIMIT 1;

  IF v_source_health_issues > 0 THEN v_priorities := v_priorities || jsonb_build_array(jsonb_build_object('kind', 'knowledge', 'title', v_source_health_issues || ' NZ finance source' || CASE WHEN v_source_health_issues = 1 THEN '' ELSE 's' END || ' need review', 'detail', 'Bob will not rely on guidance until the source register is refreshed.'));
  END IF;
  IF v_unresolved_labour > 0 THEN v_priorities := v_priorities || jsonb_build_array(jsonb_build_object('kind', 'labour', 'title', v_unresolved_labour || ' labour cost' || CASE WHEN v_unresolved_labour = 1 THEN '' ELSE 's' END || ' need a pay rate', 'detail', 'Bob can find the missing rate rule before this affects your results.')); END IF;
  IF v_over_budget > 0 THEN v_priorities := v_priorities || jsonb_build_array(jsonb_build_object('kind', 'budget', 'title', v_over_budget || ' budget item' || CASE WHEN v_over_budget = 1 THEN '' ELSE 's' END || ' need attention', 'detail', 'Bob can explain what is running over and what changed.')); END IF;
  IF v_unmatched_payments > 0 THEN v_priorities := v_priorities || jsonb_build_array(jsonb_build_object('kind', 'payments', 'title', v_unmatched_payments || ' payment' || CASE WHEN v_unmatched_payments = 1 THEN '' ELSE 's' END || ' need matching', 'detail', 'Bob can compare receipts with bank statement lines for your review.')); END IF;
  IF v_tax_due_date IS NOT NULL THEN v_priorities := v_priorities || jsonb_build_array(jsonb_build_object('kind', 'tax', 'title', 'Tax money is due by ' || to_char(v_tax_due_date, 'DD Mon YYYY'), 'detail', 'Bob can prepare the figures and checklist; you approve filing and payment.')); END IF;
  IF jsonb_array_length(v_priorities) = 0 THEN v_headline := 'Nothing urgent was found in the finance records Bob checked.'; ELSE v_headline := 'Bob found ' || jsonb_array_length(v_priorities)::text || ' item' || CASE WHEN jsonb_array_length(v_priorities) = 1 THEN '' ELSE 's' END || ' worth your attention.'; END IF;
  RETURN jsonb_build_object('headline', v_headline, 'priorities', v_priorities, 'facts', jsonb_build_object('open_periods', v_open_periods, 'over_budget', v_over_budget, 'unmatched_payments', v_unmatched_payments, 'unresolved_labour', v_unresolved_labour, 'finance_source_count', v_source_count, 'finance_source_health_issues', v_source_health_issues, 'tax_due', COALESCE(v_tax_due, 0), 'tax_due_date', v_tax_due_date), 'checked_at', now());
END;
$function$;
REVOKE ALL ON FUNCTION "public"."get_finance_owner_brief"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_finance_owner_brief"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_finance_owner_brief"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_finance_owner_brief"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_finance_pl_period_billing_basis"(p_pl_period_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_period public.finance_pl_periods%ROWTYPE;
  v_result jsonb;
BEGIN
  SELECT organization_id INTO v_org
  FROM public.user_profiles
  WHERE id = v_actor AND deactivated_at IS NULL;

  IF v_org IS NULL OR NOT public.is_admin_for_org(v_org) THEN
    RAISE EXCEPTION 'Active finance administrator required';
  END IF;

  SELECT * INTO v_period
  FROM public.finance_pl_periods
  WHERE id = p_pl_period_id AND organization_id = v_org;
  IF NOT FOUND THEN RAISE EXCEPTION 'P&L period not found in organization'; END IF;

  WITH lines AS (
    SELECT f.id, f.service_agreement_id, f.source_document_type, f.dispatch_job_id, f.total_cost
    FROM public.finance_service_costs f
    WHERE f.organization_id = v_org AND f.pl_period_id = v_period.id
  ), patrol_rows AS (
    SELECT l.id AS line_id, r.amount, c.basis, c.conflict
    FROM lines l
    JOIN public.file_import_finance_cost_rows r ON r.finance_service_cost_id = l.id AND r.status = 'applied'
    CROSS JOIN LATERAL public.classify_patrol_cost_row_billing_basis(v_org, r.source_values) c
    WHERE l.source_document_type = 'patrol_log'
  ), patrol_lines AS (
    SELECT l.id, l.service_agreement_id, l.total_cost,
      coalesce(sum(p.amount) FILTER (WHERE p.basis = 'contract'), 0) AS contract_cost,
      coalesce(sum(p.amount) FILTER (WHERE p.basis = 'extra'), 0) AS extra_cost,
      coalesce(sum(p.amount) FILTER (WHERE p.basis = 'unclassified'), 0) AS unclassified_linked,
      coalesce(sum(p.amount), 0) AS linked_cost,
      count(p.line_id) FILTER (WHERE p.basis = 'unclassified')::integer AS unclassified_rows,
      count(p.line_id) FILTER (WHERE p.conflict)::integer AS conflict_rows
    FROM lines l LEFT JOIN patrol_rows p ON p.line_id = l.id
    WHERE l.source_document_type = 'patrol_log'
    GROUP BY l.id, l.service_agreement_id, l.total_cost
  ), split AS (
    SELECT service_agreement_id, contract_cost, extra_cost,
      unclassified_linked + (total_cost - linked_cost) AS unclassified_cost,
      0::numeric AS other_cost, total_cost - linked_cost AS unlinked_cost, total_cost,
      unclassified_rows, conflict_rows
    FROM patrol_lines
    UNION ALL
    SELECT l.service_agreement_id,
      CASE WHEN dj.billing_basis = 'contract' THEN l.total_cost ELSE 0 END,
      CASE WHEN dj.billing_basis = 'extra' THEN l.total_cost ELSE 0 END,
      CASE WHEN dj.billing_basis IS NULL THEN l.total_cost ELSE 0 END,
      0, 0, l.total_cost, 0, 0
    FROM lines l LEFT JOIN public.dispatch_jobs dj ON dj.id = l.dispatch_job_id
    WHERE l.source_document_type IS DISTINCT FROM 'patrol_log' AND l.dispatch_job_id IS NOT NULL
    UNION ALL
    SELECT l.service_agreement_id, 0, 0, 0, l.total_cost, 0, l.total_cost, 0, 0
    FROM lines l
    WHERE l.source_document_type IS DISTINCT FROM 'patrol_log' AND l.dispatch_job_id IS NULL
  ), mapped AS (
    -- Agreements not billed as fixed price plus Extra bill all their work: pay as you go at agreed
    -- rates, do and invoice at actuals under standing authority, per request against the client's request.
    SELECT s.service_agreement_id,
      CASE WHEN m.uses_ce THEN s.contract_cost ELSE 0 END AS contract_cost,
      CASE WHEN m.uses_ce THEN s.extra_cost ELSE 0 END AS extra_cost,
      CASE WHEN m.uses_ce THEN s.unclassified_cost ELSE 0 END AS unclassified_cost,
      CASE WHEN m.uses_ce THEN 0 ELSE s.contract_cost + s.extra_cost + s.unclassified_cost END AS billable_cost,
      CASE WHEN m.model = 'pay_as_you_go' THEN s.contract_cost + s.extra_cost + s.unclassified_cost ELSE 0 END AS rates_cost,
      CASE WHEN m.model = 'do_and_invoice' THEN s.contract_cost + s.extra_cost + s.unclassified_cost ELSE 0 END AS actuals_cost,
      CASE WHEN m.model = 'per_request' THEN s.contract_cost + s.extra_cost + s.unclassified_cost ELSE 0 END AS request_cost,
      s.other_cost, s.unlinked_cost, s.total_cost,
      CASE WHEN m.uses_ce THEN s.unclassified_rows ELSE 0 END AS unclassified_rows,
      CASE WHEN m.uses_ce THEN s.conflict_rows ELSE 0 END AS conflict_rows
    FROM split s
    CROSS JOIN LATERAL (SELECT public.agreement_uses_contract_extra(s.service_agreement_id) AS uses_ce,
      public.agreement_commercial_model(s.service_agreement_id) AS model) m
  ), by_agreement AS (
    SELECT s.service_agreement_id,
      round(sum(s.contract_cost), 2) AS contract_cost, round(sum(s.extra_cost), 2) AS extra_cost,
      round(sum(s.unclassified_cost), 2) AS unclassified_cost, round(sum(s.billable_cost), 2) AS billable_cost,
      round(sum(s.rates_cost), 2) AS rates_cost, round(sum(s.actuals_cost), 2) AS actuals_cost, round(sum(s.request_cost), 2) AS request_cost,
      round(sum(s.other_cost), 2) AS other_cost,
      round(sum(s.total_cost), 2) AS total_cost,
      sum(s.unclassified_rows)::integer AS unclassified_rows, sum(s.conflict_rows)::integer AS conflict_rows
    FROM mapped s GROUP BY s.service_agreement_id
  ), price AS (
    SELECT q.service_agreement_id, round(sum(ql.quantity * ql.unit_charge), 2) AS total
    FROM public.quotes q JOIN public.quote_lines ql ON ql.quote_id = q.id
    WHERE q.status = 'accepted' AND q.service_agreement_id IN (SELECT service_agreement_id FROM by_agreement)
    GROUP BY q.service_agreement_id
  )
  SELECT jsonb_build_object(
    'pl_period_id', v_period.id,
    'period_name', v_period.name,
    'period_start', v_period.period_start,
    'period_end', v_period.period_end,
    'period_status', v_period.status,
    'totals', (SELECT jsonb_build_object(
        'contract_cost', round(coalesce(sum(contract_cost), 0), 2),
        'extra_cost', round(coalesce(sum(extra_cost), 0), 2),
        'unclassified_cost', round(coalesce(sum(unclassified_cost), 0), 2),
        'billable_cost', round(coalesce(sum(billable_cost), 0), 2),
        'billable_by_model', jsonb_build_object(
          'pay_as_you_go', round(coalesce(sum(rates_cost), 0), 2),
          'do_and_invoice', round(coalesce(sum(actuals_cost), 0), 2),
          'per_request', round(coalesce(sum(request_cost), 0), 2)),
        'other_cost', round(coalesce(sum(other_cost), 0), 2),
        'unlinked_cost', round(coalesce(sum(unlinked_cost), 0), 2),
        'total_cost', round(coalesce(sum(total_cost), 0), 2),
        'unclassified_rows', coalesce(sum(unclassified_rows), 0)::integer,
        'conflict_rows', coalesce(sum(conflict_rows), 0)::integer) FROM mapped),
    'by_agreement', coalesce((SELECT jsonb_agg(jsonb_build_object(
        'service_agreement_id', b.service_agreement_id,
        'agreement_name', sa.name,
        'client_name', client.name,
        'contract_cost', b.contract_cost, 'extra_cost', b.extra_cost,
        'unclassified_cost', b.unclassified_cost, 'billable_cost', b.billable_cost, 'other_cost', b.other_cost,
        'rates_cost', b.rates_cost, 'actuals_cost', b.actuals_cost, 'request_cost', b.request_cost,
        'total_cost', b.total_cost,
        'unclassified_rows', b.unclassified_rows, 'conflict_rows', b.conflict_rows,
        'agreement_price', p.total,
        'commercial_model', public.agreement_commercial_model(b.service_agreement_id)
      ) ORDER BY b.total_cost DESC, sa.name)
      FROM by_agreement b
      JOIN public.service_agreements sa ON sa.id = b.service_agreement_id
      LEFT JOIN public.organizations client ON client.id = sa.client_organization_id
      LEFT JOIN price p ON p.service_agreement_id = b.service_agreement_id), '[]'::jsonb),
    'basis_rule', 'Imported patrol cost is split by its linked workbook rows (TYPE column first, then the charge-code catalog basis). Dispatch cost follows the job billing choice. Agreements billed pay as you go, do and invoice or per request have no Contract/Extra split: all their work is billable — pay as you go at the agreed rates, do and invoice at actuals under the client''s standing authority, per request against each client request. Timesheet, overhead and manual cost is shown as other. Amounts are recorded service cost, not invoiced revenue.'
  ) INTO v_result;
  RETURN v_result;
END;
$function$;
COMMENT ON FUNCTION "public"."get_finance_pl_period_billing_basis"(p_pl_period_id uuid) IS 'Read-only, active finance administrator of the period organization only: splits the P&L period service cost into Contract, Extra, unclassified, billable (agreements not billed fixed price plus Extra; broken down into pay as you go at agreed rates, do and invoice at actuals, and per request) and other, per agreement with its commercial model. Totals reconcile to get_finance_pl_period_summary.total_cost. Does not modify finance_service_costs.';
REVOKE ALL ON FUNCTION "public"."get_finance_pl_period_billing_basis"(p_pl_period_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_finance_pl_period_billing_basis"(p_pl_period_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_finance_pl_period_billing_basis"(p_pl_period_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_finance_pl_period_billing_basis"(p_pl_period_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_finance_pl_period_summary"(p_pl_period_id uuid)
 RETURNS TABLE(pl_period_id uuid, period_status text, total_labour numeric, total_vehicle numeric, total_materials numeric, total_equipment numeric, total_overhead numeric, total_depreciation numeric, total_cost numeric, cost_line_count integer, total_revenue numeric, invoice_count integer, gross_profit numeric, gross_margin_pct numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_period public.finance_pl_periods%rowtype;
BEGIN
  SELECT organization_id
  INTO v_org
  FROM public.user_profiles
  WHERE id = v_actor
    AND deactivated_at IS NULL;

  IF v_org IS NULL OR NOT public.is_admin_for_org(v_org) THEN
    RAISE EXCEPTION 'Active finance administrator required';
  END IF;

  SELECT *
  INTO v_period
  FROM public.finance_pl_periods
  WHERE id = p_pl_period_id
    AND organization_id = v_org;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'P&L period not found in organization';
  END IF;

  RETURN QUERY
  WITH cost_summary AS (
    SELECT
      coalesce(sum(fsc.total_cost) FILTER (WHERE fsc.cost_type = 'labour'), 0)::numeric AS total_labour,
      coalesce(sum(fsc.total_cost) FILTER (WHERE fsc.cost_type = 'vehicle'), 0)::numeric AS total_vehicle,
      coalesce(sum(fsc.total_cost) FILTER (WHERE fsc.cost_type = 'materials'), 0)::numeric AS total_materials,
      coalesce(sum(fsc.total_cost) FILTER (WHERE fsc.cost_type = 'equipment'), 0)::numeric AS total_equipment,
      coalesce(sum(fsc.total_cost) FILTER (WHERE fsc.cost_type = 'overhead'), 0)::numeric AS total_overhead,
      coalesce(sum(fsc.total_cost) FILTER (WHERE fsc.cost_type = 'depreciation'), 0)::numeric AS total_depreciation,
      coalesce(sum(fsc.total_cost), 0)::numeric AS total_cost,
      count(fsc.id)::integer AS cost_line_count
    FROM public.finance_service_costs fsc
    WHERE fsc.organization_id = v_org
      AND fsc.pl_period_id = p_pl_period_id
  ),
  revenue_summary AS (
    SELECT
      coalesce(sum(invoice.total_amount), 0)::numeric AS total_revenue,
      count(*)::integer AS invoice_count
    FROM public.invoices invoice
    WHERE invoice.organization_id = v_org
      AND invoice.invoice_date BETWEEN v_period.period_start AND v_period.period_end
  )
  SELECT
    v_period.id,
    v_period.status,
    costs.total_labour,
    costs.total_vehicle,
    costs.total_materials,
    costs.total_equipment,
    costs.total_overhead,
    costs.total_depreciation,
    costs.total_cost,
    costs.cost_line_count,
    revenue.total_revenue,
    revenue.invoice_count,
    round(revenue.total_revenue - costs.total_cost, 2),
    CASE
      WHEN revenue.total_revenue > 0
        THEN round(((revenue.total_revenue - costs.total_cost) / revenue.total_revenue) * 100, 2)
      ELSE NULL
    END
  FROM cost_summary costs
  CROSS JOIN revenue_summary revenue;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."get_finance_pl_period_summary"(p_pl_period_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_finance_pl_period_summary"(p_pl_period_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_finance_pl_period_summary"(p_pl_period_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_finance_pl_period_summary"(p_pl_period_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_finance_tax_identity_summary"()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_build_object('configured', true, 'ird_last_four', right(t.ird_number, 4), 'gst_registered', t.gst_registered, 'gst_basis', t.gst_basis, 'gst_filing_frequency', t.gst_filing_frequency, 'tax_agent_name', t.tax_agent_name, 'setup_status', t.setup_status)
  FROM public.finance_tax_identity t
  WHERE public.is_admin_for_org(t.organization_id)
  LIMIT 1;
$function$;
REVOKE ALL ON FUNCTION "public"."get_finance_tax_identity_summary"() FROM PUBLIC, "anon", "authenticated", "service_role";
