CREATE OR REPLACE FUNCTION "public"."get_geofence_review_queue"(p_organization_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(entity_type text, entity_id uuid, name text, address text, organization_id uuid, organization_name text, zone_type text, module_key text, boundary_state text, boundary_status text, boundary_verification text, has_boundary boolean, boundary_geojson jsonb, center_lat double precision, center_lng double precision, active_agreements integer, open_proposal_id uuid, open_proposal_source text, open_proposal_gate_ok boolean, open_proposal_area_m2 numeric, open_proposal_drift_m double precision, open_proposal_geojson jsonb, configuration_version integer, priority integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH sites AS (
    SELECT 'client_site'::text AS entity_type, s.id AS entity_id, s.name, s.address, s.client_organization_id AS organization_id,
      NULL::text AS zone_type, NULL::text AS module_key, s.boundary_status, s.boundary_verification, s.boundary AS geom, s.center_point,
      (SELECT count(*)::integer FROM public.service_agreement_locations sal JOIN public.service_agreements sa ON sa.id = sal.service_agreement_id
        WHERE sal.site_id = s.id AND sal.status = 'active'
          AND (sa.starts_on IS NULL OR sa.starts_on <= current_date) AND (sa.ends_on IS NULL OR sa.ends_on >= current_date)) AS active_agreements,
      s.configuration_version
    FROM public.client_sites s
    WHERE s.active AND public.org_access_allowed(s.client_organization_id)
      AND (p_organization_id IS NULL OR s.client_organization_id = p_organization_id)
  ), zones AS (
    SELECT 'location_zone'::text, z.id, z.name, l.address, z.organization_id, z.zone_type, z.module_key, z.boundary_status, z.boundary_verification, z.boundary, z.center_point,
      (SELECT count(*)::integer FROM public.service_agreement_locations sal JOIN public.service_agreements sa ON sa.id = sal.service_agreement_id
        WHERE sal.zone_id = z.id AND sal.status = 'active'
          AND (sa.starts_on IS NULL OR sa.starts_on <= current_date) AND (sa.ends_on IS NULL OR sa.ends_on >= current_date)),
      z.configuration_version
    FROM public.location_zones z
    LEFT JOIN public.locations l ON l.id = z.location_id
    WHERE z.is_active AND public.org_access_allowed(z.organization_id)
      AND (p_organization_id IS NULL OR z.organization_id = p_organization_id)
  ), entities AS (SELECT * FROM sites UNION ALL SELECT * FROM zones)
  SELECT e.entity_type, e.entity_id, e.name, e.address, e.organization_id, o.name,
    e.zone_type, e.module_key,
    CASE WHEN e.geom IS NULL THEN 'missing' WHEN e.boundary_verification = 'verified' THEN 'verified' ELSE 'unverified' END,
    e.boundary_status, e.boundary_verification,
    e.geom IS NOT NULL, CASE WHEN e.geom IS NULL THEN NULL ELSE ST_AsGeoJSON(e.geom)::jsonb END,
    ST_Y(e.center_point), ST_X(e.center_point),
    e.active_agreements,
    bp.id, bp.source, bp.gate_ok, bp.area_m2, bp.drift_from_current_m, CASE WHEN bp.id IS NULL THEN NULL ELSE ST_AsGeoJSON(bp.proposed_boundary)::jsonb END,
    e.configuration_version,
    (CASE WHEN e.geom IS NULL THEN 300 WHEN e.boundary_verification <> 'verified' THEN 200 ELSE 0 END)
      + (CASE WHEN bp.id IS NOT NULL THEN 50 ELSE 0 END)
      + least(e.active_agreements, 10) * 10
  FROM entities e
  JOIN public.organizations o ON o.id = e.organization_id
  LEFT JOIN LATERAL (
    SELECT * FROM public.boundary_proposals p WHERE p.entity_type = e.entity_type AND p.entity_id = e.entity_id AND p.status = 'proposed'
    ORDER BY p.proposed_at DESC LIMIT 1
  ) bp ON true
  ORDER BY 24 DESC, e.name;
$function$;
REVOKE ALL ON FUNCTION "public"."get_geofence_review_queue"(p_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_geofence_review_queue"(p_organization_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_geofence_review_queue"(p_organization_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_geofence_review_queue"(p_organization_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_identity_document_types"()
 RETURNS SETOF identity_document_type_definitions
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT definition.* FROM public.identity_document_type_definitions definition
  WHERE definition.active AND auth.uid() IS NOT NULL ORDER BY definition.display_order, definition.display_name
$function$;
REVOKE ALL ON FUNCTION "public"."get_identity_document_types"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_identity_document_types"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_identity_document_types"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_identity_document_types"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_identity_registry"(p_organization_id uuid, p_search text DEFAULT NULL::text, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_search text := lower(trim(coalesce(p_search, '')));
  v_limit integer := greatest(1, least(coalesce(p_limit, 100), 250));
  v_visible_organizations uuid[];
  v_uid uuid := auth.uid();
  v_owner_access_orgs uuid[];
BEGIN
  IF v_uid IS NULL OR NOT public.is_admin_for_org(p_organization_id) THEN
    RAISE EXCEPTION 'Identity registry administrator access required';
  END IF;

  SELECT array_agg(DISTINCT scope.id)
    INTO v_visible_organizations
    FROM (
      SELECT p_organization_id AS id
      UNION
      SELECT unnest(public.get_descendant_organizations(p_organization_id))
      UNION
      SELECT agreement.client_organization_id
      FROM public.service_agreements AS agreement
      WHERE agreement.provider_organization_id = p_organization_id
        AND agreement.agreement_type = 'operational'
    ) AS scope;

  -- Owner-identity access is resolved once per checking organisation rather than
  -- once per document; the per-document test below mirrors nzta_document_restricted.
  SELECT array_agg(scope.organization_id)
    INTO v_owner_access_orgs
    FROM (
      SELECT DISTINCT nzta_check.organization_id
      FROM public.person_identity_documents AS document
      JOIN public.vehicle_identity_checks AS nzta_check
        ON nzta_check.identity_document_id = document.id
      WHERE document.organization_id = p_organization_id
        AND document.document_kind = 'nzta_mvr_record'
    ) AS scope
   WHERE public.can_access_vehicle_owner_identity(scope.organization_id);

  RETURN jsonb_build_object(
    'people', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'person_record_id', person.id,
        'canonical_person_id', link.canonical_person_id,
        'display_name', person.display_name,
        'review_state', person.review_state,
        'profile_details', coalesce(person.metadata->'profile_details', '{}'::jsonb),
        'date_of_birth', coalesce(person.metadata->'profile_details'->>'date_of_birth', canonical.date_of_birth::text),
        'canonical_review_state', canonical.review_state,
        'face_candidate_ready', EXISTS (
          SELECT 1 FROM public.person_face_templates face
          WHERE face.person_record_id = person.id
            AND face.organization_id = person.organization_id
        ),
        'document_count', (
          SELECT count(*)
          FROM public.person_identity_documents document
          WHERE document.person_record_id = person.id
        )
      ) ORDER BY lower(coalesce(person.display_name, '')), person.created_at)
      FROM (
        SELECT *
        FROM public.person_records
        WHERE organization_id = p_organization_id
          AND (
            v_search = ''
            OR lower(coalesce(display_name, '') || ' ' || coalesce(metadata::text, ''))
              LIKE '%' || v_search || '%'
          )
        ORDER BY created_at DESC
        LIMIT v_limit
      ) AS person
      LEFT JOIN public.canonical_person_links AS link
        ON link.source_table = 'person_records'
       AND link.source_id = person.id
      LEFT JOIN public.canonical_people AS canonical
        ON canonical.id = link.canonical_person_id
    ), '[]'::jsonb),
    'vehicle_total', (
      SELECT count(*)
      FROM public.canonical_vehicles AS vehicle
      WHERE (
        vehicle.org_notes ? p_organization_id::text
        OR EXISTS (
          SELECT 1
          FROM public.canonical_vehicle_links AS link
          WHERE link.canonical_vehicle_id = vehicle.id
            AND nullif(link.metadata->>'organization_id', '')::uuid = ANY(v_visible_organizations)
        )
        OR EXISTS (
          SELECT 1
          FROM public.observations AS observation
          WHERE observation.organization_id = ANY(v_visible_organizations)
            AND observation.canonical_vehicle_id = vehicle.id
        )
        OR EXISTS (
          SELECT 1
          FROM public.cctv_entity_observations AS observation
          WHERE observation.organization_id = ANY(v_visible_organizations)
            AND observation.canonical_vehicle_id = vehicle.id
        )
      )
      AND (
        v_search = ''
        OR lower(concat_ws(
          ' ',
          vehicle.plate_number,
          vehicle.make,
          vehicle.model,
          vehicle.colour,
          vehicle.body_type
        )) LIKE '%' || v_search || '%'
      )
    ),
    'vehicles', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'id', vehicle.id,
        'plate_number', vehicle.plate_number,
        'make', vehicle.make,
        'model', vehicle.model,
        'year', vehicle.year,
        'colour', vehicle.colour,
        'body_type', vehicle.body_type,
        'rego_status', vehicle.rego_status,
        'rego_expiry', vehicle.rego_expiry,
        'wof_status', vehicle.wof_status,
        'wof_expiry', vehicle.wof_expiry,
        'cof_status', vehicle.cof_status,
        'cof_expiry', vehicle.cof_expiry,
        'notes', vehicle.org_notes->p_organization_id::text->>'text',
        'compliance_source', vehicle.compliance_source,
        'compliance_checked_at', vehicle.compliance_checked_at,
        'observation_count', (
          SELECT count(*)
          FROM public.observations AS observation
          WHERE observation.organization_id = ANY(v_visible_organizations)
            AND observation.canonical_vehicle_id = vehicle.id
        ),
        'evidence_count', (
          SELECT count(*)
          FROM public.observations AS observation
          JOIN public.evidence_items AS evidence
            ON evidence.organization_id = observation.organization_id
           AND evidence.metadata->>'observation_id' = observation.id::text
          WHERE observation.organization_id = ANY(v_visible_organizations)
            AND observation.canonical_vehicle_id = vehicle.id
        ),
        'first_seen_at', (
          SELECT min(observation.observed_at)
          FROM public.observations AS observation
          WHERE observation.organization_id = ANY(v_visible_organizations)
            AND observation.canonical_vehicle_id = vehicle.id
        ),
        'last_seen_at', (
          SELECT max(observation.observed_at)
          FROM public.observations AS observation
          WHERE observation.organization_id = ANY(v_visible_organizations)
            AND observation.canonical_vehicle_id = vehicle.id
        ),
        'source_kinds', coalesce((
          SELECT jsonb_agg(source.kind ORDER BY source.kind)
          FROM (
            SELECT DISTINCT CASE
              WHEN observation.module_key = 'cctv_review' THEN 'CCTV review'
              WHEN observation.plate_source = 'historical_import' THEN 'Approved patrol record'
              ELSE 'Field observation'
            END AS kind
            FROM public.observations AS observation
            WHERE observation.organization_id = ANY(v_visible_organizations)
              AND observation.canonical_vehicle_id = vehicle.id
          ) AS source
        ), '[]'::jsonb)
      ) ORDER BY coalesce(vehicle.last_seen_at, vehicle.updated_at) DESC, vehicle.plate_number)
      FROM (
        SELECT *
        FROM public.canonical_vehicles AS candidate
        WHERE (
          candidate.org_notes ? p_organization_id::text
          OR EXISTS (
            SELECT 1
            FROM public.canonical_vehicle_links AS link
            WHERE link.canonical_vehicle_id = candidate.id
              AND nullif(link.metadata->>'organization_id', '')::uuid = ANY(v_visible_organizations)
          )
          OR EXISTS (
            SELECT 1
            FROM public.observations AS observation
            WHERE observation.organization_id = ANY(v_visible_organizations)
              AND observation.canonical_vehicle_id = candidate.id
          )
          OR EXISTS (
            SELECT 1
            FROM public.cctv_entity_observations AS observation
            WHERE observation.organization_id = ANY(v_visible_organizations)
              AND observation.canonical_vehicle_id = candidate.id
          )
        )
        AND (
          v_search = ''
          OR lower(concat_ws(
            ' ',
            candidate.plate_number,
            candidate.make,
            candidate.model,
            candidate.colour,
            candidate.body_type
          )) LIKE '%' || v_search || '%'
        )
        ORDER BY coalesce(candidate.last_seen_at, candidate.updated_at) DESC, candidate.plate_number
        LIMIT v_limit
      ) AS vehicle
    ), '[]'::jsonb),
    'documents', coalesce((
      -- NZTA Motor Vehicle Register records linked to a check stay masked until
      -- the caller opens a purpose-stated reveal for that vehicle or person.
      SELECT jsonb_agg(CASE WHEN restriction.restricted THEN jsonb_build_object(
        'id', document.id,
        'document_kind', document.document_kind,
        'review_state', document.review_state,
        'created_at', document.created_at,
        'reviewed_at', document.reviewed_at,
        'nzta_restricted', true,
        'canonical_vehicle_id', nzta_check.canonical_vehicle_id,
        'plate_number', nzta_vehicle.plate_number
      ) ELSE jsonb_build_object(
        'id', document.id,
        'person_record_id', document.person_record_id,
        'evidence_item_id', document.evidence_item_id,
        'attachment_id', document.attachment_id,
        'document_kind', document.document_kind,
        'extracted_fields', document.extracted_fields,
        'review_state', document.review_state,
        'review_notes', document.review_notes,
        'created_at', document.created_at,
        'reviewed_at', document.reviewed_at,
        'file_name', attachment.file_name,
        'file_type', attachment.file_type,
        'storage_bucket', attachment.storage_bucket,
        'storage_path', attachment.storage_path,
        'nzta_restricted', false,
        'canonical_vehicle_id', nzta_check.canonical_vehicle_id,
        'plate_number', nzta_vehicle.plate_number
      ) END ORDER BY document.created_at DESC)
      FROM public.person_identity_documents AS document
      LEFT JOIN public.bob_attachments AS attachment
        ON attachment.id = document.attachment_id
      LEFT JOIN public.vehicle_identity_checks AS nzta_check
        ON nzta_check.identity_document_id = document.id
      LEFT JOIN public.canonical_vehicles AS nzta_vehicle
        ON nzta_vehicle.id = nzta_check.canonical_vehicle_id
      CROSS JOIN LATERAL (
        SELECT document.document_kind = 'nzta_mvr_record' AND nzta_check.id IS NOT NULL
          AND NOT coalesce(
            nzta_check.organization_id = ANY(coalesce(v_owner_access_orgs, ARRAY[]::uuid[]))
            AND (
              EXISTS (
                SELECT 1 FROM public.nzta_register_access_log AS reveal
                WHERE reveal.actor_user_id = v_uid
                  AND reveal.subject_type = 'vehicle'
                  AND reveal.subject_id = nzta_check.canonical_vehicle_id
                  AND reveal.organization_id = nzta_check.organization_id
                  AND reveal.expires_at > clock_timestamp()
              )
              OR (
                nzta_check.canonical_person_id IS NOT NULL
                AND EXISTS (
                  SELECT 1 FROM public.nzta_register_access_log AS reveal
                  WHERE reveal.actor_user_id = v_uid
                    AND reveal.subject_type = 'person'
                    AND reveal.subject_id = nzta_check.canonical_person_id
                    AND reveal.organization_id = nzta_check.organization_id
                    AND reveal.expires_at > clock_timestamp()
                )
              )
            ),
            false
          ) AS restricted
      ) AS restriction
      WHERE document.organization_id = p_organization_id
    ), '[]'::jsonb)
  );
END;
$function$;
COMMENT ON FUNCTION "public"."get_identity_registry"(p_organization_id uuid, p_search text, p_limit integer) IS 'Administrator-only tenant registry of people and all canonical vehicles evidenced by the organization or its accepted operational clients. Vehicle results include source, sighting, and evidence summaries. NZTA Motor Vehicle Register documents linked to a check return only id, kind, state, vehicle and nzta_restricted=true until the caller opens a purpose-stated reveal for the vehicle or person.';
REVOKE ALL ON FUNCTION "public"."get_identity_registry"(p_organization_id uuid, p_search text, p_limit integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_identity_registry"(p_organization_id uuid, p_search text, p_limit integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_identity_registry"(p_organization_id uuid, p_search text, p_limit integer) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_identity_registry"(p_organization_id uuid, p_search text, p_limit integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_identity_resolution_candidates"(p_identity_document_id uuid)
 RETURNS TABLE(person_record_id uuid, display_name text, review_state text, staff_profile_id uuid, score real, basis text, last_seen_at timestamp with time zone, cctv_sighting_count bigint, approved_identity_document_count bigint, incident_count bigint, confidence_label text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_document public.person_identity_documents%rowtype;
  v_proposed jsonb;
  v_name_key text;
  v_dob date;
BEGIN
  SELECT * INTO v_document FROM public.person_identity_documents WHERE id=p_identity_document_id;
  IF v_document.id IS NULL THEN RAISE EXCEPTION 'Identity document not found'; END IF;
  IF auth.uid() IS NULL OR NOT public.is_admin_for_org(v_document.organization_id) THEN RAISE EXCEPTION 'Identity resolution administrator access required'; END IF;
  v_proposed:=coalesce(v_document.extracted_fields->'proposed','{}'::jsonb);
  v_name_key:=nullif(regexp_replace(lower(trim(coalesce(v_proposed->>'display_name',''))),'[^a-z0-9]+','','g'),'');
  v_dob:=nullif(v_proposed->>'date_of_birth','')::date;
  RETURN QUERY
  WITH face_raw AS (
    SELECT candidate,
      CASE candidate->>'match_kind'
        WHEN 'person_record' THEN nullif(candidate->>'match_id','')::uuid
        WHEN 'observation' THEN (SELECT observation.person_record_id FROM public.cctv_entity_observations observation WHERE observation.id=nullif(candidate->>'observation_id','')::uuid)
      END AS resolved_person_id
    FROM jsonb_array_elements(coalesce(v_document.extracted_fields->'candidate_matches','[]'::jsonb)) candidate
  ), face_hits AS (
    SELECT face_raw.resolved_person_id,
      coalesce((face_raw.candidate->>'score')::real,0)::real AS similarity,
      coalesce(face_raw.candidate->>'basis','face_similarity') AS match_basis,
      nullif(face_raw.candidate->>'last_seen_at','')::timestamptz AS seen_at
    FROM face_raw WHERE face_raw.resolved_person_id IS NOT NULL
  ), field_hits AS (
    SELECT person.id AS resolved_person_id,
      CASE
        WHEN (nullif(v_proposed->>'driver_licence_number','') IS NOT NULL AND person.metadata->'profile_details'->>'driver_licence_number'=v_proposed->>'driver_licence_number')
          OR (nullif(v_proposed->>'firearms_licence_number','') IS NOT NULL AND person.metadata->'profile_details'->>'firearms_licence_number'=v_proposed->>'firearms_licence_number')
          OR (nullif(v_proposed->>'security_licence_number','') IS NOT NULL AND person.metadata->'profile_details'->>'security_licence_number'=v_proposed->>'security_licence_number') THEN 1.0::real
        WHEN v_name_key IS NOT NULL AND regexp_replace(lower(trim(coalesce(person.display_name,''))),'[^a-z0-9]+','','g')=v_name_key
          AND v_dob IS NOT NULL AND nullif(person.metadata->'profile_details'->>'date_of_birth','')::date=v_dob THEN 0.98::real
        ELSE 0.82::real END AS similarity,
      CASE
        WHEN (nullif(v_proposed->>'driver_licence_number','') IS NOT NULL AND person.metadata->'profile_details'->>'driver_licence_number'=v_proposed->>'driver_licence_number')
          OR (nullif(v_proposed->>'firearms_licence_number','') IS NOT NULL AND person.metadata->'profile_details'->>'firearms_licence_number'=v_proposed->>'firearms_licence_number')
          OR (nullif(v_proposed->>'security_licence_number','') IS NOT NULL AND person.metadata->'profile_details'->>'security_licence_number'=v_proposed->>'security_licence_number') THEN 'credential_number_exact'
        WHEN v_dob IS NOT NULL AND nullif(person.metadata->'profile_details'->>'date_of_birth','')::date=v_dob THEN 'name_and_birth_date_exact'
        ELSE 'name_exact' END AS match_basis,
      NULL::timestamptz AS seen_at
    FROM public.person_records person
    WHERE person.organization_id=v_document.organization_id AND person.id<>v_document.person_record_id
      AND (
        (v_name_key IS NOT NULL AND regexp_replace(lower(trim(coalesce(person.display_name,''))),'[^a-z0-9]+','','g')=v_name_key)
        OR (nullif(v_proposed->>'driver_licence_number','') IS NOT NULL AND person.metadata->'profile_details'->>'driver_licence_number'=v_proposed->>'driver_licence_number')
        OR (nullif(v_proposed->>'firearms_licence_number','') IS NOT NULL AND person.metadata->'profile_details'->>'firearms_licence_number'=v_proposed->>'firearms_licence_number')
        OR (nullif(v_proposed->>'security_licence_number','') IS NOT NULL AND person.metadata->'profile_details'->>'security_licence_number'=v_proposed->>'security_licence_number')
      )
  ), ranked AS (
    SELECT DISTINCT ON (hit.resolved_person_id) hit.resolved_person_id,hit.similarity,hit.match_basis,hit.seen_at
    FROM (SELECT * FROM face_hits UNION ALL SELECT * FROM field_hits) hit
    WHERE hit.resolved_person_id<>v_document.person_record_id
    ORDER BY hit.resolved_person_id,hit.similarity DESC,hit.seen_at DESC NULLS LAST
  )
  SELECT person.id,person.display_name,person.review_state,
    nullif(person.metadata->'profile_details'->>'staff_profile_id','')::uuid,
    ranked.similarity,ranked.match_basis,
    coalesce(ranked.seen_at,(SELECT max(observed_at) FROM public.cctv_entity_observations observation WHERE observation.person_record_id=person.id)),
    (SELECT count(*) FROM public.cctv_entity_observations observation WHERE observation.person_record_id=person.id),
    (SELECT count(*) FROM public.person_identity_documents identity_document WHERE identity_document.person_record_id=person.id AND identity_document.review_state='approved'),
    (SELECT count(*) FROM public.incident_person_links incident_person WHERE incident_person.person_record_id=person.id),
    CASE WHEN ranked.similarity>=0.95 THEN 'strong' WHEN ranked.similarity>=0.8 THEN 'possible' ELSE 'weak' END
  FROM ranked JOIN public.person_records person ON person.id=ranked.resolved_person_id
  WHERE person.organization_id=v_document.organization_id
  ORDER BY ranked.similarity DESC,last_seen_at DESC NULLS LAST;
END;
$function$;
COMMENT ON FUNCTION "public"."get_identity_resolution_candidates"(p_identity_document_id uuid) IS 'Admin-only enriched existing-person suggestions from exact credential/name/DOB and biometric similarity, with staff, CCTV, approved-evidence, incident, and freshness context. Suggestions never resolve identity without confirmation.';
REVOKE ALL ON FUNCTION "public"."get_identity_resolution_candidates"(p_identity_document_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_identity_resolution_candidates"(p_identity_document_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_identity_resolution_candidates"(p_identity_document_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_identity_resolution_candidates"(p_identity_document_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_identity_vehicle_activity"(p_organization_id uuid, p_canonical_vehicle_id uuid, p_limit integer DEFAULT 200)
 RETURNS TABLE(observation_id uuid, organization_id uuid, observed_at timestamp with time zone, source_kind text, place_name text, officer_notes text, source_document_name text, source_reference text, source_locator text, evidence_items jsonb)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_admin_for_org(p_organization_id) THEN
    RAISE EXCEPTION 'Identity registry administrator access required';
  END IF;

  RETURN QUERY
  WITH visible_organizations AS (
    SELECT p_organization_id AS id
    UNION
    SELECT unnest(public.get_descendant_organizations(p_organization_id))
    UNION
    SELECT agreement.client_organization_id
    FROM public.service_agreements AS agreement
    WHERE agreement.provider_organization_id = p_organization_id
      AND agreement.agreement_type = 'operational'
  )
  SELECT
    observation.id,
    observation.organization_id,
    observation.observed_at,
    CASE
      WHEN observation.module_key = 'cctv_review' THEN 'CCTV review'
      WHEN observation.plate_source = 'historical_import' THEN 'Approved patrol record'
      ELSE 'Field observation'
    END,
    coalesce(zone.name, site.name, location.name, 'Place not recorded'),
    observation.officer_notes,
    observation.source_document_name,
    observation.source_reference,
    observation.source_locator,
    coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'id', coalesce(evidence.id, supporting.id),
        'storage_path', supporting.storage_path,
        'captured_at', coalesce(evidence.captured_at, supporting.captured_at),
        'sha256_hash', evidence.sha256_hash,
        'description', coalesce(
          evidence.metadata->>'description',
          supporting.notes
        ),
        'original_name', evidence.metadata->>'original_name',
        'source_note', evidence.metadata->>'source_note'
      ) ORDER BY coalesce(evidence.captured_at, supporting.captured_at))
      FROM public.observation_supporting_evidence AS supporting
      LEFT JOIN public.evidence_items AS evidence
        ON evidence.organization_id = supporting.organization_id
       AND evidence.storage_path = supporting.storage_path
      WHERE supporting.organization_id = observation.organization_id
        AND supporting.observation_id = observation.id
    ), '[]'::jsonb)
  FROM public.observations AS observation
  JOIN visible_organizations AS visible
    ON visible.id = observation.organization_id
  LEFT JOIN public.location_zones AS zone
    ON zone.id = observation.zone_id
  LEFT JOIN public.client_sites AS site
    ON site.id = observation.site_id
  LEFT JOIN public.locations AS location
    ON location.id = observation.location_id
  WHERE observation.canonical_vehicle_id = p_canonical_vehicle_id
  ORDER BY observation.observed_at DESC, observation.id
  LIMIT least(greatest(coalesce(p_limit, 200), 1), 500);
END;
$function$;
COMMENT ON FUNCTION "public"."get_identity_vehicle_activity"(p_organization_id uuid, p_canonical_vehicle_id uuid, p_limit integer) IS 'Administrator-only observation and private-evidence history for a canonical vehicle across the provider organization and accepted operational clients.';
REVOKE ALL ON FUNCTION "public"."get_identity_vehicle_activity"(p_organization_id uuid, p_canonical_vehicle_id uuid, p_limit integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_identity_vehicle_activity"(p_organization_id uuid, p_canonical_vehicle_id uuid, p_limit integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_identity_vehicle_activity"(p_organization_id uuid, p_canonical_vehicle_id uuid, p_limit integer) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_identity_vehicle_activity"(p_organization_id uuid, p_canonical_vehicle_id uuid, p_limit integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_incident_people"(p_incident_id uuid)
 RETURNS TABLE(link_id uuid, canonical_person_id uuid, person_record_id uuid, staff_profile_id uuid, display_name text, involvement_role text, source_kind text, review_state text, created_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL OR NOT public.can_record_incident_person(p_incident_id,auth.uid()) THEN RAISE EXCEPTION 'Incident person access denied'; END IF;
  RETURN QUERY SELECT link.id,link.canonical_person_id,link.person_record_id,link.staff_profile_id,
    coalesce(person.display_name,profile.display_name,'Unnamed person'),link.involvement_role,link.source_kind,person.review_state,link.created_at
  FROM public.incident_person_links link
  LEFT JOIN public.person_records person ON person.id=link.person_record_id
  LEFT JOIN public.staff_profiles staff ON staff.id=link.staff_profile_id
  LEFT JOIN public.user_profiles profile ON profile.id=coalesce(staff.user_id,staff.id)
  WHERE link.incident_id=p_incident_id ORDER BY link.created_at;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."get_incident_people"(p_incident_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_incident_people"(p_incident_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_incident_people"(p_incident_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_incident_people"(p_incident_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_live_officer_positions"(p_organization_id uuid, p_since_minutes integer DEFAULT 240, p_zone_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_reach uuid[];
  v_since timestamptz := now() - make_interval(mins => greatest(coalesce(p_since_minutes, 240), 5));
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_organization_id IS NULL THEN RAISE EXCEPTION 'An organisation is required'; END IF;
  IF NOT (public.is_admin_for_org(p_organization_id) OR public.user_can_operate_organization(p_organization_id)) THEN
    RAISE EXCEPTION 'Not authorised to view live positions for this organisation';
  END IF;
  v_reach := array(SELECT DISTINCT d FROM unnest(public.get_descendant_organizations(p_organization_id) || p_organization_id) d);

  RETURN jsonb_build_object(
    'organization_id', p_organization_id,
    'reach', to_jsonb(v_reach),
    'since', v_since,
    'refreshed_at', now(),
    'officers', coalesce((
      WITH on_shift AS (
        SELECT DISTINCT ON (s.officer_user_id) s.officer_user_id, s.id, s.status, s.scheduled_start, s.scheduled_end, s.organization_id,
               s.service_type, s.zone_id, s.location_id, s.patrol_route_id, s.service_agreement_location_id
        FROM public.shifts s
        WHERE s.organization_id = ANY(v_reach)
          AND s.status IN ('published', 'accepted', 'in_progress')
          AND s.scheduled_start <= now() + interval '1 hour'
          AND s.scheduled_end >= now() - interval '1 hour'
        ORDER BY s.officer_user_id, CASE s.status WHEN 'in_progress' THEN 0 WHEN 'accepted' THEN 1 ELSE 2 END, s.scheduled_start
      ),
      latest AS (
        -- Positions stamped at the branch reach, plus the latest position of anyone on a current shift here wherever it was stamped.
        SELECT DISTINCT ON (g.officer_id) g.officer_id, g.id, g.gps_lat, g.gps_lng, g.accuracy_meters, g.heading, g.speed_kmh,
               g.activity_type, g.recorded_at, g.detected_zone_id, g.shift_id, g.physical_address, g.organization_id
        FROM public.officer_gps_log g
        WHERE g.recorded_at >= v_since
          AND (g.organization_id = ANY(v_reach) OR g.officer_id IN (SELECT os.officer_user_id FROM on_shift os))
        ORDER BY g.officer_id, g.recorded_at DESC
      ),
      alerting AS (
        SELECT DISTINCT ON (a.officer_user_id) a.officer_user_id, a.id, a.alert_type, a.status, a.triggered_at, a.gps_lat, a.gps_lng
        FROM public.welfare_alerts a
        WHERE a.organization_id = ANY(v_reach) AND a.status IN ('pending', 'acknowledged')
        ORDER BY a.officer_user_id, a.triggered_at DESC
      ),
      shift_site AS (
        -- The contracted place the shift is for: name, and whether the latest fix is on it (boundary, or the site's on-site radius).
        SELECT os.id AS shift_id, cs.id AS site_id, cs.name AS site_name,
               CASE WHEN l.gps_lat IS NULL OR l.gps_lng IS NULL OR coalesce(cs.boundary, cs.center_point) IS NULL THEN NULL
                    ELSE (cs.boundary IS NOT NULL AND ST_Covers(cs.boundary, ST_SetSRID(ST_Point(l.gps_lng, l.gps_lat), 4326)))
                         OR ST_DWithin(coalesce(cs.boundary, cs.center_point)::geography, ST_SetSRID(ST_Point(l.gps_lng, l.gps_lat), 4326)::geography, coalesce(cs.onsite_radius_meters, 10))
               END AS on_site,
               CASE WHEN l.gps_lat IS NULL OR l.gps_lng IS NULL OR coalesce(cs.boundary, cs.center_point) IS NULL THEN NULL
                    ELSE round(ST_Distance(coalesce(cs.boundary, cs.center_point)::geography, ST_SetSRID(ST_Point(l.gps_lng, l.gps_lat), 4326)::geography))::integer
               END AS distance_m
        FROM on_shift os
        JOIN public.service_agreement_locations sal ON sal.id = os.service_agreement_location_id
        JOIN public.client_sites cs ON cs.id = sal.site_id
        LEFT JOIN latest l ON l.officer_id = os.officer_user_id
      ),
      people AS (
        SELECT officer_id AS user_id FROM latest
        UNION SELECT officer_user_id FROM on_shift
        UNION SELECT officer_user_id FROM alerting
      )
      SELECT jsonb_agg(jsonb_build_object(
        'officer_id', p.user_id,
        'officer_name', coalesce(up.display_name, up.email, p.user_id::text),
        'home_organization_id', up.organization_id,
        'gps_lat', coalesce(l.gps_lat, al.gps_lat),
        'gps_lng', coalesce(l.gps_lng, al.gps_lng),
        'accuracy_meters', l.accuracy_meters,
        'heading', l.heading,
        'speed_kmh', l.speed_kmh,
        'activity_type', coalesce(l.activity_type, CASE WHEN al.id IS NOT NULL THEN 'active_welfare_alert' END),
        'recorded_at', coalesce(l.recorded_at, al.triggered_at),
        'physical_address', l.physical_address,
        'detected_zone_id', l.detected_zone_id,
        'zone_name', (SELECT z.name FROM public.location_zones z WHERE z.id = coalesce(l.detected_zone_id, os.zone_id)),
        'site', CASE WHEN ss.site_id IS NULL THEN NULL ELSE jsonb_build_object('id', ss.site_id, 'name', ss.site_name, 'on_site', ss.on_site, 'distance_m', ss.distance_m) END,
        'position_organization_id', l.organization_id,
        'shift', CASE WHEN os.id IS NULL THEN NULL ELSE jsonb_build_object(
          'id', os.id, 'status', os.status, 'scheduled_start', os.scheduled_start, 'scheduled_end', os.scheduled_end,
          'organization_id', os.organization_id, 'organization_name', (SELECT o.name FROM public.organizations o WHERE o.id = os.organization_id),
          'service_type', os.service_type, 'zone_id', os.zone_id,
          'route_name', (SELECT r.name FROM public.patrol_routes r WHERE r.id = os.patrol_route_id),
          'work_unit_name', (SELECT wu.name FROM public.roster_slots rs JOIN public.roster_work_units wu ON wu.id = rs.work_unit_id WHERE rs.linked_shift_id = os.id LIMIT 1)) END,
        'welfare', (SELECT jsonb_build_object('enabled', w.welfare_check_enabled, 'check_interval_minutes', w.check_interval_minutes, 'last_checkin_at', w.last_checkin_at)
                    FROM public.officer_welfare_settings w WHERE w.officer_user_id = p.user_id
                    ORDER BY (w.organization_id = ANY(v_reach)) DESC, w.updated_at DESC LIMIT 1),
        'alert', CASE WHEN al.id IS NULL THEN NULL ELSE jsonb_build_object('id', al.id, 'alert_type', al.alert_type, 'status', al.status, 'triggered_at', al.triggered_at) END
      ) ORDER BY (al.id IS NOT NULL) DESC, (os.id IS NOT NULL) DESC, coalesce(up.display_name, up.email))
      FROM people p
      JOIN public.user_profiles up ON up.id = p.user_id
      LEFT JOIN latest l ON l.officer_id = p.user_id
      LEFT JOIN on_shift os ON os.officer_user_id = p.user_id
      LEFT JOIN shift_site ss ON ss.shift_id = os.id
      LEFT JOIN alerting al ON al.officer_user_id = p.user_id
      WHERE p_zone_ids IS NULL OR cardinality(p_zone_ids) = 0
         OR l.detected_zone_id = ANY(p_zone_ids) OR os.zone_id = ANY(p_zone_ids)
    ), '[]'::jsonb)
  );
END;
$function$;
COMMENT ON FUNCTION "public"."get_live_officer_positions"(p_organization_id uuid, p_since_minutes integer, p_zone_ids uuid[]) IS 'Live picture for an organisation and its branches: latest breadcrumb per officer within the window, everyone on a current shift there (with or without a fix), everyone with an open welfare alert; each with current shift, welfare settings and alert. Administrator or operator of the organisation only. Optional zone filter on detected_zone_id / shift zone.';
REVOKE ALL ON FUNCTION "public"."get_live_officer_positions"(p_organization_id uuid, p_since_minutes integer, p_zone_ids uuid[]) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_live_officer_positions"(p_organization_id uuid, p_since_minutes integer, p_zone_ids uuid[]) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_live_officer_positions"(p_organization_id uuid, p_since_minutes integer, p_zone_ids uuid[]) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_live_officer_positions"(p_organization_id uuid, p_since_minutes integer, p_zone_ids uuid[]) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_manageable_user_identities"(p_operating_organization_id uuid)
 RETURNS TABLE(id uuid, display_name text, role text, email text, phone text, module_access text[], deactivated_at timestamp with time zone, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_org public.organizations%rowtype;
begin
  if v_actor is null or not public.user_can_operate_organization(p_operating_organization_id) then
    raise exception 'Active authorized operating organisation required';
  end if;
  select * into v_org from public.organizations o where o.id = p_operating_organization_id and o.organization_type in ('owner', 'service_provider', 'branch') and o.active;
  if not found then raise exception 'Active operating organisation required'; end if;

  if v_org.organization_type = 'branch' then
    return query
    select user_profile.id, user_profile.display_name, user_profile.role, user_profile.email, user_profile.phone,
      user_profile.module_access, user_profile.deactivated_at, user_profile.updated_at
    from public.staff_branch_authorisations assignment
    join public.user_profiles user_profile on user_profile.id = assignment.user_id
    where assignment.branch_org_id = v_org.id
      and public.staff_branch_authorisation_manager_can_manage(v_actor, v_org.id, user_profile.id)
    order by user_profile.display_name nulls last, user_profile.email;
  else
    -- The organisation itself: its own people (home or employer), for its administrators.
    if not public.is_admin_for_org(v_org.id) then raise exception 'Organisation administrator required'; end if;
    return query
    select user_profile.id, user_profile.display_name, user_profile.role, user_profile.email, user_profile.phone,
      user_profile.module_access, user_profile.deactivated_at, user_profile.updated_at
    from public.user_profiles user_profile
    where (user_profile.organization_id = v_org.id or user_profile.employer_organization_id = v_org.id)
      and user_profile.role <> 'grand_master'
    order by user_profile.display_name nulls last, user_profile.email;
  end if;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."get_manageable_user_identities"(p_operating_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_manageable_user_identities"(p_operating_organization_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_manageable_user_identities"(p_operating_organization_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_manageable_user_identities"(p_operating_organization_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_median_fuel_price"(p_organization_id uuid, p_fuel_type text, p_as_at date DEFAULT CURRENT_DATE, p_months integer DEFAULT 3)
 RETURNS TABLE(fuel_type text, median_price_per_litre numeric, observation_count bigint, window_start date, window_end date, latest_observed_on date, source_names text[], source_urls text[])
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with bounds as (
    select (coalesce(p_as_at, current_date) - make_interval(months => greatest(coalesce(p_months, 3), 1)))::date as start_on,
           coalesce(p_as_at, current_date)::date as end_on
  ), rows as (
    select o.* from public.fuel_price_observations o, bounds b
    where o.organization_id = p_organization_id and o.fuel_type = p_fuel_type
      and o.observed_on >= b.start_on and o.observed_on <= b.end_on
  )
  select p_fuel_type,
         percentile_cont(0.5) within group (order by r.price_per_litre)::numeric,
         count(*)::bigint,
         (select start_on from bounds), (select end_on from bounds), max(r.observed_on),
         array_agg(distinct r.source_name order by r.source_name),
         array_agg(distinct r.source_url order by r.source_url)
  from rows r
  group by p_fuel_type;
$function$;
COMMENT ON FUNCTION "public"."get_median_fuel_price"(p_organization_id uuid, p_fuel_type text, p_as_at date, p_months integer) IS 'Returns the median website-backed fuel price over the trailing p_months calendar window, with count and source provenance. Does not change IRD per-km charge rules.';
REVOKE ALL ON FUNCTION "public"."get_median_fuel_price"(p_organization_id uuid, p_fuel_type text, p_as_at date, p_months integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_median_fuel_price"(p_organization_id uuid, p_fuel_type text, p_as_at date, p_months integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_median_fuel_price"(p_organization_id uuid, p_fuel_type text, p_as_at date, p_months integer) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_median_fuel_price"(p_organization_id uuid, p_fuel_type text, p_as_at date, p_months integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_noise_attendance_report"(p_dispatch_job_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_role text;
  v_job public.dispatch_jobs%rowtype;
  v_custodian boolean;
  v_harmed_party_reader boolean;
  v_source_reader boolean;
  v_stops jsonb;
  v_assessments jsonb;
  v_interactions jsonb;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT * INTO v_job FROM public.dispatch_jobs d WHERE d.id = p_dispatch_job_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('available', false, 'reason', 'no_basis'); END IF;
  SELECT p.role INTO v_role FROM public.user_profiles p WHERE p.id = v_user AND p.deactivated_at IS NULL AND p.organization_id = v_job.organization_id;

  -- Bases are never NULL: a reader outside the custodian org has no role row, and NULL must redact, never disclose.
  v_custodian := COALESCE(public.is_admin_for_org(v_job.organization_id) OR v_role = 'admin_officer', false);
  v_harmed_party_reader := COALESCE(v_job.harmed_party_site_id IS NOT NULL AND public.has_location_access(v_job.harmed_party_site_id, NULL::uuid, 'client_reads_provider'), false);
  v_source_reader := COALESCE(v_job.client_site_id IS NOT NULL AND public.has_location_access(v_job.client_site_id, NULL::uuid, 'client_reads_provider'), false);
  IF NOT (v_custodian OR v_harmed_party_reader OR v_source_reader OR COALESCE(public.org_access_allowed(v_job.organization_id), false)) THEN
    RETURN jsonb_build_object('available', false, 'reason', 'no_basis');
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'place_role', st.place_role, 'visit_number', st.visit_number,
      'site_id', CASE WHEN st.place_role <> 'harmed_party_place' OR v_custodian OR v_harmed_party_reader THEN st.site_id ELSE NULL END,
      'sla_arrive_by', st.sla_arrive_by, 'arrived_at', st.actual_arrived_at, 'departed_at', st.actual_departed_at,
      'sla_status', st.sla_status, 'arrival_verification', st.arrival_verification, 'arrival_distance_m', st.arrival_distance_m,
      'arrived_gps_accuracy', st.arrived_gps_accuracy, 'bwc_reference_recorded', st.bwc_reference IS NOT NULL,
      'officer_notes', CASE WHEN v_custodian THEN st.officer_notes ELSE NULL END
    ) ORDER BY st.actual_arrived_at NULLS LAST, st.visit_number), '[]'::jsonb)
  INTO v_stops FROM public.shift_stops st WHERE st.dispatch_job_id = v_job.id;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'id', na.id, 'assessed_at', na.assessed_at, 'noise_source', na.noise_source, 'noise_source_address', na.noise_source_address,
      'volume_score', na.volume_score, 'time_score', na.time_score, 'tone_score', na.tone_score, 'matrix_total', na.matrix_total,
      'assessment_distance_to_complainant_m', na.assessment_distance_to_complainant_m, 'assessment_distance_to_source_m', na.assessment_distance_to_source_m,
      'action_taken', na.action_taken, 'end_number', na.end_number, 'notice_number', na.notice_number, 'end_expires_at', na.end_expires_at,
      'end_given_orally', na.end_given_orally, 'end_recipient_role', na.end_recipient_role, 'entry_notice_left', na.entry_notice_left,
      'police_requested', na.police_requested, 'police_present', na.police_present,
      'hs_abort_reason', na.hs_abort_reason, 'follow_up_required', na.follow_up_required, 'review_status', na.review_status,
      'complaint_address', CASE WHEN v_custodian OR v_harmed_party_reader THEN na.complaint_address ELSE NULL END,
      'complainant_site_id', CASE WHEN v_custodian OR v_harmed_party_reader THEN na.complainant_site_id ELSE NULL END,
      'scene_description', CASE WHEN v_custodian THEN na.scene_description ELSE NULL END,
      'occupant_name', CASE WHEN v_custodian THEN na.occupant_name ELSE NULL END
    ) ORDER BY na.assessed_at), '[]'::jsonb)
  INTO v_assessments FROM public.noise_assessments na WHERE na.dispatch_job_id = v_job.id;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'party_role', i.party_role, 'mode', i.mode, 'occurred_at', i.occurred_at, 'at_stop_id', i.shift_stop_id,
      'summary', CASE WHEN v_custodian THEN i.summary ELSE NULL END
    ) ORDER BY i.occurred_at), '[]'::jsonb)
  INTO v_interactions FROM public.job_party_interactions i WHERE i.dispatch_job_id = v_job.id;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_job.organization_id, v_user, 'noise_attendance_report_read', 'dispatch_jobs', v_job.id,
    jsonb_build_object('custodian', v_custodian, 'harmed_party_reader', v_harmed_party_reader, 'source_reader', v_source_reader));

  RETURN jsonb_build_object(
    'available', true,
    'disclosure', jsonb_build_object('custodian', v_custodian, 'harmed_party_place', v_custodian OR v_harmed_party_reader, 'complainant_identity', false),
    'job', jsonb_build_object('id', v_job.id, 'module_key', v_job.module_key, 'job_type', v_job.job_type, 'priority', v_job.priority, 'status', v_job.status,
      'received_at', v_job.created_at, 'dispatched_at', v_job.dispatched_at, 'acknowledged_at', v_job.acknowledged_at, 'en_route_at', v_job.en_route_at,
      'on_scene_at', v_job.on_scene_at, 'completed_at', v_job.completed_at, 'sla_minutes', v_job.sla_minutes, 'sla_respond_by', v_job.sla_respond_by,
      'sla_breached', v_job.sla_breached, 'sla_delay_reason', v_job.sla_delay_reason, 'outcome_notes', v_job.outcome_notes,
      'work_place_site_id', v_job.client_site_id,
      'harmed_party_site_id', CASE WHEN v_custodian OR v_harmed_party_reader THEN v_job.harmed_party_site_id ELSE NULL END,
      'harmed_party_address', CASE WHEN v_custodian OR v_harmed_party_reader THEN v_job.harmed_party_address ELSE NULL END),
    'attendances', v_stops,
    'assessments', v_assessments,
    'interactions', v_interactions
  );
END;
$function$;
REVOKE ALL ON FUNCTION "public"."get_noise_attendance_report"(p_dispatch_job_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_noise_attendance_report"(p_dispatch_job_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_noise_attendance_report"(p_dispatch_job_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_noise_attendance_report"(p_dispatch_job_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_notice_expiry_register"(p_window_days integer DEFAULT 30, p_expired_days integer DEFAULT 90)
 RETURNS TABLE(notice_id uuid, organization_id uuid, organization_name text, notice_type text, notice_number text, issued_at timestamp with time zone, expires_at timestamp with time zone, expiry_state text, days_remaining integer, canonical_person_id uuid, person_display_name text, location_name text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_window integer := least(greatest(coalesce(p_window_days, 30), 0), 365);
  v_expired integer := least(greatest(coalesce(p_expired_days, 90), 0), 730);
  v_orgs uuid[];
BEGIN
  IF v_actor IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.user_profiles
    WHERE id = v_actor AND deactivated_at IS NULL
      AND role IN ('grand_master', 'master', 'admin', 'admin_officer')
  ) THEN
    RAISE EXCEPTION 'Active operations role required';
  END IF;
  v_orgs := array(SELECT o.id FROM public.organizations o WHERE public.org_access_allowed(o.id));
  RETURN QUERY
  SELECT notice.id, notice.organization_id, org.name, notice.notice_type, notice.notice_number,
    notice.issued_at, notice.expires_at,
    public.notice_expiry_state(notice.status, notice.expires_at, v_window),
    ((notice.expires_at AT TIME ZONE 'Pacific/Auckland')::date
      - (clock_timestamp() AT TIME ZONE 'Pacific/Auckland')::date)::integer,
    person.id, person.display_name, place.name
  FROM public.notices notice
  JOIN public.organizations org ON org.id = notice.organization_id
  LEFT JOIN public.canonical_people person ON person.id = notice.person_id
  LEFT JOIN public.observations observation ON observation.id = notice.observation_id
  LEFT JOIN public.locations place ON place.id = coalesce(notice.location_id, observation.location_id)
  WHERE notice.organization_id = ANY (v_orgs)
    AND notice.status = 'issued'
    AND notice.notice_type IN ('trespass', 'warning')
    AND notice.expires_at IS NOT NULL
    AND notice.expires_at <= clock_timestamp() + make_interval(days => v_window)
    AND notice.expires_at > clock_timestamp() - make_interval(days => v_expired)
  ORDER BY notice.expires_at;
END;
$function$;
COMMENT ON FUNCTION "public"."get_notice_expiry_register"(p_window_days integer, p_expired_days integer) IS 'Issued trespass and warning notices expiring soon or expired recently, visible only to active operations roles and scoped to their authorised organisations.';
REVOKE ALL ON FUNCTION "public"."get_notice_expiry_register"(p_window_days integer, p_expired_days integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_notice_expiry_register"(p_window_days integer, p_expired_days integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_notice_expiry_register"(p_window_days integer, p_expired_days integer) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."get_nzscv_supplier_dashboard"(p_search text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_role text;
  v_search text := upper(regexp_replace(coalesce(p_search, ''), '[^A-Za-z0-9]', '', 'g'));
  v_limit integer := least(greatest(coalesce(p_limit, 50), 1), 100);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;

  SELECT profile.role INTO v_role
  FROM public.user_profiles profile
  WHERE profile.id = v_actor AND profile.deactivated_at IS NULL;

  IF v_role NOT IN ('nzscv_monitor', 'grand_master') THEN
    RAISE EXCEPTION 'NZSCV supplier access required';
  END IF;

  RETURN jsonb_build_object(
    'summary', (
      SELECT jsonb_build_object(
        'registry_total', count(*),
        'active', count(*) FILTER (WHERE register.certificate_status = 'active'),
        'expired', count(*) FILTER (WHERE register.certificate_status = 'expired'),
        'suspended', count(*) FILTER (WHERE register.certificate_status = 'suspended'),
        'cancelled', count(*) FILTER (WHERE register.certificate_status = 'cancelled'),
        'expiring_90_days', count(*) FILTER (WHERE register.certificate_status = 'active' AND register.expiry_date BETWEEN current_date AND current_date + 90),
        'last_registry_update', max(register.updated_at),
        'freedom_camping_lookups_30_days', (
          SELECT count(*) FROM public.observations observation
          WHERE observation.module_key = 'freedom_camping'
            AND observation.canonical_scv_id IS NOT NULL
            AND observation.observed_at >= clock_timestamp() - interval '30 days'
        ),
        'freedom_camping_lookups_total', (
          SELECT count(*) FROM public.observations observation
          WHERE observation.module_key = 'freedom_camping'
            AND observation.canonical_scv_id IS NOT NULL
        )
      )
      FROM public.canonical_scv register
    ),
    'daily_usage', (
      WITH days AS (
        SELECT generate_series(current_date - 29, current_date, interval '1 day')::date AS day
      ), usage AS (
        SELECT observation.observed_at::date AS day, count(*) AS lookups
        FROM public.observations observation
        WHERE observation.module_key = 'freedom_camping'
          AND observation.canonical_scv_id IS NOT NULL
          AND observation.observed_at >= current_date - 29
        GROUP BY observation.observed_at::date
      )
      SELECT coalesce(jsonb_agg(jsonb_build_object('date', days.day, 'lookups', coalesce(usage.lookups, 0)) ORDER BY days.day), '[]'::jsonb)
      FROM days LEFT JOIN usage USING (day)
    ),
    'imports', (
      SELECT coalesce(jsonb_agg(to_jsonb(history) ORDER BY history.created_at DESC), '[]'::jsonb)
      FROM (
        SELECT batch.id, batch.source_name, batch.status, batch.total_rows, batch.valid_rows,
          batch.inserted_rows, batch.updated_rows, batch.skipped_rows, batch.invalid_rows,
          batch.started_at, batch.completed_at, batch.created_at
        FROM public.scv_import_batches batch
        ORDER BY batch.created_at DESC
        LIMIT 12
      ) history
    ),
    'records', (
      SELECT coalesce(jsonb_agg(to_jsonb(record) ORDER BY record.plate_number), '[]'::jsonb)
      FROM (
        SELECT register.id, register.plate_number, register.certificate_number,
          register.certificate_status, register.issued_date, register.expiry_date
        FROM public.canonical_scv_public register
        WHERE v_search = '' OR register.plate_number LIKE '%' || v_search || '%'
          OR upper(coalesce(register.certificate_number, '')) LIKE '%' || v_search || '%'
        ORDER BY register.plate_number
        LIMIT v_limit OFFSET v_offset
      ) record
    ),
    'page', jsonb_build_object('limit', v_limit, 'offset', v_offset, 'search', v_search),
    'privacy', jsonb_build_object(
      'usage_is_aggregate', true,
      'tenant_details_included', false,
      'officer_details_included', false,
      'incident_details_included', false,
      'raw_source_rows_included', false
    )
  );
END;
$function$;
COMMENT ON FUNCTION "public"."get_nzscv_supplier_dashboard"(p_search text, p_limit integer, p_offset integer) IS 'Read-only NZSCV supplier view: public register fields plus aggregate Freedom Camping lookup and import health. No tenant, officer, incident, or raw-source detail.';
REVOKE ALL ON FUNCTION "public"."get_nzscv_supplier_dashboard"(p_search text, p_limit integer, p_offset integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_nzscv_supplier_dashboard"(p_search text, p_limit integer, p_offset integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_nzscv_supplier_dashboard"(p_search text, p_limit integer, p_offset integer) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_nzscv_supplier_dashboard"(p_search text, p_limit integer, p_offset integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_nzta_access_holders"(p_organization_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF auth.uid() IS NULL OR p_organization_id IS NULL OR NOT public.is_admin_for_org(p_organization_id) THEN
    RAISE EXCEPTION 'Organisation administrator required' USING ERRCODE = '42501';
  END IF;
  RETURN coalesce((
    SELECT jsonb_agg(holder ORDER BY (holder->>'holds_access')::boolean DESC, holder->>'display_name')
    FROM (
      SELECT jsonb_build_object(
        'user_id', profile.id, 'display_name', profile.display_name, 'role', profile.role,
        'home_organization', profile.organization_id = p_organization_id,
        'via_role', reach.via_role,
        'direct', direct_grant.id IS NOT NULL, 'granted_at', direct_grant.updated_at,
        'via_preset', preset_grant.found,
        'holds_access', reach.via_role OR direct_grant.id IS NOT NULL OR preset_grant.found
      ) || public.nzta_access_readiness(profile.id, profile.organization_id) AS holder
      FROM public.user_profiles profile
      -- A direct grant at a parent organisation reaches its descendants, the
      -- same way can_access_vehicle_owner_identity resolves it.
      LEFT JOIN LATERAL (
        SELECT grant_row.id, grant_row.updated_at
        FROM public.staff_area_grants grant_row
        WHERE grant_row.user_id = profile.id
          AND grant_row.area = 'vehicle_owner_identity' AND grant_row.status = 'active'
          AND p_organization_id = ANY (public.get_descendant_organizations(grant_row.scope_org_id))
        ORDER BY (grant_row.scope_org_id = p_organization_id) DESC, grant_row.updated_at DESC
        LIMIT 1
      ) direct_grant ON true
      CROSS JOIN LATERAL (
        SELECT EXISTS (
          SELECT 1 FROM public.preset_assignments assignment
          JOIN public.access_presets preset ON preset.id = assignment.preset_id
          WHERE assignment.user_id = profile.id AND assignment.status = 'active'
            AND preset.grants ? 'vehicle_owner_identity'
            AND p_organization_id = ANY (public.get_descendant_organizations(assignment.scope_org_id))
        ) AS found
      ) preset_grant
      -- Mirrors is_admin_for_org for the listed user, so parent-organisation,
      -- provider and platform administrators who can see the register are listed.
      CROSS JOIN LATERAL (
        SELECT profile.role = 'grand_master'
          OR (profile.role IN ('admin', 'admin_officer', 'master') AND (
            p_organization_id = ANY (public.get_descendant_organizations(profile.organization_id))
            OR (profile.role = 'master' AND profile.employer_organization_id IS NOT NULL
                AND p_organization_id = ANY (public.get_descendant_organizations(profile.employer_organization_id)))
            OR EXISTS (
              SELECT 1 FROM public.service_agreements sa
              WHERE (sa.ends_on IS NULL OR sa.ends_on >= current_date)
                AND sa.agreement_type = 'operational'
                AND sa.client_organization_id = p_organization_id
                AND (profile.organization_id = sa.provider_organization_id
                     OR profile.employer_organization_id = sa.provider_organization_id)))) AS via_role
      ) reach
      -- Active staff of this organisation are listed even without access, so
      -- training and confidentiality can be recorded before access is granted.
      WHERE profile.deactivated_at IS NULL
        AND (profile.organization_id = p_organization_id OR reach.via_role
             OR direct_grant.id IS NOT NULL OR preset_grant.found)
    ) holders
  ), '[]'::jsonb);
END;
$function$;
REVOKE ALL ON FUNCTION "public"."get_nzta_access_holders"(p_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_nzta_access_holders"(p_organization_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_nzta_access_holders"(p_organization_id uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."get_nzta_reveal_seconds_remaining"(p_subject_type text, p_subject_id uuid, p_organization_id uuid DEFAULT NULL::uuid)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT ceil(extract(epoch FROM min(org_window.expires_at) - clock_timestamp()))::integer
  FROM (
    SELECT log.organization_id, max(log.expires_at) AS expires_at
    FROM public.nzta_register_access_log log
    WHERE auth.uid() IS NOT NULL AND log.actor_user_id = auth.uid()
      AND log.subject_type = p_subject_type AND log.subject_id = p_subject_id
      AND (p_organization_id IS NULL OR log.organization_id = p_organization_id)
      AND log.expires_at > clock_timestamp()
      AND public.can_access_vehicle_owner_identity(log.organization_id)
    GROUP BY log.organization_id
  ) org_window;
$function$;
REVOKE ALL ON FUNCTION "public"."get_nzta_reveal_seconds_remaining"(p_subject_type text, p_subject_id uuid, p_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_nzta_reveal_seconds_remaining"(p_subject_type text, p_subject_id uuid, p_organization_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_nzta_reveal_seconds_remaining"(p_subject_type text, p_subject_id uuid, p_organization_id uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."get_nzta_s241_summary"(p_organization_id uuid, p_from date, p_to date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_from timestamptz;
  v_to timestamptz;
  v_holders jsonb;
BEGIN
  IF auth.uid() IS NULL OR p_organization_id IS NULL OR NOT public.is_admin_for_org(p_organization_id) THEN
    RAISE EXCEPTION 'Organisation administrator required' USING ERRCODE = '42501';
  END IF;
  IF p_from IS NULL OR p_to IS NULL OR p_to < p_from THEN RAISE EXCEPTION 'Enter a valid reporting period'; END IF;
  v_from := p_from::timestamptz;
  v_to := (p_to + 1)::timestamptz;
  v_holders := coalesce((SELECT jsonb_agg(h) FROM jsonb_array_elements(public.get_nzta_access_holders(p_organization_id)) h
                         WHERE (h->>'holds_access')::boolean), '[]'::jsonb);
  RETURN jsonb_build_object(
    'period', jsonb_build_object('from', p_from, 'to', p_to),
    'lookups', jsonb_build_object(
      'total', (SELECT count(*) FROM public.nzta_register_lookups l
                WHERE l.organization_id = p_organization_id AND l.looked_up_at >= v_from AND l.looked_up_at < v_to),
      'by_purpose', coalesce((SELECT jsonb_object_agg(purpose, n) FROM (
          SELECT l.purpose, count(*) n FROM public.nzta_register_lookups l
          WHERE l.organization_id = p_organization_id AND l.looked_up_at >= v_from AND l.looked_up_at < v_to
          GROUP BY l.purpose) x), '{}'::jsonb),
      'by_outcome', coalesce((SELECT jsonb_object_agg(outcome, n) FROM (
          SELECT l.outcome, count(*) n FROM public.nzta_register_lookups l
          WHERE l.organization_id = p_organization_id AND l.looked_up_at >= v_from AND l.looked_up_at < v_to
          GROUP BY l.outcome) x), '{}'::jsonb),
      'historical_checks_without_purpose', (SELECT count(*) FROM public.vehicle_identity_checks c
          WHERE c.organization_id = p_organization_id AND c.checked_at >= v_from AND c.checked_at < v_to
            AND NOT EXISTS (SELECT 1 FROM public.nzta_register_lookups l WHERE l.vehicle_identity_check_id = c.id))),
    'reveals', jsonb_build_object(
      'total', (SELECT count(*) FROM public.nzta_register_access_log a
                WHERE a.organization_id = p_organization_id AND a.revealed_at >= v_from AND a.revealed_at < v_to),
      'by_purpose', coalesce((SELECT jsonb_object_agg(purpose, n) FROM (
          SELECT a.purpose, count(*) n FROM public.nzta_register_access_log a
          WHERE a.organization_id = p_organization_id AND a.revealed_at >= v_from AND a.revealed_at < v_to
          GROUP BY a.purpose) x), '{}'::jsonb),
      'without_current_training', (SELECT count(*) FROM public.nzta_register_access_log a
          WHERE a.organization_id = p_organization_id AND a.revealed_at >= v_from AND a.revealed_at < v_to
            AND NOT a.training_current)),
    'holders', jsonb_build_object(
      'total', jsonb_array_length(v_holders),
      'training_current', (SELECT count(*) FROM jsonb_array_elements(v_holders) h WHERE (h->>'training_current')::boolean),
      'confidentiality_current', (SELECT count(*) FROM jsonb_array_elements(v_holders) h WHERE (h->>'confidentiality_current')::boolean)),
    'reviews', jsonb_build_object(
      'in_period', (SELECT count(*) FROM public.nzta_access_reviews r
          WHERE r.organization_id = p_organization_id AND r.period_end >= p_from AND r.period_start <= p_to),
      'last_reviewed_at', (SELECT max(r.reviewed_at) FROM public.nzta_access_reviews r WHERE r.organization_id = p_organization_id)),
    'signage', coalesce((SELECT jsonb_agg(jsonb_build_object(
        'zone_id', zone_row.id, 'zone_name', zone_row.name, 'evidence_count', zone_row.evidence_count,
        'sign_types', zone_row.sign_types, 'latest_captured_at', zone_row.latest_captured_at) ORDER BY zone_row.name)
      FROM (
        SELECT zone.id, zone.name, count(sign.id) AS evidence_count,
          coalesce(jsonb_agg(DISTINCT sign.sign_type) FILTER (WHERE sign.id IS NOT NULL), '[]'::jsonb) AS sign_types,
          max(sign.captured_at) AS latest_captured_at
        FROM public.location_zones zone
        LEFT JOIN public.zone_signage_evidence sign ON sign.zone_id = zone.id AND sign.organization_id = p_organization_id
        WHERE zone.organization_id = p_organization_id
        GROUP BY zone.id, zone.name
      ) zone_row), '[]'::jsonb),
    'retention', jsonb_build_object(
      'note', 'Report only. Nothing is deleted until NZTA confirms the retention period.',
      'checks_older_than_18_months', (SELECT count(*) FROM public.vehicle_identity_checks c
          WHERE c.organization_id = p_organization_id AND c.checked_at < clock_timestamp() - interval '18 months'),
      'checks_older_than_2_years', (SELECT count(*) FROM public.vehicle_identity_checks c
          WHERE c.organization_id = p_organization_id AND c.checked_at < clock_timestamp() - interval '2 years'),
      'checks_older_than_5_years', (SELECT count(*) FROM public.vehicle_identity_checks c
          WHERE c.organization_id = p_organization_id AND c.checked_at < clock_timestamp() - interval '5 years'),
      'lookups_older_than_18_months', (SELECT count(*) FROM public.nzta_register_lookups l
          WHERE l.organization_id = p_organization_id AND l.looked_up_at < clock_timestamp() - interval '18 months'),
      'lookups_older_than_2_years', (SELECT count(*) FROM public.nzta_register_lookups l
          WHERE l.organization_id = p_organization_id AND l.looked_up_at < clock_timestamp() - interval '2 years'),
      'lookups_older_than_5_years', (SELECT count(*) FROM public.nzta_register_lookups l
          WHERE l.organization_id = p_organization_id AND l.looked_up_at < clock_timestamp() - interval '5 years'),
      'reveals_older_than_18_months', (SELECT count(*) FROM public.nzta_register_access_log a
          WHERE a.organization_id = p_organization_id AND a.revealed_at < clock_timestamp() - interval '18 months'),
      'reveals_older_than_2_years', (SELECT count(*) FROM public.nzta_register_access_log a
          WHERE a.organization_id = p_organization_id AND a.revealed_at < clock_timestamp() - interval '2 years'),
      'reveals_older_than_5_years', (SELECT count(*) FROM public.nzta_register_access_log a
          WHERE a.organization_id = p_organization_id AND a.revealed_at < clock_timestamp() - interval '5 years'))
  );
END;
$function$;
REVOKE ALL ON FUNCTION "public"."get_nzta_s241_summary"(p_organization_id uuid, p_from date, p_to date) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_nzta_s241_summary"(p_organization_id uuid, p_from date, p_to date) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_nzta_s241_summary"(p_organization_id uuid, p_from date, p_to date) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."get_observation_annotations"(p_observation_ids uuid[])
 RETURNS TABLE(observation_id uuid, vehicle_flagged boolean, hs_concern boolean, hazard_classes text[], notice_issued boolean, prior_notice_count integer, follow_up_open boolean, update_count integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  WITH visible AS (
    SELECT o.id, o.canonical_vehicle_id, o.canonical_person_id, o.plate_number, o.observed_at
    FROM public.observations o
    WHERE o.id = ANY(p_observation_ids[1:200]) AND auth.uid() IS NOT NULL
      AND (public.org_access_allowed(o.organization_id) OR public.org_access_allowed(o.client_org_id)
        OR public.user_has_task_entitlement(auth.uid(), o.id))
  )
  SELECT v.id,
    EXISTS (SELECT 1 FROM public.entity_flags f WHERE f.active AND f.hazard_class IS NULL
      AND public.org_access_allowed(f.organization_id)
      AND ((f.entity_type = 'vehicle' AND f.entity_id = v.canonical_vehicle_id)
        OR (f.entity_type = 'person' AND f.entity_id = v.canonical_person_id))),
    EXISTS (SELECT 1 FROM public.entity_flags f WHERE f.active AND f.hazard_class IS NOT NULL
      AND ((f.entity_type = 'vehicle' AND f.entity_id = v.canonical_vehicle_id)
        OR (f.entity_type = 'person' AND f.entity_id = v.canonical_person_id)))
      OR EXISTS (SELECT 1 FROM public.record_updates r WHERE r.record_kind = 'observation' AND r.record_id = v.id AND r.entry_kind = 'hs_concern'),
    ARRAY(SELECT DISTINCT f.hazard_class FROM public.entity_flags f WHERE f.active AND f.hazard_class IS NOT NULL
      AND ((f.entity_type = 'vehicle' AND f.entity_id = v.canonical_vehicle_id)
        OR (f.entity_type = 'person' AND f.entity_id = v.canonical_person_id))),
    EXISTS (SELECT 1 FROM public.notices n WHERE n.observation_id = v.id)
      OR EXISTS (SELECT 1 FROM public.infringement_notices n WHERE n.observation_id = v.id)
      OR EXISTS (SELECT 1 FROM public.notices_to_vacate n WHERE n.observation_id = v.id),
    (SELECT count(*)::integer FROM (
      SELECT n.id FROM public.infringement_notices n
      WHERE v.plate_number IS NOT NULL AND public.normalize_plate_number(n.plate_number) = public.normalize_plate_number(v.plate_number)
        AND n.issued_at < v.observed_at AND public.org_access_allowed(n.organization_id)
      UNION ALL
      SELECT n.id FROM public.notices_to_vacate n
      WHERE v.plate_number IS NOT NULL AND public.normalize_plate_number(n.plate_number) = public.normalize_plate_number(v.plate_number)
        AND n.issued_at < v.observed_at AND public.org_access_allowed(n.organization_id)
      UNION ALL
      SELECT n.id FROM public.notices n JOIN public.observations prior ON prior.id = n.observation_id
      WHERE v.canonical_vehicle_id IS NOT NULL AND prior.canonical_vehicle_id = v.canonical_vehicle_id
        AND prior.observed_at < v.observed_at AND public.org_access_allowed(n.organization_id)
    ) prior_notices),
    coalesce((SELECT r.entry_kind = 'follow_up_requested' FROM public.record_updates r
      WHERE r.record_kind = 'observation' AND r.record_id = v.id AND r.entry_kind IN ('follow_up_requested', 'follow_up_resolved')
      ORDER BY r.created_at DESC LIMIT 1), false),
    (SELECT count(*)::integer FROM public.record_updates r WHERE r.record_kind = 'observation' AND r.record_id = v.id)
  FROM visible v;
$function$;
COMMENT ON FUNCTION "public"."get_observation_annotations"(p_observation_ids uuid[]) IS 'Status indicators for observations the caller can read: own-organisation of-interest flag, platform H&S concern (hazard flag or recorded hs_concern update), notice issued on this observation, prior notices for the plate/vehicle, open follow-up and update count.';
REVOKE ALL ON FUNCTION "public"."get_observation_annotations"(p_observation_ids uuid[]) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_observation_annotations"(p_observation_ids uuid[]) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_observation_annotations"(p_observation_ids uuid[]) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."get_observation_people"(p_observation_id uuid)
 RETURNS TABLE(mention_id uuid, person_record_id uuid, display_name text, review_state text, aliases text[], mention_role text, status text, basis text, mention_text text, is_identity_of_record boolean, recorded_by_name text, recorded_at timestamp with time zone, reviewed_at timestamp with time zone, review_notes text, can_dismiss boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_obs public.observations%rowtype;
  v_admin boolean;
BEGIN
  SELECT * INTO v_obs FROM public.observations WHERE id = p_observation_id;
  IF auth.uid() IS NULL OR v_obs.id IS NULL OR NOT public.org_access_allowed(v_obs.organization_id) THEN RETURN; END IF;
  v_admin := public.is_admin_for_org(v_obs.organization_id);
  RETURN QUERY
  SELECT m.id, p.id, p.display_name, p.review_state,
    coalesce(ARRAY(SELECT a.alias FROM public.person_record_aliases a WHERE a.person_record_id = p.id AND a.active ORDER BY a.created_at), ARRAY[]::text[]),
    m.mention_role, m.status, m.basis, m.mention_text, p.id = v_obs.person_record_id,
    u.display_name, m.created_at, m.reviewed_at, m.review_notes,
    m.status = 'unconfirmed' AND (v_admin OR m.created_by = auth.uid())
  FROM public.observation_person_mentions m
  JOIN public.person_records p ON p.id = m.person_record_id
  LEFT JOIN public.user_profiles u ON u.id = m.created_by
  WHERE m.observation_id = v_obs.id AND m.status <> 'dismissed'
  UNION ALL
  SELECT NULL::uuid, p.id, p.display_name, p.review_state,
    coalesce(ARRAY(SELECT a.alias FROM public.person_record_aliases a WHERE a.person_record_id = p.id AND a.active ORDER BY a.created_at), ARRAY[]::text[]),
    'identity_of_record', 'confirmed', NULL, NULL, true, NULL, NULL, NULL, NULL, false
  FROM public.person_records p
  WHERE p.id = v_obs.person_record_id
    AND NOT EXISTS (SELECT 1 FROM public.observation_person_mentions m WHERE m.observation_id = v_obs.id AND m.person_record_id = p.id AND m.status <> 'dismissed');
END;
$function$;
REVOKE ALL ON FUNCTION "public"."get_observation_people"(p_observation_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_observation_people"(p_observation_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_observation_people"(p_observation_id uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."get_officer_activity_timeline"(p_officer_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer DEFAULT 1000)
 RETURNS TABLE(event_key text, event_type text, event_at timestamp with time zone, received_at timestamp with time zone, source_table text, source_id uuid, gps_lat double precision, gps_lng double precision, shift_id uuid, site_id uuid, zone_id uuid, summary text, details jsonb)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org_id uuid;
begin
  select organization_id into v_org_id from public.user_profiles where id = p_officer_id;
  if v_org_id is null then return; end if;
  if auth.uid() <> p_officer_id and not public.is_admin_for_org(v_org_id) then raise exception 'Not authorised to view this officer timeline'; end if;
  if p_from is null or p_to is null or p_from >= p_to or p_to - p_from > interval '31 days' then raise exception 'Timeline range must be between 1 second and 31 days'; end if;

  return query
  with events as (
    select 'gps:' || g.id::text, 'gps_' || g.activity_type, g.recorded_at, g.created_at,
      'officer_gps_log'::text, g.id, g.gps_lat, g.gps_lng, g.shift_id, null::uuid, g.detected_zone_id,
      case when g.activity_type = 'gps_update' then 'GPS heartbeat' else replace(g.activity_type, '_', ' ') end,
      jsonb_build_object('accuracy_meters', g.accuracy_meters, 'heading', g.heading, 'speed_kmh', g.speed_kmh, 'client_event_id', g.client_event_id)
    from public.officer_gps_log g
    where g.organization_id = v_org_id and g.officer_id = p_officer_id and g.recorded_at between p_from and p_to

    union all
    select 'welfare_check:' || w.id::text, 'welfare_check', w.checked_in_at, w.checked_in_at,
      'welfare_checks', w.id, w.gps_lat, w.gps_lng, w.shift_id, null::uuid, null::uuid,
      'Welfare check-in: ' || w.status, jsonb_build_object('status', w.status, 'notes', w.notes)
    from public.welfare_checks w where w.organization_id = v_org_id and w.officer_user_id = p_officer_id and w.checked_in_at between p_from and p_to

    union all
    select 'observation:' || o.id::text, 'observation', o.observed_at, o.created_at,
      'observations', o.id, o.gps_lat, o.gps_lng, null::uuid, o.site_id, o.zone_id,
      'Vehicle observation ' || o.plate_number, jsonb_build_object('module_key', o.module_key, 'compliance_status', o.compliance_status, 'plate_number', o.plate_number)
    from public.observations o where o.organization_id = v_org_id and o.officer_id = p_officer_id and o.observed_at between p_from and p_to

    union all
    select 'checkpoint:' || v.id::text, 'checkpoint_visit', v.visited_at, v.visited_at,
      'patrol_checkpoint_visits', v.id, v.gps_lat, v.gps_lng, p.shift_id, null::uuid, null::uuid,
      'Patrol checkpoint visit', jsonb_build_object('checkpoint_id', v.checkpoint_id, 'scan_method', v.scan_method, 'within_radius', v.within_radius, 'notes', v.notes)
    from public.patrol_checkpoint_visits v join public.patrols p on p.id = v.patrol_id
    where v.organization_id = v_org_id and v.officer_user_id = p_officer_id and v.visited_at between p_from and p_to

    union all
    select 'report:' || r.id::text, 'field_report', r.reported_at, r.created_at,
      'officer_field_reports', r.id, r.gps_lat, r.gps_lng, r.shift_id, r.site_id, r.zone_id,
      r.title, jsonb_build_object('report_type', r.report_type, 'severity', r.severity, 'status', r.status, 'immediate_action', r.immediate_action)
    from public.officer_field_reports r where r.organization_id = v_org_id and r.officer_id = p_officer_id and r.reported_at between p_from and p_to

    union all
    select 'stop_action:' || a.id::text, 'shift_stop_action', a.performed_at, a.created_at,
      'shift_stop_actions', a.id, a.gps_lat, a.gps_lng, a.shift_id, null::uuid, null::uuid,
      replace(a.action_type, '_', ' '), jsonb_build_object('outcome', a.outcome, 'notes', a.notes, 'result_table', a.result_table, 'result_record_id', a.result_record_id)
    from public.shift_stop_actions a join public.shifts s on s.id = a.shift_id
    where a.organization_id = v_org_id and s.officer_user_id = p_officer_id and a.performed_at between p_from and p_to

    union all
    select 'dispatch_job:' || j.id::text || ':' || m.milestone, 'dispatch_' || m.milestone, m.at, m.at,
      'dispatch_jobs', j.id, null::double precision, null::double precision, j.shift_id, j.client_site_id, j.zone_id,
      initcap(replace(j.job_type, '_', ' ')) || ' call-out ' || m.label,
      jsonb_build_object('job_type', j.job_type, 'priority', j.priority, 'status', j.status, 'sla_minutes', j.sla_minutes, 'sla_breached', j.sla_breached)
        || case when m.milestone = 'completed' then jsonb_build_object('outcome_notes', j.outcome_notes) else '{}'::jsonb end
    from public.dispatch_jobs j
    cross join lateral (values ('dispatched', 'dispatched', j.dispatched_at), ('acknowledged', 'acknowledged', j.acknowledged_at),
      ('en_route', 'en route', j.en_route_at), ('on_scene', 'on scene', j.on_scene_at), ('completed', 'completed', j.completed_at)) m(milestone, label, at)
    where j.organization_id = v_org_id and j.assigned_officer_id = p_officer_id and m.at between p_from and p_to
  )
  select * from events order by event_at desc limit least(greatest(coalesce(p_limit, 1000), 1), 5000);
end;
$function$;
COMMENT ON FUNCTION "public"."get_officer_activity_timeline"(p_officer_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer) IS 'Returns the authorized officer evidence timeline and atomically audits each successful access.';
REVOKE ALL ON FUNCTION "public"."get_officer_activity_timeline"(p_officer_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_officer_activity_timeline"(p_officer_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_officer_activity_timeline"(p_officer_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_officer_activity_timeline"(p_officer_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_officer_activity_timeline_unlogged"(p_officer_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer DEFAULT 1000)
 RETURNS TABLE(event_key text, event_type text, event_at timestamp with time zone, received_at timestamp with time zone, source_table text, source_id uuid, gps_lat double precision, gps_lng double precision, shift_id uuid, site_id uuid, zone_id uuid, summary text, details jsonb)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org_id uuid;
BEGIN
  SELECT organization_id INTO v_org_id FROM public.user_profiles WHERE id = p_officer_id;
  IF v_org_id IS NULL THEN RETURN; END IF;
  IF auth.uid() <> p_officer_id AND NOT public.is_admin_for_org(v_org_id) THEN RAISE EXCEPTION 'Not authorised to view this officer timeline'; END IF;
  IF p_from IS NULL OR p_to IS NULL OR p_from >= p_to OR p_to - p_from > interval '31 days' THEN RAISE EXCEPTION 'Timeline range must be between 1 second and 31 days'; END IF;

  RETURN QUERY
  WITH events AS (
    SELECT 'gps:' || g.id::text, 'gps_' || g.activity_type, g.recorded_at, g.created_at,
      'officer_gps_log'::text, g.id, g.gps_lat, g.gps_lng, g.shift_id, NULL::uuid, g.detected_zone_id,
      CASE WHEN g.activity_type = 'gps_update' THEN 'GPS heartbeat' ELSE replace(g.activity_type, '_', ' ') END,
      jsonb_build_object('accuracy_meters', g.accuracy_meters, 'heading', g.heading, 'speed_kmh', g.speed_kmh, 'physical_address', g.physical_address, 'client_event_id', g.client_event_id)
    FROM public.officer_gps_log g
    WHERE g.organization_id = v_org_id AND g.officer_id = p_officer_id AND g.recorded_at BETWEEN p_from AND p_to

    UNION ALL
    SELECT 'welfare_check:' || w.id::text, 'welfare_check', w.checked_in_at, w.checked_in_at,
      'welfare_checks', w.id, w.gps_lat, w.gps_lng, w.shift_id, NULL::uuid, NULL::uuid,
      'Welfare check-in: ' || w.status, jsonb_build_object('status', w.status, 'notes', w.notes)
    FROM public.welfare_checks w WHERE w.organization_id = v_org_id AND w.officer_user_id = p_officer_id AND w.checked_in_at BETWEEN p_from AND p_to

    UNION ALL
    SELECT 'observation:' || o.id::text, 'observation', o.observed_at, o.created_at,
      'observations', o.id, o.gps_lat, o.gps_lng, NULL::uuid, o.site_id, o.zone_id,
      'Vehicle observation ' || o.plate_number, jsonb_build_object('module_key', o.module_key, 'compliance_status', o.compliance_status, 'plate_number', o.plate_number)
    FROM public.observations o WHERE o.organization_id = v_org_id AND o.officer_id = p_officer_id AND o.observed_at BETWEEN p_from AND p_to

    UNION ALL
    SELECT 'checkpoint:' || v.id::text, 'checkpoint_visit', v.visited_at, v.visited_at,
      'patrol_checkpoint_visits', v.id, v.gps_lat, v.gps_lng, p.shift_id, NULL::uuid, NULL::uuid,
      'Patrol checkpoint visit', jsonb_build_object('checkpoint_id', v.checkpoint_id, 'scan_method', v.scan_method, 'within_radius', v.within_radius, 'notes', v.notes)
    FROM public.patrol_checkpoint_visits v JOIN public.patrols p ON p.id = v.patrol_id
    WHERE v.organization_id = v_org_id AND v.officer_user_id = p_officer_id AND v.visited_at BETWEEN p_from AND p_to

    UNION ALL
    SELECT 'report:' || r.id::text, 'field_report', r.reported_at, r.created_at, 'officer_field_reports', r.id, r.gps_lat, r.gps_lng, r.shift_id, r.site_id, r.zone_id,
      r.title, jsonb_build_object('report_type', r.report_type, 'severity', r.severity, 'status', r.status, 'immediate_action', r.immediate_action)
    FROM public.officer_field_reports r WHERE r.organization_id = v_org_id AND r.officer_id = p_officer_id AND r.reported_at BETWEEN p_from AND p_to

    UNION ALL
    SELECT 'stop_action:' || a.id::text, 'shift_stop_action', a.performed_at, a.created_at,
      'shift_stop_actions', a.id, a.gps_lat, a.gps_lng, a.shift_id, NULL::uuid, NULL::uuid,
      replace(a.action_type, '_', ' '), jsonb_build_object('outcome', a.outcome, 'notes', a.notes, 'result_table', a.result_table, 'result_record_id', a.result_record_id)
    FROM public.shift_stop_actions a JOIN public.shifts s ON s.id = a.shift_id
    WHERE a.organization_id = v_org_id AND s.officer_user_id = p_officer_id AND a.performed_at BETWEEN p_from AND p_to

    UNION ALL
    SELECT 'dispatch_job:' || j.id::text || ':' || m.milestone, 'dispatch_' || m.milestone, m.at, m.at,
      'dispatch_jobs', j.id, NULL::double precision, NULL::double precision, j.shift_id, j.client_site_id, j.zone_id,
      initcap(replace(j.job_type, '_', ' ')) || ' call-out ' || m.label,
      jsonb_build_object('job_type', j.job_type, 'priority', j.priority, 'status', j.status, 'sla_minutes', j.sla_minutes, 'sla_breached', j.sla_breached)
        || CASE WHEN m.milestone = 'completed' THEN jsonb_build_object('outcome_notes', j.outcome_notes) ELSE '{}'::jsonb END
    FROM public.dispatch_jobs j
    CROSS JOIN LATERAL (VALUES ('dispatched', 'dispatched', j.dispatched_at), ('acknowledged', 'acknowledged', j.acknowledged_at),
      ('en_route', 'en route', j.en_route_at), ('on_scene', 'on scene', j.on_scene_at), ('completed', 'completed', j.completed_at)) m(milestone, label, at)
    WHERE j.organization_id = v_org_id AND j.assigned_officer_id = p_officer_id AND m.at BETWEEN p_from AND p_to
  )
  SELECT * FROM events ORDER BY event_at DESC LIMIT least(greatest(coalesce(p_limit, 1000), 1), 5000);
END;
$function$;
REVOKE ALL ON FUNCTION "public"."get_officer_activity_timeline_unlogged"(p_officer_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_officer_activity_timeline_unlogged"(p_officer_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_officer_activity_timeline_unlogged"(p_officer_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_officer_attendance_readiness"(p_shift_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_source jsonb; v_single boolean; v_stops integer; v_tasks integer; v_open_breaks integer; v_clear boolean;
begin
  if auth.uid() is null or not exists(select 1 from public.user_profiles where id = auth.uid() and deactivated_at is null) then
    raise exception 'Active officer required' using errcode = '42501';
  end if;
  v_source := public.get_officer_recovery_readiness(p_shift_id);
  select service_type = 'static_guarding' and (select count(*) from public.shift_stops where shift_id = s.id) = 1
    into v_single from public.shifts s where id = p_shift_id;
  v_stops := (v_source->>'open_stop_count')::integer;
  v_tasks := (v_source->>'open_required_task_count')::integer;
  if v_single then
    select count(*) into v_stops from public.shift_stops where shift_id = p_shift_id and status not in ('on_scene','completed','skipped','cancelled');
    select count(*) into v_tasks from public.shift_stop_modules sm join public.shift_stops st on st.id = sm.shift_stop_id
      where st.shift_id = p_shift_id and sm.is_required and sm.status not in ('completed','skipped') and sm.module_key <> 'static_guarding';
  end if;
  select count(*) into v_open_breaks from public.shift_breaks where shift_id = p_shift_id and ended_at is null;
  v_clear := v_source->>'status' = 'in_progress' and v_stops = 0 and v_tasks = 0
    and (v_source->>'open_dispatch_job_count')::integer = 0 and (v_source->>'active_welfare_alert_count')::integer = 0 and v_open_breaks = 0;
  return v_source || jsonb_build_object('single_site_attendance',coalesce(v_single,false),
    'open_stop_count',v_stops,'open_required_task_count',v_tasks,'open_break_count',v_open_breaks,
    'can_end_after_debrief',v_clear,'can_end',v_clear and (v_source->>'debrief_submitted')::boolean);
end;
$function$;
REVOKE ALL ON FUNCTION "public"."get_officer_attendance_readiness"(p_shift_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_officer_attendance_readiness"(p_shift_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_officer_attendance_readiness"(p_shift_id uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."get_officer_break_plan"(p_shift_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_shift public.shifts%rowtype; v_slot public.roster_slots%rowtype; v_minutes numeric;
begin
  select * into v_shift from public.shifts where id = p_shift_id;
  if not found or auth.uid() is null or v_shift.officer_user_id is distinct from auth.uid()
    or not exists(select 1 from public.user_profiles where id = auth.uid() and deactivated_at is null) then
    raise exception 'Active assigned officer required' using errcode = '42501';
  end if;
  select * into v_slot from public.roster_slots where linked_shift_id = v_shift.id and status <> 'cancelled';
  select coalesce(sum(extract(epoch from (b.ended_at - b.started_at)) / 60), 0) into v_minutes
    from public.shift_breaks b where b.shift_id = v_shift.id and b.ended_at is not null
      and b.is_paid = not coalesce(v_slot.break_unpaid, false);
  return jsonb_build_object('shift_id', v_shift.id, 'planned_minutes', coalesce(v_slot.planned_break_minutes, 0),
    'unpaid', coalesce(v_slot.break_unpaid, false), 'taken_minutes', v_minutes,
    'review_status', case when coalesce(v_slot.planned_break_minutes, 0) = 0 then 'not_planned'
      when v_minutes = 0 then 'not_recorded' when v_minutes < v_slot.planned_break_minutes then 'short'
      when v_minutes > v_slot.planned_break_minutes then 'long' else 'matched' end);
end;
$function$;
REVOKE ALL ON FUNCTION "public"."get_officer_break_plan"(p_shift_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_officer_break_plan"(p_shift_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_officer_break_plan"(p_shift_id uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."get_officer_data_package"(p_shift_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_org_id uuid;
  v_zones jsonb;
  v_matrix jsonb;
  v_flags jsonb;
  v_rules jsonb;
  v_stops jsonb;
  v_welfare jsonb;
  v_package jsonb;
begin
  if v_user_id is null then raise exception 'Authentication required'; end if;
  select p.organization_id into v_org_id from public.user_profiles p where p.id = v_user_id and p.deactivated_at is null;
  if v_org_id is null then raise exception 'Active officer profile required for data package download'; end if;

  if p_shift_id is not null and not exists (select 1 from public.shifts s where s.id = p_shift_id and s.organization_id = v_org_id) then
    raise exception 'Shift does not belong to the officer organisation';
  end if;

  -- 1. Active location zones (address is the house address)
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', z.id,
    'location_id', z.location_id,
    'name', z.name,
    'address', l.address,
    'zone_type', z.zone_type,
    'module_key', z.module_key,
    'rule_type', z.rule_type,
    'is_active', z.is_active
  )), '[]'::jsonb) into v_zones
  from public.location_zones z
  left join public.locations l on l.id = z.location_id
  where z.organization_id = v_org_id and z.is_active = true;

  -- 2. Current zone compliance matrix
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', m.id,
    'zone_id', m.zone_id,
    'max_consecutive_nights', m.max_consecutive_nights,
    'max_nights_per_month', m.max_nights_per_month,
    'scv_required', m.scv_required,
    'is_current', m.is_current
  )), '[]'::jsonb) into v_matrix
  from public.zone_compliance_matrix m
  where m.organization_id = v_org_id and m.is_current = true;

  -- 3. Active entity flags (vehicle/person)
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', f.id,
    'entity_type', f.entity_type,
    'entity_id', f.entity_id,
    'plate_number', cv.plate_number,
    'flag_type', f.flag_type,
    'flag_reason', f.reason,
    'severity', f.alert_level,
    'is_active', f.active
  )), '[]'::jsonb) into v_flags
  from public.entity_flags f
  left join public.canonical_vehicles cv on f.entity_type = 'vehicle' and cv.id = f.entity_id
  where f.organization_id = v_org_id and f.active = true;

  -- 4. Module rule sets
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', r.id,
    'module_key', r.module_key,
    'name', r.name,
    'evidence_requirements', r.evidence_requirements,
    'approval_policy', r.approval_policy
  )), '[]'::jsonb) into v_rules
  from public.module_rule_sets r
  where r.organization_id = v_org_id;

  -- 5. Patrol stops for current shift if supplied
  if p_shift_id is not null then
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', st.id,
      'site_id', st.site_id,
      'zone_id', st.zone_id,
      'status', st.status,
      'sla_respond_by', st.sla_arrive_by,
      'sla_depart_by', st.sla_depart_by,
      'notes', st.officer_notes,
      'officer_instructions', st.officer_instructions
    )), '[]'::jsonb) into v_stops
    from public.shift_stops st
    where st.shift_id = p_shift_id and st.organization_id = v_org_id;
  else
    v_stops := '[]'::jsonb;
  end if;

  -- 6. Welfare settings
  select to_jsonb(w.*) into v_welfare
  from public.officer_welfare_settings w
  where w.organization_id = v_org_id limit 1;

  v_package := jsonb_build_object(
    'package_timestamp', clock_timestamp(),
    'organization_id', v_org_id,
    'officer_id', v_user_id,
    'shift_id', p_shift_id,
    'location_zones', v_zones,
    'zone_compliance_matrix', v_matrix,
    'entity_flags', v_flags,
    'module_rule_sets', v_rules,
    'shift_stops', v_stops,
    'welfare_settings', coalesce(v_welfare, '{}'::jsonb)
  );

  insert into public.audit_log (
    organization_id, actor_user_id, action, target_table, target_id, metadata
  ) values (
    v_org_id, v_user_id, 'officer_data_package_downloaded', 'user_profiles', v_user_id,
    jsonb_build_object('shift_id', p_shift_id, 'zone_count', jsonb_array_length(v_zones), 'flag_count', jsonb_array_length(v_flags))
  );

  return v_package;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."get_officer_data_package"(p_shift_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_officer_data_package"(p_shift_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_officer_data_package"(p_shift_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_officer_data_package"(p_shift_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_officer_patrol_stops"(p_shift_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_shift public.shifts%rowtype;
begin
  if v_actor is null then raise exception 'Authentication required'; end if;
  if p_shift_id is not null then
    select * into v_shift from public.shifts where id = p_shift_id and officer_user_id = v_actor;
  else
    select * into v_shift from public.shifts
    where officer_user_id = v_actor and status in ('in_progress', 'accepted')
    order by case status when 'in_progress' then 0 else 1 end, scheduled_start desc limit 1;
  end if;
  if not found then return null; end if;

  return jsonb_build_object(
    'shift', jsonb_build_object('id', v_shift.id, 'status', v_shift.status, 'scheduled_start', v_shift.scheduled_start, 'scheduled_end', v_shift.scheduled_end,
      'route_name', (select r.name from public.patrol_routes r where r.id = v_shift.patrol_route_id)),
    'stops', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', st.id, 'stop_order', st.stop_order, 'visit_number', st.visit_number,
        'visits_total', (select count(*) from public.shift_stops v where v.shift_id = st.shift_id and v.patrol_config_id is not distinct from st.patrol_config_id and v.site_id is not distinct from st.site_id and v.zone_id is not distinct from st.zone_id and v.is_adhoc = false),
        'status', st.status, 'sla_status', st.sla_status,
        'sla_window_open', st.sla_window_open, 'sla_arrive_by', st.sla_arrive_by, 'sla_depart_by', st.sla_depart_by,
        'required_dwell_minutes', st.required_dwell_minutes, 'officer_instructions', st.officer_instructions,
        'actual_arrived_at', st.actual_arrived_at, 'actual_departed_at', st.actual_departed_at,
        'actual_travel_distance_km', st.actual_travel_distance_km, 'travel_from_stop_id', st.travel_from_stop_id, 'travel_distance_method', st.travel_distance_method, 'travel_distance_version', st.travel_distance_version, 'arrival_verification', st.arrival_verification, 'arrival_distance_m', st.arrival_distance_m, 'officer_notes', st.officer_notes,
        'module_key', st.module_key,
        -- The toolset for this stop: what the officer is there to do (module-as-data, from shift_stop_modules).
        'modules', coalesce((select jsonb_agg(jsonb_build_object('module_key', m.module_key, 'is_required', m.is_required, 'status', m.status) order by m.is_required desc, m.module_key)
                             from public.shift_stop_modules m where m.shift_stop_id = st.id), '[]'::jsonb),
        'place', case
          when st.site_id is not null then (select jsonb_build_object('kind', 'site', 'name', cs.name, 'address', cs.address, 'access_instructions', cs.access_instructions, 'hs_notes', cs.hs_notes) from public.client_sites cs where cs.id = st.site_id)
          when st.zone_id is not null then (select jsonb_build_object('kind', 'zone', 'name', lz.name, 'address', null, 'access_instructions', null, 'hs_notes', null) from public.location_zones lz where lz.id = st.zone_id)
          else jsonb_build_object('kind', 'unknown', 'name', 'Contracted place', 'address', null, 'access_instructions', null, 'hs_notes', null) end
      ) order by st.stop_order, st.visit_number)
      from public.shift_stops st
      where st.shift_id = v_shift.id and st.is_adhoc = false and st.module_key <> 'static_guarding'
    ), '[]'::jsonb)
  );
end;
$function$;
COMMENT ON FUNCTION "public"."get_officer_patrol_stops"(p_shift_id uuid) IS 'Officer-scoped read of the contracted (non-adhoc, non-static) shift stops for one of the caller''s shifts, with place brief, timing window, toolset (modules), instructions, and attendance evidence. Returns null when the caller has no such shift.';
REVOKE ALL ON FUNCTION "public"."get_officer_patrol_stops"(p_shift_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_officer_patrol_stops"(p_shift_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_officer_patrol_stops"(p_shift_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_officer_patrol_stops"(p_shift_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_officer_recovery_readiness"(p_shift_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  with source as materialized (
    select public.get_shift_end_readiness(p_shift_id) as readiness
  )
  select jsonb_build_object(
    'shift_id', source.readiness -> 'shift_id',
    'status', source.readiness -> 'status',
    'scheduled_end', source.readiness -> 'scheduled_end',
    'actual_start', source.readiness -> 'actual_start',
    'open_stops', '[]'::jsonb,
    'open_stop_count', source.readiness -> 'open_stop_count',
    'open_required_task_count', source.readiness -> 'open_required_task_count',
    'open_dispatch_job_count', source.readiness -> 'open_dispatch_job_count',
    'active_welfare_alert_count', source.readiness -> 'active_welfare_alert_count',
    'debrief_submitted', source.readiness -> 'debrief_submitted',
    'blockers', '[]'::jsonb,
    'can_end', source.readiness -> 'can_end',
    'can_end_after_debrief', source.readiness -> 'can_end_after_debrief'
  )
  from source;
$function$;
COMMENT ON FUNCTION "public"."get_officer_recovery_readiness"(p_shift_id uuid) IS 'Count-only shift recovery projection. Delegates authorization to get_shift_end_readiness and withholds stop names and other unreviewed text.';
REVOKE ALL ON FUNCTION "public"."get_officer_recovery_readiness"(p_shift_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_officer_recovery_readiness"(p_shift_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_officer_recovery_readiness"(p_shift_id uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."get_officer_static_post"(p_shift_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid:=auth.uid();
  v_shift public.shifts%rowtype;
  v_stop public.shift_stops%rowtype;
  v_module public.shift_stop_modules%rowtype;
  v_site public.client_sites%rowtype;
  v_zone public.location_zones%rowtype;
  v_arrival_receipt jsonb;
  v_departure_receipt jsonb;
begin
  if v_actor is null then raise exception 'Authentication required';end if;
  select s.* into v_shift from public.shifts s
  where s.officer_user_id=v_actor and s.service_type='static_guarding'
    and s.status in('accepted','in_progress') and (p_shift_id is null or s.id=p_shift_id)
  order by
    case
      when s.status='in_progress' then 0
      when now() between s.scheduled_start and s.scheduled_end then 1
      when s.scheduled_start>now() then 2
      else 3
    end,
    case when s.scheduled_start>now() then s.scheduled_start end,
    s.scheduled_start desc
  limit 1;
  if not found then return null;end if;

  select st.* into v_stop from public.shift_stops st
  where st.shift_id=v_shift.id and st.module_key='static_guarding'
  order by st.stop_order limit 1;
  if not found then raise exception 'Static guarding stop is missing';end if;
  select sm.* into v_module from public.shift_stop_modules sm
  where sm.shift_stop_id=v_stop.id and sm.module_key='static_guarding' and sm.is_required
  order by sm.created_at limit 1;
  if not found then raise exception 'Static guarding module task is missing';end if;
  if not exists(select 1 from public.service_agreement_modules sam join public.service_agreement_locations sal on sal.service_agreement_id=sam.service_agreement_id where sam.id=v_module.service_agreement_module_id and sal.id=v_module.service_agreement_location_id and sam.module_key='static_guarding' and sam.enabled and sal.status='active') then raise exception 'Static guarding contract is no longer active';end if;

  if v_stop.site_id is not null then select cs.* into v_site from public.client_sites cs where cs.id=v_stop.site_id and cs.active;end if;
  if v_stop.zone_id is not null then select z.* into v_zone from public.location_zones z where z.id=v_stop.zone_id;end if;
  select a.receipt into v_arrival_receipt from public.shift_stop_actions a where a.shift_stop_id=v_stop.id and a.action_type='static_post_arrived' order by a.performed_at desc limit 1;
  select a.receipt into v_departure_receipt from public.shift_stop_actions a where a.shift_stop_id=v_stop.id and a.action_type='static_post_departed' order by a.performed_at desc limit 1;

  return jsonb_build_object(
    'shift',jsonb_build_object('id',v_shift.id,'status',v_shift.status,'scheduled_start',v_shift.scheduled_start,'scheduled_end',v_shift.scheduled_end,'notes',v_shift.notes),
    'stop',jsonb_build_object('id',v_stop.id,'status',v_stop.status,'sla_arrive_by',v_stop.sla_arrive_by,'actual_arrived_at',v_stop.actual_arrived_at,'actual_departed_at',v_stop.actual_departed_at,'officer_notes',v_stop.officer_notes),
    'module',jsonb_build_object('id',v_module.id,'status',v_module.status,'started_at',v_module.started_at,'completed_at',v_module.completed_at),
    'place',jsonb_build_object('id',coalesce(v_site.id,v_zone.id),'name',coalesce(v_site.name,v_zone.name),'address',v_site.address,'risk_level',v_site.risk_level,'site_brief',v_site.site_brief,'access_instructions',v_site.access_instructions,'hs_notes',v_site.hs_notes),
    'attendance_evidence',jsonb_build_object('arrival',v_arrival_receipt,'departure',v_departure_receipt)
  );
end;$function$;
REVOKE ALL ON FUNCTION "public"."get_officer_static_post"(p_shift_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_officer_static_post"(p_shift_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_officer_static_post"(p_shift_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_officer_static_post"(p_shift_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_officer_timesheet_work"(p_period_start date, p_period_end date)
 RETURNS TABLE(source_type text, source_id uuid, work_status text, started_at timestamp with time zone, ended_at timestamp with time zone, calculated_minutes integer, label text, metadata jsonb)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
declare
  v_user_id uuid := auth.uid();
  v_org_id uuid;
  v_period_start timestamptz := p_period_start::timestamptz;
  v_period_end timestamptz := (p_period_end + 1)::timestamptz;
begin
  if v_user_id is null then raise exception 'Authentication required'; end if;
  if p_period_start is null or p_period_end is null or p_period_start > p_period_end then raise exception 'Invalid timesheet period'; end if;
  select p.organization_id into v_org_id from public.user_profiles p where p.id = v_user_id and p.deactivated_at is null;
  if v_org_id is null then raise exception 'Active staff profile required'; end if;

  return query
  with shift_window as (
    -- The officer's own completed shifts, whichever branch rostered them, clipped to the period.
    select s.*, greatest(s.actual_start, v_period_start) as w_start, least(s.actual_end, v_period_end) as w_end
    from public.shifts s
    where s.officer_user_id = v_user_id
      and s.status = 'completed' and s.actual_start is not null and s.actual_end is not null
      and s.actual_end > v_period_start and s.actual_start < v_period_end
  ), breaks_taken as (
    select b.shift_id,
      coalesce(sum(case when not b.is_paid then greatest(0, extract(epoch from (least(b.ended_at, w.w_end) - greatest(b.started_at, w.w_start))) / 60) end), 0)::integer as unpaid_minutes,
      coalesce(sum(case when b.is_paid then greatest(0, extract(epoch from (least(b.ended_at, w.w_end) - greatest(b.started_at, w.w_start))) / 60) end), 0)::integer as paid_minutes
    from public.shift_breaks b
    join shift_window w on w.id = b.shift_id
    where b.ended_at is not null
    group by b.shift_id
  ), shift_work(source_type, id, work_status, started_at, ended_at, deduct_minutes, label, metadata) as (
    select 'shift'::text, w.id, 'completed'::text, w.w_start, w.w_end, coalesce(bt.unpaid_minutes, 0),
      coalesce(w.service_type, 'shift'),
      jsonb_build_object('shift_id', w.id, 'organization_id', w.organization_id, 'service_type', w.service_type, 'status', w.status, 'ended_reason', w.ended_reason,
        'scheduled_start', w.scheduled_start, 'scheduled_end', w.scheduled_end, 'actual_start', w.actual_start, 'actual_end', w.actual_end,
        'unpaid_break_minutes', coalesce(bt.unpaid_minutes, 0), 'paid_break_minutes', coalesce(bt.paid_minutes, 0))
    from shift_window w
    left join breaks_taken bt on bt.shift_id = w.id
  ), job_work(source_type, id, work_status, started_at, ended_at, deduct_minutes, label, metadata) as (
    -- Standalone dispatch jobs the officer worked (no shift), whichever branch raised them.
    select 'dispatch_job'::text, d.id, 'completed'::text,
      greatest(coalesce(d.on_scene_at, d.en_route_at, d.acknowledged_at, d.dispatched_at, d.created_at), v_period_start),
      least(d.completed_at, v_period_end), 0, coalesce(d.job_type, 'Dispatch job'),
      jsonb_build_object('dispatch_job_id', d.id, 'organization_id', d.organization_id, 'job_type', d.job_type, 'status', d.status, 'shift_id', d.shift_id, 'shift_stop_id', d.shift_stop_id, 'dispatched_at', d.dispatched_at, 'on_scene_at', d.on_scene_at, 'completed_at', d.completed_at)
    from public.dispatch_jobs d
    where d.dispatch_resource_id in (select dr.id from public.dispatch_resources dr where dr.assigned_officer_id = v_user_id)
      and d.status = 'completed' and d.completed_at is not null and d.shift_id is null
      and d.completed_at > v_period_start
      and coalesce(d.on_scene_at, d.en_route_at, d.acknowledged_at, d.dispatched_at, d.created_at) < v_period_end
  ), sources as (
    select * from shift_work union all select * from job_work
  ), bounded as (
    select *, greatest(0, floor(extract(epoch from (ended_at - started_at)) / 60) - deduct_minutes)::integer as minutes
    from sources where ended_at > started_at
  )
  select source_type, id, work_status, started_at, ended_at, minutes, label,
    metadata || jsonb_build_object('calculated_minutes', minutes)
  from bounded order by started_at, source_type, id;
end;
$function$;
COMMENT ON FUNCTION "public"."get_officer_timesheet_work"(p_period_start date, p_period_end date) IS 'The officer''s completed work in a period, from shift actual_start/actual_end (any branch) and completed standalone dispatch jobs. Unpaid ended breaks are deducted; metadata carries organization_id and break minutes.';
REVOKE ALL ON FUNCTION "public"."get_officer_timesheet_work"(p_period_start date, p_period_end date) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_officer_timesheet_work"(p_period_start date, p_period_end date) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_officer_timesheet_work"(p_period_start date, p_period_end date) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_officer_timesheet_work"(p_period_start date, p_period_end date) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_operating_branch_roster_staff"(p_operating_organization_id uuid)
 RETURNS TABLE(user_id uuid, staff_id uuid, display_name text, email text, employment_type text, work_ready boolean, credential_expiry date, credential_verified boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
BEGIN
  IF v_actor IS NULL OR NOT public.user_can_operate_organization(p_operating_organization_id) THEN
    RAISE EXCEPTION 'Active authorized operating branch required';
  END IF;
  IF NOT public.is_admin_for_org(p_operating_organization_id)
     AND NOT EXISTS(
       SELECT 1 FROM public.staff_branch_authorisations manager_assignment
       WHERE manager_assignment.user_id = v_actor
         AND manager_assignment.branch_org_id = p_operating_organization_id
         AND manager_assignment.status = 'active'
         AND manager_assignment.role_at_branch = 'branch_manager'
     )
     AND NOT EXISTS(
       SELECT 1 FROM public.resolve_access_grants(v_actor,p_operating_organization_id) authority_grant
       WHERE authority_grant.area = 'roster_impact_approve'
         AND authority_grant.level IN ('approve','adjust','manage')
     ) THEN
    RAISE EXCEPTION 'Branch roster authority required';
  END IF;

  RETURN QUERY
  SELECT user_profile.id,staff.id,user_profile.display_name,user_profile.email,staff.employment_type,staff.work_ready,min(credential.expiry_date),bool_and(credential.verified)
  FROM public.staff_branch_authorisations assignment
  JOIN public.user_profiles user_profile ON user_profile.id=assignment.user_id AND user_profile.deactivated_at IS NULL
  JOIN public.staff_profiles staff ON staff.id=coalesce(user_profile.id,staff.user_id) OR staff.user_id=user_profile.id
  LEFT JOIN public.staff_credentials credential
    ON credential.staff_id=staff.id
   AND NOT EXISTS (
     SELECT 1 FROM public.staff_credentials replacement
     WHERE replacement.replaces_credential_id=credential.id
   )
   AND NOT public.staff_credential_has_verified_match(credential.id)
  WHERE assignment.branch_org_id=p_operating_organization_id
    AND assignment.status='active'
    AND assignment.can_be_rostered
    AND (assignment.ends_on IS NULL OR assignment.ends_on>=current_date)
    AND (assignment.starts_on IS NULL OR assignment.starts_on<=current_date)
  GROUP BY user_profile.id,staff.id,user_profile.display_name,user_profile.email,staff.employment_type,staff.work_ready

  UNION

  -- A standalone organisation's own staff (no branch structure required): the
  -- person's home organization_id IS the org being rostered, and they are not
  -- already returned above via an explicit branch grant.
  SELECT user_profile.id,staff.id,user_profile.display_name,user_profile.email,staff.employment_type,staff.work_ready,min(credential.expiry_date),bool_and(credential.verified)
  FROM public.user_profiles user_profile
  JOIN public.staff_profiles staff ON staff.id=coalesce(user_profile.id,staff.user_id) OR staff.user_id=user_profile.id
  LEFT JOIN public.staff_credentials credential
    ON credential.staff_id=staff.id
   AND NOT EXISTS (
     SELECT 1 FROM public.staff_credentials replacement
     WHERE replacement.replaces_credential_id=credential.id
   )
   AND NOT public.staff_credential_has_verified_match(credential.id)
  WHERE user_profile.organization_id=p_operating_organization_id
    AND user_profile.deactivated_at IS NULL
    AND NOT EXISTS (
      SELECT 1 FROM public.staff_branch_authorisations existing
      WHERE existing.user_id=user_profile.id
        AND existing.branch_org_id=p_operating_organization_id
        AND existing.status='active'
        AND existing.can_be_rostered
        AND (existing.ends_on IS NULL OR existing.ends_on>=current_date)
        AND (existing.starts_on IS NULL OR existing.starts_on<=current_date)
    )
  GROUP BY user_profile.id,staff.id,user_profile.display_name,user_profile.email,staff.employment_type,staff.work_ready

  ORDER BY 3 NULLS LAST,4;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."get_operating_branch_roster_staff"(p_operating_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_operating_branch_roster_staff"(p_operating_organization_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_operating_branch_roster_staff"(p_operating_organization_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_operating_branch_roster_staff"(p_operating_organization_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_operating_organization_contexts"()
 RETURNS TABLE(organization_id uuid, organization_name text, authority_basis text, role_at_branch text, module_access text[], can_be_rostered boolean, is_default boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with actor as (
    select organization_id, employer_organization_id, role
    from public.user_profiles
    where id = auth.uid() and deactivated_at is null
  ), candidates as (
    -- The provider organisation itself, for its administrators.
    select
      home.id as organization_id,
      home.name as organization_name,
      'organisation_home'::text as authority_basis,
      null::text as role_at_branch,
      array[]::text[] as module_access,
      false as can_be_rostered,
      0 as authority_rank
    from actor
    join public.organizations home
      on home.id = actor.organization_id
     and home.organization_type in ('owner', 'service_provider')
     and home.active
    where actor.role in ('grand_master', 'master', 'admin', 'admin_officer')

    union all

    select
      branch.id as organization_id,
      branch.name as organization_name,
      'branch_authorisation'::text as authority_basis,
      authorisation.role_at_branch,
      authorisation.module_access,
      authorisation.can_be_rostered,
      1 as authority_rank
    from actor
    join public.staff_branch_authorisations authorisation
      on authorisation.user_id = auth.uid() and authorisation.status = 'active'
    join public.organizations branch
      on branch.id = authorisation.branch_org_id
     and branch.organization_type = 'branch'
     and branch.active

    union all

    select
      branch.id,
      branch.name,
      'corporate_oversight'::text,
      null::text,
      array[]::text[],
      false,
      2
    from actor
    join public.organizations branch
      on branch.organization_type = 'branch'
     and branch.active
     and branch.id = any(public.get_descendant_organizations(coalesce(actor.employer_organization_id, actor.organization_id)))
    where actor.role in ('grand_master', 'master', 'admin', 'admin_officer')
  ), ranked as (
    select distinct on (organization_id)
      organization_id, organization_name, authority_basis, role_at_branch,
      module_access, can_be_rostered
    from candidates
    order by organization_id, authority_rank
  )
  select
    ranked.organization_id,
    ranked.organization_name,
    ranked.authority_basis,
    ranked.role_at_branch,
    ranked.module_access,
    ranked.can_be_rostered,
    ranked.organization_id = actor.organization_id as is_default
  from ranked
  cross join actor
  order by (ranked.organization_id = actor.organization_id) desc, ranked.organization_name;
$function$;
COMMENT ON FUNCTION "public"."get_operating_organization_contexts"() IS 'Operating contexts for the caller: their own provider organisation (organisation_home, for grand_master/master/admin), branches they are authorised at (branch_authorisation), and branches in their organisation tree (corporate_oversight). Ranked so an explicit authorisation wins over oversight; the home organisation is the default.';
REVOKE ALL ON FUNCTION "public"."get_operating_organization_contexts"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_operating_organization_contexts"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_operating_organization_contexts"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_operating_organization_contexts"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_org_geofence_config"(p_org_id uuid, p_config_key text, p_zone_type text DEFAULT NULL::text, p_default integer DEFAULT NULL::integer)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
  SELECT COALESCE(
    -- Try zone-type-specific override first
    (SELECT config_value FROM public.org_geofence_config
     WHERE organization_id = p_org_id
       AND config_key = p_config_key
       AND zone_type = p_zone_type
     LIMIT 1),
    -- Then org-wide (zone_type IS NULL)
    (SELECT config_value FROM public.org_geofence_config
     WHERE organization_id = p_org_id
       AND config_key = p_config_key
       AND zone_type IS NULL
     LIMIT 1),
    -- Platform default
    p_default
  );
$function$;
COMMENT ON FUNCTION "public"."get_org_geofence_config"(p_org_id uuid, p_config_key text, p_zone_type text, p_default integer) IS 'Reads an org geofence config value with zone-type-specific override -> org-wide -> platform default fallback. Platform defaults: site_provisional_radius_m=50, zone_provisional_radius_m=100, checkpoint_radius_m=5.';
REVOKE ALL ON FUNCTION "public"."get_org_geofence_config"(p_org_id uuid, p_config_key text, p_zone_type text, p_default integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_org_geofence_config"(p_org_id uuid, p_config_key text, p_zone_type text, p_default integer) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."get_org_geofence_config"(p_org_id uuid, p_config_key text, p_zone_type text, p_default integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_org_geofence_config"(p_org_id uuid, p_config_key text, p_zone_type text, p_default integer) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."get_org_geofence_config"(p_org_id uuid, p_config_key text, p_zone_type text, p_default integer) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_org_geofence_config"(p_org_id uuid, p_config_key text, p_zone_type text, p_default integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_orgs_by_jurisdiction_point"(p_lng double precision, p_lat double precision, p_module_key text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, name text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
  WITH pt AS (
    SELECT ST_SetSRID(ST_Point(p_lng, p_lat), 4326) AS geom
  ),
  -- All orgs whose VERIFIED jurisdiction contains the point
  containing_orgs AS (
    SELECT o.id, o.name
    FROM public.organizations o, pt
    WHERE o.jurisdiction_geom IS NOT NULL
      AND o.jurisdiction_verification = 'verified'
      AND ST_Contains(o.jurisdiction_geom, pt.geom)
  ),
  -- Sites whose boundary contains the point (for ownership + agreement lookups)
  containing_sites AS (
    SELECT cs.id AS site_id, cs.client_organization_id
    FROM public.client_sites cs, pt
    WHERE cs.boundary IS NOT NULL
      AND cs.boundary_verification = 'verified'
      AND ST_IsValid(cs.boundary)
      AND NOT ST_IsEmpty(cs.boundary)
      AND ST_Contains(cs.boundary, pt.geom)
  ),
  -- Zones whose boundary contains the point (for agreement lookups)
  containing_zones AS (
    SELECT lz.id AS zone_id, lz.organization_id
    FROM public.location_zones lz, pt
    WHERE lz.boundary IS NOT NULL
      AND lz.boundary_verification = 'verified'
      AND ST_IsValid(lz.boundary)
      AND NOT ST_IsEmpty(lz.boundary)
      AND ST_Contains(lz.boundary, pt.geom)
  ),
  -- (a) Agreement-based standing: org has an active service_agreement
  --     covering the module at a site/zone containing the point.
  agreement_standing AS (
    SELECT DISTINCT sa.client_organization_id AS org_id
    FROM public.service_agreements sa
    JOIN public.service_agreement_locations sal
      ON sal.service_agreement_id = sa.id
      AND sal.status = 'active'
    LEFT JOIN public.service_agreement_modules sam
      ON sam.service_agreement_id = sa.id
      AND sam.enabled = true
    WHERE (sa.ends_on IS NULL OR sa.ends_on >= current_date)
      AND (
        -- Location match: site or zone containing the point
        (sal.site_id IS NOT NULL AND sal.site_id IN (SELECT site_id FROM containing_sites))
        OR
        (sal.zone_id IS NOT NULL AND sal.zone_id IN (SELECT zone_id FROM containing_zones))
      )
      AND (
        -- Module match: when p_module_key provided, require module enabled
        p_module_key IS NULL
        OR sam.module_key = p_module_key
      )
  ),
  -- (b) Self-request standing: org OWNS the site AND module is enabled
  --     at the site via site_services.
  ownership_standing AS (
    SELECT DISTINCT cs.client_organization_id AS org_id
    FROM containing_sites cs
    WHERE (
      p_module_key IS NULL
      OR EXISTS (
        SELECT 1 FROM public.site_services ss
        WHERE ss.site_id = cs.site_id
          AND ss.organization_id = cs.client_organization_id
          AND ss.module_key = p_module_key
          AND ss.enabled = true
      )
    )
  ),
  -- Union of all orgs with standing
  standing_orgs AS (
    SELECT org_id FROM agreement_standing
    UNION
    SELECT org_id FROM ownership_standing
  )
  SELECT co.id, co.name
  FROM containing_orgs co
  WHERE (
    -- When module_key is provided, only return orgs with standing
    p_module_key IS NULL
    OR co.id IN (SELECT org_id FROM standing_orgs)
  )
  ORDER BY
    -- Standing-bearing orgs sort first even when p_module_key is NULL
    (CASE WHEN co.id IN (SELECT org_id FROM standing_orgs) THEN 0 ELSE 1 END),
    co.name;
$function$;
COMMENT ON FUNCTION "public"."get_orgs_by_jurisdiction_point"(p_lng double precision, p_lat double precision, p_module_key text) IS 'Role-aware requester picklist (0290). Returns orgs whose verified jurisdiction contains the point. When p_module_key is provided, filters to orgs with requester standing for that module (active agreement or site ownership + site_services). When omitted, backward-compatible but standing-bearing orgs sort first. Replaces geometry-only 0286.';
REVOKE ALL ON FUNCTION "public"."get_orgs_by_jurisdiction_point"(p_lng double precision, p_lat double precision, p_module_key text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_orgs_by_jurisdiction_point"(p_lng double precision, p_lat double precision, p_module_key text) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."get_orgs_by_jurisdiction_point"(p_lng double precision, p_lat double precision, p_module_key text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_orgs_by_jurisdiction_point"(p_lng double precision, p_lat double precision, p_module_key text) TO "anon";
