CREATE OR REPLACE FUNCTION "public"."get_payroll_setup_readiness"(p_operating_organization_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_payroll_organization_id uuid;
  v_result jsonb;
BEGIN
  SELECT profile.organization_id
  INTO v_payroll_organization_id
  FROM public.user_profiles profile
  WHERE profile.id = v_actor
    AND profile.deactivated_at IS NULL
    AND profile.role IN ('grand_master', 'master', 'admin', 'admin_officer');

  IF v_payroll_organization_id IS NULL
    OR NOT public.user_can_operate_organization(p_operating_organization_id)
    OR NOT public.is_admin_for_org(p_operating_organization_id) THEN
    RAISE EXCEPTION 'Active authorized payroll administrator required';
  END IF;

  SELECT jsonb_build_object(
    'payroll_organization_id', v_payroll_organization_id,
    'operating_organization_id', p_operating_organization_id,
    'active_pay_code_count', (
      SELECT count(*)
      FROM public.reference_codes code
      WHERE code.organization_id = v_payroll_organization_id
        AND code.code_type = 'pay_item'
        AND code.is_active
    ),
    'unassigned_staff_count', (
      SELECT count(*)
      FROM public.staff_profiles staff
      WHERE staff.organization_id = v_payroll_organization_id
        AND staff.end_date IS NULL
        AND staff.role_code IS NULL
    ),
    'rules_without_active_pay_code', (
      SELECT count(*)
      FROM public.rate_rules rule
      WHERE rule.organization_id = p_operating_organization_id
        AND rule.rule_kind = 'pay'
        AND rule.active
        AND NOT EXISTS (
          SELECT 1
          FROM public.reference_codes code
          WHERE code.organization_id = v_payroll_organization_id
            AND code.code_type = 'pay_item'
            AND code.code = rule.pay_code
            AND code.is_active
        )
    ),
    'roles', coalesce((
      SELECT jsonb_agg(
        jsonb_build_object(
          'code', role.code,
          'name', role.name,
          'staff_count', (
            SELECT count(*)
            FROM public.staff_profiles staff
            WHERE staff.organization_id = v_payroll_organization_id
              AND staff.end_date IS NULL
              AND staff.role_code = role.code
          ),
          'specific_rule_count', (
            SELECT count(*)
            FROM public.rate_rules rule
            WHERE rule.organization_id = p_operating_organization_id
              AND rule.rule_kind = 'pay'
              AND rule.active
              AND rule.role_code = role.code
          ),
          'fallback_rule_count', (
            SELECT count(*)
            FROM public.rate_rules rule
            WHERE rule.organization_id = p_operating_organization_id
              AND rule.rule_kind = 'pay'
              AND rule.active
              AND rule.role_code IS NULL
          ),
          'status', CASE
            WHEN EXISTS (
              SELECT 1 FROM public.rate_rules rule
              WHERE rule.organization_id = p_operating_organization_id
                AND rule.rule_kind = 'pay'
                AND rule.active
                AND rule.role_code = role.code
            ) THEN 'ready'
            WHEN EXISTS (
              SELECT 1 FROM public.rate_rules rule
              WHERE rule.organization_id = p_operating_organization_id
                AND rule.rule_kind = 'pay'
                AND rule.active
                AND rule.role_code IS NULL
            ) THEN 'fallback'
            ELSE 'missing_rule'
          END
        )
        ORDER BY role.sort_order, role.code
      )
      FROM public.reference_codes role
      WHERE role.organization_id = v_payroll_organization_id
        AND role.code_type = 'role_code'
        AND role.is_active
    ), '[]'::jsonb)
  )
  INTO v_result;

  RETURN v_result;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."get_payroll_setup_readiness"(p_operating_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_payroll_setup_readiness"(p_operating_organization_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_payroll_setup_readiness"(p_operating_organization_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_payroll_setup_readiness"(p_operating_organization_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_pending_person_detail_updates"(p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_limit integer := least(greatest(coalesce(p_limit, 50), 1), 200);
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in to review person details' USING ERRCODE = '42501'; END IF;
  -- Only administrators of the interaction's organisation see pending details, oldest first.
  RETURN coalesce((
    SELECT jsonb_agg(row_to_json(queue) ORDER BY queue.interacted_at)
    FROM (
      SELECT pi.id AS interaction_id, pi.organization_id, org.name AS organization_name, pi.person_record_id,
        pi.person_id AS canonical_person_id, pr.display_name AS person_name, pi.proposed_details,
        jsonb_strip_nulls(jsonb_build_object(
          'date_of_birth', pr.metadata->'profile_details'->>'date_of_birth',
          'phone', pr.metadata->'profile_details'->>'phone',
          'address', pr.metadata->'profile_details'->>'address')) AS current_details,
        pi.interaction_type, pi.interacted_at, pi.source, officer.display_name AS officer_name,
        coalesce(cs.name, z.name) AS place_name
      FROM public.person_interactions pi
      JOIN public.organizations org ON org.id = pi.organization_id
      JOIN public.person_records pr ON pr.id = pi.person_record_id
      LEFT JOIN public.client_sites cs ON cs.id = pi.client_site_id
      LEFT JOIN public.location_zones z ON z.id = pi.zone_id
      LEFT JOIN public.user_profiles officer ON officer.id = pi.officer_user_id
      WHERE pi.proposal_status = 'pending' AND public.is_admin_for_org(pi.organization_id) IS TRUE
      ORDER BY pi.interacted_at
      LIMIT v_limit
    ) queue
  ), '[]'::jsonb);
END;
$function$;
COMMENT ON FUNCTION "public"."get_pending_person_detail_updates"(p_limit integer) IS 'Pending field-supplied person details awaiting administrator review, limited to organisations the caller administers.';
REVOKE ALL ON FUNCTION "public"."get_pending_person_detail_updates"(p_limit integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_pending_person_detail_updates"(p_limit integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_pending_person_detail_updates"(p_limit integer) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_pending_person_detail_updates"(p_limit integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_person_face_matches"(p_person_record_id uuid, p_limit integer DEFAULT 10)
 RETURNS TABLE(person_record_id uuid, display_name text, review_state text, score real, sighting_count bigint, last_seen_at timestamp with time zone, thumbnail text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_person public.person_records%rowtype;
BEGIN
  SELECT * INTO v_person FROM public.person_records WHERE id = p_person_record_id;
  IF auth.uid() IS NULL OR v_person.id IS NULL OR NOT public.is_admin_for_org(v_person.organization_id) THEN RETURN; END IF;
  RETURN QUERY
  WITH mine AS (
    SELECT t.face_vec FROM public.person_face_templates t WHERE t.person_record_id = v_person.id
    UNION ALL
    SELECT c.face_vec FROM public.cctv_entity_observations c WHERE c.person_record_id = v_person.id AND c.face_vec IS NOT NULL
  ), theirs AS (
    SELECT c.person_record_id AS pid, c.face_vec, c.observed_at, c.thumbnail FROM public.cctv_entity_observations c
    WHERE c.organization_id = v_person.organization_id AND c.entity_kind = 'person' AND c.face_vec IS NOT NULL
      AND c.person_record_id IS NOT NULL AND c.person_record_id <> v_person.id
    UNION ALL
    SELECT t.person_record_id, t.face_vec, t.approved_at, NULL FROM public.person_face_templates t
    WHERE t.organization_id = v_person.organization_id AND t.person_record_id <> v_person.id
  ), scored AS (
    SELECT th.pid, max((1 - (th.face_vec OPERATOR(public.<=>) m.face_vec))::real) AS score,
      max(th.observed_at) AS seen, (array_agg(th.thumbnail ORDER BY th.observed_at DESC) FILTER (WHERE th.thumbnail IS NOT NULL))[1] AS thumb
    FROM theirs th CROSS JOIN mine m GROUP BY th.pid
  )
  SELECT p.id, p.display_name, p.review_state, s.score,
    (SELECT count(*) FROM public.cctv_entity_observations c WHERE c.person_record_id = p.id), s.seen, s.thumb
  FROM scored s JOIN public.person_records p ON p.id = s.pid
  WHERE s.score >= 0.65 AND NOT (p.metadata ? 'merged_into_person_record_id') AND NOT (p.metadata ? 'resolved_into_person_record_id')
  ORDER BY s.score DESC LIMIT least(greatest(coalesce(p_limit, 10), 1), 25);
END;
$function$;
COMMENT ON FUNCTION "public"."get_person_face_matches"(p_person_record_id uuid, p_limit integer) IS 'Other profiles (for example CCTV "Unknown Person #N") whose faces resemble this person, at the 0.65 face threshold used by find_cctv_portfolio_matches. Administrators only; a suggestion for human review, never an identification.';
REVOKE ALL ON FUNCTION "public"."get_person_face_matches"(p_person_record_id uuid, p_limit integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_person_face_matches"(p_person_record_id uuid, p_limit integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_person_face_matches"(p_person_record_id uuid, p_limit integer) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."get_person_identity_summary"(p_person_record_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_person public.person_records%rowtype;
  v_admin boolean;
BEGIN
  SELECT * INTO v_person FROM public.person_records WHERE id = p_person_record_id;
  IF auth.uid() IS NULL OR v_person.id IS NULL OR NOT public.org_access_allowed(v_person.organization_id) THEN RETURN NULL; END IF;
  v_admin := public.is_admin_for_org(v_person.organization_id);
  RETURN jsonb_build_object(
    'person_record_id', v_person.id,
    'organization_id', v_person.organization_id,
    'display_name', v_person.display_name,
    'review_state', v_person.review_state,
    'verified', v_person.review_state = 'verified',
    'verified_at', v_person.metadata->>'identity_verified_at',
    'origin', coalesce(v_person.metadata->>'origin', v_person.metadata->>'created_from'),
    'merged_into_person_record_id', coalesce(v_person.metadata->>'merged_into_person_record_id', v_person.metadata->>'resolved_into_person_record_id'),
    'pending_documents', (SELECT count(*) FROM public.person_identity_documents d WHERE d.person_record_id = v_person.id AND d.review_state = 'manual_review_required'),
    'approved_documents', (SELECT count(*) FROM public.person_identity_documents d WHERE d.person_record_id = v_person.id AND d.review_state = 'approved'),
    'has_face_reference', EXISTS (SELECT 1 FROM public.person_face_templates t WHERE t.person_record_id = v_person.id)
      OR EXISTS (SELECT 1 FROM public.cctv_entity_observations c WHERE c.person_record_id = v_person.id AND c.face_vec IS NOT NULL),
    'sighting_count', (SELECT count(*) FROM public.cctv_entity_observations c WHERE c.person_record_id = v_person.id)
      + (SELECT count(*) FROM public.observations o WHERE o.person_record_id = v_person.id)
      + (SELECT count(*) FROM public.observation_person_mentions m WHERE m.person_record_id = v_person.id AND m.status <> 'dismissed'),
    'aliases', coalesce((SELECT jsonb_agg(jsonb_build_object('id', a.id, 'alias', a.alias, 'alias_kind', a.alias_kind, 'source', a.source,
        'can_remove', a.created_by = auth.uid() OR v_admin) ORDER BY a.created_at)
      FROM public.person_record_aliases a WHERE a.person_record_id = v_person.id AND a.active), '[]'::jsonb),
    'can_review', v_admin,
    'can_merge', v_admin);
END;
$function$;
REVOKE ALL ON FUNCTION "public"."get_person_identity_summary"(p_person_record_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_person_identity_summary"(p_person_record_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_person_identity_summary"(p_person_record_id uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."get_person_interactions"(p_canonical_person_id uuid, p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_limit integer := least(greatest(coalesce(p_limit, 50), 1), 200);
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in to read person history' USING ERRCODE = '42501'; END IF;
  IF p_canonical_person_id IS NULL THEN RAISE EXCEPTION 'Choose a person'; END IF;

  -- Each organisation's history is shown only to its administrators and person-search users.
  RETURN coalesce((
    SELECT jsonb_agg(row_to_json(history) ORDER BY history.interacted_at DESC)
    FROM (
      SELECT pi.id, pi.organization_id, org.name AS organization_name, pi.interaction_type, pi.notes, pi.interacted_at,
        pi.source, pi.dispatch_job_id, pi.shift_id, dj.job_type, coalesce(cs.name, z.name) AS place_name,
        officer.display_name AS officer_name, pi.proposal_status,
        CASE WHEN public.is_admin_for_org(pi.organization_id) IS TRUE THEN pi.proposed_details END AS proposed_details
      FROM public.person_interactions pi
      JOIN public.organizations org ON org.id = pi.organization_id
      LEFT JOIN public.dispatch_jobs dj ON dj.id = pi.dispatch_job_id
      LEFT JOIN public.client_sites cs ON cs.id = pi.client_site_id
      LEFT JOIN public.location_zones z ON z.id = pi.zone_id
      LEFT JOIN public.user_profiles officer ON officer.id = pi.officer_user_id
      WHERE pi.person_id = p_canonical_person_id
        AND (public.is_admin_for_org(pi.organization_id) OR public.can_search_people(pi.organization_id))
      ORDER BY pi.interacted_at DESC
      LIMIT v_limit
    ) history
  ), '[]'::jsonb);
END;
$function$;
COMMENT ON FUNCTION "public"."get_person_interactions"(p_canonical_person_id uuid, p_limit integer) IS 'Interaction history for one canonical person, limited to organisations where the caller is an administrator or person-search user.';
REVOKE ALL ON FUNCTION "public"."get_person_interactions"(p_canonical_person_id uuid, p_limit integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_person_interactions"(p_canonical_person_id uuid, p_limit integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_person_interactions"(p_canonical_person_id uuid, p_limit integer) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_person_interactions"(p_canonical_person_id uuid, p_limit integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_person_interest_summary"(p_person_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF NOT public.can_search_people() THEN RAISE EXCEPTION 'Person-search authorization required'; END IF;
  RETURN coalesce((
    SELECT jsonb_agg(jsonb_build_object('alert_level', f.alert_level, 'organization_name', o.name) ORDER BY f.raised_at DESC)
    FROM public.entity_flags f JOIN public.organizations o ON o.id = f.organization_id
    JOIN public.canonical_people cp ON cp.id = f.entity_id AND cp.status = 'active'
    WHERE f.entity_id = p_person_id AND f.entity_type = 'person' AND f.flag_type = 'poi'
      AND f.hazard_class IS NULL AND f.active AND public.can_search_people(f.organization_id)
  ), '[]'::jsonb);
END;
$function$;
REVOKE ALL ON FUNCTION "public"."get_person_interest_summary"(p_person_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_person_interest_summary"(p_person_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_person_interest_summary"(p_person_id uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."get_person_record_operations"(p_organization_id uuid, p_person_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF NOT public.person_record_admin_allowed(p_organization_id, p_person_id) THEN
    RAISE EXCEPTION 'Person record not found or administrator access denied';
  END IF;
  RETURN jsonb_build_object(
    'verified', EXISTS (
      SELECT 1 FROM public.canonical_people cp
      JOIN public.canonical_person_links link ON link.canonical_person_id = cp.id
      JOIN public.person_records pr ON pr.id = link.source_id AND pr.organization_id = link.organization_id
      WHERE cp.id = p_person_id AND cp.review_state = 'verified' AND pr.review_state = 'verified'
        AND link.organization_id = p_organization_id AND link.source_table = 'person_records'),
    'housing', (SELECT jsonb_build_object('status', cp.homeless_status, 'notes', cp.homeless_notes,
      'verified_at', cp.homeless_verified_at, 'version', cp.updated_at) FROM public.canonical_people cp WHERE cp.id = p_person_id),
    'housing_states', (SELECT jsonb_agg(to_jsonb(s) ORDER BY s.code) FROM public.person_housing_status_definitions s),
    'document_types', (SELECT jsonb_agg(to_jsonb(t) ORDER BY t.code) FROM public.person_record_document_types t),
    'flags', coalesce((SELECT jsonb_agg(jsonb_build_object('id', f.id, 'alert_level', f.alert_level,
      'reason', f.reason, 'raised_at', f.raised_at) ORDER BY f.raised_at DESC)
      FROM public.entity_flags f WHERE f.organization_id = p_organization_id AND f.entity_type = 'person'
        AND f.entity_id = p_person_id AND f.flag_type = 'poi' AND f.hazard_class IS NULL AND f.active), '[]'::jsonb),
    'documents', coalesce((SELECT jsonb_agg(to_jsonb(d) - 'request_payload' ORDER BY d.created_at DESC)
      FROM (SELECT * FROM public.person_record_documents d WHERE d.organization_id = p_organization_id
        AND d.canonical_person_id = p_person_id ORDER BY d.created_at DESC LIMIT 100) d), '[]'::jsonb),
    'document_total', (SELECT count(*) FROM public.person_record_documents d
      WHERE d.organization_id = p_organization_id AND d.canonical_person_id = p_person_id),
    'clients', coalesce((SELECT jsonb_agg(jsonb_build_object('id', o.id, 'name', o.name) ORDER BY o.name)
      FROM public.organizations o WHERE public.org_access_allowed(o.id) AND EXISTS (
        SELECT 1 FROM public.service_agreements a WHERE a.client_organization_id = o.id
          AND a.provider_organization_id = p_organization_id AND a.agreement_type = 'operational'
          AND (a.starts_on IS NULL OR a.starts_on <= current_date) AND (a.ends_on IS NULL OR a.ends_on >= current_date))), '[]'::jsonb)
  );
END;
$function$;
REVOKE ALL ON FUNCTION "public"."get_person_record_operations"(p_organization_id uuid, p_person_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_person_record_operations"(p_organization_id uuid, p_person_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_person_record_operations"(p_organization_id uuid, p_person_id uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."get_person_search_access"(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_target public.user_profiles%rowtype;
BEGIN
  SELECT * INTO v_target FROM public.user_profiles WHERE id = p_user_id;
  IF v_target.id IS NULL OR auth.uid() IS NULL
     OR NOT public.is_admin_for_org(v_target.organization_id) THEN
    RAISE EXCEPTION 'Organisation administrator required' USING ERRCODE = '42501';
  END IF;
  RETURN jsonb_build_object(
    'direct', EXISTS (
      SELECT 1 FROM public.staff_area_grants g
      WHERE g.user_id = p_user_id AND g.scope_org_id = v_target.organization_id
        AND g.area = 'person_search' AND g.status = 'active'
    ),
    'via_grant', EXISTS (
      SELECT 1 FROM public.staff_area_grants g
      WHERE g.user_id = p_user_id AND g.scope_org_id <> v_target.organization_id
        AND g.area = 'person_search' AND g.status = 'active'
        AND v_target.organization_id = ANY(public.get_descendant_organizations(g.scope_org_id))
    ),
    'via_preset', EXISTS (
      SELECT 1 FROM public.preset_assignments a
      JOIN public.access_presets p ON p.id = a.preset_id
      WHERE a.user_id = p_user_id AND a.status = 'active'
        AND p.grants->>'person_search' IN ('view', 'verify', 'approve', 'adjust', 'manage')
        AND v_target.organization_id = ANY(public.get_descendant_organizations(a.scope_org_id))
    ),
    'via_role', v_target.role IN ('grand_master', 'master', 'admin', 'admin_officer'),
    'active', v_target.deactivated_at IS NULL,
    'organization_id', v_target.organization_id
  );
END;
$function$;
REVOKE ALL ON FUNCTION "public"."get_person_search_access"(p_user_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_person_search_access"(p_user_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_person_search_access"(p_user_id uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."get_place_hazard_register"(p_location_id uuid, p_include_retired boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  RETURN coalesce((
    SELECT jsonb_agg(jsonb_build_object(
      'id', h.id, 'organization_id', h.organization_id, 'organization_name', o.name,
      'location_id', h.location_id, 'client_site_id', h.client_site_id, 'zone_id', h.zone_id,
      'place_name', coalesce(cs.name, z.name, l.name),
      'title', h.title, 'hazard_class', h.hazard_class, 'risk_level', h.risk_level,
      'likelihood', h.likelihood, 'consequence', h.consequence, 'controls', to_jsonb(h.controls), 'details', h.details,
      'source_document_id', h.source_document_id, 'source_document_name', d.original_filename,
      'source_name', h.source_name, 'source_locator', h.source_locator, 'source_as_of', h.source_as_of,
      'origin', h.origin, 'status', h.status, 'version', h.version, 'review_due', h.review_due,
      'reported_by_name', rp.display_name, 'reported_shift_id', h.reported_shift_id,
      'reviewed_at', h.reviewed_at, 'retired_at', h.retired_at, 'retired_reason', h.retired_reason,
      'created_at', h.created_at, 'updated_at', h.updated_at,
      'can_manage', public.can_manage_place_hazards(h.organization_id, h.location_id)
    ) ORDER BY CASE h.status WHEN 'reported' THEN 0 WHEN 'active' THEN 1 ELSE 2 END,
               CASE h.risk_level WHEN 'critical' THEN 0 WHEN 'high' THEN 1 WHEN 'medium' THEN 2 ELSE 3 END, h.title)
    FROM public.place_hazards h
    JOIN public.locations l ON l.id = h.location_id
    JOIN public.organizations o ON o.id = h.organization_id
    LEFT JOIN public.client_sites cs ON cs.id = h.client_site_id
    LEFT JOIN public.location_zones z ON z.id = h.zone_id
    LEFT JOIN public.documents d ON d.id = h.source_document_id
    LEFT JOIN public.user_profiles rp ON rp.id = h.reported_by
    WHERE h.location_id = p_location_id
      AND (p_include_retired OR h.status <> 'retired')
      AND public.can_read_place_hazard(h.organization_id, h.location_id, h.client_site_id, h.zone_id)
  ), '[]'::jsonb);
END;
$function$;
COMMENT ON FUNCTION "public"."get_place_hazard_register"(p_location_id uuid, p_include_retired boolean) IS 'Place hazard register for one house: officer reports awaiting review first, then live hazards critical first, with source and whether the caller may manage each.';
REVOKE ALL ON FUNCTION "public"."get_place_hazard_register"(p_location_id uuid, p_include_retired boolean) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_place_hazard_register"(p_location_id uuid, p_include_retired boolean) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_place_hazard_register"(p_location_id uuid, p_include_retired boolean) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_place_hazard_register"(p_location_id uuid, p_include_retired boolean) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_place_hazard_source"(p_hazard_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_hazard public.place_hazards%rowtype;
  v_doc public.documents%rowtype;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT * INTO v_hazard FROM public.place_hazards WHERE id = p_hazard_id AND status <> 'retired';
  IF NOT FOUND THEN RAISE EXCEPTION 'Hazard not found'; END IF;
  IF NOT public.can_read_place_hazard(v_hazard.organization_id, v_hazard.location_id, v_hazard.client_site_id, v_hazard.zone_id)
    AND NOT EXISTS (
      SELECT 1 FROM public.shifts s
      CROSS JOIN LATERAL public.shift_safety_places(s.id, NULL) p
      WHERE s.officer_user_id = v_actor
        AND s.status IN ('published', 'accepted', 'in_progress')
        AND p.location_id = v_hazard.location_id
    ) THEN
    RAISE EXCEPTION 'Not authorised to open this source';
  END IF;
  IF v_hazard.source_document_id IS NULL THEN
    RETURN jsonb_build_object('has_document', false, 'source_name', v_hazard.source_name, 'source_locator', v_hazard.source_locator);
  END IF;
  SELECT * INTO v_doc FROM public.documents WHERE id = v_hazard.source_document_id;
  RETURN jsonb_build_object(
    'has_document', v_doc.id IS NOT NULL AND v_doc.storage_object_ref IS NOT NULL,
    'storage_bucket', v_doc.storage_bucket,
    'storage_object_ref', v_doc.storage_object_ref,
    'original_filename', v_doc.original_filename,
    'mime_type', v_doc.mime_type,
    'source_name', v_hazard.source_name,
    'source_locator', v_hazard.source_locator
  );
END;
$function$;
COMMENT ON FUNCTION "public"."get_place_hazard_source"(p_hazard_id uuid) IS 'Storage location of a hazard''s source document for the place-hazard-source edge function to sign. Allowed for hazard readers and for officers with an open shift at the place.';
REVOKE ALL ON FUNCTION "public"."get_place_hazard_source"(p_hazard_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_place_hazard_source"(p_hazard_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_place_hazard_source"(p_hazard_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_place_hazard_source"(p_hazard_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_report_pack_activity_accounting"(p_pack_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
	v_pack record;
	v_from timestamptz;
	v_to timestamptz;
	v_live jsonb;
	v_frozen jsonb;
	v_categories jsonb;
	v_provenance jsonb;
	v_sources jsonb;
	v_client_month jsonb;
	v_exceptions jsonb;
begin
	if auth.uid() is null then
		raise exception 'Authenticated provider administrator required';
	end if;

	select pack.id, pack.organization_id, pack.service_agreement_id, pack.report_kind,
		pack.period_start, pack.period_end, pack.status, pack.generated_at, pack.updated_at,
		pack.data -> 'activityReport' as frozen,
		agreement.client_organization_id
	into v_pack
	from public.monthly_report_packs pack
	join public.service_agreements agreement on agreement.id = pack.service_agreement_id
	where pack.id = p_pack_id;

	if v_pack.id is null then
		raise exception 'Report pack not found';
	end if;
	if not public.is_report_provider_custodian_for_org(v_pack.organization_id) then
		raise exception 'Provider administrator access required';
	end if;
	if v_pack.report_kind <> 'monthly' then
		raise exception 'Activity accounting is available for monthly report packs only';
	end if;

	-- Same window as generate_due_report_packs.
	v_from := v_pack.period_start::timestamp at time zone 'Pacific/Auckland';
	v_to := (v_pack.period_end + 1)::timestamp at time zone 'Pacific/Auckland';
	v_live := public.build_agreement_activity_report(v_pack.service_agreement_id, v_from, v_to, 0) -> 'report';
	v_frozen := case when jsonb_typeof(v_pack.frozen) = 'object' then v_pack.frozen end;

	select coalesce(jsonb_agg(jsonb_build_object(
			'code', coalesce(f.code, l.code),
			'frozen', coalesce(f.entries, 0),
			'live', coalesce(l.entries, 0)
		) order by coalesce(f.code, l.code)), '[]'::jsonb)
	into v_categories
	from (
		select c ->> 'code' as code, (c ->> 'entries')::integer as entries
		from jsonb_array_elements(coalesce(v_frozen -> 'categories', '[]'::jsonb)) c
	) f
	full join (
		select c ->> 'code' as code, (c ->> 'entries')::integer as entries
		from jsonb_array_elements(coalesce(v_live -> 'categories', '[]'::jsonb)) c
	) l on l.code = f.code
	where coalesce(f.entries, 0) <> coalesce(l.entries, 0);

	with
	links as (
		select l.site_id, l.zone_id
		from public.service_agreement_locations l
		where l.service_agreement_id = v_pack.service_agreement_id
			and l.status = 'active'
	),
	scoped as (
		select 'event'::text as record_kind, e.id
		from public.location_events e
		where e.occurred_at >= v_from
			and e.occurred_at < v_to
			and e.source is distinct from 'observation_trigger'
			and exists (
				select 1 from links k
				where (k.zone_id is not null and k.zone_id = e.zone_id)
					or (k.site_id is not null and k.site_id = e.client_site_id)
			)
		union all
		select 'observation', o.id
		from public.observations o
		where o.observed_at >= v_from
			and o.observed_at < v_to
			and exists (
				select 1 from links k
				where (k.zone_id is not null and k.zone_id = o.zone_id)
					or (k.site_id is not null and k.site_id = o.site_id)
			)
	),
	ledger as (
		select s.record_kind, s.id, v.source_file, v.source_sheet, v.batch_id
		from scoped s
		left join lateral (
			select r.source_file, r.source_sheet, r.batch_id
			from public.patrol_import_record_versions r
			where r.record_kind = s.record_kind
				and r.record_id = s.id
				and r.is_current
				and r.provider_organization_id = v_pack.organization_id
				and r.client_organization_id = v_pack.client_organization_id
			order by r.version_no desc
			limit 1
		) v on true
	),
	counts as (
		select
			count(*) filter (where record_kind = 'event') as events,
			count(*) filter (where record_kind = 'event' and batch_id is not null) as events_ledger,
			count(*) filter (where record_kind = 'observation') as observations,
			count(*) filter (where record_kind = 'observation' and batch_id is not null) as observations_ledger
		from ledger
	),
	sources as (
		select l.source_file, l.source_sheet, l.batch_id,
			count(*) filter (where l.record_kind = 'event') as events,
			count(*) filter (where l.record_kind = 'observation') as observations
		from ledger l
		where l.batch_id is not null
		group by l.source_file, l.source_sheet, l.batch_id
	)
	select
		(select jsonb_build_object(
			'events', jsonb_build_object('inScope', c.events, 'withLedger', c.events_ledger, 'withoutLedger', c.events - c.events_ledger),
			'observations', jsonb_build_object('inScope', c.observations, 'withLedger', c.observations_ledger, 'withoutLedger', c.observations - c.observations_ledger)
		) from counts c),
		coalesce((
			select jsonb_agg(jsonb_build_object(
				'sourceFile', s.source_file,
				'sourceSheet', s.source_sheet,
				'batchId', s.batch_id,
				'batchStatus', b.status,
				'batchRows', b.row_count,
				'batchDuplicates', b.duplicate_count,
				'batchUnresolved', b.unresolved_count,
				'events', s.events,
				'observations', s.observations
			) order by s.events + s.observations desc, s.source_file, s.source_sheet)
			from (select * from sources order by events + observations desc, source_file, source_sheet limit 50) s
			left join public.file_import_batches b on b.id = s.batch_id and b.organization_id = v_pack.organization_id
		), '[]'::jsonb)
	into v_provenance, v_sources;

	with
	client_records as (
		select e.id, e.zone_id, e.client_site_id as site_id
		from public.location_events e
		where e.occurred_at >= v_from
			and e.occurred_at < v_to
			and e.source is distinct from 'observation_trigger'
			and (
				e.organization_id = v_pack.client_organization_id
				or exists (
					select 1 from public.patrol_import_record_versions r
					where r.record_kind = 'event' and r.record_id = e.id and r.is_current
						and r.provider_organization_id = v_pack.organization_id
						and r.client_organization_id = v_pack.client_organization_id
				)
			)
		union all
		select o.id, o.zone_id, o.site_id
		from public.observations o
		where o.observed_at >= v_from
			and o.observed_at < v_to
			and (
				o.organization_id = v_pack.client_organization_id
				or exists (
					select 1 from public.patrol_import_record_versions r
					where r.record_kind = 'observation' and r.record_id = o.id and r.is_current
						and r.provider_organization_id = v_pack.organization_id
						and r.client_organization_id = v_pack.client_organization_id
				)
			)
	),
	classified as (
		select c.*,
			case
				when exists (
					select 1 from public.service_agreement_locations l
					where l.service_agreement_id = v_pack.service_agreement_id and l.status = 'active'
						and ((l.zone_id is not null and l.zone_id = c.zone_id) or (l.site_id is not null and l.site_id = c.site_id))
				) then 'this_agreement'
				when exists (
					select 1 from public.service_agreement_locations l
					where l.service_agreement_id <> v_pack.service_agreement_id and l.status = 'active'
						and ((l.zone_id is not null and l.zone_id = c.zone_id) or (l.site_id is not null and l.site_id = c.site_id))
				) then 'other_agreement'
				else 'no_agreement_place'
			end as bucket
		from client_records c
	)
	select jsonb_build_object(
		'entries', count(*),
		'thisAgreement', count(*) filter (where bucket = 'this_agreement'),
		'otherAgreements', count(*) filter (where bucket = 'other_agreement'),
		'noAgreementPlace', count(*) filter (where bucket = 'no_agreement_place'),
		'unlinkedPlaces', coalesce((
			select jsonb_agg(jsonb_build_object('place', u.place, 'entries', u.n) order by u.n desc, u.place)
			from (
				select coalesce(s.name, z.name, 'No place recorded') as place, count(*) as n
				from classified x
				left join public.client_sites s on s.id = x.site_id
				left join public.location_zones z on z.id = x.zone_id
				where x.bucket = 'no_agreement_place'
				group by 1
				order by 2 desc, 1
				limit 10
			) u
		), '[]'::jsonb)
	)
	into v_client_month
	from classified;

	with client_years as (
		select extract(year from e.occurred_at at time zone 'Pacific/Auckland')::integer as year, count(*) as n
		from public.location_events e
		where e.organization_id = v_pack.client_organization_id
			and e.source is distinct from 'observation_trigger'
		group by 1
	)
	select jsonb_build_object(
		'futureDated', (
			select count(*) from public.location_events e
			where e.organization_id = v_pack.client_organization_id
				and e.source is distinct from 'observation_trigger'
				and e.occurred_at > now() + interval '1 day'
		) + (
			select count(*) from public.observations o
			where o.organization_id = v_pack.client_organization_id
				and o.observed_at > now() + interval '1 day'
		),
		'sparseYears', coalesce((
			select jsonb_agg(jsonb_build_object('year', y.year, 'entries', y.n) order by y.year)
			from client_years y
			where y.n < 50
		), '[]'::jsonb),
		'supersededDuplicates', (
			select count(*)
			from public.location_events_superseded d
			where (d.event_snapshot ->> 'occurred_at') ~ '^\d{4}-\d{2}-\d{2}'
				and (d.event_snapshot ->> 'occurred_at')::timestamptz >= v_from
				and (d.event_snapshot ->> 'occurred_at')::timestamptz < v_to
				and exists (
					select 1 from public.service_agreement_locations l
					where l.service_agreement_id = v_pack.service_agreement_id and l.status = 'active'
						and ((l.zone_id is not null and (l.zone_id)::text = d.event_snapshot ->> 'zone_id')
							or (l.site_id is not null and (l.site_id)::text = d.event_snapshot ->> 'client_site_id'))
				)
		)
	)
	into v_exceptions;

	return jsonb_build_object(
		'version', 1,
		'packId', v_pack.id,
		'packUpdatedAt', v_pack.updated_at,
		'status', v_pack.status,
		'period', jsonb_build_object('start', v_pack.period_start, 'end', v_pack.period_end),
		'generatedAt', v_pack.generated_at,
		'checkedAt', now(),
		'freshness', jsonb_build_object(
			'hasFrozenReport', v_frozen is not null,
			'frozenEntries', (v_frozen -> 'totals' ->> 'entries')::integer,
			'liveEntries', (v_live -> 'totals' ->> 'entries')::integer,
			'matchesLive', v_frozen is not null
				and (v_frozen #- '{accountedFor,itemised}' #- '{accountedFor,notItemised}')
					= (v_live #- '{accountedFor,itemised}' #- '{accountedFor,notItemised}'),
			'changedCategories', v_categories
		),
		'live', jsonb_build_object(
			'totals', v_live -> 'totals',
			'accountedFor', v_live -> 'accountedFor'
		),
		'provenance', v_provenance || jsonb_build_object('sources', v_sources),
		'clientMonth', v_client_month,
		'exceptions', v_exceptions
	);
end;
$function$;
COMMENT ON FUNCTION "public"."get_report_pack_activity_accounting"(p_pack_id uuid) IS 'Provider-only, read-only accounting for a monthly report pack: frozen versus live activity totals, import-ledger provenance per source file and batch, the client''s month split into this agreement, other agreements and unlinked places, and date and duplicate exceptions. Never persisted to client-readable data.';
REVOKE ALL ON FUNCTION "public"."get_report_pack_activity_accounting"(p_pack_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_report_pack_activity_accounting"(p_pack_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_report_pack_activity_accounting"(p_pack_id uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."get_roster_attendance_exceptions"(p_organization_id uuid, p_grace_minutes integer DEFAULT 15, p_from timestamp with time zone DEFAULT (now() - '24:00:00'::interval), p_to timestamp with time zone DEFAULT (now() + '24:00:00'::interval))
 RETURNS TABLE(shift_id uuid, officer_user_id uuid, service_type text, scheduled_start timestamp with time zone, scheduled_end timestamp with time zone, status text, exception_type text, minutes_overdue integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_admin_for_org(p_organization_id) then raise exception 'Roster administrator required'; end if;
  if p_grace_minutes < 0 or p_grace_minutes > 240 then raise exception 'Grace period is outside the accepted range'; end if;
  return query
  select s.id, s.officer_user_id, s.service_type, s.scheduled_start, s.scheduled_end, s.status,
    case when s.status = 'missed' then 'missed'
         when s.status in ('scheduled', 'published', 'accepted') then 'late_start'
         else 'active_overrun' end,
    case when s.status = 'missed' then greatest(0, floor(extract(epoch from (s.scheduled_end - s.scheduled_start)) / 60)::integer)
         when s.status in ('scheduled', 'published', 'accepted') then greatest(0, floor(extract(epoch from (clock_timestamp() - (s.scheduled_start + make_interval(mins => p_grace_minutes)))) / 60)::integer)
         else greatest(0, floor(extract(epoch from (clock_timestamp() - s.scheduled_end)) / 60)::integer) end
  from public.shifts s
  where s.organization_id = p_organization_id
    and s.scheduled_start >= p_from and s.scheduled_start <= p_to
    and (
      (s.status in ('scheduled', 'published', 'accepted') and s.scheduled_start + make_interval(mins => p_grace_minutes) < clock_timestamp() and s.actual_start is null)
      or (s.status = 'in_progress' and s.scheduled_end < clock_timestamp())
      or (s.status = 'missed' and not exists (
        select 1 from public.audit_log a where a.target_table = 'shifts' and a.target_id = s.id
          and a.action = 'roster_attendance_exception_acknowledged' and a.metadata->>'exception_type' = 'missed'))
    )
  order by s.scheduled_start;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."get_roster_attendance_exceptions"(p_organization_id uuid, p_grace_minutes integer, p_from timestamp with time zone, p_to timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_roster_attendance_exceptions"(p_organization_id uuid, p_grace_minutes integer, p_from timestamp with time zone, p_to timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_roster_attendance_exceptions"(p_organization_id uuid, p_grace_minutes integer, p_from timestamp with time zone, p_to timestamp with time zone) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_roster_attendance_exceptions"(p_organization_id uuid, p_grace_minutes integer, p_from timestamp with time zone, p_to timestamp with time zone) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_roster_batch_publish_failures"(p_client_request_id uuid)
 RETURNS TABLE(slot_id uuid, reason text, work_unit_id uuid)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select target_id, metadata->>'error', (metadata->>'work_unit_id')::uuid
  from public.audit_log
  where action = 'roster_batch_publish_materialization_failed'
    and metadata->>'client_request_id' = p_client_request_id::text
  order by created_at;
$function$;
REVOKE ALL ON FUNCTION "public"."get_roster_batch_publish_failures"(p_client_request_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_roster_batch_publish_failures"(p_client_request_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_roster_batch_publish_failures"(p_client_request_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_roster_batch_publish_failures"(p_client_request_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_roster_commercial_readiness"(p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone)
 RETURNS TABLE(slot_id uuid, pay_status text, billing_status text, quote_status text, geofence_status text, cost_centre_status text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_admin_for_org(p_organization_id) then raise exception 'Not authorised to view roster commercial readiness';end if;
  if p_from is null or p_to is null or p_from>=p_to or p_to-p_from>interval '62 days' then raise exception 'Readiness window must be between 1 and 62 days';end if;
  return query
  select s.id,
    case when exists(select 1 from public.rate_rules r where r.organization_id=s.organization_id and r.rule_kind='pay' and r.active and (r.service_type is null or r.service_type=u.service_type) and (r.effective_from is null or r.effective_from<=s.scheduled_start::date) and (r.effective_to is null or r.effective_to>=s.scheduled_start::date)) then 'ready' else 'missing_rule' end,
    case
      when public.roster_slot_is_source_truth(s.external_refs) then 'source_verified'
      when u.work_unit_type in ('internal', 'workshop') then 'not_applicable'
      when u.work_unit_type='static' and not exists(select 1 from public.service_agreement_locations l join public.service_agreements a on a.id=l.service_agreement_id join public.service_agreement_modules m on m.id=u.service_agreement_module_id and m.service_agreement_id=a.id and m.enabled where l.id=u.service_agreement_location_id and l.status='active' and a.agreement_type='operational' and (a.starts_on is null or a.starts_on<=s.scheduled_start::date) and (a.ends_on is null or a.ends_on>=s.scheduled_start::date)) then 'missing_contract'
      when u.work_unit_type='static' and public.roster_agreement_billing_ready((select l.service_agreement_id from public.service_agreement_locations l where l.id=u.service_agreement_location_id),(select l.site_id from public.service_agreement_locations l where l.id=u.service_agreement_location_id),(select l.zone_id from public.service_agreement_locations l where l.id=u.service_agreement_location_id)) then 'ready'
      when u.work_unit_type='static' then 'missing_rate'
      when s.linked_shift_id is null then 'pending_materialization'
      when not exists(select 1 from public.shift_stops st join public.shift_stop_modules sm on sm.shift_stop_id=st.id and sm.is_required where st.shift_id=s.linked_shift_id) or exists(select 1 from public.shift_stops st join public.shift_stop_modules sm on sm.shift_stop_id=st.id and sm.is_required where st.shift_id=s.linked_shift_id and (sm.service_agreement_location_id is null or sm.service_agreement_module_id is null)) then 'missing_attribution'
      when exists(select 1 from public.shift_stops st join public.shift_stop_modules sm on sm.shift_stop_id=st.id and sm.is_required join public.service_agreement_locations l on l.id=sm.service_agreement_location_id where st.shift_id=s.linked_shift_id and not public.roster_agreement_billing_ready(l.service_agreement_id,l.site_id,l.zone_id)) then 'missing_rate'
      else 'ready' end,
    case
      when public.roster_slot_is_source_truth(s.external_refs) then 'source_verified'
      when u.work_unit_type in ('internal', 'workshop') then 'not_applicable'
      when u.work_unit_type='static' and exists(select 1 from public.service_agreement_locations l join public.quotes q on q.service_agreement_id=l.service_agreement_id and q.status='accepted' where l.id=u.service_agreement_location_id) then 'accepted'
      when u.work_unit_type='static' then 'missing'
      when s.linked_shift_id is null then 'pending_materialization'
      when exists(select 1 from public.shift_stops st join public.shift_stop_modules sm on sm.shift_stop_id=st.id and sm.is_required left join public.service_agreement_locations l on l.id=sm.service_agreement_location_id left join public.quotes q on q.service_agreement_id=l.service_agreement_id and q.status='accepted' where st.shift_id=s.linked_shift_id and q.id is null) then 'missing'
      else 'accepted' end,
    case
      when public.roster_slot_is_source_truth(s.external_refs) then 'source_verified'
      when u.work_unit_type in ('internal', 'workshop') then 'not_applicable'
      when u.work_unit_type='static' then public.roster_place_geofence_state((select l.site_id from public.service_agreement_locations l where l.id=u.service_agreement_location_id),(select l.zone_id from public.service_agreement_locations l where l.id=u.service_agreement_location_id))
      when s.linked_shift_id is null then 'pending_materialization'
      when not exists(select 1 from public.shift_stops st where st.shift_id=s.linked_shift_id) then 'pending_materialization'
      when exists(select 1 from public.shift_stops st where st.shift_id=s.linked_shift_id and public.roster_place_geofence_state(st.site_id,st.zone_id)='missing') then 'missing'
      when not exists(select 1 from public.shift_stops st where st.shift_id=s.linked_shift_id and public.roster_place_geofence_state(st.site_id,st.zone_id)<>'verified') then 'verified'
      else 'mapped_unverified' end,
    case when u.work_unit_type in ('patrol', 'static') then 'not_applicable' when u.cost_centre_id is not null then 'ready' else 'missing' end
  from public.roster_slots s join public.roster_work_units u on u.id=s.work_unit_id
  where s.organization_id=p_organization_id and s.scheduled_start<p_to and s.scheduled_end>p_from and s.status<>'cancelled';
end;$function$;
COMMENT ON FUNCTION "public"."get_roster_commercial_readiness"(p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) IS 'Admin-only pay, billing, quote, geofence and cost-centre readiness per roster slot. Slots seeded from an owner-verified source of record report source_verified: no geofence requirement, billed by their source.';
REVOKE ALL ON FUNCTION "public"."get_roster_commercial_readiness"(p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_roster_commercial_readiness"(p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_roster_commercial_readiness"(p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_roster_commercial_readiness"(p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_roster_labour_cost"(p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone)
 RETURNS TABLE(slot_id uuid, work_unit_name text, staff_id uuid, scheduled_hours numeric, pay_rate numeric, charge_rate numeric, pay_cost numeric, billable numeric, margin numeric, rate_status text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_admin_for_org(p_organization_id) then raise exception 'Not authorised to view labour cost for this organization'; end if;
  return query
  select s.id, work_unit.name, s.staff_id,
    round(extract(epoch from (s.scheduled_end - s.scheduled_start)) / 3600.0, 2),
    pay.amount, bill.amount,
    round(coalesce(pay.amount, 0) * extract(epoch from (s.scheduled_end - s.scheduled_start)) / 3600.0, 2),
    case when historical.yes then null else round(coalesce(bill.amount, 0) * extract(epoch from (s.scheduled_end - s.scheduled_start)) / 3600.0, 2) end,
    case when historical.yes then null else round((coalesce(bill.amount, 0) - coalesce(pay.amount, 0)) * extract(epoch from (s.scheduled_end - s.scheduled_start)) / 3600.0, 2) end,
    case
      when historical.yes and pay.amount is null then 'no_pay_rule'
      when work_unit.work_unit_type = 'workshop' then 'billed_via_work_order'
      when historical.yes then 'billed_via_patrol_log'
      when pay.amount is null and bill.amount is null then 'no_rules'
      when pay.amount is null then 'no_pay_rule'
      when bill.amount is null then 'no_billing_rule'
      else 'resolved' end
  from public.roster_slots s
  join public.roster_work_units work_unit on work_unit.id = s.work_unit_id
  left join public.staff_profiles staff on staff.id = s.staff_id
  cross join lateral (select (work_unit.work_unit_type = 'workshop' or coalesce(s.external_refs->>'source' = 'rm_patrol_log_labour', false)) as yes) historical
  left join lateral public.resolve_rate_rule(p_organization_id, 'pay', s.scheduled_start, work_unit.service_type, null, null, null, null, null, staff.role_code, null, null, 'hourly') pay on true
  left join lateral public.resolve_rate_rule(p_organization_id, 'billing', s.scheduled_start, work_unit.service_type, null, null, null, null, null, staff.role_code, null, null, 'hourly') bill on not historical.yes
  where s.organization_id = p_organization_id and s.status not in ('cancelled', 'declined') and s.scheduled_start >= p_from and s.scheduled_start < p_to
  order by s.scheduled_start;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."get_roster_labour_cost"(p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_roster_labour_cost"(p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_roster_labour_cost"(p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_roster_labour_cost"(p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_safety_review_workspace"(p_organization_id uuid, p_location_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_admin_for_org(p_organization_id) THEN RAISE EXCEPTION 'Safety review workspace access denied'; END IF;
  IF p_location_id IS NOT NULL AND NOT public.can_manage_place_hazards(p_organization_id, p_location_id) THEN
    RAISE EXCEPTION 'Place safety review access denied';
  END IF;
  RETURN jsonb_build_object(
    'owners', coalesce((SELECT jsonb_agg(jsonb_build_object('id', id, 'name', coalesce(display_name, 'Unnamed staff member')) ORDER BY display_name)
      FROM public.user_profiles WHERE organization_id = p_organization_id AND deactivated_at IS NULL), '[]'::jsonb),
    'hazards', coalesce((SELECT jsonb_agg(jsonb_build_object('id', h.id, 'title', h.title, 'version', h.version,
      'controls', h.controls, 'control_levels', h.control_levels, 'risk_owner_id', h.risk_owner_id,
      'review_due', h.review_due, 'location_id', h.location_id) ORDER BY h.title)
      FROM public.place_hazards h WHERE h.organization_id = p_organization_id AND h.status <> 'retired'
        AND (p_location_id IS NULL OR h.location_id = p_location_id)
        AND public.can_manage_place_hazards(h.organization_id, h.location_id)), '[]'::jsonb),
    'reviews', coalesce((SELECT jsonb_agg(to_jsonb(r) || jsonb_build_object(
      'assessment', (SELECT to_jsonb(a) - 'briefing_snapshot' FROM public.dynamic_risk_assessments a WHERE a.id = r.assessment_id),
      'source_description', coalesce(
        (SELECT description FROM public.officer_field_reports WHERE id = r.field_report_id AND organization_id = r.organization_id),
        (SELECT description FROM public.incidents WHERE id = r.incident_id AND organization_id = r.organization_id)
      )
    ) ORDER BY r.created_at DESC) FROM public.safety_reviews r WHERE r.organization_id = p_organization_id
      AND (p_location_id IS NULL OR r.location_id = p_location_id)), '[]'::jsonb),
    'incidents', coalesce((SELECT jsonb_agg(jsonb_build_object('id', i.id, 'name', i.incident_type || ' - ' || i.occurred_at::date, 'summary', i.description))
      FROM public.incidents i WHERE i.organization_id = p_organization_id AND NOT EXISTS (
        SELECT 1 FROM public.safety_reviews r WHERE r.incident_id = i.id
      ) AND (p_location_id IS NULL OR i.location_id = p_location_id
        OR EXISTS (SELECT 1 FROM public.client_sites s WHERE s.id = i.client_site_id AND s.location_id = p_location_id)
        OR EXISTS (SELECT 1 FROM public.location_zones z WHERE z.id = i.zone_id AND z.location_id = p_location_id))), '[]'::jsonb),
    'investigations', coalesce((SELECT jsonb_agg(jsonb_build_object('id', id, 'name', investigation_reference || ' - ' || title))
      FROM public.investigations WHERE organization_id = p_organization_id), '[]'::jsonb)
  );
END;
$function$;
REVOKE ALL ON FUNCTION "public"."get_safety_review_workspace"(p_organization_id uuid, p_location_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_safety_review_workspace"(p_organization_id uuid, p_location_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_safety_review_workspace"(p_organization_id uuid, p_location_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_safety_review_workspace"(p_organization_id uuid, p_location_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_safety_warnings"(p_entity_type text, p_entity_ids uuid[])
 RETURNS TABLE(id uuid, entity_type text, entity_id uuid, requested_id uuid, hazard_class text, alert_level text, raised_at timestamp with time zone, organization_id uuid, organization_name text, contact_email text, contact_phone text, is_own_organization boolean, reason text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_org uuid;
  v_ids uuid[] := coalesce(p_entity_ids, '{}'::uuid[]);
begin
  -- Service-role callers (edge functions such as the officer scan) have no auth.uid(); they see the same redacted rows.
  if v_actor is not null then
    select up.organization_id into v_org from public.user_profiles up where up.id = v_actor and up.deactivated_at is null;
    if v_org is null then raise exception 'Active user required'; end if;
  elsif current_setting('request.jwt.claim.role', true) is distinct from 'service_role' and current_user <> 'postgres' then
    raise exception 'Active user required';
  end if;
  if cardinality(v_ids) = 0 or cardinality(v_ids) > 200 then return; end if;

  return query
  with requested as (
    select r.requested_id, e.entity_type, e.entity_id
    from unnest(v_ids) as r(requested_id)
    cross join lateral public.resolve_flag_entity(p_entity_type, r.requested_id) e
  )
  select f.id, f.entity_type, f.entity_id, q.requested_id, f.hazard_class, f.alert_level, f.raised_at,
         o.id, o.name, o.contact_email, o.contact_phone,
         (f.organization_id = v_org),
         case when f.organization_id = v_org then f.reason else null end
  from requested q
  join public.entity_flags f on f.entity_type = q.entity_type and f.entity_id = q.entity_id
  join public.organizations o on o.id = f.organization_id
  where f.active and f.hazard_class is not null
  order by case f.alert_level when 'critical' then 0 when 'high' then 1 when 'medium' then 2 else 3 end, f.raised_at desc;
end;
$function$;
COMMENT ON FUNCTION "public"."get_safety_warnings"(p_entity_type text, p_entity_ids uuid[]) IS 'Platform-wide health-and-safety warnings for vehicles, people, places (or sites/zones, resolved to their place): every organisation''s active hazard-classed flag, redacted to hazard class, severity, raised_at and the raising organisation''s contact path. reason is returned only for the caller''s own organisation. HSWA 2015 s.34/s.36 with Privacy Act 2020 IPP 11(1)(f); owner ruling 2026-09-15.';
REVOKE ALL ON FUNCTION "public"."get_safety_warnings"(p_entity_type text, p_entity_ids uuid[]) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_safety_warnings"(p_entity_type text, p_entity_ids uuid[]) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_safety_warnings"(p_entity_type text, p_entity_ids uuid[]) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_safety_warnings"(p_entity_type text, p_entity_ids uuid[]) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_shift_break_entitlement"(p_shift_id uuid)
 RETURNS TABLE(worked_hours numeric, rest_breaks_required integer, meal_breaks_required integer, rest_breaks_taken integer, meal_breaks_taken integer, compliant boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_shift public.shifts%rowtype;
  v_hours numeric;
  v_rest_req integer;
  v_meal_req integer;
  v_rest_taken integer;
  v_meal_taken integer;
begin
  select s.* into v_shift from public.shifts s where s.id = p_shift_id;
  if not found then
    raise exception 'Shift not found';
  end if;

  v_hours := extract(epoch from (coalesce(v_shift.actual_end, v_shift.scheduled_end)
    - coalesce(v_shift.actual_start, v_shift.scheduled_start))) / 3600.0;

  v_rest_req := case
    when v_hours < 2 then 0
    when v_hours < 4 then 1
    when v_hours < 6 then 1
    when v_hours < 8 then 2
    else 2 + floor((v_hours - 8) / 4)::integer
  end;

  v_meal_req := case
    when v_hours < 4 then 0
    when v_hours < 8 then 1
    else 1 + floor((v_hours - 8) / 4)::integer
  end;

  select
    count(*) filter (where b.break_type = 'rest' and b.ended_at is not null),
    count(*) filter (where b.break_type = 'meal' and b.ended_at is not null)
  into v_rest_taken, v_meal_taken
  from public.shift_breaks b
  where b.shift_id = v_shift.id;

  return query select
    round(v_hours, 2),
    v_rest_req,
    v_meal_req,
    coalesce(v_rest_taken, 0),
    coalesce(v_meal_taken, 0),
    coalesce(v_rest_taken, 0) >= v_rest_req and coalesce(v_meal_taken, 0) >= v_meal_req;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."get_shift_break_entitlement"(p_shift_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_shift_break_entitlement"(p_shift_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_shift_break_entitlement"(p_shift_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_shift_break_entitlement"(p_shift_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_shift_end_readiness"(p_shift_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_shift public.shifts%rowtype;
  v_open_stops jsonb;
  v_open_stop_count integer;
  v_open_modules integer;
  v_open_jobs integer;
  v_alerts integer;
  v_debrief boolean;
  v_blockers text[] := '{}';
begin
  if v_actor is null then raise exception 'Authentication required'; end if;
  select s.* into v_shift from public.shifts s where s.id = p_shift_id;
  if not found then raise exception 'Shift not found'; end if;
  if v_shift.officer_user_id <> v_actor and not public.is_admin_for_org(v_shift.organization_id) then
    raise exception 'Only the assigned officer or an administrator can review this shift';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object('stop_id', st.id, 'place', coalesce(cs.name, lz.name, 'Stop'), 'status', st.status, 'module_key', st.module_key) order by st.stop_order), '[]'::jsonb), count(*)::integer
  into v_open_stops, v_open_stop_count
  from public.shift_stops st
  left join public.client_sites cs on cs.id = st.site_id
  left join public.location_zones lz on lz.id = st.zone_id
  where st.shift_id = v_shift.id and st.status not in ('completed', 'skipped', 'cancelled');

  select count(*)::integer into v_open_modules
  from public.shift_stop_modules sm join public.shift_stops st on st.id = sm.shift_stop_id
  where st.shift_id = v_shift.id and sm.is_required and sm.status not in ('completed', 'skipped');

  select count(*)::integer into v_open_jobs from public.dispatch_jobs j where j.shift_id = v_shift.id and j.status not in ('completed', 'cancelled');
  select count(*)::integer into v_alerts from public.welfare_alerts w where w.shift_id = v_shift.id and w.status <> 'resolved';
  v_debrief := exists (select 1 from public.shift_debriefs d where d.shift_id = v_shift.id and d.officer_user_id = v_shift.officer_user_id);

  if v_shift.status <> 'in_progress' then v_blockers := array_append(v_blockers, format('The shift is %s, not in progress', replace(v_shift.status, '_', ' '))); end if;
  if v_open_stop_count > 0 then v_blockers := array_append(v_blockers, format('%s %s still open', v_open_stop_count, case when v_open_stop_count = 1 then 'stop is' else 'stops are' end)); end if;
  if v_open_modules > 0 then v_blockers := array_append(v_blockers, format('%s required stop %s not done', v_open_modules, case when v_open_modules = 1 then 'task is' else 'tasks are' end)); end if;
  if v_open_jobs > 0 then v_blockers := array_append(v_blockers, format('%s dispatch %s still open', v_open_jobs, case when v_open_jobs = 1 then 'job is' else 'jobs are' end)); end if;
  if v_alerts > 0 then v_blockers := array_append(v_blockers, format('%s welfare %s not resolved', v_alerts, case when v_alerts = 1 then 'alert is' else 'alerts are' end)); end if;
  if not v_debrief then v_blockers := array_append(v_blockers, 'The debrief has not been recorded'); end if;

  return jsonb_build_object(
    'shift_id', v_shift.id,
    'status', v_shift.status,
    'service_type', v_shift.service_type,
    'scheduled_end', v_shift.scheduled_end,
    'actual_start', v_shift.actual_start,
    'open_stops', v_open_stops,
    'open_stop_count', v_open_stop_count,
    'open_required_task_count', v_open_modules,
    'open_dispatch_job_count', v_open_jobs,
    'active_welfare_alert_count', v_alerts,
    'debrief_submitted', v_debrief,
    'blockers', to_jsonb(v_blockers),
    'can_end', v_shift.status = 'in_progress' and v_open_stop_count = 0 and v_open_modules = 0 and v_open_jobs = 0 and v_alerts = 0 and v_debrief,
    'can_end_after_debrief', v_shift.status = 'in_progress' and v_open_stop_count = 0 and v_open_modules = 0 and v_open_jobs = 0 and v_alerts = 0
  );
end;
$function$;
COMMENT ON FUNCTION "public"."get_shift_end_readiness"(p_shift_id uuid) IS 'What still stands between an in-progress shift and its end: open stops by place, open required stop tasks, open dispatch jobs, active welfare alerts, debrief state, plain-words blockers, and whether it can end now or after the debrief. Mirrors the rules complete_officer_shift enforces.';
REVOKE ALL ON FUNCTION "public"."get_shift_end_readiness"(p_shift_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_shift_end_readiness"(p_shift_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_shift_end_readiness"(p_shift_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_shift_end_readiness"(p_shift_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_shift_risk_assessments"(p_shift_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.shifts s WHERE s.id = p_shift_id AND
      (s.officer_user_id = auth.uid() OR public.is_admin_for_org(s.organization_id))
  ) THEN RAISE EXCEPTION 'Shift assessment access denied'; END IF;
  RETURN coalesce((SELECT jsonb_agg((to_jsonb(a) - 'briefing_snapshot') || jsonb_build_object(
      'review_status', r.status, 'review_outcome', r.outcome, 'reviewed_at', r.reviewed_at
    ) ORDER BY a.signed_at DESC)
    FROM public.dynamic_risk_assessments a LEFT JOIN public.safety_reviews r ON r.assessment_id = a.id
    WHERE a.shift_id = p_shift_id), '[]'::jsonb);
END;
$function$;
REVOKE ALL ON FUNCTION "public"."get_shift_risk_assessments"(p_shift_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_shift_risk_assessments"(p_shift_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_shift_risk_assessments"(p_shift_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_shift_risk_assessments"(p_shift_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_shift_safety_briefing"(p_shift_id uuid, p_stop_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_shift public.shifts%rowtype;
  v_briefing jsonb;
  v_ack public.safety_briefing_acknowledgements%rowtype;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT * INTO v_shift FROM public.shifts WHERE id = p_shift_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Shift not found'; END IF;
  IF v_shift.officer_user_id IS DISTINCT FROM v_actor AND NOT public.is_admin_for_org(v_shift.organization_id) THEN
    RAISE EXCEPTION 'Only the assigned officer or an administrator can read this briefing';
  END IF;
  IF p_stop_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.shift_stops WHERE id = p_stop_id AND shift_id = p_shift_id) THEN
    RAISE EXCEPTION 'Stop is not part of this shift';
  END IF;

  v_briefing := public.build_shift_safety_briefing(p_shift_id, p_stop_id);

  SELECT * INTO v_ack
  FROM public.safety_briefing_acknowledgements a
  WHERE a.shift_id = p_shift_id
    AND a.officer_user_id = v_shift.officer_user_id
    AND a.shift_stop_id IS NOT DISTINCT FROM p_stop_id
  ORDER BY a.acknowledged_at DESC
  LIMIT 1;

  RETURN v_briefing || jsonb_build_object(
    'shift_status', v_shift.status,
    'acknowledgement_required', (v_briefing->>'item_count')::int > 0,
    'acknowledged', v_ack.id IS NOT NULL AND v_ack.briefing_hash = v_briefing->>'briefing_hash',
    'acknowledged_at', CASE WHEN v_ack.briefing_hash = v_briefing->>'briefing_hash' THEN v_ack.acknowledged_at END,
    'changed_since_acknowledgement', v_ack.id IS NOT NULL AND v_ack.briefing_hash <> v_briefing->>'briefing_hash',
    'is_assigned_officer', v_shift.officer_user_id = v_actor
  );
END;
$function$;
COMMENT ON FUNCTION "public"."get_shift_safety_briefing"(p_shift_id uuid, p_stop_id uuid) IS 'Officer safety briefing for a shift (or one patrol stop): live place hazards critical first with controls and source reference, active place safety warnings, and whether the assigned officer has acknowledged this exact version. Readable by the assigned officer or an administrator of the shift''s organisation.';
REVOKE ALL ON FUNCTION "public"."get_shift_safety_briefing"(p_shift_id uuid, p_stop_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_shift_safety_briefing"(p_shift_id uuid, p_stop_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_shift_safety_briefing"(p_shift_id uuid, p_stop_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_shift_safety_briefing"(p_shift_id uuid, p_stop_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_site_induction_state"(p_staff_id uuid, p_service_agreement_location_id uuid)
 RETURNS TABLE(requirement_id uuid, induction_name text, required boolean, completed boolean, expires_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select r.id, r.induction_name, r.required,
    exists(select 1 from public.staff_site_inductions si where si.requirement_id = r.id and si.staff_id = p_staff_id and (si.expires_at is null or si.expires_at >= current_date)),
    (select si.expires_at from public.staff_site_inductions si where si.requirement_id = r.id and si.staff_id = p_staff_id order by si.completed_at desc limit 1)
  from public.site_induction_requirements r
  where r.service_agreement_location_id = p_service_agreement_location_id and r.active;
$function$;
REVOKE ALL ON FUNCTION "public"."get_site_induction_state"(p_staff_id uuid, p_service_agreement_location_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_site_induction_state"(p_staff_id uuid, p_service_agreement_location_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_site_induction_state"(p_staff_id uuid, p_service_agreement_location_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_site_induction_state"(p_staff_id uuid, p_service_agreement_location_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_staff_branch_authorisations"(p_user_id uuid)
 RETURNS TABLE(id uuid, branch_organization_id uuid, branch_name text, role_at_branch text, module_access text[], can_be_rostered boolean, status text, starts_on date, ends_on date, authorised_by uuid, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
begin
  if v_actor is null then raise exception 'Authenticated user required'; end if;
  if p_user_id <> v_actor and not exists (
    select 1 from public.user_profiles actor
    join public.user_profiles target on target.id = p_user_id
    where actor.id = v_actor
      and actor.deactivated_at is null
      and (actor.role = 'grand_master' or (target.employer_organization_id = coalesce(actor.employer_organization_id, actor.organization_id) and (actor.role in ('master', 'admin', 'admin_officer') or cardinality(public.user_managed_branch_ids()) > 0)))
  ) then
    raise exception 'Not authorised to view this staff member branch access';
  end if;
  return query
    select assignment.id, assignment.branch_org_id, branch.name, assignment.role_at_branch,
      assignment.module_access, assignment.can_be_rostered, assignment.status,
      assignment.starts_on, assignment.ends_on, assignment.authorised_by, assignment.updated_at
  from public.staff_branch_authorisations assignment
  join public.organizations branch on branch.id = assignment.branch_org_id
  where assignment.user_id = p_user_id
    and (p_user_id = v_actor or exists(select 1 from public.user_profiles actor where actor.id = v_actor and actor.role in ('grand_master', 'master', 'admin', 'admin_officer')) or assignment.branch_org_id = any(public.user_managed_branch_ids()))
  order by branch.name;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."get_staff_branch_authorisations"(p_user_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_staff_branch_authorisations"(p_user_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_staff_branch_authorisations"(p_user_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_staff_branch_authorisations"(p_user_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_staff_onboarding_readiness"(p_organization_id uuid)
 RETURNS TABLE(ledger_id uuid, staff_id uuid, user_id uuid, display_name text, current_stage text, status text, version integer, target_start date, identity_status text, employment_status text, evidence_status text, supervision_status text, induction_status text, work_status text, blockers text[], next_action text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_admin_for_org(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorised to assess staff onboarding';
  END IF;

  RETURN QUERY
  SELECT
    l.id,
    sp.id,
    sp.user_id,
    coalesce(up.display_name, up.email, 'Unnamed staff'),
    l.current_stage,
    l.status,
    l.version,
    l.target_start,
    CASE
      WHEN up.id IS NOT NULL
        AND up.deactivated_at IS NULL
        AND up.email IS NOT NULL
        AND up.display_name IS NOT NULL THEN 'complete'
      ELSE 'blocked'
    END,
    CASE
      WHEN sp.employment_type IS NOT NULL
        AND sp.start_date IS NOT NULL
        AND (sp.end_date IS NULL OR sp.end_date >= current_date)
        AND sp.role_code IS NOT NULL THEN 'complete'
      ELSE 'blocked'
    END,
    CASE
      WHEN EXISTS (
        SELECT 1 FROM public.staff_credentials c
        WHERE c.staff_id = sp.id
          AND c.verified
          AND (c.expiry_date IS NULL OR c.expiry_date >= current_date)
      )
      AND EXISTS (SELECT 1 FROM public.staff_documents d WHERE d.staff_id = sp.id)
      AND EXISTS (SELECT 1 FROM public.staff_skills sk WHERE sk.staff_id = sp.id) THEN 'complete'
      ELSE 'blocked'
    END,
    CASE
      WHEN EXISTS (
        SELECT 1 FROM public.staff_reporting sr
        WHERE sr.user_id = coalesce(sp.user_id, sp.id)
          AND sr.scope_org_id = p_organization_id
          AND sr.relationship_type = 'line_manager'
          AND sr.effective_to IS NULL
      ) THEN 'complete'
      ELSE 'blocked'
    END,
    CASE
      WHEN EXISTS (
        SELECT 1 FROM public.staff_training_records tr
        WHERE tr.staff_id = sp.id
          AND tr.training_type = 'induction'
          AND coalesce(tr.passed, true)
          AND (tr.expiry_date IS NULL OR tr.expiry_date >= current_date)
      ) THEN 'complete'
      ELSE 'blocked'
    END,
    CASE WHEN sp.work_ready THEN 'ready' ELSE 'blocked' END,
    array_remove(ARRAY[
      CASE WHEN up.id IS NULL OR up.deactivated_at IS NOT NULL OR up.email IS NULL OR up.display_name IS NULL THEN 'Complete active identity and invitation' END,
      CASE WHEN sp.employment_type IS NULL THEN 'Select an employment type' END,
      CASE WHEN sp.start_date IS NULL THEN 'Set a current employment start date' END,
      CASE WHEN sp.end_date IS NOT NULL AND sp.end_date < current_date THEN 'Employment has ended' END,
      CASE WHEN sp.role_code IS NULL THEN 'Assign a payroll role' END,
      CASE WHEN NOT EXISTS (
        SELECT 1 FROM public.staff_credentials c
        WHERE c.staff_id = sp.id
          AND c.verified
          AND (c.expiry_date IS NULL OR c.expiry_date >= current_date)
      ) THEN 'Verify a current credential' END,
      CASE WHEN NOT EXISTS (SELECT 1 FROM public.staff_documents d WHERE d.staff_id = sp.id) THEN 'Upload an employment or credential document' END,
      CASE WHEN NOT EXISTS (SELECT 1 FROM public.staff_skills sk WHERE sk.staff_id = sp.id) THEN 'Record at least one staff skill' END,
      CASE WHEN NOT EXISTS (
        SELECT 1 FROM public.staff_reporting sr
        WHERE sr.user_id = coalesce(sp.user_id, sp.id)
          AND sr.scope_org_id = p_organization_id
          AND sr.relationship_type = 'line_manager'
          AND sr.effective_to IS NULL
      ) THEN 'Assign a line manager' END,
      CASE WHEN NOT EXISTS (
        SELECT 1 FROM public.staff_training_records tr
        WHERE tr.staff_id = sp.id
          AND tr.training_type = 'induction'
          AND coalesce(tr.passed, true)
          AND (tr.expiry_date IS NULL OR tr.expiry_date >= current_date)
      ) THEN 'Record completed induction' END,
      CASE WHEN NOT sp.work_ready THEN 'Complete human work-readiness review' END
    ], NULL)::text[],
    CASE
      WHEN up.id IS NULL OR up.deactivated_at IS NOT NULL OR up.email IS NULL OR up.display_name IS NULL THEN 'Complete identity'
      WHEN sp.employment_type IS NULL OR sp.start_date IS NULL OR (sp.end_date IS NOT NULL AND sp.end_date < current_date) OR sp.role_code IS NULL THEN 'Complete employment setup'
      WHEN NOT EXISTS (
        SELECT 1 FROM public.staff_credentials c
        WHERE c.staff_id = sp.id
          AND c.verified
          AND (c.expiry_date IS NULL OR c.expiry_date >= current_date)
      ) THEN 'Verify credential'
      WHEN NOT EXISTS (SELECT 1 FROM public.staff_documents d WHERE d.staff_id = sp.id) THEN 'Upload evidence'
      WHEN NOT EXISTS (SELECT 1 FROM public.staff_skills sk WHERE sk.staff_id = sp.id) THEN 'Record skill'
      WHEN NOT EXISTS (
        SELECT 1 FROM public.staff_reporting sr
        WHERE sr.user_id = coalesce(sp.user_id, sp.id)
          AND sr.scope_org_id = p_organization_id
          AND sr.relationship_type = 'line_manager'
          AND sr.effective_to IS NULL
      ) THEN 'Assign line manager'
      WHEN NOT EXISTS (
        SELECT 1 FROM public.staff_training_records tr
        WHERE tr.staff_id = sp.id
          AND tr.training_type = 'induction'
          AND coalesce(tr.passed, true)
          AND (tr.expiry_date IS NULL OR tr.expiry_date >= current_date)
      ) THEN 'Record induction'
      WHEN NOT sp.work_ready THEN 'Review work readiness'
      ELSE 'Ready'
    END
  FROM public.staff_onboarding_ledgers l
  JOIN public.staff_profiles sp ON sp.id = l.staff_id
  LEFT JOIN public.user_profiles up ON up.id = coalesce(sp.user_id, sp.id)
  WHERE l.organization_id = p_organization_id
  ORDER BY l.current_stage, up.display_name NULLS LAST;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."get_staff_onboarding_readiness"(p_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_staff_onboarding_readiness"(p_organization_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_staff_onboarding_readiness"(p_organization_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_staff_onboarding_readiness"(p_organization_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_staff_readiness_assessment"(p_organization_id uuid)
 RETURNS TABLE(staff_id uuid, user_id uuid, work_ready boolean, identity_status text, employment_status text, credential_status text, training_status text, blockers text[])
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_admin_for_org(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorised to assess staff readiness';
  END IF;

  RETURN QUERY
  SELECT
    sp.id,
    sp.user_id,
    sp.work_ready,
    CASE
      WHEN up.id IS NULL THEN 'unlinked'
      WHEN up.deactivated_at IS NOT NULL THEN 'deactivated'
      WHEN up.role NOT IN ('officer', 'admin_officer') THEN 'not_field_role'
      ELSE 'active'
    END,
    CASE
      WHEN sp.end_date IS NOT NULL AND sp.end_date < current_date THEN 'ended'
      WHEN sp.employment_type IS NULL THEN 'missing_employment_type'
      WHEN sp.start_date IS NULL THEN 'missing_start_date'
      WHEN sp.role_code IS NULL THEN 'missing_pay_role'
      WHEN sp.start_date > current_date THEN 'not_started'
      ELSE 'current'
    END,
    CASE
      WHEN up.role NOT IN ('officer', 'admin_officer') THEN 'not_applicable'
      WHEN NOT EXISTS (
        SELECT 1 FROM public.staff_credentials c
        WHERE c.staff_id = sp.id
          AND c.verified
          AND (c.expiry_date IS NULL OR c.expiry_date >= current_date)
      ) THEN 'missing_valid'
      WHEN EXISTS (
        SELECT 1 FROM public.staff_credentials c
        WHERE c.staff_id = sp.id
          AND (NOT c.verified OR (c.expiry_date IS NOT NULL AND c.expiry_date < current_date))
      ) THEN 'attention'
      ELSE 'current'
    END,
    CASE
      WHEN EXISTS (
        SELECT 1 FROM public.staff_training_records tr
        WHERE tr.staff_id = sp.id
          AND (tr.passed = false OR (tr.expiry_date IS NOT NULL AND tr.expiry_date < current_date))
      ) THEN 'attention'
      ELSE 'clear'
    END,
    array_remove(ARRAY[
      CASE
        WHEN up.id IS NULL THEN 'Identity is not linked'
        WHEN up.deactivated_at IS NOT NULL THEN 'User access is deactivated'
        WHEN up.role NOT IN ('officer', 'admin_officer') THEN 'User is not assigned a field role'
      END,
      CASE WHEN sp.employment_type IS NULL THEN 'Employment type is not set' END,
      CASE
        WHEN sp.start_date IS NULL THEN 'Employment start date is not set'
        WHEN sp.start_date > current_date THEN 'Employment has not started'
      END,
      CASE WHEN sp.end_date IS NOT NULL AND sp.end_date < current_date THEN 'Employment has ended' END,
      CASE WHEN sp.role_code IS NULL THEN 'Payroll role is not assigned' END,
      CASE
        WHEN up.role IN ('officer', 'admin_officer')
          AND NOT EXISTS (
            SELECT 1 FROM public.staff_credentials c
            WHERE c.staff_id = sp.id
              AND c.verified
              AND (c.expiry_date IS NULL OR c.expiry_date >= current_date)
          ) THEN 'No verified current credential'
      END
    ], NULL)::text[]
  FROM public.staff_profiles sp
  LEFT JOIN public.user_profiles up ON up.id = sp.user_id
  WHERE sp.organization_id = p_organization_id;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."get_staff_readiness_assessment"(p_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_staff_readiness_assessment"(p_organization_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_staff_readiness_assessment"(p_organization_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_staff_readiness_assessment"(p_organization_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_timesheet_break_review"(p_timesheet_id uuid)
 RETURNS TABLE(shift_id uuid, planned_minutes integer, taken_minutes numeric, unpaid boolean, review_status text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_sheet public.timesheets%rowtype; v_staff public.staff_profiles%rowtype;
BEGIN
  SELECT * INTO v_sheet FROM public.timesheets WHERE id=p_timesheet_id;
  IF NOT FOUND OR auth.uid() IS NULL OR NOT public.is_admin_for_org(v_sheet.organization_id) THEN
    RAISE EXCEPTION 'Timesheet review authority required' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_staff FROM public.staff_profiles WHERE id=v_sheet.staff_id;
  RETURN QUERY SELECT s.id,coalesce(r.planned_break_minutes,0),b.minutes,coalesce(r.break_unpaid,false),
    CASE WHEN coalesce(r.planned_break_minutes,0)=0 THEN 'not_planned'
      WHEN b.minutes=0 THEN 'not_recorded' WHEN b.minutes<r.planned_break_minutes THEN 'short'
      WHEN b.minutes>r.planned_break_minutes THEN 'long' ELSE 'matched' END
  FROM public.shifts s LEFT JOIN public.roster_slots r ON r.linked_shift_id=s.id
  CROSS JOIN LATERAL (
    SELECT coalesce(sum(extract(epoch FROM sb.ended_at-sb.started_at)/60)
      FILTER (WHERE sb.ended_at IS NOT NULL),0)::numeric AS minutes
    FROM public.shift_breaks sb WHERE sb.shift_id=s.id AND sb.organization_id=v_sheet.organization_id
      AND sb.is_paid = NOT coalesce(r.break_unpaid,false)
  ) b
  WHERE s.organization_id=v_sheet.organization_id AND s.officer_user_id IN(v_staff.id,v_staff.user_id)
    AND (s.id=v_sheet.shift_id OR
      ((s.scheduled_start AT TIME ZONE 'Pacific/Auckland')::date >= v_sheet.period_start
       AND (s.scheduled_start AT TIME ZONE 'Pacific/Auckland')::date <= v_sheet.period_end))
  ORDER BY s.scheduled_start,s.id;
END $function$;
REVOKE ALL ON FUNCTION "public"."get_timesheet_break_review"(p_timesheet_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_timesheet_break_review"(p_timesheet_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_timesheet_break_review"(p_timesheet_id uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."get_timesheet_payroll_export"(p_batch_id uuid)
 RETURNS TABLE(timesheet_id uuid, staff_id uuid, period_start date, period_end date, payroll_snapshot jsonb)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_org uuid;
BEGIN
  SELECT organization_id INTO v_org FROM public.payroll_export_batches WHERE id=p_batch_id;
  IF NOT public.is_timesheet_payroll_admin(v_org) THEN
    RAISE EXCEPTION 'Active employer payroll administrator required' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY SELECT t.id,t.staff_id,t.period_start,t.period_end,t.payroll_snapshot
    FROM public.timesheets t WHERE t.organization_id=v_org AND t.payroll_export_batch_id=p_batch_id
    ORDER BY t.period_start,t.staff_id,t.id;
END $function$;
REVOKE ALL ON FUNCTION "public"."get_timesheet_payroll_export"(p_batch_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_timesheet_payroll_export"(p_batch_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_timesheet_payroll_export"(p_batch_id uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."get_user_sign_in_states"(p_user_ids uuid[])
 RETURNS TABLE(user_id uuid, sign_in_state text, last_sign_in_at timestamp with time zone, invited_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor public.user_profiles%rowtype;
BEGIN
  SELECT * INTO v_actor FROM public.user_profiles WHERE id = auth.uid() AND deactivated_at IS NULL;
  IF NOT FOUND OR v_actor.role NOT IN ('grand_master', 'master', 'admin', 'admin_officer', 'client_admin') THEN
    RAISE EXCEPTION 'Active identity administrator required';
  END IF;
  IF coalesce(cardinality(p_user_ids), 0) > 500 THEN RAISE EXCEPTION 'Request at most 500 people at a time'; END IF;

  RETURN QUERY
  SELECT target.id,
    CASE WHEN login.id IS NULL THEN 'no_login' WHEN login.last_sign_in_at IS NOT NULL THEN 'signed_in' ELSE 'invited' END,
    login.last_sign_in_at,
    coalesce(login.invited_at, login.confirmation_sent_at)
  FROM public.user_profiles target
  LEFT JOIN auth.users login ON login.id = target.id
  WHERE target.id = ANY(coalesce(p_user_ids, '{}'::uuid[]))
    AND (v_actor.role = 'grand_master' OR target.organization_id = v_actor.organization_id)
    AND (v_actor.role <> 'client_admin' OR target.role LIKE 'client\_%')
    AND public.identity_role_level(target.role) <= public.identity_role_level(v_actor.role);
END;
$function$;
REVOKE ALL ON FUNCTION "public"."get_user_sign_in_states"(p_user_ids uuid[]) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_user_sign_in_states"(p_user_ids uuid[]) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_user_sign_in_states"(p_user_ids uuid[]) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_user_sign_in_states"(p_user_ids uuid[]) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_user_spine_readiness"(p_organization_id uuid)
 RETURNS TABLE(user_id uuid, identity_status text, employment_status text, access_status text, credential_status text, work_status text, blockers text[], next_action text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_admin_for_org(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorised to assess users';
  END IF;

  RETURN QUERY
  SELECT
    u.id,
    CASE WHEN u.deactivated_at IS NOT NULL THEN 'deactivated' WHEN u.email IS NULL OR u.display_name IS NULL THEN 'incomplete' ELSE 'active' END,
    CASE
      WHEN u.role IN ('officer', 'admin_officer') AND sp.id IS NULL THEN 'missing'
      WHEN sp.id IS NULL THEN 'not_applicable'
      WHEN sp.end_date IS NOT NULL AND sp.end_date < current_date THEN 'ended'
      WHEN sp.employment_type IS NULL OR sp.start_date IS NULL OR sp.role_code IS NULL THEN 'incomplete'
      ELSE 'current'
    END,
    CASE
      WHEN u.role IN ('grand_master', 'master', 'admin', 'admin_officer')
        AND NOT EXISTS (
          SELECT 1 FROM public.preset_assignments pa
          WHERE pa.user_id = u.id
            AND pa.scope_org_id = u.organization_id
            AND pa.status = 'active'
        ) THEN 'missing_preset'
      ELSE 'role_scoped'
    END,
    CASE
      WHEN u.role IN ('officer', 'admin_officer')
        AND sp.id IS NOT NULL
        AND NOT EXISTS (
          SELECT 1 FROM public.staff_credentials c
          WHERE c.staff_id = sp.id
            AND c.verified
            AND (c.expiry_date IS NULL OR c.expiry_date >= current_date)
        ) THEN 'missing_valid'
      WHEN u.role IN ('officer', 'admin_officer') THEN 'current'
      ELSE 'not_applicable'
    END,
    CASE
      WHEN u.role IN ('officer', 'admin_officer') AND coalesce(sp.work_ready, false) THEN 'ready'
      WHEN u.role IN ('officer', 'admin_officer') THEN 'blocked'
      ELSE 'not_applicable'
    END,
    array_remove(ARRAY[
      CASE WHEN u.deactivated_at IS NOT NULL THEN 'Reactivate the identity before assigning work' END,
      CASE WHEN u.display_name IS NULL OR u.email IS NULL THEN 'Complete the identity profile' END,
      CASE WHEN u.role IN ('officer', 'admin_officer') AND sp.id IS NULL THEN 'Create the employment profile' END,
      CASE WHEN sp.id IS NOT NULL AND sp.employment_type IS NULL THEN 'Select an employment type' END,
      CASE WHEN sp.id IS NOT NULL AND sp.start_date IS NULL THEN 'Set an employment start date' END,
      CASE WHEN sp.id IS NOT NULL AND sp.role_code IS NULL THEN 'Assign a payroll role' END,
      CASE
        WHEN u.role IN ('grand_master', 'master', 'admin', 'admin_officer')
          AND NOT EXISTS (
            SELECT 1 FROM public.preset_assignments pa
            WHERE pa.user_id = u.id
              AND pa.scope_org_id = u.organization_id
              AND pa.status = 'active'
          ) THEN 'Assign an access preset'
      END,
      CASE
        WHEN u.role IN ('officer', 'admin_officer')
          AND sp.id IS NOT NULL
          AND NOT EXISTS (
            SELECT 1 FROM public.staff_credentials c
            WHERE c.staff_id = sp.id
              AND c.verified
              AND (c.expiry_date IS NULL OR c.expiry_date >= current_date)
          ) THEN 'Verify a current credential'
      END,
      CASE WHEN u.role IN ('officer', 'admin_officer') AND sp.id IS NOT NULL AND NOT sp.work_ready THEN 'Complete work-readiness review' END
    ], NULL),
    CASE
      WHEN u.deactivated_at IS NOT NULL THEN 'Reactivate identity'
      WHEN u.display_name IS NULL OR u.email IS NULL THEN 'Complete identity profile'
      WHEN u.role IN ('officer', 'admin_officer') AND sp.id IS NULL THEN 'Create employment profile'
      WHEN sp.id IS NOT NULL AND (sp.employment_type IS NULL OR sp.start_date IS NULL OR sp.role_code IS NULL) THEN 'Complete employment setup'
      WHEN u.role IN ('grand_master', 'master', 'admin', 'admin_officer')
        AND NOT EXISTS (
          SELECT 1 FROM public.preset_assignments pa
          WHERE pa.user_id = u.id
            AND pa.scope_org_id = u.organization_id
            AND pa.status = 'active'
        ) THEN 'Assign access preset'
      WHEN u.role IN ('officer', 'admin_officer')
        AND sp.id IS NOT NULL
        AND NOT EXISTS (
          SELECT 1 FROM public.staff_credentials c
          WHERE c.staff_id = sp.id
            AND c.verified
            AND (c.expiry_date IS NULL OR c.expiry_date >= current_date)
        ) THEN 'Verify credential'
      WHEN u.role IN ('officer', 'admin_officer') AND sp.id IS NOT NULL AND NOT sp.work_ready THEN 'Review work readiness'
      ELSE 'Ready for assigned responsibilities'
    END
  FROM public.user_profiles u
  LEFT JOIN public.staff_profiles sp ON sp.user_id = u.id OR sp.id = u.id
  WHERE u.organization_id = p_organization_id
  ORDER BY u.display_name NULLS LAST, u.email;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."get_user_spine_readiness"(p_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_user_spine_readiness"(p_organization_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_user_spine_readiness"(p_organization_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_user_spine_readiness"(p_organization_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_vehicle_identity_checks"(p_organization_id uuid, p_canonical_vehicle_id uuid)
 RETURNS TABLE(check_id uuid, checked_at timestamp with time zone, relationship text, person_record_id uuid, canonical_person_id uuid, display_name text, identity_document_id uuid, evidence_item_id uuid, source_authority text, vehicle_snapshot jsonb, storage_bucket text, storage_path text, file_name text, reviewed_at timestamp with time zone, revealed boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_revealed boolean;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_admin_for_org(p_organization_id) THEN
    RAISE EXCEPTION 'Identity registry administrator access required';
  END IF;
  v_revealed := public.can_access_vehicle_owner_identity(p_organization_id)
    AND public.nzta_reveal_active(ARRAY[p_organization_id], 'vehicle', p_canonical_vehicle_id);
  RETURN QUERY
  SELECT
    checks.id,
    checks.checked_at,
    checks.relationship,
    CASE WHEN v_revealed THEN checks.person_record_id END,
    CASE WHEN v_revealed THEN checks.canonical_person_id END,
    CASE WHEN v_revealed THEN person.display_name END,
    CASE WHEN v_revealed THEN checks.identity_document_id END,
    CASE WHEN v_revealed THEN checks.evidence_item_id END,
    checks.source_authority,
    CASE WHEN v_revealed THEN checks.vehicle_snapshot
      ELSE (SELECT coalesce(jsonb_object_agg(key, value), '{}'::jsonb)
            FROM jsonb_each(checks.vehicle_snapshot)
            WHERE key IN ('plate_number', 'vin', 'chassis_number', 'vehicle_make', 'vehicle_model',
              'vehicle_year', 'vehicle_colour', 'fuel_type', 'wof_expiry', 'rego_expiry',
              'query_completed_at', 'owner_only_review', 'vehicle_facts_review_state')) END,
    CASE WHEN v_revealed THEN attachment.storage_bucket END,
    CASE WHEN v_revealed THEN attachment.storage_path END,
    CASE WHEN v_revealed THEN attachment.file_name END,
    checks.reviewed_at,
    v_revealed
  FROM public.vehicle_identity_checks checks
  JOIN public.person_records person
    ON person.id = checks.person_record_id
   AND person.organization_id = checks.organization_id
  JOIN public.person_identity_documents document
    ON document.id = checks.identity_document_id
  LEFT JOIN public.bob_attachments attachment
    ON attachment.id = document.attachment_id
  WHERE checks.organization_id = p_organization_id
    AND checks.canonical_vehicle_id = p_canonical_vehicle_id
  ORDER BY checks.checked_at DESC, checks.reviewed_at DESC
  LIMIT 25;
END;
$function$;
COMMENT ON FUNCTION "public"."get_vehicle_identity_checks"(p_organization_id uuid, p_canonical_vehicle_id uuid) IS 'Administrator-only vehicle view of human-approved NZTA source-time checks. Person and private evidence paths are returned only with vehicle-owner authorisation and an open purpose-stated reveal.';
REVOKE ALL ON FUNCTION "public"."get_vehicle_identity_checks"(p_organization_id uuid, p_canonical_vehicle_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_vehicle_identity_checks"(p_organization_id uuid, p_canonical_vehicle_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_vehicle_identity_checks"(p_organization_id uuid, p_canonical_vehicle_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_vehicle_identity_checks"(p_organization_id uuid, p_canonical_vehicle_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_vehicle_owner_access"(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_target public.user_profiles%rowtype;
  v_direct public.staff_area_grants%rowtype;
  v_preset_level text;
BEGIN
  SELECT * INTO v_target FROM public.user_profiles WHERE id = p_user_id;
  IF v_target.id IS NULL OR auth.uid() IS NULL
     OR NOT public.is_admin_for_org(v_target.organization_id) THEN
    RAISE EXCEPTION 'Organisation administrator required';
  END IF;
  SELECT * INTO v_direct FROM public.staff_area_grants
  WHERE user_id = p_user_id AND scope_org_id = v_target.organization_id
    AND area = 'vehicle_owner_identity' AND status = 'active';
  SELECT max(grant_row.level) INTO v_preset_level
  FROM public.preset_assignments assignment
  JOIN public.access_presets preset ON preset.id = assignment.preset_id
  CROSS JOIN LATERAL jsonb_each_text(preset.grants) AS grant_row(area, level)
  WHERE assignment.user_id = p_user_id AND assignment.status = 'active'
    AND grant_row.area = 'vehicle_owner_identity'
    AND v_target.organization_id = ANY (public.get_descendant_organizations(assignment.scope_org_id));
  RETURN jsonb_build_object(
    'direct', v_direct.id IS NOT NULL,
    'direct_level', v_direct.level,
    'granted_at', v_direct.updated_at,
    'via_preset', v_preset_level IS NOT NULL,
    'via_role', v_target.role IN ('admin', 'admin_officer', 'master', 'grand_master'),
    'organization_id', v_target.organization_id
  ) || public.nzta_access_readiness(p_user_id, v_target.organization_id);
END;
$function$;
COMMENT ON FUNCTION "public"."get_vehicle_owner_access"(p_user_id uuid) IS 'Administrator view of whether a user holds the vehicle_owner_identity access area at their home organisation (direct grant, preset, or administrator role).';
REVOKE ALL ON FUNCTION "public"."get_vehicle_owner_access"(p_user_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_vehicle_owner_access"(p_user_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_vehicle_owner_access"(p_user_id uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."get_vehicle_owner_links"(p_organization_id uuid, p_canonical_vehicle_id uuid)
 RETURNS TABLE(link_id uuid, relationship text, active boolean, source text, basis text, nzta_restricted boolean, person_record_id uuid, canonical_person_id uuid, display_name text, phone text, email text, address text, locality text, observation_ids uuid[], details_visible boolean, recorded_at timestamp with time zone, recorded_by_name text, ended_at timestamp with time zone, source_checked_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_full boolean;
  v_contacts boolean;
  v_revealed boolean;
BEGIN
  IF auth.uid() IS NULL OR p_organization_id IS NULL OR NOT public.org_access_allowed(p_organization_id) THEN
    RAISE EXCEPTION 'Organization access required' USING ERRCODE = '42501';
  END IF;
  v_full := public.can_access_vehicle_owner_identity(p_organization_id);
  v_contacts := v_full AND public.can_access_person_contacts(p_organization_id);
  v_revealed := v_full AND public.nzta_reveal_active(ARRAY[p_organization_id], 'vehicle', p_canonical_vehicle_id);
  RETURN QUERY
  SELECT link.id, link.relationship, link.active, link.evidence->>'source',
    CASE WHEN v_contacts AND row_access.visible THEN link.evidence->>'basis' END,
    row_access.restricted,
    CASE WHEN row_access.visible THEN person_record.id END,
    CASE WHEN row_access.visible THEN link.from_id END,
    CASE WHEN row_access.visible THEN coalesce(person_record.display_name, canonical_person.display_name) END,
    CASE WHEN v_contacts AND row_access.visible THEN person_record.metadata->'profile_details'->>'phone' END,
    CASE WHEN v_contacts AND row_access.visible THEN person_record.metadata->'profile_details'->>'email' END,
    CASE WHEN v_contacts AND row_access.visible THEN person_record.metadata->'profile_details'->>'address' END,
    CASE WHEN v_contacts AND row_access.visible THEN public.vehicle_owner_locality(person_record.metadata->'profile_details') END,
    coalesce(ARRAY(
      SELECT (item #>> '{}')::uuid
      FROM jsonb_array_elements(coalesce(link.evidence->'observation_ids', '[]'::jsonb)) item
    ), ARRAY[]::uuid[]),
    row_access.visible, link.created_at, user_profile.display_name,
    CASE WHEN row_access.visible OR NOT (link.evidence ? 'nzta_owner_history_first_check_id') THEN link.ends_at END,
    CASE WHEN row_access.visible THEN nullif(link.evidence->>'source_checked_at', '')::timestamptz END
  FROM public.entity_links link
  CROSS JOIN LATERAL (
    SELECT coalesce((link.evidence->>'nzta_restricted')::boolean, false) AS restricted,
      v_full AND (NOT coalesce((link.evidence->>'nzta_restricted')::boolean, false) OR v_revealed) AS visible
  ) row_access
  LEFT JOIN public.person_records person_record
    ON person_record.id = (link.evidence->>'person_record_id')::uuid AND person_record.organization_id = link.organization_id
  LEFT JOIN public.canonical_people canonical_person ON canonical_person.id = link.from_id
  LEFT JOIN public.user_profiles user_profile ON user_profile.id = link.created_by
  WHERE link.organization_id = p_organization_id AND link.to_type = 'vehicle'
    AND link.to_id = p_canonical_vehicle_id AND link.from_type = 'person'
    AND link.relationship IN ('owner', 'registered_owner', 'driver', 'associated_person')
    AND NOT coalesce(link.evidence->>'superseded_by_reconciliation', 'false')::boolean
  ORDER BY link.active DESC, (link.relationship IN ('owner', 'registered_owner')) DESC, link.created_at DESC
  LIMIT 50;
END;
$function$;
COMMENT ON FUNCTION "public"."get_vehicle_owner_links"(p_organization_id uuid, p_canonical_vehicle_id uuid) IS 'Scoped vehicle-person links. NZTA-restricted links show identity only to vehicle-owner-authorised users with an open purpose-stated reveal for the vehicle. Private contact/address/locality and free-text basis also require operations administrator roles. Owner history remains source-time observations, never legal transfer dates.';
REVOKE ALL ON FUNCTION "public"."get_vehicle_owner_links"(p_organization_id uuid, p_canonical_vehicle_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_vehicle_owner_links"(p_organization_id uuid, p_canonical_vehicle_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_vehicle_owner_links"(p_organization_id uuid, p_canonical_vehicle_id uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."get_vehicle_subject_details_for_agreement"(p_plate text, p_service_agreement_id uuid)
 RETURNS TABLE(canonical_vehicle_id uuid, plate text, make text, model text, year integer, colour text, body_type text, fuel_type text, owner_identified boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_scope_orgs uuid[];
  v_plate text := upper(regexp_replace(coalesce(p_plate, ''), '[^A-Za-z0-9]', '', 'g'));
BEGIN
  v_scope_orgs := private.subject_scope_organizations(p_service_agreement_id);
  RETURN QUERY
  WITH places AS (
    SELECT l.zone_id, l.site_id FROM public.service_agreement_locations l
    WHERE l.service_agreement_id = p_service_agreement_id AND l.status = 'active'
  ), ids AS (
    SELECT o.canonical_vehicle_id id FROM public.observations o
    WHERE o.organization_id = ANY(v_scope_orgs)
      AND upper(regexp_replace(o.plate_number, '[^A-Za-z0-9]', '', 'g')) = v_plate
      AND (p_service_agreement_id IS NULL OR EXISTS (SELECT 1 FROM places p WHERE (p.zone_id IS NOT NULL AND p.zone_id = o.zone_id) OR (p.site_id IS NOT NULL AND p.site_id = o.site_id)))
    UNION
    SELECT c.canonical_vehicle_id FROM public.cctv_entity_observations c
    WHERE c.organization_id = ANY(v_scope_orgs) AND c.entity_kind = 'vehicle' AND c.review_state = 'accepted'
      AND upper(regexp_replace(coalesce(c.candidate_plate, ''), '[^A-Za-z0-9]', '', 'g')) = v_plate
      AND (p_service_agreement_id IS NULL OR EXISTS (SELECT 1 FROM places p WHERE (p.zone_id IS NOT NULL AND p.zone_id = c.zone_id) OR (p.site_id IS NOT NULL AND p.site_id = c.site_id)))
  )
  SELECT v.id, v.plate_number, v.make, v.model, v.year, v.colour, v.body_type, v.fuel_type,
    (v.registered_owner_name IS NOT NULL OR EXISTS (SELECT 1 FROM public.entity_links el WHERE el.to_type = 'vehicle' AND el.to_id = v.id AND el.from_type = 'person' AND el.active AND el.relationship IN ('owner', 'registered_owner') AND el.organization_id = ANY(v_scope_orgs)))
  FROM ids JOIN public.canonical_vehicles v ON v.id = ids.id
  ORDER BY v.last_seen_at DESC NULLS LAST LIMIT 1;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."get_vehicle_subject_details_for_agreement"(p_plate text, p_service_agreement_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_vehicle_subject_details_for_agreement"(p_plate text, p_service_agreement_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_vehicle_subject_details_for_agreement"(p_plate text, p_service_agreement_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_vehicle_subject_details_for_agreement"(p_plate text, p_service_agreement_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_website_page_view_summary"(p_from date, p_to date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_provider uuid;
BEGIN
  IF p_from IS NULL OR p_to IS NULL OR p_to < p_from OR p_to - p_from > 89 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'website_analytics_invalid:date_range';
  END IF;

  SELECT t.service_provider_organization_id
    INTO v_provider
    FROM private.platform_tenancy AS t
   WHERE t.singleton;

  IF auth.uid() IS NULL
     OR v_provider IS NULL
     OR NOT (public.is_grand_master() OR public.is_admin_for_org(v_provider)) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'website_analytics_access_denied';
  END IF;

  RETURN pg_catalog.jsonb_build_object(
    'total_page_views',
    coalesce((
      SELECT sum(v.page_views)
        FROM public.website_page_views_daily AS v
       WHERE v.provider_organization_id = v_provider
         AND v.viewed_on BETWEEN p_from AND p_to
    ), 0),
    'daily',
    coalesce((
      SELECT pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object('viewed_on', daily.viewed_on, 'page_views', daily.page_views)
        ORDER BY daily.viewed_on
      )
        FROM (
          SELECT v.viewed_on, sum(v.page_views) AS page_views
            FROM public.website_page_views_daily AS v
           WHERE v.provider_organization_id = v_provider
             AND v.viewed_on BETWEEN p_from AND p_to
           GROUP BY v.viewed_on
        ) AS daily
    ), '[]'::jsonb),
    'pages',
    coalesce((
      SELECT pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object('page_path', pages.page_path, 'page_views', pages.page_views)
        ORDER BY pages.page_views DESC, pages.page_path
      )
        FROM (
          SELECT v.page_path, sum(v.page_views) AS page_views
            FROM public.website_page_views_daily AS v
           WHERE v.provider_organization_id = v_provider
             AND v.viewed_on BETWEEN p_from AND p_to
           GROUP BY v.page_path
        ) AS pages
    ), '[]'::jsonb),
    'regions',
    coalesce((
      SELECT pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'country_code', regions.country_code,
          'region_code', regions.region_code,
          'page_views', regions.page_views
        )
        ORDER BY regions.page_views DESC, regions.country_code, regions.region_code
      )
        FROM (
          SELECT v.country_code, v.region_code, sum(v.page_views) AS page_views
            FROM public.website_page_views_daily AS v
           WHERE v.provider_organization_id = v_provider
             AND v.viewed_on BETWEEN p_from AND p_to
             AND v.country_code <> 'ZZ'
             AND v.region_code <> 'ZZ'
           GROUP BY v.country_code, v.region_code
          HAVING sum(v.page_views) >= 5
        ) AS regions
    ), '[]'::jsonb)
  );
END;
$function$;
REVOKE ALL ON FUNCTION "public"."get_website_page_view_summary"(p_from date, p_to date) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_website_page_view_summary"(p_from date, p_to date) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_website_page_view_summary"(p_from date, p_to date) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."grant_branch_area_access"(p_operating_organization_id uuid, p_user_id uuid, p_area text, p_level text, p_reason text)
 RETURNS staff_area_grants
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_grant public.staff_area_grants%rowtype;v_reason text:=nullif(trim(coalesce(p_reason,'')), '');
begin
  if v_reason is null then raise exception 'A change reason is required';end if;
  if p_area not in('timesheet_local_review','leave_branch_approve','roster_impact_approve','credentials_supervise','hr_case_local_investigate','incident_manage_local') then raise exception 'Unsupported branch authority area';end if;
  if p_level not in('view','verify','approve','adjust','manage') then raise exception 'Unsupported access level';end if;
  if p_user_id=v_actor then raise exception 'You cannot grant yourself branch authority';end if;
  if not public.user_can_operate_organization(p_operating_organization_id) or not public.staff_branch_authorisation_manager_can_manage(v_actor,p_operating_organization_id,p_user_id) then raise exception 'Not authorised to grant branch authority';end if;
  if not exists(select 1 from public.staff_branch_authorisations assignment where assignment.user_id=p_user_id and assignment.branch_org_id=p_operating_organization_id and assignment.status='active') then raise exception 'Active staff branch authorization required';end if;
  select * into v_grant from public.staff_area_grants where user_id=p_user_id and scope_org_id=p_operating_organization_id and area=p_area and status='active' for update;
  if found then raise exception 'An active grant already exists for this area';end if;
  insert into public.staff_area_grants(user_id,scope_org_id,area,level,status,source_preset,granted_by) values(p_user_id,p_operating_organization_id,p_area,p_level,'active',null,v_actor) returning * into v_grant;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)values(p_operating_organization_id,v_actor,'branch_area_grant_created','staff_area_grants',v_grant.id,jsonb_build_object('user_id',p_user_id,'area',p_area,'level',p_level,'reason',v_reason));
  return v_grant;
end;$function$;
REVOKE ALL ON FUNCTION "public"."grant_branch_area_access"(p_operating_organization_id uuid, p_user_id uuid, p_area text, p_level text, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."grant_branch_area_access"(p_operating_organization_id uuid, p_user_id uuid, p_area text, p_level text, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."grant_branch_area_access"(p_operating_organization_id uuid, p_user_id uuid, p_area text, p_level text, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."grant_branch_area_access"(p_operating_organization_id uuid, p_user_id uuid, p_area text, p_level text, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."guard_dispatch_job_billing_basis"()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF coalesce(current_setting('fcm.dispatch_billing_rpc', true), '') = 'on' AND current_user NOT IN ('anon', 'authenticated') THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.billing_basis IS NOT NULL OR NEW.extra_work_order_id IS NOT NULL OR NEW.billing_basis_set_at IS NOT NULL OR NEW.billing_basis_set_by IS NOT NULL THEN
      RAISE EXCEPTION 'Dispatch billing basis is set through set_dispatch_job_billing_basis';
    END IF;
    IF NEW.client_order_reference IS NOT NULL THEN
      RAISE EXCEPTION 'The client reference is set through set_dispatch_job_client_reference';
    END IF;
  ELSE
    IF NEW.billing_basis IS DISTINCT FROM OLD.billing_basis
       OR NEW.extra_work_order_id IS DISTINCT FROM OLD.extra_work_order_id
       OR NEW.billing_basis_set_at IS DISTINCT FROM OLD.billing_basis_set_at
       OR NEW.billing_basis_set_by IS DISTINCT FROM OLD.billing_basis_set_by THEN
      RAISE EXCEPTION 'Dispatch billing basis is set through set_dispatch_job_billing_basis';
    END IF;
    IF NEW.client_order_reference IS DISTINCT FROM OLD.client_order_reference THEN
      RAISE EXCEPTION 'The client reference is set through set_dispatch_job_client_reference';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."guard_dispatch_job_billing_basis"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."guard_dispatch_job_billing_basis"() TO "postgres";

CREATE OR REPLACE FUNCTION "public"."guard_field_verification_point"()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF OLD.is_verification_point THEN
    IF NOT NEW.is_verification_point OR jsonb_typeof(NEW.metadata->'field_capture') IS DISTINCT FROM 'object' THEN
      RAISE EXCEPTION 'Keep the field verification provenance. Edit the surrounding site or area instead';
    END IF;
    IF NEW.metadata->'field_capture' IS NOT DISTINCT FROM OLD.metadata->'field_capture'
      AND (NEW.boundary IS DISTINCT FROM OLD.boundary OR NEW.center_point IS DISTINCT FROM OLD.center_point
        OR NEW.radius_meters IS DISTINCT FROM OLD.radius_meters
        OR NEW.boundary_verification IS DISTINCT FROM OLD.boundary_verification
        OR NEW.boundary_verified_by IS DISTINCT FROM OLD.boundary_verified_by
        OR NEW.boundary_verified_at IS DISTINCT FROM OLD.boundary_verified_at
        OR NEW.is_active IS DISTINCT FROM OLD.is_active
        OR NEW.location_id IS DISTINCT FROM OLD.location_id OR NEW.parent_zone_id IS DISTINCT FROM OLD.parent_zone_id) THEN
      RAISE EXCEPTION 'Use Places to capture and confirm a new verification point; edit the surrounding perimeter separately';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."guard_field_verification_point"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."guard_field_verification_point"() TO "postgres";

CREATE OR REPLACE FUNCTION "public"."guard_shift_break_lifecycle"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if new.status = 'completed' and old.status is distinct from new.status
    and exists(select 1 from public.shift_breaks where shift_id = new.id and ended_at is null) then
    raise exception 'Finish the open break before completing this shift';
  end if;
  return new;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."guard_shift_break_lifecycle"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."guard_shift_break_lifecycle"() TO "postgres";

CREATE OR REPLACE FUNCTION "public"."guard_timesheet_payroll_evidence"()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE v_pay record;
BEGIN
  IF TG_OP='UPDATE' THEN
    NEW.revision := OLD.revision+1;
    IF OLD.payroll_snapshot IS NOT NULL AND NEW.payroll_snapshot IS DISTINCT FROM OLD.payroll_snapshot THEN
      RAISE EXCEPTION 'Exported payroll evidence is immutable';
    END IF;
    IF OLD.payroll_snapshot IS NOT NULL AND
      ROW(NEW.staff_id,NEW.organization_id,NEW.period_start,NEW.period_end,NEW.actual_hours,
        NEW.overtime_hours,NEW.pay_code_override,NEW.hourly_rate_override,NEW.payroll_export_batch_id,NEW.status)
      IS DISTINCT FROM
      ROW(OLD.staff_id,OLD.organization_id,OLD.period_start,OLD.period_end,OLD.actual_hours,
        OLD.overtime_hours,OLD.pay_code_override,OLD.hourly_rate_override,OLD.payroll_export_batch_id,OLD.status) THEN
      RAISE EXCEPTION 'Exported payroll values are immutable';
    END IF;
    IF current_user NOT IN ('postgres','service_role') AND
      (NEW.recovery_request IS DISTINCT FROM OLD.recovery_request
       OR NEW.pay_code_override IS DISTINCT FROM OLD.pay_code_override
       OR NEW.hourly_rate_override IS DISTINCT FROM OLD.hourly_rate_override
       OR NEW.pay_override_reason IS DISTINCT FROM OLD.pay_override_reason
       OR NEW.payroll_snapshot IS DISTINCT FROM OLD.payroll_snapshot) THEN
      RAISE EXCEPTION 'Use the governed payroll correction RPC';
    END IF;
    IF (NEW.recovery_request IS NOT NULL OR NEW.pay_override_reason IS NOT NULL)
      AND NEW.status='approved' AND OLD.status IS DISTINCT FROM 'approved' THEN
      IF OLD.status<>'branch_checked' OR NEW.branch_reviewed_by IS NULL
        OR NEW.branch_reviewed_by IS NOT DISTINCT FROM NEW.approved_by
        OR NEW.approved_by IS DISTINCT FROM auth.uid()
        OR NOT public.is_timesheet_payroll_admin(NEW.organization_id) THEN
        RAISE EXCEPTION 'Manual payroll evidence requires branch check and a different corporate final reviewer';
      END IF;
    END IF;
    IF NEW.status='paid' AND OLD.status='approved' THEN
      IF NOT public.is_timesheet_payroll_admin(NEW.organization_id) THEN
        RAISE EXCEPTION 'Active employer payroll administrator required' USING ERRCODE='42501';
      END IF;
      SELECT * INTO v_pay FROM public.timesheet_effective_pay(OLD.id);
      IF NOT FOUND OR v_pay.hourly_rate IS NULL OR v_pay.hourly_rate<0 OR v_pay.hourly_rate>100000
        OR v_pay.hourly_rate='NaN'::numeric OR nullif(btrim(v_pay.pay_code),'') IS NULL THEN
        RAISE EXCEPTION 'Resolve the hourly pay rate and pay code before payroll export';
      END IF;
      NEW.payroll_snapshot := jsonb_build_object('pay_code',v_pay.pay_code,'hourly_rate',v_pay.hourly_rate,
        'rate_rule_id',v_pay.rate_rule_id,'hours',NEW.actual_hours,'overtime_hours',NEW.overtime_hours,
        'gross_amount',round(NEW.actual_hours*v_pay.hourly_rate,2),'override_reason',NEW.pay_override_reason,
        'evidence_kind',coalesce(NEW.work_summary->>'evidence_kind','officer_work'),
        'exported_at',clock_timestamp());
    END IF;
  ELSIF current_user NOT IN ('postgres','service_role') AND
    (NEW.recovery_request IS NOT NULL OR NEW.pay_code_override IS NOT NULL OR NEW.hourly_rate_override IS NOT NULL
      OR NEW.pay_override_reason IS NOT NULL OR NEW.payroll_snapshot IS NOT NULL) THEN
    RAISE EXCEPTION 'Use the governed payroll recovery RPC';
  END IF;
  RETURN NEW;
END $function$;
REVOKE ALL ON FUNCTION "public"."guard_timesheet_payroll_evidence"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."guard_timesheet_payroll_evidence"() TO "postgres";

CREATE OR REPLACE FUNCTION "public"."has_location_access"(p_site_id uuid, p_zone_id uuid, p_direction text DEFAULT 'provider_reads_client'::text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select public.is_grand_master()
    or (p_site_id is not null and exists (select 1 from public.client_sites site where site.id = p_site_id and public.org_access_allowed(site.client_organization_id)))
    or (p_zone_id is not null and exists (select 1 from public.location_zones zone where zone.id = p_zone_id and public.org_access_allowed(zone.organization_id)))
    or (p_direction = 'provider_reads_client' and exists (
      select 1 from public.service_agreement_locations location
      join public.service_agreements agreement on agreement.id = location.service_agreement_id
      where location.status = 'active' and agreement.agreement_type = 'operational'
        and (location.site_id = p_site_id or location.zone_id = p_zone_id)
        and public.org_access_allowed(agreement.provider_organization_id)
    ))
    or (p_direction = 'client_reads_provider' and exists (
      select 1 from public.service_agreement_locations location
      join public.service_agreements agreement on agreement.id = location.service_agreement_id
      where location.status = 'active' and agreement.agreement_type = 'operational' and agreement.invitation_status = 'accepted'
        and (location.site_id = p_site_id or location.zone_id = p_zone_id)
        and public.org_access_allowed(agreement.client_organization_id)
    ))
    or exists (
      select 1 from public.service_agreement_locations location
      join public.service_agreements agreement on agreement.id = location.service_agreement_id
      where location.status = 'active' and agreement.agreement_type = 'operational'
        and (location.site_id = p_site_id or location.zone_id = p_zone_id)
        and location.head_contractor_org_id is not null and public.org_access_allowed(location.head_contractor_org_id)
    );
$function$;
COMMENT ON FUNCTION "public"."has_location_access"(p_site_id uuid, p_zone_id uuid, p_direction text) IS 'Returns true when the calling user''s org has access to a location (site or zone), either by ownership, via an active service_agreement_locations row, or as a head contractor with subcontracted work at the location. Direction controls cross-org read: provider_reads_client (provider reads client location data) or client_reads_provider (client reads Tier 1 operational results at their location). QA gaps G1+G2 from epic #179; head-contractor visibility from epic #203 R2 #205.';
REVOKE ALL ON FUNCTION "public"."has_location_access"(p_site_id uuid, p_zone_id uuid, p_direction text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."has_location_access"(p_site_id uuid, p_zone_id uuid, p_direction text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."has_location_access"(p_site_id uuid, p_zone_id uuid, p_direction text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."has_location_access"(p_site_id uuid, p_zone_id uuid, p_direction text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."heartbeat_cctv_inference_job"(p_job_id uuid, p_lease_token uuid, p_stage text, p_lease_seconds integer DEFAULT 900)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.role() <> 'service_role' AND session_user <> 'postgres' THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;
  UPDATE public.inference_jobs
     SET stage = COALESCE(NULLIF(trim(p_stage), ''), stage), heartbeat_at = clock_timestamp(),
         lease_expires_at = clock_timestamp() + make_interval(secs => p_lease_seconds)
   WHERE id = p_job_id AND status = 'processing' AND lease_token = p_lease_token;
  RETURN FOUND;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."heartbeat_cctv_inference_job"(p_job_id uuid, p_lease_token uuid, p_stage text, p_lease_seconds integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."heartbeat_cctv_inference_job"(p_job_id uuid, p_lease_token uuid, p_stage text, p_lease_seconds integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."heartbeat_cctv_inference_job"(p_job_id uuid, p_lease_token uuid, p_stage text, p_lease_seconds integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."identity_actor_can_admin"(p_actor_user_id uuid, p_organization_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS(
    SELECT 1 FROM public.user_profiles profile
    WHERE profile.id=p_actor_user_id AND profile.deactivated_at IS NULL
      AND profile.role IN ('grand_master','master','admin', 'admin_officer')
      AND (profile.role='grand_master'
        OR (profile.role='master' AND (p_organization_id=ANY(public.get_descendant_organizations(profile.employer_organization_id))
          OR p_organization_id=ANY(public.get_descendant_organizations(profile.organization_id))
          OR EXISTS(SELECT 1 FROM public.service_agreements agreement WHERE agreement.agreement_type='operational'
            AND (agreement.ends_on IS NULL OR agreement.ends_on>=current_date)
            AND agreement.client_organization_id=p_organization_id
            AND (profile.organization_id=agreement.provider_organization_id OR profile.employer_organization_id=agreement.provider_organization_id))))
        OR (profile.role IN ('admin', 'admin_officer') AND (profile.organization_id=p_organization_id
          OR p_organization_id=ANY(public.get_descendant_organizations(profile.organization_id))
          OR EXISTS(SELECT 1 FROM public.service_agreements agreement WHERE agreement.agreement_type='operational'
            AND (agreement.ends_on IS NULL OR agreement.ends_on>=current_date)
            AND agreement.client_organization_id=p_organization_id
            AND (profile.organization_id=agreement.provider_organization_id OR profile.employer_organization_id=agreement.provider_organization_id)))))
  ) OR EXISTS(
      SELECT 1 FROM public.user_profiles profile
      JOIN public.incidents incident ON incident.officer_user_id=profile.id
      WHERE profile.id=p_actor_user_id AND profile.deactivated_at IS NULL
        AND profile.role IN ('officer','admin_officer') AND incident.organization_id=p_organization_id
        AND incident.status IN ('open','in_review','escalated')
    )
$function$;
REVOKE ALL ON FUNCTION "public"."identity_actor_can_admin"(p_actor_user_id uuid, p_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."identity_actor_can_admin"(p_actor_user_id uuid, p_organization_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."identity_actor_can_admin"(p_actor_user_id uuid, p_organization_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."identity_role_level"(p_role text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case p_role when 'grand_master' then 6 when 'master' then 5 when 'admin' then 4 when 'admin_officer' then 4 when 'officer' then 2 when 'scan_operator' then 2 when 'nzscv_monitor' then 1 when 'client_admin' then 1 when 'client_officer' then 1 when 'client_viewer' then 1 else 0 end;
$function$;
REVOKE ALL ON FUNCTION "public"."identity_role_level"(p_role text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."identity_role_level"(p_role text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."identity_role_level"(p_role text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."import_approved_freedom_places"(p_places jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid(); v_place jsonb; v_client uuid; v_provider uuid; v_agreement uuid; v_location uuid; v_site uuid; v_zone uuid; v_geojson jsonb; v_created jsonb := '[]'::jsonb;
BEGIN
  IF NOT has_table_privilege(current_user, 'public.locations', 'INSERT') THEN RAISE EXCEPTION 'Service role table privilege required'; END IF;
  IF jsonb_typeof(p_places) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Places must be a JSON array'; END IF;
  FOR v_place IN SELECT value FROM jsonb_array_elements(p_places) LOOP
    v_client := (v_place->>'client_organization_id')::uuid; v_provider := (v_place->>'provider_organization_id')::uuid; v_agreement := (v_place->>'service_agreement_id')::uuid;
    IF v_client IS NULL OR v_provider IS NULL OR v_agreement IS NULL THEN RAISE EXCEPTION 'Client, provider, and agreement are required'; END IF;
    IF NOT EXISTS (SELECT 1 FROM public.service_agreements WHERE id=v_agreement AND provider_organization_id=v_provider AND client_organization_id=v_client) THEN RAISE EXCEPTION 'Agreement does not bind the supplied organizations'; END IF;
    v_geojson := v_place->'geojson'; IF v_geojson IS NULL OR v_geojson->>'type' NOT IN ('Polygon','MultiPolygon') THEN RAISE EXCEPTION 'Approved place geometry must be Polygon or MultiPolygon'; END IF;
    SELECT id INTO v_location FROM public.locations WHERE organization_id=v_client AND lower(name)=lower(v_place->>'location_name') ORDER BY created_at LIMIT 1;
    IF v_location IS NULL THEN
      INSERT INTO public.locations(organization_id,name,address,notes,created_by) VALUES(v_client,v_place->>'location_name',NULL,'Imported from approved Freedom Camping jurisdiction source. Source project: '||coalesce(v_place->>'source_project','unknown')||'; source id: '||coalesce(v_place->>'source_id','unknown'),v_actor) RETURNING id INTO v_location;
    END IF;
    INSERT INTO public.client_sites(client_organization_id,organization_id,location_id,name,address,active,site_origin,ownership_status,ownership_signals,boundary,boundary_status,boundary_verification,boundary_verified_by,boundary_verified_at,external_refs) VALUES(v_client,v_client,v_location,v_place->>'site_name',NULL,true,'contracted','resolved',jsonb_build_object('source','FreedomCamp-Manager','approval','user_directed_live_import'),ST_GeomFromGeoJSON(v_geojson::text),'authoritative','verified',v_actor,clock_timestamp(),jsonb_build_object('source_project',v_place->>'source_project','source_id',v_place->>'source_id','source_sha256',v_place->>'source_sha256')) ON CONFLICT DO NOTHING RETURNING id INTO v_site;
    IF v_site IS NULL THEN SELECT id INTO v_site FROM public.client_sites WHERE client_organization_id=v_client AND location_id=v_location AND name=v_place->>'site_name' ORDER BY created_at DESC LIMIT 1; END IF;
    INSERT INTO public.location_zones(organization_id,location_id,name,zone_type,module_key,is_active,boundary,boundary_verification,boundary_status,boundary_verified_by,boundary_verified_at,metadata,bylaw_clause,nightly_limit_consecutive,nightly_limit_monthly,scv_required) VALUES(v_client,v_location,v_place->>'zone_name',coalesce(v_place->>'zone_type','freedom_camping'),v_place->>'module_key',true,ST_Multi(ST_GeomFromGeoJSON(v_geojson::text)),'verified','authoritative',v_actor,clock_timestamp(),jsonb_build_object('source_project',v_place->>'source_project','source_id',v_place->>'source_id','source_sha256',v_place->>'source_sha256','source_policy',v_place->'policy'),(v_place->'policy'->>'bylaw_clause'),(v_place->'policy'->>'nightly_limit_consecutive')::integer,(v_place->'policy'->>'nightly_limit_monthly')::integer,coalesce((v_place->'policy'->>'scv_required')::boolean,false)) ON CONFLICT DO NOTHING RETURNING id INTO v_zone;
    IF v_zone IS NULL THEN SELECT id INTO v_zone FROM public.location_zones WHERE organization_id=v_client AND location_id=v_location AND name=v_place->>'zone_name' ORDER BY created_at DESC LIMIT 1; END IF;
    INSERT INTO public.service_agreement_locations(service_agreement_id,zone_id,status,created_by) VALUES(v_agreement,v_zone,'active',v_actor) ON CONFLICT DO NOTHING;
    v_created := v_created || jsonb_build_object('location_id',v_location,'site_id',v_site,'zone_id',v_zone,'agreement_id',v_agreement,'source_id',v_place->>'source_id');
  END LOOP;
  INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) VALUES((p_places->0->>'provider_organization_id')::uuid,v_actor,'freedom_places_imported','service_agreement_locations',NULL,jsonb_build_object('count',jsonb_array_length(p_places),'source_project',p_places->0->>'source_project','approval','user_directed_live_import'));
  RETURN v_created;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."import_approved_freedom_places"(p_places jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."import_approved_freedom_places"(p_places jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."import_approved_freedom_places"(p_places jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."import_historical_patrol_labour_slots"(p_organization_id uuid, p_client_request_id uuid, p_report_fingerprint text, p_slots jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_receipt jsonb;
  v_route uuid;
  v_unit uuid;
  v_slot jsonb;
  v_existing record;
  v_staff uuid;
  v_client uuid;
  v_start timestamptz;
  v_end timestamptz;
  v_hours numeric;
  v_key text;
  v_inserted integer := 0;
  v_unchanged integer := 0;
  v_changed jsonb := '[]'::jsonb;
  v_units jsonb := '{}'::jsonb;
begin
  if v_actor is null or not public.is_admin_for_org(p_organization_id) then
    raise exception 'Not authorised to import historical labour for this organization';
  end if;
  if p_client_request_id is null or coalesce(p_report_fingerprint, '') !~ '^[0-9a-f]{64}$' then
    raise exception 'A request ID and the planner report fingerprint are required';
  end if;
  if jsonb_typeof(p_slots) is distinct from 'array' or jsonb_array_length(p_slots) = 0 or jsonb_array_length(p_slots) > 1000 then
    raise exception 'Between 1 and 1000 slots are required per request';
  end if;

  select metadata into v_receipt from public.audit_log
  where organization_id = p_organization_id and action = 'historical_patrol_labour_imported'
    and metadata->>'client_request_id' = p_client_request_id::text
  limit 1;
  if found then return v_receipt || jsonb_build_object('replayed', true); end if;

  select id into v_route from public.patrol_routes
  where organization_id = p_organization_id and route_code = 'RM-PATROL-LOG-HISTORICAL';
  if v_route is null then
    insert into public.patrol_routes(organization_id, name, route_code, description, route_type, checkpoint_mode, assignment_type, is_active)
    values (p_organization_id, 'Patrol log labour (historical)', 'RM-PATROL-LOG-HISTORICAL',
      'Holds historical patrol-log labour imported into the roster. Not used for live patrols.', 'patrol', 'none', 'client_patrol', false)
    returning id into v_route;
  end if;

  perform set_config('fcm.historical_labour_import', 'on', true);

  for v_slot in select value from jsonb_array_elements(p_slots) loop
    v_key := v_slot->>'source_key';
    begin
      v_staff := (v_slot->>'staff_id')::uuid;
      v_client := (v_slot->>'client_organization_id')::uuid;
      v_start := (v_slot->>'scheduled_start')::timestamptz;
      v_end := (v_slot->>'scheduled_end')::timestamptz;
      v_hours := (v_slot->>'recorded_hours')::numeric;
    exception when others then
      raise exception 'Slot % has malformed fields', coalesce(v_key, '(no source key)');
    end;
    if v_key is null or v_key !~ '^rm_patrol_log_labour:' or v_staff is null or v_client is null
       or coalesce(v_slot->>'source_fingerprint', '') !~ '^[0-9a-f]{64}$'
       or jsonb_typeof(v_slot->'source_records') is distinct from 'array' or jsonb_array_length(v_slot->'source_records') = 0 then
      raise exception 'Slot % is missing its source identity', coalesce(v_key, '(no source key)');
    end if;
    if v_start >= v_end or v_end > now() or v_end - v_start > interval '24 hours'
       or abs(extract(epoch from (v_end - v_start)) - v_hours * 3600) > 1 then
      raise exception 'Slot % has an invalid or future time window', v_key;
    end if;
    if not exists (select 1 from public.staff_profiles where id = v_staff and organization_id = p_organization_id) then
      raise exception 'Slot % names a staff member outside this organization', v_key;
    end if;

    select id, external_refs into v_existing from public.roster_slots
    where organization_id = p_organization_id and external_refs->>'source' = 'rm_patrol_log_labour'
      and external_refs->>'source_key' = v_key;
    if found then
      if v_existing.external_refs->>'source_fingerprint' = v_slot->>'source_fingerprint' then
        v_unchanged := v_unchanged + 1;
      else
        v_changed := v_changed || jsonb_build_object('slot_id', v_existing.id, 'source_key', v_key);
      end if;
      continue;
    end if;

    if exists (
      select 1 from public.roster_slots other
      where other.organization_id = p_organization_id and other.staff_id = v_staff
        and other.status not in ('declined', 'cancelled')
        and tstzrange(other.scheduled_start, other.scheduled_end, '[)') && tstzrange(v_start, v_end, '[)')
    ) then
      raise exception 'Slot % overlaps an existing roster slot for the same staff member', v_key;
    end if;

    v_unit := (v_units->>v_client::text)::uuid;
    if v_unit is null then
      select id into v_unit from public.roster_work_units
      where organization_id = p_organization_id and external_refs->>'source' = 'rm_patrol_log_labour'
        and external_refs->>'client_organization_id' = v_client::text;
      if v_unit is null then
        insert into public.roster_work_units(organization_id, name, work_unit_type, service_type, patrol_route_id, created_by, external_refs)
        select p_organization_id, 'Patrol log - ' || coalesce(o.name, v_client::text), 'patrol', 'patrol', v_route, v_actor,
          jsonb_build_object('source', 'rm_patrol_log_labour', 'client_organization_id', v_client, 'historical_only', true)
        from (select v_client as id) c left join public.organizations o on o.id = c.id
        returning id into v_unit;
      end if;
      v_units := v_units || jsonb_build_object(v_client::text, v_unit);
    end if;

    insert into public.roster_slots(organization_id, work_unit_id, staff_id, scheduled_start, scheduled_end, status,
      client_request_id, notes, created_by, external_refs)
    values (p_organization_id, v_unit, v_staff, v_start, v_end, 'completed',
      md5('rm_patrol_log_labour|' || v_key)::uuid,
      'Historical patrol-log labour: ' || v_hours || 'h summed from ' || jsonb_array_length(v_slot->'source_records')
        || ' log entries. Start time is approximate.',
      v_actor,
      jsonb_build_object('source', 'rm_patrol_log_labour', 'source_key', v_key,
        'source_fingerprint', v_slot->>'source_fingerprint', 'report_fingerprint', p_report_fingerprint,
        'client_organization_id', v_client, 'work_date', v_slot->>'work_date', 'recorded_hours', v_hours,
        'pay_code', 'FORESTRY-PATROL', 'time_precision', 'summed_hours_anchored_to_first_entry',
        'source_records', v_slot->'source_records', 'imported_request_id', p_client_request_id));
    v_inserted := v_inserted + 1;
  end loop;

  perform set_config('fcm.historical_labour_import', 'off', true);

  v_receipt := jsonb_build_object('client_request_id', p_client_request_id, 'report_fingerprint', p_report_fingerprint,
    'submitted', jsonb_array_length(p_slots), 'inserted', v_inserted, 'unchanged', v_unchanged,
    'changed_source', v_changed, 'work_units', v_units);
  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (p_organization_id, v_actor, 'historical_patrol_labour_imported', 'roster_slots', null, v_receipt);
  return v_receipt;
end;
$function$;
COMMENT ON FUNCTION "public"."import_historical_patrol_labour_slots"(p_organization_id uuid, p_client_request_id uuid, p_report_fingerprint text, p_slots jsonb) IS 'Admin-only, idempotent import of planner-approved historical patrol-log labour as completed roster slots. Changed source fingerprints are reported, never overwritten.';
REVOKE ALL ON FUNCTION "public"."import_historical_patrol_labour_slots"(p_organization_id uuid, p_client_request_id uuid, p_report_fingerprint text, p_slots jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."import_historical_patrol_labour_slots"(p_organization_id uuid, p_client_request_id uuid, p_report_fingerprint text, p_slots jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."import_historical_patrol_labour_slots"(p_organization_id uuid, p_client_request_id uuid, p_report_fingerprint text, p_slots jsonb) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."import_historical_patrol_labour_slots"(p_organization_id uuid, p_client_request_id uuid, p_report_fingerprint text, p_slots jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."import_human_authored_trespass_notice"(p_organization_id uuid, p_subject_display_name text, p_issued_at timestamp with time zone, p_status text, p_source_document_name text, p_source_reference text, p_source_sha256 text, p_import_key text, p_narrative text DEFAULT NULL::text, p_source_author text DEFAULT NULL::text, p_notice_number text DEFAULT NULL::text, p_legal_basis text DEFAULT NULL::text, p_location_id uuid DEFAULT NULL::uuid, p_site_id uuid DEFAULT NULL::uuid, p_zone_id uuid DEFAULT NULL::uuid, p_source_locator text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_subject text := nullif(trim(coalesce(p_subject_display_name, '')), '');
  v_hash text := lower(nullif(trim(coalesce(p_source_sha256, '')), ''));
  v_key text := nullif(trim(coalesce(p_import_key, '')), '');
  v_notice public.notices%rowtype;
  v_person_record_id uuid;
  v_canonical_person_id uuid;
  v_observation_id uuid;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_organization_id IS NULL OR NOT public.org_access_allowed(p_organization_id) THEN
    RAISE EXCEPTION 'Not permitted to import records for this organization';
  END IF;
  IF v_subject IS NULL THEN RAISE EXCEPTION 'Subject display name is required'; END IF;
  IF p_issued_at IS NULL THEN RAISE EXCEPTION 'Issued date is required'; END IF;
  IF p_status NOT IN ('draft', 'issued', 'withdrawn') THEN
    RAISE EXCEPTION 'Unsupported historical notice status %', p_status;
  END IF;
  IF nullif(trim(coalesce(p_source_document_name, '')), '') IS NULL
    OR nullif(trim(coalesce(p_source_reference, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Source document name and governed source reference are required';
  END IF;
  IF v_hash IS NULL OR v_hash !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'A SHA-256 source hash is required';
  END IF;
  IF v_key IS NULL THEN RAISE EXCEPTION 'A deterministic import key is required'; END IF;
  IF p_location_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.locations l
    WHERE l.id = p_location_id AND l.organization_id = p_organization_id
  ) THEN RAISE EXCEPTION 'Location is not owned by the target organization'; END IF;
  IF p_site_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.client_sites s
    WHERE s.id = p_site_id AND s.client_organization_id = p_organization_id
  ) THEN RAISE EXCEPTION 'Site is not owned by the target organization'; END IF;
  IF p_zone_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.location_zones z
    WHERE z.id = p_zone_id AND z.organization_id = p_organization_id
  ) THEN RAISE EXCEPTION 'Zone is not owned by the target organization'; END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(
    p_organization_id::text || ':trespass:' || v_key,
    0
  ));

  SELECT * INTO v_notice
  FROM public.notices n
  WHERE n.organization_id = p_organization_id
    AND n.import_key = v_key;

  IF v_notice.id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'notice_id', v_notice.id,
      'observation_id', v_notice.observation_id,
      'canonical_person_id', v_notice.person_id,
      'inserted', false
    );
  END IF;

  INSERT INTO public.person_records (
    organization_id,
    display_name,
    review_state,
    metadata
  ) VALUES (
    p_organization_id,
    v_subject,
    'manual_review_required',
    jsonb_strip_nulls(jsonb_build_object(
      'created_from', 'human_authored_trespass_notice',
      'source_document_name', trim(p_source_document_name),
      'source_reference', trim(p_source_reference),
      'source_sha256', v_hash,
      'source_identity_scope', v_key
    ))
  )
  RETURNING id INTO v_person_record_id;

  v_canonical_person_id := public.ensure_canonical_person_for_record(v_person_record_id);

  INSERT INTO public.observations (
    organization_id,
    officer_id,
    plate_number,
    location_id,
    site_id,
    zone_id,
    observed_at,
    module_key,
    plate_source,
    officer_notes,
    compliance_status,
    person_record_id,
    canonical_person_id,
    subject_kind,
    reported_by_name,
    source_document_name,
    source_reference,
    source_sha256,
    source_locator,
    import_key,
    external_refs
  ) VALUES (
    p_organization_id,
    NULL,
    NULL,
    p_location_id,
    p_site_id,
    p_zone_id,
    p_issued_at,
    'security_operations',
    'historical_import',
    coalesce(
      nullif(trim(coalesce(p_narrative, '')), ''),
      'Human-authored source records a trespass notice for ' || v_subject || '.'
    ),
    'unknown',
    v_person_record_id,
    v_canonical_person_id,
    'person',
    nullif(trim(coalesce(p_source_author, '')), ''),
    trim(p_source_document_name),
    trim(p_source_reference),
    v_hash,
    nullif(trim(coalesce(p_source_locator, '')), ''),
    'observation:' || v_key,
    jsonb_build_object(
      'source_system', 'rm_local_folder',
      'notice_import_key', v_key,
      'human_authored', true
    )
  )
  RETURNING id INTO v_observation_id;

  INSERT INTO public.notices (
    organization_id,
    person_id,
    location_id,
    notice_type,
    notice_number,
    legal_basis,
    status,
    authorized_by,
    authorized_at,
    issued_at,
    observation_id,
    source_author,
    source_document_name,
    source_reference,
    source_sha256,
    import_key,
    metadata
  ) VALUES (
    p_organization_id,
    v_canonical_person_id,
    p_location_id,
    'trespass',
    nullif(trim(coalesce(p_notice_number, '')), ''),
    nullif(trim(coalesce(p_legal_basis, '')), ''),
    p_status,
    nullif(trim(coalesce(p_source_author, '')), ''),
    CASE WHEN p_status = 'issued' THEN p_issued_at ELSE NULL END,
    CASE WHEN p_status = 'issued' THEN p_issued_at ELSE NULL END,
    v_observation_id,
    nullif(trim(coalesce(p_source_author, '')), ''),
    trim(p_source_document_name),
    trim(p_source_reference),
    v_hash,
    v_key,
    jsonb_build_object(
      'provenance', 'human_authored_source',
      'identity_review_state', 'manual_review_required',
      'allegation_proven', false,
      'enforcement_authority_inferred', false
    )
  )
  RETURNING * INTO v_notice;

  INSERT INTO public.audit_log (
    organization_id,
    actor_user_id,
    action,
    target_table,
    target_id,
    metadata
  ) VALUES (
    p_organization_id,
    v_actor,
    'human_authored_trespass_notice_imported',
    'notices',
    v_notice.id,
    jsonb_build_object(
      'observation_id', v_observation_id,
      'canonical_person_id', v_canonical_person_id,
      'source_sha256', v_hash,
      'import_key', v_key,
      'status', p_status
    )
  );

  RETURN jsonb_build_object(
    'notice_id', v_notice.id,
    'observation_id', v_observation_id,
    'canonical_person_id', v_canonical_person_id,
    'person_record_id', v_person_record_id,
    'inserted', true
  );
END;
$function$;
REVOKE ALL ON FUNCTION "public"."import_human_authored_trespass_notice"(p_organization_id uuid, p_subject_display_name text, p_issued_at timestamp with time zone, p_status text, p_source_document_name text, p_source_reference text, p_source_sha256 text, p_import_key text, p_narrative text, p_source_author text, p_notice_number text, p_legal_basis text, p_location_id uuid, p_site_id uuid, p_zone_id uuid, p_source_locator text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."import_human_authored_trespass_notice"(p_organization_id uuid, p_subject_display_name text, p_issued_at timestamp with time zone, p_status text, p_source_document_name text, p_source_reference text, p_source_sha256 text, p_import_key text, p_narrative text, p_source_author text, p_notice_number text, p_legal_basis text, p_location_id uuid, p_site_id uuid, p_zone_id uuid, p_source_locator text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."import_human_authored_trespass_notice"(p_organization_id uuid, p_subject_display_name text, p_issued_at timestamp with time zone, p_status text, p_source_document_name text, p_source_reference text, p_source_sha256 text, p_import_key text, p_narrative text, p_source_author text, p_notice_number text, p_legal_basis text, p_location_id uuid, p_site_id uuid, p_zone_id uuid, p_source_locator text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."import_human_authored_trespass_notice"(p_organization_id uuid, p_subject_display_name text, p_issued_at timestamp with time zone, p_status text, p_source_document_name text, p_source_reference text, p_source_sha256 text, p_import_key text, p_narrative text, p_source_author text, p_notice_number text, p_legal_basis text, p_location_id uuid, p_site_id uuid, p_zone_id uuid, p_source_locator text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."import_person_notice"(p_organization_id uuid, p_notice_type text, p_status text, p_issued_at timestamp with time zone, p_subject_display_name text, p_source_document_name text, p_source_reference text, p_source_sha256 text, p_import_key text, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_canonical_person_id uuid DEFAULT NULL::uuid, p_plate_number text DEFAULT NULL::text, p_subject_address text DEFAULT NULL::text, p_notice_number text DEFAULT NULL::text, p_legal_basis text DEFAULT NULL::text, p_area text DEFAULT NULL::text, p_title text DEFAULT NULL::text, p_source_author text DEFAULT NULL::text, p_issued_date_basis text DEFAULT 'document'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_provider uuid;
  v_provider_count integer;
  v_authorized_provider_count integer;
  v_latest_owner_check timestamptz;
  v_subject text := nullif(regexp_replace(trim(coalesce(p_subject_display_name, '')), '\s+', ' ', 'g'), '');
  v_norm text;
  v_surname text;
  v_plate text := nullif(regexp_replace(upper(coalesce(p_plate_number, '')), '[^A-Z0-9]', '', 'g'), '');
  v_hash text := lower(nullif(trim(coalesce(p_source_sha256, '')), ''));
  v_key text := nullif(trim(coalesce(p_import_key, '')), '');
  v_notice public.notices%rowtype;
  v_person uuid;
  v_record uuid;
  v_basis text;
  v_candidates uuid[];
  v_name_tokens text[];
  v_surname_position bigint;
  v_given text[];
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT count(DISTINCT agreement.provider_organization_id),
         count(DISTINCT agreement.provider_organization_id)
           FILTER (WHERE public.is_admin_for_org(agreement.provider_organization_id)),
         (array_agg(agreement.provider_organization_id ORDER BY agreement.provider_organization_id)
           FILTER (WHERE public.is_admin_for_org(agreement.provider_organization_id)))[1]
    INTO v_provider_count, v_authorized_provider_count, v_provider
  FROM public.service_agreements agreement
  WHERE agreement.client_organization_id = p_organization_id
    AND agreement.agreement_type = 'operational'
    AND (agreement.starts_on IS NULL OR agreement.starts_on <= current_date)
    AND (agreement.ends_on IS NULL OR agreement.ends_on >= current_date);
  IF v_provider_count > 0 THEN
    IF v_authorized_provider_count <> 1 THEN
      RAISE EXCEPTION 'Provider administrator access to this client organisation is required';
    END IF;
  ELSE
    SELECT o.parent_organization_id INTO v_provider
    FROM public.organizations o
    WHERE o.id = p_organization_id;
  END IF;
  IF v_provider IS NULL OR NOT public.is_admin_for_org(v_provider) OR NOT public.org_access_allowed(p_organization_id) THEN
    RAISE EXCEPTION 'Provider administrator access to this client organisation is required';
  END IF;
  IF p_notice_type IS NULL OR p_notice_type NOT IN ('trespass', 'warning', 'permit_refusal', 'contact_request') THEN
    RAISE EXCEPTION 'Unsupported imported notice type %', p_notice_type;
  END IF;
  IF p_status IS NULL OR p_status NOT IN ('issued', 'withdrawn') THEN RAISE EXCEPTION 'Unsupported imported notice status %', p_status; END IF;
  IF p_issued_at IS NULL THEN RAISE EXCEPTION 'Issued date is required'; END IF;
  IF p_issued_date_basis IS NULL OR p_issued_date_basis NOT IN ('document', 'register', 'document_created') THEN
    RAISE EXCEPTION 'Unsupported issued date basis %', p_issued_date_basis;
  END IF;
  IF p_expires_at IS NOT NULL AND p_notice_type IN ('permit_refusal', 'contact_request') THEN RAISE EXCEPTION 'Letters do not expire'; END IF;
  IF p_expires_at IS NOT NULL AND p_expires_at < p_issued_at THEN RAISE EXCEPTION 'A notice cannot expire before it is issued'; END IF;
  IF v_subject IS NULL AND p_canonical_person_id IS NULL THEN RAISE EXCEPTION 'The person named on the notice is required'; END IF;
  IF nullif(trim(coalesce(p_source_document_name, '')), '') IS NULL OR nullif(trim(coalesce(p_source_reference, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Source document name and governed source reference are required';
  END IF;
  IF v_hash IS NULL OR v_hash !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'A SHA-256 source hash is required'; END IF;
  IF v_key IS NULL THEN RAISE EXCEPTION 'A deterministic import key is required'; END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(p_organization_id::text || ':person-notice:' || v_key, 0));
  SELECT * INTO v_notice FROM public.notices n WHERE n.organization_id = p_organization_id AND n.import_key = v_key;
  IF v_notice.id IS NOT NULL THEN
    IF v_notice.source_sha256 IS DISTINCT FROM v_hash THEN
      RAISE EXCEPTION 'Import key already exists with a different source hash';
    END IF;
    RETURN jsonb_build_object('notice_id', v_notice.id, 'canonical_person_id', v_notice.person_id,
      'match_basis', v_notice.metadata->>'match_basis', 'inserted', false);
  END IF;

  v_norm := regexp_replace(lower(coalesce(v_subject, '')), '[^a-z0-9]+', '', 'g');
  -- Names are compared word by word: words split on whitespace and keep their letters only, so
  -- Smith-Jones and O'Connor stay one family name. The family name is the last word of two or more
  -- letters; every other word on the notice, by position, is a given name or initial.
  v_name_tokens := array(
    SELECT word.token
    FROM (
      SELECT regexp_replace(raw.token, '[^[:alpha:]]+', '', 'g') AS token, raw.ord
      FROM unnest(regexp_split_to_array(
        lower(regexp_replace(coalesce(v_subject, ''), '^\s*(mr|mrs|ms|miss|mx|dr)\.?\s+', '', 'i')),
        '\s+')) WITH ORDINALITY AS raw(token, ord)
    ) word
    WHERE word.token <> ''
    ORDER BY word.ord);
  v_surname_position := (SELECT max(word.ord) FROM unnest(v_name_tokens) WITH ORDINALITY AS word(token, ord)
    WHERE length(word.token) >= 2);
  v_surname := v_name_tokens[v_surname_position];
  v_given := array(
    SELECT word.token FROM unnest(v_name_tokens) WITH ORDINALITY AS word(token, ord)
    WHERE word.ord IS DISTINCT FROM v_surname_position
    ORDER BY word.ord);

  IF p_canonical_person_id IS NOT NULL THEN
    SELECT p.id INTO v_person
    FROM public.canonical_people p
    WHERE p.id = p_canonical_person_id
      AND p.status = 'active'
      AND (
        EXISTS (
          SELECT 1 FROM public.canonical_person_links link
          WHERE link.canonical_person_id = p.id
            AND link.organization_id IN (v_provider, p_organization_id)
        )
        OR EXISTS (
          SELECT 1 FROM public.notices notice
          WHERE notice.person_id = p.id
            AND notice.organization_id IN (v_provider, p_organization_id)
        )
      );
    IF v_person IS NULL THEN RAISE EXCEPTION 'Canonical person not found in provider/client scope'; END IF;
    v_basis := 'explicit';
  END IF;

  -- A generational suffix (Jr, Sr, II to IV) hides where the family name ends, so a notice that
  -- carries one is never matched to the registered owner; it falls through to the exact-name
  -- match or a person verified by the notice.
  IF v_person IS NULL AND v_plate IS NOT NULL AND v_surname IS NOT NULL
    AND NOT (v_name_tokens && ARRAY['jr', 'jnr', 'sr', 'snr', 'ii', 'iii', 'iv']::text[]) THEN
    SELECT max(check_row.checked_at)
      INTO v_latest_owner_check
    FROM public.vehicle_identity_checks check_row
    JOIN public.canonical_vehicles vehicle ON vehicle.id = check_row.canonical_vehicle_id
    JOIN public.person_identity_documents document
      ON document.id = check_row.identity_document_id
     AND document.organization_id = check_row.organization_id
    WHERE check_row.organization_id = v_provider
      AND regexp_replace(upper(vehicle.plate_number), '[^A-Z0-9]', '', 'g') = v_plate
      AND check_row.checked_at <= p_issued_at
      AND document.document_kind = 'nzta_mvr_record'
      AND (document.review_state = 'approved'
        OR check_row.vehicle_snapshot->>'owner_only_review' = 'true');
    IF v_latest_owner_check IS NOT NULL THEN
      IF EXISTS (
        SELECT 1
        FROM public.vehicle_identity_checks check_row
        JOIN public.canonical_vehicles vehicle ON vehicle.id = check_row.canonical_vehicle_id
        JOIN public.person_identity_documents document
          ON document.id = check_row.identity_document_id
         AND document.organization_id = check_row.organization_id
        WHERE check_row.organization_id = v_provider
          AND regexp_replace(upper(vehicle.plate_number), '[^A-Z0-9]', '', 'g') = v_plate
          AND check_row.checked_at = v_latest_owner_check
          AND document.document_kind = 'nzta_mvr_record'
          AND (document.review_state = 'approved'
            OR check_row.vehicle_snapshot->>'owner_only_review' = 'true')
        GROUP BY check_row.checked_at
        HAVING count(DISTINCT check_row.canonical_person_id) > 1
      ) THEN
        RAISE EXCEPTION 'Ambiguous person: conflicting registered owners at the relevant NZTA check';
      END IF;
      v_candidates := array(
        SELECT DISTINCT check_row.canonical_person_id
        FROM public.vehicle_identity_checks check_row
        JOIN public.canonical_vehicles vehicle ON vehicle.id = check_row.canonical_vehicle_id
        JOIN public.person_identity_documents document
          ON document.id = check_row.identity_document_id
         AND document.organization_id = check_row.organization_id
        JOIN public.canonical_people person
          ON person.id = check_row.canonical_person_id AND person.status = 'active'
        CROSS JOIN LATERAL (
          SELECT owner_words.tokens,
            owner_family.position AS family_position,
            (SELECT min(given.ord) FROM unnest(owner_words.tokens) WITH ORDINALITY AS given(token, ord)
              WHERE given.ord <> owner_family.position) AS first_given_position
          FROM (
            SELECT array_agg(word.token ORDER BY word.ord) AS tokens
            FROM (
              SELECT regexp_replace(raw.token, '[^[:alpha:]]+', '', 'g') AS token, raw.ord
              FROM unnest(regexp_split_to_array(
                lower(regexp_replace(coalesce(person.display_name, ''), '^\s*(mr|mrs|ms|miss|mx|dr)\.?\s+', '', 'i')),
                '\s+'))
                WITH ORDINALITY AS raw(token, ord)
            ) word
            WHERE word.token <> ''
          ) owner_words
          CROSS JOIN LATERAL (
            SELECT max(family.ord) AS position
            FROM unnest(owner_words.tokens) WITH ORDINALITY AS family(token, ord)
            WHERE length(family.token) >= 2
          ) owner_family
        ) owner_name
        WHERE check_row.organization_id = v_provider
          AND regexp_replace(upper(vehicle.plate_number), '[^A-Z0-9]', '', 'g') = v_plate
          AND check_row.checked_at = v_latest_owner_check
          AND document.document_kind = 'nzta_mvr_record'
          AND (document.review_state = 'approved'
            OR check_row.vehicle_snapshot->>'owner_only_review' = 'true')
          -- An owner whose name carries a generational suffix is not matched either.
          AND NOT (owner_name.tokens && ARRAY['jr', 'jnr', 'sr', 'snr', 'ii', 'iii', 'iv']::text[])
          -- The owner's family name is resolved the same way as the notice's (the last word of two or
          -- more letters) and must be the notice's family name, so a notice family name that only
          -- equals one of the owner's given or middle names is not agreement.
          AND owner_name.tokens[owner_name.family_position] = v_surname
          -- A shared family name on the plate is not enough: a family member named on the notice is a
          -- different person. The owner matches only when the notice gives no given name, or the first
          -- given name on the notice equals the owner's first given name, is a one-letter initial of it,
          -- or shares a 3+ letter prefix with it, or exactly equals one of the owner's later words (a
          -- middle name). Later owner words get no initial or prefix leeway because a family-name
          -- particle (de, van) sits among them. Titles are stripped and the owner's family name is
          -- excluded by position, so Thomas Thomas keeps its given name, an owner recorded only by
          -- initial cannot claim a full given name, and a shared particle or middle name after a
          -- different first name never passes as agreement.
          AND (
            cardinality(v_given) = 0
            OR EXISTS (
              SELECT 1
              FROM unnest(owner_name.tokens) WITH ORDINALITY AS owner_given(token, ord)
              WHERE owner_given.ord <> owner_name.family_position
                AND (
                  owner_given.token = v_given[1]
                  OR (owner_given.ord = owner_name.first_given_position
                    AND ((length(v_given[1]) = 1 AND left(owner_given.token, 1) = v_given[1])
                      OR (least(length(owner_given.token), length(v_given[1])) >= 3
                        AND (starts_with(owner_given.token, v_given[1])
                          OR starts_with(v_given[1], owner_given.token)))))
                )
            )
          ));
      IF cardinality(v_candidates) > 1 THEN
        RAISE EXCEPTION 'Ambiguous person: % registered owners at the relevant NZTA check share the surname', cardinality(v_candidates);
      END IF;
      IF cardinality(v_candidates) = 1 THEN
        v_person := v_candidates[1];
        v_basis := 'vehicle_registered_owner_at_notice';
      END IF;
    END IF;
  END IF;

  IF v_person IS NULL AND length(v_norm) >= 4 AND v_subject ~ '\S\s+\S' THEN
    v_candidates := array(
      SELECT DISTINCT p.id
      FROM public.canonical_people p
      JOIN public.canonical_person_links link ON link.canonical_person_id = p.id
      WHERE p.status = 'active' AND p.normalized_name = v_norm
        AND link.organization_id IN (v_provider, p_organization_id));
    IF cardinality(v_candidates) > 1 THEN
      RAISE EXCEPTION 'Ambiguous person: % people share this exact name', cardinality(v_candidates);
    END IF;
    IF cardinality(v_candidates) = 1 THEN v_person := v_candidates[1]; v_basis := 'exact_name'; END IF;
  END IF;

  IF v_person IS NULL THEN
    IF v_subject IS NULL THEN RAISE EXCEPTION 'The person named on the notice is required'; END IF;
    IF regexp_replace(v_subject, '^\s*(mr|mrs|ms|miss|mx|dr)\.?\s+', '', 'i') !~ '[[:alpha:]]{2,}.*\s+.*[[:alpha:]]{2,}' THEN
      RAISE EXCEPTION 'A given name and family name are required to create a person from a notice';
    END IF;
    INSERT INTO public.person_records (organization_id, display_name, review_state, metadata)
    VALUES (v_provider, v_subject, 'verified', jsonb_strip_nulls(jsonb_build_object(
      'created_from', 'person_notice',
      'verified_by', 'notice',
      'notice_import_key', v_key,
      'source_sha256', v_hash,
      'source_document_name', trim(p_source_document_name),
      'notice_organization_id', p_organization_id,
      'profile_details', CASE WHEN nullif(trim(coalesce(p_subject_address, '')), '') IS NULL THEN NULL
        ELSE jsonb_build_object('address', trim(p_subject_address)) END,
      'created_by', v_actor)))
    RETURNING id INTO v_record;
    v_person := public.ensure_canonical_person_for_record(v_record);
    v_basis := 'created_from_notice';
    INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
    VALUES (v_provider, v_actor, 'identity_person_create', 'person_records', v_record,
      jsonb_build_object('canonical_person_id', v_person,
        'reason', 'Person named on an R&M ' || replace(p_notice_type, '_', ' ') || ' for a landowner client; the notice is the verification (owner-confirmed import rule).',
        'notice_import_key', v_key));
  END IF;

  INSERT INTO public.notices (
    organization_id, person_id, notice_type, notice_number, legal_basis, status,
    authorized_by, authorized_at, issued_at, expires_at, source_author,
    source_document_name, source_reference, source_sha256, import_key, metadata
  ) VALUES (
    p_organization_id, v_person, p_notice_type,
    nullif(trim(coalesce(p_notice_number, '')), ''), nullif(trim(coalesce(p_legal_basis, '')), ''), p_status,
    nullif(trim(coalesce(p_source_author, '')), ''), p_issued_at, p_issued_at, p_expires_at,
    nullif(trim(coalesce(p_source_author, '')), ''),
    trim(p_source_document_name), trim(p_source_reference), v_hash, v_key,
    jsonb_strip_nulls(jsonb_build_object(
      'provenance', 'rm_source_document',
      'source_of_truth', 'R&M records until R&M operate in FCM (owner-confirmed import rule)',
      'title', nullif(trim(coalesce(p_title, '')), ''),
      'area', nullif(trim(coalesce(p_area, '')), ''),
      'plate_number', v_plate,
      'subject_name_on_notice', v_subject,
      'match_basis', v_basis,
      'issued_date_basis', p_issued_date_basis,
      'created_person_record_id', v_record))
  ) RETURNING * INTO v_notice;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (p_organization_id, v_actor, 'person_notice_imported', 'notices', v_notice.id,
    jsonb_build_object('notice_type', p_notice_type, 'canonical_person_id', v_person, 'match_basis', v_basis,
      'import_key', v_key, 'source_sha256', v_hash, 'expires_at', v_notice.expires_at));

  RETURN jsonb_build_object('notice_id', v_notice.id, 'canonical_person_id', v_person,
    'person_record_id', v_record, 'match_basis', v_basis, 'expires_at', v_notice.expires_at, 'inserted', true);
END;
$function$;
COMMENT ON FUNCTION "public"."import_person_notice"(p_organization_id uuid, p_notice_type text, p_status text, p_issued_at timestamp with time zone, p_subject_display_name text, p_source_document_name text, p_source_reference text, p_source_sha256 text, p_import_key text, p_expires_at timestamp with time zone, p_canonical_person_id uuid, p_plate_number text, p_subject_address text, p_notice_number text, p_legal_basis text, p_area text, p_title text, p_source_author text, p_issued_date_basis text) IS 'Provider-administrator import of an R&M historical trespass notice, warning, permit refusal or contact request for a landowner client. Links the shared canonical person (explicit, NZTA registered owner of the named vehicle with agreeing family name and a compatible given name, or unique exact name) or creates a person verified by the notice; refuses ambiguous matches. Replay-safe by import key; audited.';
REVOKE ALL ON FUNCTION "public"."import_person_notice"(p_organization_id uuid, p_notice_type text, p_status text, p_issued_at timestamp with time zone, p_subject_display_name text, p_source_document_name text, p_source_reference text, p_source_sha256 text, p_import_key text, p_expires_at timestamp with time zone, p_canonical_person_id uuid, p_plate_number text, p_subject_address text, p_notice_number text, p_legal_basis text, p_area text, p_title text, p_source_author text, p_issued_date_basis text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."import_person_notice"(p_organization_id uuid, p_notice_type text, p_status text, p_issued_at timestamp with time zone, p_subject_display_name text, p_source_document_name text, p_source_reference text, p_source_sha256 text, p_import_key text, p_expires_at timestamp with time zone, p_canonical_person_id uuid, p_plate_number text, p_subject_address text, p_notice_number text, p_legal_basis text, p_area text, p_title text, p_source_author text, p_issued_date_basis text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."import_person_notice"(p_organization_id uuid, p_notice_type text, p_status text, p_issued_at timestamp with time zone, p_subject_display_name text, p_source_document_name text, p_source_reference text, p_source_sha256 text, p_import_key text, p_expires_at timestamp with time zone, p_canonical_person_id uuid, p_plate_number text, p_subject_address text, p_notice_number text, p_legal_basis text, p_area text, p_title text, p_source_author text, p_issued_date_basis text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."import_person_notice"(p_organization_id uuid, p_notice_type text, p_status text, p_issued_at timestamp with time zone, p_subject_display_name text, p_source_document_name text, p_source_reference text, p_source_sha256 text, p_import_key text, p_expires_at timestamp with time zone, p_canonical_person_id uuid, p_plate_number text, p_subject_address text, p_notice_number text, p_legal_basis text, p_area text, p_title text, p_source_author text, p_issued_date_basis text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."import_person_permit"(p_organization_id uuid, p_client_organization_id uuid, p_permit jsonb, p_source_document text, p_source_sha256 text, p_source_checked_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_canonical_person_id uuid DEFAULT NULL::uuid, p_create_holder boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_fields constant text[] := ARRAY[
    'contact_email', 'contact_phone', 'address_text', 'permit_type', 'applicant_type', 'company_name',
    'forest_areas', 'activities', 'hunting_season', 'date_from', 'date_to', 'firearm_confirm',
    'firearm_licence_valid', 'firearm_licence_number', 'chainsaw_safety_equipment', 'keys_issued', 'conditions'
  ];
  v_unknown text[];
  v_number text := nullif(regexp_replace(trim(coalesce(p_permit->>'permit_number', '')), '\s+', ' ', 'g'), '');
  v_hash text := lower(nullif(trim(coalesce(p_source_sha256, '')), ''));
  v_source text := nullif(trim(coalesce(p_source_document, '')), '');
  v_holder_name text := nullif(regexp_replace(trim(coalesce(p_permit->>'holder_name', '')), '\s+', ' ', 'g'), '');
  v_holder_norm text := public.normalize_person_name(p_permit->>'holder_name');
  v_input public.person_permits%rowtype;
  v_permit public.person_permits%rowtype;
  v_merged public.person_permits%rowtype;
  v_in jsonb;
  v_old jsonb;
  v_patch jsonb := '{}'::jsonb;
  v_field text;
  v_person uuid;
  v_basis text;
  v_candidates uuid[];
  v_filled text[] := '{}';
  v_differing text[] := '{}';
  v_holder_name_differs boolean := false;
  v_holder_created boolean := false;
  v_vehicle jsonb;
  v_plate text;
  v_vehicle_id uuid;
  v_rows integer;
  v_linked integer := 0;
  v_created integer := 0;
  v_already integer := 0;
  v_invalid integer := 0;
  v_outcome text;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_organization_id IS NULL OR NOT public.is_admin_for_org(p_organization_id) THEN
    RAISE EXCEPTION 'Administrator access to the permit organisation is required';
  END IF;
  IF p_client_organization_id IS NOT NULL AND NOT public.org_access_allowed(p_client_organization_id) THEN
    RAISE EXCEPTION 'Access to the client organisation is required';
  END IF;
  IF p_permit IS NULL OR jsonb_typeof(p_permit) <> 'object' THEN RAISE EXCEPTION 'Permit details must be a JSON object'; END IF;
  SELECT array_agg(field_name ORDER BY field_name) INTO v_unknown
  FROM jsonb_object_keys(p_permit) AS supplied(field_name)
  WHERE field_name <> ALL (v_fields || ARRAY['permit_number', 'holder_name', 'vehicles']);
  IF v_unknown IS NOT NULL THEN RAISE EXCEPTION 'Unsupported permit fields: %', array_to_string(v_unknown, ', '); END IF;
  IF v_number IS NULL THEN RAISE EXCEPTION 'A permit number is required'; END IF;
  IF v_source IS NULL THEN RAISE EXCEPTION 'The source document is required'; END IF;
  IF v_hash IS NULL OR v_hash !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'A SHA-256 source hash is required'; END IF;
  IF p_permit ? 'vehicles' AND jsonb_typeof(p_permit->'vehicles') <> 'array' THEN RAISE EXCEPTION 'Permit vehicles must be a list'; END IF;

  v_input := jsonb_populate_record(NULL::public.person_permits, p_permit - 'permit_number' - 'holder_name' - 'vehicles');
  v_input.contact_email := lower(nullif(trim(v_input.contact_email), ''));
  v_input.contact_phone := nullif(trim(v_input.contact_phone), '');
  v_input.address_text := nullif(regexp_replace(trim(v_input.address_text), '\s+', ' ', 'g'), '');
  v_input.permit_type := nullif(trim(v_input.permit_type), '');
  v_input.applicant_type := nullif(trim(v_input.applicant_type), '');
  v_input.company_name := nullif(trim(v_input.company_name), '');
  v_input.hunting_season := nullif(trim(v_input.hunting_season), '');
  v_input.firearm_licence_number := nullif(trim(v_input.firearm_licence_number), '');
  v_input.conditions := nullif(trim(v_input.conditions), '');
  v_input.forest_areas := nullif(array(SELECT trim(item) FROM unnest(v_input.forest_areas) item WHERE trim(item) <> ''), '{}');
  v_input.activities := nullif(array(SELECT trim(item) FROM unnest(v_input.activities) item WHERE trim(item) <> ''), '{}');
  IF v_input.date_from IS NOT NULL AND v_input.date_to IS NOT NULL AND v_input.date_to < v_input.date_from THEN
    RAISE EXCEPTION 'A permit cannot finish before it starts';
  END IF;
  v_in := to_jsonb(v_input);

  PERFORM pg_advisory_xact_lock(hashtextextended(p_organization_id::text || ':person-permit:' || v_number, 0));
  SELECT * INTO v_permit FROM public.person_permits permit
  WHERE permit.organization_id = p_organization_id AND permit.permit_number = v_number
  FOR UPDATE;

  IF v_permit.id IS NOT NULL THEN
    IF p_canonical_person_id IS NOT NULL AND p_canonical_person_id <> v_permit.canonical_person_id THEN
      RAISE EXCEPTION 'Permit holder conflict: this permit is recorded against another person';
    END IF;
    IF p_client_organization_id IS NOT NULL AND v_permit.client_organization_id IS NOT NULL
       AND p_client_organization_id <> v_permit.client_organization_id THEN
      RAISE EXCEPTION 'Permit client conflict: this permit is recorded for another client';
    END IF;
    v_person := v_permit.canonical_person_id;
    v_basis := 'existing_permit';
    SELECT v_holder_norm IS NOT NULL AND v_holder_norm IS DISTINCT FROM public.normalize_person_name(p.display_name)
      INTO v_holder_name_differs
    FROM public.canonical_people p WHERE p.id = v_person;
    v_holder_name_differs := coalesce(v_holder_name_differs, false);

    v_old := to_jsonb(v_permit);
    FOREACH v_field IN ARRAY v_fields LOOP
      CONTINUE WHEN coalesce(jsonb_typeof(v_in->v_field), 'null') = 'null';
      IF coalesce(jsonb_typeof(v_old->v_field), 'null') = 'null' OR v_old->v_field IN ('[]'::jsonb, '""'::jsonb)
         OR (jsonb_typeof(v_old->v_field) = 'string' AND trim(v_old->>v_field) = '') THEN
        v_patch := v_patch || jsonb_build_object(v_field, v_in->v_field);
        v_filled := v_filled || v_field;
      ELSIF public.person_permit_compare_value(v_field, v_old->v_field)
            IS DISTINCT FROM public.person_permit_compare_value(v_field, v_in->v_field) THEN
        v_differing := v_differing || v_field;
      END IF;
    END LOOP;
    IF v_permit.client_organization_id IS NULL AND p_client_organization_id IS NOT NULL THEN
      v_patch := v_patch || jsonb_build_object('client_organization_id', p_client_organization_id);
      v_filled := v_filled || 'client_organization_id'::text;
    END IF;
    IF v_permit.compliance_checked_at IS NULL AND p_source_checked_at IS NOT NULL THEN
      v_patch := v_patch || jsonb_build_object('compliance_checked_at', p_source_checked_at);
      v_filled := v_filled || 'compliance_checked_at'::text;
    END IF;
    IF v_patch <> '{}'::jsonb THEN
      v_merged := jsonb_populate_record(v_permit, v_patch);
      IF v_merged.date_from IS NOT NULL AND v_merged.date_to IS NOT NULL AND v_merged.date_to < v_merged.date_from THEN
        RAISE EXCEPTION 'A permit cannot finish before it starts';
      END IF;
      UPDATE public.person_permits permit SET
        client_organization_id = v_merged.client_organization_id,
        contact_email = v_merged.contact_email,
        contact_phone = v_merged.contact_phone,
        address_text = v_merged.address_text,
        permit_type = v_merged.permit_type,
        applicant_type = v_merged.applicant_type,
        company_name = v_merged.company_name,
        forest_areas = v_merged.forest_areas,
        activities = v_merged.activities,
        hunting_season = v_merged.hunting_season,
        date_from = v_merged.date_from,
        date_to = v_merged.date_to,
        firearm_confirm = v_merged.firearm_confirm,
        firearm_licence_valid = v_merged.firearm_licence_valid,
        firearm_licence_number = v_merged.firearm_licence_number,
        chainsaw_safety_equipment = v_merged.chainsaw_safety_equipment,
        keys_issued = v_merged.keys_issued,
        conditions = v_merged.conditions,
        compliance_checked_at = v_merged.compliance_checked_at,
        updated_at = now()
      WHERE permit.id = v_permit.id;
    END IF;
    v_outcome := CASE WHEN v_patch <> '{}'::jsonb THEN 'enriched' ELSE 'unchanged' END;
  ELSE
    IF p_canonical_person_id IS NOT NULL THEN
      SELECT p.id INTO v_person FROM public.canonical_people p
      WHERE p.id = p_canonical_person_id AND p.status = 'active' AND p.merged_into_id IS NULL;
      IF v_person IS NULL THEN RAISE EXCEPTION 'The permit holder must be an active, unmerged person'; END IF;
      v_basis := 'explicit';
    ELSE
      IF v_holder_norm IS NULL THEN
        RAISE EXCEPTION 'Permit holder not resolved: the holder name is required';
      END IF;
      IF v_input.contact_email IS NULL AND NOT coalesce(p_create_holder, false) THEN
        RAISE EXCEPTION 'Permit holder not resolved: the holder name and application email are both required';
      END IF;
      PERFORM pg_advisory_xact_lock(hashtextextended(
        p_organization_id::text || ':permit-holder:' || coalesce(v_input.contact_email, v_holder_norm), 0));
      IF v_input.contact_email IS NOT NULL THEN
        v_candidates := array(
          SELECT DISTINCT permit.canonical_person_id
          FROM public.person_permits permit
          JOIN public.canonical_people p ON p.id = permit.canonical_person_id
          WHERE permit.organization_id = p_organization_id
            AND lower(trim(permit.contact_email)) = v_input.contact_email
            AND public.normalize_person_name(p.display_name) = v_holder_norm
            AND p.status = 'active' AND p.merged_into_id IS NULL
        );
        IF cardinality(v_candidates) > 1 THEN
          RAISE EXCEPTION 'Permit holder not resolved: % existing permit holders share this name and application email', cardinality(v_candidates);
        END IF;
        IF cardinality(v_candidates) = 1 THEN
          v_person := v_candidates[1];
          v_basis := 'permit_email_and_name';
        ELSE
          -- A holder recorded by surname alone is the same person when the email agrees, this permit's name extends
          -- the recorded name, and only one such holder exists. A related name in either direction on any other
          -- holder ("Jane Smith" for "Mary Jane Smith", or "Mary Jane Smith" for "Jane Smith") is neither linked
          -- nor duplicated: it is held for review.
          v_candidates := array(
            SELECT DISTINCT permit.canonical_person_id
            FROM public.person_permits permit
            JOIN public.canonical_people p ON p.id = permit.canonical_person_id
            WHERE permit.organization_id = p_organization_id
              AND lower(trim(permit.contact_email)) = v_input.contact_email
              AND (public.person_name_extends(p.display_name, v_holder_name)
                   OR public.person_name_extends(v_holder_name, p.display_name))
              AND p.status = 'active' AND p.merged_into_id IS NULL
          );
          IF EXISTS (SELECT 1 FROM public.canonical_people p
                     WHERE p.id = ANY (v_candidates) AND p.metadata->>'name_basis' IS DISTINCT FROM 'surname') THEN
            RAISE EXCEPTION 'Permit holder not resolved: a holder with this application email and a related name is not recorded by surname alone';
          END IF;
          IF EXISTS (SELECT 1 FROM public.canonical_people p
                     WHERE p.id = ANY (v_candidates) AND NOT public.person_name_extends(p.display_name, v_holder_name)) THEN
            RAISE EXCEPTION 'Permit holder not resolved: a holder with this application email is recorded under a longer related name';
          END IF;
          IF cardinality(v_candidates) > 1 THEN
            RAISE EXCEPTION 'Permit holder not resolved: % existing permit holders share this surname and application email', cardinality(v_candidates);
          END IF;
          IF cardinality(v_candidates) = 1 THEN
            v_person := v_candidates[1];
            v_basis := 'permit_email_and_surname';
            v_holder_name_differs := true;
          END IF;
        END IF;
      END IF;
      IF v_person IS NULL THEN
        IF NOT coalesce(p_create_holder, false) THEN
          RAISE EXCEPTION 'Permit holder not resolved: no existing permit holder shares this name and application email';
        END IF;
        IF cardinality(public.person_name_parts(v_holder_name)) < 2 THEN
          RAISE EXCEPTION 'Permit holder not resolved: a new holder needs a full name';
        END IF;
        v_person := gen_random_uuid();
        INSERT INTO public.canonical_people (id, canonical_key, display_name, normalized_name, metadata, review_state, status)
        VALUES (v_person, 'person:permit-holder:' || v_person::text, v_holder_name, v_holder_norm,
          jsonb_build_object('created_from_permit_number', v_number, 'source_document', v_source, 'source_sha256', v_hash),
          'draft', 'active');
        v_basis := 'created_holder';
        v_holder_created := true;
      END IF;
    END IF;
    INSERT INTO public.person_permits (
      organization_id, client_organization_id, canonical_person_id, permit_number, permit_type, applicant_type,
      company_name, forest_areas, activities, hunting_season, date_from, date_to, firearm_confirm,
      firearm_licence_valid, firearm_licence_number, chainsaw_safety_equipment, keys_issued, conditions,
      status, compliance_checked_at, compliance_source, source_document, created_by,
      contact_email, contact_phone, address_text
    ) VALUES (
      p_organization_id, p_client_organization_id, v_person, v_number, v_input.permit_type, v_input.applicant_type,
      v_input.company_name, v_input.forest_areas, v_input.activities, v_input.hunting_season, v_input.date_from,
      v_input.date_to, v_input.firearm_confirm, v_input.firearm_licence_valid, v_input.firearm_licence_number,
      v_input.chainsaw_safety_equipment, v_input.keys_issued, v_input.conditions,
      'active', p_source_checked_at, 'import', v_source, v_actor,
      v_input.contact_email, v_input.contact_phone, v_input.address_text
    ) RETURNING * INTO v_permit;
    v_filled := array(SELECT field FROM unnest(v_fields) field WHERE jsonb_typeof(v_in->field) <> 'null');
    v_outcome := 'inserted';
  END IF;

  FOR v_vehicle IN SELECT value FROM jsonb_array_elements(coalesce(p_permit->'vehicles', '[]'::jsonb)) LOOP
    v_plate := public.normalize_plate_number(v_vehicle->>'plate');
    IF v_plate IS NULL OR length(v_plate) < 2 OR length(v_plate) > 8 THEN
      v_invalid := v_invalid + 1;
      CONTINUE;
    END IF;
    v_vehicle_id := NULL;
    SELECT vehicle.id INTO v_vehicle_id FROM public.canonical_vehicles vehicle WHERE vehicle.plate_number = v_plate;
    IF v_vehicle_id IS NULL THEN
      SELECT vehicle.id INTO v_vehicle_id FROM public.canonical_vehicles vehicle
      WHERE public.normalize_plate_number(vehicle.plate_number) = v_plate
      ORDER BY vehicle.created_at
      LIMIT 1;
    END IF;
    IF v_vehicle_id IS NULL THEN
      -- A new plate takes the applicant's description; an existing shared vehicle is never changed.
      INSERT INTO public.canonical_vehicles (plate_number, make, model, colour)
      VALUES (v_plate, nullif(trim(v_vehicle->>'make'), ''), nullif(trim(v_vehicle->>'model'), ''), nullif(trim(v_vehicle->>'colour'), ''))
      ON CONFLICT (plate_number) DO NOTHING
      RETURNING id INTO v_vehicle_id;
      IF v_vehicle_id IS NULL THEN
        SELECT vehicle.id INTO v_vehicle_id FROM public.canonical_vehicles vehicle WHERE vehicle.plate_number = v_plate;
      ELSE
        v_created := v_created + 1;
      END IF;
    END IF;
    INSERT INTO public.person_permit_vehicles (organization_id, permit_id, canonical_vehicle_id)
    VALUES (p_organization_id, v_permit.id, v_vehicle_id)
    ON CONFLICT (permit_id, canonical_vehicle_id) DO NOTHING;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows = 1 THEN v_linked := v_linked + 1; ELSE v_already := v_already + 1; END IF;
  END LOOP;
  IF v_outcome = 'unchanged' AND v_linked > 0 THEN v_outcome := 'enriched'; END IF;

  IF v_outcome <> 'unchanged' THEN
    INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
    VALUES (p_organization_id, v_actor,
      CASE WHEN v_outcome = 'inserted' THEN 'person_permit_imported' ELSE 'person_permit_enriched' END,
      'person_permits', v_permit.id,
      jsonb_build_object(
        'source_document', v_source, 'source_sha256', v_hash, 'source_checked_at', p_source_checked_at,
        'permit_number', v_number, 'match_basis', v_basis, 'fields_filled', to_jsonb(v_filled),
        'fields_differing', to_jsonb(v_differing), 'holder_name_differs', v_holder_name_differs,
        'holder_created', v_holder_created, 'canonical_person_id', v_person,
        'vehicles_linked', v_linked, 'vehicles_created', v_created));
  END IF;

  RETURN jsonb_build_object(
    'outcome', v_outcome, 'permit_id', v_permit.id, 'canonical_person_id', v_person, 'match_basis', v_basis,
    'fields_filled', to_jsonb(v_filled), 'fields_differing', to_jsonb(v_differing),
    'holder_name_differs', v_holder_name_differs, 'holder_created', v_holder_created,
    'holder_name_incomplete', v_basis = 'permit_email_and_surname',
    'vehicles_linked', v_linked, 'vehicles_created', v_created,
    'vehicles_already_linked', v_already, 'vehicles_invalid', v_invalid);
END;
$function$;
COMMENT ON FUNCTION "public"."import_person_permit"(p_organization_id uuid, p_client_organization_id uuid, p_permit jsonb, p_source_document text, p_source_sha256 text, p_source_checked_at timestamp with time zone, p_canonical_person_id uuid, p_create_holder boolean) IS 'Organisation-administrator import of a forest/site access permit extract row. Replay-safe by (organisation, permit number); fill-only (recorded values are never overwritten; differences are reported field by field through person_permit_compare_value); never changes a permit''s holder. A new permit goes to an explicit active person, else the single existing permit holder whose application email and name agree, else the single holder with that email recorded by surname alone (metadata name_basis; reported as holder_name_incomplete so the name can be completed through attribute_permit_holder) - a related name in either direction on any other holder (a longer or a shorter full name) is held, never linked or duplicated - else - only when p_create_holder is true and the holder has a full name of at least two parts - a new draft person. Plates are normalised and matched to the shared vehicle register; a new plate is created with the applicant''s description and an existing vehicle is never changed. Audited with source file and SHA-256.';
REVOKE ALL ON FUNCTION "public"."import_person_permit"(p_organization_id uuid, p_client_organization_id uuid, p_permit jsonb, p_source_document text, p_source_sha256 text, p_source_checked_at timestamp with time zone, p_canonical_person_id uuid, p_create_holder boolean) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."import_person_permit"(p_organization_id uuid, p_client_organization_id uuid, p_permit jsonb, p_source_document text, p_source_sha256 text, p_source_checked_at timestamp with time zone, p_canonical_person_id uuid, p_create_holder boolean) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."import_person_permit"(p_organization_id uuid, p_client_organization_id uuid, p_permit jsonb, p_source_document text, p_source_sha256 text, p_source_checked_at timestamp with time zone, p_canonical_person_id uuid, p_create_holder boolean) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."import_person_permit"(p_organization_id uuid, p_client_organization_id uuid, p_permit jsonb, p_source_document text, p_source_sha256 text, p_source_checked_at timestamp with time zone, p_canonical_person_id uuid, p_create_holder boolean) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."ingest_base44_rams_companions"(p_provider_organization_id uuid, p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
	r jsonb;
	v_holder_user text;
	v_holder uuid;
	v_companion uuid;
	v_name text;
	v_email text;
	v_resolved record;
	v_inserted boolean;
	v_created integer := 0;
	v_updated integer := 0;
	v_people_created integer := 0;
	v_people_review integer := 0;
	v_rejected integer := 0;
begin
	if p_provider_organization_id is null
		or not exists (select 1 from public.organizations o where o.id = p_provider_organization_id) then
		raise exception 'unknown provider organization' using errcode = '22023';
	end if;
	if jsonb_typeof(coalesce(p_rows, '[]'::jsonb)) <> 'array' then
		raise exception 'p_rows must be a JSON array' using errcode = '22023';
	end if;

	for r in select x from jsonb_array_elements(coalesce(p_rows, '[]'::jsonb)) x loop
		v_holder_user := nullif(btrim(r ->> 'holder_user_id'), '');
		v_name := left(nullif(regexp_replace(btrim(coalesce(r ->> 'full_name', '')), '\s+', ' ', 'g'), ''), 200);
		v_email := left(nullif(lower(btrim(r ->> 'email')), ''), 254);
		v_holder := null;
		v_companion := null;
		if v_holder_user is not null and v_holder_user ~ '^[A-Za-z0-9_-]{6,64}$' then
			select coalesce(cp.merged_into_id, cp.id) into v_holder
			from public.rams_person_profiles rp join public.canonical_people cp on cp.id = rp.canonical_person_id
			where rp.source_system = 'base44_rams' and rp.source_user_id = v_holder_user
				and rp.organization_id = p_provider_organization_id;
			if v_holder is null then
				select coalesce(cp.merged_into_id, cp.id) into v_holder
				from public.canonical_people cp where cp.canonical_key = 'person:base44:' || v_holder_user;
			end if;
		end if;
		if v_holder is null or v_name is null or public.normalize_person_name(v_name) is null then
			v_rejected := v_rejected + 1;
			continue;
		end if;

		-- A companion who is a RAMS user in their own right resolves through the resolver's
		-- provider email + normalised-name rule; email alone never identifies a person.
		select * into v_resolved from public.base44_rams_resolve_person(
			p_provider_organization_id,
			'person:base44-companion:' || p_provider_organization_id::text || ':'
				|| coalesce(v_email, 'holder:' || v_holder_user) || ':' || public.normalize_person_name(v_name),
			v_name, v_email);
		v_companion := v_resolved.person_id;
		if v_resolved.created then v_people_created := v_people_created + 1; end if;
		if v_resolved.needs_review then v_people_review := v_people_review + 1; end if;
		if v_companion = v_holder then
			v_rejected := v_rejected + 1;
			continue;
		end if;

		insert into public.rams_person_associations as a (
			organization_id, client_organization_id, canonical_person_id, associated_canonical_person_id, holder_source_user_id,
			companion_name, companion_email, companion_phone, permitted_status, booking_count, first_booking_date,
			last_booking_date, last_hunting_area, synced_at
		) values (
			p_provider_organization_id,
			(select o.id from public.organizations o where o.id = case
				when (r ->> 'client_organization_id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
				then (r ->> 'client_organization_id')::uuid end),
			v_holder, v_companion, v_holder_user, v_name, v_email,
			left(nullif(btrim(r ->> 'phone'), ''), 40),
			left(nullif(lower(btrim(r ->> 'permitted_status')), ''), 40),
			least(greatest(coalesce(case when (r ->> 'booking_count') ~ '^\d{1,6}$' then (r ->> 'booking_count')::integer end, 0), 0), 100000),
			case when (r ->> 'first_booking_date') ~ '^\d{4}-\d{2}-\d{2}$' then (r ->> 'first_booking_date')::date end,
			case when (r ->> 'last_booking_date') ~ '^\d{4}-\d{2}-\d{2}$' then (r ->> 'last_booking_date')::date end,
			left(nullif(btrim(r ->> 'last_hunting_area'), ''), 200),
			now()
		)
		on conflict (organization_id, canonical_person_id, associated_canonical_person_id, relationship) do update set
			client_organization_id = coalesce(excluded.client_organization_id, a.client_organization_id),
			holder_source_user_id = excluded.holder_source_user_id,
			companion_name = excluded.companion_name,
			companion_email = coalesce(excluded.companion_email, a.companion_email),
			companion_phone = coalesce(excluded.companion_phone, a.companion_phone),
			permitted_status = coalesce(excluded.permitted_status, a.permitted_status),
			booking_count = excluded.booking_count,
			first_booking_date = excluded.first_booking_date,
			last_booking_date = excluded.last_booking_date,
			last_hunting_area = excluded.last_hunting_area,
			synced_at = now()
		returning (xmax = 0) into v_inserted;
		if v_inserted then v_created := v_created + 1; else v_updated := v_updated + 1; end if;
	end loop;

	insert into public.audit_log (organization_id, action, target_table, metadata)
	values (p_provider_organization_id, 'sync_base44_rams_companions', 'rams_person_associations', jsonb_build_object(
		'source', 'base44_rams', 'received', jsonb_array_length(coalesce(p_rows, '[]'::jsonb)),
		'created', v_created, 'updated', v_updated, 'rejected', v_rejected,
		'people_created', v_people_created, 'people_needing_review', v_people_review));

	return jsonb_build_object('created', v_created, 'updated', v_updated, 'rejected', v_rejected,
		'people_created', v_people_created, 'people_needing_review', v_people_review);
end;
$function$;
COMMENT ON FUNCTION "public"."ingest_base44_rams_companions"(p_provider_organization_id uuid, p_rows jsonb) IS 'Server-only upsert of RAMS booking companions (one row per permit holder and companion, aggregated across bookings) into rams_person_associations, resolving both sides to canonical people. Writes one audit_log entry per call.';
REVOKE ALL ON FUNCTION "public"."ingest_base44_rams_companions"(p_provider_organization_id uuid, p_rows jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."ingest_base44_rams_companions"(p_provider_organization_id uuid, p_rows jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."ingest_base44_rams_companions"(p_provider_organization_id uuid, p_rows jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."ingest_base44_rams_kill_returns"(p_provider_organization_id uuid, p_rows jsonb, p_seen_source_ids text[] DEFAULT NULL::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
	v_inserted integer := 0;
	v_updated integer := 0;
	v_rejected integer := 0;
	v_withdrawn integer := 0;
	v_clients uuid[];
begin
	if p_provider_organization_id is null
		or not exists (select 1 from public.organizations o where o.id = p_provider_organization_id) then
		raise exception 'unknown provider organization' using errcode = '22023';
	end if;
	if jsonb_typeof(coalesce(p_rows, '[]'::jsonb)) <> 'array' then
		raise exception 'p_rows must be a JSON array' using errcode = '22023';
	end if;

	with raw as (
		select r,
			nullif(btrim(r ->> 'source_id'), '') as source_id,
			case when (r ->> 'client_organization_id') ~* '^[0-9a-f-]{36}$' then (r ->> 'client_organization_id')::uuid end as client_id,
			case when (r ->> 'hunt_date') ~ '^\d{4}-\d{2}-\d{2}$' then (r ->> 'hunt_date')::date end as hunt_date,
			lower(btrim(r ->> 'return_type')) as return_type,
			left(nullif(btrim(r ->> 'hunting_area'), ''), 200) as hunting_area
		from jsonb_array_elements(coalesce(p_rows, '[]'::jsonb)) r
	),
	valid as (
		select raw.*,
			coalesce((
				select jsonb_agg(jsonb_build_object('species', a.species, 'count', a.n) order by a.species)
				from (
					select left(btrim(x ->> 'species'), 60) as species, sum(least(greatest((x ->> 'count')::integer, 0), 1000))::integer as n
					from jsonb_array_elements(case when jsonb_typeof(raw.r -> 'animals') = 'array' then raw.r -> 'animals' else '[]'::jsonb end) x
					where raw.return_type = 'kill'
						and nullif(btrim(x ->> 'species'), '') is not null
						and (x ->> 'count') ~ '^\d{1,6}$'
					group by 1
				) a where a.n > 0
			), '[]'::jsonb) as animals
		from raw
		where raw.source_id ~ '^[A-Za-z0-9_-]{6,64}$'
			and raw.client_id is not null
			and exists (select 1 from public.organizations o where o.id = raw.client_id)
			and raw.hunt_date is not null
			and raw.return_type in ('kill', 'nil')
			and raw.hunting_area is not null
	),
	shaped as (
		select v.source_id, v.client_id, v.hunt_date, v.return_type, v.hunting_area, v.animals,
			(select coalesce(sum((a ->> 'count')::integer), 0) from jsonb_array_elements(v.animals) a)::integer as total_animals,
			left(nullif(btrim(v.r ->> 'booking_id'), ''), 64) as booking_id,
			left(nullif(btrim(v.r ->> 'permit_number'), ''), 64) as permit_number,
			left(nullif(btrim(v.r ->> 'comments'), ''), 2000) as comments,
			left(nullif(btrim(v.r ->> 'hunter_name'), ''), 200) as hunter_name,
			left(nullif(lower(btrim(v.r ->> 'hunter_email')), ''), 254) as hunter_email,
			case when (v.r ->> 'source_created_at') ~ '^\d{4}-\d{2}-\d{2}T' then (v.r ->> 'source_created_at')::timestamptz end as source_created_at,
			case when (v.r ->> 'source_updated_at') ~ '^\d{4}-\d{2}-\d{2}T' then (v.r ->> 'source_updated_at')::timestamptz end as source_updated_at
		from valid v
	),
	upserted as (
		insert into public.hunter_kill_returns as h (
			organization_id, client_organization_id, source_id, source_booking_id, permit_number, person_permit_id,
			hunting_area, hunt_date, return_type, animals, total_animals, comments, hunter_name, hunter_email,
			source_created_at, source_updated_at, synced_at, withdrawn_at
		)
		select p_provider_organization_id, s.client_id, s.source_id, s.booking_id, s.permit_number,
			(select pp.id from public.person_permits pp where pp.organization_id = p_provider_organization_id and pp.permit_number = s.permit_number),
			s.hunting_area, s.hunt_date, s.return_type, s.animals, s.total_animals, s.comments, s.hunter_name, s.hunter_email,
			s.source_created_at, s.source_updated_at, now(), null
		from shaped s
		on conflict (source_system, source_id) do update set
			client_organization_id = excluded.client_organization_id,
			source_booking_id = excluded.source_booking_id,
			permit_number = excluded.permit_number,
			person_permit_id = excluded.person_permit_id,
			hunting_area = excluded.hunting_area,
			hunt_date = excluded.hunt_date,
			return_type = excluded.return_type,
			animals = excluded.animals,
			total_animals = excluded.total_animals,
			comments = excluded.comments,
			hunter_name = excluded.hunter_name,
			hunter_email = excluded.hunter_email,
			source_created_at = excluded.source_created_at,
			source_updated_at = excluded.source_updated_at,
			synced_at = now(),
			withdrawn_at = null
		where h.organization_id = p_provider_organization_id
			and (h.withdrawn_at is not null
				or (h.client_organization_id, h.source_booking_id, h.permit_number, h.person_permit_id, h.hunting_area, h.hunt_date,
					h.return_type, h.animals, h.comments, h.hunter_name, h.hunter_email, h.source_updated_at)
				is distinct from
				(excluded.client_organization_id, excluded.source_booking_id, excluded.permit_number, excluded.person_permit_id,
					excluded.hunting_area, excluded.hunt_date, excluded.return_type, excluded.animals, excluded.comments,
					excluded.hunter_name, excluded.hunter_email, excluded.source_updated_at))
		returning (h.xmax = 0) as inserted
	)
	select count(*) filter (where inserted), count(*) filter (where not inserted)
	into v_inserted, v_updated
	from upserted;

	v_rejected := jsonb_array_length(coalesce(p_rows, '[]'::jsonb)) - (
		select count(*) from jsonb_array_elements(coalesce(p_rows, '[]'::jsonb)) r
		where exists (
			select 1 from public.hunter_kill_returns h
			where h.source_system = 'base44_rams' and h.source_id = btrim(r ->> 'source_id')
				and h.organization_id = p_provider_organization_id and h.withdrawn_at is null
		)
	);

	if p_seen_source_ids is not null then
		if cardinality(p_seen_source_ids) = 0 then
			raise exception 'refusing to withdraw every return from an empty source listing' using errcode = '22023';
		end if;
		update public.hunter_kill_returns h
		set withdrawn_at = now()
		where h.organization_id = p_provider_organization_id
			and h.source_system = 'base44_rams'
			and h.withdrawn_at is null
			and not (h.source_id = any (p_seen_source_ids));
		get diagnostics v_withdrawn = row_count;
	end if;

	select coalesce(array_agg(distinct h.client_organization_id), '{}') into v_clients
	from public.hunter_kill_returns h where h.organization_id = p_provider_organization_id;

	insert into public.audit_log (organization_id, action, target_table, metadata)
	values (p_provider_organization_id, 'sync_base44_rams_kill_returns', 'hunter_kill_returns', jsonb_build_object(
		'source', 'base44_rams', 'received', jsonb_array_length(coalesce(p_rows, '[]'::jsonb)),
		'inserted', v_inserted, 'updated', v_updated, 'rejected', v_rejected, 'withdrawn', v_withdrawn,
		'complete_listing', p_seen_source_ids is not null));

	return jsonb_build_object('inserted', v_inserted, 'updated', v_updated, 'rejected', v_rejected,
		'withdrawn', v_withdrawn, 'clients', to_jsonb(v_clients));
end;
$function$;
COMMENT ON FUNCTION "public"."ingest_base44_rams_kill_returns"(p_provider_organization_id uuid, p_rows jsonb, p_seen_source_ids text[]) IS 'Server-only upsert of hunter kill/nil returns read from the Base44 RAMS (OFO) app. Idempotent on (source_system, source_id); rows failing validation are counted as rejected. When p_seen_source_ids carries the complete Base44 listing, returns no longer present are marked withdrawn (never deleted). Writes one audit_log entry per call.';
REVOKE ALL ON FUNCTION "public"."ingest_base44_rams_kill_returns"(p_provider_organization_id uuid, p_rows jsonb, p_seen_source_ids text[]) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."ingest_base44_rams_kill_returns"(p_provider_organization_id uuid, p_rows jsonb, p_seen_source_ids text[]) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."ingest_base44_rams_kill_returns"(p_provider_organization_id uuid, p_rows jsonb, p_seen_source_ids text[]) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."ingest_base44_rams_people"(p_provider_organization_id uuid, p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
	r jsonb;
	v jsonb;
	v_user_id text;
	v_name text;
	v_email text;
	v_dob date;
	v_person uuid;
	v_profile uuid;
	v_vehicle uuid;
	v_plate text;
	v_vehicle_ids uuid[];
	v_resolved record;
	v_inserted boolean;
	v_rows integer;
	v_profiles_created integer := 0;
	v_profiles_updated integer := 0;
	v_people_created integer := 0;
	v_people_review integer := 0;
	v_people_enriched integer := 0;
	v_vehicles_linked integer := 0;
	v_vehicles_withdrawn integer := 0;
	v_rejected integer := 0;
begin
	if p_provider_organization_id is null
		or not exists (select 1 from public.organizations o where o.id = p_provider_organization_id) then
		raise exception 'unknown provider organization' using errcode = '22023';
	end if;
	if jsonb_typeof(coalesce(p_rows, '[]'::jsonb)) <> 'array' then
		raise exception 'p_rows must be a JSON array' using errcode = '22023';
	end if;

	for r in select x from jsonb_array_elements(coalesce(p_rows, '[]'::jsonb)) x loop
		v_user_id := nullif(btrim(r ->> 'source_user_id'), '');
		v_name := left(nullif(regexp_replace(btrim(coalesce(r ->> 'full_name', r ->> 'legal_name', '')), '\s+', ' ', 'g'), ''), 200);
		if v_user_id is null or v_user_id !~ '^[A-Za-z0-9_-]{6,64}$' or v_name is null
			or public.normalize_person_name(v_name) is null then
			v_rejected := v_rejected + 1;
			continue;
		end if;
		v_email := left(nullif(lower(btrim(r ->> 'email')), ''), 254);
		v_dob := case when (r ->> 'date_of_birth') ~ '^\d{4}-\d{2}-\d{2}$' then (r ->> 'date_of_birth')::date end;

		select coalesce(cp.merged_into_id, cp.id) into v_person
		from public.rams_person_profiles rp join public.canonical_people cp on cp.id = rp.canonical_person_id
		where rp.source_system = 'base44_rams' and rp.source_user_id = v_user_id;
		if v_person is null then
			select * into v_resolved from public.base44_rams_resolve_person(
				p_provider_organization_id, 'person:base44:' || v_user_id, v_name, v_email);
			v_person := v_resolved.person_id;
			if v_resolved.created then v_people_created := v_people_created + 1; end if;
			if v_resolved.needs_review then v_people_review := v_people_review + 1; end if;
		end if;

		update public.canonical_people cp set
			display_name = coalesce(cp.display_name, v_name),
			date_of_birth = coalesce(cp.date_of_birth, v_dob),
			updated_at = clock_timestamp()
		where cp.id = v_person
			and (cp.display_name is null or (cp.date_of_birth is null and v_dob is not null));
		get diagnostics v_rows = row_count;
		v_people_enriched := v_people_enriched + v_rows;

		insert into public.rams_person_profiles as rp (
			organization_id, canonical_person_id, source_user_id, source_url, full_name, legal_name, nickname, email, phone,
			home_address, date_of_birth, firearms_licence_number, firearms_licence_expiry, firearms_licence_status,
			firearms_licence_document_url, account_role, admin_level, is_verified, client_organization_ids,
			source_created_at, source_updated_at, synced_at
		) values (
			p_provider_organization_id, v_person, v_user_id,
			left(coalesce(nullif(btrim(r ->> 'source_url'), ''), 'https://app.base44.com'), 500),
			v_name,
			left(nullif(btrim(r ->> 'legal_name'), ''), 200),
			left(nullif(btrim(r ->> 'nickname'), ''), 120),
			v_email,
			left(nullif(btrim(r ->> 'phone'), ''), 40),
			left(nullif(btrim(r ->> 'home_address'), ''), 500),
			v_dob,
			left(nullif(btrim(r ->> 'firearms_licence_number'), ''), 60),
			case when (r ->> 'firearms_licence_expiry') ~ '^\d{4}-\d{2}-\d{2}$' then (r ->> 'firearms_licence_expiry')::date end,
			left(nullif(lower(btrim(r ->> 'firearms_licence_status')), ''), 40),
			left(nullif(btrim(r ->> 'firearms_licence_document_url'), ''), 1000),
			left(nullif(btrim(r ->> 'account_role'), ''), 60),
			left(nullif(btrim(r ->> 'admin_level'), ''), 60),
			case when jsonb_typeof(r -> 'is_verified') = 'boolean' then (r ->> 'is_verified')::boolean end,
			coalesce((select array_agg(distinct o.id) from jsonb_array_elements_text(
				case when jsonb_typeof(r -> 'client_organization_ids') = 'array' then r -> 'client_organization_ids' else '[]'::jsonb end) c
				join public.organizations o on o.id = case when c ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then c::uuid end), '{}'),
			case when (r ->> 'source_created_at') ~ '^\d{4}-\d{2}-\d{2}T' then (r ->> 'source_created_at')::timestamptz end,
			case when (r ->> 'source_updated_at') ~ '^\d{4}-\d{2}-\d{2}T' then (r ->> 'source_updated_at')::timestamptz end,
			now()
		)
		on conflict (source_system, source_user_id) do update set
			canonical_person_id = excluded.canonical_person_id,
			source_url = excluded.source_url,
			full_name = excluded.full_name,
			legal_name = excluded.legal_name,
			nickname = excluded.nickname,
			email = excluded.email,
			phone = excluded.phone,
			home_address = excluded.home_address,
			date_of_birth = excluded.date_of_birth,
			firearms_licence_number = excluded.firearms_licence_number,
			firearms_licence_expiry = excluded.firearms_licence_expiry,
			firearms_licence_status = excluded.firearms_licence_status,
			firearms_licence_document_url = excluded.firearms_licence_document_url,
			account_role = excluded.account_role,
			admin_level = excluded.admin_level,
			is_verified = excluded.is_verified,
			client_organization_ids = excluded.client_organization_ids,
			source_created_at = excluded.source_created_at,
			source_updated_at = excluded.source_updated_at,
			synced_at = now()
		where rp.organization_id = p_provider_organization_id
		returning id, (xmax = 0) into v_profile, v_inserted;
		if v_profile is null then
			-- The RAMS identity is already held by another provider; never overwrite it.
			v_rejected := v_rejected + 1;
			v_person := null;
			continue;
		end if;
		if v_inserted then v_profiles_created := v_profiles_created + 1; else v_profiles_updated := v_profiles_updated + 1; end if;

		insert into public.canonical_person_links (canonical_person_id, source_table, source_id, organization_id, link_kind, metadata)
		values (v_person, 'rams_person_profiles', v_profile, p_provider_organization_id, 'imported',
			jsonb_build_object('source', 'base44_rams', 'source_user_id', v_user_id))
		on conflict (source_table, source_id) do update set canonical_person_id = excluded.canonical_person_id
		where public.canonical_person_links.canonical_person_id is distinct from excluded.canonical_person_id;

		v_vehicle_ids := '{}';
		for v in select x from jsonb_array_elements(case when jsonb_typeof(r -> 'vehicles') = 'array' then r -> 'vehicles' else '[]'::jsonb end) x loop
			v_plate := upper(regexp_replace(coalesce(v ->> 'plate', ''), '[^A-Za-z0-9]', '', 'g'));
			continue when v_plate !~ '^[A-Z0-9]{2,8}$';
			insert into public.canonical_vehicles (plate_number, make, model, colour, compliance_source, compliance_checked_at)
			values (v_plate, left(nullif(btrim(v ->> 'make'), ''), 60), left(nullif(btrim(v ->> 'model'), ''), 60),
				left(nullif(btrim(v ->> 'colour'), ''), 40), 'canonical', now())
			on conflict (plate_number) do update set
				make = coalesce(public.canonical_vehicles.make, excluded.make),
				model = coalesce(public.canonical_vehicles.model, excluded.model),
				colour = coalesce(public.canonical_vehicles.colour, excluded.colour)
			returning id into v_vehicle;
			v_vehicle_ids := v_vehicle_ids || v_vehicle;

			insert into public.rams_person_vehicles as pv (
				organization_id, rams_person_profile_id, canonical_person_id, canonical_vehicle_id, plate_as_recorded,
				make, model, colour, insurance_expiry, company_insurance, company_insurance_comments,
				insurance_document_urls, vehicle_status, archived, synced_at, withdrawn_at
			) values (
				p_provider_organization_id, v_profile, v_person, v_vehicle, left(btrim(v ->> 'plate'), 20),
				left(nullif(btrim(v ->> 'make'), ''), 60), left(nullif(btrim(v ->> 'model'), ''), 60),
				left(nullif(btrim(v ->> 'colour'), ''), 40),
				case when (v ->> 'insurance_expiry') ~ '^\d{4}-\d{2}-\d{2}$' then (v ->> 'insurance_expiry')::date end,
				case when jsonb_typeof(v -> 'company_insurance') = 'boolean' then (v ->> 'company_insurance')::boolean end,
				left(nullif(btrim(v ->> 'company_insurance_comments'), ''), 1000),
				coalesce((select array_agg(left(u, 1000)) from jsonb_array_elements_text(
					case when jsonb_typeof(v -> 'insurance_document_urls') = 'array' then v -> 'insurance_document_urls' else '[]'::jsonb end) u
					where u ~ '^https://'), '{}'),
				left(nullif(lower(btrim(v ->> 'status')), ''), 40),
				case when jsonb_typeof(v -> 'archived') = 'boolean' then (v ->> 'archived')::boolean end,
				now(), null
			)
			on conflict (rams_person_profile_id, canonical_vehicle_id) do update set
				canonical_person_id = excluded.canonical_person_id,
				plate_as_recorded = excluded.plate_as_recorded,
				make = excluded.make,
				model = excluded.model,
				colour = excluded.colour,
				insurance_expiry = excluded.insurance_expiry,
				company_insurance = excluded.company_insurance,
				company_insurance_comments = excluded.company_insurance_comments,
				insurance_document_urls = excluded.insurance_document_urls,
				vehicle_status = excluded.vehicle_status,
				archived = excluded.archived,
				synced_at = now(),
				withdrawn_at = null
			returning (xmax = 0) into v_inserted;
			if v_inserted then v_vehicles_linked := v_vehicles_linked + 1; end if;
		end loop;

		-- The profile carries the person's complete vehicle list, so absent vehicles have left it.
		update public.rams_person_vehicles pv set withdrawn_at = now()
		where pv.rams_person_profile_id = v_profile and pv.withdrawn_at is null
			and not (pv.canonical_vehicle_id = any (v_vehicle_ids));
		get diagnostics v_rows = row_count;
		v_vehicles_withdrawn := v_vehicles_withdrawn + v_rows;

		v_person := null;
		v_profile := null;
	end loop;

	insert into public.audit_log (organization_id, action, target_table, metadata)
	values (p_provider_organization_id, 'sync_base44_rams_people', 'rams_person_profiles', jsonb_build_object(
		'source', 'base44_rams', 'received', jsonb_array_length(coalesce(p_rows, '[]'::jsonb)),
		'profiles_created', v_profiles_created, 'profiles_updated', v_profiles_updated, 'rejected', v_rejected,
		'people_created', v_people_created, 'people_needing_review', v_people_review, 'people_enriched', v_people_enriched,
		'vehicles_linked', v_vehicles_linked, 'vehicles_withdrawn', v_vehicles_withdrawn));

	return jsonb_build_object('profiles_created', v_profiles_created, 'profiles_updated', v_profiles_updated,
		'rejected', v_rejected, 'people_created', v_people_created, 'people_needing_review', v_people_review,
		'people_enriched', v_people_enriched, 'vehicles_linked', v_vehicles_linked, 'vehicles_withdrawn', v_vehicles_withdrawn);
end;
$function$;
COMMENT ON FUNCTION "public"."ingest_base44_rams_people"(p_provider_organization_id uuid, p_rows jsonb) IS 'Server-only upsert of RAMS user profiles read from Base44: resolves or creates the canonical person (never by name alone), fills blank canonical name/date of birth, mirrors every supplied detail into rams_person_profiles with a canonical_person_links entry, and links the person''s registered vehicles through canonical_vehicles into rams_person_vehicles. Writes one audit_log entry per call.';
REVOKE ALL ON FUNCTION "public"."ingest_base44_rams_people"(p_provider_organization_id uuid, p_rows jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."ingest_base44_rams_people"(p_provider_organization_id uuid, p_rows jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."ingest_base44_rams_people"(p_provider_organization_id uuid, p_rows jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."ingest_base44_rams_permits"(p_provider_organization_id uuid, p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
	r jsonb;
	v jsonb;
	v_client uuid;
	v_permit_number text;
	v_holder text;
	v_user_id text;
	v_person uuid;
	v_resolved record;
	v_permit uuid;
	v_vehicle uuid;
	v_plate text;
	v_status text;
	v_expiry date;
	v_created integer := 0;
	v_updated integer := 0;
	v_rejected integer := 0;
	v_people_created integer := 0;
	v_people_review integer := 0;
	v_vehicles_linked integer := 0;
	v_rows integer;
begin
	if p_provider_organization_id is null
		or not exists (select 1 from public.organizations o where o.id = p_provider_organization_id) then
		raise exception 'unknown provider organization' using errcode = '22023';
	end if;
	if jsonb_typeof(coalesce(p_rows, '[]'::jsonb)) <> 'array' then
		raise exception 'p_rows must be a JSON array' using errcode = '22023';
	end if;

	for r in select x from jsonb_array_elements(coalesce(p_rows, '[]'::jsonb)) x loop
		v_permit_number := left(nullif(btrim(r ->> 'permit_number'), ''), 64);
		v_holder := left(nullif(regexp_replace(btrim(coalesce(r ->> 'holder_name', '')), '\s+', ' ', 'g'), ''), 200);
		v_user_id := nullif(btrim(r ->> 'source_user_id'), '');
		v_client := case when (r ->> 'client_organization_id') ~* '^[0-9a-f-]{36}$' then (r ->> 'client_organization_id')::uuid end;
		v_status := lower(btrim(coalesce(r ->> 'status', '')));
		v_expiry := case when (r ->> 'expiry_date') ~ '^\d{4}-\d{2}-\d{2}$' then (r ->> 'expiry_date')::date end;
		if v_permit_number is null or v_holder is null or v_client is null
			or v_user_id is null or v_user_id !~ '^[A-Za-z0-9_-]{6,64}$'
			or v_status not in ('active', 'expired', 'revoked', 'suspended')
			or not exists (select 1 from public.organizations o where o.id = v_client) then
			v_rejected := v_rejected + 1;
			continue;
		end if;

		select pp.id into v_permit
		from public.person_permits pp
		where pp.organization_id = p_provider_organization_id and pp.permit_number = v_permit_number;

		if v_permit is null then
			select coalesce(cp.merged_into_id, cp.id) into v_person
			from public.rams_person_profiles rp join public.canonical_people cp on cp.id = rp.canonical_person_id
			where rp.source_system = 'base44_rams' and rp.source_user_id = v_user_id
				and rp.organization_id = p_provider_organization_id;
			if v_person is null then
				select * into v_resolved from public.base44_rams_resolve_person(
					p_provider_organization_id, 'person:base44:' || v_user_id, v_holder, r ->> 'contact_email');
				v_person := v_resolved.person_id;
				if v_resolved.created then v_people_created := v_people_created + 1; end if;
				if v_resolved.needs_review then v_people_review := v_people_review + 1; end if;
			end if;

			insert into public.person_permits (
				organization_id, client_organization_id, canonical_person_id, permit_number, permit_type, applicant_type,
				company_name, activities, date_to, firearm_confirm, firearm_licence_valid, firearm_licence_number, conditions,
				status, contact_email, contact_phone, address_text, compliance_checked_at, compliance_source, source_document
			) values (
				p_provider_organization_id, v_client, v_person, v_permit_number,
				left(nullif(btrim(r ->> 'permit_type'), ''), 120), left(nullif(btrim(r ->> 'applicant_type'), ''), 120),
				left(nullif(btrim(r ->> 'company_name'), ''), 200),
				(select nullif(array_agg(left(btrim(a), 80) order by ord), '{}') from jsonb_array_elements_text(
					case when jsonb_typeof(r -> 'activities') = 'array' then r -> 'activities' else '[]'::jsonb end) with ordinality t(a, ord)
					where nullif(btrim(a), '') is not null),
				v_expiry,
				case when jsonb_typeof(r -> 'firearms_permitted') = 'boolean' then (r ->> 'firearms_permitted')::boolean end,
				case when jsonb_typeof(r -> 'firearm_licence_valid') = 'boolean' then (r ->> 'firearm_licence_valid')::boolean end,
				left(nullif(btrim(r ->> 'firearm_licence_number'), ''), 60),
				left(nullif(btrim(r ->> 'conditions'), ''), 4000),
				v_status, left(nullif(lower(btrim(r ->> 'contact_email')), ''), 254), left(nullif(btrim(r ->> 'contact_phone'), ''), 40),
				left(nullif(btrim(r ->> 'address'), ''), 500),
				now(), 'import', 'Base44 RAMS (OFO)'
			) returning id into v_permit;
			v_created := v_created + 1;
		else
			update public.person_permits pp set
				client_organization_id = v_client,
				permit_type = coalesce(left(nullif(btrim(r ->> 'permit_type'), ''), 120), pp.permit_type),
				applicant_type = coalesce(left(nullif(btrim(r ->> 'applicant_type'), ''), 120), pp.applicant_type),
				company_name = coalesce(left(nullif(btrim(r ->> 'company_name'), ''), 200), pp.company_name),
				activities = coalesce((select nullif(array_agg(left(btrim(a), 80) order by ord), '{}') from jsonb_array_elements_text(
					case when jsonb_typeof(r -> 'activities') = 'array' then r -> 'activities' else '[]'::jsonb end) with ordinality t(a, ord)
					where nullif(btrim(a), '') is not null), pp.activities),
				date_to = coalesce(v_expiry, pp.date_to),
				firearm_confirm = coalesce(case when jsonb_typeof(r -> 'firearms_permitted') = 'boolean' then (r ->> 'firearms_permitted')::boolean end, pp.firearm_confirm),
				firearm_licence_valid = coalesce(case when jsonb_typeof(r -> 'firearm_licence_valid') = 'boolean' then (r ->> 'firearm_licence_valid')::boolean end, pp.firearm_licence_valid),
				firearm_licence_number = coalesce(left(nullif(btrim(r ->> 'firearm_licence_number'), ''), 60), pp.firearm_licence_number),
				conditions = coalesce(left(nullif(btrim(r ->> 'conditions'), ''), 4000), pp.conditions),
				address_text = coalesce(left(nullif(btrim(r ->> 'address'), ''), 500), pp.address_text),
				status = v_status,
				contact_email = coalesce(left(nullif(lower(btrim(r ->> 'contact_email')), ''), 254), pp.contact_email),
				contact_phone = coalesce(left(nullif(btrim(r ->> 'contact_phone'), ''), 40), pp.contact_phone),
				compliance_checked_at = now(),
				compliance_source = 'import',
				source_document = 'Base44 RAMS (OFO)',
				updated_at = now()
			where pp.id = v_permit;
			v_updated := v_updated + 1;
		end if;

		for v in select x from jsonb_array_elements(case when jsonb_typeof(r -> 'vehicles') = 'array' then r -> 'vehicles' else '[]'::jsonb end) x loop
			v_plate := upper(regexp_replace(coalesce(v ->> 'plate', ''), '[^A-Za-z0-9]', '', 'g'));
			continue when v_plate !~ '^[A-Z0-9]{2,8}$';
			insert into public.canonical_vehicles (plate_number, make, model, colour, compliance_source, compliance_checked_at)
			values (v_plate, left(nullif(btrim(v ->> 'make'), ''), 60), left(nullif(btrim(v ->> 'model'), ''), 60),
				left(nullif(btrim(v ->> 'colour'), ''), 40), 'canonical', now())
			on conflict (plate_number) do update set
				make = coalesce(public.canonical_vehicles.make, excluded.make),
				model = coalesce(public.canonical_vehicles.model, excluded.model),
				colour = coalesce(public.canonical_vehicles.colour, excluded.colour)
			returning id into v_vehicle;
			insert into public.person_permit_vehicles (organization_id, permit_id, canonical_vehicle_id)
			values (p_provider_organization_id, v_permit, v_vehicle)
			on conflict (permit_id, canonical_vehicle_id) do nothing;
			get diagnostics v_rows = row_count;
			v_vehicles_linked := v_vehicles_linked + v_rows;
		end loop;
		v_permit := null;
		v_person := null;
	end loop;

	update public.hunter_kill_returns h
	set person_permit_id = pp.id
	from public.person_permits pp
	where h.organization_id = p_provider_organization_id
		and pp.organization_id = p_provider_organization_id
		and pp.permit_number = h.permit_number
		and h.person_permit_id is distinct from pp.id;

	insert into public.audit_log (organization_id, action, target_table, metadata)
	values (p_provider_organization_id, 'sync_base44_rams_permits', 'person_permits', jsonb_build_object(
		'source', 'base44_rams', 'received', jsonb_array_length(coalesce(p_rows, '[]'::jsonb)),
		'created', v_created, 'updated', v_updated, 'rejected', v_rejected,
		'people_created', v_people_created, 'people_needing_review', v_people_review, 'vehicles_linked', v_vehicles_linked));

	return jsonb_build_object('created', v_created, 'updated', v_updated, 'rejected', v_rejected,
		'people_created', v_people_created, 'people_needing_review', v_people_review, 'vehicles_linked', v_vehicles_linked);
end;
$function$;
COMMENT ON FUNCTION "public"."ingest_base44_rams_permits"(p_provider_organization_id uuid, p_rows jsonb) IS 'Server-only upsert of RAMS permits read from Base44 into person_permits (idempotent on organization_id, permit_number), with the holder resolved through their RAMS profile, else by email and normalised name within the provider (otherwise a draft keyed by the Base44 user id, flagged for review on a same-name clash) and permit vehicles linked through canonical_vehicles. Existing permits keep their linked person. Writes one audit_log entry per call.';
REVOKE ALL ON FUNCTION "public"."ingest_base44_rams_permits"(p_provider_organization_id uuid, p_rows jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."ingest_base44_rams_permits"(p_provider_organization_id uuid, p_rows jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."ingest_base44_rams_permits"(p_provider_organization_id uuid, p_rows jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."inherit_dispatch_charge_line_billing_basis"()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  SELECT j.billing_basis, j.extra_work_order_id INTO NEW.billing_basis, NEW.extra_work_order_id
  FROM public.dispatch_jobs j WHERE j.id = NEW.source_dispatch_id;
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."inherit_dispatch_charge_line_billing_basis"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."inherit_dispatch_charge_line_billing_basis"() TO "postgres";

CREATE OR REPLACE FUNCTION "public"."insert_adhoc_stop"(p_client_request_id uuid, p_dispatch_job_id uuid, p_shift_id uuid, p_expected_job_status text, p_expected_shift_updated_at timestamp with time zone, p_reason text)
 RETURNS TABLE(shift_stop_id uuid, created boolean, dispatch_status text, runsheet_shift_id uuid, stop_order integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_job public.dispatch_jobs%rowtype;
  v_shift public.shifts%rowtype;
  v_stop public.shift_stops%rowtype;
  v_receipt public.audit_log%rowtype;
  v_shift_agreement_id uuid;
  v_module_key text;
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
  v_max_order integer;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Active user required';
  END IF;
  IF p_client_request_id IS NULL THEN
    RAISE EXCEPTION 'client_request_id is required';
  END IF;
  IF p_dispatch_job_id IS NULL OR p_shift_id IS NULL THEN
    RAISE EXCEPTION 'Dispatch job and run sheet are required';
  END IF;
  IF p_expected_job_status IS NULL OR p_expected_shift_updated_at IS NULL THEN
    RAISE EXCEPTION 'Expected job and run-sheet state are required';
  END IF;
  IF v_reason IS NULL THEN
    RAISE EXCEPTION 'Reason is required';
  END IF;

  SELECT *
    INTO v_job
    FROM public.dispatch_jobs
   WHERE id = p_dispatch_job_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Dispatch job not found';
  END IF;
  IF NOT public.is_admin_for_org(v_job.organization_id) THEN
    RAISE EXCEPTION 'Active organization administrator required';
  END IF;

  SELECT *
    INTO v_receipt
    FROM public.audit_log
   WHERE organization_id = v_job.organization_id
     AND action = 'dispatch_job_runsheet_insert'
     AND target_table = 'shift_stops'
     AND metadata ->> 'client_request_id' = p_client_request_id::text;
  IF FOUND THEN
    IF v_receipt.metadata ->> 'dispatch_job_id' IS DISTINCT FROM p_dispatch_job_id::text
       OR v_receipt.metadata ->> 'shift_id' IS DISTINCT FROM p_shift_id::text THEN
      RAISE EXCEPTION 'client_request_id has already been used for a different run-sheet insertion';
    END IF;

    SELECT *
      INTO v_stop
      FROM public.shift_stops
     WHERE id = v_receipt.target_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'The prior run-sheet insertion receipt no longer resolves to a stop';
    END IF;

    RETURN QUERY
    SELECT v_stop.id, false, v_job.status, v_stop.shift_id, v_stop.stop_order;
    RETURN;
  END IF;

  SELECT *
    INTO v_shift
    FROM public.shifts
   WHERE id = p_shift_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Run sheet not found';
  END IF;
  IF v_shift.organization_id IS DISTINCT FROM v_job.organization_id THEN
    RAISE EXCEPTION 'Dispatch job and run sheet must belong to the same organization';
  END IF;

  IF v_job.shift_stop_id IS NOT NULL THEN
    SELECT *
      INTO v_stop
      FROM public.shift_stops
     WHERE id = v_job.shift_stop_id;
    IF NOT FOUND OR v_stop.shift_id IS DISTINCT FROM p_shift_id THEN
      RAISE EXCEPTION 'Dispatch job is already assigned to another run sheet';
    END IF;

    RETURN QUERY
    SELECT v_stop.id, false, v_job.status, v_stop.shift_id, v_stop.stop_order;
    RETURN;
  END IF;

  IF v_job.status IS DISTINCT FROM p_expected_job_status THEN
    RAISE EXCEPTION 'Dispatch job changed from expected status % to %', p_expected_job_status, v_job.status;
  END IF;
  IF v_job.status NOT IN ('pending', 'dispatched', 'acknowledged') THEN
    RAISE EXCEPTION 'Only pending, dispatched or acknowledged jobs can be added to a run sheet';
  END IF;
  IF v_shift.updated_at IS DISTINCT FROM p_expected_shift_updated_at THEN
    RAISE EXCEPTION 'Run sheet changed after it was opened. Refresh and review it before adding the job';
  END IF;
  IF v_shift.status NOT IN ('published', 'accepted', 'in_progress') THEN
    RAISE EXCEPTION 'Only published, accepted or in-progress run sheets can receive an urgent job';
  END IF;
  IF v_job.shift_id IS NOT NULL AND v_job.shift_id IS DISTINCT FROM p_shift_id THEN
    RAISE EXCEPTION 'Dispatch job is already assigned to another shift';
  END IF;
  IF v_job.assigned_officer_id IS NOT NULL
     AND v_job.assigned_officer_id IS DISTINCT FROM v_shift.officer_user_id THEN
    RAISE EXCEPTION 'The job is assigned to a different officer than this run sheet';
  END IF;
  IF (v_job.client_site_id IS NULL) = (v_job.zone_id IS NULL) THEN
    RAISE EXCEPTION 'Dispatch job must resolve to exactly one Site or Zone before run-sheet insertion';
  END IF;
  IF v_job.service_agreement_id IS NULL THEN
    RAISE EXCEPTION 'Dispatch job must have a service agreement before run-sheet insertion';
  END IF;

  SELECT coalesce(sal.service_agreement_id, sam.service_agreement_id)
    INTO v_shift_agreement_id
    FROM public.shifts s
    LEFT JOIN public.service_agreement_locations sal
      ON sal.id = s.service_agreement_location_id
    LEFT JOIN public.service_agreement_modules sam
      ON sam.id = s.service_agreement_module_id
   WHERE s.id = v_shift.id;

  IF v_shift_agreement_id IS NULL
     OR v_shift_agreement_id IS DISTINCT FROM v_job.service_agreement_id THEN
    RAISE EXCEPTION 'Run sheet and dispatch job must resolve to the same service agreement';
  END IF;
  IF NOT EXISTS (
    SELECT 1
      FROM public.service_agreement_locations sal
     WHERE sal.service_agreement_id = v_job.service_agreement_id
       AND sal.status = 'active'
       AND (
         (v_job.client_site_id IS NOT NULL AND sal.site_id = v_job.client_site_id)
         OR (v_job.zone_id IS NOT NULL AND sal.zone_id = v_job.zone_id)
       )
  ) THEN
    RAISE EXCEPTION 'Dispatch place is not active under the run sheet service agreement';
  END IF;
  IF v_job.module_key IS NOT NULL
     AND v_shift.module_key IS NOT NULL
     AND v_job.module_key IS DISTINCT FROM v_shift.module_key THEN
    RAISE EXCEPTION 'Dispatch job module does not match the selected run sheet';
  END IF;

  v_module_key := coalesce(v_job.module_key, v_shift.module_key, v_shift.service_type);
  IF v_module_key IS NULL OR trim(v_module_key) = '' THEN
    RAISE EXCEPTION 'A canonical module is required for the run-sheet stop';
  END IF;

  SELECT coalesce(max(s.stop_order), 0)
    INTO v_max_order
    FROM public.shift_stops s
   WHERE s.shift_id = v_shift.id;

  INSERT INTO public.shift_stops (
    organization_id,
    shift_id,
    dispatch_job_id,
    site_id,
    zone_id,
    module_key,
    stop_order,
    visit_number,
    is_adhoc,
    sla_window_open,
    sla_arrive_by,
    required_dwell_minutes,
    status,
    sla_status,
    officer_instructions
  )
  VALUES (
    v_job.organization_id,
    v_shift.id,
    v_job.id,
    v_job.client_site_id,
    v_job.zone_id,
    v_module_key,
    v_max_order + 10,
    1,
    true,
    v_job.created_at,
    coalesce(
      v_job.sla_respond_by,
      v_job.created_at + make_interval(mins => greatest(coalesce(v_job.sla_minutes, 15), 1))
    ),
    greatest(coalesce(v_job.expected_dwell_minutes, 5), 1),
    'pending',
    CASE
      WHEN coalesce(
        v_job.sla_respond_by,
        v_job.created_at + make_interval(mins => greatest(coalesce(v_job.sla_minutes, 15), 1))
      ) < now() THEN 'breached'
      ELSE 'on_track'
    END,
    v_job.briefing_notes
  )
  RETURNING * INTO v_stop;

  UPDATE public.dispatch_jobs
     SET shift_id = v_shift.id,
         shift_stop_id = v_stop.id,
         assigned_officer_id = coalesce(assigned_officer_id, v_shift.officer_user_id),
         adhoc_inserted_at = now(),
         status = 'dispatched',
         dispatched_at = coalesce(dispatched_at, now())
   WHERE id = v_job.id;

  UPDATE public.shifts
     SET total_stops = total_stops + 1,
         updated_at = now()
   WHERE id = v_shift.id;

  UPDATE public.patrol_solve_cache
     SET invalidated_at = now(),
         invalidation_reason = 'dispatch_job_runsheet_insert'
   WHERE shift_id = v_shift.id;

  INSERT INTO public.audit_log (
    organization_id,
    actor_user_id,
    action,
    target_table,
    target_id,
    metadata
  )
  VALUES (
    v_job.organization_id,
    v_actor,
    'dispatch_job_runsheet_insert',
    'shift_stops',
    v_stop.id,
    jsonb_build_object(
      'client_request_id', p_client_request_id,
      'dispatch_job_id', v_job.id,
      'shift_id', v_shift.id,
      'officer_user_id', v_shift.officer_user_id,
      'service_agreement_id', v_job.service_agreement_id,
      'site_id', v_job.client_site_id,
      'zone_id', v_job.zone_id,
      'module_key', v_module_key,
      'stop_order', v_stop.stop_order,
      'previous_job_status', v_job.status,
      'new_job_status', 'dispatched',
      'reason', v_reason
    )
  );

  RETURN QUERY
  SELECT v_stop.id, true, 'dispatched'::text, v_stop.shift_id, v_stop.stop_order;
END;
$function$;
COMMENT ON FUNCTION "public"."insert_adhoc_stop"(p_client_request_id uuid, p_dispatch_job_id uuid, p_shift_id uuid, p_expected_job_status text, p_expected_shift_updated_at timestamp with time zone, p_reason text) IS 'Adds an eligible dispatch job to one current officer run sheet. Requires administrator authority, exact organization/agreement/place/officer alignment, optimistic job and shift state, replay identity, and writes an audit receipt.';
REVOKE ALL ON FUNCTION "public"."insert_adhoc_stop"(p_client_request_id uuid, p_dispatch_job_id uuid, p_shift_id uuid, p_expected_job_status text, p_expected_shift_updated_at timestamp with time zone, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."insert_adhoc_stop"(p_client_request_id uuid, p_dispatch_job_id uuid, p_shift_id uuid, p_expected_job_status text, p_expected_shift_updated_at timestamp with time zone, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."insert_adhoc_stop"(p_client_request_id uuid, p_dispatch_job_id uuid, p_shift_id uuid, p_expected_job_status text, p_expected_shift_updated_at timestamp with time zone, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."insert_adhoc_stop"(p_client_request_id uuid, p_dispatch_job_id uuid, p_shift_id uuid, p_expected_job_status text, p_expected_shift_updated_at timestamp with time zone, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."invite_client_capability_share"(p_service_agreement_id uuid, p_capability text, p_email text)
 RETURNS onboarding_invites
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_agreement public.service_agreements%rowtype;
  v_invite_kind text;
  v_email text := lower(trim(coalesce(p_email, '')));
  v_token text := encode(extensions.gen_random_bytes(32), 'hex');
  v_invite public.onboarding_invites%rowtype;
BEGIN
  IF p_capability NOT IN ('reporting', 'finance') THEN
    RAISE EXCEPTION 'capability must be reporting or finance';
  END IF;
  v_invite_kind := p_capability || '_share';
  IF v_email = '' OR v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' THEN
    RAISE EXCEPTION 'A valid email is required';
  END IF;

  SELECT * INTO v_agreement FROM public.service_agreements WHERE id = p_service_agreement_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Service agreement not found'; END IF;
  IF v_actor IS NULL OR NOT public.is_admin_for_org(v_agreement.provider_organization_id) THEN
    RAISE EXCEPTION 'Provider administrator required';
  END IF;

  INSERT INTO public.onboarding_invites (target_organization_id, service_agreement_id, invited_by, email, token_hash, invite_kind, status, expires_at)
  VALUES (v_agreement.client_organization_id, v_agreement.id, v_actor, v_email, encode(extensions.digest(v_token, 'sha256'), 'hex'), v_invite_kind, 'pending', now() + interval '14 days')
  RETURNING * INTO v_invite;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_agreement.provider_organization_id, v_actor, 'client_capability_share_invited', 'onboarding_invites', v_invite.id, jsonb_build_object('service_agreement_id', v_agreement.id, 'capability', p_capability, 'email', v_email));

  -- Plaintext token returned once, to the inviter, for delivery out-of-band.
  v_invite.token_hash := v_token;
  RETURN v_invite;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."invite_client_capability_share"(p_service_agreement_id uuid, p_capability text, p_email text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."invite_client_capability_share"(p_service_agreement_id uuid, p_capability text, p_email text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."invite_client_capability_share"(p_service_agreement_id uuid, p_capability text, p_email text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."invite_client_capability_share"(p_service_agreement_id uuid, p_capability text, p_email text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."invoice_due_date"(p_invoice_date date, p_period_end date, p_terms_days integer, p_due_day integer)
 RETURNS date
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN p_due_day IS NULL THEN p_invoice_date + coalesce(p_terms_days, 14)
    -- The due day of the month after the work, rolled to the next one if the invoice is raised after it.
    ELSE greatest(
      (date_trunc('month', coalesce(p_period_end, p_invoice_date)) + interval '1 month')::date + (p_due_day - 1),
      (date_trunc('month', p_invoice_date) + CASE WHEN extract(day FROM p_invoice_date) > p_due_day THEN interval '1 month' ELSE interval '0 days' END)::date + (p_due_day - 1))
  END
$function$;
COMMENT ON FUNCTION "public"."invoice_due_date"(p_invoice_date date, p_period_end date, p_terms_days integer, p_due_day integer) IS 'Invoice due date: with a due day, that day of the month after the period end (invoice date when no period), never before the invoice date; otherwise the invoice date plus the payment terms days (default 14).';
REVOKE ALL ON FUNCTION "public"."invoice_due_date"(p_invoice_date date, p_period_end date, p_terms_days integer, p_due_day integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."invoice_due_date"(p_invoice_date date, p_period_end date, p_terms_days integer, p_due_day integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."invoice_due_date"(p_invoice_date date, p_period_end date, p_terms_days integer, p_due_day integer) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."invoice_due_date"(p_invoice_date date, p_period_end date, p_terms_days integer, p_due_day integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."is_admin_for_org"(target_org_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1 from user_profiles
    where id = auth.uid()
      and deactivated_at is null
      and role in ('grand_master', 'master', 'admin', 'admin_officer')
      and (
        role = 'grand_master'
        or (role = 'master' and (
          target_org_id = any (public.get_descendant_organizations(employer_organization_id))
          or target_org_id = any (public.get_descendant_organizations(organization_id))
          or exists (
            select 1 from public.service_agreements sa
            where (sa.ends_on is null or sa.ends_on >= current_date)
              and sa.agreement_type = 'operational'
              and sa.client_organization_id = target_org_id
              and (organization_id = sa.provider_organization_id
                   or employer_organization_id = sa.provider_organization_id)
          )
        ))
        or (role IN ('admin', 'admin_officer') and (
          organization_id = target_org_id
          or target_org_id = any (public.get_descendant_organizations(organization_id))
          or exists (
            select 1 from public.service_agreements sa
            where (sa.ends_on is null or sa.ends_on >= current_date)
              and sa.agreement_type = 'operational'
              and sa.client_organization_id = target_org_id
              and (organization_id = sa.provider_organization_id
                   or employer_organization_id = sa.provider_organization_id)
          )
        ))
      )
  );
$function$;
COMMENT ON FUNCTION "public"."is_admin_for_org"(target_org_id uuid) IS 'Returns true if the current active user is admin, master, or grand_master for the target org. Admin/master check the org descendant tree (via get_descendant_organizations) and agreement-based provider access on OPERATIONAL agreements only (0271 Model A; financial agreements excluded — owner ruling 2026-09-15). Grand master has unrestricted access.';
REVOKE ALL ON FUNCTION "public"."is_admin_for_org"(target_org_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."is_admin_for_org"(target_org_id uuid) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."is_admin_for_org"(target_org_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."is_admin_for_org"(target_org_id uuid) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."is_admin_for_org"(target_org_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."is_admin_for_org"(target_org_id uuid) TO "service_role";

