CREATE OR REPLACE FUNCTION "public"."is_zone_closed"(p_zone_id uuid, p_at timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
  select jsonb_build_object(
    'closed',       true,
    'closure_id',   c.id,
    'closure_type', c.closure_type,
    'reason',       c.reason,
    'effective_from', c.effective_from,
    'effective_to',   c.effective_to
  )
  from zone_closures c
  where c.zone_id = p_zone_id
    and c.status <> 'lifted'
    and c.effective_from <= (p_at at time zone 'Pacific/Auckland')::date
    and (c.effective_to is null
         or c.effective_to >= (p_at at time zone 'Pacific/Auckland')::date)
  order by
    case c.closure_type
      when 'prohibited' then 0
      when 'restricted' then 1
      else 2
    end asc,
    c.effective_from desc
  limit 1;
$function$;
COMMENT ON FUNCTION "public"."is_zone_closed"(p_zone_id uuid, p_at timestamp with time zone) IS 'Returns the in-force closure for a zone at p_at as JSON (closed, closure_id, closure_type, reason, dates), or NULL when the zone is open. prohibited > restricted > temporary_closure. Dates compared in Pacific/Auckland.';
REVOKE ALL ON FUNCTION "public"."is_zone_closed"(p_zone_id uuid, p_at timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."is_zone_closed"(p_zone_id uuid, p_at timestamp with time zone) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."is_zone_closed"(p_zone_id uuid, p_at timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."is_zone_closed"(p_zone_id uuid, p_at timestamp with time zone) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."is_zone_closed"(p_zone_id uuid, p_at timestamp with time zone) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."is_zone_closed"(p_zone_id uuid, p_at timestamp with time zone) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."issue_cctv_export"(p_export_id uuid, p_artifact_bucket text, p_artifact_path text)
 RETURNS cctv_exports
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  actor_id uuid := auth.uid();
  export_row public.cctv_exports;
  expected_path text;
BEGIN
  IF actor_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT *
    INTO export_row
    FROM public.cctv_exports
   WHERE id = p_export_id
   FOR UPDATE;

  IF NOT FOUND OR NOT public.is_admin_for_org(export_row.organization_id) THEN
    RAISE EXCEPTION 'CCTV export not found or administrator access denied';
  END IF;
  IF export_row.approval_state <> 'sealed' THEN
    RAISE EXCEPTION 'Only sealed exports may be issued';
  END IF;

  expected_path := format(
    'cctv-exports/%s/%s/manifest-%s.json',
    export_row.organization_id,
    export_row.id,
    export_row.manifest_sha256
  );
  IF p_artifact_bucket <> 'bob-uploads' OR p_artifact_path <> expected_path THEN
    RAISE EXCEPTION 'CCTV export artifact must use its governed private manifest path';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM storage.objects object
    WHERE object.bucket_id = p_artifact_bucket
      AND object.name = p_artifact_path
  ) THEN
    RAISE EXCEPTION 'CCTV export artifact has not been uploaded';
  END IF;

  UPDATE public.cctv_exports
     SET approval_state = 'issued',
         artifact_bucket = p_artifact_bucket,
         artifact_path = p_artifact_path,
         issued_at = clock_timestamp()
   WHERE id = p_export_id
   RETURNING * INTO export_row;

  INSERT INTO public.audit_log (
    organization_id,
    actor_user_id,
    action,
    target_table,
    target_id,
    metadata
  )
  VALUES (
    export_row.organization_id,
    actor_id,
    'cctv_export_issued',
    'cctv_exports',
    p_export_id,
    jsonb_build_object(
      'previous_state', 'sealed',
      'artifact_bucket', p_artifact_bucket,
      'artifact_path', p_artifact_path,
      'manifest_sha256', export_row.manifest_sha256
    )
  );

  RETURN export_row;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."issue_cctv_export"(p_export_id uuid, p_artifact_bucket text, p_artifact_path text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."issue_cctv_export"(p_export_id uuid, p_artifact_bucket text, p_artifact_path text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."issue_cctv_export"(p_export_id uuid, p_artifact_bucket text, p_artifact_path text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."issue_cctv_export"(p_export_id uuid, p_artifact_bucket text, p_artifact_path text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."issue_cctv_report_receipt"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_batch_id text, p_payload jsonb)
 RETURNS TABLE(report_id uuid, generated_at timestamp with time zone, observation_count integer, sha256 text, provenance jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  actor_id uuid := auth.uid();
  generated timestamptz := clock_timestamp();
  receipt_id uuid := gen_random_uuid();
  v_evidence public.evidence_items%rowtype;
  v_job public.inference_jobs%rowtype;
  v_import public.cctv_imports%rowtype;
  v_place record;
  v_result record;
  v_review record;
  v_legacy record;
  v_prior record;
  v_provenance jsonb;
  v_payload jsonb;
  payload_hash text;
  count_observations integer;
  v_claimed_status text := p_payload->>'report_status';
BEGIN
  IF actor_id IS NULL OR NOT public.org_access_allowed(p_organization_id) THEN RAISE EXCEPTION 'CCTV report access denied'; END IF;
  IF jsonb_typeof(p_payload) <> 'object' THEN RAISE EXCEPTION 'CCTV report payload must be an object'; END IF;

  SELECT * INTO v_job FROM public.inference_jobs
   WHERE id = p_job_id AND evidence_item_id = p_evidence_id AND organization_id = p_organization_id AND domain IN ('video_motion', 'vehicle', 'face');
  IF v_job.id IS NULL THEN RAISE EXCEPTION 'CCTV job or evidence is missing or outside the organization'; END IF;
  SELECT * INTO v_evidence FROM public.evidence_items WHERE id = p_evidence_id AND organization_id = p_organization_id;
  IF v_evidence.id IS NULL THEN RAISE EXCEPTION 'CCTV job or evidence is missing or outside the organization'; END IF;
  IF v_evidence.cctv_import_id IS NOT NULL THEN
    SELECT * INTO v_import FROM public.cctv_imports WHERE id = v_evidence.cctv_import_id;
    SELECT l.name, l.address INTO v_place FROM public.locations l WHERE l.id = v_import.location_id;
  END IF;
  SELECT r.id, r.status, r.created_at, r.result->'classification_plan' AS classification_plan,
         r.result->>'worker_version' AS worker_version, r.result->>'model_version' AS model_version
    INTO v_result
    FROM public.inference_results r WHERE r.inference_job_id = v_job.id ORDER BY r.created_at DESC LIMIT 1;
  SELECT count(*) AS total,
         count(*) FILTER (WHERE o.review_state = 'accepted') AS accepted,
         count(*) FILTER (WHERE o.review_state = 'rejected') AS rejected,
         count(*) FILTER (WHERE o.review_state = 'unreviewed') AS unreviewed,
         count(*) FILTER (WHERE o.review_state IN ('uncertain', 'needs_more_context')) AS undecided,
         max(o.reviewed_at) AS last_reviewed_at
    INTO v_review
    FROM public.cctv_entity_observations o WHERE o.evidence_item_id = v_evidence.id;
  SELECT count(*) AS decisions, max(d.decided_at) AS last_decided_at INTO v_legacy
    FROM public.cctv_review_decisions d WHERE d.evidence_item_id = v_evidence.id;
  SELECT count(*) AS receipts, max(r.generated_at) AS latest_at,
         (array_agg(r.id ORDER BY r.generated_at DESC))[1] AS latest_id
    INTO v_prior
    FROM public.cctv_report_receipts r WHERE r.evidence_item_id = v_evidence.id;

  count_observations := jsonb_array_length(CASE WHEN jsonb_typeof(p_payload->'observations') = 'array' THEN p_payload->'observations' ELSE '[]'::jsonb END);

  v_provenance := jsonb_strip_nulls(jsonb_build_object(
    'receipt_id', receipt_id,
    'issued_at', generated,
    'issued_by', actor_id,
    'claimed_report_status', v_claimed_status,
    'evidence', jsonb_build_object(
      'id', v_evidence.id, 'storage_path', v_evidence.storage_path, 'captured_at', v_evidence.captured_at,
      'sha256_hash', v_evidence.sha256_hash, 'source_size_bytes', (v_evidence.metadata->>'source_size_bytes')::bigint,
      'is_court_ready', v_evidence.is_court_ready, 'locked_at', v_evidence.locked_at, 'retention_hold', v_evidence.retention_hold,
      'integrity_state', v_evidence.metadata->'integrity'->>'state', 'integrity_checked_at', v_evidence.metadata->'integrity'->>'checked_at'),
    'import', CASE WHEN v_import.id IS NULL THEN NULL ELSE jsonb_build_object(
      'id', v_import.id, 'camera_label', v_import.camera_label, 'camera_key', v_import.camera_key,
      'source_device_kind', v_import.source_device_kind, 'source_timezone', v_import.source_timezone,
      'location_id', v_import.location_id, 'canonical_place_id', v_import.canonical_place_id,
      'place_name', v_place.name, 'place_address', v_place.address) END,
    'job', jsonb_build_object('id', v_job.id, 'domain', v_job.domain, 'status', v_job.status, 'completed_at', v_job.completed_at, 'attempt_count', v_job.attempt_count),
    'result', CASE WHEN v_result.id IS NULL THEN NULL ELSE jsonb_build_object(
      'inference_result_id', v_result.id, 'status', v_result.status, 'created_at', v_result.created_at,
      'classification_plan', v_result.classification_plan, 'worker_version', v_result.worker_version, 'model_version', v_result.model_version) END,
    'review', jsonb_build_object(
      'observations_total', v_review.total, 'accepted', v_review.accepted, 'rejected', v_review.rejected,
      'unreviewed', v_review.unreviewed, 'undecided', v_review.undecided, 'last_reviewed_at', v_review.last_reviewed_at,
      'legacy_decisions', v_legacy.decisions, 'legacy_last_decided_at', v_legacy.last_decided_at),
    'review_consistency', CASE
      WHEN v_claimed_status = 'review_ready' AND (v_review.unreviewed + v_review.undecided) > 0 THEN 'client_claims_review_ready_but_database_holds_undecided_sightings'
      WHEN v_claimed_status = 'review_ready' THEN 'consistent'
      ELSE 'draft' END,
    'supersedes', CASE WHEN v_prior.receipts > 0 THEN jsonb_build_object('receipt_id', v_prior.latest_id, 'issued_at', v_prior.latest_at, 'earlier_receipts', v_prior.receipts) ELSE NULL END
  ));

  v_payload := p_payload || jsonb_build_object('provenance', v_provenance);
  payload_hash := encode(digest(convert_to(v_payload::text, 'UTF8'), 'sha256'), 'hex');

  INSERT INTO public.cctv_report_receipts (id, organization_id, inference_job_id, evidence_item_id, batch_id, generated_by, generated_at, observation_count, payload, sha256)
  VALUES (receipt_id, p_organization_id, p_job_id, p_evidence_id, NULLIF(trim(p_batch_id), ''), actor_id, generated, count_observations, v_payload, payload_hash);

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (p_organization_id, actor_id, 'cctv_report_receipt_issued', 'cctv_report_receipts', receipt_id,
          jsonb_strip_nulls(jsonb_build_object('inference_job_id', p_job_id, 'evidence_item_id', p_evidence_id, 'batch_id', p_batch_id,
            'observation_count', count_observations, 'sha256', payload_hash, 'evidence_sha256', v_evidence.sha256_hash,
            'claimed_report_status', v_claimed_status, 'review_consistency', v_provenance->>'review_consistency',
            'supersedes_receipt_id', v_provenance->'supersedes'->>'receipt_id')));

  RETURN QUERY SELECT receipt_id, generated, count_observations, payload_hash, v_provenance;
END $function$;
COMMENT ON FUNCTION "public"."issue_cctv_report_receipt"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_batch_id text, p_payload jsonb) IS 'Issues an immutable receipt for a CCTV report. The server appends a provenance block (evidence hash/lock/integrity, camera and place, job and inference result, database review counts, superseded receipts, review_consistency) before hashing. Returns the hash and the provenance for printing.';
REVOKE ALL ON FUNCTION "public"."issue_cctv_report_receipt"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_batch_id text, p_payload jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."issue_cctv_report_receipt"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_batch_id text, p_payload jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."issue_cctv_report_receipt"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_batch_id text, p_payload jsonb) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."issue_cctv_report_receipt"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_batch_id text, p_payload jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."jsonb_object_length"(p_value jsonb)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'pg_catalog'
AS $function$
  SELECT count(*)::integer
  FROM jsonb_object_keys(coalesce(p_value, '{}'::jsonb));
$function$;
COMMENT ON FUNCTION "public"."jsonb_object_length"(p_value jsonb) IS 'Returns the number of top-level keys in a JSON object. Used by manage_identity_vehicle shared-record protection.';
REVOKE ALL ON FUNCTION "public"."jsonb_object_length"(p_value jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."jsonb_object_length"(p_value jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."jsonb_object_length"(p_value jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."link_cctv_resident_vehicle_observations"(p_job_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_obs public.cctv_entity_observations%rowtype;
  v_resident public.cctv_resident_objects%rowtype;
  v_camera text;
  v_colour text;
  v_end timestamptz;
  v_sightings integer;
  v_count integer := 0;
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' AND session_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.inference_jobs WHERE id = p_job_id) THEN
    RAISE EXCEPTION 'CCTV inference job is missing';
  END IF;
  FOR v_obs IN
    SELECT * FROM public.cctv_entity_observations
     WHERE inference_job_id = p_job_id
       AND entity_kind = 'vehicle'
       AND review_state = 'unreviewed'
       AND attributes->>'motion_state' = 'stationary'
       AND jsonb_typeof(attributes->'bbox') = 'object'
       AND NOT (attributes ? 'resident_object_id')
     ORDER BY observed_at, id
  LOOP
    SELECT coalesce(nullif(evidence.metadata->>'camera_key', ''), nullif(import.camera_key, ''))
      INTO v_camera
      FROM public.evidence_items evidence
      LEFT JOIN public.cctv_imports import ON import.id = v_obs.cctv_import_id
     WHERE evidence.id = v_obs.evidence_item_id;
    IF v_camera IS NULL THEN CONTINUE; END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended(v_obs.organization_id::text || ':' || v_camera || ':resident-object', 0));
    v_colour := nullif(lower(trim(coalesce(v_obs.attributes->>'colour', ''))), '');
    v_end := coalesce(v_obs.observed_to, v_obs.observed_at);
    v_resident.id := NULL;
    SELECT resident.* INTO v_resident
      FROM public.cctv_resident_objects resident
     WHERE resident.organization_id = v_obs.organization_id
       AND resident.camera_key = v_camera
       AND resident.last_seen_at >= v_obs.observed_at - interval '14 days'
       AND resident.first_seen_at <= v_end + interval '14 days'
       AND public.cctv_bbox_iou(resident.bbox, v_obs.attributes->'bbox') >= 0.6
       AND (resident.candidate_plate IS NULL OR v_obs.candidate_plate IS NULL OR resident.candidate_plate = v_obs.candidate_plate)
       AND (resident.colour IS NULL OR v_colour IS NULL OR resident.colour = v_colour)
     ORDER BY public.cctv_bbox_iou(resident.bbox, v_obs.attributes->'bbox') DESC, resident.last_seen_at DESC
     LIMIT 1
     FOR UPDATE;
    IF v_resident.id IS NULL THEN
      INSERT INTO public.cctv_resident_objects (
        organization_id, camera_key, bbox, candidate_plate, colour, portfolio_key,
        first_seen_at, last_seen_at, anchor_observation_id, last_observation_id
      ) VALUES (
        v_obs.organization_id, v_camera, v_obs.attributes->'bbox', v_obs.candidate_plate, v_colour,
        coalesce(v_obs.portfolio_key, gen_random_uuid()), v_obs.observed_at, v_end, v_obs.id, v_obs.id
      ) RETURNING * INTO v_resident;
      v_sightings := 1;
    ELSE
      -- Counted from the linked rows, not incremented, so reprocessing a clip cannot inflate the count.
      SELECT count(*) + 1 INTO v_sightings
        FROM public.cctv_entity_observations linked
       WHERE linked.organization_id = v_obs.organization_id
         AND linked.entity_kind = 'vehicle'
         AND linked.review_state <> 'superseded'
         AND linked.attributes->>'resident_object_id' = v_resident.id::text;
      UPDATE public.cctv_resident_objects
         SET first_seen_at = least(first_seen_at, v_obs.observed_at),
             last_seen_at = greatest(last_seen_at, v_end),
             candidate_plate = coalesce(candidate_plate, v_obs.candidate_plate),
             colour = coalesce(colour, v_colour),
             sighting_count = v_sightings,
             last_observation_id = v_obs.id,
             updated_at = clock_timestamp()
       WHERE id = v_resident.id
      RETURNING * INTO v_resident;
    END IF;
    UPDATE public.cctv_entity_observations
       SET portfolio_key = v_resident.portfolio_key,
           portfolio_state = CASE WHEN v_sightings > 1 AND portfolio_state = 'unmatched' THEN 'candidate' ELSE portfolio_state END,
           attributes = attributes || jsonb_strip_nulls(jsonb_build_object(
             'resident_object_id', v_resident.id,
             'resident_first_seen_at', v_resident.first_seen_at,
             'resident_sighting_count', v_sightings,
             'portfolio_key_before_resident_link', CASE WHEN portfolio_key IS DISTINCT FROM v_resident.portfolio_key THEN portfolio_key END))
     WHERE id = v_obs.id AND review_state = 'unreviewed';
    IF FOUND THEN v_count := v_count + 1; END IF;
  END LOOP;
  RETURN v_count;
END;
$function$;
COMMENT ON FUNCTION "public"."link_cctv_resident_vehicle_observations"(p_job_id uuid) IS 'Service-only, run after stationary coalescing. Links unreviewed stationary vehicle sightings to a resident object on the same camera (bbox IoU >= 0.6, compatible plate and colour, within 14 days) and gives them its provisional portfolio. Reviewed rows are never changed.';
REVOKE ALL ON FUNCTION "public"."link_cctv_resident_vehicle_observations"(p_job_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."link_cctv_resident_vehicle_observations"(p_job_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."link_cctv_resident_vehicle_observations"(p_job_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."link_investigation_entity"(p_investigation_id uuid, p_entity_type text, p_entity_id uuid, p_link_role text, p_link_reason text)
 RETURNS investigation_links
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_actor uuid := auth.uid(); v_item public.investigations%rowtype; v_link public.investigation_links%rowtype; v_exists boolean;
BEGIN
  SELECT * INTO v_item FROM public.investigations WHERE id=p_investigation_id FOR UPDATE;
  IF NOT FOUND OR v_actor IS NULL OR NOT public.is_admin_for_org(v_item.organization_id) THEN RAISE EXCEPTION 'Investigation access denied'; END IF;
  IF nullif(trim(p_link_reason),'') IS NULL THEN RAISE EXCEPTION 'Link reason is required'; END IF;

  v_exists := CASE p_entity_type
    WHEN 'field_report' THEN EXISTS (SELECT 1 FROM public.officer_field_reports WHERE id = p_entity_id AND organization_id = v_item.organization_id)
    WHEN 'incident' THEN EXISTS (SELECT 1 FROM public.incidents WHERE id = p_entity_id AND organization_id = v_item.organization_id)
    WHEN 'observation' THEN EXISTS (SELECT 1 FROM public.observations WHERE id = p_entity_id AND organization_id = v_item.organization_id)
    WHEN 'evidence' THEN EXISTS (SELECT 1 FROM public.evidence_items WHERE id = p_entity_id AND organization_id = v_item.organization_id)
    WHEN 'site' THEN EXISTS (SELECT 1 FROM public.client_sites WHERE id = p_entity_id AND organization_id = v_item.organization_id)
    WHEN 'zone' THEN EXISTS (SELECT 1 FROM public.location_zones WHERE id = p_entity_id AND organization_id = v_item.organization_id)
    WHEN 'dispatch_job' THEN EXISTS (SELECT 1 FROM public.dispatch_jobs WHERE id = p_entity_id AND organization_id = v_item.organization_id)
    WHEN 'person' THEN EXISTS (SELECT 1 FROM public.canonical_people WHERE id = p_entity_id)
    WHEN 'vehicle' THEN EXISTS (SELECT 1 FROM public.canonical_vehicles WHERE id = p_entity_id)
    ELSE false
  END;
  IF NOT v_exists THEN RAISE EXCEPTION 'Entity % % not found in this organization', p_entity_type, p_entity_id; END IF;

  SELECT * INTO v_link FROM public.investigation_links WHERE investigation_id=p_investigation_id AND entity_type=p_entity_type AND entity_id=p_entity_id;
  IF FOUND THEN RETURN v_link; END IF;
  INSERT INTO public.investigation_links (investigation_id, organization_id, entity_type, entity_id, link_role, link_reason, linked_by)
  VALUES (p_investigation_id, v_item.organization_id, p_entity_type, p_entity_id, p_link_role, trim(p_link_reason), v_actor)
  RETURNING * INTO v_link;
  IF p_entity_type='field_report' THEN UPDATE public.officer_field_reports SET investigation_id=p_investigation_id WHERE id=p_entity_id AND organization_id=v_item.organization_id; END IF;
  IF p_entity_type='incident' THEN UPDATE public.incidents SET investigation_id=p_investigation_id WHERE id=p_entity_id AND organization_id=v_item.organization_id; END IF;
  INSERT INTO public.investigation_events (investigation_id, organization_id, event_type, description, source_table, source_id, created_by)
  VALUES (p_investigation_id, v_item.organization_id, 'entity_linked', p_entity_type || ' linked: ' || trim(p_link_reason), p_entity_type, p_entity_id, v_actor);
  RETURN v_link;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."link_investigation_entity"(p_investigation_id uuid, p_entity_type text, p_entity_id uuid, p_link_role text, p_link_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."link_investigation_entity"(p_investigation_id uuid, p_entity_type text, p_entity_id uuid, p_link_role text, p_link_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."link_investigation_entity"(p_investigation_id uuid, p_entity_type text, p_entity_id uuid, p_link_role text, p_link_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."link_investigation_entity"(p_investigation_id uuid, p_entity_type text, p_entity_id uuid, p_link_role text, p_link_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."link_nzta_register_lookup_check"(p_lookup_id uuid, p_check_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_lookup public.nzta_register_lookups%rowtype;
  v_check public.vehicle_identity_checks%rowtype;
  v_check_plate text;
  v_check_vin text;
BEGIN
  SELECT * INTO v_lookup FROM public.nzta_register_lookups WHERE id = p_lookup_id FOR UPDATE;
  IF v_actor IS NULL OR v_lookup.id IS NULL OR NOT public.is_admin_for_org(v_lookup.organization_id) THEN
    RAISE EXCEPTION 'Organisation administrator required' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_check FROM public.vehicle_identity_checks
  WHERE id = p_check_id AND organization_id = v_lookup.organization_id;
  IF v_check.id IS NULL THEN RAISE EXCEPTION 'That NZTA check is not in this organisation'; END IF;
  IF length(btrim(coalesce(p_reason, ''))) < 5 THEN RAISE EXCEPTION 'A reason is required'; END IF;
  IF v_lookup.vehicle_identity_check_id IS NOT NULL THEN
    RAISE EXCEPTION 'This lookup is already linked to an NZTA check';
  END IF;
  IF EXISTS (SELECT 1 FROM public.nzta_register_lookups WHERE vehicle_identity_check_id = p_check_id) THEN
    RAISE EXCEPTION 'That NZTA check is already linked to another lookup';
  END IF;
  SELECT upper(regexp_replace(coalesce(vehicle.plate_number, ''), '[^A-Za-z0-9]', '', 'g')), upper(vehicle.vin)
  INTO v_check_plate, v_check_vin
  FROM public.canonical_vehicles vehicle WHERE vehicle.id = v_check.canonical_vehicle_id;
  IF NOT (v_lookup.canonical_vehicle_id = v_check.canonical_vehicle_id
          OR (v_lookup.plate_number IS NOT NULL AND v_lookup.plate_number = v_check_plate)
          OR (v_lookup.vin IS NOT NULL AND v_lookup.vin = v_check_vin)) THEN
    RAISE EXCEPTION 'The lookup and the NZTA check are for different vehicles';
  END IF;
  UPDATE public.nzta_register_lookups
  SET vehicle_identity_check_id = p_check_id,
      canonical_vehicle_id = coalesce(canonical_vehicle_id, v_check.canonical_vehicle_id),
      updated_at = clock_timestamp()
  WHERE id = p_lookup_id;
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_lookup.organization_id, v_actor, 'nzta_register_lookup_check_linked', 'nzta_register_lookups', p_lookup_id,
    jsonb_build_object('vehicle_identity_check_id', p_check_id, 'reason', btrim(p_reason)));
END;
$function$;
REVOKE ALL ON FUNCTION "public"."link_nzta_register_lookup_check"(p_lookup_id uuid, p_check_id uuid, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."link_nzta_register_lookup_check"(p_lookup_id uuid, p_check_id uuid, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."link_nzta_register_lookup_check"(p_lookup_id uuid, p_check_id uuid, p_reason text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."link_observation_entities"(p_observation_id uuid, p_organization_id uuid, p_canonical_vehicle_id uuid DEFAULT NULL::uuid, p_person_record_id uuid DEFAULT NULL::uuid, p_site_id uuid DEFAULT NULL::uuid, p_zone_id uuid DEFAULT NULL::uuid, p_location_id uuid DEFAULT NULL::uuid, p_incident_id uuid DEFAULT NULL::uuid, p_identity_basis text DEFAULT NULL::text)
 RETURNS observations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  result public.observations;
  v_previous_person uuid;
  v_previous_vehicle uuid;
  v_plate text;
BEGIN
  IF auth.uid() IS NULL OR NOT public.org_access_allowed(p_organization_id) THEN
    RAISE EXCEPTION 'Observation access denied';
  END IF;
  IF (p_person_record_id IS NOT NULL OR p_canonical_vehicle_id IS NOT NULL)
     AND NOT private.rnm_admin_for_organization(p_organization_id) THEN
    RAISE EXCEPTION 'R&M administrator, master or grandmaster access required for identity links';
  END IF;
  SELECT o.person_record_id, o.canonical_vehicle_id INTO v_previous_person, v_previous_vehicle
  FROM public.observations o WHERE o.id = p_observation_id AND o.organization_id = p_organization_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Observation not found'; END IF;
  IF p_person_record_id IS NOT NULL AND p_person_record_id IS DISTINCT FROM v_previous_person
     AND nullif(trim(coalesce(p_identity_basis, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Record the basis for identifying this person';
  END IF;
  IF p_person_record_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.person_records pr
    JOIN public.canonical_person_links cpl ON cpl.source_table = 'person_records' AND cpl.source_id = pr.id AND cpl.organization_id = pr.organization_id
    JOIN public.canonical_people cp ON cp.id = cpl.canonical_person_id AND cp.review_state = 'verified' AND cp.status = 'active'
    WHERE pr.id = p_person_record_id AND pr.organization_id = p_organization_id AND pr.review_state = 'verified'
  ) THEN RAISE EXCEPTION 'Select a verified person record with a verified canonical identity'; END IF;
  IF p_site_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.client_sites
    WHERE id = p_site_id AND public.has_location_access(id, NULL, 'client_reads_provider')
  ) THEN RAISE EXCEPTION 'Site is outside the accessible organization'; END IF;
  IF p_zone_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.location_zones
    WHERE id = p_zone_id AND public.org_access_allowed(organization_id)
  ) THEN RAISE EXCEPTION 'Zone is outside the accessible organization'; END IF;
  IF p_incident_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.incidents
    WHERE id = p_incident_id AND public.org_access_allowed(organization_id)
  ) THEN RAISE EXCEPTION 'Incident is outside the accessible organization'; END IF;
  IF p_canonical_vehicle_id IS NOT NULL THEN
    SELECT upper(regexp_replace(o.plate_number, '[^A-Za-z0-9]', '', 'g')) INTO v_plate
    FROM public.observations o
    WHERE o.id = p_observation_id AND o.organization_id = p_organization_id;
    IF v_plate IS NULL OR NOT EXISTS (
      SELECT 1 FROM public.canonical_vehicles v
      WHERE v.id = p_canonical_vehicle_id
        AND upper(regexp_replace(v.plate_number, '[^A-Za-z0-9]', '', 'g')) = v_plate
    ) THEN RAISE EXCEPTION 'Canonical vehicle plate does not match the observation'; END IF;
  END IF;

  UPDATE public.observations
  SET canonical_vehicle_id = COALESCE(p_canonical_vehicle_id, canonical_vehicle_id),
      person_record_id = COALESCE(p_person_record_id, person_record_id),
      site_id = COALESCE(p_site_id, site_id),
      zone_id = COALESCE(p_zone_id, zone_id),
      location_id = COALESCE(p_location_id, location_id),
      incident_id = COALESCE(p_incident_id, incident_id)
  WHERE id = p_observation_id AND organization_id = p_organization_id
  RETURNING * INTO result;

  IF result.person_record_id IS DISTINCT FROM v_previous_person OR result.canonical_vehicle_id IS DISTINCT FROM v_previous_vehicle THEN
    INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
    VALUES (p_organization_id, auth.uid(), 'observation_identity_linked', 'observations', p_observation_id,
      jsonb_strip_nulls(jsonb_build_object(
        'previous_person_record_id', v_previous_person,
        'person_record_id', result.person_record_id,
        'previous_canonical_vehicle_id', v_previous_vehicle,
        'canonical_vehicle_id', result.canonical_vehicle_id,
        'identity_basis', nullif(trim(coalesce(p_identity_basis, '')), '')
      )));
  END IF;
  RETURN result;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."link_observation_entities"(p_observation_id uuid, p_organization_id uuid, p_canonical_vehicle_id uuid, p_person_record_id uuid, p_site_id uuid, p_zone_id uuid, p_location_id uuid, p_incident_id uuid, p_identity_basis text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."link_observation_entities"(p_observation_id uuid, p_organization_id uuid, p_canonical_vehicle_id uuid, p_person_record_id uuid, p_site_id uuid, p_zone_id uuid, p_location_id uuid, p_incident_id uuid, p_identity_basis text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."link_observation_entities"(p_observation_id uuid, p_organization_id uuid, p_canonical_vehicle_id uuid, p_person_record_id uuid, p_site_id uuid, p_zone_id uuid, p_location_id uuid, p_incident_id uuid, p_identity_basis text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."link_observation_entities"(p_observation_id uuid, p_organization_id uuid, p_canonical_vehicle_id uuid, p_person_record_id uuid, p_site_id uuid, p_zone_id uuid, p_location_id uuid, p_incident_id uuid, p_identity_basis text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."list_dispatch_target_officers"(p_service_agreement_id uuid)
 RETURNS TABLE(id uuid, organization_id uuid, display_name text, email text, role text)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT u.id, u.organization_id, u.display_name, u.email, u.role
  FROM public.user_profiles u
  JOIN public.service_agreements sa
    ON sa.id = p_service_agreement_id
  JOIN public.organizations officer_org
    ON officer_org.id = u.organization_id
  WHERE u.deactivated_at IS NULL
    AND u.role IN ('officer', 'admin_officer')
    AND (sa.ends_on IS NULL OR sa.ends_on >= current_date)
    AND (
      officer_org.id = sa.provider_organization_id
      OR sa.provider_organization_id = ANY(public.get_descendant_organizations(officer_org.id))
    )
    AND public.org_access_allowed(sa.provider_organization_id)
  ORDER BY coalesce(u.display_name, u.email), u.email;
$function$;
REVOKE ALL ON FUNCTION "public"."list_dispatch_target_officers"(p_service_agreement_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."list_dispatch_target_officers"(p_service_agreement_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."list_dispatch_target_officers"(p_service_agreement_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."list_dispatch_target_officers"(p_service_agreement_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."list_nzta_access_reviews"(p_organization_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF auth.uid() IS NULL OR p_organization_id IS NULL OR NOT public.is_admin_for_org(p_organization_id) THEN
    RAISE EXCEPTION 'Organisation administrator required' USING ERRCODE = '42501';
  END IF;
  RETURN coalesce((
    SELECT jsonb_agg(jsonb_build_object(
      'review_id', review.id, 'period_start', review.period_start, 'period_end', review.period_end,
      'reviewed_at', review.reviewed_at, 'reviewed_by_name', reviewer.display_name,
      'holder_count', jsonb_array_length(review.holders), 'findings', review.findings, 'actions', review.actions
    ) ORDER BY review.period_end DESC, review.reviewed_at DESC)
    FROM public.nzta_access_reviews review
    LEFT JOIN public.user_profiles reviewer ON reviewer.id = review.reviewed_by
    WHERE review.organization_id = p_organization_id
  ), '[]'::jsonb);
END;
$function$;
REVOKE ALL ON FUNCTION "public"."list_nzta_access_reviews"(p_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."list_nzta_access_reviews"(p_organization_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."list_nzta_access_reviews"(p_organization_id uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."list_nzta_follow_up_notices"(p_subject_type text, p_subject_id uuid, p_organization_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(notice_id uuid, organization_id uuid, notice_number text, notice_type text, issued_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT notice.id, notice.organization_id, notice.notice_number, notice.notice_type, notice.issued_at
  FROM public.notices notice
  WHERE auth.uid() IS NOT NULL
    AND p_subject_type IN ('person', 'vehicle') AND p_subject_id IS NOT NULL
    AND notice.status = 'issued' AND notice.notice_type IN ('trespass', 'warning')
    AND (p_organization_id IS NULL OR notice.organization_id = p_organization_id)
    AND public.can_access_vehicle_owner_identity(notice.organization_id)
    AND public.nzta_notice_matches_subject(notice.id, p_subject_type, p_subject_id)
  ORDER BY notice.issued_at DESC NULLS LAST
  LIMIT 50;
$function$;
REVOKE ALL ON FUNCTION "public"."list_nzta_follow_up_notices"(p_subject_type text, p_subject_id uuid, p_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."list_nzta_follow_up_notices"(p_subject_type text, p_subject_id uuid, p_organization_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."list_nzta_follow_up_notices"(p_subject_type text, p_subject_id uuid, p_organization_id uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."list_nzta_register_access_log"(p_organization_id uuid, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 500)
 RETURNS TABLE(log_id uuid, revealed_at timestamp with time zone, expires_at timestamp with time zone, actor_name text, subject_type text, subject_label text, purpose text, explanation text, notice_number text, lookup_id uuid, training_current boolean, confidentiality_current boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF auth.uid() IS NULL OR p_organization_id IS NULL OR NOT public.is_admin_for_org(p_organization_id) THEN
    RAISE EXCEPTION 'Organisation administrator required' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
  SELECT log.id, log.revealed_at, log.expires_at, actor.display_name, log.subject_type,
    CASE WHEN log.subject_type = 'vehicle' THEN vehicle.plate_number ELSE person.display_name END,
    log.purpose, log.explanation, notice.notice_number, log.lookup_id, log.training_current, log.confidentiality_current
  FROM public.nzta_register_access_log log
  LEFT JOIN public.user_profiles actor ON actor.id = log.actor_user_id
  LEFT JOIN public.canonical_vehicles vehicle ON log.subject_type = 'vehicle' AND vehicle.id = log.subject_id
  LEFT JOIN public.canonical_people person ON log.subject_type = 'person' AND person.id = log.subject_id
  LEFT JOIN public.notices notice ON notice.id = log.notice_id
  WHERE log.organization_id = p_organization_id
    AND (p_from IS NULL OR log.revealed_at >= p_from) AND (p_to IS NULL OR log.revealed_at < p_to)
  ORDER BY log.revealed_at DESC
  LIMIT least(greatest(coalesce(p_limit, 500), 1), 5000);
END;
$function$;
REVOKE ALL ON FUNCTION "public"."list_nzta_register_access_log"(p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."list_nzta_register_access_log"(p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."list_nzta_register_access_log"(p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."list_nzta_register_lookups"(p_organization_id uuid, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 500)
 RETURNS TABLE(entry_kind text, entry_id uuid, looked_up_at timestamp with time zone, plate_number text, vin text, motochek_user text, purpose text, explanation text, outcome text, outcome_notes text, place_name text, observation_id uuid, notice_number text, vehicle_identity_check_id uuid, recorded_by_name text, recorded_at timestamp with time zone, can_edit boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_admin boolean;
  v_limit integer := least(greatest(coalesce(p_limit, 500), 1), 5000);
BEGIN
  IF v_actor IS NULL OR p_organization_id IS NULL
     OR NOT public.can_access_vehicle_owner_identity(p_organization_id) THEN
    RAISE EXCEPTION 'NZTA register authorisation required' USING ERRCODE = '42501';
  END IF;
  v_admin := public.is_admin_for_org(p_organization_id);
  RETURN QUERY
  SELECT * FROM (
    SELECT 'lookup'::text, l.id, l.looked_up_at, l.plate_number, l.vin, l.motochek_user, l.purpose, l.explanation,
      l.outcome, l.outcome_notes, place.name, l.observation_id, notice.notice_number, l.vehicle_identity_check_id,
      author.display_name, l.created_at, (v_admin OR l.created_by = v_actor)
    FROM public.nzta_register_lookups l
    LEFT JOIN public.locations place ON place.id = l.location_id
    LEFT JOIN public.notices notice ON notice.id = l.notice_id
    LEFT JOIN public.user_profiles author ON author.id = l.created_by
    WHERE l.organization_id = p_organization_id AND (v_admin OR l.created_by = v_actor)
      AND (p_from IS NULL OR l.looked_up_at >= p_from) AND (p_to IS NULL OR l.looked_up_at < p_to)
    UNION ALL
    -- Checks recorded before the register existed. Their purpose was never
    -- captured, so it is reported as missing rather than inferred.
    SELECT 'historical_check'::text, c.id, c.checked_at, v.plate_number, v.vin, NULL::text, NULL::text, NULL::text,
      NULL::text, NULL::text, NULL::text, NULL::uuid, NULL::text, c.id, reviewer.display_name, c.created_at, false
    FROM public.vehicle_identity_checks c
    LEFT JOIN public.canonical_vehicles v ON v.id = c.canonical_vehicle_id
    LEFT JOIN public.user_profiles reviewer ON reviewer.id = c.reviewed_by
    WHERE v_admin AND c.organization_id = p_organization_id
      AND NOT EXISTS (SELECT 1 FROM public.nzta_register_lookups l WHERE l.vehicle_identity_check_id = c.id)
      AND (p_from IS NULL OR c.checked_at >= p_from) AND (p_to IS NULL OR c.checked_at < p_to)
  ) entries
  ORDER BY 3 DESC
  LIMIT v_limit;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."list_nzta_register_lookups"(p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."list_nzta_register_lookups"(p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."list_nzta_register_lookups"(p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."list_person_subject_history_for_agreement"(p_canonical_person_id uuid, p_service_agreement_id uuid, p_limit integer DEFAULT 200)
 RETURNS TABLE(source text, record_id uuid, organization_id uuid, observed_at timestamp with time zone, place_id uuid, plate text, note text, evidence_item_id uuid)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_scope_orgs uuid[];
BEGIN
  v_scope_orgs := private.subject_scope_organizations(p_service_agreement_id);
  IF NOT EXISTS (SELECT 1 FROM public.canonical_people cp WHERE cp.id=p_canonical_person_id AND cp.review_state='verified' AND cp.status='active') THEN RAISE EXCEPTION 'Verified canonical person is not available'; END IF;
  RETURN QUERY
  WITH places AS MATERIALIZED (SELECT l.zone_id,l.site_id FROM public.service_agreement_locations l WHERE l.service_agreement_id=p_service_agreement_id AND l.status='active')
  SELECT * FROM (
    SELECT 'patrol'::text,o.id,o.organization_id,o.observed_at,coalesce(o.zone_id,o.site_id),o.plate_number,o.officer_notes,
      (SELECT e.id FROM public.evidence_items e WHERE e.organization_id=o.organization_id AND e.metadata->>'observation_id'=o.id::text ORDER BY e.captured_at DESC LIMIT 1)
    FROM public.observations o
    JOIN public.person_records pr ON pr.id=o.person_record_id AND pr.organization_id=o.organization_id AND pr.review_state='verified'
    LEFT JOIN public.canonical_person_links cpl ON cpl.source_table='person_records' AND cpl.source_id=o.person_record_id AND cpl.organization_id=o.organization_id
    WHERE o.organization_id=ANY(v_scope_orgs) AND coalesce(o.canonical_person_id,cpl.canonical_person_id)=p_canonical_person_id AND o.observed_at<=now()
      AND (p_service_agreement_id IS NULL OR EXISTS (SELECT 1 FROM places p WHERE (p.zone_id IS NOT NULL AND p.zone_id=o.zone_id) OR (p.site_id IS NOT NULL AND p.site_id=o.site_id)))
    UNION ALL
    SELECT 'cctv'::text,c.id,c.organization_id,c.observed_at,coalesce(c.zone_id,c.site_id),c.candidate_plate,
      nullif(concat_ws(' · ',c.candidate_label,c.attributes->>'description'),''),c.evidence_item_id
    FROM public.cctv_entity_observations c
    JOIN public.person_records pr ON pr.id=c.person_record_id AND pr.organization_id=c.organization_id AND pr.review_state='verified'
    LEFT JOIN public.canonical_person_links cpl ON cpl.source_table='person_records' AND cpl.source_id=c.person_record_id AND cpl.organization_id=c.organization_id
    WHERE c.organization_id=ANY(v_scope_orgs) AND c.entity_kind='person' AND c.review_state='accepted'
      AND coalesce(c.canonical_person_id,cpl.canonical_person_id)=p_canonical_person_id AND c.observed_at<=now()
      AND (p_service_agreement_id IS NULL OR EXISTS (SELECT 1 FROM places p WHERE (p.zone_id IS NOT NULL AND p.zone_id=c.zone_id) OR (p.site_id IS NOT NULL AND p.site_id=c.site_id)))
  ) h ORDER BY observed_at DESC LIMIT least(greatest(coalesce(p_limit,200),1),500);
END;
$function$;
REVOKE ALL ON FUNCTION "public"."list_person_subject_history_for_agreement"(p_canonical_person_id uuid, p_service_agreement_id uuid, p_limit integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."list_person_subject_history_for_agreement"(p_canonical_person_id uuid, p_service_agreement_id uuid, p_limit integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."list_person_subject_history_for_agreement"(p_canonical_person_id uuid, p_service_agreement_id uuid, p_limit integer) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."list_person_subject_history_for_agreement"(p_canonical_person_id uuid, p_service_agreement_id uuid, p_limit integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."list_record_updates"(p_record_kind text, p_record_id uuid)
 RETURNS TABLE(id uuid, entry_kind text, body text, created_at timestamp with time zone, created_by_name text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT r.id, r.entry_kind, r.body, r.created_at, u.display_name
  FROM public.record_updates r
  LEFT JOIN public.user_profiles u ON u.id = r.created_by
  WHERE public.record_update_target_org(p_record_kind, p_record_id) IS NOT NULL
    AND r.record_kind = p_record_kind AND r.record_id = p_record_id
  ORDER BY r.created_at DESC
  LIMIT 200;
$function$;
REVOKE ALL ON FUNCTION "public"."list_record_updates"(p_record_kind text, p_record_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."list_record_updates"(p_record_kind text, p_record_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."list_record_updates"(p_record_kind text, p_record_id uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."list_repeat_person_subjects_for_agreement"(p_service_agreement_id uuid, p_min_sightings integer DEFAULT 2, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0)
 RETURNS TABLE(canonical_person_id uuid, display_name text, sightings bigint, places bigint, patrol_sightings bigint, cctv_sightings bigint, first_seen timestamp with time zone, last_seen timestamp with time zone, total_count bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_scope_orgs uuid[];
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  v_scope_orgs := private.subject_scope_organizations(p_service_agreement_id);
  RETURN QUERY
  WITH places AS MATERIALIZED (
    SELECT l.zone_id,l.site_id FROM public.service_agreement_locations l WHERE l.service_agreement_id=p_service_agreement_id AND l.status='active'
  ), seen AS (
    SELECT coalesce(o.canonical_person_id,cpl.canonical_person_id) person_id, coalesce(o.zone_id,o.site_id) place, o.observed_at at, 'patrol'::text src
    FROM public.observations o
    JOIN public.person_records pr ON pr.id=o.person_record_id AND pr.organization_id=o.organization_id AND pr.review_state='verified'
    LEFT JOIN public.canonical_person_links cpl ON cpl.source_table='person_records' AND cpl.source_id=o.person_record_id AND cpl.organization_id=o.organization_id
    JOIN public.canonical_people cp ON cp.id=coalesce(o.canonical_person_id,cpl.canonical_person_id) AND cp.review_state='verified' AND cp.status='active'
    WHERE o.organization_id=ANY(v_scope_orgs) AND o.person_record_id IS NOT NULL AND o.observed_at<=now()
      AND (p_from IS NULL OR o.observed_at>=p_from) AND (p_to IS NULL OR o.observed_at<p_to)
      AND (p_service_agreement_id IS NULL OR EXISTS (SELECT 1 FROM places p WHERE (p.zone_id IS NOT NULL AND p.zone_id=o.zone_id) OR (p.site_id IS NOT NULL AND p.site_id=o.site_id)))
    UNION ALL
    SELECT coalesce(c.canonical_person_id,cpl.canonical_person_id), coalesce(c.zone_id,c.site_id), c.observed_at, 'cctv'::text
    FROM public.cctv_entity_observations c
    JOIN public.person_records pr ON pr.id=c.person_record_id AND pr.organization_id=c.organization_id AND pr.review_state='verified'
    LEFT JOIN public.canonical_person_links cpl ON cpl.source_table='person_records' AND cpl.source_id=c.person_record_id AND cpl.organization_id=c.organization_id
    JOIN public.canonical_people cp ON cp.id=coalesce(c.canonical_person_id,cpl.canonical_person_id) AND cp.review_state='verified' AND cp.status='active'
    WHERE c.organization_id=ANY(v_scope_orgs) AND c.entity_kind='person' AND c.review_state='accepted'
      AND c.person_record_id IS NOT NULL AND c.observed_at<=now()
      AND (p_from IS NULL OR c.observed_at>=p_from) AND (p_to IS NULL OR c.observed_at<p_to)
      AND (p_service_agreement_id IS NULL OR EXISTS (SELECT 1 FROM places p WHERE (p.zone_id IS NOT NULL AND p.zone_id=c.zone_id) OR (p.site_id IS NOT NULL AND p.site_id=c.site_id)))
  ), grouped AS (
    SELECT s.person_id, count(*) n, count(DISTINCT s.place) place_count,
      count(*) FILTER (WHERE s.src='patrol') patrol_count, count(*) FILTER (WHERE s.src='cctv') cctv_count,
      min(s.at) first_at, max(s.at) last_at
    FROM seen s GROUP BY s.person_id HAVING count(*)>=greatest(coalesce(p_min_sightings,2),1)
  )
  SELECT g.person_id, cp.display_name, g.n, g.place_count, g.patrol_count, g.cctv_count, g.first_at, g.last_at, count(*) OVER ()
  FROM grouped g JOIN public.canonical_person_public cp ON cp.id=g.person_id AND cp.review_state='verified' AND cp.status='active'
  ORDER BY g.n DESC,g.last_at DESC LIMIT least(greatest(coalesce(p_limit,100),1),500) OFFSET greatest(coalesce(p_offset,0),0);
END;
$function$;
REVOKE ALL ON FUNCTION "public"."list_repeat_person_subjects_for_agreement"(p_service_agreement_id uuid, p_min_sightings integer, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer, p_offset integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."list_repeat_person_subjects_for_agreement"(p_service_agreement_id uuid, p_min_sightings integer, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer, p_offset integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."list_repeat_person_subjects_for_agreement"(p_service_agreement_id uuid, p_min_sightings integer, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer, p_offset integer) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."list_repeat_person_subjects_for_agreement"(p_service_agreement_id uuid, p_min_sightings integer, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer, p_offset integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."list_repeat_vehicle_subjects_for_agreement"(p_service_agreement_id uuid, p_min_sightings integer DEFAULT 2, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0)
 RETURNS TABLE(plate text, sightings bigint, places bigint, officers bigint, patrol_sightings bigint, cctv_sightings bigint, first_seen timestamp with time zone, last_seen timestamp with time zone, owner_identified boolean, total_count bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_scope_orgs uuid[];
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  v_scope_orgs := private.subject_scope_organizations(p_service_agreement_id);

  RETURN QUERY
  WITH places AS MATERIALIZED (
    SELECT l.zone_id, l.site_id FROM public.service_agreement_locations l
    WHERE l.service_agreement_id = p_service_agreement_id AND l.status = 'active'
  ),
  seen AS (
    SELECT upper(regexp_replace(o.plate_number, '[^A-Za-z0-9]', '', 'g')) pl,
      o.canonical_vehicle_id cv, o.observed_at at,
      coalesce(o.zone_id, o.site_id) place, o.officer_id officer, 'patrol'::text src
    FROM public.observations o
    WHERE o.organization_id = ANY(v_scope_orgs)
      AND o.observed_at <= now() AND (p_from IS NULL OR o.observed_at >= p_from) AND (p_to IS NULL OR o.observed_at < p_to)
      AND (p_service_agreement_id IS NULL OR EXISTS (SELECT 1 FROM places p WHERE (p.zone_id IS NOT NULL AND p.zone_id = o.zone_id) OR (p.site_id IS NOT NULL AND p.site_id = o.site_id)))
    UNION ALL
    SELECT upper(regexp_replace(c.candidate_plate, '[^A-Za-z0-9]', '', 'g')), c.canonical_vehicle_id,
      c.observed_at, coalesce(c.zone_id, c.site_id), NULL::uuid, 'cctv'::text
    FROM public.cctv_entity_observations c
    WHERE c.organization_id = ANY(v_scope_orgs)
      AND c.entity_kind = 'vehicle' AND c.review_state = 'accepted' AND c.candidate_plate IS NOT NULL
      AND c.observed_at <= now() AND (p_from IS NULL OR c.observed_at >= p_from) AND (p_to IS NULL OR c.observed_at < p_to)
      AND (p_service_agreement_id IS NULL OR EXISTS (SELECT 1 FROM places p WHERE (p.zone_id IS NOT NULL AND p.zone_id = c.zone_id) OR (p.site_id IS NOT NULL AND p.site_id = c.site_id)))
  ),
  grouped AS (
    SELECT s.pl, count(*) n, count(DISTINCT s.place) place_count, count(DISTINCT s.officer) officer_count,
      count(*) FILTER (WHERE s.src = 'patrol') patrol_count, count(*) FILTER (WHERE s.src = 'cctv') cctv_count,
      min(s.at) first_at, max(s.at) last_at,
      coalesce(bool_or((EXISTS (SELECT 1 FROM public.canonical_vehicles v WHERE v.id = s.cv AND v.registered_owner_name IS NOT NULL) OR EXISTS (SELECT 1 FROM public.entity_links el WHERE el.to_type = 'vehicle' AND el.to_id = s.cv AND el.from_type = 'person' AND el.active AND el.relationship IN ('owner', 'registered_owner') AND el.organization_id = ANY(v_scope_orgs)))), false) owner_flag
    FROM seen s WHERE s.pl <> '' GROUP BY s.pl
    HAVING count(*) >= greatest(coalesce(p_min_sightings, 2), 1)
  )
  SELECT g.pl, g.n, g.place_count, g.officer_count, g.patrol_count, g.cctv_count,
    g.first_at, g.last_at, g.owner_flag, count(*) OVER ()
  FROM grouped g ORDER BY g.n DESC, g.last_at DESC
  LIMIT least(greatest(coalesce(p_limit, 100), 1), 500) OFFSET greatest(coalesce(p_offset, 0), 0);
END;
$function$;
COMMENT ON FUNCTION "public"."list_repeat_vehicle_subjects_for_agreement"(p_service_agreement_id uuid, p_min_sightings integer, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer, p_offset integer) IS 'Selected agreement, or all authorised R&M observations when agreement is NULL: repeat vehicle summary, restricted to R&M administrators. No person names are returned.';
REVOKE ALL ON FUNCTION "public"."list_repeat_vehicle_subjects_for_agreement"(p_service_agreement_id uuid, p_min_sightings integer, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer, p_offset integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."list_repeat_vehicle_subjects_for_agreement"(p_service_agreement_id uuid, p_min_sightings integer, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer, p_offset integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."list_repeat_vehicle_subjects_for_agreement"(p_service_agreement_id uuid, p_min_sightings integer, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer, p_offset integer) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."list_repeat_vehicle_subjects_for_agreement"(p_service_agreement_id uuid, p_min_sightings integer, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer, p_offset integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."list_report_incident_triage"(p_pack_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_pack record;
begin
  if auth.uid() is null then
    raise exception 'Authenticated provider administrator required';
  end if;
  select pack.id, pack.organization_id, pack.service_agreement_id, pack.period_start, pack.period_end
  into v_pack
  from public.monthly_report_packs pack
  where pack.id = p_pack_id;
  if v_pack.id is null then
    raise exception 'Report pack not found';
  end if;
  if not public.is_report_provider_custodian_for_org(v_pack.organization_id) then
    raise exception 'Provider administrator access required';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'line_key', t.line_key,
      'bob_flagged', t.bob_flagged,
      'bob_incident_type', t.bob_incident_type,
      'bob_reason', t.bob_reason,
      'bob_confidence', t.bob_confidence,
      'bob_assessed_at', t.bob_assessed_at,
      'decision', t.decision,
      'incident_type', t.incident_type,
      'decision_note', t.decision_note,
      'decided_at', t.decided_at,
      'in_sent_report', exists (
        select 1
        from public.monthly_report_packs sent
        where sent.service_agreement_id = t.service_agreement_id
          and sent.status = 'sent'
          and t.line_date between sent.period_start and sent.period_end
      )
    ) order by t.line_date, t.line_key)
    from public.report_incident_triage t
    where t.service_agreement_id = v_pack.service_agreement_id
      and t.line_date between v_pack.period_start and v_pack.period_end
  ), '[]'::jsonb);
end;
$function$;
COMMENT ON FUNCTION "public"."list_report_incident_triage"(p_pack_id uuid) IS 'Returns Bob''s potential-incident flags and reviewer decisions for the activity lines inside one report pack''s period, with in_sent_report when a sent pack already covers the entry. Report provider custodians only.';
REVOKE ALL ON FUNCTION "public"."list_report_incident_triage"(p_pack_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."list_report_incident_triage"(p_pack_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."list_report_incident_triage"(p_pack_id uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."list_unlinked_plate_mentions_for_agreement"(p_service_agreement_id uuid, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0)
 RETURNS TABLE(plate text, mentions bigint, first_seen timestamp with time zone, last_seen timestamp with time zone, total_count bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_scope_orgs uuid[];
BEGIN
  v_scope_orgs := private.subject_scope_organizations(p_service_agreement_id);
  RETURN QUERY
  WITH places AS MATERIALIZED (
    SELECT l.zone_id, l.site_id FROM public.service_agreement_locations l WHERE l.service_agreement_id = p_service_agreement_id AND l.status = 'active'
  ), mentions AS (
    SELECT upper(regexp_replace(m.plate[1], '[^A-Za-z0-9]', '', 'g')) plate, e.id, e.occurred_at
    FROM public.location_events e
    CROSS JOIN LATERAL regexp_matches(coalesce(e.payload->>'comments',''), '\m([A-Z]{3}[0-9]{3})\M', 'gi') AS m(plate)
    WHERE e.organization_id = ANY(v_scope_orgs) AND e.occurred_at <= now() AND (p_from IS NULL OR e.occurred_at >= p_from) AND (p_to IS NULL OR e.occurred_at < p_to)
      AND (p_service_agreement_id IS NULL OR EXISTS (SELECT 1 FROM places p WHERE (p.zone_id IS NOT NULL AND p.zone_id = e.zone_id) OR (p.site_id IS NOT NULL AND p.site_id = e.client_site_id)))
      AND NOT EXISTS (SELECT 1 FROM public.observations o WHERE upper(regexp_replace(o.plate_number,'[^A-Za-z0-9]','','g')) = upper(regexp_replace(m.plate[1],'[^A-Za-z0-9]','','g')) AND (o.zone_id=e.zone_id OR o.site_id=e.client_site_id))
      AND NOT EXISTS (SELECT 1 FROM public.cctv_entity_observations c WHERE c.review_state='accepted' AND upper(regexp_replace(coalesce(c.candidate_plate,''),'[^A-Za-z0-9]','','g')) = upper(regexp_replace(m.plate[1],'[^A-Za-z0-9]','','g')) AND (c.zone_id=e.zone_id OR c.site_id=e.client_site_id))
  ), grouped AS (
    SELECT m.plate, count(*) n, min(m.occurred_at) first_at, max(m.occurred_at) last_at FROM mentions m GROUP BY m.plate
  )
  SELECT g.plate, g.n, g.first_at, g.last_at, count(*) over () FROM grouped g ORDER BY g.n DESC, g.last_at DESC
  LIMIT least(greatest(coalesce(p_limit,100),1),500) OFFSET greatest(coalesce(p_offset,0),0);
END;
$function$;
REVOKE ALL ON FUNCTION "public"."list_unlinked_plate_mentions_for_agreement"(p_service_agreement_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer, p_offset integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."list_unlinked_plate_mentions_for_agreement"(p_service_agreement_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer, p_offset integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."list_unlinked_plate_mentions_for_agreement"(p_service_agreement_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer, p_offset integer) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."list_unlinked_plate_mentions_for_agreement"(p_service_agreement_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer, p_offset integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."list_vehicle_subject_history_for_agreement"(p_plate text, p_service_agreement_id uuid, p_limit integer DEFAULT 200)
 RETURNS TABLE(source text, record_id uuid, organization_id uuid, observed_at timestamp with time zone, place_id uuid, officer_id uuid, note text, canonical_vehicle_id uuid, evidence_item_id uuid, compliance_status text, compliance_reason text, photo_url text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_scope_orgs uuid[];
  v_plate text := upper(regexp_replace(coalesce(p_plate, ''), '[^A-Za-z0-9]', '', 'g'));
BEGIN
  v_scope_orgs := private.subject_scope_organizations(p_service_agreement_id);
  IF v_plate = '' THEN RETURN; END IF;
  RETURN QUERY
  WITH places AS MATERIALIZED (
    SELECT l.zone_id, l.site_id FROM public.service_agreement_locations l
    WHERE l.service_agreement_id = p_service_agreement_id AND l.status = 'active'
  )
  SELECT * FROM (
    SELECT 'patrol'::text, o.id, o.organization_id, o.observed_at, coalesce(o.zone_id, o.site_id), o.officer_id,
      o.officer_notes, o.canonical_vehicle_id,
      (SELECT e.id FROM public.evidence_items e WHERE e.organization_id = o.organization_id AND e.metadata->>'observation_id' = o.id::text ORDER BY e.captured_at DESC LIMIT 1),
      CASE WHEN o.is_compliant IS NULL THEN NULL WHEN o.is_compliant THEN 'compliant' ELSE 'non_compliant' END,
      o.compliance_reason, o.photo_url
    FROM public.observations o
    WHERE o.organization_id = ANY(v_scope_orgs)
      AND upper(regexp_replace(o.plate_number, '[^A-Za-z0-9]', '', 'g')) = v_plate AND o.observed_at <= now()
      AND (p_service_agreement_id IS NULL OR EXISTS (SELECT 1 FROM places p WHERE (p.zone_id IS NOT NULL AND p.zone_id = o.zone_id) OR (p.site_id IS NOT NULL AND p.site_id = o.site_id)))
    UNION ALL
    SELECT 'cctv'::text, c.id, c.organization_id, c.observed_at, coalesce(c.zone_id, c.site_id), NULL::uuid,
      nullif(concat_ws(' · ', c.candidate_label, c.attributes->>'description'), ''), c.canonical_vehicle_id, c.evidence_item_id,
      NULL::text, NULL::text, NULL::text
    FROM public.cctv_entity_observations c
    WHERE c.organization_id = ANY(v_scope_orgs) AND c.entity_kind = 'vehicle' AND c.review_state = 'accepted' AND c.observed_at <= now()
      AND upper(regexp_replace(coalesce(c.candidate_plate, ''), '[^A-Za-z0-9]', '', 'g')) = v_plate
      AND (p_service_agreement_id IS NULL OR EXISTS (SELECT 1 FROM places p WHERE (p.zone_id IS NOT NULL AND p.zone_id = c.zone_id) OR (p.site_id IS NOT NULL AND p.site_id = c.site_id)))
    UNION ALL
    SELECT 'patrol_comment'::text, e.id, e.organization_id, e.occurred_at, coalesce(e.zone_id, e.client_site_id), NULL::uuid,
      e.payload->>'comments', NULL::uuid, NULL::uuid, NULL::text, e.payload->>'issue', NULL::text
    FROM public.location_events e
    WHERE e.organization_id = ANY(v_scope_orgs) AND e.occurred_at <= now() AND e.payload->>'comments' ILIKE '%' || v_plate || '%'
      AND (p_service_agreement_id IS NULL OR EXISTS (SELECT 1 FROM places p WHERE (p.zone_id IS NOT NULL AND p.zone_id = e.zone_id) OR (p.site_id IS NOT NULL AND p.site_id = e.client_site_id)))
      AND NOT EXISTS (SELECT 1 FROM public.observations o WHERE o.external_refs->>'external_ref' = e.external_ref AND o.organization_id = e.organization_id)
  ) history
  ORDER BY observed_at DESC
  LIMIT least(greatest(coalesce(p_limit, 200), 1), 500);
END;
$function$;
COMMENT ON FUNCTION "public"."list_vehicle_subject_history_for_agreement"(p_plate text, p_service_agreement_id uuid, p_limit integer) IS 'Selected agreement, or all authorised R&M observations when agreement is NULL: patrol, accepted CCTV and unlinked patrol-comment history, restricted to R&M administrators.';
REVOKE ALL ON FUNCTION "public"."list_vehicle_subject_history_for_agreement"(p_plate text, p_service_agreement_id uuid, p_limit integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."list_vehicle_subject_history_for_agreement"(p_plate text, p_service_agreement_id uuid, p_limit integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."list_vehicle_subject_history_for_agreement"(p_plate text, p_service_agreement_id uuid, p_limit integer) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."list_vehicle_subject_history_for_agreement"(p_plate text, p_service_agreement_id uuid, p_limit integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."list_vehicle_subject_identifications"(p_plate text, p_service_agreement_id uuid)
 RETURNS TABLE(canonical_person_id uuid, person_record_id uuid, display_name text, identification_basis text, linked_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_scope_orgs uuid[]; v_plate text:=upper(regexp_replace(coalesce(p_plate,''),'[^A-Za-z0-9]','','g'));
BEGIN
  v_scope_orgs := private.subject_scope_organizations(p_service_agreement_id);
  RETURN QUERY
  SELECT DISTINCT ON (cp.id) cp.id, o.person_record_id, cp.display_name,
    coalesce(a.metadata->>'identity_basis', 'Basis not recorded'), coalesce(a.created_at, o.observed_at)
  FROM public.observations o JOIN public.person_records pr ON pr.id=o.person_record_id AND pr.organization_id=o.organization_id AND pr.review_state='verified'
  JOIN public.canonical_person_links cpl ON cpl.source_table='person_records' AND cpl.source_id=pr.id AND cpl.organization_id=pr.organization_id
  JOIN public.canonical_people cp ON cp.id=coalesce(o.canonical_person_id,cpl.canonical_person_id) AND cp.review_state='verified' AND cp.status='active'
  LEFT JOIN LATERAL (
    SELECT al.metadata, al.created_at FROM public.audit_log al
    WHERE al.target_table='observations' AND al.target_id=o.id AND al.action='observation_identity_linked'
      AND al.metadata->>'person_record_id'=o.person_record_id::text
    ORDER BY al.created_at DESC LIMIT 1
  ) a ON true
  WHERE o.organization_id = ANY(v_scope_orgs)
    AND upper(regexp_replace(o.plate_number,'[^A-Za-z0-9]','','g'))=v_plate AND o.person_record_id IS NOT NULL AND o.observed_at<=now()
    AND (p_service_agreement_id IS NULL OR EXISTS (SELECT 1 FROM public.service_agreement_locations l
      WHERE l.service_agreement_id=p_service_agreement_id AND l.status='active'
        AND ((l.zone_id IS NOT NULL AND l.zone_id=o.zone_id) OR (l.site_id IS NOT NULL AND l.site_id=o.site_id))))
  ORDER BY cp.id, coalesce(a.created_at, o.observed_at) DESC;
END;
$function$;
COMMENT ON FUNCTION "public"."list_vehicle_subject_identifications"(p_plate text, p_service_agreement_id uuid) IS 'Returns person identity details only to R&M administrators for the selected agreement, or all authorised R&M observations when agreement is NULL.';
REVOKE ALL ON FUNCTION "public"."list_vehicle_subject_identifications"(p_plate text, p_service_agreement_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."list_vehicle_subject_identifications"(p_plate text, p_service_agreement_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."list_vehicle_subject_identifications"(p_plate text, p_service_agreement_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."list_vehicle_subject_identifications"(p_plate text, p_service_agreement_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."list_verified_person_projections_for_organization"(p_organization_id uuid)
 RETURNS TABLE(id uuid, canonical_person_id uuid, display_name text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_rnm_orgs uuid[] := ARRAY['e96d71c9-28a6-4d4a-b0f3-1c4ecdaa9c13'::uuid] || public.get_descendant_organizations('e96d71c9-28a6-4d4a-b0f3-1c4ecdaa9c13'::uuid);
BEGIN
  IF auth.uid() IS NULL OR NOT private.rnm_admin_for_organization(p_organization_id) OR NOT (p_organization_id = ANY(v_rnm_orgs)) THEN
    RAISE EXCEPTION 'R&M administrator access to this organization is required';
  END IF;
  RETURN QUERY
  SELECT pr.id, cp.id, cp.display_name
  FROM public.person_records pr
  JOIN public.canonical_person_links cpl ON cpl.source_table='person_records' AND cpl.source_id=pr.id AND cpl.organization_id=pr.organization_id
  JOIN public.canonical_people cp ON cp.id=cpl.canonical_person_id AND cp.review_state='verified' AND cp.status='active'
  WHERE pr.organization_id=p_organization_id AND pr.review_state='verified'
  ORDER BY cp.display_name NULLS LAST, pr.id;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."list_verified_person_projections_for_organization"(p_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."list_verified_person_projections_for_organization"(p_organization_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."list_verified_person_projections_for_organization"(p_organization_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."list_verified_person_projections_for_organization"(p_organization_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."list_website_posts"()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
DECLARE v_provider uuid := public.website_post_admin_organization();
BEGIN
  IF v_provider IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'website_posts_access_denied';
  END IF;
  RETURN coalesce((
    SELECT jsonb_agg(to_jsonb(p) - 'last_request_payload' - 'last_request_id' ORDER BY p.updated_at DESC, p.id)
    FROM (
      SELECT * FROM public.website_posts WHERE provider_organization_id = v_provider
      ORDER BY updated_at DESC, id LIMIT 100
    ) p
  ), '[]'::jsonb);
END
$function$;
REVOKE ALL ON FUNCTION "public"."list_website_posts"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."list_website_posts"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."list_website_posts"() TO "authenticated";

