CREATE OR REPLACE FUNCTION "public"."lock_cctv_evidence"(p_evidence_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_evidence public.evidence_items%rowtype;
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF v_reason IS NULL OR char_length(v_reason) < 5 THEN RAISE EXCEPTION 'An evidence lock needs a stated reason (at least 5 characters)'; END IF;

  SELECT * INTO v_evidence FROM public.evidence_items WHERE id = p_evidence_id FOR UPDATE;
  IF v_evidence.id IS NULL THEN RAISE EXCEPTION 'Recording not found'; END IF;
  IF NOT public.is_admin_for_org(v_evidence.organization_id) THEN RAISE EXCEPTION 'Only an administrator of the custodian organisation can lock evidence'; END IF;
  IF v_evidence.locked_at IS NOT NULL THEN
    RETURN jsonb_build_object('evidence_item_id', v_evidence.id, 'locked_at', v_evidence.locked_at, 'already_locked', true);
  END IF;
  IF nullif(trim(coalesce(v_evidence.sha256_hash, '')), '') IS NULL THEN
    RAISE EXCEPTION 'This recording has no integrity hash yet; wait for analysis to record it before locking';
  END IF;

  UPDATE public.evidence_items
     SET is_court_ready = true,
         locked_at = clock_timestamp(),
         retention_hold = true,
         retention_reason = 'evidence_lock: ' || v_reason,
         metadata = metadata || jsonb_build_object('evidence_lock', jsonb_build_object('locked_by', v_actor, 'reason', v_reason, 'locked_at', clock_timestamp()))
   WHERE id = v_evidence.id
   RETURNING * INTO v_evidence;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_evidence.organization_id, v_actor, 'cctv_evidence_locked', 'evidence_items', v_evidence.id,
          jsonb_build_object('reason', v_reason, 'sha256_hash', v_evidence.sha256_hash, 'locked_at', v_evidence.locked_at, 'cctv_import_id', v_evidence.cctv_import_id));

  RETURN jsonb_build_object('evidence_item_id', v_evidence.id, 'locked_at', v_evidence.locked_at, 'already_locked', false);
END $function$;
COMMENT ON FUNCTION "public"."lock_cctv_evidence"(p_evidence_id uuid, p_reason text) IS 'Admin-only evidence lock for a CCTV recording: sets is_court_ready, locked_at and retention_hold so retention cannot purge it. Refused without a recorded sha256_hash. Audited; not reversible from the browser.';
REVOKE ALL ON FUNCTION "public"."lock_cctv_evidence"(p_evidence_id uuid, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."lock_cctv_evidence"(p_evidence_id uuid, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."lock_cctv_evidence"(p_evidence_id uuid, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."lock_cctv_evidence"(p_evidence_id uuid, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."log_bob_signing_event"(p_event_type text, p_fingerprint_sha256 text, p_success boolean, p_reason text DEFAULT NULL::text, p_request_id text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_identity_id uuid;
  v_event_id uuid;
  v_payload jsonb;
begin
  if p_event_type not in ('sign_request','sign_success','sign_failure','identity_check') then
    raise exception 'invalid event_type';
  end if;

  if p_fingerprint_sha256 is distinct from 'SHA256:ckUO3+2YpwZcGZFGvqu/R4cZpO1iXq8IaAL9pKQl3Y4' then
    raise exception 'fingerprint not allowlisted';
  end if;

  select id
  into v_identity_id
  from public.bob_signing_identities
  where provider = 'gitea'
    and key_name = 'bob-gitea'
    and fingerprint_sha256 = p_fingerprint_sha256
    and enabled = true
  order by created_at desc
  limit 1;

  if v_identity_id is null then
    raise exception 'active signing identity not found';
  end if;

  v_payload := jsonb_build_object(
    'namespace', 'gitea',
    'key_name', 'bob-gitea',
    'fingerprint_sha256', p_fingerprint_sha256,
    'success', p_success,
    'reason', p_reason,
    'request_id', p_request_id
  );

  insert into public.bob_signing_audit (
    identity_id,
    event_type,
    event_payload,
    actor_user_id
  )
  values (
    v_identity_id,
    p_event_type,
    v_payload,
    auth.uid()
  )
  returning id into v_event_id;

  return v_event_id;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."log_bob_signing_event"(p_event_type text, p_fingerprint_sha256 text, p_success boolean, p_reason text, p_request_id text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."log_bob_signing_event"(p_event_type text, p_fingerprint_sha256 text, p_success boolean, p_reason text, p_request_id text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."log_bob_signing_event"(p_event_type text, p_fingerprint_sha256 text, p_success boolean, p_reason text, p_request_id text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."log_user_management_action"(p_organization_id uuid, p_target_user_id uuid, p_action_type text, p_performed_by uuid, p_old_value jsonb DEFAULT NULL::jsonb, p_new_value jsonb DEFAULT NULL::jsonb, p_metadata jsonb DEFAULT NULL::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
  if p_organization_id is null or p_target_user_id is null or p_action_type is null or p_performed_by is null then raise exception 'Complete audit provenance is required';end if;
  insert into public.user_management_audit(target_user_id,action_type,performed_by,old_value,new_value,metadata)
  values(p_target_user_id,p_action_type,p_performed_by,p_old_value,p_new_value,coalesce(p_metadata,'{}'::jsonb)||jsonb_build_object('organization_id',p_organization_id)) returning id into v_id;
  return v_id;
end;$function$;
REVOKE ALL ON FUNCTION "public"."log_user_management_action"(p_organization_id uuid, p_target_user_id uuid, p_action_type text, p_performed_by uuid, p_old_value jsonb, p_new_value jsonb, p_metadata jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."log_user_management_action"(p_organization_id uuid, p_target_user_id uuid, p_action_type text, p_performed_by uuid, p_old_value jsonb, p_new_value jsonb, p_metadata jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."log_user_management_action"(p_organization_id uuid, p_target_user_id uuid, p_action_type text, p_performed_by uuid, p_old_value jsonb, p_new_value jsonb, p_metadata jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."manage_active_shift"(p_client_request_id uuid, p_shift_id uuid, p_expected_status text, p_expected_updated_at timestamp with time zone, p_action text, p_notes text DEFAULT NULL::text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_shift public.shifts%rowtype;
  v_existing public.audit_log%rowtype;
  v_previous jsonb;
  v_resulting jsonb;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Authentication is required';
  END IF;
  IF p_client_request_id IS NULL THEN
    RAISE EXCEPTION 'A client request ID is required';
  END IF;

  SELECT *
  INTO v_shift
  FROM public.shifts s
  WHERE s.id = p_shift_id
  FOR UPDATE;

  IF NOT FOUND OR NOT public.is_admin_for_org(v_shift.organization_id) THEN
    RAISE EXCEPTION 'Shift not found or access denied';
  END IF;

  SELECT *
  INTO v_existing
  FROM public.audit_log al
  WHERE al.organization_id = v_shift.organization_id
    AND al.metadata ->> 'client_request_id' = p_client_request_id::text
    AND al.action IN (
      'shift_stop_reorder',
      'shift_stop_skip',
      'shift_stop_cancel',
      'shift_amend',
      'shift_escalate',
      'shift_cancel'
    )
    AND al.target_table IN ('shift_stops', 'shifts')
  ORDER BY al.created_at DESC
  LIMIT 1;

  IF FOUND THEN
    IF v_existing.target_id IS DISTINCT FROM p_shift_id
      OR v_existing.action IS DISTINCT FROM ('shift_' || p_action) THEN
      RAISE EXCEPTION 'Client request ID was already used for a different runsheet action';
    END IF;
    RETURN jsonb_build_object(
      'replayed', true,
      'action', p_action,
      'target_id', p_shift_id,
      'previous', v_existing.metadata -> 'previous',
      'resulting', v_existing.metadata -> 'resulting'
    );
  END IF;

  IF v_shift.status IS DISTINCT FROM p_expected_status
    OR v_shift.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'Shift changed since it was opened';
  END IF;
  IF p_action IS NULL OR p_action NOT IN ('amend', 'escalate', 'cancel') THEN
    RAISE EXCEPTION 'Unsupported active shift action';
  END IF;
  IF nullif(trim(coalesce(p_reason, '')), '') IS NULL THEN
    RAISE EXCEPTION 'A reason is required';
  END IF;
  IF length(trim(p_reason)) > 1000 THEN
    RAISE EXCEPTION 'The reason is too long';
  END IF;
  IF v_shift.status IN ('completed', 'cancelled', 'declined') THEN
    RAISE EXCEPTION 'A closed shift cannot be changed';
  END IF;
  IF p_action = 'amend' AND nullif(trim(coalesce(p_notes, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Updated shift notes are required';
  END IF;
  IF p_action = 'amend' AND length(trim(p_notes)) > 4000 THEN
    RAISE EXCEPTION 'Shift notes are too long';
  END IF;
  IF p_action = 'cancel' AND v_shift.actual_start IS NOT NULL THEN
    RAISE EXCEPTION 'An active shift cannot be cancelled after it has started';
  END IF;

  v_previous := jsonb_build_object(
    'status', v_shift.status,
    'shift_health', v_shift.shift_health,
    'notes', v_shift.notes,
    'updated_at', v_shift.updated_at
  );

  UPDATE public.shifts
  SET
    notes = CASE WHEN p_action = 'amend' THEN trim(p_notes) ELSE notes END,
    shift_health = CASE WHEN p_action = 'escalate' THEN 'critical' ELSE shift_health END,
    status = CASE WHEN p_action = 'cancel' THEN 'cancelled' ELSE status END,
    updated_at = clock_timestamp()
  WHERE id = v_shift.id
  RETURNING * INTO v_shift;

  v_resulting := jsonb_build_object(
    'status', v_shift.status,
    'shift_health', v_shift.shift_health,
    'notes', v_shift.notes,
    'updated_at', v_shift.updated_at
  );

  INSERT INTO public.audit_log (
    organization_id,
    actor_user_id,
    action,
    target_table,
    target_id,
    metadata
  ) VALUES (
    v_shift.organization_id,
    v_actor,
    'shift_' || p_action,
    'shifts',
    v_shift.id,
    jsonb_build_object(
      'client_request_id', p_client_request_id,
      'reason', trim(p_reason),
      'previous', v_previous,
      'resulting', v_resulting
    )
  );

  RETURN jsonb_build_object(
    'replayed', false,
    'action', p_action,
    'target_id', v_shift.id,
    'previous', v_previous,
    'resulting', v_resulting
  );
END;
$function$;
REVOKE ALL ON FUNCTION "public"."manage_active_shift"(p_client_request_id uuid, p_shift_id uuid, p_expected_status text, p_expected_updated_at timestamp with time zone, p_action text, p_notes text, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_active_shift"(p_client_request_id uuid, p_shift_id uuid, p_expected_status text, p_expected_updated_at timestamp with time zone, p_action text, p_notes text, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."manage_active_shift"(p_client_request_id uuid, p_shift_id uuid, p_expected_status text, p_expected_updated_at timestamp with time zone, p_action text, p_notes text, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."manage_active_shift"(p_client_request_id uuid, p_shift_id uuid, p_expected_status text, p_expected_updated_at timestamp with time zone, p_action text, p_notes text, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."manage_agreement_extra_work_order"(p_client_request_id uuid, p_agreement_id uuid, p_action text, p_order_id uuid DEFAULT NULL::uuid, p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_title text DEFAULT NULL::text, p_scope text DEFAULT NULL::text, p_authority_kind text DEFAULT NULL::text, p_authority_reference text DEFAULT NULL::text, p_charge_code text DEFAULT NULL::text, p_rate_note text DEFAULT NULL::text, p_starts_on date DEFAULT NULL::date, p_ends_on date DEFAULT NULL::date, p_review_on date DEFAULT NULL::date, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_agreement public.service_agreements%rowtype;
  v_order public.agreement_extra_work_orders%rowtype;
  v_receipt public.audit_log%rowtype;
  v_before jsonb;
  v_next integer;
  v_code text := nullif(btrim(p_charge_code), '');
BEGIN
  IF p_client_request_id IS NULL THEN RAISE EXCEPTION 'client_request_id is required'; END IF;
  IF p_action IS NULL OR p_action NOT IN ('create', 'update', 'end') THEN RAISE EXCEPTION 'Unsupported Extra works action'; END IF;

  SELECT * INTO v_agreement FROM public.service_agreements WHERE id = p_agreement_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Service agreement not found'; END IF;
  IF v_actor IS NULL OR NOT public.is_admin_for_org(v_agreement.provider_organization_id) THEN
    RAISE EXCEPTION 'Provider administrator required';
  END IF;
  IF v_agreement.agreement_type <> 'operational' THEN
    RAISE EXCEPTION 'Extra works orders belong to operational agreements';
  END IF;

  SELECT * INTO v_receipt FROM public.audit_log a
  WHERE a.organization_id = v_agreement.provider_organization_id
    AND a.target_table = 'agreement_extra_work_orders'
    AND a.metadata->>'client_request_id' = p_client_request_id::text;
  IF FOUND THEN
    IF v_receipt.metadata->>'agreement_id' <> p_agreement_id::text OR v_receipt.metadata->>'request_action' <> p_action THEN
      RAISE EXCEPTION 'client_request_id was already used for another Extra works command';
    END IF;
    SELECT * INTO v_order FROM public.agreement_extra_work_orders WHERE id = v_receipt.target_id;
    RETURN to_jsonb(v_order) || jsonb_build_object('replayed', true);
  END IF;

  IF p_action IN ('update', 'end') THEN
    SELECT * INTO v_order FROM public.agreement_extra_work_orders
    WHERE id = p_order_id AND service_agreement_id = v_agreement.id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Extra works order not found'; END IF;
    IF p_expected_updated_at IS NULL OR v_order.updated_at IS DISTINCT FROM p_expected_updated_at THEN
      RAISE EXCEPTION 'This Extra works order changed since it was opened. Reload and try again.';
    END IF;
    IF v_order.ends_on IS NOT NULL AND v_order.ends_on < current_date THEN
      RAISE EXCEPTION 'This Extra works order has ended and can no longer be changed';
    END IF;
    v_before := to_jsonb(v_order);
  END IF;

  IF p_action = 'end' THEN
    IF p_ends_on IS NULL THEN RAISE EXCEPTION 'Give the last day the Extra work is authorised'; END IF;
    IF p_ends_on < v_order.starts_on - 1 THEN
      RAISE EXCEPTION 'The order cannot end before it started (%). To cancel one that never took effect, end it the day before it started.', to_char(v_order.starts_on, 'DD Mon YYYY');
    END IF;
    IF char_length(btrim(coalesce(p_reason, ''))) NOT BETWEEN 3 AND 500 THEN
      RAISE EXCEPTION 'Say why the Extra work is ending (3 to 500 characters)';
    END IF;
    UPDATE public.agreement_extra_work_orders
    SET ends_on = p_ends_on,
        review_on = CASE WHEN review_on IS NOT NULL AND review_on > p_ends_on THEN NULL ELSE review_on END,
        end_reason = btrim(p_reason), updated_by = v_actor, updated_at = clock_timestamp()
    WHERE id = v_order.id RETURNING * INTO v_order;
  ELSE
    IF char_length(btrim(coalesce(p_title, ''))) NOT BETWEEN 3 AND 160 THEN RAISE EXCEPTION 'Give the Extra work a short title (3 to 160 characters)'; END IF;
    IF char_length(btrim(coalesce(p_scope, ''))) NOT BETWEEN 10 AND 4000 THEN RAISE EXCEPTION 'Describe what the client asked for that is outside the contract (at least 10 characters)'; END IF;
    IF p_authority_kind IS NULL OR p_authority_kind NOT IN ('written', 'purchase_order', 'verbal', 'standing_instruction') THEN RAISE EXCEPTION 'Record how the client authorised this work'; END IF;
    IF p_authority_kind = 'verbal' AND nullif(btrim(p_authority_reference), '') IS NULL THEN RAISE EXCEPTION 'Verbal authority needs a note of who authorised it and when'; END IF;
    IF p_starts_on IS NULL THEN RAISE EXCEPTION 'Give the date the Extra work starts'; END IF;
    IF v_agreement.starts_on IS NOT NULL AND p_starts_on < v_agreement.starts_on THEN RAISE EXCEPTION 'Extra work cannot start before the agreement (%)', to_char(v_agreement.starts_on, 'DD Mon YYYY'); END IF;
    IF v_agreement.ends_on IS NOT NULL AND p_starts_on > v_agreement.ends_on THEN RAISE EXCEPTION 'The agreement ends on %; Extra work must start inside it', to_char(v_agreement.ends_on, 'DD Mon YYYY'); END IF;
    IF p_ends_on IS NOT NULL AND p_ends_on < p_starts_on THEN RAISE EXCEPTION 'The end date must be on or after the start date'; END IF;
    IF v_agreement.ends_on IS NOT NULL AND p_ends_on IS NOT NULL AND p_ends_on > v_agreement.ends_on THEN RAISE EXCEPTION 'Extra work cannot run past the agreement end (%)', to_char(v_agreement.ends_on, 'DD Mon YYYY'); END IF;
    IF p_review_on IS NOT NULL AND (p_review_on < p_starts_on OR (p_ends_on IS NOT NULL AND p_review_on > p_ends_on)) THEN RAISE EXCEPTION 'The review date must fall inside the Extra work term'; END IF;
    IF v_code IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM public.reference_codes rc
      WHERE rc.organization_id = v_agreement.provider_organization_id AND rc.code_type = 'charge_code' AND rc.code = v_code AND rc.is_active
    ) THEN RAISE EXCEPTION 'Charge code % is not in this organisation''s active catalog', v_code; END IF;

    IF p_action = 'create' THEN
      SELECT coalesce(max(nullif(substring(reference FROM '^EW-(\d+)$'), '')::integer), 0) + 1 INTO v_next
      FROM public.agreement_extra_work_orders WHERE service_agreement_id = v_agreement.id;
      INSERT INTO public.agreement_extra_work_orders(
        organization_id, service_agreement_id, reference, title, scope, authority_kind, authority_reference,
        charge_code, rate_note, starts_on, ends_on, review_on, created_by)
      VALUES (
        v_agreement.provider_organization_id, v_agreement.id, 'EW-' || lpad(v_next::text, 3, '0'), btrim(p_title), btrim(p_scope),
        p_authority_kind, nullif(btrim(p_authority_reference), ''), v_code, nullif(btrim(p_rate_note), ''),
        p_starts_on, p_ends_on, p_review_on, v_actor)
      RETURNING * INTO v_order;
    ELSE
      IF p_starts_on <> v_order.starts_on AND v_order.starts_on <= current_date AND EXISTS (
        SELECT 1 FROM public.dispatch_jobs j WHERE j.extra_work_order_id = v_order.id
      ) THEN RAISE EXCEPTION 'Jobs are already billed under this order; its start date cannot move'; END IF;
      UPDATE public.agreement_extra_work_orders
      SET title = btrim(p_title), scope = btrim(p_scope), authority_kind = p_authority_kind,
          authority_reference = nullif(btrim(p_authority_reference), ''), charge_code = v_code,
          rate_note = nullif(btrim(p_rate_note), ''), starts_on = p_starts_on, ends_on = p_ends_on,
          review_on = p_review_on, updated_by = v_actor, updated_at = clock_timestamp()
      WHERE id = v_order.id RETURNING * INTO v_order;
    END IF;
  END IF;

  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_agreement.provider_organization_id, v_actor, 'agreement_extra_work_order_' || p_action, 'agreement_extra_work_orders', v_order.id,
    jsonb_strip_nulls(jsonb_build_object(
      'client_request_id', p_client_request_id, 'request_action', p_action, 'agreement_id', v_agreement.id,
      'client_organization_id', v_agreement.client_organization_id, 'reference', v_order.reference,
      'reason', nullif(btrim(p_reason), ''), 'before', v_before, 'after', to_jsonb(v_order))));
  RETURN to_jsonb(v_order) || jsonb_build_object('replayed', false);
END;
$function$;
COMMENT ON FUNCTION "public"."manage_agreement_extra_work_order"(p_client_request_id uuid, p_agreement_id uuid, p_action text, p_order_id uuid, p_expected_updated_at timestamp with time zone, p_title text, p_scope text, p_authority_kind text, p_authority_reference text, p_charge_code text, p_rate_note text, p_starts_on date, p_ends_on date, p_review_on date, p_reason text) IS 'Provider administrator creates, updates or ends an Extra works order (authorised work outside the contracted scope; not a variation). Idempotent by client_request_id; optimistic concurrency by updated_at; audited with before/after.';
REVOKE ALL ON FUNCTION "public"."manage_agreement_extra_work_order"(p_client_request_id uuid, p_agreement_id uuid, p_action text, p_order_id uuid, p_expected_updated_at timestamp with time zone, p_title text, p_scope text, p_authority_kind text, p_authority_reference text, p_charge_code text, p_rate_note text, p_starts_on date, p_ends_on date, p_review_on date, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_agreement_extra_work_order"(p_client_request_id uuid, p_agreement_id uuid, p_action text, p_order_id uuid, p_expected_updated_at timestamp with time zone, p_title text, p_scope text, p_authority_kind text, p_authority_reference text, p_charge_code text, p_rate_note text, p_starts_on date, p_ends_on date, p_review_on date, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."manage_agreement_extra_work_order"(p_client_request_id uuid, p_agreement_id uuid, p_action text, p_order_id uuid, p_expected_updated_at timestamp with time zone, p_title text, p_scope text, p_authority_kind text, p_authority_reference text, p_charge_code text, p_rate_note text, p_starts_on date, p_ends_on date, p_review_on date, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."manage_agreement_extra_work_order"(p_client_request_id uuid, p_agreement_id uuid, p_action text, p_order_id uuid, p_expected_updated_at timestamp with time zone, p_title text, p_scope text, p_authority_kind text, p_authority_reference text, p_charge_code text, p_rate_note text, p_starts_on date, p_ends_on date, p_review_on date, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."manage_asset"(p_client_request_id uuid, p_action text, p_asset_id uuid DEFAULT NULL::uuid, p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_asset_type text DEFAULT NULL::text, p_name text DEFAULT NULL::text, p_serial_number text DEFAULT NULL::text, p_registration text DEFAULT NULL::text, p_make text DEFAULT NULL::text, p_model text DEFAULT NULL::text, p_year integer DEFAULT NULL::integer, p_status text DEFAULT NULL::text, p_next_inspection_date date DEFAULT NULL::date, p_notes text DEFAULT NULL::text)
 RETURNS assets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_provider uuid;
  v_asset public.assets%rowtype;
  v_previous public.assets%rowtype;
  v_receipt public.audit_log%rowtype;
  v_name text := nullif(btrim(coalesce(p_name, '')), '');
  v_serial_number text := nullif(upper(btrim(coalesce(p_serial_number, ''))), '');
  v_registration text := nullif(upper(regexp_replace(btrim(coalesce(p_registration, '')), '\s+', '', 'g')), '');
  v_make text := nullif(btrim(coalesce(p_make, '')), '');
  v_model text := nullif(btrim(coalesce(p_model, '')), '');
  v_notes text := nullif(btrim(coalesce(p_notes, '')), '');
  v_audit_action text;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Active user required';
  END IF;
  IF p_client_request_id IS NULL THEN
    RAISE EXCEPTION 'client_request_id is required';
  END IF;
  IF p_action NOT IN ('create', 'update') THEN
    RAISE EXCEPTION 'Unsupported manage_asset action %', p_action;
  END IF;

  SELECT actor.organization_id
    INTO v_provider
    FROM public.user_profiles actor
   WHERE actor.id = v_actor
     AND actor.deactivated_at IS NULL;
  IF v_provider IS NULL OR NOT public.is_admin_for_org(v_provider) THEN
    RAISE EXCEPTION 'Active fleet administrator required';
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended('asset-management:' || p_client_request_id::text, 0)
  );

  SELECT al.*
    INTO v_receipt
    FROM public.audit_log al
   WHERE al.organization_id = v_provider
     AND al.target_table = 'assets'
     AND al.action IN ('asset_created', 'asset_updated')
     AND al.metadata ->> 'client_request_id' = p_client_request_id::text;
  IF FOUND THEN
    IF v_receipt.metadata ->> 'request_action' IS DISTINCT FROM p_action
       OR (p_asset_id IS NOT NULL AND v_receipt.target_id IS DISTINCT FROM p_asset_id) THEN
      RAISE EXCEPTION 'client_request_id has already been used for a different asset action';
    END IF;
    RETURN jsonb_populate_record(NULL::public.assets, v_receipt.metadata -> 'record');
  END IF;

  IF v_name IS NULL THEN
    RAISE EXCEPTION 'Asset name is required';
  END IF;
  IF p_asset_type NOT IN (
    'vehicle', 'radio', 'body_camera', 'torch', 'uniform',
    'first_aid_kit', 'ems_device', 'other'
  ) THEN
    RAISE EXCEPTION 'Unsupported asset type';
  END IF;
  IF coalesce(p_status, 'available') NOT IN (
    'available', 'in_use', 'maintenance', 'retired', 'lost'
  ) THEN
    RAISE EXCEPTION 'Unsupported asset status';
  END IF;
  IF p_year IS NOT NULL
     AND (p_year < 1900 OR p_year > extract(year FROM current_date)::integer + 1) THEN
    RAISE EXCEPTION 'Asset year must be between 1900 and next year';
  END IF;

  IF p_action = 'create' THEN
    IF p_asset_id IS NOT NULL OR p_expected_updated_at IS NOT NULL THEN
      RAISE EXCEPTION 'New assets cannot carry an existing asset ID or expected timestamp';
    END IF;
    IF p_status = 'in_use' THEN
      RAISE EXCEPTION 'An asset becomes in use only when it is signed out to a shift';
    END IF;

    INSERT INTO public.assets (
      organization_id,
      asset_type,
      name,
      serial_number,
      registration,
      make,
      model,
      year,
      status,
      next_inspection_date,
      notes,
      updated_at
    )
    VALUES (
      v_provider,
      p_asset_type,
      v_name,
      v_serial_number,
      v_registration,
      v_make,
      v_model,
      p_year,
      coalesce(p_status, 'available'),
      p_next_inspection_date,
      v_notes,
      now()
    )
    RETURNING * INTO v_asset;
    v_audit_action := 'asset_created';
  ELSE
    IF p_asset_id IS NULL OR p_expected_updated_at IS NULL THEN
      RAISE EXCEPTION 'Asset ID and expected updated timestamp are required for an update';
    END IF;

    SELECT a.*
      INTO v_previous
      FROM public.assets a
     WHERE a.id = p_asset_id
       AND a.organization_id = v_provider
     FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Asset not found';
    END IF;
    IF v_previous.updated_at IS DISTINCT FROM p_expected_updated_at THEN
      RAISE EXCEPTION 'This asset changed after it was opened. Reload it before saving.';
    END IF;
    IF p_asset_type IS DISTINCT FROM v_previous.asset_type THEN
      RAISE EXCEPTION 'Asset type cannot be changed after registration';
    END IF;
    IF p_status = 'in_use' AND v_previous.status <> 'in_use' THEN
      RAISE EXCEPTION 'An asset becomes in use only when it is signed out to a shift';
    END IF;
    IF p_status = 'available' AND EXISTS (
      SELECT 1
        FROM public.shift_assets link
       WHERE link.asset_id = v_previous.id
         AND link.returned_at IS NULL
    ) THEN
      RAISE EXCEPTION 'Asset is still assigned to an active shift';
    END IF;

    UPDATE public.assets
       SET name = v_name,
           serial_number = v_serial_number,
           registration = v_registration,
           make = v_make,
           model = v_model,
           year = p_year,
           status = coalesce(p_status, status),
           next_inspection_date = p_next_inspection_date,
           notes = v_notes,
           updated_at = now()
     WHERE id = v_previous.id
    RETURNING * INTO v_asset;
    v_audit_action := 'asset_updated';
  END IF;

  INSERT INTO public.audit_log (
    organization_id,
    actor_user_id,
    action,
    target_table,
    target_id,
    metadata
  )
  VALUES (
    v_provider,
    v_actor,
    v_audit_action,
    'assets',
    v_asset.id,
    jsonb_build_object(
      'client_request_id', p_client_request_id,
      'request_action', p_action,
      'previous_record', CASE
        WHEN v_previous.id IS NULL THEN NULL
        ELSE to_jsonb(v_previous)
      END,
      'record', to_jsonb(v_asset)
    )
  );

  RETURN v_asset;
END;
$function$;
COMMENT ON FUNCTION "public"."manage_asset"(p_client_request_id uuid, p_action text, p_asset_id uuid, p_expected_updated_at timestamp with time zone, p_asset_type text, p_name text, p_serial_number text, p_registration text, p_make text, p_model text, p_year integer, p_status text, p_next_inspection_date date, p_notes text) IS 'Replay-safe, optimistic fleet and equipment register authority. Creates or updates one organization-owned asset, normalizes identifiers, prevents direct in-use transitions, and records before/after audit evidence.';
REVOKE ALL ON FUNCTION "public"."manage_asset"(p_client_request_id uuid, p_action text, p_asset_id uuid, p_expected_updated_at timestamp with time zone, p_asset_type text, p_name text, p_serial_number text, p_registration text, p_make text, p_model text, p_year integer, p_status text, p_next_inspection_date date, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_asset"(p_client_request_id uuid, p_action text, p_asset_id uuid, p_expected_updated_at timestamp with time zone, p_asset_type text, p_name text, p_serial_number text, p_registration text, p_make text, p_model text, p_year integer, p_status text, p_next_inspection_date date, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."manage_asset"(p_client_request_id uuid, p_action text, p_asset_id uuid, p_expected_updated_at timestamp with time zone, p_asset_type text, p_name text, p_serial_number text, p_registration text, p_make text, p_model text, p_year integer, p_status text, p_next_inspection_date date, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."manage_asset"(p_client_request_id uuid, p_action text, p_asset_id uuid, p_expected_updated_at timestamp with time zone, p_asset_type text, p_name text, p_serial_number text, p_registration text, p_make text, p_model text, p_year integer, p_status text, p_next_inspection_date date, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."manage_biosecurity_assessment_review"(p_assessment_id uuid, p_expected_review_version integer, p_action text, p_priority text, p_assigned_reviewer_id uuid, p_review_due_at timestamp with time zone, p_species_decision text, p_confirmed_species_name text, p_notes text)
 RETURNS TABLE(assessment_id uuid, review_status text, review_version integer, review_priority text, assigned_reviewer_id uuid, review_due_at timestamp with time zone, species_review_decision text, confirmed_species_name text, species_confirmed boolean, follow_up_required boolean, reviewed_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_item public.biosecurity_assessments%rowtype;
  v_next_status text;
  v_notes text := NULLIF(BTRIM(COALESCE(p_notes, '')), '');
  v_species_name text := NULLIF(BTRIM(COALESCE(p_confirmed_species_name, '')), '');
  v_officer uuid;
  v_now timestamptz := clock_timestamp();
BEGIN
  SELECT assessment.* INTO v_item
  FROM public.biosecurity_assessments assessment
  WHERE assessment.id = p_assessment_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Biosecurity assessment not found';
  END IF;
  IF NOT public.is_admin_for_org(v_item.organization_id) THEN
    RAISE EXCEPTION 'Active Biosecurity administrator required';
  END IF;
  IF v_item.review_version <> p_expected_review_version THEN
    RAISE EXCEPTION 'Biosecurity review changed from expected version % to %', p_expected_review_version, v_item.review_version;
  END IF;
  IF v_notes IS NULL OR char_length(v_notes) < 10 THEN
    RAISE EXCEPTION 'Review rationale must contain at least 10 characters';
  END IF;
  IF p_priority NOT IN ('urgent', 'high', 'routine', 'monitor') THEN
    RAISE EXCEPTION 'Unsupported biosecurity review priority';
  END IF;
  IF p_assigned_reviewer_id IS NULL OR NOT EXISTS (
    SELECT 1
    FROM public.user_profiles reviewer
    WHERE reviewer.id = p_assigned_reviewer_id
      AND reviewer.organization_id = v_item.organization_id
      AND reviewer.deactivated_at IS NULL
      AND reviewer.role IN ('grand_master', 'master', 'admin', 'admin_officer')
  ) THEN
    RAISE EXCEPTION 'Active organization reviewer required';
  END IF;

  IF p_action = 'triage' AND v_item.review_status IN ('awaiting_review', 'triaged', 'follow_up') THEN
    v_next_status := 'triaged';
    IF p_species_decision <> 'pending' THEN
      RAISE EXCEPTION 'Triage cannot make the final species decision';
    END IF;
  ELSIF p_action = 'require_follow_up' AND v_item.review_status IN ('awaiting_review', 'triaged', 'follow_up') THEN
    v_next_status := 'follow_up';
    IF p_species_decision <> 'insufficient_evidence' THEN
      RAISE EXCEPTION 'Follow-up requires an insufficient-evidence decision';
    END IF;
  ELSIF p_action = 'close' AND v_item.review_status IN ('awaiting_review', 'triaged', 'follow_up') THEN
    v_next_status := 'closed';
    IF p_species_decision NOT IN ('confirmed', 'rejected') THEN
      RAISE EXCEPTION 'Closure requires a confirmed or rejected species decision';
    END IF;
    IF p_species_decision = 'confirmed' AND v_species_name IS NULL THEN
      RAISE EXCEPTION 'Confirmed species name is required';
    END IF;
  ELSE
    RAISE EXCEPTION 'Unsupported Biosecurity review transition from % using %', v_item.review_status, p_action;
  END IF;

  IF v_next_status <> 'closed' THEN
    IF p_review_due_at IS NULL OR p_review_due_at <= v_now THEN
      RAISE EXCEPTION 'An active review requires a future due date';
    END IF;
    IF (p_priority = 'urgent' AND p_review_due_at > v_now + interval '2 days')
       OR (p_priority = 'high' AND p_review_due_at > v_now + interval '7 days')
       OR (p_priority = 'routine' AND p_review_due_at > v_now + interval '30 days')
       OR (p_priority = 'monitor' AND p_review_due_at > v_now + interval '90 days') THEN
      RAISE EXCEPTION 'Review due date exceeds the selected priority window';
    END IF;
  END IF;

    UPDATE public.biosecurity_assessments AS assessment
  SET review_status = v_next_status,
      review_version = assessment.review_version + 1,
      review_priority = p_priority,
      assigned_reviewer_id = p_assigned_reviewer_id,
      review_due_at = CASE WHEN v_next_status = 'closed' THEN NULL ELSE p_review_due_at END,
      species_review_decision = p_species_decision,
      confirmed_species_name = CASE WHEN p_species_decision = 'confirmed' THEN v_species_name ELSE NULL END,
      species_confirmed = p_species_decision = 'confirmed',
      reviewed_by = v_actor,
      reviewed_at = v_now,
      review_notes = v_notes,
      follow_up_required = v_next_status = 'follow_up',
      status = CASE WHEN v_next_status = 'closed' THEN 'closed' ELSE 'open' END
  WHERE assessment.id = v_item.id
  RETURNING * INTO v_item;

  v_officer := COALESCE(v_item.officer_user_id, v_item.officer_id);
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (
    v_item.organization_id,
    v_actor,
    'biosecurity_assessment_reviewed',
    'biosecurity_assessments',
    v_item.id,
    jsonb_build_object(
      'review_action', p_action,
      'review_status', v_item.review_status,
      'review_version', v_item.review_version,
      'priority', v_item.review_priority,
      'assigned_reviewer_id', v_item.assigned_reviewer_id,
      'species_decision', v_item.species_review_decision,
      'source_officer_id', v_officer,
      'rationale', v_notes
    )
  );

  IF v_officer IS NOT NULL THEN
    PERFORM public.enqueue_notification(
      p_organization_id => v_item.organization_id,
      p_category => 'biosecurity_review',
      p_title => CASE
        WHEN v_next_status = 'follow_up' THEN 'Biosecurity evidence follow-up required'
        WHEN v_next_status = 'closed' THEN 'Biosecurity assessment decision recorded'
        ELSE 'Biosecurity assessment triaged'
      END,
      p_body => v_notes,
      p_severity => CASE WHEN v_item.review_priority IN ('urgent', 'high') OR v_next_status = 'follow_up' THEN 'warning' ELSE 'info' END,
      p_recipient_user_id => v_officer,
      p_link_page => 'biosecurity-review',
      p_link_payload => jsonb_build_object('assessment_id', v_item.id),
      p_dedup_key => 'biosecurity_review:' || v_item.id::text || ':' || v_item.review_version::text
    );
  END IF;

  RETURN QUERY SELECT
    v_item.id,
    v_item.review_status,
    v_item.review_version,
    v_item.review_priority,
    v_item.assigned_reviewer_id,
    v_item.review_due_at,
    v_item.species_review_decision,
    v_item.confirmed_species_name,
    v_item.species_confirmed,
    v_item.follow_up_required,
    v_item.reviewed_at;
END;
$function$;
COMMENT ON FUNCTION "public"."manage_biosecurity_assessment_review"(p_assessment_id uuid, p_expected_review_version integer, p_action text, p_priority text, p_assigned_reviewer_id uuid, p_review_due_at timestamp with time zone, p_species_decision text, p_confirmed_species_name text, p_notes text) IS 'Versioned administrator review boundary for biosecurity triage, evidence follow-up, and explicit human species decisions. Audits and personally notifies the reporting officer.';
REVOKE ALL ON FUNCTION "public"."manage_biosecurity_assessment_review"(p_assessment_id uuid, p_expected_review_version integer, p_action text, p_priority text, p_assigned_reviewer_id uuid, p_review_due_at timestamp with time zone, p_species_decision text, p_confirmed_species_name text, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_biosecurity_assessment_review"(p_assessment_id uuid, p_expected_review_version integer, p_action text, p_priority text, p_assigned_reviewer_id uuid, p_review_due_at timestamp with time zone, p_species_decision text, p_confirmed_species_name text, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."manage_biosecurity_assessment_review"(p_assessment_id uuid, p_expected_review_version integer, p_action text, p_priority text, p_assigned_reviewer_id uuid, p_review_due_at timestamp with time zone, p_species_decision text, p_confirmed_species_name text, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."manage_biosecurity_assessment_review"(p_assessment_id uuid, p_expected_review_version integer, p_action text, p_priority text, p_assigned_reviewer_id uuid, p_review_due_at timestamp with time zone, p_species_decision text, p_confirmed_species_name text, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."manage_biosecurity_assessment_review"(p_assessment_id uuid, p_expected_review_state text, p_action text, p_notes text)
 RETURNS TABLE(assessment_id uuid, review_state text, reviewed_by uuid, reviewed_at timestamp with time zone, follow_up_required boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_item public.biosecurity_assessments%rowtype;
  v_officer uuid;
  v_next text;
  v_notes text := nullif(trim(coalesce(p_notes, '')), '');
begin
  select b.* into v_item from public.biosecurity_assessments b where b.id = p_assessment_id for update;
  if not found then raise exception 'Biosecurity assessment not found'; end if;
  if not public.is_admin_for_org(v_item.organization_id) then raise exception 'Active Biosecurity administrator required'; end if;
  if v_item.review_state <> p_expected_review_state then
    raise exception 'Biosecurity review changed from expected state % to %', p_expected_review_state, v_item.review_state;
  end if;
  if v_notes is null then raise exception 'Review notes are required'; end if;

  if p_action = 'triage' and v_item.review_state in ('submitted', 'requires_supervisor_review') then
    v_next := 'triaged';
  elsif p_action = 'require_review' then
    v_next := 'requires_supervisor_review';
  elsif p_action = 'close' and v_item.review_state in ('submitted', 'requires_supervisor_review', 'triaged') then
    v_next := 'closed';
  else
    raise exception 'Unsupported biosecurity review transition from % using %', v_item.review_state, p_action;
  end if;

  update public.biosecurity_assessments
    set review_state = v_next,
        reviewed_by = v_actor,
        reviewed_at = clock_timestamp(),
        review_notes = v_notes,
        follow_up_required = case when v_next = 'requires_supervisor_review' then true when v_next = 'closed' then false else biosecurity_assessments.follow_up_required end
    where id = v_item.id
    returning * into v_item;

  v_officer := coalesce(v_item.officer_user_id, v_item.officer_id);

  insert into public.audit_log (
    organization_id, actor_user_id, action, target_table, target_id, metadata
  ) values (
    v_item.organization_id, v_actor, 'biosecurity_assessment_reviewed', 'biosecurity_assessments', v_item.id,
    jsonb_build_object('previous_review_state', p_expected_review_state, 'review_state', v_next, 'action', p_action, 'source_officer_id', v_officer, 'notes', v_notes)
  );

  if v_officer is not null then
    perform public.enqueue_notification(
      p_organization_id => v_item.organization_id,
      p_category => 'report_reviewed',
      p_title => 'Biosecurity assessment reviewed',
      p_body => v_notes,
      p_severity => case when v_next = 'requires_supervisor_review' then 'warning' else 'info' end,
      p_recipient_user_id => v_officer,
      p_link_page => 'biosecurity-review',
      p_link_payload => jsonb_build_object('assessment_id', v_item.id),
      p_dedup_key => 'biosecurity_review:' || v_item.id::text || ':' || v_item.review_state
    );
  end if;

  return query select v_item.id, v_item.review_state, v_item.reviewed_by, v_item.reviewed_at, v_item.follow_up_required;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."manage_biosecurity_assessment_review"(p_assessment_id uuid, p_expected_review_state text, p_action text, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_biosecurity_assessment_review"(p_assessment_id uuid, p_expected_review_state text, p_action text, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."manage_biosecurity_assessment_review"(p_assessment_id uuid, p_expected_review_state text, p_action text, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."manage_biosecurity_assessment_review"(p_assessment_id uuid, p_expected_review_state text, p_action text, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."manage_bob_message_feedback"(p_message_id uuid, p_rating text, p_note text DEFAULT NULL::text)
 RETURNS bob_message_feedback
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_message public.bob_messages%ROWTYPE;
  v_conversation public.bob_conversations%ROWTYPE;
  v_note text := NULLIF(btrim(p_note), '');
  v_feedback public.bob_message_feedback%ROWTYPE;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF p_rating NOT IN ('up', 'down') THEN
    RAISE EXCEPTION 'Rating must be up or down';
  END IF;

  IF v_note IS NOT NULL AND length(v_note) > 1000 THEN
    RAISE EXCEPTION 'Feedback note must be 1000 characters or fewer';
  END IF;

  SELECT *
  INTO v_message
  FROM public.bob_messages
  WHERE id = p_message_id;

  IF v_message.id IS NULL OR v_message.role <> 'assistant' THEN
    RAISE EXCEPTION 'Assistant message not found';
  END IF;

  SELECT *
  INTO v_conversation
  FROM public.bob_conversations
  WHERE id = v_message.conversation_id
    AND organization_id = v_message.organization_id;

  IF v_conversation.id IS NULL
     OR v_conversation.user_id <> v_actor
     OR NOT public.org_access_allowed(v_message.organization_id) THEN
    RAISE EXCEPTION 'Message feedback is not authorized';
  END IF;

  INSERT INTO public.bob_message_feedback (
    organization_id,
    conversation_id,
    message_id,
    user_id,
    rating,
    note
  )
  VALUES (
    v_message.organization_id,
    v_message.conversation_id,
    v_message.id,
    v_actor,
    p_rating,
    CASE WHEN p_rating = 'down' THEN v_note ELSE NULL END
  )
  ON CONFLICT (message_id, user_id) DO UPDATE
  SET rating = EXCLUDED.rating,
      note = EXCLUDED.note
  RETURNING * INTO v_feedback;

  RETURN v_feedback;
END;
$function$;
COMMENT ON FUNCTION "public"."manage_bob_message_feedback"(p_message_id uuid, p_rating text, p_note text) IS 'Records or updates the caller feedback for one assistant reply in their own Bob conversation. Organization, conversation, and user are derived from the persisted message.';
