CREATE OR REPLACE FUNCTION "public"."manage_breach_alert"(p_alert_id uuid, p_expected_status text, p_action text, p_notes text)
 RETURNS TABLE(alert_id uuid, alert_status text, action_type text, actioned_at timestamp with time zone, source_officer_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_alert public.breach_alerts%rowtype;
  v_officer uuid;
  v_next_status text;
  v_action_type text;
  v_notes text := nullif(trim(coalesce(p_notes, '')), '');
begin
  select b.* into v_alert
  from public.breach_alerts b
  where b.id = p_alert_id
  for update;
  if not found then
    raise exception 'Breach alert not found';
  end if;
  if not public.is_admin_for_org(v_alert.organization_id) then
    raise exception 'Active compliance administrator required';
  end if;
  if v_alert.status <> p_expected_status then
    raise exception 'Breach alert changed from expected status % to %', p_expected_status, v_alert.status;
  end if;
  if v_notes is null then
    raise exception 'Breach decision notes are required';
  end if;

  if v_alert.status = 'open'
     and p_action in ('verbal_warning', 'written_warning', 'notice_to_vacate', 'infringement', 'tow_request', 'welfare_referral') then
    v_next_status := 'actioned';
    v_action_type := p_action;
  elsif v_alert.status = 'open' and p_action = 'dismissed' then
    v_next_status := 'dismissed';
    v_action_type := 'dismissed';
  elsif v_alert.status = 'acknowledged' and p_action = 'approve_requested' then
    if v_alert.requested_action is null then
      raise exception 'Officer request has no proposed action';
    end if;
    v_next_status := 'actioned';
    v_action_type := v_alert.requested_action;
  elsif v_alert.status = 'acknowledged' and p_action = 'dismissed' then
    v_next_status := 'dismissed';
    v_action_type := 'dismissed';
  elsif v_alert.status = 'actioned' and p_action in ('resolved', 'exempt_homeless') then
    v_next_status := p_action;
    v_action_type := v_alert.action_type;
  else
    raise exception 'Unsupported breach transition from % using %', v_alert.status, p_action;
  end if;

  update public.breach_alerts
  set status = v_next_status,
      action_type = v_action_type,
      actioned_by = v_actor,
      actioned_at = clock_timestamp(),
      notes = concat_ws(E'\n', nullif(notes, ''), 'Decision: ' || v_notes)
  where id = v_alert.id
  returning * into v_alert;

  select o.officer_id into v_officer
  from public.observations o
  where o.id = v_alert.observation_id;

  insert into public.audit_log(
    organization_id, actor_user_id, action, target_table, target_id, metadata
  ) values (
    v_alert.organization_id,
    v_actor,
    'breach_alert_managed',
    'breach_alerts',
    v_alert.id,
    jsonb_build_object(
      'previous_status', p_expected_status,
      'status', v_alert.status,
      'action', p_action,
      'requested_action', v_alert.requested_action,
      'request_id', v_alert.request_id,
      'source_officer_id', v_officer,
      'notes', v_notes
    )
  );

  if v_officer is not null then
    perform public.enqueue_notification(
      p_organization_id => v_alert.organization_id,
      p_category => 'breach_decision',
      p_title => 'Breach review updated',
      p_body => v_notes,
      p_severity => 'info',
      p_recipient_user_id => v_officer,
      p_link_page => 'breach-decision',
      p_link_payload => jsonb_build_object('breach_alert_id', v_alert.id),
      p_dedup_key => 'breach_decision:' || v_alert.id::text || ':' || v_alert.status
    );
  end if;

  return query
    select v_alert.id, v_alert.status, v_alert.action_type, v_alert.actioned_at, v_officer;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."manage_breach_alert"(p_alert_id uuid, p_expected_status text, p_action text, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_breach_alert"(p_alert_id uuid, p_expected_status text, p_action text, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."manage_breach_alert"(p_alert_id uuid, p_expected_status text, p_action text, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."manage_breach_alert"(p_alert_id uuid, p_expected_status text, p_action text, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."manage_cctv_inference_job"(p_job_id uuid, p_organization_id uuid, p_action text)
 RETURNS TABLE(job_id uuid, action text, new_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_job public.inference_jobs%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL OR NOT public.org_access_allowed(p_organization_id) THEN
    RAISE EXCEPTION 'CCTV job access denied';
  END IF;

  SELECT * INTO v_job
    FROM public.inference_jobs
   WHERE id = p_job_id
     AND organization_id = p_organization_id
     AND domain = 'video_motion'
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'CCTV job not found';
  END IF;

  IF p_action = 'retry' THEN
    IF v_job.status NOT IN ('failed', 'inconclusive', 'manual_review_required') THEN
      RAISE EXCEPTION 'Only failed or reviewable CCTV jobs can be retried';
    END IF;
    UPDATE public.inference_jobs
       SET status = 'queued', completed_at = NULL, created_at = clock_timestamp()
     WHERE id = v_job.id;
    RETURN QUERY SELECT v_job.id, p_action, 'queued'::text;
    RETURN;
  END IF;

  IF p_action = 'reprocess' THEN
    IF v_job.status <> 'complete' THEN
      RAISE EXCEPTION 'Only a completed CCTV job can be reprocessed';
    END IF;
    DELETE FROM public.cctv_entity_observations
     WHERE inference_job_id = v_job.id AND review_state = 'unreviewed';
    UPDATE public.inference_jobs
       SET status = 'queued', completed_at = NULL, created_at = clock_timestamp()
     WHERE id = v_job.id;
    RETURN QUERY SELECT v_job.id, p_action, 'queued'::text;
    RETURN;
  END IF;

  IF p_action = 'cancel' THEN
    IF v_job.status NOT IN ('queued', 'processing') THEN
      RAISE EXCEPTION 'Only queued or processing CCTV jobs can be cancelled';
    END IF;
    UPDATE public.inference_jobs
       SET status = 'cancelled', completed_at = clock_timestamp()
     WHERE id = v_job.id;
    RETURN QUERY SELECT v_job.id, p_action, 'cancelled'::text;
    RETURN;
  END IF;

  IF p_action = 'close' THEN
    IF v_job.status NOT IN ('failed', 'inconclusive', 'manual_review_required') THEN
      RAISE EXCEPTION 'Only failed or reviewable CCTV jobs can be closed';
    END IF;
    UPDATE public.inference_jobs
       SET status = 'cancelled', completed_at = clock_timestamp()
     WHERE id = v_job.id;
    RETURN QUERY SELECT v_job.id, p_action, 'cancelled'::text;
    RETURN;
  END IF;

  IF p_action = 'archive' THEN
    IF v_job.status IN ('queued', 'processing') THEN
      RAISE EXCEPTION 'Running CCTV jobs must be cancelled before archiving';
    END IF;
    UPDATE public.inference_jobs
       SET status = 'archived', completed_at = COALESCE(completed_at, clock_timestamp())
     WHERE id = v_job.id;
    RETURN QUERY SELECT v_job.id, p_action, 'archived'::text;
    RETURN;
  END IF;

  IF p_action = 'delete' THEN
    IF v_job.status NOT IN ('failed', 'inconclusive', 'cancelled', 'archived') THEN
      RAISE EXCEPTION 'Only terminal CCTV jobs can be deleted';
    END IF;
    DELETE FROM public.inference_jobs WHERE id = v_job.id;
    RETURN QUERY SELECT v_job.id, p_action, 'deleted'::text;
    RETURN;
  END IF;

  RAISE EXCEPTION 'Unsupported CCTV job action';
END;
$function$;
REVOKE ALL ON FUNCTION "public"."manage_cctv_inference_job"(p_job_id uuid, p_organization_id uuid, p_action text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_cctv_inference_job"(p_job_id uuid, p_organization_id uuid, p_action text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."manage_cctv_inference_job"(p_job_id uuid, p_organization_id uuid, p_action text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."manage_cctv_inference_job"(p_job_id uuid, p_organization_id uuid, p_action text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."manage_commercial_discount_schedule"(p_client_request_id uuid, p_action text, p_schedule_id uuid DEFAULT NULL::uuid, p_name text DEFAULT NULL::text, p_effective_from date DEFAULT NULL::date, p_effective_to date DEFAULT NULL::date, p_notes text DEFAULT NULL::text)
 RETURNS commercial_discount_schedules
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_provider uuid;
  v_schedule public.commercial_discount_schedules%rowtype;
  v_name text := nullif(trim(coalesce(p_name, '')), '');
begin
  if p_client_request_id is null then raise exception 'client_request_id is required'; end if;
  select organization_id into v_provider from public.user_profiles where id = v_actor and deactivated_at is null;
  if v_provider is null or not public.is_admin_for_org(v_provider) then raise exception 'Active finance administrator required'; end if;
  if p_action = 'create' then
    if v_name is null then raise exception 'Discount schedule name is required'; end if;
    if p_effective_to is not null and p_effective_to < coalesce(p_effective_from, current_date) then raise exception 'Effective end cannot precede effective start'; end if;
    select * into v_schedule from public.commercial_discount_schedules where provider_organization_id = v_provider and client_request_id = p_client_request_id;
    if found then return v_schedule; end if;
    insert into public.commercial_discount_schedules(provider_organization_id,name,effective_from,effective_to,notes,client_request_id,created_by)
    values(v_provider,v_name,coalesce(p_effective_from,current_date),p_effective_to,nullif(trim(coalesce(p_notes,'')),''),p_client_request_id,v_actor)
    returning * into v_schedule;
  else
    select * into v_schedule from public.commercial_discount_schedules where id = p_schedule_id for update;
    if not found or v_schedule.provider_organization_id <> v_provider then raise exception 'Discount schedule not found in your organization'; end if;
    if p_action = 'activate' then
      if not exists (select 1 from public.commercial_discount_schedule_rules where schedule_id = v_schedule.id) then raise exception 'An active discount schedule needs at least one rule'; end if;
      update public.commercial_discount_schedules set status = 'active', updated_at = now() where id = v_schedule.id returning * into v_schedule;
    elsif p_action = 'retire' then
      update public.commercial_discount_schedules set status = 'retired', updated_at = now() where id = v_schedule.id returning * into v_schedule;
    else
      raise exception 'Unsupported discount schedule action';
    end if;
  end if;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
  values(v_provider,v_actor,'commercial_discount_schedule_' || p_action,'commercial_discount_schedules',v_schedule.id,jsonb_build_object('status',v_schedule.status,'version',v_schedule.version,'client_request_id',p_client_request_id));
  return v_schedule;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."manage_commercial_discount_schedule"(p_client_request_id uuid, p_action text, p_schedule_id uuid, p_name text, p_effective_from date, p_effective_to date, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_commercial_discount_schedule"(p_client_request_id uuid, p_action text, p_schedule_id uuid, p_name text, p_effective_from date, p_effective_to date, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."manage_commercial_discount_schedule"(p_client_request_id uuid, p_action text, p_schedule_id uuid, p_name text, p_effective_from date, p_effective_to date, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."manage_commercial_discount_schedule"(p_client_request_id uuid, p_action text, p_schedule_id uuid, p_name text, p_effective_from date, p_effective_to date, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."manage_commercial_discount_schedule_rule"(p_schedule_id uuid, p_module_key text DEFAULT NULL::text, p_client_organization_id uuid DEFAULT NULL::uuid, p_site_id uuid DEFAULT NULL::uuid, p_zone_id uuid DEFAULT NULL::uuid, p_discount_kind text DEFAULT NULL::text, p_discount_value numeric DEFAULT NULL::numeric, p_minimum_subtotal numeric DEFAULT NULL::numeric, p_priority integer DEFAULT 0)
 RETURNS commercial_discount_schedule_rules
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_schedule public.commercial_discount_schedules%rowtype;
  v_rule public.commercial_discount_schedule_rules%rowtype;
begin
  select * into v_schedule from public.commercial_discount_schedules where id = p_schedule_id for update;
  if not found or not public.is_admin_for_org(v_schedule.provider_organization_id) then raise exception 'Discount schedule not found in your organization'; end if;
  if v_schedule.status <> 'draft' then raise exception 'Only draft discount schedules can be changed'; end if;
  if p_module_key is not null and not exists (select 1 from public.module_catalog where module_key = p_module_key and active) then raise exception 'Active module catalog entry required'; end if;
  if p_discount_kind not in ('percentage', 'fixed_amount') or p_discount_value is null or p_discount_value < 0 or (p_discount_kind = 'percentage' and p_discount_value > 100) then raise exception 'Discount kind and value are invalid'; end if;
  if p_minimum_subtotal is not null and p_minimum_subtotal < 0 then raise exception 'Minimum subtotal cannot be negative'; end if;
  if p_site_id is not null and p_zone_id is not null then raise exception 'A discount rule can target a Site or Zone, not both'; end if;
  if (p_site_id is not null or p_zone_id is not null) and p_client_organization_id is null then raise exception 'A Site or Zone discount requires its client organization'; end if;
  if p_site_id is not null and not exists (select 1 from public.client_sites where id = p_site_id and client_organization_id = p_client_organization_id) then raise exception 'Site does not belong to the selected client organization'; end if;
  if p_zone_id is not null and not exists (select 1 from public.location_zones zone join public.locations location on location.id = zone.location_id where zone.id = p_zone_id and location.organization_id = p_client_organization_id) then raise exception 'Zone does not belong to the selected client organization'; end if;

  insert into public.commercial_discount_schedule_rules(schedule_id,module_key,client_organization_id,site_id,zone_id,discount_kind,discount_value,minimum_subtotal,priority)
  values(p_schedule_id,p_module_key,p_client_organization_id,p_site_id,p_zone_id,p_discount_kind,p_discount_value,p_minimum_subtotal,coalesce(p_priority,0))
  returning * into v_rule;

  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
  values(v_schedule.provider_organization_id,v_actor,'commercial_discount_rule_created','commercial_discount_schedule_rules',v_rule.id,jsonb_build_object('schedule_id',v_schedule.id,'module_key',p_module_key,'client_organization_id',p_client_organization_id,'site_id',p_site_id,'zone_id',p_zone_id,'discount_kind',p_discount_kind,'discount_value',p_discount_value));
  return v_rule;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."manage_commercial_discount_schedule_rule"(p_schedule_id uuid, p_module_key text, p_client_organization_id uuid, p_site_id uuid, p_zone_id uuid, p_discount_kind text, p_discount_value numeric, p_minimum_subtotal numeric, p_priority integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_commercial_discount_schedule_rule"(p_schedule_id uuid, p_module_key text, p_client_organization_id uuid, p_site_id uuid, p_zone_id uuid, p_discount_kind text, p_discount_value numeric, p_minimum_subtotal numeric, p_priority integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."manage_commercial_discount_schedule_rule"(p_schedule_id uuid, p_module_key text, p_client_organization_id uuid, p_site_id uuid, p_zone_id uuid, p_discount_kind text, p_discount_value numeric, p_minimum_subtotal numeric, p_priority integer) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."manage_commercial_discount_schedule_rule"(p_schedule_id uuid, p_module_key text, p_client_organization_id uuid, p_site_id uuid, p_zone_id uuid, p_discount_kind text, p_discount_value numeric, p_minimum_subtotal numeric, p_priority integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."manage_crm_activation_handoff_task"(p_handoff_id uuid, p_task_id uuid, p_expected_version integer, p_complete boolean, p_note text)
 RETURNS crm_activation_handoffs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_provider uuid;v_handoff public.crm_activation_handoffs%rowtype;v_task public.crm_activation_handoff_tasks%rowtype;v_note text:=trim(coalesce(p_note,''));v_all_complete boolean;
begin
  select organization_id into v_provider from public.user_profiles where id=v_actor and deactivated_at is null;
  if v_provider is null or not public.is_admin_for_org(v_provider) then raise exception 'Active CRM administrator required';end if;
  select * into v_handoff from public.crm_activation_handoffs h where h.id=p_handoff_id and h.provider_organization_id=v_provider for update;
  if not found then raise exception 'Activation handoff not found';end if;
  if v_handoff.version<>p_expected_version then raise exception 'Activation handoff changed since it was opened';end if;
  select * into v_task from public.crm_activation_handoff_tasks t where t.id=p_task_id and t.handoff_id=v_handoff.id for update;
  if not found then raise exception 'Activation handoff task not found';end if;
  if char_length(v_note) not between 3 and 1000 then raise exception 'Completion note must be between 3 and 1000 characters';end if;
  if p_complete and v_task.task_key='first_roster_action' and not exists(select 1 from public.roster_slots rs join public.roster_work_units wu on wu.id=rs.work_unit_id join public.service_agreement_locations sal on sal.id=wu.service_agreement_location_id where sal.service_agreement_id=v_handoff.agreement_id and rs.status in('published','accepted','completed') and rs.scheduled_start>=v_handoff.activated_at) then raise exception 'Publish the first post-activation roster action before completing this task';end if;
  update public.crm_activation_handoff_tasks set status=case when p_complete then 'completed' else 'pending' end,completion_note=v_note,completed_at=case when p_complete then clock_timestamp() else null end,completed_by=case when p_complete then v_actor else null end where id=v_task.id;
  select not exists(select 1 from public.crm_activation_handoff_tasks t where t.handoff_id=v_handoff.id and t.status<>'completed') into v_all_complete;
  update public.crm_activation_handoffs set status=case when v_all_complete then 'completed' else 'open' end,version=version+1,completed_at=case when v_all_complete then clock_timestamp() else null end,completed_by=case when v_all_complete then v_actor else null end,updated_at=clock_timestamp() where id=v_handoff.id returning * into v_handoff;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_provider,v_actor,'crm_activation_handoff_task_'||case when p_complete then 'completed' else 'reopened' end,'crm_activation_handoff_tasks',v_task.id,jsonb_build_object('handoff_id',v_handoff.id,'task_key',v_task.task_key,'handoff_status',v_handoff.status,'handoff_version',v_handoff.version,'note',v_note));
  return v_handoff;
end;$function$;
REVOKE ALL ON FUNCTION "public"."manage_crm_activation_handoff_task"(p_handoff_id uuid, p_task_id uuid, p_expected_version integer, p_complete boolean, p_note text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_crm_activation_handoff_task"(p_handoff_id uuid, p_task_id uuid, p_expected_version integer, p_complete boolean, p_note text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."manage_crm_activation_handoff_task"(p_handoff_id uuid, p_task_id uuid, p_expected_version integer, p_complete boolean, p_note text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."manage_crm_activation_handoff_task"(p_handoff_id uuid, p_task_id uuid, p_expected_version integer, p_complete boolean, p_note text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."manage_crm_agreement_delivery_schedule"(p_client_request_id uuid, p_agreement_id uuid, p_action text, p_schedule_id uuid DEFAULT NULL::uuid, p_site_id uuid DEFAULT NULL::uuid, p_zone_id uuid DEFAULT NULL::uuid, p_module_key text DEFAULT NULL::text, p_active_days integer[] DEFAULT NULL::integer[], p_window_start time without time zone DEFAULT NULL::time without time zone, p_window_end time without time zone DEFAULT NULL::time without time zone, p_visits_per_shift integer DEFAULT 1, p_min_gap_between_visits_minutes integer DEFAULT 60, p_dwell_minutes integer DEFAULT 10, p_officer_instructions text DEFAULT NULL::text, p_operating_organization_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_agreement public.service_agreements%rowtype;
  v_schedule public.service_agreement_delivery_schedules%rowtype;
  v_config public.client_site_patrol_config%rowtype;
  v_operating uuid;
  v_days integer[];
  v_capability text;
  v_config_module text;
  v_toolset text;
  v_place_ok boolean;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_client_request_id IS NULL THEN RAISE EXCEPTION 'client_request_id is required'; END IF;
  IF p_action NOT IN ('create', 'update', 'remove') THEN RAISE EXCEPTION 'Unsupported schedule action'; END IF;
  SELECT * INTO v_agreement FROM public.service_agreements WHERE id = p_agreement_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Service agreement not found'; END IF;
  IF NOT public.is_admin_for_org(v_agreement.provider_organization_id) THEN RAISE EXCEPTION 'Provider administrator required'; END IF;
  IF v_agreement.agreement_type <> 'operational'
     OR (v_agreement.ends_on IS NOT NULL AND v_agreement.ends_on < current_date) THEN
    RAISE EXCEPTION 'Only live operational agreements can carry a delivery schedule';
  END IF;

  -- Idempotent replay of a create.
  IF p_action = 'create' AND EXISTS (SELECT 1 FROM public.audit_log a WHERE a.action = 'crm_delivery_schedule_create' AND a.metadata->>'client_request_id' = p_client_request_id::text) THEN
    SELECT s.* INTO v_schedule FROM public.service_agreement_delivery_schedules s
    WHERE s.id = (SELECT (a.metadata->>'schedule_id')::uuid FROM public.audit_log a WHERE a.action = 'crm_delivery_schedule_create' AND a.metadata->>'client_request_id' = p_client_request_id::text LIMIT 1);
    RETURN jsonb_build_object('schedule_id', v_schedule.id, 'replayed', true);
  END IF;

  IF p_action = 'remove' THEN
    SELECT * INTO v_schedule FROM public.service_agreement_delivery_schedules WHERE id = p_schedule_id AND service_agreement_id = v_agreement.id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Delivery schedule not found on this agreement'; END IF;
    UPDATE public.service_agreement_delivery_schedules SET active = false WHERE id = v_schedule.id;
    UPDATE public.client_site_patrol_config SET active = false, updated_at = clock_timestamp() WHERE delivery_schedule_id = v_schedule.id;
    INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
    VALUES (v_agreement.provider_organization_id, v_actor, 'crm_delivery_schedule_remove', 'service_agreement_delivery_schedules', v_schedule.id, jsonb_build_object('client_request_id', p_client_request_id, 'agreement_id', v_agreement.id));
    RETURN jsonb_build_object('schedule_id', v_schedule.id, 'removed', true);
  END IF;

  -- Validate the place, the module and the schedule shape.
  IF (p_site_id IS NULL) = (p_zone_id IS NULL) THEN RAISE EXCEPTION 'Choose one place: a site or an area'; END IF;
  IF p_site_id IS NOT NULL THEN
    SELECT EXISTS (SELECT 1 FROM public.client_sites s WHERE s.id = p_site_id AND s.client_organization_id = v_agreement.client_organization_id AND s.active) INTO v_place_ok;
  ELSE
    SELECT EXISTS (SELECT 1 FROM public.location_zones z JOIN public.locations l ON l.id = z.location_id WHERE z.id = p_zone_id AND z.is_active
                   AND (l.organization_id = v_agreement.client_organization_id OR z.organization_id = v_agreement.provider_organization_id)) INTO v_place_ok;
  END IF;
  IF NOT v_place_ok THEN RAISE EXCEPTION 'That place does not belong to this client'; END IF;
  IF p_module_key IS NULL OR NOT EXISTS (SELECT 1 FROM public.module_catalog m WHERE m.module_key = p_module_key AND m.active) THEN RAISE EXCEPTION 'Choose an active service (module)'; END IF;
  IF p_module_key = 'static_guarding' THEN RAISE EXCEPTION 'A guard on post is covered by the place and the module; it does not take a visit schedule'; END IF;
  v_days := (SELECT coalesce(array_agg(DISTINCT d ORDER BY d), '{}') FROM unnest(coalesce(p_active_days, '{1,2,3,4,5,6,7}'::integer[])) d WHERE d BETWEEN 1 AND 7);
  IF cardinality(v_days) = 0 THEN RAISE EXCEPTION 'Choose at least one day of the week (Monday = 1)'; END IF;
  IF (p_window_start IS NULL) <> (p_window_end IS NULL) THEN RAISE EXCEPTION 'Set both window times, or neither for any time of day'; END IF;
  IF p_visits_per_shift IS NULL OR p_visits_per_shift < 1 OR p_visits_per_shift > 24 THEN RAISE EXCEPTION 'Visits per shift must be between 1 and 24'; END IF;
  IF p_min_gap_between_visits_minutes IS NULL OR p_min_gap_between_visits_minutes < 0 OR p_min_gap_between_visits_minutes > 720 THEN RAISE EXCEPTION 'Minimum gap must be between 0 and 720 minutes'; END IF;
  IF p_dwell_minutes IS NULL OR p_dwell_minutes < 0 OR p_dwell_minutes > 480 THEN RAISE EXCEPTION 'Time on site must be between 0 and 480 minutes'; END IF;
  v_operating := coalesce(p_operating_organization_id, v_agreement.provider_organization_id);
  IF NOT (v_operating = v_agreement.provider_organization_id OR v_operating = ANY(public.get_descendant_organizations(v_agreement.provider_organization_id))) THEN
    RAISE EXCEPTION 'The operating branch must be the agreement holder or one of its branches';
  END IF;
  v_capability := CASE WHEN p_module_key IN ('dispatch', 'alarm_response') THEN 'alarm_response' WHEN p_module_key = 'noise_control' THEN 'noise_control' WHEN p_module_key = 'freedom_camping' THEN 'freedom_camping' ELSE 'patrol' END;
  -- The catalog module is what the agreement covers; the toolset key is what the officer does at the stop.
  v_toolset := CASE p_module_key WHEN 'patrol' THEN 'general_patrol' WHEN 'dispatch' THEN 'alarm_response' WHEN 'welfare' THEN 'welfare_check' ELSE p_module_key END;
  IF v_toolset NOT IN ('freedom_camping', 'parking_enforcement', 'noise_control', 'biosecurity', 'smoke_complaints', 'access_control', 'ems', 'alarm_response', 'welfare_check', 'general_patrol') THEN
    RAISE EXCEPTION 'This service is not delivered as visits to a place';
  END IF;
  v_config_module := CASE WHEN v_capability = 'patrol' THEN 'general_patrol' ELSE v_capability END;

  -- The module and the place are on the agreement (idempotent).
  INSERT INTO public.service_agreement_modules(service_agreement_id, module_key, enabled)
  VALUES (v_agreement.id, p_module_key, true)
  ON CONFLICT (service_agreement_id, module_key) DO UPDATE SET enabled = true;
  UPDATE public.service_agreements SET enabled_modules = coalesce((SELECT array_agg(sam.module_key ORDER BY sam.module_key) FROM public.service_agreement_modules sam WHERE sam.service_agreement_id = v_agreement.id AND sam.enabled), '{}') WHERE id = v_agreement.id;
  IF p_site_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.service_agreement_locations l WHERE l.service_agreement_id = v_agreement.id AND l.site_id = p_site_id AND l.status = 'active') THEN
    INSERT INTO public.service_agreement_locations(service_agreement_id, site_id, status, created_by) VALUES (v_agreement.id, p_site_id, 'active', v_actor);
  END IF;
  IF p_zone_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.service_agreement_locations l WHERE l.service_agreement_id = v_agreement.id AND l.zone_id = p_zone_id AND l.status = 'active') THEN
    INSERT INTO public.service_agreement_locations(service_agreement_id, zone_id, status, created_by) VALUES (v_agreement.id, p_zone_id, 'active', v_actor);
  END IF;

  IF p_action = 'create' THEN
    INSERT INTO public.service_agreement_delivery_schedules(service_agreement_id, site_id, zone_id, module_key, capability_key, work_model, active_days, active_months, visits_per_shift, min_gap_between_visits_minutes, window_start, window_end, dwell_minutes, preferred_stop_order, pricing_basis, officer_instructions, active)
    VALUES (v_agreement.id, p_site_id, p_zone_id, v_toolset, v_capability, CASE WHEN v_capability = 'alarm_response' THEN 'on_demand_callout' ELSE 'scheduled_patrol' END, v_days, '{}', p_visits_per_shift, p_min_gap_between_visits_minutes, p_window_start, p_window_end, p_dwell_minutes, 0, 'standard_rate_rule', nullif(trim(coalesce(p_officer_instructions, '')), ''), true)
    RETURNING * INTO v_schedule;
  ELSE
    SELECT * INTO v_schedule FROM public.service_agreement_delivery_schedules WHERE id = p_schedule_id AND service_agreement_id = v_agreement.id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Delivery schedule not found on this agreement'; END IF;
    UPDATE public.service_agreement_delivery_schedules
    SET site_id = p_site_id, zone_id = p_zone_id, module_key = v_toolset, capability_key = v_capability, active_days = v_days, visits_per_shift = p_visits_per_shift,
        min_gap_between_visits_minutes = p_min_gap_between_visits_minutes, window_start = p_window_start, window_end = p_window_end, dwell_minutes = p_dwell_minutes,
        officer_instructions = nullif(trim(coalesce(p_officer_instructions, '')), ''), active = true
    WHERE id = v_schedule.id RETURNING * INTO v_schedule;
  END IF;

  -- The patrol config the run builder and stop generator read (same shape the quote acceptance trigger writes).
  IF v_capability <> 'alarm_response' THEN
    SELECT * INTO v_config FROM public.client_site_patrol_config WHERE delivery_schedule_id = v_schedule.id FOR UPDATE;
    IF FOUND THEN
      UPDATE public.client_site_patrol_config
      SET organization_id = v_operating, site_id = p_site_id, zone_id = p_zone_id, module_key = v_config_module, active_days = v_days, visits_per_shift = p_visits_per_shift,
          min_gap_between_visits_minutes = p_min_gap_between_visits_minutes, time_window_type = 'fixed', window_start = p_window_start, window_end = p_window_end,
          dwell_minutes = p_dwell_minutes, officer_instructions = v_schedule.officer_instructions, active = true, updated_at = clock_timestamp()
      WHERE id = v_config.id;
    ELSE
      INSERT INTO public.client_site_patrol_config(organization_id, site_id, zone_id, module_key, active_days, visits_per_shift, min_gap_between_visits_minutes, time_window_type, window_start, window_end, active_months, dwell_minutes, sla_arrive_within_minutes, sla_depart_within_minutes, preferred_stop_order, officer_instructions, delivery_schedule_id)
      VALUES (v_operating, p_site_id, p_zone_id, v_config_module, v_days, p_visits_per_shift, p_min_gap_between_visits_minutes, 'fixed', p_window_start, p_window_end, '{}', p_dwell_minutes, 30, 45, 0, v_schedule.officer_instructions, v_schedule.id);
    END IF;
  END IF;

  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_agreement.provider_organization_id, v_actor, 'crm_delivery_schedule_' || p_action, 'service_agreement_delivery_schedules', v_schedule.id,
    jsonb_build_object('client_request_id', p_client_request_id, 'schedule_id', v_schedule.id, 'agreement_id', v_agreement.id, 'site_id', p_site_id, 'zone_id', p_zone_id, 'module_key', p_module_key,
      'active_days', v_days, 'window_start', p_window_start, 'window_end', p_window_end, 'visits_per_shift', p_visits_per_shift, 'operating_organization_id', v_operating));
  RETURN jsonb_build_object('schedule_id', v_schedule.id, 'agreement_id', v_agreement.id, 'module_key', p_module_key, 'toolset_key', v_toolset, 'capability_key', v_capability, 'operating_organization_id', v_operating, 'active_days', v_days);
END;
$function$;
COMMENT ON FUNCTION "public"."manage_crm_agreement_delivery_schedule"(p_client_request_id uuid, p_agreement_id uuid, p_action text, p_schedule_id uuid, p_site_id uuid, p_zone_id uuid, p_module_key text, p_active_days integer[], p_window_start time without time zone, p_window_end time without time zone, p_visits_per_shift integer, p_min_gap_between_visits_minutes integer, p_dwell_minutes integer, p_officer_instructions text, p_operating_organization_id uuid) IS 'Guided client setup: a contracted schedule for one place and one service on a live operational agreement — days (ISO 1–7, default every day), window (none = any time of day), visits per shift, minimum gap, time on site. Writes the delivery schedule and its patrol config (linked by delivery_schedule_id), enables the module and links the place on the agreement. Idempotent on client_request_id.';
REVOKE ALL ON FUNCTION "public"."manage_crm_agreement_delivery_schedule"(p_client_request_id uuid, p_agreement_id uuid, p_action text, p_schedule_id uuid, p_site_id uuid, p_zone_id uuid, p_module_key text, p_active_days integer[], p_window_start time without time zone, p_window_end time without time zone, p_visits_per_shift integer, p_min_gap_between_visits_minutes integer, p_dwell_minutes integer, p_officer_instructions text, p_operating_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_crm_agreement_delivery_schedule"(p_client_request_id uuid, p_agreement_id uuid, p_action text, p_schedule_id uuid, p_site_id uuid, p_zone_id uuid, p_module_key text, p_active_days integer[], p_window_start time without time zone, p_window_end time without time zone, p_visits_per_shift integer, p_min_gap_between_visits_minutes integer, p_dwell_minutes integer, p_officer_instructions text, p_operating_organization_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."manage_crm_agreement_delivery_schedule"(p_client_request_id uuid, p_agreement_id uuid, p_action text, p_schedule_id uuid, p_site_id uuid, p_zone_id uuid, p_module_key text, p_active_days integer[], p_window_start time without time zone, p_window_end time without time zone, p_visits_per_shift integer, p_min_gap_between_visits_minutes integer, p_dwell_minutes integer, p_officer_instructions text, p_operating_organization_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."manage_crm_agreement_delivery_schedule"(p_client_request_id uuid, p_agreement_id uuid, p_action text, p_schedule_id uuid, p_site_id uuid, p_zone_id uuid, p_module_key text, p_active_days integer[], p_window_start time without time zone, p_window_end time without time zone, p_visits_per_shift integer, p_min_gap_between_visits_minutes integer, p_dwell_minutes integer, p_officer_instructions text, p_operating_organization_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."manage_crm_agreement_finance"(p_agreement_id uuid, p_expected_invitation_status text, p_client_portal_finance_enabled boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_agreement public.service_agreements%rowtype;
BEGIN
  SELECT * INTO v_agreement FROM public.service_agreements WHERE id=p_agreement_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Service agreement not found'; END IF;
  IF v_actor IS NULL OR NOT public.is_admin_for_org(v_agreement.provider_organization_id) THEN RAISE EXCEPTION 'Provider administrator required'; END IF;
  IF v_agreement.agreement_type <> 'operational' THEN RAISE EXCEPTION 'Only operational agreements can be configured'; END IF;
  IF v_agreement.invitation_status IS DISTINCT FROM p_expected_invitation_status THEN RAISE EXCEPTION 'Service agreement changed since it was opened'; END IF;

  UPDATE public.service_agreements
  SET client_portal_finance_enabled = coalesce(p_client_portal_finance_enabled, false)
  WHERE id = v_agreement.id
  RETURNING * INTO v_agreement;

  INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
  VALUES(v_agreement.provider_organization_id,v_actor,'crm_agreement_finance_updated','service_agreements',v_agreement.id,jsonb_build_object('client_portal_finance_enabled',v_agreement.client_portal_finance_enabled));

  RETURN jsonb_build_object('agreement_id',v_agreement.id,'client_portal_finance_enabled',v_agreement.client_portal_finance_enabled);
END;
$function$;
REVOKE ALL ON FUNCTION "public"."manage_crm_agreement_finance"(p_agreement_id uuid, p_expected_invitation_status text, p_client_portal_finance_enabled boolean) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_crm_agreement_finance"(p_agreement_id uuid, p_expected_invitation_status text, p_client_portal_finance_enabled boolean) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."manage_crm_agreement_finance"(p_agreement_id uuid, p_expected_invitation_status text, p_client_portal_finance_enabled boolean) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."manage_crm_agreement_finance"(p_agreement_id uuid, p_expected_invitation_status text, p_client_portal_finance_enabled boolean) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."manage_crm_agreement_obligation"(p_client_request_id uuid, p_agreement_id uuid, p_action text, p_obligation_id uuid DEFAULT NULL::uuid, p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_obligation_code text DEFAULT NULL::text, p_obligation_type text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_sla_target_minutes integer DEFAULT NULL::integer, p_requires_proof boolean DEFAULT false, p_proof_artifact_type text DEFAULT NULL::text, p_escalation_minutes integer DEFAULT NULL::integer, p_escalation_contact text DEFAULT NULL::text, p_site_id uuid DEFAULT NULL::uuid, p_frequency_rule jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_agreement public.service_agreements%rowtype;
  v_obligation public.agreement_obligations%rowtype;
  v_receipt public.audit_log%rowtype;
  v_code text := upper(nullif(btrim(p_obligation_code), ''));
  v_previous jsonb;
BEGIN
  IF p_client_request_id IS NULL THEN
    RAISE EXCEPTION 'client_request_id is required';
  END IF;

  SELECT sa.*
  INTO v_agreement
  FROM public.service_agreements sa
  WHERE sa.id = p_agreement_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Service agreement not found';
  END IF;
  IF v_actor IS NULL OR NOT public.is_admin_for_org(v_agreement.provider_organization_id) THEN
    RAISE EXCEPTION 'Provider administrator required';
  END IF;
  IF v_agreement.agreement_type <> 'operational' THEN
    RAISE EXCEPTION 'Only operational agreements can be configured';
  END IF;
  IF p_action IS NULL OR p_action NOT IN ('save', 'deactivate') THEN
    RAISE EXCEPTION 'Unsupported obligation action';
  END IF;

  SELECT a.*
  INTO v_receipt
  FROM public.audit_log a
  WHERE a.organization_id = v_agreement.provider_organization_id
    AND a.target_table = 'agreement_obligations'
    AND a.action IN (
      'crm_agreement_obligation_save',
      'crm_agreement_obligation_deactivate'
    )
    AND a.metadata->>'client_request_id' = p_client_request_id::text;

  IF FOUND THEN
    IF v_receipt.metadata->>'agreement_id' <> p_agreement_id::text
       OR v_receipt.metadata->>'request_action' <> p_action THEN
      RAISE EXCEPTION 'client_request_id was already used for another obligation command';
    END IF;
    SELECT ao.*
    INTO v_obligation
    FROM public.agreement_obligations ao
    WHERE ao.id = v_receipt.target_id
      AND ao.service_agreement_id = v_agreement.id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Agreement obligation receipt no longer resolves';
    END IF;
    RETURN to_jsonb(v_obligation);
  END IF;

  IF p_obligation_id IS NOT NULL THEN
    SELECT ao.*
    INTO v_obligation
    FROM public.agreement_obligations ao
    WHERE ao.id = p_obligation_id
      AND ao.service_agreement_id = v_agreement.id
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Agreement obligation not found';
    END IF;
    IF p_expected_updated_at IS NULL
       OR v_obligation.updated_at IS DISTINCT FROM p_expected_updated_at THEN
      RAISE EXCEPTION 'Agreement obligation changed since it was opened';
    END IF;
    v_previous := jsonb_build_object(
      'obligation_code', v_obligation.obligation_code,
      'obligation_type', v_obligation.obligation_type,
      'site_id', v_obligation.site_id,
      'active', v_obligation.active
    );
  END IF;

  IF p_action = 'deactivate' THEN
    IF p_obligation_id IS NULL THEN
      RAISE EXCEPTION 'Agreement obligation required';
    END IF;
    UPDATE public.agreement_obligations
    SET active = false,
        updated_at = clock_timestamp()
    WHERE id = v_obligation.id
    RETURNING * INTO v_obligation;
  ELSE
    IF v_code IS NULL OR v_code !~ '^[A-Z0-9][A-Z0-9._-]{1,63}$' THEN
      RAISE EXCEPTION 'Obligation code must be 2-64 letters, numbers, dots, dashes, or underscores';
    END IF;
    IF nullif(btrim(p_description), '') IS NULL THEN
      RAISE EXCEPTION 'Obligation description required';
    END IF;
    IF p_obligation_type IS NULL
       OR p_obligation_type NOT IN (
         'response_time',
         'patrol_frequency',
         'report_delivery',
         'incident_escalation',
         'compliance_check',
         'custom'
       ) THEN
      RAISE EXCEPTION 'Valid obligation type required';
    END IF;
    IF p_sla_target_minutes IS NOT NULL AND p_sla_target_minutes < 1 THEN
      RAISE EXCEPTION 'SLA target must be positive';
    END IF;
    IF p_escalation_minutes IS NOT NULL AND p_escalation_minutes < 1 THEN
      RAISE EXCEPTION 'Escalation time must be positive';
    END IF;
    IF coalesce(p_requires_proof, false)
       AND (
         p_proof_artifact_type IS NULL
         OR p_proof_artifact_type NOT IN (
           'photo', 'gps_track', 'report', 'signature', 'timestamp', 'other'
         )
       ) THEN
      RAISE EXCEPTION 'Proof artifact type required';
    END IF;
    IF p_site_id IS NOT NULL AND NOT EXISTS (
      SELECT 1
      FROM public.service_agreement_locations sal
      WHERE sal.service_agreement_id = v_agreement.id
        AND sal.site_id = p_site_id
        AND sal.status = 'active'
    ) THEN
      RAISE EXCEPTION 'Obligation site must be in active agreement coverage';
    END IF;
    IF p_obligation_type = 'patrol_frequency' THEN
      IF p_frequency_rule IS NULL
         OR jsonb_typeof(p_frequency_rule) <> 'object'
         OR coalesce(p_frequency_rule->>'period', '') NOT IN (
           'shift', 'day', 'week', 'month'
         )
         OR coalesce(p_frequency_rule->>'minimum_count', '') !~ '^[1-9][0-9]*$' THEN
        RAISE EXCEPTION 'Patrol frequency requires a positive minimum count per shift, day, week, or month';
      END IF;
    ELSIF p_frequency_rule IS NOT NULL THEN
      RAISE EXCEPTION 'Frequency rule is only valid for patrol frequency obligations';
    END IF;
    IF EXISTS (
      SELECT 1
      FROM public.agreement_obligations ao
      WHERE ao.service_agreement_id = v_agreement.id
        AND ao.obligation_code = v_code
        AND ao.id IS DISTINCT FROM p_obligation_id
    ) THEN
      RAISE EXCEPTION 'Obligation code already exists for this agreement';
    END IF;

    IF p_obligation_id IS NULL THEN
      INSERT INTO public.agreement_obligations(
        service_agreement_id,
        obligation_code,
        obligation_type,
        description,
        sla_target_minutes,
        requires_proof,
        proof_artifact_type,
        escalation_minutes,
        escalation_contact,
        site_id,
        frequency_rule,
        active
      )
      VALUES (
        v_agreement.id,
        v_code,
        p_obligation_type,
        btrim(p_description),
        p_sla_target_minutes,
        coalesce(p_requires_proof, false),
        CASE WHEN coalesce(p_requires_proof, false)
          THEN p_proof_artifact_type ELSE NULL END,
        p_escalation_minutes,
        nullif(btrim(p_escalation_contact), ''),
        p_site_id,
        p_frequency_rule,
        true
      )
      RETURNING * INTO v_obligation;
    ELSE
      UPDATE public.agreement_obligations
      SET obligation_code = v_code,
          obligation_type = p_obligation_type,
          description = btrim(p_description),
          sla_target_minutes = p_sla_target_minutes,
          requires_proof = coalesce(p_requires_proof, false),
          proof_artifact_type = CASE WHEN coalesce(p_requires_proof, false)
            THEN p_proof_artifact_type ELSE NULL END,
          escalation_minutes = p_escalation_minutes,
          escalation_contact = nullif(btrim(p_escalation_contact), ''),
          site_id = p_site_id,
          frequency_rule = p_frequency_rule,
          active = true,
          updated_at = clock_timestamp()
      WHERE id = v_obligation.id
      RETURNING * INTO v_obligation;
    END IF;
  END IF;

  INSERT INTO public.audit_log(
    organization_id,
    actor_user_id,
    action,
    target_table,
    target_id,
    metadata
  )
  VALUES (
    v_agreement.provider_organization_id,
    v_actor,
    'crm_agreement_obligation_' || p_action,
    'agreement_obligations',
    v_obligation.id,
    jsonb_build_object(
      'agreement_id', v_agreement.id,
      'client_request_id', p_client_request_id,
      'request_action', p_action,
      'previous', v_previous,
      'result', jsonb_build_object(
        'obligation_code', v_obligation.obligation_code,
        'obligation_type', v_obligation.obligation_type,
        'site_id', v_obligation.site_id,
        'active', v_obligation.active
      )
    )
  );

  RETURN to_jsonb(v_obligation);
END;
$function$;
REVOKE ALL ON FUNCTION "public"."manage_crm_agreement_obligation"(p_client_request_id uuid, p_agreement_id uuid, p_action text, p_obligation_id uuid, p_expected_updated_at timestamp with time zone, p_obligation_code text, p_obligation_type text, p_description text, p_sla_target_minutes integer, p_requires_proof boolean, p_proof_artifact_type text, p_escalation_minutes integer, p_escalation_contact text, p_site_id uuid, p_frequency_rule jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_crm_agreement_obligation"(p_client_request_id uuid, p_agreement_id uuid, p_action text, p_obligation_id uuid, p_expected_updated_at timestamp with time zone, p_obligation_code text, p_obligation_type text, p_description text, p_sla_target_minutes integer, p_requires_proof boolean, p_proof_artifact_type text, p_escalation_minutes integer, p_escalation_contact text, p_site_id uuid, p_frequency_rule jsonb) TO "postgres";
