GRANT EXECUTE ON FUNCTION "public"."manage_shift_template"(p_client_request_id uuid, p_template_id uuid, p_action text, p_name text, p_shift_type text, p_start_time time without time zone, p_end_time time without time zone, p_recurrence_type text, p_active_days integer[], p_required_staff_count integer, p_notes text) TO "authenticated";
