CREATE OR REPLACE FUNCTION "public"."manage_smoke_assessment"(p_assessment_id uuid, p_expected_status text, p_action text, p_legal_basis text, p_follow_up_required boolean, p_notes text)
 RETURNS smoke_assessments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_item public.smoke_assessments%rowtype;v_notice text;
begin
  select * into v_item from public.smoke_assessments where id=p_assessment_id for update;
  if not found or not public.is_admin_for_org(v_item.organization_id) then raise exception 'Active Smoke Control administrator required';end if;
  if v_item.status<>p_expected_status then raise exception 'Smoke assessment changed from expected status % to %',p_expected_status,v_item.status;end if;
  if p_action not in('no_action','verbal_warning','abatement_notice','infringement_notice','prosecution_referral') then raise exception 'Unsupported Smoke Control action';end if;
  if nullif(trim(coalesce(p_notes,'')),'') is null then raise exception 'Supervisor decision notes are required';end if;
  if p_action in('abatement_notice','infringement_notice','prosecution_referral') and nullif(trim(coalesce(p_legal_basis,'')),'') is null then raise exception 'Legal basis is required for formal Smoke action';end if;
  v_notice:=case when p_action in('abatement_notice','infringement_notice') then coalesce(v_item.notice_number,'SMK-'||to_char(clock_timestamp(),'YYYYMMDD')||'-'||upper(substr(replace(v_item.id::text,'-',''),1,8))) else v_item.notice_number end;
  update public.smoke_assessments set action_taken=p_action,action=p_action,legal_basis=case when p_action='no_action' then null else nullif(trim(coalesce(p_legal_basis,'')),'') end,follow_up_required=coalesce(p_follow_up_required,false),notice_number=v_notice,status=case when coalesce(p_follow_up_required,false) then 'follow_up' else 'actioned' end,reviewed_by=v_actor,reviewed_at=clock_timestamp(),review_notes=trim(p_notes) where id=v_item.id returning * into v_item;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_item.organization_id,v_actor,'smoke_assessment_reviewed','smoke_assessments',v_item.id,jsonb_build_object('previous_status',p_expected_status,'status',v_item.status,'action',p_action,'notice_number',v_item.notice_number,'follow_up_required',v_item.follow_up_required));
  return v_item;
end;$function$;
REVOKE ALL ON FUNCTION "public"."manage_smoke_assessment"(p_assessment_id uuid, p_expected_status text, p_action text, p_legal_basis text, p_follow_up_required boolean, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_smoke_assessment"(p_assessment_id uuid, p_expected_status text, p_action text, p_legal_basis text, p_follow_up_required boolean, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."manage_smoke_assessment"(p_assessment_id uuid, p_expected_status text, p_action text, p_legal_basis text, p_follow_up_required boolean, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."manage_smoke_assessment"(p_assessment_id uuid, p_expected_status text, p_action text, p_legal_basis text, p_follow_up_required boolean, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."manage_smoke_assessment_review"(p_assessment_id uuid, p_expected_review_state text, p_action text, p_notes text)
 RETURNS TABLE(assessment_id uuid, review_state text, reviewed_by uuid, reviewed_at timestamp with time zone, follow_up_required boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
declare
  v_actor uuid := auth.uid();
  v_item public.smoke_assessments%rowtype;
  v_officer uuid;
  v_next text;
  v_notes text := nullif(trim(coalesce(p_notes, '')), '');
begin
  select s.* into v_item from public.smoke_assessments s where s.id = p_assessment_id for update;
  if not found then raise exception 'Smoke assessment not found'; end if;
  if not public.is_admin_for_org(v_item.organization_id) then raise exception 'Active Smoke Complaints administrator required'; end if;
  if v_item.review_state <> p_expected_review_state then
    raise exception 'Smoke review changed from expected state % to %', p_expected_review_state, v_item.review_state;
  end if;
  if v_notes is null then raise exception 'Review notes are required'; end if;

  if p_action = 'triage' and v_item.review_state in ('submitted', 'requires_supervisor_review') then
    v_next := 'triaged';
  elsif p_action = 'require_review' then
    v_next := 'requires_supervisor_review';
  elsif p_action = 'close' and v_item.review_state in ('submitted', 'requires_supervisor_review', 'triaged') then
    v_next := 'closed';
  else
    raise exception 'Unsupported smoke review transition from % using %', v_item.review_state, p_action;
  end if;

  update public.smoke_assessments
    set review_state = v_next,
        reviewed_by = v_actor,
        reviewed_at = clock_timestamp(),
        review_notes = v_notes,
        follow_up_required = case when v_next = 'requires_supervisor_review' then true when v_next = 'closed' then false else follow_up_required end
    where id = v_item.id
    returning * into v_item;

  v_officer := coalesce(v_item.officer_user_id, v_item.officer_id);

  insert into public.audit_log (
    organization_id, actor_user_id, action, target_table, target_id, metadata
  ) values (
    v_item.organization_id, v_actor, 'smoke_assessment_reviewed', 'smoke_assessments', v_item.id,
    jsonb_build_object('previous_review_state', p_expected_review_state, 'review_state', v_next, 'action', p_action, 'source_officer_id', v_officer, 'notes', v_notes)
  );

  if v_officer is not null then
    perform public.enqueue_notification(
      p_organization_id => v_item.organization_id,
      p_category => 'report_reviewed',
      p_title => 'Smoke assessment reviewed',
      p_body => v_notes,
      p_severity => case when v_next = 'requires_supervisor_review' then 'warning' else 'info' end,
      p_recipient_user_id => v_officer,
      p_link_page => 'smoke-review',
      p_link_payload => jsonb_build_object('assessment_id', v_item.id),
      p_dedup_key => 'smoke_review:' || v_item.id::text || ':' || v_item.review_state
    );
  end if;

  return query select v_item.id, v_item.review_state, v_item.reviewed_by, v_item.reviewed_at, v_item.follow_up_required;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."manage_smoke_assessment_review"(p_assessment_id uuid, p_expected_review_state text, p_action text, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_smoke_assessment_review"(p_assessment_id uuid, p_expected_review_state text, p_action text, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."manage_smoke_assessment_review"(p_assessment_id uuid, p_expected_review_state text, p_action text, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."manage_smoke_assessment_review"(p_assessment_id uuid, p_expected_review_state text, p_action text, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."manage_staff_availability"(p_client_request_id uuid, p_staff_id uuid, p_action text, p_availability_id uuid DEFAULT NULL::uuid, p_day_of_week integer DEFAULT NULL::integer, p_specific_date date DEFAULT NULL::date, p_available_from time without time zone DEFAULT NULL::time without time zone, p_available_to time without time zone DEFAULT NULL::time without time zone, p_all_day boolean DEFAULT false, p_type text DEFAULT 'unavailable'::text, p_notes text DEFAULT NULL::text)
 RETURNS staff_availability
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_staff public.staff_profiles%rowtype;
  v_avail public.staff_availability%rowtype;
  v_receipt public.audit_log%rowtype;
  v_notes text := nullif(trim(coalesce(p_notes, '')), '');
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Active user required';
  END IF;
  IF p_client_request_id IS NULL THEN
    RAISE EXCEPTION 'client_request_id is required';
  END IF;
  IF p_action NOT IN ('create', 'delete') THEN
    RAISE EXCEPTION 'Unsupported manage_staff_availability action %', p_action;
  END IF;

  SELECT sp.*
    INTO v_staff
    FROM public.staff_profiles sp
   WHERE sp.id = p_staff_id OR sp.user_id = p_staff_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Staff profile not found';
  END IF;
  IF NOT public.is_admin_for_org(v_staff.organization_id)
     AND v_staff.user_id IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'Not authorised to manage availability for this staff member';
  END IF;

  SELECT al.*
    INTO v_receipt
    FROM public.audit_log al
   WHERE al.organization_id = v_staff.organization_id
     AND al.action IN ('staff_availability_created', 'staff_availability_deleted')
     AND al.target_table = 'staff_availability'
     AND al.metadata ->> 'client_request_id' = p_client_request_id::text;
  IF FOUND THEN
    IF v_receipt.metadata ->> 'staff_id' IS DISTINCT FROM v_staff.id::text
       OR v_receipt.metadata ->> 'requested_action' IS DISTINCT FROM p_action THEN
      RAISE EXCEPTION 'client_request_id has already been used for a different availability action';
    END IF;
    v_avail := jsonb_populate_record(
      NULL::public.staff_availability,
      v_receipt.metadata -> 'record'
    );
    RETURN v_avail;
  END IF;

  IF p_action = 'create' THEN
    IF (p_day_of_week IS NULL) = (p_specific_date IS NULL) THEN
      RAISE EXCEPTION 'Choose either a recurring weekday or one specific date';
    END IF;
    IF p_day_of_week IS NOT NULL AND p_day_of_week NOT BETWEEN 1 AND 7 THEN
      RAISE EXCEPTION 'Recurring weekday must be from 1 to 7';
    END IF;
    IF p_type NOT IN ('available', 'preferred', 'unavailable', 'leave') THEN
      RAISE EXCEPTION 'Unsupported availability type';
    END IF;
    IF p_all_day AND (p_available_from IS NOT NULL OR p_available_to IS NOT NULL) THEN
      RAISE EXCEPTION 'All-day availability must not include start or end times';
    END IF;
    IF NOT p_all_day AND (
      p_available_from IS NULL
      OR p_available_to IS NULL
      OR p_available_from >= p_available_to
    ) THEN
      RAISE EXCEPTION 'Part-day availability requires a start time before its end time';
    END IF;
    IF p_type IN ('unavailable', 'leave') AND v_notes IS NULL THEN
      RAISE EXCEPTION 'A reason is required when staff cannot work';
    END IF;

    INSERT INTO public.staff_availability (
      staff_id,
      organization_id,
      day_of_week,
      specific_date,
      available_from,
      available_to,
      all_day,
      availability_type,
      notes
    )
    VALUES (
      v_staff.id,
      v_staff.organization_id,
      p_day_of_week,
      p_specific_date,
      CASE WHEN p_all_day THEN NULL ELSE p_available_from END,
      CASE WHEN p_all_day THEN NULL ELSE p_available_to END,
      p_all_day,
      p_type,
      v_notes
    )
    RETURNING * INTO v_avail;

    INSERT INTO public.audit_log (
      organization_id,
      actor_user_id,
      action,
      target_table,
      target_id,
      metadata
    )
    VALUES (
      v_staff.organization_id,
      v_actor,
      'staff_availability_created',
      'staff_availability',
      v_avail.id,
      jsonb_build_object(
        'staff_id', v_staff.id,
        'requested_action', p_action,
        'client_request_id', p_client_request_id,
        'record', to_jsonb(v_avail)
      )
    );

    RETURN v_avail;
  END IF;

  IF p_availability_id IS NULL THEN
    RAISE EXCEPTION 'Availability record is required for deletion';
  END IF;
  IF v_notes IS NULL THEN
    RAISE EXCEPTION 'A removal reason is required';
  END IF;

  SELECT sa.*
    INTO v_avail
    FROM public.staff_availability sa
   WHERE sa.id = p_availability_id
     AND sa.organization_id = v_staff.organization_id
     AND sa.staff_id = v_staff.id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Availability record not found for this staff member';
  END IF;

  DELETE FROM public.staff_availability
   WHERE id = v_avail.id;

  INSERT INTO public.audit_log (
    organization_id,
    actor_user_id,
    action,
    target_table,
    target_id,
    metadata
  )
  VALUES (
    v_staff.organization_id,
    v_actor,
    'staff_availability_deleted',
    'staff_availability',
    v_avail.id,
    jsonb_build_object(
      'staff_id', v_staff.id,
      'requested_action', p_action,
      'client_request_id', p_client_request_id,
      'reason', v_notes,
      'record', to_jsonb(v_avail)
    )
  );

  RETURN v_avail;
END;
$function$;
COMMENT ON FUNCTION "public"."manage_staff_availability"(p_client_request_id uuid, p_staff_id uuid, p_action text, p_availability_id uuid, p_day_of_week integer, p_specific_date date, p_available_from time without time zone, p_available_to time without time zone, p_all_day boolean, p_type text, p_notes text) IS 'Replay-safe staff availability create/delete authority. Binds deletion to the selected staff member, validates schedule shape, and records an immutable audit receipt.';
REVOKE ALL ON FUNCTION "public"."manage_staff_availability"(p_client_request_id uuid, p_staff_id uuid, p_action text, p_availability_id uuid, p_day_of_week integer, p_specific_date date, p_available_from time without time zone, p_available_to time without time zone, p_all_day boolean, p_type text, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_staff_availability"(p_client_request_id uuid, p_staff_id uuid, p_action text, p_availability_id uuid, p_day_of_week integer, p_specific_date date, p_available_from time without time zone, p_available_to time without time zone, p_all_day boolean, p_type text, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."manage_staff_availability"(p_client_request_id uuid, p_staff_id uuid, p_action text, p_availability_id uuid, p_day_of_week integer, p_specific_date date, p_available_from time without time zone, p_available_to time without time zone, p_all_day boolean, p_type text, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."manage_staff_availability"(p_client_request_id uuid, p_staff_id uuid, p_action text, p_availability_id uuid, p_day_of_week integer, p_specific_date date, p_available_from time without time zone, p_available_to time without time zone, p_all_day boolean, p_type text, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."manage_staff_branch_authorisation"(p_action text, p_user_id uuid, p_branch_organization_id uuid, p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_role_at_branch text DEFAULT 'officer'::text, p_module_access text[] DEFAULT '{}'::text[], p_can_be_rostered boolean DEFAULT true, p_starts_on date DEFAULT NULL::date, p_ends_on date DEFAULT NULL::date, p_reason text DEFAULT NULL::text)
 RETURNS staff_branch_authorisations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_target public.user_profiles%rowtype;
  v_branch public.organizations%rowtype;
  v_authorisation public.staff_branch_authorisations%rowtype;
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
  v_previous jsonb;
begin
  if v_actor is null then raise exception 'Authenticated user required'; end if;
  if v_actor = p_user_id then raise exception 'You cannot change your own branch access'; end if;
  if p_action not in ('grant', 'update', 'suspend', 'end') then raise exception 'Unsupported branch authorization action'; end if;
  if v_reason is null then raise exception 'A change reason is required'; end if;
  select * into v_target from public.user_profiles where id = p_user_id and deactivated_at is null;
  if not found then raise exception 'Active target user not found'; end if;
  select * into v_branch from public.organizations where id = p_branch_organization_id and organization_type = 'branch' and active;
  if not found then raise exception 'Active delivery branch not found'; end if;
  if not public.staff_branch_authorisation_manager_can_manage(v_actor, v_branch.id, v_target.id) then raise exception 'Not authorised to manage staff access for this branch'; end if;
  if p_action in ('grant', 'update') and p_role_at_branch not in ('officer', 'supervisor', 'branch_manager') then raise exception 'Unsupported branch role'; end if;
  if p_starts_on is not null and p_ends_on is not null and p_ends_on < p_starts_on then raise exception 'Branch authorization end date cannot precede its start date'; end if;
  select * into v_authorisation from public.staff_branch_authorisations where user_id = p_user_id and branch_org_id = v_branch.id for update;
  if found and p_expected_updated_at is not null and v_authorisation.updated_at <> p_expected_updated_at then raise exception 'Branch authorization changed since it was opened'; end if;
  v_previous := case when found then jsonb_build_object('role_at_branch', v_authorisation.role_at_branch, 'module_access', v_authorisation.module_access, 'can_be_rostered', v_authorisation.can_be_rostered, 'status', v_authorisation.status, 'starts_on', v_authorisation.starts_on, 'ends_on', v_authorisation.ends_on) else null end;
  if p_action = 'grant' then
    if found and v_authorisation.status = 'active' then raise exception 'An active authorization already exists for this branch'; end if;
    if found then
      update public.staff_branch_authorisations set role_at_branch = p_role_at_branch, module_access = coalesce(p_module_access, '{}'::text[]), can_be_rostered = p_can_be_rostered, status = 'active', starts_on = p_starts_on, ends_on = p_ends_on, authorised_by = v_actor where id = v_authorisation.id returning * into v_authorisation;
    else
      insert into public.staff_branch_authorisations(user_id, branch_org_id, role_at_branch, module_access, can_be_rostered, status, authorised_by, starts_on, ends_on) values(p_user_id, v_branch.id, p_role_at_branch, coalesce(p_module_access, '{}'::text[]), p_can_be_rostered, 'active', v_actor, p_starts_on, p_ends_on) returning * into v_authorisation;
    end if;
  elsif p_action = 'update' then
    if not found then raise exception 'Branch authorization not found'; end if;
    update public.staff_branch_authorisations set role_at_branch = p_role_at_branch, module_access = coalesce(p_module_access, '{}'::text[]), can_be_rostered = p_can_be_rostered, starts_on = p_starts_on, ends_on = p_ends_on, authorised_by = v_actor where id = v_authorisation.id returning * into v_authorisation;
  elsif p_action = 'suspend' then
    if not found or v_authorisation.status <> 'active' then raise exception 'Active branch authorization not found'; end if;
    update public.staff_branch_authorisations set status = 'suspended', can_be_rostered = false, authorised_by = v_actor where id = v_authorisation.id returning * into v_authorisation;
  else
    if not found or v_authorisation.status = 'ended' then raise exception 'Current branch authorization not found'; end if;
    update public.staff_branch_authorisations set status = 'ended', can_be_rostered = false, ends_on = coalesce(p_ends_on, current_date), authorised_by = v_actor where id = v_authorisation.id returning * into v_authorisation;
  end if;
  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values(v_branch.id, v_actor, 'staff_branch_authorisation_' || p_action, 'staff_branch_authorisations', v_authorisation.id,
    jsonb_build_object('target_user_id', p_user_id, 'employer_organization_id', v_target.employer_organization_id, 'branch_organization_id', v_branch.id, 'reason', v_reason, 'previous', v_previous, 'current', jsonb_build_object('role_at_branch', v_authorisation.role_at_branch, 'module_access', v_authorisation.module_access, 'can_be_rostered', v_authorisation.can_be_rostered, 'status', v_authorisation.status, 'starts_on', v_authorisation.starts_on, 'ends_on', v_authorisation.ends_on)));
  return v_authorisation;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."manage_staff_branch_authorisation"(p_action text, p_user_id uuid, p_branch_organization_id uuid, p_expected_updated_at timestamp with time zone, p_role_at_branch text, p_module_access text[], p_can_be_rostered boolean, p_starts_on date, p_ends_on date, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_staff_branch_authorisation"(p_action text, p_user_id uuid, p_branch_organization_id uuid, p_expected_updated_at timestamp with time zone, p_role_at_branch text, p_module_access text[], p_can_be_rostered boolean, p_starts_on date, p_ends_on date, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."manage_staff_branch_authorisation"(p_action text, p_user_id uuid, p_branch_organization_id uuid, p_expected_updated_at timestamp with time zone, p_role_at_branch text, p_module_access text[], p_can_be_rostered boolean, p_starts_on date, p_ends_on date, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."manage_staff_branch_authorisation"(p_action text, p_user_id uuid, p_branch_organization_id uuid, p_expected_updated_at timestamp with time zone, p_role_at_branch text, p_module_access text[], p_can_be_rostered boolean, p_starts_on date, p_ends_on date, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."manage_staff_onboarding"(p_ledger_id uuid, p_expected_version integer, p_action text, p_stage text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_assigned_to uuid DEFAULT NULL::uuid, p_target_start date DEFAULT NULL::date)
 RETURNS staff_onboarding_ledgers
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid(); v_ledger public.staff_onboarding_ledgers%rowtype; v_next text; v_next_status text; v_previous_stage text; v_previous_status text; v_note text:=nullif(trim(coalesce(p_note,'')),''); v_readiness record;
  v_order text[] := array['identity','employment','evidence','supervision','induction','review','ready'];
begin
  select l.* into v_ledger from public.staff_onboarding_ledgers l where l.id=p_ledger_id for update;
  if not found then raise exception 'Staff onboarding ledger not found'; end if;
  if not public.is_admin_for_org(v_ledger.organization_id) then raise exception 'Not authorised to manage staff onboarding'; end if;
  if v_ledger.version<>p_expected_version then raise exception 'Staff onboarding changed since it was opened'; end if;
  if v_note is null then raise exception 'A stage note is required'; end if;

  v_next:=coalesce(p_stage,v_ledger.current_stage);
  if p_action not in ('advance','return','assign','block','withdraw') then raise exception 'Unsupported onboarding action'; end if;
  if p_action in ('advance','return') then
    if array_position(v_order,v_next) is null then raise exception 'Unsupported onboarding stage'; end if;
    if p_action='advance' and array_position(v_order,v_next)>array_position(v_order,v_ledger.current_stage)+1 then raise exception 'Stages must advance one step at a time'; end if;
  end if;
  if p_action='advance' and v_next in ('employment','evidence','supervision','induction','review','ready') then
    select * into v_readiness from public.get_staff_onboarding_readiness(v_ledger.organization_id) r where r.ledger_id=v_ledger.id;
    if v_next='employment' and v_readiness.identity_status<>'complete' then raise exception 'Identity must be complete before employment'; end if;
    if v_next='evidence' and v_readiness.employment_status<>'complete' then raise exception 'Employment details must be complete before evidence'; end if;
    if v_next='supervision' and v_readiness.evidence_status<>'complete' then raise exception 'Credential, document, and skill evidence must be complete before supervision'; end if;
    if v_next='induction' and v_readiness.supervision_status<>'complete' then raise exception 'A line manager must be assigned before induction'; end if;
    if v_next='review' and v_readiness.induction_status<>'complete' then raise exception 'Induction must be complete before review'; end if;
    if v_next='ready' and (v_readiness.blockers is not null and array_length(v_readiness.blockers,1)>0) then raise exception 'Staff onboarding blockers remain: %', array_to_string(v_readiness.blockers,'; '); end if;
  end if;
  v_next_status:=case when p_action='block' then 'blocked' when p_action='withdraw' then 'withdrawn' when v_next='ready' then 'ready' else 'in_progress' end;

  v_previous_stage:=v_ledger.current_stage; v_previous_status:=v_ledger.status;
  update public.staff_onboarding_ledgers set current_stage=v_next, status=v_next_status, stage_note=v_note, assigned_to=coalesce(p_assigned_to,assigned_to), target_start=coalesce(p_target_start,target_start), version=version+1 where id=v_ledger.id returning * into v_ledger;
  insert into public.staff_onboarding_events(ledger_id,organization_id,from_stage,to_stage,from_status,to_status,note,actor_user_id,version)
  values(v_ledger.id,v_ledger.organization_id,v_previous_stage,v_next,v_previous_status,v_next_status,v_note,v_actor,v_ledger.version);
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
  values(v_ledger.organization_id,v_actor,'staff_onboarding_stage_changed','staff_onboarding_ledgers',v_ledger.id,jsonb_build_object('stage',v_next,'status',v_next_status,'note',v_note,'version',v_ledger.version));
  return v_ledger;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."manage_staff_onboarding"(p_ledger_id uuid, p_expected_version integer, p_action text, p_stage text, p_note text, p_assigned_to uuid, p_target_start date) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_staff_onboarding"(p_ledger_id uuid, p_expected_version integer, p_action text, p_stage text, p_note text, p_assigned_to uuid, p_target_start date) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."manage_staff_onboarding"(p_ledger_id uuid, p_expected_version integer, p_action text, p_stage text, p_note text, p_assigned_to uuid, p_target_start date) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."manage_staff_onboarding"(p_ledger_id uuid, p_expected_version integer, p_action text, p_stage text, p_note text, p_assigned_to uuid, p_target_start date) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."manage_staff_onboarding_evidence"(p_client_request_id uuid, p_staff_id uuid, p_action text, p_skill_name text DEFAULT NULL::text, p_skill_category text DEFAULT NULL::text, p_proficiency_level text DEFAULT NULL::text, p_reports_to_user_id uuid DEFAULT NULL::uuid, p_training_name text DEFAULT NULL::text, p_document_type text DEFAULT NULL::text, p_file_name text DEFAULT NULL::text, p_storage_path text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_staff public.staff_profiles%rowtype;
  v_user_id uuid;
  v_id uuid;
  v_note text := nullif(trim(coalesce(p_notes, '')), '');
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_client_request_id IS NULL THEN RAISE EXCEPTION 'client_request_id is required'; END IF;
  SELECT sp.* INTO v_staff FROM public.staff_profiles sp WHERE sp.id = p_staff_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Staff profile not found'; END IF;
  IF NOT public.is_admin_for_org(v_staff.organization_id) THEN RAISE EXCEPTION 'Active HR administrator required'; END IF;
  v_user_id := coalesce(v_staff.user_id, v_staff.id);

  IF p_action = 'add_skill' THEN
    IF nullif(trim(coalesce(p_skill_name, '')), '') IS NULL THEN RAISE EXCEPTION 'Skill name is required'; END IF;
    IF p_skill_category NOT IN ('enforcement','technical','medical','language','driving','equipment','other') THEN RAISE EXCEPTION 'Unsupported skill category'; END IF;
    IF p_proficiency_level NOT IN ('basic','competent','proficient','expert') THEN RAISE EXCEPTION 'Unsupported proficiency level'; END IF;
    INSERT INTO public.staff_skills(staff_id, organization_id, skill_name, skill_category, proficiency_level, notes)
    VALUES(v_staff.id, v_staff.organization_id, trim(p_skill_name), p_skill_category, p_proficiency_level, v_note)
    RETURNING id INTO v_id;
  ELSIF p_action = 'assign_line_manager' THEN
    IF p_reports_to_user_id IS NULL OR p_reports_to_user_id = v_user_id THEN RAISE EXCEPTION 'A different line manager is required'; END IF;
    IF NOT EXISTS(SELECT 1 FROM public.user_profiles u WHERE u.id = p_reports_to_user_id AND u.organization_id = v_staff.organization_id AND u.deactivated_at IS NULL) THEN RAISE EXCEPTION 'Line manager must be an active organization member'; END IF;
    UPDATE public.staff_reporting SET effective_to = current_date - 1
    WHERE user_id = v_user_id AND scope_org_id = v_staff.organization_id AND relationship_type = 'line_manager' AND effective_to IS NULL;
    INSERT INTO public.staff_reporting(user_id, reports_to_user_id, scope_org_id, relationship_type, set_by, notes)
    VALUES(v_user_id, p_reports_to_user_id, v_staff.organization_id, 'line_manager', v_actor, v_note)
    RETURNING id INTO v_id;
  ELSIF p_action = 'record_induction' THEN
    IF nullif(trim(coalesce(p_training_name, '')), '') IS NULL THEN RAISE EXCEPTION 'Induction name is required'; END IF;
    INSERT INTO public.staff_training_records(organization_id, staff_id, officer_id, training_name, training_type, completed_date, passed, notes, recorded_by)
    VALUES(v_staff.organization_id, v_staff.id, v_user_id, trim(p_training_name), 'induction', current_date, true, v_note, v_actor)
    RETURNING id INTO v_id;
  ELSIF p_action = 'record_document' THEN
    RAISE EXCEPTION 'Staff documents must be uploaded through record_staff_document_upload';
  ELSE
    RAISE EXCEPTION 'Unsupported staff onboarding evidence action';
  END IF;

  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES(v_staff.organization_id, v_actor, 'staff_onboarding_evidence_recorded', 'staff_profiles', v_staff.id,
    jsonb_build_object('action', p_action, 'evidence_id', v_id, 'client_request_id', p_client_request_id));
  RETURN jsonb_build_object('staff_id', v_staff.id, 'action', p_action, 'evidence_id', v_id);
END;
$function$;
REVOKE ALL ON FUNCTION "public"."manage_staff_onboarding_evidence"(p_client_request_id uuid, p_staff_id uuid, p_action text, p_skill_name text, p_skill_category text, p_proficiency_level text, p_reports_to_user_id uuid, p_training_name text, p_document_type text, p_file_name text, p_storage_path text, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_staff_onboarding_evidence"(p_client_request_id uuid, p_staff_id uuid, p_action text, p_skill_name text, p_skill_category text, p_proficiency_level text, p_reports_to_user_id uuid, p_training_name text, p_document_type text, p_file_name text, p_storage_path text, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."manage_staff_onboarding_evidence"(p_client_request_id uuid, p_staff_id uuid, p_action text, p_skill_name text, p_skill_category text, p_proficiency_level text, p_reports_to_user_id uuid, p_training_name text, p_document_type text, p_file_name text, p_storage_path text, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."manage_staff_onboarding_evidence"(p_client_request_id uuid, p_staff_id uuid, p_action text, p_skill_name text, p_skill_category text, p_proficiency_level text, p_reports_to_user_id uuid, p_training_name text, p_document_type text, p_file_name text, p_storage_path text, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."manage_user_identity_access"(p_user_id uuid, p_expected_updated_at timestamp with time zone, p_action text, p_display_name text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_role text DEFAULT NULL::text, p_preset_id uuid DEFAULT NULL::uuid, p_assignment_id uuid DEFAULT NULL::uuid, p_grant_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor public.user_profiles%rowtype;v_target public.user_profiles%rowtype;v_preset public.access_presets%rowtype;v_assignment public.preset_assignments%rowtype;v_grant public.staff_area_grants%rowtype;v_reason text:=nullif(trim(coalesce(p_reason,'')),'');v_old_identity jsonb;
begin
  select p.* into v_actor from public.user_profiles p where p.id=auth.uid() and p.deactivated_at is null;
  if not found or v_actor.role not in('grand_master','master','admin', 'admin_officer') then raise exception 'Active identity administrator required';end if;
  select p.* into v_target from public.user_profiles p where p.id=p_user_id for update;if not found then raise exception 'User profile not found';end if;
  if v_actor.role<>'grand_master' and v_target.organization_id<>v_actor.organization_id then raise exception 'User is outside your organization';end if;
  if public.identity_role_level(v_target.role)>public.identity_role_level(v_actor.role) then raise exception 'Cannot manage a user above your authority';end if;
  if p_expected_updated_at is not null and v_target.updated_at<>p_expected_updated_at then raise exception 'User identity changed since it was opened';end if;
  if v_reason is null then raise exception 'A change reason is required';end if;

  if p_action='update_identity' then
    if nullif(trim(coalesce(p_display_name,'')),'') is null then raise exception 'Display name is required';end if;
    if p_role not in('grand_master','master','admin','admin_officer','nzscv_monitor','officer','scan_operator','client_admin','client_officer','client_viewer') then raise exception 'Unsupported user role';end if;
    if public.identity_role_level(p_role)>public.identity_role_level(v_actor.role) then raise exception 'Cannot assign a role above your authority';end if;
    if v_target.id=v_actor.id and p_role<>v_target.role then raise exception 'You cannot change your own role';end if;
    v_old_identity:=jsonb_build_object('display_name',v_target.display_name,'phone',v_target.phone,'role',v_target.role);
    update public.user_profiles set display_name=trim(p_display_name),phone=nullif(trim(coalesce(p_phone,'')),''),role=p_role where id=v_target.id returning * into v_target;
    perform public.log_user_management_action(v_target.organization_id,v_target.id,'user_identity_updated',v_actor.id,v_old_identity,jsonb_build_object('display_name',v_target.display_name,'phone',v_target.phone,'role',v_target.role),jsonb_build_object('reason',v_reason));
  elsif p_action='set_preset' then
    if v_target.id=v_actor.id then raise exception 'You cannot change your own access preset';end if;
    if v_target.role not in('grand_master','master','admin','admin_officer') then raise exception 'Access presets apply to administration roles';end if;
    select p.* into v_preset from public.access_presets p where p.id=p_preset_id and (p.organization_id is null or p.organization_id=v_target.organization_id);if not found then raise exception 'Access preset is not available for this organization';end if;
    update public.preset_assignments set status='ended',updated_at=clock_timestamp() where user_id=v_target.id and scope_org_id=v_target.organization_id and status='active';
    insert into public.preset_assignments(user_id,preset_id,scope_org_id,status,assigned_by) values(v_target.id,v_preset.id,v_target.organization_id,'active',v_actor.id)
    on conflict(user_id,preset_id,scope_org_id) do update set status='active',assigned_by=excluded.assigned_by,updated_at=clock_timestamp() returning * into v_assignment;
    perform public.log_user_management_action(v_target.organization_id,v_target.id,'access_preset_assigned',v_actor.id,null,jsonb_build_object('preset_id',v_preset.id,'preset_key',v_preset.key),jsonb_build_object('reason',v_reason));
  elsif p_action='clear_preset' then
    if v_target.id=v_actor.id then raise exception 'You cannot change your own access preset';end if;
    update public.preset_assignments set status='ended',updated_at=clock_timestamp() where id=p_assignment_id and user_id=v_target.id and scope_org_id=v_target.organization_id and status='active' returning * into v_assignment;
    if not found then raise exception 'Active preset assignment not found';end if;
    perform public.log_user_management_action(v_target.organization_id,v_target.id,'access_preset_ended',v_actor.id,jsonb_build_object('assignment_id',v_assignment.id,'preset_id',v_assignment.preset_id),null,jsonb_build_object('reason',v_reason));
  elsif p_action='end_grant' then
    if v_target.id=v_actor.id then raise exception 'You cannot end your own direct access grant';end if;
    update public.staff_area_grants set status='ended',updated_at=clock_timestamp() where id=p_grant_id and user_id=v_target.id and scope_org_id=v_target.organization_id and status='active' returning * into v_grant;
    if not found then raise exception 'Active direct grant not found';end if;
    perform public.log_user_management_action(v_target.organization_id,v_target.id,'direct_access_grant_ended',v_actor.id,jsonb_build_object('grant_id',v_grant.id,'area',v_grant.area,'level',v_grant.level),null,jsonb_build_object('reason',v_reason));
  else raise exception 'Unsupported identity access action';end if;
  return jsonb_build_object('user_id',v_target.id,'display_name',v_target.display_name,'role',v_target.role,'updated_at',v_target.updated_at,'action',p_action,'assignment_id',v_assignment.id,'grant_id',v_grant.id);
end;$function$;
REVOKE ALL ON FUNCTION "public"."manage_user_identity_access"(p_user_id uuid, p_expected_updated_at timestamp with time zone, p_action text, p_display_name text, p_phone text, p_role text, p_preset_id uuid, p_assignment_id uuid, p_grant_id uuid, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_user_identity_access"(p_user_id uuid, p_expected_updated_at timestamp with time zone, p_action text, p_display_name text, p_phone text, p_role text, p_preset_id uuid, p_assignment_id uuid, p_grant_id uuid, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."manage_user_identity_access"(p_user_id uuid, p_expected_updated_at timestamp with time zone, p_action text, p_display_name text, p_phone text, p_role text, p_preset_id uuid, p_assignment_id uuid, p_grant_id uuid, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."manage_user_identity_access"(p_user_id uuid, p_expected_updated_at timestamp with time zone, p_action text, p_display_name text, p_phone text, p_role text, p_preset_id uuid, p_assignment_id uuid, p_grant_id uuid, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."manage_website_post"(p_post_id uuid, p_expected_version integer, p_request_id uuid, p_action text, p_title text, p_summary text, p_body text, p_photo_path text, p_photo_alt text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_provider uuid := public.website_post_admin_organization();
  v_post public.website_posts%ROWTYPE;
  v_payload jsonb;
  v_title text := btrim(coalesce(p_title, ''));
  v_summary text := btrim(coalesce(p_summary, ''));
  v_body text := btrim(coalesce(p_body, ''));
  v_photo text := nullif(btrim(coalesce(p_photo_path, '')), '');
  v_alt text := btrim(coalesce(p_photo_alt, ''));
BEGIN
  IF v_provider IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'website_posts_access_denied';
  END IF;
  IF p_post_id IS NULL OR p_request_id IS NULL OR p_expected_version IS NULL OR p_expected_version < 0
     OR p_action IS NULL OR p_action NOT IN ('save', 'publish', 'unpublish')
     OR char_length(v_title) NOT BETWEEN 1 AND 160 OR char_length(v_summary) > 300
     OR char_length(v_body) > 20000 OR char_length(v_alt) > 240 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'website_post_invalid:fields';
  END IF;
  v_payload := jsonb_build_object(
    'actor', auth.uid(), 'version', p_expected_version, 'action', p_action,
    'title', v_title, 'summary', v_summary, 'body', v_body, 'photo', v_photo, 'alt', v_alt
  );
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('website-post:' || p_post_id::text, 0));
  SELECT * INTO v_post FROM public.website_posts WHERE id = p_post_id FOR UPDATE;
  IF FOUND AND v_post.provider_organization_id <> v_provider THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'website_posts_access_denied';
  END IF;
  IF v_post.last_request_id = p_request_id THEN
    IF v_post.last_request_payload <> v_payload THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'website_post_invalid:request_reuse';
    END IF;
    RETURN to_jsonb(v_post) - 'last_request_payload' - 'last_request_id';
  END IF;
  IF coalesce(v_post.version, 0) <> p_expected_version THEN
    RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'website_post_conflict:reload_before_saving';
  END IF;
  IF p_action = 'unpublish' AND v_post.id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'website_post_invalid:not_published';
  END IF;
  IF v_photo IS NOT NULL AND (
    v_photo !~ ('^' || v_provider::text || '/' || p_post_id::text || '/[0-9a-f-]{36}\.jpg$')
    OR NOT EXISTS (
      SELECT 1 FROM storage.objects o
      WHERE o.bucket_id = 'website-post-images' AND o.name = v_photo
        AND o.metadata->>'mimetype' = 'image/jpeg'
        AND (o.metadata->>'size')::bigint BETWEEN 1 AND 5242880
    )
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'website_post_invalid:photo';
  END IF;
  IF p_action = 'publish' AND (v_body = '' OR (v_photo IS NOT NULL AND v_alt = '')) THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'website_post_invalid:publish_content';
  END IF;
  IF p_action = 'publish' AND replace(v_title || ' ' || v_summary || ' ' || v_body || ' ' || v_alt, '$10 million', ' ')
    ~* '[$][[:space:]]?[0-9]|\mper hour\M|\mhourly rate\M|\m(incl?|excl?)\.?[[:space:]]*GST\M|\mdiscount\M' THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'website_post_invalid:pricing_not_permitted';
  END IF;
  IF v_post.id IS NULL THEN
    INSERT INTO public.website_posts (
      id, provider_organization_id, slug, title, created_by, updated_by, last_request_id, last_request_payload
    ) VALUES (
      p_post_id, v_provider,
      left(coalesce(nullif(trim(both '-' FROM regexp_replace(lower(v_title), '[^a-z0-9]+', '-', 'g')), ''), 'update'), 90) || '-' || p_post_id::text,
      v_title, auth.uid(), auth.uid(), p_request_id, v_payload
    ) RETURNING * INTO v_post;
    v_post.version := 0;
  END IF;
  UPDATE public.website_posts SET
    title = v_title, summary = v_summary, body = v_body, photo_path = v_photo, photo_alt = v_alt,
    published_content = CASE
      WHEN p_action = 'unpublish' THEN NULL
      WHEN p_action = 'publish' THEN jsonb_build_object(
        'id', id, 'slug', slug, 'title', v_title,
        'summary', coalesce(nullif(v_summary, ''), left(v_body, 220)),
        'body', v_body, 'photo_path', v_photo, 'photo_alt', v_alt,
        'published_at', coalesce(published_content->'published_at', to_jsonb(now())),
        'updated_at', now(), 'version', v_post.version + 1
      )
      ELSE published_content END,
    version = v_post.version + 1, updated_by = auth.uid(), updated_at = now(),
    last_request_id = p_request_id, last_request_payload = v_payload
  WHERE id = p_post_id RETURNING * INTO v_post;
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_provider, auth.uid(), 'website_post_' || p_action, 'website_posts', p_post_id,
    jsonb_build_object('request_id', p_request_id, 'version', v_post.version, 'published', v_post.published_content IS NOT NULL));
  RETURN to_jsonb(v_post) - 'last_request_payload' - 'last_request_id';
END
$function$;
REVOKE ALL ON FUNCTION "public"."manage_website_post"(p_post_id uuid, p_expected_version integer, p_request_id uuid, p_action text, p_title text, p_summary text, p_body text, p_photo_path text, p_photo_alt text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_website_post"(p_post_id uuid, p_expected_version integer, p_request_id uuid, p_action text, p_title text, p_summary text, p_body text, p_photo_path text, p_photo_alt text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."manage_website_post"(p_post_id uuid, p_expected_version integer, p_request_id uuid, p_action text, p_title text, p_summary text, p_body text, p_photo_path text, p_photo_alt text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."manage_welfare_alert"(p_alert_id uuid, p_expected_status text, p_action text, p_notes text)
 RETURNS TABLE(alert_id uuid, alert_status text, acted_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_alert public.welfare_alerts%rowtype;v_notes text:=nullif(trim(coalesce(p_notes,'')),'');v_is_admin boolean;v_now timestamptz:=clock_timestamp();
begin
  if v_actor is null then raise exception 'Authentication required';end if;if v_notes is null then raise exception 'Welfare action notes are required';end if;
  select a.* into v_alert from public.welfare_alerts a where a.id=p_alert_id for update;if not found then raise exception 'Welfare alert not found';end if;
  v_is_admin:=public.is_admin_for_org(v_alert.organization_id);
  if p_action='acknowledge' then
    if not v_is_admin then raise exception 'Only an authorized supervisor can acknowledge this alert';end if;if v_alert.status<>p_expected_status or v_alert.status<>'pending' then raise exception 'Welfare alert changed from expected status % to %',p_expected_status,v_alert.status;end if;
    update public.welfare_alerts a set status='acknowledged',acknowledged_by=v_actor,acknowledged_at=v_now,acknowledgement_notes=v_notes where a.id=v_alert.id returning a.* into v_alert;
  elsif p_action='resolve' then
    if not v_is_admin and v_alert.officer_user_id<>v_actor then raise exception 'Not authorized to resolve this welfare alert';end if;if v_alert.status<>p_expected_status or v_alert.status not in('pending','acknowledged') then raise exception 'Welfare alert changed from expected status % to %',p_expected_status,v_alert.status;end if;
    update public.welfare_alerts a set status='resolved',resolved_by=v_actor,resolved_at=v_now,resolution_notes=v_notes where a.id=v_alert.id returning a.* into v_alert;
  else raise exception 'Unsupported welfare alert action';end if;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_alert.organization_id,v_actor,case when p_action='acknowledge' then 'welfare_alert_acknowledged' when v_is_admin then 'welfare_alert_resolved_by_supervisor' else 'welfare_alert_resolved_by_officer' end,'welfare_alerts',v_alert.id,jsonb_build_object('officer_user_id',v_alert.officer_user_id,'alert_type',v_alert.alert_type,'previous_status',p_expected_status,'status',v_alert.status,'notes',v_notes));
  perform public.enqueue_notification(p_organization_id=>v_alert.organization_id,p_category=>'welfare',p_title=>case when v_alert.status='acknowledged' then 'Welfare response acknowledged' else 'Welfare alert resolved' end,p_body=>v_notes,p_severity=>case when v_alert.status='resolved' then 'info' else 'warning' end,p_recipient_user_id=>v_alert.officer_user_id,p_link_page=>'welfare-outcome',p_link_payload=>jsonb_build_object('welfare_alert_id',v_alert.id,'status',v_alert.status),p_dedup_key=>'welfare_alert_outcome:'||v_alert.id::text||':'||v_alert.status);
  return query select v_alert.id,v_alert.status,v_now;
end;$function$;
REVOKE ALL ON FUNCTION "public"."manage_welfare_alert"(p_alert_id uuid, p_expected_status text, p_action text, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_welfare_alert"(p_alert_id uuid, p_expected_status text, p_action text, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."manage_welfare_alert"(p_alert_id uuid, p_expected_status text, p_action text, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."manage_welfare_alert"(p_alert_id uuid, p_expected_status text, p_action text, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."manage_workshop_bom_template"(p_client_request_id uuid, p_organization_id uuid, p_action text, p_template_id uuid DEFAULT NULL::uuid, p_name text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_kind text DEFAULT 'fabrication'::text, p_lines jsonb DEFAULT '[]'::jsonb)
 RETURNS workshop_bom_templates
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := public.workshop_actor_org(p_organization_id);
  v_tpl public.workshop_bom_templates%rowtype;
  v_line jsonb;
  v_pos integer := 0;
  v_item public.finance_item_catalog%rowtype;
begin
  if p_client_request_id is null then raise exception 'client_request_id is required'; end if;
  if p_action = 'create' then
    if nullif(trim(coalesce(p_name, '')), '') is null then raise exception 'Template name is required'; end if;
    if p_kind not in ('fabrication', 'maintenance') then raise exception 'Template kind must be fabrication or maintenance'; end if;
    insert into public.workshop_bom_templates (organization_id, name, description, kind, created_by)
    values (p_organization_id, trim(p_name), nullif(trim(coalesce(p_description, '')), ''), p_kind, v_actor)
    on conflict (organization_id, name) do update set description = excluded.description, kind = excluded.kind, active = true, updated_at = now()
    returning * into v_tpl;
  elsif p_action in ('update', 'archive') then
    select * into v_tpl from public.workshop_bom_templates t where t.id = p_template_id and t.organization_id = p_organization_id for update;
    if not found then raise exception 'Template not found'; end if;
    if p_action = 'archive' then
      update public.workshop_bom_templates set active = false, updated_at = now() where id = v_tpl.id returning * into v_tpl;
      insert into public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
      values (p_organization_id, v_actor, 'workshop_bom_template_archived', 'workshop_bom_templates', v_tpl.id, jsonb_build_object('name', v_tpl.name));
      return v_tpl;
    end if;
    update public.workshop_bom_templates
       set name = coalesce(nullif(trim(coalesce(p_name, '')), ''), name),
           description = coalesce(nullif(trim(coalesce(p_description, '')), ''), description),
           kind = coalesce(p_kind, kind), active = true, updated_at = now()
     where id = v_tpl.id returning * into v_tpl;
  else
    raise exception 'Action must be create, update or archive';
  end if;

  -- Lines are replaced wholesale: [{line_kind, item_id?, description?, quantity, unit_of_measure?}]
  delete from public.workshop_bom_template_lines where template_id = v_tpl.id;
  for v_line in select * from jsonb_array_elements(coalesce(p_lines, '[]'::jsonb)) loop
    v_pos := v_pos + 1;
    if coalesce(v_line->>'line_kind', '') not in ('material', 'labour', 'travel', 'equipment') then raise exception 'Line % has an unknown kind', v_pos; end if;
    if coalesce((v_line->>'quantity')::numeric, 0) <= 0 then raise exception 'Line % needs a quantity above zero', v_pos; end if;
    v_item := null;
    if nullif(v_line->>'item_id', '') is not null then
      select * into v_item from public.finance_item_catalog i where i.id = (v_line->>'item_id')::uuid and i.organization_id = p_organization_id and i.active;
      if not found then raise exception 'Line % refers to an item that is not in this organisation''s price book', v_pos; end if;
    end if;
    insert into public.workshop_bom_template_lines (template_id, organization_id, line_kind, item_id, description, quantity, unit_of_measure, position)
    values (v_tpl.id, p_organization_id, v_line->>'line_kind', v_item.id,
            coalesce(nullif(trim(coalesce(v_line->>'description', '')), ''), v_item.name, 'Line ' || v_pos),
            (v_line->>'quantity')::numeric, coalesce(nullif(v_line->>'unit_of_measure', ''), v_item.unit_of_measure), v_pos);
  end loop;

  insert into public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (p_organization_id, v_actor, 'workshop_bom_template_' || p_action || 'd', 'workshop_bom_templates', v_tpl.id,
          jsonb_build_object('name', v_tpl.name, 'kind', v_tpl.kind, 'lines', v_pos, 'client_request_id', p_client_request_id));
  return v_tpl;
end;
$function$;
COMMENT ON FUNCTION "public"."manage_workshop_bom_template"(p_client_request_id uuid, p_organization_id uuid, p_action text, p_template_id uuid, p_name text, p_description text, p_kind text, p_lines jsonb) IS 'Create, update (lines replaced wholesale) or archive a reusable bill-of-materials template. Workshop admin of the organisation; audited.';
REVOKE ALL ON FUNCTION "public"."manage_workshop_bom_template"(p_client_request_id uuid, p_organization_id uuid, p_action text, p_template_id uuid, p_name text, p_description text, p_kind text, p_lines jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_workshop_bom_template"(p_client_request_id uuid, p_organization_id uuid, p_action text, p_template_id uuid, p_name text, p_description text, p_kind text, p_lines jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."manage_workshop_bom_template"(p_client_request_id uuid, p_organization_id uuid, p_action text, p_template_id uuid, p_name text, p_description text, p_kind text, p_lines jsonb) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."manage_zone_active_schedule"(p_zone_id uuid, p_expected_version integer, p_days integer[] DEFAULT NULL::integer[], p_start time without time zone DEFAULT NULL::time without time zone, p_end time without time zone DEFAULT NULL::time without time zone, p_months integer[] DEFAULT NULL::integer[])
 RETURNS location_zones
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_zone public.location_zones%rowtype;
  v_days integer[];
  v_months integer[];
  v_schedule jsonb := '{}'::jsonb;
  v_before jsonb;
begin
  if v_actor is null then raise exception 'Authentication required'; end if;
  select * into v_zone from public.location_zones z where z.id = p_zone_id for update;
  if not found then raise exception 'Zone not found'; end if;
  if not (
    (v_zone.location_id is not null and public.crm_actor_can_manage_location(v_zone.location_id))
    or public.is_admin_for_org(v_zone.organization_id)
  ) then raise exception 'Active CRM administrator required for this zone'; end if;
  if v_zone.configuration_version <> p_expected_version then
    raise exception 'Zone configuration changed since it was opened; reload and try again';
  end if;

  -- Days: ISO 1..7, distinct, sorted. All seven (or none) is no restriction.
  select coalesce(array_agg(distinct d order by d), '{}') into v_days from unnest(coalesce(p_days, '{}')) d;
  if exists (select 1 from unnest(v_days) d where d < 1 or d > 7) then
    raise exception 'Days must be 1 (Monday) to 7 (Sunday)';
  end if;
  select coalesce(array_agg(distinct m order by m), '{}') into v_months from unnest(coalesce(p_months, '{}')) m;
  if exists (select 1 from unnest(v_months) m where m < 1 or m > 12) then
    raise exception 'Months must be 1 (January) to 12 (December)';
  end if;
  if (p_start is null) <> (p_end is null) then
    raise exception 'Give both a start and an end time, or neither for any time of day';
  end if;
  if p_start is not null and p_start = p_end then
    raise exception 'Start and end times must differ (leave both empty for any time of day)';
  end if;

  if array_length(v_days, 1) between 1 and 6 then v_schedule := v_schedule || jsonb_build_object('days', to_jsonb(v_days)); end if;
  if array_length(v_months, 1) between 1 and 11 then v_schedule := v_schedule || jsonb_build_object('months', to_jsonb(v_months)); end if;
  if p_start is not null then v_schedule := v_schedule || jsonb_build_object('start', to_char(p_start, 'HH24:MI'), 'end', to_char(p_end, 'HH24:MI')); end if;

  v_before := v_zone.active_schedule;
  update public.location_zones
     set active_schedule = case when v_schedule = '{}'::jsonb then null else v_schedule end,
         configuration_version = configuration_version + 1
   where id = v_zone.id
   returning * into v_zone;

  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (v_zone.organization_id, v_actor, 'zone_active_schedule_updated', 'location_zones', v_zone.id,
          jsonb_build_object('before', v_before, 'after', v_zone.active_schedule, 'configuration_version', v_zone.configuration_version));
  return v_zone;
end;
$function$;
COMMENT ON FUNCTION "public"."manage_zone_active_schedule"(p_zone_id uuid, p_expected_version integer, p_days integer[], p_start time without time zone, p_end time without time zone, p_months integer[]) IS 'Governed writer for location_zones.active_schedule: ISO days (1=Mon..7=Sun), optional start/end time (overnight allowed), optional months. All-days / no-times / all-months collapse to always active (null). Optimistic version check; audit row with before/after.';
REVOKE ALL ON FUNCTION "public"."manage_zone_active_schedule"(p_zone_id uuid, p_expected_version integer, p_days integer[], p_start time without time zone, p_end time without time zone, p_months integer[]) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_zone_active_schedule"(p_zone_id uuid, p_expected_version integer, p_days integer[], p_start time without time zone, p_end time without time zone, p_months integer[]) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."manage_zone_active_schedule"(p_zone_id uuid, p_expected_version integer, p_days integer[], p_start time without time zone, p_end time without time zone, p_months integer[]) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."manage_zone_active_schedule"(p_zone_id uuid, p_expected_version integer, p_days integer[], p_start time without time zone, p_end time without time zone, p_months integer[]) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."match_finance_bank_statement_line"(p_statement_line_id uuid, p_payment_receipt_id uuid)
 RETURNS finance_bank_statement_lines
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_line public.finance_bank_statement_lines%rowtype;
  v_payment public.payment_receipts%rowtype;
BEGIN
  SELECT organization_id INTO v_org
  FROM public.user_profiles
  WHERE id = v_actor AND deactivated_at IS NULL;

  IF v_org IS NULL OR NOT public.is_admin_for_org(v_org) THEN
    RAISE EXCEPTION 'Active finance administrator required';
  END IF;
  IF p_statement_line_id IS NULL OR p_payment_receipt_id IS NULL THEN
    RAISE EXCEPTION 'Statement line and payment receipt are required';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('finance-payment-match:' || p_payment_receipt_id::text, 0));

  SELECT * INTO v_line
  FROM public.finance_bank_statement_lines
  WHERE id = p_statement_line_id AND organization_id = v_org
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Bank statement line not found in organization';
  END IF;

  SELECT * INTO v_payment
  FROM public.payment_receipts
  WHERE id = p_payment_receipt_id AND organization_id = v_org
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Payment receipt not found in organization';
  END IF;

  IF v_line.matched_payment_receipt_id = p_payment_receipt_id
    AND v_line.reconciliation_status = 'matched'
    AND v_payment.reconciliation_status = 'matched'
  THEN
    RETURN v_line;
  END IF;

  IF v_line.reconciliation_status NOT IN ('unmatched', 'review')
    OR v_line.matched_payment_receipt_id IS NOT NULL
  THEN
    RAISE EXCEPTION 'Statement line is no longer available for matching';
  END IF;
  IF v_payment.reconciliation_status NOT IN ('pending', 'unmatched') THEN
    RAISE EXCEPTION 'Payment receipt is no longer available for matching';
  END IF;
  IF v_line.transaction_type <> 'credit'
    OR abs(abs(v_line.amount) - v_payment.payment_amount) > 0.01
  THEN
    RAISE EXCEPTION 'Statement credit amount does not match payment receipt';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.finance_bank_statement_lines
    WHERE matched_payment_receipt_id = p_payment_receipt_id
      AND id <> p_statement_line_id
  ) OR EXISTS (
    SELECT 1 FROM public.finance_external_bank_transactions
    WHERE matched_payment_receipt_id = p_payment_receipt_id
  ) THEN
    RAISE EXCEPTION 'Payment receipt is already matched to another bank movement';
  END IF;

  UPDATE public.finance_bank_statement_lines
  SET matched_payment_receipt_id = p_payment_receipt_id,
      reconciliation_status = 'matched'
  WHERE id = p_statement_line_id
  RETURNING * INTO v_line;

  UPDATE public.payment_receipts
  SET reconciliation_status = 'matched',
      bank_statement_reference = v_line.reference,
      reconciled_by = v_actor,
      reconciled_at = clock_timestamp()
  WHERE id = p_payment_receipt_id;

  INSERT INTO public.audit_log(
    organization_id, actor_user_id, action, target_table, target_id, metadata
  ) VALUES (
    v_org, v_actor, 'finance_bank_statement_line_matched',
    'finance_bank_statement_lines', v_line.id,
    jsonb_build_object('payment_receipt_id', p_payment_receipt_id)
  );

  RETURN v_line;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."match_finance_bank_statement_line"(p_statement_line_id uuid, p_payment_receipt_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."match_finance_bank_statement_line"(p_statement_line_id uuid, p_payment_receipt_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."match_finance_bank_statement_line"(p_statement_line_id uuid, p_payment_receipt_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."match_finance_bank_statement_line"(p_statement_line_id uuid, p_payment_receipt_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."match_finance_external_bank_transaction"(p_transaction_id uuid, p_payment_receipt_id uuid)
 RETURNS finance_external_bank_transactions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_transaction public.finance_external_bank_transactions%rowtype;
  v_receipt public.payment_receipts%rowtype;
BEGIN
  SELECT organization_id INTO v_org
  FROM public.user_profiles
  WHERE id = v_actor AND deactivated_at IS NULL;

  IF v_org IS NULL OR NOT public.is_admin_for_org(v_org) THEN
    RAISE EXCEPTION 'Active finance administrator required';
  END IF;
  IF p_transaction_id IS NULL OR p_payment_receipt_id IS NULL THEN
    RAISE EXCEPTION 'External transaction and payment receipt are required';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('finance-payment-match:' || p_payment_receipt_id::text, 0));

  SELECT * INTO v_transaction
  FROM public.finance_external_bank_transactions
  WHERE id = p_transaction_id AND organization_id = v_org
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'External bank transaction not found in organization';
  END IF;

  SELECT * INTO v_receipt
  FROM public.payment_receipts
  WHERE id = p_payment_receipt_id AND organization_id = v_org
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Payment receipt not found in organization';
  END IF;

  IF v_transaction.matched_payment_receipt_id = p_payment_receipt_id
    AND v_transaction.reconciliation_status = 'matched'
    AND v_receipt.reconciliation_status = 'matched'
  THEN
    RETURN v_transaction;
  END IF;

  IF v_transaction.reconciliation_status NOT IN ('unmatched', 'review')
    OR v_transaction.matched_payment_receipt_id IS NOT NULL
  THEN
    RAISE EXCEPTION 'External bank transaction is no longer available for matching';
  END IF;
  IF v_receipt.reconciliation_status NOT IN ('pending', 'unmatched') THEN
    RAISE EXCEPTION 'Payment receipt is no longer available for matching';
  END IF;
  IF v_transaction.direction <> 'credit'
    OR abs(COALESCE(v_transaction.amount, 0) - v_receipt.payment_amount) > 0.01
  THEN
    RAISE EXCEPTION 'Transaction amount does not match payment receipt';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.finance_external_bank_transactions
    WHERE matched_payment_receipt_id = p_payment_receipt_id
      AND id <> p_transaction_id
  ) OR EXISTS (
    SELECT 1 FROM public.finance_bank_statement_lines
    WHERE matched_payment_receipt_id = p_payment_receipt_id
  ) THEN
    RAISE EXCEPTION 'Payment receipt is already matched to another bank movement';
  END IF;

  UPDATE public.finance_external_bank_transactions
  SET matched_payment_receipt_id = p_payment_receipt_id,
      reconciliation_status = 'matched'
  WHERE id = p_transaction_id
  RETURNING * INTO v_transaction;

  UPDATE public.payment_receipts
  SET reconciliation_status = 'matched',
      bank_statement_reference = v_transaction.external_transaction_id,
      reconciled_by = v_actor,
      reconciled_at = clock_timestamp()
  WHERE id = p_payment_receipt_id;

  INSERT INTO public.audit_log(
    organization_id, actor_user_id, action, target_table, target_id, metadata
  ) VALUES (
    v_org, v_actor, 'finance_external_transaction_matched',
    'finance_external_bank_transactions', v_transaction.id,
    jsonb_build_object(
      'payment_receipt_id', p_payment_receipt_id,
      'amount', v_transaction.amount
    )
  );

  RETURN v_transaction;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."match_finance_external_bank_transaction"(p_transaction_id uuid, p_payment_receipt_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."match_finance_external_bank_transaction"(p_transaction_id uuid, p_payment_receipt_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."match_finance_external_bank_transaction"(p_transaction_id uuid, p_payment_receipt_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."match_finance_external_bank_transaction"(p_transaction_id uuid, p_payment_receipt_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."materialize_roster_slot"(p_slot_id uuid, p_expected_status text DEFAULT 'published'::text)
 RETURNS TABLE(slot_id uuid, shift_id uuid, created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_slot public.roster_slots%rowtype;
begin
  select s.* into v_slot
  from public.roster_slots s
  where s.id = p_slot_id;
  if not found then
    raise exception 'Roster slot not found';
  end if;
  if not public.is_admin_for_org(v_slot.organization_id) then
    raise exception 'Not authorised to materialize this roster slot';
  end if;

  return query
  select *
  from public.materialize_roster_slot_core(p_slot_id, p_expected_status);
end;
$function$;
REVOKE ALL ON FUNCTION "public"."materialize_roster_slot"(p_slot_id uuid, p_expected_status text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."materialize_roster_slot"(p_slot_id uuid, p_expected_status text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."materialize_roster_slot"(p_slot_id uuid, p_expected_status text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."materialize_roster_slot"(p_slot_id uuid, p_expected_status text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."materialize_roster_slot_core"(p_slot_id uuid, p_expected_status text)
 RETURNS TABLE(slot_id uuid, shift_id uuid, created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_slot public.roster_slots%rowtype;
  v_unit public.roster_work_units%rowtype;
  v_staff public.staff_profiles%rowtype;
  v_user uuid;
  v_shift public.shifts%rowtype;
  v_shift_status text;
  v_sal public.service_agreement_locations%rowtype;
  v_site_location uuid;
  v_stop uuid;
  v_fatigue_conflict text;
begin
  select s.* into v_slot
  from public.roster_slots s
  where s.id = p_slot_id
  for update;
  if not found then
    raise exception 'Roster slot not found';
  end if;
  if v_slot.status <> p_expected_status then
    raise exception 'Roster slot changed from expected status % to %', p_expected_status, v_slot.status;
  end if;

  select u.* into v_unit
  from public.roster_work_units u
  where u.id = v_slot.work_unit_id
    and u.organization_id = v_slot.organization_id
    and u.active;
  if not found then
    raise exception 'Active work unit not found';
  end if;
  if v_unit.work_unit_type not in ('patrol', 'static') then
    raise exception 'Only patrol and static roster slots materialize field shifts';
  end if;

  select sp.* into v_staff
  from public.staff_profiles sp
  where sp.id = v_slot.staff_id and sp.work_ready;
  if not found or not (
    v_staff.organization_id = v_slot.organization_id
    or exists (
      select 1
      from public.staff_branch_authorisations sba
      where sba.user_id = v_staff.user_id
        and sba.branch_org_id = v_slot.organization_id
        and sba.status = 'active'
    )
  ) then
    raise exception 'Work-ready staff profile required';
  end if;

  v_user := coalesce(v_staff.user_id, v_staff.id);
  if not exists (
    select 1
    from public.user_profiles up
    where up.id = v_user
      and up.deactivated_at is null
      and up.role in ('officer', 'admin_officer')
  ) then
    raise exception 'Roster slot staff is not an active field officer';
  end if;

  if v_slot.scheduled_start < now() - interval '5 minutes'
    or v_slot.scheduled_end <= v_slot.scheduled_start
    or v_slot.scheduled_end - v_slot.scheduled_start > interval '24 hours'
  then
    raise exception 'Slot timing is outside the accepted range';
  end if;

  if exists (
    select 1
    from public.leave_requests l
    where l.staff_id = v_staff.id
      and l.status = 'approved'
      and daterange(l.starts_on, l.ends_on, '[]')
        && daterange(v_slot.scheduled_start::date, v_slot.scheduled_end::date, '[]')
  ) then
    raise exception 'Staff member has approved leave';
  end if;

  if public.staff_has_roster_availability_conflict(
    v_staff.id,
    v_slot.scheduled_start,
    v_slot.scheduled_end
  ) then
    raise exception 'Staff member is unavailable during this roster slot';
  end if;

  v_fatigue_conflict := public.staff_fatigue_conflict(
    v_staff.id,
    v_slot.scheduled_start,
    v_slot.scheduled_end,
    v_slot.id
  );
  if v_fatigue_conflict is not null then
    raise exception 'Fatigue rule breach: %', v_fatigue_conflict;
  end if;

  if exists (
    select 1
    from public.shifts s
    where s.id <> coalesce(v_slot.linked_shift_id, '00000000-0000-0000-0000-000000000000'::uuid)
      and s.officer_user_id = v_user
      and s.status not in ('declined', 'cancelled')
      and s.scheduled_start < v_slot.scheduled_end
      and s.scheduled_end > v_slot.scheduled_start
  ) then
    raise exception 'Officer already has an overlapping field shift';
  end if;

  v_shift_status := case when v_slot.status = 'accepted' then 'accepted' else 'published' end;

  if v_slot.linked_shift_id is not null then
    select s.* into v_shift
    from public.shifts s
    where s.id = v_slot.linked_shift_id
    for update;
    if not found then
      raise exception 'Linked field shift not found';
    end if;

    if v_shift.officer_user_id <> v_user then
      if v_shift.status not in ('published', 'accepted', 'declined')
        or v_shift.actual_start is not null
      then
        raise exception 'Field shift has started or is no longer reassignable';
      end if;
      if exists (
        select 1 from public.patrols p
        where p.shift_id = v_shift.id and p.status = 'in_progress'
      ) then
        raise exception 'Active patrol prevents reassignment';
      end if;
      if exists (
        select 1 from public.dispatch_jobs d
        where d.shift_id = v_shift.id
          and d.status in ('pending', 'pending_approval', 'dispatched', 'acknowledged', 'en_route', 'on_scene')
      ) then
        raise exception 'Active dispatch work prevents reassignment';
      end if;
      if exists (
        select 1 from public.shift_stop_actions a
        where a.shift_id = v_shift.id
      ) then
        raise exception 'Recorded field activity prevents reassignment';
      end if;
    end if;

    update public.shifts
    set officer_user_id = v_user,
        status = v_shift_status
    where id = v_shift.id
    returning * into v_shift;

    return query select v_slot.id, v_shift.id, false;
    return;
  end if;

  if v_unit.work_unit_type = 'patrol' then
    insert into public.shifts (
      organization_id,
      officer_user_id,
      service_type,
      patrol_route_id,
      scheduled_start,
      scheduled_end,
      status,
      notes,
      roster_slot_id
    )
    values (
      v_slot.organization_id,
      v_user,
      v_unit.service_type,
      v_unit.patrol_route_id,
      v_slot.scheduled_start,
      v_slot.scheduled_end,
      v_shift_status,
      v_slot.notes,
      v_slot.id
    )
    returning * into v_shift;

    perform public.generate_shift_stops(
      v_shift.id,
      (v_slot.scheduled_start at time zone 'Pacific/Auckland')::date
    );
  elsif v_unit.work_unit_type = 'static' then
    select sal.* into v_sal
    from public.service_agreement_locations sal
    where sal.id = v_unit.service_agreement_location_id
      and sal.status = 'active';
    if not found or not exists (
      select 1
      from public.service_agreement_modules sam
      where sam.id = v_unit.service_agreement_module_id
        and sam.service_agreement_id = v_sal.service_agreement_id
        and sam.enabled
        and sam.module_key = 'static_guarding'
    ) then
      raise exception 'Static work unit contract is no longer active';
    end if;

    if v_sal.site_id is not null then
      select cs.location_id into v_site_location
      from public.client_sites cs
      where cs.id = v_sal.site_id;
    end if;

    insert into public.shifts (
      organization_id,
      officer_user_id,
      service_type,
      location_id,
      zone_id,
      scheduled_start,
      scheduled_end,
      status,
      notes,
      roster_slot_id,
      service_agreement_location_id,
      service_agreement_module_id,
      total_stops,
      generated_at
    )
    values (
      v_slot.organization_id,
      v_user,
      v_unit.service_type,
      v_site_location,
      v_sal.zone_id,
      v_slot.scheduled_start,
      v_slot.scheduled_end,
      v_shift_status,
      v_slot.notes,
      v_slot.id,
      v_unit.service_agreement_location_id,
      v_unit.service_agreement_module_id,
      1,
      clock_timestamp()
    )
    returning * into v_shift;

    insert into public.shift_stops (
      organization_id,
      shift_id,
      site_id,
      zone_id,
      module_key,
      stop_order,
      visit_number,
      is_adhoc,
      sla_arrive_by,
      required_dwell_minutes,
      status,
      sla_status,
      officer_notes
    )
    values (
      v_slot.organization_id,
      v_shift.id,
      v_sal.site_id,
      v_sal.zone_id,
      'static_guarding',
      1,
      1,
      false,
      v_slot.scheduled_start,
      0,
      'pending',
      'on_track',
      v_slot.notes
    )
    returning id into v_stop;

    insert into public.shift_stop_modules (
      organization_id,
      shift_stop_id,
      module_key,
      is_required,
      service_agreement_module_id,
      service_agreement_location_id
    )
    values (
      v_slot.organization_id,
      v_stop,
      'static_guarding',
      true,
      v_unit.service_agreement_module_id,
      v_unit.service_agreement_location_id
    );
  else
    raise exception 'Unsupported field work unit type';
  end if;

  update public.roster_slots
  set linked_shift_id = v_shift.id
  where id = v_slot.id;

  insert into public.audit_log (
    organization_id,
    actor_user_id,
    action,
    target_table,
    target_id,
    metadata
  )
  values (
    v_slot.organization_id,
    v_actor,
    'roster_shift_created',
    'shifts',
    v_shift.id,
    jsonb_build_object(
      'officer_user_id', v_user,
      'staff_id', v_staff.id,
      'roster_slot_id', v_slot.id,
      'status', v_shift.status
    )
  );

  insert into public.audit_log (
    organization_id,
    actor_user_id,
    action,
    target_table,
    target_id,
    metadata
  )
  values (
    v_slot.organization_id,
    v_actor,
    'roster_slot_materialized',
    'roster_slots',
    v_slot.id,
    jsonb_build_object(
      'work_unit_id', v_unit.id,
      'work_unit_type', v_unit.work_unit_type,
      'shift_id', v_shift.id
    )
  );

  return query select v_slot.id, v_shift.id, true;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."materialize_roster_slot_core"(p_slot_id uuid, p_expected_status text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."materialize_roster_slot_core"(p_slot_id uuid, p_expected_status text) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."merge_canonical_place"(p_from uuid, p_into uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' AND session_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;
  IF p_from IS NULL OR p_into IS NULL OR p_from = p_into THEN RETURN; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.canonical_places WHERE id = p_into AND status <> 'merged') THEN
    RAISE EXCEPTION 'Merge target % is not an active canonical place', p_into;
  END IF;
  UPDATE public.observations SET canonical_place_id = p_into WHERE canonical_place_id = p_from;
  UPDATE public.incidents SET canonical_place_id = p_into WHERE canonical_place_id = p_from;
  UPDATE public.location_events SET canonical_place_id = p_into WHERE canonical_place_id = p_from;
  UPDATE public.officer_field_reports SET canonical_place_id = p_into WHERE canonical_place_id = p_from;
  UPDATE public.canonical_place_links SET canonical_place_id = p_into WHERE canonical_place_id = p_from;
  UPDATE public.locations SET canonical_place_id = p_into, updated_at = now() WHERE canonical_place_id = p_from;
  UPDATE public.canonical_places SET merged_into_id = p_into WHERE merged_into_id = p_from;
  UPDATE public.canonical_places SET status = 'merged', merged_into_id = p_into, updated_at = now() WHERE id = p_from;
END $function$;
REVOKE ALL ON FUNCTION "public"."merge_canonical_place"(p_from uuid, p_into uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."merge_canonical_place"(p_from uuid, p_into uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."merge_canonical_place"(p_from uuid, p_into uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."merge_person_records"(p_organization_id uuid, p_source_person_record_id uuid, p_target_person_record_id uuid, p_reason text, p_display_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_source public.person_records%rowtype;
  v_target public.person_records%rowtype;
  v_source_canonical uuid;
  v_target_canonical uuid;
  v_link record;
  v_incident_link public.incident_person_links%rowtype;
  v_name text;
  v_counts jsonb := '{}'::jsonb;
  v_n integer;
BEGIN
  IF v_actor IS NULL OR NOT public.is_admin_for_org(p_organization_id) THEN RAISE EXCEPTION 'An administrator merges person records'; END IF;
  IF coalesce(trim(p_reason), '') = '' THEN RAISE EXCEPTION 'Say why these are the same person'; END IF;
  SELECT * INTO v_source FROM public.person_records WHERE id = p_source_person_record_id AND organization_id = p_organization_id FOR UPDATE;
  SELECT * INTO v_target FROM public.person_records WHERE id = p_target_person_record_id AND organization_id = p_organization_id FOR UPDATE;
  IF v_source.id IS NULL OR v_target.id IS NULL OR v_source.id = v_target.id THEN RAISE EXCEPTION 'Choose two different people in this organisation'; END IF;
  IF v_source.metadata ? 'merged_into_person_record_id' OR v_target.metadata ? 'merged_into_person_record_id'
     OR v_source.metadata ? 'resolved_into_person_record_id' OR v_target.metadata ? 'resolved_into_person_record_id' THEN
    RAISE EXCEPTION 'One of these records has already been merged';
  END IF;
  IF v_source.review_state = 'verified' AND v_target.review_state <> 'verified' THEN
    RAISE EXCEPTION 'Keep the verified record: merge the unverified profile into the verified one';
  END IF;
  IF nullif(v_source.metadata->'profile_details'->>'staff_profile_id', '') IS NOT NULL
     AND nullif(v_target.metadata->'profile_details'->>'staff_profile_id', '') IS NOT NULL
     AND v_source.metadata->'profile_details'->>'staff_profile_id' <> v_target.metadata->'profile_details'->>'staff_profile_id' THEN
    RAISE EXCEPTION 'Both records belong to different staff members';
  END IF;
  v_source_canonical := public.ensure_canonical_person_for_record(v_source.id);
  v_target_canonical := public.ensure_canonical_person_for_record(v_target.id);

  -- Identity evidence and biometrics follow the person.
  UPDATE public.person_identity_documents SET person_record_id = v_target.id, updated_at = clock_timestamp() WHERE person_record_id = v_source.id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('identity_documents', v_n);
  UPDATE public.person_identity_face_proposals SET person_record_id = v_target.id WHERE person_record_id = v_source.id;
  DELETE FROM public.person_face_templates s WHERE s.person_record_id = v_source.id AND EXISTS (
    SELECT 1 FROM public.person_face_templates t WHERE t.person_record_id = v_target.id AND t.organization_id = s.organization_id
      AND t.source_kind = s.source_kind AND t.source_ref = s.source_ref);
  UPDATE public.person_face_templates SET person_record_id = v_target.id WHERE person_record_id = v_source.id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('face_templates', v_n);

  -- Incidents (unique per incident, canonical person and role).
  FOR v_incident_link IN SELECT * FROM public.incident_person_links WHERE person_record_id = v_source.id LOOP
    INSERT INTO public.incident_person_links(organization_id, incident_id, canonical_person_id, person_record_id, staff_profile_id, identity_document_id,
      involvement_role, source_kind, notes, recorded_by, created_at, updated_at)
    VALUES (v_incident_link.organization_id, v_incident_link.incident_id, v_target_canonical, v_target.id,
      coalesce(nullif(v_target.metadata->'profile_details'->>'staff_profile_id', '')::uuid, v_incident_link.staff_profile_id),
      v_incident_link.identity_document_id, v_incident_link.involvement_role, v_incident_link.source_kind, v_incident_link.notes,
      v_actor, v_incident_link.created_at, clock_timestamp())
    ON CONFLICT (incident_id, canonical_person_id, involvement_role) DO UPDATE SET
      person_record_id = excluded.person_record_id,
      identity_document_id = coalesce(incident_person_links.identity_document_id, excluded.identity_document_id),
      updated_at = clock_timestamp();
  END LOOP;
  DELETE FROM public.incident_person_links WHERE person_record_id = v_source.id;

  -- Sightings, CCTV and reviews.
  UPDATE public.cctv_entity_observations SET person_record_id = v_target.id, canonical_person_id = v_target_canonical WHERE person_record_id = v_source.id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('cctv_sightings', v_n);
  UPDATE public.face_observations SET person_record_id = v_target.id WHERE person_record_id = v_source.id;
  UPDATE public.observations SET person_record_id = v_target.id WHERE person_record_id = v_source.id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('observations', v_n);
  UPDATE public.cctv_identity_drafts SET proposed_person_record_id = v_target.id WHERE proposed_person_record_id = v_source.id;
  UPDATE public.cctv_identity_drafts SET final_person_record_id = v_target.id WHERE final_person_record_id = v_source.id;
  UPDATE public.cctv_review_event_decisions SET linked_person_record_id = v_target.id WHERE linked_person_record_id = v_source.id;
  UPDATE public.cctv_review_events SET linked_person_record_id = v_target.id WHERE linked_person_record_id = v_source.id;
  -- NZTA owner checks follow the person on both identity keys; the owner-history trigger then rebuilds
  -- the vehicle's registered-owner periods for the kept person.
  UPDATE public.vehicle_identity_checks SET person_record_id = v_target.id, canonical_person_id = v_target_canonical
  WHERE person_record_id = v_source.id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('vehicle_owner_checks', v_n);
  DELETE FROM public.observation_person_mentions s WHERE s.person_record_id = v_source.id AND s.status <> 'dismissed' AND EXISTS (
    SELECT 1 FROM public.observation_person_mentions t WHERE t.person_record_id = v_target.id AND t.observation_id = s.observation_id AND t.status <> 'dismissed');
  UPDATE public.observation_person_mentions SET person_record_id = v_target.id WHERE person_record_id = v_source.id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('sighting_mentions', v_n);

  -- Vehicle people and other graph edges keyed by canonical person.
  FOR v_link IN SELECT * FROM public.entity_links WHERE from_type = 'person' AND from_id = v_source_canonical AND active LOOP
    IF EXISTS (SELECT 1 FROM public.entity_links t WHERE t.organization_id = v_link.organization_id AND t.from_type = 'person'
        AND t.from_id = v_target_canonical AND t.to_type = v_link.to_type AND t.to_id = v_link.to_id AND t.relationship = v_link.relationship AND t.active) THEN
      UPDATE public.entity_links t SET evidence = t.evidence || jsonb_build_object('observation_ids', (
          SELECT coalesce(jsonb_agg(DISTINCT item), '[]'::jsonb)
          FROM jsonb_array_elements(coalesce(t.evidence->'observation_ids', '[]'::jsonb) || coalesce(v_link.evidence->'observation_ids', '[]'::jsonb)) item)),
        updated_at = clock_timestamp()
      WHERE t.organization_id = v_link.organization_id AND t.from_type = 'person' AND t.from_id = v_target_canonical
        AND t.to_type = v_link.to_type AND t.to_id = v_link.to_id AND t.relationship = v_link.relationship AND t.active;
      UPDATE public.entity_links SET active = false, ends_at = clock_timestamp(), updated_at = clock_timestamp(),
        evidence = evidence || jsonb_build_object('merged_into_canonical_person_id', v_target_canonical)
      WHERE id = v_link.id;
    ELSE
      UPDATE public.entity_links SET from_id = v_target_canonical, updated_at = clock_timestamp(),
        evidence = evidence || jsonb_build_object('person_record_id', v_target.id, 'merged_from_person_record_id', v_source.id)
      WHERE id = v_link.id;
    END IF;
  END LOOP;
  UPDATE public.entity_links SET from_id = v_target_canonical, updated_at = clock_timestamp()
  WHERE from_type = 'person' AND from_id = v_source_canonical AND NOT active;
  UPDATE public.entity_links SET to_id = v_target_canonical, updated_at = clock_timestamp()
  WHERE to_type = 'person' AND to_id = v_source_canonical;
  UPDATE public.entity_flags SET entity_id = v_target_canonical WHERE entity_type = 'person' AND entity_id = v_source_canonical;

  -- Names: the other profile's name becomes an AKA of the kept person.
  v_name := coalesce(nullif(trim(p_display_name), ''), v_target.display_name);
  IF public.normalize_person_name(v_name) IS NULL THEN RAISE EXCEPTION 'The kept person needs a name'; END IF;
  UPDATE public.person_record_aliases s SET active = false, retired_at = clock_timestamp(), retired_by = v_actor, retired_reason = 'Duplicate after merge'
  WHERE s.person_record_id = v_source.id AND s.active AND EXISTS (
    SELECT 1 FROM public.person_record_aliases t WHERE t.person_record_id = v_target.id AND t.active AND t.alias_norm = s.alias_norm);
  UPDATE public.person_record_aliases SET person_record_id = v_target.id, organization_id = p_organization_id WHERE person_record_id = v_source.id;
  INSERT INTO public.person_record_aliases (organization_id, person_record_id, alias, alias_norm, alias_kind, source, notes, created_by)
  SELECT p_organization_id, v_target.id, n.name, public.normalize_person_name(n.name), 'merged_record', 'merge', trim(p_reason), v_actor
  FROM (VALUES (v_source.display_name), (v_target.display_name)) n(name)
  WHERE public.normalize_person_name(n.name) IS NOT NULL AND public.normalize_person_name(n.name) <> public.normalize_person_name(v_name)
  ON CONFLICT (person_record_id, alias_norm) WHERE active DO NOTHING;
  -- Kept name is no longer an alias of itself.
  UPDATE public.person_record_aliases SET active = false, retired_at = clock_timestamp(), retired_by = v_actor, retired_reason = 'Now the main name'
  WHERE person_record_id = v_target.id AND active AND alias_norm = public.normalize_person_name(v_name);

  UPDATE public.person_records SET
    display_name = v_name,
    metadata = metadata
      || jsonb_build_object('profile_details', coalesce(v_source.metadata->'profile_details', '{}'::jsonb) || coalesce(metadata->'profile_details', '{}'::jsonb))
      || CASE WHEN NOT (metadata ? 'face_reference') AND v_source.metadata ? 'face_reference'
           THEN jsonb_build_object('face_reference', v_source.metadata->'face_reference') ELSE '{}'::jsonb END
      || jsonb_build_object('merged_from_person_record_ids',
           coalesce(metadata->'merged_from_person_record_ids', '[]'::jsonb) || jsonb_build_array(v_source.id))
  WHERE id = v_target.id;
  UPDATE public.canonical_people SET display_name = v_name, normalized_name = public.normalize_person_name(v_name), updated_at = clock_timestamp()
  WHERE id = v_target_canonical;

  UPDATE public.canonical_person_links SET canonical_person_id = v_target_canonical,
    metadata = metadata || jsonb_build_object('merged_from_canonical_person_id', v_source_canonical, 'merged_by', v_actor, 'merged_at', clock_timestamp())
  WHERE source_table = 'person_records' AND source_id = v_source.id;
  IF NOT EXISTS (SELECT 1 FROM public.canonical_person_links WHERE canonical_person_id = v_source_canonical) THEN
    UPDATE public.canonical_people SET status = 'merged', merged_into_id = v_target_canonical, updated_at = clock_timestamp() WHERE id = v_source_canonical;
  END IF;
  UPDATE public.person_records SET review_state = 'rejected',
    metadata = metadata || jsonb_build_object('merged_into_person_record_id', v_target.id, 'merged_at', clock_timestamp(),
      'merged_by', v_actor, 'merge_reason', trim(p_reason))
  WHERE id = v_source.id;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (p_organization_id, v_actor, 'person_records_merged', 'person_records', v_target.id, jsonb_build_object(
    'source_person_record_id', v_source.id, 'source_display_name', v_source.display_name,
    'target_person_record_id', v_target.id, 'kept_display_name', v_name,
    'source_canonical_person_id', v_source_canonical, 'target_canonical_person_id', v_target_canonical,
    'moved', v_counts, 'reason', trim(p_reason)));
  RETURN jsonb_build_object('person_record_id', v_target.id, 'merged_person_record_id', v_source.id,
    'canonical_person_id', v_target_canonical, 'display_name', v_name, 'moved', v_counts);
END;
$function$;
COMMENT ON FUNCTION "public"."merge_person_records"(p_organization_id uuid, p_source_person_record_id uuid, p_target_person_record_id uuid, p_reason text, p_display_name text) IS 'Administrator merge of two profiles of the same person (for example a CCTV "Unknown Person #N" and a named person). Moves identity evidence, face templates, sightings, CCTV, incidents, NZTA owner checks (person record and canonical person, so owner history follows), vehicle people, mentions, flags and aliases to the kept record; the other name becomes an AKA; the merged record is retained (rejected, merged_into_person_record_id) for audit.';
REVOKE ALL ON FUNCTION "public"."merge_person_records"(p_organization_id uuid, p_source_person_record_id uuid, p_target_person_record_id uuid, p_reason text, p_display_name text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."merge_person_records"(p_organization_id uuid, p_source_person_record_id uuid, p_target_person_record_id uuid, p_reason text, p_display_name text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."merge_person_records"(p_organization_id uuid, p_source_person_record_id uuid, p_target_person_record_id uuid, p_reason text, p_display_name text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."move_document_to_folder"(p_organization_id uuid, p_document_id uuid, p_space_id uuid, p_folder_id uuid, p_client_request_id uuid)
 RETURNS document_placements
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_actor uuid:=auth.uid();v_space public.file_spaces%rowtype;v_folder public.file_folders%rowtype;v_placement public.document_placements%rowtype;
BEGIN
  IF v_actor IS NULL OR NOT public.is_admin_for_org(p_organization_id) THEN RAISE EXCEPTION 'Active organization administrator required'; END IF;
  IF p_client_request_id IS NULL THEN RAISE EXCEPTION 'client_request_id is required'; END IF;
  SELECT * INTO v_placement FROM public.document_placements WHERE organization_id=p_organization_id AND client_request_id=p_client_request_id;
  IF FOUND THEN RETURN v_placement; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.documents WHERE id=p_document_id AND organization_id=p_organization_id) THEN RAISE EXCEPTION 'Document not found in this organization'; END IF;
  SELECT * INTO v_space FROM public.file_spaces WHERE id=p_space_id AND organization_id=p_organization_id AND active;
  IF v_space.id IS NULL THEN RAISE EXCEPTION 'Destination section not found'; END IF;
  IF NOT public.file_space_access_allowed(p_organization_id,v_space.sensitivity) THEN RAISE EXCEPTION 'Destination folder access denied'; END IF;
  IF EXISTS(SELECT 1 FROM public.document_placements placement JOIN public.file_spaces source_space ON source_space.id=placement.space_id WHERE placement.document_id=p_document_id AND placement.is_primary AND placement.removed_at IS NULL AND NOT public.file_space_access_allowed(p_organization_id,source_space.sensitivity)) THEN RAISE EXCEPTION 'Source file access denied'; END IF;
  IF p_folder_id IS NOT NULL THEN
    SELECT * INTO v_folder FROM public.file_folders WHERE id=p_folder_id AND organization_id=p_organization_id AND space_id=p_space_id AND active;
    IF v_folder.id IS NULL THEN RAISE EXCEPTION 'Destination folder not found'; END IF;
  END IF;
  UPDATE public.document_placements SET is_primary=false,removed_at=clock_timestamp() WHERE document_id=p_document_id AND is_primary AND removed_at IS NULL;
  INSERT INTO public.document_placements(organization_id,document_id,space_id,folder_id,is_primary,client_request_id,placed_by)
  VALUES(p_organization_id,p_document_id,v_space.id,v_folder.id,true,p_client_request_id,v_actor) RETURNING * INTO v_placement;
  INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) VALUES(p_organization_id,v_actor,'document_moved_to_folder','documents',p_document_id,jsonb_build_object('folder_id',p_folder_id,'space_id',v_space.id,'placement_id',v_placement.id));
  RETURN v_placement;
END;
$function$;
COMMENT ON FUNCTION "public"."move_document_to_folder"(p_organization_id uuid, p_document_id uuid, p_space_id uuid, p_folder_id uuid, p_client_request_id uuid) IS 'Moves a tenant document to a file-space root or folder while retaining placement history and an audit receipt.';
REVOKE ALL ON FUNCTION "public"."move_document_to_folder"(p_organization_id uuid, p_document_id uuid, p_space_id uuid, p_folder_id uuid, p_client_request_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."move_document_to_folder"(p_organization_id uuid, p_document_id uuid, p_space_id uuid, p_folder_id uuid, p_client_request_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."move_document_to_folder"(p_organization_id uuid, p_document_id uuid, p_space_id uuid, p_folder_id uuid, p_client_request_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."move_document_to_folder"(p_organization_id uuid, p_document_id uuid, p_space_id uuid, p_folder_id uuid, p_client_request_id uuid) TO "service_role";

