CREATE OR REPLACE FUNCTION "public"."notice_expiry_state"(p_status text, p_expires_at timestamp with time zone, p_window_days integer DEFAULT 30)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  SELECT CASE
    WHEN p_status IN ('draft', 'withdrawn') THEN p_status
    WHEN p_expires_at IS NULL THEN 'no_expiry'
    WHEN p_expires_at <= clock_timestamp() THEN 'expired'
    WHEN p_expires_at <= clock_timestamp() + make_interval(days => greatest(coalesce(p_window_days, 30), 0)) THEN 'expiring_soon'
    ELSE 'in_force'
  END;
$function$;
COMMENT ON FUNCTION "public"."notice_expiry_state"(p_status text, p_expires_at timestamp with time zone, p_window_days integer) IS 'Plain state of a notice for people searches and registers: draft, withdrawn, no_expiry, in_force, expiring_soon (inside the window) or expired.';
REVOKE ALL ON FUNCTION "public"."notice_expiry_state"(p_status text, p_expires_at timestamp with time zone, p_window_days integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."notice_expiry_state"(p_status text, p_expires_at timestamp with time zone, p_window_days integer) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."notice_expiry_state"(p_status text, p_expires_at timestamp with time zone, p_window_days integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."notice_expiry_state"(p_status text, p_expires_at timestamp with time zone, p_window_days integer) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."notice_expiry_state"(p_status text, p_expires_at timestamp with time zone, p_window_days integer) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."notice_expiry_state"(p_status text, p_expires_at timestamp with time zone, p_window_days integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."notices_set_expiry"()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  IF NEW.notice_type IN ('trespass', 'warning') AND NEW.issued_at IS NOT NULL THEN
    IF NEW.expires_at IS NULL
       OR (TG_OP = 'UPDATE'
           AND NEW.issued_at IS DISTINCT FROM OLD.issued_at
           AND NEW.expires_at IS NOT DISTINCT FROM OLD.expires_at
           AND OLD.expires_at = OLD.issued_at + interval '2 years') THEN
      NEW.expires_at := NEW.issued_at + interval '2 years';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."notices_set_expiry"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."notices_set_expiry"() TO "postgres";

CREATE OR REPLACE FUNCTION "public"."notify_builder_job_terminal"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_recipient uuid;
  v_outcome text;
  v_severity text;
BEGIN
  IF NEW.status NOT IN ('deployed', 'failed', 'cancelled')
     AND COALESCE(NEW.autopilot_state, '') NOT IN ('done', 'blocked', 'cancelled') THEN
    RETURN NEW;
  END IF;

  IF OLD.status IN ('deployed', 'failed', 'cancelled')
     OR COALESCE(OLD.autopilot_state, '') IN ('done', 'blocked', 'cancelled') THEN
    RETURN NEW;
  END IF;

  v_recipient := COALESCE(NEW.autopilot_requested_by, NEW.created_by);
  IF v_recipient IS NULL THEN
    RETURN NEW;
  END IF;

  v_outcome := CASE
    WHEN NEW.status IN ('deployed', 'failed', 'cancelled') THEN NEW.status
    ELSE COALESCE(NULLIF(NEW.autopilot_state, ''), NEW.status)
  END;
  v_severity := CASE
    WHEN NEW.status = 'failed' OR NEW.autopilot_state = 'blocked' THEN 'warning'
    ELSE 'info'
  END;

  PERFORM public.enqueue_notification(
    p_organization_id => NEW.organization_id,
    p_category => 'builder_job',
    p_title => 'Bob Builder job finished: ' || left(NEW.title, 140),
    p_body => 'Outcome: ' || v_outcome || '. Open Builder to review the job receipt.',
    p_severity => v_severity,
    p_recipient_user_id => v_recipient,
    p_recipient_role => NULL,
    p_link_page => 'builder',
    p_link_payload => jsonb_build_object('job_id', NEW.id, 'status', NEW.status, 'autopilot_state', NEW.autopilot_state),
    p_dedup_key => 'builder_job_terminal:' || NEW.id::text || ':' || v_outcome
  );

  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."notify_builder_job_terminal"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."notify_builder_job_terminal"() TO "postgres";

CREATE OR REPLACE FUNCTION "public"."notify_dispatch_job_created"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_officer uuid;
begin
  if new.status not in('pending','dispatched') then return new;end if;
  if new.dispatch_resource_id is not null then select dr.assigned_officer_id into v_officer from public.dispatch_resources dr where dr.id=new.dispatch_resource_id;end if;
  if v_officer is null and new.shift_id is not null then select s.officer_user_id into v_officer from public.shifts s where s.id=new.shift_id;end if;
  if v_officer is null then return new;end if;
  perform public.enqueue_notification(p_organization_id=>new.organization_id,p_category=>'dispatch',p_title=>'New dispatch assignment',p_body=>replace(new.job_type,'_',' ')||' requires your response.',p_severity=>case when new.priority in('urgent','high') then 'warning' else 'info' end,p_recipient_user_id=>v_officer,p_link_page=>'dispatch',p_link_payload=>jsonb_build_object('dispatch_job_id',new.id),p_dedup_key=>'dispatch_job_assigned:'||new.id::text);
  return new;
end;$function$;
REVOKE ALL ON FUNCTION "public"."notify_dispatch_job_created"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."notify_dispatch_job_created"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."notify_dispatch_job_created"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."notify_dispatch_job_created"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."notify_place_hazard_report"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_reviewer record;
BEGIN
  IF NEW.status = 'reported' AND NEW.origin = 'officer_reported' THEN
    FOR v_reviewer IN
      SELECT p.id FROM public.user_profiles p
      WHERE p.organization_id = NEW.organization_id AND p.deactivated_at IS NULL
        AND p.role IN ('admin', 'admin_officer', 'master', 'grand_master')
    LOOP
      PERFORM public.enqueue_notification(
        p_organization_id => NEW.organization_id, p_category => 'place_hazard_review',
        p_title => 'Reported site hazard needs review',
        p_body => 'An officer reported a hazard. It is visible to officers as not yet reviewed. Confirm, amend or retire it in the place hazard register.',
        p_severity => CASE WHEN NEW.risk_level IN ('high', 'critical') THEN 'warning' ELSE 'info' END,
        p_recipient_user_id => v_reviewer.id, p_link_page => 'sites',
        p_link_payload => jsonb_build_object('site_id', NEW.client_site_id, 'location_id', NEW.location_id, 'hazard_id', NEW.id),
        p_dedup_key => 'place_hazard_review:' || NEW.id::text || ':' || v_reviewer.id::text
      );
    END LOOP;
  END IF;
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."notify_place_hazard_report"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."notify_place_hazard_report"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."notify_place_hazard_report"() TO "service_role";

