 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.person_identity_documents d
    WHERE d.attachment_id = p_attachment_id AND d.document_kind = 'nzta_mvr_record'
      AND public.nzta_document_restricted(d.id)
  );
$function$;
REVOKE ALL ON FUNCTION "public"."nzta_attachment_restricted"(p_attachment_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."nzta_attachment_restricted"(p_attachment_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."nzta_attachment_restricted"(p_attachment_id uuid) TO "anon";
