CREATE OR REPLACE FUNCTION "public"."officer_photo_path_allowed"(p_path text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_org uuid;
BEGIN
  IF p_path IS NULL OR p_path !~ '^org/[0-9a-f-]{36}/officer-photos/(field_report|incident)/[0-9a-f-]{36}/[0-9a-f]{64}$' THEN
    RETURN false;
  END IF;
  SELECT c.organization_id INTO v_org FROM public.officer_photo_target_context(
    split_part(p_path,'/',4), split_part(p_path,'/',5)::uuid
  ) c;
  RETURN v_org = split_part(p_path,'/',2)::uuid;
EXCEPTION WHEN invalid_text_representation OR raise_exception THEN RETURN false;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."officer_photo_path_allowed"(p_path text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."officer_photo_path_allowed"(p_path text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."officer_photo_path_allowed"(p_path text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."officer_photo_path_allowed"(p_path text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."officer_photo_target_context"(p_record_kind text, p_record_id uuid)
 RETURNS TABLE(organization_id uuid, shift_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_org uuid;
  v_shift uuid;
BEGIN
  IF v_user IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.user_profiles p WHERE p.id = v_user AND p.deactivated_at IS NULL
  ) THEN RAISE EXCEPTION 'Photo target is unavailable'; END IF;
  IF p_record_kind = 'field_report' THEN
    SELECT r.organization_id, r.shift_id INTO v_org, v_shift
    FROM public.officer_field_reports r
    JOIN public.user_profiles p ON p.id = v_user AND p.organization_id = r.organization_id
    WHERE r.id = p_record_id AND r.officer_id = v_user;
  ELSIF p_record_kind = 'incident' THEN
    SELECT i.organization_id, j.shift_id INTO v_org, v_shift
    FROM public.incidents i
    JOIN public.user_profiles p ON p.id = v_user AND p.organization_id = i.organization_id
    LEFT JOIN public.dispatch_jobs j ON j.id = i.dispatch_job_id
      AND j.organization_id = i.organization_id
    WHERE i.id = p_record_id AND i.officer_user_id = v_user
      AND (i.dispatch_job_id IS NULL OR j.id IS NOT NULL);
  END IF;
  IF v_org IS NULL OR NOT public.org_access_allowed(v_org) THEN
    RAISE EXCEPTION 'Photo target is unavailable';
  END IF;
  IF v_shift IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.shifts s WHERE s.id = v_shift
      AND s.organization_id = v_org AND s.officer_user_id = v_user
  ) THEN RAISE EXCEPTION 'Photo shift context is unavailable'; END IF;
  RETURN QUERY SELECT v_org, v_shift;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."officer_photo_target_context"(p_record_kind text, p_record_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."officer_photo_target_context"(p_record_kind text, p_record_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."officer_photo_target_context"(p_record_kind text, p_record_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."officer_photo_target_context"(p_record_kind text, p_record_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."officer_report_inherit_shift_place"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_count integer;
  v_site uuid;
  v_zone uuid;
begin
  if new.shift_id is null or new.site_id is not null or new.zone_id is not null then
    return new;
  end if;
  select count(*), (array_agg(p.site_id))[1], (array_agg(p.zone_id))[1]
    into v_count, v_site, v_zone
  from (
    select distinct st.site_id, st.zone_id
    from public.shift_stops st
    join public.shifts s on s.id = st.shift_id and s.organization_id = new.organization_id
    where st.shift_id = new.shift_id
      and (st.site_id is not null or st.zone_id is not null)
  ) p;
  if coalesce(v_count, 0) = 0 then
    -- A static shift may carry its place on the shift rather than on stops.
    select count(*), (array_agg(p.site_id))[1], (array_agg(p.zone_id))[1]
      into v_count, v_site, v_zone
    from (
      select l.site_id, l.zone_id
      from public.shifts s
      join public.service_agreement_locations l on l.id = s.service_agreement_location_id
      where s.id = new.shift_id and s.organization_id = new.organization_id
        and (l.site_id is not null or l.zone_id is not null)
      union
      select null::uuid, s.zone_id
      from public.shifts s
      where s.id = new.shift_id and s.organization_id = new.organization_id
        and s.service_agreement_location_id is null and s.zone_id is not null
    ) p;
  end if;
  -- Only an unambiguous single place is inherited; a multi-place patrol shift
  -- leaves the report unplaced for an admin to resolve.
  if v_count = 1 then
    if v_zone is not null then
      new.zone_id := v_zone;
    else
      new.site_id := v_site;
    end if;
  end if;
  return new;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."officer_report_inherit_shift_place"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."officer_report_inherit_shift_place"() TO "postgres";

CREATE OR REPLACE FUNCTION "public"."open_callout"(p_client_request_id uuid, p_on_call_period_id uuid, p_dispatch_job_id uuid DEFAULT NULL::uuid, p_minimum_pay_hours numeric DEFAULT 3, p_after_minimum_rate numeric DEFAULT NULL::numeric, p_notes text DEFAULT NULL::text)
 RETURNS callout_shifts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_period public.on_call_periods%rowtype;
  v_callout public.callout_shifts%rowtype;
begin
  if p_client_request_id is null then
    raise exception 'client_request_id is required';
  end if;

  select p.* into v_period from public.on_call_periods p where p.id = p_on_call_period_id for update;
  if not found then
    raise exception 'On-call period not found';
  end if;

  if not public.is_admin_for_org(v_period.organization_id) then
    raise exception 'Not authorised to raise callouts for this organization';
  end if;

  select c.* into v_callout from public.callout_shifts c
  where c.organization_id = v_period.organization_id and c.client_request_id = p_client_request_id;
  if found then
    return v_callout;
  end if;

  if v_period.status <> 'accepted' then
    raise exception 'Callouts can only be raised against an accepted on-call period';
  end if;

  if p_minimum_pay_hours is null or p_minimum_pay_hours <= 0 or p_minimum_pay_hours > 24 then
    raise exception 'Minimum pay hours must be between 0 and 24';
  end if;

  insert into public.callout_shifts(
    organization_id, on_call_period_id, officer_user_id, dispatch_job_id,
    minimum_pay_hours, after_minimum_rate, callout_received_at, status,
    client_request_id, notes
  )
  values (
    v_period.organization_id, v_period.id, v_period.officer_user_id, p_dispatch_job_id,
    p_minimum_pay_hours, p_after_minimum_rate, now(), 'raised',
    p_client_request_id, nullif(trim(coalesce(p_notes, '')), '')
  )
  returning * into v_callout;

  perform public.enqueue_notification(
    v_period.organization_id, 'roster', 'Callout raised',
    format('You have been called out. Minimum %s hours guaranteed.', p_minimum_pay_hours),
    'critical', v_period.officer_user_id, null, 'roster',
    jsonb_build_object('callout_id', v_callout.id), 'callout_raised:' || v_callout.id::text
  );

  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (
    v_period.organization_id, v_actor, 'callout_raised', 'callout_shifts', v_callout.id,
    jsonb_build_object(
      'on_call_period_id', v_period.id,
      'officer_user_id', v_period.officer_user_id,
      'minimum_pay_hours', p_minimum_pay_hours,
      'client_request_id', p_client_request_id
    )
  );

  return v_callout;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."open_callout"(p_client_request_id uuid, p_on_call_period_id uuid, p_dispatch_job_id uuid, p_minimum_pay_hours numeric, p_after_minimum_rate numeric, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."open_callout"(p_client_request_id uuid, p_on_call_period_id uuid, p_dispatch_job_id uuid, p_minimum_pay_hours numeric, p_after_minimum_rate numeric, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."open_callout"(p_client_request_id uuid, p_on_call_period_id uuid, p_dispatch_job_id uuid, p_minimum_pay_hours numeric, p_after_minimum_rate numeric, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."open_callout"(p_client_request_id uuid, p_on_call_period_id uuid, p_dispatch_job_id uuid, p_minimum_pay_hours numeric, p_after_minimum_rate numeric, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."open_incident_safety_review"(p_incident_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_incident public.incidents%rowtype; v_id uuid;
BEGIN
  SELECT * INTO v_incident FROM public.incidents WHERE id = p_incident_id FOR SHARE;
  IF NOT FOUND OR auth.uid() IS NULL OR NOT public.is_admin_for_org(v_incident.organization_id) THEN
    RAISE EXCEPTION 'Incident safety review access denied';
  END IF;
  INSERT INTO public.safety_reviews(organization_id, location_id, incident_id, title)
  VALUES (v_incident.organization_id, coalesce(
    (SELECT location_id FROM public.client_sites WHERE id = v_incident.client_site_id),
    (SELECT location_id FROM public.location_zones WHERE id = v_incident.zone_id), v_incident.location_id
  ), v_incident.id, 'Supervisor-linked incident safety review')
  ON CONFLICT (incident_id) DO UPDATE SET incident_id = excluded.incident_id RETURNING id INTO v_id;
  RETURN v_id;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."open_incident_safety_review"(p_incident_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."open_incident_safety_review"(p_incident_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."open_incident_safety_review"(p_incident_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."open_incident_safety_review"(p_incident_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."open_ptt_transmission"(p_channel_id uuid DEFAULT NULL::uuid, p_emergency boolean DEFAULT false, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS TABLE(transmission_id uuid, organization_id uuid, state text, started_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_org_id uuid;
  v_trans public.ptt_transmissions%rowtype;
begin
  if v_user_id is null then raise exception 'Authentication required'; end if;
  select p.organization_id into v_org_id from public.user_profiles p where p.id = v_user_id and p.deactivated_at is null;
  if v_org_id is null then raise exception 'Active officer profile required for PTT transmission'; end if;

  if p_channel_id is not null and not exists (select 1 from public.ptt_channels c where c.id = p_channel_id and c.organization_id = v_org_id) then
    raise exception 'Channel does not belong to the officer organisation';
  end if;

  insert into public.ptt_transmissions (
    organization_id, channel_id, speaker_user_id, state, emergency, metadata
  ) values (
    v_org_id, p_channel_id, v_user_id, case when p_emergency then 'emergency' else 'started' end, coalesce(p_emergency, false), coalesce(p_metadata, '{}'::jsonb)
  ) returning * into v_trans;

  insert into public.audit_log (
    organization_id, actor_user_id, action, target_table, target_id, metadata
  ) values (
    v_org_id, v_user_id, 'ptt_transmission_started', 'ptt_transmissions', v_trans.id,
    jsonb_build_object('channel_id', p_channel_id, 'emergency', p_emergency)
  );

  return query select v_trans.id, v_trans.organization_id, v_trans.state, v_trans.started_at;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."open_ptt_transmission"(p_channel_id uuid, p_emergency boolean, p_metadata jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."open_ptt_transmission"(p_channel_id uuid, p_emergency boolean, p_metadata jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."open_ptt_transmission"(p_channel_id uuid, p_emergency boolean, p_metadata jsonb) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."open_ptt_transmission"(p_channel_id uuid, p_emergency boolean, p_metadata jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."open_safety_review_from_evidence"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_location uuid;
BEGIN
  IF TG_TABLE_NAME = 'officer_field_reports' THEN
    IF NEW.report_type <> 'health_safety' THEN RETURN NEW; END IF;
    SELECT coalesce(
      (SELECT location_id FROM public.client_sites WHERE id = NEW.site_id),
      (SELECT location_id FROM public.location_zones WHERE id = NEW.zone_id)
    ) INTO v_location;
    INSERT INTO public.safety_reviews(organization_id, location_id, field_report_id, title)
    VALUES (NEW.organization_id, v_location, NEW.id, 'H&S field report review') ON CONFLICT (field_report_id) DO NOTHING;
  ELSE
    INSERT INTO public.safety_reviews(organization_id, location_id, assessment_id, title)
    VALUES (NEW.organization_id, NEW.location_id, NEW.id,
      CASE NEW.decision WHEN 'stop_work' THEN 'STOP WORK - dynamic assessment' ELSE 'Dynamic task assessment review' END)
    ON CONFLICT (assessment_id) DO NOTHING;
  END IF;
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."open_safety_review_from_evidence"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."open_safety_review_from_evidence"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."open_safety_review_from_evidence"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."org_access_allowed"(target_org_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    is_grand_master()
    or exists (
      select 1
      from user_profiles p
      where p.id = auth.uid() and p.deactivated_at is null
        and (
          p.organization_id = target_org_id
          or target_org_id = any(p.authorized_organization_ids)
        )
    )
    or exists (
      select 1
      from user_profiles p
      where p.id = auth.uid() and p.deactivated_at is null
        and p.role in ('grand_master', 'master', 'admin', 'admin_officer')
        and (
          target_org_id = any(get_descendant_organizations(p.organization_id))
          or (
            p.employer_organization_id is not null
            and target_org_id = any(get_descendant_organizations(p.employer_organization_id))
          )
        )
    )
    or exists (
      select 1
      from provider_client_access_grants g
      join user_profiles p on p.id = auth.uid() and p.deactivated_at is null
      where (
        p.organization_id = g.provider_organization_id
        or p.organization_id = g.client_organization_id
      )
        and (g.ends_at is null or g.ends_at > now())
        and (
          g.provider_organization_id = target_org_id
          or g.client_organization_id = target_org_id
        )
    )
    -- Agreement-based visibility (0271 Model A), OPERATIONAL agreements only.
    -- A Layer-1 financial (platform subscription) agreement is a billing link and
    -- confers no data reach in either direction (owner ruling 2026-09-15).
    or exists (
      select 1
      from service_agreements sa
      join user_profiles p on p.id = auth.uid() and p.deactivated_at is null
      where (sa.ends_on is null or sa.ends_on >= current_date)
        and sa.agreement_type = 'operational'
        and (
          (sa.client_organization_id = target_org_id
           and (p.organization_id = sa.provider_organization_id
                or p.employer_organization_id = sa.provider_organization_id))
          or
          (sa.provider_organization_id = target_org_id
           and (p.organization_id = sa.client_organization_id
                or p.employer_organization_id = sa.client_organization_id))
        )
    );
$function$;
COMMENT ON FUNCTION "public"."org_access_allowed"(target_org_id uuid) IS 'Single-target organisation reach check. Row-level security policies use the initPlan form with accessible_org_ids(), which must stay equivalent; change both together.';
REVOKE ALL ON FUNCTION "public"."org_access_allowed"(target_org_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."org_access_allowed"(target_org_id uuid) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."org_access_allowed"(target_org_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."org_access_allowed"(target_org_id uuid) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."org_access_allowed"(target_org_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."org_access_allowed"(target_org_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."org_default_level"(p_type text)
 RETURNS smallint
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case p_type
    when 'owner'              then 0
    when 'service_provider'   then 1
    when 'government'         then 2
    when 'private_enterprise' then 2
    when 'branch'             then 2
    when 'contractor'         then 3
    when 'client'             then 4
    else 2
  end::smallint;
$function$;
REVOKE ALL ON FUNCTION "public"."org_default_level"(p_type text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."org_default_level"(p_type text) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."org_default_level"(p_type text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."org_default_level"(p_type text) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."org_default_level"(p_type text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."org_default_level"(p_type text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."org_set_level"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  parent_level smallint;
begin
  if new.parent_organization_id is null then
    new.organization_level := public.org_default_level(new.organization_type);
  else
    select organization_level into parent_level
      from public.organizations where id = new.parent_organization_id;
    if parent_level is null then
      new.organization_level := public.org_default_level(new.organization_type);
    else
      new.organization_level := (parent_level + 1)::smallint;
    end if;
  end if;
  return new;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."org_set_level"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."org_set_level"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."org_set_level"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."org_set_level"() TO "anon";
GRANT EXECUTE ON FUNCTION "public"."org_set_level"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."org_set_level"() TO "service_role";

