CREATE OR REPLACE FUNCTION "public"."patrol_checkpoints_geometry_guard"()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.radius_meters IS NULL OR NEW.radius_meters < 1 OR NEW.radius_meters > 500 THEN
    RAISE EXCEPTION 'Checkpoint radius must be between 1 and 500 metres';
  END IF;
  IF (NEW.gps_lat IS NULL) <> (NEW.gps_lng IS NULL) THEN
    RAISE EXCEPTION 'Checkpoint position needs both latitude and longitude';
  END IF;
  IF NEW.gps_lat IS NOT NULL AND (NEW.gps_lat NOT BETWEEN -90 AND 90 OR NEW.gps_lng NOT BETWEEN -180 AND 180) THEN
    RAISE EXCEPTION 'Checkpoint position is out of range';
  END IF;
  IF TG_OP = 'INSERT'
     OR (NEW.gps_lat, NEW.gps_lng, NEW.radius_meters) IS DISTINCT FROM (OLD.gps_lat, OLD.gps_lng, OLD.radius_meters) THEN
    NEW.checkpoint_verification := 'unverified';
    NEW.checkpoint_verified_by := NULL;
    NEW.checkpoint_verified_at := NULL;
  END IF;
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."patrol_checkpoints_geometry_guard"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."patrol_checkpoints_geometry_guard"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."patrol_checkpoints_geometry_guard"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."patrol_checkpoints_geometry_guard"() TO "anon";
GRANT EXECUTE ON FUNCTION "public"."patrol_checkpoints_geometry_guard"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."patrol_checkpoints_geometry_guard"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."patrol_import_record_versions_append_only"()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'DELETE' then
    raise exception 'Patrol source history is append-only';
  end if;
  if (to_jsonb(new) - 'is_current') is distinct from (to_jsonb(old) - 'is_current')
     or not (old.is_current and not new.is_current) then
    raise exception 'Patrol source history is append-only; only the current marker may be retired';
  end if;
  return new;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."patrol_import_record_versions_append_only"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."patrol_import_record_versions_append_only"() TO "postgres";

