CREATE OR REPLACE FUNCTION "public"."patrol_source_assert_row_provenance"(p_batch file_import_batches, p_item jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_payload jsonb := p_item->'desired'->'payload';
begin
  if p_item->>'kind' not in ('observation', 'event')
     or nullif(p_item->>'record_id', '') is null
     or jsonb_typeof(p_item->'desired') <> 'object'
     or jsonb_typeof(v_payload) <> 'object'
     or nullif(btrim(p_item->>'external_ref'), '') is null
     or p_item->'desired'->>'external_ref' is distinct from p_item->>'external_ref'
     or coalesce(p_item->>'source_fingerprint', '') !~ '^[a-f0-9]{64}$' then
    raise exception 'Source sync rows require kind, record, external reference, desired state and fingerprint';
  end if;
  if v_payload->>'source_sha256' is distinct from p_batch.source_sha256
     or v_payload->>'derivative_sha256' is distinct from p_batch.manifest_json->>'derivative_sha256'
     or nullif(v_payload->>'source_file', '') is null
     or v_payload->>'source_file' is distinct from p_batch.source_file
     or coalesce(v_payload->>'source_row', '') !~ '^[1-9][0-9]*$'
     or v_payload->>'classification_profile' is distinct from p_batch.manifest_json->>'source_profile' then
    raise exception 'Source sync row provenance does not match its batch';
  end if;
  return jsonb_set(v_payload, '{source}', '"rm_patrol_log_import"'::jsonb, true);
end;
$function$;
REVOKE ALL ON FUNCTION "public"."patrol_source_assert_row_provenance"(p_batch file_import_batches, p_item jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."patrol_source_assert_row_provenance"(p_batch file_import_batches, p_item jsonb) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."patrol_source_correction_dependency_hold"(p_provider_organization_id uuid, p_client_organization_id uuid, p_kind text, p_record_id uuid, p_external_ref text, p_batch_id uuid, p_service_date_unchanged boolean)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_fk record;
  v_linked boolean;
begin
  if exists (
    select 1 from public.file_import_finance_cost_rows cost_row
    join public.finance_service_costs cost on cost.id = cost_row.finance_service_cost_id
    where cost_row.client_organization_id = p_client_organization_id
      and cost_row.evidence_external_ref = p_external_ref
      and (cost.invoice_line_item_id is not null or cost.invoiced_at is not null)
  ) then
    return 'invoiced_record';
  end if;
  if not coalesce(p_service_date_unchanged, false) and exists (
    select 1 from public.file_import_finance_cost_rows cost_row
    where cost_row.client_organization_id = p_client_organization_id
      and cost_row.evidence_external_ref = p_external_ref
  ) then
    return 'finance_cost_linked';
  end if;
  if exists (
    select 1 from public.file_import_row_proposals proposal
    where proposal.organization_id = p_provider_organization_id
      and proposal.source_record_key = p_external_ref
      and proposal.batch_id <> p_batch_id
      and proposal.status in ('proposed', 'approved')
  ) then
    return 'dependent_proposal_review_required';
  end if;
  if p_kind = 'event' then
    for v_fk in
      select constraint_def.conrelid::regclass as table_name, attribute.attname as column_name
      from pg_constraint constraint_def
      join pg_attribute attribute
        on attribute.attrelid = constraint_def.conrelid and attribute.attnum = constraint_def.conkey[1]
      where constraint_def.contype = 'f'
        and constraint_def.confrelid = 'public.location_events'::regclass
        and cardinality(constraint_def.conkey) = 1
    loop
      execute format('select exists(select 1 from %s where %I = $1)', v_fk.table_name, v_fk.column_name)
        into v_linked using p_record_id;
      if v_linked then
        return 'linked_record:' || v_fk.table_name::text;
      end if;
    end loop;
  end if;
  return null;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."patrol_source_correction_dependency_hold"(p_provider_organization_id uuid, p_client_organization_id uuid, p_kind text, p_record_id uuid, p_external_ref text, p_batch_id uuid, p_service_date_unchanged boolean) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."patrol_source_correction_dependency_hold"(p_provider_organization_id uuid, p_client_organization_id uuid, p_kind text, p_record_id uuid, p_external_ref text, p_batch_id uuid, p_service_date_unchanged boolean) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."patrol_source_event_dependency_hold"(p_provider_organization_id uuid, p_client_organization_id uuid, p_event_id uuid, p_external_ref text, p_batch_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_fk record;
  v_linked boolean;
begin
  if exists (
    select 1 from public.file_import_finance_cost_rows cost_row
    join public.finance_service_costs cost on cost.id = cost_row.finance_service_cost_id
    where cost_row.client_organization_id = p_client_organization_id
      and cost_row.evidence_external_ref = p_external_ref
      and (cost.invoice_line_item_id is not null or cost.invoiced_at is not null)
  ) then
    return 'invoiced_record';
  end if;
  if exists (
    select 1 from public.file_import_finance_cost_rows cost_row
    where cost_row.client_organization_id = p_client_organization_id
      and cost_row.evidence_external_ref = p_external_ref
  ) then
    return 'finance_cost_linked';
  end if;
  if exists (
    select 1 from public.file_import_row_proposals proposal
    where proposal.organization_id = p_provider_organization_id
      and proposal.source_record_key = p_external_ref
      and proposal.batch_id <> p_batch_id
      and proposal.status in ('proposed', 'approved')
  ) then
    return 'dependent_proposal_review_required';
  end if;
  for v_fk in
    select constraint_def.conrelid::regclass as table_name, attribute.attname as column_name
    from pg_constraint constraint_def
    join pg_attribute attribute
      on attribute.attrelid = constraint_def.conrelid and attribute.attnum = constraint_def.conkey[1]
    where constraint_def.contype = 'f'
      and constraint_def.confrelid = 'public.location_events'::regclass
      and cardinality(constraint_def.conkey) = 1
  loop
    execute format('select exists(select 1 from %s where %I = $1)', v_fk.table_name, v_fk.column_name)
      into v_linked using p_event_id;
    if v_linked then
      return 'linked_record:' || v_fk.table_name::text;
    end if;
  end loop;
  return null;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."patrol_source_event_dependency_hold"(p_provider_organization_id uuid, p_client_organization_id uuid, p_event_id uuid, p_external_ref text, p_batch_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."patrol_source_event_dependency_hold"(p_provider_organization_id uuid, p_client_organization_id uuid, p_event_id uuid, p_external_ref text, p_batch_id uuid) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."patrol_source_numeric_text_equal"(p_left jsonb, p_right jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
begin
  if p_left is null or p_right is null then
    return false;
  end if;
  if jsonb_typeof(p_left) not in ('string', 'number') or jsonb_typeof(p_right) not in ('string', 'number')
     or (p_left#>>'{}') !~ '^-?[0-9]+(\.[0-9]+)?$' or (p_right#>>'{}') !~ '^-?[0-9]+(\.[0-9]+)?$' then
    return false;
  end if;
  return abs((p_left#>>'{}')::numeric - (p_right#>>'{}')::numeric) < 0.000000001;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."patrol_source_numeric_text_equal"(p_left jsonb, p_right jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."patrol_source_numeric_text_equal"(p_left jsonb, p_right jsonb) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."patrol_source_record_state"(p_kind text, p_record_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case p_kind
    when 'event' then (
      select jsonb_build_object(
        'occurred_at', to_char(event.occurred_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
        'zone_id', event.zone_id,
        'site_id', event.client_site_id,
        'officer_id', event.observed_entity_id,
        'event_type', event.event_type,
        'status', event.status,
        'observed_entity_type', event.observed_entity_type,
        'distance_km', event.distance_km,
        'payload', coalesce(event.payload, '{}'::jsonb)
      )
      from public.location_events event where event.id = p_record_id
    )
    when 'observation' then (
      select jsonb_build_object(
        'occurred_at', to_char(observation.observed_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
        'zone_id', observation.zone_id,
        'site_id', observation.site_id,
        'officer_id', observation.officer_id,
        'plate', upper(observation.plate_number),
        'officer_notes', observation.officer_notes,
        'distance_km', observation.distance_km,
        'payload', coalesce(observation.external_refs->'import', '{}'::jsonb)
      )
      from public.observations observation where observation.id = p_record_id
    )
  end;
$function$;
REVOKE ALL ON FUNCTION "public"."patrol_source_record_state"(p_kind text, p_record_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."patrol_source_record_state"(p_kind text, p_record_id uuid) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."patrol_source_state_diff"(p_before jsonb, p_after jsonb)
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select coalesce(array_agg(field order by field), '{}'::text[])
  from (
    select key as field
    from (select jsonb_object_keys(coalesce(p_before, '{}'::jsonb) || coalesce(p_after, '{}'::jsonb)) as key) keys
    where key <> 'payload' and p_before->key is distinct from p_after->key
    union all
    select 'payload.' || key
    from (
      select jsonb_object_keys(coalesce(p_before->'payload', '{}'::jsonb) || coalesce(p_after->'payload', '{}'::jsonb)) as key
    ) payload_keys
    where coalesce(p_before->'payload'->key, 'null'::jsonb) is distinct from coalesce(p_after->'payload'->key, 'null'::jsonb)
  ) changed;
$function$;
REVOKE ALL ON FUNCTION "public"."patrol_source_state_diff"(p_before jsonb, p_after jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."patrol_source_state_diff"(p_before jsonb, p_after jsonb) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."patrol_source_sync_batch"(p_batch_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid)
 RETURNS file_import_batches
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_batch public.file_import_batches%rowtype;
  v_profile public.import_source_profiles%rowtype;
begin
  select * into v_batch from public.file_import_batches where id = p_batch_id for update;
  if not found or v_batch.organization_id <> p_provider_organization_id or v_batch.status <> 'staging' then
    raise exception 'Open provider import batch required';
  end if;
  if v_batch.manifest_json->>'target_client_organization_id' is distinct from p_client_organization_id::text then
    raise exception 'Import batch client mismatch';
  end if;
  select * into v_profile from public.import_source_profiles
  where organization_id = p_provider_organization_id
    and profile_code = v_batch.manifest_json->>'source_profile'
    and active;
  if not found or v_profile.import_actor_id is null or v_profile.import_actor_id <> auth.uid()
     or v_batch.created_by <> auth.uid() then
    raise exception 'Configured tenant import identity required';
  end if;
  if not public.is_tenant_import_admin(p_provider_organization_id) then
    raise exception 'Tenant import administrator required';
  end if;
  if v_batch.source_sha256 is null or coalesce(v_batch.manifest_json->>'derivative_sha256', '') !~ '^[a-f0-9]{64}$' then
    raise exception 'Import batch provenance is incomplete';
  end if;
  if not exists (
    select 1 from public.service_agreements agreement
    join public.service_agreement_modules module
      on module.service_agreement_id = agreement.id and module.module_key = 'patrol' and module.enabled
    where agreement.provider_organization_id = p_provider_organization_id
      and agreement.client_organization_id = p_client_organization_id
      and agreement.agreement_type = 'operational'
      and (agreement.starts_on is null or agreement.starts_on <= current_date)
      and (agreement.ends_on is null or agreement.ends_on >= current_date)
  ) then
    raise exception 'Active contracted patrol module required';
  end if;
  return v_batch;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."patrol_source_sync_batch"(p_batch_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."patrol_source_sync_batch"(p_batch_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."patrol_window_bounds"(p_shift_date date, p_window_start time without time zone, p_window_end time without time zone, p_shift_start timestamp with time zone, p_shift_end timestamp with time zone)
 RETURNS TABLE(window_open timestamp with time zone, window_close timestamp with time zone)
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  v_open timestamptz;
  v_close timestamptz;
BEGIN
  IF p_window_start IS NULL THEN
    RETURN QUERY SELECT NULL::timestamptz, NULL::timestamptz;
    RETURN;
  END IF;
  v_open := (p_shift_date + p_window_start) AT TIME ZONE 'Pacific/Auckland';
  v_close := CASE WHEN p_window_end IS NOT NULL THEN (p_shift_date + p_window_end) AT TIME ZONE 'Pacific/Auckland' END;
  -- A window that "ends" before it starts crosses midnight (e.g. 22:00–06:00).
  IF v_close IS NOT NULL AND v_close <= v_open THEN v_close := v_close + interval '1 day'; END IF;
  -- Last night's window may still be running when a shift starts after midnight.
  IF p_shift_start IS NOT NULL AND p_shift_end IS NOT NULL AND v_close IS NOT NULL
     AND NOT (v_open < p_shift_end AND p_shift_start < v_close)
     AND (v_open - interval '1 day') < p_shift_end AND p_shift_start < (v_close - interval '1 day') THEN
    v_open := v_open - interval '1 day';
    v_close := v_close - interval '1 day';
  END IF;
  RETURN QUERY SELECT v_open, v_close;
END;
$function$;
COMMENT ON FUNCTION "public"."patrol_window_bounds"(p_shift_date date, p_window_start time without time zone, p_window_end time without time zone, p_shift_start timestamp with time zone, p_shift_end timestamp with time zone) IS 'The contracted patrol window for a shift, as timestamps: anchored on the shift date, extended past midnight when the window crosses it, and anchored on the previous day when only last night''s window overlaps a shift that starts after midnight. Null window_start = any time of day.';
REVOKE ALL ON FUNCTION "public"."patrol_window_bounds"(p_shift_date date, p_window_start time without time zone, p_window_end time without time zone, p_shift_start timestamp with time zone, p_shift_end timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."patrol_window_bounds"(p_shift_date date, p_window_start time without time zone, p_window_end time without time zone, p_shift_start timestamp with time zone, p_shift_end timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."patrol_window_bounds"(p_shift_date date, p_window_start time without time zone, p_window_end time without time zone, p_shift_start timestamp with time zone, p_shift_end timestamp with time zone) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."patrol_window_bounds"(p_shift_date date, p_window_start time without time zone, p_window_end time without time zone, p_shift_start timestamp with time zone, p_shift_end timestamp with time zone) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."pause_cctv_inference_claims"(p_holder text, p_reason text, p_seconds integer)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_until timestamptz;
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' AND session_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;
  IF p_holder IS NULL OR p_holder !~ '^[a-z0-9][a-z0-9:._-]{0,79}$' THEN
    RAISE EXCEPTION 'A valid pause holder is required';
  END IF;
  IF p_reason IS NULL OR char_length(btrim(p_reason)) NOT BETWEEN 1 AND 300 THEN
    RAISE EXCEPTION 'A pause reason of at most 300 characters is required';
  END IF;
  IF p_seconds IS NULL OR p_seconds NOT BETWEEN 60 AND 7200 THEN
    RAISE EXCEPTION 'Pause duration must be between 60 and 7200 seconds';
  END IF;

  -- Waits for claims already in flight to commit; claims that start afterwards see this pause.
  PERFORM pg_advisory_xact_lock(hashtextextended('public.cctv_inference_claim_gate', 0));

  INSERT INTO public.cctv_inference_claim_pauses AS p (holder, reason, paused_until)
  VALUES (p_holder, btrim(p_reason), clock_timestamp() + make_interval(secs => p_seconds))
  ON CONFLICT (holder) DO UPDATE
     SET reason = EXCLUDED.reason, paused_until = EXCLUDED.paused_until, created_at = clock_timestamp()
  RETURNING p.paused_until INTO v_until;
  RETURN v_until;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."pause_cctv_inference_claims"(p_holder text, p_reason text, p_seconds integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."pause_cctv_inference_claims"(p_holder text, p_reason text, p_seconds integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."pause_cctv_inference_claims"(p_holder text, p_reason text, p_seconds integer) TO "service_role";

