CREATE OR REPLACE FUNCTION "public"."person_document_upload_allowed"(p_path text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT CASE WHEN p_path ~ '^[0-9a-f-]{36}/person/[0-9a-f-]{36}/[0-9a-f-]{36}/source$'
    AND split_part(p_path, '/', 1) ~ '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
    AND split_part(p_path, '/', 3) ~ '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
    AND split_part(p_path, '/', 4) ~ '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
    THEN public.person_record_admin_allowed(split_part(p_path, '/', 1)::uuid, split_part(p_path, '/', 3)::uuid)
    ELSE false END
$function$;
REVOKE ALL ON FUNCTION "public"."person_document_upload_allowed"(p_path text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."person_document_upload_allowed"(p_path text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."person_document_upload_allowed"(p_path text) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."person_document_upload_allowed"(p_path text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."person_name_extends"(p_recorded text, p_full text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  WITH parts AS (
    SELECT public.person_name_parts(p_recorded) AS recorded, public.person_name_parts(p_full) AS full_name
  )
  SELECT cardinality(recorded) > 0 AND cardinality(full_name) > cardinality(recorded)
    AND full_name[cardinality(full_name) - cardinality(recorded) + 1 : cardinality(full_name)] = recorded
  FROM parts
$function$;
COMMENT ON FUNCTION "public"."person_name_extends"(p_recorded text, p_full text) IS 'True when the recorded name''s parts are the trailing parts of a longer full name (Smith -> Jane Smith). Used to add proven given names to a surname-only person; never matches equal or unrelated names, or a longer surname (Jones -> Jane Smith-Jones).';
REVOKE ALL ON FUNCTION "public"."person_name_extends"(p_recorded text, p_full text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."person_name_extends"(p_recorded text, p_full text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."person_name_extends"(p_recorded text, p_full text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."person_name_extends"(p_recorded text, p_full text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."person_name_parts"(p_name text)
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  SELECT coalesce(array_agg(parts.part ORDER BY parts.ord), '{}'::text[])
  FROM (
    SELECT regexp_replace(lower(listed.token), '[^a-z0-9]+', '', 'g') AS part, listed.ord
    FROM unnest(regexp_split_to_array(trim(coalesce(p_name, '')), '\s+')) WITH ORDINALITY AS listed(token, ord)
  ) parts
  WHERE parts.part <> ''
$function$;
COMMENT ON FUNCTION "public"."person_name_parts"(p_name text) IS 'The whitespace-separated parts of a person''s name, each compared as public.normalize_person_name does (O''Neill -> {oneill}; Mary-Jane Smith -> {maryjane, smith}). A punctuated or accented single name stays one part.';
REVOKE ALL ON FUNCTION "public"."person_name_parts"(p_name text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."person_name_parts"(p_name text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."person_name_parts"(p_name text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."person_name_parts"(p_name text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."person_permit_compare_value"(p_field text, p_value jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  SELECT CASE
    WHEN p_value IS NULL OR jsonb_typeof(p_value) = 'null' THEN NULL
    WHEN jsonb_typeof(p_value) = 'array' THEN coalesce((
      SELECT jsonb_agg(DISTINCT entries.words ORDER BY entries.words)
      FROM (
        SELECT nullif(trim(regexp_replace(lower(listed.entry), '[^[:alnum:]]+', ' ', 'g')), '') AS words
        FROM jsonb_array_elements_text(p_value) AS listed(entry)
      ) entries
      WHERE entries.words IS NOT NULL), '[]'::jsonb)
    WHEN jsonb_typeof(p_value) <> 'string' THEN p_value
    WHEN p_field = 'contact_email' THEN to_jsonb(lower(trim(p_value #>> '{}')))
    WHEN p_field = 'contact_phone' THEN to_jsonb(regexp_replace(p_value #>> '{}', '[^0-9]+', '', 'g'))
    WHEN p_field = 'firearm_licence_number' THEN to_jsonb(upper(regexp_replace(p_value #>> '{}', '[^[:alnum:]]+', '', 'g')))
    WHEN p_field IN ('date_from', 'date_to') THEN p_value
    ELSE to_jsonb(trim(regexp_replace(lower(p_value #>> '{}'), '[^[:alnum:]]+', ' ', 'g')))
  END
$function$;
COMMENT ON FUNCTION "public"."person_permit_compare_value"(p_field text, p_value jsonb) IS 'The comparable form of one forest/site access permit field, used to report how a recorded permit differs from an extract: lists as a sorted set of entries compared by their words; contact_email lower-cased and trimmed; contact_phone by its digits; firearm_licence_number by its letters and digits; dates, booleans and numbers as recorded; other text by its words, ignoring case and punctuation. A different email address or a different list of areas is never reported as agreeing.';
REVOKE ALL ON FUNCTION "public"."person_permit_compare_value"(p_field text, p_value jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."person_permit_compare_value"(p_field text, p_value jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."person_permit_compare_value"(p_field text, p_value jsonb) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."person_permit_compare_value"(p_field text, p_value jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."person_permit_validity"(p_status text, p_date_from date, p_date_to date, p_window_days integer DEFAULT 30)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  WITH today AS (SELECT (clock_timestamp() AT TIME ZONE 'Pacific/Auckland')::date AS d)
  SELECT CASE
    WHEN p_status IN ('revoked', 'suspended', 'expired') THEN p_status
    WHEN p_date_to IS NOT NULL AND p_date_to < today.d THEN 'expired'
    WHEN p_date_from IS NOT NULL AND p_date_from > today.d THEN 'not_started'
    WHEN p_date_from IS NULL AND p_date_to IS NULL THEN 'dates_not_recorded'
    WHEN p_date_to IS NOT NULL AND p_date_to <= today.d + greatest(coalesce(p_window_days, 30), 0) THEN 'expiring_soon'
    ELSE 'valid'
  END
  FROM today;
$function$;
COMMENT ON FUNCTION "public"."person_permit_validity"(p_status text, p_date_from date, p_date_to date, p_window_days integer) IS 'Plain validity of a forest/site access permit on today''s New Zealand date: revoked, suspended or expired by status; expired after the finishing date (inclusive end); not_started before the start date; dates_not_recorded when neither date is known; expiring_soon inside the window; otherwise valid.';
REVOKE ALL ON FUNCTION "public"."person_permit_validity"(p_status text, p_date_from date, p_date_to date, p_window_days integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."person_permit_validity"(p_status text, p_date_from date, p_date_to date, p_window_days integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."person_permit_validity"(p_status text, p_date_from date, p_date_to date, p_window_days integer) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."person_permit_validity"(p_status text, p_date_from date, p_date_to date, p_window_days integer) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."person_permit_validity"(p_status text, p_date_from date, p_date_to date, p_window_days integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."person_record_admin_allowed"(p_organization_id uuid, p_person_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT auth.uid() IS NOT NULL AND public.is_admin_for_org(p_organization_id) AND EXISTS (
    SELECT 1 FROM public.canonical_people cp
    JOIN public.canonical_person_links link ON link.canonical_person_id = cp.id
    JOIN public.person_records pr ON pr.id = link.source_id AND pr.organization_id = link.organization_id
    WHERE cp.id = p_person_id AND cp.status = 'active'
      AND link.source_table = 'person_records' AND link.organization_id = p_organization_id
  )
$function$;
REVOKE ALL ON FUNCTION "public"."person_record_admin_allowed"(p_organization_id uuid, p_person_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."person_record_admin_allowed"(p_organization_id uuid, p_person_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."person_record_admin_allowed"(p_organization_id uuid, p_person_id uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."place_hazards_check_facet"()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.client_site_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.client_sites s WHERE s.id = NEW.client_site_id AND s.location_id = NEW.location_id
  ) THEN
    RAISE EXCEPTION 'Site does not belong to this place';
  END IF;
  IF NEW.zone_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.location_zones z WHERE z.id = NEW.zone_id AND z.location_id = NEW.location_id
  ) THEN
    RAISE EXCEPTION 'Zone does not belong to this place';
  END IF;
  NEW.updated_at := clock_timestamp();
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."place_hazards_check_facet"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."place_hazards_check_facet"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."place_hazards_check_facet"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."platform_list_subscribers"()
 RETURNS TABLE(organization_id uuid, name text, organization_type text, status text, active boolean, created_at timestamp with time zone, updated_at timestamp with time zone, contact_email text, agreement_id uuid, agreement_starts_on date, agreement_ends_on date, module_keys text[], active_module_count integer, suspended_module_count integer, cancelled_module_count integer, user_count integer, active_user_count integer, master_count integer, last_sign_in_at timestamp with time zone, shifts_30d integer, jobs_30d integer, sites integer, branches integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with owner as (
    select o.id from public.organizations o where o.organization_type = 'owner' and o.active order by o.created_at limit 1
  )
  select
    o.id, o.name, o.organization_type, o.status, o.active, o.created_at, o.updated_at,
    o.contact_email,
    sa.id, sa.starts_on, sa.ends_on,
    coalesce((select array_agg(s.module_key order by s.module_key) from public.org_module_subscriptions s where s.organization_id = o.id and s.status <> 'cancelled'), '{}'::text[]),
    (select count(*)::integer from public.org_module_subscriptions s where s.organization_id = o.id and s.status = 'active'),
    (select count(*)::integer from public.org_module_subscriptions s where s.organization_id = o.id and s.status = 'suspended'),
    (select count(*)::integer from public.org_module_subscriptions s where s.organization_id = o.id and s.status = 'cancelled'),
    (select count(*)::integer from public.user_profiles u where u.organization_id = o.id),
    (select count(*)::integer from public.user_profiles u where u.organization_id = o.id and u.deactivated_at is null),
    (select count(*)::integer from public.user_profiles u where u.organization_id = o.id and u.deactivated_at is null and u.role = 'master'),
    (select max(au.last_sign_in_at) from public.user_profiles u join auth.users au on au.id = u.id where u.organization_id = o.id),
    (select count(*)::integer from public.shifts s where s.organization_id = o.id and s.scheduled_start >= now() - interval '30 days'),
    (select count(*)::integer from public.dispatch_jobs j where j.organization_id = o.id and j.created_at >= now() - interval '30 days'),
    (select count(*)::integer from public.client_sites cs where cs.organization_id = o.id),
    (select count(*)::integer from public.organizations b where b.parent_organization_id = o.id and b.organization_type = 'branch' and b.status <> 'archived')
  from public.organizations o
  cross join owner
  left join lateral (
    select a.id, a.starts_on, a.ends_on from public.service_agreements a
    where a.agreement_type = 'financial' and a.provider_organization_id = owner.id and a.client_organization_id = o.id
    order by (a.ends_on is null or a.ends_on >= current_date) desc, a.created_at desc limit 1
  ) sa on true
  where public.is_grand_master()
    and o.organization_type = 'service_provider'
    and o.parent_organization_id is null
    and o.id <> owner.id
  order by (o.status = 'active') desc, o.name;
$function$;
COMMENT ON FUNCTION "public"."platform_list_subscribers"() IS 'Owner console: subscriber organisations with platform agreement, subscription lines, and aggregate activity (counts and last sign-in only). Returns no rows for anyone but grand_master; exposes no operational or financial records.';
REVOKE ALL ON FUNCTION "public"."platform_list_subscribers"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."platform_list_subscribers"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."platform_list_subscribers"() TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."platform_provision_subscriber"(p_client_request_id uuid, p_organization_id uuid, p_name text, p_module_keys text[], p_starts_on date DEFAULT CURRENT_DATE)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null or not public.is_grand_master() then raise exception 'Iron Eagle platform owner required'; end if;
  return public.platform_provision_subscriber_internal(auth.uid(), p_client_request_id, p_organization_id, p_name, p_module_keys, p_starts_on);
end;
$function$;
COMMENT ON FUNCTION "public"."platform_provision_subscriber"(p_client_request_id uuid, p_organization_id uuid, p_name text, p_module_keys text[], p_starts_on date) IS 'Layer-1 onboarding (owner ruling 2026-09-15): grand_master creates, or reclassifies a dependent-free CRM prospect into, an own-rooted service_provider subscriber; creates the Iron Eagle financial platform agreement; seeds org_module_subscriptions and organization_modules for the purchased modules. Hand off to invite-org for the first master. Idempotent on p_client_request_id.';
REVOKE ALL ON FUNCTION "public"."platform_provision_subscriber"(p_client_request_id uuid, p_organization_id uuid, p_name text, p_module_keys text[], p_starts_on date) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."platform_provision_subscriber"(p_client_request_id uuid, p_organization_id uuid, p_name text, p_module_keys text[], p_starts_on date) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."platform_provision_subscriber_internal"(p_actor uuid, p_client_request_id uuid, p_organization_id uuid, p_name text, p_module_keys text[], p_starts_on date DEFAULT CURRENT_DATE)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_owner uuid;
  v_org public.organizations%rowtype;
  v_name text := nullif(trim(coalesce(p_name, '')), '');
  v_agreement_id uuid;
  v_key text;
  v_unknown text[];
  v_created boolean := false;
begin
  if p_client_request_id is null then raise exception 'client_request_id is required'; end if;
  if p_module_keys is null or cardinality(p_module_keys) = 0 then raise exception 'At least one module key is required'; end if;

  select id into v_owner from public.organizations where organization_type = 'owner' and active order by created_at limit 1;
  if v_owner is null then raise exception 'Platform owner organisation not found'; end if;
  if (select count(*) from public.organizations where organization_type = 'owner' and active) > 1 then
    raise exception 'More than one active owner organisation; refusing to guess the platform owner';
  end if;

  select array_agg(k) into v_unknown
  from unnest(p_module_keys) k
  where not exists (select 1 from public.module_catalog m where m.module_key = k and m.active);
  if v_unknown is not null then raise exception 'Unknown or inactive module key(s): %', array_to_string(v_unknown, ', '); end if;

  -- Idempotency: the same request id returns the same receipt.
  select o.* into v_org from public.organizations o
  where o.client_request_id = p_client_request_id and o.organization_type = 'service_provider' and o.parent_organization_id is null;
  if found then
    select id into v_agreement_id from public.service_agreements
    where agreement_type = 'financial' and provider_organization_id = v_owner and client_organization_id = v_org.id
    order by created_at limit 1;
    return jsonb_build_object('organization_id', v_org.id, 'name', v_org.name, 'agreement_id', v_agreement_id, 'created', false, 'module_keys', p_module_keys, 'replayed', true);
  end if;

  if p_organization_id is not null then
    select o.* into v_org from public.organizations o where o.id = p_organization_id for update;
    if not found then raise exception 'Organisation not found'; end if;
    if v_org.organization_type = 'owner' then raise exception 'The platform owner cannot be provisioned as a subscriber'; end if;
    if v_org.organization_type <> 'service_provider' or v_org.parent_organization_id is not null then
      -- Reclassification is only allowed while nothing depends on the row.
      if exists (select 1 from public.user_profiles u where u.organization_id = v_org.id or u.employer_organization_id = v_org.id) then
        raise exception 'Organisation already has users; it cannot be reclassified as a new subscriber';
      end if;
      if exists (select 1 from public.client_sites s where s.client_organization_id = v_org.id) then
        raise exception 'Organisation already owns places; it cannot be reclassified as a new subscriber';
      end if;
      if exists (select 1 from public.service_agreements sa where sa.provider_organization_id = v_org.id or (sa.client_organization_id = v_org.id and sa.agreement_type = 'operational')) then
        raise exception 'Organisation already has service agreements; it cannot be reclassified as a new subscriber';
      end if;
      if exists (select 1 from public.organizations c where c.parent_organization_id = v_org.id) then
        raise exception 'Organisation has child organisations; it cannot be reclassified as a new subscriber';
      end if;
    end if;
    update public.organizations
       set organization_type = 'service_provider',
           parent_organization_id = null,
           active = true,
           status = 'active',
           name = coalesce(v_name, name),
           client_request_id = p_client_request_id,
           account_owner_user_id = null,
           updated_at = now()
     where id = v_org.id
     returning * into v_org;
  else
    if v_name is null or char_length(v_name) > 200 then raise exception 'Organisation name is required and must be 200 characters or fewer'; end if;
    if exists (select 1 from public.organizations o where o.parent_organization_id is null and lower(trim(o.name)) = lower(v_name)) then
      raise exception 'An own-rooted organisation with this name already exists';
    end if;
    insert into public.organizations (name, organization_type, parent_organization_id, active, status, client_request_id)
    values (v_name, 'service_provider', null, true, 'active', p_client_request_id)
    returning * into v_org;
    v_created := true;
  end if;

  select id into v_agreement_id from public.service_agreements
  where agreement_type = 'financial' and provider_organization_id = v_owner and client_organization_id = v_org.id
    and (ends_on is null or ends_on >= current_date)
  order by created_at limit 1;
  if v_agreement_id is null then
    insert into public.service_agreements (provider_organization_id, client_organization_id, name, agreement_type, starts_on, ends_on, enabled_modules, invitation_status)
    values (v_owner, v_org.id, 'Iron Eagle - ' || v_org.name || ' Platform Agreement', 'financial', coalesce(p_starts_on, current_date), null, p_module_keys, 'not_invited')
    returning id into v_agreement_id;
  else
    update public.service_agreements
       set enabled_modules = (select array_agg(distinct k) from unnest(enabled_modules || p_module_keys) k)
     where id = v_agreement_id;
  end if;

  -- Layer-1 subscription lines (what Iron Eagle bills), then operational enablement
  -- in dependency order so tg_enforce_module_dependencies is satisfied.
  for v_key in
    select k from unnest(p_module_keys) k
    order by (exists (select 1 from public.module_dependencies d where d.module_key = k)), k
  loop
    insert into public.org_module_subscriptions (organization_id, module_key, status, started_at, created_by, updated_by)
    values (v_org.id, v_key, 'active', coalesce(p_starts_on, current_date), p_actor, p_actor)
    on conflict (organization_id, module_key) do update
      set status = 'active', ended_at = null, updated_at = now(), updated_by = excluded.updated_by;
    insert into public.organization_modules (organization_id, module_key, enabled)
    values (v_org.id, v_key, true)
    on conflict (organization_id, module_key) do update set enabled = true;
  end loop;

  insert into public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (v_org.id, p_actor, 'platform_subscriber_provisioned', 'organizations', v_org.id,
          jsonb_build_object('created', v_created, 'agreement_id', v_agreement_id, 'module_keys', p_module_keys, 'client_request_id', p_client_request_id, 'owner_organization_id', v_owner));

  return jsonb_build_object('organization_id', v_org.id, 'name', v_org.name, 'agreement_id', v_agreement_id, 'created', v_created, 'module_keys', p_module_keys, 'replayed', false);
end;
$function$;
COMMENT ON FUNCTION "public"."platform_provision_subscriber_internal"(p_actor uuid, p_client_request_id uuid, p_organization_id uuid, p_name text, p_module_keys text[], p_starts_on date) IS 'Definer-only body of platform_provision_subscriber; callable from migrations with an explicit actor. Not granted to any API role.';
REVOKE ALL ON FUNCTION "public"."platform_provision_subscriber_internal"(p_actor uuid, p_client_request_id uuid, p_organization_id uuid, p_name text, p_module_keys text[], p_starts_on date) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."platform_provision_subscriber_internal"(p_actor uuid, p_client_request_id uuid, p_organization_id uuid, p_name text, p_module_keys text[], p_starts_on date) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."platform_set_subscriber_status"(p_organization_id uuid, p_status text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_org public.organizations%rowtype;
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
  v_key text;
  v_restore text[];
  v_affected integer := 0;
begin
  if v_actor is null or not public.is_grand_master() then raise exception 'Iron Eagle platform owner required'; end if;
  if p_status not in ('active', 'suspended', 'cancelled') then raise exception 'Unsupported subscriber status'; end if;
  select * into v_org from public.organizations where id = p_organization_id for update;
  if not found or v_org.organization_type <> 'service_provider' or v_org.parent_organization_id is not null then
    raise exception 'Subscriber organisation not found';
  end if;
  if p_status in ('suspended', 'cancelled') and v_reason is null then raise exception 'A reason is required to suspend or cancel a subscriber'; end if;

  if p_status = 'active' then
    -- Reinstate what was active before the last suspension; fall back to every non-cancelled line.
    select coalesce(array(select jsonb_array_elements_text(al.metadata->'active_modules')), '{}'::text[]) into v_restore
    from public.audit_log al where al.target_id = v_org.id and al.action in ('platform_subscriber_suspended', 'platform_subscriber_cancelled')
    order by al.created_at desc limit 1;
    if v_restore is null or cardinality(v_restore) = 0 then
      select coalesce(array_agg(module_key), '{}'::text[]) into v_restore from public.org_module_subscriptions where organization_id = v_org.id and status <> 'cancelled';
    end if;
    update public.org_module_subscriptions set status = 'active', ended_at = null, updated_at = now(), updated_by = v_actor
     where organization_id = v_org.id and module_key = any(v_restore) and status <> 'active';
    get diagnostics v_affected = row_count;
    for v_key in
      select k from unnest(v_restore) k
      order by (exists (select 1 from public.module_dependencies d where d.module_key = k)), k
    loop
      insert into public.organization_modules (organization_id, module_key, enabled) values (v_org.id, v_key, true)
      on conflict (organization_id, module_key) do update set enabled = true;
    end loop;
    update public.organizations set status = 'active', active = true, updated_at = now() where id = v_org.id returning * into v_org;
    insert into public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
    values (v_org.id, v_actor, 'platform_subscriber_reinstated', 'organizations', v_org.id, jsonb_build_object('reason', v_reason, 'modules_restored', v_restore, 'lines_updated', v_affected));
  else
    select coalesce(array_agg(module_key order by module_key), '{}'::text[]) into v_restore
    from public.org_module_subscriptions where organization_id = v_org.id and status = 'active';
    update public.org_module_subscriptions
       set status = p_status, ended_at = case when p_status = 'cancelled' then current_date else ended_at end, updated_at = now(), updated_by = v_actor
     where organization_id = v_org.id and status = 'active';
    get diagnostics v_affected = row_count;
    for v_key in
      select om.module_key from public.organization_modules om where om.organization_id = v_org.id and om.enabled
      order by (exists (select 1 from public.module_dependencies d where d.depends_on_module_key = om.module_key)), om.module_key
    loop
      update public.organization_modules set enabled = false where organization_id = v_org.id and module_key = v_key;
    end loop;
    update public.organizations set status = case when p_status = 'cancelled' then 'archived' else 'suspended' end, active = (p_status = 'suspended'), updated_at = now()
     where id = v_org.id returning * into v_org;
    insert into public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
    values (v_org.id, v_actor, case when p_status = 'cancelled' then 'platform_subscriber_cancelled' else 'platform_subscriber_suspended' end, 'organizations', v_org.id,
            jsonb_build_object('reason', v_reason, 'active_modules', v_restore, 'lines_updated', v_affected));
  end if;

  return jsonb_build_object('organization_id', v_org.id, 'status', v_org.status, 'active', v_org.active, 'modules', v_restore, 'lines_updated', v_affected);
end;
$function$;
COMMENT ON FUNCTION "public"."platform_set_subscriber_status"(p_organization_id uuid, p_status text, p_reason text) IS 'Owner console: suspend, reinstate, or cancel a subscriber organisation as one audited act — subscription lines and operational module enablement move together; reinstatement restores the lines recorded at suspension. grand_master only; a reason is required to suspend or cancel.';
REVOKE ALL ON FUNCTION "public"."platform_set_subscriber_status"(p_organization_id uuid, p_status text, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."platform_set_subscriber_status"(p_organization_id uuid, p_status text, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."platform_set_subscriber_status"(p_organization_id uuid, p_status text, p_reason text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."post_finance_timesheet_labour_cost"(p_timesheet_id uuid, p_pl_period_id uuid, p_service_agreement_id uuid, p_service_type text DEFAULT NULL::text, p_cost_centre_id uuid DEFAULT NULL::uuid, p_work_unit_id uuid DEFAULT NULL::uuid)
 RETURNS finance_labour_cost_postings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_sheet public.timesheets%rowtype;
  v_period public.finance_pl_periods%rowtype;
  v_agreement public.service_agreements%rowtype;
  v_shift public.shifts%rowtype;
  v_staff public.staff_profiles%rowtype;
  v_posting public.finance_labour_cost_postings%rowtype;
  v_cost public.finance_service_costs%rowtype;
  v_rate record;
  v_location_agreement_id uuid;
  v_location_status text;
  v_module_agreement_id uuid;
  v_module_enabled boolean;
  v_derived_agreement_id uuid;
  v_hours numeric(8,2);
  v_requested_service_type text;
BEGIN
  SELECT organization_id INTO v_org
  FROM public.user_profiles
  WHERE id = v_actor AND deactivated_at IS NULL;

  IF v_org IS NULL OR NOT public.is_admin_for_org(v_org) THEN
    RAISE EXCEPTION 'Active finance administrator required';
  END IF;
  IF p_timesheet_id IS NULL OR p_pl_period_id IS NULL OR p_service_agreement_id IS NULL THEN
    RAISE EXCEPTION 'Timesheet, P&L period, and service agreement are required';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('finance-timesheet-cost:' || p_timesheet_id::text, 0));

  SELECT * INTO v_sheet
  FROM public.timesheets
  WHERE id = p_timesheet_id AND organization_id = v_org
  FOR UPDATE;

  IF NOT FOUND OR v_sheet.status NOT IN ('approved', 'paid') THEN
    RAISE EXCEPTION 'Only approved or paid timesheets can be posted';
  END IF;
  IF v_sheet.shift_id IS NULL THEN
    RAISE EXCEPTION 'Timesheet must identify one governed shift before labour cost can be posted';
  END IF;

  SELECT * INTO v_staff
  FROM public.staff_profiles
  WHERE id = v_sheet.staff_id AND organization_id = v_org;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Staff profile not found in organization';
  END IF;

  SELECT * INTO v_shift
  FROM public.shifts
  WHERE id = v_sheet.shift_id
    AND organization_id = v_org
    AND (officer_user_id = v_staff.id OR officer_user_id = v_staff.user_id);

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Timesheet shift is not available for this staff member';
  END IF;

  IF v_shift.service_agreement_location_id IS NOT NULL THEN
    SELECT service_agreement_id, status
    INTO v_location_agreement_id, v_location_status
    FROM public.service_agreement_locations
    WHERE id = v_shift.service_agreement_location_id;

    IF v_location_agreement_id IS NULL OR v_location_status <> 'active' THEN
      RAISE EXCEPTION 'Shift agreement location is not active';
    END IF;
  END IF;

  IF v_shift.service_agreement_module_id IS NOT NULL THEN
    SELECT service_agreement_id, enabled
    INTO v_module_agreement_id, v_module_enabled
    FROM public.service_agreement_modules
    WHERE id = v_shift.service_agreement_module_id;

    IF v_module_agreement_id IS NULL OR NOT v_module_enabled THEN
      RAISE EXCEPTION 'Shift agreement module is not enabled';
    END IF;
  END IF;

  IF v_location_agreement_id IS NOT NULL
    AND v_module_agreement_id IS NOT NULL
    AND v_location_agreement_id <> v_module_agreement_id
  THEN
    RAISE EXCEPTION 'Shift agreement links do not identify the same agreement';
  END IF;

  v_derived_agreement_id := COALESCE(v_location_agreement_id, v_module_agreement_id);
  IF v_derived_agreement_id IS NULL THEN
    RAISE EXCEPTION 'Shift is not linked to a service agreement';
  END IF;
  IF p_service_agreement_id <> v_derived_agreement_id THEN
    RAISE EXCEPTION 'Service agreement does not match the timesheet shift';
  END IF;

  SELECT * INTO v_agreement
  FROM public.service_agreements
  WHERE id = v_derived_agreement_id
    AND provider_organization_id = v_org
    AND agreement_type = 'operational'
    AND (starts_on IS NULL OR starts_on <= v_sheet.period_start)
    AND (ends_on IS NULL OR ends_on >= v_sheet.period_end);

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Timesheet shift agreement is not active for the work period';
  END IF;

  SELECT * INTO v_period
  FROM public.finance_pl_periods
  WHERE id = p_pl_period_id
    AND organization_id = v_org
    AND status IN ('draft', 'locked')
    AND period_start <= v_sheet.period_start
    AND period_end >= v_sheet.period_end;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'P&L period must be open and contain the timesheet work period';
  END IF;

  IF p_work_unit_id IS NOT NULL AND p_work_unit_id IS DISTINCT FROM v_shift.work_unit_id THEN
    RAISE EXCEPTION 'Work unit does not match the timesheet shift';
  END IF;
  IF p_cost_centre_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.cost_centres
    WHERE id = p_cost_centre_id
      AND organization_id = v_org
      AND active
  ) THEN
    RAISE EXCEPTION 'Cost centre is not active in organization';
  END IF;

  v_requested_service_type := NULLIF(trim(COALESCE(p_service_type, '')), '');
  IF v_requested_service_type IS NOT NULL
    AND v_requested_service_type <> v_shift.service_type
  THEN
    RAISE EXCEPTION 'Service type does not match the timesheet shift';
  END IF;

  SELECT * INTO v_posting
  FROM public.finance_labour_cost_postings
  WHERE timesheet_id = p_timesheet_id;

  IF FOUND THEN
    IF v_posting.pl_period_id <> p_pl_period_id
      OR v_posting.service_agreement_id <> v_derived_agreement_id
    THEN
      RAISE EXCEPTION 'Timesheet labour cost was already posted with different accounting attribution';
    END IF;
    RETURN v_posting;
  END IF;

  v_hours := COALESCE(v_sheet.actual_hours, v_sheet.work_derived_hours, 0);
  IF v_hours <= 0 THEN
    RAISE EXCEPTION 'Timesheet has no positive actual hours';
  END IF;

  SELECT p.rate_rule_id, p.hourly_rate AS amount INTO v_rate FROM public.timesheet_effective_pay(v_sheet.id) p;

  INSERT INTO public.finance_service_costs(
    organization_id, pl_period_id, service_agreement_id, client_organization_id, cost_type,
    cost_centre_id, work_unit_id, shift_id, source_document_type, source_reference,
    quantity, unit_of_measure, unit_cost, total_cost, created_by
  ) VALUES (
    v_org, p_pl_period_id, v_derived_agreement_id, v_agreement.client_organization_id, 'labour',
    p_cost_centre_id, v_shift.work_unit_id, v_sheet.shift_id, 'timesheet', 'timesheet:' || v_sheet.id::text,
    v_hours, 'hours', COALESCE(v_rate.amount, 0), round(v_hours * COALESCE(v_rate.amount, 0), 2), v_actor
  ) RETURNING * INTO v_cost;

  INSERT INTO public.finance_labour_cost_postings(
    organization_id, timesheet_id, finance_service_cost_id, service_agreement_id, pl_period_id,
    staff_id, rate_rule_id, hours, hourly_rate, rate_status, source_snapshot, posted_by
  ) VALUES (
    v_org, v_sheet.id, v_cost.id, v_derived_agreement_id, p_pl_period_id, v_sheet.staff_id,
    v_rate.rate_rule_id, v_hours, COALESCE(v_rate.amount, 0),
    CASE WHEN v_rate.amount IS NULL THEN 'unresolved' ELSE 'resolved' END,
    jsonb_build_object(
      'timesheet_status', v_sheet.status,
      'period_start', v_sheet.period_start,
      'period_end', v_sheet.period_end,
      'actual_hours', v_sheet.actual_hours,
      'work_derived_hours', v_sheet.work_derived_hours,
      'role_code', v_staff.role_code,
      'shift_id', v_shift.id,
      'work_unit_id', v_shift.work_unit_id,
      'service_agreement_id', v_derived_agreement_id,
      'service_type', v_shift.service_type,
      'rate_rule_id', v_rate.rate_rule_id,
      'pay_code_override', v_sheet.pay_code_override, 'pay_override_reason', v_sheet.pay_override_reason, 'hourly_rate', COALESCE(v_rate.amount, 0)
    ),
    v_actor
  ) RETURNING * INTO v_posting;

  INSERT INTO public.audit_log(
    organization_id, actor_user_id, action, target_table, target_id, metadata
  ) VALUES (
    v_org, v_actor, 'finance_timesheet_labour_cost_posted',
    'finance_labour_cost_postings', v_posting.id,
    jsonb_build_object(
      'timesheet_id', v_sheet.id,
      'shift_id', v_shift.id,
      'service_agreement_id', v_derived_agreement_id,
      'pl_period_id', p_pl_period_id,
      'finance_service_cost_id', v_cost.id,
      'hours', v_hours,
      'pay_code_override', v_sheet.pay_code_override, 'pay_override_reason', v_sheet.pay_override_reason, 'hourly_rate', COALESCE(v_rate.amount, 0),
      'rate_status', v_posting.rate_status
    )
  );

  RETURN v_posting;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."post_finance_timesheet_labour_cost"(p_timesheet_id uuid, p_pl_period_id uuid, p_service_agreement_id uuid, p_service_type text, p_cost_centre_id uuid, p_work_unit_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."post_finance_timesheet_labour_cost"(p_timesheet_id uuid, p_pl_period_id uuid, p_service_agreement_id uuid, p_service_type text, p_cost_centre_id uuid, p_work_unit_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."post_finance_timesheet_labour_cost"(p_timesheet_id uuid, p_pl_period_id uuid, p_service_agreement_id uuid, p_service_type text, p_cost_centre_id uuid, p_work_unit_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."post_finance_timesheet_labour_cost"(p_timesheet_id uuid, p_pl_period_id uuid, p_service_agreement_id uuid, p_service_type text, p_cost_centre_id uuid, p_work_unit_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."prepare_cctv_media_upload"(p_import_id uuid, p_sha256 text, p_evidence_kind text, p_storage_path text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_actor uuid:=auth.uid();v_import public.cctv_imports%rowtype;v_evidence public.evidence_items%rowtype;v_claim public.cctv_media_upload_claims%rowtype;v_hash text:=lower(trim(coalesce(p_sha256,'')));v_prefix text;
BEGIN
  SELECT * INTO v_import FROM public.cctv_imports WHERE id=p_import_id FOR UPDATE;
  IF v_import.id IS NULL THEN RAISE EXCEPTION 'CCTV import not found';END IF;
  IF v_actor IS NULL OR NOT public.org_access_allowed(v_import.organization_id) THEN RAISE EXCEPTION 'CCTV import access denied';END IF;
  IF p_evidence_kind NOT IN('video','photo') OR v_hash !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'Valid CCTV media kind and SHA-256 are required';END IF;
  v_prefix:='org/'||v_import.organization_id::text||'/cctv/'||v_import.id::text||'/';
  IF p_storage_path IS NULL OR position(v_prefix in p_storage_path)<>1 THEN RAISE EXCEPTION 'CCTV media must be stored under %',v_prefix;END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(v_import.organization_id::text||':'||p_evidence_kind||':'||v_hash,0));
  SELECT evidence.* INTO v_evidence FROM public.evidence_items evidence
  WHERE evidence.organization_id=v_import.organization_id AND evidence.evidence_kind=p_evidence_kind AND lower(evidence.sha256_hash)=v_hash
  ORDER BY evidence.captured_at,evidence.id LIMIT 1;
  IF v_evidence.id IS NOT NULL THEN
    INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
    VALUES(v_import.organization_id,v_actor,'cctv_media_duplicate_reused','evidence_items',v_evidence.id,jsonb_build_object('requested_import_id',p_import_id,'existing_import_id',v_evidence.cctv_import_id,'evidence_kind',p_evidence_kind,'sha256_prefix',left(v_hash,12)));
    RETURN jsonb_build_object('action','reuse','evidence_item_id',v_evidence.id,'cctv_import_id',v_evidence.cctv_import_id,'storage_path',v_evidence.storage_path,'file_name',v_evidence.metadata->>'file_name');
  END IF;
  SELECT * INTO v_claim FROM public.cctv_media_upload_claims WHERE organization_id=v_import.organization_id AND evidence_kind=p_evidence_kind AND sha256=v_hash FOR UPDATE;
  IF v_claim.id IS NULL THEN
    INSERT INTO public.cctv_media_upload_claims(organization_id,evidence_kind,sha256,cctv_import_id,storage_path,claimed_by)
    VALUES(v_import.organization_id,p_evidence_kind,v_hash,p_import_id,p_storage_path,v_actor) RETURNING * INTO v_claim;
    RETURN jsonb_build_object('action','upload','claim_id',v_claim.id);
  END IF;
  IF v_claim.status='registered' OR v_claim.expires_at<=clock_timestamp() THEN
    UPDATE public.cctv_media_upload_claims SET cctv_import_id=p_import_id,storage_path=p_storage_path,status='claimed',evidence_item_id=NULL,claimed_by=v_actor,claimed_at=clock_timestamp(),expires_at=clock_timestamp()+interval '30 minutes',registered_at=NULL WHERE id=v_claim.id RETURNING * INTO v_claim;
    RETURN jsonb_build_object('action','upload','claim_id',v_claim.id);
  END IF;
  IF v_claim.cctv_import_id=p_import_id AND v_claim.storage_path=p_storage_path AND v_claim.claimed_by=v_actor THEN RETURN jsonb_build_object('action','upload','claim_id',v_claim.id);END IF;
  RETURN jsonb_build_object('action','pending','claim_id',v_claim.id,'retry_after',v_claim.expires_at);
END;
$function$;
COMMENT ON FUNCTION "public"."prepare_cctv_media_upload"(p_import_id uuid, p_sha256 text, p_evidence_kind text, p_storage_path text) IS 'Atomically reuses existing CCTV evidence or reserves an organization/kind/hash before Desktop V2 uploads bytes.';
REVOKE ALL ON FUNCTION "public"."prepare_cctv_media_upload"(p_import_id uuid, p_sha256 text, p_evidence_kind text, p_storage_path text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."prepare_cctv_media_upload"(p_import_id uuid, p_sha256 text, p_evidence_kind text, p_storage_path text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."prepare_cctv_media_upload"(p_import_id uuid, p_sha256 text, p_evidence_kind text, p_storage_path text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."prepare_cctv_media_upload"(p_import_id uuid, p_sha256 text, p_evidence_kind text, p_storage_path text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."prepare_crm_client_invitation"(p_account_organization_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_provider uuid;
  v_account public.organizations%rowtype;
  v_contact public.crm_contacts%rowtype;
  v_agreement public.service_agreements%rowtype;
  v_site_count integer;
  v_zone_count integer;
BEGIN
  SELECT organization_id INTO v_provider FROM public.user_profiles WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_provider IS NULL OR NOT public.is_admin_for_org(v_provider) THEN RAISE EXCEPTION 'Active provider CRM administrator required'; END IF;
  -- prospects before activation, and active clients that still have nobody who can sign in
  SELECT * INTO v_account FROM public.organizations
  WHERE id = p_account_organization_id AND ((status = 'prospect' AND NOT active) OR (status = 'active' AND active)) FOR UPDATE;
  IF NOT FOUND OR NOT public.crm_actor_can_manage_account(v_account.id) THEN RAISE EXCEPTION 'Managed client account not found'; END IF;

  SELECT * INTO v_contact FROM public.crm_contacts WHERE organization_id = v_account.id AND is_primary AND deactivated_at IS NULL ORDER BY updated_at DESC LIMIT 1;
  IF v_contact.email IS NULL AND v_account.contact_email IS NOT NULL THEN
    v_contact.email := lower(trim(v_account.contact_email));
  END IF;
  IF v_contact.email IS NULL THEN RAISE EXCEPTION 'A primary client contact email is required before inviting the client'; END IF;

  SELECT count(*) INTO v_site_count FROM public.client_sites WHERE client_organization_id = v_account.id AND active;
  SELECT count(*) INTO v_zone_count
  FROM public.location_zones zone
  JOIN public.locations location ON location.id = zone.location_id
  WHERE location.organization_id = v_account.id AND zone.is_active;
  IF v_site_count = 0 AND v_zone_count = 0 THEN RAISE EXCEPTION 'Add at least one place (a site address or an area) before inviting the client'; END IF;

  SELECT * INTO v_agreement
  FROM public.service_agreements
  WHERE provider_organization_id = ANY(public.get_descendant_organizations(v_provider)) AND client_organization_id = v_account.id AND agreement_type = 'operational'
    AND (ends_on IS NULL OR ends_on >= current_date)
  ORDER BY CASE WHEN invitation_status = 'accepted' THEN 0 WHEN invitation_status = 'invited' THEN 1 ELSE 2 END, created_at DESC
  LIMIT 1 FOR UPDATE;
  IF NOT FOUND THEN
    -- the branch that manages the account holds the agreement; the actor's own organisation only when the account is parented to it
    INSERT INTO public.service_agreements (provider_organization_id, client_organization_id, name, starts_on, agreement_type, invitation_status, client_portal_access_mode, external_refs)
    VALUES (CASE WHEN v_account.parent_organization_id = ANY(public.get_descendant_organizations(v_provider)) THEN v_account.parent_organization_id ELSE v_provider END,
      v_account.id, v_account.name || ' service agreement', current_date, 'operational', 'not_invited', 'transparency_only', jsonb_build_object('created_for_client_invite', true, 'created_by', v_actor))
    RETURNING * INTO v_agreement;
  END IF;
  IF EXISTS (SELECT 1 FROM public.user_profiles cu WHERE cu.organization_id = v_account.id AND cu.deactivated_at IS NULL) THEN RAISE EXCEPTION 'This client already has a user who can sign in; add more people from their own administrator account'; END IF;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_provider, v_actor, 'crm_client_invitation_prepared', 'service_agreements', v_agreement.id,
    jsonb_build_object('account_organization_id', v_account.id, 'account_status', v_account.status, 'site_count', v_site_count, 'zone_count', v_zone_count, 'contact_email', v_contact.email));
  RETURN jsonb_build_object('account_organization_id', v_account.id, 'agreement_id', v_agreement.id, 'provider_organization_id', v_agreement.provider_organization_id, 'agreement_status', v_agreement.invitation_status, 'email', lower(trim(v_contact.email)), 'display_name', trim(coalesce(v_contact.first_name, '') || ' ' || coalesce(v_contact.last_name, '')), 'site_count', v_site_count, 'zone_count', v_zone_count);
END;
$function$;
REVOKE ALL ON FUNCTION "public"."prepare_crm_client_invitation"(p_account_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."prepare_crm_client_invitation"(p_account_organization_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."prepare_crm_client_invitation"(p_account_organization_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."prepare_crm_client_invitation"(p_account_organization_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."prepare_finance_tax_period"(p_tax_period_id uuid)
 RETURNS finance_tax_periods
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_period public.finance_tax_periods%rowtype;
BEGIN
  SELECT organization_id INTO v_org FROM public.user_profiles WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_org IS NULL OR NOT public.is_admin_for_org(v_org) THEN RAISE EXCEPTION 'Active finance administrator required'; END IF;
  SELECT * INTO v_period FROM public.finance_tax_periods WHERE id = p_tax_period_id AND organization_id = v_org FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Tax period not found in organization'; END IF;
  IF v_period.status NOT IN ('open','prepared') THEN RAISE EXCEPTION 'Tax period cannot be prepared from its current status'; END IF;
  SELECT COALESCE(SUM(CASE WHEN tax_direction = 'output' THEN tax_amount ELSE 0 END), 0),
         COALESCE(SUM(CASE WHEN tax_direction = 'input' THEN tax_amount ELSE 0 END), 0),
         COALESCE(SUM(CASE WHEN tax_direction = 'adjustment' THEN tax_amount ELSE 0 END), 0)
  INTO v_period.output_tax, v_period.input_tax, v_period.adjustments
  FROM public.finance_tax_transactions WHERE tax_period_id = p_tax_period_id AND organization_id = v_org;
  v_period.net_tax_due := v_period.output_tax - v_period.input_tax + v_period.adjustments;
  v_period.status := 'prepared';
  UPDATE public.finance_tax_periods SET output_tax = v_period.output_tax, input_tax = v_period.input_tax, adjustments = v_period.adjustments, net_tax_due = v_period.net_tax_due, status = v_period.status WHERE id = p_tax_period_id RETURNING * INTO v_period;
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_org, v_actor, 'finance_tax_period_prepared', 'finance_tax_periods', v_period.id, jsonb_build_object('output_tax', v_period.output_tax, 'input_tax', v_period.input_tax, 'adjustments', v_period.adjustments, 'net_tax_due', v_period.net_tax_due));
  RETURN v_period;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."prepare_finance_tax_period"(p_tax_period_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."prepare_finance_tax_period"(p_tax_period_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."prepare_finance_tax_period"(p_tax_period_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."prepare_finance_tax_period"(p_tax_period_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."prepare_nz_payday_filing_package"(p_payroll_export_batch_id uuid)
 RETURNS finance_payday_filing_packages
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid(); v_org uuid; v_batch public.payroll_export_batches%rowtype; v_package public.finance_payday_filing_packages%rowtype; v_unresolved integer; v_resolved integer;
BEGIN
  SELECT organization_id INTO v_org FROM public.user_profiles WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_org IS NULL OR NOT public.is_admin_for_org(v_org) THEN RAISE EXCEPTION 'Active payroll administrator required'; END IF;
  SELECT * INTO v_batch FROM public.payroll_export_batches WHERE id = p_payroll_export_batch_id AND organization_id = v_org;
  IF NOT FOUND THEN RAISE EXCEPTION 'Payroll export batch not found in organization'; END IF;
  SELECT count(*) FILTER (WHERE rate_status = 'unresolved')::integer, count(*) FILTER (WHERE rate_status = 'resolved')::integer INTO v_unresolved, v_resolved FROM public.finance_labour_cost_postings WHERE organization_id = v_org AND timesheet_id IN (SELECT id FROM public.timesheets WHERE payroll_export_batch_id = p_payroll_export_batch_id);
  INSERT INTO public.finance_payday_filing_packages(organization_id, payroll_export_batch_id, period_from, period_to, timesheet_count, total_hours, resolved_rate_count, unresolved_rate_count, package_summary, created_by)
  VALUES (v_org, v_batch.id, v_batch.period_from, v_batch.period_to, v_batch.timesheet_count, v_batch.total_hours, v_resolved, v_unresolved, jsonb_build_object('handoff_only', true, 'submission_supported', false, 'payday_filing_source', 'approved timesheets', 'unresolved_rate_count', v_unresolved, 'provider_action', 'Import into an approved NZ payroll provider and review before IRD submission'), v_actor)
  ON CONFLICT (payroll_export_batch_id) DO UPDATE SET total_hours = EXCLUDED.total_hours, resolved_rate_count = EXCLUDED.resolved_rate_count, unresolved_rate_count = EXCLUDED.unresolved_rate_count, package_summary = EXCLUDED.package_summary
  RETURNING * INTO v_package;
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata) VALUES (v_org, v_actor, 'nz_payday_filing_package_prepared', 'finance_payday_filing_packages', v_package.id, jsonb_build_object('payroll_export_batch_id', v_batch.id, 'handoff_only', true, 'submission_supported', false));
  RETURN v_package;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."prepare_nz_payday_filing_package"(p_payroll_export_batch_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."prepare_nz_payday_filing_package"(p_payroll_export_batch_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."prepare_nz_payday_filing_package"(p_payroll_export_batch_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."prepare_nz_payday_filing_package"(p_payroll_export_batch_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."prepare_provisional_tax_scenario"(p_pl_period_id uuid, p_tax_year integer, p_estimated_taxable_profit numeric, p_tax_rate_pct numeric, p_method text DEFAULT 'scenario_only'::text)
 RETURNS finance_provisional_tax_plans
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid(); v_org uuid; v_period public.finance_pl_periods%rowtype; v_source public.bob_nz_finance_sources%rowtype; v_plan public.finance_provisional_tax_plans%rowtype;
BEGIN
  SELECT organization_id INTO v_org FROM public.user_profiles WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_org IS NULL OR NOT public.is_admin_for_org(v_org) THEN RAISE EXCEPTION 'Active finance administrator required'; END IF;
  SELECT * INTO v_period FROM public.finance_pl_periods WHERE id = p_pl_period_id AND organization_id = v_org;
  IF NOT FOUND THEN RAISE EXCEPTION 'P&L period not found in organization'; END IF;
  SELECT * INTO v_source FROM public.bob_nz_finance_sources WHERE source_key = 'ird-provisional-tax' AND status = 'active' AND last_verified_on IS NOT NULL AND (review_due_on IS NULL OR review_due_on >= CURRENT_DATE);
  IF NOT FOUND THEN RAISE EXCEPTION 'Current provisional-tax source verification is required'; END IF;
  IF p_estimated_taxable_profit IS NULL OR p_estimated_taxable_profit < 0 OR p_tax_rate_pct IS NULL OR p_tax_rate_pct < 0 OR p_tax_rate_pct > 100 THEN RAISE EXCEPTION 'Tax scenario inputs are invalid'; END IF;
  IF p_method NOT IN ('scenario_only','standard_estimate','accountant_provided') THEN RAISE EXCEPTION 'Unsupported provisional-tax method'; END IF;
  INSERT INTO public.finance_provisional_tax_plans(organization_id, pl_period_id, tax_year, method, estimated_taxable_profit, tax_rate_pct, estimated_income_tax, estimated_provisional_amount, status, assumptions, created_by)
  VALUES (v_org, p_pl_period_id, p_tax_year, p_method, p_estimated_taxable_profit, p_tax_rate_pct, round(p_estimated_taxable_profit * p_tax_rate_pct / 100, 2), round(p_estimated_taxable_profit * p_tax_rate_pct / 100, 2), CASE WHEN p_method = 'accountant_provided' THEN 'awaiting_accountant' ELSE 'draft' END, jsonb_build_object('management_scenario_only', p_method = 'scenario_only', 'source_key', v_source.source_key, 'source_last_verified_on', v_source.last_verified_on, 'not_an_ird_calculation', true, 'not_a_payment_instruction', true), v_actor)
  RETURNING * INTO v_plan;
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata) VALUES (v_org, v_actor, 'provisional_tax_scenario_prepared', 'finance_provisional_tax_plans', v_plan.id, jsonb_build_object('tax_year', p_tax_year, 'method', p_method, 'estimated_taxable_profit', p_estimated_taxable_profit, 'tax_rate_pct', p_tax_rate_pct));
  RETURN v_plan;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."prepare_provisional_tax_scenario"(p_pl_period_id uuid, p_tax_year integer, p_estimated_taxable_profit numeric, p_tax_rate_pct numeric, p_method text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."prepare_provisional_tax_scenario"(p_pl_period_id uuid, p_tax_year integer, p_estimated_taxable_profit numeric, p_tax_rate_pct numeric, p_method text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."prepare_provisional_tax_scenario"(p_pl_period_id uuid, p_tax_year integer, p_estimated_taxable_profit numeric, p_tax_rate_pct numeric, p_method text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."prepare_provisional_tax_scenario"(p_pl_period_id uuid, p_tax_year integer, p_estimated_taxable_profit numeric, p_tax_rate_pct numeric, p_method text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."preserve_scan_geofence_context"()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
	if old.geofence_context<>'{}'::jsonb and new.geofence_context is distinct from old.geofence_context then raise exception 'Captured geofence context is immutable';end if;
	return new;
end;$function$;
REVOKE ALL ON FUNCTION "public"."preserve_scan_geofence_context"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."preserve_scan_geofence_context"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."preserve_scan_geofence_context"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."prevent_duplicate_cctv_media_hash"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.evidence_kind NOT IN('video','photo') OR NEW.sha256_hash IS NULL THEN RETURN NEW;END IF;
  NEW.sha256_hash:=lower(trim(NEW.sha256_hash));
  IF NEW.sha256_hash !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'CCTV media SHA-256 must be lowercase hexadecimal';END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(NEW.organization_id::text||':'||NEW.evidence_kind||':'||NEW.sha256_hash,0));
  IF EXISTS(SELECT 1 FROM public.evidence_items evidence WHERE evidence.organization_id=NEW.organization_id AND evidence.evidence_kind=NEW.evidence_kind AND lower(evidence.sha256_hash)=NEW.sha256_hash AND evidence.id<>NEW.id) THEN RAISE EXCEPTION 'This CCTV media is already registered in FCM';END IF;
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."prevent_duplicate_cctv_media_hash"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."prevent_duplicate_cctv_media_hash"() TO "postgres";

