CREATE OR REPLACE FUNCTION "public"."raise_scoped_person_interest_flag"(p_organization_id uuid, p_client_request_id uuid, p_canonical_person_id uuid, p_alert_level text, p_reason text)
 RETURNS entity_flags
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
	v_actor uuid := auth.uid();
	v_reason text := nullif(trim(coalesce(p_reason, '')), '');
	v_flag public.entity_flags%rowtype;
BEGIN
	IF p_client_request_id IS NULL THEN RAISE EXCEPTION 'client_request_id is required'; END IF;
	IF v_actor IS NULL OR NOT private.rnm_admin_for_organization(p_organization_id) THEN
		RAISE EXCEPTION 'R&M administrator access to this organization is required';
	END IF;
	SELECT * INTO v_flag
	FROM public.entity_flags
	WHERE organization_id = p_organization_id
		AND client_request_id = p_client_request_id;
	IF FOUND THEN
		IF v_flag.entity_type <> 'person'
			OR v_flag.entity_id <> p_canonical_person_id
			OR v_flag.flag_type <> 'poi'
			OR v_flag.hazard_class IS NOT NULL THEN
			RAISE EXCEPTION 'client_request_id was already used for a different flag';
		END IF;
		RETURN v_flag;
	END IF;
	IF p_alert_level IS NULL OR p_alert_level NOT IN ('low', 'medium', 'high', 'critical') THEN
		RAISE EXCEPTION 'Severity must be low, medium, high or critical';
	END IF;
	IF v_reason IS NULL OR length(v_reason) < 5 THEN RAISE EXCEPTION 'A reason and supporting basis of at least 5 characters is required'; END IF;
	IF NOT EXISTS (
		SELECT 1
		FROM public.canonical_person_links cpl
		JOIN public.person_records pr
			ON pr.id = cpl.source_id
			AND pr.organization_id = cpl.organization_id
			AND pr.review_state = 'verified'
		JOIN public.canonical_people cp
			ON cp.id = cpl.canonical_person_id
			AND cp.review_state = 'verified'
			AND cp.status = 'active'
		WHERE cpl.organization_id = p_organization_id
			AND cpl.source_table = 'person_records'
			AND cpl.canonical_person_id = p_canonical_person_id
	) THEN RAISE EXCEPTION 'Select a verified person record with a verified canonical identity in this organization'; END IF;

	PERFORM 1 FROM public.canonical_people cp
	WHERE cp.id = p_canonical_person_id
	FOR UPDATE;
	IF EXISTS (
		SELECT 1 FROM public.entity_flags
		WHERE organization_id = p_organization_id
			AND entity_type = 'person'
			AND entity_id = p_canonical_person_id
			AND flag_type = 'poi'
			AND active
			AND hazard_class IS NULL
	) THEN RAISE EXCEPTION 'An active person-of-interest flag already exists for this organization'; END IF;

	INSERT INTO public.entity_flags (
		organization_id, entity_type, entity_id, flag_type, alert_level, reason,
		hazard_class, active, raised_by, client_request_id
	) VALUES (
		p_organization_id, 'person', p_canonical_person_id, 'poi', p_alert_level,
		v_reason, NULL, true, v_actor, p_client_request_id
	)
	RETURNING * INTO v_flag;

	INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
	VALUES (
		p_organization_id, v_actor, 'entity_flag_raised', 'entity_flags', v_flag.id,
		jsonb_build_object(
			'entity_type', v_flag.entity_type,
			'entity_id', v_flag.entity_id,
			'flag_type', v_flag.flag_type,
			'alert_level', v_flag.alert_level,
			'client_request_id', p_client_request_id
		)
	);
	RETURN v_flag;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."raise_scoped_person_interest_flag"(p_organization_id uuid, p_client_request_id uuid, p_canonical_person_id uuid, p_alert_level text, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."raise_scoped_person_interest_flag"(p_organization_id uuid, p_client_request_id uuid, p_canonical_person_id uuid, p_alert_level text, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."raise_scoped_person_interest_flag"(p_organization_id uuid, p_client_request_id uuid, p_canonical_person_id uuid, p_alert_level text, p_reason text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."read_person_permits_fieldwork"(p_plate text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, organization_id uuid, client_organization_id uuid, canonical_person_id uuid, holder_name text, permit_number text, permit_type text, applicant_type text, company_name text, contact_email text, contact_phone text, address_text text, forest_areas text[], activities text[], hunting_season text, date_from date, date_to date, firearm_confirm boolean, firearm_licence_valid boolean, chainsaw_safety_equipment boolean, keys_issued boolean, conditions text, status text, compliance_checked_at timestamp with time zone, compliance_source text, vehicle_plates text[], validity_state text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT pp.id, pp.organization_id, pp.client_organization_id, pp.canonical_person_id,
    cp.display_name, pp.permit_number, pp.permit_type, pp.applicant_type, pp.company_name,
    CASE WHEN public.can_access_person_contacts(pp.organization_id) THEN pp.contact_email END,
    CASE WHEN public.can_access_person_contacts(pp.organization_id) THEN pp.contact_phone END,
    CASE WHEN public.can_access_person_contacts(pp.organization_id) THEN pp.address_text END,
    pp.forest_areas, pp.activities, pp.hunting_season, pp.date_from, pp.date_to,
    pp.firearm_confirm, pp.firearm_licence_valid, pp.chainsaw_safety_equipment, pp.keys_issued,
    pp.conditions, pp.status, pp.compliance_checked_at, pp.compliance_source,
    (SELECT array_agg(cv.plate_number ORDER BY cv.plate_number)
     FROM public.person_permit_vehicles ppv
     JOIN public.canonical_vehicles cv ON cv.id = ppv.canonical_vehicle_id
     WHERE ppv.permit_id = pp.id),
    public.person_permit_validity(pp.status, pp.date_from, pp.date_to)
  FROM public.person_permits pp
  LEFT JOIN public.canonical_people cp ON cp.id = pp.canonical_person_id
  WHERE (p_plate IS NULL OR pp.id IN (
      SELECT ppv.permit_id
      FROM public.person_permit_vehicles ppv
      JOIN public.canonical_vehicles cv ON cv.id = ppv.canonical_vehicle_id
      WHERE cv.plate_number = public.normalize_plate_number(p_plate)))
    AND public.can_search_people(pp.organization_id);
$function$;
COMMENT ON FUNCTION "public"."read_person_permits_fieldwork"(p_plate text) IS 'Operational permit projection for authorized person-search users; pass p_plate to read only permits listing that plate. Contact fields are null outside contact-detail roles.';
REVOKE ALL ON FUNCTION "public"."read_person_permits_fieldwork"(p_plate text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."read_person_permits_fieldwork"(p_plate text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."read_person_permits_fieldwork"(p_plate text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."read_published_website_posts"(p_slug text DEFAULT NULL::text, p_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT coalesce(jsonb_agg(p.published_content ORDER BY p.published_content->>'published_at' DESC, p.id), '[]'::jsonb)
  FROM (
    SELECT w.id, w.published_content FROM public.website_posts w
    JOIN private.platform_tenancy t ON t.singleton AND t.service_provider_organization_id = w.provider_organization_id
    WHERE w.published_content IS NOT NULL
      AND (p_slug IS NULL OR w.slug = p_slug) AND (p_id IS NULL OR w.id = p_id)
    ORDER BY w.published_content->>'published_at' DESC, w.id LIMIT 100
  ) p
$function$;
COMMENT ON FUNCTION "public"."read_published_website_posts"(p_slug text, p_id uuid) IS 'Server-only read for website-news. Returns published snapshots only; never returns draft text, actor IDs, retry payloads or unpublished images.';
REVOKE ALL ON FUNCTION "public"."read_published_website_posts"(p_slug text, p_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."read_published_website_posts"(p_slug text, p_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."read_published_website_posts"(p_slug text, p_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."reassign_roster_slot"(p_slot_id uuid, p_expected_status text, p_new_staff_id uuid, p_reason text)
 RETURNS TABLE(slot_id uuid, slot_status text, staff_id uuid, shift_id uuid, shift_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_slot public.roster_slots%rowtype;
  v_unit public.roster_work_units%rowtype;
  v_staff public.staff_profiles%rowtype;
  v_old_staff_id uuid;
  v_new_status text;
  v_materialized record;
begin
  select s.* into v_slot
  from public.roster_slots s
  where s.id = p_slot_id
  for update;
  if not found then
    raise exception 'Roster slot not found';
  end if;
  if not public.is_admin_for_org(v_slot.organization_id) then
    raise exception 'Not authorised to reassign this roster slot';
  end if;
  if v_slot.status <> p_expected_status then
    raise exception 'Roster slot changed from expected status % to %', p_expected_status, v_slot.status;
  end if;
  if v_slot.status not in ('draft', 'published', 'accepted', 'declined') then
    raise exception 'This roster slot can no longer be reassigned';
  end if;
  if p_new_staff_id = v_slot.staff_id then
    raise exception 'Select a different staff member';
  end if;
  if nullif(trim(coalesce(p_reason, '')), '') is null then
    raise exception 'Reassignment reason is required';
  end if;

  select u.* into v_unit
  from public.roster_work_units u
  where u.id = v_slot.work_unit_id
    and u.organization_id = v_slot.organization_id
    and u.active;
  if not found then
    raise exception 'Active work unit not found';
  end if;

  select sp.* into v_staff
  from public.staff_profiles sp
  where sp.id = p_new_staff_id and sp.work_ready
    and (
      sp.organization_id = v_slot.organization_id
      or exists (
        select 1
        from public.staff_branch_authorisations sba
        where sba.user_id = sp.user_id
          and sba.branch_org_id = v_slot.organization_id
          and sba.status = 'active'
      )
    );
  if not found then
    raise exception 'Work-ready staff profile required';
  end if;

  v_old_staff_id := v_slot.staff_id;
  v_new_status := case when v_slot.status = 'draft' then 'draft' else 'published' end;

  update public.roster_slots rs
  set staff_id = p_new_staff_id,
      status = v_new_status,
      notes = concat_ws(E'\n', nullif(rs.notes, ''), 'Reassigned: ' || trim(p_reason))
  where rs.id = v_slot.id
  returning rs.* into v_slot;

  if v_unit.work_unit_type in ('patrol', 'static') and v_slot.status <> 'draft' then
    select * into v_materialized
    from public.materialize_roster_slot_core(v_slot.id, v_slot.status);
    v_slot.linked_shift_id := v_materialized.shift_id;
  end if;

  insert into public.audit_log (
    organization_id,
    actor_user_id,
    action,
    target_table,
    target_id,
    metadata
  )
  values (
    v_slot.organization_id,
    v_actor,
    'roster_slot_reassigned',
    'roster_slots',
    v_slot.id,
    jsonb_build_object(
      'work_unit_id', v_unit.id,
      'old_staff_id', v_old_staff_id,
      'new_staff_id', p_new_staff_id,
      'linked_shift_id', v_slot.linked_shift_id,
      'reason', trim(p_reason)
    )
  );

  return query
  select
    v_slot.id,
    v_slot.status,
    v_slot.staff_id,
    v_slot.linked_shift_id,
    (
      select s.status
      from public.shifts s
      where s.id = v_slot.linked_shift_id
    );
end;
$function$;
REVOKE ALL ON FUNCTION "public"."reassign_roster_slot"(p_slot_id uuid, p_expected_status text, p_new_staff_id uuid, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."reassign_roster_slot"(p_slot_id uuid, p_expected_status text, p_new_staff_id uuid, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."reassign_roster_slot"(p_slot_id uuid, p_expected_status text, p_new_staff_id uuid, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."reassign_roster_slot"(p_slot_id uuid, p_expected_status text, p_new_staff_id uuid, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."reconcile_cctv_reviewed_observations"(p_job_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_new public.cctv_entity_observations%rowtype;
  v_reviewed public.cctv_entity_observations%rowtype;
  v_count integer := 0;
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' AND session_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.inference_jobs WHERE id = p_job_id) THEN
    RAISE EXCEPTION 'CCTV inference job is missing';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_job_id::text || ':reconcile-reviewed', 0));
  FOR v_new IN
    SELECT * FROM public.cctv_entity_observations
     WHERE inference_job_id = p_job_id AND review_state = 'unreviewed'
     ORDER BY observed_at, id
  LOOP
    v_reviewed.id := NULL;
    SELECT reviewed.* INTO v_reviewed
      FROM public.cctv_entity_observations reviewed
     WHERE reviewed.id <> v_new.id
       AND reviewed.organization_id = v_new.organization_id
       AND reviewed.evidence_item_id = v_new.evidence_item_id
       AND reviewed.entity_kind = v_new.entity_kind
       AND reviewed.review_state IN ('accepted', 'rejected')
       AND reviewed.observed_at <= coalesce(v_new.observed_to, v_new.observed_at) + interval '2 seconds'
       AND coalesce(reviewed.observed_to, reviewed.observed_at) >= v_new.observed_at - interval '2 seconds'
       AND (
         (v_new.candidate_plate IS NOT NULL AND reviewed.candidate_plate = v_new.candidate_plate)
         OR public.cctv_bbox_iou(reviewed.attributes->'bbox', v_new.attributes->'bbox') >= 0.3
         OR public.cctv_bbox_is_stationary(coalesce(reviewed.attributes->'last_bbox', reviewed.attributes->'bbox'), v_new.attributes->'bbox')
       )
     ORDER BY (v_new.candidate_plate IS NOT NULL AND reviewed.candidate_plate = v_new.candidate_plate) DESC,
              public.cctv_bbox_iou(reviewed.attributes->'bbox', v_new.attributes->'bbox') DESC,
              abs(extract(epoch FROM (reviewed.observed_at - v_new.observed_at))),
              reviewed.reviewed_at DESC NULLS LAST
     LIMIT 1;
    IF v_reviewed.id IS NULL THEN CONTINUE; END IF;
    UPDATE public.cctv_entity_observations
       SET review_state = 'superseded',
           review_notes = 'Reprocessed sighting; the human ' || v_reviewed.review_state || ' decision on observation ' || v_reviewed.id::text || ' stands',
           attributes = attributes || jsonb_build_object(
             'superseded_by_observation_id', v_reviewed.id,
             'human_decision_carried_from', v_reviewed.id,
             'carried_review_state', v_reviewed.review_state),
           portfolio_candidates = '[]'::jsonb,
           thumbnail = NULL
     WHERE id = v_new.id AND review_state = 'unreviewed';
    IF FOUND THEN v_count := v_count + 1; END IF;
  END LOOP;
  RETURN v_count;
END;
$function$;
COMMENT ON FUNCTION "public"."reconcile_cctv_reviewed_observations"(p_job_id uuid) IS 'Service-only, run after each CCTV job writes observations. Supersedes new unreviewed sightings that duplicate an accepted or rejected sighting of the same kind on the same footage (time overlap plus bbox IoU >= 0.3, stationary position, or the same plate). Reviewed rows are never changed.';
REVOKE ALL ON FUNCTION "public"."reconcile_cctv_reviewed_observations"(p_job_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."reconcile_cctv_reviewed_observations"(p_job_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."reconcile_cctv_reviewed_observations"(p_job_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."reconcile_downer_linz_vehicle_log"(p_limit integer DEFAULT 1000)
 RETURNS TABLE(scanned_rows integer, linked_rows integer, unresolved_rows integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_scanned_rows integer;
  v_linked_rows integer;
  v_unresolved_rows integer;
begin
  with candidates as (
    select raw.source_id,
      coalesce(nullif(btrim(raw.normalized_plate), ''), nullif(regexp_replace(upper(coalesce(raw.rego, '')), '[^A-Z0-9]', '', 'g'), '')) as plate
    from public._seed_downer_linz_vehicle_log_raw raw
    where raw.processed_at is null
      and raw.canonical_vehicle_id is null
    order by raw.created_at, raw.source_id
    limit greatest(1, least(coalesce(p_limit, 1000), 5000))
  ), reconciled as (
    select candidate.source_id, vehicle.id as vehicle_id
    from candidates candidate
    left join public.canonical_vehicles vehicle on vehicle.plate_number = candidate.plate
  ), updated as (
    update public._seed_downer_linz_vehicle_log_raw raw
    set canonical_vehicle_id = reconciled.vehicle_id,
      processed_at = now(),
      error = case when reconciled.vehicle_id is null then 'No exact canonical vehicle match' else null end
    from reconciled
    where raw.source_id = reconciled.source_id
    returning reconciled.vehicle_id
  )
  select count(*)::integer,
    count(*) filter (where vehicle_id is not null)::integer,
    count(*) filter (where vehicle_id is null)::integer
  into v_scanned_rows, v_linked_rows, v_unresolved_rows
  from updated;

  return query select v_scanned_rows, v_linked_rows, v_unresolved_rows;
end;
$function$;
COMMENT ON FUNCTION "public"."reconcile_downer_linz_vehicle_log"(p_limit integer) IS 'Service-role staging reconciliation: links Downer/LINZ rows to exact existing canonical vehicles only. Every attempt is marked processed; unmatched rows retain a review reason and it never creates observations or vehicles.';
REVOKE ALL ON FUNCTION "public"."reconcile_downer_linz_vehicle_log"(p_limit integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."reconcile_downer_linz_vehicle_log"(p_limit integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."reconcile_downer_linz_vehicle_log"(p_limit integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_access_control_perception_envelope"(p_access_control_event_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_event public.access_control_events%ROWTYPE;
  v_link public.access_control_event_evidence%ROWTYPE;
  v_evidence public.evidence_items%ROWTYPE;
  v_details jsonb;
  v_confidence real;
  v_authority text;
  v_idempotency_key text;
  v_envelope_id uuid;
  v_recorded integer := 0;
  v_field record;
  v_probe jsonb;
  v_candidate jsonb;
  v_candidate_ordinal integer := 0;
BEGIN
  IF coalesce(auth.jwt()->>'role', '') <> 'service_role'
     AND session_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;

  SELECT * INTO v_event
  FROM public.access_control_events
  WHERE id = p_access_control_event_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Access-control event is missing'; END IF;

  IF coalesce(v_event.recognition_summary->>'status', 'unavailable') <> 'available' THEN
    RETURN jsonb_build_object('recorded', 0, 'replayed', 0, 'skipped', 'recognition_unavailable');
  END IF;

  SELECT * INTO v_link
  FROM public.access_control_event_evidence
  WHERE access_control_event_id = v_event.id
  ORDER BY ordinal, id
  LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('recorded', 0, 'replayed', 0, 'skipped', 'missing_evidence_link');
  END IF;

  SELECT * INTO v_evidence
  FROM public.evidence_items
  WHERE id = v_link.evidence_item_id
    AND organization_id = v_event.organization_id;
  IF NOT FOUND OR lower(coalesce(v_evidence.sha256_hash, '')) !~ '^[0-9a-f]{64}$' THEN
    RETURN jsonb_build_object('recorded', 0, 'replayed', 0, 'skipped', 'missing_source_hash');
  END IF;

  v_confidence := CASE
    WHEN v_event.recognition_summary->>'confidence' ~ '^[0-9]+([.][0-9]+)?$'
      THEN (v_event.recognition_summary->>'confidence')::real
  END;
  IF v_confidence IS NULL OR v_confidence < 0 OR v_confidence > 1 THEN
    RAISE EXCEPTION 'Access-control recognition confidence is invalid';
  END IF;

  v_details := coalesce(v_event.recognition_summary->'details', '{}'::jsonb);
  v_authority := CASE WHEN v_confidence < 0.5 THEN 'insufficient' ELSE 'candidate' END;
  v_idempotency_key :=
    'access-control-photo:' || v_event.id::text || ':v1:' || lower(v_evidence.sha256_hash);

  SELECT id INTO v_envelope_id
  FROM public.perception_evidence_envelopes
  WHERE organization_id = v_event.organization_id
    AND idempotency_key = v_idempotency_key;
  IF FOUND THEN
    RETURN jsonb_build_object('recorded', 0, 'replayed', 1, 'envelope_id', v_envelope_id);
  END IF;

  INSERT INTO public.perception_evidence_envelopes (
    organization_id, schema_version, domain, source_kind, source_sha256,
    evidence_item_id, source_receipt, model_receipt, derivative_receipts,
    status, idempotency_key
  ) VALUES (
    v_event.organization_id, 1, 'access_control_photo', 'image',
    lower(v_evidence.sha256_hash), v_evidence.id,
    jsonb_strip_nulls(jsonb_build_object(
      'access_control_event_id', v_event.id,
      'location_event_id', v_event.location_event_id,
      'site_id', v_event.site_id,
      'zone_id', v_event.zone_id,
      'observed_at', v_event.observed_at,
      'officer_decision_recorded_separately', true,
      'authoritative_source_preserved', true
    )),
    jsonb_strip_nulls(jsonb_build_object(
      'classifier', v_event.recognition_summary->>'classifier',
      'provider', v_event.recognition_summary->>'provider',
      'model', v_event.recognition_summary->>'model',
      'prompt_version', v_event.recognition_summary->>'prompt_version',
      'machine_candidate_discovery_permitted', true,
      'machine_identity_confirmation_permitted', false,
      'machine_access_decision_permitted', false
    )),
    jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
      'evidence_item_id', v_evidence.id,
      'original_path', v_evidence.metadata->>'original_path',
      'watermarked_path', v_evidence.metadata->>'watermarked_path',
      'original_sha256', v_evidence.metadata->>'raw_sha256',
      'watermarked_sha256', v_evidence.sha256_hash,
      'watermark_service', v_evidence.metadata->>'watermark_service'
    ))),
    'manual_review_required',
    v_idempotency_key
  )
  RETURNING id INTO v_envelope_id;

  FOR v_field IN
    SELECT *
    FROM (
      VALUES
        ('access.subject_kind', 'classification', nullif(trim(v_details->>'subject_kind'), '')),
        ('access.person_present', 'boolean', CASE
          WHEN jsonb_typeof(v_details->'person_present') = 'boolean'
            THEN v_details->>'person_present'
        END),
        ('access.face_visible', 'boolean', CASE
          WHEN jsonb_typeof(v_details->'face_visible') = 'boolean'
            THEN v_details->>'face_visible'
        END),
        ('access.credential_visible', 'boolean', CASE
          WHEN jsonb_typeof(v_details->'credential_visible') = 'boolean'
            THEN v_details->>'credential_visible'
        END),
        ('access.vehicle_present', 'boolean', CASE
          WHEN jsonb_typeof(v_details->'vehicle_present') = 'boolean'
            THEN v_details->>'vehicle_present'
        END)
    ) AS fields(field_key, value_type, candidate_value)
    WHERE candidate_value IS NOT NULL
  LOOP
    INSERT INTO public.perception_evidence_fields (
      organization_id, envelope_id, field_key, candidate_ordinal, value_type,
      candidate_value, normalized_value, candidate_payload, raw_confidence,
      source_locations, consensus_rule, authority_state, review_required
    ) VALUES (
      v_event.organization_id, v_envelope_id, v_field.field_key, 0,
      v_field.value_type, v_field.candidate_value, lower(v_field.candidate_value),
      jsonb_build_object(
        'source', 'deterministic_recognition',
        'candidate_discovery_permitted', true,
        'identity_confirmation_permitted', false,
        'access_decision_permitted', false
      ),
      v_confidence,
      jsonb_build_array(jsonb_build_object(
        'evidence_item_id', v_evidence.id,
        'storage_path', v_evidence.storage_path
      )),
      'advisory_access_scene_candidate_human_review_required_v1',
      v_authority,
      true
    );
    v_recorded := v_recorded + 1;
  END LOOP;

  FOR v_probe IN
    SELECT value
    FROM jsonb_array_elements(CASE
      WHEN jsonb_typeof(v_event.recognition_summary->'probes') = 'array'
        THEN v_event.recognition_summary->'probes'
      ELSE '[]'::jsonb
    END)
  LOOP
    FOR v_candidate IN
      SELECT value
      FROM jsonb_array_elements(CASE
        WHEN jsonb_typeof(v_probe->'candidates') = 'array'
          THEN v_probe->'candidates'
        ELSE '[]'::jsonb
      END)
    LOOP
      IF nullif(trim(v_candidate->>'display_name'), '') IS NULL
         OR coalesce(v_candidate->>'score', '') !~ '^[0-9]+([.][0-9]+)?$' THEN
        CONTINUE;
      END IF;
      v_candidate_ordinal := v_candidate_ordinal + 1;
      INSERT INTO public.perception_evidence_fields (
        organization_id, envelope_id, field_key, candidate_ordinal, value_type,
        candidate_value, normalized_value, candidate_payload, raw_confidence,
        source_locations, consensus_rule, authority_state, review_required
      ) VALUES (
        v_event.organization_id,
        v_envelope_id,
        CASE
          WHEN v_candidate->>'entity_kind' = 'vehicle'
            THEN 'access.vehicle_match_candidate'
          ELSE 'access.person_match_candidate'
        END,
        v_candidate_ordinal,
        'entity',
        v_candidate->>'display_name',
        lower(v_candidate->>'display_name'),
        jsonb_strip_nulls(jsonb_build_object(
          'candidate_id', v_candidate->>'candidate_id',
          'entity_kind', v_candidate->>'entity_kind',
          'match_kind', v_candidate->>'match_kind',
          'basis', v_candidate->>'basis',
          'person_record_id', v_candidate->>'person_record_id',
          'canonical_vehicle_id', v_candidate->>'canonical_vehicle_id',
          'plate_number', v_candidate->>'plate_number',
          'last_seen_at', v_candidate->>'last_seen_at',
          'candidate_discovery_only', true,
          'identity_confirmation_permitted', false,
          'access_decision_permitted', false
        )),
        (v_candidate->>'score')::real,
        jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
          'evidence_item_id', v_evidence.id,
          'storage_path', v_evidence.storage_path,
          'probe_id', v_probe->>'probe_id',
          'probe_kind', v_probe->>'probe_kind',
          'bbox', v_probe->'bbox'
        ))),
        'ranked_similarity_candidate_human_confirmation_required_v1',
        'candidate',
        true
      );
      v_recorded := v_recorded + 1;
    END LOOP;
  END LOOP;

  IF v_recorded = 0 THEN
    UPDATE public.perception_evidence_envelopes
    SET status = 'failed', updated_at = clock_timestamp()
    WHERE id = v_envelope_id;
    RETURN jsonb_build_object(
      'recorded', 0, 'replayed', 0, 'skipped', 'no_structured_candidates',
      'envelope_id', v_envelope_id
    );
  END IF;

  RETURN jsonb_build_object(
    'recorded', v_recorded, 'replayed', 0, 'envelope_id', v_envelope_id
  );
END;
$function$;
COMMENT ON FUNCTION "public"."record_access_control_perception_envelope"(p_access_control_event_id uuid) IS 'Service-only projection of visible access-scene fields and ranked person/vehicle discovery candidates. Candidates require human confirmation and never grant access.';
REVOKE ALL ON FUNCTION "public"."record_access_control_perception_envelope"(p_access_control_event_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_access_control_perception_envelope"(p_access_control_event_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_access_control_perception_envelope"(p_access_control_event_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_akahu_import"(p_request_id uuid, p_provider_reference text, p_accounts jsonb DEFAULT '[]'::jsonb, p_transactions jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_request public.finance_external_connection_requests%rowtype; v_item jsonb; v_transactions integer := 0;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Provider adapter execution only'; END IF;
  SELECT * INTO v_request FROM public.finance_external_connection_requests WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND OR v_request.provider_name <> 'ANZ' THEN RAISE EXCEPTION 'ANZ connection request not found'; END IF;
  FOR v_item IN SELECT * FROM jsonb_array_elements(COALESCE(p_transactions, '[]'::jsonb)) LOOP
    INSERT INTO public.finance_external_bank_transactions(organization_id, connection_request_id, bank_account_id, external_transaction_id, transaction_date, description, amount, currency_code, direction, raw_summary)
    VALUES (v_request.organization_id, p_request_id, v_request.bank_account_id, COALESCE(v_item->>'id', v_item->>'transaction_id'), NULLIF(v_item->>'date', '')::date, NULLIF(v_item->>'description', ''), NULLIF(v_item->>'amount', '')::numeric, COALESCE(v_item->>'currency', 'NZD'), CASE WHEN (v_item->>'amount')::numeric >= 0 THEN 'credit' ELSE 'debit' END, v_item)
    ON CONFLICT (connection_request_id, external_transaction_id) DO UPDATE SET transaction_date = EXCLUDED.transaction_date, description = EXCLUDED.description, amount = EXCLUDED.amount, currency_code = EXCLUDED.currency_code, raw_summary = EXCLUDED.raw_summary;
    v_transactions := v_transactions + 1;
  END LOOP;
  UPDATE public.finance_external_connection_requests SET status = 'connected', provider_connection_reference = p_provider_reference, connected_at = now(), last_sync_at = now(), last_error = NULL, updated_at = now() WHERE id = p_request_id;
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata) VALUES (v_request.organization_id, NULL, 'anz_transactions_imported', 'finance_external_bank_transactions', p_request_id, jsonb_build_object('transaction_count', v_transactions, 'credentials_stored', false));
  RETURN jsonb_build_object('transaction_count', v_transactions, 'account_count', jsonb_array_length(COALESCE(p_accounts, '[]'::jsonb)));
END;
$function$;
REVOKE ALL ON FUNCTION "public"."record_akahu_import"(p_request_id uuid, p_provider_reference text, p_accounts jsonb, p_transactions jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_akahu_import"(p_request_id uuid, p_provider_reference text, p_accounts jsonb, p_transactions jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_akahu_import"(p_request_id uuid, p_provider_reference text, p_accounts jsonb, p_transactions jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_akahu_personal_check"(p_actor_user_id uuid, p_app_reference text, p_account_count integer, p_account_summary jsonb, p_status text, p_error_category text DEFAULT NULL::text)
 RETURNS finance_akahu_personal_checks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_actor uuid := p_actor_user_id; v_org uuid; v_check public.finance_akahu_personal_checks%rowtype;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Personal Akahu adapter execution only'; END IF;
  SELECT organization_id INTO v_org FROM public.user_profiles WHERE id = v_actor AND role = 'grand_master' AND deactivated_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'Grandmaster test access required'; END IF;
  INSERT INTO public.finance_akahu_personal_checks(organization_id, requested_by, app_reference, account_count, connected_account_summary, status, error_category)
  VALUES (v_org, v_actor, p_app_reference, COALESCE(p_account_count, 0), COALESCE(p_account_summary, '[]'::jsonb), p_status, p_error_category)
  RETURNING * INTO v_check;
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_org, v_actor, 'akahu_personal_test_checked', 'finance_akahu_personal_checks', v_check.id, jsonb_build_object('account_count', v_check.account_count, 'status', v_check.status, 'personal_test_only', true, 'transactions_imported', false));
  RETURN v_check;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."record_akahu_personal_check"(p_actor_user_id uuid, p_app_reference text, p_account_count integer, p_account_summary jsonb, p_status text, p_error_category text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_akahu_personal_check"(p_actor_user_id uuid, p_app_reference text, p_account_count integer, p_account_summary jsonb, p_status text, p_error_category text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_akahu_personal_check"(p_actor_user_id uuid, p_app_reference text, p_account_count integer, p_account_summary jsonb, p_status text, p_error_category text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_alarm_signal"(p_dispatch_job_id uuid, p_received_at timestamp with time zone, p_signal_type text, p_intake_channel text, p_panel_id text DEFAULT NULL::text, p_zone_number text DEFAULT NULL::text, p_zone_name text DEFAULT NULL::text, p_account_number text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS alarm_events
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_job public.dispatch_jobs%rowtype;
  v_event public.alarm_events%rowtype;
  v_place_name text;
BEGIN
  SELECT * INTO v_job FROM public.dispatch_jobs job WHERE job.id = p_dispatch_job_id FOR UPDATE;
  IF NOT FOUND OR NOT public.is_admin_for_org(v_job.organization_id) THEN
    RAISE EXCEPTION 'Dispatch job not found or access denied';
  END IF;
  IF v_job.status IN ('completed', 'cancelled') THEN
    RAISE EXCEPTION 'The alarm cannot be changed on a job that is already %', v_job.status;
  END IF;
  IF p_received_at IS NULL OR p_received_at > now() + interval '5 minutes' THEN
    RAISE EXCEPTION 'The alarm received time cannot be in the future';
  END IF;
  IF p_received_at < v_job.created_at - interval '7 days' THEN
    RAISE EXCEPTION 'The alarm received time is more than 7 days before the job was created';
  END IF;
  IF p_signal_type IS NULL OR p_signal_type NOT IN ('burglary', 'panic_duress', 'fire', 'medical', 'tamper', 'power_fail', 'unknown') THEN
    RAISE EXCEPTION 'Unknown alarm signal type';
  END IF;
  IF p_intake_channel IS NULL OR p_intake_channel NOT IN ('phone', 'email', 'sms', 'radio', 'monitoring_portal', 'other') THEN
    RAISE EXCEPTION 'Unknown alarm intake channel';
  END IF;

  IF v_job.client_site_id IS NOT NULL THEN
    SELECT site.name INTO v_place_name FROM public.client_sites site WHERE site.id = v_job.client_site_id;
  ELSE
    SELECT zone.name INTO v_place_name FROM public.location_zones zone WHERE zone.id = v_job.zone_id;
  END IF;

  INSERT INTO public.alarm_events (
    organization_id, site_id, dispatch_job_id, signal_type, intake_channel,
    panel_id, zone_number, zone_name, account_number, location_name, notes,
    received_at, recorded_by
  ) VALUES (
    v_job.organization_id, v_job.client_site_id, v_job.id, p_signal_type,
    p_intake_channel, nullif(trim(p_panel_id), ''), nullif(trim(p_zone_number), ''),
    nullif(trim(p_zone_name), ''), nullif(trim(p_account_number), ''),
    v_place_name, nullif(trim(p_notes), ''), p_received_at, auth.uid()
  )
  ON CONFLICT (dispatch_job_id) WHERE dispatch_job_id IS NOT NULL DO UPDATE
    SET site_id = excluded.site_id,
        signal_type = excluded.signal_type,
        intake_channel = excluded.intake_channel,
        panel_id = excluded.panel_id,
        zone_number = excluded.zone_number,
        zone_name = excluded.zone_name,
        account_number = excluded.account_number,
        location_name = excluded.location_name,
        notes = excluded.notes,
        received_at = excluded.received_at,
        recorded_by = excluded.recorded_by
  RETURNING * INTO v_event;

  IF v_job.job_type = 'alarm_response' AND v_job.sla_minutes IS NOT NULL THEN
    UPDATE public.dispatch_jobs job
    SET sla_respond_by = p_received_at + make_interval(mins => job.sla_minutes),
        sla_breached = CASE
          WHEN job.on_scene_at IS NOT NULL THEN job.on_scene_at > p_received_at + make_interval(mins => job.sla_minutes)
          ELSE false
        END
    WHERE job.id = v_job.id;
    UPDATE public.sla_clocks clock
    SET started_at = p_received_at,
        alarm_event_id = v_event.id,
        updated_at = now(),
        elapsed_minutes = CASE WHEN clock.arrived_at IS NULL THEN NULL ELSE ceil(extract(epoch FROM (clock.arrived_at - p_received_at)) / 60.0)::integer END,
        status = CASE
          WHEN clock.arrived_at IS NULL THEN clock.status
          WHEN clock.target_minutes IS NULL OR ceil(extract(epoch FROM (clock.arrived_at - p_received_at)) / 60.0) <= clock.target_minutes THEN 'met'
          ELSE 'breached'
        END
    WHERE clock.dispatch_job_id = v_job.id AND clock.status <> 'cancelled';
  ELSE
    UPDATE public.sla_clocks clock
    SET alarm_event_id = v_event.id, updated_at = now()
    WHERE clock.dispatch_job_id = v_job.id AND clock.alarm_event_id IS NULL;
  END IF;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (
    v_job.organization_id, auth.uid(), 'alarm_signal_recorded', 'alarm_events', v_event.id,
    jsonb_build_object('dispatch_job_id', v_job.id, 'signal_type', p_signal_type, 'intake_channel', p_intake_channel, 'received_at', p_received_at)
  );
  RETURN v_event;
END;
$function$;
COMMENT ON FUNCTION "public"."record_alarm_signal"(p_dispatch_job_id uuid, p_received_at timestamp with time zone, p_signal_type text, p_intake_channel text, p_panel_id text, p_zone_number text, p_zone_name text, p_account_number text, p_notes text) IS 'Records or corrects one alarm signal per dispatch job, retaining the Site or Zone place name and anchoring the response clock at receipt time.';
REVOKE ALL ON FUNCTION "public"."record_alarm_signal"(p_dispatch_job_id uuid, p_received_at timestamp with time zone, p_signal_type text, p_intake_channel text, p_panel_id text, p_zone_number text, p_zone_name text, p_account_number text, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_alarm_signal"(p_dispatch_job_id uuid, p_received_at timestamp with time zone, p_signal_type text, p_intake_channel text, p_panel_id text, p_zone_number text, p_zone_name text, p_account_number text, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_alarm_signal"(p_dispatch_job_id uuid, p_received_at timestamp with time zone, p_signal_type text, p_intake_channel text, p_panel_id text, p_zone_number text, p_zone_name text, p_account_number text, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."record_alarm_signal"(p_dispatch_job_id uuid, p_received_at timestamp with time zone, p_signal_type text, p_intake_channel text, p_panel_id text, p_zone_number text, p_zone_name text, p_account_number text, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_approved_fuel_price_observation"(p_client_request_id uuid, p_organization_id uuid, p_source_id uuid, p_observed_on date, p_price_per_litre numeric, p_source_url text, p_source_published_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_source_reference text DEFAULT NULL::text, p_source_hash text DEFAULT NULL::text)
 RETURNS fuel_price_observations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_source public.fuel_price_sources%rowtype;
  v_row public.fuel_price_observations%rowtype;
  v_url text := nullif(trim(coalesce(p_source_url, '')), '');
  v_base text;
  v_base_origin text;
  v_url_origin text;
  v_next_char text;
begin
  select * into v_source from public.fuel_price_sources where id = p_source_id and organization_id = p_organization_id and active;
  if not found then raise exception 'Choose an active approved fuel price source'; end if;
  v_base := trim(trailing '/' from v_source.source_url);
  if v_url is null or v_url !~ '^https?://' or v_base !~ '^https?://' then
    raise exception 'Observation URL must be a public http(s) URL';
  end if;
  v_base_origin := lower(regexp_replace(v_base, '^https?://([^/]+).*$','\1'));
  v_url_origin := lower(regexp_replace(v_url, '^https?://([^/]+).*$','\1'));
  v_next_char := substr(v_url, length(v_base) + 1, 1);
  if v_url_origin <> v_base_origin or not (v_url = v_base or v_next_char in ('/', '?', '#')) then
    raise exception 'Observation URL must be under the approved source URL';
  end if;
  v_row := public.record_fuel_price_observation(p_client_request_id, p_organization_id, v_source.fuel_type, p_observed_on, p_price_per_litre, v_source.name, v_url, p_source_published_at, p_source_reference, p_source_hash);
  update public.fuel_price_observations set source_id = v_source.id where id = v_row.id returning * into v_row;
  return v_row;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."record_approved_fuel_price_observation"(p_client_request_id uuid, p_organization_id uuid, p_source_id uuid, p_observed_on date, p_price_per_litre numeric, p_source_url text, p_source_published_at timestamp with time zone, p_source_reference text, p_source_hash text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_approved_fuel_price_observation"(p_client_request_id uuid, p_organization_id uuid, p_source_id uuid, p_observed_on date, p_price_per_litre numeric, p_source_url text, p_source_published_at timestamp with time zone, p_source_reference text, p_source_hash text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_approved_fuel_price_observation"(p_client_request_id uuid, p_organization_id uuid, p_source_id uuid, p_observed_on date, p_price_per_litre numeric, p_source_url text, p_source_published_at timestamp with time zone, p_source_reference text, p_source_hash text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."record_asset_check"(p_client_request_id uuid, p_asset_id uuid, p_check_type text, p_condition text, p_odometer_reading integer DEFAULT NULL::integer, p_fuel_level text DEFAULT NULL::text, p_defects_noted text DEFAULT NULL::text, p_action_required text DEFAULT NULL::text)
 RETURNS asset_checks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_asset public.assets%rowtype;
  v_check public.asset_checks%rowtype;
begin
  if p_client_request_id is null then
    raise exception 'client_request_id is required';
  end if;

  select a.* into v_asset from public.assets a where a.id = p_asset_id for update;
  if not found then
    raise exception 'Asset not found';
  end if;

  if not public.org_access_allowed(v_asset.organization_id) then
    raise exception 'Not authorised to check this asset';
  end if;

  if p_check_type not in ('pre_shift', 'post_shift', 'weekly', 'monthly', 'defect_report') then
    raise exception 'Unsupported asset check type';
  end if;

  if p_condition not in ('good', 'minor_issue', 'major_issue', 'unserviceable') then
    raise exception 'Unsupported asset condition';
  end if;

  if p_fuel_level is not null and p_fuel_level not in ('full', 'three_quarter', 'half', 'quarter', 'empty') then
    raise exception 'Unsupported fuel level';
  end if;

  insert into public.asset_checks(
    organization_id, asset_id, checked_by, check_type, condition,
    odometer_reading, fuel_level, defects_noted, action_required
  )
  values (
    v_asset.organization_id, v_asset.id, v_actor, p_check_type, p_condition,
    p_odometer_reading, p_fuel_level,
    nullif(trim(coalesce(p_defects_noted, '')), ''),
    nullif(trim(coalesce(p_action_required, '')), '')
  )
  returning * into v_check;

  if p_condition in ('major_issue', 'unserviceable') then
    update public.assets set status = 'maintenance' where id = v_asset.id;
    perform public.enqueue_notification(
      v_asset.organization_id, 'system', 'Asset requires maintenance',
      format('%s reported %s during a %s check.', v_asset.name, replace(p_condition, '_', ' '), replace(p_check_type, '_', ' ')),
      'warning', null, 'admin', 'roster',
      jsonb_build_object('asset_id', v_asset.id, 'asset_check_id', v_check.id),
      'asset_defect:' || v_check.id::text
    );
  end if;

  update public.assets set last_inspection_date = current_date where id = v_asset.id;

  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (
    v_asset.organization_id, v_actor, 'asset_check_recorded', 'asset_checks', v_check.id,
    jsonb_build_object(
      'asset_id', v_asset.id,
      'check_type', p_check_type,
      'condition', p_condition,
      'odometer_reading', p_odometer_reading,
      'client_request_id', p_client_request_id
    )
  );

  return v_check;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."record_asset_check"(p_client_request_id uuid, p_asset_id uuid, p_check_type text, p_condition text, p_odometer_reading integer, p_fuel_level text, p_defects_noted text, p_action_required text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_asset_check"(p_client_request_id uuid, p_asset_id uuid, p_check_type text, p_condition text, p_odometer_reading integer, p_fuel_level text, p_defects_noted text, p_action_required text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_asset_check"(p_client_request_id uuid, p_asset_id uuid, p_check_type text, p_condition text, p_odometer_reading integer, p_fuel_level text, p_defects_noted text, p_action_required text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."record_asset_check"(p_client_request_id uuid, p_asset_id uuid, p_check_type text, p_condition text, p_odometer_reading integer, p_fuel_level text, p_defects_noted text, p_action_required text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_biosecurity_photo_perception_envelope"(p_assessment_id uuid, p_classification jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_source_hash text;
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.biosecurity_assessments
    WHERE id = p_assessment_id
  ) THEN
    RAISE EXCEPTION 'Biosecurity assessment is missing';
  END IF;

  SELECT lower(coalesce(
    nullif(evidence.sha256_hash, ''),
    nullif(evidence.metadata->>'watermarked_sha256', '')
  ))
  INTO v_source_hash
  FROM public.biosecurity_assessment_evidence link
  JOIN public.evidence_items evidence
    ON evidence.id = link.evidence_item_id
   AND evidence.organization_id = link.organization_id
  WHERE link.biosecurity_assessment_id = p_assessment_id
  ORDER BY
    CASE WHEN link.purpose = 'primary_evidence' THEN 0 ELSE 1 END,
    link.ordinal,
    link.id
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('recorded', 0, 'replayed', 0, 'skipped', 'missing_evidence_link');
  END IF;
  IF (v_source_hash ~ '^[0-9a-f]{64}$') IS DISTINCT FROM TRUE THEN
    RETURN jsonb_build_object('recorded', 0, 'replayed', 0, 'skipped', 'missing_source_hash');
  END IF;

  RETURN public.record_biosecurity_photo_perception_envelope_v1_unchecked(
    p_assessment_id,
    p_classification
  );
END;
$function$;
COMMENT ON FUNCTION "public"."record_biosecurity_photo_perception_envelope"(p_assessment_id uuid, p_classification jsonb) IS 'Service-only fail-closed custody gate for replay-safe biosecurity photo perception evidence.';
REVOKE ALL ON FUNCTION "public"."record_biosecurity_photo_perception_envelope"(p_assessment_id uuid, p_classification jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_biosecurity_photo_perception_envelope"(p_assessment_id uuid, p_classification jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_biosecurity_photo_perception_envelope"(p_assessment_id uuid, p_classification jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_biosecurity_photo_perception_envelope_v1_unchecked"(p_assessment_id uuid, p_classification jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_assessment public.biosecurity_assessments%rowtype;
  v_link public.biosecurity_assessment_evidence%rowtype;
  v_evidence public.evidence_items%rowtype;
  v_source_hash text;
  v_classification text;
  v_species text;
  v_density text;
  v_threat_level text;
  v_reasoning text;
  v_confidence real;
  v_authority text;
  v_conflicts jsonb := '[]'::jsonb;
  v_envelope_id uuid;
  v_idempotency_key text;
  v_field_count integer := 0;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  IF jsonb_typeof(p_classification) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'Structured biosecurity classification is required';
  END IF;

  SELECT * INTO v_assessment
  FROM public.biosecurity_assessments
  WHERE id = p_assessment_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Biosecurity assessment is missing'; END IF;

  SELECT link.* INTO v_link
  FROM public.biosecurity_assessment_evidence link
  WHERE link.biosecurity_assessment_id = v_assessment.id
    AND link.organization_id = v_assessment.organization_id
  ORDER BY
    CASE WHEN link.purpose = 'primary_evidence' THEN 0 ELSE 1 END,
    link.ordinal,
    link.id
  LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('recorded', 0, 'replayed', 0, 'skipped', 'missing_evidence_link');
  END IF;

  SELECT * INTO v_evidence
  FROM public.evidence_items
  WHERE id = v_link.evidence_item_id
    AND organization_id = v_assessment.organization_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('recorded', 0, 'replayed', 0, 'skipped', 'missing_evidence_item');
  END IF;

  v_source_hash := lower(coalesce(
    nullif(v_evidence.sha256_hash, ''),
    nullif(v_evidence.metadata->>'watermarked_sha256', '')
  ));
  IF v_source_hash !~ '^[0-9a-f]{64}$' THEN
    RETURN jsonb_build_object('recorded', 0, 'replayed', 0, 'skipped', 'missing_source_hash');
  END IF;
  IF coalesce(p_classification->>'status', 'unavailable') <> 'available' THEN
    UPDATE public.biosecurity_assessments
    SET biosecurity_ai_analysis = p_classification,
        review_state = 'requires_supervisor_review',
        updated_at = clock_timestamp()
    WHERE id = v_assessment.id;
    RETURN jsonb_build_object('recorded', 0, 'replayed', 0, 'skipped', 'classification_unavailable');
  END IF;

  v_classification := nullif(trim(p_classification->>'classification'), '');
  v_species := nullif(trim(coalesce(
    p_classification#>>'{details,species_name}',
    v_classification
  )), '');
  v_density := nullif(trim(p_classification#>>'{details,density}'), '');
  v_threat_level := nullif(trim(p_classification#>>'{details,threat_level}'), '');
  v_reasoning := nullif(trim(p_classification->>'reasoning'), '');
  v_confidence := CASE
    WHEN p_classification->>'confidence' ~ '^[0-9]+([.][0-9]+)?$'
      THEN (p_classification->>'confidence')::real
  END;

  IF v_species IS NULL OR lower(v_species) = 'unknown' THEN
    UPDATE public.biosecurity_assessments
    SET biosecurity_ai_analysis = p_classification,
        review_state = 'requires_supervisor_review',
        updated_at = clock_timestamp()
    WHERE id = v_assessment.id;
    RETURN jsonb_build_object('recorded', 0, 'replayed', 0, 'skipped', 'no_species_candidate');
  END IF;
  IF v_confidence IS NULL OR v_confidence < 0 OR v_confidence > 1 THEN
    RAISE EXCEPTION 'Biosecurity classification confidence is invalid';
  END IF;

  UPDATE public.evidence_items
  SET sha256_hash = coalesce(sha256_hash, v_source_hash)
  WHERE id = v_evidence.id;

  UPDATE public.biosecurity_assessments
  SET biosecurity_ai_analysis = p_classification,
      bob_classification = v_classification,
      bob_confidence = v_confidence,
      bob_species_id = v_species,
      bob_species_confirmed = false,
      bob_recommendation = v_reasoning,
      review_state = 'requires_supervisor_review',
      updated_at = clock_timestamp()
  WHERE id = v_assessment.id
  RETURNING * INTO v_assessment;

  IF nullif(trim(v_assessment.species_name), '') IS NOT NULL
     AND lower(trim(v_assessment.species_name)) <> lower(v_species) THEN
    v_conflicts := jsonb_build_array(jsonb_build_object(
      'source', 'officer_submission',
      'candidate', v_assessment.species_name,
      'reason', 'differs_from_photo_classifier'
    ));
  END IF;
  v_authority := CASE WHEN v_confidence < 0.5 THEN 'insufficient' ELSE 'candidate' END;
  v_idempotency_key := 'biosecurity-photo:' || v_assessment.id::text || ':v1:' || v_source_hash;

  SELECT id INTO v_envelope_id
  FROM public.perception_evidence_envelopes
  WHERE organization_id = v_assessment.organization_id
    AND idempotency_key = v_idempotency_key;
  IF FOUND THEN
    PERFORM public.apply_biosecurity_photo_review_to_perception(v_assessment.id);
    RETURN jsonb_build_object('recorded', 0, 'replayed', 1, 'envelope_id', v_envelope_id);
  END IF;

  INSERT INTO public.perception_evidence_envelopes (
    organization_id, schema_version, domain, source_kind, source_sha256,
    evidence_item_id, source_receipt, model_receipt, derivative_receipts,
    status, idempotency_key
  ) VALUES (
    v_assessment.organization_id, 1, 'biosecurity_photo', 'image', v_source_hash,
    v_evidence.id,
    jsonb_strip_nulls(jsonb_build_object(
      'biosecurity_assessment_id', v_assessment.id,
      'evidence_item_id', v_evidence.id,
      'assessed_at', v_assessment.assessed_at,
      'source_location_id', v_assessment.location_id,
      'source_site_id', v_assessment.site_id,
      'protected_land_site_id', v_assessment.protected_land_site_id,
      'storage_bucket', 'scans',
      'storage_path', v_evidence.storage_path,
      'authoritative_source_preserved', true
    )),
    jsonb_strip_nulls(jsonb_build_object(
      'classifier', coalesce(p_classification->>'classifier', 'bob_vision'),
      'provider', p_classification->'provider',
      'model', p_classification->'model',
      'prompt_version', coalesce(p_classification->>'prompt_version', 'biosecurity_photo_v1'),
      'machine_confirmation_permitted', false
    )),
    jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
      'evidence_item_id', v_evidence.id,
      'original_path', v_evidence.metadata->>'original_path',
      'watermarked_path', v_evidence.metadata->>'watermarked_path',
      'original_sha256', v_evidence.metadata->>'raw_sha256',
      'watermarked_sha256', v_source_hash,
      'watermark_service', v_evidence.metadata->>'watermark_service'
    ))),
    'manual_review_required',
    v_idempotency_key
  )
  RETURNING id INTO v_envelope_id;

  INSERT INTO public.perception_evidence_fields (
    organization_id, envelope_id, field_key, candidate_ordinal, value_type,
    candidate_value, normalized_value, candidate_payload, raw_confidence,
    source_locations, consensus_rule, conflicts, authority_state, review_required
  ) VALUES (
    v_assessment.organization_id, v_envelope_id, 'biosecurity.species_candidate', 0, 'classification',
    v_species, lower(v_species),
    jsonb_strip_nulls(jsonb_build_object(
      'common_name', p_classification#>'{details,common_name}',
      'reasoning', v_reasoning,
      'officer_recorded_species', v_assessment.species_name,
      'legal_or_enforcement_authority', false
    )),
    v_confidence,
    jsonb_build_array(jsonb_build_object(
      'evidence_item_id', v_evidence.id,
      'storage_path', v_evidence.storage_path
    )),
    'advisory_biosecurity_photo_candidate_human_review_required_v1',
    v_conflicts, v_authority, true
  );
  v_field_count := v_field_count + 1;

  IF v_density IS NOT NULL THEN
    INSERT INTO public.perception_evidence_fields (
      organization_id, envelope_id, field_key, candidate_ordinal, value_type,
      candidate_value, normalized_value, candidate_payload, raw_confidence,
      source_locations, consensus_rule, authority_state, review_required
    ) VALUES (
      v_assessment.organization_id, v_envelope_id, 'biosecurity.density_candidate', 0, 'classification',
      v_density, lower(v_density),
      jsonb_build_object('legal_or_enforcement_authority', false),
      v_confidence,
      jsonb_build_array(jsonb_build_object('evidence_item_id', v_evidence.id)),
      'advisory_biosecurity_photo_candidate_human_review_required_v1',
      v_authority, true
    );
    v_field_count := v_field_count + 1;
  END IF;

  IF v_threat_level IS NOT NULL THEN
    INSERT INTO public.perception_evidence_fields (
      organization_id, envelope_id, field_key, candidate_ordinal, value_type,
      candidate_value, normalized_value, candidate_payload, raw_confidence,
      source_locations, consensus_rule, authority_state, review_required
    ) VALUES (
      v_assessment.organization_id, v_envelope_id, 'biosecurity.threat_level_candidate', 0, 'classification',
      v_threat_level, lower(v_threat_level),
      jsonb_build_object('legal_or_enforcement_authority', false),
      v_confidence,
      jsonb_build_array(jsonb_build_object('evidence_item_id', v_evidence.id)),
      'advisory_biosecurity_photo_candidate_human_review_required_v1',
      v_authority, true
    );
    v_field_count := v_field_count + 1;
  END IF;

  PERFORM public.apply_biosecurity_photo_review_to_perception(v_assessment.id);
  INSERT INTO public.audit_log (
    organization_id, actor_user_id, action, target_table, target_id, metadata
  ) VALUES (
    v_assessment.organization_id, NULL, 'biosecurity_photo_perception_recorded',
    'perception_evidence_envelopes', v_envelope_id,
    jsonb_build_object(
      'biosecurity_assessment_id', v_assessment.id,
      'evidence_item_id', v_evidence.id,
      'field_count', v_field_count,
      'machine_confirmation_permitted', false
    )
  );

  RETURN jsonb_build_object(
    'recorded', 1,
    'replayed', 0,
    'envelope_id', v_envelope_id,
    'field_count', v_field_count
  );
END;
$function$;
COMMENT ON FUNCTION "public"."record_biosecurity_photo_perception_envelope_v1_unchecked"(p_assessment_id uuid, p_classification jsonb) IS 'Service-only replay-safe compiler for advisory biosecurity photo classification. It stores custody and candidates but never confirms species or enforcement action.';
REVOKE ALL ON FUNCTION "public"."record_biosecurity_photo_perception_envelope_v1_unchecked"(p_assessment_id uuid, p_classification jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_biosecurity_photo_perception_envelope_v1_unchecked"(p_assessment_id uuid, p_classification jsonb) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."record_callout_milestone"(p_callout_id uuid, p_milestone text, p_expected_status text)
 RETURNS callout_shifts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_callout public.callout_shifts%rowtype;
  v_at timestamptz := now();
  v_next_status text;
begin
  select c.* into v_callout from public.callout_shifts c where c.id = p_callout_id for update;
  if not found then
    raise exception 'Callout not found';
  end if;

  if v_callout.officer_user_id <> v_actor and not public.is_admin_for_org(v_callout.organization_id) then
    raise exception 'Only the called-out officer or an administrator can record milestones';
  end if;

  if v_callout.status <> p_expected_status then
    raise exception 'Callout changed from expected status % to %', p_expected_status, v_callout.status;
  end if;

  v_next_status := case p_milestone
    when 'departed' then 'responding'
    when 'arrived' then 'on_site'
    when 'work_started' then 'working'
    when 'work_ended' then 'returning'
    when 'returned' then 'completed'
    else null
  end;

  if v_next_status is null then
    raise exception 'Unsupported callout milestone %', p_milestone;
  end if;

  if array_position(array['raised','responding','on_site','working','returning','completed'], v_next_status)
     <> array_position(array['raised','responding','on_site','working','returning','completed'], v_callout.status) + 1 then
    raise exception 'Callout milestone % cannot follow status %', p_milestone, v_callout.status;
  end if;

  update public.callout_shifts
  set
    status = v_next_status,
    departed_at = case when p_milestone = 'departed' then v_at else departed_at end,
    arrived_at = case when p_milestone = 'arrived' then v_at else arrived_at end,
    work_started_at = case when p_milestone = 'work_started' then v_at else work_started_at end,
    work_ended_at = case when p_milestone = 'work_ended' then v_at else work_ended_at end,
    returned_at = case when p_milestone = 'returned' then v_at else returned_at end
  where id = v_callout.id
  returning * into v_callout;

  if v_next_status = 'completed' then
    update public.on_call_periods set status = 'completed'
    where id = v_callout.on_call_period_id and status = 'accepted';
  end if;

  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (
    v_callout.organization_id, v_actor, 'callout_milestone_recorded', 'callout_shifts', v_callout.id,
    jsonb_build_object('milestone', p_milestone, 'status', v_next_status, 'recorded_at', v_at)
  );

  return v_callout;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."record_callout_milestone"(p_callout_id uuid, p_milestone text, p_expected_status text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_callout_milestone"(p_callout_id uuid, p_milestone text, p_expected_status text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_callout_milestone"(p_callout_id uuid, p_milestone text, p_expected_status text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."record_callout_milestone"(p_callout_id uuid, p_milestone text, p_expected_status text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_carjam_vehicle_enrichment"(p_client_request_id uuid, p_canonical_vehicle_id uuid, p_plate text, p_make text, p_model text, p_year integer, p_colour text, p_body_type text, p_fuel_type text, p_source_url text, p_source_location text, p_source_terms_url text, p_storage_authorization_reference text, p_response_sha256 text, p_retrieved_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
    v_vehicle public.canonical_vehicles%ROWTYPE;
    v_existing public.vehicle_data_sources%ROWTYPE;
    v_plate text := upper(regexp_replace(coalesce(p_plate, ''), '[^A-Za-z0-9]', '', 'g'));
    v_payload jsonb;
BEGIN
    IF p_client_request_id IS NULL THEN
        RAISE EXCEPTION 'client request id is required';
    END IF;

    PERFORM pg_advisory_xact_lock(hashtextextended('carjam-vehicle:' || p_client_request_id::text, 0));

    SELECT *
      INTO v_existing
      FROM public.vehicle_data_sources
     WHERE client_request_id = p_client_request_id;

    IF FOUND THEN
        IF v_existing.canonical_vehicle_id <> p_canonical_vehicle_id
           OR v_existing.source_key <> v_plate THEN
            RAISE EXCEPTION 'client request id has already been used for a different vehicle';
        END IF;

        SELECT *
          INTO v_vehicle
          FROM public.canonical_vehicles
         WHERE id = p_canonical_vehicle_id;

        RETURN jsonb_build_object(
            'replayed', true,
            'receipt_id', v_existing.id,
            'vehicle', jsonb_build_object(
                'id', v_vehicle.id,
                'plate_number', v_vehicle.plate_number,
                'make', v_vehicle.make,
                'model', v_vehicle.model,
                'year', v_vehicle.year,
                'colour', v_vehicle.colour,
                'body_type', v_vehicle.body_type,
                'fuel_type', v_vehicle.fuel_type,
                'external_data_source_name', v_vehicle.external_data_source_name,
                'external_data_source_url', v_vehicle.external_data_source_url,
                'external_data_source_location', v_vehicle.external_data_source_location,
                'external_data_source_checked_at', v_vehicle.external_data_source_checked_at
            )
        );
    END IF;

    IF v_plate = '' OR v_plate !~ '^[A-Z0-9]{1,10}$' THEN
        RAISE EXCEPTION 'valid plate is required';
    END IF;
    IF p_year IS NOT NULL
       AND (p_year < 1886 OR p_year > extract(year FROM current_date)::integer + 1) THEN
        RAISE EXCEPTION 'vehicle year is outside the supported range';
    END IF;
    IF p_source_url IS NULL
       OR p_source_url IS DISTINCT FROM
          'https://www.carjam.co.nz/api/car/?plate='
          || v_plate
          || '&basic=1&f=json' THEN
        RAISE EXCEPTION 'credential-free CarJam API source URL is required';
    END IF;
    IF p_source_terms_url IS DISTINCT FROM
       'https://www.carjam.co.nz/cms:page?t=api-terms-and-conditions' THEN
        RAISE EXCEPTION 'CarJam API terms URL is required';
    END IF;
    IF length(btrim(coalesce(p_storage_authorization_reference, ''))) < 3 THEN
        RAISE EXCEPTION 'CarJam written storage authorization reference is required';
    END IF;
    IF p_response_sha256 IS NULL OR p_response_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION 'valid response digest is required';
    END IF;
    IF p_retrieved_at IS NULL OR p_retrieved_at > clock_timestamp() + interval '5 minutes' THEN
        RAISE EXCEPTION 'valid retrieval timestamp is required';
    END IF;

    SELECT *
      INTO v_vehicle
      FROM public.canonical_vehicles
     WHERE id = p_canonical_vehicle_id
     FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'canonical vehicle not found';
    END IF;
    IF upper(regexp_replace(coalesce(v_vehicle.plate_number, ''), '[^A-Za-z0-9]', '', 'g'))
       IS DISTINCT FROM v_plate THEN
        RAISE EXCEPTION 'plate does not match canonical vehicle';
    END IF;

    v_payload := jsonb_strip_nulls(jsonb_build_object(
        'plate', v_plate,
        'make', nullif(btrim(p_make), ''),
        'model', nullif(btrim(p_model), ''),
        'year', p_year,
        'colour', nullif(btrim(p_colour), ''),
        'body_type', nullif(btrim(p_body_type), ''),
        'fuel_type', nullif(btrim(p_fuel_type), '')
    ));

    UPDATE public.canonical_vehicles
       SET make = coalesce(make, nullif(btrim(p_make), '')),
           model = coalesce(model, nullif(btrim(p_model), '')),
           year = coalesce(year, p_year),
           colour = coalesce(colour, nullif(btrim(p_colour), '')),
           body_type = coalesce(body_type, nullif(btrim(p_body_type), '')),
           fuel_type = coalesce(fuel_type, nullif(btrim(p_fuel_type), '')),
           external_data_source_name = CASE
               WHEN external_data_source_checked_at IS NULL
                    OR external_data_source_checked_at <= p_retrieved_at
               THEN 'CarJam Developer Connection API'
               ELSE external_data_source_name
           END,
           external_data_source_url = CASE
               WHEN external_data_source_checked_at IS NULL
                    OR external_data_source_checked_at <= p_retrieved_at
               THEN p_source_url
               ELSE external_data_source_url
           END,
           external_data_source_location = CASE
               WHEN external_data_source_checked_at IS NULL
                    OR external_data_source_checked_at <= p_retrieved_at
               THEN p_source_location
               ELSE external_data_source_location
           END,
           external_data_source_checked_at = CASE
               WHEN external_data_source_checked_at IS NULL
                    OR external_data_source_checked_at <= p_retrieved_at
               THEN p_retrieved_at
               ELSE external_data_source_checked_at
           END,
           external_data_source_meta = CASE
               WHEN external_data_source_checked_at IS NULL
                    OR external_data_source_checked_at <= p_retrieved_at
               THEN jsonb_build_object(
                   'terms_url', p_source_terms_url,
                   'response_sha256', p_response_sha256
               )
               ELSE external_data_source_meta
           END,
           updated_at = clock_timestamp()
     WHERE id = p_canonical_vehicle_id
     RETURNING * INTO v_vehicle;

    INSERT INTO public.vehicle_data_sources (
        canonical_vehicle_id,
        client_request_id,
        source_name,
        source_url,
        source_location,
        source_terms_url,
        storage_authorization_reference,
        source_key,
        normalized_payload,
        response_sha256,
        retrieved_at
    ) VALUES (
        p_canonical_vehicle_id,
        p_client_request_id,
        'CarJam Developer Connection API',
        p_source_url,
        p_source_location,
        p_source_terms_url,
        p_storage_authorization_reference,
        v_plate,
        v_payload,
        p_response_sha256,
        p_retrieved_at
    )
    RETURNING * INTO v_existing;

    RETURN jsonb_build_object(
        'replayed', false,
        'receipt_id', v_existing.id,
        'vehicle', jsonb_build_object(
            'id', v_vehicle.id,
            'plate_number', v_vehicle.plate_number,
            'make', v_vehicle.make,
            'model', v_vehicle.model,
            'year', v_vehicle.year,
            'colour', v_vehicle.colour,
            'body_type', v_vehicle.body_type,
            'fuel_type', v_vehicle.fuel_type,
            'external_data_source_name', v_vehicle.external_data_source_name,
            'external_data_source_url', v_vehicle.external_data_source_url,
            'external_data_source_location', v_vehicle.external_data_source_location,
            'external_data_source_checked_at', v_vehicle.external_data_source_checked_at
        )
    );
END;
$function$;
COMMENT ON FUNCTION "public"."record_carjam_vehicle_enrichment"(p_client_request_id uuid, p_canonical_vehicle_id uuid, p_plate text, p_make text, p_model text, p_year integer, p_colour text, p_body_type text, p_fuel_type text, p_source_url text, p_source_location text, p_source_terms_url text, p_storage_authorization_reference text, p_response_sha256 text, p_retrieved_at timestamp with time zone) IS 'Atomic, service-role-only CarJam enrichment receipt. Requires an existing canonical vehicle, exact plate match, credential-free source URL, response digest and written storage authorization reference. Older concurrent receipts remain in history but cannot replace the canonical latest-source attribution.';
REVOKE ALL ON FUNCTION "public"."record_carjam_vehicle_enrichment"(p_client_request_id uuid, p_canonical_vehicle_id uuid, p_plate text, p_make text, p_model text, p_year integer, p_colour text, p_body_type text, p_fuel_type text, p_source_url text, p_source_location text, p_source_terms_url text, p_storage_authorization_reference text, p_response_sha256 text, p_retrieved_at timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_carjam_vehicle_enrichment"(p_client_request_id uuid, p_canonical_vehicle_id uuid, p_plate text, p_make text, p_model text, p_year integer, p_colour text, p_body_type text, p_fuel_type text, p_source_url text, p_source_location text, p_source_terms_url text, p_storage_authorization_reference text, p_response_sha256 text, p_retrieved_at timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_carjam_vehicle_enrichment"(p_client_request_id uuid, p_canonical_vehicle_id uuid, p_plate text, p_make text, p_model text, p_year integer, p_colour text, p_body_type text, p_fuel_type text, p_source_url text, p_source_location text, p_source_terms_url text, p_storage_authorization_reference text, p_response_sha256 text, p_retrieved_at timestamp with time zone) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_cctv_alpr_perception_envelopes"(p_job_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;

  PERFORM set_config('request.jwt.claim.role', 'service_role', true);
  RETURN public.record_cctv_alpr_perception_envelopes_unchecked(p_job_id);
END;
$function$;
COMMENT ON FUNCTION "public"."record_cctv_alpr_perception_envelopes"(p_job_id uuid) IS 'Service-only replay-safe projection of CCTV ALPR observations and source/enhanced derivative receipts into the shared perception evidence spine.';
REVOKE ALL ON FUNCTION "public"."record_cctv_alpr_perception_envelopes"(p_job_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_alpr_perception_envelopes"(p_job_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_alpr_perception_envelopes"(p_job_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_cctv_alpr_perception_envelopes_unchecked"(p_job_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_job public.inference_jobs%rowtype;
  v_evidence public.evidence_items%rowtype;
  v_observation public.cctv_entity_observations%rowtype;
  v_derivative public.cctv_observation_derivatives%rowtype;
  v_envelope_id uuid;
  v_field_id uuid;
  v_source_plate text;
  v_enhanced_plate text;
  v_conflicts jsonb;
  v_authority text;
  v_agreement boolean;
  v_temporal_consensus boolean;
  v_char_confidence real;
  v_evidence_quality text;
  v_idempotency_key text;
  v_recorded integer := 0;
  v_replayed integer := 0;
BEGIN
  IF coalesce(current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;

  SELECT * INTO v_job FROM public.inference_jobs WHERE id = p_job_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Inference job is missing'; END IF;

  SELECT * INTO v_evidence FROM public.evidence_items WHERE id = v_job.evidence_item_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Evidence item is missing'; END IF;
  IF v_evidence.organization_id <> v_job.organization_id THEN
    RAISE EXCEPTION 'Evidence and inference job organization mismatch';
  END IF;
  IF lower(coalesce(v_evidence.sha256_hash, '')) !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'CCTV source custody SHA-256 is required before ALPR evidence can be recorded';
  END IF;

  FOR v_observation IN
    SELECT o.*
    FROM public.cctv_entity_observations o
    WHERE o.inference_job_id = p_job_id
      AND o.organization_id = v_job.organization_id
      AND o.entity_kind = 'vehicle'
      AND o.candidate_plate IS NOT NULL
      AND o.review_state <> 'superseded'
    ORDER BY o.observed_at, o.id
  LOOP
    v_idempotency_key := 'cctv-alpr:' || v_observation.id::text || ':v1:' || lower(v_evidence.sha256_hash);
    SELECT id INTO v_envelope_id
    FROM public.perception_evidence_envelopes
    WHERE organization_id = v_job.organization_id
      AND idempotency_key = v_idempotency_key;
    IF FOUND THEN
      v_replayed := v_replayed + 1;
      CONTINUE;
    END IF;

    SELECT d.* INTO v_derivative
    FROM public.cctv_observation_derivatives d
    WHERE d.observation_id = v_observation.id
    ORDER BY d.created_at DESC
    LIMIT 1;

    v_source_plate := regexp_replace(upper(coalesce(
      v_derivative.recognition_comparison#>>'{alpr,source,text}', ''
    )), '[^A-Z0-9]', '', 'g');
    v_enhanced_plate := regexp_replace(upper(coalesce(
      v_derivative.recognition_comparison#>>'{alpr,enhanced,text}', ''
    )), '[^A-Z0-9]', '', 'g');
    v_agreement := coalesce((v_derivative.recognition_comparison#>>'{alpr,agreement}')::boolean, false);
    v_temporal_consensus := coalesce((v_observation.attributes->>'temporal_consensus')::boolean, false);
    v_char_confidence := nullif(v_observation.attributes->>'plate_char_confidence_min', '')::real;
    v_evidence_quality := coalesce(nullif(v_observation.attributes->>'alpr_evidence_quality', ''), 'unknown');

    v_conflicts := '[]'::jsonb;
    IF v_source_plate <> '' AND v_source_plate <> v_observation.candidate_plate THEN
      v_conflicts := v_conflicts || jsonb_build_array(jsonb_build_object(
        'source', 'source_derivative', 'candidate', v_source_plate,
        'reason', 'differs_from_temporal_candidate'
      ));
    END IF;
    IF v_enhanced_plate <> '' AND v_enhanced_plate <> v_observation.candidate_plate THEN
      v_conflicts := v_conflicts || jsonb_build_array(jsonb_build_object(
        'source', 'enhanced_derivative', 'candidate', v_enhanced_plate,
        'reason', 'differs_from_temporal_candidate'
      ));
    END IF;

    v_authority := CASE
      WHEN v_evidence_quality = 'insufficient'
        OR coalesce((v_observation.attributes->>'plate_width_px')::integer, 0) < 48
        THEN 'insufficient'
      WHEN v_temporal_consensus
        AND v_agreement
        AND v_source_plate = v_observation.candidate_plate
        AND v_enhanced_plate = v_observation.candidate_plate
        AND coalesce(v_char_confidence, 0) >= 0.55
        AND jsonb_array_length(v_conflicts) = 0
        THEN 'verified_candidate'
      ELSE 'candidate'
    END;

    INSERT INTO public.perception_evidence_envelopes (
      organization_id, schema_version, domain, source_kind, source_sha256,
      evidence_item_id, inference_job_id, source_receipt, model_receipt,
      derivative_receipts, status, idempotency_key
    ) VALUES (
      v_job.organization_id, 1, 'cctv_alpr',
      CASE WHEN v_evidence.evidence_kind IN ('photo', 'image') THEN 'image' ELSE 'video' END,
      lower(v_evidence.sha256_hash), v_evidence.id, v_job.id,
      jsonb_strip_nulls(jsonb_build_object(
        'cctv_entity_observation_id', v_observation.id,
        'source_event_id', v_observation.source_event_id,
        'observed_at', v_observation.observed_at,
        'observed_to', v_observation.observed_to,
        'source_frame_sha256', v_observation.frame_sha256,
        'authoritative_source_preserved', true
      )),
      jsonb_strip_nulls(jsonb_build_object(
        'alpr_provider', v_observation.attributes->'alpr_provider',
        'alpr_models', v_observation.attributes->'alpr_models',
        'detector_provider', v_observation.attributes->'detector_provider',
        'inference_provider', v_observation.attributes->'inference_provider'
      )),
      CASE WHEN v_derivative.id IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(
        jsonb_strip_nulls(jsonb_build_object(
          'cctv_observation_derivative_id', v_derivative.id,
          'provider', v_derivative.provider,
          'original_sha256', v_derivative.original_sha256,
          'enhanced_sha256', v_derivative.enhanced_sha256,
          'fusion', v_derivative.fusion_receipt,
          'enhancement', v_derivative.enhancement_receipt,
          'recognition_comparison', v_derivative.recognition_comparison,
          'generative', v_derivative.generative
        ))
      ) END,
      'manual_review_required',
      v_idempotency_key
    )
    RETURNING id INTO v_envelope_id;

    INSERT INTO public.perception_evidence_fields (
      organization_id, envelope_id, field_key, candidate_ordinal, value_type,
      candidate_value, normalized_value, candidate_payload, raw_confidence,
      character_confidences, source_locations, consensus_rule, conflicts,
      authority_state, review_required
    ) VALUES (
      v_job.organization_id, v_envelope_id, 'vehicle.plate_number', 0, 'identifier',
      v_observation.candidate_plate, v_observation.candidate_plate,
      jsonb_strip_nulls(jsonb_build_object(
        'raw_text', v_observation.attributes->'plate_raw_text',
        'corrections', v_observation.attributes->'plate_corrections',
        'minimum_character_confidence', v_char_confidence,
        'plate_width_px', v_observation.attributes->'plate_width_px',
        'evidence_quality', v_evidence_quality,
        'frame_count', v_observation.attributes->'frame_count',
        'visit_count', v_observation.attributes->'visit_count',
        'temporal_consensus', v_temporal_consensus,
        'source_candidate', nullif(v_source_plate, ''),
        'enhanced_candidate', nullif(v_enhanced_plate, ''),
        'source_enhanced_agreement', v_agreement
      )),
      v_observation.model_confidence,
      '[]'::jsonb,
      jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
        'source_event_id', v_observation.source_event_id,
        'frame_sha256', v_observation.frame_sha256,
        'bbox', v_observation.attributes->'bbox',
        'observed_at', v_observation.observed_at,
        'observed_to', v_observation.observed_to
      ))),
      CASE
        WHEN v_authority = 'verified_candidate' THEN 'temporal_and_source_enhanced_consensus_v1'
        ELSE 'cctv_alpr_candidate_v1'
      END,
      v_conflicts, v_authority, true
    )
    RETURNING id INTO v_field_id;

    IF v_observation.review_state IN ('accepted','rejected','uncertain','needs_more_context')
       AND v_observation.reviewed_by IS NOT NULL THEN
      INSERT INTO public.perception_evidence_reviews (
        organization_id, field_id, previous_authority_state, decision,
        next_authority_state, reviewer_notes, canonical_reference, decided_by
      ) VALUES (
        v_job.organization_id, v_field_id, v_authority,
        CASE v_observation.review_state
          WHEN 'accepted' THEN 'approve'
          WHEN 'rejected' THEN 'reject'
          WHEN 'uncertain' THEN 'uncertain'
          ELSE 'needs_more_context'
        END,
        CASE
          WHEN v_observation.review_state = 'accepted' THEN 'human_approved'
          WHEN v_observation.review_state = 'rejected' THEN 'rejected'
          ELSE 'candidate'
        END,
        nullif(trim(v_observation.review_notes), ''),
        jsonb_strip_nulls(jsonb_build_object(
          'cctv_entity_observation_id', v_observation.id,
          'canonical_vehicle_id', v_observation.canonical_vehicle_id,
          'review_state', v_observation.review_state
        )),
        v_observation.reviewed_by
      );

      UPDATE public.perception_evidence_fields
      SET authority_state = CASE
            WHEN v_observation.review_state = 'accepted' THEN 'human_approved'
            WHEN v_observation.review_state = 'rejected' THEN 'rejected'
            ELSE 'candidate'
          END,
          review_required = v_observation.review_state IN ('uncertain','needs_more_context'),
          updated_at = clock_timestamp()
      WHERE id = v_field_id;

      UPDATE public.perception_evidence_envelopes
      SET status = CASE
            WHEN v_observation.review_state IN ('uncertain','needs_more_context') THEN 'manual_review_required'
            ELSE 'complete'
          END,
          updated_at = clock_timestamp()
      WHERE id = v_envelope_id;
    END IF;

    INSERT INTO public.audit_log (
      organization_id, actor_user_id, action, target_table, target_id, metadata
    ) VALUES (
      v_job.organization_id, auth.uid(), 'cctv_alpr_perception_evidence_recorded',
      'perception_evidence_envelopes', v_envelope_id,
      jsonb_build_object(
        'inference_job_id', p_job_id,
        'cctv_entity_observation_id', v_observation.id,
        'authority_state', v_authority
      )
    );
    v_recorded := v_recorded + 1;
  END LOOP;

  RETURN jsonb_build_object('recorded', v_recorded, 'replayed', v_replayed);
END;
$function$;
COMMENT ON FUNCTION "public"."record_cctv_alpr_perception_envelopes_unchecked"(p_job_id uuid) IS 'Internal CCTV ALPR envelope compiler. Invocation is restricted to the service-gated wrapper.';
REVOKE ALL ON FUNCTION "public"."record_cctv_alpr_perception_envelopes_unchecked"(p_job_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_alpr_perception_envelopes_unchecked"(p_job_id uuid) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."record_cctv_cloud_inference_receipt"(p_job_id uuid, p_receipt jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_job public.inference_jobs%rowtype;
  v_policy public.cctv_inference_policies%rowtype;
  v_model text;
  v_bytes integer;
  v_plate_boxes integer;
  v_id uuid;
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' AND session_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;
  IF p_receipt IS NULL OR jsonb_typeof(p_receipt) <> 'object' THEN RAISE EXCEPTION 'Cloud inference receipt must be a JSON object'; END IF;
  SELECT * INTO v_job FROM public.inference_jobs WHERE id = p_job_id;
  IF v_job.id IS NULL THEN RAISE EXCEPTION 'Inference job is missing'; END IF;
  SELECT * INTO v_policy FROM public.cctv_inference_policies WHERE organization_id = v_job.organization_id;
  IF v_policy.cloud_vehicle_vlm_enabled IS NOT TRUE THEN
    RAISE EXCEPTION 'Cloud vehicle hints are not enabled for this organisation';
  END IF;
  IF p_receipt->>'provider' IS DISTINCT FROM 'ollama_cloud' THEN RAISE EXCEPTION 'Unsupported cloud inference provider'; END IF;
  IF p_receipt->>'purpose' IS DISTINCT FROM 'vehicle_make_model_hint' THEN RAISE EXCEPTION 'Unsupported cloud inference purpose'; END IF;
  IF p_receipt->'plate_masked' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'Plates must be masked before a crop leaves the platform'; END IF;
  IF p_receipt->'persons_excluded' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'People must be excluded before a crop leaves the platform'; END IF;
  IF coalesce(p_receipt->>'crop_sha256', '') !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'A SHA-256 crop hash is required'; END IF;
  v_model := nullif(trim(coalesce(p_receipt->>'model', '')), '');
  IF v_model IS NULL THEN RAISE EXCEPTION 'The cloud model is required'; END IF;
  IF v_policy.cloud_vehicle_vlm_model IS NOT NULL AND v_model <> v_policy.cloud_vehicle_vlm_model THEN
    RAISE EXCEPTION 'The cloud model is not the one this organisation allowed';
  END IF;
  IF jsonb_typeof(p_receipt->'crop_bytes') IS DISTINCT FROM 'number' OR jsonb_typeof(p_receipt->'plate_boxes_masked') IS DISTINCT FROM 'number' THEN
    RAISE EXCEPTION 'Crop size and masked plate count are required';
  END IF;
  v_bytes := (p_receipt->>'crop_bytes')::integer;
  v_plate_boxes := (p_receipt->>'plate_boxes_masked')::integer;
  INSERT INTO public.cctv_cloud_inference_receipts (
    organization_id, inference_job_id, evidence_item_id, source_event_id, provider, purpose, model,
    crop_sha256, crop_bytes, plate_masked, plate_boxes_masked, persons_excluded, policy_set_at
  ) VALUES (
    v_job.organization_id, v_job.id, v_job.evidence_item_id, left(nullif(p_receipt->>'source_event_id', ''), 200),
    'ollama_cloud', 'vehicle_make_model_hint', v_model, p_receipt->>'crop_sha256', v_bytes, true, v_plate_boxes, true,
    v_policy.set_at
  ) RETURNING id INTO v_id;
  RETURN v_id;
END;
$function$;
COMMENT ON FUNCTION "public"."record_cctv_cloud_inference_receipt"(p_job_id uuid, p_receipt jsonb) IS 'Service-only. Refuses unless the job organisation opted in, the model matches its policy, plates are masked and people excluded. The worker sends the crop only after this returns an id.';
REVOKE ALL ON FUNCTION "public"."record_cctv_cloud_inference_receipt"(p_job_id uuid, p_receipt jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_cloud_inference_receipt"(p_job_id uuid, p_receipt jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_cloud_inference_receipt"(p_job_id uuid, p_receipt jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_cctv_device_events"(p_import_id uuid, p_events jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_actor uuid := auth.uid(); v_import public.cctv_imports%rowtype; v_n integer;
BEGIN
  SELECT * INTO v_import FROM public.cctv_imports WHERE id = p_import_id;
  IF v_import.id IS NULL THEN RAISE EXCEPTION 'CCTV import not found'; END IF;
  IF auth.role() IS DISTINCT FROM 'service_role' AND session_user NOT IN ('postgres', 'supabase_admin')
     AND (v_actor IS NULL OR NOT public.org_access_allowed(v_import.organization_id)) THEN
    RAISE EXCEPTION 'CCTV import access denied';
  END IF;
  IF jsonb_typeof(p_events) <> 'array' THEN RAISE EXCEPTION 'Events must be an array'; END IF;
  INSERT INTO public.cctv_device_events (cctv_import_id, organization_id, source, source_ref, event_start_at, event_end_at, severity, thumbnail_path, metadata)
  SELECT v_import.id, v_import.organization_id, e->>'source', e->>'source_ref', (e->>'event_start_at')::timestamptz, nullif(e->>'event_end_at', '')::timestamptz,
         coalesce(nullif(e->>'severity', ''), 'motion'), nullif(e->>'thumbnail_path', ''),
         CASE WHEN jsonb_typeof(e->'metadata') = 'object' THEN e->'metadata' ELSE '{}'::jsonb END
  FROM jsonb_array_elements(p_events) e
  WHERE e->>'source' IN ('device_snapshot', 'device_index', 'inference') AND nullif(e->>'source_ref', '') IS NOT NULL AND nullif(e->>'event_start_at', '') IS NOT NULL
    AND coalesce(nullif(e->>'severity', ''), 'motion') IN ('motion', 'detection', 'alert')
  ON CONFLICT (cctv_import_id, source, source_ref) DO NOTHING;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END $function$;
REVOKE ALL ON FUNCTION "public"."record_cctv_device_events"(p_import_id uuid, p_events jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_device_events"(p_import_id uuid, p_events jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_device_events"(p_import_id uuid, p_events jsonb) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_device_events"(p_import_id uuid, p_events jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_cctv_entity_observations"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_observations jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  observation jsonb;
  saved_count integer := 0;
  v_id uuid;
  v_kind text;
  v_import public.cctv_imports%rowtype;
  v_import_id uuid;
  v_face public.vector;
  v_app public.vector;
  v_vehicle_app public.vector;
  v_face_input jsonb;
  v_app_input jsonb;
  v_face_usable boolean;
  v_app_usable boolean;
  v_vehicle_app_usable boolean;
  v_candidates jsonb;
  v_key uuid;
  v_best_key uuid;
  v_best_score real;
  v_state text;
  v_person_id uuid;
  v_canonical_id uuid;
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' AND session_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;
  IF jsonb_typeof(p_observations) <> 'array' THEN
    RAISE EXCEPTION 'CCTV entity observations must be an array';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.inference_jobs
    WHERE id = p_job_id
      AND evidence_item_id = p_evidence_id
      AND organization_id = p_organization_id
      AND domain = 'video_motion'
  ) THEN
    RAISE EXCEPTION 'CCTV inference job is missing or outside the organization';
  END IF;
  SELECT evidence.cctv_import_id
    INTO v_import_id
    FROM public.evidence_items AS evidence
   WHERE evidence.id = p_evidence_id;
  IF v_import_id IS NOT NULL THEN
    SELECT * INTO v_import FROM public.cctv_imports WHERE id = v_import_id;
  END IF;

  FOR observation IN SELECT value FROM jsonb_array_elements(p_observations)
  LOOP
    v_kind := observation->>'entity_kind';
    IF v_kind IS NULL OR v_kind NOT IN ('person', 'vehicle', 'animal')
       OR NULLIF(observation->>'source_event_id', '') IS NULL
       OR NULLIF(observation->>'observed_at', '') IS NULL THEN
      CONTINUE;
    END IF;

    v_face_usable := v_kind = 'person'
      AND observation #>> '{attributes,face_usable_for_matching}' = 'true'
      AND COALESCE(observation->>'quality_state', 'clear') = 'clear';
    v_app_usable := v_kind = 'animal'
      OR (
        v_kind = 'person'
        AND
        observation #>> '{attributes,appearance_embedding_usable}' = 'true'
        AND COALESCE(observation->>'quality_state', 'clear') = 'clear'
      );
    v_vehicle_app_usable := v_kind = 'vehicle'
      AND observation #>> '{attributes,appearance_embedding_usable}' = 'true'
      AND observation #>> '{attributes,appearance_embedding_model}' = 'vehicle-reid-0001.onnx'
      AND COALESCE(observation->>'quality_state', 'clear') = 'clear';
    v_face_input := observation->'candidate_embedding';
    v_app_input := observation->'appearance_embedding';
    IF NOT v_face_usable THEN v_face_input := NULL; END IF;
    IF NOT v_app_usable AND NOT v_vehicle_app_usable THEN v_app_input := NULL; END IF;
    v_face := CASE WHEN v_face_usable THEN public.cctv_jsonb_to_vector(v_face_input, 128) END;
    v_app := CASE WHEN v_app_usable THEN public.cctv_jsonb_to_vector(v_app_input, 256) END;
    v_vehicle_app := CASE WHEN v_vehicle_app_usable THEN public.cctv_jsonb_to_vector(v_app_input, 512) END;
    IF v_face IS NULL THEN v_face_input := NULL; END IF;
    IF v_app IS NULL AND v_vehicle_app IS NULL THEN v_app_input := NULL; END IF;
    v_id := NULL;
    v_person_id := NULL;
    v_canonical_id := NULL;

    INSERT INTO public.cctv_entity_observations (
      organization_id, inference_job_id, evidence_item_id, source_event_id, entity_kind,
      observed_at, observed_to, cctv_import_id, location_id, canonical_place_id, site_id, zone_id,
      candidate_label, candidate_plate, animal_type, species_confidence, is_pest,
      candidate_embedding, appearance_embedding, face_vec, appearance_vec, vehicle_appearance_vec,
      model_confidence, quality_state, attributes, frame_sha256, thumbnail
    ) VALUES (
      p_organization_id, p_job_id, p_evidence_id, observation->>'source_event_id', v_kind,
      (observation->>'observed_at')::timestamptz, NULLIF(observation->>'observed_to', '')::timestamptz,
      v_import.id, v_import.location_id, v_import.canonical_place_id,
      COALESCE(v_import.site_id, NULLIF(observation->>'site_id', '')::uuid),
      COALESCE(v_import.zone_id, NULLIF(observation->>'zone_id', '')::uuid),
      NULLIF(observation->>'candidate_label', ''),
      NULLIF(public.normalize_plate_number(observation->>'candidate_plate'), ''),
      NULLIF(lower(observation->>'animal_type'), ''),
      NULLIF(observation->>'species_confidence', '')::real,
      CASE WHEN observation ? 'is_pest' THEN (observation->>'is_pest')::boolean END,
      CASE WHEN jsonb_typeof(v_face_input) = 'array' THEN v_face_input END,
      CASE WHEN jsonb_typeof(v_app_input) = 'array' THEN v_app_input END,
      v_face, v_app, v_vehicle_app,
      NULLIF(observation->>'model_confidence', '')::real,
      CASE WHEN observation->>'quality_state' IN ('clear', 'glitch', 'flare', 'ir_switch', 'degraded', 'occluded') THEN observation->>'quality_state' ELSE 'clear' END,
      CASE WHEN jsonb_typeof(observation->'attributes') = 'object' THEN observation->'attributes' ELSE '{}'::jsonb END,
      NULLIF(observation->>'frame_sha256', ''),
      CASE WHEN observation->>'thumbnail' LIKE 'data:image/%' THEN observation->>'thumbnail' ELSE NULL END
    )
    ON CONFLICT (inference_job_id, source_event_id, entity_kind) DO UPDATE SET
      observed_to = EXCLUDED.observed_to,
      candidate_label = EXCLUDED.candidate_label,
      candidate_plate = EXCLUDED.candidate_plate,
      animal_type = EXCLUDED.animal_type,
      species_confidence = EXCLUDED.species_confidence,
      is_pest = EXCLUDED.is_pest,
      candidate_embedding = EXCLUDED.candidate_embedding,
      appearance_embedding = EXCLUDED.appearance_embedding,
      face_vec = EXCLUDED.face_vec,
      appearance_vec = EXCLUDED.appearance_vec,
      vehicle_appearance_vec = EXCLUDED.vehicle_appearance_vec,
      model_confidence = EXCLUDED.model_confidence,
      quality_state = EXCLUDED.quality_state,
      attributes = EXCLUDED.attributes,
      frame_sha256 = EXCLUDED.frame_sha256,
      thumbnail = EXCLUDED.thumbnail,
      portfolio_candidates = '[]'::jsonb,
      portfolio_key = NULL,
      portfolio_state = 'unmatched',
      person_record_id = NULL,
      canonical_person_id = NULL,
      canonical_vehicle_id = NULL
    WHERE public.cctv_entity_observations.review_state = 'unreviewed'
    RETURNING id INTO v_id;
    IF v_id IS NULL THEN
      CONTINUE;
    END IF;
    saved_count := saved_count + 1;

    SELECT COALESCE(jsonb_agg(jsonb_build_object(
             'match_kind', match.match_kind,
             'match_id', match.match_id,
             'observation_id', match.observation_id,
             'portfolio_key', match.portfolio_key,
             'display_name', match.display_name,
             'score', match.score,
             'basis', match.basis,
             'last_seen_at', match.last_seen_at,
             'plate_number', match.plate_number,
             'person_record_id', match.person_record_id,
             'canonical_vehicle_id', match.canonical_vehicle_id,
             'thumbnail', match.thumbnail,
             'evidence_item_id', match.evidence_item_id,
             'cctv_import_id', match.cctv_import_id
               ) ORDER BY match.score DESC), '[]'::jsonb)
      INTO v_candidates
      FROM public.find_cctv_portfolio_matches(
        p_organization_id, v_kind, v_face_input, v_app_input,
        observation->>'candidate_plate', v_id, 5
      ) AS match;

    SELECT match.portfolio_key, match.score
      INTO v_best_key, v_best_score
      FROM public.find_cctv_portfolio_matches(
        p_organization_id, v_kind, v_face_input, v_app_input, NULL, v_id, 5
      ) AS match
     WHERE match.match_kind = 'observation'
       AND match.portfolio_key IS NOT NULL
       AND match.score >= CASE match.basis WHEN 'face' THEN 0.72 ELSE 0.80 END
     ORDER BY match.score DESC
     LIMIT 1;

    v_key := COALESCE(v_best_key, gen_random_uuid());
    v_state := CASE WHEN jsonb_array_length(v_candidates) > 0 THEN 'candidate' ELSE 'unmatched' END;
    UPDATE public.cctv_entity_observations
       SET portfolio_candidates = v_candidates,
           portfolio_key = v_key,
           portfolio_state = v_state
     WHERE id = v_id;
    SELECT portfolio_key INTO v_key FROM public.cctv_entity_observations WHERE id = v_id;

    -- A usable face may create a profile. A usable body match may only join the matched portfolio's profile.
    IF v_kind = 'person' AND (v_face IS NOT NULL OR v_best_key IS NOT NULL) THEN
      SELECT profile.person_record_id, profile.canonical_person_id
        INTO v_person_id, v_canonical_id
        FROM public.ensure_cctv_person_profile(
          p_organization_id, v_key, v_id, p_evidence_id,
          (observation->>'observed_at')::timestamptz
        ) AS profile;

      IF v_person_id IS NOT NULL THEN
      UPDATE public.cctv_entity_observations
         SET person_record_id = v_person_id,
             canonical_person_id = v_canonical_id
       WHERE organization_id = p_organization_id
         AND entity_kind = 'person'
         AND portfolio_key = v_key
         AND review_state = 'unreviewed'
         AND (person_record_id IS NULL OR person_record_id = v_person_id)
         AND (canonical_person_id IS NULL OR canonical_person_id = v_canonical_id);
      END IF;
    END IF;
  END LOOP;
  RETURN saved_count;
END;
$function$;
COMMENT ON FUNCTION "public"."record_cctv_entity_observations"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_observations jsonb) IS 'Service-only CCTV writer. Person and vehicle templates are stored and matched only when their explicit quality gates pass; usable body matches may join existing profiles, while new provisional profiles require a usable face.';
REVOKE ALL ON FUNCTION "public"."record_cctv_entity_observations"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_observations jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_entity_observations"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_observations jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_entity_observations"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_observations jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_cctv_identity_draft"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_event_id text, p_event_type text, p_subject_kind text, p_proposed_person_record_id uuid, p_proposed_display_name text, p_candidate_matches jsonb DEFAULT '[]'::jsonb, p_reason text DEFAULT NULL::text)
 RETURNS cctv_identity_drafts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  draft_row public.cctv_identity_drafts;
BEGIN
  IF auth.uid() IS NULL OR NOT public.org_access_allowed(p_organization_id) THEN
    RAISE EXCEPTION 'CCTV identity draft access denied';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.inference_jobs
    WHERE id = p_job_id
      AND evidence_item_id = p_evidence_id
      AND organization_id = p_organization_id
      AND domain IN ('video_motion', 'vehicle', 'face')
  ) THEN
    RAISE EXCEPTION 'CCTV inference job is missing or outside the organization';
  END IF;

  IF jsonb_typeof(COALESCE(p_candidate_matches, '[]'::jsonb)) <> 'array' THEN
    RAISE EXCEPTION 'Candidate matches must be an array';
  END IF;

  IF p_event_type NOT IN ('video', 'vehicle', 'person', 'face', 'keyframe') THEN
    RAISE EXCEPTION 'Invalid CCTV event type';
  END IF;

  IF p_subject_kind NOT IN ('person', 'vehicle', 'location', 'entity', 'case') THEN
    RAISE EXCEPTION 'Invalid subject kind';
  END IF;

  IF p_proposed_person_record_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.person_records pr
      WHERE pr.id = p_proposed_person_record_id AND pr.organization_id = p_organization_id
    ) THEN
      RAISE EXCEPTION 'Proposed person record is not in the organization';
    END IF;
  END IF;

  INSERT INTO public.cctv_identity_drafts (
    organization_id,
    inference_job_id,
    evidence_item_id,
    event_id,
    event_type,
    subject_kind,
    proposed_person_record_id,
    proposed_display_name,
    candidate_matches,
    status,
    authority_level,
    reason,
    created_by,
    updated_at
  ) VALUES (
    p_organization_id,
    p_job_id,
    p_evidence_id,
    NULLIF(trim(p_event_id), ''),
    p_event_type,
    p_subject_kind,
    p_proposed_person_record_id,
    NULLIF(trim(p_proposed_display_name), ''),
    COALESCE(p_candidate_matches, '[]'::jsonb),
    'draft',
    'draft',
    NULLIF(trim(p_reason), ''),
    auth.uid(),
    clock_timestamp()
  )
  ON CONFLICT (inference_job_id, event_id, subject_kind)
  DO UPDATE SET
    proposed_person_record_id = EXCLUDED.proposed_person_record_id,
    proposed_display_name = EXCLUDED.proposed_display_name,
    candidate_matches = EXCLUDED.candidate_matches,
    status = 'draft',
    authority_level = 'draft',
    reason = EXCLUDED.reason,
    updated_at = clock_timestamp(),
    approved_by = NULL,
    approved_at = NULL
  RETURNING * INTO draft_row;

  RETURN draft_row;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."record_cctv_identity_draft"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_event_id text, p_event_type text, p_subject_kind text, p_proposed_person_record_id uuid, p_proposed_display_name text, p_candidate_matches jsonb, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_identity_draft"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_event_id text, p_event_type text, p_subject_kind text, p_proposed_person_record_id uuid, p_proposed_display_name text, p_candidate_matches jsonb, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_identity_draft"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_event_id text, p_event_type text, p_subject_kind text, p_proposed_person_record_id uuid, p_proposed_display_name text, p_candidate_matches jsonb, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_identity_draft"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_event_id text, p_event_type text, p_subject_kind text, p_proposed_person_record_id uuid, p_proposed_display_name text, p_candidate_matches jsonb, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_cctv_inference_usage"(p_job_id uuid, p_usage jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_job public.inference_jobs%rowtype; v_counts jsonb; v_used bigint;
BEGIN
  IF auth.role() <> 'service_role' AND session_user NOT IN ('postgres', 'supabase_admin') THEN RAISE EXCEPTION 'Service identity required'; END IF;
  IF p_usage IS NULL OR jsonb_typeof(p_usage) <> 'object' THEN RAISE EXCEPTION 'Usage must be a JSON object'; END IF;
  SELECT * INTO v_job FROM public.inference_jobs WHERE id = p_job_id;
  IF v_job.id IS NULL THEN RAISE EXCEPTION 'Job not found'; END IF;
  -- Counts only. Nothing about who or what was seen belongs in a metering row.
  v_counts := jsonb_build_object(
    'frames_sampled', greatest(0, coalesce((p_usage->>'frames_sampled')::int, 0)),
    'frames_recognised', greatest(0, coalesce((p_usage->>'frames_recognised')::int, 0)),
    'frames_sent', greatest(0, coalesce((p_usage->>'frames_sent')::int, 0)),
    'gpu_calls', greatest(0, coalesce((p_usage->>'gpu_calls')::int, 0)),
    'gpu_ms', greatest(0, coalesce((p_usage->>'gpu_ms')::bigint, 0)),
    'evidence_item_id', v_job.evidence_item_id);
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_job.organization_id, NULL, 'cctv_inference_usage_recorded', 'inference_jobs', v_job.id, v_counts);
  v_used := public.cctv_inference_frames_used_today(v_job.organization_id);
  RETURN jsonb_build_object('organization_id', v_job.organization_id, 'frames_used_today', v_used);
END $function$;
REVOKE ALL ON FUNCTION "public"."record_cctv_inference_usage"(p_job_id uuid, p_usage jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_inference_usage"(p_job_id uuid, p_usage jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_inference_usage"(p_job_id uuid, p_usage jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_cctv_integrity_check"(p_evidence_id uuid, p_sha256_observed text, p_size_bytes bigint DEFAULT NULL::bigint, p_checked_by text DEFAULT 'vision_worker'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_observed text := lower(nullif(trim(coalesce(p_sha256_observed, '')), ''));
  v_evidence public.evidence_items%rowtype;
  v_expected text;
  v_state text;
  v_checked_at timestamptz := clock_timestamp();
  v_record jsonb;
BEGIN
  IF auth.role() <> 'service_role' AND session_user NOT IN ('postgres', 'supabase_admin') THEN RAISE EXCEPTION 'Service identity required'; END IF;
  IF v_observed IS NULL OR v_observed !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'A 64-character hex sha256 is required'; END IF;
  SELECT * INTO v_evidence FROM public.evidence_items WHERE id = p_evidence_id FOR UPDATE;
  IF v_evidence.id IS NULL THEN RAISE EXCEPTION 'Recording not found'; END IF;

  v_expected := lower(coalesce(v_evidence.sha256_hash, v_evidence.metadata->>'source_sha256'));
  v_state := CASE WHEN v_expected IS NULL THEN 'unanchored' WHEN v_expected = v_observed THEN 'verified' ELSE 'mismatch' END;
  v_record := jsonb_strip_nulls(jsonb_build_object(
    'state', v_state, 'checked_at', v_checked_at, 'checked_by', p_checked_by,
    'observed_sha256', v_observed, 'expected_sha256', v_expected, 'observed_size_bytes', p_size_bytes,
    'check_count', coalesce((v_evidence.metadata->'integrity'->>'check_count')::int, 0) + 1,
    'first_verified_at', CASE WHEN v_state = 'verified' THEN coalesce((v_evidence.metadata->'integrity'->>'first_verified_at')::timestamptz, v_checked_at) ELSE (v_evidence.metadata->'integrity'->>'first_verified_at')::timestamptz END,
    'mismatch_count', coalesce((v_evidence.metadata->'integrity'->>'mismatch_count')::int, 0) + CASE WHEN v_state = 'mismatch' THEN 1 ELSE 0 END
  ));

  UPDATE public.evidence_items SET metadata = metadata || jsonb_build_object('integrity', v_record) WHERE id = v_evidence.id;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_evidence.organization_id, NULL,
          CASE v_state WHEN 'verified' THEN 'cctv_evidence_integrity_verified' WHEN 'mismatch' THEN 'cctv_evidence_integrity_mismatch' ELSE 'cctv_evidence_integrity_unanchored' END,
          'evidence_items', v_evidence.id,
          v_record || jsonb_strip_nulls(jsonb_build_object('cctv_import_id', v_evidence.cctv_import_id, 'locked_at', v_evidence.locked_at, 'storage_path', v_evidence.storage_path)));

  RETURN jsonb_build_object('evidence_item_id', v_evidence.id, 'state', v_state, 'expected_sha256', v_expected, 'observed_sha256', v_observed, 'checked_at', v_checked_at);
END $function$;
COMMENT ON FUNCTION "public"."record_cctv_integrity_check"(p_evidence_id uuid, p_sha256_observed text, p_size_bytes bigint, p_checked_by text) IS 'Service-only: compares a fresh hash of the stored bytes with the sealed/recorded hash. Writes metadata.integrity (state verified|mismatch|unanchored, counts, timestamps) and an audit_log row. Never changes the sealed hash.';
REVOKE ALL ON FUNCTION "public"."record_cctv_integrity_check"(p_evidence_id uuid, p_sha256_observed text, p_size_bytes bigint, p_checked_by text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_integrity_check"(p_evidence_id uuid, p_sha256_observed text, p_size_bytes bigint, p_checked_by text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_integrity_check"(p_evidence_id uuid, p_sha256_observed text, p_size_bytes bigint, p_checked_by text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_cctv_observation_derivatives"(p_job_id uuid, p_derivatives jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_job public.inference_jobs%rowtype;
  v_observation public.cctv_entity_observations%rowtype;
  v_item jsonb;
  v_id uuid;
  v_profile text;
  v_prefix text;
  v_count integer := 0;
BEGIN
  IF auth.role() <> 'service_role' AND session_user NOT IN ('postgres','supabase_admin') THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;
  IF jsonb_typeof(p_derivatives) <> 'array' THEN RAISE EXCEPTION 'CCTV derivatives must be an array'; END IF;
  SELECT * INTO v_job FROM public.inference_jobs WHERE id = p_job_id AND domain = 'video_motion';
  IF NOT FOUND THEN RAISE EXCEPTION 'CCTV inference job is missing'; END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_derivatives)
  LOOP
    SELECT * INTO v_observation
    FROM public.cctv_entity_observations
    WHERE inference_job_id = p_job_id AND source_event_id = v_item->>'source_event_id'
      AND entity_kind = v_item->>'entity_kind' AND review_state <> 'superseded'
    ORDER BY created_at LIMIT 1;
    IF NOT FOUND THEN CONTINUE; END IF;
    v_profile := nullif(v_item#>>'{enhancement,profile}', '');
    v_prefix := 'org/' || v_job.organization_id::text || '/cctv-derivatives/' || v_job.evidence_item_id::text || '/';
    IF v_profile IS NULL OR NOT (coalesce(v_item->>'original_path','') LIKE v_prefix || '%') OR NOT (coalesce(v_item->>'enhanced_path','') LIKE v_prefix || '%') THEN
      RAISE EXCEPTION 'Derivative storage path or enhancement profile is invalid';
    END IF;
    IF coalesce(v_item->>'original_sha256','') !~ '^[0-9a-f]{64}$' OR coalesce(v_item->>'enhanced_sha256','') !~ '^[0-9a-f]{64}$' THEN
      RAISE EXCEPTION 'Derivative hashes must be lowercase SHA-256';
    END IF;
    IF v_item->>'provider' NOT IN ('laptop_gpu','runpod_fallback','worker_deterministic') THEN
      RAISE EXCEPTION 'Unknown derivative provider';
    END IF;

    INSERT INTO public.cctv_observation_derivatives (
      organization_id, observation_id, inference_job_id, evidence_item_id, source_event_id, entity_kind,
      original_bucket, original_path, original_sha256, enhanced_bucket, enhanced_path, enhanced_sha256,
      provider, enhancement_profile, generative, source_frame_hash, source_frames,
      fusion_receipt, enhancement_receipt, recognition_results, recognition_comparison, review_required
    ) VALUES (
      v_job.organization_id, v_observation.id, p_job_id, v_job.evidence_item_id, v_item->>'source_event_id', v_item->>'entity_kind',
      v_item->>'original_bucket', v_item->>'original_path', v_item->>'original_sha256', v_item->>'enhanced_bucket', v_item->>'enhanced_path', v_item->>'enhanced_sha256',
      v_item->>'provider', v_profile, coalesce((v_item#>>'{enhancement,generative}')::boolean, false), nullif(v_item->>'source_frame_hash',''),
      CASE WHEN jsonb_typeof(v_item->'source_frames')='array' THEN v_item->'source_frames' ELSE '[]'::jsonb END,
      coalesce(v_item->'fusion','{}'::jsonb), coalesce(v_item->'enhancement','{}'::jsonb), coalesce(v_item->'recognition','{}'::jsonb), coalesce(v_item->'recognition_comparison','{}'::jsonb), true
    )
    ON CONFLICT (observation_id, enhancement_profile) DO UPDATE SET
      original_bucket=excluded.original_bucket, original_path=excluded.original_path, original_sha256=excluded.original_sha256,
      enhanced_bucket=excluded.enhanced_bucket, enhanced_path=excluded.enhanced_path, enhanced_sha256=excluded.enhanced_sha256,
      provider=excluded.provider, generative=excluded.generative, source_frame_hash=excluded.source_frame_hash, source_frames=excluded.source_frames,
      fusion_receipt=excluded.fusion_receipt, enhancement_receipt=excluded.enhancement_receipt,
      recognition_results=excluded.recognition_results, recognition_comparison=excluded.recognition_comparison, updated_at=clock_timestamp()
    RETURNING id INTO v_id;

    UPDATE public.cctv_entity_observations
    SET attributes = attributes || jsonb_build_object('capture_recognition', jsonb_build_object(
      'derivative_id', v_id, 'provider', v_item->>'provider',
      'original_storage_bucket', v_item->>'original_bucket', 'original_storage_path', v_item->>'original_path', 'original_sha256', v_item->>'original_sha256',
      'enhanced_storage_bucket', v_item->>'enhanced_bucket', 'enhanced_storage_path', v_item->>'enhanced_path', 'enhanced_sha256', v_item->>'enhanced_sha256',
      'enhancement', coalesce(v_item->'enhancement','{}'::jsonb), 'fusion', coalesce(v_item->'fusion','{}'::jsonb),
      'recognition_comparison', coalesce(v_item->'recognition_comparison','{}'::jsonb), 'authority', 'provisional', 'review_required', true
    ))
    WHERE id = v_observation.id;
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END;
$function$;
COMMENT ON FUNCTION "public"."record_cctv_observation_derivatives"(p_job_id uuid, p_derivatives jsonb) IS 'Service-only writer for private source/enhanced CCTV still pairs. Validates evidence-scoped paths, hashes, provider and provisional authority.';
REVOKE ALL ON FUNCTION "public"."record_cctv_observation_derivatives"(p_job_id uuid, p_derivatives jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_observation_derivatives"(p_job_id uuid, p_derivatives jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_observation_derivatives"(p_job_id uuid, p_derivatives jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_cctv_person_perception_envelopes"(p_job_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_job public.inference_jobs%rowtype;
  v_evidence public.evidence_items%rowtype;
  v_observation public.cctv_entity_observations%rowtype;
  v_derivative public.cctv_observation_derivatives%rowtype;
  v_envelope_id uuid;
  v_idempotency_key text;
  v_initial_authority text;
  v_face_present boolean;
  v_candidate_count integer;
  v_top_similarity real;
  v_recorded integer := 0;
  v_replayed integer := 0;
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;

  SELECT * INTO v_job FROM public.inference_jobs WHERE id = p_job_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Inference job is missing'; END IF;

  SELECT * INTO v_evidence FROM public.evidence_items WHERE id = v_job.evidence_item_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Evidence item is missing'; END IF;
  IF v_evidence.organization_id <> v_job.organization_id THEN
    RAISE EXCEPTION 'Evidence and inference job organization mismatch';
  END IF;
  IF lower(coalesce(v_evidence.sha256_hash, '')) !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'CCTV source custody SHA-256 is required before person evidence can be recorded';
  END IF;

  FOR v_observation IN
    SELECT o.*
    FROM public.cctv_entity_observations o
    WHERE o.inference_job_id = p_job_id
      AND o.organization_id = v_job.organization_id
      AND o.entity_kind = 'person'
      AND o.review_state <> 'superseded'
    ORDER BY o.observed_at, o.id
  LOOP
    v_idempotency_key := 'cctv-person:' || v_observation.id::text || ':v1:' || lower(v_evidence.sha256_hash);
    SELECT id INTO v_envelope_id
    FROM public.perception_evidence_envelopes
    WHERE organization_id = v_job.organization_id
      AND idempotency_key = v_idempotency_key;
    IF FOUND THEN
      v_replayed := v_replayed + 1;
      CONTINUE;
    END IF;

    SELECT d.* INTO v_derivative
    FROM public.cctv_observation_derivatives d
    WHERE d.observation_id = v_observation.id
    ORDER BY d.created_at DESC
    LIMIT 1;

    v_initial_authority := CASE
      WHEN v_observation.quality_state IN ('glitch', 'flare', 'ir_switch', 'degraded', 'occluded')
        THEN 'insufficient'
      ELSE 'candidate'
    END;
    v_face_present := coalesce((v_observation.attributes->>'face_detected')::boolean, false)
      OR v_observation.attributes ? 'face_event_id'
      OR coalesce((v_observation.attributes->>'face_only')::boolean, false);
    v_candidate_count := CASE
      WHEN jsonb_typeof(v_observation.portfolio_candidates) = 'array'
        THEN jsonb_array_length(v_observation.portfolio_candidates)
      ELSE 0
    END;
    SELECT max(
      CASE WHEN candidate.value->>'score' ~ '^[0-9]+([.][0-9]+)?$'
        THEN (candidate.value->>'score')::real END
    )
    INTO v_top_similarity
    FROM jsonb_array_elements(
      CASE WHEN jsonb_typeof(v_observation.portfolio_candidates) = 'array'
        THEN v_observation.portfolio_candidates ELSE '[]'::jsonb END
    ) AS candidate(value);

    INSERT INTO public.perception_evidence_envelopes (
      organization_id, schema_version, domain, source_kind, source_sha256,
      evidence_item_id, inference_job_id, source_receipt, model_receipt,
      derivative_receipts, status, idempotency_key
    ) VALUES (
      v_job.organization_id, 1, 'cctv_person',
      CASE WHEN v_evidence.evidence_kind IN ('photo', 'image') THEN 'image' ELSE 'video' END,
      lower(v_evidence.sha256_hash), v_evidence.id, v_job.id,
      jsonb_strip_nulls(jsonb_build_object(
        'cctv_entity_observation_id', v_observation.id,
        'source_event_id', v_observation.source_event_id,
        'observed_at', v_observation.observed_at,
        'observed_to', v_observation.observed_to,
        'source_frame_sha256', v_observation.frame_sha256,
        'location_id', v_observation.location_id,
        'canonical_place_id', v_observation.canonical_place_id,
        'authoritative_source_preserved', true
      )),
      jsonb_strip_nulls(jsonb_build_object(
        'face_provider', v_observation.attributes->'face_provider',
        'face_detector_model', v_observation.attributes->'face_detector_model',
        'face_embedding_model', v_observation.attributes->'face_embedding_model',
        'appearance_embedding_model', v_observation.attributes->'appearance_embedding_model',
        'identity_resolution', 'manual_review_required',
        'biometric_templates_copied', false
      )),
      CASE WHEN v_derivative.id IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(
        jsonb_strip_nulls(jsonb_build_object(
          'cctv_observation_derivative_id', v_derivative.id,
          'provider', v_derivative.provider,
          'original_sha256', v_derivative.original_sha256,
          'enhanced_sha256', v_derivative.enhanced_sha256,
          'fusion_profile', v_derivative.fusion_receipt->>'profile',
          'enhancement_profile', v_derivative.enhancement_profile,
          'generative', v_derivative.generative,
          'source_face_count', v_derivative.recognition_comparison->'source_face_count',
          'enhanced_face_count', v_derivative.recognition_comparison->'enhanced_face_count'
        ))
      ) END,
      'manual_review_required',
      v_idempotency_key
    )
    RETURNING id INTO v_envelope_id;

    INSERT INTO public.perception_evidence_fields (
      organization_id, envelope_id, field_key, candidate_ordinal, value_type,
      candidate_value, normalized_value, candidate_payload, raw_confidence,
      source_locations, consensus_rule, authority_state, review_required
    ) VALUES (
      v_job.organization_id, v_envelope_id, 'person.presence', 0, 'boolean',
      'true', 'true',
      jsonb_strip_nulls(jsonb_build_object(
        'frame_count', v_observation.attributes->'frame_count',
        'review_candidate_basis', v_observation.attributes->'review_candidate_basis',
        'face_only', v_observation.attributes->'face_only',
        'upper_body_colour', v_observation.attributes->'upper_body_colour',
        'lower_body_colour', v_observation.attributes->'lower_body_colour',
        'visible_head_region', v_observation.attributes->'visible_head_region',
        'quality_state', v_observation.quality_state
      )),
      v_observation.model_confidence,
      jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
        'source_event_id', v_observation.source_event_id,
        'frame_sha256', v_observation.frame_sha256,
        'bbox', v_observation.attributes->'bbox',
        'observed_at', v_observation.observed_at,
        'observed_to', v_observation.observed_to
      ))),
      'person_detection_requires_human_review_v1',
      v_initial_authority, true
    );

    IF v_face_present THEN
      INSERT INTO public.perception_evidence_fields (
        organization_id, envelope_id, field_key, candidate_ordinal, value_type,
        candidate_value, normalized_value, candidate_payload, raw_confidence,
        source_locations, consensus_rule, authority_state, review_required
      ) VALUES (
        v_job.organization_id, v_envelope_id, 'person.face_detected', 0, 'boolean',
        'true', 'true',
        jsonb_strip_nulls(jsonb_build_object(
          'face_basis', v_observation.attributes->'face_basis',
          'face_provider', v_observation.attributes->'face_provider',
          'face_detector_model', v_observation.attributes->'face_detector_model',
          'face_embedding_model', v_observation.attributes->'face_embedding_model',
          'face_crop_width_px', v_observation.attributes->'face_crop_width_px',
          'face_alignment_basis', v_observation.attributes->'face_alignment_basis',
          'visit_count', coalesce(v_observation.attributes->'face_visit_count', v_observation.attributes->'visit_count'),
          'biometric_template_included', false
        )),
        nullif(v_observation.attributes->>'face_detector_confidence', '')::real,
        jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
          'source_event_id', v_observation.source_event_id,
          'frame_sha256', v_observation.frame_sha256,
          'bbox', v_observation.attributes->'bbox'
        ))),
        'human_review_required_no_tenant_face_calibration_v1',
        v_initial_authority, true
      );
    END IF;

    IF v_observation.portfolio_key IS NOT NULL THEN
      INSERT INTO public.perception_evidence_fields (
        organization_id, envelope_id, field_key, candidate_ordinal, value_type,
        candidate_value, normalized_value, candidate_payload,
        source_locations, consensus_rule, authority_state, review_required
      ) VALUES (
        v_job.organization_id, v_envelope_id, 'person.portfolio_candidate', 0, 'entity',
        v_observation.portfolio_key::text, v_observation.portfolio_key::text,
        jsonb_strip_nulls(jsonb_build_object(
          'portfolio_state', v_observation.portfolio_state,
          'candidate_count', v_candidate_count,
          'top_similarity', v_top_similarity,
          'identity_claimed', false,
          'biometric_template_included', false
        )),
        jsonb_build_array(jsonb_build_object(
          'cctv_entity_observation_id', v_observation.id,
          'source_event_id', v_observation.source_event_id
        )),
        'provisional_similarity_cluster_human_identity_required_v1',
        'candidate', true
      );
    END IF;

    PERFORM public.apply_cctv_person_review_to_perception(v_observation.id);

    INSERT INTO public.audit_log (
      organization_id, actor_user_id, action, target_table, target_id, metadata
    ) VALUES (
      v_job.organization_id, auth.uid(), 'cctv_person_perception_evidence_recorded',
      'perception_evidence_envelopes', v_envelope_id,
      jsonb_build_object(
        'inference_job_id', p_job_id,
        'cctv_entity_observation_id', v_observation.id,
        'face_present', v_face_present,
        'biometric_templates_copied', false
      )
    );
    v_recorded := v_recorded + 1;
  END LOOP;

  RETURN jsonb_build_object('recorded', v_recorded, 'replayed', v_replayed);
END;
$function$;
COMMENT ON FUNCTION "public"."record_cctv_person_perception_envelopes"(p_job_id uuid) IS 'Service-only replay-safe projection of CCTV person and face provenance into shared perception receipts. Raw biometric templates never enter the shared envelope.';
REVOKE ALL ON FUNCTION "public"."record_cctv_person_perception_envelopes"(p_job_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_person_perception_envelopes"(p_job_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_person_perception_envelopes"(p_job_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_cctv_review_decision"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_event_id text, p_event_type text, p_decision text, p_reason text)
 RETURNS cctv_review_decisions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE result public.cctv_review_decisions;
BEGIN
  IF auth.uid() IS NULL OR NOT public.org_access_allowed(p_organization_id) THEN RAISE EXCEPTION 'CCTV review access denied'; END IF;
  IF p_decision NOT IN ('confirmed', 'dismissed') OR p_event_type NOT IN ('video', 'vehicle', 'person', 'face', 'keyframe') THEN RAISE EXCEPTION 'Invalid CCTV review decision'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.inference_jobs WHERE id = p_job_id AND evidence_item_id = p_evidence_id AND organization_id = p_organization_id AND domain = 'video_motion') THEN RAISE EXCEPTION 'CCTV job not found'; END IF;
  INSERT INTO public.cctv_review_decisions (organization_id, inference_job_id, evidence_item_id, event_id, event_type, decision, reason, decided_by)
  VALUES (p_organization_id, p_job_id, p_evidence_id, NULLIF(trim(p_event_id), ''), p_event_type, p_decision, trim(p_reason), auth.uid())
  ON CONFLICT (inference_job_id, event_id) DO UPDATE SET decision = EXCLUDED.decision, reason = EXCLUDED.reason, decided_by = EXCLUDED.decided_by, decided_at = clock_timestamp()
  RETURNING * INTO result;
  RETURN result;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."record_cctv_review_decision"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_event_id text, p_event_type text, p_decision text, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_review_decision"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_event_id text, p_event_type text, p_decision text, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_review_decision"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_event_id text, p_event_type text, p_decision text, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_review_decision"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_event_id text, p_event_type text, p_decision text, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_cctv_review_event"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_source_event_id text, p_event_type text, p_review_state text, p_reviewer_notes text DEFAULT NULL::text, p_confidence_override real DEFAULT NULL::real, p_person_record_id uuid DEFAULT NULL::uuid, p_vehicle_id uuid DEFAULT NULL::uuid, p_incident_id uuid DEFAULT NULL::uuid)
 RETURNS cctv_review_events
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  actor_id uuid := auth.uid();
  current_event public.cctv_review_events;
  saved_event public.cctv_review_events;
BEGIN
  IF actor_id IS NULL OR NOT public.org_access_allowed(p_organization_id) THEN
    RAISE EXCEPTION 'CCTV review access denied';
  END IF;
  IF p_source_event_id IS NULL OR trim(p_source_event_id) = '' THEN
    RAISE EXCEPTION 'Source event ID is required';
  END IF;
  IF p_event_type NOT IN ('video', 'vehicle', 'person', 'face', 'keyframe')
     OR p_review_state NOT IN ('unreviewed', 'accepted', 'rejected', 'uncertain', 'needs_more_context', 'superseded') THEN
    RAISE EXCEPTION 'Invalid CCTV review event type or state';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.inference_jobs
    WHERE id = p_job_id AND evidence_item_id = p_evidence_id
      AND organization_id = p_organization_id AND domain IN ('video_motion', 'vehicle', 'face')
  ) THEN
    RAISE EXCEPTION 'CCTV inference job is missing or outside the organization';
  END IF;
  IF p_person_record_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.person_records WHERE id = p_person_record_id AND organization_id = p_organization_id) THEN
    RAISE EXCEPTION 'Person record is outside the organization';
  END IF;
  IF p_vehicle_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.vehicles WHERE id = p_vehicle_id AND organization_id = p_organization_id) THEN
    RAISE EXCEPTION 'Vehicle record is outside the organization';
  END IF;
  IF p_incident_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.incidents WHERE id = p_incident_id AND organization_id = p_organization_id) THEN
    RAISE EXCEPTION 'Incident is outside the organization';
  END IF;
  IF p_review_state = 'accepted' AND p_event_type IN ('face', 'person') AND p_person_record_id IS NULL THEN
    RAISE EXCEPTION 'Accepted person events require an explicit person record link';
  END IF;
  IF p_review_state = 'accepted' AND p_event_type = 'vehicle' AND p_vehicle_id IS NULL THEN
    RAISE EXCEPTION 'Accepted vehicle events require an explicit vehicle record link';
  END IF;

  SELECT * INTO current_event
    FROM public.cctv_review_events
   WHERE inference_job_id = p_job_id AND source_event_id = trim(p_source_event_id) AND event_type = p_event_type
   FOR UPDATE;

  INSERT INTO public.cctv_review_events (
    organization_id, inference_job_id, evidence_item_id, source_event_id, event_type,
    review_state, reviewer_notes, confidence_override,
    linked_person_record_id, linked_vehicle_id, linked_incident_id
  ) VALUES (
    p_organization_id, p_job_id, p_evidence_id, trim(p_source_event_id), p_event_type,
    p_review_state, NULLIF(trim(p_reviewer_notes), ''), p_confidence_override,
    p_person_record_id, p_vehicle_id, p_incident_id
  )
  ON CONFLICT (inference_job_id, source_event_id, event_type)
  DO UPDATE SET
    review_state = EXCLUDED.review_state,
    reviewer_notes = EXCLUDED.reviewer_notes,
    confidence_override = EXCLUDED.confidence_override,
    linked_person_record_id = EXCLUDED.linked_person_record_id,
    linked_vehicle_id = EXCLUDED.linked_vehicle_id,
    linked_incident_id = EXCLUDED.linked_incident_id,
    updated_at = clock_timestamp()
  RETURNING * INTO saved_event;

  INSERT INTO public.cctv_review_event_decisions (
    organization_id, review_event_id, previous_state, next_state, reviewer_notes,
    confidence_override, linked_person_record_id, linked_vehicle_id, linked_incident_id, decided_by
  ) VALUES (
    p_organization_id, saved_event.id, current_event.review_state, p_review_state,
    NULLIF(trim(p_reviewer_notes), ''), p_confidence_override,
    p_person_record_id, p_vehicle_id, p_incident_id, actor_id
  );

  RETURN saved_event;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."record_cctv_review_event"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_source_event_id text, p_event_type text, p_review_state text, p_reviewer_notes text, p_confidence_override real, p_person_record_id uuid, p_vehicle_id uuid, p_incident_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_review_event"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_source_event_id text, p_event_type text, p_review_state text, p_reviewer_notes text, p_confidence_override real, p_person_record_id uuid, p_vehicle_id uuid, p_incident_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_review_event"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_source_event_id text, p_event_type text, p_review_state text, p_reviewer_notes text, p_confidence_override real, p_person_record_id uuid, p_vehicle_id uuid, p_incident_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_review_event"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_source_event_id text, p_event_type text, p_review_state text, p_reviewer_notes text, p_confidence_override real, p_person_record_id uuid, p_vehicle_id uuid, p_incident_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_cctv_scene_observation"(p_organization_id uuid, p_evidence_id uuid, p_inference_job_id uuid, p_camera_key text, p_scene_fingerprint jsonb, p_location_id uuid DEFAULT NULL::uuid, p_site_id uuid DEFAULT NULL::uuid, p_zone_id uuid DEFAULT NULL::uuid)
 RETURNS cctv_camera_scene_profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_profile public.cctv_camera_scene_profiles;
  v_result jsonb;
  v_vehicle_count integer := 0;
  v_person_count integer := 0;
  v_review_count integer := 0;
BEGIN
  IF auth.role() <> 'service_role' AND session_user <> 'postgres' THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;
  IF p_camera_key IS NULL OR length(trim(p_camera_key)) < 3 THEN
    RAISE EXCEPTION 'camera key is required';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.evidence_items e
    WHERE e.id = p_evidence_id AND e.organization_id = p_organization_id
  ) THEN RAISE EXCEPTION 'evidence item not found for organization'; END IF;

  SELECT r.result INTO v_result
  FROM public.inference_results r
  WHERE r.inference_job_id = p_inference_job_id AND r.evidence_item_id = p_evidence_id
  ORDER BY r.created_at DESC
  LIMIT 1;

  v_vehicle_count := COALESCE(jsonb_array_length(v_result #> '{consolidated_events,vehicle_events}'), 0);
  v_person_count := COALESCE(jsonb_array_length(v_result #> '{consolidated_events,person_events}'), 0)
    + COALESCE(jsonb_array_length(v_result #> '{consolidated_events,face_events}'), 0);
  v_review_count := COALESCE((v_result #>> '{consolidated_events,quality_summary,review_required_count}')::integer, 0);

  INSERT INTO public.cctv_camera_scene_profiles (
    organization_id, location_id, site_id, zone_id, camera_key, scene_fingerprint,
    first_seen_at, last_seen_at, evidence_count, recidivism_summary
  ) VALUES (
    p_organization_id, p_location_id, p_site_id, p_zone_id, trim(p_camera_key), COALESCE(p_scene_fingerprint, '{}'::jsonb),
    clock_timestamp(), clock_timestamp(), 1,
    jsonb_build_object('vehicle_events', v_vehicle_count, 'person_events', v_person_count, 'review_required', v_review_count)
  )
  ON CONFLICT (organization_id, camera_key) DO UPDATE SET
    location_id = COALESCE(EXCLUDED.location_id, cctv_camera_scene_profiles.location_id),
    site_id = COALESCE(EXCLUDED.site_id, cctv_camera_scene_profiles.site_id),
    zone_id = COALESCE(EXCLUDED.zone_id, cctv_camera_scene_profiles.zone_id),
    scene_fingerprint = EXCLUDED.scene_fingerprint,
    last_seen_at = clock_timestamp(),
    evidence_count = cctv_camera_scene_profiles.evidence_count + 1,
    recidivism_summary = jsonb_build_object(
      'vehicle_events', COALESCE((cctv_camera_scene_profiles.recidivism_summary->>'vehicle_events')::integer, 0) + v_vehicle_count,
      'person_events', COALESCE((cctv_camera_scene_profiles.recidivism_summary->>'person_events')::integer, 0) + v_person_count,
      'review_required', COALESCE((cctv_camera_scene_profiles.recidivism_summary->>'review_required')::integer, 0) + v_review_count
    )
  RETURNING * INTO v_profile;

  RETURN v_profile;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."record_cctv_scene_observation"(p_organization_id uuid, p_evidence_id uuid, p_inference_job_id uuid, p_camera_key text, p_scene_fingerprint jsonb, p_location_id uuid, p_site_id uuid, p_zone_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_scene_observation"(p_organization_id uuid, p_evidence_id uuid, p_inference_job_id uuid, p_camera_key text, p_scene_fingerprint jsonb, p_location_id uuid, p_site_id uuid, p_zone_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_scene_observation"(p_organization_id uuid, p_evidence_id uuid, p_inference_job_id uuid, p_camera_key text, p_scene_fingerprint jsonb, p_location_id uuid, p_site_id uuid, p_zone_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_cctv_scene_synopsis"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_summary text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_id uuid;
  v_metadata jsonb := CASE WHEN jsonb_typeof(p_metadata) = 'object' THEN p_metadata ELSE '{}'::jsonb END;
BEGIN
  IF auth.role() <> 'service_role' AND session_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;
  IF NULLIF(trim(p_summary), '') IS NULL THEN
    RETURN NULL;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.inference_jobs
     WHERE id = p_job_id AND evidence_item_id = p_evidence_id AND organization_id = p_organization_id AND domain = 'video_motion'
  ) THEN
    RAISE EXCEPTION 'CCTV inference job is missing or outside the organization';
  END IF;

  SELECT id INTO v_id
    FROM public.evidence_summary_approvals
   WHERE evidence_id = p_evidence_id
     AND generated_mode = 'cctv_vision_llm_scene_synopsis'
     AND generated_review_status IS NULL
   LIMIT 1;

  IF v_id IS NOT NULL THEN
    UPDATE public.evidence_summary_approvals
       SET generated_summary = trim(p_summary),
           generated_metadata = v_metadata,
           generated_at = clock_timestamp()
     WHERE id = v_id;
  ELSE
    INSERT INTO public.evidence_summary_approvals (
      organization_id, evidence_id, approval_status, generated_summary, generated_mode, generated_metadata, generated_at
    ) VALUES (
      p_organization_id, p_evidence_id, 'pending', trim(p_summary), 'cctv_vision_llm_scene_synopsis', v_metadata, clock_timestamp()
    ) RETURNING id INTO v_id;
  END IF;
  RETURN v_id;
END;
$function$;
COMMENT ON FUNCTION "public"."record_cctv_scene_synopsis"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_summary text, p_metadata jsonb) IS 'Service-only CCTV writer. Stores an unverified vision-LLM scene synopsis as a pending evidence_summary_approvals row (generated_mode = cctv_vision_llm_scene_synopsis); a human must review it before it is relied on as fact.';
REVOKE ALL ON FUNCTION "public"."record_cctv_scene_synopsis"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_summary text, p_metadata jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_scene_synopsis"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_summary text, p_metadata jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_scene_synopsis"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_summary text, p_metadata jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_cctv_source_hash"(p_evidence_id uuid, p_sha256 text, p_size_bytes bigint DEFAULT NULL::bigint)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_hash text := lower(nullif(trim(coalesce(p_sha256, '')), ''));
BEGIN
  IF auth.role() <> 'service_role' AND session_user NOT IN ('postgres', 'supabase_admin') THEN RAISE EXCEPTION 'Service identity required'; END IF;
  IF v_hash IS NULL OR v_hash !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'A 64-character hex sha256 is required'; END IF;
  UPDATE public.evidence_items
     SET sha256_hash = v_hash,
         metadata = metadata || jsonb_strip_nulls(jsonb_build_object('source_sha256', v_hash, 'source_size_bytes', p_size_bytes, 'source_hashed_at', clock_timestamp()))
   WHERE id = p_evidence_id AND locked_at IS NULL AND (sha256_hash IS NULL OR lower(sha256_hash) = v_hash);
  RETURN FOUND;
END $function$;
COMMENT ON FUNCTION "public"."record_cctv_source_hash"(p_evidence_id uuid, p_sha256 text, p_size_bytes bigint) IS 'Service-only, write-once: records the sha256 (and size/time provenance) of the stored source bytes. Repeating the same hash refreshes provenance; a different hash or a sealed row changes nothing and returns false.';
REVOKE ALL ON FUNCTION "public"."record_cctv_source_hash"(p_evidence_id uuid, p_sha256 text, p_size_bytes bigint) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_source_hash"(p_evidence_id uuid, p_sha256 text, p_size_bytes bigint) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_source_hash"(p_evidence_id uuid, p_sha256 text, p_size_bytes bigint) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_cctv_vehicle_attribute_perception_envelopes"(p_job_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_job public.inference_jobs%rowtype;
  v_evidence public.evidence_items%rowtype;
  v_observation public.cctv_entity_observations%rowtype;
  v_derivative public.cctv_observation_derivatives%rowtype;
  v_envelope_id uuid;
  v_idempotency_key text;
  v_field_key text;
  v_value text;
  v_confidence real;
  v_recorded integer := 0;
  v_replayed integer := 0;
  v_field_count integer;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;

  SELECT * INTO v_job FROM public.inference_jobs WHERE id = p_job_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Inference job is missing'; END IF;
  SELECT * INTO v_evidence FROM public.evidence_items WHERE id = v_job.evidence_item_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Evidence item is missing'; END IF;
  IF v_evidence.organization_id <> v_job.organization_id THEN
    RAISE EXCEPTION 'Evidence and inference job organization mismatch';
  END IF;
  IF lower(coalesce(v_evidence.sha256_hash, '')) !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'CCTV source custody SHA-256 is required before vehicle attributes can be recorded';
  END IF;

  FOR v_observation IN
    SELECT o.*
    FROM public.cctv_entity_observations o
    WHERE o.inference_job_id = p_job_id
      AND o.organization_id = v_job.organization_id
      AND o.entity_kind = 'vehicle'
      AND o.review_state <> 'superseded'
      AND (
        nullif(trim(o.attributes->>'make'), '') IS NOT NULL
        OR nullif(trim(o.attributes->>'model'), '') IS NOT NULL
        OR nullif(trim(o.attributes->>'colour'), '') IS NOT NULL
        OR nullif(trim(o.attributes->>'body_type'), '') IS NOT NULL
        OR nullif(trim(o.attributes->>'year'), '') IS NOT NULL
      )
    ORDER BY o.observed_at, o.id
  LOOP
    v_idempotency_key := 'cctv-vehicle-attributes:' || v_observation.id::text
      || ':v1:' || lower(v_evidence.sha256_hash);
    SELECT id INTO v_envelope_id
    FROM public.perception_evidence_envelopes
    WHERE organization_id = v_job.organization_id
      AND idempotency_key = v_idempotency_key;
    IF FOUND THEN
      v_replayed := v_replayed + 1;
      CONTINUE;
    END IF;

    SELECT d.* INTO v_derivative
    FROM public.cctv_observation_derivatives d
    WHERE d.observation_id = v_observation.id
    ORDER BY d.created_at DESC
    LIMIT 1;

    INSERT INTO public.perception_evidence_envelopes (
      organization_id, schema_version, domain, source_kind, source_sha256,
      evidence_item_id, inference_job_id, source_receipt, model_receipt,
      derivative_receipts, status, idempotency_key
    ) VALUES (
      v_job.organization_id, 1, 'cctv_vehicle_attributes',
      CASE WHEN v_evidence.evidence_kind IN ('photo', 'image') THEN 'image' ELSE 'video' END,
      lower(v_evidence.sha256_hash), v_evidence.id, v_job.id,
      jsonb_strip_nulls(jsonb_build_object(
        'cctv_entity_observation_id', v_observation.id,
        'source_event_id', v_observation.source_event_id,
        'observed_at', v_observation.observed_at,
        'observed_to', v_observation.observed_to,
        'source_frame_sha256', v_observation.frame_sha256,
        'location_id', v_observation.location_id,
        'canonical_place_id', v_observation.canonical_place_id,
        'authoritative_source_preserved', true
      )),
      jsonb_strip_nulls(jsonb_build_object(
        'attribute_provider', coalesce(
          v_observation.attributes->'vehicle_attribute_source',
          v_observation.attributes->'inference_provider'
        ),
        'attribute_model', v_observation.attributes->'vehicle_attribute_model',
        'attribute_status', v_observation.attributes->'vehicle_attribute_status',
        'crop_status', v_observation.attributes->'vehicle_crop_status',
        'make_model_source', v_observation.attributes->'make_model_source',
        'appearance_embedding_included', false
      )),
      CASE WHEN v_derivative.id IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(
        jsonb_strip_nulls(jsonb_build_object(
          'cctv_observation_derivative_id', v_derivative.id,
          'provider', v_derivative.provider,
          'original_sha256', v_derivative.original_sha256,
          'enhanced_sha256', v_derivative.enhanced_sha256,
          'enhancement_profile', v_derivative.enhancement_profile,
          'generative', v_derivative.generative
        ))
      ) END,
      'manual_review_required',
      v_idempotency_key
    )
    RETURNING id INTO v_envelope_id;

    v_field_count := 0;
    FOR v_field_key, v_value, v_confidence IN
      SELECT *
      FROM (VALUES
        ('vehicle.make', nullif(trim(v_observation.attributes->>'make'), ''), NULL::real),
        ('vehicle.model', nullif(trim(v_observation.attributes->>'model'), ''), NULL::real),
        ('vehicle.colour', nullif(trim(v_observation.attributes->>'colour'), ''),
          coalesce(
            CASE WHEN v_observation.attributes->>'colour_confidence' ~ '^[0-9]+([.][0-9]+)?$'
              THEN (v_observation.attributes->>'colour_confidence')::real END,
            CASE WHEN v_observation.attributes->>'attribute_confidence' ~ '^[0-9]+([.][0-9]+)?$'
              THEN (v_observation.attributes->>'attribute_confidence')::real END
          )),
        ('vehicle.body_type', nullif(trim(v_observation.attributes->>'body_type'), ''),
          coalesce(
            CASE WHEN v_observation.attributes->>'body_type_confidence' ~ '^[0-9]+([.][0-9]+)?$'
              THEN (v_observation.attributes->>'body_type_confidence')::real END,
            CASE WHEN v_observation.attributes->>'attribute_confidence' ~ '^[0-9]+([.][0-9]+)?$'
              THEN (v_observation.attributes->>'attribute_confidence')::real END
          )),
        ('vehicle.year', nullif(trim(v_observation.attributes->>'year'), ''), NULL::real)
      ) AS candidate(field_key, candidate_value, confidence)
      WHERE candidate_value IS NOT NULL
    LOOP
      INSERT INTO public.perception_evidence_fields (
        organization_id, envelope_id, field_key, candidate_ordinal, value_type,
        candidate_value, normalized_value, candidate_payload, raw_confidence,
        source_locations, consensus_rule, authority_state, review_required
      ) VALUES (
        v_job.organization_id, v_envelope_id, v_field_key, 0,
        CASE WHEN v_field_key = 'vehicle.year' THEN 'number' ELSE 'text' END,
        v_value, lower(trim(v_value)),
        jsonb_strip_nulls(jsonb_build_object(
          'source', CASE
            WHEN v_field_key IN ('vehicle.make','vehicle.model')
              THEN v_observation.attributes->'make_model_source'
            ELSE coalesce(
              v_observation.attributes->'vehicle_attribute_source',
              v_observation.attributes->'inference_provider'
            )
          END,
          'model', v_observation.attributes->'vehicle_attribute_model',
          'attribute_status', v_observation.attributes->'vehicle_attribute_status',
          'crop_status', v_observation.attributes->'vehicle_crop_status',
          'quality_state', v_observation.quality_state,
          'appearance_embedding_included', false
        )),
        v_confidence,
        jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
          'source_event_id', v_observation.source_event_id,
          'frame_sha256', v_observation.frame_sha256,
          'bbox', v_observation.attributes->'bbox',
          'observed_at', v_observation.observed_at,
          'observed_to', v_observation.observed_to
        ))),
        CASE
          WHEN v_field_key IN ('vehicle.make','vehicle.model')
            THEN 'unverified_vision_llm_hint_human_review_required_v1'
          WHEN coalesce(
            v_observation.attributes->>'vehicle_attribute_source',
            v_observation.attributes->>'inference_provider',
            ''
          ) = 'openvino_vehicle_attributes_0039'
            THEN 'trained_vehicle_attribute_candidate_human_review_required_v1'
          ELSE 'legacy_or_heuristic_vehicle_attribute_human_review_required_v1'
        END,
        CASE
          WHEN v_observation.quality_state IN ('glitch','flare','ir_switch','degraded','occluded')
            THEN 'insufficient'
          ELSE 'candidate'
        END,
        true
      );
      v_field_count := v_field_count + 1;
    END LOOP;

    IF v_field_count = 0 THEN
      RAISE EXCEPTION 'Vehicle attribute envelope requires at least one candidate field';
    END IF;
    PERFORM public.apply_cctv_vehicle_attribute_review_to_perception(v_observation.id);

    INSERT INTO public.audit_log (
      organization_id, actor_user_id, action, target_table, target_id, metadata
    ) VALUES (
      v_job.organization_id, auth.uid(), 'cctv_vehicle_attribute_perception_recorded',
      'perception_evidence_envelopes', v_envelope_id,
      jsonb_build_object(
        'inference_job_id', p_job_id,
        'cctv_entity_observation_id', v_observation.id,
        'field_count', v_field_count,
        'appearance_embedding_included', false
      )
    );
    v_recorded := v_recorded + 1;
  END LOOP;

  RETURN jsonb_build_object('recorded', v_recorded, 'replayed', v_replayed);
END;
$function$;
COMMENT ON FUNCTION "public"."record_cctv_vehicle_attribute_perception_envelopes"(p_job_id uuid) IS 'Service-only replay-safe projection of CCTV vehicle attribute candidates into shared receipts. Machine attributes never become canonical without the existing human review action.';
REVOKE ALL ON FUNCTION "public"."record_cctv_vehicle_attribute_perception_envelopes"(p_job_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_vehicle_attribute_perception_envelopes"(p_job_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_vehicle_attribute_perception_envelopes"(p_job_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_court_appearance_outcome"(p_appearance_id uuid, p_expected_status text, p_status text, p_actual_start timestamp with time zone DEFAULT NULL::timestamp with time zone, p_actual_end timestamp with time zone DEFAULT NULL::timestamp with time zone, p_outcome text DEFAULT NULL::text)
 RETURNS court_appearances
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_appearance public.court_appearances%rowtype;
  v_outcome text := nullif(trim(coalesce(p_outcome, '')), '');
begin
  select c.* into v_appearance from public.court_appearances c where c.id = p_appearance_id for update;
  if not found then
    raise exception 'Court appearance not found';
  end if;

  if v_appearance.officer_user_id <> v_actor and not public.is_admin_for_org(v_appearance.organization_id) then
    raise exception 'Not authorised to update this court appearance';
  end if;

  if v_appearance.status <> p_expected_status then
    raise exception 'Court appearance changed from expected status % to %', p_expected_status, v_appearance.status;
  end if;

  if p_status not in ('attended', 'adjourned', 'cancelled', 'excused') then
    raise exception 'Unsupported court appearance outcome status';
  end if;

  if p_status = 'attended' and (p_actual_start is null or p_actual_end is null) then
    raise exception 'Attended appearances require actual start and end times';
  end if;

  if p_actual_end is not null and p_actual_start is not null and p_actual_end <= p_actual_start then
    raise exception 'Court appearance must end after it starts';
  end if;

  update public.court_appearances
  set status = p_status, actual_start = p_actual_start, actual_end = p_actual_end, outcome = v_outcome
  where id = v_appearance.id
  returning * into v_appearance;

  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (
    v_appearance.organization_id, v_actor, 'court_appearance_outcome_recorded', 'court_appearances', v_appearance.id,
    jsonb_build_object(
      'status', p_status,
      'actual_start', p_actual_start,
      'actual_end', p_actual_end,
      'is_overtime', v_appearance.is_overtime,
      'outcome', v_outcome
    )
  );

  return v_appearance;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."record_court_appearance_outcome"(p_appearance_id uuid, p_expected_status text, p_status text, p_actual_start timestamp with time zone, p_actual_end timestamp with time zone, p_outcome text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_court_appearance_outcome"(p_appearance_id uuid, p_expected_status text, p_status text, p_actual_start timestamp with time zone, p_actual_end timestamp with time zone, p_outcome text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_court_appearance_outcome"(p_appearance_id uuid, p_expected_status text, p_status text, p_actual_start timestamp with time zone, p_actual_end timestamp with time zone, p_outcome text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."record_court_appearance_outcome"(p_appearance_id uuid, p_expected_status text, p_status text, p_actual_start timestamp with time zone, p_actual_end timestamp with time zone, p_outcome text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_finance_external_sync"(p_request_id uuid, p_sync_cursor text DEFAULT NULL::text, p_error text DEFAULT NULL::text)
 RETURNS finance_external_connection_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_request public.finance_external_connection_requests%rowtype;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Provider adapter execution only'; END IF;
  SELECT * INTO v_request FROM public.finance_external_connection_requests WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Finance connection request not found'; END IF;
  UPDATE public.finance_external_connection_requests
  SET status = CASE WHEN p_error IS NULL THEN 'connected' ELSE 'failed' END, sync_cursor = COALESCE(p_sync_cursor, sync_cursor), last_sync_at = CASE WHEN p_error IS NULL THEN now() ELSE last_sync_at END, last_error = nullif(trim(p_error), ''), updated_at = now()
  WHERE id = p_request_id
  RETURNING * INTO v_request;
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_request.organization_id, NULL, 'finance_external_sync_recorded', 'finance_external_connection_requests', v_request.id, jsonb_build_object('provider_type', v_request.provider_type, 'adapter_name', v_request.adapter_name, 'success', p_error IS NULL));
  RETURN v_request;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."record_finance_external_sync"(p_request_id uuid, p_sync_cursor text, p_error text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_finance_external_sync"(p_request_id uuid, p_sync_cursor text, p_error text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_finance_external_sync"(p_request_id uuid, p_sync_cursor text, p_error text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_finance_inventory_transaction"(p_item_id uuid, p_location_id uuid, p_transaction_type text, p_quantity numeric, p_unit_cost numeric, p_idempotency_key text, p_source_reference text DEFAULT NULL::text, p_target_location_id uuid DEFAULT NULL::uuid, p_asset_id uuid DEFAULT NULL::uuid, p_dispatch_job_id uuid DEFAULT NULL::uuid, p_investigation_id uuid DEFAULT NULL::uuid)
 RETURNS finance_inventory_transactions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_item public.finance_item_catalog%rowtype;
  v_location public.finance_inventory_locations%rowtype;
  v_transaction public.finance_inventory_transactions%rowtype;
  v_balance public.finance_inventory_balances%rowtype;
BEGIN
  SELECT organization_id INTO v_org FROM public.user_profiles WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_org IS NULL OR NOT public.is_admin_for_org(v_org) THEN RAISE EXCEPTION 'Active finance or operations administrator required'; END IF;
  IF p_quantity IS NULL OR p_quantity <= 0 OR p_unit_cost IS NULL OR p_unit_cost < 0 THEN RAISE EXCEPTION 'Quantity and unit cost must be valid positive values'; END IF;
  IF p_idempotency_key IS NULL OR trim(p_idempotency_key) = '' THEN RAISE EXCEPTION 'Idempotency key is required'; END IF;
  SELECT * INTO v_item FROM public.finance_item_catalog WHERE id = p_item_id AND organization_id = v_org AND active;
  IF NOT FOUND THEN RAISE EXCEPTION 'Active inventory item not found in organization'; END IF;
  SELECT * INTO v_location FROM public.finance_inventory_locations WHERE id = p_location_id AND organization_id = v_org AND active;
  IF NOT FOUND THEN RAISE EXCEPTION 'Active inventory location not found in organization'; END IF;
  SELECT * INTO v_transaction FROM public.finance_inventory_transactions WHERE organization_id = v_org AND idempotency_key = trim(p_idempotency_key);
  IF FOUND THEN RETURN v_transaction; END IF;
  IF p_transaction_type IN ('issue','consumption','write_off','transfer_out','quarantine') THEN
    SELECT * INTO v_balance FROM public.finance_inventory_balances WHERE item_id = p_item_id AND location_id = p_location_id FOR UPDATE;
    IF NOT FOUND OR v_balance.on_hand - v_balance.reserved < p_quantity THEN RAISE EXCEPTION 'Insufficient available inventory'; END IF;
    UPDATE public.finance_inventory_balances SET on_hand = on_hand - p_quantity, updated_at = now() WHERE item_id = p_item_id AND location_id = p_location_id;
  ELSE
    INSERT INTO public.finance_inventory_balances(item_id, location_id, organization_id, on_hand) VALUES (p_item_id, p_location_id, v_org, p_quantity)
    ON CONFLICT (item_id, location_id) DO UPDATE SET on_hand = public.finance_inventory_balances.on_hand + excluded.on_hand, updated_at = now();
  END IF;
  INSERT INTO public.finance_inventory_transactions(organization_id,item_id,location_id,transaction_type,quantity,unit_cost,idempotency_key,source_reference,location_id_target,dispatch_job_id,investigation_id,asset_id,created_by)
  VALUES(v_org,p_item_id,p_location_id,p_transaction_type,p_quantity,p_unit_cost,trim(p_idempotency_key),nullif(trim(p_source_reference),''),p_target_location_id,p_dispatch_job_id,p_investigation_id,p_asset_id,v_actor)
  RETURNING * INTO v_transaction;
  INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
  VALUES(v_org,v_actor,'finance_inventory_transaction_recorded','finance_inventory_transactions',v_transaction.id,jsonb_build_object('item_id',p_item_id,'location_id',p_location_id,'transaction_type',p_transaction_type,'quantity',p_quantity,'unit_cost',p_unit_cost,'idempotency_key',trim(p_idempotency_key)));
  RETURN v_transaction;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."record_finance_inventory_transaction"(p_item_id uuid, p_location_id uuid, p_transaction_type text, p_quantity numeric, p_unit_cost numeric, p_idempotency_key text, p_source_reference text, p_target_location_id uuid, p_asset_id uuid, p_dispatch_job_id uuid, p_investigation_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_finance_inventory_transaction"(p_item_id uuid, p_location_id uuid, p_transaction_type text, p_quantity numeric, p_unit_cost numeric, p_idempotency_key text, p_source_reference text, p_target_location_id uuid, p_asset_id uuid, p_dispatch_job_id uuid, p_investigation_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_finance_inventory_transaction"(p_item_id uuid, p_location_id uuid, p_transaction_type text, p_quantity numeric, p_unit_cost numeric, p_idempotency_key text, p_source_reference text, p_target_location_id uuid, p_asset_id uuid, p_dispatch_job_id uuid, p_investigation_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."record_finance_inventory_transaction"(p_item_id uuid, p_location_id uuid, p_transaction_type text, p_quantity numeric, p_unit_cost numeric, p_idempotency_key text, p_source_reference text, p_target_location_id uuid, p_asset_id uuid, p_dispatch_job_id uuid, p_investigation_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_finance_service_cost"(p_pl_period_id uuid, p_service_agreement_id uuid, p_cost_type text, p_quantity numeric, p_unit_cost numeric, p_source_document_type text, p_source_reference text, p_work_unit_id uuid DEFAULT NULL::uuid, p_shift_id uuid DEFAULT NULL::uuid, p_dispatch_job_id uuid DEFAULT NULL::uuid, p_investigation_id uuid DEFAULT NULL::uuid, p_asset_id uuid DEFAULT NULL::uuid)
 RETURNS finance_service_costs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_period public.finance_pl_periods%rowtype;
  v_agreement public.service_agreements%rowtype;
  v_cost public.finance_service_costs%rowtype;
BEGIN
  SELECT organization_id INTO v_org FROM public.user_profiles WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_org IS NULL OR NOT public.is_admin_for_org(v_org) THEN RAISE EXCEPTION 'Active finance administrator required'; END IF;
  IF p_quantity IS NULL OR p_quantity <= 0 OR p_unit_cost IS NULL OR p_unit_cost < 0 THEN RAISE EXCEPTION 'Quantity and unit cost must be valid positive values'; END IF;

  SELECT * INTO v_period FROM public.finance_pl_periods WHERE id = p_pl_period_id AND organization_id = v_org;
  IF NOT FOUND THEN RAISE EXCEPTION 'P&L period not found in organization'; END IF;
  IF v_period.status = 'closed' THEN RAISE EXCEPTION 'Cannot record costs in a closed P&L period'; END IF;

  SELECT * INTO v_agreement FROM public.service_agreements WHERE id = p_service_agreement_id AND provider_organization_id = v_org;
  IF NOT FOUND THEN RAISE EXCEPTION 'Service agreement not found in organization'; END IF;

  INSERT INTO public.finance_service_costs(
    organization_id, pl_period_id, service_agreement_id, client_organization_id, cost_type,
    work_unit_id, shift_id, dispatch_job_id, investigation_id, asset_id,
    source_document_type, source_reference, quantity, unit_cost, total_cost, created_by
  )
  VALUES (
    v_org, p_pl_period_id, p_service_agreement_id, v_agreement.client_organization_id, p_cost_type,
    p_work_unit_id, p_shift_id, p_dispatch_job_id, p_investigation_id, p_asset_id,
    p_source_document_type, trim(p_source_reference), p_quantity, p_unit_cost, round(p_quantity * p_unit_cost, 2), v_actor
  )
  RETURNING * INTO v_cost;

  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_org, v_actor, 'finance_service_cost_recorded', 'finance_service_costs', v_cost.id,
    jsonb_build_object('pl_period_id', p_pl_period_id, 'service_agreement_id', p_service_agreement_id,
      'cost_type', p_cost_type, 'quantity', p_quantity, 'unit_cost', p_unit_cost, 'source_reference', trim(p_source_reference)));

  RETURN v_cost;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."record_finance_service_cost"(p_pl_period_id uuid, p_service_agreement_id uuid, p_cost_type text, p_quantity numeric, p_unit_cost numeric, p_source_document_type text, p_source_reference text, p_work_unit_id uuid, p_shift_id uuid, p_dispatch_job_id uuid, p_investigation_id uuid, p_asset_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_finance_service_cost"(p_pl_period_id uuid, p_service_agreement_id uuid, p_cost_type text, p_quantity numeric, p_unit_cost numeric, p_source_document_type text, p_source_reference text, p_work_unit_id uuid, p_shift_id uuid, p_dispatch_job_id uuid, p_investigation_id uuid, p_asset_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_finance_service_cost"(p_pl_period_id uuid, p_service_agreement_id uuid, p_cost_type text, p_quantity numeric, p_unit_cost numeric, p_source_document_type text, p_source_reference text, p_work_unit_id uuid, p_shift_id uuid, p_dispatch_job_id uuid, p_investigation_id uuid, p_asset_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."record_finance_service_cost"(p_pl_period_id uuid, p_service_agreement_id uuid, p_cost_type text, p_quantity numeric, p_unit_cost numeric, p_source_document_type text, p_source_reference text, p_work_unit_id uuid, p_shift_id uuid, p_dispatch_job_id uuid, p_investigation_id uuid, p_asset_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_fuel_price_observation"(p_client_request_id uuid, p_organization_id uuid, p_fuel_type text, p_observed_on date, p_price_per_litre numeric, p_source_name text, p_source_url text, p_source_published_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_source_reference text DEFAULT NULL::text, p_source_hash text DEFAULT NULL::text)
 RETURNS fuel_price_observations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_row public.fuel_price_observations%rowtype;
begin
  if p_client_request_id is null then raise exception 'client_request_id is required'; end if;
  if v_actor is null or not public.is_admin_for_org(p_organization_id) then raise exception 'Active organisation administrator required'; end if;
  if p_fuel_type not in ('petrol', 'diesel', 'lpg', 'other') then raise exception 'Unsupported fuel type'; end if;
  if p_observed_on is null or p_price_per_litre is null or p_price_per_litre <= 0 then raise exception 'Observed date and positive price are required'; end if;
  if nullif(trim(coalesce(p_source_name, '')), '') is null or nullif(trim(coalesce(p_source_url, '')), '') is null then raise exception 'Source name and URL are required'; end if;
  select * into v_row from public.fuel_price_observations where organization_id = p_organization_id and source_reference = p_client_request_id::text;
  if found then return v_row; end if;
  insert into public.fuel_price_observations (organization_id, fuel_type, observed_on, price_per_litre, source_name, source_url, source_published_at, source_reference, source_hash, created_by)
  values (p_organization_id, p_fuel_type, p_observed_on, p_price_per_litre, trim(p_source_name), trim(p_source_url), p_source_published_at, coalesce(nullif(trim(p_source_reference), ''), p_client_request_id::text), nullif(trim(p_source_hash), ''), v_actor)
  on conflict (organization_id, fuel_type, observed_on, source_url, source_reference) do update
    set price_per_litre = excluded.price_per_litre, source_published_at = excluded.source_published_at, source_hash = excluded.source_hash
  returning * into v_row;
  insert into public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (p_organization_id, v_actor, 'fuel_price_observation_recorded', 'fuel_price_observations', v_row.id,
          jsonb_build_object('fuel_type', v_row.fuel_type, 'observed_on', v_row.observed_on, 'price_per_litre', v_row.price_per_litre, 'source_name', v_row.source_name, 'source_url', v_row.source_url));
  return v_row;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."record_fuel_price_observation"(p_client_request_id uuid, p_organization_id uuid, p_fuel_type text, p_observed_on date, p_price_per_litre numeric, p_source_name text, p_source_url text, p_source_published_at timestamp with time zone, p_source_reference text, p_source_hash text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_fuel_price_observation"(p_client_request_id uuid, p_organization_id uuid, p_fuel_type text, p_observed_on date, p_price_per_litre numeric, p_source_name text, p_source_url text, p_source_published_at timestamp with time zone, p_source_reference text, p_source_hash text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_fuel_price_observation"(p_client_request_id uuid, p_organization_id uuid, p_fuel_type text, p_observed_on date, p_price_per_litre numeric, p_source_name text, p_source_url text, p_source_published_at timestamp with time zone, p_source_reference text, p_source_hash text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."record_identity_person_details"(p_organization_id uuid, p_person_record_id uuid, p_action text, p_fields jsonb, p_distinct_from uuid[], p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_fields jsonb := coalesce(p_fields, '{}'::jsonb);
  v_name text;
  v_norm text;
  v_dob date;
  v_details jsonb;
  v_matches uuid[];
  v_person public.person_records%rowtype;
  v_current jsonb;
  v_canonical_id uuid;
  v_result jsonb;
BEGIN
  IF v_actor IS NULL OR NOT public.is_admin_for_org(p_organization_id) THEN
    RAISE EXCEPTION 'Identity registry administrator access required' USING ERRCODE = '42501';
  END IF;
  IF p_action IS NULL OR p_action NOT IN ('create', 'update') THEN RAISE EXCEPTION 'Unsupported person action'; END IF;
  IF coalesce(btrim(p_reason), '') = '' THEN RAISE EXCEPTION 'A reason is required for the identity audit trail'; END IF;
  IF jsonb_typeof(v_fields) <> 'object' THEN RAISE EXCEPTION 'Person details must be an object'; END IF;
  IF nullif(btrim(v_fields->>'date_of_birth'), '') IS NOT NULL THEN
    v_dob := (v_fields->>'date_of_birth')::date;
    IF v_dob > current_date THEN RAISE EXCEPTION 'Date of birth cannot be in the future'; END IF;
  END IF;
  v_details := jsonb_strip_nulls(jsonb_build_object(
    'category', nullif(btrim(v_fields->>'category'), ''),
    'notes', nullif(btrim(v_fields->>'notes'), ''),
    'email', nullif(btrim(v_fields->>'email'), ''),
    'phone', nullif(btrim(v_fields->>'phone'), ''),
    'date_of_birth', v_dob
  ));
  IF length(v_details->>'category') > 120 OR length(v_details->>'notes') > 1000
    OR length(v_details->>'email') > 254 OR length(v_details->>'phone') > 40 THEN
    RAISE EXCEPTION 'A person detail is longer than the register allows';
  END IF;

  IF p_action = 'create' THEN
    v_name := nullif(btrim(regexp_replace(coalesce(v_fields->>'display_name', ''), '\s+', ' ', 'g')), '');
    v_norm := public.normalize_person_name(v_name);
    IF coalesce(v_norm, '') = '' THEN RAISE EXCEPTION 'Person name is required'; END IF;
    IF length(v_name) > 120 THEN RAISE EXCEPTION 'Person name is longer than the register allows'; END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended('identity_person_create:' || p_organization_id::text || ':' || v_norm, 0));
    SELECT coalesce(array_agg(person.id ORDER BY person.id), '{}'::uuid[]) INTO v_matches
    FROM public.person_records AS person
    LEFT JOIN public.canonical_person_links AS link
      ON link.source_table = 'person_records' AND link.source_id = person.id
    LEFT JOIN public.canonical_people AS canonical ON canonical.id = link.canonical_person_id
    WHERE person.organization_id = p_organization_id
      AND NOT (person.metadata ? 'merged_into_person_record_id')
      AND NOT (person.metadata ? 'resolved_into_person_record_id')
      AND NOT (person.id = ANY (coalesce(p_distinct_from, '{}'::uuid[])))
      AND (public.normalize_person_name(person.display_name) = v_norm
        OR EXISTS (SELECT 1 FROM public.person_record_aliases AS alias
          WHERE alias.person_record_id = person.id AND alias.active AND public.normalize_person_name(alias.alias) = v_norm))
      AND (v_dob IS NULL
        OR coalesce(nullif(person.metadata->'profile_details'->>'date_of_birth', '')::date, canonical.date_of_birth) IS NULL
        OR coalesce(nullif(person.metadata->'profile_details'->>'date_of_birth', '')::date, canonical.date_of_birth) = v_dob);
    IF cardinality(v_matches) > 1 THEN
      RAISE EXCEPTION 'AMBIGUOUS_PERSON: % people named % are already recorded', cardinality(v_matches), v_name;
    END IF;
    IF cardinality(v_matches) = 1 THEN
      SELECT * INTO v_person FROM public.person_records WHERE id = v_matches[1];
      RETURN jsonb_build_object('outcome', 'existing', 'person_record_id', v_person.id,
        'canonical_person_id', public.ensure_canonical_person_for_record(v_person.id), 'display_name', v_person.display_name);
    END IF;
    v_result := public.manage_identity_person(p_organization_id, NULL, 'create',
      v_details || jsonb_build_object('display_name', v_name), btrim(p_reason));
    RETURN v_result || jsonb_build_object('outcome', 'created');
  END IF;

  IF v_details = '{}'::jsonb THEN RAISE EXCEPTION 'No person details were given'; END IF;
  SELECT * INTO v_person FROM public.person_records
  WHERE id = p_person_record_id AND organization_id = p_organization_id FOR UPDATE;
  IF v_person.id IS NULL THEN RAISE EXCEPTION 'Person record not found in this organization'; END IF;
  IF v_person.metadata ? 'merged_into_person_record_id' OR v_person.metadata ? 'resolved_into_person_record_id' THEN
    RAISE EXCEPTION 'This person has been merged into another record';
  END IF;
  v_current := coalesce(v_person.metadata->'profile_details', '{}'::jsonb);
  IF v_current @> v_details THEN
    SELECT link.canonical_person_id INTO v_canonical_id FROM public.canonical_person_links AS link
    WHERE link.source_table = 'person_records' AND link.source_id = v_person.id LIMIT 1;
    RETURN jsonb_build_object('outcome', 'unchanged', 'person_record_id', v_person.id,
      'canonical_person_id', v_canonical_id, 'display_name', v_person.display_name);
  END IF;
  v_canonical_id := public.ensure_canonical_person_for_record(v_person.id);
  UPDATE public.person_records
  SET metadata = metadata || jsonb_build_object('profile_details', v_current || v_details)
  WHERE id = v_person.id;
  IF v_dob IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.canonical_person_links
    WHERE canonical_person_id = v_canonical_id AND organization_id IS DISTINCT FROM p_organization_id
  ) THEN
    UPDATE public.canonical_people SET date_of_birth = v_dob, updated_at = clock_timestamp()
    WHERE id = v_canonical_id AND date_of_birth IS DISTINCT FROM v_dob;
  END IF;
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (p_organization_id, v_actor, 'identity_person_details_update', 'person_records', v_person.id,
    jsonb_build_object('canonical_person_id', v_canonical_id, 'reason', btrim(p_reason),
      'fields', array(SELECT jsonb_object_keys(v_details))));
  RETURN jsonb_build_object('outcome', 'updated', 'person_record_id', v_person.id,
    'canonical_person_id', v_canonical_id, 'display_name', v_person.display_name);
END;
$function$;
COMMENT ON FUNCTION "public"."record_identity_person_details"(p_organization_id uuid, p_person_record_id uuid, p_action text, p_fields jsonb, p_distinct_from uuid[], p_reason text) IS 'Administrator person step for confirmed chat updates. create is serialised per organisation and normalised name and returns an existing exact-name person with no conflicting date of birth instead of inserting a duplicate (p_distinct_from excludes records the user confirmed are different people); update changes profile details only, under the row lock, never the name, and refuses merged or resolved records.';
REVOKE ALL ON FUNCTION "public"."record_identity_person_details"(p_organization_id uuid, p_person_record_id uuid, p_action text, p_fields jsonb, p_distinct_from uuid[], p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_identity_person_details"(p_organization_id uuid, p_person_record_id uuid, p_action text, p_fields jsonb, p_distinct_from uuid[], p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_identity_person_details"(p_organization_id uuid, p_person_record_id uuid, p_action text, p_fields jsonb, p_distinct_from uuid[], p_reason text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."record_incident_person_identity"(p_incident_id uuid, p_involvement_role text, p_notes text, p_person_record_id uuid DEFAULT NULL::uuid, p_staff_profile_id uuid DEFAULT NULL::uuid, p_display_name text DEFAULT NULL::text, p_identity_document_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid:=auth.uid();
  v_incident public.incidents%rowtype;
  v_person_id uuid:=p_person_record_id;
  v_canonical_id uuid;
  v_link public.incident_person_links%rowtype;
  v_source text;
BEGIN
  SELECT * INTO v_incident FROM public.incidents WHERE id=p_incident_id FOR UPDATE;
  IF v_incident.id IS NULL THEN RAISE EXCEPTION 'Incident not found'; END IF;
  IF v_actor IS NULL OR NOT public.can_record_incident_person(v_incident.id,v_actor) THEN RAISE EXCEPTION 'Only the assigned officer or an administrator can record a person for this incident'; END IF;
  IF p_involvement_role NOT IN ('subject','reporting_party','witness','affected_person','staff_involved','other') THEN RAISE EXCEPTION 'Choose a valid involvement role'; END IF;
  IF coalesce(trim(p_notes),'')='' THEN RAISE EXCEPTION 'Record how the identity was obtained'; END IF;
  IF p_person_record_id IS NOT NULL AND p_staff_profile_id IS NOT NULL THEN RAISE EXCEPTION 'Choose either a person record or a staff profile'; END IF;
  IF p_identity_document_id IS NOT NULL AND NOT public.is_admin_for_org(v_incident.organization_id) THEN RAISE EXCEPTION 'Only an administrator can link approved identity evidence'; END IF;

  IF p_staff_profile_id IS NOT NULL THEN
    IF NOT EXISTS(SELECT 1 FROM public.staff_profiles WHERE id=p_staff_profile_id AND organization_id=v_incident.organization_id) THEN RAISE EXCEPTION 'Staff profile is outside the incident organization'; END IF;
    SELECT ensured.canonical_person_id,ensured.person_record_id INTO v_canonical_id,v_person_id FROM public.ensure_canonical_person_for_staff(p_staff_profile_id) ensured;
    v_source:='staff_profile';
  ELSIF v_person_id IS NOT NULL THEN
    IF NOT EXISTS(SELECT 1 FROM public.person_records WHERE id=v_person_id AND organization_id=v_incident.organization_id) THEN RAISE EXCEPTION 'Person record is outside the incident organization'; END IF;
    v_canonical_id:=public.ensure_canonical_person_for_record(v_person_id);
    v_source:='manual_link';
  ELSE
    IF nullif(trim(p_display_name),'') IS NULL THEN RAISE EXCEPTION 'Enter the name stated or shown on the identity document'; END IF;
    INSERT INTO public.person_records(organization_id,display_name,review_state,metadata)
    VALUES(v_incident.organization_id,trim(p_display_name),'manual_review_required',jsonb_build_object(
      'profile_details',jsonb_build_object('category','Incident identity'),
      'created_from','incident_identity_capture','incident_id',v_incident.id,'recorded_by',v_actor)) RETURNING id INTO v_person_id;
    v_canonical_id:=public.ensure_canonical_person_for_record(v_person_id);
    v_source:='stated_identity';
  END IF;

  IF p_identity_document_id IS NOT NULL AND NOT EXISTS(
    SELECT 1 FROM public.person_identity_documents document
    WHERE document.id=p_identity_document_id AND document.organization_id=v_incident.organization_id
      AND document.person_record_id=v_person_id AND document.review_state='approved'
  ) THEN RAISE EXCEPTION 'Approved identity evidence for this person is required'; END IF;
  IF p_identity_document_id IS NOT NULL THEN v_source:='identity_document'; END IF;

  INSERT INTO public.incident_person_links(organization_id,incident_id,canonical_person_id,person_record_id,staff_profile_id,identity_document_id,involvement_role,source_kind,notes,recorded_by)
  VALUES(v_incident.organization_id,v_incident.id,v_canonical_id,v_person_id,p_staff_profile_id,p_identity_document_id,p_involvement_role,v_source,trim(p_notes),v_actor)
  ON CONFLICT(incident_id,canonical_person_id,involvement_role) DO UPDATE SET
    person_record_id=coalesce(excluded.person_record_id,incident_person_links.person_record_id),
    staff_profile_id=coalesce(excluded.staff_profile_id,incident_person_links.staff_profile_id),
    identity_document_id=coalesce(excluded.identity_document_id,incident_person_links.identity_document_id),
    source_kind=excluded.source_kind,notes=excluded.notes,recorded_by=excluded.recorded_by,updated_at=clock_timestamp()
  RETURNING * INTO v_link;
  INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
  VALUES(v_incident.organization_id,v_actor,'incident_person_identity_recorded','incident_person_links',v_link.id,jsonb_build_object(
    'incident_id',v_incident.id,'canonical_person_id',v_canonical_id,'person_record_id',v_person_id,
    'staff_profile_id',p_staff_profile_id,'identity_document_id',p_identity_document_id,
    'involvement_role',p_involvement_role,'source_kind',v_source));
  RETURN jsonb_build_object('incident_person_link_id',v_link.id,'incident_id',v_incident.id,
    'canonical_person_id',v_canonical_id,'person_record_id',v_person_id,'staff_profile_id',p_staff_profile_id,
    'review_state',(SELECT review_state FROM public.person_records WHERE id=v_person_id));
END;
$function$;
COMMENT ON FUNCTION "public"."record_incident_person_identity"(p_incident_id uuid, p_involvement_role text, p_notes text, p_person_record_id uuid, p_staff_profile_id uuid, p_display_name text, p_identity_document_id uuid) IS 'Assigned-officer/admin path to record a stated, known, staff, or approved-document identity in an active incident. New identities remain manual-review-required.';
REVOKE ALL ON FUNCTION "public"."record_incident_person_identity"(p_incident_id uuid, p_involvement_role text, p_notes text, p_person_record_id uuid, p_staff_profile_id uuid, p_display_name text, p_identity_document_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_incident_person_identity"(p_incident_id uuid, p_involvement_role text, p_notes text, p_person_record_id uuid, p_staff_profile_id uuid, p_display_name text, p_identity_document_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_incident_person_identity"(p_incident_id uuid, p_involvement_role text, p_notes text, p_person_record_id uuid, p_staff_profile_id uuid, p_display_name text, p_identity_document_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."record_incident_person_identity"(p_incident_id uuid, p_involvement_role text, p_notes text, p_person_record_id uuid, p_staff_profile_id uuid, p_display_name text, p_identity_document_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_job_party_interaction"(p_client_request_id uuid, p_dispatch_job_id uuid, p_party_role text, p_mode text, p_occurred_at timestamp with time zone DEFAULT now(), p_summary text DEFAULT NULL::text, p_noise_assessment_id uuid DEFAULT NULL::uuid, p_shift_stop_id uuid DEFAULT NULL::uuid, p_gps_lat double precision DEFAULT NULL::double precision, p_gps_lng double precision DEFAULT NULL::double precision, p_gps_accuracy double precision DEFAULT NULL::double precision)
 RETURNS TABLE(id uuid, created boolean, occurred_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_org uuid;
  v_job public.dispatch_jobs%rowtype;
  v_existing public.job_party_interactions%rowtype;
  v_row public.job_party_interactions%rowtype;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_client_request_id IS NULL THEN RAISE EXCEPTION 'client_request_id is required'; END IF;
  IF p_party_role NOT IN ('complainant', 'occupant', 'witness', 'police', 'other') THEN RAISE EXCEPTION 'Unsupported party role'; END IF;
  IF p_mode NOT IN ('in_person', 'phone', 'message', 'no_answer') THEN RAISE EXCEPTION 'Unsupported interaction mode'; END IF;
  IF p_occurred_at IS NULL OR p_occurred_at > now() + interval '5 minutes' OR p_occurred_at < now() - interval '24 hours' THEN
    RAISE EXCEPTION 'occurred_at is outside the accepted capture window';
  END IF;
  SELECT p.organization_id INTO v_org FROM public.user_profiles p
  WHERE p.id = v_user AND p.deactivated_at IS NULL AND p.role IN ('officer', 'admin_officer', 'admin', 'master', 'grand_master');
  IF v_org IS NULL THEN RAISE EXCEPTION 'Active officer profile required'; END IF;

  SELECT * INTO v_existing FROM public.job_party_interactions i WHERE i.client_request_id = p_client_request_id;
  IF FOUND THEN
    IF v_existing.officer_user_id <> v_user THEN RAISE EXCEPTION 'client_request_id belongs to another actor'; END IF;
    RETURN QUERY SELECT v_existing.id, false, v_existing.occurred_at; RETURN;
  END IF;

  SELECT * INTO v_job FROM public.dispatch_jobs d WHERE d.id = p_dispatch_job_id AND d.organization_id = v_org;
  IF NOT FOUND THEN RAISE EXCEPTION 'Dispatch job not found in the officer organisation'; END IF;
  IF NOT (v_job.assigned_officer_id = v_user OR public.is_admin_for_org(v_org)
      OR EXISTS (SELECT 1 FROM public.dispatch_resources dr WHERE dr.id = v_job.dispatch_resource_id AND dr.assigned_officer_id = v_user)) THEN
    RAISE EXCEPTION 'Only the assigned officer may record interactions for this job';
  END IF;
  IF p_noise_assessment_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.noise_assessments na WHERE na.id = p_noise_assessment_id AND na.organization_id = v_org) THEN
    RAISE EXCEPTION 'Noise assessment not found in the officer organisation';
  END IF;
  IF p_shift_stop_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.shift_stops st WHERE st.id = p_shift_stop_id AND st.dispatch_job_id = v_job.id) THEN
    RAISE EXCEPTION 'Stop does not belong to this job';
  END IF;

  INSERT INTO public.job_party_interactions (organization_id, dispatch_job_id, noise_assessment_id, shift_stop_id, party_role, mode, occurred_at,
    gps_lat, gps_lng, gps_accuracy, summary, protected, officer_user_id, client_request_id)
  VALUES (v_org, v_job.id, p_noise_assessment_id, p_shift_stop_id, p_party_role, p_mode, p_occurred_at,
    p_gps_lat, p_gps_lng, p_gps_accuracy, nullif(trim(coalesce(p_summary, '')), ''), p_party_role IN ('complainant', 'witness'), v_user, p_client_request_id)
  RETURNING * INTO v_row;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_org, v_user, 'job_party_interaction_recorded', 'job_party_interactions', v_row.id,
    jsonb_build_object('dispatch_job_id', v_job.id, 'party_role', p_party_role, 'mode', p_mode, 'noise_assessment_id', p_noise_assessment_id, 'shift_stop_id', p_shift_stop_id));

  RETURN QUERY SELECT v_row.id, true, v_row.occurred_at;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."record_job_party_interaction"(p_client_request_id uuid, p_dispatch_job_id uuid, p_party_role text, p_mode text, p_occurred_at timestamp with time zone, p_summary text, p_noise_assessment_id uuid, p_shift_stop_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_gps_accuracy double precision) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_job_party_interaction"(p_client_request_id uuid, p_dispatch_job_id uuid, p_party_role text, p_mode text, p_occurred_at timestamp with time zone, p_summary text, p_noise_assessment_id uuid, p_shift_stop_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_gps_accuracy double precision) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_job_party_interaction"(p_client_request_id uuid, p_dispatch_job_id uuid, p_party_role text, p_mode text, p_occurred_at timestamp with time zone, p_summary text, p_noise_assessment_id uuid, p_shift_stop_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_gps_accuracy double precision) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."record_job_party_interaction"(p_client_request_id uuid, p_dispatch_job_id uuid, p_party_role text, p_mode text, p_occurred_at timestamp with time zone, p_summary text, p_noise_assessment_id uuid, p_shift_stop_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_gps_accuracy double precision) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_noise_direction_particulars"(p_client_request_id uuid, p_assessment_id uuid, p_given_orally boolean, p_recipient_role text, p_period_hours smallint DEFAULT NULL::smallint, p_entry_notice_left boolean DEFAULT NULL::boolean)
 RETURNS TABLE(assessment_id uuid, end_given_orally boolean, end_recipient_role text, end_expires_at timestamp with time zone, entry_notice_left boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_org uuid;
  v_assessment public.noise_assessments%rowtype;
  v_receipt public.officer_command_requests%rowtype;
  v_cap smallint := 192;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_client_request_id IS NULL THEN RAISE EXCEPTION 'client_request_id is required'; END IF;
  IF p_recipient_role NOT IN ('occupier', 'responsible_person', 'unoccupied_notice_left') THEN
    RAISE EXCEPTION 'recipient_role must be occupier, responsible_person or unoccupied_notice_left';
  END IF;
  SELECT p.organization_id INTO v_org FROM public.user_profiles p
  WHERE p.id = v_user AND p.deactivated_at IS NULL AND p.role IN ('officer', 'admin_officer', 'admin', 'master', 'grand_master');
  IF v_org IS NULL THEN RAISE EXCEPTION 'Active officer profile required'; END IF;

  SELECT * INTO v_receipt FROM public.officer_command_requests r WHERE r.request_id = p_client_request_id::text;
  IF FOUND AND v_receipt.actor_user_id IS DISTINCT FROM v_user THEN RAISE EXCEPTION 'client_request_id belongs to another actor'; END IF;
  IF FOUND AND v_receipt.command_status = 'completed' THEN
    RETURN QUERY SELECT (v_receipt.response->>'assessment_id')::uuid, (v_receipt.response->>'end_given_orally')::boolean,
      v_receipt.response->>'end_recipient_role', (v_receipt.response->>'end_expires_at')::timestamptz, (v_receipt.response->>'entry_notice_left')::boolean;
    RETURN;
  END IF;

  SELECT * INTO v_assessment FROM public.noise_assessments na WHERE na.id = p_assessment_id AND na.organization_id = v_org;
  IF NOT FOUND THEN RAISE EXCEPTION 'Noise assessment not found in the officer organisation'; END IF;
  IF NOT (v_assessment.officer_user_id = v_user OR public.is_admin_for_org(v_org)) THEN
    RAISE EXCEPTION 'Only the assessing officer may record direction particulars';
  END IF;
  IF v_assessment.action_taken NOT IN ('direction_notice', 'equipment_seized') THEN
    RAISE EXCEPTION 'Direction particulars apply to an excessive noise direction or a seizure under it';
  END IF;
  -- s328(5): an unoccupied entry must leave the written direction and the entry notice.
  IF p_recipient_role = 'unoccupied_notice_left' AND NOT coalesce(p_entry_notice_left, false) THEN
    RAISE EXCEPTION 'Entry where no occupier can be identified requires the written direction and entry notice to be left (RMA s328(5))';
  END IF;
  IF p_recipient_role = 'unoccupied_notice_left' AND coalesce(p_given_orally, false) THEN
    RAISE EXCEPTION 'A direction left at an unoccupied place must be written (RMA s328(5)(a))';
  END IF;

  -- s327(3): the officer may specify a shorter period; never longer than the council rule, which is capped at the statute.
  SELECT n.end_validity_hours INTO v_cap FROM public.noise_module_config n
  WHERE n.organization_id = v_org AND n.is_current AND n.effective_from <= current_date AND (n.effective_to IS NULL OR n.effective_to >= current_date)
  ORDER BY n.effective_from DESC, n.version DESC LIMIT 1;
  IF v_cap IS NULL THEN v_cap := 192; END IF;
  IF p_period_hours IS NOT NULL AND (p_period_hours < 1 OR p_period_hours > v_cap) THEN
    RAISE EXCEPTION 'Direction period must be between 1 and % hours (RMA s327(3); council rule)', v_cap;
  END IF;

  UPDATE public.noise_assessments
  SET end_given_orally = p_given_orally,
      end_recipient_role = p_recipient_role,
      entry_notice_left = COALESCE(p_entry_notice_left, noise_assessments.entry_notice_left),
      end_expires_at = CASE
        WHEN p_period_hours IS NOT NULL THEN noise_assessments.assessed_at + make_interval(hours => p_period_hours)
        ELSE COALESCE(noise_assessments.end_expires_at, noise_assessments.assessed_at + make_interval(hours => v_cap))
      END
  WHERE id = v_assessment.id
  RETURNING * INTO v_assessment;

  INSERT INTO public.officer_command_requests (request_id, organization_id, actor_user_id, shift_id, site_id, command_type, command_status, response)
  VALUES (p_client_request_id::text, v_org, v_user, v_assessment.shift_id, v_assessment.site_id, 'record_noise_direction_particulars', 'completed',
    jsonb_build_object('assessment_id', v_assessment.id, 'end_given_orally', v_assessment.end_given_orally, 'end_recipient_role', v_assessment.end_recipient_role,
      'end_expires_at', v_assessment.end_expires_at, 'entry_notice_left', v_assessment.entry_notice_left))
  ON CONFLICT (request_id) DO UPDATE SET command_status = 'completed', response = EXCLUDED.response;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_org, v_user, 'noise_direction_particulars_recorded', 'noise_assessments', v_assessment.id,
    jsonb_build_object('client_request_id', p_client_request_id, 'end_given_orally', v_assessment.end_given_orally,
      'end_recipient_role', v_assessment.end_recipient_role, 'period_hours', p_period_hours, 'end_expires_at', v_assessment.end_expires_at,
      'entry_notice_left', v_assessment.entry_notice_left));

  RETURN QUERY SELECT v_assessment.id, v_assessment.end_given_orally, v_assessment.end_recipient_role, v_assessment.end_expires_at, v_assessment.entry_notice_left;
END;
$function$;
COMMENT ON FUNCTION "public"."record_noise_direction_particulars"(p_client_request_id uuid, p_assessment_id uuid, p_given_orally boolean, p_recipient_role text, p_period_hours smallint, p_entry_notice_left boolean) IS 'Records how an excessive noise direction was given (oral/written, recipient), an officer-specified shorter period within the council rule (RMA s327(3)), and the s328(5) entry notice for an unoccupied place. Officer-owned, idempotent by client_request_id, audited.';
REVOKE ALL ON FUNCTION "public"."record_noise_direction_particulars"(p_client_request_id uuid, p_assessment_id uuid, p_given_orally boolean, p_recipient_role text, p_period_hours smallint, p_entry_notice_left boolean) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_noise_direction_particulars"(p_client_request_id uuid, p_assessment_id uuid, p_given_orally boolean, p_recipient_role text, p_period_hours smallint, p_entry_notice_left boolean) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_noise_direction_particulars"(p_client_request_id uuid, p_assessment_id uuid, p_given_orally boolean, p_recipient_role text, p_period_hours smallint, p_entry_notice_left boolean) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."record_noise_direction_particulars"(p_client_request_id uuid, p_assessment_id uuid, p_given_orally boolean, p_recipient_role text, p_period_hours smallint, p_entry_notice_left boolean) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_noise_photo_perception_envelope"(p_assessment_id uuid, p_classification jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_assessment public.noise_assessments%ROWTYPE;
  v_evidence public.evidence_items%ROWTYPE;
  v_source text;
  v_equipment text;
  v_level text;
  v_confidence real;
  v_authority text;
  v_key text;
  v_envelope uuid;
  v_recorded integer := 0;
BEGIN

  IF jsonb_typeof(p_classification) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'Structured noise classification is required';
  END IF;

  SELECT * INTO v_assessment
  FROM public.noise_assessments
  WHERE id = p_assessment_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Noise assessment is missing'; END IF;

  SELECT evidence.* INTO v_evidence
  FROM public.noise_assessment_evidence link
  JOIN public.evidence_items evidence ON evidence.id = link.evidence_item_id
  WHERE link.noise_assessment_id = v_assessment.id
    AND link.organization_id = v_assessment.organization_id
  ORDER BY CASE WHEN link.purpose = 'primary_evidence' THEN 0 ELSE 1 END,
           link.ordinal, link.id
  LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('recorded', 0, 'replayed', 0, 'skipped', 'missing_evidence_link');
  END IF;
  IF (lower(v_evidence.sha256_hash) ~ '^[0-9a-f]{64}$') IS DISTINCT FROM TRUE THEN
    RETURN jsonb_build_object('recorded', 0, 'replayed', 0, 'skipped', 'missing_source_hash');
  END IF;
  IF coalesce(p_classification->>'status', 'unavailable') <> 'available' THEN
    RETURN jsonb_build_object('recorded', 0, 'replayed', 0, 'skipped', 'classification_unavailable');
  END IF;

  v_source := nullif(trim(coalesce(
    p_classification#>>'{details,source_type}',
    p_classification->>'classification'
  )), '');
  v_equipment := nullif(trim(p_classification#>>'{details,equipment_type}'), '');
  v_level := nullif(trim(p_classification#>>'{details,estimated_level}'), '');
  v_confidence := CASE
    WHEN p_classification->>'confidence' ~ '^[0-9]+([.][0-9]+)?$'
      THEN (p_classification->>'confidence')::real
  END;
  IF v_confidence IS NULL OR v_confidence < 0 OR v_confidence > 1 THEN
    RAISE EXCEPTION 'Noise classification confidence is invalid';
  END IF;
  IF v_source IS NULL AND v_equipment IS NULL AND v_level IS NULL THEN
    RETURN jsonb_build_object('recorded', 0, 'replayed', 0, 'skipped', 'no_structured_candidates');
  END IF;

  v_key := 'noise-photo:' || v_assessment.id::text || ':v1:' || lower(v_evidence.sha256_hash);
  SELECT id INTO v_envelope
  FROM public.perception_evidence_envelopes
  WHERE organization_id = v_assessment.organization_id
    AND idempotency_key = v_key;
  IF FOUND THEN
    RETURN jsonb_build_object('recorded', 0, 'replayed', 1, 'envelope_id', v_envelope);
  END IF;

  INSERT INTO public.perception_evidence_envelopes (
    organization_id, schema_version, domain, source_kind, source_sha256,
    evidence_item_id, source_receipt, model_receipt, derivative_receipts,
    status, idempotency_key
  ) VALUES (
    v_assessment.organization_id, 1, 'noise_photo', 'image',
    lower(v_evidence.sha256_hash), v_evidence.id,
    jsonb_build_object(
      'noise_assessment_id', v_assessment.id,
      'evidence_item_id', v_evidence.id,
      'assessed_at', v_assessment.assessed_at,
      'source_site_id', v_assessment.site_id,
      'complainant_site_id', v_assessment.complainant_site_id,
      'storage_bucket', coalesce(v_evidence.metadata->>'storage_bucket', 'scans'),
      'storage_path', v_evidence.storage_path,
      'authoritative_source_preserved', true
    ),
    jsonb_strip_nulls(jsonb_build_object(
      'classifier', coalesce(p_classification->>'classifier', 'bob_vision'),
      'provider', p_classification->'provider',
      'model', p_classification->'model',
      'prompt_version', coalesce(p_classification->>'prompt_version', 'noise_photo_v1'),
      'machine_acoustic_decision_permitted', false,
      'machine_legal_decision_permitted', false
    )),
    jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
      'original_path', v_evidence.metadata->>'original_path',
      'watermarked_path', v_evidence.storage_path,
      'original_sha256', v_evidence.metadata->>'raw_sha256',
      'watermarked_sha256', v_evidence.sha256_hash
    ))),
    'manual_review_required', v_key
  )
  RETURNING id INTO v_envelope;

  v_authority := CASE WHEN v_confidence < 0.5 THEN 'insufficient' ELSE 'candidate' END;

  IF v_source IS NOT NULL THEN
    INSERT INTO public.perception_evidence_fields (
      organization_id,envelope_id,field_key,candidate_ordinal,value_type,
      candidate_value,normalized_value,candidate_payload,raw_confidence,
      source_locations,consensus_rule,authority_state,review_required
    ) VALUES (
      v_assessment.organization_id,v_envelope,'noise.source_candidate',0,'classification',
      to_jsonb(v_source),lower(v_source),
      jsonb_build_object('source','visible_image_classifier','acoustic_decision_permitted',false),
      v_confidence,jsonb_build_array(jsonb_build_object('evidence_item_id',v_evidence.id)),
      'advisory_visible_noise_candidate_human_review_required_v1',v_authority,true
    );
    v_recorded := v_recorded + 1;
  END IF;
  IF v_equipment IS NOT NULL THEN
    INSERT INTO public.perception_evidence_fields (
      organization_id,envelope_id,field_key,candidate_ordinal,value_type,
      candidate_value,normalized_value,candidate_payload,raw_confidence,
      source_locations,consensus_rule,authority_state,review_required
    ) VALUES (
      v_assessment.organization_id,v_envelope,'noise.equipment_candidate',0,'text',
      to_jsonb(v_equipment),lower(v_equipment),
      jsonb_build_object('source','visible_image_classifier'),
      v_confidence,jsonb_build_array(jsonb_build_object('evidence_item_id',v_evidence.id)),
      'advisory_visible_noise_candidate_human_review_required_v1',v_authority,true
    );
    v_recorded := v_recorded + 1;
  END IF;
  IF v_level IS NOT NULL THEN
    INSERT INTO public.perception_evidence_fields (
      organization_id,envelope_id,field_key,candidate_ordinal,value_type,
      candidate_value,normalized_value,candidate_payload,raw_confidence,
      source_locations,consensus_rule,authority_state,review_required
    ) VALUES (
      v_assessment.organization_id,v_envelope,'noise.estimated_level_candidate',0,'classification',
      to_jsonb(v_level),lower(v_level),
      jsonb_build_object(
        'source','visible_image_classifier',
        'acoustic_measurement',false,
        'excessive_noise_decision_permitted',false
      ),
      v_confidence,jsonb_build_array(jsonb_build_object('evidence_item_id',v_evidence.id)),
      'advisory_visual_only_level_candidate_human_review_required_v1',v_authority,true
    );
    v_recorded := v_recorded + 1;
  END IF;

  RETURN jsonb_build_object(
    'recorded',1,'replayed',0,'envelope_id',v_envelope,'field_candidates',v_recorded
  );
END;
$function$;
REVOKE ALL ON FUNCTION "public"."record_noise_photo_perception_envelope"(p_assessment_id uuid, p_classification jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_noise_photo_perception_envelope"(p_assessment_id uuid, p_classification jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_noise_photo_perception_envelope"(p_assessment_id uuid, p_classification jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_nzta_access_attestation"(p_user_id uuid, p_attestation_type text, p_completed_on date, p_expires_on date DEFAULT NULL::date, p_provider text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_organization_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_target public.user_profiles%rowtype;
  v_expires date;
  v_id uuid;
BEGIN
  SELECT * INTO v_target FROM public.user_profiles WHERE id = p_user_id AND deactivated_at IS NULL;
  IF v_actor IS NULL OR v_target.id IS NULL THEN RAISE EXCEPTION 'Active user required' USING ERRCODE = '42501'; END IF;
  IF p_attestation_type IS NULL OR p_attestation_type NOT IN ('training', 'confidentiality') THEN
    RAISE EXCEPTION 'Choose training or confidentiality';
  END IF;
  -- Administrators of an organisation where the person holds register access
  -- (provider staff, parent-organisation admins) can record it too; it is still
  -- stored against the person's home organisation because it is personal.
  IF NOT (public.is_admin_for_org(v_target.organization_id)
          OR (p_attestation_type = 'confidentiality' AND p_user_id = v_actor)
          OR (p_organization_id IS NOT NULL AND public.is_admin_for_org(p_organization_id)
              AND EXISTS (
                SELECT 1 FROM jsonb_array_elements(public.get_nzta_access_holders(p_organization_id)) holder
                WHERE holder->>'user_id' = p_user_id::text))) THEN
    RAISE EXCEPTION 'Organisation administrator required' USING ERRCODE = '42501';
  END IF;
  IF p_completed_on IS NULL OR p_completed_on > current_date THEN
    RAISE EXCEPTION 'Enter the completion date; it cannot be in the future';
  END IF;
  v_expires := coalesce(p_expires_on, (p_completed_on + interval '12 months')::date);
  IF v_expires <= p_completed_on OR v_expires > (p_completed_on + interval '12 months')::date THEN
    RAISE EXCEPTION 'Refresh is required within 12 months of completion';
  END IF;
  INSERT INTO public.nzta_access_attestations (organization_id, user_id, attestation_type, completed_on, expires_on,
    provider, notes, recorded_by)
  VALUES (v_target.organization_id, p_user_id, p_attestation_type, p_completed_on, v_expires,
    nullif(btrim(coalesce(p_provider, '')), ''), nullif(btrim(coalesce(p_notes, '')), ''), v_actor)
  RETURNING id INTO v_id;
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_target.organization_id, v_actor, 'nzta_access_attestation_recorded', 'nzta_access_attestations', v_id,
    jsonb_build_object('user_id', p_user_id, 'attestation_type', p_attestation_type, 'expires_on', v_expires,
      'recorded_via_organization_id', coalesce(p_organization_id, v_target.organization_id)));
  RETURN v_id;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."record_nzta_access_attestation"(p_user_id uuid, p_attestation_type text, p_completed_on date, p_expires_on date, p_provider text, p_notes text, p_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_nzta_access_attestation"(p_user_id uuid, p_attestation_type text, p_completed_on date, p_expires_on date, p_provider text, p_notes text, p_organization_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_nzta_access_attestation"(p_user_id uuid, p_attestation_type text, p_completed_on date, p_expires_on date, p_provider text, p_notes text, p_organization_id uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."record_nzta_access_review"(p_organization_id uuid, p_period_start date, p_period_end date, p_findings text, p_actions text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_id uuid;
BEGIN
  IF auth.uid() IS NULL OR p_organization_id IS NULL OR NOT public.is_admin_for_org(p_organization_id) THEN
    RAISE EXCEPTION 'Organisation administrator required' USING ERRCODE = '42501';
  END IF;
  IF p_period_start IS NULL OR p_period_end IS NULL OR p_period_end < p_period_start THEN
    RAISE EXCEPTION 'Enter a valid review period';
  END IF;
  IF p_period_end > current_date THEN RAISE EXCEPTION 'The review period cannot end in the future'; END IF;
  IF length(btrim(coalesce(p_findings, ''))) < 10 THEN
    RAISE EXCEPTION 'Record what was reviewed and found (at least 10 characters)';
  END IF;
  INSERT INTO public.nzta_access_reviews (organization_id, period_start, period_end, reviewed_by, holders, findings, actions)
  VALUES (p_organization_id, p_period_start, p_period_end, auth.uid(),
    coalesce((SELECT jsonb_agg(h) FROM jsonb_array_elements(public.get_nzta_access_holders(p_organization_id)) h
              WHERE (h->>'holds_access')::boolean), '[]'::jsonb),
    btrim(p_findings), nullif(btrim(coalesce(p_actions, '')), ''))
  RETURNING id INTO v_id;
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (p_organization_id, auth.uid(), 'nzta_access_review_recorded', 'nzta_access_reviews', v_id,
    jsonb_build_object('period_start', p_period_start, 'period_end', p_period_end));
  RETURN v_id;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."record_nzta_access_review"(p_organization_id uuid, p_period_start date, p_period_end date, p_findings text, p_actions text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_nzta_access_review"(p_organization_id uuid, p_period_start date, p_period_end date, p_findings text, p_actions text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_nzta_access_review"(p_organization_id uuid, p_period_start date, p_period_end date, p_findings text, p_actions text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."record_nzta_register_lookup"(p_organization_id uuid, p_looked_up_at timestamp with time zone, p_plate_number text, p_vin text, p_motochek_user text, p_purpose text, p_explanation text, p_location_id uuid DEFAULT NULL::uuid, p_observation_id uuid DEFAULT NULL::uuid, p_notice_id uuid DEFAULT NULL::uuid, p_vehicle_identity_check_id uuid DEFAULT NULL::uuid, p_evidence_item_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_plate text := nullif(upper(regexp_replace(coalesce(p_plate_number, ''), '[^A-Za-z0-9]', '', 'g')), '');
  v_vin text := nullif(upper(regexp_replace(coalesce(p_vin, ''), '[^A-Za-z0-9]', '', 'g')), '');
  v_vehicle uuid;
  v_id uuid;
BEGIN
  IF v_actor IS NULL OR p_organization_id IS NULL
     OR NOT public.can_access_vehicle_owner_identity(p_organization_id) THEN
    RAISE EXCEPTION 'NZTA register authorisation required' USING ERRCODE = '42501';
  END IF;
  IF v_plate IS NULL AND v_vin IS NULL THEN RAISE EXCEPTION 'Enter the plate or VIN that was looked up'; END IF;
  IF p_looked_up_at IS NULL OR p_looked_up_at > clock_timestamp() + interval '10 minutes' THEN
    RAISE EXCEPTION 'Enter when the lookup was made; it cannot be in the future';
  END IF;
  IF length(btrim(coalesce(p_motochek_user, ''))) < 2 THEN
    RAISE EXCEPTION 'Enter the individual Motochek login used for this lookup';
  END IF;
  IF p_purpose IS NULL OR p_purpose NOT IN ('trespass_unpermitted_vehicle', 'cctv_patrol_signage_breach') THEN
    RAISE EXCEPTION 'Choose one of the authorised purposes';
  END IF;
  IF length(btrim(coalesce(p_explanation, ''))) < 10 THEN
    RAISE EXCEPTION 'Explain why the lookup was needed (at least 10 characters)';
  END IF;
  IF p_location_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.locations WHERE id = p_location_id AND organization_id = p_organization_id) THEN
    RAISE EXCEPTION 'That place is not in this organisation';
  END IF;
  IF p_observation_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.observations WHERE id = p_observation_id AND organization_id = p_organization_id) THEN
    RAISE EXCEPTION 'That sighting is not in this organisation';
  END IF;
  IF p_notice_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.notices WHERE id = p_notice_id AND organization_id = p_organization_id) THEN
    RAISE EXCEPTION 'That notice is not in this organisation';
  END IF;
  IF p_vehicle_identity_check_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.vehicle_identity_checks WHERE id = p_vehicle_identity_check_id AND organization_id = p_organization_id) THEN
    RAISE EXCEPTION 'That NZTA check is not in this organisation';
  END IF;
  IF p_vehicle_identity_check_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.nzta_register_lookups WHERE vehicle_identity_check_id = p_vehicle_identity_check_id) THEN
    RAISE EXCEPTION 'That NZTA check is already linked to another lookup';
  END IF;
  IF p_evidence_item_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.evidence_items WHERE id = p_evidence_item_id AND organization_id = p_organization_id) THEN
    RAISE EXCEPTION 'That evidence item is not in this organisation';
  END IF;
  IF v_plate IS NOT NULL THEN
    SELECT id INTO v_vehicle FROM public.canonical_vehicles
    WHERE upper(regexp_replace(plate_number, '[^A-Za-z0-9]', '', 'g')) = v_plate
    ORDER BY updated_at DESC NULLS LAST LIMIT 1;
  END IF;
  IF v_vehicle IS NULL AND v_vin IS NOT NULL THEN
    SELECT id INTO v_vehicle FROM public.canonical_vehicles WHERE upper(vin) = v_vin
    ORDER BY updated_at DESC NULLS LAST LIMIT 1;
  END IF;
  INSERT INTO public.nzta_register_lookups (organization_id, looked_up_at, plate_number, vin, canonical_vehicle_id,
    motochek_user, purpose, explanation, location_id, observation_id, evidence_item_id, notice_id,
    vehicle_identity_check_id, created_by)
  VALUES (p_organization_id, p_looked_up_at, v_plate, v_vin, v_vehicle, btrim(p_motochek_user), p_purpose,
    btrim(p_explanation), p_location_id, p_observation_id, p_evidence_item_id, p_notice_id,
    p_vehicle_identity_check_id, v_actor)
  RETURNING id INTO v_id;
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (p_organization_id, v_actor, 'nzta_register_lookup_recorded', 'nzta_register_lookups', v_id,
    jsonb_build_object('purpose', p_purpose, 'has_plate', v_plate IS NOT NULL, 'has_vin', v_vin IS NOT NULL));
  RETURN v_id;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."record_nzta_register_lookup"(p_organization_id uuid, p_looked_up_at timestamp with time zone, p_plate_number text, p_vin text, p_motochek_user text, p_purpose text, p_explanation text, p_location_id uuid, p_observation_id uuid, p_notice_id uuid, p_vehicle_identity_check_id uuid, p_evidence_item_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_nzta_register_lookup"(p_organization_id uuid, p_looked_up_at timestamp with time zone, p_plate_number text, p_vin text, p_motochek_user text, p_purpose text, p_explanation text, p_location_id uuid, p_observation_id uuid, p_notice_id uuid, p_vehicle_identity_check_id uuid, p_evidence_item_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_nzta_register_lookup"(p_organization_id uuid, p_looked_up_at timestamp with time zone, p_plate_number text, p_vin text, p_motochek_user text, p_purpose text, p_explanation text, p_location_id uuid, p_observation_id uuid, p_notice_id uuid, p_vehicle_identity_check_id uuid, p_evidence_item_id uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."record_observation_direct_initiation"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.officer_id is null then
    return new;
  end if;
  insert into public.task_assignments(
    user_id,
    organization_id,
    basis,
    observation_id,
    started_at,
    granted_by,
    notes
  ) values (
    new.officer_id,
    new.organization_id,
    'direct_module_initiation',
    new.id,
    new.observed_at,
    new.officer_id,
    'Automatically recorded from the officer-authored observation'
  )
  on conflict (user_id, observation_id, basis)
    where observation_id is not null and basis = 'direct_module_initiation'
  do nothing;
  return new;
end;
$function$;
COMMENT ON FUNCTION "public"."record_observation_direct_initiation"() IS 'Records the source officer direct_module_initiation basis whenever an observation is created. The observation remains the accountable source receipt.';
REVOKE ALL ON FUNCTION "public"."record_observation_direct_initiation"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_observation_direct_initiation"() TO "postgres";

CREATE OR REPLACE FUNCTION "public"."record_observation_person_mention"(p_observation_id uuid, p_person_record_id uuid DEFAULT NULL::uuid, p_person_fields jsonb DEFAULT NULL::jsonb, p_mention_role text DEFAULT 'mentioned'::text, p_basis text DEFAULT NULL::text, p_mention_text text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_obs_org uuid;
  v_person_id uuid := p_person_record_id;
  v_person_org uuid;
  v_name text := nullif(trim(p_person_fields->>'display_name'), '');
  v_details jsonb;
  v_id uuid;
BEGIN
  SELECT o.organization_id INTO v_obs_org FROM public.observations o WHERE o.id = p_observation_id;
  IF v_actor IS NULL OR v_obs_org IS NULL OR NOT public.org_access_allowed(v_obs_org) THEN
    RAISE EXCEPTION 'Observation not found in your authorised scope';
  END IF;
  IF coalesce(p_mention_role, 'mentioned') NOT IN ('mentioned', 'driver', 'passenger', 'occupant', 'witness', 'other') THEN
    RAISE EXCEPTION 'Choose how this person relates to the sighting';
  END IF;
  IF coalesce(trim(p_basis), '') = '' THEN RAISE EXCEPTION 'Say how this person came up at the sighting'; END IF;

  IF v_person_id IS NULL THEN
    IF v_name IS NULL THEN RAISE EXCEPTION 'Choose an existing person or enter their name'; END IF;
    PERFORM public.assert_new_person_not_duplicate(v_obs_org, p_person_fields);
    v_details := jsonb_strip_nulls(jsonb_build_object(
      'date_of_birth', nullif(p_person_fields->>'date_of_birth', ''),
      'phone', nullif(trim(p_person_fields->>'phone'), ''),
      'email', nullif(trim(p_person_fields->>'email'), ''),
      'suburb', nullif(trim(p_person_fields->>'suburb'), ''),
      'city', nullif(trim(p_person_fields->>'city'), ''),
      'notes', nullif(trim(p_person_fields->>'notes'), '')));
    INSERT INTO public.person_records (organization_id, display_name, review_state, metadata)
    VALUES (v_obs_org, v_name, 'manual_review_required',
      jsonb_build_object('profile_details', v_details, 'created_from', 'observation_mention', 'created_by', v_actor,
        'first_observation_id', p_observation_id))
    RETURNING id INTO v_person_id;
    PERFORM public.ensure_canonical_person_for_record(v_person_id);
    INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
    VALUES (v_obs_org, v_actor, 'identity_person_create', 'person_records', v_person_id,
      jsonb_build_object('reason', 'Mentioned at sighting: ' || trim(p_basis), 'observation_id', p_observation_id,
        'fields', array(SELECT jsonb_object_keys(v_details))));
  ELSE
    SELECT pr.organization_id INTO v_person_org FROM public.person_records pr WHERE pr.id = v_person_id;
    IF v_person_org IS NULL OR NOT public.org_access_allowed(v_person_org) THEN RAISE EXCEPTION 'Person record not found in your authorised scope'; END IF;
    IF EXISTS (SELECT 1 FROM public.person_records pr WHERE pr.id = v_person_id AND pr.metadata ? 'merged_into_person_record_id') THEN
      RAISE EXCEPTION 'This person has been merged into another record';
    END IF;
  END IF;

  INSERT INTO public.observation_person_mentions (organization_id, observation_id, person_record_id, mention_role, basis, mention_text, created_by)
  VALUES (v_obs_org, p_observation_id, v_person_id, coalesce(p_mention_role, 'mentioned'), trim(p_basis), nullif(trim(p_mention_text), ''), v_actor)
  ON CONFLICT (observation_id, person_record_id) WHERE status <> 'dismissed' DO NOTHING
  RETURNING id INTO v_id;
  IF v_id IS NULL THEN RAISE EXCEPTION 'This person is already recorded at this sighting'; END IF;
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_obs_org, v_actor, 'observation_person_mentioned', 'observation_person_mentions', v_id,
    jsonb_build_object('observation_id', p_observation_id, 'person_record_id', v_person_id, 'mention_role', coalesce(p_mention_role, 'mentioned')));
  RETURN jsonb_build_object('mention_id', v_id, 'person_record_id', v_person_id, 'status', 'unconfirmed');
END;
$function$;
REVOKE ALL ON FUNCTION "public"."record_observation_person_mention"(p_observation_id uuid, p_person_record_id uuid, p_person_fields jsonb, p_mention_role text, p_basis text, p_mention_text text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_observation_person_mention"(p_observation_id uuid, p_person_record_id uuid, p_person_fields jsonb, p_mention_role text, p_basis text, p_mention_text text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_observation_person_mention"(p_observation_id uuid, p_person_record_id uuid, p_person_fields jsonb, p_mention_role text, p_basis text, p_mention_text text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."record_officer_breadcrumb"(p_client_event_id uuid, p_recorded_at timestamp with time zone, p_gps_lat double precision, p_gps_lng double precision, p_accuracy_meters double precision DEFAULT NULL::double precision, p_heading double precision DEFAULT NULL::double precision, p_speed_kmh double precision DEFAULT NULL::double precision, p_activity_type text DEFAULT 'gps_update'::text, p_shift_id uuid DEFAULT NULL::uuid, p_physical_address text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, created boolean, received_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_home_org uuid;
  v_org_id uuid;
  v_shift public.shifts%rowtype;
  v_zone_id uuid;
  v_assigned_zone uuid;
  v_existing public.officer_gps_log%rowtype;
  v_created public.officer_gps_log%rowtype;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT up.organization_id INTO v_home_org FROM public.user_profiles up
  WHERE up.id = v_user_id AND up.deactivated_at IS NULL AND up.role IN ('officer', 'admin_officer', 'scan_operator');
  IF v_home_org IS NULL THEN RAISE EXCEPTION 'Active officer profile not found'; END IF;
  IF p_client_event_id IS NULL THEN RAISE EXCEPTION 'client_event_id is required'; END IF;
  IF p_recorded_at IS NULL OR p_recorded_at > now() + interval '5 minutes' OR p_recorded_at < now() - interval '24 hours' THEN
    RAISE EXCEPTION 'recorded_at is outside the accepted capture window';
  END IF;
  IF p_gps_lat NOT BETWEEN -90 AND 90 OR p_gps_lng NOT BETWEEN -180 AND 180 THEN RAISE EXCEPTION 'Invalid GPS coordinates'; END IF;
  IF p_accuracy_meters IS NOT NULL AND p_accuracy_meters < 0 THEN RAISE EXCEPTION 'GPS accuracy cannot be negative'; END IF;
  IF p_activity_type NOT IN ('gps_update', 'shift_start', 'shift_end', 'scan', 'welfare_checkin', 'sos', 'checkpoint_scan') THEN
    RAISE EXCEPTION 'Unsupported breadcrumb activity type';
  END IF;

  -- The shift may belong to any operating branch; the breadcrumb then belongs to that branch too.
  IF p_shift_id IS NOT NULL THEN
    SELECT s.* INTO v_shift FROM public.shifts s WHERE s.id = p_shift_id AND s.officer_user_id = v_user_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Shift does not belong to the authenticated officer'; END IF;
  END IF;
  v_org_id := coalesce(v_shift.organization_id, v_home_org);

  -- Replays return the original receipt whichever organisation it was stamped with.
  SELECT g.* INTO v_existing FROM public.officer_gps_log g
  WHERE g.officer_id = v_user_id AND g.client_event_id = p_client_event_id
  ORDER BY g.created_at LIMIT 1;
  IF FOUND THEN RETURN QUERY SELECT v_existing.id, false, v_existing.created_at; RETURN; END IF;

  -- Zone detection is evidence, never a gate: a resolver failure must not lose a position.
  -- A shift's own assigned zone wins when the fix is inside it, so the crumb is tied to the job, not to whichever geofence overlaps.
  BEGIN
    IF v_shift.id IS NOT NULL THEN
      SELECT z.id INTO v_assigned_zone
      FROM public.location_zones z
      WHERE z.id = coalesce(v_shift.zone_id,
                            (SELECT sal.zone_id FROM public.service_agreement_locations sal WHERE sal.id = v_shift.service_agreement_location_id))
        AND z.boundary IS NOT NULL
        AND z.boundary_verification = 'verified'
        AND ST_IsValid(z.boundary) AND NOT ST_IsEmpty(z.boundary)
        AND ST_Covers(z.boundary, ST_SetSRID(ST_Point(p_gps_lng, p_gps_lat), 4326));
    END IF;
    IF v_assigned_zone IS NOT NULL THEN
      v_zone_id := v_assigned_zone;
    ELSE
      SELECT r.matched_zone_id INTO v_zone_id FROM public.resolve_context(p_gps_lat, p_gps_lng, v_org_id, NULL, p_recorded_at) r LIMIT 1;
    END IF;
  EXCEPTION WHEN OTHERS THEN v_zone_id := NULL;
  END;

  BEGIN
    INSERT INTO public.officer_gps_log (
      organization_id, officer_id, client_event_id, recorded_at, gps_lat, gps_lng,
      accuracy_meters, heading, speed_kmh, activity_type, shift_id, physical_address, detected_zone_id
    ) VALUES (
      v_org_id, v_user_id, p_client_event_id, p_recorded_at, p_gps_lat, p_gps_lng,
      p_accuracy_meters, p_heading, p_speed_kmh, p_activity_type, v_shift.id, NULLIF(trim(p_physical_address), ''), v_zone_id
    ) RETURNING * INTO v_created;
  EXCEPTION WHEN unique_violation THEN
    SELECT * INTO v_created FROM public.officer_gps_log
    WHERE officer_id = v_user_id AND client_event_id = p_client_event_id ORDER BY created_at LIMIT 1;
    RETURN QUERY SELECT v_created.id, false, v_created.created_at; RETURN;
  END;
  RETURN QUERY SELECT v_created.id, true, v_created.created_at;
END;
$function$;
COMMENT ON FUNCTION "public"."record_officer_breadcrumb"(p_client_event_id uuid, p_recorded_at timestamp with time zone, p_gps_lat double precision, p_gps_lng double precision, p_accuracy_meters double precision, p_heading double precision, p_speed_kmh double precision, p_activity_type text, p_shift_id uuid, p_physical_address text) IS 'Idempotent officer GPS breadcrumb. Stamped with the shift''s operating organisation when a shift of the caller is given, else the caller''s home organisation; detected_zone_id resolved best-effort through resolve_context. Replays (same officer + client_event_id) return the original receipt.';
REVOKE ALL ON FUNCTION "public"."record_officer_breadcrumb"(p_client_event_id uuid, p_recorded_at timestamp with time zone, p_gps_lat double precision, p_gps_lng double precision, p_accuracy_meters double precision, p_heading double precision, p_speed_kmh double precision, p_activity_type text, p_shift_id uuid, p_physical_address text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_officer_breadcrumb"(p_client_event_id uuid, p_recorded_at timestamp with time zone, p_gps_lat double precision, p_gps_lng double precision, p_accuracy_meters double precision, p_heading double precision, p_speed_kmh double precision, p_activity_type text, p_shift_id uuid, p_physical_address text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_officer_breadcrumb"(p_client_event_id uuid, p_recorded_at timestamp with time zone, p_gps_lat double precision, p_gps_lng double precision, p_accuracy_meters double precision, p_heading double precision, p_speed_kmh double precision, p_activity_type text, p_shift_id uuid, p_physical_address text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."record_officer_breadcrumb"(p_client_event_id uuid, p_recorded_at timestamp with time zone, p_gps_lat double precision, p_gps_lng double precision, p_accuracy_meters double precision, p_heading double precision, p_speed_kmh double precision, p_activity_type text, p_shift_id uuid, p_physical_address text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_officer_checkpoint_visit"(p_client_request_id uuid, p_shift_id uuid, p_checkpoint_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_gps_accuracy double precision DEFAULT NULL::double precision, p_gps_distance_from_checkpoint double precision DEFAULT NULL::double precision, p_within_radius boolean DEFAULT NULL::boolean)
 RETURNS TABLE(visit_id uuid, patrol_id uuid, visited_at timestamp with time zone, created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_checkpoint public.patrol_checkpoints%ROWTYPE;
  v_patrol public.patrols%ROWTYPE;
  v_visit public.patrol_checkpoint_visits%ROWTYPE;
  v_stop_id uuid;
  v_stop_count integer;
  v_at timestamptz := clock_timestamp();
  v_distance double precision := NULL;
  v_within boolean := NULL;
BEGIN
  IF v_actor IS NULL OR p_client_request_id IS NULL THEN
    RAISE EXCEPTION 'Authentication and client_request_id are required';
  END IF;

  SELECT organization_id INTO v_org FROM public.user_profiles WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'Active officer identity required'; END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.shifts s
    WHERE s.id = p_shift_id AND s.organization_id = v_org AND s.officer_user_id = v_actor AND s.status = 'in_progress'
  ) THEN RAISE EXCEPTION 'Checkpoint visit must be recorded for your active shift'; END IF;

  SELECT * INTO v_checkpoint FROM public.patrol_checkpoints WHERE id = p_checkpoint_id AND organization_id = v_org AND active = true;
  IF NOT FOUND THEN RAISE EXCEPTION 'Checkpoint is not active for your organization'; END IF;

  SELECT * INTO v_visit FROM public.patrol_checkpoint_visits
  WHERE organization_id = v_org AND officer_user_id = v_actor AND client_request_id = p_client_request_id;
  IF FOUND THEN
    RETURN QUERY SELECT v_visit.id, v_visit.patrol_id, v_visit.visited_at, false;
    RETURN;
  END IF;

  -- P1: presence is measured here, from the recorded point. The client's p_gps_distance_from_checkpoint /
  -- p_within_radius are accepted for signature compatibility only. No point or no GPS -> NULL, not a guess.
  IF p_gps_lat IS NOT NULL AND p_gps_lng IS NOT NULL AND v_checkpoint.gps_lat IS NOT NULL AND v_checkpoint.gps_lng IS NOT NULL THEN
    v_distance := round(ST_Distance(ST_SetSRID(ST_MakePoint(v_checkpoint.gps_lng, v_checkpoint.gps_lat), 4326)::geography,
                                    ST_SetSRID(ST_MakePoint(p_gps_lng, p_gps_lat), 4326)::geography)::numeric, 1);
    v_within := v_distance <= v_checkpoint.radius_meters;
  END IF;

  SELECT * INTO v_patrol FROM public.patrols
  WHERE organization_id = v_org AND shift_id = p_shift_id AND officer_user_id = v_actor AND status = 'in_progress'
  ORDER BY started_at DESC LIMIT 1;
  IF NOT FOUND THEN
    INSERT INTO public.patrols(organization_id, shift_id, officer_user_id, zone_id, status, started_at)
    VALUES(v_org, p_shift_id, v_actor, v_checkpoint.zone_id, 'in_progress', v_at)
    RETURNING * INTO v_patrol;
  END IF;

  SELECT count(*) INTO v_stop_count FROM (
    SELECT ss.id FROM public.shift_stops ss
    WHERE ss.shift_id = p_shift_id AND ss.status IN ('pending', 'en_route', 'on_scene')
      AND ((v_checkpoint.client_site_id IS NOT NULL AND ss.site_id = v_checkpoint.client_site_id)
        OR (v_checkpoint.zone_id IS NOT NULL AND ss.zone_id = v_checkpoint.zone_id))
    ORDER BY ss.stop_order LIMIT 2
  ) candidates;
  IF v_stop_count = 1 THEN
    SELECT ss.id INTO v_stop_id FROM public.shift_stops ss
    WHERE ss.shift_id = p_shift_id AND ss.status IN ('pending', 'en_route', 'on_scene')
      AND ((v_checkpoint.client_site_id IS NOT NULL AND ss.site_id = v_checkpoint.client_site_id)
        OR (v_checkpoint.zone_id IS NOT NULL AND ss.zone_id = v_checkpoint.zone_id))
    ORDER BY ss.stop_order LIMIT 1;
  END IF;

  INSERT INTO public.patrol_checkpoint_visits(
    organization_id, patrol_id, checkpoint_id, officer_user_id, gps_lat, gps_lng,
    gps_accuracy, gps_distance_from_checkpoint, within_radius, scan_method,
    shift_stop_id, notes, visited_at, client_request_id, checkpoint_verification_at_visit
  ) VALUES (
    v_org, v_patrol.id, v_checkpoint.id, v_actor, p_gps_lat, p_gps_lng,
    p_gps_accuracy, v_distance, v_within, 'qr_camera',
    v_stop_id, 'QR checkpoint scan from mobile app', v_at, p_client_request_id, v_checkpoint.checkpoint_verification
  ) RETURNING * INTO v_visit;

  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES(v_org, v_actor, 'officer_checkpoint_visit_recorded', 'patrol_checkpoint_visits', v_visit.id,
    jsonb_build_object('patrol_id', v_patrol.id, 'checkpoint_id', v_checkpoint.id, 'shift_id', p_shift_id,
      'client_request_id', p_client_request_id, 'gps_distance_from_checkpoint', v_distance, 'within_radius', v_within,
      'checkpoint_verification', v_checkpoint.checkpoint_verification, 'client_claimed_within_radius', p_within_radius));
  RETURN QUERY SELECT v_visit.id, v_patrol.id, v_visit.visited_at, true;
END;
$function$;
COMMENT ON FUNCTION "public"."record_officer_checkpoint_visit"(p_client_request_id uuid, p_shift_id uuid, p_checkpoint_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_gps_accuracy double precision, p_gps_distance_from_checkpoint double precision, p_within_radius boolean) IS 'Officer QR checkpoint visit. Since 20260915100000 the distance and within_radius are computed by the server from the checkpoint point + radius (client values accepted for compatibility only) and the checkpoint verification state is recorded with the visit (P1/P2). Idempotent by client_request_id; audited.';
REVOKE ALL ON FUNCTION "public"."record_officer_checkpoint_visit"(p_client_request_id uuid, p_shift_id uuid, p_checkpoint_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_gps_accuracy double precision, p_gps_distance_from_checkpoint double precision, p_within_radius boolean) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_officer_checkpoint_visit"(p_client_request_id uuid, p_shift_id uuid, p_checkpoint_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_gps_accuracy double precision, p_gps_distance_from_checkpoint double precision, p_within_radius boolean) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_officer_checkpoint_visit"(p_client_request_id uuid, p_shift_id uuid, p_checkpoint_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_gps_accuracy double precision, p_gps_distance_from_checkpoint double precision, p_within_radius boolean) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."record_officer_checkpoint_visit"(p_client_request_id uuid, p_shift_id uuid, p_checkpoint_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_gps_accuracy double precision, p_gps_distance_from_checkpoint double precision, p_within_radius boolean) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_officer_welfare_checkin"(p_client_request_id uuid, p_gps_lat double precision DEFAULT NULL::double precision, p_gps_lng double precision DEFAULT NULL::double precision, p_shift_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text)
 RETURNS TABLE(check_id uuid, checked_in_at timestamp with time zone, created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_org uuid;v_check public.welfare_checks%rowtype;v_at timestamptz:=clock_timestamp();
begin
 if v_actor is null or p_client_request_id is null then raise exception 'Authentication and client_request_id are required';end if;
 select organization_id into v_org from public.user_profiles where id=v_actor and deactivated_at is null;if v_org is null then raise exception 'Active officer identity required';end if;
 if p_shift_id is not null and not exists(select 1 from public.shifts s where s.id=p_shift_id and s.organization_id=v_org and s.officer_user_id=v_actor and s.status='in_progress') then raise exception 'Check-in shift must be your active shift';end if;
 select * into v_check from public.welfare_checks where organization_id=v_org and officer_user_id=v_actor and client_request_id=p_client_request_id;if found then return query select v_check.id,v_check.checked_in_at,false;return;end if;
 insert into public.welfare_checks(organization_id,officer_user_id,shift_id,status,notes,gps_lat,gps_lng,checked_in_at,client_request_id) values(v_org,v_actor,p_shift_id,'ok',nullif(trim(coalesce(p_notes,'')),''),p_gps_lat,p_gps_lng,v_at,p_client_request_id) returning * into v_check;
 insert into public.officer_welfare_settings(organization_id,officer_user_id,last_checkin_at) values(v_org,v_actor,v_at) on conflict(officer_user_id,organization_id) do update set last_checkin_at=excluded.last_checkin_at;
 insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_org,v_actor,'officer_welfare_checkin','welfare_checks',v_check.id,jsonb_build_object('shift_id',p_shift_id,'client_request_id',p_client_request_id));
 return query select v_check.id,v_check.checked_in_at,true;
end;$function$;
REVOKE ALL ON FUNCTION "public"."record_officer_welfare_checkin"(p_client_request_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_shift_id uuid, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_officer_welfare_checkin"(p_client_request_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_shift_id uuid, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_officer_welfare_checkin"(p_client_request_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_shift_id uuid, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."record_officer_welfare_checkin"(p_client_request_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_shift_id uuid, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_patrol_checkpoint_visit"(p_patrol_id uuid, p_checkpoint_kind text, p_checkpoint_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_gps_accuracy double precision, p_notes text DEFAULT NULL::text)
 RETURNS TABLE(visit_id uuid, created boolean, visited_at timestamp with time zone, scan_method text, notes text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid:=auth.uid();v_profile public.user_profiles%rowtype;v_patrol record;v_checkpoint record;v_existing public.patrol_checkpoint_visits%rowtype;v_visit public.patrol_checkpoint_visits%rowtype;
  v_radius double precision;v_distance double precision;v_shift_stop_id uuid;v_regular_id uuid;v_route_id uuid;
begin
  if v_actor is null then raise exception 'Authentication required';end if;
  select * into v_profile from public.user_profiles where id=v_actor and deactivated_at is null;
  if not found or v_profile.role not in('grand_master','master','admin','admin_officer','officer') then raise exception 'Active Patrol officer required';end if;
  select p.*,s.patrol_route_id,s.zone_id as shift_zone_id into v_patrol from public.patrols p join public.shifts s on s.id=p.shift_id where p.id=p_patrol_id for update of p;
  if not found or v_patrol.organization_id is distinct from v_profile.organization_id or v_patrol.officer_user_id is distinct from v_actor then raise exception 'Active assigned Patrol session not found';end if;
  if v_patrol.status<>'in_progress' then raise exception 'Patrol session is not in progress';end if;
  if p_gps_lat is null or p_gps_lng is null or p_gps_accuracy is null or p_gps_lat not between -90 and 90 or p_gps_lng not between -180 and 180 or p_gps_accuracy<0 or p_gps_accuracy>1000 then raise exception 'Valid checkpoint GPS and accuracy are required';end if;
  if p_checkpoint_kind='route' then
    select id,gps_lat,gps_lng,geofence_radius_meters as radius,patrol_route_id,is_active,null::uuid as client_site_id,null::uuid as zone_id into v_checkpoint from public.patrol_route_checkpoints where id=p_checkpoint_id;
    if not found or not v_checkpoint.is_active or v_checkpoint.patrol_route_id is distinct from v_patrol.patrol_route_id then raise exception 'Assigned route checkpoint not found';end if;
    v_route_id:=v_checkpoint.id;
  elsif p_checkpoint_kind='site' then
    select id,gps_lat,gps_lng,radius_meters as radius,null::uuid as patrol_route_id,active as is_active,client_site_id,zone_id into v_checkpoint from public.patrol_checkpoints where id=p_checkpoint_id and organization_id=v_patrol.organization_id;
    if not found or not v_checkpoint.is_active or not((v_checkpoint.zone_id is not null and v_checkpoint.zone_id=v_patrol.shift_zone_id) or exists(select 1 from public.shift_stops st where st.shift_id=v_patrol.shift_id and((v_checkpoint.client_site_id is not null and st.site_id=v_checkpoint.client_site_id)or(v_checkpoint.zone_id is not null and st.zone_id=v_checkpoint.zone_id)))) then raise exception 'Assigned Patrol checkpoint not found';end if;
    v_regular_id:=v_checkpoint.id;
    select st.id into v_shift_stop_id from public.shift_stops st where st.shift_id=v_patrol.shift_id and(st.site_id=v_checkpoint.client_site_id or st.zone_id=v_checkpoint.zone_id) and st.status not in('completed','skipped','cancelled') order by st.stop_order limit 1;
  else raise exception 'Checkpoint kind must be route or site';end if;
  if v_checkpoint.gps_lat is null or v_checkpoint.gps_lng is null then raise exception 'Checkpoint has no verified GPS anchor';end if;
  v_radius:=greatest(coalesce(v_checkpoint.radius,0),1);
  if p_gps_accuracy>v_radius then raise exception 'GPS accuracy is too poor for this checkpoint';end if;
  v_distance:=st_distance(st_setsrid(st_makepoint(p_gps_lng,p_gps_lat),4326)::geography,st_setsrid(st_makepoint(v_checkpoint.gps_lng,v_checkpoint.gps_lat),4326)::geography);
  if v_distance>v_radius then raise exception 'GPS position is outside the checkpoint radius';end if;
  perform pg_advisory_xact_lock(hashtextextended(p_patrol_id::text||':'||p_checkpoint_kind||':'||p_checkpoint_id::text,0));
  select * into v_existing from public.patrol_checkpoint_visits where patrol_id=p_patrol_id and((p_checkpoint_kind='route' and route_checkpoint_id=p_checkpoint_id)or(p_checkpoint_kind='site' and checkpoint_id=p_checkpoint_id)) order by visited_at limit 1;
  if found then return query select v_existing.id,false,v_existing.visited_at,v_existing.scan_method,v_existing.notes;return;end if;
  insert into public.patrol_checkpoint_visits(organization_id,patrol_id,checkpoint_id,route_checkpoint_id,officer_user_id,gps_lat,gps_lng,gps_accuracy,gps_distance_from_checkpoint,within_radius,scan_method,notes,shift_stop_id)
  values(v_patrol.organization_id,v_patrol.id,v_regular_id,v_route_id,v_actor,p_gps_lat,p_gps_lng,p_gps_accuracy,v_distance,true,'gps',nullif(trim(coalesce(p_notes,'')),''),v_shift_stop_id) returning * into v_visit;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_visit.organization_id,v_actor,'patrol.checkpoint_recorded','patrol_checkpoint_visits',v_visit.id,jsonb_build_object('patrol_id',v_visit.patrol_id,'checkpoint_kind',p_checkpoint_kind,'checkpoint_id',p_checkpoint_id,'distance_metres',round(v_distance::numeric,1),'shift_stop_id',v_shift_stop_id));
  return query select v_visit.id,true,v_visit.visited_at,v_visit.scan_method,v_visit.notes;
end;$function$;
REVOKE ALL ON FUNCTION "public"."record_patrol_checkpoint_visit"(p_patrol_id uuid, p_checkpoint_kind text, p_checkpoint_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_gps_accuracy double precision, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_patrol_checkpoint_visit"(p_patrol_id uuid, p_checkpoint_kind text, p_checkpoint_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_gps_accuracy double precision, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_patrol_checkpoint_visit"(p_patrol_id uuid, p_checkpoint_kind text, p_checkpoint_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_gps_accuracy double precision, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."record_patrol_checkpoint_visit"(p_patrol_id uuid, p_checkpoint_kind text, p_checkpoint_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_gps_accuracy double precision, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_patrol_travel_distance"(p_request_id uuid, p_from_stop_id uuid, p_to_stop_id uuid, p_distance_km numeric DEFAULT NULL::numeric, p_odometer_start_km numeric DEFAULT NULL::numeric, p_odometer_end_km numeric DEFAULT NULL::numeric, p_expected_version integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid:=auth.uid();
  v_from public.shift_stops%rowtype;
  v_to public.shift_stops%rowtype;
  v_shift public.shifts%rowtype;
  v_distance numeric;
  v_method text;
  v_replay jsonb;
  v_result jsonb;
  v_before jsonb;
BEGIN
  IF v_actor IS NULL OR p_request_id IS NULL OR p_from_stop_id IS NULL OR p_to_stop_id IS NULL
    OR p_from_stop_id=p_to_stop_id THEN RAISE EXCEPTION 'Two different attended stops and a request identity are required'; END IF;
  SELECT * INTO v_to FROM public.shift_stops WHERE id=p_to_stop_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Destination stop not found'; END IF;
  SELECT * INTO v_shift FROM public.shifts WHERE id=v_to.shift_id;
  IF NOT FOUND OR v_shift.officer_user_id<>v_actor OR NOT EXISTS(
    SELECT 1 FROM public.user_profiles WHERE id=v_actor AND deactivated_at IS NULL
  ) THEN RAISE EXCEPTION 'Only the assigned active officer can record this patrol travel'; END IF;
  SELECT * INTO v_from FROM public.shift_stops WHERE id=p_from_stop_id FOR SHARE;
  IF NOT FOUND OR v_from.shift_id<>v_to.shift_id OR v_from.organization_id<>v_to.organization_id
    OR v_to.organization_id<>v_shift.organization_id THEN RAISE EXCEPTION 'Travel stops must belong to the same assigned patrol shift'; END IF;
  IF v_from.actual_departed_at IS NULL OR v_to.actual_arrived_at IS NULL
    OR v_from.status<>'completed' OR v_to.status NOT IN ('on_scene','completed')
    OR v_from.actual_departed_at>v_to.actual_arrived_at THEN
    RAISE EXCEPTION 'Record departure from the origin and arrival at the destination first';
  END IF;
  IF EXISTS(SELECT 1 FROM public.shift_stops st WHERE st.shift_id=v_shift.id
    AND st.id NOT IN(v_from.id,v_to.id) AND st.actual_arrived_at>v_from.actual_departed_at
    AND st.actual_arrived_at<v_to.actual_arrived_at) THEN
    RAISE EXCEPTION 'Another attended stop lies between these places; record the individual travel legs';
  END IF;
  IF (p_odometer_start_km IS NULL)<>(p_odometer_end_km IS NULL) THEN
    RAISE EXCEPTION 'Enter both odometer readings or a measured distance'; END IF;
  IF p_odometer_start_km IS NOT NULL THEN
    IF p_odometer_start_km<0 OR p_odometer_end_km<p_odometer_start_km THEN
      RAISE EXCEPTION 'Odometer reset or decreasing reading requires review'; END IF;
    v_distance:=p_odometer_end_km-p_odometer_start_km;
    v_method:='odometer_difference';
    IF p_distance_km IS NOT NULL AND p_distance_km<>v_distance THEN
      RAISE EXCEPTION 'Entered distance does not match the odometer difference'; END IF;
  ELSE
    v_distance:=p_distance_km;v_method:='recorded_km';
  END IF;
  IF v_distance IS NULL OR v_distance<0 OR v_distance>1000000 OR v_distance::text IN ('NaN','Infinity','-Infinity')
    OR v_distance<>round(v_distance,3) THEN RAISE EXCEPTION 'Record measured kilometres with at most three decimal places'; END IF;
  SELECT metadata->'result' INTO v_replay FROM public.audit_log
  WHERE organization_id=v_shift.organization_id AND actor_user_id=v_actor AND action='patrol_actual_travel_recorded'
    AND metadata->>'request_id'=p_request_id::text ORDER BY created_at DESC LIMIT 1;
  IF v_replay IS NOT NULL THEN
    IF v_replay->>'from_stop_id'<>p_from_stop_id::text OR v_replay->>'to_stop_id'<>p_to_stop_id::text
      OR (v_replay->>'distance_km')::numeric<>v_distance OR v_replay->>'method'<>v_method
      OR (v_replay->>'odometer_start_km')::numeric IS DISTINCT FROM p_odometer_start_km
      OR (v_replay->>'odometer_end_km')::numeric IS DISTINCT FROM p_odometer_end_km THEN
      RAISE EXCEPTION 'Travel request identity was already used for different evidence'; END IF;
    RETURN v_replay||jsonb_build_object('replayed',true);
  END IF;
  IF v_to.travel_distance_version IS DISTINCT FROM p_expected_version THEN
    RAISE EXCEPTION 'Recorded travel changed; refresh before saving a correction'; END IF;
  v_before:=jsonb_build_object('distance_km',v_to.actual_travel_distance_km,'from_stop_id',v_to.travel_from_stop_id,
    'method',v_to.travel_distance_method,'version',v_to.travel_distance_version,
    'odometer_start_km',v_to.travel_odometer_start_km,'odometer_end_km',v_to.travel_odometer_end_km);
  PERFORM set_config('app.patrol_travel_write',p_request_id::text,true);
  UPDATE public.shift_stops SET actual_travel_distance_km=v_distance,travel_from_stop_id=v_from.id,
    travel_distance_method=v_method,travel_odometer_start_km=p_odometer_start_km,travel_odometer_end_km=p_odometer_end_km,
    travel_distance_version=travel_distance_version+1,travel_distance_recorded_at=clock_timestamp(),travel_distance_recorded_by=v_actor
  WHERE id=v_to.id RETURNING * INTO v_to;
  PERFORM set_config('app.patrol_travel_write','',true);
  v_result:=jsonb_build_object('reference',p_request_id,'from_stop_id',v_from.id,'to_stop_id',v_to.id,
    'distance_km',v_to.actual_travel_distance_km,'method',v_method,'version',v_to.travel_distance_version,
    'recorded_at',v_to.travel_distance_recorded_at,'replayed',false,
    'odometer_start_km',v_to.travel_odometer_start_km,'odometer_end_km',v_to.travel_odometer_end_km);
  INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
  VALUES(v_shift.organization_id,v_actor,'patrol_actual_travel_recorded','shift_stops',v_to.id,
    jsonb_build_object('request_id',p_request_id,'before',v_before,'result',v_result));
  RETURN v_result;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."record_patrol_travel_distance"(p_request_id uuid, p_from_stop_id uuid, p_to_stop_id uuid, p_distance_km numeric, p_odometer_start_km numeric, p_odometer_end_km numeric, p_expected_version integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_patrol_travel_distance"(p_request_id uuid, p_from_stop_id uuid, p_to_stop_id uuid, p_distance_km numeric, p_odometer_start_km numeric, p_odometer_end_km numeric, p_expected_version integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_patrol_travel_distance"(p_request_id uuid, p_from_stop_id uuid, p_to_stop_id uuid, p_distance_km numeric, p_odometer_start_km numeric, p_odometer_end_km numeric, p_expected_version integer) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."record_patrol_travel_distance"(p_request_id uuid, p_from_stop_id uuid, p_to_stop_id uuid, p_distance_km numeric, p_odometer_start_km numeric, p_odometer_end_km numeric, p_expected_version integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_payment_receipt"(p_invoice_id uuid, p_payment_date date, p_payment_amount numeric, p_payment_method text, p_bank_account_id uuid DEFAULT NULL::uuid, p_transaction_reference text DEFAULT NULL::text)
 RETURNS payment_receipts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_invoice public.invoices%rowtype;
  v_receipt public.payment_receipts%rowtype;
  v_remaining_balance numeric(14,2);
BEGIN
  SELECT organization_id INTO v_org FROM public.user_profiles WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_org IS NULL OR NOT public.is_admin_for_org(v_org) THEN RAISE EXCEPTION 'Active finance administrator required'; END IF;
  IF p_payment_amount IS NULL OR p_payment_amount <= 0 THEN RAISE EXCEPTION 'Payment amount must be positive'; END IF;
  SELECT * INTO v_invoice FROM public.invoices WHERE id = p_invoice_id AND organization_id = v_org;
  IF NOT FOUND THEN RAISE EXCEPTION 'Invoice not found in organization'; END IF;
  SELECT COALESCE(v_invoice.total_amount - SUM(payment_amount), v_invoice.total_amount) INTO v_remaining_balance
  FROM public.payment_receipts WHERE invoice_id = p_invoice_id;
  IF p_payment_amount > v_remaining_balance + 0.01 THEN RAISE EXCEPTION 'Payment amount (%) exceeds remaining balance (%)', p_payment_amount, v_remaining_balance; END IF;
  INSERT INTO public.payment_receipts(organization_id, invoice_id, payment_date, payment_amount, payment_method, bank_account_id, transaction_reference, created_by)
  VALUES (v_org, p_invoice_id, p_payment_date, p_payment_amount, p_payment_method, p_bank_account_id, p_transaction_reference, v_actor)
  RETURNING * INTO v_receipt;
  UPDATE public.invoices SET updated_at = now(), paid_at = CASE WHEN p_payment_amount >= v_remaining_balance - 0.01 THEN now() ELSE paid_at END,
    status = CASE WHEN p_payment_amount >= v_remaining_balance - 0.01 THEN 'paid' ELSE status END WHERE id = p_invoice_id;
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_org, v_actor, 'payment_receipt_recorded', 'payment_receipts', v_receipt.id, jsonb_build_object('invoice_id', p_invoice_id, 'payment_amount', p_payment_amount, 'transaction_reference', p_transaction_reference));
  RETURN v_receipt;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."record_payment_receipt"(p_invoice_id uuid, p_payment_date date, p_payment_amount numeric, p_payment_method text, p_bank_account_id uuid, p_transaction_reference text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_payment_receipt"(p_invoice_id uuid, p_payment_date date, p_payment_amount numeric, p_payment_method text, p_bank_account_id uuid, p_transaction_reference text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_payment_receipt"(p_invoice_id uuid, p_payment_date date, p_payment_amount numeric, p_payment_method text, p_bank_account_id uuid, p_transaction_reference text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."record_payment_receipt"(p_invoice_id uuid, p_payment_date date, p_payment_amount numeric, p_payment_method text, p_bank_account_id uuid, p_transaction_reference text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_perception_evidence_envelope"(p_attachment_id uuid, p_idempotency_key text, p_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF jsonb_typeof(p_payload) IS DISTINCT FROM 'object'
     OR jsonb_typeof(p_payload->'fields') IS DISTINCT FROM 'array'
     OR jsonb_array_length(p_payload->'fields') = 0 THEN
    RAISE EXCEPTION 'Perception payload requires a non-empty fields array';
  END IF;
  RETURN public.record_perception_evidence_envelope_unchecked(
    p_attachment_id,
    p_idempotency_key,
    p_payload
  );
END;
$function$;
COMMENT ON FUNCTION "public"."record_perception_evidence_envelope"(p_attachment_id uuid, p_idempotency_key text, p_payload jsonb) IS 'Service-only replay-safe writer. Rejects missing or empty field candidates before invoking the internal recorder.';
REVOKE ALL ON FUNCTION "public"."record_perception_evidence_envelope"(p_attachment_id uuid, p_idempotency_key text, p_payload jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_perception_evidence_envelope"(p_attachment_id uuid, p_idempotency_key text, p_payload jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_perception_evidence_envelope"(p_attachment_id uuid, p_idempotency_key text, p_payload jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_perception_evidence_envelope_unchecked"(p_attachment_id uuid, p_idempotency_key text, p_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_attachment public.bob_attachments%rowtype;
  v_envelope_id uuid;
  v_field jsonb;
  v_domain text := nullif(trim(p_payload->>'domain'), '');
  v_source_sha256 text := lower(coalesce(p_payload->>'source_sha256', ''));
  v_status text := coalesce(nullif(trim(p_payload->>'status'), ''), 'candidate');
BEGIN
  IF coalesce(auth.jwt()->>'role', '') <> 'service_role'
     AND session_user NOT IN ('postgres','supabase_admin') THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;
  IF p_attachment_id IS NULL OR p_idempotency_key IS NULL OR char_length(p_idempotency_key) NOT BETWEEN 8 AND 300 THEN
    RAISE EXCEPTION 'Attachment and idempotency key are required';
  END IF;
  IF jsonb_typeof(p_payload) <> 'object' OR jsonb_typeof(p_payload->'fields') <> 'array' THEN
    RAISE EXCEPTION 'Perception payload and fields array are required';
  END IF;
  IF v_domain IS NULL OR v_domain !~ '^[a-z][a-z0-9_]{1,63}$' OR v_source_sha256 !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'Perception domain or source SHA-256 is invalid';
  END IF;
  IF v_status NOT IN ('candidate','complete','manual_review_required','failed','superseded') THEN
    RAISE EXCEPTION 'Perception envelope status is invalid';
  END IF;

  SELECT * INTO v_attachment FROM public.bob_attachments WHERE id = p_attachment_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Bob attachment is missing'; END IF;

  SELECT id INTO v_envelope_id
  FROM public.perception_evidence_envelopes
  WHERE organization_id = v_attachment.organization_id
    AND idempotency_key = p_idempotency_key;
  IF v_envelope_id IS NOT NULL THEN RETURN v_envelope_id; END IF;

  INSERT INTO public.perception_evidence_envelopes (
    organization_id, schema_version, domain, source_kind, source_sha256,
    attachment_id, source_receipt, model_receipt, derivative_receipts,
    status, idempotency_key
  ) VALUES (
    v_attachment.organization_id,
    coalesce((p_payload->>'schema_version')::integer, 1),
    v_domain,
    coalesce(nullif(trim(p_payload->>'source_kind'), ''), 'document'),
    v_source_sha256,
    v_attachment.id,
    coalesce(p_payload->'source_receipt', '{}'::jsonb),
    coalesce(p_payload->'model_receipt', '{}'::jsonb),
    coalesce(p_payload->'derivative_receipts', '[]'::jsonb),
    v_status,
    p_idempotency_key
  )
  RETURNING id INTO v_envelope_id;

  FOR v_field IN SELECT value FROM jsonb_array_elements(p_payload->'fields')
  LOOP
    INSERT INTO public.perception_evidence_fields (
      organization_id, envelope_id, field_key, candidate_ordinal, value_type,
      candidate_value, normalized_value, candidate_payload, raw_confidence,
      calibrated_confidence, character_confidences, source_locations,
      consensus_rule, conflicts, authority_state, review_required
    ) VALUES (
      v_attachment.organization_id,
      v_envelope_id,
      trim(v_field->>'field_key'),
      coalesce((v_field->>'candidate_ordinal')::integer, 0),
      coalesce(nullif(trim(v_field->>'value_type'), ''), 'text'),
      nullif(v_field->>'candidate_value', ''),
      nullif(v_field->>'normalized_value', ''),
      coalesce(v_field->'candidate_payload', '{}'::jsonb),
      nullif(v_field->>'raw_confidence', '')::real,
      nullif(v_field->>'calibrated_confidence', '')::real,
      coalesce(v_field->'character_confidences', '[]'::jsonb),
      coalesce(v_field->'source_locations', '[]'::jsonb),
      nullif(v_field->>'consensus_rule', ''),
      coalesce(v_field->'conflicts', '[]'::jsonb),
      coalesce(nullif(v_field->>'authority_state', ''), 'candidate'),
      coalesce((v_field->>'review_required')::boolean, true)
    );
  END LOOP;

  INSERT INTO public.audit_log (
    organization_id, actor_user_id, action, target_table, target_id, metadata
  ) VALUES (
    v_attachment.organization_id, auth.uid(), 'perception_evidence_recorded',
    'perception_evidence_envelopes', v_envelope_id,
    jsonb_build_object('domain', v_domain, 'attachment_id', p_attachment_id, 'schema_version', coalesce((p_payload->>'schema_version')::integer, 1))
  );
  RETURN v_envelope_id;
END;
$function$;
COMMENT ON FUNCTION "public"."record_perception_evidence_envelope_unchecked"(p_attachment_id uuid, p_idempotency_key text, p_payload jsonb) IS 'Internal service-gated implementation. Invoke record_perception_evidence_envelope so payload shape is validated first.';
REVOKE ALL ON FUNCTION "public"."record_perception_evidence_envelope_unchecked"(p_attachment_id uuid, p_idempotency_key text, p_payload jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_perception_evidence_envelope_unchecked"(p_attachment_id uuid, p_idempotency_key text, p_payload jsonb) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."record_person_document"(p_organization_id uuid, p_person_id uuid, p_client_request_id uuid, p_document_type text, p_file_name text, p_storage_path text, p_sha256 text, p_reason text, p_notice jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_existing public.person_record_documents%rowtype;
  v_type public.person_record_document_types%rowtype;
  v_notice_id uuid;
  v_receipt jsonb;
  v_request jsonb := jsonb_build_object('person_id', p_person_id, 'document_type', p_document_type,
    'file_name', p_file_name, 'storage_path', p_storage_path, 'sha256', p_sha256, 'reason', btrim(p_reason), 'notice', p_notice);
  v_size bigint;
  v_mime text;
  v_owner text;
  v_hash text;
  v_client uuid;
  v_issued timestamptz;
  v_expires timestamptz;
BEGIN
  IF NOT public.person_record_admin_allowed(p_organization_id, p_person_id) THEN
    RAISE EXCEPTION 'Person record not found or administrator access denied';
  END IF;
  IF p_client_request_id IS NULL OR p_storage_path IS DISTINCT FROM
    p_organization_id::text || '/person/' || p_person_id::text || '/' || p_client_request_id::text || '/source' THEN
    RAISE EXCEPTION 'Upload path must match this organisation, person and request';
  END IF;
  IF coalesce(length(p_file_name), 0) NOT BETWEEN 1 AND 255 OR p_file_name ~ '[/\\]'
    OR coalesce(p_sha256, '') !~ '^[0-9a-f]{64}$' OR coalesce(length(btrim(p_reason)), 0) NOT BETWEEN 5 AND 1000 THEN
    RAISE EXCEPTION 'A valid source name, SHA-256 and reason of 5 to 1000 characters are required';
  END IF;
  SELECT * INTO v_type FROM public.person_record_document_types WHERE code = p_document_type;
  IF NOT FOUND THEN RAISE EXCEPTION 'Select a configured document type'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_organization_id::text || ':person-document:' || p_client_request_id, 0));
  SELECT * INTO v_existing FROM public.person_record_documents
    WHERE organization_id = p_organization_id AND client_request_id = p_client_request_id;
  IF FOUND THEN
    IF v_existing.request_payload IS DISTINCT FROM v_request THEN RAISE EXCEPTION 'Request ID already used for a different document'; END IF;
    RETURN to_jsonb(v_existing) - 'request_payload';
  END IF;
  SELECT (o.metadata->>'size')::bigint, o.metadata->>'mimetype', o.owner_id, o.user_metadata->>'sha256'
    INTO v_size, v_mime, v_owner, v_hash FROM storage.objects o
    WHERE o.bucket_id = 'person-documents' AND o.name = p_storage_path;
  IF NOT FOUND OR v_size IS NULL OR v_size NOT BETWEEN 1 AND 10485760
    OR v_mime IS NULL OR v_mime NOT IN ('application/pdf','image/jpeg','image/png','image/webp')
    OR v_owner IS DISTINCT FROM auth.uid()::text OR v_hash IS DISTINCT FROM p_sha256 THEN
    RAISE EXCEPTION 'Source upload is missing, invalid, or does not match your file';
  END IF;
  IF v_type.notice_type IS NOT NULL THEN
    IF jsonb_typeof(p_notice) IS DISTINCT FROM 'object' OR p_notice->'confirmed' IS DISTINCT FROM 'true'::jsonb
      OR coalesce(p_notice->>'issued_date', '') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
      OR coalesce(length(btrim(p_notice->>'area')), 0) NOT BETWEEN 1 AND 500
      OR coalesce(length(p_notice->>'notice_number'), 0) > 100
      OR coalesce(length(p_notice->>'source_author'), 0) > 200 THEN
      RAISE EXCEPTION 'Review the existing issued notice, its client, issue date and affected place';
    END IF;
    IF EXISTS (SELECT 1 FROM jsonb_object_keys(p_notice) field
      WHERE field NOT IN ('confirmed','client_organization_id','issued_date','expires_date','notice_number','area','source_author')) THEN
      RAISE EXCEPTION 'Unsupported notice field';
    END IF;
    v_client := (p_notice->>'client_organization_id')::uuid;
    IF NOT EXISTS (SELECT 1 FROM public.service_agreements a WHERE a.provider_organization_id = p_organization_id
      AND a.client_organization_id = v_client AND a.agreement_type = 'operational'
      AND (a.starts_on IS NULL OR a.starts_on <= current_date) AND (a.ends_on IS NULL OR a.ends_on >= current_date)) THEN
      RAISE EXCEPTION 'Select a client with a current operational agreement';
    END IF;
    v_issued := (p_notice->>'issued_date')::date::timestamp AT TIME ZONE 'Pacific/Auckland';
    IF v_issued > clock_timestamp() THEN RAISE EXCEPTION 'The source notice cannot be issued in the future'; END IF;
    IF nullif(p_notice->>'expires_date', '') IS NOT NULL THEN
      v_expires := (p_notice->>'expires_date')::date::timestamp AT TIME ZONE 'Pacific/Auckland';
    END IF;
    SELECT public.import_person_notice(
      p_organization_id => v_client, p_notice_type => v_type.notice_type, p_status => 'issued',
      p_issued_at => v_issued, p_subject_display_name => (SELECT display_name FROM public.canonical_people WHERE id = p_person_id),
      p_source_document_name => p_file_name, p_source_reference => 'storage://person-documents/' || p_storage_path,
      p_source_sha256 => p_sha256, p_import_key => 'person-document:' || p_client_request_id,
      p_expires_at => v_expires, p_canonical_person_id => p_person_id,
      p_notice_number => p_notice->>'notice_number', p_area => p_notice->>'area',
      p_source_author => p_notice->>'source_author') INTO v_receipt;
    v_notice_id := (v_receipt->>'notice_id')::uuid;
    IF v_notice_id IS NULL THEN RAISE EXCEPTION 'No notice receipt returned; document was not recorded'; END IF;
  ELSIF p_notice IS NOT NULL THEN
    RAISE EXCEPTION 'Supporting documents do not issue notices';
  END IF;
  INSERT INTO public.person_record_documents(organization_id, canonical_person_id, document_type, file_name,
    storage_path, sha256, mime_type, file_size_bytes, notice_id, uploaded_by, client_request_id, request_payload)
  VALUES (p_organization_id, p_person_id, p_document_type, p_file_name, p_storage_path, p_sha256,
    v_mime, v_size, v_notice_id, auth.uid(), p_client_request_id, v_request) RETURNING * INTO v_existing;
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES(p_organization_id, auth.uid(), 'person_document_recorded', 'person_record_documents', v_existing.id,
    jsonb_build_object('client_request_id', p_client_request_id, 'canonical_person_id', p_person_id,
      'notice_id', v_notice_id, 'sha256', p_sha256, 'reason', btrim(p_reason)));
  RETURN to_jsonb(v_existing) - 'request_payload';
END;
$function$;
REVOKE ALL ON FUNCTION "public"."record_person_document"(p_organization_id uuid, p_person_id uuid, p_client_request_id uuid, p_document_type text, p_file_name text, p_storage_path text, p_sha256 text, p_reason text, p_notice jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_person_document"(p_organization_id uuid, p_person_id uuid, p_client_request_id uuid, p_document_type text, p_file_name text, p_storage_path text, p_sha256 text, p_reason text, p_notice jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_person_document"(p_organization_id uuid, p_person_id uuid, p_client_request_id uuid, p_document_type text, p_file_name text, p_storage_path text, p_sha256 text, p_reason text, p_notice jsonb) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."record_person_interaction"(p_client_request_id uuid, p_organization_id uuid, p_interaction_type text, p_notes text, p_person_record_id uuid DEFAULT NULL::uuid, p_new_person_name text DEFAULT NULL::text, p_dispatch_job_id uuid DEFAULT NULL::uuid, p_shift_id uuid DEFAULT NULL::uuid, p_interacted_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_source text DEFAULT 'field'::text, p_details jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_profile public.user_profiles%rowtype;
  v_is_admin boolean;
  v_can_search boolean;
  v_job public.dispatch_jobs%rowtype;
  v_shift public.shifts%rowtype;
  v_existing public.person_interactions%rowtype;
  v_person_id uuid := p_person_record_id;
  v_canonical_id uuid;
  v_matches uuid[];
  v_created boolean := false;
  v_name text := nullif(regexp_replace(trim(coalesce(p_new_person_name, '')), '\s+', ' ', 'g'), '');
  v_notes text := nullif(trim(coalesce(p_notes, '')), '');
  v_at timestamptz := coalesce(p_interacted_at, clock_timestamp());
  v_officer uuid;
  v_location uuid;
  v_site uuid;
  v_zone uuid;
  v_interaction public.person_interactions%rowtype;
  v_details jsonb;
  v_dob date;
  v_phone text;
  v_proposal text;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Sign in to record a person interaction' USING ERRCODE = '42501'; END IF;
  SELECT * INTO v_profile FROM public.user_profiles WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_profile.id IS NULL THEN RAISE EXCEPTION 'Your account is not active' USING ERRCODE = '42501'; END IF;
  IF p_client_request_id IS NULL THEN RAISE EXCEPTION 'A client request id is required'; END IF;
  IF p_organization_id IS NULL THEN RAISE EXCEPTION 'Choose the organisation this interaction belongs to'; END IF;
  IF p_interaction_type IS NULL OR p_interaction_type NOT IN (
    'spoken_to', 'warning_given', 'trespass_notice_served', 'moved_on', 'welfare_check',
    'observed', 'report_attached', 'other') THEN
    RAISE EXCEPTION 'Choose what happened with this person';
  END IF;
  IF p_source IS NULL OR p_source NOT IN ('field', 'admin', 'bob') THEN RAISE EXCEPTION 'Unsupported interaction source'; END IF;
  IF v_notes IS NULL OR length(v_notes) < 3 THEN RAISE EXCEPTION 'Describe what happened with this person'; END IF;
  IF length(v_notes) > 4000 THEN RAISE EXCEPTION 'Interaction notes must be 4000 characters or fewer'; END IF;
  IF v_at > clock_timestamp() + interval '5 minutes' THEN RAISE EXCEPTION 'The interaction time cannot be in the future'; END IF;
  IF (p_person_record_id IS NULL) = (v_name IS NULL) THEN RAISE EXCEPTION 'Choose an existing person or enter a new person''s name'; END IF;
  IF v_name IS NOT NULL AND (length(v_name) < 2 OR length(v_name) > 120) THEN RAISE EXCEPTION 'Enter the person''s name as given (2 to 120 characters)'; END IF;
  IF p_dispatch_job_id IS NULL AND p_shift_id IS NULL THEN RAISE EXCEPTION 'Record the interaction against a dispatch job or shift'; END IF;
  IF p_details IS NOT NULL AND p_details <> '{}'::jsonb THEN
    IF jsonb_typeof(p_details) <> 'object'
      OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_details) k WHERE k NOT IN ('description', 'date_of_birth', 'phone', 'address')) THEN
      RAISE EXCEPTION 'Person details may only include a description, date of birth, phone and address';
    END IF;
    IF nullif(trim(p_details->>'date_of_birth'), '') IS NOT NULL THEN
      BEGIN
        v_dob := (p_details->>'date_of_birth')::date;
      EXCEPTION WHEN others THEN
        RAISE EXCEPTION 'Enter the date of birth as a date (YYYY-MM-DD)';
      END;
      IF v_dob < date '1900-01-01' OR v_dob > current_date THEN RAISE EXCEPTION 'Enter a date of birth between 1900 and today'; END IF;
    END IF;
    v_phone := nullif(trim(p_details->>'phone'), '');
    IF v_phone IS NOT NULL AND v_phone !~ '^[0-9+() -]{5,40}$' THEN RAISE EXCEPTION 'Enter the phone number using digits, spaces, +, ( ) or -'; END IF;
    IF length(trim(coalesce(p_details->>'description', ''))) > 1000 THEN RAISE EXCEPTION 'The description must be 1000 characters or fewer'; END IF;
    IF length(trim(coalesce(p_details->>'address', ''))) > 300 THEN RAISE EXCEPTION 'The address must be 300 characters or fewer'; END IF;
    v_details := jsonb_strip_nulls(jsonb_build_object(
      'description', nullif(regexp_replace(trim(coalesce(p_details->>'description', '')), '\s+', ' ', 'g'), ''),
      'date_of_birth', v_dob::text,
      'phone', v_phone,
      'address', nullif(regexp_replace(trim(coalesce(p_details->>'address', '')), '\s+', ' ', 'g'), '')));
    IF v_details = '{}'::jsonb THEN v_details := NULL; END IF;
  END IF;

  -- A retried request returns the interaction it already recorded instead of writing a second one.
  SELECT * INTO v_existing FROM public.person_interactions
  WHERE organization_id = p_organization_id AND client_request_id = p_client_request_id;
  IF v_existing.id IS NOT NULL THEN
    IF v_existing.created_by IS DISTINCT FROM v_actor THEN RAISE EXCEPTION 'This request id was already used' USING ERRCODE = '42501'; END IF;
    RETURN jsonb_build_object('interaction_id', v_existing.id, 'person_record_id', v_existing.person_record_id,
      'outcome', 'already_recorded');
  END IF;

  v_is_admin := public.is_admin_for_org(p_organization_id);
  v_can_search := v_is_admin OR public.can_search_people(p_organization_id);

  IF p_dispatch_job_id IS NOT NULL THEN
    SELECT * INTO v_job FROM public.dispatch_jobs WHERE id = p_dispatch_job_id;
    IF v_job.id IS NULL OR v_job.organization_id IS DISTINCT FROM p_organization_id THEN RAISE EXCEPTION 'Dispatch job not found in this organisation'; END IF;
    IF NOT v_is_admin THEN
      IF NOT (v_job.assigned_officer_id = v_actor
        OR EXISTS (SELECT 1 FROM public.dispatch_resources dr WHERE dr.id = v_job.dispatch_resource_id AND dr.assigned_officer_id = v_actor)
        OR EXISTS (SELECT 1 FROM public.shifts s WHERE s.id = v_job.shift_id AND s.officer_user_id = v_actor)) THEN
        RAISE EXCEPTION 'Only the officer on this job or an administrator can record people for it' USING ERRCODE = '42501';
      END IF;
      IF v_job.status = 'cancelled' OR (v_job.completed_at IS NOT NULL AND v_job.completed_at < clock_timestamp() - interval '24 hours') THEN
        RAISE EXCEPTION 'This job is closed; ask an administrator to add the interaction' USING ERRCODE = '42501';
      END IF;
    END IF;
    IF p_shift_id IS NULL AND v_job.shift_id IS NOT NULL THEN
      SELECT * INTO v_shift FROM public.shifts WHERE id = v_job.shift_id;
    END IF;
  END IF;

  IF p_shift_id IS NOT NULL THEN
    SELECT * INTO v_shift FROM public.shifts WHERE id = p_shift_id;
    IF v_shift.id IS NULL OR v_shift.organization_id IS DISTINCT FROM p_organization_id THEN RAISE EXCEPTION 'Shift not found in this organisation'; END IF;
    IF v_job.id IS NOT NULL AND v_job.shift_id IS DISTINCT FROM v_shift.id THEN RAISE EXCEPTION 'The dispatch job is not on this shift'; END IF;
    IF NOT v_is_admin AND v_job.id IS NULL THEN
      IF v_shift.officer_user_id IS DISTINCT FROM v_actor THEN
        RAISE EXCEPTION 'Only the officer on this shift or an administrator can record people for it' USING ERRCODE = '42501';
      END IF;
      IF v_shift.status NOT IN ('accepted', 'in_progress', 'completed')
        OR (v_shift.actual_end IS NOT NULL AND v_shift.actual_end < clock_timestamp() - interval '24 hours') THEN
        RAISE EXCEPTION 'This shift is closed; ask an administrator to add the interaction' USING ERRCODE = '42501';
      END IF;
    END IF;
  END IF;

  v_location := coalesce(v_job.location_id, v_shift.location_id);
  v_site := v_job.client_site_id;
  v_zone := coalesce(v_job.zone_id, v_shift.zone_id);
  IF v_location IS NULL AND v_site IS NULL AND v_zone IS NULL THEN
    RAISE EXCEPTION 'This job or shift has no place recorded, so the interaction cannot be anchored';
  END IF;
  -- An administrator recording after the fact credits the officer who was on the job or shift.
  v_officer := CASE WHEN v_is_admin THEN coalesce(v_job.assigned_officer_id, v_shift.officer_user_id, v_actor) ELSE v_actor END;

  IF p_person_record_id IS NOT NULL THEN
    IF NOT v_can_search THEN
      RAISE EXCEPTION 'Enter the person''s name; choosing an existing record needs person-search access' USING ERRCODE = '42501';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.person_records pr
      WHERE pr.id = p_person_record_id AND pr.organization_id = p_organization_id
        AND NOT (pr.metadata ? 'merged_into_person_record_id')
        AND NOT (pr.metadata ? 'resolved_into_person_record_id')
    ) THEN RAISE EXCEPTION 'Person record not found in this organisation'; END IF;
  ELSE
    -- Serialise per organisation and name so two officers naming the same person at once share one draft.
    PERFORM pg_advisory_xact_lock(hashtextextended(p_organization_id::text || ':' || coalesce(public.normalize_person_name(v_name), ''), 0));
    SELECT array_agg(pr.id) INTO v_matches FROM public.person_records pr
    WHERE pr.organization_id = p_organization_id
      AND public.normalize_person_name(pr.display_name) = public.normalize_person_name(v_name)
      AND NOT (pr.metadata ? 'merged_into_person_record_id')
      AND NOT (pr.metadata ? 'resolved_into_person_record_id');
    IF cardinality(v_matches) = 1 THEN
      v_person_id := v_matches[1];
    ELSE
      INSERT INTO public.person_records (organization_id, display_name, review_state, metadata)
      VALUES (p_organization_id, v_name, 'manual_review_required', jsonb_strip_nulls(jsonb_build_object(
        'profile_details', jsonb_strip_nulls(jsonb_build_object('category', 'Field interaction',
          'notes', v_details->>'description', 'date_of_birth', v_details->>'date_of_birth',
          'phone', v_details->>'phone', 'address', v_details->>'address')),
        'created_from', 'person_interaction', 'recorded_by', v_actor,
        'dispatch_job_id', v_job.id, 'shift_id', v_shift.id,
        'possible_duplicate_count', CASE WHEN cardinality(v_matches) > 1 THEN cardinality(v_matches) END)))
      RETURNING id INTO v_person_id;
      v_created := true;
    END IF;
  END IF;

  v_canonical_id := public.ensure_canonical_person_for_record(v_person_id);
  IF v_canonical_id IS NULL THEN RAISE EXCEPTION 'The person''s platform identity could not be confirmed'; END IF;

  -- A new draft already carries the details; an administrator's details apply now; anyone else's wait for review.
  v_proposal := CASE WHEN v_details IS NULL THEN NULL WHEN v_created THEN 'applied_to_draft'
    WHEN v_is_admin THEN 'applied' ELSE 'pending' END;

  INSERT INTO public.person_interactions (
    organization_id, person_id, person_record_id, officer_user_id, interaction_type, notes, interacted_at,
    location_id, client_site_id, zone_id, dispatch_job_id, shift_id, client_request_id, created_by, source,
    proposed_details, proposal_status, proposal_reviewed_by, proposal_reviewed_at)
  VALUES (
    p_organization_id, v_canonical_id, v_person_id, v_officer, p_interaction_type, v_notes, v_at,
    v_location, v_site, v_zone, v_job.id, v_shift.id, p_client_request_id, v_actor, p_source,
    v_details, v_proposal,
    CASE WHEN v_proposal = 'applied' THEN v_actor END, CASE WHEN v_proposal = 'applied' THEN clock_timestamp() END)
  RETURNING * INTO v_interaction;

  IF v_proposal = 'applied' THEN
    PERFORM public.apply_person_interaction_details(v_interaction.id, 'Details recorded with a person interaction by an administrator');
  END IF;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (p_organization_id, v_actor, 'person_interaction_recorded', 'person_interactions', v_interaction.id,
    jsonb_strip_nulls(jsonb_build_object(
      'person_record_id', v_person_id, 'canonical_person_id', v_canonical_id, 'person_created', v_created,
      'interaction_type', p_interaction_type, 'dispatch_job_id', v_job.id, 'shift_id', v_shift.id, 'source', p_source,
      'detail_fields', CASE WHEN v_details IS NOT NULL THEN to_jsonb(array(SELECT jsonb_object_keys(v_details))) END,
      'details_status', v_proposal)));

  -- Officers without person-search access are not told whether the name matched an existing record, so the
  -- detail outcome (draft versus pending review) is also withheld from them.
  RETURN jsonb_strip_nulls(jsonb_build_object(
    'interaction_id', v_interaction.id,
    'person_record_id', v_person_id,
    'outcome', 'recorded',
    'person_created', CASE WHEN v_can_search THEN v_created END,
    'details_status', CASE WHEN v_can_search THEN v_proposal END,
    'review_state', CASE WHEN v_can_search THEN (SELECT review_state FROM public.person_records WHERE id = v_person_id) END));
END;
$function$;
COMMENT ON FUNCTION "public"."record_person_interaction"(p_client_request_id uuid, p_organization_id uuid, p_interaction_type text, p_notes text, p_person_record_id uuid, p_new_person_name text, p_dispatch_job_id uuid, p_shift_id uuid, p_interacted_at timestamp with time zone, p_source text, p_details jsonb) IS 'Officer/admin write path for person interaction history and field-supplied person details. Officers record on their own dispatch job or shift; a new name creates a manual-review draft carrying the details, and details for an existing record wait for administrator review. Idempotent per client request and audited.';
REVOKE ALL ON FUNCTION "public"."record_person_interaction"(p_client_request_id uuid, p_organization_id uuid, p_interaction_type text, p_notes text, p_person_record_id uuid, p_new_person_name text, p_dispatch_job_id uuid, p_shift_id uuid, p_interacted_at timestamp with time zone, p_source text, p_details jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_person_interaction"(p_client_request_id uuid, p_organization_id uuid, p_interaction_type text, p_notes text, p_person_record_id uuid, p_new_person_name text, p_dispatch_job_id uuid, p_shift_id uuid, p_interacted_at timestamp with time zone, p_source text, p_details jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_person_interaction"(p_client_request_id uuid, p_organization_id uuid, p_interaction_type text, p_notes text, p_person_record_id uuid, p_new_person_name text, p_dispatch_job_id uuid, p_shift_id uuid, p_interacted_at timestamp with time zone, p_source text, p_details jsonb) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."record_person_interaction"(p_client_request_id uuid, p_organization_id uuid, p_interaction_type text, p_notes text, p_person_record_id uuid, p_new_person_name text, p_dispatch_job_id uuid, p_shift_id uuid, p_interacted_at timestamp with time zone, p_source text, p_details jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_radio_transcript_segment"(p_transmission_id uuid, p_sequence integer, p_text text, p_confidence real DEFAULT 1.0, p_is_final boolean DEFAULT true)
 RETURNS TABLE(segment_id uuid, transmission_id uuid, sequence integer, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_trans public.ptt_transmissions%rowtype;
  v_segment public.radio_transcript_segments%rowtype;
  v_clean_text text := nullif(trim(coalesce(p_text, '')), '');
begin
  if v_user_id is null then raise exception 'Authentication required'; end if;
  if v_clean_text is null then raise exception 'Transcript text is required'; end if;

  select t.* into v_trans from public.ptt_transmissions t where t.id = p_transmission_id;
  if not found then raise exception 'PTT transmission not found'; end if;
  if v_trans.speaker_user_id <> v_user_id and not public.is_admin_for_org(v_trans.organization_id) then
    raise exception 'Not authorised to transcribe this PTT transmission';
  end if;

  insert into public.radio_transcript_segments (
    organization_id, transmission_id, sequence, text, confidence, is_final
  ) values (
    v_trans.organization_id, v_trans.id, coalesce(p_sequence, 1), v_clean_text, coalesce(p_confidence, 1.0), coalesce(p_is_final, true)
  ) returning * into v_segment;

  return query select v_segment.id, v_segment.transmission_id, v_segment.sequence, v_segment.created_at;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."record_radio_transcript_segment"(p_transmission_id uuid, p_sequence integer, p_text text, p_confidence real, p_is_final boolean) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_radio_transcript_segment"(p_transmission_id uuid, p_sequence integer, p_text text, p_confidence real, p_is_final boolean) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_radio_transcript_segment"(p_transmission_id uuid, p_sequence integer, p_text text, p_confidence real, p_is_final boolean) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."record_radio_transcript_segment"(p_transmission_id uuid, p_sequence integer, p_text text, p_confidence real, p_is_final boolean) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_report_pack_pdf"(p_pack_id uuid, p_expected_updated_at timestamp with time zone, p_pdf_path text, p_pdf_sha256 text, p_renderer_version text, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_actor uuid := p_actor_user_id;
  v_pack public.monthly_report_packs%rowtype;
  v_now timestamptz := clock_timestamp();
begin
  if v_actor is null then raise exception 'Provider administrator identity required'; end if;
  select * into v_pack from public.monthly_report_packs where id = p_pack_id for update;
  if not found then raise exception 'Report pack not found'; end if;
  if not public.report_provider_custodian_for_actor(v_pack.organization_id, v_actor) then
    raise exception 'Provider administrator access required';
  end if;
  if v_pack.status not in ('draft', 'generated') then raise exception 'Only draft or published report packs can be rendered'; end if;
  if v_pack.delivery_attempt_id is not null then raise exception 'Report email delivery is in progress or requires review before retry'; end if;
  if v_pack.updated_at is distinct from p_expected_updated_at then raise exception 'Report changed while the PDF was rendering'; end if;
  if nullif(btrim(coalesce(p_pdf_path, '')), '') is null
     or nullif(btrim(coalesce(p_pdf_sha256, '')), '') is null
     or nullif(btrim(coalesce(p_renderer_version, '')), '') is null then
    raise exception 'Complete PDF metadata is required';
  end if;
  if position(format('org/%s/report-packs/%s/', v_pack.organization_id, v_pack.id) in p_pdf_path) <> 1
     or p_pdf_sha256 !~ '^[0-9a-f]{64}$'
     or length(p_renderer_version) > 160 then
    raise exception 'Invalid report PDF metadata';
  end if;

  update public.monthly_report_packs
  set pdf_path = p_pdf_path,
      pdf_mime_type = 'application/pdf',
      pdf_sha256 = p_pdf_sha256,
      pdf_renderer_version = p_renderer_version,
      pdf_source_updated_at = v_now,
      updated_at = v_now
  where id = p_pack_id;

  insert into public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (v_pack.organization_id, v_actor, 'monthly_report_pack_pdf_generated', 'monthly_report_packs', p_pack_id,
    jsonb_build_object('pdf_path', p_pdf_path, 'pdf_sha256', p_pdf_sha256, 'renderer_version', p_renderer_version,
      'replaced_pdf_path', v_pack.pdf_path));

  return jsonb_build_object('id', p_pack_id, 'pdf_path', p_pdf_path, 'pdf_mime_type', 'application/pdf',
    'pdf_sha256', p_pdf_sha256, 'pdf_renderer_version', p_renderer_version, 'pdf_source_updated_at', v_now);
end;
$function$;
REVOKE ALL ON FUNCTION "public"."record_report_pack_pdf"(p_pack_id uuid, p_expected_updated_at timestamp with time zone, p_pdf_path text, p_pdf_sha256 text, p_renderer_version text, p_actor_user_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_report_pack_pdf"(p_pack_id uuid, p_expected_updated_at timestamp with time zone, p_pdf_path text, p_pdf_sha256 text, p_renderer_version text, p_actor_user_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_report_pack_pdf"(p_pack_id uuid, p_expected_updated_at timestamp with time zone, p_pdf_path text, p_pdf_sha256 text, p_renderer_version text, p_actor_user_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_retrospective_noise_job_outcome"(p_client_request_id uuid, p_job_id uuid, p_expected_status text, p_source_name text, p_source_sha256 text, p_source_reference text, p_source_time_zone text, p_source_received_local text, p_source_arrived_local text, p_source_departed_local text, p_outcome_notes text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_job public.dispatch_jobs%rowtype;
  v_existing public.audit_log%rowtype;
  v_shift public.shifts%rowtype;
  v_now timestamptz;
  v_source_received timestamp without time zone;
  v_source_arrived timestamp without time zone;
  v_source_departed timestamp without time zone;
  v_received_at timestamptz;
  v_arrived_at timestamptz;
  v_departed_at timestamptz;
  v_prior_stamp_mode text;
  v_outcome text;
  v_previous jsonb;
  v_resulting jsonb;
  v_finance record;
  v_finance_result jsonb;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Authentication is required';
  END IF;
  IF p_client_request_id IS NULL THEN
    RAISE EXCEPTION 'A client request ID is required';
  END IF;

  SELECT * INTO v_job
  FROM public.dispatch_jobs j
  WHERE j.id = p_job_id
  FOR UPDATE;
  IF NOT FOUND OR NOT public.is_admin_for_org(v_job.organization_id) THEN
    RAISE EXCEPTION 'Dispatch job not found or access denied';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_job.organization_id::text || ':' || p_client_request_id::text, 0)
  );

  SELECT * INTO v_existing
  FROM public.audit_log al
  WHERE al.organization_id = v_job.organization_id
    AND al.action = 'dispatch_job_retroactive_register_completion'
    AND al.target_table = 'dispatch_jobs'
    AND al.metadata ->> 'client_request_id' = p_client_request_id::text
  ORDER BY al.created_at DESC
  LIMIT 1;
  IF FOUND THEN
    IF v_existing.target_id IS DISTINCT FROM p_job_id THEN
      RAISE EXCEPTION 'Client request ID was already used for a different dispatch job';
    END IF;
    RETURN jsonb_build_object(
      'replayed', true,
      'target_id', p_job_id,
      'previous', v_existing.metadata -> 'previous',
      'resulting', v_existing.metadata -> 'resulting',
      'finance', v_existing.metadata -> 'finance'
    );
  END IF;

  IF p_expected_status IS DISTINCT FROM 'pending' OR v_job.status IS DISTINCT FROM p_expected_status THEN
    RAISE EXCEPTION 'Dispatch job changed since it was opened';
  END IF;
  IF v_job.job_type <> 'noise_control' AND v_job.module_key IS DISTINCT FROM 'noise_control' THEN
    RAISE EXCEPTION 'This action is only for noise-control jobs';
  END IF;
  IF v_job.client_site_id IS NULL THEN
    RAISE EXCEPTION 'The noise-source work place must be linked before recording an outcome';
  END IF;
  IF v_job.shift_stop_id IS NOT NULL THEN
    RAISE EXCEPTION 'This job is already on an officer stop; reconcile its attendance through the stop workflow';
  END IF;
  IF v_job.dispatched_at IS NOT NULL
    OR v_job.acknowledged_at IS NOT NULL
    OR v_job.en_route_at IS NOT NULL
    OR v_job.on_scene_at IS NOT NULL
    OR v_job.completed_at IS NOT NULL THEN
    RAISE EXCEPTION 'This job already has lifecycle timestamps and needs review before retrospective completion';
  END IF;

  IF nullif(btrim(coalesce(p_source_name, '')), '') IS NULL
    OR length(btrim(p_source_name)) > 255
    OR pg_catalog.strpos(p_source_name, '/') > 0
    OR pg_catalog.strpos(p_source_name, pg_catalog.chr(92)) > 0
    OR lower(coalesce(p_source_sha256, '')) !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'A source file name and valid SHA-256 hash are required';
  END IF;
  IF coalesce(p_source_reference, '') !~ '^[0-9]{1,32}$'
    OR coalesce(v_job.briefing_notes, '') !~ ('(^|[^0-9])' || p_source_reference || '([^0-9]|$)') THEN
    RAISE EXCEPTION 'The register reference must exactly match a number in this job''s briefing';
  END IF;
  IF p_source_time_zone IS DISTINCT FROM 'Pacific/Auckland' THEN
    RAISE EXCEPTION 'Source times must be recorded in Pacific/Auckland';
  END IF;
  IF coalesce(p_source_received_local, '') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}$'
    OR coalesce(p_source_arrived_local, '') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}$'
    OR coalesce(p_source_departed_local, '') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}$' THEN
    RAISE EXCEPTION 'Enter each source time as a New Zealand local date and time';
  END IF;
  BEGIN
    v_source_received := replace(p_source_received_local, 'T', ' ')::timestamp without time zone;
    v_source_arrived := replace(p_source_arrived_local, 'T', ' ')::timestamp without time zone;
    v_source_departed := replace(p_source_departed_local, 'T', ' ')::timestamp without time zone;
  EXCEPTION
    WHEN datetime_field_overflow OR invalid_datetime_format THEN
      RAISE EXCEPTION 'One or more source date/time values are invalid';
  END;
  IF v_source_received > v_source_arrived OR v_source_arrived > v_source_departed THEN
    RAISE EXCEPTION 'Source times must be in received, on-site, off-site order';
  END IF;

  v_now := clock_timestamp();
  v_received_at := v_source_received AT TIME ZONE 'Pacific/Auckland';
  v_arrived_at := v_source_arrived AT TIME ZONE 'Pacific/Auckland';
  v_departed_at := v_source_departed AT TIME ZONE 'Pacific/Auckland';
  IF v_departed_at > v_now THEN
    RAISE EXCEPTION 'The source off-site time cannot be in the future';
  END IF;
  IF nullif(btrim(coalesce(p_outcome_notes, '')), '') IS NULL
    OR length(btrim(p_outcome_notes)) > 2000 THEN
    RAISE EXCEPTION 'Enter a source-reported outcome (up to 2,000 characters)';
  END IF;
  IF nullif(btrim(coalesce(p_reason, '')), '') IS NULL
    OR length(btrim(p_reason)) > 1000 THEN
    RAISE EXCEPTION 'A reason for the retrospective correction is required';
  END IF;

  PERFORM 1 FROM public.sla_clocks c
  WHERE c.organization_id = v_job.organization_id AND c.dispatch_job_id = p_job_id
  FOR UPDATE;

  v_previous := jsonb_build_object(
    'status', v_job.status,
    'dispatched_at', v_job.dispatched_at,
    'on_scene_at', v_job.on_scene_at,
    'completed_at', v_job.completed_at,
    'outcome_notes', v_job.outcome_notes,
    'sla_clocks', (
      SELECT coalesce(jsonb_agg(jsonb_build_object(
        'id', c.id, 'started_at', c.started_at, 'arrived_at', c.arrived_at,
        'elapsed_minutes', c.elapsed_minutes, 'target_minutes', c.target_minutes, 'status', c.status
      ) ORDER BY c.id), '[]'::jsonb)
      FROM public.sla_clocks c
      WHERE c.organization_id = v_job.organization_id AND c.dispatch_job_id = p_job_id
    )
  );
  v_outcome := format(
    'Retrospective source-register outcome. Reference %s; source-reported on-site %s and off-site %s (%s). FCM did not capture GPS for this historical record. Outcome: %s',
    p_source_reference,
    p_source_arrived_local,
    p_source_departed_local,
    p_source_time_zone,
    btrim(p_outcome_notes)
  );

  UPDATE public.sla_clocks
  SET started_at = v_received_at, updated_at = v_now
  WHERE organization_id = v_job.organization_id AND dispatch_job_id = p_job_id
    AND status IN ('running', 'met', 'breached');

  v_prior_stamp_mode := pg_catalog.current_setting('fcm.retrospective_register_completion', true);
  PERFORM pg_catalog.set_config('fcm.retrospective_register_completion', 'on', true);
  UPDATE public.dispatch_jobs
  SET status = 'completed',
      on_scene_at = v_arrived_at,
      completed_at = v_departed_at,
      outcome_notes = v_outcome
  WHERE id = p_job_id
  RETURNING * INTO v_job;
  PERFORM pg_catalog.set_config('fcm.retrospective_register_completion', coalesce(v_prior_stamp_mode, ''), true);

  IF v_job.shift_id IS NOT NULL
    AND v_job.insert_gps_lat IS NULL
    AND v_job.insert_gps_lng IS NULL THEN
    SELECT * INTO v_shift
    FROM public.shifts s
    WHERE s.id = v_job.shift_id
      AND s.organization_id = v_job.organization_id
      AND s.officer_user_id IS NOT NULL;
  END IF;

  IF v_shift.id IS NOT NULL THEN
    SELECT * INTO v_finance
    FROM public.resolve_dispatch_job_financials_internal(
      v_actor,
      p_client_request_id,
      p_job_id,
      NULL
    );
    v_finance_result := jsonb_build_object(
      'status', CASE WHEN v_finance.unresolved_count > 0 THEN 'review_required' ELSE 'resolved' END,
      'pay_lines_written', v_finance.lines_written,
      'pay_total', v_finance.total_pay,
      'unresolved_pay_lines', v_finance.unresolved_count,
      'charge_lines_written', v_finance.charge_lines_written,
      'charge_total', v_finance.total_charge,
      'travel_basis', 'not_calculated_without_dispatch_origin'
    );
  ELSE
    v_finance_result := jsonb_build_object(
      'status', 'review_required',
      'reason', CASE
        WHEN v_job.shift_id IS NULL THEN 'No linked shift/officer is available for pay attribution'
        WHEN v_job.insert_gps_lat IS NOT NULL OR v_job.insert_gps_lng IS NOT NULL THEN 'Dispatch-origin coordinates are present; travel-based finance was not calculated'
        ELSE 'The linked shift has no officer in this organization'
      END
    );
  END IF;

  v_resulting := jsonb_build_object(
    'status', v_job.status,
    'on_scene_at', v_job.on_scene_at,
    'completed_at', v_job.completed_at,
    'dispatched_at', v_job.dispatched_at,
    'gps_captured', false,
    'shift_stop_created', false,
    'finance', v_finance_result,
    'sla_clocks', (
      SELECT coalesce(jsonb_agg(jsonb_build_object(
        'id', c.id, 'started_at', c.started_at, 'arrived_at', c.arrived_at,
        'elapsed_minutes', c.elapsed_minutes, 'target_minutes', c.target_minutes, 'status', c.status
      ) ORDER BY c.id), '[]'::jsonb)
      FROM public.sla_clocks c
      WHERE c.organization_id = v_job.organization_id AND c.dispatch_job_id = p_job_id
    )
  );

  INSERT INTO public.audit_log (
    organization_id, actor_user_id, action, target_table, target_id, metadata
  ) VALUES (
    v_job.organization_id,
    v_actor,
    'dispatch_job_retroactive_register_completion',
    'dispatch_jobs',
    v_job.id,
    jsonb_build_object(
      'client_request_id', p_client_request_id,
      'reason', btrim(p_reason),
      'recording_method', 'retrospective_source_register',
      'source', jsonb_build_object(
        'file_name', btrim(p_source_name),
        'sha256', lower(p_source_sha256),
        'reference', p_source_reference,
        'time_zone', p_source_time_zone,
        'received_local', p_source_received_local,
        'arrived_local', p_source_arrived_local,
        'departed_local', p_source_departed_local,
        'outcome_notes', btrim(p_outcome_notes)
      ),
      'gps_captured', false,
      'shift_stop_created', false,
      'previous', v_previous,
      'resulting', v_resulting,
      'finance', v_finance_result
    )
  );

  RETURN jsonb_build_object(
    'replayed', false,
    'target_id', v_job.id,
    'previous', v_previous,
    'resulting', v_resulting,
    'finance', v_finance_result
  );
END;
$function$;
COMMENT ON FUNCTION "public"."record_retrospective_noise_job_outcome"(p_client_request_id uuid, p_job_id uuid, p_expected_status text, p_source_name text, p_source_sha256 text, p_source_reference text, p_source_time_zone text, p_source_received_local text, p_source_arrived_local text, p_source_departed_local text, p_outcome_notes text, p_reason text) IS 'Admin-only, replay-safe completion of an unstarted noise-control job from an exact-match historical register record. Stores source-reported on/off-site times, creates no GPS fix or shift stop, preserves the normal location-event projection, and defers finance unless a linked shift/officer exists and no dispatch-origin coordinates could create unverified travel.';
REVOKE ALL ON FUNCTION "public"."record_retrospective_noise_job_outcome"(p_client_request_id uuid, p_job_id uuid, p_expected_status text, p_source_name text, p_source_sha256 text, p_source_reference text, p_source_time_zone text, p_source_received_local text, p_source_arrived_local text, p_source_departed_local text, p_outcome_notes text, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_retrospective_noise_job_outcome"(p_client_request_id uuid, p_job_id uuid, p_expected_status text, p_source_name text, p_source_sha256 text, p_source_reference text, p_source_time_zone text, p_source_received_local text, p_source_arrived_local text, p_source_departed_local text, p_outcome_notes text, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_retrospective_noise_job_outcome"(p_client_request_id uuid, p_job_id uuid, p_expected_status text, p_source_name text, p_source_sha256 text, p_source_reference text, p_source_time_zone text, p_source_received_local text, p_source_arrived_local text, p_source_departed_local text, p_outcome_notes text, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."record_retrospective_noise_job_outcome"(p_client_request_id uuid, p_job_id uuid, p_expected_status text, p_source_name text, p_source_sha256 text, p_source_reference text, p_source_time_zone text, p_source_received_local text, p_source_arrived_local text, p_source_departed_local text, p_outcome_notes text, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_smoke_photo_perception_envelope"(p_assessment_id uuid, p_classification jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_assessment public.smoke_assessments%ROWTYPE;
  v_link public.smoke_assessment_evidence%ROWTYPE;
  v_evidence public.evidence_items%ROWTYPE;
  v_source_hash text;
  v_source text;
  v_severity text;
  v_visibility text;
  v_reasoning text;
  v_confidence real;
  v_authority text;
  v_idempotency_key text;
  v_envelope_id uuid;
  v_recorded integer := 0;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  IF jsonb_typeof(p_classification) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'Structured smoke classification is required';
  END IF;

  SELECT * INTO v_assessment
  FROM public.smoke_assessments
  WHERE id = p_assessment_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Smoke assessment is missing'; END IF;

  SELECT link.* INTO v_link
  FROM public.smoke_assessment_evidence link
  WHERE link.smoke_assessment_id = v_assessment.id
    AND link.organization_id = v_assessment.organization_id
  ORDER BY
    CASE WHEN link.purpose = 'primary_evidence' THEN 0 ELSE 1 END,
    link.ordinal,
    link.id
  LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('recorded', 0, 'replayed', 0, 'skipped', 'missing_evidence_link');
  END IF;

  SELECT * INTO v_evidence
  FROM public.evidence_items
  WHERE id = v_link.evidence_item_id
    AND organization_id = v_assessment.organization_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('recorded', 0, 'replayed', 0, 'skipped', 'missing_evidence_item');
  END IF;

  v_source_hash := lower(coalesce(
    nullif(v_evidence.sha256_hash, ''),
    nullif(v_evidence.metadata->>'watermarked_sha256', '')
  ));
  IF (v_source_hash ~ '^[0-9a-f]{64}$') IS DISTINCT FROM TRUE THEN
    RETURN jsonb_build_object('recorded', 0, 'replayed', 0, 'skipped', 'missing_source_hash');
  END IF;

  IF coalesce(p_classification->>'status', 'unavailable') <> 'available' THEN
    UPDATE public.smoke_assessments
    SET smoke_ai_analysis = p_classification,
        review_state = 'requires_supervisor_review',
        updated_at = clock_timestamp()
    WHERE id = v_assessment.id;
    RETURN jsonb_build_object('recorded', 0, 'replayed', 0, 'skipped', 'classification_unavailable');
  END IF;

  v_source := nullif(trim(coalesce(
    p_classification#>>'{details,smoke_source}',
    p_classification->>'classification'
  )), '');
  v_severity := nullif(trim(p_classification#>>'{details,severity}'), '');
  v_visibility := nullif(trim(p_classification#>>'{details,visibility_impact}'), '');
  v_reasoning := nullif(trim(p_classification->>'reasoning'), '');
  v_confidence := CASE
    WHEN p_classification->>'confidence' ~ '^[0-9]+([.][0-9]+)?$'
      THEN (p_classification->>'confidence')::real
  END;
  IF v_confidence IS NULL OR v_confidence < 0 OR v_confidence > 1 THEN
    RAISE EXCEPTION 'Smoke classification confidence is invalid';
  END IF;
  IF v_source IS NULL AND v_severity IS NULL AND v_visibility IS NULL THEN
    UPDATE public.smoke_assessments
    SET smoke_ai_analysis = p_classification,
        review_state = 'requires_supervisor_review',
        updated_at = clock_timestamp()
    WHERE id = v_assessment.id;
    RETURN jsonb_build_object('recorded', 0, 'replayed', 0, 'skipped', 'no_structured_candidates');
  END IF;

  UPDATE public.evidence_items
  SET sha256_hash = coalesce(sha256_hash, v_source_hash)
  WHERE id = v_evidence.id;

  UPDATE public.smoke_assessments
  SET smoke_ai_analysis = p_classification,
      smoke_ai_analyzed_at = clock_timestamp(),
      bob_classification = coalesce(v_source, p_classification->>'classification'),
      bob_confidence = v_confidence,
      bob_recommendation = v_reasoning,
      review_state = 'requires_supervisor_review',
      updated_at = clock_timestamp()
  WHERE id = v_assessment.id
  RETURNING * INTO v_assessment;

  v_authority := CASE WHEN v_confidence < 0.5 THEN 'insufficient' ELSE 'candidate' END;
  v_idempotency_key := 'smoke-photo:' || v_assessment.id::text || ':v1:' || v_source_hash;

  SELECT id INTO v_envelope_id
  FROM public.perception_evidence_envelopes
  WHERE organization_id = v_assessment.organization_id
    AND idempotency_key = v_idempotency_key;
  IF FOUND THEN
    PERFORM private.apply_smoke_photo_review_to_perception(v_assessment.id);
    RETURN jsonb_build_object('recorded', 0, 'replayed', 1, 'envelope_id', v_envelope_id);
  END IF;

  INSERT INTO public.perception_evidence_envelopes (
    organization_id, schema_version, domain, source_kind, source_sha256,
    evidence_item_id, source_receipt, model_receipt, derivative_receipts,
    status, idempotency_key
  ) VALUES (
    v_assessment.organization_id, 1, 'smoke_photo', 'image', v_source_hash,
    v_evidence.id,
    jsonb_strip_nulls(jsonb_build_object(
      'smoke_assessment_id', v_assessment.id,
      'evidence_item_id', v_evidence.id,
      'assessed_at', v_assessment.assessed_at,
      'source_location_id', v_assessment.location_id,
      'source_site_id', v_assessment.site_id,
      'complainant_site_id', v_assessment.complainant_site_id,
      'storage_bucket', 'scans',
      'storage_path', v_evidence.storage_path,
      'authoritative_source_preserved', true
    )),
    jsonb_strip_nulls(jsonb_build_object(
      'classifier', coalesce(p_classification->>'classifier', 'bob_vision'),
      'provider', p_classification->'provider',
      'model', p_classification->'model',
      'prompt_version', coalesce(p_classification->>'prompt_version', 'smoke_photo_v1'),
      'machine_legal_decision_permitted', false
    )),
    jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
      'evidence_item_id', v_evidence.id,
      'original_path', v_evidence.metadata->>'original_path',
      'watermarked_path', v_evidence.metadata->>'watermarked_path',
      'original_sha256', v_evidence.metadata->>'raw_sha256',
      'watermarked_sha256', v_source_hash,
      'watermark_service', v_evidence.metadata->>'watermark_service'
    ))),
    'manual_review_required',
    v_idempotency_key
  )
  RETURNING id INTO v_envelope_id;

  IF v_source IS NOT NULL THEN
    INSERT INTO public.perception_evidence_fields (
      organization_id, envelope_id, field_key, candidate_ordinal, value_type,
      candidate_value, normalized_value, candidate_payload, raw_confidence,
      source_locations, consensus_rule, authority_state, review_required
    ) VALUES (
      v_assessment.organization_id, v_envelope_id, 'smoke.source_candidate', 0, 'classification',
      to_jsonb(v_source), lower(v_source),
      jsonb_build_object('source', 'visible_image_classifier', 'legal_decision_permitted', false),
      v_confidence,
      jsonb_build_array(jsonb_build_object('evidence_item_id', v_evidence.id, 'storage_path', v_evidence.storage_path)),
      'advisory_visible_smoke_candidate_human_review_required_v1',
      v_authority,
      true
    );
    v_recorded := v_recorded + 1;
  END IF;

  IF v_severity IS NOT NULL THEN
    INSERT INTO public.perception_evidence_fields (
      organization_id, envelope_id, field_key, candidate_ordinal, value_type,
      candidate_value, normalized_value, candidate_payload, raw_confidence,
      source_locations, consensus_rule, authority_state, review_required
    ) VALUES (
      v_assessment.organization_id, v_envelope_id, 'smoke.severity_candidate', 0, 'classification',
      to_jsonb(v_severity), lower(v_severity),
      jsonb_build_object('source', 'visible_image_classifier', 'statutory_threshold_permitted', false),
      v_confidence,
      jsonb_build_array(jsonb_build_object('evidence_item_id', v_evidence.id)),
      'advisory_visible_smoke_candidate_human_review_required_v1',
      v_authority,
      true
    );
    v_recorded := v_recorded + 1;
  END IF;

  IF v_visibility IS NOT NULL THEN
    INSERT INTO public.perception_evidence_fields (
      organization_id, envelope_id, field_key, candidate_ordinal, value_type,
      candidate_value, normalized_value, candidate_payload, raw_confidence,
      source_locations, consensus_rule, authority_state, review_required
    ) VALUES (
      v_assessment.organization_id, v_envelope_id, 'smoke.visibility_impact_candidate', 0, 'text',
      to_jsonb(v_visibility), lower(v_visibility),
      jsonb_build_object('source', 'visible_image_classifier', 'visual_observation_only', true),
      v_confidence,
      jsonb_build_array(jsonb_build_object('evidence_item_id', v_evidence.id)),
      'advisory_visible_smoke_candidate_human_review_required_v1',
      v_authority,
      true
    );
    v_recorded := v_recorded + 1;
  END IF;

  PERFORM private.apply_smoke_photo_review_to_perception(v_assessment.id);
  RETURN jsonb_build_object(
    'recorded', 1,
    'replayed', 0,
    'envelope_id', v_envelope_id,
    'field_candidates', v_recorded
  );
END;
$function$;
COMMENT ON FUNCTION "public"."record_smoke_photo_perception_envelope"(p_assessment_id uuid, p_classification jsonb) IS 'Service-only replay-safe compiler for advisory smoke photo candidates. Missing custody fails closed and machine output never creates statutory or enforcement authority.';
REVOKE ALL ON FUNCTION "public"."record_smoke_photo_perception_envelope"(p_assessment_id uuid, p_classification jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_smoke_photo_perception_envelope"(p_assessment_id uuid, p_classification jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_smoke_photo_perception_envelope"(p_assessment_id uuid, p_classification jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_staff_credential"(p_client_request_id uuid, p_staff_id uuid, p_credential_type text, p_credential_number text DEFAULT NULL::text, p_issuing_authority text DEFAULT NULL::text, p_issued_date date DEFAULT NULL::date, p_expiry_date date DEFAULT NULL::date, p_authorized_activities text[] DEFAULT '{}'::text[], p_verified boolean DEFAULT false, p_evidence_notes text DEFAULT NULL::text)
 RETURNS TABLE(credential_id uuid, staff_id uuid, verified boolean, verified_at timestamp with time zone, created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_staff public.staff_profiles%rowtype;
  v_row public.staff_credentials%rowtype;
  v_number text := nullif(trim(coalesce(p_credential_number, '')), '');
  v_authority text := nullif(trim(coalesce(p_issuing_authority, '')), '');
  v_notes text := nullif(trim(coalesce(p_evidence_notes, '')), '');
begin
  if v_actor is null then raise exception 'Authentication required'; end if;
  if p_client_request_id is null then raise exception 'Client request ID is required'; end if;
  select s.* into v_staff from public.staff_profiles s where s.id = p_staff_id;
  if not found then raise exception 'Staff profile not found'; end if;
  if not public.is_admin_for_org(v_staff.organization_id) then raise exception 'Active provider administrator required'; end if;
  if p_credential_type not in ('certificate_of_authority', 'warrant_of_authority', 'drivers_licence', 'first_aid', 'security_licence', 'firearms_licence', 'noise_control_warrant', 'biosecurity_warrant', 'other') then raise exception 'Unsupported credential type'; end if;
  if p_issued_date is not null and p_expiry_date is not null and p_issued_date > p_expiry_date then raise exception 'Credential expiry cannot precede its issue date'; end if;
  if p_verified and (v_number is null or v_authority is null or v_notes is null or length(v_notes) < 10) then raise exception 'Verifying a credential needs its number, the issuing authority, and evidence notes of at least 10 characters'; end if;

  perform pg_advisory_xact_lock(hashtextextended(p_client_request_id::text, 0));
  select c.* into v_row from public.staff_credentials c where c.organization_id = v_staff.organization_id and c.client_request_id = p_client_request_id;
  if found then
    if v_row.staff_id <> v_staff.id then raise exception 'Credential request identity collision'; end if;
    return query select v_row.id, v_row.staff_id, v_row.verified, v_row.verified_at, false;
    return;
  end if;

  insert into public.staff_credentials(staff_id, organization_id, credential_type, credential_number, issuing_authority, issued_date, expiry_date, authorized_activities, verified, verified_by, verified_at, notes, client_request_id)
  values (v_staff.id, v_staff.organization_id, p_credential_type, v_number, v_authority, p_issued_date, p_expiry_date, coalesce(p_authorized_activities, '{}'::text[]), p_verified, case when p_verified then v_actor end, case when p_verified then clock_timestamp() end, v_notes, p_client_request_id)
  returning * into v_row;

  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (v_staff.organization_id, v_actor, 'staff_credential_recorded', 'staff_credentials', v_row.id, jsonb_build_object(
    'staff_id', v_staff.id,
    'credential_type', p_credential_type,
    'credential_number', v_number,
    'issuing_authority', v_authority,
    'issued_date', p_issued_date,
    'expiry_date', p_expiry_date,
    'verified', p_verified,
    'client_request_id', p_client_request_id
  ));
  return query select v_row.id, v_row.staff_id, v_row.verified, v_row.verified_at, true;
end;
$function$;
COMMENT ON FUNCTION "public"."record_staff_credential"(p_client_request_id uuid, p_staff_id uuid, p_credential_type text, p_credential_number text, p_issuing_authority text, p_issued_date date, p_expiry_date date, p_authorized_activities text[], p_verified boolean, p_evidence_notes text) IS 'Records a staff member''s credential (first or additional) as an administrator of their organisation. Verification requires number, authority and evidence notes. Replay-safe on p_client_request_id; audited as staff_credential_recorded. Renewals of an expiring credential use renew_staff_credential.';
REVOKE ALL ON FUNCTION "public"."record_staff_credential"(p_client_request_id uuid, p_staff_id uuid, p_credential_type text, p_credential_number text, p_issuing_authority text, p_issued_date date, p_expiry_date date, p_authorized_activities text[], p_verified boolean, p_evidence_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_staff_credential"(p_client_request_id uuid, p_staff_id uuid, p_credential_type text, p_credential_number text, p_issuing_authority text, p_issued_date date, p_expiry_date date, p_authorized_activities text[], p_verified boolean, p_evidence_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_staff_credential"(p_client_request_id uuid, p_staff_id uuid, p_credential_type text, p_credential_number text, p_issuing_authority text, p_issued_date date, p_expiry_date date, p_authorized_activities text[], p_verified boolean, p_evidence_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."record_staff_credential"(p_client_request_id uuid, p_staff_id uuid, p_credential_type text, p_credential_number text, p_issuing_authority text, p_issued_date date, p_expiry_date date, p_authorized_activities text[], p_verified boolean, p_evidence_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_staff_document_upload"(p_client_request_id uuid, p_staff_id uuid, p_document_type text, p_file_name text, p_storage_path text, p_description text DEFAULT NULL::text, p_expiry_date date DEFAULT NULL::date)
 RETURNS staff_documents
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_staff public.staff_profiles%rowtype;
  v_document public.staff_documents%rowtype;
  v_size bigint;
  v_mime text;
  v_prefix text;
  v_file_name text := nullif(btrim(coalesce(p_file_name, '')), '');
  v_description text := nullif(btrim(coalesce(p_description, '')), '');
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  IF p_client_request_id IS NULL THEN
    RAISE EXCEPTION 'Client request ID is required';
  END IF;

  SELECT staff.*
  INTO v_staff
  FROM public.staff_profiles staff
  WHERE staff.id = p_staff_id
  FOR UPDATE;

  IF NOT FOUND OR NOT public.is_admin_for_org(v_staff.organization_id) THEN
    RAISE EXCEPTION 'Active organisation HR administrator required';
  END IF;
  IF p_document_type IS NULL
     OR p_document_type NOT IN ('credential_evidence', 'contract', 'certificate', 'policy_acknowledgement', 'other') THEN
    RAISE EXCEPTION 'Unsupported staff document type';
  END IF;
  IF v_file_name IS NULL
     OR length(v_file_name) > 255
     OR v_file_name ~ '[/\\]'
     OR p_storage_path IS NULL THEN
    RAISE EXCEPTION 'A valid file name and private storage path are required';
  END IF;
  IF v_description IS NOT NULL AND length(v_description) > 500 THEN
    RAISE EXCEPTION 'Document description must be 500 characters or fewer';
  END IF;
  v_prefix := v_staff.organization_id::text || '/staff/' || v_staff.id::text || '/' || p_client_request_id::text || '/';
  IF left(p_storage_path, length(v_prefix)) <> v_prefix
     OR right(p_storage_path, length(v_file_name)) <> v_file_name THEN
    RAISE EXCEPTION 'Document path does not match the organisation, staff member, and upload request';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(p_client_request_id::text, 0));

  SELECT document.*
  INTO v_document
  FROM public.staff_documents document
  WHERE document.organization_id = v_staff.organization_id
    AND document.client_request_id = p_client_request_id;
  IF FOUND THEN
    IF v_document.staff_id <> v_staff.id
       OR v_document.storage_path <> p_storage_path
       OR v_document.document_type <> p_document_type THEN
      RAISE EXCEPTION 'Document request ID has already been used for another upload';
    END IF;
    RETURN v_document;
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.staff_documents document
    WHERE document.client_request_id = p_client_request_id
  ) THEN
    RAISE EXCEPTION 'Document request ID has already been used by another organisation';
  END IF;

  SELECT
    nullif(uploaded_object.metadata ->> 'size', '')::bigint,
    nullif(uploaded_object.metadata ->> 'mimetype', '')
  INTO v_size, v_mime
  FROM storage.objects uploaded_object
  WHERE uploaded_object.bucket_id = 'staff-documents'
    AND uploaded_object.name = p_storage_path;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Uploaded document was not found in private storage';
  END IF;
  IF v_size IS NULL OR v_size < 1 OR v_size > 10485760 THEN
    RAISE EXCEPTION 'Staff document must be between 1 byte and 10 MB';
  END IF;
  IF v_mime IS NULL OR v_mime NOT IN (
    'application/pdf',
    'image/jpeg',
    'image/png',
    'image/webp',
    'text/plain',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
  ) THEN
    RAISE EXCEPTION 'Unsupported staff document media type';
  END IF;

  INSERT INTO public.staff_documents (
    staff_id,
    organization_id,
    document_type,
    file_name,
    storage_path,
    file_size_bytes,
    mime_type,
    description,
    uploaded_by,
    expiry_date,
    client_request_id
  ) VALUES (
    v_staff.id,
    v_staff.organization_id,
    p_document_type,
    v_file_name,
    p_storage_path,
    v_size,
    v_mime,
    v_description,
    v_actor,
    p_expiry_date,
    p_client_request_id
  )
  RETURNING * INTO v_document;

  INSERT INTO public.audit_log (
    organization_id, actor_user_id, action, target_table, target_id, metadata
  ) VALUES (
    v_staff.organization_id,
    v_actor,
    'staff_document_uploaded',
    'staff_documents',
    v_document.id,
    jsonb_build_object(
      'staff_id', v_staff.id,
      'document_type', v_document.document_type,
      'file_name', v_document.file_name,
      'file_size_bytes', v_document.file_size_bytes,
      'mime_type', v_document.mime_type,
      'client_request_id', p_client_request_id
    )
  );

  RETURN v_document;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."record_staff_document_upload"(p_client_request_id uuid, p_staff_id uuid, p_document_type text, p_file_name text, p_storage_path text, p_description text, p_expiry_date date) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_staff_document_upload"(p_client_request_id uuid, p_staff_id uuid, p_document_type text, p_file_name text, p_storage_path text, p_description text, p_expiry_date date) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_staff_document_upload"(p_client_request_id uuid, p_staff_id uuid, p_document_type text, p_file_name text, p_storage_path text, p_description text, p_expiry_date date) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."record_staff_document_upload"(p_client_request_id uuid, p_staff_id uuid, p_document_type text, p_file_name text, p_storage_path text, p_description text, p_expiry_date date) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_staff_training"(p_client_request_id uuid, p_staff_id uuid, p_training_name text, p_training_type text, p_provider text, p_completed_date date, p_expiry_date date DEFAULT NULL::date, p_passed boolean DEFAULT NULL::boolean, p_score numeric DEFAULT NULL::numeric, p_notes text DEFAULT NULL::text, p_supersedes_training_record_id uuid DEFAULT NULL::uuid)
 RETURNS staff_training_records
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_staff public.staff_profiles%rowtype;
  v_previous public.staff_training_records%rowtype;
  v_record public.staff_training_records%rowtype;
  v_training_name text := nullif(trim(coalesce(p_training_name, '')), '');
  v_training_type text := lower(nullif(trim(coalesce(p_training_type, '')), ''));
BEGIN
  IF p_client_request_id IS NULL THEN
    RAISE EXCEPTION 'client_request_id is required';
  END IF;

  SELECT *
  INTO v_staff
  FROM public.staff_profiles staff
  WHERE staff.id = p_staff_id
  FOR UPDATE;

  IF NOT FOUND OR NOT public.is_admin_for_org(v_staff.organization_id) THEN
    RAISE EXCEPTION 'Organisation training administrator required';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(p_client_request_id::text, 0));

  SELECT *
  INTO v_record
  FROM public.staff_training_records record
  WHERE record.client_request_id = p_client_request_id
    AND record.organization_id = v_staff.organization_id
    AND record.staff_id = v_staff.id;
  IF FOUND THEN
    RETURN v_record;
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.staff_training_records record
    WHERE record.client_request_id = p_client_request_id
  ) THEN
    RAISE EXCEPTION 'client_request_id has already been used for another training record';
  END IF;

  IF v_training_name IS NULL THEN
    RAISE EXCEPTION 'Training name is required';
  END IF;
  IF v_training_type NOT IN ('induction', 'internal', 'external', 'refresher', 'assessment') THEN
    RAISE EXCEPTION 'Unsupported training type';
  END IF;
  IF p_completed_date IS NULL THEN
    RAISE EXCEPTION 'Completion date is required';
  END IF;
  IF p_expiry_date IS NOT NULL AND p_expiry_date < p_completed_date THEN
    RAISE EXCEPTION 'Training expiry cannot precede completion';
  END IF;
  IF p_score IS NOT NULL AND (p_score < 0 OR p_score > 100) THEN
    RAISE EXCEPTION 'Training score must be between 0 and 100';
  END IF;

  IF p_supersedes_training_record_id IS NOT NULL THEN
    SELECT *
    INTO v_previous
    FROM public.staff_training_records record
    WHERE record.id = p_supersedes_training_record_id
      AND record.organization_id = v_staff.organization_id
      AND record.staff_id = v_staff.id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Previous training record not found for this staff member';
    END IF;
  END IF;

  INSERT INTO public.staff_training_records (
    organization_id,
    staff_id,
    officer_id,
    training_name,
    training_type,
    provider,
    completed_date,
    expiry_date,
    passed,
    score,
    notes,
    recorded_by,
    client_request_id,
    supersedes_training_record_id
  ) VALUES (
    v_staff.organization_id,
    v_staff.id,
    v_staff.user_id,
    v_training_name,
    v_training_type,
    nullif(trim(coalesce(p_provider, '')), ''),
    p_completed_date,
    p_expiry_date,
    p_passed,
    p_score,
    nullif(trim(coalesce(p_notes, '')), ''),
    v_actor,
    p_client_request_id,
    p_supersedes_training_record_id
  )
  RETURNING * INTO v_record;

  INSERT INTO public.audit_log (
    organization_id, actor_user_id, action, target_table, target_id, metadata
  ) VALUES (
    v_staff.organization_id,
    v_actor,
    CASE WHEN p_supersedes_training_record_id IS NULL
      THEN 'staff_training_recorded'
      ELSE 'staff_training_renewed'
    END,
    'staff_training_records',
    v_record.id,
    jsonb_build_object(
      'staff_id', v_staff.id,
      'training_name', v_record.training_name,
      'training_type', v_record.training_type,
      'completed_date', v_record.completed_date,
      'expiry_date', v_record.expiry_date,
      'supersedes_training_record_id', p_supersedes_training_record_id,
      'client_request_id', p_client_request_id
    )
  );

  RETURN v_record;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."record_staff_training"(p_client_request_id uuid, p_staff_id uuid, p_training_name text, p_training_type text, p_provider text, p_completed_date date, p_expiry_date date, p_passed boolean, p_score numeric, p_notes text, p_supersedes_training_record_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_staff_training"(p_client_request_id uuid, p_staff_id uuid, p_training_name text, p_training_type text, p_provider text, p_completed_date date, p_expiry_date date, p_passed boolean, p_score numeric, p_notes text, p_supersedes_training_record_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_staff_training"(p_client_request_id uuid, p_staff_id uuid, p_training_name text, p_training_type text, p_provider text, p_completed_date date, p_expiry_date date, p_passed boolean, p_score numeric, p_notes text, p_supersedes_training_record_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."record_staff_training"(p_client_request_id uuid, p_staff_id uuid, p_training_name text, p_training_type text, p_provider text, p_completed_date date, p_expiry_date date, p_passed boolean, p_score numeric, p_notes text, p_supersedes_training_record_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_static_shift_presence"(p_shift_id uuid, p_action text, p_request_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_shift public.shifts%rowtype; v_stop public.shift_stops%rowtype; v_module public.shift_stop_modules%rowtype;
  v_position jsonb; v_at timestamptz := clock_timestamp(); v_action_id uuid := gen_random_uuid(); v_receipt jsonb;
begin
  select * into v_shift from public.shifts where id = p_shift_id for update;
  if not found or auth.uid() is null or v_shift.officer_user_id is distinct from auth.uid() or v_shift.status <> 'in_progress' then
    raise exception 'Assigned in-progress shift required' using errcode = '42501';
  end if;
  if p_action not in ('arrive','depart') or p_action is null or p_request_id is null then raise exception 'Attendance action and request required'; end if;
  v_position := public.evaluate_static_shift_position(v_shift.id, p_gps_lat, p_gps_lng);
  if v_position->>'status' <> 'on_site' and nullif(btrim(p_reason),'') is null then
    raise exception 'Explain the unverified attendance for operations review';
  end if;
  select * into v_stop from public.shift_stops where shift_id = v_shift.id and module_key = 'static_guarding' for update;
  if exists(select 1 from public.shift_stop_actions where shift_stop_id = v_stop.id
    and action_type = case when p_action = 'arrive' then 'static_post_arrived' else 'static_post_departed' end) then return; end if;
  select * into v_module from public.shift_stop_modules where shift_stop_id = v_stop.id and module_key = 'static_guarding' and is_required for update;
  if not found then raise exception 'Static guarding module task is missing'; end if;
  if not exists(select 1 from public.service_agreement_modules sam join public.service_agreement_locations sal on sal.service_agreement_id = sam.service_agreement_id
    where sam.id = v_module.service_agreement_module_id and sal.id = v_module.service_agreement_location_id
      and sam.module_key = 'static_guarding' and sam.enabled and sal.status = 'active') then raise exception 'Static guarding contract is no longer active'; end if;
  if p_action = 'arrive' then
    if v_stop.status not in ('pending','en_route','on_scene') then raise exception 'Static post cannot be started from this state'; end if;
    update public.shift_stops set status = 'on_scene', actual_arrived_at = coalesce(actual_arrived_at,v_at),
      arrived_gps_lat = p_gps_lat, arrived_gps_lng = p_gps_lng,
      arrival_verification = case when (v_position->>'verified_attendance')::boolean then 'verified_on_site'
        when v_position->>'status' = 'unverified_site' then 'unverified_boundary' else v_position->>'status' end,
      updated_at = v_at where id = v_stop.id returning * into v_stop;
    update public.shift_stop_modules set status = 'in_progress', started_at = coalesce(started_at,v_at), updated_at = v_at where id = v_module.id;
  else
    if v_stop.status <> 'on_scene' then raise exception 'Start this static post before ending the shift'; end if;
    update public.shift_stop_modules set status = 'completed', completed_at = v_at, updated_at = v_at where id = v_module.id;
    update public.shift_stops set status = 'completed', actual_departed_at = v_at,
      departed_gps_lat = p_gps_lat, departed_gps_lng = p_gps_lng, sla_status = 'completed', updated_at = v_at
      where id = v_stop.id returning * into v_stop;
    update public.shifts set completed_stops = 1 where id = v_shift.id;
  end if;
  v_receipt := jsonb_build_object('reference','SG-'||upper(left(replace(v_action_id::text,'-',''),8)),
    'action',p_action,'occurred_at',v_at,'shift_id',v_shift.id,'stop_id',v_stop.id,
    'gps_result',v_position->>'status','timing_status','recorded',
    'dwell_minutes',greatest(0,floor(extract(epoch from (v_at-v_stop.actual_arrived_at))/60)),
    'handover_recorded',p_action = 'depart');
  insert into public.shift_stop_actions(id,organization_id,shift_stop_id,shift_id,shift_stop_module_id,action_type,
    gps_lat,gps_lng,performed_at,client_request_id,evidence_metadata,receipt)
  values(v_action_id,v_shift.organization_id,v_stop.id,v_shift.id,v_module.id,
    case when p_action = 'arrive' then 'static_post_arrived' else 'static_post_departed' end,
    p_gps_lat,p_gps_lng,v_at,p_request_id,jsonb_build_object('capture_method','shift_attendance',
      'position_status',v_position->>'status','verified_attendance',(v_position->>'verified_attendance')::boolean,
      'review_required',v_position->>'status' <> 'on_site','exception_reason',nullif(btrim(p_reason),'')),v_receipt);
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
  values(v_shift.organization_id,auth.uid(),'static_shift_attendance','shift_stops',v_stop.id,
    jsonb_build_object('shift_id',v_shift.id,'action',p_action,'position_status',v_position->>'status',
      'review_required',v_position->>'status' <> 'on_site','exception_reason',nullif(btrim(p_reason),'')));
end;
$function$;
REVOKE ALL ON FUNCTION "public"."record_static_shift_presence"(p_shift_id uuid, p_action text, p_request_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_static_shift_presence"(p_shift_id uuid, p_action text, p_request_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_reason text) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."record_update_target_org"(p_record_kind text, p_record_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_org uuid;
  v_client uuid;
  v_site uuid;
  v_zone uuid;
BEGIN
  IF v_uid IS NULL THEN RETURN NULL; END IF;
  IF p_record_kind = 'observation' THEN
    SELECT organization_id, client_org_id INTO v_org, v_client FROM public.observations WHERE id = p_record_id;
    IF v_org IS NULL THEN RETURN NULL; END IF;
    IF public.org_access_allowed(v_org) OR public.org_access_allowed(v_client)
      OR public.user_has_task_entitlement(v_uid, p_record_id) THEN RETURN v_org; END IF;
  ELSIF p_record_kind = 'location_event' THEN
    SELECT organization_id, client_site_id, zone_id INTO v_org, v_site, v_zone FROM public.location_events WHERE id = p_record_id;
    IF v_org IS NULL THEN RETURN NULL; END IF;
    IF public.org_access_allowed(v_org) OR public.has_location_access(v_site, v_zone, 'client_reads_provider') THEN RETURN v_org; END IF;
  END IF;
  RETURN NULL;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."record_update_target_org"(p_record_kind text, p_record_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_update_target_org"(p_record_kind text, p_record_id uuid) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."record_vehicle_owner"(p_organization_id uuid, p_canonical_vehicle_id uuid, p_person_record_id uuid, p_person_fields jsonb, p_source text, p_basis text)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT public.record_vehicle_person(p_organization_id, p_canonical_vehicle_id, p_person_record_id,
    p_person_fields, 'owner', p_source, p_basis, NULL);
$function$;
COMMENT ON FUNCTION "public"."record_vehicle_owner"(p_organization_id uuid, p_canonical_vehicle_id uuid, p_person_record_id uuid, p_person_fields jsonb, p_source text, p_basis text) IS 'Owner shortcut for record_vehicle_person (relationship owner).';
REVOKE ALL ON FUNCTION "public"."record_vehicle_owner"(p_organization_id uuid, p_canonical_vehicle_id uuid, p_person_record_id uuid, p_person_fields jsonb, p_source text, p_basis text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_vehicle_owner"(p_organization_id uuid, p_canonical_vehicle_id uuid, p_person_record_id uuid, p_person_fields jsonb, p_source text, p_basis text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_vehicle_owner"(p_organization_id uuid, p_canonical_vehicle_id uuid, p_person_record_id uuid, p_person_fields jsonb, p_source text, p_basis text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."record_vehicle_person"(p_organization_id uuid, p_canonical_vehicle_id uuid, p_person_record_id uuid, p_person_fields jsonb, p_relationship text, p_source text, p_basis text, p_observation_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_person_record_id uuid := p_person_record_id;
  v_canonical_person_id uuid;
  v_name text := nullif(trim(p_person_fields->>'display_name'), '');
  v_details jsonb;
  v_relationship text;
  v_link_id uuid;
  v_ended integer := 0;
  v_observations jsonb := CASE WHEN p_observation_id IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(p_observation_id) END;
BEGIN
  IF v_actor IS NULL OR NOT public.can_access_vehicle_owner_identity(p_organization_id, true) THEN
    RAISE EXCEPTION 'Vehicle owner identity access required';
  END IF;
  IF p_relationship NOT IN ('owner', 'driver', 'associated_person') THEN
    RAISE EXCEPTION 'Choose how this person relates to the vehicle';
  END IF;
  IF p_source NOT IN ('nzta_mvr', 'owner_declared', 'officer_observed', 'other') THEN
    RAISE EXCEPTION 'Choose where the details came from';
  END IF;
  IF p_source = 'nzta_mvr' AND p_relationship <> 'owner' THEN
    RAISE EXCEPTION 'The NZTA register only establishes the registered owner';
  END IF;
  IF coalesce(trim(p_basis), '') = '' THEN RAISE EXCEPTION 'A reason is required for the identity audit trail'; END IF;
  v_relationship := CASE WHEN p_relationship = 'owner' AND p_source = 'nzta_mvr' THEN 'registered_owner' ELSE p_relationship END;
  PERFORM 1 FROM public.canonical_vehicles WHERE id = p_canonical_vehicle_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Canonical vehicle not found'; END IF;
  IF p_observation_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.observations o
    WHERE o.id = p_observation_id AND public.org_access_allowed(o.organization_id)
  ) THEN RAISE EXCEPTION 'Observation not found in your authorised scope'; END IF;

  IF v_person_record_id IS NULL THEN
    IF p_person_fields IS NULL OR jsonb_typeof(p_person_fields) <> 'object' THEN
      RAISE EXCEPTION 'Choose an existing person or enter their details';
    END IF;
    IF v_name IS NULL THEN RAISE EXCEPTION 'Person name is required'; END IF;
    PERFORM public.assert_new_person_not_duplicate(p_organization_id, p_person_fields);
    v_details := jsonb_strip_nulls(jsonb_build_object(
      'phone', nullif(trim(p_person_fields->>'phone'), ''),
      'email', nullif(trim(p_person_fields->>'email'), ''),
      'address', nullif(trim(p_person_fields->>'address'), ''),
      'suburb', nullif(trim(p_person_fields->>'suburb'), ''),
      'city', nullif(trim(p_person_fields->>'city'), ''),
      'notes', nullif(trim(p_person_fields->>'notes'), ''),
      'nzta_mvr_sourced', p_source = 'nzta_mvr'
    ));
    INSERT INTO public.person_records (organization_id, display_name, review_state, metadata)
    VALUES (p_organization_id, v_name, 'manual_review_required',
      jsonb_build_object('profile_details', v_details, 'created_from', 'vehicle_' || p_relationship, 'created_by', v_actor))
    RETURNING id INTO v_person_record_id;
    v_canonical_person_id := public.ensure_canonical_person_for_record(v_person_record_id);
    INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
    VALUES (p_organization_id, v_actor, 'identity_person_create', 'person_records', v_person_record_id,
      jsonb_build_object('canonical_person_id', v_canonical_person_id,
        'reason', 'Vehicle ' || replace(p_relationship, '_', ' ') || ': ' || trim(p_basis),
        'fields', array(SELECT jsonb_object_keys(v_details))));
  ELSE
    PERFORM 1 FROM public.person_records WHERE id = v_person_record_id AND organization_id = p_organization_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Person record not found in this organization'; END IF;
    v_canonical_person_id := public.ensure_canonical_person_for_record(v_person_record_id);
  END IF;
  IF v_canonical_person_id IS NULL THEN RAISE EXCEPTION 'The person could not be linked to a canonical person'; END IF;

  -- A vehicle has one current owner per organisation; drivers and associated people accumulate.
  IF v_relationship IN ('owner', 'registered_owner') THEN
    UPDATE public.entity_links SET active = false, ends_at = clock_timestamp(), updated_at = clock_timestamp()
    WHERE organization_id = p_organization_id AND to_type = 'vehicle' AND to_id = p_canonical_vehicle_id
      AND relationship = v_relationship AND active
      AND NOT (from_type = 'person' AND from_id = v_canonical_person_id);
    GET DIAGNOSTICS v_ended = ROW_COUNT;
  END IF;

  INSERT INTO public.entity_links AS link (organization_id, from_type, from_id, to_type, to_id, relationship, evidence, active, starts_at, created_by)
  VALUES (p_organization_id, 'person', v_canonical_person_id, 'vehicle', p_canonical_vehicle_id, v_relationship,
    jsonb_build_object('source', p_source, 'basis', trim(p_basis), 'person_record_id', v_person_record_id,
      'nzta_restricted', p_source = 'nzta_mvr', 'observation_ids', v_observations),
    true, clock_timestamp(), v_actor)
  ON CONFLICT (organization_id, from_type, from_id, to_type, to_id, relationship) WHERE active
  DO UPDATE SET evidence = excluded.evidence || jsonb_build_object('observation_ids', (
      SELECT coalesce(jsonb_agg(DISTINCT item), '[]'::jsonb)
      FROM jsonb_array_elements(coalesce(link.evidence->'observation_ids', '[]'::jsonb) || v_observations) item
    )),
    updated_at = clock_timestamp()
  RETURNING id INTO v_link_id;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (p_organization_id, v_actor,
    CASE WHEN v_relationship IN ('owner', 'registered_owner') THEN 'vehicle_owner_recorded' ELSE 'vehicle_person_recorded' END,
    'entity_links', v_link_id,
    jsonb_strip_nulls(jsonb_build_object('canonical_vehicle_id', p_canonical_vehicle_id, 'person_record_id', v_person_record_id,
      'canonical_person_id', v_canonical_person_id, 'relationship', v_relationship, 'source', p_source,
      'basis', trim(p_basis), 'observation_id', p_observation_id, 'previous_owner_links_ended', v_ended)));
  RETURN jsonb_build_object('link_id', v_link_id, 'person_record_id', v_person_record_id,
    'canonical_person_id', v_canonical_person_id, 'relationship', v_relationship);
END;
$function$;
COMMENT ON FUNCTION "public"."record_vehicle_person"(p_organization_id uuid, p_canonical_vehicle_id uuid, p_person_record_id uuid, p_person_fields jsonb, p_relationship text, p_source text, p_basis text, p_observation_id uuid) IS 'Authorised-user write path (vehicle_owner_identity at adjust/manage, or organisation administrator) linking a person to a canonical vehicle as owner (registered_owner when NZTA-sourced), driver or associated person, optionally at a specific sighting. Creates the tenant person record and canonical person when needed. Owners replace the previous owner; drivers and associated people accumulate. Audited.';
REVOKE ALL ON FUNCTION "public"."record_vehicle_person"(p_organization_id uuid, p_canonical_vehicle_id uuid, p_person_record_id uuid, p_person_fields jsonb, p_relationship text, p_source text, p_basis text, p_observation_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_vehicle_person"(p_organization_id uuid, p_canonical_vehicle_id uuid, p_person_record_id uuid, p_person_fields jsonb, p_relationship text, p_source text, p_basis text, p_observation_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_vehicle_person"(p_organization_id uuid, p_canonical_vehicle_id uuid, p_person_record_id uuid, p_person_fields jsonb, p_relationship text, p_source text, p_basis text, p_observation_id uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."record_website_page_view"(p_page_path text, p_country_code text, p_region_code text, p_notice_version text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_settings private.website_analytics_settings%ROWTYPE;
  v_provider uuid;
  v_page_path text := btrim(coalesce(p_page_path, ''));
  v_country text := upper(coalesce(nullif(btrim(p_country_code), ''), 'ZZ'));
  v_region text := upper(coalesce(nullif(btrim(p_region_code), ''), 'ZZ'));
BEGIN
  IF char_length(v_page_path) > 160
     OR v_page_path !~ '^/(about|contact|gallery|privacy|services(/[a-z0-9-]+)?|blog(/[a-z0-9-]+)?)?$' THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'website_analytics_invalid:page_path';
  END IF;
  IF v_country <> 'ZZ' AND v_country !~ '^[A-Z]{2}$' THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'website_analytics_invalid:country';
  END IF;
  IF v_region <> 'ZZ' AND v_region !~ '^[A-Z0-9-]{1,15}$' THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'website_analytics_invalid:region';
  END IF;
  IF v_country = 'ZZ' THEN
    v_region := 'ZZ';
  END IF;
  IF p_notice_version IS NULL OR p_notice_version !~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,79}$' THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'website_analytics_invalid:notice_version';
  END IF;

  SELECT s.*
    INTO v_settings
    FROM private.website_analytics_settings AS s
   WHERE s.singleton;

  IF NOT FOUND
     OR NOT v_settings.enabled
     OR v_settings.approved_notice_version IS DISTINCT FROM p_notice_version THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'website_analytics_not_enabled';
  END IF;

  SELECT t.service_provider_organization_id
    INTO v_provider
    FROM private.platform_tenancy AS t
   WHERE t.singleton;

  IF v_provider IS NULL THEN
    RAISE EXCEPTION 'Single-provider tenancy is not configured';
  END IF;

  INSERT INTO public.website_page_views_daily (
    provider_organization_id,
    viewed_on,
    page_path,
    country_code,
    region_code,
    page_views
  )
  VALUES (
    v_provider,
    (pg_catalog.timezone('UTC', pg_catalog.now()))::date,
    v_page_path,
    v_country,
    v_region,
    1
  )
  ON CONFLICT (provider_organization_id, viewed_on, page_path, country_code, region_code)
  DO UPDATE SET page_views = public.website_page_views_daily.page_views + 1;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."record_website_page_view"(p_page_path text, p_country_code text, p_region_code text, p_notice_version text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_website_page_view"(p_page_path text, p_country_code text, p_region_code text, p_notice_version text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_website_page_view"(p_page_path text, p_country_code text, p_region_code text, p_notice_version text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."recover_scheduled_timesheet"(p_client_request_id uuid, p_staff_id uuid, p_period_start date, p_period_end date, p_rows jsonb, p_overtime_hours numeric, p_reason text)
 RETURNS timesheets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_staff public.staff_profiles%rowtype;
  v_sheet public.timesheets%rowtype;
  v_row jsonb; v_source record; v_sources jsonb := '[]'::jsonb; v_request jsonb;
  v_start timestamptz; v_end timestamptz; v_break numeric;
  v_hours numeric := 0; v_scheduled numeric := 0; v_shift uuid; v_count integer := 0;
BEGIN
  SELECT * INTO v_staff FROM public.staff_profiles WHERE id = p_staff_id;
  IF NOT FOUND OR NOT public.is_timesheet_payroll_admin(v_staff.organization_id) THEN
    RAISE EXCEPTION 'Active employer payroll administrator required' USING ERRCODE = '42501';
  END IF;
  IF p_client_request_id IS NULL OR nullif(btrim(p_reason), '') IS NULL OR length(p_reason) > 2000 THEN
    RAISE EXCEPTION 'A request ID and audited recovery reason (up to 2000 characters) are required';
  END IF;
  IF p_period_start IS NULL OR p_period_end IS NULL OR p_period_end < p_period_start
    OR p_period_end - p_period_start > 31 OR p_period_end > (now() AT TIME ZONE 'Pacific/Auckland')::date THEN
    RAISE EXCEPTION 'Choose a past or current period between 1 and 32 days';
  END IF;
  IF jsonb_typeof(p_rows) IS DISTINCT FROM 'array' OR jsonb_array_length(p_rows) NOT BETWEEN 1 AND 100 THEN
    RAISE EXCEPTION 'Select between 1 and 100 scheduled rows';
  END IF;
  v_request := jsonb_build_object('staff_id',p_staff_id,'period_start',p_period_start,
    'period_end',p_period_end,'rows',p_rows,'overtime_hours',p_overtime_hours,'reason',btrim(p_reason));
  -- The officer submission path takes this same lock before its overlap check.
  PERFORM pg_advisory_xact_lock(hashtextextended('timesheet_submission:' || v_staff.id::text, 0));
  SELECT * INTO v_sheet FROM public.timesheets
    WHERE staff_id = v_staff.id AND client_event_id = p_client_request_id;
  IF FOUND THEN
    IF v_sheet.recovery_request IS DISTINCT FROM v_request THEN
      RAISE EXCEPTION 'Request ID already used with different recovery details';
    END IF;
    RETURN v_sheet;
  END IF;
  IF EXISTS (SELECT 1 FROM public.timesheets t WHERE t.staff_id = v_staff.id
    AND daterange(t.period_start,t.period_end,'[]') && daterange(p_period_start,p_period_end,'[]')) THEN
    RAISE EXCEPTION 'A timesheet already overlaps this period; correct the existing sheet instead';
  END IF;
  IF (SELECT count(*) FROM jsonb_array_elements(p_rows)) <>
     (SELECT count(DISTINCT (x->>'source_type',x->>'source_id')) FROM jsonb_array_elements(p_rows) x) THEN
    RAISE EXCEPTION 'Duplicate scheduled rows are not allowed';
  END IF;
  -- Lock source rows in a deterministic order, including their linked attendance rows.
  PERFORM 1 FROM public.roster_slots r JOIN jsonb_array_elements(p_rows) x
    ON x->>'source_type' = 'roster_slot' AND r.id = (x->>'source_id')::uuid ORDER BY r.id FOR UPDATE OF r;
  PERFORM 1 FROM public.shifts s WHERE s.id IN (
    SELECT (x->>'source_id')::uuid FROM jsonb_array_elements(p_rows) x WHERE x->>'source_type' = 'shift'
    UNION SELECT r.linked_shift_id FROM public.roster_slots r JOIN jsonb_array_elements(p_rows) x
      ON x->>'source_type' = 'roster_slot' AND r.id = (x->>'source_id')::uuid
  ) ORDER BY s.id FOR UPDATE;
  FOR v_row IN SELECT value FROM jsonb_array_elements(p_rows) LOOP
    SELECT * INTO v_source FROM public.preview_scheduled_timesheet(p_staff_id,p_period_start,p_period_end) s
      WHERE s.source_type = v_row->>'source_type' AND s.source_id = (v_row->>'source_id')::uuid;
    IF NOT FOUND OR v_source.source_version IS DISTINCT FROM v_row->>'source_version' THEN
      RAISE EXCEPTION 'Scheduled source changed or is no longer eligible; reload the preview';
    END IF;
    IF v_source.shift_id IS NOT NULL AND EXISTS (
      SELECT 1 FROM public.shifts s WHERE s.id = v_source.shift_id
        AND (s.organization_id <> v_staff.organization_id OR s.officer_user_id NOT IN (v_staff.id,coalesce(v_staff.user_id,v_staff.id))
          OR s.status IN ('cancelled','declined','in_progress'))
    ) THEN RAISE EXCEPTION 'Linked shift changed or is still in progress'; END IF;
    IF v_source.shift_id IS NOT NULL AND EXISTS (SELECT 1 FROM jsonb_array_elements(v_sources) x
      WHERE x->>'shift_id'=v_source.shift_id::text) THEN RAISE EXCEPTION 'Duplicate linked shift sources are not allowed'; END IF;
    v_start := (v_row->>'reviewed_start')::timestamptz;
    v_end := (v_row->>'reviewed_end')::timestamptz;
    v_break := (v_row->>'unpaid_break_minutes')::numeric;
    IF v_start IS NULL OR v_end IS NULL OR v_break IS NULL OR v_break = 'NaN'::numeric
      OR v_break < 0 OR v_end <= v_start OR v_end > now() OR v_end - v_start > interval '24 hours'
      OR v_break >= extract(epoch FROM v_end-v_start)/60
      OR (v_start AT TIME ZONE 'Pacific/Auckland')::date < p_period_start
      OR (v_end AT TIME ZONE 'Pacific/Auckland')::date > p_period_end THEN
      RAISE EXCEPTION 'Review valid start, end and unpaid break inside the selected period';
    END IF;
    IF EXISTS (SELECT 1 FROM jsonb_array_elements(v_sources) x
      WHERE tstzrange((x->>'reviewed_start')::timestamptz,(x->>'reviewed_end')::timestamptz,'[)')
        && tstzrange(v_start,v_end,'[)')) THEN RAISE EXCEPTION 'Reviewed scheduled rows overlap'; END IF;
    v_hours := v_hours + (extract(epoch FROM v_end-v_start)/3600 - v_break/60);
    v_scheduled := v_scheduled + extract(epoch FROM v_source.scheduled_end-v_source.scheduled_start)/3600;
    v_sources := v_sources || jsonb_build_array(to_jsonb(v_source) || jsonb_build_object(
      'evidence_kind','manual_admin','reviewed_start',v_start,'reviewed_end',v_end,
      'unpaid_break_minutes',v_break,'reviewed_by',auth.uid(),'reason',btrim(p_reason)));
    v_shift := v_source.shift_id; v_count := v_count + 1;
  END LOOP;
  v_hours := round(v_hours,2);
  IF v_hours <= 0 OR v_hours > 744 OR p_overtime_hours IS NULL OR p_overtime_hours = 'NaN'::numeric
    OR p_overtime_hours < 0 OR p_overtime_hours > v_hours THEN RAISE EXCEPTION 'Invalid hours or overtime'; END IF;
  INSERT INTO public.timesheets(organization_id,staff_id,shift_id,period_start,period_end,
    scheduled_hours,actual_hours,overtime_hours,status,notes,submitted_at,client_event_id,
    work_derived_hours,adjustment_hours,work_summary,recovery_request)
  VALUES(v_staff.organization_id,v_staff.id,CASE WHEN v_count=1 THEN v_shift END,p_period_start,p_period_end,
    round(v_scheduled,2),v_hours,p_overtime_hours,'submitted',btrim(p_reason),clock_timestamp(),p_client_request_id,
    0,v_hours,jsonb_build_object('evidence_kind','manual_admin','source_count',0,'manual_sources',v_sources),v_request)
  RETURNING * INTO v_sheet;
  INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
    VALUES(v_staff.organization_id,auth.uid(),'timesheet_schedule_recovered','timesheets',v_sheet.id,
      jsonb_build_object('client_request_id',p_client_request_id,'reason',btrim(p_reason),
        'sources',v_sources,'actual_hours',v_hours,'evidence_kind','manual_admin'));
  RETURN v_sheet;
END $function$;
REVOKE ALL ON FUNCTION "public"."recover_scheduled_timesheet"(p_client_request_id uuid, p_staff_id uuid, p_period_start date, p_period_end date, p_rows jsonb, p_overtime_hours numeric, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."recover_scheduled_timesheet"(p_client_request_id uuid, p_staff_id uuid, p_period_start date, p_period_end date, p_rows jsonb, p_overtime_hours numeric, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."recover_scheduled_timesheet"(p_client_request_id uuid, p_staff_id uuid, p_period_start date, p_period_end date, p_rows jsonb, p_overtime_hours numeric, p_reason text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."recover_stale_cctv_inference_jobs"()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE recovered integer;
BEGIN
  IF auth.role() <> 'service_role' AND session_user <> 'postgres' THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;
  UPDATE public.inference_jobs
     SET status = 'queued', stage = 'queued', lease_token = NULL,
         lease_expires_at = NULL, heartbeat_at = NULL,
         error_message = 'Recovered after orphaned worker claim'
   WHERE domain = 'video_motion'
     AND status = 'processing'
     AND (lease_token IS NULL OR lease_expires_at IS NULL OR lease_expires_at < clock_timestamp());
  GET DIAGNOSTICS recovered = ROW_COUNT;
  RETURN recovered;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."recover_stale_cctv_inference_jobs"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."recover_stale_cctv_inference_jobs"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."recover_stale_cctv_inference_jobs"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."refresh_canonical_ta_names"(p_names text[], p_source text DEFAULT 'nzta_featureserver'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_count integer;
  v_name text;
BEGIN
  -- Guard: never wipe the table with an empty input (Q6 ruling)
  IF p_names IS NULL OR array_length(p_names, 1) IS NULL OR array_length(p_names, 1) = 0 THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'REFRESH_REFUSED: input names array is empty. The NZTA source may be unavailable. The existing canonical_ta_names data has been preserved (Q6: never silently degrade).'
    );
  END IF;

  -- Upsert each name
  v_count := 0;
  FOREACH v_name IN ARRAY p_names LOOP
    INSERT INTO public.canonical_ta_names (ta_name, source, last_refreshed_at)
    VALUES (trim(v_name), p_source, now())
    ON CONFLICT (ta_name) DO UPDATE
      SET source = EXCLUDED.source,
          last_refreshed_at = EXCLUDED.last_refreshed_at;
    v_count := v_count + 1;
  END LOOP;

  -- Remove names that are no longer in the authoritative source
  -- (but only if we received a reasonable number of names -- at least 50
  -- to avoid accidental wipe from a partial fetch)
  IF v_count >= 50 THEN
    DELETE FROM public.canonical_ta_names
    WHERE ta_name NOT IN (SELECT unnest(p_names));
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'upserted', v_count,
    'source', p_source,
    'refreshed_at', now()
  );
END;
$function$;
COMMENT ON FUNCTION "public"."refresh_canonical_ta_names"(p_names text[], p_source text) IS 'Upsert canonical TA names from a live NZTA fetch. Called by the bob-refresh-canonical-ta-names edge function. Refuses empty input (Q6: never silently degrade). Phase 2 geofence redesign (epic #226).';
REVOKE ALL ON FUNCTION "public"."refresh_canonical_ta_names"(p_names text[], p_source text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."refresh_canonical_ta_names"(p_names text[], p_source text) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."refresh_canonical_ta_names"(p_names text[], p_source text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."refresh_canonical_ta_names"(p_names text[], p_source text) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."refresh_canonical_ta_names"(p_names text[], p_source text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."refresh_canonical_ta_names"(p_names text[], p_source text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."refresh_face_observation_candidates"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_candidates jsonb;
BEGIN
  IF jsonb_typeof(NEW.metadata->'embedding') <> 'array' THEN RETURN NEW; END IF;
  SELECT coalesce(jsonb_agg(candidate ORDER BY similarity DESC), '[]'::jsonb)
  INTO v_candidates
  FROM (
    SELECT DISTINCT ON (match.person_record_id)
      jsonb_build_object(
        'match_kind', match.match_kind,
        'person_record_id', match.person_record_id,
        'display_name', coalesce(match.display_name, 'Unnamed person'),
        'similarity', round(match.score::numeric, 4),
        'reference_thumbnail', match.thumbnail,
        'review_state', person.review_state
      ) AS candidate,
      match.score AS similarity,
      match.person_record_id
    FROM public.find_cctv_portfolio_matches(NEW.organization_id, 'person', NEW.metadata->'embedding', NULL, NULL, NULL, 10) match
    JOIN public.person_records person ON person.id = match.person_record_id AND person.organization_id = NEW.organization_id
    WHERE match.person_record_id IS NOT NULL
    ORDER BY match.person_record_id, match.score DESC
  ) ranked;
  NEW.metadata := jsonb_set(coalesce(NEW.metadata, '{}'::jsonb), '{candidates}', v_candidates, true);
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."refresh_face_observation_candidates"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."refresh_face_observation_candidates"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."refresh_face_observation_candidates"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."refresh_fs_nelson_clients_clean"()
 RETURNS TABLE(raw_rows integer, clean_rows integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_raw_rows integer;
  v_clean_rows integer;
begin
  select count(*)::integer into v_raw_rows from public._seed_fs_nelson_clients_raw;

  truncate public.fs_nelson_clients_clean;

  insert into public.fs_nelson_clients_clean (
    bureau_id, bureau_name, client_id, client_name, client_address, client_suburb,
    client_postcode, client_state, patrol_type, onsite_datetime, offsite_datetime,
    comments, is_incident_report, patrol_complete_status, visit_charge_ex_gst,
    despatch_zone, subcontractor, onsite_distance_from_site, time_onsite_variation_mins,
    despatch_datetime, internal_clientid, internal_despatchid
  )
  select distinct on (
    coalesce(nullif(btrim(raw.client_id), ''), nullif(btrim(raw.internal_clientid), ''),
      lower(btrim(coalesce(raw.client_name, ''))) || '|' || lower(btrim(coalesce(raw.client_address, ''))))
  )
    nullif(btrim(raw.bureau_id), ''), nullif(btrim(raw.bureau_name), ''),
    nullif(btrim(raw.client_id), ''), nullif(btrim(raw.client_name), ''),
    nullif(btrim(raw.client_address), ''), nullif(btrim(raw.client_suburb), ''),
    nullif(btrim(raw.client_postcode), ''), nullif(btrim(raw.client_state), ''),
    nullif(btrim(raw.patrol_type), ''), nullif(btrim(raw.onsite_datetime), ''),
    nullif(btrim(raw.offsite_datetime), ''), nullif(btrim(raw.comments), ''),
    nullif(btrim(raw.is_incident_report), ''), nullif(btrim(raw.patrol_complete_status), ''),
    nullif(btrim(raw.visit_charge_ex_gst), ''), nullif(btrim(raw.despatch_zone), ''),
    nullif(btrim(raw.subcontractor), ''), nullif(btrim(raw.onsite_distance_from_site), ''),
    nullif(btrim(raw.time_onsite_variation_mins), ''), nullif(btrim(raw.despatch_datetime), ''),
    nullif(btrim(raw.internal_clientid), ''), nullif(btrim(raw.internal_despatchid), '')
  from public._seed_fs_nelson_clients_raw raw
  where nullif(btrim(raw.client_name), '') is not null
     or nullif(btrim(raw.client_address), '') is not null
  order by coalesce(nullif(btrim(raw.client_id), ''), nullif(btrim(raw.internal_clientid), ''),
      lower(btrim(coalesce(raw.client_name, ''))) || '|' || lower(btrim(coalesce(raw.client_address, '')))),
    raw.client_name, raw.client_address;

  get diagnostics v_clean_rows = row_count;
  return query select v_raw_rows, v_clean_rows;
end;
$function$;
COMMENT ON FUNCTION "public"."refresh_fs_nelson_clients_clean"() IS 'Service-role staging reconciliation: normalizes and deduplicates Nelson client rows for canonical client/site comparison. It never creates organizations or sites.';
REVOKE ALL ON FUNCTION "public"."refresh_fs_nelson_clients_clean"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."refresh_fs_nelson_clients_clean"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."refresh_fs_nelson_clients_clean"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."refresh_group_charge_catalog"(p_root uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_member uuid; v_total integer := 0;
BEGIN
  FOR v_member IN SELECT member FROM public.charge_catalog_group_members(p_root) member WHERE member <> p_root LOOP
    v_total := v_total + public.sync_group_charge_catalog(p_root, v_member);
  END LOOP;
  RETURN v_total;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."refresh_group_charge_catalog"(p_root uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."refresh_group_charge_catalog"(p_root uuid) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."register_bob_video_attachment_for_review"(p_attachment_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  attachment public.bob_attachments%rowtype;
  evidence_id uuid;
  job_id uuid;
BEGIN
  IF auth.role() <> 'service_role' AND session_user <> 'postgres' THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;

  SELECT * INTO attachment
    FROM public.bob_attachments
   WHERE id = p_attachment_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Bob attachment not found';
  END IF;
  IF attachment.file_type NOT LIKE 'video/%' THEN
    RAISE EXCEPTION 'Bob attachment is not a video';
  END IF;

  SELECT id INTO evidence_id
    FROM public.evidence_items
   WHERE metadata->>'bob_attachment_id' = attachment.id::text
   LIMIT 1;
  IF evidence_id IS NULL THEN
    INSERT INTO public.evidence_items (
      organization_id,
      module_key,
      evidence_kind,
      storage_path,
      captured_by_user_id,
      metadata
    ) VALUES (
      attachment.organization_id,
      'cctv_review',
      'video',
      attachment.storage_path,
      attachment.uploaded_by,
      jsonb_build_object(
        'bob_attachment_id', attachment.id,
        'bob_conversation_id', attachment.conversation_id,
        'file_name', attachment.file_name,
        'file_type', attachment.file_type,
        'file_size_bytes', attachment.file_size_bytes,
        'storage_bucket', attachment.storage_bucket
      ) || jsonb_strip_nulls(jsonb_build_object(
        'desktop_review_batch', attachment.extraction_payload->'desktop_review_batch'
      ))
    ) RETURNING id INTO evidence_id;
  END IF;

  SELECT id INTO job_id
    FROM public.inference_jobs
   WHERE evidence_item_id = evidence_id
     AND domain = 'video_motion'
   LIMIT 1;
  IF job_id IS NULL THEN
    INSERT INTO public.inference_jobs (
      organization_id,
      evidence_item_id,
      domain,
      status,
      requested_by_user_id
    ) VALUES (
      attachment.organization_id,
      evidence_id,
      'video_motion',
      'queued',
      attachment.uploaded_by
    ) RETURNING id INTO job_id;
  END IF;

  UPDATE public.bob_attachments
     SET purpose = 'video_intake',
         processing_state = 'processing',
         extraction_summary = 'Queued for CCTV motion and risk review.',
         extraction_payload = coalesce(extraction_payload, '{}'::jsonb)
           || jsonb_build_object('evidence_item_id', evidence_id, 'inference_job_id', job_id),
         updated_at = now()
   WHERE id = attachment.id;

  RETURN job_id;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."register_bob_video_attachment_for_review"(p_attachment_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."register_bob_video_attachment_for_review"(p_attachment_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."register_bob_video_attachment_for_review"(p_attachment_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."register_cctv_import_photo"(p_import_id uuid, p_storage_path text, p_file_name text, p_file_size_bytes bigint, p_sha256 text DEFAULT NULL::text, p_captured_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_source_ref text DEFAULT NULL::text, p_content_type text DEFAULT 'image/jpeg'::text, p_capture_time_source text DEFAULT 'file_modified_time'::text, p_width integer DEFAULT NULL::integer, p_height integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_actor uuid := auth.uid(); v_import public.cctv_imports%rowtype; v_prefix text; v_media_prefix text; v_ref text; v_captured_at timestamptz := coalesce(p_captured_at, clock_timestamp()); v_evidence uuid; v_job uuid;
BEGIN
  SELECT * INTO v_import FROM public.cctv_imports WHERE id = p_import_id;
  IF v_import.id IS NULL THEN RAISE EXCEPTION 'CCTV import not found'; END IF;
  IF v_actor IS NULL OR NOT public.org_access_allowed(v_import.organization_id) THEN RAISE EXCEPTION 'CCTV import access denied'; END IF;
  v_prefix := 'org/' || v_import.organization_id::text || '/cctv/' || v_import.id::text || '/';
  v_media_prefix := 'org/' || v_import.organization_id::text || '/cctv-media/';
  IF p_storage_path IS NULL OR (position(v_prefix in p_storage_path) <> 1 AND position(v_media_prefix in p_storage_path) <> 1) THEN
    RAISE EXCEPTION 'Photo must be stored under the import or content media prefix';
  END IF;
  IF position(v_media_prefix in p_storage_path) = 1 AND (p_sha256 IS NULL OR lower(p_sha256) <> lower(split_part(substr(p_storage_path, length(v_media_prefix) + 1), '/', 1))) THEN
    RAISE EXCEPTION 'Content-addressed photo path must match its SHA-256';
  END IF;
  IF coalesce(p_content_type, '') NOT IN ('image/jpeg', 'image/png', 'image/webp', 'image/bmp', 'image/tiff') THEN RAISE EXCEPTION 'Unsupported CCTV photo type'; END IF;
  IF p_file_size_bytes IS NULL OR p_file_size_bytes <= 0 THEN RAISE EXCEPTION 'Photo file size is required'; END IF;
  IF p_capture_time_source NOT IN ('camera_filename', 'camera_index', 'file_metadata', 'file_modified_time', 'operator') THEN RAISE EXCEPTION 'Unknown photo capture-time source'; END IF;
  v_ref := coalesce(nullif(trim(p_source_ref), ''), nullif(trim(p_file_name), ''), p_storage_path);
  SELECT id INTO v_evidence FROM public.evidence_items WHERE cctv_import_id = v_import.id AND evidence_kind = 'photo' AND metadata->>'source_ref' = v_ref;
  IF v_evidence IS NULL THEN
    INSERT INTO public.evidence_items (organization_id, module_key, evidence_kind, storage_path, captured_by_user_id, captured_at, sha256_hash, cctv_import_id, metadata)
    VALUES (v_import.organization_id, 'cctv_review', 'photo', p_storage_path, v_actor, v_captured_at, nullif(lower(trim(p_sha256)), ''), v_import.id,
      jsonb_strip_nulls(jsonb_build_object('file_name', p_file_name, 'file_type', p_content_type, 'file_size_bytes', p_file_size_bytes,
        'storage_bucket', 'bob-uploads', 'source_ref', v_ref, 'recorded_start_at', v_captured_at, 'capture_time_source', p_capture_time_source,
        'width', p_width, 'height', p_height, 'cctv_import_id', v_import.id, 'camera_label', v_import.camera_label, 'camera_key', v_import.camera_key,
        'source_device_kind', v_import.source_device_kind, 'source_timezone', v_import.source_timezone, 'location_id', v_import.location_id,
        'site_id', v_import.site_id, 'zone_id', v_import.zone_id, 'canonical_place_id', v_import.canonical_place_id, 'review_required', true)))
    RETURNING id INTO v_evidence;
  END IF;
  INSERT INTO public.cctv_device_events (cctv_import_id, organization_id, source, source_ref, event_start_at, severity, thumbnail_path, metadata)
  VALUES (v_import.id, v_import.organization_id, 'device_snapshot', v_ref, v_captured_at, 'detection', p_storage_path,
    jsonb_strip_nulls(jsonb_build_object('kind', 'photo_evidence', 'evidence_item_id', v_evidence, 'file_name', p_file_name, 'file_type', p_content_type,
      'file_size_bytes', p_file_size_bytes, 'sha256', p_sha256, 'capture_time_source', p_capture_time_source, 'width', p_width, 'height', p_height, 'review_required', true)))
  ON CONFLICT (cctv_import_id, source, source_ref) DO UPDATE SET event_start_at = EXCLUDED.event_start_at, severity = EXCLUDED.severity, thumbnail_path = EXCLUDED.thumbnail_path, metadata = public.cctv_device_events.metadata || EXCLUDED.metadata;
  SELECT id INTO v_job FROM public.inference_jobs WHERE evidence_item_id = v_evidence AND domain = 'video_motion' LIMIT 1;
  IF v_job IS NULL THEN
    INSERT INTO public.inference_jobs (organization_id, evidence_item_id, domain, status, stage, progress_label, requested_by_user_id)
    VALUES (v_import.organization_id, v_evidence, 'video_motion', 'queued', 'queued', 'Photo queued for face and plate review', v_actor) RETURNING id INTO v_job;
  END IF;
  UPDATE public.cctv_imports SET status = CASE WHEN status IN ('draft', 'uploading') THEN 'registered' ELSE status END WHERE id = v_import.id;
  RETURN jsonb_build_object('evidence_item_id', v_evidence, 'inference_job_id', v_job, 'source_ref', v_ref);
END $function$;
COMMENT ON FUNCTION "public"."register_cctv_import_photo"(p_import_id uuid, p_storage_path text, p_file_name text, p_file_size_bytes bigint, p_sha256 text, p_captured_at timestamp with time zone, p_source_ref text, p_content_type text, p_capture_time_source text, p_width integer, p_height integer) IS 'Registers an immutable CCTV photo as evidence and a dated timeline event, then queues laptop-first face/ALPR review.';
REVOKE ALL ON FUNCTION "public"."register_cctv_import_photo"(p_import_id uuid, p_storage_path text, p_file_name text, p_file_size_bytes bigint, p_sha256 text, p_captured_at timestamp with time zone, p_source_ref text, p_content_type text, p_capture_time_source text, p_width integer, p_height integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."register_cctv_import_photo"(p_import_id uuid, p_storage_path text, p_file_name text, p_file_size_bytes bigint, p_sha256 text, p_captured_at timestamp with time zone, p_source_ref text, p_content_type text, p_capture_time_source text, p_width integer, p_height integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."register_cctv_import_photo"(p_import_id uuid, p_storage_path text, p_file_name text, p_file_size_bytes bigint, p_sha256 text, p_captured_at timestamp with time zone, p_source_ref text, p_content_type text, p_capture_time_source text, p_width integer, p_height integer) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."register_cctv_import_photo"(p_import_id uuid, p_storage_path text, p_file_name text, p_file_size_bytes bigint, p_sha256 text, p_captured_at timestamp with time zone, p_source_ref text, p_content_type text, p_capture_time_source text, p_width integer, p_height integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."register_cctv_import_video"(p_import_id uuid, p_storage_path text, p_file_name text, p_file_size_bytes bigint, p_sha256 text DEFAULT NULL::text, p_recorded_start_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_recorded_end_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_source_ref text DEFAULT NULL::text, p_content_type text DEFAULT 'video/mp4'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_actor uuid := auth.uid(); v_import public.cctv_imports%rowtype; v_prefix text; v_media_prefix text; v_ref text; v_evidence uuid; v_job uuid;
BEGIN
  SELECT * INTO v_import FROM public.cctv_imports WHERE id = p_import_id;
  IF v_import.id IS NULL THEN RAISE EXCEPTION 'CCTV import not found'; END IF;
  IF v_actor IS NULL OR NOT public.org_access_allowed(v_import.organization_id) THEN RAISE EXCEPTION 'CCTV import access denied'; END IF;
  v_prefix := 'org/' || v_import.organization_id::text || '/cctv/' || v_import.id::text || '/';
  v_media_prefix := 'org/' || v_import.organization_id::text || '/cctv-media/';
  IF p_storage_path IS NULL OR (position(v_prefix in p_storage_path) <> 1 AND position(v_media_prefix in p_storage_path) <> 1) THEN
    RAISE EXCEPTION 'Video must be stored under the import or content media prefix';
  END IF;
  IF position(v_media_prefix in p_storage_path) = 1 AND (p_sha256 IS NULL OR lower(p_sha256) <> lower(split_part(substr(p_storage_path, length(v_media_prefix) + 1), '/', 1))) THEN
    RAISE EXCEPTION 'Content-addressed video path must match its SHA-256';
  END IF;
  IF coalesce(p_content_type, '') NOT LIKE 'video/%' THEN RAISE EXCEPTION 'Only video files are registered for CCTV review'; END IF;
  v_ref := coalesce(nullif(trim(p_source_ref), ''), nullif(trim(p_file_name), ''), p_storage_path);
  SELECT id INTO v_evidence FROM public.evidence_items WHERE cctv_import_id = v_import.id AND metadata->>'source_ref' = v_ref;
  IF v_evidence IS NULL THEN
    INSERT INTO public.evidence_items (organization_id, module_key, evidence_kind, storage_path, captured_by_user_id, captured_at, sha256_hash, cctv_import_id, metadata)
    VALUES (v_import.organization_id, 'cctv_review', 'video', p_storage_path, v_actor, coalesce(p_recorded_start_at, clock_timestamp()), nullif(lower(trim(p_sha256)), ''), v_import.id,
      jsonb_strip_nulls(jsonb_build_object('file_name', p_file_name, 'file_type', coalesce(p_content_type, 'video/mp4'), 'file_size_bytes', p_file_size_bytes,
        'storage_bucket', 'bob-uploads', 'source_ref', v_ref, 'recorded_start_at', p_recorded_start_at, 'recorded_end_at', p_recorded_end_at,
        'cctv_import_id', v_import.id, 'camera_label', v_import.camera_label, 'camera_key', v_import.camera_key, 'source_device_kind', v_import.source_device_kind,
        'source_timezone', v_import.source_timezone, 'location_id', v_import.location_id, 'canonical_place_id', v_import.canonical_place_id)))
    RETURNING id INTO v_evidence;
  END IF;
  SELECT id INTO v_job FROM public.inference_jobs WHERE evidence_item_id = v_evidence AND domain = 'video_motion' LIMIT 1;
  IF v_job IS NULL THEN
    INSERT INTO public.inference_jobs (organization_id, evidence_item_id, domain, status, requested_by_user_id)
    VALUES (v_import.organization_id, v_evidence, 'video_motion', 'queued', v_actor) RETURNING id INTO v_job;
  END IF;
  UPDATE public.cctv_imports SET status = CASE WHEN status IN ('draft', 'uploading') THEN 'registered' ELSE status END WHERE id = v_import.id;
  RETURN jsonb_build_object('evidence_item_id', v_evidence, 'inference_job_id', v_job, 'source_ref', v_ref);
END $function$;
REVOKE ALL ON FUNCTION "public"."register_cctv_import_video"(p_import_id uuid, p_storage_path text, p_file_name text, p_file_size_bytes bigint, p_sha256 text, p_recorded_start_at timestamp with time zone, p_recorded_end_at timestamp with time zone, p_source_ref text, p_content_type text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."register_cctv_import_video"(p_import_id uuid, p_storage_path text, p_file_name text, p_file_size_bytes bigint, p_sha256 text, p_recorded_start_at timestamp with time zone, p_recorded_end_at timestamp with time zone, p_source_ref text, p_content_type text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."register_cctv_import_video"(p_import_id uuid, p_storage_path text, p_file_name text, p_file_size_bytes bigint, p_sha256 text, p_recorded_start_at timestamp with time zone, p_recorded_end_at timestamp with time zone, p_source_ref text, p_content_type text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."register_cctv_import_video"(p_import_id uuid, p_storage_path text, p_file_name text, p_file_size_bytes bigint, p_sha256 text, p_recorded_start_at timestamp with time zone, p_recorded_end_at timestamp with time zone, p_source_ref text, p_content_type text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."register_deterministic_identity_document_proposal"(p_actor_user_id uuid, p_organization_id uuid, p_person_record_id uuid, p_attachment_id uuid, p_document_kind text, p_sha256 text, p_proposed_fields jsonb, p_face_embedding jsonb DEFAULT NULL::jsonb, p_face_confidence real DEFAULT NULL::real, p_face_count integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_definition public.identity_document_type_definitions%rowtype;
  v_storage_kind text;
  v_result jsonb;
  v_document_id uuid;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' AND session_user NOT IN ('postgres','supabase_admin') THEN RAISE EXCEPTION 'Service identity required for identity extraction registration'; END IF;
  SELECT * INTO v_definition FROM public.identity_document_type_definitions WHERE document_kind=p_document_kind AND active;
  IF v_definition.document_kind IS NULL THEN RAISE EXCEPTION 'Unsupported identity document kind'; END IF;
  v_storage_kind := CASE WHEN p_document_kind IN ('driver_licence','firearms_licence','security_licence','passport','national_id','person_photo','other_identity') THEN p_document_kind ELSE 'other_identity' END;
  v_result := public.register_identity_document_proposal(p_actor_user_id,p_organization_id,p_person_record_id,p_attachment_id,
    v_storage_kind,p_sha256,p_proposed_fields,p_face_embedding,p_face_confidence,p_face_count);
  v_document_id := (v_result->>'identity_document_id')::uuid;
  IF v_document_id IS NOT NULL AND v_storage_kind <> p_document_kind THEN
    UPDATE public.person_identity_documents SET document_kind=p_document_kind WHERE id=v_document_id;
    UPDATE public.evidence_items SET metadata=jsonb_set(metadata,'{document_kind}',to_jsonb(p_document_kind),true)
      WHERE id=(v_result->>'evidence_item_id')::uuid;
    UPDATE public.bob_attachments SET extraction_payload=jsonb_set(extraction_payload,'{document_kind}',to_jsonb(p_document_kind),true)
      WHERE id=p_attachment_id;
    UPDATE public.audit_log SET metadata=jsonb_set(metadata,'{document_kind}',to_jsonb(p_document_kind),true)
      WHERE action='identity_document_proposed' AND target_id=v_document_id;
  END IF;
  RETURN v_result || jsonb_build_object(
    'document_kind',p_document_kind,'display_name',v_definition.display_name,
    'canonical_destination',v_definition.canonical_destination,
    'staff_credential_type',v_definition.staff_credential_type,
    'default_authorized_activities',v_definition.default_authorized_activities
  );
END;
$function$;
COMMENT ON FUNCTION "public"."register_deterministic_identity_document_proposal"(p_actor_user_id uuid, p_organization_id uuid, p_person_record_id uuid, p_attachment_id uuid, p_document_kind text, p_sha256 text, p_proposed_fields jsonb, p_face_embedding jsonb, p_face_confidence real, p_face_count integer) IS 'Service-only data-driven identity/warrant proposal registration using the active document definition registry.';
REVOKE ALL ON FUNCTION "public"."register_deterministic_identity_document_proposal"(p_actor_user_id uuid, p_organization_id uuid, p_person_record_id uuid, p_attachment_id uuid, p_document_kind text, p_sha256 text, p_proposed_fields jsonb, p_face_embedding jsonb, p_face_confidence real, p_face_count integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."register_deterministic_identity_document_proposal"(p_actor_user_id uuid, p_organization_id uuid, p_person_record_id uuid, p_attachment_id uuid, p_document_kind text, p_sha256 text, p_proposed_fields jsonb, p_face_embedding jsonb, p_face_confidence real, p_face_count integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."register_deterministic_identity_document_proposal"(p_actor_user_id uuid, p_organization_id uuid, p_person_record_id uuid, p_attachment_id uuid, p_document_kind text, p_sha256 text, p_proposed_fields jsonb, p_face_embedding jsonb, p_face_confidence real, p_face_count integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."register_edge_court_photo"(p_organization_id uuid, p_module_key text, p_storage_path text, p_captured_at timestamp with time zone, p_metadata jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_evidence_id uuid;
begin
  if auth.role() <> 'service_role' then
    raise exception 'Only trusted evidence-processing services may register edge photos';
  end if;

  insert into public.evidence_items (
    organization_id, module_key, evidence_kind, storage_path, captured_at,
    retention_days, metadata
  ) values (
    p_organization_id, p_module_key, 'photo', p_storage_path, p_captured_at,
    2555, p_metadata
  ) returning id into v_evidence_id;

  insert into public.audit_log (organization_id, action, target_table, target_id, metadata)
  values (p_organization_id, 'edge_court_photo_registered', 'evidence_items', v_evidence_id, p_metadata);

  return v_evidence_id;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."register_edge_court_photo"(p_organization_id uuid, p_module_key text, p_storage_path text, p_captured_at timestamp with time zone, p_metadata jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."register_edge_court_photo"(p_organization_id uuid, p_module_key text, p_storage_path text, p_captured_at timestamp with time zone, p_metadata jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."register_edge_court_photo"(p_organization_id uuid, p_module_key text, p_storage_path text, p_captured_at timestamp with time zone, p_metadata jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."register_evidence_media_item"(p_module_key text, p_evidence_kind text, p_storage_path text, p_sha256_hash text DEFAULT NULL::text, p_is_court_ready boolean DEFAULT false, p_retention_days integer DEFAULT NULL::integer, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS TABLE(id uuid, organization_id uuid, module_key text, evidence_kind text, storage_path text, sha256_hash text, is_court_ready boolean, retention_days integer, captured_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_org_id uuid;
  v_item public.evidence_items%rowtype;
  v_retention integer := p_retention_days;
  v_clean_path text := nullif(trim(coalesce(p_storage_path, '')), '');
begin
  if v_user_id is null then raise exception 'Authentication required'; end if;
  select p.organization_id into v_org_id from public.user_profiles p where p.id = v_user_id and p.deactivated_at is null;
  if v_org_id is null then raise exception 'Active profile required for evidence registration'; end if;

  if nullif(trim(coalesce(p_module_key, '')), '') is null then
    raise exception 'module_key is required';
  end if;

  if p_evidence_kind not in ('photo', 'video', 'audio', 'document', 'note') then
    raise exception 'Unsupported evidence kind %', p_evidence_kind;
  end if;

  if v_clean_path is null then
    raise exception 'storage_path is required';
  end if;

  -- Derive retention_days from retention_policies if not explicitly provided
  if v_retention is null then
    select r.retention_days into v_retention
    from public.retention_policies r
    where (r.organization_id = v_org_id or r.organization_id is null)
      and (r.module_key = p_module_key or r.module_key is null)
      and r.is_active = true
    order by r.organization_id nulls last, r.module_key nulls last
    limit 1;
    if v_retention is null then v_retention := 2555; end if; -- Default 7 years (2555 days)
  end if;

  insert into public.evidence_items (
    organization_id, module_key, evidence_kind, storage_path, captured_by_user_id,
    captured_at, sha256_hash, is_court_ready, retention_days, metadata
  ) values (
    v_org_id, p_module_key, p_evidence_kind, v_clean_path, v_user_id,
    clock_timestamp(), nullif(trim(coalesce(p_sha256_hash, '')), ''), coalesce(p_is_court_ready, false), v_retention, coalesce(p_metadata, '{}'::jsonb)
  ) returning * into v_item;

  insert into public.audit_log (
    organization_id, actor_user_id, action, target_table, target_id, metadata
  ) values (
    v_org_id, v_user_id, 'evidence_media_registered', 'evidence_items', v_item.id,
    jsonb_build_object(
      'module_key', v_item.module_key,
      'evidence_kind', v_item.evidence_kind,
      'storage_path', v_item.storage_path,
      'sha256_hash', v_item.sha256_hash,
      'is_court_ready', v_item.is_court_ready,
      'retention_days', v_item.retention_days
    )
  );

  return query select v_item.id, v_item.organization_id, v_item.module_key, v_item.evidence_kind, v_item.storage_path, v_item.sha256_hash, v_item.is_court_ready, v_item.retention_days, v_item.captured_at;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."register_evidence_media_item"(p_module_key text, p_evidence_kind text, p_storage_path text, p_sha256_hash text, p_is_court_ready boolean, p_retention_days integer, p_metadata jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."register_evidence_media_item"(p_module_key text, p_evidence_kind text, p_storage_path text, p_sha256_hash text, p_is_court_ready boolean, p_retention_days integer, p_metadata jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."register_evidence_media_item"(p_module_key text, p_evidence_kind text, p_storage_path text, p_sha256_hash text, p_is_court_ready boolean, p_retention_days integer, p_metadata jsonb) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."register_evidence_media_item"(p_module_key text, p_evidence_kind text, p_storage_path text, p_sha256_hash text, p_is_court_ready boolean, p_retention_days integer, p_metadata jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."register_identity_document_proposal"(p_actor_user_id uuid, p_organization_id uuid, p_person_record_id uuid, p_attachment_id uuid, p_document_kind text, p_sha256 text, p_proposed_fields jsonb, p_face_embedding jsonb DEFAULT NULL::jsonb, p_face_confidence real DEFAULT NULL::real, p_face_count integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := p_actor_user_id;
  v_attachment public.bob_attachments%rowtype;
  v_evidence_id uuid;
  v_document_id uuid;
  v_candidate_matches jsonb := '[]'::jsonb;
  v_face_vec vector(128);
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' AND session_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'Service identity required for identity extraction registration';
  END IF;
  IF v_actor IS NULL OR NOT public.identity_actor_can_admin(v_actor, p_organization_id) THEN RAISE EXCEPTION 'Identity registry administrator access required'; END IF;
  IF p_document_kind NOT IN ('driver_licence','firearms_licence','security_licence','passport','national_id','person_photo','other_identity') THEN RAISE EXCEPTION 'Unsupported identity document kind'; END IF;
  IF p_sha256 !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'Identity document SHA-256 is required'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.person_records WHERE id = p_person_record_id AND organization_id = p_organization_id) THEN RAISE EXCEPTION 'Person record not found in this organization'; END IF;
  SELECT * INTO v_attachment FROM public.bob_attachments
  WHERE id = p_attachment_id AND organization_id = p_organization_id AND uploaded_by = v_actor;
  IF v_attachment.id IS NULL THEN RAISE EXCEPTION 'Identity attachment not found for this administrator'; END IF;
  IF v_attachment.purpose <> 'identity_document' OR v_attachment.storage_bucket <> 'identity-evidence'
     OR v_attachment.storage_path NOT LIKE 'org/' || p_organization_id::text || '/identity/' || v_actor::text || '/%' THEN
    RAISE EXCEPTION 'Identity attachment is outside the governed private intake path';
  END IF;
  SELECT id INTO v_document_id FROM public.person_identity_documents WHERE attachment_id = p_attachment_id;
  IF v_document_id IS NOT NULL THEN RETURN jsonb_build_object('identity_document_id', v_document_id, 'duplicate', true); END IF;

  INSERT INTO public.evidence_items (organization_id, module_key, evidence_kind, storage_path, captured_by_user_id, captured_at, sha256_hash, metadata)
  VALUES (p_organization_id, 'identity_registry', 'document', v_attachment.storage_path, v_actor, v_attachment.created_at, p_sha256,
    jsonb_build_object('storage_bucket', v_attachment.storage_bucket, 'file_name', v_attachment.file_name,
      'file_type', v_attachment.file_type, 'file_size_bytes', v_attachment.file_size_bytes,
      'attachment_id', v_attachment.id, 'document_kind', p_document_kind,
      'authority', 'source_document', 'human_review_required', true))
  RETURNING id INTO v_evidence_id;

  IF p_face_count = 1 AND jsonb_typeof(p_face_embedding) = 'array' AND jsonb_array_length(p_face_embedding) = 128 THEN
    v_face_vec := public.cctv_jsonb_to_vector(p_face_embedding, 128);
  END IF;
  IF v_face_vec IS NOT NULL THEN
    SELECT coalesce(jsonb_agg(jsonb_build_object(
      'match_kind', match_kind, 'match_id', match_id, 'observation_id', observation_id,
      'display_name', display_name, 'score', score, 'basis', basis, 'last_seen_at', last_seen_at
    ) ORDER BY score DESC), '[]'::jsonb)
    INTO v_candidate_matches
    FROM public.find_cctv_portfolio_matches(p_organization_id, 'person', p_face_embedding, NULL, NULL, NULL, 10);
  END IF;

  INSERT INTO public.person_identity_documents (organization_id, person_record_id, evidence_item_id, attachment_id,
    document_kind, extracted_fields, id_photo_storage_path, review_state, created_by, face_confidence, face_count)
  VALUES (p_organization_id, p_person_record_id, v_evidence_id, p_attachment_id, p_document_kind,
    jsonb_build_object('proposed', coalesce(p_proposed_fields, '{}'::jsonb), 'face_count', greatest(coalesce(p_face_count, 0), 0),
      'candidate_matches', v_candidate_matches, 'ocr_authority', 'advisory', 'review_required', true),
    CASE WHEN v_attachment.file_type LIKE 'image/%' THEN v_attachment.storage_path ELSE NULL END,
    'manual_review_required', v_actor, CASE WHEN v_face_vec IS NOT NULL THEN p_face_confidence ELSE NULL END,
    greatest(coalesce(p_face_count, 0), 0))
  RETURNING id INTO v_document_id;
  IF v_face_vec IS NOT NULL THEN
    INSERT INTO public.person_identity_face_proposals (identity_document_id, organization_id, person_record_id, face_vec, confidence)
    VALUES (v_document_id, p_organization_id, p_person_record_id, v_face_vec, p_face_confidence);
  END IF;
  UPDATE public.bob_attachments SET processing_state = 'manual_review_required', extraction_payload = jsonb_build_object(
    'identity_document_id', v_document_id, 'document_kind', p_document_kind, 'proposed_fields', coalesce(p_proposed_fields, '{}'::jsonb),
    'face_count', greatest(coalesce(p_face_count, 0), 0)), confidence = p_face_confidence WHERE id = p_attachment_id;
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (p_organization_id, v_actor, 'identity_document_proposed', 'person_identity_documents', v_document_id,
    jsonb_build_object('person_record_id', p_person_record_id, 'document_kind', p_document_kind, 'attachment_id', p_attachment_id,
      'evidence_item_id', v_evidence_id, 'face_count', greatest(coalesce(p_face_count, 0), 0)));
  RETURN jsonb_build_object('identity_document_id', v_document_id, 'evidence_item_id', v_evidence_id,
    'face_candidate_pending', v_face_vec IS NOT NULL, 'candidate_matches', v_candidate_matches, 'duplicate', false);
END;
$function$;
COMMENT ON FUNCTION "public"."register_identity_document_proposal"(p_actor_user_id uuid, p_organization_id uuid, p_person_record_id uuid, p_attachment_id uuid, p_document_kind text, p_sha256 text, p_proposed_fields jsonb, p_face_embedding jsonb, p_face_confidence real, p_face_count integer) IS 'Service-only registration of private identity evidence and provisional OCR/face candidates for an already-authorized administrator. Never updates canonical identity before review.';
REVOKE ALL ON FUNCTION "public"."register_identity_document_proposal"(p_actor_user_id uuid, p_organization_id uuid, p_person_record_id uuid, p_attachment_id uuid, p_document_kind text, p_sha256 text, p_proposed_fields jsonb, p_face_embedding jsonb, p_face_confidence real, p_face_count integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."register_identity_document_proposal"(p_actor_user_id uuid, p_organization_id uuid, p_person_record_id uuid, p_attachment_id uuid, p_document_kind text, p_sha256 text, p_proposed_fields jsonb, p_face_embedding jsonb, p_face_confidence real, p_face_count integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."register_identity_document_proposal"(p_actor_user_id uuid, p_organization_id uuid, p_person_record_id uuid, p_attachment_id uuid, p_document_kind text, p_sha256 text, p_proposed_fields jsonb, p_face_embedding jsonb, p_face_confidence real, p_face_count integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."register_incident_identity_attachment"(p_incident_id uuid, p_person_record_id uuid, p_document_kind text, p_attachment_id uuid, p_file_name text, p_file_type text, p_file_size_bytes bigint, p_storage_path text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid:=auth.uid();v_incident public.incidents%rowtype;v_conversation uuid;v_definition public.identity_document_type_definitions%rowtype;
BEGIN
  SELECT * INTO v_incident FROM public.incidents WHERE id=p_incident_id;
  IF v_incident.id IS NULL OR v_actor IS NULL OR NOT public.can_record_incident_person(v_incident.id,v_actor) THEN RAISE EXCEPTION 'Assigned incident access required'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.incident_person_links WHERE incident_id=v_incident.id AND person_record_id=p_person_record_id) THEN RAISE EXCEPTION 'Record the person on the incident before adding identity evidence'; END IF;
  SELECT * INTO v_definition FROM public.identity_document_type_definitions WHERE document_kind=p_document_kind AND active;
  IF v_definition.document_kind IS NULL THEN RAISE EXCEPTION 'Unsupported identity document kind'; END IF;
  IF p_file_type NOT IN ('image/jpeg','image/png','image/webp','image/bmp','image/tiff','application/pdf') THEN RAISE EXCEPTION 'Unsupported identity evidence file type'; END IF;
  IF p_file_size_bytes<=0 OR p_file_size_bytes>26214400 THEN RAISE EXCEPTION 'Identity evidence must be 25 MB or smaller'; END IF;
  IF p_storage_path NOT LIKE 'org/'||v_incident.organization_id::text||'/identity/'||v_actor::text||'/incident-'||v_incident.id::text||'/%' THEN RAISE EXCEPTION 'Identity evidence path is outside the incident scope'; END IF;
  IF NOT EXISTS(SELECT 1 FROM storage.objects object WHERE object.bucket_id='identity-evidence' AND object.name=p_storage_path) THEN RAISE EXCEPTION 'Uploaded identity evidence object not found'; END IF;
  SELECT id INTO v_conversation FROM public.bob_conversations WHERE organization_id=v_incident.organization_id AND user_id=v_actor AND module_key='operations' ORDER BY updated_at DESC LIMIT 1;
  IF v_conversation IS NULL THEN
    INSERT INTO public.bob_conversations(organization_id,user_id,module_key,title)VALUES(v_incident.organization_id,v_actor,'operations','Incident identity evidence')RETURNING id INTO v_conversation;
  END IF;
  INSERT INTO public.bob_attachments(id,organization_id,conversation_id,uploaded_by,file_name,file_type,file_size_bytes,storage_bucket,storage_path,purpose,processing_state,extraction_payload)
  VALUES(p_attachment_id,v_incident.organization_id,v_conversation,v_actor,p_file_name,p_file_type,p_file_size_bytes,'identity-evidence',p_storage_path,'identity_document','processing',jsonb_build_object(
    'incident_id',v_incident.id,'person_record_id',p_person_record_id,'document_kind',p_document_kind,'capture_authority','assigned_incident'));
  INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
  VALUES(v_incident.organization_id,v_actor,'incident_identity_attachment_registered','bob_attachments',p_attachment_id,jsonb_build_object('incident_id',v_incident.id,'person_record_id',p_person_record_id,'document_kind',p_document_kind));
  RETURN jsonb_build_object('attachment_id',p_attachment_id,'organization_id',v_incident.organization_id,'person_record_id',p_person_record_id,'document_kind',p_document_kind);
END;
$function$;
COMMENT ON FUNCTION "public"."register_incident_identity_attachment"(p_incident_id uuid, p_person_record_id uuid, p_document_kind text, p_attachment_id uuid, p_file_name text, p_file_type text, p_file_size_bytes bigint, p_storage_path text) IS 'Assigned-officer/admin registration of an uploaded incident-scoped ID source before trusted OCR/face inference.';
REVOKE ALL ON FUNCTION "public"."register_incident_identity_attachment"(p_incident_id uuid, p_person_record_id uuid, p_document_kind text, p_attachment_id uuid, p_file_name text, p_file_type text, p_file_size_bytes bigint, p_storage_path text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."register_incident_identity_attachment"(p_incident_id uuid, p_person_record_id uuid, p_document_kind text, p_attachment_id uuid, p_file_name text, p_file_type text, p_file_size_bytes bigint, p_storage_path text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."register_incident_identity_attachment"(p_incident_id uuid, p_person_record_id uuid, p_document_kind text, p_attachment_id uuid, p_file_name text, p_file_type text, p_file_size_bytes bigint, p_storage_path text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."register_incident_identity_attachment"(p_incident_id uuid, p_person_record_id uuid, p_document_kind text, p_attachment_id uuid, p_file_name text, p_file_type text, p_file_size_bytes bigint, p_storage_path text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."register_officer_device_token"(p_push_token text, p_platform text DEFAULT 'expo'::text, p_device_name text DEFAULT NULL::text, p_app_version text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, push_token text, platform text, is_active boolean, last_seen_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
declare
  v_user_id uuid := auth.uid();
  v_org_id uuid;
  v_token public.officer_device_tokens%rowtype;
  v_clean_token text := trim(coalesce(p_push_token, ''));
  v_clean_platform text := lower(trim(coalesce(p_platform, 'expo')));
begin
  if v_user_id is null then raise exception 'Authentication required'; end if;
  select p.organization_id into v_org_id from public.user_profiles p where p.id = v_user_id and p.deactivated_at is null;
  if v_org_id is null then raise exception 'Active profile required for device registration'; end if;
  if v_clean_token = '' then raise exception 'push_token is required'; end if;
  if v_clean_platform not in ('expo', 'ios', 'android', 'web') then
    raise exception 'Unsupported device platform %', p_platform;
  end if;

  insert into public.officer_device_tokens (
    organization_id, user_id, push_token, platform, device_name, app_version, is_active, last_seen_at, updated_at
  ) values (
    v_org_id, v_user_id, v_clean_token, v_clean_platform, nullif(trim(coalesce(p_device_name, '')), ''), nullif(trim(coalesce(p_app_version, '')), ''), true, clock_timestamp(), clock_timestamp()
  )
  on conflict (organization_id, user_id, push_token) do update set
    platform = excluded.platform,
    device_name = coalesce(excluded.device_name, officer_device_tokens.device_name),
    app_version = coalesce(excluded.app_version, officer_device_tokens.app_version),
    is_active = true,
    last_seen_at = clock_timestamp(),
    updated_at = clock_timestamp()
  returning * into v_token;

  insert into public.audit_log (
    organization_id, actor_user_id, action, target_table, target_id, metadata
  ) values (
    v_org_id, v_user_id, 'officer_device_token_registered', 'officer_device_tokens', v_token.id,
    jsonb_build_object('platform', v_token.platform, 'device_name', v_token.device_name, 'app_version', v_token.app_version)
  );

  return query select v_token.id, v_token.push_token, v_token.platform, v_token.is_active, v_token.last_seen_at;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."register_officer_device_token"(p_push_token text, p_platform text, p_device_name text, p_app_version text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."register_officer_device_token"(p_push_token text, p_platform text, p_device_name text, p_app_version text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."register_officer_device_token"(p_push_token text, p_platform text, p_device_name text, p_app_version text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."register_officer_device_token"(p_push_token text, p_platform text, p_device_name text, p_app_version text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."register_organization_brand_asset"(p_organization_id uuid, p_asset_kind text, p_variant text, p_label text, p_storage_bucket text DEFAULT NULL::text, p_storage_path text DEFAULT NULL::text, p_asset_url text DEFAULT NULL::text, p_mime_type text DEFAULT NULL::text, p_sha256 text DEFAULT NULL::text, p_alt_text text DEFAULT NULL::text, p_usage_scope text DEFAULT 'documents'::text)
 RETURNS organization_brand_assets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_asset public.organization_brand_assets;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF NOT public.is_admin_for_org(p_organization_id) AND NOT public.is_grand_master() THEN RAISE EXCEPTION 'Brand asset registration denied'; END IF;
  IF nullif(trim(coalesce(p_label, '')), '') IS NULL THEN RAISE EXCEPTION 'Brand asset label is required'; END IF;
  IF p_storage_path IS NULL AND p_asset_url IS NULL THEN RAISE EXCEPTION 'Brand asset source is required'; END IF;

  INSERT INTO public.organization_brand_assets (
    organization_id, asset_kind, variant, label, storage_bucket, storage_path, asset_url,
    mime_type, sha256, alt_text, usage_scope, status, created_by
  ) VALUES (
    p_organization_id, p_asset_kind, p_variant, trim(p_label), p_storage_bucket, p_storage_path,
    p_asset_url, p_mime_type, p_sha256, nullif(trim(coalesce(p_alt_text, '')), ''), p_usage_scope,
    'pending', v_actor
  ) RETURNING * INTO v_asset;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (p_organization_id, v_actor, 'organization_brand_asset_registered', 'organization_brand_assets', v_asset.id,
    jsonb_build_object('asset_kind', p_asset_kind, 'variant', p_variant, 'usage_scope', p_usage_scope));
  RETURN v_asset;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."register_organization_brand_asset"(p_organization_id uuid, p_asset_kind text, p_variant text, p_label text, p_storage_bucket text, p_storage_path text, p_asset_url text, p_mime_type text, p_sha256 text, p_alt_text text, p_usage_scope text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."register_organization_brand_asset"(p_organization_id uuid, p_asset_kind text, p_variant text, p_label text, p_storage_bucket text, p_storage_path text, p_asset_url text, p_mime_type text, p_sha256 text, p_alt_text text, p_usage_scope text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."register_organization_brand_asset"(p_organization_id uuid, p_asset_kind text, p_variant text, p_label text, p_storage_bucket text, p_storage_path text, p_asset_url text, p_mime_type text, p_sha256 text, p_alt_text text, p_usage_scope text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."register_organization_brand_asset"(p_organization_id uuid, p_asset_kind text, p_variant text, p_label text, p_storage_bucket text, p_storage_path text, p_asset_url text, p_mime_type text, p_sha256 text, p_alt_text text, p_usage_scope text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."register_person_identity_submission"(p_person_record_id uuid, p_document_kind text, p_attachment_id uuid, p_file_name text, p_file_type text, p_file_size_bytes bigint, p_storage_path text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_person public.person_records%rowtype;
  v_conversation uuid;
BEGIN
  SELECT * INTO v_person FROM public.person_records WHERE id = p_person_record_id;
  IF v_actor IS NULL OR v_person.id IS NULL OR NOT public.org_access_allowed(v_person.organization_id) THEN
    RAISE EXCEPTION 'Person record not found in your authorised scope';
  END IF;
  IF v_person.metadata ? 'merged_into_person_record_id' OR v_person.metadata ? 'resolved_into_person_record_id' THEN
    RAISE EXCEPTION 'This person has been merged into another record';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.identity_document_type_definitions d WHERE d.document_kind = p_document_kind AND d.active) THEN
    RAISE EXCEPTION 'Unsupported identity document kind';
  END IF;
  IF p_file_type NOT IN ('image/jpeg', 'image/png', 'image/webp', 'image/bmp', 'image/tiff', 'application/pdf') THEN
    RAISE EXCEPTION 'Unsupported identity evidence file type';
  END IF;
  IF p_file_size_bytes <= 0 OR p_file_size_bytes > 26214400 THEN RAISE EXCEPTION 'Identity evidence must be 25 MB or smaller'; END IF;
  IF p_storage_path NOT LIKE 'org/' || v_person.organization_id::text || '/identity/' || v_actor::text || '/submission-' || v_person.id::text || '/%' THEN
    RAISE EXCEPTION 'Identity evidence path is outside the submission scope';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM storage.objects o WHERE o.bucket_id = 'identity-evidence' AND o.name = p_storage_path) THEN
    RAISE EXCEPTION 'Uploaded identity evidence object not found';
  END IF;
  SELECT id INTO v_conversation FROM public.bob_conversations
  WHERE organization_id = v_person.organization_id AND user_id = v_actor AND module_key = 'operations' ORDER BY updated_at DESC LIMIT 1;
  IF v_conversation IS NULL THEN
    INSERT INTO public.bob_conversations (organization_id, user_id, module_key, title)
    VALUES (v_person.organization_id, v_actor, 'operations', 'Identity evidence')
    RETURNING id INTO v_conversation;
  END IF;
  INSERT INTO public.bob_attachments (id, organization_id, conversation_id, uploaded_by, file_name, file_type, file_size_bytes,
    storage_bucket, storage_path, purpose, processing_state, extraction_payload)
  VALUES (p_attachment_id, v_person.organization_id, v_conversation, v_actor, p_file_name, p_file_type, p_file_size_bytes,
    'identity-evidence', p_storage_path, 'identity_document', 'processing',
    jsonb_build_object('person_record_id', v_person.id, 'document_kind', p_document_kind, 'capture_authority', 'member_submission'));
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_person.organization_id, v_actor, 'person_identity_submission_registered', 'bob_attachments', p_attachment_id,
    jsonb_build_object('person_record_id', v_person.id, 'document_kind', p_document_kind));
  RETURN jsonb_build_object('attachment_id', p_attachment_id, 'organization_id', v_person.organization_id,
    'person_record_id', v_person.id, 'document_kind', p_document_kind);
END;
$function$;
COMMENT ON FUNCTION "public"."register_person_identity_submission"(p_person_record_id uuid, p_document_kind text, p_attachment_id uuid, p_file_name text, p_file_type text, p_file_size_bytes bigint, p_storage_path text) IS 'Any member of the organisation can submit ID evidence for a person. bob-perceive-image extracts it into a manual_review_required identity document; only an administrator approves it (review_canonical_identity_evidence) and only approval verifies the person.';
REVOKE ALL ON FUNCTION "public"."register_person_identity_submission"(p_person_record_id uuid, p_document_kind text, p_attachment_id uuid, p_file_name text, p_file_type text, p_file_size_bytes bigint, p_storage_path text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."register_person_identity_submission"(p_person_record_id uuid, p_document_kind text, p_attachment_id uuid, p_file_name text, p_file_type text, p_file_size_bytes bigint, p_storage_path text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."register_person_identity_submission"(p_person_record_id uuid, p_document_kind text, p_attachment_id uuid, p_file_name text, p_file_type text, p_file_size_bytes bigint, p_storage_path text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."reject_boundary_proposal"(p_proposal_id uuid, p_note text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_actor uuid := auth.uid(); v_p public.boundary_proposals%rowtype;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF nullif(trim(coalesce(p_note, '')), '') IS NULL THEN RAISE EXCEPTION 'A rejection reason is required'; END IF;
  SELECT * INTO v_p FROM public.boundary_proposals WHERE id = p_proposal_id FOR UPDATE;
  IF NOT FOUND OR NOT public.org_access_allowed(v_p.organization_id) THEN RAISE EXCEPTION 'Proposal not found or access denied'; END IF;
  IF v_p.status <> 'proposed' THEN RAISE EXCEPTION 'Proposal is already %', v_p.status; END IF;
  UPDATE public.boundary_proposals SET status = 'rejected', decided_by = v_actor, decided_at = clock_timestamp(), decision_note = trim(p_note) WHERE id = v_p.id;
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_p.organization_id, v_actor, 'boundary_proposal_rejected', 'boundary_proposals', v_p.id, jsonb_build_object('entity_type', v_p.entity_type, 'entity_id', v_p.entity_id, 'source', v_p.source, 'note', trim(p_note)));
  RETURN true;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."reject_boundary_proposal"(p_proposal_id uuid, p_note text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."reject_boundary_proposal"(p_proposal_id uuid, p_note text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."reject_boundary_proposal"(p_proposal_id uuid, p_note text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."reject_boundary_proposal"(p_proposal_id uuid, p_note text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."remove_crm_invoice_line"(p_client_request_id uuid, p_invoice_id uuid, p_line_id uuid)
 RETURNS TABLE(invoice_id uuid, subtotal numeric, gst_amount numeric, total_amount numeric, removed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_invoice public.invoices%rowtype;
  v_line public.invoice_line_items%rowtype;
  v_prior_removal boolean;
BEGIN
  IF p_client_request_id IS NULL OR p_invoice_id IS NULL OR p_line_id IS NULL THEN
    RAISE EXCEPTION 'client_request_id, invoice, and line are required';
  END IF;

  SELECT i.* INTO v_invoice
  FROM public.invoices i
  WHERE i.id = p_invoice_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invoice not found';
  END IF;
  IF NOT public.is_admin_for_org(v_invoice.organization_id) THEN
    RAISE EXCEPTION 'Not authorised to manage invoices for this organization';
  END IF;
  IF v_invoice.status <> 'draft' THEN
    RAISE EXCEPTION 'Only draft invoices can be modified';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.audit_log a
    WHERE a.organization_id = v_invoice.organization_id
      AND a.action = 'crm_invoice_line_removed'
      AND a.metadata->>'invoice_id' = v_invoice.id::text
      AND a.metadata->>'line_id' = p_line_id::text
      AND a.metadata->>'client_request_id' = p_client_request_id::text
  ) INTO v_prior_removal;

  IF v_prior_removal THEN
    RETURN QUERY
    SELECT v_invoice.id, v_invoice.subtotal, v_invoice.gst_amount, v_invoice.total_amount, true;
    RETURN;
  END IF;

  SELECT l.* INTO v_line
  FROM public.invoice_line_items l
  WHERE l.id = p_line_id AND l.invoice_id = v_invoice.id;

  IF NOT FOUND THEN
    RETURN QUERY
    SELECT v_invoice.id, v_invoice.subtotal, v_invoice.gst_amount, v_invoice.total_amount, false;
    RETURN;
  END IF;
  IF v_line.line_source <> 'manual' OR v_line.client_request_id IS NULL THEN
    RAISE EXCEPTION 'Evidence-backed invoice lines cannot be removed; correct the source work or void the draft';
  END IF;

  DELETE FROM public.invoice_line_items
  WHERE id = v_line.id;

  UPDATE public.invoices i
  SET subtotal = totals.subtotal,
      gst_amount = round(totals.subtotal * 0.15, 2),
      total_amount = round(totals.subtotal * 1.15, 2),
      updated_at = now()
  FROM (
    SELECT coalesce(sum(l.line_total), 0)::numeric(12,2) AS subtotal
    FROM public.invoice_line_items l
    WHERE l.invoice_id = v_invoice.id
  ) totals
  WHERE i.id = v_invoice.id
  RETURNING i.* INTO v_invoice;

  INSERT INTO public.audit_log(
    organization_id, actor_user_id, action, target_table, target_id, metadata
  ) VALUES (
    v_invoice.organization_id, v_actor, 'crm_invoice_line_removed',
    'invoice_line_items', v_line.id,
    jsonb_build_object(
      'invoice_id', v_invoice.id,
      'line_id', v_line.id,
      'description', v_line.description,
      'line_total', v_line.line_total,
      'original_client_request_id', v_line.client_request_id,
      'client_request_id', p_client_request_id
    )
  );

  RETURN QUERY
  SELECT v_invoice.id, v_invoice.subtotal, v_invoice.gst_amount, v_invoice.total_amount, true;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."remove_crm_invoice_line"(p_client_request_id uuid, p_invoice_id uuid, p_line_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."remove_crm_invoice_line"(p_client_request_id uuid, p_invoice_id uuid, p_line_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."remove_crm_invoice_line"(p_client_request_id uuid, p_invoice_id uuid, p_line_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."remove_crm_invoice_line"(p_client_request_id uuid, p_invoice_id uuid, p_line_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."remove_crm_quote_line"(p_client_request_id uuid, p_quote_id uuid, p_line_id uuid, p_expected_status text)
 RETURNS TABLE(quote_id uuid, total_cost numeric, subtotal_charge numeric, discount_amount numeric, gst_amount numeric, total_charge numeric, removed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_quote public.quotes%rowtype;
  v_line public.quote_lines%rowtype;
begin
  if p_client_request_id is null then
    raise exception 'client_request_id is required';
  end if;

  select q.* into v_quote from public.quotes q where q.id = p_quote_id for update;
  if not found then
    raise exception 'Quote not found';
  end if;

  if not public.is_admin_for_org(v_quote.provider_org_id) then
    raise exception 'Not authorised to price this quote';
  end if;

  if v_quote.status <> p_expected_status then
    raise exception 'Quote changed from expected status % to %', p_expected_status, v_quote.status;
  end if;

  if v_quote.status <> 'draft' then
    raise exception 'Only draft quotes can be modified';
  end if;

  select l.* into v_line from public.quote_lines l where l.id = p_line_id and l.quote_id = v_quote.id;
  if not found then
    return query select v_quote.id, v_quote.total_cost, v_quote.subtotal_charge, v_quote.discount_amount, v_quote.gst_amount, v_quote.total_charge, false;
    return;
  end if;

  delete from public.quote_lines where id = v_line.id;

  update public.quotes q set
    total_cost = totals.total_cost,
    subtotal_charge = totals.subtotal_charge,
    discount_amount = round(totals.subtotal_charge * q.discount_pct / 100, 2),
    gst_amount = round((totals.subtotal_charge - round(totals.subtotal_charge * q.discount_pct / 100, 2)) * q.gst_rate, 2),
    total_charge = round((totals.subtotal_charge - round(totals.subtotal_charge * q.discount_pct / 100, 2)) * (1 + q.gst_rate), 2),
    updated_by = v_actor,
    updated_at = now()
  from (
    select
      coalesce(sum(l.quantity * l.unit_cost), 0)::numeric(12,2) total_cost,
      coalesce(sum(l.quantity * l.unit_charge), 0)::numeric(12,2) subtotal_charge
    from public.quote_lines l
    where l.quote_id = v_quote.id
  ) totals
  where q.id = v_quote.id
  returning q.* into v_quote;

  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (
    v_quote.provider_org_id,
    v_actor,
    'crm_quote_line_removed',
    'quote_lines',
    v_line.id,
    jsonb_build_object(
      'quote_id', v_quote.id,
      'kind', v_line.kind,
      'description', v_line.description,
      'total_cost', v_quote.total_cost,
      'total_charge', v_quote.total_charge,
      'client_request_id', p_client_request_id
    )
  );

  return query select v_quote.id, v_quote.total_cost, v_quote.subtotal_charge, v_quote.discount_amount, v_quote.gst_amount, v_quote.total_charge, true;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."remove_crm_quote_line"(p_client_request_id uuid, p_quote_id uuid, p_line_id uuid, p_expected_status text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."remove_crm_quote_line"(p_client_request_id uuid, p_quote_id uuid, p_line_id uuid, p_expected_status text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."remove_crm_quote_line"(p_client_request_id uuid, p_quote_id uuid, p_line_id uuid, p_expected_status text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."remove_crm_quote_line"(p_client_request_id uuid, p_quote_id uuid, p_line_id uuid, p_expected_status text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."remove_workshop_work_order_line"(p_work_order_id uuid, p_line_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_wo public.workshop_work_orders%rowtype;
  v_actor uuid := auth.uid();
  v_role text;
  v_line public.workshop_work_order_lines%rowtype;
begin
  select * into v_wo from public.workshop_work_orders w where w.id = p_work_order_id for update;
  if not found then raise exception 'Work order not found'; end if;
  v_role := public.workshop_line_actor_role(v_wo);
  if v_wo.status in ('completed', 'cancelled') then raise exception 'Lines cannot be removed once the work order is %', v_wo.status; end if;
  select * into v_line from public.workshop_work_order_lines l where l.id = p_line_id and l.work_order_id = v_wo.id;
  if not found then return; end if;
  if v_role = 'worker' and v_line.created_by is distinct from v_actor then
    raise exception 'You can only remove lines you added yourself';
  end if;
  delete from public.workshop_work_order_lines where id = v_line.id;
  update public.workshop_work_orders set updated_at = now(), updated_by = v_actor where id = v_wo.id;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."remove_workshop_work_order_line"(p_work_order_id uuid, p_line_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."remove_workshop_work_order_line"(p_work_order_id uuid, p_line_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."remove_workshop_work_order_line"(p_work_order_id uuid, p_line_id uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."renew_staff_credential"(p_client_request_id uuid, p_source_credential_id uuid, p_expected_expiry_date date, p_credential_number text, p_issuing_authority text, p_issued_date date, p_expiry_date date, p_evidence_notes text)
 RETURNS TABLE(credential_id uuid, staff_id uuid, verified boolean, verified_at timestamp with time zone, created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_source public.staff_credentials%rowtype;v_renewal public.staff_credentials%rowtype;v_number text:=nullif(trim(coalesce(p_credential_number,'')),'');v_authority text:=nullif(trim(coalesce(p_issuing_authority,'')),'');v_notes text:=nullif(trim(coalesce(p_evidence_notes,'')),'');
begin
  if p_client_request_id is null then raise exception 'Client request ID is required';end if;
  select c.* into v_source from public.staff_credentials c where c.id=p_source_credential_id for update;if not found then raise exception 'Source credential not found';end if;
  if not public.is_admin_for_org(v_source.organization_id) then raise exception 'Active provider administrator required';end if;
  if v_source.expiry_date is distinct from p_expected_expiry_date then raise exception 'Credential expiry changed from expected state';end if;
  if v_source.expiry_date is null then raise exception 'Only expiring credentials can be renewed';end if;
  if v_number is null or v_authority is null or v_notes is null or length(v_notes)<10 then raise exception 'Credential number, issuing authority, and evidence notes are required';end if;
  if p_issued_date is null or p_expiry_date is null or p_issued_date>p_expiry_date or p_expiry_date<=v_source.expiry_date then raise exception 'Renewal dates must establish a later valid credential';end if;
  perform pg_advisory_xact_lock(hashtextextended(p_client_request_id::text,0));
  select c.* into v_renewal from public.staff_credentials c where c.organization_id=v_source.organization_id and c.client_request_id=p_client_request_id;
  if found then if v_renewal.replaces_credential_id<>v_source.id then raise exception 'Credential renewal request identity collision';end if;return query select v_renewal.id,v_renewal.staff_id,v_renewal.verified,v_renewal.verified_at,false;return;end if;
  insert into public.staff_credentials(staff_id,organization_id,credential_type,credential_number,issuing_authority,issued_date,expiry_date,authorized_activities,verified,verified_by,verified_at,notes,client_request_id,replaces_credential_id) values(v_source.staff_id,v_source.organization_id,v_source.credential_type,v_number,v_authority,p_issued_date,p_expiry_date,v_source.authorized_activities,true,v_actor,clock_timestamp(),v_notes,p_client_request_id,v_source.id) returning * into v_renewal;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_source.organization_id,v_actor,'staff_credential_renewed','staff_credentials',v_renewal.id,jsonb_build_object('source_credential_id',v_source.id,'staff_id',v_source.staff_id,'credential_type',v_source.credential_type,'previous_expiry_date',v_source.expiry_date,'expiry_date',v_renewal.expiry_date,'evidence_notes',v_notes));
  return query select v_renewal.id,v_renewal.staff_id,v_renewal.verified,v_renewal.verified_at,true;
end;$function$;
REVOKE ALL ON FUNCTION "public"."renew_staff_credential"(p_client_request_id uuid, p_source_credential_id uuid, p_expected_expiry_date date, p_credential_number text, p_issuing_authority text, p_issued_date date, p_expiry_date date, p_evidence_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."renew_staff_credential"(p_client_request_id uuid, p_source_credential_id uuid, p_expected_expiry_date date, p_credential_number text, p_issuing_authority text, p_issued_date date, p_expiry_date date, p_evidence_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."renew_staff_credential"(p_client_request_id uuid, p_source_credential_id uuid, p_expected_expiry_date date, p_credential_number text, p_issuing_authority text, p_issued_date date, p_expiry_date date, p_evidence_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."renew_staff_credential"(p_client_request_id uuid, p_source_credential_id uuid, p_expected_expiry_date date, p_credential_number text, p_issuing_authority text, p_issued_date date, p_expiry_date date, p_evidence_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."repeat_roster_slot_range"(p_source_slot_id uuid, p_from_date date, p_to_date date)
 RETURNS TABLE(created_count integer, skipped_conflict_count integer, leave_conflict_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_actor uuid := auth.uid(); v_source public.roster_slots%rowtype; v_day date; v_start timestamptz;
  v_end timestamptz; v_created integer := 0; v_skipped integer := 0; v_leave integer := 0; v_duration interval;
begin
  select * into v_source from public.roster_slots where id = p_source_slot_id for update;
  if not found or v_actor is null or not public.is_admin_for_org(v_source.organization_id)
    or not exists(select 1 from public.user_profiles where id = v_actor and deactivated_at is null) then
    raise exception 'Active roster administrator required' using errcode = '42501';
  end if;
  if v_source.status in ('completed','cancelled') then raise exception 'Completed or cancelled slots cannot be repeated'; end if;
  if p_from_date is null or p_to_date is null or p_from_date > p_to_date or p_to_date - p_from_date > 92 then
    raise exception 'Repeat period must be between 1 and 93 days';
  end if;
  v_duration := v_source.scheduled_end - v_source.scheduled_start;
  for v_day in select generate_series(p_from_date,p_to_date,interval '1 day')::date loop
    v_start := v_day + v_source.scheduled_start::time; v_end := v_start + v_duration;
    if exists(select 1 from public.leave_requests l where l.staff_id = v_source.staff_id and l.status = 'approved'
      and daterange(l.starts_on,l.ends_on,'[]') && daterange(v_start::date,v_end::date,'[]')) then
      v_leave := v_leave + 1; continue;
    end if;
    if exists(select 1 from public.roster_slots s where s.staff_id = v_source.staff_id and s.status not in ('declined','cancelled')
      and s.scheduled_start < v_end and s.scheduled_end > v_start) then v_skipped := v_skipped + 1; continue; end if;
    insert into public.roster_slots(organization_id,work_unit_id,staff_id,scheduled_start,scheduled_end,status,
      client_request_id,notes,created_by,planned_break_minutes,break_unpaid)
    values(v_source.organization_id,v_source.work_unit_id,v_source.staff_id,v_start,v_end,'draft',gen_random_uuid(),
      coalesce(v_source.notes,'') || ' - Repeated assignment',v_actor,v_source.planned_break_minutes,v_source.break_unpaid);
    v_created := v_created + 1;
  end loop;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
  values(v_source.organization_id,v_actor,'roster_slot_repeated','roster_slots',v_source.id,
    jsonb_build_object('from_date',p_from_date,'to_date',p_to_date,'created_count',v_created,
      'skipped_conflict_count',v_skipped,'leave_conflict_count',v_leave));
  return query select v_created,v_skipped,v_leave;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."repeat_roster_slot_range"(p_source_slot_id uuid, p_from_date date, p_to_date date) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."repeat_roster_slot_range"(p_source_slot_id uuid, p_from_date date, p_to_date date) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."repeat_roster_slot_range"(p_source_slot_id uuid, p_from_date date, p_to_date date) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."report_activity_category"(p_kind text, p_event_type text, p_service_line text, p_subject text, p_activity text, p_species text, p_equipment text, p_material text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
	select case
		when p_kind = 'incident' then 'incident'
		when p_event_type = 'dispatch_callout' then 'call_out'
		when p_service_line = 'pest_control'
			or p_subject in ('animal', 'pest_device')
			or p_activity in ('cull', 'sighting', 'pest_patrol', 'device_unset', 'device_reset', 'device_inactive', 'rebait', 'prefeed')
			or p_species is not null
			or p_equipment in ('trap', 'bait_station')
			or p_material in ('ammunition', 'bait_feed')
			then 'pest_control'
		when p_activity = 'manufacture' then 'manufacture'
		when p_activity = 'maintenance' then 'maintenance'
		when p_activity in ('installation', 'uninstall', 'removal') then 'installation_removal'
		when p_activity = 'securing' then 'securing'
		when p_activity = 'inspection' then 'inspection'
		when p_activity in ('travel', 'administration', 'materials') then 'travel_admin'
		when p_kind = 'observation' then 'vehicle_observation'
		when p_event_type = 'camera_activation' then 'camera_activation'
		when p_activity = 'other' then 'other_work'
		when p_event_type = 'patrol_visit' then 'patrol_visit'
		else 'unclassified'
	end;
$function$;
COMMENT ON FUNCTION "public"."report_activity_category"(p_kind text, p_event_type text, p_service_line text, p_subject text, p_activity text, p_species text, p_equipment text, p_material text) IS 'Assigns exactly one report category to a recorded activity entry. Precedence: incidents, attended dispatch call-outs, pest control, manufacture, maintenance, installation and removal, securing, inspection, travel and administration, observations, camera activations, other recorded work, patrol visits without a work type, then other site activity.';
REVOKE ALL ON FUNCTION "public"."report_activity_category"(p_kind text, p_event_type text, p_service_line text, p_subject text, p_activity text, p_species text, p_equipment text, p_material text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."report_activity_category"(p_kind text, p_event_type text, p_service_line text, p_subject text, p_activity text, p_species text, p_equipment text, p_material text) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."report_cctv_missed_detection"(p_evidence_item_id uuid, p_entity_kind text, p_offset_seconds numeric DEFAULT NULL::numeric, p_observed_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_bbox jsonb DEFAULT NULL::jsonb, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_job uuid;
  v_engine text;
  v_id uuid;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT organization_id INTO v_org FROM public.evidence_items WHERE id = p_evidence_item_id;
  IF v_org IS NULL OR NOT coalesce(public.org_access_allowed(v_org), false) THEN RAISE EXCEPTION 'CCTV review access denied'; END IF;
  IF p_entity_kind IS NULL OR p_entity_kind NOT IN ('person', 'vehicle', 'animal') THEN
    RAISE EXCEPTION 'Choose person, vehicle, or animal';
  END IF;
  IF p_offset_seconds IS NULL AND p_observed_at IS NULL THEN RAISE EXCEPTION 'Say when in the clip the sighting was missed'; END IF;
  IF p_offset_seconds IS NOT NULL AND p_offset_seconds < 0 THEN RAISE EXCEPTION 'The clip position cannot be negative'; END IF;
  IF p_bbox IS NOT NULL AND jsonb_typeof(p_bbox) <> 'object' THEN RAISE EXCEPTION 'The marked area must be a box'; END IF;
  SELECT job.id INTO v_job
    FROM public.inference_jobs job
   WHERE job.evidence_item_id = p_evidence_item_id AND job.organization_id = v_org AND job.domain = 'video_motion'
   ORDER BY job.created_at DESC
   LIMIT 1;
  IF v_job IS NOT NULL THEN
    SELECT result.result->'classification_plan'->'model_manifest'->>'engine_version' INTO v_engine
      FROM public.inference_results result
     WHERE result.inference_job_id = v_job
     ORDER BY result.created_at DESC
     LIMIT 1;
  END IF;
  INSERT INTO public.cctv_missed_detection_reports (
    organization_id, evidence_item_id, inference_job_id, entity_kind, offset_seconds, observed_at, bbox, notes,
    engine_version, reported_by
  ) VALUES (
    v_org, p_evidence_item_id, v_job, p_entity_kind, p_offset_seconds, p_observed_at, p_bbox,
    left(nullif(trim(coalesce(p_notes, '')), ''), 2000), coalesce(v_engine, 'legacy'), v_actor
  ) RETURNING id INTO v_id;
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_org, v_actor, 'cctv_missed_detection_reported', 'cctv_missed_detection_reports', v_id,
          jsonb_strip_nulls(jsonb_build_object('evidence_item_id', p_evidence_item_id, 'inference_job_id', v_job,
            'entity_kind', p_entity_kind, 'engine_version', coalesce(v_engine, 'legacy'))));
  RETURN v_id;
END;
$function$;
COMMENT ON FUNCTION "public"."report_cctv_missed_detection"(p_evidence_item_id uuid, p_entity_kind text, p_offset_seconds numeric, p_observed_at timestamp with time zone, p_bbox jsonb, p_notes text) IS 'Any member with access to the footage reports a sighting the engine missed. Stamps the engine version that produced the latest result and writes audit_log cctv_missed_detection_reported.';
REVOKE ALL ON FUNCTION "public"."report_cctv_missed_detection"(p_evidence_item_id uuid, p_entity_kind text, p_offset_seconds numeric, p_observed_at timestamp with time zone, p_bbox jsonb, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."report_cctv_missed_detection"(p_evidence_item_id uuid, p_entity_kind text, p_offset_seconds numeric, p_observed_at timestamp with time zone, p_bbox jsonb, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."report_cctv_missed_detection"(p_evidence_item_id uuid, p_entity_kind text, p_offset_seconds numeric, p_observed_at timestamp with time zone, p_bbox jsonb, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."report_cctv_missed_detection"(p_evidence_item_id uuid, p_entity_kind text, p_offset_seconds numeric, p_observed_at timestamp with time zone, p_bbox jsonb, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."report_code_or_null"(p_value text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
	select case when p_value ~ '^[a-z][a-z0-9_]{0,40}$' then p_value end;
$function$;
COMMENT ON FUNCTION "public"."report_code_or_null"(p_value text) IS 'Returns a work-catalogue style code (lower snake case) or null, so only catalogue codes can be copied from imported payloads into reports.';
REVOKE ALL ON FUNCTION "public"."report_code_or_null"(p_value text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."report_code_or_null"(p_value text) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."report_numeric_or_null"(p_value text)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
	select case
		when p_value is not null
			and p_value <> ''
			and p_value ~ '^[0-9]{0,9}(\.[0-9]{1,6})?$'
		then p_value::numeric
	end;
$function$;
COMMENT ON FUNCTION "public"."report_numeric_or_null"(p_value text) IS 'Parses a non-negative decimal from imported text, or returns null. Used so report statistics never cast free text.';
REVOKE ALL ON FUNCTION "public"."report_numeric_or_null"(p_value text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."report_numeric_or_null"(p_value text) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."report_pack_trend_context"(p_pack_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_pack record;
  v_month date;
  v_report jsonb;
  v_months jsonb := '[]'::jsonb;
begin
  select pack.id, pack.service_agreement_id, pack.period_start
  into v_pack
  from public.monthly_report_packs pack
  where pack.id = p_pack_id;
  if v_pack.id is null then
    raise exception 'Report pack not found';
  end if;
  for i in 1..2 loop
    v_month := (date_trunc('month', v_pack.period_start::timestamp) - make_interval(months => i))::date;
    v_report := public.build_agreement_activity_report(
      v_pack.service_agreement_id,
      v_month::timestamp at time zone 'Pacific/Auckland',
      (v_month + interval '1 month')::timestamp at time zone 'Pacific/Auckland',
      0
    ) -> 'report';
    v_months := v_months || jsonb_build_array(jsonb_build_object(
      'month', to_char(v_month, 'YYYY-MM'),
      'report', case when v_report is null then null else jsonb_strip_nulls(jsonb_build_object(
        'version', v_report -> 'version',
        'totals', v_report -> 'totals',
        'categories', v_report -> 'categories',
        'incidents', v_report -> 'incidents',
        'observations', v_report -> 'observations',
        'pestControl', v_report -> 'pestControl',
        'hunterReturns', v_report -> 'hunterReturns',
        'labels', v_report -> 'labels'
      )) end,
      'confirmedIncidents', coalesce((
        select jsonb_agg(jsonb_build_object('type', grouped.incident_type, 'count', grouped.n) order by grouped.n desc, grouped.incident_type)
        from (
          select t.incident_type, count(*)::integer as n
          from public.report_incident_triage t
          where t.service_agreement_id = v_pack.service_agreement_id
            and t.decision = 'incident'
            and t.line_date >= v_month
            and t.line_date < (v_month + interval '1 month')::date
          group by t.incident_type
        ) grouped
      ), '[]'::jsonb)
    ));
  end loop;
  return jsonb_build_object('months', v_months);
end;
$function$;
COMMENT ON FUNCTION "public"."report_pack_trend_context"(p_pack_id uuid) IS 'Server-only: the report figures (no itemised lines) for the two calendar months before a pack, plus reviewer-confirmed incidents by type, so Bob can compare the period with the previous two months. Called by draft-report-executive-summary with the service role after its own custodian check.';
REVOKE ALL ON FUNCTION "public"."report_pack_trend_context"(p_pack_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."report_pack_trend_context"(p_pack_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."report_pack_trend_context"(p_pack_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."report_photo_name_withheld"(p_name text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'pg_catalog'
AS $function$
select coalesce(p_name, '') ~* '(^|[^a-z0-9])nzta([^a-z0-9]|$)'
	or coalesce(p_name, '') ~* '(^|[^a-z])(dl|dl_?front|dl_?back|drivers?_?licen[cs]e|licen[cs]e|firearms?_?licen[cs]e|passport|id_?card|photo_?id)([^a-z]|$)'
$function$;
COMMENT ON FUNCTION "public"."report_photo_name_withheld"(p_name text) IS 'True when a photo file name or path marks an NZTA screenshot or an identity document (driver licence, passport, ID card); such photos never appear in client reports.';
REVOKE ALL ON FUNCTION "public"."report_photo_name_withheld"(p_name text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."report_photo_name_withheld"(p_name text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."report_photo_name_withheld"(p_name text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."report_place_hazard"(p_shift_id uuid, p_place_kind text, p_place_id uuid, p_title text, p_hazard_class text, p_risk_level text, p_client_request_id uuid, p_details text DEFAULT NULL::text, p_controls text[] DEFAULT '{}'::text[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_shift public.shifts%rowtype;
  v_place record;
  v_id uuid;
  v_controls text[];
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_client_request_id IS NULL THEN RAISE EXCEPTION 'client_request_id is required'; END IF;
  SELECT * INTO v_shift FROM public.shifts WHERE id = p_shift_id;
  IF NOT FOUND OR v_shift.officer_user_id IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'Only the assigned officer can report a hazard on this shift';
  END IF;
  SELECT h.id INTO v_id FROM public.place_hazards h WHERE h.organization_id = v_shift.organization_id AND h.client_request_id = p_client_request_id;
  IF FOUND THEN RETURN v_id; END IF;
  IF v_shift.status <> 'in_progress' THEN
    RAISE EXCEPTION 'Hazards can be reported during an in-progress shift';
  END IF;

  SELECT * INTO v_place FROM public.shift_safety_places(p_shift_id, NULL) p
  WHERE p.place_kind = p_place_kind AND p.place_id = p_place_id
  LIMIT 1;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'That place is not part of this shift';
  END IF;

  SELECT coalesce(array_agg(left(btrim(c), 300)) FILTER (WHERE btrim(c) <> ''), '{}'::text[])
  INTO v_controls FROM unnest(coalesce(p_controls, '{}'::text[])) c;

  INSERT INTO public.place_hazards (
    organization_id, location_id, client_site_id, zone_id, title, hazard_class, risk_level,
    controls, details, origin, status, reported_by, reported_shift_id, client_request_id, created_by
  ) VALUES (
    v_shift.organization_id, v_place.location_id,
    CASE WHEN p_place_kind = 'site' THEN p_place_id END,
    CASE WHEN p_place_kind = 'zone' THEN p_place_id END,
    btrim(coalesce(p_title, '')), p_hazard_class, p_risk_level,
    v_controls, nullif(btrim(coalesce(p_details, '')), ''),
    'officer_reported', 'reported', v_actor, p_shift_id, p_client_request_id, v_actor
  )
  RETURNING id INTO v_id;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_shift.organization_id, v_actor, 'place_hazard_reported', 'place_hazards', v_id,
    jsonb_build_object('shift_id', p_shift_id, 'place_kind', p_place_kind, 'place_id', p_place_id, 'hazard_class', p_hazard_class, 'risk_level', p_risk_level));

  RETURN v_id;
END;
$function$;
COMMENT ON FUNCTION "public"."report_place_hazard"(p_shift_id uuid, p_place_kind text, p_place_id uuid, p_title text, p_hazard_class text, p_risk_level text, p_client_request_id uuid, p_details text, p_controls text[]) IS 'The assigned officer reports a new hazard at one of the places of their in-progress shift. Stored as reported (shown to other officers as not yet reviewed) until a supervisor confirms or retires it. Idempotent on client_request_id; audited.';
REVOKE ALL ON FUNCTION "public"."report_place_hazard"(p_shift_id uuid, p_place_kind text, p_place_id uuid, p_title text, p_hazard_class text, p_risk_level text, p_client_request_id uuid, p_details text, p_controls text[]) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."report_place_hazard"(p_shift_id uuid, p_place_kind text, p_place_id uuid, p_title text, p_hazard_class text, p_risk_level text, p_client_request_id uuid, p_details text, p_controls text[]) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."report_place_hazard"(p_shift_id uuid, p_place_kind text, p_place_id uuid, p_title text, p_hazard_class text, p_risk_level text, p_client_request_id uuid, p_details text, p_controls text[]) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."report_place_hazard"(p_shift_id uuid, p_place_kind text, p_place_id uuid, p_title text, p_hazard_class text, p_risk_level text, p_client_request_id uuid, p_details text, p_controls text[]) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."report_provider_custodian_for_actor"(p_target_organization_id uuid, p_actor_user_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
  select exists (
    select 1
    from public.user_profiles profile
    where profile.id = p_actor_user_id
      and profile.deactivated_at is null
      and profile.role in ('grand_master', 'master', 'admin', 'admin_officer')
      and (
        profile.organization_id = p_target_organization_id
        or p_target_organization_id = any(public.get_descendant_organizations(profile.organization_id))
        or (
          profile.employer_organization_id is not null
          and (
            profile.employer_organization_id = p_target_organization_id
            or p_target_organization_id = any(public.get_descendant_organizations(profile.employer_organization_id))
          )
        )
      )
  );
$function$;
REVOKE ALL ON FUNCTION "public"."report_provider_custodian_for_actor"(p_target_organization_id uuid, p_actor_user_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."report_provider_custodian_for_actor"(p_target_organization_id uuid, p_actor_user_id uuid) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."report_redact_identified_persons"(p_text text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'pg_catalog'
AS $function$
with sentences as (
	select s.ord, s.sentence,
		(
			s.sentence ~* '(^|[^a-z])(d\.?\s?o\.?\s?b\.?|date of birth|born on)([^a-z]|$)'
			or s.sentence ~ '\m\d{1,5}[A-Za-z]?\s+([A-Z][a-z]+\s+){1,3}(Road|Rd|Street|St|Avenue|Ave|Drive|Dr|Lane|Ln|Place|Pl|Crescent|Cres|Terrace|Tce|Grove|Close|Highway|Hwy)\M'
			or s.sentence ~ '(^|[^0-9])0\d{1,2}[\s-]?\d{3}[\s-]?\d{3,4}([^0-9]|$)'
			or (s.sentence ~ '\m[A-Z]{2}\d{6}\M' and s.sentence ~* '(licen[cs]e|(^|[^a-z])dl([^a-z]|$)|driver)')
			or s.sentence ~* '[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}'
			or s.sentence ~ '\m(?!(Reg|Rego|Review|Reviewed|Plate|Plates|Vehicle|Camera|Cameras)\M)[A-Z][a-z]+(\s+[A-Z][a-z]+){0,2}\s+(?!(COVID|TPFL|MTRS|REMSEC|DART|OLSEN|DOWNER|NZDF|NZTA|LINZ|SPCA|CCTV|STAND|SERP|BERR|SMIT|INWO|POLICE|NOTE|NOTED|OPEN|OPENED|CLOSED|LOCKED|UNLOCKED|SECURE|GATE|DONE|NONE|LEFT|RIGHT|ONLY|ALSO|STILL|EXIT|ENTRY|WARNING|CAUTION|ALERT|URGENT|FOOTAGE|IMAGE|IMAGES|PHOTO|PHOTOS|VIDEO|SECURITY|TRESPASS|TRESPASSED|PERMIT|HUNTING|FIRE|SMOKE|DEER|PIGS|GOATS|HILUX|RANGER|NAVARA|TRITON|COURIER|PRADO|CRUISER|LANDCRUISER|BT50|NISSAN|TOYOTA|FORD|HOLDEN|MAZDA|HONDA|SUZUKI|YAMAHA|POLARIS|ISUZU|MITSUBISHI|SUBARU|WORKING|FAULTY|BROKEN|DAMAGED|MISSING|STOLEN|CALLED|NOTIFIED|REPORTED|ADMIN|TRAVEL|PATROL|CHECK|CHECKED|OKAY|KEYS|LOCK|LOCKS|SIGN|SIGNS|ROAD|BLOCK|FOREST|NELSON|TASMAN|MARLBOROUGH|MOTUEKA|RICHMOND|BLENHEIM|ONEFORTYONE)\M)[A-Z]{4,}\M'
			or s.sentence ~ '\m(?!(COVID|TPFL|MTRS|REMSEC|DART|OLSEN|DOWNER|NZDF|NZTA|LINZ|SPCA|CCTV|STAND|SERP|BERR|SMIT|INWO|POLICE|NOTE|NOTED|OPEN|OPENED|CLOSED|LOCKED|UNLOCKED|SECURE|GATE|DONE|NONE|LEFT|RIGHT|ONLY|ALSO|STILL|EXIT|ENTRY|WARNING|CAUTION|ALERT|URGENT|FOOTAGE|IMAGE|IMAGES|PHOTO|PHOTOS|VIDEO|SECURITY|TRESPASS|TRESPASSED|PERMIT|HUNTING|FIRE|SMOKE|DEER|PIGS|GOATS|HILUX|RANGER|NAVARA|TRITON|COURIER|PRADO|CRUISER|LANDCRUISER|BT50|NISSAN|TOYOTA|FORD|HOLDEN|MAZDA|HONDA|SUZUKI|YAMAHA|POLARIS|ISUZU|MITSUBISHI|SUBARU|WORKING|FAULTY|BROKEN|DAMAGED|MISSING|STOLEN|CALLED|NOTIFIED|REPORTED|ADMIN|TRAVEL|PATROL|CHECK|CHECKED|OKAY|KEYS|LOCK|LOCKS|SIGN|SIGNS|ROAD|BLOCK|FOREST|NELSON|TASMAN|MARLBOROUGH|MOTUEKA|RICHMOND|BLENHEIM|ONEFORTYONE)\M)[A-Z]{4,}/[A-Z][a-z]+\M'
		) as identifies
	from regexp_split_to_table(p_text, '(?<=[.!?])\s*(?=[A-Z("]|$)') with ordinality as s(sentence, ord)
	where btrim(s.sentence) <> ''
),
marked as (
	select ord, sentence, identifies,
		coalesce(lag(identifies) over (order by ord), false) as previous_identifies,
		(
			select string_agg(m[1], ' ')
			from regexp_matches(sentence, '(\([^)]*(?:image|footage|photo|video)[^)]*\))', 'gi') as m
		) as capture_markers
	from sentences
)
select case
	when p_text is null then null
	when not exists (select 1 from sentences where identifies) then p_text
	else (
		select string_agg(
			case
				when not identifies then btrim(sentence)
				when previous_identifies then capture_markers
				else concat_ws(' ', 'R & M have identified a person relating to this.', capture_markers)
			end,
			' ' order by ord
		)
		from marked
	)
end
$function$;
COMMENT ON FUNCTION "public"."report_redact_identified_persons"(p_text text) IS 'Rewords sentences that name or give personal details of an identified person as "R & M have identified a person relating to this", keeping photo or footage capture markers. Used by the client site activity report.';
REVOKE ALL ON FUNCTION "public"."report_redact_identified_persons"(p_text text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."report_redact_identified_persons"(p_text text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."report_redact_identified_persons"(p_text text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."report_service_delivery_summary"(p_agreement_id uuid, p_from timestamp with time zone, p_to timestamp with time zone)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
with agreement as materialized (
  select id, provider_organization_id, client_organization_id
  from public.service_agreements where id = p_agreement_id
), links as materialized (
  select l.id, l.site_id, l.zone_id
  from public.service_agreement_locations l
  where l.service_agreement_id = p_agreement_id and l.status = 'active'
), contracted_shifts as materialized (
  select s.id from public.shifts s join agreement a on a.provider_organization_id = s.organization_id
  where (exists (
    select 1 from public.service_agreement_modules am
    where am.id = s.service_agreement_module_id and am.service_agreement_id = a.id
  ) or exists (
    select 1 from public.shift_stops st
    join public.shift_stop_modules m on m.shift_stop_id = st.id
    join public.service_agreement_modules am on am.id = m.service_agreement_module_id
    where st.shift_id = s.id and am.service_agreement_id = a.id
      and m.organization_id = a.provider_organization_id
  )) and not exists (
    select 1 from public.shift_stops st
    join public.shift_stop_modules m on m.shift_stop_id = st.id
    join public.service_agreement_modules am on am.id = m.service_agreement_module_id
    where st.shift_id = s.id and am.service_agreement_id <> a.id
  )
), field_scope as materialized (
  select distinct on (coalesce(r.client_event_id, r.id))
    r.id, r.client_event_id, r.status, r.reviewed_at, r.reviewed_by, r.investigation_id,
    array(
      select duplicate.id from public.officer_field_reports duplicate
      where duplicate.organization_id = r.organization_id and duplicate.report_type in ('incident', 'health_safety')
        and (duplicate.id = r.id or duplicate.client_event_id = r.client_event_id)
    ) as provenance_ids
  from public.officer_field_reports r
  join agreement a on a.provider_organization_id = r.organization_id
  where r.reported_at >= p_from and r.reported_at < p_to
    -- Health and safety reports are client site hazard checks (owner ruling
    -- 2026-11-06); maintenance reports stay in-house.
    and r.report_type in ('incident', 'health_safety')
    and exists (select 1 from links l where l.site_id = r.site_id or l.zone_id = r.zone_id)
    and (
      ((
        exists (
          select 1 from public.shifts s
          join public.service_agreement_modules am on am.id = s.service_agreement_module_id
          where s.id = r.shift_id and s.organization_id = a.provider_organization_id
            and am.service_agreement_id = a.id
        ) or exists (
          select 1 from public.shift_stops st
          join public.shift_stop_modules m on m.shift_stop_id = st.id
          join public.service_agreement_modules am on am.id = m.service_agreement_module_id
          where st.shift_id = r.shift_id and st.organization_id = a.provider_organization_id
            and m.organization_id = a.provider_organization_id and am.service_agreement_id = a.id
            and (st.site_id = r.site_id or st.zone_id = r.zone_id)
        )
      ) and not exists (
        select 1 from public.shift_stops st
        join public.shift_stop_modules m on m.shift_stop_id = st.id
        join public.service_agreement_modules am on am.id = m.service_agreement_module_id
        where st.shift_id = r.shift_id and am.service_agreement_id <> a.id
          and (st.site_id = r.site_id or st.zone_id = r.zone_id)
      ))
      or (r.shift_id is null and not exists (
        select 1 from public.service_agreement_locations other
        where other.status = 'active' and other.service_agreement_id <> a.id
          and (other.site_id = r.site_id or other.zone_id = r.zone_id)
      ))
    )
    and not exists (
      select 1 from public.incidents i
      where i.investigation_id = r.investigation_id and i.is_staff_sensitive
    )
  order by coalesce(r.client_event_id, r.id),
    (r.status in ('reviewed', 'closed') and r.reviewed_at is not null and r.reviewed_by is not null) desc,
    r.reported_at, r.id
), candidates as materialized (
  select 'reviewedReports'::text as kind, r.id, r.client_event_id,
    null::uuid as stop_id, r.investigation_id, r.provenance_ids
  from field_scope r
  where r.status in ('reviewed', 'closed') and r.reviewed_at is not null and r.reviewed_by is not null
  union all
  select 'completedDispatch', j.id, null::uuid, j.shift_stop_id, j.investigation_id, array[j.id]
  from public.dispatch_jobs j
  join agreement a on a.provider_organization_id = j.organization_id
  where j.status = 'completed' and j.completed_at >= p_from and j.completed_at < p_to
    and exists (select 1 from links l where l.site_id = j.client_site_id or l.zone_id = j.zone_id)
    and (j.service_agreement_id = a.id or (
      j.service_agreement_id is null and not exists (
        select 1 from public.service_agreement_locations other
        where other.status = 'active' and other.service_agreement_id <> a.id
          and (other.site_id = j.client_site_id or other.zone_id = j.zone_id)
      )
    ))
  union all
  select distinct 'completedStatic', st.id, null::uuid, st.id, null::uuid, array[st.id]
  from public.shift_stops st
  join agreement a on st.organization_id = a.provider_organization_id
  join public.shift_stop_modules m on m.shift_stop_id = st.id and m.organization_id = a.provider_organization_id
  join public.service_agreement_modules am on am.id = m.service_agreement_module_id and am.service_agreement_id = a.id
  join links l on l.id = m.service_agreement_location_id and (l.site_id = st.site_id or l.zone_id = st.zone_id)
  where m.module_key = 'static_guarding' and m.status = 'completed'
    and st.actual_departed_at >= p_from and st.actual_departed_at < p_to
    and exists (
      select 1 from public.shift_stop_actions act
      where act.shift_stop_module_id = m.id and act.organization_id = a.provider_organization_id
        and act.action_type = 'static_post_departed'
    )
), represented as (
  select c.*, exists (
    select 1 from public.location_events e
    join agreement a on e.organization_id in (a.provider_organization_id, a.client_organization_id)
    where e.occurred_at >= p_from and e.occurred_at < p_to
      and exists (select 1 from links l where l.site_id = e.client_site_id or l.zone_id = e.zone_id)
      and (
        (e.source in ('dispatch_job', 'dispatch_jobs') and c.kind = 'completedDispatch' and e.external_ref = c.id::text)
        or (e.source in ('officer_field_report', 'officer_field_reports') and c.kind = 'reviewedReports' and e.external_ref = any(c.provenance_ids::text[]))
        or (c.kind = 'completedDispatch' and e.payload ->> 'dispatch_job_id' = c.id::text)
        or (c.kind = 'reviewedReports' and e.payload ->> 'officer_field_report_id' = any(c.provenance_ids::text[]))
        or (c.kind = 'completedStatic' and e.payload ->> 'shift_stop_id' = c.stop_id::text)
        or (c.client_event_id is not null and e.payload ->> 'client_event_id' = c.client_event_id::text)
      )
  ) or exists (
    select 1 from public.observations o
    join agreement a on o.organization_id in (a.provider_organization_id, a.client_organization_id)
    where o.observed_at >= p_from and o.observed_at < p_to
      and exists (select 1 from links l where l.site_id = o.site_id or l.zone_id = o.zone_id)
      and (
        (c.kind = 'reviewedReports' and o.external_refs ->> 'officer_field_report_id' = any(c.provenance_ids::text[]))
        or (c.kind = 'completedDispatch' and o.external_refs ->> 'dispatch_job_id' = c.id::text)
        or (c.client_event_id is not null and o.external_refs ->> 'client_event_id' = c.client_event_id::text)
      )
  ) or exists (
    select 1 from public.incidents i
    join agreement a on i.organization_id in (a.provider_organization_id, a.client_organization_id)
    where i.occurred_at >= p_from and i.occurred_at < p_to and not i.is_staff_sensitive
      and exists (select 1 from links l where l.site_id = i.client_site_id or l.zone_id = i.zone_id)
      and c.kind = 'completedDispatch' and i.dispatch_job_id = c.id
  ) as in_activity
  from candidates c
), counts as (
  select kinds.kind, count(r.id) as recorded,
    count(r.id) filter (where r.in_activity) as represented
  from (values ('reviewedReports'), ('completedDispatch'), ('completedStatic')) kinds(kind)
  left join represented r on r.kind = kinds.kind group by kinds.kind
)
select jsonb_build_object(
  'client', jsonb_build_object(
    'version', 1,
    'counts', (select jsonb_object_agg(kind, jsonb_build_object(
      'recorded', recorded, 'alreadyInActivity', represented, 'additional', recorded - represented
    )) from counts)
  ),
  'internal', jsonb_build_object(
    'awaitingReview', (select count(*) from field_scope where status = 'submitted'),
    'handoversReceived', (
      select count(*) from public.shift_debriefs d join agreement a on d.organization_id = a.provider_organization_id
      where d.shift_id in (select id from contracted_shifts) and d.submitted_at >= p_from and d.submitted_at < p_to
    )
  )
);
$function$;
COMMENT ON FUNCTION "public"."report_service_delivery_summary"(p_agreement_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) IS 'Internal count-only service evidence: reviewed incident and site hazard (health and safety) reports, completed dispatch and static attendance, with provenance overlaps; private handover counts only in the provider projection. No free text or financial estimates.';
REVOKE ALL ON FUNCTION "public"."report_service_delivery_summary"(p_agreement_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."report_service_delivery_summary"(p_agreement_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."report_service_line"(p_value text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
	select case regexp_replace(lower(btrim(coalesce(p_value, ''))), '[\s_]+', ' ', 'g')
		when '' then null
		when 'security' then 'security'
		when 'pest control' then 'pest_control'
		when 'callout' then 'callout'
		when 'email' then 'email'
		when 'fire' then 'fire'
		else 'other'
	end;
$function$;
COMMENT ON FUNCTION "public"."report_service_line"(p_value text) IS 'Maps the spreadsheet source category (SECURITY, PEST CONTROL, CALLOUT, EMAIL, FIRE) to a code. Any other value becomes other so source text is never copied.';
REVOKE ALL ON FUNCTION "public"."report_service_line"(p_value text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."report_service_line"(p_value text) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."report_text_or_null"(p_value text, p_max_length integer)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
	select case
		when s.cleaned = '' then null
		when length(s.cleaned) > greatest(coalesce(p_max_length, 1), 2)
			then rtrim(left(s.cleaned, greatest(coalesce(p_max_length, 1), 2) - 1)) || '…'
		else s.cleaned
	end
	from (
		select btrim(regexp_replace(coalesce(p_value, ''), '[[:cntrl:][:space:]]+', ' ', 'g')) as cleaned
	) s;
$function$;
COMMENT ON FUNCTION "public"."report_text_or_null"(p_value text, p_max_length integer) IS 'Normalises a narrative written at a location (comment, action note, description) for a client report: control characters and runs of whitespace become one space, blank becomes null, and long text is capped with an ellipsis.';
REVOKE ALL ON FUNCTION "public"."report_text_or_null"(p_value text, p_max_length integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."report_text_or_null"(p_value text, p_max_length integer) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."request_anz_bank_connection"(p_bank_account_id uuid, p_connection_mode text DEFAULT 'approved_provider'::text, p_requested_scopes text[] DEFAULT ARRAY['account_transactions'::text, 'balances'::text, 'payment_matches'::text], p_consent_confirmed boolean DEFAULT false)
 RETURNS finance_external_connection_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid(); v_org uuid; v_account public.bank_accounts%rowtype; v_request public.finance_external_connection_requests%rowtype;
BEGIN
  SELECT organization_id INTO v_org FROM public.user_profiles WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_org IS NULL OR NOT public.is_admin_for_org(v_org) THEN RAISE EXCEPTION 'Active finance administrator required'; END IF;
  IF p_connection_mode NOT IN ('oauth','approved_provider','secure_file_import','manual_review') THEN RAISE EXCEPTION 'Unsupported ANZ connection method'; END IF;
  IF NOT p_consent_confirmed THEN RAISE EXCEPTION 'ANZ connection consent is required'; END IF;
  SELECT * INTO v_account FROM public.bank_accounts WHERE id = p_bank_account_id AND organization_id = v_org AND is_active AND bank_name ILIKE '%ANZ%';
  IF NOT FOUND THEN RAISE EXCEPTION 'Select an active ANZ bank account'; END IF;
  INSERT INTO public.finance_external_connection_requests(organization_id, provider_type, provider_name, connection_mode, requested_scopes, bank_account_id, consent_confirmed, consent_confirmed_by, consent_confirmed_at, status, setup_summary, created_by)
  VALUES (v_org, 'bank', 'ANZ', p_connection_mode, COALESCE(p_requested_scopes, ARRAY['account_transactions','balances','payment_matches']), p_bank_account_id, true, v_actor, now(), 'awaiting_authorisation', jsonb_build_object('bank', 'ANZ', 'credentials_collected', false, 'human_approval_required', true, 'data_minimised', true, 'adapter_required', 'approved ANZ/Open Banking provider'), v_actor)
  ON CONFLICT (organization_id, provider_type, bank_account_id) DO UPDATE SET provider_name = 'ANZ', connection_mode = EXCLUDED.connection_mode, requested_scopes = EXCLUDED.requested_scopes, consent_confirmed = true, consent_confirmed_by = EXCLUDED.consent_confirmed_by, consent_confirmed_at = now(), status = CASE WHEN finance_external_connection_requests.status = 'connected' THEN finance_external_connection_requests.status ELSE 'awaiting_authorisation' END, setup_summary = EXCLUDED.setup_summary, updated_at = now()
  RETURNING * INTO v_request;
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata) VALUES (v_org, v_actor, 'anz_bank_connection_requested', 'finance_external_connection_requests', v_request.id, jsonb_build_object('provider_name', 'ANZ', 'bank_account_id', p_bank_account_id, 'credentials_collected', false));
  RETURN v_request;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."request_anz_bank_connection"(p_bank_account_id uuid, p_connection_mode text, p_requested_scopes text[], p_consent_confirmed boolean) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."request_anz_bank_connection"(p_bank_account_id uuid, p_connection_mode text, p_requested_scopes text[], p_consent_confirmed boolean) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."request_anz_bank_connection"(p_bank_account_id uuid, p_connection_mode text, p_requested_scopes text[], p_consent_confirmed boolean) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."request_anz_bank_connection"(p_bank_account_id uuid, p_connection_mode text, p_requested_scopes text[], p_consent_confirmed boolean) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."request_bob_document_output"(p_document_id uuid, p_document_version_id uuid, p_output_format text)
 RETURNS bob_generated_document_outputs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org_id uuid;
  v_status text;
  v_output public.bob_generated_document_outputs;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_output_format NOT IN ('pdf', 'docx', 'print') THEN RAISE EXCEPTION 'Unsupported output format'; END IF;

  SELECT d.organization_id, coalesce(dv.metadata_json->>'authoring_status', '')
  INTO v_org_id, v_status
  FROM public.documents d JOIN public.document_versions dv ON dv.document_id = d.id
  WHERE d.id = p_document_id AND dv.id = p_document_version_id;
  IF v_org_id IS NULL THEN RAISE EXCEPTION 'Document version not found'; END IF;
  IF NOT public.is_admin_for_org(v_org_id) AND NOT public.is_grand_master() THEN RAISE EXCEPTION 'Document output request denied'; END IF;
  IF v_status <> 'approved' THEN RAISE EXCEPTION 'Only approved document versions can produce outputs'; END IF;

  INSERT INTO public.bob_generated_document_outputs (
    organization_id, document_id, document_version_id, output_format, requested_by, approved_by, approved_at
  ) VALUES (v_org_id, p_document_id, p_document_version_id, p_output_format, v_actor, v_actor, clock_timestamp())
  RETURNING * INTO v_output;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_org_id, v_actor, 'bob_document_output_requested', 'bob_generated_document_outputs', v_output.id,
    jsonb_build_object('document_id', p_document_id, 'document_version_id', p_document_version_id, 'output_format', p_output_format));
  RETURN v_output;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."request_bob_document_output"(p_document_id uuid, p_document_version_id uuid, p_output_format text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."request_bob_document_output"(p_document_id uuid, p_document_version_id uuid, p_output_format text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."request_bob_document_output"(p_document_id uuid, p_document_version_id uuid, p_output_format text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."request_bob_document_output"(p_document_id uuid, p_document_version_id uuid, p_output_format text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."request_document_source_ingestion"(p_source_id uuid, p_client_request_id uuid, p_mode text DEFAULT 'inventory'::text)
 RETURNS document_source_ingestion_runs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor uuid := (SELECT auth.uid());
  v_source public.document_reference_sources%ROWTYPE;
  v_run public.document_source_ingestion_runs%ROWTYPE;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  IF p_client_request_id IS NULL THEN
    RAISE EXCEPTION 'client_request_id is required';
  END IF;
  IF p_mode <> 'inventory' THEN
    RAISE EXCEPTION 'Only read-only inventory is available';
  END IF;

  SELECT * INTO v_source
  FROM public.document_reference_sources
  WHERE id = p_source_id
    AND source_kind = 'local_folder'
    AND approval_status = 'approved'
    AND is_active
  FOR UPDATE;

  IF NOT FOUND OR v_source.organization_id IS NULL THEN
    RAISE EXCEPTION 'Approved tenant local-folder source not found';
  END IF;
  IF NOT (public.is_admin_for_org(v_source.organization_id) OR public.is_grand_master()) THEN
    RAISE EXCEPTION 'Not authorized for this document source';
  END IF;

  SELECT * INTO v_run
  FROM public.document_source_ingestion_runs
  WHERE source_id = v_source.id
    AND status IN ('queued', 'running', 'cancel_requested')
  ORDER BY requested_at
  LIMIT 1;

  IF FOUND THEN
    RETURN v_run;
  END IF;

  INSERT INTO public.document_source_ingestion_runs (
    organization_id,
    source_id,
    requested_by,
    client_request_id,
    mode
  )
  VALUES (
    v_source.organization_id,
    v_source.id,
    v_actor,
    p_client_request_id,
    p_mode
  )
  ON CONFLICT (organization_id, requested_by, client_request_id)
  DO UPDATE SET client_request_id = EXCLUDED.client_request_id
  RETURNING * INTO v_run;

  INSERT INTO public.document_source_run_events (
    organization_id,
    run_id,
    event_type,
    phase,
    message_redacted
  )
  VALUES (
    v_run.organization_id,
    v_run.id,
    'inventory_requested',
    v_run.phase,
    'Read-only source inventory requested.'
  )
  ON CONFLICT (run_id, event_type)
    WHERE event_type = 'inventory_requested'
  DO NOTHING;

  RETURN v_run;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."request_document_source_ingestion"(p_source_id uuid, p_client_request_id uuid, p_mode text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."request_document_source_ingestion"(p_source_id uuid, p_client_request_id uuid, p_mode text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."request_document_source_ingestion"(p_source_id uuid, p_client_request_id uuid, p_mode text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."request_finance_external_connection"(p_provider_type text, p_connection_mode text, p_requested_scopes text[] DEFAULT '{}'::text[], p_bank_account_id uuid DEFAULT NULL::uuid, p_consent_confirmed boolean DEFAULT false)
 RETURNS finance_external_connection_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid(); v_org uuid; v_request public.finance_external_connection_requests%rowtype; v_account public.bank_accounts%rowtype;
BEGIN
  SELECT organization_id INTO v_org FROM public.user_profiles WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_org IS NULL OR NOT public.is_admin_for_org(v_org) THEN RAISE EXCEPTION 'Active finance administrator required'; END IF;
  IF p_provider_type NOT IN ('ird','bank') THEN RAISE EXCEPTION 'Unsupported finance connection'; END IF;
  IF p_connection_mode NOT IN ('oauth','approved_provider','secure_file_import','manual_review') THEN RAISE EXCEPTION 'Unsupported connection method'; END IF;
  IF p_provider_type = 'bank' AND p_bank_account_id IS NULL THEN RAISE EXCEPTION 'Select the bank account to connect'; END IF;
  IF p_provider_type = 'bank' THEN
    SELECT * INTO v_account FROM public.bank_accounts WHERE id = p_bank_account_id AND organization_id = v_org AND is_active;
    IF NOT FOUND THEN RAISE EXCEPTION 'Active bank account not found in organization'; END IF;
  END IF;
  IF NOT p_consent_confirmed THEN RAISE EXCEPTION 'Connection consent is required'; END IF;
  INSERT INTO public.finance_external_connection_requests(organization_id, provider_type, connection_mode, requested_scopes, bank_account_id, consent_confirmed, consent_confirmed_by, consent_confirmed_at, status, setup_summary, created_by)
  VALUES (v_org, p_provider_type, p_connection_mode, COALESCE(p_requested_scopes, '{}'), p_bank_account_id, true, v_actor, now(), 'awaiting_authorisation', jsonb_build_object('credentials_collected', false, 'human_approval_required', true, 'data_minimised', true, 'next_action', CASE WHEN p_provider_type = 'ird' THEN 'Complete the approved IRD/provider authorization window' ELSE 'Complete the approved bank-provider authorization window' END), v_actor)
  ON CONFLICT (organization_id, provider_type, bank_account_id) DO UPDATE SET connection_mode = EXCLUDED.connection_mode, requested_scopes = EXCLUDED.requested_scopes, consent_confirmed = true, consent_confirmed_by = EXCLUDED.consent_confirmed_by, consent_confirmed_at = now(), status = CASE WHEN finance_external_connection_requests.status = 'connected' THEN finance_external_connection_requests.status ELSE 'awaiting_authorisation' END, setup_summary = EXCLUDED.setup_summary, updated_at = now()
  RETURNING * INTO v_request;
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata) VALUES (v_org, v_actor, 'finance_external_connection_requested', 'finance_external_connection_requests', v_request.id, jsonb_build_object('provider_type', p_provider_type, 'connection_mode', p_connection_mode, 'requested_scopes', p_requested_scopes, 'credentials_collected', false));
  RETURN v_request;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."request_finance_external_connection"(p_provider_type text, p_connection_mode text, p_requested_scopes text[], p_bank_account_id uuid, p_consent_confirmed boolean) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."request_finance_external_connection"(p_provider_type text, p_connection_mode text, p_requested_scopes text[], p_bank_account_id uuid, p_consent_confirmed boolean) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."request_finance_external_connection"(p_provider_type text, p_connection_mode text, p_requested_scopes text[], p_bank_account_id uuid, p_consent_confirmed boolean) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."request_finance_external_connection"(p_provider_type text, p_connection_mode text, p_requested_scopes text[], p_bank_account_id uuid, p_consent_confirmed boolean) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."request_shift_swap"(p_client_request_id uuid, p_shift_id uuid, p_swap_with_staff_id uuid DEFAULT NULL::uuid, p_swap_type text DEFAULT 'open'::text, p_reason text DEFAULT NULL::text)
 RETURNS shift_swaps
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid(); v_shift public.shifts%rowtype; v_original_staff public.staff_profiles%rowtype; v_replacement public.staff_profiles%rowtype; v_swap public.shift_swaps%rowtype; v_reason text := nullif(trim(coalesce(p_reason, '')), '');
begin
  if v_actor is null then raise exception 'Authentication required'; end if;
  if p_client_request_id is null then raise exception 'client_request_id is required'; end if;
  if p_swap_type not in ('open', 'direct', 'coverage_request') then raise exception 'Unsupported shift swap type'; end if;
  if v_reason is null then raise exception 'A reason is required for a shift swap request'; end if;
  select s.* into v_shift from public.shifts s where s.id = p_shift_id for update;
  if not found then raise exception 'Shift not found'; end if;
  if v_shift.officer_user_id <> v_actor then raise exception 'Only the assigned officer can request a swap'; end if;
  if v_shift.status not in ('scheduled', 'published', 'accepted') then raise exception 'Only unstarted shifts can be swapped'; end if;
  select sp.* into v_original_staff from public.staff_profiles sp where sp.organization_id = v_shift.organization_id and (sp.user_id = v_actor or sp.id = v_actor) and sp.work_ready;
  if not found then raise exception 'Active work-ready staff profile required'; end if;
  if p_swap_with_staff_id is not null then
    if p_swap_type <> 'direct' then raise exception 'A replacement officer requires a direct swap'; end if;
    select sp.* into v_replacement from public.staff_profiles sp where sp.id = p_swap_with_staff_id and sp.organization_id = v_shift.organization_id and sp.work_ready;
    if not found or v_replacement.id = v_original_staff.id then raise exception 'Replacement officer is not eligible'; end if;
    if exists (select 1 from public.roster_slots rs where rs.staff_id = v_replacement.id and rs.status not in ('declined', 'cancelled') and rs.scheduled_start < v_shift.scheduled_end and rs.scheduled_end > v_shift.scheduled_start) then raise exception 'Replacement officer has an overlapping roster assignment'; end if;
  end if;
  select sw.* into v_swap from public.shift_swaps sw where sw.organization_id = v_shift.organization_id and sw.original_shift_id = v_shift.id and sw.status = 'pending' order by sw.created_at desc limit 1;
  if found then return v_swap; end if;
  insert into public.shift_swaps (organization_id, original_shift_id, original_staff_id, swap_with_staff_id, swap_type, reason, status, requested_by, requested_at) values (v_shift.organization_id, v_shift.id, v_original_staff.id, p_swap_with_staff_id, p_swap_type, v_reason, 'pending', v_actor, clock_timestamp()) returning * into v_swap;
  insert into public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata) values (v_shift.organization_id, v_actor, 'shift_swap_requested', 'shift_swaps', v_swap.id, jsonb_build_object('shift_id', v_shift.id, 'swap_type', p_swap_type, 'replacement_staff_id', p_swap_with_staff_id, 'reason', v_reason, 'client_request_id', p_client_request_id));
  if p_swap_with_staff_id is not null and v_replacement.user_id is not null then perform public.enqueue_notification(v_shift.organization_id, 'roster', 'Direct shift swap requested', 'An officer has requested you take a rostered shift. Await roster approval.', 'warning', v_replacement.user_id, null, 'schedule', jsonb_build_object('shift_swap_id', v_swap.id, 'shift_id', v_shift.id), 'shift_swap_requested:' || v_swap.id::text); end if;
  return v_swap;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."request_shift_swap"(p_client_request_id uuid, p_shift_id uuid, p_swap_with_staff_id uuid, p_swap_type text, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."request_shift_swap"(p_client_request_id uuid, p_shift_id uuid, p_swap_with_staff_id uuid, p_swap_type text, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."request_shift_swap"(p_client_request_id uuid, p_shift_id uuid, p_swap_with_staff_id uuid, p_swap_type text, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."request_shift_swap"(p_client_request_id uuid, p_shift_id uuid, p_swap_with_staff_id uuid, p_swap_type text, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."require_shift_safety_acknowledgement"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_briefing jsonb;
BEGIN
  IF NEW.status = 'in_progress' AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM 'in_progress') THEN
    v_briefing := public.build_shift_safety_briefing(NEW.id, NULL);
    IF (v_briefing->>'item_count')::integer > 0 AND NOT EXISTS (
      SELECT 1 FROM public.safety_briefing_acknowledgements a
      WHERE a.shift_id = NEW.id AND a.officer_user_id = NEW.officer_user_id
        AND a.shift_stop_id IS NULL AND a.briefing_hash = v_briefing->>'briefing_hash'
    ) THEN
      RAISE EXCEPTION 'The assigned officer must read and acknowledge the current site risks before starting this shift.'
        USING ERRCODE = 'P0001', HINT = 'safety_briefing_required';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;
COMMENT ON FUNCTION "public"."require_shift_safety_acknowledgement"() IS 'Starting a shift with recorded hazards requires the assigned officer''s current whole-shift acknowledgement, including direct inserts and admin-initiated starts. No silent client bypass.';
REVOKE ALL ON FUNCTION "public"."require_shift_safety_acknowledgement"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."require_shift_safety_acknowledgement"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."require_shift_safety_acknowledgement"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."require_stop_safety_acknowledgement"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_briefing jsonb; v_officer uuid;
BEGIN
  IF NEW.status = 'on_scene' AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM 'on_scene') THEN
    SELECT officer_user_id INTO v_officer FROM public.shifts WHERE id = NEW.shift_id;
    v_briefing := public.build_shift_safety_briefing(NEW.shift_id, NEW.id);
    IF (v_briefing->>'item_count')::integer > 0 AND NOT EXISTS (
      SELECT 1 FROM public.safety_briefing_acknowledgements a
      WHERE a.shift_id = NEW.shift_id AND a.officer_user_id = v_officer
        AND a.shift_stop_id = NEW.id AND a.briefing_hash = v_briefing->>'briefing_hash'
    ) THEN
      RAISE EXCEPTION 'Read and acknowledge the current risks for this stop before recording arrival.'
        USING ERRCODE = 'P0001', HINT = 'safety_briefing_required';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."require_stop_safety_acknowledgement"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."require_stop_safety_acknowledgement"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."require_stop_safety_acknowledgement"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."reserve_infringement_notice_number"(p_organization_id uuid, p_module_key text, p_prefix text DEFAULT 'INF'::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_sequence integer;
  v_prefix text := coalesce(nullif(trim(p_prefix), ''), 'INF');
BEGIN
  IF v_actor IS NULL OR NOT public.org_access_allowed(p_organization_id) THEN
    RAISE EXCEPTION 'Organization access required';
  END IF;
  INSERT INTO public.infringement_notice_counters (organization_id, module_key, last_number, prefix)
  VALUES (p_organization_id, p_module_key, 1, v_prefix)
  ON CONFLICT (organization_id, module_key)
  DO UPDATE SET last_number = infringement_notice_counters.last_number + 1,
                updated_at = now()
  RETURNING last_number, prefix INTO v_sequence, v_prefix;
  RETURN format('%s-%s-%s', v_prefix, to_char(current_date, 'YYYYMMDD'), lpad(v_sequence::text, 4, '0'));
END;
$function$;
REVOKE ALL ON FUNCTION "public"."reserve_infringement_notice_number"(p_organization_id uuid, p_module_key text, p_prefix text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."reserve_infringement_notice_number"(p_organization_id uuid, p_module_key text, p_prefix text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."reserve_infringement_notice_number"(p_organization_id uuid, p_module_key text, p_prefix text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."reserve_infringement_notice_number"(p_organization_id uuid, p_module_key text, p_prefix text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."resolve_access_basis"(p_user uuid DEFAULT auth.uid(), p_observation_id uuid DEFAULT NULL::uuid, p_noise_assessment_id uuid DEFAULT NULL::uuid, p_smoke_assessment_id uuid DEFAULT NULL::uuid, p_biosecurity_assessment_id uuid DEFAULT NULL::uuid, p_incident_id uuid DEFAULT NULL::uuid, p_notice_id uuid DEFAULT NULL::uuid, p_enforcement_case_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_ref_count      int;
  v_caller         uuid := auth.uid();
  v_basis          text := null;
  v_expiry         text := null;
begin
  -- ========================================================
  -- 0329 IDENTITY GUARD (SELF-ONLY). Server-derived caller; reject any request
  -- to resolve someone else's basis. This is the ONLY change from the 0327
  -- body; every basis branch below is reproduced verbatim.
  --
  -- p_user defaults to auth.uid() (UI sends no id). If a caller explicitly
  -- passes a p_user that is not themselves, or is unauthenticated, resolve to
  -- NO basis -- an informative, content-free statement (reject by
  -- non-appearance, never an error that would itself confirm anything).
  -- ========================================================
  if v_caller is null or p_user is null or p_user <> v_caller then
    return jsonb_build_object(
      'decision_state',       'no_task_entitlement',
      'granted_basis',        null,
      'failed_gate',          'task',
      'expiry_end_condition', null,
      'sensitivity_mode',     'informative',
      'message_key',          'access.no_live_basis'
    );
  end if;

  -- COMPOSITION CONTRACT (ACCESS_MODEL.md section 7): this resolver returns on
  -- the FIRST basis found, and the branch order below IS the composition rule -
  -- strongest depth first (ownership -> dispatch on-scene -> dispatch en-route
  -- -> roster -> supervisory), so "first match" == "maximum depth". This
  -- ordering is LOAD-BEARING: do not reorder without switching to an explicit
  -- resolve-all-then-take-max-depth form, or a weaker basis could shadow a
  -- stronger one and under-grant (a lockout).
  -- Exactly-one-record guard (mirrors task_assignments chk_one_record).
  v_ref_count :=
      (case when p_observation_id            is not null then 1 else 0 end)
    + (case when p_noise_assessment_id       is not null then 1 else 0 end)
    + (case when p_smoke_assessment_id       is not null then 1 else 0 end)
    + (case when p_biosecurity_assessment_id is not null then 1 else 0 end)
    + (case when p_incident_id               is not null then 1 else 0 end)
    + (case when p_notice_id                 is not null then 1 else 0 end)
    + (case when p_enforcement_case_id       is not null then 1 else 0 end);

  if v_ref_count <> 1 then
    -- Malformed call: no basis. (section 0: absent basis, not a verdict.)
    return jsonb_build_object(
      'decision_state',       'no_task_entitlement',
      'granted_basis',        null,
      'failed_gate',          'task',
      'expiry_end_condition', null,
      'sensitivity_mode',     'informative',
      'message_key',          'access.no_live_basis'
    );
  end if;

  -- ========================================================
  -- OWNERSHIP-DERIVED bases (task_assignments 0323; geofence NOT required).
  -- follow_up_ownership + direct_module_initiation resolve FULL depth.
  -- A live row with ended_at IS NULL is a LIVE basis.
  -- ========================================================
  select ta.basis,
         'basis_ends: ' || coalesce(ta.end_reason, 'live until ended_at set')
    into v_basis, v_expiry
  from public.task_assignments ta
  where ta.user_id = p_user
    and ta.ended_at is null
    and (
         (p_observation_id            is not null and ta.observation_id            = p_observation_id)
      or (p_noise_assessment_id       is not null and ta.noise_assessment_id       = p_noise_assessment_id)
      or (p_smoke_assessment_id       is not null and ta.smoke_assessment_id       = p_smoke_assessment_id)
      or (p_biosecurity_assessment_id is not null and ta.biosecurity_assessment_id = p_biosecurity_assessment_id)
      or (p_incident_id               is not null and ta.incident_id               = p_incident_id)
      or (p_notice_id                 is not null and ta.notice_id                 = p_notice_id)
      or (p_enforcement_case_id       is not null and ta.enforcement_case_id       = p_enforcement_case_id)
    )
    -- Prefer the strongest ownership basis first (follow_up/initiation = full;
    -- backup graduates and is handled in the presence block for its depth).
    order by case ta.basis
               when 'follow_up_ownership'       then 1
               when 'direct_module_initiation'  then 2
               when 'backup_attachment'         then 3
               else 4 end
    limit 1;

  if v_basis in ('follow_up_ownership', 'direct_module_initiation') then
    -- Ownership-derived: FULL working depth (section 3: geofence may be false;
    -- report writing / QA / handover must not break). S12 no-lockout case.
    return jsonb_build_object(
      'decision_state',       'full_access',
      'granted_basis',        v_basis,
      'failed_gate',          'none',
      'expiry_end_condition', v_expiry,
      'sensitivity_mode',     'informative',
      'message_key',          'access.granted.' || v_basis
    );
  elsif v_basis = 'backup_attachment' then
    -- R1: backup graduates. Without a live-geofence gate in v1, the task record
    -- itself is the presence proof; a live backup attachment earns operational
    -- depth (on-scene upgrade is a v-next hardening, ACCESS_MODEL section 3).
    return jsonb_build_object(
      'decision_state',       'operational_only',
      'granted_basis',        'backup_attachment',
      'failed_gate',          'none',
      'expiry_end_condition', v_expiry,
      'sensitivity_mode',     'informative',
      'message_key',          'access.granted.backup_attachment'
    );
  end if;

  -- ========================================================
  -- PRESENCE-DERIVED: dispatch_response (TIMESTAMP-LED graduation, S3/S13).
  -- Officer link: dispatch_jobs.dispatch_resource_id
  --   -> dispatch_resources.assigned_officer_id (live-verified path).
  -- Depth: dispatched_at set -> operational_only (en route);
  --        on_scene_at set   -> full_access (arrived).
  -- 0327 PLACE-LINK (Bug 2 fix): the dispatch job must be for the SAME SITE as
  -- the observation -- dj.client_site_id = o.site_id (the only place pair
  -- anchored in the live schema at both ends). FAIL-CLOSED: an observation with
  -- no site_id gets no dispatch basis (the join cannot match a null).
  -- ========================================================
  if p_observation_id is not null then
    perform 1
      from public.dispatch_jobs dj
      join public.dispatch_resources dr on dr.id = dj.dispatch_resource_id
      join public.observations o on o.id = p_observation_id
     where dr.assigned_officer_id = p_user
       and dj.dispatched_at is not null
       and dj.completed_at is null
       and dj.on_scene_at is not null
       and o.site_id is not null
       and dj.client_site_id = o.site_id;
    if found then
      return jsonb_build_object(
        'decision_state',       'full_access',
        'granted_basis',        'dispatch_response',
        'failed_gate',          'none',
        'expiry_end_condition', 'basis_ends: dispatch completed_at set, reassignment, or 24h grace (Q1)',
        'sensitivity_mode',     'informative',
        'message_key',          'access.granted.dispatch_response.on_scene'
      );
    end if;

    perform 1
      from public.dispatch_jobs dj
      join public.dispatch_resources dr on dr.id = dj.dispatch_resource_id
      join public.observations o on o.id = p_observation_id
     where dr.assigned_officer_id = p_user
       and dj.dispatched_at is not null
       and dj.completed_at is null
       and o.site_id is not null
       and dj.client_site_id = o.site_id;
    if found then
      -- En route (dispatched, not yet on-scene): operational_only (S13/S3).
      return jsonb_build_object(
        'decision_state',       'operational_only',
        'granted_basis',        'dispatch_response',
        'failed_gate',          'none',
        'expiry_end_condition', 'basis_ends: dispatch completed_at set, reassignment, or 24h grace (Q1)',
        'sensitivity_mode',     'informative',
        'message_key',          'access.granted.dispatch_response.en_route'
      );
    end if;
  end if;

  -- ========================================================
  -- PRESENCE-DERIVED: rostered_presence.
  -- Officer link: shift_stops JOIN shifts (shifts.officer_user_id) - shift_stops
  -- has NO direct officer column (live-verified; the substrate-note trap).
  -- Live presence = a non-terminal stop (status not in the done set).
  -- Depth: presence-alone caps at operational_only (section 7 composition, S11).
  -- v1: the roster record is the presence proof (geofence deferred).
  -- ========================================================
  if p_observation_id is not null then
    perform 1
      from public.shift_stops ss
      join public.shifts s on s.id = ss.shift_id
      join public.observations o on o.id = p_observation_id
     where s.officer_user_id = p_user
       and ss.status not in ('completed', 'skipped', 'cancelled')
       and (
              (ss.site_id is not null and ss.site_id = o.site_id)
           or (ss.zone_id is not null and ss.zone_id = o.zone_id)
       );
    if found then
      -- S11: inside the tasked place, presence basis -> operational_only, NEVER
      -- narrative history from presence alone.
      return jsonb_build_object(
        'decision_state',       'operational_only',
        'granted_basis',        'rostered_presence',
        'failed_gate',          'none',
        'expiry_end_condition', 'basis_ends: stop completed/skipped/cancelled or shift end',
        'sensitivity_mode',     'informative',
        'message_key',          'access.granted.rostered_presence'
      );
    end if;
  end if;

  -- ========================================================
  -- PRESENCE/RESPONSIBILITY: supervisory_review (R2 scoped default).
  -- staff_reporting: this user is the reports_to for an officer who holds a live
  -- task basis on THIS record; active line = effective_to IS NULL.
  -- Default depth (sensitive subject-matter): operational_only (R2). The
  -- officer-SAFETY inversion (full_access) is NOT auto-resolved here - it is a
  -- named, record-bound escalation basis (R2 exception / S10), reserved for the
  -- welfare/duress path, never a broad supervisor read.
  -- ========================================================
  perform 1
    from public.staff_reporting sr
    join public.task_assignments ta on ta.user_id = sr.user_id and ta.ended_at is null
   where sr.reports_to_user_id = p_user
     and sr.effective_to is null
     and (
           (p_observation_id            is not null and ta.observation_id            = p_observation_id)
        or (p_noise_assessment_id       is not null and ta.noise_assessment_id       = p_noise_assessment_id)
        or (p_smoke_assessment_id       is not null and ta.smoke_assessment_id       = p_smoke_assessment_id)
        or (p_biosecurity_assessment_id is not null and ta.biosecurity_assessment_id = p_biosecurity_assessment_id)
        or (p_incident_id               is not null and ta.incident_id               = p_incident_id)
        or (p_notice_id                 is not null and ta.notice_id                 = p_notice_id)
        or (p_enforcement_case_id       is not null and ta.enforcement_case_id       = p_enforcement_case_id)
     );
  if found then
    return jsonb_build_object(
      'decision_state',       'operational_only',
      'granted_basis',        'supervisory_review',
      'failed_gate',          'none',
      'expiry_end_condition', 'basis_ends: reporting responsibility ends or supervised task ends (R2)',
      'sensitivity_mode',     'informative',
      'message_key',          'access.granted.supervisory_review'
    );
  end if;

  -- ========================================================
  -- No live task basis found. section 0: this is ABSENT BASIS, not a verdict on
  -- the reader. operator_custody + lawful_production are SEPARATE named bases,
  -- resolved elsewhere (R3) - deliberately NOT granted here.
  -- ========================================================
  return jsonb_build_object(
    'decision_state',       'no_task_entitlement',
    'granted_basis',        null,
    'failed_gate',          'task',
    'expiry_end_condition', null,
    'sensitivity_mode',     'informative',
    'message_key',          'access.no_live_basis'
  );
end;
$function$;
COMMENT ON FUNCTION "public"."resolve_access_basis"(p_user uuid, p_observation_id uuid, p_noise_assessment_id uuid, p_smoke_assessment_id uuid, p_biosecurity_assessment_id uuid, p_incident_id uuid, p_notice_id uuid, p_enforcement_case_id uuid) IS 'BASIS ENGINE (ACCESS_MODEL.md sections 8/11). SECURITY DEFINER + fixed search_path (0326). 0327: dispatch branch SITE-ANCHORED. 0329: SELF-ONLY - p_user defaults to auth.uid() and any p_user <> auth.uid() (or unauthenticated) resolves to no-basis. Closes the caller-supplied-identity impersonation surface on the direct-RPC / UI path. No supervisor/GM cross-user carve-out (separate privileged path if ever needed). Narrow contract: one SELF user, one record, verdict only.';
REVOKE ALL ON FUNCTION "public"."resolve_access_basis"(p_user uuid, p_observation_id uuid, p_noise_assessment_id uuid, p_smoke_assessment_id uuid, p_biosecurity_assessment_id uuid, p_incident_id uuid, p_notice_id uuid, p_enforcement_case_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."resolve_access_basis"(p_user uuid, p_observation_id uuid, p_noise_assessment_id uuid, p_smoke_assessment_id uuid, p_biosecurity_assessment_id uuid, p_incident_id uuid, p_notice_id uuid, p_enforcement_case_id uuid) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."resolve_access_basis"(p_user uuid, p_observation_id uuid, p_noise_assessment_id uuid, p_smoke_assessment_id uuid, p_biosecurity_assessment_id uuid, p_incident_id uuid, p_notice_id uuid, p_enforcement_case_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."resolve_access_basis"(p_user uuid, p_observation_id uuid, p_noise_assessment_id uuid, p_smoke_assessment_id uuid, p_biosecurity_assessment_id uuid, p_incident_id uuid, p_notice_id uuid, p_enforcement_case_id uuid) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."resolve_access_basis"(p_user uuid, p_observation_id uuid, p_noise_assessment_id uuid, p_smoke_assessment_id uuid, p_biosecurity_assessment_id uuid, p_incident_id uuid, p_notice_id uuid, p_enforcement_case_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."resolve_access_basis"(p_user uuid, p_observation_id uuid, p_noise_assessment_id uuid, p_smoke_assessment_id uuid, p_biosecurity_assessment_id uuid, p_incident_id uuid, p_notice_id uuid, p_enforcement_case_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."resolve_access_basis_batch"(p_observation_ids uuid[])
 RETURNS SETOF access_basis_verdict
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_caller uuid := auth.uid();
  v_count  int  := coalesce(array_length(p_observation_ids, 1), 0);
begin
  -- ========================================================
  -- INPUT CAP: hard cap of 200 ids per call. Over-cap -> reject the whole
  -- call. Do NOT silently truncate. Prevents the batch becoming a
  -- bulk-enumeration primitive.
  -- ========================================================
  if v_count > 200 then
    raise exception 'resolve_access_basis_batch: input cap exceeded (% ids, max 200)', v_count;
  end if;

  -- ========================================================
  -- SELF-ONLY: unauthenticated caller -> every id gets the collapsed
  -- no-basis verdict. There is NO p_user parameter at all; the caller
  -- identity is derived server-side from auth.uid() only.
  -- ========================================================
  if v_caller is null then
    return query
      select
        req.id,
        'no_task_entitlement'::text,
        null::text,
        'task'::text,
        null::text,
        'informative'::text,
        'access.no_live_basis'::text
      from unnest(p_observation_ids) as req(id);
    return;
  end if;

  -- ========================================================
  -- BATCHED BASIS DERIVATION
  -- Mirrors 0329 branches and ordering per id, applied set-wise.
  -- Composition order (first-match-by-depth, strongest first):
  --   1. ownership (follow_up_ownership / direct_module_initiation) -> full
  --   2. backup_attachment -> operational_only
  --   3. dispatch on-scene -> full_access
  --   4. dispatch en-route -> operational_only
  --   5. rostered_presence -> operational_only
  --   6. supervisory_review -> operational_only
  --
  -- The CTE chain resolves ALL matching bases per id, ranks them by the
  -- same depth ordering as 0329, and picks the strongest (first match).
  -- Any requested id with no match gets the collapsed no-basis verdict
  -- via LEFT JOIN against the input array (EXISTENCE COLLAPSE).
  -- ========================================================
  return query
  with
    -- Unnest the input array into a relation for joining.
    requested as (
      select unnest(p_observation_ids) as obs_id
    ),

    -- BRANCH 1: ownership-derived bases (task_assignments).
    -- follow_up_ownership / direct_module_initiation -> full_access (depth 1,2)
    -- backup_attachment -> operational_only (depth 3)
    -- Mirrors 0329 ownership block verbatim.
    ownership as (
      select distinct on (ta.observation_id)
        ta.observation_id as obs_id,
        ta.basis,
        'basis_ends: ' || coalesce(ta.end_reason, 'live until ended_at set') as expiry
      from public.task_assignments ta
      join requested r on r.obs_id = ta.observation_id
      where ta.user_id = v_caller
        and ta.ended_at is null
        and ta.observation_id is not null
      order by ta.observation_id,
        case ta.basis
          when 'follow_up_ownership'      then 1
          when 'direct_module_initiation' then 2
          when 'backup_attachment'        then 3
          else 4
        end
    ),

    -- BRANCH 2: dispatch on-scene (full_access).
    -- 0327 site-anchored: dj.client_site_id = o.site_id.
    -- Mirrors 0329 dispatch on-scene block verbatim.
    dispatch_on_scene as (
      select distinct on (o.id)
        o.id as obs_id
      from public.observations o
      join requested r on r.obs_id = o.id
      join public.dispatch_jobs dj on dj.client_site_id = o.site_id
      join public.dispatch_resources dr on dr.id = dj.dispatch_resource_id
      where dr.assigned_officer_id = v_caller
        and dj.dispatched_at is not null
        and dj.completed_at is null
        and dj.on_scene_at is not null
        and o.site_id is not null
    ),

    -- BRANCH 3: dispatch en-route (operational_only).
    -- Same join as on-scene but WITHOUT on_scene_at requirement.
    -- Exclude ids already matched by on-scene (first-match-by-depth).
    dispatch_en_route as (
      select distinct on (o.id)
        o.id as obs_id
      from public.observations o
      join requested r on r.obs_id = o.id
      join public.dispatch_jobs dj on dj.client_site_id = o.site_id
      join public.dispatch_resources dr on dr.id = dj.dispatch_resource_id
      where dr.assigned_officer_id = v_caller
        and dj.dispatched_at is not null
        and dj.completed_at is null
        and o.site_id is not null
        and o.id not in (select dos.obs_id from dispatch_on_scene dos)
    ),

    -- BRANCH 4: rostered_presence (operational_only).
    -- Officer link: shift_stops -> shifts.officer_user_id.
    -- Mirrors 0329 roster block verbatim.
    roster as (
      select distinct on (o.id)
        o.id as obs_id
      from public.observations o
      join requested r on r.obs_id = o.id
      join public.shift_stops ss on (
           (ss.site_id is not null and ss.site_id = o.site_id)
        or (ss.zone_id is not null and ss.zone_id = o.zone_id)
      )
      join public.shifts s on s.id = ss.shift_id
      where s.officer_user_id = v_caller
        and ss.status not in ('completed', 'skipped', 'cancelled')
    ),

    -- BRANCH 5: supervisory_review (operational_only).
    -- staff_reporting: caller is reports_to for an officer who holds a live
    -- task basis on this observation. Mirrors 0329 supervisory block.
    supervisory as (
      select distinct on (ta.observation_id)
        ta.observation_id as obs_id
      from public.staff_reporting sr
      join public.task_assignments ta
        on ta.user_id = sr.user_id
        and ta.ended_at is null
        and ta.observation_id is not null
      join requested r on r.obs_id = ta.observation_id
      where sr.reports_to_user_id = v_caller
        and sr.effective_to is null
    ),

    -- COMPOSE: first-match-by-depth per id. The COALESCE chain mirrors the
    -- 0329 branch ordering: ownership > dispatch on-scene > dispatch en-route
    -- > roster > supervisory. For each id, the first non-null match wins.
    resolved as (
      select
        r.obs_id,
        -- Decision state: full_access or operational_only depending on basis.
        case
          when ow.basis in ('follow_up_ownership', 'direct_module_initiation') then 'full_access'
          when ow.basis = 'backup_attachment' then 'operational_only'
          when dos.obs_id is not null then 'full_access'
          when der.obs_id is not null then 'operational_only'
          when ros.obs_id is not null then 'operational_only'
          when sup.obs_id is not null then 'operational_only'
          else null  -- no basis found
        end as decision_state,
        -- Granted basis name.
        case
          when ow.basis is not null then ow.basis
          when dos.obs_id is not null then 'dispatch_response'
          when der.obs_id is not null then 'dispatch_response'
          when ros.obs_id is not null then 'rostered_presence'
          when sup.obs_id is not null then 'supervisory_review'
          else null
        end as granted_basis,
        -- Expiry end condition.
        case
          when ow.basis is not null then ow.expiry
          when dos.obs_id is not null then 'basis_ends: dispatch completed_at set, reassignment, or 24h grace (Q1)'
          when der.obs_id is not null then 'basis_ends: dispatch completed_at set, reassignment, or 24h grace (Q1)'
          when ros.obs_id is not null then 'basis_ends: stop completed/skipped/cancelled or shift end'
          when sup.obs_id is not null then 'basis_ends: reporting responsibility ends or supervised task ends (R2)'
          else null
        end as expiry_end_condition,
        -- Message key.
        case
          when ow.basis in ('follow_up_ownership', 'direct_module_initiation')
            then 'access.granted.' || ow.basis
          when ow.basis = 'backup_attachment'
            then 'access.granted.backup_attachment'
          when dos.obs_id is not null then 'access.granted.dispatch_response.on_scene'
          when der.obs_id is not null then 'access.granted.dispatch_response.en_route'
          when ros.obs_id is not null then 'access.granted.rostered_presence'
          when sup.obs_id is not null then 'access.granted.supervisory_review'
          else null
        end as message_key
      from requested r
      left join ownership ow on ow.obs_id = r.obs_id
      left join dispatch_on_scene dos on dos.obs_id = r.obs_id
      left join dispatch_en_route der on der.obs_id = r.obs_id
      left join roster ros on ros.obs_id = r.obs_id
      left join supervisory sup on sup.obs_id = r.obs_id
    )

  -- FINAL SELECT: one row per requested id. EXISTENCE COLLAPSE: ids with
  -- no basis (including nonexistent ids that never matched any join) get
  -- the identical no-basis verdict via COALESCE.
  select
    rv.obs_id                                                          as id,
    coalesce(rv.decision_state, 'no_task_entitlement')                 as decision_state,
    rv.granted_basis                                                   as granted_basis,
    case when rv.decision_state is not null then 'none' else 'task' end as failed_gate,
    rv.expiry_end_condition                                            as expiry_end_condition,
    'informative'::text                                                as sensitivity_mode,
    coalesce(rv.message_key, 'access.no_live_basis')                   as message_key
  from resolved rv;
end;
$function$;
COMMENT ON FUNCTION "public"."resolve_access_basis_batch"(p_observation_ids uuid[]) IS 'BATCHED BASIS ENGINE (ACCESS_MODEL.md sections 8/11, step-4 prerequisite). Ratified plan: docs/design/BATCHED_ACCESS_BASIS_RESOLVER.md (!1292). SECURITY DEFINER + fixed search_path. SELF-ONLY: caller derived from auth.uid(); NO p_user parameter. Observations-only (not the 7-type polymorphic batch). Returns one verdict row per requested id; existence collapsed (nonexistent/inaccessible/no-basis ids all yield the identical no-basis shape). Input cap: 200 ids. Static SQL only. Additive: does not touch the single-record resolver, the RLS boolean, or the keystone.';
REVOKE ALL ON FUNCTION "public"."resolve_access_basis_batch"(p_observation_ids uuid[]) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."resolve_access_basis_batch"(p_observation_ids uuid[]) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."resolve_access_basis_batch"(p_observation_ids uuid[]) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."resolve_access_basis_batch"(p_observation_ids uuid[]) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."resolve_access_basis_batch"(p_observation_ids uuid[]) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."resolve_access_basis_batch"(p_observation_ids uuid[]) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."resolve_access_grants"(p_user_id uuid, p_org_id uuid)
 RETURNS TABLE(area text, level text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with rank_map as (
    select * from (values
      ('view', 1), ('verify', 2), ('approve', 3), ('adjust', 4), ('manage', 5)
    ) as r(level, ord)
  ),
  -- (a) direct per-user grants scoped to an org whose subtree contains p_org_id
  direct as (
    select g.area, g.level
    from public.staff_area_grants g
    where g.user_id = p_user_id
      and g.status = 'active'
      and p_org_id = any (public.get_descendant_organizations(g.scope_org_id))
  ),
  -- (b) grants from assigned presets, expanded from the jsonb grants map
  from_presets as (
    select kv.key as area, kv.value as level
    from public.preset_assignments pa
    join public.access_presets ap on ap.id = pa.preset_id
    cross join lateral jsonb_each_text(ap.grants) as kv(key, value)
    where pa.user_id = p_user_id
      and pa.status = 'active'
      and p_org_id = any (public.get_descendant_organizations(pa.scope_org_id))
  ),
  effective as (
    select area, level from direct
    union all
    select area, level from from_presets
  ),
  ranked as (
    select e.area, rm.ord
    from effective e
    join rank_map rm on rm.level = e.level
  ),
  best as (
    select area, max(ord) as ord from ranked group by area
  )
  select b.area, rm.level
  from best b
  join rank_map rm on rm.ord = b.ord
  order by b.area;
$function$;
COMMENT ON FUNCTION "public"."resolve_access_grants"(p_user_id uuid, p_org_id uuid) IS 'Effective functional-area:level for a user in an org: union of direct grants (staff_area_grants) + assigned-preset grants (preset_assignments -> access_presets.grants), highest level per area. Preset edits cascade to all holders (issue #3, C3).';
REVOKE ALL ON FUNCTION "public"."resolve_access_grants"(p_user_id uuid, p_org_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."resolve_access_grants"(p_user_id uuid, p_org_id uuid) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."resolve_access_grants"(p_user_id uuid, p_org_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."resolve_access_grants"(p_user_id uuid, p_org_id uuid) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."resolve_access_grants"(p_user_id uuid, p_org_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."resolve_access_grants"(p_user_id uuid, p_org_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."resolve_active_rules"(p_organization_id uuid, p_module_key text, p_lat double precision DEFAULT NULL::double precision, p_lng double precision DEFAULT NULL::double precision, p_zone_id uuid DEFAULT NULL::uuid, p_site_id uuid DEFAULT NULL::uuid, p_location_id uuid DEFAULT NULL::uuid, p_at timestamp with time zone DEFAULT now())
 RETURNS TABLE(organization_id uuid, module_key text, enabled boolean, dominant_anchor_kind text, active_zone_id uuid, active_site_id uuid, active_location_id uuid, governing_jurisdiction_id uuid, governing_jurisdiction_name text, module_rule_set_id uuid, module_rule_set_name text, evidence_requirements jsonb, approval_policy jsonb, report_template_code text, jurisdiction_rule_set_id uuid, jurisdiction_rule_set_name text, jurisdiction_name text, jurisdiction_rules jsonb, resolution_status text, effective_rules jsonb, policy_status text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_zone_id uuid := p_zone_id;
  v_site_id uuid := p_site_id;
  v_location_id uuid := p_location_id;
  v_rule jsonb := '{}'::jsonb;
  v_jur_id uuid := NULL;
  v_jur_name text := NULL;
  v_module_rule_set_id uuid := NULL;
  v_module_rule_set_name text := NULL;
  v_module_evidence_requirements jsonb := '{}'::jsonb;
  v_module_approval_policy jsonb := '{}'::jsonb;
  v_module_report_template_code text := NULL;
  v_jurisdiction_rule_set_id uuid := NULL;
  v_jurisdiction_rule_set_name text := NULL;
  v_jurisdiction_name text := NULL;
  v_jurisdiction_rules jsonb := '{}'::jsonb;
  v_resolution text := 'outside_all_geofences';
  v_enabled boolean := false;
  v_anchor text := 'unresolved';
BEGIN
  IF p_organization_id IS NULL OR NULLIF(trim(COALESCE(p_module_key, '')), '') IS NULL THEN RETURN; END IF;
  SELECT om.enabled INTO v_enabled FROM public.organization_modules om
    WHERE om.organization_id = p_organization_id AND om.module_key = p_module_key LIMIT 1;
  IF v_enabled IS NULL THEN v_enabled := false; END IF;

  IF p_zone_id IS NOT NULL THEN
    SELECT z.id,
           (SELECT cs.id FROM public.client_sites cs WHERE cs.location_id = z.location_id AND cs.active ORDER BY cs.created_at LIMIT 1),
           z.location_id, z.jurisdiction_rule_set_id,
           COALESCE(jrs.name, 'jurisdiction_rules'), jrs.jurisdiction_name, COALESCE(jrs.rules, '{}'::jsonb),
           COALESCE(z.module_key, p_module_key),
           CASE WHEN z.boundary IS NOT NULL THEN 'zone' ELSE 'unresolved' END
      INTO v_zone_id, v_site_id, v_location_id, v_jurisdiction_rule_set_id,
           v_jurisdiction_rule_set_name, v_jurisdiction_name, v_jurisdiction_rules, p_module_key, v_anchor
    FROM public.location_zones z
    LEFT JOIN public.jurisdiction_rule_sets jrs ON jrs.id = z.jurisdiction_rule_set_id
    WHERE z.id = p_zone_id AND NOT z.is_verification_point LIMIT 1;
    IF NOT FOUND THEN RAISE EXCEPTION 'Selected zone is not an operational work area'; END IF;
    v_resolution := 'resolved';
  ELSIF p_site_id IS NOT NULL THEN
    SELECT cs.id, cs.location_id, COALESCE(z.jurisdiction_rule_set_id, NULL),
           COALESCE(jrs.name, 'jurisdiction_rules'), jrs.jurisdiction_name, COALESCE(jrs.rules, '{}'::jsonb), 'site'
      INTO v_site_id, v_location_id, v_jurisdiction_rule_set_id,
           v_jurisdiction_rule_set_name, v_jurisdiction_name, v_jurisdiction_rules, v_anchor
    FROM public.client_sites cs
    LEFT JOIN public.location_zones z ON z.location_id = cs.location_id AND z.module_key = p_module_key AND NOT z.is_verification_point
    LEFT JOIN public.jurisdiction_rule_sets jrs ON jrs.id = z.jurisdiction_rule_set_id
    WHERE cs.id = p_site_id ORDER BY z.created_at LIMIT 1;
    v_resolution := 'resolved';
  ELSIF p_lat IS NOT NULL AND p_lng IS NOT NULL THEN
    SELECT rc.matched_zone_id, rc.site_id, rc.client_org_id, rc.governing_jurisdiction_id,
           rc.governing_jurisdiction_name, rc.effective_rules, rc.resolution_status
      INTO v_zone_id, v_site_id, v_location_id, v_jur_id, v_jur_name, v_rule, v_resolution
    FROM public.resolve_context(p_lat, p_lng, p_organization_id, p_module_key, p_at) rc LIMIT 1;
    IF v_zone_id IS NOT NULL THEN
      SELECT z.location_id INTO v_location_id FROM public.location_zones z WHERE z.id = v_zone_id AND NOT z.is_verification_point LIMIT 1;
    END IF;
    v_anchor := CASE WHEN v_zone_id IS NOT NULL THEN 'zone' WHEN v_site_id IS NOT NULL THEN 'site' ELSE 'unresolved' END;
  END IF;

  SELECT mrs.id, mrs.name, mrs.evidence_requirements, mrs.approval_policy, mrs.report_template_code
    INTO v_module_rule_set_id, v_module_rule_set_name, v_module_evidence_requirements, v_module_approval_policy, v_module_report_template_code
  FROM public.module_rule_sets mrs
  WHERE mrs.organization_id = p_organization_id AND mrs.module_key = p_module_key
  ORDER BY mrs.created_at DESC LIMIT 1;
  IF v_jurisdiction_rule_set_id IS NULL AND p_organization_id IS NOT NULL AND p_module_key IS NOT NULL THEN
    SELECT jrs.id, jrs.name, jrs.jurisdiction_name, jrs.rules
      INTO v_jurisdiction_rule_set_id, v_jurisdiction_rule_set_name, v_jurisdiction_name, v_jurisdiction_rules
    FROM public.jurisdiction_rule_sets jrs
    WHERE jrs.organization_id = p_organization_id AND jrs.module_key = p_module_key
    ORDER BY jrs.created_at DESC LIMIT 1;
  END IF;
  IF v_rule = '{}'::jsonb THEN v_rule := COALESCE(v_jurisdiction_rules, '{}'::jsonb); END IF;
  RETURN QUERY SELECT p_organization_id, p_module_key, v_enabled, v_anchor, v_zone_id,
    v_site_id, v_location_id, v_jur_id, v_jur_name, v_module_rule_set_id,
    v_module_rule_set_name, v_module_evidence_requirements, v_module_approval_policy,
    v_module_report_template_code, v_jurisdiction_rule_set_id, v_jurisdiction_rule_set_name,
    v_jurisdiction_name, v_jurisdiction_rules, v_resolution, v_rule,
    CASE WHEN v_enabled = false THEN 'disabled'
      WHEN v_resolution IN ('unresolved_no_geofence','unresolved_invalid','unresolved_unverified','outside_all_geofences') THEN 'needs_resolution'
      WHEN v_module_rule_set_id IS NULL THEN 'missing_module_rule_set'
      WHEN v_jurisdiction_rule_set_id IS NULL THEN 'missing_jurisdiction_rule_set'
      ELSE 'effective_rules_ready' END;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."resolve_active_rules"(p_organization_id uuid, p_module_key text, p_lat double precision, p_lng double precision, p_zone_id uuid, p_site_id uuid, p_location_id uuid, p_at timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."resolve_active_rules"(p_organization_id uuid, p_module_key text, p_lat double precision, p_lng double precision, p_zone_id uuid, p_site_id uuid, p_location_id uuid, p_at timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."resolve_active_rules"(p_organization_id uuid, p_module_key text, p_lat double precision, p_lng double precision, p_zone_id uuid, p_site_id uuid, p_location_id uuid, p_at timestamp with time zone) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."resolve_active_rules"(p_organization_id uuid, p_module_key text, p_lat double precision, p_lng double precision, p_zone_id uuid, p_site_id uuid, p_location_id uuid, p_at timestamp with time zone) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."resolve_cctv_missed_detection"(p_report_id uuid, p_state text, p_notes text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_report public.cctv_missed_detection_reports%ROWTYPE;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT * INTO v_report FROM public.cctv_missed_detection_reports WHERE id = p_report_id FOR UPDATE;
  IF v_report.id IS NULL OR NOT coalesce(public.is_admin_for_org(v_report.organization_id), false) THEN
    RAISE EXCEPTION 'Only an organisation administrator can resolve a missed-detection report';
  END IF;
  IF p_state IS NULL OR p_state NOT IN ('confirmed_missed', 'not_missed') THEN
    RAISE EXCEPTION 'Resolve as confirmed_missed or not_missed';
  END IF;
  IF v_report.state <> 'open' THEN RAISE EXCEPTION 'This report was already resolved as %', v_report.state; END IF;
  UPDATE public.cctv_missed_detection_reports
     SET state = p_state,
         resolved_by = v_actor,
         resolved_at = clock_timestamp(),
         resolution_notes = left(nullif(trim(coalesce(p_notes, '')), ''), 2000)
   WHERE id = p_report_id AND state = 'open';
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_report.organization_id, v_actor, 'cctv_missed_detection_resolved', 'cctv_missed_detection_reports', p_report_id,
          jsonb_build_object('state', p_state, 'reported_by', v_report.reported_by, 'entity_kind', v_report.entity_kind,
            'engine_version', v_report.engine_version));
  RETURN p_state;
END;
$function$;
COMMENT ON FUNCTION "public"."resolve_cctv_missed_detection"(p_report_id uuid, p_state text, p_notes text) IS 'An organisation administrator resolves an open missed-detection report as confirmed_missed or not_missed, once. Writes audit_log cctv_missed_detection_resolved.';
REVOKE ALL ON FUNCTION "public"."resolve_cctv_missed_detection"(p_report_id uuid, p_state text, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."resolve_cctv_missed_detection"(p_report_id uuid, p_state text, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."resolve_cctv_missed_detection"(p_report_id uuid, p_state text, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."resolve_cctv_missed_detection"(p_report_id uuid, p_state text, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."resolve_context"(p_lat double precision, p_lng double precision, p_org_id uuid, p_module_key text DEFAULT NULL::text, p_at timestamp with time zone DEFAULT now())
 RETURNS TABLE(in_operating_bounds boolean, out_of_bounds_district text, governing_jurisdiction_id uuid, governing_jurisdiction_name text, on_site boolean, site_id uuid, client_org_id uuid, matched_zone_id uuid, matched_module_key text, effective_rules jsonb, resolution_status text, governor_overlap_flag boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_point        geometry := st_setsrid(st_point(p_lng, p_lat), 4326);
  v_in_bounds    boolean := false;
  v_oob_district text := null;
  v_jur_id       uuid := null;
  v_jur_name     text := null;
  v_zone         record;
  v_on_site      boolean := false;
  v_site_id      uuid := null;
  v_client_org   uuid := null;
  v_rules        jsonb := '{}'::jsonb;
  v_resolution   text := 'outside_all_geofences';
  v_gov_overlap  boolean := false;
  v_org_jur_verification text;
  v_org_jur_geom_exists  boolean;
  v_org_jur_geom_valid   boolean;
  v_governor_count integer := 0;
BEGIN
  -- Layer 1: operating bounds (P1/P2: no-geofence / unverified / invalid / outside / inside are distinct).
  SELECT
    o.jurisdiction_geom IS NOT NULL,
    CASE WHEN o.jurisdiction_geom IS NOT NULL
         THEN ST_IsValid(o.jurisdiction_geom) AND NOT ST_IsEmpty(o.jurisdiction_geom)
         ELSE false END,
    o.jurisdiction_verification,
    CASE WHEN o.jurisdiction_geom IS NOT NULL
              AND ST_IsValid(o.jurisdiction_geom)
              AND NOT ST_IsEmpty(o.jurisdiction_geom)
              AND o.jurisdiction_verification = 'verified'
         THEN st_contains(o.jurisdiction_geom, v_point)
         ELSE false END
    INTO v_org_jur_geom_exists, v_org_jur_geom_valid,
         v_org_jur_verification, v_in_bounds
  FROM public.organizations o
  WHERE o.id = p_org_id;

  IF NOT COALESCE(v_org_jur_geom_exists, false) THEN
    v_resolution := 'unresolved_no_geofence';
  ELSIF NOT COALESCE(v_org_jur_geom_valid, false) THEN
    v_resolution := 'unresolved_invalid';
  ELSIF COALESCE(v_org_jur_verification, 'unverified') <> 'verified' THEN
    v_resolution := 'unresolved_unverified';
  ELSE
    v_resolution := 'outside_all_geofences';
  END IF;

  v_in_bounds := COALESCE(v_in_bounds, false);

  IF NOT v_in_bounds THEN
    SELECT o.name INTO v_oob_district
    FROM public.organizations o
    WHERE o.jurisdiction_geom IS NOT NULL
      AND o.active AND o.status IS DISTINCT FROM 'archived'
      AND st_contains(o.jurisdiction_geom, v_point)
    ORDER BY st_area(o.jurisdiction_geom) ASC
    LIMIT 1;
  END IF;

  -- Layer 2: governing council jurisdiction (role-aware; unchanged).
  SELECT count(*)
    INTO v_governor_count
  FROM public.organizations o
  WHERE o.jurisdiction_geom IS NOT NULL
    AND o.id <> p_org_id
    AND o.active AND o.status IS DISTINCT FROM 'archived'
    AND o.jurisdiction_verification = 'verified'
    AND ST_IsValid(o.jurisdiction_geom)
    AND NOT ST_IsEmpty(o.jurisdiction_geom)
    AND st_contains(o.jurisdiction_geom, v_point)
    AND (
      EXISTS (
        SELECT 1 FROM public.org_engagements e
        WHERE e.status = 'active'
          AND ((e.from_org_id = p_org_id AND e.to_org_id = o.id)
            OR (e.to_org_id = p_org_id AND e.from_org_id = o.id))
      )
      OR o.parent_organization_id = p_org_id
      OR o.id = (SELECT parent_organization_id FROM public.organizations WHERE id = p_org_id)
    )
    AND (
      o.organization_type IN ('government', 'service_provider', 'branch')
      OR EXISTS (
        SELECT 1 FROM public.service_agreements sa
        WHERE sa.provider_organization_id = o.id
          AND (sa.ends_on IS NULL OR sa.ends_on >= current_date)
      )
      OR EXISTS (
        SELECT 1 FROM public.organizations child
        WHERE child.parent_organization_id = o.id
      )
      OR EXISTS (
        SELECT 1 FROM public.org_engagements e2
        WHERE e2.to_org_id = o.id
          AND e2.status = 'active'
      )
    );

  IF v_governor_count > 1 THEN
    v_gov_overlap := true;
  END IF;

  SELECT o.id, o.name
    INTO v_jur_id, v_jur_name
  FROM public.organizations o
  WHERE o.jurisdiction_geom IS NOT NULL
    AND o.id <> p_org_id
    AND o.active AND o.status IS DISTINCT FROM 'archived'
    AND o.jurisdiction_verification = 'verified'
    AND ST_IsValid(o.jurisdiction_geom)
    AND NOT ST_IsEmpty(o.jurisdiction_geom)
    AND st_contains(o.jurisdiction_geom, v_point)
    AND (
      EXISTS (
        SELECT 1 FROM public.org_engagements e
        WHERE e.status = 'active'
          AND ((e.from_org_id = p_org_id AND e.to_org_id = o.id)
            OR (e.to_org_id = p_org_id AND e.from_org_id = o.id))
      )
      OR o.parent_organization_id = p_org_id
      OR o.id = (SELECT parent_organization_id FROM public.organizations WHERE id = p_org_id)
    )
    AND (
      o.organization_type IN ('government', 'service_provider', 'branch')
      OR EXISTS (
        SELECT 1 FROM public.service_agreements sa
        WHERE sa.provider_organization_id = o.id
          AND (sa.ends_on IS NULL OR sa.ends_on >= current_date)
      )
      OR EXISTS (
        SELECT 1 FROM public.organizations child
        WHERE child.parent_organization_id = o.id
      )
      OR EXISTS (
        SELECT 1 FROM public.org_engagements e2
        WHERE e2.to_org_id = o.id
          AND e2.status = 'active'
      )
    )
  ORDER BY st_area(o.jurisdiction_geom) ASC
  LIMIT 1;

  -- Layer 3: verified zone geofence. Matching is unchanged; the site and owner now come from the house.
  SELECT z.id, z.location_id, z.module_key, z.onsite_profile, z.boundary,
         z.jurisdiction_rule_set_id, z.rule_overrides,
         z.repeat_stay_radius_m, z.repeat_stay_window_nights,
         z.nightly_limit_consecutive, z.nightly_limit_monthly, z.scv_required
    INTO v_zone
  FROM public.location_zones z
  WHERE z.organization_id = p_org_id AND NOT z.is_verification_point
    AND z.boundary IS NOT NULL
    AND z.boundary_verification = 'verified'
    AND ST_IsValid(z.boundary)
    AND NOT ST_IsEmpty(z.boundary)
    AND st_contains(z.boundary, v_point)
    AND (p_module_key IS NULL OR z.module_key = p_module_key)
    AND public._geofence_active_at(z.active_schedule, p_at)
  ORDER BY st_area(z.boundary) ASC
  LIMIT 1;

  IF v_zone.id IS NOT NULL THEN
    v_resolution := 'resolved';

    -- The owner is the house (locations.organization_id); the zone's own org is the fallback.
    SELECT loc.organization_id INTO v_client_org FROM public.locations loc WHERE loc.id = v_zone.location_id;
    v_client_org := COALESCE(v_client_org, p_org_id);

    -- The site facet on the same house, preferring one whose geometry holds the point.
    SELECT cs.id,
           CASE
             WHEN v_zone.onsite_profile = 'approach_10m'
               THEN st_dwithin(COALESCE(cs.center_point, cs.boundary)::geography, v_point::geography, 10)
             ELSE
               (cs.boundary IS NOT NULL AND st_contains(cs.boundary, v_point))
               OR st_dwithin(COALESCE(cs.center_point, cs.boundary)::geography,
                             v_point::geography,
                             COALESCE(cs.onsite_radius_meters, 10))
           END
      INTO v_site_id, v_on_site
    FROM public.client_sites cs
    WHERE cs.location_id = v_zone.location_id
      AND cs.active
    ORDER BY (cs.boundary IS NOT NULL AND st_contains(cs.boundary, v_point)) DESC,
             st_dwithin(COALESCE(cs.center_point, cs.boundary)::geography, v_point::geography, COALESCE(cs.onsite_radius_meters, 10)) DESC,
             cs.created_at
    LIMIT 1;
    v_on_site := COALESCE(v_on_site, false);

    SELECT COALESCE(jrs.rules, '{}'::jsonb)
      INTO v_rules
    FROM public.jurisdiction_rule_sets jrs
    WHERE jrs.id = v_zone.jurisdiction_rule_set_id;

    v_rules := COALESCE(v_rules, '{}'::jsonb)
      || jsonb_strip_nulls(jsonb_build_object(
           'repeat_stay_radius_m',      v_zone.repeat_stay_radius_m,
           'repeat_stay_window_nights', v_zone.repeat_stay_window_nights,
           'nightly_limit_consecutive', v_zone.nightly_limit_consecutive,
           'nightly_limit_monthly',     v_zone.nightly_limit_monthly,
           'scv_required',              v_zone.scv_required
         ))
      || COALESCE(v_zone.rule_overrides, '{}'::jsonb);
  ELSE
    IF v_resolution NOT IN ('unresolved_no_geofence', 'unresolved_invalid', 'unresolved_unverified') THEN
      IF EXISTS (
        SELECT 1 FROM public.location_zones z
        WHERE z.organization_id = p_org_id AND NOT z.is_verification_point
          AND z.boundary IS NOT NULL
          AND z.boundary_verification = 'unverified'
          AND ST_IsValid(z.boundary)
          AND NOT ST_IsEmpty(z.boundary)
          AND st_contains(z.boundary, v_point)
          AND (p_module_key IS NULL OR z.module_key = p_module_key)
          AND public._geofence_active_at(z.active_schedule, p_at)
      ) THEN
        v_resolution := 'unresolved_unverified';
      ELSIF EXISTS (
        SELECT 1 FROM public.location_zones z
        WHERE z.organization_id = p_org_id AND NOT z.is_verification_point
          AND z.boundary IS NOT NULL
          AND (NOT ST_IsValid(z.boundary) OR ST_IsEmpty(z.boundary))
          AND st_contains(z.boundary, v_point)
          AND (p_module_key IS NULL OR z.module_key = p_module_key)
          AND public._geofence_active_at(z.active_schedule, p_at)
      ) THEN
        v_resolution := 'unresolved_invalid';
      ELSE
        IF NOT EXISTS (
          SELECT 1 FROM public.location_zones z
          WHERE z.organization_id = p_org_id AND NOT z.is_verification_point
            AND z.boundary IS NOT NULL
            AND (p_module_key IS NULL OR z.module_key = p_module_key)
        ) THEN
          v_resolution := 'unresolved_no_geofence';
        END IF;
      END IF;
    END IF;
  END IF;

  RETURN QUERY SELECT
    v_in_bounds, v_oob_district, v_jur_id, v_jur_name,
    v_on_site, v_site_id, v_client_org,
    v_zone.id, v_zone.module_key, v_rules,
    v_resolution,
    v_gov_overlap;
END;
$function$;
COMMENT ON FUNCTION "public"."resolve_context"(p_lat double precision, p_lng double precision, p_org_id uuid, p_module_key text, p_at timestamp with time zone) IS 'Three-layer geofence resolution with verification gate (P1/P2) and role-aware governing jurisdiction. 0347 convergence step 1: the OWNERSHIP answer (client_org_id) ALWAYS resolves TO THE HOUSE (locations.organization_id) where a house is reachable. site_id is a transitional COMPATIBILITY LINK (v2 ruling !1304), used only as a ROUTE to the house, never as a co-equal owner. Resolution tiers: (1) zone.location_id -> locations; (2) zone.site_id -> client_sites.location_id -> locations (site as route); (3) zone.site_id -> client_sites.client_organization_id (transitional last-resort only while a site has no house link during migration). Per the owner ruling (2026-08-05) all three tiers return the SAME org by construction (same PLACE axis), so this changes the SOURCE of the answer, not the answer. ON-SITE geometry, zone matching, Layer 1/2, resolution_status, all 12 columns and governor_overlap_flag are byte-unchanged from 0290. Safe day-one: live zones have location_id NULL and their sites may not yet carry location_id, so resolution reaches tier 3 = the exact 0290 answer -> IDENTICAL output on current data; becomes house-authoritative as step 2 populates location_id upward.';
REVOKE ALL ON FUNCTION "public"."resolve_context"(p_lat double precision, p_lng double precision, p_org_id uuid, p_module_key text, p_at timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."resolve_context"(p_lat double precision, p_lng double precision, p_org_id uuid, p_module_key text, p_at timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."resolve_context"(p_lat double precision, p_lng double precision, p_org_id uuid, p_module_key text, p_at timestamp with time zone) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."resolve_context_authorized"(p_lat double precision, p_lng double precision, p_org_id uuid, p_module_key text DEFAULT NULL::text, p_at timestamp with time zone DEFAULT now())
 RETURNS TABLE(in_operating_bounds boolean, out_of_bounds_district text, governing_jurisdiction_id uuid, governing_jurisdiction_name text, on_site boolean, site_id uuid, client_org_id uuid, matched_zone_id uuid, matched_module_key text, effective_rules jsonb, resolution_status text, governor_overlap_flag boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null or not public.org_access_allowed(p_org_id) then
    raise exception 'Geofence context access denied';
  end if;
  return query select * from public.resolve_context(p_lat,p_lng,p_org_id,p_module_key,p_at);
end;$function$;
COMMENT ON FUNCTION "public"."resolve_context_authorized"(p_lat double precision, p_lng double precision, p_org_id uuid, p_module_key text, p_at timestamp with time zone) IS 'Authenticated tenant-scoped wrapper for resolve_context. The underlying canonical resolver is service-role only; browser callers must pass org_access_allowed for p_org_id.';
REVOKE ALL ON FUNCTION "public"."resolve_context_authorized"(p_lat double precision, p_lng double precision, p_org_id uuid, p_module_key text, p_at timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."resolve_context_authorized"(p_lat double precision, p_lng double precision, p_org_id uuid, p_module_key text, p_at timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."resolve_context_authorized"(p_lat double precision, p_lng double precision, p_org_id uuid, p_module_key text, p_at timestamp with time zone) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."resolve_context_authorized"(p_lat double precision, p_lng double precision, p_org_id uuid, p_module_key text, p_at timestamp with time zone) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."resolve_dispatch_job_financials_internal"(p_actor uuid, p_client_request_id uuid, p_dispatch_job_id uuid, p_day_category text DEFAULT NULL::text)
 RETURNS TABLE(lines_written integer, total_pay numeric, unresolved_count integer, charge_lines_written integer, total_charge numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_job public.dispatch_jobs%rowtype;
  v_site public.client_sites%rowtype;
  v_client_org uuid;
  v_charge record;
  v_charge_written integer := 0;
  v_charge_total numeric := 0;
  v_charge_line numeric;
  v_shift_service text;
  v_officer uuid;
  v_role_code text;
  v_worked_hours numeric;
  v_place_lat double precision;
  v_place_lng double precision;
  v_distance numeric;
  v_distance_reason text;
  v_rule record;
  v_written integer := 0;
  v_unresolved integer := 0;
  v_total numeric := 0;
  v_line_total numeric;
  v_pl_period_id uuid;
BEGIN
  IF p_client_request_id IS NULL THEN RAISE EXCEPTION 'client_request_id is required'; END IF;
  SELECT job.* INTO v_job FROM public.dispatch_jobs job WHERE job.id = p_dispatch_job_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Dispatch job not found'; END IF;
  IF v_job.status <> 'completed' OR v_job.completed_at IS NULL THEN
    RAISE EXCEPTION 'Only completed dispatch jobs produce pay lines';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.dispatch_job_pay_lines line
    WHERE line.source_dispatch_id = v_job.id AND line.rate_rule_id IS NOT NULL
  ) OR EXISTS (
    SELECT 1 FROM public.dispatch_job_charge_lines line
    WHERE line.source_dispatch_id = v_job.id AND line.rate_rule_id IS NOT NULL
  ) THEN
    SELECT count(*)::integer, coalesce(sum(line.line_total), 0)
      INTO v_written, v_total
      FROM public.dispatch_job_pay_lines line WHERE line.source_dispatch_id = v_job.id;
    SELECT count(*)::integer, coalesce(sum(line.line_total), 0)
      INTO v_charge_written, v_charge_total
      FROM public.dispatch_job_charge_lines line WHERE line.source_dispatch_id = v_job.id;
    RETURN QUERY SELECT v_written, v_total,
      (SELECT count(*)::integer FROM public.dispatch_job_pay_lines line WHERE line.source_dispatch_id = v_job.id AND line.rate_rule_id IS NULL),
      v_charge_written, v_charge_total;
    RETURN;
  END IF;

  DELETE FROM public.dispatch_job_pay_lines WHERE source_dispatch_id = v_job.id AND rate_rule_id IS NULL;
  DELETE FROM public.dispatch_job_charge_lines WHERE source_dispatch_id = v_job.id AND rate_rule_id IS NULL;

  SELECT shift.officer_user_id, shift.service_type
    INTO v_officer, v_shift_service
    FROM public.shifts shift WHERE shift.id = v_job.shift_id;
  SELECT staff.role_code INTO v_role_code
    FROM public.staff_profiles staff
    WHERE staff.organization_id = v_job.organization_id
      AND (staff.user_id = v_officer OR staff.id = v_officer)
    LIMIT 1;
  v_worked_hours := CASE
    WHEN v_job.on_scene_at IS NOT NULL THEN extract(epoch FROM (v_job.completed_at - v_job.on_scene_at)) / 3600.0
    WHEN v_job.en_route_at IS NOT NULL THEN extract(epoch FROM (v_job.completed_at - v_job.en_route_at)) / 3600.0
    ELSE NULL
  END;

  IF v_job.client_site_id IS NOT NULL THEN
    SELECT site.* INTO v_site FROM public.client_sites site WHERE site.id = v_job.client_site_id;
    v_place_lat := v_site.gps_lat;
    v_place_lng := v_site.gps_lng;
  ELSE
    SELECT st_y(zone.center_point), st_x(zone.center_point)
      INTO v_place_lat, v_place_lng
      FROM public.location_zones zone WHERE zone.id = v_job.zone_id;
  END IF;
  v_distance := public.compute_travel_distance_km(v_job.insert_gps_lat, v_job.insert_gps_lng, v_place_lat, v_place_lng);
  v_distance_reason := CASE
    WHEN v_distance IS NOT NULL THEN CASE WHEN v_job.zone_id IS NULL THEN 'haversine_dispatch_origin_to_site' ELSE 'haversine_dispatch_origin_to_zone' END
    WHEN v_job.insert_gps_lat IS NULL THEN 'no_dispatch_origin_coordinate'
    WHEN v_place_lat IS NULL THEN 'place_has_no_coordinate'
    ELSE 'unavailable'
  END;

  SELECT * INTO v_rule FROM public.resolve_rate_rule(
    v_job.organization_id, 'pay', v_job.completed_at, NULL, v_job.job_type, NULL,
    NULL, v_job.client_site_id, v_job.zone_id, v_role_code, v_distance, p_day_category, 'hourly'
  );
  IF v_rule.rate_rule_id IS NULL AND v_shift_service IS NOT NULL THEN
    SELECT * INTO v_rule FROM public.resolve_rate_rule(
      v_job.organization_id, 'pay', v_job.completed_at, v_shift_service, NULL, NULL,
      NULL, v_job.client_site_id, v_job.zone_id, v_role_code, v_distance, p_day_category, 'hourly'
    );
  END IF;
  IF v_rule.rate_rule_id IS NOT NULL AND v_worked_hours IS NOT NULL THEN
    v_line_total := round(v_worked_hours * v_rule.amount, 2);
    INSERT INTO public.dispatch_job_pay_lines (
      organization_id, source_dispatch_id, officer_user_id, rate_rule_id, pay_code,
      rate_type, description, quantity, unit_rate, multiplier, line_total,
      distance_km, distance_reason, role_code, region_code, service_type, day_category
    ) VALUES (
      v_job.organization_id, v_job.id, v_officer, v_rule.rate_rule_id, v_rule.pay_code,
      'hourly', 'Attendance labour', round(v_worked_hours, 4), v_rule.amount, 1, v_line_total,
      v_distance, v_distance_reason, v_rule.role_code, v_rule.region_code, v_job.job_type, v_rule.day_category
    );
    v_written := v_written + 1;
    v_total := v_total + v_line_total;
  ELSE
    v_unresolved := v_unresolved + 1;
    INSERT INTO public.dispatch_job_pay_lines (
      organization_id, source_dispatch_id, officer_user_id, rate_rule_id, pay_code,
      rate_type, description, quantity, unit_rate, multiplier, line_total,
      distance_km, distance_reason, role_code, service_type, day_category
    ) VALUES (
      v_job.organization_id, v_job.id, v_officer, NULL, 'UNRESOLVED', 'hourly',
      CASE WHEN v_worked_hours IS NULL THEN 'Unresolved: no on-scene or en-route timestamp' ELSE 'Unresolved: no active hourly pay rule matched' END,
      coalesce(round(v_worked_hours, 4), 0), 0, 1, 0, v_distance, v_distance_reason,
      v_role_code, v_job.job_type, p_day_category
    );
    v_written := v_written + 1;
  END IF;

  IF v_distance IS NOT NULL THEN
    SELECT * INTO v_rule FROM public.resolve_rate_rule(
      v_job.organization_id, 'pay', v_job.completed_at, NULL, v_job.job_type, NULL,
      NULL, v_job.client_site_id, v_job.zone_id, v_role_code, v_distance, p_day_category, 'per_km'
    );
    IF v_rule.rate_rule_id IS NULL AND v_shift_service IS NOT NULL THEN
      SELECT * INTO v_rule FROM public.resolve_rate_rule(
        v_job.organization_id, 'pay', v_job.completed_at, v_shift_service, NULL, NULL,
        NULL, v_job.client_site_id, v_job.zone_id, v_role_code, v_distance, p_day_category, 'per_km'
      );
    END IF;
    IF v_rule.rate_rule_id IS NOT NULL THEN
      v_line_total := round(v_distance * v_rule.amount, 2);
      INSERT INTO public.dispatch_job_pay_lines (
        organization_id, source_dispatch_id, officer_user_id, rate_rule_id, pay_code,
        rate_type, description, quantity, unit_rate, multiplier, line_total,
        distance_km, distance_reason, role_code, region_code, service_type, day_category
      ) VALUES (
        v_job.organization_id, v_job.id, v_officer, v_rule.rate_rule_id,
        coalesce(v_rule.pay_code, 'TRAVEL'), 'per_km', 'Travel to place',
        v_distance, v_rule.amount, 1, v_line_total, v_distance, v_distance_reason,
        v_rule.role_code, v_rule.region_code, v_job.job_type, v_rule.day_category
      );
      v_written := v_written + 1;
      v_total := v_total + v_line_total;

      BEGIN
        SELECT period.id INTO v_pl_period_id
        FROM public.finance_pl_periods period
        WHERE period.organization_id = v_job.organization_id
          AND v_job.completed_at::date BETWEEN period.period_start AND period.period_end
          AND period.status NOT IN ('closed', 'archived')
        ORDER BY period.period_end DESC LIMIT 1;
        IF v_pl_period_id IS NOT NULL AND v_job.service_agreement_id IS NOT NULL THEN
          INSERT INTO public.finance_service_costs (
            organization_id, pl_period_id, service_agreement_id, client_organization_id,
            cost_type, dispatch_job_id, shift_id, source_document_type,
            source_reference, quantity, unit_cost, total_cost, created_by
          )
          SELECT v_job.organization_id, v_pl_period_id, v_job.service_agreement_id,
            agreement.client_organization_id, 'vehicle', v_job.id, v_job.shift_id,
            'dispatch_job', 'Travel to place (auto, dispatch completion)',
            v_distance, v_rule.amount, v_line_total, v_officer
          FROM public.service_agreements agreement WHERE agreement.id = v_job.service_agreement_id
          ON CONFLICT DO NOTHING;
        END IF;
      EXCEPTION WHEN others THEN NULL;
      END;
    END IF;
  END IF;

  SELECT coalesce(agreement.client_organization_id, v_site.client_organization_id)
    INTO v_client_org
    FROM (SELECT 1) seed
    LEFT JOIN public.service_agreements agreement ON agreement.id = v_job.service_agreement_id;
  SELECT * INTO v_charge FROM public.resolve_rate_rule(
    v_job.organization_id, 'billing', v_job.completed_at, NULL, v_job.job_type,
    v_job.module_key, v_client_org, v_job.client_site_id, v_job.zone_id,
    NULL, v_distance, p_day_category, 'hourly'
  );
  IF v_charge.rate_rule_id IS NULL AND v_shift_service IS NOT NULL THEN
    SELECT * INTO v_charge FROM public.resolve_rate_rule(
      v_job.organization_id, 'billing', v_job.completed_at, v_shift_service, NULL,
      v_job.module_key, v_client_org, v_job.client_site_id, v_job.zone_id,
      NULL, v_distance, p_day_category, 'hourly'
    );
  END IF;
  IF v_charge.rate_rule_id IS NOT NULL AND v_worked_hours IS NOT NULL THEN
    v_charge_line := round(v_worked_hours * v_charge.amount, 2);
    INSERT INTO public.dispatch_job_charge_lines (
      organization_id, source_dispatch_id, client_organization_id, service_agreement_id,
      rate_rule_id, rate_type, description, quantity, unit_rate, line_total,
      distance_km, service_type, day_category
    ) VALUES (
      v_job.organization_id, v_job.id, v_client_org, v_job.service_agreement_id,
      v_charge.rate_rule_id, 'hourly', 'Attendance', round(v_worked_hours, 4),
      v_charge.amount, v_charge_line, v_distance, v_job.job_type, v_charge.day_category
    );
    v_charge_written := v_charge_written + 1;
    v_charge_total := v_charge_total + v_charge_line;
  ELSE
    INSERT INTO public.dispatch_job_charge_lines (
      organization_id, source_dispatch_id, client_organization_id, service_agreement_id,
      rate_rule_id, rate_type, description, quantity, unit_rate, line_total,
      distance_km, service_type, day_category
    ) VALUES (
      v_job.organization_id, v_job.id, v_client_org, v_job.service_agreement_id,
      NULL, 'hourly', CASE WHEN v_worked_hours IS NULL THEN 'Unresolved: no on-scene or en-route timestamp' ELSE 'Unresolved: no active hourly charge rule matched' END,
      coalesce(round(v_worked_hours, 4), 0), 0, 0, v_distance, v_job.job_type, p_day_category
    );
    v_charge_written := v_charge_written + 1;
  END IF;

  IF v_distance IS NOT NULL THEN
    SELECT * INTO v_charge FROM public.resolve_rate_rule(
      v_job.organization_id, 'billing', v_job.completed_at, NULL, v_job.job_type,
      v_job.module_key, v_client_org, v_job.client_site_id, v_job.zone_id,
      NULL, v_distance, p_day_category, 'per_km'
    );
    IF v_charge.rate_rule_id IS NULL AND v_shift_service IS NOT NULL THEN
      SELECT * INTO v_charge FROM public.resolve_rate_rule(
        v_job.organization_id, 'billing', v_job.completed_at, v_shift_service, NULL,
        v_job.module_key, v_client_org, v_job.client_site_id, v_job.zone_id,
        NULL, v_distance, p_day_category, 'per_km'
      );
    END IF;
    IF v_charge.rate_rule_id IS NOT NULL THEN
      v_charge_line := round(v_distance * v_charge.amount, 2);
      INSERT INTO public.dispatch_job_charge_lines (
        organization_id, source_dispatch_id, client_organization_id, service_agreement_id,
        rate_rule_id, rate_type, description, quantity, unit_rate, line_total,
        distance_km, service_type, day_category
      ) VALUES (
        v_job.organization_id, v_job.id, v_client_org, v_job.service_agreement_id,
        v_charge.rate_rule_id, 'per_km', 'Travel to place', v_distance,
        v_charge.amount, v_charge_line, v_distance, v_job.job_type, v_charge.day_category
      );
      v_charge_written := v_charge_written + 1;
      v_charge_total := v_charge_total + v_charge_line;
    END IF;
  END IF;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (
    v_job.organization_id, p_actor, 'dispatch_financials_resolved',
    'dispatch_job_pay_lines', v_job.id,
    jsonb_build_object(
      'dispatch_job_id', v_job.id,
      'lines_written', v_written,
      'unresolved_count', v_unresolved,
      'total_pay', v_total,
      'charge_lines_written', v_charge_written,
      'total_charge', v_charge_total,
      'distance_km', v_distance,
      'distance_reason', v_distance_reason,
      'role_code', v_role_code,
      'client_request_id', p_client_request_id
    )
  );
  RETURN QUERY SELECT v_written, v_total, v_unresolved, v_charge_written, v_charge_total;
END;
$function$;
COMMENT ON FUNCTION "public"."resolve_dispatch_job_financials_internal"(p_actor uuid, p_client_request_id uuid, p_dispatch_job_id uuid, p_day_category text) IS 'Resolves completed dispatch pay, customer charges, travel distance, and vehicle cost for either a Site or Zone place.';
REVOKE ALL ON FUNCTION "public"."resolve_dispatch_job_financials_internal"(p_actor uuid, p_client_request_id uuid, p_dispatch_job_id uuid, p_day_category text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."resolve_dispatch_job_financials_internal"(p_actor uuid, p_client_request_id uuid, p_dispatch_job_id uuid, p_day_category text) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."resolve_dispatch_job_pay_lines"(p_client_request_id uuid, p_dispatch_job_id uuid, p_day_category text DEFAULT NULL::text)
 RETURNS TABLE(lines_written integer, total_pay numeric, unresolved_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_org uuid;
begin
  select j.organization_id into v_org from public.dispatch_jobs j where j.id = p_dispatch_job_id;
  if v_org is null then raise exception 'Dispatch job not found'; end if;
  if not public.is_admin_for_org(v_org) then raise exception 'Not authorised to resolve pay for this organization'; end if;
  return query select r.lines_written, r.total_pay, r.unresolved_count
  from public.resolve_dispatch_job_financials_internal(auth.uid(), p_client_request_id, p_dispatch_job_id, p_day_category) r;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."resolve_dispatch_job_pay_lines"(p_client_request_id uuid, p_dispatch_job_id uuid, p_day_category text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."resolve_dispatch_job_pay_lines"(p_client_request_id uuid, p_dispatch_job_id uuid, p_day_category text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."resolve_dispatch_job_pay_lines"(p_client_request_id uuid, p_dispatch_job_id uuid, p_day_category text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."resolve_dispatch_job_pay_lines"(p_client_request_id uuid, p_dispatch_job_id uuid, p_day_category text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."resolve_enforcement_mode"(p_zone_id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(
    lz.enforcement_workflow_override,
    o.enforcement_workflow_mode,
    'officer_direct'
  )
  from public.location_zones lz
  join public.organizations o on o.id = lz.organization_id
  where lz.id = p_zone_id;
$function$;
COMMENT ON FUNCTION "public"."resolve_enforcement_mode"(p_zone_id uuid) IS 'Internal effective enforcement workflow resolver: zone override, then organization default, then officer_direct. Called only from governed server-side paths.';
REVOKE ALL ON FUNCTION "public"."resolve_enforcement_mode"(p_zone_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."resolve_enforcement_mode"(p_zone_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."resolve_enforcement_mode"(p_zone_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."resolve_entity_flag"(p_flag_id uuid, p_note text DEFAULT NULL::text)
 RETURNS entity_flags
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_flag public.entity_flags%rowtype;
begin
  select * into v_flag from public.entity_flags where id = p_flag_id for update;
  if not found then raise exception 'Flag not found'; end if;
  if v_actor is null or not (v_flag.raised_by = v_actor or public.is_admin_for_org(v_flag.organization_id)) then
    raise exception 'Only the person who raised this flag or an administrator of their organisation can resolve it';
  end if;
  if not v_flag.active then return v_flag; end if;
  update public.entity_flags set active = false, resolved_at = now(), resolved_by = v_actor where id = v_flag.id returning * into v_flag;
  insert into public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (v_flag.organization_id, v_actor, case when v_flag.hazard_class is null then 'entity_flag_resolved' else 'safety_warning_resolved' end, 'entity_flags', v_flag.id,
          jsonb_build_object('entity_type', v_flag.entity_type, 'entity_id', v_flag.entity_id, 'hazard_class', v_flag.hazard_class, 'note', nullif(trim(coalesce(p_note, '')), '')));
  return v_flag;
end;
$function$;
COMMENT ON FUNCTION "public"."resolve_entity_flag"(p_flag_id uuid, p_note text) IS 'Resolve (deactivate) a flag or safety warning: the raiser or an administrator of the raising organisation. Audited.';
REVOKE ALL ON FUNCTION "public"."resolve_entity_flag"(p_flag_id uuid, p_note text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."resolve_entity_flag"(p_flag_id uuid, p_note text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."resolve_entity_flag"(p_flag_id uuid, p_note text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."resolve_flag_entity"(p_entity_type text, p_entity_id uuid, OUT entity_type text, OUT entity_id uuid)
 RETURNS record
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_entity_type = 'site' then
    -- A site is a facet of its house; the house carries the canonical place (locations.canonical_place_id is NOT NULL),
    -- so warnings live on the place and every organisation working at that address sees them.
    select 'place', l.canonical_place_id into entity_type, entity_id
    from public.client_sites s join public.locations l on l.id = s.location_id where s.id = p_entity_id;
    if entity_id is null then raise exception 'Site is not linked to a place'; end if;
  elsif p_entity_type = 'zone' then
    select 'place', l.canonical_place_id into entity_type, entity_id
    from public.location_zones z join public.locations l on l.id = z.location_id where z.id = p_entity_id;
    if entity_id is null then raise exception 'Zone is not linked to a place'; end if;
  elsif p_entity_type in ('vehicle', 'person', 'place') then
    entity_type := p_entity_type; entity_id := p_entity_id;
  else
    raise exception 'Safety warnings apply to vehicles, people, places, sites and zones';
  end if;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."resolve_flag_entity"(p_entity_type text, p_entity_id uuid, OUT entity_type text, OUT entity_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."resolve_flag_entity"(p_entity_type text, p_entity_id uuid, OUT entity_type text, OUT entity_id uuid) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."resolve_identity_document_person"(p_identity_document_id uuid, p_target_person_record_id uuid, p_resolution_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid:=auth.uid();v_document public.person_identity_documents%rowtype;v_source public.person_records%rowtype;v_target public.person_records%rowtype;
  v_source_canonical uuid;v_target_canonical uuid;v_other_source_links integer;v_incident_link public.incident_person_links%rowtype;
BEGIN
  IF coalesce(trim(p_resolution_reason),'')='' THEN RAISE EXCEPTION 'Resolution reason is required'; END IF;
  SELECT * INTO v_document FROM public.person_identity_documents WHERE id=p_identity_document_id FOR UPDATE;
  IF v_document.id IS NULL OR v_document.review_state<>'manual_review_required' THEN RAISE EXCEPTION 'A pending identity document is required'; END IF;
  IF v_actor IS NULL OR NOT public.is_admin_for_org(v_document.organization_id) THEN RAISE EXCEPTION 'Identity resolution administrator access required'; END IF;
  SELECT * INTO v_source FROM public.person_records WHERE id=v_document.person_record_id AND organization_id=v_document.organization_id FOR UPDATE;
  SELECT * INTO v_target FROM public.person_records WHERE id=p_target_person_record_id AND organization_id=v_document.organization_id FOR UPDATE;
  IF v_source.id IS NULL OR v_target.id IS NULL OR v_source.id=v_target.id THEN RAISE EXCEPTION 'Choose a different existing person in this organization'; END IF;
  v_source_canonical:=public.ensure_canonical_person_for_record(v_source.id);
  v_target_canonical:=public.ensure_canonical_person_for_record(v_target.id);

  UPDATE public.person_identity_documents SET person_record_id=v_target.id,updated_at=clock_timestamp() WHERE id=v_document.id;
  UPDATE public.person_identity_face_proposals SET person_record_id=v_target.id WHERE identity_document_id=v_document.id;
  UPDATE public.bob_attachments SET extraction_payload=jsonb_set(coalesce(extraction_payload,'{}'::jsonb),'{person_record_id}',to_jsonb(v_target.id),true)
    WHERE id=v_document.attachment_id;
  UPDATE public.evidence_items SET metadata=jsonb_set(coalesce(metadata,'{}'::jsonb),'{resolved_person_record_id}',to_jsonb(v_target.id),true)
    WHERE id=v_document.evidence_item_id;

  FOR v_incident_link IN SELECT * FROM public.incident_person_links WHERE person_record_id=v_source.id LOOP
    INSERT INTO public.incident_person_links(organization_id,incident_id,canonical_person_id,person_record_id,staff_profile_id,identity_document_id,involvement_role,source_kind,notes,recorded_by,created_at,updated_at)
    VALUES(v_incident_link.organization_id,v_incident_link.incident_id,v_target_canonical,v_target.id,
      nullif(v_target.metadata->'profile_details'->>'staff_profile_id','')::uuid,
      CASE WHEN v_incident_link.identity_document_id=v_document.id THEN v_document.id ELSE v_incident_link.identity_document_id END,
      v_incident_link.involvement_role,v_incident_link.source_kind,v_incident_link.notes,v_actor,v_incident_link.created_at,clock_timestamp())
    ON CONFLICT(incident_id,canonical_person_id,involvement_role) DO UPDATE SET
      person_record_id=excluded.person_record_id,staff_profile_id=coalesce(excluded.staff_profile_id,incident_person_links.staff_profile_id),
      identity_document_id=coalesce(excluded.identity_document_id,incident_person_links.identity_document_id),
      notes=excluded.notes,recorded_by=excluded.recorded_by,updated_at=clock_timestamp();
  END LOOP;
  DELETE FROM public.incident_person_links WHERE person_record_id=v_source.id;

  UPDATE public.cctv_entity_observations SET person_record_id=v_target.id,canonical_person_id=v_target_canonical WHERE person_record_id=v_source.id;
  UPDATE public.face_observations SET person_record_id=v_target.id WHERE person_record_id=v_source.id;
  UPDATE public.observations SET person_record_id=v_target.id,canonical_person_id=v_target_canonical WHERE person_record_id=v_source.id;
  UPDATE public.cctv_identity_drafts SET proposed_person_record_id=v_target.id WHERE proposed_person_record_id=v_source.id AND organization_id=v_document.organization_id;
  UPDATE public.canonical_person_links SET canonical_person_id=v_target_canonical,metadata=metadata||jsonb_build_object('resolved_from_canonical_person_id',v_source_canonical,'resolved_by',v_actor,'resolved_at',clock_timestamp())
    WHERE source_table='person_records' AND source_id=v_source.id;
  SELECT count(*) INTO v_other_source_links FROM public.canonical_person_links WHERE canonical_person_id=v_source_canonical;
  IF v_other_source_links=0 THEN UPDATE public.canonical_people SET status='merged',merged_into_id=v_target_canonical,updated_at=clock_timestamp() WHERE id=v_source_canonical; END IF;
  UPDATE public.person_records SET review_state='rejected',metadata=metadata||jsonb_build_object('resolved_into_person_record_id',v_target.id,'resolved_at',clock_timestamp(),'resolved_by',v_actor)
    WHERE id=v_source.id;
  INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
  VALUES(v_document.organization_id,v_actor,'identity_document_person_resolved','person_identity_documents',v_document.id,jsonb_build_object(
    'source_person_record_id',v_source.id,'target_person_record_id',v_target.id,'source_canonical_person_id',v_source_canonical,
    'target_canonical_person_id',v_target_canonical,'resolution_reason',trim(p_resolution_reason)));
  RETURN jsonb_build_object('identity_document_id',v_document.id,'source_person_record_id',v_source.id,'person_record_id',v_target.id,
    'canonical_person_id',v_target_canonical,'staff_profile_id',nullif(v_target.metadata->'profile_details'->>'staff_profile_id','')::uuid);
END;
$function$;
COMMENT ON FUNCTION "public"."resolve_identity_document_person"(p_identity_document_id uuid, p_target_person_record_id uuid, p_resolution_reason text) IS 'Admin-only human resolution of pending incident/CCTV identity evidence to an existing person projection and canonical person, preserving source history and audit.';
REVOKE ALL ON FUNCTION "public"."resolve_identity_document_person"(p_identity_document_id uuid, p_target_person_record_id uuid, p_resolution_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."resolve_identity_document_person"(p_identity_document_id uuid, p_target_person_record_id uuid, p_resolution_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."resolve_identity_document_person"(p_identity_document_id uuid, p_target_person_record_id uuid, p_resolution_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."resolve_identity_document_person"(p_identity_document_id uuid, p_target_person_record_id uuid, p_resolution_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."resolve_location_visibility"(p_sal_id uuid, p_viewing_org_id uuid)
 RETURNS TABLE(share_contract_price boolean, share_actual_cost boolean, is_provider boolean, is_client boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    -- Effective share_contract_price: location override if set, else agreement default.
    coalesce(sal.share_contract_price, sa.default_share_contract_price) as share_contract_price,
    coalesce(sal.share_actual_cost,    sa.default_share_actual_cost)    as share_actual_cost,
    -- Which side of the agreement is the viewing org?
    public.org_access_allowed(sa.provider_organization_id) as is_provider,
    public.org_access_allowed(sa.client_organization_id)   as is_client
  from public.service_agreement_locations sal
  join public.service_agreements sa on sa.id = sal.service_agreement_id
  where sal.id = p_sal_id;
$function$;
COMMENT ON FUNCTION "public"."resolve_location_visibility"(p_sal_id uuid, p_viewing_org_id uuid) IS 'Returns effective visibility settings for a location contract: share_contract_price and share_actual_cost (location override coalesced with agreement default), plus which side of the agreement the viewing org is on. Used by the UI finance tab and conductor egress gate (epic #179).';
REVOKE ALL ON FUNCTION "public"."resolve_location_visibility"(p_sal_id uuid, p_viewing_org_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."resolve_location_visibility"(p_sal_id uuid, p_viewing_org_id uuid) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."resolve_location_visibility"(p_sal_id uuid, p_viewing_org_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."resolve_location_visibility"(p_sal_id uuid, p_viewing_org_id uuid) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."resolve_location_visibility"(p_sal_id uuid, p_viewing_org_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."resolve_location_visibility"(p_sal_id uuid, p_viewing_org_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."resolve_manager_for_user"(p_user_id uuid, p_context_org_id uuid)
 RETURNS TABLE(manager_user_id uuid, resolution_source text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_manager_id     uuid;
  v_source         text;
  v_home_org_id    uuid;
  v_walk_org_id    uuid;
  v_parent_org_id  uuid;
BEGIN
  -- ── Step 1: Branch-specific line_manager at context org ──
  SELECT sr.reports_to_user_id INTO v_manager_id
  FROM public.staff_reporting sr
  WHERE sr.user_id = p_user_id
    AND sr.scope_org_id = p_context_org_id
    AND sr.relationship_type = 'line_manager'
    AND sr.effective_to IS NULL
  LIMIT 1;

  IF v_manager_id IS NOT NULL THEN
    manager_user_id := v_manager_id;
    resolution_source := 'branch_line_manager';
    RETURN NEXT;
    RETURN;
  END IF;

  -- ── Step 2: Org-wide line_manager (at user's home org) ──
  SELECT up.organization_id INTO v_home_org_id
  FROM public.user_profiles up
  WHERE up.id = p_user_id;

  IF v_home_org_id IS NOT NULL AND v_home_org_id <> p_context_org_id THEN
    SELECT sr.reports_to_user_id INTO v_manager_id
    FROM public.staff_reporting sr
    WHERE sr.user_id = p_user_id
      AND sr.scope_org_id = v_home_org_id
      AND sr.relationship_type = 'line_manager'
      AND sr.effective_to IS NULL
    LIMIT 1;

    IF v_manager_id IS NOT NULL THEN
      manager_user_id := v_manager_id;
      resolution_source := 'org_wide_line_manager';
      RETURN NEXT;
      RETURN;
    END IF;
  END IF;

  -- ── Step 3: Team lead fallback ──
  SELECT t.team_lead_user_id INTO v_manager_id
  FROM public.team_members tm
  JOIN public.teams t ON tm.team_id = t.id
  WHERE tm.user_id = p_user_id
    AND tm.left_at IS NULL
    AND t.status = 'active'
    AND (t.scope_org_id = p_context_org_id OR t.scope_org_id IS NULL)
    AND t.team_lead_user_id IS NOT NULL
    AND t.team_lead_user_id <> p_user_id  -- prevent self-reference
  LIMIT 1;

  IF v_manager_id IS NOT NULL THEN
    manager_user_id := v_manager_id;
    resolution_source := 'team_lead';
    RETURN NEXT;
    RETURN;
  END IF;

  -- ── Step 4: Branch manager by role_at_branch + org tree walk (Q2) ──
  -- Start at the context org, then walk up parent_organization_id
  v_walk_org_id := p_context_org_id;

  LOOP
    SELECT sba.user_id INTO v_manager_id
    FROM public.staff_branch_authorisations sba
    WHERE sba.branch_org_id = v_walk_org_id
      AND sba.role_at_branch = 'branch_manager'
      AND sba.status = 'active'
      AND sba.user_id <> p_user_id  -- prevent self-reference
    LIMIT 1;

    IF v_manager_id IS NOT NULL THEN
      manager_user_id := v_manager_id;
      resolution_source := CASE
        WHEN v_walk_org_id = p_context_org_id THEN 'branch_manager'
        ELSE 'tree_walk_branch_manager'
      END;
      RETURN NEXT;
      RETURN;
    END IF;

    -- Walk up the org tree
    SELECT o.parent_organization_id INTO v_parent_org_id
    FROM public.organizations o
    WHERE o.id = v_walk_org_id;

    -- No parent or reached the root -- stop walking
    IF v_parent_org_id IS NULL THEN
      EXIT;
    END IF;

    v_walk_org_id := v_parent_org_id;
  END LOOP;

  -- ── Step 5: No manager found ──
  RETURN;
END;
$function$;
COMMENT ON FUNCTION "public"."resolve_manager_for_user"(p_user_id uuid, p_context_org_id uuid) IS '4-step manager resolver with org-tree walk fallback. Returns (manager_user_id, resolution_source). Steps: (1) branch-specific line_manager, (2) org-wide line_manager, (3) team lead, (4) branch_manager by role + tree walk. Returns zero rows if none found. SECURITY DEFINER for system-level consumers (speak-up, welfare). #224.';
REVOKE ALL ON FUNCTION "public"."resolve_manager_for_user"(p_user_id uuid, p_context_org_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."resolve_manager_for_user"(p_user_id uuid, p_context_org_id uuid) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."resolve_manager_for_user"(p_user_id uuid, p_context_org_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."resolve_manager_for_user"(p_user_id uuid, p_context_org_id uuid) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."resolve_manager_for_user"(p_user_id uuid, p_context_org_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."resolve_manager_for_user"(p_user_id uuid, p_context_org_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."resolve_operational_context"(p_lat double precision, p_lng double precision, p_org_id uuid, p_module_key text DEFAULT NULL::text, p_at timestamp with time zone DEFAULT now())
 RETURNS TABLE(in_operating_bounds boolean, out_of_bounds_district text, governing_jurisdiction_id uuid, governing_jurisdiction_name text, on_site boolean, site_id uuid, client_org_id uuid, matched_zone_id uuid, matched_module_key text, effective_rules jsonb, resolution_status text, governor_overlap_flag boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_point geometry := ST_SetSRID(ST_Point(p_lng, p_lat), 4326);
  v_direct record;
  v_contracted record;
  v_site record;
  v_blocked_status text;
BEGIN
  SELECT * INTO v_direct FROM public.resolve_context(p_lat, p_lng, p_org_id, p_module_key, p_at);
  IF v_direct.matched_zone_id IS NOT NULL OR v_direct.site_id IS NOT NULL THEN
    RETURN QUERY SELECT v_direct.in_operating_bounds, v_direct.out_of_bounds_district,
      v_direct.governing_jurisdiction_id, v_direct.governing_jurisdiction_name,
      v_direct.on_site, v_direct.site_id, v_direct.client_org_id,
      v_direct.matched_zone_id, v_direct.matched_module_key, v_direct.effective_rules,
      v_direct.resolution_status, v_direct.governor_overlap_flag;
    RETURN;
  END IF;

  SELECT rc.* INTO v_contracted
  FROM public.service_agreements sa
  JOIN public.service_agreement_modules sam
    ON sam.service_agreement_id = sa.id AND sam.enabled
   AND (p_module_key IS NULL OR sam.module_key = p_module_key)
  JOIN public.service_agreement_locations sal
    ON sal.service_agreement_id = sa.id AND sal.status = 'active'
  CROSS JOIN LATERAL public.resolve_context(p_lat, p_lng, sa.client_organization_id, p_module_key, p_at) rc
  WHERE sa.provider_organization_id = p_org_id
    AND (sa.starts_on IS NULL OR sa.starts_on <= p_at::date)
    AND (sa.ends_on IS NULL OR sa.ends_on >= p_at::date)
    AND rc.resolution_status = 'resolved'
    AND ((sal.zone_id IS NOT NULL AND sal.zone_id = rc.matched_zone_id)
      OR (sal.site_id IS NOT NULL AND sal.site_id = rc.site_id))
  ORDER BY CASE WHEN sal.zone_id = rc.matched_zone_id THEN 0 ELSE 1 END
  LIMIT 1;

  IF FOUND THEN
    RETURN QUERY SELECT true, NULL::text, v_contracted.governing_jurisdiction_id,
      v_contracted.governing_jurisdiction_name, v_contracted.on_site,
      v_contracted.site_id, v_contracted.client_org_id, v_contracted.matched_zone_id,
      v_contracted.matched_module_key, v_contracted.effective_rules,
      v_contracted.resolution_status, v_contracted.governor_overlap_flag;
    RETURN;
  END IF;

  SELECT cs.id AS site_id, COALESCE(l.organization_id, cs.client_organization_id) AS client_org_id
    INTO v_site
  FROM public.service_agreements sa
  JOIN public.service_agreement_modules sam
    ON sam.service_agreement_id = sa.id AND sam.enabled
   AND (p_module_key IS NULL OR sam.module_key = p_module_key)
  JOIN public.service_agreement_locations sal
    ON sal.service_agreement_id = sa.id AND sal.status = 'active' AND sal.site_id IS NOT NULL
  JOIN public.client_sites cs ON cs.id = sal.site_id AND cs.active
  LEFT JOIN public.locations l ON l.id = cs.location_id
  WHERE sa.provider_organization_id = p_org_id
    AND (sa.starts_on IS NULL OR sa.starts_on <= p_at::date)
    AND (sa.ends_on IS NULL OR sa.ends_on >= p_at::date)
    AND cs.boundary IS NOT NULL AND cs.boundary_verification = 'verified'
    AND ST_IsValid(cs.boundary) AND NOT ST_IsEmpty(cs.boundary) AND ST_Contains(cs.boundary, v_point)
  ORDER BY ST_Area(cs.boundary) ASC
  LIMIT 1;

  IF FOUND THEN
    RETURN QUERY SELECT true, NULL::text, v_direct.governing_jurisdiction_id,
      v_direct.governing_jurisdiction_name, true, v_site.site_id,
      v_site.client_org_id, NULL::uuid, p_module_key, '{}'::jsonb,
      'resolved'::text, v_direct.governor_overlap_flag;
    RETURN;
  END IF;

  SELECT candidate.status INTO v_blocked_status
  FROM (
    SELECT 'unresolved_unverified'::text AS status, 0 AS priority, ST_Area(z.boundary) AS area
    FROM public.service_agreements sa
    JOIN public.service_agreement_modules sam ON sam.service_agreement_id = sa.id AND sam.enabled
      AND (p_module_key IS NULL OR sam.module_key = p_module_key)
    JOIN public.service_agreement_locations sal ON sal.service_agreement_id = sa.id AND sal.status = 'active'
    JOIN public.location_zones z ON z.id = sal.zone_id AND z.is_active AND NOT z.is_verification_point
    WHERE sa.provider_organization_id = p_org_id
      AND (sa.starts_on IS NULL OR sa.starts_on <= p_at::date) AND (sa.ends_on IS NULL OR sa.ends_on >= p_at::date)
      AND z.boundary IS NOT NULL AND COALESCE(z.boundary_verification, 'unverified') <> 'verified'
      AND ST_IsValid(z.boundary) AND NOT ST_IsEmpty(z.boundary) AND ST_Contains(z.boundary, v_point)
      AND (p_module_key IS NULL OR z.module_key = p_module_key) AND public._geofence_active_at(z.active_schedule, p_at)
    UNION ALL
    SELECT 'unresolved_unverified'::text, 1, ST_Area(cs.boundary)
    FROM public.service_agreements sa
    JOIN public.service_agreement_modules sam ON sam.service_agreement_id = sa.id AND sam.enabled
      AND (p_module_key IS NULL OR sam.module_key = p_module_key)
    JOIN public.service_agreement_locations sal ON sal.service_agreement_id = sa.id AND sal.status = 'active'
    JOIN public.client_sites cs ON cs.id = sal.site_id AND cs.active
    WHERE sa.provider_organization_id = p_org_id
      AND (sa.starts_on IS NULL OR sa.starts_on <= p_at::date) AND (sa.ends_on IS NULL OR sa.ends_on >= p_at::date)
      AND cs.boundary IS NOT NULL AND COALESCE(cs.boundary_verification, 'unverified') <> 'verified'
      AND ST_IsValid(cs.boundary) AND NOT ST_IsEmpty(cs.boundary) AND ST_Contains(cs.boundary, v_point)
    UNION ALL
    SELECT 'unresolved_invalid'::text, 2, 0::double precision
    FROM public.service_agreements sa
    JOIN public.service_agreement_modules sam ON sam.service_agreement_id = sa.id AND sam.enabled
      AND (p_module_key IS NULL OR sam.module_key = p_module_key)
    JOIN public.service_agreement_locations sal ON sal.service_agreement_id = sa.id AND sal.status = 'active'
    JOIN public.location_zones z ON z.id = sal.zone_id AND z.is_active AND NOT z.is_verification_point
    WHERE sa.provider_organization_id = p_org_id
      AND (sa.starts_on IS NULL OR sa.starts_on <= p_at::date) AND (sa.ends_on IS NULL OR sa.ends_on >= p_at::date)
      AND z.boundary IS NOT NULL AND (NOT ST_IsValid(z.boundary) OR ST_IsEmpty(z.boundary))
      AND z.boundary && v_point AND (p_module_key IS NULL OR z.module_key = p_module_key)
    UNION ALL
    SELECT 'unresolved_invalid'::text, 3, 0::double precision
    FROM public.service_agreements sa
    JOIN public.service_agreement_modules sam ON sam.service_agreement_id = sa.id AND sam.enabled
      AND (p_module_key IS NULL OR sam.module_key = p_module_key)
    JOIN public.service_agreement_locations sal ON sal.service_agreement_id = sa.id AND sal.status = 'active'
    JOIN public.client_sites cs ON cs.id = sal.site_id AND cs.active
    WHERE sa.provider_organization_id = p_org_id
      AND (sa.starts_on IS NULL OR sa.starts_on <= p_at::date) AND (sa.ends_on IS NULL OR sa.ends_on >= p_at::date)
      AND cs.boundary IS NOT NULL AND (NOT ST_IsValid(cs.boundary) OR ST_IsEmpty(cs.boundary)) AND cs.boundary && v_point
  ) candidate
  ORDER BY candidate.priority, candidate.area
  LIMIT 1;

  IF v_blocked_status IS NOT NULL THEN
    RETURN QUERY SELECT v_direct.in_operating_bounds, v_direct.out_of_bounds_district,
      v_direct.governing_jurisdiction_id, v_direct.governing_jurisdiction_name,
      false, NULL::uuid, NULL::uuid, NULL::uuid, NULL::text, '{}'::jsonb,
      v_blocked_status, v_direct.governor_overlap_flag;
    RETURN;
  END IF;

  RETURN QUERY SELECT v_direct.in_operating_bounds, v_direct.out_of_bounds_district,
    v_direct.governing_jurisdiction_id, v_direct.governing_jurisdiction_name,
    v_direct.on_site, v_direct.site_id, v_direct.client_org_id,
    v_direct.matched_zone_id, v_direct.matched_module_key, v_direct.effective_rules,
    v_direct.resolution_status, v_direct.governor_overlap_flag;
END;
$function$;
COMMENT ON FUNCTION "public"."resolve_operational_context"(p_lat double precision, p_lng double precision, p_org_id uuid, p_module_key text, p_at timestamp with time zone) IS 'Field-operation resolver for direct and accepted contracted Site/Zone facets. Null starts_on is already in force; verified Zone wins, verified Site is the fallback, and blocked linked geometry preserves P1/P2 status.';
REVOKE ALL ON FUNCTION "public"."resolve_operational_context"(p_lat double precision, p_lng double precision, p_org_id uuid, p_module_key text, p_at timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."resolve_operational_context"(p_lat double precision, p_lng double precision, p_org_id uuid, p_module_key text, p_at timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."resolve_operational_context"(p_lat double precision, p_lng double precision, p_org_id uuid, p_module_key text, p_at timestamp with time zone) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."resolve_operational_context_authorized"(p_lat double precision, p_lng double precision, p_org_id uuid, p_module_key text DEFAULT NULL::text, p_at timestamp with time zone DEFAULT now())
 RETURNS TABLE(in_operating_bounds boolean, out_of_bounds_district text, governing_jurisdiction_id uuid, governing_jurisdiction_name text, on_site boolean, site_id uuid, client_org_id uuid, matched_zone_id uuid, matched_module_key text, effective_rules jsonb, resolution_status text, governor_overlap_flag boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL OR NOT public.org_access_allowed(p_org_id) THEN
    RAISE EXCEPTION 'Operational geofence context access denied';
  END IF;
  RETURN QUERY SELECT * FROM public.resolve_operational_context(p_lat, p_lng, p_org_id, p_module_key, p_at);
END;
$function$;
COMMENT ON FUNCTION "public"."resolve_operational_context_authorized"(p_lat double precision, p_lng double precision, p_org_id uuid, p_module_key text, p_at timestamp with time zone) IS 'Authenticated tenant-scoped wrapper for operational Site/Zone GPS resolution across accepted service agreements.';
REVOKE ALL ON FUNCTION "public"."resolve_operational_context_authorized"(p_lat double precision, p_lng double precision, p_org_id uuid, p_module_key text, p_at timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."resolve_operational_context_authorized"(p_lat double precision, p_lng double precision, p_org_id uuid, p_module_key text, p_at timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."resolve_operational_context_authorized"(p_lat double precision, p_lng double precision, p_org_id uuid, p_module_key text, p_at timestamp with time zone) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."resolve_operational_context_authorized"(p_lat double precision, p_lng double precision, p_org_id uuid, p_module_key text, p_at timestamp with time zone) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."resolve_or_create_dispatch_place_site"(p_provider_organization_id uuid, p_client_organization_id uuid, p_name text, p_address text, p_lat double precision, p_lng double precision, p_actor uuid DEFAULT auth.uid())
 RETURNS TABLE(site_id uuid, location_id uuid, site_created boolean, house_action text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_address text := nullif(trim(coalesce(p_address, '')), '');
  v_name text := coalesce(nullif(trim(coalesce(p_name, '')), ''), nullif(trim(coalesce(p_address, '')), ''));
  v_key text;
  v_site public.client_sites%rowtype;
  v_house_id uuid;
  v_house_action text;
  v_signals jsonb := NULL;
  v_ownership text := 'resolved';
BEGIN
  IF p_client_organization_id IS NULL OR NOT EXISTS (SELECT 1 FROM public.organizations o WHERE o.id = p_client_organization_id) THEN
    RAISE EXCEPTION 'Place owner organisation not found';
  END IF;
  IF v_address IS NULL OR char_length(v_address) < 4 OR char_length(v_address) > 500 THEN RAISE EXCEPTION 'A complete place address is required'; END IF;
  IF p_lat IS NULL OR p_lng IS NULL OR p_lat NOT BETWEEN -90 AND 90 OR p_lng NOT BETWEEN -180 AND 180 THEN RAISE EXCEPTION 'Resolve the place address before recording it'; END IF;
  v_key := regexp_replace(lower(v_address), '[^a-z0-9]+', '', 'g');

  -- House first (LOCATION_HOUSE_MODEL). Same key normalisation as manage_crm_location and the site facet.
  SELECT h.id INTO v_house_id FROM public.locations h WHERE h.organization_id = p_client_organization_id AND h.address_match_key = v_key ORDER BY h.created_at LIMIT 1;
  IF v_house_id IS NOT NULL THEN
    v_house_action := 'existing_house';
  ELSIF EXISTS (SELECT 1 FROM public.locations h WHERE h.address_match_key = v_key) THEN
    -- A house at this address exists under another organisation: never jump ownership, never fork the
    -- house. The facet is created without a house and flagged for human review (loud, non-blocking).
    v_house_action := 'other_org_house';
    v_ownership := 'needs_review';
    v_signals := jsonb_build_object('house_conflict', 'other_org_house', 'address_match_key', v_key, 'flagged_at', now());
  ELSE
    INSERT INTO public.locations (organization_id, name, address, address_match_key, created_by)
    VALUES (p_client_organization_id, v_name, v_address, v_key, p_actor) RETURNING id INTO v_house_id;
    v_house_action := 'created_house';
    INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
    VALUES (p_provider_organization_id, p_actor, 'dispatch_place_house_created', 'locations', v_house_id,
      jsonb_build_object('owner_organization_id', p_client_organization_id, 'address_match_key', v_key));
  END IF;

  SELECT * INTO v_site FROM public.client_sites cs
  WHERE cs.client_organization_id = p_client_organization_id AND cs.address_match_key = v_key
  ORDER BY cs.active DESC, cs.created_at LIMIT 1 FOR UPDATE;
  IF FOUND THEN
    IF v_site.location_id IS NULL AND v_house_id IS NOT NULL THEN
      UPDATE public.client_sites SET location_id = v_house_id WHERE id = v_site.id;
    END IF;
    RETURN QUERY SELECT v_site.id, COALESCE(v_site.location_id, v_house_id), false, v_house_action;
    RETURN;
  END IF;

  INSERT INTO public.client_sites (client_organization_id, organization_id, location_id, name, address, address_match_key, site_type, active,
    site_origin, boundary_status, boundary_verification, center_point, ownership_status, ownership_signals)
  VALUES (p_client_organization_id, p_provider_organization_id, v_house_id, v_name, v_address, v_key, 'other', true,
    'adhoc', 'provisional', 'unverified', ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326), v_ownership, v_signals)
  RETURNING * INTO v_site;
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (p_provider_organization_id, p_actor, 'dispatch_place_site_created', 'client_sites', v_site.id,
    jsonb_build_object('owner_organization_id', p_client_organization_id, 'address_match_key', v_key, 'house_action', v_house_action,
      'location_id', v_house_id, 'boundary_status', 'provisional', 'boundary_verification', 'unverified', 'center_source', 'resolved_address'));
  RETURN QUERY SELECT v_site.id, v_house_id, true, v_house_action;
END;
$function$;
COMMENT ON FUNCTION "public"."resolve_or_create_dispatch_place_site"(p_provider_organization_id uuid, p_client_organization_id uuid, p_name text, p_address text, p_lat double precision, p_lng double precision, p_actor uuid) IS 'Resolve-or-create the client_sites facet (and its locations house) for a place a dispatch job points at. Dedup by address_match_key within the owner org; a house under another org is flagged needs_review, never reused or forked. Provisional centre, unverified boundary. Internal: called by create_dispatch_intake_job and set_dispatch_job_harmed_party.';
REVOKE ALL ON FUNCTION "public"."resolve_or_create_dispatch_place_site"(p_provider_organization_id uuid, p_client_organization_id uuid, p_name text, p_address text, p_lat double precision, p_lng double precision, p_actor uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."resolve_or_create_dispatch_place_site"(p_provider_organization_id uuid, p_client_organization_id uuid, p_name text, p_address text, p_lat double precision, p_lng double precision, p_actor uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."resolve_or_create_dispatch_place_site"(p_provider_organization_id uuid, p_client_organization_id uuid, p_name text, p_address text, p_lat double precision, p_lng double precision, p_actor uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."resolve_org_invitation"(p_target_organization_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_profile public.user_profiles%rowtype;
  v_target public.organizations%rowtype;
  v_agreement public.service_agreements%rowtype;
  v_scope uuid[];
begin
  select * into v_profile from public.user_profiles where id = v_actor and deactivated_at is null;
  if not found or v_profile.role not in ('grand_master', 'master', 'admin', 'admin_officer') then raise exception 'Not authorised to invite users for this organisation'; end if;
  select * into v_target from public.organizations where id = p_target_organization_id;
  if not found then raise exception 'Organisation not found'; end if;

  -- own organisation: a master seats the first user of their own organisation (bootstrap only; claim_first_org_user refuses a second)
  if v_target.id = v_profile.organization_id and v_profile.role in ('grand_master', 'master') then
    return jsonb_build_object('kind', 'same_org', 'role', 'master', 'agreement_id', null, 'provider_organization_id', v_target.id, 'invitation_status', null);
  end if;

  -- reach: the employing organisation and its branches, plus any branch the actor is authorised at
  v_scope := public.get_descendant_organizations(coalesce(v_profile.employer_organization_id, v_profile.organization_id))
    || coalesce((select array_agg(a.branch_org_id) from public.staff_branch_authorisations a where a.user_id = v_actor and a.status = 'active'), '{}'::uuid[]);

  -- a client of the actor's provider under an operational agreement: the client's first user runs the client portal
  select a.* into v_agreement
  from public.service_agreements a
  where a.client_organization_id = v_target.id
    and a.agreement_type = 'operational'
    and a.provider_organization_id = any(v_scope)
    and (a.ends_on is null or a.ends_on >= current_date)
    and public.is_admin_for_org(a.provider_organization_id)
  order by case a.invitation_status when 'invited' then 0 when 'not_invited' then 1 when 'accepted' then 2 else 3 end, a.created_at desc
  limit 1;
  if found then
    return jsonb_build_object('kind', 'client', 'role', 'client_admin', 'agreement_id', v_agreement.id, 'provider_organization_id', v_agreement.provider_organization_id, 'invitation_status', v_agreement.invitation_status);
  end if;

  -- a platform subscriber under the owner's financial agreement: the subscriber's first master (owner ruling 2026-09-15)
  if v_profile.role = 'grand_master' then
    select a.* into v_agreement
    from public.service_agreements a
    where a.client_organization_id = v_target.id
      and a.agreement_type = 'financial'
      and a.provider_organization_id = any(v_scope)
      and (a.ends_on is null or a.ends_on >= current_date)
    order by a.created_at desc
    limit 1;
    if found then
      return jsonb_build_object('kind', 'subscriber', 'role', 'master', 'agreement_id', v_agreement.id, 'provider_organization_id', v_agreement.provider_organization_id, 'invitation_status', v_agreement.invitation_status);
    end if;
  end if;

  raise exception 'Not authorised to invite users for this organisation';
end;
$function$;
COMMENT ON FUNCTION "public"."resolve_org_invitation"(p_target_organization_id uuid) IS 'For invite-org: which agreement authorises the caller to seat the first user of the target organisation and which role that user gets (client_admin under an operational agreement; master for a platform subscriber or own-org bootstrap). Raises when not authorised.';
REVOKE ALL ON FUNCTION "public"."resolve_org_invitation"(p_target_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."resolve_org_invitation"(p_target_organization_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."resolve_org_invitation"(p_target_organization_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."resolve_org_invitation"(p_target_organization_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."resolve_patrol_stop_charge_line"(p_charge_line_id uuid, p_client_request_id uuid)
 RETURNS patrol_stop_charge_lines
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_line public.patrol_stop_charge_lines%ROWTYPE;
BEGIN
  IF p_client_request_id IS NULL THEN RAISE EXCEPTION 'client_request_id is required'; END IF;
  SELECT * INTO v_line FROM public.patrol_stop_charge_lines WHERE id = p_charge_line_id;
  IF NOT FOUND OR NOT public.is_admin_for_org(v_line.organization_id) THEN
    RAISE EXCEPTION 'Finance administrator access required';
  END IF;
  v_line := public.resolve_patrol_stop_charge_line_internal(v_line.shift_stop_id);
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_line.organization_id, auth.uid(), 'patrol_stop_charge_rechecked', 'patrol_stop_charge_lines', v_line.id,
    jsonb_build_object('client_request_id', p_client_request_id, 'status', v_line.status, 'line_total', v_line.line_total));
  RETURN v_line;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."resolve_patrol_stop_charge_line"(p_charge_line_id uuid, p_client_request_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."resolve_patrol_stop_charge_line"(p_charge_line_id uuid, p_client_request_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."resolve_patrol_stop_charge_line"(p_charge_line_id uuid, p_client_request_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."resolve_patrol_stop_charge_line"(p_charge_line_id uuid, p_client_request_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."resolve_patrol_stop_charge_line_internal"(p_stop_id uuid)
 RETURNS patrol_stop_charge_lines
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_stop public.shift_stops%ROWTYPE;
  v_shift public.shifts%ROWTYPE;
  v_existing public.patrol_stop_charge_lines%ROWTYPE;
  v_line public.patrol_stop_charge_lines%ROWTYPE;
  v_agreement_id uuid;
  v_client_id uuid;
  v_rate_id uuid;
  v_rate numeric;
  v_rule_type text;
  v_over_by integer := 0;
  v_discount numeric := 0;
  v_base numeric;
  v_total numeric;
  v_status text;
  v_description text;
BEGIN
  SELECT * INTO v_stop FROM public.shift_stops WHERE id = p_stop_id;
  IF NOT FOUND OR v_stop.status <> 'completed' OR v_stop.is_adhoc OR v_stop.dispatch_job_id IS NOT NULL THEN
    RAISE EXCEPTION 'A completed contracted patrol stop is required';
  END IF;
  SELECT * INTO v_shift FROM public.shifts WHERE id = v_stop.shift_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Patrol shift not found'; END IF;
  SELECT * INTO v_existing FROM public.patrol_stop_charge_lines WHERE shift_stop_id = p_stop_id FOR UPDATE;
  IF FOUND AND v_existing.invoice_line_item_id IS NOT NULL THEN RETURN v_existing; END IF;

  SELECT location.service_agreement_id, agreement.client_organization_id
    INTO v_agreement_id, v_client_id
  FROM public.service_agreement_locations location
  JOIN public.service_agreements agreement ON agreement.id = location.service_agreement_id
  WHERE location.id = v_shift.service_agreement_location_id
    AND location.status = 'active';

  IF v_agreement_id IS NULL THEN
    v_status := 'unresolved_agreement';
    v_description := 'Unresolved: patrol shift has no active client service agreement';
  ELSE
    SELECT rate_rule_id, amount, rate_type INTO v_rate_id, v_rate, v_rule_type
    FROM public.resolve_rate_rule(
      v_stop.organization_id, 'billing', coalesce(v_stop.actual_departed_at, now()),
      v_shift.service_type, NULL, v_stop.module_key, v_client_id, v_stop.site_id, v_stop.zone_id,
      NULL, NULL, NULL, 'per_visit'
    );
    IF v_rate_id IS NULL THEN
      v_status := 'unresolved_rate';
      v_description := 'Unresolved: no active customer per-visit rate matched this completed patrol stop';
    ELSE
      v_base := round(v_rate, 2);
      IF v_stop.actual_arrived_at > v_stop.sla_arrive_by THEN
        v_over_by := ceil(extract(epoch FROM (v_stop.actual_arrived_at - v_stop.sla_arrive_by)) / 60)::integer;
        SELECT band.discount_pct INTO v_discount
        FROM public.sla_discount_bands band
        WHERE band.organization_id = v_stop.organization_id AND band.module_key = 'patrol'
          AND band.active AND (band.service_type IS NULL OR band.service_type = v_shift.service_type)
          AND v_over_by >= band.over_by_minutes_min
          AND (band.over_by_minutes_max IS NULL OR v_over_by <= band.over_by_minutes_max)
        ORDER BY (band.service_type IS NOT NULL) DESC, band.over_by_minutes_min DESC
        LIMIT 1;
      END IF;
      v_discount := coalesce(v_discount, 0);
      v_total := round(v_base * (1 - v_discount), 2);
      v_status := CASE WHEN v_discount = 1 THEN 'waived_sla' ELSE 'ready' END;
      v_description := CASE WHEN v_discount > 0
        THEN format('Patrol visit · %s%% SLA discount', round(v_discount * 100, 2))
        ELSE 'Completed contracted patrol visit' END;
    END IF;
  END IF;

  INSERT INTO public.patrol_stop_charge_lines (
    organization_id, shift_stop_id, shift_id, service_agreement_id, client_organization_id,
    rate_rule_id, module_key, service_type, status, description, quantity, unit_rate,
    base_amount, discount_pct, discount_amount, line_total, sla_over_by_minutes,
    created_at, updated_at
  ) VALUES (
    v_stop.organization_id, v_stop.id, v_shift.id, v_agreement_id, v_client_id,
    v_rate_id, v_stop.module_key, v_shift.service_type, v_status, v_description, 1,
    v_rate, v_base, v_discount, CASE WHEN v_base IS NULL THEN 0 ELSE round(v_base * v_discount, 2) END,
    v_total, v_over_by, now(), now()
  )
  ON CONFLICT (shift_stop_id) DO UPDATE SET
    service_agreement_id = EXCLUDED.service_agreement_id,
    client_organization_id = EXCLUDED.client_organization_id,
    rate_rule_id = EXCLUDED.rate_rule_id,
    service_type = EXCLUDED.service_type,
    status = EXCLUDED.status,
    description = EXCLUDED.description,
    unit_rate = EXCLUDED.unit_rate,
    base_amount = EXCLUDED.base_amount,
    discount_pct = EXCLUDED.discount_pct,
    discount_amount = EXCLUDED.discount_amount,
    line_total = EXCLUDED.line_total,
    sla_over_by_minutes = EXCLUDED.sla_over_by_minutes,
    updated_at = now()
  WHERE public.patrol_stop_charge_lines.invoice_line_item_id IS NULL
  RETURNING * INTO v_line;
  IF NOT FOUND THEN
    SELECT * INTO v_line FROM public.patrol_stop_charge_lines WHERE shift_stop_id = p_stop_id;
  END IF;
  RETURN v_line;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."resolve_patrol_stop_charge_line_internal"(p_stop_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."resolve_patrol_stop_charge_line_internal"(p_stop_id uuid) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."resolve_rate_rule"(p_organization_id uuid, p_rule_kind text, p_when timestamp with time zone, p_service_type text DEFAULT NULL::text, p_job_type text DEFAULT NULL::text, p_module_key text DEFAULT NULL::text, p_client_org_id uuid DEFAULT NULL::uuid, p_site_id uuid DEFAULT NULL::uuid, p_zone_id uuid DEFAULT NULL::uuid, p_role_code text DEFAULT NULL::text, p_distance_km numeric DEFAULT NULL::numeric, p_day_category text DEFAULT NULL::text, p_rate_type text DEFAULT NULL::text)
 RETURNS TABLE(rate_rule_id uuid, rate_type text, amount numeric, pay_code text, role_code text, region_code text, specificity integer, day_category text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_when date := (p_when at time zone 'Pacific/Auckland')::date;
  v_hour integer := extract(hour from (p_when at time zone 'Pacific/Auckland'));
  v_dow integer := extract(isodow from (p_when at time zone 'Pacific/Auckland'));
  v_day text;
begin
  if p_rule_kind not in ('pay', 'billing') then
    raise exception 'rule_kind must be pay or billing';
  end if;

  -- Callers holding the regional holiday calendar pass p_day_category explicitly.
  v_day := coalesce(
    p_day_category,
    case
      when v_hour >= 22 or v_hour < 6 then 'night'
      when v_dow >= 6 then 'weekend'
      else 'weekday'
    end
  );

  return query
  select
    r.id,
    r.rate_type,
    r.amount,
    r.pay_code,
    r.role_code,
    r.region_code,
    (
      (case when r.service_type is not null then 8 else 0 end) +
      (case when r.site_id is not null then 16 else 0 end) +
      (case when r.zone_id is not null then 12 else 0 end) +
      (case when r.client_org_id is not null then 10 else 0 end) +
      (case when r.job_type is not null then 6 else 0 end) +
      (case when r.module_key is not null then 6 else 0 end) +
      (case when r.role_code is not null then 4 else 0 end) +
      (case when r.day_category is not null then 4 else 0 end) +
      (case when r.distance_min_km is not null or r.distance_max_km is not null then 3 else 0 end)
    )::integer as specificity,
    v_day
  from public.rate_rules r
  where r.organization_id = p_organization_id
    and r.rule_kind = p_rule_kind
    and r.active = true
    and (r.effective_from is null or r.effective_from <= v_when)
    and (r.effective_to is null or r.effective_to >= v_when)
    and (p_rate_type is null or r.rate_type = p_rate_type)
    and (r.service_type is null or r.service_type = p_service_type)
    and (r.job_type is null or r.job_type = p_job_type)
    and (r.module_key is null or r.module_key = p_module_key)
    and (r.client_org_id is null or r.client_org_id = p_client_org_id)
    and (r.site_id is null or r.site_id = p_site_id)
    and (r.zone_id is null or r.zone_id = p_zone_id)
    and (r.role_code is null or r.role_code = p_role_code)
    and (r.day_category is null or r.day_category = v_day)
    and (r.distance_min_km is null or (p_distance_km is not null and p_distance_km >= r.distance_min_km))
    and (r.distance_max_km is null or (p_distance_km is not null and p_distance_km <= r.distance_max_km))
  order by specificity desc, r.priority desc, r.effective_from desc nulls last, r.updated_at desc
  limit 1;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."resolve_rate_rule"(p_organization_id uuid, p_rule_kind text, p_when timestamp with time zone, p_service_type text, p_job_type text, p_module_key text, p_client_org_id uuid, p_site_id uuid, p_zone_id uuid, p_role_code text, p_distance_km numeric, p_day_category text, p_rate_type text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."resolve_rate_rule"(p_organization_id uuid, p_rule_kind text, p_when timestamp with time zone, p_service_type text, p_job_type text, p_module_key text, p_client_org_id uuid, p_site_id uuid, p_zone_id uuid, p_role_code text, p_distance_km numeric, p_day_category text, p_rate_type text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."resolve_rate_rule"(p_organization_id uuid, p_rule_kind text, p_when timestamp with time zone, p_service_type text, p_job_type text, p_module_key text, p_client_org_id uuid, p_site_id uuid, p_zone_id uuid, p_role_code text, p_distance_km numeric, p_day_category text, p_rate_type text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."resolve_rate_rule"(p_organization_id uuid, p_rule_kind text, p_when timestamp with time zone, p_service_type text, p_job_type text, p_module_key text, p_client_org_id uuid, p_site_id uuid, p_zone_id uuid, p_role_code text, p_distance_km numeric, p_day_category text, p_rate_type text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."resolve_record_canonical_identity"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_plate text;
BEGIN
  IF TG_TABLE_NAME = 'observations' THEN
    NEW.canonical_place_id := public.ensure_canonical_place_for_projection(
      CASE WHEN NEW.location_id IS NOT NULL THEN 'locations' WHEN NEW.site_id IS NOT NULL THEN 'client_sites' ELSE 'location_zones' END,
      COALESCE(NEW.location_id, NEW.site_id, NEW.zone_id));
    NEW.canonical_person_id := public.ensure_canonical_person_for_record(NEW.person_record_id);
    v_plate := public.normalize_plate_number(NEW.plate_number);
    SELECT scv.id INTO NEW.canonical_scv_id
    FROM public.canonical_scv scv
    WHERE public.normalize_plate_number(scv.plate_number) = v_plate
    ORDER BY scv.updated_at DESC
    LIMIT 1;
    IF NEW.canonical_vehicle_id IS NULL THEN
      NEW.canonical_vehicle_id := public.ensure_canonical_vehicle(
        NEW.plate_number, NEW.vehicle_make, NEW.vehicle_model, NEW.vehicle_colour,
        'observations', NEW.id::text, NEW.observed_at);
    END IF;
  ELSIF TG_TABLE_NAME = 'parking_chalk_records' THEN
    IF NEW.canonical_vehicle_id IS NULL THEN
      NEW.canonical_vehicle_id := public.ensure_canonical_vehicle(
        NEW.plate, NEW.vehicle_make, NEW.vehicle_model, NEW.vehicle_colour,
        'parking_chalk_records', NEW.id::text, NEW.chalked_at);
    END IF;
  ELSIF TG_TABLE_NAME = 'incidents' THEN
    NEW.canonical_place_id := public.ensure_canonical_place_for_projection(
      CASE WHEN NEW.location_id IS NOT NULL THEN 'locations' WHEN NEW.client_site_id IS NOT NULL THEN 'client_sites' ELSE 'location_zones' END,
      COALESCE(NEW.location_id, NEW.client_site_id, NEW.zone_id));
  ELSIF TG_TABLE_NAME = 'officer_field_reports' THEN
    NEW.canonical_place_id := public.ensure_canonical_place_for_projection(
      CASE WHEN NEW.site_id IS NOT NULL THEN 'client_sites' ELSE 'location_zones' END,
      COALESCE(NEW.site_id, NEW.zone_id));
  ELSE
    NEW.canonical_place_id := public.ensure_canonical_place_for_projection(
      CASE WHEN NEW.client_site_id IS NOT NULL THEN 'client_sites' ELSE 'location_zones' END,
      COALESCE(NEW.client_site_id, NEW.zone_id));
  END IF;
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."resolve_record_canonical_identity"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."resolve_record_canonical_identity"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."resolve_record_canonical_identity"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."resolve_record_canonical_identity"() TO "anon";
GRANT EXECUTE ON FUNCTION "public"."resolve_record_canonical_identity"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."resolve_record_canonical_identity"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."resolve_retention_days"(p_org_id uuid, p_module_key text, p_category text)
 RETURNS integer
 LANGUAGE sql
 STABLE
AS $function$
  select retention_days
  from public.retention_policies
  where category = p_category
    and is_active
    and (
      (organization_id = p_org_id and module_key = p_module_key)
      or (organization_id = p_org_id and module_key is null)
      or (organization_id is null and module_key is null)
    )
  order by
    -- most specific wins: org+module, then org, then platform
    (organization_id is not null and module_key is not null) desc,
    (organization_id is not null) desc
  limit 1;
$function$;
COMMENT ON FUNCTION "public"."resolve_retention_days"(p_org_id uuid, p_module_key text, p_category text) IS 'Effective retention days for (org, module, category): module policy -> org default -> platform default. Drives observations.retention_until; periods are per-council, not hardcoded.';
REVOKE ALL ON FUNCTION "public"."resolve_retention_days"(p_org_id uuid, p_module_key text, p_category text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."resolve_retention_days"(p_org_id uuid, p_module_key text, p_category text) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."resolve_retention_days"(p_org_id uuid, p_module_key text, p_category text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."resolve_retention_days"(p_org_id uuid, p_module_key text, p_category text) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."resolve_retention_days"(p_org_id uuid, p_module_key text, p_category text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."resolve_retention_days"(p_org_id uuid, p_module_key text, p_category text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."resolve_verified_site_context"(p_lat double precision, p_lng double precision, p_client_org_ids uuid[])
 RETURNS TABLE(site_id uuid, site_name text, location_id uuid, client_organization_id uuid, match_kind text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with point as(select st_setsrid(st_point(p_lng,p_lat),4326) geometry)
  select s.id,s.name,s.location_id,s.client_organization_id,
    case when st_covers(s.boundary,p.geometry) then 'verified_boundary' else 'verified_onsite_radius' end
  from public.client_sites s cross join point p
  where s.client_organization_id=any(coalesce(p_client_org_ids,'{}'::uuid[]))
    and s.active
    and s.boundary is not null
    and s.boundary_verification='verified'
    and st_isvalid(s.boundary)
    and not st_isempty(s.boundary)
    and (st_covers(s.boundary,p.geometry) or st_dwithin(coalesce(s.center_point,s.boundary)::geography,p.geometry::geography,coalesce(s.onsite_radius_meters,10)))
  order by case when st_covers(s.boundary,p.geometry) then 0 else 1 end,st_area(s.boundary),s.name
  limit 1;
$function$;
COMMENT ON FUNCTION "public"."resolve_verified_site_context"(p_lat double precision, p_lng double precision, p_client_org_ids uuid[]) IS 'Service-only standalone Site resolver. Matches only active, valid, verified Site geometry within an already-authorized client organization scope; prefers polygon coverage over the configured on-site radius.';
REVOKE ALL ON FUNCTION "public"."resolve_verified_site_context"(p_lat double precision, p_lng double precision, p_client_org_ids uuid[]) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."resolve_verified_site_context"(p_lat double precision, p_lng double precision, p_client_org_ids uuid[]) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."resolve_verified_site_context"(p_lat double precision, p_lng double precision, p_client_org_ids uuid[]) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."resolve_verified_site_context"(p_lat double precision, p_lng double precision, p_client_org_ids uuid[], p_module_key text DEFAULT NULL::text, p_provider_org_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(site_id uuid, site_name text, location_id uuid, client_organization_id uuid, match_kind text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH point AS (
    SELECT st_setsrid(st_point(p_lng, p_lat), 4326) geometry
  )
  SELECT s.id, s.name, s.location_id, s.client_organization_id,
    CASE WHEN st_covers(s.boundary, p.geometry) THEN 'verified_boundary' ELSE 'verified_onsite_radius' END
  FROM public.client_sites s
  CROSS JOIN point p
  WHERE s.client_organization_id = ANY(coalesce(p_client_org_ids, '{}'::uuid[]))
    AND s.active
    AND s.boundary IS NOT NULL
    AND s.boundary_verification = 'verified'
    AND st_isvalid(s.boundary)
    AND NOT st_isempty(s.boundary)
    AND (
      st_covers(s.boundary, p.geometry)
      OR st_dwithin(coalesce(s.center_point, s.boundary)::geography, p.geometry::geography, coalesce(s.onsite_radius_meters, 10))
    )
    AND (
      p_module_key IS NULL
      OR EXISTS (
        SELECT 1
        FROM public.service_agreements sa
        JOIN public.service_agreement_modules sam ON sam.service_agreement_id = sa.id
          AND sam.enabled AND sam.module_key = p_module_key
        JOIN public.service_agreement_locations sal ON sal.service_agreement_id = sa.id
          AND sal.site_id = s.id AND sal.status = 'active'
        WHERE sa.client_organization_id = s.client_organization_id
          AND (p_provider_org_id IS NULL OR sa.provider_organization_id = p_provider_org_id)
          AND (sa.starts_on IS NULL OR sa.starts_on <= current_date)
          AND (sa.ends_on IS NULL OR sa.ends_on >= current_date)
      )
    )
  ORDER BY CASE WHEN st_covers(s.boundary, p.geometry) THEN 0 ELSE 1 END,
    st_area(s.boundary), s.name
  LIMIT 1;
$function$;
REVOKE ALL ON FUNCTION "public"."resolve_verified_site_context"(p_lat double precision, p_lng double precision, p_client_org_ids uuid[], p_module_key text, p_provider_org_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."resolve_verified_site_context"(p_lat double precision, p_lng double precision, p_client_org_ids uuid[], p_module_key text, p_provider_org_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."resolve_verified_site_context"(p_lat double precision, p_lng double precision, p_client_org_ids uuid[], p_module_key text, p_provider_org_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."respond_to_on_call_period"(p_period_id uuid, p_expected_status text, p_response text, p_decline_reason text DEFAULT NULL::text)
 RETURNS on_call_periods
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_period public.on_call_periods%rowtype;
  v_reason text := nullif(trim(coalesce(p_decline_reason, '')), '');
begin
  select p.* into v_period from public.on_call_periods p where p.id = p_period_id for update;
  if not found then
    raise exception 'On-call period not found';
  end if;

  if v_period.officer_user_id <> v_actor then
    raise exception 'Only the assigned officer can respond to this on-call period';
  end if;

  if v_period.status <> p_expected_status then
    raise exception 'On-call period changed from expected status % to %', p_expected_status, v_period.status;
  end if;

  if v_period.status <> 'pending' then
    raise exception 'Only pending on-call periods can be answered';
  end if;

  if p_response not in ('accepted', 'declined') then
    raise exception 'Response must be accepted or declined';
  end if;

  if p_response = 'declined' and v_reason is null then
    raise exception 'A decline reason is required';
  end if;

  update public.on_call_periods
  set status = p_response, decline_reason = v_reason, responded_at = now()
  where id = v_period.id
  returning * into v_period;

  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (
    v_period.organization_id, v_actor, 'on_call_period_answered', 'on_call_periods', v_period.id,
    jsonb_build_object('response', p_response, 'decline_reason', v_reason)
  );

  return v_period;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."respond_to_on_call_period"(p_period_id uuid, p_expected_status text, p_response text, p_decline_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."respond_to_on_call_period"(p_period_id uuid, p_expected_status text, p_response text, p_decline_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."respond_to_on_call_period"(p_period_id uuid, p_expected_status text, p_response text, p_decline_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."respond_to_on_call_period"(p_period_id uuid, p_expected_status text, p_response text, p_decline_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."respond_to_overtime_offer"(p_offer_id uuid, p_expected_status text, p_response text, p_decline_reason text DEFAULT NULL::text)
 RETURNS overtime_offers
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_offer public.overtime_offers%rowtype;
  v_slot public.roster_slots%rowtype;
  v_unit public.roster_work_units%rowtype;
  v_staff public.staff_profiles%rowtype;
  v_reason text := nullif(trim(coalesce(p_decline_reason, '')), '');
begin
  select o.* into v_offer
  from public.overtime_offers o
  where o.id = p_offer_id
  for update;
  if not found then
    raise exception 'Overtime offer not found';
  end if;

  select sp.* into v_staff
  from public.staff_profiles sp
  where sp.id = v_offer.staff_id
    and sp.work_ready
    and (sp.user_id = v_actor or sp.id = v_actor);
  if not found then
    raise exception 'Only the offered work-ready staff member can respond';
  end if;

  if v_offer.status <> p_expected_status then
    raise exception 'Overtime offer changed from expected status % to %', p_expected_status, v_offer.status;
  end if;
  if v_offer.status <> 'offered' then
    raise exception 'Only open overtime offers can be answered';
  end if;
  if v_offer.expires_at < now() then
    update public.overtime_offers
    set status = 'expired'
    where id = v_offer.id
    returning * into v_offer;
    raise exception 'This overtime offer has expired';
  end if;
  if p_response not in ('accepted', 'declined') then
    raise exception 'Response must be accepted or declined';
  end if;

  if p_response = 'declined' then
    update public.overtime_offers
    set status = 'declined',
        decline_reason = v_reason,
        responded_at = now()
    where id = v_offer.id
    returning * into v_offer;
  else
    select s.* into v_slot
    from public.roster_slots s
    where s.id = v_offer.roster_slot_id
    for update;
    if not found or v_slot.status not in ('draft', 'published', 'declined') then
      raise exception 'Roster slot is no longer available';
    end if;

    select u.* into v_unit
    from public.roster_work_units u
    where u.id = v_slot.work_unit_id
      and u.organization_id = v_slot.organization_id
      and u.active;
    if not found then
      raise exception 'Active work unit not found';
    end if;

    if exists (
      select 1
      from public.roster_slots s
      where s.id <> v_slot.id
        and s.staff_id = v_staff.id
        and s.status not in ('declined', 'cancelled')
        and s.scheduled_start < v_slot.scheduled_end
        and s.scheduled_end > v_slot.scheduled_start
    ) then
      raise exception 'Staff member already has an overlapping roster slot';
    end if;

    update public.roster_slots
    set staff_id = v_offer.staff_id,
        status = 'accepted'
    where id = v_slot.id
    returning * into v_slot;

    if v_unit.work_unit_type in ('patrol', 'static') then
      perform public.materialize_roster_slot_core(v_slot.id, 'accepted');
      select s.* into v_slot
      from public.roster_slots s
      where s.id = v_slot.id;
    end if;

    update public.overtime_offers
    set status = 'accepted',
        responded_at = now()
    where id = v_offer.id
    returning * into v_offer;

    update public.overtime_offers
    set status = 'withdrawn'
    where roster_slot_id = v_offer.roster_slot_id
      and status = 'offered'
      and id <> v_offer.id;
  end if;

  insert into public.audit_log (
    organization_id,
    actor_user_id,
    action,
    target_table,
    target_id,
    metadata
  )
  values (
    v_offer.organization_id,
    v_actor,
    'overtime_offer_answered',
    'overtime_offers',
    v_offer.id,
    jsonb_build_object(
      'response', p_response,
      'roster_slot_id', v_offer.roster_slot_id,
      'seniority_position', v_offer.seniority_position,
      'decline_reason', v_reason,
      'linked_shift_id', v_slot.linked_shift_id
    )
  );

  return v_offer;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."respond_to_overtime_offer"(p_offer_id uuid, p_expected_status text, p_response text, p_decline_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."respond_to_overtime_offer"(p_offer_id uuid, p_expected_status text, p_response text, p_decline_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."respond_to_overtime_offer"(p_offer_id uuid, p_expected_status text, p_response text, p_decline_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."respond_to_overtime_offer"(p_offer_id uuid, p_expected_status text, p_response text, p_decline_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."respond_to_roster_slot"(p_slot_id uuid, p_expected_status text, p_response text, p_decline_reason text DEFAULT NULL::text)
 RETURNS TABLE(slot_id uuid, slot_status text, shift_id uuid, shift_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_user uuid:=auth.uid();v_slot public.roster_slots%rowtype;v_staff public.staff_profiles%rowtype;v_next text;v_shift_status text;
begin
  if v_user is null then raise exception 'Authentication required';end if;
  select s.* into v_slot from public.roster_slots s where s.id=p_slot_id for update;if not found then raise exception 'Roster slot not found';end if;
  select sp.* into v_staff from public.staff_profiles sp where sp.id=v_slot.staff_id and (sp.user_id=v_user or sp.id=v_user);if not found then raise exception 'Roster slot does not belong to the authenticated staff member';end if;
  if v_slot.status<>p_expected_status then raise exception 'Roster slot changed from expected status % to %',p_expected_status,v_slot.status;end if;
  if v_slot.status<>'published' then raise exception 'Only published roster slots can be accepted or declined';end if;
  if p_response='accept' then v_next:='accepted';elsif p_response='decline' then if nullif(trim(coalesce(p_decline_reason,'')),'') is null then raise exception 'Decline reason is required';end if;v_next:='declined';else raise exception 'Unsupported roster response';end if;
  if v_slot.linked_shift_id is not null then
    select s.status into v_shift_status from public.shifts s where s.id=v_slot.linked_shift_id for update;
    if v_shift_status is null then raise exception 'Linked field shift not found';end if;
    if v_shift_status<>'published' then raise exception 'Linked field shift changed from expected status published to %',v_shift_status;end if;
    update public.shifts set status=v_next where id=v_slot.linked_shift_id returning status into v_shift_status;
  end if;
  update public.roster_slots set status=v_next,notes=case when v_next='declined' then concat_ws(E'\n',nullif(notes,''),'Declined: '||trim(p_decline_reason)) else notes end where id=v_slot.id returning * into v_slot;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
  values(v_slot.organization_id,v_user,case when v_next='accepted' then 'roster_slot_accepted' else 'roster_slot_declined' end,'roster_slots',v_slot.id,jsonb_build_object('linked_shift_id',v_slot.linked_shift_id,'decline_reason',case when v_next='declined' then trim(p_decline_reason) else null end));
  return query select v_slot.id,v_slot.status,v_slot.linked_shift_id,v_shift_status;
end;$function$;
REVOKE ALL ON FUNCTION "public"."respond_to_roster_slot"(p_slot_id uuid, p_expected_status text, p_response text, p_decline_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."respond_to_roster_slot"(p_slot_id uuid, p_expected_status text, p_response text, p_decline_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."respond_to_roster_slot"(p_slot_id uuid, p_expected_status text, p_response text, p_decline_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."respond_to_roster_slot"(p_slot_id uuid, p_expected_status text, p_response text, p_decline_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."resubmit_rejected_timesheet_from_work"(p_timesheet_id uuid, p_adjustment_hours numeric DEFAULT 0, p_notes text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, submitted_at timestamp with time zone, actual_hours numeric, source_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
declare
  v_actor uuid := auth.uid();
  v_staff public.staff_profiles%rowtype;
  v_sheet public.timesheets%rowtype;
  v_work record;
  v_minutes integer := 0;
  v_count integer := 0;
  v_actual numeric;
  v_entries jsonb := '[]'::jsonb;
begin
  if v_actor is null then raise exception 'Authentication required'; end if;
  select t.* into v_sheet from public.timesheets t where t.id = p_timesheet_id for update;
  if not found then raise exception 'Timesheet not found'; end if;
  select sp.* into v_staff from public.staff_profiles sp where (sp.user_id = v_actor or sp.id = v_actor) and sp.id = v_sheet.staff_id and sp.organization_id = v_sheet.organization_id;
  if not found then raise exception 'Only the timesheet owner can resubmit it'; end if;
  if v_sheet.status <> 'rejected' then raise exception 'Only rejected timesheets can be resubmitted'; end if;
  if p_adjustment_hours < -744 or p_adjustment_hours > 744 then raise exception 'Adjustment hours are outside the accepted range'; end if;

  for v_work in select * from public.get_officer_timesheet_work(v_sheet.period_start, v_sheet.period_end) loop
    v_minutes := v_minutes + v_work.calculated_minutes;
    v_count := v_count + 1;
    v_entries := v_entries || jsonb_build_array(jsonb_build_object('source_type', v_work.source_type, 'source_id', v_work.source_id, 'work_status', v_work.work_status, 'started_at', v_work.started_at, 'ended_at', v_work.ended_at, 'calculated_minutes', v_work.calculated_minutes, 'label', v_work.label, 'metadata', v_work.metadata));
  end loop;
  v_actual := round((v_minutes::numeric / 60) + coalesce(p_adjustment_hours, 0), 2);
  if v_actual < 0 or v_actual > 744 then raise exception 'Derived actual hours are outside the accepted range'; end if;

  delete from public.timesheet_work_entries where timesheet_id = v_sheet.id;
  update public.timesheets set actual_hours = v_actual, overtime_hours = greatest(0, v_actual - coalesce(scheduled_hours, 0)), adjustment_hours = coalesce(p_adjustment_hours, 0), work_derived_hours = round(v_minutes::numeric / 60, 2), work_summary = jsonb_build_object('source_count', v_count, 'work_minutes', v_minutes, 'entries', v_entries), status = 'submitted', review_notes = nullif(trim(coalesce(p_notes, '')), ''), submitted_at = clock_timestamp(), approved_by = null, approved_at = null where id = v_sheet.id returning * into v_sheet;

  for v_work in select value from jsonb_array_elements(v_entries) loop
    insert into public.timesheet_work_entries (organization_id, timesheet_id, source_type, source_id, work_status, started_at, ended_at, calculated_minutes, metadata) values (v_sheet.organization_id, v_sheet.id, (v_work.value)->>'source_type', ((v_work.value)->>'source_id')::uuid, (v_work.value)->>'work_status', ((v_work.value)->>'started_at')::timestamptz, ((v_work.value)->>'ended_at')::timestamptz, ((v_work.value)->>'calculated_minutes')::integer, coalesce((v_work.value)->'metadata', '{}'::jsonb));
  end loop;

  insert into public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata) values (v_sheet.organization_id, v_actor, 'timesheet_resubmitted_after_correction', 'timesheets', v_sheet.id, jsonb_build_object('actual_hours', v_actual, 'adjustment_hours', p_adjustment_hours, 'source_count', v_count, 'prior_status', 'rejected'));
  return query select v_sheet.id, v_sheet.submitted_at, v_sheet.actual_hours, v_count;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."resubmit_rejected_timesheet_from_work"(p_timesheet_id uuid, p_adjustment_hours numeric, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."resubmit_rejected_timesheet_from_work"(p_timesheet_id uuid, p_adjustment_hours numeric, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."resubmit_rejected_timesheet_from_work"(p_timesheet_id uuid, p_adjustment_hours numeric, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."resubmit_rejected_timesheet_from_work"(p_timesheet_id uuid, p_adjustment_hours numeric, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."resume_cctv_inference_claims"(p_holder text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' AND session_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;
  DELETE FROM public.cctv_inference_claim_pauses WHERE holder = p_holder;
  RETURN FOUND;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."resume_cctv_inference_claims"(p_holder text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."resume_cctv_inference_claims"(p_holder text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."resume_cctv_inference_claims"(p_holder text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."retire_person_alias"(p_alias_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_alias public.person_record_aliases%rowtype;
BEGIN
  SELECT * INTO v_alias FROM public.person_record_aliases WHERE id = p_alias_id AND active FOR UPDATE;
  IF v_actor IS NULL OR v_alias.id IS NULL OR NOT public.org_access_allowed(v_alias.organization_id) THEN
    RAISE EXCEPTION 'Name not found in your authorised scope';
  END IF;
  IF v_alias.created_by IS DISTINCT FROM v_actor AND NOT public.is_admin_for_org(v_alias.organization_id) THEN
    RAISE EXCEPTION 'Only the person who added this name or an administrator can remove it';
  END IF;
  IF coalesce(trim(p_reason), '') = '' THEN RAISE EXCEPTION 'A reason is required'; END IF;
  UPDATE public.person_record_aliases SET active = false, retired_at = clock_timestamp(), retired_by = v_actor, retired_reason = trim(p_reason)
  WHERE id = v_alias.id;
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_alias.organization_id, v_actor, 'person_alias_retired', 'person_record_aliases', v_alias.id,
    jsonb_build_object('person_record_id', v_alias.person_record_id, 'reason', trim(p_reason)));
END;
$function$;
REVOKE ALL ON FUNCTION "public"."retire_person_alias"(p_alias_id uuid, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."retire_person_alias"(p_alias_id uuid, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."retire_person_alias"(p_alias_id uuid, p_reason text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."return_shift_asset"(p_link_id uuid, p_condition text DEFAULT 'good'::text, p_odometer_reading integer DEFAULT NULL::integer, p_fuel_level text DEFAULT NULL::text, p_defects_noted text DEFAULT NULL::text)
 RETURNS shift_assets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_link public.shift_assets%rowtype;
begin
  select l.* into v_link from public.shift_assets l where l.id = p_link_id for update;
  if not found then
    raise exception 'Shift asset assignment not found';
  end if;

  if not public.is_admin_for_org(v_link.organization_id)
     and not exists (select 1 from public.shifts s where s.id = v_link.shift_id and s.officer_user_id = v_actor) then
    raise exception 'Not authorised to return this asset';
  end if;

  if v_link.returned_at is not null then
    return v_link;
  end if;

  if p_condition not in ('good', 'minor_issue', 'major_issue', 'unserviceable') then
    raise exception 'Unsupported asset condition';
  end if;

  if p_fuel_level is not null and p_fuel_level not in ('full', 'three_quarter', 'half', 'quarter', 'empty') then
    raise exception 'Unsupported fuel level';
  end if;

  update public.shift_assets set returned_at = now() where id = v_link.id returning * into v_link;

  insert into public.asset_checks(
    organization_id, asset_id, checked_by, check_type, condition,
    odometer_reading, fuel_level, defects_noted
  )
  values (
    v_link.organization_id, v_link.asset_id, v_actor, 'post_shift', p_condition,
    p_odometer_reading, p_fuel_level, nullif(trim(coalesce(p_defects_noted, '')), '')
  );

  update public.assets
  set
    status = case when p_condition in ('major_issue', 'unserviceable') then 'maintenance' else 'available' end,
    assigned_to = null,
    last_inspection_date = current_date
  where id = v_link.asset_id;

  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (
    v_link.organization_id, v_actor, 'shift_asset_returned', 'shift_assets', v_link.id,
    jsonb_build_object(
      'asset_id', v_link.asset_id,
      'condition', p_condition,
      'odometer_reading', p_odometer_reading,
      'fuel_level', p_fuel_level,
      'defects_noted', p_defects_noted
    )
  );

  return v_link;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."return_shift_asset"(p_link_id uuid, p_condition text, p_odometer_reading integer, p_fuel_level text, p_defects_noted text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."return_shift_asset"(p_link_id uuid, p_condition text, p_odometer_reading integer, p_fuel_level text, p_defects_noted text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."return_shift_asset"(p_link_id uuid, p_condition text, p_odometer_reading integer, p_fuel_level text, p_defects_noted text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."return_shift_asset"(p_link_id uuid, p_condition text, p_odometer_reading integer, p_fuel_level text, p_defects_noted text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."reveal_nzta_registered_person"(p_subject_type text, p_subject_id uuid, p_purpose text, p_explanation text, p_organization_id uuid DEFAULT NULL::uuid, p_lookup_id uuid DEFAULT NULL::uuid, p_notice_id uuid DEFAULT NULL::uuid, p_observation_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_orgs uuid[];
  v_org uuid;
  v_notice_org uuid;
  v_notice uuid := CASE WHEN p_purpose = 'notice_follow_up' THEN p_notice_id END;
  v_ready jsonb;
  v_expires timestamptz := clock_timestamp() + interval '15 minutes';
  v_warnings text[] := ARRAY[]::text[];
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Sign in required' USING ERRCODE = '42501'; END IF;
  IF p_subject_type IS NULL OR p_subject_type NOT IN ('vehicle', 'person') OR p_subject_id IS NULL THEN
    RAISE EXCEPTION 'Choose the vehicle or person to reveal';
  END IF;
  IF p_purpose IS NULL OR p_purpose NOT IN ('trespass_unpermitted_vehicle', 'cctv_patrol_signage_breach', 'notice_follow_up') THEN
    RAISE EXCEPTION 'Choose one of the authorised purposes';
  END IF;
  IF length(btrim(coalesce(p_explanation, ''))) < 10 THEN
    RAISE EXCEPTION 'Explain why you need this information (at least 10 characters)';
  END IF;
  IF p_purpose = 'notice_follow_up' AND p_notice_id IS NULL THEN
    RAISE EXCEPTION 'Choose the notice you are following up';
  END IF;
  IF p_purpose = 'notice_follow_up' THEN
    -- The notice justifies a window only in the organisation it was issued by.
    SELECT notice.organization_id INTO v_notice_org FROM public.notices notice
    WHERE notice.id = p_notice_id AND public.nzta_notice_matches_subject(notice.id, p_subject_type, p_subject_id);
    IF v_notice_org IS NULL THEN
      RAISE EXCEPTION 'Choose an issued trespass or warning notice for this %', p_subject_type;
    END IF;
    IF p_organization_id IS NOT NULL AND p_organization_id <> v_notice_org THEN
      RAISE EXCEPTION 'That notice was issued by another organisation';
    END IF;
    v_orgs := ARRAY[v_notice_org];
  ELSIF p_organization_id IS NOT NULL THEN
    v_orgs := ARRAY[p_organization_id];
  ELSIF p_subject_type = 'person' THEN
    v_orgs := array(
      SELECT DISTINCT c.organization_id FROM public.vehicle_identity_checks c WHERE c.canonical_person_id = p_subject_id
      UNION
      SELECT DISTINCT link.organization_id FROM public.entity_links link
      WHERE link.from_type = 'person' AND link.from_id = p_subject_id AND link.to_type = 'vehicle'
        AND coalesce((link.evidence->>'nzta_restricted')::boolean, false));
  ELSE
    RAISE EXCEPTION 'Choose the organisation for this vehicle';
  END IF;
  IF cardinality(v_orgs) = 0 THEN
    RAISE EXCEPTION 'No NZTA register information is recorded for this person';
  END IF;
  v_orgs := array(SELECT org_id FROM unnest(v_orgs) org_id WHERE public.can_access_vehicle_owner_identity(org_id));
  IF cardinality(v_orgs) = 0 THEN
    RAISE EXCEPTION 'NZTA register authorisation required' USING ERRCODE = '42501';
  END IF;
  IF p_lookup_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.nzta_register_lookups WHERE id = p_lookup_id AND organization_id = ANY (v_orgs)) THEN
    RAISE EXCEPTION 'That lookup is not in your authorised organisations';
  END IF;
  IF v_notice IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.notices WHERE id = v_notice AND organization_id = ANY (v_orgs)) THEN
    RAISE EXCEPTION 'That notice is not in your authorised organisations';
  END IF;
  IF p_observation_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.observations WHERE id = p_observation_id AND organization_id = ANY (v_orgs)) THEN
    RAISE EXCEPTION 'That sighting is not in your authorised organisations';
  END IF;
  FOREACH v_org IN ARRAY v_orgs LOOP
    v_ready := public.nzta_access_readiness(v_actor, v_org);
    IF NOT (v_ready->>'training_current')::boolean THEN v_warnings := array_append(v_warnings, 'training'); END IF;
    IF NOT (v_ready->>'confidentiality_current')::boolean THEN v_warnings := array_append(v_warnings, 'confidentiality'); END IF;
    INSERT INTO public.nzta_register_access_log (organization_id, actor_user_id, subject_type, subject_id, purpose,
      explanation, lookup_id, notice_id, observation_id, training_current, confidentiality_current, expires_at)
    VALUES (v_org, v_actor, p_subject_type, p_subject_id, p_purpose, btrim(p_explanation),
      CASE WHEN EXISTS (SELECT 1 FROM public.nzta_register_lookups WHERE id = p_lookup_id AND organization_id = v_org) THEN p_lookup_id END,
      CASE WHEN EXISTS (SELECT 1 FROM public.notices WHERE id = v_notice AND organization_id = v_org) THEN v_notice END,
      CASE WHEN EXISTS (SELECT 1 FROM public.observations WHERE id = p_observation_id AND organization_id = v_org) THEN p_observation_id END,
      (v_ready->>'training_current')::boolean, (v_ready->>'confidentiality_current')::boolean, v_expires);
  END LOOP;
  RETURN jsonb_build_object('revealed_until', v_expires, 'organization_count', cardinality(v_orgs),
    'warnings', to_jsonb(ARRAY(SELECT DISTINCT w FROM unnest(v_warnings) w ORDER BY w)));
END;
$function$;
REVOKE ALL ON FUNCTION "public"."reveal_nzta_registered_person"(p_subject_type text, p_subject_id uuid, p_purpose text, p_explanation text, p_organization_id uuid, p_lookup_id uuid, p_notice_id uuid, p_observation_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."reveal_nzta_registered_person"(p_subject_type text, p_subject_id uuid, p_purpose text, p_explanation text, p_organization_id uuid, p_lookup_id uuid, p_notice_id uuid, p_observation_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."reveal_nzta_registered_person"(p_subject_type text, p_subject_id uuid, p_purpose text, p_explanation text, p_organization_id uuid, p_lookup_id uuid, p_notice_id uuid, p_observation_id uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."review_biosecurity_photo_classification"(p_assessment_id uuid, p_action text, p_species_name text DEFAULT NULL::text, p_density_estimate text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_request_id text DEFAULT NULL::text)
 RETURNS biosecurity_assessments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_assessment public.biosecurity_assessments%rowtype;
  v_actor uuid := auth.uid();
  v_action text := lower(trim(coalesce(p_action, '')));
  v_analysis jsonb;
  v_candidate_species text;
  v_candidate_density text;
  v_candidate_threat text;
  v_final_species text;
  v_final_density text;
  v_reviewed_fields jsonb := '[]'::jsonb;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF v_action NOT IN ('confirm','correct','reject') THEN
    RAISE EXCEPTION 'Action must be confirm, correct, or reject';
  END IF;

  SELECT * INTO v_assessment
  FROM public.biosecurity_assessments
  WHERE id = p_assessment_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Biosecurity assessment not found'; END IF;
  IF NOT public.is_admin_for_org(v_assessment.organization_id) THEN
    RAISE EXCEPTION 'Active Biosecurity administrator required';
  END IF;
  IF nullif(trim(coalesce(p_request_id, '')), '') IS NOT NULL
     AND EXISTS (
       SELECT 1
       FROM public.audit_log
       WHERE organization_id = v_assessment.organization_id
         AND action = 'biosecurity_photo_classification_reviewed'
         AND metadata->>'request_id' = trim(p_request_id)
     ) THEN
    RETURN v_assessment;
  END IF;

  v_analysis := v_assessment.biosecurity_ai_analysis;
  IF jsonb_typeof(v_analysis) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'This assessment has no structured photo classification to review';
  END IF;
  v_candidate_species := nullif(trim(coalesce(
    v_analysis#>>'{details,species_name}',
    v_analysis->>'classification'
  )), '');
  v_candidate_density := nullif(trim(v_analysis#>>'{details,density}'), '');
  v_candidate_threat := nullif(trim(v_analysis#>>'{details,threat_level}'), '');

  IF v_action = 'correct'
     AND nullif(trim(coalesce(p_species_name, '')), '') IS NULL
     AND nullif(trim(coalesce(p_density_estimate, '')), '') IS NULL THEN
    RAISE EXCEPTION 'A correction requires a species or density value';
  END IF;
  IF v_action = 'confirm'
     AND coalesce(v_analysis->>'status', 'unavailable') <> 'available' THEN
    RAISE EXCEPTION 'An unavailable machine classification cannot be confirmed';
  END IF;
  IF nullif(trim(coalesce(p_density_estimate, '')), '') IS NOT NULL
     AND lower(trim(p_density_estimate)) NOT IN ('isolated','scattered','moderate','dense','severe','not_found') THEN
    RAISE EXCEPTION 'Density estimate is not supported';
  END IF;
  v_final_species := CASE
    WHEN v_action = 'correct' THEN coalesce(nullif(trim(p_species_name), ''), v_candidate_species)
    WHEN v_action = 'confirm' THEN v_candidate_species
  END;
  v_final_density := CASE
    WHEN v_action = 'correct' THEN coalesce(nullif(trim(p_density_estimate), ''), v_candidate_density)
    WHEN v_action = 'confirm' THEN v_candidate_density
  END;
  IF v_action IN ('confirm','correct') AND v_final_species IS NULL THEN
    RAISE EXCEPTION 'A species candidate is required before approval';
  END IF;
  IF v_final_species IS NOT NULL THEN
    v_reviewed_fields := v_reviewed_fields || jsonb_build_array('species_name');
  END IF;
  IF v_final_density IS NOT NULL THEN
    v_reviewed_fields := v_reviewed_fields || jsonb_build_array('density_estimate');
  END IF;
  IF v_candidate_threat IS NOT NULL THEN
    v_reviewed_fields := v_reviewed_fields || jsonb_build_array('threat_level');
  END IF;

  UPDATE public.biosecurity_assessments
  SET species_name = CASE WHEN v_action IN ('confirm','correct') THEN v_final_species ELSE species_name END,
      species_identified = CASE WHEN v_action IN ('confirm','correct') THEN v_final_species ELSE species_identified END,
      confirmed_species_name = CASE WHEN v_action IN ('confirm','correct') THEN v_final_species ELSE NULL END,
      density_estimate = CASE WHEN v_action IN ('confirm','correct') THEN coalesce(v_final_density, density_estimate) ELSE density_estimate END,
      bob_species_confirmed = v_action IN ('confirm','correct'),
      species_confirmed = v_action IN ('confirm','correct'),
      species_review_decision = CASE WHEN v_action IN ('confirm','correct') THEN 'confirmed' ELSE 'rejected' END,
      biosecurity_ai_review = jsonb_strip_nulls(jsonb_build_object(
        'status', CASE v_action
          WHEN 'confirm' THEN 'confirmed'
          WHEN 'correct' THEN 'corrected'
          ELSE 'rejected'
        END,
        'reviewed_at', clock_timestamp(),
        'reviewed_by', v_actor,
        'notes', nullif(trim(p_notes), ''),
        'reviewed_fields', CASE
          WHEN v_action = 'reject'
            THEN jsonb_build_array('species_name','density_estimate','threat_level')
          ELSE v_reviewed_fields
        END,
        'values', CASE WHEN v_action = 'reject' THEN NULL ELSE jsonb_strip_nulls(jsonb_build_object(
          'species_name', v_final_species,
          'density_estimate', v_final_density,
          'threat_level', v_candidate_threat
        )) END
      )),
      updated_at = clock_timestamp()
  WHERE id = v_assessment.id
  RETURNING * INTO v_assessment;

  PERFORM public.apply_biosecurity_photo_review_to_perception(v_assessment.id);
  INSERT INTO public.audit_log (
    organization_id, actor_user_id, action, target_table, target_id, metadata
  ) VALUES (
    v_assessment.organization_id, v_actor, 'biosecurity_photo_classification_reviewed',
    'biosecurity_assessments', v_assessment.id,
    jsonb_strip_nulls(jsonb_build_object(
      'request_id', nullif(trim(p_request_id), ''),
      'review_action', v_action,
      'reviewed_fields', CASE
        WHEN v_action = 'reject'
          THEN jsonb_build_array('species_name','density_estimate','threat_level')
        ELSE v_reviewed_fields
      END,
      'values', v_assessment.biosecurity_ai_review->'values',
      'legal_or_enforcement_decision', false
    ))
  );
  RETURN v_assessment;
END;
$function$;
COMMENT ON FUNCTION "public"."review_biosecurity_photo_classification"(p_assessment_id uuid, p_action text, p_species_name text, p_density_estimate text, p_notes text, p_request_id text) IS 'Admin confirmation, correction or rejection of advisory biosecurity photo fields. It cannot create a notice, referral or enforcement action.';
REVOKE ALL ON FUNCTION "public"."review_biosecurity_photo_classification"(p_assessment_id uuid, p_action text, p_species_name text, p_density_estimate text, p_notes text, p_request_id text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."review_biosecurity_photo_classification"(p_assessment_id uuid, p_action text, p_species_name text, p_density_estimate text, p_notes text, p_request_id text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."review_biosecurity_photo_classification"(p_assessment_id uuid, p_action text, p_species_name text, p_density_estimate text, p_notes text, p_request_id text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."review_biosecurity_photo_classification"(p_assessment_id uuid, p_action text, p_species_name text, p_density_estimate text, p_notes text, p_request_id text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."review_bob_document_draft"(p_document_id uuid, p_document_version_id uuid, p_decision text, p_review_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org_id uuid;
  v_metadata jsonb;
  v_author text;
  v_status text;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_decision NOT IN ('approved', 'rejected') THEN RAISE EXCEPTION 'Decision must be approved or rejected'; END IF;
  IF nullif(trim(coalesce(p_review_reason, '')), '') IS NULL THEN RAISE EXCEPTION 'Review reason is required'; END IF;

  SELECT d.organization_id, dv.metadata_json INTO v_org_id, v_metadata
  FROM public.documents d JOIN public.document_versions dv ON dv.document_id = d.id
  WHERE d.id = p_document_id AND dv.id = p_document_version_id FOR UPDATE;
  IF v_org_id IS NULL THEN RAISE EXCEPTION 'Document version not found'; END IF;
  IF NOT public.is_admin_for_org(v_org_id) AND NOT public.is_grand_master() THEN RAISE EXCEPTION 'Document review denied'; END IF;
  IF coalesce(v_metadata->>'authoring_status', '') <> 'needs_review' THEN RAISE EXCEPTION 'Only documents needing review can receive a decision'; END IF;

  v_author := v_metadata->>'authored_by';
  IF v_author = v_actor::text THEN RAISE EXCEPTION 'The document author cannot be its reviewer'; END IF;
  v_status := CASE WHEN p_decision = 'approved' THEN 'approved' ELSE 'rejected' END;

  UPDATE public.document_versions
  SET metadata_json = jsonb_set(
    jsonb_set(
      jsonb_set(
        jsonb_set(coalesce(metadata_json, '{}'::jsonb), '{authoring_status}', to_jsonb(v_status)),
        '{reviewed_by}', to_jsonb(v_actor::text)
      ),
      '{reviewed_at}', to_jsonb(clock_timestamp()::text)
    ),
    '{review_reason}', to_jsonb(trim(p_review_reason))
  ), updated_at = clock_timestamp()
  WHERE id = p_document_version_id;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_org_id, v_actor, 'bob_document_review_decided', 'document_versions', p_document_version_id,
    jsonb_build_object('document_id', p_document_id, 'decision', v_status, 'review_reason', trim(p_review_reason)));

  IF v_author IS NOT NULL AND v_author ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    PERFORM public.enqueue_notification(
      p_organization_id => v_org_id,
      p_category => 'document_review',
      p_title => 'Bob document ' || v_status,
      p_body => 'Your document draft "' || coalesce(v_metadata->>'title', 'Untitled') || '" was ' || v_status || '.',
      p_severity => CASE WHEN v_status = 'approved' THEN 'info' ELSE 'warning' END,
      p_recipient_user_id => v_author::uuid,
      p_link_page => 'document-studio',
      p_link_payload => jsonb_build_object('document_id', p_document_id, 'version_id', p_document_version_id),
      p_dedup_key => 'bob_document_decided:' || p_document_version_id::text || ':' || v_status
    );
  END IF;

  RETURN jsonb_build_object('ok', true, 'document_id', p_document_id, 'document_version_id', p_document_version_id, 'status', v_status);
END;
$function$;
REVOKE ALL ON FUNCTION "public"."review_bob_document_draft"(p_document_id uuid, p_document_version_id uuid, p_decision text, p_review_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."review_bob_document_draft"(p_document_id uuid, p_document_version_id uuid, p_decision text, p_review_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."review_bob_document_draft"(p_document_id uuid, p_document_version_id uuid, p_decision text, p_review_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."review_bob_document_draft"(p_document_id uuid, p_document_version_id uuid, p_decision text, p_review_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."review_branch_leave_request"(p_operating_organization_id uuid, p_request_id uuid, p_expected_status text, p_decision text, p_review_notes text DEFAULT NULL::text)
 RETURNS leave_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_leave public.leave_requests%rowtype;v_staff_user uuid;v_notes text:=nullif(trim(coalesce(p_review_notes,'')), '');
begin
  if p_decision not in('branch_checked','declined') then raise exception 'Unsupported branch leave decision';end if;select * into v_leave from public.leave_requests where id=p_request_id for update;if not found then raise exception 'Leave request not found';end if;select coalesce(staff.user_id,staff.id) into v_staff_user from public.staff_profiles staff where staff.id=v_leave.staff_id;
  if not public.user_can_operate_organization(p_operating_organization_id) or not public.user_can_exercise_branch_authority(p_operating_organization_id,v_staff_user,'leave_branch_approve') then raise exception 'Not authorised to review this branch leave request';end if;
  if v_leave.status<>p_expected_status or v_leave.status<>'pending' then raise exception 'Leave request changed since it was opened';end if;if p_decision='declined' and v_notes is null then raise exception 'Review notes are required to decline leave';end if;
  update public.leave_requests set status=p_decision,branch_reviewed_by=v_actor,branch_reviewed_at=clock_timestamp(),branch_review_notes=v_notes,branch_reviewed_organization_id=p_operating_organization_id,decision_notes=case when p_decision='declined' then v_notes else decision_notes end,approved_by=case when p_decision='declined' then v_actor else approved_by end,approved_at=case when p_decision='declined' then clock_timestamp() else approved_at end where id=v_leave.id returning * into v_leave;insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)values(v_leave.organization_id,v_actor,case when p_decision='branch_checked' then 'leave_branch_checked' else 'leave_branch_declined' end,'leave_requests',v_leave.id,jsonb_build_object('staff_id',v_leave.staff_id,'operating_organization_id',p_operating_organization_id,'review_notes',v_notes));return v_leave;
end;$function$;
REVOKE ALL ON FUNCTION "public"."review_branch_leave_request"(p_operating_organization_id uuid, p_request_id uuid, p_expected_status text, p_decision text, p_review_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."review_branch_leave_request"(p_operating_organization_id uuid, p_request_id uuid, p_expected_status text, p_decision text, p_review_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."review_branch_leave_request"(p_operating_organization_id uuid, p_request_id uuid, p_expected_status text, p_decision text, p_review_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."review_branch_leave_request"(p_operating_organization_id uuid, p_request_id uuid, p_expected_status text, p_decision text, p_review_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."review_branch_timesheet"(p_operating_organization_id uuid, p_timesheet_id uuid, p_expected_status text, p_decision text, p_review_notes text DEFAULT NULL::text)
 RETURNS timesheets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_sheet public.timesheets%rowtype;v_staff_user uuid;v_notes text:=nullif(trim(coalesce(p_review_notes,'')), '');v_pay_blocker text;
begin
  if p_decision not in('branch_checked','rejected') then raise exception 'Unsupported branch timesheet decision';end if;select * into v_sheet from public.timesheets where id=p_timesheet_id for update;if not found then raise exception 'Timesheet not found';end if;select coalesce(staff.user_id,staff.id) into v_staff_user from public.staff_profiles staff where staff.id=v_sheet.staff_id;
  if not public.user_can_operate_organization(p_operating_organization_id) or not public.user_can_exercise_branch_authority(p_operating_organization_id,v_staff_user,'timesheet_local_review') then raise exception 'Not authorised to review this branch timesheet';end if;
  if v_sheet.status<>p_expected_status or v_sheet.status<>'submitted' then raise exception 'Only submitted timesheets are available for branch review';end if;if p_decision='rejected' and v_notes is null then raise exception 'Review notes are required to return a timesheet for correction';end if;if v_sheet.actual_hours is null then raise exception 'Actual hours are required before review';end if;if p_decision='branch_checked' then v_pay_blocker:=public.timesheet_dispatch_pay_review_blocker(v_sheet.id);if v_pay_blocker is not null then raise exception 'Timesheet cannot be branch checked: %',v_pay_blocker;end if;end if;
  update public.timesheets set status=p_decision,branch_reviewed_by=v_actor,branch_reviewed_at=clock_timestamp(),branch_review_notes=v_notes,branch_reviewed_organization_id=p_operating_organization_id,review_notes=case when p_decision='rejected' then v_notes else review_notes end where id=v_sheet.id returning * into v_sheet;insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)values(v_sheet.organization_id,v_actor,case when p_decision='branch_checked' then 'timesheet_branch_checked' else 'timesheet_returned_for_correction' end,'timesheets',v_sheet.id,jsonb_build_object('staff_id',v_sheet.staff_id,'operating_organization_id',p_operating_organization_id,'review_notes',v_notes));return v_sheet;
end;$function$;
REVOKE ALL ON FUNCTION "public"."review_branch_timesheet"(p_operating_organization_id uuid, p_timesheet_id uuid, p_expected_status text, p_decision text, p_review_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."review_branch_timesheet"(p_operating_organization_id uuid, p_timesheet_id uuid, p_expected_status text, p_decision text, p_review_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."review_branch_timesheet"(p_operating_organization_id uuid, p_timesheet_id uuid, p_expected_status text, p_decision text, p_review_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."review_branch_timesheet"(p_operating_organization_id uuid, p_timesheet_id uuid, p_expected_status text, p_decision text, p_review_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."review_canonical_identity_evidence"(p_identity_document_id uuid, p_action text, p_approved_fields jsonb DEFAULT '{}'::jsonb, p_review_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_document public.person_identity_documents%rowtype;v_definition public.identity_document_type_definitions%rowtype;v_person public.person_records%rowtype;
  v_result jsonb;v_staff_id uuid;v_credential_id uuid;v_number text;v_authority text;v_issued date;v_expiry date;v_activities text[];v_storage_path text;
BEGIN
  SELECT * INTO v_document FROM public.person_identity_documents WHERE id=p_identity_document_id;
  IF v_document.id IS NULL THEN RAISE EXCEPTION 'Identity document not found'; END IF;
  SELECT * INTO v_definition FROM public.identity_document_type_definitions WHERE document_kind=v_document.document_kind;
  v_result:=public.review_deterministic_identity_evidence(p_identity_document_id,p_action,p_approved_fields,p_review_notes);
  IF p_action='approve' THEN
    UPDATE public.incident_person_links SET source_kind='identity_document',updated_at=clock_timestamp() WHERE identity_document_id=v_document.id;
    SELECT * INTO v_person FROM public.person_records WHERE id=v_document.person_record_id;
    v_staff_id:=nullif(v_person.metadata->'profile_details'->>'staff_profile_id','')::uuid;
    IF v_staff_id IS NOT NULL AND v_definition.staff_credential_type IS NOT NULL THEN
      v_number:=coalesce(nullif(trim(p_approved_fields->>'security_licence_number'),''),nullif(trim(p_approved_fields->>'driver_licence_number'),''),nullif(trim(p_approved_fields->>'firearms_licence_number'),''),nullif(trim(p_approved_fields->>'document_number'),''));
      v_authority:=coalesce(nullif(trim(p_approved_fields->>'security_licence_authority'),''),nullif(trim(p_approved_fields->>'issuing_authority'),''));
      v_issued:=nullif(p_approved_fields->>'issued_date','')::date;
      v_expiry:=coalesce(nullif(p_approved_fields->>'security_licence_expiry','')::date,nullif(p_approved_fields->>'driver_licence_expiry','')::date,nullif(p_approved_fields->>'firearms_licence_expiry','')::date,nullif(p_approved_fields->>'expiry_date','')::date);
      v_activities:=CASE WHEN nullif(trim(p_approved_fields->>'authorized_activities'),'') IS NOT NULL THEN regexp_split_to_array(trim(p_approved_fields->>'authorized_activities'),'\s*,\s*') ELSE v_definition.default_authorized_activities END;
      SELECT credential_id INTO v_credential_id FROM public.record_staff_credential(v_document.id,v_staff_id,v_definition.staff_credential_type,v_number,v_authority,v_issued,v_expiry,v_activities,false,'Created from approved identity evidence; People & HR verification still required');
      SELECT attachment.storage_path INTO v_storage_path FROM public.bob_attachments attachment WHERE attachment.id=v_document.attachment_id;
      UPDATE public.staff_credentials SET document_storage_path=v_storage_path WHERE id=v_credential_id;
    END IF;
  END IF;
  RETURN v_result||jsonb_build_object('staff_credential_handoff_id',v_credential_id,'staff_verification_required',v_credential_id IS NOT NULL);
END;
$function$;
COMMENT ON FUNCTION "public"."review_canonical_identity_evidence"(p_identity_document_id uuid, p_action text, p_approved_fields jsonb, p_review_notes text) IS 'Admin approval boundary for canonical identity evidence; staff projections receive an unverified Staff Credential handoff for People & HR review.';
REVOKE ALL ON FUNCTION "public"."review_canonical_identity_evidence"(p_identity_document_id uuid, p_action text, p_approved_fields jsonb, p_review_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."review_canonical_identity_evidence"(p_identity_document_id uuid, p_action text, p_approved_fields jsonb, p_review_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."review_canonical_identity_evidence"(p_identity_document_id uuid, p_action text, p_approved_fields jsonb, p_review_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."review_canonical_identity_evidence"(p_identity_document_id uuid, p_action text, p_approved_fields jsonb, p_review_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."review_cctv_entity_observation"(p_observation_id uuid, p_action text, p_target_id uuid DEFAULT NULL::uuid, p_display_name text DEFAULT NULL::text, p_plate text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS cctv_entity_observations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid(); v_obs public.cctv_entity_observations%rowtype; v_person uuid; v_vehicle uuid;
  v_plate text; v_target public.cctv_entity_observations%rowtype; v_n integer := 0;
  v_seed_make text; v_seed_model text;
BEGIN
  SELECT * INTO v_obs FROM public.cctv_entity_observations WHERE id = p_observation_id FOR UPDATE;
  IF v_obs.id IS NULL THEN RAISE EXCEPTION 'CCTV observation not found'; END IF;
  IF v_actor IS NULL OR NOT public.org_access_allowed(v_obs.organization_id) THEN RAISE EXCEPTION 'CCTV review access denied'; END IF;
  IF p_action NOT IN ('accept', 'reject', 'link_person', 'new_person', 'link_vehicle', 'new_vehicle', 'merge_portfolio', 'accept_portfolio') THEN
    RAISE EXCEPTION 'Unsupported CCTV review action %', p_action;
  END IF;

  IF p_action = 'reject' THEN
    UPDATE public.cctv_entity_observations
       SET review_state = 'rejected', portfolio_state = 'rejected', reviewed_by = v_actor, reviewed_at = clock_timestamp(),
           review_notes = nullif(trim(p_notes), '')
     WHERE id = v_obs.id RETURNING * INTO v_obs;

  ELSIF p_action = 'link_person' THEN
    IF v_obs.entity_kind <> 'person' THEN RAISE EXCEPTION 'Only a person observation can be linked to a person'; END IF;
    IF NOT EXISTS (SELECT 1 FROM public.person_records pr WHERE pr.id = p_target_id AND pr.organization_id = v_obs.organization_id) THEN
      RAISE EXCEPTION 'Person record is outside the organization';
    END IF;
    UPDATE public.cctv_entity_observations
       SET person_record_id = p_target_id, canonical_person_id = public.ensure_canonical_person_for_record(p_target_id),
           review_state = 'accepted', portfolio_state = 'linked', reviewed_by = v_actor, reviewed_at = clock_timestamp(),
           review_notes = nullif(trim(p_notes), '')
     WHERE id = v_obs.id RETURNING * INTO v_obs;

  ELSIF p_action = 'new_person' THEN
    IF v_obs.entity_kind <> 'person' THEN RAISE EXCEPTION 'Only a person observation can create a person'; END IF;
    IF nullif(trim(coalesce(p_display_name, '')), '') IS NULL THEN RAISE EXCEPTION 'A display name is required for a new person'; END IF;
    INSERT INTO public.person_records (organization_id, display_name, review_state, metadata)
    VALUES (v_obs.organization_id, trim(p_display_name), 'draft',
            jsonb_build_object('created_from', 'cctv_entity_observation', 'observation_id', v_obs.id, 'created_by', v_actor))
    RETURNING id INTO v_person;
    UPDATE public.cctv_entity_observations
       SET person_record_id = v_person, canonical_person_id = public.ensure_canonical_person_for_record(v_person),
           review_state = 'accepted', portfolio_state = 'new_identity', reviewed_by = v_actor, reviewed_at = clock_timestamp(),
           review_notes = nullif(trim(p_notes), '')
     WHERE id = v_obs.id RETURNING * INTO v_obs;

  ELSIF p_action = 'link_vehicle' THEN
    IF v_obs.entity_kind <> 'vehicle' THEN RAISE EXCEPTION 'Only a vehicle observation can be linked to a vehicle'; END IF;
    IF NOT EXISTS (SELECT 1 FROM public.canonical_vehicles cv WHERE cv.id = p_target_id) THEN RAISE EXCEPTION 'Canonical vehicle not found'; END IF;
    UPDATE public.cctv_entity_observations
       SET canonical_vehicle_id = p_target_id, review_state = 'accepted', portfolio_state = 'linked',
           reviewed_by = v_actor, reviewed_at = clock_timestamp(), review_notes = nullif(trim(p_notes), '')
     WHERE id = v_obs.id RETURNING * INTO v_obs;
    INSERT INTO public.canonical_vehicle_links (canonical_vehicle_id, source_system, source_table, source_key, metadata)
    VALUES (p_target_id, 'cctv_review', 'cctv_entity_observations', v_obs.id::text, jsonb_build_object('linked_by', v_actor, 'observed_at', v_obs.observed_at))
    ON CONFLICT (source_system, source_table, source_key) DO NOTHING;

  ELSIF p_action IN ('new_vehicle', 'accept') AND v_obs.entity_kind = 'vehicle' AND NULLIF(public.normalize_plate_number(coalesce(p_plate, v_obs.candidate_plate)), '') IS NOT NULL THEN
    v_plate := public.normalize_plate_number(coalesce(p_plate, v_obs.candidate_plate));
    -- Never seed a brand-new canonical vehicle from an unverified vision-LLM guess; see header comment.
    v_seed_make := CASE WHEN v_obs.attributes->>'make_model_source' = 'vision_llm_hint_unverified' THEN NULL ELSE v_obs.attributes->>'make' END;
    v_seed_model := CASE WHEN v_obs.attributes->>'make_model_source' = 'vision_llm_hint_unverified' THEN NULL ELSE v_obs.attributes->>'model' END;
    v_vehicle := public.ensure_canonical_vehicle(v_plate, v_seed_make, v_seed_model, v_obs.attributes->>'colour',
                                                 'cctv_entity_observations', v_obs.id::text, v_obs.observed_at);
    IF v_vehicle IS NULL THEN RAISE EXCEPTION 'Plate % is not a valid vehicle identity', v_plate; END IF;
    UPDATE public.cctv_entity_observations
       SET candidate_plate = v_plate, canonical_vehicle_id = v_vehicle, review_state = 'accepted',
           portfolio_state = CASE WHEN p_action = 'new_vehicle' THEN 'new_identity' ELSE 'linked' END,
           reviewed_by = v_actor, reviewed_at = clock_timestamp(), review_notes = nullif(trim(p_notes), '')
     WHERE id = v_obs.id RETURNING * INTO v_obs;

  ELSIF p_action = 'new_vehicle' THEN
    RAISE EXCEPTION 'A readable plate is required to create a vehicle; keep it in its portfolio until one is read';

  ELSIF p_action = 'accept' THEN
    UPDATE public.cctv_entity_observations
       SET review_state = 'accepted', reviewed_by = v_actor, reviewed_at = clock_timestamp(), review_notes = nullif(trim(p_notes), '')
     WHERE id = v_obs.id RETURNING * INTO v_obs;

  ELSIF p_action = 'merge_portfolio' THEN
    SELECT * INTO v_target FROM public.cctv_entity_observations WHERE id = p_target_id AND organization_id = v_obs.organization_id;
    IF v_target.id IS NULL OR v_target.entity_kind <> v_obs.entity_kind THEN RAISE EXCEPTION 'Merge target must be an observation of the same kind in the organization'; END IF;
    IF v_target.portfolio_key IS NULL THEN
      UPDATE public.cctv_entity_observations SET portfolio_key = gen_random_uuid() WHERE id = v_target.id RETURNING * INTO v_target;
    END IF;
    UPDATE public.cctv_entity_observations
       SET portfolio_key = v_target.portfolio_key,
           portfolio_state = CASE WHEN portfolio_state IN ('linked', 'new_identity', 'rejected') THEN portfolio_state ELSE 'candidate' END
     WHERE organization_id = v_obs.organization_id AND (portfolio_key = v_obs.portfolio_key OR id = v_obs.id);
    SELECT * INTO v_obs FROM public.cctv_entity_observations WHERE id = v_obs.id;

  ELSIF p_action = 'accept_portfolio' THEN
    IF v_obs.person_record_id IS NULL AND v_obs.canonical_vehicle_id IS NULL THEN
      RAISE EXCEPTION 'Link this observation to an identity before applying it to its portfolio';
    END IF;
    UPDATE public.cctv_entity_observations o
       SET person_record_id = v_obs.person_record_id, canonical_person_id = v_obs.canonical_person_id,
           canonical_vehicle_id = v_obs.canonical_vehicle_id, candidate_plate = coalesce(o.candidate_plate, v_obs.candidate_plate),
           review_state = 'accepted', portfolio_state = 'linked', reviewed_by = v_actor, reviewed_at = clock_timestamp(),
           review_notes = coalesce(nullif(trim(p_notes), ''), 'Accepted with portfolio ' || v_obs.portfolio_key::text)
     WHERE o.organization_id = v_obs.organization_id AND o.portfolio_key = v_obs.portfolio_key
       AND o.id <> v_obs.id AND o.review_state = 'unreviewed';
    GET DIAGNOSTICS v_n = ROW_COUNT;
  END IF;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_obs.organization_id, v_actor, 'cctv_entity_observation_' || p_action, 'cctv_entity_observations', v_obs.id,
          jsonb_strip_nulls(jsonb_build_object('entity_kind', v_obs.entity_kind, 'target_id', p_target_id, 'plate', v_plate,
            'person_record_id', v_obs.person_record_id, 'canonical_vehicle_id', v_obs.canonical_vehicle_id,
            'portfolio_key', v_obs.portfolio_key, 'portfolio_rows_updated', nullif(v_n, 0))));
  -- Biometric templates never leave the database through a review response: matching happens in
  -- find_cctv_portfolio_matches, and the reviewer only needs the decision, labels and thumbnail back.
  v_obs.face_vec := NULL; v_obs.appearance_vec := NULL; v_obs.candidate_embedding := NULL; v_obs.appearance_embedding := NULL;
  RETURN v_obs;
END $function$;
REVOKE ALL ON FUNCTION "public"."review_cctv_entity_observation"(p_observation_id uuid, p_action text, p_target_id uuid, p_display_name text, p_plate text, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."review_cctv_entity_observation"(p_observation_id uuid, p_action text, p_target_id uuid, p_display_name text, p_plate text, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."review_cctv_entity_observation"(p_observation_id uuid, p_action text, p_target_id uuid, p_display_name text, p_plate text, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."review_cctv_entity_observation"(p_observation_id uuid, p_action text, p_target_id uuid, p_display_name text, p_plate text, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."review_deterministic_identity_evidence"(p_identity_document_id uuid, p_action text, p_approved_fields jsonb DEFAULT '{}'::jsonb, p_review_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_document public.person_identity_documents%rowtype;
  v_definition public.identity_document_type_definitions%rowtype;
  v_result jsonb;
  v_extras jsonb;
BEGIN
  SELECT * INTO v_document FROM public.person_identity_documents WHERE id=p_identity_document_id;
  IF v_document.id IS NULL THEN RAISE EXCEPTION 'Identity document not found'; END IF;
  SELECT * INTO v_definition FROM public.identity_document_type_definitions WHERE document_kind=v_document.document_kind AND active;
  IF v_definition.document_kind IS NULL THEN RAISE EXCEPTION 'Unsupported identity document kind'; END IF;
  v_result := public.review_identity_evidence(p_identity_document_id,p_action,p_approved_fields,p_review_notes);
  IF p_action='approve' THEN
    v_extras := jsonb_strip_nulls(jsonb_build_object(
      'document_number',nullif(trim(p_approved_fields->>'document_number'),''),
      'issued_date',nullif(p_approved_fields->>'issued_date','')::date,
      'expiry_date',nullif(p_approved_fields->>'expiry_date','')::date,
      'issuing_authority',nullif(trim(p_approved_fields->>'issuing_authority'),''),
      'authorized_activities',nullif(trim(p_approved_fields->>'authorized_activities'),'')
    ));
    UPDATE public.person_identity_documents
    SET extracted_fields=jsonb_set(extracted_fields,'{approved}',coalesce(extracted_fields->'approved','{}'::jsonb)||v_extras,true)
    WHERE id=p_identity_document_id;
  END IF;
  RETURN v_result || jsonb_build_object(
    'document_kind',v_definition.document_kind,
    'canonical_destination',v_definition.canonical_destination,
    'staff_credential_type',v_definition.staff_credential_type,
    'default_authorized_activities',v_definition.default_authorized_activities
  );
END;
$function$;
COMMENT ON FUNCTION "public"."review_deterministic_identity_evidence"(p_identity_document_id uuid, p_action text, p_approved_fields jsonb, p_review_notes text) IS 'Human approval wrapper that preserves generic warrant fields and returns the governed staff credential destination without creating staff readiness.';
REVOKE ALL ON FUNCTION "public"."review_deterministic_identity_evidence"(p_identity_document_id uuid, p_action text, p_approved_fields jsonb, p_review_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."review_deterministic_identity_evidence"(p_identity_document_id uuid, p_action text, p_approved_fields jsonb, p_review_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."review_deterministic_identity_evidence"(p_identity_document_id uuid, p_action text, p_approved_fields jsonb, p_review_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."review_dispatch_job_pay_line"(p_client_request_id uuid, p_pay_line_id uuid, p_expected_review_id uuid, p_decision text, p_review_notes text DEFAULT NULL::text)
 RETURNS dispatch_job_pay_line_reviews
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_line public.dispatch_job_pay_lines%rowtype;
  v_existing public.dispatch_job_pay_line_reviews%rowtype;
  v_current_review_id uuid;
  v_review public.dispatch_job_pay_line_reviews%rowtype;
  v_notes text := nullif(trim(coalesce(p_review_notes, '')), '');
begin
  if p_client_request_id is null then
    raise exception 'client_request_id is required';
  end if;
  if p_decision not in ('approved', 'rejected') then
    raise exception 'decision must be approved or rejected';
  end if;
  if p_decision = 'rejected' and v_notes is null then
    raise exception 'review notes are required when rejecting pay evidence';
  end if;

  select * into v_existing
  from public.dispatch_job_pay_line_reviews
  where organization_id = (select organization_id from public.dispatch_job_pay_lines where id = p_pay_line_id)
    and client_request_id = p_client_request_id;
  if found then
    return v_existing;
  end if;

  select * into v_line from public.dispatch_job_pay_lines where id = p_pay_line_id for update;
  if not found then
    raise exception 'Dispatch pay line not found';
  end if;
  if not public.is_admin_for_org(v_line.organization_id) then
    raise exception 'Not authorised to review pay evidence for this organization';
  end if;

  select r.id into v_current_review_id
  from public.dispatch_job_pay_line_reviews r
  where r.pay_line_id = v_line.id
  order by r.reviewed_at desc, r.id desc
  limit 1;
  if v_current_review_id is distinct from p_expected_review_id then
    raise exception 'Pay-line review changed; reload before deciding';
  end if;

  insert into public.dispatch_job_pay_line_reviews(
    organization_id, pay_line_id, decision, review_notes, reviewed_by, supersedes_review_id, client_request_id
  ) values (
    v_line.organization_id, v_line.id, p_decision, v_notes, v_actor, v_current_review_id, p_client_request_id
  ) returning * into v_review;

  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (
    v_line.organization_id, v_actor, 'dispatch_pay_line_reviewed', 'dispatch_job_pay_line_reviews', v_review.id,
    jsonb_build_object('pay_line_id', v_line.id, 'decision', p_decision, 'supersedes_review_id', v_current_review_id, 'review_notes', v_notes)
  );

  return v_review;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."review_dispatch_job_pay_line"(p_client_request_id uuid, p_pay_line_id uuid, p_expected_review_id uuid, p_decision text, p_review_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."review_dispatch_job_pay_line"(p_client_request_id uuid, p_pay_line_id uuid, p_expected_review_id uuid, p_decision text, p_review_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."review_dispatch_job_pay_line"(p_client_request_id uuid, p_pay_line_id uuid, p_expected_review_id uuid, p_decision text, p_review_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."review_dispatch_job_pay_line"(p_client_request_id uuid, p_pay_line_id uuid, p_expected_review_id uuid, p_decision text, p_review_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."review_document_classification"(p_document_version_id uuid, p_privacy_class text, p_contains_pii boolean, p_contains_operational_security boolean, p_contains_financial_data boolean, p_contains_legal_privilege boolean, p_reason text)
 RETURNS document_classifications
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org_id uuid;
  v_review public.document_classifications%rowtype;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF nullif(trim(coalesce(p_reason, '')), '') IS NULL THEN RAISE EXCEPTION 'Review reason is required'; END IF;
  IF p_privacy_class NOT IN ('public', 'internal_non_sensitive', 'tenant_sensitive', 'restricted') THEN
    RAISE EXCEPTION 'Unsupported privacy class';
  END IF;

  SELECT d.organization_id INTO v_org_id
  FROM public.document_versions dv
  JOIN public.documents d ON d.id = dv.document_id
  WHERE dv.id = p_document_version_id;
  IF v_org_id IS NULL THEN RAISE EXCEPTION 'Document version not found'; END IF;
  IF NOT public.is_admin_for_org(v_org_id) AND NOT public.is_grand_master() THEN
    RAISE EXCEPTION 'Document classification review denied';
  END IF;

  INSERT INTO public.document_classifications (
    document_version_id, privacy_class, contains_pii, contains_operational_security,
    contains_financial_data, contains_legal_privilege, classifier_source,
    confidence, rationale, reviewed_by, reviewed_at
  ) VALUES (
    p_document_version_id, p_privacy_class, coalesce(p_contains_pii, false),
    coalesce(p_contains_operational_security, false), coalesce(p_contains_financial_data, false),
    coalesce(p_contains_legal_privilege, false), 'human_review', 1.0,
    trim(p_reason), v_actor, clock_timestamp()
  ) RETURNING * INTO v_review;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_org_id, v_actor, 'document_classification_reviewed', 'document_classifications', v_review.id,
    jsonb_build_object('document_version_id', p_document_version_id, 'privacy_class', p_privacy_class,
      'contains_pii', p_contains_pii, 'contains_operational_security', p_contains_operational_security,
      'contains_financial_data', p_contains_financial_data, 'contains_legal_privilege', p_contains_legal_privilege,
      'reason', trim(p_reason)));
  RETURN v_review;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."review_document_classification"(p_document_version_id uuid, p_privacy_class text, p_contains_pii boolean, p_contains_operational_security boolean, p_contains_financial_data boolean, p_contains_legal_privilege boolean, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."review_document_classification"(p_document_version_id uuid, p_privacy_class text, p_contains_pii boolean, p_contains_operational_security boolean, p_contains_financial_data boolean, p_contains_legal_privilege boolean, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."review_document_classification"(p_document_version_id uuid, p_privacy_class text, p_contains_pii boolean, p_contains_operational_security boolean, p_contains_financial_data boolean, p_contains_legal_privilege boolean, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."review_document_classification"(p_document_version_id uuid, p_privacy_class text, p_contains_pii boolean, p_contains_operational_security boolean, p_contains_financial_data boolean, p_contains_legal_privilege boolean, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."review_document_promotion_proposal"(p_proposal_id uuid, p_decision text, p_reason text)
 RETURNS document_promotion_proposals
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_proposal public.document_promotion_proposals%rowtype;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_decision NOT IN ('approved', 'rejected') THEN RAISE EXCEPTION 'Decision must be approved or rejected'; END IF;
  IF nullif(trim(coalesce(p_reason, '')), '') IS NULL THEN RAISE EXCEPTION 'Review reason is required'; END IF;
  SELECT * INTO v_proposal FROM public.document_promotion_proposals WHERE id = p_proposal_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Promotion proposal not found'; END IF;
  IF NOT public.is_admin_for_org(v_proposal.organization_id) AND NOT public.is_grand_master() THEN
    RAISE EXCEPTION 'Promotion proposal review denied';
  END IF;
  IF v_proposal.status <> 'proposed' THEN RAISE EXCEPTION 'Only proposed promotions can be reviewed'; END IF;
  UPDATE public.document_promotion_proposals
  SET status = p_decision, reviewed_by = v_actor, reviewed_at = clock_timestamp(), review_reason = trim(p_reason), updated_at = clock_timestamp()
  WHERE id = v_proposal.id
  RETURNING * INTO v_proposal;
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_proposal.organization_id, v_actor, 'document_promotion_proposal_reviewed', 'document_promotion_proposals', v_proposal.id,
    jsonb_build_object('decision', p_decision, 'target_type', v_proposal.target_type, 'reason', trim(p_reason)));
  RETURN v_proposal;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."review_document_promotion_proposal"(p_proposal_id uuid, p_decision text, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."review_document_promotion_proposal"(p_proposal_id uuid, p_decision text, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."review_document_promotion_proposal"(p_proposal_id uuid, p_decision text, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."review_document_promotion_proposal"(p_proposal_id uuid, p_decision text, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."review_file_import_batch"(p_batch_id uuid, p_decision text, p_reason text)
 RETURNS file_import_batches
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_batch public.file_import_batches%rowtype; v_expected_proposals integer; v_actual_proposals integer; v_expected_mappings integer; v_actual_mappings integer;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_decision NOT IN ('approved','rejected') THEN RAISE EXCEPTION 'Decision must be approved or rejected'; END IF;
  IF nullif(trim(coalesce(p_reason,'')),'') IS NULL THEN RAISE EXCEPTION 'Review reason is required'; END IF;
  SELECT * INTO v_batch FROM public.file_import_batches WHERE id=p_batch_id FOR UPDATE;
  IF NOT FOUND OR NOT public.is_tenant_import_admin(v_batch.organization_id) THEN RAISE EXCEPTION 'Import batch review denied'; END IF;
  IF v_batch.status NOT IN ('preview','needs_review') THEN RAISE EXCEPTION 'Only review-ready batches can be reviewed'; END IF;
  IF p_decision='approved' THEN
    IF jsonb_typeof(v_batch.schema_json->'headers')='array' THEN
      SELECT count(*)::integer INTO v_expected_mappings
      FROM jsonb_array_elements_text(v_batch.schema_json->'headers') header(value)
      WHERE nullif(regexp_replace(btrim(header.value), '\s+', '', 'g'), '') IS NOT NULL;
      SELECT count(*)::integer INTO v_actual_mappings FROM public.file_import_mapping_reviews WHERE batch_id=v_batch.id;
      IF v_actual_mappings<>v_expected_mappings THEN RAISE EXCEPTION 'Mapping review is incomplete: expected %, found %',v_expected_mappings,v_actual_mappings; END IF;
    END IF;
    IF EXISTS(SELECT 1 FROM public.file_import_mapping_reviews WHERE batch_id=v_batch.id AND decision='proposed') THEN RAISE EXCEPTION 'Every proposed column mapping must be confirmed or rejected before batch approval'; END IF;
    IF EXISTS(SELECT 1 FROM public.file_import_row_proposals WHERE batch_id=v_batch.id AND status='proposed') THEN RAISE EXCEPTION 'Every row proposal must be approved or rejected before batch approval'; END IF;
    IF v_batch.manifest_json->'receipt' ? 'proposal_candidates' THEN
      v_expected_proposals:=(v_batch.manifest_json->'receipt'->>'proposal_candidates')::integer;
      SELECT count(*)::integer INTO v_actual_proposals FROM public.file_import_row_proposals WHERE batch_id=v_batch.id;
      IF v_actual_proposals<>v_expected_proposals THEN RAISE EXCEPTION 'Proposal staging is incomplete: expected %, found %',v_expected_proposals,v_actual_proposals; END IF;
    END IF;
  ELSE
    UPDATE public.file_import_mapping_reviews SET decision='rejected',review_reason=coalesce(review_reason,trim(p_reason)),reviewed_by=v_actor,reviewed_at=clock_timestamp(),updated_at=clock_timestamp() WHERE batch_id=v_batch.id AND decision='proposed';
    UPDATE public.file_import_row_proposals SET status='rejected',review_reason=coalesce(review_reason,trim(p_reason)),reviewed_by=v_actor,reviewed_at=clock_timestamp(),updated_at=clock_timestamp() WHERE batch_id=v_batch.id AND status='proposed';
  END IF;
  UPDATE public.file_import_batches SET status=p_decision,reviewed_by=v_actor,reviewed_at=clock_timestamp(),review_reason=trim(p_reason),updated_at=clock_timestamp() WHERE id=v_batch.id RETURNING * INTO v_batch;
  INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) VALUES(v_batch.organization_id,v_actor,'file_import_batch_reviewed','file_import_batches',v_batch.id,jsonb_build_object('decision',p_decision,'reason',trim(p_reason),'source_file',v_batch.source_file));
  RETURN v_batch;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."review_file_import_batch"(p_batch_id uuid, p_decision text, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."review_file_import_batch"(p_batch_id uuid, p_decision text, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."review_file_import_batch"(p_batch_id uuid, p_decision text, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."review_file_import_batch"(p_batch_id uuid, p_decision text, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."review_file_import_finance_proposals"(p_batch_id uuid, p_expected_proposal_count integer, p_expected_total numeric, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid:=auth.uid();
  v_batch public.file_import_batches%rowtype;
  v_count integer;
  v_total numeric;
  v_row_count integer;
BEGIN
  IF p_expected_proposal_count<1 OR p_expected_total<=0 OR nullif(trim(coalesce(p_reason,'')),'') IS NULL THEN
    RAISE EXCEPTION 'Expected proposal count, total, and review reason are required';
  END IF;
  SELECT * INTO v_batch FROM public.file_import_batches WHERE id=p_batch_id FOR UPDATE;
  IF NOT FOUND OR v_batch.status<>'needs_review' OR NOT public.is_tenant_import_admin(v_batch.organization_id) THEN
    RAISE EXCEPTION 'Finance import batch is not open for review';
  END IF;
  IF EXISTS(SELECT 1 FROM public.file_import_mapping_reviews WHERE batch_id=v_batch.id AND decision<>'confirmed') THEN
    RAISE EXCEPTION 'Every source mapping must be confirmed before finance proposal approval';
  END IF;
  IF EXISTS(SELECT 1 FROM public.file_import_row_proposals WHERE batch_id=v_batch.id AND target_type<>'finance_service_cost') THEN
    RAISE EXCEPTION 'Finance batch contains a different consequential proposal type';
  END IF;
  SELECT count(*),coalesce(sum((proposed_payload->>'unit_cost')::numeric),0),coalesce(sum((proposed_payload->>'source_row_count')::integer),0)
  INTO v_count,v_total,v_row_count
  FROM public.file_import_row_proposals
  WHERE batch_id=v_batch.id AND target_type='finance_service_cost' AND status='proposed';
  IF v_count<>p_expected_proposal_count OR round(v_total,2)<>round(p_expected_total,2) THEN
    RAISE EXCEPTION 'Finance proposal summary changed: expected % / %, found % / %',p_expected_proposal_count,p_expected_total,v_count,v_total;
  END IF;
  IF v_row_count<>(SELECT count(*) FROM public.file_import_finance_cost_rows WHERE batch_id=v_batch.id AND status='eligible') THEN
    RAISE EXCEPTION 'Finance proposal source row coverage is incomplete';
  END IF;
  UPDATE public.file_import_row_proposals
  SET status='approved',review_reason=trim(p_reason),reviewed_by=v_actor,reviewed_at=now(),updated_at=now()
  WHERE batch_id=v_batch.id AND target_type='finance_service_cost' AND status='proposed';
  INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
  VALUES(v_batch.organization_id,v_actor,'file_import_finance_proposals_approved','file_import_batches',v_batch.id,
    jsonb_build_object('proposal_count',v_count,'source_row_count',v_row_count,'total',round(v_total,2),'reason',trim(p_reason)));
  RETURN jsonb_build_object('proposal_count',v_count,'source_row_count',v_row_count,'total',round(v_total,2));
END;
$function$;
REVOKE ALL ON FUNCTION "public"."review_file_import_finance_proposals"(p_batch_id uuid, p_expected_proposal_count integer, p_expected_total numeric, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."review_file_import_finance_proposals"(p_batch_id uuid, p_expected_proposal_count integer, p_expected_total numeric, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."review_file_import_finance_proposals"(p_batch_id uuid, p_expected_proposal_count integer, p_expected_total numeric, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."review_file_import_finance_proposals"(p_batch_id uuid, p_expected_proposal_count integer, p_expected_total numeric, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."review_file_import_mapping"(p_batch_id uuid, p_source_column text, p_target_entity text, p_target_field text, p_decision text, p_review_reason text)
 RETURNS file_import_mapping_reviews
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_actor uuid := auth.uid(); v_batch public.file_import_batches%rowtype; v_review public.file_import_mapping_reviews%rowtype;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_decision NOT IN ('proposed','confirmed','rejected') THEN RAISE EXCEPTION 'Invalid mapping decision'; END IF;
  IF nullif(trim(coalesce(p_source_column,'')),'') IS NULL THEN RAISE EXCEPTION 'Source column is required'; END IF;
  IF p_decision='confirmed' AND nullif(trim(coalesce(p_target_entity,'')),'') IS NULL THEN RAISE EXCEPTION 'Confirmed mappings require a target entity'; END IF;
  SELECT * INTO v_batch FROM public.file_import_batches WHERE id=p_batch_id FOR UPDATE;
  IF NOT FOUND OR NOT public.is_tenant_import_admin(v_batch.organization_id) THEN RAISE EXCEPTION 'Mapping review denied'; END IF;
  IF v_batch.status NOT IN ('preview','needs_review') THEN RAISE EXCEPTION 'Import batch is not open for mapping review'; END IF;
  IF jsonb_typeof(v_batch.schema_json->'headers')='array' AND NOT (v_batch.schema_json->'headers' ? trim(p_source_column)) THEN RAISE EXCEPTION 'Source column was not present in the batch'; END IF;
  INSERT INTO public.file_import_mapping_reviews(organization_id,batch_id,source_column,target_entity,target_field,decision,review_reason,reviewed_by,reviewed_at,updated_at)
  VALUES(v_batch.organization_id,p_batch_id,trim(p_source_column),nullif(trim(coalesce(p_target_entity,'')),''),nullif(trim(coalesce(p_target_field,'')),''),p_decision,nullif(trim(coalesce(p_review_reason,'')),''),v_actor,clock_timestamp(),clock_timestamp())
  ON CONFLICT(batch_id,source_column) DO UPDATE SET target_entity=excluded.target_entity,target_field=excluded.target_field,decision=excluded.decision,review_reason=excluded.review_reason,reviewed_by=excluded.reviewed_by,reviewed_at=excluded.reviewed_at,updated_at=clock_timestamp()
  RETURNING * INTO v_review;
  INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) VALUES(v_batch.organization_id,v_actor,'file_import_mapping_reviewed','file_import_mapping_reviews',v_review.id,jsonb_build_object('batch_id',p_batch_id,'source_column',v_review.source_column,'target_entity',v_review.target_entity,'target_field',v_review.target_field,'decision',v_review.decision));
  RETURN v_review;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."review_file_import_mapping"(p_batch_id uuid, p_source_column text, p_target_entity text, p_target_field text, p_decision text, p_review_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."review_file_import_mapping"(p_batch_id uuid, p_source_column text, p_target_entity text, p_target_field text, p_decision text, p_review_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."review_file_import_mapping"(p_batch_id uuid, p_source_column text, p_target_entity text, p_target_field text, p_decision text, p_review_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."review_file_import_mapping"(p_batch_id uuid, p_source_column text, p_target_entity text, p_target_field text, p_decision text, p_review_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."review_file_import_row_proposal"(p_proposal_id uuid, p_decision text, p_reason text)
 RETURNS file_import_row_proposals
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid:=auth.uid();
  v_proposal public.file_import_row_proposals%rowtype;
  v_batch public.file_import_batches%rowtype;
  v_batch_id uuid;
  v_provider uuid;
  v_client uuid;
  v_site uuid;
  v_zone uuid;
  v_assignee uuid;
  v_subject uuid;
  v_activity uuid;
  v_module_key text;
  v_evidence_type text;
  v_evidence_ref text;
  v_profile text;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_decision NOT IN ('approved','rejected') THEN RAISE EXCEPTION 'Decision must be approved or rejected'; END IF;
  IF nullif(trim(coalesce(p_reason,'')),'') IS NULL THEN RAISE EXCEPTION 'Review reason is required'; END IF;
  SELECT batch_id INTO v_batch_id FROM public.file_import_row_proposals WHERE id=p_proposal_id;
  IF v_batch_id IS NULL THEN RAISE EXCEPTION 'Import proposal not found'; END IF;
  SELECT * INTO v_batch FROM public.file_import_batches WHERE id=v_batch_id FOR UPDATE;
  IF NOT FOUND OR v_batch.status NOT IN ('preview','needs_review') THEN RAISE EXCEPTION 'Import proposal parent batch is no longer open for review'; END IF;
  IF NOT public.is_tenant_import_admin(v_batch.organization_id) THEN RAISE EXCEPTION 'Import review access required'; END IF;
  SELECT * INTO v_proposal FROM public.file_import_row_proposals WHERE id=p_proposal_id FOR UPDATE;
  IF NOT FOUND OR v_proposal.status<>'proposed' THEN RAISE EXCEPTION 'Only proposed import rows can be reviewed'; END IF;

  IF p_decision='approved' THEN
    v_provider:=v_batch.organization_id;
    v_profile:=v_batch.manifest_json->>'source_profile';
    v_client:=NULLIF(v_proposal.proposed_payload->>'client_organization_id','')::uuid;
    v_site:=NULLIF(v_proposal.proposed_payload->>'client_site_id','')::uuid;
    v_zone:=NULLIF(v_proposal.proposed_payload->>'zone_id','')::uuid;
    v_assignee:=NULLIF(v_proposal.proposed_payload->>'assigned_user_id','')::uuid;
    v_subject:=NULLIF(v_proposal.proposed_payload->>'work_subject_code_id','')::uuid;
    v_activity:=NULLIF(v_proposal.proposed_payload->>'work_activity_code_id','')::uuid;
    v_evidence_type:=coalesce(v_proposal.proposed_payload->>'evidence_record_type',v_proposal.source_values->>'evidence_record_type');
    v_evidence_ref:=coalesce(v_proposal.proposed_payload->>'evidence_external_ref',v_proposal.source_values->>'evidence_external_ref');
    v_module_key:=CASE v_proposal.target_type WHEN 'workshop_work_order' THEN 'workshop' WHEN 'finance_service_cost' THEN 'patrol' ELSE NULL END;

    IF v_module_key IS NULL OR v_proposal.proposed_payload->>'organization_id' IS DISTINCT FROM v_provider::text
      OR v_client IS NULL OR ((v_site IS NULL)=(v_zone IS NULL)) THEN
      RAISE EXCEPTION 'Proposal tenant, target type, and exactly one place are required';
    END IF;
    IF v_proposal.source_values->>'source' IS DISTINCT FROM 'rm_patrol_log_import'
      OR v_proposal.source_values->>'source_sha256' IS DISTINCT FROM v_batch.source_sha256
      OR v_proposal.source_values->>'derivative_sha256' IS DISTINCT FROM v_batch.manifest_json->>'derivative_sha256'
      OR v_proposal.source_values->>'source_profile' IS DISTINCT FROM v_profile
      OR nullif(v_proposal.source_values->>'source_file','') IS NULL
      OR coalesce(v_proposal.source_values->>'source_row','') !~ '^[1-9][0-9]*$' THEN
      RAISE EXCEPTION 'Proposal provenance does not match its batch';
    END IF;
    IF NOT EXISTS(
      SELECT 1 FROM public.service_agreements agreement
      JOIN public.service_agreement_modules module ON module.service_agreement_id=agreement.id AND module.module_key=v_module_key AND module.enabled
      JOIN public.service_agreement_locations location ON location.service_agreement_id=agreement.id AND location.status='active'
      WHERE agreement.provider_organization_id=v_provider AND agreement.client_organization_id=v_client
        AND agreement.agreement_type='operational' AND (agreement.starts_on IS NULL OR agreement.starts_on<=current_date) AND (agreement.ends_on IS NULL OR agreement.ends_on>=current_date)
        AND ((v_site IS NOT NULL AND location.site_id=v_site) OR (v_zone IS NOT NULL AND location.zone_id=v_zone))
    ) THEN RAISE EXCEPTION 'Proposal target is outside active contracted module/place coverage'; END IF;

    IF v_evidence_type='observations' THEN
      IF NOT EXISTS(
        SELECT 1 FROM public.observations observation
        WHERE observation.organization_id=v_client AND observation.external_refs->>'external_ref'=v_evidence_ref
          AND observation.external_refs->'import'->>'source'='rm_patrol_log_import'
          AND observation.external_refs->'import'->>'source_sha256'=v_batch.source_sha256
          AND observation.external_refs->'import'->>'derivative_sha256'=v_batch.manifest_json->>'derivative_sha256'
      ) THEN RAISE EXCEPTION 'Proposal observation evidence is missing or outside this batch'; END IF;
    ELSIF v_evidence_type='location_events' THEN
      IF NOT EXISTS(
        SELECT 1 FROM public.location_events event
        WHERE event.organization_id=v_client AND event.external_ref=v_evidence_ref AND event.source='rm_patrol_log_import'
          AND event.payload->>'source'='rm_patrol_log_import' AND event.payload->>'source_sha256'=v_batch.source_sha256
          AND event.payload->>'derivative_sha256'=v_batch.manifest_json->>'derivative_sha256'
      ) THEN RAISE EXCEPTION 'Proposal location event evidence is missing or outside this batch'; END IF;
    ELSE
      RAISE EXCEPTION 'Proposal requires an existing batch-bound observation or location event';
    END IF;

    IF v_proposal.target_type='workshop_work_order' THEN
      IF nullif(v_proposal.proposed_payload->>'scheduled_for','') IS NULL OR v_assignee IS NULL THEN RAISE EXCEPTION 'Workshop proposal schedule and assignee are required'; END IF;
      IF NOT EXISTS(SELECT 1 FROM public.user_profiles profile WHERE profile.id=v_assignee AND profile.deactivated_at IS NULL AND (profile.organization_id=v_provider OR profile.employer_organization_id=v_provider)) THEN RAISE EXCEPTION 'Workshop proposal assignee is outside the provider'; END IF;
      IF NOT EXISTS(SELECT 1 FROM public.reference_codes code WHERE code.id=v_subject AND code.organization_id=v_provider AND code.code_type='work_subject' AND code.is_active) THEN RAISE EXCEPTION 'Workshop proposal subject is invalid'; END IF;
      IF NOT EXISTS(SELECT 1 FROM public.reference_codes code WHERE code.id=v_activity AND code.organization_id=v_provider AND code.code_type='work_activity' AND code.is_active) THEN RAISE EXCEPTION 'Workshop proposal activity is invalid'; END IF;
      IF jsonb_typeof(v_proposal.source_values->'classification_rule_ids')<>'array'
        OR jsonb_array_length(v_proposal.source_values->'classification_rule_ids')<2
        OR EXISTS(
          SELECT 1 FROM jsonb_array_elements_text(v_proposal.source_values->'classification_rule_ids') rule_id
          WHERE NOT EXISTS(
            SELECT 1 FROM public.import_value_classification_rules rule
            WHERE rule.id=rule_id::uuid AND rule.organization_id=v_provider AND rule.source_profile=v_profile AND rule.active
          )
        ) THEN RAISE EXCEPTION 'Workshop proposal classification rules are invalid'; END IF;
    ELSE
      IF coalesce(
        jsonb_typeof(v_proposal.source_values->'job_cost')='number',false
      )=false AND coalesce(jsonb_typeof(v_proposal.source_values->'travel_cost')='number',false)=false
        AND coalesce(jsonb_typeof(v_proposal.source_values->'total_cost')='number',false)=false THEN
        RAISE EXCEPTION 'Finance proposal requires numeric source cost evidence';
      END IF;
      IF coalesce((v_proposal.proposed_payload->>'requires_cost_type_mapping')::boolean,false) THEN
        RAISE EXCEPTION 'Finance proposal cost type mapping must be resolved before approval';
      END IF;
    END IF;
  END IF;

  UPDATE public.file_import_row_proposals
  SET status=p_decision,review_reason=trim(p_reason),reviewed_by=v_actor,reviewed_at=now(),updated_at=now()
  WHERE id=v_proposal.id RETURNING * INTO v_proposal;
  INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
  VALUES(v_proposal.organization_id,v_actor,'file_import_row_proposal_reviewed','file_import_row_proposals',v_proposal.id,
    jsonb_build_object('batch_id',v_proposal.batch_id,'target_type',v_proposal.target_type,'decision',p_decision));
  RETURN v_proposal;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."review_file_import_row_proposal"(p_proposal_id uuid, p_decision text, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."review_file_import_row_proposal"(p_proposal_id uuid, p_decision text, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."review_file_import_row_proposal"(p_proposal_id uuid, p_decision text, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."review_file_import_row_proposal"(p_proposal_id uuid, p_decision text, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."review_identity_document"(p_identity_document_id uuid, p_action text, p_approved_fields jsonb DEFAULT '{}'::jsonb, p_review_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_document public.person_identity_documents%rowtype;
  v_person public.person_records%rowtype;
  v_canonical_id uuid;
  v_name text;
  v_dob date;
  v_details jsonb;
  v_approved_fields jsonb;
  v_face_proposal public.person_identity_face_proposals%rowtype;
  v_can_verify_identity boolean := false;
  v_canonical_updated boolean := false;
BEGIN
  SELECT * INTO v_document FROM public.person_identity_documents WHERE id = p_identity_document_id FOR UPDATE;
  IF v_document.id IS NULL THEN RAISE EXCEPTION 'Identity document not found'; END IF;
  IF v_actor IS NULL OR NOT public.is_admin_for_org(v_document.organization_id) THEN RAISE EXCEPTION 'Identity registry administrator access required'; END IF;
  IF p_action NOT IN ('approve','reject') THEN RAISE EXCEPTION 'Unsupported identity document review action'; END IF;
  IF v_document.review_state <> 'manual_review_required' THEN RAISE EXCEPTION 'Identity document has already been reviewed'; END IF;
  IF coalesce(trim(p_review_notes), '') = '' THEN RAISE EXCEPTION 'Review notes are required'; END IF;
  SELECT * INTO v_person FROM public.person_records WHERE id = v_document.person_record_id AND organization_id = v_document.organization_id FOR UPDATE;
  IF v_person.id IS NULL THEN RAISE EXCEPTION 'Linked person record not found'; END IF;
  SELECT * INTO v_face_proposal FROM public.person_identity_face_proposals
  WHERE identity_document_id = v_document.id FOR UPDATE;

  IF p_action = 'reject' THEN
    DELETE FROM public.person_identity_face_proposals WHERE identity_document_id = v_document.id;
    UPDATE public.person_identity_documents SET review_state = 'rejected', extracted_fields = extracted_fields - 'candidate_matches', reviewed_by = v_actor,
      reviewed_at = clock_timestamp(), review_notes = trim(p_review_notes), updated_at = clock_timestamp() WHERE id = v_document.id;
  ELSE
    v_name := coalesce(nullif(trim(p_approved_fields->>'display_name'), ''), v_person.display_name);
    IF nullif(p_approved_fields->>'date_of_birth', '') IS NOT NULL THEN v_dob := (p_approved_fields->>'date_of_birth')::date; END IF;
    v_details := jsonb_strip_nulls(jsonb_build_object(
      'category', nullif(trim(p_approved_fields->>'category'), ''),
      'notes', nullif(trim(p_approved_fields->>'notes'), ''),
      'email', nullif(trim(p_approved_fields->>'email'), ''),
      'phone', nullif(trim(p_approved_fields->>'phone'), ''),
      'address', nullif(trim(p_approved_fields->>'address'), ''),
      'date_of_birth', v_dob,
      'driver_licence_number', nullif(trim(p_approved_fields->>'driver_licence_number'), ''),
      'driver_licence_expiry', nullif(p_approved_fields->>'driver_licence_expiry', '')::date,
      'firearms_licence_number', nullif(trim(p_approved_fields->>'firearms_licence_number'), ''),
      'firearms_licence_expiry', nullif(p_approved_fields->>'firearms_licence_expiry', '')::date
    ));
    v_approved_fields := v_details || jsonb_strip_nulls(jsonb_build_object('display_name', v_name, 'date_of_birth', v_dob));
    v_can_verify_identity := v_document.document_kind IN ('driver_licence','firearms_licence','passport','national_id')
      AND (nullif(trim(p_approved_fields->>'display_name'), '') IS NOT NULL
        OR nullif(p_approved_fields->>'date_of_birth', '') IS NOT NULL
        OR nullif(trim(p_approved_fields->>'driver_licence_number'), '') IS NOT NULL
        OR nullif(trim(p_approved_fields->>'firearms_licence_number'), '') IS NOT NULL);
    UPDATE public.person_records SET display_name = v_name,
      review_state = CASE WHEN v_can_verify_identity THEN 'verified' ELSE review_state END,
      metadata = metadata || jsonb_build_object('profile_details', coalesce(metadata->'profile_details', '{}'::jsonb) || v_details,
        'last_identity_document_id', v_document.id, 'identity_evidence_approved_at', clock_timestamp(), 'identity_evidence_approved_by', v_actor)
        || CASE WHEN v_can_verify_identity THEN jsonb_build_object('identity_verified_at', clock_timestamp(), 'identity_verified_by', v_actor) ELSE '{}'::jsonb END
    WHERE id = v_person.id RETURNING * INTO v_person;
    v_canonical_id := public.ensure_canonical_person_for_record(v_person.id);
    IF NOT EXISTS (
      SELECT 1 FROM public.canonical_person_links
      WHERE canonical_person_id = v_canonical_id AND organization_id IS DISTINCT FROM v_document.organization_id
    ) THEN
      UPDATE public.canonical_people SET display_name = v_name,
        normalized_name = regexp_replace(lower(coalesce(v_name, '')), '[^a-z0-9]+', '', 'g'),
        date_of_birth = coalesce(v_dob, date_of_birth),
        review_state = CASE WHEN v_can_verify_identity THEN 'verified' ELSE review_state END,
        updated_at = clock_timestamp()
      WHERE id = v_canonical_id;
      v_canonical_updated := true;
    END IF;
    UPDATE public.person_identity_documents SET review_state = 'approved', extracted_fields = extracted_fields || jsonb_build_object('approved', v_approved_fields),
      reviewed_by = v_actor, reviewed_at = clock_timestamp(), review_notes = trim(p_review_notes), updated_at = clock_timestamp()
    WHERE id = v_document.id;
    IF v_face_proposal.identity_document_id IS NOT NULL THEN
      INSERT INTO public.person_face_templates (organization_id, person_record_id, identity_document_id, face_vec,
        confidence, model, source_kind, source_ref, retention_reason, approved_by)
      VALUES (v_document.organization_id, v_document.person_record_id, v_document.id, v_face_proposal.face_vec,
        v_face_proposal.confidence, 'sface', 'identity_document', v_document.id::text, trim(p_review_notes), v_actor);
      DELETE FROM public.person_identity_face_proposals WHERE identity_document_id = v_document.id;
    END IF;
  END IF;
  UPDATE public.bob_attachments SET processing_state = 'extracted',
    extraction_payload = coalesce(extraction_payload, '{}'::jsonb) || jsonb_build_object(
      'review_state', CASE WHEN p_action = 'approve' THEN 'approved' ELSE 'rejected' END,
      'reviewed_at', clock_timestamp(), 'reviewed_by', v_actor),
    updated_at = clock_timestamp() WHERE id = v_document.attachment_id;
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_document.organization_id, v_actor, 'identity_document_' || p_action, 'person_identity_documents', v_document.id,
    jsonb_build_object('person_record_id', v_document.person_record_id, 'document_kind', v_document.document_kind, 'review_notes', trim(p_review_notes)));
  RETURN jsonb_build_object('identity_document_id', v_document.id, 'person_record_id', v_document.person_record_id,
    'canonical_person_id', v_canonical_id, 'canonical_updated', v_canonical_updated,
    'identity_verified', v_can_verify_identity, 'face_candidate_enrolled', p_action = 'approve' AND v_face_proposal.identity_document_id IS NOT NULL,
    'review_state', CASE WHEN p_action='approve' THEN 'approved' ELSE 'rejected' END);
END;
$function$;
COMMENT ON FUNCTION "public"."review_identity_document"(p_identity_document_id uuid, p_action text, p_approved_fields jsonb, p_review_notes text) IS 'Explicit human approval/rejection boundary for identity-document fields and face candidate enrollment.';
REVOKE ALL ON FUNCTION "public"."review_identity_document"(p_identity_document_id uuid, p_action text, p_approved_fields jsonb, p_review_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."review_identity_document"(p_identity_document_id uuid, p_action text, p_approved_fields jsonb, p_review_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."review_identity_document"(p_identity_document_id uuid, p_action text, p_approved_fields jsonb, p_review_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."review_identity_evidence"(p_identity_document_id uuid, p_action text, p_approved_fields jsonb DEFAULT '{}'::jsonb, p_review_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_document public.person_identity_documents%rowtype;
  v_person public.person_records%rowtype;
  v_prior_details jsonb;
  v_current_details jsonb;
  v_result jsonb;
  v_approved jsonb;
  v_number_key text;
  v_expiry_key text;
  v_incoming_expiry date;
  v_existing_expiry date;
  v_promote_current boolean := false;
  v_value text;
BEGIN
  SELECT * INTO v_document FROM public.person_identity_documents WHERE id = p_identity_document_id;
  IF v_document.id IS NULL THEN RAISE EXCEPTION 'Identity document not found'; END IF;
  IF auth.uid() IS NULL OR NOT public.is_admin_for_org(v_document.organization_id) THEN RAISE EXCEPTION 'Identity registry administrator access required'; END IF;
  SELECT * INTO v_person FROM public.person_records WHERE id = v_document.person_record_id AND organization_id = v_document.organization_id;
  IF v_person.id IS NULL THEN RAISE EXCEPTION 'Linked person record not found'; END IF;
  v_prior_details := coalesce(v_person.metadata->'profile_details', '{}'::jsonb);

  v_result := public.review_identity_document(p_identity_document_id, p_action, p_approved_fields, p_review_notes);
  IF p_action <> 'approve' THEN RETURN v_result; END IF;

  v_approved := jsonb_strip_nulls(jsonb_build_object(
    'display_name', nullif(trim(p_approved_fields->>'display_name'), ''),
    'date_of_birth', nullif(p_approved_fields->>'date_of_birth', '')::date,
    'address', nullif(trim(p_approved_fields->>'address'), ''),
    'issued_date', nullif(p_approved_fields->>'issued_date', '')::date,
    'expiry_date', nullif(p_approved_fields->>'expiry_date', '')::date,
    'document_number', nullif(trim(p_approved_fields->>'document_number'), ''),
    'driver_licence_number', nullif(trim(p_approved_fields->>'driver_licence_number'), ''),
    'driver_licence_expiry', nullif(p_approved_fields->>'driver_licence_expiry', '')::date,
    'firearms_licence_number', nullif(trim(p_approved_fields->>'firearms_licence_number'), ''),
    'firearms_licence_expiry', nullif(p_approved_fields->>'firearms_licence_expiry', '')::date,
    'security_licence_number', nullif(trim(p_approved_fields->>'security_licence_number'), ''),
    'security_licence_expiry', nullif(p_approved_fields->>'security_licence_expiry', '')::date,
    'security_licence_authority', nullif(trim(p_approved_fields->>'security_licence_authority'), ''),
    'security_endorsements', nullif(trim(p_approved_fields->>'security_endorsements'), '')
  ));

  IF v_document.document_kind = 'driver_licence' THEN
    v_number_key := 'driver_licence_number'; v_expiry_key := 'driver_licence_expiry';
  ELSIF v_document.document_kind = 'firearms_licence' THEN
    v_number_key := 'firearms_licence_number'; v_expiry_key := 'firearms_licence_expiry';
  ELSIF v_document.document_kind = 'security_licence' THEN
    v_number_key := 'security_licence_number'; v_expiry_key := 'security_licence_expiry';
  END IF;

  IF v_expiry_key IS NOT NULL THEN
    v_incoming_expiry := coalesce(nullif(p_approved_fields->>v_expiry_key, '')::date, nullif(p_approved_fields->>'expiry_date', '')::date);
    v_existing_expiry := nullif(v_prior_details->>v_expiry_key, '')::date;
    v_promote_current := (v_incoming_expiry IS NULL OR v_incoming_expiry >= current_date)
      AND (v_existing_expiry IS NULL OR (v_incoming_expiry IS NOT NULL AND v_incoming_expiry >= v_existing_expiry));
    v_current_details := coalesce((SELECT metadata->'profile_details' FROM public.person_records WHERE id = v_person.id), '{}'::jsonb);
    IF v_promote_current THEN
      IF nullif(trim(p_approved_fields->>v_number_key), '') IS NOT NULL THEN
        v_current_details := jsonb_set(v_current_details, ARRAY[v_number_key], to_jsonb(trim(p_approved_fields->>v_number_key)), true);
      END IF;
      IF v_incoming_expiry IS NOT NULL THEN
        v_current_details := jsonb_set(v_current_details, ARRAY[v_expiry_key], to_jsonb(v_incoming_expiry), true);
      END IF;
      IF v_document.document_kind = 'security_licence' THEN
        FOREACH v_number_key IN ARRAY ARRAY['security_licence_authority','security_endorsements'] LOOP
          v_value := nullif(trim(p_approved_fields->>v_number_key), '');
          IF v_value IS NOT NULL THEN v_current_details := jsonb_set(v_current_details, ARRAY[v_number_key], to_jsonb(v_value), true); END IF;
        END LOOP;
      END IF;
    ELSE
      FOREACH v_number_key IN ARRAY ARRAY[v_number_key, v_expiry_key] LOOP
        IF v_prior_details ? v_number_key THEN
          v_current_details := jsonb_set(v_current_details, ARRAY[v_number_key], v_prior_details->v_number_key, true);
        ELSE
          v_current_details := v_current_details - v_number_key;
        END IF;
      END LOOP;
    END IF;
    UPDATE public.person_records SET metadata = metadata || jsonb_build_object('profile_details', v_current_details) WHERE id = v_person.id;
  END IF;

  UPDATE public.person_identity_documents
  SET extracted_fields = extracted_fields || jsonb_build_object('approved', v_approved, 'promoted_to_current_profile', v_promote_current)
  WHERE id = v_document.id;
  RETURN v_result || jsonb_build_object('current_credential_updated', v_promote_current);
END;
$function$;
COMMENT ON FUNCTION "public"."review_identity_evidence"(p_identity_document_id uuid, p_action text, p_approved_fields jsonb, p_review_notes text) IS 'Human review boundary for identity evidence. Keeps older/expired licence versions as evidence without replacing the current profile credential.';
REVOKE ALL ON FUNCTION "public"."review_identity_evidence"(p_identity_document_id uuid, p_action text, p_approved_fields jsonb, p_review_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."review_identity_evidence"(p_identity_document_id uuid, p_action text, p_approved_fields jsonb, p_review_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."review_identity_evidence"(p_identity_document_id uuid, p_action text, p_approved_fields jsonb, p_review_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."review_leave_request"(p_request_id uuid, p_expected_status text, p_decision text, p_review_notes text DEFAULT NULL::text)
 RETURNS leave_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_leave public.leave_requests%rowtype;v_notes text:=nullif(trim(coalesce(p_review_notes,'')), '');v_officer_user_id uuid;
begin
  select * into v_leave from public.leave_requests where id=p_request_id for update;if not found then raise exception 'Leave request not found';end if;
  if not exists(select 1 from public.user_profiles actor where actor.id=v_actor and actor.deactivated_at is null and actor.role in('grand_master','master','admin', 'admin_officer') and coalesce(actor.employer_organization_id,actor.organization_id)=v_leave.organization_id) then raise exception 'Corporate leave approval required';end if;
  if v_leave.status<>p_expected_status or v_leave.status<>'branch_checked' or p_decision not in('approved','declined') then raise exception 'Only branch-checked leave requests are available for corporate decision';end if;
  if p_decision='approved' and v_leave.branch_reviewed_by=v_actor then raise exception 'A different corporate reviewer must approve this leave request';end if;
  if p_decision='declined' and v_notes is null then raise exception 'Review notes are required to decline leave';end if;
  if p_decision='approved' and exists(select 1 from public.roster_slots slot where slot.staff_id=v_leave.staff_id and slot.status not in('declined','cancelled') and daterange((slot.scheduled_start at time zone 'Pacific/Auckland')::date,(slot.scheduled_end at time zone 'Pacific/Auckland')::date,'[]')&&daterange(v_leave.starts_on,v_leave.ends_on,'[]')) then raise exception 'Active roster slots overlap this leave request';end if;
  update public.leave_requests set status=p_decision,approved_by=v_actor,approved_at=clock_timestamp(),decision_notes=v_notes where id=v_leave.id returning * into v_leave;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)values(v_leave.organization_id,v_actor,case when p_decision='approved' then 'leave_corporate_approved' else 'leave_corporate_declined' end,'leave_requests',v_leave.id,jsonb_build_object('staff_id',v_leave.staff_id,'branch_reviewed_organization_id',v_leave.branch_reviewed_organization_id,'review_notes',v_notes));
  select coalesce(staff.user_id,staff.id) into v_officer_user_id from public.staff_profiles staff where staff.id=v_leave.staff_id;
  if v_officer_user_id is not null then perform public.enqueue_notification(p_organization_id=>v_leave.organization_id,p_category=>'leave_decision',p_title=>'Leave request '||v_leave.status,p_body=>coalesce(v_notes,'Your leave request has been '||v_leave.status||'.'),p_severity=>'info',p_recipient_user_id=>v_officer_user_id,p_link_page=>'leave-decision',p_link_payload=>jsonb_build_object('leave_request_id',v_leave.id,'status',v_leave.status),p_dedup_key=>'leave_decision:'||v_leave.id::text||':'||v_leave.status);end if;
  return v_leave;
end;$function$;
REVOKE ALL ON FUNCTION "public"."review_leave_request"(p_request_id uuid, p_expected_status text, p_decision text, p_review_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."review_leave_request"(p_request_id uuid, p_expected_status text, p_decision text, p_review_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."review_leave_request"(p_request_id uuid, p_expected_status text, p_decision text, p_review_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."review_leave_request"(p_request_id uuid, p_expected_status text, p_decision text, p_review_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."review_monthly_report_pack"(p_pack_id uuid, p_expected_updated_at timestamp with time zone, p_title text DEFAULT NULL::text, p_executive_summary text DEFAULT NULL::text, p_client_notes text DEFAULT NULL::text, p_follow_up text DEFAULT NULL::text, p_action text DEFAULT 'save'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_pack record;
  v_editorial jsonb;
  v_client_has_login boolean := false;
  v_delivery_channel text;
  v_updated public.monthly_report_packs%rowtype;
  v_cleared jsonb;
  v_pending integer;
begin
  if v_actor is null then
    raise exception 'Authenticated provider administrator required';
  end if;
  if p_action not in ('save', 'publish') then
    raise exception 'Action must be save or publish';
  end if;
  if p_expected_updated_at is null then
    raise exception 'Expected updated timestamp is required';
  end if;
  if length(coalesce(p_title, '')) > 160
     or length(coalesce(p_executive_summary, '')) > 4000
     or length(coalesce(p_client_notes, '')) > 8000
     or length(coalesce(p_follow_up, '')) > 4000 then
    raise exception 'Report review content exceeds the allowed length';
  end if;

  select pack.*, agreement.client_organization_id,
         agreement.client_portal_reports_enabled
  into v_pack
  from public.monthly_report_packs pack
  join public.service_agreements agreement
    on agreement.id = pack.service_agreement_id
  where pack.id = p_pack_id
  for update of pack;

  if v_pack.id is null then
    raise exception 'Report pack not found';
  end if;
  if not public.is_admin_for_org(v_pack.organization_id) then
    raise exception 'Provider administrator access required';
  end if;
  if v_pack.status = 'sent' then
    raise exception 'Sent report packs are immutable';
  end if;
  if v_pack.updated_at is distinct from p_expected_updated_at then
    raise exception 'Report pack changed since it was opened; reload before saving';
  end if;

  v_editorial := jsonb_strip_nulls(jsonb_build_object(
    'title', nullif(btrim(coalesce(p_title, '')), ''),
    'executive_summary', nullif(btrim(coalesce(p_executive_summary, '')), ''),
    'client_notes', nullif(btrim(coalesce(p_client_notes, '')), ''),
    'follow_up', nullif(btrim(coalesce(p_follow_up, '')), '')
  ));

  if p_action = 'publish' and not (v_editorial ? 'title') then
    raise exception 'A client-facing report title is required before publishing';
  end if;

  -- Publishing makes the pack client-readable, so a monthly pack with a frozen
  -- activity copy must carry Bob's privacy clearance for every entry and for
  -- this exact wording (written by the check-report-privacy edge function).
  if p_action = 'publish'
     and coalesce(v_pack.report_kind, 'monthly') <> 'custom'
     and jsonb_typeof(v_pack.activity_lines) = 'object'
     and jsonb_typeof(v_pack.activity_lines -> 'lines') = 'array' then
    select count(*)::integer
    into v_pending
    from jsonb_array_elements(v_pack.activity_lines -> 'lines') line
    where (line -> 'pv') is distinct from to_jsonb(1)
      and exists (
        select 1
        from unnest(array['ti', 'n', 'ac']) field
        where jsonb_typeof(line -> field) = 'string'
          and (line ->> field) ~ '\S'
      );
    if v_pending > 0 then
      raise exception 'Run Bob''s privacy check first: % report entries have not been checked for personal names', v_pending
        using errcode = 'P0001';
    end if;

    v_cleared := v_pack.activity_lines -> 'privacy' -> 'cleared_editorial';
    if jsonb_typeof(v_cleared) is distinct from 'object'
       or exists (
         select 1
         from (values
           ('title', p_title),
           ('executive_summary', p_executive_summary),
           ('client_notes', p_client_notes),
           ('follow_up', p_follow_up)
         ) submitted(field, value)
         where regexp_replace(coalesce(submitted.value, ''), '^\s+|\s+$', '', 'g')
               is distinct from coalesce(v_cleared ->> submitted.field, '')
       ) then
      raise exception 'Run Bob''s privacy check first: the report wording has changed since it was last checked for personal names'
        using errcode = 'P0001';
    end if;
  end if;

  select exists (
    select 1
    from public.user_profiles profile
    where profile.organization_id = v_pack.client_organization_id
      and profile.deactivated_at is null
      and profile.role in ('client_admin', 'client_officer', 'client_viewer')
  )
  into v_client_has_login;

  if p_action = 'publish' then
    v_delivery_channel := case
      when v_pack.client_portal_reports_enabled and v_client_has_login then 'portal'
      else 'email'
    end;
  end if;

  update public.monthly_report_packs
  set editorial = v_editorial,
      status = case when p_action = 'publish' then 'generated' else 'draft' end,
      reviewed_at = clock_timestamp(),
      reviewed_by = v_actor,
      published_at = case when p_action = 'publish' then clock_timestamp() else null end,
      published_by = case when p_action = 'publish' then v_actor else null end,
      delivery_channel = v_delivery_channel,
      pdf_path = null,
      pdf_mime_type = null,
      pdf_sha256 = null,
      pdf_renderer_version = null,
      delivery_error = null,
      updated_at = clock_timestamp()
  where id = p_pack_id
    and updated_at = p_expected_updated_at
  returning * into v_updated;

  if v_updated.id is null then
    raise exception 'Report pack changed since it was opened; reload before saving';
  end if;

  insert into public.audit_log (
    organization_id, actor_user_id, action, target_table, target_id, metadata
  ) values (
    v_updated.organization_id,
    v_actor,
    case when p_action = 'publish'
      then 'monthly_report_pack_published'
      else 'monthly_report_pack_review_saved'
    end,
    'monthly_report_packs',
    v_updated.id,
    jsonb_build_object(
      'status', v_updated.status,
      'delivery_channel', v_updated.delivery_channel,
      'client_has_login', v_client_has_login,
      'editorial_fields', array(select jsonb_object_keys(v_editorial))
    )
  );

  return jsonb_build_object(
    'id', v_updated.id,
    'status', v_updated.status,
    'editorial', v_updated.editorial,
    'updated_at', v_updated.updated_at,
    'reviewed_at', v_updated.reviewed_at,
    'published_at', v_updated.published_at,
    'delivery_channel', v_updated.delivery_channel,
    'client_has_login', v_client_has_login
  );
end;
$function$;
COMMENT ON FUNCTION "public"."review_monthly_report_pack"(p_pack_id uuid, p_expected_updated_at timestamp with time zone, p_title text, p_executive_summary text, p_client_notes text, p_follow_up text, p_action text) IS 'Saves or publishes provider-authored report editorial content with optimistic locking and audit evidence. Publishing a monthly pack requires Bob''s privacy clearance for every entry and the exact wording. Source-derived metrics are not editable; sent packs are immutable.';
REVOKE ALL ON FUNCTION "public"."review_monthly_report_pack"(p_pack_id uuid, p_expected_updated_at timestamp with time zone, p_title text, p_executive_summary text, p_client_notes text, p_follow_up text, p_action text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."review_monthly_report_pack"(p_pack_id uuid, p_expected_updated_at timestamp with time zone, p_title text, p_executive_summary text, p_client_notes text, p_follow_up text, p_action text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."review_monthly_report_pack"(p_pack_id uuid, p_expected_updated_at timestamp with time zone, p_title text, p_executive_summary text, p_client_notes text, p_follow_up text, p_action text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."review_noise_photo_classification"(p_assessment_id uuid, p_action text, p_source_candidate text, p_equipment_candidate text, p_level_candidate text, p_notes text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_assessment public.noise_assessments%ROWTYPE;
  v_envelope uuid;
  v_field public.perception_evidence_fields%ROWTYPE;
  v_action text := lower(trim(coalesce(p_action,'')));
  v_notes text := nullif(trim(coalesce(p_notes,'')),'');
  v_value text;
  v_new_field uuid;
  v_ordinal integer;
BEGIN
  SELECT * INTO v_assessment
  FROM public.noise_assessments
  WHERE id = p_assessment_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Noise assessment is missing'; END IF;
  IF v_actor IS NULL OR NOT public.is_admin_for_org(v_assessment.organization_id) THEN
    RAISE EXCEPTION 'Active Noise Control administrator required';
  END IF;
  IF v_action NOT IN ('confirm','correct','reject') THEN
    RAISE EXCEPTION 'Unsupported noise photo review action';
  END IF;
  IF v_notes IS NULL THEN RAISE EXCEPTION 'Review notes are required'; END IF;
  IF jsonb_typeof(v_assessment.noise_ai_analysis) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'This assessment has no structured photo classification to review';
  END IF;
  IF v_action IN ('confirm','correct')
     AND coalesce(v_assessment.noise_ai_analysis->>'status','unavailable') <> 'available' THEN
    RAISE EXCEPTION 'An unavailable machine classification cannot be approved';
  END IF;

  SELECT id INTO v_envelope
  FROM public.perception_evidence_envelopes
  WHERE organization_id = v_assessment.organization_id
    AND domain = 'noise_photo'
    AND source_receipt->>'noise_assessment_id' = v_assessment.id::text
  ORDER BY created_at DESC, id DESC
  LIMIT 1;
  IF v_envelope IS NULL THEN RAISE EXCEPTION 'Noise photo evidence envelope is missing'; END IF;

  FOR v_field IN
    SELECT * FROM public.perception_evidence_fields
    WHERE envelope_id = v_envelope
      AND candidate_ordinal = 0
      AND field_key IN (
        'noise.source_candidate','noise.equipment_candidate','noise.estimated_level_candidate'
      )
    ORDER BY field_key
  LOOP
    IF v_action = 'reject' THEN
      INSERT INTO public.perception_evidence_reviews (
        organization_id,field_id,previous_authority_state,decision,
        next_authority_state,reviewer_notes,canonical_reference,decided_by
      ) VALUES (
        v_assessment.organization_id,v_field.id,v_field.authority_state,'reject',
        'rejected',v_notes,jsonb_build_object('noise_assessment_id',v_assessment.id),v_actor
      );
      UPDATE public.perception_evidence_fields
      SET authority_state='rejected',review_required=false,updated_at=clock_timestamp()
      WHERE id=v_field.id;
      CONTINUE;
    END IF;

    v_value := CASE v_field.field_key
      WHEN 'noise.source_candidate' THEN nullif(trim(coalesce(p_source_candidate,'')),'')
      WHEN 'noise.equipment_candidate' THEN nullif(trim(coalesce(p_equipment_candidate,'')),'')
      WHEN 'noise.estimated_level_candidate' THEN nullif(trim(coalesce(p_level_candidate,'')),'')
    END;
    IF v_value IS NULL THEN CONTINUE; END IF;

    INSERT INTO public.perception_evidence_reviews (
      organization_id,field_id,previous_authority_state,decision,
      next_authority_state,reviewer_notes,canonical_reference,decided_by
    ) VALUES (
      v_assessment.organization_id,v_field.id,v_field.authority_state,'supersede',
      'superseded',v_notes,jsonb_build_object('noise_assessment_id',v_assessment.id),v_actor
    );
    UPDATE public.perception_evidence_fields
    SET authority_state='superseded',review_required=false,updated_at=clock_timestamp()
    WHERE id=v_field.id;

    SELECT coalesce(max(candidate_ordinal),0)+1 INTO v_ordinal
    FROM public.perception_evidence_fields
    WHERE envelope_id=v_envelope AND field_key=v_field.field_key;

    INSERT INTO public.perception_evidence_fields (
      organization_id,envelope_id,field_key,candidate_ordinal,value_type,
      candidate_value,normalized_value,candidate_payload,source_locations,
      consensus_rule,authority_state,review_required
    ) VALUES (
      v_assessment.organization_id,v_envelope,v_field.field_key,v_ordinal,v_field.value_type,
      to_jsonb(v_value),lower(v_value),
      jsonb_build_object('source','human_noise_photo_review','machine_candidate_preserved',true),
      v_field.source_locations,'attributable_human_noise_photo_review_v1','candidate',true
    ) RETURNING id INTO v_new_field;

    INSERT INTO public.perception_evidence_reviews (
      organization_id,field_id,previous_authority_state,decision,
      next_authority_state,reviewer_notes,canonical_reference,decided_by
    ) VALUES (
      v_assessment.organization_id,v_new_field,'candidate',
      CASE WHEN v_action='correct' THEN 'correct' ELSE 'approve' END,
      'human_approved',v_notes,jsonb_build_object('noise_assessment_id',v_assessment.id),v_actor
    );
    UPDATE public.perception_evidence_fields
    SET authority_state='human_approved',review_required=false,updated_at=clock_timestamp()
    WHERE id=v_new_field;
  END LOOP;

  UPDATE public.noise_assessments
  SET noise_ai_review = jsonb_strip_nulls(jsonb_build_object(
        'action',v_action,
        'source_candidate',p_source_candidate,
        'equipment_candidate',p_equipment_candidate,
        'level_candidate',p_level_candidate,
        'notes',v_notes,
        'reviewed_by',v_actor,
        'reviewed_at',clock_timestamp()
      )),
      updated_at=clock_timestamp()
  WHERE id=v_assessment.id;

  INSERT INTO public.audit_log (
    organization_id,actor_user_id,action,target_table,target_id,metadata
  ) VALUES (
    v_assessment.organization_id,v_actor,'noise_photo_classification_reviewed',
    'noise_assessments',v_assessment.id,
    jsonb_build_object(
      'review_action',v_action,
      'acoustic_matrix_changed',false,
      'legal_action_changed',false,
      'notice_changed',false,
      'notes',v_notes
    )
  );

  RETURN jsonb_build_object(
    'assessment_id',v_assessment.id,'action',v_action,
    'reviewed_by',v_actor,'matrix_changed',false,'legal_action_changed',false
  );
END;
$function$;
REVOKE ALL ON FUNCTION "public"."review_noise_photo_classification"(p_assessment_id uuid, p_action text, p_source_candidate text, p_equipment_candidate text, p_level_candidate text, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."review_noise_photo_classification"(p_assessment_id uuid, p_action text, p_source_candidate text, p_equipment_candidate text, p_level_candidate text, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."review_noise_photo_classification"(p_assessment_id uuid, p_action text, p_source_candidate text, p_equipment_candidate text, p_level_candidate text, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."review_noise_photo_classification"(p_assessment_id uuid, p_action text, p_source_candidate text, p_equipment_candidate text, p_level_candidate text, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."review_nzta_mvr_identity_evidence"(p_identity_document_id uuid, p_action text, p_approved_fields jsonb DEFAULT '{}'::jsonb, p_review_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_document public.person_identity_documents%rowtype;
  v_person public.person_records%rowtype;
  v_plate text;
  v_checked_at timestamptz;
  v_canonical_person_id uuid;
  v_vehicle_result jsonb;
  v_vehicle_id uuid;
  v_vehicle public.canonical_vehicles%rowtype;
  v_check_id uuid;
  v_result jsonb;
  v_year integer;
  v_vin text := nullif(upper(regexp_replace(trim(coalesce(p_approved_fields->>'vin', '')), '[^A-Z0-9]', '', 'g')), '');
  v_chassis text := nullif(upper(regexp_replace(trim(coalesce(p_approved_fields->>'chassis_number', '')), '[^A-Z0-9-]', '', 'g')), '');
  v_engine text := nullif(upper(regexp_replace(trim(coalesce(p_approved_fields->>'engine_number', '')), '[^A-Z0-9-]', '', 'g')), '');
BEGIN
  SELECT * INTO v_document
  FROM public.person_identity_documents
  WHERE id = p_identity_document_id
  FOR UPDATE;
  IF v_document.id IS NULL OR v_document.document_kind <> 'nzta_mvr_record' THEN
    RAISE EXCEPTION 'NZTA MVR identity evidence not found';
  END IF;
  IF v_actor IS NULL OR NOT public.is_admin_for_org(v_document.organization_id) THEN
    RAISE EXCEPTION 'Identity registry administrator access required';
  END IF;
  IF p_action NOT IN ('approve', 'reject') THEN
    RAISE EXCEPTION 'Unsupported identity evidence action';
  END IF;
  IF p_action = 'reject' THEN
    RETURN public.review_canonical_identity_evidence(
      p_identity_document_id, p_action, '{}'::jsonb, p_review_notes
    );
  END IF;
  IF v_document.review_state <> 'manual_review_required' THEN
    RAISE EXCEPTION 'Identity evidence has already been reviewed';
  END IF;
  IF coalesce(p_approved_fields->>'person_vehicle_match_confirmed', '') <> 'true' THEN
    RAISE EXCEPTION 'Confirm that the private source image links this person and vehicle';
  END IF;
  v_plate := public.normalize_plate_number(p_approved_fields->>'plate_number');
  IF v_plate IS NULL OR length(v_plate) > 10 THEN
    RAISE EXCEPTION 'A valid plate from the source image is required';
  END IF;
  v_checked_at := nullif(p_approved_fields->>'query_completed_at', '')::timestamptz;
  IF v_checked_at IS NULL OR v_checked_at > clock_timestamp() + interval '5 minutes' THEN
    RAISE EXCEPTION 'A valid NZTA query completion time is required';
  END IF;
  IF nullif(p_approved_fields->>'vehicle_year', '') IS NOT NULL THEN
    v_year := (p_approved_fields->>'vehicle_year')::integer;
    IF v_year NOT BETWEEN 1886 AND extract(year FROM current_date)::integer + 1 THEN
      RAISE EXCEPTION 'Enter a valid vehicle year';
    END IF;
  END IF;

  SELECT * INTO v_person
  FROM public.person_records
  WHERE id = v_document.person_record_id
    AND organization_id = v_document.organization_id;
  IF v_person.id IS NULL THEN
    RAISE EXCEPTION 'Person record not found in this organization';
  END IF;

  v_result := public.review_canonical_identity_evidence(
    p_identity_document_id, p_action, p_approved_fields, p_review_notes
  );
  v_canonical_person_id := public.ensure_canonical_person_for_record(v_person.id);
  UPDATE public.person_records
  SET review_state = 'verified'
  WHERE id = v_person.id;
  UPDATE public.canonical_people
  SET
    display_name = coalesce(nullif(trim(p_approved_fields->>'display_name'), ''), display_name),
    normalized_name = regexp_replace(
      lower(trim(coalesce(nullif(p_approved_fields->>'display_name', ''), display_name, ''))),
      '[^a-z0-9]+', '', 'g'
    ),
    review_state = 'verified',
    metadata = metadata || jsonb_build_object(
      'last_nzta_mvr_identity_document_id', v_document.id,
      'last_nzta_mvr_checked_at', v_checked_at,
      'last_nzta_mvr_reviewed_by', v_actor
    ),
    updated_at = clock_timestamp()
  WHERE id = v_canonical_person_id;

  v_vehicle_result := public.manage_identity_vehicle(
    v_document.organization_id,
    NULL,
    v_plate,
    jsonb_strip_nulls(jsonb_build_object(
      'make', nullif(trim(p_approved_fields->>'vehicle_make'), ''),
      'model', nullif(trim(p_approved_fields->>'vehicle_model'), ''),
      'year', v_year,
      'colour', nullif(trim(p_approved_fields->>'vehicle_colour'), ''),
      'body_type', nullif(trim(p_approved_fields->>'vehicle_body_type'), ''),
      'rego_expiry', nullif(p_approved_fields->>'rego_expiry', ''),
      'wof_expiry', nullif(p_approved_fields->>'wof_expiry', ''),
      'cof_expiry', nullif(p_approved_fields->>'cof_expiry', ''),
      'notes', nullif(trim(p_approved_fields->>'vehicle_notes'), '')
    )),
    'Human-approved NZTA MVR source image ' || p_identity_document_id::text
  );
  v_vehicle_id := (v_vehicle_result->>'vehicle_id')::uuid;

  SELECT * INTO v_vehicle
  FROM public.canonical_vehicles
  WHERE id = v_vehicle_id
  FOR UPDATE;
  IF v_vehicle.id IS NULL THEN
    RAISE EXCEPTION 'Canonical vehicle was not returned';
  END IF;
  IF NOT public.is_grand_master() AND (
    (v_vin IS NOT NULL AND v_vehicle.vin IS NOT NULL AND v_vehicle.vin <> v_vin)
    OR (v_chassis IS NOT NULL AND v_vehicle.chassis_number IS NOT NULL AND v_vehicle.chassis_number <> v_chassis)
    OR (v_engine IS NOT NULL AND v_vehicle.engine_number IS NOT NULL AND v_vehicle.engine_number <> v_engine)
  ) THEN
    RAISE EXCEPTION 'Conflicting canonical vehicle identifiers require grand master review';
  END IF;

  UPDATE public.canonical_vehicles
  SET
    vin = coalesce(v_vin, vin),
    chassis_number = coalesce(v_chassis, chassis_number),
    engine_number = coalesce(v_engine, engine_number),
    fuel_type = coalesce(nullif(trim(p_approved_fields->>'fuel_type'), ''), fuel_type),
    compliance_checked_at = v_checked_at,
    compliance_source = 'nzta_mvr',
    rego_status = CASE
      WHEN lower(coalesce(p_approved_fields->>'registration_status', '')) IN ('active','current') THEN 'current'
      WHEN lower(coalesce(p_approved_fields->>'registration_status', '')) IN ('expired','cancelled','inactive') THEN lower(p_approved_fields->>'registration_status')
      ELSE rego_status
    END,
    wof_status = CASE
      WHEN nullif(p_approved_fields->>'wof_expiry', '')::date >= v_checked_at::date THEN 'current'
      WHEN nullif(p_approved_fields->>'wof_expiry', '') IS NOT NULL THEN 'expired'
      ELSE wof_status
    END,
    cof_status = CASE
      WHEN nullif(p_approved_fields->>'cof_expiry', '')::date >= v_checked_at::date THEN 'current'
      WHEN nullif(p_approved_fields->>'cof_expiry', '') IS NOT NULL THEN 'expired'
      ELSE cof_status
    END,
    updated_at = clock_timestamp()
  WHERE id = v_vehicle_id;

  UPDATE public.person_records
  SET metadata = metadata || jsonb_build_object(
    'profile_details',
    coalesce(metadata->'profile_details', '{}'::jsonb)
      || jsonb_build_object(
        'nzta_mvr_sourced', true,
        'nzta_mvr_last_checked_at', v_checked_at,
        'nzta_mvr_last_identity_document_id', v_document.id
      )
  )
  WHERE id = v_person.id;

  INSERT INTO public.vehicle_identity_checks (
    organization_id, canonical_vehicle_id, person_record_id,
    canonical_person_id, identity_document_id, evidence_item_id,
    checked_at, vehicle_snapshot, reviewed_by
  ) VALUES (
    v_document.organization_id, v_vehicle_id, v_person.id,
    v_canonical_person_id, v_document.id, v_document.evidence_item_id,
    v_checked_at,
    p_approved_fields - ARRAY[
      'address','email','phone','driver_licence_number','firearms_licence_number',
      'security_licence_number','document_number'
    ],
    v_actor
  )
  ON CONFLICT (identity_document_id) DO UPDATE SET
    canonical_vehicle_id = excluded.canonical_vehicle_id,
    person_record_id = excluded.person_record_id,
    canonical_person_id = excluded.canonical_person_id,
    evidence_item_id = excluded.evidence_item_id,
    checked_at = excluded.checked_at,
    vehicle_snapshot = excluded.vehicle_snapshot,
    reviewed_by = excluded.reviewed_by,
    reviewed_at = clock_timestamp()
  RETURNING id INTO v_check_id;

  INSERT INTO public.audit_log (
    organization_id, actor_user_id, action, target_table, target_id, metadata
  ) VALUES (
    v_document.organization_id, v_actor, 'nzta_mvr_identity_check_approved',
    'vehicle_identity_checks', v_check_id,
    jsonb_build_object(
      'canonical_vehicle_id', v_vehicle_id,
      'canonical_person_id', v_canonical_person_id,
      'person_record_id', v_person.id,
      'identity_document_id', v_document.id,
      'evidence_item_id', v_document.evidence_item_id,
      'checked_at', v_checked_at,
      'source_authority', 'NZTA Motor Vehicle Register'
    )
  );

  RETURN v_result || jsonb_build_object(
    'vehicle_identity_check_id', v_check_id,
    'canonical_vehicle_id', v_vehicle_id,
    'canonical_person_id', v_canonical_person_id,
    'nzta_check_completed', true,
    'checked_at', v_checked_at
  );
END;
$function$;
COMMENT ON FUNCTION "public"."review_nzta_mvr_identity_evidence"(p_identity_document_id uuid, p_action text, p_approved_fields jsonb, p_review_notes text) IS 'Human approval boundary for private NZTA MVR source images. Promotes reviewed vehicle facts, records a source-time person/vehicle link, preserves the evidence link, and audits the decision.';
REVOKE ALL ON FUNCTION "public"."review_nzta_mvr_identity_evidence"(p_identity_document_id uuid, p_action text, p_approved_fields jsonb, p_review_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."review_nzta_mvr_identity_evidence"(p_identity_document_id uuid, p_action text, p_approved_fields jsonb, p_review_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."review_nzta_mvr_identity_evidence"(p_identity_document_id uuid, p_action text, p_approved_fields jsonb, p_review_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."review_nzta_mvr_identity_evidence"(p_identity_document_id uuid, p_action text, p_approved_fields jsonb, p_review_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."review_nzta_mvr_owner_evidence"(p_identity_document_id uuid, p_approved_fields jsonb, p_review_notes text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_document public.person_identity_documents%rowtype;
  v_person public.person_records%rowtype;
  v_canonical_person_id uuid;
  v_vehicle_result jsonb;
  v_vehicle_id uuid;
  v_check_id uuid;
  v_existing public.vehicle_identity_checks%rowtype;
  v_existing_plate text;
  v_plate text := public.normalize_plate_number(p_approved_fields->>'plate_number');
  v_checked_at timestamptz := nullif(p_approved_fields->>'query_completed_at', '')::timestamptz;
  v_display_name text := nullif(trim(p_approved_fields->>'display_name'), '');
  v_notes text := nullif(trim(coalesce(p_review_notes, '')), '');
BEGIN
  SELECT * INTO v_document
  FROM public.person_identity_documents
  WHERE id = p_identity_document_id
  FOR UPDATE;
  IF v_document.id IS NULL OR v_document.document_kind <> 'nzta_mvr_record' THEN
    RAISE EXCEPTION 'NZTA MVR identity evidence not found';
  END IF;
  IF v_actor IS NULL
     OR NOT public.is_admin_for_org(v_document.organization_id)
     OR NOT public.can_access_vehicle_owner_identity(v_document.organization_id, true) THEN
    RAISE EXCEPTION 'Identity registry and vehicle owner identity administrator access required';
  END IF;
  IF v_document.review_state <> 'manual_review_required' THEN
    RAISE EXCEPTION 'Identity evidence is not awaiting review';
  END IF;
  IF jsonb_typeof(p_approved_fields) IS DISTINCT FROM 'object'
     OR coalesce(p_approved_fields->>'person_vehicle_match_confirmed', '') <> 'true' THEN
    RAISE EXCEPTION 'Confirm that the private source image links this person and vehicle';
  END IF;
  IF v_plate IS NULL OR length(v_plate) > 10 THEN
    RAISE EXCEPTION 'A valid plate from the source image is required';
  END IF;
  IF v_checked_at IS NULL OR v_checked_at > clock_timestamp() + interval '5 minutes' THEN
    RAISE EXCEPTION 'A valid NZTA query completion time is required';
  END IF;
  IF v_notes IS NULL OR char_length(v_notes) > 1000 THEN
    RAISE EXCEPTION 'A review reason of 1 to 1000 characters is required';
  END IF;

  SELECT * INTO v_person
  FROM public.person_records
  WHERE id = v_document.person_record_id
    AND organization_id = v_document.organization_id;
  IF v_person.id IS NULL THEN RAISE EXCEPTION 'Person record not found in this organization'; END IF;
  IF v_document.evidence_item_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.evidence_items item
    WHERE item.id = v_document.evidence_item_id
      AND item.organization_id = v_document.organization_id
  ) THEN
    RAISE EXCEPTION 'Private NZTA source evidence is missing';
  END IF;

  v_canonical_person_id := public.ensure_canonical_person_for_record(v_person.id);
  IF v_canonical_person_id IS NULL THEN RAISE EXCEPTION 'The person could not be linked to a canonical person'; END IF;

  SELECT * INTO v_existing
  FROM public.vehicle_identity_checks
  WHERE identity_document_id = v_document.id
  FOR UPDATE;
  IF v_existing.id IS NOT NULL THEN
    SELECT public.normalize_plate_number(vehicle.plate_number)
      INTO v_existing_plate
    FROM public.canonical_vehicles vehicle
    WHERE vehicle.id = v_existing.canonical_vehicle_id;
    IF v_existing.checked_at <> v_checked_at
       OR v_existing.vehicle_snapshot->>'owner_only_review' IS DISTINCT FROM 'true'
       OR v_existing.person_record_id <> v_person.id
       OR v_existing.canonical_person_id <> v_canonical_person_id
       OR v_existing_plate IS DISTINCT FROM v_plate THEN
      RAISE EXCEPTION 'Identity evidence already has a different source-time check';
    END IF;
    PERFORM public.sync_nzta_registered_owner_history(
      v_document.organization_id, v_existing.canonical_vehicle_id
    );
    RETURN jsonb_build_object(
      'identity_document_id', v_document.id,
      'identity_check_id', v_existing.id,
      'canonical_vehicle_id', v_existing.canonical_vehicle_id,
      'owner_history_synchronized', true,
      'vehicle_facts_pending', true,
      'inserted', false
    );
  END IF;

  v_vehicle_result := public.manage_identity_vehicle(
    v_document.organization_id,
    NULL,
    v_plate,
    '{}'::jsonb,
    'NZTA registered-owner identity reviewed; vehicle facts remain pending for source comparison'
  );
  v_vehicle_id := (v_vehicle_result->>'vehicle_id')::uuid;
  IF v_vehicle_id IS NULL THEN RAISE EXCEPTION 'Canonical vehicle was not returned'; END IF;

  UPDATE public.person_records
  SET review_state = 'verified',
      metadata = metadata || jsonb_build_object(
        'profile_details',
        coalesce(metadata->'profile_details', '{}'::jsonb) || jsonb_build_object(
          'nzta_mvr_sourced', true,
          'nzta_mvr_last_checked_at', v_checked_at,
          'nzta_mvr_owner_identity_document_id', v_document.id
        )
      )
  WHERE id = v_person.id;
  UPDATE public.canonical_people
  SET display_name = coalesce(v_display_name, display_name),
      normalized_name = regexp_replace(
        lower(trim(coalesce(v_display_name, display_name, ''))),
        '[^a-z0-9]+', '', 'g'
      ),
      review_state = 'verified',
      metadata = metadata || jsonb_build_object(
        'last_nzta_mvr_owner_identity_document_id', v_document.id,
        'last_nzta_mvr_checked_at', v_checked_at,
        'last_nzta_mvr_reviewed_by', v_actor
      ),
      updated_at = clock_timestamp()
  WHERE id = v_canonical_person_id;

  INSERT INTO public.vehicle_identity_checks (
    organization_id, canonical_vehicle_id, person_record_id,
    canonical_person_id, identity_document_id, evidence_item_id,
    checked_at, vehicle_snapshot, reviewed_by
  ) VALUES (
    v_document.organization_id, v_vehicle_id, v_person.id,
    v_canonical_person_id, v_document.id, v_document.evidence_item_id,
    v_checked_at,
    p_approved_fields - ARRAY[
      'address', 'email', 'phone', 'driver_licence_number',
      'firearms_licence_number', 'security_licence_number', 'document_number'
    ] || jsonb_build_object(
      'owner_only_review', true,
      'vehicle_facts_review_state', 'manual_review_required'
    ),
    v_actor
  )
  RETURNING id INTO v_check_id;

  UPDATE public.person_identity_documents
  SET extracted_fields = jsonb_set(
        coalesce(extracted_fields, '{}'::jsonb),
        '{owner_review}',
        jsonb_build_object(
          'decision', 'registered_owner_confirmed',
          'reviewed_by', v_actor,
          'reviewed_at', clock_timestamp(),
          'source_checked_at', v_checked_at,
          'vehicle_facts_pending', true,
          'notes', v_notes
        ),
        true
      ),
      updated_at = clock_timestamp()
  WHERE id = v_document.id;

  INSERT INTO public.audit_log (
    organization_id, actor_user_id, action, target_table, target_id, metadata
  ) VALUES (
    v_document.organization_id, v_actor, 'nzta_owner_identity_reviewed',
    'person_identity_documents', v_document.id,
    jsonb_build_object(
      'identity_check_id', v_check_id,
      'canonical_vehicle_id', v_vehicle_id,
      'canonical_person_id', v_canonical_person_id,
      'source_checked_at', v_checked_at,
      'vehicle_facts_pending', true,
      'review_notes', v_notes
    )
  );

  RETURN jsonb_build_object(
    'identity_document_id', v_document.id,
    'identity_check_id', v_check_id,
    'canonical_vehicle_id', v_vehicle_id,
    'canonical_person_id', v_canonical_person_id,
    'owner_history_synchronized', true,
    'vehicle_facts_pending', true,
    'inserted', true
  );
END;
$function$;
COMMENT ON FUNCTION "public"."review_nzta_mvr_owner_evidence"(p_identity_document_id uuid, p_approved_fields jsonb, p_review_notes text) IS 'Separately confirms the registered person and check time from a consistent NZTA source image while leaving conflicting or unreviewed mechanical vehicle facts in the identity review queue.';
REVOKE ALL ON FUNCTION "public"."review_nzta_mvr_owner_evidence"(p_identity_document_id uuid, p_approved_fields jsonb, p_review_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."review_nzta_mvr_owner_evidence"(p_identity_document_id uuid, p_approved_fields jsonb, p_review_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."review_nzta_mvr_owner_evidence"(p_identity_document_id uuid, p_approved_fields jsonb, p_review_notes text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."review_observation_person_mention"(p_mention_id uuid, p_action text, p_notes text DEFAULT NULL::text, p_set_identity_of_record boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_mention public.observation_person_mentions%rowtype;
  v_person public.person_records%rowtype;
BEGIN
  SELECT * INTO v_mention FROM public.observation_person_mentions WHERE id = p_mention_id FOR UPDATE;
  IF v_actor IS NULL OR v_mention.id IS NULL OR NOT public.org_access_allowed(v_mention.organization_id) THEN
    RAISE EXCEPTION 'Mention not found in your authorised scope';
  END IF;
  IF p_action NOT IN ('confirm', 'dismiss') THEN RAISE EXCEPTION 'Unsupported action'; END IF;
  IF v_mention.status <> 'unconfirmed' AND NOT (p_action = 'confirm' AND p_set_identity_of_record AND v_mention.status = 'confirmed') THEN
    RAISE EXCEPTION 'This mention has already been reviewed';
  END IF;
  IF coalesce(trim(p_notes), '') = '' THEN RAISE EXCEPTION 'Review notes are required'; END IF;
  IF p_action = 'dismiss' THEN
    IF v_mention.created_by IS DISTINCT FROM v_actor AND NOT public.is_admin_for_org(v_mention.organization_id) THEN
      RAISE EXCEPTION 'Only the person who recorded this mention or an administrator can dismiss it';
    END IF;
  ELSE
    IF NOT public.is_admin_for_org(v_mention.organization_id) THEN RAISE EXCEPTION 'An administrator confirms people at a sighting'; END IF;
    SELECT * INTO v_person FROM public.person_records WHERE id = v_mention.person_record_id;
    IF v_person.review_state <> 'verified' THEN
      RAISE EXCEPTION 'Verify this person''s identity (approved ID evidence) before confirming them at the sighting';
    END IF;
    IF p_set_identity_of_record THEN
      -- The existing governed path enforces administrator, verified person and verified canonical identity.
      PERFORM public.link_observation_entities(v_mention.observation_id, v_mention.organization_id, NULL, v_mention.person_record_id,
        NULL, NULL, NULL, NULL, trim(p_notes));
    END IF;
  END IF;
  UPDATE public.observation_person_mentions
  SET status = CASE WHEN p_action = 'confirm' THEN 'confirmed' ELSE 'dismissed' END,
      reviewed_by = v_actor, reviewed_at = clock_timestamp(), review_notes = trim(p_notes)
  WHERE id = v_mention.id;
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_mention.organization_id, v_actor,
    CASE WHEN p_action = 'confirm' THEN 'observation_person_confirmed' ELSE 'observation_person_dismissed' END,
    'observation_person_mentions', v_mention.id,
    jsonb_build_object('observation_id', v_mention.observation_id, 'person_record_id', v_mention.person_record_id,
      'identity_of_record', p_action = 'confirm' AND p_set_identity_of_record, 'notes', trim(p_notes)));
  RETURN jsonb_build_object('mention_id', v_mention.id, 'status', CASE WHEN p_action = 'confirm' THEN 'confirmed' ELSE 'dismissed' END,
    'identity_of_record', p_action = 'confirm' AND p_set_identity_of_record);
END;
$function$;
REVOKE ALL ON FUNCTION "public"."review_observation_person_mention"(p_mention_id uuid, p_action text, p_notes text, p_set_identity_of_record boolean) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."review_observation_person_mention"(p_mention_id uuid, p_action text, p_notes text, p_set_identity_of_record boolean) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."review_observation_person_mention"(p_mention_id uuid, p_action text, p_notes text, p_set_identity_of_record boolean) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."review_officer_field_report"(p_report_id uuid, p_expected_status report_status, p_review_notes text)
 RETURNS officer_field_reports
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor_id uuid:=auth.uid();v_report public.officer_field_reports%rowtype;
begin
  if v_actor_id is null then raise exception 'Authentication required';end if;
  if nullif(trim(p_review_notes),'') is null then raise exception 'Review notes are required';end if;
  select * into v_report from public.officer_field_reports where id=p_report_id for update;if not found then raise exception 'Field report not found';end if;
  if not public.is_admin_for_org(v_report.organization_id) then raise exception 'Not authorised to review this field report';end if;
  if v_report.status<>p_expected_status then raise exception 'Field report changed from expected status % to %',p_expected_status,v_report.status;end if;
  if v_report.status<>'submitted' then raise exception 'Only submitted field reports can be reviewed';end if;
  update public.officer_field_reports set status='reviewed',reviewed_by=v_actor_id,reviewed_at=clock_timestamp(),review_notes=trim(p_review_notes),updated_at=clock_timestamp() where id=p_report_id returning * into v_report;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_report.organization_id,v_actor_id,'officer_field_report_reviewed','officer_field_reports',v_report.id,jsonb_build_object('officer_id',v_report.officer_id,'severity',v_report.severity,'review_notes',v_report.review_notes));
  perform public.enqueue_notification(p_organization_id=>v_report.organization_id,p_category=>'report_reviewed',p_title=>'Field report reviewed',p_body=>v_report.review_notes,p_severity=>'info',p_recipient_user_id=>v_report.officer_id,p_link_page=>'field-report-review',p_link_payload=>jsonb_build_object('report_id',v_report.id),p_dedup_key=>'field-report-reviewed:'||v_report.id::text);
  return v_report;
end;$function$;
COMMENT ON FUNCTION "public"."review_officer_field_report"(p_report_id uuid, p_expected_status report_status, p_review_notes text) IS 'Race-checks and records the submitted-to-reviewed field report transition with required supervisor notes and audit provenance.';
REVOKE ALL ON FUNCTION "public"."review_officer_field_report"(p_report_id uuid, p_expected_status report_status, p_review_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."review_officer_field_report"(p_report_id uuid, p_expected_status report_status, p_review_notes text) TO "postgres";
