GRANT EXECUTE ON FUNCTION "public"."review_officer_field_report"(p_report_id uuid, p_expected_status report_status, p_review_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."review_organization_brand_asset"(p_asset_id uuid, p_decision text, p_reason text)
 RETURNS organization_brand_assets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_asset public.organization_brand_assets;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_decision NOT IN ('approved', 'revoked') THEN RAISE EXCEPTION 'Brand asset decision must be approved or revoked'; END IF;
  IF nullif(trim(coalesce(p_reason, '')), '') IS NULL THEN RAISE EXCEPTION 'Brand asset review reason is required'; END IF;
  SELECT * INTO v_asset FROM public.organization_brand_assets WHERE id = p_asset_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Brand asset not found'; END IF;
  IF NOT public.is_admin_for_org(v_asset.organization_id) AND NOT public.is_grand_master() THEN RAISE EXCEPTION 'Brand asset review denied'; END IF;

  UPDATE public.organization_brand_assets
  SET status = p_decision,
      approved_by = CASE WHEN p_decision = 'approved' THEN v_actor ELSE approved_by END,
      approved_at = CASE WHEN p_decision = 'approved' THEN clock_timestamp() ELSE approved_at END,
      updated_at = clock_timestamp()
  WHERE id = v_asset.id
  RETURNING * INTO v_asset;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_asset.organization_id, v_actor, 'organization_brand_asset_reviewed', 'organization_brand_assets', v_asset.id,
    jsonb_build_object('decision', p_decision, 'reason', trim(p_reason)));
  RETURN v_asset;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."review_organization_brand_asset"(p_asset_id uuid, p_decision text, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."review_organization_brand_asset"(p_asset_id uuid, p_decision text, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."review_organization_brand_asset"(p_asset_id uuid, p_decision text, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."review_organization_brand_asset"(p_asset_id uuid, p_decision text, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."review_organization_compliance_record"(p_record_id uuid, p_expected_updated_at timestamp with time zone, p_decision text, p_review_notes text DEFAULT NULL::text)
 RETURNS organization_compliance_records
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_record public.organization_compliance_records%rowtype;
BEGIN
  IF p_decision NOT IN ('verified', 'rejected') THEN
    RAISE EXCEPTION 'Decision must be verified or rejected';
  END IF;

  SELECT *
  INTO v_record
  FROM public.organization_compliance_records
  WHERE id = p_record_id
    AND status = 'current'
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Current compliance record not found';
  END IF;
  IF v_actor IS NULL OR NOT public.is_admin_for_org(v_record.organization_id) OR NOT EXISTS (
    SELECT 1
    FROM public.user_profiles actor
    WHERE actor.id = v_actor
      AND actor.deactivated_at IS NULL
      AND actor.role IN ('grand_master', 'master')
  ) THEN
    RAISE EXCEPTION 'Active organization master required';
  END IF;
  IF v_record.updated_at <> p_expected_updated_at THEN
    RAISE EXCEPTION 'Compliance record changed since it was opened';
  END IF;
  IF p_decision = 'verified' AND (
    v_record.source_name IS NULL
    OR v_record.source_as_of IS NULL
    OR (v_record.record_type IN ('company_licence', 'insurance') AND (
      v_record.reference_number IS NULL
      OR v_record.issuer IS NULL
      OR v_record.expiry_date IS NULL
    ))
  ) THEN
    RAISE EXCEPTION 'Required source, reference, issuer, or expiry evidence is missing';
  END IF;

  UPDATE public.organization_compliance_records
  SET
    verification_status = p_decision,
    verified_by = CASE WHEN p_decision = 'verified' THEN v_actor ELSE NULL END,
    verified_at = CASE WHEN p_decision = 'verified' THEN clock_timestamp() ELSE NULL END,
    review_notes = nullif(trim(coalesce(p_review_notes, '')), ''),
    updated_by = v_actor,
    updated_at = clock_timestamp()
  WHERE id = v_record.id
  RETURNING * INTO v_record;

  INSERT INTO public.audit_log (
    organization_id,
    actor_user_id,
    action,
    target_table,
    target_id,
    metadata
  )
  VALUES (
    v_record.organization_id,
    v_actor,
    'organization_compliance_record_reviewed',
    'organization_compliance_records',
    v_record.id,
    jsonb_build_object(
      'record_type', v_record.record_type,
      'decision', p_decision,
      'expiry_date', v_record.expiry_date
    )
  );

  RETURN v_record;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."review_organization_compliance_record"(p_record_id uuid, p_expected_updated_at timestamp with time zone, p_decision text, p_review_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."review_organization_compliance_record"(p_record_id uuid, p_expected_updated_at timestamp with time zone, p_decision text, p_review_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."review_organization_compliance_record"(p_record_id uuid, p_expected_updated_at timestamp with time zone, p_decision text, p_review_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."review_organization_compliance_record"(p_record_id uuid, p_expected_updated_at timestamp with time zone, p_decision text, p_review_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."review_organization_corporate_profile"(p_organization_id uuid, p_expected_updated_at timestamp with time zone, p_decision text)
 RETURNS organizations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org public.organizations%rowtype;
BEGIN
  IF p_decision NOT IN ('verified', 'rejected') THEN
    RAISE EXCEPTION 'Decision must be verified or rejected';
  END IF;
  IF v_actor IS NULL OR NOT public.is_admin_for_org(p_organization_id) OR NOT EXISTS (
    SELECT 1
    FROM public.user_profiles actor
    WHERE actor.id = v_actor
      AND actor.deactivated_at IS NULL
      AND actor.role IN ('grand_master', 'master')
  ) THEN
    RAISE EXCEPTION 'Active organization master required';
  END IF;

  SELECT *
  INTO v_org
  FROM public.organizations
  WHERE id = p_organization_id
    AND parent_organization_id IS NULL
    AND active
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Active root organization not found';
  END IF;
  IF v_org.updated_at <> p_expected_updated_at THEN
    RAISE EXCEPTION 'Organization changed since it was opened';
  END IF;
  IF p_decision = 'verified' AND (
    v_org.legal_name IS NULL
    OR v_org.nzbn IS NULL
    OR v_org.company_registration_number IS NULL
    OR v_org.corporate_profile_source IS NULL
  ) THEN
    RAISE EXCEPTION 'Legal name, NZBN, company number, and source are required before verification';
  END IF;

  UPDATE public.organizations
  SET
    corporate_profile_verification_status = p_decision,
    corporate_profile_verified_by = CASE WHEN p_decision = 'verified' THEN v_actor ELSE NULL END,
    corporate_profile_verified_at = CASE WHEN p_decision = 'verified' THEN clock_timestamp() ELSE NULL END,
    updated_at = clock_timestamp()
  WHERE id = v_org.id
  RETURNING * INTO v_org;

  INSERT INTO public.audit_log (
    organization_id,
    actor_user_id,
    action,
    target_table,
    target_id,
    metadata
  )
  VALUES (
    v_org.id,
    v_actor,
    'organization_corporate_profile_reviewed',
    'organizations',
    v_org.id,
    jsonb_build_object('decision', p_decision)
  );

  RETURN v_org;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."review_organization_corporate_profile"(p_organization_id uuid, p_expected_updated_at timestamp with time zone, p_decision text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."review_organization_corporate_profile"(p_organization_id uuid, p_expected_updated_at timestamp with time zone, p_decision text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."review_organization_corporate_profile"(p_organization_id uuid, p_expected_updated_at timestamp with time zone, p_decision text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."review_organization_corporate_profile"(p_organization_id uuid, p_expected_updated_at timestamp with time zone, p_decision text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."review_perception_evidence_field"(p_field_id uuid, p_decision text, p_reviewer_notes text DEFAULT NULL::text, p_canonical_reference jsonb DEFAULT '{}'::jsonb)
 RETURNS perception_evidence_fields
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_field public.perception_evidence_fields%rowtype;
  v_next text;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT * INTO v_field FROM public.perception_evidence_fields WHERE id = p_field_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Perception field is missing'; END IF;
  IF NOT public.is_admin_for_org(v_field.organization_id) THEN
    RAISE EXCEPTION 'Administrator review authority required';
  END IF;
  IF p_decision = 'approve' THEN v_next := 'human_approved';
  ELSIF p_decision = 'reject' THEN v_next := 'rejected';
  ELSIF p_decision IN ('uncertain','needs_more_context') THEN v_next := 'candidate';
  ELSIF p_decision = 'supersede' THEN v_next := 'superseded';
  ELSE RAISE EXCEPTION 'Perception review decision is invalid';
  END IF;
  IF jsonb_typeof(coalesce(p_canonical_reference, '{}'::jsonb)) <> 'object' THEN
    RAISE EXCEPTION 'Canonical reference must be an object';
  END IF;

  INSERT INTO public.perception_evidence_reviews (
    organization_id, field_id, previous_authority_state, decision,
    next_authority_state, reviewer_notes, canonical_reference, decided_by
  ) VALUES (
    v_field.organization_id, v_field.id, v_field.authority_state, p_decision,
    v_next, nullif(trim(p_reviewer_notes), ''), coalesce(p_canonical_reference, '{}'::jsonb), v_actor
  );

  UPDATE public.perception_evidence_fields
  SET authority_state = v_next,
      review_required = (v_next NOT IN ('human_approved','rejected','superseded')),
      updated_at = clock_timestamp()
  WHERE id = v_field.id
  RETURNING * INTO v_field;

  UPDATE public.perception_evidence_envelopes
  SET status = CASE
        WHEN EXISTS (
          SELECT 1 FROM public.perception_evidence_fields f
          WHERE f.envelope_id = v_field.envelope_id AND f.review_required
        ) THEN 'manual_review_required'
        ELSE 'complete'
      END,
      updated_at = clock_timestamp()
  WHERE id = v_field.envelope_id;

  INSERT INTO public.audit_log (
    organization_id, actor_user_id, action, target_table, target_id, metadata
  ) VALUES (
    v_field.organization_id, v_actor, 'perception_evidence_reviewed',
    'perception_evidence_fields', v_field.id,
    jsonb_build_object('decision', p_decision, 'authority_state', v_next, 'canonical_reference', coalesce(p_canonical_reference, '{}'::jsonb))
  );
  RETURN v_field;
END;
$function$;
COMMENT ON FUNCTION "public"."review_perception_evidence_field"(p_field_id uuid, p_decision text, p_reviewer_notes text, p_canonical_reference jsonb) IS 'Administrator review of one perception candidate. Writes an append-only decision receipt and updates the guarded current authority state.';
REVOKE ALL ON FUNCTION "public"."review_perception_evidence_field"(p_field_id uuid, p_decision text, p_reviewer_notes text, p_canonical_reference jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."review_perception_evidence_field"(p_field_id uuid, p_decision text, p_reviewer_notes text, p_canonical_reference jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."review_perception_evidence_field"(p_field_id uuid, p_decision text, p_reviewer_notes text, p_canonical_reference jsonb) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."review_perception_evidence_field"(p_field_id uuid, p_decision text, p_reviewer_notes text, p_canonical_reference jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."review_person_detail_update"(p_interaction_id uuid, p_decision text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_pi public.person_interactions%rowtype;
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
  v_status text;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Sign in to review person details' USING ERRCODE = '42501'; END IF;
  IF p_decision IS NULL OR p_decision NOT IN ('apply', 'dismiss') THEN RAISE EXCEPTION 'Choose apply or dismiss'; END IF;
  IF v_reason IS NULL OR length(v_reason) < 3 THEN RAISE EXCEPTION 'A reason is required for the identity audit trail'; END IF;
  SELECT * INTO v_pi FROM public.person_interactions WHERE id = p_interaction_id FOR UPDATE;
  IF v_pi.id IS NULL OR public.is_admin_for_org(v_pi.organization_id) IS NOT TRUE THEN
    RAISE EXCEPTION 'Only an administrator of this organisation can review these details' USING ERRCODE = '42501';
  END IF;
  IF v_pi.proposal_status IS DISTINCT FROM 'pending' THEN RAISE EXCEPTION 'These details have already been reviewed'; END IF;

  IF p_decision = 'apply' THEN
    PERFORM public.apply_person_interaction_details(v_pi.id, v_reason);
    v_status := 'applied';
  ELSE
    v_status := 'dismissed';
  END IF;
  UPDATE public.person_interactions
  SET proposal_status = v_status, proposal_reviewed_by = v_actor, proposal_reviewed_at = clock_timestamp(),
      proposal_review_reason = v_reason
  WHERE id = v_pi.id;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_pi.organization_id, v_actor, 'person_detail_update_' || v_status, 'person_interactions', v_pi.id,
    jsonb_build_object('person_record_id', v_pi.person_record_id, 'reason', v_reason,
      'detail_fields', to_jsonb(array(SELECT jsonb_object_keys(v_pi.proposed_details)))));
  RETURN jsonb_build_object('interaction_id', v_pi.id, 'person_record_id', v_pi.person_record_id, 'proposal_status', v_status);
END;
$function$;
COMMENT ON FUNCTION "public"."review_person_detail_update"(p_interaction_id uuid, p_decision text, p_reason text) IS 'Administrator applies or dismisses person details an officer gave for an existing person record. Applying goes through manage_identity_person (audited); every decision is audited with a reason.';
REVOKE ALL ON FUNCTION "public"."review_person_detail_update"(p_interaction_id uuid, p_decision text, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."review_person_detail_update"(p_interaction_id uuid, p_decision text, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."review_person_detail_update"(p_interaction_id uuid, p_decision text, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."review_person_detail_update"(p_interaction_id uuid, p_decision text, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."review_place_hazard"(p_hazard_id uuid, p_expected_version integer, p_owner_id uuid, p_control_levels jsonb, p_review_due date, p_notes text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_h public.place_hazards%rowtype;
BEGIN
  SELECT * INTO v_h FROM public.place_hazards WHERE id = p_hazard_id FOR UPDATE;
  IF NOT FOUND OR auth.uid() IS NULL OR NOT public.can_manage_place_hazards(v_h.organization_id, v_h.location_id) THEN
    RAISE EXCEPTION 'Place hazard review access denied';
  END IF;
  IF v_h.status = 'retired' OR v_h.version IS DISTINCT FROM p_expected_version THEN
    RAISE EXCEPTION 'This hazard changed. Reload it before recording the review';
  END IF;
  IF length(btrim(coalesce(p_notes, ''))) NOT BETWEEN 10 AND 4000
    OR p_review_due IS NULL OR p_review_due <= current_date THEN
    RAISE EXCEPTION 'Record review findings and a future next-review date';
  END IF;
  UPDATE public.place_hazards SET risk_owner_id = p_owner_id,
    control_levels = coalesce(p_control_levels, '{}'::jsonb), review_due = p_review_due,
    status = 'active', reviewed_by = auth.uid(), reviewed_at = clock_timestamp(), version = version + 1
  WHERE id = v_h.id;
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_h.organization_id, auth.uid(), 'place_hazard_reviewed', 'place_hazards', v_h.id,
    jsonb_build_object('previous_version', v_h.version, 'owner_id', p_owner_id, 'next_review', p_review_due, 'findings', btrim(p_notes)));
  RETURN v_h.id;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."review_place_hazard"(p_hazard_id uuid, p_expected_version integer, p_owner_id uuid, p_control_levels jsonb, p_review_due date, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."review_place_hazard"(p_hazard_id uuid, p_expected_version integer, p_owner_id uuid, p_control_levels jsonb, p_review_due date, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."review_place_hazard"(p_hazard_id uuid, p_expected_version integer, p_owner_id uuid, p_control_levels jsonb, p_review_due date, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."review_place_hazard"(p_hazard_id uuid, p_expected_version integer, p_owner_id uuid, p_control_levels jsonb, p_review_due date, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."review_shift_swap"(p_client_request_id uuid, p_swap_id uuid, p_expected_status text, p_decision text, p_review_notes text DEFAULT NULL::text)
 RETURNS shift_swaps
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid := auth.uid(); v_swap public.shift_swaps%rowtype; v_orig_shift public.shifts%rowtype; v_notes text := nullif(trim(coalesce(p_review_notes, '')), ''); v_original_user uuid; v_replacement_user uuid;
begin
  if p_client_request_id is null then raise exception 'client_request_id is required'; end if;
  select sw.* into v_swap from public.shift_swaps sw where sw.id = p_swap_id for update;
  if not found then raise exception 'Shift swap request not found'; end if;
  if not public.is_admin_for_org(v_swap.organization_id) then raise exception 'Not authorised to review shift swaps for this organization'; end if;
  if v_swap.status <> p_expected_status then raise exception 'Shift swap changed from expected status % to %', p_expected_status, v_swap.status; end if;
  if p_decision not in ('approved', 'declined') then raise exception 'Decision must be approved or declined'; end if;
  select coalesce(sp.user_id, sp.id) into v_original_user from public.staff_profiles sp where sp.id = v_swap.original_staff_id;
  select coalesce(sp.user_id, sp.id) into v_replacement_user from public.staff_profiles sp where sp.id = v_swap.swap_with_staff_id;
  if p_decision = 'approved' then
    if v_swap.swap_with_staff_id is null then raise exception 'Cannot approve swap without designated replacement staff'; end if;
    select sh.* into v_orig_shift from public.shifts sh where sh.id = v_swap.original_shift_id;
    if found then update public.shifts set officer_user_id = v_swap.swap_with_staff_id, updated_at = now() where id = v_orig_shift.id; if v_orig_shift.roster_slot_id is not null then update public.roster_slots set staff_id = v_swap.swap_with_staff_id, updated_at = now() where id = v_orig_shift.roster_slot_id; end if; end if;
    update public.shift_swaps set status = 'approved', approved_by = v_actor, approved_at = now(), completed_at = now() where id = v_swap.id returning * into v_swap;
  else
    update public.shift_swaps set status = 'declined', declined_reason = v_notes, approved_by = v_actor, approved_at = now() where id = v_swap.id returning * into v_swap;
  end if;
  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata) values (v_swap.organization_id, v_actor, 'shift_swap_reviewed', 'shift_swaps', v_swap.id, jsonb_build_object('decision', p_decision, 'original_shift_id', v_swap.original_shift_id, 'swap_with_staff_id', v_swap.swap_with_staff_id, 'client_request_id', p_client_request_id));
  if v_original_user is not null then perform public.enqueue_notification(v_swap.organization_id, 'roster', 'Shift swap ' || p_decision, coalesce(v_notes, 'Your shift swap request has been ' || p_decision || '.'), 'info', v_original_user, null, 'schedule', jsonb_build_object('shift_swap_id', v_swap.id, 'status', v_swap.status), 'shift_swap_decision:' || v_swap.id::text || ':original:' || v_swap.status); end if;
  if v_replacement_user is not null and v_replacement_user is distinct from v_original_user then perform public.enqueue_notification(v_swap.organization_id, 'roster', 'Direct shift swap ' || p_decision, coalesce(v_notes, 'The direct shift swap has been ' || p_decision || '.'), 'info', v_replacement_user, null, 'schedule', jsonb_build_object('shift_swap_id', v_swap.id, 'status', v_swap.status), 'shift_swap_decision:' || v_swap.id::text || ':replacement:' || v_swap.status); end if;
  return v_swap;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."review_shift_swap"(p_client_request_id uuid, p_swap_id uuid, p_expected_status text, p_decision text, p_review_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."review_shift_swap"(p_client_request_id uuid, p_swap_id uuid, p_expected_status text, p_decision text, p_review_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."review_shift_swap"(p_client_request_id uuid, p_swap_id uuid, p_expected_status text, p_decision text, p_review_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."review_shift_swap"(p_client_request_id uuid, p_swap_id uuid, p_expected_status text, p_decision text, p_review_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."review_smoke_photo_classification"(p_assessment_id uuid, p_action text, p_smoke_source_type text, p_severity text, p_notes text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_assessment public.smoke_assessments%ROWTYPE;
  v_action text := lower(trim(coalesce(p_action, '')));
  v_notes text := nullif(trim(coalesce(p_notes, '')), '');
  v_source text := nullif(trim(coalesce(p_smoke_source_type, '')), '');
  v_severity text := nullif(trim(coalesce(p_severity, '')), '');
BEGIN
  SELECT * INTO v_assessment
  FROM public.smoke_assessments
  WHERE id = p_assessment_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Smoke assessment is missing'; END IF;
  IF v_actor IS NULL OR NOT public.is_admin_for_org(v_assessment.organization_id) THEN
    RAISE EXCEPTION 'Active Smoke Control administrator required';
  END IF;
  IF v_action NOT IN ('confirm', 'correct', 'reject') THEN
    RAISE EXCEPTION 'Unsupported smoke photo review action';
  END IF;
  IF v_notes IS NULL THEN RAISE EXCEPTION 'Review notes are required'; END IF;
  IF jsonb_typeof(v_assessment.smoke_ai_analysis) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'This assessment has no structured photo classification to review';
  END IF;
  IF v_action IN ('confirm', 'correct')
     AND coalesce(v_assessment.smoke_ai_analysis->>'status', 'unavailable') <> 'available' THEN
    RAISE EXCEPTION 'An unavailable machine classification cannot be approved';
  END IF;
  IF v_action IN ('confirm', 'correct')
     AND v_source NOT IN (
       'domestic_solid_fuel', 'industrial', 'vehicle_exhaust',
       'agricultural', 'nuisance_burning', 'unknown'
     ) THEN
    RAISE EXCEPTION 'A supported canonical smoke source is required';
  END IF;
  IF v_action IN ('confirm', 'correct')
     AND v_severity NOT IN ('low', 'moderate', 'high', 'critical') THEN
    RAISE EXCEPTION 'A supported canonical severity is required';
  END IF;

  UPDATE public.smoke_assessments
  SET smoke_source_type = CASE WHEN v_action IN ('confirm', 'correct') THEN v_source ELSE smoke_source_type END,
      smoke_source = CASE WHEN v_action IN ('confirm', 'correct') THEN v_source ELSE smoke_source END,
      severity = CASE WHEN v_action IN ('confirm', 'correct') THEN v_severity ELSE severity END,
      source_confirmed = CASE WHEN v_action IN ('confirm', 'correct') THEN true ELSE source_confirmed END,
      smoke_ai_review = jsonb_strip_nulls(jsonb_build_object(
        'action', v_action,
        'smoke_source_type', CASE WHEN v_action IN ('confirm', 'correct') THEN v_source END,
        'severity', CASE WHEN v_action IN ('confirm', 'correct') THEN v_severity END,
        'notes', v_notes,
        'reviewed_by', v_actor,
        'reviewed_at', clock_timestamp()
      )),
      updated_at = clock_timestamp()
  WHERE id = v_assessment.id
  RETURNING * INTO v_assessment;

  PERFORM private.apply_smoke_photo_review_to_perception(v_assessment.id);

  INSERT INTO public.audit_log (
    organization_id, actor_user_id, action, target_table, target_id, metadata
  ) VALUES (
    v_assessment.organization_id, v_actor, 'smoke_photo_classification_reviewed',
    'smoke_assessments', v_assessment.id,
    jsonb_build_object(
      'review_action', v_action,
      'smoke_source_type', v_source,
      'severity', v_severity,
      'legal_action_changed', false,
      'notice_changed', false,
      'notes', v_notes
    )
  );

  RETURN jsonb_build_object(
    'assessment_id', v_assessment.id,
    'action', v_action,
    'smoke_source_type', v_assessment.smoke_source_type,
    'severity', v_assessment.severity,
    'reviewed_by', v_actor,
    'reviewed_at', v_assessment.smoke_ai_review->>'reviewed_at'
  );
END;
$function$;
COMMENT ON FUNCTION "public"."review_smoke_photo_classification"(p_assessment_id uuid, p_action text, p_smoke_source_type text, p_severity text, p_notes text) IS 'Administrator-only field review for advisory smoke photo candidates. It never changes legal action, notice number, legal basis, or workflow closure.';
REVOKE ALL ON FUNCTION "public"."review_smoke_photo_classification"(p_assessment_id uuid, p_action text, p_smoke_source_type text, p_severity text, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."review_smoke_photo_classification"(p_assessment_id uuid, p_action text, p_smoke_source_type text, p_severity text, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."review_smoke_photo_classification"(p_assessment_id uuid, p_action text, p_smoke_source_type text, p_severity text, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."review_smoke_photo_classification"(p_assessment_id uuid, p_action text, p_smoke_source_type text, p_severity text, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."review_timesheet"(p_timesheet_id uuid, p_expected_status text, p_decision text, p_review_notes text DEFAULT NULL::text)
 RETURNS timesheets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_sheet public.timesheets%rowtype;
  v_notes text := nullif(trim(coalesce(p_review_notes, '')), '');
  v_officer_user_id uuid;
  v_pay_blocker text;
begin
  select t.* into v_sheet from public.timesheets t where t.id = p_timesheet_id for update;
  if not found then raise exception 'Timesheet not found'; end if;
  if not public.is_admin_for_org(v_sheet.organization_id) then raise exception 'Not authorised to review this timesheet'; end if;
  if v_sheet.status <> p_expected_status then raise exception 'Timesheet changed from expected status % to %', p_expected_status, v_sheet.status; end if;
  if v_sheet.status not in ('submitted', 'branch_checked') or p_decision not in ('approved', 'rejected') then raise exception 'Unsupported timesheet decision'; end if;
  if v_sheet.status = 'branch_checked' and v_sheet.branch_reviewed_by = v_actor then raise exception 'Final approval must come from a different reviewer than the branch check'; end if;
  if p_decision = 'rejected' and v_notes is null then raise exception 'Review notes are required to reject a timesheet'; end if;
  if v_sheet.actual_hours is null then raise exception 'Actual hours are required before review'; end if;

  if p_decision = 'approved' then
    v_pay_blocker := public.timesheet_dispatch_pay_review_blocker(v_sheet.id);
    if v_pay_blocker is not null then
      raise exception 'Timesheet cannot be approved: %', v_pay_blocker;
    end if;
  end if;

  update public.timesheets set status = p_decision, approved_by = v_actor, approved_at = clock_timestamp(), review_notes = v_notes where id = v_sheet.id returning * into v_sheet;
  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata) values(v_sheet.organization_id, v_actor, case when p_decision = 'approved' then 'timesheet_approved' else 'timesheet_rejected' end, 'timesheets', v_sheet.id, jsonb_build_object('staff_id', v_sheet.staff_id, 'period_start', v_sheet.period_start, 'period_end', v_sheet.period_end, 'actual_hours', v_sheet.actual_hours, 'overtime_hours', v_sheet.overtime_hours, 'review_notes', v_notes, 'previous_status', p_expected_status, 'branch_reviewed_by', v_sheet.branch_reviewed_by));
  select coalesce(sp.user_id, sp.id) into v_officer_user_id from public.staff_profiles sp where sp.id = v_sheet.staff_id;
  if v_officer_user_id is not null then perform public.enqueue_notification(p_organization_id => v_sheet.organization_id, p_category => 'timesheet_decision', p_title => 'Timesheet ' || v_sheet.status, p_body => coalesce(v_notes, 'Your timesheet has been ' || v_sheet.status || '.'), p_severity => 'info', p_recipient_user_id => v_officer_user_id, p_link_page => 'timesheet-decision', p_link_payload => jsonb_build_object('timesheet_id', v_sheet.id, 'status', v_sheet.status), p_dedup_key => 'timesheet_decision:' || v_sheet.id::text || ':' || v_sheet.status); end if;
  return v_sheet;
end;
$function$;
COMMENT ON FUNCTION "public"."review_timesheet"(p_timesheet_id uuid, p_expected_status text, p_decision text, p_review_notes text) IS 'Corporate final decision on a timesheet: approve or reject from submitted (single-organisation employer) or branch_checked (branch model). The final reviewer must differ from the branch reviewer. Approval is blocked while dispatch pay lines await review.';
REVOKE ALL ON FUNCTION "public"."review_timesheet"(p_timesheet_id uuid, p_expected_status text, p_decision text, p_review_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."review_timesheet"(p_timesheet_id uuid, p_expected_status text, p_decision text, p_review_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."review_timesheet"(p_timesheet_id uuid, p_expected_status text, p_decision text, p_review_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."review_timesheet"(p_timesheet_id uuid, p_expected_status text, p_decision text, p_review_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."review_website_enquiry"(p_enquiry_id uuid, p_status text, p_note text, p_expected_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_status text := lower(btrim(coalesce(p_status, '')));
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  v_provider uuid;
  v_row public.website_enquiries%ROWTYPE;
  v_from text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Sign in to review website enquiries' USING ERRCODE = '42501';
  END IF;
  IF p_enquiry_id IS NULL OR p_expected_version IS NULL THEN
    RAISE EXCEPTION 'Choose an enquiry to update' USING ERRCODE = '22023';
  END IF;
  IF v_status NOT IN ('contacted', 'converted', 'closed', 'spam') THEN
    RAISE EXCEPTION 'Choose contacted, converted, closed or spam' USING ERRCODE = '22023';
  END IF;
  IF v_note IS NOT NULL AND char_length(v_note) > 2000 THEN
    RAISE EXCEPTION 'Keep the note under 2000 characters' USING ERRCODE = '22023';
  END IF;

  SELECT e.provider_organization_id INTO v_provider
    FROM public.website_enquiries e
   WHERE e.id = p_enquiry_id;
  IF v_provider IS NULL OR NOT (public.is_grand_master() OR public.is_admin_for_org(v_provider)) THEN
    RAISE EXCEPTION 'Website enquiry not found, or you do not have access to it' USING ERRCODE = '42501';
  END IF;

  SELECT e.* INTO v_row
    FROM public.website_enquiries e
   WHERE e.id = p_enquiry_id
   FOR UPDATE;

  IF v_row.version <> p_expected_version THEN
    RAISE EXCEPTION 'This enquiry was changed by someone else. Reload and try again.' USING ERRCODE = 'PT409';
  END IF;

  v_from := v_row.status;
  IF v_from = v_status THEN
    RAISE EXCEPTION 'This enquiry is already marked %', v_status USING ERRCODE = '22023';
  END IF;
  IF v_from = 'converted' THEN
    RAISE EXCEPTION 'A converted enquiry is final. Continue the work in Client Portfolio.' USING ERRCODE = '22023';
  END IF;
  IF v_from IN ('closed', 'spam') AND v_status <> 'contacted' THEN
    RAISE EXCEPTION 'Reopen a closed or spam enquiry as contacted first' USING ERRCODE = '22023';
  END IF;
  IF (v_status IN ('converted', 'closed', 'spam') OR v_from IN ('closed', 'spam'))
     AND (v_note IS NULL OR char_length(v_note) < 3) THEN
    RAISE EXCEPTION 'Add a short note saying why' USING ERRCODE = '22023';
  END IF;

  UPDATE public.website_enquiries e
     SET status = v_status,
         status_note = v_note,
         handled_by = v_uid,
         handled_at = clock_timestamp(),
         version = e.version + 1,
         updated_at = clock_timestamp()
   WHERE e.id = v_row.id
  RETURNING e.* INTO v_row;

  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_row.provider_organization_id, v_uid, 'website_enquiry_reviewed', 'website_enquiries', v_row.id,
    jsonb_strip_nulls(jsonb_build_object(
      'reference', v_row.reference,
      'from_status', v_from,
      'to_status', v_row.status,
      'note', v_note,
      'version', v_row.version
    )));

  RETURN jsonb_build_object(
    'id', v_row.id,
    'reference', v_row.reference,
    'status', v_row.status,
    'status_note', v_row.status_note,
    'version', v_row.version,
    'handled_by', v_row.handled_by,
    'handled_at', v_row.handled_at
  );
END;
$function$;
COMMENT ON FUNCTION "public"."review_website_enquiry"(p_enquiry_id uuid, p_status text, p_note text, p_expected_version integer) IS 'R&M admin review of a website enquiry. Requires grand master or admin reach over the provider organisation, the current row version (PT409 when stale) and a note for converted/closed/spam or a reopen. Writes audit_log action website_enquiry_reviewed.';
REVOKE ALL ON FUNCTION "public"."review_website_enquiry"(p_enquiry_id uuid, p_status text, p_note text, p_expected_version integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."review_website_enquiry"(p_enquiry_id uuid, p_status text, p_note text, p_expected_version integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."review_website_enquiry"(p_enquiry_id uuid, p_status text, p_note text, p_expected_version integer) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."review_website_enquiry"(p_enquiry_id uuid, p_status text, p_note text, p_expected_version integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."rls_auto_enable"()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."rls_auto_enable"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."rls_auto_enable"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."rls_auto_enable"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."rls_auto_enable"() TO "anon";
GRANT EXECUTE ON FUNCTION "public"."rls_auto_enable"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."rls_auto_enable"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."rollback_bob_roster_fill_plan"(p_action_id uuid)
 RETURNS TABLE(plan_id uuid, assignments_rolled_back integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
declare
  v_action public.bob_agentic_actions%rowtype;
  v_plan public.bob_roster_plans%rowtype;
  v_item public.bob_roster_plan_slots%rowtype;
  v_slot public.roster_slots%rowtype;
  v_count integer := 0;
begin
  select a.* into v_action from public.bob_agentic_actions a where a.id = p_action_id for update;
  if not found then raise exception 'Bob action not found'; end if;
  if v_action.action_type <> 'rollback_bob_roster_plan' or v_action.status <> 'approved' then
    raise exception 'Only approved rollback_bob_roster_plan actions can be executed';
  end if;

  select p.* into v_plan from public.bob_roster_plans p
  where p.id = (coalesce(v_action.amended_payload, v_action.proposed_payload)->>'plan_id')::uuid
    and p.organization_id = v_action.organization_id
  for update;
  if not found then raise exception 'Bob roster plan not found'; end if;
  if v_plan.status <> 'applied' then raise exception 'Bob roster plan is already rolled back'; end if;

  for v_item in select * from public.bob_roster_plan_slots where plan_id = v_plan.id and rolled_back_at is null loop
    select s.* into v_slot from public.roster_slots s where s.id = v_item.roster_slot_id for update;
    if not found or v_slot.status <> 'draft' or v_slot.staff_id is distinct from v_item.staff_id then
      raise exception 'Roster slot % was edited or published after plan application; it cannot be rolled back automatically', v_item.roster_slot_id;
    end if;
    update public.roster_slots set staff_id = null where id = v_slot.id;
    update public.bob_roster_plan_slots set rolled_back_at = now() where id = v_item.id;
    v_count := v_count + 1;
  end loop;

  update public.bob_roster_plans
  set status = 'rolled_back', rolled_back_at = now(), rolled_back_by = v_action.approved_by,
      rollback_reason = nullif(trim(coalesce(coalesce(v_action.amended_payload, v_action.proposed_payload)->>'reason', '')), '')
  where id = v_plan.id;

  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (v_action.organization_id, v_action.approved_by, 'bob_roster_plan_rolled_back', 'bob_roster_plans', v_plan.id,
    jsonb_build_object('action_id', v_action.id, 'assignments_rolled_back', v_count));

  return query select v_plan.id, v_count;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."rollback_bob_roster_fill_plan"(p_action_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."rollback_bob_roster_fill_plan"(p_action_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."rollback_bob_roster_fill_plan"(p_action_id uuid) TO "service_role";

