CREATE OR REPLACE FUNCTION "public"."roster_assignment_load"(p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_exclude_slot_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(rest_hours numeric, week_start date, week_hours numeric, consecutive_days integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_week_start date := date_trunc('week', p_scheduled_start at time zone 'Pacific/Auckland')::date;
  v_week_from timestamptz := (v_week_start::timestamp) at time zone 'Pacific/Auckland';
  v_week_to timestamptz := ((v_week_start + 7)::timestamp) at time zone 'Pacific/Auckland';
  v_shift_date date := (p_scheduled_start at time zone 'Pacific/Auckland')::date;
  v_rest numeric;
  v_hours numeric;
  v_days integer := 1;
  v_day date;
begin
  -- Rest: the smallest gap to any other slot of this officer that does not overlap the new one.
  select min(case when s.scheduled_start >= p_scheduled_end then extract(epoch from (s.scheduled_start - p_scheduled_end)) / 3600.0
                  else extract(epoch from (p_scheduled_start - s.scheduled_end)) / 3600.0 end)
  into v_rest
  from public.roster_slots s
  where s.staff_id = p_staff_id
    and s.status not in ('declined', 'cancelled')
    and (p_exclude_slot_id is null or s.id <> p_exclude_slot_id)
    and not tstzrange(s.scheduled_start, s.scheduled_end, '[)') && tstzrange(p_scheduled_start, p_scheduled_end, '[)');

  -- Hours this roster week (Monday to Sunday, NZ time) including the new slot.
  select coalesce(sum(extract(epoch from (s.scheduled_end - s.scheduled_start)) / 3600.0), 0)
  into v_hours
  from public.roster_slots s
  where s.staff_id = p_staff_id
    and s.status not in ('declined', 'cancelled')
    and (p_exclude_slot_id is null or s.id <> p_exclude_slot_id)
    and s.scheduled_start >= v_week_from and s.scheduled_start < v_week_to
    and not tstzrange(s.scheduled_start, s.scheduled_end, '[)') && tstzrange(p_scheduled_start, p_scheduled_end, '[)');
  v_hours := v_hours + extract(epoch from (p_scheduled_end - p_scheduled_start)) / 3600.0;

  -- Days in a row ending on the new slot's day: walk back while the previous day has a slot.
  v_day := v_shift_date - 1;
  while v_days < 60 and exists (
    select 1 from public.roster_slots s
    where s.staff_id = p_staff_id
      and s.status not in ('declined', 'cancelled')
      and (p_exclude_slot_id is null or s.id <> p_exclude_slot_id)
      and (s.scheduled_start at time zone 'Pacific/Auckland')::date = v_day
  ) loop
    v_days := v_days + 1;
    v_day := v_day - 1;
  end loop;

  return query select round(v_rest, 1), v_week_start, round(v_hours, 1), v_days;
end;
$function$;
COMMENT ON FUNCTION "public"."roster_assignment_load"(p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_exclude_slot_id uuid) IS 'Internal: rest since/until the nearest other slot, hours in the Mon-Sun (NZ) roster week including the proposed slot, and days in a row ending on its day. Used by staff_fatigue_conflict and preview_roster_assignment.';
REVOKE ALL ON FUNCTION "public"."roster_assignment_load"(p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_exclude_slot_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."roster_assignment_load"(p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_exclude_slot_id uuid) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."roster_place_geofence_state"(p_site_id uuid, p_zone_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_has_boundary boolean;v_verified boolean;
begin
  select case when p_site_id is not null then exists(select 1 from public.client_sites s where s.id=p_site_id and s.boundary is not null) else exists(select 1 from public.location_zones z where z.id=p_zone_id and z.boundary is not null) end into v_has_boundary;
  if not v_has_boundary then return 'missing';end if;
  select coalesce((select h.verification_state='verified' from public.geofence_boundary_history h where h.entity_type=case when p_site_id is not null then 'client_site' else 'location_zone' end and h.entity_id=coalesce(p_site_id,p_zone_id) order by h.created_at desc limit 1),false) into v_verified;
  return case when v_verified then 'verified' else 'mapped_unverified' end;
end;$function$;
REVOKE ALL ON FUNCTION "public"."roster_place_geofence_state"(p_site_id uuid, p_zone_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."roster_place_geofence_state"(p_site_id uuid, p_zone_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."roster_place_geofence_state"(p_site_id uuid, p_zone_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."roster_slot_is_source_truth"(p_external_refs jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select coalesce(p_external_refs->>'source', '') = any (array['rm_patrol_log_labour']);
$function$;
COMMENT ON FUNCTION "public"."roster_slot_is_source_truth"(p_external_refs jsonb) IS 'True when a roster slot was seeded from an owner-verified source of record (R&M spreadsheets). Such slots need no geofence and are billed by their source.';
REVOKE ALL ON FUNCTION "public"."roster_slot_is_source_truth"(p_external_refs jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."roster_slot_is_source_truth"(p_external_refs jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."roster_slot_is_source_truth"(p_external_refs jsonb) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."roster_slot_is_source_truth"(p_external_refs jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."route_historical_patrol_labour"(p_organization_id uuid, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_moved integer := 0;
  v_zones_added integer := 0;
  v_units_closed integer := 0;
  v_units_reopened integer := 0;
  v_summary jsonb;
begin
  -- One routing run per organisation at a time; the audited wrapper takes the same lock first.
  perform pg_advisory_xact_lock(hashtextextended('historical_patrol_labour_routing:' || p_organization_id::text, 0));
  drop table if exists pg_temp._hpl_routes, pg_temp._hpl_events, pg_temp._hpl_attendance,
    pg_temp._hpl_places, pg_temp._hpl_centres, pg_temp._hpl_decisions;

  create temp table _hpl_routes on commit drop as
  select route.id as route_id, route.route_code, route.primary_staff_id,
    (select unit.id from public.roster_work_units unit
      where unit.organization_id = p_organization_id and unit.patrol_route_id = route.id
        and unit.active and unit.work_unit_type = 'patrol'
        and coalesce((unit.external_refs->>'historical_only')::boolean, false) = false
      order by unit.created_at, unit.id limit 1) as unit_id
  from public.patrol_routes route
  where route.organization_id = p_organization_id and route.primary_staff_id is not null;
  delete from _hpl_routes where unit_id is null;
  if not exists (select 1 from _hpl_routes) then
    -- Nothing can be routed, so every holding unit that still has labour must stay visible.
    update public.roster_work_units unit set active = true, updated_at = now()
    where unit.organization_id = p_organization_id and not unit.active
      and unit.external_refs->>'source' = 'rm_patrol_log_labour'
      and exists (select 1 from public.roster_slots slot where slot.work_unit_id = unit.id);
    get diagnostics v_units_reopened = row_count;
    return jsonb_build_object('routes', 0, 'moved', 0, 'unrouted', null, 'holding_units_reopened', v_units_reopened,
      'skipped_reason', 'No patrol route has both a primary officer and an active patrol work unit');
  end if;

  -- Place evidence from both supported source kinds: patrol-log events and observations.
  create temp table _hpl_events on commit drop as
  with refs as (
    select slot.id as slot_id, slot.staff_id, ref.value
    from public.roster_slots slot
    cross join lateral jsonb_array_elements_text(slot.external_refs->'source_records') ref(value)
    where slot.organization_id = p_organization_id
      and slot.external_refs->>'source' = 'rm_patrol_log_labour'
  ), places as (
    select refs.slot_id, refs.staff_id, event.zone_id, event.client_site_id as site_id
    from refs join public.location_events event
      on event.id = case when refs.value ~ '^event:[0-9a-f-]{36}$' then substr(refs.value, 7)::uuid end
    union all
    select refs.slot_id, refs.staff_id, observation.zone_id, observation.site_id
    from refs join public.observations observation
      on observation.id = case when refs.value ~ '^observation:[0-9a-f-]{36}$' then substr(refs.value, 13)::uuid end
  )
  select slot_id, staff_id, zone_id, coalesce(zone_id::text, 'site:' || site_id::text) as place
  from places
  where coalesce(zone_id, site_id) is not null;

  create temp table _hpl_attendance on commit drop as
  select ev.place, route.route_id, count(*) as visits
  from _hpl_events ev join _hpl_routes route on route.primary_staff_id = ev.staff_id
  group by 1, 2;

  create temp table _hpl_places on commit drop as
  select place, (array_agg(zone_id))[1] as zone_id, null::uuid as route_id, null::text as basis
  from _hpl_events group by place;

  -- a. The place is mostly attended by one route's primary officer.
  with ranked as (
    select place, route_id, rank() over (partition by place order by visits desc) as rk,
      count(*) over (partition by place, visits) as ties
    from _hpl_attendance
  )
  update _hpl_places p set route_id = ranked.route_id, basis = 'site_primary_officer'
  from ranked where ranked.place = p.place and ranked.rk = 1 and ranked.ties = 1;

  -- b. Nearest route working area, weighted by the primary officer's attendance.
  create temp table _hpl_centres on commit drop as
  select p.route_id,
    st_setsrid(st_makepoint(sum(st_x(geo.pt) * att.visits) / sum(att.visits),
                            sum(st_y(geo.pt) * att.visits) / sum(att.visits)), 4326) as centre
  from _hpl_places p
  join _hpl_attendance att on att.place = p.place and att.route_id = p.route_id
  join lateral (
    select st_transform(coalesce(zone.center_point, st_centroid(zone.boundary)), 4326) as pt
    from public.location_zones zone where zone.id = p.zone_id
  ) geo on geo.pt is not null
  where p.basis = 'site_primary_officer'
  group by p.route_id;

  update _hpl_places p set route_id = (
      select centre.route_id from _hpl_centres centre
      order by st_distance(centre.centre::geography, geo.pt::geography) limit 1),
    basis = 'site_nearest_route_area'
  from (
    select zone.id, st_transform(coalesce(zone.center_point, st_centroid(zone.boundary)), 4326) as pt
    from public.location_zones zone
  ) geo
  where p.route_id is null and geo.id = p.zone_id and geo.pt is not null
    and exists (select 1 from _hpl_centres);

  -- c. The zone already sits on exactly one candidate route's zone list.
  update _hpl_places p set route_id = listed.route_id, basis = 'site_route_zone_list'
  from (
    select route_zone.zone_id, (array_agg(route_zone.patrol_route_id))[1] as route_id
    from public.patrol_route_zones route_zone
    where route_zone.patrol_route_id in (select route_id from _hpl_routes)
    group by route_zone.zone_id having count(*) = 1
  ) listed
  where p.route_id is null and listed.zone_id = p.zone_id;

  create temp table _hpl_decisions on commit drop as
  with pending as (
    select slot.id as slot_id, slot.staff_id, staff.user_id, slot.work_unit_id, slot.external_refs,
      (slot.external_refs->>'work_date')::date as work_date
    from public.roster_slots slot
    join public.staff_profiles staff on staff.id = slot.staff_id
    where slot.organization_id = p_organization_id
      and slot.external_refs->>'source' = 'rm_patrol_log_labour'
      and slot.work_unit_id not in (select unit_id from _hpl_routes)
  ), votes as (
    -- Distinct places decide; entry volume only breaks a tie between routes.
    select ev.slot_id, p.route_id, count(distinct ev.place) as n, count(*) as entries
    from _hpl_events ev join _hpl_places p on p.place = ev.place
    where p.route_id is not null and ev.slot_id in (select slot_id from pending)
    group by 1, 2
  ), best as (
    select slot_id, route_id, rank() over (partition by slot_id order by n desc, entries desc) as rk,
      count(*) over (partition by slot_id, n, entries) as ties
    from votes
  )
  select pending.*,
    best.route_id as place_route_id,
    (select (array_agg(distinct assignment.patrol_route_id))[1]
       from public.roster_assignments assignment
      where assignment.organization_id = p_organization_id
        and assignment.officer_id = pending.user_id
        and assignment.specific_date = pending.work_date
        and assignment.patrol_route_id in (select route_id from _hpl_routes)
      having count(distinct assignment.patrol_route_id) = 1) as assignment_route_id,
    null::uuid as route_id,
    null::text as basis
  from pending
  left join best on best.slot_id = pending.slot_id and best.rk = 1 and best.ties = 1;

  update _hpl_decisions set route_id = place_route_id, basis = 'site' where place_route_id is not null;
  update _hpl_decisions set route_id = assignment_route_id, basis = 'dated_route_assignment'
  where route_id is null and assignment_route_id is not null;

  with history as (
    select slot.staff_id, route.route_id, count(*) as n
    from public.roster_slots slot join _hpl_routes route on route.unit_id = slot.work_unit_id
    where slot.organization_id = p_organization_id and slot.external_refs->>'source' = 'rm_patrol_log_labour'
    group by 1, 2
    union all
    select staff_id, route_id, count(*) from _hpl_decisions where route_id is not null group by 1, 2
  ), totals as (
    select staff_id, route_id, sum(n) as n from history group by 1, 2
  ), best as (
    select staff_id, route_id, rank() over (partition by staff_id order by n desc) as rk,
      count(*) over (partition by staff_id, n) as ties
    from totals
  )
  update _hpl_decisions d set route_id = best.route_id, basis = 'officer_usual_route'
  from best where d.route_id is null and best.staff_id = d.staff_id and best.rk = 1 and best.ties = 1;

  update public.roster_slots slot
  set work_unit_id = route.unit_id,
      external_refs = slot.external_refs || jsonb_build_object(
        'route_code', route.route_code,
        'route_basis', d.basis,
        'routed_from_work_unit_id', d.work_unit_id,
        'routed_request_id', p_request_id,
        'client_name', client.name)
  from _hpl_decisions d
  join _hpl_routes route on route.route_id = d.route_id
  left join public.organizations client on client.id = (d.external_refs->>'client_organization_id')::uuid
  where slot.id = d.slot_id;
  get diagnostics v_moved = row_count;

  -- Record the routed zones on their route so each officer's places are visible on the route.
  insert into public.patrol_route_zones(patrol_route_id, zone_id, notes)
  select p.route_id, p.zone_id, 'Primary officer coverage: routed from patrol-log attendance (' || p.basis || ').'
  from _hpl_places p
  where p.route_id is not null and p.zone_id is not null
    and not exists (select 1 from public.patrol_route_zones existing where existing.patrol_route_id = p.route_id and existing.zone_id = p.zone_id)
    and (
      exists (select 1 from public.location_zones zone where zone.id = p.zone_id and zone.organization_id = p_organization_id)
      or exists (
        select 1 from public.service_agreement_locations sal
        join public.service_agreements agreement on agreement.id = sal.service_agreement_id
        where sal.status = 'active' and sal.zone_id = p.zone_id and agreement.provider_organization_id = p_organization_id)
    )
  on conflict do nothing;
  get diagnostics v_zones_added = row_count;

  -- Holding units are visible exactly while they hold labour (a later import may reuse a closed one).
  update public.roster_work_units unit set active = false, updated_at = now()
  where unit.organization_id = p_organization_id and unit.active
    and unit.external_refs->>'source' = 'rm_patrol_log_labour'
    and not exists (select 1 from public.roster_slots slot where slot.work_unit_id = unit.id);
  get diagnostics v_units_closed = row_count;
  update public.roster_work_units unit set active = true, updated_at = now()
  where unit.organization_id = p_organization_id and not unit.active
    and unit.external_refs->>'source' = 'rm_patrol_log_labour'
    and exists (select 1 from public.roster_slots slot where slot.work_unit_id = unit.id);
  get diagnostics v_units_reopened = row_count;

  select jsonb_build_object(
    'request_id', p_request_id,
    'routes', (select jsonb_object_agg(route_code, jsonb_build_object('route_id', route_id, 'unit_id', unit_id, 'primary_staff_id', primary_staff_id)) from _hpl_routes),
    'moved', v_moved,
    'unrouted', (select count(*) from _hpl_decisions where route_id is null),
    'by_route', coalesce((select jsonb_object_agg(route_code, n) from (
        select route.route_code, count(*) as n from _hpl_decisions d join _hpl_routes route using (route_id) group by 1) x), '{}'::jsonb),
    'by_basis', coalesce((select jsonb_object_agg(coalesce(basis, 'unrouted'), n) from (
        select basis, count(*) as n from _hpl_decisions group by 1) x), '{}'::jsonb),
    'place_basis', coalesce((select jsonb_object_agg(coalesce(basis, 'unresolved'), n) from (
        select basis, count(*) as n from _hpl_places group by 1) x), '{}'::jsonb),
    'route_zones_added', v_zones_added,
    'holding_units_closed', v_units_closed,
    'holding_units_reopened', v_units_reopened)
  into v_summary;
  return v_summary;
end;
$function$;
COMMENT ON FUNCTION "public"."route_historical_patrol_labour"(p_organization_id uuid, p_request_id uuid) IS 'Internal: moves unrouted historical patrol-log labour onto the patrol route of each place''s primary officer, using event and observation place evidence and a distinct-place majority. Serialised per organisation. Called by audited RPCs only.';
REVOKE ALL ON FUNCTION "public"."route_historical_patrol_labour"(p_organization_id uuid, p_request_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."route_historical_patrol_labour"(p_organization_id uuid, p_request_id uuid) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safe_healthcheck"()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'ok', true,
    'uid', (select auth.uid()),
    'ts', now()
  );
$function$;
REVOKE ALL ON FUNCTION "public"."safe_healthcheck"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."safe_healthcheck"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."safe_healthcheck"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."safe_healthcheck"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."save_bob_document_revision"(p_document_id uuid, p_supersedes_version_id uuid, p_title text, p_document_type text, p_authored_html text, p_authored_text text, p_reference_handles jsonb DEFAULT '[]'::jsonb, p_reference_metadata jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org_id uuid;
  v_next_label text;
  v_version_id uuid;
  v_title text := nullif(trim(coalesce(p_title, '')), '');
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF v_title IS NULL THEN RAISE EXCEPTION 'Document title is required'; END IF;
  IF nullif(trim(coalesce(p_authored_text, '')), '') IS NULL THEN RAISE EXCEPTION 'Document content is required'; END IF;
  IF jsonb_typeof(coalesce(p_reference_handles, '[]'::jsonb)) <> 'array' THEN RAISE EXCEPTION 'Reference handles must be an array'; END IF;

  SELECT d.organization_id INTO v_org_id
  FROM public.documents d
  JOIN public.document_versions dv ON dv.document_id = d.id
  WHERE d.id = p_document_id AND dv.id = p_supersedes_version_id
  FOR UPDATE;
  IF v_org_id IS NULL THEN RAISE EXCEPTION 'Document version not found'; END IF;
  IF NOT public.is_admin_for_org(v_org_id) AND NOT public.is_grand_master() THEN
    RAISE EXCEPTION 'Document revision requires an administrator';
  END IF;

  SELECT 'v' || (count(*) + 1)::text INTO v_next_label
  FROM public.document_versions
  WHERE document_id = p_document_id;

  INSERT INTO public.document_versions (
    document_id, version_label, supersedes_version_id, extracted_text, metadata_json
  ) VALUES (
    p_document_id, v_next_label, p_supersedes_version_id, p_authored_text,
    jsonb_build_object(
      'authoring_html', coalesce(p_authored_html, ''),
      'content_format', 'html',
      'title', v_title,
      'document_type', nullif(trim(coalesce(p_document_type, '')), ''),
      'authoring_status', 'draft',
      'authored_by', v_actor,
      'reference_handles', coalesce(p_reference_handles, '[]'::jsonb),
      'references', coalesce(p_reference_metadata, '[]'::jsonb),
      'revision_reason', 'Authoring revision created from the previous version.'
    )
  ) RETURNING id INTO v_version_id;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (
    v_org_id, v_actor, 'bob_document_revision_created', 'document_versions', v_version_id,
    jsonb_build_object('document_id', p_document_id, 'supersedes_version_id', p_supersedes_version_id, 'version_label', v_next_label)
  );

  RETURN jsonb_build_object('ok', true, 'document_id', p_document_id, 'document_version_id', v_version_id, 'version_label', v_next_label, 'status', 'draft');
END;
$function$;
REVOKE ALL ON FUNCTION "public"."save_bob_document_revision"(p_document_id uuid, p_supersedes_version_id uuid, p_title text, p_document_type text, p_authored_html text, p_authored_text text, p_reference_handles jsonb, p_reference_metadata jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."save_bob_document_revision"(p_document_id uuid, p_supersedes_version_id uuid, p_title text, p_document_type text, p_authored_html text, p_authored_text text, p_reference_handles jsonb, p_reference_metadata jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."save_bob_document_revision"(p_document_id uuid, p_supersedes_version_id uuid, p_title text, p_document_type text, p_authored_html text, p_authored_text text, p_reference_handles jsonb, p_reference_metadata jsonb) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."save_bob_document_revision"(p_document_id uuid, p_supersedes_version_id uuid, p_title text, p_document_type text, p_authored_html text, p_authored_text text, p_reference_handles jsonb, p_reference_metadata jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."save_discovered_org_as_client"(p_client_request_id uuid, p_source_organization_id uuid)
 RETURNS organizations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_provider uuid;
  v_source public.organizations%rowtype;
  v_client public.organizations%rowtype;
BEGIN
  SELECT organization_id INTO v_provider
  FROM public.user_profiles
  WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_provider IS NULL OR NOT public.is_admin_for_org(v_provider) THEN
    RAISE EXCEPTION 'Active CRM administrator required';
  END IF;
  IF p_client_request_id IS NULL THEN RAISE EXCEPTION 'client_request_id is required'; END IF;

  SELECT * INTO v_source FROM public.organizations WHERE id = p_source_organization_id;
  IF NOT FOUND OR v_source.id = v_provider THEN RAISE EXCEPTION 'A valid external organization is required'; END IF;
  IF NOT v_source.active OR v_source.status <> 'active' THEN RAISE EXCEPTION 'Only an active discovered organization can be saved as a client'; END IF;

  SELECT * INTO v_client
  FROM public.organizations
  WHERE parent_organization_id = v_provider
    AND (client_request_id = p_client_request_id OR external_refs->>'canonical_organization_id' = v_source.id::text);
  IF FOUND THEN RETURN v_client; END IF;

  INSERT INTO public.organizations(
    name, organization_type, parent_organization_id, active, status, nzbn,
    company_registration_number, contact_email, contact_phone, billing_email,
    billing_address, account_notes, external_refs, client_request_id
  ) VALUES (
    v_source.name, 'client', v_provider, false, 'prospect', v_source.nzbn,
    v_source.company_registration_number, v_source.contact_email, v_source.contact_phone,
    v_source.billing_email, v_source.billing_address, v_source.account_notes,
    jsonb_build_object('canonical_organization_id', v_source.id, 'source_status', v_source.status),
    p_client_request_id
  ) RETURNING * INTO v_client;

  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (
    v_provider, v_actor, 'crm_discovered_organization_saved_as_client', 'organizations', v_client.id,
    jsonb_build_object('canonical_organization_id', v_source.id, 'client_account_id', v_client.id)
  );
  RETURN v_client;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."save_discovered_org_as_client"(p_client_request_id uuid, p_source_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."save_discovered_org_as_client"(p_client_request_id uuid, p_source_organization_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."save_discovered_org_as_client"(p_client_request_id uuid, p_source_organization_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."save_discovered_org_as_client"(p_client_request_id uuid, p_source_organization_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."save_finance_tax_identity"(p_ird_number text, p_gst_registered boolean, p_gst_basis text, p_gst_filing_frequency text, p_tax_agent_name text DEFAULT NULL::text, p_tax_agent_contact text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_actor uuid := auth.uid(); v_org uuid; v_ird text; v_status text;
BEGIN
  SELECT organization_id INTO v_org FROM public.user_profiles WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_org IS NULL OR NOT public.is_admin_for_org(v_org) THEN RAISE EXCEPTION 'Active finance administrator required'; END IF;
  v_ird := regexp_replace(COALESCE(p_ird_number, ''), '[^0-9]', '', 'g');
  IF length(v_ird) NOT BETWEEN 8 AND 9 THEN RAISE EXCEPTION 'Enter the organisation IRD number as 8 or 9 digits'; END IF;
  IF p_gst_registered AND p_gst_basis NOT IN ('payments','invoice','hybrid') THEN RAISE EXCEPTION 'Choose the GST accounting basis'; END IF;
  IF p_gst_registered AND p_gst_filing_frequency NOT IN ('monthly','two_monthly','six_monthly') THEN RAISE EXCEPTION 'Choose the GST filing frequency'; END IF;
  v_status := CASE WHEN nullif(trim(COALESCE(p_tax_agent_name, '')), '') IS NULL THEN 'owner_review' ELSE 'accountant_review' END;
  INSERT INTO public.finance_tax_identity(organization_id, ird_number, gst_registered, gst_basis, gst_filing_frequency, tax_agent_name, tax_agent_contact, setup_status, created_by, updated_by)
  VALUES (v_org, v_ird, p_gst_registered, CASE WHEN p_gst_registered THEN p_gst_basis ELSE 'not_registered' END, CASE WHEN p_gst_registered THEN p_gst_filing_frequency ELSE 'not_registered' END, nullif(trim(p_tax_agent_name), ''), nullif(trim(p_tax_agent_contact), ''), v_status, v_actor, v_actor)
  ON CONFLICT (organization_id) DO UPDATE SET ird_number = EXCLUDED.ird_number, gst_registered = EXCLUDED.gst_registered, gst_basis = EXCLUDED.gst_basis, gst_filing_frequency = EXCLUDED.gst_filing_frequency, tax_agent_name = EXCLUDED.tax_agent_name, tax_agent_contact = EXCLUDED.tax_agent_contact, setup_status = EXCLUDED.setup_status, updated_by = v_actor, updated_at = now();
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata) VALUES (v_org, v_actor, 'finance_tax_identity_saved', 'finance_tax_identity', v_org, jsonb_build_object('ird_last_four', right(v_ird, 4), 'gst_registered', p_gst_registered, 'setup_status', v_status));
  RETURN jsonb_build_object('ird_last_four', right(v_ird, 4), 'gst_registered', p_gst_registered, 'gst_basis', CASE WHEN p_gst_registered THEN p_gst_basis ELSE 'not_registered' END, 'gst_filing_frequency', CASE WHEN p_gst_registered THEN p_gst_filing_frequency ELSE 'not_registered' END, 'setup_status', v_status);
END;
$function$;
REVOKE ALL ON FUNCTION "public"."save_finance_tax_identity"(p_ird_number text, p_gst_registered boolean, p_gst_basis text, p_gst_filing_frequency text, p_tax_agent_name text, p_tax_agent_contact text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."save_finance_tax_identity"(p_ird_number text, p_gst_registered boolean, p_gst_basis text, p_gst_filing_frequency text, p_tax_agent_name text, p_tax_agent_contact text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."save_finance_tax_identity"(p_ird_number text, p_gst_registered boolean, p_gst_basis text, p_gst_filing_frequency text, p_tax_agent_name text, p_tax_agent_contact text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."save_finance_tax_identity"(p_ird_number text, p_gst_registered boolean, p_gst_basis text, p_gst_filing_frequency text, p_tax_agent_name text, p_tax_agent_contact text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."save_organization_compliance_record"(p_client_request_id uuid, p_organization_id uuid, p_record_id uuid, p_expected_updated_at timestamp with time zone, p_record_type text, p_name text, p_reference_number text, p_issuer text, p_effective_date date, p_expiry_date date, p_coverage_amount numeric, p_currency text, p_evidence_document_id uuid, p_source_name text, p_source_as_of date, p_source_notes text, p_replaces_record_id uuid)
 RETURNS organization_compliance_records
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_record public.organization_compliance_records%rowtype;
  v_replaced public.organization_compliance_records%rowtype;
BEGIN
  IF v_actor IS NULL OR NOT public.is_admin_for_org(p_organization_id) OR NOT EXISTS (
    SELECT 1
    FROM public.user_profiles actor
    WHERE actor.id = v_actor
      AND actor.deactivated_at IS NULL
      AND actor.role IN ('grand_master', 'master')
  ) THEN
    RAISE EXCEPTION 'Active organization master required';
  END IF;
  IF p_record_type NOT IN (
    'company_licence',
    'insurance',
    'policy',
    'prequalification',
    'registration',
    'certification',
    'other'
  ) THEN
    RAISE EXCEPTION 'Unsupported compliance record type';
  END IF;
  IF length(trim(coalesce(p_name, ''))) < 2 THEN
    RAISE EXCEPTION 'Compliance record name is required';
  END IF;
  IF length(trim(coalesce(p_source_name, ''))) < 2 OR p_source_as_of IS NULL THEN
    RAISE EXCEPTION 'Source name and source date are required';
  END IF;
  IF p_effective_date IS NOT NULL AND p_expiry_date IS NOT NULL AND p_expiry_date < p_effective_date THEN
    RAISE EXCEPTION 'Expiry date cannot precede effective date';
  END IF;
  IF p_coverage_amount IS NOT NULL AND p_coverage_amount < 0 THEN
    RAISE EXCEPTION 'Coverage amount cannot be negative';
  END IF;

  IF p_record_id IS NULL THEN
    IF p_client_request_id IS NULL THEN
      RAISE EXCEPTION 'Client request ID is required';
    END IF;

    SELECT *
    INTO v_record
    FROM public.organization_compliance_records
    WHERE organization_id = p_organization_id
      AND client_request_id = p_client_request_id;

    IF FOUND THEN
      RETURN v_record;
    END IF;

    IF p_replaces_record_id IS NOT NULL THEN
      SELECT *
      INTO v_replaced
      FROM public.organization_compliance_records
      WHERE id = p_replaces_record_id
        AND organization_id = p_organization_id
        AND status = 'current'
      FOR UPDATE;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'Current record to replace was not found';
      END IF;
    END IF;

    INSERT INTO public.organization_compliance_records (
      organization_id,
      record_type,
      name,
      reference_number,
      issuer,
      effective_date,
      expiry_date,
      coverage_amount,
      currency,
      evidence_document_id,
      source_name,
      source_as_of,
      source_notes,
      replaces_record_id,
      client_request_id,
      created_by,
      updated_by
    )
    VALUES (
      p_organization_id,
      p_record_type,
      trim(p_name),
      nullif(trim(coalesce(p_reference_number, '')), ''),
      nullif(trim(coalesce(p_issuer, '')), ''),
      p_effective_date,
      p_expiry_date,
      p_coverage_amount,
      upper(coalesce(nullif(trim(p_currency), ''), 'NZD')),
      p_evidence_document_id,
      trim(p_source_name),
      p_source_as_of,
      nullif(trim(coalesce(p_source_notes, '')), ''),
      p_replaces_record_id,
      p_client_request_id,
      v_actor,
      v_actor
    )
    RETURNING * INTO v_record;

    IF p_replaces_record_id IS NOT NULL THEN
      UPDATE public.organization_compliance_records
      SET status = 'superseded', updated_by = v_actor, updated_at = clock_timestamp()
      WHERE id = p_replaces_record_id;
    END IF;
  ELSE
    SELECT *
    INTO v_record
    FROM public.organization_compliance_records
    WHERE id = p_record_id
      AND organization_id = p_organization_id
      AND status = 'current'
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Current compliance record not found';
    END IF;
    IF v_record.updated_at <> p_expected_updated_at THEN
      RAISE EXCEPTION 'Compliance record changed since it was opened';
    END IF;

    UPDATE public.organization_compliance_records
    SET
      record_type = p_record_type,
      name = trim(p_name),
      reference_number = nullif(trim(coalesce(p_reference_number, '')), ''),
      issuer = nullif(trim(coalesce(p_issuer, '')), ''),
      effective_date = p_effective_date,
      expiry_date = p_expiry_date,
      coverage_amount = p_coverage_amount,
      currency = upper(coalesce(nullif(trim(p_currency), ''), 'NZD')),
      evidence_document_id = p_evidence_document_id,
      source_name = trim(p_source_name),
      source_as_of = p_source_as_of,
      source_notes = nullif(trim(coalesce(p_source_notes, '')), ''),
      verification_status = 'unverified',
      verified_by = NULL,
      verified_at = NULL,
      review_notes = NULL,
      updated_by = v_actor,
      updated_at = clock_timestamp()
    WHERE id = v_record.id
    RETURNING * INTO v_record;
  END IF;

  INSERT INTO public.audit_log (
    organization_id,
    actor_user_id,
    action,
    target_table,
    target_id,
    metadata
  )
  VALUES (
    p_organization_id,
    v_actor,
    CASE WHEN p_record_id IS NULL THEN 'organization_compliance_record_created' ELSE 'organization_compliance_record_updated' END,
    'organization_compliance_records',
    v_record.id,
    jsonb_build_object(
      'record_type', v_record.record_type,
      'verification_status', v_record.verification_status,
      'expiry_date', v_record.expiry_date,
      'replaces_record_id', p_replaces_record_id
    )
  );

  RETURN v_record;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."save_organization_compliance_record"(p_client_request_id uuid, p_organization_id uuid, p_record_id uuid, p_expected_updated_at timestamp with time zone, p_record_type text, p_name text, p_reference_number text, p_issuer text, p_effective_date date, p_expiry_date date, p_coverage_amount numeric, p_currency text, p_evidence_document_id uuid, p_source_name text, p_source_as_of date, p_source_notes text, p_replaces_record_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."save_organization_compliance_record"(p_client_request_id uuid, p_organization_id uuid, p_record_id uuid, p_expected_updated_at timestamp with time zone, p_record_type text, p_name text, p_reference_number text, p_issuer text, p_effective_date date, p_expiry_date date, p_coverage_amount numeric, p_currency text, p_evidence_document_id uuid, p_source_name text, p_source_as_of date, p_source_notes text, p_replaces_record_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."save_organization_compliance_record"(p_client_request_id uuid, p_organization_id uuid, p_record_id uuid, p_expected_updated_at timestamp with time zone, p_record_type text, p_name text, p_reference_number text, p_issuer text, p_effective_date date, p_expiry_date date, p_coverage_amount numeric, p_currency text, p_evidence_document_id uuid, p_source_name text, p_source_as_of date, p_source_notes text, p_replaces_record_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."save_organization_compliance_record"(p_client_request_id uuid, p_organization_id uuid, p_record_id uuid, p_expected_updated_at timestamp with time zone, p_record_type text, p_name text, p_reference_number text, p_issuer text, p_effective_date date, p_expiry_date date, p_coverage_amount numeric, p_currency text, p_evidence_document_id uuid, p_source_name text, p_source_as_of date, p_source_notes text, p_replaces_record_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."save_service_client"(p_request_id uuid, p_provider_id uuid, p_client_id uuid, p_expected_updated_at timestamp with time zone, p_name text, p_email text, p_phone text, p_notes text, p_confirm_engagement boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_actor uuid := auth.uid(); v_org public.organizations%rowtype;
  v_agreement public.service_agreements%rowtype; v_request jsonb; v_prior jsonb; v_result jsonb;
BEGIN
  IF v_actor IS NULL OR NOT public.field_place_provider_allowed(p_provider_id)
    OR NOT public.is_admin_for_org(p_provider_id) THEN
    RAISE EXCEPTION 'An active provider administrator is required';
  END IF;
  IF p_request_id IS NULL OR nullif(trim(p_name), '') IS NULL OR char_length(p_name) > 200
    OR char_length(coalesce(p_notes, '')) > 10000 THEN
    RAISE EXCEPTION 'A request ID and client name of up to 200 characters are required';
  END IF;
  IF nullif(trim(coalesce(p_email, '')), '') IS NOT NULL
    AND trim(p_email) !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN
    RAISE EXCEPTION 'Enter a valid contact email or leave it empty';
  END IF;
  v_request := jsonb_build_object('client_id', p_client_id, 'version', p_expected_updated_at,
    'name', trim(p_name), 'email', p_email, 'phone', p_phone, 'notes', p_notes, 'engaged', p_confirm_engagement);
  PERFORM pg_advisory_xact_lock(hashtextextended('service-client:' || p_provider_id || ':' || p_request_id, 0));
  SELECT metadata INTO v_prior FROM public.audit_log
    WHERE organization_id = p_provider_id AND actor_user_id = v_actor AND action = 'service_client_saved'
      AND metadata->>'request_id' = p_request_id::text LIMIT 1;
  IF FOUND THEN
    IF v_prior->'request' IS DISTINCT FROM v_request THEN RAISE EXCEPTION 'Retry contains changed client details'; END IF;
    RETURN v_prior->'result';
  END IF;
  IF p_client_id IS NULL THEN
    IF p_confirm_engagement IS DISTINCT FROM true THEN RAISE EXCEPTION 'Confirm the provider is engaged by this client'; END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended('service-client-name:' || lower(trim(p_name)), 0));
    IF EXISTS (SELECT 1 FROM public.organizations WHERE lower(trim(name)) = lower(trim(p_name))) THEN
      RAISE EXCEPTION 'An organisation with this name already exists. Select its existing record instead of creating a duplicate';
    END IF;
    INSERT INTO public.organizations(name, organization_type, parent_organization_id, active, status,
      contact_email, contact_phone, account_notes, client_request_id)
    VALUES (trim(p_name), 'client', p_provider_id, true, 'active', nullif(trim(p_email), ''),
      nullif(trim(p_phone), ''), nullif(trim(p_notes), ''), p_request_id) RETURNING * INTO v_org;
  ELSE
    IF p_client_id = p_provider_id OR (NOT public.crm_actor_can_manage_account(p_client_id) AND NOT (
      p_confirm_engagement IS TRUE AND EXISTS (
        SELECT 1 FROM public.service_agreements pending
        WHERE pending.provider_organization_id = p_provider_id AND pending.client_organization_id = p_client_id
          AND pending.agreement_type = 'operational' AND pending.invitation_status IN ('not_invited', 'invited')
          AND (pending.starts_on IS NULL OR pending.starts_on <= current_date)
          AND (pending.ends_on IS NULL OR pending.ends_on >= current_date)
      )
    )) THEN
      RAISE EXCEPTION 'Client is outside your managed operational accounts';
    END IF;
    SELECT * INTO v_org FROM public.organizations WHERE id = p_client_id FOR UPDATE;
    IF NOT FOUND OR p_expected_updated_at IS NULL OR v_org.updated_at IS DISTINCT FROM p_expected_updated_at THEN
      RAISE EXCEPTION 'Client changed since it was opened. Reload before saving';
    END IF;
    UPDATE public.organizations SET name = trim(p_name), contact_email = nullif(trim(p_email), ''),
      contact_phone = nullif(trim(p_phone), ''), account_notes = nullif(trim(p_notes), ''), updated_at = clock_timestamp()
      WHERE id = p_client_id RETURNING * INTO v_org;
  END IF;
  IF p_confirm_engagement THEN
    IF (SELECT count(*) FROM public.service_agreements
      WHERE provider_organization_id = p_provider_id AND client_organization_id = v_org.id
        AND agreement_type = 'operational'
        AND (starts_on IS NULL OR starts_on <= current_date) AND (ends_on IS NULL OR ends_on >= current_date)) > 1 THEN
      RAISE EXCEPTION 'Several current agreements exist. Confirm engagement in the agreement workspace instead';
    END IF;
    SELECT * INTO v_agreement FROM public.service_agreements
      WHERE provider_organization_id = p_provider_id AND client_organization_id = v_org.id
        AND agreement_type = 'operational'
        AND (starts_on IS NULL OR starts_on <= current_date) AND (ends_on IS NULL OR ends_on >= current_date)
      ORDER BY created_at DESC LIMIT 1 FOR UPDATE;
    IF NOT FOUND THEN
      INSERT INTO public.service_agreements(provider_organization_id, client_organization_id, name,
        agreement_type, starts_on, invitation_status, client_portal_access_mode)
      VALUES (p_provider_id, v_org.id, v_org.name || ' services', 'operational', current_date,
        'not_invited', 'transparency_only') RETURNING * INTO v_agreement;
    END IF;
    UPDATE public.service_agreements SET external_refs = coalesce(external_refs, '{}') || jsonb_build_object(
      'engagement_confirmation', jsonb_build_object('confirmed_by', v_actor, 'confirmed_at', clock_timestamp(),
        'source', 'provider_administrator', 'request_id', p_request_id))
      WHERE id = v_agreement.id;
  END IF;
  v_result := jsonb_build_object('id', v_org.id, 'name', v_org.name, 'updated_at', v_org.updated_at,
    'agreement_id', v_agreement.id, 'engagement_confirmed', public.field_place_client_allowed(p_provider_id, v_org.id),
    'contact_email', v_org.contact_email, 'contact_phone', v_org.contact_phone, 'account_notes', v_org.account_notes);
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
    VALUES (p_provider_id, v_actor, 'service_client_saved', 'organizations', v_org.id,
      jsonb_build_object('request_id', p_request_id, 'request', v_request, 'result', v_result));
  RETURN v_result;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."save_service_client"(p_request_id uuid, p_provider_id uuid, p_client_id uuid, p_expected_updated_at timestamp with time zone, p_name text, p_email text, p_phone text, p_notes text, p_confirm_engagement boolean) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."save_service_client"(p_request_id uuid, p_provider_id uuid, p_client_id uuid, p_expected_updated_at timestamp with time zone, p_name text, p_email text, p_phone text, p_notes text, p_confirm_engagement boolean) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."save_service_client"(p_request_id uuid, p_provider_id uuid, p_client_id uuid, p_expected_updated_at timestamp with time zone, p_name text, p_email text, p_phone text, p_notes text, p_confirm_engagement boolean) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."save_service_location_profile"(p_provider_id uuid, p_location_id uuid, p_expected_updated_at timestamp with time zone, p_name text, p_notes text, p_site_id uuid DEFAULT NULL::uuid, p_site_version integer DEFAULT NULL::integer, p_site_profile jsonb DEFAULT NULL::jsonb, p_resolved_address jsonb DEFAULT NULL::jsonb, p_zone_id uuid DEFAULT NULL::uuid, p_zone_version integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_house public.locations%rowtype; v_zone public.location_zones%rowtype;
BEGIN
  IF auth.uid() IS NULL OR NOT public.field_place_provider_allowed(p_provider_id)
    OR NOT public.is_admin_for_org(p_provider_id) THEN RAISE EXCEPTION 'Provider administrator access is required'; END IF;
  SELECT * INTO v_house FROM public.locations WHERE id = p_location_id FOR UPDATE;
  IF NOT FOUND OR NOT public.field_place_client_allowed(p_provider_id, v_house.organization_id) THEN
    RAISE EXCEPTION 'Location is outside your operational clients';
  END IF;
  IF p_expected_updated_at IS NULL OR v_house.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'Location changed since it was opened. Reload before saving';
  END IF;
  IF nullif(trim(p_name), '') IS NULL OR char_length(p_name) > 200 OR char_length(coalesce(p_notes, '')) > 10000 THEN
    RAISE EXCEPTION 'Enter a name up to 200 characters and notes up to 10000 characters';
  END IF;
  IF p_resolved_address IS NOT NULL THEN
    IF jsonb_typeof(p_resolved_address) IS DISTINCT FROM 'object'
      OR nullif(trim(p_resolved_address->>'label'), '') IS NULL
      OR char_length(p_resolved_address->>'label') > 500
      OR coalesce(p_resolved_address->>'source', '') NOT IN ('linz_address','google_address','google_reverse','google_place','council_registry') THEN
      RAISE EXCEPTION 'Choose an address from the address search results';
    END IF;
    IF EXISTS (SELECT 1 FROM public.locations WHERE organization_id = v_house.organization_id
      AND id <> v_house.id AND address_match_key = public.address_match_key(p_resolved_address->>'label')) THEN
      RAISE EXCEPTION 'Another location for this client already has that address. Review the existing location before linking';
    END IF;
  END IF;
  IF p_site_id IS NOT NULL THEN
    IF p_zone_id IS NOT NULL THEN RAISE EXCEPTION 'Edit one site or area profile at a time'; END IF;
    IF p_site_version IS NULL THEN RAISE EXCEPTION 'Site version is required. Reload the profile'; END IF;
    IF NOT EXISTS (SELECT 1 FROM public.client_sites WHERE id = p_site_id AND location_id = v_house.id) THEN
      RAISE EXCEPTION 'Site does not belong to this location';
    END IF;
    IF jsonb_typeof(p_site_profile->'active') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'Choose the site active state'; END IF;
    UPDATE public.client_sites SET metadata = coalesce(metadata, '{}') || jsonb_build_object('field_place_managed', true)
      WHERE id = p_site_id;
    PERFORM public.manage_crm_site_profile(p_site_id, p_site_version, p_site_profile->>'risk_level',
      p_site_profile->>'site_brief', p_site_profile->>'access_instructions', p_site_profile->>'hs_notes',
      (p_site_profile->>'active')::boolean);
  END IF;
  IF p_zone_id IS NOT NULL THEN
    SELECT * INTO v_zone FROM public.location_zones
      WHERE id = p_zone_id AND location_id = v_house.id AND NOT is_verification_point FOR UPDATE;
    IF NOT FOUND OR p_zone_version IS NULL OR v_zone.configuration_version IS DISTINCT FROM p_zone_version THEN
      RAISE EXCEPTION 'Area changed or is not available. Reload the profile before saving';
    END IF;
    UPDATE public.location_zones SET name = trim(p_name), configuration_version = configuration_version + 1
      WHERE id = p_zone_id;
  END IF;
  UPDATE public.locations SET name = trim(p_name), notes = nullif(trim(p_notes), ''), updated_at = clock_timestamp()
    , address = CASE WHEN p_resolved_address IS NULL THEN address ELSE trim(p_resolved_address->>'label') END
    WHERE id = p_location_id RETURNING * INTO v_house;
  IF p_site_id IS NOT NULL THEN UPDATE public.client_sites SET name = trim(p_name), address = v_house.address WHERE id = p_site_id; END IF;
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
    VALUES (p_provider_id, auth.uid(), 'service_location_profile_saved', 'locations', v_house.id,
      jsonb_build_object('client_id', v_house.organization_id, 'previous_version', p_expected_updated_at, 'resolved_address', p_resolved_address));
  RETURN jsonb_build_object('location_id', v_house.id, 'updated_at', v_house.updated_at);
END;
$function$;
REVOKE ALL ON FUNCTION "public"."save_service_location_profile"(p_provider_id uuid, p_location_id uuid, p_expected_updated_at timestamp with time zone, p_name text, p_notes text, p_site_id uuid, p_site_version integer, p_site_profile jsonb, p_resolved_address jsonb, p_zone_id uuid, p_zone_version integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."save_service_location_profile"(p_provider_id uuid, p_location_id uuid, p_expected_updated_at timestamp with time zone, p_name text, p_notes text, p_site_id uuid, p_site_version integer, p_site_profile jsonb, p_resolved_address jsonb, p_zone_id uuid, p_zone_version integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."save_service_location_profile"(p_provider_id uuid, p_location_id uuid, p_expected_updated_at timestamp with time zone, p_name text, p_notes text, p_site_id uuid, p_site_version integer, p_site_profile jsonb, p_resolved_address jsonb, p_zone_id uuid, p_zone_version integer) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."schedule_court_appearance"(p_client_request_id uuid, p_officer_user_id uuid, p_court_name text, p_appearance_type text, p_scheduled_at timestamp with time zone, p_estimated_hours numeric DEFAULT 2, p_enforcement_case_id uuid DEFAULT NULL::uuid, p_case_reference text DEFAULT NULL::text, p_subpoena_reference text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS court_appearances
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_provider uuid;
  v_appearance public.court_appearances%rowtype;
  v_court text := nullif(trim(coalesce(p_court_name, '')), '');
  v_is_ot boolean;
begin
  if p_client_request_id is null then
    raise exception 'client_request_id is required';
  end if;

  select actor.organization_id into v_provider from public.user_profiles actor
  where actor.id = v_actor and actor.deactivated_at is null;

  if v_provider is null or not public.is_admin_for_org(v_provider) then
    raise exception 'Active roster administrator required';
  end if;

  select c.* into v_appearance from public.court_appearances c
  where c.organization_id = v_provider and c.client_request_id = p_client_request_id;
  if found then
    return v_appearance;
  end if;

  if v_court is null then
    raise exception 'Court name is required';
  end if;

  if p_appearance_type not in ('hearing', 'trial', 'deposition', 'tribunal', 'mediation', 'other') then
    raise exception 'Unsupported court appearance type';
  end if;

  if p_estimated_hours is null or p_estimated_hours <= 0 or p_estimated_hours > 24 then
    raise exception 'Estimated hours must be between 0 and 24';
  end if;

  -- Court time outside any rostered slot is overtime.
  v_is_ot := not exists (
    select 1 from public.roster_slots s
    join public.staff_profiles sp on sp.id = s.staff_id
    where coalesce(sp.user_id, sp.id) = p_officer_user_id
      and s.status in ('published', 'accepted', 'completed')
      and tstzrange(s.scheduled_start, s.scheduled_end, '[)')
          @> p_scheduled_at
  );

  insert into public.court_appearances(
    organization_id, officer_user_id, enforcement_case_id, court_name, case_reference,
    subpoena_reference, appearance_type, scheduled_at, estimated_hours, status,
    is_overtime, notes, client_request_id, created_by
  )
  values (
    v_provider, p_officer_user_id, p_enforcement_case_id, v_court,
    nullif(trim(coalesce(p_case_reference, '')), ''),
    nullif(trim(coalesce(p_subpoena_reference, '')), ''),
    p_appearance_type, p_scheduled_at, p_estimated_hours, 'scheduled',
    v_is_ot, nullif(trim(coalesce(p_notes, '')), ''), p_client_request_id, v_actor
  )
  returning * into v_appearance;

  perform public.enqueue_notification(
    v_provider, 'roster', 'Court appearance scheduled',
    format('%s at %s on %s.', initcap(p_appearance_type), v_court,
      to_char(p_scheduled_at at time zone 'Pacific/Auckland', 'DD Mon YYYY HH24:MI')),
    'warning', p_officer_user_id, null, 'roster',
    jsonb_build_object('court_appearance_id', v_appearance.id),
    'court_appearance:' || v_appearance.id::text
  );

  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (
    v_provider, v_actor, 'court_appearance_scheduled', 'court_appearances', v_appearance.id,
    jsonb_build_object(
      'officer_user_id', p_officer_user_id,
      'court_name', v_court,
      'scheduled_at', p_scheduled_at,
      'is_overtime', v_is_ot,
      'subpoena_reference', p_subpoena_reference,
      'client_request_id', p_client_request_id
    )
  );

  return v_appearance;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."schedule_court_appearance"(p_client_request_id uuid, p_officer_user_id uuid, p_court_name text, p_appearance_type text, p_scheduled_at timestamp with time zone, p_estimated_hours numeric, p_enforcement_case_id uuid, p_case_reference text, p_subpoena_reference text, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."schedule_court_appearance"(p_client_request_id uuid, p_officer_user_id uuid, p_court_name text, p_appearance_type text, p_scheduled_at timestamp with time zone, p_estimated_hours numeric, p_enforcement_case_id uuid, p_case_reference text, p_subpoena_reference text, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."schedule_court_appearance"(p_client_request_id uuid, p_officer_user_id uuid, p_court_name text, p_appearance_type text, p_scheduled_at timestamp with time zone, p_estimated_hours numeric, p_enforcement_case_id uuid, p_case_reference text, p_subpoena_reference text, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."schedule_court_appearance"(p_client_request_id uuid, p_officer_user_id uuid, p_court_name text, p_appearance_type text, p_scheduled_at timestamp with time zone, p_estimated_hours numeric, p_enforcement_case_id uuid, p_case_reference text, p_subpoena_reference text, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."seal_cctv_export"(p_export_id uuid)
 RETURNS cctv_exports
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  actor_id uuid := auth.uid();
  export_row public.cctv_exports;
BEGIN
  IF actor_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT *
    INTO export_row
    FROM public.cctv_exports
   WHERE id = p_export_id
   FOR UPDATE;

  IF NOT FOUND OR NOT public.is_admin_for_org(export_row.organization_id) THEN
    RAISE EXCEPTION 'CCTV export not found or administrator access denied';
  END IF;
  IF export_row.approval_state <> 'approved' THEN
    RAISE EXCEPTION 'Only approved exports may be sealed';
  END IF;

  UPDATE public.cctv_exports
     SET approval_state = 'sealed',
         sealed_at = clock_timestamp()
   WHERE id = p_export_id
   RETURNING * INTO export_row;

  INSERT INTO public.audit_log (
    organization_id,
    actor_user_id,
    action,
    target_table,
    target_id,
    metadata
  )
  VALUES (
    export_row.organization_id,
    actor_id,
    'cctv_export_sealed',
    'cctv_exports',
    p_export_id,
    jsonb_build_object(
      'previous_state', 'approved',
      'manifest_sha256', export_row.manifest_sha256
    )
  );

  RETURN export_row;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."seal_cctv_export"(p_export_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."seal_cctv_export"(p_export_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."seal_cctv_export"(p_export_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."seal_cctv_export"(p_export_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."seal_court_ready_evidence"(p_evidence_id uuid, p_sha256_hash text, p_notes text DEFAULT NULL::text)
 RETURNS TABLE(evidence_id uuid, sha256_hash text, is_court_ready boolean, locked_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_item public.evidence_items%rowtype;
  v_hash text := nullif(trim(coalesce(p_sha256_hash, '')), '');
begin
  if v_user_id is null then raise exception 'Authentication required'; end if;
  if v_hash is null then raise exception 'sha256_hash is required to seal court-ready evidence'; end if;

  select e.* into v_item from public.evidence_items e where e.id = p_evidence_id for update;
  if not found then raise exception 'Evidence item not found'; end if;
  if not public.is_admin_for_org(v_item.organization_id) and v_item.captured_by_user_id <> v_user_id then
    raise exception 'Not authorised to seal this evidence item';
  end if;

  if v_item.locked_at is not null then
    raise exception 'Evidence item is already sealed and locked';
  end if;

  update public.evidence_items
    set sha256_hash = v_hash,
        is_court_ready = true,
        locked_at = clock_timestamp(),
        metadata = metadata || jsonb_build_object('seal_notes', nullif(trim(coalesce(p_notes, '')), ''), 'sealed_by', v_user_id)
    where id = v_item.id
    returning * into v_item;

  insert into public.audit_log (
    organization_id, actor_user_id, action, target_table, target_id, metadata
  ) values (
    v_item.organization_id, v_user_id, 'evidence_media_sealed', 'evidence_items', v_item.id,
    jsonb_build_object('sha256_hash', v_hash, 'locked_at', v_item.locked_at, 'notes', p_notes)
  );

  return query select v_item.id, v_item.sha256_hash, v_item.is_court_ready, v_item.locked_at;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."seal_court_ready_evidence"(p_evidence_id uuid, p_sha256_hash text, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."seal_court_ready_evidence"(p_evidence_id uuid, p_sha256_hash text, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."seal_court_ready_evidence"(p_evidence_id uuid, p_sha256_hash text, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."seal_court_ready_evidence"(p_evidence_id uuid, p_sha256_hash text, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."search_activity_records"(p_kind text, p_zone_ids uuid[], p_site_ids uuid[], p_term text, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS TABLE(record jsonb, total_count bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_term text := trim(coalesce(p_term, ''));
  v_pattern text;
  v_limit integer := least(greatest(coalesce(p_limit, 50), 1), 100);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF length(v_term) < 2 THEN RAISE EXCEPTION 'Enter at least 2 characters to search'; END IF;
  v_pattern := '%' || replace(replace(replace(v_term, '\', '\\'), '%', '\%'), '_', '\_') || '%';

  IF p_kind = 'visits' THEN
    RETURN QUERY
    WITH candidates AS (
      SELECT e.id FROM public.location_events e
      WHERE public.location_event_search_text(e.event_type, e.payload) ILIKE v_pattern
      UNION
      SELECT r.record_id FROM public.record_updates r WHERE r.record_kind = 'location_event' AND r.body ILIKE v_pattern
      UNION
      SELECT e.id FROM public.location_events e
      JOIN public.user_profiles u ON u.id = e.observed_entity_id
      WHERE u.display_name ILIKE v_pattern
    ), matched AS (
      SELECT e.* FROM candidates c JOIN public.location_events e ON e.id = c.id
      WHERE (e.zone_id = ANY(coalesce(p_zone_ids, '{}')) OR e.client_site_id = ANY(coalesce(p_site_ids, '{}')))
        AND (p_from IS NULL OR e.occurred_at >= p_from) AND (p_to IS NULL OR e.occurred_at < p_to)
        AND (public.org_access_allowed(e.organization_id) OR public.has_location_access(e.client_site_id, e.zone_id, 'client_reads_provider'))
    )
    SELECT jsonb_build_object('id', m.id, 'organization_id', m.organization_id, 'event_type', m.event_type,
        'occurred_at', m.occurred_at, 'module_key', m.module_key, 'source', m.source, 'distance_km', m.distance_km,
        'zone_id', m.zone_id, 'client_site_id', m.client_site_id, 'observed_entity_id', m.observed_entity_id,
        'payload', m.payload),
      count(*) OVER ()
    FROM matched m ORDER BY m.occurred_at DESC LIMIT v_limit OFFSET v_offset;
  ELSIF p_kind = 'sightings' THEN
    RETURN QUERY
    WITH candidates AS (
      SELECT o.id FROM public.observations o
      WHERE public.observation_search_text(o.plate_number, o.officer_notes, o.reported_by_name, o.source_document_name,
        o.source_reference, o.compliance_reason, o.subject_kind, o.vehicle_make, o.vehicle_model, o.vehicle_colour, o.external_refs) ILIKE v_pattern
      UNION
      SELECT r.record_id FROM public.record_updates r WHERE r.record_kind = 'observation' AND r.body ILIKE v_pattern
      UNION
      SELECT o.id FROM public.observations o JOIN public.person_records p ON p.id = o.person_record_id
      WHERE p.display_name ILIKE v_pattern
      UNION
      SELECT o.id FROM public.observations o JOIN public.user_profiles u ON u.id = o.officer_id
      WHERE u.display_name ILIKE v_pattern
    ), matched AS (
      SELECT o.* FROM candidates c JOIN public.observations o ON o.id = c.id
      WHERE (o.zone_id = ANY(coalesce(p_zone_ids, '{}')) OR o.site_id = ANY(coalesce(p_site_ids, '{}')))
        AND (p_from IS NULL OR o.observed_at >= p_from) AND (p_to IS NULL OR o.observed_at < p_to)
        AND (public.org_access_allowed(o.organization_id) OR public.org_access_allowed(o.client_org_id)
          OR public.user_has_task_entitlement(v_uid, o.id))
    )
    SELECT jsonb_build_object('id', m.id, 'organization_id', m.organization_id, 'observed_at', m.observed_at,
        'plate_number', m.plate_number, 'officer_id', m.officer_id, 'zone_id', m.zone_id, 'site_id', m.site_id,
        'distance_km', m.distance_km, 'officer_notes', m.officer_notes, 'is_compliant', m.is_compliant,
        'compliance_reason', m.compliance_reason, 'canonical_vehicle_id', m.canonical_vehicle_id,
        'canonical_person_id', m.canonical_person_id, 'person_record_id', m.person_record_id,
        'subject_kind', m.subject_kind, 'reported_by_name', m.reported_by_name,
        'source_document_name', m.source_document_name, 'source_reference', m.source_reference,
        'source_sha256', m.source_sha256, 'source_locator', m.source_locator,
        'person_record', (SELECT jsonb_build_object('display_name', p.display_name) FROM public.person_records p
          WHERE p.id = m.person_record_id AND public.org_access_allowed(p.organization_id)),
        'external_refs', m.external_refs),
      count(*) OVER ()
    FROM matched m ORDER BY m.observed_at DESC LIMIT v_limit OFFSET v_offset;
  ELSE
    RAISE EXCEPTION 'Unsupported record kind';
  END IF;
END;
$function$;
COMMENT ON FUNCTION "public"."search_activity_records"(p_kind text, p_zone_ids uuid[], p_site_ids uuid[], p_term text, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer, p_offset integer) IS 'Full-text search of patrol visits (every payload field) or vehicle sightings (plate, notes, reporter, source, reason, vehicle, imported fields, person name, officer name) plus appended record updates, across all dates unless a window is given. Restricted to the requested places and the same row access as the table policies.';
REVOKE ALL ON FUNCTION "public"."search_activity_records"(p_kind text, p_zone_ids uuid[], p_site_ids uuid[], p_term text, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer, p_offset integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."search_activity_records"(p_kind text, p_zone_ids uuid[], p_site_ids uuid[], p_term text, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer, p_offset integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."search_activity_records"(p_kind text, p_zone_ids uuid[], p_site_ids uuid[], p_term text, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer, p_offset integer) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."search_observations"(p_organization_id uuid, p_search text DEFAULT NULL::text, p_site_id uuid DEFAULT NULL::uuid, p_zone_id uuid DEFAULT NULL::uuid, p_location_id uuid DEFAULT NULL::uuid, p_vehicle_id uuid DEFAULT NULL::uuid, p_person_id uuid DEFAULT NULL::uuid, p_incident_id uuid DEFAULT NULL::uuid, p_poi boolean DEFAULT NULL::boolean, p_loi boolean DEFAULT NULL::boolean, p_limit integer DEFAULT 50)
 RETURNS TABLE(observation_id uuid, observed_at timestamp with time zone, organization_id uuid, plate_number text, vehicle_id uuid, vehicle_label text, vehicle_homeless_status text, person_id uuid, person_label text, person_category text, person_homeless_status text, site_id uuid, site_name text, zone_id uuid, zone_name text, location_id uuid, location_name text, incident_id uuid, incident_label text, poi boolean, loi boolean, compliance_status text, officer_notes text, photo_url text)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  WITH identity_scope AS MATERIALIZED (
    SELECT public.can_view_rnm_identity_for_organization(p_organization_id) AS can_view
  )
  SELECT o.id, o.observed_at, o.organization_id, o.plate_number,
    o.canonical_vehicle_id,
    COALESCE(NULLIF(trim(concat_ws(' ', cv.plate_number, cv.make, cv.model)), ''), o.plate_number),
    NULLIF(cv.homeless_status, 'none'),
    CASE WHEN identity_scope.can_view AND cpp.id IS NOT NULL THEN o.person_record_id END,
    CASE WHEN identity_scope.can_view AND cpp.id IS NOT NULL THEN cpp.display_name END,
    CASE WHEN identity_scope.can_view AND cpp.id IS NOT NULL THEN NULLIF(pr.metadata -> 'profile_details' ->> 'category', '') END,
    CASE WHEN identity_scope.can_view AND cpp.id IS NOT NULL THEN NULLIF(cpp.homeless_status, 'none') END,
    o.site_id, cs.name, o.zone_id, z.name,
    o.location_id, l.name, o.incident_id,
    CASE WHEN i.id IS NULL THEN NULL ELSE concat_ws(': ', i.incident_type, i.description) END,
    COALESCE(vf.active, false), COALESCE(pf.active, false), o.compliance_status,
    o.officer_notes, o.photo_url
  FROM public.observations o
  CROSS JOIN identity_scope
  LEFT JOIN public.canonical_vehicle_public cv ON cv.id = o.canonical_vehicle_id
  LEFT JOIN public.person_records pr ON pr.id = o.person_record_id AND pr.organization_id=o.organization_id AND pr.review_state='verified' AND identity_scope.can_view
  LEFT JOIN LATERAL (
    SELECT cpl.canonical_person_id FROM public.canonical_person_links cpl
    WHERE identity_scope.can_view AND cpl.source_table = 'person_records' AND cpl.source_id = pr.id AND cpl.organization_id=pr.organization_id
    LIMIT 1
  ) link ON true
  LEFT JOIN public.canonical_person_public cpp ON identity_scope.can_view AND cpp.id = COALESCE(o.canonical_person_id,link.canonical_person_id) AND cpp.review_state='verified' AND cpp.status='active'
  LEFT JOIN public.client_sites cs ON cs.id = o.site_id
  LEFT JOIN public.location_zones z ON z.id = o.zone_id
  LEFT JOIN public.locations l ON l.id = o.location_id
  LEFT JOIN public.incidents i ON i.id = o.incident_id
  LEFT JOIN LATERAL (
    SELECT bool_or(ef.active AND ef.flag_type IN ('poi','voi')) AS active
    FROM public.entity_flags ef
    WHERE ef.organization_id = o.organization_id AND ef.entity_type = 'vehicle'
      AND ef.entity_id = COALESCE(o.canonical_vehicle_id, cv.id)
  ) vf ON true
  LEFT JOIN LATERAL (
    SELECT bool_or(ef.active AND ef.flag_type IN ('loi','poi')) AS active
    FROM public.entity_flags ef
    WHERE identity_scope.can_view AND ef.organization_id = o.organization_id AND ef.entity_type = 'person'
      AND ef.entity_id = o.person_record_id
  ) pf ON true
  WHERE o.organization_id = p_organization_id
    AND public.org_access_allowed(o.organization_id)
    AND (p_site_id IS NULL OR o.site_id = p_site_id)
    AND (p_zone_id IS NULL OR o.zone_id = p_zone_id)
    AND (p_location_id IS NULL OR o.location_id = p_location_id)
    AND (p_vehicle_id IS NULL OR o.canonical_vehicle_id = p_vehicle_id)
    AND (p_person_id IS NULL OR (identity_scope.can_view AND (o.person_record_id = p_person_id OR COALESCE(o.canonical_person_id,link.canonical_person_id) = p_person_id)))
    AND (p_incident_id IS NULL OR o.incident_id = p_incident_id)
    AND (p_poi IS NULL OR COALESCE(vf.active, false) = p_poi)
    AND (p_loi IS NULL OR COALESCE(pf.active, false) = p_loi)
    AND (
      NULLIF(trim(p_search), '') IS NULL OR
      concat_ws(' ', o.plate_number, o.officer_notes, cv.plate_number, cv.make, cv.model,
        pr.display_name, cs.name, z.name, l.name, l.address, l.suburb, l.notes, i.incident_type, i.description,
        o.location_id::text, o.site_id::text, o.zone_id::text) ILIKE '%' || trim(p_search) || '%'
    )
  ORDER BY o.observed_at DESC
  LIMIT LEAST(GREATEST(COALESCE(p_limit, 50), 1), 100);
$function$;
REVOKE ALL ON FUNCTION "public"."search_observations"(p_organization_id uuid, p_search text, p_site_id uuid, p_zone_id uuid, p_location_id uuid, p_vehicle_id uuid, p_person_id uuid, p_incident_id uuid, p_poi boolean, p_loi boolean, p_limit integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."search_observations"(p_organization_id uuid, p_search text, p_site_id uuid, p_zone_id uuid, p_location_id uuid, p_vehicle_id uuid, p_person_id uuid, p_incident_id uuid, p_poi boolean, p_loi boolean, p_limit integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."search_observations"(p_organization_id uuid, p_search text, p_site_id uuid, p_zone_id uuid, p_location_id uuid, p_vehicle_id uuid, p_person_id uuid, p_incident_id uuid, p_poi boolean, p_loi boolean, p_limit integer) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."search_observations"(p_organization_id uuid, p_search text, p_site_id uuid, p_zone_id uuid, p_location_id uuid, p_vehicle_id uuid, p_person_id uuid, p_incident_id uuid, p_poi boolean, p_loi boolean, p_limit integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."search_people"(p_query text, p_limit integer DEFAULT 25)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_query text := regexp_replace(lower(trim(coalesce(p_query, ''))), '\s+', ' ', 'g');
  v_norm text;
  v_tokens text[];
  v_limit integer := least(greatest(coalesce(p_limit, 25), 1), 50);
  v_orgs uuid[];
  v_identity_orgs uuid[];
  v_contact_orgs uuid[];
  v_result jsonb;
BEGIN
  IF NOT public.can_search_people() THEN
    RAISE EXCEPTION 'Person-search authorization required' USING ERRCODE = '42501';
  END IF;
  v_norm := regexp_replace(v_query, '[^a-z0-9]+', '', 'g');
  IF length(v_norm) < 2 THEN RAISE EXCEPTION 'Enter at least two letters or numbers'; END IF;
  v_tokens := array(
    SELECT token FROM unnest(regexp_split_to_array(regexp_replace(v_query, '[^a-z0-9 ]+', '', 'g'), ' ')) token
    WHERE token <> ''
  );
  v_orgs := array(SELECT o.id FROM public.organizations o WHERE public.can_search_people(o.id));
  v_identity_orgs := array(SELECT org_id FROM unnest(v_orgs) org_id WHERE public.can_access_vehicle_owner_identity(org_id));
  v_contact_orgs := array(SELECT org_id FROM unnest(v_orgs) org_id WHERE public.can_access_person_contacts(org_id));

  WITH matched AS (
    SELECT p.id FROM public.canonical_people p
    WHERE p.status = 'active'
      AND (p.normalized_name LIKE '%' || v_norm || '%'
        OR (cardinality(v_tokens) > 1 AND NOT EXISTS (
          SELECT 1 FROM unnest(v_tokens) token WHERE position(token IN lower(coalesce(p.display_name, ''))) = 0)))
    UNION
    SELECT link.canonical_person_id
    FROM public.person_record_aliases alias
    JOIN public.canonical_person_links link ON link.source_table = 'person_records' AND link.source_id = alias.person_record_id
    WHERE alias.active AND alias.organization_id = ANY(v_orgs) AND alias.alias_norm LIKE '%' || v_norm || '%'
    UNION
    SELECT link.canonical_person_id
    FROM public.person_records record
    JOIN public.canonical_person_links link ON link.source_table = 'person_records' AND link.source_id = record.id
    WHERE record.organization_id = ANY(v_orgs)
      AND regexp_replace(lower(coalesce(record.display_name, '')), '[^a-z0-9]+', '', 'g') LIKE '%' || v_norm || '%'
    UNION
    SELECT permit.canonical_person_id FROM public.person_permits permit
    WHERE permit.organization_id = ANY(v_orgs)
      AND regexp_replace(lower(permit.permit_number), '[^a-z0-9]+', '', 'g') = v_norm
  ), visible AS (
    SELECT p.* FROM public.canonical_people p
    WHERE p.id IN (SELECT id FROM matched) AND p.status = 'active'
      AND (EXISTS (SELECT 1 FROM public.canonical_person_links link
                   WHERE link.canonical_person_id = p.id AND link.organization_id = ANY(v_orgs))
        OR EXISTS (SELECT 1 FROM public.notices notice
                   WHERE notice.person_id = p.id AND notice.organization_id = ANY(v_orgs))
        OR EXISTS (SELECT 1 FROM public.person_permits permit
                   WHERE permit.canonical_person_id = p.id AND permit.organization_id = ANY(v_orgs)))
  ), ranked AS (
    SELECT v.*,
      (v.normalized_name = v_norm OR EXISTS (
        SELECT 1 FROM public.person_permits permit
        WHERE permit.canonical_person_id = v.id AND permit.organization_id = ANY(v_orgs)
          AND regexp_replace(lower(permit.permit_number), '[^a-z0-9]+', '', 'g') = v_norm)) AS exact_match,
      EXISTS (SELECT 1 FROM public.notices notice
              WHERE notice.person_id = v.id AND notice.organization_id = ANY(v_orgs)
                AND notice.status = 'issued' AND notice.notice_type IN ('trespass', 'warning')
                AND (notice.expires_at IS NULL OR notice.expires_at > clock_timestamp())) AS has_notice_in_force
    FROM visible v
    ORDER BY exact_match DESC, has_notice_in_force DESC, v.display_name
    LIMIT v_limit
  )
  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'canonical_person_id', r.id,
    'display_name', r.display_name,
    'review_state', r.review_state,
    'homeless_status', r.homeless_status,
    'has_notice_in_force', r.has_notice_in_force,
    'contact_details_authorised', cardinality(v_contact_orgs) > 0,
    'aliases', coalesce((
      SELECT jsonb_agg(DISTINCT alias.alias)
      FROM public.canonical_person_links link
      JOIN public.person_record_aliases alias ON alias.person_record_id = link.source_id AND alias.active
      WHERE link.canonical_person_id = r.id AND link.source_table = 'person_records' AND alias.organization_id = ANY(v_orgs)
    ), '[]'::jsonb),
    'organizations', coalesce((
      SELECT jsonb_agg(DISTINCT org.name) FROM public.organizations org
      WHERE org.id = ANY(v_orgs)
        AND (EXISTS (SELECT 1 FROM public.canonical_person_links link WHERE link.canonical_person_id = r.id AND link.organization_id = org.id)
          OR EXISTS (SELECT 1 FROM public.notices notice WHERE notice.person_id = r.id AND notice.organization_id = org.id)
          OR EXISTS (SELECT 1 FROM public.person_permits permit WHERE permit.canonical_person_id = r.id AND permit.organization_id = org.id))
    ), '[]'::jsonb),
    'notices', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'notice_id', notice.id, 'organization_id', notice.organization_id, 'organization_name', org.name,
        'notice_type', notice.notice_type, 'notice_number', notice.notice_number, 'status', notice.status,
        'issued_at', notice.issued_at, 'expires_at', notice.expires_at,
        'expiry_state', public.notice_expiry_state(notice.status, notice.expires_at), 'location_name', place.name
      ) ORDER BY notice.issued_at DESC NULLS LAST)
      FROM public.notices notice JOIN public.organizations org ON org.id = notice.organization_id
      LEFT JOIN public.observations observation ON observation.id = notice.observation_id
      LEFT JOIN public.locations place ON place.id = coalesce(notice.location_id, observation.location_id)
      WHERE notice.person_id = r.id AND notice.organization_id = ANY(v_orgs)
    ), '[]'::jsonb),
    'permits', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'permit_id', permit.id, 'organization_name', org.name, 'client_organization_name', client.name,
        'permit_number', permit.permit_number, 'permit_type', permit.permit_type,
        'applicant_type', permit.applicant_type, 'company_name', permit.company_name, 'status', permit.status,
        'validity_state', public.person_permit_validity(permit.status, permit.date_from, permit.date_to),
        'date_from', permit.date_from, 'date_to', permit.date_to,
        'forest_areas', coalesce(to_jsonb(permit.forest_areas), '[]'::jsonb),
        'activities', coalesce(to_jsonb(permit.activities), '[]'::jsonb),
        'hunting_season', permit.hunting_season, 'firearm_licence_valid', permit.firearm_licence_valid,
        'chainsaw_safety_equipment', permit.chainsaw_safety_equipment, 'keys_issued', permit.keys_issued,
        'conditions', permit.conditions,
        'contact_email', CASE WHEN permit.organization_id = ANY(v_contact_orgs) THEN permit.contact_email END,
        'contact_phone', CASE WHEN permit.organization_id = ANY(v_contact_orgs) THEN permit.contact_phone END,
        'address_text', CASE WHEN permit.organization_id = ANY(v_contact_orgs) THEN permit.address_text END,
        'compliance_checked_at', permit.compliance_checked_at, 'source_document', permit.source_document,
        'vehicles', coalesce((
          SELECT jsonb_agg(jsonb_build_object(
            'canonical_vehicle_id', vehicle.id, 'plate_number', vehicle.plate_number,
            'make', vehicle.make, 'model', vehicle.model, 'colour', vehicle.colour
          ) ORDER BY vehicle.plate_number)
          FROM public.person_permit_vehicles permit_vehicle
          JOIN public.canonical_vehicles vehicle ON vehicle.id = permit_vehicle.canonical_vehicle_id
          WHERE permit_vehicle.permit_id = permit.id
        ), '[]'::jsonb)
      ) ORDER BY permit.date_to DESC NULLS LAST, permit.created_at DESC)
      FROM public.person_permits permit JOIN public.organizations org ON org.id = permit.organization_id
      LEFT JOIN public.organizations client ON client.id = permit.client_organization_id
      WHERE permit.canonical_person_id = r.id AND permit.organization_id = ANY(v_orgs)
    ), '[]'::jsonb),
    'vehicles', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'canonical_vehicle_id', vehicle.id, 'plate_number', vehicle.plate_number,
        'make', vehicle.make, 'model', vehicle.model, 'colour', vehicle.colour,
        'relationship', link.relationship, 'since', link.starts_at,
        'source', CASE WHEN link.organization_id = ANY(v_identity_orgs) THEN link.evidence->>'source' END,
        'source_checked_at', CASE WHEN link.organization_id = ANY(v_identity_orgs) THEN link.evidence->>'source_checked_at' END
      ) ORDER BY link.starts_at DESC NULLS LAST)
      FROM public.entity_links link JOIN public.canonical_vehicles vehicle ON vehicle.id = link.to_id
      WHERE link.from_type = 'person' AND link.from_id = r.id AND link.to_type = 'vehicle'
        AND link.active AND link.organization_id = ANY(v_orgs)
        AND (link.relationship NOT IN ('owner', 'registered_owner', 'driver', 'associated_person')
          OR link.organization_id = ANY(v_identity_orgs))
        AND (NOT coalesce((link.evidence->>'nzta_restricted')::boolean, false) OR link.organization_id = ANY(rv.orgs))
    ), '[]'::jsonb),
    'nzta_authorised', cardinality(v_identity_orgs) > 0,
    -- A reveal opens NZTA data only for the organisations it was logged in;
    -- anything recorded by another authorised organisation still needs a reveal.
    'nzta_reveal_required', cardinality(v_identity_orgs) > 0 AND (
      EXISTS (SELECT 1 FROM public.vehicle_identity_checks pending_check
              WHERE pending_check.canonical_person_id = r.id AND pending_check.organization_id = ANY(v_identity_orgs)
                AND pending_check.organization_id <> ALL(rv.orgs))
      OR EXISTS (SELECT 1 FROM public.entity_links pending_link
                 WHERE pending_link.from_type = 'person' AND pending_link.from_id = r.id AND pending_link.to_type = 'vehicle'
                   AND pending_link.active AND pending_link.organization_id = ANY(v_identity_orgs)
                   AND pending_link.organization_id <> ALL(rv.orgs)
                   AND coalesce((pending_link.evidence->>'nzta_restricted')::boolean, false))),
    'nzta', CASE WHEN cardinality(rv.orgs) = 0 THEN NULL ELSE (
      SELECT jsonb_build_object(
        'address', CASE WHEN check_row.organization_id = ANY(v_contact_orgs) THEN
          coalesce(doc.extracted_fields->'approved'->>'address',
                   doc.extracted_fields->'proposed'->>'physical_address',
                   doc.extracted_fields->'proposed'->>'address') END,
        'last_checked_at', check_row.checked_at,
        'checks', (
          SELECT coalesce(jsonb_agg(jsonb_build_object(
            'plate_number', checked_vehicle.plate_number, 'checked_at', history.checked_at
          ) ORDER BY history.checked_at DESC), '[]'::jsonb)
          FROM public.vehicle_identity_checks history
          JOIN public.canonical_vehicles checked_vehicle ON checked_vehicle.id = history.canonical_vehicle_id
          WHERE history.canonical_person_id = r.id AND history.organization_id = ANY(rv.orgs)
        )
      )
      FROM public.vehicle_identity_checks check_row
      JOIN public.person_identity_documents doc ON doc.id = check_row.identity_document_id
      WHERE check_row.canonical_person_id = r.id AND check_row.organization_id = ANY(rv.orgs)
      ORDER BY check_row.checked_at DESC LIMIT 1
    ) END
  ) ORDER BY r.exact_match DESC, r.has_notice_in_force DESC, r.display_name), '[]'::jsonb)
  INTO v_result FROM ranked r
  CROSS JOIN LATERAL (
    SELECT array(SELECT org_id FROM unnest(v_identity_orgs) org_id
                 WHERE public.nzta_reveal_active(ARRAY[org_id], 'person', r.id)) AS orgs
  ) rv;
  RETURN v_result;
END;
$function$;
COMMENT ON FUNCTION "public"."search_people"(p_query text, p_limit integer) IS 'Authorized operational person search by name, alias or exact permit number. Organization-scoped notices, permits and linked vehicles. NZTA-sourced person-vehicle links and the NZTA block need vehicle-owner authorisation plus an open purpose-stated reveal (reveal_nzta_registered_person). Private contact/address values require active Admin, Admin officer, Master or Grand Master access. No firearm licence numbers.';
REVOKE ALL ON FUNCTION "public"."search_people"(p_query text, p_limit integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."search_people"(p_query text, p_limit integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."search_people"(p_query text, p_limit integer) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."search_vehicle_registrations"(p_pattern text, p_limit integer DEFAULT 51)
 RETURNS TABLE(id uuid, plate_number text, make text, model text, year integer, colour text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_pattern IS NULL OR length(p_pattern) > 40 OR p_pattern !~ '^[A-Za-z0-9%]+$'
    OR p_pattern !~ '[A-Za-z0-9]' THEN
    RAISE EXCEPTION 'Enter a registration fragment using letters, numbers and %% wildcards';
  END IF;
  RETURN QUERY
  WITH candidates AS (
    SELECT v.id, v.plate_number, v.make, v.model, v.year, v.colour
    FROM public.canonical_vehicle_public v WHERE v.plate_number ILIKE p_pattern
    UNION ALL
    SELECT NULL::uuid, upper(regexp_replace(o.plate_number, '[^A-Za-z0-9]', '', 'g')),
      NULL::text, NULL::text, NULL::integer, NULL::text
    FROM public.observations o
    WHERE o.canonical_vehicle_id IS NULL
      AND upper(regexp_replace(o.plate_number, '[^A-Za-z0-9]', '', 'g')) ILIKE p_pattern
  ), unique_plates AS (
    SELECT DISTINCT ON (c.plate_number) c.*
    FROM candidates c
    ORDER BY c.plate_number, c.id NULLS LAST
  )
  SELECT u.* FROM unique_plates u ORDER BY u.plate_number
  LIMIT least(greatest(coalesce(p_limit, 51), 1), 51);
END;
$function$;
COMMENT ON FUNCTION "public"."search_vehicle_registrations"(p_pattern text, p_limit integer) IS 'Registration discovery from the existing Tier-0 canonical vehicle projection, with caller-RLS fallback for legacy unlinked observations only. Does not enumerate linked observation history or implement a separate permission engine.';
REVOKE ALL ON FUNCTION "public"."search_vehicle_registrations"(p_pattern text, p_limit integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."search_vehicle_registrations"(p_pattern text, p_limit integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."search_vehicle_registrations"(p_pattern text, p_limit integer) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."seed_aam_e2e_dataset"(p_provider_organization_id uuid, p_owner_user_id uuid, p_admin_user_id uuid, p_admin_email text, p_officer_user_ids uuid[], p_officer_emails text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_account_id constant uuid:='a1000000-0000-4000-8000-000000000001';v_location_id constant uuid:='a1000000-0000-4000-8000-000000000002';v_site_id constant uuid:='a1000000-0000-4000-8000-000000000003';v_agreement_id constant uuid:='a1000000-0000-4000-8000-000000000004';v_contact_id constant uuid:='a1000000-0000-4000-8000-000000000005';v_commercial_id constant uuid:='a1000000-0000-4000-8000-000000000006';
  v_site_link_id uuid;v_static_module_id uuid;v_work_unit_id uuid;v_module text;v_zone_type text;v_zone_id uuid;v_index integer;v_shift_type text;v_start time;v_end time;
  v_operational_modules text[]:=array['access_control','biosecurity','ems','freedom_camping','noise_control','parking_enforcement','patrol','smoke_complaints','static_guarding'];
begin
  if auth.role() is distinct from 'service_role' then raise exception 'Service role required';end if;
  if not exists(select 1 from public.organizations o where o.id=p_provider_organization_id and o.active) then raise exception 'Active provider organization required';end if;
  if not exists(select 1 from public.user_profiles u where u.id=p_owner_user_id and u.organization_id=p_provider_organization_id and u.role in('grand_master','master','admin') and u.deactivated_at is null) then raise exception 'Active provider owner required';end if;
  if cardinality(p_officer_user_ids)<>5 or cardinality(p_officer_emails)<>5 then raise exception 'Exactly five AAM officers are required';end if;
  perform public.purge_aam_e2e_dataset(p_provider_organization_id);

  insert into public.user_profiles(id,organization_id,role,display_name,email,deactivated_at) values(p_admin_user_id,p_provider_organization_id,'admin','AAM E2E Administrator',p_admin_email,null) on conflict(id) do update set organization_id=excluded.organization_id,role=excluded.role,display_name=excluded.display_name,email=excluded.email,deactivated_at=null;
  for v_index in 1..5 loop
    insert into public.user_profiles(id,organization_id,role,display_name,email,deactivated_at) values(p_officer_user_ids[v_index],p_provider_organization_id,'officer','AAM E2E Officer '||v_index,p_officer_emails[v_index],null) on conflict(id) do update set organization_id=excluded.organization_id,role=excluded.role,display_name=excluded.display_name,email=excluded.email,deactivated_at=null;
    insert into public.staff_profiles(id,organization_id,employee_number,employment_type,start_date,user_id,work_ready,notes) values(p_officer_user_ids[v_index],p_provider_organization_id,'AAM-'||lpad(v_index::text,3,'0'),'casual',current_date,p_officer_user_ids[v_index],true,'AAM E2E retained test identity') on conflict(id) do update set organization_id=excluded.organization_id,employee_number=excluded.employee_number,user_id=excluded.user_id,work_ready=true,notes=excluded.notes;
  end loop;

  insert into public.organizations(id,name,organization_type,parent_organization_id,active,status,contact_email,billing_email,billing_address,account_notes,external_refs) values(v_account_id,'AAM End-to-End Test Account','client',p_provider_organization_id,false,'prospect','operations@aam-e2e.test','billing@aam-e2e.test','100 Test Avenue, Wellington','Controlled synthetic account. Safe to purge and reseed.',jsonb_build_object('dataset','aam_e2e_20260831'));
  insert into public.crm_contacts(id,organization_id,first_name,last_name,role_title,email,is_primary,is_emergency) values(v_contact_id,v_account_id,'Ari','AAM','Test Operations Lead','ari@aam-e2e.test',true,true);
  insert into public.locations(id,organization_id,name,address,address_match_key,suburb,postcode,notes,created_by) values(v_location_id,v_account_id,'AAM Test Operations House','100 Test Avenue, Wellington','100testavenuewellington','Te Aro','6011','Synthetic location for module, zone, and roster verification.',p_admin_user_id);
  insert into public.client_sites(id,client_organization_id,organization_id,location_id,name,address,address_match_key,site_type,risk_level,site_brief,access_instructions,hs_notes,active,site_origin,boundary,boundary_status,boundary_verification,boundary_verified_by,boundary_verified_at,external_refs) values(v_site_id,v_account_id,v_account_id,v_location_id,'AAM Test Operations Site','100 Test Avenue, Wellington','100testavenuewellington','commercial_premises','medium','Synthetic all-module operational test site.','Use the signed east service entrance. Test access code only.','Synthetic hazards: vehicle movement and wet-surface controls.',true,'contracted',st_geomfromtext('POLYGON((174.7750 -41.2920,174.7770 -41.2920,174.7770 -41.2900,174.7750 -41.2900,174.7750 -41.2920))',4326),'authoritative','verified',p_owner_user_id,clock_timestamp(),jsonb_build_object('dataset','aam_e2e_20260831'));
  insert into public.geofence_boundary_history(entity_type,entity_id,boundary,boundary_source,verification_state,verified_by,verified_at,changed_by,changed_via,change_reason,version) select 'client_site',v_site_id,s.boundary,'aam_e2e_seed','verified',p_owner_user_id,clock_timestamp(),p_owner_user_id,'backfill','AAM E2E verified test site boundary',1 from public.client_sites s where s.id=v_site_id;

  foreach v_module in array v_operational_modules loop
    v_zone_id:=(substr(md5('aam-e2e-zone-'||v_module),1,8)||'-'||substr(md5('aam-e2e-zone-'||v_module),9,4)||'-4'||substr(md5('aam-e2e-zone-'||v_module),14,3)||'-8'||substr(md5('aam-e2e-zone-'||v_module),18,3)||'-'||substr(md5('aam-e2e-zone-'||v_module),21,12))::uuid;
    v_zone_type:=case v_module when 'access_control' then 'access_control' when 'biosecurity' then 'biosecurity' when 'freedom_camping' then 'freedom_camping' when 'noise_control' then 'noise_control' when 'parking_enforcement' then 'parking' when 'patrol' then 'patrol_route' else 'general' end;
    insert into public.location_zones(id,organization_id,location_id,name,zone_type,module_key,rule_type,is_active,boundary,boundary_status,boundary_verification,boundary_verified_by,boundary_verified_at,center_point,metadata) values(v_zone_id,v_account_id,v_location_id,'AAM '||replace(initcap(v_module),'_',' ')||' Zone',v_zone_type,v_module,'restricted',true,st_multi(st_geomfromtext('POLYGON((174.7745 -41.2925,174.7775 -41.2925,174.7775 -41.2895,174.7745 -41.2895,174.7745 -41.2925))',4326)), 'authoritative','verified',p_owner_user_id,clock_timestamp(),st_geomfromtext('POINT(174.776 -41.291)',4326),jsonb_build_object('dataset','aam_e2e_20260831'));
    insert into public.geofence_boundary_history(entity_type,entity_id,boundary,boundary_source,verification_state,verified_by,verified_at,changed_by,changed_via,change_reason,version) select 'location_zone',v_zone_id,z.boundary,'aam_e2e_seed','verified',p_owner_user_id,clock_timestamp(),p_owner_user_id,'backfill','AAM E2E verified module zone',1 from public.location_zones z where z.id=v_zone_id;
  end loop;

  insert into public.service_agreements(id,provider_organization_id,client_organization_id,name,starts_on,agreement_type,invitation_status,client_portal_access_mode,client_portal_reports_enabled,enabled_modules,external_refs) select v_agreement_id,p_provider_organization_id,v_account_id,'AAM All-Module Service Agreement',current_date,'operational','accepted','full_modules',false,array_agg(mc.module_key order by mc.module_key),jsonb_build_object('dataset','aam_e2e_20260831') from public.module_catalog mc where mc.active;
  insert into public.service_agreement_modules(id,service_agreement_id,module_key,enabled,sla_minutes,allows_client_submission,allows_auto_dispatch,standalone_scan_enabled,settings) select gen_random_uuid(),v_agreement_id,mc.module_key,true,30,true,true,(mc.module_key in('freedom_camping','parking_enforcement')),jsonb_build_object('dataset','aam_e2e_20260831') from public.module_catalog mc where mc.active;
  insert into public.service_agreement_locations(id,service_agreement_id,site_id,status,created_by) values(gen_random_uuid(),v_agreement_id,v_site_id,'active',p_admin_user_id) returning id into v_site_link_id;
  insert into public.service_agreement_locations(id,service_agreement_id,zone_id,status,created_by) select gen_random_uuid(),v_agreement_id,z.id,'active',p_admin_user_id from public.location_zones z where z.location_id=v_location_id;
  insert into public.crm_commercial_settings(id,service_agreement_id,billing_cycle,payment_terms_days,currency,base_rate_per_hour,invoice_email,notes) values(v_commercial_id,v_agreement_id,'monthly',14,'NZD',85,'billing@aam-e2e.test','AAM E2E synthetic commercial readiness');
  select sam.id into v_static_module_id from public.service_agreement_modules sam where sam.service_agreement_id=v_agreement_id and sam.module_key='static_guarding';
  insert into public.roster_work_units(organization_id,name,work_unit_type,service_type,service_agreement_location_id,service_agreement_module_id,created_by) values(p_provider_organization_id,'[AAM E2E] Static Site Operations','static','static_guarding',v_site_link_id,v_static_module_id,p_admin_user_id) returning id into v_work_unit_id;

  for v_index in 1..5 loop
    v_shift_type:=(array['day','swing','night','overnight','split'])[v_index];
    v_start:=(array['08:00','14:00','20:00','22:00','07:00'])[v_index]::time;
    v_end:=(array['16:00','22:00','04:00','06:00','11:00'])[v_index]::time;
    insert into public.shift_templates(organization_id,name,description,shift_type,start_time,end_time,recurrence_type,active_days,required_staff_count,site_id,is_active,effective_from,notes,created_by) values(p_provider_organization_id,'[AAM E2E] '||initcap(v_shift_type)||' Shift','Synthetic canonical '||v_shift_type||' shift template',v_shift_type,v_start,v_end,'weekly',array[1,2,3,4,5,6,7],1,v_site_id,true,current_date,'[AAM E2E] retained test template',p_admin_user_id);
  end loop;
  return jsonb_build_object('dataset','aam_e2e_20260831','account_id',v_account_id,'agreement_id',v_agreement_id,'location_id',v_location_id,'site_id',v_site_id,'work_unit_id',v_work_unit_id,'admin_user_id',p_admin_user_id,'officer_user_ids',to_jsonb(p_officer_user_ids),'active_module_count',(select count(*) from public.module_catalog where active),'operational_zones',(select jsonb_agg(jsonb_build_object('zone_id',z.id,'module_key',z.module_key) order by z.module_key) from public.location_zones z where z.location_id=v_location_id));
end;$function$;
REVOKE ALL ON FUNCTION "public"."seed_aam_e2e_dataset"(p_provider_organization_id uuid, p_owner_user_id uuid, p_admin_user_id uuid, p_admin_email text, p_officer_user_ids uuid[], p_officer_emails text[]) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."seed_aam_e2e_dataset"(p_provider_organization_id uuid, p_owner_user_id uuid, p_admin_user_id uuid, p_admin_email text, p_officer_user_ids uuid[], p_officer_emails text[]) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."seed_aam_e2e_dataset"(p_provider_organization_id uuid, p_owner_user_id uuid, p_admin_user_id uuid, p_admin_email text, p_officer_user_ids uuid[], p_officer_emails text[]) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."seed_crm_activation_handoff"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_agreement_id uuid;
  v_handoff_id uuid;
BEGIN
  IF new.status = 'activated' AND old.status IS DISTINCT FROM 'activated' THEN
    SELECT sa.id INTO v_agreement_id
    FROM public.service_agreements sa
    WHERE sa.provider_organization_id = ANY(public.get_descendant_organizations(new.provider_organization_id))
      AND sa.client_organization_id = new.account_organization_id
      AND sa.agreement_type = 'operational'
    ORDER BY sa.created_at DESC
    LIMIT 1;

    IF v_agreement_id IS NULL THEN RAISE EXCEPTION 'Accepted operational agreement required for activation handoff'; END IF;

    INSERT INTO public.crm_activation_handoffs(provider_organization_id,account_organization_id,agreement_id,onboarding_ledger_id,owner_user_id,activated_at)
    VALUES(new.provider_organization_id,new.account_organization_id,v_agreement_id,new.id,new.assigned_to,coalesce(new.activated_at,clock_timestamp()))
    ON CONFLICT(onboarding_ledger_id) DO UPDATE SET owner_user_id = excluded.owner_user_id
    RETURNING id INTO v_handoff_id;

    INSERT INTO public.crm_activation_handoff_tasks(handoff_id,task_key,title,destination)
    VALUES
      (v_handoff_id,'site_briefing','Confirm site access and safety briefing','site-360'),
      (v_handoff_id,'first_roster_action','Publish the first operational roster action','roster'),
      (v_handoff_id,'reporting_handoff','Confirm reporting delivery handoff','reports')
    ON CONFLICT(handoff_id,task_key) DO NOTHING;
  END IF;
  RETURN new;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."seed_crm_activation_handoff"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."seed_crm_activation_handoff"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."seed_crm_activation_handoff"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."seed_crm_onboarding_ledger"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_ledger public.crm_onboarding_ledgers%rowtype;
BEGIN
  IF new.organization_type IN ('client','government','private_enterprise','contractor','department') AND new.parent_organization_id IS NOT NULL AND new.status='prospect' THEN
    INSERT INTO public.crm_onboarding_ledgers(provider_organization_id,account_organization_id)
    VALUES(new.parent_organization_id,new.id)
    ON CONFLICT DO NOTHING RETURNING * INTO v_ledger;
    IF v_ledger.id IS NOT NULL THEN
      INSERT INTO public.crm_onboarding_events(ledger_id,provider_organization_id,account_organization_id,event_type,to_stage,ledger_status,note,ledger_version)
      VALUES(v_ledger.id,v_ledger.provider_organization_id,v_ledger.account_organization_id,'started',v_ledger.current_stage,v_ledger.status,'Onboarding ledger created',v_ledger.version);
    END IF;
  END IF;
  RETURN new;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."seed_crm_onboarding_ledger"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."seed_crm_onboarding_ledger"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."seed_crm_onboarding_ledger"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."seed_debrief_followup"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.safety_incident_reported or new.equipment_issue_reported or new.follow_up_required then
    insert into public.debrief_followups(organization_id,debrief_id,shift_id,officer_user_id,priority,latest_note)
    values(new.organization_id,new.id,new.shift_id,new.officer_user_id,case when new.safety_incident_reported then 'critical' when new.equipment_issue_reported then 'high' else 'normal' end,new.follow_up_notes)
    on conflict(debrief_id) do nothing;
  end if;
  return new;
end;$function$;
REVOKE ALL ON FUNCTION "public"."seed_debrief_followup"() FROM PUBLIC, "anon", "authenticated", "service_role";
