CREATE OR REPLACE FUNCTION "public"."set_cctv_import_manifest"(p_import_id uuid, p_manifest jsonb, p_status text DEFAULT NULL::text)
 RETURNS cctv_imports
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_actor uuid := auth.uid(); v_row public.cctv_imports%rowtype;
BEGIN
  SELECT * INTO v_row FROM public.cctv_imports WHERE id = p_import_id FOR UPDATE;
  IF v_row.id IS NULL THEN RAISE EXCEPTION 'CCTV import not found'; END IF;
  IF v_actor IS NULL OR NOT public.org_access_allowed(v_row.organization_id) THEN RAISE EXCEPTION 'CCTV import access denied'; END IF;
  IF jsonb_typeof(p_manifest) <> 'array' THEN RAISE EXCEPTION 'Manifest must be an array'; END IF;
  IF p_status IS NOT NULL AND p_status NOT IN ('draft', 'uploading', 'registered', 'processing', 'review_ready', 'archived', 'failed') THEN RAISE EXCEPTION 'Unknown import status %', p_status; END IF;
  UPDATE public.cctv_imports SET
    source_manifest = p_manifest,
    video_count = (SELECT count(*) FROM jsonb_array_elements(p_manifest) item WHERE item->>'kind' = 'video'),
    skipped_count = (SELECT count(*) FROM jsonb_array_elements(p_manifest) item WHERE item->>'kind' = 'skipped_empty'),
    snapshot_count = (SELECT count(*) FROM jsonb_array_elements(p_manifest) item WHERE item->>'kind' IN ('snapshot', 'photo')),
    bytes_total = (SELECT coalesce(sum((item->>'size_bytes')::bigint), 0) FROM jsonb_array_elements(p_manifest) item WHERE item->>'kind' IN ('video', 'snapshot', 'photo')),
    recorded_from = (SELECT min((item->>'slot_start_at')::timestamptz) FROM jsonb_array_elements(p_manifest) item WHERE item->>'kind' IN ('video', 'snapshot', 'photo') AND nullif(item->>'slot_start_at', '') IS NOT NULL),
    recorded_to = (SELECT max(coalesce((item->>'slot_end_at')::timestamptz, (item->>'slot_start_at')::timestamptz)) FROM jsonb_array_elements(p_manifest) item WHERE item->>'kind' IN ('video', 'snapshot', 'photo') AND nullif(item->>'slot_start_at', '') IS NOT NULL),
    status = coalesce(p_status, status)
  WHERE id = p_import_id RETURNING * INTO v_row;
  RETURN v_row;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."set_cctv_import_manifest"(p_import_id uuid, p_manifest jsonb, p_status text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."set_cctv_import_manifest"(p_import_id uuid, p_manifest jsonb, p_status text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."set_cctv_import_manifest"(p_import_id uuid, p_manifest jsonb, p_status text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."set_cctv_import_manifest"(p_import_id uuid, p_manifest jsonb, p_status text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."set_cctv_inference_budget"(p_organization_id uuid, p_daily_frame_budget integer, p_reason text DEFAULT NULL::text)
 RETURNS cctv_inference_budgets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_actor uuid := auth.uid(); v_row public.cctv_inference_budgets%rowtype; v_previous integer;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF NOT public.is_admin_for_org(p_organization_id) THEN RAISE EXCEPTION 'Only an administrator of the organisation can set its inference budget'; END IF;
  IF p_daily_frame_budget IS NULL OR p_daily_frame_budget < 100 THEN RAISE EXCEPTION 'A daily frame budget must be at least 100 frames'; END IF;
  SELECT daily_frame_budget INTO v_previous FROM public.cctv_inference_budgets WHERE organization_id = p_organization_id;
  INSERT INTO public.cctv_inference_budgets (organization_id, daily_frame_budget, reason, set_by, set_at)
  VALUES (p_organization_id, p_daily_frame_budget, nullif(trim(coalesce(p_reason, '')), ''), v_actor, clock_timestamp())
  ON CONFLICT (organization_id) DO UPDATE SET daily_frame_budget = EXCLUDED.daily_frame_budget, reason = EXCLUDED.reason, set_by = EXCLUDED.set_by, set_at = EXCLUDED.set_at
  RETURNING * INTO v_row;
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (p_organization_id, v_actor, 'cctv_inference_budget_set', 'cctv_inference_budgets', p_organization_id,
          jsonb_strip_nulls(jsonb_build_object('daily_frame_budget', p_daily_frame_budget, 'previous', v_previous, 'reason', v_row.reason)));
  RETURN v_row;
END $function$;
REVOKE ALL ON FUNCTION "public"."set_cctv_inference_budget"(p_organization_id uuid, p_daily_frame_budget integer, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."set_cctv_inference_budget"(p_organization_id uuid, p_daily_frame_budget integer, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."set_cctv_inference_budget"(p_organization_id uuid, p_daily_frame_budget integer, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."set_cctv_inference_budget"(p_organization_id uuid, p_daily_frame_budget integer, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."set_cctv_inference_policy"(p_organization_id uuid, p_cloud_vehicle_vlm_enabled boolean, p_cloud_vehicle_vlm_model text DEFAULT NULL::text, p_reason text DEFAULT NULL::text)
 RETURNS cctv_inference_policies
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_row public.cctv_inference_policies%rowtype;
  v_previous public.cctv_inference_policies%rowtype;
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
  v_model text := nullif(trim(coalesce(p_cloud_vehicle_vlm_model, '')), '');
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF NOT coalesce(public.is_admin_for_org(p_organization_id), false) THEN
    RAISE EXCEPTION 'Only an administrator of the organisation can set its CCTV inference policy';
  END IF;
  IF p_cloud_vehicle_vlm_enabled IS NULL THEN RAISE EXCEPTION 'Choose whether cloud vehicle hints are on or off'; END IF;
  IF p_cloud_vehicle_vlm_enabled AND v_reason IS NULL THEN
    RAISE EXCEPTION 'A reason is required to allow cloud vehicle hints';
  END IF;
  IF v_model IS NOT NULL AND v_model !~ '^[A-Za-z0-9][A-Za-z0-9._:/-]{0,79}$' THEN
    RAISE EXCEPTION 'The cloud model name is not valid';
  END IF;
  SELECT * INTO v_previous FROM public.cctv_inference_policies WHERE organization_id = p_organization_id FOR UPDATE;
  INSERT INTO public.cctv_inference_policies (organization_id, cloud_vehicle_vlm_enabled, cloud_vehicle_vlm_model, reason, set_by, set_at)
  VALUES (p_organization_id, p_cloud_vehicle_vlm_enabled, v_model, v_reason, v_actor, clock_timestamp())
  ON CONFLICT (organization_id) DO UPDATE
    SET cloud_vehicle_vlm_enabled = EXCLUDED.cloud_vehicle_vlm_enabled,
        cloud_vehicle_vlm_model = EXCLUDED.cloud_vehicle_vlm_model,
        reason = EXCLUDED.reason,
        set_by = EXCLUDED.set_by,
        set_at = EXCLUDED.set_at
  RETURNING * INTO v_row;
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (p_organization_id, v_actor, 'cctv_inference_policy_set', 'cctv_inference_policies', p_organization_id,
          jsonb_strip_nulls(jsonb_build_object(
            'cloud_vehicle_vlm_enabled', v_row.cloud_vehicle_vlm_enabled,
            'cloud_vehicle_vlm_model', v_row.cloud_vehicle_vlm_model,
            'previous_cloud_vehicle_vlm_enabled', v_previous.cloud_vehicle_vlm_enabled,
            'previous_cloud_vehicle_vlm_model', v_previous.cloud_vehicle_vlm_model,
            'reason', v_row.reason)));
  RETURN v_row;
END;
$function$;
COMMENT ON FUNCTION "public"."set_cctv_inference_policy"(p_organization_id uuid, p_cloud_vehicle_vlm_enabled boolean, p_cloud_vehicle_vlm_model text, p_reason text) IS 'Organisation administrators only. Turns cloud vehicle make/model hints on (reason required) or off, and writes audit_log cctv_inference_policy_set.';
REVOKE ALL ON FUNCTION "public"."set_cctv_inference_policy"(p_organization_id uuid, p_cloud_vehicle_vlm_enabled boolean, p_cloud_vehicle_vlm_model text, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."set_cctv_inference_policy"(p_organization_id uuid, p_cloud_vehicle_vlm_enabled boolean, p_cloud_vehicle_vlm_model text, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."set_cctv_inference_policy"(p_organization_id uuid, p_cloud_vehicle_vlm_enabled boolean, p_cloud_vehicle_vlm_model text, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."set_cctv_inference_policy"(p_organization_id uuid, p_cloud_vehicle_vlm_enabled boolean, p_cloud_vehicle_vlm_model text, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."set_cctv_playback_copy"(p_evidence_id uuid, p_playback jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_allowed jsonb;
BEGIN
  IF auth.role() <> 'service_role' AND session_user NOT IN ('postgres', 'supabase_admin') THEN RAISE EXCEPTION 'Service identity required'; END IF;
  IF p_playback IS NULL OR jsonb_typeof(p_playback) <> 'object' THEN RAISE EXCEPTION 'Playback details must be a JSON object'; END IF;
  -- Only the playback keys may arrive through this path; the source provenance is untouchable here.
  SELECT coalesce(jsonb_object_agg(key, value), '{}'::jsonb) INTO v_allowed
    FROM jsonb_each(p_playback)
   WHERE key IN ('playback_storage_path', 'playback_content_type', 'playback_transcode_profile', 'playback_source_codec', 'playback_source_preserved', 'playback_prepared_at');
  IF v_allowed = '{}'::jsonb THEN RAISE EXCEPTION 'No playback keys supplied'; END IF;
  UPDATE public.evidence_items
     SET metadata = metadata || v_allowed || jsonb_build_object('playback_prepared_at', coalesce(v_allowed->>'playback_prepared_at', clock_timestamp()::text))
   WHERE id = p_evidence_id;
  RETURN FOUND;
END $function$;
COMMENT ON FUNCTION "public"."set_cctv_playback_copy"(p_evidence_id uuid, p_playback jsonb) IS 'Service-only: merges the derived playback-copy keys into evidence_items.metadata (jsonb ||) so the source hash provenance recorded moments earlier is never overwritten by a stale read.';
REVOKE ALL ON FUNCTION "public"."set_cctv_playback_copy"(p_evidence_id uuid, p_playback jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."set_cctv_playback_copy"(p_evidence_id uuid, p_playback jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."set_cctv_playback_copy"(p_evidence_id uuid, p_playback jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."set_crm_quote_proposal_work_model"(p_quote_id uuid, p_module_key text, p_work_model text)
 RETURNS quote_proposal_modules
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_quote public.quotes%rowtype;
  v_module public.quote_proposal_modules%rowtype;
begin
  select * into v_quote from public.quotes where id = p_quote_id for update;
  if not found or not public.is_admin_for_org(v_quote.provider_org_id) then raise exception 'Quote not found in your organization'; end if;
  if v_quote.status <> 'draft' then raise exception 'Work model can only be changed on a draft quote'; end if;
  if p_work_model not in ('scheduled_patrol', 'scheduled_static', 'on_demand_callout', 'inspection_or_notice', 'recurring_service') then raise exception 'Unsupported proposal work model'; end if;
  update public.quote_proposal_modules set work_model = p_work_model where quote_id = v_quote.id and module_key = p_module_key returning * into v_module;
  if not found then raise exception 'Proposal module not found'; end if;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
  values(v_quote.provider_org_id,auth.uid(),'crm_quote_proposal_work_model_set','quote_proposal_modules',v_module.id,jsonb_build_object('quote_id',v_quote.id,'module_key',p_module_key,'work_model',p_work_model));
  return v_module;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."set_crm_quote_proposal_work_model"(p_quote_id uuid, p_module_key text, p_work_model text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."set_crm_quote_proposal_work_model"(p_quote_id uuid, p_module_key text, p_work_model text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."set_crm_quote_proposal_work_model"(p_quote_id uuid, p_module_key text, p_work_model text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."set_crm_quote_proposal_work_model"(p_quote_id uuid, p_module_key text, p_work_model text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."set_desktop_signing_material"(p_pfx_base64 text, p_password text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'vault'
AS $function$
DECLARE v_pfx_id uuid; v_pw_id uuid;
BEGIN
  IF auth.role() <> 'service_role' AND session_user NOT IN ('postgres', 'supabase_admin') THEN RAISE EXCEPTION 'Service identity required'; END IF;
  IF p_pfx_base64 IS NULL OR p_pfx_base64 !~ '^[A-Za-z0-9+/=\s]{200,}$' THEN RAISE EXCEPTION 'A base64-encoded PFX is required'; END IF;
  IF nullif(p_password, '') IS NULL THEN RAISE EXCEPTION 'The PFX password is required'; END IF;

  SELECT id INTO v_pfx_id FROM vault.secrets WHERE name = 'desktop_signing_pfx_base64';
  IF v_pfx_id IS NULL THEN
    v_pfx_id := vault.create_secret(regexp_replace(p_pfx_base64, '\s', '', 'g'), 'desktop_signing_pfx_base64', coalesce(p_note, 'FCM Desktop code-signing PFX (base64)'));
  ELSE
    PERFORM vault.update_secret(v_pfx_id, regexp_replace(p_pfx_base64, '\s', '', 'g'), 'desktop_signing_pfx_base64', coalesce(p_note, 'FCM Desktop code-signing PFX (base64)'));
  END IF;
  SELECT id INTO v_pw_id FROM vault.secrets WHERE name = 'desktop_signing_pfx_password';
  IF v_pw_id IS NULL THEN
    v_pw_id := vault.create_secret(p_password, 'desktop_signing_pfx_password', 'FCM Desktop code-signing PFX password');
  ELSE
    PERFORM vault.update_secret(v_pw_id, p_password, 'desktop_signing_pfx_password', 'FCM Desktop code-signing PFX password');
  END IF;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (NULL, auth.uid(), 'desktop_signing_material_set', 'vault.secrets', v_pfx_id,
          jsonb_build_object('pfx_base64_length', length(p_pfx_base64), 'session_user', session_user, 'note', p_note));
  RETURN jsonb_build_object('stored', true, 'names', jsonb_build_array('desktop_signing_pfx_base64', 'desktop_signing_pfx_password'));
END $function$;
COMMENT ON FUNCTION "public"."set_desktop_signing_material"(p_pfx_base64 text, p_password text, p_note text) IS 'Service-only: stores/rotates the FCM Desktop code-signing PFX (base64) and password in Vault under fixed names. Audited (lengths only).';
REVOKE ALL ON FUNCTION "public"."set_desktop_signing_material"(p_pfx_base64 text, p_password text, p_note text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."set_desktop_signing_material"(p_pfx_base64 text, p_password text, p_note text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."set_desktop_signing_material"(p_pfx_base64 text, p_password text, p_note text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."set_dispatch_job_billing_basis"(p_job_id uuid, p_billing_basis text, p_extra_work_order_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_job public.dispatch_jobs%rowtype;
  v_order public.agreement_extra_work_orders%rowtype;
  v_job_day date;
BEGIN
  SELECT * INTO v_job FROM public.dispatch_jobs WHERE id = p_job_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Dispatch job not found'; END IF;
  IF v_actor IS NULL OR NOT public.is_admin_for_org(v_job.organization_id) THEN
    RAISE EXCEPTION 'Not authorised to classify dispatch jobs for this organisation';
  END IF;
  IF p_billing_basis IS NULL OR p_billing_basis NOT IN ('contract', 'extra') THEN
    RAISE EXCEPTION 'Billing basis must be contract or extra';
  END IF;
  IF NOT public.agreement_uses_contract_extra(v_job.service_agreement_id) THEN
    RAISE EXCEPTION 'This agreement is billed %; Contracted work and Extra do not apply. All completed work on it is billed.',
      public.commercial_model_label(public.agreement_commercial_model(v_job.service_agreement_id));
  END IF;
  IF p_extra_work_order_id IS NOT NULL AND p_billing_basis <> 'extra' THEN
    RAISE EXCEPTION 'Only Extra jobs can sit under an Extra works order';
  END IF;
  IF v_job.billing_basis IS NOT NULL
     AND (v_job.billing_basis IS DISTINCT FROM p_billing_basis OR v_job.extra_work_order_id IS DISTINCT FROM p_extra_work_order_id)
     AND char_length(btrim(coalesce(p_reason, ''))) NOT BETWEEN 3 AND 500 THEN
    RAISE EXCEPTION 'Say why the billing basis is changing (3 to 500 characters)';
  END IF;
  IF v_job.billing_basis IS NOT DISTINCT FROM p_billing_basis AND v_job.extra_work_order_id IS NOT DISTINCT FROM p_extra_work_order_id THEN
    RETURN jsonb_build_object('job_id', v_job.id, 'billing_basis', v_job.billing_basis, 'extra_work_order_id', v_job.extra_work_order_id, 'changed', false);
  END IF;
  IF EXISTS (SELECT 1 FROM public.dispatch_job_charge_lines l WHERE l.source_dispatch_id = v_job.id AND l.invoice_line_item_id IS NOT NULL) THEN
    RAISE EXCEPTION 'This job is already invoiced; correct the billing basis through a credit note, not here';
  END IF;

  IF p_extra_work_order_id IS NOT NULL THEN
    SELECT * INTO v_order FROM public.agreement_extra_work_orders WHERE id = p_extra_work_order_id;
    IF NOT FOUND OR v_order.service_agreement_id IS DISTINCT FROM v_job.service_agreement_id THEN
      RAISE EXCEPTION 'The Extra works order must belong to the same service agreement as the job';
    END IF;
    v_job_day := (v_job.created_at AT TIME ZONE 'Pacific/Auckland')::date;
    IF v_job_day < v_order.starts_on OR (v_order.ends_on IS NOT NULL AND v_job_day > v_order.ends_on) THEN
      RAISE EXCEPTION 'Extra works order % was not in force on %', v_order.reference, to_char(v_job_day, 'DD Mon YYYY');
    END IF;
  END IF;

  PERFORM set_config('fcm.dispatch_billing_rpc', 'on', true);
  UPDATE public.dispatch_jobs
  SET billing_basis = p_billing_basis, extra_work_order_id = p_extra_work_order_id,
      billing_basis_set_at = clock_timestamp(), billing_basis_set_by = v_actor
  WHERE id = v_job.id;
  UPDATE public.dispatch_job_charge_lines
  SET billing_basis = p_billing_basis, extra_work_order_id = p_extra_work_order_id
  WHERE source_dispatch_id = v_job.id;
  PERFORM set_config('fcm.dispatch_billing_rpc', 'off', true);

  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_job.organization_id, v_actor, 'dispatch_job_billing_basis_set', 'dispatch_jobs', v_job.id,
    jsonb_strip_nulls(jsonb_build_object(
      'service_agreement_id', v_job.service_agreement_id, 'reason', nullif(btrim(p_reason), ''),
      'before', jsonb_build_object('billing_basis', v_job.billing_basis, 'extra_work_order_id', v_job.extra_work_order_id),
      'after', jsonb_build_object('billing_basis', p_billing_basis, 'extra_work_order_id', p_extra_work_order_id, 'extra_work_order_reference', v_order.reference))));
  RETURN jsonb_build_object('job_id', v_job.id, 'billing_basis', p_billing_basis, 'extra_work_order_id', p_extra_work_order_id, 'extra_work_order_reference', v_order.reference, 'changed', true);
END;
$function$;
COMMENT ON FUNCTION "public"."set_dispatch_job_billing_basis"(p_job_id uuid, p_billing_basis text, p_extra_work_order_id uuid, p_reason text) IS 'Dispatcher (provider administrator) marks a dispatch job as contracted work or Extra, optionally under an in-force Extra works order of the same agreement. Refused when the agreement commercial model is not fixed price plus Extra. Reason required to change an existing classification; audited.';
REVOKE ALL ON FUNCTION "public"."set_dispatch_job_billing_basis"(p_job_id uuid, p_billing_basis text, p_extra_work_order_id uuid, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."set_dispatch_job_billing_basis"(p_job_id uuid, p_billing_basis text, p_extra_work_order_id uuid, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."set_dispatch_job_billing_basis"(p_job_id uuid, p_billing_basis text, p_extra_work_order_id uuid, p_reason text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."set_dispatch_job_client_reference"(p_job_id uuid, p_reference text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_job public.dispatch_jobs%ROWTYPE;
  v_reference text := nullif(btrim(coalesce(p_reference, '')), '');
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
BEGIN
  SELECT * INTO v_job FROM public.dispatch_jobs WHERE id = p_job_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Dispatch job not found'; END IF;
  IF v_actor IS NULL OR NOT public.is_admin_for_org(v_job.organization_id) THEN
    RAISE EXCEPTION 'Not authorised to change dispatch jobs for this organisation';
  END IF;
  IF v_reference IS NULL THEN RAISE EXCEPTION 'Enter the client''s request or purchase-order reference'; END IF;
  IF char_length(v_reference) > 120 THEN RAISE EXCEPTION 'Reference is limited to 120 characters'; END IF;
  IF v_job.client_order_reference IS NOT DISTINCT FROM v_reference THEN
    RETURN jsonb_build_object('job_id', v_job.id, 'client_order_reference', v_reference, 'changed', false);
  END IF;
  IF v_job.client_order_reference IS NOT NULL AND char_length(coalesce(v_reason, '')) NOT BETWEEN 3 AND 500 THEN
    RAISE EXCEPTION 'Say why the client reference is changing (3 to 500 characters)';
  END IF;
  IF EXISTS (SELECT 1 FROM public.dispatch_job_charge_lines l WHERE l.source_dispatch_id = v_job.id AND l.invoice_line_item_id IS NOT NULL) THEN
    RAISE EXCEPTION 'This job is already invoiced; correct the reference on the invoice, not here';
  END IF;

  PERFORM set_config('fcm.dispatch_billing_rpc', 'on', true);
  UPDATE public.dispatch_jobs SET client_order_reference = v_reference WHERE id = v_job.id;
  PERFORM set_config('fcm.dispatch_billing_rpc', 'off', true);

  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_job.organization_id, v_actor, 'dispatch_job_client_reference_set', 'dispatch_jobs', v_job.id,
    jsonb_strip_nulls(jsonb_build_object('service_agreement_id', v_job.service_agreement_id, 'reason', v_reason,
      'before', v_job.client_order_reference, 'after', v_reference)));
  RETURN jsonb_build_object('job_id', v_job.id, 'client_order_reference', v_reference, 'changed', true);
END;
$function$;
COMMENT ON FUNCTION "public"."set_dispatch_job_client_reference"(p_job_id uuid, p_reference text, p_reason text) IS 'Dispatcher (provider administrator) records the client''s request, approval or purchase-order reference on a dispatch job. Required before invoicing on per_request agreements, and on do_and_invoice agreements when the job is over the standing authority limit. Reason required to change an existing reference; refuses invoiced jobs; audited.';
REVOKE ALL ON FUNCTION "public"."set_dispatch_job_client_reference"(p_job_id uuid, p_reference text, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."set_dispatch_job_client_reference"(p_job_id uuid, p_reference text, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."set_dispatch_job_client_reference"(p_job_id uuid, p_reference text, p_reason text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."set_dispatch_job_harmed_party"(p_client_request_id uuid, p_dispatch_job_id uuid, p_harmed_party_site_id uuid DEFAULT NULL::uuid, p_harmed_party_address text DEFAULT NULL::text, p_party_role text DEFAULT 'complainant'::text, p_display_name text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_harmed_party_lat double precision DEFAULT NULL::double precision, p_harmed_party_lng double precision DEFAULT NULL::double precision)
 RETURNS TABLE(out_dispatch_job_id uuid, out_harmed_party_site_id uuid, protected_party_recorded boolean, place_created boolean, house_action text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_org uuid;
  v_role text;
  v_job public.dispatch_jobs%rowtype;
  v_client_org uuid;
  v_site_id uuid := p_harmed_party_site_id;
  v_address text := nullif(trim(coalesce(p_harmed_party_address, '')), '');
  v_place record;
  v_place_created boolean := false;
  v_house_action text := NULL;
  v_has_identity boolean;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_client_request_id IS NULL THEN RAISE EXCEPTION 'client_request_id is required'; END IF;
  SELECT p.organization_id, p.role INTO v_org, v_role FROM public.user_profiles p WHERE p.id = v_user AND p.deactivated_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'Active profile required'; END IF;
  SELECT * INTO v_job FROM public.dispatch_jobs d WHERE d.id = p_dispatch_job_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Dispatch job not found'; END IF;
  IF NOT (public.is_admin_for_org(v_job.organization_id) OR (v_role = 'admin_officer' AND v_org = v_job.organization_id)) THEN
    RAISE EXCEPTION 'Dispatcher or administrator of the custodian organisation required';
  END IF;
  IF p_party_role NOT IN ('complainant', 'occupant', 'witness', 'landowner') THEN RAISE EXCEPTION 'Unsupported party role'; END IF;
  SELECT a.client_organization_id INTO v_client_org FROM public.service_agreements a WHERE a.id = v_job.service_agreement_id;

  IF v_site_id IS NOT NULL THEN
    -- The harmed-party site grants its owner the harmed-party read (W1), so it must be the job's client or the custodian.
    IF NOT EXISTS (SELECT 1 FROM public.client_sites cs WHERE cs.id = v_site_id
                   AND cs.client_organization_id IN (v_job.organization_id, COALESCE(v_client_org, v_job.organization_id))) THEN
      RAISE EXCEPTION 'Harmed-party site must belong to the job''s client or custodian organisation';
    END IF;
  ELSIF v_address IS NOT NULL AND p_harmed_party_lat IS NOT NULL AND p_harmed_party_lng IS NOT NULL THEN
    -- Address-only place resolved to coordinates: same pipeline as the work place. The platform's
    -- autolink trigger attaches every client-org site to its current agreement (that is what gives
    -- the custodian access to the place); site_origin = 'adhoc' marks it as not contracted.
    SELECT * INTO v_place FROM public.resolve_or_create_dispatch_place_site(
      v_job.organization_id, COALESCE(v_client_org, v_job.organization_id), v_address, v_address, p_harmed_party_lat, p_harmed_party_lng, v_user);
    v_site_id := v_place.site_id;
    v_place_created := v_place.site_created;
    v_house_action := v_place.house_action;
  END IF;

  UPDATE public.dispatch_jobs
  SET harmed_party_site_id = COALESCE(v_site_id, dispatch_jobs.harmed_party_site_id),
      harmed_party_address = COALESCE(v_address, dispatch_jobs.harmed_party_address)
  WHERE id = v_job.id;

  v_has_identity := nullif(trim(coalesce(p_display_name, '')), '') IS NOT NULL
    OR nullif(trim(coalesce(p_phone, '')), '') IS NOT NULL
    OR nullif(trim(coalesce(p_email, '')), '') IS NOT NULL
    OR nullif(trim(coalesce(p_notes, '')), '') IS NOT NULL;
  IF v_has_identity THEN
    INSERT INTO public.dispatch_job_protected_parties (organization_id, dispatch_job_id, party_role, display_name, phone, email, notes, created_by, updated_by)
    VALUES (v_job.organization_id, v_job.id, p_party_role, nullif(trim(coalesce(p_display_name, '')), ''), nullif(trim(coalesce(p_phone, '')), ''), nullif(trim(coalesce(p_email, '')), ''), nullif(trim(coalesce(p_notes, '')), ''), v_user, v_user)
    ON CONFLICT (dispatch_job_id, party_role) DO UPDATE
      SET display_name = COALESCE(EXCLUDED.display_name, dispatch_job_protected_parties.display_name),
          phone = COALESCE(EXCLUDED.phone, dispatch_job_protected_parties.phone),
          email = COALESCE(EXCLUDED.email, dispatch_job_protected_parties.email),
          notes = COALESCE(EXCLUDED.notes, dispatch_job_protected_parties.notes),
          updated_by = v_user, updated_at = now();
  END IF;

  -- Audit carries the fact of the record, never the identity values.
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_job.organization_id, v_user, 'dispatch_job_harmed_party_set', 'dispatch_jobs', v_job.id,
    jsonb_build_object('client_request_id', p_client_request_id, 'party_role', p_party_role,
      'harmed_party_site_id', v_site_id, 'identity_recorded', v_has_identity, 'place_created', v_place_created, 'house_action', v_house_action));

  RETURN QUERY SELECT v_job.id, COALESCE(v_site_id, v_job.harmed_party_site_id), v_has_identity, v_place_created, v_house_action;
END;
$function$;
COMMENT ON FUNCTION "public"."set_dispatch_job_harmed_party"(p_client_request_id uuid, p_dispatch_job_id uuid, p_harmed_party_site_id uuid, p_harmed_party_address text, p_party_role text, p_display_name text, p_phone text, p_email text, p_notes text, p_harmed_party_lat double precision, p_harmed_party_lng double precision) IS 'Dispatcher records the harmed-party place on the job (known site of the client/custodian, or an address resolved to coordinates which becomes a provisional site through resolve_or_create_dispatch_place_site) and the protected identity behind dispatch_job_protected_parties. Audited without identity values.';
REVOKE ALL ON FUNCTION "public"."set_dispatch_job_harmed_party"(p_client_request_id uuid, p_dispatch_job_id uuid, p_harmed_party_site_id uuid, p_harmed_party_address text, p_party_role text, p_display_name text, p_phone text, p_email text, p_notes text, p_harmed_party_lat double precision, p_harmed_party_lng double precision) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."set_dispatch_job_harmed_party"(p_client_request_id uuid, p_dispatch_job_id uuid, p_harmed_party_site_id uuid, p_harmed_party_address text, p_party_role text, p_display_name text, p_phone text, p_email text, p_notes text, p_harmed_party_lat double precision, p_harmed_party_lng double precision) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."set_dispatch_job_harmed_party"(p_client_request_id uuid, p_dispatch_job_id uuid, p_harmed_party_site_id uuid, p_harmed_party_address text, p_party_role text, p_display_name text, p_phone text, p_email text, p_notes text, p_harmed_party_lat double precision, p_harmed_party_lng double precision) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."set_dispatch_job_harmed_party"(p_client_request_id uuid, p_dispatch_job_id uuid, p_harmed_party_site_id uuid, p_harmed_party_address text, p_party_role text, p_display_name text, p_phone text, p_email text, p_notes text, p_harmed_party_lat double precision, p_harmed_party_lng double precision) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."set_nzta_register_lookup_outcome"(p_lookup_id uuid, p_outcome text, p_notes text DEFAULT NULL::text, p_notice_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_row public.nzta_register_lookups%rowtype;
BEGIN
  SELECT * INTO v_row FROM public.nzta_register_lookups WHERE id = p_lookup_id FOR UPDATE;
  IF v_actor IS NULL OR v_row.id IS NULL OR NOT (
       public.is_admin_for_org(v_row.organization_id)
       OR (v_row.created_by = v_actor AND public.can_access_vehicle_owner_identity(v_row.organization_id))) THEN
    RAISE EXCEPTION 'NZTA register authorisation required' USING ERRCODE = '42501';
  END IF;
  IF p_outcome IS NULL OR p_outcome NOT IN ('pending', 'trespass_notice', 'damage_letter', 'debt_collection', 'no_action') THEN
    RAISE EXCEPTION 'Choose a recognised outcome';
  END IF;
  IF p_notice_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.notices WHERE id = p_notice_id AND organization_id = v_row.organization_id) THEN
    RAISE EXCEPTION 'That notice is not in this organisation';
  END IF;
  UPDATE public.nzta_register_lookups SET outcome = p_outcome, outcome_notes = nullif(btrim(coalesce(p_notes, '')), ''),
    notice_id = coalesce(p_notice_id, notice_id), outcome_recorded_at = clock_timestamp(),
    outcome_recorded_by = v_actor, updated_at = clock_timestamp()
  WHERE id = p_lookup_id;
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_row.organization_id, v_actor, 'nzta_register_lookup_outcome_set', 'nzta_register_lookups', p_lookup_id,
    jsonb_build_object('outcome', p_outcome, 'previous_outcome', v_row.outcome));
END;
$function$;
REVOKE ALL ON FUNCTION "public"."set_nzta_register_lookup_outcome"(p_lookup_id uuid, p_outcome text, p_notes text, p_notice_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."set_nzta_register_lookup_outcome"(p_lookup_id uuid, p_outcome text, p_notes text, p_notice_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."set_nzta_register_lookup_outcome"(p_lookup_id uuid, p_outcome text, p_notes text, p_notice_id uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."set_operating_branch_module"(p_operating_organization_id uuid, p_module_key text, p_enabled boolean)
 RETURNS organization_modules
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_module public.organization_modules%rowtype;
begin
  if not public.user_can_operate_organization(p_operating_organization_id) or not public.is_admin_for_org(p_operating_organization_id) then raise exception 'Active authorized operating branch administrator required';end if;
  if not exists(select 1 from public.organizations branch where branch.id=p_operating_organization_id and branch.organization_type in ('owner','service_provider','branch') and branch.active) then raise exception 'Active operating organisation not found';end if;
  if not exists(select 1 from public.module_catalog module where module.module_key=p_module_key and module.active) then raise exception 'Active platform module required';end if;
  if p_enabled and exists(select 1 from public.organizations b where b.id=p_operating_organization_id and b.parent_organization_id is not null and not exists(select 1 from public.organization_modules pm where pm.organization_id=b.parent_organization_id and pm.module_key=p_module_key and pm.enabled)) then raise exception 'Enable this module for the organisation before enabling it for a branch';end if;
  insert into public.organization_modules(organization_id,module_key,enabled)values(p_operating_organization_id,p_module_key,p_enabled) on conflict(organization_id,module_key) do update set enabled=excluded.enabled returning * into v_module;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)values(p_operating_organization_id,v_actor,'operating_branch_module_set','organization_modules',v_module.id,jsonb_build_object('module_key',v_module.module_key,'enabled',v_module.enabled));return v_module;
end;$function$;
REVOKE ALL ON FUNCTION "public"."set_operating_branch_module"(p_operating_organization_id uuid, p_module_key text, p_enabled boolean) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."set_operating_branch_module"(p_operating_organization_id uuid, p_module_key text, p_enabled boolean) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."set_operating_branch_module"(p_operating_organization_id uuid, p_module_key text, p_enabled boolean) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."set_operating_branch_module"(p_operating_organization_id uuid, p_module_key text, p_enabled boolean) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."set_org_jurisdiction_geom"(p_org_id uuid, p_polygons jsonb, p_boundary_source text DEFAULT NULL::text, p_changed_by uuid DEFAULT NULL::uuid, p_changed_via text DEFAULT 'governed_proposal'::text)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_geom geometry;
BEGIN
  IF p_polygons IS NULL OR jsonb_typeof(p_polygons) <> 'array' OR jsonb_array_length(p_polygons) = 0 THEN
    RAISE EXCEPTION 'p_polygons must be a non-empty JSON array of GeoJSON geometries';
  END IF;
  SELECT st_union(st_makevalid(st_geomfromgeojson(elem.value)))
    INTO v_geom
    FROM jsonb_array_elements(p_polygons) AS elem;
  RETURN public._write_org_jurisdiction_geom(p_org_id, v_geom, p_boundary_source, p_changed_by, p_changed_via);
END;
$function$;
COMMENT ON FUNCTION "public"."set_org_jurisdiction_geom"(p_org_id uuid, p_polygons jsonb, p_boundary_source text, p_changed_by uuid, p_changed_via text) IS 'Writes organizations.jurisdiction_geom by ST_Union-ing an array of GeoJSON polygons into one MultiPolygon(4326) with ST_MakeValid. Returns the written area in m^2. Records a history row in geofence_boundary_history with real provenance. Phase 1+4 geofence redesign (#226).';
REVOKE ALL ON FUNCTION "public"."set_org_jurisdiction_geom"(p_org_id uuid, p_polygons jsonb, p_boundary_source text, p_changed_by uuid, p_changed_via text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."set_org_jurisdiction_geom"(p_org_id uuid, p_polygons jsonb, p_boundary_source text, p_changed_by uuid, p_changed_via text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."set_org_jurisdiction_geom"(p_org_id uuid, p_polygons jsonb, p_boundary_source text, p_changed_by uuid, p_changed_via text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."set_organization_calendar_region"(p_organization_id uuid, p_region_code text)
 RETURNS organization_calendar_settings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_row public.organization_calendar_settings%rowtype;v_region text:=nullif(upper(trim(coalesce(p_region_code,''))), '');
begin
  if not public.is_admin_for_org(p_organization_id) then raise exception 'Not authorised to configure this organization calendar';end if;
  if v_region is not null and v_region not in('AUK','BOP','CAN','CIT','GIS','HKB','MBH','MWT','NSN','NTL','OTA','STL','TAS','TKI','WKO','WGN','WTC') then raise exception 'Unsupported New Zealand holiday region';end if;
  insert into public.organization_calendar_settings(organization_id,region_code,updated_by) values(p_organization_id,v_region,v_actor)
  on conflict(organization_id) do update set region_code=excluded.region_code,updated_by=v_actor,updated_at=clock_timestamp()
  returning * into v_row;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(p_organization_id,v_actor,'organization_calendar_region_set','organization_calendar_settings',p_organization_id,jsonb_build_object('country_code','NZ','region_code',v_region));
  return v_row;
end;$function$;
REVOKE ALL ON FUNCTION "public"."set_organization_calendar_region"(p_organization_id uuid, p_region_code text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."set_organization_calendar_region"(p_organization_id uuid, p_region_code text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."set_organization_calendar_region"(p_organization_id uuid, p_region_code text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."set_organization_calendar_region"(p_organization_id uuid, p_region_code text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."set_organization_module_subscription"(p_organization_id uuid, p_module_key text, p_enabled boolean)
 RETURNS organization_modules
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_module public.organization_modules%rowtype;
BEGIN
  IF v_actor IS NULL OR NOT public.is_admin_for_org(p_organization_id) THEN
    RAISE EXCEPTION 'Active organisation administrator required';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.module_catalog module WHERE module.module_key = p_module_key AND module.active) THEN
    RAISE EXCEPTION 'Active platform module required';
  END IF;

  INSERT INTO public.organization_modules (organization_id, module_key, enabled)
  VALUES (p_organization_id, p_module_key, p_enabled)
  ON CONFLICT (organization_id, module_key) DO UPDATE SET enabled = excluded.enabled
  RETURNING * INTO v_module;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (p_organization_id, v_actor, 'organization_module_subscription_set', 'organization_modules', v_module.id, jsonb_build_object('module_key', v_module.module_key, 'enabled', v_module.enabled));

  RETURN v_module;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."set_organization_module_subscription"(p_organization_id uuid, p_module_key text, p_enabled boolean) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."set_organization_module_subscription"(p_organization_id uuid, p_module_key text, p_enabled boolean) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."set_organization_module_subscription"(p_organization_id uuid, p_module_key text, p_enabled boolean) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."set_organization_module_subscription"(p_organization_id uuid, p_module_key text, p_enabled boolean) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."set_patrol_route_primary_officer"(p_route_id uuid, p_staff_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_route public.patrol_routes%rowtype;
  v_receipt jsonb;
begin
  select * into v_route from public.patrol_routes where id = p_route_id for update;
  if not found then raise exception 'Patrol route not found'; end if;
  if v_actor is null or not public.is_admin_for_org(v_route.organization_id) then
    raise exception 'Not authorised to change the primary officer for this route';
  end if;
  if length(trim(coalesce(p_reason, ''))) < 3 then
    raise exception 'A reason is required to change the primary officer';
  end if;
  if p_staff_id is not null and not exists (
    select 1 from public.staff_profiles where id = p_staff_id and organization_id = v_route.organization_id
  ) then
    raise exception 'The primary officer must be a staff member of this organisation';
  end if;

  update public.patrol_routes set primary_staff_id = p_staff_id where id = p_route_id;
  v_receipt := jsonb_build_object('route_id', p_route_id, 'route_code', v_route.route_code,
    'previous_staff_id', v_route.primary_staff_id, 'staff_id', p_staff_id, 'reason', trim(p_reason));
  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (v_route.organization_id, v_actor, 'patrol_route_primary_officer_set', 'patrol_routes', p_route_id, v_receipt);
  return v_receipt;
end;
$function$;
COMMENT ON FUNCTION "public"."set_patrol_route_primary_officer"(p_route_id uuid, p_staff_id uuid, p_reason text) IS 'Admin-only, audited change of the usual officer for a patrol route.';
REVOKE ALL ON FUNCTION "public"."set_patrol_route_primary_officer"(p_route_id uuid, p_staff_id uuid, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."set_patrol_route_primary_officer"(p_route_id uuid, p_staff_id uuid, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."set_patrol_route_primary_officer"(p_route_id uuid, p_staff_id uuid, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."set_patrol_route_primary_officer"(p_route_id uuid, p_staff_id uuid, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."set_person_search_access"(p_user_id uuid, p_enabled boolean, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_target public.user_profiles%rowtype;
  v_grant_id uuid;
BEGIN
  SELECT * INTO v_target FROM public.user_profiles WHERE id = p_user_id FOR UPDATE;
  IF v_target.id IS NULL OR auth.uid() IS NULL
     OR NOT public.is_admin_for_org(v_target.organization_id) THEN
    RAISE EXCEPTION 'Organisation administrator required' USING ERRCODE = '42501';
  END IF;
  IF p_user_id = auth.uid() THEN RAISE EXCEPTION 'You cannot change your own person-search authorization'; END IF;
  IF v_target.role = 'grand_master' THEN RAISE EXCEPTION 'Grand master access is not configurable here'; END IF;
  IF p_enabled IS NULL THEN RAISE EXCEPTION 'An enabled or disabled choice is required'; END IF;
  IF nullif(trim(p_reason), '') IS NULL THEN RAISE EXCEPTION 'A reason is required for the access audit trail'; END IF;
  IF p_enabled AND v_target.deactivated_at IS NOT NULL THEN RAISE EXCEPTION 'Cannot enable an inactive user'; END IF;
  IF p_enabled THEN
    INSERT INTO public.staff_area_grants(user_id, scope_org_id, area, level, status, granted_by)
    VALUES(p_user_id, v_target.organization_id, 'person_search', 'view', 'active', auth.uid())
    ON CONFLICT(user_id, scope_org_id, area)
    DO UPDATE SET level = 'view', status = 'active', granted_by = auth.uid(), updated_at = clock_timestamp()
    RETURNING id INTO v_grant_id;
  ELSE
    UPDATE public.staff_area_grants SET status = 'ended', updated_at = clock_timestamp()
    WHERE user_id = p_user_id AND scope_org_id = v_target.organization_id
      AND area = 'person_search' AND status = 'active'
    RETURNING id INTO v_grant_id;
  END IF;
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES(v_target.organization_id, auth.uid(),
    CASE WHEN p_enabled THEN 'person_search_access_granted' ELSE 'person_search_access_ended' END,
    'staff_area_grants', v_grant_id,
    jsonb_build_object('user_id', p_user_id, 'area', 'person_search', 'level', 'view', 'reason', trim(p_reason)));
  RETURN public.get_person_search_access(p_user_id);
END;
$function$;
REVOKE ALL ON FUNCTION "public"."set_person_search_access"(p_user_id uuid, p_enabled boolean, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."set_person_search_access"(p_user_id uuid, p_enabled boolean, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."set_person_search_access"(p_user_id uuid, p_enabled boolean, p_reason text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."set_report_incident_triage"(p_pack_id uuid, p_line_key text, p_decision text, p_incident_type text DEFAULT NULL::text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_pack record;
  v_row public.report_incident_triage%rowtype;
  v_previous text;
  v_previous_type text;
  v_line_date date;
  v_stale_pdfs integer := 0;
  v_sent_packs uuid[];
  v_changes boolean;
  v_type text := nullif(btrim(coalesce(p_incident_type, '')), '');
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
begin
  if v_actor is null then
    raise exception 'Authenticated provider administrator required';
  end if;
  if p_decision not in ('unreviewed', 'incident', 'not_incident') then
    raise exception 'Decision must be unreviewed, incident or not_incident';
  end if;
  if length(coalesce(v_note, '')) > 1000 then
    raise exception 'Review note exceeds 1000 characters';
  end if;
  if p_decision <> 'incident' then
    v_type := null;
  end if;

  select pack.id, pack.organization_id, pack.service_agreement_id, pack.period_start, pack.period_end, pack.status
  into v_pack
  from public.monthly_report_packs pack
  where pack.id = p_pack_id;
  if v_pack.id is null then
    raise exception 'Report pack not found';
  end if;
  if not public.is_report_provider_custodian_for_org(v_pack.organization_id) then
    raise exception 'Provider administrator access required';
  end if;

  select t.decision, t.incident_type, t.line_date into v_previous, v_previous_type, v_line_date
  from public.report_incident_triage t
  where t.service_agreement_id = v_pack.service_agreement_id
    and t.line_key = p_line_key
    and t.line_date between v_pack.period_start and v_pack.period_end
  for update;
  if not found then
    raise exception 'That entry has not been checked by Bob for this report';
  end if;
  -- New evidence can escalate or clear an entry after a report has been sent.
  -- The sent pack stays exactly as delivered; the change is a recorded
  -- reclassification and must carry the reason for it.
  select coalesce(array_agg(sent.id order by sent.period_start, sent.id), '{}')
  into v_sent_packs
  from public.monthly_report_packs sent
  where sent.service_agreement_id = v_pack.service_agreement_id
    and sent.status = 'sent'
    and v_line_date between sent.period_start and sent.period_end;
  v_changes := (p_decision, case when p_decision = 'incident' then coalesce(v_type, v_previous_type) end)
    is distinct from (v_previous, case when v_previous = 'incident' then v_previous_type end);
  if cardinality(v_sent_packs) > 0 and v_changes and length(coalesce(v_note, '')) < 10 then
    raise exception 'This entry was in a report already sent to the client. Record the reason or new evidence for the change (at least 10 characters).';
  end if;

  update public.report_incident_triage t
  set decision = p_decision,
      incident_type = case when p_decision = 'incident' then coalesce(v_type, t.bob_incident_type, 'other') end,
      decision_note = case when p_decision = 'unreviewed' then null else v_note end,
      decided_by = case when p_decision = 'unreviewed' then null else v_actor end,
      decided_at = case when p_decision = 'unreviewed' then null else clock_timestamp() end,
      updated_at = clock_timestamp()
  where t.service_agreement_id = v_pack.service_agreement_id
    and t.line_key = p_line_key
  returning * into v_row;

  -- The decision changes what the client report shows, so any PDF already
  -- generated for an unsent pack covering this entry is no longer current and
  -- must be generated again before sending. The pack trigger refuses this
  -- while an email delivery is in progress.
  update public.monthly_report_packs pack
  set pdf_source_updated_at = null
  where pack.service_agreement_id = v_pack.service_agreement_id
    and pack.status in ('draft', 'generated')
    and v_line_date between pack.period_start and pack.period_end
    and pack.pdf_source_updated_at is not null
    and (v_row.decision, v_row.incident_type) is distinct from (v_previous, v_previous_type);
  get diagnostics v_stale_pdfs = row_count;

  insert into public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (
    v_pack.organization_id,
    v_actor,
    'report_incident_triage_decided',
    'report_incident_triage',
    v_row.id,
    jsonb_build_object(
      'pack_id', v_pack.id,
      'line_key', v_row.line_key,
      'previous_decision', v_previous,
      'decision', v_row.decision,
      'incident_type', v_row.incident_type,
      'bob_flagged', v_row.bob_flagged,
      'bob_incident_type', v_row.bob_incident_type,
      'pdfs_invalidated', v_stale_pdfs,
      'after_delivery', cardinality(v_sent_packs) > 0,
      'sent_pack_ids', to_jsonb(v_sent_packs),
      'reason', case when cardinality(v_sent_packs) > 0 then v_note end
    )
  );

  return jsonb_build_object(
    'line_key', v_row.line_key,
    'bob_flagged', v_row.bob_flagged,
    'bob_incident_type', v_row.bob_incident_type,
    'bob_reason', v_row.bob_reason,
    'bob_confidence', v_row.bob_confidence,
    'bob_assessed_at', v_row.bob_assessed_at,
    'decision', v_row.decision,
    'incident_type', v_row.incident_type,
    'decision_note', v_row.decision_note,
    'decided_at', v_row.decided_at,
    'pdf_needs_regenerating', v_stale_pdfs > 0,
    'in_sent_report', cardinality(v_sent_packs) > 0
  );
end;
$function$;
COMMENT ON FUNCTION "public"."set_report_incident_triage"(p_pack_id uuid, p_line_key text, p_decision text, p_incident_type text, p_note text) IS 'Records a provider reviewer''s decision on an activity line Bob has checked: unreviewed, incident (with a type) or not_incident. Report provider custodians only, from any pack covering the entry. When a sent pack already covers the entry, a changed decision needs a reason of at least 10 characters and is audited as after_delivery with the sent pack ids; sent packs are never changed. A changed decision clears pdf_source_updated_at on unsent packs covering the entry so their PDF must be generated again; writes an audit_log receipt.';
REVOKE ALL ON FUNCTION "public"."set_report_incident_triage"(p_pack_id uuid, p_line_key text, p_decision text, p_incident_type text, p_note text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."set_report_incident_triage"(p_pack_id uuid, p_line_key text, p_decision text, p_incident_type text, p_note text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."set_report_incident_triage"(p_pack_id uuid, p_line_key text, p_decision text, p_incident_type text, p_note text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."set_roster_slot_break"(p_slot_id uuid, p_expected_status text, p_planned_break_minutes integer, p_break_unpaid boolean)
 RETURNS roster_slots
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_slot public.roster_slots%rowtype;
begin
  select * into v_slot from public.roster_slots where id = p_slot_id for update;
  if not found or auth.uid() is null or not public.is_admin_for_org(v_slot.organization_id) then
    raise exception 'Roster administrator required' using errcode = '42501';
  end if;
  if not exists (select 1 from public.user_profiles where id = auth.uid() and deactivated_at is null) then
    raise exception 'Active administrator required' using errcode = '42501';
  end if;
  if v_slot.status is distinct from p_expected_status or v_slot.status <> 'draft' then
    raise exception 'Only an unchanged draft can have its break plan edited';
  end if;
  if p_planned_break_minutes is null or p_break_unpaid is null then raise exception 'Break settings are required'; end if;
  update public.roster_slots set planned_break_minutes = p_planned_break_minutes,
    break_unpaid = p_break_unpaid, updated_at = clock_timestamp() where id = v_slot.id returning * into v_slot;
  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values(v_slot.organization_id, auth.uid(), 'roster_break_planned', 'roster_slots', v_slot.id,
    jsonb_build_object('planned_break_minutes', p_planned_break_minutes, 'unpaid', p_break_unpaid));
  return v_slot;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."set_roster_slot_break"(p_slot_id uuid, p_expected_status text, p_planned_break_minutes integer, p_break_unpaid boolean) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."set_roster_slot_break"(p_slot_id uuid, p_expected_status text, p_planned_break_minutes integer, p_break_unpaid boolean) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."set_roster_slot_break"(p_slot_id uuid, p_expected_status text, p_planned_break_minutes integer, p_break_unpaid boolean) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."set_site_geometry"(p_site_id uuid, p_boundary jsonb DEFAULT NULL::jsonb, p_center_lat double precision DEFAULT NULL::double precision, p_center_lng double precision DEFAULT NULL::double precision, p_provisional_radius_m double precision DEFAULT 50, p_boundary_source text DEFAULT NULL::text, p_changed_by uuid DEFAULT NULL::uuid, p_changed_via text DEFAULT 'governed_proposal'::text)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_boundary   geometry;
  v_center     geometry;
  v_area_m2    numeric;
  v_source     text;
  v_via        text;
BEGIN
  IF p_boundary IS NOT NULL THEN
    v_boundary := st_makevalid(st_setsrid(st_geomfromgeojson(p_boundary::text), 4326));
    IF v_boundary IS NULL THEN
      RAISE EXCEPTION 'set_site_geometry: could not build geometry from p_boundary GeoJSON';
    END IF;
    IF geometrytype(v_boundary) <> 'POLYGON' THEN
      v_boundary := st_convexhull(v_boundary);
    END IF;
    -- Polygon path: use caller-supplied source, else 'UNKNOWN_SOURCE' (P1).
    v_source := COALESCE(NULLIF(TRIM(p_boundary_source), ''), 'UNKNOWN_SOURCE');
  ELSIF p_center_lat IS NOT NULL AND p_center_lng IS NOT NULL THEN
    v_boundary := st_setsrid(
      st_buffer(
        st_setsrid(st_makepoint(p_center_lng, p_center_lat), 4326)::geography,
        greatest(coalesce(p_provisional_radius_m, 50), 1)
      )::geometry,
      4326
    );
    IF geometrytype(v_boundary) <> 'POLYGON' THEN
      v_boundary := st_convexhull(v_boundary);
    END IF;
    -- Point-radius path: source is always 'point_radius' regardless of caller.
    v_source := 'point_radius';
  ELSE
    RAISE EXCEPTION 'set_site_geometry: supply either p_boundary (GeoJSON polygon) or p_center_lat + p_center_lng (provisional point)';
  END IF;

  v_center  := st_centroid(v_boundary);
  v_area_m2 := st_area(v_boundary::geography);

  UPDATE public.client_sites
     SET boundary     = v_boundary,
         center_point = v_center
   WHERE id = p_site_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'set_site_geometry: site % not found', p_site_id;
  END IF;

  -- Resolve changed_via: validate against the CHECK constraint values.
  v_via := CASE
    WHEN p_changed_via IN ('governed_proposal', 'direct_edit', 'reconciliation', 'refresh', 'verification', 'backfill')
    THEN p_changed_via
    ELSE 'governed_proposal'
  END;

  -- Record history
  INSERT INTO public.geofence_boundary_history (
    entity_type, entity_id, boundary, boundary_source,
    verification_state, verified_by, verified_at,
    changed_by, changed_via, change_reason, version
  ) VALUES (
    'client_site', p_site_id, v_boundary, v_source,
    'unverified', NULL, NULL,
    p_changed_by, v_via, 'Site geometry set via set_site_geometry',
    public._gbh_next_version('client_site', p_site_id)
  );

  RETURN v_area_m2;
END;
$function$;
COMMENT ON FUNCTION "public"."set_site_geometry"(p_site_id uuid, p_boundary jsonb, p_center_lat double precision, p_center_lng double precision, p_provisional_radius_m double precision, p_boundary_source text, p_changed_by uuid, p_changed_via text) IS 'Writes client_sites.boundary (GeoJSON polygon with ST_MakeValid, or a buffered provisional point) and center_point = ST_Centroid(boundary). Returns area in m^2. Records a history row with real provenance. Phase 1+4 geofence redesign (#226).';
REVOKE ALL ON FUNCTION "public"."set_site_geometry"(p_site_id uuid, p_boundary jsonb, p_center_lat double precision, p_center_lng double precision, p_provisional_radius_m double precision, p_boundary_source text, p_changed_by uuid, p_changed_via text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."set_site_geometry"(p_site_id uuid, p_boundary jsonb, p_center_lat double precision, p_center_lng double precision, p_provisional_radius_m double precision, p_boundary_source text, p_changed_by uuid, p_changed_via text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."set_site_geometry"(p_site_id uuid, p_boundary jsonb, p_center_lat double precision, p_center_lng double precision, p_provisional_radius_m double precision, p_boundary_source text, p_changed_by uuid, p_changed_via text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."set_staff_employment_setup"(p_staff_id uuid, p_expected_employment_type text, p_expected_start_date date, p_expected_end_date date, p_expected_role_code text, p_employment_type text, p_start_date date, p_end_date date DEFAULT NULL::date, p_role_code text DEFAULT NULL::text, p_reason text DEFAULT NULL::text)
 RETURNS staff_profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_staff public.staff_profiles%rowtype;
  v_employment_type text := nullif(trim(coalesce(p_employment_type, '')), '');
  v_role_code text := nullif(trim(coalesce(p_role_code, '')), '');
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
  v_previous jsonb;
BEGIN
  SELECT *
  INTO v_staff
  FROM public.staff_profiles
  WHERE id = p_staff_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Staff profile not found';
  END IF;
  IF NOT public.is_admin_for_org(v_staff.organization_id) THEN
    RAISE EXCEPTION 'Not authorised to manage staff employment';
  END IF;
  IF v_staff.employment_type IS DISTINCT FROM nullif(trim(coalesce(p_expected_employment_type, '')), '')
    OR v_staff.start_date IS DISTINCT FROM p_expected_start_date
    OR v_staff.end_date IS DISTINCT FROM p_expected_end_date
    OR v_staff.role_code IS DISTINCT FROM nullif(trim(coalesce(p_expected_role_code, '')), '') THEN
    RAISE EXCEPTION 'Staff employment changed; reload before saving';
  END IF;
  IF v_employment_type NOT IN ('permanent', 'part_time', 'casual', 'contractor', 'volunteer') THEN
    RAISE EXCEPTION 'A supported employment type is required';
  END IF;
  IF p_start_date IS NULL THEN
    RAISE EXCEPTION 'Employment start date is required';
  END IF;
  IF p_end_date IS NOT NULL AND p_end_date < p_start_date THEN
    RAISE EXCEPTION 'Employment end date cannot precede the start date';
  END IF;
  IF v_role_code IS NULL OR NOT EXISTS (
    SELECT 1
    FROM public.reference_codes code
    WHERE code.organization_id = v_staff.organization_id
      AND code.code_type = 'role_code'
      AND code.code = v_role_code
      AND code.is_active
  ) THEN
    RAISE EXCEPTION 'An active organization payroll role is required';
  END IF;
  IF v_reason IS NULL THEN
    RAISE EXCEPTION 'Employment setup reason is required';
  END IF;

  v_previous := jsonb_build_object(
    'employment_type', v_staff.employment_type,
    'start_date', v_staff.start_date,
    'end_date', v_staff.end_date,
    'role_code', v_staff.role_code
  );

  UPDATE public.staff_profiles
  SET employment_type = v_employment_type,
      start_date = p_start_date,
      end_date = p_end_date,
      role_code = v_role_code
  WHERE id = v_staff.id
  RETURNING * INTO v_staff;

  INSERT INTO public.audit_log(
    organization_id,
    actor_user_id,
    action,
    target_table,
    target_id,
    metadata
  )
  VALUES (
    v_staff.organization_id,
    v_actor,
    'staff_employment_setup_saved',
    'staff_profiles',
    v_staff.id,
    jsonb_build_object(
      'previous', v_previous,
      'current', jsonb_build_object(
        'employment_type', v_staff.employment_type,
        'start_date', v_staff.start_date,
        'end_date', v_staff.end_date,
        'role_code', v_staff.role_code
      ),
      'reason', v_reason
    )
  );

  RETURN v_staff;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."set_staff_employment_setup"(p_staff_id uuid, p_expected_employment_type text, p_expected_start_date date, p_expected_end_date date, p_expected_role_code text, p_employment_type text, p_start_date date, p_end_date date, p_role_code text, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."set_staff_employment_setup"(p_staff_id uuid, p_expected_employment_type text, p_expected_start_date date, p_expected_end_date date, p_expected_role_code text, p_employment_type text, p_start_date date, p_end_date date, p_role_code text, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."set_staff_employment_setup"(p_staff_id uuid, p_expected_employment_type text, p_expected_start_date date, p_expected_end_date date, p_expected_role_code text, p_employment_type text, p_start_date date, p_end_date date, p_role_code text, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."set_staff_employment_setup"(p_staff_id uuid, p_expected_employment_type text, p_expected_start_date date, p_expected_end_date date, p_expected_role_code text, p_employment_type text, p_start_date date, p_end_date date, p_role_code text, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."set_staff_pay_role_code"(p_staff_id uuid, p_expected_role_code text, p_role_code text DEFAULT NULL::text)
 RETURNS staff_profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_staff public.staff_profiles%rowtype;
  v_role_code text := nullif(trim(coalesce(p_role_code, '')), '');
begin
  select * into v_staff from public.staff_profiles where id = p_staff_id for update;
  if not found then raise exception 'Staff profile not found'; end if;
  if not public.is_admin_for_org(v_staff.organization_id) then raise exception 'Not authorised to set staff pay role'; end if;
  if v_staff.role_code is distinct from nullif(trim(coalesce(p_expected_role_code, '')), '') then raise exception 'Staff pay role changed; reload before saving'; end if;
  if v_role_code is not null and not exists (
    select 1 from public.reference_codes code
    where code.organization_id = v_staff.organization_id
      and code.code_type = 'role_code'
      and code.code = v_role_code
      and code.is_active
  ) then
    raise exception 'Pay role code must be an active organization role code';
  end if;

  update public.staff_profiles set role_code = v_role_code where id = v_staff.id returning * into v_staff;
  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (v_staff.organization_id, v_actor, 'staff_pay_role_set', 'staff_profiles', v_staff.id,
    jsonb_build_object('previous_role_code', nullif(trim(coalesce(p_expected_role_code, '')), ''), 'role_code', v_role_code));
  return v_staff;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."set_staff_pay_role_code"(p_staff_id uuid, p_expected_role_code text, p_role_code text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."set_staff_pay_role_code"(p_staff_id uuid, p_expected_role_code text, p_role_code text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."set_staff_pay_role_code"(p_staff_id uuid, p_expected_role_code text, p_role_code text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."set_staff_pay_role_code"(p_staff_id uuid, p_expected_role_code text, p_role_code text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."set_staff_work_readiness"(p_staff_id uuid, p_expected_work_ready boolean, p_work_ready boolean, p_review_notes text)
 RETURNS staff_profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_staff public.staff_profiles%rowtype;v_assessment record;v_notes text:=nullif(trim(coalesce(p_review_notes,'')),'');
begin
  select sp.* into v_staff from public.staff_profiles sp where sp.id=p_staff_id for update;if not found then raise exception 'Staff profile not found';end if;
  if not public.is_admin_for_org(v_staff.organization_id) then raise exception 'Not authorised to change staff readiness';end if;
  if v_staff.work_ready<>p_expected_work_ready then raise exception 'Staff readiness changed from expected state';end if;
  if v_staff.work_ready=p_work_ready then raise exception 'Staff readiness is already in the requested state';end if;
  if v_notes is null then raise exception 'Readiness review notes are required';end if;
  if p_work_ready then
    select * into v_assessment from public.get_staff_readiness_assessment(v_staff.organization_id) a where a.staff_id=v_staff.id;
    if coalesce(array_length(v_assessment.blockers,1),0)>0 then raise exception 'Staff member is not work ready: %',array_to_string(v_assessment.blockers,'; ');end if;
  end if;
  update public.staff_profiles sp set work_ready=p_work_ready,work_ready_reviewed_by=v_actor,work_ready_reviewed_at=clock_timestamp(),work_ready_review_notes=v_notes where sp.id=v_staff.id returning sp.* into v_staff;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)values(v_staff.organization_id,v_actor,case when p_work_ready then 'staff_work_ready_enabled' else 'staff_work_ready_disabled' end,'staff_profiles',v_staff.id,jsonb_build_object('previous_work_ready',p_expected_work_ready,'work_ready',p_work_ready,'review_notes',v_notes));
  return v_staff;
end;$function$;
REVOKE ALL ON FUNCTION "public"."set_staff_work_readiness"(p_staff_id uuid, p_expected_work_ready boolean, p_work_ready boolean, p_review_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."set_staff_work_readiness"(p_staff_id uuid, p_expected_work_ready boolean, p_work_ready boolean, p_review_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."set_staff_work_readiness"(p_staff_id uuid, p_expected_work_ready boolean, p_work_ready boolean, p_review_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."set_staff_work_readiness"(p_staff_id uuid, p_expected_work_ready boolean, p_work_ready boolean, p_review_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."set_user_deactivation"(p_target_user_id uuid, p_action text, p_reason text DEFAULT NULL::text)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor public.user_profiles%ROWTYPE;
  v_target public.user_profiles%ROWTYPE;
  v_new_deactivated_at timestamptz;
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  v_sessions_revoked integer;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication is required';
  END IF;
  IF p_target_user_id IS NULL OR p_action IS NULL OR p_action NOT IN ('deactivate', 'reactivate') THEN
    RAISE EXCEPTION 'A target user and valid action are required';
  END IF;

  SELECT p.*
  INTO v_actor
  FROM public.user_profiles p
  WHERE p.id = auth.uid()
    AND p.deactivated_at IS NULL
  FOR UPDATE;

  IF NOT FOUND OR v_actor.role NOT IN ('grand_master', 'master', 'admin', 'admin_officer', 'client_admin') THEN
    RAISE EXCEPTION 'Active user administrator required';
  END IF;

  SELECT p.*
  INTO v_target
  FROM public.user_profiles p
  WHERE p.id = p_target_user_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Target user not found';
  END IF;
  IF v_actor.role <> 'grand_master' AND v_target.organization_id IS DISTINCT FROM v_actor.organization_id THEN
    RAISE EXCEPTION 'Cannot manage users from other organizations';
  END IF;
  IF v_actor.role = 'client_admin' AND left(v_target.role, 7) <> 'client_' THEN
    RAISE EXCEPTION 'A client administrator can only manage client users';
  END IF;
  IF v_target.id = v_actor.id THEN
    RAISE EXCEPTION 'Cannot deactivate your own account';
  END IF;
  IF v_target.role = 'grand_master' AND v_actor.role <> 'grand_master' THEN
    RAISE EXCEPTION 'Cannot deactivate grand master users';
  END IF;
  IF p_action = 'deactivate' AND v_target.deactivated_at IS NOT NULL THEN
    RAISE EXCEPTION 'User is already deactivated';
  END IF;
  IF p_action = 'reactivate' AND v_target.deactivated_at IS NULL THEN
    RAISE EXCEPTION 'User is already active';
  END IF;

  v_new_deactivated_at := CASE
    WHEN p_action = 'deactivate' THEN clock_timestamp()
    ELSE NULL
  END;

  UPDATE public.user_profiles
  SET deactivated_at = v_new_deactivated_at,
      deactivated_by = CASE WHEN v_new_deactivated_at IS NULL THEN NULL ELSE v_actor.id END,
      updated_at = clock_timestamp()
  WHERE id = v_target.id;

  -- A ban stops sign-in and refresh; deleting sessions makes Auth reject access tokens already issued.
  IF p_action = 'deactivate' THEN
    UPDATE auth.users
    SET banned_until = clock_timestamp() + interval '100 years'
    WHERE id = v_target.id;

    DELETE FROM auth.sessions
    WHERE user_id = v_target.id;
    GET DIAGNOSTICS v_sessions_revoked = ROW_COUNT;
  ELSE
    UPDATE auth.users
    SET banned_until = NULL
    WHERE id = v_target.id;
  END IF;

  -- user_management_audit keys its target to auth.users; roster-only profiles are audited in audit_log.
  IF EXISTS (SELECT 1 FROM auth.users au WHERE au.id = v_target.id) THEN
    PERFORM public.log_user_management_action(
      v_target.organization_id,
      v_target.id,
      CASE WHEN p_action = 'deactivate' THEN 'user_deactivated' ELSE 'user_reactivated' END,
      v_actor.id,
      jsonb_build_object('role', v_target.role, 'deactivated_at', v_target.deactivated_at),
      jsonb_build_object('role', v_target.role, 'deactivated_at', v_new_deactivated_at),
      jsonb_strip_nulls(jsonb_build_object(
        'display_name', v_target.display_name,
        'role', v_target.role,
        'reason', v_reason,
        'auth_sessions_revoked', v_sessions_revoked
      ))
    );
  ELSE
    INSERT INTO public.audit_log (
      organization_id, actor_user_id, action, target_table, target_id, metadata
    )
    VALUES (
      v_target.organization_id,
      v_actor.id,
      CASE WHEN p_action = 'deactivate' THEN 'user_deactivated' ELSE 'user_reactivated' END,
      'user_profiles',
      v_target.id,
      jsonb_strip_nulls(jsonb_build_object(
        'display_name', v_target.display_name,
        'role', v_target.role,
        'reason', v_reason,
        'previous_deactivated_at', v_target.deactivated_at,
        'deactivated_at', v_new_deactivated_at,
        'auth_account', 'absent'
      ))
    );
  END IF;

  RETURN v_new_deactivated_at;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."set_user_deactivation"(p_target_user_id uuid, p_action text, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."set_user_deactivation"(p_target_user_id uuid, p_action text, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."set_user_deactivation"(p_target_user_id uuid, p_action text, p_reason text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."set_vehicle_owner_access"(p_user_id uuid, p_enabled boolean, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_target public.user_profiles%rowtype;
  v_grant public.staff_area_grants%rowtype;
  v_ready jsonb;
BEGIN
  SELECT * INTO v_target FROM public.user_profiles WHERE id = p_user_id FOR UPDATE;
  IF v_target.id IS NULL OR v_actor IS NULL OR NOT public.is_admin_for_org(v_target.organization_id) THEN
    RAISE EXCEPTION 'Organisation administrator required';
  END IF;
  IF v_target.role = 'grand_master' THEN RAISE EXCEPTION 'Grand master access is not configurable here'; END IF;
  IF coalesce(trim(p_reason), '') = '' THEN RAISE EXCEPTION 'A reason is required for the access audit trail'; END IF;
  IF p_enabled AND NOT EXISTS (
    SELECT 1 FROM public.staff_area_grants
    WHERE user_id = p_user_id AND scope_org_id = v_target.organization_id
      AND area = 'vehicle_owner_identity' AND status = 'active') THEN
    v_ready := public.nzta_access_readiness(p_user_id, v_target.organization_id);
    IF NOT (v_ready->>'training_current')::boolean OR NOT (v_ready->>'confidentiality_current')::boolean THEN
      RAISE EXCEPTION 'Record current NZTA register training and confidentiality acceptance before granting access';
    END IF;
  END IF;
  IF p_enabled THEN
    INSERT INTO public.staff_area_grants (user_id, scope_org_id, area, level, status, granted_by)
    VALUES (p_user_id, v_target.organization_id, 'vehicle_owner_identity', 'manage', 'active', v_actor)
    ON CONFLICT (user_id, scope_org_id, area)
    DO UPDATE SET level = 'manage', status = 'active', granted_by = v_actor, updated_at = clock_timestamp()
    RETURNING * INTO v_grant;
  ELSE
    UPDATE public.staff_area_grants SET status = 'ended', updated_at = clock_timestamp()
    WHERE user_id = p_user_id AND scope_org_id = v_target.organization_id
      AND area = 'vehicle_owner_identity' AND status = 'active'
    RETURNING * INTO v_grant;
  END IF;
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_target.organization_id, v_actor,
    CASE WHEN p_enabled THEN 'vehicle_owner_access_granted' ELSE 'vehicle_owner_access_ended' END,
    'staff_area_grants', v_grant.id,
    jsonb_build_object('user_id', p_user_id, 'area', 'vehicle_owner_identity', 'reason', trim(p_reason)));
  RETURN public.get_vehicle_owner_access(p_user_id);
END;
$function$;
COMMENT ON FUNCTION "public"."set_vehicle_owner_access"(p_user_id uuid, p_enabled boolean, p_reason text) IS 'Audited administrator switch for a user''s vehicle_owner_identity access area. New grants require current NZTA register training and confidentiality acceptance; existing grants are not revoked.';
REVOKE ALL ON FUNCTION "public"."set_vehicle_owner_access"(p_user_id uuid, p_enabled boolean, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."set_vehicle_owner_access"(p_user_id uuid, p_enabled boolean, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."set_vehicle_owner_access"(p_user_id uuid, p_enabled boolean, p_reason text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."set_vehicle_profile_photo"(p_organization_id uuid, p_vehicle_id uuid, p_storage_path text, p_sha256_hash text, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_previous public.vehicle_profile_photos%rowtype;
  v_metadata jsonb;
  v_actor uuid := auth.uid();
BEGIN
  IF v_actor IS NULL OR NOT public.is_admin_for_org(p_organization_id) THEN
    RAISE EXCEPTION 'Identity registry administrator access required';
  END IF;
  IF coalesce(trim(p_reason), '') = '' THEN RAISE EXCEPTION 'A reason is required for the identity audit trail'; END IF;
  IF p_sha256_hash IS NULL OR p_sha256_hash !~ '^[0-9a-f]{64}$'
    OR p_storage_path IS NULL OR p_storage_path NOT LIKE
      p_organization_id::text || '/' || v_actor::text || '/' || p_vehicle_id::text || '/%'
    OR p_storage_path !~ '/[0-9a-f-]{36}\.(jpg|png|webp)$' THEN
    RAISE EXCEPTION 'Invalid vehicle photo upload receipt';
  END IF;
  SELECT metadata INTO v_metadata FROM storage.objects
    WHERE bucket_id = 'vehicle-profile-photos' AND name = p_storage_path;
  IF v_metadata IS NULL OR coalesce(v_metadata->>'mimetype', '') NOT IN ('image/jpeg','image/png','image/webp')
    OR coalesce((v_metadata->>'size')::bigint, 0) NOT BETWEEN 1 AND 5242880 THEN
    RAISE EXCEPTION 'Upload a JPEG, PNG or WebP photo of at most 5 MB first';
  END IF;
  PERFORM 1 FROM public.canonical_vehicles WHERE id = p_vehicle_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Canonical vehicle not found'; END IF;
  SELECT * INTO v_previous FROM public.vehicle_profile_photos WHERE canonical_vehicle_id = p_vehicle_id;
  IF v_previous.storage_path = p_storage_path AND v_previous.sha256_hash = p_sha256_hash THEN RETURN; END IF;
  INSERT INTO public.vehicle_profile_photos(canonical_vehicle_id,organization_id,storage_path,sha256_hash,uploaded_by)
  VALUES(p_vehicle_id,p_organization_id,p_storage_path,p_sha256_hash,v_actor)
  ON CONFLICT(canonical_vehicle_id) DO UPDATE SET organization_id=excluded.organization_id,
    storage_path=excluded.storage_path,sha256_hash=excluded.sha256_hash,
    uploaded_by=excluded.uploaded_by,updated_at=clock_timestamp();
  INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
  VALUES(p_organization_id,v_actor,'vehicle_profile_photo_set','canonical_vehicles',p_vehicle_id,
    jsonb_build_object('reason',trim(p_reason),'storage_path',p_storage_path,'sha256',p_sha256_hash,
      'previous_storage_path',v_previous.storage_path,'previous_sha256',v_previous.sha256_hash,
      'disclosure','shared_with_authorised_organisations'));
END;
$function$;
REVOKE ALL ON FUNCTION "public"."set_vehicle_profile_photo"(p_organization_id uuid, p_vehicle_id uuid, p_storage_path text, p_sha256_hash text, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."set_vehicle_profile_photo"(p_organization_id uuid, p_vehicle_id uuid, p_storage_path text, p_sha256_hash text, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."set_vehicle_profile_photo"(p_organization_id uuid, p_vehicle_id uuid, p_storage_path text, p_sha256_hash text, p_reason text) TO "authenticated";

