CREATE OR REPLACE FUNCTION "public"."set_workshop_default_job_lead"(p_organization_id uuid, p_user_id uuid)
 RETURNS workshop_settings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_previous uuid;
  v_row public.workshop_settings%rowtype;
BEGIN
  IF v_actor IS NULL OR NOT public.user_can_operate_organization(p_organization_id)
    OR NOT public.is_admin_for_org(p_organization_id) THEN
    RAISE EXCEPTION 'Active authorized operating branch administrator required';
  END IF;
  IF p_user_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.user_profiles profile
    WHERE profile.id = p_user_id AND profile.deactivated_at IS NULL
      AND (profile.organization_id = p_organization_id OR profile.employer_organization_id = p_organization_id)
  ) THEN
    RAISE EXCEPTION 'Job lead must be an active staff member of this organization';
  END IF;
  SELECT default_job_lead_user_id INTO v_previous FROM public.workshop_settings WHERE organization_id = p_organization_id;
  INSERT INTO public.workshop_settings (organization_id, default_job_lead_user_id, updated_by, updated_at)
  VALUES (p_organization_id, p_user_id, v_actor, now())
  ON CONFLICT (organization_id) DO UPDATE
    SET default_job_lead_user_id = EXCLUDED.default_job_lead_user_id, updated_by = v_actor, updated_at = now()
  RETURNING * INTO v_row;
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (p_organization_id, v_actor, 'workshop_default_job_lead_set', 'workshop_settings', p_organization_id,
    jsonb_build_object('previous_user_id', v_previous, 'user_id', p_user_id));
  RETURN v_row;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."set_workshop_default_job_lead"(p_organization_id uuid, p_user_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."set_workshop_default_job_lead"(p_organization_id uuid, p_user_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."set_workshop_default_job_lead"(p_organization_id uuid, p_user_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."set_workshop_default_job_lead"(p_organization_id uuid, p_user_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."set_zone_geometry"(p_zone_id uuid, p_polygons jsonb, p_boundary_source text DEFAULT NULL::text, p_changed_by uuid DEFAULT NULL::uuid, p_changed_via text DEFAULT 'governed_proposal'::text)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_geom    geometry;
  v_center  geometry;
  v_area_m2 numeric;
  v_source  text;
  v_via     text;
BEGIN
  IF p_polygons IS NULL OR jsonb_array_length(p_polygons) = 0 THEN
    RAISE EXCEPTION 'set_zone_geometry: p_polygons must be a non-empty JSON array';
  END IF;

  SELECT st_union(array_agg(st_makevalid(st_setsrid(st_geomfromgeojson(elem::text), 4326))))
    INTO v_geom
    FROM jsonb_array_elements(p_polygons) AS elem;

  IF v_geom IS NULL OR st_isempty(v_geom) THEN
    RAISE EXCEPTION 'set_zone_geometry: could not build geometry from supplied polygons';
  END IF;

  v_geom := st_multi(st_makevalid(v_geom));

  IF NOT st_isvalid(v_geom) THEN
    RAISE EXCEPTION 'set_zone_geometry: geometry still invalid after ST_MakeValid: %', st_isvalidreason(v_geom);
  END IF;

  v_center  := st_centroid(v_geom);
  v_area_m2 := st_area(v_geom::geography);

  UPDATE location_zones
     SET boundary     = v_geom,
         center_point = v_center
   WHERE id = p_zone_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'set_zone_geometry: zone % not found', p_zone_id;
  END IF;

  -- Resolve provenance: use caller-supplied source, else 'UNKNOWN_SOURCE' (P1).
  v_source := COALESCE(NULLIF(TRIM(p_boundary_source), ''), 'UNKNOWN_SOURCE');

  -- Resolve changed_via: validate against the CHECK constraint values.
  v_via := CASE
    WHEN p_changed_via IN ('governed_proposal', 'direct_edit', 'reconciliation', 'refresh', 'verification', 'backfill')
    THEN p_changed_via
    ELSE 'governed_proposal'
  END;

  -- Record history
  INSERT INTO public.geofence_boundary_history (
    entity_type, entity_id, boundary, boundary_source,
    verification_state, verified_by, verified_at,
    changed_by, changed_via, change_reason, version
  ) VALUES (
    'location_zone', p_zone_id, v_geom, v_source,
    'unverified', NULL, NULL,
    p_changed_by, v_via, 'Zone geometry set via set_zone_geometry (polygon)',
    public._gbh_next_version('location_zone', p_zone_id)
  );

  RETURN v_area_m2;
END;
$function$;
COMMENT ON FUNCTION "public"."set_zone_geometry"(p_zone_id uuid, p_polygons jsonb, p_boundary_source text, p_changed_by uuid, p_changed_via text) IS 'Writes a zone boundary from a GeoJSON polygon array (union, ST_MakeValid, MultiPolygon) and returns its real area (m^2). Records a history row with real provenance. Phase 1+4 geofence redesign (#226).';
REVOKE ALL ON FUNCTION "public"."set_zone_geometry"(p_zone_id uuid, p_polygons jsonb, p_boundary_source text, p_changed_by uuid, p_changed_via text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."set_zone_geometry"(p_zone_id uuid, p_polygons jsonb, p_boundary_source text, p_changed_by uuid, p_changed_via text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."set_zone_geometry"(p_zone_id uuid, p_polygons jsonb, p_boundary_source text, p_changed_by uuid, p_changed_via text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."set_zone_geometry"(p_zone_id uuid, p_center_lat double precision, p_center_lng double precision, p_provisional_radius_m double precision DEFAULT 100, p_boundary_source text DEFAULT NULL::text, p_changed_by uuid DEFAULT NULL::uuid, p_changed_via text DEFAULT 'governed_proposal'::text)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_point   geometry;
  v_buffer  geometry;
  v_area_m2 numeric;
  v_source  text;
  v_via     text;
BEGIN
  IF p_center_lat IS NULL OR p_center_lng IS NULL THEN
    RAISE EXCEPTION 'set_zone_geometry: p_center_lat and p_center_lng are required for provisional fence';
  END IF;

  v_point  := st_setsrid(st_point(p_center_lng, p_center_lat), 4326);
  v_buffer := st_transform(
                st_buffer(
                  st_transform(v_point, 2193),
                  coalesce(p_provisional_radius_m, 100)
                ),
                4326
              );

  v_buffer  := st_multi(v_buffer);
  v_area_m2 := st_area(v_buffer::geography);

  UPDATE location_zones
     SET boundary     = v_buffer,
         center_point = v_point
   WHERE id = p_zone_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'set_zone_geometry: zone % not found', p_zone_id;
  END IF;

  -- Point-radius path: source is always 'point_radius' regardless of caller,
  -- unless the caller explicitly overrides (unlikely but supported).
  v_source := COALESCE(NULLIF(TRIM(p_boundary_source), ''), 'point_radius');

  -- Resolve changed_via: validate against the CHECK constraint values.
  v_via := CASE
    WHEN p_changed_via IN ('governed_proposal', 'direct_edit', 'reconciliation', 'refresh', 'verification', 'backfill')
    THEN p_changed_via
    ELSE 'governed_proposal'
  END;

  -- Record history
  INSERT INTO public.geofence_boundary_history (
    entity_type, entity_id, boundary, boundary_source,
    verification_state, verified_by, verified_at,
    changed_by, changed_via, change_reason, version
  ) VALUES (
    'location_zone', p_zone_id, v_buffer, v_source,
    'unverified', NULL, NULL,
    p_changed_by, v_via, 'Zone geometry set via set_zone_geometry (provisional point)',
    public._gbh_next_version('location_zone', p_zone_id)
  );

  RETURN v_area_m2;
END;
$function$;
COMMENT ON FUNCTION "public"."set_zone_geometry"(p_zone_id uuid, p_center_lat double precision, p_center_lng double precision, p_provisional_radius_m double precision, p_boundary_source text, p_changed_by uuid, p_changed_via text) IS 'Writes a provisional circular boundary from a GPS point + radius (NZTM2000 metric buffer, wrapped as MultiPolygon) and returns its area (m^2). Records a history row with real provenance. Phase 1+4 geofence redesign (#226).';
REVOKE ALL ON FUNCTION "public"."set_zone_geometry"(p_zone_id uuid, p_center_lat double precision, p_center_lng double precision, p_provisional_radius_m double precision, p_boundary_source text, p_changed_by uuid, p_changed_via text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."set_zone_geometry"(p_zone_id uuid, p_center_lat double precision, p_center_lng double precision, p_provisional_radius_m double precision, p_boundary_source text, p_changed_by uuid, p_changed_via text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."set_zone_geometry"(p_zone_id uuid, p_center_lat double precision, p_center_lng double precision, p_provisional_radius_m double precision, p_boundary_source text, p_changed_by uuid, p_changed_via text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."shift_safety_places"(p_shift_id uuid, p_stop_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(place_kind text, place_id uuid, location_id uuid, place_name text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT 'site'::text, cs.id, cs.location_id, cs.name
  FROM public.shift_stops st JOIN public.client_sites cs ON cs.id = st.site_id
  WHERE st.shift_id = p_shift_id AND st.status NOT IN ('cancelled', 'skipped') AND (p_stop_id IS NULL OR st.id = p_stop_id)
  UNION
  SELECT 'zone'::text, z.id, z.location_id, z.name
  FROM public.shift_stops st JOIN public.location_zones z ON z.id = st.zone_id
  WHERE st.shift_id = p_shift_id AND st.status NOT IN ('cancelled', 'skipped') AND (p_stop_id IS NULL OR st.id = p_stop_id)
  UNION
  SELECT 'zone'::text, z.id, z.location_id, z.name
  FROM public.shifts s JOIN public.location_zones z ON z.id = s.zone_id
  WHERE s.id = p_shift_id AND p_stop_id IS NULL
  UNION
  SELECT 'site'::text, cs.id, cs.location_id, cs.name
  FROM public.shifts s
  JOIN public.service_agreement_locations sal ON sal.id = s.service_agreement_location_id
  JOIN public.client_sites cs ON cs.id = sal.site_id
  WHERE s.id = p_shift_id AND p_stop_id IS NULL
  UNION
  SELECT 'zone'::text, z.id, z.location_id, z.name
  FROM public.shifts s
  JOIN public.service_agreement_locations sal ON sal.id = s.service_agreement_location_id
  JOIN public.location_zones z ON z.id = sal.zone_id
  WHERE s.id = p_shift_id AND p_stop_id IS NULL
  UNION
  SELECT 'site'::text, cs.id, cs.location_id, cs.name
  FROM public.shifts s JOIN public.client_sites cs ON cs.location_id = s.location_id
  WHERE s.id = p_shift_id AND p_stop_id IS NULL
  UNION
  SELECT 'zone'::text, z.id, z.location_id, z.name
  FROM public.shifts s JOIN public.location_zones z ON z.location_id = s.location_id
  WHERE s.id = p_shift_id AND p_stop_id IS NULL;
$function$;
COMMENT ON FUNCTION "public"."shift_safety_places"(p_shift_id uuid, p_stop_id uuid) IS 'Internal: the sites and zones (with their house) a shift, or one of its stops, is for. Used by the safety briefing and officer hazard reports.';
REVOKE ALL ON FUNCTION "public"."shift_safety_places"(p_shift_id uuid, p_stop_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."shift_safety_places"(p_shift_id uuid, p_stop_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."shift_safety_places"(p_shift_id uuid, p_stop_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."shifts_one_at_a_time"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_other public.shifts%rowtype;
  v_at timestamptz := clock_timestamp();
  v_open_stops integer;
  v_open_modules integer;
  v_open_jobs integer;
  v_alerts integer;
  v_debrief boolean;
begin
  if new.status <> 'in_progress' or (tg_op = 'UPDATE' and old.status = 'in_progress') then
    return new;
  end if;

  for v_other in
    select s.* from public.shifts s
    where s.officer_user_id = new.officer_user_id and s.status = 'in_progress' and s.id <> new.id
    for update
  loop
    select count(*) into v_open_stops from public.shift_stops st where st.shift_id = v_other.id and st.status not in ('completed', 'skipped', 'cancelled');
    select count(*) into v_open_modules from public.shift_stop_modules sm join public.shift_stops st on st.id = sm.shift_stop_id where st.shift_id = v_other.id and sm.is_required and sm.status not in ('completed', 'skipped');
    select count(*) into v_open_jobs from public.dispatch_jobs j where j.shift_id = v_other.id and j.status not in ('completed', 'cancelled');
    select count(*) into v_alerts from public.welfare_alerts w where w.shift_id = v_other.id and w.status <> 'resolved';
    v_debrief := exists (select 1 from public.shift_debriefs d where d.shift_id = v_other.id);

    update public.shifts
    set status = 'completed', actual_end = coalesce(actual_end, v_at), ended_reason = 'superseded_by_next_shift', superseded_by_shift_id = new.id, updated_at = v_at
    where id = v_other.id;
    update public.roster_slots set status = 'completed' where linked_shift_id = v_other.id and status in ('published', 'accepted');

    insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
    values (v_other.organization_id, auth.uid(), 'officer_shift_superseded', 'shifts', v_other.id, jsonb_build_object(
      'superseded_by_shift_id', new.id,
      'actual_start', v_other.actual_start,
      'actual_end', v_at,
      'scheduled_end', v_other.scheduled_end,
      'open_stop_count', v_open_stops,
      'open_required_task_count', v_open_modules,
      'open_dispatch_job_count', v_open_jobs,
      'active_welfare_alert_count', v_alerts,
      'debrief_submitted', v_debrief,
      'rule', 'one shift at a time'
    ));
  end loop;

  return new;
end;
$function$;
COMMENT ON FUNCTION "public"."shifts_one_at_a_time"() IS 'Owner ruling 2026-09-19: an officer is on at most one shift. When a shift goes in progress, any other in-progress shift of the same officer is stopped (completed, ended_reason = superseded_by_next_shift), its roster slot closed, and what was still open written to audit_log as officer_shift_superseded.';
REVOKE ALL ON FUNCTION "public"."shifts_one_at_a_time"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."shifts_one_at_a_time"() TO "postgres";

CREATE OR REPLACE FUNCTION "public"."staff_branch_authorisation_manager_can_manage"(p_actor_id uuid, p_branch_organization_id uuid, p_target_user_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1
    from public.user_profiles actor
    join public.user_profiles target on target.id = p_target_user_id
    where actor.id = p_actor_id
      and actor.deactivated_at is null
      and target.employer_organization_id is not null
      and (
        actor.role = 'grand_master'
        or (
          target.employer_organization_id = coalesce(actor.employer_organization_id, actor.organization_id)
          and p_branch_organization_id = any(public.get_descendant_organizations(coalesce(actor.employer_organization_id, actor.organization_id)))
          and (actor.role in ('master', 'admin', 'admin_officer') or p_branch_organization_id = any(public.user_managed_branch_ids()))
        )
      )
  );
$function$;
REVOKE ALL ON FUNCTION "public"."staff_branch_authorisation_manager_can_manage"(p_actor_id uuid, p_branch_organization_id uuid, p_target_user_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."staff_branch_authorisation_manager_can_manage"(p_actor_id uuid, p_branch_organization_id uuid, p_target_user_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."staff_branch_authorisation_manager_can_manage"(p_actor_id uuid, p_branch_organization_id uuid, p_target_user_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."staff_credential_has_verified_match"(p_credential_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.staff_credentials source
    JOIN public.staff_credentials verified
      ON verified.staff_id = source.staff_id
    WHERE source.id = p_credential_id
      AND source.verified IS FALSE
      AND verified.verified IS TRUE
      AND nullif(btrim(source.credential_number), '') IS NOT NULL
      AND nullif(btrim(verified.credential_number), '') = nullif(btrim(source.credential_number), '')
      AND verified.expiry_date IS NOT DISTINCT FROM source.expiry_date
      AND (source.issued_date IS NULL OR verified.issued_date = source.issued_date)
      AND (
        source.credential_type = verified.credential_type
        OR (
          source.credential_type IN ('certificate_of_authority', 'security_licence')
          AND verified.credential_type IN ('certificate_of_authority', 'security_licence')
        )
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.staff_credentials replacement
        WHERE replacement.replaces_credential_id = verified.id
      )
  );
$function$;
COMMENT ON FUNCTION "public"."staff_credential_has_verified_match"(p_credential_id uuid) IS 'True only when this unverified credential matches an active verified credential for the same staff member by number, issue/expiry dates and canonical credential type.';
REVOKE ALL ON FUNCTION "public"."staff_credential_has_verified_match"(p_credential_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."staff_credential_has_verified_match"(p_credential_id uuid) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."staff_fatigue_conflict"(p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_exclude_slot_id uuid DEFAULT NULL::uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org uuid;
  v_rules public.organization_fatigue_rules%rowtype;
  v_load record;
begin
  select sp.organization_id into v_org from public.staff_profiles sp where sp.id = p_staff_id;
  if v_org is null then return null; end if;
  select r.* into v_rules from public.organization_fatigue_rules r where r.organization_id = v_org;
  if not found or not v_rules.enforced then return null; end if;

  select * into v_load from public.roster_assignment_load(p_staff_id, p_scheduled_start, p_scheduled_end, p_exclude_slot_id);

  if v_load.rest_hours is not null and v_load.rest_hours < v_rules.min_rest_hours_between_shifts then
    return format('Only %s hours'' rest from the nearest other shift; this organisation requires %s', trim_scale(v_load.rest_hours), trim_scale(v_rules.min_rest_hours_between_shifts));
  end if;
  if v_load.week_hours > v_rules.max_hours_per_week then
    return format('%s hours in the week starting %s, over the %s-hour limit', trim_scale(v_load.week_hours), to_char(v_load.week_start, 'DD Mon'), trim_scale(v_rules.max_hours_per_week));
  end if;
  if v_load.consecutive_days > v_rules.max_consecutive_days then
    return format('Day %s in a row, over the limit of %s', v_load.consecutive_days, v_rules.max_consecutive_days);
  end if;
  return null;
end;
$function$;
COMMENT ON FUNCTION "public"."staff_fatigue_conflict"(p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_exclude_slot_id uuid) IS 'Null when the proposed slot passes the employing organisation''s rest and hours rules (or none are set/enforced); otherwise one plain sentence naming the rule and the numbers. Enforced by the roster_slots trigger and the roster RPCs.';
REVOKE ALL ON FUNCTION "public"."staff_fatigue_conflict"(p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_exclude_slot_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."staff_fatigue_conflict"(p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_exclude_slot_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."staff_fatigue_conflict"(p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_exclude_slot_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."staff_fatigue_conflict"(p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_exclude_slot_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."staff_has_roster_availability_conflict"(p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists(
    select 1
    from public.staff_availability a
    cross join lateral generate_series(
      (p_scheduled_start at time zone 'Pacific/Auckland')::date,
      ((p_scheduled_end-interval '1 microsecond') at time zone 'Pacific/Auckland')::date,
      interval '1 day'
    ) as roster_day
    where a.staff_id=p_staff_id
      and a.availability_type in('unavailable','leave')
      and (a.specific_date=roster_day::date or (a.specific_date is null and a.day_of_week=extract(isodow from roster_day)::integer))
      and (
        a.all_day
        or a.available_from is null
        or a.available_to is null
        or tstzrange(p_scheduled_start,p_scheduled_end,'[)') && tstzrange(
          (roster_day::date+a.available_from) at time zone 'Pacific/Auckland',
          ((roster_day::date+case when a.available_to>a.available_from then 0 else 1 end)+a.available_to) at time zone 'Pacific/Auckland',
          '[)'
        )
      )
  );
$function$;
REVOKE ALL ON FUNCTION "public"."staff_has_roster_availability_conflict"(p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."staff_has_roster_availability_conflict"(p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."staff_has_roster_availability_conflict"(p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."stage_org_jurisdiction_part"(p_stage_id uuid, p_org_id uuid, p_polygon jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_stage public.org_jurisdiction_geom_stages;
  v_part  geometry;
BEGIN
  IF p_org_id IS NULL THEN
    RAISE EXCEPTION 'Organization is required';
  END IF;
  IF p_polygon IS NULL OR jsonb_typeof(p_polygon) <> 'object' THEN
    RAISE EXCEPTION 'p_polygon must be one GeoJSON geometry object';
  END IF;
  v_part := st_collectionextract(st_makevalid(st_setsrid(st_geomfromgeojson(p_polygon), 4326)), 3);
  IF v_part IS NULL OR st_isempty(v_part) THEN
    RAISE EXCEPTION 'Jurisdiction part has no polygon area';
  END IF;

  DELETE FROM public.org_jurisdiction_geom_stages WHERE expires_at < now();

  IF p_stage_id IS NULL THEN
    IF NOT EXISTS (SELECT 1 FROM public.organizations WHERE id = p_org_id) THEN
      RAISE EXCEPTION 'Organization % not found', p_org_id;
    END IF;
    INSERT INTO public.org_jurisdiction_geom_stages (organization_id, geom, part_count)
    VALUES (p_org_id, st_multi(v_part), 1)
    RETURNING * INTO v_stage;
    RETURN v_stage.id;
  END IF;

  SELECT * INTO v_stage FROM public.org_jurisdiction_geom_stages WHERE id = p_stage_id FOR UPDATE;
  IF NOT FOUND OR v_stage.expires_at < now() THEN
    RAISE EXCEPTION 'Jurisdiction stage % not found or expired', p_stage_id;
  END IF;
  IF v_stage.organization_id <> p_org_id THEN
    RAISE EXCEPTION 'Jurisdiction stage belongs to a different organization';
  END IF;

  UPDATE public.org_jurisdiction_geom_stages
     SET geom = st_multi(st_collectionextract(st_union(geom, v_part), 3)),
         part_count = part_count + 1
   WHERE id = v_stage.id;
  RETURN v_stage.id;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."stage_org_jurisdiction_part"(p_stage_id uuid, p_org_id uuid, p_polygon jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."stage_org_jurisdiction_part"(p_stage_id uuid, p_org_id uuid, p_polygon jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."stage_org_jurisdiction_part"(p_stage_id uuid, p_org_id uuid, p_polygon jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."stage_patrol_finance_cost_rows"(p_batch_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_service_agreement_id uuid, p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid:=auth.uid();
  v_batch public.file_import_batches%rowtype;
  v_profile public.import_source_profiles%rowtype;
  v_agreement public.service_agreements%rowtype;
  v_row jsonb;
  v_status text;
  v_reason text;
  v_evidence_type text;
  v_site uuid;
  v_zone uuid;
  v_service_date date;
  v_component text;
  v_cost_type text;
  v_amount numeric;
  v_source_row integer;
  v_inserted integer:=0;
  v_existing integer:=0;
  v_eligible integer:=0;
  v_quarantined integer:=0;
  v_proposals integer:=0;
  v_eligible_total numeric:=0;
BEGIN
  IF jsonb_typeof(p_rows)<>'array' THEN RAISE EXCEPTION 'Finance source rows must be an array'; END IF;
  SELECT * INTO v_batch FROM public.file_import_batches WHERE id=p_batch_id FOR UPDATE;
  IF NOT FOUND OR v_batch.organization_id<>p_provider_organization_id OR v_batch.status<>'staging' THEN
    RAISE EXCEPTION 'Open provider import batch required';
  END IF;
  SELECT * INTO v_profile FROM public.import_source_profiles
  WHERE organization_id=p_provider_organization_id AND profile_code=v_batch.manifest_json->>'source_profile' AND active;
  IF NOT FOUND OR v_profile.import_actor_id IS DISTINCT FROM v_actor
    OR v_batch.created_by IS DISTINCT FROM v_actor
    OR NOT public.is_tenant_import_admin(p_provider_organization_id) THEN
    RAISE EXCEPTION 'Configured tenant import identity required';
  END IF;
  IF v_batch.manifest_json->>'target_client_organization_id' IS DISTINCT FROM p_client_organization_id::text THEN
    RAISE EXCEPTION 'Import batch client scope is invalid';
  END IF;
  SELECT agreement.* INTO v_agreement
    FROM public.service_agreements agreement
    JOIN public.service_agreement_modules module ON module.service_agreement_id=agreement.id AND module.module_key='patrol' AND module.enabled
    WHERE agreement.id=p_service_agreement_id
      AND agreement.provider_organization_id=p_provider_organization_id
      AND agreement.client_organization_id=p_client_organization_id
      AND agreement.agreement_type='operational';
  IF NOT FOUND THEN RAISE EXCEPTION 'Contracted patrol agreement required'; END IF;

  FOR v_row IN SELECT * FROM jsonb_array_elements(p_rows) LOOP
    IF v_row->>'organization_id' IS DISTINCT FROM p_provider_organization_id::text
      OR v_row->>'client_organization_id' IS DISTINCT FROM p_client_organization_id::text
      OR v_row->>'service_agreement_id' IS DISTINCT FROM p_service_agreement_id::text
      OR v_row->>'source_file' IS DISTINCT FROM v_batch.source_file
      OR v_row->>'source_sha256' IS DISTINCT FROM v_batch.source_sha256
      OR v_row->>'derivative_sha256' IS DISTINCT FROM v_batch.manifest_json->>'derivative_sha256'
      OR v_row->>'source_sheet' IS DISTINCT FROM v_batch.manifest_json->>'source_sheet'
      OR coalesce(v_row->>'source_row','') !~ '^[1-9][0-9]*$'
      OR coalesce(v_row->>'source_row_sha256','') !~ '^[a-f0-9]{64}$' THEN
      RAISE EXCEPTION 'Finance source row provenance does not match its batch';
    END IF;
    v_source_row:=(v_row->>'source_row')::integer;
    v_component:=v_row->>'component';
    v_cost_type:=v_row->>'cost_type';
    v_amount:=NULLIF(v_row->>'amount','')::numeric;
    v_site:=NULLIF(v_row->>'site_id','')::uuid;
    v_zone:=NULLIF(v_row->>'zone_id','')::uuid;
    v_service_date:=NULLIF(v_row->>'service_date','')::date;
    v_status:=v_row->>'status';
    v_reason:=NULLIF(v_row->>'quarantine_reason','');
    v_evidence_type:=NULL;

    IF v_component NOT IN ('job_cost','travel_cost')
      OR (v_component='job_cost' AND v_cost_type<>'labour')
      OR (v_component='travel_cost' AND v_cost_type<>'vehicle')
      OR v_amount IS NULL OR v_amount<=0 THEN
      RAISE EXCEPTION 'Finance source component and amount are invalid';
    END IF;
    IF v_status='quarantined' THEN
      IF v_reason IS NULL THEN RAISE EXCEPTION 'Quarantined finance source row requires a reason'; END IF;
      IF v_reason NOT IN (
        'invalid_service_date','unresolved_contracted_place','formula_error',
        'displayed_total_mismatch','duplicate_external_reference',
        'outside_agreement_term','outside_contracted_place','operational_evidence_not_found'
      ) THEN RAISE EXCEPTION 'Unsupported finance source quarantine reason'; END IF;
    ELSIF v_status='eligible' THEN
      IF v_reason IS NOT NULL OR v_service_date IS NULL OR ((v_site IS NULL)=(v_zone IS NULL))
        OR v_row->>'aggregate_key' IS DISTINCT FROM to_char(v_service_date,'YYYY-MM')||':'||v_component THEN
        RAISE EXCEPTION 'Eligible finance source row is incomplete';
      END IF;
      IF NULLIF(v_row->>'total_cost','') IS NOT NULL
        AND abs(
          (v_row->>'total_cost')::numeric
          - coalesce(NULLIF(v_row->>'job_cost','')::numeric,0)
          - coalesce(NULLIF(v_row->>'travel_cost','')::numeric,0)
        )>0.02 THEN
        v_status:='quarantined';v_reason:='displayed_total_mismatch';
      END IF;
        IF v_status='eligible'
          AND ((v_agreement.starts_on IS NOT NULL AND v_service_date<v_agreement.starts_on)
            OR (v_agreement.ends_on IS NOT NULL AND v_service_date>v_agreement.ends_on)) THEN
          v_status:='quarantined';v_reason:='outside_agreement_term';
        ELSIF v_status='eligible' AND NOT EXISTS(
          SELECT 1 FROM public.service_agreement_locations location
        WHERE location.service_agreement_id=p_service_agreement_id AND location.status='active'
          AND ((v_site IS NOT NULL AND location.site_id=v_site) OR (v_zone IS NOT NULL AND location.zone_id=v_zone))
      ) THEN
        v_status:='quarantined';v_reason:='outside_contracted_place';
      ELSIF v_status='eligible' AND EXISTS(
        SELECT 1 FROM public.observations observation
        WHERE observation.organization_id=p_client_organization_id
          AND observation.external_refs->>'external_ref'=v_row->>'evidence_external_ref'
          AND observation.observed_at::date=v_service_date
          AND observation.site_id IS NOT DISTINCT FROM v_site
          AND observation.zone_id IS NOT DISTINCT FROM v_zone
      ) THEN
        v_evidence_type:='observations';
      ELSIF v_status='eligible' AND EXISTS(
        SELECT 1 FROM public.location_events event
        WHERE event.organization_id=p_client_organization_id
          AND event.external_ref=v_row->>'evidence_external_ref'
          AND event.occurred_at::date=v_service_date
          AND event.client_site_id IS NOT DISTINCT FROM v_site
          AND event.zone_id IS NOT DISTINCT FROM v_zone
      ) THEN
        v_evidence_type:='location_events';
      ELSIF v_status='eligible' THEN
        v_status:='quarantined';v_reason:='operational_evidence_not_found';
      END IF;
    ELSE
      RAISE EXCEPTION 'Finance source row status must be eligible or quarantined';
    END IF;

    IF EXISTS(
      SELECT 1 FROM public.file_import_finance_cost_rows existing
      WHERE existing.organization_id=p_provider_organization_id
        AND existing.source_file=v_batch.source_file
        AND existing.source_sheet=v_batch.manifest_json->>'source_sheet'
        AND existing.source_row=v_source_row
        AND existing.component=v_component
        AND existing.status IN ('eligible','applied')
    ) THEN
      IF EXISTS(
        SELECT 1 FROM public.file_import_finance_cost_rows existing
        WHERE existing.organization_id=p_provider_organization_id
          AND existing.source_file=v_batch.source_file
          AND existing.source_sheet=v_batch.manifest_json->>'source_sheet'
          AND existing.source_row=v_source_row
          AND existing.component=v_component
          AND existing.status IN ('eligible','applied')
          AND (
            existing.source_row_sha256 IS DISTINCT FROM v_row->>'source_row_sha256'
            OR existing.client_organization_id IS DISTINCT FROM p_client_organization_id
            OR existing.service_agreement_id IS DISTINCT FROM p_service_agreement_id
          )
      ) THEN
        RAISE EXCEPTION 'Previously accepted finance source row changed and requires governed financial reconciliation';
      END IF;
      v_existing:=v_existing+1;
      CONTINUE;
    END IF;

    INSERT INTO public.file_import_finance_cost_rows(
      organization_id,batch_id,client_organization_id,service_agreement_id,
      source_file,source_sha256,derivative_sha256,source_sheet,source_row,source_row_sha256,
      component,cost_type,amount,formula,service_date,site_id,zone_id,
      evidence_record_type,evidence_external_ref,aggregate_key,source_values,status,quarantine_reason,created_by
    ) VALUES(
      p_provider_organization_id,p_batch_id,p_client_organization_id,p_service_agreement_id,
      v_batch.source_file,v_batch.source_sha256,v_batch.manifest_json->>'derivative_sha256',
      v_batch.manifest_json->>'source_sheet',v_source_row,v_row->>'source_row_sha256',
      v_component,v_cost_type,v_amount,NULLIF(v_row->>'formula',''),v_service_date,v_site,v_zone,
      v_evidence_type,NULLIF(v_row->>'evidence_external_ref',''),NULLIF(v_row->>'aggregate_key',''),
      v_row-'organization_id'-'client_organization_id'-'service_agreement_id'-'status'-'quarantine_reason',
      v_status,v_reason,v_actor
    )
    ON CONFLICT(batch_id,source_file,source_sheet,source_row,component) DO NOTHING;
    IF FOUND THEN
      v_inserted:=v_inserted+1;
      IF v_status='eligible' THEN v_eligible:=v_eligible+1;v_eligible_total:=v_eligible_total+v_amount;
      ELSE v_quarantined:=v_quarantined+1; END IF;
    ELSE
      v_existing:=v_existing+1;
    END IF;
  END LOOP;

  DELETE FROM public.file_import_row_proposals
  WHERE batch_id=v_batch.id AND target_type='finance_service_cost' AND status='proposed';

  INSERT INTO public.file_import_row_proposals(
    organization_id,batch_id,source_record_key,target_type,proposed_payload,source_values,confidence,created_by
  )
  SELECT
    p_provider_organization_id,v_batch.id,row.aggregate_key,'finance_service_cost',
    jsonb_build_object(
      'organization_id',p_provider_organization_id,
      'client_organization_id',p_client_organization_id,
      'service_agreement_id',p_service_agreement_id,
      'service_month',split_part(row.aggregate_key,':',1),
      'cost_type',min(row.cost_type),
      'quantity',1,
      'unit_cost',round(sum(row.amount),2),
      'source_document_type','patrol_log',
      'source_reference','rm_patrol:'||v_batch.source_sha256||':'||(v_batch.manifest_json->>'source_sheet')||':'||row.aggregate_key,
      'source_row_count',count(*)
    ),
    jsonb_build_object(
      'source','rm_patrol_log_import',
      'source_file',v_batch.source_file,
      'source_sha256',v_batch.source_sha256,
      'derivative_sha256',v_batch.manifest_json->>'derivative_sha256',
      'source_profile',v_batch.manifest_json->>'source_profile',
      'source_sheet',v_batch.manifest_json->>'source_sheet',
      'component',min(row.component),
      'component_total',round(sum(row.amount),2),
      'source_row_count',count(*),
      'quarantined_row_count',(SELECT count(*) FROM public.file_import_finance_cost_rows quarantined WHERE quarantined.batch_id=v_batch.id AND quarantined.status='quarantined')
    ),
    1,v_actor
  FROM public.file_import_finance_cost_rows row
  WHERE row.batch_id=v_batch.id AND row.status='eligible'
  GROUP BY row.aggregate_key;
  GET DIAGNOSTICS v_proposals=ROW_COUNT;

  SELECT count(*) FILTER(WHERE status='eligible'),count(*) FILTER(WHERE status='quarantined'),coalesce(sum(amount) FILTER(WHERE status='eligible'),0)
  INTO v_eligible,v_quarantined,v_eligible_total
  FROM public.file_import_finance_cost_rows WHERE batch_id=v_batch.id;
  UPDATE public.file_import_batches
  SET unresolved_count=v_quarantined,
      manifest_json=manifest_json||jsonb_build_object('expected_proposal_count',v_proposals),
      updated_at=now()
  WHERE id=v_batch.id;
  RETURN jsonb_build_object(
    'inserted',v_inserted,'existing',v_existing,'eligible',v_eligible,'quarantined',v_quarantined,
    'proposal_candidates',v_proposals,'eligible_total',round(v_eligible_total,2)
  );
END;
$function$;
REVOKE ALL ON FUNCTION "public"."stage_patrol_finance_cost_rows"(p_batch_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_service_agreement_id uuid, p_rows jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."stage_patrol_finance_cost_rows"(p_batch_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_service_agreement_id uuid, p_rows jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."stage_patrol_finance_cost_rows"(p_batch_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_service_agreement_id uuid, p_rows jsonb) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."stage_patrol_finance_cost_rows"(p_batch_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_service_agreement_id uuid, p_rows jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."stage_patrol_import_chunk"(p_batch_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_observations jsonb, p_events jsonb, p_proposals jsonb)
 RETURNS TABLE(obs_inserted integer, obs_matched integer, evt_inserted integer, evt_matched integer, proposal_candidates integer, proposals_inserted integer, proposals_existing integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_batch public.file_import_batches%rowtype;
  v_profile public.import_source_profiles%rowtype;
  v_row jsonb;
  v_existing jsonb;
  v_observations jsonb;
  v_events jsonb;
  v_proposals jsonb;
  v_derivative_hash text;
  v_profile_code text;
BEGIN
  SELECT * INTO v_batch FROM public.file_import_batches WHERE id=p_batch_id FOR UPDATE;
  IF NOT FOUND OR v_batch.organization_id<>p_provider_organization_id OR v_batch.status<>'staging' THEN RAISE EXCEPTION 'Open provider import batch required'; END IF;
  v_profile_code:=v_batch.manifest_json->>'source_profile';
  v_derivative_hash:=v_batch.manifest_json->>'derivative_sha256';
  SELECT * INTO v_profile FROM public.import_source_profiles WHERE organization_id=p_provider_organization_id AND profile_code=v_profile_code AND active;
  IF NOT FOUND OR v_profile.import_actor_id IS NULL OR v_profile.import_actor_id<>auth.uid() OR v_batch.created_by<>auth.uid() THEN RAISE EXCEPTION 'Configured tenant import identity required'; END IF;
  IF v_batch.source_sha256 IS NULL OR v_derivative_hash IS NULL THEN RAISE EXCEPTION 'Import batch provenance is incomplete'; END IF;

  SELECT coalesce(jsonb_agg(jsonb_set(value,'{payload,source}','"rm_patrol_log_import"'::jsonb,true)),'[]'::jsonb)
  INTO v_observations FROM jsonb_array_elements(p_observations) value;
  SELECT coalesce(jsonb_agg(jsonb_set(value,'{payload,source}','"rm_patrol_log_import"'::jsonb,true)),'[]'::jsonb)
  INTO v_events FROM jsonb_array_elements(p_events) value;
  SELECT coalesce(jsonb_agg(jsonb_set(value,'{source_values,source}','"rm_patrol_log_import"'::jsonb,true)),'[]'::jsonb)
  INTO v_proposals FROM jsonb_array_elements(p_proposals) value;

  FOR v_row IN SELECT * FROM jsonb_array_elements(v_observations) LOOP
    IF v_row->'payload'->>'source_sha256' IS DISTINCT FROM v_batch.source_sha256
      OR v_row->'payload'->>'derivative_sha256' IS DISTINCT FROM v_derivative_hash
      OR nullif(v_row->'payload'->>'source_file','') IS NULL
      OR coalesce(v_row->'payload'->>'source_row','') !~ '^[1-9][0-9]*$'
      OR v_row->'payload'->>'classification_profile' IS DISTINCT FROM v_profile_code THEN
      RAISE EXCEPTION 'Observation row provenance is incomplete or does not match its batch';
    END IF;
    SELECT observation.external_refs->'import' INTO v_existing FROM public.observations observation
    WHERE observation.organization_id=p_client_organization_id AND observation.external_refs->>'external_ref'=v_row->>'external_ref';
    IF v_existing IS NOT NULL AND (
      (nullif(v_existing->>'source','') IS NOT NULL AND v_existing->>'source' IS DISTINCT FROM 'rm_patrol_log_import')
      OR (nullif(v_existing->>'source_sha256','') IS NOT NULL AND v_existing->>'source_sha256' IS DISTINCT FROM v_batch.source_sha256)
      OR (nullif(v_existing->>'derivative_sha256','') IS NOT NULL AND v_existing->>'derivative_sha256' IS DISTINCT FROM v_derivative_hash)
      OR (nullif(v_existing->>'source_file','') IS NOT NULL AND v_existing->>'source_file' IS DISTINCT FROM v_row->'payload'->>'source_file')
      OR (nullif(v_existing->>'source_sheet','') IS NOT NULL AND v_existing->>'source_sheet' IS DISTINCT FROM v_row->'payload'->>'source_sheet')
      OR (nullif(v_existing->>'source_row','') IS NOT NULL AND v_existing->>'source_row' IS DISTINCT FROM v_row->'payload'->>'source_row')
    ) THEN RAISE EXCEPTION 'Observation immutable provenance conflict requires reconciliation'; END IF;
  END LOOP;

  FOR v_row IN SELECT * FROM jsonb_array_elements(v_events) LOOP
    IF v_row->'payload'->>'source_sha256' IS DISTINCT FROM v_batch.source_sha256
      OR v_row->'payload'->>'derivative_sha256' IS DISTINCT FROM v_derivative_hash
      OR nullif(v_row->'payload'->>'source_file','') IS NULL
      OR coalesce(v_row->'payload'->>'source_row','') !~ '^[1-9][0-9]*$'
      OR v_row->'payload'->>'classification_profile' IS DISTINCT FROM v_profile_code THEN
      RAISE EXCEPTION 'Location event row provenance is incomplete or does not match its batch';
    END IF;
    SELECT event.payload INTO v_existing FROM public.location_events event
    WHERE event.organization_id=p_client_organization_id AND event.external_ref=v_row->>'external_ref';
    IF v_existing IS NOT NULL AND (
      (nullif(v_existing->>'source','') IS NOT NULL AND v_existing->>'source' IS DISTINCT FROM 'rm_patrol_log_import')
      OR (nullif(v_existing->>'source_sha256','') IS NOT NULL AND v_existing->>'source_sha256' IS DISTINCT FROM v_batch.source_sha256)
      OR (nullif(v_existing->>'derivative_sha256','') IS NOT NULL AND v_existing->>'derivative_sha256' IS DISTINCT FROM v_derivative_hash)
      OR (nullif(v_existing->>'source_file','') IS NOT NULL AND v_existing->>'source_file' IS DISTINCT FROM v_row->'payload'->>'source_file')
      OR (nullif(v_existing->>'source_sheet','') IS NOT NULL AND v_existing->>'source_sheet' IS DISTINCT FROM v_row->'payload'->>'source_sheet')
      OR (nullif(v_existing->>'source_row','') IS NOT NULL AND v_existing->>'source_row' IS DISTINCT FROM v_row->'payload'->>'source_row')
    ) THEN RAISE EXCEPTION 'Location event immutable provenance conflict requires reconciliation'; END IF;
  END LOOP;

  FOR v_row IN SELECT * FROM jsonb_array_elements(v_proposals) LOOP
    IF v_row->'source_values'->>'source_sha256' IS DISTINCT FROM v_batch.source_sha256
      OR v_row->'source_values'->>'derivative_sha256' IS DISTINCT FROM v_derivative_hash
      OR nullif(v_row->'source_values'->>'source_file','') IS NULL
      OR coalesce(v_row->'source_values'->>'source_row','') !~ '^[1-9][0-9]*$'
      OR v_row->'source_values'->>'source_profile' IS DISTINCT FROM v_profile_code THEN
      RAISE EXCEPTION 'Proposal row provenance is incomplete or does not match its batch';
    END IF;
  END LOOP;

  RETURN QUERY SELECT * FROM public.stage_patrol_import_chunk_contract_scoped(
    p_batch_id,p_provider_organization_id,p_client_organization_id,v_observations,v_events,v_proposals
  );
END;
$function$;
REVOKE ALL ON FUNCTION "public"."stage_patrol_import_chunk"(p_batch_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_observations jsonb, p_events jsonb, p_proposals jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."stage_patrol_import_chunk"(p_batch_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_observations jsonb, p_events jsonb, p_proposals jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."stage_patrol_import_chunk"(p_batch_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_observations jsonb, p_events jsonb, p_proposals jsonb) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."stage_patrol_import_chunk"(p_batch_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_observations jsonb, p_events jsonb, p_proposals jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."stage_patrol_import_chunk_contract_scoped"(p_batch_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_observations jsonb, p_events jsonb, p_proposals jsonb)
 RETURNS TABLE(obs_inserted integer, obs_matched integer, evt_inserted integer, evt_matched integer, proposal_candidates integer, proposals_inserted integer, proposals_existing integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_batch public.file_import_batches%rowtype;
  v_row jsonb;
  v_zone_id uuid;
  v_site_id uuid;
  v_key text;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_tenant_import_admin(p_provider_organization_id) THEN RAISE EXCEPTION 'Tenant import administrator required'; END IF;
  IF jsonb_typeof(p_observations)<>'array' OR jsonb_typeof(p_events)<>'array' OR jsonb_typeof(p_proposals)<>'array' THEN RAISE EXCEPTION 'Import chunk values must be arrays'; END IF;
  SELECT * INTO v_batch FROM public.file_import_batches WHERE id=p_batch_id;
  IF NOT FOUND OR v_batch.organization_id<>p_provider_organization_id OR v_batch.status<>'staging' THEN RAISE EXCEPTION 'Open provider import batch required'; END IF;
  IF v_batch.source_sha256 IS NULL OR v_batch.manifest_json->>'target_client_organization_id' IS DISTINCT FROM p_client_organization_id::text THEN RAISE EXCEPTION 'Import batch provenance or client scope is invalid'; END IF;
  IF NOT EXISTS(
    SELECT 1 FROM public.service_agreements agreement
    JOIN public.service_agreement_modules module ON module.service_agreement_id=agreement.id AND module.module_key='patrol' AND module.enabled
    WHERE agreement.provider_organization_id=p_provider_organization_id
      AND agreement.client_organization_id=p_client_organization_id
      AND agreement.agreement_type='operational'
      AND (agreement.starts_on IS NULL OR agreement.starts_on<=current_date)
      AND (agreement.ends_on IS NULL OR agreement.ends_on>=current_date)
  ) THEN RAISE EXCEPTION 'Active contracted patrol module required'; END IF;

  FOR v_row IN SELECT * FROM jsonb_array_elements(p_observations) LOOP
    v_zone_id:=NULLIF(v_row->>'zone_id','')::uuid;v_site_id:=NULLIF(v_row->>'site_id','')::uuid;
    IF v_row->'payload'->>'source_sha256' IS DISTINCT FROM v_batch.source_sha256 THEN RAISE EXCEPTION 'Observation source hash does not match its batch'; END IF;
    IF NOT EXISTS(
      SELECT 1 FROM public.service_agreements agreement
      JOIN public.service_agreement_modules module ON module.service_agreement_id=agreement.id AND module.module_key='patrol' AND module.enabled
      JOIN public.service_agreement_locations location ON location.service_agreement_id=agreement.id AND location.status='active'
      WHERE agreement.provider_organization_id=p_provider_organization_id AND agreement.client_organization_id=p_client_organization_id
        AND agreement.agreement_type='operational' AND (agreement.starts_on IS NULL OR agreement.starts_on<=current_date) AND (agreement.ends_on IS NULL OR agreement.ends_on>=current_date)
        AND ((v_zone_id IS NOT NULL AND location.zone_id=v_zone_id) OR (v_site_id IS NOT NULL AND location.site_id=v_site_id))
    ) THEN RAISE EXCEPTION 'Observation place is outside contracted patrol coverage'; END IF;
    IF EXISTS(
      SELECT 1 FROM public.observations observation
      WHERE observation.organization_id=p_client_organization_id AND observation.external_refs->>'external_ref'=v_row->>'external_ref'
        AND observation.external_refs->'import'->>'source' IS DISTINCT FROM 'rm_patrol_log_import'
    ) THEN RAISE EXCEPTION 'Observation external reference is not owned by this importer'; END IF;
  END LOOP;

  FOR v_row IN SELECT * FROM jsonb_array_elements(p_events) LOOP
    v_zone_id:=NULLIF(v_row->>'zone_id','')::uuid;v_site_id:=NULLIF(v_row->>'site_id','')::uuid;
    IF v_row->'payload'->>'source_sha256' IS DISTINCT FROM v_batch.source_sha256 THEN RAISE EXCEPTION 'Location event source hash does not match its batch'; END IF;
    IF NOT EXISTS(
      SELECT 1 FROM public.service_agreements agreement
      JOIN public.service_agreement_modules module ON module.service_agreement_id=agreement.id AND module.module_key='patrol' AND module.enabled
      JOIN public.service_agreement_locations location ON location.service_agreement_id=agreement.id AND location.status='active'
      WHERE agreement.provider_organization_id=p_provider_organization_id AND agreement.client_organization_id=p_client_organization_id
        AND agreement.agreement_type='operational' AND (agreement.starts_on IS NULL OR agreement.starts_on<=current_date) AND (agreement.ends_on IS NULL OR agreement.ends_on>=current_date)
        AND ((v_zone_id IS NOT NULL AND location.zone_id=v_zone_id) OR (v_site_id IS NOT NULL AND location.site_id=v_site_id))
    ) THEN RAISE EXCEPTION 'Location event place is outside contracted patrol coverage'; END IF;
    IF EXISTS(
      SELECT 1 FROM public.location_events event
      WHERE event.organization_id=p_client_organization_id AND event.external_ref=v_row->>'external_ref'
        AND event.source IS DISTINCT FROM 'rm_patrol_log_import'
    ) THEN RAISE EXCEPTION 'Location event external reference is not owned by this importer'; END IF;
  END LOOP;

  FOR v_row IN SELECT * FROM jsonb_array_elements(p_proposals) LOOP
    IF v_row->'source_values'->>'source_sha256' IS DISTINCT FROM v_batch.source_sha256 THEN RAISE EXCEPTION 'Proposal source hash does not match its batch'; END IF;
  END LOOP;

  FOR v_key IN
    SELECT lock_key FROM (
      SELECT 'evidence:'||(value->>'external_ref') AS lock_key FROM jsonb_array_elements(p_observations) value
      UNION SELECT 'evidence:'||(value->>'external_ref') FROM jsonb_array_elements(p_events) value
    ) keys WHERE nullif(lock_key,'') IS NOT NULL ORDER BY lock_key
  LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended(p_client_organization_id::text||':'||v_key,0));
  END LOOP;
  FOR v_key IN
    SELECT DISTINCT 'vehicle:'||upper(value->>'plate') AS lock_key
    FROM jsonb_array_elements(p_observations) value
    WHERE nullif(value->>'plate','') IS NOT NULL ORDER BY lock_key
  LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended(v_key,0));
  END LOOP;

  RETURN QUERY SELECT * FROM public.stage_patrol_import_chunk_unlocked(
    p_batch_id,p_provider_organization_id,p_client_organization_id,p_observations,p_events,p_proposals
  );
END;
$function$;
REVOKE ALL ON FUNCTION "public"."stage_patrol_import_chunk_contract_scoped"(p_batch_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_observations jsonb, p_events jsonb, p_proposals jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."stage_patrol_import_chunk_contract_scoped"(p_batch_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_observations jsonb, p_events jsonb, p_proposals jsonb) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."stage_patrol_import_chunk_unlocked"(p_batch_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_observations jsonb, p_events jsonb, p_proposals jsonb)
 RETURNS TABLE(obs_inserted integer, obs_matched integer, evt_inserted integer, evt_matched integer, proposal_candidates integer, proposals_inserted integer, proposals_existing integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_batch public.file_import_batches%rowtype;
  v_obs jsonb; v_evt jsonb; v_proposal jsonb;
  v_existing_obs public.observations%rowtype; v_existing_evt public.location_events%rowtype;
  v_vehicle_id uuid; v_plate text; v_zone_id uuid; v_site_id uuid; v_officer_id uuid;
  v_distance numeric; v_rows integer;
  v_obs_inserted integer := 0; v_obs_matched integer := 0;
  v_evt_inserted integer := 0; v_evt_matched integer := 0; v_proposals_inserted integer := 0;
  v_source_hash text;
BEGIN
  IF v_actor IS NULL OR NOT public.is_tenant_import_admin(p_provider_organization_id) THEN RAISE EXCEPTION 'Tenant import administrator required'; END IF;
  SELECT * INTO v_batch FROM public.file_import_batches WHERE id = p_batch_id FOR UPDATE;
  IF NOT FOUND OR v_batch.organization_id <> p_provider_organization_id OR v_batch.status <> 'staging' THEN RAISE EXCEPTION 'Open provider import batch required'; END IF;
  IF v_batch.manifest_json->>'target_client_organization_id' <> p_client_organization_id::text THEN RAISE EXCEPTION 'Import batch client mismatch'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.service_agreements agreement
    WHERE agreement.provider_organization_id = p_provider_organization_id
      AND agreement.client_organization_id = p_client_organization_id
      AND agreement.agreement_type = 'operational'
      AND (agreement.starts_on IS NULL OR agreement.starts_on <= current_date)
      AND (agreement.ends_on IS NULL OR agreement.ends_on >= current_date)
  ) THEN RAISE EXCEPTION 'Active operational provider-client agreement required'; END IF;
  IF jsonb_typeof(p_observations) <> 'array' OR jsonb_typeof(p_events) <> 'array' OR jsonb_typeof(p_proposals) <> 'array' THEN RAISE EXCEPTION 'Import chunk values must be arrays'; END IF;
  v_source_hash := v_batch.source_sha256;

  FOR v_obs IN SELECT * FROM jsonb_array_elements(p_observations) LOOP
    v_zone_id := NULLIF(v_obs->>'zone_id', '')::uuid;
    v_site_id := NULLIF(v_obs->>'site_id', '')::uuid;
    v_officer_id := NULLIF(v_obs->>'officer_id', '')::uuid;
    IF v_zone_id IS NULL AND v_site_id IS NULL THEN RAISE EXCEPTION 'Observation import requires a resolved place'; END IF;
    IF v_obs->'payload'->>'source_sha256' <> v_source_hash THEN RAISE EXCEPTION 'Observation source hash does not match its batch'; END IF;
    IF NOT EXISTS (SELECT 1 FROM public.user_profiles profile WHERE profile.id = v_officer_id AND profile.deactivated_at IS NULL AND (profile.organization_id = p_provider_organization_id OR profile.employer_organization_id = p_provider_organization_id)) THEN RAISE EXCEPTION 'Observation officer does not belong to the provider'; END IF;
    IF v_zone_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.location_zones zone WHERE zone.id = v_zone_id AND zone.organization_id = p_client_organization_id) THEN RAISE EXCEPTION 'Observation zone does not belong to the client'; END IF;
    IF v_site_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.client_sites site WHERE site.id = v_site_id AND (site.client_organization_id = p_client_organization_id OR site.organization_id = p_client_organization_id)) THEN RAISE EXCEPTION 'Observation site does not belong to the client'; END IF;

    SELECT * INTO v_existing_obs FROM public.observations
    WHERE organization_id = p_client_organization_id AND external_refs->>'external_ref' = v_obs->>'external_ref'
    FOR UPDATE;
    IF FOUND THEN
      IF nullif(v_existing_obs.external_refs->'import'->>'source_sha256', '') IS NOT NULL
         AND v_existing_obs.external_refs->'import'->>'source_sha256' <> v_source_hash THEN RAISE EXCEPTION 'Observation source version conflict requires reconciliation'; END IF;
      IF v_existing_obs.officer_id <> v_officer_id OR upper(v_existing_obs.plate_number) <> upper(v_obs->>'plate')
         OR v_existing_obs.zone_id IS DISTINCT FROM v_zone_id OR v_existing_obs.site_id IS DISTINCT FROM v_site_id
         OR v_existing_obs.observed_at <> (v_obs->>'occurred_at')::timestamptz THEN RAISE EXCEPTION 'Observation core fields conflict with existing evidence'; END IF;
      v_distance := CASE WHEN v_obs->'payload'->>'job_kms' ~ '^[0-9]+([.][0-9]+)?$' THEN (v_obs->'payload'->>'job_kms')::numeric ELSE NULL END;
      UPDATE public.observations SET
        external_refs = jsonb_set(coalesce(external_refs, '{}'::jsonb), '{import}', coalesce(external_refs->'import', '{}'::jsonb) || jsonb_strip_nulls(v_obs->'payload'), true),
        distance_km = coalesce(distance_km, v_distance)
      WHERE id = v_existing_obs.id;
      v_obs_matched := v_obs_matched + 1;
    ELSE
      v_plate := v_obs->>'plate';
      SELECT id INTO v_vehicle_id FROM public.canonical_vehicles WHERE upper(plate_number) = upper(v_plate) LIMIT 1;
      IF v_vehicle_id IS NULL THEN INSERT INTO public.canonical_vehicles(plate_number, compliance_source) VALUES(v_plate, 'canonical') RETURNING id INTO v_vehicle_id; END IF;
      INSERT INTO public.observations(organization_id, officer_id, plate_number, zone_id, site_id, observed_at, module_key, canonical_vehicle_id, officer_notes, plate_source, external_refs, distance_km)
      VALUES(p_client_organization_id, v_officer_id, v_plate, v_zone_id, v_site_id, (v_obs->>'occurred_at')::timestamptz, 'patrol', v_vehicle_id, v_obs->>'officer_notes', 'manual',
        jsonb_build_object('external_ref', v_obs->>'external_ref', 'import', v_obs->'payload'),
        CASE WHEN v_obs->'payload'->>'job_kms' ~ '^[0-9]+([.][0-9]+)?$' THEN (v_obs->'payload'->>'job_kms')::numeric ELSE NULL END);
      v_obs_inserted := v_obs_inserted + 1;
    END IF;
  END LOOP;

  FOR v_evt IN SELECT * FROM jsonb_array_elements(p_events) LOOP
    v_zone_id := NULLIF(v_evt->>'zone_id', '')::uuid;
    v_site_id := NULLIF(v_evt->>'site_id', '')::uuid;
    v_officer_id := NULLIF(v_evt->>'observed_entity_id', '')::uuid;
    IF v_zone_id IS NULL AND v_site_id IS NULL THEN RAISE EXCEPTION 'Location event import requires a resolved place'; END IF;
    IF v_evt->'payload'->>'source_sha256' <> v_source_hash THEN RAISE EXCEPTION 'Location event source hash does not match its batch'; END IF;
    IF v_officer_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.user_profiles profile WHERE profile.id = v_officer_id AND profile.deactivated_at IS NULL AND (profile.organization_id = p_provider_organization_id OR profile.employer_organization_id = p_provider_organization_id)) THEN RAISE EXCEPTION 'Location event staff does not belong to the provider'; END IF;
    IF v_zone_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.location_zones zone WHERE zone.id = v_zone_id AND zone.organization_id = p_client_organization_id) THEN RAISE EXCEPTION 'Location event zone does not belong to the client'; END IF;
    IF v_site_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.client_sites site WHERE site.id = v_site_id AND (site.client_organization_id = p_client_organization_id OR site.organization_id = p_client_organization_id)) THEN RAISE EXCEPTION 'Location event site does not belong to the client'; END IF;

    SELECT * INTO v_existing_evt FROM public.location_events
    WHERE organization_id = p_client_organization_id AND external_ref = v_evt->>'external_ref'
    FOR UPDATE;
    IF FOUND THEN
      IF nullif(v_existing_evt.payload->>'source_sha256', '') IS NOT NULL AND v_existing_evt.payload->>'source_sha256' <> v_source_hash THEN RAISE EXCEPTION 'Location event source version conflict requires reconciliation'; END IF;
      IF v_existing_evt.zone_id IS DISTINCT FROM v_zone_id OR v_existing_evt.client_site_id IS DISTINCT FROM v_site_id
         OR v_existing_evt.observed_entity_id IS DISTINCT FROM v_officer_id
         OR v_existing_evt.occurred_at <> (v_evt->>'occurred_at')::timestamptz THEN RAISE EXCEPTION 'Location event core fields conflict with existing evidence'; END IF;
      v_distance := CASE WHEN v_evt->'payload'->>'job_kms' ~ '^[0-9]+([.][0-9]+)?$' THEN (v_evt->'payload'->>'job_kms')::numeric ELSE NULL END;
      UPDATE public.location_events SET payload = coalesce(payload, '{}'::jsonb) || jsonb_strip_nulls(v_evt->'payload'), distance_km = coalesce(distance_km, v_distance) WHERE id = v_existing_evt.id;
      v_evt_matched := v_evt_matched + 1;
    ELSE
      PERFORM public.create_location_event(
        p_organization_id => p_client_organization_id, p_event_type => v_evt->>'event_type', p_client_site_id => v_site_id, p_zone_id => v_zone_id,
        p_module_key => 'patrol', p_occurred_at => (v_evt->>'occurred_at')::timestamptz, p_status => v_evt->>'status',
        p_source => 'rm_patrol_log_import', p_external_ref => v_evt->>'external_ref', p_payload => v_evt->'payload',
        p_observed_entity_type => v_evt->>'observed_entity_type', p_observed_entity_id => v_officer_id,
        p_provider_organization_id => p_provider_organization_id, p_client_organization_id => p_client_organization_id
      );
      IF v_evt->'payload'->>'job_kms' ~ '^[0-9]+([.][0-9]+)?$' THEN UPDATE public.location_events SET distance_km = (v_evt->'payload'->>'job_kms')::numeric WHERE organization_id = p_client_organization_id AND external_ref = v_evt->>'external_ref'; END IF;
      v_evt_inserted := v_evt_inserted + 1;
    END IF;
  END LOOP;

  FOR v_proposal IN SELECT * FROM jsonb_array_elements(p_proposals) LOOP
    IF v_proposal->>'target_type' NOT IN ('workshop_work_order', 'finance_service_cost') THEN RAISE EXCEPTION 'Unsupported import proposal target'; END IF;
    IF v_proposal->'source_values'->>'source_sha256' <> v_source_hash THEN RAISE EXCEPTION 'Proposal source hash does not match its batch'; END IF;
    IF v_proposal->'proposed_payload'->>'organization_id' <> p_provider_organization_id::text OR v_proposal->'proposed_payload'->>'client_organization_id' <> p_client_organization_id::text THEN RAISE EXCEPTION 'Proposal organization scope mismatch'; END IF;
    IF v_proposal->>'target_type' = 'workshop_work_order' THEN
      IF NOT EXISTS (SELECT 1 FROM public.reference_codes code WHERE code.id = (v_proposal->'proposed_payload'->>'work_subject_code_id')::uuid AND code.organization_id = p_provider_organization_id AND code.code_type = 'work_subject' AND code.is_active) THEN RAISE EXCEPTION 'Proposal work subject is invalid'; END IF;
      IF NOT EXISTS (SELECT 1 FROM public.reference_codes code WHERE code.id = (v_proposal->'proposed_payload'->>'work_activity_code_id')::uuid AND code.organization_id = p_provider_organization_id AND code.code_type = 'work_activity' AND code.is_active) THEN RAISE EXCEPTION 'Proposal work activity is invalid'; END IF;
    END IF;
    INSERT INTO public.file_import_row_proposals(organization_id,batch_id,source_record_key,source_row_number,target_type,proposed_payload,source_values,confidence,created_by)
    VALUES(p_provider_organization_id,p_batch_id,v_proposal->>'source_record_key',NULLIF(v_proposal->>'source_row_number','')::integer,v_proposal->>'target_type',v_proposal->'proposed_payload',v_proposal->'source_values',NULLIF(v_proposal->>'confidence','')::numeric,v_actor)
    ON CONFLICT(batch_id,source_record_key,target_type) DO NOTHING;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    v_proposals_inserted := v_proposals_inserted + v_rows;
  END LOOP;

  RETURN QUERY SELECT v_obs_inserted, v_obs_matched, v_evt_inserted, v_evt_matched,
    jsonb_array_length(p_proposals), v_proposals_inserted, jsonb_array_length(p_proposals) - v_proposals_inserted;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."stage_patrol_import_chunk_unlocked"(p_batch_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_observations jsonb, p_events jsonb, p_proposals jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."stage_patrol_import_chunk_unlocked"(p_batch_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_observations jsonb, p_events jsonb, p_proposals jsonb) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."start_ad_hoc_officer_shift"(p_work_unit_id uuid, p_module_key text, p_location_id uuid DEFAULT NULL::uuid, p_zone_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text)
 RETURNS shifts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_profile public.user_profiles%rowtype;
  v_unit public.roster_work_units%rowtype;
  v_shift public.shifts%rowtype;
  v_now timestamptz := clock_timestamp();
BEGIN
  SELECT * INTO v_profile FROM public.user_profiles
  WHERE id = v_actor AND deactivated_at IS NULL AND role IN ('officer', 'admin_officer') FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Active officer profile required'; END IF;
  SELECT * INTO v_unit FROM public.roster_work_units
  WHERE id = p_work_unit_id AND organization_id = v_profile.organization_id AND active FOR SHARE;
  IF NOT FOUND OR v_unit.service_type IS DISTINCT FROM p_module_key THEN
    RAISE EXCEPTION 'Authorized active work unit/module required';
  END IF;
  IF EXISTS (SELECT 1 FROM public.shifts WHERE officer_user_id = v_actor AND status = 'in_progress') THEN
    RAISE EXCEPTION 'Officer already has an active shift';
  END IF;
  IF p_location_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.locations l WHERE l.id = p_location_id AND (
      l.organization_id = v_profile.organization_id
      OR EXISTS (SELECT 1 FROM public.client_sites s WHERE s.location_id = l.id AND public.has_location_access(s.id, NULL))
      OR EXISTS (SELECT 1 FROM public.location_zones z WHERE z.location_id = l.id AND public.has_location_access(NULL, z.id))
    )
  ) THEN RAISE EXCEPTION 'Work location is not authorised'; END IF;
  IF p_zone_id IS NOT NULL AND NOT public.has_location_access(NULL, p_zone_id) THEN
    RAISE EXCEPTION 'Work zone is not authorised';
  END IF;
  SELECT * INTO v_shift FROM public.shifts
  WHERE officer_user_id = v_actor AND work_unit_id = v_unit.id AND shift_origin = 'ad_hoc'
    AND status = 'scheduled' AND scheduled_end > v_now
  ORDER BY created_at DESC LIMIT 1 FOR UPDATE;
  IF FOUND THEN RETURN v_shift; END IF;
  INSERT INTO public.shifts (
    organization_id, officer_user_id, service_type, location_id, zone_id,
    patrol_route_id, service_agreement_location_id, service_agreement_module_id,
    scheduled_start, scheduled_end, status, notes, work_unit_id, module_key, shift_origin
  ) VALUES (
    v_profile.organization_id, v_actor, p_module_key, p_location_id, p_zone_id,
    v_unit.patrol_route_id, v_unit.service_agreement_location_id, v_unit.service_agreement_module_id,
    v_now, v_now + interval '12 hours', 'scheduled', nullif(trim(p_notes), ''), p_work_unit_id, p_module_key, 'ad_hoc'
  ) RETURNING * INTO v_shift;
  IF v_unit.patrol_route_id IS NOT NULL THEN
    PERFORM public.generate_shift_stops(v_shift.id, (v_now AT TIME ZONE 'Pacific/Auckland')::date);
  END IF;
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_profile.organization_id, v_actor, 'officer_ad_hoc_shift_prepared', 'shifts', v_shift.id,
    jsonb_build_object('work_unit_id', p_work_unit_id, 'module_key', p_module_key, 'safety_check_required', true));
  SELECT * INTO v_shift FROM public.shifts WHERE id = v_shift.id;
  RETURN v_shift;
END;
$function$;
COMMENT ON FUNCTION "public"."start_ad_hoc_officer_shift"(p_work_unit_id uuid, p_module_key text, p_location_id uuid, p_zone_id uuid, p_notes text) IS 'Prepares a scheduled ad-hoc shift with its work-unit contract/route and stops. The officer then reads risks, acknowledges and starts through start_officer_shift. Reuses an unstarted shift on retry.';
REVOKE ALL ON FUNCTION "public"."start_ad_hoc_officer_shift"(p_work_unit_id uuid, p_module_key text, p_location_id uuid, p_zone_id uuid, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."start_ad_hoc_officer_shift"(p_work_unit_id uuid, p_module_key text, p_location_id uuid, p_zone_id uuid, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."start_ad_hoc_officer_shift"(p_work_unit_id uuid, p_module_key text, p_location_id uuid, p_zone_id uuid, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."start_ad_hoc_officer_shift"(p_work_unit_id uuid, p_module_key text, p_location_id uuid, p_zone_id uuid, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."start_finance_external_oauth"(p_request_id uuid, p_state_hash text, p_state_expires_at timestamp with time zone, p_adapter_name text)
 RETURNS finance_external_connection_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_request public.finance_external_connection_requests%rowtype;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'OAuth adapter execution only'; END IF;
  IF nullif(trim(p_state_hash), '') IS NULL OR p_state_expires_at <= now() OR nullif(trim(p_adapter_name), '') IS NULL THEN RAISE EXCEPTION 'Invalid OAuth start parameters'; END IF;
  SELECT * INTO v_request FROM public.finance_external_connection_requests WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Finance connection request not found'; END IF;
  IF v_request.status NOT IN ('awaiting_authorisation','requested','connected','failed') THEN RAISE EXCEPTION 'Connection request is not available for OAuth'; END IF;
  UPDATE public.finance_external_connection_requests SET status = 'awaiting_authorisation', adapter_name = p_adapter_name, oauth_state_hash = p_state_hash, oauth_state_expires_at = p_state_expires_at, oauth_started_at = now(), last_error = NULL, updated_at = now() WHERE id = p_request_id RETURNING * INTO v_request;
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata) VALUES (v_request.organization_id, NULL, 'finance_external_oauth_started', 'finance_external_connection_requests', v_request.id, jsonb_build_object('provider_type', v_request.provider_type, 'adapter_name', p_adapter_name, 'reauthorisation', true));
  RETURN v_request;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."start_finance_external_oauth"(p_request_id uuid, p_state_hash text, p_state_expires_at timestamp with time zone, p_adapter_name text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."start_finance_external_oauth"(p_request_id uuid, p_state_hash text, p_state_expires_at timestamp with time zone, p_adapter_name text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."start_finance_external_oauth"(p_request_id uuid, p_state_hash text, p_state_expires_at timestamp with time zone, p_adapter_name text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."start_officer_shift"(p_client_request_id uuid, p_shift_id uuid, p_expected_status text, p_gps_lat double precision DEFAULT NULL::double precision, p_gps_lng double precision DEFAULT NULL::double precision, p_off_site_reason text DEFAULT NULL::text)
 RETURNS TABLE(shift_id uuid, shift_status text, started_at timestamp with time zone, created boolean, position_status text, place_name text, distance_m numeric, superseded_shift_id uuid, superseded_service_type text, superseded_started_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  c_start_window constant interval := interval '60 minutes';
  v_actor uuid := auth.uid();
  v_shift public.shifts%rowtype;
  v_at timestamptz := now();
  v_position jsonb;
  v_reason text := nullif(trim(coalesce(p_off_site_reason, '')), '');
  v_prev_id uuid;
  v_prev_type text;
  v_prev_started timestamptz;
  v_is_admin boolean;
begin
  if p_client_request_id is null then
    raise exception 'client_request_id is required';
  end if;

  select s.* into v_shift from public.shifts s where s.id = p_shift_id for update;
  if not found then
    raise exception 'Shift not found';
  end if;

  v_is_admin := public.is_admin_for_org(v_shift.organization_id);
  if v_shift.officer_user_id <> v_actor and not v_is_admin then
    raise exception 'Only the assigned officer or an administrator can start this shift';
  end if;

  if v_shift.status = 'in_progress' and v_shift.actual_start is not null then
    return query select v_shift.id, v_shift.status, v_shift.actual_start, false, null::text, null::text, null::numeric, null::uuid, null::text, null::timestamptz;
    return;
  end if;

  if v_shift.status <> p_expected_status then
    raise exception 'Shift changed from expected status % to %', p_expected_status, v_shift.status;
  end if;

  if v_shift.status not in ('scheduled', 'published', 'accepted') then
    raise exception 'Shift cannot be started from status %', v_shift.status;
  end if;

  if not v_is_admin and v_shift.scheduled_start - v_at > c_start_window then
    raise exception 'Too early to start this shift: it is rostered for later. You can start it from an hour before its rostered start.'
      using errcode = 'P0001', hint = format('opens_at=%s', to_char((v_shift.scheduled_start - c_start_window) at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'));
  end if;

  v_position := public.evaluate_shift_start_position(v_shift.id, p_gps_lat, p_gps_lng);

  -- The shift this start will stop (the shifts_one_at_a_time trigger does the stopping and its audit).
  select s.id, s.service_type, s.actual_start into v_prev_id, v_prev_type, v_prev_started
  from public.shifts s
  where s.officer_user_id = v_shift.officer_user_id and s.status = 'in_progress' and s.id <> v_shift.id
  order by s.actual_start desc nulls last
  limit 1;

  update public.shifts
  set status = 'in_progress', actual_start = coalesce(actual_start, v_at), updated_at = v_at
  where id = v_shift.id
  returning * into v_shift;

  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (
    v_shift.organization_id, v_actor, 'officer_shift_started', 'shifts', v_shift.id,
    jsonb_build_object(
      'previous_status', p_expected_status,
      'actual_start', v_shift.actual_start,
      'scheduled_start', v_shift.scheduled_start,
      'started_early_by_minutes', greatest(0, floor(extract(epoch from (v_shift.scheduled_start - v_shift.actual_start)) / 60))::integer,
      'gps_lat', p_gps_lat,
      'gps_lng', p_gps_lng,
      'start_position', v_position,
      'off_site_reason', v_reason,
      'superseded_shift_id', v_prev_id,
      'client_request_id', p_client_request_id
    )
  );

  return query select v_shift.id, v_shift.status, v_shift.actual_start, true,
    v_position->>'status', v_position->>'place_name', (v_position->>'distance_m')::numeric,
    v_prev_id, v_prev_type, v_prev_started;
end;
$function$;
COMMENT ON FUNCTION "public"."start_officer_shift"(p_client_request_id uuid, p_shift_id uuid, p_expected_status text, p_gps_lat double precision, p_gps_lng double precision, p_off_site_reason text) IS 'Starts the officer''s shift from an hour before its rostered start (administrators are not bound by the window). Records the start position (advisory, never a gate) and any off-site reason. One shift at a time: an earlier in-progress shift is stopped by the shifts_one_at_a_time trigger and named in the receipt (superseded_shift_id).';
REVOKE ALL ON FUNCTION "public"."start_officer_shift"(p_client_request_id uuid, p_shift_id uuid, p_expected_status text, p_gps_lat double precision, p_gps_lng double precision, p_off_site_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."start_officer_shift"(p_client_request_id uuid, p_shift_id uuid, p_expected_status text, p_gps_lat double precision, p_gps_lng double precision, p_off_site_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."start_officer_shift"(p_client_request_id uuid, p_shift_id uuid, p_expected_status text, p_gps_lat double precision, p_gps_lng double precision, p_off_site_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."start_officer_shift"(p_client_request_id uuid, p_shift_id uuid, p_expected_status text, p_gps_lat double precision, p_gps_lng double precision, p_off_site_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."start_officer_static_shift"(p_client_request_id uuid, p_shift_id uuid, p_expected_status text, p_gps_lat double precision DEFAULT NULL::double precision, p_gps_lng double precision DEFAULT NULL::double precision, p_off_site_reason text DEFAULT NULL::text)
 RETURNS TABLE(shift_id uuid, shift_status text, started_at timestamp with time zone, created boolean, position_status text, place_name text, distance_m numeric, superseded_shift_id uuid, superseded_service_type text, superseded_started_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  perform public.evaluate_static_shift_position(p_shift_id,p_gps_lat,p_gps_lng);
  return query select * from public.start_officer_shift(p_client_request_id,p_shift_id,p_expected_status,p_gps_lat,p_gps_lng,p_off_site_reason);
  perform public.record_static_shift_presence(p_shift_id,'arrive',p_client_request_id,p_gps_lat,p_gps_lng,p_off_site_reason);
end;
$function$;
REVOKE ALL ON FUNCTION "public"."start_officer_static_shift"(p_client_request_id uuid, p_shift_id uuid, p_expected_status text, p_gps_lat double precision, p_gps_lng double precision, p_off_site_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."start_officer_static_shift"(p_client_request_id uuid, p_shift_id uuid, p_expected_status text, p_gps_lat double precision, p_gps_lng double precision, p_off_site_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."start_officer_static_shift"(p_client_request_id uuid, p_shift_id uuid, p_expected_status text, p_gps_lat double precision, p_gps_lng double precision, p_off_site_reason text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."start_patrol_session"(p_shift_id uuid)
 RETURNS patrols
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_profile public.user_profiles%rowtype;v_shift public.shifts%rowtype;v_patrol public.patrols%rowtype;
begin
  if v_actor is null then raise exception 'Authentication required';end if;
  select * into v_profile from public.user_profiles where id=v_actor and deactivated_at is null;
  if not found or v_profile.role not in('grand_master','master','admin','admin_officer','officer') then raise exception 'Active Patrol officer required';end if;
  select * into v_shift from public.shifts where id=p_shift_id for update;
  if not found or v_shift.organization_id is distinct from v_profile.organization_id or v_shift.officer_user_id is distinct from v_actor then raise exception 'Assigned Patrol shift not found';end if;
  if v_shift.status not in('published','accepted','in_progress') then raise exception 'Patrol shift is not active';end if;
  select * into v_patrol from public.patrols where shift_id=v_shift.id and officer_user_id=v_actor and status='in_progress' order by started_at desc limit 1;
  if found then return v_patrol;end if;
  insert into public.patrols(organization_id,shift_id,officer_user_id,zone_id,status,started_at) values(v_shift.organization_id,v_shift.id,v_actor,v_shift.zone_id,'in_progress',clock_timestamp()) returning * into v_patrol;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_patrol.organization_id,v_actor,'patrol.started','patrols',v_patrol.id,jsonb_build_object('shift_id',v_shift.id,'patrol_route_id',v_shift.patrol_route_id));
  return v_patrol;
end;$function$;
REVOKE ALL ON FUNCTION "public"."start_patrol_session"(p_shift_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."start_patrol_session"(p_shift_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."start_patrol_session"(p_shift_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."start_patrol_session"(p_shift_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."start_shift_break"(p_client_request_id uuid, p_shift_id uuid, p_break_type text)
 RETURNS shift_breaks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_shift public.shifts%rowtype;
  v_break public.shift_breaks%rowtype;
begin
  if p_client_request_id is null then
    raise exception 'client_request_id is required';
  end if;

  if p_break_type not in ('rest', 'meal') then
    raise exception 'Break type must be rest or meal';
  end if;

  select s.* into v_shift from public.shifts s where s.id = p_shift_id for update;
  if not found then
    raise exception 'Shift not found';
  end if;

  if v_shift.officer_user_id <> v_actor then
    raise exception 'Only the assigned officer can record a break';
  end if;

  select b.* into v_break from public.shift_breaks b
  where b.organization_id = v_shift.organization_id and b.client_request_id = p_client_request_id;
  if found then
    return v_break;
  end if;

  if v_shift.status <> 'in_progress' then
    raise exception 'Breaks can only be recorded while the shift is in progress';
  end if;

  if exists (select 1 from public.shift_breaks b where b.shift_id = v_shift.id and b.ended_at is null) then
    raise exception 'An open break is already in progress for this shift';
  end if;

  insert into public.shift_breaks(
    organization_id, shift_id, officer_user_id, break_type, started_at, is_paid, client_request_id
  )
  values (
    v_shift.organization_id, v_shift.id, v_actor, p_break_type, now(), p_break_type = 'rest', p_client_request_id
  )
  returning * into v_break;

  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (
    v_shift.organization_id, v_actor, 'shift_break_started', 'shift_breaks', v_break.id,
    jsonb_build_object('shift_id', v_shift.id, 'break_type', p_break_type, 'is_paid', v_break.is_paid)
  );

  return v_break;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."start_shift_break"(p_client_request_id uuid, p_shift_id uuid, p_break_type text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."start_shift_break"(p_client_request_id uuid, p_shift_id uuid, p_break_type text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."start_shift_break"(p_client_request_id uuid, p_shift_id uuid, p_break_type text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."start_shift_break"(p_client_request_id uuid, p_shift_id uuid, p_break_type text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."start_staff_onboarding"(p_client_request_id uuid, p_staff_id uuid, p_assigned_to uuid DEFAULT NULL::uuid, p_target_start date DEFAULT NULL::date, p_note text DEFAULT NULL::text)
 RETURNS staff_onboarding_ledgers
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_staff public.staff_profiles%rowtype;
  v_ledger public.staff_onboarding_ledgers%rowtype;
  v_note text := nullif(trim(coalesce(p_note, '')), '');
begin
  if p_client_request_id is null then raise exception 'client_request_id is required'; end if;
  select sp.* into v_staff from public.staff_profiles sp where sp.id = p_staff_id for update;
  if not found then raise exception 'Staff profile not found'; end if;
  if not public.is_admin_for_org(v_staff.organization_id) then raise exception 'Active HR administrator required'; end if;
  if p_assigned_to is not null and not exists (
    select 1 from public.user_profiles u where u.id = p_assigned_to and u.organization_id = v_staff.organization_id and u.deactivated_at is null
  ) then raise exception 'Onboarding owner must be an active member of this organization'; end if;
  select l.* into v_ledger from public.staff_onboarding_ledgers l where l.staff_id = v_staff.id;
  if found then return v_ledger; end if;
  insert into public.staff_onboarding_ledgers(organization_id, staff_id, assigned_to, target_start, stage_note)
  values (v_staff.organization_id, v_staff.id, p_assigned_to, p_target_start, coalesce(v_note, 'Staff onboarding started'))
  returning * into v_ledger;
  insert into public.staff_onboarding_events(ledger_id, organization_id, to_stage, to_status, note, actor_user_id, version)
  values (v_ledger.id, v_ledger.organization_id, v_ledger.current_stage, v_ledger.status, coalesce(v_note, 'Staff onboarding started'), v_actor, v_ledger.version);
  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (v_ledger.organization_id, v_actor, 'staff_onboarding_started', 'staff_onboarding_ledgers', v_ledger.id,
    jsonb_build_object('staff_id', v_staff.id, 'assigned_to', p_assigned_to, 'target_start', p_target_start, 'client_request_id', p_client_request_id));
  return v_ledger;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."start_staff_onboarding"(p_client_request_id uuid, p_staff_id uuid, p_assigned_to uuid, p_target_start date, p_note text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."start_staff_onboarding"(p_client_request_id uuid, p_staff_id uuid, p_assigned_to uuid, p_target_start date, p_note text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."start_staff_onboarding"(p_client_request_id uuid, p_staff_id uuid, p_assigned_to uuid, p_target_start date, p_note text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."start_staff_onboarding"(p_client_request_id uuid, p_staff_id uuid, p_assigned_to uuid, p_target_start date, p_note text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."submit_access_control_event_receipt"(p_actor_user_id uuid, p_client_request_id uuid, p_observed_at timestamp with time zone, p_site_id uuid, p_zone_id uuid, p_shift_id uuid, p_event_kind text, p_subject_kind text, p_officer_decision text, p_decision_basis text, p_claimed_identity text, p_credential_reference text, p_notes text, p_gps_lat double precision, p_gps_lng double precision, p_geofence_context jsonb, p_evidence_items jsonb, p_recognition jsonb)
 RETURNS TABLE(id uuid, created boolean, received_at timestamp with time zone, evidence_state text, recognition_review_state text, geofence_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_profile public.user_profiles%ROWTYPE;
  v_shift public.shifts%ROWTYPE;
  v_existing public.access_control_events%ROWTYPE;
  v_event public.access_control_events%ROWTYPE;
  v_location_event_id uuid;
  v_evidence jsonb;
  v_evidence_id uuid;
  v_ordinal integer := 0;
  v_has_module boolean := false;
  v_has_place_access boolean := false;
  v_recognition jsonb := '{}'::jsonb;
  v_recognition_state text := 'not_requested';
  v_evidence_state text := 'not_provided';
  v_source_hash text;
  v_site_location_id uuid;
  v_zone_location_id uuid;
BEGIN
  IF coalesce(auth.jwt()->>'role', '') <> 'service_role'
     AND session_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;
  IF p_actor_user_id IS NULL OR p_client_request_id IS NULL THEN
    RAISE EXCEPTION 'Actor and client request id are required';
  END IF;
  IF p_observed_at IS NULL OR p_observed_at > clock_timestamp() + interval '5 minutes' THEN
    RAISE EXCEPTION 'A valid observation time is required';
  END IF;
  IF num_nonnulls(p_site_id, p_zone_id) = 0 THEN
    RAISE EXCEPTION 'A site or zone place anchor is required';
  END IF;
  IF p_event_kind NOT IN (
    'entry_request', 'exit', 'credential_check', 'visitor_arrival', 'door_security_check'
  ) THEN
    RAISE EXCEPTION 'Unsupported access-control event kind';
  END IF;
  IF p_subject_kind NOT IN ('person', 'vehicle', 'mixed', 'unknown') THEN
    RAISE EXCEPTION 'Unsupported access-control subject kind';
  END IF;
  IF p_officer_decision NOT IN ('admitted', 'refused', 'escorted', 'departed', 'record_only') THEN
    RAISE EXCEPTION 'Unsupported officer decision';
  END IF;
  IF p_decision_basis NOT IN (
    'credential_present', 'known_person', 'visitor_authorization',
    'supervisor_authorization', 'safety_refusal', 'policy_refusal',
    'no_decision', 'other'
  ) THEN
    RAISE EXCEPTION 'Unsupported decision basis';
  END IF;
  IF p_officer_decision = 'admitted'
     AND p_decision_basis NOT IN (
       'credential_present', 'known_person', 'visitor_authorization',
       'supervisor_authorization', 'other'
     ) THEN
    RAISE EXCEPTION 'An admitted entry requires an attributable human decision basis';
  END IF;
  IF p_gps_lat IS NOT NULL AND (p_gps_lat < -90 OR p_gps_lat > 90) THEN
    RAISE EXCEPTION 'Latitude is invalid';
  END IF;
  IF p_gps_lng IS NOT NULL AND (p_gps_lng < -180 OR p_gps_lng > 180) THEN
    RAISE EXCEPTION 'Longitude is invalid';
  END IF;
  IF jsonb_typeof(coalesce(p_geofence_context, '{}'::jsonb)) <> 'object' THEN
    RAISE EXCEPTION 'Geofence context must be an object';
  END IF;
  IF jsonb_typeof(coalesce(p_evidence_items, '[]'::jsonb)) <> 'array' THEN
    RAISE EXCEPTION 'Evidence items must be an array';
  END IF;
  IF jsonb_array_length(coalesce(p_evidence_items, '[]'::jsonb)) > 5 THEN
    RAISE EXCEPTION 'No more than five evidence items may be submitted';
  END IF;

  SELECT profile.* INTO v_profile
  FROM public.user_profiles profile
  WHERE profile.id = p_actor_user_id
    AND profile.deactivated_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'Active officer profile required'; END IF;

  IF p_shift_id IS NOT NULL THEN
    SELECT shift_row.* INTO v_shift
    FROM public.shifts shift_row
    WHERE shift_row.id = p_shift_id
      AND shift_row.organization_id = v_profile.organization_id
      AND shift_row.officer_user_id = p_actor_user_id
      AND shift_row.status IN ('scheduled', 'active', 'in_progress');
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Access-control shift is not active for this officer';
    END IF;
  END IF;

  v_has_module :=
    v_profile.role IN ('grand_master', 'master', 'admin', 'admin_officer')
    OR 'access_control' = ANY(v_profile.module_access)
    OR (
      p_shift_id IS NOT NULL
      AND (
        v_shift.module_key = 'access_control'
        OR v_shift.service_type = 'access_control'
      )
    );
  IF NOT v_has_module THEN
    RAISE EXCEPTION 'Access-control standing authority or an active access-control shift is required';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.organization_modules
    WHERE organization_id = v_profile.organization_id
  ) AND NOT EXISTS (
    SELECT 1 FROM public.organization_modules
    WHERE organization_id = v_profile.organization_id
      AND module_key = 'access_control'
      AND enabled
  ) THEN
    RAISE EXCEPTION 'Access Control is not enabled for this organization';
  END IF;

  IF p_site_id IS NOT NULL THEN
    SELECT site.location_id INTO v_site_location_id
    FROM public.client_sites site
    WHERE site.id = p_site_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Access-control site is missing'; END IF;

    v_has_place_access := EXISTS (
      SELECT 1
      FROM public.client_sites site
      WHERE site.id = p_site_id
        AND (
          site.client_organization_id = v_profile.organization_id
          OR EXISTS (
            SELECT 1
            FROM public.service_agreement_locations location
            JOIN public.service_agreements agreement
              ON agreement.id = location.service_agreement_id
            WHERE location.site_id = site.id
              AND location.status = 'active'
              AND agreement.agreement_type = 'operational'
              AND (
                agreement.provider_organization_id = v_profile.organization_id
                OR location.head_contractor_org_id = v_profile.organization_id
              )
          )
        )
    );
  END IF;

  IF p_zone_id IS NOT NULL THEN
    SELECT zone.location_id INTO v_zone_location_id
    FROM public.location_zones zone
    WHERE zone.id = p_zone_id
      AND zone.module_key = 'access_control';
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Access-control zone is missing or belongs to another module';
    END IF;

    v_has_place_access := v_has_place_access OR EXISTS (
      SELECT 1
      FROM public.location_zones zone
      WHERE zone.id = p_zone_id
        AND (
          zone.organization_id = v_profile.organization_id
          OR EXISTS (
            SELECT 1
            FROM public.service_agreement_locations location
            JOIN public.service_agreements agreement
              ON agreement.id = location.service_agreement_id
            WHERE location.zone_id = zone.id
              AND location.status = 'active'
              AND agreement.agreement_type = 'operational'
              AND (
                agreement.provider_organization_id = v_profile.organization_id
                OR location.head_contractor_org_id = v_profile.organization_id
              )
          )
        )
    );
  END IF;

  IF p_site_id IS NOT NULL AND p_zone_id IS NOT NULL
     AND v_site_location_id IS DISTINCT FROM v_zone_location_id THEN
    RAISE EXCEPTION 'Selected site and zone do not describe the same canonical place';
  END IF;
  IF NOT v_has_place_access THEN
    RAISE EXCEPTION 'Officer organization has no active authority at this place';
  END IF;

  SELECT * INTO v_existing
  FROM public.access_control_events
  WHERE organization_id = v_profile.organization_id
    AND client_request_id = p_client_request_id;
  IF FOUND THEN
    RETURN QUERY SELECT
      v_existing.id, false, v_existing.received_at, v_existing.evidence_state,
      v_existing.recognition_review_state,
      coalesce(v_existing.geofence_context->>'resolution_status', 'not_evaluated');
    RETURN;
  END IF;

  IF jsonb_typeof(coalesce(p_recognition, '{}'::jsonb)) = 'object'
     AND coalesce(p_recognition->>'status', 'unavailable') = 'available' THEN
    v_recognition := jsonb_strip_nulls(jsonb_build_object(
      'status', 'available',
      'classification', nullif(trim(p_recognition->>'classification'), ''),
      'confidence', CASE
        WHEN p_recognition->>'confidence' ~ '^[0-9]+([.][0-9]+)?$'
          THEN (p_recognition->>'confidence')::real
      END,
      'details', jsonb_strip_nulls(jsonb_build_object(
        'subject_kind', p_recognition#>>'{details,subject_kind}',
        'person_present', p_recognition#>'{details,person_present}',
        'face_visible', p_recognition#>'{details,face_visible}',
        'credential_visible', p_recognition#>'{details,credential_visible}',
        'vehicle_present', p_recognition#>'{details,vehicle_present}'
      )),
      'probes', CASE
        WHEN jsonb_typeof(p_recognition->'probes') = 'array'
          THEN p_recognition->'probes'
        ELSE '[]'::jsonb
      END,
      'reasoning', nullif(trim(p_recognition->>'reasoning'), ''),
      'classifier', nullif(trim(p_recognition->>'classifier'), ''),
      'provider', nullif(trim(p_recognition->>'provider'), ''),
      'model', nullif(trim(p_recognition->>'model'), ''),
      'prompt_version', nullif(trim(p_recognition->>'prompt_version'), ''),
      'machine_candidate_discovery_permitted', true,
      'machine_identity_confirmation_permitted', false,
      'machine_access_decision_permitted', false
    ));
    v_recognition_state := 'requires_supervisor_review';
  ELSIF jsonb_typeof(coalesce(p_recognition, '{}'::jsonb)) = 'object'
        AND coalesce(p_recognition->>'status', 'not_requested') <> 'not_requested' THEN
    v_recognition := jsonb_build_object(
      'status', 'unavailable',
      'failure_reason', nullif(trim(p_recognition->>'failure_reason'), ''),
      'machine_candidate_discovery_permitted', true,
      'machine_identity_confirmation_permitted', false,
      'machine_access_decision_permitted', false
    );
    v_recognition_state := 'unavailable';
  END IF;

  IF jsonb_array_length(coalesce(p_evidence_items, '[]'::jsonb)) > 0 THEN
    v_evidence_state := 'received';
  END IF;

  INSERT INTO public.access_control_events (
    organization_id, client_request_id, site_id, zone_id, shift_id,
    officer_user_id, observed_at, event_kind, subject_kind,
    officer_decision, decision_basis, claimed_identity, credential_reference,
    notes, gps_lat, gps_lng, geofence_context, evidence_state,
    recognition_summary, recognition_review_state
  ) VALUES (
    v_profile.organization_id, p_client_request_id, p_site_id, p_zone_id, p_shift_id,
    p_actor_user_id, p_observed_at, p_event_kind, p_subject_kind,
    p_officer_decision, p_decision_basis,
    nullif(trim(coalesce(p_claimed_identity, '')), ''),
    nullif(trim(coalesce(p_credential_reference, '')), ''),
    nullif(trim(coalesce(p_notes, '')), ''),
    p_gps_lat, p_gps_lng, coalesce(p_geofence_context, '{}'::jsonb),
    v_evidence_state, v_recognition, v_recognition_state
  )
  RETURNING * INTO v_event;

  INSERT INTO public.location_events (
    organization_id, client_site_id, zone_id, event_type, module_key,
    occurred_at, status, source, external_ref, payload, created_by,
    observed_entity_type
  ) VALUES (
    v_profile.organization_id,
    CASE WHEN p_zone_id IS NULL THEN p_site_id ELSE NULL END,
    p_zone_id,
    'access_control.' || p_event_kind,
    'access_control',
    p_observed_at,
    p_officer_decision,
    'access_control_field',
    'access-control:' || v_event.id::text,
    jsonb_strip_nulls(jsonb_build_object(
      'access_control_event_id', v_event.id,
      'subject_kind', p_subject_kind,
      'officer_decision', p_officer_decision,
      'decision_basis', p_decision_basis,
      'evidence_state', v_evidence_state,
      'recognition_review_state', v_recognition_state,
      'geofence_status', coalesce(p_geofence_context->>'resolution_status', 'not_evaluated')
    )),
    p_actor_user_id,
    CASE WHEN p_subject_kind IN ('person', 'vehicle') THEN p_subject_kind ELSE NULL END
  )
  RETURNING public.location_events.id INTO v_location_event_id;

  UPDATE public.access_control_events
  SET location_event_id = v_location_event_id,
      updated_at = clock_timestamp()
  WHERE public.access_control_events.id = v_event.id;

  FOR v_evidence IN
    SELECT value
    FROM jsonb_array_elements(coalesce(p_evidence_items, '[]'::jsonb))
  LOOP
    IF jsonb_typeof(v_evidence) <> 'object' THEN
      RAISE EXCEPTION 'Each evidence item must be an object';
    END IF;
    v_source_hash := lower(coalesce(
      nullif(v_evidence->>'watermarked_sha256', ''),
      nullif(v_evidence->>'sha256_hash', '')
    ));
    IF v_source_hash !~ '^[0-9a-f]{64}$' THEN
      RAISE EXCEPTION 'Each access-control evidence item requires a SHA-256 hash';
    END IF;
    IF nullif(trim(coalesce(v_evidence->>'watermarked_path', v_evidence->>'storage_path', '')), '') IS NULL THEN
      RAISE EXCEPTION 'Each access-control evidence item requires a storage path';
    END IF;

    INSERT INTO public.evidence_items (
      organization_id, module_key, evidence_kind, storage_path,
      captured_by_user_id, captured_at, sha256_hash, is_court_ready,
      locked_at, retention_reason, location_event_id, metadata
    ) VALUES (
      v_profile.organization_id,
      'access_control',
      coalesce(nullif(trim(v_evidence->>'evidence_kind'), ''), 'photo'),
      coalesce(v_evidence->>'watermarked_path', v_evidence->>'storage_path'),
      p_actor_user_id,
      coalesce((v_evidence->>'captured_at')::timestamptz, p_observed_at),
      v_source_hash,
      true,
      clock_timestamp(),
      'access_control_event_evidence',
      v_location_event_id,
      jsonb_strip_nulls(jsonb_build_object(
        'original_path', v_evidence->>'original_path',
        'watermarked_path', v_evidence->>'watermarked_path',
        'raw_sha256', v_evidence->>'raw_sha256',
        'watermarked_sha256', v_evidence->>'watermarked_sha256',
        'watermark_text', v_evidence->>'watermark_text',
        'watermark_service', v_evidence->>'watermark_service',
        'access_control_event_id', v_event.id,
        'authoritative_source_preserved', true
      ))
    )
    RETURNING public.evidence_items.id INTO v_evidence_id;

    INSERT INTO public.access_control_event_evidence (
      organization_id, access_control_event_id, evidence_item_id, purpose, ordinal
    ) VALUES (
      v_profile.organization_id, v_event.id, v_evidence_id,
      CASE WHEN v_ordinal = 0 THEN 'primary_evidence' ELSE 'supporting_evidence' END,
      v_ordinal
    );
    v_ordinal := v_ordinal + 1;
  END LOOP;

  INSERT INTO public.audit_log (
    organization_id, actor_user_id, action, target_table, target_id, metadata
  ) VALUES (
    v_profile.organization_id, p_actor_user_id, 'access_control_event_recorded',
    'access_control_events', v_event.id,
    jsonb_build_object(
      'event_kind', p_event_kind,
      'subject_kind', p_subject_kind,
      'officer_decision', p_officer_decision,
      'decision_basis', p_decision_basis,
      'site_id', p_site_id,
      'zone_id', p_zone_id,
      'location_event_id', v_location_event_id,
      'evidence_count', v_ordinal,
      'recognition_review_state', v_recognition_state,
      'geofence_status', coalesce(p_geofence_context->>'resolution_status', 'not_evaluated')
    )
  );

  RETURN QUERY SELECT
    v_event.id, true, v_event.received_at, v_evidence_state,
    v_recognition_state,
    coalesce(p_geofence_context->>'resolution_status', 'not_evaluated');
END;
$function$;
COMMENT ON FUNCTION "public"."submit_access_control_event_receipt"(p_actor_user_id uuid, p_client_request_id uuid, p_observed_at timestamp with time zone, p_site_id uuid, p_zone_id uuid, p_shift_id uuid, p_event_kind text, p_subject_kind text, p_officer_decision text, p_decision_basis text, p_claimed_identity text, p_credential_reference text, p_notes text, p_gps_lat double precision, p_gps_lng double precision, p_geofence_context jsonb, p_evidence_items jsonb, p_recognition jsonb) IS 'Service-only, replay-safe access-control field write. Records the officer action, place event, evidence custody, and advisory recognition separately. Recognition never grants access.';
REVOKE ALL ON FUNCTION "public"."submit_access_control_event_receipt"(p_actor_user_id uuid, p_client_request_id uuid, p_observed_at timestamp with time zone, p_site_id uuid, p_zone_id uuid, p_shift_id uuid, p_event_kind text, p_subject_kind text, p_officer_decision text, p_decision_basis text, p_claimed_identity text, p_credential_reference text, p_notes text, p_gps_lat double precision, p_gps_lng double precision, p_geofence_context jsonb, p_evidence_items jsonb, p_recognition jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."submit_access_control_event_receipt"(p_actor_user_id uuid, p_client_request_id uuid, p_observed_at timestamp with time zone, p_site_id uuid, p_zone_id uuid, p_shift_id uuid, p_event_kind text, p_subject_kind text, p_officer_decision text, p_decision_basis text, p_claimed_identity text, p_credential_reference text, p_notes text, p_gps_lat double precision, p_gps_lng double precision, p_geofence_context jsonb, p_evidence_items jsonb, p_recognition jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."submit_access_control_event_receipt"(p_actor_user_id uuid, p_client_request_id uuid, p_observed_at timestamp with time zone, p_site_id uuid, p_zone_id uuid, p_shift_id uuid, p_event_kind text, p_subject_kind text, p_officer_decision text, p_decision_basis text, p_claimed_identity text, p_credential_reference text, p_notes text, p_gps_lat double precision, p_gps_lng double precision, p_geofence_context jsonb, p_evidence_items jsonb, p_recognition jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."submit_biosecurity_assessment_receipt"(p_client_request_id uuid, p_assessed_at timestamp with time zone, p_species_name text DEFAULT NULL::text, p_density_estimate text DEFAULT 'scattered'::text, p_action_taken text DEFAULT 'no_action'::text, p_scene_description text DEFAULT NULL::text, p_location_name text DEFAULT NULL::text, p_protected_land_address text DEFAULT NULL::text, p_protected_land_site_id uuid DEFAULT NULL::uuid, p_notice_number text DEFAULT NULL::text, p_mpi_referral_number text DEFAULT NULL::text, p_follow_up_required boolean DEFAULT false, p_shift_id uuid DEFAULT NULL::uuid, p_dispatch_job_id uuid DEFAULT NULL::uuid, p_evidence_items jsonb DEFAULT '[]'::jsonb, p_classification jsonb DEFAULT '{}'::jsonb)
 RETURNS TABLE(id uuid, created boolean, received_at timestamp with time zone, evidence_state text, review_state text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_org_id uuid;
  v_existing public.biosecurity_assessments%rowtype;
  v_assessment public.biosecurity_assessments%rowtype;
  v_review_state text;
  v_evidence_state text := 'verified';
  v_item jsonb;
  v_evidence_id uuid;
  v_photo_arr jsonb := '[]'::jsonb;
  v_ordinal integer := 0;
begin
  if v_user_id is null then raise exception 'Authentication required'; end if;
  select p.organization_id into v_org_id from public.user_profiles p where p.id = v_user_id and p.deactivated_at is null and p.role in ('officer', 'admin_officer', 'admin', 'master', 'grand_master');
  if v_org_id is null then raise exception 'Active officer profile required'; end if;
  if p_client_request_id is null then raise exception 'client_request_id is required'; end if;

  if p_assessed_at is null or p_assessed_at > now() + interval '5 minutes' or p_assessed_at < now() - interval '24 hours' then
    raise exception 'assessed_at is outside the accepted capture window';
  end if;

  if nullif(trim(coalesce(p_location_name, '')), '') is null then
    raise exception 'Observed location name is required';
  end if;

  if p_density_estimate <> 'not_found' and nullif(trim(coalesce(p_species_name, '')), '') is null then
    raise exception 'Species name is required when pest/species is present';
  end if;

  if p_action_taken in ('notice_of_direction', 'infringement_notice') and nullif(trim(coalesce(p_notice_number, '')), '') is null then
    raise exception 'Notice number is required for direction or infringement actions';
  end if;

  if p_action_taken = 'mpi_referral' and nullif(trim(coalesce(p_mpi_referral_number, '')), '') is null then
    raise exception 'MPI referral number is required for MPI referrals';
  end if;

  if p_shift_id is not null and not exists (select 1 from public.shifts s where s.id = p_shift_id and s.organization_id = v_org_id) then
    raise exception 'Shift does not belong to the officer organisation';
  end if;

  if p_dispatch_job_id is not null and not exists (select 1 from public.dispatch_jobs d where d.id = p_dispatch_job_id and d.organization_id = v_org_id) then
    raise exception 'Dispatch job does not belong to the officer organisation';
  end if;

  -- Idempotency check
  select b.* into v_existing from public.biosecurity_assessments b
    where b.organization_id = v_org_id and b.officer_user_id = v_user_id and b.client_request_id = p_client_request_id;
  if found then
    return query select v_existing.id, false, v_existing.created_at, v_existing.evidence_state, v_existing.review_state;
    return;
  end if;

  -- Derive initial review state
  if p_classification is null or coalesce(p_classification->>'classification', '') = '' or coalesce(p_classification->>'status', '') = 'unavailable' then
    v_review_state := 'requires_supervisor_review';
  else
    v_review_state := 'submitted';
  end if;

  insert into public.biosecurity_assessments (
    organization_id, officer_user_id, officer_id, client_request_id, assessed_at,
    species_name, species_identified, density_estimate, action_taken, scene_description,
    location_name, protected_land_address, protected_land_site_id, notice_number, mpi_referral_number,
    follow_up_required, shift_id, dispatch_job_id, status, evidence_state, review_state,
    bob_classification, bob_confidence
  ) values (
    v_org_id, v_user_id, v_user_id, p_client_request_id, p_assessed_at,
    nullif(trim(coalesce(p_species_name, '')), ''), nullif(trim(coalesce(p_species_name, '')), ''), p_density_estimate, p_action_taken, nullif(trim(coalesce(p_scene_description, '')), ''),
    trim(p_location_name), nullif(trim(coalesce(p_protected_land_address, '')), ''), p_protected_land_site_id, nullif(trim(coalesce(p_notice_number, '')), ''), nullif(trim(coalesce(p_mpi_referral_number, '')), ''),
    coalesce(p_follow_up_required, false), p_shift_id, p_dispatch_job_id, 'open', v_evidence_state, v_review_state,
    nullif(trim(coalesce(p_classification->>'classification', '')), ''), (p_classification->>'confidence')::real
  ) returning * into v_assessment;

  -- Process evidence items
  if jsonb_array_length(p_evidence_items) > 0 then
    for v_item in select * from jsonb_array_elements(p_evidence_items) loop
      v_evidence_id := gen_random_uuid();
      insert into public.evidence_items (
        id, organization_id, module_key, evidence_kind, storage_path, captured_by_user_id, captured_at, metadata
      ) values (
        v_evidence_id, v_org_id, 'biosecurity', coalesce(v_item->>'evidence_kind', 'photo'), v_item->>'watermarked_path', v_user_id, p_assessed_at, coalesce(v_item, '{}'::jsonb)
      );

      insert into public.biosecurity_assessment_evidence (
        organization_id, biosecurity_assessment_id, evidence_item_id, ordinal, purpose
      ) values (
        v_org_id, v_assessment.id, v_evidence_id, v_ordinal, coalesce(v_item->>'purpose', 'primary_evidence')
      );

      v_photo_arr := v_photo_arr || jsonb_build_array(jsonb_build_object(
        'id', v_evidence_id,
        'storage_path', v_item->>'watermarked_path',
        'original_path', v_item->>'original_path',
        'captured_at', p_assessed_at
      ));
      v_ordinal := v_ordinal + 1;
    end loop;

    update public.biosecurity_assessments
      set photo_urls = v_photo_arr,
          photo_url = coalesce(v_item->>'watermarked_path', photo_url)
      where biosecurity_assessments.id = v_assessment.id;
  end if;

  insert into public.audit_log (
    organization_id, actor_user_id, action, target_table, target_id, metadata
  ) values (
    v_org_id, v_user_id, 'biosecurity_assessment_submitted', 'biosecurity_assessments', v_assessment.id,
    jsonb_build_object(
      'client_request_id', p_client_request_id,
      'species_name', v_assessment.species_name,
      'density_estimate', v_assessment.density_estimate,
      'action_taken', v_assessment.action_taken,
      'review_state', v_review_state,
      'evidence_count', v_ordinal
    )
  );

  return query select v_assessment.id, true, v_assessment.created_at, v_assessment.evidence_state, v_assessment.review_state;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."submit_biosecurity_assessment_receipt"(p_client_request_id uuid, p_assessed_at timestamp with time zone, p_species_name text, p_density_estimate text, p_action_taken text, p_scene_description text, p_location_name text, p_protected_land_address text, p_protected_land_site_id uuid, p_notice_number text, p_mpi_referral_number text, p_follow_up_required boolean, p_shift_id uuid, p_dispatch_job_id uuid, p_evidence_items jsonb, p_classification jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."submit_biosecurity_assessment_receipt"(p_client_request_id uuid, p_assessed_at timestamp with time zone, p_species_name text, p_density_estimate text, p_action_taken text, p_scene_description text, p_location_name text, p_protected_land_address text, p_protected_land_site_id uuid, p_notice_number text, p_mpi_referral_number text, p_follow_up_required boolean, p_shift_id uuid, p_dispatch_job_id uuid, p_evidence_items jsonb, p_classification jsonb) TO "postgres";
