CREATE OR REPLACE FUNCTION "public"."submit_bob_document_for_review"(p_document_id uuid, p_document_version_id uuid, p_review_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org_id uuid;
  v_current jsonb;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF nullif(trim(coalesce(p_review_reason, '')), '') IS NULL THEN RAISE EXCEPTION 'Review reason is required'; END IF;

  SELECT d.organization_id, dv.metadata_json
  INTO v_org_id, v_current
  FROM public.documents d
  JOIN public.document_versions dv ON dv.document_id = d.id
  WHERE d.id = p_document_id AND dv.id = p_document_version_id
  FOR UPDATE;

  IF v_org_id IS NULL THEN RAISE EXCEPTION 'Document draft not found'; END IF;
  IF NOT public.is_admin_for_org(v_org_id) AND NOT public.is_grand_master() THEN
    RAISE EXCEPTION 'Document review submission requires an administrator';
  END IF;
  IF coalesce(v_current->>'authoring_status', 'draft') <> 'draft' THEN
    RAISE EXCEPTION 'Only draft documents can be submitted for review';
  END IF;

  UPDATE public.document_versions
  SET metadata_json = jsonb_set(
    jsonb_set(
      jsonb_set(coalesce(metadata_json, '{}'::jsonb), '{authoring_status}', '"needs_review"'::jsonb),
      '{review_requested_by}', to_jsonb(v_actor::text)
    ),
    '{review_reason}', to_jsonb(trim(p_review_reason))
  ), updated_at = clock_timestamp()
  WHERE id = p_document_version_id;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (
    v_org_id, v_actor, 'bob_document_review_requested', 'document_versions', p_document_version_id,
    jsonb_build_object('document_id', p_document_id, 'review_reason', trim(p_review_reason))
  );

  PERFORM public.enqueue_notification(
    p_organization_id => v_org_id,
    p_category => 'document_review',
    p_title => 'Bob document needs review',
    p_body => coalesce(v_current->>'title', 'A document draft') || ' is ready for human review.',
    p_severity => 'info',
    p_recipient_role => 'admin',
    p_link_page => 'approvals',
    p_link_payload => jsonb_build_object('document_id', p_document_id, 'version_id', p_document_version_id),
    p_dedup_key => 'bob_document_review:' || p_document_version_id::text
  );

  RETURN jsonb_build_object('ok', true, 'document_id', p_document_id, 'document_version_id', p_document_version_id, 'status', 'needs_review');
END;
$function$;
REVOKE ALL ON FUNCTION "public"."submit_bob_document_for_review"(p_document_id uuid, p_document_version_id uuid, p_review_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."submit_bob_document_for_review"(p_document_id uuid, p_document_version_id uuid, p_review_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."submit_bob_document_for_review"(p_document_id uuid, p_document_version_id uuid, p_review_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."submit_bob_document_for_review"(p_document_id uuid, p_document_version_id uuid, p_review_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."submit_dynamic_risk_assessment"(p_shift_id uuid, p_place_kind text, p_place_id uuid, p_task text, p_hazards text, p_controls text[], p_likelihood smallint, p_consequence smallint, p_decision text, p_understood boolean, p_client_request_id uuid)
 RETURNS dynamic_risk_assessments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_shift public.shifts%rowtype; v_place record; v_item public.dynamic_risk_assessments%rowtype; v_controls text[];
BEGIN
  SELECT * INTO v_shift FROM public.shifts WHERE id = p_shift_id FOR SHARE;
  IF auth.uid() IS NULL OR v_shift.officer_user_id IS DISTINCT FROM auth.uid() OR v_shift.status <> 'in_progress'
    OR NOT EXISTS (SELECT 1 FROM public.user_profiles WHERE id = auth.uid() AND deactivated_at IS NULL) THEN
    RAISE EXCEPTION 'Only the active assigned officer can submit a task assessment';
  END IF;
  IF p_understood IS DISTINCT FROM true OR p_client_request_id IS NULL THEN
    RAISE EXCEPTION 'Confirm that you assessed these risks and understand the controls';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtext(auth.uid()::text || ':' || p_client_request_id::text));
  IF cardinality(p_controls) NOT BETWEEN 1 AND 12 OR EXISTS (
    SELECT 1 FROM unnest(p_controls) c WHERE length(btrim(c)) NOT BETWEEN 1 AND 300 OR c IS NULL
  ) THEN RAISE EXCEPTION 'Record 1-12 controls, each 1-300 characters'; END IF;
  SELECT array_agg(btrim(c) ORDER BY ord) INTO v_controls FROM unnest(p_controls) WITH ORDINALITY x(c,ord);
  SELECT * INTO v_place FROM public.shift_safety_places(p_shift_id, NULL)
    WHERE place_kind = p_place_kind AND place_id = p_place_id LIMIT 1;
  IF NOT FOUND THEN RAISE EXCEPTION 'Assessment place must belong to the active shift'; END IF;
  SELECT * INTO v_item FROM public.dynamic_risk_assessments
    WHERE officer_id = auth.uid() AND client_request_id = p_client_request_id;
  IF FOUND THEN
    IF v_item.shift_id IS DISTINCT FROM p_shift_id OR v_item.site_id IS DISTINCT FROM
      (CASE WHEN p_place_kind = 'site' THEN p_place_id END) OR v_item.zone_id IS DISTINCT FROM
      (CASE WHEN p_place_kind = 'zone' THEN p_place_id END) OR v_item.task IS DISTINCT FROM btrim(p_task)
      OR v_item.hazards IS DISTINCT FROM btrim(p_hazards) OR v_item.decision IS DISTINCT FROM p_decision
      OR v_item.likelihood IS DISTINCT FROM p_likelihood OR v_item.consequence IS DISTINCT FROM p_consequence
      OR v_item.controls IS DISTINCT FROM v_controls THEN
      RAISE EXCEPTION 'Request already records another assessment. Reload before submitting a new one';
    END IF;
    RETURN v_item;
  END IF;
  INSERT INTO public.dynamic_risk_assessments(
    organization_id, shift_id, officer_id, location_id, site_id, zone_id,
    task, hazards, controls, likelihood, consequence, decision, briefing_snapshot, client_request_id
  ) VALUES (
    v_shift.organization_id, p_shift_id, auth.uid(), v_place.location_id,
    CASE WHEN p_place_kind = 'site' THEN p_place_id END, CASE WHEN p_place_kind = 'zone' THEN p_place_id END,
    btrim(p_task), btrim(p_hazards), v_controls, p_likelihood, p_consequence, p_decision,
    public.build_shift_safety_briefing(p_shift_id, NULL), p_client_request_id
  ) RETURNING * INTO v_item;
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_shift.organization_id, auth.uid(), 'dynamic_risk_assessment_signed', 'dynamic_risk_assessments', v_item.id,
    jsonb_build_object('shift_id', p_shift_id, 'decision', p_decision, 'signed_at', v_item.signed_at));
  RETURN v_item;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."submit_dynamic_risk_assessment"(p_shift_id uuid, p_place_kind text, p_place_id uuid, p_task text, p_hazards text, p_controls text[], p_likelihood smallint, p_consequence smallint, p_decision text, p_understood boolean, p_client_request_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."submit_dynamic_risk_assessment"(p_shift_id uuid, p_place_kind text, p_place_id uuid, p_task text, p_hazards text, p_controls text[], p_likelihood smallint, p_consequence smallint, p_decision text, p_understood boolean, p_client_request_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."submit_dynamic_risk_assessment"(p_shift_id uuid, p_place_kind text, p_place_id uuid, p_task text, p_hazards text, p_controls text[], p_likelihood smallint, p_consequence smallint, p_decision text, p_understood boolean, p_client_request_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."submit_dynamic_risk_assessment"(p_shift_id uuid, p_place_kind text, p_place_id uuid, p_task text, p_hazards text, p_controls text[], p_likelihood smallint, p_consequence smallint, p_decision text, p_understood boolean, p_client_request_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."submit_officer_breach_action"(p_alert_id uuid, p_expected_status text, p_action text, p_notes text, p_request_id uuid)
 RETURNS TABLE(alert_id uuid, alert_status text, requested_action text, enforcement_mode text, disposition text, requested_at timestamp with time zone, next_actor text, request_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_alert public.breach_alerts%rowtype;
  v_observation public.observations%rowtype;
  v_profile public.user_profiles%rowtype;
  v_mode text;
  v_disposition text;
  v_notes text := nullif(trim(coalesce(p_notes, '')), '');
  v_direct boolean;
begin
  if v_actor is null then
    raise exception 'Authenticated officer required';
  end if;
  if p_request_id is null then
    raise exception 'Request ID is required';
  end if;
  if p_action not in ('written_warning', 'notice_to_vacate', 'infringement') then
    raise exception 'Unsupported officer enforcement action %', p_action;
  end if;
  if v_notes is null then
    raise exception 'Enforcement notes are required';
  end if;

  select b.* into v_alert
  from public.breach_alerts b
  where b.request_id = p_request_id;

  if found then
    if v_alert.id <> p_alert_id or v_alert.requested_by <> v_actor then
      raise exception 'Request ID has already been used';
    end if;
    return query
      select v_alert.id, v_alert.status, v_alert.requested_action,
        v_alert.enforcement_mode, v_alert.request_disposition,
        v_alert.requested_at,
        case when v_alert.request_disposition = 'direct' then 'officer' else 'administrator' end,
        v_alert.request_id;
    return;
  end if;

  select b.* into v_alert
  from public.breach_alerts b
  where b.id = p_alert_id
  for update;
  if not found then
    raise exception 'Breach alert not found';
  end if;
  if v_alert.status <> p_expected_status then
    raise exception 'Breach alert changed from expected status % to %', p_expected_status, v_alert.status;
  end if;
  if v_alert.status <> 'open' then
    raise exception 'Officer enforcement requests require an open breach alert';
  end if;
  if v_alert.observation_id is null or v_alert.zone_id is null then
    raise exception 'Officer enforcement requires a zone-backed source observation';
  end if;

  select o.* into v_observation
  from public.observations o
  where o.id = v_alert.observation_id;
  if not found or v_observation.officer_id <> v_actor then
    raise exception 'Only the source officer may action this breach alert';
  end if;

  select p.* into v_profile
  from public.user_profiles p
  where p.id = v_actor and p.deactivated_at is null;
  if not found or v_profile.role not in ('officer', 'admin_officer') then
    raise exception 'Active field officer role required';
  end if;
  if not public.is_enforcement_operator_for_org(v_alert.organization_id) then
    raise exception 'Enforcement operator access is required for this organisation';
  end if;
  if not public.has_location_access(v_observation.site_id, v_observation.zone_id) then
    raise exception 'Active place authority is required for this breach';
  end if;
  if not public.user_has_task_entitlement(
    p_user => v_actor,
    p_observation_id => v_observation.id
  ) then
    raise exception 'A live task entitlement is required for this breach';
  end if;

  v_mode := public.resolve_enforcement_mode(v_alert.zone_id);
  if v_mode not in ('officer_direct', 'admin_first', 'hybrid') then
    raise exception 'A valid enforcement workflow mode could not be resolved';
  end if;

  v_direct := v_mode = 'officer_direct'
    or (v_mode = 'hybrid' and p_action <> 'infringement');
  v_disposition := case when v_direct then 'direct' else 'administrator_review' end;

  update public.breach_alerts
  set requested_action = p_action,
      requested_by = v_actor,
      requested_at = clock_timestamp(),
      request_notes = v_notes,
      request_id = p_request_id,
      enforcement_mode = v_mode,
      request_disposition = v_disposition,
      status = case when v_direct then 'actioned' else 'acknowledged' end,
      action_type = case when v_direct then p_action else null end,
      actioned_by = case when v_direct then v_actor else null end,
      actioned_at = case when v_direct then clock_timestamp() else null end,
      notes = concat_ws(E'\n', nullif(notes, ''), 'Officer request: ' || v_notes)
  where id = v_alert.id
  returning * into v_alert;

  insert into public.audit_log(
    organization_id, actor_user_id, action, target_table, target_id, metadata
  ) values (
    v_alert.organization_id,
    v_actor,
    case when v_direct then 'officer_breach_action_direct' else 'officer_breach_action_requested' end,
    'breach_alerts',
    v_alert.id,
    jsonb_build_object(
      'previous_status', p_expected_status,
      'status', v_alert.status,
      'requested_action', p_action,
      'enforcement_mode', v_mode,
      'disposition', v_disposition,
      'request_id', p_request_id,
      'observation_id', v_observation.id,
      'zone_id', v_alert.zone_id,
      'notes', v_notes
    )
  );

  if not v_direct then
    perform public.enqueue_notification(
      p_organization_id => v_alert.organization_id,
      p_category => 'breach_decision',
      p_title => 'Officer enforcement request needs review',
      p_body => v_notes,
      p_severity => 'warning',
      p_recipient_role => 'admin',
      p_link_page => 'breach-review',
      p_link_payload => jsonb_build_object('breach_alert_id', v_alert.id),
      p_dedup_key => 'breach_officer_request:' || p_request_id::text
    );
  end if;

  return query
    select v_alert.id, v_alert.status, v_alert.requested_action,
      v_alert.enforcement_mode, v_alert.request_disposition,
      v_alert.requested_at,
      case when v_direct then 'officer' else 'administrator' end,
      v_alert.request_id;
end;
$function$;
COMMENT ON FUNCTION "public"."submit_officer_breach_action"(p_alert_id uuid, p_expected_status text, p_action text, p_notes text, p_request_id uuid) IS 'Governed officer enforcement request. Proves source ownership, active place and task authority, resolves enforcement mode server-side, and returns an idempotent direct-or-review receipt.';
REVOKE ALL ON FUNCTION "public"."submit_officer_breach_action"(p_alert_id uuid, p_expected_status text, p_action text, p_notes text, p_request_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."submit_officer_breach_action"(p_alert_id uuid, p_expected_status text, p_action text, p_notes text, p_request_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."submit_officer_breach_action"(p_alert_id uuid, p_expected_status text, p_action text, p_notes text, p_request_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."submit_officer_breach_action"(p_alert_id uuid, p_expected_status text, p_action text, p_notes text, p_request_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."submit_officer_field_report"(p_client_event_id uuid, p_reported_at timestamp with time zone, p_report_type report_type, p_severity report_severity, p_title text, p_description text, p_location_name text DEFAULT NULL::text, p_address text DEFAULT NULL::text, p_gps_lat double precision DEFAULT NULL::double precision, p_gps_lng double precision DEFAULT NULL::double precision, p_shift_id uuid DEFAULT NULL::uuid, p_immediate_action text DEFAULT NULL::text, p_follow_up_required boolean DEFAULT false, p_follow_up_notes text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, created boolean, received_at timestamp with time zone, shift_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_home_org uuid;
  v_report_org uuid;
  v_shift public.shifts%rowtype;
  v_existing public.officer_field_reports%rowtype;
  v_report public.officer_field_reports%rowtype;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT p.organization_id INTO v_home_org
  FROM public.user_profiles p
  WHERE p.id=v_user_id AND p.deactivated_at IS NULL AND p.role IN('officer','admin_officer');
  IF v_home_org IS NULL THEN RAISE EXCEPTION 'Active officer profile required'; END IF;
  IF p_client_event_id IS NULL THEN RAISE EXCEPTION 'client_event_id is required'; END IF;
  IF p_reported_at IS NULL OR p_reported_at > now()+interval '5 minutes' OR p_reported_at < now()-interval '24 hours' THEN RAISE EXCEPTION 'reported_at is outside the accepted capture window'; END IF;
  IF char_length(trim(coalesce(p_title,''))) NOT BETWEEN 5 AND 200 THEN RAISE EXCEPTION 'Title must be between 5 and 200 characters'; END IF;
  IF char_length(trim(coalesce(p_description,''))) NOT BETWEEN 10 AND 10000 THEN RAISE EXCEPTION 'Description must be between 10 and 10000 characters'; END IF;
  IF (p_gps_lat IS NULL) <> (p_gps_lng IS NULL) THEN RAISE EXCEPTION 'Both GPS coordinates are required together'; END IF;
  IF p_gps_lat IS NOT NULL AND (p_gps_lat NOT BETWEEN -90 AND 90 OR p_gps_lng NOT BETWEEN -180 AND 180) THEN RAISE EXCEPTION 'Invalid GPS coordinates'; END IF;
  IF p_follow_up_required AND nullif(trim(coalesce(p_follow_up_notes,'')),'') IS NULL THEN RAISE EXCEPTION 'Follow-up notes are required'; END IF;

  v_report_org := v_home_org;
  IF p_shift_id IS NOT NULL THEN
    SELECT s.* INTO v_shift
    FROM public.shifts s
    WHERE s.id=p_shift_id AND s.officer_user_id=v_user_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Shift does not belong to the authenticated officer'; END IF;
    v_report_org := v_shift.organization_id;
  END IF;

  SELECT r.* INTO v_existing
  FROM public.officer_field_reports r
  WHERE r.organization_id=v_report_org AND r.officer_id=v_user_id AND r.client_event_id=p_client_event_id;
  IF FOUND THEN RETURN QUERY SELECT v_existing.id,false,v_existing.created_at,v_existing.shift_id; RETURN; END IF;

  INSERT INTO public.officer_field_reports(organization_id,officer_id,client_event_id,reported_at,report_type,severity,status,title,description,location_name,address,gps_lat,gps_lng,shift_id,immediate_action,follow_up_required,follow_up_notes)
  VALUES(v_report_org,v_user_id,p_client_event_id,p_reported_at,p_report_type,p_severity,'submitted',trim(p_title),trim(p_description),nullif(trim(coalesce(p_location_name,'')),''),nullif(trim(coalesce(p_address,'')),''),p_gps_lat,p_gps_lng,p_shift_id,nullif(trim(coalesce(p_immediate_action,'')),''),coalesce(p_follow_up_required,false),nullif(trim(coalesce(p_follow_up_notes,'')),''))
  RETURNING * INTO v_report;

  INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
  VALUES(v_report_org,v_user_id,'officer_field_report_submitted','officer_field_reports',v_report.id,jsonb_build_object('report_type',v_report.report_type,'severity',v_report.severity,'shift_id',v_report.shift_id,'follow_up_required',v_report.follow_up_required));

  RETURN QUERY SELECT v_report.id,true,v_report.created_at,v_report.shift_id;
END;
$function$;
COMMENT ON FUNCTION "public"."submit_officer_field_report"(p_client_event_id uuid, p_reported_at timestamp with time zone, p_report_type report_type, p_severity report_severity, p_title text, p_description text, p_location_name text, p_address text, p_gps_lat double precision, p_gps_lng double precision, p_shift_id uuid, p_immediate_action text, p_follow_up_required boolean, p_follow_up_notes text) IS 'Creates a retry-safe officer field report, storing branch-shift-linked evidence under the operating organization.';
REVOKE ALL ON FUNCTION "public"."submit_officer_field_report"(p_client_event_id uuid, p_reported_at timestamp with time zone, p_report_type report_type, p_severity report_severity, p_title text, p_description text, p_location_name text, p_address text, p_gps_lat double precision, p_gps_lng double precision, p_shift_id uuid, p_immediate_action text, p_follow_up_required boolean, p_follow_up_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."submit_officer_field_report"(p_client_event_id uuid, p_reported_at timestamp with time zone, p_report_type report_type, p_severity report_severity, p_title text, p_description text, p_location_name text, p_address text, p_gps_lat double precision, p_gps_lng double precision, p_shift_id uuid, p_immediate_action text, p_follow_up_required boolean, p_follow_up_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."submit_officer_field_report"(p_client_event_id uuid, p_reported_at timestamp with time zone, p_report_type report_type, p_severity report_severity, p_title text, p_description text, p_location_name text, p_address text, p_gps_lat double precision, p_gps_lng double precision, p_shift_id uuid, p_immediate_action text, p_follow_up_required boolean, p_follow_up_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."submit_officer_field_report"(p_client_event_id uuid, p_reported_at timestamp with time zone, p_report_type report_type, p_severity report_severity, p_title text, p_description text, p_location_name text, p_address text, p_gps_lat double precision, p_gps_lng double precision, p_shift_id uuid, p_immediate_action text, p_follow_up_required boolean, p_follow_up_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."submit_officer_field_report"(p_client_event_id uuid, p_reported_at timestamp with time zone, p_report_type report_type, p_severity report_severity, p_title text, p_description text, p_location_name text DEFAULT NULL::text, p_address text DEFAULT NULL::text, p_gps_lat double precision DEFAULT NULL::double precision, p_gps_lng double precision DEFAULT NULL::double precision, p_shift_id uuid DEFAULT NULL::uuid, p_immediate_action text DEFAULT NULL::text, p_follow_up_required boolean DEFAULT false, p_follow_up_notes text DEFAULT NULL::text, p_site_id uuid DEFAULT NULL::uuid, p_zone_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, created boolean, received_at timestamp with time zone, shift_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_home_org uuid;
  v_report_org uuid;
  v_shift public.shifts%rowtype;
  v_existing public.officer_field_reports%rowtype;
  v_report public.officer_field_reports%rowtype;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT p.organization_id INTO v_home_org
  FROM public.user_profiles p
  WHERE p.id=v_user_id AND p.deactivated_at IS NULL AND p.role IN('officer','admin_officer');
  IF v_home_org IS NULL THEN RAISE EXCEPTION 'Active officer profile required'; END IF;
  IF p_client_event_id IS NULL THEN RAISE EXCEPTION 'client_event_id is required'; END IF;
  IF p_reported_at IS NULL OR p_reported_at > now()+interval '5 minutes' OR p_reported_at < now()-interval '24 hours' THEN RAISE EXCEPTION 'reported_at is outside the accepted capture window'; END IF;
  IF char_length(trim(coalesce(p_title,''))) NOT BETWEEN 5 AND 200 THEN RAISE EXCEPTION 'Title must be between 5 and 200 characters'; END IF;
  IF char_length(trim(coalesce(p_description,''))) NOT BETWEEN 10 AND 10000 THEN RAISE EXCEPTION 'Description must be between 10 and 10000 characters'; END IF;
  IF (p_gps_lat IS NULL) <> (p_gps_lng IS NULL) THEN RAISE EXCEPTION 'Both GPS coordinates are required together'; END IF;
  IF p_gps_lat IS NOT NULL AND (p_gps_lat NOT BETWEEN -90 AND 90 OR p_gps_lng NOT BETWEEN -180 AND 180) THEN RAISE EXCEPTION 'Invalid GPS coordinates'; END IF;
  IF p_follow_up_required AND nullif(trim(coalesce(p_follow_up_notes,'')),'') IS NULL THEN RAISE EXCEPTION 'Follow-up notes are required'; END IF;
  IF p_site_id IS NOT NULL AND p_zone_id IS NOT NULL THEN RAISE EXCEPTION 'A report resolves to a site or a zone, never both'; END IF;

  v_report_org := v_home_org;
  IF p_shift_id IS NOT NULL THEN
    SELECT s.* INTO v_shift
    FROM public.shifts s
    WHERE s.id=p_shift_id AND s.officer_user_id=v_user_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Shift does not belong to the authenticated officer'; END IF;
    v_report_org := v_shift.organization_id;
  END IF;
  IF p_site_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.client_sites s WHERE s.id=p_site_id) THEN RAISE EXCEPTION 'Site not found'; END IF;
  IF p_zone_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.location_zones z WHERE z.id=p_zone_id) THEN RAISE EXCEPTION 'Zone not found'; END IF;

  SELECT r.* INTO v_existing
  FROM public.officer_field_reports r
  WHERE r.organization_id=v_report_org AND r.officer_id=v_user_id AND r.client_event_id=p_client_event_id;
  IF FOUND THEN RETURN QUERY SELECT v_existing.id,false,v_existing.created_at,v_existing.shift_id; RETURN; END IF;

  INSERT INTO public.officer_field_reports(organization_id,officer_id,client_event_id,reported_at,report_type,severity,status,title,description,location_name,address,gps_lat,gps_lng,shift_id,immediate_action,follow_up_required,follow_up_notes,site_id,zone_id)
  VALUES(v_report_org,v_user_id,p_client_event_id,p_reported_at,p_report_type,p_severity,'submitted',trim(p_title),trim(p_description),nullif(trim(coalesce(p_location_name,'')),''),nullif(trim(coalesce(p_address,'')),''),p_gps_lat,p_gps_lng,p_shift_id,nullif(trim(coalesce(p_immediate_action,'')),''),coalesce(p_follow_up_required,false),nullif(trim(coalesce(p_follow_up_notes,'')),''),p_site_id,p_zone_id)
  RETURNING * INTO v_report;

  INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
  VALUES(v_report_org,v_user_id,'officer_field_report_submitted','officer_field_reports',v_report.id,jsonb_build_object('report_type',v_report.report_type,'severity',v_report.severity,'shift_id',v_report.shift_id,'follow_up_required',v_report.follow_up_required,'site_id',v_report.site_id,'zone_id',v_report.zone_id));

  RETURN QUERY SELECT v_report.id,true,v_report.created_at,v_report.shift_id;
END;
$function$;
COMMENT ON FUNCTION "public"."submit_officer_field_report"(p_client_event_id uuid, p_reported_at timestamp with time zone, p_report_type report_type, p_severity report_severity, p_title text, p_description text, p_location_name text, p_address text, p_gps_lat double precision, p_gps_lng double precision, p_shift_id uuid, p_immediate_action text, p_follow_up_required boolean, p_follow_up_notes text, p_site_id uuid, p_zone_id uuid) IS 'Creates a retry-safe officer field report, storing branch-shift-linked evidence under the operating organization. site_id/zone_id are the geofence-resolved structured place (site XOR zone), populated by ServiceRelationshipContext''s live GPS resolution - see docs/canon/GEOFENCE_PRINCIPLES.md.';
REVOKE ALL ON FUNCTION "public"."submit_officer_field_report"(p_client_event_id uuid, p_reported_at timestamp with time zone, p_report_type report_type, p_severity report_severity, p_title text, p_description text, p_location_name text, p_address text, p_gps_lat double precision, p_gps_lng double precision, p_shift_id uuid, p_immediate_action text, p_follow_up_required boolean, p_follow_up_notes text, p_site_id uuid, p_zone_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."submit_officer_field_report"(p_client_event_id uuid, p_reported_at timestamp with time zone, p_report_type report_type, p_severity report_severity, p_title text, p_description text, p_location_name text, p_address text, p_gps_lat double precision, p_gps_lng double precision, p_shift_id uuid, p_immediate_action text, p_follow_up_required boolean, p_follow_up_notes text, p_site_id uuid, p_zone_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."submit_officer_field_report"(p_client_event_id uuid, p_reported_at timestamp with time zone, p_report_type report_type, p_severity report_severity, p_title text, p_description text, p_location_name text, p_address text, p_gps_lat double precision, p_gps_lng double precision, p_shift_id uuid, p_immediate_action text, p_follow_up_required boolean, p_follow_up_notes text, p_site_id uuid, p_zone_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."submit_officer_field_report"(p_client_event_id uuid, p_reported_at timestamp with time zone, p_report_type report_type, p_severity report_severity, p_title text, p_description text, p_location_name text, p_address text, p_gps_lat double precision, p_gps_lng double precision, p_shift_id uuid, p_immediate_action text, p_follow_up_required boolean, p_follow_up_notes text, p_site_id uuid, p_zone_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."submit_officer_leave_request"(p_client_event_id uuid, p_leave_type text, p_starts_on date, p_ends_on date, p_reason text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, created boolean, status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_user uuid:=auth.uid();v_staff public.staff_profiles%rowtype;v_leave public.leave_requests%rowtype;
begin
  select sp.* into v_staff from public.staff_profiles sp join public.user_profiles up on up.id=v_user and up.deactivated_at is null where sp.organization_id=up.organization_id and (sp.user_id=v_user or sp.id=v_user) limit 1;if not found then raise exception 'Active staff profile required';end if;
  if p_client_event_id is null then raise exception 'client_event_id is required';end if;if p_leave_type not in('annual','sick','bereavement','parental','unpaid','other') then raise exception 'Unsupported leave type';end if;if p_starts_on is null or p_ends_on is null or p_starts_on>p_ends_on or p_ends_on-p_starts_on>366 then raise exception 'Leave period is outside the accepted range';end if;
  select l.* into v_leave from public.leave_requests l where l.organization_id=v_staff.organization_id and l.staff_id=v_staff.id and l.client_event_id=p_client_event_id;if found then return query select v_leave.id,false,v_leave.status;return;end if;
  if exists(select 1 from public.leave_requests l where l.staff_id=v_staff.id and l.status in('pending','approved') and daterange(l.starts_on,l.ends_on,'[]')&&daterange(p_starts_on,p_ends_on,'[]')) then raise exception 'An active leave request already overlaps this period';end if;
  insert into public.leave_requests(organization_id,staff_id,leave_type,starts_on,ends_on,status,reason,client_event_id) values(v_staff.organization_id,v_staff.id,p_leave_type,p_starts_on,p_ends_on,'pending',nullif(trim(coalesce(p_reason,'')),''),p_client_event_id) returning * into v_leave;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)values(v_staff.organization_id,v_user,'leave_request_submitted','leave_requests',v_leave.id,jsonb_build_object('staff_id',v_staff.id,'leave_type',p_leave_type,'starts_on',p_starts_on,'ends_on',p_ends_on));return query select v_leave.id,true,v_leave.status;
end;$function$;
REVOKE ALL ON FUNCTION "public"."submit_officer_leave_request"(p_client_event_id uuid, p_leave_type text, p_starts_on date, p_ends_on date, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."submit_officer_leave_request"(p_client_event_id uuid, p_leave_type text, p_starts_on date, p_ends_on date, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."submit_officer_leave_request"(p_client_event_id uuid, p_leave_type text, p_starts_on date, p_ends_on date, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."submit_officer_leave_request"(p_client_event_id uuid, p_leave_type text, p_starts_on date, p_ends_on date, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."submit_officer_noise_assessment"(p_client_request_id uuid, p_assessed_at timestamp with time zone, p_noise_source text, p_noise_source_address text, p_action_taken text DEFAULT 'no_action'::text, p_volume_score smallint DEFAULT 0, p_time_score smallint DEFAULT 1, p_tone_score smallint DEFAULT 0, p_complaint_address text DEFAULT NULL::text, p_complainant_site_id uuid DEFAULT NULL::uuid, p_notice_number text DEFAULT NULL::text, p_end_number text DEFAULT NULL::text, p_occupant_name text DEFAULT NULL::text, p_occupant_dob date DEFAULT NULL::date, p_is_large_event_or_commercial boolean DEFAULT false, p_police_requested boolean DEFAULT false, p_police_present boolean DEFAULT false, p_scene_description text DEFAULT NULL::text, p_incident_report_text text DEFAULT NULL::text, p_follow_up_required boolean DEFAULT false, p_shift_id uuid DEFAULT NULL::uuid, p_dispatch_job_id uuid DEFAULT NULL::uuid, p_gps_lat double precision DEFAULT NULL::double precision, p_gps_lng double precision DEFAULT NULL::double precision)
 RETURNS TABLE(id uuid, created boolean, received_at timestamp with time zone, review_status text, matrix_total smallint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_org_id uuid;
  v_existing public.noise_assessments%rowtype;
  v_assessment public.noise_assessments%rowtype;
  v_job public.dispatch_jobs%rowtype;
  v_matrix_total smallint;
  v_threshold smallint := 5;
  v_end_validity_hours smallint := 192;
  v_excessive boolean;
  v_site_id uuid;
  v_complainant_site_id uuid := p_complainant_site_id;
  v_complaint_address text := nullif(trim(coalesce(p_complaint_address, '')), '');
  v_source_stop_id uuid;
  v_complainant_stop_id uuid;
  v_point geometry;
  v_dist_complainant numeric;
  v_dist_source numeric;
  v_end_expires_at timestamptz;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT p.organization_id INTO v_org_id FROM public.user_profiles p
  WHERE p.id = v_user_id AND p.deactivated_at IS NULL
    AND p.role IN ('officer', 'admin_officer', 'admin', 'master', 'grand_master');
  IF v_org_id IS NULL THEN RAISE EXCEPTION 'Active officer profile required'; END IF;
  IF p_client_request_id IS NULL THEN RAISE EXCEPTION 'client_request_id is required'; END IF;
  IF p_assessed_at IS NULL OR p_assessed_at > now() + interval '5 minutes' OR p_assessed_at < now() - interval '24 hours' THEN RAISE EXCEPTION 'assessed_at is outside the accepted capture window'; END IF;
  IF nullif(trim(coalesce(p_noise_source_address, '')), '') IS NULL THEN RAISE EXCEPTION 'Noise source address is required'; END IF;
  IF nullif(trim(coalesce(p_noise_source, '')), '') IS NULL THEN RAISE EXCEPTION 'Noise source type is required'; END IF;
  IF p_volume_score NOT BETWEEN 0 AND 4 THEN RAISE EXCEPTION 'Volume score must be between 0 and 4'; END IF;
  IF p_time_score NOT BETWEEN 1 AND 4 THEN RAISE EXCEPTION 'Time score must be between 1 and 4'; END IF;
  IF p_tone_score NOT BETWEEN 0 AND 2 THEN RAISE EXCEPTION 'Tone score must be between 0 and 2'; END IF;

  v_matrix_total := coalesce(p_volume_score, 0) + coalesce(p_time_score, 1) + coalesce(p_tone_score, 0);
  SELECT n.excessive_threshold, n.end_validity_hours INTO v_threshold, v_end_validity_hours
  FROM public.noise_module_config n
  WHERE n.organization_id = v_org_id AND n.is_current
    AND n.effective_from <= current_date
    AND (n.effective_to IS NULL OR n.effective_to >= current_date)
  ORDER BY n.effective_from DESC, n.version DESC
  LIMIT 1;
  IF v_threshold IS NULL THEN v_threshold := 5; END IF;
  IF v_end_validity_hours IS NULL THEN v_end_validity_hours := 192; END IF;
  v_excessive := (v_matrix_total >= v_threshold);

  IF p_action_taken IN ('abatement_notice', 'direction_notice', 'enforcement_notice', 'equipment_seized')
    AND nullif(trim(coalesce(p_notice_number, coalesce(p_end_number, ''))), '') IS NULL THEN
    RAISE EXCEPTION 'Notice or END number is required for statutory noise enforcement actions';
  END IF;
  -- RMA s327(1)(a): an excessive noise direction follows a received complaint.
  IF p_action_taken = 'direction_notice' AND p_dispatch_job_id IS NULL THEN
    RAISE EXCEPTION 'An excessive noise direction requires a linked complaint (dispatch job); use the abatement path for officer-initiated noise';
  END IF;
  -- RMA s328(3) / s323(2): seizure is exercised accompanied by a constable.
  IF p_action_taken = 'equipment_seized' AND NOT coalesce(p_police_present, false) THEN
    RAISE EXCEPTION 'Equipment seizure requires Police present (RMA s328(3))';
  END IF;
  IF p_shift_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.shifts s WHERE s.id = p_shift_id AND s.organization_id = v_org_id) THEN RAISE EXCEPTION 'Shift does not belong to the officer organisation'; END IF;
  IF p_dispatch_job_id IS NOT NULL THEN
    SELECT * INTO v_job FROM public.dispatch_jobs d WHERE d.id = p_dispatch_job_id AND d.organization_id = v_org_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Dispatch job does not belong to the officer organisation'; END IF;
  END IF;

  SELECT n.* INTO v_existing FROM public.noise_assessments n
  WHERE n.organization_id = v_org_id AND n.officer_user_id = v_user_id AND n.client_request_id = p_client_request_id;
  IF FOUND THEN RETURN QUERY SELECT v_existing.id, false, v_existing.created_at, v_existing.review_status, v_existing.matrix_total; RETURN; END IF;

  -- Both places come from the job when the officer did not supply them (rule #157: site_id = source).
  IF v_job.id IS NOT NULL THEN
    v_site_id := v_job.client_site_id;
    v_complainant_site_id := COALESCE(v_complainant_site_id, v_job.harmed_party_site_id);
    v_complaint_address := COALESCE(v_complaint_address, v_job.harmed_party_address);
    SELECT st.id INTO v_source_stop_id FROM public.shift_stops st
    WHERE st.dispatch_job_id = v_job.id AND st.place_role = 'work_place' AND st.actual_arrived_at IS NOT NULL ORDER BY st.visit_number DESC LIMIT 1;
    SELECT st.id INTO v_complainant_stop_id FROM public.shift_stops st
    WHERE st.dispatch_job_id = v_job.id AND st.place_role = 'harmed_party_place' AND st.actual_arrived_at IS NOT NULL ORDER BY st.visit_number DESC LIMIT 1;
  END IF;

  -- Measured position: how close the officer assessed to the complainant, and to the source.
  IF p_gps_lat IS NOT NULL AND p_gps_lng IS NOT NULL THEN
    v_point := ST_SetSRID(ST_MakePoint(p_gps_lng, p_gps_lat), 4326);
    SELECT round(ST_Distance(COALESCE(cs.boundary, cs.center_point)::geography, v_point::geography)::numeric, 1) INTO v_dist_complainant
    FROM public.client_sites cs WHERE cs.id = v_complainant_site_id AND (cs.boundary IS NOT NULL OR cs.center_point IS NOT NULL);
    SELECT round(ST_Distance(COALESCE(cs.boundary, cs.center_point)::geography, v_point::geography)::numeric, 1) INTO v_dist_source
    FROM public.client_sites cs WHERE cs.id = v_site_id AND (cs.boundary IS NOT NULL OR cs.center_point IS NOT NULL);
  END IF;

  IF p_action_taken = 'direction_notice' THEN
    v_end_expires_at := p_assessed_at + make_interval(hours => v_end_validity_hours);
  END IF;

  INSERT INTO public.noise_assessments (
    organization_id, officer_user_id, officer_id, client_request_id, assessed_at,
    noise_source, noise_source_address, assessment_location, action_taken, action,
    volume_score, time_score, tone_score, matrix_total, complaint_address,
    complainant_site_id, notice_number, end_number, occupant_name, occupant_dob,
    is_large_event_or_commercial, police_requested, police_present, scene_description,
    incident_report_text, follow_up_required, shift_id, dispatch_job_id, status,
    review_status, assessment_gps_lat, assessment_gps_lng,
    site_id, complainant_protected, source_stop_id, complainant_stop_id,
    assessment_distance_to_complainant_m, assessment_distance_to_source_m, end_expires_at
  ) VALUES (
    v_org_id, v_user_id, v_user_id, p_client_request_id, p_assessed_at,
    trim(p_noise_source), trim(p_noise_source_address), trim(p_noise_source_address),
    p_action_taken, p_action_taken, p_volume_score, p_time_score, p_tone_score,
    v_matrix_total, v_complaint_address,
    v_complainant_site_id, nullif(trim(coalesce(p_notice_number, '')), ''),
    nullif(trim(coalesce(p_end_number, '')), ''), nullif(trim(coalesce(p_occupant_name, '')), ''),
    p_occupant_dob, coalesce(p_is_large_event_or_commercial, false),
    coalesce(p_police_requested, false), coalesce(p_police_present, false),
    nullif(trim(coalesce(p_scene_description, '')), ''),
    nullif(trim(coalesce(p_incident_report_text, '')), ''),
    coalesce(p_follow_up_required, false), p_shift_id, p_dispatch_job_id, 'open', 'open',
    p_gps_lat, p_gps_lng,
    v_site_id, true, v_source_stop_id, v_complainant_stop_id,
    v_dist_complainant, v_dist_source, v_end_expires_at
  ) RETURNING * INTO v_assessment;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_org_id, v_user_id, 'noise_assessment_submitted', 'noise_assessments', v_assessment.id,
    jsonb_build_object('client_request_id', p_client_request_id, 'noise_source', v_assessment.noise_source,
      'matrix_total', v_matrix_total, 'excessive', v_excessive, 'action_taken', v_assessment.action_taken,
      'notice_number', v_assessment.notice_number, 'dispatch_job_id', p_dispatch_job_id,
      'source_stop_id', v_source_stop_id, 'complainant_stop_id', v_complainant_stop_id,
      'assessment_distance_to_complainant_m', v_dist_complainant, 'assessment_distance_to_source_m', v_dist_source,
      'end_expires_at', v_end_expires_at));

  RETURN QUERY SELECT v_assessment.id, true, v_assessment.created_at, v_assessment.review_status, v_assessment.matrix_total;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."submit_officer_noise_assessment"(p_client_request_id uuid, p_assessed_at timestamp with time zone, p_noise_source text, p_noise_source_address text, p_action_taken text, p_volume_score smallint, p_time_score smallint, p_tone_score smallint, p_complaint_address text, p_complainant_site_id uuid, p_notice_number text, p_end_number text, p_occupant_name text, p_occupant_dob date, p_is_large_event_or_commercial boolean, p_police_requested boolean, p_police_present boolean, p_scene_description text, p_incident_report_text text, p_follow_up_required boolean, p_shift_id uuid, p_dispatch_job_id uuid, p_gps_lat double precision, p_gps_lng double precision) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."submit_officer_noise_assessment"(p_client_request_id uuid, p_assessed_at timestamp with time zone, p_noise_source text, p_noise_source_address text, p_action_taken text, p_volume_score smallint, p_time_score smallint, p_tone_score smallint, p_complaint_address text, p_complainant_site_id uuid, p_notice_number text, p_end_number text, p_occupant_name text, p_occupant_dob date, p_is_large_event_or_commercial boolean, p_police_requested boolean, p_police_present boolean, p_scene_description text, p_incident_report_text text, p_follow_up_required boolean, p_shift_id uuid, p_dispatch_job_id uuid, p_gps_lat double precision, p_gps_lng double precision) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."submit_officer_noise_assessment"(p_client_request_id uuid, p_assessed_at timestamp with time zone, p_noise_source text, p_noise_source_address text, p_action_taken text, p_volume_score smallint, p_time_score smallint, p_tone_score smallint, p_complaint_address text, p_complainant_site_id uuid, p_notice_number text, p_end_number text, p_occupant_name text, p_occupant_dob date, p_is_large_event_or_commercial boolean, p_police_requested boolean, p_police_present boolean, p_scene_description text, p_incident_report_text text, p_follow_up_required boolean, p_shift_id uuid, p_dispatch_job_id uuid, p_gps_lat double precision, p_gps_lng double precision) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."submit_officer_noise_assessment"(p_client_request_id uuid, p_assessed_at timestamp with time zone, p_noise_source text, p_noise_source_address text, p_action_taken text, p_volume_score smallint, p_time_score smallint, p_tone_score smallint, p_complaint_address text, p_complainant_site_id uuid, p_notice_number text, p_end_number text, p_occupant_name text, p_occupant_dob date, p_is_large_event_or_commercial boolean, p_police_requested boolean, p_police_present boolean, p_scene_description text, p_incident_report_text text, p_follow_up_required boolean, p_shift_id uuid, p_dispatch_job_id uuid, p_gps_lat double precision, p_gps_lng double precision) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."submit_officer_noise_assessment_v2"(p_client_request_id uuid, p_assessed_at timestamp with time zone, p_noise_source text, p_noise_source_address text, p_action_taken text DEFAULT 'no_action'::text, p_volume_score smallint DEFAULT 0, p_time_score smallint DEFAULT 1, p_tone_score smallint DEFAULT 0, p_complaint_address text DEFAULT NULL::text, p_complainant_site_id uuid DEFAULT NULL::uuid, p_notice_number text DEFAULT NULL::text, p_end_number text DEFAULT NULL::text, p_occupant_name text DEFAULT NULL::text, p_occupant_dob date DEFAULT NULL::date, p_is_large_event_or_commercial boolean DEFAULT false, p_police_requested boolean DEFAULT false, p_police_present boolean DEFAULT false, p_scene_description text DEFAULT NULL::text, p_incident_report_text text DEFAULT NULL::text, p_follow_up_required boolean DEFAULT false, p_shift_id uuid DEFAULT NULL::uuid, p_dispatch_job_id uuid DEFAULT NULL::uuid, p_gps_lat double precision DEFAULT NULL::double precision, p_gps_lng double precision DEFAULT NULL::double precision, p_evidence_items jsonb DEFAULT '[]'::jsonb, p_classification jsonb DEFAULT '{}'::jsonb)
 RETURNS TABLE(id uuid, created boolean, received_at timestamp with time zone, review_status text, matrix_total smallint, evidence_state text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_receipt record;
  v_assessment public.noise_assessments%ROWTYPE;
  v_item jsonb;
  v_evidence_id uuid;
  v_hash text;
  v_ordinal integer := 0;
  v_photos jsonb := '[]'::jsonb;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF jsonb_typeof(p_evidence_items) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'Noise evidence items must be an array';
  END IF;
  IF jsonb_array_length(p_evidence_items) = 0 THEN
    RAISE EXCEPTION 'At least one governed noise evidence photo is required';
  END IF;
  IF jsonb_typeof(p_classification) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'Structured noise classification receipt is required';
  END IF;

  SELECT user_profiles.organization_id INTO v_org
  FROM public.user_profiles
  WHERE user_profiles.id = v_actor AND user_profiles.deactivated_at IS NULL
    AND role IN ('officer', 'admin_officer', 'admin', 'master', 'grand_master');
  IF v_org IS NULL THEN RAISE EXCEPTION 'Active officer profile required'; END IF;

  SELECT * INTO v_receipt
  FROM public.submit_officer_noise_assessment(
    p_client_request_id => p_client_request_id,
    p_assessed_at => p_assessed_at,
    p_noise_source => p_noise_source,
    p_noise_source_address => p_noise_source_address,
    p_action_taken => p_action_taken,
    p_volume_score => p_volume_score,
    p_time_score => p_time_score,
    p_tone_score => p_tone_score,
    p_complaint_address => p_complaint_address,
    p_complainant_site_id => p_complainant_site_id,
    p_notice_number => p_notice_number,
    p_end_number => p_end_number,
    p_occupant_name => p_occupant_name,
    p_occupant_dob => p_occupant_dob,
    p_is_large_event_or_commercial => p_is_large_event_or_commercial,
    p_police_requested => p_police_requested,
    p_police_present => p_police_present,
    p_scene_description => p_scene_description,
    p_incident_report_text => p_incident_report_text,
    p_follow_up_required => p_follow_up_required,
    p_shift_id => p_shift_id,
    p_dispatch_job_id => p_dispatch_job_id,
    p_gps_lat => p_gps_lat,
    p_gps_lng => p_gps_lng
  );

  SELECT * INTO v_assessment
  FROM public.noise_assessments
  WHERE noise_assessments.id = v_receipt.id
    AND organization_id = v_org
    AND officer_user_id = v_actor
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Noise assessment receipt is outside caller authority'; END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_evidence_items)
  LOOP
    IF nullif(v_item->>'watermarked_path', '') IS NULL
       OR v_item->>'watermarked_path' NOT LIKE
          'org/' || v_org::text || '/noise-assessments/' || p_client_request_id::text || '/%' THEN
      RAISE EXCEPTION 'Noise evidence is outside the governed private intake path';
    END IF;
    v_hash := lower(coalesce(v_item->>'watermarked_sha256', ''));
    IF (v_hash ~ '^[0-9a-f]{64}$') IS DISTINCT FROM TRUE THEN
      RAISE EXCEPTION 'Noise evidence requires a valid SHA-256 custody hash';
    END IF;

    SELECT link.evidence_item_id INTO v_evidence_id
    FROM public.noise_assessment_evidence link
    JOIN public.evidence_items evidence ON evidence.id = link.evidence_item_id
    WHERE link.noise_assessment_id = v_assessment.id
      AND evidence.storage_path = v_item->>'watermarked_path';

    IF v_evidence_id IS NULL THEN
      INSERT INTO public.evidence_items (
        organization_id, module_key, evidence_kind, storage_path,
        captured_by_user_id, captured_at, metadata, sha256_hash,
        is_court_ready, locked_at
      ) VALUES (
        v_org, 'noise_control', coalesce(v_item->>'evidence_kind', 'photo'),
        v_item->>'watermarked_path', v_actor, p_assessed_at, v_item, v_hash,
        true, clock_timestamp()
      )
      RETURNING evidence_items.id INTO v_evidence_id;

      INSERT INTO public.noise_assessment_evidence (
        organization_id, noise_assessment_id, evidence_item_id, ordinal, purpose
      ) VALUES (
        v_org, v_assessment.id, v_evidence_id, v_ordinal,
        coalesce(v_item->>'purpose', 'primary_evidence')
      );
    END IF;

    v_photos := v_photos || jsonb_build_array(jsonb_build_object(
      'id', v_evidence_id,
      'storage_path', v_item->>'watermarked_path',
      'original_path', v_item->>'original_path',
      'captured_at', p_assessed_at,
      'sha256', v_hash
    ));
    v_ordinal := v_ordinal + 1;
  END LOOP;

  UPDATE public.noise_assessments
  SET photo_urls = v_photos,
      noise_ai_analysis = p_classification,
      bob_classification = nullif(trim(coalesce(p_classification->>'classification', '')), ''),
      bob_confidence = CASE
        WHEN p_classification->>'confidence' ~ '^[0-9]+([.][0-9]+)?$'
          THEN (p_classification->>'confidence')::real
        ELSE NULL
      END,
      updated_at = clock_timestamp()
  WHERE noise_assessments.id = v_assessment.id
  RETURNING * INTO v_assessment;

  RETURN QUERY
  SELECT v_assessment.id, v_receipt.created, v_receipt.received_at,
         v_assessment.review_status, v_assessment.matrix_total, 'verified'::text;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."submit_officer_noise_assessment_v2"(p_client_request_id uuid, p_assessed_at timestamp with time zone, p_noise_source text, p_noise_source_address text, p_action_taken text, p_volume_score smallint, p_time_score smallint, p_tone_score smallint, p_complaint_address text, p_complainant_site_id uuid, p_notice_number text, p_end_number text, p_occupant_name text, p_occupant_dob date, p_is_large_event_or_commercial boolean, p_police_requested boolean, p_police_present boolean, p_scene_description text, p_incident_report_text text, p_follow_up_required boolean, p_shift_id uuid, p_dispatch_job_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_evidence_items jsonb, p_classification jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."submit_officer_noise_assessment_v2"(p_client_request_id uuid, p_assessed_at timestamp with time zone, p_noise_source text, p_noise_source_address text, p_action_taken text, p_volume_score smallint, p_time_score smallint, p_tone_score smallint, p_complaint_address text, p_complainant_site_id uuid, p_notice_number text, p_end_number text, p_occupant_name text, p_occupant_dob date, p_is_large_event_or_commercial boolean, p_police_requested boolean, p_police_present boolean, p_scene_description text, p_incident_report_text text, p_follow_up_required boolean, p_shift_id uuid, p_dispatch_job_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_evidence_items jsonb, p_classification jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."submit_officer_noise_assessment_v2"(p_client_request_id uuid, p_assessed_at timestamp with time zone, p_noise_source text, p_noise_source_address text, p_action_taken text, p_volume_score smallint, p_time_score smallint, p_tone_score smallint, p_complaint_address text, p_complainant_site_id uuid, p_notice_number text, p_end_number text, p_occupant_name text, p_occupant_dob date, p_is_large_event_or_commercial boolean, p_police_requested boolean, p_police_present boolean, p_scene_description text, p_incident_report_text text, p_follow_up_required boolean, p_shift_id uuid, p_dispatch_job_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_evidence_items jsonb, p_classification jsonb) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."submit_officer_noise_assessment_v2"(p_client_request_id uuid, p_assessed_at timestamp with time zone, p_noise_source text, p_noise_source_address text, p_action_taken text, p_volume_score smallint, p_time_score smallint, p_tone_score smallint, p_complaint_address text, p_complainant_site_id uuid, p_notice_number text, p_end_number text, p_occupant_name text, p_occupant_dob date, p_is_large_event_or_commercial boolean, p_police_requested boolean, p_police_present boolean, p_scene_description text, p_incident_report_text text, p_follow_up_required boolean, p_shift_id uuid, p_dispatch_job_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_evidence_items jsonb, p_classification jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."submit_officer_timesheet_from_work"(p_client_event_id uuid, p_period_start date, p_period_end date, p_adjustment_hours numeric DEFAULT 0, p_notes text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, created boolean, submitted_at timestamp with time zone, work_derived_hours numeric, actual_hours numeric, source_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_staff public.staff_profiles%rowtype;
  v_sheet public.timesheets%rowtype;
  v_work record;
  v_work_json jsonb := '[]'::jsonb;
  v_work_minutes integer := 0;
  v_source_count integer := 0;
  v_adjustment numeric := coalesce(p_adjustment_hours, 0);
  v_actual numeric;
  v_scheduled numeric;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT sp.* INTO v_staff
  FROM public.staff_profiles sp
  JOIN public.user_profiles up ON up.id = v_user_id AND up.deactivated_at IS NULL
  WHERE (sp.user_id = v_user_id OR sp.id = v_user_id)
    AND sp.organization_id = up.organization_id
  LIMIT 1;
  IF NOT FOUND THEN RAISE EXCEPTION 'Active staff profile required'; END IF;
  IF p_client_event_id IS NULL THEN RAISE EXCEPTION 'client_event_id is required'; END IF;
  IF p_period_start IS NULL OR p_period_end IS NULL OR p_period_start > p_period_end OR p_period_end - p_period_start > 31 THEN
    RAISE EXCEPTION 'Timesheet period must be between 1 and 32 days';
  END IF;
  IF p_period_end > current_date THEN RAISE EXCEPTION 'Future timesheet periods cannot be submitted'; END IF;
  IF v_adjustment < -744 OR v_adjustment > 744 THEN RAISE EXCEPTION 'Adjustment hours are outside the accepted range'; END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('timesheet_submission:' || v_staff.id::text, 0));

  SELECT t.* INTO v_sheet
  FROM public.timesheets t
  WHERE t.organization_id = v_staff.organization_id
    AND t.staff_id = v_staff.id
    AND t.client_event_id = p_client_event_id;
  IF FOUND THEN
    RETURN QUERY SELECT v_sheet.id, false, v_sheet.submitted_at,
      coalesce(v_sheet.work_derived_hours, 0), v_sheet.actual_hours,
      (SELECT count(*)::integer FROM public.timesheet_work_entries e WHERE e.timesheet_id = v_sheet.id);
    RETURN;
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.timesheets t
    WHERE t.staff_id = v_staff.id
      AND daterange(t.period_start, t.period_end, '[]') && daterange(p_period_start, p_period_end, '[]')
  ) THEN
    RAISE EXCEPTION 'A timesheet already overlaps this period';
  END IF;

  FOR v_work IN SELECT * FROM public.get_officer_timesheet_work(p_period_start, p_period_end) LOOP
    v_work_minutes := v_work_minutes + v_work.calculated_minutes;
    v_source_count := v_source_count + 1;
    v_work_json := v_work_json || jsonb_build_array(jsonb_build_object(
      'source_type', v_work.source_type,
      'source_id', v_work.source_id,
      'work_status', v_work.work_status,
      'started_at', v_work.started_at,
      'ended_at', v_work.ended_at,
      'calculated_minutes', v_work.calculated_minutes,
      'label', v_work.label,
      'metadata', v_work.metadata
    ));
  END LOOP;

  v_actual := round((v_work_minutes::numeric / 60) + v_adjustment, 2);
  IF v_actual < 0 OR v_actual > 744 THEN RAISE EXCEPTION 'Derived actual hours are outside the accepted range'; END IF;

  SELECT coalesce(sum(extract(epoch FROM (s.scheduled_end - s.scheduled_start)) / 3600), 0)
  INTO v_scheduled
  FROM public.shifts s
  WHERE s.officer_user_id = v_user_id
    AND s.scheduled_start::date BETWEEN p_period_start AND p_period_end
    AND s.status IN ('accepted', 'in_progress', 'completed');

  INSERT INTO public.timesheets (
    organization_id, staff_id, period_start, period_end, scheduled_hours, actual_hours,
    overtime_hours, adjustment_hours, work_derived_hours, work_summary, status, notes,
    submitted_at, client_event_id
  )
  VALUES (
    v_staff.organization_id, v_staff.id, p_period_start, p_period_end,
    round(v_scheduled, 2), v_actual, greatest(0, v_actual - round(v_scheduled, 2)),
    v_adjustment, round(v_work_minutes::numeric / 60, 2),
    jsonb_build_object('source_count', v_source_count, 'work_minutes', v_work_minutes, 'entries', v_work_json),
    'submitted', nullif(trim(coalesce(p_notes, '')), ''), clock_timestamp(), p_client_event_id
  )
  RETURNING * INTO v_sheet;

  FOR v_work IN SELECT value FROM jsonb_array_elements(v_work_json) LOOP
    INSERT INTO public.timesheet_work_entries (
      organization_id, timesheet_id, source_type, source_id, work_status,
      started_at, ended_at, calculated_minutes, metadata
    )
    VALUES (
      v_staff.organization_id, v_sheet.id, v_work.value->>'source_type',
      (v_work.value->>'source_id')::uuid, v_work.value->>'work_status',
      (v_work.value->>'started_at')::timestamptz, (v_work.value->>'ended_at')::timestamptz,
      (v_work.value->>'calculated_minutes')::integer,
      coalesce(v_work.value->'metadata', '{}'::jsonb)
    );
  END LOOP;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (
    v_staff.organization_id, v_user_id, 'timesheet_submitted_from_work', 'timesheets', v_sheet.id,
    jsonb_build_object(
      'staff_id', v_sheet.staff_id,
      'period_start', p_period_start,
      'period_end', p_period_end,
      'work_derived_hours', v_sheet.work_derived_hours,
      'adjustment_hours', v_adjustment,
      'actual_hours', v_sheet.actual_hours,
      'source_count', v_source_count
    )
  );

  RETURN QUERY SELECT v_sheet.id, true, v_sheet.submitted_at,
    v_sheet.work_derived_hours, v_sheet.actual_hours, v_source_count;
END;
$function$;
COMMENT ON FUNCTION "public"."submit_officer_timesheet_from_work"(p_client_event_id uuid, p_period_start date, p_period_end date, p_adjustment_hours numeric, p_notes text) IS 'Submits the officer''s timesheet for a period from completed work (get_officer_timesheet_work). Rostered hours are the officer''s accepted/in-progress/completed shifts in the period across every branch; the timesheet itself belongs to the employer (home organisation). Submissions serialize per staff profile before idempotency and overlapping-period checks.';
REVOKE ALL ON FUNCTION "public"."submit_officer_timesheet_from_work"(p_client_event_id uuid, p_period_start date, p_period_end date, p_adjustment_hours numeric, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."submit_officer_timesheet_from_work"(p_client_event_id uuid, p_period_start date, p_period_end date, p_adjustment_hours numeric, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."submit_officer_timesheet_from_work"(p_client_event_id uuid, p_period_start date, p_period_end date, p_adjustment_hours numeric, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."submit_officer_timesheet_from_work"(p_client_event_id uuid, p_period_start date, p_period_end date, p_adjustment_hours numeric, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."submit_shift_debrief"(p_shift_id uuid, p_client_event_id uuid, p_summary text, p_safety_incident_reported boolean DEFAULT false, p_equipment_issue_reported boolean DEFAULT false, p_follow_up_required boolean DEFAULT false, p_follow_up_notes text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, created boolean, submitted_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_shift public.shifts%rowtype;
  v_debrief public.shift_debriefs%rowtype;
begin
  if v_user_id is null then raise exception 'Authentication required'; end if;
  if p_client_event_id is null then raise exception 'client_event_id is required'; end if;
  if char_length(trim(coalesce(p_summary, ''))) not between 10 and 5000 then raise exception 'Debrief summary must be between 10 and 5000 characters'; end if;
  if p_follow_up_required and nullif(trim(coalesce(p_follow_up_notes, '')), '') is null then raise exception 'Follow-up notes are required'; end if;
  select s.* into v_shift from public.shifts s where s.id = p_shift_id for share;
  if not found then raise exception 'Shift not found'; end if;
  if v_shift.officer_user_id <> v_user_id then raise exception 'Shift does not belong to the authenticated officer'; end if;
  if v_shift.status not in ('accepted', 'in_progress', 'completed') then raise exception 'Shift is not eligible for debrief'; end if;
  select d.* into v_debrief from public.shift_debriefs d
  where d.organization_id = v_shift.organization_id and d.officer_user_id = v_user_id and d.client_event_id = p_client_event_id;
  if found then return query select v_debrief.id, false, v_debrief.submitted_at; return; end if;
  if exists (select 1 from public.shift_debriefs d where d.shift_id = p_shift_id) then raise exception 'A debrief has already been submitted for this shift'; end if;
  insert into public.shift_debriefs (organization_id, shift_id, officer_user_id, client_event_id, summary, safety_incident_reported, equipment_issue_reported, follow_up_required, follow_up_notes)
  values (v_shift.organization_id, p_shift_id, v_user_id, p_client_event_id, trim(p_summary), coalesce(p_safety_incident_reported, false), coalesce(p_equipment_issue_reported, false), coalesce(p_follow_up_required, false), nullif(trim(coalesce(p_follow_up_notes, '')), ''))
  returning * into v_debrief;
  insert into public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (v_shift.organization_id, v_user_id, 'shift_debrief_submitted', 'shift_debriefs', v_debrief.id,
    jsonb_build_object('shift_id', p_shift_id, 'safety_incident_reported', v_debrief.safety_incident_reported, 'equipment_issue_reported', v_debrief.equipment_issue_reported, 'follow_up_required', v_debrief.follow_up_required));
  return query select v_debrief.id, true, v_debrief.submitted_at;
end;
$function$;
COMMENT ON FUNCTION "public"."submit_shift_debrief"(p_shift_id uuid, p_client_event_id uuid, p_summary text, p_safety_incident_reported boolean, p_equipment_issue_reported boolean, p_follow_up_required boolean, p_follow_up_notes text) IS 'Creates one retry-safe, self-owned, append-only handover per eligible shift and audits submission.';
REVOKE ALL ON FUNCTION "public"."submit_shift_debrief"(p_shift_id uuid, p_client_event_id uuid, p_summary text, p_safety_incident_reported boolean, p_equipment_issue_reported boolean, p_follow_up_required boolean, p_follow_up_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."submit_shift_debrief"(p_shift_id uuid, p_client_event_id uuid, p_summary text, p_safety_incident_reported boolean, p_equipment_issue_reported boolean, p_follow_up_required boolean, p_follow_up_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."submit_shift_debrief"(p_shift_id uuid, p_client_event_id uuid, p_summary text, p_safety_incident_reported boolean, p_equipment_issue_reported boolean, p_follow_up_required boolean, p_follow_up_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."submit_shift_debrief"(p_shift_id uuid, p_client_event_id uuid, p_summary text, p_safety_incident_reported boolean, p_equipment_issue_reported boolean, p_follow_up_required boolean, p_follow_up_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."submit_smoke_assessment_receipt"(p_client_request_id uuid, p_assessed_at timestamp with time zone, p_smoke_source_type text DEFAULT 'domestic_solid_fuel'::text, p_complaint_source text DEFAULT 'neighbour'::text, p_severity text DEFAULT 'medium'::text, p_action_taken text DEFAULT 'no_action'::text, p_scene_description text DEFAULT NULL::text, p_address text DEFAULT NULL::text, p_complaint_address text DEFAULT NULL::text, p_complainant_site_id uuid DEFAULT NULL::uuid, p_site_id uuid DEFAULT NULL::uuid, p_notice_number text DEFAULT NULL::text, p_legal_basis text DEFAULT 'RMA s.17A'::text, p_is_out_of_hours boolean DEFAULT false, p_follow_up_required boolean DEFAULT false, p_shift_id uuid DEFAULT NULL::uuid, p_dispatch_job_id uuid DEFAULT NULL::uuid, p_evidence_items jsonb DEFAULT '[]'::jsonb, p_classification jsonb DEFAULT '{}'::jsonb)
 RETURNS TABLE(id uuid, created boolean, received_at timestamp with time zone, evidence_state text, review_state text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
declare
  v_user_id uuid := auth.uid();
  v_org_id uuid;
  v_existing public.smoke_assessments%rowtype;
  v_assessment public.smoke_assessments%rowtype;
  v_review_state text;
  v_evidence_state text := 'verified';
  v_item jsonb;
  v_evidence_id uuid;
  v_photo_arr jsonb := '[]'::jsonb;
  v_ordinal integer := 0;
begin
  if v_user_id is null then raise exception 'Authentication required'; end if;
  select p.organization_id into v_org_id from public.user_profiles p where p.id = v_user_id and p.deactivated_at is null and p.role in ('officer', 'admin_officer', 'admin', 'master', 'grand_master');
  if v_org_id is null then raise exception 'Active officer profile required'; end if;
  if p_client_request_id is null then raise exception 'client_request_id is required'; end if;

  if p_assessed_at is null or p_assessed_at > now() + interval '5 minutes' or p_assessed_at < now() - interval '24 hours' then
    raise exception 'assessed_at is outside the accepted capture window';
  end if;

  if nullif(trim(coalesce(p_address, '')), '') is null then
    raise exception 'Observed smoke location address is required';
  end if;

  if p_action_taken in ('abatement_notice', 'infringement_notice') and nullif(trim(coalesce(p_notice_number, '')), '') is null then
    raise exception 'Notice number is required for statutory abatement or infringement notices';
  end if;

  if p_shift_id is not null and not exists (select 1 from public.shifts s where s.id = p_shift_id and s.organization_id = v_org_id) then
    raise exception 'Shift does not belong to the officer organisation';
  end if;

  if p_dispatch_job_id is not null and not exists (select 1 from public.dispatch_jobs d where d.id = p_dispatch_job_id and d.organization_id = v_org_id) then
    raise exception 'Dispatch job does not belong to the officer organisation';
  end if;

  -- Idempotency check
  select s.* into v_existing from public.smoke_assessments s
    where s.organization_id = v_org_id and s.officer_user_id = v_user_id and s.client_request_id = p_client_request_id;
  if found then
    return query select v_existing.id, false, v_existing.created_at, v_existing.evidence_state, v_existing.review_state;
    return;
  end if;

  -- Derive initial review state
  if p_classification is null or coalesce(p_classification->>'classification', '') = '' or coalesce(p_classification->>'status', '') = 'unavailable' then
    v_review_state := 'requires_supervisor_review';
  else
    v_review_state := 'submitted';
  end if;

  insert into public.smoke_assessments (
    organization_id, officer_user_id, officer_id, client_request_id, assessed_at,
    smoke_source_type, smoke_source, complaint_source, severity, action_taken, action,
    scene_description, address, complaint_address, complainant_site_id, site_id,
    notice_number, legal_basis, is_out_of_hours, follow_up_required,
    shift_id, dispatch_job_id, status, evidence_state, review_state,
    bob_classification, bob_confidence
  ) values (
    v_org_id, v_user_id, v_user_id, p_client_request_id, p_assessed_at,
    p_smoke_source_type, p_smoke_source_type, p_complaint_source, p_severity, p_action_taken, p_action_taken,
    nullif(trim(coalesce(p_scene_description, '')), ''), trim(p_address), nullif(trim(coalesce(p_complaint_address, '')), ''), p_complainant_site_id, p_site_id,
    nullif(trim(coalesce(p_notice_number, '')), ''), coalesce(p_legal_basis, 'RMA s.17A'), coalesce(p_is_out_of_hours, false), coalesce(p_follow_up_required, false),
    p_shift_id, p_dispatch_job_id, 'open', v_evidence_state, v_review_state,
    nullif(trim(coalesce(p_classification->>'classification', '')), ''), (p_classification->>'confidence')::real
  ) returning * into v_assessment;

  -- Process evidence items
  if jsonb_array_length(p_evidence_items) > 0 then
    for v_item in select * from jsonb_array_elements(p_evidence_items) loop
      v_evidence_id := gen_random_uuid();
      insert into public.evidence_items (
        id, organization_id, module_key, evidence_kind, storage_path, captured_by_user_id, captured_at, metadata
      ) values (
        v_evidence_id, v_org_id, 'smoke_complaints', coalesce(v_item->>'evidence_kind', 'photo'), v_item->>'watermarked_path', v_user_id, p_assessed_at, coalesce(v_item, '{}'::jsonb)
      );

      insert into public.smoke_assessment_evidence (
        organization_id, smoke_assessment_id, evidence_item_id, ordinal, purpose
      ) values (
        v_org_id, v_assessment.id, v_evidence_id, v_ordinal, coalesce(v_item->>'purpose', 'primary_evidence')
      );

      v_photo_arr := v_photo_arr || jsonb_build_array(jsonb_build_object(
        'id', v_evidence_id,
        'storage_path', v_item->>'watermarked_path',
        'original_path', v_item->>'original_path',
        'captured_at', p_assessed_at
      ));
      v_ordinal := v_ordinal + 1;
    end loop;

    update public.smoke_assessments
      set photo_urls = v_photo_arr
      where id = v_assessment.id;
  end if;

  insert into public.audit_log (
    organization_id, actor_user_id, action, target_table, target_id, metadata
  ) values (
    v_org_id, v_user_id, 'smoke_assessment_submitted', 'smoke_assessments', v_assessment.id,
    jsonb_build_object(
      'client_request_id', p_client_request_id,
      'smoke_source_type', v_assessment.smoke_source_type,
      'severity', v_assessment.severity,
      'action_taken', v_assessment.action_taken,
      'is_out_of_hours', v_assessment.is_out_of_hours,
      'review_state', v_review_state,
      'evidence_count', v_ordinal
    )
  );

  return query select v_assessment.id, true, v_assessment.created_at, v_assessment.evidence_state, v_assessment.review_state;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."submit_smoke_assessment_receipt"(p_client_request_id uuid, p_assessed_at timestamp with time zone, p_smoke_source_type text, p_complaint_source text, p_severity text, p_action_taken text, p_scene_description text, p_address text, p_complaint_address text, p_complainant_site_id uuid, p_site_id uuid, p_notice_number text, p_legal_basis text, p_is_out_of_hours boolean, p_follow_up_required boolean, p_shift_id uuid, p_dispatch_job_id uuid, p_evidence_items jsonb, p_classification jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."submit_smoke_assessment_receipt"(p_client_request_id uuid, p_assessed_at timestamp with time zone, p_smoke_source_type text, p_complaint_source text, p_severity text, p_action_taken text, p_scene_description text, p_address text, p_complaint_address text, p_complainant_site_id uuid, p_site_id uuid, p_notice_number text, p_legal_basis text, p_is_out_of_hours boolean, p_follow_up_required boolean, p_shift_id uuid, p_dispatch_job_id uuid, p_evidence_items jsonb, p_classification jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."submit_smoke_assessment_receipt"(p_client_request_id uuid, p_assessed_at timestamp with time zone, p_smoke_source_type text, p_complaint_source text, p_severity text, p_action_taken text, p_scene_description text, p_address text, p_complaint_address text, p_complainant_site_id uuid, p_site_id uuid, p_notice_number text, p_legal_basis text, p_is_out_of_hours boolean, p_follow_up_required boolean, p_shift_id uuid, p_dispatch_job_id uuid, p_evidence_items jsonb, p_classification jsonb) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."submit_smoke_assessment_receipt"(p_client_request_id uuid, p_assessed_at timestamp with time zone, p_smoke_source_type text, p_complaint_source text, p_severity text, p_action_taken text, p_scene_description text, p_address text, p_complaint_address text, p_complainant_site_id uuid, p_site_id uuid, p_notice_number text, p_legal_basis text, p_is_out_of_hours boolean, p_follow_up_required boolean, p_shift_id uuid, p_dispatch_job_id uuid, p_evidence_items jsonb, p_classification jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."submit_smoke_assessment_receipt_v2"(p_client_request_id uuid, p_assessed_at timestamp with time zone, p_smoke_source_type text DEFAULT 'domestic_solid_fuel'::text, p_complaint_source text DEFAULT 'neighbour'::text, p_severity text DEFAULT 'moderate'::text, p_action_taken text DEFAULT 'no_action'::text, p_scene_description text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_source_confirmed boolean DEFAULT false, p_address text DEFAULT NULL::text, p_complaint_address text DEFAULT NULL::text, p_complainant_site_id uuid DEFAULT NULL::uuid, p_site_id uuid DEFAULT NULL::uuid, p_notice_number text DEFAULT NULL::text, p_legal_basis text DEFAULT 'RMA s.17A'::text, p_is_out_of_hours boolean DEFAULT false, p_follow_up_required boolean DEFAULT false, p_shift_id uuid DEFAULT NULL::uuid, p_dispatch_job_id uuid DEFAULT NULL::uuid, p_evidence_items jsonb DEFAULT '[]'::jsonb, p_classification jsonb DEFAULT '{}'::jsonb)
 RETURNS TABLE(id uuid, created boolean, received_at timestamp with time zone, evidence_state text, review_state text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_receipt record;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF coalesce(p_source_confirmed, false) IS FALSE THEN
    RAISE EXCEPTION 'Officer must confirm the observed smoke source';
  END IF;
  IF p_severity NOT IN ('low', 'moderate', 'high', 'critical') THEN
    RAISE EXCEPTION 'Unsupported smoke severity';
  END IF;

  SELECT * INTO v_receipt
  FROM public.submit_smoke_assessment_receipt(
    p_client_request_id => p_client_request_id,
    p_assessed_at => p_assessed_at,
    p_smoke_source_type => p_smoke_source_type,
    p_complaint_source => p_complaint_source,
    p_severity => p_severity,
    p_action_taken => p_action_taken,
    p_scene_description => p_scene_description,
    p_address => p_address,
    p_complaint_address => p_complaint_address,
    p_complainant_site_id => p_complainant_site_id,
    p_site_id => p_site_id,
    p_notice_number => p_notice_number,
    p_legal_basis => p_legal_basis,
    p_is_out_of_hours => p_is_out_of_hours,
    p_follow_up_required => p_follow_up_required,
    p_shift_id => p_shift_id,
    p_dispatch_job_id => p_dispatch_job_id,
    p_evidence_items => p_evidence_items,
    p_classification => p_classification
  );

  UPDATE public.smoke_assessments
  SET source_confirmed = true,
      notes = nullif(trim(coalesce(p_notes, '')), ''),
      smoke_ai_analysis = p_classification,
      smoke_ai_analyzed_at = CASE
        WHEN p_classification->>'status' = 'available' THEN clock_timestamp()
        ELSE smoke_ai_analyzed_at
      END,
      review_state = 'requires_supervisor_review',
      updated_at = clock_timestamp()
  WHERE smoke_assessments.id = v_receipt.id;

  RETURN QUERY
  SELECT v_receipt.id, v_receipt.created, v_receipt.received_at,
         v_receipt.evidence_state, 'requires_supervisor_review'::text;
END;
$function$;
COMMENT ON FUNCTION "public"."submit_smoke_assessment_receipt_v2"(p_client_request_id uuid, p_assessed_at timestamp with time zone, p_smoke_source_type text, p_complaint_source text, p_severity text, p_action_taken text, p_scene_description text, p_notes text, p_source_confirmed boolean, p_address text, p_complaint_address text, p_complainant_site_id uuid, p_site_id uuid, p_notice_number text, p_legal_basis text, p_is_out_of_hours boolean, p_follow_up_required boolean, p_shift_id uuid, p_dispatch_job_id uuid, p_evidence_items jsonb, p_classification jsonb) IS 'Caller-context smoke receipt preserving human source confirmation, notes, and structured advisory classification without changing legal authority.';
REVOKE ALL ON FUNCTION "public"."submit_smoke_assessment_receipt_v2"(p_client_request_id uuid, p_assessed_at timestamp with time zone, p_smoke_source_type text, p_complaint_source text, p_severity text, p_action_taken text, p_scene_description text, p_notes text, p_source_confirmed boolean, p_address text, p_complaint_address text, p_complainant_site_id uuid, p_site_id uuid, p_notice_number text, p_legal_basis text, p_is_out_of_hours boolean, p_follow_up_required boolean, p_shift_id uuid, p_dispatch_job_id uuid, p_evidence_items jsonb, p_classification jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."submit_smoke_assessment_receipt_v2"(p_client_request_id uuid, p_assessed_at timestamp with time zone, p_smoke_source_type text, p_complaint_source text, p_severity text, p_action_taken text, p_scene_description text, p_notes text, p_source_confirmed boolean, p_address text, p_complaint_address text, p_complainant_site_id uuid, p_site_id uuid, p_notice_number text, p_legal_basis text, p_is_out_of_hours boolean, p_follow_up_required boolean, p_shift_id uuid, p_dispatch_job_id uuid, p_evidence_items jsonb, p_classification jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."submit_smoke_assessment_receipt_v2"(p_client_request_id uuid, p_assessed_at timestamp with time zone, p_smoke_source_type text, p_complaint_source text, p_severity text, p_action_taken text, p_scene_description text, p_notes text, p_source_confirmed boolean, p_address text, p_complaint_address text, p_complainant_site_id uuid, p_site_id uuid, p_notice_number text, p_legal_basis text, p_is_out_of_hours boolean, p_follow_up_required boolean, p_shift_id uuid, p_dispatch_job_id uuid, p_evidence_items jsonb, p_classification jsonb) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."submit_smoke_assessment_receipt_v2"(p_client_request_id uuid, p_assessed_at timestamp with time zone, p_smoke_source_type text, p_complaint_source text, p_severity text, p_action_taken text, p_scene_description text, p_notes text, p_source_confirmed boolean, p_address text, p_complaint_address text, p_complainant_site_id uuid, p_site_id uuid, p_notice_number text, p_legal_basis text, p_is_out_of_hours boolean, p_follow_up_required boolean, p_shift_id uuid, p_dispatch_job_id uuid, p_evidence_items jsonb, p_classification jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."submit_website_enquiry"(p_name text, p_message text, p_privacy_ack boolean, p_client_hash text, p_email text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_organisation text DEFAULT NULL::text, p_location text DEFAULT NULL::text, p_services text[] DEFAULT NULL::text[], p_preferred_contact text DEFAULT NULL::text, p_source_page text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  c_allowed_services constant text[] := ARRAY[
    'static-guarding', 'patrols-response', 'cctv-surveillance', 'raptor', 'gates-access',
    'investigations', 'forestry-rural', 'rams-permits', 'council-compliance', 'pest-control', 'other'
  ]::text[];
  v_provider uuid;
  v_name text := btrim(coalesce(p_name, ''));
  v_message text := btrim(coalesce(p_message, ''));
  v_email text := nullif(btrim(coalesce(p_email, '')), '');
  v_phone text := nullif(btrim(coalesce(p_phone, '')), '');
  v_organisation text := nullif(btrim(coalesce(p_organisation, '')), '');
  v_location text := nullif(btrim(coalesce(p_location, '')), '');
  v_source_page text := nullif(btrim(coalesce(p_source_page, '')), '');
  v_preferred text := coalesce(nullif(btrim(coalesce(p_preferred_contact, '')), ''), 'either');
  v_client_hash text := lower(btrim(coalesce(p_client_hash, '')));
  v_services text[] := '{}'::text[];
  v_recent integer;
  v_id uuid;
  v_reference text;
  v_attempt integer := 0;
  v_role text;
BEGIN
  SELECT t.service_provider_organization_id
    INTO v_provider
    FROM private.platform_tenancy t
   WHERE t.singleton;
  IF v_provider IS NULL THEN
    RAISE EXCEPTION 'Single-provider tenancy is not configured';
  END IF;

  -- Defence in depth: the edge function validates first; these checks keep
  -- the table honest if anything else ever calls this function.
  IF char_length(v_name) NOT BETWEEN 2 AND 120 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'website_enquiry_invalid:name';
  END IF;
  IF v_email IS NOT NULL AND (char_length(v_email) > 200 OR v_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$') THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'website_enquiry_invalid:email';
  END IF;
  IF v_phone IS NOT NULL AND (char_length(v_phone) > 40 OR v_phone !~ '^[0-9 +()-]+$' OR v_phone !~ '[0-9]') THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'website_enquiry_invalid:phone';
  END IF;
  IF v_email IS NULL AND v_phone IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'website_enquiry_invalid:email';
  END IF;
  IF v_organisation IS NOT NULL AND char_length(v_organisation) > 160 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'website_enquiry_invalid:organisation';
  END IF;
  IF v_location IS NOT NULL AND char_length(v_location) > 160 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'website_enquiry_invalid:location';
  END IF;
  IF p_services IS NOT NULL THEN
    IF array_position(p_services, NULL) IS NOT NULL OR NOT (p_services <@ c_allowed_services) THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'website_enquiry_invalid:services';
    END IF;
    SELECT coalesce(array_agg(d.service ORDER BY d.first_seen), '{}'::text[])
      INTO v_services
      FROM (
        SELECT u.service, min(u.ord) AS first_seen
          FROM unnest(p_services) WITH ORDINALITY AS u(service, ord)
         GROUP BY u.service
      ) d;
    IF cardinality(v_services) > 11 THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'website_enquiry_invalid:services';
    END IF;
  END IF;
  IF char_length(v_message) NOT BETWEEN 10 AND 4000 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'website_enquiry_invalid:message';
  END IF;
  IF v_preferred NOT IN ('email', 'phone', 'either') THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'website_enquiry_invalid:preferred_contact';
  END IF;
  IF p_privacy_ack IS DISTINCT FROM true THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'website_enquiry_invalid:privacy_ack';
  END IF;
  IF v_source_page IS NOT NULL AND char_length(v_source_page) > 200 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'website_enquiry_invalid:source_page';
  END IF;
  IF v_client_hash !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'website_enquiry_invalid:client_hash';
  END IF;

  -- Five enquiries per client hash per rolling hour. The advisory lock
  -- serialises concurrent submissions from the same client so the count is
  -- exact. PT429 makes PostgREST answer HTTP 429.
  PERFORM pg_advisory_xact_lock(hashtext('website_enquiry:' || v_client_hash));
  SELECT count(*)
    INTO v_recent
    FROM public.website_enquiries e
   WHERE e.client_hash = v_client_hash
     AND e.received_at > clock_timestamp() - interval '1 hour';
  IF v_recent >= 5 THEN
    RAISE EXCEPTION USING ERRCODE = 'PT429', MESSAGE = 'website_enquiry_rate_limited',
      HINT = 'Five enquiries per hour from one client. Try again later.';
  END IF;

  LOOP
    v_attempt := v_attempt + 1;
    v_id := gen_random_uuid();
    v_reference := 'ENQ-' || upper(substr(replace(v_id::text, '-', ''), 1, 6));
    BEGIN
      INSERT INTO public.website_enquiries (
        id, provider_organization_id, reference, name, email, phone, organisation,
        location, services, message, preferred_contact, privacy_ack, source_page, client_hash
      ) VALUES (
        v_id, v_provider, v_reference, v_name, v_email, v_phone, v_organisation,
        v_location, v_services, v_message, v_preferred, true, v_source_page, v_client_hash
      );
      EXIT;
    EXCEPTION WHEN unique_violation THEN
      IF v_attempt >= 5 THEN
        RAISE;
      END IF;
    END;
  END LOOP;

  -- Tell R&M admins. Role 'admin' notifications are also shown to
  -- admin_officer; masters need their own row. The body carries no personal
  -- details. A notification failure must never lose the lead.
  BEGIN
    FOREACH v_role IN ARRAY ARRAY['admin', 'master']::text[] LOOP
      PERFORM public.enqueue_notification(
        p_organization_id => v_provider,
        p_category => 'crm_client',
        p_title => 'New website enquiry ' || v_reference,
        p_body => 'Received from the R&M website. Open Website enquiries to reply.',
        p_severity => 'info',
        p_recipient_role => v_role,
        p_link_page => 'website-enquiries',
        p_link_payload => jsonb_build_object('enquiry_id', v_id, 'reference', v_reference),
        p_dedup_key => 'website_enquiry:' || v_id::text || ':' || v_role
      );
    END LOOP;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'website enquiry % notification failed: %', v_reference, SQLERRM;
  END;

  RETURN v_reference;
END;
$function$;
COMMENT ON FUNCTION "public"."submit_website_enquiry"(p_name text, p_message text, p_privacy_ack boolean, p_client_hash text, p_email text, p_phone text, p_organisation text, p_location text, p_services text[], p_preferred_contact text, p_source_page text) IS 'Service-role intake for the public website-enquiry edge function. Resolves the provider from private.platform_tenancy, re-validates every field (22023 website_enquiry_invalid:<field>), limits each client hash to 5 per hour (PT429 website_enquiry_rate_limited), inserts the enquiry, notifies R&M admins and returns the ENQ-XXXXXX reference.';
REVOKE ALL ON FUNCTION "public"."submit_website_enquiry"(p_name text, p_message text, p_privacy_ack boolean, p_client_hash text, p_email text, p_phone text, p_organisation text, p_location text, p_services text[], p_preferred_contact text, p_source_page text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."submit_website_enquiry"(p_name text, p_message text, p_privacy_ack boolean, p_client_hash text, p_email text, p_phone text, p_organisation text, p_location text, p_services text[], p_preferred_contact text, p_source_page text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."submit_website_enquiry"(p_name text, p_message text, p_privacy_ack boolean, p_client_hash text, p_email text, p_phone text, p_organisation text, p_location text, p_services text[], p_preferred_contact text, p_source_page text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."supersede_duplicate_patrol_events"(p_batch_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_items jsonb)
 RETURNS TABLE(external_ref text, record_id uuid, outcome text, detail text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_batch public.file_import_batches%rowtype;
  v_item jsonb;
  v_payload jsonb;
  v_ref text;
  v_canonical_ref text;
  v_event public.location_events%rowtype;
  v_canonical public.location_events%rowtype;
  v_version public.patrol_import_record_versions%rowtype;
  v_has_version boolean;
  v_shift numeric;
  v_mismatch text[];
  v_hold text;
begin
  v_batch := public.patrol_source_sync_batch(p_batch_id, p_provider_organization_id, p_client_organization_id);
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) > 500 then
    raise exception 'Between 0 and 500 supersede rows are required per call';
  end if;

  for v_item in
    select value from jsonb_array_elements(p_items) value order by value->>'external_ref'
  loop
    v_ref := nullif(btrim(v_item->>'external_ref'), '');
    v_canonical_ref := nullif(btrim(v_item->>'canonical_external_ref'), '');
    if v_item->>'kind' is distinct from 'event' or v_ref is null or v_canonical_ref is null or v_ref = v_canonical_ref then
      raise exception 'Supersede rows require an event reference and a different canonical reference';
    end if;
    v_payload := case when v_item ? 'desired' then public.patrol_source_assert_row_provenance(v_batch, v_item || jsonb_build_object(
      'record_id', coalesce(nullif(v_item->>'record_id', ''), '00000000-0000-0000-0000-000000000000'))) end;
    v_hold := null;
    perform pg_advisory_xact_lock(hashtextextended(p_client_organization_id::text || ':evidence:' || least(v_ref, v_canonical_ref), 0));
    perform pg_advisory_xact_lock(hashtextextended(p_client_organization_id::text || ':evidence:' || greatest(v_ref, v_canonical_ref), 0));

    if exists (select 1 from public.location_events_superseded archived
               where archived.client_organization_id = p_client_organization_id and archived.external_ref = v_ref) then
      external_ref := v_ref; record_id := null; outcome := 'already_superseded'; detail := null;
      return next; continue;
    end if;

    select * into v_event from public.location_events event
    where event.organization_id = p_client_organization_id and event.external_ref = v_ref
      and event.source = 'rm_patrol_log_import'
    for update;
    if not found then
      external_ref := v_ref; record_id := null; outcome := 'held'; detail := 'record_not_owned_by_importer';
      return next; continue;
    end if;
    select * into v_canonical from public.location_events event
    where event.organization_id = p_client_organization_id and event.external_ref = v_canonical_ref
      and event.source = 'rm_patrol_log_import'
    for update;
    if not found then
      v_hold := 'canonical_record_missing';
    end if;

    -- Only same-workbook duplicates qualify. Year sheets stay separate (owner ruling) and
    -- Update worksheet copies must go through the one-to-one paired path.
    if v_hold is null then
      v_hold := (select case
        when nullif(source->>'source_sheet', '') is null or nullif(v_canonical.payload->>'source_sheet', '') is null
          or nullif(source->>'source_sha256', '') is null
          or source->>'source_sha256' is distinct from v_canonical.payload->>'source_sha256'
          or source->>'source_file' is distinct from v_canonical.payload->>'source_file'
          then 'supersede_requires_same_workbook_provenance'
        when source->>'source_sheet' ~* '^update\M' then 'update_copy_requires_paired_path'
        when source->>'source_sheet' ~ '^[0-9]{4}$' then 'source_year_records_remain_separate'
      end from (select coalesce(v_payload, v_event.payload) as source) copy_source);
    end if;

    if v_hold is null then
      v_shift := extract(epoch from v_event.occurred_at - v_canonical.occurred_at);
      select coalesce(array_agg(field order by field), '{}'::text[]) into v_mismatch
      from (
        select 'zone_id' as field where v_event.zone_id is distinct from v_canonical.zone_id
        union all select 'site_id' where v_event.client_site_id is distinct from v_canonical.client_site_id
        union all select 'officer_id' where v_event.observed_entity_id is distinct from v_canonical.observed_entity_id
        union all select 'event_type' where v_event.event_type is distinct from v_canonical.event_type
        -- A visit-level copy (no issue status) may stand for any job row of the same visit.
        union all select 'status' where v_event.status is not null and v_event.status is distinct from v_canonical.status
        union all select 'comments' where nullif(btrim(v_event.payload->>'comments'), '') is distinct from nullif(btrim(v_canonical.payload->>'comments'), '')
        -- A copy may carry the legacy one-hour artifact on either side, but only in NZ daylight time.
        union all select 'occurred_at' where not (v_shift = 0 or (abs(v_shift) = 3600
          and public.patrol_nz_daylight(least(v_event.occurred_at, v_canonical.occurred_at))))
      ) compared;
      if cardinality(v_mismatch) > 0 then
        v_hold := 'not_an_identical_copy:' || array_to_string(v_mismatch, ',');
      end if;
    end if;

    if v_hold is null then
      v_hold := public.patrol_source_event_dependency_hold(p_provider_organization_id, p_client_organization_id, v_event.id, v_ref, p_batch_id);
    end if;

    if v_hold is null then
      select * into v_version from public.patrol_import_record_versions version
      where version.record_kind = 'event' and version.record_id = v_event.id and version.is_current
      for update;
      v_has_version := found;
      if v_has_version and v_version.external_ref <> v_ref then
        raise exception 'Source history scope does not match the requested record';
      end if;
    end if;

    if v_hold is not null then
      external_ref := v_ref; record_id := v_event.id; outcome := 'held'; detail := v_hold;
      return next; continue;
    end if;

    insert into public.location_events_superseded(
      provider_organization_id, client_organization_id, location_event_id, external_ref,
      canonical_location_event_id, canonical_external_ref, reason_code, batch_id, event_snapshot, superseded_by
    ) values (
      p_provider_organization_id, p_client_organization_id, v_event.id, v_ref,
      v_canonical.id, v_canonical_ref, 'duplicate_of_canonical_sheet', p_batch_id, to_jsonb(v_event), auth.uid()
    );

    if v_has_version or v_payload is not null then
      if v_has_version then
        update public.patrol_import_record_versions set is_current = false where id = v_version.id;
      end if;
      insert into public.patrol_import_record_versions(
        provider_organization_id, client_organization_id, record_kind, record_id, external_ref, source_profile,
        source_file, source_sheet, source_row, source_sha256, derivative_sha256, source_fingerprint, batch_id,
        version_no, change_kind, changed_fields, state_before, state_after, applied_by
      ) values (
        p_provider_organization_id, p_client_organization_id, 'event', v_event.id, v_ref,
        coalesce(v_payload->>'classification_profile', v_version.source_profile),
        coalesce(v_payload->>'source_file', v_version.source_file),
        case when v_payload is null then v_version.source_sheet else v_payload->>'source_sheet' end,
        coalesce((v_payload->>'source_row')::integer, v_version.source_row),
        coalesce(v_payload->>'source_sha256', v_version.source_sha256),
        coalesce(v_payload->>'derivative_sha256', v_version.derivative_sha256),
        coalesce(v_item->>'source_fingerprint', v_version.source_fingerprint), p_batch_id,
        case when v_has_version then v_version.version_no + 1 else 1 end, 'superseded', array['superseded'],
        public.patrol_source_record_state('event', v_event.id),
        jsonb_build_object('superseded_by_external_ref', v_canonical_ref, 'canonical_location_event_id', v_canonical.id),
        auth.uid()
      );
    end if;

    delete from public.location_events event where event.id = v_event.id;

    insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
    values (p_provider_organization_id, auth.uid(), 'patrol_duplicate_event_superseded', 'location_events', v_event.id,
      jsonb_build_object('batch_id', p_batch_id, 'client_organization_id', p_client_organization_id,
        'external_ref', v_ref, 'canonical_external_ref', v_canonical_ref,
        'canonical_location_event_id', v_canonical.id, 'time_shift_seconds', v_shift));

    external_ref := v_ref; record_id := v_event.id; outcome := 'superseded'; detail := v_canonical_ref;
    return next;
  end loop;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."supersede_duplicate_patrol_events"(p_batch_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_items jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."supersede_duplicate_patrol_events"(p_batch_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_items jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."supersede_duplicate_patrol_events"(p_batch_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_items jsonb) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."sweep_missed_field_work"(p_now timestamp with time zone DEFAULT clock_timestamp(), p_grace_minutes integer DEFAULT 15)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r record;
  v_officer text;
  v_work text;
  v_window text;
  v_late_starts integer := 0;
  v_late_visits integer := 0;
  v_missed integer := 0;
  v_overruns integer := 0;
  v_stops integer;
BEGIN
  IF session_user NOT IN ('postgres', 'supabase_admin') AND coalesce(current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;

  -- DURING: not started after the grace period, window still open.
  FOR r IN
    SELECT s.*
    FROM public.shifts s
    WHERE s.status IN ('scheduled', 'published', 'accepted')
      AND s.actual_start IS NULL
      AND s.scheduled_start + make_interval(mins => p_grace_minutes) < p_now
      AND s.scheduled_end > p_now
      AND NOT EXISTS (SELECT 1 FROM public.notifications n WHERE n.organization_id = s.organization_id AND n.dedup_key = 'shift_late_start:' || s.id::text)
  LOOP
    SELECT coalesce(up.display_name, up.email, 'The officer') INTO v_officer FROM public.user_profiles up WHERE up.id = r.officer_user_id;
    SELECT coalesce(u.name, pr.name, replace(r.service_type, '_', ' ')) INTO v_work
    FROM public.shifts s LEFT JOIN public.roster_slots rs ON rs.id = s.roster_slot_id LEFT JOIN public.roster_work_units u ON u.id = rs.work_unit_id
    LEFT JOIN public.patrol_routes pr ON pr.id = s.patrol_route_id WHERE s.id = r.id;
    v_window := to_char(r.scheduled_start AT TIME ZONE 'Pacific/Auckland', 'HH24:MI') || '–' || to_char(r.scheduled_end AT TIME ZONE 'Pacific/Auckland', 'HH24:MI');
    PERFORM public.enqueue_notification(
      p_organization_id => r.organization_id, p_category => 'roster', p_severity => 'warning',
      p_title => 'Shift not started', p_body => v_officer || ' has not started ' || v_work || ' (' || v_window || '). ' || greatest(0, floor(extract(epoch FROM (p_now - r.scheduled_start)) / 60))::integer || ' min after the start time.',
      p_recipient_user_id => NULL, p_recipient_role => 'admin', p_link_page => 'roster', p_link_payload => jsonb_build_object('shift_id', r.id, 'roster_slot_id', r.roster_slot_id),
      p_dedup_key => 'shift_late_start:' || r.id::text);
    IF r.officer_user_id IS NOT NULL THEN
      PERFORM public.enqueue_notification(
        p_organization_id => r.organization_id, p_category => 'roster', p_severity => 'warning',
        p_title => 'Your shift has started', p_body => v_work || ' started at ' || to_char(r.scheduled_start AT TIME ZONE 'Pacific/Auckland', 'HH24:MI') || '. Start it on your schedule, or tell your supervisor if you cannot attend.',
        p_recipient_user_id => r.officer_user_id, p_recipient_role => NULL, p_link_page => 'schedule', p_link_payload => jsonb_build_object('shift_id', r.id, 'roster_slot_id', r.roster_slot_id),
        p_dedup_key => 'shift_late_start_officer:' || r.id::text);
    END IF;
    INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
    VALUES (r.organization_id, NULL, 'shift_late_start', 'shifts', r.id, jsonb_build_object('officer_user_id', r.officer_user_id, 'scheduled_start', r.scheduled_start, 'grace_minutes', p_grace_minutes, 'detected_at', p_now));
    v_late_starts := v_late_starts + 1;
  END LOOP;

  -- DURING: a contracted visit whose arrive-by time passed with nobody there.
  WITH late AS (
    UPDATE public.shift_stops st
    SET sla_status = 'breached', updated_at = p_now
    FROM public.shifts s
    WHERE s.id = st.shift_id
      AND st.is_adhoc = false
      AND st.status IN ('pending', 'en_route')
      AND st.sla_status <> 'breached'
      AND st.sla_arrive_by IS NOT NULL AND st.sla_arrive_by < p_now
      AND s.status IN ('scheduled', 'published', 'accepted', 'in_progress')
    RETURNING st.shift_id, s.organization_id
  ), per_shift AS (
    SELECT shift_id, organization_id, count(*) AS n FROM late GROUP BY shift_id, organization_id
  )
  SELECT coalesce(sum(n), 0)::integer INTO v_late_visits FROM per_shift;
  FOR r IN
    SELECT s.*, (SELECT count(*) FROM public.shift_stops st WHERE st.shift_id = s.id AND st.is_adhoc = false AND st.status IN ('pending', 'en_route') AND st.sla_status = 'breached') AS late_count
    FROM public.shifts s
    WHERE s.status IN ('scheduled', 'published', 'accepted', 'in_progress')
      AND s.scheduled_end > p_now
      AND EXISTS (SELECT 1 FROM public.shift_stops st WHERE st.shift_id = s.id AND st.is_adhoc = false AND st.status IN ('pending', 'en_route') AND st.sla_status = 'breached')
      AND NOT EXISTS (SELECT 1 FROM public.notifications n WHERE n.organization_id = s.organization_id AND n.dedup_key = 'shift_visits_late:' || s.id::text)
  LOOP
    SELECT coalesce(up.display_name, up.email, 'The officer') INTO v_officer FROM public.user_profiles up WHERE up.id = r.officer_user_id;
    SELECT coalesce(u.name, pr.name, replace(r.service_type, '_', ' ')) INTO v_work
    FROM public.shifts s LEFT JOIN public.roster_slots rs ON rs.id = s.roster_slot_id LEFT JOIN public.roster_work_units u ON u.id = rs.work_unit_id
    LEFT JOIN public.patrol_routes pr ON pr.id = s.patrol_route_id WHERE s.id = r.id;
    PERFORM public.enqueue_notification(
      p_organization_id => r.organization_id, p_category => 'sla_breach', p_severity => 'warning',
      p_title => 'Contracted visits running late', p_body => r.late_count || ' contracted ' || CASE WHEN r.late_count = 1 THEN 'visit has' ELSE 'visits have' END || ' passed their arrive-by time on ' || v_work || ' (' || v_officer || ').',
      p_recipient_user_id => NULL, p_recipient_role => 'admin', p_link_page => 'live-map', p_link_payload => jsonb_build_object('shift_id', r.id, 'officer_user_id', r.officer_user_id),
      p_dedup_key => 'shift_visits_late:' || r.id::text);
  END LOOP;

  -- AFTER: the window closed and nobody ever started. Recorded for every such shift; people are paged only when
  -- the window closed in the last 24 h (older ones are history the first sweep is catching up on).
  FOR r IN
    SELECT s.* FROM public.shifts s
    WHERE s.status IN ('scheduled', 'published', 'accepted')
      AND s.actual_start IS NULL
      AND s.scheduled_end <= p_now
    FOR UPDATE SKIP LOCKED
  LOOP
    -- Old catch-up rows are recorded, not announced (the officer notice trigger honours this flag).
    PERFORM set_config('fcm.silent_shift_notice', CASE WHEN r.scheduled_end > p_now - interval '24 hours' THEN 'off' ELSE 'on' END, true);
    UPDATE public.shifts SET status = 'missed', ended_reason = 'not_started', updated_at = p_now WHERE id = r.id;
    PERFORM set_config('fcm.silent_shift_notice', 'off', true);
    UPDATE public.shift_stops SET status = 'missed', sla_status = 'breached', updated_at = p_now
    WHERE shift_id = r.id AND status IN ('pending', 'en_route');
    GET DIAGNOSTICS v_stops = ROW_COUNT;
    SELECT coalesce(up.display_name, up.email, 'The officer') INTO v_officer FROM public.user_profiles up WHERE up.id = r.officer_user_id;
    SELECT coalesce(u.name, pr.name, replace(r.service_type, '_', ' ')) INTO v_work
    FROM public.shifts s LEFT JOIN public.roster_slots rs ON rs.id = s.roster_slot_id LEFT JOIN public.roster_work_units u ON u.id = rs.work_unit_id
    LEFT JOIN public.patrol_routes pr ON pr.id = s.patrol_route_id WHERE s.id = r.id;
    v_window := to_char(r.scheduled_start AT TIME ZONE 'Pacific/Auckland', 'Dy DD Mon HH24:MI') || '–' || to_char(r.scheduled_end AT TIME ZONE 'Pacific/Auckland', 'HH24:MI');
    INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
    VALUES (r.organization_id, NULL, 'shift_missed', 'shifts', r.id, jsonb_build_object('officer_user_id', r.officer_user_id, 'roster_slot_id', r.roster_slot_id, 'scheduled_start', r.scheduled_start, 'scheduled_end', r.scheduled_end, 'stops_missed', v_stops, 'previous_status', r.status, 'detected_at', p_now, 'notified', r.scheduled_end > p_now - interval '24 hours'));
    IF r.scheduled_end > p_now - interval '24 hours' THEN
      PERFORM public.enqueue_notification(
        p_organization_id => r.organization_id, p_category => 'roster', p_severity => 'critical',
        p_title => 'Shift missed — nobody attended', p_body => v_officer || ' never started ' || v_work || ' (' || v_window || ').' || CASE WHEN v_stops > 0 THEN ' ' || v_stops || ' contracted ' || CASE WHEN v_stops = 1 THEN 'visit was' ELSE 'visits were' END || ' not made.' ELSE '' END || ' Acknowledge it on the roster and tell the client what happens next.',
        p_recipient_user_id => NULL, p_recipient_role => 'admin', p_link_page => 'roster', p_link_payload => jsonb_build_object('shift_id', r.id, 'roster_slot_id', r.roster_slot_id),
        p_dedup_key => 'shift_missed:' || r.id::text);
    END IF;
    v_missed := v_missed + 1;
  END LOOP;

  -- Still running long after the end: said once, never auto-ended (the officer may be legitimately held).
  FOR r IN
    SELECT s.* FROM public.shifts s
    WHERE s.status = 'in_progress' AND s.scheduled_end + interval '60 minutes' < p_now
      AND NOT EXISTS (SELECT 1 FROM public.notifications n WHERE n.organization_id = s.organization_id AND n.dedup_key = 'shift_overrun:' || s.id::text)
  LOOP
    SELECT coalesce(up.display_name, up.email, 'The officer') INTO v_officer FROM public.user_profiles up WHERE up.id = r.officer_user_id;
    PERFORM public.enqueue_notification(
      p_organization_id => r.organization_id, p_category => 'roster', p_severity => 'warning',
      p_title => 'Shift still running', p_body => v_officer || ' is still on a shift that was due to end at ' || to_char(r.scheduled_end AT TIME ZONE 'Pacific/Auckland', 'HH24:MI') || '. Check they are safe and end or extend the shift.',
      p_recipient_user_id => NULL, p_recipient_role => 'admin', p_link_page => 'live-map', p_link_payload => jsonb_build_object('shift_id', r.id, 'officer_user_id', r.officer_user_id),
      p_dedup_key => 'shift_overrun:' || r.id::text);
    v_overruns := v_overruns + 1;
  END LOOP;

  RETURN jsonb_build_object('at', p_now, 'late_starts', v_late_starts, 'late_visits', v_late_visits, 'missed_shifts', v_missed, 'overruns', v_overruns);
END;
$function$;
COMMENT ON FUNCTION "public"."sweep_missed_field_work"(p_now timestamp with time zone, p_grace_minutes integer) IS 'Every five minutes (pg_cron): tells the branch when a shift has not started after the grace period, marks contracted visits whose arrive-by time has passed as breached, turns a shift that ended without starting into status missed (stops missed, audit row, critical notification), and flags shifts running long past their end. Idempotent through notification dedup keys.';
REVOKE ALL ON FUNCTION "public"."sweep_missed_field_work"(p_now timestamp with time zone, p_grace_minutes integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."sweep_missed_field_work"(p_now timestamp with time zone, p_grace_minutes integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."sweep_missed_field_work"(p_now timestamp with time zone, p_grace_minutes integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."sweep_notice_expiry_alerts"(p_window_days integer DEFAULT 30)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_notice record;
  v_user record;
  v_state text;
  v_count integer := 0;
BEGIN
  IF session_user NOT IN ('postgres', 'supabase_admin')
     AND coalesce(current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtext('sweep_notice_expiry_alerts'));
  FOR v_notice IN
    SELECT notice.id, notice.organization_id, notice.notice_type, notice.expires_at, notice.person_id,
      person.display_name AS person_name, org.name AS organization_name
    FROM public.notices notice
    JOIN public.organizations org ON org.id = notice.organization_id
    LEFT JOIN public.canonical_people person ON person.id = notice.person_id
    WHERE notice.status = 'issued'
      AND notice.notice_type IN ('trespass', 'warning')
      AND notice.expires_at IS NOT NULL
      AND notice.expires_at <= clock_timestamp() + make_interval(days => greatest(coalesce(p_window_days, 30), 1))
      AND notice.expires_at > clock_timestamp() - interval '30 days'
  LOOP
    v_state := CASE WHEN v_notice.expires_at <= clock_timestamp() THEN 'expired' ELSE 'expiring_soon' END;
    FOR v_user IN
      SELECT DISTINCT profile.id, profile.organization_id
      FROM public.user_profiles profile
      WHERE profile.deactivated_at IS NULL
        AND profile.role IN ('admin', 'master', 'admin_officer')
        AND (profile.organization_id = v_notice.organization_id
          OR EXISTS (
            SELECT 1 FROM public.service_agreements agreement
            WHERE agreement.client_organization_id = v_notice.organization_id
              AND agreement.provider_organization_id = profile.organization_id
              AND agreement.agreement_type = 'operational'
              AND (agreement.ends_on IS NULL OR agreement.ends_on >= current_date)))
    LOOP
      CONTINUE WHEN EXISTS (
        SELECT 1 FROM public.notifications existing
        WHERE existing.organization_id = v_user.organization_id
          AND existing.dedup_key = 'notice_expiry:' || v_state || ':' || v_notice.id::text || ':' || v_user.id::text);
      PERFORM public.enqueue_notification(
        p_organization_id => v_user.organization_id,
        p_category => 'notice_expiry',
        p_title => CASE WHEN v_state = 'expired'
          THEN initcap(v_notice.notice_type) || ' notice has expired'
          ELSE initcap(v_notice.notice_type) || ' notice expires ' || to_char(v_notice.expires_at AT TIME ZONE 'Pacific/Auckland', 'DD Mon YYYY') END,
        p_body => coalesce(v_notice.person_name, 'Unnamed person') || ', ' || v_notice.organization_name
          || CASE WHEN v_state = 'expired' THEN '. Decide whether a new notice is needed.' ELSE '. Review before it lapses.' END,
        p_severity => CASE WHEN v_state = 'expired' THEN 'warning' ELSE 'info' END,
        p_recipient_user_id => v_user.id,
        p_link_page => 'person-search',
        p_link_payload => jsonb_build_object('notice_id', v_notice.id, 'canonical_person_id', v_notice.person_id),
        p_dedup_key => 'notice_expiry:' || v_state || ':' || v_notice.id::text || ':' || v_user.id::text
      );
      v_count := v_count + 1;
    END LOOP;
  END LOOP;
  RETURN v_count;
END;
$function$;
COMMENT ON FUNCTION "public"."sweep_notice_expiry_alerts"(p_window_days integer) IS 'Daily; returns the number of new alerts. Tells admins of the notice organisation and of providers serving it under an operational agreement when an issued trespass/warning notice is inside the expiry window and again when it has expired. Idempotent per notice, state and recipient.';
REVOKE ALL ON FUNCTION "public"."sweep_notice_expiry_alerts"(p_window_days integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."sweep_notice_expiry_alerts"(p_window_days integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."sweep_notice_expiry_alerts"(p_window_days integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."sweep_place_hazard_reviews"(p_organization_id uuid DEFAULT NULL::uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_h record; v_user record; v_count integer := 0;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('sweep_place_hazard_reviews'));
  FOR v_h IN SELECT * FROM public.place_hazards
    WHERE status <> 'retired' AND review_due <= (now() AT TIME ZONE 'Pacific/Auckland')::date
      AND (p_organization_id IS NULL OR organization_id = p_organization_id)
  LOOP
    FOR v_user IN SELECT id FROM public.user_profiles WHERE organization_id = v_h.organization_id
      AND deactivated_at IS NULL AND (id = v_h.risk_owner_id OR role IN ('admin', 'admin_officer', 'master', 'grand_master'))
    LOOP
      PERFORM public.enqueue_notification(
        p_organization_id => v_h.organization_id, p_category => 'place_hazard_review',
        p_title => 'Place hazard review is due', p_body => 'Review the hazard, controls and owner; record findings and the next review date.',
        p_severity => 'warning', p_recipient_user_id => v_user.id, p_link_page => 'sites',
        p_link_payload => jsonb_build_object('site_id', v_h.client_site_id, 'location_id', v_h.location_id, 'hazard_id', v_h.id),
        p_dedup_key => 'hazard_due:' || v_h.id::text || ':' || v_h.review_due::text || ':' || v_user.id::text
      );
      v_count := v_count + 1;
    END LOOP;
  END LOOP;
  RETURN v_count;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."sweep_place_hazard_reviews"(p_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."sweep_place_hazard_reviews"(p_organization_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."sweep_place_hazard_reviews"(p_organization_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."sweep_slow_builder_job_notifications"(p_now timestamp with time zone DEFAULT clock_timestamp(), p_after_minutes integer DEFAULT 45)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r record;
  v_notified integer := 0;
  v_dedup_key text;
BEGIN
  IF session_user NOT IN ('postgres', 'supabase_admin')
     AND COALESCE(current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;
  IF p_after_minutes < 1 OR p_after_minutes > 1440 THEN
    RAISE EXCEPTION 'p_after_minutes must be between 1 and 1440';
  END IF;

  FOR r IN
    SELECT
      j.id,
      j.organization_id,
      j.title,
      j.status,
      j.current_step_name,
      COALESCE(j.autopilot_requested_by, j.created_by) AS recipient_user_id,
      GREATEST(
        j.updated_at,
        COALESCE(steps.last_updated_at, j.updated_at),
        COALESCE(models.last_updated_at, j.updated_at),
        COALESCE(workers.last_updated_at, j.updated_at)
      ) AS last_progress_at
    FROM public.builder_jobs j
    LEFT JOIN LATERAL (
      SELECT max(s.updated_at) AS last_updated_at
      FROM public.builder_job_steps s
      WHERE s.job_id = j.id
    ) steps ON true
    LEFT JOIN LATERAL (
      SELECT max(m.updated_at) AS last_updated_at
      FROM public.builder_model_runs m
      WHERE m.job_id = j.id
    ) models ON true
    LEFT JOIN LATERAL (
      SELECT max(w.updated_at) AS last_updated_at
      FROM public.builder_worker_runs w
      WHERE w.job_id = j.id
    ) workers ON true
    WHERE j.status IN (
      'intake', 'analysis_pending', 'specification_ready', 'design_pending',
      'implementation_pending', 'building', 'testing', 'security_review'
    )
      AND COALESCE(j.autopilot_state, '') NOT IN ('awaiting_human', 'done', 'blocked', 'cancelled')
      AND COALESCE(j.autopilot_requested_by, j.created_by) IS NOT NULL
  LOOP
    IF r.last_progress_at > p_now - make_interval(mins => p_after_minutes) THEN
      CONTINUE;
    END IF;

    v_dedup_key := 'builder_job_slow:' || r.id::text;
    IF EXISTS (
      SELECT 1
      FROM public.notifications n
      WHERE n.organization_id = r.organization_id
        AND n.dedup_key = v_dedup_key
    ) THEN
      CONTINUE;
    END IF;

    PERFORM public.enqueue_notification(
      p_organization_id => r.organization_id,
      p_category => 'builder_job',
      p_title => 'Bob Builder job taking longer than expected',
      p_body => left(r.title, 140) || ' has had no recorded progress for at least '
        || p_after_minutes::text || ' minutes'
        || COALESCE(' (stage: ' || NULLIF(r.current_step_name, '') || ')', '')
        || '. This is a warning only; the job has not been cancelled.',
      p_severity => 'warning',
      p_recipient_user_id => r.recipient_user_id,
      p_recipient_role => NULL,
      p_link_page => 'builder',
      p_link_payload => jsonb_build_object(
        'job_id', r.id,
        'status', r.status,
        'current_step_name', r.current_step_name,
        'last_progress_at', r.last_progress_at
      ),
      p_dedup_key => v_dedup_key
    );
    v_notified := v_notified + 1;
  END LOOP;

  RETURN v_notified;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."sweep_slow_builder_job_notifications"(p_now timestamp with time zone, p_after_minutes integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."sweep_slow_builder_job_notifications"(p_now timestamp with time zone, p_after_minutes integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."sweep_slow_builder_job_notifications"(p_now timestamp with time zone, p_after_minutes integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."sync_authorised_org_ids"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  affected uuid;
begin
  affected := coalesce(new.user_id, old.user_id);
  update public.user_profiles up
    set authorized_organization_ids = (
      select coalesce(array_agg(branch_org_id), array[]::uuid[])
      from public.staff_branch_authorisations
      where user_id = affected and status = 'active'
    )
  where up.id = affected;
  return null;
end;
$function$;
