CREATE OR REPLACE FUNCTION "public"."sync_file_person_folder"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_staff uuid;v_user uuid;v_existing uuid;v_parent text:='other_people';v_name text:=coalesce(nullif(trim(NEW.display_name),''),'Person');
BEGIN
  IF coalesce(NEW.metadata->>'staff_profile_id','') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_staff:=(NEW.metadata->>'staff_profile_id')::uuid;
    SELECT coalesce(staff.user_id,staff.id) INTO v_user FROM public.staff_profiles staff WHERE staff.id=v_staff;
  END IF;
  IF v_user IS NOT NULL THEN
    v_parent:='users_staff';
    SELECT id INTO v_existing FROM public.file_folders WHERE organization_id=NEW.organization_id AND entity_type='user_profile' AND entity_id=v_user AND active LIMIT 1;
    IF v_existing IS NOT NULL THEN
      UPDATE public.file_folders SET entity_type='person_record',entity_id=NEW.id,folder_key='entity:person_record:'||NEW.id::text,name=left(v_name,160),updated_at=clock_timestamp() WHERE id=v_existing;
      RETURN NEW;
    END IF;
  END IF;
  PERFORM public.upsert_file_entity_folder(NEW.organization_id,'people',v_parent,'person_record',NEW.id,v_name);
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."sync_file_person_folder"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."sync_file_person_folder"() TO "postgres";

CREATE OR REPLACE FUNCTION "public"."sync_file_user_folder"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_person uuid;v_name text:=coalesce(nullif(trim(NEW.display_name),''),nullif(trim(NEW.email),''),'User');
BEGIN
  SELECT person.id INTO v_person FROM public.person_records person
  JOIN public.staff_profiles staff ON person.metadata->>'staff_profile_id'=staff.id::text
  WHERE coalesce(staff.user_id,staff.id)=NEW.id AND person.organization_id=NEW.organization_id LIMIT 1;
  IF v_person IS NULL THEN
    PERFORM public.upsert_file_entity_folder(NEW.organization_id,'people','users_staff','user_profile',NEW.id,v_name);
  ELSE
    PERFORM public.upsert_file_entity_folder(NEW.organization_id,'people','users_staff','person_record',v_person,v_name);
  END IF;
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."sync_file_user_folder"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."sync_file_user_folder"() TO "postgres";

CREATE OR REPLACE FUNCTION "public"."sync_group_charge_catalog"(p_source uuid, p_target uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_rows integer;
BEGIN
  IF p_source IS NULL OR p_target IS NULL OR p_source = p_target THEN RETURN 0; END IF;
  INSERT INTO public.reference_codes(
    organization_id, code_type, code, name, description, is_active, sort_order, external_refs
  )
  SELECT p_target, source.code_type, source.code, source.name, source.description, source.is_active, source.sort_order,
         source.external_refs || jsonb_build_object('catalog_source_organization_id',
           coalesce(source.external_refs->>'catalog_source_organization_id', p_source::text))
  FROM public.reference_codes source
  WHERE source.organization_id = p_source
    AND source.code_type IN ('charge_source', 'charge_subject', 'charge_issue', 'charge_code')
    AND source.external_refs->>'scheme' = 'rm_group_charge_code'
    AND EXISTS (SELECT 1 FROM public.organizations target WHERE target.id = p_target)
  ON CONFLICT (organization_id, code_type, code) DO UPDATE SET
    name = EXCLUDED.name,
    description = EXCLUDED.description,
    is_active = EXCLUDED.is_active,
    sort_order = EXCLUDED.sort_order,
    external_refs = EXCLUDED.external_refs,
    updated_at = now()
  WHERE reference_codes.external_refs->>'scheme' = 'rm_group_charge_code';
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  RETURN v_rows;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."sync_group_charge_catalog"(p_source uuid, p_target uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."sync_group_charge_catalog"(p_source uuid, p_target uuid) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."sync_invitation_status"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- Only sync if the invite is linked to an agreement
  IF NEW.service_agreement_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Never overwrite 'accepted' (acceptance is permanent)
  IF (SELECT invitation_status FROM public.service_agreements
      WHERE id = NEW.service_agreement_id) = 'accepted' THEN
    RETURN NEW;
  END IF;

  -- On INSERT of a pending invite: set agreement to 'invited'
  IF TG_OP = 'INSERT' AND NEW.status = 'pending' THEN
    UPDATE public.service_agreements
    SET invitation_status = 'invited'
    WHERE id = NEW.service_agreement_id;
    RETURN NEW;
  END IF;

  -- On status change FROM pending: derive the new agreement status
  IF TG_OP = 'UPDATE' AND OLD.status = 'pending' AND NEW.status != 'pending' THEN
    UPDATE public.service_agreements
    SET invitation_status = CASE NEW.status
      WHEN 'accepted' THEN 'accepted'
      WHEN 'declined' THEN 'declined'
      WHEN 'revoked' THEN 'not_invited'
      WHEN 'expired' THEN 'expired'
    END
    WHERE id = NEW.service_agreement_id;
    RETURN NEW;
  END IF;

  -- All other changes: no-op (historical invites don't affect the agreement)
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."sync_invitation_status"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."sync_invitation_status"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."sync_invitation_status"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."sync_invitation_status"() TO "anon";
GRANT EXECUTE ON FUNCTION "public"."sync_invitation_status"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."sync_invitation_status"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."sync_my_profile_email"()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_email text := nullif(lower(trim(coalesce(auth.email(), ''))), '');
  v_row public.user_profiles%rowtype;
BEGIN
  IF v_actor IS NULL OR v_email IS NULL THEN RETURN NULL; END IF;
  SELECT * INTO v_row FROM public.user_profiles WHERE id = v_actor FOR UPDATE;
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF lower(coalesce(v_row.email, '')) = v_email THEN RETURN v_row.email; END IF;

  UPDATE public.user_profiles SET email = v_email WHERE id = v_actor;
  PERFORM public.log_user_management_action(
    v_row.organization_id, v_actor, 'user_email_change_confirmed', v_actor,
    jsonb_build_object('email', v_row.email), jsonb_build_object('email', v_email),
    jsonb_build_object('source', 'auth_session'));
  RETURN v_email;
END;
$function$;
COMMENT ON FUNCTION "public"."sync_my_profile_email"() IS 'Brings the caller''s own user_profiles.email up to the address they are actually signed in with, after a confirmed email change. Acts only on auth.uid() and records the catch-up in the identity audit trail.';
REVOKE ALL ON FUNCTION "public"."sync_my_profile_email"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."sync_my_profile_email"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."sync_my_profile_email"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."sync_my_profile_email"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."sync_nzta_owner_history_after_check"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF NEW.source_authority = 'NZTA Motor Vehicle Register'
     AND NEW.relationship = 'registered_person_at_check' THEN
    PERFORM public.sync_nzta_registered_owner_history(
      NEW.organization_id, NEW.canonical_vehicle_id
    );
  END IF;
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."sync_nzta_owner_history_after_check"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."sync_nzta_owner_history_after_check"() TO "postgres";

CREATE OR REPLACE FUNCTION "public"."sync_nzta_registered_owner_history"(p_organization_id uuid, p_canonical_vehicle_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_episode record;
  v_link_id uuid;
  v_episode_count integer := 0;
  v_current_person uuid;
  v_manual_link_count integer;
  v_episode_keys text[];
BEGIN
  IF v_actor IS NULL
     OR NOT public.is_admin_for_org(p_organization_id)
     OR NOT public.can_access_vehicle_owner_identity(p_organization_id, true) THEN
    RAISE EXCEPTION 'Vehicle owner identity administrator access required';
  END IF;

  PERFORM 1
  FROM public.canonical_vehicles
  WHERE id = p_canonical_vehicle_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Canonical vehicle not found'; END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.vehicle_identity_checks check_row
    JOIN public.person_identity_documents document
      ON document.id = check_row.identity_document_id
     AND document.organization_id = check_row.organization_id
    WHERE check_row.organization_id = p_organization_id
      AND check_row.canonical_vehicle_id = p_canonical_vehicle_id
      AND check_row.source_authority = 'NZTA Motor Vehicle Register'
      AND check_row.relationship = 'registered_person_at_check'
      AND document.document_kind = 'nzta_mvr_record'
      AND (document.review_state = 'approved'
        OR check_row.vehicle_snapshot->>'owner_only_review' = 'true')
  ) THEN
    RAISE EXCEPTION 'No reviewed NZTA registered-person checks exist for this vehicle';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.vehicle_identity_checks check_row
    JOIN public.person_identity_documents document
      ON document.id = check_row.identity_document_id
     AND document.organization_id = check_row.organization_id
    WHERE check_row.organization_id = p_organization_id
      AND check_row.canonical_vehicle_id = p_canonical_vehicle_id
      AND check_row.source_authority = 'NZTA Motor Vehicle Register'
      AND check_row.relationship = 'registered_person_at_check'
      AND document.document_kind = 'nzta_mvr_record'
      AND (document.review_state = 'approved'
        OR check_row.vehicle_snapshot->>'owner_only_review' = 'true')
    GROUP BY check_row.checked_at
    HAVING count(DISTINCT check_row.canonical_person_id) > 1
  ) THEN
    RAISE EXCEPTION 'Conflicting owners share an NZTA check timestamp; owner history was not changed';
  END IF;

  SELECT count(*) INTO v_manual_link_count
  FROM public.entity_links link
  WHERE link.organization_id = p_organization_id
    AND link.from_type = 'person'
    AND link.to_type = 'vehicle'
    AND link.to_id = p_canonical_vehicle_id
    AND link.relationship = 'registered_owner'
    AND link.active
    AND link.evidence->>'source' IS DISTINCT FROM 'nzta_mvr';
  IF v_manual_link_count > 0 THEN
    RAISE EXCEPTION 'A manually recorded registered owner needs review before NZTA history can be synchronized';
  END IF;

  SELECT check_row.canonical_person_id
    INTO v_current_person
  FROM public.vehicle_identity_checks check_row
  JOIN public.person_identity_documents document
    ON document.id = check_row.identity_document_id
   AND document.organization_id = check_row.organization_id
  WHERE check_row.organization_id = p_organization_id
    AND check_row.canonical_vehicle_id = p_canonical_vehicle_id
    AND check_row.source_authority = 'NZTA Motor Vehicle Register'
    AND check_row.relationship = 'registered_person_at_check'
    AND document.document_kind = 'nzta_mvr_record'
    AND (document.review_state = 'approved'
      OR check_row.vehicle_snapshot->>'owner_only_review' = 'true')
  ORDER BY check_row.checked_at DESC, check_row.id DESC
  LIMIT 1;

  WITH source_checks AS (
    SELECT check_row.id, check_row.checked_at, check_row.canonical_person_id
    FROM public.vehicle_identity_checks check_row
    JOIN public.person_identity_documents document
      ON document.id = check_row.identity_document_id
     AND document.organization_id = check_row.organization_id
    WHERE check_row.organization_id = p_organization_id
      AND check_row.canonical_vehicle_id = p_canonical_vehicle_id
      AND check_row.source_authority = 'NZTA Motor Vehicle Register'
      AND check_row.relationship = 'registered_person_at_check'
      AND document.document_kind = 'nzta_mvr_record'
      AND (document.review_state = 'approved'
        OR check_row.vehicle_snapshot->>'owner_only_review' = 'true')
  ),
  ordered_checks AS (
    SELECT source_checks.*,
           lag(canonical_person_id) OVER (ORDER BY checked_at, id) AS previous_person_id
    FROM source_checks
  ),
  numbered_checks AS (
    SELECT ordered_checks.*,
           sum(CASE WHEN previous_person_id IS DISTINCT FROM canonical_person_id THEN 1 ELSE 0 END)
             OVER (ORDER BY checked_at, id) AS episode_number
    FROM ordered_checks
  ),
  episodes AS (
    SELECT episode_number,
           (array_agg(id ORDER BY checked_at, id))[1] AS first_check_id
    FROM numbered_checks
    GROUP BY episode_number
  )
  SELECT coalesce(array_agg(first_check_id::text), ARRAY[]::text[])
    INTO v_episode_keys
  FROM episodes;

  UPDATE public.entity_links link
  SET active = false,
      ends_at = coalesce(link.ends_at, clock_timestamp()),
      evidence = link.evidence || jsonb_build_object(
        'superseded_by_reconciliation', true,
        'reconciled_at', clock_timestamp()
      ),
      updated_at = clock_timestamp()
  WHERE link.organization_id = p_organization_id
    AND link.from_type = 'person'
    AND link.to_type = 'vehicle'
    AND link.to_id = p_canonical_vehicle_id
    AND link.relationship = 'registered_owner'
    AND link.evidence ? 'nzta_owner_history_first_check_id'
    AND NOT (link.evidence->>'nzta_owner_history_first_check_id' = ANY(v_episode_keys));

  UPDATE public.entity_links link
  SET active = false,
      ends_at = coalesce(link.ends_at, clock_timestamp()),
      evidence = link.evidence || CASE WHEN EXISTS (
          SELECT 1 FROM public.vehicle_identity_checks seen
          WHERE seen.organization_id = p_organization_id
            AND seen.canonical_vehicle_id = p_canonical_vehicle_id
            AND seen.canonical_person_id = link.from_id
            AND seen.relationship = 'registered_person_at_check'
        ) THEN jsonb_build_object(
          'superseded_by_reconciliation', true,
          'replaced_by_owner_history', true,
          'reconciled_at', clock_timestamp()
        ) ELSE jsonb_build_object('reconciled_at', clock_timestamp()) END,
      updated_at = clock_timestamp()
  WHERE link.organization_id = p_organization_id
    AND link.from_type = 'person'
    AND link.to_type = 'vehicle'
    AND link.to_id = p_canonical_vehicle_id
    AND link.relationship = 'registered_owner'
    AND link.active
    AND link.evidence->>'source' = 'nzta_mvr'
    AND NOT (link.evidence ? 'nzta_owner_history_first_check_id');

  UPDATE public.entity_links link
  SET active = false,
      ends_at = coalesce(link.ends_at, clock_timestamp()),
      updated_at = clock_timestamp()
  WHERE link.organization_id = p_organization_id
    AND link.from_type = 'person'
    AND link.to_type = 'vehicle'
    AND link.to_id = p_canonical_vehicle_id
    AND link.relationship = 'registered_owner'
    AND link.active
    AND link.evidence ? 'nzta_owner_history_first_check_id';

  FOR v_episode IN
    WITH source_checks AS (
      SELECT check_row.id, check_row.checked_at, check_row.canonical_person_id,
             check_row.person_record_id
      FROM public.vehicle_identity_checks check_row
      JOIN public.person_identity_documents document
        ON document.id = check_row.identity_document_id
       AND document.organization_id = check_row.organization_id
      WHERE check_row.organization_id = p_organization_id
        AND check_row.canonical_vehicle_id = p_canonical_vehicle_id
        AND check_row.source_authority = 'NZTA Motor Vehicle Register'
        AND check_row.relationship = 'registered_person_at_check'
        AND document.document_kind = 'nzta_mvr_record'
        AND (document.review_state = 'approved'
          OR check_row.vehicle_snapshot->>'owner_only_review' = 'true')
    ),
    ordered_checks AS (
      SELECT source_checks.*,
             lag(canonical_person_id) OVER (ORDER BY checked_at, id) AS previous_person_id
      FROM source_checks
    ),
    numbered_checks AS (
      SELECT ordered_checks.*,
             sum(CASE WHEN previous_person_id IS DISTINCT FROM canonical_person_id THEN 1 ELSE 0 END)
               OVER (ORDER BY checked_at, id) AS episode_number
      FROM ordered_checks
    ),
    episodes AS (
      SELECT episode_number, canonical_person_id,
             min(checked_at) AS observed_from,
             (array_agg(id ORDER BY checked_at, id))[1] AS first_check_id,
             (array_agg(person_record_id ORDER BY checked_at DESC, id DESC))[1] AS person_record_id,
             array_agg(id ORDER BY checked_at, id) AS check_ids
      FROM numbered_checks
      GROUP BY episode_number, canonical_person_id
    )
    SELECT episodes.*,
           lead(observed_from) OVER (ORDER BY episode_number) AS superseded_at
    FROM episodes
    ORDER BY episode_number
  LOOP
    SELECT link.id INTO v_link_id
    FROM public.entity_links link
    WHERE link.organization_id = p_organization_id
      AND link.relationship = 'registered_owner'
      AND link.evidence->>'nzta_owner_history_first_check_id' = v_episode.first_check_id::text
    FOR UPDATE;

    IF v_link_id IS NULL THEN
      INSERT INTO public.entity_links (
        organization_id, from_type, from_id, to_type, to_id, relationship,
        evidence, active, starts_at, ends_at, created_by
      ) VALUES (
        p_organization_id, 'person', v_episode.canonical_person_id,
        'vehicle', p_canonical_vehicle_id, 'registered_owner',
        jsonb_build_object(
          'source', 'nzta_mvr',
          'basis', 'Observed at NZTA source check; dates are observations, not legal transfer dates.',
          'person_record_id', v_episode.person_record_id,
          'nzta_restricted', true,
          'observation_ids', '[]'::jsonb,
          'nzta_owner_history_first_check_id', v_episode.first_check_id,
          'nzta_owner_history_check_ids', to_jsonb(v_episode.check_ids),
          'source_checked_at', v_episode.observed_from,
          'superseded_at_nzta_check', v_episode.superseded_at
        ),
        v_episode.superseded_at IS NULL,
        v_episode.observed_from,
        v_episode.superseded_at,
        v_actor
      )
      RETURNING id INTO v_link_id;
    ELSE
      UPDATE public.entity_links link
      SET from_id = v_episode.canonical_person_id,
          evidence = jsonb_build_object(
            'source', 'nzta_mvr',
            'basis', 'Observed at NZTA source check; dates are observations, not legal transfer dates.',
            'person_record_id', v_episode.person_record_id,
            'nzta_restricted', true,
            'observation_ids', '[]'::jsonb,
            'nzta_owner_history_first_check_id', v_episode.first_check_id,
            'nzta_owner_history_check_ids', to_jsonb(v_episode.check_ids),
            'source_checked_at', v_episode.observed_from,
            'superseded_at_nzta_check', v_episode.superseded_at
          ),
          active = v_episode.superseded_at IS NULL,
          starts_at = v_episode.observed_from,
          ends_at = v_episode.superseded_at,
          updated_at = clock_timestamp()
      WHERE link.id = v_link_id;
    END IF;
    v_episode_count := v_episode_count + 1;
    v_link_id := NULL;
  END LOOP;

  INSERT INTO public.audit_log (
    organization_id, actor_user_id, action, target_table, target_id, metadata
  ) VALUES (
    p_organization_id, v_actor, 'nzta_registered_owner_history_synchronized',
    'entity_links', p_canonical_vehicle_id,
    jsonb_build_object(
      'canonical_vehicle_id', p_canonical_vehicle_id,
      'current_canonical_person_id', v_current_person,
      'owner_observation_episodes', v_episode_count,
      'date_basis', 'NZTA source check observations; not legal transfer dates'
    )
  );

  RETURN jsonb_build_object(
    'canonical_vehicle_id', p_canonical_vehicle_id,
    'current_canonical_person_id', v_current_person,
    'owner_observation_episodes', v_episode_count
  );
END;
$function$;
COMMENT ON FUNCTION "public"."sync_nzta_registered_owner_history"(p_organization_id uuid, p_canonical_vehicle_id uuid) IS 'Rebuilds the R&M organisation-scoped registered-owner observations from reviewed NZTA source-time checks. The latest check is current; prior distinct-owner periods are inactive. Dates are check observations, never legal transfer dates.';
REVOKE ALL ON FUNCTION "public"."sync_nzta_registered_owner_history"(p_organization_id uuid, p_canonical_vehicle_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."sync_nzta_registered_owner_history"(p_organization_id uuid, p_canonical_vehicle_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."sync_nzta_registered_owner_history"(p_organization_id uuid, p_canonical_vehicle_id uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."sync_observation_to_location_event"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_event_id uuid;
BEGIN
  IF NEW.site_id IS NOT NULL AND NEW.zone_id IS NOT NULL THEN
    RAISE EXCEPTION 'Observation must reference a Site or Zone, not both';
  END IF;

  IF NEW.site_id IS NULL AND NEW.zone_id IS NULL THEN
    INSERT INTO public.event_context_snapshots (
      source_table, source_event_id, location_id, module_key, provider_organization_id,
      client_organization_id, authority_snapshot, source_refs, captured_at
    ) VALUES (
      'observations', NEW.id, NEW.location_id, NEW.module_key, NEW.organization_id,
      NEW.client_org_id, jsonb_build_object(
        'officer_id', NEW.officer_id,
        'reported_by_name', NEW.reported_by_name
      ),
      jsonb_build_object(
        'source', 'observation_trigger',
        'unresolved_reason', 'no_site_or_zone',
        'subject_kind', NEW.subject_kind,
        'source_reference', NEW.source_reference
      ),
      NEW.observed_at
    ) ON CONFLICT (source_table, source_event_id) DO NOTHING;
    RETURN NEW;
  END IF;

  INSERT INTO public.location_events (
    organization_id, client_site_id, zone_id, event_type, module_key, occurred_at,
    status, source, external_ref, payload, observed_entity_type, observed_entity_id, created_by
  ) VALUES (
    NEW.organization_id, NEW.site_id, NEW.zone_id, 'observation', NEW.module_key, NEW.observed_at,
    coalesce(NEW.compliance_status, 'recorded'), 'observation_trigger', NEW.id::text,
    jsonb_strip_nulls(jsonb_build_object(
      'observation_id', NEW.id,
      'plate_number', NEW.plate_number,
      'canonical_person_id', NEW.canonical_person_id,
      'compliance_status', NEW.compliance_status,
      'source_reference', NEW.source_reference
    )),
    NEW.subject_kind,
    NEW.id,
    NEW.officer_id
  ) RETURNING id INTO v_event_id;

  INSERT INTO public.event_context_snapshots (
    source_table, source_event_id, location_id, client_site_id, zone_id, module_key,
    provider_organization_id, client_organization_id, authority_snapshot, source_refs, captured_at
  ) VALUES (
    'observations', NEW.id, NEW.location_id, NEW.site_id, NEW.zone_id, NEW.module_key,
    NEW.organization_id, NEW.client_org_id, jsonb_build_object(
      'officer_id', NEW.officer_id,
      'reported_by_name', NEW.reported_by_name
    ),
    jsonb_build_object(
      'location_event_id', v_event_id,
      'source', 'observation_trigger',
      'subject_kind', NEW.subject_kind,
      'source_reference', NEW.source_reference
    ),
    NEW.observed_at
  ) ON CONFLICT (source_table, source_event_id) DO NOTHING;

  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."sync_observation_to_location_event"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."sync_observation_to_location_event"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."sync_observation_to_location_event"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."sync_observation_to_location_event"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."sync_service_agreement_location_from_site"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.service_agreement_id is not null then
    insert into public.service_agreement_locations (
      service_agreement_id,
      site_id,
      status,
      created_by
    )
    values (
      new.service_agreement_id,
      new.id,
      'active',
      null
    )
    on conflict (service_agreement_id, site_id) do update
      set status = excluded.status,
          updated_at = now();
  end if;

  return new;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."sync_service_agreement_location_from_site"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."sync_service_agreement_location_from_site"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."sync_service_agreement_location_from_site"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."sync_service_agreement_location_from_site"() TO "anon";
GRANT EXECUTE ON FUNCTION "public"."sync_service_agreement_location_from_site"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."sync_service_agreement_location_from_site"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."test_bob_signing_config"()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with active as (
    select provider, key_name, fingerprint_sha256, enabled
    from public.bob_signing_identities
    where provider = 'gitea' and enabled = true
    order by created_at desc
    limit 1
  ),
  v2_present as (
    select exists(
      select 1
      from public.bob_signing_identities
      where provider = 'gitea'
        and (
          key_name ilike '%v2%'
          or notes ilike '%v2%'
          or fingerprint_sha256 <> 'SHA256:ckUO3+2YpwZcGZFGvqu/R4cZpO1iXq8IaAL9pKQl3Y4'
        )
    ) as has_v2_or_nonallowlisted
  )
  select jsonb_build_object(
    'active_is_expected', exists(
      select 1 from active
      where key_name = 'bob-gitea'
        and fingerprint_sha256 = 'SHA256:ckUO3+2YpwZcGZFGvqu/R4cZpO1iXq8IaAL9pKQl3Y4'
        and enabled = true
    ),
    'v2_not_used', not (select has_v2_or_nonallowlisted from v2_present),
    'active_identity', (select to_jsonb(active) from active)
  );
$function$;
REVOKE ALL ON FUNCTION "public"."test_bob_signing_config"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."test_bob_signing_config"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."test_bob_signing_config"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."tg_align_module_subscription"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_org_type text;
begin
  -- Only act when the enabled flag is set (INSERT) or actually changed (UPDATE).
  if tg_op = 'UPDATE' and (new.enabled is not distinct from old.enabled) then
    return new;
  end if;

  select organization_type into v_org_type
  from public.organizations
  where id = new.organization_id;

  -- Layer 1 bills providers only. Non-provider orgs no-op.
  if v_org_type is null or v_org_type not in ('service_provider', 'branch') then
    return new;
  end if;

  if new.enabled then
    -- Create or reactivate the line. Preserve any existing per-provider overrides
    -- (only status/updated_at are forced; price columns are left untouched).
    insert into public.org_module_subscriptions (organization_id, module_key, status)
    values (new.organization_id, new.module_key, 'active')
    on conflict (organization_id, module_key) do update
      set status = case
                     when public.org_module_subscriptions.status = 'cancelled'
                       then public.org_module_subscriptions.status  -- do not silently revive a cancelled contract
                     else 'active'
                   end,
          updated_at = now();
  else
    -- Disable => suspend the line (never delete; keeps overrides + history).
    update public.org_module_subscriptions
       set status = 'suspended', updated_at = now()
     where organization_id = new.organization_id
       and module_key = new.module_key
       and status <> 'cancelled';
  end if;

  return new;
end $function$;
COMMENT ON FUNCTION "public"."tg_align_module_subscription"() IS 'B2 (#2): aligns org_module_subscriptions with organization_modules enablement for billable provider tiers (service_provider|branch). Preserves overrides; suspends (never deletes) on disable; does not revive cancelled contracts.';
REVOKE ALL ON FUNCTION "public"."tg_align_module_subscription"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."tg_align_module_subscription"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."tg_align_module_subscription"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."tg_align_module_subscription"() TO "anon";
GRANT EXECUTE ON FUNCTION "public"."tg_align_module_subscription"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."tg_align_module_subscription"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."tg_assign_staff_employee_number"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_existing_suffix bigint;
BEGIN
  IF nullif(btrim(NEW.employee_number), '') IS NULL THEN
    NEW.employee_number := public.next_staff_employee_number(NEW.organization_id);
    INSERT INTO public.audit_log (
      organization_id, actor_user_id, action, target_table, target_id, metadata
    ) VALUES (
      NEW.organization_id,
      auth.uid(),
      'staff_employee_number_assigned',
      'staff_profiles',
      NEW.id,
      jsonb_build_object('employee_number', NEW.employee_number, 'assignment_source', 'organisation_counter')
    );
  ELSE
    v_existing_suffix := (regexp_match(btrim(NEW.employee_number), '^EMP-([0-9]+)$'))[1]::bigint;
    IF v_existing_suffix IS NOT NULL THEN
      INSERT INTO public.staff_employee_number_counters (organization_id, last_number)
      VALUES (NEW.organization_id, v_existing_suffix)
      ON CONFLICT (organization_id) DO UPDATE
      SET last_number = GREATEST(
        public.staff_employee_number_counters.last_number,
        EXCLUDED.last_number
      );
    END IF;
  END IF;

  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."tg_assign_staff_employee_number"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."tg_assign_staff_employee_number"() TO "postgres";

CREATE OR REPLACE FUNCTION "public"."tg_cctv_imports_place"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_house public.locations%rowtype; v_slug text;
BEGIN
  SELECT * INTO v_house FROM public.locations WHERE id = NEW.location_id;
  IF v_house.id IS NULL THEN RAISE EXCEPTION 'CCTV import needs an existing location house'; END IF;
  NEW.canonical_place_id := v_house.canonical_place_id;
  IF NEW.site_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.client_sites s WHERE s.id = NEW.site_id AND s.location_id = NEW.location_id) THEN
    RAISE EXCEPTION 'CCTV import site is not a facet of the chosen house';
  END IF;
  IF NEW.zone_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.location_zones z WHERE z.id = NEW.zone_id AND z.location_id = NEW.location_id) THEN
    RAISE EXCEPTION 'CCTV import zone is not a facet of the chosen house';
  END IF;
  NEW.camera_label := trim(NEW.camera_label);
  v_slug := trim(both '-' from regexp_replace(lower(NEW.camera_label), '[^a-z0-9]+', '-', 'g'));
  NEW.camera_key := left(NEW.location_id::text, 8) || ':' || coalesce(nullif(v_slug, ''), 'camera');
  NEW.updated_at := clock_timestamp();
  RETURN NEW;
END $function$;
REVOKE ALL ON FUNCTION "public"."tg_cctv_imports_place"() FROM PUBLIC, "anon", "authenticated", "service_role";
