CREATE OR REPLACE FUNCTION "public"."tg_client_sites_place_house"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_owner uuid := coalesce(NEW.client_organization_id, NEW.organization_id); v_house_org uuid; v_house uuid;
BEGIN
  NEW.address := nullif(trim(NEW.address), '');
  IF NEW.address IS NOT NULL THEN
    NEW.address_match_key := public.address_match_key(NEW.address);
  ELSIF NEW.address_match_key IS NOT NULL THEN
    NEW.address_match_key := public.address_match_key(NEW.address_match_key);
  END IF;
  -- center_point is the one geometry fact; gps_lat/gps_lng are a derived view of it kept for old readers.
  IF NEW.gps_lat IS NOT NULL AND NEW.gps_lng IS NOT NULL AND (
       NEW.center_point IS NULL
       OR (TG_OP = 'UPDATE' AND (NEW.gps_lat IS DISTINCT FROM OLD.gps_lat OR NEW.gps_lng IS DISTINCT FROM OLD.gps_lng)
           AND NEW.center_point IS NOT DISTINCT FROM OLD.center_point)) THEN
    NEW.center_point := ST_SetSRID(ST_MakePoint(NEW.gps_lng, NEW.gps_lat), 4326);
  END IF;
  IF NEW.center_point IS NOT NULL THEN
    NEW.gps_lat := ST_Y(NEW.center_point::geometry);
    NEW.gps_lng := ST_X(NEW.center_point::geometry);
  END IF;
  IF NEW.location_id IS NULL AND v_owner IS NOT NULL THEN
    IF NEW.address_match_key IS NOT NULL THEN
      SELECT id INTO NEW.location_id FROM public.locations
       WHERE organization_id = v_owner AND address_match_key = NEW.address_match_key ORDER BY created_at LIMIT 1;
    ELSIF NEW.name IS NOT NULL THEN
      SELECT id INTO NEW.location_id FROM public.locations
       WHERE organization_id = v_owner AND lower(name) = lower(NEW.name) ORDER BY created_at LIMIT 1;
    END IF;
    IF NEW.location_id IS NULL THEN
      v_house := gen_random_uuid();
      INSERT INTO public.locations (id, organization_id, name, address, address_match_key, created_by, canonical_place_id)
      VALUES (v_house, v_owner, coalesce(nullif(trim(NEW.name), ''), NEW.address, 'Unnamed place'), NEW.address, NEW.address_match_key,
              (SELECT up.id FROM public.user_profiles up WHERE up.id = auth.uid()),
              public.canonical_place_for_house(v_house, v_owner, coalesce(nullif(trim(NEW.name), ''), NEW.address, 'Unnamed place'), NEW.address, NEW.address_match_key, 'site'));
      NEW.location_id := v_house;
    END IF;
  END IF;
  IF NEW.location_id IS NOT NULL THEN
    SELECT organization_id INTO v_house_org FROM public.locations WHERE id = NEW.location_id;
    IF v_house_org IS NULL THEN
      RAISE EXCEPTION 'Location house % does not exist', NEW.location_id;
    END IF;
    IF v_owner IS NOT NULL AND v_house_org <> v_owner THEN
      RAISE EXCEPTION 'Site % cannot hang off a house owned by another organisation', coalesce(NEW.name, NEW.id::text);
    END IF;
    UPDATE public.canonical_places cp SET
      center_point = coalesce(cp.center_point, NEW.center_point),
      boundary = coalesce(cp.boundary, CASE WHEN NEW.boundary IS NULL THEN NULL ELSE ST_Multi(NEW.boundary) END),
      updated_at = now()
    FROM public.locations l
    WHERE l.id = NEW.location_id AND cp.id = l.canonical_place_id
      AND ((cp.center_point IS NULL AND NEW.center_point IS NOT NULL) OR (cp.boundary IS NULL AND NEW.boundary IS NOT NULL));
  END IF;
  RETURN NEW;
END $function$;
REVOKE ALL ON FUNCTION "public"."tg_client_sites_place_house"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."tg_client_sites_place_house"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."tg_client_sites_place_house"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."tg_client_sites_place_house"() TO "anon";
GRANT EXECUTE ON FUNCTION "public"."tg_client_sites_place_house"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."tg_client_sites_place_house"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."tg_dispatch_job_close_sla_clock"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.status = 'cancelled' and coalesce(old.status, '') <> 'cancelled' then
    update public.sla_clocks c set status = 'cancelled', updated_at = now() where c.dispatch_job_id = new.id and c.status = 'running';
  elsif new.on_scene_at is not null and (old.on_scene_at is null or old.on_scene_at <> new.on_scene_at) then
    update public.sla_clocks c
    set arrived_at = new.on_scene_at,
        elapsed_minutes = ceil(extract(epoch from (new.on_scene_at - c.started_at)) / 60.0)::integer,
        status = case when c.target_minutes is null or ceil(extract(epoch from (new.on_scene_at - c.started_at)) / 60.0) <= c.target_minutes then 'met' else 'breached' end,
        updated_at = now()
    where c.dispatch_job_id = new.id and c.status in ('running', 'met', 'breached');
  end if;
  return new;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."tg_dispatch_job_close_sla_clock"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."tg_dispatch_job_close_sla_clock"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."tg_dispatch_job_close_sla_clock"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."tg_dispatch_job_close_sla_clock"() TO "anon";
GRANT EXECUTE ON FUNCTION "public"."tg_dispatch_job_close_sla_clock"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."tg_dispatch_job_close_sla_clock"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."tg_dispatch_job_stamp_milestones"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    IF NEW.status = 'dispatched' AND NEW.dispatched_at IS NULL THEN
      NEW.dispatched_at := now();
    END IF;
    IF NEW.status = 'acknowledged' AND NEW.acknowledged_at IS NULL THEN
      NEW.acknowledged_at := now();
    END IF;
    IF NEW.status = 'en_route' AND NEW.en_route_at IS NULL THEN
      NEW.en_route_at := now();
    END IF;
    IF NEW.status = 'on_scene' AND NEW.on_scene_at IS NULL THEN
      NEW.on_scene_at := now();
    END IF;
    IF NEW.status = 'completed' AND NEW.completed_at IS NULL THEN
      NEW.completed_at := now();
    END IF;
    IF NEW.status IN ('acknowledged', 'en_route', 'on_scene', 'completed')
      AND NEW.dispatched_at IS NULL
      AND coalesce(pg_catalog.current_setting('fcm.retrospective_register_completion', true), '') <> 'on' THEN
      NEW.dispatched_at := now();
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;
COMMENT ON FUNCTION "public"."tg_dispatch_job_stamp_milestones"() IS 'Fills lifecycle milestone timestamps when a governed path does not supply them. The audited retrospective-register path suppresses only the synthetic dispatched_at milestone.';
REVOKE ALL ON FUNCTION "public"."tg_dispatch_job_stamp_milestones"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."tg_dispatch_job_stamp_milestones"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."tg_dispatch_job_stamp_milestones"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."tg_dispatch_job_stamp_milestones"() TO "anon";
