GRANT EXECUTE ON FUNCTION "public"."tg_dispatch_job_stamp_milestones"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."tg_enforce_module_dependencies"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.enabled THEN
    IF EXISTS (
      SELECT 1 FROM public.module_dependencies dep
      WHERE dep.module_key = NEW.module_key
        AND NOT EXISTS (
          SELECT 1 FROM public.organization_modules om
          WHERE om.organization_id = NEW.organization_id
            AND om.module_key = dep.depends_on_module_key
            AND om.enabled
        )
    ) THEN
      RAISE EXCEPTION 'Module % requires its dependency module to be enabled first', NEW.module_key;
    END IF;
  ELSE
    IF EXISTS (
      SELECT 1 FROM public.module_dependencies dep
      JOIN public.organization_modules om
        ON om.organization_id = NEW.organization_id
        AND om.module_key = dep.module_key
        AND om.enabled
      WHERE dep.depends_on_module_key = NEW.module_key
    ) THEN
      RAISE EXCEPTION 'Cannot disable % while a dependent module remains enabled', NEW.module_key;
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."tg_enforce_module_dependencies"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."tg_enforce_module_dependencies"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."tg_enforce_module_dependencies"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."tg_enforce_roster_slot_skill_requirements"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_required text[]; v_missing text;
begin
  if new.staff_id is null then return new; end if;
  select required_skill_names into v_required from public.roster_work_units where id = new.work_unit_id;
  select required into v_missing
  from unnest(coalesce(v_required, '{}')) required
  where not exists (
    select 1 from public.staff_skills skill
    where skill.staff_id = new.staff_id
      and lower(trim(skill.skill_name)) = lower(trim(required))
      and (not skill.certified or skill.certification_expiry is null or skill.certification_expiry >= current_date)
  ) limit 1;
  if v_missing is not null then raise exception 'Assigned staff member lacks required current skill: %', v_missing; end if;
  return new;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."tg_enforce_roster_slot_skill_requirements"() FROM PUBLIC, "anon", "authenticated", "service_role";
