CREATE OR REPLACE FUNCTION "public"."tg_notify_roster_slot_change"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid;
  v_title text;
  v_body text;
  v_kind text;
begin
  if tg_op <> 'UPDATE' then return new; end if;
  if new.staff_id is not distinct from old.staff_id
     and new.scheduled_start is not distinct from old.scheduled_start
     and new.scheduled_end is not distinct from old.scheduled_end
     and new.status is not distinct from old.status then return new; end if;

  select sp.user_id into v_user_id from public.staff_profiles sp where sp.id = new.staff_id;
  if v_user_id is null then return new; end if;
  v_kind := case when new.staff_id is distinct from old.staff_id then 'reassigned' when new.status = 'cancelled' then 'cancelled' when new.status = 'published' and old.status = 'draft' then 'published' when new.scheduled_start is distinct from old.scheduled_start or new.scheduled_end is distinct from old.scheduled_end then 'updated' else new.status end;
  v_title := 'Roster assignment ' || v_kind;
  v_body := case when v_kind = 'cancelled' then 'A roster assignment has been cancelled.' when v_kind = 'reassigned' then 'A roster assignment has been reassigned to you.' else 'A roster assignment has changed. Review your schedule.' end;
  perform public.enqueue_notification(p_organization_id => new.organization_id, p_category => 'roster', p_title => v_title, p_body => v_body, p_severity => case when v_kind = 'cancelled' then 'warning' else 'info' end, p_recipient_user_id => v_user_id, p_link_page => 'schedule', p_link_payload => jsonb_build_object('roster_slot_id', new.id, 'status', new.status), p_dedup_key => 'roster_slot_change:' || new.id::text || ':' || v_kind || ':' || coalesce(new.updated_at::text, now()::text));
  return new;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."tg_notify_roster_slot_change"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."tg_notify_roster_slot_change"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."tg_notify_roster_slot_change"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."tg_notify_roster_slot_change"() TO "anon";
GRANT EXECUTE ON FUNCTION "public"."tg_notify_roster_slot_change"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."tg_notify_roster_slot_change"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."tg_notify_shift_change"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_user_id uuid; v_kind text; v_title text; v_body text;
begin
  if tg_op <> 'UPDATE' then return new; end if;
  if coalesce(current_setting('fcm.silent_shift_notice', true), 'off') = 'on' then return new; end if;
  if new.officer_user_id is not distinct from old.officer_user_id and new.scheduled_start is not distinct from old.scheduled_start and new.scheduled_end is not distinct from old.scheduled_end and new.status is not distinct from old.status then return new; end if;
  v_user_id := new.officer_user_id;
  if v_user_id is null then return new; end if;
  v_kind := case when new.officer_user_id is distinct from old.officer_user_id then 'ownership' when new.status = 'cancelled' then 'cancelled' when new.status = 'in_progress' then 'started' when new.status = 'completed' then 'completed' when new.status = 'missed' then 'missed' when new.scheduled_start is distinct from old.scheduled_start or new.scheduled_end is distinct from old.scheduled_end then 'timing' else new.status end;
  v_title := case when v_kind = 'missed' then 'Shift recorded as missed' else 'Shift ' || v_kind end;
  v_body := case when v_kind = 'cancelled' then 'A field shift has been cancelled.'
                 when v_kind = 'completed' then 'Your shift has been completed and is ready for timesheet review.'
                 when v_kind = 'missed' then 'You did not start the shift of ' || to_char(new.scheduled_start at time zone 'Pacific/Auckland', 'Dy DD Mon HH24:MI') || '–' || to_char(new.scheduled_end at time zone 'Pacific/Auckland', 'HH24:MI') || '. Your supervisor has been told. If this is wrong, talk to them today.'
                 else 'Your field shift has changed. Review your schedule.' end;
  perform public.enqueue_notification(p_organization_id => new.organization_id, p_category => 'roster', p_title => v_title, p_body => v_body, p_severity => case when v_kind in ('cancelled', 'missed') then 'warning' else 'info' end, p_recipient_user_id => v_user_id, p_link_page => 'schedule', p_link_payload => jsonb_build_object('shift_id', new.id, 'status', new.status), p_dedup_key => 'shift_change:' || new.id::text || ':' || v_kind || ':' || new.updated_at::text);
  return new;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."tg_notify_shift_change"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."tg_notify_shift_change"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."tg_notify_shift_change"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."tg_notify_shift_change"() TO "anon";
GRANT EXECUTE ON FUNCTION "public"."tg_notify_shift_change"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."tg_notify_shift_change"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."tg_observations_enforce_lock"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  -- CONDITION A: post-lock edit (row was already locked before this UPDATE).
  if old.locked_at is not null then
    -- Block clearing or rewriting locked_at.
    if new.locked_at is distinct from old.locked_at then
      raise exception
        'observation % is locked. locked_at may not be cleared or rewritten. Use the authorised correction path.',
        old.id
        using errcode = 'P0001';
    end if;
    -- Block changes to frozen fact fields.
    if (
      new.observed_at       is distinct from old.observed_at       or
      new.gps_lat           is distinct from old.gps_lat           or
      new.gps_lng           is distinct from old.gps_lng           or
      new.plate_number      is distinct from old.plate_number      or
      new.is_compliant      is distinct from old.is_compliant      or
      new.compliance_reason is distinct from old.compliance_reason or
      new.officer_id        is distinct from old.officer_id        or
      new.zone_id           is distinct from old.zone_id
    ) then
      raise exception
        'observation % is locked (locked_at = %). Frozen fact fields may not be edited after lock. Authorised corrections require the correction workflow (Part 2, not yet built).',
        old.id, old.locked_at
        using errcode = 'P0001';
    end if;
  end if;

  -- CONDITION B: lock-transition tamper (this UPDATE causes the row to become locked).
  -- The normal completion write sets photo fields only and must pass through.
  -- A tampered write that also changes frozen fields must be blocked.
  if old.locked_at is null and new.locked_at is not null then
    if (
      new.observed_at       is distinct from old.observed_at       or
      new.gps_lat           is distinct from old.gps_lat           or
      new.gps_lng           is distinct from old.gps_lng           or
      new.plate_number      is distinct from old.plate_number      or
      new.is_compliant      is distinct from old.is_compliant      or
      new.compliance_reason is distinct from old.compliance_reason or
      new.officer_id        is distinct from old.officer_id        or
      new.zone_id           is distinct from old.zone_id
    ) then
      raise exception
        'observation % cannot be locked with mutated frozen fields. Frozen fact fields must be unchanged at the moment of lock.',
        old.id
        using errcode = 'P0001';
    end if;
  end if;

  return new;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."tg_observations_enforce_lock"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."tg_observations_enforce_lock"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."tg_observations_enforce_lock"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."tg_observations_enforce_lock"() TO "anon";
GRANT EXECUTE ON FUNCTION "public"."tg_observations_enforce_lock"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."tg_observations_enforce_lock"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."tg_observations_lock_on_completion"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  -- Transition-based: only fire when photo_captured_at goes NULL -> NOT NULL.
  -- Never fires if photo_captured_at was already set, or if it stays null.
  if (old.photo_captured_at is null and new.photo_captured_at is not null) then
    -- Write-once: only set locked_at if not already set (idempotent).
    if new.locked_at is null then
      new.locked_at := now();
    end if;
  end if;
  return new;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."tg_observations_lock_on_completion"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."tg_observations_lock_on_completion"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."tg_observations_lock_on_completion"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."tg_observations_lock_on_completion"() TO "anon";
GRANT EXECUTE ON FUNCTION "public"."tg_observations_lock_on_completion"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."tg_observations_lock_on_completion"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."tg_place_permanence"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF current_setting('app.place_delete_scope', true) = 'test_dataset_purge' THEN RETURN OLD; END IF;
  IF current_setting('app.place_delete_scope', true) = 'active_build_cleanup' THEN RETURN OLD; END IF;
  -- A service or admin session may roll back a row it created moments ago (proposal compensation).
  IF (auth.role() = 'service_role' OR session_user IN ('postgres', 'supabase_admin'))
     AND OLD.created_at > clock_timestamp() - interval '15 minutes' THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'Places are permanent: %.% cannot be deleted. Retire or merge it instead.', TG_TABLE_NAME, OLD.id
    USING ERRCODE = 'P0001', HINT = 'docs/canon/LOCATION_HOUSE_MODEL.md, ruling 2026-09-15';
END $function$;
REVOKE ALL ON FUNCTION "public"."tg_place_permanence"() FROM PUBLIC, "anon", "authenticated", "service_role";
