CREATE OR REPLACE FUNCTION "public"."timesheet_dispatch_pay_review_blocker"(p_timesheet_id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case
    when line.id is null then 'missing pay evidence for dispatch work'
    when line.pay_code = 'UNRESOLVED' then 'unresolved dispatch pay evidence'
    when latest.decision is null then 'unreviewed dispatch pay evidence'
    when latest.decision <> 'approved' then 'rejected dispatch pay evidence'
  end
  from public.timesheet_work_entries work
  left join public.dispatch_job_pay_lines line
    on line.organization_id = work.organization_id
   and line.source_dispatch_id = work.source_id
  left join lateral (
    select review.decision
    from public.dispatch_job_pay_line_reviews review
    where review.pay_line_id = line.id
    order by review.reviewed_at desc, review.id desc
    limit 1
  ) latest on true
  where work.timesheet_id = p_timesheet_id
    and work.source_type = 'dispatch_job'
    and (line.id is null or line.pay_code = 'UNRESOLVED' or latest.decision is distinct from 'approved')
  order by work.created_at, line.created_at nulls first
  limit 1;
$function$;
REVOKE ALL ON FUNCTION "public"."timesheet_dispatch_pay_review_blocker"(p_timesheet_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."timesheet_dispatch_pay_review_blocker"(p_timesheet_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."timesheet_dispatch_pay_review_blocker"(p_timesheet_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."timesheet_effective_pay"(p_timesheet_id uuid)
 RETURNS TABLE(rate_rule_id uuid, pay_code text, hourly_rate numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT CASE WHEN t.payroll_snapshot IS NOT NULL THEN (t.payroll_snapshot->>'rate_rule_id')::uuid ELSE r.id END,
    coalesce(t.payroll_snapshot->>'pay_code',t.pay_code_override,r.pay_code),
    coalesce((t.payroll_snapshot->>'hourly_rate')::numeric,t.hourly_rate_override,r.amount)
  FROM public.timesheets t
  JOIN public.staff_profiles sp ON sp.id=t.staff_id AND sp.organization_id=t.organization_id
  LEFT JOIN public.shifts s ON s.id=t.shift_id
  LEFT JOIN LATERAL (
    SELECT rr.id,rr.pay_code,rr.amount FROM public.rate_rules rr
    WHERE rr.organization_id=t.organization_id AND rr.rule_kind='pay' AND rr.rate_type='hourly' AND rr.active
      AND (rr.role_code IS NULL OR rr.role_code=sp.role_code)
      AND (rr.service_type IS NULL OR rr.service_type=s.service_type)
      AND (rr.effective_from IS NULL OR rr.effective_from<=t.period_start)
      AND (rr.effective_to IS NULL OR rr.effective_to>=t.period_start)
    ORDER BY (rr.role_code IS NOT NULL)::integer DESC,(rr.service_type IS NOT NULL)::integer DESC,
      rr.priority DESC,rr.effective_from DESC NULLS LAST,rr.id LIMIT 1
  ) r ON true
  WHERE t.id=p_timesheet_id AND public.is_admin_for_org(t.organization_id)
    AND EXISTS (SELECT 1 FROM public.user_profiles u WHERE u.id=auth.uid()
      AND u.organization_id=t.organization_id AND u.deactivated_at IS NULL)
$function$;
REVOKE ALL ON FUNCTION "public"."timesheet_effective_pay"(p_timesheet_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."timesheet_effective_pay"(p_timesheet_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."timesheet_effective_pay"(p_timesheet_id uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."trg_location_zones_parent_same_org"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.parent_zone_id IS NOT NULL THEN
    IF NEW.parent_zone_id = NEW.id THEN
      RAISE EXCEPTION 'A zone cannot be its own parent';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.location_zones p
      WHERE p.id = NEW.parent_zone_id AND p.organization_id = NEW.organization_id
    ) THEN
      RAISE EXCEPTION 'parent_zone_id must reference a zone owned by the same organisation';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;
