CREATE OR REPLACE FUNCTION "public"."update_person_housing_status"(p_organization_id uuid, p_person_id uuid, p_client_request_id uuid, p_expected_version timestamp with time zone, p_status text, p_notes text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_person public.canonical_people%rowtype;
  v_request jsonb := jsonb_build_object('person_id', p_person_id, 'expected_version', p_expected_version,
    'status', p_status, 'notes', nullif(btrim(p_notes), ''), 'reason', btrim(p_reason));
  v_audit public.audit_log%rowtype;
  v_requires_verified boolean;
  v_previous jsonb;
  v_result jsonb;
BEGIN
  IF NOT public.person_record_admin_allowed(p_organization_id, p_person_id) THEN
    RAISE EXCEPTION 'Person record not found or administrator access denied';
  END IF;
  IF p_client_request_id IS NULL THEN RAISE EXCEPTION 'A request ID is required'; END IF;
  IF coalesce(length(btrim(p_reason)), 0) NOT BETWEEN 5 AND 1000 OR coalesce(length(p_notes), 0) > 2000 THEN
    RAISE EXCEPTION 'Give a reason of 5 to 1000 characters and notes of up to 2000 characters';
  END IF;
  SELECT requires_verified_identity INTO v_requires_verified FROM public.person_housing_status_definitions WHERE code = p_status;
  IF NOT FOUND THEN RAISE EXCEPTION 'Select a configured housing status'; END IF;
  IF v_requires_verified AND NOT (public.get_person_record_operations(p_organization_id, p_person_id)->>'verified')::boolean THEN
    RAISE EXCEPTION 'Verify the person identity before confirming homelessness';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_organization_id::text || ':housing:' || p_client_request_id, 0));
  SELECT * INTO v_audit FROM public.audit_log WHERE organization_id = p_organization_id
    AND action = 'person_housing_status_updated' AND metadata->>'client_request_id' = p_client_request_id::text LIMIT 1;
  IF FOUND THEN
    IF v_audit.metadata->'request' IS DISTINCT FROM v_request THEN RAISE EXCEPTION 'Request ID already used for a different housing update'; END IF;
    RETURN v_audit.metadata->'resulting';
  END IF;
  SELECT * INTO v_person FROM public.canonical_people WHERE id = p_person_id FOR UPDATE;
  IF v_person.updated_at IS DISTINCT FROM p_expected_version THEN RAISE EXCEPTION 'Person record changed; reload before saving'; END IF;
  v_previous := jsonb_build_object('status', v_person.homeless_status, 'notes', v_person.homeless_notes,
    'verified_at', v_person.homeless_verified_at, 'version', v_person.updated_at);
  UPDATE public.canonical_people SET homeless_status = p_status, homeless_notes = nullif(btrim(p_notes), ''),
    homeless_verified_at = CASE WHEN p_status = 'confirmed' THEN clock_timestamp() ELSE NULL END,
    updated_at = clock_timestamp() WHERE id = p_person_id RETURNING * INTO v_person;
  v_result := jsonb_build_object('status', v_person.homeless_status, 'notes', v_person.homeless_notes,
    'verified_at', v_person.homeless_verified_at, 'version', v_person.updated_at);
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (p_organization_id, auth.uid(), 'person_housing_status_updated', 'canonical_people', p_person_id,
    jsonb_build_object('client_request_id', p_client_request_id, 'request', v_request, 'previous', v_previous, 'resulting', v_result));
  RETURN v_result;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."update_person_housing_status"(p_organization_id uuid, p_person_id uuid, p_client_request_id uuid, p_expected_version timestamp with time zone, p_status text, p_notes text, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."update_person_housing_status"(p_organization_id uuid, p_person_id uuid, p_client_request_id uuid, p_expected_version timestamp with time zone, p_status text, p_notes text, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."update_person_housing_status"(p_organization_id uuid, p_person_id uuid, p_client_request_id uuid, p_expected_version timestamp with time zone, p_status text, p_notes text, p_reason text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."update_roster_slot"(p_slot_id uuid, p_expected_status text, p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_notes text DEFAULT NULL::text)
 RETURNS roster_slots
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_slot public.roster_slots%rowtype;
  v_staff public.staff_profiles%rowtype;
  v_fatigue text;
begin
  select s.* into v_slot from public.roster_slots s where s.id = p_slot_id for update;
  if not found then raise exception 'Roster slot not found'; end if;
  if not public.is_admin_for_org(v_slot.organization_id) then raise exception 'Not authorised to edit this roster slot'; end if;
  if v_slot.status <> p_expected_status then raise exception 'Roster slot changed from expected status % to %', p_expected_status, v_slot.status; end if;
  if v_slot.status <> 'draft' then raise exception 'Only draft roster slots can be edited'; end if;
  if p_scheduled_end <= p_scheduled_start then raise exception 'Roster slot must end after it starts'; end if;

  select sp.* into v_staff from public.staff_profiles sp where sp.id = p_staff_id and sp.work_ready;
  if not found or not (
    v_staff.organization_id = v_slot.organization_id
    or exists (select 1 from public.staff_branch_authorisations sba where sba.user_id = coalesce(v_staff.user_id, v_staff.id) and sba.branch_org_id = v_slot.organization_id and sba.status = 'active')
  ) then raise exception 'Work-ready staff profile required'; end if;
  if public.staff_has_roster_availability_conflict(v_staff.id, p_scheduled_start, p_scheduled_end) then raise exception 'Staff member is unavailable during this roster slot'; end if;
  v_fatigue := public.staff_fatigue_conflict(v_staff.id, p_scheduled_start, p_scheduled_end, v_slot.id);
  if v_fatigue is not null then raise exception 'Fatigue rule breach: %', v_fatigue; end if;

  update public.roster_slots set staff_id = p_staff_id, scheduled_start = p_scheduled_start, scheduled_end = p_scheduled_end, notes = nullif(trim(coalesce(p_notes, '')), '') where id = v_slot.id returning * into v_slot;
  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (v_slot.organization_id, v_actor, 'roster_slot_human_edited', 'roster_slots', v_slot.id, jsonb_build_object('staff_id', p_staff_id, 'scheduled_start', p_scheduled_start, 'scheduled_end', p_scheduled_end));
  return v_slot;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."update_roster_slot"(p_slot_id uuid, p_expected_status text, p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."update_roster_slot"(p_slot_id uuid, p_expected_status text, p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."update_roster_slot"(p_slot_id uuid, p_expected_status text, p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."update_roster_slot"(p_slot_id uuid, p_expected_status text, p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."update_roster_slot_with_break"(p_slot_id uuid, p_expected_status text, p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_notes text DEFAULT NULL::text, p_planned_break_minutes integer DEFAULT 0, p_break_unpaid boolean DEFAULT false)
 RETURNS roster_slots
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_slot public.roster_slots%rowtype;
begin
  select * into v_slot from public.roster_slots where id = p_slot_id for update;
  if not found or auth.uid() is null or not public.is_admin_for_org(v_slot.organization_id)
    or not exists(select 1 from public.user_profiles where id = auth.uid() and deactivated_at is null)
    or v_slot.status is distinct from p_expected_status or v_slot.status <> 'draft' then
    raise exception 'An unchanged draft and active roster administrator are required' using errcode = '42501';
  end if;
  -- The old allowance must not prevent shortening a shift while reducing its break in the same transaction.
  update public.roster_slots set planned_break_minutes = 0 where id = p_slot_id;
  perform public.update_roster_slot(p_slot_id, p_expected_status, p_staff_id, p_scheduled_start, p_scheduled_end, p_notes);
  select * into v_slot from public.set_roster_slot_break(p_slot_id, p_expected_status, p_planned_break_minutes, p_break_unpaid);
  return v_slot;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."update_roster_slot_with_break"(p_slot_id uuid, p_expected_status text, p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_notes text, p_planned_break_minutes integer, p_break_unpaid boolean) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."update_roster_slot_with_break"(p_slot_id uuid, p_expected_status text, p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_notes text, p_planned_break_minutes integer, p_break_unpaid boolean) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."update_roster_slot_with_break"(p_slot_id uuid, p_expected_status text, p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_notes text, p_planned_break_minutes integer, p_break_unpaid boolean) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."update_vehicle_profile_details"(p_organization_id uuid, p_vehicle_id uuid, p_fields jsonb, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_before public.canonical_vehicles%rowtype;
  v_after public.canonical_vehicles%rowtype;
  v_year integer;
  v_changed jsonb := '{}'::jsonb;
  v_key text;
BEGIN
  IF v_actor IS NULL OR NOT public.is_admin_for_org(p_organization_id) THEN
    RAISE EXCEPTION 'Identity registry administrator access required';
  END IF;
  IF coalesce(trim(p_reason), '') = '' THEN RAISE EXCEPTION 'A reason is required for the identity audit trail'; END IF;
  IF p_fields IS NULL OR jsonb_typeof(p_fields) <> 'object'
    OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_fields) k
      WHERE k NOT IN ('make','model','year','colour','body_type','rego_expiry','wof_expiry','cof_expiry')) THEN
    RAISE EXCEPTION 'Unsupported vehicle profile fields';
  END IF;
  IF EXISTS (SELECT 1 FROM jsonb_each_text(p_fields) entry WHERE length(entry.value) > 100) THEN
    RAISE EXCEPTION 'Vehicle profile fields must be at most 100 characters';
  END IF;
  IF nullif(p_fields->>'year', '') IS NOT NULL THEN
    v_year := (p_fields->>'year')::integer;
    IF v_year NOT BETWEEN 1886 AND extract(year FROM current_date)::integer + 1 THEN RAISE EXCEPTION 'Enter a valid vehicle year'; END IF;
  END IF;

  SELECT * INTO v_before FROM public.canonical_vehicles WHERE id = p_vehicle_id FOR UPDATE;
  IF v_before.id IS NULL THEN RAISE EXCEPTION 'Canonical vehicle not found'; END IF;

  UPDATE public.canonical_vehicles SET
    make = coalesce(nullif(trim(p_fields->>'make'), ''), make),
    model = coalesce(nullif(trim(p_fields->>'model'), ''), model),
    year = coalesce(v_year, year),
    colour = coalesce(nullif(trim(p_fields->>'colour'), ''), colour),
    body_type = coalesce(nullif(trim(p_fields->>'body_type'), ''), body_type),
    rego_expiry = coalesce(nullif(p_fields->>'rego_expiry', '')::date, rego_expiry),
    wof_expiry = coalesce(nullif(p_fields->>'wof_expiry', '')::date, wof_expiry),
    cof_expiry = coalesce(nullif(p_fields->>'cof_expiry', '')::date, cof_expiry)
  WHERE id = p_vehicle_id
  RETURNING * INTO v_after;

  FOREACH v_key IN ARRAY ARRAY['make','model','year','colour','body_type','rego_expiry','wof_expiry','cof_expiry'] LOOP
    IF (to_jsonb(v_before)->v_key) IS DISTINCT FROM (to_jsonb(v_after)->v_key) THEN
      v_changed := v_changed || jsonb_build_object(v_key, jsonb_build_object('before', to_jsonb(v_before)->v_key, 'after', to_jsonb(v_after)->v_key));
    END IF;
  END LOOP;
  IF v_changed = '{}'::jsonb THEN
    RETURN jsonb_build_object('vehicle_id', p_vehicle_id, 'plate_number', v_before.plate_number, 'changed', false);
  END IF;

  UPDATE public.canonical_vehicles SET
    rego_status = CASE WHEN v_changed ? 'rego_expiry' THEN CASE WHEN rego_expiry >= current_date THEN 'current' ELSE 'expired' END ELSE rego_status END,
    wof_status = CASE WHEN v_changed ? 'wof_expiry' THEN CASE WHEN wof_expiry >= current_date THEN 'current' ELSE 'expired' END ELSE wof_status END,
    cof_status = CASE WHEN v_changed ? 'cof_expiry' THEN CASE WHEN cof_expiry >= current_date THEN 'current' ELSE 'expired' END ELSE cof_status END,
    compliance_source = 'manual',
    compliance_checked_at = clock_timestamp(),
    details_updated_at = clock_timestamp(),
    details_updated_by_org_id = p_organization_id,
    details_updated_by = v_actor,
    updated_at = clock_timestamp()
  WHERE id = p_vehicle_id;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (p_organization_id, v_actor, 'vehicle_profile_details_updated', 'canonical_vehicles', p_vehicle_id,
    jsonb_build_object('plate', v_before.plate_number, 'reason', trim(p_reason), 'changes', v_changed,
      'scope', 'shared_canonical_vehicle'));
  RETURN jsonb_build_object('vehicle_id', p_vehicle_id, 'plate_number', v_before.plate_number, 'changed', true);
END;
$function$;
COMMENT ON FUNCTION "public"."update_vehicle_profile_details"(p_organization_id uuid, p_vehicle_id uuid, p_fields jsonb, p_reason text) IS 'Any organisation administrator may correct shared canonical vehicle profile facts (owner ruling 2026-10-20). Audits before/after values and stamps details_updated_at/by org. Does not touch plate, identifiers, owner or organisation notes.';
REVOKE ALL ON FUNCTION "public"."update_vehicle_profile_details"(p_organization_id uuid, p_vehicle_id uuid, p_fields jsonb, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."update_vehicle_profile_details"(p_organization_id uuid, p_vehicle_id uuid, p_fields jsonb, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."update_vehicle_profile_details"(p_organization_id uuid, p_vehicle_id uuid, p_fields jsonb, p_reason text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."upsert_file_entity_folder"(p_organization_id uuid, p_space_key text, p_parent_key text, p_entity_type text, p_entity_id uuid, p_name text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_space uuid;v_parent uuid;v_folder uuid;v_name text:=coalesce(nullif(trim(p_name),''),'Unnamed');
BEGIN
  PERFORM public.ensure_file_organization_tree(p_organization_id);
  SELECT id INTO v_space FROM public.file_spaces WHERE organization_id=p_organization_id AND space_key=p_space_key AND active;
  IF v_space IS NULL THEN RAISE EXCEPTION 'File space not found'; END IF;
  IF p_parent_key IS NOT NULL THEN SELECT id INTO v_parent FROM public.file_folders WHERE space_id=v_space AND folder_key=p_parent_key AND active; END IF;
  IF EXISTS(SELECT 1 FROM public.file_folders folder WHERE folder.space_id=v_space AND folder.parent_folder_id IS NOT DISTINCT FROM v_parent AND lower(folder.name)=lower(v_name) AND folder.active AND NOT (folder.entity_type=p_entity_type AND folder.entity_id=p_entity_id)) THEN
    v_name:=left(v_name,145)||' · '||left(p_entity_id::text,8);
  END IF;
  INSERT INTO public.file_folders(organization_id,space_id,parent_folder_id,name,folder_key,folder_kind,entity_type,entity_id)
  VALUES(p_organization_id,v_space,v_parent,left(v_name,160),'entity:'||p_entity_type||':'||p_entity_id::text,'entity',p_entity_type,p_entity_id)
  ON CONFLICT(organization_id,entity_type,entity_id) WHERE active AND entity_type IS NOT NULL
  DO UPDATE SET space_id=excluded.space_id,parent_folder_id=excluded.parent_folder_id,name=excluded.name,folder_key=excluded.folder_key,updated_at=clock_timestamp()
  RETURNING id INTO v_folder;
  RETURN v_folder;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."upsert_file_entity_folder"(p_organization_id uuid, p_space_key text, p_parent_key text, p_entity_type text, p_entity_id uuid, p_name text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."upsert_file_entity_folder"(p_organization_id uuid, p_space_key text, p_parent_key text, p_entity_type text, p_entity_id uuid, p_name text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."upsert_file_entity_folder"(p_organization_id uuid, p_space_key text, p_parent_key text, p_entity_type text, p_entity_id uuid, p_name text) TO "service_role";

