CREATE OR REPLACE FUNCTION "public"."user_managed_branch_ids"()
 RETURNS uuid[]
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT coalesce(array_agg(sba.branch_org_id), ARRAY[]::uuid[])
  FROM public.staff_branch_authorisations sba
  JOIN public.user_profiles p
    ON p.id = sba.user_id
   AND p.deactivated_at IS NULL
  WHERE sba.user_id = auth.uid()
    AND sba.status = 'active'
    AND sba.role_at_branch = 'branch_manager';
$function$;
REVOKE ALL ON FUNCTION "public"."user_managed_branch_ids"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."user_managed_branch_ids"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."user_managed_branch_ids"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."user_managed_branch_ids"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."validate_assignment_location_access"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_assignment_org_id uuid;
  v_site_id           uuid := null;
  v_zone_id           uuid := null;
  v_has_access        boolean;
begin
  -- Resolve the assignment org from patrol_routes.
  select organization_id into v_assignment_org_id
    from public.patrol_routes
   where id = new.patrol_route_id;

  if v_assignment_org_id is null then
    raise exception 'Assignment (patrol_route_id=%) not found or has no organization_id.', new.patrol_route_id;
  end if;

  -- Determine which location is being added.
  if tg_table_name = 'patrol_route_sites' then
    v_site_id := new.site_id;
  else
    v_zone_id := new.zone_id;
  end if;

  -- Check ownership: does the assignment org own the location?
  if v_site_id is not null then
    select exists (
      select 1 from public.client_sites
      where id = v_site_id
        and client_organization_id = v_assignment_org_id
    ) into v_has_access;
  else
    select exists (
      select 1 from public.location_zones
      where id = v_zone_id
        and organization_id = v_assignment_org_id
    ) into v_has_access;
  end if;

  -- If not owner, check for an active service_agreement_locations row
  -- where the assignment org is the provider.
  if not v_has_access then
    select exists (
      select 1
      from public.service_agreement_locations sal
      join public.service_agreements sa on sa.id = sal.service_agreement_id
      where sal.status = 'active'
        and (sal.site_id = v_site_id or sal.zone_id = v_zone_id)
        and sa.provider_organization_id = v_assignment_org_id
    ) into v_has_access;
  end if;

  if not v_has_access then
    raise exception
      'Cannot add location to assignment: org % does not own this location and has no active service agreement for it. Create a service_agreement_locations row first.',
      v_assignment_org_id
      using errcode = 'P0001';
  end if;

  return new;
end;
$function$;
COMMENT ON FUNCTION "public"."validate_assignment_location_access"() IS 'Trigger: validates that the assignment org owns the location OR has an active service_agreement_locations row before allowing a location to be added to an assignment (patrol_route_sites / patrol_route_zones). QA gap G4, epic #179.';
REVOKE ALL ON FUNCTION "public"."validate_assignment_location_access"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."validate_assignment_location_access"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."validate_assignment_location_access"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."validate_assignment_location_access"() TO "anon";
GRANT EXECUTE ON FUNCTION "public"."validate_assignment_location_access"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."validate_assignment_location_access"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."validate_dispatch_job_service_agreement"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_site_agreement_id uuid;
begin
  if new.client_site_id is null then
    return new;
  end if;

  select cs.service_agreement_id
    into v_site_agreement_id
  from public.client_sites cs
  where cs.id = new.client_site_id;

  if v_site_agreement_id is not null then
    if new.service_agreement_id is null then
      new.service_agreement_id := v_site_agreement_id;
    elsif new.service_agreement_id <> v_site_agreement_id then
      raise exception
        'dispatch_jobs.service_agreement_id (%) must match client_sites.service_agreement_id (%) for client_site_id (%)',
        new.service_agreement_id, v_site_agreement_id, new.client_site_id;
    end if;
  end if;

  return new;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."validate_dispatch_job_service_agreement"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."validate_dispatch_job_service_agreement"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."validate_dispatch_job_service_agreement"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."validate_dispatch_job_service_agreement"() TO "anon";
GRANT EXECUTE ON FUNCTION "public"."validate_dispatch_job_service_agreement"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."validate_dispatch_job_service_agreement"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."validate_file_folder_parent"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_parent public.file_folders%rowtype;
BEGIN
  IF NEW.parent_folder_id IS NULL THEN RETURN NEW; END IF;
  IF NEW.parent_folder_id=NEW.id THEN RAISE EXCEPTION 'A folder cannot contain itself'; END IF;
  SELECT * INTO v_parent FROM public.file_folders WHERE id=NEW.parent_folder_id;
  IF v_parent.id IS NULL OR v_parent.organization_id<>NEW.organization_id OR v_parent.space_id<>NEW.space_id THEN RAISE EXCEPTION 'Parent folder must be in the same file space'; END IF;
  IF EXISTS(WITH RECURSIVE ancestors AS(SELECT parent_folder_id FROM public.file_folders WHERE id=NEW.parent_folder_id UNION ALL SELECT folder.parent_folder_id FROM public.file_folders folder JOIN ancestors ON folder.id=ancestors.parent_folder_id) SELECT 1 FROM ancestors WHERE parent_folder_id=NEW.id) THEN RAISE EXCEPTION 'Folder nesting would create a cycle'; END IF;
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."validate_file_folder_parent"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."validate_file_folder_parent"() TO "postgres";

CREATE OR REPLACE FUNCTION "public"."validate_location_event_checkpoint_anchor"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_checkpoint public.patrol_checkpoints%rowtype;
BEGIN
  IF NEW.client_site_id IS NOT NULL AND NEW.zone_id IS NOT NULL THEN
    RAISE EXCEPTION 'Location event must reference a Site or Zone, not both';
  END IF;
  IF NEW.checkpoint_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT * INTO v_checkpoint FROM public.patrol_checkpoints WHERE id = NEW.checkpoint_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Checkpoint not found'; END IF;
  IF NEW.organization_id IS DISTINCT FROM v_checkpoint.organization_id THEN
    RAISE EXCEPTION 'Checkpoint and event organization do not match';
  END IF;
  IF v_checkpoint.client_site_id IS NOT NULL THEN
    IF NEW.client_site_id IS DISTINCT FROM v_checkpoint.client_site_id OR NEW.zone_id IS NOT NULL THEN
      RAISE EXCEPTION 'Checkpoint belongs to a different Site than the event anchor';
    END IF;
  ELSIF v_checkpoint.zone_id IS NOT NULL THEN
    IF NEW.zone_id IS DISTINCT FROM v_checkpoint.zone_id OR NEW.client_site_id IS NOT NULL THEN
      RAISE EXCEPTION 'Checkpoint belongs to a different Zone than the event anchor';
    END IF;
  ELSE
    RAISE EXCEPTION 'Checkpoint has no Site or Zone parent';
  END IF;
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."validate_location_event_checkpoint_anchor"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."validate_location_event_checkpoint_anchor"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."validate_location_event_checkpoint_anchor"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."validate_location_event_checkpoint_anchor"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."validate_patrol_route_primary_staff"()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  -- API roles reach this trigger directly; the audited SECURITY DEFINER RPC runs as its owner.
  if current_user in ('anon', 'authenticated', 'service_role')
     and new.primary_staff_id is distinct from (case when tg_op = 'UPDATE' then old.primary_staff_id end) then
    raise exception 'Change the usual officer with set_patrol_route_primary_officer, which records a reason and audit entry';
  end if;
  if new.primary_staff_id is not null and not exists (
    select 1 from public.staff_profiles where id = new.primary_staff_id and organization_id = new.organization_id
  ) then
    raise exception 'The primary officer must be a staff member of the route organisation';
  end if;
  return new;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."validate_patrol_route_primary_staff"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."validate_patrol_route_primary_staff"() TO "postgres";

CREATE OR REPLACE FUNCTION "public"."validate_ta_names"(p_names text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  v_result jsonb := '[]'::jsonb;
  v_name text;
  v_match text;
  v_suggestions jsonb;
  v_entry jsonb;
BEGIN
  -- If the canonical_ta_names table is empty, return all as valid
  -- (defence in depth: do not block proposals when the table has not
  -- been populated yet; the executor still validates against the live
  -- NZTA source).
  IF NOT EXISTS (SELECT 1 FROM public.canonical_ta_names LIMIT 1) THEN
    FOR i IN 1..array_length(p_names, 1) LOOP
      v_result := v_result || jsonb_build_object(
        'name', p_names[i],
        'valid', true,
        'suggestions', '[]'::jsonb,
        'note', 'canonical_ta_names table is empty; validation deferred to executor'
      );
    END LOOP;
    RETURN v_result;
  END IF;

  FOREACH v_name IN ARRAY p_names LOOP
    -- Exact match (case-insensitive)
    SELECT ta_name INTO v_match
    FROM public.canonical_ta_names
    WHERE upper(ta_name) = upper(trim(v_name))
    LIMIT 1;

    IF v_match IS NOT NULL THEN
      v_result := v_result || jsonb_build_object(
        'name', v_name,
        'valid', true,
        'canonical_name', v_match,
        'suggestions', '[]'::jsonb
      );
    ELSE
      -- No exact match: compute top 3 fuzzy suggestions by Levenshtein distance
      SELECT jsonb_agg(sub.ta_name ORDER BY sub.dist, sub.ta_name)
      INTO v_suggestions
      FROM (
        SELECT c.ta_name,
               levenshtein(upper(trim(v_name)), upper(c.ta_name)) AS dist
        FROM public.canonical_ta_names c
        ORDER BY dist ASC
        LIMIT 3
      ) sub;

      v_result := v_result || jsonb_build_object(
        'name', v_name,
        'valid', false,
        'suggestions', COALESCE(v_suggestions, '[]'::jsonb)
      );
    END IF;
  END LOOP;

  RETURN v_result;
END;
$function$;
COMMENT ON FUNCTION "public"."validate_ta_names"(p_names text[]) IS 'Validate TA names against canonical_ta_names. Returns JSON array with valid/invalid status and Levenshtein-based fuzzy suggestions for invalid names. Phase 2 geofence redesign (epic #226).';
REVOKE ALL ON FUNCTION "public"."validate_ta_names"(p_names text[]) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."validate_ta_names"(p_names text[]) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."validate_ta_names"(p_names text[]) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."validate_ta_names"(p_names text[]) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."validate_ta_names"(p_names text[]) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."validate_ta_names"(p_names text[]) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."vehicle_owner_locality"(p_details jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE
  v_street_types constant text := '(street|st|road|rd|terrace|tce|avenue|ave|drive|dr|place|pl|lane|ln|crescent|cres|way|close|grove|highway|hwy|parade|pde|quay|rise|court|ct|esplanade|mews|square|sq|boulevard|blvd|track|valley|heights|hts|view|glade|loop|green|walk)';
  v_structured text := concat_ws(', ',
    nullif(trim(p_details->>'suburb'), ''), nullif(trim(p_details->>'city'), ''));
  v_text text := nullif(trim(p_details->>'address'), '');
  v_rest text;
  v_parts text[];
  v_kept text[] := ARRAY[]::text[];
  v_part text;
BEGIN
  IF v_structured <> '' THEN RETURN v_structured; END IF;
  IF v_text IS NULL THEN RETURN NULL; END IF;
  v_text := regexp_replace(v_text, '[\s,]*\m\d{4}\s*$', '');
  v_text := regexp_replace(v_text, '\s*,?\s*(new zealand|nz)\s*$', '', 'i');

  IF position(',' IN v_text) > 0 THEN
    v_parts := regexp_split_to_array(v_text, '\s*,\s*');
    FOREACH v_part IN ARRAY v_parts LOOP
      v_part := trim(regexp_replace(v_part, '^(rd|r\.d\.)\s*\d+\s*', '', 'i'));
      CONTINUE WHEN v_part = '' OR v_part ~ '\d' OR v_part ~* ('\m' || v_street_types || '\M');
      v_kept := v_kept || v_part;
    END LOOP;
    IF cardinality(v_kept) = 0 THEN RETURN NULL; END IF;
    RETURN array_to_string(v_kept[greatest(1, cardinality(v_kept) - 1):], ', ');
  END IF;

  -- No commas: drop "<number> <name> <street type>" from the front.
  -- Leading lazy quantifier makes the whole match non-greedy (Postgres regex
  -- rule), so the first street-type word ends the street, not a later "RD 1".
  v_rest := regexp_replace(v_text, '^\s*?\S*\d\S*\s+(\S+\s+)+?' || v_street_types || '\M', '', 'i');
  IF v_rest = v_text THEN
    v_rest := regexp_replace(v_text, '^\s*?(\S+\s+)+?' || v_street_types || '\M', '', 'i');
  END IF;
  v_rest := regexp_replace(v_rest, '^[\s.,]+', '');
  -- Compound names such as "Bay View Road": drop a street type left at the front.
  -- Rural delivery numbers ("RD 1") are removed first.
  LOOP
    v_rest := regexp_replace(v_rest, '^(rd|r\.d\.)\s*\d+[\s.,]*', '', 'i');
    EXIT WHEN v_rest !~* ('^' || v_street_types || '\M');
    v_rest := regexp_replace(v_rest, '^\S+[\s.,]*', '');
  END LOOP;
  v_rest := trim(v_rest);
  -- Never leak a street number: if digits remain, the address could not be parsed safely.
  IF v_rest = '' OR v_rest ~ '\d' THEN RETURN NULL; END IF;
  RETURN v_rest;
END;
$function$;
COMMENT ON FUNCTION "public"."vehicle_owner_locality"(p_details jsonb) IS 'Suburb and city for display from person profile_details: structured suburb/city when recorded, otherwise derived from the free-text address with the street number, street name and postcode removed. Returns NULL rather than risk exposing a street address.';
REVOKE ALL ON FUNCTION "public"."vehicle_owner_locality"(p_details jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."vehicle_owner_locality"(p_details jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."vehicle_owner_locality"(p_details jsonb) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."vehicle_owner_locality"(p_details jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."verify_boundary"(p_entity_type text, p_entity_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org_id   uuid;
  v_uid      uuid := auth.uid();
  v_boundary geometry;
  v_et       text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'verify_boundary: not authenticated'; END IF;

  IF p_entity_type = 'organization' THEN
    SELECT id, jurisdiction_geom INTO v_org_id, v_boundary FROM public.organizations WHERE id = p_entity_id;
    IF NOT FOUND THEN RETURN false; END IF;
    IF NOT public.is_admin_for_org(v_org_id) THEN RAISE EXCEPTION 'verify_boundary: access denied for organization %', p_entity_id; END IF;
    v_et := 'organization';
  ELSIF p_entity_type = 'location_zone' THEN
    SELECT organization_id, boundary INTO v_org_id, v_boundary FROM public.location_zones WHERE id = p_entity_id;
    IF NOT FOUND THEN RETURN false; END IF;
    IF NOT public.is_admin_for_org(v_org_id) THEN RAISE EXCEPTION 'verify_boundary: access denied for location_zone %', p_entity_id; END IF;
    v_et := 'location_zone';
  ELSIF p_entity_type = 'client_site' THEN
    SELECT client_organization_id, boundary INTO v_org_id, v_boundary FROM public.client_sites WHERE id = p_entity_id;
    IF NOT FOUND THEN RETURN false; END IF;
    IF NOT public.org_access_allowed(v_org_id) THEN RAISE EXCEPTION 'verify_boundary: access denied for client_site %', p_entity_id; END IF;
    v_et := 'client_site';
  ELSIF p_entity_type = 'patrol_checkpoint' THEN
    -- Tier 4 is a point + radius. Same P1 rule: nothing is certified without geometry (Q4: versioned too).
    SELECT organization_id,
           CASE WHEN gps_lat IS NOT NULL AND gps_lng IS NOT NULL AND coalesce(radius_meters, 0) > 0
                THEN ST_Buffer(ST_SetSRID(ST_MakePoint(gps_lng, gps_lat), 4326)::geography, radius_meters)::geometry END
      INTO v_org_id, v_boundary
      FROM public.patrol_checkpoints WHERE id = p_entity_id;
    IF NOT FOUND THEN RETURN false; END IF;
    IF NOT public.is_admin_for_org(v_org_id) THEN RAISE EXCEPTION 'verify_boundary: access denied for patrol_checkpoint %', p_entity_id; END IF;
    v_et := 'patrol_checkpoint';
  ELSE
    RAISE EXCEPTION 'verify_boundary: unknown entity_type "%"', p_entity_type;
  END IF;

  -- P1: "no geofence" and "geometry invalid" are distinct answers and neither can be certified.
  IF v_boundary IS NULL OR ST_IsEmpty(v_boundary) THEN
    RAISE EXCEPTION 'verify_boundary: % % has no boundary geometry to verify (unresolved_no_geofence)', v_et, p_entity_id;
  END IF;
  IF NOT ST_IsValid(v_boundary) THEN
    RAISE EXCEPTION 'verify_boundary: % % boundary geometry is invalid; redraw or re-import before verifying (unresolved_invalid)', v_et, p_entity_id;
  END IF;

  IF v_et = 'organization' THEN
    UPDATE public.organizations SET jurisdiction_verification = 'verified', jurisdiction_verified_by = v_uid, jurisdiction_verified_at = now() WHERE id = p_entity_id;
  ELSIF v_et = 'location_zone' THEN
    UPDATE public.location_zones SET boundary_verification = 'verified', boundary_verified_by = v_uid, boundary_verified_at = now() WHERE id = p_entity_id;
  ELSIF v_et = 'patrol_checkpoint' THEN
    UPDATE public.patrol_checkpoints SET checkpoint_verification = 'verified', checkpoint_verified_by = v_uid, checkpoint_verified_at = now() WHERE id = p_entity_id;
  ELSE
    UPDATE public.client_sites SET boundary_verification = 'verified', boundary_verified_by = v_uid, boundary_verified_at = now() WHERE id = p_entity_id;
  END IF;

  INSERT INTO public.geofence_boundary_history (
    entity_type, entity_id, boundary, boundary_source, verification_state, verified_by, verified_at,
    changed_by, changed_via, change_reason, version
  ) VALUES (
    v_et, p_entity_id, v_boundary, NULL, 'verified', v_uid, now(),
    v_uid, 'verification', 'Boundary verified via visual map confirmation', public._gbh_next_version(v_et, p_entity_id)
  );
  RETURN true;
END;
$function$;
COMMENT ON FUNCTION "public"."verify_boundary"(p_entity_type text, p_entity_id uuid) IS 'Sets the verification state of a geofence-bearing entity to verified after a human visual map confirmation. Refuses when no geometry exists or the geometry is invalid (P1: distinct answers, never certified). Records a history row. Checkpoints: state only.';
REVOKE ALL ON FUNCTION "public"."verify_boundary"(p_entity_type text, p_entity_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."verify_boundary"(p_entity_type text, p_entity_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."verify_boundary"(p_entity_type text, p_entity_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."verify_boundary"(p_entity_type text, p_entity_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."verify_cctv_report_receipt"(p_receipt_id uuid, p_sha256 text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_receipt public.cctv_report_receipts%rowtype;
  v_recomputed text;
  v_evidence public.evidence_items%rowtype;
  v_claimed text := lower(nullif(trim(coalesce(p_sha256, '')), ''));
BEGIN
  IF auth.uid() IS NULL AND auth.role() <> 'service_role' AND session_user NOT IN ('postgres', 'supabase_admin') THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT * INTO v_receipt FROM public.cctv_report_receipts WHERE id = p_receipt_id;
  IF v_receipt.id IS NULL THEN RETURN jsonb_build_object('receipt_id', p_receipt_id, 'found', false); END IF;
  IF NOT public.org_access_allowed(v_receipt.organization_id) THEN RAISE EXCEPTION 'CCTV report access denied'; END IF;
  v_recomputed := encode(digest(convert_to(v_receipt.payload::text, 'UTF8'), 'sha256'), 'hex');
  SELECT * INTO v_evidence FROM public.evidence_items WHERE id = v_receipt.evidence_item_id;
  RETURN jsonb_strip_nulls(jsonb_build_object(
    'receipt_id', v_receipt.id,
    'found', true,
    'issued_at', v_receipt.generated_at,
    'issued_by', v_receipt.generated_by,
    'observation_count', v_receipt.observation_count,
    'stored_sha256', v_receipt.sha256,
    'receipt_intact', v_recomputed = v_receipt.sha256,
    'presented_sha256', v_claimed,
    'presented_matches', CASE WHEN v_claimed IS NULL THEN NULL ELSE v_claimed = v_receipt.sha256 END,
    'evidence_sha256_at_issue', v_receipt.payload->'provenance'->'evidence'->>'sha256_hash',
    'evidence_sha256_now', v_evidence.sha256_hash,
    'evidence_integrity_now', v_evidence.metadata->'integrity'->>'state',
    'evidence_locked_at', v_evidence.locked_at,
    'review_consistency_at_issue', v_receipt.payload->'provenance'->>'review_consistency',
    'superseded_by', (SELECT r.id FROM public.cctv_report_receipts r WHERE r.evidence_item_id = v_receipt.evidence_item_id AND r.generated_at > v_receipt.generated_at ORDER BY r.generated_at ASC LIMIT 1)
  ));
END $function$;
COMMENT ON FUNCTION "public"."verify_cctv_report_receipt"(p_receipt_id uuid, p_sha256 text) IS 'Org-scoped: recomputes the stored receipt hash (receipt_intact), compares a presented hash, and reports the evidence integrity now against the hash sealed at issue, plus any later receipt that supersedes it.';
REVOKE ALL ON FUNCTION "public"."verify_cctv_report_receipt"(p_receipt_id uuid, p_sha256 text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."verify_cctv_report_receipt"(p_receipt_id uuid, p_sha256 text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."verify_cctv_report_receipt"(p_receipt_id uuid, p_sha256 text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."verify_cctv_report_receipt"(p_receipt_id uuid, p_sha256 text) TO "service_role";

