CREATE OR REPLACE FUNCTION "public"."wf_approve_job"(_job_id uuid, _stage wf_approval_stage, _decision wf_approval_decision, _comment text DEFAULT NULL::text)
 RETURNS wf_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  _uid uuid := (select auth.uid());
  _next public.wf_job_state;
  _job public.wf_jobs%rowtype;
begin
  if _uid is null then
    raise exception 'Not authenticated';
  end if;

  insert into public.wf_approvals (job_id, stage, decision, comment, decided_by)
  values (_job_id, _stage, _decision, _comment, _uid);

  if _decision = 'rejected' then
    _next := 'failed';
  elsif _stage = 'verify' then
    _next := 'verified';
  else
    _next := 'ratified';
  end if;

  select * into _job
  from public.wf_transition_job_state(
    _job_id,
    _next,
    concat('approval ', _stage::text, ':', _decision::text),
    'user'
  );

  return _job;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."wf_approve_job"(_job_id uuid, _stage wf_approval_stage, _decision wf_approval_decision, _comment text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."wf_approve_job"(_job_id uuid, _stage wf_approval_stage, _decision wf_approval_decision, _comment text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."wf_approve_job"(_job_id uuid, _stage wf_approval_stage, _decision wf_approval_decision, _comment text) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."wf_approve_job"(_job_id uuid, _stage wf_approval_stage, _decision wf_approval_decision, _comment text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."wf_approve_job"(_job_id uuid, _stage wf_approval_stage, _decision wf_approval_decision, _comment text) TO "service_role";

