CREATE OR REPLACE FUNCTION "public"."wf_return_artifact"(_job_id uuid, _run_id uuid, _kind wf_artifact_kind, _bucket_id text, _object_path text, _sha256 text DEFAULT NULL::text, _size_bytes bigint DEFAULT NULL::bigint, _lease_token text DEFAULT NULL::text)
 RETURNS wf_artifacts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _artifact public.wf_artifacts%rowtype;
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF _run_id IS NULL OR _lease_token IS NULL THEN
    RAISE EXCEPTION 'run_id and lease_token are required';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.wf_runs r
    WHERE r.id = _run_id
      AND r.job_id = _job_id
      AND r.status = 'picked_up'
      AND r.lease_token = _lease_token
      AND r.lease_expires_at > now()
  ) THEN
    RAISE EXCEPTION 'Run lease is missing, expired, or does not belong to job';
  END IF;

  INSERT INTO public.wf_artifacts (
    job_id, run_id, kind, bucket_id, object_path, sha256, size_bytes, created_by
  )
  VALUES (
    _job_id, _run_id, _kind, _bucket_id, _object_path, _sha256, _size_bytes, _uid
  )
  RETURNING * INTO _artifact;

  RETURN _artifact;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."wf_return_artifact"(_job_id uuid, _run_id uuid, _kind wf_artifact_kind, _bucket_id text, _object_path text, _sha256 text, _size_bytes bigint, _lease_token text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."wf_return_artifact"(_job_id uuid, _run_id uuid, _kind wf_artifact_kind, _bucket_id text, _object_path text, _sha256 text, _size_bytes bigint, _lease_token text) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."wf_return_artifact"(_job_id uuid, _run_id uuid, _kind wf_artifact_kind, _bucket_id text, _object_path text, _sha256 text, _size_bytes bigint, _lease_token text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."wf_return_artifact"(_job_id uuid, _run_id uuid, _kind wf_artifact_kind, _bucket_id text, _object_path text, _sha256 text, _size_bytes bigint, _lease_token text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."wf_return_artifact"(_job_id uuid, _run_id uuid, _kind wf_artifact_kind, _bucket_id text, _object_path text, _sha256 text, _size_bytes bigint, _lease_token text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."wf_service_pickup_run"(_job_id uuid, _runner_id text)
 RETURNS wf_runs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _job public.wf_jobs%rowtype;
  _run public.wf_runs%rowtype;
  _lease_token text := encode(extensions.gen_random_bytes(32), 'hex');
  _now timestamptz := now();
  _bob uuid := '00000000-0000-0000-0000-00000000b0b0';
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;
  IF _runner_id IS NULL OR btrim(_runner_id) = '' THEN
    RAISE EXCEPTION 'runner_id is required';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.user_profiles WHERE id = _bob) THEN
    RAISE EXCEPTION 'Bob system actor is not configured';
  END IF;

  SELECT * INTO _job FROM public.wf_jobs WHERE id = _job_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Job not found: %', _job_id; END IF;
  IF _job.state <> 'ratified' THEN
    RAISE EXCEPTION 'Job is not ratified for execution';
  END IF;

  UPDATE public.wf_runs
  SET status = 'failed', finished_at = _now, result_summary = jsonb_build_object('reason', 'lease expired')
  WHERE job_id = _job_id AND status = 'picked_up'
    AND lease_expires_at IS NOT NULL AND lease_expires_at <= _now;

  IF EXISTS (SELECT 1 FROM public.wf_runs WHERE job_id = _job_id AND status = 'picked_up' AND lease_token IS NOT NULL) THEN
    RAISE EXCEPTION 'Job already has an active worker lease';
  END IF;

  INSERT INTO public.wf_runs (job_id, runner_id, status, picked_up_at, lease_token, lease_expires_at, heartbeat_at)
  VALUES (_job_id, _runner_id, 'picked_up', _now, _lease_token, _now + interval '15 minutes', _now)
  RETURNING * INTO _run;

  UPDATE public.wf_jobs SET state = 'running', updated_at = _now WHERE id = _job_id;
  INSERT INTO public.wf_state_events (job_id, from_state, to_state, reason, actor_user_id, actor_type)
  VALUES (_job_id, 'ratified', 'running', concat('service runner pickup ', _runner_id), _bob, 'system');
  RETURN _run;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."wf_service_pickup_run"(_job_id uuid, _runner_id text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."wf_service_pickup_run"(_job_id uuid, _runner_id text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."wf_service_pickup_run"(_job_id uuid, _runner_id text) TO "service_role";

