CREATE OR REPLACE FUNCTION "public"."wf_transition_job_state"(_job_id uuid, _to_state wf_job_state, _reason text DEFAULT NULL::text, _actor_type wf_actor_type DEFAULT 'user'::wf_actor_type)
 RETURNS wf_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  _job public.wf_jobs%rowtype;
  _from_state public.wf_job_state;
  _uid uuid := (select auth.uid());
  _allowed boolean := false;
begin
  if _uid is null then
    raise exception 'Not authenticated';
  end if;

  select * into _job
  from public.wf_jobs
  where id = _job_id
  for update;

  if not found then
    raise exception 'Job not found: %', _job_id;
  end if;

  _from_state := _job.state;

  if _from_state = _to_state then
    raise exception 'No-op transition % -> % is not allowed', _from_state, _to_state;
  end if;

  _allowed :=
    ((_from_state = 'draft' and _to_state = 'verify_pending') and (_job.created_by = _uid or (select public.wf_has_role('operator'))))
    or ((_from_state = 'verify_pending' and _to_state = 'verified') and (select public.wf_has_role('verifier')))
    or ((_from_state = 'verified' and _to_state = 'ratify_pending') and ((select public.wf_has_role('operator')) or (select public.wf_has_role('verifier'))))
    or ((_from_state = 'ratify_pending' and _to_state = 'ratified') and (select public.wf_has_role('ratifier')))
    or ((_from_state = 'ratified' and _to_state = 'running') and ((select public.wf_has_role('runner')) or (select public.wf_has_role('operator'))))
    or ((_from_state = 'running' and _to_state = 'promoted') and (select public.wf_has_role('operator')) and exists (
      select 1 from public.wf_runs r where r.job_id = _job_id and r.status = 'succeeded'
    ))
    or (_to_state = 'failed' and (
      _job.created_by = _uid
      or (select public.wf_has_role('verifier'))
      or (select public.wf_has_role('ratifier'))
      or (select public.wf_has_role('operator'))
      or (select public.wf_has_role('runner'))
    ));

  if not _allowed then
    raise exception 'Illegal transition % -> % for user %', _from_state, _to_state, _uid;
  end if;

  update public.wf_jobs
  set
    state = _to_state,
    verified_at = case when _to_state = 'verified' then now() else verified_at end,
    ratified_at = case when _to_state = 'ratified' then now() else ratified_at end,
    promoted_at = case when _to_state = 'promoted' then now() else promoted_at end
  where id = _job_id
  returning * into _job;

  insert into public.wf_state_events (job_id, from_state, to_state, reason, actor_user_id, actor_type)
  values (_job_id, _from_state, _to_state, _reason, _uid, _actor_type);

  return _job;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."wf_transition_job_state"(_job_id uuid, _to_state wf_job_state, _reason text, _actor_type wf_actor_type) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."wf_transition_job_state"(_job_id uuid, _to_state wf_job_state, _reason text, _actor_type wf_actor_type) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."wf_transition_job_state"(_job_id uuid, _to_state wf_job_state, _reason text, _actor_type wf_actor_type) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."wf_transition_job_state"(_job_id uuid, _to_state wf_job_state, _reason text, _actor_type wf_actor_type) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."wf_transition_job_state"(_job_id uuid, _to_state wf_job_state, _reason text, _actor_type wf_actor_type) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."withdraw_nzta_access_attestation"(p_attestation_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_row public.nzta_access_attestations%rowtype;
BEGIN
  SELECT * INTO v_row FROM public.nzta_access_attestations WHERE id = p_attestation_id FOR UPDATE;
  IF auth.uid() IS NULL OR v_row.id IS NULL OR NOT public.is_admin_for_org(v_row.organization_id) THEN
    RAISE EXCEPTION 'Organisation administrator required' USING ERRCODE = '42501';
  END IF;
  IF v_row.withdrawn_at IS NOT NULL THEN RAISE EXCEPTION 'This record was already withdrawn'; END IF;
  IF length(btrim(coalesce(p_reason, ''))) < 5 THEN RAISE EXCEPTION 'A reason is required'; END IF;
  UPDATE public.nzta_access_attestations
  SET withdrawn_at = clock_timestamp(), withdrawn_by = auth.uid(), withdrawn_reason = btrim(p_reason)
  WHERE id = p_attestation_id;
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_row.organization_id, auth.uid(), 'nzta_access_attestation_withdrawn', 'nzta_access_attestations',
    p_attestation_id, jsonb_build_object('user_id', v_row.user_id, 'reason', btrim(p_reason)));
END;
$function$;
REVOKE ALL ON FUNCTION "public"."withdraw_nzta_access_attestation"(p_attestation_id uuid, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."withdraw_nzta_access_attestation"(p_attestation_id uuid, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."withdraw_nzta_access_attestation"(p_attestation_id uuid, p_reason text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."workshop_actor_org"(p_organization_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_home uuid;
begin
  if p_organization_id is null then raise exception 'organization_id is required'; end if;
  select up.organization_id into v_home from public.user_profiles up where up.id = v_actor and up.deactivated_at is null;
  if v_home is null then raise exception 'Active user required'; end if;
  if not public.is_admin_for_org(p_organization_id) then raise exception 'Workshop administrator access required'; end if;
  if not exists (select 1 from public.organization_modules m where m.organization_id = p_organization_id and m.module_key = 'workshop' and m.enabled) then
    raise exception 'The workshop module is not enabled for this organisation';
  end if;
  return v_actor;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."workshop_actor_org"(p_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."workshop_actor_org"(p_organization_id uuid) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."workshop_current_prices"(p_item_id uuid, OUT unit_cost numeric, OUT unit_price numeric, OUT unit_of_measure text, OUT item_name text)
 RETURNS record
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(pb.unit_cost, 0), coalesce(pb.unit_price, 0), pb.unit_of_measure, pb.name
  from public.finance_price_book pb where pb.item_id = p_item_id;
$function$;
REVOKE ALL ON FUNCTION "public"."workshop_current_prices"(p_item_id uuid, OUT unit_cost numeric, OUT unit_price numeric, OUT unit_of_measure text, OUT item_name text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."workshop_current_prices"(p_item_id uuid, OUT unit_cost numeric, OUT unit_price numeric, OUT unit_of_measure text, OUT item_name text) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."workshop_line_actor_role"(p_work_order workshop_work_orders)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
begin
  if v_actor is null then raise exception 'Active user required'; end if;
  if public.is_admin_for_org(p_work_order.organization_id) then
    perform public.workshop_actor_org(p_work_order.organization_id);
    return 'admin';
  end if;
  if p_work_order.assigned_user_id = v_actor
     and p_work_order.status in ('approved', 'in_progress')
     and exists (select 1 from public.user_profiles up where up.id = v_actor and up.deactivated_at is null)
     and exists (select 1 from public.organization_modules m where m.organization_id = p_work_order.organization_id and m.module_key = 'workshop' and m.enabled) then
    return 'worker';
  end if;
  raise exception 'Only a workshop administrator, or the assigned worker while the job is approved or in progress, can change these lines';
end;
$function$;
REVOKE ALL ON FUNCTION "public"."workshop_line_actor_role"(p_work_order workshop_work_orders) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."workshop_line_actor_role"(p_work_order workshop_work_orders) TO "postgres";

CREATE OR REPLACE VIEW "public"."canonical_person_public" AS
 SELECT id,
    canonical_key,
    display_name,
    normalized_name,
    review_state,
    status,
    homeless_status,
    created_at,
    updated_at
   FROM canonical_people;
COMMENT ON VIEW "public"."canonical_person_public" IS 'Platform-wide person identity (Tier 0): identity, review state, and the homeless status signal an officer must know before approaching. Deliberately excludes date_of_birth and homeless_notes (personal information; governed paths only). Definer view over canonical_people, which stays Bob-only at the table.';

CREATE OR REPLACE VIEW "public"."canonical_scv_public" AS
 SELECT id,
    plate_number,
    certificate_number,
    certificate_status,
    issued_date,
    expiry_date
   FROM canonical_scv;
COMMENT ON VIEW "public"."canonical_scv_public" IS 'Self-containment certificate status per plate (a public register). Definer view over canonical_scv, which stays Bob-only at the table.';

CREATE OR REPLACE VIEW "public"."canonical_vehicle_public" AS
 SELECT id,
    plate_number,
    make,
    model,
    year,
    colour,
    body_type,
    fuel_type,
    rego_status,
    rego_expiry,
    wof_status,
    wof_expiry,
    cof_status,
    cof_expiry,
    homeless_status,
    last_seen_at,
    created_at,
    updated_at,
    external_data_source_name,
    external_data_source_url,
    external_data_source_location,
    external_data_source_checked_at,
    details_updated_at,
    ( SELECT o.name
           FROM organizations o
          WHERE o.id = v.details_updated_by_org_id) AS details_updated_by_org_name
   FROM canonical_vehicles v;
COMMENT ON VIEW "public"."canonical_vehicle_public" IS 'Platform-wide Tier 0 plate attributes, credential-free source attribution and the organisation/time of the last human profile correction. Excludes owner identity, welfare notes, provider payload metadata and authorization references.';

CREATE OR REPLACE VIEW "public"."finance_price_book" WITH (security_invoker=true) AS
 SELECT item.id AS item_id,
    item.organization_id,
    item.sku,
    item.name,
    item.item_type,
    item.unit_of_measure,
    item.active,
    cost.unit_cost,
    cost.supplier_name,
    price.unit_price,
        CASE
            WHEN price.unit_price > 0::numeric THEN round((price.unit_price - COALESCE(cost.unit_cost, 0::numeric)) / price.unit_price * 100::numeric, 2)
            ELSE NULL::numeric
        END AS margin_pct,
    GREATEST(item.updated_at, COALESCE(cost.created_at, item.updated_at), COALESCE(price.created_at, item.updated_at)) AS updated_at
   FROM finance_item_catalog item
     LEFT JOIN LATERAL ( SELECT c.unit_cost,
            c.supplier_name,
            c.created_at
           FROM finance_item_cost_versions c
          WHERE c.item_id = item.id AND c.status = 'approved'::text AND c.effective_from <= CURRENT_DATE AND (c.effective_to IS NULL OR c.effective_to >= CURRENT_DATE)
          ORDER BY c.effective_from DESC, c.version DESC
         LIMIT 1) cost ON true
     LEFT JOIN LATERAL ( SELECT p.unit_price,
            p.created_at
           FROM finance_item_price_versions p
          WHERE p.item_id = item.id AND p.status = 'approved'::text AND p.effective_from <= CURRENT_DATE AND (p.effective_to IS NULL OR p.effective_to >= CURRENT_DATE)
          ORDER BY p.effective_from DESC, p.version DESC
         LIMIT 1) price ON true;
COMMENT ON VIEW "public"."finance_price_book" IS 'One row per price-book item with the current approved cost and sell price. Inherits RLS via security_invoker.';

CREATE OR REPLACE VIEW "public"."house_event_anchor_projection" WITH (security_invoker=true) AS
 SELECT 'location_events'::text AS source_table,
    e.id AS event_id,
    e.organization_id,
    e.module_key,
    e.event_type,
    e.occurred_at,
    e.checkpoint_id,
    e.client_site_id,
    e.zone_id,
    COALESCE(z.location_id, s.location_id) AS location_id,
        CASE
            WHEN e.checkpoint_id IS NOT NULL THEN 'checkpoint'::text
            WHEN e.client_site_id IS NOT NULL THEN 'site'::text
            WHEN e.zone_id IS NOT NULL THEN 'zone'::text
            WHEN COALESCE(z.location_id, s.location_id) IS NOT NULL THEN 'house'::text
            ELSE 'unresolved'::text
        END AS anchor_kind,
        CASE
            WHEN e.checkpoint_id IS NULL AND e.client_site_id IS NULL AND e.zone_id IS NULL THEN 'no_checkpoint_site_or_zone'::text
            WHEN COALESCE(z.location_id, s.location_id) IS NULL THEN 'facet_has_no_house_link'::text
            ELSE NULL::text
        END AS unresolved_reason
   FROM location_events e
     LEFT JOIN client_sites s ON s.id = e.client_site_id
     LEFT JOIN location_zones z ON z.id = e.zone_id
UNION ALL
 SELECT 'observations'::text AS source_table,
    o.id AS event_id,
    o.organization_id,
    o.module_key,
    'observation'::text AS event_type,
    o.observed_at AS occurred_at,
    NULL::uuid AS checkpoint_id,
    o.site_id AS client_site_id,
    o.zone_id,
    COALESCE(o.location_id, z.location_id, s.location_id) AS location_id,
        CASE
            WHEN o.site_id IS NOT NULL THEN 'site'::text
            WHEN o.zone_id IS NOT NULL THEN 'zone'::text
            WHEN COALESCE(o.location_id, z.location_id, s.location_id) IS NOT NULL THEN 'house'::text
            ELSE 'unresolved'::text
        END AS anchor_kind,
        CASE
            WHEN o.site_id IS NULL AND o.zone_id IS NULL AND o.location_id IS NULL THEN 'no_site_zone_or_house'::text
            WHEN COALESCE(o.location_id, z.location_id, s.location_id) IS NULL THEN 'facet_has_no_house_link'::text
            ELSE NULL::text
        END AS unresolved_reason
   FROM observations o
     LEFT JOIN client_sites s ON s.id = o.site_id
     LEFT JOIN location_zones z ON z.id = o.zone_id
UNION ALL
 SELECT 'noise_assessments'::text AS source_table,
    n.id AS event_id,
    n.organization_id,
    'noise_control'::text AS module_key,
    'noise_assessment'::text AS event_type,
    n.assessed_at AS occurred_at,
    NULL::uuid AS checkpoint_id,
    n.site_id AS client_site_id,
    NULL::uuid AS zone_id,
    n.location_id,
        CASE
            WHEN n.site_id IS NOT NULL THEN 'site'::text
            WHEN n.location_id IS NOT NULL THEN 'house'::text
            ELSE 'unresolved'::text
        END AS anchor_kind,
        CASE
            WHEN n.site_id IS NULL AND n.location_id IS NULL THEN 'no_site_or_house'::text
            WHEN n.location_id IS NULL THEN 'site_has_no_house_link'::text
            ELSE NULL::text
        END AS unresolved_reason
   FROM noise_assessments n
UNION ALL
 SELECT 'dispatch_jobs'::text AS source_table,
    d.id AS event_id,
    d.organization_id,
    d.module_key,
    d.job_type AS event_type,
    d.created_at AS occurred_at,
    NULL::uuid AS checkpoint_id,
    d.client_site_id,
    NULL::uuid AS zone_id,
    s.location_id,
        CASE
            WHEN d.client_site_id IS NOT NULL THEN 'site'::text
            WHEN s.location_id IS NOT NULL THEN 'house'::text
            ELSE 'unresolved'::text
        END AS anchor_kind,
        CASE
            WHEN d.client_site_id IS NULL AND s.location_id IS NULL THEN 'no_site_or_house'::text
            WHEN s.location_id IS NULL THEN 'site_has_no_house_link'::text
            ELSE NULL::text
        END AS unresolved_reason
   FROM dispatch_jobs d
     LEFT JOIN client_sites s ON s.id = d.client_site_id;
COMMENT ON VIEW "public"."house_event_anchor_projection" IS 'Read-only normalized event/place projection. Anchor precedence: checkpoint, Site, Zone, House fallback, unresolved. Does not replace immutable event context; supports issue #18 backfill and reconciliation.';

CREATE OR REPLACE VIEW "public"."investigations_summary" WITH (security_invoker=true) AS
 SELECT id,
    organization_id,
    investigation_reference,
    title,
    investigation_type,
    status,
    priority,
    legal_hold,
    lead_user_id,
    opened_at,
    resolved_at,
    closed_at
   FROM investigations i
  WHERE org_access_allowed(organization_id);
COMMENT ON VIEW "public"."investigations_summary" IS 'Org-visible investigation existence/status projection: excludes summary, resolution_notes and the event/link timeline (third-party PII, alleged-conduct narrative, Police liaison detail) which stay admin-or-assigned-lead only on the base tables.';

CREATE OR REPLACE VIEW "public"."location_visibility_for_viewer" WITH (security_invoker=true) AS
 SELECT sal.id AS sal_id,
    sal.site_id,
    sal.zone_id,
    sal.service_agreement_id,
    sal.status,
    COALESCE(sal.share_contract_price, sa.default_share_contract_price) AS share_contract_price,
    COALESCE(sal.share_actual_cost, sa.default_share_actual_cost) AS share_actual_cost,
    sa.provider_organization_id,
    sa.client_organization_id
   FROM service_agreement_locations sal
     JOIN service_agreements sa ON sa.id = sal.service_agreement_id
  WHERE sal.status = 'active'::text;
COMMENT ON VIEW "public"."location_visibility_for_viewer" IS 'Effective T2 finance visibility settings per active location contract. Resolves share_contract_price and share_actual_cost with agreement-level defaults as fallback. Queryable by site_id or zone_id. RLS inherits from service_agreement_locations (0261). Epic #185 E2.';

CREATE OR REPLACE VIEW "public"."module_context_contract" WITH (security_invoker=true) AS
 SELECT om.organization_id,
    om.module_key,
    om.enabled,
    rar.dominant_anchor_kind,
    rar.active_zone_id,
    rar.active_site_id,
    rar.active_location_id,
    rar.governing_jurisdiction_id,
    rar.governing_jurisdiction_name,
    rar.module_rule_set_id,
    rar.module_rule_set_name,
    rar.evidence_requirements,
    rar.approval_policy,
    rar.report_template_code,
    rar.jurisdiction_rule_set_id,
    rar.jurisdiction_rule_set_name,
    rar.jurisdiction_name,
    rar.jurisdiction_rules,
    rar.resolution_status,
    rar.effective_rules,
    rar.policy_status
   FROM organization_modules om
     LEFT JOIN LATERAL resolve_active_rules(om.organization_id, om.module_key, NULL::double precision, NULL::double precision, NULL::uuid, NULL::uuid, NULL::uuid, now()) rar(organization_id, module_key, enabled, dominant_anchor_kind, active_zone_id, active_site_id, active_location_id, governing_jurisdiction_id, governing_jurisdiction_name, module_rule_set_id, module_rule_set_name, evidence_requirements, approval_policy, report_template_code, jurisdiction_rule_set_id, jurisdiction_rule_set_name, jurisdiction_name, jurisdiction_rules, resolution_status, effective_rules, policy_status) ON rar.organization_id = om.organization_id AND rar.module_key = om.module_key
  ORDER BY om.organization_id, om.module_key;
COMMENT ON VIEW "public"."module_context_contract" IS 'App-facing module context contract: one read-only view returning the live effective rule, place anchor, and policy status for each enabled module. This is the UI contract that all screens should consume instead of re-deriving org-only policy.';

CREATE OR REPLACE VIEW "public"."module_rule_index_view" WITH (security_invoker=true) AS
 SELECT om.organization_id,
    om.module_key,
    om.enabled,
    mrs.id AS module_rule_set_id,
    mrs.name AS module_rule_set_name,
    mrs.evidence_requirements,
    mrs.approval_policy,
    mrs.report_template_code,
    jrs.id AS jurisdiction_rule_set_id,
    jrs.name AS jurisdiction_rule_set_name,
    jrs.jurisdiction_name,
    jrs.rules AS jurisdiction_rules,
    z.id AS zone_id,
    z.location_id,
    z.organization_id AS zone_organization_id,
    COALESCE(z.jurisdiction_rule_set_id, jrs.id) AS active_rule_set_id,
        CASE
            WHEN z.id IS NOT NULL THEN 'zone'::text
            WHEN cs.id IS NOT NULL THEN 'site'::text
            ELSE 'organization'::text
        END AS place_scope
   FROM organization_modules om
     LEFT JOIN module_rule_sets mrs ON mrs.organization_id = om.organization_id AND mrs.module_key = om.module_key
     LEFT JOIN jurisdiction_rule_sets jrs ON jrs.organization_id = om.organization_id AND jrs.module_key = om.module_key
     LEFT JOIN location_zones z ON z.organization_id = om.organization_id AND z.module_key = om.module_key
     LEFT JOIN client_sites cs ON cs.organization_id = om.organization_id AND cs.site_type IS NOT NULL
  ORDER BY om.organization_id, om.module_key, z.id;
COMMENT ON VIEW "public"."module_rule_index_view" IS 'Read-only lookup view for active module rule sets keyed by organization, module, and governing place context. This supports multi-jurisdiction service-provider rule resolution without hidden org assumptions.';

CREATE OR REPLACE VIEW "public"."organization_tree" WITH (security_invoker=true) AS
 WITH RECURSIVE tree AS (
         SELECT organizations.id,
            organizations.name,
            organizations.organization_type,
            organizations.parent_organization_id,
            0 AS depth,
            organizations.id AS root_id,
            organizations.name AS path
           FROM organizations
          WHERE organizations.parent_organization_id IS NULL
        UNION ALL
         SELECT o.id,
            o.name,
            o.organization_type,
            o.parent_organization_id,
            t.depth + 1,
            t.root_id,
            (t.path || ' \u203a '::text) || o.name
           FROM organizations o
             JOIN tree t ON o.parent_organization_id = t.id
        )
 SELECT id,
    name,
    organization_type,
    parent_organization_id,
    depth,
    root_id,
    path
   FROM tree;
COMMENT ON VIEW "public"."organization_tree" IS 'Recursive organisation hierarchy (id, parent, depth, root, path). Inherits RLS from organizations via security_invoker.';

CREATE OR REPLACE VIEW "public"."patrol_travel_km_summary" WITH (security_invoker=true) AS
 SELECT observations.organization_id,
    observations.officer_id,
    observations.zone_id,
    observations.site_id,
    date_trunc('month'::text, observations.observed_at) AS month,
    count(*) AS visit_count,
    sum(observations.distance_km) AS total_distance_km
   FROM observations
  WHERE observations.distance_km IS NOT NULL
  GROUP BY observations.organization_id, observations.officer_id, observations.zone_id, observations.site_id, (date_trunc('month'::text, observations.observed_at))
UNION ALL
 SELECT location_events.organization_id,
    location_events.observed_entity_id AS officer_id,
    location_events.zone_id,
    location_events.client_site_id AS site_id,
    date_trunc('month'::text, location_events.occurred_at) AS month,
    count(*) AS visit_count,
    sum(location_events.distance_km) AS total_distance_km
   FROM location_events
  WHERE location_events.distance_km IS NOT NULL AND location_events.observed_entity_type = 'staff'::text
  GROUP BY location_events.organization_id, location_events.observed_entity_id, location_events.zone_id, location_events.client_site_id, (date_trunc('month'::text, location_events.occurred_at));
COMMENT ON VIEW "public"."patrol_travel_km_summary" IS 'Real recorded travel km per officer/place/month, unioned from observations and location_events.distance_km. Read-only reporting aggregate for cost-of-service and vehicle-usage tracking - not part of the finance/invoicing write pipeline. Inherits RLS from observations and location_events via security_invoker.';

CREATE OR REPLACE VIEW "public"."person_permits_fieldwork" WITH (security_invoker=true) AS
 SELECT id,
    organization_id,
    client_organization_id,
    canonical_person_id,
    holder_name,
    permit_number,
    permit_type,
    applicant_type,
    company_name,
    contact_email,
    contact_phone,
    address_text,
    forest_areas,
    activities,
    hunting_season,
    date_from,
    date_to,
    firearm_confirm,
    firearm_licence_valid,
    chainsaw_safety_equipment,
    keys_issued,
    conditions,
    status,
    compliance_checked_at,
    compliance_source,
    vehicle_plates,
    validity_state
   FROM read_person_permits_fieldwork() read_person_permits_fieldwork(id, organization_id, client_organization_id, canonical_person_id, holder_name, permit_number, permit_type, applicant_type, company_name, contact_email, contact_phone, address_text, forest_areas, activities, hunting_season, date_from, date_to, firearm_confirm, firearm_licence_valid, chainsaw_safety_equipment, keys_issued, conditions, status, compliance_checked_at, compliance_source, vehicle_plates, validity_state);
COMMENT ON VIEW "public"."person_permits_fieldwork" IS 'Organization-scoped operational permit projection for authorized person-search users. Contact fields are null outside active operations roles. Never exposes firearm licence numbers or raw identity evidence.';

CREATE OR REPLACE VIEW "public"."v_service_agreement_readiness" WITH (security_invoker=true) AS
 WITH agreement_orgs AS (
         SELECT sa.client_organization_id AS org_id,
            count(*) AS agreements,
            min(sa.starts_on) AS first_agreement_start,
            max(sa.starts_on) AS latest_agreement_start
           FROM service_agreements sa
          GROUP BY sa.client_organization_id
        ), site_orgs AS (
         SELECT cs.client_organization_id AS org_id,
            count(*) AS sites,
            count(*) FILTER (WHERE cs.service_agreement_id IS NOT NULL) AS sites_linked
           FROM client_sites cs
          GROUP BY cs.client_organization_id
        ), linked_orgs AS (
         SELECT sa.client_organization_id AS org_id,
            count(DISTINCT sal.id) AS agreement_locations,
            count(DISTINCT sfc.id) AS financial_configs
           FROM service_agreements sa
             LEFT JOIN service_agreement_locations sal ON sal.service_agreement_id = sa.id
             LEFT JOIN site_financial_config sfc ON sfc.service_agreement_id = sa.id
          GROUP BY sa.client_organization_id
        )
 SELECT ao.org_id AS client_org_id,
    o.name AS client_org_name,
    ao.agreements,
    COALESCE(so.sites, 0::bigint) AS sites,
    COALESCE(so.sites_linked, 0::bigint) AS sites_linked,
    COALESCE(lo.agreement_locations, 0::bigint) AS agreement_locations,
    COALESCE(lo.financial_configs, 0::bigint) AS financial_configs,
    ao.first_agreement_start,
    ao.latest_agreement_start,
        CASE
            WHEN COALESCE(so.sites, 0::bigint) = 0 THEN 'needs_site_onboarding'::text
            WHEN COALESCE(so.sites_linked, 0::bigint) = 0 THEN 'needs_site_linking'::text
            WHEN COALESCE(lo.agreement_locations, 0::bigint) = 0 THEN 'needs_location_linking'::text
            WHEN COALESCE(lo.financial_configs, 0::bigint) = 0 THEN 'needs_financial_config'::text
            ELSE 'linked'::text
        END AS readiness_status
   FROM agreement_orgs ao
     LEFT JOIN site_orgs so ON so.org_id = ao.org_id
     LEFT JOIN linked_orgs lo ON lo.org_id = ao.org_id
     LEFT JOIN organizations o ON o.id = ao.org_id;
COMMENT ON VIEW "public"."v_service_agreement_readiness" IS 'Per-agreement readiness projection over service_agreements, service_agreement_locations, client_sites and site_financial_config. Inherits RLS from those base tables via security_invoker.';

CREATE OR REPLACE VIEW "public"."workshop_work_order_summary" WITH (security_invoker=true) AS
 SELECT wo.id,
    wo.organization_id,
    wo.order_number,
    wo.kind,
    wo.status,
    wo.title,
    wo.description,
    wo.client_organization_id,
    co.name AS client_name,
    wo.service_agreement_id,
    wo.client_site_id,
    cs.name AS site_name,
    wo.asset_id,
    a.name AS asset_name,
    wo.inventory_location_id,
    il.name AS stock_location_name,
    wo.bom_template_id,
    t.name AS template_name,
    wo.assigned_user_id,
    up.display_name AS assigned_name,
    wo.scheduled_for,
    wo.started_at,
    wo.completed_at,
    wo.cancelled_at,
    wo.completion_note,
    wo.created_at,
    wo.updated_at,
    COALESCE(l.line_count, 0::bigint) AS line_count,
    COALESCE(l.charge_total, 0::numeric) AS charge_total,
    COALESCE(l.cost_total, 0::numeric) AS cost_total,
    COALESCE(l.uninvoiced_total, 0::numeric) AS uninvoiced_total,
    wo.zone_id,
    z.name AS zone_name,
    wo.work_subject_code_id,
    subject.code AS work_subject_code,
    subject.name AS work_subject_name,
    wo.work_activity_code_id,
    activity.code AS work_activity_code,
    activity.name AS work_activity_name
   FROM workshop_work_orders wo
     LEFT JOIN organizations co ON co.id = wo.client_organization_id
     LEFT JOIN client_sites cs ON cs.id = wo.client_site_id
     LEFT JOIN location_zones z ON z.id = wo.zone_id
     LEFT JOIN assets a ON a.id = wo.asset_id
     LEFT JOIN finance_inventory_locations il ON il.id = wo.inventory_location_id
     LEFT JOIN workshop_bom_templates t ON t.id = wo.bom_template_id
     LEFT JOIN user_profiles up ON up.id = wo.assigned_user_id
     LEFT JOIN reference_codes subject ON subject.id = wo.work_subject_code_id
     LEFT JOIN reference_codes activity ON activity.id = wo.work_activity_code_id
     LEFT JOIN LATERAL ( SELECT count(*) AS line_count,
            sum(line.line_total) AS charge_total,
            sum(round(line.quantity * line.unit_cost, 2)) AS cost_total,
            sum(line.line_total) FILTER (WHERE line.invoice_line_item_id IS NULL) AS uninvoiced_total
           FROM workshop_work_order_lines line
          WHERE line.work_order_id = wo.id) l ON true;
COMMENT ON VIEW "public"."workshop_work_order_summary" IS 'One row per work order with catalog-backed subject/activity names and line totals resolved. Inherits RLS via security_invoker.';

CREATE OR REPLACE VIEW "public"."house_event_anchor_reconciliation" WITH (security_invoker=true) AS
 SELECT p.source_table,
    p.event_id,
    p.organization_id,
    p.module_key,
    p.event_type,
    p.occurred_at,
    p.checkpoint_id,
    p.client_site_id,
    p.zone_id,
    p.location_id,
    p.anchor_kind,
    p.unresolved_reason,
        CASE
            WHEN p.source_table <> 'location_events'::text OR p.checkpoint_id IS NULL THEN 'not_applicable'::text
            WHEN cp.id IS NULL THEN 'invalid_missing_checkpoint'::text
            WHEN cp.organization_id IS DISTINCT FROM p.organization_id THEN 'invalid_organization'::text
            WHEN cp.client_site_id IS NOT NULL AND p.client_site_id = cp.client_site_id AND p.zone_id IS NULL THEN 'valid'::text
            WHEN cp.zone_id IS NOT NULL AND p.zone_id = cp.zone_id AND p.client_site_id IS NULL THEN 'valid'::text
            ELSE 'invalid_facet_mismatch'::text
        END AS checkpoint_consistency,
        CASE
            WHEN p.source_table = 'location_events'::text AND p.checkpoint_id IS NOT NULL AND (cp.id IS NULL OR cp.organization_id IS DISTINCT FROM p.organization_id OR cp.client_site_id IS NOT NULL AND (p.client_site_id IS DISTINCT FROM cp.client_site_id OR p.zone_id IS NOT NULL) OR cp.zone_id IS NOT NULL AND (p.zone_id IS DISTINCT FROM cp.zone_id OR p.client_site_id IS NOT NULL)) THEN 'checkpoint_facet_mismatch'::text
            ELSE p.unresolved_reason
        END AS reconciliation_reason
   FROM house_event_anchor_projection p
     LEFT JOIN location_events e ON p.source_table = 'location_events'::text AND e.id = p.event_id
     LEFT JOIN patrol_checkpoints cp ON cp.id = e.checkpoint_id;
COMMENT ON VIEW "public"."house_event_anchor_reconciliation" IS 'Read-only event anchor quality overlay. Adds checkpoint consistency and explicit reconciliation reasons; never rewrites historical events.';

CREATE OR REPLACE VIEW "public"."module_event_place_matrix" WITH (security_invoker=true) AS
 WITH module_catalog AS (
         SELECT om.organization_id,
            om.module_key,
            om.enabled,
            ( SELECT mrs.name
                   FROM module_rule_sets mrs
                  WHERE mrs.organization_id = om.organization_id AND mrs.module_key = om.module_key
                  ORDER BY mrs.created_at DESC
                 LIMIT 1) AS rule_set_name,
            ( SELECT jrs.name
                   FROM jurisdiction_rule_sets jrs
                  WHERE jrs.organization_id = om.organization_id AND jrs.module_key = om.module_key
                  ORDER BY jrs.created_at DESC
                 LIMIT 1) AS jurisdiction_rule_set_name
           FROM organization_modules om
        ), anchor_counts AS (
         SELECT p.organization_id,
            p.module_key,
            p.anchor_kind,
            count(*) AS event_count
           FROM house_event_anchor_projection p
          WHERE p.module_key IS NOT NULL
          GROUP BY p.organization_id, p.module_key, p.anchor_kind
        ), module_anchor_summary AS (
         SELECT anchor_counts.organization_id,
            anchor_counts.module_key,
            anchor_counts.anchor_kind,
            max(anchor_counts.event_count) AS event_count
           FROM anchor_counts
          GROUP BY anchor_counts.organization_id, anchor_counts.module_key, anchor_counts.anchor_kind
        )
 SELECT organization_id,
    module_key,
    enabled,
    rule_set_name,
    jurisdiction_rule_set_name,
        CASE
            WHEN module_key IS NULL THEN 'unsupported'::text
            WHEN (EXISTS ( SELECT 1
               FROM house_event_anchor_projection p
              WHERE p.organization_id = mc.organization_id AND p.module_key = mc.module_key AND p.anchor_kind = 'checkpoint'::text)) THEN 'checkpoint'::text
            WHEN (EXISTS ( SELECT 1
               FROM house_event_anchor_projection p
              WHERE p.organization_id = mc.organization_id AND p.module_key = mc.module_key AND p.anchor_kind = 'site'::text)) THEN 'site'::text
            WHEN (EXISTS ( SELECT 1
               FROM house_event_anchor_projection p
              WHERE p.organization_id = mc.organization_id AND p.module_key = mc.module_key AND p.anchor_kind = 'zone'::text)) THEN 'zone'::text
            WHEN (EXISTS ( SELECT 1
               FROM house_event_anchor_projection p
              WHERE p.organization_id = mc.organization_id AND p.module_key = mc.module_key AND p.anchor_kind = 'house'::text)) THEN 'house'::text
            ELSE 'unresolved'::text
        END AS dominant_anchor_kind,
    COALESCE(( SELECT sum(mas.event_count) AS sum
           FROM module_anchor_summary mas
          WHERE mas.organization_id = mc.organization_id AND mas.module_key = mc.module_key), 0::numeric) AS total_event_count,
    COALESCE(( SELECT sum(
                CASE
                    WHEN mas.anchor_kind = 'unresolved'::text THEN mas.event_count
                    ELSE 0::bigint
                END) AS sum
           FROM module_anchor_summary mas
          WHERE mas.organization_id = mc.organization_id AND mas.module_key = mc.module_key), 0::numeric) AS unresolved_event_count,
    COALESCE(( SELECT sum(
                CASE
                    WHEN mas.anchor_kind = 'checkpoint'::text THEN mas.event_count
                    ELSE 0::bigint
                END) AS sum
           FROM module_anchor_summary mas
          WHERE mas.organization_id = mc.organization_id AND mas.module_key = mc.module_key), 0::numeric) AS checkpoint_event_count,
    COALESCE(( SELECT sum(
                CASE
                    WHEN mas.anchor_kind = 'site'::text THEN mas.event_count
                    ELSE 0::bigint
                END) AS sum
           FROM module_anchor_summary mas
          WHERE mas.organization_id = mc.organization_id AND mas.module_key = mc.module_key), 0::numeric) AS site_event_count,
    COALESCE(( SELECT sum(
                CASE
                    WHEN mas.anchor_kind = 'zone'::text THEN mas.event_count
                    ELSE 0::bigint
                END) AS sum
           FROM module_anchor_summary mas
          WHERE mas.organization_id = mc.organization_id AND mas.module_key = mc.module_key), 0::numeric) AS zone_event_count
   FROM module_catalog mc
  ORDER BY organization_id, module_key;
COMMENT ON VIEW "public"."module_event_place_matrix" IS 'Read-only module rule and place-anchor matrix for enterprise reconciliation. Classifies current event coverage by module and place anchor precedence without mutating history.';

CREATE OR REPLACE VIEW "public"."effective_rule_resolution_view" WITH (security_invoker=true) AS
 WITH latest_module_rules AS (
         SELECT DISTINCT ON (mrs.organization_id, mrs.module_key) mrs.organization_id,
            mrs.module_key,
            mrs.id AS module_rule_set_id,
            mrs.name AS module_rule_set_name,
            mrs.evidence_requirements,
            mrs.approval_policy,
            mrs.report_template_code
           FROM module_rule_sets mrs
          ORDER BY mrs.organization_id, mrs.module_key, mrs.created_at DESC
        ), latest_jurisdiction_rules AS (
         SELECT DISTINCT ON (jrs.organization_id, jrs.module_key) jrs.organization_id,
            jrs.module_key,
            jrs.id AS jurisdiction_rule_set_id,
            jrs.name AS jurisdiction_rule_set_name,
            jrs.jurisdiction_name,
            jrs.rules AS jurisdiction_rules
           FROM jurisdiction_rule_sets jrs
          ORDER BY jrs.organization_id, jrs.module_key, jrs.created_at DESC
        )
 SELECT om.organization_id,
    om.module_key,
    om.enabled,
    mepm.dominant_anchor_kind,
    mepm.total_event_count,
    mepm.unresolved_event_count,
    lmr.module_rule_set_id,
    lmr.module_rule_set_name,
    lmr.evidence_requirements,
    lmr.approval_policy,
    lmr.report_template_code,
    ljr.jurisdiction_rule_set_id,
    ljr.jurisdiction_rule_set_name,
    ljr.jurisdiction_name,
    ljr.jurisdiction_rules,
        CASE
            WHEN om.enabled = false THEN 'disabled'::text
            WHEN mepm.unresolved_event_count > 0::numeric THEN 'needs_reconciliation'::text
            WHEN lmr.module_rule_set_id IS NULL THEN 'missing_module_rule_set'::text
            WHEN ljr.jurisdiction_rule_set_id IS NULL THEN 'missing_jurisdiction_rule_set'::text
            ELSE 'effective_rules_ready'::text
        END AS effective_policy_status
   FROM organization_modules om
     LEFT JOIN latest_module_rules lmr ON lmr.organization_id = om.organization_id AND lmr.module_key = om.module_key
     LEFT JOIN latest_jurisdiction_rules ljr ON ljr.organization_id = om.organization_id AND ljr.module_key = om.module_key
     LEFT JOIN module_event_place_matrix mepm ON mepm.organization_id = om.organization_id AND mepm.module_key = om.module_key
  ORDER BY om.organization_id, om.module_key;
COMMENT ON VIEW "public"."effective_rule_resolution_view" IS 'Read-only effective rule resolution summary for multi-jurisdiction providers: geofence + module + jurisdiction + agreement context, without mutating historical events.';

CREATE OR REPLACE VIEW "public"."module_place_policy_summary" WITH (security_invoker=true) AS
 WITH latest_module_rules AS (
         SELECT DISTINCT ON (mrs.organization_id, mrs.module_key) mrs.organization_id,
            mrs.module_key,
            mrs.id AS module_rule_set_id,
            mrs.name AS module_rule_set_name,
            mrs.evidence_requirements,
            mrs.approval_policy,
            mrs.report_template_code,
            mrs.created_at
           FROM module_rule_sets mrs
          ORDER BY mrs.organization_id, mrs.module_key, mrs.created_at DESC
        ), latest_jurisdiction_rules AS (
         SELECT DISTINCT ON (jrs.organization_id, jrs.module_key) jrs.organization_id,
            jrs.module_key,
            jrs.id AS jurisdiction_rule_set_id,
            jrs.name AS jurisdiction_rule_set_name,
            jrs.jurisdiction_name,
            jrs.rules AS jurisdiction_rules,
            jrs.created_at
           FROM jurisdiction_rule_sets jrs
          ORDER BY jrs.organization_id, jrs.module_key, jrs.created_at DESC
        )
 SELECT om.organization_id,
    om.module_key,
    om.enabled,
    lmr.module_rule_set_id,
    lmr.module_rule_set_name,
    lmr.evidence_requirements,
    lmr.approval_policy,
    lmr.report_template_code,
    ljr.jurisdiction_rule_set_id,
    ljr.jurisdiction_rule_set_name,
    ljr.jurisdiction_name,
    ljr.jurisdiction_rules,
    mepm.dominant_anchor_kind,
    mepm.total_event_count,
    mepm.unresolved_event_count,
    mepm.checkpoint_event_count,
    mepm.site_event_count,
    mepm.zone_event_count,
        CASE
            WHEN om.enabled = false THEN 'disabled'::text
            WHEN mepm.unresolved_event_count > 0::numeric THEN 'needs_reconciliation'::text
            WHEN mepm.dominant_anchor_kind IS NULL THEN 'no_place_coverage'::text
            ELSE 'ready'::text
        END AS policy_status
   FROM organization_modules om
     LEFT JOIN latest_module_rules lmr ON lmr.organization_id = om.organization_id AND lmr.module_key = om.module_key
     LEFT JOIN latest_jurisdiction_rules ljr ON ljr.organization_id = om.organization_id AND ljr.module_key = om.module_key
     LEFT JOIN module_event_place_matrix mepm ON mepm.organization_id = om.organization_id AND mepm.module_key = om.module_key
  ORDER BY om.organization_id, om.module_key;
COMMENT ON VIEW "public"."module_place_policy_summary" IS 'Read-only module policy summary combining feature enablement, module rules, jurisdiction rules, and current place anchor coverage for reconciliation and geofence policy design.';

